    'msDS-AllowedToActOnBehalfOfOtherIdentity' = [GUID]'3f78c3e5-f79a-46bd-a0b8-9d18116ddc79'
    'gPLink'                         = [GUID]'f30e3bbe-9ff0-11d1-b603-0000f80367c1'
