    @{ SID = 'S-1-5-1';     Name = 'NT AUTHORITY\Dialup' }
    @{ SID = 'S-1-5-2';     Name = 'NT AUTHORITY\Network';        Short = 'Network' }
    @{ SID = 'S-1-5-3';     Name = 'NT AUTHORITY\Batch' }
