# =============================================================================
# Get-ExceptionErrorInfo
# =============================================================================
function Get-ExceptionErrorInfo {
    <#
    .SYNOPSIS
        Extracts structured error information from an exception.

    .DESCRIPTION
        Analyzes an exception and returns structured error information including:
        - Error code/HRESULT
        - Human-readable message
        - Category (AccessDenied, Network, RPC, etc.)
        - Whether the error is retryable
        - Whether it's an access denied error

    .PARAMETER Exception
        The exception to analyze.

    .PARAMETER Context
        Optional context string for the error message (e.g., "SMB", "WMI", "LDAP").

    .PARAMETER IncludeOriginalMessage
        Include the original exception message in unknown errors.

    .EXAMPLE
        try {
            Get-Item "\\server\share" -ErrorAction Stop
        } catch {
            $errorInfo = Get-ExceptionErrorInfo -Exception $_.Exception -Context "SMB"
            if ($errorInfo.IsAccessDenied) {
                Write-Host "Access denied"
            } elseif ($errorInfo.IsRetryable) {
                Write-Host "Network error, will retry"
            }
        }
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [System.Exception]$Exception,

        [Parameter(Mandatory=$false)]
        [string]$Context = "Operation",

        [Parameter(Mandatory=$false)]
        [switch]$IncludeOriginalMessage
    )

    $result = [PSCustomObject]@{
        HResult        = $null
        Win32Code      = $null
        Name           = $null
        Message        = $null
        Category       = 'Unknown'
        IsError        = $true
        IsRetryable    = $false
        IsAccessDenied = $false
        IsNotFound     = $false
        Context        = $Context
        OriginalMessage = $Exception.Message
    }

    # Get HRESULT from exception
    $hresult = $Exception.HResult

    # Note: HResult 0 is valid (SUCCESS), so check for $null explicitly
    if ($null -ne $hresult -and $hresult -ne 0) {
        $result.HResult = $hresult
        $result.Win32Code = $hresult -band 0xFFFF

        # Try HRESULT lookup
        $errorInfo = ConvertFrom-HResult -HResult $hresult

        if ($errorInfo.Name -notmatch '^UNKNOWN') {
            $result.Name = $errorInfo.Name
            $result.Message = $errorInfo.Message
            $result.Category = $errorInfo.Category
            $result.IsError = $errorInfo.IsError
            $result.IsRetryable = $errorInfo.IsRetryable
            $result.IsAccessDenied = $errorInfo.IsAccessDenied
            $result.IsNotFound = $errorInfo.IsNotFound
            return $result
        }
    }

    # Check for specific exception types
    if ($Exception -is [System.UnauthorizedAccessException]) {
        $result.Name = 'UnauthorizedAccessException'
        $result.Message = 'Access denied'
        $result.Category = 'AccessDenied'
        $result.IsAccessDenied = $true
        return $result
    }

    if ($Exception -is [System.Net.Sockets.SocketException]) {
        $socketCode = $Exception.SocketErrorCode
        $result.Win32Code = [int]$socketCode
        $result.Name = "SocketException_$socketCode"
        $result.Message = "Network error: $($Exception.Message)"
        $result.Category = 'Network'
        $result.IsRetryable = $true
        return $result
    }

    if ($Exception -is [System.TimeoutException]) {
        $result.Name = 'TimeoutException'
        $result.Message = 'Operation timed out'
        $result.Category = 'Timeout'
        $result.IsRetryable = $true
        return $result
    }

    # Check for SSL/TLS AuthenticationException (from SslStream.AuthenticateAsClient)
    if ($Exception -is [System.Security.Authentication.AuthenticationException]) {
        # Get the deepest error message for classification
        $sslMsg = if ($Exception.InnerException) { $Exception.InnerException.Message } else { $Exception.Message }
        $result.OriginalMessage = $sslMsg

        # Classify by error message patterns (HResults are not differentiated enough for SSL)
        if ($sslMsg -match 'certificate|trust|validation|verify|chain|revoked|expired') {
            $result.Name = 'SSLCertificateError'
            $result.Message = "SSL certificate validation failed: $sslMsg"
            $result.Category = 'SSLCertificate'
        }
        elseif ($sslMsg -match 'closed|reset|aborted|refused|terminated') {
            $result.Name = 'SSLConnectionClosed'
            $result.Message = "Server closed SSL connection - may not support LDAPS or TLS version mismatch"
            $result.Category = 'SSLConnection'
        }
        elseif ($sslMsg -match 'protocol|version|handshake|TLS|SSL') {
            $result.Name = 'SSLProtocolError'
            $result.Message = "TLS/SSL protocol error - server may require specific TLS version"
            $result.Category = 'SSLProtocol'
        }
        elseif ($sslMsg -match 'timeout|timed out') {
            $result.Name = 'SSLTimeout'
            $result.Message = 'SSL handshake timed out'
            $result.Category = 'Timeout'
            $result.IsRetryable = $true
        }
        else {
            $result.Name = 'SSLError'
            $result.Message = "SSL/TLS handshake failed: $sslMsg"
            $result.Category = 'SSLConnection'
        }
        return $result
    }

    # Check for System.DirectoryServices.Protocols.LdapException (adPEAS primary LDAP client)
    if ($Exception.GetType().FullName -eq 'System.DirectoryServices.Protocols.LdapException') {
        $ldapErrorCode = $Exception.ErrorCode
        $ldapInfo = ConvertFrom-LDAPError -ErrorCode $ldapErrorCode
        $result.Win32Code = $ldapErrorCode
        $result.Name = $ldapInfo.Name
        $result.Message = $ldapInfo.Message
        $result.Category = $ldapInfo.Category
        $result.IsError = $ldapInfo.IsError
        $result.IsRetryable = $ldapInfo.IsRetryable
        $result.IsAccessDenied = $ldapInfo.IsAccessDenied
        $result.IsNotFound = $ldapInfo.IsNotFound
        return $result
    }

    # Fallback: Unknown error
    if ($IncludeOriginalMessage -or -not $hresult) {
        $result.Message = "$Context error: $($Exception.Message)"
    } else {
        $result.Message = "$Context error (0x{0:X8})" -f $hresult
    }

    return $result
}


# =============================================================================
# Test-ErrorRetryable
# =============================================================================
function Test-ErrorRetryable {
    <#
    .SYNOPSIS
        Quick check if an exception represents a retryable error.

    .PARAMETER Exception
        The exception to check.

    .EXAMPLE
        catch {
            if (Test-ErrorRetryable -Exception $_.Exception) {
                Start-Sleep -Seconds 2
                # Retry operation
            }
        }
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [System.Exception]$Exception
    )

    $errorInfo = Get-ExceptionErrorInfo -Exception $Exception
    return $errorInfo.IsRetryable
}


# =============================================================================
# Test-ErrorAccessDenied
# =============================================================================
function Test-ErrorAccessDenied {
    <#
    .SYNOPSIS
        Quick check if an exception represents an access denied error.

    .PARAMETER Exception
        The exception to check.

    .EXAMPLE
        catch {
            if (Test-ErrorAccessDenied -Exception $_.Exception) {
                Write-Warning "Insufficient permissions"
            }
        }
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [System.Exception]$Exception
    )

    $errorInfo = Get-ExceptionErrorInfo -Exception $Exception
    return $errorInfo.IsAccessDenied
}


# =============================================================================
# Test-LDAPErrorNotFound
# =============================================================================
function Test-LDAPErrorNotFound {
    <#
    .SYNOPSIS
        Quick check if an exception represents LDAP_NO_SUCH_OBJECT error.

    .DESCRIPTION
        Checks if the exception is an LDAP "object not found" error (0x80072030).
        This is an expected case in LDAP searches when the SearchBase doesn't exist,
        and should typically be handled by returning an empty result rather than throwing.

        Checks multiple sources for the error code:
        - Exception.HResult
        - Exception.InnerException.HResult
        - DirectoryServicesCOMException.ErrorCode

    .PARAMETER Exception
        The exception to check.

    .EXAMPLE
        catch {
            if (Test-LDAPErrorNotFound -Exception $_.Exception) {
                # SearchBase doesn't exist - return empty result
                return @()
            }
            # Real error - rethrow
            throw
        }

    .NOTES
        LDAP_NO_SUCH_OBJECT (error code 32) is returned as HRESULT 0x80072030
        where 0x8007 is the FACILITY_WIN32 prefix and 0x2030 is 32 in decimal
        with an offset (0x2000 base for LDAP errors).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [System.Exception]$Exception
    )

    # LDAP_NO_SUCH_OBJECT = 0x80072030
    $LDAP_NO_SUCH_OBJECT = [int]0x80072030

    # Method 1: Check HResult directly (most common)
    if ($Exception.HResult -eq $LDAP_NO_SUCH_OBJECT) {
        return $true
    }

    # Method 2: Check InnerException HResult
    if ($Exception.InnerException -and $Exception.InnerException.HResult -eq $LDAP_NO_SUCH_OBJECT) {
        return $true
    }

    # Method 3: Check DirectoryServicesCOMException.ErrorCode
    if ($Exception -is [System.DirectoryServices.DirectoryServicesCOMException] -and
        $Exception.ErrorCode -eq $LDAP_NO_SUCH_OBJECT) {
        return $true
    }

    # Method 4: Check low 16 bits for LDAP code (0x2030 = 8240 decimal)
    # This catches cases where the full HRESULT might differ slightly
    if (($Exception.HResult -band 0xFFFF) -eq 0x2030) {
        return $true
    }

    return $false
}


# =============================================================================
# Resolve-LDAPWriteError
# =============================================================================
function Resolve-LDAPWriteError {
    <#
    .SYNOPSIS
        Decodes an exception from an LDAP write operation into a tester-actionable message.

    .DESCRIPTION
        Directory write operations (AddRequest/ModifyRequest/DeleteRequest) via
        $Script:LdapConnection.SendRequest() throw a DirectoryOperationException on
        failure. PowerShell wraps that in a MethodInvocationException, so the raw
        error a user sees is the generic ".NET" message (e.g. "The server cannot
        handle directory requests.") with no LDAP ResultCode and no AD sub-error.

        This function unwraps the inner exception chain, extracts the LDAP ResultCode
        and the server-side ErrorMessage, decodes the AD extended sub-error (the
        8-hex-digit prefix, e.g. 0000216D = MachineAccountQuota exceeded), and returns
        a structured object plus a formatted, actionable hint. It also degrades
        gracefully when the failure was re-thrown as a plain string message.

    .PARAMETER Exception
        The exception to decode (typically $_.Exception from a catch block).

    .PARAMETER Operation
        Short description of the attempted operation, used in the formatted output
        (e.g. "create computer 'BadPC$'"). On an access-rights rejection it also
        selects the "Required rights" line from $Script:LDAPWriteOperationHints,
        so keep the wording aligned with the patterns defined there.

    .EXAMPLE
        catch {
            $info = Resolve-LDAPWriteError -Exception $_.Exception -Operation "create computer '$Name'"
            Write-Error "Failed to $($info.Operation).`n  $($info.Formatted)"
        }

    .NOTES
        Author: Alexander Sturz (@_61106960_)
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [System.Exception]$Exception,

        [Parameter(Mandatory=$false)]
        [string]$Operation = 'LDAP write operation'
    )

    # Walk the InnerException chain to find the underlying directory exception.
    # PowerShell wraps .NET method exceptions in a MethodInvocationException, so the
    # DirectoryOperationException/LdapException is usually one or more levels down.
    $dirEx = $null
    $ldapEx = $null
    $messageChain = New-Object System.Collections.Generic.List[string]
    $cursor = $Exception
    $depth = 0
    while ($cursor -and $depth -lt 10) {
        if ($cursor.Message) { $messageChain.Add($cursor.Message) }
        $typeName = $cursor.GetType().FullName
        if (-not $dirEx -and $typeName -eq 'System.DirectoryServices.Protocols.DirectoryOperationException') {
            $dirEx = $cursor
        }
        if (-not $ldapEx -and $typeName -eq 'System.DirectoryServices.Protocols.LdapException') {
            $ldapEx = $cursor
        }
        $cursor = $cursor.InnerException
        $depth++
    }

    $resultCode = $null
    $resultName = $null
    $serverMessage = $null

    if ($dirEx -and $dirEx.Response) {
        $resultCode = [int]$dirEx.Response.ResultCode
        $resultName = [string]$dirEx.Response.ResultCode
        $serverMessage = $dirEx.Response.ErrorMessage
    }
    elseif ($ldapEx) {
        $resultCode = [int]$ldapEx.ErrorCode
        $resultName = (ConvertFrom-LDAPError -ErrorCode $resultCode).Name
        $serverMessage = $ldapEx.ServerErrorMessage
    }

    # Text to scan for the AD extended sub-error: prefer the server ErrorMessage,
    # otherwise the concatenated exception-chain messages (covers re-thrown strings).
    $scanText = $serverMessage
    if (-not $scanText) { $scanText = ($messageChain -join ' ') }

    # If no ResultCode was found via exception type, try to recover it from the
    # message text (e.g. a re-thrown "... failed: UnwillingToPerform - ..." string).
    if ($null -eq $resultCode -and $scanText) {
        $resultNameMap = @{
            'UnwillingToPerform'       = 53
            'InsufficientAccessRights' = 50
            'ConstraintViolation'      = 19
            'EntryAlreadyExists'       = 68
            'NoSuchObject'             = 32
            'StrongAuthRequired'       = 8
        }
        foreach ($rn in $resultNameMap.Keys) {
            if ($scanText -match $rn) {
                $resultCode = $resultNameMap[$rn]
                $resultName = $rn
                break
            }
        }
    }

    # Parse the AD extended sub-error (8-hex-digit code). Anchored form is the
    # canonical AD layout; the loose 0000xxxx form catches it embedded in free text.
    $extCode = $null
    $extHex = $null
    $extName = $null
    $extHint = $null
    if ($scanText) {
        if ($scanText -match '(^|[^0-9A-Fa-f])([0-9A-Fa-f]{8})\s*:') {
            $extHex = $matches[2].ToUpper()
        }
        elseif ($scanText -match '\b(0000[0-9A-Fa-f]{4})\b') {
            $extHex = $matches[1].ToUpper()
        }
        if ($extHex) {
            $extCode = [Convert]::ToInt32($extHex, 16)
            $extInfo = $Script:ADExtendedErrorCodes[$extCode]
            if ($extInfo) {
                $extName = $extInfo.Name
                $extHint = $extInfo.Hint
            }
        }
    }

    # Choose the most specific hint available: sub-error first, then ResultCode.
    $hint = $extHint
    if (-not $hint -and $null -ne $resultCode -and $Script:LDAPWriteResultHints.ContainsKey($resultCode)) {
        $hint = $Script:LDAPWriteResultHints[$resultCode]
    }

    # For an access-rights rejection the codes above can only say "denied" - which permission is
    # missing depends entirely on what was being written. Derive that from the operation string
    # so the message points at the right ACE instead of a generic delegation remark.
    $operationHint = $null
    if ($Operation -and ($resultCode -eq 50 -or $extCode -eq 0x00002098)) {
        foreach ($rule in $Script:LDAPWriteOperationHints) {
            if ($Operation -match $rule.Pattern) {
                $operationHint = $rule.Hint
                break
            }
        }
    }

    # Build a formatted, tester-friendly multi-line message.
    $lines = New-Object System.Collections.Generic.List[string]
    if ($null -ne $resultCode) {
        $lines.Add(("LDAP result: {0} ({1})" -f $resultCode, $resultName))
    }
    if ($extHex) {
        if ($extName) {
            $lines.Add(("Server sub-error: {0} ({1})" -f $extHex, $extName))
        } else {
            $lines.Add(("Server sub-error: {0}" -f $extHex))
        }
    }
    if ($hint) {
        $lines.Add(("Likely cause: {0}" -f $hint))
    }
    if ($operationHint) {
        $lines.Add(("Required rights: {0}" -f $operationHint))
    }
    if ($lines.Count -eq 0) {
        # Nothing structured could be extracted - surface the raw message so the
        # tester is never left with less information than before.
        $lines.Add($Exception.Message)
    }

    return [PSCustomObject]@{
        Operation     = $Operation
        ResultCode    = $resultCode
        ResultName    = $resultName
        ExtendedCode  = $extCode
        ExtendedHex   = $extHex
        ExtendedName  = $extName
        Hint          = $hint
        OperationHint = $operationHint
        ServerMessage = $serverMessage
        Formatted     = ($lines -join ([Environment]::NewLine + '  '))
    }
}




# ----- adPEAS-InputValidation.ps1 -----

<#
.SYNOPSIS
    Central input validation functions for adPEAS.

.DESCRIPTION
    Provides secure input validation and sanitization functions to prevent:
    - LDAP Injection attacks (RFC 4515 escaping)
    - UNC Path traversal attacks
    - Invalid computer/domain name injection
    - Command injection via parameter manipulation

    All validation functions follow the principle of whitelist validation
    (allow known-good patterns) rather than blacklist (block known-bad).

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

#region LDAP Escaping (RFC 4515)

<#
.SYNOPSIS
    Escapes special characters in LDAP filter values according to RFC 4515.

.DESCRIPTION
    LDAP filters use special characters that must be escaped when they appear
    in filter values. This function escapes all characters defined in RFC 4515
    Section 3 to prevent LDAP injection attacks.

    Characters that MUST be escaped:
    - * (asterisk)     -> \2a
    - ( (left paren)   -> \28
    - ) (right paren)  -> \29
    - \ (backslash)    -> \5c
    - NUL (0x00)       -> \00

    Additionally, any non-ASCII characters are hex-escaped for safety.

.PARAMETER Value
    The string value to escape for use in an LDAP filter.

.EXAMPLE
    Escape-LDAPFilterValue -Value "john*"
    # Returns: john\2a

.EXAMPLE
    Escape-LDAPFilterValue -Value "CN=Test (Group)"
    # Returns: CN=Test \28Group\29

.EXAMPLE
    # Safe LDAP filter construction
    $escapedName = Escape-LDAPFilterValue -Value $userInput
    $filter = "(sAMAccountName=$escapedName)"

.OUTPUTS
    [string] The escaped value safe for use in LDAP filters.

.NOTES
    ALWAYS use this function when incorporating user input into LDAP filters!

    WRONG (vulnerable):
        $filter = "(sAMAccountName=$userInput)"

    CORRECT (safe):
        $escaped = Escape-LDAPFilterValue -Value $userInput
        $filter = "(sAMAccountName=$escaped)"
#>
function Escape-LDAPFilterValue {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [AllowEmptyString()]
        [string]$Value
    )

    process {
        if ([string]::IsNullOrEmpty($Value)) {
            return $Value
        }

        # RFC 4515 Section 3 - Characters that MUST be escaped in LDAP filter values
        # Build result character by character for complete control
        $result = [System.Text.StringBuilder]::new($Value.Length * 2)

        foreach ($char in $Value.ToCharArray()) {
            switch ($char) {
                # RFC 4515 required escapes
                '*'  { [void]$result.Append('\2a'); break }
                '('  { [void]$result.Append('\28'); break }
                ')'  { [void]$result.Append('\29'); break }
                '\'  { [void]$result.Append('\5c'); break }
                "`0" { [void]$result.Append('\00'); break }  # NUL character

                default {
                    # Check for non-printable or non-ASCII characters
                    $charCode = [int]$char
                    if ($charCode -lt 32 -or $charCode -gt 126) {
                        # Hex-encode non-printable/non-ASCII
                        $bytes = [System.Text.Encoding]::UTF8.GetBytes([string]$char)
                        foreach ($byte in $bytes) {
                            [void]$result.Append('\')
                            [void]$result.Append($byte.ToString('x2'))
                        }
                    }
                    else {
                        [void]$result.Append($char)
                    }
                }
            }
        }

        return $result.ToString()
    }
}

<#
.SYNOPSIS
    Escapes a Distinguished Name for use in LDAP filter values.

.DESCRIPTION
    When a DN is used as a VALUE in an LDAP filter (e.g., memberOf=<DN>),
    it needs RFC 4515 escaping for the filter context.

    IMPORTANT: This function is for DNs used INSIDE filter assertions.
    It applies RFC 4515 filter value escaping, which handles:
    - * ( ) \ NUL and non-ASCII characters

    Note: RFC 4514 DN escaping (for DN construction) uses different rules
    and escapes: , + " \ < > ; and leading/trailing spaces.
    AD typically returns properly escaped DNs, so when re-using AD-returned
    DNs in filters, only RFC 4515 escaping is needed.

.PARAMETER DistinguishedName
    The DN to escape for use in an LDAP filter value.

.EXAMPLE
    $escapedDN = Escape-LDAPFilterDN -DistinguishedName "CN=Test (User),OU=Users,DC=contoso,DC=com"
    $filter = "(memberOf=$escapedDN)"

.OUTPUTS
    [string] The escaped DN safe for use in LDAP filters.
#>
function Escape-LDAPFilterDN {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [AllowEmptyString()]
        [string]$DistinguishedName
    )

    process {
        if ([string]::IsNullOrEmpty($DistinguishedName)) {
            return $DistinguishedName
        }

        # DNs from AD are already RFC 4514 escaped. RFC 4514 uses backslash-escaping
        # for special chars: \, \+ \" \\ \< \> \; \# and \XX hex pairs.
        # We must NOT double-escape those backslashes. We only need to escape
        # the RFC 4515 filter-specific characters: * ( ) NUL
        # and any non-ASCII characters.
        $result = [System.Text.StringBuilder]::new($DistinguishedName.Length * 2)
        $chars = $DistinguishedName.ToCharArray()
        $i = 0

        while ($i -lt $chars.Length) {
            $char = $chars[$i]

            if ($char -eq '\') {
                # Check if this backslash is part of an existing RFC 4514 escape sequence
                if (($i + 2) -lt $chars.Length) {
                    $next1 = $chars[$i + 1]
                    $next2 = $chars[$i + 2]
                    # RFC 4514 hex pair: \XX where X is [0-9a-fA-F]
                    $isHex1 = ($next1 -ge '0' -and $next1 -le '9') -or ($next1 -ge 'a' -and $next1 -le 'f') -or ($next1 -ge 'A' -and $next1 -le 'F')
                    $isHex2 = ($next2 -ge '0' -and $next2 -le '9') -or ($next2 -ge 'a' -and $next2 -le 'f') -or ($next2 -ge 'A' -and $next2 -le 'F')
                    if ($isHex1 -and $isHex2) {
                        # Existing hex escape - pass through unchanged
                        [void]$result.Append($chars[$i])
                        [void]$result.Append($chars[$i + 1])
                        [void]$result.Append($chars[$i + 2])
                        $i += 3
                        continue
                    }
                }
                if (($i + 1) -lt $chars.Length) {
                    $next = $chars[$i + 1]
                    # RFC 4514 special char escapes: \, \+ \" \\ \< \> \; \#
                    if ($next -eq ',' -or $next -eq '+' -or $next -eq '"' -or $next -eq '\' -or
                        $next -eq '<' -or $next -eq '>' -or $next -eq ';' -or $next -eq '#' -or $next -eq ' ') {
                        # Existing special char escape - pass through unchanged
                        [void]$result.Append($chars[$i])
                        [void]$result.Append($chars[$i + 1])
                        $i += 2
                        continue
                    }
                }
                # Standalone backslash (not part of RFC 4514 escape) - escape for RFC 4515
                [void]$result.Append('\5c')
            }
            elseif ($char -eq '*') {
                [void]$result.Append('\2a')
            }
            elseif ($char -eq '(') {
                [void]$result.Append('\28')
            }
            elseif ($char -eq ')') {
                [void]$result.Append('\29')
            }
            elseif ($char -eq "`0") {
                [void]$result.Append('\00')
            }
            else {
                $charCode = [int]$char
                if ($charCode -lt 32 -or $charCode -gt 126) {
                    $bytes = [System.Text.Encoding]::UTF8.GetBytes([string]$char)
                    foreach ($byte in $bytes) {
                        [void]$result.Append('\')
                        [void]$result.Append($byte.ToString('x2'))
                    }
                }
                else {
                    [void]$result.Append($char)
                }
            }
            $i++
        }

        return $result.ToString()
    }
}

#endregion

#region Computer Name Validation

<#
.SYNOPSIS
    Validates a computer name against Windows/NetBIOS naming rules.

.DESCRIPTION
    Validates computer names using whitelist approach based on:
    - RFC 1123 (Internet host naming)
    - Microsoft NetBIOS naming conventions
    - Windows computer naming restrictions

    Valid names:
    - 1-15 characters for NetBIOS, up to 63 for DNS
    - Alphanumeric characters (a-z, A-Z, 0-9)
    - Hyphens (but not at start or end)
    - Cannot be all digits
    - Cannot contain: \ / : * ? " < > |

.PARAMETER ComputerName
    The computer name to validate.

.PARAMETER AllowFQDN
    If specified, allows fully qualified domain names (e.g., server.contoso.com).

.PARAMETER AllowIPAddress
    If specified, allows IPv4 addresses.

.EXAMPLE
    Test-ValidComputerName -ComputerName "DC01"
    # Returns: $true

.EXAMPLE
    Test-ValidComputerName -ComputerName "server.contoso.com" -AllowFQDN
    # Returns: $true

.EXAMPLE
    Test-ValidComputerName -ComputerName "../../etc"
    # Returns: $false (path traversal attempt)

.OUTPUTS
    [bool] $true if valid, $false otherwise.
#>
function Test-ValidComputerName {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [AllowEmptyString()]
        [string]$ComputerName,

        [Parameter(Mandatory = $false)]
        [switch]$AllowFQDN,

        [Parameter(Mandatory = $false)]
        [switch]$AllowIPAddress
    )

    process {
        if ([string]::IsNullOrWhiteSpace($ComputerName)) {
            return $false
        }

        # Trim whitespace
        $name = $ComputerName.Trim()

        # Check for path traversal attempts
        if ($name -match '\.\.' -or $name -match '[\\/]') {
            Write-Log "[Test-ValidComputerName] Rejected: Path traversal pattern detected in '$name'"
            return $false
        }

        # Check for shell metacharacters
        if ($name -match '[;&|`$<>]') {
            Write-Log "[Test-ValidComputerName] Rejected: Shell metacharacters detected in '$name'"
            return $false
        }

        # Check for IPv6 addresses (IPv4 is handled in the dot-check below)
        if ($AllowIPAddress) {
            $ipResult = $null
            if ([System.Net.IPAddress]::TryParse($name, [ref]$ipResult)) {
                if ($ipResult.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetworkV6) {
                    return $true
                }
            }
        }

        # Check if name contains dots (potential FQDN or IP)
        if ($name -match '\.') {
            # Reject IPv4 addresses unless -AllowIPAddress is set
            # This prevents IPs from being accepted via the FQDN path
            $ipv4Pattern = '^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
            if ($name -match $ipv4Pattern) {
                if ($AllowIPAddress) {
                    return $true
                }
                Write-Log "[Test-ValidComputerName] Rejected: IP address not allowed, got '$name'"
                return $false
            }

            if (-not $AllowFQDN) {
                Write-Log "[Test-ValidComputerName] Rejected: FQDN not allowed, got '$name'"
                return $false
            }

            # FQDN validation: series of labels separated by dots (at least one dot required)
            # Each label: 1-63 chars, alphanumeric + hyphen, no start/end hyphen
            $fqdnPattern = '^(?=.{1,253}$)(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$'
            if ($name -match $fqdnPattern) {
                return $true
            }
            Write-Log "[Test-ValidComputerName] Rejected: Invalid FQDN format '$name'"
            return $false
        }

        # NetBIOS/single-label name validation
        # Length: 1-15 characters
        if ($name.Length -lt 1 -or $name.Length -gt 15) {
            Write-Log "[Test-ValidComputerName] Rejected: Length out of range (1-15) for '$name'"
            return $false
        }

        # Must start with alphanumeric
        if ($name -notmatch '^[a-zA-Z0-9]') {
            Write-Log "[Test-ValidComputerName] Rejected: Must start with alphanumeric '$name'"
            return $false
        }

        # Must end with alphanumeric
        if ($name -notmatch '[a-zA-Z0-9]$') {
            Write-Log "[Test-ValidComputerName] Rejected: Must end with alphanumeric '$name'"
            return $false
        }

        # Only alphanumeric, hyphens, and underscores allowed
        if ($name -notmatch '^[a-zA-Z0-9_-]+$') {
            Write-Log "[Test-ValidComputerName] Rejected: Invalid characters in '$name'"
            return $false
        }

        # Cannot be all digits
        if ($name -match '^\d+$') {
            Write-Log "[Test-ValidComputerName] Rejected: Cannot be all digits '$name'"
            return $false
        }

        return $true
    }
}

#endregion

#region UNC Path Validation

<#
.SYNOPSIS
    Validates a UNC path for security.

.DESCRIPTION
    Validates UNC paths using whitelist approach to prevent:
    - Path traversal attacks (../)
    - Redirect to external hosts
    - Invalid path formats
    - Shell metacharacter injection

.PARAMETER UNCPath
    The UNC path to validate.

.PARAMETER AllowedHosts
    Optional array of allowed hostnames/IPs. If specified, only these hosts are allowed.

.PARAMETER AllowedShares
    Optional array of allowed share names. If specified, only these shares are allowed.

.EXAMPLE
    Test-ValidUNCPath -UNCPath "\\dc01\SYSVOL"
    # Returns: $true

.EXAMPLE
    Test-ValidUNCPath -UNCPath "\\dc01\..\C$"
    # Returns: $false (path traversal)

.EXAMPLE
    Test-ValidUNCPath -UNCPath "\\dc01\SYSVOL" -AllowedShares @("SYSVOL", "NETLOGON")
    # Returns: $true

.OUTPUTS
    [bool] $true if valid, $false otherwise.
#>
function Test-ValidUNCPath {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [AllowEmptyString()]
        [string]$UNCPath,

        [Parameter(Mandatory = $false)]
        [string[]]$AllowedHosts,

        [Parameter(Mandatory = $false)]
        [string[]]$AllowedShares
    )

    process {
        if ([string]::IsNullOrWhiteSpace($UNCPath)) {
            return $false
        }

        # Must start with \\
        if ($UNCPath -notmatch '^\\\\') {
            Write-Log "[Test-ValidUNCPath] Rejected: Must start with \\\\ - '$UNCPath'"
            return $false
        }

        # Check for path traversal
        if ($UNCPath -match '\.\.') {
            Write-Log "[Test-ValidUNCPath] Rejected: Path traversal detected in '$UNCPath'"
            return $false
        }

        # Check for shell metacharacters
        if ($UNCPath -match '[;&|`<>]') {
            Write-Log "[Test-ValidUNCPath] Rejected: Shell metacharacters in '$UNCPath'"
            return $false
        }

        # Parse UNC path: \\host\share[\path]
        if ($UNCPath -notmatch '^\\\\([^\\]+)\\([^\\]+)') {
            Write-Log "[Test-ValidUNCPath] Rejected: Invalid UNC format '$UNCPath'"
            return $false
        }

        $uncHost = $Matches[1]
        $share = $Matches[2]

        # Validate host part
        if (-not (Test-ValidComputerName -ComputerName $uncHost -AllowFQDN -AllowIPAddress)) {
            Write-Log "[Test-ValidUNCPath] Rejected: Invalid host in '$UNCPath'"
            return $false
        }

        # Check allowed hosts if specified
        if ($AllowedHosts -and $AllowedHosts.Count -gt 0) {
            $hostAllowed = $false
            foreach ($allowedHost in $AllowedHosts) {
                if ($uncHost -ieq $allowedHost) {
                    $hostAllowed = $true
                    break
                }
            }
            if (-not $hostAllowed) {
                Write-Log "[Test-ValidUNCPath] Rejected: Host '$uncHost' not in allowed list"
                return $false
            }
        }

        # Validate share name (alphanumeric, hyphen, underscore, dot, dollar for admin shares)
        # Dots allowed for shares like "Data.2024" or "Backup.Archive"
        if ($share -notmatch '^[a-zA-Z0-9_.-]+\$?$') {
            Write-Log "[Test-ValidUNCPath] Rejected: Invalid share name '$share'"
            return $false
        }

        # Check allowed shares if specified
        if ($AllowedShares -and $AllowedShares.Count -gt 0) {
            $shareAllowed = $false
            foreach ($allowedShare in $AllowedShares) {
                if ($share -ieq $allowedShare) {
                    $shareAllowed = $true
                    break
                }
            }
            if (-not $shareAllowed) {
                Write-Log "[Test-ValidUNCPath] Rejected: Share '$share' not in allowed list"
                return $false
            }
        }

        return $true
    }
}

#endregion



# ----- Write-adPEASOutput.ps1 -----

<#
.SYNOPSIS
    Pure output layer for adPEAS - handles console and file output.

.DESCRIPTION
    Layer 3 of the three-layer architecture. This module is responsible ONLY for:
    - ANSI color-coded console output (Write-Host)
    - Plain text file output (without ANSI codes)
    - Prefix handling ([?], [!], [+], [*], [#])

    NO business logic, NO data transformation, NO LDAP queries.
    All formatting decisions are made by Get-RenderModel and the renderers.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

<#
.SYNOPSIS
    Writes a single formatted line to console and/or file.
.DESCRIPTION
    Pure output function - takes pre-formatted content and writes it to:
    - Console with ANSI colors (if $Script:adPEAS_OutputColor is not $false)
    - File without ANSI codes (if $Script:adPEAS_Outputfile is set)
.PARAMETER Text
    The text to output.
.PARAMETER Class
    The severity class for coloring: Info, SubInfo, Finding, Hint, Note, Secure, Standard.
.PARAMETER NoPrefix
    Skip the class prefix ([!], [+], etc.).
.PARAMETER NoNewline
    Don't add a newline after output.
.PARAMETER NoColor
    Force plain output even if color is enabled.
.PARAMETER LeadingNewline
    Add a newline before the output (for visual separation).
.EXAMPLE
    Write-adPEASOutput -Text "Vulnerability found!" -Class "Finding"
.EXAMPLE
    Write-adPEASOutput -Text "contoso.com" -Class "Standard" -NoPrefix
#>
function Write-adPEASOutput {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true)]
        [AllowEmptyString()]
        [string]$Text,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Info", "SubInfo", "Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [switch]$NoPrefix,

        [Parameter(Mandatory=$false)]
        [switch]$NoNewline,

        [Parameter(Mandatory=$false)]
        [switch]$NoColor,

        [Parameter(Mandatory=$false)]
        [switch]$LeadingNewline
    )

    begin {
        $ANSI = $Script:ANSI
        $ANSI_esc = $Script:ANSI_esc
    }

    process {
        # Build prefix
        $prefix = if (-not $NoPrefix) { Get-ClassPrefix -Class $Class } else { "" }

        # Build plain text (for file output and non-color console)
        $plainText = $prefix + $Text
        if ($LeadingNewline) {
            $plainText = "`n" + $plainText
        }

        # Console output
        if ($Script:adPEAS_OutputColor -ne $false -and -not $NoColor) {
            # Colored output
            $color = Get-ClassColor -Class $Class
            $coloredText = $color + $plainText + $ANSI["Reset"]
            Write-Host $coloredText -NoNewline:$NoNewline
        } else {
            # Plain output
            Write-Host $plainText -NoNewline:$NoNewline
        }

        # File output (with or without ANSI codes based on $Script:adPEAS_OutputColor)
        if ($Script:adPEAS_Outputfile) {
            if ($Script:adPEAS_OutputColor -ne $false -and -not $NoColor) {
                # Colored file output (default) - include ANSI codes
                $color = Get-ClassColor -Class $Class
                $fileText = $color + $plainText + $ANSI["Reset"]
            } else {
                # Plain file output (-NoColor) - strip ANSI codes
                $fileText = $plainText -replace "$ANSI_esc\[\d+(;\d+)*m", ""
            }
            # Add newline to text itself to avoid Out-File adding extra blank lines
            if (-not $NoNewline) {
                $fileText = $fileText + "`n"
            }
            [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $fileText, [System.Text.Encoding]::UTF8)
        }
    }
}

<#
.SYNOPSIS
    Writes a formatted attribute line (key-value pair) to output.
.DESCRIPTION
    Outputs a key-value pair with proper alignment and optional per-value coloring.
    Used for AD object attributes where the key (attribute name) may have a different class than the value.
.PARAMETER Name
    The attribute name (key).
.PARAMETER Value
    The attribute value.
.PARAMETER Class
    The severity class for the attribute name.
.PARAMETER ValueClass
    Optional separate class for the value. If not specified, value uses Standard (grey).
.PARAMETER AlignAt
    Column width for alignment (default: 45).
.PARAMETER ColorValue
    When set, color the entire line (name + value) with the Class color.
.EXAMPLE
    Write-adPEASAttribute -Name "sAMAccountName" -Value "admin"
.EXAMPLE
    Write-adPEASAttribute -Name "pwdLastSet" -Value "01/01/2020" -Class "Finding" -ColorValue
#>
function Write-adPEASAttribute {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Name,

        [Parameter(Mandatory=$true)]
        [string]$Value,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Info", "SubInfo", "Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [ValidateSet("Info", "SubInfo", "Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$ValueClass,

        [Parameter(Mandatory=$false)]
        [int]$AlignAt = 45,

        [Parameter(Mandatory=$false)]
        [switch]$ColorValue
    )

    $ANSI = $Script:ANSI
    $ANSI_esc = $Script:ANSI_esc

    # Determine if this is a continuation line (no name)
    $IsContinuationLine = [string]::IsNullOrEmpty($Name)

    # Build prefix (only for non-continuation lines)
    $prefix = if (-not $IsContinuationLine) { Get-ClassPrefix -Class $Class } else { "" }
    $hasPrefix = ($prefix.Length -gt 0)

    # Calculate padding (reduce by 4 when prefix present)
    $paddingWidth = if ($hasPrefix) { $AlignAt - 4 } else { $AlignAt }
    $nameWithColon = if ($Name) { "${Name}:" } else { "" }
    $paddedName = $nameWithColon.PadRight($paddingWidth, ' ')

    # Build plain text
    $plainText = $prefix + $paddedName + $Value

    # Console output
    if ($Script:adPEAS_OutputColor -ne $false) {
        $classColor = Get-ClassColor -Class $Class

        # For Secure class: NEVER color entire line (background color looks ugly), instead, color name and value separately WITH padding uncolored
        if ($ColorValue -and $Class -notin @("Standard", "Secure")) {
            # Color entire line (name + value) with class color
            $coloredText = $classColor + $plainText + $ANSI["Reset"]
            Write-Host $coloredText
        } elseif ($Class -eq "Secure") {
            # Special handling for Secure class (has background color), color ONLY the prefix+name and value, NOT the padding spaces
            $nameOnlyWithColon = if ($Name) { "${Name}:" } else { "" }
            $paddingSpaces = ' ' * ($paddingWidth - $nameOnlyWithColon.Length)

            # Build: [colored prefix+name] [reset] [padding] [colored value] [reset]
            $coloredOutput = $classColor + $prefix + $nameOnlyWithColon + $ANSI["Reset"] +
                            $paddingSpaces +
                            $classColor + $Value + $ANSI["Reset"]
            Write-Host $coloredOutput
        } else {
            # Default: color attribute name (with padding), value uses ValueClass or grey
            $attrPart = $prefix + $paddedName
            $effectiveValueClass = if ($ValueClass) { $ValueClass } else { "Standard" }
            $valueColor = Get-ClassColor -Class $effectiveValueClass
            Write-Host ($classColor + $attrPart + $ANSI["Reset"] + $valueColor + $Value + $ANSI["Reset"])
        }
    } else {
        Write-Host $plainText
    }

    # File output (with or without ANSI codes based on $Script:adPEAS_OutputColor)
    if ($Script:adPEAS_Outputfile) {
        if ($Script:adPEAS_OutputColor -ne $false) {
            # Colored file output (default) - recreate the colored version
            $classColor = Get-ClassColor -Class $Class
            if ($ColorValue -and $Class -notin @("Standard", "Secure")) {
                $fileText = $classColor + $plainText + $ANSI["Reset"]
            } elseif ($Class -eq "Secure") {
                $nameOnlyWithColon = if ($Name) { "${Name}:" } else { "" }
                $paddingSpaces = ' ' * ($paddingWidth - $nameOnlyWithColon.Length)
                $fileText = $classColor + $prefix + $nameOnlyWithColon + $ANSI["Reset"] +
                            $paddingSpaces +
                            $classColor + $Value + $ANSI["Reset"]
            } else {
                $attrPart = $prefix + $paddedName
                $effectiveValueClass = if ($ValueClass) { $ValueClass } else { "Standard" }
                $valueColor = Get-ClassColor -Class $effectiveValueClass
                $fileText = $classColor + $attrPart + $ANSI["Reset"] + $valueColor + $Value + $ANSI["Reset"]
            }
        } else {
            # Plain file output (-NoColor) - strip any ANSI codes
            $fileText = $plainText -replace "$ANSI_esc\[\d+(;\d+)*m", ""
        }
        # Add newline to match console output exactly
        [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $fileText + "`n", [System.Text.Encoding]::UTF8)
    }
}

<#
.SYNOPSIS
    Writes an empty line to output.
.DESCRIPTION
    Utility function to add vertical spacing in output.
    Follows the Show-* naming convention for consistency with other output functions.
#>
function Show-EmptyLine {
    [CmdletBinding()]
    param()

    Write-Host ""
    if ($Script:adPEAS_Outputfile) {
        # Write single newline to match console output exactly
        [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, "`n", [System.Text.Encoding]::UTF8)
    }
}

<#
.SYNOPSIS
    Writes the adPEAS logo to output.
.DESCRIPTION
    Displays the adPEAS logo with version number and legend.
    This is a special case that bypasses the normal formatting pipeline.
.PARAMETER Version
    The version string to display.
#>
function Write-adPEASLogo {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Version = "2.0"
    )

    $ANSI = $Script:ANSI

    # Build legend entries
    $Legend = @{
        "Info"    = "[?] Searching for juicy information"
        "Finding" = "[!] Found a vulnerability which may be exploitable"
        "Hint"    = "[+] Found some interesting information for further investigation"
        "Note"    = "[*] Some kind of note"
        "Secure"  = "[#] Some kind of secure configuration"
    }

    # Color legend if enabled
    if ($Script:adPEAS_OutputColor -ne $false) {
        foreach ($cls in @("Info", "Finding", "Hint", "Note", "Secure")) {
            $color = Get-ClassColor -Class $cls
            $Legend[$cls] = $color + $Legend[$cls] + $ANSI["Reset"]
        }
    }

    # Build logo
    $LogoStart = if ($Script:adPEAS_OutputColor -ne $false) { Get-ClassColor -Class "Info" } else { "" }
    $LogoStop = if ($Script:adPEAS_OutputColor -ne $false) { $ANSI["Reset"] } else { "" }

    $LogoText = @"
$LogoStart
               _ _____  ______           _____
              | |  __ \|  ____|   /\    / ____|
      ____  __| | |__) | |__     /  \  | (___
     / _  |/ _  |  ___/|  __|   / /\ \  \___ \
    | (_| | (_| | |    | |____ / ____ \ ____) |
     \__,_|\__,_|_|    |______/_/    \_\_____/
                                            Version $Version
$LogoStop
    Active Directory Enumeration
    by @61106960
$("")
    Legend
        $($Legend["Info"])
        $($Legend["Finding"])
        $($Legend["Hint"])
        $($Legend["Note"])
        $($Legend["Secure"])
"@

    Write-Host $LogoText
    # Explicit empty line after logo (survives minification and scope changes)
    Write-Host ""

    # File output (with or without ANSI codes based on $Script:adPEAS_OutputColor)
    if ($Script:adPEAS_Outputfile) {
        if ($Script:adPEAS_OutputColor -ne $false) {
            # Colored file output (default) - include ANSI codes
            # Extra newline at end for empty line after logo
            [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $LogoText + "`n`n", [System.Text.Encoding]::UTF8)
        } else {
            # Plain file output (-NoColor) - strip ANSI codes
            # Extra newline at end for empty line after logo
            $ANSI_esc = $Script:ANSI_esc
            $FileLogoText = $LogoText -replace "$ANSI_esc\[\d+(;\d+)*m", ""
            [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $FileLogoText + "`n`n", [System.Text.Encoding]::UTF8)
        }
    }
}

<#
.SYNOPSIS
    Writes a section header with decorative lines.
.DESCRIPTION
    Outputs a visually distinct section header with separator lines.
    Used for main sections like "Domain Information", "User Enumeration", etc.
.PARAMETER Value
    The header text.
#>
function Write-adPEASHeader {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Value
    )

    $ANSI = $Script:ANSI
    $ANSI_esc = $Script:ANSI_esc

    $SeparatorLine = "=" * 70
    $HeaderLine = "+++++ $Value +++++"

    if ($Script:adPEAS_OutputColor -ne $false) {
        $color = Get-ClassColor -Class "Info"
        $output = "`n`n" + $color + $SeparatorLine + "`n" + $HeaderLine + "`n" + $SeparatorLine + $ANSI["Reset"]
        Write-Host $output
    } else {
        Write-Host ("`n`n" + $SeparatorLine)
        Write-Host $HeaderLine
        Write-Host $SeparatorLine
    }

    # File output (with or without ANSI codes based on $Script:adPEAS_OutputColor)
    if ($Script:adPEAS_Outputfile) {
        if ($Script:adPEAS_OutputColor -ne $false) {
            # Colored file output (default) - include ANSI codes
            $color = Get-ClassColor -Class "Info"
            $fileOutput = "`n`n" + $color + $SeparatorLine + "`n" + $HeaderLine + "`n" + $SeparatorLine + $ANSI["Reset"] + "`n"
            [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $fileOutput, [System.Text.Encoding]::UTF8)
        } else {
            # Plain file output (-NoColor)
            $fileOutput = "`n`n" + $SeparatorLine + "`n" + $HeaderLine + "`n" + $SeparatorLine + "`n"
            [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $fileOutput, [System.Text.Encoding]::UTF8)
        }
    }
}



# ----- adPEAS-AttributeOrder.ps1 -----

<#
.SYNOPSIS
    Central attribute order definitions for adPEAS output formatting.

.DESCRIPTION
    Defines the display order of attributes for different object types.
    Used by Get-RenderModel.ps1 for both console and HTML output.

    Design principle:
    - Primary attributes are always displayed prominently
    - Extended attributes with non-Standard severity are promoted to primary
    - This ensures consistent output across console and HTML

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# Primary attributes by object type
# These attributes are always shown in the main/primary section (in order)
#
# DESIGN: User and Computer share a harmonized structure for consistency:
#   1. Identity -> 2. OS (Computer only) -> 3. Groups -> 4. SPNs -> 5. Credentials
#   -> 6. Description -> 7. Delegation -> 8. UAC -> 9. Timestamps -> 10. Activity
#   -> 11. SID History -> 12. Security Findings -> 13. Roasting Hashes (User only)
#
$Script:PrimaryAttributes = @{

    # User objects (includes service accounts)
    User = @(
        # 1. IDENTITY BLOCK
        'displayName',
        'sAMAccountName', 'userPrincipalName', 'distinguishedName', 'objectSid',

        # 2. GROUP MEMBERSHIPS (security-critical)
        'memberOf', 'privilegedGroups',

        # 3. SERVICE PRINCIPAL NAMES (Kerberoasting indicator)
        'servicePrincipalName',

        # 4. CREDENTIAL EXPOSURE (passwords, LAPS)
        'unixUserPassword', 'userPassword', 'unicodePwd', 'msSFU30Password',
        'sambaNTPassword', 'sambaLMPassword',
        'ms-Mcs-AdmPwd', 'msLAPS-Password', 'msLAPS-EncryptedPassword', 'msLAPS-Account',

        # 5. DESCRIPTION/INFO (may contain credentials)
        'description', 'info',
        # Entra ID Connect information (parsed from description)
        'entraConnectServer', 'entraM365Tenant',

        # 6. DELEGATION SETTINGS
        'msDS-AllowedToDelegateTo', 'msDS-AllowedToActOnBehalfOfOtherIdentity',

        # 6b. SHADOW CREDENTIALS
        'msDS-KeyCredentialLink',

        # 7. ACCOUNT STATUS FLAGS
        'userAccountControl',

        # 8. TIMESTAMPS
        'pwdLastSet', 'lastLogonTimestamp',

        # 9. ACTIVITY STATUS
        'daysSinceLastLogon', 'isOrphaned', 'activityStatus',

        # 10. SID HISTORY (privilege escalation)
        'sIDHistory',

        # 11. SECURITY FINDINGS from check modules
        'dangerousRights', 'affectedOUs',

        # 12. ROASTING HASHES (ALWAYS LAST)
        'KerberoastingHash', 'KerberoastingHashType', 'ASREPRoastingHash', 'ASREPRoastingHashType'
    )

    # Computer objects
    Computer = @(
        # 1. IDENTITY BLOCK
        'displayName',
        'sAMAccountName', 'dNSHostName', 'distinguishedName', 'objectSid',

        # 2. OPERATING SYSTEM
        'operatingSystem',

        # 3. GROUP MEMBERSHIPS
        'memberOf', 'privilegedGroups',

        # 4. CREDENTIAL EXPOSURE (LAPS)
        # Note: servicePrincipalName moved to extended view (too verbose for primary display)
        'ms-Mcs-AdmPwd', 'msLAPS-Password', 'msLAPS-EncryptedPassword', 'msLAPS-Account',

        # 5. DESCRIPTION/INFO (may contain credentials)
        'description', 'info',

        # 6. DELEGATION SETTINGS
        'msDS-AllowedToDelegateTo', 'msDS-AllowedToActOnBehalfOfOtherIdentity',

        # 6b. SHADOW CREDENTIALS
        'msDS-KeyCredentialLink',

        # 7. ACCOUNT STATUS FLAGS
        'userAccountControl',

        # 8. TIMESTAMPS
        'pwdLastSet', 'lastLogonTimestamp',

        # 9. ACTIVITY STATUS
        'activityStatus', 'daysSinceLastLogon', 'isOrphaned',

        # 10. SID HISTORY (privilege escalation)
        'sIDHistory',

        # 11. SECURITY FINDINGS from check modules
        'dangerousRights', 'affectedOUs'
    )

    # Certificate Template objects
    CertificateTemplate = @(
        # 1. Identification
        'Name', 'displayName', 'DistinguishedName',
        # 2. CA publishing info
        'PublishedOn',
        # 3. Template info
        'SchemaVersion',
        # 3. EKU and flags (security-critical)
        # Note: ClientAuthentication is redundant - shown in ExtendedKeyUsage
        'ExtendedKeyUsage', 'CertificateNameFlagDisplay',
        # 4. Approval settings
        'ManagerApprovalRequired',
        # 4b. Registration Authority requirement (ESC3 condition 2).
        # A template that demands a co-signature from an enrollment agent is both a barrier for
        # direct abuse and the target of an "enroll on behalf of" attack - it must be visible on
        # the console, not only in the HTML extended block.
        'RASignatureCount', 'RAApplicationPolicies',
        # 5. Enrollment
        'EnrollmentPrincipals',
        # 6. Security findings
        'DangerousACEs',
        # 7. ESC13 - Issuance policy group links
        'IssuancePolicyGroupLinks'
    )

    # GPO objects (generic fallback for GPOs without specific _adPEASObjectType)
    GPO = @(
        'displayName', 'Name', 'distinguishedName', 'gPCFileSysPath',
        # LDAP security settings
        'LDAPSigning', 'ChannelBinding', 'AnonymousBinding', 'ServerSigning', 'ClientSigning',
        # Security findings
        'DangerousPermissions', 'DangerousSettings',
        # Linkage
        'Scope', 'LinkedOUs', 'AffectedComputers'
    )

    # SMB Signing GPO (only SMB-relevant attributes, no LDAP)
    SMBSigning = @(
        'displayName', 'Name', 'distinguishedName', 'gPCFileSysPath',
        'ServerSigning', 'ClientSigning',
        'Scope', 'LinkedOUs', 'IsEffectiveSetting'
    )

    # LDAP Configuration GPO (only LDAP-relevant attributes, no SMB)
    LDAPConfigGPO = @(
        'displayName', 'Name', 'distinguishedName', 'gPCFileSysPath',
        'LDAPSigning', 'ChannelBinding', 'AnonymousBinding',
        'Scope', 'LinkedOUs', 'IsEffectiveSetting'
    )

    # GPO-deployed dangerous registry settings (Get-GPORegistrySettings)
    GPORegistrySetting = @(
        'GPOName', 'Source', 'RegistryKey', 'ConfiguredValue',
        'VulnerabilityName', 'RiskReason',
        'LinkedOUs', 'LinkedOUCount'
    )

    # LAPS policy settings deployed via GPO (Get-LAPSConfiguration, Step 3)
    LAPSGPOConfig = @(
        'GPOName', 'LAPSVersion', 'ManagedAccount',
        'BackupDirectory', 'PasswordEncryption', 'EncryptionPrincipal',
        'PasswordComplexity', 'PasswordLength', 'PassphraseLength', 'PasswordAgeDays',
        'ExpirationProtection',
        'LinkedOUs', 'LinkedOUCount'
    )

    # Domain Password Policy (all attributes are security-relevant)
    DomainPasswordPolicy = @(
        'minPwdLength', 'passwordComplexity',
        'minPwdAge', 'maxPwdAge',
        'reversibleEncryption',
        'lockoutThreshold', 'lockoutDuration', 'lockoutObservationWindow'
    )

    # Fine-Grained Password Policy (PSO)
    FineGrainedPasswordPolicy = @(
        'psoName', 'precedence',
        'minPwdLength', 'passwordComplexity',
        'reversibleEncryption',
        'lockoutThreshold',
        'appliesTo'
    )

    # Certificate Authority objects
    CertificateAuthority = @(
        # 1. CA Common Name (from pKIEnrollmentService, added by check module)
        'caName',
        # 2. Identification
        'sAMAccountName', 'dNSHostName', 'distinguishedName', 'objectSid',
        # 2a. Cross-domain note (when CA computer object is in different domain)
        'caNote',
        # 3. Operating System
        'operatingSystem',
        # 4. Group memberships
        'memberOf',
        # 5. CA Certificate properties
        'CACertSubject', 'CACertThumbprint', 'CACertValidity',
        'CACertSignatureAlgorithm', 'CACertKeySize',
        # 6. CA Certificate security findings
        'CACertWeakSignature', 'CACertShortKey', 'CACertExpired',
        # 7. Web enrollment (ESC8)
        'HttpAvailable', 'HttpsAvailable', 'WebEnrollmentEndpoints',
        # 8. Security
        'NTLMEnabled', 'EPAStatus',
        # 9. ADCS-specific
        'certificateTemplates',
        # 10. Enrollment service metadata
        'CALastModified'
    )

    # Root CA objects (PKI Trust Infrastructure)
    RootCA = @(
        'Subject', 'Issuer', 'SerialNumber', 'Thumbprint', 'Validity', 'Status',
        'SignatureAlgorithm', 'KeySize', 'HasBasicConstraints',
        'CRLDistributionPoints', 'OCSPURLs', 'AIAURLs'
    )

    # NTAuth Store certificate objects
    NTAuthCertificate = @(
        'Subject', 'Issuer', 'SerialNumber', 'Thumbprint', 'Validity', 'Status',
        'SignatureAlgorithm', 'KeySize', 'HasBasicConstraints',
        'CRLDistributionPoints', 'OCSPURLs', 'AIAURLs'
    )

    # AIA CA objects
    AIACA = @(
        'Subject', 'Issuer', 'SerialNumber', 'Thumbprint', 'Validity', 'Status',
        'SignatureAlgorithm', 'KeySize', 'HasBasicConstraints',
        'CRLDistributionPoints', 'OCSPURLs', 'AIAURLs'
    )

    # Domain Information object
    DomainInfo = @(
        'domainNameDNS', 'domainNameNetBIOS', 'domainSID',
        'domainFunctionalLevel', 'forestFunctionalLevel',
        'domainControllers', 'forestName',
        'parentDomain', 'childDomains',
        'anonymousLDAPAccess', 'anonymousReadableAttributes'
    )

    # Kerberos Policy object
    KerberosPolicy = @(
        'maxTicketAgeTGT', 'maxRenewalAge', 'krbtgtPasswordAge', 'domainControllerTime'
    )

    # Guest Account object (from Get-DomainInformation)
    GuestAccount = @(
        'accountStatus', 'memberOf'
    )

    # Domain Trust object (from Get-DomainTrusts)
    # Primary: trust identity only. All boolean flags are Extended but get auto-promoted
    # to Primary when their severity is non-Standard (Finding/Hint/Secure).
    # This means: isQuarantined=False on external trusts (Finding) -> promoted to Primary.
    #             isQuarantined=False on within-forest trusts (Standard) -> stays Extended.
    DomainTrust = @(
        'trustPartner',
        'flatName',
        'trustDirection',
        'trustType',
        'trustAttributes'
    )

    # Domain Controllers object
    DomainControllers = @(
        'domainControllers'
    )

    # Sites and Subnets object
    SitesSubnets = @(
        'siteName'
        'siteSubnets'
        'siteDomainControllers'
    )

    # Effective LDAP Security Configuration
    EffectiveLDAPConfig = @(
        'LDAPSigning', 'ChannelBinding', 'AnonymousBinding'
    )

    # Outdated Computer object
    OutdatedComputer = @(
        'name', 'dNSHostName', 'operatingSystem', 'operatingSystemVersion',
        'eolDate', 'daysSinceEoL', 'lastLogonTimestamp'
    )

    # GPO User Rights Assignment findings ([Privilege Rights] in GptTmpl.inf)
    GPOUserRights = @(
        'gpoName', 'userRight', 'userRightName', 'principals', 'scope', 'linkedOUs'
    )

    # Add Computer Rights findings (ACL-based)
    AddComputerRights = @(
        'sid', 'accountName', 'right', 'attributeName', 'value', 'isSecure',
        'gpoName', 'accounts', 'hasAuthenticatedUsers', 'severity'
    )

    # Machine Account Quota setting
    MachineAccountQuota = @(
        'ms-DS-MachineAccountQuota'
    )

    # GPO Scheduled Tasks (custom PSCustomObject from Get-GPOScheduledTasks)
    GPOScheduledTask = @(
        'GPOName', 'TaskName', 'Command', 'RunAs', 'Context',
        'Action', 'Trigger', 'LinkedOUs'
    )

    # GPO Script Paths (custom PSCustomObject from Get-GPOScriptPaths)
    GPOScriptPath = @(
        'GPOName', 'ScriptType', 'ScriptPath', 'Parameters', 'FullCommand',
        'ScriptLanguage', 'ExecutionContext', 'LinkedOUs'
    )

    # GPO Local Group Membership (custom PSCustomObject from Get-GPOLocalGroupMembership)
    GPOLocalGroup = @(
        'GPOName', 'Type', 'TargetGroup', 'MembersAdded',
        'RiskyMembers', 'LinkedOUs'
    )

    # GPO granting SeMachineAccountPrivilege (enriched native GPO object, same pattern as LDAPConfigGPO/SMBSigning)
    AddComputerGPO = @(
        'displayName', 'Name', 'distinguishedName', 'gPCFileSysPath',
        'Accounts',
        'Scope', 'LinkedOUs', 'IsEffectiveSetting'
    )

    # BitLocker Recovery Key (readable msFVE-RecoveryInformation child object)
    BitLockerRecoveryKey = @(
        'ComputerName',
        'msFVE-RecoveryPassword',
        'msFVE-RecoveryGuid',
        'msFVE-VolumeGuid',
        'whenCreated',
        'distinguishedName'
    )

    # Credential findings (GPP and SYSVOL)
    GPPCredential = @(
        'credentialType', 'gpoName', 'filePath', 'userName', 'password', 'matchedLine', 'LinkedOUs'
    )
    SYSVOLCredential = @(
        'credentialType', 'gpoName', 'filePath', 'userName', 'password', 'matchedLine', 'LinkedOUs'
    )

    # ACL findings (users/computers/groups with dangerous permissions)
    ACLFinding = @(
        # 1. Identification
        'sAMAccountName', 'userPrincipalName', 'distinguishedName', 'objectSid',
        # 2. Security findings
        'dangerousRights', 'affectedOUs',
        # 3. Inheritance source (shows where inherited permissions came from)
        'inheritedFrom',
        # 4. Group memberships
        'memberOf',
        # 5. Account control
        'userAccountControl',
        # 6. Timestamps
        'pwdLastSet', 'lastLogonTimestamp'
    )

    # Exchange Infrastructure
    Exchange = @(
        'sAMAccountName', 'dNSHostName', 'distinguishedName', 'objectSid',
        'operatingSystem',
        'memberOf',
        'HttpAvailable', 'HttpsAvailable',
        'ExchangeVersion', 'ExchangeBuildNumber',
        'WebEndpoints',
        'DangerousPermissions'
    )

    # ExchangeOrganization (Config Partition overview from Get-ExchangeInfrastructure)
    ExchangeOrganization = @(
        'OrganizationName', 'ExchangeServerCount', 'AcceptedDomains', 'SMTPSendConnectors'
    )

    # ExchangeConfigServer (per-server details from Config Partition)
    # Primary: targeting-relevant info (Name, FQDN, version, external exposure, ports)
    # Extended: structural details (DN, domain, VDirs, connector count, build number)
    ExchangeConfigServer = @(
        'Name', 'dNSHostName',
        'ExchangeVersion',
        'ExternalHostnames', 'SMTPListeningPorts'
    )

    # ExchangeServer alias (used by _adPEASObjectType from Get-ExchangeInfrastructure)
    ExchangeServer = @(
        'sAMAccountName', 'dNSHostName', 'distinguishedName', 'objectSid',
        'operatingSystem',
        'memberOf',
        'HttpAvailable', 'HttpsAvailable',
        'ExchangeVersion', 'ExchangeBuildNumber',
        'WebEndpoints',
        'DangerousPermissions'
    )

    # LAPS Finding (OU without LAPS protection)
    LAPSFinding = @(
        'ouName', 'computerCount', 'lapsUnprotectedComputers'
    )

    # Operator Group Finding (from Get-ProtectedUsersStatus)
    # Note: MemberCount and ProtectedCount are kept in object but excluded from display
    OperatorGroup = @(
        'OperatorGroup', 'OperatorGroupDN', 'Members'
    )

    # SCCM Site (from Get-SCCMInfrastructure Step 3)
    SCCMSite = @(
        'SiteCode', 'SourceForest', 'SiteGUID', 'DistinguishedName'
    )

    # SCCM Management Point (from Get-SCCMInfrastructure Step 4)
    SCCMManagementPoint = @(
        'ManagementPoint', 'SiteCode', 'SiteType', 'CommandLineSiteCode', 'RootSiteCode', 'Forest'
    )

    # SCCM PXE/WDS Server (from Get-SCCMInfrastructure Step 7)
    SCCMPXEServer = @(
        'PXEServer', 'WDSServicePoint', 'ParentObject', 'BindingInfo'
    )

    # SCCM Group (from Get-SCCMInfrastructure Step 8)
    # NOTE: Deliberately excludes 'member' to avoid per-DN SID resolution (O(n) LDAP queries per group)
    SCCMGroup = @(
        'sAMAccountName', 'description', 'MemberCount', 'memberOf', 'managedBy',
        'whenCreated', 'distinguishedName'
    )

    # SCOM Group (from Get-SCOMInfrastructure)
    # NOTE: Same rationale as SCCMGroup - excludes 'member' for performance
    SCOMGroup = @(
        'sAMAccountName', 'description', 'MemberCount', 'memberOf', 'managedBy',
        'whenCreated', 'distinguishedName'
    )

    # AdminSDHolder ACL (from Get-PrivilegedGroupMembers Step 5)
    AdminSDHolderACL = @(
        'Trustee', 'TrusteeSID', 'dangerousRights'
    )

    # LDAP Statistics per module (from Invoke-adPEAS -Statistics)
    LDAPStatisticsModule = @(
        'Queries', 'Results', 'EstimatedTraffic'
    )

    # LDAP Statistics total (from Invoke-adPEAS -Statistics)
    LDAPStatisticsTotal = @(
        'Queries', 'Results', 'EstimatedTraffic'
    )
}

# Object types with strict attribute display: ONLY PrimaryAttributes are shown, no Extended overflow.
# Use this for specialized views of shared objects (e.g., same GPO object used by both LDAP and SMB checks)
# to prevent cross-contamination of attributes from other checks.
$Script:StrictAttributeTypes = @(
    'SMBSigning',
    'LDAPConfigGPO',
    'AddComputerGPO',
    'EffectiveLDAPConfig',
    'LDAPStatisticsModule',
    'LDAPStatisticsTotal',
    'DomainPasswordPolicy',
    'FineGrainedPasswordPolicy',
    'BitLockerRecoveryKey',
    'GPOUserRights'
)

# Attributes to always exclude from display
# These are internal/technical attributes that should never be shown in output:
# - AD metadata (objectGUID, objectCategory, USN, whenCreated/Changed)
# - Security descriptors (handled separately)
# - Redundant attributes (already shown elsewhere)
# - Internal adPEAS markers (_adPEASObjectType, _adPEASContext)
$Script:ExcludeAttributes = @(
    'objectClass', 'objectGUID', 'objectCategory', 'instanceType',
    'uSNCreated', 'uSNChanged', 'whenCreated', 'whenChanged',
    'nTSecurityDescriptor',
    # Certificate Template internal attributes
    'PrivateKeyFlagDisplay', 'SecurityDescriptor',
    # EnrolleeSuppliesSubject is redundant - already shown in CertificateNameFlagDisplay as ENROLLEE_SUPPLIES_SUBJECT
    'EnrolleeSuppliesSubject',
    # ClientAuthentication is redundant - already shown in ExtendedKeyUsage as "Client Authentication"
    'ClientAuthentication',
    # EnrollmentAgentSignatureRequired is redundant for display - the underlying facts are shown as
    # RASignatureCount and RAApplicationPolicies. The property is kept on the object because the
    # ra_signature_gated finding trigger evaluates it via SourceObject.
    'EnrollmentAgentSignatureRequired',
    # EnrollmentAgentChainReachable records whether an enrollment agent certificate is obtainable
    # in this domain. Never displayed - picking the template to abuse for that is the tester's
    # call; the flag only feeds the ra_signature_gated severity trigger.
    'EnrollmentAgentChainReachable',
    # Internal classification attribute for Exchange groups - not for display
    'dangerousRightsSeverity',
    # Operator Group internal counts - kept in object but not displayed
    'MemberCount', 'ProtectedCount',
    # Internal adPEAS type markers and transport properties - not for display
    '_adPEASObjectType', '_adPEASContext', '_Severity', '_Risk',
    # GPO check internal analysis flags - used for severity calculation, not for display
    'GPOGUID', 'Risk', 'Severity',
    'IsSystemAccount', 'IsPrivilegedAccount',
    'HasUNCPath', 'HasRiskyPath', 'HasUnquotedPath', 'IsPowerShell', 'IsScript',
    'RunsAsSystem', 'TargetGroupSID', 'MemberSIDs',
    # Name is used for HTML card title resolution ({Name} in TitleFormat) but excluded from
    # extended attribute display to avoid redundancy. ObjectTypes that need Name visible
    # (CertificateTemplate, GPO) list it in their PrimaryAttributes, which takes precedence.
    'Name'
)

<#
.SYNOPSIS
    Detects the object type for attribute ordering.
.PARAMETER Object
    The object to analyze.
.RETURNS
    String identifying the object type (User, Computer, CertificateTemplate, GPO, etc.)
#>
function Get-ObjectTypeForOrdering {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Object
    )

    try {
        # If _adPEASObjectType is set and has a PrimaryAttributes entry, use it directly
    # This is the most authoritative source for custom PSCustomObjects (SCCM, GPO tasks, etc.)
    if ($Object._adPEASObjectType -and $Script:PrimaryAttributes.ContainsKey($Object._adPEASObjectType)) {
        return $Object._adPEASObjectType
    }

    # Domain Information objects (from Get-DomainInformation)
    if ($Object.domainNameDNS -and $Object.domainSID) {
        return 'DomainInfo'
    }

    # Kerberos Policy
    if ($Object.maxTicketAgeTGT -and $Object.maxRenewalAge) {
        return 'KerberosPolicy'
    }

    # Guest Account
    if ($Object.accountStatus -and $Object.passwordAge -and $Object._adPEASObjectType -eq 'GuestAccount') {
        return 'GuestAccount'
    }

    # Domain Controllers
    if ($Object.domainControllers -and -not $Object.domainNameDNS) {
        return 'DomainControllers'
    }

    # Sites and Subnets
    if ($Object.siteName -and $Object.siteSubnets) {
        return 'SitesSubnets'
    }

    # Effective LDAP Security Configuration
    if ($Object.LDAPSigning -and $Object.ChannelBinding -and $Object.AnonymousBinding -and -not $Object.gPCFileSysPath) {
        return 'EffectiveLDAPConfig'
    }

    # GPO (has gPCFileSysPath or GUID name pattern)
    if ($Object.gPCFileSysPath -or ($Object.Name -match '^\{[0-9a-fA-F-]+\}$')) {
        return 'GPO'
    }

    # Certificate Template
    if (($null -ne $Object.EnrolleeSuppliesSubject) -or ($null -ne $Object.CertificateNameFlagDisplay)) {
        return 'CertificateTemplate'
    }

    # Certificate Authority (CA computer object with ADCS-specific attributes)
    # HttpAvailable/WebEnrollmentEndpoints/certificateTemplates are only set by ADCS check module
    if (($null -ne $Object.HttpAvailable) -or ($null -ne $Object.WebEnrollmentEndpoints) -or
        ($null -ne $Object.certificateTemplates -and @($Object.objectClass) -contains 'computer')) {
        return 'CertificateAuthority'
    }

    # Operator Group Finding (from Get-ProtectedUsersStatus)
    if ($Object.OperatorGroup -and $null -ne $Object.MemberCount -and $null -ne $Object.ProtectedCount) {
        return 'OperatorGroup'
    }

    # Outdated Computer
    if ($Object.eolDate -and $Object.daysSinceEoL) {
        return 'OutdatedComputer'
    }

    # Add Computer Rights (ACL-based)
    if ($Object.sid -and $Object.accountName -and $Object.right) {
        return 'AddComputerRights'
    }

    # Machine Account Quota
    if ($Object.PSObject.Properties['ms-DS-MachineAccountQuota']) {
        return 'MachineAccountQuota'
    }

    # GPO granting SeMachineAccountPrivilege (enriched native GPO object with Accounts property)
    if ($Object._adPEASObjectType -eq 'AddComputerGPO') {
        return 'AddComputerGPO'
    }

    # Credential finding
    if ($Object.credentialType -and ($Object.password -or $Object.matchedLine)) {
        return 'GPPCredential'
    }

    # ACL Finding (has dangerousRights or affectedOUs)
    if ($Object.dangerousRights -or $Object.affectedOUs) {
        return 'ACLFinding'
    }

    # LAPS Finding (OU without LAPS protection)
    if ($Object.ouName -and $Object.lapsUnprotectedComputers -and $null -ne $Object.computerCount) {
        return 'LAPSFinding'
    }

    # Exchange Infrastructure
    if ($Object.ExchangeVersion -or $Object.ExchangeBuildNumber) {
        return 'Exchange'
    }

    # Computer (objectClass or $ suffix)
    # Use @() wrapper to ensure -contains works even if objectClass is a single value
    if ((@($Object.objectClass) -contains 'computer') -or ($Object.sAMAccountName -like '*$')) {
        return 'Computer'
    }

    # Default: User
    return 'User'

    } catch {
        # On any error during type detection, fall back to User
        Write-Warning "[Get-ObjectTypeForOrdering] Error detecting object type: $_"
        return 'User'
    }
}

<#
.SYNOPSIS
    Gets ordered attributes for an object, separating primary from extended.
.DESCRIPTION
    Returns attributes in defined order, with option to promote non-Standard
    severity attributes to primary section.
.PARAMETER Object
    The AD object to process.
.PARAMETER PromoteNonStandard
    If set, attributes with non-Standard severity (Finding, Hint, Secure, Note)
    are promoted to primary even if not in the primary list.
.PARAMETER IsComputer
    Hint for Get-AttributeSeverity classification.
.RETURNS
    PSCustomObject with Primary and Extended arrays, each containing
    @{ Name; Value; Severity } objects.
#>
function Get-OrderedAttributes {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Object,

        [switch]$PromoteNonStandard,

        [bool]$IsComputer = $false
    )

    try {
        # Detect object type
        $objectType = Get-ObjectTypeForOrdering -Object $Object

    # Get primary attributes for this type
    $primaryAttrNames = $Script:PrimaryAttributes[$objectType]
    if (-not $primaryAttrNames) {
        $primaryAttrNames = $Script:PrimaryAttributes['User']  # Fallback
    }

    $result = [PSCustomObject]@{
        ObjectType = $objectType
        Primary = [System.Collections.ArrayList]@()
        Extended = [System.Collections.ArrayList]@()
    }

    $processedAttrs = @{}

    # 1. Process defined primary attributes in order
    # Attributes that should be rendered even when empty - their absence carries meaning
    # (e.g. an unlinked GPO is a security-relevant fact that users will miss if the row is suppressed).
    $alwaysShowEmpty = @('LinkedOUs')

    foreach ($attrName in $primaryAttrNames) {
        $value = $Object.$attrName
        $isEmpty = ($null -eq $value) -or ($value -isnot [bool] -and $value -eq '')
        if (-not $isEmpty -or ($attrName -in $alwaysShowEmpty -and $Object.PSObject.Properties[$attrName])) {
            $severity = Get-AttributeSeverity -Name $attrName -Value $value -IsComputer $IsComputer -SourceObject $Object
            [void]$result.Primary.Add(@{
                Name = $attrName
                Value = $value
                Severity = $severity
            })
            $processedAttrs[$attrName] = $true
        }
    }

    # 2. Process remaining attributes
    # Skip entirely for strict types (only PrimaryAttributes are shown)
    $isStrictType = $objectType -in $Script:StrictAttributeTypes
    if ($isStrictType) {
        return $result
    }

    foreach ($prop in $Object.PSObject.Properties) {
        # Skip already processed
        if ($processedAttrs.ContainsKey($prop.Name)) { continue }

        # Skip excluded attributes
        if ($prop.Name -in $Script:ExcludeAttributes) { continue }

        # Skip null/empty (but keep boolean $false, and keep AlwaysShow attributes whose
        # absence is itself meaningful - e.g. unlinked GPO LinkedOUs).
        $isEmptyValue = ($null -eq $prop.Value) -or ($prop.Value -isnot [bool] -and $prop.Value -eq '')
        if ($isEmptyValue -and $prop.Name -notin $alwaysShowEmpty) { continue }

        $severity = Get-AttributeSeverity -Name $prop.Name -Value $prop.Value -IsComputer $IsComputer -SourceObject $Object

        # Special handling for Owner: Determine severity based on default owner status
        # Non-default owners are a security risk (owner has implicit full control)
        if ($prop.Name -ieq 'Owner') {
            $ownerSID = $Object.OwnerSID
            if ($ownerSID) {
                $isDefaultOwner = Test-IsDefaultOwner -SID $ownerSID
                if ($isDefaultOwner) {
                    # Default owner - Standard severity, goes to Extended
                    $severity = 'Standard'
                } else {
                    # Non-default owner - Finding severity (red), will be promoted if PromoteNonStandard is set
                    $severity = 'Finding'
                }
            }
        }

        $attrInfo = @{
            Name = $prop.Name
            Value = $prop.Value
            Severity = $severity
        }

        # Promote to primary if non-Standard severity and switch is set
        if ($PromoteNonStandard -and $severity -ne 'Standard') {
            [void]$result.Primary.Add($attrInfo)
        } else {
            [void]$result.Extended.Add($attrInfo)
        }
    }

    return $result

    } catch {
        # On any error, return empty result with User type
        # Surface as warning so silent breakage (e.g. invalid transformer call) is visible.
        Write-Warning "[Get-OrderedAttributes] Error processing attributes: $_"
        return [PSCustomObject]@{
            ObjectType = 'User'
            Primary = [System.Collections.ArrayList]@()
            Extended = [System.Collections.ArrayList]@()
        }
    }
}



# ----- Get-RenderModel.ps1 -----

<#
.SYNOPSIS
    Central RenderModel builder for adPEAS output.

.DESCRIPTION
    Produces a unified RenderModel that both Console and HTML renderers consume.
    This is the SINGLE SOURCE OF TRUTH for:
    - Which attributes are shown (via Get-OrderedAttributes / PrimaryAttributes)
    - What severity each attribute has (via Get-TriggerMatch)
    - What tooltip each value gets (via Get-TriggerMatch FindingId)
    - How values are transformed (via AttributeTransformers)

    The RenderModel architecture provides a single pipeline where attribute selection,
    severity, and formatting are determined once, then consumed by both
    Render-ConsoleObject.ps1 (console) and Render-HtmlObject.ps1 (HTML).

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Requires: adPEAS-AttributeOrder.ps1, adPEAS-FindingDefinitions.ps1, AttributeTransformers.ps1
#>

# ============================================================================
# Transformer Registry
# Maps attribute names to transformer functions.
# Attributes not in this registry use the default transformer.
# Populated by AttributeTransformers.ps1 after it loads.
# ============================================================================
$Script:AttributeTransformers = @{}

# ============================================================================
# Factory Functions
# ============================================================================

<#
.SYNOPSIS
    Creates a new RenderValue object.
.PARAMETER Display
    The display text for this value (resolved name, formatted string, etc.)
.PARAMETER Severity
    Per-value severity: Finding, Hint, Secure, Note, or Standard.
.PARAMETER FindingId
    Optional FindingDefinition ID for HTML tooltip.
.PARAMETER RawValue
    The original unprocessed value.
.PARAMETER Metadata
    Optional hashtable with extra info (SID, DN, etc.)
#>
function New-RenderValue {
    [CmdletBinding()]
    param(
        # AllowEmptyString: a blank display value must never abort rendering. Mandatory [string]
        # otherwise rejects '' and the exception propagates out of Show-Object, so a single
        # attribute with a blank line silently costs the caller the whole object.
        [Parameter(Mandatory=$true)]
        [AllowEmptyString()]
        [string]$Display,

        [Parameter(Mandatory=$false)]
        [string]$Severity = 'Standard',

        [Parameter(Mandatory=$false)]
        [string]$FindingId = $null,

        [Parameter(Mandatory=$false)]
        $RawValue = $null,

        [Parameter(Mandatory=$false)]
        [hashtable]$Metadata = @{}
    )

    [PSCustomObject]@{
        PSTypeName = 'adPEAS.RenderValue'
        Display    = $Display
        Severity   = $Severity
        FindingId  = $FindingId
        RawValue   = $RawValue
        Metadata   = $Metadata
    }
}

<#
.SYNOPSIS
    Creates a new RenderRow object.
.PARAMETER Name
    Display name for the attribute.
.PARAMETER RawName
    Original attribute name.
.PARAMETER RowType
    SingleValue, MultiValue, Image, or Hash.
.PARAMETER OverallSeverity
    Aggregate severity for the attribute label.
.PARAMETER FindingId
    Optional row-level FindingId.
.PARAMETER Values
    Array of RenderValue objects.
.PARAMETER ForceAttributeClass
    Whether to force attribute name coloring even if all values are Standard.
#>
function New-RenderRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Name,

        [Parameter(Mandatory=$false)]
        [string]$RawName = $Name,

        [Parameter(Mandatory=$false)]
        [string]$RowType = 'SingleValue',

        [Parameter(Mandatory=$false)]
        [string]$OverallSeverity = 'Standard',

        [Parameter(Mandatory=$false)]
        [string]$FindingId = $null,

        [Parameter(Mandatory=$false)]
        [array]$Values = @(),

        [Parameter(Mandatory=$false)]
        [bool]$ForceAttributeClass = $false
    )

    [PSCustomObject]@{
        PSTypeName         = 'adPEAS.RenderRow'
        Name               = $Name
        RawName            = $RawName
        RowType            = $RowType
        OverallSeverity    = $OverallSeverity
        FindingId          = $FindingId
        Values             = $Values
        ForceAttributeClass = $ForceAttributeClass
    }
}

# ============================================================================
# Default Transformer
# ============================================================================

<#
.SYNOPSIS
    Default transformer for attributes without a registered custom transformer.
.DESCRIPTION
    Determines severity and FindingId via Get-TriggerMatch,
    and handles common value types (scalar, array, multi-line string, ImageData).
#>
function Convert-DefaultToRenderValues {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Name,

        [Parameter(Mandatory=$true)]
        $Value,

        [Parameter(Mandatory=$true)]
        $Context
    )

    # Handle ImageData objects (thumbnailPhoto, jpegPhoto)
    if ($Value -is [PSCustomObject] -and ($Value.psobject.TypeNames -contains 'adPEAS.ImageData')) {
        return @{
            RowType         = 'Image'
            OverallSeverity = 'Standard'
            ForceAttributeClass = $false
            Values          = @(
                New-RenderValue -Display $Value.DisplayText -Severity 'Standard' -RawValue $Value
            )
        }
    }

    # Handle multi-line strings (e.g., siteIPSubnets, domainControllers)
    if ($Value -is [string] -and $Value -match "`n") {
        $lines = $Value -split "`n"
        $renderValues = @()
        foreach ($line in $lines) {
            # Blank lines carry no information and would render as empty rows. AD free-text
            # attributes (description, info) routinely contain them and trailing newlines.
            $line = $line.TrimEnd("`r")
            if ([string]::IsNullOrWhiteSpace($line)) { continue }
            $lineMatch = Get-TriggerMatch -Name $Name -Value $line -IsComputer $Context.IsComputer -SourceObject $Context.SourceObject
            $renderValues += New-RenderValue -Display $line -Severity $lineMatch.Severity -FindingId $lineMatch.FindingId -RawValue $line
        }
        if ($renderValues.Count -eq 0) { return $null }
        $maxSev = Get-MaxSeverityFromValues -Values $renderValues
        return @{
            RowType         = 'MultiValue'
            OverallSeverity = $maxSev
            ForceAttributeClass = ($maxSev -ne 'Standard')
            Values          = $renderValues
        }
    }

    # Handle arrays
    if ($Value -is [array]) {
        # Check if array contains objects with DisplayText (e.g., privilegedGroups structured format)
        $firstItem = $Value | Select-Object -First 1
        if ($firstItem -is [PSCustomObject] -and $firstItem.PSObject.Properties['DisplayText']) {
            # Array of objects with DisplayText - use DisplayText for display
            $renderValues = @()
            foreach ($item in $Value) {
                $itemDisplay = [string]$item.DisplayText
                if ([string]::IsNullOrEmpty($itemDisplay)) { continue }
                $itemMatch = Get-TriggerMatch -Name $Name -Value $item -IsComputer $Context.IsComputer -SourceObject $Context.SourceObject
                $renderValues += New-RenderValue -Display $itemDisplay -Severity $itemMatch.Severity -FindingId $itemMatch.FindingId -RawValue $item
            }
            if ($renderValues.Count -eq 0) { return $null }
            $maxSev = Get-MaxSeverityFromValues -Values $renderValues
            return @{
                RowType         = 'MultiValue'
                OverallSeverity = $maxSev
                ForceAttributeClass = ($maxSev -ne 'Standard')
                Values          = $renderValues
            }
        }

        # Check if array contains LinkedOUs objects (from Get-GPOLinkage)
        if ($firstItem -is [PSCustomObject] -and $firstItem.PSObject.Properties['DistinguishedName'] -and $firstItem.PSObject.Properties['Scope']) {
            # Display full DistinguishedName with LinkStatus for clarity
            $renderValues = @()
            foreach ($item in $Value) {
                $ouDisplay = $item.DistinguishedName
                if ([string]::IsNullOrWhiteSpace($ouDisplay)) { continue }

                # Append LinkStatus if not standard Enabled (show Disabled/Enforced explicitly)
                if ($item.LinkStatus -and $item.LinkStatus -ne 'Enabled') {
                    $ouDisplay = "$ouDisplay ($($item.LinkStatus))"
                }

                # Check each OU individually for trigger matches (e.g., domain-level GPO links)
                $itemMatch = Get-TriggerMatch -Name $Name -Value $item.DistinguishedName -IsComputer $Context.IsComputer -SourceObject $Context.SourceObject
                $renderValues += New-RenderValue -Display $ouDisplay -Severity $itemMatch.Severity -FindingId $itemMatch.FindingId -RawValue $item
            }
            if ($renderValues.Count -eq 0) { return $null }
            $maxSev = Get-MaxSeverityFromValues -Values $renderValues
            return @{
                RowType         = 'MultiValue'
                OverallSeverity = $maxSev
                ForceAttributeClass = ($maxSev -ne 'Standard')
                Values          = $renderValues
            }
        }

        # Simple array of strings - render as MultiValue (one line per item)
        # Skip empty arrays (e.g., LinkedOUs = @() on GPO tasks)
        if ($Value.Count -eq 0) { return $null }
        $renderValues = @()
        foreach ($item in $Value) {
            $itemStr = [string]$item
            if ([string]::IsNullOrEmpty($itemStr)) { continue }
            $itemMatch = Get-TriggerMatch -Name $Name -Value $itemStr -IsComputer $Context.IsComputer -SourceObject $Context.SourceObject
            $renderValues += New-RenderValue -Display $itemStr -Severity $itemMatch.Severity -FindingId $itemMatch.FindingId -RawValue $item
        }
        if ($renderValues.Count -eq 0) { return $null }
        $maxSev = Get-MaxSeverityFromValues -Values $renderValues
        return @{
            RowType         = 'MultiValue'
            OverallSeverity = $maxSev
            ForceAttributeClass = ($maxSev -ne 'Standard')
            Values          = $renderValues
        }
    }

    # Simple scalar value
    $displayValue = [string]$Value
    # Skip empty scalar values that slipped through the filter
    if ([string]::IsNullOrEmpty($displayValue)) { return $null }
    # Pass original $Value (not $displayValue) so typed objects (DateTime, Int64) are preserved
    # for Custom triggers like pwdAge_gt_1825 that need Get-DateFromValue to work correctly
    $scalarMatch = Get-TriggerMatch -Name $Name -Value $Value -IsComputer $Context.IsComputer -SourceObject $Context.SourceObject
    return @{
        RowType         = 'SingleValue'
        OverallSeverity = $scalarMatch.Severity
        ForceAttributeClass = $false
        Values          = @(
            New-RenderValue -Display $displayValue -Severity $scalarMatch.Severity -FindingId $scalarMatch.FindingId -RawValue $Value
        )
    }
}

# ============================================================================
# Helper Functions
# ============================================================================

<#
.SYNOPSIS
    Gets the maximum severity from an array of RenderValue objects.
#>
function Get-MaxSeverityFromValues {
    [CmdletBinding()]
    param([array]$Values)

    $priority = @{ 'Finding' = 4; 'Secure' = 3; 'Hint' = 2; 'Note' = 1; 'Standard' = 0 }
    $maxPriority = 0
    $maxSeverity = 'Standard'

    foreach ($v in $Values) {
        $p = $priority[$v.Severity]
        if ($null -ne $p -and $p -gt $maxPriority) {
            $maxPriority = $p
            $maxSeverity = $v.Severity
            if ($maxSeverity -eq 'Finding') { return 'Finding' }
        }
    }
    return $maxSeverity
}

<#
.SYNOPSIS
    Builds a RenderRow from a transformer result hashtable.
#>
function Build-RenderRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Name,

        [Parameter(Mandatory=$true)]
        [hashtable]$TransformResult
    )

    # Use custom display name if provided, otherwise use raw name
    $displayName = if ($TransformResult.DisplayName) { $TransformResult.DisplayName } else { $Name }

    # Row-level FindingId: if single value with FindingId, promote to row level
    $rowFindingId = $TransformResult.FindingId
    if (-not $rowFindingId -and $TransformResult.Values.Count -eq 1 -and $TransformResult.Values[0].FindingId) {
        $rowFindingId = $TransformResult.Values[0].FindingId
    }

    New-RenderRow -Name $displayName `
                  -RawName $Name `
                  -RowType ($TransformResult.RowType) `
                  -OverallSeverity ($TransformResult.OverallSeverity) `
                  -FindingId $rowFindingId `
                  -Values ($TransformResult.Values) `
                  -ForceAttributeClass ([bool]$TransformResult.ForceAttributeClass)
}

# ============================================================================
# Object Type Detection and Activity Status (used by Get-RenderModel)
# ============================================================================

<#
.SYNOPSIS
    Detects if an object is a Computer account.
.PARAMETER Object
    The object to check.
.RETURNS
    $true if the object is a Computer, $false otherwise.
#>
function Test-IsComputerObject {
    param($Object)

    return (($Object.objectClass -contains "computer") -or ($Object.sAMAccountName -like '*$'))
}

<#
.SYNOPSIS
    Converts an AD timestamp value to a DateTime.
.DESCRIPTION
    Handles the timestamp representations that occur on AD objects:
    - DateTime objects (pass through)
    - FileTime integers (lastLogonTimestamp, pwdLastSet)
    - FileTime as string
    - Generalized Time strings (whenCreated, e.g. "20180101000000.0Z")
    - Generic DateTime strings (fallback)
    Returns $null for "never" / unset values (0, Int64.MaxValue) or on failure.
.PARAMETER Value
    The raw timestamp value (may be wrapped in a single-element array).
#>
function ConvertTo-ActivityDate {
    param($Value)

    if ($null -eq $Value) { return $null }
    if ($Value -is [array]) {
        if ($Value.Count -eq 0) { return $null }
        $Value = $Value[0]
    }

    if ($Value -is [DateTime]) { return $Value }

    if ($Value -is [long] -or $Value -is [int]) {
        if ($Value -le 0 -or $Value -eq 9223372036854775807) { return $null }
        try { return [DateTime]::FromFileTime([long]$Value) } catch { return $null }
    }

    if ($Value -is [string]) {
        # FileTime stored as string
        $parsed = 0L
        if ([long]::TryParse($Value, [ref]$parsed)) {
            if ($parsed -le 0 -or $parsed -eq 9223372036854775807) { return $null }
            try { return [DateTime]::FromFileTime($parsed) } catch { return $null }
        }

        # Generalized Time (e.g. "20180101000000.0Z" / "20180101000000Z")
        if ($Value -match '^(\d{14})') {
            $gtDate = [DateTime]::MinValue
            if ([DateTime]::TryParseExact($Matches[1], 'yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal, [ref]$gtDate)) {
                return $gtDate.ToLocalTime()
            }
        }

        # Generic DateTime string
        $parsedDate = [DateTime]::MinValue
        if ([DateTime]::TryParse($Value, [ref]$parsedDate)) {
            return $parsedDate
        }
    }

    return $null
}

<#
.SYNOPSIS
    Adds activity status to an object based on logon / password / creation age.
.DESCRIPTION
    Determines whether an account is inactive and, if so, adds an activityStatus
    property (rendered as a Hint). Uses $Script:DefaultInactiveDays by default.

    Detection logic:
    - lastLogonTimestamp present  -> inactive if older than the threshold
    - lastLogonTimestamp missing  -> fall back to pwdLastSet (machine accounts
      rotate their password ~every 30 days, so a stale pwdLastSet means the host
      is effectively dead even though it never recorded a replicated logon).
      If the password was never set either, the account is flagged as
      "never logged on" only when whenCreated proves it is old enough - this
      guards against false positives on freshly created / not-yet-replicated
      accounts.
.PARAMETER Object
    The object to check and potentially modify.
.PARAMETER InactiveDays
    Number of days without login to consider inactive.
    Default: Uses $Script:DefaultInactiveDays (typically 90 days) set by Invoke-adPEAS.
#>
function Add-ActivityStatus {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Object,

        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 0  # 0 = use $Script:DefaultInactiveDays
    )

    # Skip if already classified
    if ($Object.activityStatus) {
        return
    }

    # Only user / computer accounts have a meaningful logon history. Groups,
    # GPOs, OUs, certificate templates, etc. carry whenCreated but never log
    # on, so the whenCreated fallback below would otherwise mark every
    # long-lived group as "INACTIVE (never logged on)".
    $objectClasses = @($Object.objectClass)
    $isAccountObject = ($objectClasses -contains 'user') -or
                       ($objectClasses -contains 'computer') -or
                       ($Object.sAMAccountName -like '*$')
    if (-not $isAccountObject) {
        return
    }

    # Resolve InactiveDays from global constant if not explicitly set
    $effectiveInactiveDays = if ($InactiveDays -gt 0) {
        $InactiveDays
    } elseif ($Script:DefaultInactiveDays) {
        $Script:DefaultInactiveDays
    } else {
        90  # Fallback if global not set
    }

    $cutoffDate = (Get-Date).AddDays(-$effectiveInactiveDays)
    $lastLogonDate = ConvertTo-ActivityDate -Value $Object.lastLogonTimestamp

    if ($lastLogonDate) {
        # Primary signal: a replicated logon timestamp exists
        if ($lastLogonDate -lt $cutoffDate) {
            $Object | Add-Member -NotePropertyName 'activityStatus' -NotePropertyValue "INACTIVE (no login for >$effectiveInactiveDays days)" -Force
        }
        return
    }

    # No lastLogonTimestamp - fall back to secondary signals so old/dead
    # accounts are not silently rendered as if they were alive.
    $pwdLastSetDate = ConvertTo-ActivityDate -Value $Object.pwdLastSet

    if ($pwdLastSetDate) {
        if ($pwdLastSetDate -lt $cutoffDate) {
            $Object | Add-Member -NotePropertyName 'activityStatus' -NotePropertyValue "INACTIVE (no logon recorded, password not changed for >$effectiveInactiveDays days)" -Force
        }
        # Recent password change -> live host whose lastLogonTimestamp simply
        # has not replicated yet. Do not flag (avoids false positives).
        return
    }

    # Password was never set either. Only flag as "never logged on" when
    # whenCreated proves the account is older than the threshold; otherwise it
    # may be a brand-new / not-yet-replicated account.
    $createdDate = ConvertTo-ActivityDate -Value $Object.whenCreated
    if ($createdDate -and $createdDate -lt $cutoffDate) {
        $Object | Add-Member -NotePropertyName 'activityStatus' -NotePropertyValue "INACTIVE (never logged on, account created >$effectiveInactiveDays days ago)" -Force
    }
}

# ============================================================================
# Main Function: Get-RenderModel
# ============================================================================

<#
.SYNOPSIS
    Builds a unified RenderModel from an AD object.
.DESCRIPTION
    Central function that produces a RenderModel consumed by both Console and HTML
    renderers. Determines attribute selection (via Get-OrderedAttributes), severity
    (via Get-TriggerMatch), and transformations (via AttributeTransformers).

    This function is the SINGLE SOURCE OF TRUTH for all output decisions.
.PARAMETER Object
    The AD object or PSCustomObject to render.
.RETURNS
    A PSCustomObject with ObjectType, IsComputer, Primary, Extended, and PostObject arrays.
#>
function Get-RenderModel {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Object
    )

    # 1. Detect object type and computer status
    $objectType = Get-ObjectTypeForOrdering -Object $Object
    $isComputer = Test-IsComputerObject -Object $Object

    # 2. Enrich object with activity status if inactive (mutates input object)
    Add-ActivityStatus -Object $Object

    # 3. Build context for transformers
    $context = [PSCustomObject]@{
        IsComputer              = $isComputer
        IsExchangeGroup         = [bool]$Object._isExchangeGroup
        DangerousRightsSeverity = $Object.dangerousRightsSeverity
        CredentialType          = $Object.credentialType
        OwnerSID                = $Object.OwnerSID
        ObjectType              = $objectType
        SourceObject            = $Object
    }

    # 4. Get ordered attribute lists (Primary/Extended)
    $orderedAttrs = Get-OrderedAttributes -Object $Object -PromoteNonStandard -IsComputer $isComputer

    # 5. Transform each attribute into RenderRows
    $primaryRows = [System.Collections.ArrayList]@()
    $extendedRows = [System.Collections.ArrayList]@()
    $postObjectRows = [System.Collections.ArrayList]@()

    # Track attributes for PostObject (rendered after the card in console)
    $postObjectAttributes = @('KerberoastingHash', 'ASREPRoastingHash')

    foreach ($section in @(
        @{ Source = $orderedAttrs.Primary; Target = 'Primary' },
        @{ Source = $orderedAttrs.Extended; Target = 'Extended' }
    )) {
        foreach ($attrInfo in $section.Source) {
            $name = $attrInfo.Name
            $value = $attrInfo.Value

            # Route PostObject attributes (roasting hashes)
            $isPostObject = $name -in $postObjectAttributes

            # Look up transformer or use default
            $transformer = $Script:AttributeTransformers[$name]
            if ($transformer) {
                $result = & $transformer -Name $name -Value $value -Context $context
            } else {
                $result = Convert-DefaultToRenderValues -Name $name -Value $value -Context $context
            }

            # Skip if transformer returns $null (e.g., Owner that IS default)
            if ($null -eq $result) { continue }

            $row = Build-RenderRow -Name $name -TransformResult $result

            if ($isPostObject) {
                [void]$postObjectRows.Add($row)
            } elseif ($section.Target -eq 'Primary') {
                [void]$primaryRows.Add($row)
            } else {
                [void]$extendedRows.Add($row)
            }
        }
    }

    # 6. Return the model
    [PSCustomObject]@{
        PSTypeName  = 'adPEAS.RenderModel'
        ObjectType  = $objectType
        IsComputer  = $isComputer
        Primary     = $primaryRows.ToArray()
        Extended    = $extendedRows.ToArray()
        PostObject  = $postObjectRows.ToArray()
    }
}



