        Triggers = @(
            @{ Attribute = 'LinkedOUs'; Pattern = '^Not linked'; Severity = 'Hint' }
        )
    }

    # Hardcoded scriptPath (UNC or absolute local path)
    'SCRIPTPATH_HARDCODED' = @{
        Title = "Hardcoded Logon Script Path"
        Risk = "Hint"
        BaseScore = 30
        Description = "This user account has a scriptPath attribute pointing to a UNC path (e.g., \\server\share\script.bat) or an absolute local path (e.g., C:\scripts\logon.bat) instead of a relative path resolved via NETLOGON. This is unusual and may indicate persistence, backdoor activity, or a misconfiguration that could be exploited for code execution."
        Impact = @(
            "UNC paths can point to attacker-controlled SMB servers, enabling code execution on user logon"
            "Absolute local paths bypass NETLOGON share protections and GPO-based script management"
            "Logon scripts execute with the user's privileges - privileged accounts amplify the risk"
            "An attacker who can modify scriptPath can achieve persistence without touching NETLOGON"
        )
        Attack = @(
            "1. Attacker modifies scriptPath to point to an attacker-controlled UNC share (\\evil\share\payload.bat)"
            "2. User logs on and Windows executes the script from the UNC path"
            "3. Attacker gains code execution in the user's security context"
            "4. If the user is privileged, the attacker escalates privileges"
        )
        Remediation = @(
            "Use only relative paths in scriptPath that resolve via the NETLOGON share"
            "Prefer Group Policy-based logon scripts over per-user scriptPath settings"
            "Monitor scriptPath changes, especially to UNC or absolute paths"
            "Audit who has WriteProperty permissions on scriptPath in affected OUs"
        )
        References = @(
            @{ Title = "Boot or Logon Initialization Scripts - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1037/001/" }
            @{ Title = "scriptPath Attribute - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-scriptpath" }
        )
        Tools = @("PowerView", "BloodHound", "ADExplorer")
        MITRE = "T1037.001"
        Triggers = @(
            @{ Attribute = 'scriptPath'; Custom = 'is_hardcoded_path'; Severity = 'Hint' }
        )
    }

    # UAC flags with DC context
    'UAC_SEVERITY_OVERRIDE' = @{
        Title = "User Account Control Severity Classification"
        Risk = "Finding"
        BaseScore = 0
        Description = "UAC flag severity classification with DC context awareness."
        Triggers = @(
            # DONT_REQ_PREAUTH and ENCRYPTED_TEXT always Finding
            @{ Attribute = 'userAccountControl'; Pattern = 'DONT_REQ_PREAUTH|ENCRYPTED_TEXT_PWD_ALLOWED'; Severity = 'Finding'; SeverityOnly = $true }
            # TRUSTED_FOR_DELEGATION on DC = Hint (expected)
            @{ Attribute = 'userAccountControl'; Pattern = 'TRUSTED_FOR_DELEGATION'; Custom = 'is_dc_uac'; Severity = 'Hint'; SeverityOnly = $true }
            # TRUSTED_FOR_DELEGATION on non-DC = Finding
            @{ Attribute = 'userAccountControl'; Pattern = 'TRUSTED_FOR_DELEGATION'; Severity = 'Finding'; SeverityOnly = $true }
            # Noteworthy flags = Hint
            @{ Attribute = 'userAccountControl'; Pattern = 'PASSWD_NOTREQD|DONT_EXPIRE_PASSWORD|INTERDOMAIN_TRUST_ACCOUNT'; Severity = 'Hint'; SeverityOnly = $true }
            # Secure flags
            @{ Attribute = 'userAccountControl'; Pattern = 'ACCOUNTDISABLE|SMARTCARD_REQUIRED|NOT_DELEGATED'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }
}

<#
.SYNOPSIS
    Exports finding definitions as JSON for embedding in HTML.
.PARAMETER Minified
    If set, outputs minified JSON without indentation.
.RETURNS
    JSON string of all finding definitions.
#>
function Export-FindingDefinitionsJson {
    [CmdletBinding()]
    param(
        [switch]$Minified
    )

    # Convert hashtable to format suitable for JSON
    $jsonObject = @{}

    foreach ($key in $Script:FindingDefinitions.Keys) {
        $def = $Script:FindingDefinitions[$key]

        # Convert References array of hashtables to array of objects
        $refs = [System.Collections.Generic.List[object]]::new()
        if ($def.References) {
            foreach ($ref in $def.References) {
                $refs.Add(@{ title = $ref.Title; url = $ref.Url })
            }
        }

        # Convert Tools - support both old string format and new object format
        $tools = [System.Collections.Generic.List[object]]::new()
        if ($def.Tools) {
            foreach ($tool in $def.Tools) {
                if ($tool -is [hashtable] -or $tool -is [System.Collections.Specialized.OrderedDictionary]) {
                    $tools.Add(@{ name = $tool.Name; url = $tool.Url })
                } else {
                    # String format - resolve URL from central repository
                    $toolUrl = $Script:ToolUrls[$tool]
                    $tools.Add(@{ name = [string]$tool; url = $toolUrl })
                }
            }
        }

        # Convert RemediationCommands array of hashtables to array of objects
        $remediationCmds = [System.Collections.Generic.List[object]]::new()
        if ($def.RemediationCommands) {
            foreach ($cmd in $def.RemediationCommands) {
                $remediationCmds.Add(@{ description = $cmd.Description; command = $cmd.Command })
            }
        }

        $jsonObject[$key] = @{
            title = $def.Title
            risk = $def.Risk
            baseScore = $def.BaseScore
            description = $def.Description
            impact = $def.Impact
            attack = $def.Attack
            remediation = $def.Remediation
            remediationCommands = $remediationCmds.ToArray()
            references = $refs.ToArray()
            tools = $tools.ToArray()
            mitre = $def.MITRE
        }
    }

    if ($Minified) {
        return ($jsonObject | ConvertTo-Json -Depth 10 -Compress)
    } else {
        return ($jsonObject | ConvertTo-Json -Depth 10)
    }
}

# =============================================================================
# BUILD INVERTED INDEX for fast attribute -> FindingId + Severity lookup
# =============================================================================
# Reads Triggers from each FindingDefinition and builds an inverted index.
# Used by Get-FindingIdForAttribute (tooltip lookup) and Get-SeverityFromTrigger (severity).
#
# Structure: $Script:FindingTriggerIndex['attributeName'] = @(
#   @{ FindingId = 'XXX'; Pattern = 'regex'; ExcludePattern = 'regex'; Context = 'ctx';
#      Custom = 'func'; Severity = 'Hint'; ParentRisk = 'Finding' }
# )
#
# Severity resolution order:
#   1. Trigger.Severity (explicit per-trigger override, e.g. "Hint" for Optional values)
#   2. FindingDefinition.Risk (parent definition risk level, e.g. "Finding")

$Script:FindingTriggerIndex = @{}
$triggerLists = @{}  # Temporary List<object> per attribute for O(1) append

foreach ($findingId in $Script:FindingDefinitions.Keys) {
    $definition = $Script:FindingDefinitions[$findingId]

    # Skip if no Triggers defined
    if (-not $definition.ContainsKey('Triggers') -or $null -eq $definition.Triggers) {
        continue
    }

    foreach ($trigger in $definition.Triggers) {
        if (-not $trigger.Attribute) { continue }

        $attrName = $trigger.Attribute.ToLower()

        if (-not $triggerLists.ContainsKey($attrName)) {
            $triggerLists[$attrName] = [System.Collections.Generic.List[object]]::new()
        }

        $triggerLists[$attrName].Add(@{
            FindingId      = $findingId
            Pattern        = $trigger.Pattern
            ExcludePattern = $trigger.ExcludePattern
            Context        = $trigger.Context
            Custom         = $trigger.Custom
            Severity       = $trigger.Severity      # Optional: per-trigger severity override
            SeverityOnly   = $trigger.SeverityOnly   # If $true, Get-FindingIdForAttribute skips this
            ParentRisk     = $definition.Risk        # Parent definition risk level
        })
    }
}

# Convert Lists to arrays for the final index (arrays are faster to iterate)
foreach ($key in $triggerLists.Keys) {
    $Script:FindingTriggerIndex[$key] = $triggerLists[$key].ToArray()
}
Remove-Variable -Name triggerLists -ErrorAction SilentlyContinue

<#
.SYNOPSIS
    Maps attribute names/values to finding definition IDs for tooltip display.
.DESCRIPTION
    Thin wrapper around Get-TriggerMatch that returns only the FindingId.
    Returns $null if no tooltip should be shown.
.PARAMETER Name
    The attribute name (e.g., 'servicePrincipalName', 'userAccountControl').
.PARAMETER Value
    The attribute value to check against patterns.
.PARAMETER Context
    Optional context string for context-specific triggers.
.RETURNS
    FindingId string or $null.
#>
function Get-FindingIdForAttribute {
    [CmdletBinding()]
    param(
        [string]$Name,
        $Value,
        [string]$Context = $null
    )

    $match = Get-TriggerMatch -Name $Name -Value $Value -Context $Context
    return $match.FindingId
}

<#
.SYNOPSIS
    Determines attribute severity from FindingDefinitions triggers.
.DESCRIPTION
    Thin wrapper around Get-TriggerMatch that returns only the Severity.
    Returns $null if no trigger matches (caller should use "Standard" as fallback).
.PARAMETER Name
    The attribute name (e.g., 'LDAPSigning', 'servicePrincipalName').
.PARAMETER Value
    The attribute value to check against patterns.
.PARAMETER IsComputer
    Set to $true if the source object is a computer account.
.PARAMETER SourceObject
    Optional. The source AD object for context-aware triggers.
.PARAMETER Context
    Optional context string for context-specific triggers.
.RETURNS
    Severity string ("Finding", "Hint", "Secure", "Note") or $null if no trigger matches.
#>
function Get-SeverityFromTrigger {
    [CmdletBinding()]
    param(
        [string]$Name,
        $Value,
        [bool]$IsComputer = $false,
        $SourceObject = $null,
        [string]$Context = $null
    )

    $match = Get-TriggerMatch -Name $Name -Value $Value -IsComputer $IsComputer `
        -SourceObject $SourceObject -Context $Context
    $severity = $match.Severity
    if ($severity -eq 'Standard') { return $null }
    return $severity
}

<#
.SYNOPSIS
    Combined severity and FindingId lookup in a single pass.
.DESCRIPTION
    Returns both severity and FindingId for an attribute value from FindingDefinitions.
    Eliminates the need for separate Get-AttributeSeverity + Get-FindingIdForAttribute calls.

    The function performs two lookups:
    1. Severity: Via two-pass evaluation (SeverityOnly triggers first, then normal triggers)
    2. FindingId: Via normal triggers only (SeverityOnly triggers are excluded)

    When both are found in the same trigger match, only one index lookup is needed.
.PARAMETER Name
    The attribute name.
.PARAMETER Value
    The attribute value.
.PARAMETER IsComputer
    Whether the source object is a computer account.
.PARAMETER SourceObject
    The source AD object for context-aware triggers.
.PARAMETER Context
    Optional context string for context-specific triggers.
.RETURNS
    PSCustomObject with Severity (string or "Standard") and FindingId (string or $null).
    Returns $null if attribute has no triggers at all.
#>
function Get-TriggerMatch {
    [CmdletBinding()]
    param(
        [string]$Name,
        $Value,
        [bool]$IsComputer = $false,
        $SourceObject = $null,
        [string]$Context = $null
    )

    # Default return object for no-match cases
    $noMatch = [PSCustomObject]@{ Severity = 'Standard'; FindingId = $null }

    if ([string]::IsNullOrEmpty($Name)) { return $noMatch }

    # Auto-detect IsComputer from SourceObject via central helper
    if (-not $IsComputer -and $SourceObject) {
        $IsComputer = Test-IsComputerObject -Object $SourceObject
    }

    $attrNameLower = $Name.ToLower()
    $strValue = [string]$Value

    if (-not $Script:FindingTriggerIndex.ContainsKey($attrNameLower)) {
        return $noMatch
    }

    $triggers = $Script:FindingTriggerIndex[$attrNameLower]
    $resultSeverity = $null
    $resultFindingId = $null

    # Pass 1: SeverityOnly triggers (priority for severity)
    # Pass 2: Normal triggers (provide both severity fallback and FindingId)
    foreach ($pass in @($true, $false)) {
        foreach ($trigger in $triggers) {
            $isSeverityOnly = [bool]$trigger.SeverityOnly
            if ($isSeverityOnly -ne $pass) { continue }

            # Check Context requirement
            if ($trigger.Context) {
                if (-not $Context -or $Context -notmatch $trigger.Context) { continue }
            }

            # Check ExcludePattern
            if ($trigger.ExcludePattern) {
                if ($strValue -match $trigger.ExcludePattern) { continue }
            }

            # Determine if trigger matches
            $matched = $false
            if ($trigger.Custom) {
                $customResult = Test-CustomTrigger -CustomType $trigger.Custom -Value $Value `
                    -IsComputer $IsComputer -SourceObject $SourceObject
                if (-not $customResult) { continue }
                if ($trigger.Pattern) {
                    if ($strValue -notmatch $trigger.Pattern) { continue }
                }
                $matched = $true
            } elseif ($trigger.Pattern) {
                if ($strValue -match $trigger.Pattern) { $matched = $true }
            } else {
                $matched = $true
            }

            if (-not $matched) { continue }

            # Extract severity from matched trigger
            if ($null -eq $resultSeverity) {
                $resultSeverity = if ($trigger.Severity) { $trigger.Severity } else { $trigger.ParentRisk }
            }

            # Extract FindingId from non-SeverityOnly triggers
            if ($null -eq $resultFindingId -and -not $isSeverityOnly) {
                $resultFindingId = $trigger.FindingId
            }

            # If we have both, we can stop early
            if ($null -ne $resultSeverity -and $null -ne $resultFindingId) {
                break
            }
        }

        # If we have both after pass 1, skip pass 2
        if ($null -ne $resultSeverity -and $null -ne $resultFindingId) {
            break
        }
    }

    if ($null -eq $resultSeverity -and $null -eq $resultFindingId) {
        return $noMatch
    }

    return [PSCustomObject]@{
        Severity  = if ($resultSeverity) { $resultSeverity } else { 'Standard' }
        FindingId = $resultFindingId
    }
}

<#
.SYNOPSIS
    Evaluates custom trigger conditions.
.DESCRIPTION
    Handles special cases that can't be expressed as simple regex patterns.
    Supports SourceObject for context-aware triggers (SID-based, computer detection).
#>
function Test-CustomTrigger {
    param(
        [string]$CustomType,
        $Value,
        [bool]$IsComputer = $false,
        $SourceObject = $null
    )

    switch ($CustomType) {
        # =====================================================================
        # Context-aware triggers (require SourceObject)
        # =====================================================================

        'ra_signature_gated' {
            # Certificate template only: true when a required enrollment agent co-signature makes
            # the template's enrollment-driven ESC findings a two-step attack instead of a direct
            # one. Used SeverityOnly, so it damps the colour without changing the finding card.
            #
            # Returns $false (no damping, full severity) in three cases:
            #   - no co-signature is required at all
            #   - the template is ESC4-vulnerable: write access lets an attacker drop the
            #     msPKI-RA-Signature requirement before enrolling, so it is no barrier
            #   - an enrollment agent template is enrollable by non-privileged principals, which
            #     makes the co-signature a formality rather than an obstacle
            if (-not $SourceObject) { return $false }

            $raCount = $SourceObject.RASignatureCount
            if ($null -eq $raCount) { return $false }
            $raCountInt = 0
            if (-not [int]::TryParse([string]$raCount, [ref]$raCountInt)) { return $false }
            if ($raCountInt -lt 1) { return $false }

            if ([string]$SourceObject.Vulnerabilities -match 'ESC4') { return $false }
            if ($SourceObject.EnrollmentAgentChainReachable) { return $false }

            return $true
        }

        'is_not_computer' {
            # Returns true if the source object is NOT a computer account
            # Used for servicePrincipalName: SPNs on user accounts = Finding, on computers = expected
            if ($IsComputer) { return $false }
            if ($SourceObject -and (Test-IsComputerObject -Object $SourceObject)) {
                return $false
            }
            return $true
        }

        'is_privileged_sid' {
            # Returns true if the SID belongs to a privileged group/user
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $privResult = Test-IsPrivileged -Identity $sid
            return ($privResult.Category -eq 'Privileged')
        }

        'is_operator_sid' {
            # Returns true if the SID belongs to an operator group
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $privResult = Test-IsPrivileged -Identity $sid
            return ($privResult.Category -eq 'Operator')
        }

        'is_broad_group_sid' {
            # Returns true if the SID is a broad group (Everyone, Authenticated Users, Domain Users)
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { [string]$Value }
            if (-not $sid) { return $false }
            if (Get-Command -Name 'Test-IsBroadGroupSID' -ErrorAction SilentlyContinue) {
                return (Test-IsBroadGroupSID -SID $sid)
            }
            # Fallback: check common broad group SID patterns
            $privResult = Test-IsPrivileged -Identity $sid
            return ($privResult.Category -eq 'BroadGroup')
        }

        'is_not_default_owner' {
            # Returns true if the Owner SID is NOT a default owner (DA, EA, Administrators, SYSTEM)
            if ($SourceObject -and $SourceObject.OwnerSID) {
                $isDefault = Test-IsDefaultOwner -SID $SourceObject.OwnerSID
                return (-not $isDefault)
            }
            return $false
        }

        'is_within_forest_trust' {
            # Returns true if the trust is a within-forest trust (for SID filtering context)
            if ($SourceObject -and $SourceObject.isWithinForest -eq $true) {
                return $true
            }
            return $false
        }

        'is_gpo_finding_object' {
            # Returns true if the GPO object has DangerousPermissions or DangerousSettings
            # Used to prevent Scope/LinkedOUs severity coloring on informational GPO displays
            # (e.g. LDAPConfigGPO, SMBSigningGPO) where domain-wide scope is just context, not a finding
            if (-not $SourceObject) { return $false }
            $hasDangerousPerms = $SourceObject.PSObject.Properties['DangerousPermissions'] -and $SourceObject.DangerousPermissions
            $hasDangerousSettings = $SourceObject.PSObject.Properties['DangerousSettings'] -and $SourceObject.DangerousSettings
            return ($hasDangerousPerms -or $hasDangerousSettings)
        }

        'is_hardcoded_path' {
            # Returns true if scriptPath is a UNC path (\\server\share) or absolute local path (C:\...)
            $strVal = [string]$Value
            if ([string]::IsNullOrWhiteSpace($strVal)) { return $false }
            return ($strVal -match '^\\\\[^\\]+\\' -or $strVal -match '^[A-Za-z]:[\\\/]')
        }

        'is_dc_uac' {
            # Returns true if userAccountControl flags contain SERVER_TRUST_ACCOUNT (Domain Controller)
            # SourceObject contains all UAC flags joined by space (from UAC transformer)
            $allFlags = if ($SourceObject) { [string]$SourceObject } else { [string]$Value }
            return ($allFlags -match 'SERVER_TRUST_ACCOUNT')
        }

        'is_exchange_eol' {
            # Returns true if the Exchange version/build is EOL (not Standard severity)
            # For ExchangeBuildNumber: check build directly
            # For ExchangeVersion: check via SourceObject for build number
            $strValue = [string]$Value
            $severity = 'Standard'
            if ($strValue -match '^\d+\.\d+\.\d+') {
                # Build number format (e.g., 15.2.2562.37)
                $severity = Get-ExchangeSeverity -BuildNumber $strValue
            } elseif ($SourceObject) {
                # ExchangeVersion attribute - check SourceObject for build number
                $buildNum = if ($SourceObject.PSObject.Properties['ExchangeBuildNumber']) { $SourceObject.ExchangeBuildNumber } else { $null }
                if ($buildNum) {
                    $severity = Get-ExchangeSeverity -BuildNumber $buildNum
                } else {
                    $severity = Get-ExchangeSeverity -ProductName $strValue
                }
            } else {
                $severity = Get-ExchangeSeverity -ProductName $strValue
            }
            return ($severity -ne 'Standard')
        }

        'credential_needs_review' {
            # Returns true if the source object has credentialType "(needs review)" (Tier2 pattern)
            if ($SourceObject -and $SourceObject.credentialType -and $SourceObject.credentialType -match '\(needs review\)') {
                return $true
            }
            return $false
        }

        'dangerous_rights_expected' {
            # Returns true if dangerousRightsSeverity indicates expected/privileged permissions
            if ($SourceObject -and $SourceObject.dangerousRightsSeverity) {
                return ($SourceObject.dangerousRightsSeverity -in @('Expected', 'Attention', 'Hint'))
            }
            return $false
        }

        'is_dnsadmins_sid' {
            # Returns true if the SID resolves to DnsAdmins (no fixed RID)
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $resolvedName = ConvertFrom-SID -SID $sid
            return ($resolvedName -match '\\DnsAdmins$')
        }

        'days_over_365' {
            # Integer value > 365 (for daysSinceLastLogon/krbtgtPasswordAge)
            $strValue = [string]$Value
            if ($strValue -match '^(\d+)') {
                return ([int]$Matches[1] -gt 365)
            }
            return $false
        }

        'days_91_to_365' {
            # Integer value in range 91-365 (> 90 and <= 365)
            $strValue = [string]$Value
            if ($strValue -match '^(\d+)') {
                $days = [int]$Matches[1]
                return ($days -gt 90 -and $days -le 365)
            }
            return $false
        }

        'days_181_to_365' {
            # Integer value in range 181-365 (> 180 and <= 365)
            $strValue = [string]$Value
            if ($strValue -match '^(\d+)') {
                $days = [int]$Matches[1]
                return ($days -gt 180 -and $days -le 365)
            }
            return $false
        }

        'lt_8' {
            # Integer value < 8 or "Disabled" (for minimum password length = Finding)
            $strValue = [string]$Value
            if ($strValue -match 'Disabled') { return $true }
            $intValue = 0
            if ([int]::TryParse($strValue, [ref]$intValue)) {
                return ($intValue -lt 8)
            }
            if ($strValue -match '^(\d+)') {
                if ([int]::TryParse($Matches[1], [ref]$intValue)) {
                    return ($intValue -lt 8)
                }
            }
            return $false
        }

        'affected_computers_gt_10' {
            # Integer value > 10
            $intValue = 0
            if ([int]::TryParse([string]$Value, [ref]$intValue)) {
                return ($intValue -gt 10)
            }
            return $false
        }

        'affected_computers_gt_0' {
            # Integer value > 0 but <= 10
            $intValue = 0
            if ([int]::TryParse([string]$Value, [ref]$intValue)) {
                return ($intValue -gt 0 -and $intValue -le 10)
            }
            return $false
        }

        # =====================================================================
        # Existing custom triggers (unchanged)
        # =====================================================================

        'pwdAge_gt_1825' {
            # Password age > 5 years (1825 days)
            $pwdDate = Get-DateFromValue -Value $Value
            if ($pwdDate) {
                $pwdAge = ((Get-Date) - $pwdDate).Days
                return ($pwdAge -gt 1825)
            }
            return $false
        }
        'pwdAge_365_1825' {
            # Password age between 1-5 years
            $pwdDate = Get-DateFromValue -Value $Value
            if ($pwdDate) {
                $pwdAge = ((Get-Date) - $pwdDate).Days
                return ($pwdAge -gt 365 -and $pwdAge -le 1825)
            }
            return $false
        }
        'gt_0' {
            # Integer value > 0
            $intValue = 0
            if ([int]::TryParse([string]$Value, [ref]$intValue)) {
                return ($intValue -gt 0)
            }
            return $false
        }
        'lt_12' {
            # Integer value < 12 (for password length)
            $strValue = [string]$Value
            $intValue = 0
            if ([int]::TryParse($strValue, [ref]$intValue)) {
                return ($intValue -lt 12)
            }
            if ($strValue -match '^(\d+)') {
                if ([int]::TryParse($Matches[1], [ref]$intValue)) {
                    return ($intValue -lt 12)
                }
            }
            return $false
        }
        'lt_10_minutes' {
            # Lockout duration < 10 minutes (extract number from "5 minutes")
            $strValue = [string]$Value
            # Skip "Forever" / "manual unlock" - those are secure
            if ($strValue -match 'Forever|Permanent|manual') {
                return $false
            }
            $intValue = 0
            if ([int]::TryParse($strValue, [ref]$intValue)) {
                return ($intValue -gt 0 -and $intValue -lt 10)
            }
            if ($strValue -match '^(\d+)') {
                if ([int]::TryParse($Matches[1], [ref]$intValue)) {
                    return ($intValue -gt 0 -and $intValue -lt 10)
                }
            }
            return $false
        }
        default {
            return $false
        }
    }
}

<#
.SYNOPSIS
    Converts various date value formats to DateTime.
.DESCRIPTION
    Handles pwdLastSet (FileTime), DateTime objects, and string representations.
#>
function Get-DateFromValue {
    param($Value)

    if ($null -eq $Value) { return $null }

    # Already a DateTime
    if ($Value -is [DateTime]) {
        return $Value
    }

    # FileTime (Int64)
    if ($Value -is [Int64] -or $Value -is [long]) {
        if ($Value -gt 0) {
            try {
                return [DateTime]::FromFileTime($Value)
            } catch {
                return $null
            }
        }
        return $null
    }

    # String representation
    $strValue = [string]$Value
    if ([string]::IsNullOrEmpty($strValue)) { return $null }

    # Try parsing as FileTime
    $longValue = 0
    if ([long]::TryParse($strValue, [ref]$longValue) -and $longValue -gt 0) {
        try {
            return [DateTime]::FromFileTime($longValue)
        } catch {
            # Fall through to DateTime parse
        }
    }

    # Try parsing as DateTime
    $dtValue = [DateTime]::MinValue
    if ([DateTime]::TryParse($strValue, [ref]$dtValue)) {
        return $dtValue
    }

    return $null
}




# ----- AttributeTransformers.ps1 -----

<#
.SYNOPSIS
    Attribute transformer functions for the RenderModel pipeline.

.DESCRIPTION
    Contains all transformer functions that convert raw AD attribute values into RenderValue arrays with severity, FindingId, and display text.
    Each transformer is registered in $Script:AttributeTransformers and called by Get-RenderModel when processing the corresponding attribute.
    Attributes without a registered transformer use Convert-DefaultToRenderValues
    (defined in Get-RenderModel.ps1).

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Requires: Get-RenderModel.ps1, adPEAS-FindingDefinitions.ps1
#>

# ============================================================================
# Helper Functions
# ============================================================================

<#
.SYNOPSIS
    Determines the severity class for an attribute value.
.DESCRIPTION
    Delegates to Get-SeverityFromTrigger which evaluates FindingDefinition triggers.
    Auto-detects computer accounts from SourceObject for context-aware classification.

    Severity Classes:
    - "Finding"  : Security vulnerability (red)
    - "Hint"     : Interesting/noteworthy (yellow)
    - "Note"     : General information (green)
    - "Secure"   : Secure configuration (special)
    - "Standard" : No special coloring (default)
.PARAMETER Name
    The attribute name (e.g., 'memberOf', 'servicePrincipalName').
.PARAMETER Value
    The attribute value (can be string, array, PSCustomObject, DateTime, etc.).
.PARAMETER IsComputer
    Set to $true if the object is a computer account (affects SPN classification).
.PARAMETER SourceObject
    Optional. The source AD object containing this attribute. Enables context-aware
    severity via Custom triggers (e.g., credential_needs_review, dangerous_rights_expected).
.RETURNS
    Severity class string: "Finding", "Hint", "Note", "Secure", or "Standard".
.EXAMPLE
    Get-AttributeSeverity -Name "servicePrincipalName" -Value "HTTP/server.domain.com"
    # Returns "Finding" for user accounts (Kerberoastable)

    Get-AttributeSeverity -Name "LDAPSigning" -Value "Required"
    # Returns "Secure"

    Get-AttributeSeverity -Name "dangerousRights" -Value "WriteDacl" -SourceObject $exchangeGroup
    # Returns "Hint" if $exchangeGroup.dangerousRightsSeverity is "Expected"
#>
function Get-AttributeSeverity {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Name,

        [Parameter(Mandatory=$false)]
        $Value,

        [Parameter(Mandatory=$false)]
        [bool]$IsComputer = $false,

        [Parameter(Mandatory=$false)]
        $SourceObject = $null
    )

    # Auto-detect IsComputer from SourceObject if not explicitly set
    if (-not $IsComputer -and $SourceObject) {
        if ($SourceObject.objectClass) {
            $IsComputer = $SourceObject.objectClass -contains 'computer' -or
                          $SourceObject.objectClass -eq 'computer' -or
                          ($SourceObject.objectClass -is [string] -and $SourceObject.objectClass -match 'computer')
        }
        if (-not $IsComputer -and $SourceObject.sAMAccountName -and $SourceObject.sAMAccountName -match '\$$') {
            $IsComputer = $true
        }
    }

    # TemplateACL: promote to Primary (Note severity) only when a low-privileged identity
    # has write/modify rights on the template. All-privileged ACLs stay in Extended (Standard).
    if ($Name -eq 'TemplateACL' -and $Value) {
        $entries = if ($Value -is [array]) { $Value } else { @($Value) }
        foreach ($entry in $entries) {
            if (-not $entry.SID) { continue }
            $privResult = Test-IsPrivileged -Identity $entry.SID
            if (-not $privResult.IsPrivileged) {
                return 'Note'   # Non-Standard -> auto-promoted to Primary
            }
        }
        return 'Standard'   # All privileged -> stays in Extended
    }

    # Delegate to FindingDefinitions triggers (Single Source of Truth)
    $triggerSeverity = Get-SeverityFromTrigger -Name $Name -Value $Value `
        -IsComputer $IsComputer -SourceObject $SourceObject
    if ($null -ne $triggerSeverity) {
        return $triggerSeverity
    }

    # No trigger matched - default severity
    return "Standard"
}

<#
.SYNOPSIS
    Converts an array of Distinguished Names to objects with DisplayName, DN, and SID.
.DESCRIPTION
    Helper function that extracts the CN from each DN and resolves the SID using the central ConvertTo-SID helper function.
.PARAMETER DistinguishedNames
    Array of distinguished names to process.
.RETURNS
    Array of PSCustomObjects with DisplayName, DN, and SID properties.
#>
function Convert-DNsToMemberInfo {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [array]$DistinguishedNames
    )

    $DistinguishedNames | ForEach-Object {
        $dn = $_
        $cn = if ($dn -match '^CN=([^,]+)') { $Matches[1] } else { $dn }
        [PSCustomObject]@{
            DisplayName = $cn
            DN = $dn
            SID = ConvertTo-SID -Identity $dn
        }
    }
}

<#
.SYNOPSIS
    Classifies a member object by SID.
.DESCRIPTION
    Returns the severity class for a member based on SID-based group classification.
    Delegates to central Get-AttributeSeverity for classification.
.PARAMETER MemberInfo
    PSCustomObject with DisplayName, DN, and SID properties.
.RETURNS
    Severity class string.
#>
function Get-MemberClass {
    param($MemberInfo)
    Get-AttributeSeverity -Name 'Member' -Value $MemberInfo.SID
}

<#
.SYNOPSIS
    Classifies a member of an Exchange service group.
.DESCRIPTION
    For Exchange service groups, the classification is INVERTED from normal:
    - Low-privileged members are CRITICAL (Finding) - they shouldn't be in Exchange groups!
    - High-privileged accounts (Domain Admins, etc.) are expected (Hint)
    - Exchange service accounts (computers like EX01) are expected (Hint)
    - Other Exchange groups as members are expected (Hint)
.PARAMETER MemberInfo
    PSCustomObject with DisplayName, DN, and SID properties.
.RETURNS
    Severity class string: "Finding" for low-privileged, "Hint" for expected members.
#>
function Get-ExchangeGroupMemberClass {
    param($MemberInfo)

    $sid = $MemberInfo.SID
    $dn = $MemberInfo.DN

    # No SID available - cannot classify, treat as Hint (unknown)
    if (-not $sid) {
        return "Hint"
    }

    # Check if this is an Exchange service group itself (nested Exchange groups)
    if ($dn -and $dn -match 'OU=Microsoft Exchange Security Groups') {
        return "Hint"
    }

    # Check if this is an Exchange Server by SPN
    if ($Script:LdapConnection -and $sid) {
        try {
            $exchangeCheck = Test-IsExchangeServer -Identity $sid
            if ($exchangeCheck.IsExchangeServer) {
                return "Hint"
            }
        } catch {
            Write-Debug "[Get-ExchangeGroupMemberClass] Exchange server check failed for SID $sid - $($_.Exception.Message)"
        }
    }

    # Check if this is a computer account by querying AD for objectClass
    if ($Script:LdapConnection -and $sid) {
        try {
            $sidHex = ConvertTo-LDAPSIDHex -SID $sid
            if ($sidHex) {
                $obj = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" -Properties 'objectClass')[0]
                if ($obj -and $obj.objectClass) {
                    $objectClasses = @($obj.objectClass)
                    if ($objectClasses -contains 'computer') {
                        return "Hint"
                    }
                }
            }
        } catch {
            Write-Debug "[Get-ExchangeGroupMemberClass] Computer account check failed for SID $sid - $($_.Exception.Message)"
        }
    }

    # Use Test-IsPrivileged with -IncludeOperators for recursive group membership check
    $privilegeCheck = Test-IsPrivileged -Identity $sid -IncludeOperators
    if ($privilegeCheck.IsPrivileged -eq $true) {
        return "Hint"
    }

    # Fallback: Check if this is a computer account by DN pattern
    if ($dn -and ($dn -match 'CN=Computers,' -or $dn -match 'OU=.*Server')) {
        return "Hint"
    }

    # Fallback: Check if the account name ends with $ (computer account convention)
    $name = $MemberInfo.DisplayName
    if ($name -and $name -match '\$$') {
        return "Hint"
    }

    # Low-privileged account in Exchange group - CRITICAL!
    return "Finding"
}

<#
.SYNOPSIS
    Classifies a memberOf group by SID.
.PARAMETER GroupInfo
    PSCustomObject with DisplayName, DN, and SID properties.
.RETURNS
    Severity class string.
#>
function Get-MemberOfClass {
    param($GroupInfo)
    Get-AttributeSeverity -Name 'MemberOf' -Value $GroupInfo
}

<#
.SYNOPSIS
    Classifies a sIDHistory SID by security relevance.
.PARAMETER SID
    The SID string from sIDHistory.
.RETURNS
    Severity class string (Finding for privileged, Hint for non-privileged).
#>
function Get-SIDHistoryClass {
    param([string]$SID)
    Get-AttributeSeverity -Name 'sIDHistory' -Value $SID
}

# ============================================================================
# Transformer Functions
# ============================================================================

# --- memberOf Transformer ---
function Convert-MemberOfToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $memberOfArray = @($Value)
    $memberOfObjects = Convert-DNsToMemberInfo -DistinguishedNames $memberOfArray

    $renderValues = @()
    foreach ($groupInfo in $memberOfObjects) {
        $groupClass = Get-MemberOfClass -GroupInfo $groupInfo
        $findingId = switch ($groupClass) {
            'Finding' { 'PRIVILEGED_GROUP_MEMBERSHIP' }
            'Hint'    { 'OPERATOR_GROUP_MEMBERSHIP' }
            default   { $null }
        }
        $renderValues += New-RenderValue -Display $groupInfo.DisplayName `
            -Severity $groupClass -FindingId $findingId `
            -RawValue $groupInfo.DN -Metadata @{ SID = $groupInfo.SID }
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

# --- privilegedGroups Transformer ---
function Convert-PrivilegedGroupsToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $privGroupValues = @($Value)
    $firstItem = $privGroupValues | Select-Object -First 1
    $isNewFormat = $firstItem -is [PSCustomObject] -and $firstItem.PSObject.Properties['SID']

    $renderValues = @()

    if ($isNewFormat) {
        foreach ($entry in $privGroupValues) {
            $sid = $entry.SID
            $displayText = $entry.DisplayText
            $triggerResult = if ($sid) {
                Get-TriggerMatch -Name 'privilegedGroups' -Value $sid
            } else { [PSCustomObject]@{ Severity = 'Hint'; FindingId = $null } }

            $severity = if ($triggerResult.Severity -ne 'Standard') { $triggerResult.Severity } else { 'Standard' }
            $findingId = $triggerResult.FindingId
            $renderValues += New-RenderValue -Display $displayText `
                -Severity $severity -FindingId $findingId `
                -RawValue $entry -Metadata @{ SID = $sid }
        }
    } else {
        # Legacy format: plain strings
        foreach ($g in $privGroupValues) {
            $triggerResult = Get-TriggerMatch -Name 'privilegedGroups' -Value $g
            $severity = if ($triggerResult.Severity -ne 'Standard') { $triggerResult.Severity } else { 'Standard' }
            $renderValues += New-RenderValue -Display ([string]$g) -Severity $severity `
                -FindingId $triggerResult.FindingId -RawValue $g
        }
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

# --- member Transformer (with Exchange group inversion) ---
function Convert-MemberToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $memberArray = @($Value)
    $memberObjects = Convert-DNsToMemberInfo -DistinguishedNames $memberArray
    $isExchangeGroup = $Context.IsExchangeGroup

    $renderValues = @()
    foreach ($memberInfo in $memberObjects) {
        if ($isExchangeGroup) {
            $memberClass = Get-ExchangeGroupMemberClass -MemberInfo $memberInfo
            $findingId = switch ($memberClass) {
                'Finding' { 'EXCHANGE_GROUP_LOW_PRIV_MEMBER' }
                default   { $null }
            }
        } else {
            $memberClass = Get-MemberClass -MemberInfo $memberInfo
            $findingId = switch ($memberClass) {
                'Finding' { 'PRIVILEGED_GROUP_MEMBERSHIP' }
                default   { $null }
            }
        }
        $renderValues += New-RenderValue -Display $memberInfo.DisplayName `
            -Severity $memberClass -FindingId $findingId `
            -RawValue $memberInfo.DN -Metadata @{ SID = $memberInfo.SID }
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = $true
        Values              = $renderValues
    }
}

# --- userAccountControl Transformer ---
function Convert-UACToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $uacFlags = @($Value)
    $allFlagsStr = $uacFlags -join ' '
    $renderValues = @()
    foreach ($flag in $uacFlags) {
        $flagStr = [string]$flag
        # Pass allFlagsStr as SourceObject so is_dc_uac can check for SERVER_TRUST_ACCOUNT
        $match = Get-TriggerMatch -Name 'userAccountControl' -Value $flagStr -SourceObject $allFlagsStr
        $renderValues += New-RenderValue -Display $flagStr -Severity $match.Severity -FindingId $match.FindingId -RawValue $flag
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

# --- servicePrincipalName Transformer ---
function Convert-SPNToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $spnValues = @($Value)
    $renderValues = @()

    # SPNs on computers are standard (informational); on users they indicate Kerberoasting risk
    $isComputer = $Context.IsComputer

    foreach ($spn in $spnValues) {
        if ($isComputer) {
            $renderValues += New-RenderValue -Display ([string]$spn) -Severity 'Standard' -RawValue $spn
        } else {
            $match = Get-TriggerMatch -Name 'servicePrincipalName' -Value $spn -IsComputer $false
            $renderValues += New-RenderValue -Display ([string]$spn) -Severity $match.Severity -FindingId $match.FindingId -RawValue $spn
        }
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = (-not $isComputer)
        Values              = $renderValues
    }
}

# --- sIDHistory Transformer ---
function Convert-SIDHistoryToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $sidHistoryRaw = @($Value)
    $renderValues = @()

    foreach ($sidEntry in $sidHistoryRaw) {
        $sidString = $null
        if ($sidEntry -is [byte[]]) {
            try {
                $secId = New-Object System.Security.Principal.SecurityIdentifier($sidEntry, 0)
                $sidString = $secId.Value
            } catch { continue }
        } elseif ($sidEntry -is [string]) {
            $sidString = $sidEntry
        } else { continue }

        if ($sidString) {
            $sidClass = Get-SIDHistoryClass -SID $sidString
            $resolvedName = ConvertFrom-SID -SID $sidString
            # ConvertFrom-SID returns a real name (e.g. "DOMAIN\user") for resolvable SIDs, but a
            # decorated SID string for unresolvable ones ("<SID> (FOREIGN)", "<SID> (UNRESOLVABLE...)").
            # Only append "($sidString)" when we actually resolved a NAME - otherwise the SID would be
            # printed twice, e.g. "<SID> (FOREIGN) (<SID>)". Detect the decorated-SID case by checking
            # whether the returned string already contains the raw SID.
            $display = if ($resolvedName -and ($resolvedName -notlike "*$sidString*")) {
                "$resolvedName ($sidString)"     # genuine name resolved
            } elseif ($resolvedName) {
                $resolvedName                    # already the SID (optionally with a (FOREIGN)/(UNRESOLVABLE) marker)
            } else {
                $sidString
            }

            $findingId = Get-FindingIdForAttribute -Name 'sIDHistory' -Value $sidString
            $renderValues += New-RenderValue -Display $display -Severity $sidClass `
                -FindingId $findingId -RawValue $sidString -Metadata @{ ResolvedName = $resolvedName }
        }
    }

    if ($renderValues.Count -eq 0) { return $null }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        DisplayName         = 'sIDHistory'
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = $true
        Values              = $renderValues
    }
}

# --- Owner Transformer ---
function Convert-OwnerToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $ownerSID = $Context.OwnerSID
    if (-not $ownerSID) { return $null }

    $domainSID = $Script:LDAPContext.DomainSID
    $isDefault = Test-IsDefaultOwner -SID $ownerSID -DomainSID $domainSID

    if ($isDefault) {
        # Default owner - show as standard, no highlighting
        return @{
            RowType             = 'SingleValue'
            OverallSeverity     = 'Standard'
            ForceAttributeClass = $false
            Values              = @(
                New-RenderValue -Display ([string]$Value) -Severity 'Standard' -RawValue $Value
            )
        }
    }

    # Non-default owner - Finding (red)
    $findingId = Get-FindingIdForAttribute -Name 'Owner' -Value $Value
    if (-not $findingId) { $findingId = 'NON_DEFAULT_COMPUTER_OWNERS' }
    return @{
        DisplayName         = 'Owner (non-default)'
        RowType             = 'SingleValue'
        OverallSeverity     = 'Finding'
        ForceAttributeClass = $true
        Values              = @(
            New-RenderValue -Display ([string]$Value) -Severity 'Finding' -FindingId $findingId -RawValue $Value
        )
    }
}

# --- msds-groupmsamembership Transformer ---
function Convert-GMSAToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $gmsaPrincipals = @()

    # Check unified object format (from Invoke-LDAPSearch)
    if ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['ACEs']) {
        $gmsaPrincipals = @($Value.ACEs | Where-Object { $_.Type -eq 'Allow' } | ForEach-Object {
            [PSCustomObject]@{ Name = $_.Name; SID = $_.SID }
        })
    }
    elseif ($Value -is [array]) {
        $firstItem = $Value | Select-Object -First 1
        if ($firstItem -is [PSCustomObject] -and $firstItem.PSObject.Properties['Name'] -and $firstItem.PSObject.Properties['SID']) {
            # New structured format from Get-DomainUser
            $gmsaPrincipals = @($Value)
        } else {
            # Legacy format (string array)
            $gmsaAllowEntries = @($Value | Where-Object { $_ -match '^Allow\s+-' })
            $gmsaPrincipals = @($gmsaAllowEntries | ForEach-Object {
                $principalName = if ($_ -match '^Allow\s+-\s+(.+?)\s+-\s+') { $Matches[1] } else { $_ }
                [PSCustomObject]@{ Name = $principalName; SID = $null }
            })
        }
    }

    if ($gmsaPrincipals.Count -eq 0) { return $null }

    $renderValues = @()
    foreach ($principal in $gmsaPrincipals) {
        $severity = 'Hint'
        $findingId = 'GMSA_MEMBERSHIP_INFO'
        if ($principal.SID) {
            $privResult = Test-IsPrivileged -Identity $principal.SID
            if ($privResult.Category -eq 'Privileged') {
                $severity = 'Finding'
                $findingId = 'GMSA_PASSWORD_READABLE'
            }
            elseif ($privResult.Category -in @('Operator', 'BroadGroup')) {
                $severity = 'Finding'
                $findingId = 'GMSA_PASSWORD_READABLE'
            }
        }
        $renderValues += New-RenderValue -Display $principal.Name -Severity $severity `
            -FindingId $findingId -RawValue $principal -Metadata @{ SID = $principal.SID }
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        DisplayName         = 'PrincipalsAllowedToRetrievePassword'
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = $true
        Values              = $renderValues
    }
}

# --- dangerousRights Transformer ---
function Convert-DangerousRightsToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $sourceObject = $Context.SourceObject

    # Split comma-separated string into individual rights for per-value tooltips
    # Check modules output dangerousRights as "GenericAll, GenericWrite, WriteDacl, WriteOwner"
    $rightsValues = if ($Value -is [string] -and $Value -match ',') {
        @($Value -split ',\s*' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    } else {
        @($Value)
    }

    # Use dangerousRightsSeverity from context for overall classification
    $overallClass = Get-AttributeSeverity -Name 'dangerousRightsSeverity' `
        -Value $Context.DangerousRightsSeverity -SourceObject $sourceObject

    # Build display name with ESC code if present
    $displayName = if ($sourceObject.dangerousRightsESC) {
        "dangerousRights [$($sourceObject.dangerousRightsESC)]"
    } else { 'dangerousRights' }

    $renderValues = @()
    foreach ($right in $rightsValues) {
        $rightStr = [string]$right
        $findingId = if ($Context.IsExchangeGroup) {
            'EXCHANGE_GROUP_PERMISSIONS'
        } else {
            Get-FindingIdForAttribute -Name 'dangerousRights' -Value $rightStr
        }
        $renderValues += New-RenderValue -Display $rightStr -Severity $overallClass `
            -FindingId $findingId -RawValue $right
    }

    return @{
        DisplayName         = $displayName
        RowType             = 'MultiValue'
        OverallSeverity     = $overallClass
        ForceAttributeClass = $true
        Values              = $renderValues
    }
}

# --- affectedOUs Transformer ---
function Convert-AffectedOUsToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $ouValues = @($Value)
    $sourceObject = $Context.SourceObject

    $renderValues = @()
    foreach ($ou in $ouValues) {
        $severity = Get-AttributeSeverity -Name 'affectedOUs' -Value $ou -SourceObject $sourceObject
        $renderValues += New-RenderValue -Display ([string]$ou) -Severity $severity -RawValue $ou
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = $true
        Values              = $renderValues
    }
}

# --- inheritedFrom Transformer ---
function Convert-InheritedFromToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $inheritedValues = @($Value)
    $renderValues = @()
    foreach ($v in $inheritedValues) {
        $severity = Get-AttributeSeverity -Name 'inheritedFrom' -Value $v
        $renderValues += New-RenderValue -Display ([string]$v) -Severity $severity -RawValue $v
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

# --- TemplateACL Transformer ---
# Displays write/modify permissions on certificate templates (owner + dangerous rights)
# Color-coding: Standard = expected admin, Hint = operator/unknown, Finding = non-privileged
function Convert-TemplateACLToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $aces = @($Value)
    if ($aces.Count -eq 0) { return $null }

    $renderValues = @()
    foreach ($ace in $aces) {
        if ($ace -isnot [PSCustomObject]) { continue }

        $display = "$($ace.Identity): $($ace.Right)"
        $sid = $ace.SID

        # Determine severity based on privilege level
        $severity = 'Standard'
        if ($sid) {
            $privCheck = Test-IsPrivileged -Identity $sid
            $severity = switch ($privCheck.Category) {
                'Privileged'  { 'Standard' }   # Domain Admins, Enterprise Admins, SYSTEM - expected
                'BroadGroup'  { 'Finding' }    # Everyone, Auth Users, Domain Users - dangerous
                default       { 'Hint' }       # Operator-level or unknown
            }
        }

        $findingId = if ($severity -ne 'Standard') { 'ESC4_TEMPLATE' } else { $null }
        $renderValues += New-RenderValue -Display $display -Severity $severity `
            -FindingId $findingId -RawValue $ace
    }

    if ($renderValues.Count -eq 0) { return $null }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        DisplayName         = 'templateACL'
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

# --- DangerousACEs Transformer ---
function Convert-DangerousACEsToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $aces = @($Value)
    $renderValues = @()
    foreach ($ace in $aces) {
        if ($ace -is [PSCustomObject]) {
            $display = "$($ace.Identity): $($ace.DangerousRight)"
            $severity = if ($ace.Severity -in @('Expected', 'Attention')) { 'Hint' } else { 'Finding' }
            $findingId = 'ESC4_TEMPLATE'
            $renderValues += New-RenderValue -Display $display -Severity $severity `
                -FindingId $findingId -RawValue $ace
        } else {
            $renderValues += New-RenderValue -Display ([string]$ace) -Severity 'Finding' `
                -FindingId 'ESC4_TEMPLATE' -RawValue $ace
        }
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        DisplayName         = 'dangerousPermissions'
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = $true
        Values              = $renderValues
    }
}

# --- DangerousPermissions Transformer (GPO - 2 formats) ---
function Convert-DangerousPermToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $sourceObject = $Context.SourceObject

    # Format 1: Array of objects with Trustee/Rights properties
    if ($Value -is [array] -and $Value.Count -gt 0 -and $Value[0].PSObject.Properties['Trustee']) {
        $permClass = Get-AttributeSeverity -Name 'DangerousPermissions' -Value $Value -SourceObject $sourceObject
        $renderValues = @()
        # First line: summary count
        $renderValues += New-RenderValue -Display "$($Value.Count) non-privileged ACE(s)" `
            -Severity $permClass -RawValue $Value
        # Per-ACE details
        foreach ($perm in $Value) {
            $renderValues += New-RenderValue -Display "$($perm.Trustee): $($perm.Rights)" `
                -Severity $permClass -RawValue $perm
        }
        return @{
            RowType             = 'MultiValue'
            OverallSeverity     = $permClass
            ForceAttributeClass = $true
            Values              = $renderValues
        }
    }

    # Format 2: String or multiline string
    if ($Value -is [string]) {
        $permValues = if ($Value -match "`n") { $Value -split "`n" } else { @($Value) }
        $permClass = Get-AttributeSeverity -Name 'DangerousPermissions' -Value $permValues -SourceObject $sourceObject
        $renderValues = @()
        foreach ($pv in $permValues) {
            $pvSeverity = Get-AttributeSeverity -Name 'DangerousPermissions' -Value $pv -SourceObject $sourceObject
            $renderValues += New-RenderValue -Display ([string]$pv) -Severity $pvSeverity -RawValue $pv
        }
        $maxSev = Get-MaxSeverityFromValues -Values $renderValues
        return @{
            RowType             = 'MultiValue'
            OverallSeverity     = $maxSev
            ForceAttributeClass = $true
            Values              = $renderValues
        }
    }

    return $null
}

# --- EnrollmentPrincipals Transformer ---
function Convert-EnrollPrincipalsToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $principals = @($Value)
    $renderValues = @()
    foreach ($p in $principals) {
        $pStr = [string]$p
        $privCheck = Test-IsPrivileged -Identity $pStr
        $severity = switch ($privCheck.Category) {
            'Privileged'  { 'Standard' }   # Admins expected to enroll
            'BroadGroup'  { 'Finding' }    # Everyone, Auth Users, Domain Users
            default       { 'Hint' }
        }
        $findingId = switch ($severity) {
            'Finding' { 'ADCS_NONPRIV_ENROLLMENT' }
            'Hint'    { 'ADCS_NONPRIV_ENROLLMENT' }
            default   { $null }
        }
        $renderValues += New-RenderValue -Display $pStr -Severity $severity `
            -FindingId $findingId -RawValue $p
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        DisplayName         = 'enrollmentPrincipals'
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

# --- ExtendedKeyUsage Transformer ---
function Convert-EKUToRenderValues {
    [CmdletBinding()]
    param([string]$Name, $Value, $Context)

    $ekuValues = @($Value)
    $renderValues = @()
    foreach ($eku in $ekuValues) {
        $ekuStr = [string]$eku
        $severity = 'Standard'
        $findingId = $null
        if ($ekuStr -match '2\.5\.29\.37\.0|Any Purpose') {
            $severity = 'Finding'
            $findingId = 'ESC2_TEMPLATE'
        }
        elseif ($ekuStr -match '1\.3\.6\.1\.5\.5\.7\.3\.2|Client Authentication') {
            $severity = 'Hint'
            $findingId = 'ADCS_CLIENT_AUTH_EKU'
        }
        elseif ($ekuStr -match '1\.3\.6\.1\.4\.1\.311\.20\.2\.2|Smartcard') {
            $severity = 'Hint'
            $findingId = 'ADCS_SMARTCARD_LOGON_EKU'
        }
        $renderValues += New-RenderValue -Display $ekuStr -Severity $severity `
            -FindingId $findingId -RawValue $eku
    }

    $maxSev = Get-MaxSeverityFromValues -Values $renderValues
    return @{
        DisplayName         = 'extendedKeyUsage'
        RowType             = 'MultiValue'
        OverallSeverity     = $maxSev
        ForceAttributeClass = ($maxSev -ne 'Standard')
        Values              = $renderValues
    }
}

