# ----- Render-ConsoleObject.ps1 -----

<#
.SYNOPSIS
    Console renderer for adPEAS RenderModel objects.

.DESCRIPTION
    Iterates over a RenderModel and outputs each row to the console using Write-adPEASAttribute from Write-adPEASOutput.ps1.
    Multi-value rendering is handled inline with per-value severity coloring.

    This is a "dumb" renderer - all business logic (severity, attribute selection, transformations) has already been resolved by Get-RenderModel.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Requires: Write-adPEASOutput.ps1 (Write-adPEASAttribute, Show-EmptyLine)
#>

<#
.SYNOPSIS
    Renders a RenderModel to the console.
.DESCRIPTION
    Iterates over Primary and PostObject rows and renders each one.
    Extended rows are NOT shown in console (they are HTML-only collapsible).
.PARAMETER Model
    The RenderModel object produced by Get-RenderModel.
.PARAMETER AlignAt
    Column width for attribute alignment (default: 45).
#>
function Render-ConsoleObject {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Model,

        [Parameter(Mandatory=$false)]
        [int]$AlignAt = 45
    )

    $outputSomething = $false

    # Render Primary rows (always visible)
    foreach ($row in $Model.Primary) {
        Render-ConsoleRow -Row $row -AlignAt $AlignAt
        $outputSomething = $true
    }

    # Render PostObject rows (roasting hashes - special format)
    foreach ($row in $Model.PostObject) {
        Render-ConsolePostObjectRow -Row $row
        $outputSomething = $true
    }

    # Trailing empty line after object
    if ($outputSomething) {
        Show-EmptyLine
    }
}

<#
.SYNOPSIS
    Renders a single RenderRow to the console.
.DESCRIPTION
    Dispatches to the appropriate output function based on RowType:
    - SingleValue: Write-adPEASAttribute
    - MultiValue: Inline per-value coloring
    - Image: Write-adPEASAttribute (with DisplayText)
    - Hash: handled by PostObject
#>
function Render-ConsoleRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Row,

        [Parameter(Mandatory=$false)]
        [int]$AlignAt = 45
    )

    switch ($Row.RowType) {
        'SingleValue' {
            $val = $Row.Values[0]
            $colorValue = ($Row.OverallSeverity -ne 'Standard')
            Write-adPEASAttribute -Name $Row.Name -Value $val.Display -Class $Row.OverallSeverity -AlignAt $AlignAt -ColorValue:$colorValue
        }

        'MultiValue' {
            # Build classified values for inline multi-value rendering
            $classifiedValues = @()
            foreach ($val in $Row.Values) {
                $classifiedValues += [PSCustomObject]@{ Value = $val.Display; Class = $val.Severity }
            }

            if ($classifiedValues.Count -eq 0) { return }

            # Determine if attribute name should be colored
            $attrClass = if ($Row.ForceAttributeClass -or $Row.OverallSeverity -ne 'Standard') {
                $Row.OverallSeverity
            } else { 'Standard' }

            $attrPrefix = Get-ClassPrefix -Class $attrClass
            $hasAttrPrefix = ($attrPrefix.Length -gt 0)

            $ANSI = $Script:ANSI

            # Build attribute name with padding
            $attrPadding = if ($hasAttrPrefix) { $AlignAt - 4 } else { $AlignAt }
            $paddedAttrName = "$($Row.Name):".PadRight($attrPadding, ' ')

            # First value - output with attribute name
            $firstVal = $classifiedValues[0]
            $firstLinePlain = $attrPrefix + $paddedAttrName + $firstVal.Value

            if ($Script:adPEAS_OutputColor -ne $false) {
                $attrColor = Get-ClassColor -Class $attrClass
                $valColor = Get-ClassColor -Class $firstVal.Class

                # Special handling for Secure class (has background color)
                if ($attrClass -eq "Secure") {
                    $nameOnlyWithColon = "$($Row.Name):"
                    $paddingSpaces = ' ' * ($attrPadding - $nameOnlyWithColon.Length)
                    $coloredOutput = $attrColor + $attrPrefix + $nameOnlyWithColon + $ANSI["Reset"] + $paddingSpaces + $valColor + $firstVal.Value + $ANSI["Reset"]
                    Write-Host $coloredOutput
                } else {
                    $attrPart = $attrColor + $attrPrefix + $paddedAttrName + $ANSI["Reset"]
                    Write-Host ($attrPart + $valColor + $firstVal.Value + $ANSI["Reset"])
                }
            } else {
                Write-Host $firstLinePlain
            }

            if ($Script:adPEAS_Outputfile) {
                if ($Script:adPEAS_OutputColor -ne $false) {
                    $attrColor = Get-ClassColor -Class $attrClass
                    $valColor = Get-ClassColor -Class $firstVal.Class
                    if ($attrClass -eq "Secure") {
                        $nameOnlyWithColon = "$($Row.Name):"
                        $paddingSpaces = ' ' * ($attrPadding - $nameOnlyWithColon.Length)
                        $fileText = $attrColor + $attrPrefix + $nameOnlyWithColon + $ANSI["Reset"] + $paddingSpaces + $valColor + $firstVal.Value + $ANSI["Reset"]
                    } else {
                        $fileText = $attrColor + $attrPrefix + $paddedAttrName + $ANSI["Reset"] + $valColor + $firstVal.Value + $ANSI["Reset"]
                    }
                } else {
                    $fileText = $firstLinePlain
                }
                [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $fileText + "`n", [System.Text.Encoding]::UTF8)
            }

            # Continuation values - indented
            $indent = " " * $AlignAt
            for ($i = 1; $i -lt $classifiedValues.Count; $i++) {
                $cv = $classifiedValues[$i]
                $linePlain = $indent + $cv.Value

                if ($Script:adPEAS_OutputColor -ne $false) {
                    $lineColor = Get-ClassColor -Class $cv.Class
                    Write-Host ($indent + $lineColor + $cv.Value + $ANSI["Reset"])
                } else {
                    Write-Host $linePlain
                }

                if ($Script:adPEAS_Outputfile) {
                    if ($Script:adPEAS_OutputColor -ne $false) {
                        $lineColor = Get-ClassColor -Class $cv.Class
                        $fileText = $indent + $lineColor + $cv.Value + $ANSI["Reset"]
                    } else {
                        $fileText = $linePlain
                    }
                    [System.IO.File]::AppendAllText($Script:adPEAS_Outputfile, $fileText + "`n", [System.Text.Encoding]::UTF8)
                }
            }
        }

        'Image' {
            # Image data - show DisplayText
            $val = $Row.Values[0]
            Write-adPEASAttribute -Name $Row.Name -Value $val.Display -AlignAt $AlignAt
        }
    }
}

<#
.SYNOPSIS
    Renders a PostObject row (roasting hashes) to the console.
.DESCRIPTION
    PostObject rows (KerberoastingHash, ASREPRoastingHash) are rendered after
    the object card with a Show-Line label followed by the hash value.
#>
function Render-ConsolePostObjectRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Row
    )

    $val = $Row.Values[0]

    # Determine hash type label from RawName
    $hashLabel = switch ($Row.RawName) {
        'KerberoastingHash' {
            if ($val.RawValue -is [PSCustomObject] -and $val.RawValue.PSObject.Properties['KerberoastingHashType']) {
                $val.RawValue.KerberoastingHashType
            } else { 'Kerberoast Hash' }
        }
        'ASREPRoastingHash' {
            if ($val.RawValue -is [PSCustomObject] -and $val.RawValue.PSObject.Properties['ASREPRoastingHashType']) {
                $val.RawValue.ASREPRoastingHashType
            } else { 'AS-REP Roast Hash' }
        }
        default { $Row.Name }
    }

    Show-Line "${hashLabel}:" -Class "Finding" -NoCollect
    Write-adPEASOutput -Text $val.Display -Class "Finding" -NoPrefix
}



# ----- Render-HtmlObject.ps1 -----

<#
.SYNOPSIS
    HTML renderer for adPEAS RenderModel objects.

.DESCRIPTION
    Iterates over a RenderModel and produces HTML for each row.
    Replaces the previous Build-AttributeRowHtml function in Export-HTMLReport.ps1.

    This is a "dumb" renderer - all business logic (severity, attribute selection,
    transformations) has already been resolved by Get-RenderModel.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Requires: Get-RenderModel.ps1, Export-HTMLReport.ps1 (ConvertTo-HtmlEncode)
#>

<#
.SYNOPSIS
    Renders a full RenderModel as HTML for an object detail card.
.DESCRIPTION
    Produces the HTML content for Primary, Extended, and PostObject sections.
    Primary attributes are always visible, Extended are in a collapsible section.
.PARAMETER Model
    The RenderModel object produced by Get-RenderModel.
.PARAMETER ObjectId
    Unique ID for this object's HTML elements (for toggle functionality).
.PARAMETER Severity
    Overall card severity (unused by renderer itself, passed through for compatibility).
.RETURNS
    HTML string for the object's attribute rows.
#>
function Render-HtmlObject {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Model,

        [Parameter(Mandatory=$true)]
        [string]$ObjectId,

        [Parameter(Mandatory=$false)]
        [string]$Severity = 'Standard'
    )

    $primaryHtml = [System.Text.StringBuilder]::new()
    $extendedHtml = [System.Text.StringBuilder]::new()

    # Render Primary rows
    foreach ($row in $Model.Primary) {
        [void]$primaryHtml.AppendLine((Render-HtmlRow -Row $row))
    }

    # Render Extended rows
    foreach ($row in $Model.Extended) {
        [void]$extendedHtml.AppendLine((Render-HtmlRow -Row $row))
    }

    # Render PostObject rows (roasting hashes etc.) - inside the primary section
    foreach ($row in $Model.PostObject) {
        [void]$primaryHtml.AppendLine((Render-HtmlRow -Row $row))
    }

    # Build output
    $html = [System.Text.StringBuilder]::new()
    [void]$html.Append($primaryHtml.ToString())

    # Extended section (collapsible)
    $extendedContent = $extendedHtml.ToString().Trim()
    if ($extendedContent) {
        $extendedCount = $Model.Extended.Count
        [void]$html.AppendLine("                        <div class=`"extended-attrs-toggle`" onclick=`"toggleExtendedAttrs('$ObjectId')`">")
        [void]$html.AppendLine("                            <span class=`"toggle-icon`" id=`"icon-$ObjectId`">&#9654;</span>")
        [void]$html.AppendLine("                            <span>Show $extendedCount more attribute(s)</span>")
        [void]$html.AppendLine("                        </div>")
        [void]$html.AppendLine("                        <div class=`"extended-attrs`" id=`"ext-$ObjectId`" style=`"display: none;`">")
        [void]$html.Append($extendedContent)
        [void]$html.AppendLine("                        </div>")
    }

    return $html.ToString()
}

<#
.SYNOPSIS
    Renders a single RenderRow as HTML.
.DESCRIPTION
    Creates an attr-row div with the attribute name and formatted values.
    Values with non-Standard severity get CSS class spans with optional
    data-finding-id attributes for tooltips.
.PARAMETER Row
    A RenderRow object from the RenderModel.
.RETURNS
    HTML string for the attribute row.
#>
function Render-HtmlRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Row
    )

    $nameHtml = ConvertTo-HtmlEncode $Row.Name

    switch ($Row.RowType) {
        'SingleValue' {
            $val = $Row.Values[0]
            $displayHtml = ConvertTo-HtmlEncode $val.Display
            $valueHtml = Format-HtmlValueSpan -DisplayHtml $displayHtml -Severity $val.Severity -FindingId $val.FindingId
            $classAttr = Get-HtmlValueClassAttr -Severity $Row.OverallSeverity
            $attrNameEncoded = ConvertTo-HtmlEncode $Row.Name
            return "                        <div class=`"attr-row`" data-attr-name=`"$attrNameEncoded`"><span class=`"attr-drag-handle`" draggable=`"true`" title=`"Drag to reorder`" aria-hidden=`"true`">&#10303;</span><div class=`"attr-name`">$nameHtml</div><div$classAttr>$valueHtml</div></div>"
        }

        'MultiValue' {
            $valuesHtml = @()
            foreach ($val in $Row.Values) {
                $displayHtml = ConvertTo-HtmlEncode $val.Display
                $valuesHtml += Format-HtmlValueSpan -DisplayHtml $displayHtml -Severity $val.Severity -FindingId $val.FindingId
            }
            $displayValue = $valuesHtml -join '<br>'
            # Individual values carry their own severity spans, so the container
            # div uses plain "attr-value" to avoid coloring non-severity items
            $attrNameEncoded = ConvertTo-HtmlEncode $Row.Name
            return "                        <div class=`"attr-row`" data-attr-name=`"$attrNameEncoded`"><span class=`"attr-drag-handle`" draggable=`"true`" title=`"Drag to reorder`" aria-hidden=`"true`">&#10303;</span><div class=`"attr-name`">$nameHtml</div><div class=`"attr-value`">$displayValue</div></div>"
        }

        'Image' {
            $val = $Row.Values[0]
            $rawValue = $val.RawValue

            # Check if this is an ImageData object
            $isImageData = $false
            if ($rawValue -is [PSCustomObject]) {
                if ($rawValue.psobject.TypeNames -contains 'adPEAS.ImageData') {
                    $isImageData = $true
                }
                elseif ($rawValue.PSObject.Properties['Base64'] -and $rawValue.PSObject.Properties['MimeType']) {
                    $isImageData = $true
                }
            }

            if ($isImageData) {
                # XSS Protection: Validate MimeType
                $allowedMimeTypes = @('image/jpeg', 'image/png', 'image/gif', 'image/bmp', 'image/webp')
                $mimeType = if ($rawValue.MimeType -in $allowedMimeTypes) { $rawValue.MimeType } else { 'image/png' }

                $imgSrc = "data:$mimeType;base64,$($rawValue.Base64)"
                $imgTypeEncoded = ConvertTo-HtmlEncode $rawValue.ImageType
                $imgSizeEncoded = ConvertTo-HtmlEncode $rawValue.SizeKB
                $imgTitle = "$imgTypeEncoded image, $imgSizeEncoded KB"
                $altText = ConvertTo-HtmlEncode $Row.Name
                $displayValue = "<img src=`"$imgSrc`" alt=`"$altText`" title=`"$imgTitle`" style=`"max-width: 96px; max-height: 96px; border: 1px solid #555; border-radius: 4px;`" /><br><span style=`"font-size: 0.85em; color: #888;`">$imgTitle</span>"
                $attrNameEncoded = ConvertTo-HtmlEncode $Row.Name
                return "                        <div class=`"attr-row`" data-attr-name=`"$attrNameEncoded`"><span class=`"attr-drag-handle`" draggable=`"true`" title=`"Drag to reorder`" aria-hidden=`"true`">&#10303;</span><div class=`"attr-name`">$nameHtml</div><div class=`"attr-value`">$displayValue</div></div>"
            }

            # Fallback: display as text
            $displayHtml = ConvertTo-HtmlEncode $val.Display
            $attrNameEncoded = ConvertTo-HtmlEncode $Row.Name
            return "                        <div class=`"attr-row`" data-attr-name=`"$attrNameEncoded`"><span class=`"attr-drag-handle`" draggable=`"true`" title=`"Drag to reorder`" aria-hidden=`"true`">&#10303;</span><div class=`"attr-name`">$nameHtml</div><div class=`"attr-value`">$displayHtml</div></div>"
        }

        'Hash' {
            # Roasting hashes - always red/finding
            $val = $Row.Values[0]
            $displayHtml = ConvertTo-HtmlEncode $val.Display
            $dataAttr = if ($val.FindingId) { " data-finding-id=`"$(ConvertTo-HtmlEncode $val.FindingId)`"" } else { "" }
            $valueHtml = "<span class=`"finding`"$dataAttr>$displayHtml</span>"
            $attrNameEncoded = ConvertTo-HtmlEncode $Row.Name
            return "                        <div class=`"attr-row`" data-attr-name=`"$attrNameEncoded`"><span class=`"attr-drag-handle`" draggable=`"true`" title=`"Drag to reorder`" aria-hidden=`"true`">&#10303;</span><div class=`"attr-name`">$nameHtml</div><div class=`"attr-value`">$valueHtml</div></div>"
        }

        default {
            # Fallback
            $val = if ($Row.Values.Count -gt 0) { $Row.Values[0] } else { $null }
            $displayHtml = if ($val) { ConvertTo-HtmlEncode $val.Display } else { '' }
            $attrNameEncoded = ConvertTo-HtmlEncode $Row.Name
            return "                        <div class=`"attr-row`" data-attr-name=`"$attrNameEncoded`"><span class=`"attr-drag-handle`" draggable=`"true`" title=`"Drag to reorder`" aria-hidden=`"true`">&#10303;</span><div class=`"attr-name`">$nameHtml</div><div class=`"attr-value`">$displayHtml</div></div>"
        }
    }
}

# ============================================================================
# HTML Helper Functions
# ============================================================================

<#
.SYNOPSIS
    Wraps a display value in a severity-colored span with optional FindingId.
.DESCRIPTION
    If severity is Standard, returns the raw HTML. Otherwise wraps in a span
    with CSS class and optional data-finding-id for tooltip.
#>
function Format-HtmlValueSpan {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$DisplayHtml,

        [Parameter(Mandatory=$false)]
        [string]$Severity = 'Standard',

        [Parameter(Mandatory=$false)]
        [string]$FindingId = $null
    )

    if ($Severity -eq 'Standard' -or -not $Severity) {
        return $DisplayHtml
    }

    $cssClass = ConvertTo-HtmlEncode $Severity.ToLower()
    $dataAttr = if ($FindingId) { " data-finding-id=`"$(ConvertTo-HtmlEncode $FindingId)`"" } else { "" }
    return "<span class=`"$cssClass`"$dataAttr>$DisplayHtml</span>"
}

<#
.SYNOPSIS
    Returns the class attribute string for an attr-value div based on severity.
.DESCRIPTION
    For Standard severity, returns just class="attr-value".
    For other severities, adds the severity as CSS class.
#>
function Get-HtmlValueClassAttr {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Severity = 'Standard'
    )

    if ($Severity -eq 'Standard' -or -not $Severity) {
        return " class=`"attr-value`""
    }

    $cssClass = ConvertTo-HtmlEncode $Severity.ToLower()
    return " class=`"attr-value $cssClass`""
}



# ----- adPEAS-ScoringDefinitions.ps1 -----

<#
.SYNOPSIS
    Central scoring definitions for adPEAS HTML reports.

.DESCRIPTION
    This file contains all scoring-related definitions used by the HTML report generator.

    Scoring Formula:
    FINAL_SCORE = (BASE x IMPACT x EXPLOITABILITY x SECURITY) + CORRELATION

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# =============================================================================
# HELPER FUNCTION: Get BaseScores from FindingDefinitions
# =============================================================================
# Extracts all BaseScore values from $Script:FindingDefinitions for JavaScript export.

function Get-FindingBaseScores {
    <#
    .SYNOPSIS
        Returns a hashtable of FindingID => BaseScore from FindingDefinitions.
    .DESCRIPTION
        Extracts BaseScore values from $Script:FindingDefinitions for use in JavaScript generation and statistics.
    #>
    $scores = @{}

    if ($null -eq $Script:FindingDefinitions) {
        Write-Warning "[Get-FindingBaseScores] FindingDefinitions not loaded"
        return $scores
    }

    foreach ($entry in $Script:FindingDefinitions.GetEnumerator()) {
        $findingId = $entry.Key
        $definition = $entry.Value

        if ($definition.ContainsKey('BaseScore')) {
            $scores[$findingId] = $definition.BaseScore
        } else {
            # Fallback based on Risk level if BaseScore not defined
            $risk = if ($definition.ContainsKey('Risk')) { $definition.Risk } else { 'Standard' }
            $scores[$findingId] = switch ($risk) {
                'Finding' { $Script:SeverityFallbackScores[$Script:SeverityClasses.Finding] }
                'Hint'    { $Script:SeverityFallbackScores[$Script:SeverityClasses.Hint] }
                'Note'    { $Script:SeverityFallbackScores[$Script:SeverityClasses.Note] }
                'Secure'  { $Script:SeverityFallbackScores[$Script:SeverityClasses.Secure] }
                default   { 0 }
            }
        }
    }

    return $scores
}

# =============================================================================
# SEVERITY FALLBACK SCORES
# =============================================================================
# Used when no keyword matches the finding title.

$Script:SeverityFallbackScores = @{
    $Script:SeverityClasses.Finding  = 35    # Red findings without keyword match
    $Script:SeverityClasses.Hint     = 15    # Yellow hints without keyword match
    $Script:SeverityClasses.Note     = 0     # Green notes
    $Script:SeverityClasses.Secure   = 0     # Secure configurations
    $Script:SeverityClasses.Standard = 0     # Standard output (no severity)
}

# =============================================================================
# IMPACT MULTIPLIERS (ACCOUNT TIER)
# =============================================================================
# Adjusts score based on the privilege level of affected accounts
# Microsoft Tiering Model: https://docs.microsoft.com/en-us/security/privileged-access-workstations/
# Tier 0: -512 (Domain Admins), -519 (Enterprise Admins), -518 (Schema Admins) - Domain Controllers
# Tier 1: -548 (Account Ops), -549 (Server Ops), -551 (Backup Ops), -550 (Print Ops) - Servers
# Tier 2: Other privileged groups - Workstations

$Script:ImpactMultipliers = @{
    'tier0' = 2.0    # Domain/Enterprise/Schema Admins - immediate domain compromise (Microsoft Tier 0)
    'tier1' = 1.5    # Operators (Account, Server, Backup, Print) - significant access (Microsoft Tier 1)
    'tier2' = 1.2    # Other privileged groups - elevated access (Microsoft Tier 2)
    'none'  = 1.0    # Standard user accounts - base impact
}

# =============================================================================
# EXPLOITABILITY MODIFIERS
# =============================================================================

# Password Age Modifiers (relative to domain maxPwdAge policy)
# Example: If maxPwdAge=90 days and password is 450 days old = 5x policy = 1.4 modifier
$Script:PasswordAgeModifiers = @{
    'multiplier_10x' = 1.6    # Password age >= 10x maxPwdAge
    'multiplier_5x'  = 1.4    # Password age >= 5x maxPwdAge
    'multiplier_3x'  = 1.3    # Password age >= 3x maxPwdAge
    'multiplier_2x'  = 1.2    # Password age >= 2x maxPwdAge
    'multiplier_1x'  = 1.1    # Password age >= 1x maxPwdAge (over policy)
    'within_policy'  = 1.0    # Password age < maxPwdAge
}

# Password Length Modifiers (based on domain minPwdLength)
$Script:PasswordLengthModifiers = @{
    'very_weak'  = 1.4    # minPwdLength < 8 characters
    'weak'       = 1.2    # minPwdLength 8-11 characters
    'standard'   = 1.0    # minPwdLength 12-15 characters
    'strong'     = 0.8    # minPwdLength >= 16 characters
}

# Password Complexity Modifier
$Script:PasswordComplexityModifiers = @{
    'disabled' = 1.25    # Complexity not required - weak passwords likely
    'enabled'  = 1.0     # Complexity required - standard
}

# Encryption Type Modifiers (for Kerberos-based attacks)
$Script:EncryptionTypeModifiers = @{
    'rc4_only'  = 1.3    # RC4-HMAC only (etype 23) - fast to crack
    'aes128'    = 1.0    # AES128-CTS (etype 17) - standard
    'aes256'    = 0.9    # AES256-CTS (etype 18) - slower to crack
}

# =============================================================================
# SECURITY MODIFIERS (MITIGATING CONTROLS)
# =============================================================================
# These REDUCE the score when protective measures are in place

$Script:SecurityModifiers = @{
    # UAC Flags
    'ACCOUNTDISABLE'      = 0.1     # Account is disabled - can't be used
    'LOCKOUT'             = 0.3     # Account is locked out
    'SMARTCARD_REQUIRED'  = 0.15    # Password is random/unknown (cracking attacks)
    'PASSWORD_EXPIRED'    = 0.7     # Password may be changed soon
    'USE_DES_KEY_ONLY'    = 1.3     # Weak encryption - INCREASES risk
    'NOT_DELEGATED'       = 0.3     # Delegation protection (delegation attacks)

    # Group Membership
    'PROTECTED_USERS'     = 0.2     # Protected Users group membership
}

# =============================================================================
# CORRELATION BONUS
# =============================================================================
# Bonus points when same account appears in multiple risky findings
# Non-admin accounts appearing repeatedly are MORE interesting (potential attack paths)

$Script:CorrelationBonus = @{
    # Standard correlation (for privileged accounts)
    'per_finding'           = 5     # Points per additional finding
    'max_bonus'             = 15    # Maximum correlation bonus

    # Enhanced correlation for non-admin accounts (potential privilege escalation paths)
    # Rationale: A non-admin appearing in 3+ findings suggests an attack path exists
    'non_admin_per_finding' = 8     # Higher points per finding for non-admins
    'non_admin_max_bonus'   = 30    # Higher cap - these are more interesting
    'non_admin_threshold'   = 3     # Minimum findings to trigger enhanced bonus
}

# =============================================================================
# SCORE DISPLAY THRESHOLDS
# =============================================================================
# Color coding for score badges in HTML report

$Script:ScoreThresholds = @{
    'critical' = 80    # Score >= 80: Red (Critical)
    'high'     = 60    # Score >= 60: Orange (High)
    'medium'   = 40    # Score >= 40: Yellow (Medium)
    'low'      = 20    # Score >= 20: Blue (Low)
    # Score < 20: Gray (Info)
}

# =============================================================================
# HELPER FUNCTION: Convert to JavaScript
# =============================================================================

function ConvertTo-ScoringJavaScript {
    <#
    .SYNOPSIS
        Converts PowerShell scoring definitions to JavaScript for HTML embedding.

    .DESCRIPTION
        Generates JavaScript code that can be embedded in the HTML report.
        Called by Export-HTMLReport.ps1 during report generation.
        BaseScores are extracted from $Script:FindingDefinitions.

    .OUTPUTS
        String containing JavaScript variable declarations.
    #>

    # Get base scores from FindingDefinitions (single source of truth)
    $baseScores = Get-FindingBaseScores

    $js = @"
        // ==========================================================================
        // SCORING DEFINITIONS (Auto-generated from adPEAS-FindingDefinitions.ps1)
        // ==========================================================================

        const findingBaseScores = {
"@

    # Add base scores from FindingDefinitions
    $sortedScores = $baseScores.GetEnumerator() | Sort-Object Value -Descending
    $scoreLines = @()
    foreach ($entry in $sortedScores) {
        $scoreLines += "            '$($entry.Key)': $($entry.Value)"
    }
    $js += $scoreLines -join ",`n"
    $js += @"

        };

        const severityBaseScores = {
            'finding': $($Script:SeverityFallbackScores[$Script:SeverityClasses.Finding]),
            'hint': $($Script:SeverityFallbackScores[$Script:SeverityClasses.Hint]),
            'note': $($Script:SeverityFallbackScores[$Script:SeverityClasses.Note]),
            'secure': $($Script:SeverityFallbackScores[$Script:SeverityClasses.Secure])
        };

        const impactMultipliers = {
            tier0: $($Script:ImpactMultipliers['tier0']),
            tier1: $($Script:ImpactMultipliers['tier1']),
            tier2: $($Script:ImpactMultipliers['tier2']),
            none: $($Script:ImpactMultipliers['none'])
        };

        const passwordAgeModifiers = {
            multiplier_10x: $($Script:PasswordAgeModifiers['multiplier_10x']),
            multiplier_5x: $($Script:PasswordAgeModifiers['multiplier_5x']),
            multiplier_3x: $($Script:PasswordAgeModifiers['multiplier_3x']),
            multiplier_2x: $($Script:PasswordAgeModifiers['multiplier_2x']),
            multiplier_1x: $($Script:PasswordAgeModifiers['multiplier_1x']),
            within_policy: $($Script:PasswordAgeModifiers['within_policy'])
        };

        const passwordLengthModifiers = {
            very_weak: $($Script:PasswordLengthModifiers['very_weak']),
            weak: $($Script:PasswordLengthModifiers['weak']),
            standard: $($Script:PasswordLengthModifiers['standard']),
            strong: $($Script:PasswordLengthModifiers['strong'])
        };

        const passwordComplexityModifiers = {
            disabled: $($Script:PasswordComplexityModifiers['disabled']),
            enabled: $($Script:PasswordComplexityModifiers['enabled'])
        };

        const encryptionTypeModifiers = {
            rc4_only: $($Script:EncryptionTypeModifiers['rc4_only']),
            aes128: $($Script:EncryptionTypeModifiers['aes128']),
            aes256: $($Script:EncryptionTypeModifiers['aes256'])
        };

        const securityModifiers = {
            ACCOUNTDISABLE: $($Script:SecurityModifiers['ACCOUNTDISABLE']),
            LOCKOUT: $($Script:SecurityModifiers['LOCKOUT']),
            SMARTCARD_REQUIRED: $($Script:SecurityModifiers['SMARTCARD_REQUIRED']),
            PASSWORD_EXPIRED: $($Script:SecurityModifiers['PASSWORD_EXPIRED']),
            USE_DES_KEY_ONLY: $($Script:SecurityModifiers['USE_DES_KEY_ONLY']),
            NOT_DELEGATED: $($Script:SecurityModifiers['NOT_DELEGATED']),
            PROTECTED_USERS: $($Script:SecurityModifiers['PROTECTED_USERS'])
        };

        const correlationBonus = {
            // Standard correlation (privileged accounts)
            perFinding: $($Script:CorrelationBonus['per_finding']),
            maxBonus: $($Script:CorrelationBonus['max_bonus']),
            // Enhanced correlation for non-admins (potential privilege escalation paths)
            nonAdminPerFinding: $($Script:CorrelationBonus['non_admin_per_finding']),
            nonAdminMaxBonus: $($Script:CorrelationBonus['non_admin_max_bonus']),
            nonAdminThreshold: $($Script:CorrelationBonus['non_admin_threshold'])
        };

        const scoreThresholds = {
            critical: $($Script:ScoreThresholds['critical']),
            high: $($Script:ScoreThresholds['high']),
            medium: $($Script:ScoreThresholds['medium']),
            low: $($Script:ScoreThresholds['low'])
        };
"@

    return $js
}

# =============================================================================
# EXPORT SCORING STATS (for debugging/documentation)
# =============================================================================

function Get-ScoringStats {
    <#
    .SYNOPSIS
        Returns statistics about the scoring definitions.

    .DESCRIPTION
        Extracts statistics from FindingDefinitions BaseScores.

    .EXAMPLE
        Get-ScoringStats
    #>

    $baseScores = Get-FindingBaseScores
    $scoreValues = $baseScores.Values

    [PSCustomObject]@{
        TotalFindings       = $baseScores.Count
        MaxBaseScore        = ($scoreValues | Measure-Object -Maximum).Maximum
        MinBaseScore        = ($scoreValues | Measure-Object -Minimum).Minimum
        AvgBaseScore        = [math]::Round(($scoreValues | Measure-Object -Average).Average, 1)
        ScoreCategories     = @{
            'Critical (80-100)' = ($scoreValues | Where-Object { $_ -ge 80 }).Count
            'High (60-79)'      = ($scoreValues | Where-Object { $_ -ge 60 -and $_ -lt 80 }).Count
            'Medium (40-59)'    = ($scoreValues | Where-Object { $_ -ge 40 -and $_ -lt 60 }).Count
            'Low (20-39)'       = ($scoreValues | Where-Object { $_ -ge 20 -and $_ -lt 40 }).Count
            'Info (0-19)'       = ($scoreValues | Where-Object { $_ -lt 20 }).Count
        }
    }
}



# ----- adPEAS-ObjectTypes.ps1 -----

<#
.SYNOPSIS
    Central ObjectType definitions for adPEAS - Single Source of Truth.

.DESCRIPTION
    This file serves as the Single Source of Truth for all ObjectType definitions.
    Each ObjectType used in Check modules must be defined here with:
    - Module: adPEAS module name (Domain, Creds, Rights, Delegation, ADCS, Accounts, GPO, Computer, Application, Bloodhound)
    - TitleFormat: Template for object card titles (e.g., "User: {Name}")
    - Category: Grouping category for organization
    - SectionTitle: Section header text (for HTML report sections)
    - Summary: Brief description of what the check does
    - WhyItMatters: Security impact explanation
    - WhatWeCheck: Array of bullet points describing the check
    - SecureMessage: (optional) Message shown when finding is secure
    - FilteringNote: (optional) Note about what is filtered from output

    Benefits:
    - Eliminates manual synchronization between Check modules and Export-HTMLReport
    - Build-time validation catches undefined ObjectTypes
    - Consistent title formatting across all reports
    - All metadata in one place for easy maintenance

.NOTES
    Author: Alexander Sturz (@_61106960_)

    How to add a new ObjectType:
    1. Add entry to $Script:ObjectTypeDefinitions below
    2. Use in Check module: $obj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'YourType' -Force
    3. Build will validate that the type exists

    Title format placeholders:
    - {Name}    : Object name (sAMAccountName, Name, displayName, or CN)
    - {Context} : Value from _adPEASContext property (optional)
    - {DN}      : Distinguished Name path (for showing hierarchy)
#>

# Central ObjectType definitions
# Key = ObjectType value used in Check modules
# Value = Hashtable with TitleFormat, Category, SectionTitle, Summary, WhyItMatters, WhatWeCheck, and optional SecureMessage/FilteringNote
$Script:ObjectTypeDefinitions = [ordered]@{

    # ============================================================================
    # DOMAIN CONFIGURATION
    # ============================================================================

    'DomainBasicInfo' = @{
        TitleFormat = "Domain Information"
        Module = "Domain"
        Category = "Domain"
        SectionTitle = "Domain Information"
        Summary = "Gathers basic information about the Active Directory domain."
        WhyItMatters = "Understanding the domain structure, functional levels, and key configurations provides the foundation for all security assessments. Old functional levels may indicate legacy systems with known vulnerabilities."
        WhatWeCheck = @(
            "Domain and forest names, SIDs, and functional levels"
            "Domain Controller locations and FSMO role holders"
            "Anonymous LDAP access settings"
        )
    }

    'KerberosPolicy' = @{
        TitleFormat = "Kerberos Policy"
        Module = "Domain"
        Category = "Domain"
        SectionTitle = "Kerberos Policy"
        Summary = "Reviews Kerberos ticket lifetime and password policies."
        WhyItMatters = "Kerberos policies control ticket lifetimes and the krbtgt password age. Long-lived tickets or old krbtgt passwords increase the window for Golden Ticket attacks."
        WhatWeCheck = @(
            "TGT maximum lifetime (should be 10 hours or less)"
            "TGT renewal lifetime (should be 7 days or less)"
            "krbtgt password age (should be changed at least yearly)"
        )
        SecureMessage = "Kerberos policy settings are properly configured. Ticket lifetimes are within recommended limits and the krbtgt password has been rotated within the last 180 days."
    }

    'GuestAccount' = @{
        TitleFormat = "Guest Account Status"
        Module = "Domain"
        Category = "Domain"
        SectionTitle = "Guest Account Status"
        Summary = "Checks if the built-in Guest account (RID 501) is enabled and reviews group memberships."
        WhyItMatters = "The Guest account allows anonymous access with minimal authentication. An enabled Guest account, especially with privileged group memberships, poses a significant security risk."
        WhatWeCheck = @(
            "Guest account enabled/disabled status"
            "Guest account membership in privileged groups (via Test-IsPrivileged)"
        )
        SecureMessage = "Guest account is disabled (secure default configuration)."
    }

    'DomainControllers' = @{
        TitleFormat = "Domain Controllers"
        Module = "Domain"
        Category = "Domain"
        SectionTitle = "Domain Controllers"
        Summary = "Lists all Domain Controllers in the domain."
        WhyItMatters = "Domain Controllers are Tier-0 assets containing all domain secrets. Understanding the DC infrastructure helps identify critical assets requiring maximum protection."
        WhatWeCheck = @(
            "All computers with the DC role"
            "FSMO role assignments"
            "Global Catalog servers"
        )
    }

    'SitesAndSubnets' = @{
        TitleFormat = "Sites and Subnets: {Name}"
        Module = "Domain"
        Category = "Domain"
        SectionTitle = "Sites and Subnets"
        Summary = "Maps AD Sites with associated IP subnets and Domain Controllers."
        WhyItMatters = "Sites and subnets control DC selection for authentication. Misconfigured subnets can cause clients to authenticate to DCs across WAN links, enabling interception. Knowing which DCs serve which site helps identify lateral movement paths."
        WhatWeCheck = @(
            "All configured AD sites"
            "IP subnet assignments per site"
            "Domain Controllers assigned to each site"
        )
    }

    'DomainPasswordPolicy' = @{
        TitleFormat = "Password Policy"
        Module = "Domain"
        Category = "Domain"
        SectionTitle = "Domain Password Policy"
        Summary = "Reviews the domain's default password policy settings."
        WhyItMatters = "Weak password policies allow users to set easily guessable passwords, making the domain vulnerable to password spraying and brute force attacks."
        WhatWeCheck = @(
            "Minimum password length and complexity requirements"
            "Password history and maximum age settings"
            "Account lockout threshold and duration"
            "Lockout observation window"
        )
        SecureMessage = "The domain password policy meets security best practices with adequate password length (14+ characters), complexity requirements enabled, and appropriate lockout settings configured."
    }

    'FineGrainedPasswordPolicy' = @{
