    'GPOPermission' = @{
        TitleFormat = "GPO Permission: {Name}"
        Module = "GPO"
        Category = "GPO"
        SectionTitle = "GPO Permissions"
        Summary = "Identifies Group Policy Objects with risky permissions."
        WhyItMatters = "GPO modification rights enable code execution on all computers where the GPO is applied. Attackers can deploy malware, create scheduled tasks, or modify security settings."
        WhatWeCheck = @(
            "GPOs with write permissions for non-admins"
            "Which computers/users are affected by each GPO"
            "Potential impact of GPO modification"
        )
        SecureMessage = "No dangerous GPO permissions found. Only privileged accounts have write access to Group Policy Objects."
        PrimaryFindingId = 'GPO_DANGEROUS_PERMISSIONS'
    }

    'GPOLocalGroup' = @{
        TitleFormat = "GPO Local Group: {Name}"
        Module = "GPO"
        Category = "GPO"
        SectionTitle = "GPO Local Group Assignments"
        Summary = "Reviews GPO-based local group membership configurations."
        WhyItMatters = "GPOs can add principals to local Administrators groups on target systems. This is legitimate for administration but dangerous if misconfigured or overly broad."
        WhatWeCheck = @(
            "Restricted Groups settings adding local admins"
            "Group Policy Preferences modifying local groups"
            "Scope of these configurations"
        )
        SecureMessage = "No vulnerable GPO local group assignments found. Local administrator configurations through GPO are properly scoped and controlled."
    }

    'GPOScheduledTask' = @{
        TitleFormat = "GPO Scheduled Task: {Name}"
        Module = "GPO"
        Category = "GPO"
        SectionTitle = "GPO Scheduled Tasks"
        Summary = "Analyzes scheduled tasks deployed via Group Policy."
        WhyItMatters = "GPO scheduled tasks run with specified privileges on target systems. Tasks running as SYSTEM from writable paths or UNC shares enable privilege escalation."
        WhatWeCheck = @(
            "Scheduled tasks in GPO configurations"
            "Execution context (SYSTEM, user, etc.)"
            "Executable paths and whether they're writable"
            "UNC paths that could enable relay attacks"
        )
        SecureMessage = "No vulnerable GPO scheduled tasks found. All scheduled tasks use secure local paths and do not expose systems to privilege escalation through writable paths or UNC relay attacks."
    }

    'GPOScriptPath' = @{
        TitleFormat = "GPO Script: {Name}"
        Module = "GPO"
        Category = "GPO"
        SectionTitle = "GPO Script Paths"
        Summary = "Detects Logon/Logoff/Startup/Shutdown scripts deployed via Group Policy."
        WhyItMatters = "GPO scripts execute automatically on target systems. Startup and Shutdown scripts run as SYSTEM, making them high-value targets for privilege escalation. Scripts loaded from UNC paths expose machine credentials on the network."
        WhatWeCheck = @(
            "Startup/Shutdown scripts (run as SYSTEM)"
            "Logon/Logoff scripts (run as user)"
            "UNC paths (credential exposure risk)"
            "PowerShell scripts via psscripts.ini"
        )
        SecureMessage = "No scripts distributed via GPO. No Logon/Logoff/Startup/Shutdown scripts were found in Group Policy configurations."
    }

    'GPORegistrySetting' = @{
        TitleFormat = "GPO Registry Setting: {Name}"
        Module = "GPO"
        Category = "GPO"
        SectionTitle = "GPO Registry Settings"
        Summary = "Detects security-relevant registry values deployed via Group Policy that, when set, enable an attack."
        WhyItMatters = "Group Policy can push registry values to every linked system. A single value such as WDigest cleartext caching, AlwaysInstallElevated, RDP Restricted Admin, the Zerologon/OneLogon allow-list, Point and Print (PrintNightmare), or WSUS-over-HTTP turns the whole scope into an attack surface for credential theft, lateral movement, or privilege escalation. This check parses both delivery mechanisms (Registry.pol and Registry.xml) and reports only values that are actively set to a dangerous state. It sees what is deployed via GPO, not what is set locally on a host."
        WhatWeCheck = @(
            "Administrative Templates (Registry.pol, PReg binary)"
            "Group Policy Preferences (Registry.xml)"
            "Credential-theft enablers (WDigest, LM/NTLMv1, LSA/Credential Guard disabled)"
            "Lateral-movement enablers (Remote UAC, RDP Restricted Admin, Zerologon allow-list)"
            "Privilege-escalation enablers (AlwaysInstallElevated, Point and Print, WSUS over HTTP)"
        )
        SecureMessage = "No vulnerable registry settings deployed via GPO. No Group Policy was found pushing a registry value in a state that enables an attack."
    }

    'LAPSGPOConfig' = @{
        TitleFormat = "LAPS GPO: {Name}"
        Module = "Computer"
        Category = "Computer"
        SectionTitle = "LAPS GPO Configuration"
        Summary = "Shows the LAPS policy settings deployed via Group Policy and where they apply."
        WhyItMatters = "The LAPS policy in a GPO decides which local account is managed, how strong the password is, and - for Windows LAPS - whether the password is encrypted in Active Directory and escrowed there at all. These settings are readable from SYSVOL without any LAPS password permissions, so they disclose the managed account name and reveal misconfigurations before a single computer object is touched. A policy with encryption disabled writes the password in cleartext to msLAPS-Password, and a policy with the backup target disabled or pointed only at Microsoft Entra ID leaves this Active Directory without any escrowed password despite LAPS appearing to be deployed."
        WhatWeCheck = @(
            "Managed account name (AdminAccountName / AdministratorAccountName)"
            "Windows LAPS AD password encryption and the principal allowed to decrypt"
            "Windows LAPS backup target (Active Directory, Microsoft Entra ID, or disabled)"
            "Password complexity, length, passphrase length and maximum age"
            "Password expiration protection"
            "The OUs, domains and sites each GPO is linked to"
        )
        SecureMessage = "No LAPS policy settings deployed via Group Policy were found."
    }

    # ============================================================================
    # BLOODHOUND COLLECTOR
    # ============================================================================

    'BloodHoundCollector' = @{
        TitleFormat = "BloodHound Collection: {Name}"
        Module = "Bloodhound"
        Category = "BloodHound"
        SectionTitle = "BloodHound Data Collection"
        Summary = "Collects AD data in BloodHound Community Edition format using adPEAS native collector."
        WhyItMatters = "BloodHound enables graph-based attack path analysis. The collected data helps identify privilege escalation paths, ACL abuses, and delegation attacks that might be missed by individual checks."
        WhatWeCheck = @(
            "Users, Groups, Computers, OUs, GPOs, Containers"
            "Group memberships and nested membership chains"
            "ACLs and dangerous permissions (GenericAll, WriteDACL, etc.)"
            "Kerberos delegation configurations (Unconstrained, Constrained, RBCD)"
            "DCOnly mode: No session collection, pure LDAP queries"
        )
        FilteringNote = "adPEAS uses its own native collector (no SharpHound dependency). Collection mode is DCOnly - all data is retrieved via LDAP without requiring local admin access or session enumeration. Output is BloodHound CE v6 JSON format."
    }

    # ============================================================================
    # LDAP STATISTICS
    # ============================================================================

    'LDAPStatisticsModule' = @{
        TitleFormat = "Module: {Name}"
        Module = "Statistics"
        Category = "Statistics"
        SectionTitle = "LDAP Statistics"
        Summary = "LDAP query statistics per module."
        WhyItMatters = "Shows the LDAP query load per module to identify expensive operations and estimate network traffic."
        WhatWeCheck = @(
            "Number of LDAP queries sent"
            "Number of result entries received"
            "Estimated network traffic volume"
        )
    }

    'LDAPStatisticsTotal' = @{
        TitleFormat = "Total"
        Module = "Statistics"
        Category = "Statistics"
        SectionTitle = "LDAP Statistics"
        Summary = "Total LDAP query statistics across all modules."
        WhyItMatters = "Provides a complete picture of the scan's LDAP footprint."
        WhatWeCheck = @(
            "Aggregated LDAP query count and result count"
            "Total estimated network traffic"
        )
    }
}

<#
.SYNOPSIS
    Gets the display title for an AD object based on its ObjectType.

.DESCRIPTION
    Central function for generating object card titles in HTML reports.
    Replaces the switch statement in Export-HTMLReport.ps1 with data-driven approach.

.PARAMETER Object
    The AD object with _adPEASObjectType property.

.OUTPUTS
    String - The formatted title for display.

.EXAMPLE
    $title = Get-ObjectTypeTitle -Object $adObject
#>
function Get-ObjectTypeTitle {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        $Object
    )

    # Get the ObjectType from the object
    $objectType = $Object._adPEASObjectType

    # Get object name (try various properties)
    # Note: displayName comes before Name because GPOs have Name=GUID but displayName=readable name
    # gpoName is used by custom GPO objects (e.g., AddComputerGPO from Get-AddComputerRights)
    $objName = $Object.sAMAccountName
    if (-not $objName) { $objName = $Object.gpoName }
    if (-not $objName) { $objName = $Object.ouName }
    if (-not $objName) { $objName = $Object.displayName }
    if (-not $objName) { $objName = $Object.Name }
    if (-not $objName) {
        # Try to extract from DN
        if ($Object.distinguishedName -match '^CN=([^,]+)') {
            $objName = $Matches[1]
        }
    }
    if (-not $objName) { $objName = "Unknown" }

    # Get context if available
    $context = $Object._adPEASContext
    $contextStr = if ($context) { " ($context)" } else { "" }

    # If no ObjectType defined, return just the name
    if (-not $objectType) {
        return $objName
    }

    # Look up definition
    $definition = $Script:ObjectTypeDefinitions[$objectType]

    if (-not $definition) {
        # Unknown ObjectType - return with warning indicator
        Write-Verbose "[Get-ObjectTypeTitle] Unknown ObjectType: $objectType"
        # Generate title from PascalCase (fallback)
        $autoTitle = $objectType -creplace '([a-z])([A-Z])', '$1 $2'
        return "${autoTitle}: $objName"
    }

    # Format the title using the template
    $title = $definition.TitleFormat

    # Replace placeholders
    $title = $title -replace '\{Name\}', $objName
    $title = $title -replace '\{Context\}', $contextStr

    # Handle {DisplayName} placeholder - prefers displayName over sAMAccountName
    if ($title -match '\{DisplayName\}') {
        $displayName = if ($Object.displayName) { $Object.displayName } else { $objName }
        $title = $title -replace '\{DisplayName\}', $displayName
    }

    # Handle {CAName} placeholder - used by CertificateAuthority titles
    if ($title -match '\{CAName\}') {
        $caName = if ($Object.caName) { $Object.caName } else { $objName }
        $title = $title -replace '\{CAName\}', $caName
    }

    # Handle DN placeholder if present
    if ($title -match '\{DN\}' -and $Object.distinguishedName) {
        # Extract OU path from DN
        $dn = $Object.distinguishedName
        if ($dn -match ',(.+)$') {
            $ouPath = $Matches[1]
            $title = $title -replace '\{DN\}', $ouPath
        } else {
            $title = $title -replace '\{DN\}', ''
        }
    }

    # Generic fallback: resolve any remaining {propertyName} placeholders
    # directly from a matching object property (e.g. {userRightName}, {ComputerName}).
    # Falls back to the object name when the property is absent. Uses literal
    # string replacement so property values containing '$' are not treated as
    # regex replacement tokens.
    foreach ($match in [regex]::Matches($title, '\{(\w+)\}')) {
        $propName = $match.Groups[1].Value
        $propValue = $Object.$propName
        $replacement = if ($propValue) { [string]$propValue } else { $objName }
        $title = $title.Replace($match.Value, $replacement)
    }

    return $title
}


<#
.SYNOPSIS
    Validates that all ObjectTypes used in source files are defined.

.DESCRIPTION
    Build-time validation function that scans source files for _adPEASObjectType
    assignments and verifies each one exists in $Script:ObjectTypeDefinitions.

.PARAMETER SourcePath
    Path to the source directory to scan.

.OUTPUTS
    PSCustomObject with validation results.

.EXAMPLE
    $result = Test-ObjectTypeDefinitions -SourcePath ".\src\modules\Checks"
    if (-not $result.Valid) { throw "ObjectType validation failed" }
#>
function Test-ObjectTypeDefinitions {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$SourcePath
    )

    $results = @{
        Valid = $true
        DefinedTypes = @($Script:ObjectTypeDefinitions.Keys)
        UsedTypes = @()
        UndefinedTypes = @()
        UnusedTypes = @()
        Details = @()
    }

    # Scan all PS1 files for ObjectType assignments
    $files = Get-ChildItem -Path $SourcePath -Filter "*.ps1" -Recurse -ErrorAction SilentlyContinue

    foreach ($file in $files) {
        $content = Get-Content $file.FullName -Raw -ErrorAction SilentlyContinue
        if (-not $content) { continue }

        # Find all _adPEASObjectType assignments
        $regexMatches = [regex]::Matches($content, "'_adPEASObjectType'\s*-NotePropertyValue\s+'([^']+)'")

        foreach ($match in $regexMatches) {
            $objectType = $match.Groups[1].Value

            if ($objectType -notin $results.UsedTypes) {
                $results.UsedTypes += $objectType
            }

            if (-not $Script:ObjectTypeDefinitions.Contains($objectType)) {
                $results.Valid = $false
                if ($objectType -notin $results.UndefinedTypes) {
                    $results.UndefinedTypes += $objectType
                    $results.Details += [PSCustomObject]@{
                        Type = "Undefined"
                        ObjectType = $objectType
                        File = $file.Name
                        Line = ($content.Substring(0, $match.Index) -split "`n").Count
                    }
                }
            }
        }
    }

    # Find unused definitions
    foreach ($definedType in $results.DefinedTypes) {
        if ($definedType -notin $results.UsedTypes) {
            $results.UnusedTypes += $definedType
        }
    }

    return [PSCustomObject]$results
}


<#
.SYNOPSIS
    Gets the list of all defined ObjectTypes.

.DESCRIPTION
    Returns all ObjectType keys defined in $Script:ObjectTypeDefinitions.
    Useful for documentation and validation.

.OUTPUTS
    String[] - Array of ObjectType names.
#>
function Get-DefinedObjectTypes {
    return @($Script:ObjectTypeDefinitions.Keys | Sort-Object)
}


<#
.SYNOPSIS
    Gets the category for an ObjectType.

.DESCRIPTION
    Returns the category associated with an ObjectType, or "Unknown" if not defined.

.PARAMETER ObjectType
    The ObjectType to look up.

.OUTPUTS
    String - The category name.
#>
function Get-ObjectTypeCategory {
    param([string]$ObjectType)

    $definition = $Script:ObjectTypeDefinitions[$ObjectType]
    if ($definition -and $definition.Category) {
        return $definition.Category
    }
    return "Unknown"
}


<#
.SYNOPSIS
    Gets the check description for a specific ObjectType.

.DESCRIPTION
    Returns the full definition hashtable for an ObjectType including
    SectionTitle, Summary, WhyItMatters, WhatWeCheck, and optional fields.

.PARAMETER ObjectType
    The _adPEASObjectType value.

.OUTPUTS
    Hashtable with check description or $null if not found.

.EXAMPLE
    $desc = Get-CheckDescription -ObjectType 'Kerberoastable'
#>
function Get-CheckDescription {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$ObjectType
    )

    if ($Script:ObjectTypeDefinitions.Contains($ObjectType)) {
        return $Script:ObjectTypeDefinitions[$ObjectType]
    }
    return $null
}


<#
.SYNOPSIS
    Gets all available ObjectTypes with descriptions.

.DESCRIPTION
    Returns all ObjectType keys defined in $Script:ObjectTypeDefinitions.

.OUTPUTS
    Array of ObjectType strings.

.EXAMPLE
    $types = Get-CheckObjectTypes
#>
function Get-CheckObjectTypes {
    [CmdletBinding()]
    param()

    return $Script:ObjectTypeDefinitions.Keys | Sort-Object
}


<#
.SYNOPSIS
    Exports check descriptions as JSON for embedding in HTML.

.DESCRIPTION
    Converts all ObjectType definitions to a JSON format suitable for
    embedding in HTML reports for JavaScript-based tooltip display.

.PARAMETER Minified
    If set, outputs minified JSON without indentation.

.OUTPUTS
    JSON string of all check descriptions keyed by ObjectType.

.EXAMPLE
    $json = Export-CheckDescriptionsJson -Minified
#>
function Export-CheckDescriptionsJson {
    [CmdletBinding()]
    param(
        [switch]$Minified
    )

    # Convert hashtable to format suitable for JSON
    $jsonObject = @{}

    foreach ($key in $Script:ObjectTypeDefinitions.Keys) {
        $desc = $Script:ObjectTypeDefinitions[$key]

        $jsonObject[$key] = @{
            title = $desc.SectionTitle
            summary = $desc.Summary
            whyItMatters = $desc.WhyItMatters
            whatWeCheck = $desc.WhatWeCheck
        }

        # Include FilteringNote only when privilege filtering is active (not -IncludePrivileged)
        # When -IncludePrivileged is used, privileged accounts ARE shown, so the note is misleading
        if ($desc.FilteringNote -and -not $Script:IncludePrivilegedMode) {
            $jsonObject[$key].filteringNote = $desc.FilteringNote
        }

        # Include SecureMessage if present (explains why secure finding is good)
        if ($desc.SecureMessage) {
            $jsonObject[$key].secureMessage = $desc.SecureMessage
        }

        # Include PrimaryFindingId if present (overrides automatic findingId detection in Top Priority Actions)
        if ($desc.PrimaryFindingId) {
            $jsonObject[$key].primaryFindingId = $desc.PrimaryFindingId
        }
    }

    if ($Minified) {
        return ($jsonObject | ConvertTo-Json -Depth 10 -Compress)
    } else {
        return ($jsonObject | ConvertTo-Json -Depth 10)
    }
}





# ----- adPEAS-SoftwareLifecycle.ps1 -----

<#
.SYNOPSIS
    Central Software Lifecycle definitions for adPEAS.

.DESCRIPTION
    This file serves as the Single Source of Truth for software End-of-Life dates.
    Used by Check modules and severity classification (Get-AttributeSeverity).

    Supported Software:
    - Windows Client Operating Systems
    - Windows Server Operating Systems
    - Microsoft Exchange Server

.NOTES
    Author: Alexander Sturz (@_61106960_)
    References:
    - Windows: https://learn.microsoft.com/en-us/lifecycle/products/
    - Exchange: https://learn.microsoft.com/en-us/exchange/new-features/build-numbers-and-release-dates

    How to add new software:
    1. Add entry to appropriate $Script:*Lifecycle hashtable below
    2. Add normalization pattern to Get-Normalized*Name function if needed
    3. Update regex patterns in AttributeTransformers.ps1 (Get-AttributeSeverity) if needed for severity classification
#>

# =============================================================================
# WINDOWS LIFECYCLE DATA
# =============================================================================
# Key = Normalized OS name (as returned by Get-NormalizedOSName)
# Value = End-of-Support date (extended support end, not mainstream)
#
# Note: Dates are when ALL support ends (including ESU where applicable)

$Script:WindowsLifecycle = @{
    # ===== Windows Client =====
    'Windows XP'           = '2014-04-08'   # Extended support ended
    'Windows Vista'        = '2017-04-11'   # Extended support ended
    'Windows 7'            = '2023-01-10'   # ESU Year 3 ended (was 2020-01-14 without ESU)
    'Windows 8'            = '2016-01-12'   # No extended support (upgrade to 8.1 required)
    'Windows 8.1'          = '2023-01-10'   # Extended support ended
    'Windows 10'           = '2025-10-14'   # End of support for non-LTSC (final SAC version)

    # Windows 10 LTSC editions have extended support lifecycles
    # Identified by "LTSC" in operatingSystem AND build number in operatingSystemVersion
    'Windows 10 LTSC 2015' = '2025-10-14'   # Build 10240 (version 1507)
    'Windows 10 LTSC 2016' = '2026-10-13'   # Build 14393 (version 1607)
    'Windows 10 LTSC 2019' = '2029-01-09'   # Build 17763 (version 1809)
    'Windows 10 LTSC 2021' = '2027-01-12'   # Build 19044 (version 21H2)

    # ===== Windows Server =====
    'Windows Server 2003'    = '2015-07-14'   # Extended support ended
    'Windows Server 2008'    = '2023-01-10'   # ESU Year 3 ended (was 2020-01-14 without ESU)
    'Windows Server 2008 R2' = '2023-01-10'   # ESU Year 3 ended (was 2020-01-14 without ESU)
    'Windows Server 2012'    = '2026-10-13'   # ESU Year 3 ends (was 2023-10-10 without ESU)
    'Windows Server 2012 R2' = '2026-10-13'   # ESU Year 3 ends (was 2023-10-10 without ESU)
    'Windows Server 2016'    = '2027-01-12'   # Extended support ends

    # ===== Currently Supported (no EOL date yet or far future) =====
    # Windows 11           - Support ongoing (version-dependent)
    # Windows Server 2019  - Extended support: 2029-01-09
    # Windows Server 2022  - Extended support: 2031-10-14
    # Windows Server 2025  - Extended support: TBD
}

# =============================================================================
# EXCHANGE LIFECYCLE DATA
# =============================================================================
# Key = Normalized Exchange version (as returned by Get-NormalizedExchangeVersion)
# Value = Hashtable with EOLDate and optional metadata
#
# Exchange versions are identified by:
# - Version string from msExchVersion attribute
# - Build number prefix (e.g., "15.1" for Exchange 2016)
# - Product name from HTTP detection

$Script:ExchangeLifecycle = @{
    # ===== End-of-Life Versions =====
    # Severity values match Show-Line system: Finding (red), Hint (yellow), Note (green), Secure (highlight)
    'Exchange 2007' = @{
        EOLDate = '2017-04-11'
        BuildPrefix = '8.'
        Severity = 'Finding'      # EOL - critical security risk
    }
    'Exchange 2010' = @{
        EOLDate = '2020-10-13'
        BuildPrefix = '14.'
        Severity = 'Finding'      # EOL - critical security risk
    }
    'Exchange 2013' = @{
        EOLDate = '2023-04-11'
        BuildPrefix = '15.0.'
        Severity = 'Finding'      # EOL - critical security risk
    }
    'Exchange 2016' = @{
        EOLDate = '2025-10-14'
        BuildPrefix = '15.1.'
        Severity = 'Finding'      # EOL October 2025 - upgrade urgently recommended
    }
    'Exchange 2019' = @{
        EOLDate = '2025-10-14'
        BuildPrefix = '15.2.'
        BuildMax = 2561           # Builds below 2562 are Exchange 2019 (CU15 = 15.2.1748.x)
        Severity = 'Hint'         # EOL October 2025 - upgrade to SE recommended
    }

    # ===== Currently Supported =====
    'Exchange SE' = @{
        EOLDate = $null           # Currently supported
        BuildPrefix = '15.2.'
        BuildMin = 2562           # Builds 2562+ are Exchange SE (SE RTM = 15.2.2562.17)
        Severity = 'Standard'     # Current supported version
    }
}

# =============================================================================
# WINDOWS OS NAME NORMALIZATION
# =============================================================================
<#
.SYNOPSIS
    Normalizes an OS name from AD to a lifecycle lookup key.

.DESCRIPTION
    AD stores OS names with version details (e.g., "Windows Server 2019 Datacenter").
    This function extracts the base OS name for lifecycle lookup.

    For Windows 10 LTSC editions, the build number from operatingSystemVersion is used
    to determine the specific LTSC release (2015/2016/2019/2021) since each has a
    different extended support end date.

.PARAMETER OSName
    The operatingSystem attribute value from AD.

.PARAMETER OSVersion
    The operatingSystemVersion attribute from AD (e.g., "10.0 (17763)").
    Required for correct Windows 10 LTSC identification.

.OUTPUTS
    String - Normalized OS name matching $Script:WindowsLifecycle keys.

.EXAMPLE
    Get-NormalizedOSName -OSName "Windows Server 2012 R2 Standard"
    # Returns: "Windows Server 2012 R2"

.EXAMPLE
    Get-NormalizedOSName -OSName "Windows 10 Enterprise LTSC" -OSVersion "10.0 (17763)"
    # Returns: "Windows 10 LTSC 2019"
#>
function Get-NormalizedOSName {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$OSName,

        [Parameter(Mandatory=$false)]
        [string]$OSVersion
    )

    # Normalize OS name for lifecycle lookup
    switch -Regex ($OSName) {
        # Windows Client - order matters (8.1 before 8)
        '^Windows XP'               { return 'Windows XP' }
        '^Windows Vista'            { return 'Windows Vista' }
        '^Windows 7'                { return 'Windows 7' }
        '^Windows 8\.1'             { return 'Windows 8.1' }
        '^Windows 8[^.]'            { return 'Windows 8' }
        '^Windows 10' {
            # Check for LTSC editions (have much longer support than SAC)
            if ($OSName -match 'LTSC') {
                # Map build number to LTSC release year
                $buildNumber = 0
                if ($OSVersion -match '\((\d+)\)') {
                    $buildNumber = [int]$Matches[1]
                }
                # LTSC 2019: Build 17763 (version 1809) - EOL 2029-01-09
                if ($buildNumber -ge 17763 -and $buildNumber -lt 19044) { return 'Windows 10 LTSC 2019' }
                # LTSC 2021: Build 19044 (version 21H2) - EOL 2027-01-12
                if ($buildNumber -ge 19044) { return 'Windows 10 LTSC 2021' }
                # LTSC 2016: Build 14393 (version 1607) - EOL 2026-10-13
                if ($buildNumber -ge 14393 -and $buildNumber -lt 17763) { return 'Windows 10 LTSC 2016' }
                # LTSC 2015: Build 10240 (version 1507) - EOL 2025-10-14
                if ($buildNumber -ge 10240 -and $buildNumber -lt 14393) { return 'Windows 10 LTSC 2015' }
                # Unknown LTSC build - fall through to generic Windows 10
            }
            return 'Windows 10'
        }
        '^Windows 11'               { return 'Windows 11' }

        # Windows Server - order matters (R2 before base version)
        '^Windows Server 2003'      { return 'Windows Server 2003' }
        '^Windows Server 2008 R2'   { return 'Windows Server 2008 R2' }
        '^Windows Server 2008'      { return 'Windows Server 2008' }
        '^Windows Server 2012 R2'   { return 'Windows Server 2012 R2' }
        '^Windows Server 2012'      { return 'Windows Server 2012' }
        '^Windows Server 2016'      { return 'Windows Server 2016' }
        '^Windows Server 2019'      { return 'Windows Server 2019' }
        '^Windows Server 2022'      { return 'Windows Server 2022' }
        '^Windows Server 2025'      { return 'Windows Server 2025' }

        # Default: return as-is (for unknown OS types)
        default                     { return $OSName }
    }
}

# =============================================================================
# EXCHANGE VERSION NORMALIZATION
# =============================================================================
<#
.SYNOPSIS
    Normalizes an Exchange version/build to a lifecycle lookup key.

.DESCRIPTION
    Exchange versions can be identified by build numbers (e.g., "15.1.2507.27") or product names.
    This function normalizes to a lifecycle key.

.PARAMETER BuildNumber
    The Exchange build number (e.g., "15.1.2507.27" or "15.2.1544.11").

.PARAMETER ProductName
    The Exchange product name (e.g., "Exchange 2016", "Microsoft Exchange Server 2019").

.OUTPUTS
    String - Normalized Exchange version matching $Script:ExchangeLifecycle keys.

.EXAMPLE
    Get-NormalizedExchangeVersion -BuildNumber "15.1.2507.27"
    # Returns: "Exchange 2016"

.EXAMPLE
    Get-NormalizedExchangeVersion -BuildNumber "15.2.2562.1"
    # Returns: "Exchange SE"
#>
function Get-NormalizedExchangeVersion {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$BuildNumber,

        [Parameter(Mandatory=$false)]
        [string]$ProductName
    )

    # Try build number first (most reliable)
    if (-not [string]::IsNullOrEmpty($BuildNumber)) {
        # Exchange 2007: 8.x
        if ($BuildNumber -match '^8\.') {
            return 'Exchange 2007'
        }
        # Exchange 2010: 14.x
        if ($BuildNumber -match '^14\.') {
            return 'Exchange 2010'
        }
        # Exchange 2013: 15.0.x
        if ($BuildNumber -match '^15\.0\.') {
            return 'Exchange 2013'
        }
        # Exchange 2016: 15.1.x
        if ($BuildNumber -match '^15\.1\.') {
            return 'Exchange 2016'
        }
        # Exchange 2019 vs SE: 15.2.x - differentiate by build
        # SE RTM starts at 15.2.2562.17 (July 2025)
        # Exchange 2019 CU15 is 15.2.1748.x
        if ($BuildNumber -match '^15\.2\.(\d+)') {
            $minorBuild = [int]$Matches[1]
            if ($minorBuild -ge 2562) {
                return 'Exchange SE'
            } else {
                return 'Exchange 2019'
            }
        }
    }

    # Fallback to product name
    if (-not [string]::IsNullOrEmpty($ProductName)) {
        if ($ProductName -match 'Exchange.*2007') { return 'Exchange 2007' }
        if ($ProductName -match 'Exchange.*2010') { return 'Exchange 2010' }
        if ($ProductName -match 'Exchange.*2013') { return 'Exchange 2013' }
        if ($ProductName -match 'Exchange.*2016') { return 'Exchange 2016' }
        if ($ProductName -match 'Exchange.*2019') { return 'Exchange 2019' }
        if ($ProductName -match 'Exchange.*SE|Subscription') { return 'Exchange SE' }
    }

    return $null
}

# =============================================================================
# WINDOWS EOL CHECK FUNCTIONS
# =============================================================================
<#
.SYNOPSIS
    Tests if a Windows operating system is past its End-of-Life date.

.DESCRIPTION
    Checks the Windows lifecycle data to determine if an OS has reached EOL.
    Returns detailed information about the EOL status.

    For Windows 10 LTSC editions, the OSVersion parameter is critical for correct
    EOL determination since each LTSC release has a different support end date.

.PARAMETER OSName
    The operatingSystem attribute value from AD (will be normalized internally).

.PARAMETER OSVersion
    The operatingSystemVersion attribute from AD (e.g., "10.0 (17763)").
    Required for correct Windows 10 LTSC identification.

.PARAMETER ReferenceDate
    The date to compare against (default: current date).

.OUTPUTS
    PSCustomObject with properties:
    - IsOutdated: $true if OS is past EOL
    - NormalizedOS: The normalized OS name
    - EOLDate: The EOL date (or $null if not in lifecycle data)
    - DaysSinceEOL: Days since EOL (negative if not yet EOL)
    - HasLifecycleData: $true if OS is in lifecycle database

.EXAMPLE
    Test-IsOutdatedOS -OSName "Windows Server 2012 R2 Standard"
    # Returns object with IsOutdated = $true (as of 2024+)

.EXAMPLE
    Test-IsOutdatedOS -OSName "Windows 10 Enterprise LTSC" -OSVersion "10.0 (17763)"
    # Returns object with IsOutdated = $false (LTSC 2019 EOL is 2029-01-09)
#>
function Test-IsOutdatedOS {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$OSName,

        [Parameter(Mandatory=$false)]
        [string]$OSVersion,

        [Parameter(Mandatory=$false)]
        [DateTime]$ReferenceDate = (Get-Date)
    )

    $normalizedOS = Get-NormalizedOSName -OSName $OSName -OSVersion $OSVersion

    $result = [PSCustomObject]@{
        IsOutdated = $false
        NormalizedOS = $normalizedOS
        EOLDate = $null
        DaysSinceEOL = $null
        HasLifecycleData = $false
    }

    if ($Script:WindowsLifecycle.ContainsKey($normalizedOS)) {
        $result.HasLifecycleData = $true
        $eolDate = [DateTime]::ParseExact($Script:WindowsLifecycle[$normalizedOS], 'yyyy-MM-dd', $null)
        $result.EOLDate = $eolDate

        $daysDiff = ($ReferenceDate - $eolDate).Days
        $result.DaysSinceEOL = $daysDiff

        if ($daysDiff -gt 0) {
            $result.IsOutdated = $true
        }
    }

    return $result
}

# =============================================================================
# EXCHANGE EOL CHECK FUNCTIONS
# =============================================================================
<#
.SYNOPSIS
    Gets the recommended severity for an Exchange version.

.PARAMETER BuildNumber
    The Exchange build number.

.PARAMETER ProductName
    The Exchange product name (fallback).

.OUTPUTS
    String - Severity class (Critical, Finding, Hint, Standard)
#>
function Get-ExchangeSeverity {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$BuildNumber,

        [Parameter(Mandatory=$false)]
        [string]$ProductName
    )

    $normalizedVersion = Get-NormalizedExchangeVersion -BuildNumber $BuildNumber -ProductName $ProductName

    if ($normalizedVersion -and $Script:ExchangeLifecycle.ContainsKey($normalizedVersion)) {
        return $Script:ExchangeLifecycle[$normalizedVersion].Severity
    }

    return 'Standard'
}


# ----- adPEAS-Messages.ps1 -----

<#
.SYNOPSIS
    Output functions and message templates for adPEAS v2.

.DESCRIPTION
    This module provides the central output functions and message templates for adPEAS v2.

    OUTPUT FUNCTIONS (delegate to RenderModel pipeline):
    - Show-Output    - Low-level output with full control
    - Show-Line      - Single line output with optional styling
    - Show-KeyValue  - Key-value pairs with alignment
    - Show-Object    - AD object output with all properties
    - Show-Header    - Main section headers (+++++ text +++++)
    - Show-SubHeader - Sub-section headers

    Output Architecture:
    - adPEAS-Types.ps1         - Constants, helpers, Finding schema
    - Write-adPEASOutput.ps1   - Pure output (console, file)
    - Get-RenderModel.ps1      - RenderModel builder (enrichment, classification)
    - Render-ConsoleObject.ps1 - Console renderer
    - Render-HtmlObject.ps1    - HTML renderer

    Output Classes (compatible with adPEAS v1):
    - [?] Info (Blue)       - Section headers (with ++++)
    - [?] SubInfo (Blue)    - Sub-task headers (without ++++)
    - [!] Finding (Red)     - Vulnerabilities
    - [+] Hint (Yellow)     - Interesting findings
    - [*] Note (Green)      - General information
    - [#] Secure (RedYellow)- Secure configuration

    MESSAGE TEMPLATES:
    - Show-Message: Central function for Error/Warning/Success/Info messages
    - Show-NoSessionError: No active session errors
    - Show-Error: Unified error function
    - Show-DisconnectError: Disconnect failure messages
    - Show-NoParametersError: Missing parameters errors
    - Get-adPEASHelp: Help overview with -Section parameter (QuickStart, Checks, Commands)

    FINDINGS COLLECTION (for HTML/JSON export):
    - Initialize-FindingsCollection: Start collecting findings
    - Add-Finding: Add a finding to the collection (called automatically)
    - Get-FindingsCollection: Retrieve all collected findings
    - Clear-FindingsCollection: Clear the collection

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# ============================================================================
# Findings Collection System
# ============================================================================
# This system collects findings in parallel to console/file output.
# It enables HTML and JSON report generation without modifying Check-Modules.
#
# Design: "Tap into the Output Layer"
# - Check-Modules call Show-Object, Show-Line as before (unchanged)
# - Show-Output intercepts and collects findings when enabled
# - After all checks, Export-HTMLReport uses the collection

# Module-level variables for findings collection (Script scope - shared across all functions in the standalone .ps1)
$Script:adPEAS_FindingsCollection = $null
$Script:adPEAS_FindingsCollectionEnabled = $false
$Script:adPEAS_CurrentCheckContext = $null

<#
.SYNOPSIS
    Initializes the findings collection system.
.DESCRIPTION
    Call this before running checks to enable findings collection.
    The collection stores all findings for later export to HTML/JSON.
.EXAMPLE
    Initialize-FindingsCollection
    Invoke-adPEAS -Domain "contoso.com"
    $findings = Get-FindingsCollection
#>
function Initialize-FindingsCollection {
    [CmdletBinding()]
    param()

    $Script:adPEAS_FindingsCollection = [System.Collections.ArrayList]::new()
    $Script:adPEAS_FindingsCollectionEnabled = $true
    $Script:adPEAS_CurrentCheckContext = $null
    Write-Log "[FindingsCollection] Initialized"
}

<#
.SYNOPSIS
    Sets the current check context for findings collection.
.DESCRIPTION
    Called by Invoke-adPEAS before each check to provide context (category, check name, title) for collected findings.
.PARAMETER Category
    The module category (e.g., "Accounts", "Delegation", "ADCS")
.PARAMETER CheckName
    The function name (e.g., "Get-KerberoastableAccounts")
.PARAMETER Title
    Human-readable title for the check
#>
function Set-CheckContext {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Category,

        [Parameter(Mandatory=$true)]
        [string]$CheckName,

        [Parameter(Mandatory=$false)]
        [string]$Title = ""
    )

    $Script:adPEAS_CurrentCheckContext = @{
        Category  = $Category
        CheckName = $CheckName
        Title     = if ($Title) { $Title } else { $CheckName }
        Timestamp = Get-Date
    }
}

<#
.SYNOPSIS
    Clears the current check context.
.DESCRIPTION
    Called by Invoke-adPEAS after each check completes.
#>
function Clear-CheckContext {
    [CmdletBinding()]
    param()

    $Script:adPEAS_CurrentCheckContext = $null
}

<#
.SYNOPSIS
    Adds a finding to the collection.
.DESCRIPTION
    Internal function called by Show-Output when collection is enabled.
    Captures the object, severity class, and current check context.
.PARAMETER Object
    The AD object or finding data.
.PARAMETER Class
    The severity class (Finding, Hint, Note, etc.)
.PARAMETER Text
    Text message (for Show-Line calls)
.PARAMETER Key
    Key name (for Show-KeyValue calls)
.PARAMETER Value
    Value (for Show-KeyValue calls)
#>
function Add-Finding {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        $Object,

        [Parameter(Mandatory=$false)]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [string]$Text,

        [Parameter(Mandatory=$false)]
        [string]$Key,

        [Parameter(Mandatory=$false)]
        [string]$Value,

        [Parameter(Mandatory=$false)]
        [string]$FindingId,

        [Parameter(Mandatory=$false)]
        [string]$ObjectType,

        [Parameter(Mandatory=$false)]
        $RenderModel
    )

    if (-not $Script:adPEAS_FindingsCollectionEnabled) { return }
    if ($null -eq $Script:adPEAS_FindingsCollection) { return }

    # Skip Standard class without Object AND without Key (neutral text like "Executing Modules: Domain")
    # But keep KeyValue pairs with Standard class (they contain useful data)
    if (-not $Object -and -not $Key -and $Class -eq "Standard") { return }

    # Determine type and severity
    $entryType = switch ($Class) {
        "Info"    { "Header" }      # Main section header
        "SubInfo" { "SubHeader" }   # Sub-section header
        default   { if ($Object) { "Object" } elseif ($Key) { "KeyValue" } else { "Line" } }
    }

    # Use original adPEAS class names as severity (Finding, Hint, Note, Secure)
    $severity = switch ($Class) {
        "Finding" { "Finding" }     # [!] Red - Vulnerabilities
        "Hint"    { "Hint" }        # [+] Yellow - Interesting findings
        "Note"    { "Note" }        # [*] Green - General information
        "Secure"  { "Secure" }      # [#] RedYellow - Secure configuration
        "Info"    { "Header" }      # Special marker for headers
        "SubInfo" { "SubHeader" }   # Special marker for sub-headers
        "Standard" { "Standard" }
        default   { "Note" }
    }

    # Derive attribute severities from RenderModel if available, otherwise use legacy function
    $attributeSeverities = $null
    if ($RenderModel) {
        # Derive from RenderModel - Single Source of Truth
        $attributeSeverities = @{}
        foreach ($row in @($RenderModel.Primary) + @($RenderModel.Extended) + @($RenderModel.PostObject)) {
            if ($row.OverallSeverity -ne 'Standard') {
                $attributeSeverities[$row.RawName] = $row.OverallSeverity
            }
        }
    } elseif ($Object) {
        # Legacy fallback - inline severity calculation (Get-ObjectAttributeSeverities was removed)
        $attributeSeverities = @{}
        foreach ($prop in $Object.PSObject.Properties) {
            if ($null -eq $prop.Value) { continue }
            $sev = Get-AttributeSeverity -Name $prop.Name -Value $prop.Value -SourceObject $Object
            if ($sev -ne "Standard") { $attributeSeverities[$prop.Name] = $sev }
        }
    }

    # Build the finding entry
    $finding = [PSCustomObject]@{
        Timestamp           = Get-Date
        Category            = if ($Script:adPEAS_CurrentCheckContext) { $Script:adPEAS_CurrentCheckContext.Category } else { "Unknown" }
        CheckName           = if ($Script:adPEAS_CurrentCheckContext) { $Script:adPEAS_CurrentCheckContext.CheckName } else { "Unknown" }
        CheckTitle          = if ($Script:adPEAS_CurrentCheckContext) { $Script:adPEAS_CurrentCheckContext.Title } else { "Unknown" }
        Severity            = $severity
        Class               = $Class
        Type                = $entryType
        Object              = $Object
        Text                = $Text
        Key                 = $Key
        Value               = $Value
        AttributeSeverities = $attributeSeverities  # Pre-calculated attribute classifications
        FindingId           = $FindingId            # Reference to FindingDefinitions for detailed tooltips
        ObjectType          = $ObjectType           # Direct ObjectType for SubHeader tooltip lookup (preferred over title mapping)
        RenderModel         = $RenderModel          # Cached RenderModel for HTML rendering (avoids re-computation)
    }

    [void]$Script:adPEAS_FindingsCollection.Add($finding)
    Write-Verbose "[FindingsCollection] Added: $($finding.Type) - $($finding.Class) - $Text$Key$(if($ObjectType){" ObjectType=$ObjectType"})"
}

<#
.SYNOPSIS
    Retrieves the collected findings.
.DESCRIPTION
    Returns all findings collected since Initialize-FindingsCollection was called.
.EXAMPLE
    $findings = Get-FindingsCollection
    $findings | Where-Object Severity -eq "Critical"
#>
function Get-FindingsCollection {
    [CmdletBinding()]
    param()

    if ($null -eq $Script:adPEAS_FindingsCollection) {
        return @()
    }

    return $Script:adPEAS_FindingsCollection.ToArray()
}

<#
.SYNOPSIS
    Clears the findings collection.
.DESCRIPTION
    Resets the collection and disables collection mode.
#>
function Clear-FindingsCollection {
    [CmdletBinding()]
    param()

    $Script:adPEAS_FindingsCollection = $null
    $Script:adPEAS_FindingsCollectionEnabled = $false
    $Script:adPEAS_CurrentCheckContext = $null
    Write-Log "[FindingsCollection] Cleared"
}

# ============================================================================
# Findings Cache Functions (for -OutputAppend)
# ============================================================================
# These functions enable persisting findings between Invoke-adPEAS runs.
# A JSON cache file stores serialized findings alongside the HTML report.
# On subsequent runs with -OutputAppend, previous findings are loaded,
# merged with current findings (replacing by module/category), and re-exported.

<#
.SYNOPSIS
    Replaces the current in-memory findings collection.
.DESCRIPTION
    Overwrites the findings collection with a new set of findings.
    Used by the -OutputAppend feature to inject merged findings.
#>
function Set-FindingsCollection {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [array]$Findings
    )

    $Script:adPEAS_FindingsCollection = [System.Collections.ArrayList]@($Findings)
    Write-Log "[FindingsCollection] Set to $($Findings.Count) findings"
}

<#
.SYNOPSIS
    Exports the current findings collection to a JSON cache file.
.DESCRIPTION
    Serializes all collected findings to a JSON file for persistence between runs.
    AD objects are serialized as property hashtables, RenderModel is excluded
    (it will be re-computed by Export-HTMLReport via Get-RenderModel).
.PARAMETER Path
    Path for the JSON cache file.
#>
function Export-FindingsCache {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path
    )

    $findings = Get-FindingsCollection
    $serializable = foreach ($f in $findings) {
        $objectProps = $null
        if ($f.Object) {
            $objectProps = @{}
            foreach ($p in $f.Object.PSObject.Properties) {
                # Serialize primitive types directly, convert complex types to string
                if ($p.Value -is [System.Collections.IDictionary] -or
                    $p.Value -is [array] -or
                    $p.Value -is [string] -or
                    $p.Value -is [int] -or $p.Value -is [long] -or
                    $p.Value -is [bool] -or $p.Value -is [datetime] -or
                    $null -eq $p.Value) {
                    $objectProps[$p.Name] = $p.Value
                } else {
                    $objectProps[$p.Name] = $p.Value.ToString()
                }
            }
        }

        @{
            Timestamp           = $f.Timestamp.ToString('o')
            Category            = $f.Category
            CheckName           = $f.CheckName
            CheckTitle          = $f.CheckTitle
            Severity            = $f.Severity
            Class               = $f.Class
            Type                = $f.Type
            Text                = $f.Text
            Key                 = $f.Key
            Value               = $f.Value
            FindingId           = $f.FindingId
            ObjectType          = $f.ObjectType
            AttributeSeverities = $f.AttributeSeverities
            ObjectProperties    = $objectProps
        }
    }

    $cache = @{
        CacheVersion  = 1
        ExportDate    = (Get-Date).ToString('o')
        Domain        = if ($Script:LDAPContext) { $Script:LDAPContext.Domain } else { 'Unknown' }
        Server        = if ($Script:LDAPContext) { $Script:LDAPContext.Server } else { 'Unknown' }
        adPEASVersion = if ($Script:adPEASVersion) { $Script:adPEASVersion } else { 'Unknown' }
        FindingCount  = $serializable.Count
        Findings      = @($serializable)
    }

    $json = $cache | ConvertTo-Json -Depth 5 -Compress
    $utf8NoBom = New-Object System.Text.UTF8Encoding $false
    $resolvedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($Path)
    [System.IO.File]::WriteAllText($resolvedPath, $json, $utf8NoBom)
    Write-Log "[FindingsCache] Exported $($serializable.Count) findings to '$Path'"
}

<#
.SYNOPSIS
    Imports findings from a JSON cache file.
.DESCRIPTION
    Reads a JSON cache file and delegates to Import-FindingsFromCache for deserialization.
    Includes version check and domain mismatch warning.
.PARAMETER Path
    Path to the JSON cache file.
#>
function Import-FindingsCache {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path
    )

    $raw = Get-Content -Path $Path -Raw -Encoding UTF8
    $cache = $raw | ConvertFrom-Json

    # Version check
    if ($cache.CacheVersion -ne 1) {
        Write-Warning "[FindingsCache] Unsupported cache version $($cache.CacheVersion) - expected 1"
        return @()
    }

    # Domain mismatch warning
    $currentDomain = if ($Script:LDAPContext) { $Script:LDAPContext.Domain } else { $null }
    if ($currentDomain -and $cache.Domain -and $cache.Domain -ne $currentDomain -and $cache.Domain -ne 'Unknown') {
        Write-Warning "[FindingsCache] Cache domain '$($cache.Domain)' differs from current domain '$currentDomain'"
        Write-Warning "[FindingsCache] Continuing with merge - findings may be from different domains"
    }

    $result = Import-FindingsFromCache -Cache $cache
    Write-Log "[FindingsCache] Loaded $(@($result).Count) findings from '$Path'"
    return @($result)
}

<#
.SYNOPSIS
    Imports findings from an already-parsed JSON cache object.
.DESCRIPTION
    Reconstructs finding objects from a deserialized cache.
    Used by Import-FindingsCache (file-based) and Convert-adPEASReport (pre-parsed).
    AD objects are reconstructed using hashtable construction (24x faster than Add-Member).
    RenderModel is set to $null and will be re-computed during HTML export.
.PARAMETER Cache
    The deserialized cache object (from ConvertFrom-Json).
#>
function Import-FindingsFromCache {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Cache
    )

    $result = foreach ($f in $Cache.Findings) {
        # Reconstruct AD-Object from serialized properties using hashtable construction
        $adObject = $null
        if ($f.ObjectProperties) {
            $props = @{}
            foreach ($p in $f.ObjectProperties.PSObject.Properties) {
                $props[$p.Name] = $p.Value
            }
            $adObject = [PSCustomObject]$props
        }

        # Reconstruct AttributeSeverities as hashtable (ConvertFrom-Json returns PSCustomObject)
        $attrSev = $null
        if ($f.AttributeSeverities) {
            $attrSev = @{}
            foreach ($p in $f.AttributeSeverities.PSObject.Properties) {
                $attrSev[$p.Name] = $p.Value
            }
        }

        [PSCustomObject]@{
            Timestamp           = [datetime]::Parse($f.Timestamp)
            Category            = $f.Category
            CheckName           = $f.CheckName
            CheckTitle          = $f.CheckTitle
            Severity            = $f.Severity
            Class               = $f.Class
            Type                = $f.Type
            Object              = $adObject
            Text                = $f.Text
            Key                 = $f.Key
            Value               = $f.Value
            FindingId           = $f.FindingId
            ObjectType          = $f.ObjectType
            AttributeSeverities = $attrSev
            RenderModel         = $null  # Re-computed by Export-HTMLReport via Get-RenderModel
        }
    }

    return @($result)
}

<#
.SYNOPSIS
    Merges previous and current findings, replacing by category.
.DESCRIPTION
    Combines findings from a previous cache with current scan findings.
    Findings from categories that were re-scanned (in ReplacedCategories)
    are removed from the previous set and replaced with current findings.
.PARAMETER PreviousFindings
    Findings loaded from cache.
.PARAMETER CurrentFindings
    Findings from the current scan.
.PARAMETER ReplacedCategories
    Category names whose findings should be replaced (= modules that ran).
#>
function Merge-FindingsCollection {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [array]$PreviousFindings,

        [Parameter(Mandatory=$true)]
        [array]$CurrentFindings,

        [Parameter(Mandatory=$true)]
        [string[]]$ReplacedCategories
    )

    # Keep old findings EXCEPT those whose Category is being replaced
    # Use HashSet for O(1) lookups instead of Where-Object pipeline
    $replacedSet = [System.Collections.Generic.HashSet[string]]::new(
        [string[]]$ReplacedCategories, [System.StringComparer]::OrdinalIgnoreCase
    )
    $kept = [System.Collections.ArrayList]::new($PreviousFindings.Count)
    foreach ($f in $PreviousFindings) {
        if (-not $replacedSet.Contains($f.Category)) {
            [void]$kept.Add($f)
        }
    }

    # Sort by canonical module order to ensure consistent report layout
    $categoryOrder = @('Domain','Creds','Rights','Delegation','ADCS','Accounts','GPO','Computer','Application','Bloodhound')
    $categoryIndex = @{}
    for ($i = 0; $i -lt $categoryOrder.Count; $i++) {
        $categoryIndex[$categoryOrder[$i]] = $i
    }

    # Build merged list: kept previous + current, then sort by category order
    $merged = [System.Collections.ArrayList]::new($kept.Count + $CurrentFindings.Count)
    [void]$merged.AddRange(@($kept))
    [void]$merged.AddRange(@($CurrentFindings))
    $sorted = @($merged | Sort-Object { if ($categoryIndex.ContainsKey($_.Category)) { $categoryIndex[$_.Category] } else { 999 } })

    Write-Log "[FindingsCache] Merge: kept $($kept.Count) previous, added $($CurrentFindings.Count) new, total $($sorted.Count)"
    return $sorted
}

# ============================================================================
# Core Output Functions
# ============================================================================
# These functions provide the primary output interface for adPEAS.
# They delegate to the three-layer output architecture.

<#
.SYNOPSIS
    Low-level output function with full control over output formatting.

.DESCRIPTION
    Core output function that dispatches to the RenderModel pipeline.
    Use the semantic wrapper functions (Show-Line, Show-Header, etc.) for most cases.

.PARAMETER Object
    AD object to output (uses Get-RenderModel + Render-ConsoleObject).

.PARAMETER Class
    Output class: Info, SubInfo, Finding, Hint, Note, Secure, Standard

.PARAMETER Value
    The message to output.

.PARAMETER Key
    Key name for key-value pairs with automatic alignment (used with -Value).

.PARAMETER AlignAt
    Column width for key alignment (default: 45 characters).

.PARAMETER Raw
    No prefixes ([?], [!], etc.)

.PARAMETER Logo
    Outputs the adPEAS logo.

.PARAMETER ObjectType
    The _adPEASObjectType for SubHeader checks. Used for tooltip lookup in HTML reports.

.EXAMPLE
    Show-Output -Class Info -Value "Checking Domain Information"
    Output: [?] +++++ Checking Domain Information +++++

.EXAMPLE
    Show-Output -Class Finding -Value "Vulnerability Found"
    Output: [!] Vulnerability Found

.EXAMPLE
    Show-Output -Key "Domain Name (DNS)" -Value "contoso.com"
    Output: Domain Name (DNS):                      contoso.com
#>
function Show-Output {
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true, Mandatory=$false)]
        [ValidateNotNullOrEmpty()]
        $Object,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Info", "SubInfo", "Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [string]$Value,

        [Parameter(Mandatory=$false)]
        [string]$Key,

        [Parameter(Mandatory=$false)]
        [int]$AlignAt = 45,

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        [Parameter(Mandatory=$false)]
        [switch]$Logo,

        [Parameter(Mandatory=$false)]
        [string]$FindingId,

        [Parameter(Mandatory=$false)]
        [string]$ObjectType,

        [Parameter(Mandatory=$false)]
        [switch]$NoCollect
    )

    # =========================================================================
    # FINDINGS COLLECTION: Collect findings in parallel to normal output
    # This enables HTML/JSON export without modifying Check-Modules
    # Skip collection if -NoCollect is specified (used for console-only output)
    # =========================================================================
    # Build RenderModel for objects (used by both console rendering and findings collection)
    $renderModel = $null
    if ($Object) {
        $renderModel = Get-RenderModel -Object $Object
    }

    if ($Script:adPEAS_FindingsCollectionEnabled -and -not $NoCollect) {
        Write-Verbose "[FindingsCollection] Show-Output called: Object=$($null -ne $Object), Key=$Key, Class=$Class, FindingId=$FindingId, ObjectType=$ObjectType"
        if ($Object) {
            # Collect object findings with pre-built RenderModel
            Add-Finding -Object $Object -Class $Class -FindingId $FindingId -RenderModel $renderModel
        }
        elseif ($Key) {
            # Collect key-value findings
            Add-Finding -Class $Class -Key $Key -Value $Value -FindingId $FindingId
        }
        elseif ($Value) {
            # Collect ALL line findings including headers (Info/SubInfo)
            # These are used for structuring the HTML report
            # For SubHeaders, include ObjectType for direct tooltip lookup
            Add-Finding -Class $Class -Text $Value -FindingId $FindingId -ObjectType $ObjectType
        }
    }
    # =========================================================================

    if ($Logo) {
        Write-adPEASLogo -Version $Value
        return
    }

    if ($Object) {
        # Use RenderModel pipeline: Get-RenderModel -> Render-ConsoleObject
        Render-ConsoleObject -Model $renderModel -AlignAt $AlignAt
        return
    }

    if ($Key) {
        if ($Class -eq "Secure") {
            # Use Write-adPEASAttribute with ColorValue for proper key:value coloring
            # Remove trailing colon from Key if present (Write-adPEASAttribute adds it)
            $keyName = if ($Key.EndsWith(':')) { $Key.TrimEnd(':') } else { $Key }
            Write-adPEASAttribute -Name $keyName -Value $Value -Class $Class -ValueClass $Class -AlignAt $AlignAt
            return
        }

        # For other classes: color the entire line
        $hasPrefix = $Class -in @("Info", "SubInfo", "Finding", "Hint", "Note", "Secure")
        $paddingWidth = if ($hasPrefix) { $AlignAt - 4 } else { $AlignAt }
        $paddedKey = $Key.PadRight($paddingWidth)
        $formattedValue = "$paddedKey$Value"

        # Output with class coloring (entire line colored)
        Write-adPEASOutput -Text $formattedValue -Class $Class -LeadingNewline:($Class -eq "SubInfo")
        return
    }

    switch ($Class) {
        "Info" {
            # Main section header with decorative lines
            Write-adPEASHeader -Value $Value
        }

        "SubInfo" {
            # Sub-section header with leading newline
            if ($Raw) {
                Write-adPEASOutput -Text $Value -Class "Standard" -NoPrefix -LeadingNewline
            } else {
                Write-adPEASOutput -Text $Value -Class "SubInfo" -LeadingNewline
            }
        }

        default {
            # Standard text output
            if ($Raw) {
                Write-adPEASOutput -Text $Value -Class "Standard" -NoPrefix
            } else {
                Write-adPEASOutput -Text $Value -Class $Class
            }
        }
    }
}

# ============================================================================
# Semantic Wrapper Functions
# ============================================================================
# These functions provide clearer semantics for common output patterns.
# They all delegate to Show-Output internally.

<#
.SYNOPSIS
    Outputs a single line of text with optional class styling.

.DESCRIPTION
    Simple wrapper for outputting a single line of text.
    Use this for status messages, simple text output, and informational lines.

.PARAMETER Text
    The text to output.

.PARAMETER Class
    Output class: Finding, Hint, Note, Secure, Standard (default: Standard)

.PARAMETER Raw
    Output without prefix ([?], [!], etc.)

.EXAMPLE
    Show-Line "Processing users..."
    Output: Processing users...

.EXAMPLE
    Show-Line "Vulnerability found!" -Class Finding
    Output: [!] Vulnerability found!
#>
function Show-Line {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [string]$Text,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Info", "SubInfo", "Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        [Parameter(Mandatory=$false)]
        [string]$FindingId,

        [Parameter(Mandatory=$false)]
        [switch]$NoCollect
    )

    Show-Output -Value $Text -Class $Class -Raw:$Raw -FindingId $FindingId -NoCollect:$NoCollect
}

<#
.SYNOPSIS
    Outputs a key-value pair with automatic alignment.

.DESCRIPTION
    Formats and outputs a key-value pair with consistent column alignment.
    The key is padded to AlignAt characters, then the value follows.

.PARAMETER Key
    The attribute/property name (left side).

.PARAMETER Value
    The attribute/property value (right side).

.PARAMETER Class
    Output class for styling: Finding, Hint, Note, Secure, Standard (default: Standard)

.PARAMETER AlignAt
    Column width for key alignment (default: 45 characters).

.EXAMPLE
    Show-KeyValue -Key "Domain Name" -Value "contoso.com"
    Output: Domain Name:                                contoso.com

.EXAMPLE
    Show-KeyValue -Key "Status" -Value "VULNERABLE" -Class Finding
    Output: [!] Status:                                 VULNERABLE
#>
function Show-KeyValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [string]$Key,

        [Parameter(Mandatory=$true, Position=1)]
        [string]$Value,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [int]$AlignAt = 45,

        [Parameter(Mandatory=$false)]
        [string]$FindingId,

        [Parameter(Mandatory=$false)]
        [switch]$NoCollect
    )

    Show-Output -Key $Key -Value $Value -Class $Class -AlignAt $AlignAt -FindingId $FindingId -NoCollect:$NoCollect
}

<#
.SYNOPSIS
    Emits a standardized note when a web endpoint probe could not reach the target.

.DESCRIPTION
    Shared by every check that probes HTTP/HTTPS endpoints (ADCS web enrollment,
    Exchange endpoints, ...). Centralizing the wording and severity guarantees that
    all web endpoint checks behave identically, so a missing endpoint row is never
    mistaken for "the service exposes no web endpoint" when in reality the probe was
    simply blocked (firewall, VPN, host down). Does nothing when the probe succeeded.

.PARAMETER ProbeResult
    The result object returned by Invoke-HTTPRequest (-ScanADCS / -ScanExchange).
    May be $null when the probe was abandoned before it ran (e.g. a TCP pre-check failed).

.PARAMETER Hostname
    The target host name that was (or would have been) probed.

.PARAMETER CheckLabel
    Short label describing the probe, prefixed to the message (e.g. 'Web enrollment check').

.EXAMPLE
    Show-WebEndpointUnreachable -ProbeResult $webEnrollmentResult -Hostname $ca.DNSHostName -CheckLabel 'Web enrollment check'
#>
function Show-WebEndpointUnreachable {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [AllowNull()]
        $ProbeResult,

        [Parameter(Mandatory=$true)]
        [string]$Hostname,

        [Parameter(Mandatory=$false)]
        [string]$CheckLabel = 'Web endpoint check'
    )

    # Probe reached the target - nothing to report here.
    if ($ProbeResult -and $ProbeResult.Success) { return }

    Show-Line "$CheckLabel could not reach $Hostname (HTTP/HTTPS unreachable)" -Class Note
}

<#
.SYNOPSIS
    Outputs an AD object with all relevant properties formatted.

.DESCRIPTION
    Takes an AD object (user, computer, group, GPO, etc.) and outputs
    all its relevant properties in a formatted, aligned manner.
    Uses Get-RenderModel + Render-ConsoleObject internally.

.PARAMETER Object
    The AD object to output.

.PARAMETER AlignAt
    Column width for property name alignment (default: 45 characters).

.EXAMPLE
    Show-Object $user
    Outputs all relevant properties of the AD user object.

.EXAMPLE
    Get-DomainUser -Identity "admin" | Show-Object
    Pipes a user object directly to Show-Object.
#>
function Show-Object {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true)]
        [ValidateNotNullOrEmpty()]
        $Object,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Finding", "Hint", "Note", "Secure", "Standard")]
        [string]$Class = "Standard",

        [Parameter(Mandatory=$false)]
        [int]$AlignAt = 45,

        [Parameter(Mandatory=$false)]
        [switch]$NoCollect
    )

    process {
        Show-Output -Object $Object -Class $Class -AlignAt $AlignAt -NoCollect:$NoCollect
    }
}

