# ============================================================================
# Module Import / Quick Start Messages
# ============================================================================

function Get-adPEASHelp {
<#
.SYNOPSIS
    Displays adPEAS help including check modules, commands, and usage examples.

.DESCRIPTION
    Shows a comprehensive overview of adPEAS: quick start examples,
    the 10 security check modules, all available commands grouped by category,
    and how to access detailed help for individual commands.

    Use the -Section parameter to display only specific sections.

.PARAMETER Section
    Which section(s) to display. Valid values: QuickStart, Checks, Commands.
    Default: all sections are shown.

.EXAMPLE
    Get-adPEASHelp

    Displays the full adPEAS help overview.

.EXAMPLE
    Get-adPEASHelp -Section Checks

    Displays only the security check modules section.

.EXAMPLE
    Get-adPEASHelp -Section QuickStart,Commands

    Displays quick start examples and available commands.
#>
    [CmdletBinding()]
    param(
        [ValidateSet('QuickStart','Checks','Commands')]
        [string[]]$Section
    )

    # If no section specified, show all
    $showAll = -not $Section
    $showQuickStart = $showAll -or ($Section -contains 'QuickStart')
    $showChecks = $showAll -or ($Section -contains 'Checks')
    $showCommands = $showAll -or ($Section -contains 'Commands')

    # --- Quick Start ---
    if ($showQuickStart) {
        Show-SubHeader "Quick Start"

        Show-Line "Simple scan (Windows Auth):" -Class Hint
        Show-Line "Invoke-adPEAS -Domain 'contoso.com'"
        Show-EmptyLine

        Show-Line "Session-based with credentials:" -Class Hint
        Show-Line "Connect-adPEAS -Domain 'contoso.com' -Credential (Get-Credential)"
        Show-Line "Invoke-adPEAS"
        Show-EmptyLine

        # PTT Note (for domain-joined machines with alternate credentials)
        Show-Line "On domain-joined machines, Kerberos authentication with -Password/-NTHash/-AES*Key/-Certificate replace Kerberos tickets." -Class Note
        Show-Line "Use Connect-adPEAS with -ForceNTLM or -ForceSimpleBind to avoid this."
        Show-EmptyLine

        Show-Line "More help:" -Class Hint
        Show-Line "Get-adPEASHelp"
        Show-Line "Get-Help Connect-adPEAS -Examples"
        Show-Line "Get-Help <Command> -Detailed"
        Show-EmptyLine

    }

    # --- Check Modules (dynamic from ObjectTypeDefinitions) ---
    if ($showChecks) {
        Show-SubHeader "Security Check Modules"

        Show-Line "Run all modules:" -Class Hint
        Show-Line "Invoke-adPEAS (without -Module)"
        Show-EmptyLine
        Show-Line "Run specific modules only:" -Class Hint
        Show-Line "Invoke-adPEAS -Module 'Domain','Creds','ADCS'"
        Show-EmptyLine

        # Module display order and descriptions
        $moduleOrder = [ordered]@{
            'Domain'      = "Domain Configuration"
            'Creds'       = "Credential Exposure"
            'Rights'      = "Access Permissions"
            'Delegation'  = "Delegation Settings"
            'ADCS'        = "AD Certificate Services"
            'Accounts'    = "Privileged Accounts"
            'GPO'         = "Group Policy Objects"
            'Computer'    = "Computer Security"
            'Application' = "Application Infrastructure"
            'Bloodhound'  = "BloodHound Data"
        }

        # Group ObjectTypes by Module, collect unique SectionTitles with Summary
        $checksByModule = @{}
        if ($Script:ObjectTypeDefinitions) {
            foreach ($entry in $Script:ObjectTypeDefinitions.GetEnumerator()) {
                $mod = $entry.Value.Module
                if ($mod -and $moduleOrder.Contains($mod)) {
                    if (-not $checksByModule[$mod]) { $checksByModule[$mod] = @() }
                    $title = $entry.Value.SectionTitle
                    $summary = $entry.Value.Summary
                    if ($title -and ($checksByModule[$mod].Title -notcontains $title)) {
                        $checksByModule[$mod] += @{ Title = $title; Summary = $summary }
                    }
                }
            }
        }

        foreach ($mod in $moduleOrder.Keys) {
            $desc = $moduleOrder[$mod]
            Show-Line "$($desc): -Module $mod" -Class Hint
            $checks = $checksByModule[$mod]
            if ($checks) {
                foreach ($check in $checks) {
                    Show-KeyValue $check.Title $check.Summary
                }
            }
            Show-EmptyLine
        }
    }

    # --- Commands ---
    if ($showCommands) {
        Show-SubHeader "Additional Core and Helper Modules"

        # --- Connection ---
        Show-Line "Connection:" -Class Hint
        Show-KeyValue "Connect-adPEAS" "Establish LDAP session"
        Show-KeyValue "Disconnect-adPEAS" "Close LDAP session"
        Show-KeyValue "Get-adPEASSession" "Show session status"
        Show-EmptyLine

        # --- AD Queries ---
        Show-Line "AD Queries:" -Class Hint
        Show-KeyValue "Get-DomainUser" "Query AD users"
        Show-KeyValue "Get-DomainComputer" "Query AD computers"
        Show-KeyValue "Get-DomainGroup" "Query AD groups"
        Show-KeyValue "Get-DomainGPO" "Query Group Policy Objects"
        Show-KeyValue "Get-DomainObject" "Query any AD object"
        Show-KeyValue "Get-ObjectACL" "Query object ACLs"
        Show-KeyValue "Get-CertificateTemplate" "Query certificate templates"
        Show-KeyValue "Get-CertificateAuthority" "Query certificate authorities"
        Show-EmptyLine

        # --- AD Modifications ---
        Show-Line "AD Modifications:" -Class Hint
        Show-KeyValue "Set-DomainUser" "Modify user attributes"
        Show-KeyValue "Set-DomainComputer" "Modify computer attributes"
        Show-KeyValue "Set-DomainGroup" "Modify group attributes"
        Show-KeyValue "Set-DomainObject" "Modify any AD object"
        Show-KeyValue "Set-DomainGPO" "Modify Group Policy Objects"
        Show-KeyValue "Set-CertificateTemplate" "Modify certificate templates"
        Show-KeyValue "New-DomainUser" "Create AD user"
        Show-KeyValue "New-DomainComputer" "Create AD computer"
        Show-KeyValue "New-DomainGroup" "Create AD group"
        Show-KeyValue "New-DomainGPO" "Create Group Policy Object"
        Show-EmptyLine

        # --- Kerberos Authentication ---
        Show-Line "Kerberos Authentication:" -Class Hint
        Show-KeyValue "Invoke-KerberosAuth" "Request TGT (Password/Hash/Key/Cert)"
        Show-KeyValue "Request-ServiceTicket" "Request TGS for a service"
        Show-KeyValue "Import-KerberosTicket" "Pass-the-Ticket (inject into session)"
        Show-EmptyLine

        # --- Credential Attacks ---
        Show-Line "Credential Attacks:" -Class Hint
        Show-KeyValue "Invoke-Kerberoast" "Kerberoasting (request service tickets)"
        Show-KeyValue "Invoke-ASREPRoast" "AS-REP Roasting (no preauth)"
        Show-KeyValue "Invoke-DCSync" "DCSync (directory replication)"
        Show-KeyValue "Invoke-PasswordSpray" "Password spraying"
        Show-EmptyLine

        # --- Offensive Actions ---
        Show-Line "Offensive Actions:" -Class Hint
        Show-KeyValue "Invoke-TicketForge" "Golden/Silver/Diamond Tickets"
        Show-KeyValue "Invoke-S4U" "S4U delegation attacks"
        Show-KeyValue "Invoke-RBCDOperation" "Resource-Based Constrained Delegation"
        Show-KeyValue "Invoke-ShadowCredentialOperation" "Shadow Credentials"
        Show-KeyValue "Request-ADCSCertificate" "Request ADCS certificate"
        Show-EmptyLine
    }
}




# ----- Get-AuthenticatedDirectoryEntry.ps1 -----

<#
.SYNOPSIS
    Gets an authenticated DirectoryEntry object for LDAP operations.

.DESCRIPTION
    Get-AuthenticatedDirectoryEntry is a helper function that returns a DirectoryEntry object
    with proper authentication handling. It centralizes the credential logic used across all
    New-Domain*, Set-Domain*, and other modules that need direct LDAP access.

    The function handles three authentication scenarios:
    1. Explicit Credential parameter provided
    2. Script-level LDAPCredential from established session
    3. Current user context (no credentials)

    Path construction uses $Script:LDAPContext to build the correct LDAP path.
    For LDAPS sessions, the path uses LDAP://server:636/DN with SecureSocketsLayer
    authentication type, since DirectoryEntry does not support the LDAPS:// scheme.

    This function uses $Credential.UserName (with domain prefix) instead of
    $NetworkCred.UserName which strips the domain prefix and causes authentication failures.

.PARAMETER DistinguishedName
    The distinguishedName of the AD object (e.g., "CN=Users,DC=contoso,DC=com").
    The function automatically constructs the full LDAP path using $Script:LDAPContext.

.PARAMETER Credential
    Optional PSCredential object for authentication. If not provided, uses
    $Script:LDAPCredential from an established session, or falls back to current user context.

.EXAMPLE
    $entry = Get-AuthenticatedDirectoryEntry -DistinguishedName "CN=Users,DC=contoso,DC=com"
    Gets a DirectoryEntry using session context (Server/Port) and credentials.

.EXAMPLE
    $entry = Get-AuthenticatedDirectoryEntry -DistinguishedName $dn -Credential (Get-Credential)
    Gets a DirectoryEntry with explicit credentials.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Get-AuthenticatedDirectoryEntry {
    [CmdletBinding()]
    [OutputType([System.DirectoryServices.DirectoryEntry])]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [string]$DistinguishedName,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    process {
        try {
            # Ensure we have a valid LDAP context
            if (-not $Script:LDAPContext) {
                Write-Error "[Get-AuthenticatedDirectoryEntry] No LDAP context available. Use Connect-adPEAS first."
                return $null
            }

            $server = $Script:LDAPContext.Server
            $useLDAPS = $Script:LDAPContext.UseLDAPS
            $port = $Script:LDAPContext.Port

            # DirectoryEntry only supports LDAP:// scheme (not LDAPS://)
            # For SSL, use LDAP://server:636/DN with AuthenticationTypes.SecureSocketsLayer
            if ($server) {
                if ($useLDAPS) {
                    $Path = "LDAP://${server}:${port}/$DistinguishedName"
                } else {
                    $Path = "LDAP://$server/$DistinguishedName"
                }
            } else {
                $Path = "LDAP://$DistinguishedName"
            }

            Write-Log "[Get-AuthenticatedDirectoryEntry] Path: $Path (SSL: $useLDAPS)"

            # Determine authentication types
            # SecureSocketsLayer = SSL/TLS, Secure = Negotiate (Kerberos/NTLM)
            $authTypes = [System.DirectoryServices.AuthenticationTypes]::Secure
            if ($useLDAPS) {
                $authTypes = $authTypes -bor [System.DirectoryServices.AuthenticationTypes]::SecureSocketsLayer
            }

            # Resolve credentials: explicit > session > current user
            $cred = if ($Credential) { $Credential } elseif ($Script:LDAPCredential) { $Script:LDAPCredential } else { $null }

            if ($cred) {
                # Use $cred.UserName (with domain prefix) NOT GetNetworkCredential().UserName (strips domain)
                $NetworkCred = $cred.GetNetworkCredential()
                $Entry = New-Object System.DirectoryServices.DirectoryEntry(
                    $Path,
                    $cred.UserName,
                    $NetworkCred.Password,
                    $authTypes
                )
            }
            else {
                # Current user context
                $Entry = New-Object System.DirectoryServices.DirectoryEntry($Path, $null, $null, $authTypes)
            }

            return $Entry
        }
        catch {
            Write-Error "[Get-AuthenticatedDirectoryEntry] Failed to get DirectoryEntry for '$DistinguishedName': $_"
            return $null
        }
    }
}



# ----- Show-ConnectionError.ps1 -----

<#
.SYNOPSIS
    Displays a standardized connection error message.

.DESCRIPTION
    Central helper function for displaying consistent, short error messages for all connection and authentication failures in adPEAS.

    Error types:
    - AuthenticationFailed: Invalid credentials (username/password/hash/certificate)
    - NetworkError: Cannot reach domain controller
    - CertificateError: SSL/TLS certificate validation failed (use -IgnoreSSLErrors)
    - SSLHandshakeError: SSL/TLS handshake failed (server doesn't support LDAPS or TLS version mismatch)
    - PFXLoadError: Failed to load PFX/P12 certificate file
    - PermissionError: Access denied
    - DomainError: Domain not found or unreachable
    - KerberosError: Kerberos-specific failures (with sub-types via ErrorCode)
    - NTLMDisabledError: NTLM disabled and Kerberos not available
    - TicketImportError: Pass-the-Ticket import failed
    - GenericError: Unclassified connection error

    Error code resolution:
    Callers should pass structured error codes via -ErrorCode and -ErrorCodeType instead of free-text -Details.
    Show-ConnectionError resolves error codes to English text using the central lookup tables:
    - Kerberos: $Script:KERBEROS_ERROR_CODES (Kerberos-Crypto.ps1)
    - LDAP: ConvertFrom-LDAPError (adPEAS-ErrorCodes.ps1)
    - Win32: ConvertFrom-Win32Error (adPEAS-ErrorCodes.ps1)
    - HRESULT: ConvertFrom-HResult (adPEAS-ErrorCodes.ps1)

.PARAMETER ErrorType
    The type of error to display.

.PARAMETER Details
    Optional fallback details when no error code is available.

.PARAMETER ErrorCode
    Numeric error code (LDAP, Win32, Kerberos KDC, or HRESULT).

.PARAMETER ErrorCodeType
    Type of the error code: "Kerberos", "LDAP", "Win32", or "HRESULT".

.PARAMETER NoThrow
    If specified, does not throw an exception after displaying the error.

.EXAMPLE
    Show-ConnectionError -ErrorType "AuthenticationFailed" -ErrorCode 1326 -ErrorCodeType "Win32"

.EXAMPLE
    Show-ConnectionError -ErrorType "KerberosError" -ErrorCode 14 -ErrorCodeType "Kerberos"

.EXAMPLE
    Show-ConnectionError -ErrorType "PFXLoadError" -ErrorCode 0x80070056 -ErrorCodeType "HRESULT"

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Show-ConnectionError {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [ValidateSet(
            "AuthenticationFailed",
            "NetworkError",
            "CertificateError",
            "SSLHandshakeError",
            "PFXLoadError",
            "PermissionError",
            "DomainError",
            "KerberosError",
            "NTLMDisabledError",
            "TicketImportError",
            "GenericError"
        )]
        [string]$ErrorType,

        [Parameter(Mandatory=$false)]
        [string]$Details,

        [Parameter(Mandatory=$false)]
        [object]$ErrorCode,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Kerberos", "LDAP", "Win32", "HRESULT")]
        [string]$ErrorCodeType,

        # Authentication method that was in use (Connect-adPEAS parameter set name, e.g. 'AES256',
        # 'AES128', 'NTHash', 'UsernamePassword'). Lets encryption-type errors give advice that
        # matches what the caller actually did, instead of assuming an RC4/NTHash attempt.
        [Parameter(Mandatory=$false)]
        [string]$AuthMethod,

        [Parameter(Mandatory=$false)]
        [switch]$NoThrow
    )

    process {
        if ($Details) {
            $Details = $Details.Trim()
        }

        $ThrowMessage = "Connection failed"

        # Phase 1: Resolve error code to user-friendly details
        # For common error codes, provide specific helpful text (like Kerberos switch does)
        # For uncommon codes, fall back to central lookup tables
        # Kerberos codes are resolved in the KerberosError case below (has extended handling)
        $resolvedDetails = $null
        if ($null -ne $ErrorCode -and $ErrorCodeType -and $ErrorCodeType -ne "Kerberos") {
            switch ($ErrorCodeType) {
                "LDAP" {
                    # Specific messages for common LDAP auth/connection errors
                    switch ([int]$ErrorCode) {
                        1  { $resolvedDetails = "Reason: LDAP server denied the request - credentials were not accepted or bind resulted in anonymous access." }  # LDAP_OPERATIONS_ERROR
                        8  { $resolvedDetails = "Reason: LDAP signing or channel binding is enforced by domain policy." }  # LDAP_STRONG_AUTH_REQUIRED
                        49 { $resolvedDetails = "Reason: Wrong username or password." }  # LDAP_INVALID_CREDENTIALS
                        50 { $resolvedDetails = "Reason: The account does not have sufficient privileges for this operation." }  # LDAP_INSUFFICIENT_RIGHTS
                        81 { $resolvedDetails = "Reason: Cannot connect to the LDAP server - verify hostname and port." }  # LDAP_SERVER_DOWN
                        82 { $resolvedDetails = "Reason: Authentication negotiation failed - Kerberos SPN mismatch, invalid ticket, or NTLM negotiation error." }  # LDAP_LOCAL_ERROR
                        91 { $resolvedDetails = "Reason: Cannot establish TCP connection to LDAP server." }  # LDAP_CONNECT_ERROR
                        default {
                            $lookupInfo = ConvertFrom-LDAPError -ErrorCode $ErrorCode
                            if ($lookupInfo -and $lookupInfo.Message) { $resolvedDetails = "Reason: $($lookupInfo.Message)" }
                        }
                    }
                }
                "Win32" {
                    # Specific messages for common Win32 auth errors (NTLM LogonUser)
                    switch ([int]$ErrorCode) {
                        1326 { $resolvedDetails = "Reason: Wrong username or password." }  # ERROR_LOGON_FAILURE
                        1327 { $resolvedDetails = "Reason: Account has restrictions that prevent logon." }  # ERROR_ACCOUNT_RESTRICTION
                        1328 { $resolvedDetails = "Reason: Account is not allowed to log on at this time." }  # ERROR_INVALID_LOGON_HOURS
                        1329 { $resolvedDetails = "Reason: Account is not allowed to log on from this workstation." }  # ERROR_INVALID_WORKSTATION
                        1330 { $resolvedDetails = "Reason: Password has expired - change password required." }  # ERROR_PASSWORD_EXPIRED
                        1331 { $resolvedDetails = "Reason: Account is disabled." }  # ERROR_ACCOUNT_DISABLED
                        1385 { $resolvedDetails = "Reason: Logon type (network) is not granted for this account." }  # ERROR_LOGON_TYPE_NOT_GRANTED
                        5    { $resolvedDetails = "Reason: Access denied - insufficient privileges." }  # ERROR_ACCESS_DENIED
                        53   { $resolvedDetails = "Reason: Network path not found - verify server hostname." }  # ERROR_BAD_NETPATH
                        1355 { $resolvedDetails = "Reason: Domain not found - verify domain name." }  # ERROR_NO_SUCH_DOMAIN
                        default {
                            $lookupInfo = ConvertFrom-Win32Error -ErrorCode $ErrorCode
                            if ($lookupInfo -and $lookupInfo.Message) { $resolvedDetails = "Reason: $($lookupInfo.Message)" }
                        }
                    }
                }
                "HRESULT" {
                    $lookupInfo = ConvertFrom-HResult -HResult $ErrorCode
                    if ($lookupInfo -and $lookupInfo.Message -and $lookupInfo.Message -notmatch '^Unknown') { $resolvedDetails = "Reason: $($lookupInfo.Message)" }
                }
            }
        }

        # Use resolved text from lookup, fall back to Details if no code or lookup failed.
        # Exception: if an explicit $Details string was provided alongside an ErrorCode,
        # the caller wants to override the generic lookup message with context-specific text.
        $effectiveDetails = if ($Details) { $Details } elseif ($resolvedDetails) { $resolvedDetails } else { $null }

        switch ($ErrorType) {
            "AuthenticationFailed" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }

                # Check if this might be an expired Kerberos ticket (Windows Auth without explicit credentials)
                $IsWindowsAuth = $Script:AuthInfo.ParameterSet -eq 'WindowsAuth'
                $IsNTLMImpersonation = $Script:AuthInfo.NTLMImpersonation -eq $true

                $hints = @()
                if ($IsWindowsAuth -and -not $IsNTLMImpersonation) {
                    $hints += "If using Windows Authentication, your Kerberos ticket may have expired."
                }

                Show-Message -Type Error -Title "Authentication failed: Invalid credentials" -Details $detailsArray -Hints $hints
                $ThrowMessage = "Authentication failed"
            }

            "NetworkError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }
                Show-Message -Type Error -Title "Connection failed: Server unreachable" -Details $detailsArray
                $ThrowMessage = "Network error: Server unreachable"
            }

            "CertificateError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                } else {
                    $detailsArray += "Use LDAP instead (remove -UseLDAPS) or fix certificate validation"
                }
                $hints = @(
                    "Try: -IgnoreSSLErrors to bypass certificate validation",
                    "Or: Remove -UseLDAPS to use unencrypted LDAP"
                )
                Show-Message -Type Error -Title "LDAPS failed: Certificate validation error" -Details $detailsArray -Hints $hints
                $ThrowMessage = "LDAPS certificate error"
            }

            "SSLHandshakeError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }
                $hints = @(
                    "Server may not support LDAPS on port 636",
                    "Server may require specific TLS version (1.2+)",
                    "Try: Remove -UseLDAPS to use unencrypted LDAP"
                )
                Show-Message -Type Error -Title "LDAPS failed: SSL/TLS handshake error" -Details $detailsArray -Hints $hints
                $ThrowMessage = "LDAPS SSL handshake failed"
            }

            "PFXLoadError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }
                $hints = @(
                    "Verify: Certificate password is correct",
                    "Verify: File is a valid PFX/P12 certificate and certificate contains a private key"
                )
                Show-Message -Type Error -Title "Certificate load failed" -Details $detailsArray -Hints $hints
                $ThrowMessage = "Certificate load failed"
            }

            "PermissionError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }
                Show-Message -Type Error -Title "Access denied: Insufficient privileges" -Details $detailsArray
                $ThrowMessage = "Permission denied"
            }

            "DomainError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }
                Show-Message -Type Error -Title "Domain not found or unreachable" -Details $detailsArray
                $ThrowMessage = "Domain error"
            }

            "KerberosError" {
                $detailsArray = @()

                # Kerberos error codes have extended handling with detailed messages and hints
                if ($null -ne $ErrorCode -and $ErrorCodeType -eq "Kerberos") {
                    switch ($ErrorCode) {
                        # === Authentication Errors (AS-REQ) ===
                        6 {  # KDC_ERR_C_PRINCIPAL_UNKNOWN
                            $detailsArray += "Reason: User not found in the domain."
                        }
                        12 {  # KDC_ERR_POLICY
                            $detailsArray += "Reason: KDC policy rejects the request (check account restrictions)."
                        }
                        14 {  # KDC_ERR_ETYPE_NOSUPP
                            # The KDC has no key for this account in any encryption type the client
                            # offered. The right advice depends on what the caller actually sent -
                            # the previous text assumed an RC4/NTHash attempt, which is wrong (and
                            # confusing) when the caller already used an AES key.
                            if ($AuthMethod -in @('AES256','AES128')) {
                                $detailsArray += "Reason: The KDC has no AES key for this account. The account likely supports only RC4 (its AES keys were never generated - msDS-SupportedEncryptionTypes), or the key does not match the account."
                                $detailsArray += "Try: reset the account password to generate AES keys, or authenticate with its RC4 key via -NTHash (if RC4 is still enabled in the domain)."
                            }
                            elseif ($AuthMethod -eq 'NTHash') {
                                $detailsArray += "Reason: RC4 is disabled in this domain, so the RC4/NT hash cannot be used. Use -AES256Key (or -AES128Key) instead."
                            }
                            else {
                                $detailsArray += "Reason: The KDC does not support any of the offered Kerberos encryption types for this account (KDC_ERR_ETYPE_NOSUPP). RC4 may be disabled, or the account may lack AES keys."
                                $detailsArray += "Try: -AES256Key if you used an NT hash, or -NTHash if you used an AES key, depending on which encryption types the account actually supports."
                            }
                        }
                        18 {  # KDC_ERR_CLIENT_REVOKED
                            $detailsArray += "Reason: Account is disabled or locked out."
                        }
                        23 {  # KDC_ERR_KEY_EXPIRED
                            $detailsArray += "Reason: Password has expired - change password required."
                        }
                        24 {  # KDC_ERR_PREAUTH_FAILED
                            $detailsArray += "Reason: Wrong password, hash, or key."
                        }
                        25 {  # KDC_ERR_PREAUTH_REQUIRED
                            $detailsArray += "Reason: Pre-authentication required (internal error)."
                        }

                        # === Service Ticket Errors (TGS-REQ) ===
                        7 {  # KDC_ERR_S_PRINCIPAL_UNKNOWN
                            $detailsArray += "Reason: Service principal (SPN) not found in the domain."
                        }
                        26 {  # KDC_ERR_SERVER_NOMATCH
                            $detailsArray += "Reason: Requested server and ticket don't match."
                        }
                        29 {  # KDC_ERR_SVC_UNAVAILABLE
                            $detailsArray += "Reason: KDC service unavailable - check if DC is reachable."
                        }

                        # === Time/Clock Errors ===
                        37 {  # KRB_AP_ERR_SKEW
                            $detailsArray += "Reason: Clock skew too great - sync system time with DC (max 5 min difference)."
                        }

                        # === Ticket Errors ===
                        31 {  # KRB_AP_ERR_BAD_INTEGRITY
                            $detailsArray += "Reason: Integrity check failed - wrong key or corrupted ticket."
                        }
                        32 {  # KRB_AP_ERR_TKT_EXPIRED
                            $detailsArray += "Reason: Ticket has expired - request a new ticket."
                        }
                        33 {  # KRB_AP_ERR_TKT_NYV
                            $detailsArray += "Reason: Ticket not yet valid - check system time."
                        }
                        41 {  # KRB_AP_ERR_MODIFIED
                            $detailsArray += "Reason: Message stream modified - ticket checksum validation failed."
                            $detailsArray += "This usually means the wrong key was used for encryption/signing."
                        }

                        # === PKINIT (Certificate) Errors ===
                        62 {  # KDC_ERR_CLIENT_NOT_TRUSTED
                            $detailsArray += "Reason: Client certificate not trusted by KDC."
                            $detailsArray += "This typically means the Domain Controller lacks PKINIT support."
                            $detailsArray += ""
                            $detailsArray += "PKINIT Prerequisites (Shadow Credentials / Certificate Auth):"
                            $detailsArray += "  1. AD CS must be installed in the domain, OR"
                            $detailsArray += "  2. DC must have a certificate from another PKI"
                            $detailsArray += "  3. DC certificate must have 'Kerberos Authentication' EKU"
                            $detailsArray += ""
                            $detailsArray += "Alternative: Use Schannel/LDAPS authentication instead:"
                            $detailsArray += "  - PassTheCert tool (LDAP/S with certificate)"
                            $detailsArray += "  - Or use RBCD attack if you have write access to the target"
                        }
                        63 {  # KDC_ERR_KDC_NOT_TRUSTED
                            $detailsArray += "Reason: KDC certificate not trusted by client."
                        }
                        64 {  # KDC_ERR_INVALID_SIG
                            $detailsArray += "Reason: Invalid signature in PKINIT request."
                        }
                        66 {  # KDC_ERR_CERTIFICATE_MISMATCH
                            $detailsArray += "Reason: Certificate doesn't match the principal name."
                        }
                        70 {  # KDC_ERR_CANT_VERIFY_CERTIFICATE
                            $detailsArray += "Reason: Cannot verify certificate - check CA trust chain."
                        }
                        71 {  # KDC_ERR_INVALID_CERTIFICATE
                            $detailsArray += "Reason: Invalid certificate - not valid for Kerberos authentication."
                        }
                        72 {  # KDC_ERR_REVOKED_CERTIFICATE
                            $detailsArray += "Reason: Certificate has been revoked."
                        }
                        77 {  # KDC_ERR_INCONSISTENT_KEY_PURPOSE
                            $detailsArray += "Reason: Certificate cannot be used for PKINIT client authentication."
                            $detailsArray += "The certificate's Extended Key Usage (EKU) must include:"
                            $detailsArray += "  - Smart Card Logon (1.3.6.1.4.1.311.20.2.2), or"
                            $detailsArray += "  - Client Authentication (1.3.6.1.5.5.7.3.2)"
                        }
                        79 {  # KDC_ERR_PA_CHECKSUM_MUST_BE_INCLUDED
                            $detailsArray += "Reason: Windows Server 2022+ requires paChecksum2 with SHA-256."
                            $detailsArray += "This error indicates the PKINIT request is missing the SHA-256 checksum."
                            $detailsArray += ""
                            $detailsArray += "Note: This should not occur with the current adPEAS version."
                            $detailsArray += "If you see this error, please report it as a bug."
                        }

                        default {
                            # Fallback: central error code map
                            if ($Script:KERBEROS_ERROR_CODES -and $Script:KERBEROS_ERROR_CODES.ContainsKey([int]$ErrorCode)) {
                                $errorInfo = $Script:KERBEROS_ERROR_CODES[[int]$ErrorCode]
                                $detailsArray += "Reason: $($errorInfo.Name): $($errorInfo.Description)"
                            }
                            elseif ($Details) {
                                $detailsArray += $Details
                            }
                            else {
                                $detailsArray += "Reason: KDC error code: $ErrorCode"
                            }
                        }
                    }
                }
                elseif ($effectiveDetails) {
                    # No Kerberos error code provided - use effective details as fallback
                    $detailsArray += $effectiveDetails
                }

                Show-Message -Type Error -Title "Authentication failed: Invalid credentials" -Details $detailsArray
                $ThrowMessage = "Authentication failed"
            }

            "NTLMDisabledError" {
                $detailsArray = @("Windows SSPI negotiation failed - NTLM unavailable and Kerberos not possible")
                if ($effectiveDetails) {
                    $detailsArray += "Technical: $effectiveDetails"
                }
                $hints = @(
                    "Use explicit credentials with Kerberos or SimpleBind:",
                    "  Connect-adPEAS -Domain 'domain.com' -Username 'user' -Password 'pass'",
                    "  Connect-adPEAS -Domain 'domain.com' -Username 'user' -Password 'pass' -ForceSimpleBind"
                )
                Show-Message -Type Error -Title "Authentication failed: NTLM is disabled" -Details $detailsArray -Hints $hints
                $ThrowMessage = "NTLM disabled - use explicit credentials or Kerberos"
            }

            "TicketImportError" {
                $detailsArray = @()

                # Determine if this is a file format error or PTT error
                if ($effectiveDetails -match "Invalid kirbi file|Invalid ccache file") {
                    $detailsArray += $effectiveDetails
                    Show-Message -Type Error -Title "Invalid ticket file format" -Details $detailsArray
                }
                else {
                    if ($effectiveDetails) {
                        if ($effectiveDetails -match "non-domain-joined|Remote Credential Guard") {
                            $detailsArray += "PTT requires domain-joined machine or elevated privileges"
                        } else {
                            $detailsArray += $effectiveDetails
                        }
                    }
                    Show-Message -Type Error -Title "Ticket import failed (Pass-the-Ticket)" -Details $detailsArray
                }
                $ThrowMessage = "Ticket import failed"
            }

            "GenericError" {
                $detailsArray = @()
                if ($effectiveDetails) {
                    $detailsArray += $effectiveDetails
                }
                Show-Message -Type Error -Title "Connection failed" -Details $detailsArray
                $ThrowMessage = "Connection failed"
            }
        }

        if (-not $NoThrow) {
            throw $ThrowMessage
        }
    }
}



# ----- ConvertFrom-KeyCredentialLink.ps1 -----

<#
.SYNOPSIS
    Parses msDS-KeyCredentialLink binary blob to extract Shadow Credential metadata.

.DESCRIPTION
    Decodes the KEYCREDENTIALLINK_BLOB structure (LTV format) to extract human-readable
    information such as DeviceID, KeyCreationTime, KeyUsage, and KeySource.

    The structure is:
    - Version (4 bytes): 0x00000200 for version 2
    - Entries: LTV format (Length 2 bytes, Type 2 bytes, Value variable)

    Entry Types:
    - 0x0001: KeyID (SHA256 hash of public key)
    - 0x0002: KeyHash (SHA256 of entries 3-9)
    - 0x0003: KeyMaterial (BCRYPT_RSAKEY_BLOB)
    - 0x0004: KeyUsage (1=NGC, 2=FIDO, 7=FEK)
    - 0x0005: KeySource (0=AD, 1=AzureAD)
    - 0x0006: DeviceId (GUID)
    - 0x0007: CustomKeyInformation
    - 0x0008: KeyApproximateLastLogonTimeStamp (FILETIME)
    - 0x0009: KeyCreationTime (FILETIME)

.PARAMETER KeyCredentialBytes
    The raw binary bytes of the KeyCredentialLink blob.

.PARAMETER DNWithBinary
    The DNWithBinary string format: B:Length:HexData:DN

.PARAMETER Raw
    If specified, returns the full parsed object with all fields.
    Default: Returns a compact display string.

.EXAMPLE
    ConvertFrom-KeyCredentialLink -KeyCredentialBytes $bytes
    Returns: "DeviceID: a1b2c3d4-... | Created: 2024-01-15 10:30:00 | Source: AD"

.EXAMPLE
    ConvertFrom-KeyCredentialLink -DNWithBinary "B:880:0002000001..." -Raw
    Returns the full PSCustomObject with all parsed fields.

.OUTPUTS
    String or PSCustomObject depending on -Raw switch.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function ConvertFrom-KeyCredentialLink {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false, ValueFromPipeline=$true)]
        [byte[]]$KeyCredentialBytes,

        [Parameter(Mandatory=$false)]
        [string]$DNWithBinary,

        [Parameter(Mandatory=$false)]
        [switch]$Raw
    )

    process {
        try {
            # Handle DNWithBinary format: B:Length:HexData:DN
            if ($DNWithBinary) {
                if ($DNWithBinary -match '^B:(\d+):([0-9A-Fa-f]+)(?::(.+))?$') {
                    $HexData = $Matches[2]
                    # Convert hex string to bytes
                    $KeyCredentialBytes = [byte[]]::new($HexData.Length / 2)
                    for ($i = 0; $i -lt $HexData.Length; $i += 2) {
                        $KeyCredentialBytes[$i / 2] = [Convert]::ToByte($HexData.Substring($i, 2), 16)
                    }
                } else {
                    if ($Raw) {
                        return [PSCustomObject]@{
                            Success = $false
                            Error = "Invalid DNWithBinary format"
                        }
                    }
                    return "[Invalid format]"
                }
            }

            if (-not $KeyCredentialBytes -or $KeyCredentialBytes.Length -lt 8) {
                if ($Raw) {
                    return [PSCustomObject]@{
                        Success = $false
                        Error = "Invalid or empty KeyCredentialLink data"
                    }
                }
                return "[Invalid data]"
            }

            # Parse Version (4 bytes, little-endian)
            $Version = [BitConverter]::ToUInt32($KeyCredentialBytes, 0)
            if ($Version -ne 0x00000200) {
                if ($Raw) {
                    return [PSCustomObject]@{
                        Success = $false
                        Error = "Unknown version: 0x$($Version.ToString('X8'))"
                        Version = $Version
                    }
                }
                return "[Unknown version: 0x$($Version.ToString('X8'))]"
            }

            # Initialize result object
            $Result = [PSCustomObject]@{
                Success = $true
                Version = 2
                KeyID = $null
                KeyIDHex = $null
                DeviceID = $null
                KeyCreationTime = $null
                KeyLastLogonTime = $null
                KeyUsage = $null
                KeyUsageText = $null
                KeySource = $null
                KeySourceText = $null
                KeyMaterialLength = 0
                CustomKeyInfo = $null
                RawBytes = $KeyCredentialBytes
                ByteLength = $KeyCredentialBytes.Length
            }

            # Parse LTV entries starting at offset 4
            # MS-ADTS 2.2.19: Each entry is Length (2 bytes) + Identifier (1 byte) + Data (variable)
            $Offset = 4
            while ($Offset + 3 -le $KeyCredentialBytes.Length) {
                # Length (2 bytes, little-endian) - length of Data field only
                $EntryLength = [BitConverter]::ToUInt16($KeyCredentialBytes, $Offset)
                $Offset += 2

                # Identifier/Type (1 byte)
                $EntryType = $KeyCredentialBytes[$Offset]
                $Offset += 1

                # Check bounds
                if ($Offset + $EntryLength -gt $KeyCredentialBytes.Length) {
                    break
                }

                # Extract entry data
                $EntryData = if ($EntryLength -gt 0) { $KeyCredentialBytes[$Offset..($Offset + $EntryLength - 1)] } else { @() }
                $Offset += $EntryLength

                # Parse based on entry type (1 byte identifier per MS-ADTS 2.2.19)
                switch ($EntryType) {
                    0x01 {  # KeyID (SHA256 hash of public key)
                        if ($EntryData.Length -ge 16) {
                            $Result.KeyIDHex = [BitConverter]::ToString($EntryData).Replace('-', '').ToLower()
                            $Result.KeyID = $Result.KeyIDHex.Substring(0, 16) + "..."
                        }
                    }
                    0x02 {  # KeyHash (SHA256 of entries 3-9)
                        # Not displayed, but parsed for completeness
                    }
                    0x03 {  # KeyMaterial (BCRYPT_RSAKEY_BLOB)
                        $Result.KeyMaterialLength = $EntryLength
                    }
                    0x04 {  # KeyUsage
                        if ($EntryData.Length -ge 1) {
                            $Result.KeyUsage = $EntryData[0]
                            $Result.KeyUsageText = switch ($EntryData[0]) {
                                0x01 { "NGC" }
                                0x02 { "FIDO" }
                                0x07 { "FEK" }
                                default { "0x$($EntryData[0].ToString('X2'))" }
                            }
                        }
                    }
                    0x05 {  # KeySource
                        if ($EntryData.Length -ge 1) {
                            $Result.KeySource = $EntryData[0]
                            $Result.KeySourceText = switch ($EntryData[0]) {
                                0x00 { "AD" }
                                0x01 { "AzureAD" }
                                default { "0x$($EntryData[0].ToString('X2'))" }
                            }
                        }
                    }
                    0x06 {  # DeviceId (GUID)
                        if ($EntryData.Length -eq 16) {
                            try {
                                # Must use New-Object constructor syntax for byte array to GUID conversion
                                # [GUID]$EntryData does NOT work - it silently fails
                                $Result.DeviceID = (New-Object GUID(,$EntryData)).ToString()
                            } catch {
                                $Result.DeviceID = [BitConverter]::ToString($EntryData).Replace('-', '').ToLower()
                            }
                        }
                    }
                    0x07 {  # CustomKeyInformation
                        $Result.CustomKeyInfo = [BitConverter]::ToString($EntryData).Replace('-', '').ToLower()
                    }
                    0x08 {  # KeyApproximateLastLogonTimeStamp (FILETIME)
                        if ($EntryData.Length -eq 8) {
                            try {
                                $FileTime = [BitConverter]::ToInt64($EntryData, 0)
                                if ($FileTime -gt 0) {
                                    $Result.KeyLastLogonTime = [DateTime]::FromFileTimeUtc($FileTime)
                                }
                            } catch { }
                        }
                    }
                    0x09 {  # KeyCreationTime (FILETIME)
                        if ($EntryData.Length -eq 8) {
                            try {
                                $FileTime = [BitConverter]::ToInt64($EntryData, 0)
                                if ($FileTime -gt 0) {
                                    $Result.KeyCreationTime = [DateTime]::FromFileTimeUtc($FileTime)
                                }
                            } catch { }
                        }
                    }
                }
            }

            # Return based on mode
            if ($Raw) {
                return $Result
            }

            # Build compact display string: Full DeviceID + CreationTime
            # Source (AD) and Usage (NGC) are omitted as they're almost always the same for Shadow Credentials
            $Parts = @()

            if ($Result.DeviceID) {
                # Show FULL DeviceID (needed for -RemoveDeviceID parameter)
                $Parts += "DeviceID: $($Result.DeviceID)"
            }

            if ($Result.KeyCreationTime) {
                $Parts += "Created: $($Result.KeyCreationTime.ToString('yyyy-MM-dd HH:mm'))"
            }

            if ($Parts.Count -gt 0) {
                return $Parts -join " | "
            }

            return "KeyCredential ($($KeyCredentialBytes.Length) bytes)"

        } catch {
            if ($Raw) {
                return [PSCustomObject]@{
                    Success = $false
                    Error = $_.Exception.Message
                }
            }
            return "[Parse error: $($_.Exception.Message)]"
        }
    }
}



# ----- Connect-LDAP.ps1 -----

<#
.SYNOPSIS
    Establishes an LDAP/LDAPS connection to an Active Directory environment.

.DESCRIPTION
    Initializes an LDAP connection to the target domain using System.DirectoryServices.Protocols

    Supports:
    - LDAP (Port 389) and LDAPS (Port 636) with SSL/TLS
    - Global Catalog connections (Ports 3268/3269) via -AsGlobalCatalog
    - Alternative credentials (SimpleBind) or Windows Authentication (Negotiate)
    - Schannel (TLS client certificate) via -ClientCertificate (Pass-the-Cert)
    - Automatic domain and DC discovery
    - Anonymous access detection
    - Custom DNS server support (via $Script:LDAPContext['DnsServer'])

    In normal mode, stores the connection in $Script:LdapConnection and $Script:LDAPContext.
    In GC mode (-AsGlobalCatalog), returns the raw LdapConnection without modifying global state.

.PARAMETER Domain
    The target domain (FQDN).
    Optional - Default: Automatic detection via GetCurrentDomain()

.PARAMETER Server
    Specific Domain Controller (FQDN or IP).
    Optional - Default: Automatic via Domain

.PARAMETER Credential
    PSCredential object for alternative authentication.
    Optional - Default: Current user context (Negotiate/Kerberos)

.PARAMETER UseLDAPS
    Forces LDAPS (no fallback to LDAP).

.PARAMETER IgnoreSSLErrors
    Ignores SSL certificate errors for LDAPS connections (self-signed certs, expired certs,
    hostname mismatches, untrusted CAs, etc.).
    Default: $true (for maximum compatibility in pentesting environments)
    Can be explicitly disabled with -IgnoreSSLErrors:$false

.PARAMETER TimeoutSeconds
    Timeout in seconds for LDAP operations.
    Default: 30 seconds
    Valid range: 5-600 seconds. Increase for high-latency connections (SOCKS tunnels, VPN).

.PARAMETER AsGlobalCatalog
    Connects to the Global Catalog (port 3268 or 3269 with -UseLDAPS).
    Requires -Domain and -Server to be specified.
    Returns the raw LdapConnection object without storing it globally.

.EXAMPLE
    Connect-LDAP
    Connects to current domain (automatic detection)

.EXAMPLE
    Connect-LDAP -Domain "contoso.com" -UseLDAPS
    Connects to contoso.com via LDAPS

.EXAMPLE
    Connect-LDAP -Domain "contoso.com" -Credential (Get-Credential)
    Connects with alternative credentials

.EXAMPLE
    Connect-LDAP -Domain "contoso.com" -Server "dc01.contoso.com" -AsGlobalCatalog
    Returns a GC LdapConnection on port 3268

.OUTPUTS
    Hashtable with connection context (normal mode) or LdapConnection object (GC mode)

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Connect-LDAP {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$UseLDAPS,

        [Parameter(Mandatory=$false)]
        [bool]$IgnoreSSLErrors = $true,

        [Parameter(Mandatory=$false)]
        [ValidateRange(5, 600)]
        [int]$TimeoutSeconds = 30,

        [Parameter(Mandatory=$false)]
        [switch]$AsGlobalCatalog,

        [Parameter(Mandatory=$false)]
        [System.Security.Cryptography.X509Certificates.X509Certificate2]$ClientCertificate,

        # Forces explicit NTLM authentication via Sicily (AuthType::Ntlm) instead of Negotiate.
        # SSPI sends a pure NTLM NEGOTIATE_MESSAGE without offering Kerberos first.
        # Works against real AD DCs on domain-joined and non-domain-joined systems.
        # Requires -Credential to be set.
        [Parameter(Mandatory=$false)]
        [switch]$ForceNTLM,

        # Suppress user-visible error messages (Show-ConnectionError) while still tracking error codes.
        # Used by Connect-adPEAS when it knows it will auto-retry (e.g., LDAPS upgrade after SimpleBind failure).
        [Parameter(Mandatory=$false)]
        [switch]$SuppressErrorDisplay
    )

    begin {
        Write-Log "[Connect-LDAP] Starting LDAP connection..."

        # Reset connection state at the beginning
        $Script:ConnectionState = $null
        $Script:LastLDAPErrorCode = $null

        # SSL Certificate Validation Callback (only relevant for LDAPS)
        if ($IgnoreSSLErrors) {
            [System.Net.ServicePointManager]::ServerCertificateValidationCallback = {$true}
            # Disable CRL (Certificate Revocation List) checking to prevent ~15s timeout
            # during LDAPS Bind() when CRL Distribution Points are unreachable (lab/isolated environments)
            # SChannel performs CRL checks BEFORE VerifyServerCertificate callback is invoked
            [System.Net.ServicePointManager]::CheckCertificateRevocationList = $false
        }

        # Helper: Classify LDAP/connection errors and show appropriate error message
        # Used by Phase 5, Phase 6, and final catch block to avoid code duplication
        function Resolve-LDAPConnectionError {
            param(
                [Parameter(Mandatory)] $ErrorRecord,
                [string]$Context = "Connection",
                [switch]$BindSucceeded  # Set when Bind() succeeded but a subsequent SendRequest() failed
            )
            # Extract error message and code from exception chain
            # PowerShell wraps .NET exceptions: MethodInvocationException -> LdapException or DirectoryOperationException
            # - LdapException: has ErrorCode property (e.g., 49 = invalid credentials)
            # - DirectoryOperationException: thrown for LDAP result codes like StrongAuthRequired (8),
            #   but does NOT expose the numeric error code - must be identified by exception type
            $ex = $ErrorRecord.Exception
            $innerEx = $ex.InnerException

            # Walk the full exception chain to find known LDAP exception types
            $ldapEx = $null
            $dirOpEx = $null
            $walker = $ex
            while ($walker) {
                $typeName = $walker.GetType().FullName
                if ($typeName -eq 'System.DirectoryServices.Protocols.LdapException') {
                    $ldapEx = $walker
                    break
                }
                if ($typeName -eq 'System.DirectoryServices.Protocols.DirectoryOperationException') {
                    $dirOpEx = $walker
                }
                $walker = $walker.InnerException
            }

            $msg = if ($ldapEx) { $ldapEx.Message } elseif ($dirOpEx) { $dirOpEx.Message } elseif ($innerEx) { $innerEx.Message } else { $ex.Message }

            $errorInfo = $null
            $ldapErrorCode = $null

            if ($ldapEx) {
                # LdapException has ErrorCode property
                $ldapErrorCode = $ldapEx.ErrorCode
                $errorInfo = ConvertFrom-LDAPError -ErrorCode $ldapErrorCode
                Write-Log "[Connect-LDAP] $Context failed: $msg (LDAP error $ldapErrorCode`: $($errorInfo.Name))"
            } elseif ($dirOpEx) {
                # DirectoryOperationException: extract ResultCode from Response if available,
                # otherwise fall back to code 8 (StrongAuthRequired) for Bind failures where Response is null
                if ($dirOpEx.Response -and $dirOpEx.Response.ResultCode) {
                    $ldapErrorCode = [int]$dirOpEx.Response.ResultCode
                } else {
                    $ldapErrorCode = 8
                }
                $errorInfo = ConvertFrom-LDAPError -ErrorCode $ldapErrorCode
                Write-Log "[Connect-LDAP] $Context failed: $msg (LDAP error $ldapErrorCode`: $($errorInfo.Name))"
            } elseif ($innerEx -and $innerEx.PSObject.Properties['ErrorCode']) {
                # Generic exception with ErrorCode (e.g., HResult-based)
                $code = $innerEx.ErrorCode
                $errorInfo = ConvertFrom-HResult -HResult $code
                Write-Log "[Connect-LDAP] $Context failed: $msg (Error 0x$($code.ToString('X8')): $($errorInfo.Name))"
                if ($errorInfo.LDAPCode) { $ldapErrorCode = $errorInfo.LDAPCode }
            } else {
                Write-Log "[Connect-LDAP] $Context failed: $msg"
            }

            # Store LDAP error code and details for upstream callers (e.g., Connect-adPEAS LDAPS auto-upgrade)
            $Script:LastLDAPErrorCode = $ldapErrorCode
            $Script:LastLDAPErrorDetails = $msg

            $errorType = switch ($errorInfo.Category) {
                'AccessDenied' { if ($errorInfo.Name -match 'LOGON|CREDENTIALS|OPERATIONS_ERROR') { "AuthenticationFailed" } else { "PermissionError" } }
                'Network'      { "NetworkError" }
                'Domain'       { "DomainError" }
                'Timeout'      { "NetworkError" }
                'LDAP'         { "GenericError" }
                default        { "GenericError" }
            }

            # Override: LDAP 81 (SERVER_DOWN) after a successful Bind() is NOT a network error -
            # the server IS reachable and authentication succeeded. The failure is in the LDAP
            # protocol layer (post-bind request processing). Use GenericError to avoid the
            # misleading "Server unreachable" title from NetworkError.
            if ($ldapErrorCode -eq 81 -and $BindSucceeded) {
                $errorType = "GenericError"
            }

            $Script:ConnectionState = $errorType
            if (-not $SuppressErrorDisplay) {
                if ($null -ne $ldapErrorCode) {
                    # For LDAP 81 after a successful Bind(), provide more specific details:
                    # the TCP connection and authentication handshake worked, but the server
                    # stopped responding to LDAP protocol messages (e.g., incomplete LDAP server implementation)
                    $extraDetails = $null
                    if ($ldapErrorCode -eq 81 -and $BindSucceeded) {
                        $extraDetails = "Bind() succeeded but the server did not respond to the search request. The LDAP server may not fully support authenticated queries."
                    }
                    # For LDAP 82 after a successful Bind(), distinguish the NTLM/GSSAPI negotiation failure
                    # from a Kerberos SPN mismatch (which is the typical non-bind context for error 82)
                    elseif ($ldapErrorCode -eq 82 -and $BindSucceeded) {
                        $extraDetails = "GSSAPI/NTLM negotiation failed during Bind() - the server may not support this authentication mechanism."
                    }
                    if ($extraDetails) {
                        Show-ConnectionError -ErrorType $errorType -ErrorCode $ldapErrorCode -ErrorCodeType "LDAP" -Details $extraDetails -NoThrow
                    } else {
                        Show-ConnectionError -ErrorType $errorType -ErrorCode $ldapErrorCode -ErrorCodeType "LDAP" -NoThrow
                    }
                } else {
                    Show-ConnectionError -ErrorType $errorType -Details $msg -NoThrow
                }
            }
        }
    }

    process {
        try {
            # ===== Phase 1: Domain Discovery =====
            if ($AsGlobalCatalog) {
                # GC mode: Domain and Server must be pre-populated from existing session
                if ([string]::IsNullOrEmpty($Domain) -or [string]::IsNullOrEmpty($Server)) {
                    Write-Log "[Connect-LDAP] AsGlobalCatalog requires -Domain and -Server parameters"
                    return $null
                }
                $DomainDN = "DC=" + ($Domain -replace "\.", ",DC=")
                Write-Log "[Connect-LDAP] GC mode: Server=$Server, Domain=$Domain"
            } else {
                if ([string]::IsNullOrEmpty($Domain)) {
                    Write-Log "[Connect-LDAP] No domain specified, attempting automatic discovery..."
                    try {
                        $CurrentDomain = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()
                        $Domain = $CurrentDomain.Name
                        Write-Log "[Connect-LDAP] Automatically detected domain: $Domain"
                    } catch {
                        $Script:ConnectionState = "DomainError"
                        Show-ConnectionError -ErrorType "DomainError" -Details "Domain parameter required or system must be domain-joined" -NoThrow
                        return $null
                    }
                }

                # Determine Domain Controller if not specified
                if ([string]::IsNullOrEmpty($Server)) {
                    Write-Log "[Connect-LDAP] No server specified, using domain name: $Domain"
                    $Server = $Domain
                }

                # Create Distinguished Name for Domain
                $DomainDN = "DC=" + ($Domain -replace "\.", ",DC=")
                Write-Log "[Connect-LDAP] Domain DN: $DomainDN"
            }

            # ===== Phase 2: DNS Resolution =====
            Write-Log "[Connect-LDAP] Testing DNS resolution for: $Server"
            $ResolvedIPs = $null
            $ResolvedIPString = $null

            # Check if custom DNS server is configured (from Connect-adPEAS -DnsServer parameter)
            $CustomDnsServer = $null
            if ($Script:LDAPContext -and $Script:LDAPContext['DnsServer']) {
                $CustomDnsServer = $Script:LDAPContext['DnsServer']
                Write-Log "[Connect-LDAP] Using custom DNS server: $CustomDnsServer"
            }

            try {
                if ($CustomDnsServer) {
                    # Use custom DNS resolution via Resolve-adPEASName
                    $ResolvedIPString = Resolve-adPEASName -Name $Server -DnsServer $CustomDnsServer
                    if ($ResolvedIPString) {
                        Write-Log "[Connect-LDAP] DNS resolution via custom DNS successful: $ResolvedIPString"
                    } else {
                        throw "Custom DNS resolution failed for $Server"
                    }
                } else {
                    # Use system DNS
                    $ResolvedIPs = [System.Net.Dns]::GetHostAddresses($Server)
                    if (-not $ResolvedIPs -or $ResolvedIPs.Count -eq 0) {
                        throw "DNS resolution returned no addresses"
                    }
                    $ResolvedIPString = $ResolvedIPs[0].IPAddressToString
                    Write-Log "[Connect-LDAP] DNS resolution successful: $ResolvedIPString"
                }
            } catch {
                $Script:ConnectionState = "DomainError"
                $Detail = if ($Server -eq $Domain) {
                    "Domain '$Domain' could not be resolved"
                } else {
                    "Server '$Server' could not be resolved"
                }
                Show-ConnectionError -ErrorType "DomainError" -Details $Detail -NoThrow
                return $null
            }

            # ===== Phase 3: Port Reachability =====
            # Use resolved IP for connection test when custom DNS is active
            $ConnectTarget = if ($CustomDnsServer -and $ResolvedIPString) { $ResolvedIPString } else { $Server }
            Write-Log "[Connect-LDAP] Testing port reachability to: $ConnectTarget"
            $ServerReachable = $false
            $TestPort = if ($AsGlobalCatalog) {
                if ($UseLDAPS) { 3269 } else { 3268 }
            } else {
                if ($UseLDAPS) { 636 } else { 389 }
            }

            try {
                $TcpClient = New-Object System.Net.Sockets.TcpClient
                $ConnectTask = $TcpClient.BeginConnect($ConnectTarget, $TestPort, $null, $null)
                $WaitHandle = $ConnectTask.AsyncWaitHandle

                if ($WaitHandle.WaitOne(2000, $false)) {
                    $TcpClient.EndConnect($ConnectTask)
                    $ServerReachable = $true
                    Write-Log "[Connect-LDAP] Server is reachable on port $TestPort"
                }
                $TcpClient.Close()
            } catch {
                Write-Log "[Connect-LDAP] Port test failed: $_"
            }

            if (-not $ServerReachable) {
                $Script:ConnectionState = "NetworkError"
                $PortDesc = "$TestPort ($(if ($AsGlobalCatalog) { 'GC' } else { if ($UseLDAPS) { 'LDAPS' } else { 'LDAP' } }))"
                Show-ConnectionError -ErrorType "NetworkError" -Details "Port $PortDesc unreachable on $Server" -NoThrow
                return $null
            }

            # ===== Phase 3b: SSL/TLS Handshake Test (LDAPS only) =====
            if ($UseLDAPS) {
                $SSLPort = $TestPort  # Already set to 3269 for GC, 636 for normal LDAPS
                Write-Log "[Connect-LDAP] Testing SSL/TLS handshake on port $SSLPort..."
                $SSLTestPassed = $false
                $sslErrorInfo = $null

                try {
                    $TcpClientSSL = New-Object System.Net.Sockets.TcpClient
                    $TcpClientSSL.Connect($ConnectTarget, $SSLPort)

                    $SslStream = New-Object System.Net.Security.SslStream(
                        $TcpClientSSL.GetStream(),
                        $false,
                        { param($sslSender, $cert, $chain, $errors)
                            return $IgnoreSSLErrors -or ($errors -eq [System.Net.Security.SslPolicyErrors]::None)
                        }
                    )

                    # Authenticate as client
                    $SslStream.AuthenticateAsClient($Server)
                    $SSLTestPassed = $true

                    Write-Log "[Connect-LDAP] SSL/TLS handshake successful"
                    Write-Log "[Connect-LDAP] SSL Protocol: $($SslStream.SslProtocol)"
                    Write-Log "[Connect-LDAP] Cipher: $($SslStream.CipherAlgorithm)"
                    if ($SslStream.RemoteCertificate) {
                        Write-Log "[Connect-LDAP] Certificate Subject: $($SslStream.RemoteCertificate.Subject)"
                        Write-Log "[Connect-LDAP] Certificate Issuer: $($SslStream.RemoteCertificate.Issuer)"

                        # Pre-cache the certificate chain with CRL check disabled (X509RevocationMode.NoCheck)
                        # This prevents a ~15s timeout during LdapConnection.Bind() when SChannel tries to
                        # download the CRL from an unreachable CDP (common in labs/isolated environments).
                        # The Windows CryptoAPI caches the chain result, so the subsequent Bind() gets a cache hit.
                        if ($IgnoreSSLErrors) {
                            try {
                                $cert2 = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($SslStream.RemoteCertificate)
                                $chain = New-Object System.Security.Cryptography.X509Certificates.X509Chain
                                $chain.ChainPolicy.RevocationMode = [System.Security.Cryptography.X509Certificates.X509RevocationMode]::NoCheck
                                $chain.ChainPolicy.RevocationFlag = [System.Security.Cryptography.X509Certificates.X509RevocationFlag]::EntireChain
                                $chain.ChainPolicy.VerificationFlags = [System.Security.Cryptography.X509Certificates.X509VerificationFlags]::AllFlags
                                [void]$chain.Build($cert2)
                                $chain.Reset()
                                Write-Log "[Connect-LDAP] Certificate chain pre-cached (CRL check disabled)"
                            } catch {
                                Write-Log "[Connect-LDAP] Certificate chain pre-cache failed (non-critical): $_"
                            }
                        }
                    }

                    $SslStream.Close()
                    $TcpClientSSL.Close()
                }
                catch {
                    $sslErrorInfo = Get-ExceptionErrorInfo -Exception $_.Exception -Context "SSL handshake"
                    Write-Log "[Connect-LDAP] SSL/TLS handshake FAILED: $($sslErrorInfo.Message)"

                    if ($sslErrorInfo.Category -eq 'SSLCertificate' -and -not $IgnoreSSLErrors) {
                        Write-Log "[Connect-LDAP] Consider using -IgnoreSSLErrors parameter"
                    }
                }

                if (-not $SSLTestPassed) {
                    $errorType = if ($sslErrorInfo.Category -eq 'SSLCertificate') { "CertificateError" } else { "SSLHandshakeError" }
                    $Script:ConnectionState = $errorType
                    Show-ConnectionError -ErrorType $errorType -Details $sslErrorInfo.Message -NoThrow
                    return $null
                }
            }

            # ===== Phase 4: Anonymous Access Check (A-NullSession) =====
            # Test if anonymous LDAP bind is possible and can read AD data
            # This check is silent - failures are expected and NOT displayed to user
            # UNIFIED: Use System.DirectoryServices.Protocols.LdapConnection with Anonymous AuthType
            # NOTE: Skip for LDAPS - anonymous access over SSL is extremely rare and the SSL handshake timeout cannot be reliably controlled, causing delays of 10+ seconds
            # NOTE: Skip for GC mode - anonymous check is not relevant for auxiliary GC connections
            $Script:AnonymousAccessEnabled = $false
            $Script:AnonymousAccessDetails = $null

            if ($AsGlobalCatalog) {
                Write-Log "[Connect-LDAP] Skipping anonymous access check for GC mode"
            }
            elseif ($UseLDAPS) {
                Write-Log "[Connect-LDAP] Skipping anonymous access check for LDAPS (rarely enabled over SSL)"
            }

            $AnonLdapConn = $null
            if (-not $UseLDAPS -and -not $AsGlobalCatalog) {
            try {
                # Use resolved IP when custom DNS is active
                $AnonTarget = if ($CustomDnsServer -and $ResolvedIPString) { $ResolvedIPString } else { $Server }

                # Create temporary LdapConnection for anonymous bind test (always port 389 - LDAPS/GC are skipped above)
                $AnonIdentifier = New-Object System.DirectoryServices.Protocols.LdapDirectoryIdentifier($AnonTarget, 389)
                $AnonLdapConn = New-Object System.DirectoryServices.Protocols.LdapConnection($AnonIdentifier)
                $AnonLdapConn.SessionOptions.ProtocolVersion = 3
                # Short timeouts for anonymous test - Bind() uses SendTimeout, SendRequest uses Timeout
                $AnonLdapConn.Timeout = [TimeSpan]::FromSeconds(2)
                $AnonLdapConn.SessionOptions.SendTimeout = [TimeSpan]::FromSeconds(2)

                # Set Anonymous authentication
                $AnonLdapConn.AuthType = [System.DirectoryServices.Protocols.AuthType]::Anonymous

                # Attempt anonymous bind
                $AnonLdapConn.Bind()
                Write-Log "[Connect-LDAP] Anonymous bind successful - testing read access..."

                # Try to read the domain object
                $AnonSearchRequest = New-Object System.DirectoryServices.Protocols.SearchRequest(
                    $DomainDN,
                    "(objectClass=domainDNS)",
                    [System.DirectoryServices.Protocols.SearchScope]::Base,
                    @("distinguishedName", "name", "objectSid")
                )

                $AnonSearchResponse = $AnonLdapConn.SendRequest($AnonSearchRequest)

                if ($AnonSearchResponse -and $AnonSearchResponse.Entries.Count -gt 0) {
                    $AnonEntry = $AnonSearchResponse.Entries[0]

                    if ($AnonEntry.DistinguishedName) {
                        # Anonymous access is possible
                        $Script:AnonymousAccessEnabled = $true

                        # Determine what we can read
                        $ReadableAttrs = @()
                        foreach ($attr in $AnonEntry.Attributes.AttributeNames) {
                            $ReadableAttrs += $attr
                        }

                        # Try to enumerate users
                        $CanEnumUsers = $false
                        $UserCount = 0
                        try {
                            $UserSearchRequest = New-Object System.DirectoryServices.Protocols.SearchRequest(
                                $DomainDN,
                                "(objectClass=user)",
                                [System.DirectoryServices.Protocols.SearchScope]::Subtree,
                                @("sAMAccountName")
                            )
                            $UserSearchRequest.SizeLimit = 5  # Just test if we can read any

                            $UserSearchResponse = $AnonLdapConn.SendRequest($UserSearchRequest)
                            $UserCount = $UserSearchResponse.Entries.Count
                            if ($UserCount -gt 0) {
                                $CanEnumUsers = $true
                            }
                        } catch {
                            Write-Log "[Connect-LDAP] Anonymous user enumeration test failed (expected)"
                        }

                        $Script:AnonymousAccessDetails = @{
                            CanReadDomainRoot = $true
                            ReadableAttributes = $ReadableAttrs
                            CanEnumerateUsers = $CanEnumUsers
                            UsersSampled = $UserCount
                        }

                        Write-Log "[Connect-LDAP] WARNING: Anonymous LDAP access is enabled!"
                        Write-Log "[Connect-LDAP] Readable attributes: $($ReadableAttrs -join ', ')"
                        if ($CanEnumUsers) {
                            Write-Log "[Connect-LDAP] WARNING: Anonymous user enumeration is possible!"
                        }
                    }
                }

            } catch {
                # Anonymous access not possible (expected/secure configuration)
                Write-Log "[Connect-LDAP] Anonymous access test: denied (secure - this is expected)"
                $Script:AnonymousAccessEnabled = $false
            } finally {
                # Always dispose the temporary anonymous connection
                if ($AnonLdapConn) {
                    try { $AnonLdapConn.Dispose() } catch { }
                }
            }
            }  # End of: if (-not $UseLDAPS -and -not $AsGlobalCatalog)

            # ===== Phase 5: LDAP Connection =====
            # UNIFIED APPROACH: Always use System.DirectoryServices.Protocols.LdapConnection for ALL operations
            # This includes queries (SearchRequest) AND modifications (ModifyRequest)
            $ConnectionEstablished = $false
            $LdapProtocolConn = $null
            $LDAPPort = if ($AsGlobalCatalog) {
                if ($UseLDAPS) { 3269 } else { 3268 }
            } else {
                if ($UseLDAPS) { 636 } else { 389 }
            }
            $LDAPTarget = $Server
            Write-Log "[Connect-LDAP] Using hostname for LDAP connection: $LDAPTarget"

            $ProtocolDisplay = if ($AsGlobalCatalog) { "GC" } elseif ($UseLDAPS) { "LDAPS" } else { "LDAP" }
            Write-Log "[Connect-LDAP] Attempting $ProtocolDisplay connection to ${LDAPTarget}:${LDAPPort}..."

            try {
                # ===== UNIFIED: Always use System.DirectoryServices.Protocols.LdapConnection =====
                # This works reliably for both LDAP (389) and LDAPS (636)
                Write-Log "[Connect-LDAP] Using System.DirectoryServices.Protocols.LdapConnection for $ProtocolDisplay..."

                # Load the assembly
                Add-Type -AssemblyName System.DirectoryServices.Protocols -ErrorAction Stop

                # Create LdapConnection with server:port
                $LdapIdentifier = New-Object System.DirectoryServices.Protocols.LdapDirectoryIdentifier($LDAPTarget, $LDAPPort)
                $LdapProtocolConn = New-Object System.DirectoryServices.Protocols.LdapConnection($LdapIdentifier)

                if ($ClientCertificate) {
                    # ===== Schannel (Pass-the-Cert): Minimal configuration =====
                    # CRITICAL: For Schannel to work, the LdapConnection must be configured with
                    # MINIMAL SessionOptions. Extra options like ProtocolVersion, ReferralChasing,
                    # and Timeouts interfere with the implicit TLS authentication.
                    # This matches exactly what Invoke-PassTheCert (Viper-One) does:
                    # Only ClientCertificates.Add() + SecureSocketLayer + VerifyServerCertificate
                    $LdapProtocolConn.ClientCertificates.Add($ClientCertificate) | Out-Null
                    $LdapProtocolConn.SessionOptions.SecureSocketLayer = $true
                    $LdapProtocolConn.SessionOptions.VerifyServerCertificate = { param($conn, $cert) return $true }
                    Write-Log "[Connect-LDAP] Schannel: Minimal config (ClientCert + SSL + VerifyServerCert)"
                } else {
                    # ===== Standard configuration for non-Schannel connections =====
                    # Configure protocol version
                    $LdapProtocolConn.SessionOptions.ProtocolVersion = 3

                    # Configure timeouts for faster connection/response
                    $LdapProtocolConn.Timeout = [TimeSpan]::FromSeconds($TimeoutSeconds)
                    $SendTimeoutSeconds = [Math]::Max(5, [Math]::Floor($TimeoutSeconds / 2))
                    $LdapProtocolConn.SessionOptions.SendTimeout = [TimeSpan]::FromSeconds($SendTimeoutSeconds)
                    Write-Log "[Connect-LDAP] Configured timeouts: Operation=${TimeoutSeconds}s, Send=${SendTimeoutSeconds}s"

                    # Disable referral chasing
                    $LdapProtocolConn.SessionOptions.ReferralChasing = [System.DirectoryServices.Protocols.ReferralChasingOptions]::None
                    Write-Log "[Connect-LDAP] Referral chasing disabled (domain-local queries only)"

                    # Configure SSL for LDAPS
                    if ($UseLDAPS) {
                        $LdapProtocolConn.SessionOptions.SecureSocketLayer = $true
                        if ($IgnoreSSLErrors) {
                            $LdapProtocolConn.SessionOptions.VerifyServerCertificate = { param($conn, $cert) return $true }
                            Write-Log "[Connect-LDAP] SSL certificate validation disabled (IgnoreSSLErrors)"
                        }
                    }
                }

                # Set authentication and bind
                if ($ClientCertificate) {
                    # Schannel: No AuthType, no Bind() - exactly like Viper-One and AlmondOffSec
                    # The first SendRequest() will trigger AutoBind with TLS client certificate identity
                    Write-Log "[Connect-LDAP] Schannel: No explicit AuthType or Bind() - TLS handshake provides identity"
                }
                elseif ($Credential -and $ForceNTLM) {
                    # Explicit NTLM via Sicily: AuthType::Ntlm + NetworkCredential.
                    # Sicily is Microsoft's proprietary NTLM-over-LDAP mechanism. Unlike Negotiate,
                    # SSPI sends a pure NTLM NEGOTIATE_MESSAGE without offering Kerberos first.
                    # Works correctly against real AD DCs (domain-joined and non-domain-joined).
                    $NtlmNetCred = $Credential.GetNetworkCredential()
                    $NtlmUser   = $NtlmNetCred.UserName
                    $NtlmDomain = $NtlmNetCred.Domain
                    $NtlmPass   = $NtlmNetCred.Password

                    Write-Log "[Connect-LDAP] Configuring explicit NTLM authentication (Sicily): $NtlmDomain\$NtlmUser"
                    $LdapProtocolConn.AuthType  = [System.DirectoryServices.Protocols.AuthType]::Ntlm
                    $LdapProtocolConn.Credential = New-Object System.Net.NetworkCredential($NtlmUser, $NtlmPass, $NtlmDomain)
                }
                elseif ($Credential) {
                    $NetworkCred = $Credential.GetNetworkCredential()
                    $UserName = $NetworkCred.UserName  # Username part only (without domain prefix)
                    $Password = $NetworkCred.Password
                    $CredDomain = $NetworkCred.Domain  # Domain part (if user specified DOMAIN\user)

                    # SimpleBind requires domain-qualified username
                    # AD accepts: NETBIOS\user or user@domain.fqdn (UPN format)
                    # AD does NOT accept: domain.fqdn\user

                    # Determine correct format based on what user provided:
                    # 1. If NetworkCredential.Domain is set -> user specified DOMAIN\username -> reconstruct it
                    # 2. If username contains '@' -> user specified UPN -> keep it as-is
                    # 3. Otherwise -> bare username -> auto-qualify with UPN format

                    if (-not [string]::IsNullOrEmpty($CredDomain)) {
                        # User specified DOMAIN\username format - reconstruct it
                        $UserName = "$CredDomain\$UserName"
                        Write-Log "[Connect-LDAP] Username from credential (NETBIOS format): $UserName"
                    }
                    elseif ($UserName -match '@') {
                        # User specified UPN format (user@domain.com) - keep as-is
                        Write-Log "[Connect-LDAP] Username from credential (UPN format): $UserName"
                    }
                    else {
                        # Bare username without domain/UPN - auto-qualify with UPN format
                        if ($Domain) {
                            $UserName = "$UserName@$Domain"
                            Write-Log "[Connect-LDAP] Username qualified for SimpleBind (UPN): $UserName"
                        } else {
                            Write-Log "[Connect-LDAP] WARNING: Username '$UserName' is not domain-qualified and no domain available"
                        }
                    }

                    Write-Log "[Connect-LDAP] Configuring SimpleBind with credentials: $UserName"

                    # Use Basic auth for SimpleBind
                    $LdapProtocolConn.AuthType = [System.DirectoryServices.Protocols.AuthType]::Basic
                    $LdapProtocolConn.Credential = New-Object System.Net.NetworkCredential($UserName, $Password)
                } else {
                    Write-Log "[Connect-LDAP] Configuring Negotiate (Kerberos/NTLM) authentication"
                    $LdapProtocolConn.AuthType = [System.DirectoryServices.Protocols.AuthType]::Negotiate
                }

                # Bind to server (skip for Schannel - AutoBind handles it on first SendRequest)
                $LdapBindSucceeded = $false
                if ($ClientCertificate) {
                    Write-Log "[Connect-LDAP] Schannel: Skipping Bind() - first SendRequest() will trigger AutoBind"
                    $LdapBindSucceeded = $true  # AutoBind - treat as succeeded for error context
                } else {
                    Write-Log "[Connect-LDAP] Binding to $ProtocolDisplay server..."
                    $bindStopwatch = [System.Diagnostics.Stopwatch]::StartNew()
                    $LdapProtocolConn.Bind()
                    $bindStopwatch.Stop()
                    Write-Log "[Connect-LDAP] $ProtocolDisplay bind successful! ($($bindStopwatch.ElapsedMilliseconds)ms)"
                    $LdapBindSucceeded = $true
                }

                if ($AsGlobalCatalog) {
                    # ===== GC Mode: Verify isGlobalCatalogReady and return =====
                    # For GC connections, skip RootDSE/DomainSID/UserVerification and return
                    # the raw LdapConnection WITHOUT writing to global state.
                    $ConnectionEstablished = $true

                    try {
                        $gcRootDSE = New-Object System.DirectoryServices.Protocols.SearchRequest(
                            "", "(objectClass=*)",
                            [System.DirectoryServices.Protocols.SearchScope]::Base,
                            @("isGlobalCatalogReady")
                        )
                        $gcRootDSEResponse = $LdapProtocolConn.SendRequest($gcRootDSE)
                        $isGC = $false
                        if ($gcRootDSEResponse -and $gcRootDSEResponse.Entries.Count -gt 0) {
                            $gcReadyAttr = $gcRootDSEResponse.Entries[0].Attributes["isglobalcatalogready"]
                            if ($gcReadyAttr -and $gcReadyAttr.Count -gt 0) {
                                $isGC = ([string]$gcReadyAttr[0]) -eq "TRUE"
                            }
                        }
                        if (-not $isGC) {
                            Write-Log "[Connect-LDAP] GC mode: ${LDAPTarget}:${LDAPPort} is NOT a Global Catalog (isGlobalCatalogReady != TRUE)"
                            try { $LdapProtocolConn.Dispose() } catch { }
                            return $null
                        }
                    } catch {
                        Write-Log "[Connect-LDAP] GC mode: Could not verify GC status on ${LDAPTarget}:${LDAPPort}: $($_.Exception.Message)"
                        try { $LdapProtocolConn.Dispose() } catch { }
                        return $null
                    }

                    Write-Log "[Connect-LDAP] GC mode: Connection to ${LDAPTarget}:${LDAPPort} established and verified as Global Catalog"
                    return $LdapProtocolConn
                }

                # ===== Normal Mode: Test search and store globally =====
                # Test by searching for domain root
                Write-Log "[Connect-LDAP] Testing $ProtocolDisplay connection with search query..."
                Write-Log "[Connect-LDAP] Connection state: AuthType=$($LdapProtocolConn.AuthType), AutoBind=$($LdapProtocolConn.AutoBind)"
                if ($ClientCertificate) {
                    Write-Log "[Connect-LDAP] Client certificates count: $($LdapProtocolConn.ClientCertificates.Count)"
                }
                $SearchRequest = New-Object System.DirectoryServices.Protocols.SearchRequest(
                    $DomainDN,
                    "(objectClass=domainDNS)",
                    [System.DirectoryServices.Protocols.SearchScope]::Base,
                    @("distinguishedName", "name")
                )

                $SearchResponse = $LdapProtocolConn.SendRequest($SearchRequest)

                if ($SearchResponse -and $SearchResponse.Entries.Count -gt 0) {
                    $TestDN = $SearchResponse.Entries[0].DistinguishedName
                    Write-Log "[Connect-LDAP] $ProtocolDisplay search successful! DN: $TestDN"
                    $ConnectionEstablished = $true

                    # Store the LdapConnection for ALL operations (queries AND modifications)
                    $Script:LdapConnection = $LdapProtocolConn
                    Write-Log "[Connect-LDAP] LdapConnection stored for all LDAP operations"

                } else {
                    throw "$ProtocolDisplay search returned no results"
                }

            } catch {
                # Enhanced error logging for Schannel debugging
                if ($ClientCertificate) {
                    Write-Log "[Connect-LDAP] Schannel connection error details:"
                    Write-Log "[Connect-LDAP]   Exception Type: $($_.Exception.GetType().FullName)"
                    Write-Log "[Connect-LDAP]   Message: $($_.Exception.Message)"
                    if ($_.Exception.InnerException) {
                        Write-Log "[Connect-LDAP]   Inner Exception: $($_.Exception.InnerException.Message)"
                        Write-Log "[Connect-LDAP]   Inner Type: $($_.Exception.InnerException.GetType().FullName)"
                    }
                    # DirectoryOperationException has ResultCode and ErrorMessage
                    if ($_.Exception -is [System.DirectoryServices.Protocols.DirectoryOperationException]) {
                        $dirEx = $_.Exception
                        Write-Log "[Connect-LDAP]   ResultCode: $($dirEx.Response.ResultCode)"
                        Write-Log "[Connect-LDAP]   ErrorMessage: $($dirEx.Response.ErrorMessage)"
                    }
                }

                Resolve-LDAPConnectionError -ErrorRecord $_ -Context "LDAP connection" -BindSucceeded:$LdapBindSucceeded

                # Dispose the connection on failure to avoid resource leak
                if ($LdapProtocolConn) {
                    try { $LdapProtocolConn.Dispose() } catch { }
                }
            }

            # Stop if connection failed
            if (-not $ConnectionEstablished) {
                return $null
            }

            # ===== Phase 6: RootDSE Retrieval =====
            # UNIFIED: Always use LdapConnection (works for both LDAP and LDAPS)
            Write-Log "[Connect-LDAP] Retrieving RootDSE via LdapConnection..."
            $RootDSEData = @{}

            try {
                # Request RootDSE attributes
                # IMPORTANT: For System.DirectoryServices.Protocols, we need to add attributes via the Attributes property, not the constructor.
                # The constructor's string[] parameter doesn't work reliably for all LDAP servers.
                $RootDSERequest = New-Object System.DirectoryServices.Protocols.SearchRequest
                $RootDSERequest.DistinguishedName = ""  # Empty DN = RootDSE
                $RootDSERequest.Filter = "(objectClass=*)"
                $RootDSERequest.Scope = [System.DirectoryServices.Protocols.SearchScope]::Base

                # Add attributes to request (this is the correct way for S.DS.P)
                $attributesToExtract = @(
                    "defaultNamingContext",
                    "configurationNamingContext",
                    "schemaNamingContext",
                    "rootDomainNamingContext",
                    "dnsHostName",
                    "domainFunctionality",
                    "forestFunctionality"
                )
                foreach ($attr in $attributesToExtract) {
                    [void]$RootDSERequest.Attributes.Add($attr)
                }

                Write-Log "[Connect-LDAP] Sending RootDSE request for attributes: $($attributesToExtract -join ', ')"

                $RootDSEResponse = $Script:LdapConnection.SendRequest($RootDSERequest)

                if ($RootDSEResponse -and $RootDSEResponse.Entries.Count -gt 0) {
                    $RootDSEEntry = $RootDSEResponse.Entries[0]

                    # Debug: Log what we got back
                    Write-Log "[Connect-LDAP] RootDSE entry returned, Attributes.Count = $($RootDSEEntry.Attributes.Count)"

                    # Extract attributes from the response
                    # Use direct access by attribute name (case-insensitive in LDAP)
                    foreach ($attrName in $attributesToExtract) {
                        if ($RootDSEEntry.Attributes.Contains($attrName)) {
                            $dirAttr = $RootDSEEntry.Attributes[$attrName]
                            if ($dirAttr -and $dirAttr.Count -gt 0) {
                                # GetValues returns the actual values as the specified type
                                $value = $dirAttr.GetValues([string])[0]
                                $RootDSEData[$attrName] = $value
                                Write-Log "[Connect-LDAP] RootDSE attribute $attrName = $value"
                            }
                        } else {
                            Write-Log "[Connect-LDAP] RootDSE attribute $attrName not found in server response"
                        }
                    }

                    Write-Log "[Connect-LDAP] RootDSE retrieved successfully with $($RootDSEData.Count) attributes"
                } else {
                    throw "RootDSE query returned no results"
                }

            } catch {
                Resolve-LDAPConnectionError -ErrorRecord $_ -Context "RootDSE retrieval"
                return $null
            }

            # Get actual DC name from RootDSE
            $ActualDCName = if ($RootDSEData["dnsHostName"]) {
                $RootDSEData["dnsHostName"]
            } else {
                $Server
            }

            # ===== Phase 7: Build Domain Info =====
            $DomainInfo = @{
                Domain = $Domain
                Server = $ActualDCName
                DomainDN = $DomainDN
                Protocol = if ($UseLDAPS) { "LDAPS" } else { "LDAP" }
                Port = if ($UseLDAPS) { 636 } else { 389 }

                # RootDSE Properties (from RootDSEData hashtable)
                DefaultNamingContext = $RootDSEData["defaultNamingContext"]
                ConfigurationNamingContext = $RootDSEData["configurationNamingContext"]
                ConfigurationDN = $RootDSEData["configurationNamingContext"]
                SchemaNamingContext = $RootDSEData["schemaNamingContext"]
                RootDomainNamingContext = $RootDSEData["rootDomainNamingContext"]
                DnsHostName = $RootDSEData["dnsHostName"]
                DomainFunctionality = $RootDSEData["domainFunctionality"]
                ForestFunctionality = $RootDSEData["forestFunctionality"]

                # Connection Details
                LdapConnection = $Script:LdapConnection  # Primary connection for all operations
                Credential = $Credential
                Timestamp = Get-Date
                Connected = $true
                UseLDAPS = $UseLDAPS

                # Track explicit parameters
                ExplicitServer = $PSBoundParameters.ContainsKey('Server')
                ExplicitDomain = $PSBoundParameters.ContainsKey('Domain')
                ExplicitCredential = $PSBoundParameters.ContainsKey('Credential')

                # Schannel (Pass-the-Cert)
                ClientCertificate = $ClientCertificate  # X509Certificate2 object for session reuse
            }

            # ===== Phase 7b: Get Domain SID =====
            # UNIFIED: Always use LdapConnection (works for both LDAP and LDAPS)
            Write-Log "[Connect-LDAP] Retrieving Domain SID via LdapConnection..."
            $DomainSID = $null
            try {
                $SIDRequest = New-Object System.DirectoryServices.Protocols.SearchRequest(
                    $DomainDN,
                    "(objectClass=domainDNS)",
                    [System.DirectoryServices.Protocols.SearchScope]::Base,
                    @("objectSid")
                )
                $SIDResponse = $Script:LdapConnection.SendRequest($SIDRequest)

                if ($SIDResponse -and $SIDResponse.Entries.Count -gt 0 -and $SIDResponse.Entries[0].Attributes["objectsid"]) {
                    $SIDBytes = $SIDResponse.Entries[0].Attributes["objectsid"][0]
                    $DomainSID = (New-Object System.Security.Principal.SecurityIdentifier($SIDBytes, 0)).Value
                    Write-Log "[Connect-LDAP] Domain SID: $DomainSID"
                }
            } catch {
                Write-Log "[Connect-LDAP] Could not retrieve Domain SID: $_"
            }

            $DomainInfo['DomainSID'] = $DomainSID

            # ===== Phase 7b2: Resolve the TRUE NetBIOS domain name =====
            # The NetBIOS name is NOT the first DNS label. A domain "example.com"
            # can have the NetBIOS name "CORP". The only authoritative source is the crossRef
            # object in the Partitions container (nETBIOSName keyed by nCName=<DomainDN>).
            # Deriving it from Domain.Split('.')[0] is wrong for any domain that was renamed or
            # provisioned with a NetBIOS name that differs from its DNS label. Resolve it once
            # here so every consumer (Resolve-CrossDomainIdentity, Get-DomainInformation, etc.)
            # can read LDAPContext.DomainNetBIOS instead of guessing.
            $DomainNetBIOS = $null
            try {
                $ConfigNC = $RootDSEData["configurationNamingContext"]
                if ($ConfigNC) {
                    $PartitionsDN = "CN=Partitions,$ConfigNC"
                    $CrossRefRequest = New-Object System.DirectoryServices.Protocols.SearchRequest(
                        $PartitionsDN,
                        "(&(objectClass=crossRef)(nCName=$DomainDN))",
                        [System.DirectoryServices.Protocols.SearchScope]::OneLevel,
                        @("nETBIOSName")
                    )
                    $CrossRefResponse = $Script:LdapConnection.SendRequest($CrossRefRequest)
                    if ($CrossRefResponse -and $CrossRefResponse.Entries.Count -gt 0 -and $CrossRefResponse.Entries[0].Attributes["netbiosname"]) {
                        $DomainNetBIOS = [string]$CrossRefResponse.Entries[0].Attributes["netbiosname"][0]
                        Write-Log "[Connect-LDAP] Domain NetBIOS name (from crossRef): $DomainNetBIOS"
                    }
                }
            } catch {
                Write-Log "[Connect-LDAP] Could not resolve NetBIOS name from crossRef: $_"
            }
            if (-not $DomainNetBIOS) {
                # Fallback only: first DNS label, upper-cased. Logged so the guess is traceable.
                $DomainNetBIOS = ($Domain -split '\.')[0].ToUpper()
                Write-Log "[Connect-LDAP] NetBIOS name not resolved via crossRef - falling back to DNS label guess: $DomainNetBIOS" -Level Warning
            }
            $DomainInfo['DomainNetBIOS'] = $DomainNetBIOS

            # ===== Phase 7c: Store Anonymous Access Results =====
            # Note: Display of anonymous access findings is handled by Get-DomainInformation
            $DomainInfo['AnonymousAccessEnabled'] = $Script:AnonymousAccessEnabled
            $DomainInfo['AnonymousAccessDetails'] = $Script:AnonymousAccessDetails

            # ===== Phase 8: User Context Verification via LDAP =====
            Write-Log "[Connect-LDAP] Verifying authenticated user context via LDAP..."

            $AuthenticatedUser = $null
            $AuthenticatedUserDN = $null
            $AuthenticatedUserSAM = $null

            try {
                if ($Credential) {
                    # Explicit credentials - use the provided username
                    $AuthenticatedUser = $Credential.UserName
                    Write-Log "[Connect-LDAP] Using explicit credential: $AuthenticatedUser"

                    # Extract sAMAccountName from credential for LDAP lookup
                    $CredentialSAM = $Credential.UserName
                    if ($CredentialSAM -match '\\') {
                        $CredentialSAM = $CredentialSAM.Split('\')[1]
                    } elseif ($CredentialSAM -match '@') {
                        $CredentialSAM = $CredentialSAM.Split('@')[0]
                    }

                    # Query LDAP to get full user DN and verify the user exists
                    # UNIFIED: Always use LdapConnection (works for both LDAP and LDAPS)
                    try {
                        $UserRequest = New-Object System.DirectoryServices.Protocols.SearchRequest(
                            $DomainDN,
                            "(sAMAccountName=$CredentialSAM)",
                            [System.DirectoryServices.Protocols.SearchScope]::Subtree,
                            @("distinguishedName", "sAMAccountName", "userPrincipalName")
                        )
                        $UserResponse = $Script:LdapConnection.SendRequest($UserRequest)

                        if ($UserResponse -and $UserResponse.Entries.Count -gt 0) {
                            $UserEntry = $UserResponse.Entries[0]
                            $AuthenticatedUserDN = $UserEntry.DistinguishedName
                            if ($UserEntry.Attributes["samaccountname"]) {
                                $AuthenticatedUserSAM = $UserEntry.Attributes["samaccountname"][0]
                            }
                            Write-Log "[Connect-LDAP] Verified user: $AuthenticatedUserDN"
                        }
                    } catch {
                        Write-Log "[Connect-LDAP] Could not verify user via LDAP: $_"
                    }
                } else {
                    # Windows Authentication (SSPI) - use LDAP "Who Am I?" Extended Operation
                    # This is the authoritative way to determine the authenticated identity
                    # UNIFIED: Always use existing LdapConnection (works for both LDAP and LDAPS)
                    Write-Log "[Connect-LDAP] Using LDAP Who Am I? Extended Operation..."

                    try {
                        # Send Who Am I? Extended Operation (OID 1.3.6.1.4.1.4203.1.11.3)
                        $WhoAmIRequest = New-Object System.DirectoryServices.Protocols.ExtendedRequest("1.3.6.1.4.1.4203.1.11.3")
                        $WhoAmIResponse = $Script:LdapConnection.SendRequest($WhoAmIRequest)

                        if ($WhoAmIResponse -and $WhoAmIResponse.ResponseValue) {
                            # Response format: "u:DOMAIN\username" or "dn:CN=User,OU=Users,DC=domain,DC=com"
                            $WhoAmIResult = [System.Text.Encoding]::UTF8.GetString($WhoAmIResponse.ResponseValue)
                            Write-Log "[Connect-LDAP] LDAP Who Am I? response: $WhoAmIResult"

                            if ($WhoAmIResult -match '^u:(.+)$') {
                                # Format: u:DOMAIN\username
                                $AuthenticatedUser = $Matches[1]
                            } elseif ($WhoAmIResult -match '^dn:(.+)$') {
                                # Format: dn:CN=User,OU=Users,DC=domain,DC=com
                                $AuthenticatedUserDN = $Matches[1]
                                # Extract CN from DN for display
                                if ($AuthenticatedUserDN -match '^CN=([^,]+)') {
                                    $AuthenticatedUser = $Matches[1]
                                } else {
                                    $AuthenticatedUser = $AuthenticatedUserDN
                                }
                            } else {
                                $AuthenticatedUser = $WhoAmIResult
                            }

                            Write-Log "[Connect-LDAP] Authenticated user from LDAP: $AuthenticatedUser"
                        }

                    } catch {
                        Write-Log "[Connect-LDAP] LDAP Who Am I? failed: $_ - falling back to LSA ticket cache"

                        # Fallback: Query Kerberos ticket cache via native LSA API.
                        # Reuse the NetBIOS name resolved via crossRef in Phase 7b2; only guess from
                        # the DNS label if that lookup failed (it is guaranteed set, but guard anyway).
                        if (-not $DomainNetBIOS) { $DomainNetBIOS = $Domain.Split('.')[0].ToUpper() }
                        try {
                            $TGTStatus = Test-KerberosTGTExists -Detailed -Force
                            if ($TGTStatus.Valid -and $TGTStatus.ClientName) {
                                $AuthenticatedUser = "$DomainNetBIOS\$($TGTStatus.ClientName)"
                                Write-Log "[Connect-LDAP] Found user via LSA ticket cache: $AuthenticatedUser"
                            } else {
                                $AuthenticatedUser = "$DomainNetBIOS\[Kerberos Authenticated]"
                                Write-Log "[Connect-LDAP] Kerberos authenticated but no valid TGT in cache"
                            }
                        } catch {
                            Write-Log "[Connect-LDAP] LSA ticket cache query failed: $_"
                            $AuthenticatedUser = "$DomainNetBIOS\[Kerberos Authenticated]"
                        }
                    }
                }

                # If we still don't have a user, mark as unknown
                if ([string]::IsNullOrEmpty($AuthenticatedUser)) {
                    $AuthenticatedUser = "[LDAP Identity Unknown]"
                }

                Write-Log "[Connect-LDAP] Final Authenticated User: $AuthenticatedUser"
                $DomainInfo['AuthenticatedUser'] = $AuthenticatedUser
                $DomainInfo['AuthenticatedUserDN'] = $AuthenticatedUserDN
                $DomainInfo['AuthenticatedUserSAM'] = $AuthenticatedUserSAM

                # Detect if Kerberos was used for authentication
                if ($AuthenticatedUser -notmatch '^\[' -and -not $Credential) {
                    $DomainInfo['DetectedKerberos'] = $true
                    Write-Log "[Connect-LDAP] Kerberos authentication detected (Who Am I? returned domain user)"
                } else {
                    $DomainInfo['DetectedKerberos'] = $false
                }

            } catch {
                Write-Log "[Connect-LDAP] User verification failed (non-critical): $_"
                $DomainInfo['AuthenticatedUser'] = "[Error determining identity]"
            }

            # ===== Phase 9: Store Connection Globally =====
            # Note: $Script:LdapConnection is already set in Phase 5

            # Preserve existing LDAPContext values (like DnsServer, DnsCache) that were set by Connect-adPEAS before calling Connect-LDAP
            if ($Script:LDAPContext) {
                # Merge: DomainInfo overwrites existing keys, but preserve keys not in DomainInfo
                foreach ($key in $DomainInfo.Keys) {
                    $Script:LDAPContext[$key] = $DomainInfo[$key]
                }
            }
            else {
                $Script:LDAPContext = $DomainInfo
            }

            $Script:LDAPCredential = $Credential
            $Script:ConnectionState = "Success"

            # Set AuthMethod if not already set by Connect-adPEAS
            # This handles direct calls to Connect-LDAP (via Ensure-LDAPConnection)
            if (-not $Script:LDAPContext['AuthMethod']) {
                if ($ClientCertificate) {
                    $Script:LDAPContext['AuthMethod'] = 'Schannel'
                }
                elseif ($Credential) {
                    $Script:LDAPContext['AuthMethod'] = 'SimpleBind'
                } else {
                    $Script:LDAPContext['AuthMethod'] = 'WindowsAuth'
                }
                Write-Log "[Connect-LDAP] Set AuthMethod: $($Script:LDAPContext['AuthMethod'])"
            }

            Write-Log "[Connect-LDAP] Connection established successfully"
            Write-Log "[Connect-LDAP] Domain: $Domain, Server: $ActualDCName, Protocol: $ProtocolDisplay"

            return $DomainInfo

        } catch {
            # Final catch for any unhandled errors - only show if not already handled
            if (-not $Script:ConnectionState) {
                Resolve-LDAPConnectionError -ErrorRecord $_ -Context "Unhandled error"
            }
            return $null
        }
    }

    end {
        if ($Script:LdapConnection) {
            Write-Log "[Connect-LDAP] LDAP connection setup completed"
        }
    }
}



# ----- Connect-adPEAS.ps1 -----

function Connect-adPEAS {
<#
.SYNOPSIS
    Central authentication function for adPEAS v2.

.DESCRIPTION
    Unified entry point for all authentication methods in adPEAS v2.
    Supports various authentication mechanisms:
    - Windows Authentication (Current User Context)
    - PSCredential Object (classic)
    - Username/Password (Convenience)
    - PKINIT Certificate-based (Kerberos)
    - Pass-the-Cert / Schannel (LDAPS with client certificate, no Kerberos)
    - NT-Hash (Overpass-the-Hash)
    - AES256 Key (Pass-the-Key)
    - AES128 Key (Pass-the-Key)
    - Kirbi Ticket File (.kirbi)
    - Ccache Ticket File (.ccache)

    KERBEROS BY DEFAULT:
    All authentication methods attempt Kerberos first (TGT ? TGS ? PTT), with automatic fallback to SimpleBind/NTLM if Kerberos fails.
    Use -ForceSimpleBind to skip Kerberos entirely.
    Use -ForceKerberos to fail if Kerberos is unavailable.

    This function:
    - Automatically selects the correct auth method based on parameters
    - Attempts Kerberos authentication first (imports ticket into session)
    - Falls back to SimpleBind/NTLM if Kerberos fails
    - Establishes LDAP/LDAPS connection
    - Validates the connection with a test query
    - Displays login status and session information

    IMPORTANT: Domain parameter is ALWAYS required (explicit intention)!

.PARAMETER Domain
    The target domain (FQDN).
    MANDATORY - Explicit specification required for security tool.

.PARAMETER Server
    Specific Domain Controller (FQDN or IP).
    Optional - Default: Automatic via Domain

.PARAMETER UseWindowsAuth
    Uses Windows Authentication (current user context).
    Parameter-Set: WindowsAuth

.PARAMETER Credential
    PSCredential object for alternative authentication.
    Parameter-Set: PSCredential

.PARAMETER Username
    Username for authentication.
    Format: "domain\username" or "username@domain.com"
    Parameter-Set: UsernamePassword

.PARAMETER Password
    Password for authentication (SecureString or plain text).
    Parameter-Set: UsernamePassword
    Optional - Allows empty passwords for accounts with PASSWD_NOTREQD flag (userAccountControl 0x0020)

.PARAMETER Certificate
    Path to PKCS#12 certificate (.pfx/.p12) OR Base64-encoded PFX data for PKINIT authentication.
    The function auto-detects whether the input is Base64 or a file path.
    Parameter-Set: Certificate

.PARAMETER CertificatePassword
    Password for the certificate (SecureString or plain text).
    Parameter-Set: Certificate
    Optional - Default: empty string (for unprotected PFX files)

.PARAMETER ForcePassTheCert
    Use Schannel (TLS client certificate) authentication instead of PKINIT (Kerberos).
    The certificate is presented directly in the TLS handshake to LDAPS (port 636).
    Parameter-Set: Certificate

    Advantages over PKINIT:
    - Works when port 88 (Kerberos) is blocked (SOCKS proxy, SSH tunnel, firewall)
    - No PTT injection needed (no LSA API call, no admin rights)
    - Works with certificates without Smart Card Logon EKU (e.g., from ESC8 relay)
    - Immune to LDAP Channel Binding and Signing requirements (TLS provides both)

    LDAPS is automatically enabled when -ForcePassTheCert is used.

.PARAMETER NTHash
    NT-Hash (NTLM hash) for Overpass-the-Hash authentication.
    Format: 32 hex characters (e.g., "32ED87BDB5FDC5E9CBA88547376818D4")
    Parameter-Set: NTHash
    Requires: -Username

    Primary: Kerberos TGT + TGS for LDAP + Pass-the-Ticket
    No fallback: requires Kerberos (port 88 must be reachable)

.PARAMETER AES256Key
    AES256 key for Pass-the-Key authentication.
    Format: 64 hex characters
    Parameter-Set: AES256
    Requires: -Username

    Primary: Kerberos TGT + TGS for LDAP + Pass-the-Ticket
    No fallback: requires Kerberos (port 88 must be reachable)

.PARAMETER AES128Key
    AES128 key for Pass-the-Key authentication.
    Format: 32 hex characters
    Parameter-Set: AES128
    Requires: -Username

    Primary: Kerberos TGT + TGS for LDAP + Pass-the-Ticket
    No fallback: requires Kerberos (port 88 must be reachable)

.PARAMETER Kirbi
    Path to a .kirbi file OR Base64-encoded kirbi data containing a Kerberos ticket (TGT or TGS).
    The function auto-detects whether the input is Base64 or a file path.
    Parameter-Set: Kirbi

    Uses Pass-the-Ticket to import the ticket into the Windows session.
    This is for tickets exported by tools like Rubeus, Mimikatz, or adPEAS.
    No fallback available - requires valid ticket data.

.PARAMETER Ccache
    Path to a .ccache file OR Base64-encoded ccache data containing a Kerberos ticket.
    The function auto-detects whether the input is Base64 or a file path.
    Parameter-Set: Ccache

    Uses Pass-the-Ticket to import the ticket into the Windows session.
    This is for tickets from Linux systems (MIT Kerberos format).
    No fallback available - requires valid ticket data.

.PARAMETER ForceNTLM
    Force NTLM impersonation, skipping Kerberos entirely.
    Only available for Username/Password and PSCredential authentication.

    This method uses LogonUser() with LOGON32_LOGON_NEW_CREDENTIALS (similar to "runas /netonly"):
    - Does NOT modify the Kerberos ticket cache
    - Original Kerberos tickets remain intact
    - Network operations use NTLM Challenge/Response authentication
    - Supports LDAP Signing (unlike SimpleBind)
    - Works even when LDAP Signing is enforced on the DC

    Advantages over SimpleBind:
    - Credentials never sent in clear text
    - LDAP Signing is supported
    - No LDAPS required for security

    Disadvantages:
    - Only works with Username/Password (not Hash/Key/Cert)
    - NTLM may be disabled in hardened environments

.PARAMETER ForceSimpleBind
    Force SimpleBind authentication, skipping Kerberos entirely.
    Applies to ALL authentication methods (Password, PSCredential, WindowsAuth, Hash/Key).
    Useful when Kerberos is known to be unavailable or port 88 is blocked.

.PARAMETER ForceKerberos
    Force Kerberos authentication without fallback.
    If Kerberos fails, the connection fails completely (no SimpleBind/NTLM fallback).
    Applies to ALL authentication methods.
    Use this when you require Kerberos specifically (e.g., for security reasons).

.PARAMETER BuildCompletionCache
    Build tab-completion cache for Get-Domain* functions.
    Queries AD for all Users, Computers, Groups, and GPOs and caches their names.
    Enables tab-completion for -Identity parameter in Get-DomainUser, Get-DomainComputer, Get-DomainGroup, and Get-DomainGPO functions.

    Note: Initial cache build may take a few seconds depending on domain size.
    Cache is stored in memory and cleared when PowerShell session ends.

    Example usage after connection:
    - Get-DomainUser -Identity adm[TAB] -> Get-DomainUser -Identity "administrator"
    - Get-DomainGPO -Identity Def[TAB] -> Get-DomainGPO -Identity "Default Domain Policy"

.PARAMETER UseLDAPS
    Forces LDAPS (no fallback to LDAP).

.PARAMETER IgnoreSSLErrors
    Ignores SSL certificate errors for LDAPS connections (self-signed certs, expired certs, hostname mismatches, untrusted CAs, etc.).
    Default: $true (for maximum compatibility in pentesting environments)
    Can be explicitly disabled with -IgnoreSSLErrors:$false

    Uses LdapConnection.SessionOptions.VerifyServerCertificate callback to bypass all certificate validation when enabled.
    This covers all SSL/TLS error types including name mismatches (e.g., connecting via IP when cert has FQDN).

.PARAMETER DnsServer
    Custom DNS server to use for resolving AD hostnames.
    Essential for non-domain-joined systems or VPN scenarios where system DNS cannot resolve the target AD domain.

    When specified:
    - DC hostname resolution uses this DNS server
    - Resolved IPs are cached for SMB operations
    - System DNS is used as fallback if custom DNS fails

    Example: -DnsServer "10.10.10.1"

.PARAMETER PatchHostsFile
    Automatically add resolved hostnames to Windows hosts file.
    Requires Administrator privileges.

    This enables full system-wide DNS resolution for AD hostnames, including Kerberos SPN resolution and SMB share access.

    Entries are automatically cleaned up by Disconnect-adPEAS.
    WARNING: Modifies system hosts file. Use with caution in production environments.

.PARAMETER TimeoutSeconds
    Timeout in seconds for LDAP operations.
    Default: 30 seconds
    Valid range: 5-600 seconds. Increase for high-latency connections (SOCKS tunnels, VPN).
    Example: -TimeoutSeconds 120

    Lower values = faster failure detection (useful for fast networks)
    Higher values = more tolerance for slow/high-latency networks

    Example: -TimeoutSeconds 10 (for fast local networks)
    Example: -TimeoutSeconds 60 (for slow VPN connections)

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Connects with Windows Authentication (current user).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Credential (Get-Credential)
    Connects with PSCredential object.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Username "admin" -Password "P@ssw0rd!"
    Connects with Username/Password.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Certificate "user.pfx" -CertificatePassword "pass"
    Connects with PKINIT certificate from file (protected PFX).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Certificate "user.pfx"
    Connects with PKINIT certificate from file (unprotected PFX without password).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Certificate "MIIKwgYJKoZI..." -CertificatePassword "pass"
    Connects with PKINIT certificate from Base64-encoded PFX data.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Certificate "user.pfx" -ForcePassTheCert
    Connects with Pass-the-Cert (Schannel) - direct LDAPS bind with client certificate, no Kerberos.
    Works when port 88 is blocked or certificate lacks Smart Card Logon EKU.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Server "dc01.contoso.com" -Credential $cred
    Connects with specific DC.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth -IgnoreSSLErrors:$false
    Connects with Windows Auth and enforces SSL certificate validation.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Username "admin" -NTHash "32ED87BDB5FDC5E9CBA88547376818D4"
    Connects using Overpass-the-Hash (Kerberos TGT + LDAP TGS + PTT).
    No fallback - requires Kerberos (port 88 must be reachable).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Username "admin" -AES256Key "4a3b2c1d5e6f..."
    Connects using Pass-the-Key with AES256.
    No fallback - requires Kerberos (port 88 must be reachable).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Username "admin" -NTHash "..." -ForceSimpleBind
    Skips Kerberos and connects directly via SimpleBind with the hash.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Username "admin" -NTHash "..." -ForceKerberos
    Requires Kerberos authentication - fails if Kerberos is unavailable.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Username "admin" -Password "P@ssw0rd" -ForceNTLM
    Connects using NTLM impersonation (runas /netonly style).
    Does NOT modify Kerberos ticket cache - original tickets remain intact.
    Supports LDAP Signing and works without LDAPS.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Credential (Get-Credential) -ForceNTLM
    Connects using NTLM impersonation with PSCredential object.

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Kirbi "ticket.kirbi"
    Connects using a .kirbi ticket file (Pass-the-Ticket).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Kirbi "YIIKwgYJKoZIhvc..."
    Connects using a Base64-encoded kirbi ticket (Pass-the-Ticket).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Ccache "/tmp/krb5cc_1000"
    Connects using a .ccache ticket file from Linux (Pass-the-Ticket).

.EXAMPLE
    Connect-adPEAS -Domain "contoso.com" -Credential (Get-Credential) -BuildCompletionCache
    Connects and builds tab-completion cache for Get-Domain* functions.
    After connection, use TAB to autocomplete Identity parameters.

.OUTPUTS
    Hashtable with connection details or $null on error

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(DefaultParameterSetName='WindowsAuth')]
    param(
        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [Parameter(Mandatory=$true, ParameterSetName='PSCredential')]
        [Parameter(Mandatory=$true, ParameterSetName='UsernamePassword')]
        [Parameter(Mandatory=$true, ParameterSetName='Certificate')]
        [Parameter(Mandatory=$true, ParameterSetName='NTHash')]
        [Parameter(Mandatory=$true, ParameterSetName='AES256')]
        [Parameter(Mandatory=$true, ParameterSetName='AES128')]
        [Parameter(Mandatory=$true, ParameterSetName='Kirbi')]
        [Parameter(Mandatory=$true, ParameterSetName='Ccache')]
        [AllowEmptyString()]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [switch]$UseLDAPS,

        [Parameter(Mandatory=$false)]
        [bool]$IgnoreSSLErrors = $true,

        [Parameter(Mandatory=$false)]
        [string]$DnsServer,

        [Parameter(Mandatory=$false)]
        [switch]$PatchHostsFile,

        [Parameter(Mandatory=$false)]
        [switch]$Quiet,

        # Windows Authentication Parameter-Set (Default)
        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [switch]$UseWindowsAuth,

        # PSCredential Parameter-Set
        [Parameter(Mandatory=$true, ParameterSetName='PSCredential')]
        [System.Management.Automation.PSCredential]$Credential,

        # Username/Password Parameter-Set
        # For Certificate: optional override to select identity when cert has multiple SANs
        [Parameter(Mandatory=$true, ParameterSetName='UsernamePassword')]
        [Parameter(Mandatory=$true, ParameterSetName='NTHash')]
        [Parameter(Mandatory=$true, ParameterSetName='AES256')]
        [Parameter(Mandatory=$true, ParameterSetName='AES128')]
        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [Parameter(Mandatory=$false, ParameterSetName='Kirbi')]
        [Parameter(Mandatory=$false, ParameterSetName='Ccache')]
        [AllowEmptyString()]
        [string]$Username,

        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        $Password,  # Accepts SecureString or String (allows empty passwords for PASSWD_NOTREQD accounts)

        # Certificate Parameter-Set (PKINIT)
        [Parameter(Mandatory=$true, ParameterSetName='Certificate')]
        [AllowEmptyString()]
        [string]$Certificate,

        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        $CertificatePassword = "",  # Accepts SecureString or String. Default: empty (for unprotected PFX)

        # Pass-the-Cert: Use Schannel (TLS client certificate) instead of PKINIT (Kerberos)
        # Bypasses Kerberos entirely - works when port 88 is blocked, no Smart Card Logon EKU needed
        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [switch]$ForcePassTheCert,

        # NTHash Parameter-Set (Overpass-the-Hash)
        [Parameter(Mandatory=$true, ParameterSetName='NTHash')]
        [AllowEmptyString()]
        [string]$NTHash,

        # AES256 Parameter-Set (Pass-the-Key)
        [Parameter(Mandatory=$true, ParameterSetName='AES256')]
        [AllowEmptyString()]
        [string]$AES256Key,

        # AES128 Parameter-Set (Pass-the-Key)
        [Parameter(Mandatory=$true, ParameterSetName='AES128')]
        [AllowEmptyString()]
        [string]$AES128Key,

        # Kirbi Parameter-Set (Ticket File)
        [Parameter(Mandatory=$true, ParameterSetName='Kirbi')]
        [AllowEmptyString()]
        [string]$Kirbi,

        # Ccache Parameter-Set (Ticket File)
        [Parameter(Mandatory=$true, ParameterSetName='Ccache')]
        [AllowEmptyString()]
        [string]$Ccache,

        # Force NTLM Impersonation (only for Username/Password and PSCredential)
        [Parameter(Mandatory=$false, ParameterSetName='PSCredential')]
        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [switch]$ForceNTLM,

        # Force SimpleBind (applies to ALL parameter sets)
        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [Parameter(Mandatory=$false, ParameterSetName='PSCredential')]
        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [Parameter(Mandatory=$false, ParameterSetName='NTHash')]
        [Parameter(Mandatory=$false, ParameterSetName='AES256')]
        [Parameter(Mandatory=$false, ParameterSetName='AES128')]
        [Parameter(Mandatory=$false, ParameterSetName='Kirbi')]
        [Parameter(Mandatory=$false, ParameterSetName='Ccache')]
        [switch]$ForceSimpleBind,

        # Force Kerberos (no fallback, applies to ALL parameter sets)
        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [Parameter(Mandatory=$false, ParameterSetName='PSCredential')]
        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [Parameter(Mandatory=$false, ParameterSetName='NTHash')]
        [Parameter(Mandatory=$false, ParameterSetName='AES256')]
        [Parameter(Mandatory=$false, ParameterSetName='AES128')]
        [Parameter(Mandatory=$false, ParameterSetName='Kirbi')]
        [Parameter(Mandatory=$false, ParameterSetName='Ccache')]
        [switch]$ForceKerberos,

        # License file path (applies to ALL parameter sets)
        # Loads license JSON and stores it for disclaimer display by Invoke-adPEAS
        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [Parameter(Mandatory=$false, ParameterSetName='PSCredential')]
        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [Parameter(Mandatory=$false, ParameterSetName='NTHash')]
        [Parameter(Mandatory=$false, ParameterSetName='AES256')]
        [Parameter(Mandatory=$false, ParameterSetName='AES128')]
        [Parameter(Mandatory=$false, ParameterSetName='Kirbi')]
        [Parameter(Mandatory=$false, ParameterSetName='Ccache')]
        [string]$License,

        # Tab-Completion Cache (applies to ALL parameter sets)
        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [Parameter(Mandatory=$false, ParameterSetName='PSCredential')]
        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [Parameter(Mandatory=$false, ParameterSetName='NTHash')]
        [Parameter(Mandatory=$false, ParameterSetName='AES256')]
        [Parameter(Mandatory=$false, ParameterSetName='AES128')]
        [Parameter(Mandatory=$false, ParameterSetName='Kirbi')]
        [Parameter(Mandatory=$false, ParameterSetName='Ccache')]
        [switch]$BuildCompletionCache,

        # LDAP Operation Timeout (applies to ALL parameter sets)
        [Parameter(Mandatory=$false)]
        [ValidateRange(5, 600)]
        [int]$TimeoutSeconds = 30
    )

    begin {
        Write-Log "[Connect-adPEAS] Starting authentication process..."

        # ===== License Loading =====
        # Store license JSON for later use by Invoke-adPEAS disclaimer display
        if ($PSBoundParameters.ContainsKey('License') -and $License) {
            if (Test-Path $License -ErrorAction SilentlyContinue) {
                $Script:RuntimeLicense = Get-Content $License -Raw -Encoding UTF8
                Write-Log "[Connect-adPEAS] Loaded runtime license from: $License"
            }
            else {
                Write-Warning "[Connect-adPEAS] License file not found: $License"
            }
        }

        # ===== Automatic Session Cleanup =====
        # Clean up any existing session BEFORE establishing a new one.
        # This is critical for NTLM impersonation which creates a security context that persists until explicitly reverted.
        # Without cleanup, subsequent Connect-adPEAS calls would still run in the old impersonated context.
        $existingSession = $Script:LDAPContext -or $Script:LdapConnection -or
                          ($Script:NTLMTokenHandle -and $Script:NTLMTokenHandle -ne [IntPtr]::Zero)

        if ($existingSession) {
            Write-Log "[Connect-adPEAS] Existing session detected - performing automatic cleanup..."

            # Step 1: Revert NTLM impersonation (MUST be done first!)
            if ($Script:NTLMTokenHandle -and $Script:NTLMTokenHandle -ne [IntPtr]::Zero) {
                Write-Log "[Connect-adPEAS] Reverting existing NTLM impersonation..."
                try {
                    Invoke-RevertToSelf -TokenHandle $Script:NTLMTokenHandle
                    Write-Log "[Connect-adPEAS] NTLM impersonation reverted successfully"
                }
                catch {
                    Write-Log "[Connect-adPEAS] Warning: Failed to revert NTLM impersonation: $_"
                }
                $Script:NTLMTokenHandle = [IntPtr]::Zero
            }

            # Step 2: Dispose LDAP connection
            if ($Script:LdapConnection) {
                try {
                    $Script:LdapConnection.Dispose()
                    Write-Log "[Connect-adPEAS] Previous LdapConnection disposed"
                }
                catch {
                    # Ignore disposal errors (may already be disposed)
                    Write-Log "[Connect-adPEAS] Note: LdapConnection disposal: $_"
                }
            }

            # Step 3: Clean up hosts file entries (if any)
            if ($Script:LDAPContext -and $Script:LDAPContext['HostsEntries'] -and $Script:LDAPContext['HostsEntries'].Count -gt 0) {
                try {
                    $hostsResult = Remove-adPEASHostsEntry
                    if ($hostsResult.Success -and $hostsResult.RemovedCount -gt 0) {
                        Write-Log "[Connect-adPEAS] Cleaned up $($hostsResult.RemovedCount) hosts file entries from previous session"
                    }
                }
                catch {
                    Write-Log "[Connect-adPEAS] Warning: Hosts file cleanup failed: $_"
                }
            }

            # Step 4: Clear ALL session variables and caches via central function.
            # This ensures every cache (GPOs, SIDs, groups, ACLs, collector, etc.)
            # is reset before the new session starts.
            Clear-SessionState

            Write-Log "[Connect-adPEAS] Previous session cleanup completed"
        }

        # Create readable parameter set name for verbose output
        $ParamSetDisplay = switch ($PSCmdlet.ParameterSetName) {
            'PSCredential' { 'PSCredential Object' }
            'UsernamePassword' { 'Username/Password' }
            'Certificate' { 'Certificate (PKINIT)' }
            'WindowsAuth' { 'Windows Authentication' }
            'NTHash' { 'NT-Hash (Overpass-the-Hash)' }
            'AES256' { 'AES256 Key (Pass-the-Key)' }
            'AES128' { 'AES128 Key (Pass-the-Key)' }
            'Kirbi' { 'Kirbi Ticket File (Pass-the-Ticket)' }
            'Ccache' { 'Ccache Ticket File (Pass-the-Ticket)' }
            default { $PSCmdlet.ParameterSetName }
        }
        Write-Log "[Connect-adPEAS] Parameter Set: $ParamSetDisplay"
    }

    process {
        try {
            # ===== ISE Compatibility Warning =====
            if ($Host.Name -eq 'Windows PowerShell ISE Host') {
                Write-Warning "PowerShell ISE is deprecated and not supported by adPEAS. Console output may be garbled. Use powershell.exe or VS Code instead."
            }

            # ===== Determine Authentication Method =====
            $AuthMethod = $PSCmdlet.ParameterSetName

            # ===== Validate Mutually Exclusive Parameters =====
            if ($ForceNTLM -and $ForceKerberos) {
                Show-ConnectionError -ErrorType "GenericError" -Details "-ForceNTLM and -ForceKerberos are mutually exclusive" -NoThrow
                return $null
            }
            if ($ForceSimpleBind -and $ForceKerberos) {
                Show-ConnectionError -ErrorType "GenericError" -Details "-ForceSimpleBind and -ForceKerberos are mutually exclusive" -NoThrow
                return $null
            }
            if ($ForceNTLM -and $ForceSimpleBind) {
                Show-ConnectionError -ErrorType "GenericError" -Details "-ForceNTLM and -ForceSimpleBind are mutually exclusive" -NoThrow
                return $null
            }

            # ===== Validate Required String Parameters =====
            # [AllowEmptyString()] lets PowerShell accept "" without ugly ParameterBindingValidation errors.
            # We catch empty values here with clean Show-ConnectionError messages instead.
            if ($PSBoundParameters.ContainsKey('Domain') -and [string]::IsNullOrWhiteSpace($Domain)) {
                Show-ConnectionError -ErrorType "GenericError" -Details "Domain name must not be empty" -NoThrow
                return $null
            }
            if ($AuthMethod -in @('UsernamePassword','NTHash','AES256','AES128') -and [string]::IsNullOrWhiteSpace($Username)) {
                Show-ConnectionError -ErrorType "GenericError" -Details "Username must not be empty" -NoThrow
                return $null
            }
            if ($AuthMethod -eq 'Certificate' -and [string]::IsNullOrWhiteSpace($Certificate)) {
                Show-ConnectionError -ErrorType "GenericError" -Details "Certificate path or Base64 string must not be empty" -NoThrow
                return $null
            }
            if ($AuthMethod -eq 'Kirbi' -and [string]::IsNullOrWhiteSpace($Kirbi)) {
                Show-ConnectionError -ErrorType "GenericError" -Details "Kirbi ticket file path or Base64 string must not be empty" -NoThrow
                return $null
            }
            if ($AuthMethod -eq 'Ccache' -and [string]::IsNullOrWhiteSpace($Ccache)) {
                Show-ConnectionError -ErrorType "GenericError" -Details "Ccache ticket file path must not be empty" -NoThrow
                return $null
            }

            # ===== Validate Hash/Key Input =====
            if ($AuthMethod -eq 'NTHash') {
                if ($NTHash -notmatch '^[0-9a-fA-F]{32}$') {
                    $Detail = if ($NTHash.Length -ne 32) { "Expected 32 hex chars, got $($NTHash.Length)" } else { "Contains non-hex characters" }
                    Show-ConnectionError -ErrorType "GenericError" -Details "Invalid NT-Hash format: $Detail" -NoThrow
                    return $null
                }
            }
            elseif ($AuthMethod -eq 'AES256') {
                if ($AES256Key -notmatch '^[0-9a-fA-F]{64}$') {
                    $Detail = if ($AES256Key.Length -ne 64) { "Expected 64 hex chars, got $($AES256Key.Length)" } else { "Contains non-hex characters" }
                    Show-ConnectionError -ErrorType "GenericError" -Details "Invalid AES256 key format: $Detail" -NoThrow
                    return $null
                }
            }
            elseif ($AuthMethod -eq 'AES128') {
                if ($AES128Key -notmatch '^[0-9a-fA-F]{32}$') {
                    $Detail = if ($AES128Key.Length -ne 32) { "Expected 32 hex chars, got $($AES128Key.Length)" } else { "Contains non-hex characters" }
                    Show-ConnectionError -ErrorType "GenericError" -Details "Invalid AES128 key format: $Detail" -NoThrow
                    return $null
                }
            }

            # ===== Initialize Auth Info Tracking =====
            # These will be populated based on actual auth method used
            $Script:AuthInfo = @{
                Method = $null              # 'Kerberos' or 'SimpleBind' or 'WindowsSSPI' or 'NTLM Impersonation'
                ParameterSet = $AuthMethod  # Original parameter set name
                KerberosUsed = $false       # Was Kerberos actually used?
                TGTInfo = $null             # TGT details if Kerberos was used
                NTLMImpersonation = $ForceNTLM.IsPresent  # Track if NTLM impersonation was requested
            }

            # ===== Initialize LDAPContext Early =====
            # Must be done BEFORE any Resolve-adPEASName calls so that UseLDAPS is available
            if (-not $Script:LDAPContext) {
                $Script:LDAPContext = @{}
            }

            # Store UseLDAPS for use by Resolve-adPEASName (DC reachability checks)
            if ($UseLDAPS) {
                $Script:LDAPContext['UseLDAPS'] = $true
                Write-Log "[Connect-adPEAS] LDAPS mode enabled - DC reachability will check port 636"
            }

            # ===== Custom DNS Server Handling =====
            if ($DnsServer) {
                Write-Log "[Connect-adPEAS] Custom DNS server specified: $DnsServer"

                # Store DNS server for use by other functions
                $Script:LDAPContext['DnsServer'] = $DnsServer
                # Use case-insensitive dictionary for DNS cache (hostnames are case-insensitive)
                $Script:LDAPContext['DnsCache'] = [System.Collections.Generic.Dictionary[string,string]]::new([System.StringComparer]::OrdinalIgnoreCase)

                # Validate DNS server can resolve the target domain
                try {
                    $null = Resolve-DnsName -Name $Domain -Server $DnsServer -Type A -DnsOnly -ErrorAction Stop
                    Write-Log "[Connect-adPEAS] Custom DNS server can resolve $Domain"
                }
                catch {
                    Write-Warning "[Connect-adPEAS] DNS server $DnsServer not reachable or cannot resolve '$Domain'"
                }

                # If PatchHostsFile is requested, verify admin privileges
                if ($PatchHostsFile) {
                    $isAdmin = Test-adPEASAdminPrivileges
                    if (-not $isAdmin) {
                        Write-Warning "[Connect-adPEAS] -PatchHostsFile requires Administrator privileges!"
                        Write-Warning "[Connect-adPEAS] Hosts file patching will be skipped. Run as Administrator for full functionality."
                        $PatchHostsFile = $false
                    }
                    else {
                        Write-Log "[Connect-adPEAS] Administrator privileges confirmed for hosts file patching"
                        $Script:LDAPContext['PatchHostsFile'] = $true

                        # ===== EARLY Hosts File Patching =====
                        # Kerberos PTT requires Windows to resolve the DC hostname for SPN matching.
                        # Without hosts file entries, the LDAP connect after PTT fails with "Invalid credentials" because Windows cannot resolve the DC hostname via system DNS.
                        Write-Log "[Connect-adPEAS] Early hosts file patching for Kerberos authentication..."

                        # First, resolve the server/domain to get IP
                        $earlyResolveTarget = if ($Server) { $Server } else { $Domain }
                        $resolvedIP = Resolve-adPEASName -Name $earlyResolveTarget -DnsServer $DnsServer

                        if ($resolvedIP) {
                            $hostsPatched = @()

                            # Patch the server hostname if provided
                            if ($Server) {
                                $patchResult = Add-adPEASHostsEntry -IPAddress $resolvedIP -Hostname $Server -Force
                                if ($patchResult.Success) {
                                    $hostsPatched += $Server
                                    Write-Log "[Connect-adPEAS] Early hosts entry: $resolvedIP -> $Server"
                                }
                                # Brief delay to ensure file handle is fully released before next write
                                Start-Sleep -Milliseconds 50
                            }

                            # Also patch domain name -> DC IP (if different from server)
                            if ($Domain -ne $Server) {
                                $patchResult = Add-adPEASHostsEntry -IPAddress $resolvedIP -Hostname $Domain -Force
                                if ($patchResult.Success) {
                                    $hostsPatched += $Domain
                                    Write-Log "[Connect-adPEAS] Early hosts entry: $resolvedIP -> $Domain"
                                }
                            }

                            # Store for cleanup later
                            $Script:LDAPContext['HostsEntries'] = $hostsPatched
                            $Script:LDAPContext['EarlyHostsPatched'] = $true

                            if ($hostsPatched.Count -gt 0) {
                                Show-Line "Patched hosts file with $($hostsPatched.Count) entries (cleanup on Disconnect-adPEAS)" -Class Info
                            }
                        }
                        else {
                            Write-Warning "[Connect-adPEAS] Could not resolve $earlyResolveTarget via custom DNS - hosts patching skipped"
                        }
                    }
                }
            }

            # ===== Get Domain if not specified (WindowsAuth only) =====
            if ($AuthMethod -eq 'WindowsAuth' -and -not $Domain) {
                try {
                    $Domain = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain().Name
                    Write-Log "[Connect-adPEAS] No domain specified, using current domain: $Domain"
                } catch {
                    Show-ConnectionError -ErrorType "DomainError" -Details "Specify domain with -Domain parameter" -NoThrow
                    return $null
                }
            }

            Write-Log "[Connect-adPEAS] Establishing connection..."

            # Create readable authentication method name for verbose output
            $AuthMethodDisplay = switch ($AuthMethod) {
                'PSCredential' { 'PSCredential Object' }
                'UsernamePassword' { 'Username/Password' }
                'Certificate' { if ($ForcePassTheCert) { 'Certificate (Pass-the-Cert/Schannel)' } else { 'Certificate (PKINIT)' } }
                'WindowsAuth' { 'Windows Authentication' }
                'NTHash' { 'NT-Hash (Overpass-the-Hash)' }
                'AES256' { 'AES256 Key (Pass-the-Key)' }
                'AES128' { 'AES128 Key (Pass-the-Key)' }
                'Kirbi' { 'Kirbi Ticket File (Pass-the-Ticket)' }
                'Ccache' { 'Ccache Ticket File (Pass-the-Ticket)' }
                default { $AuthMethod }
            }
            Write-Log "[Connect-adPEAS] Authentication Method: $AuthMethodDisplay"

            # ===== Parameter-Set Specific Handling =====
            switch ($AuthMethod) {
                { $_ -in @('PSCredential', 'UsernamePassword') } {
                    # ===== Credential Preparation (auth-method-specific) =====
                    # Both cases produce the same three variables:
                    #   $SamAccountName  - for Kerberos auth
                    #   $PlainPassword   - for Kerberos auth
                    #   $CredObject      - PSCredential for NTLM impersonation and SimpleBind

                    if ($AuthMethod -eq 'PSCredential') {
                        Write-Log "[Connect-adPEAS] Domain: $Domain"
                        if ($Server) { Write-Log "[Connect-adPEAS] Server: $Server" }
                        Write-Log "[Connect-adPEAS] Username: $($Credential.UserName)"

                        # Extract password from credential for Kerberos (with proper memory cleanup)
                        $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($Credential.Password)
                        try {
                            $PlainPassword = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
                        }
                        finally {
                            [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
                        }

                        # Extract sAMAccountName and detect cross-domain authentication
                        $CredUsername = $Credential.UserName
                        $SamAccountName = $CredUsername
                        $UserRealm = $null  # null = same as target domain

                        if ($CredUsername -match '^([^\\]+)\\(.+)$') {
                            $UserDomainPrefix = $Matches[1]
                            $SamAccountName = $Matches[2]

                            # Check if user domain differs from target domain
                            $targetPrefix = ($Domain -split '\.')[0]
                            if ($UserDomainPrefix -ine $targetPrefix -and $UserDomainPrefix -ine $Domain) {
                                $UserRealm = $UserDomainPrefix
                                if ($UserRealm -match '\.') {
                                    Write-Log "[Connect-adPEAS] Cross-domain detected: user in '$UserRealm' (FQDN), target '$Domain'"
                                } else {
                                    Write-Log "[Connect-adPEAS] Cross-domain detected: user in '$UserRealm' (NetBIOS), target '$Domain'"
                                }
                            }
                        }
                        elseif ($CredUsername -match '^(.+)@([^@]+)$') {
                            $SamAccountName = $Matches[1]
                            $upnDomain = $Matches[2]
                            if ($upnDomain -ine $Domain) {
                                $UserRealm = $upnDomain
                                Write-Log "[Connect-adPEAS] Cross-domain detected: user UPN realm '$UserRealm', target '$Domain'"
                            }
                        }

                        $CredObject = $Credential
                    }
                    else {
                        # UsernamePassword
                        Write-Log "[Connect-adPEAS] Domain: $Domain"
                        if ($Server) { Write-Log "[Connect-adPEAS] Server: $Server" }
                        Write-Log "[Connect-adPEAS] Username: $Username"

                        # Convert Password to plain string for Kerberos, SecureString for SimpleBind
                        # Handle various input types: String, SecureString, numeric, or $null (empty password)
                        if ($null -eq $Password -or $Password -eq '') {
                            # Empty password (PASSWD_NOTREQD accounts)
                            $PlainPassword = ""
                            # Create empty SecureString manually (ConvertTo-SecureString rejects empty string in some PS versions)
                            $SecurePassword = New-Object System.Security.SecureString
                            Write-Log "[Connect-adPEAS] Empty password provided (PASSWD_NOTREQD account)"
                        }
                        elseif ($Password -is [string]) {
                            $PlainPassword = $Password
                            $SecurePassword = ConvertTo-SecureString -String $Password -AsPlainText -Force
                        }
                        elseif ($Password -is [System.Security.SecureString]) {
                            $SecurePassword = $Password
                            # Extract plain password with proper memory cleanup
                            $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($Password)
                            try {
                                $PlainPassword = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
                            }
                            finally {
                                [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
                            }
                        }
                        elseif ($Password -is [int] -or $Password -is [long] -or $Password -is [double]) {
                            # Numeric password (PowerShell auto-parses "12345" as int) - convert to string
                            $PlainPassword = $Password.ToString()
                            $SecurePassword = ConvertTo-SecureString -String $PlainPassword -AsPlainText -Force
                            Write-Log "[Connect-adPEAS] Password was numeric, converted to string"
                        }
                        else {
                            throw "Password must be either String, SecureString, or empty"
                        }

                        # Normalize Username for credential creation
                        # If no domain prefix/suffix, add NetBIOS domain prefix for SMB compatibility
                        $CredentialUsername = $Username
                        if ($Username -notmatch '\\' -and $Username -notmatch '@') {
                            $NetBIOSDomain = ($Domain -split '\.')[0].ToUpper()
                            $CredentialUsername = "$NetBIOSDomain\$Username"
                            Write-Log "[Connect-adPEAS] Username normalized for SMB: $Username -> $CredentialUsername"
                        }

                        # Create PSCredential for NTLM impersonation and SimpleBind fallback
                        $CredObject = New-Object System.Management.Automation.PSCredential($CredentialUsername, $SecurePassword)

                        # Extract sAMAccountName and detect cross-domain authentication
                        # Cross-domain: user realm differs from target domain (e.g., contoso.com\b.pitt -> dev.contoso.com)
                        $SamAccountName = $Username
                        $UserRealm = $null  # null = same as target domain, set when cross-domain detected

                        if ($Username -match '^([^\\]+)\\(.+)$') {
                            $UserDomainPrefix = $Matches[1]
                            $SamAccountName = $Matches[2]

                            # Check if user domain differs from target domain
                            $targetPrefix = ($Domain -split '\.')[0]
                            if ($UserDomainPrefix -ine $targetPrefix -and $UserDomainPrefix -ine $Domain) {
                                $UserRealm = $UserDomainPrefix
                                if ($UserRealm -match '\.') {
                                    Write-Log "[Connect-adPEAS] Cross-domain detected: user in '$UserRealm' (FQDN), target '$Domain'"
                                } else {
                                    Write-Log "[Connect-adPEAS] Cross-domain detected: user in '$UserRealm' (NetBIOS), target '$Domain'"
                                }
                            }
                        }
                        elseif ($Username -match '^(.+)@([^@]+)$') {
                            $SamAccountName = $Matches[1]
                            $upnDomain = $Matches[2]
                            if ($upnDomain -ine $Domain) {
                                $UserRealm = $upnDomain
                                Write-Log "[Connect-adPEAS] Cross-domain detected: user UPN realm '$UserRealm', target '$Domain'"
                            }
                        }
                    }

                    # ===== Shared Auth Flow: Kerberos -> NTLM Impersonation -> SimpleBind =====

                    # Resolve DC hostname and IP using unified resolver
                    if ($Server) {
                        $ResolvedIP = Resolve-adPEASName -Name $Server
                        $DCResolution = [PSCustomObject]@{ Hostname = $Server; IP = $ResolvedIP }

                        # If explicit -Server was given but DNS fails, terminate immediately
                        # No point trying Kerberos/NTLM/SimpleBind if we can't resolve the server
                        if (-not $ResolvedIP) {
                            Show-ConnectionError -ErrorType "DomainError" -Details "Server '$Server' could not be resolved - check DNS or use an IP address" -NoThrow
                            return $null
                        }
                    } else {
                        $DCResolution = Resolve-adPEASName -Domain $Domain

                        # If domain-based DC discovery fails, terminate immediately
                        if (-not $DCResolution -or -not $DCResolution.Hostname) {
                            Show-ConnectionError -ErrorType "DomainError" -Details "Could not discover a Domain Controller for '$Domain' - DNS resolution failed. Use -Server to specify a DC manually." -NoThrow
                            return $null
                        }
                    }

                    $KerberosAuthSuccess = $false
                    $Connection = $null

                    # ===== Explicit NTLM (if requested) =====
                    if ($ForceNTLM) {
                        Write-Log "[Connect-adPEAS] Using explicit NTLM authentication (AuthType::Ntlm)..."

                        $ConnParams = @{}
                        $ConnParams['Domain'] = $Domain
                        if ($Server) {
                            $ConnParams['Server'] = $Server
                        } elseif ($DCResolution -and $DCResolution.Hostname) {
                            $ConnParams['Server'] = $DCResolution.Hostname
                            Write-Log "[Connect-adPEAS] ForceNTLM: Using discovered DC: $($DCResolution.Hostname)"
                        }
                        if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }
                        $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
                        $ConnParams['TimeoutSeconds'] = $TimeoutSeconds
                        $ConnParams['Credential'] = $CredObject
                        $ConnParams['ForceNTLM'] = $true

                        $Connection = Connect-LDAP @ConnParams

                        if (-not $Connection) {
                            return $null
                        }

                        # Track auth info
                        $Script:AuthInfo.Method = 'NTLM'
                        $Script:AuthInfo.KerberosUsed = $false
                        $Script:AuthInfo.NTLMImpersonation = $false
                        $Script:LDAPContext['Credential'] = $CredObject
                    }
                    # ===== Primary: Kerberos Authentication =====
                    # Cross-domain with NetBIOS prefix (e.g., CONTOSO\b.pitt): skip Kerberos
                    # Cannot discover KDC for NetBIOS name, go directly to NTLM/SimpleBind
                    elseif (-not $ForceSimpleBind -and $UserRealm -and $UserRealm -notmatch '\.') {
                        Write-Log "[Connect-adPEAS] Cross-domain with NetBIOS prefix '$UserRealm' - skipping Kerberos (cannot discover KDC)"
                        Show-Line "Cross-domain authentication (NetBIOS): using NTLM/SimpleBind" -Class Hint
                        # Fall through to NTLM Impersonation / SimpleBind below
                    }
                    elseif (-not $ForceSimpleBind) {
                        Write-Log "[Connect-adPEAS] Attempting Kerberos authentication..."

                        # Cross-domain with FQDN UserRealm: resolve KDC for user's realm
                        $UserRealmDC = $null
                        if ($UserRealm -and $UserRealm -match '\.') {
                            Write-Log "[Connect-adPEAS] Cross-domain: discovering KDC for user realm '$UserRealm'..."
                            $UserRealmDC = Resolve-adPEASName -Domain $UserRealm
                            if (-not $UserRealmDC -or -not $UserRealmDC.IP) {
                                Write-Log "[Connect-adPEAS] Cross-domain: could not discover KDC for '$UserRealm' - falling back to NTLM/SimpleBind"
                                Show-Line "Cross-domain: could not find KDC for '$UserRealm' - using NTLM/SimpleBind" -Class Hint
                                # Set flag to skip Kerberos and fall through to NTLM/SimpleBind
                                $UserRealmDC = $null
                                $UserRealm = $null  # Clear to prevent cross-domain Kerberos attempt
                            } else {
                                Write-Log "[Connect-adPEAS] Cross-domain: found KDC for '$UserRealm': $($UserRealmDC.Hostname) ($($UserRealmDC.IP))"
                            }
                        }

                        $KerbFlowParams = @{
                            SamAccountName = $SamAccountName
                            Domain = $Domain
                            DCHostname = $DCResolution.Hostname
                            Password = $PlainPassword
                            IgnoreSSLErrors = $IgnoreSSLErrors
                        }
                        if ($DCResolution.IP) { $KerbFlowParams['DCIP'] = $DCResolution.IP }
                        if ($Server) { $KerbFlowParams['Server'] = $Server }
                        if ($UseLDAPS) { $KerbFlowParams['UseLDAPS'] = $true }


                        # Cross-domain: pass user realm info so TGT is requested from correct KDC
                        if ($UserRealm -and $UserRealmDC) {
                            $KerbFlowParams['UserRealm'] = $UserRealm
                            $KerbFlowParams['UserRealmKDC'] = $UserRealmDC.IP
                        }

                        $KerbFlowResult = Invoke-KerberosAuthFlow @KerbFlowParams

                        if ($KerbFlowResult.Success) {
                            $KerberosAuthSuccess = $true
                            $Connection = $KerbFlowResult.Connection
                            Write-Log "[Connect-adPEAS] Kerberos authentication completed successfully"

                            $Script:AuthInfo.Method = 'Kerberos'
                            $Script:AuthInfo.KerberosUsed = $true
                            $Script:AuthInfo.TGTInfo = @{
                                UserName = $KerbFlowResult.TGTResult.UserName
                                Domain = $KerbFlowResult.TGTResult.Domain
                                EncryptionType = $KerbFlowResult.TGTResult.EncryptionType
                                Method = $KerbFlowResult.TGTResult.Method
                                AuthTime = $KerbFlowResult.TGTResult.AuthTime
                                StartTime = $KerbFlowResult.TGTResult.StartTime
                                EndTime = $KerbFlowResult.TGTResult.EndTime
                                RenewTill = $KerbFlowResult.TGTResult.RenewTill
                                ClockSkew = $KerbFlowResult.TGTResult.ClockSkew
                            }
                        }
                        else {
                            $ErrorMessage = $KerbFlowResult.Error
                            $KdcErrorCode = $KerbFlowResult.ErrorCode
                            Write-Log "[Connect-adPEAS] Kerberos authentication failed: $ErrorMessage (ErrorCode: $KdcErrorCode)"

                            # KDC errors indicate authentication/credential issues - fallback makes no sense
                            # Exception: cross-domain auth may get Error 6 (user not found) if TGS fails,
                            # which is expected - allow NTLM/SimpleBind fallback in that case
                            $IsCrossDomain = $null -ne $UserRealm
                            if ($null -ne $KdcErrorCode -and $KdcErrorCode -in $Script:KDC_FATAL_ERROR_CODES -and -not $IsCrossDomain) {
                                Show-ConnectionError -ErrorType "KerberosError" -ErrorCode $KdcErrorCode -ErrorCodeType "Kerberos" -AuthMethod $AuthMethod -NoThrow
                                return $null
                            }
                            if ($IsCrossDomain) {
                                Write-Log "[Connect-adPEAS] Cross-domain: Kerberos failed, allowing NTLM/SimpleBind fallback"
                                Show-Line "Cross-domain authentication: falling back to NTLM/SimpleBind" -Class Hint
                            }

                            # Check if this is a DNS resolution issue (custom DNS without hosts patching)
                            $IsDnsResolutionIssue = $ErrorMessage -match "Kerberos tickets obtained successfully.*LDAP connection failed"
                            if ($IsDnsResolutionIssue) {
                                Show-Line "Kerberos TGT/TGS acquired successfully, but LDAP requires hostname resolution" -Class Note
                                Show-Line "Use -PatchHostsFile for full Kerberos authentication" -Class Note
                                Write-Log "[Connect-adPEAS] Custom DNS active without hosts patching - SimpleBind fallback"
                            }

                            # Technical error (PTT failed, LDAP without Kerberos, etc.) - fallback is OK
                            $IsPTTError = $ErrorMessage -match "non-domain-joined|Remote Credential Guard|Ticket import failed|ticket not used|ticket not usable"
                            if ($IsPTTError) {
                                Write-Log "[Connect-adPEAS] Kerberos PTT not available on this system - using SimpleBind"
                            }

                            if ($ForceKerberos) {
                                if ($KerbFlowResult.IsNetworkError) {
                                    $NetworkServer = if ($KerbFlowResult.NetworkErrorServer) { $KerbFlowResult.NetworkErrorServer } else { $Server }
                                    Show-ConnectionError -ErrorType "NetworkError" -Details "Port 88 (Kerberos) unreachable on $NetworkServer" -NoThrow
                                }
                                else {
                                    if ($null -ne $KdcErrorCode) {
                                        Show-ConnectionError -ErrorType "KerberosError" -ErrorCode $KdcErrorCode -ErrorCodeType "Kerberos" -AuthMethod $AuthMethod -NoThrow
                                    } else {
                                        Show-ConnectionError -ErrorType "KerberosError" -Details $ErrorMessage -NoThrow
                                    }
                                }
                                return $null
                            }

                            Write-Log "[Connect-adPEAS] Kerberos PTT failed - trying NTLM impersonation fallback..."
                            Show-Line "Kerberos failed - trying NTLM impersonation" -Class Info
                        }
                    }
                    else {
                        Write-Log "[Connect-adPEAS] ForceSimpleBind specified, skipping Kerberos"
                    }

                    # ===== Fallback: Explicit NTLM -> SimpleBind =====
                    if (-not $KerberosAuthSuccess -and -not $ForceNTLM) {
                        # Try explicit NTLM first (better than SimpleBind: supports LDAP signing)
                        if (-not $ForceSimpleBind) {
                            Write-Log "[Connect-adPEAS] Attempting explicit NTLM fallback (AuthType::Ntlm)..."

                            $ConnParams = @{}
                            $ConnParams['Domain'] = $Domain
                            if ($Server) {
                                $ConnParams['Server'] = $Server
                            } elseif ($DCResolution -and $DCResolution.Hostname) {
                                $ConnParams['Server'] = $DCResolution.Hostname
                                Write-Log "[Connect-adPEAS] NTLM fallback: Using discovered DC: $($DCResolution.Hostname)"
                            }
                            if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }
                            $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
                            $ConnParams['TimeoutSeconds'] = $TimeoutSeconds
                            $ConnParams['Credential'] = $CredObject
                            $ConnParams['ForceNTLM'] = $true

                            $Connection = Connect-LDAP @ConnParams

                            if (-not $Connection) {
                                Write-Log "[Connect-adPEAS] LDAP connection failed with explicit NTLM - trying SimpleBind..."
                                Show-Line "NTLM failed - falling back to SimpleBind" -Class Hint
                                # Fall through to SimpleBind below
                            }
                            else {
                                $Script:AuthInfo.Method = 'NTLM'
                                $Script:AuthInfo.KerberosUsed = $false
                                $Script:AuthInfo.NTLMImpersonation = $false
                                $Script:LDAPContext['Credential'] = $CredObject

                                Show-Line "Connected via NTLM (supports LDAP signing)" -Class Hint
                            }
                        }

                        # Final fallback: SimpleBind
                        if (-not $Connection) {
                            Write-Log "[Connect-adPEAS] Using SimpleBind authentication..."

                            $ConnParams = @{}
                            $ConnParams['Domain'] = $Domain
                            if ($Server) {
                                $ConnParams['Server'] = $Server
                            } elseif ($DCResolution -and $DCResolution.Hostname) {
                                $ConnParams['Server'] = $DCResolution.Hostname
                                Write-Log "[Connect-adPEAS] Using discovered DC: $($DCResolution.Hostname)"
                            }
                            if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }

                            $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
                            $ConnParams['TimeoutSeconds'] = $TimeoutSeconds
                            $ConnParams['Credential'] = $CredObject

                            # Suppress error display on first attempt when LDAPS auto-upgrade might trigger
                            if (-not $UseLDAPS) {
                                $ConnParams['SuppressErrorDisplay'] = $true
                            }
                            $Connection = Connect-LDAP @ConnParams
                            $ConnParams.Remove('SuppressErrorDisplay')

                            # Auto-upgrade to LDAPS when SimpleBind fails with LDAP_STRONG_AUTH_REQUIRED (error 8)
                            # This happens when LDAP Channel Binding or LDAP Signing is enforced by domain policy

                            # Reclassify LDAP OperationsError (1) as AuthenticationFailed for SimpleBind
                            # Empty password -> anonymous bind succeeds -> search fails with OperationsError = auth failure
                            if (-not $Connection -and $Script:LastLDAPErrorCode -eq 1) {
                                $Script:ConnectionState = "AuthenticationFailed"
                            }

                            # If it's a different error, show the suppressed error message now
                            if (-not $Connection -and -not $UseLDAPS -and $Script:LastLDAPErrorCode -ne 8) {
                                if ($Script:ConnectionState) {
                                    if ($null -ne $Script:LastLDAPErrorCode) {
                                        Show-ConnectionError -ErrorType $Script:ConnectionState -ErrorCode $Script:LastLDAPErrorCode -ErrorCodeType "LDAP" -NoThrow
                                    } else {
                                        Show-ConnectionError -ErrorType $Script:ConnectionState -Details $Script:LastLDAPErrorDetails -NoThrow
                                    }
                                }
                            }
                            if (-not $Connection -and -not $UseLDAPS -and $Script:LastLDAPErrorCode -eq 8) {
                                Write-Log "[Connect-adPEAS] SimpleBind failed with LDAP_STRONG_AUTH_REQUIRED - auto-upgrading to LDAPS..."
                                Show-Line "LDAP signing/channel binding required - auto-upgrading to LDAPS" -Class Hint

                                $ConnParams['UseLDAPS'] = $true
                                $Connection = Connect-LDAP @ConnParams
                            }

                            if (-not $Connection) {
                                return $null
                            }

                            $Script:AuthInfo.Method = 'SimpleBind'
                            $Script:AuthInfo.KerberosUsed = $false
                        }
                    }
                }

                'Certificate' {
                    Write-Log "[Connect-adPEAS] Domain: $Domain"
                    if ($Server) {
                        Write-Log "[Connect-adPEAS] Server: $Server"
                    }
                    Write-Log "[Connect-adPEAS] Certificate: $Certificate"

                    # Convert CertificatePassword to plain string for Invoke-KerberosAuth (with proper memory cleanup)
                    if ($CertificatePassword -is [System.Security.SecureString]) {
                        $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($CertificatePassword)
                        try {
                            $PlainCertPassword = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
                        }
                        finally {
                            [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
                        }
                    }
                    elseif ($CertificatePassword -is [string]) {
                        $PlainCertPassword = $CertificatePassword
                    }
                    else {
                        throw "CertificatePassword must be either String or SecureString"
                    }

                    # Load certificate - handle both Base64 and file path via helper
                    try {
                        $certResult = ConvertFrom-Base64OrFile -InputValue $Certificate -ExpectedFormat "Certificate" -ParameterName "Certificate"

                        if (-not $certResult.Success) {
                            throw $certResult.Error
                        }

                        Write-Log "[Connect-adPEAS] Certificate loaded from $($certResult.Source): $($certResult.Data.Length) bytes ($($certResult.Format))"

                        # Load X509Certificate2 from bytes
                        $Cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(
                            $certResult.Data,
                            $PlainCertPassword,
                            [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable
                        )
                    }
                    catch {
                        $Script:ConnectionState = "CertificateLoadFailed"

                        # Use HResult for structured error classification via central lookup
                        $errorHResult = $_.Exception.HResult
                        $errorMsg = $_.Exception.Message

                        Write-Log "[Connect-adPEAS] Certificate load error - HResult: 0x$($errorHResult.ToString('X8')), Message: $errorMsg"

                        # Pass HRESULT code for central lookup; Details as fallback for unknown HRESULTs
                        Show-ConnectionError -ErrorType "PFXLoadError" -ErrorCode $errorHResult -ErrorCodeType "HRESULT" -Details $errorMsg -NoThrow
                        throw "Certificate load failed"
                    }

                    if ($ForcePassTheCert) {
                        # ===== Pass-the-Cert (Schannel) =====
                        # Direct LDAPS bind with client certificate - no Kerberos involved
                        # Works when: Port 88 blocked, no Smart Card Logon EKU, no admin rights for PTT
                        Write-Log "[Connect-adPEAS] Using Pass-the-Cert (Schannel) - bypassing Kerberos"

                        # Force LDAPS (Schannel requires TLS)
                        if (-not $UseLDAPS) {
                            $UseLDAPS = $true
                            Write-Log "[Connect-adPEAS] LDAPS automatically enabled for Pass-the-Cert"
                        }

                        # Extract display identity from cert (for console output only, not for auth)
                        $CertDisplayName = "Certificate-based (Schannel)"
                        foreach ($ext in $Cert.Extensions) {
                            if ($ext.Oid.Value -eq "2.5.29.17") {
                                $san = $ext.Format($false)
                                if ($san -match "Principal Name[=:]([^,\r\n]+)") {
                                    $CertDisplayName = $Matches[1].Trim()
                                    break
                                }
                            }
                        }
                        if ($CertDisplayName -eq "Certificate-based (Schannel)" -and $Cert.Subject -match "CN=([^,]+)") {
                            $CertDisplayName = $Matches[1]
                        }
                        Write-Log "[Connect-adPEAS] Certificate display identity: $CertDisplayName"

                        # Resolve DC hostname using unified resolver
                        if ($Server) {
                            $ResolvedIP = Resolve-adPEASName -Name $Server
                            if (-not $ResolvedIP) {
                                Show-ConnectionError -ErrorType "DomainError" -Details "Server '$Server' could not be resolved - check DNS or use an IP address" -NoThrow
                                return $null
                            }
                        }

                        # Connect to LDAP with client certificate
                        $ConnParams = @{
                            Domain = $Domain
                            ClientCertificate = $Cert
                            UseLDAPS = $true
                            IgnoreSSLErrors = $IgnoreSSLErrors
                            TimeoutSeconds = $TimeoutSeconds
                        }
                        if ($Server) { $ConnParams['Server'] = $Server }

                        $Connection = Connect-LDAP @ConnParams

                        if (-not $Connection) {
                            return $null
                        }

                        # Track auth info - Schannel, no Kerberos
                        $Script:AuthInfo.Method = 'Schannel'
                        $Script:AuthInfo.KerberosUsed = $false

                    } else {
                    # ===== PKINIT Flow (existing) =====

                    # Extract all identities from certificate (multi-identity support)
                    # Certificates can contain multiple SANs (UPN + DNS, multiple UPNs, etc.)
                    # The user can select which identity to authenticate as via -Username
                    $certIdentities = @()

                    # 1. Collect all UPNs from SAN
                    foreach ($ext in $Cert.Extensions) {
                        if ($ext.Oid.Value -eq "2.5.29.17") {  # Subject Alternative Name
                            $san = $ext.Format($false)
                            Write-Log "[Connect-adPEAS] SAN Extension content: $san"

                            # Match all UPNs - Format: "Principal Name=user@domain.com" (may appear multiple times)
                            $upnMatches = [regex]::Matches($san, "Principal Name[=:]([^,\r\n]+)")
                            foreach ($m in $upnMatches) {
                                $upnValue = $m.Groups[1].Value.Trim()
                                if ($upnValue -match "^([^@]+)@") {
                                    $certIdentities += [PSCustomObject]@{
                                        Type = "UPN"
                                        Value = $upnValue
                                        CName = $Matches[1]  # username part without domain
                                    }
                                    Write-Log "[Connect-adPEAS] Found UPN identity: $upnValue -> cname: $($Matches[1])"
                                }
                            }

                            # Match all DNS names - Format: "DNS Name=srv-dc.contoso.com"
                            $dnsMatches = [regex]::Matches($san, "DNS Name=([^,\r\n]+)")
                            foreach ($m in $dnsMatches) {
                                $dnsValue = $m.Groups[1].Value.Trim()
                                $hostPart = ($dnsValue -split '\.')[0]
                                $certIdentities += [PSCustomObject]@{
                                    Type = "DNS"
                                    Value = $dnsValue
                                    CName = "$hostPart`$"  # computer account
                                }
                                Write-Log "[Connect-adPEAS] Found DNS identity: $dnsValue -> cname: $hostPart`$"
                            }
                        }
                    }

                    # 2. CN from Subject as fallback (only if no SAN identities found)
                    if ($certIdentities.Count -eq 0) {
                        if ($Cert.Subject -match "CN=([^,]+)") {
                            $cnValue = $Matches[1]
                            Write-Log "[Connect-adPEAS] No SAN identities, falling back to CN: $cnValue"

                            if ($cnValue -match "^([^.]+)\.(.+\..+)$") {
                                # FQDN format (e.g. DC01.contoso.com) -> computer account
                                $certIdentities += [PSCustomObject]@{
                                    Type = "CN"
                                    Value = $cnValue
                                    CName = "$($Matches[1])`$"
                                }
                            } else {
                                # Simple CN -> user account
                                $certIdentities += [PSCustomObject]@{
                                    Type = "CN"
                                    Value = $cnValue
                                    CName = $cnValue
                                }
                            }
                        }
                    }

                    if ($certIdentities.Count -eq 0) {
                        $Script:ConnectionState = "CertificateUsernameFailed"
                        Show-ConnectionError -ErrorType "GenericError" -Details "Could not extract identity from certificate. Certificate must have UPN or DNS in SAN, or CN in Subject." -NoThrow
                        throw "Certificate username extraction failed"
                    }

                    # 3. Identity selection
                    $CertUserName = $null

                    if ($Username) {
                        # Manual override via -Username parameter
                        # Map the provided value to a cname
                        if ($Username -match '@') {
                            # UPN format (user@domain.com) -> extract username part
                            $CertUserName = ($Username -split '@')[0]
                        } elseif ($Username -match '\..*\.') {
                            # FQDN format (srv-dc.contoso.com) -> computer account
                            $CertUserName = "$(($Username -split '\.')[0])`$"
                        } elseif ($Username -match '\$$') {
                            # Explicit computer account (SRV-DC$) -> use as-is
                            $CertUserName = $Username
                        } else {
                            # Simple name - check if it matches a DNS identity (-> computer) or use as-is (-> user)
                            $dnsMatch = $certIdentities | Where-Object { $_.Type -eq 'DNS' -and ($_.Value -split '\.')[0] -eq $Username }
                            if ($dnsMatch) {
                                $CertUserName = "$Username`$"
                            } else {
                                $CertUserName = $Username
                            }
                        }

                        # Display all identities + selected override
                        if ($certIdentities.Count -gt 1) {
                            Show-Line "Certificate contains multiple identities" -Class Note
                            $idx = 1
                            foreach ($id in $certIdentities) {
                                Show-KeyValue "    [$idx] $($id.Type):" $id.Value
                                $idx++
                            }
                        }
                        Show-KeyValue "Using specified identity:" $CertUserName -Class Note
                        Write-Log "[Connect-adPEAS] Manual identity override: $Username -> cname: $CertUserName"

                    } elseif ($certIdentities.Count -eq 1) {
                        # Single identity - auto-select (no extra output, same as before)
                        $CertUserName = $certIdentities[0].CName
                        Write-Log "[Connect-adPEAS] Single identity in certificate: $($certIdentities[0].Type)=$($certIdentities[0].Value) -> cname: $CertUserName"

                    } else {
                        # Multiple identities - show all, auto-select first, hint about -Username
                        Show-Line "Certificate contains multiple identities" -Class Note
                        $idx = 1
                        foreach ($id in $certIdentities) {
                            Show-KeyValue "    [$idx] $($id.Type):" $id.Value
                            $idx++
                        }

                        # Auto-select first identity (UPNs come before DNS in the list)
                        $CertUserName = $certIdentities[0].CName
                        Show-KeyValue "Using identity [1]:" $CertUserName -Class Note
                        Show-Line "To select a different identity, use: -Username <name>" -Class Note

                        Write-Log "[Connect-adPEAS] Multiple identities found ($($certIdentities.Count)), auto-selected first: $($certIdentities[0].Type)=$($certIdentities[0].Value) -> cname: $CertUserName"
                    }

                    Write-Log "[Connect-adPEAS] Username from certificate: $CertUserName"

                    # Resolve DC hostname and IP using unified resolver
                    # If -Server is explicit, just resolve that hostname to IP (skip DC discovery)
                    # If -Server is not set, use domain-based DC discovery via SRV records
                    if ($Server) {
                        $ResolvedIP = Resolve-adPEASName -Name $Server
                        $DCResolution = [PSCustomObject]@{ Hostname = $Server; IP = $ResolvedIP }

                        if (-not $ResolvedIP) {
                            Show-ConnectionError -ErrorType "DomainError" -Details "Server '$Server' could not be resolved - check DNS or use an IP address" -NoThrow
                            return $null
                        }
                    } else {
                        $DCResolution = Resolve-adPEASName -Domain $Domain

                        # If domain-based DC discovery fails, terminate immediately
                        if (-not $DCResolution -or -not $DCResolution.Hostname) {
                            Show-ConnectionError -ErrorType "DomainError" -Details "Could not discover a Domain Controller for '$Domain' - DNS resolution failed. Use -Server to specify a DC manually." -NoThrow
                            return $null
                        }
                    }

                    # Determine DC for PKINIT - use resolved IP if available (custom DNS scenario)
                    $PKINITServer = if ($DCResolution.IP) {
                        Write-Log "[Connect-adPEAS] Using resolved IP for PKINIT: $($DCResolution.IP)"
                        $DCResolution.IP
                    } elseif ($Server) {
                        $Server
                    } else {
                        $Domain
                    }

                    # Step 1: PKINIT Authentication using unified Invoke-KerberosAuth
                    # Pass the already-loaded certificate object (avoids re-loading)
                    Write-Log "[Connect-adPEAS] Step 1: Performing PKINIT authentication..."
                    Write-Log "[Connect-adPEAS] PKINIT Target: $PKINITServer"
                    Write-Log "[Connect-adPEAS] PKINIT User: $CertUserName"
                    Write-Log "[Connect-adPEAS] PKINIT Domain: $Domain"
                    Write-Log "[Connect-adPEAS] Certificate Subject: $($Cert.Subject)"
                    Write-Log "[Connect-adPEAS] Certificate Issuer: $($Cert.Issuer)"
                    Write-Log "[Connect-adPEAS] Certificate Thumbprint: $($Cert.Thumbprint)"
                    Write-Log "[Connect-adPEAS] Certificate Has Private Key: $($Cert.HasPrivateKey)"
                    Write-Log "[Connect-adPEAS] Certificate Valid From: $($Cert.NotBefore) To: $($Cert.NotAfter)"

                    $PKINITResult = Invoke-KerberosAuth -UserName $CertUserName -Domain $Domain -DomainController $PKINITServer -Certificate $Cert

                    if (-not $PKINITResult -or -not $PKINITResult.Success) {
                        $ErrorMsg = if ($PKINITResult.Error) { $PKINITResult.Error } elseif ($PKINITResult.Message) { $PKINITResult.Message } else { "Unknown PKINIT error" }
                        Write-Log "[Connect-adPEAS] PKINIT Result: $($PKINITResult | ConvertTo-Json -Depth 2 -Compress)"
                        $Script:ConnectionState = "PKINITFailed"

                        # Use structured error code from result object (no fragile regex extraction)
                        $KdcErrorCode = $PKINITResult.ErrorCode
                        if ($null -ne $KdcErrorCode) {
                            Show-ConnectionError -ErrorType "KerberosError" -ErrorCode $KdcErrorCode -ErrorCodeType "Kerberos" -AuthMethod $AuthMethod -NoThrow
                        } else {
                            Show-ConnectionError -ErrorType "KerberosError" -Details $ErrorMsg -NoThrow
                        }
                        return $null
                    }

                    Write-Log "[Connect-adPEAS] PKINIT authentication successful"
                    Write-Log "[Connect-adPEAS] PKINIT Method: $($PKINITResult.Method)"
                    Write-Log "[Connect-adPEAS] PKINIT Encryption: $($PKINITResult.EncryptionType)"

                    # Step 2: Import TGT into Windows session (Pass-the-Ticket)
                    # The PKINIT result contains the TGT which needs to be injected into Windows so that subsequent LDAP connections can use Kerberos auth automatically
                    Write-Log "[Connect-adPEAS] Step 2: Importing TGT into Windows session..."

                    $PTTSuccess = $false
                    if ($PKINITResult.TicketBytes -and $PKINITResult.SessionKeyBytes) {
                        try {
                            # Get realm from PKINIT result (uppercase domain)
                            $Realm = if ($PKINITResult.Domain) { $PKINITResult.Domain.ToUpper() } else { $Domain.ToUpper() }

                            Write-Log "[Connect-adPEAS] PTT Realm: $Realm"
                            Write-Log "[Connect-adPEAS] PTT ClientName: $CertUserName"
                            Write-Log "[Connect-adPEAS] PTT TicketBytes: $($PKINITResult.TicketBytes.Length) bytes"
                            Write-Log "[Connect-adPEAS] PTT SessionKeyBytes: $($PKINITResult.SessionKeyBytes.Length) bytes"
                            if ($PKINITResult.TicketFlags) {
                                $flagsHex = ($PKINITResult.TicketFlags | ForEach-Object { $_.ToString('X2') }) -join ''
                                Write-Log "[Connect-adPEAS] PTT TicketFlags: 0x$flagsHex"
                            }

                            # Build parameters for Import-KerberosTicket
                            $pttParams = @{
                                TicketBytes = $PKINITResult.TicketBytes
                                SessionKey = $PKINITResult.SessionKeyBytes
                                SessionKeyType = $PKINITResult.EncryptionType
                                Realm = $Realm
                                ClientName = $CertUserName
                                ServerName = "krbtgt"
                                ServerInstance = $Realm
                            }
                            # Add actual ticket times from EncKDCRepPart (critical for Windows LSA to accept)
                            if ($PKINITResult.StartTime) { $pttParams['StartTime'] = $PKINITResult.StartTime }
                            if ($PKINITResult.EndTime) { $pttParams['EndTime'] = $PKINITResult.EndTime }
                            if ($PKINITResult.RenewTill) { $pttParams['RenewTill'] = $PKINITResult.RenewTill }
                            if ($PKINITResult.TicketFlags) { $pttParams['TicketFlags'] = $PKINITResult.TicketFlags }

                            $PTTResult = Import-KerberosTicket @pttParams

                            if ($PTTResult -and $PTTResult.Success) {
                                Write-Log "[Connect-adPEAS] TGT imported successfully (Pass-the-Ticket)"
                                $PTTSuccess = $true
                            } else {
                                $PTTError = if ($PTTResult.Error) { $PTTResult.Error } else { "Unknown error" }
                                Write-Warning "[Connect-adPEAS] Failed to import TGT: $PTTError"
                                Write-Log "[Connect-adPEAS] Continuing without PTT - LDAP may require alternative auth"
                            }
                        }
                        catch {
                            Write-Warning "[Connect-adPEAS] PTT failed: $_"
                            Write-Log "[Connect-adPEAS] Continuing without PTT - LDAP may require alternative auth"
                        }
                    } else {
                        Write-Log "[Connect-adPEAS] No TGT bytes available for PTT (ticket/session key missing)"
                        if ($PKINITResult.TicketBytes) {
                            Write-Log "[Connect-adPEAS] TicketBytes: $($PKINITResult.TicketBytes.Length) bytes"
                        } else {
                            Write-Log "[Connect-adPEAS] TicketBytes: null/empty"
                        }
                        if ($PKINITResult.SessionKeyBytes) {
                            Write-Log "[Connect-adPEAS] SessionKeyBytes: $($PKINITResult.SessionKeyBytes.Length) bytes"
                        } else {
                            Write-Log "[Connect-adPEAS] SessionKeyBytes: null/empty"
                        }
                    }

                    # Step 3: Connect to LDAP using Kerberos TGT from Windows session
                    Write-Log "[Connect-adPEAS] Step 3: Establishing LDAP connection..."
                    $ConnParams = @{}
                    $ConnParams['Domain'] = $Domain  # Domain is always provided now
                    if ($Server) { $ConnParams['Server'] = $Server }
                    if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }

                    $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
                    $ConnParams['TimeoutSeconds'] = $TimeoutSeconds
                    # Note: No Credential needed - uses Kerberos TGT from Windows session (PTT)

                    $Connection = Connect-LDAP @ConnParams

                    # Connect-LDAP already showed error if it failed
                    if (-not $Connection) {
                        return $null
                    }

                    # Track auth info - PKINIT always uses Kerberos
                    $Script:AuthInfo.Method = 'Kerberos'
                    $Script:AuthInfo.KerberosUsed = $true
                    $Script:AuthInfo.TGTInfo = @{
                        UserName       = $PKINITResult.UserName
                        Domain         = $PKINITResult.Domain
                        EncryptionType = $PKINITResult.EncryptionType
                        Method         = $PKINITResult.Method
                        AuthTime       = $PKINITResult.AuthTime
                        StartTime      = $PKINITResult.StartTime
                        EndTime        = $PKINITResult.EndTime
                        RenewTill      = $PKINITResult.RenewTill
                        ClockSkew      = $PKINITResult.ClockSkew
                    }

                    # UnPAC-the-hash: Recover NT hash from PKINIT via U2U TGS-REQ
                    if ($PKINITResult.ASRepReplyKey -and $PKINITResult.TicketBytes -and $PKINITResult.SessionKeyBytes) {
                        try {
                            Write-Log "[Connect-adPEAS] Attempting UnPAC-the-hash to recover NT hash..."
                            $unPACResult = Invoke-UnPACTheHash `
                                -TGT $PKINITResult.TicketBytes `
                                -SessionKey $PKINITResult.SessionKeyBytes `
                                -SessionKeyType $PKINITResult.EncryptionType `
                                -ASRepReplyKey $PKINITResult.ASRepReplyKey `
                                -UserName $CertUserName `
                                -Domain $Domain `
                                -DomainController $PKINITServer

                            if ($unPACResult.Success) {
                                $Script:AuthInfo.TGTInfo['NTHash'] = $unPACResult.NTHash
                                if ($unPACResult.LMHash) {
                                    $Script:AuthInfo.TGTInfo['LMHash'] = $unPACResult.LMHash
                                }
                                Write-Log "[Connect-adPEAS] UnPAC-the-hash successful: NT hash recovered"
                            } else {
                                Write-Log "[Connect-adPEAS] UnPAC-the-hash: $($unPACResult.Message)" -Level Warning
                            }
                        }
                        catch {
                            Write-Log "[Connect-adPEAS] UnPAC-the-hash failed: $_" -Level Warning
                        }
                    }
                    } # end else (PKINIT flow)
                }

                'WindowsAuth' {
                    Write-Log "[Connect-adPEAS] Domain: $Domain"
                    if ($Server) {
                        Write-Log "[Connect-adPEAS] Server: $Server"
                    }
                    Write-Log "[Connect-adPEAS] Username: $env:USERDOMAIN\$env:USERNAME"

                    # Windows Authentication uses SSPI which automatically selects Kerberos when available and falls back to NTLM when Kerberos is not possible
                    # -ForceSimpleBind has no effect here (Windows handles auth negotiation)
                    # -ForceKerberos has no effect here (controlled by Windows/GPO)

                    if ($ForceSimpleBind) {
                        Write-Warning "[!] -ForceSimpleBind has no effect with WindowsAuth"
                        Write-Warning "[!] Windows Auth automatically negotiates Kerberos/NTLM via SSPI"
                        Write-Warning "[!] To force a specific auth method, use -Username/-Password or -Credential"
                    }

                    if ($ForceKerberos) {
                        Write-Warning "[!] -ForceKerberos has no effect with WindowsAuth"
                        Write-Warning "[!] Windows Auth negotiation is controlled by system/GPO settings"
                        Write-Warning "[!] To enforce Kerberos, use -Username/-Password with -ForceKerberos"
                    }

                    Write-Log "[Connect-adPEAS] Using Windows Authentication (SSPI - Kerberos/NTLM negotiation)"

                    # Build connection parameters
                    $ConnParams = @{}
                    $ConnParams['Domain'] = $Domain
                    if ($Server) { $ConnParams['Server'] = $Server }
                    if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }

                    $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
                    $ConnParams['TimeoutSeconds'] = $TimeoutSeconds

                    # Connect (no credentials = use current Windows identity via SSPI)
                    $Connection = Connect-LDAP @ConnParams

                    # Connect-LDAP already showed error if it failed
                    if (-not $Connection) {
                        return $null
                    }

                    # Track auth info - WindowsAuth uses SSPI (Kerberos/NTLM negotiation)
                    # Connect-LDAP now detects if Kerberos was used via "Who Am I?" operation
                    if ($Connection -and $Connection.DetectedKerberos) {
                        $Script:AuthInfo.Method = 'Kerberos'
                        $Script:AuthInfo.KerberosUsed = $true
                        Write-Log "[Connect-adPEAS] Kerberos authentication detected by LDAP layer"
                    } else {
                        $Script:AuthInfo.Method = 'WindowsSSPI'
                        $Script:AuthInfo.KerberosUsed = $false  # Unknown - could be Kerberos or NTLM
                    }
                }

                { $_ -in @('NTHash', 'AES256', 'AES128') } {
                    # Hash/Key-based authentication (Overpass-the-Hash / Pass-the-Key)
                    # Primary: Kerberos TGT + TGS for LDAP + Pass-the-Ticket
                    # No fallback - hash/key auth requires Kerberos

                    Write-Log "[Connect-adPEAS] Domain: $Domain"
                    if ($Server) {
                        Write-Log "[Connect-adPEAS] Server: $Server"
                    }
                    Write-Log "[Connect-adPEAS] Username: $Username"
                    Write-Log "[Connect-adPEAS] Auth Type: $AuthMethod"

                    # Extract sAMAccountName and detect cross-domain authentication
                    $SamAccountName = $Username
                    $UserRealm = $null  # null = same as target domain

                    if ($Username -match '^([^\\]+)\\(.+)$') {
                        $UserDomainPrefix = $Matches[1]
                        $SamAccountName = $Matches[2]

                        $targetPrefix = ($Domain -split '\.')[0]
                        if ($UserDomainPrefix -ine $targetPrefix -and $UserDomainPrefix -ine $Domain) {
                            $UserRealm = $UserDomainPrefix
                            if ($UserRealm -match '\.') {
                                Write-Log "[Connect-adPEAS] Cross-domain detected: user in '$UserRealm' (FQDN), target '$Domain'"
                            } else {
                                Write-Log "[Connect-adPEAS] Cross-domain detected: user in '$UserRealm' (NetBIOS), target '$Domain'"
                            }
                        }
                    }
                    elseif ($Username -match '^(.+)@([^@]+)$') {
                        $SamAccountName = $Matches[1]
                        $upnDomain = $Matches[2]
                        if ($upnDomain -ine $Domain) {
                            $UserRealm = $upnDomain
                            Write-Log "[Connect-adPEAS] Cross-domain detected: user UPN realm '$UserRealm', target '$Domain'"
                        }
                    }
                    Write-Log "[Connect-adPEAS] Extracted sAMAccountName: $SamAccountName"

                    $KerberosAuthSuccess = $false
                    $Connection = $null
                    $KerberosError = $null

                    # Resolve DC hostname and IP using unified resolver
                    # If -Server is explicit, just resolve that hostname to IP (skip DC discovery)
                    # If -Server is not set, use domain-based DC discovery via SRV records
                    if ($Server) {
                        $ResolvedIP = Resolve-adPEASName -Name $Server
                        $DCResolution = [PSCustomObject]@{ Hostname = $Server; IP = $ResolvedIP }

                        if (-not $ResolvedIP) {
                            Show-ConnectionError -ErrorType "DomainError" -Details "Server '$Server' could not be resolved - check DNS or use an IP address" -NoThrow
                            return $null
                        }
                    } else {
                        $DCResolution = Resolve-adPEASName -Domain $Domain

                        # If domain-based DC discovery fails, terminate immediately
                        if (-not $DCResolution -or -not $DCResolution.Hostname) {
                            Show-ConnectionError -ErrorType "DomainError" -Details "Could not discover a Domain Controller for '$Domain' - DNS resolution failed. Use -Server to specify a DC manually." -NoThrow
                            return $null
                        }
                    }

                    # ===== Primary: Kerberos Authentication =====
                    if (-not $ForceSimpleBind) {
                        Write-Log "[Connect-adPEAS] Attempting Kerberos authentication ($AuthMethod)..."

                        # Cross-domain with FQDN UserRealm: resolve KDC for user's realm
                        $UserRealmDC = $null
                        if ($UserRealm -and $UserRealm -match '\.') {
                            Write-Log "[Connect-adPEAS] Cross-domain: discovering KDC for user realm '$UserRealm'..."
                            $UserRealmDC = Resolve-adPEASName -Domain $UserRealm
                            if (-not $UserRealmDC -or -not $UserRealmDC.IP) {
                                Write-Log "[Connect-adPEAS] Cross-domain: could not discover KDC for '$UserRealm'"
                                Show-ConnectionError -ErrorType "KerberosError" -Details "Could not discover KDC for user realm '$UserRealm'" -NoThrow
                                return $null
                            }
                            Write-Log "[Connect-adPEAS] Cross-domain: found KDC for '$UserRealm': $($UserRealmDC.Hostname) ($($UserRealmDC.IP))"
                        }
                        elseif ($UserRealm -and $UserRealm -notmatch '\.') {
                            # NetBIOS prefix with hash auth - cannot discover KDC and no SimpleBind fallback
                            Write-Log "[Connect-adPEAS] Cross-domain with NetBIOS prefix '$UserRealm' and hash auth - cannot discover KDC"
                            Show-ConnectionError -ErrorType "KerberosError" -Details "Cross-domain with NetBIOS prefix '$UserRealm' requires FQDN (e.g., contoso.com\\$SamAccountName)" -NoThrow
                            return $null
                        }

                        # Use helper function for Kerberos auth flow
                        $KerbFlowParams = @{
                            SamAccountName = $SamAccountName
                            Domain = $Domain
                            DCHostname = $DCResolution.Hostname
                            IgnoreSSLErrors = $IgnoreSSLErrors
                        }
                        # Pass resolved IP for custom DNS scenarios (system DNS may not resolve DC hostname)
                        if ($DCResolution.IP) { $KerbFlowParams['DCIP'] = $DCResolution.IP }
                        if ($Server) { $KerbFlowParams['Server'] = $Server }
                        if ($UseLDAPS) { $KerbFlowParams['UseLDAPS'] = $true }


                        # Cross-domain: pass user realm info so TGT is requested from correct KDC
                        if ($UserRealm -and $UserRealmDC) {
                            $KerbFlowParams['UserRealm'] = $UserRealm
                            $KerbFlowParams['UserRealmKDC'] = $UserRealmDC.IP
                        }

                        # Add the appropriate key based on auth method
                        switch ($AuthMethod) {
                            'NTHash' { $KerbFlowParams['NTHash'] = $NTHash }
                            'AES256' { $KerbFlowParams['AES256Key'] = $AES256Key }
                            'AES128' { $KerbFlowParams['AES128Key'] = $AES128Key }
                        }

                        $KerbFlowResult = Invoke-KerberosAuthFlow @KerbFlowParams

                        if ($KerbFlowResult.Success) {
                            $KerberosAuthSuccess = $true
                            $Connection = $KerbFlowResult.Connection
                            Write-Log "[Connect-adPEAS] Kerberos authentication completed successfully"

                            # Track auth info
                            $Script:AuthInfo.Method = 'Kerberos'
                            $Script:AuthInfo.KerberosUsed = $true
                            $Script:AuthInfo.TGTInfo = @{
                                UserName = $KerbFlowResult.TGTResult.UserName
                                Domain = $KerbFlowResult.TGTResult.Domain
                                EncryptionType = $KerbFlowResult.TGTResult.EncryptionType
                                Method = $KerbFlowResult.TGTResult.Method
                                AuthTime = $KerbFlowResult.TGTResult.AuthTime
                                StartTime = $KerbFlowResult.TGTResult.StartTime
                                EndTime = $KerbFlowResult.TGTResult.EndTime
                                RenewTill = $KerbFlowResult.TGTResult.RenewTill
                                ClockSkew = $KerbFlowResult.TGTResult.ClockSkew
                            }
                        }
                        else {
                            $KerberosError = $KerbFlowResult.Error
                            $KerberosErrorCode = $KerbFlowResult.ErrorCode
                            Write-Log "[Connect-adPEAS] Kerberos authentication failed: $KerberosError"
                        }
                    }
                    else {
                        Write-Log "[Connect-adPEAS] ForceSimpleBind specified, skipping Kerberos"
                        $KerberosError = "Skipped (ForceSimpleBind)"
                    }

                    # ===== Hash auth failed =====
                    if (-not $KerberosAuthSuccess) {
                        $Script:ConnectionState = "HashAuthFailed"
                        if ($null -ne $KerberosErrorCode) {
                            Show-ConnectionError -ErrorType "KerberosError" -ErrorCode $KerberosErrorCode -ErrorCodeType "Kerberos" -AuthMethod $AuthMethod -NoThrow
                        } else {
                            Show-ConnectionError -ErrorType "KerberosError" -Details $KerberosError -NoThrow
                        }
                        return $null
                    }
                }

                { $_ -in @('Kirbi', 'Ccache') } {
                    # Ticket-based authentication (Pass-the-Ticket)
                    # Accepts file path OR Base64-encoded data
                    # No fallback available - requires valid ticket data

                    # Warn about ignored parameters
                    if ($Username) {
                        Write-Warning "[!] -Username is ignored for ticket-based auth (identity is embedded in ticket)"
                    }

                    $TicketInput = if ($AuthMethod -eq 'Kirbi') { $Kirbi } else { $Ccache }
                    Write-Log "[Connect-adPEAS] Domain: $Domain"
                    if ($Server) {
                        Write-Log "[Connect-adPEAS] Server: $Server"
                    }
                    Write-Log "[Connect-adPEAS] Ticket Input: $($TicketInput.Substring(0, [Math]::Min(50, $TicketInput.Length)))..."

                    $Connection = $null

                    try {
                        # Load and import the ticket
                        Write-Log "[Connect-adPEAS] Step 1: Loading ticket..."

                        $ImportParams = @{}
                        if ($AuthMethod -eq 'Kirbi') {
                            $ImportParams['Kirbi'] = $Kirbi
                        }
                        else {
                            $ImportParams['Ccache'] = $Ccache
                        }

                        $PTTResult = Import-KerberosTicket @ImportParams

                        if (-not $PTTResult -or -not $PTTResult.Success) {
                            $ErrorMsg = if ($PTTResult.Error) { $PTTResult.Error } else { "Unknown error" }
                            throw "Ticket import failed: $ErrorMsg"
                        }

                        Write-Log "[Connect-adPEAS] Ticket imported successfully"

                        # Connect to LDAP using Kerberos (ticket now in session)
                        Write-Log "[Connect-adPEAS] Step 2: Establishing LDAP connection with Kerberos..."

                        $ConnParams = @{}
                        $ConnParams['Domain'] = $Domain
                        if ($Server) { $ConnParams['Server'] = $Server }
                        if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }
    
                        $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
                        $ConnParams['TimeoutSeconds'] = $TimeoutSeconds
                        # No Credential - uses Kerberos ticket from session

                        $Connection = Connect-LDAP @ConnParams

                        if ($Connection) {
                            Write-Log "[Connect-adPEAS] Kerberos authentication completed successfully"

                            # Track auth info
                            $Script:AuthInfo.Method = 'Kerberos'
                            $Script:AuthInfo.KerberosUsed = $true
                            # For imported tickets, estimate clock skew from AuthTime
                            $importedClockSkew = $null
                            if ($PTTResult.AuthTime) {
                                $importedClockSkew = $PTTResult.AuthTime - [DateTime]::UtcNow
                            }
                            $Script:AuthInfo.TGTInfo = @{
                                UserName = $PTTResult.UserName
                                Domain = $PTTResult.Realm
                                EncryptionType = $PTTResult.EncryptionType
                                Method = if ($AuthMethod -eq 'Kirbi') { 'Kirbi' } else { 'Ccache' }
                                AuthTime = $PTTResult.AuthTime
                                StartTime = $PTTResult.StartTime
                                EndTime = $PTTResult.EndTime
                                RenewTill = $PTTResult.RenewTill
                                ClockSkew = $importedClockSkew
                            }
                        }
                    }
                    catch {
                        $TicketError = $_.Exception.Message
                        # Show error if it's from ticket import/validation, not from Connect-LDAP
                        if ($TicketError -match "Ticket import failed|Invalid kirbi|Invalid ccache|input error") {
                            Show-ConnectionError -ErrorType "TicketImportError" -Details $TicketError -NoThrow
                        }
                        $Script:ConnectionState = "TicketAuthFailed"
                        return $null
                    }

                    # Connect-LDAP already showed error if it failed
                    if (-not $Connection) {
                        $Script:ConnectionState = "TicketAuthFailed"
                        return $null
                    }
                }
            }

            # ===== Connection Validation =====
            Write-Log "[Connect-adPEAS] Validating connection..."

            # Test connection with a simple query
            $TestQuery = Invoke-LDAPSearch -Filter "(objectClass=domain)" -SearchBase $Connection.DomainDN -Properties "name" -Scope Base

            if (-not $TestQuery) {
                throw "Connection validation failed - could not query domain object"
            }

            # ===== Store Auth Info in LDAPContext =====
            # Add auth info to the LDAPContext for display by Get-adPEASSession
            $Script:LDAPContext['AuthMethod'] = $Script:AuthInfo.Method
            $Script:LDAPContext['KerberosUsed'] = $Script:AuthInfo.KerberosUsed
            $Script:LDAPContext['TGTInfo'] = $Script:AuthInfo.TGTInfo
            $Script:LDAPContext['ParameterSet'] = $Script:AuthInfo.ParameterSet
            $Script:LDAPContext['SessionStartTime'] = Get-Date

            # Store authenticated username for reports (use LDAP-verified identity)
            if ($Connection.AuthenticatedUser) {
                $Script:LDAPContext['Username'] = $Connection.AuthenticatedUser
            }
            elseif ($Connection.Credential) {
                $Script:LDAPContext['Username'] = $Connection.Credential.UserName
            }
            elseif ($Username) {
                # For hash/key-based auth where username was provided
                $Script:LDAPContext['Username'] = $Username
            }

            # Store Domain SID (already retrieved by Connect-LDAP)
            if ($Connection.DomainSID) {
                $Script:LDAPContext['DomainSID'] = $Connection.DomainSID
                Write-Log "[Connect-adPEAS] Domain SID: $($Connection.DomainSID)"
            }

            # Store Credential in LDAPContext for later use
            if (-not $Script:LDAPContext['Credential']) {
                if ($CredObject) {
                    $Script:LDAPContext['Credential'] = $CredObject
                    Write-Log "[Connect-adPEAS] Stored credential in LDAPContext for later use"
                }
                elseif ($Credential) {
                    $Script:LDAPContext['Credential'] = $Credential
                    Write-Log "[Connect-adPEAS] Stored credential in LDAPContext for later use"
                }
            }

            # Store Certificate in LDAPContext for session reuse by Invoke-adPEAS
            if ($Certificate) {
                $Script:LDAPContext['Certificate'] = $Certificate
                if ($CertificatePassword) {
                    $Script:LDAPContext['CertificatePassword'] = $CertificatePassword
                }
                if ($ForcePassTheCert) {
                    $Script:LDAPContext['ForcePassTheCert'] = $true
                }
                Write-Log "[Connect-adPEAS] Stored certificate in LDAPContext for later use"
            }

            # ===== Hosts File Patching (if custom DNS and PatchHostsFile, and not already done early) =====
            if ($Script:LDAPContext['PatchHostsFile'] -and $Script:LDAPContext['DnsServer'] -and -not $Script:LDAPContext['EarlyHostsPatched']) {
                # This code path is for cases where early patching didn't happen (shouldn't occur with current logic)
                Write-Log "[Connect-adPEAS] Late hosts file patching (fallback)..."

                $hostsPatched = @()

                # Patch domain name -> DC IP
                if ($Connection.Server -and $Script:LDAPContext['DnsCache']) {
                    # Get the DC hostname from the connection
                    $dcHostname = $Connection.Server
                    # Use lowercase key for case-insensitive cache lookup
                    $dcHostnameLowerForPatch = $dcHostname.ToLower()

                    # Try to get IP from cache or resolve it
                    $dcIP = $null
                    if ($Script:LDAPContext['DnsCache'].ContainsKey($dcHostnameLowerForPatch)) {
                        $dcIP = $Script:LDAPContext['DnsCache'][$dcHostnameLowerForPatch]
                    }
                    else {
                        # Try to resolve using custom DNS
                        $dcIP = Resolve-adPEASName -Name $dcHostname
                    }

                    if ($dcIP) {
                        # Patch DC hostname
                        $patchResult = Add-adPEASHostsEntry -IPAddress $dcIP -Hostname $dcHostname -Force
                        if ($patchResult.Success) {
                            $hostsPatched += $dcHostname
                            Write-Log "[Connect-adPEAS] Added hosts entry: $dcIP -> $dcHostname"
                        }

                        # Also patch domain name if different from DC hostname
                        if ($Domain -ne $dcHostname) {
                            $patchResult = Add-adPEASHostsEntry -IPAddress $dcIP -Hostname $Domain -Force
                            if ($patchResult.Success) {
                                $hostsPatched += $Domain
                                Write-Log "[Connect-adPEAS] Added hosts entry: $dcIP -> $Domain"
                            }
                        }
                    }
                }

                # Store patched hosts for cleanup
                $Script:LDAPContext['HostsEntries'] = $hostsPatched

                if ($hostsPatched.Count -gt 0) {
                    Show-Line "Patched hosts file with $($hostsPatched.Count) entries (cleanup on Disconnect-adPEAS)" -Class Info
                }
            }
            elseif ($Script:LDAPContext['EarlyHostsPatched'] -and $Connection.Server) {
                # Early patching was done, but we may need to add the actual DC hostname if it differs
                # from what we patched early (we patched -Server, but Connect-LDAP may have resolved to different hostname)
                $dcHostname = $Connection.Server
                $alreadyPatched = $Script:LDAPContext['HostsEntries'] -contains $dcHostname

                if (-not $alreadyPatched) {
                    $dcHostnameLower = $dcHostname.ToLower()
                    $dcIP = $null

                    if ($Script:LDAPContext['DnsCache'] -and $Script:LDAPContext['DnsCache'].ContainsKey($dcHostnameLower)) {
                        $dcIP = $Script:LDAPContext['DnsCache'][$dcHostnameLower]
                    }
                    elseif ($Script:LDAPContext['ServerIP']) {
                        $dcIP = $Script:LDAPContext['ServerIP']
                    }

                    if ($dcIP) {
                        $patchResult = Add-adPEASHostsEntry -IPAddress $dcIP -Hostname $dcHostname -Force
                        if ($patchResult.Success) {
                            $Script:LDAPContext['HostsEntries'] += $dcHostname
                            Write-Log "[Connect-adPEAS] Added additional hosts entry: $dcIP -> $dcHostname"
                        }
                    }
                }
            }

            # Store resolved DC IP for SMB access (even without hosts patching)
            if ($Script:LDAPContext['DnsServer'] -and $Connection.Server) {
                $dcHostname = $Connection.Server
                # Normalize to lowercase for case-insensitive cache lookup
                $dcHostnameLower = $dcHostname.ToLower()
                $domainLower = $Domain.ToLower()
                $dcIP = $null

                Write-Log "[Connect-adPEAS] Looking up DC IP for: $dcHostname (normalized: $dcHostnameLower)"

                # Try multiple sources for the DC IP
                # Source 1: Check if DC hostname is directly in cache (case-insensitive)
                if ($Script:LDAPContext['DnsCache'] -and $Script:LDAPContext['DnsCache'].ContainsKey($dcHostnameLower)) {
                    $dcIP = $Script:LDAPContext['DnsCache'][$dcHostnameLower]
                    Write-Log "[Connect-adPEAS] Found DC IP in DnsCache: $dcIP"
                }
                # Source 2: Check if domain name is in cache (DC IP is same as domain IP)
                elseif ($Script:LDAPContext['DnsCache'] -and $Script:LDAPContext['DnsCache'].ContainsKey($domainLower)) {
                    $dcIP = $Script:LDAPContext['DnsCache'][$domainLower]
                    Write-Log "[Connect-adPEAS] Using domain IP as DC IP: $dcIP"
                    # Also cache the DC hostname -> IP mapping for future use (lowercase key)
                    $Script:LDAPContext['DnsCache'][$dcHostnameLower] = $dcIP
                }
                # Source 3: Resolve DC hostname via custom DNS
                else {
                    Write-Log "[Connect-adPEAS] Resolving DC hostname via custom DNS: $dcHostname"
                    $dcIP = Resolve-adPEASName -Name $dcHostname -DnsServer $Script:LDAPContext['DnsServer']
                    if ($dcIP) {
                        Write-Log "[Connect-adPEAS] Resolved DC IP: $dcIP"
                    }
                    else {
                        Write-Log "[Connect-adPEAS] WARNING: Could not resolve DC hostname $dcHostname"
                    }
                }

                if ($dcIP) {
                    $Script:LDAPContext['ServerIP'] = $dcIP
                    Write-Log "[Connect-adPEAS] Stored DC IP for SMB access: $($Script:LDAPContext['ServerIP'])"
                }
            }

            # ===== Success Output (Verbose) =====
            Write-Log "[Connect-adPEAS] CONNECTION SUCCESSFUL"
            Write-Log "[Connect-adPEAS] Domain: $($Connection.Domain)"
            Write-Log "[Connect-adPEAS] Server: $($Connection.Server)"
            Write-Log "[Connect-adPEAS] Protocol: $($Connection.Protocol) (Port $($Connection.Port))"

            # Display authenticated user (LDAP-verified if available)
            if ($Connection.AuthenticatedUser) {
                # LDAP-verified identity
                Write-Log "[Connect-adPEAS] Authenticated as: $($Connection.AuthenticatedUser)"

                # Show identity mismatch warning if detected
                if ($Connection.IdentityMismatch) {
                    Write-Warning "[Connect-adPEAS] Identity Mismatch Detected (see warning above)"
                }
            }
            else {
                # Fallback if LDAP verification failed
                if ($Connection.Credential) {
                    $DisplayUser = $Connection.Credential.UserName
                }
                elseif ($AuthMethod -eq 'Certificate' -and $ForcePassTheCert) {
                    $DisplayUser = "Certificate-based (Pass-the-Cert)"
                }
                elseif ($AuthMethod -eq 'Certificate') {
                    $DisplayUser = "Certificate-based (PKINIT)"
                }
                elseif ($AuthMethod -in @('NTHash', 'AES256', 'AES128')) {
                    $DisplayUser = "$Username (Hash/Key-based)"
                }
                elseif ($AuthMethod -in @('Kirbi', 'Ccache')) {
                    $DisplayUser = "Ticket-based (PTT)"
                }
                else {
                    $DisplayUser = "$env:USERDOMAIN\$env:USERNAME"
                }
                Write-Log "[Connect-adPEAS] Authenticated as: $DisplayUser"
            }

            # Functional Level Info
            $FLMapping = @{
                0 = "Windows 2000"
                1 = "Windows 2003 Interim"
                2 = "Windows 2003"
                3 = "Windows 2008"
                4 = "Windows 2008 R2"
                5 = "Windows 2012"
                6 = "Windows 2012 R2"
                7 = "Windows 2016"
                10 = "Windows 2025"
            }
            $DomainFL = $FLMapping[[int]$Connection.DomainFunctionality]
            Write-Log "[Connect-adPEAS] Domain Functional Level: $DomainFL"

            # Build tab-completion cache if requested
            if ($BuildCompletionCache) {
                Show-EmptyLine
                Show-Line "Building tab-completion cache..." -Class Info
                Build-CompletionCache
                $stats = Get-CompletionCacheStats
                Show-Line "Cached: $($stats.Users) users, $($stats.Computers) computers, $($stats.Groups) groups, $($stats.GPOs) GPOs" -Class Hint
            }

            if (-not $Quiet) {
                Get-adPEASSession
                return
            }
            else {
                return $Connection
            }

        }
        catch {
            # Display error to user if not already shown via Show-ConnectionError
            $ErrorDetail = $_.Exception.Message
            Write-Log "[Connect-adPEAS] Connection failed: $ErrorDetail"
            Write-Log "[Connect-adPEAS] ConnectionState: $Script:ConnectionState"

            # Show error to user (Show-ConnectionError may not have been called for all error types)
            Show-ConnectionError -ErrorType "GenericError" -Details $ErrorDetail -NoThrow
            return $null
        }
    }

    end {
        if ($Script:LdapConnection) {
            Write-Log "[Connect-adPEAS] Authentication process completed"
        }
    }
}



# ----- Disconnect-adPEAS.ps1 -----

function Disconnect-adPEAS {
<#
.SYNOPSIS
    Terminates the current adPEAS session and cleans up resources.

.DESCRIPTION
    Closes the current LDAP connection, disposes connection objects and clears all global session variables and caches.

    This function:
    - Reverts NTLM impersonation if active (RevertToSelf + CloseHandle)
    - Disposes $Script:LdapConnection (System.DirectoryServices.Protocols.LdapConnection)
    - Disposes $Script:GCConnection (Global Catalog connection for cross-domain SID resolution)
    - Clears all session state variables ($Script:LDAPContext, $Script:LDAPCredential, $Script:ConnectionState, etc.)
    - Clears all session caches (SID resolution, privileged check, completion, SMB, LAPS, etc.)
    - Removes hosts file entries added by Connect-adPEAS (requires Admin)

.PARAMETER Force
    Forces disconnect even if errors occur during cleanup.

.EXAMPLE
    Disconnect-adPEAS
    Terminates the current session cleanly.

.EXAMPLE
    Disconnect-adPEAS -Force
    Forces disconnect even with cleanup errors.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [switch]$Force
    )

    begin {
        # Helper: Safe dispose of IDisposable objects (LdapConnection, etc.)
        function Invoke-SafeDispose {
            param(
                [Parameter(Mandatory)]
                [string]$Name,
                [Parameter(Mandatory)]
                [AllowNull()]
                $Object
            )
            if (-not $Object) { return $null }
            try {
                Write-Log "[Disconnect-adPEAS] Disposing $Name..."
                $Object.Dispose()
                Write-Log "[Disconnect-adPEAS] $Name disposed successfully"
                return $null
            }
            catch {
                if ($_.Exception.InnerException -is [System.ObjectDisposedException] -or
                    $_.Exception -is [System.ObjectDisposedException]) {
                    Write-Log "[Disconnect-adPEAS] $Name already disposed - continuing cleanup"
                    return $null
                }
                Write-Log "[Disconnect-adPEAS] Error disposing ${Name}: $_"
                return "$Name disposal failed: $_"
            }
        }
    }

    process {
        try {
            # Check if a real session exists (LDAPContext with Domain set, or active connection)
            $hasSession = ($Script:LDAPContext -and $Script:LDAPContext['Domain']) -or $Script:LdapConnection
            if (-not $hasSession) {
                Show-NoSessionError -Context "Disconnect-adPEAS"
                # Still clean up any partial state (e.g. empty LDAPContext from failed connect)
                if ($Script:LDAPContext) { Clear-SessionState }
                return
            }

            # Display current session before disconnect
            Show-SubHeader "Disconnecting session..."

            if ($Script:LDAPContext -and $Script:LDAPContext['Domain']) {
                Show-Line "Current Session:" -Class Hint
                Show-KeyValue "Domain:" $Script:LDAPContext.Domain
                # Display authenticated user
                if ($Script:LDAPContext.AuthenticatedUser) {
                    Show-KeyValue "Authenticated as:" $Script:LDAPContext.AuthenticatedUser
                } elseif ($Script:LDAPContext.Credential) {
                    Show-KeyValue "Authenticated as:" $Script:LDAPContext.Credential.UserName
                } else {
                    Show-KeyValue "Authenticated as:" "$env:USERDOMAIN\$env:USERNAME"
                }

                # Calculate session duration if available
                if ($Script:LDAPContext.SessionStartTime) {
                    $sessionDuration = (Get-Date) - $Script:LDAPContext.SessionStartTime
                    Show-KeyValue "Session Duration:" $sessionDuration.ToString('hh\:mm\:ss')
                }
            }

            $cleanupErrors = @()

            # Step 1: Revert NTLM impersonation (MUST be done BEFORE disposing connections)
            if ($Script:NTLMTokenHandle -and $Script:NTLMTokenHandle -ne [IntPtr]::Zero) {
                Write-Log "[Disconnect-adPEAS] Reverting NTLM impersonation..."
                try {
                    Invoke-RevertToSelf -TokenHandle $Script:NTLMTokenHandle
                    Write-Log "[Disconnect-adPEAS] NTLM impersonation reverted successfully"
                    Show-KeyValue "NTLM Impersonation:" "Reverted to original context"
                }
                catch {
                    $cleanupErrors += "NTLM revert failed: $_"
                    Write-Log "[Disconnect-adPEAS] Error reverting NTLM impersonation: $_"
                    if (-not $Force) {
                        Write-Warning "[Disconnect-adPEAS] Failed to revert NTLM impersonation: $_"
                    }
                }
                $Script:NTLMTokenHandle = [IntPtr]::Zero
            }

            # Step 2: Dispose connections
            $err = Invoke-SafeDispose -Name "LdapConnection" -Object $Script:LdapConnection
            if ($err) { $cleanupErrors += $err }

            $err = Invoke-SafeDispose -Name "GCConnection" -Object $Script:GCConnection
            if ($err) { $cleanupErrors += $err }

            # Step 3: Clean up hosts file entries (if patched during connect)
            if ($Script:LDAPContext -and $Script:LDAPContext['HostsEntries'] -and $Script:LDAPContext['HostsEntries'].Count -gt 0) {
                Write-Log "[Disconnect-adPEAS] Cleaning up hosts file entries..."
                try {
                    $hostsResult = Remove-adPEASHostsEntry
                    if ($hostsResult.Success -and $hostsResult.RemovedCount -gt 0) {
                        Write-Log "[Disconnect-adPEAS] Removed $($hostsResult.RemovedCount) hosts file entries"
                        Show-KeyValue "Hosts File:" "Cleaned ($($hostsResult.RemovedCount) entries removed)"
                    }
                    elseif ($hostsResult.RequiresElevation) {
                        Write-Warning "[Disconnect-adPEAS] Cannot clean hosts file - Administrator privileges required"
                        Write-Warning "[Disconnect-adPEAS] Manually remove adPEAS entries from: $env:SystemRoot\System32\drivers\etc\hosts"
                        Show-KeyValue "Hosts File:" "Cleanup requires Admin (manual removal needed)" -Class Hint
                    }
                }
                catch {
                    $cleanupErrors += "Hosts file cleanup failed: $_"
                    Write-Log "[Disconnect-adPEAS] Error cleaning hosts file: $_"
                    if (-not $Force) {
                        Write-Warning "[Disconnect-adPEAS] Hosts file cleanup failed: $_"
                    }
                }
            }

            # Step 4: Clear all session variables and caches
            Clear-SessionState
            Write-Log "[Disconnect-adPEAS] All session variables and caches cleared"

            # Success output
            Show-EmptyLine
            Show-Line "Cleanup:" -Class Hint
            Show-KeyValue "Connection:" "Closed" -Class Note
            Show-KeyValue "Variables:" "Cleared" -Class Note
            Show-EmptyLine

            if ($cleanupErrors.Count -gt 0 -and $Force) {
                Show-Line "Cleanup errors (forced disconnect):" -Class Hint
                foreach ($err in $cleanupErrors) {
                    Show-Line "- $err"
                }
            }
        }
        catch {
            # Use centralized error message
            Show-DisconnectError -ErrorMessage $_.Exception.Message

            # If Force is specified, clear variables anyway
            if ($Force) {
                Show-Line "Force mode enabled - clearing variables anyway..." -Class Hint
                # Revert NTLM impersonation even in force mode
                if ($Script:NTLMTokenHandle -and $Script:NTLMTokenHandle -ne [IntPtr]::Zero) {
                    try { Invoke-RevertToSelf -TokenHandle $Script:NTLMTokenHandle } catch {}
                    $Script:NTLMTokenHandle = [IntPtr]::Zero
                }
                # Dispose connections silently
                try { if ($Script:LdapConnection) { $Script:LdapConnection.Dispose() } } catch {}
                try { if ($Script:GCConnection) { $Script:GCConnection.Dispose() } } catch {}
                # Clear all state
                Clear-SessionState
                Show-Line "Session variables and caches force-cleared" -Class Note
            }
        }
    }
}

function Clear-SessionState {
    <#
    .SYNOPSIS
        Clears all session-specific $Script: variables and caches.
    .DESCRIPTION
        Internal helper used by Disconnect-adPEAS (normal and force path).
        Only clears session state - does NOT dispose connections or revert impersonation.
    #>

    # Connection references (already disposed at this point)
    $Script:LdapConnection = $null
    $Script:GCConnection = $null

    # Core session state
    $Script:LDAPContext = $null
    $Script:LDAPCredential = $null
    $Script:ConnectionState = $null
    $Script:LastLDAPErrorCode = $null
    $Script:LastLDAPErrorDetails = $null
    $Script:AuthInfo = $null
    $Script:NTLMTokenHandle = [IntPtr]::Zero

    # Anonymous access detection (Connect-LDAP)
    $Script:AnonymousAccessEnabled = $null
    $Script:AnonymousAccessDetails = $null

    # License (runtime-provided via -License parameter)
    $Script:RuntimeLicense = $null
    $Script:adPEASDisclaimer = $null

    # Kerberos ticket metadata
    $Script:KirbiMetadata = $null
    $Script:CcacheMetadata = $null

    # SID resolution caches (ConvertFrom-SID / ConvertTo-SID)
    $Script:SIDResolutionCache = @{}
    $Script:SIDVerboseCache = @{}
    $Script:NameToSIDCache = @{}

    # Privileged check cache (Test-IsPrivileged)
    $Script:PrivilegedCheckCache = @{}
    $Script:GroupMembershipCache = @{}

    # Token groups cache (Get-CurrentUserTokenGroups)
    $Script:CurrentUserTokenGroups = $null

    # Foreign domain cache (ConvertFrom-SID)
    $Script:ForeignDomainCache = @{}

    # Collector caches (Invoke-adPEASCollector) - MUST be reset to $null, not @{}.
    # These are lazy-built and their build guards use "if ($cache) { return }". An empty @{} is
    # TRUTHY, so resetting to @{} makes the next collection skip rebuilding and run with an empty
    # cache - group memberships and OU/container children come out empty, and the sibling
    # ParentDNToChildren (previously omitted here entirely) stays $null and crashes Collect-BHOUs
    # with "cannot call a method on a null-valued expression". Reset the full set the collector's
    # end{} block clears, so "null means not built" holds after a disconnect/reconnect.
    $Script:ComputerHostnameCache = $null
    $Script:DNToIdentityCache = $null
    $Script:ParentDNToChildren = $null
    $Script:ConfigContainerGuidCache = $null
    $Script:TemplateCNToOID = $null

    # Tab-completion cache (Register-adPEASCompleters)
    if ($Script:CompletionCache) { Clear-CompletionCache }
    $Script:CompletionCacheAttempted = $null

    # SMB share access cache (Invoke-SMBAccess)
    if ($Script:SMBShareAccessCache -and $Script:SMBShareAccessCache.Count -gt 0) {
        Reset-SMBShareAccessCache
    } else {
        $Script:SMBShareAccessCache = @{}
    }

    # SYSVOL file listing cache
    if ($null -ne $Script:SYSVOLFileCache) {
        Reset-SYSVOLFileCache
    }

    # SYSVOL content cache (on-demand file content, e.g., GptTmpl.inf)
    $Script:SYSVOLContentCache = $null

    # Findings collection (adPEAS-Messages / HTML export)
    $Script:adPEAS_FindingsCollection = $null
    $Script:adPEAS_FindingsCollectionEnabled = $false
    $Script:adPEAS_CurrentCheckContext = $null

    # LDAP Statistics tracking (set by Invoke-adPEAS -Statistics)
    $Script:LDAPStatistics = $null

    # Runtime configuration (set by Invoke-adPEAS)
    $Script:DefaultInactiveDays = $null
    $Script:IncludePrivilegedMode = $null
    $Script:adPEAS_OutputColor = $true
    $Script:adPEAS_VerboseLogging = $false
    $Script:ModuleCategoryHeaders = $null

    # Output file (set by Invoke-adPEAS -Outputfile)
    $Script:adPEAS_Outputfile = $null
    $Script:HTMLOutputPath = $null
    $Script:JSONOutputPath = $null

    # ACE Inheritance source cache (parent ACL cache for Get-OUPermissions)
    $Script:InheritanceACLCache = $null

    # Exchange service group check cache (Test-IsExchangeServiceGroup)
    $Script:ExchangeGroupCache = $null

    # OU Permissions result cache (cross-module: DangerousOU, LAPS, PasswordReset)
    $Script:OUPermissionsCache = $null

    # Check module caches
    $Script:LAPSSchemaInfo = $null
    $Script:BitLockerSchemaInfo = $null
    $Script:lapsGPOResults = $null
    $Script:AllForeignMembers = $null
    $Script:PrivilegedGroupSIDs = $null
    $Script:PrivilegedGroupRIDs = $null
    $Script:DynamicPrivilegedGroups = $null
    $Script:FilterAccountExpired = $null

    # GPO caches (Get-DomainGPO and Get-GPOLinkage)
    $Script:CachedAllGPOs = $null
    $Script:CachedGPOLinkage = $null

    # Collector metadata (Invoke-adPEASCollector)
    $Script:CollectorVersion = $null
    $Script:JsonVersion = $null
    $Script:CollectionTimestamp = $null
    $Script:CollectedParts = $null
    $Script:ProgressPadWidth = $null
    $Script:CursorUp = $null
    $Script:CursorDown = $null
    $Script:WriteCollectionStatus = $null
}



# ----- Invoke-LDAPSearch.ps1 -----

<#
.SYNOPSIS
    Performs LDAP searches using System.DirectoryServices.Protocols.LdapConnection.

.DESCRIPTION
    Central search function for all LDAP queries.
    Uses LdapConnection for efficient AD queries (works for both LDAP and LDAPS).

    Features:
    - Server-side LDAP filters
    - Paging for large result sets
    - Attribute selection for performance
    - Scope control (Base, OneLevel, Subtree)

.PARAMETER Filter
    LDAP filter string (e.g. "(&(objectClass=user)(adminCount=1))")

.PARAMETER SearchBase
    Distinguished Name as search base.
    Optional - Default: Domain DN from $Script:LDAPContext

.PARAMETER Properties
    Array of attribute names to load.
    Optional - Default: All attributes

.PARAMETER Scope
    Search scope: Base, OneLevel, Subtree
    Default: Subtree

.PARAMETER PageSize
    Page size for paging (performance for large result sets)
    Default: 1000

.PARAMETER SizeLimit
    Maximum number of results (0 = unlimited)
    Default: 0

.PARAMETER Raw
    Switch to return raw LDAP values without any conversions.
    When specified, all attribute conversions are skipped:
    - objectSid remains as byte array (not converted to string)
    - userAccountControl remains as Int32 (not converted to flag array)
    - DateTime attributes remain as Int64 (not converted to DateTime)
    - etc.
    Use this for performance when programmatically processing results.

.PARAMETER CountOnly
    Switch to return only the count of matching objects without collecting or converting them.
    Significantly reduces memory usage and processing time for large result sets
    where only the total number of matches is needed.
    Returns an integer instead of an array of PSCustomObjects.

.EXAMPLE
    Invoke-LDAPSearch -Filter "(&(objectClass=user)(adminCount=1))"
    Searches all users with adminCount=1

.EXAMPLE
    Invoke-LDAPSearch -Filter "(objectClass=group)" -Properties "sAMAccountName","member"
    Searches groups and loads only specific attributes

.EXAMPLE
    Invoke-LDAPSearch -Filter "(objectClass=user)" -Raw
    Searches users and returns raw LDAP values without conversions (faster for programmatic use)

.EXAMPLE
    Invoke-LDAPSearch -Filter "(&(objectClass=computer)(servicePrincipalName=CmRcService/*))" -CountOnly
    Returns only the count of matching computers without loading any object data

.OUTPUTS
    Array of PSCustomObjects with found AD objects

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Invoke-LDAPSearch {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Filter,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [string[]]$AdditionalProperties,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Base", "OneLevel", "Subtree")]
        [string]$Scope = "Subtree",

        [Parameter(Mandatory=$false)]
        [int]$PageSize = 1000,

        [Parameter(Mandatory=$false)]
        [int]$SizeLimit = 0,

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        [Parameter(Mandatory=$false)]
        [switch]$CountOnly,

        [Parameter(Mandatory=$false)]
        [System.DirectoryServices.Protocols.LdapConnection]$LdapConnection
    )

    begin {
        Write-Log "[Invoke-LDAPSearch] Filter: $Filter"

        # Use provided connection or fall back to script-scope connection
        $ActiveConnection = if ($LdapConnection) { $LdapConnection } else { $Script:LdapConnection }

        if (-not $ActiveConnection) {
            throw "No LDAP connection available. Please run Connect-adPEAS first."
        }

        Write-Log "[Invoke-LDAPSearch] Using System.DirectoryServices.Protocols.LdapConnection"
    }

    process {
        # Helper: Convert X.509 certificate bytes to structured object
        function Convert-CertificateToInfo {
            param([byte[]]$CertBytes)
            try {
                $Cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList @(,$CertBytes)

                # Extract Subject CN
                $SubjectCN = if ($Cert.Subject -match 'CN=([^,]+)') { $Matches[1] } else { $Cert.Subject }

                # Extract Issuer CN
                $IssuerCN = if ($Cert.Issuer -match 'CN=([^,]+)') { $Matches[1] } else { $Cert.Issuer }

                # Determine certificate status
                $Status = if ((Get-Date) -gt $Cert.NotAfter) { "EXPIRED" }
                          elseif ((Get-Date) -lt $Cert.NotBefore) { "Not yet valid" }
                          else { "Valid" }

                # Extract Subject Alternative Name (SAN) - OID 2.5.29.17
                $SAN = $null
                $SANExtension = $Cert.Extensions | Where-Object { $_.Oid.Value -eq "2.5.29.17" }
                if ($SANExtension) {
                    # Format the SAN for display
                    $SANFormatted = $SANExtension.Format($false)
                    if ($SANFormatted) {
                        $SAN = $SANFormatted
                    }
                }

                # Extract Enhanced Key Usage (EKU)
                $EKU = $null
                $EKUExtension = $Cert.Extensions | Where-Object { $_ -is [System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension] }
                if ($EKUExtension) {
                    $EKUList = @()
                    foreach ($oid in $EKUExtension.EnhancedKeyUsages) {
                        $EKUList += "$($oid.FriendlyName) ($($oid.Value))"
                    }
                    $EKU = $EKUList -join ", "
                }

                # Signature Algorithm (e.g., sha256RSA, sha1RSA)
                $SigAlgo = $Cert.SignatureAlgorithm.FriendlyName

                # Public Key Length
                $KeyLength = 0
                try {
                    if ($Cert.PublicKey -and $Cert.PublicKey.Key) {
                        $KeyLength = $Cert.PublicKey.Key.KeySize
                    }
                } catch {
                    # Some key types may not expose KeySize
                }

                # Basic Constraints (OID 2.5.29.19) - CA flag and path length
                $HasBasicConstraints = $false
                $BasicConstraintsPathLength = 0
                $bcExt = $Cert.Extensions | Where-Object { $_.Oid.Value -eq '2.5.29.19' }
                if ($bcExt) {
                    $HasBasicConstraints = $true
                    try {
                        $bcTyped = [System.Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]$bcExt
                        if ($bcTyped.HasPathLengthConstraint) {
                            $BasicConstraintsPathLength = $bcTyped.PathLengthConstraint
                        }
                    } catch { }
                }

                # CRL Distribution Points (OID 2.5.29.31)
                $CRLDistributionPoints = @()
                $crlExt = $Cert.Extensions | Where-Object { $_.Oid.Value -eq '2.5.29.31' }
                if ($crlExt) {
                    try {
                        # Format() returns a multi-line string like:
                        # "Distribution Point\r\n  Full Name:\r\n    URL=http://..."
                        $crlFormatted = $crlExt.Format($false)
                        # Extract http(s):// and ldap:// URLs
                        $CRLDistributionPoints = @([regex]::Matches($crlFormatted, 'https?://[^\s,]+|ldap://[^\s,]+') | ForEach-Object { $_.Value })
                    } catch { }
                }

                # Authority Information Access (OID 1.3.6.1.5.5.7.1.1) - OCSP and CA Issuer URLs
                $OCSPURLs = @()
                $AIAURLs = @()
                $aiaExt = $Cert.Extensions | Where-Object { $_.Oid.Value -eq '1.3.6.1.5.5.7.1.1' }
                if ($aiaExt) {
                    try {
                        # Format() returns a string like:
                        # "Access Method=On-line Certificate Status Protocol (1.3.6.1.5.5.7.48.1)\r\nAlternative Name:\r\n  URL=http://ocsp...."
                        # "Access Method=Certification Authority Issuer (1.3.6.1.5.5.7.48.2)\r\nAlternative Name:\r\n  URL=http://..."
                        $aiaFormatted = $aiaExt.Format($false)
                        # Split into per-entry blocks by splitting on Access Method lines
                        # Process each URL with its preceding context
                        $lines = $aiaFormatted -split '\r?\n'
                        $currentIsOCSP = $false
                        $currentIsCAIssuer = $false
                        foreach ($line in $lines) {
                            if ($line -match '1\.3\.6\.1\.5\.5\.7\.48\.1') { $currentIsOCSP = $true; $currentIsCAIssuer = $false }
                            elseif ($line -match '1\.3\.6\.1\.5\.5\.7\.48\.2') { $currentIsOCSP = $false; $currentIsCAIssuer = $true }
                            elseif ($line -match '^\s*URL=(https?://[^\s]+|ldap://[^\s]+)') {
                                $url = $Matches[1]
                                if ($currentIsOCSP) { $OCSPURLs += $url }
                                elseif ($currentIsCAIssuer) { $AIAURLs += $url }
                            }
                        }
                    } catch { }
                }

                $CertInfo = [PSCustomObject]@{
                    Subject      = $SubjectCN
                    SubjectFull  = $Cert.Subject
                    Issuer       = $IssuerCN
                    IssuerFull   = $Cert.Issuer
                    SerialNumber = $Cert.SerialNumber
                    NotBefore    = $Cert.NotBefore
                    NotAfter     = $Cert.NotAfter
                    Status       = $Status
                    Thumbprint   = $Cert.Thumbprint
                    SAN          = $SAN
                    EKU          = $EKU
                    SignatureAlgorithm      = $SigAlgo
                    PublicKeyLength         = $KeyLength
                    HasBasicConstraints     = $HasBasicConstraints
                    BasicConstraintsPathLength = $BasicConstraintsPathLength
                    CRLDistributionPoints   = $CRLDistributionPoints
                    OCSPURLs                = $OCSPURLs
                    AIAURLs                 = $AIAURLs
                }

                $Cert.Dispose()
                return $CertInfo
            } catch {
                # Return error object if certificate parsing fails
                return [PSCustomObject]@{
                    Subject      = "[Invalid Certificate]"
                    SubjectFull  = $null
                    Issuer       = $null
                    IssuerFull   = $null
                    SerialNumber = $null
                    NotBefore    = $null
                    NotAfter     = $null
                    Status       = "Parse Error"
                    Thumbprint   = $null
                    SAN          = $null
                    EKU          = $null
                    SignatureAlgorithm      = $null
                    PublicKeyLength         = 0
                    HasBasicConstraints     = $false
                    BasicConstraintsPathLength = 0
                    CRLDistributionPoints   = @()
                    OCSPURLs                = @()
                    AIAURLs                 = @()
                    ErrorInfo    = if ($CertBytes.Length -gt 0) { "$($CertBytes.Length) bytes" } else { "Empty" }
                }
            }
        }

        # Helper: Convert KeyCredentialLink to readable info
        # msDS-KeyCredentialLink is a DNWithBinary attribute: B:Length:HexData:DN
        # Uses ConvertFrom-KeyCredentialLink helper for full LTV parsing
        function Convert-KeyCredentialToInfo {
            param($KeyCredValue)

            try {
                # Handle string format (DNWithBinary)
                if ($KeyCredValue -is [string]) {
                    # Format: B:Length:HexData:DN
                    if ($KeyCredValue -match '^B:(\d+):([0-9A-Fa-f]+)(?::(.+))?$') {
                        # Use the full parser to extract DeviceID, CreationTime, etc.
                        return ConvertFrom-KeyCredentialLink -DNWithBinary $KeyCredValue
                    }
                    # Return as-is if not matching DNWithBinary format
                    return $KeyCredValue
                }

                # Handle byte array (raw binary)
                if ($KeyCredValue -is [byte[]]) {
                    return ConvertFrom-KeyCredentialLink -KeyCredentialBytes $KeyCredValue
                }

                # Handle COM objects (IADsDNWithBinary) from DirectoryServices
                # COM interop requires using GetType().InvokeMember() for property access
                if ($KeyCredValue -and $KeyCredValue.GetType().IsCOMObject) {
                    try {
                        # Use COM Reflection to access BinaryValue property
                        $binaryValue = $KeyCredValue.GetType().InvokeMember(
                            'BinaryValue',
                            [System.Reflection.BindingFlags]::GetProperty,
                            $null,
                            $KeyCredValue,
                            $null
                        )
                        if ($binaryValue -is [byte[]]) {
                            return ConvertFrom-KeyCredentialLink -KeyCredentialBytes $binaryValue
                        }
                    } catch {
                        # COM reflection failed, try direct access
                    }
                }

                # Method 2: Try direct property access (works for some COM wrappers)
                if ($KeyCredValue.PSObject.Properties['DNString'] -and $KeyCredValue.PSObject.Properties['BinaryValue']) {
                    $binaryValue = $KeyCredValue.BinaryValue
                    if ($binaryValue -is [byte[]]) {
                        return ConvertFrom-KeyCredentialLink -KeyCredentialBytes $binaryValue
                    }
                }

                # Try converting to string and parsing as DNWithBinary
                $strValue = $KeyCredValue.ToString()
                if ($strValue -match '^B:(\d+):([0-9A-Fa-f]+)(?::(.+))?$') {
                    return ConvertFrom-KeyCredentialLink -DNWithBinary $strValue
                }

                return "KeyCredential (unknown format)"
            } catch {
                return "[KeyCredential - parse error: $($_.Exception.Message)]"
            }
        }

        # Helper: Convert SID byte array to string
        function Convert-SIDToString {
            param([byte[]]$SIDBytes)
            try {
                return (New-Object System.Security.Principal.SecurityIdentifier($SIDBytes, 0)).Value
            } catch {
                return $null
            }
        }

        try {
            # Determine SearchBase
            if ([string]::IsNullOrEmpty($SearchBase)) {
                if ($LdapConnection) {
                    # External connection (e.g. GC): use empty SearchBase for forest-wide search (default)
                    $SearchBase = ""
                    Write-Log "[Invoke-LDAPSearch] Using empty SearchBase for external connection (forest-wide)"
                } else {
                    $SearchBase = $Script:LDAPContext.DomainDN
                    Write-Log "[Invoke-LDAPSearch] Using domain DN as SearchBase: $SearchBase"
                }
            } else {
                # SearchBase was explicitly provided - use it
                Write-Log "[Invoke-LDAPSearch] Using explicit SearchBase: $SearchBase"
            }

            # Convert results to PSCustomObjects
            $OutputObjects = [System.Collections.ArrayList]@()

            Write-Log "[Invoke-LDAPSearch] Using LdapConnection for search"

            # Map scope
            $ProtocolScope = switch ($Scope) {
                "Base"     { [System.DirectoryServices.Protocols.SearchScope]::Base }
                "OneLevel" { [System.DirectoryServices.Protocols.SearchScope]::OneLevel }
                "Subtree"  { [System.DirectoryServices.Protocols.SearchScope]::Subtree }
                default    { [System.DirectoryServices.Protocols.SearchScope]::Subtree }
            }

            # Build attribute list
            # CRITICAL: Pass $null (not @("*")) to SearchRequest when Properties is null
            # On Global Catalog (port 3268), @("*") behaves differently than $null:
            # - $null -> Returns all PAS attributes (correct for GC)
            # - @("*") -> May return DN-only for cross-partition objects (S.DS.P GC quirk)
            $AttributeList = $null

            # CountOnly: force "1.1" (no attributes) to minimize network traffic
            if ($CountOnly) {
                $AttributeList = [string[]]@("1.1")
                Write-Log "[Invoke-LDAPSearch] CountOnly mode: requesting no attributes (1.1)"
            } elseif ($Properties -and $Properties.Count -gt 0) {
                $AttributeList = [string[]]$Properties
                if ($AdditionalProperties) {
                    $AttributeList = [string[]]($Properties + $AdditionalProperties | Select-Object -Unique)
                }
                Write-Log "[Invoke-LDAPSearch] Requesting attributes: $($AttributeList -join ', ')"
            } else {
                # Request all attributes by passing $null (NOT @("*"))
                # $null works correctly on both port 389 and GC port 3268
                $AttributeList = $null
                Write-Log "[Invoke-LDAPSearch] Requesting ALL attributes (null list for GC compatibility)"
            }

            # Create search request
            $SearchRequest = New-Object System.DirectoryServices.Protocols.SearchRequest($SearchBase,$Filter,$ProtocolScope,$AttributeList)

            # Add paging control
            $PageControl = New-Object System.DirectoryServices.Protocols.PageResultRequestControl($PageSize)
            $SearchRequest.Controls.Add($PageControl) | Out-Null

            # Add DomainScope control to prevent phantom results from other domain partitions
            # When the DC is also a Global Catalog, subtree searches can return objects from
            # child domains (phantom objects) even with ReferralChasing=None on the session.
            # SearchOptionsControl with DomainScope tells the DC to only return objects from
            # the domain partition specified by the SearchBase.
            # CRITICAL: Only apply DomainScope to main connection, NOT to external GC connections
            # (GC connections NEED forest-wide results)
            if (-not $LdapConnection) {
                $DomainScopeControl = New-Object System.DirectoryServices.Protocols.SearchOptionsControl(
                    [System.DirectoryServices.Protocols.SearchOption]::DomainScope
                )
                $SearchRequest.Controls.Add($DomainScopeControl) | Out-Null
            }

            # Add SecurityDescriptor control if nTSecurityDescriptor is requested
            $AllRequestedProps = @()
            if ($Properties) { $AllRequestedProps += $Properties }
            if ($AdditionalProperties) { $AllRequestedProps += $AdditionalProperties }

            if ($AllRequestedProps -contains "nTSecurityDescriptor" -or $AttributeList -contains "*") {
                # SecurityDescriptorFlagControl: Owner (1) + Group (2) + DACL (4) = 7
                $SDControl = New-Object System.DirectoryServices.Protocols.SecurityDescriptorFlagControl(
                    [System.DirectoryServices.Protocols.SecurityMasks]::Dacl -bor
                    [System.DirectoryServices.Protocols.SecurityMasks]::Owner -bor
                    [System.DirectoryServices.Protocols.SecurityMasks]::Group
                )
                $SearchRequest.Controls.Add($SDControl) | Out-Null
                Write-Log "[Invoke-LDAPSearch] Added SecurityDescriptorFlagControl for nTSecurityDescriptor"
            }

            # Known binary attributes that need byte[] extraction (defined once, used per-attribute)
            $BinaryAttributeSet = [System.Collections.Generic.HashSet[string]]::new(
                [System.StringComparer]::OrdinalIgnoreCase
            )
            foreach ($ba in @(
                'objectsid', 'objectguid', 'ntsecuritydescriptor', 'sidhistory',
                'msexchmailboxguid', 'msexchmailboxsecuritydescriptor', 'msexchblockedsendershash',
                'msexchsafesendershash', 'msexchmasteraccountsid', 'ms-ds-creatorsid',
                'msds-generationid', 'msds-groupmsamembership', 'msds-managedpasswordid',
                'msds-managedpasswordpreviousid', 'ms-ds-consistencyguid', 'logonhours',
                'msds-allowedtoactonbehalfofotheridentity', 'mslaps-encryptedpassword',
                'mslaps-encryptedpasswordhistory', 'mslaps-encrypteddsconfigurationdata',
                'msfve-recoveryguid', 'msfve-volumeguid',
                'thumbnailphoto', 'jpegphoto', 'usercertificate', 'cacertificate',
                'msds-keyversionnumber', 'repluptodatevector', 'replpropertymeta',
                'pkiexpirationperiod', 'pkioverlapperiod', 'pkikeyusage',
                'extensiondata',
                'msmqdigests', 'msmqsigncertificates',
                'userparameters', 'terminalserver'
            )) { [void]$BinaryAttributeSet.Add($ba) }

            # CountOnly mode: only count matching objects without collecting or converting them
            if ($CountOnly) {
                $TotalCount = 0
                do {
                    $SearchResponse = $ActiveConnection.SendRequest($SearchRequest)

                    # Statistics tracking (CountOnly path)
                    if ($Script:LDAPStatistics) {
                        $Script:LDAPStatistics.TotalQueries++
                        # Base overhead per request/response (~search filter + controls + response header)
                        $Script:LDAPStatistics.TotalEstimatedBytes += 200
                        if ($SearchResponse.Entries) {
                            $Script:LDAPStatistics.TotalResults += $SearchResponse.Entries.Count
                            # CountOnly still returns DNs - estimate ~120 bytes per entry (DN + envelope)
                            $Script:LDAPStatistics.TotalEstimatedBytes += $SearchResponse.Entries.Count * 120
                        }
                    }

                    if ($SearchResponse.Entries) {
                        $TotalCount += $SearchResponse.Entries.Count
                    }

                    # Check for paging response control
                    $PageResponseControl = $null
                    foreach ($ctrl in $SearchResponse.Controls) {
                        if ($ctrl -is [System.DirectoryServices.Protocols.PageResultResponseControl]) {
                            $PageResponseControl = $ctrl
                            break
                        }
                    }

                    if ($PageResponseControl -and $PageResponseControl.Cookie.Length -gt 0) {
                        $PageControl.Cookie = $PageResponseControl.Cookie
                    } else {
                        break
                    }
                } while ($true)

                Write-Log "[Invoke-LDAPSearch] CountOnly: $TotalCount objects matched"
                return $TotalCount
            }

            # Execute paged search
            $AllEntries = [System.Collections.ArrayList]@()
            do {
                $SearchResponse = $ActiveConnection.SendRequest($SearchRequest)

                # Statistics tracking (full search path)
                if ($Script:LDAPStatistics) {
                    $Script:LDAPStatistics.TotalQueries++
                    # Base overhead per request/response (~search filter + controls + response header)
                    $Script:LDAPStatistics.TotalEstimatedBytes += 200
                    if ($SearchResponse.Entries) {
                        $Script:LDAPStatistics.TotalResults += $SearchResponse.Entries.Count
                    }
                }

                if ($SearchResponse.Entries) {
                    [void]$AllEntries.AddRange($SearchResponse.Entries)
                }

                # Check for paging response control
                $PageResponseControl = $null
                foreach ($ctrl in $SearchResponse.Controls) {
                    if ($ctrl -is [System.DirectoryServices.Protocols.PageResultResponseControl]) {
                        $PageResponseControl = $ctrl
                        break
                    }
                }

                if ($PageResponseControl -and $PageResponseControl.Cookie.Length -gt 0) {
                    $PageControl.Cookie = $PageResponseControl.Cookie
                } else {
                    break
                }

                # Check SizeLimit
                if ($SizeLimit -gt 0 -and $AllEntries.Count -ge $SizeLimit) {
                    break
                }

            } while ($true)

            Write-Log "[Invoke-LDAPSearch] Found: $($AllEntries.Count) objects via LdapConnection"

            # Convert LdapConnection results to PSCustomObjects with full attribute conversion
            foreach ($Entry in $AllEntries) {
                $Obj = [PSCustomObject]@{}

                # Add distinguishedName first (use -Force in case it's also in Attributes)
                $Obj | Add-Member -Force -NotePropertyName "distinguishedName" -NotePropertyValue $Entry.DistinguishedName

                # Statistics: count DN bytes per entry (~DN string + LDAP envelope overhead)
                if ($Script:LDAPStatistics -and $Entry.DistinguishedName) {
                    $Script:LDAPStatistics.TotalEstimatedBytes += $Entry.DistinguishedName.Length * 2 + 40
                }

                # Call .get_Item([string]) directly instead of the PowerShell [] indexer:
                # PS's indexer resolution on SearchResultAttributeCollection silently drops
                # some attributes (e.g. objectSid, msExchDelegateListBL) with a null result.
                $EntryAttrs = $Entry.Attributes
                if (-not $EntryAttrs) { continue }
                foreach ($PropName in $EntryAttrs.AttributeNames) {
                    if ([string]::IsNullOrEmpty($PropName)) { continue }
                    $AttrValues = $null
                    try { $AttrValues = $EntryAttrs.get_Item([string]$PropName) } catch {
                        Write-Log "[Invoke-LDAPSearch] Failed to read attribute '$PropName' on '$($Entry.DistinguishedName)': $($_.Exception.Message)" -Level Warning
                        continue
                    }
                    if ($null -eq $AttrValues) { continue }

                    # Statistics: estimate bytes for this attribute
                    if ($Script:LDAPStatistics) {
                        for ($si = 0; $si -lt $AttrValues.Count; $si++) {
                            try {
                                $statVal = $AttrValues[$si]
                                if ($statVal -is [byte[]]) {
                                    $Script:LDAPStatistics.TotalEstimatedBytes += $statVal.Length
                                } elseif ($statVal -is [string]) {
                                    $Script:LDAPStatistics.TotalEstimatedBytes += $statVal.Length * 2  # UTF-16
                                } else {
                                    $Script:LDAPStatistics.TotalEstimatedBytes += 8  # fixed-size estimate
                                }
                            } catch {
                                $Script:LDAPStatistics.TotalEstimatedBytes += 8
                            }
                        }
                        # Add attribute name overhead (~DN length + attribute name)
                        $Script:LDAPStatistics.TotalEstimatedBytes += $PropName.Length + 20
                    }

                    # Build PropValue array from LdapConnection attribute values
                    # NOTE: DirectoryAttribute indexer returns strings by default.
                    # For binary attributes, we need to use GetValues([byte[]]) to get raw bytes.
                    $PropValue = @()
                    $PropNameLower = $PropName.ToLower()

                    if ($BinaryAttributeSet.Contains($PropNameLower)) {
                        # Binary attribute - extract as byte arrays
                        try {
                            $ByteValues = $AttrValues.GetValues([byte[]])
                            foreach ($bv in $ByteValues) {
                                $PropValue += ,$bv  # Use comma to prevent array flattening
                            }
                        } catch {
                            # Fallback to string extraction if byte[] fails
                            for ($i = 0; $i -lt $AttrValues.Count; $i++) {
                                $PropValue += $AttrValues[$i]
                            }
                        }
                    } else {
                        # Non-binary attribute - use default string extraction
                        for ($i = 0; $i -lt $AttrValues.Count; $i++) {
                            $PropValue += $AttrValues[$i]
                        }
                    }

                    # If -Raw is specified, skip all conversions and return raw values
                    if ($Raw) {
                        # Raw mode - no conversions, just add property as-is
                        if ($PropValue.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                        } else {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @($PropValue)
                        }
                        continue
                    }

                    # =====================================================================
                    # Handle multi-value attributes that need special processing
                    # These are processed BEFORE single-value check
                    # =====================================================================

                    # sIDHistory - Multi-valued SID attribute (critical for SID History Injection detection)
                    if ($PropName -ieq "sIDHistory") {
                        $sidStrings = @()
                        foreach ($sidBytes in $PropValue) {
                            if ($sidBytes -is [byte[]]) {
                                $sidString = Convert-SIDToString -SIDBytes $sidBytes
                                if ($sidString) {
                                    $sidStrings += $sidString
                                }
                            } elseif ($sidBytes -is [string]) {
                                $sidStrings += $sidBytes
                            }
                        }
                        if ($sidStrings.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $sidStrings[0]
                        } elseif ($sidStrings.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $sidStrings
                        }
                        continue
                    }

                    # userCertificate / cACertificate - Multi-valued X.509 certificates
                    if ($PropName -ieq "userCertificate" -or $PropName -ieq "cACertificate") {
                        $certInfos = @()
                        foreach ($certBytes in $PropValue) {
                            if ($certBytes -is [byte[]]) {
                                $certInfo = Convert-CertificateToInfo -CertBytes $certBytes
                                $certInfos += $certInfo
                            }
                        }
                        if ($certInfos.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $certInfos[0]
                        } elseif ($certInfos.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $certInfos
                        }
                        continue
                    }

                    # msDS-KeyCredentialLink - Multi-valued DNWithBinary (Windows Hello for Business, etc.)
                    if ($PropName -ieq "msDS-KeyCredentialLink") {
                        $keyInfos = @()
                        foreach ($keyValue in $PropValue) {
                            $keyInfo = Convert-KeyCredentialToInfo -KeyCredValue $keyValue
                            if ($keyInfo) {
                                $keyInfos += $keyInfo
                            }
                        }
                        if ($keyInfos.Count -gt 0) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $keyInfos
                        }
                        continue
                    }

                    # msLAPS-EncryptedPasswordHistory - Multi-valued (array of encrypted blobs)
                    if ($PropName -ieq "msLAPS-EncryptedPasswordHistory") {
                        # LAPS v2 Encrypted Password History - Array of encrypted password blobs
                        try {
                            $historyEntries = @()
                            $entryIndex = 0

                            foreach ($historyBlob in $PropValue) {
                                $entryIndex++
                                try {
                                    $historyInfo = ConvertFrom-LAPSEncryptedPassword -Blob $historyBlob
                                    if ($historyInfo -and $historyInfo.UpdateTimestamp) {
                                        $historyEntries += "[$entryIndex] $($historyInfo.UpdateTimestamp.ToString('yyyy-MM-dd HH:mm:ss'))"
                                    } else {
                                        $historyEntries += "[$entryIndex] [Encrypted - $($historyBlob.Length) bytes]"
                                    }
                                } catch {
                                    $historyEntries += "[$entryIndex] [Encrypted - $($historyBlob.Length) bytes]"
                                }
                            }

                            if ($historyEntries.Count -gt 0) {
                                $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $historyEntries
                            }
                        } catch {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[History: $($PropValue.Count) entries]"
                        }
                        continue
                    }

                    # protocolSettings - Exchange's per-user protocol overrides.
                    # Each entry has the form '<Protocol>SEP<Enabled 0/1>SEP<UseDefaults 0/1>SEP<encoding flags...>'
                    # where SEP is U+00A7 (section sign, see the Split below). For security review
                    # only the protocol + enabled state matter;
                    # the trailing per-user encoding overrides (mail format, MIME charset, etc.) are noise.
                    if ($PropName -ieq "protocolSettings") {
                        $protoLines = @()
                        foreach ($entry in $PropValue) {
                            $entryStr = [string]$entry
                            if ([string]::IsNullOrWhiteSpace($entryStr)) { continue }
                            $fields = $entryStr.Split([char]0x00A7)
                            $proto = if ($fields[0]) { $fields[0] } else { '<unknown>' }
                            $state = if ($fields.Count -ge 2 -and -not [string]::IsNullOrEmpty($fields[1])) {
                                switch ($fields[1]) {
                                    '0'     { 'disabled' }
                                    '1'     { 'enabled' }
                                    default { "unknown=$($fields[1])" }
                                }
                            } else { 'no enable flag' }
                            $protoLines += "${proto}: $state"
                        }
                        if ($protoLines.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $protoLines[0]
                        } elseif ($protoLines.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $protoLines
                        }
                        continue
                    }

                    # pKIExtendedKeyUsage - Multi-valued OID array (convert to friendly names)
                    if ($PropName -ieq "pKIExtendedKeyUsage") {
                        # Convert EKU OIDs to friendly names using central OID mapping
                        $ekuNames = Convert-OIDsToNames -OIDs $PropValue -IncludeOID
                        if ($ekuNames.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $ekuNames[0]
                        } elseif ($ekuNames.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $ekuNames
                        } else {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("Any Purpose")
                        }
                        continue
                    }

                    # msPKI-Certificate-Application-Policy - Multi-valued OID array (convert to friendly names)
                    if ($PropName -ieq "msPKI-Certificate-Application-Policy") {
                        # Convert Application Policy OIDs to friendly names using central OID mapping
                        $policyNames = Convert-OIDsToNames -OIDs $PropValue -IncludeOID
                        if ($policyNames.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $policyNames[0]
                        } elseif ($policyNames.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $policyNames
                        }
                        continue
                    }

                    # msPKI-RA-Application-Policies / msPKI-RA-Policies - Registration Authority
                    # requirements (ESC3 condition 2). Values are normally OIDs, but schema v3+/v4
                    # templates may store non-OID qualifier strings here - those are passed through
                    # unchanged so they stay visible instead of being mangled by the OID lookup.
                    if ($PropName -iin @("msPKI-RA-Application-Policies", "msPKI-RA-Policies")) {
                        $raNames = @()
                        foreach ($raValue in @($PropValue)) {
                            $raString = [string]$raValue
                            if ($raString -match '^\d+(\.\d+)+$') {
                                $raNames += (ConvertFrom-OID -OID $raString -IncludeOID)
                            } elseif ($raString) {
                                $raNames += $raString
                            }
                        }
                        if ($raNames.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $raNames[0]
                        } elseif ($raNames.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $raNames
                        }
                        continue
                    }

                    # pKICriticalExtensions - Multi-valued OID array (convert to friendly names)
                    if ($PropName -ieq "pKICriticalExtensions") {
                        # Convert Critical Extensions OIDs to friendly names using central OID mapping
                        $critExtNames = Convert-OIDsToNames -OIDs $PropValue -IncludeOID
                        if ($critExtNames.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $critExtNames[0]
                        } elseif ($critExtNames.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $critExtNames
                        }
                        continue
                    }

                    # thumbnailPhoto / jpegPhoto - Image data (JPEG/PNG)
                    # Store as object with metadata for console and Base64 for HTML rendering
                    if ($PropName -iin @("thumbnailPhoto", "jpegPhoto")) {
                        if ($PropValue.Count -ge 1 -and $PropValue[0] -is [byte[]]) {
                            $imageBytes = $PropValue[0]
                            $imageSizeKB = [math]::Round($imageBytes.Length / 1024, 1)

                            # Detect image type from magic bytes
                            $imageType = "unknown"
                            $mimeType = "application/octet-stream"
                            if ($imageBytes.Length -ge 3) {
                                # JPEG: FF D8 FF
                                if ($imageBytes[0] -eq 0xFF -and $imageBytes[1] -eq 0xD8 -and $imageBytes[2] -eq 0xFF) {
                                    $imageType = "JPEG"
                                    $mimeType = "image/jpeg"
                                }
                                # PNG: 89 50 4E 47
                                elseif ($imageBytes[0] -eq 0x89 -and $imageBytes[1] -eq 0x50 -and $imageBytes[2] -eq 0x4E -and $imageBytes.Length -ge 4 -and $imageBytes[3] -eq 0x47) {
                                    $imageType = "PNG"
                                    $mimeType = "image/png"
                                }
                                # GIF: 47 49 46
                                elseif ($imageBytes[0] -eq 0x47 -and $imageBytes[1] -eq 0x49 -and $imageBytes[2] -eq 0x46) {
                                    $imageType = "GIF"
                                    $mimeType = "image/gif"
                                }
                                # BMP: 42 4D
                                elseif ($imageBytes[0] -eq 0x42 -and $imageBytes[1] -eq 0x4D) {
                                    $imageType = "BMP"
                                    $mimeType = "image/bmp"
                                }
                            }

                            # Create structured object with image data
                            $imageObj = [PSCustomObject]@{
                                PSTypeName = 'adPEAS.ImageData'
                                ImageType = $imageType
                                MimeType = $mimeType
                                SizeBytes = $imageBytes.Length
                                SizeKB = $imageSizeKB
                                Base64 = [Convert]::ToBase64String($imageBytes)
                                DisplayText = "[$imageType image, $imageSizeKB KB]"
                            }

                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $imageObj
                        }
                        continue
                    }

                    # mSMQDigests - Multi-valued binary (MD5 message digests, 16 bytes each)
                    if ($PropName -ieq "mSMQDigests") {
                        $digestValues = @()
                        foreach ($bytes in $PropValue) {
                            if ($bytes -is [byte[]] -and $bytes.Length -eq 16) {
                                # MD5 digest - display as hex string
                                $hexStr = ($bytes | ForEach-Object { $_.ToString('X2') }) -join ''
                                $digestValues += $hexStr
                            } elseif ($bytes -is [byte[]]) {
                                # Non-standard length - show with byte count
                                $hexStr = ($bytes | ForEach-Object { $_.ToString('X2') }) -join ''
                                $digestValues += "$hexStr ($($bytes.Length) bytes)"
                            } else {
                                $digestValues += [string]$bytes
                            }
                        }
                        if ($digestValues.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $digestValues[0]
                        } elseif ($digestValues.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $digestValues
                        }
                        continue
                    }

                    # mSMQSignCertificates - Multi-valued binary (X.509 certificates)
                    if ($PropName -ieq "mSMQSignCertificates") {
                        $certValues = @()
                        foreach ($bytes in $PropValue) {
                            if ($bytes -is [byte[]]) {
                                try {
                                    # Try to parse as X.509 certificate
                                    $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList @(,$bytes)
                                    $subject = $cert.Subject
                                    $thumbprint = $cert.Thumbprint
                                    $notAfter = $cert.NotAfter.ToString('yyyy-MM-dd')
                                    $certValues += "$subject (Thumbprint: $thumbprint, Expires: $notAfter)"
                                    $cert.Dispose()
                                } catch {
                                    # Not a valid certificate - show as binary info
                                    $certValues += "[Certificate: $($bytes.Length) bytes]"
                                }
                            } else {
                                $certValues += [string]$bytes
                            }
                        }
                        if ($certValues.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $certValues[0]
                        } elseif ($certValues.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $certValues
                        }
                        continue
                    }

                    # extensionData - Multi-valued binary blob (Exchange mailbox data, etc.)
                    # Format: UTF-16LE header string + null terminator + binary data
                    if ($PropName -ieq "extensionData") {
                        $decodedValues = @()
                        foreach ($bytes in $PropValue) {
                            if ($bytes -is [byte[]]) {
                                $result = $null

                                # Exchange extensionData format: UTF-16LE header followed by binary data
                                # Examples: "MBXEXTDATA", "MBXEXTCTIDATA", "DVPROPERTYSTREAMID", etc.
                                # Pattern: Look for UTF-16LE header (alternating nulls) terminated by double-null

                                # Check for UTF-16LE pattern (alternating nulls in first 20+ bytes)
                                $hasAlternatingNulls = $false
                                if ($bytes.Length -ge 4) {
                                    $nullCount = 0
                                    for ($i = 1; $i -lt [Math]::Min($bytes.Length, 40); $i += 2) {
                                        if ($bytes[$i] -eq 0) { $nullCount++ }
                                    }
                                    $hasAlternatingNulls = ($nullCount -ge 3)
                                }

                                if ($hasAlternatingNulls) {
                                    # Find the null terminator (00 00) that ends the UTF-16LE string
                                    $headerEndIndex = -1
                                    for ($i = 0; $i -lt $bytes.Length - 1; $i += 2) {
                                        if ($bytes[$i] -eq 0 -and $bytes[$i + 1] -eq 0) {
                                            $headerEndIndex = $i
                                            break
                                        }
                                    }

                                    if ($headerEndIndex -gt 0) {
                                        # Extract and decode just the header portion
                                        $headerBytes = $bytes[0..($headerEndIndex - 1)]
                                        $header = [System.Text.Encoding]::Unicode.GetString($headerBytes)

                                        # Check if header is printable text
                                        if ($header -match '^[\x20-\x7E\xA0-\xFF]+$') {
                                            $dataLength = $bytes.Length - $headerEndIndex - 2
                                            $result = "$header ($dataLength bytes binary data)"
                                        }
                                    }

                                    # If no header found, try full decode (for pure text values)
                                    if (-not $result) {
                                        $decoded = [System.Text.Encoding]::Unicode.GetString($bytes)
                                        $decoded = $decoded.TrimEnd([char]0)
                                        if ($decoded -match '^[\x20-\x7E\xA0-\xFF]+$') {
                                            $result = $decoded
                                        }
                                    }
                                }

                                # Try UTF-8 for non-UTF16LE data
                                if (-not $result) {
                                    try {
                                        $decoded = [System.Text.Encoding]::UTF8.GetString($bytes)
                                        $decoded = $decoded.TrimEnd([char]0)
                                        # Check if mostly printable
                                        $printable = ($decoded -replace '[^\x20-\x7E\xA0-\xFF]', '').Length
                                        if ($decoded.Length -gt 0 -and $printable -ge ($decoded.Length * 0.8)) {
                                            $result = $decoded -replace '[^\x20-\x7E\xA0-\xFF]', '?'
                                        }
                                    } catch { }
                                }

                                # Try ASCII
                                if (-not $result) {
                                    $decoded = [System.Text.Encoding]::ASCII.GetString($bytes)
                                    $decoded = $decoded.TrimEnd([char]0)
                                    $printable = ($decoded -replace '[^\x20-\x7E]', '').Length
                                    if ($decoded.Length -gt 0 -and $printable -ge ($decoded.Length * 0.7)) {
                                        $result = $decoded -replace '[^\x20-\x7E]', '?'
                                    }
                                }

                                # Fallback: Show as hex string if not decodable
                                if (-not $result -or $result.Length -eq 0) {
                                    $hexStr = ($bytes | ForEach-Object { $_.ToString('X2') }) -join ' '
                                    if ($hexStr.Length -gt 100) {
                                        $result = "[Binary: $($hexStr.Substring(0, 100))... ($($bytes.Length) bytes)]"
                                    } else {
                                        $result = "[Binary: $hexStr]"
                                    }
                                }

                                $decodedValues += $result
                            } else {
                                $decodedValues += [string]$bytes
                            }
                        }

                        if ($decodedValues.Count -eq 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $decodedValues[0]
                        } elseif ($decodedValues.Count -gt 1) {
                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $decodedValues
                        }
                        continue
                    }

                    # If single value, process with full conversion
                    if ($PropValue.Count -eq 1) {
                        # Convert byte arrays (e.g., objectSid, objectGUID, LAPS)
                        # NOTE: Use -ieq for case-insensitive comparison because LdapConnection returns lowercase attribute names
                        if ($PropValue[0] -is [byte[]]) {
                            if ($PropName -ieq "objectSid") {
                                try {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value (New-Object System.Security.Principal.SecurityIdentifier($PropValue[0], 0)).Value
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "ms-DS-CreatorSID") {
                                try {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value (New-Object System.Security.Principal.SecurityIdentifier($PropValue[0], 0)).Value
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "objectGUID" -or $PropName -ieq "msExchMailboxGuid") {
                                try {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value ([System.Guid]$PropValue[0]).ToString()
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msDS-GenerationId") {
                                try {
                                    $GenIdBytes = $PropValue[0]
                                    if ($GenIdBytes.Length -eq 16) {
                                        $GenIdGuid = [System.Guid]::new($GenIdBytes)
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $GenIdGuid.ToString()
                                    } elseif ($GenIdBytes.Length -eq 8) {
                                        $HexString = ($GenIdBytes | ForEach-Object { $_.ToString('X2') }) -join '-'
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $HexString
                                    } else {
                                        $HexString = ($GenIdBytes | ForEach-Object { $_.ToString('X2') }) -join ''
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "0x$HexString"
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msExchMasterAccountSid") {
                                try {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value (New-Object System.Security.Principal.SecurityIdentifier($PropValue[0], 0)).Value
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msDS-GroupMSAMembership") {
                                try {
                                    # gMSA membership uses same unified structure as nTSecurityDescriptor
                                    $SDResult = ConvertFrom-SecurityDescriptor -SecurityDescriptorBytes $PropValue[0]
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $SDResult
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msDS-ManagedPasswordId" -or $PropName -ieq "msDS-ManagedPasswordPreviousId") {
                                try {
                                    # MS-GKDI KEY_ID structure (used by gMSA/dMSA managed password IDs):
                                    #   Offset  0: Version   (4 bytes, = 1)
                                    #   Offset  4: Magic     (4 bytes, = "KDSK")
                                    #   Offset  8: Flags     (4 bytes)
                                    #   Offset 12: L0 Index  (4 bytes)
                                    #   Offset 16: L1 Index  (4 bytes)
                                    #   Offset 20: L2 Index  (4 bytes)
                                    #   Offset 24: Root Key Identifier (16 bytes, GUID)
                                    #   followed by length fields and domain/forest name (UTF-16)
                                    # The Root Key Identifier tells us which KDS root key derived the password,
                                    # the L0/L1/L2 indexes identify the key generation within that root key.
                                    $PasswordIdBytes = $PropValue[0]
                                    if ($PasswordIdBytes -is [byte[]] -and $PasswordIdBytes.Length -ge 40 -and
                                        $PasswordIdBytes[4] -eq 0x4B -and $PasswordIdBytes[5] -eq 0x44 -and
                                        $PasswordIdBytes[6] -eq 0x53 -and $PasswordIdBytes[7] -eq 0x4B) {

                                        $L0Index = [BitConverter]::ToInt32($PasswordIdBytes, 12)
                                        $L1Index = [BitConverter]::ToInt32($PasswordIdBytes, 16)
                                        $L2Index = [BitConverter]::ToInt32($PasswordIdBytes, 20)

                                        $RootKeyBytes = [byte[]]::new(16)
                                        [Array]::Copy($PasswordIdBytes, 24, $RootKeyBytes, 0, 16)
                                        $RootKeyId = [System.Guid]::new($RootKeyBytes)

                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "RootKeyId: $($RootKeyId.ToString()), L0/L1/L2: $L0Index/$L1Index/$L2Index"
                                    } elseif ($PasswordIdBytes -is [byte[]]) {
                                        # Unknown structure - fall back to full hex representation
                                        $HexString = ($PasswordIdBytes | ForEach-Object { $_.ToString('X2') }) -join '-'
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $HexString
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "ms-DS-ConsistencyGuid") {
                                try {
                                    $GuidBytes = $PropValue[0]
                                    if ($GuidBytes -is [byte[]] -and $GuidBytes.Length -eq 16) {
                                        $ByteArray = [byte[]]$GuidBytes
                                        $GuidObj = [System.Guid]::new($ByteArray)
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $GuidObj.ToString()
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "nTSecurityDescriptor") {
                                try {
                                    $SDResult = ConvertFrom-SecurityDescriptor -SecurityDescriptorBytes $PropValue[0]
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $SDResult
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msExchMailboxSecurityDescriptor") {
                                try {
                                    $SDResult = ConvertFrom-SecurityDescriptor -SecurityDescriptorBytes $PropValue[0]
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $SDResult
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msDS-AllowedToActOnBehalfOfOtherIdentity") {
                                # RBCD: extract principal names from the security descriptor who are allowed to delegate
                                try {
                                    $SD = New-Object System.DirectoryServices.ActiveDirectorySecurity
                                    $SD.SetSecurityDescriptorBinaryForm($PropValue[0])

                                    # Extract only Allow ACEs - these are the principals allowed to delegate
                                    $rbcdPrincipals = @()
                                    foreach ($ACE in $SD.Access) {
                                        if ($ACE.AccessControlType -eq 'Allow') {
                                            $Principal = $ACE.IdentityReference.Value
                                            # Resolve SID to name if needed
                                            if ($Principal -match '^S-1-') {
                                                $PrincipalName = ConvertFrom-SID -SID $Principal
                                            } else {
                                                $PrincipalName = $Principal
                                            }
                                            $rbcdPrincipals += $PrincipalName
                                        }
                                    }

                                    if ($rbcdPrincipals.Count -eq 1) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $rbcdPrincipals[0]
                                    } elseif ($rbcdPrincipals.Count -gt 1) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $rbcdPrincipals
                                    } else {
                                        # SD parsed but no Allow ACEs found - attribute is set but SD has no delegates.
                                        # Still set the property so it appears in display (attribute is present in AD).
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[SD present, no Allow ACEs]"
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "msExchSafeSendersHash" -or $PropName -ieq "msExchBlockedSendersHash") {
                                # Exchange Safe/Blocked Senders Hash - MD5 hash of sender list
                                # Display as compact hex string (these are hashes, not text)
                                try {
                                    $bytes = $PropValue[0]
                                    $hexStr = ($bytes | ForEach-Object { $_.ToString('X2') }) -join ''
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $hexStr
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[Hash: $($PropValue[0].Length) bytes]"
                                }
                            } elseif ($PropName -ieq "msLAPS-EncryptedPassword") {
                                # LAPS v2 Encrypted Password (single value) - binary blob
                                try {
                                    $encryptedInfo = ConvertFrom-LAPSEncryptedPassword -Blob $PropValue[0]
                                    if ($encryptedInfo -and $encryptedInfo.UpdateTimestamp) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[Encrypted - Updated: $($encryptedInfo.UpdateTimestamp.ToString('yyyy-MM-dd HH:mm:ss'))]"
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[Encrypted - $($PropValue[0].Length) bytes]"
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[Encrypted - $($PropValue[0].Length) bytes]"
                                }
                            } elseif ($PropName -ieq "logonHours") {
                                # logonHours is a 21-byte array (168 bits = 24 hours * 7 days)
                                # Each bit represents one hour, starting Sunday 00:00 UTC
                                try {
                                    $bytes = $PropValue[0]
                                    if ($bytes -is [byte[]] -and $bytes.Length -eq 21) {
                                        # Check if all hours are allowed (all bits set = 0xFF for all bytes)
                                        $allAllowed = $true
                                        foreach ($b in $bytes) {
                                            if ($b -ne 0xFF) { $allAllowed = $false; break }
                                        }

                                        if ($allAllowed) {
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "All hours (no restriction)"
                                        } else {
                                            # Check if all hours are denied (all bits clear)
                                            $allDenied = $true
                                            foreach ($b in $bytes) {
                                                if ($b -ne 0x00) { $allDenied = $false; break }
                                            }

                                            if ($allDenied) {
                                                $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "No hours allowed (logon blocked)"
                                            } else {
                                                # Parse restricted hours - show summary per day
                                                $days = @('Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat')
                                                $restrictions = @()

                                                for ($day = 0; $day -lt 7; $day++) {
                                                    $dayStart = $day * 24
                                                    $allowedHours = @()

                                                    for ($hour = 0; $hour -lt 24; $hour++) {
                                                        $bitIndex = $dayStart + $hour
                                                        $byteIndex = [Math]::Floor($bitIndex / 8)
                                                        $bitPosition = $bitIndex % 8
                                                        $isAllowed = ($bytes[$byteIndex] -band (1 -shl $bitPosition)) -ne 0

                                                        if ($isAllowed) {
                                                            $allowedHours += $hour
                                                        }
                                                    }

                                                    if ($allowedHours.Count -eq 0) {
                                                        $restrictions += "$($days[$day]): Blocked"
                                                    } elseif ($allowedHours.Count -eq 24) {
                                                        $restrictions += "$($days[$day]): All day"
                                                    } else {
                                                        # Find contiguous ranges
                                                        $ranges = @()
                                                        $rangeStart = $allowedHours[0]
                                                        $rangeEnd = $rangeStart

                                                        for ($i = 1; $i -lt $allowedHours.Count; $i++) {
                                                            if ($allowedHours[$i] -eq $rangeEnd + 1) {
                                                                $rangeEnd = $allowedHours[$i]
                                                            } else {
                                                                $ranges += "{0:D2}:00-{1:D2}:00" -f $rangeStart, ($rangeEnd + 1)
                                                                $rangeStart = $allowedHours[$i]
                                                                $rangeEnd = $rangeStart
                                                            }
                                                        }
                                                        $ranges += "{0:D2}:00-{1:D2}:00" -f $rangeStart, (($rangeEnd + 1) % 24)
                                                        $restrictions += "$($days[$day]): $($ranges -join ', ')"
                                                    }
                                                }

                                                $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $restrictions
                                            }
                                        }
                                    } else {
                                        # Unexpected format - show as hex
                                        $hexStr = ($bytes | ForEach-Object { $_.ToString('X2') }) -join ''
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[LogonHours: $hexStr]"
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "pKIExpirationPeriod" -or $PropName -ieq "pKIOverlapPeriod") {
                                # Convert PKI time period byte arrays to readable duration
                                try {
                                    $Bytes = $PropValue[0]
                                    if ($Bytes.Length -eq 8) {
                                        $Int64Value = [BitConverter]::ToInt64($Bytes, 0)
                                        $Seconds = [Math]::Abs($Int64Value) / 10000000

                                        if ($Seconds -ge 31536000) {
                                            $Years = [Math]::Floor($Seconds / 31536000)
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "$Years year(s)"
                                        } elseif ($Seconds -ge 86400) {
                                            $Days = [Math]::Floor($Seconds / 86400)
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "$Days day(s)"
                                        } elseif ($Seconds -ge 3600) {
                                            $Hours = [Math]::Floor($Seconds / 3600)
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "$Hours hour(s)"
                                        } else {
                                            $Minutes = [Math]::Floor($Seconds / 60)
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "$Minutes minute(s)"
                                        }
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropName -ieq "pKIKeyUsage") {
                                # Convert PKI Key Usage byte array to readable flags
                                try {
                                    $Bytes = $PropValue[0]
                                    if ($Bytes.Length -ge 2) {
                                        $KeyUsage = [int]$Bytes[0] + ([int]$Bytes[1] -shl 8)
                                        $KeyUsageList = @()

                                        if ($KeyUsage -band 0x0080) { $KeyUsageList += "Digital Signature" }
                                        if ($KeyUsage -band 0x0040) { $KeyUsageList += "Non Repudiation" }
                                        if ($KeyUsage -band 0x0020) { $KeyUsageList += "Key Encipherment" }
                                        if ($KeyUsage -band 0x0010) { $KeyUsageList += "Data Encipherment" }
                                        if ($KeyUsage -band 0x0008) { $KeyUsageList += "Key Agreement" }
                                        if ($KeyUsage -band 0x0004) { $KeyUsageList += "Key Cert Sign" }
                                        if ($KeyUsage -band 0x0002) { $KeyUsageList += "CRL Sign" }
                                        if ($KeyUsage -band 0x0001) { $KeyUsageList += "Encipher Only" }
                                        if ($KeyUsage -band 0x8000) { $KeyUsageList += "Decipher Only" }

                                        if ($KeyUsageList.Count -gt 0) {
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $KeyUsageList
                                        } else {
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                        }
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'userparameters') {
                                # TSPropertyArray ([MS-TSTS] 2.2.1.1) - per-user TS settings.
                                $tsLines = ConvertFrom-TSProperties -Bytes $PropValue
                                if ($tsLines) {
                                    if ($tsLines.Count -eq 1) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $tsLines[0]
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $tsLines
                                    }
                                } else {
                                    $byteLen = if ($PropValue[0] -is [byte[]]) { $PropValue[0].Length } else { 0 }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[userParameters blob: $byteLen bytes, no recognised TSPropertyArray signature]"
                                }
                            } elseif ($PropNameLower -eq 'terminalserver') {
                                # Per-User CAL tracking token written by Remote Desktop Licensing.
                                $licLines = ConvertFrom-TSClientLicense -Bytes $PropValue
                                if ($licLines) {
                                    if ($licLines.Count -eq 1) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $licLines[0]
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $licLines
                                    }
                                } else {
                                    $byteLen = if ($PropValue[0] -is [byte[]]) { $PropValue[0].Length } else { 0 }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "[terminalServer blob: $byteLen bytes, unknown format]"
                                }
                            } else {
                                # Generic byte array handling
                                $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                            }
                        } else {
                            # Non-byte array single values - apply type conversions

                            # FileTime attributes (Windows FILETIME - 100-nanosecond intervals since 1601-01-01)
                            $FileTimeAttributes = @(
                                'lastlogon', 'lastlogontimestamp', 'pwdlastset', 'badpasswordtime',
                                'lockouttime', 'accountexpires', 'lastlogoff', 'maxpwdage', 'minpwdage',
                                'forcelogoff', 'lockoutduration', 'lockoutobservationwindow',
                                'creationtime', 'lastsettime'
                            )

                            # Generalized Time attributes (ISO 8601 format: YYYYMMDDHHmmss.0Z)
                            $GeneralizedTimeAttributes = @('whenchanged', 'whencreated', 'msexchwhenmailboxcreated')

                            if ($FileTimeAttributes -contains $PropNameLower) {
                                # Convert FileTime to DateTime
                                try {
                                    $ftValue = [long]$PropValue[0]
                                    # Handle special values: 0 = never, 9223372036854775807 = never expires
                                    if ($ftValue -eq 0 -or $ftValue -eq 9223372036854775807) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    } else {
                                        $dateTime = [DateTime]::FromFileTime($ftValue)
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $dateTime
                                    }
                                } catch {
                                    # Fallback to raw value if conversion fails
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($GeneralizedTimeAttributes -contains $PropNameLower) {
                                # Convert Generalized Time (YYYYMMDDHHmmss.0Z) to DateTime
                                try {
                                    $gtValue = [string]$PropValue[0]
                                    # Parse format: 20260105135347.0Z
                                    if ($gtValue -match '^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})') {
                                        $dateTime = [DateTime]::new(
                                            [int]$Matches[1],  # Year
                                            [int]$Matches[2],  # Month
                                            [int]$Matches[3],  # Day
                                            [int]$Matches[4],  # Hour
                                            [int]$Matches[5],  # Minute
                                            [int]$Matches[6],  # Second
                                            [DateTimeKind]::Utc
                                        )
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $dateTime
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'useraccountcontrol') {
                                # Convert userAccountControl to readable flags
                                try {
                                    $UACValue = [Int32]$PropValue[0]
                                    $UACFlags = @()

                                    # Define UAC flags (MS-ADTS 2.2.16)
                                    $FlagMap = @{
                                        1 = "SCRIPT"
                                        2 = "ACCOUNTDISABLE"
                                        8 = "HOMEDIR_REQUIRED"
                                        16 = "LOCKOUT"
                                        32 = "PASSWD_NOTREQD"
                                        64 = "PASSWD_CANT_CHANGE"
                                        128 = "ENCRYPTED_TEXT_PWD_ALLOWED"
                                        256 = "TEMP_DUPLICATE_ACCOUNT"
                                        512 = "NORMAL_ACCOUNT"
                                        2048 = "INTERDOMAIN_TRUST_ACCOUNT"
                                        4096 = "WORKSTATION_TRUST_ACCOUNT"
                                        8192 = "SERVER_TRUST_ACCOUNT"
                                        65536 = "DONT_EXPIRE_PASSWORD"
                                        131072 = "MNS_LOGON_ACCOUNT"
                                        262144 = "SMARTCARD_REQUIRED"
                                        524288 = "TRUSTED_FOR_DELEGATION"
                                        1048576 = "NOT_DELEGATED"
                                        2097152 = "USE_DES_KEY_ONLY"
                                        4194304 = "DONT_REQ_PREAUTH"
                                        8388608 = "PASSWORD_EXPIRED"
                                        16777216 = "TRUSTED_TO_AUTH_FOR_DELEGATION"
                                        33554432 = "NO_AUTH_DATA_REQUIRED"
                                        67108864 = "PARTIAL_SECRETS_ACCOUNT"
                                    }

                                    foreach ($Flag in $FlagMap.Keys) {
                                        if ($UACValue -band $Flag) {
                                            $UACFlags += $FlagMap[$Flag]
                                        }
                                    }

                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $UACFlags
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'msds-supportedencryptiontypes') {
                                # Convert supported encryption types to readable flags
                                try {
                                    $EncTypes = [Int32]$PropValue[0]
                                    $EncTypeFlags = @()

                                    # Encryption types (MS-KILE 2.2.7)
                                    if ($EncTypes -band 1) { $EncTypeFlags += "DES-CBC-CRC" }
                                    if ($EncTypes -band 2) { $EncTypeFlags += "DES-CBC-MD5" }
                                    if ($EncTypes -band 4) { $EncTypeFlags += "RC4-HMAC" }
                                    if ($EncTypes -band 8) { $EncTypeFlags += "AES128-CTS-HMAC-SHA1-96" }
                                    if ($EncTypes -band 16) { $EncTypeFlags += "AES256-CTS-HMAC-SHA1-96" }
                                    if ($EncTypes -band 32) { $EncTypeFlags += "AES256-CTS-HMAC-SHA1-96-SK" }
                                    # Kerberos feature flags
                                    if ($EncTypes -band 64) { $EncTypeFlags += "FAST-Supported" }
                                    if ($EncTypes -band 128) { $EncTypeFlags += "Compound-Identity-Supported" }
                                    if ($EncTypes -band 256) { $EncTypeFlags += "Claims-Supported" }
                                    if ($EncTypes -band 512) { $EncTypeFlags += "Resource-SID-Compression-Disabled" }

                                    if ($EncTypeFlags.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $EncTypeFlags
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("Not configured")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'samaccounttype') {
                                # Convert sAMAccountType to readable value
                                try {
                                    $SamType = [Int32]$PropValue[0]
                                    $SamTypeName = switch ($SamType) {
                                        268435456 { "GROUP_OBJECT" }
                                        268435457 { "NON_SECURITY_GROUP_OBJECT" }
                                        536870912 { "ALIAS_OBJECT" }
                                        536870913 { "NON_SECURITY_ALIAS_OBJECT" }
                                        805306368 { "USER_OBJECT" }
                                        805306369 { "MACHINE_ACCOUNT" }
                                        805306370 { "TRUST_ACCOUNT" }
                                        1073741824 { "APP_BASIC_GROUP" }
                                        1073741825 { "APP_QUERY_GROUP" }
                                        default { "UNKNOWN ($SamType)" }
                                    }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $SamTypeName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'grouptype') {
                                # Convert groupType to readable flags
                                try {
                                    $GroupType = [Int32]$PropValue[0]
                                    $GroupScope = if ($GroupType -band 2) { "Global" }
                                                  elseif ($GroupType -band 4) { "Domain Local" }
                                                  elseif ($GroupType -band 8) { "Universal" }
                                                  elseif ($GroupType -band 1) { "Builtin Local" }
                                                  else { "Unknown Scope" }

                                    $GroupTypeName = if ($GroupType -band [int]0x80000000) {
                                        "$GroupScope Security Group"
                                    } else {
                                        "$GroupScope Distribution Group"
                                    }

                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $GroupTypeName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'instancetype') {
                                # Convert instanceType to readable value
                                try {
                                    $InstType = [Int32]$PropValue[0]
                                    if ($InstType -eq 4) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "Writable"
                                    } else {
                                        $InstTypeFlags = @()
                                        if ($InstType -band 0x01) { $InstTypeFlags += "NC_HEAD" }
                                        if ($InstType -band 0x02) { $InstTypeFlags += "NC_REPLICA" }
                                        if ($InstType -band 0x04) { $InstTypeFlags += "NC_WRITABLE" }
                                        if ($InstType -band 0x08) { $InstTypeFlags += "NC_ABOVE" }
                                        if ($InstType -band 0x10) { $InstTypeFlags += "NC_BEING_CONSTRUCTED" }
                                        if ($InstType -band 0x20) { $InstTypeFlags += "NC_BEING_REMOVED" }
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value ($InstTypeFlags -join ", ")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'systemflags') {
                                # Convert systemFlags to readable flags
                                try {
                                    $SysFlags = [Int32]$PropValue[0]
                                    $SysFlagsArray = @()

                                    $SysFlagsMap = @{
                                        0x00000001 = "FLAG_DISALLOW_DELETE"
                                        0x00000002 = "FLAG_CONFIG_ALLOW_RENAME"
                                        0x00000004 = "FLAG_CONFIG_ALLOW_MOVE"
                                        0x00000010 = "FLAG_ATTR_NOT_REPLICATED"
                                        0x04000000 = "FLAG_ATTR_IS_CONSTRUCTED"
                                        0x10000000 = "FLAG_DOMAIN_DISALLOW_RENAME"
                                        0x20000000 = "FLAG_DOMAIN_DISALLOW_MOVE"
                                        0x40000000 = "FLAG_CR_NTDS_NC"
                                        0x80000000 = "FLAG_CR_NTDS_DOMAIN"
                                    }

                                    foreach ($Flag in $SysFlagsMap.Keys) {
                                        if ($SysFlags -band $Flag) {
                                            $SysFlagsArray += $SysFlagsMap[$Flag]
                                        }
                                    }

                                    if ($SysFlagsArray.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $SysFlagsArray
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'trustdirection') {
                                # Convert trust direction to readable value (MS-ADTS 6.1.6.7.9)
                                try {
                                    $TrustDir = [Int32]$PropValue[0]
                                    $TrustDirName = switch ($TrustDir) {
                                        0 { "Disabled" }
                                        1 { "Inbound" }
                                        2 { "Outbound" }
                                        3 { "Bidirectional" }
                                        default { "Unknown ($TrustDir)" }
                                    }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $TrustDirName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'trusttype') {
                                # Convert trust type to readable value (MS-ADTS 6.1.6.7.15)
                                try {
                                    $TrustTypeVal = [Int32]$PropValue[0]
                                    $TrustTypeName = switch ($TrustTypeVal) {
                                        1 { "Windows NT (Downlevel)" }
                                        2 { "Active Directory (Uplevel)" }
                                        3 { "MIT Kerberos Realm" }
                                        4 { "DCE" }
                                        default { "Unknown ($TrustTypeVal)" }
                                    }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $TrustTypeName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'trustattributes') {
                                # Convert trust attributes to readable flags (MS-ADTS 6.1.6.7.9)
                                try {
                                    $TrustAttr = [Int32]$PropValue[0]
                                    $TrustAttrFlags = @()

                                    if ($TrustAttr -band 0x00000001) { $TrustAttrFlags += "NON_TRANSITIVE" }
                                    if ($TrustAttr -band 0x00000002) { $TrustAttrFlags += "UPLEVEL_ONLY" }
                                    if ($TrustAttr -band 0x00000004) { $TrustAttrFlags += "QUARANTINED_DOMAIN" }
                                    if ($TrustAttr -band 0x00000008) { $TrustAttrFlags += "FOREST_TRANSITIVE" }
                                    if ($TrustAttr -band 0x00000010) { $TrustAttrFlags += "CROSS_ORGANIZATION" }
                                    if ($TrustAttr -band 0x00000020) { $TrustAttrFlags += "WITHIN_FOREST" }
                                    if ($TrustAttr -band 0x00000040) { $TrustAttrFlags += "TREAT_AS_EXTERNAL" }
                                    if ($TrustAttr -band 0x00000080) { $TrustAttrFlags += "USES_RC4_ENCRYPTION" }
                                    if ($TrustAttr -band 0x00000200) { $TrustAttrFlags += "CROSS_ORGANIZATION_NO_TGT_DELEGATION" }
                                    if ($TrustAttr -band 0x00000400) { $TrustAttrFlags += "PIM_TRUST" }

                                    if ($TrustAttrFlags.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $TrustAttrFlags
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'pwdproperties') {
                                # Convert password properties to readable flags (MS-ADTS 6.1.6.1)
                                try {
                                    $PwdProps = [Int32]$PropValue[0]
                                    $PwdPropsFlags = @()

                                    if ($PwdProps -band 1) { $PwdPropsFlags += "DOMAIN_PASSWORD_COMPLEX" }
                                    if ($PwdProps -band 2) { $PwdPropsFlags += "DOMAIN_PASSWORD_NO_ANON_CHANGE" }
                                    if ($PwdProps -band 4) { $PwdPropsFlags += "DOMAIN_PASSWORD_NO_CLEAR_CHANGE" }
                                    if ($PwdProps -band 8) { $PwdPropsFlags += "DOMAIN_LOCKOUT_ADMINS" }
                                    if ($PwdProps -band 16) { $PwdPropsFlags += "DOMAIN_PASSWORD_STORE_CLEARTEXT" }
                                    if ($PwdProps -band 32) { $PwdPropsFlags += "DOMAIN_REFUSE_PASSWORD_CHANGE" }

                                    if ($PwdPropsFlags.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PwdPropsFlags
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'maxpwdage' -or $PropNameLower -eq 'minpwdage' -or $PropNameLower -eq 'lockoutduration' -or $PropNameLower -eq 'lockoutobservationwindow' -or $PropNameLower -eq 'forcelogoff') {
                                # Domain policy attributes (negative 100-nanosecond intervals)
                                try {
                                    $Ticks = [Int64]$PropValue[0]

                                    if ($Ticks -eq 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "Not set"
                                    } elseif ($Ticks -eq -9223372036854775808) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "Never"
                                    } else {
                                        $Seconds = [Math]::Abs($Ticks) / 10000000

                                        if ($PropNameLower -eq 'maxpwdage' -or $PropNameLower -eq 'minpwdage') {
                                            $Days = [Math]::Floor($Seconds / 86400)
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "$Days days"
                                        } else {
                                            $Minutes = [Math]::Floor($Seconds / 60)
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value "$Minutes minutes"
                                        }
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'ms-mcs-admpwdexpirationtime' -or $PropNameLower -eq 'mslaps-passwordexpirationtime') {
                                # LAPS Expiration Times
                                try {
                                    $ExpirationInt64 = [Int64]$PropValue[0]
                                    $ExpirationDateTime = [DateTime]::FromFileTime($ExpirationInt64)
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $ExpirationDateTime
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'mslaps-password') {
                                # LAPS Native Plaintext Password - JSON format: {"n":"Account","t":"HexFILETIME","p":"Password"}
                                try {
                                    $LAPSObj = $PropValue[0] | ConvertFrom-Json
                                    if ($LAPSObj.p) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $LAPSObj.p
                                        if ($LAPSObj.n) {
                                            $Obj | Add-Member -Force -MemberType NoteProperty -Name 'msLAPS-Account' -Value $LAPSObj.n
                                        }
                                        if ($LAPSObj.t) {
                                            try {
                                                $LAPSFileTime = [Convert]::ToInt64($LAPSObj.t, 16)
                                                $Obj | Add-Member -Force -MemberType NoteProperty -Name 'msLAPS-Updated' -Value ([DateTime]::FromFileTimeUtc($LAPSFileTime))
                                            } catch { }
                                        }
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'msexchrecipientdisplaytype') {
                                # Convert Exchange Recipient Display Type
                                try {
                                    $DisplayType = [Int64]$PropValue[0]
                                    $DisplayTypeName = switch ($DisplayType) {
                                        0 { "MailboxUser" }
                                        1 { "DistributionGroup" }
                                        2 { "PublicFolder" }
                                        3 { "DynamicDistributionGroup" }
                                        4 { "Organization" }
                                        5 { "PrivateDistributionList" }
                                        6 { "RemoteMailUser" }
                                        7 { "ConferenceRoomMailbox" }
                                        8 { "EquipmentMailbox" }
                                        10 { "ArbitrationMailbox" }
                                        11 { "MailboxPlan" }
                                        12 { "LinkedUser" }
                                        15 { "RoomList" }
                                        1073741824 { "ACLableMailboxUser" }
                                        1073741830 { "ACLableRemoteMailUser" }
                                        -2147483642 { "SyncedMailboxUser" }
                                        -2147483391 { "SyncedUDGasUDG" }
                                        -2147483386 { "SyncedUDGasContact" }
                                        -2147483130 { "SyncedPublicFolder" }
                                        -2147482874 { "SyncedDynamicDistributionGroup" }
                                        -2147482106 { "SyncedRemoteMailUser" }
                                        -2147481850 { "SyncedConferenceRoomMailbox" }
                                        -2147481594 { "SyncedEquipmentMailbox" }
                                        -2147481343 { "SyncedUSGasUDG" }
                                        -2147481338 { "SyncedUSGasContact" }
                                        -1073741818 { "ACLableSyncedMailboxUser" }
                                        -1073740282 { "ACLableSyncedRemoteMailUser" }
                                        -1073739514 { "ACLableSyncedUSGasContact" }
                                        -1073739511 { "SyncedUSGasUSG" }
                                        -1073741824 { "SecurityDistributionGroup" }
                                        default { "Type $DisplayType" }
                                    }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $DisplayTypeName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'msexchrecipienttypedetails') {
                                # Convert Exchange Recipient Type Details
                                try {
                                    $TypeDetails = [Int64]$PropValue[0]
                                    $TypeName = switch ($TypeDetails) {
                                        1 { "UserMailbox" }
                                        2 { "LinkedMailbox" }
                                        4 { "SharedMailbox" }
                                        8 { "LegacyMailbox" }
                                        16 { "RoomMailbox" }
                                        32 { "EquipmentMailbox" }
                                        64 { "MailContact" }
                                        128 { "MailUser" }
                                        256 { "MailUniversalDistributionGroup" }
                                        512 { "MailNonUniversalGroup" }
                                        1024 { "MailUniversalSecurityGroup" }
                                        2048 { "DynamicDistributionGroup" }
                                        4096 { "PublicFolder" }
                                        8192 { "SystemAttendantMailbox" }
                                        16384 { "SystemMailbox" }
                                        32768 { "MailForestContact" }
                                        65536 { "User" }
                                        131072 { "Contact" }
                                        262144 { "UniversalDistributionGroup" }
                                        524288 { "UniversalSecurityGroup" }
                                        1048576 { "NonUniversalGroup" }
                                        2097152 { "DisabledUser" }
                                        4194304 { "MicrosoftExchange" }
                                        8388608 { "ArbitrationMailbox" }
                                        16777216 { "MailboxPlan" }
                                        33554432 { "LinkedUser" }
                                        268435456 { "RoomList" }
                                        536870912 { "DiscoveryMailbox" }
                                        1073741824 { "RoleGroup" }
                                        2147483648 { "RemoteUserMailbox" }
                                        4294967296 { "Computer" }
                                        8589934592 { "RemoteRoomMailbox" }
                                        17179869184 { "RemoteEquipmentMailbox" }
                                        34359738368 { "RemoteSharedMailbox" }
                                        68719476736 { "PublicFolderMailbox" }
                                        137438953472 { "TeamMailbox" }
                                        549755813888 { "MonitoringMailbox" }
                                        1099511627776 { "GroupMailbox" }
                                        2199023255552 { "LinkedRoomMailbox" }
                                        4398046511104 { "AuditLogMailbox" }
                                        17592186044416 { "SchedulingMailbox" }
                                        35184372088832 { "GuestMailUser" }
                                        default { "Type $TypeDetails" }
                                    }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $TypeName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'mspki-certificate-name-flag') {
                                # Convert Certificate Name Flag to readable flags (ADCS ESC1)
                                try {
                                    $CertNameFlag = [Int32]$PropValue[0]
                                    $CertNameFlags = @()

                                    # CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT (0x00000001) - ESC1 indicator
                                    if ($CertNameFlag -band 0x00000001) { $CertNameFlags += "ENROLLEE_SUPPLIES_SUBJECT" }
                                    # CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT_ALT_NAME (0x00010000)
                                    if ($CertNameFlag -band 0x00010000) { $CertNameFlags += "ENROLLEE_SUPPLIES_SUBJECT_ALT_NAME" }
                                    # CT_FLAG_SUBJECT_ALT_REQUIRE_DOMAIN_DNS (0x00400000)
                                    if ($CertNameFlag -band 0x00400000) { $CertNameFlags += "SUBJECT_ALT_REQUIRE_DOMAIN_DNS" }
                                    # CT_FLAG_SUBJECT_ALT_REQUIRE_SPN (0x00800000)
                                    if ($CertNameFlag -band 0x00800000) { $CertNameFlags += "SUBJECT_ALT_REQUIRE_SPN" }
                                    # CT_FLAG_SUBJECT_ALT_REQUIRE_DIRECTORY_GUID (0x01000000)
                                    if ($CertNameFlag -band 0x01000000) { $CertNameFlags += "SUBJECT_ALT_REQUIRE_DIRECTORY_GUID" }
                                    # CT_FLAG_SUBJECT_ALT_REQUIRE_UPN (0x02000000)
                                    if ($CertNameFlag -band 0x02000000) { $CertNameFlags += "SUBJECT_ALT_REQUIRE_UPN" }
                                    # CT_FLAG_SUBJECT_ALT_REQUIRE_EMAIL (0x04000000)
                                    if ($CertNameFlag -band 0x04000000) { $CertNameFlags += "SUBJECT_ALT_REQUIRE_EMAIL" }
                                    # CT_FLAG_SUBJECT_ALT_REQUIRE_DNS (0x08000000)
                                    if ($CertNameFlag -band 0x08000000) { $CertNameFlags += "SUBJECT_ALT_REQUIRE_DNS" }
                                    # CT_FLAG_SUBJECT_REQUIRE_DNS_AS_CN (0x10000000)
                                    if ($CertNameFlag -band 0x10000000) { $CertNameFlags += "SUBJECT_REQUIRE_DNS_AS_CN" }
                                    # CT_FLAG_SUBJECT_REQUIRE_EMAIL (0x20000000)
                                    if ($CertNameFlag -band 0x20000000) { $CertNameFlags += "SUBJECT_REQUIRE_EMAIL" }
                                    # CT_FLAG_SUBJECT_REQUIRE_COMMON_NAME (0x40000000)
                                    if ($CertNameFlag -band 0x40000000) { $CertNameFlags += "SUBJECT_REQUIRE_COMMON_NAME" }
                                    # CT_FLAG_SUBJECT_REQUIRE_DIRECTORY_PATH (0x80000000)
                                    if ($CertNameFlag -band 0x80000000) { $CertNameFlags += "SUBJECT_REQUIRE_DIRECTORY_PATH" }
                                    # CT_FLAG_OLD_CERT_SUPPLIES_SUBJECT_AND_ALT_NAME (0x00000008)
                                    if ($CertNameFlag -band 0x00000008) { $CertNameFlags += "OLD_CERT_SUPPLIES_SUBJECT_AND_ALT_NAME" }

                                    if ($CertNameFlags.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $CertNameFlags
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'mspki-enrollment-flag') {
                                # Convert Enrollment Flag to readable flags (ADCS ESC2/ESC9)
                                try {
                                    $EnrollFlag = [Int32]$PropValue[0]
                                    $EnrollFlags = @()

                                    # CT_FLAG_INCLUDE_SYMMETRIC_ALGORITHMS (0x00000001)
                                    if ($EnrollFlag -band 0x00000001) { $EnrollFlags += "INCLUDE_SYMMETRIC_ALGORITHMS" }
                                    # CT_FLAG_PEND_ALL_REQUESTS (0x00000002) - Manager approval required
                                    if ($EnrollFlag -band 0x00000002) { $EnrollFlags += "PEND_ALL_REQUESTS" }
                                    # CT_FLAG_PUBLISH_TO_KRA_CONTAINER (0x00000004)
                                    if ($EnrollFlag -band 0x00000004) { $EnrollFlags += "PUBLISH_TO_KRA_CONTAINER" }
                                    # CT_FLAG_PUBLISH_TO_DS (0x00000008)
                                    if ($EnrollFlag -band 0x00000008) { $EnrollFlags += "PUBLISH_TO_DS" }
                                    # CT_FLAG_AUTO_ENROLLMENT_CHECK_USER_DS_CERTIFICATE (0x00000010)
                                    if ($EnrollFlag -band 0x00000010) { $EnrollFlags += "AUTO_ENROLLMENT_CHECK_USER_DS_CERTIFICATE" }
                                    # CT_FLAG_AUTO_ENROLLMENT (0x00000020)
                                    if ($EnrollFlag -band 0x00000020) { $EnrollFlags += "AUTO_ENROLLMENT" }
                                    # CT_FLAG_PREVIOUS_APPROVAL_VALIDATE_REENROLLMENT (0x00000040)
                                    if ($EnrollFlag -band 0x00000040) { $EnrollFlags += "PREVIOUS_APPROVAL_VALIDATE_REENROLLMENT" }
                                    # CT_FLAG_USER_INTERACTION_REQUIRED (0x00000100)
                                    if ($EnrollFlag -band 0x00000100) { $EnrollFlags += "USER_INTERACTION_REQUIRED" }
                                    # CT_FLAG_REMOVE_INVALID_CERTIFICATE_FROM_PERSONAL_STORE (0x00000400)
                                    if ($EnrollFlag -band 0x00000400) { $EnrollFlags += "REMOVE_INVALID_CERTIFICATE_FROM_PERSONAL_STORE" }
                                    # CT_FLAG_ALLOW_ENROLL_ON_BEHALF_OF (0x00000800)
                                    if ($EnrollFlag -band 0x00000800) { $EnrollFlags += "ALLOW_ENROLL_ON_BEHALF_OF" }
                                    # CT_FLAG_ADD_OCSP_NOCHECK (0x00001000)
                                    if ($EnrollFlag -band 0x00001000) { $EnrollFlags += "ADD_OCSP_NOCHECK" }
                                    # CT_FLAG_ENABLE_KEY_REUSE_ON_NT_TOKEN_KEYSET_STORAGE_FULL (0x00002000)
                                    if ($EnrollFlag -band 0x00002000) { $EnrollFlags += "ENABLE_KEY_REUSE_ON_NT_TOKEN_KEYSET_STORAGE_FULL" }
                                    # CT_FLAG_NOREVOCATIONINFOINISSUEDCERTS (0x00004000)
                                    if ($EnrollFlag -band 0x00004000) { $EnrollFlags += "NOREVOCATIONINFOINISSUEDCERTS" }
                                    # CT_FLAG_INCLUDE_BASIC_CONSTRAINTS_FOR_EE_CERTS (0x00008000)
                                    if ($EnrollFlag -band 0x00008000) { $EnrollFlags += "INCLUDE_BASIC_CONSTRAINTS_FOR_EE_CERTS" }
                                    # CT_FLAG_ALLOW_PREVIOUS_APPROVAL_KEYBASEDRENEWAL_VALIDATE_REENROLLMENT (0x00010000)
                                    if ($EnrollFlag -band 0x00010000) { $EnrollFlags += "ALLOW_PREVIOUS_APPROVAL_KEYBASEDRENEWAL_VALIDATE_REENROLLMENT" }
                                    # CT_FLAG_ISSUANCE_POLICIES_FROM_REQUEST (0x00020000)
                                    if ($EnrollFlag -band 0x00020000) { $EnrollFlags += "ISSUANCE_POLICIES_FROM_REQUEST" }
                                    # CT_FLAG_SKIP_AUTO_RENEWAL (0x00040000)
                                    if ($EnrollFlag -band 0x00040000) { $EnrollFlags += "SKIP_AUTO_RENEWAL" }
                                    # CT_FLAG_NO_SECURITY_EXTENSION (0x00080000) - ESC9 indicator
                                    if ($EnrollFlag -band 0x00080000) { $EnrollFlags += "NO_SECURITY_EXTENSION" }

                                    if ($EnrollFlags.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $EnrollFlags
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'mspki-private-key-flag') {
                                # Convert Private Key Flag to readable flags
                                try {
                                    $PrivKeyFlag = [Int32]$PropValue[0]
                                    $PrivKeyFlags = @()

                                    # CT_FLAG_REQUIRE_PRIVATE_KEY_ARCHIVAL (0x00000001)
                                    if ($PrivKeyFlag -band 0x00000001) { $PrivKeyFlags += "REQUIRE_PRIVATE_KEY_ARCHIVAL" }
                                    # CT_FLAG_EXPORTABLE_KEY (0x00000010)
                                    if ($PrivKeyFlag -band 0x00000010) { $PrivKeyFlags += "EXPORTABLE_KEY" }
                                    # CT_FLAG_STRONG_KEY_PROTECTION_REQUIRED (0x00000020)
                                    if ($PrivKeyFlag -band 0x00000020) { $PrivKeyFlags += "STRONG_KEY_PROTECTION_REQUIRED" }
                                    # CT_FLAG_REQUIRE_ALTERNATE_SIGNATURE_ALGORITHM (0x00000040)
                                    if ($PrivKeyFlag -band 0x00000040) { $PrivKeyFlags += "REQUIRE_ALTERNATE_SIGNATURE_ALGORITHM" }
                                    # CT_FLAG_REQUIRE_SAME_KEY_RENEWAL (0x00000080)
                                    if ($PrivKeyFlag -band 0x00000080) { $PrivKeyFlags += "REQUIRE_SAME_KEY_RENEWAL" }
                                    # CT_FLAG_USE_LEGACY_PROVIDER (0x00000100)
                                    if ($PrivKeyFlag -band 0x00000100) { $PrivKeyFlags += "USE_LEGACY_PROVIDER" }
                                    # CT_FLAG_ATTEST_NONE (0x00000000) - implicit
                                    # CT_FLAG_ATTEST_REQUIRED (0x00002000)
                                    if ($PrivKeyFlag -band 0x00002000) { $PrivKeyFlags += "ATTEST_REQUIRED" }
                                    # CT_FLAG_ATTEST_PREFERRED (0x00001000)
                                    if ($PrivKeyFlag -band 0x00001000) { $PrivKeyFlags += "ATTEST_PREFERRED" }
                                    # CT_FLAG_ATTESTATION_WITHOUT_POLICY (0x00004000)
                                    if ($PrivKeyFlag -band 0x00004000) { $PrivKeyFlags += "ATTESTATION_WITHOUT_POLICY" }
                                    # CT_FLAG_EK_TRUST_ON_USE (0x00000200)
                                    if ($PrivKeyFlag -band 0x00000200) { $PrivKeyFlags += "EK_TRUST_ON_USE" }
                                    # CT_FLAG_EK_VALIDATE_CERT (0x00000400)
                                    if ($PrivKeyFlag -band 0x00000400) { $PrivKeyFlags += "EK_VALIDATE_CERT" }
                                    # CT_FLAG_EK_VALIDATE_KEY (0x00000800)
                                    if ($PrivKeyFlag -band 0x00000800) { $PrivKeyFlags += "EK_VALIDATE_KEY" }
                                    # CT_FLAG_HELLO_LOGON_KEY (0x00200000)
                                    if ($PrivKeyFlag -band 0x00200000) { $PrivKeyFlags += "HELLO_LOGON_KEY" }

                                    if ($PrivKeyFlags.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PrivKeyFlags
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'pkidefaultkeyspec') {
                                # Convert pKIDefaultKeySpec to readable value
                                try {
                                    $KeySpec = [Int32]$PropValue[0]
                                    $KeySpecName = switch ($KeySpec) {
                                        1 { "AT_KEYEXCHANGE (Key Exchange)" }
                                        2 { "AT_SIGNATURE (Digital Signature)" }
                                        default { "Unknown ($KeySpec)" }
                                    }
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $KeySpecName
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'msrassavedframedipaddress') {
                                # Convert IP address from signed Int32 to dotted decimal notation
                                try {
                                    $IPBytes = [BitConverter]::GetBytes([Int32]$PropValue[0])
                                    $IPAddr = [System.Net.IPAddress]::new($IPBytes)
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $IPAddr.ToString()
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'msexchversion') {
                                # Convert Exchange Version to readable format
                                try {
                                    $Version = [Int64]$PropValue[0]
                                    $Major = ($Version -shr 48) -band 0xFFFF
                                    $Minor = ($Version -shr 32) -band 0xFFFF
                                    $Build = ($Version -shr 16) -band 0xFFFF
                                    $Revision = $Version -band 0xFFFF
                                    $VersionString = "$Major.$Minor.$Build.$Revision"
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $VersionString
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'msexchelcmailboxflags') {
                                # Convert Exchange ELC Mailbox Flags to readable flags
                                try {
                                    $ELCFlags = [Int32]$PropValue[0]
                                    $ELCFlagList = @()

                                    if ($ELCFlags -band 1) { $ELCFlagList += "MRM_POLICY_APPLIED" }
                                    if ($ELCFlags -band 2) { $ELCFlagList += "SINGLE_ITEM_RECOVERY" }
                                    if ($ELCFlags -band 4) { $ELCFlagList += "CALENDAR_VERSION_STORE" }
                                    if ($ELCFlags -band 8) { $ELCFlagList += "LITIGATION_HOLD" }
                                    if ($ELCFlags -band 16) { $ELCFlagList += "DUMPSTER_EXTENDED" }
                                    if ($ELCFlags -band 32) { $ELCFlagList += "SITE_MAILBOX_HOLD" }
                                    if ($ELCFlags -band 64) { $ELCFlagList += "ARCHIVE_ENABLED" }
                                    if ($ELCFlags -band 128) { $ELCFlagList += "ELC_PROCESSING_DISABLED" }

                                    if ($ELCFlagList.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $ELCFlagList
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @("NONE")
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -eq 'gplink') {
                                # GPO links - format for readability
                                try {
                                    $GPLinkString = $PropValue[0]

                                    # Parse GPO links: [LDAP://cn={GUID},cn=policies,cn=system,DC=...;LinkOptions]
                                    $GPLinks = @()
                                    $Pattern = '(?i)\[LDAP://cn=\{([^\}]+)\}[^\]]+;(\d+)\]'
                                    $GPLinkMatches = [regex]::Matches($GPLinkString, $Pattern)

                                    foreach ($Match in $GPLinkMatches) {
                                        $GUID = $Match.Groups[1].Value
                                        $LinkOptions = [int]$Match.Groups[2].Value

                                        # Link options: 0 = Enabled, 1 = Disabled, 2 = Enforced, 3 = Disabled+Enforced
                                        $Status = if ($LinkOptions -band 1) { "Disabled" } else { "Enabled" }
                                        if ($LinkOptions -band 2) { $Status += " (Enforced)" }

                                        $GPLinks += "GPO {$GUID} [$Status]"
                                    }

                                    if ($GPLinks.Count -gt 0) {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $GPLinks
                                    } else {
                                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                    }
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } elseif ($PropNameLower -match '^msexch.*quota$' -or $PropNameLower -eq 'mdbstoragequota' -or $PropNameLower -eq 'mdboverquotalimit' -or $PropNameLower -eq 'mdboverhardquotalimit') {
                                # Convert Exchange quota attributes from bytes to human-readable format
                                try {
                                    $QuotaBytes = [Int64]$PropValue[0]

                                    if ($QuotaBytes -eq 0) {
                                        $QuotaString = "Unlimited"
                                    } elseif ($QuotaBytes -lt 1KB) {
                                        $QuotaString = "$QuotaBytes bytes"
                                    } elseif ($QuotaBytes -lt 1MB) {
                                        $QuotaKB = [Math]::Round($QuotaBytes / 1KB, 2)
                                        $QuotaString = "$QuotaKB KB"
                                    } elseif ($QuotaBytes -lt 1GB) {
                                        $QuotaMB = [Math]::Round($QuotaBytes / 1MB, 2)
                                        $QuotaString = "$QuotaMB MB"
                                    } elseif ($QuotaBytes -lt 1TB) {
                                        $QuotaGB = [Math]::Round($QuotaBytes / 1GB, 2)
                                        $QuotaString = "$QuotaGB GB"
                                    } else {
                                        $QuotaTB = [Math]::Round($QuotaBytes / 1TB, 2)
                                        $QuotaString = "$QuotaTB TB"
                                    }

                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $QuotaString
                                } catch {
                                    $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                                }
                            } else {
                                # Default: add as-is
                                $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value $PropValue[0]
                            }
                        }
                    } else {
                        # Multiple values - add as array
                        $Obj | Add-Member -Force -MemberType NoteProperty -Name $PropName -Value @($PropValue)
                    }
                }

                # Sort properties alphabetically for consistent output
                $SortedPropertyNames = $Obj.PSObject.Properties.Name | Sort-Object

                $SortedObj = [PSCustomObject]@{}
                foreach ($SortedPropName in $SortedPropertyNames) {
                    $SortedObj | Add-Member -Force -MemberType NoteProperty -Name $SortedPropName -Value $Obj.$SortedPropName
                }

                [void]$OutputObjects.Add($SortedObj)
            }

            Write-Log "[Invoke-LDAPSearch] Processing completed: $($OutputObjects.Count) objects"
            return $OutputObjects

        } catch {
            # Check if it's a "not found" error (expected case when SearchBase doesn't exist)
            # Uses central error handling from adPEAS-ErrorCodes.ps1
            if (Test-LDAPErrorNotFound -Exception $_.Exception) {
                # Not an error - just no results. Return empty array silently.
                Write-Log "[Invoke-LDAPSearch] SearchBase not found: $SearchBase"
                return @()
            } else {
                # Real error - log and re-throw
                Write-Log "[Invoke-LDAPSearch] Error during LDAP search: $_"
                throw
            }
        }
    }

    end {
    }
}



# ----- Get-DomainObject.ps1 -----

function Get-DomainObject {
<#
.SYNOPSIS
    Universal function for querying ANY Active Directory object.

.DESCRIPTION
    Get-DomainObject is a flexible helper function that can query ANY AD object type without needing to know the object class beforehand.
    It supports:

    - Search by Identity (sAMAccountName, DN, SID, GUID, DOMAIN\name)
    - Search by ObjectClass (user, computer, group, contact, organizationalUnit, etc.)
    - Flexible property selection
    - Custom LDAP filters
    - LDAP-optimized account status filters (IsEnabled, IsDisabled, etc.)
    - nTSecurityDescriptor is automatically loaded and converted when querying all properties

    This is useful when you don't know the object type in advance (e.g., resolving ACEs, memberOf attributes, or forensic analysis).

.PARAMETER Identity
    sAMAccountName, DistinguishedName, SID, ObjectGUID, or DOMAIN\name format.
    Wildcards are supported for sAMAccountName.

.PARAMETER ObjectClass
    Filter by specific object class (e.g., "user", "computer", "group", "contact",
    "organizationalUnit", "container", "domainDNS", etc.).

.PARAMETER LDAPFilter
    Custom LDAP filter for special queries.

.PARAMETER Properties
    Array of attribute names to return.
    Default: All default properties from Invoke-LDAPSearch.

.PARAMETER ShowOwner
    Include Owner and OwnerSID properties on returned objects.
    Use Get-ObjectOwner -NonDefaultOnly to filter for non-default owners.

.PARAMETER SearchBase
    Alternative SearchBase (DN). Default: Domain DN.

.PARAMETER Scope
    Search scope: Subtree (default), OneLevel, or Base.
    - Subtree: Search the entire subtree (default)
    - OneLevel: Search only immediate children
    - Base: Search only the base object itself

.PARAMETER Raw
    Switch to return raw LDAP values without conversions (passed through to Invoke-LDAPSearch).
    Use this for performance when programmatically processing results.

.PARAMETER IsEnabled
    LDAP-optimized filter: Return only enabled accounts (ACCOUNTDISABLE flag NOT set).
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER IsDisabled
    LDAP-optimized filter: Return only disabled accounts (ACCOUNTDISABLE flag set).
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER PasswordNeverExpires
    LDAP-optimized filter: Return only accounts with PASSWORD_NEVER_EXPIRES flag set.
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER PasswordNotRequired
    LDAP-optimized filter: Return only accounts with PASSWORD_NOT_REQUIRED flag set.
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER TrustedForDelegation
    LDAP-optimized filter: Return only accounts with TRUSTED_FOR_DELEGATION flag set.
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER TrustedToAuthForDelegation
    LDAP-optimized filter: Return only accounts with TRUSTED_TO_AUTH_FOR_DELEGATION flag set.
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER HasSPN
    LDAP-optimized filter: Return only accounts with servicePrincipalName attribute set.
    Useful for finding Kerberoastable accounts.

.PARAMETER AdminCount
    LDAP-optimized filter: Return only accounts with adminCount=1.
    Indicates accounts that are/were members of privileged groups.

.PARAMETER PasswordMustChange
    LDAP-optimized filter: Return only accounts where pwdLastSet=0.
    These accounts must change their password at next logon.

.PARAMETER LockedOut
    LDAP-optimized filter: Return only locked out accounts (lockoutTime > 0).

.PARAMETER SmartcardRequired
    LDAP-optimized filter: Return only accounts with SMARTCARD_REQUIRED flag set.
    Uses bitwise LDAP filter for server-side filtering (fast).

.PARAMETER AccountExpired
    Return only accounts where accountExpires is in the past.
    Note: Requires post-processing as LDAP cannot compare to current time.

.PARAMETER AccountNeverExpires
    LDAP-optimized filter: Return only accounts where accountExpires is 0 or never set.

.PARAMETER PreauthNotRequired
    LDAP-optimized filter: Return only accounts with DONT_REQ_PREAUTH flag set.
    These accounts are vulnerable to AS-REP Roasting attacks!

.PARAMETER DESOnly
    LDAP-optimized filter: Return only accounts with USE_DES_KEY_ONLY flag set.
    These accounts use weak DES encryption for Kerberos.

.PARAMETER ReversibleEncryption
    LDAP-optimized filter: Return only accounts with ENCRYPTED_TEXT_PWD_ALLOWED flag set.
    These accounts store passwords with reversible encryption - security risk!

.PARAMETER NotDelegated
    LDAP-optimized filter: Return only accounts with NOT_DELEGATED flag set.
    These accounts are protected from delegation attacks.

.EXAMPLE
    Get-DomainObject -Identity "CN=Brad Pitt,OU=Users,DC=contoso,DC=com"
    Returns any object with this DN (automatically detects if User, Group, etc.).

.EXAMPLE
    Get-DomainObject -Identity "Administrator"
    Returns any object with sAMAccountName "Administrator" (could be User or Group).

.EXAMPLE
    Get-DomainObject -Identity "S-1-5-21-...-500"
    Returns any object with this SID.

.EXAMPLE
    Get-DomainObject -ObjectClass "contact"
    Returns all Contact objects in the domain.

.EXAMPLE
    Get-DomainObject -Identity "WORKSTATION01$" -ShowOwner
    Returns the computer object with Owner and OwnerSID properties.

.EXAMPLE
    Get-DomainObject -LDAPFilter "(description=*admin*)"
    Returns all objects with "admin" in their description.

.EXAMPLE
    Get-DomainObject -ObjectClass "user" -IsEnabled -PasswordNeverExpires
    Returns all enabled user accounts with PASSWORD_NEVER_EXPIRES flag (LDAP-optimized).

.EXAMPLE
    Get-DomainObject -ObjectClass "user" -IsEnabled -HasSPN
    Returns all enabled accounts with SPNs set (potential Kerberoast targets).

.OUTPUTS
    PSCustomObject with object attributes, plus objectClass property showing type.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [Alias('distinguishedName', 'Name')]
        [string]$Identity,

        [Parameter(Mandatory=$false)]
        [string]$ObjectClass,

        [Parameter(Mandatory=$false)]
        [string]$LDAPFilter,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [switch]$ShowOwner,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [ValidateSet('Subtree', 'OneLevel', 'Base')]
        [string]$Scope = 'Subtree',

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        [Parameter(Mandatory=$false)]
        [int]$ResultLimit = 0,

        # ===== LDAP-Optimized Account Filters =====
        # These use bitwise LDAP filters for server-side filtering (fast!)

        [Parameter(Mandatory=$false)]
        [switch]$IsEnabled,

        [Parameter(Mandatory=$false)]
        [switch]$IsDisabled,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordNeverExpires,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordNotRequired,

        [Parameter(Mandatory=$false)]
        [switch]$TrustedForDelegation,

        [Parameter(Mandatory=$false)]
        [switch]$TrustedToAuthForDelegation,

        [Parameter(Mandatory=$false)]
        [switch]$HasSPN,

        [Parameter(Mandatory=$false)]
        [switch]$AdminCount,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordMustChange,

        [Parameter(Mandatory=$false)]
        [switch]$LockedOut,

        [Parameter(Mandatory=$false)]
        [switch]$SmartcardRequired,

        [Parameter(Mandatory=$false)]
        [switch]$AccountExpired,

        [Parameter(Mandatory=$false)]
        [switch]$AccountNeverExpires,

        [Parameter(Mandatory=$false)]
        [switch]$PreauthNotRequired,

        [Parameter(Mandatory=$false)]
        [switch]$DESOnly,

        [Parameter(Mandatory=$false)]
        [switch]$ReversibleEncryption,

        [Parameter(Mandatory=$false)]
        [switch]$NotDelegated,

        # Server-side password-age filter: return accounts whose password was last set at least
        # N days ago (pwdLastSet older than the threshold). pwdLastSet=0 (never set / must change)
        # is excluded. Value <= 0 disables the filter.
        [Parameter(Mandatory=$false)]
        [int]$PasswordAgeDays = 0,

        # Server-side inactivity filter: return accounts that HAVE logged in at least once but not
        # within the last N days (lastLogonTimestamp older than the threshold). Accounts that never
        # logged in are excluded (they are "never used", not "inactive" - use -NeverLoggedIn).
        # Note: lastLogonTimestamp replicates lazily (updated at most every ~9-14 days by design),
        # so this is coarse-grained; the same limitation applies to any lastLogonTimestamp query.
        # Value <= 0 disables the filter.
        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 0,

        # Server-side filter: return accounts that have never logged in (lastLogonTimestamp absent).
        [Parameter(Mandatory=$false)]
        [switch]$NeverLoggedIn
    )

    begin {
        Write-Log "[Get-DomainObject] Starting object enumeration"

        # Ensure LDAP connection exists (auto-connect if needed)
        $ConnectionParams = @{}
        if ($Domain) { $ConnectionParams['Domain'] = $Domain }
        if ($Server) { $ConnectionParams['Server'] = $Server }
        if ($Credential) { $ConnectionParams['Credential'] = $Credential }

        if (-not (Ensure-LDAPConnection @ConnectionParams)) {
            # No session - Show-NoSessionError was already called by Ensure-LDAPConnection
            # process{} will check $Script:LDAPContext and skip if not set
            return
        }

        # Reset Verbose cache for SID resolution (so user sees SID resolutions for each query)
        if ($Script:SIDVerboseCache) {
            $Script:SIDVerboseCache.Clear()
            Write-Log "[Get-DomainObject] Reset SID verbose cache for new query"
        }
    }

    process {
        # Skip processing if connection failed in begin{}
        if (-not $Script:LDAPContext) {
            return $null
        }

        try {
            # Build Filter based on what's provided
            if ($LDAPFilter -and -not $Identity -and -not $ObjectClass) {
                # Use LDAPFilter directly when it's the only filter
                $Filter = $LDAPFilter
            } else {
                # Build composite filter
                $Filter = "(objectClass=*)"

                # Build Identity filter
                if ($Identity) {
                    # Resolve cross-domain identity (if DOMAIN\name format)
                    $crossDomainInfo = Resolve-CrossDomainIdentity -Identity $Identity
                    $crossDomainQuery = $crossDomainInfo.IsCrossDomain
                    $targetDomainDN = $crossDomainInfo.TargetDomainDN
                    $targetDomainFQDN = $crossDomainInfo.TargetDomainFQDN

                    # Use the extracted identity (without domain prefix)
                    $Identity = $crossDomainInfo.Identity

                    if ($crossDomainQuery) {
                        Write-Log "[Get-DomainObject] Cross-domain query detected: $($crossDomainInfo.Domain) - using GC"
                    }

                    # Check if SID, DN, GUID, or sAMAccountName
                    if ($Identity -match '^S-1-5-.*') {
                        # SID Format - convert to hex for LDAP
                        $SIDObj = New-Object System.Security.Principal.SecurityIdentifier($Identity)
                        $SIDBytes = New-Object byte[] $SIDObj.BinaryLength
                        $SIDObj.GetBinaryForm($SIDBytes, 0)
                        $SIDHex = ($SIDBytes | ForEach-Object { '\' + $_.ToString('X2') }) -join ''
                        $IdentityFilter = "(objectSid=$SIDHex)"
                    } elseif ($Identity -match '^CN=.*|^OU=.*|^DC=.*') {
                        # Distinguished Name - MUST be RFC 4515 escaped before going into a filter.
                        # DNs legitimately contain '(' ')' (e.g. "CN=Doe\, Jane (Contractor),...")
                        # which are filter grammar characters; unescaped they produce an invalid
                        # filter and the object silently drops out of every result.
                        $escapedIdentityDN = Escape-LDAPFilterDN -DistinguishedName $Identity
                        $IdentityFilter = "(distinguishedName=$escapedIdentityDN)"
                    } elseif ($Identity -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') {
                        # GUID Format (e.g., "bf967aba-0de6-11d0-a285-00aa003049e2")
                        $GUIDObj = [System.Guid]::Parse($Identity)
                        $GUIDBytes = $GUIDObj.ToByteArray()
                        $GUIDHex = ($GUIDBytes | ForEach-Object { '\' + $_.ToString('X2') }) -join ''
                        $IdentityFilter = "(objectGUID=$GUIDHex)"
                    } else {
                        # sAMAccountName (with wildcard support)
                        # Also try cn and name attributes for objects without sAMAccountName
                        $IdentityFilter = "(|(sAMAccountName=$Identity)(cn=$Identity)(name=$Identity))"
                    }

                    # Combine base filter with identity filter
                    $Filter = "(&$Filter$IdentityFilter)"
                }

                # ObjectClass filter (if specified)
                if ($ObjectClass) {
                    $Filter = "(&$Filter(objectClass=$ObjectClass))"
                }

                # Append custom LDAP filter (only when combined with Identity or ObjectClass)
                if ($LDAPFilter) {
                    $Filter = "(&$Filter$LDAPFilter)"
                }
            }

            # ===== Apply LDAP-optimized account filters =====
            # These use LDAP_MATCHING_RULE_BIT_AND (1.2.840.113556.1.4.803) for bitwise AND
            # or LDAP_MATCHING_RULE_BIT_OR (1.2.840.113556.1.4.804) for bitwise OR

            $accountFilters = @()

            # IsEnabled: ACCOUNTDISABLE (0x0002) flag NOT set
            if ($IsEnabled) {
                $accountFilters += "(!(userAccountControl:1.2.840.113556.1.4.803:=2))"
            }

            # IsDisabled: ACCOUNTDISABLE (0x0002) flag IS set
            if ($IsDisabled) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=2)"
            }

            # PasswordNeverExpires: DONT_EXPIRE_PASSWD (0x10000 = 65536) flag set
            if ($PasswordNeverExpires) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=65536)"
            }

            # PasswordNotRequired: PASSWD_NOTREQD (0x0020 = 32) flag set
            if ($PasswordNotRequired) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=32)"
            }

            # TrustedForDelegation: TRUSTED_FOR_DELEGATION (0x80000 = 524288) flag set
            if ($TrustedForDelegation) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=524288)"
            }

            # TrustedToAuthForDelegation: TRUSTED_TO_AUTH_FOR_DELEGATION (0x1000000 = 16777216) flag set
            if ($TrustedToAuthForDelegation) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=16777216)"
            }

            # HasSPN: servicePrincipalName attribute exists
            if ($HasSPN) {
                $accountFilters += "(servicePrincipalName=*)"
            }

            # AdminCount: adminCount = 1
            if ($AdminCount) {
                $accountFilters += "(adminCount=1)"
            }

            # PasswordMustChange: pwdLastSet = 0 (user must change password at next logon)
            if ($PasswordMustChange) {
                $accountFilters += "(pwdLastSet=0)"
            }

            # LockedOut: lockoutTime > 0 (account is locked)
            if ($LockedOut) {
                $accountFilters += "(lockoutTime>=1)"
            }

            # SmartcardRequired: SMARTCARD_REQUIRED (0x40000 = 262144) flag set
            if ($SmartcardRequired) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=262144)"
            }

            # AccountExpired: accountExpires is set and in the past
            # Note: This requires post-processing as LDAP can't compare timestamps to "now"
            # We filter for accounts where accountExpires is set (not 0 or never)
            if ($AccountExpired) {
                # accountExpires = 0 or 9223372036854775807 means never expires
                # We get accounts with expiration set, then filter in post-processing
                $accountFilters += "(&(accountExpires>=1)(!(accountExpires=9223372036854775807)))"
                $Script:FilterAccountExpired = $true
            }

            # AccountNeverExpires: accountExpires = 0 or 9223372036854775807 (never/not set)
            if ($AccountNeverExpires) {
                $accountFilters += "(|(accountExpires=0)(accountExpires=9223372036854775807))"
            }

            # PreauthNotRequired: DONT_REQ_PREAUTH (0x400000 = 4194304) flag set - AS-REP Roastable!
            if ($PreauthNotRequired) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=4194304)"
            }

            # DESOnly: USE_DES_KEY_ONLY (0x200000 = 2097152) flag set - weak encryption
            if ($DESOnly) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=2097152)"
            }

            # ReversibleEncryption: ENCRYPTED_TEXT_PWD_ALLOWED (0x80 = 128) flag set
            if ($ReversibleEncryption) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=128)"
            }

            # NotDelegated: NOT_DELEGATED (0x100000 = 1048576) flag set - protected from delegation
            if ($NotDelegated) {
                $accountFilters += "(userAccountControl:1.2.840.113556.1.4.803:=1048576)"
            }

            # PasswordAgeDays: password last set at least N days ago (pwdLastSet <= threshold).
            # pwdLastSet is a FileTime; (pwdLastSet>=1) excludes 0 (never set / must change).
            if ($PasswordAgeDays -gt 0) {
                $pwdThresholdFileTime = (Get-Date).AddDays(-$PasswordAgeDays).ToFileTime()
                $accountFilters += "(&(pwdLastSet>=1)(pwdLastSet<=$pwdThresholdFileTime))"
            }

            # InactiveDays: has logged in once (lastLogonTimestamp present) but not within N days.
            # An LDAP ordering match (<=) never matches an absent attribute, so this inherently
            # excludes never-logged-in accounts; (lastLogonTimestamp>=1) makes that explicit.
            if ($InactiveDays -gt 0) {
                $logonThresholdFileTime = (Get-Date).AddDays(-$InactiveDays).ToFileTime()
                $accountFilters += "(&(lastLogonTimestamp>=1)(lastLogonTimestamp<=$logonThresholdFileTime))"
            }

            # NeverLoggedIn: lastLogonTimestamp attribute is absent (account never authenticated).
            if ($NeverLoggedIn) {
                $accountFilters += "(!(lastLogonTimestamp=*))"
            }

            # Append all account filters to main filter
            if ($accountFilters.Count -gt 0) {
                $allAccountFilters = $accountFilters -join ''
                $Filter = "(&$Filter$allAccountFilters)"
                Write-Log "[Get-DomainObject] Applied LDAP-optimized filters: $($accountFilters -join ', ')"
            }

            Write-Log "[Get-DomainObject] Using filter: $Filter"

            # Prepare Invoke-LDAPSearch parameters
            $SearchParams = @{
                Filter = $Filter
            }

            if ($Properties) {
                $SearchParams['Properties'] = $Properties
            }

            # If ShowOwner is set, ensure nTSecurityDescriptor is loaded
            # (nTSecurityDescriptor is automatically converted by Invoke-LDAPSearch when requested)
            if ($ShowOwner) {
                if ($Properties) {
                    # Add nTSecurityDescriptor to Properties if not already present
                    if ($Properties -inotcontains 'nTSecurityDescriptor') {
                        $SearchParams['Properties'] = $Properties + 'nTSecurityDescriptor'
                    }
                } else {
                    # Use AdditionalProperties to load nTSecurityDescriptor alongside all other properties
                    $SearchParams['AdditionalProperties'] = @('nTSecurityDescriptor')
                }
                Write-Log "[Get-DomainObject] ShowOwner enabled - nTSecurityDescriptor will be included in results"
            }

            # Set SearchBase: cross-domain DN takes precedence over user-specified SearchBase
            if ($targetDomainDN) {
                $SearchParams['SearchBase'] = $targetDomainDN
                Write-Log "[Get-DomainObject] Using cross-domain SearchBase: $targetDomainDN"
            } elseif ($SearchBase) {
                $SearchParams['SearchBase'] = $SearchBase
            }

            if ($Scope) {
                $SearchParams['Scope'] = $Scope
            }

            if ($Raw) {
                $SearchParams['Raw'] = $true
            }

            if ($ResultLimit -gt 0) {
                $SearchParams['SizeLimit'] = $ResultLimit
            }

            # For cross-domain queries, use Global Catalog
            if ($crossDomainQuery) {
                $gcConn = Get-GCConnection
                if ($gcConn) {
                    Write-Log "[Get-DomainObject] Using GC connection for cross-domain query"
                    $SearchParams['LdapConnection'] = $gcConn
                    # Keep SearchBase if set (for domain-specific cross-domain queries)
                    # Only remove if not set by cross-domain logic (= forest-wide fallback)
                    if (-not $targetDomainDN -and $SearchParams.ContainsKey('SearchBase')) {
                        $SearchParams.Remove('SearchBase')
                        Write-Log "[Get-DomainObject] Removed SearchBase for forest-wide fallback"
                    }
                } else {
                    Write-Log "[Get-DomainObject] GC connection unavailable - query may return incorrect results" -Level Warning
                }
            }

            # Execute search
            $Objects = @(Invoke-LDAPSearch @SearchParams)

            Write-Log "[Get-DomainObject] Found $($Objects.Count) object(s)"

            # Post-processing for cross-domain queries: filter out child domains
            # SearchBase with Subtree scope includes child domains (e.g., DC=dev,DC=contoso,DC=com when searching DC=contoso,DC=com)
            # We use Test-DomainMatch to extract domain FQDN from distinguishedName (DN) and compare with target domain
            if ($targetDomainFQDN -and $Objects.Count -gt 0) {
                $FilteredObjects = @()

                foreach ($Obj in $Objects) {
                    if ($Obj.distinguishedName) {
                        # Use centralized Test-DomainMatch function for domain filtering
                        if (Test-DomainMatch -DistinguishedName $Obj.distinguishedName -TargetDomainFQDN $targetDomainFQDN) {
                            $FilteredObjects += $Obj
                        }
                        # Test-DomainMatch logs mismatches internally, no need for extra logging here
                    } else {
                        # Fallback: if DN missing (shouldn't happen), include object
                        Write-Log "[Get-DomainObject] Warning: Object has no distinguishedName - including anyway" -Level Warning
                        $FilteredObjects += $Obj
                    }
                }

                $Objects = $FilteredObjects
                Write-Log "[Get-DomainObject] After cross-domain post-filter: $($Objects.Count) object(s)"
            }

            # Post-processing for AccountExpired filter (LDAP can't compare to "now")
            if ($AccountExpired -and $Objects.Count -gt 0) {
                $Now = [DateTime]::UtcNow
                $NowFileTime = $Now.ToFileTimeUtc()
                $FilteredObjects = @()

                foreach ($Obj in $Objects) {
                    if ($Obj.accountExpires) {
                        try {
                            $ExpireTime = $Obj.accountExpires
                            # Convert to Int64 if it's a string
                            if ($ExpireTime -is [string]) {
                                $ExpireTime = [Int64]::Parse($ExpireTime)
                            }
                            # Check if expired (value is less than now)
                            if ($ExpireTime -lt $NowFileTime) {
                                $FilteredObjects += $Obj
                            }
                        } catch {
                            Write-Log "[Get-DomainObject] Error parsing accountExpires for '$($Obj.distinguishedName)': $_"
                        }
                    }
                }

                $Objects = $FilteredObjects
                Write-Log "[Get-DomainObject] After AccountExpired post-filter: $($Objects.Count) object(s)"
            }

            # If ShowOwner is set, add Owner properties from nTSecurityDescriptor.Owner
            if ($ShowOwner) {
                Write-Log "[Get-DomainObject] Adding Owner properties to objects..."

                foreach ($Object in $Objects) {
                    # Owner is now part of the unified nTSecurityDescriptor structure
                    if ($Object.nTSecurityDescriptor -and $Object.nTSecurityDescriptor.Owner) {
                        # Add user-facing properties (Owner and OwnerSID only)
                        $Object | Add-Member -NotePropertyName 'Owner' -NotePropertyValue $Object.nTSecurityDescriptor.Owner.Name -Force
                        $Object | Add-Member -NotePropertyName 'OwnerSID' -NotePropertyValue $Object.nTSecurityDescriptor.Owner.SID -Force

                        Write-Log "[Get-DomainObject] Owner for '$($Object.distinguishedName)': $($Object.nTSecurityDescriptor.Owner.Name)"
                    } else {
                        Write-Log "[Get-DomainObject] No owner info in nTSecurityDescriptor for '$($Object.distinguishedName)'"
                    }
                }
            }

            return $Objects

        } catch {
            Write-Log "[Get-DomainObject] Error: $_"
            throw
        }
    }

    end {
        Write-Log "[Get-DomainObject] Object enumeration completed"
    }
}



# ----- Get-ObjectACL.ps1 -----

function Get-ObjectACL {
<#
.SYNOPSIS
    Retrieves and analyzes Access Control Lists (ACLs) from Active Directory objects.

.DESCRIPTION
    Get-ObjectACL is a central function for ACL analysis in adPEAS v2. It provides:

    - Direct ACL retrieval for any AD object (user, computer, group, OU, GPO, etc.)
    - Filtering by trustee, rights, extended rights
    - Dangerous ACE detection (GenericAll, WriteDacl, WriteOwner, etc.)
    - Pipeline support for batch analysis
    - Integration with ConvertTo-FormattedACE for human-readable output

    This function is designed to be used by:
    - Check modules (Get-DangerousACLs, Get-DangerousOUPermissions, etc.)
    - Direct command-line analysis by pentesters/admins
    - Other Core modules via -ShowACE parameter

    Well-Known Dangerous Rights:
    - GenericAll: Full control over object
    - GenericWrite: Modify most attributes
    - WriteDacl: Modify object's ACL
    - WriteOwner: Take ownership of object
    - WriteProperty: Modify specific attributes
    - ExtendedRight: Includes DCSync, ForceChangePassword, etc.

.PARAMETER Identity
    Target object identity. Accepts:
    - sAMAccountName (e.g., "Administrator", "DC01$")
    - DistinguishedName (e.g., "CN=Domain Admins,CN=Users,DC=contoso,DC=com")
    - SID (e.g., "S-1-5-21-...")
    - GUID (e.g., "{12345678-1234-...}")

.PARAMETER DistinguishedName
    Direct DN specification (alternative to -Identity).

.PARAMETER Trustee
    Filter ACEs by trustee name or SID. Supports wildcards.
    Example: -Trustee "CONTOSO\helpdesk*"

.PARAMETER ExcludeTrustee
    Exclude ACEs for specified trustees. Useful for filtering out well-known admins.
    Example: -ExcludeTrustee "NT AUTHORITY\SYSTEM","CONTOSO\Domain Admins"

.PARAMETER Rights
    Filter for specific rights.
    Example: -Rights "GenericAll","WriteDacl","WriteOwner"

.PARAMETER ExtendedRight
    Filter for specific extended rights by name.
    Example: -ExtendedRight "DS-Replication-Get-Changes-All"

.PARAMETER DangerousOnly
    Only return ACEs with dangerous rights:
    - GenericAll, GenericWrite, WriteDacl, WriteOwner
    - WriteProperty, Self, ExtendedRight
    - Delete, DeleteTree, CreateChild, DeleteChild

.PARAMETER WriteOnly
    Only return ACEs with write permissions:
    - GenericAll, GenericWrite, WriteDacl, WriteOwner, WriteProperty

.PARAMETER ExtendedRightsOnly
    Only return ACEs with ExtendedRight flag set.

.PARAMETER ExplicitOnly
    Exclude inherited ACEs, show only explicit permissions.

.PARAMETER AllowOnly
    Only return Allow ACEs (exclude Deny).

.PARAMETER DenyOnly
    Only return Deny ACEs (exclude Allow).

.PARAMETER IncludeObjectInfo
    Include object information (DN, objectClass) in output.

.PARAMETER NoResolveGUIDs
    If set, skips GUID-to-Name resolution for ObjectType and InheritedObjectType.
    By default, GUIDs are resolved to friendly names (e.g., "DS-Replication-Get-Changes").

.PARAMETER NoResolveSIDs
    If set, skips SID-to-Name resolution and displays raw SIDs instead.
    By default, SIDs are resolved to friendly names (e.g., "CONTOSO\Domain Admins").

.PARAMETER Domain
    Target domain (FQDN).

.PARAMETER Server
    Specific Domain Controller to query.

.PARAMETER Credential
    PSCredential object for authentication.

.EXAMPLE
    Get-ObjectACL -Identity "Domain Admins"
    Returns all ACEs for the Domain Admins group.

.EXAMPLE
    Get-ObjectACL -Identity "CN=AdminSDHolder,CN=System,DC=contoso,DC=com" -DangerousOnly
    Returns only dangerous ACEs on the AdminSDHolder object.

.EXAMPLE
    Get-ObjectACL -Identity "krbtgt" -Trustee "CONTOSO\helpdesk"
    Returns ACEs where helpdesk has permissions on krbtgt.

.EXAMPLE
    Get-DomainUser -AdminCount | Get-ObjectACL -DangerousOnly -ExcludeTrustee "NT AUTHORITY\SYSTEM"
    Batch analysis: Get dangerous ACEs on all admin users.

.EXAMPLE
    Get-ObjectACL -Identity $domainDN -ExtendedRight "DS-Replication-Get-Changes-All"
    Find who has DCSync rights on the domain.

.EXAMPLE
    Get-ObjectACL -Identity "OU=Servers,DC=contoso,DC=com" -WriteOnly -ExplicitOnly
    Find explicit write permissions on the Servers OU.

.OUTPUTS
    PSCustomObject with properties:
    - ObjectDN: Distinguished Name of the target object
    - ObjectClass: Object class (user, group, computer, etc.)
    - Owner: ACL owner (resolved name)
    - OwnerSID: ACL owner SID
    - ACEs: Array of filtered ACE objects

    Each ACE object contains:
    - AccessControlType: Allow/Deny
    - Trustee: Resolved trustee name
    - TrusteeSID: Trustee SID
    - Rights: Formatted rights string
    - RightsRaw: Array of individual rights
    - ObjectType: GUID of property/extended right (if applicable)
    - ObjectTypeName: Resolved name (if ResolveGUIDs)
    - InheritedObjectType: GUID for inheritance filter
    - IsInherited: Boolean indicating if ACE is inherited
    - InheritanceFlags: Inheritance flag details
    - PropagationFlags: Propagation flag details

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(DefaultParameterSetName='Identity')]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true, ParameterSetName='Identity')]
        [Alias('samAccountName', 'Name')]
        [string]$Identity,

        [Parameter(ValueFromPipelineByPropertyName=$true, ParameterSetName='DN')]
        [Alias('DN')]
        [string]$DistinguishedName,

        # ACE Filters
        [Parameter(Mandatory=$false)]
        [string[]]$Trustee,

        [Parameter(Mandatory=$false)]
        [string[]]$ExcludeTrustee,

        [Parameter(Mandatory=$false)]
        [ValidateSet('GenericAll', 'GenericRead', 'GenericWrite', 'GenericExecute',
                     'CreateChild', 'DeleteChild', 'ListChildren', 'Self',
                     'ReadProperty', 'WriteProperty', 'DeleteTree', 'ListObject',
                     'ExtendedRight', 'Delete', 'ReadControl', 'WriteDacl', 'WriteOwner', 'Synchronize')]
        [string[]]$Rights,

        [Parameter(Mandatory=$false)]
        [string[]]$ExtendedRight,

        # Convenience Switches
        [Parameter(Mandatory=$false)]
        [switch]$DangerousOnly,

        [Parameter(Mandatory=$false)]
        [switch]$WriteOnly,

        [Parameter(Mandatory=$false)]
        [switch]$ExtendedRightsOnly,

        [Parameter(Mandatory=$false)]
        [switch]$ExplicitOnly,

        [Parameter(Mandatory=$false)]
        [switch]$AllowOnly,

        [Parameter(Mandatory=$false)]
        [switch]$DenyOnly,

        # Output Options
        [Parameter(Mandatory=$false)]
        [switch]$IncludeObjectInfo,

        [Parameter(Mandatory=$false)]
        [switch]$NoResolveGUIDs,

        [Parameter(Mandatory=$false)]
        [switch]$NoResolveSIDs,

        # Connection Parameters
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ObjectACL] Starting ACL enumeration"
    }

    process {
        try {
            # Build connection parameters
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return $null
            }

            # Determine target DN
            $targetDN = $null
            $targetObject = $null

            if ($DistinguishedName) {
                $targetDN = $DistinguishedName
            }
            elseif ($Identity) {
                # Check if Identity is already a DN
                if ($Identity -match '^(CN|OU|DC)=') {
                    $targetDN = $Identity
                }
                else {
                    # Resolve Identity to DN via Get-DomainObject
                    # Use -Raw to get nTSecurityDescriptor as byte[] instead of converted format
                    $targetObject = @(Get-DomainObject -Identity $Identity -Properties 'distinguishedName','objectClass','nTSecurityDescriptor' -Raw @connectionParams)[0]
                    if (-not $targetObject) {
                        Write-Warning "[Get-ObjectACL] Object not found: $Identity"
                        return $null
                    }
                    $targetDN = $targetObject.distinguishedName
                }
            }
            else {
                Write-Warning "[Get-ObjectACL] No Identity or DistinguishedName specified"
                return $null
            }

            Write-Log "[Get-ObjectACL] Target DN: $targetDN"

            # Get object with nTSecurityDescriptor if not already loaded
            if (-not $targetObject -or -not $targetObject.nTSecurityDescriptor) {
                # Use -Raw to get nTSecurityDescriptor as byte[] instead of converted format
                $targetObject = @(Get-DomainObject -Identity $targetDN -Properties 'distinguishedName','objectClass','nTSecurityDescriptor' -Raw @connectionParams)[0]
                if (-not $targetObject) {
                    Write-Warning "[Get-ObjectACL] Failed to retrieve object: $targetDN"
                    return $null
                }
            }

            # Check if nTSecurityDescriptor is available
            if (-not $targetObject.nTSecurityDescriptor) {
                Write-Warning "[Get-ObjectACL] No nTSecurityDescriptor available for: $targetDN (access denied or not present)"
                return $null
            }

            # Parse security descriptor
            $securityDescriptor = $targetObject.nTSecurityDescriptor

            # Handle if already parsed by Get-DomainObject -ShowACE
            if ($securityDescriptor -is [PSCustomObject] -and $securityDescriptor.ACEs) {
                $parsedSD = $securityDescriptor
            }
            elseif ($securityDescriptor -is [System.DirectoryServices.ActiveDirectorySecurity] -or
                    $securityDescriptor -is [byte[]] -or
                    ($securityDescriptor -is [System.Array] -and -not ($securityDescriptor -is [byte[]]))) {
                # Parse via shared helper (handles byte[], ActiveDirectorySecurity, and array-wrapped bytes)
                $sdParsed = ConvertTo-AccessRules -SecurityDescriptorBytes $securityDescriptor
                if (-not $sdParsed) {
                    Write-Warning "[Get-ObjectACL] Failed to parse nTSecurityDescriptor for: $targetDN"
                    return $null
                }

                $OwnerSID = $sdParsed.OwnerSID
                $OwnerName = if (-not $NoResolveSIDs) { ConvertFrom-SID -SID $OwnerSID } else { $OwnerSID }
                $DACL = $sdParsed.AccessRules

                # Parse ACEs with extended information
                $ACEList = @()

                foreach ($ACE in $DACL) {
                    $TrusteeSID = $ACE.IdentityReference.Value
                    $TrusteeName = if (-not $NoResolveSIDs) { ConvertFrom-SID -SID $TrusteeSID } else { $TrusteeSID }

                    # Parse rights
                    $RightsArray = @()
                    $ADRights = $ACE.ActiveDirectoryRights

                    # Use central AllActiveDirectoryRights from adPEAS-GUIDs.ps1
                    foreach ($Right in $Script:AllActiveDirectoryRights) {
                        # IMPORTANT: Check if ALL bits of the right are set, not just ANY overlap
                        # Using ($ADRights -band $Right) -eq $Right instead of just ($ADRights -band $Right)
                        # because the latter returns true if ANY bits match (e.g., ReadProperty 0x10
                        # would falsely match GenericAll 0xF01FF since they share bits)
                        if (($ADRights -band $Right) -eq $Right) {
                            $RightsArray += $Right.ToString()
                        }
                    }

                    # Resolve ObjectType GUID (extended rights, property sets)
                    $ObjectTypeGuid = if ($ACE.ObjectType -and $ACE.ObjectType -ne [System.Guid]::Empty) {
                        $ACE.ObjectType.ToString()
                    } else { $null }

                    $ObjectTypeName = $null
                    if ($ObjectTypeGuid -and (-not $NoResolveGUIDs)) {
                        # Use central GUID resolution from adPEAS-GUIDs.ps1
                        $ObjectTypeName = Get-ExtendedRightName -GUID $ObjectTypeGuid
                    }

                    # Add extended right name to rights array if applicable
                    if ($ObjectTypeName -and ($RightsArray -contains 'ExtendedRight')) {
                        $RightsArray = $RightsArray | Where-Object { $_ -ne 'ExtendedRight' }
                        $RightsArray += $ObjectTypeName
                    }

                    # InheritedObjectType
                    $InheritedObjectTypeGuid = if ($ACE.InheritedObjectType -and $ACE.InheritedObjectType -ne [System.Guid]::Empty) {
                        $ACE.InheritedObjectType.ToString()
                    } else { $null }

                    # Build ACE object with extended info
                    $ACEObj = [PSCustomObject]@{
                        AccessControlType    = $ACE.AccessControlType.ToString()
                        Trustee              = $TrusteeName
                        TrusteeSID           = $TrusteeSID
                        Rights               = ($RightsArray -join ', ')
                        RightsRaw            = $RightsArray
                        ObjectType           = $ObjectTypeGuid
                        ObjectTypeName       = $ObjectTypeName
                        InheritedObjectType  = $InheritedObjectTypeGuid
                        IsInherited          = $ACE.IsInherited
                        InheritanceFlags     = $ACE.InheritanceFlags.ToString()
                        PropagationFlags     = $ACE.PropagationFlags.ToString()
                    }

                    $ACEList += $ACEObj
                }

                $parsedSD = [PSCustomObject]@{
                    Owner    = $OwnerName
                    OwnerSID = $OwnerSID
                    ACEs     = $ACEList
                }
            }
            else {
                Write-Warning "[Get-ObjectACL] Unknown nTSecurityDescriptor format for: $targetDN (Type: $($securityDescriptor.GetType().FullName))"
                return $null
            }

            # Apply filters to ACEs
            $filteredACEs = $parsedSD.ACEs

            # Filter: AllowOnly / DenyOnly
            if ($AllowOnly) {
                $filteredACEs = $filteredACEs | Where-Object { $_.AccessControlType -eq 'Allow' }
            }
            if ($DenyOnly) {
                $filteredACEs = $filteredACEs | Where-Object { $_.AccessControlType -eq 'Deny' }
            }

            # Filter: ExplicitOnly (exclude inherited)
            if ($ExplicitOnly) {
                $filteredACEs = $filteredACEs | Where-Object { $_.IsInherited -eq $false }
            }

            # Filter: Trustee
            if ($Trustee) {
                $filteredACEs = $filteredACEs | Where-Object {
                    $ace = $_
                    $matchFound = $false
                    foreach ($t in $Trustee) {
                        if ($ace.Trustee -like $t -or $ace.TrusteeSID -like $t) {
                            $matchFound = $true
                            break
                        }
                    }
                    $matchFound
                }
            }

            # Filter: ExcludeTrustee
            if ($ExcludeTrustee) {
                $filteredACEs = $filteredACEs | Where-Object {
                    $ace = $_
                    $excluded = $false
                    foreach ($t in $ExcludeTrustee) {
                        if ($ace.Trustee -like $t -or $ace.TrusteeSID -like $t) {
                            $excluded = $true
                            break
                        }
                    }
                    -not $excluded
                }
            }

            # Filter: DangerousOnly
            if ($DangerousOnly) {
                $filteredACEs = $filteredACEs | Where-Object {
                    $ace = $_
                    $hasDangerous = $false
                    foreach ($right in $ace.RightsRaw) {
                        if ($Script:DangerousRights -contains $right) {
                            $hasDangerous = $true
                            break
                        }
                        # Also check for dangerous extended rights
                        if ($right -match 'DS-Replication|Force-Change-Password|All-Extended-Rights') {
                            $hasDangerous = $true
                            break
                        }
                    }
                    $hasDangerous
                }
            }

            # Filter: WriteOnly
            if ($WriteOnly) {
                $filteredACEs = $filteredACEs | Where-Object {
                    $ace = $_
                    $hasWrite = $false
                    foreach ($right in $ace.RightsRaw) {
                        if ($Script:WriteRights -contains $right) {
                            $hasWrite = $true
                            break
                        }
                    }
                    $hasWrite
                }
            }

            # Filter: ExtendedRightsOnly
            if ($ExtendedRightsOnly) {
                $filteredACEs = $filteredACEs | Where-Object {
                    ($_.RightsRaw -contains 'ExtendedRight') -or ($null -ne $_.ObjectTypeName)
                }
            }

            # Filter: Rights
            if ($Rights) {
                $filteredACEs = $filteredACEs | Where-Object {
                    $ace = $_
                    $hasRight = $false
                    foreach ($right in $Rights) {
                        if ($ace.RightsRaw -contains $right) {
                            $hasRight = $true
                            break
                        }
                    }
                    $hasRight
                }
            }

            # Filter: ExtendedRight (by name)
            if ($ExtendedRight) {
                $filteredACEs = $filteredACEs | Where-Object {
                    $ace = $_
                    $hasExtRight = $false
                    foreach ($extRight in $ExtendedRight) {
                        if ($ace.ObjectTypeName -like $extRight -or $ace.RightsRaw -contains $extRight) {
                            $hasExtRight = $true
                            break
                        }
                    }
                    $hasExtRight
                }
            }

            # Build result object
            $result = [PSCustomObject]@{
                ObjectDN    = $targetDN
                ObjectClass = if ($targetObject.objectClass) {
                    if ($targetObject.objectClass -is [array]) { $targetObject.objectClass[-1] }
                    else { $targetObject.objectClass }
                } else { "Unknown" }
                Owner       = $parsedSD.Owner
                OwnerSID    = $parsedSD.OwnerSID
                ACECount    = @($filteredACEs).Count
                ACEs        = @($filteredACEs)
            }

            Write-Log "[Get-ObjectACL] Found $($result.ACECount) ACE(s) after filtering for: $targetDN"

            return $result

        } catch {
            Write-Log "[Get-ObjectACL] Error: $_"
            Write-Error "[Get-ObjectACL] Failed to get ACL for object: $_"
            return $null
        }
    }

    end {
        Write-Log "[Get-ObjectACL] ACL enumeration completed"
    }
}



# ----- Set-DomainObject.ps1 -----

function Set-DomainObject {
<#
.SYNOPSIS
    Universal function for modifying ANY Active Directory object (attributes and ACLs).

.DESCRIPTION
    Set-DomainObject is a flexible helper function that can modify ANY AD object attribute AND Access Control Lists (ACLs) without needing to know the object
    class beforehand. It supports:

    ATTRIBUTE OPERATIONS:
    - Set/Replace/Append/Remove/Clear attribute operations
    - Multiple attributes in single operation

    ACL OPERATIONS:
    - Grant ACE (Allow permissions)
    - Revoke ACE (Remove permissions)
    - Deny ACE (Explicit deny)
    - Set Owner (Change object ownership)
    - Clear ACE (Remove all ACEs for a principal)

.PARAMETER Identity
    sAMAccountName, DistinguishedName, SID, ObjectGUID, or DOMAIN\name format.
    Identifies the object to modify.

.PARAMETER Set
    Hashtable of attributes to SET (replace existing values).
    Example: @{ description = "New description"; info = "Additional info" }

.PARAMETER Append
    Hashtable of attributes to APPEND (add to existing multi-valued attributes).
    Example: @{ servicePrincipalName = "HTTP/server.contoso.com" }

.PARAMETER Remove
    Hashtable of attributes to REMOVE (remove specific values).
    Example: @{ memberOf = "CN=OldGroup,DC=contoso,DC=com" }

.PARAMETER Clear
    Array of attribute names to CLEAR (remove all values).
    Example: @("description", "info")

.PARAMETER GrantACE
    Switch to grant (Allow) permissions on the object.
    Requires -Principal and either -Rights or -ExtendedRight.

.PARAMETER RevokeACE
    Switch to revoke (remove) permissions from the object.
    Requires -Principal and either -Rights or -ExtendedRight.

.PARAMETER DenyACE
    Switch to add explicit Deny permissions on the object.
    Requires -Principal and either -Rights or -ExtendedRight.

.PARAMETER SetOwner
    Switch to change the object's owner.
    Requires -Principal parameter.

.PARAMETER ClearACE
    Switch to remove ALL ACEs for a specific principal.
    Requires -Principal parameter.

.PARAMETER Principal
    Security principal (user/group) for ACE operations.
    Format: "DOMAIN\name", "name@domain.com", or DN.

.PARAMETER Rights
    ActiveDirectory rights to grant/revoke/deny.
    Valid values: GenericAll, GenericRead, GenericWrite, WriteDacl, WriteOwner,
                  CreateChild, DeleteChild, ReadProperty, WriteProperty, etc.

.PARAMETER ExtendedRight
    Extended right to grant/revoke/deny (user-friendly aliases supported).

    Common aliases:
    - DCSync              : All 3 DCSync rights (Get-Changes, Get-Changes-All, Get-Changes-In-Filtered-Set)
    - ForceChangePassword : Reset user password
    - AddMember           : Add members to group
    - SendAs              : Send email as another user
    - ReceiveAs           : Receive email as another user
    - ReadLAPSPassword    : Read LAPS password
    - AutoEnroll          : Certificate auto-enrollment

.PARAMETER Domain
    Target domain (FQDN). If not specified, uses current session or user's domain.

.PARAMETER Server
    Specific Domain Controller to connect to. If not specified, auto-discovery.

.PARAMETER Credential
    PSCredential object for authentication.

.PARAMETER PassThru
    Returns a result object instead of only console output.
    Useful for scripting and automation.

.EXAMPLE
    Set-DomainObject -Identity "CN=Brad Pitt,OU=Users,DC=contoso,DC=com" -Set @{ description = "Actor" }
    Sets the description attribute on the user object.

.EXAMPLE
    Set-DomainObject -Identity "DC=contoso,DC=com" -GrantACE -Principal "CONTOSO\BackupAdmin" -ExtendedRight "DCSync"
    Grants DCSync rights (all 3 required permissions) to BackupAdmin on the domain root.

.EXAMPLE
    Set-DomainObject -Identity "CN=TargetUser,OU=Users,DC=contoso,DC=com" -GrantACE -Principal "CONTOSO\HelpDesk" -ExtendedRight "ForceChangePassword"
    Allows HelpDesk group to reset TargetUser's password.

.EXAMPLE
    Set-DomainObject -Identity "CN=Domain Admins,CN=Users,DC=contoso,DC=com" -GrantACE -Principal "CONTOSO\attacker" -Rights "WriteDacl"
    Grants WriteDacl permission (allows modifying ACL of Domain Admins group).

.EXAMPLE
    Set-DomainObject -Identity "OU=Servers,DC=contoso,DC=com" -SetOwner -Principal "CONTOSO\IT-Admins"
    Changes the owner of the Servers OU to IT-Admins group.

.EXAMPLE
    Set-DomainObject -Identity "CN=krbtgt,CN=Users,DC=contoso,DC=com" -DenyACE -Principal "NT AUTHORITY\Authenticated Users" -Rights "WriteProperty"
    Adds explicit Deny for WriteProperty on krbtgt account.

.EXAMPLE
    Set-DomainObject -Identity "CN=CEO,OU=VIP,DC=contoso,DC=com" -GrantACE -Principal "CONTOSO\attacker" -ExtendedRight "SendAs"
    Allows attacker to send emails as the CEO.

.OUTPUTS
    Boolean - $true if successful, $false if failed.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(DefaultParameterSetName='SetAttributes')]
    param(
        # === Object Identity ===
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [Alias('distinguishedName', 'Name', 'sAMAccountName')]
        [string]$Identity,

        # === Attribute Modification Parameters (SetAttributes ParameterSet) ===
        [Parameter(Mandatory=$false, ParameterSetName='SetAttributes')]
        [hashtable]$Set,

        [Parameter(Mandatory=$false, ParameterSetName='SetAttributes')]
        [hashtable]$Append,

        [Parameter(Mandatory=$false, ParameterSetName='SetAttributes')]
        [hashtable]$Remove,

        [Parameter(Mandatory=$false, ParameterSetName='SetAttributes')]
        [string[]]$Clear,

        # === ACE Operation Switches (mutually exclusive) ===
        [Parameter(Mandatory=$true, ParameterSetName='GrantACE')]
        [switch]$GrantACE,

        [Parameter(Mandatory=$true, ParameterSetName='RevokeACE')]
        [switch]$RevokeACE,

        [Parameter(Mandatory=$true, ParameterSetName='DenyACE')]
        [switch]$DenyACE,

        [Parameter(Mandatory=$true, ParameterSetName='ClearACE')]
        [switch]$ClearACE,

        [Parameter(Mandatory=$true, ParameterSetName='SetOwner')]
        [switch]$SetOwner,

        # === ACE Parameters ===
        [Parameter(Mandatory=$true, ParameterSetName='GrantACE')]
        [Parameter(Mandatory=$true, ParameterSetName='RevokeACE')]
        [Parameter(Mandatory=$true, ParameterSetName='DenyACE')]
        [Parameter(Mandatory=$true, ParameterSetName='ClearACE')]
        [Parameter(Mandatory=$true, ParameterSetName='SetOwner')]
        [string]$Principal,

        # Rights (for GrantACE/RevokeACE/DenyACE)
        [Parameter(Mandatory=$false, ParameterSetName='GrantACE')]
        [Parameter(Mandatory=$false, ParameterSetName='RevokeACE')]
        [Parameter(Mandatory=$false, ParameterSetName='DenyACE')]
        [ValidateSet(
            'GenericAll', 'GenericRead', 'GenericWrite', 'GenericExecute',
            'Delete', 'ReadControl', 'WriteDacl', 'WriteOwner',
            'CreateChild', 'DeleteChild', 'ListChildren', 'Self',
            'ReadProperty', 'WriteProperty', 'DeleteTree', 'ListObject',
            'ExtendedRight', 'ControlAccess'
        )]
        [string]$Rights,

        # ExtendedRight (alternative to Rights - user-friendly aliases)
        [Parameter(Mandatory=$false, ParameterSetName='GrantACE')]
        [Parameter(Mandatory=$false, ParameterSetName='RevokeACE')]
        [Parameter(Mandatory=$false, ParameterSetName='DenyACE')]
        [ValidateSet(
            # Critical Red Team Rights
            'DCSync', 'ForceChangePassword', 'ResetPassword', 'AddMember',
            # Exchange
            'SendAs', 'ReceiveAs',
            # LAPS
            'ReadLAPSPassword',
            # Certificates
            'AutoEnroll', 'CertEnroll',
            # Kerberos
            'AllowedToAuthenticate',
            # Replication
            'ReplicateDirectory', 'InstallReplica', 'CloneDC',
            # SID History
            'MigrateSIDHistory',
            # GPO
            'ApplyGroupPolicy', 'CreateGPOLink',
            # RSoP
            'GenerateRSoPLogging', 'GenerateRSoPPlanning',
            # Tombstone
            'ReanimateTombstones',
            # Self Membership
            'SelfMembership',
            # Dangerous
            'AllExtendedRights'
        )]
        [string]$ExtendedRight,

        # === Connection Parameters ===
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$PassThru,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase
    )

    begin {
        Write-Log "[Set-DomainObject] Starting object modification (ParameterSet: $($PSCmdlet.ParameterSetName))"

        if ($PSCmdlet.ParameterSetName -in @('GrantACE', 'RevokeACE', 'DenyACE')) {
            if (-not $Rights -and -not $ExtendedRight) {
                throw "[Set-DomainObject] $($PSCmdlet.ParameterSetName) requires either -Rights or -ExtendedRight parameter"
            }
        }
    }

    process {
        # Ensure LDAP connection at start of process block
        $ConnectionParams = @{}
        if ($Domain) { $ConnectionParams['Domain'] = $Domain }
        if ($Server) { $ConnectionParams['Server'] = $Server }
        if ($Credential) { $ConnectionParams['Credential'] = $Credential }

        if (-not (Ensure-LDAPConnection @ConnectionParams)) {
            if ($PassThru) {
                return [PSCustomObject]@{
                    Operation = $PSCmdlet.ParameterSetName
                    Object = $Identity
                    Success = $false
                    Message = "No LDAP connection available"
                }
            }
            return $false
        }

        try {
            $Filter = "(objectClass=*)"
            $crossDomainQuery = $false
            $targetDomainDN = $null
            $targetDomainFQDN = $null

            if ($Identity) {
                # Detect DOMAIN\name format and handle cross-domain queries
                if ($Identity -match '^([^\\]+)\\(.+)$') {
                    Write-Log "[Set-DomainObject] Detecting cross-domain format: $Identity"

                    # Use centralized cross-domain resolution
                    $crossDomainInfo = Resolve-CrossDomainIdentity -Identity $Identity
                    $crossDomainQuery = $crossDomainInfo.IsCrossDomain
                    $targetDomainDN = $crossDomainInfo.TargetDomainDN
                    $targetDomainFQDN = $crossDomainInfo.TargetDomainFQDN

                    # Use the extracted identity (without domain prefix)
                    $Identity = $crossDomainInfo.Identity

                    if ($crossDomainQuery) {
                        Write-Log "[Set-DomainObject] Cross-domain query detected: Target domain = $targetDomainFQDN"
                    }
                }

                # Check if SID, DN, GUID, or sAMAccountName
                if ($Identity -match '^S-1-5-.*') {
                    # SID Format - convert to hex for LDAP
                    $SIDObj = New-Object System.Security.Principal.SecurityIdentifier($Identity)
                    $SIDBytes = New-Object byte[] $SIDObj.BinaryLength
                    $SIDObj.GetBinaryForm($SIDBytes, 0)
                    $SIDHex = ($SIDBytes | ForEach-Object { '\' + $_.ToString('X2') }) -join ''
                    $IdentityFilter = "(objectSid=$SIDHex)"
                } elseif ($Identity -match '^CN=.*|^OU=.*|^DC=.*') {
                    # Distinguished Name - RFC 4515 escape before embedding in a filter so DNs that
                    # contain '(' ')' or '*' (e.g. "CN=Doe\, Jane (Contractor),...") do not break it.
                    $escapedIdentityDN = Escape-LDAPFilterDN -DistinguishedName $Identity
                    $IdentityFilter = "(distinguishedName=$escapedIdentityDN)"
                } elseif ($Identity -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') {
                    # GUID Format
                    $GUIDObj = [System.Guid]::Parse($Identity)
                    $GUIDBytes = $GUIDObj.ToByteArray()
                    $GUIDHex = ($GUIDBytes | ForEach-Object { '\' + $_.ToString('X2') }) -join ''
                    $IdentityFilter = "(objectGUID=$GUIDHex)"
                } else {
                    # sAMAccountName (with wildcard support)
                    $IdentityFilter = "(|(sAMAccountName=$Identity)(cn=$Identity)(name=$Identity))"
                }

                $Filter = "(&$Filter$IdentityFilter)"
            }

            Write-Log "[Set-DomainObject] Using filter: $Filter"

            # ACL MODIFICATION LOGIC - use Raw query directly to avoid double query
            if ($PSCmdlet.ParameterSetName -ne 'SetAttributes') {
                Write-Log "[Set-DomainObject] Processing ACL modification: $($PSCmdlet.ParameterSetName)"

                # Single LDAP query with Raw for ACL operations
                $SearchParams = @{
                    Filter = $Filter
                    Properties = @('distinguishedName', 'nTSecurityDescriptor')
                    SizeLimit = 10  # Increased for cross-domain (may return multiple before filtering)
                    Raw = $true
                }

                # For cross-domain queries, use Global Catalog
                if ($crossDomainQuery) {
                    $gcConn = Get-GCConnection
                    if ($gcConn) {
                        Write-Log "[Set-DomainObject] Using GC connection for cross-domain query"
                        $SearchParams['LdapConnection'] = $gcConn
                        $SearchParams['SearchBase'] = $targetDomainDN
                    } else {
                        Write-Log "[Set-DomainObject] GC connection unavailable - cross-domain query may fail" -Level Warning
                    }
                } elseif ($SearchBase) {
                    $SearchParams['SearchBase'] = $SearchBase
                    Write-Log "[Set-DomainObject] Using custom SearchBase: $SearchBase"
                }

                $SearchResult = Invoke-LDAPSearch @SearchParams

                # Post-filter for cross-domain queries (exclude child domains)
                if ($crossDomainQuery -and $targetDomainFQDN -and $SearchResult) {
                    $ResultArray = @($SearchResult)
                    $FilteredResults = @()

                    foreach ($res in $ResultArray) {
                        if ($res.distinguishedName) {
                            if (Test-DomainMatch -DistinguishedName $res.distinguishedName -TargetDomainFQDN $targetDomainFQDN) {
                                $FilteredResults += $res
                            }
                        }
                    }

                    $SearchResult = $FilteredResults
                    Write-Log "[Set-DomainObject] After cross-domain filter: $($SearchResult.Count) result(s)"
                }

                # Ensure single result
                $SearchResult = @($SearchResult)[0]

                if (-not $SearchResult) {
                    Write-Error "[Set-DomainObject] Object not found: $Identity"
                    return $false
                }

                $ResultArray = @($SearchResult)
                $ObjectDN = $ResultArray[0].distinguishedName
                Write-Log "[Set-DomainObject] Found object: $ObjectDN"

                # Resolve Principal to SecurityIdentifier
                $PrincipalSID = $null
                $ResolvedSIDString = ConvertTo-SID -Identity $Principal

                if ($ResolvedSIDString) {
                    $PrincipalSID = New-Object System.Security.Principal.SecurityIdentifier($ResolvedSIDString)
                    Write-Log "[Set-DomainObject] Resolved principal '$Principal' to SID: $ResolvedSIDString"
                } else {
                    Write-Error "[Set-DomainObject] Failed to resolve principal '$Principal' - ensure the identity exists in AD"
                    return $false
                }

                # Get Security Descriptor from raw result
                if (-not $ResultArray[0].nTSecurityDescriptor) {
                    Write-Error "[Set-DomainObject] Failed to retrieve Security Descriptor for: $ObjectDN"
                    return $false
                }

                # Create ActiveDirectorySecurity object from binary SD
                $ACL = New-Object System.DirectoryServices.ActiveDirectorySecurity
                $ACL.SetSecurityDescriptorBinaryForm($ResultArray[0].nTSecurityDescriptor)
                Write-Log "[Set-DomainObject] Retrieved current ACL from object via nTSecurityDescriptor"

                # Track ACE operations for feedback
                $ACEsAdded = 0
                $ACEsRemoved = 0

                # Process based on operation type
                switch ($PSCmdlet.ParameterSetName) {
                    'GrantACE' {
                        Write-Log "[Set-DomainObject] Processing GrantACE operation"
                        $ACEsAdded = Add-ACEToACL -ACL $ACL -PrincipalSID $PrincipalSID -Rights $Rights -ExtendedRight $ExtendedRight -AccessType 'Allow' -Operation 'Add'
                    }

                    'RevokeACE' {
                        Write-Log "[Set-DomainObject] Processing RevokeACE operation"
                        $ACEsRemoved = Add-ACEToACL -ACL $ACL -PrincipalSID $PrincipalSID -Rights $Rights -ExtendedRight $ExtendedRight -AccessType 'Allow' -Operation 'Remove'
                    }

                    'DenyACE' {
                        Write-Log "[Set-DomainObject] Processing DenyACE operation"
                        $ACEsAdded = Add-ACEToACL -ACL $ACL -PrincipalSID $PrincipalSID -Rights $Rights -ExtendedRight $ExtendedRight -AccessType 'Deny' -Operation 'Add'
                    }

                    'ClearACE' {
                        Write-Log "[Set-DomainObject] Processing ClearACE operation (removing all ACEs for principal)"

                        # Get all ACEs for this principal
                        $ACEs = $ACL.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier])

                        foreach ($ACE in $ACEs) {
                            if ($ACE.IdentityReference -eq $PrincipalSID) {
                                $removed = $ACL.RemoveAccessRule($ACE)
                                if ($removed) {
                                    $ACEsRemoved++
                                }
                            }
                        }

                        Write-Log "[Set-DomainObject] Removed $ACEsRemoved ACE(s) for principal $Principal"
                    }

                    'SetOwner' {
                        Write-Log "[Set-DomainObject] Processing SetOwner operation"

                        $ACL.SetOwner($PrincipalSID)
                        Write-Log "[Set-DomainObject] Set owner to: $Principal ($($PrincipalSID.Value))"
                    }
                }

                # Commit ACL changes via ModifyRequest (unified LdapConnection architecture)
                try {
                    # Convert modified ACL back to binary Security Descriptor
                    $SDBytes = $ACL.GetSecurityDescriptorBinaryForm()

                    # Create ModifyRequest for nTSecurityDescriptor
                    $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                    $ModifyRequest.DistinguishedName = $ObjectDN

                    # Create attribute modification for nTSecurityDescriptor
                    $SDModification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                    $SDModification.Name = "nTSecurityDescriptor"
                    $SDModification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                    $SDModification.Add($SDBytes) | Out-Null

                    $ModifyRequest.Modifications.Add($SDModification) | Out-Null

                    # Send the request via LdapConnection
                    $Response = $Script:LdapConnection.SendRequest($ModifyRequest)

                    if ($Response.ResultCode -eq [System.DirectoryServices.Protocols.ResultCode]::Success) {
                        Write-Log "[Set-DomainObject] Successfully committed ACL changes to AD via ModifyRequest"

                        # Build appropriate message based on operation
                        $OperationMsg = switch ($PSCmdlet.ParameterSetName) {
                            'GrantACE'  { "Granted $ACEsAdded ACE(s) on object: $ObjectDN" }
                            'RevokeACE' { "Revoked $ACEsRemoved ACE(s) from object: $ObjectDN" }
                            'DenyACE'   { "Added $ACEsAdded Deny ACE(s) on object: $ObjectDN" }
                            'ClearACE'  { "Removed $ACEsRemoved ACE(s) for principal '$Principal' on object: $ObjectDN" }
                            'SetOwner'  { "Changed owner to '$Principal' on object: $ObjectDN" }
                        }

                        if ($PassThru) {
                            return [PSCustomObject]@{
                                Operation = $PSCmdlet.ParameterSetName
                                Object = $ObjectDN
                                Principal = $Principal
                                ACEsAdded = $ACEsAdded
                                ACEsRemoved = $ACEsRemoved
                                Success = $true
                                Message = $OperationMsg
                            }
                        } else {
                            Show-Line $OperationMsg -Class Hint
                        }
                        return $true
                    } else {
                        Write-Log "[Set-DomainObject] ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                        if ($PassThru) {
                            return [PSCustomObject]@{
                                Operation = $PSCmdlet.ParameterSetName
                                Object = $ObjectDN
                                Success = $false
                                Message = "ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }
                        }
                        return $false
                    }
                } catch {
                    # Decode the LDAP write failure into an actionable message (LDAP
                    # ResultCode + AD server sub-error) instead of the generic text.
                    $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "modify ACL on '$ObjectDN'"
                    Write-Log ("[Set-DomainObject] Failed to commit ACL changes: " + $writeError.Formatted)
                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Operation  = $PSCmdlet.ParameterSetName
                            Object     = $ObjectDN
                            Success    = $false
                            ResultCode = $writeError.ResultCode
                            ResultName = $writeError.ResultName
                            Message    = $writeError.Formatted
                        }
                    }
                    return $false
                }
            }

            # ATTRIBUTE MODIFICATION LOGIC - find object first
            $SearchParams = @{
                Filter = $Filter
                Properties = @('distinguishedName')
                SizeLimit = 10  # Increased for cross-domain (may return multiple before filtering)
            }

            # For cross-domain queries, use Global Catalog
            if ($crossDomainQuery) {
                $gcConn = Get-GCConnection
                if ($gcConn) {
                    Write-Log "[Set-DomainObject] Using GC connection for cross-domain query"
                    $SearchParams['LdapConnection'] = $gcConn
                    $SearchParams['SearchBase'] = $targetDomainDN
                } else {
                    Write-Log "[Set-DomainObject] GC connection unavailable - cross-domain query may fail" -Level Warning
                }
            } elseif ($SearchBase) {
                $SearchParams['SearchBase'] = $SearchBase
                Write-Log "[Set-DomainObject] Using custom SearchBase: $SearchBase"
            }

            $SearchResult = Invoke-LDAPSearch @SearchParams

            # Post-filter for cross-domain queries (exclude child domains)
            if ($crossDomainQuery -and $targetDomainFQDN -and $SearchResult) {
                $ResultArray = @($SearchResult)
                $FilteredResults = @()

                foreach ($res in $ResultArray) {
                    if ($res.distinguishedName) {
                        if (Test-DomainMatch -DistinguishedName $res.distinguishedName -TargetDomainFQDN $targetDomainFQDN) {
                            $FilteredResults += $res
                        }
                    }
                }

                $SearchResult = $FilteredResults
                Write-Log "[Set-DomainObject] After cross-domain filter: $($SearchResult.Count) result(s)"
            }

            # Ensure single result
            $SearchResult = @($SearchResult)[0]

            if (-not $SearchResult) {
                Write-Error "[Set-DomainObject] Object not found: $Identity"
                return $false
            }

            # Ensure we have a single result
            $ResultArray = @($SearchResult)
            $ObjectDN = $ResultArray[0].distinguishedName
            Write-Log "[Set-DomainObject] Found object: $ObjectDN"

            # Build ModifyRequest with all attribute modifications
            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
            $ModifyRequest.DistinguishedName = $ObjectDN
            $ModificationsAdded = $false

            # === SET Operation (Replace values) ===
            if ($Set -and $Set.Count -gt 0) {
                Write-Log "[Set-DomainObject] Processing SET operation on $($Set.Count) attribute(s)"

                foreach ($AttrName in $Set.Keys) {
                    $AttrValue = $Set[$AttrName]

                    try {
                        $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $Modification.Name = $AttrName
                        $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace

                        # Add value(s) to modification
                        if ($AttrValue -is [array]) {
                            foreach ($item in $AttrValue) {
                                $Modification.Add($item) | Out-Null
                            }
                            Write-Log "[Set-DomainObject] Set $AttrName = $AttrValue (array with $($AttrValue.Count) items)"
                        } else {
                            $Modification.Add($AttrValue) | Out-Null
                            Write-Log "[Set-DomainObject] Set $AttrName = $AttrValue"
                        }

                        $ModifyRequest.Modifications.Add($Modification) | Out-Null
                        $ModificationsAdded = $true
                    } catch {
                        Write-Warning "[Set-DomainObject] Failed to prepare SET for ${AttrName}: $_"
                    }
                }
            }

            # === APPEND Operation (Add to multi-valued attributes) ===
            if ($Append -and $Append.Count -gt 0) {
                Write-Log "[Set-DomainObject] Processing APPEND operation on $($Append.Count) attribute(s)"

                foreach ($AttrName in $Append.Keys) {
                    $AttrValue = $Append[$AttrName]

                    try {
                        $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $Modification.Name = $AttrName
                        $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Add

                        if ($AttrValue -is [array]) {
                            foreach ($item in $AttrValue) {
                                $Modification.Add($item) | Out-Null
                            }
                            Write-Log "[Set-DomainObject] Appended $AttrName += $AttrValue (array with $($AttrValue.Count) items)"
                        } else {
                            $Modification.Add($AttrValue) | Out-Null
                            Write-Log "[Set-DomainObject] Appended $AttrName += $AttrValue"
                        }

                        $ModifyRequest.Modifications.Add($Modification) | Out-Null
                        $ModificationsAdded = $true
                    } catch {
                        Write-Warning "[Set-DomainObject] Failed to prepare APPEND for ${AttrName}: $_"
                    }
                }
            }

            # === REMOVE Operation (Remove specific values from multi-valued attributes) ===
            if ($Remove -and $Remove.Count -gt 0) {
                Write-Log "[Set-DomainObject] Processing REMOVE operation on $($Remove.Count) attribute(s)"

                foreach ($AttrName in $Remove.Keys) {
                    $AttrValue = $Remove[$AttrName]

                    try {
                        $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $Modification.Name = $AttrName
                        $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                        if ($AttrValue -is [array]) {
                            foreach ($item in $AttrValue) {
                                $Modification.Add($item) | Out-Null
                            }
                            Write-Log "[Set-DomainObject] Removed $AttrName -= $AttrValue (array with $($AttrValue.Count) items)"
                        } else {
                            $Modification.Add($AttrValue) | Out-Null
                            Write-Log "[Set-DomainObject] Removed $AttrName -= $AttrValue"
                        }

                        $ModifyRequest.Modifications.Add($Modification) | Out-Null
                        $ModificationsAdded = $true
                    } catch {
                        Write-Warning "[Set-DomainObject] Failed to prepare REMOVE for ${AttrName}: $_"
                    }
                }
            }

            # === CLEAR Operation (Remove all values) ===
            if ($Clear -and $Clear.Count -gt 0) {
                Write-Log "[Set-DomainObject] Processing CLEAR operation on $($Clear.Count) attribute(s)"

                foreach ($AttrName in $Clear) {
                    try {
                        $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $Modification.Name = $AttrName
                        # Delete without values = clear all values
                        $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                        $ModifyRequest.Modifications.Add($Modification) | Out-Null
                        Write-Log "[Set-DomainObject] Cleared $AttrName"
                        $ModificationsAdded = $true
                    } catch {
                        Write-Warning "[Set-DomainObject] Failed to prepare CLEAR for ${AttrName}: $_"
                    }
                }
            }

            # Send ModifyRequest if any modifications were added
            if ($ModificationsAdded) {
                try {
                    $Response = $Script:LdapConnection.SendRequest($ModifyRequest)

                    if ($Response.ResultCode -eq [System.DirectoryServices.Protocols.ResultCode]::Success) {
                        Write-Log "[Set-DomainObject] Successfully committed attribute changes to AD via ModifyRequest"
                        if ($PassThru) {
                            return [PSCustomObject]@{
                                Operation = "SetAttributes"
                                Object = $ObjectDN
                                Success = $true
                                Message = "Attributes successfully modified"
                            }
                        }
                        return $true
                    } else {
                        Write-Error "[Set-DomainObject] ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                        if ($PassThru) {
                            return [PSCustomObject]@{
                                Operation = "SetAttributes"
                                Object = $ObjectDN
                                Success = $false
                                Message = "ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }
                        }
                        return $false
                    }
                } catch {
                    # Decode the LDAP write failure into an actionable message (LDAP
                    # ResultCode + AD server sub-error) instead of the generic text.
                    $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "modify object '$ObjectDN'"
                    Write-Error ("[Set-DomainObject] Failed to commit changes." + [Environment]::NewLine + '  ' + $writeError.Formatted)
                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Operation  = "SetAttributes"
                            Object     = $ObjectDN
                            Success    = $false
                            ResultCode = $writeError.ResultCode
                            ResultName = $writeError.ResultName
                            Message    = $writeError.Formatted
                        }
                    }
                    return $false
                }
            } else {
                # No modifications requested - this is a no-op, not a success
                Write-Log "[Set-DomainObject] No attribute modifications specified"
                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "SetAttributes"
                        Object = $ObjectDN
                        Success = $true
                        NoOp = $true
                        Message = "No modifications specified"
                    }
                }
                Show-Line "No modifications specified for object: $ObjectDN" -Class Note
                return $true
            }

        } catch {
            # Decode the LDAP write failure into an actionable message (LDAP ResultCode
            # + AD server sub-error) instead of the generic ".NET" exception text.
            $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "modify object '$Identity'"
            Write-Error ("[Set-DomainObject] Error." + [Environment]::NewLine + '  ' + $writeError.Formatted)
            if ($PassThru) {
                return [PSCustomObject]@{
                    Operation  = $PSCmdlet.ParameterSetName
                    Object     = $Identity
                    Success    = $false
                    ResultCode = $writeError.ResultCode
                    ResultName = $writeError.ResultName
                    Message    = $writeError.Formatted
                }
            }
            return $false
        }
    }

    end {
        Write-Log "[Set-DomainObject] Object modification completed"
    }
}

<#
.SYNOPSIS
    Internal helper function to add/remove ACE to/from an ACL.

.DESCRIPTION
    Consolidates the duplicated ACE creation logic from GrantACE, RevokeACE, and DenyACE operations.
    Handles ReadProperty aliases, WriteProperty aliases, ExtendedRights, and standard Rights.

.PARAMETER ACL
    The ActiveDirectorySecurity object to modify.

.PARAMETER PrincipalSID
    The SecurityIdentifier of the principal.

.PARAMETER Rights
    Standard AD rights (GenericAll, WriteDacl, etc.).

.PARAMETER ExtendedRight
    ExtendedRight alias (DCSync, ForceChangePassword, etc.).

.PARAMETER AccessType
    'Allow' or 'Deny' for the ACE type.

.PARAMETER Operation
    'Add' to add ACE, 'Remove' to remove ACE.

.OUTPUTS
    Int - Number of ACEs added or removed.
#>
function Add-ACEToACL {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [System.DirectoryServices.ActiveDirectorySecurity]$ACL,

        [Parameter(Mandatory=$true)]
        [System.Security.Principal.SecurityIdentifier]$PrincipalSID,

        [Parameter(Mandatory=$false)]
        [string]$Rights,

        [Parameter(Mandatory=$false)]
        [string]$ExtendedRight,

        [Parameter(Mandatory=$true)]
        [ValidateSet('Allow', 'Deny')]
        [string]$AccessType,

        [Parameter(Mandatory=$true)]
        [ValidateSet('Add', 'Remove')]
        [string]$Operation
    )

    $ACECount = 0
    $AccessControlType = [System.Security.AccessControl.AccessControlType]::$AccessType

    if ($ExtendedRight) {
        # Check if this is a ReadProperty alias (e.g., ReadLAPSPassword)
        $ReadPropertyGUID = $Script:ReadPropertyAliases[$ExtendedRight]

        if ($ReadPropertyGUID) {
            Write-Log "[Add-ACEToACL] '$ExtendedRight' is a ReadProperty alias (attribute GUID: $ReadPropertyGUID)"

            $ObjectType = New-Object Guid($ReadPropertyGUID)
            $ACE = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
                $PrincipalSID,
                [System.DirectoryServices.ActiveDirectoryRights]::ReadProperty,
                $AccessControlType,
                $ObjectType,
                [System.DirectoryServices.ActiveDirectorySecurityInheritance]::None
            )

            if ($Operation -eq 'Add') {
                $ACL.AddAccessRule($ACE)
                $ACECount++
                Write-Log "[Add-ACEToACL] Added $AccessType ACE for ReadProperty '$ExtendedRight'"
            } else {
                $removed = $ACL.RemoveAccessRule($ACE)
                if ($removed) {
                    $ACECount++
                    Write-Log "[Add-ACEToACL] Removed ACE for ReadProperty '$ExtendedRight'"
                } else {
                    Write-Log "[Add-ACEToACL] ACE for ReadProperty '$ExtendedRight' was not found - nothing removed"
                }
            }
        }
        # Check if this is a WriteProperty alias (e.g., AddMember, WriteMembers)
        elseif (($WritePropertyGUID = $Script:WritePropertyAliases[$ExtendedRight])) {
            Write-Log "[Add-ACEToACL] '$ExtendedRight' is a WriteProperty alias (attribute GUID: $WritePropertyGUID)"

            $ObjectType = New-Object Guid($WritePropertyGUID)
            $ACE = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
                $PrincipalSID,
                [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty,
                $AccessControlType,
                $ObjectType,
                [System.DirectoryServices.ActiveDirectorySecurityInheritance]::None
            )

            if ($Operation -eq 'Add') {
                $ACL.AddAccessRule($ACE)
                $ACECount++
                Write-Log "[Add-ACEToACL] Added $AccessType ACE for WriteProperty '$ExtendedRight'"
            } else {
                $removed = $ACL.RemoveAccessRule($ACE)
                if ($removed) {
                    $ACECount++
                    Write-Log "[Add-ACEToACL] Removed ACE for WriteProperty '$ExtendedRight'"
                } else {
                    Write-Log "[Add-ACEToACL] ACE for WriteProperty '$ExtendedRight' was not found - nothing removed"
                }
            }
        } else {
            # Handle ExtendedRight with alias mapping
            $GUIDs = $Script:ExtendedRightsAliases[$ExtendedRight]

            if (-not $GUIDs) {
                Write-Error "[Add-ACEToACL] Unknown ExtendedRight alias: $ExtendedRight"
                return 0
            }

            # DCSync is special - it's an array of 3 GUIDs
            $GUIDList = if ($GUIDs -is [array]) { $GUIDs } else { @($GUIDs) }

            foreach ($GUID in $GUIDList) {
                $ObjectType = New-Object Guid($GUID)
                $ACE = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
                    $PrincipalSID,
                    [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight,
                    $AccessControlType,
                    $ObjectType,
                    [System.DirectoryServices.ActiveDirectorySecurityInheritance]::None
                )

                if ($Operation -eq 'Add') {
                    $ACL.AddAccessRule($ACE)
                    $ACECount++
                    Write-Log "[Add-ACEToACL] Added $AccessType ACE for ExtendedRight GUID: $GUID"
                } else {
                    $removed = $ACL.RemoveAccessRule($ACE)
                    if ($removed) {
                        $ACECount++
                        Write-Log "[Add-ACEToACL] Removed ACE for ExtendedRight GUID: $GUID"
                    } else {
                        Write-Log "[Add-ACEToACL] ACE for ExtendedRight GUID $GUID was not found - nothing removed"
                    }
                }
            }
        }
    } elseif ($Rights) {
        # Standard rights
        $ADRights = [System.DirectoryServices.ActiveDirectoryRights]::$Rights
        $ACE = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
            $PrincipalSID,
            $ADRights,
            $AccessControlType
        )

        if ($Operation -eq 'Add') {
            $ACL.AddAccessRule($ACE)
            $ACECount++
            Write-Log "[Add-ACEToACL] Added $AccessType ACE for Rights: $Rights"
        } else {
            $removed = $ACL.RemoveAccessRule($ACE)
            if ($removed) {
                $ACECount++
                Write-Log "[Add-ACEToACL] Removed ACE for Rights: $Rights"
            } else {
                Write-Log "[Add-ACEToACL] ACE for Rights '$Rights' was not found - nothing removed"
            }
        }
    }

    return $ACECount
}



# ----- Get-DomainUser.ps1 -----

function Get-DomainUser {
<#
.SYNOPSIS
    Retrieves user objects from Active Directory (wrapper for Get-DomainObject).

.DESCRIPTION
    Get-DomainUser is a convenience wrapper around Get-DomainObject that provides user-specific filters and functionality:

    - Search by Identity (sAMAccountName, DN, SID, DOMAIN\user)
    - Filter by specific criteria (AdminCount, SPN, Delegation, etc.)
    - Flexible property selection
    - Custom LDAP filters
    - gMSA-specific features (ShowGMSADetails)

.PARAMETER Identity
    sAMAccountName, DistinguishedName, SID or DOMAIN\user format.
    Wildcards are supported.

.PARAMETER SPN
    Return only users with Service Principal Names.

.PARAMETER AdminCount
    Return only users with adminCount=1 (privileged accounts).

.PARAMETER Unconstrained
    Users with Unconstrained Delegation (TRUSTED_FOR_DELEGATION flag).

.PARAMETER Constrained
    Users with Constrained Delegation (msDS-AllowedToDelegateTo attribute).
    Includes both regular Constrained Delegation and Protocol Transition variants.

.PARAMETER RBCD
    Users with Resource-Based Constrained Delegation (msDS-AllowedToActOnBehalfOfOtherIdentity attribute).
    RBCD allows the target resource to control who can delegate to it.

.PARAMETER TrustedToAuth
    Users with Protocol Transition (TRUSTED_TO_AUTH_FOR_DELEGATION flag).
    This is the more dangerous variant of Constrained Delegation with S4U2Self.

.PARAMETER DisallowDelegation
    Users NOT allowed for delegation (NOT_DELEGATED flag set).

.PARAMETER PreauthNotRequired
    Users with DONT_REQ_PREAUTH flag (AS-REP Roastable).

.PARAMETER PasswordNotRequired
    Users with PASSWD_NOTREQD flag.

.PARAMETER PasswordNeverExpires
    Users with DONT_EXPIRE_PASSWORD flag.

.PARAMETER PasswordMustChange
    Users where pwdLastSet=0 (must change password at next logon).

.PARAMETER Enabled
    Only enabled users (ACCOUNTDISABLE flag not set).

.PARAMETER Disabled
    Only disabled users (ACCOUNTDISABLE flag set).

.PARAMETER LockedOut
    Only locked out users (lockoutTime > 0).

.PARAMETER SmartcardRequired
    Users with SMARTCARD_REQUIRED flag set.

.PARAMETER AccountExpired
    Users where accountExpires is in the past.

.PARAMETER AccountNeverExpires
    Users where accountExpires is 0 or never set.

.PARAMETER DESOnly
    Users with USE_DES_KEY_ONLY flag set (weak encryption).

.PARAMETER ReversibleEncryption
    Users with ENCRYPTED_TEXT_PWD_ALLOWED flag set (security risk).

.PARAMETER GMSA
    Return only Managed Service Accounts (MSA and gMSA).
    Includes both standalone MSA (Server 2008 R2+) and Group MSA (Server 2012+).

.PARAMETER ShowGMSADetails
    Shows extended MSA/gMSA information (password access, rotation, SPNs).
    Must be used together with -GMSA.

.PARAMETER LDAPFilter
    Custom LDAP filter for special queries.

.PARAMETER Properties
    Array of attribute names to return.
    Default: All default properties from Get-DomainObject.

.PARAMETER ShowOwner
    Include Owner and OwnerSID properties on returned objects.

.PARAMETER SearchBase
    Alternative SearchBase (DN). Default: Domain DN.

.PARAMETER Domain
    Target domain (FQDN).

.PARAMETER Server
    Specific Domain Controller to query.

.PARAMETER Credential
    PSCredential object for authentication.

.EXAMPLE
    Get-DomainUser -Identity "Administrator"
    Returns the Administrator account.

.EXAMPLE
    Get-DomainUser -AdminCount
    Returns all users with adminCount=1.

.EXAMPLE
    Get-DomainUser -SPN
    Returns all Kerberoastable users (with SPNs).

.EXAMPLE
    Get-DomainUser -Unconstrained
    Returns all users with Unconstrained Delegation.

.EXAMPLE
    Get-DomainUser -Constrained
    Returns all users with Constrained Delegation.

.EXAMPLE
    Get-DomainUser -TrustedToAuth
    Returns all users with Protocol Transition (S4U2Self).

.EXAMPLE
    Get-DomainUser -RBCD
    Returns all users with Resource-Based Constrained Delegation configured.

.EXAMPLE
    Get-DomainUser -PreauthNotRequired
    Returns all AS-REP Roastable users.

.EXAMPLE
    Get-DomainUser -GMSA
    Returns all Managed Service Accounts (standalone MSA and gMSA).

.EXAMPLE
    Get-DomainUser -GMSA -ShowGMSADetails
    Returns all MSAs/gMSAs with extended details (password access, rotation interval, etc.).

.OUTPUTS
    PSCustomObject with user attributes

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(DefaultParameterSetName='Default')]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [Alias('samAccountName', 'Name', 'User')]
        [string]$Identity,

        # All filter parameters are combinable (no ParameterSetName restriction)
        [Parameter(Mandatory=$false)]
        [switch]$SPN,

        [Parameter(Mandatory=$false)]
        [switch]$AdminCount,

        [Parameter(Mandatory=$false)]
        [switch]$Unconstrained,

        [Parameter(Mandatory=$false)]
        [switch]$Constrained,

        [Parameter(Mandatory=$false)]
        [switch]$RBCD,

        [Parameter(Mandatory=$false)]
        [switch]$TrustedToAuth,

        [Parameter(Mandatory=$false)]
        [switch]$DisallowDelegation,

        [Parameter(Mandatory=$false)]
        [switch]$PreauthNotRequired,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordNotRequired,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordNeverExpires,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordMustChange,

        [Parameter(Mandatory=$false)]
        [switch]$Enabled,

        [Parameter(Mandatory=$false)]
        [switch]$Disabled,

        [Parameter(Mandatory=$false)]
        [switch]$LockedOut,

        [Parameter(Mandatory=$false)]
        [switch]$SmartcardRequired,

        [Parameter(Mandatory=$false)]
        [switch]$AccountExpired,

        [Parameter(Mandatory=$false)]
        [switch]$AccountNeverExpires,

        [Parameter(Mandatory=$false)]
        [switch]$DESOnly,

        [Parameter(Mandatory=$false)]
        [switch]$ReversibleEncryption,

        [Parameter(ParameterSetName='GMSA')]
        [switch]$GMSA,

        [Parameter(Mandatory=$false)]
        [switch]$ShowGMSADetails,

        [Parameter(Mandatory=$false)]
        [string]$LDAPFilter,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [switch]$ShowOwner,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        # Server-side filter: users whose password was last set at least N days ago.
        [Parameter(Mandatory=$false)]
        [int]$PasswordAgeDays = 0,

        # Server-side filter: users that logged in once but not within the last N days (inactive).
        # Never-logged-in users are excluded (use -NeverLoggedIn). lastLogonTimestamp is coarse.
        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 0,

        # Server-side filter: users that never logged in (lastLogonTimestamp absent).
        [Parameter(Mandatory=$false)]
        [switch]$NeverLoggedIn,

        [Parameter(Mandatory=$false)]
        [int]$ResultLimit = 0
    )

    begin {
        Write-Log "[Get-DomainUser] Starting user enumeration (wrapper for Get-DomainObject)"

        # Info: ShowGMSADetails only works with -GMSA
        if ($ShowGMSADetails -and -not $GMSA) {
            Write-Log "[Get-DomainUser] -ShowGMSADetails was specified without -GMSA, ignoring extended properties"
        }
    }

    process {
        try {
            # Build base filter depending on what we're searching for
            if ($GMSA) {
                # Managed Service Accounts (both standalone MSA and gMSA)
                # - Standalone MSA: objectClass=msDS-ManagedServiceAccount (Server 2008 R2+)
                # - Group MSA (gMSA): objectClass=msDS-GroupManagedServiceAccount (Server 2012+)
                # Note: gMSA inherits from MSA, so we need OR filter to catch both
                $Filter = "(|(objectClass=msDS-ManagedServiceAccount)(objectClass=msDS-GroupManagedServiceAccount))"
            } else {
                # Standard users: only user objects, no computers, no gMSAs
                $Filter = "(&(objectCategory=person)(objectClass=user)(!(objectClass=computer)))"
            }

            if ($Unconstrained) {
                # TRUSTED_FOR_DELEGATION Flag (524288) - keep here as it's user-specific context
                $Filter = "(&$Filter(userAccountControl:1.2.840.113556.1.4.803:=524288))"
            }

            if ($Constrained) {
                # Constrained Delegation: Has msDS-AllowedToDelegateTo attribute
                # This includes both regular Constrained Delegation and Protocol Transition
                $Filter = "(&$Filter(msDS-AllowedToDelegateTo=*))"
            }

            if ($RBCD) {
                # Resource-Based Constrained Delegation: Has msDS-AllowedToActOnBehalfOfOtherIdentity attribute
                # The target resource controls who can delegate to it (stored as Security Descriptor)
                $Filter = "(&$Filter(msDS-AllowedToActOnBehalfOfOtherIdentity=*))"
            }

            # Custom LDAP filter
            if ($LDAPFilter) {
                $Filter = "(&$Filter$LDAPFilter)"
            }

            Write-Log "[Get-DomainUser] Using filter: $Filter"

            # Build parameters for Get-DomainObject
            $GetParams = @{
                LDAPFilter = $Filter
            }

            # Add MSA/gMSA-specific properties if ShowGMSADetails is set (only with -GMSA)
            if ($ShowGMSADetails -and $GMSA) {
                if ($Properties) {
                    # Merge user-specified properties with MSA-specific properties
                    $MSAProperties = @(
                        # Standalone MSA attributes (Server 2008 R2+)
                        'msds-hostserviceaccountbl',
                        'pwdlastset',

                        # gMSA attributes (Server 2012+)
                        'msds-managedpasswordinterval',
                        'msds-groupmsamembership',
                        'msds-managedpasswordid',
                        'msds-managedpasswordpreviousid',
                        'principalsallowedtoretrievemanagedpassword',

                        # Common attributes
                        'serviceprincipalname',
                        'objectclass'
                    )
                    $GetParams['Properties'] = $Properties + $MSAProperties | Select-Object -Unique
                }
                Write-Log "[Get-DomainUser] ShowGMSADetails enabled - MSA/gMSA-specific properties will be included"
            } elseif ($Properties) {
                $GetParams['Properties'] = $Properties
            }

            # Pass through Identity parameter
            if ($Identity) {
                $GetParams['Identity'] = $Identity
            }

            # Pass through other parameters
            if ($ShowOwner) { $GetParams['ShowOwner'] = $true }
            if ($SearchBase) { $GetParams['SearchBase'] = $SearchBase }
            if ($Domain) { $GetParams['Domain'] = $Domain }
            if ($Server) { $GetParams['Server'] = $Server }
            if ($Credential) { $GetParams['Credential'] = $Credential }
            if ($Raw) { $GetParams['Raw'] = $true }

            # Pass through LDAP-optimized account filters to Get-DomainObject
            if ($Enabled) { $GetParams['IsEnabled'] = $true }
            if ($Disabled) { $GetParams['IsDisabled'] = $true }
            if ($PasswordNeverExpires) { $GetParams['PasswordNeverExpires'] = $true }
            if ($PasswordNotRequired) { $GetParams['PasswordNotRequired'] = $true }
            if ($PasswordMustChange) { $GetParams['PasswordMustChange'] = $true }
            if ($SPN) { $GetParams['HasSPN'] = $true }
            if ($AdminCount) { $GetParams['AdminCount'] = $true }
            if ($TrustedToAuth) { $GetParams['TrustedToAuthForDelegation'] = $true }
            if ($DisallowDelegation) { $GetParams['NotDelegated'] = $true }
            if ($PreauthNotRequired) { $GetParams['PreauthNotRequired'] = $true }
            if ($LockedOut) { $GetParams['LockedOut'] = $true }
            if ($SmartcardRequired) { $GetParams['SmartcardRequired'] = $true }
            if ($AccountExpired) { $GetParams['AccountExpired'] = $true }
            if ($AccountNeverExpires) { $GetParams['AccountNeverExpires'] = $true }
            if ($DESOnly) { $GetParams['DESOnly'] = $true }
            if ($ReversibleEncryption) { $GetParams['ReversibleEncryption'] = $true }
            if ($PasswordAgeDays -gt 0) { $GetParams['PasswordAgeDays'] = $PasswordAgeDays }
            if ($InactiveDays -gt 0) { $GetParams['InactiveDays'] = $InactiveDays }
            if ($NeverLoggedIn) { $GetParams['NeverLoggedIn'] = $true }
            if ($ResultLimit -gt 0) { $GetParams['ResultLimit'] = $ResultLimit }

            $Users = @(Get-DomainObject @GetParams)

            Write-Log "[Get-DomainUser] Found $($Users.Count) user(s)"

            # Post-processing for MSA/gMSA details (parse binary attributes, only with -GMSA)
            if ($ShowGMSADetails -and $GMSA -and $Users.Count -gt 0) {
                Write-Log "[Get-DomainUser] Parsing MSA/gMSA attributes to readable format..."

                foreach ($User in $Users) {
                    # Parse msds-groupmsamembership (Security Descriptor)
                    if ($User.'msds-groupmsamembership') {
                        $AllowedPrincipals = @()
                        try {
                            $SD = New-Object System.DirectoryServices.ActiveDirectorySecurity
                            $SD.SetSecurityDescriptorBinaryForm($User.'msds-groupmsamembership')

                            $DACL = $SD.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier])

                            foreach ($ACE in $DACL) {
                                if ($ACE.AccessControlType -eq 'Allow') {
                                    $TrusteeSID = $ACE.IdentityReference.Value

                                    # Resolve SID to name using LDAP-based ConvertFrom-SID
                                    $PrincipalName = ConvertFrom-SID -SID $TrusteeSID
                                    if (-not $PrincipalName) {
                                        $PrincipalName = $TrusteeSID
                                    }

                                    # Store as structured object with SID for classification
                                    $AllowedPrincipals += [PSCustomObject]@{
                                        Name = $PrincipalName
                                        SID = $TrusteeSID
                                        DisplayText = $PrincipalName
                                    }
                                    Write-Log "[Get-DomainUser] gMSA '$($User.sAMAccountName)' allows password retrieval by: $PrincipalName"
                                }
                            }

                            # Replace byte array with structured principal objects (includes SID for classification)
                            $User.'msds-groupmsamembership' = $AllowedPrincipals
                        } catch {
                            Write-Log "[Get-DomainUser] Error parsing msds-groupmsamembership: $_"
                        }
                    }

                    # NOTE: msDS-ManagedPasswordId and msDS-ManagedPasswordPreviousId are already
                    # parsed into a readable form (RootKeyId + L0/L1/L2 indexes) by Invoke-LDAPSearch.
                }
            }

            return $Users

        } catch {
            Write-Log "[Get-DomainUser] Error: $_"
            throw
        }
    }

    end {
        Write-Log "[Get-DomainUser] User enumeration completed"
    }
}



# ----- Get-DomainComputer.ps1 -----

function Get-DomainComputer {
<#
.SYNOPSIS
    Central function for querying computer objects from Active Directory.

.DESCRIPTION
    Get-DomainComputer is a flexible helper function that unifies all computer queries in adPEAS v2.
    It builds on Invoke-LDAPSearch and provides:

    - Search by Identity (sAMAccountName, DN, SID, DOMAIN\computer)
    - Filter by specific criteria (OperatingSystem, SPN, Delegation, LAPS, etc.)
    - Flexible property selection
    - Custom LDAP filters

.PARAMETER Identity
    sAMAccountName, DistinguishedName, SID or DOMAIN\computer format.
    Wildcards are supported.

.PARAMETER OperatingSystem
    Filter by operating system (e.g. "Windows Server 2019", "*2016*").
    Wildcards are supported.

.PARAMETER SPN
    Return only computers with Service Principal Names.

.PARAMETER Unconstrained
    Computers with Unconstrained Delegation (TRUSTED_FOR_DELEGATION flag).
    Excludes Domain Controllers (primaryGroupID=516).

.PARAMETER Constrained
    Computers with Constrained Delegation (msDS-AllowedToDelegateTo attribute).
    Includes both regular Constrained Delegation and Protocol Transition variants.

.PARAMETER RBCD
    Computers with Resource-Based Constrained Delegation (msDS-AllowedToActOnBehalfOfOtherIdentity attribute).
    RBCD allows the target resource to control who can delegate to it.

.PARAMETER TrustedToAuth
    Computers with Protocol Transition (TRUSTED_TO_AUTH_FOR_DELEGATION flag).
    This is the more dangerous variant of Constrained Delegation with S4U2Self.

.PARAMETER LAPS
    Computers with LAPS enabled (detected via expiration time attributes).
    Searches for ms-Mcs-AdmPwdExpirationTime (Legacy LAPS) or msLAPS-PasswordExpirationTime (Windows LAPS).

.PARAMETER Enabled
    Only enabled computers (ACCOUNTDISABLE flag not set).

.PARAMETER Disabled
    Only disabled computers (ACCOUNTDISABLE flag set).

.PARAMETER HighValueSPN
    Computers running high-value services (security-critical targets).
    Includes: MSSQL, Exchange, SCCM, WSUS, ADFS, Certificate Authority, SCOM, Backup software.
    These are prime targets for lateral movement and privilege escalation.

.PARAMETER KnownSPN
    Filter by specific known service SPN. Available options:
    - MSSQL: SQL Server instances (MSSQLSvc/*)
    - Exchange: Exchange servers (exchangeMDB/*, exchangeRFR/*, exchangeAB/*)
    - SCCM: SCCM/MECM servers (SMS Site Server/*)
    - WSUS: WSUS servers
    - ADFS: AD Federation Services (adfssrv/*)
    - CA: Certificate Authorities (certsvc/*)
    - SCOM: System Center Operations Manager (MSOMHSvc/*, MSOMSdkSvc/*)
    - Backup: Backup servers (wbengine/*, veeam*)
    - HyperV: Hyper-V hosts (Microsoft Virtual Console Service/*)
    - RDP: RDP-enabled servers (TERMSRV/*)
    - WinRM: WinRM-enabled servers (WSMAN/*)
    - HTTP: Web servers (HTTP/*)
    - FTP: FTP servers (FTP/*)

.PARAMETER LDAPFilter
    Custom LDAP filter for special queries.

.PARAMETER Properties
    Array of attribute names to return.
    Default: All default properties from Invoke-LDAPSearch.

.PARAMETER SearchBase
    Alternative SearchBase (DN). Default: Domain DN.

.EXAMPLE
    Get-DomainComputer -Identity "DC01"
    Returns the Domain Controller DC01.

.EXAMPLE
    Get-DomainComputer -OperatingSystem "Windows Server 2019"
    Returns all Windows Server 2019 computers.

.EXAMPLE
    Get-DomainComputer -Unconstrained
    Returns all computers with Unconstrained Delegation (excluding DCs).

.EXAMPLE
    Get-DomainComputer -Constrained
    Returns all computers with Constrained Delegation.

.EXAMPLE
    Get-DomainComputer -TrustedToAuth
    Returns all computers with Protocol Transition (S4U2Self).

.EXAMPLE
    Get-DomainComputer -RBCD
    Returns all computers with Resource-Based Constrained Delegation configured.

.EXAMPLE
    Get-DomainComputer -LAPS
    Returns all computers with LAPS passwords.

.EXAMPLE
    Get-DomainComputer -LDAPFilter "(description=*SQL*)"
    Custom LDAP filter for special searches.

.EXAMPLE
    Get-DomainComputer -HighValueSPN
    Returns all computers running high-value services (MSSQL, Exchange, SCCM, etc.).

.EXAMPLE
    Get-DomainComputer -KnownSPN MSSQL
    Returns all SQL Server instances.

.EXAMPLE
    Get-DomainComputer -KnownSPN Exchange -Enabled
    Returns all enabled Exchange servers.

.OUTPUTS
    PSCustomObject with computer attributes

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [Alias('samAccountName', 'Name', 'Computer', 'DNSHostName')]
        [string]$Identity,

        # All filter parameters are combinable (no ParameterSetName restriction)
        [Parameter(Mandatory=$false)]
        [string]$OperatingSystem,

        [Parameter(Mandatory=$false)]
        [switch]$SPN,

        [Parameter(Mandatory=$false)]
        [switch]$Unconstrained,

        [Parameter(Mandatory=$false)]
        [switch]$Constrained,

        [Parameter(Mandatory=$false)]
        [switch]$RBCD,

        [Parameter(Mandatory=$false)]
        [switch]$TrustedToAuth,

        [Parameter(Mandatory=$false)]
        [switch]$LAPS,

        [Parameter(Mandatory=$false)]
        [switch]$Enabled,

        [Parameter(Mandatory=$false)]
        [switch]$Disabled,

        [Parameter(Mandatory=$false)]
        [switch]$HighValueSPN,

        [Parameter(Mandatory=$false)]
        [ValidateSet('MSSQL', 'Exchange', 'SCCM', 'WSUS', 'ADFS', 'CA', 'SCOM', 'Backup', 'HyperV', 'RDP', 'WinRM', 'HTTP', 'FTP')]
        [string]$KnownSPN,

        [Parameter(Mandatory=$false)]
        [string]$LDAPFilter,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [switch]$ShowOwner,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        # Server-side filter: computers whose machine password was last set at least N days ago
        # (stale machine account - normally rotated every ~30 days).
        [Parameter(Mandatory=$false)]
        [int]$PasswordAgeDays = 0,

        # Server-side filter: computers that logged in once but not within the last N days
        # (inactive). Never-logged-in computers are excluded (use -NeverLoggedIn). Coarse-grained.
        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 0,

        # Server-side filter: computers that never logged in (lastLogonTimestamp absent).
        [Parameter(Mandatory=$false)]
        [switch]$NeverLoggedIn,

        [Parameter(Mandatory=$false)]
        [int]$ResultLimit = 0
    )

    begin {
        Write-Log "[Get-DomainComputer] Starting computer enumeration"
    }

    process {
        try {
            # Base Filter: computer objects only
            $Filter = "(&(objectCategory=computer)(objectClass=computer))"

            # OperatingSystem filter
            if ($OperatingSystem) {
                $Filter = "(&$Filter(operatingSystem=$OperatingSystem))"
            }

            # Add computer-specific filters (not delegated to Get-DomainObject)
            if ($Unconstrained) {
                # TRUSTED_FOR_DELEGATION Flag (524288) - but NOT Domain Controllers
                $Filter = "(&$Filter(userAccountControl:1.2.840.113556.1.4.803:=524288)(!(primaryGroupID=516)))"
            }

            if ($Constrained) {
                # Constrained Delegation: Has msDS-AllowedToDelegateTo attribute
                # This includes both regular Constrained Delegation and Protocol Transition
                $Filter = "(&$Filter(msDS-AllowedToDelegateTo=*))"
            }

            if ($RBCD) {
                # Resource-Based Constrained Delegation: Has msDS-AllowedToActOnBehalfOfOtherIdentity attribute
                # The target resource controls who can delegate to it (stored as Security Descriptor)
                $Filter = "(&$Filter(msDS-AllowedToActOnBehalfOfOtherIdentity=*))"
            }

            if ($LAPS) {
                # Computers with LAPS enabled (Legacy or Native)
                # Legacy LAPS: ms-Mcs-AdmPwdExpirationTime
                # Windows LAPS: msLAPS-PasswordExpirationTime
                $Filter = "(&$Filter(|(ms-Mcs-AdmPwdExpirationTime=*)(msLAPS-PasswordExpirationTime=*)))"
            }

            # HighValueSPN: Computers running high-value/security-critical services
            if ($HighValueSPN) {
                # Exchange SPNs are also registered on Domain Controllers for Autodiscover - exclude DCs for Exchange
                # Other services (MSSQL, CA, etc.) can legitimately run on DCs, so we don't exclude them globally
                $HighValueSPNFilter = "(|" +
                    "(servicePrincipalName=MSSQLSvc/*)" +           # SQL Server
                    "(&(|(servicePrincipalName=exchangeMDB/*)(servicePrincipalName=exchangeRFR/*)(servicePrincipalName=exchangeAB/*))(!(primaryGroupID=516)))" +  # Exchange (exclude DCs)
                    "(servicePrincipalName=SMS Site Server/*)" +    # SCCM/MECM
                    "(servicePrincipalName=CmRcService/*)" +        # SCCM Remote Control
                    "(servicePrincipalName=adfssrv/*)" +            # ADFS
                    "(servicePrincipalName=certsvc/*)" +            # Certificate Authority
                    "(servicePrincipalName=MSOMHSvc/*)" +           # SCOM
                    "(servicePrincipalName=MSOMSdkSvc/*)" +         # SCOM SDK
                    "(servicePrincipalName=wbengine/*)" +           # Windows Backup
                    "(servicePrincipalName=veeam*)" +               # Veeam Backup
                    "(servicePrincipalName=wsusService/*)" +        # WSUS
                    ")"
                $Filter = "(&$Filter$HighValueSPNFilter)"
                Write-Log "[Get-DomainComputer] HighValueSPN filter applied"
            }

            # KnownSPN: Filter by specific known service type
            if ($KnownSPN) {
                $SPNFilter = switch ($KnownSPN) {
                    'MSSQL'    { "(servicePrincipalName=MSSQLSvc/*)" }
                    # Exchange: Exclude Domain Controllers (primaryGroupID=516) as they also have Exchange SPNs for Autodiscover
                    'Exchange' { "(&(|(servicePrincipalName=exchangeMDB/*)(servicePrincipalName=exchangeRFR/*)(servicePrincipalName=exchangeAB/*))(!(primaryGroupID=516)))" }
                    'SCCM'     { "(|(servicePrincipalName=SMS Site Server/*)(servicePrincipalName=CmRcService/*))" }
                    'WSUS'     { "(|(servicePrincipalName=wsusService/*)(servicePrincipalName=WSUS/*))" }
                    'ADFS'     { "(servicePrincipalName=adfssrv/*)" }
                    'CA'       { "(servicePrincipalName=certsvc/*)" }
                    'SCOM'     { "(|(servicePrincipalName=MSOMHSvc/*)(servicePrincipalName=MSOMSdkSvc/*))" }
                    'Backup'   { "(|(servicePrincipalName=wbengine/*)(servicePrincipalName=veeam*))" }
                    'HyperV'   { "(|(servicePrincipalName=Microsoft Virtual Console Service/*)(servicePrincipalName=vmms/*))" }
                    'RDP'      { "(servicePrincipalName=TERMSRV/*)" }
                    'WinRM'    { "(servicePrincipalName=WSMAN/*)" }
                    'HTTP'     { "(servicePrincipalName=HTTP/*)" }
                    'FTP'      { "(servicePrincipalName=FTP/*)" }
                }
                $Filter = "(&$Filter$SPNFilter)"
                Write-Log "[Get-DomainComputer] KnownSPN filter applied: $KnownSPN"
            }

            # Append custom LDAP filter
            if ($LDAPFilter) {
                $Filter = "(&$Filter$LDAPFilter)"
            }

            Write-Log "[Get-DomainComputer] Using filter: $Filter"

            # Build parameters for Get-DomainObject
            $GetParams = @{
                LDAPFilter = $Filter
            }

            # Pass through Identity parameter
            if ($Identity) {
                $GetParams['Identity'] = $Identity
            }

            # Pass through other parameters
            if ($Properties) { $GetParams['Properties'] = $Properties }
            if ($ShowOwner) { $GetParams['ShowOwner'] = $true }
            if ($SearchBase) { $GetParams['SearchBase'] = $SearchBase }
            if ($Domain) { $GetParams['Domain'] = $Domain }
            if ($Server) { $GetParams['Server'] = $Server }
            if ($Credential) { $GetParams['Credential'] = $Credential }
            if ($Raw) { $GetParams['Raw'] = $true }

            # Pass through LDAP-optimized account filters to Get-DomainObject
            if ($Enabled) { $GetParams['IsEnabled'] = $true }
            if ($Disabled) { $GetParams['IsDisabled'] = $true }
            if ($SPN) { $GetParams['HasSPN'] = $true }
            if ($TrustedToAuth) { $GetParams['TrustedToAuthForDelegation'] = $true }
            if ($PasswordAgeDays -gt 0) { $GetParams['PasswordAgeDays'] = $PasswordAgeDays }
            if ($InactiveDays -gt 0) { $GetParams['InactiveDays'] = $InactiveDays }
            if ($NeverLoggedIn) { $GetParams['NeverLoggedIn'] = $true }
            if ($ResultLimit -gt 0) { $GetParams['ResultLimit'] = $ResultLimit }

            $Computers = @(Get-DomainObject @GetParams)

            Write-Log "[Get-DomainComputer] Found $($Computers.Count) computer(s)"

            return $Computers

        } catch {
            Write-Log "[Get-DomainComputer] Error: $_"
            throw
        }
    }

    end {
        Write-Log "[Get-DomainComputer] Computer enumeration completed"
    }
}



# ----- Get-DomainGroup.ps1 -----

function Get-DomainGroup {
<#
.SYNOPSIS
    Central function for querying group objects from Active Directory.

.DESCRIPTION
    Get-DomainGroup is a flexible helper function that unifies all group queries in adPEAS v2.
    It builds on Invoke-LDAPSearch and provides:

    - Search by Identity (sAMAccountName, DN, SID, DOMAIN\group)
    - Filter by specific criteria (AdminCount, GroupScope, GroupCategory, etc.)
    - Flexible property selection
    - Custom LDAP filters

.PARAMETER Identity
    sAMAccountName, DistinguishedName, SID or DOMAIN\group format.
    Wildcards are supported.

.PARAMETER AdminCount
    Only groups with adminCount=1 (privileged groups).

.PARAMETER GroupScope
    Filter by Group Scope: DomainLocal, Global, Universal.

.PARAMETER GroupCategory
    Filter by Group Category: Security, Distribution.

.PARAMETER LDAPFilter
    Custom LDAP filter for special queries.

.PARAMETER Properties
    Array of attribute names to return.
    Default: All default properties from Invoke-LDAPSearch.

.PARAMETER ShowOwner
    Retrieves and displays the owner of the group object.
    The owner has implicit control over the object.

.PARAMETER ShowMembers
    Resolves and displays all group members with their type and description.
    Members are shown in a formatted list (User, Computer, Group, gMSA, etc.).

.PARAMETER SearchBase
    Alternative SearchBase (DN). Default: Domain DN.

.EXAMPLE
    Get-DomainGroup -Identity "Domain Admins"
    Returns the Domain Admins group.

.EXAMPLE
    Get-DomainGroup -AdminCount
    Returns all privileged groups.

.EXAMPLE
    Get-DomainGroup -GroupScope Global -GroupCategory Security
    Returns all global security groups.

.EXAMPLE
    Get-DomainGroup -LDAPFilter "(description=*admin*)"
    Custom LDAP filter for special searches.

.EXAMPLE
    Get-DomainGroup -Identity "Domain Admins" -ShowMembers
    Shows all members of Domain Admins group with their types.

.OUTPUTS
    PSCustomObject with group attributes

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(DefaultParameterSetName='Default')]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [Alias('samAccountName', 'Name', 'Group')]
        [string]$Identity,

        [Parameter(Mandatory=$false)]
        [switch]$AdminCount,

        [Parameter(Mandatory=$false)]
        [ValidateSet('DomainLocal','Global','Universal')]
        [string]$GroupScope,

        [Parameter(Mandatory=$false)]
        [ValidateSet('Security','Distribution')]
        [string]$GroupCategory,

        [Parameter(Mandatory=$false)]
        [string]$LDAPFilter,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [switch]$ShowOwner,

        [Parameter(Mandatory=$false)]
        [switch]$ShowMembers,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$Raw
    )

    begin {
        Write-Log "[Get-DomainGroup] Starting group enumeration (wrapper for Get-DomainObject)"
    }

    process {
        try {
            # Validation: ShowMembers requires Identity (ignore if not provided)
            if ($ShowMembers -and -not $Identity) {
                Write-Log "[Get-DomainGroup] -ShowMembers requires -Identity parameter - ignoring ShowMembers switch"
                $ShowMembers = $false
            }

            # Base Filter: group objects only
            $Filter = "(objectClass=group)"

            # AdminCount filter
            if ($AdminCount) {
                $Filter = "(&$Filter(adminCount=1))"
            }

            # GroupScope filter
            if ($GroupScope) {
                switch ($GroupScope) {
                    'Global' {
                        $Filter = "(&$Filter(groupType:1.2.840.113556.1.4.803:=2))"
                    }
                    'DomainLocal' {
                        $Filter = "(&$Filter(groupType:1.2.840.113556.1.4.803:=4))"
                    }
                    'Universal' {
                        $Filter = "(&$Filter(groupType:1.2.840.113556.1.4.803:=8))"
                    }
                }
            }

            # GroupCategory filter
            if ($GroupCategory) {
                switch ($GroupCategory) {
                    'Security' {
                        $Filter = "(&$Filter(groupType:1.2.840.113556.1.4.803:=2147483648))"
                    }
                    'Distribution' {
                        $Filter = "(&$Filter(!(groupType:1.2.840.113556.1.4.803:=2147483648)))"
                    }
                }
            }

            # Append custom LDAP filter
            if ($LDAPFilter) {
                $Filter = "(&$Filter$LDAPFilter)"
            }

            Write-Log "[Get-DomainGroup] Using filter: $Filter"

            # Build parameters for Get-DomainObject
            $GetParams = @{
                LDAPFilter = $Filter
            }

            # Pass through Identity parameter
            if ($Identity) {
                $GetParams['Identity'] = $Identity
            }

            # Pass through other parameters
            if ($Properties) { $GetParams['Properties'] = $Properties }
            if ($ShowOwner) { $GetParams['ShowOwner'] = $true }
            if ($SearchBase) { $GetParams['SearchBase'] = $SearchBase }
            if ($Domain) { $GetParams['Domain'] = $Domain }
            if ($Server) { $GetParams['Server'] = $Server }
            if ($Credential) { $GetParams['Credential'] = $Credential }
            if ($Raw) { $GetParams['Raw'] = $true }

            $Groups = @(Get-DomainObject @GetParams)

            Write-Log "[Get-DomainGroup] Found $($Groups.Count) group(s)"

            # If ShowMembers is set, return only member DNs as array
            if ($ShowMembers) {
                foreach ($Group in $Groups) {
                    if ($Group.member) {
                        # Return member DNs directly
                        return $Group.member
                    } else {
                        # No members
                        return @()
                    }
                }
            }

            return $Groups

        } catch {
            Write-Log "[Get-DomainGroup] Error: $_"
            throw
        }
    }

    end {
        Write-Log "[Get-DomainGroup] Group enumeration completed"
    }
}



# ----- Get-DomainGPO.ps1 -----

function Get-DomainGPO {
<#
.SYNOPSIS
    Central function for querying Group Policy Objects from Active Directory.

.DESCRIPTION
    Get-DomainGPO is a flexible helper function that unifies all GPO queries in adPEAS v2.
    It builds on Invoke-LDAPSearch and provides:

    - Search by Identity (DisplayName, DN, GUID)
    - Filter by specific criteria (Linked to OU, Disabled, etc.)
    - Flexible property selection
    - Custom LDAP filters

.PARAMETER Identity
    DisplayName, DistinguishedName, or GUID of the GPO.
    Automatically detects format:
    - GUID: {31B2F340-016D-11D2-945F-00C04FB984F9} or 31B2F340-016D-11D2-945F-00C04FB984F9
    - DN: CN={GUID},CN=Policies,CN=System,DC=domain,DC=com
    - DisplayName: "Default Domain Policy" (wildcards supported)

.PARAMETER AppliedToOU
    Returns all GPOs that are applied to the specified OU (DN format).
    Finds GPOs by querying the OU's gPLink attribute.

.PARAMETER Enabled
    Only fully enabled GPOs (flags=0).

.PARAMETER Disabled
    Only fully disabled GPOs (flags=3, all settings disabled).

.PARAMETER Domain
    Target domain for GPO search.

.PARAMETER LDAPFilter
    Custom LDAP filter for special queries.

.PARAMETER Properties
    Array of attribute names to return.
    Default: displayName, name, gPCFileSysPath, versionNumber, flags, whenCreated, whenChanged

.PARAMETER SearchBase
    Alternative SearchBase (DN). Default: CN=Policies,CN=System,DC=domain,DC=com

.PARAMETER ShowLinkedOU
    Returns only the OUs where the GPO is linked (array of DNs).
    Similar to -ShowMembers in Get-DomainGroup.
    Does not return the GPO object itself.

.PARAMETER ShowDangerousSettings
    Analyzes GPO settings for dangerous configurations (Scheduled Tasks, Scripts, etc.).
    Adds a DangerousSettings property to each GPO object.
    DEFENSIVE USE ONLY - for identifying attack surface and misconfigurations.

.PARAMETER ShowPermissions
    Analyzes GPO ACLs for dangerous permissions (non-admin users with edit rights).
    Adds a DangerousPermissions property to each GPO object.
    DEFENSIVE USE ONLY - for identifying privilege escalation paths.

.EXAMPLE
    Get-DomainGPO
    Returns all GPOs in the domain.

.EXAMPLE
    Get-DomainGPO -Identity "Default Domain Policy"
    Returns the Default Domain Policy GPO by DisplayName.

.EXAMPLE
    Get-DomainGPO -Identity "{31B2F340-016D-11D2-945F-00C04FB984F9}"
    Returns GPO by GUID (with curly braces).

.EXAMPLE
    Get-DomainGPO -Identity "31B2F340-016D-11D2-945F-00C04FB984F9"
    Returns GPO by GUID (without curly braces).

.EXAMPLE
    Get-DomainGPO -AppliedToOU "OU=Workstations,DC=contoso,DC=com"
    Returns all GPOs applied to the Workstations OU.

.EXAMPLE
    Get-DomainGPO -Enabled
    Returns only fully enabled GPOs (all settings active).

.EXAMPLE
    Get-DomainGPO -Disabled
    Returns only fully disabled GPOs (all settings disabled).

.EXAMPLE
    Get-DomainGPO -Identity "Default Domain Policy" -ShowLinkedOU
    Returns only the OUs where Default Domain Policy is linked (array of DNs).

.EXAMPLE
    Get-DomainGPO -ShowDangerousSettings
    Analyzes all GPOs for dangerous configurations like Scheduled Tasks or Scripts.

.EXAMPLE
    Get-DomainGPO -ShowPermissions
    Analyzes all GPOs for dangerous ACL permissions.

.EXAMPLE
    Get-DomainGPO -ShowLinkedOU -ShowDangerousSettings -ShowPermissions
    Complete security analysis of all GPOs.

.EXAMPLE
    Get-DomainGPO -LDAPFilter "(displayName=*Admin*)"
    Custom LDAP filter for special searches.

.OUTPUTS
    PSCustomObject with GPO attributes

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [Alias('DisplayName', 'Name', 'GPO')]
        [string]$Identity,

        [Parameter(Mandatory=$false)]
        [Alias('LinkedOU')]
        [string]$AppliedToOU,

        [Parameter(Mandatory=$false)]
        [switch]$Enabled,

        [Parameter(Mandatory=$false)]
        [switch]$Disabled,

        [Parameter(Mandatory=$false)]
        [string]$LDAPFilter,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [switch]$ShowLinkedOU,

        [Parameter(Mandatory=$false)]
        [switch]$ShowDangerousSettings,

        [Parameter(Mandatory=$false)]
        [switch]$ShowPermissions,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$Raw
    )

    begin {
        Write-Log "[Get-DomainGPO] Starting GPO enumeration"
    }

    process {
        try {
            # Cache: Return cached GPOs for unfiltered calls (no Identity, no LDAPFilter, no switches)
            $isUnfilteredCall = -not $Identity -and -not $LDAPFilter -and -not $AppliedToOU -and -not $Enabled -and -not $Disabled -and -not $ShowLinkedOU -and -not $ShowDangerousSettings -and -not $ShowPermissions -and -not $Properties -and -not $SearchBase -and -not $Raw
            if ($isUnfilteredCall -and $Script:CachedAllGPOs) {
                Write-Log "[Get-DomainGPO] Returning cached GPO list ($($Script:CachedAllGPOs.Count) objects)"
                return $Script:CachedAllGPOs
            }

            # Validation: ShowLinkedOU requires Identity (ignore if not provided)
            if ($ShowLinkedOU -and -not $Identity) {
                Write-Log "[Get-DomainGPO] -ShowLinkedOU requires -Identity parameter - ignoring ShowLinkedOU switch"
                $ShowLinkedOU = $false
            }

            # Base Filter: groupPolicyContainer objects only
            $Filter = "(objectClass=groupPolicyContainer)"

            # Build Identity filter (auto-detects DisplayName, DN, or GUID)
            if ($Identity) {
                # Check if DN, GUID or DisplayName
                if ($Identity -match '^CN=.*') {
                    # Distinguished Name - RFC 4515 escape so DNs containing '(' ')' or '*' stay valid
                    $escapedIdentityDN = Escape-LDAPFilterDN -DistinguishedName $Identity
                    $IdentityFilter = "(distinguishedName=$escapedIdentityDN)"
                    Write-Log "[Get-DomainGPO] Identity detected as DN"
                } elseif ($Identity -match '^\{?[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\}?$') {
                    # GUID format - remove curly braces if present
                    $CleanGUID = $Identity.Trim('{}')
                    $IdentityFilter = "(name={$CleanGUID})"
                    Write-Log "[Get-DomainGPO] Identity detected as GUID: {$CleanGUID}"
                } else {
                    # DisplayName (with wildcard support)
                    $IdentityFilter = "(displayName=$Identity)"
                    Write-Log "[Get-DomainGPO] Identity detected as DisplayName"
                }

                $Filter = "(&$Filter$IdentityFilter)"
            }

            # Enabled/Disabled filter
            if ($Enabled) {
                # flags=0 means GPO is fully enabled
                $Filter = "(&$Filter(flags=0))"
                Write-Log "[Get-DomainGPO] Filtering for enabled GPOs (flags=0)"
            }

            if ($Disabled) {
                # flags=3 means all settings disabled (both Computer and User portions)
                $Filter = "(&$Filter(flags=3))"
                Write-Log "[Get-DomainGPO] Filtering for disabled GPOs (flags=3)"
            }

            # AppliedToOU filter - search for GPOs applied to specific OU
            if ($AppliedToOU) {
                Write-Log "[Get-DomainGPO] Searching for GPOs applied to OU: $AppliedToOU"

                # Query the OU for its gPLink attribute via Get-DomainObject
                $OUParams = @{
                    Identity = $AppliedToOU
                    Properties = @('gPLink')
                }

                $OU = Get-DomainObject @OUParams | Select-Object -First 1

                if ($OU -and $OU.gPLink) {
                    Write-Log "[Get-DomainGPO] gPLink: $($OU.gPLink)"

                    # Parse gPLink to extract GPO GUIDs
                    # Format: [LDAP://cn={GUID},cn=policies,cn=system,DC=domain,DC=com;0]
                    $GPOGUIDs = @()
                    $gPLinkMatches = [regex]::Matches($OU.gPLink, '\{([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\}')

                    foreach ($Match in $gPLinkMatches) {
                        $GPOGUIDs += $Match.Groups[1].Value
                    }

                    if ($GPOGUIDs.Count -eq 0) {
                        Write-Log "[Get-DomainGPO] No GPOs applied to OU: $AppliedToOU"
                        return
                    }

                    Write-Log "[Get-DomainGPO] Found $($GPOGUIDs.Count) GPO(s) applied to OU"

                    # Build OR filter for all linked GPOs
                    if ($GPOGUIDs.Count -eq 1) {
                        $LinkedFilter = "(name={$($GPOGUIDs[0])})"
                    } else {
                        $LinkedFilterParts = $GPOGUIDs | ForEach-Object { "(name={$_})" }
                        $LinkedFilter = "(|$($LinkedFilterParts -join ''))"
                    }

                    $Filter = "(&$Filter$LinkedFilter)"
                } else {
                    Write-Log "[Get-DomainGPO] OU has no GPOs applied: $AppliedToOU"
                    return
                }
            }

            # Append custom LDAP filter
            if ($LDAPFilter) {
                $Filter = "(&$Filter$LDAPFilter)"
            }

            Write-Log "[Get-DomainGPO] Using filter: $Filter"

            # Build parameters for Get-DomainObject
            $GetParams = @{
                LDAPFilter = $Filter
            }

            # Do NOT pass Identity to Get-DomainObject!
            # The Identity filter is already built into $Filter above. Passing Identity would cause Get-DomainObject to override our filter.
            if ($Properties) {
                $GetParams['Properties'] = $Properties
            }

            if ($SearchBase) { $GetParams['SearchBase'] = $SearchBase }
            if ($Domain) { $GetParams['Domain'] = $Domain }
            if ($Server) { $GetParams['Server'] = $Server }
            if ($Credential) { $GetParams['Credential'] = $Credential }
            if ($Raw) { $GetParams['Raw'] = $true }

            $GPOs = @(Get-DomainObject @GetParams)

            Write-Log "[Get-DomainGPO] Found $($GPOs.Count) GPO(s)"

            # Enrich GPO objects with additional computed properties
            foreach ($GPO in $GPOs) {
                # Parse version number (high word = computer, low word = user)
                if ($GPO.versionNumber) {
                    $VersionNum = [int]$GPO.versionNumber
                    $ComputerVersion = $VersionNum -shr 16
                    $UserVersion = $VersionNum -band 0xFFFF

                    $GPO | Add-Member -NotePropertyName "ComputerVersion" -NotePropertyValue $ComputerVersion -Force
                    $GPO | Add-Member -NotePropertyName "UserVersion" -NotePropertyValue $UserVersion -Force
                }

                # Parse flags
                if ($null -ne $GPO.flags) {
                    $FlagsValue = [int]$GPO.flags
                    $Status = switch ($FlagsValue) {
                        0 { "Enabled" }
                        1 { "User portion disabled" }
                        2 { "Computer portion disabled" }
                        3 { "All settings disabled" }
                        default { "Unknown ($FlagsValue)" }
                    }

                    $GPO | Add-Member -NotePropertyName "GPOStatus" -NotePropertyValue $Status -Force
                }

                # CSE GUID to Name Mapping (Client-Side Extensions)
                $CSENames = @{
                    '{00000000-0000-0000-0000-000000000000}' = 'Core GPO Engine'
                    '{0E28E245-9368-4853-AD84-6DA3BA35BB75}' = 'Group Policy Preference Client Side Extension'
