}

<#
.SYNOPSIS
    Tests if an identity is an Exchange service group based on its Distinguished Name.

.DESCRIPTION
    Exchange service groups are created during Exchange installation and reside in the
    "OU=Microsoft Exchange Security Groups" organizational unit. This OU name remains
    English even in non-English AD installations, making it a reliable, language-independent
    detection method.

    Exchange groups (like "Exchange Windows Permissions", "Exchange Trusted Subsystem", etc.)
    have extensive AD permissions by design. These permissions are required for Exchange
    to function and cannot be removed without breaking Exchange functionality.

    Groups detected as Exchange service groups are classified as "ExchangeService" category
    and treated as "Attention" (not "Finding") in security checks because:
    1. The permissions are by-design and cannot be removed
    2. They are not misconfiguration that the customer can fix
    3. Pentesters should still know WHERE Exchange has permissions

.PARAMETER Identity
    The identity to check. Accepts:
    - Distinguished Name string (e.g., "CN=Exchange Windows Permissions,OU=Microsoft Exchange Security Groups,DC=domain,DC=com")
    - AD Object with distinguishedName property
    - SID string (will resolve to DN via LDAP)

.OUTPUTS
    [PSCustomObject] with:
    - IsExchangeService: $true if identity is an Exchange service group
    - Reason: Description of the match (or $null if not matched)
    - DistinguishedName: The DN that was checked

.EXAMPLE
    $result = Test-IsExchangeServiceGroup -Identity "CN=Exchange Windows Permissions,OU=Microsoft Exchange Security Groups,DC=contoso,DC=com"
    $result.IsExchangeService  # $true

.EXAMPLE
    $result = Test-IsExchangeServiceGroup -Identity $groupObject
    if ($result.IsExchangeService) { "Exchange service group - by-design permissions" }

.NOTES
    Author: Alexander Sturz (@_61106960_)
    The OU name "Microsoft Exchange Security Groups" is always English, even in localized AD installations.
#>
function Test-IsExchangeServiceGroup {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true)]
        $Identity
    )

    process {
        $dn = $null
        $sid = $null

        # Extract DN and SID from various input formats
        if ($Identity -is [PSCustomObject] -or $Identity -is [System.Collections.Hashtable]) {
            if ($Identity.distinguishedName) {
                $dn = $Identity.distinguishedName
            } elseif ($Identity.DistinguishedName) {
                $dn = $Identity.DistinguishedName
            }
            if ($Identity.objectSid) {
                $sid = $Identity.objectSid
            } elseif ($Identity.SID) {
                $sid = $Identity.SID
            }
        }
        elseif ($Identity -is [string]) {
            if ($Identity -match '^S-1-\d+-\d+') {
                $sid = $Identity
            }
            elseif ($Identity -match '^CN=|^OU=|^DC=') {
                $dn = $Identity
            }
            else {
                # sAMAccountName - try to resolve via LDAP
                if ($Script:LdapConnection) {
                    try {
                        $obj = @(Get-DomainObject -Identity $Identity -Properties 'distinguishedName')[0]
                        if ($obj -and $obj.distinguishedName) {
                            $dn = $obj.distinguishedName
                        }
                    } catch {
                        Write-Log "[Test-IsExchangeServiceGroup] Failed to resolve sAMAccountName: $Identity"
                    }
                }
            }
        }

        # Session-level cache - same SIDs appear across hundreds of OUs
        if (-not $Script:ExchangeGroupCache) {
            $Script:ExchangeGroupCache = @{}
        }

        # Check cache before expensive LDAP lookup
        $cacheKey = if ($sid) { $sid } elseif ($dn) { $dn.ToLowerInvariant() } else { $null }
        if ($cacheKey -and $Script:ExchangeGroupCache.ContainsKey($cacheKey)) {
            return $Script:ExchangeGroupCache[$cacheKey]
        }

        # If we only have SID, resolve to DN
        if (-not $dn -and $sid -and $Script:LdapConnection) {
            try {
                $sidHex = ConvertTo-LDAPSIDHex -SID $sid
                if ($sidHex) {
                    $obj = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" -Properties 'distinguishedName')[0]
                    if ($obj -and $obj.distinguishedName) {
                        $dn = $obj.distinguishedName
                    }
                }
            } catch {
                Write-Log "[Test-IsExchangeServiceGroup] Failed to resolve SID to DN: $sid"
            }
        }

        # No DN available - cannot determine
        if (-not $dn) {
            $result = [PSCustomObject]@{
                IsExchangeService = $false
                Reason = $null
                DistinguishedName = $null
            }
            if ($cacheKey) { $Script:ExchangeGroupCache[$cacheKey] = $result }
            return $result
        }

        # Check if DN contains Exchange Security Groups OU (language-independent)
        # The OU name is always "Microsoft Exchange Security Groups" even in non-English installations
        if ($dn -match 'OU=Microsoft Exchange Security Groups') {
            Write-Log "[Test-IsExchangeServiceGroup] Exchange service group detected: $dn"
            $result = [PSCustomObject]@{
                IsExchangeService = $true
                Reason = "Member of Exchange Security Groups OU (by-design permissions)"
                DistinguishedName = $dn
            }
            if ($cacheKey) { $Script:ExchangeGroupCache[$cacheKey] = $result }
            return $result
        }

        # Not an Exchange service group
        $result = [PSCustomObject]@{
            IsExchangeService = $false
            Reason = $null
            DistinguishedName = $dn
        }
        if ($cacheKey) { $Script:ExchangeGroupCache[$cacheKey] = $result }
        return $result
    }
}

<#
.SYNOPSIS
    Tests if a computer is an Exchange Server based on Exchange-specific SPNs.

.DESCRIPTION
    Exchange Servers register characteristic Service Principal Names (SPNs) that
    uniquely identify them as Exchange infrastructure:
    - exchangeMDB/* - Mailbox Database service
    - exchangeRFR/* - Referral service (Address Book)
    - exchangeAB/*  - Address Book service

    This function queries the computer's servicePrincipalName attribute and checks
    for these Exchange-specific SPNs.

.PARAMETER Identity
    Can be:
    - SID string (e.g., "S-1-5-21-...")
    - Distinguished Name (e.g., "CN=EX01,OU=Servers,DC=contoso,DC=com")
    - sAMAccountName (e.g., "EX01$")
    - PSCustomObject with objectSid/SID/distinguishedName property

.OUTPUTS
    [PSCustomObject] with properties:
    - IsExchangeServer: Boolean indicating if computer is an Exchange Server
    - SPNs: Array of Exchange-specific SPNs found (if any)
    - ComputerName: The computer's name

.EXAMPLE
    $result = Test-IsExchangeServer -Identity "S-1-5-21-xxx-1001"
    if ($result.IsExchangeServer) { "This is an Exchange Server" }

.EXAMPLE
    $result = Test-IsExchangeServer -Identity "CN=EX01,OU=Servers,DC=contoso,DC=com"

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Exchange SPNs are language-independent and reliable across all Exchange versions.
#>
function Test-IsExchangeServer {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true)]
        $Identity
    )

    process {
        $sid = $null
        $dn = $null

        # Extract SID/DN from various input formats
        if ($Identity -is [PSCustomObject] -or $Identity -is [System.Collections.Hashtable]) {
            if ($Identity.objectSid) { $sid = $Identity.objectSid }
            elseif ($Identity.SID) { $sid = $Identity.SID }
            if ($Identity.distinguishedName) { $dn = $Identity.distinguishedName }
            elseif ($Identity.DistinguishedName) { $dn = $Identity.DistinguishedName }
        }
        elseif ($Identity -is [string]) {
            if ($Identity -match '^S-1-\d+-\d+') {
                $sid = $Identity
            }
            elseif ($Identity -match '^CN=|^OU=|^DC=') {
                $dn = $Identity
            }
            else {
                # Assume sAMAccountName - will resolve via LDAP
                $sid = $Identity
            }
        }

        # Need LDAP connection
        if (-not $Script:LdapConnection) {
            return [PSCustomObject]@{
                IsExchangeServer = $false
                SPNs = @()
                ComputerName = $null
            }
        }

        # Build LDAP filter based on what we have
        $ldapFilter = $null
        if ($sid -and $sid -match '^S-1-\d+-\d+') {
            $sidHex = ConvertTo-LDAPSIDHex -SID $sid
            if ($sidHex) {
                $ldapFilter = "(objectSid=$sidHex)"
            }
        }
        elseif ($dn) {
            # For DN, we need to escape special characters
            $escapedDN = $dn -replace '([\\*\(\)])', '\$1'
            $ldapFilter = "(distinguishedName=$escapedDN)"
        }
        elseif ($sid) {
            # Assume it's a sAMAccountName
            $ldapFilter = "(sAMAccountName=$sid)"
        }

        if (-not $ldapFilter) {
            return [PSCustomObject]@{
                IsExchangeServer = $false
                SPNs = @()
                ComputerName = $null
            }
        }

        try {
            $obj = @(Get-DomainObject -LDAPFilter $ldapFilter -Properties 'servicePrincipalName', 'name', 'sAMAccountName', 'objectClass')[0]

            if (-not $obj) {
                return [PSCustomObject]@{
                    IsExchangeServer = $false
                    SPNs = @()
                    ComputerName = $null
                }
            }

            # Check if it's a computer
            $objectClasses = @($obj.objectClass)
            if ($objectClasses -notcontains 'computer') {
                return [PSCustomObject]@{
                    IsExchangeServer = $false
                    SPNs = @()
                    ComputerName = $obj.name
                }
            }

            # Check for Exchange-specific SPNs
            $spns = @($obj.servicePrincipalName)
            $exchangeSPNs = @($spns | Where-Object {
                $_ -match '^exchangeMDB/' -or
                $_ -match '^exchangeRFR/' -or
                $_ -match '^exchangeAB/'
            })

            $computerName = if ($obj.name) { $obj.name } elseif ($obj.sAMAccountName) { $obj.sAMAccountName -replace '\$$' } else { $null }

            if ($exchangeSPNs.Count -gt 0) {
                Write-Log "[Test-IsExchangeServer] Exchange Server detected: $computerName (SPNs: $($exchangeSPNs -join ', '))"
                return [PSCustomObject]@{
                    IsExchangeServer = $true
                    SPNs = $exchangeSPNs
                    ComputerName = $computerName
                }
            }

            return [PSCustomObject]@{
                IsExchangeServer = $false
                SPNs = @()
                ComputerName = $computerName
            }

        } catch {
            Write-Log "[Test-IsExchangeServer] Error checking $Identity`: $_"
            return [PSCustomObject]@{
                IsExchangeServer = $false
                SPNs = @()
                ComputerName = $null
            }
        }
    }
}

<#
.SYNOPSIS
    Gets all recursive group memberships for an identity (cached).

.DESCRIPTION
    Uses a single LDAP query with LDAP_MATCHING_RULE_IN_CHAIN (1.2.840.113556.1.4.1941) to retrieve ALL groups where the identity is a direct or nested member.
    Results are cached for subsequent lookups (SID -> Array of Group SIDs).

.PARAMETER IdentitySID
    The SID of the identity to check.

.PARAMETER IdentityDN
    The Distinguished Name of the identity. If not provided, will be resolved from SID.

.PARAMETER NoCache
    Bypasses the cache and forces a new LDAP query.

.OUTPUTS
    [String[]] - Array of group SIDs where the identity is a (recursive) member.
    Returns empty array if identity is not a member of any groups.

.EXAMPLE
    $groupSIDs = Get-RecursiveGroupMembership -IdentitySID "S-1-5-21-xxx-1234"
    if ($groupSIDs -contains "S-1-5-21-xxx-512") { "Member of Domain Admins" }

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
function Get-RecursiveGroupMembership {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$IdentitySID,

        [Parameter(Mandatory=$false)]
        [string]$IdentityDN,

        [Parameter(Mandatory=$false)]
        [switch]$NoCache
    )

    # Check cache first (unless NoCache is specified)
    if (-not $NoCache -and $Script:GroupMembershipCache.ContainsKey($IdentitySID)) {
        Write-Log "[Get-RecursiveGroupMembership] Cache hit for $IdentitySID"
        return $Script:GroupMembershipCache[$IdentitySID]
    }

    # Need LDAP connection
    if (-not $Script:LdapConnection) {
        Write-Log "[Get-RecursiveGroupMembership] No LDAP connection available"
        return @()
    }

    # Resolve DN from SID if not provided
    if (-not $IdentityDN) {
        try {
            $sidHex = ConvertTo-LDAPSIDHex -SID $IdentitySID
            if ($sidHex) {
                $obj = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" -Properties 'distinguishedName')[0]
                if ($obj) {
                    $IdentityDN = $obj.distinguishedName
                    Write-Log "[Get-RecursiveGroupMembership] Resolved SID to DN: $IdentityDN"
                }
            }
        } catch {
            Write-Log "[Get-RecursiveGroupMembership] Failed to resolve SID to DN: $_"
        }

        # Still no DN after resolution attempt (either exception or object not found)
        if (-not $IdentityDN) {
            Write-Log "[Get-RecursiveGroupMembership] No DN available for $IdentitySID"
            $Script:GroupMembershipCache[$IdentitySID] = @()
            return @()
        }
    }

    # Single LDAP query: Get ALL groups where identity is a recursive member
    # Query pattern: (member:1.2.840.113556.1.4.1941:=<DN>)
    $groupSIDs = @()

    try {
        Write-Log "[Get-RecursiveGroupMembership] Querying all group memberships for: $IdentityDN"

        # Escape DN for LDAP filter (special characters in DN)
        $escapedDN = Escape-LDAPFilterValue -Value $IdentityDN

        $filter = "(member:1.2.840.113556.1.4.1941:=$escapedDN)"
        $groups = @(Get-DomainGroup -LDAPFilter $filter -Properties 'objectSid','sAMAccountName')

        if ($groups) {
            foreach ($group in $groups) {
                if ($group.objectSid) {
                    $groupSIDs += $group.objectSid
                    Write-Log "[Get-RecursiveGroupMembership] Found membership: $($group.sAMAccountName) ($($group.objectSid))"
                }
            }
        }

        Write-Log "[Get-RecursiveGroupMembership] Found $($groupSIDs.Count) group membership(s) for $IdentitySID"

    } catch {
        Write-Log "[Get-RecursiveGroupMembership] Error querying group memberships: $_"
    }

    # Cache the result
    $Script:GroupMembershipCache[$IdentitySID] = $groupSIDs
    Write-Log "[Get-RecursiveGroupMembership] Cached result for $IdentitySID"

    return $groupSIDs
}

function Test-IsPrivileged {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true)]
        $Identity,

        [Parameter(Mandatory=$false)]
        [switch]$IncludeOperators,

        [Parameter(Mandatory=$false)]
        [switch]$NoCache
    )

    process {
        # ===== PHASE 1: Identity Resolution =====
        # Extract SID, DN, and name from various input formats
        $sid = $null
        $dn = $null
        $name = $null

        # Handle AD Objects (PSCustomObject/Hashtable with objectSid)
        if ($Identity -is [PSCustomObject] -or $Identity -is [System.Collections.Hashtable]) {
            if ($Identity.objectSid) {
                $sid = $Identity.objectSid
            } elseif ($Identity.SID) {
                $sid = $Identity.SID
            }
            if ($Identity.distinguishedName) {
                $dn = $Identity.distinguishedName
            } elseif ($Identity.DistinguishedName) {
                $dn = $Identity.DistinguishedName
            }
            if ($Identity.sAMAccountName) {
                $name = $Identity.sAMAccountName
            } elseif ($Identity.name) {
                $name = $Identity.name
            }
        }
        elseif ($Identity -is [System.Security.Principal.SecurityIdentifier]) {
            $sid = $Identity.Value
        }
        elseif ($Identity -is [string]) {
            if ($Identity -match '^S-1-\d+-\d+') {
                $sid = $Identity
            } else {
                $sid = ConvertTo-SID -Identity $Identity
                $name = $Identity
            }
        }

        if (-not $sid) {
            Write-Log "[Test-IsPrivileged] Could not resolve identity to SID: $Identity"
            return [PSCustomObject]@{
                IsPrivileged = $null
                Category = 'Unknown'
                Reason = 'Could not resolve identity to SID'
                MatchedSID = $null
                MatchedGroup = $null
                Identity = $Identity
            }
        }

        # ===== PHASE 2: Cache Check =====
        $cacheKey = $sid

        if (-not $NoCache -and $Script:PrivilegedCheckCache.ContainsKey($cacheKey)) {
            $cached = $Script:PrivilegedCheckCache[$cacheKey]
            # Return a copy with IsPrivileged computed for current flags
            $resultCopy = $cached.PSObject.Copy()
            $resultCopy.IsPrivileged = Get-IsPrivilegedFromCategory -Category $cached.Category -IncludeOperators:$IncludeOperators
            return $resultCopy
        }

        # Extract RID suffix
        $ridSuffix = Get-SIDRIDSuffix -SID $sid

        # ===== PHASE 3: Static SID Checks =====
        # 3a. Check Operator SIDs FIRST (separate category)
        if ($sid -in $Script:OperatorSIDs) {
            $result = [PSCustomObject]@{
                IsPrivileged = $false
                Category = 'Operator'
                Reason = "Operator group (static SID)"
                MatchedSID = $sid
                MatchedGroup = $null
                Identity = $Identity
            }
            Write-Log "[Test-IsPrivileged] Operator detected: $sid"
            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
        }

        # 3a2. Check Operator RID suffixes (domain-relative, e.g., Cert Publishers -517)
        if ($ridSuffix -and $ridSuffix -in $Script:OperatorRIDSuffixes) {
            $result = [PSCustomObject]@{
                IsPrivileged = $false
                Category = 'Operator'
                Reason = "Operator group (RID suffix $ridSuffix)"
                MatchedSID = $sid
                MatchedGroup = $null
                Identity = $Identity
            }
            Write-Log "[Test-IsPrivileged] Operator via RID suffix: $sid"
            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
        }

        # 3b. Check Privileged SIDs (static well-known)
        if ($sid -in $Script:PrivilegedSIDs) {
            $result = [PSCustomObject]@{
                IsPrivileged = $false
                Category = 'Privileged'
                Reason = "Privileged identity (static SID)"
                MatchedSID = $sid
                MatchedGroup = $null
                Identity = $Identity
            }
            Write-Log "[Test-IsPrivileged] Privileged via static SID: $sid"
            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
        }

        # 3c. Check Privileged RID suffixes (precise matching)
        if ($ridSuffix -and $ridSuffix -in $Script:PrivilegedRIDSuffixes) {
            $result = [PSCustomObject]@{
                IsPrivileged = $false
                Category = 'Privileged'
                Reason = "Privileged group (RID suffix $ridSuffix)"
                MatchedSID = $sid
                MatchedGroup = $null
                Identity = $Identity
            }
            Write-Log "[Test-IsPrivileged] Privileged via RID suffix: $sid"
            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
        }

        # 3d. Check Broad Group SIDs (static well-known)
        # We defer the return to Phase 5 to check if the BroadGroup is member of a Privileged group.
        $isBroadGroup = $false
        $broadGroupReason = $null

        if ($sid -in $Script:BroadGroupSIDs) {
            $isBroadGroup = $true
            $broadGroupReason = "Broad group (static SID)"
            Write-Log "[Test-IsPrivileged] BroadGroup detected (static): $sid - checking for privileged membership..."
        }

        # 3e. Check Broad Group RID suffixes (precise matching)
        if (-not $isBroadGroup -and $ridSuffix -in $Script:BroadGroupRIDSuffixes) {
            $isBroadGroup = $true
            $broadGroupReason = "Broad group (RID suffix $ridSuffix)"
            Write-Log "[Test-IsPrivileged] BroadGroup detected (RID): $sid - checking for privileged membership..."
        }

        # Resolve name from SID only if not already known (needed for logging)
        if (-not $name -and $sid) {
            $name = ConvertFrom-SID -SID $sid
        }

        Write-Log "[Test-IsPrivileged] Checking SID: $sid (Name: $name)"

        # ===== PHASE 4: sIDHistory Check (SID History Injection Detection) =====
        # Check if this identity has privileged SIDs in sIDHistory attribute.
        # Only domain SIDs (S-1-5-21-*) can have sIDHistory - well-known SIDs
        # (SYSTEM, Administrators, Everyone, etc.) have no AD object to query.
        $isDomainSID = $sid -match '^S-1-5-21-'
        if ($Script:LdapConnection -and $isDomainSID) {
            try {
                # Query the AD object for sIDHistory + distinguishedName (reused by Phase 5)
                $sidHex = ConvertTo-LDAPSIDHex -SID $sid
                if ($sidHex) {
                    $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" -Properties 'sIDHistory','distinguishedName')[0]

                    # Capture DN for Phase 5 (avoids redundant LDAP query in Get-RecursiveGroupMembership)
                    if ($adObject -and $adObject.distinguishedName -and -not $dn) {
                        $dn = $adObject.distinguishedName
                    }

                    if ($adObject -and $adObject.sIDHistory) {
                        # sIDHistory can contain multiple SIDs
                        $sidHistoryValues = @()
                        if ($adObject.sIDHistory -is [array]) {
                            $sidHistoryValues = $adObject.sIDHistory
                        } else {
                            $sidHistoryValues = @($adObject.sIDHistory)
                        }

                        Write-Log "[Test-IsPrivileged] Found $($sidHistoryValues.Count) sIDHistory entries for $sid"

                        foreach ($historySID in $sidHistoryValues) {
                            # Convert byte array to SID string if needed
                            $historySIDString = $null
                            if ($historySID -is [byte[]]) {
                                try {
                                    $secId = New-Object System.Security.Principal.SecurityIdentifier($historySID, 0)
                                    $historySIDString = $secId.Value
                                } catch {
                                    Write-Log "[Test-IsPrivileged] Failed to convert sIDHistory byte array: $_"
                                    continue
                                }
                            } elseif ($historySID -is [string]) {
                                $historySIDString = $historySID
                            } else {
                                continue
                            }

                            Write-Log "[Test-IsPrivileged] Checking sIDHistory entry: $historySIDString"

                            # Check if this sIDHistory SID is privileged
                            $historyRIDSuffix = Get-SIDRIDSuffix -SID $historySIDString

                            # Check Operator SIDs in sIDHistory
                            if ($historySIDString -in $Script:OperatorSIDs) {
                                $result = [PSCustomObject]@{
                                    IsPrivileged = $false
                                    Category = 'Operator'
                                    Reason = "sIDHistory contains Operator SID (SID History Injection risk)"
                                    MatchedSID = $historySIDString
                                    MatchedGroup = $null
                                    Identity = $Identity
                                }
                                Write-Log "[Test-IsPrivileged] CRITICAL: sIDHistory contains Operator SID: $historySIDString"
                                return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                            }

                            # Check Operator RID suffixes in sIDHistory (e.g., Cert Publishers -517)
                            if ($historyRIDSuffix -and $historyRIDSuffix -in $Script:OperatorRIDSuffixes) {
                                $result = [PSCustomObject]@{
                                    IsPrivileged = $false
                                    Category = 'Operator'
                                    Reason = "sIDHistory contains Operator RID $historyRIDSuffix (SID History Injection risk)"
                                    MatchedSID = $historySIDString
                                    MatchedGroup = $null
                                    Identity = $Identity
                                }
                                Write-Log "[Test-IsPrivileged] CRITICAL: sIDHistory contains Operator RID: $historySIDString"
                                return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                            }

                            # Check Privileged SIDs in sIDHistory
                            if ($historySIDString -in $Script:PrivilegedSIDs) {
                                $result = [PSCustomObject]@{
                                    IsPrivileged = $false
                                    Category = 'Privileged'
                                    Reason = "sIDHistory contains privileged SID (SID History Injection risk)"
                                    MatchedSID = $historySIDString
                                    MatchedGroup = $null
                                    Identity = $Identity
                                }
                                Write-Log "[Test-IsPrivileged] CRITICAL: sIDHistory contains privileged SID: $historySIDString"
                                return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                            }

                            # Check Privileged RID suffixes in sIDHistory
                            if ($historyRIDSuffix -and $historyRIDSuffix -in $Script:PrivilegedRIDSuffixes) {
                                $result = [PSCustomObject]@{
                                    IsPrivileged = $false
                                    Category = 'Privileged'
                                    Reason = "sIDHistory contains privileged RID $historyRIDSuffix (SID History Injection risk)"
                                    MatchedSID = $historySIDString
                                    MatchedGroup = $null
                                    Identity = $Identity
                                }
                                Write-Log "[Test-IsPrivileged] CRITICAL: sIDHistory contains privileged RID: $historySIDString"
                                return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                            }
                        }
                    }
                }
            } catch {
                Write-Log "[Test-IsPrivileged] Error checking sIDHistory: $_"
            }
        }

        # ===== PHASE 5: Recursive Group Membership Check (ALWAYS when LDAP available) =====
        # Uses Get-RecursiveGroupMembership for a SINGLE LDAP query instead of N queries.
        if ($Script:LdapConnection) {
            # Get all group memberships with a single LDAP query (cached)
            $groupMemberships = Get-RecursiveGroupMembership -IdentitySID $sid -IdentityDN $dn

            if ($groupMemberships -and $groupMemberships.Count -gt 0) {
                Write-Log "[Test-IsPrivileged] Found $($groupMemberships.Count) group membership(s) for $sid"

                $domainSID = $null
                if ($Script:LDAPContext -and $Script:LDAPContext.DomainSID) {
                    $domainSID = $Script:LDAPContext.DomainSID
                }

                # 5a. Check Operator group membership (local array comparison)
                # First check static Operator SIDs
                foreach ($opSID in $Script:OperatorSIDs) {
                    if ($opSID -in $groupMemberships) {
                        $groupName = ConvertFrom-SID -SID $opSID
                        if (-not $groupName) { $groupName = $opSID }

                        $result = [PSCustomObject]@{
                            IsPrivileged = $false
                            Category = 'Operator'
                            Reason = "Member of Operator group"
                            MatchedSID = $opSID
                            MatchedGroup = $groupName
                            Identity = $Identity
                        }
                        Write-Log "[Test-IsPrivileged] Operator via membership: $groupName"
                        return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                    }
                }

                # Then check domain-relative Operator RID suffixes (e.g., Cert Publishers -517)
                if ($domainSID) {
                    foreach ($suffix in $Script:OperatorRIDSuffixes) {
                        $opSID = "$domainSID$suffix"
                        if ($opSID -in $groupMemberships) {
                            $groupName = ConvertFrom-SID -SID $opSID
                            if (-not $groupName) { $groupName = $opSID }

                            $result = [PSCustomObject]@{
                                IsPrivileged = $false
                                Category = 'Operator'
                                Reason = "Member of Operator group"
                                MatchedSID = $opSID
                                MatchedGroup = $groupName
                                Identity = $Identity
                            }
                            Write-Log "[Test-IsPrivileged] Operator via membership (RID suffix): $groupName"
                            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                        }
                    }
                }

                # 5b. Check Privileged group membership (local array comparison)
                $privilegedGroupSIDs = @('S-1-5-32-544')  # BUILTIN\Administrators
                if ($domainSID) {
                    foreach ($suffix in $Script:PrivilegedRIDSuffixes) {
                        $privilegedGroupSIDs += "$domainSID$suffix"
                    }
                }

                foreach ($groupSID in $privilegedGroupSIDs) {
                    if ($groupSID -in $groupMemberships) {
                        $groupName = ConvertFrom-SID -SID $groupSID
                        if (-not $groupName) { $groupName = $groupSID }

                        $result = [PSCustomObject]@{
                            IsPrivileged = $false
                            Category = 'Privileged'
                            Reason = "Member of privileged group"
                            MatchedSID = $groupSID
                            MatchedGroup = $groupName
                            Identity = $Identity
                        }
                        Write-Log "[Test-IsPrivileged] Privileged via membership: $groupName"
                        return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                    }
                }

                # 5c. Check BroadGroup membership (local array comparison)
                if ($domainSID) {
                    foreach ($suffix in $Script:BroadGroupRIDSuffixes) {
                        $broadSID = "$domainSID$suffix"
                        if ($broadSID -in $groupMemberships) {
                            $groupName = ConvertFrom-SID -SID $broadSID
                            if (-not $groupName) { $groupName = $broadSID }

                            $result = [PSCustomObject]@{
                                IsPrivileged = $false
                                Category = 'BroadGroup'
                                Reason = "Member of broad group"
                                MatchedSID = $broadSID
                                MatchedGroup = $groupName
                                Identity = $Identity
                            }
                            Write-Log "[Test-IsPrivileged] BroadGroup via membership: $groupName"
                            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
                        }
                    }
                }
            } else {
                Write-Log "[Test-IsPrivileged] No group memberships found for $sid"
            }
        } else {
            Write-Log "[Test-IsPrivileged] No LDAP connection - group membership check skipped"
        }

        # ===== PHASE 6: Final Category Determination =====
        # If we identified this as a BroadGroup in Phase 3/4 but deferred the result to check
        # for privileged group membership first, return BroadGroup now.
        if ($isBroadGroup) {
            $result = [PSCustomObject]@{
                IsPrivileged = $false
                Category = 'BroadGroup'
                Reason = $broadGroupReason
                MatchedSID = $sid
                MatchedGroup = $null
                Identity = $Identity
            }
            Write-Log "[Test-IsPrivileged] BroadGroup confirmed (no privileged membership found): $sid"
            return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
        }

        # Default: Standard Category
        $result = [PSCustomObject]@{
            IsPrivileged = $false
            Category = 'Standard'
            Reason = $null
            MatchedSID = $sid
            MatchedGroup = $null
            Identity = $Identity
        }
        Write-Log "[Test-IsPrivileged] Standard identity: $sid"
        return (Complete-PrivilegedCheck -Result $result -CacheKey $cacheKey -NoCache:$NoCache -IncludeOperators:$IncludeOperators)
    }
}

<#
.SYNOPSIS
    Determines if an ACL identity should be skipped based on the check context.

.DESCRIPTION
    Different security checks require different filtering logic:

    - Domain Root ACLs: SELF/Creator Owner are ABNORMAL (findings!)
    - OU/Container ACLs: SELF/Creator Owner are NORMAL (self-modification)
    - CN=Computers: SELF/Creator Owner/Pre-Win2000 are NORMAL (object management)

    This function returns $true if the identity should be SKIPPED (not a finding).

.PARAMETER SID
    The Security Identifier to check.

.PARAMETER Context
    The context of the check. Valid values:
    - 'DomainRoot': ACLs on the domain root object (DC=domain,DC=com)
    - 'OU': ACLs on Organizational Units
    - 'Container': ACLs on containers like CN=Computers
    - 'Object': ACLs on individual objects (users, computers, groups)

.OUTPUTS
    [PSCustomObject] with:
    - Skip: $true if the identity should be skipped completely
    - SkipAllPropertiesOnly: $true if only "All Properties" findings should be skipped (but specific property findings shown)
    - Reason: Why it should be skipped (or $null)

.EXAMPLE
    $result = Test-IsExpectedACLIdentity -SID 'S-1-5-10' -Context 'OU'
    if ($result.Skip) { continue }  # Skip SELF on OUs

.EXAMPLE
    $result = Test-IsExpectedACLIdentity -SID 'S-1-5-10' -Context 'DomainRoot'
    # Returns Skip=$false because SELF on Domain Root is abnormal!

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
function Test-IsExpectedACLIdentity {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$SID,

        [Parameter(Mandatory=$true)]
        [ValidateSet('DomainRoot', 'OU', 'Container', 'Object', 'GPO')]
        [string]$Context
    )

    $result = [PSCustomObject]@{
        Skip = $false
        SkipAllPropertiesOnly = $false  # If true: skip "All Properties" findings but show specific property findings
        Reason = $null
    }

    switch ($Context) {
        'DomainRoot' {
            # On Domain Root, NO special identities should be skipped!
            $result.Skip = $false
            $result.Reason = $null
        }

        'OU' {
            # On OUs, only SELF/Creator Owner should be completely skipped
            if ($SID -in $Script:SelfModificationSIDs) {
                $result.Skip = $true
                $result.Reason = "Self-modification identity (normal on OUs)"
            }
            elseif ($SID -in $Script:LegacyCompatibilitySIDs) {
                # Don't skip completely - only skip "All Properties" findings
                $result.Skip = $false
                $result.SkipAllPropertiesOnly = $true
                $result.Reason = "Legacy compatibility identity (has default read rights)"
            }
            elseif ($SID -in $Script:BroadGroupSIDs) {
                # Don't skip completely - only skip "All Properties" findings
                $result.Skip = $false
                $result.SkipAllPropertiesOnly = $true
                $result.Reason = "Broad group (has default read rights)"
            }
        }

        'Container' {
            # On Containers (like CN=Computers), several identities are expected:
            # - SELF, Creator Owner: self-modification
            # - Pre-Win2000: legacy compatibility
            # - Account/Print Operators: can manage computer accounts by design
            if ($SID -in $Script:SelfModificationSIDs) {
                $result.Skip = $true
                $result.Reason = "Self-modification identity (normal on containers)"
            }
            elseif ($SID -in $Script:LegacyCompatibilitySIDs) {
                $result.Skip = $true
                $result.Reason = "Legacy compatibility identity (normal on containers)"
            }
            elseif ($SID -in $Script:ContainerOperatorSIDs) {
                $result.Skip = $true
                $result.Reason = "Operator group (expected to manage computer accounts)"
            }
        }

        'Object' {
            # On individual objects, SELF is normal (object modifies itself)
            if ($SID -in $Script:SelfModificationSIDs) {
                $result.Skip = $true
                $result.Reason = "Self-modification identity (normal on objects)"
            }
        }

        'GPO' {
            # On GPOs, Creator Owner is a default ACE (creator has rights on created GPO), this is normal Windows behavior
            if ($SID -in $Script:SelfModificationSIDs) {
                $result.Skip = $true
                $result.Reason = "Self-modification identity (normal on GPOs - creator has rights)"
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Tests if an identity is EXPECTED in a specific security scope.

.DESCRIPTION
    Context-dependent check that answers: "Is this identity expected to have these rights?"
    Uses scope definitions from $Script:SecurityScopes to classify findings.

    This function is the complement to Test-IsPrivileged:
    - Test-IsPrivileged: "WHAT is this identity?" (factual classification)
    - Test-IsExpectedInScope: "Is it EXPECTED here?" (contextual judgment)

    Return Severities:
    - "Expected": Identity is expected in this scope (no finding needed)
    - "Attention": Identity is technically expected but security-relevant (soft finding)
    - "Finding": Identity should NOT have these rights (hard finding)

.PARAMETER Identity
    The identity to check. Accepts:
    - SID string (e.g., "S-1-5-21-...")
    - AD Object with objectSid property
    - sAMAccountName (will be resolved to SID)

.PARAMETER Scope
    The security scope to check against. Available scopes:
    - DCSync: Identities with replication rights
    - DomainRootACL: Identities with GenericAll/WriteDACL on domain root
    - OUACL: Identities with GenericAll/WriteDACL on OUs
    - ComputerContainerACL: Identities with CreateChild on CN=Computers
    - MachineAccountQuota: Identities that can create computer accounts via MAQ
    - UserObjectACL: Identities with write access to user objects
    - GPO: Identities that can create/edit GPOs
    - ADCSEnroll: Identities with certificate enrollment rights
    - KerberosDelegation: Identities with delegation configured
    - LAPSRead: Identities that can read LAPS passwords

.PARAMETER ReturnDetails
    Returns detailed object instead of just severity string.

.EXAMPLE
    Test-IsExpectedInScope -Identity "S-1-5-21-xxx-512" -Scope "DCSync"
    Returns "Finding" - Domain Admins should be flagged for DCSync (even if they have it).

.EXAMPLE
    Test-IsExpectedInScope -Identity "S-1-5-18" -Scope "DCSync"
    Returns "Expected" - SYSTEM is expected to have DCSync rights.

.EXAMPLE
    Test-IsExpectedInScope -Identity "S-1-5-11" -Scope "MachineAccountQuota"
    Returns "Attention" - Authenticated Users with MAQ is default but noteworthy.

.OUTPUTS
    [String] - Default: "Expected", "Attention", or "Finding"
    [PSCustomObject] - With -ReturnDetails: Detailed result object

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
function Test-IsExpectedInScope {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true)]
        $Identity,

        [Parameter(Mandatory=$true)]
        [ValidateSet(
            'DCSync',
            'DomainRootACL',
            'OUACL',
            'ComputerContainerACL',
            'MachineAccountQuota',
            'UserObjectACL',
            'GPO',
            'ADCSEnroll',
            'KerberosDelegation',
            'LAPSRead',
            'PKIContainer'
        )]
        [string]$Scope,

        [Parameter(Mandatory=$false)]
        [switch]$ReturnDetails
    )

    process {
        # ===== Get Scope Definition =====
        $scopeDef = $Script:SecurityScopes[$Scope]
        if (-not $scopeDef) {
            Write-Warning "[Test-IsExpectedInScope] Unknown scope: $Scope"
            if ($ReturnDetails) {
                return [PSCustomObject]@{
                    Severity = 'Finding'
                    Reason = "Unknown scope: $Scope"
                    Identity = $Identity
                    Scope = $Scope
                }
            }
            return 'Finding'
        }

        # ===== Resolve Identity to SID =====
        $sid = $null
        $name = $null

        if ($Identity -is [PSCustomObject] -or $Identity -is [System.Collections.Hashtable]) {
            if ($Identity.objectSid) { $sid = $Identity.objectSid }
            elseif ($Identity.SID) { $sid = $Identity.SID }
            if ($Identity.sAMAccountName) { $name = $Identity.sAMAccountName }
            elseif ($Identity.name) { $name = $Identity.name }
        }
        elseif ($Identity -is [System.Security.Principal.SecurityIdentifier]) {
            $sid = $Identity.Value
        }
        elseif ($Identity -is [string]) {
            if ($Identity -match '^S-1-\d+-\d+') {
                $sid = $Identity
            } else {
                $sid = ConvertTo-SID -Identity $Identity
                $name = $Identity
            }
        }

        if (-not $sid -and -not $name) {
            if ($ReturnDetails) {
                return [PSCustomObject]@{
                    Severity = 'Finding'
                    Reason = "Could not resolve identity"
                    Identity = $Identity
                    Scope = $Scope
                }
            }
            return 'Finding'
        }

        # Resolve name from SID if not already known
        if (-not $name -and $sid) {
            $name = ConvertFrom-SID -SID $sid
        }

        # ===== Check Static Expected SIDs =====
        if ($sid -and $scopeDef.ExpectedSIDs -and $sid -in $scopeDef.ExpectedSIDs) {
            if ($ReturnDetails) {
                return [PSCustomObject]@{
                    Severity = 'Expected'
                    Reason = "Static SID in scope '$Scope'"
                    Identity = $Identity
                    Scope = $Scope
                    MatchedSID = $sid
                }
            }
            return 'Expected'
        }

        # ===== Check Expected RID Suffixes (precise matching) =====
        if ($sid) {
            $ridSuffix = Get-SIDRIDSuffix -SID $sid
            if ($ridSuffix -and $scopeDef.ExpectedRIDSuffixes -and $ridSuffix -in $scopeDef.ExpectedRIDSuffixes) {
                if ($ReturnDetails) {
                    return [PSCustomObject]@{
                        Severity = 'Expected'
                        Reason = "RID suffix $ridSuffix in scope '$Scope'"
                        Identity = $Identity
                        Scope = $Scope
                        MatchedSID = $sid
                        MatchedRIDSuffix = $ridSuffix
                    }
                }
                return 'Expected'
            }
        }

        # ===== Check Attention Broad Groups =====
        if ($sid -and $scopeDef.AttentionBroadGroups -and $sid -in $scopeDef.AttentionBroadGroups) {
            if ($ReturnDetails) {
                return [PSCustomObject]@{
                    Severity = 'Attention'
                    Reason = "Broad group in scope '$Scope' (expected but noteworthy)"
                    Identity = $Identity
                    Scope = $Scope
                    MatchedSID = $sid
                }
            }
            return 'Attention'
        }

        # ===== PHASE 2: Recursive Group Membership Check (Cached) =====
        # If identity is not directly expected, check if it's a MEMBER of an expected group.
        # This reduces noise: e.g., a Domain Admin user with explicit ACE is not a new finding.
        # Returns "Attention" (not "Expected") because the explicit ACE is technically unnecessary.
        if ($Script:LdapConnection -and $sid) {
            # Get all group memberships for this identity (cached after first lookup)
            $identityGroupMemberships = Get-RecursiveGroupMembership -IdentitySID $sid

            if ($identityGroupMemberships -and $identityGroupMemberships.Count -gt 0) {
                $domainSID = $null
                if ($Script:LDAPContext -and $Script:LDAPContext.DomainSID) {
                    $domainSID = $Script:LDAPContext.DomainSID
                }

                # Build list of expected group SIDs for this scope
                $expectedGroupSIDs = @()

                # Add static expected SIDs (only groups, not SYSTEM etc.)
                if ($scopeDef.ExpectedSIDs) {
                    # BUILTIN\Administrators is a group
                    if ('S-1-5-32-544' -in $scopeDef.ExpectedSIDs) {
                        $expectedGroupSIDs += 'S-1-5-32-544'
                    }
                    # Account Operators, Server Operators, etc.
                    foreach ($expSID in $scopeDef.ExpectedSIDs) {
                        if ($expSID -match '^S-1-5-32-') {
                            $expectedGroupSIDs += $expSID
                        }
                    }
                }

                # Add domain-relative expected groups
                if ($domainSID -and $scopeDef.ExpectedRIDSuffixes) {
                    foreach ($suffix in $scopeDef.ExpectedRIDSuffixes) {
                        $expectedGroupSIDs += "$domainSID$suffix"
                    }
                }

                # Check if identity is member of any expected group
                foreach ($expectedGroupSID in $expectedGroupSIDs) {
                    if ($expectedGroupSID -in $identityGroupMemberships) {
                        # Resolve group name for display
                        $groupName = ConvertFrom-SID -SID $expectedGroupSID
                        if (-not $groupName) { $groupName = $expectedGroupSID }

                        # Identity is member of an expected group -> Attention (not Finding), because the explicit ACE is redundant but not a new attack vector
                        Write-Log "[Test-IsExpectedInScope] Identity $sid is member of expected group $groupName"
                        if ($ReturnDetails) {
                            return [PSCustomObject]@{
                                Severity = 'Attention'
                                Reason = "Member of expected group '$groupName' in scope '$Scope' (explicit ACE is redundant)"
                                Identity = $Identity
                                Scope = $Scope
                                ResolvedSID = $sid
                                MemberOfExpectedGroup = $groupName
                                MemberOfExpectedGroupSID = $expectedGroupSID
                            }
                        }
                        return 'Attention'
                    }
                }

            }
        }

        # ===== PHASE 3: Exchange Service Group Check =====
        # Before returning "Finding", check if this is an Exchange service group.
        # Exchange groups have by-design permissions that cannot be removed without breaking Exchange.
        # They should be shown as "Attention" (informational) rather than "Finding" (actionable).
        if ($Script:LdapConnection) {
            $exchangeCheck = Test-IsExchangeServiceGroup -Identity $Identity
            if ($exchangeCheck.IsExchangeService) {
                Write-Log "[Test-IsExpectedInScope] Exchange service group detected: $($exchangeCheck.DistinguishedName)"
                if ($ReturnDetails) {
                    return [PSCustomObject]@{
                        Severity = 'Attention'
                        Reason = "Exchange service group in scope '$Scope' (by-design permissions, cannot be removed)"
                        Identity = $Identity
                        Scope = $Scope
                        ResolvedSID = $sid
                        ResolvedName = $name
                        IsExchangeService = $true
                    }
                }
                return 'Attention'
            }
        }

        # ===== Not Expected (neither directly nor via group membership) =====
        if ($ReturnDetails) {
            return [PSCustomObject]@{
                Severity = 'Finding'
                Reason = "Identity not expected in scope '$Scope'"
                Identity = $Identity
                Scope = $Scope
                ResolvedSID = $sid
                ResolvedName = $name
            }
        }
        return 'Finding'
    }
}




# ----- Get-ObjectOwner.ps1 -----

<#
.SYNOPSIS
    Retrieves the owner of an AD object's security descriptor.

.DESCRIPTION
    Queries the nTSecurityDescriptor of an AD object to extract the owner SID and determines if it's a non-default owner.

    Default Owners (expected for User/Computer objects):
    - Domain Admins (-512)
    - Enterprise Admins (-519)
    - BUILTIN\Administrators (S-1-5-32-544)
    - NT AUTHORITY\SYSTEM (S-1-5-18)

.PARAMETER DistinguishedName
    The distinguishedName of the AD object to check.

.PARAMETER ADObject
    An AD object (from Get-DomainUser, Get-DomainComputer, etc.) with distinguishedName property.

.PARAMETER NonDefaultOnly
    Only return results for objects with non-default owners.
    If the owner is a default owner (Domain Admins, Enterprise Admins, etc.), returns $null.
    Useful for filtering to find security-relevant owner configurations.

.EXAMPLE
    Get-ObjectOwner -DistinguishedName "CN=JohnDoe,OU=Users,DC=contoso,DC=com"

.EXAMPLE
    $user | Get-ObjectOwner

.EXAMPLE
    Get-DomainComputer -Identity "WORKSTATION01" | Get-ObjectOwner

.EXAMPLE
    Get-DomainComputer | Get-ObjectOwner -NonDefaultOnly
    Returns only computers with non-default owners (potential security findings).

.OUTPUTS
    PSCustomObject with:
    - OwnerSID: The SID of the owner
    - OwnerName: Resolved name of the owner
    - IsDefaultOwner: $true if owner is Domain Admins/Enterprise Admins/Administrators/SYSTEM
    - DistinguishedName: The DN that was queried

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# Default owner SIDs - accounts expected to own AD objects
$Script:DefaultOwnerRIDSuffixes = @(
    '-512',   # Domain Admins
    '-519'    # Enterprise Admins
)

$Script:DefaultOwnerStaticSIDs = @(
    'S-1-5-32-544',  # BUILTIN\Administrators
    'S-1-5-18'       # NT AUTHORITY\SYSTEM
)

function Get-ObjectOwner {
    [CmdletBinding(DefaultParameterSetName='ByDN')]
    param(
        [Parameter(Mandatory=$true, ParameterSetName='ByDN', Position=0)]
        [ValidateNotNullOrEmpty()]
        [string]$DistinguishedName,

        [Parameter(Mandatory=$true, ParameterSetName='ByObject', ValueFromPipeline=$true)]
        [ValidateNotNullOrEmpty()]
        [object]$ADObject,

        [Parameter(Mandatory=$false)]
        [switch]$NonDefaultOnly
    )

    process {
        # Get DN from parameter or object
        $targetDN = if ($PSCmdlet.ParameterSetName -eq 'ByObject') {
            if ($ADObject.distinguishedName) {
                $ADObject.distinguishedName
            } else {
                Write-Log "[Get-ObjectOwner] ADObject has no distinguishedName property"
                return $null
            }
        } else {
            $DistinguishedName
        }

        # Internal helper - caller must ensure LDAP connection exists
        # UNIFIED: Check for LdapConnection (works for both LDAP and LDAPS)
        if (-not $Script:LdapConnection) {
            Write-Log "[Get-ObjectOwner] No LDAP connection - returning null"
            return $null
        }

        Write-Log "[Get-ObjectOwner] Querying owner for: $targetDN"

        try {
            # Use Invoke-LDAPSearch with Base scope to query the specific object, this ensures we use the central LDAP access mechanism
            $result = Invoke-LDAPSearch -Filter "(objectClass=*)" -SearchBase $targetDN -Scope Base -Properties @("nTSecurityDescriptor")

            if (-not $result) {
                Write-Log "[Get-ObjectOwner] Object not found: $targetDN"
                return $null
            }

            # Get first result (Base scope returns single object)
            $objectResult = if ($result -is [array]) { $result[0] } else { $result }

            # nTSecurityDescriptor is now a unified object with Owner property
            # Owner has: SID, Name, DisplayText
            if (-not $objectResult.nTSecurityDescriptor -or -not $objectResult.nTSecurityDescriptor.Owner) {
                Write-Log "[Get-ObjectOwner] Could not retrieve owner information from nTSecurityDescriptor"
                return $null
            }

            $ownerSID = $objectResult.nTSecurityDescriptor.Owner.SID
            $ownerName = $objectResult.nTSecurityDescriptor.Owner.Name

            Write-Log "[Get-ObjectOwner] Owner SID: $ownerSID"

            # Determine if this is a default owner using Test-IsDefaultOwner
            $isDefault = Test-IsDefaultOwner -SID $ownerSID

            Write-Log "[Get-ObjectOwner] Owner: $ownerName (IsDefault: $isDefault)"

            # If NonDefaultOnly is set and this is a default owner, return nothing
            if ($NonDefaultOnly -and $isDefault) {
                Write-Log "[Get-ObjectOwner] Skipping default owner (NonDefaultOnly filter)"
                return $null
            }

            # Return result object
            return [PSCustomObject]@{
                OwnerSID          = $ownerSID
                OwnerName         = $ownerName
                IsDefaultOwner    = $isDefault
                DistinguishedName = $targetDN
            }

        } catch {
            Write-Log "[Get-ObjectOwner] Error querying owner: $_"
            return $null
        }
    }
}

<#
.SYNOPSIS
    Tests if a SID is a default/expected owner for AD objects.

.DESCRIPTION
    Checks if the given SID is one of the expected default owners:
    - Domain Admins (-512)
    - Enterprise Admins (-519)
    - BUILTIN\Administrators (S-1-5-32-544)
    - NT AUTHORITY\SYSTEM (S-1-5-18)

.PARAMETER SID
    The SID to check.

.PARAMETER DomainSID
    The domain SID (optional - uses $Script:LDAPContext.DomainSID if not provided).

.EXAMPLE
    Test-IsDefaultOwner -SID "S-1-5-21-123456789-123456789-123456789-512"
    Returns: $true (Domain Admins)

.EXAMPLE
    Test-IsDefaultOwner -SID "S-1-5-21-123456789-123456789-123456789-1234"
    Returns: $false (regular user)

.OUTPUTS
    Boolean - $true if default owner, $false otherwise
#>
function Test-IsDefaultOwner {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$SID,

        [Parameter(Mandatory=$false)]
        [string]$DomainSID  # Kept for backward compatibility, no longer used
    )

    # Check static SIDs first
    if ($Script:DefaultOwnerStaticSIDs -contains $SID) {
        return $true
    }

    # Check domain-relative RID suffixes
    # Use pattern matching (S-1-5-21-*-512) to support multi-domain environments
    # where the owner may be Domain Admins/Enterprise Admins from ANY domain
    # (e.g. child domain objects owned by child domain's DA)
    foreach ($ridSuffix in $Script:DefaultOwnerRIDSuffixes) {
        if ($SID -like "S-1-5-21-*$ridSuffix") {
            return $true
        }
    }

    return $false
}



# ----- ConvertFrom-GPPPassword.ps1 -----

<#
.SYNOPSIS
    Decrypts Group Policy Preferences (GPP) passwords using the published AES key.

.DESCRIPTION
    Microsoft published the AES-256 key used for cpassword encryption in MS14-025 (CVE-2014-1812).
    This function decrypts GPP passwords using that known key.

    GPP passwords were stored encrypted in XML files:
    - Groups.xml (local group memberships)
    - Services.xml (Windows services)
    - ScheduledTasks.xml (scheduled tasks)
    - DataSources.xml (ODBC data sources)
    - Printers.xml (printer mappings)
    - Drives.xml (network drive mappings)

.PARAMETER EncryptedPassword
    The cpassword value from GPP XML files (Base64-encoded AES-encrypted string).

.EXAMPLE
    ConvertFrom-GPPPassword -EncryptedPassword "j1Uyj3Vx8TY9LtLZil2uAuZkFQA/4latT76ZwgdHdhw"
    Returns: P@ssw0rd123

.EXAMPLE
    # From XML parsing
    [xml]$xml = Get-Content "Groups.xml"
    $cpassword = $xml.Groups.User.Properties.cpassword
    $plaintext = ConvertFrom-GPPPassword -EncryptedPassword $cpassword

.OUTPUTS
    String - Decrypted plaintext password

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function ConvertFrom-GPPPassword {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, ValueFromPipeline=$true)]
        [ValidateNotNullOrEmpty()]
        [string]$EncryptedPassword
    )

    begin {
        Write-Log "[ConvertFrom-GPPPassword] Starting GPP password decryption"
    }

    process {
        try {
            # Validate input - must contain only Base64 characters
            if ($EncryptedPassword -notmatch '^[A-Za-z0-9+/=]+$') {
                Write-Log "[ConvertFrom-GPPPassword] Invalid Base64 format: $EncryptedPassword"
                return "[Invalid Format]"
            }

            # Fix Base64 padding (cpassword often lacks proper padding)
            $paddedPassword = $EncryptedPassword
            $mod = $paddedPassword.Length % 4
            switch ($mod) {
                1 { $paddedPassword = $paddedPassword.Substring(0, $paddedPassword.Length - 1) }
                2 { $paddedPassword += '==' }
                3 { $paddedPassword += '=' }
            }

            Write-Log "[ConvertFrom-GPPPassword] Original: $EncryptedPassword, Padded: $paddedPassword"

            # Microsoft's published AES-256 key (MS14-025), This key was intentionally published by Microsoft to deprecate GPP passwords
            $aesKeyBytes = @(
                0x4e,0x99,0x06,0xe8,0xfc,0xb6,0x6c,0xc9,
                0xfa,0xf4,0x93,0x10,0x62,0x0f,0xfe,0xe8,
                0xf4,0x96,0xe8,0x06,0xcc,0x05,0x79,0x90,
                0x20,0x9b,0x09,0xa4,0x33,0xb6,0x6c,0x1b
            )

            Write-Log "[ConvertFrom-GPPPassword] Decoding Base64: $paddedPassword"

            # Decode Base64 to encrypted bytes
            $encryptedBytes = [System.Convert]::FromBase64String($paddedPassword)

            Write-Log "[ConvertFrom-GPPPassword] Encrypted data length: $($encryptedBytes.Length) bytes"

            # Validate encrypted data length (should be multiple of 16 for AES)
            if ($encryptedBytes.Length -eq 0 -or ($encryptedBytes.Length % 16) -ne 0) {
                Write-Log "[ConvertFrom-GPPPassword] Invalid encrypted data length: $($encryptedBytes.Length)"
                return "[Invalid Data Length]"
            }

            # Create AES decryptor
            $aes = New-Object System.Security.Cryptography.AesCryptoServiceProvider
            $aes.Key = $aesKeyBytes
            $aes.IV = New-Object Byte[] 16  # IV is all zeros for GPP
            $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
            $aes.Padding = [System.Security.Cryptography.PaddingMode]::Zeros

            # Decrypt
            $decryptor = $aes.CreateDecryptor()
            $decryptedBytes = $decryptor.TransformFinalBlock($encryptedBytes, 0, $encryptedBytes.Length)

            # Convert to Unicode string and trim padding
            $decryptedPassword = [System.Text.Encoding]::Unicode.GetString($decryptedBytes)

            # Remove AES padding artifacts (null bytes and any trailing non-printable chars)
            # GPP passwords are ASCII-safe, so we can safely trim anything non-printable
            # This handles: null bytes (0x00), and padding remnants like U+0C0C, U+0202, U+0E0E
            $cleanPassword = ""
            foreach ($char in $decryptedPassword.ToCharArray()) {
                $code = [int]$char
                # Keep only printable ASCII range (space to tilde) and common extended chars
                if ($code -ge 32 -and $code -le 126) {
                    $cleanPassword += $char
                }
                elseif ($code -ge 128 -and $code -le 255) {
                    # Extended ASCII (accented chars, etc.) - keep these too
                    $cleanPassword += $char
                }
                elseif ($code -eq 0) {
                    # Null byte - stop here (rest is padding)
                    break
                }
                # Skip other control chars and Unicode oddities (padding artifacts)
            }
            $decryptedPassword = $cleanPassword

            # Cleanup
            $decryptor.Dispose()
            $aes.Dispose()

            Write-Log "[ConvertFrom-GPPPassword] Decryption successful"

            return $decryptedPassword

        } catch [System.FormatException] {
            Write-Log "[ConvertFrom-GPPPassword] Base64 decode error: $_"
            return "[Base64 Decode Failed]"

        } catch [System.Security.Cryptography.CryptographicException] {
            Write-Log "[ConvertFrom-GPPPassword] Decryption error: $_"
            return "[Decryption Failed]"

        } catch {
            Write-Log "[ConvertFrom-GPPPassword] Unexpected error: $_"
            return "[Decryption Failed]"
        }
    }

    end {
        Write-Log "[ConvertFrom-GPPPassword] Decryption completed"
    }
}



# ----- ConvertFrom-VBE.ps1 -----

<#
.SYNOPSIS
    Decodes VBScript Encoded (.vbe) files.

.DESCRIPTION
    VBScript.Encode (screnc.exe) creates "encoded" scripts that are obfuscated but NOT encrypted.
    This function reverses the encoding using the known character substitution table and escape sequence handling.

    VBE encoding is a simple obfuscation technique used to hide VBScript source code.
    The algorithm was reverse-engineered and published by multiple security researchers.

    VBE Format: #@~^XXXXXX==<encoded_data>YYYYYY==^#~@
    Where XXXXXX and YYYYYY are 6-character checksums

    Escape Sequences (processed during decoding):
    - @& -> newline (chr(10))
    - @# -> carriage return (chr(13))
    - @* -> >
    - @! -> <
    - @$ -> @

.PARAMETER EncodedScript
    The content of a .vbe file (VBScript Encoded).

.EXAMPLE
    $vbeContent = Get-Content "script.vbe" -Raw
    ConvertFrom-VBE -EncodedScript $vbeContent

.EXAMPLE
    ConvertFrom-VBE -EncodedScript '#@~^DgAAAA==\ko$K6,JCV^GJqAQAAA==^#~@'
    # Returns: MsgBox "Hello"

.OUTPUTS
    String - Decoded VBScript source code

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Algorithm based on Didier Stevens' decode-vbe.py
    Reference: https://blog.didierstevens.com/2016/03/29/decoding-vbe/
#>

function ConvertFrom-VBE {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, ValueFromPipeline=$true)]
        [ValidateNotNullOrEmpty()]
        [string]$EncodedScript
    )

    begin {
        Write-Log "[ConvertFrom-VBE] Starting VBE decoding"

        # VBE decode table - 128 entries indexed DIRECTLY by byte value
        # Each entry contains 3 chars, selected by VBECombination[index % 64]
        $script:VBEDecodings = @(
            [char[]]@(0x00, 0x00, 0x00),  # 0
            [char[]]@(0x01, 0x01, 0x01),  # 1
            [char[]]@(0x02, 0x02, 0x02),  # 2
            [char[]]@(0x03, 0x03, 0x03),  # 3
            [char[]]@(0x04, 0x04, 0x04),  # 4
            [char[]]@(0x05, 0x05, 0x05),  # 5
            [char[]]@(0x06, 0x06, 0x06),  # 6
            [char[]]@(0x07, 0x07, 0x07),  # 7
            [char[]]@(0x08, 0x08, 0x08),  # 8
            [char[]]@(0x57, 0x6E, 0x7B),  # 9  (TAB)
            [char[]]@(0x4A, 0x4C, 0x41),  # 10 (LF)
            [char[]]@(0x0B, 0x0B, 0x0B),  # 11
            [char[]]@(0x0C, 0x0C, 0x0C),  # 12
            [char[]]@(0x4A, 0x4C, 0x41),  # 13 (CR)
            [char[]]@(0x0E, 0x0E, 0x0E),  # 14
            [char[]]@(0x0F, 0x0F, 0x0F),  # 15
            [char[]]@(0x10, 0x10, 0x10),  # 16
            [char[]]@(0x11, 0x11, 0x11),  # 17
            [char[]]@(0x12, 0x12, 0x12),  # 18
            [char[]]@(0x13, 0x13, 0x13),  # 19
            [char[]]@(0x14, 0x14, 0x14),  # 20
            [char[]]@(0x15, 0x15, 0x15),  # 21
            [char[]]@(0x16, 0x16, 0x16),  # 22
            [char[]]@(0x17, 0x17, 0x17),  # 23
            [char[]]@(0x18, 0x18, 0x18),  # 24
            [char[]]@(0x19, 0x19, 0x19),  # 25
            [char[]]@(0x1A, 0x1A, 0x1A),  # 26
            [char[]]@(0x1B, 0x1B, 0x1B),  # 27
            [char[]]@(0x1C, 0x1C, 0x1C),  # 28
            [char[]]@(0x1D, 0x1D, 0x1D),  # 29
            [char[]]@(0x1E, 0x1E, 0x1E),  # 30
            [char[]]@(0x1F, 0x1F, 0x1F),  # 31
            [char[]]@(0x2E, 0x2D, 0x32),  # 32 (space)
            [char[]]@(0x47, 0x75, 0x30),  # 33 !
            [char[]]@(0x7A, 0x52, 0x21),  # 34 "
            [char[]]@(0x56, 0x60, 0x29),  # 35 #
            [char[]]@(0x42, 0x71, 0x5B),  # 36 $
            [char[]]@(0x6A, 0x5E, 0x38),  # 37 %
            [char[]]@(0x2F, 0x49, 0x33),  # 38 &
            [char[]]@(0x26, 0x5C, 0x3D),  # 39 '
            [char[]]@(0x49, 0x62, 0x58),  # 40 (
            [char[]]@(0x41, 0x7D, 0x3A),  # 41 )
            [char[]]@(0x34, 0x29, 0x35),  # 42 *
            [char[]]@(0x32, 0x36, 0x65),  # 43 +
            [char[]]@(0x5B, 0x20, 0x39),  # 44 ,
            [char[]]@(0x76, 0x7C, 0x5C),  # 45 -
            [char[]]@(0x72, 0x7A, 0x56),  # 46 .
            [char[]]@(0x43, 0x7F, 0x73),  # 47 /
            [char[]]@(0x38, 0x6B, 0x66),  # 48 0
            [char[]]@(0x39, 0x63, 0x4E),  # 49 1
            [char[]]@(0x70, 0x33, 0x45),  # 50 2
            [char[]]@(0x45, 0x2B, 0x6B),  # 51 3
            [char[]]@(0x68, 0x68, 0x62),  # 52 4
            [char[]]@(0x71, 0x51, 0x59),  # 53 5
            [char[]]@(0x4F, 0x66, 0x78),  # 54 6
            [char[]]@(0x09, 0x76, 0x5E),  # 55 7
            [char[]]@(0x62, 0x31, 0x7D),  # 56 8
            [char[]]@(0x44, 0x64, 0x4A),  # 57 9
            [char[]]@(0x23, 0x54, 0x6D),  # 58 :
            [char[]]@(0x75, 0x43, 0x71),  # 59 ;
            [char[]]@(0x4A, 0x4C, 0x41),  # 60 < (special)
            [char[]]@(0x7E, 0x3A, 0x60),  # 61 =
            [char[]]@(0x4A, 0x4C, 0x41),  # 62 > (special)
            [char[]]@(0x5E, 0x7E, 0x53),  # 63 ?
            [char[]]@(0x40, 0x4C, 0x40),  # 64 @ (special)
            [char[]]@(0x77, 0x45, 0x42),  # 65 A
            [char[]]@(0x4A, 0x2C, 0x27),  # 66 B
            [char[]]@(0x61, 0x2A, 0x48),  # 67 C
            [char[]]@(0x5D, 0x74, 0x72),  # 68 D
            [char[]]@(0x22, 0x27, 0x75),  # 69 E
            [char[]]@(0x4B, 0x37, 0x31),  # 70 F
            [char[]]@(0x6F, 0x44, 0x37),  # 71 G
            [char[]]@(0x4E, 0x79, 0x4D),  # 72 H
            [char[]]@(0x3B, 0x59, 0x52),  # 73 I
            [char[]]@(0x4C, 0x2F, 0x22),  # 74 J
            [char[]]@(0x50, 0x6F, 0x54),  # 75 K
            [char[]]@(0x67, 0x26, 0x6A),  # 76 L
            [char[]]@(0x2A, 0x72, 0x47),  # 77 M
            [char[]]@(0x7D, 0x6A, 0x64),  # 78 N
            [char[]]@(0x74, 0x39, 0x2D),  # 79 O
            [char[]]@(0x54, 0x7B, 0x20),  # 80 P
            [char[]]@(0x2B, 0x3F, 0x7F),  # 81 Q
            [char[]]@(0x2D, 0x38, 0x2E),  # 82 R
            [char[]]@(0x2C, 0x77, 0x4C),  # 83 S
            [char[]]@(0x30, 0x67, 0x5D),  # 84 T
            [char[]]@(0x6E, 0x53, 0x7E),  # 85 U
            [char[]]@(0x6B, 0x47, 0x6C),  # 86 V
            [char[]]@(0x66, 0x34, 0x6F),  # 87 W
            [char[]]@(0x35, 0x78, 0x79),  # 88 X
            [char[]]@(0x25, 0x5D, 0x74),  # 89 Y
            [char[]]@(0x21, 0x30, 0x43),  # 90 Z
            [char[]]@(0x64, 0x23, 0x26),  # 91 [
            [char[]]@(0x4D, 0x5A, 0x76),  # 92 \
            [char[]]@(0x52, 0x5B, 0x25),  # 93 ]
            [char[]]@(0x63, 0x6C, 0x24),  # 94 ^
            [char[]]@(0x3F, 0x48, 0x2B),  # 95 _
            [char[]]@(0x7B, 0x55, 0x28),  # 96 `
            [char[]]@(0x78, 0x70, 0x23),  # 97 a
            [char[]]@(0x29, 0x69, 0x41),  # 98 b
            [char[]]@(0x28, 0x2E, 0x34),  # 99 c
            [char[]]@(0x73, 0x4C, 0x09),  # 100 d
            [char[]]@(0x59, 0x21, 0x2A),  # 101 e
            [char[]]@(0x33, 0x24, 0x44),  # 102 f
            [char[]]@(0x7F, 0x4E, 0x3F),  # 103 g
            [char[]]@(0x6D, 0x50, 0x77),  # 104 h
            [char[]]@(0x55, 0x09, 0x3B),  # 105 i
            [char[]]@(0x53, 0x56, 0x55),  # 106 j
            [char[]]@(0x7C, 0x73, 0x69),  # 107 k
            [char[]]@(0x3A, 0x35, 0x61),  # 108 l
            [char[]]@(0x5F, 0x61, 0x63),  # 109 m
            [char[]]@(0x65, 0x4B, 0x50),  # 110 n
            [char[]]@(0x46, 0x58, 0x67),  # 111 o
            [char[]]@(0x58, 0x3B, 0x51),  # 112 p
            [char[]]@(0x31, 0x57, 0x49),  # 113 q
            [char[]]@(0x69, 0x22, 0x4F),  # 114 r
            [char[]]@(0x6C, 0x6D, 0x46),  # 115 s
            [char[]]@(0x5A, 0x4D, 0x68),  # 116 t
            [char[]]@(0x48, 0x25, 0x7C),  # 117 u
            [char[]]@(0x27, 0x28, 0x36),  # 118 v
            [char[]]@(0x5C, 0x46, 0x70),  # 119 w
            [char[]]@(0x3D, 0x4A, 0x6E),  # 120 x
            [char[]]@(0x24, 0x32, 0x7A),  # 121 y
            [char[]]@(0x79, 0x41, 0x2F),  # 122 z
            [char[]]@(0x37, 0x3D, 0x5F),  # 123 {
            [char[]]@(0x60, 0x5F, 0x4B),  # 124 |
            [char[]]@(0x51, 0x4F, 0x5A),  # 125 }
            [char[]]@(0x20, 0x42, 0x2C),  # 126 ~
            [char[]]@(0x36, 0x65, 0x57)   # 127
        )

        # Combination table - determines which of the 3 decoded chars to use
        # Index into this table is (position % 64)
        $script:VBECombination = @(
            0, 1, 2, 0, 1, 2, 1, 2, 2, 1, 2, 1, 0, 2, 1, 2,
            0, 2, 1, 2, 0, 0, 1, 2, 2, 1, 0, 2, 1, 2, 2, 1,
            0, 0, 2, 1, 2, 1, 2, 0, 2, 0, 0, 1, 2, 0, 2, 1,
            0, 2, 1, 2, 0, 0, 1, 2, 2, 0, 0, 1, 2, 0, 2, 1
        )

        # Bad bytes that should not be decoded (passed through as-is)
        $script:VBEBadBytes = @(60, 62, 64)  # < > @
    }

    process {
        try {
            # Check for VBE marker format
            # Format: #@~^XXXXXX==<encoded_data>YYYYYY==^#~@
            # Where XXXXXX and YYYYYY are 6-character checksums (any characters)
            if ($EncodedScript -match '#@~\^.{6}==(.+).{6}==\^#~@') {
                $encodedData = $Matches[1]

                Write-Log "[ConvertFrom-VBE] Found VBE block, encoded data length: $($encodedData.Length)"

                if ([string]::IsNullOrEmpty($encodedData)) {
                    Write-Log "[ConvertFrom-VBE] Empty encoded data"
                    return ""
                }

                # Process escape sequences first (like Python version does inline)
                $processedData = $encodedData
                $processedData = $processedData -replace '@&', "`n"    # Line feed (chr(10))
                $processedData = $processedData -replace '@#', "`r"    # Carriage return (chr(13))
                $processedData = $processedData -replace '@\*', '>'    # Greater than
                $processedData = $processedData -replace '@!', '<'     # Less than
                $processedData = $processedData -replace '@\$', '@'    # At sign

                Write-Log "[ConvertFrom-VBE] After escape processing: $($processedData.Length) characters"

                # Decode using substitution table with combination cycling
                $decoded = New-Object System.Text.StringBuilder
                $index = -1

                foreach ($char in $processedData.ToCharArray()) {
                    $byteValue = [int][char]$char

                    # Only increment index for bytes < 128 (VBE_PERM_TRIPLET_SIZE)
                    if ($byteValue -lt 128) {
                        $index++
                    }

                    # Check if this byte should be decoded:
                    # (byte == 9 or (byte > 31 and byte < 128)) and byte not in bad_bytes
                    if (($byteValue -eq 9 -or ($byteValue -gt 31 -and $byteValue -lt 128)) -and
                        $byteValue -notin $script:VBEBadBytes) {

                        # Direct index into table (no offset subtraction)
                        # Table has 128 entries, index = byte value
                        if ($byteValue -lt $script:VBEDecodings.Count) {
                            $triplet = $script:VBEDecodings[$byteValue]
                            $combinationIndex = $script:VBECombination[$index % 64]
                            $decodedChar = $triplet[$combinationIndex]
                            [void]$decoded.Append($decodedChar)
                        } else {
                            # Out of range - pass through
                            [void]$decoded.Append($char)
                        }
                    } else {
                        # Special characters (< > @) or control chars - pass through
                        [void]$decoded.Append($char)
                    }
                }

                $decodedScript = $decoded.ToString()
                Write-Log "[ConvertFrom-VBE] Decoding successful, decoded length: $($decodedScript.Length) characters"

                return $decodedScript

            } else {
                Write-Log "[ConvertFrom-VBE] Not a valid VBE encoded script (missing #@~^ markers)"
                # Not VBE encoded - return as-is (might be plain VBS in .vbe extension)
                return $EncodedScript
            }

        } catch {
            Write-Log "[ConvertFrom-VBE] Decoding failed: $_"
            return "[VBE Decoding Failed: $_]"
        }
    }

    end {
        Write-Log "[ConvertFrom-VBE] VBE decoding completed"
    }
}



# ----- ConvertFrom-Base64OrFile.ps1 -----

<#
.SYNOPSIS
    Converts a Base64 string or reads a file path to byte array.

.DESCRIPTION
    This helper function handles input that can be either:
    1. A Base64-encoded string (standard or URL-safe)
    2. A file path to read

    Logic:
    1. First attempts to decode as Base64 (both standard and URL-safe)
    2. Validates decoded bytes match expected format (optional)
    3. If Base64 decoding fails or produces invalid format, treats input as file path

.PARAMETER InputValue
    The input string - either Base64-encoded data or a file path.

.PARAMETER ExpectedFormat
    Optional. The expected format of the decoded data:
    - "Kirbi" - KRB-CRED format (starts with 0x76) or raw Ticket (0x61)
    - "Ccache" - MIT Kerberos ccache format (starts with 0x0501-0x0504)
    - "Certificate" - PFX/PKCS12 format (starts with 0x30) or PEM (starts with "-----")
    - "Any" - Accept any valid Base64 (default)

.PARAMETER ParameterName
    Optional. The name of the parameter for error messages.

.OUTPUTS
    PSCustomObject with:
    - Success: Boolean indicating success
    - Data: Byte array of the decoded/read data
    - Source: "Base64" or "File"
    - Format: Detected format
    - Error: Error message if failed

.EXAMPLE
    $result = ConvertFrom-Base64OrFile -InputValue "YII..." -ExpectedFormat "Kirbi"
    if ($result.Success) {
        $ticketBytes = $result.Data
    }

.EXAMPLE
    $result = ConvertFrom-Base64OrFile -InputValue "C:\tickets\admin.kirbi" -ExpectedFormat "Kirbi"
    if ($result.Success) {
        $ticketBytes = $result.Data
    }

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function ConvertFrom-Base64OrFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$InputValue,

        [Parameter(Mandatory = $false)]
        [ValidateSet("Kirbi", "Ccache", "Certificate", "Any")]
        [string]$ExpectedFormat = "Any",

        [Parameter(Mandatory = $false)]
        [string]$ParameterName = "Input"
    )

    process {
        $result = [PSCustomObject]@{
            Success = $false
            Data    = $null
            Source  = $null
            Format  = $null
            Error   = $null
        }

        # Empty or null check
        if ([string]::IsNullOrWhiteSpace($InputValue)) {
            $result.Error = "$ParameterName cannot be empty"
            return $result
        }

        Write-Log "[ConvertFrom-Base64OrFile] Processing $ParameterName (length: $($InputValue.Length) chars)"

        #Try Base64 decoding first
        $decodedBytes = $null
        $isValidBase64 = $false

        try {
            # Normalize the input - handle URL-safe Base64
            $base64String = $InputValue.Trim()

            # Replace URL-safe characters with standard Base64 characters
            $base64String = $base64String -replace '-', '+' -replace '_', '/'

            # Add padding if necessary
            $paddingNeeded = $base64String.Length % 4
            if ($paddingNeeded -gt 0) {
                $base64String += ('=' * (4 - $paddingNeeded))
            }

            # Check if it looks like Base64 (only valid Base64 characters), also reject strings that look like file paths
            $isPathLike = $base64String -match '^[A-Za-z]:\\' -or        # Windows absolute path
                          $base64String -match '^\\\\' -or                 # UNC path
                          $base64String -match '^\.\.?[/\\]' -or           # Relative path
                          $base64String -match '^[/~]' -or                 # Unix path
                          $base64String -match '\.[a-zA-Z0-9]{2,5}$' -and  # File extension
                          $base64String.Length -lt 100                      # Short string with extension

            if ($isPathLike) {
                Write-Log "[ConvertFrom-Base64OrFile] Input looks like a file path, skipping Base64 decoding"
            }
            else {
                # Check for valid Base64 characters
                $base64Pattern = '^[A-Za-z0-9+/=]+$'
                if ($base64String -match $base64Pattern -and $base64String.Length -ge 4) {

                    # Try to decode
                    $decodedBytes = [Convert]::FromBase64String($base64String)

                    if ($decodedBytes.Length -gt 0) {
                        Write-Log "[ConvertFrom-Base64OrFile] Base64 decoded to $($decodedBytes.Length) bytes"

                        # Validate against expected format
                        $formatValid = $false
                        $detectedFormat = "Unknown"

                        switch ($ExpectedFormat) {
                            "Kirbi" {
                                # KRB-CRED starts with APPLICATION 22 (0x76)
                                # Raw Ticket starts with APPLICATION 1 (0x61)
                                if ($decodedBytes[0] -eq 0x76) {
                                    $formatValid = $true
                                    $detectedFormat = "KRB-CRED"
                                }
                                elseif ($decodedBytes[0] -eq 0x61) {
                                    $formatValid = $true
                                    $detectedFormat = "RawTicket"
                                }
                                else {
                                    Write-Log "[ConvertFrom-Base64OrFile] Kirbi format check failed: first byte is 0x$($decodedBytes[0].ToString('X2')), expected 0x76 or 0x61"
                                }
                            }
                            "Ccache" {
                                # Ccache starts with version bytes (0x0501, 0x0502, 0x0503, 0x0504)
                                if ($decodedBytes.Length -ge 2) {
                                    $version = ([uint16]$decodedBytes[0] -shl 8) -bor $decodedBytes[1]
                                    if ($version -ge 0x0501 -and $version -le 0x0504) {
                                        $formatValid = $true
                                        $detectedFormat = "Ccache-v$($version -band 0xFF)"
                                    }
                                    else {
                                        Write-Log "[ConvertFrom-Base64OrFile] Ccache format check failed: version is 0x$($version.ToString('X4')), expected 0x0501-0x0504"
                                    }
                                }
                            }
                            "Certificate" {
                                # PFX/PKCS12 starts with SEQUENCE (0x30)
                                # PEM starts with "-----BEGIN" (but that would be in InputValue, not decoded)
                                if ($decodedBytes[0] -eq 0x30) {
                                    # Additional check: valid ASN.1 length byte
                                    if ($decodedBytes.Length -ge 2) {
                                        $formatValid = $true
                                        $detectedFormat = "PFX/PKCS12"
                                    }
                                }
                                else {
                                    Write-Log "[ConvertFrom-Base64OrFile] Certificate format check failed: first byte is 0x$($decodedBytes[0].ToString('X2')), expected 0x30 (SEQUENCE)"
                                }
                            }
                            "Any" {
                                # Accept any valid decoded bytes
                                $formatValid = $true

                                # Try to detect format
                                if ($decodedBytes[0] -eq 0x76) { $detectedFormat = "KRB-CRED" }
                                elseif ($decodedBytes[0] -eq 0x61) { $detectedFormat = "RawTicket" }
                                elseif ($decodedBytes.Length -ge 2 -and (([uint16]$decodedBytes[0] -shl 8) -bor $decodedBytes[1]) -ge 0x0501 -and (([uint16]$decodedBytes[0] -shl 8) -bor $decodedBytes[1]) -le 0x0504) { $detectedFormat = "Ccache" }
                                elseif ($decodedBytes[0] -eq 0x30) { $detectedFormat = "ASN.1" }
                                else { $detectedFormat = "Binary" }
                            }
                        }

                        if ($formatValid) {
                            $isValidBase64 = $true
                            Write-Log "[ConvertFrom-Base64OrFile] Valid $ExpectedFormat format detected: $detectedFormat"

                            $result.Success = $true
                            $result.Data = $decodedBytes
                            $result.Source = "Base64"
                            $result.Format = $detectedFormat
                            return $result
                        }
                        else {
                            Write-Log "[ConvertFrom-Base64OrFile] Base64 decoded but format doesn't match expected: $ExpectedFormat"
                            # Clear decoded bytes - will try as file path
                            $decodedBytes = $null
                        }
                    }
                }
                else {
                    Write-Log "[ConvertFrom-Base64OrFile] Input doesn't look like Base64"
                }
            }
        }
        catch {
            Write-Log "[ConvertFrom-Base64OrFile] Base64 decoding failed: $_"
            $decodedBytes = $null
        }

        # Try as file path

        Write-Log "[ConvertFrom-Base64OrFile] Trying as file path: $InputValue"

        # Check if file exists
        if (Test-Path -Path $InputValue -PathType Leaf) {
            try {
                # Resolve to a full filesystem path before handing it to .NET:
                # [IO.File]::ReadAllBytes uses Environment.CurrentDirectory, not PowerShell's $PWD,
                # so relative paths like ".\cert.pfx" would otherwise resolve against the wrong directory.
                $resolvedPath = (Resolve-Path -LiteralPath $InputValue -ErrorAction Stop).ProviderPath
                $fileBytes = [System.IO.File]::ReadAllBytes($resolvedPath)

                if ($fileBytes.Length -eq 0) {
                    $result.Error = "File is empty: $InputValue"
                    return $result
                }

                Write-Log "[ConvertFrom-Base64OrFile] Read $($fileBytes.Length) bytes from file"

                # Validate format for files too
                $detectedFormat = "Unknown"
                $formatValid = $false

                switch ($ExpectedFormat) {
                    "Kirbi" {
                        if ($fileBytes[0] -eq 0x76) {
                            $formatValid = $true
                            $detectedFormat = "KRB-CRED"
                        }
                        elseif ($fileBytes[0] -eq 0x61) {
                            $formatValid = $true
                            $detectedFormat = "RawTicket"
                        }
                        else {
                            $result.Error = "Invalid Kirbi file format. Expected KRB-CRED (0x76) or Ticket (0x61), got 0x$($fileBytes[0].ToString('X2'))"
                            return $result
                        }
                    }
                    "Ccache" {
                        if ($fileBytes.Length -ge 2) {
                            $version = ([uint16]$fileBytes[0] -shl 8) -bor $fileBytes[1]
                            if ($version -ge 0x0501 -and $version -le 0x0504) {
                                $formatValid = $true
                                $detectedFormat = "Ccache-v$($version -band 0xFF)"
                            }
                            else {
                                $result.Error = "Invalid Ccache file format. Expected version 0x0501-0x0504, got 0x$($version.ToString('X4'))"
                                return $result
                            }
                        }
                        else {
                            $result.Error = "Ccache file too small"
                            return $result
                        }
                    }
                    "Certificate" {
                        if ($fileBytes[0] -eq 0x30) {
                            $formatValid = $true
                            $detectedFormat = "PFX/PKCS12"
                        }
                        elseif ($fileBytes.Length -ge 10) {
                            $header = [System.Text.Encoding]::ASCII.GetString($fileBytes, 0, [Math]::Min(11, $fileBytes.Length))
                            if ($header.StartsWith("-----BEGIN")) {
                                $formatValid = $true
                                $detectedFormat = "PEM"
                            }
                        }

                        if (-not $formatValid) {
                            $result.Error = "Invalid certificate file format. Expected PFX/PKCS12 (0x30) or PEM"
                            return $result
                        }
                    }
                    "Any" {
                        $formatValid = $true
                        # Try to detect format
                        if ($fileBytes[0] -eq 0x76) { $detectedFormat = "KRB-CRED" }
                        elseif ($fileBytes[0] -eq 0x61) { $detectedFormat = "RawTicket" }
                        elseif ($fileBytes.Length -ge 2 -and (([uint16]$fileBytes[0] -shl 8) -bor $fileBytes[1]) -ge 0x0501 -and (([uint16]$fileBytes[0] -shl 8) -bor $fileBytes[1]) -le 0x0504) { $detectedFormat = "Ccache" }
                        elseif ($fileBytes[0] -eq 0x30) { $detectedFormat = "ASN.1" }
                        else { $detectedFormat = "Binary" }
                    }
                }

                $result.Success = $true
                $result.Data = $fileBytes
                $result.Source = "File"
                $result.Format = $detectedFormat
                return $result
            }
            catch {
                $result.Error = "Failed to read file '$InputValue': $_"
                return $result
            }
        }
        else {
            if ($isValidBase64 -eq $false -and $null -eq $decodedBytes) {
                $result.Error = "Input is neither a valid Base64 string nor an existing file path: $InputValue"
            }
            else {
                $result.Error = "File not found: $InputValue"
            }
            return $result
        }
    }
}



# ----- ConvertFrom-ManagedPassword.ps1 -----

function ConvertFrom-ManagedPassword {
    <#
    .SYNOPSIS
    Parses the msDS-ManagedPassword attribute blob from a Group Managed Service Account (gMSA).

    .DESCRIPTION
    Decodes the MSDS-MANAGEDPASSWORD_BLOB structure returned by Active Directory when
    reading the msDS-ManagedPassword constructed attribute from a gMSA.

    The structure contains:
    - Current password (UTF-16LE null-terminated string, up to 256 random characters)
    - Previous password (optional, for password rollover)
    - Query password interval (when to re-query)
    - Unchanged password interval (password validity period)

    This function returns the passwords in multiple formats:
    - SecureString (for secure operations)
    - Plaintext (for display/export)
    - NT Hash (for authentication)

    Security Note:
    gMSA passwords are 256 random Unicode characters and cannot be typed manually.
    They are designed for programmatic use only.

    .PARAMETER Blob
    The raw byte array from the msDS-ManagedPassword attribute.

    .PARAMETER AsSecureString
    If specified, returns passwords as SecureString instead of plaintext.

    .EXAMPLE
    $gmsa = Get-DomainUser -GMSA -Identity "svc_gmsa$" -Properties msDS-ManagedPassword
    $password = ConvertFrom-ManagedPassword -Blob $gmsa.'msDS-ManagedPassword'
    $password.CurrentPassword

    .EXAMPLE
    # Get NT hash for authentication
    $gmsa = Get-DomainUser -GMSA -Identity "svc_gmsa$" -Properties msDS-ManagedPassword
    $password = ConvertFrom-ManagedPassword -Blob $gmsa.'msDS-ManagedPassword'
    $password.CurrentNTHash  # Returns hex string like "32ED87BDB5FDC5E9CBA88547376818D4"

    .NOTES
    References:
    - MS-ADTS 2.2.5.4: MSDS-MANAGEDPASSWORD_BLOB
    - https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/a9019740-3d73-46ef-a9ae-3ea8eb86ac2e

    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [byte[]]$Blob,

        [Parameter(Mandatory = $false)]
        [switch]$AsSecureString
    )

    begin {
        # Structure header size: Version(2) + Reserved(2) + Length(4) + CurrentPwdOffset(2) +
        #                        PreviousPwdOffset(2) + QueryPwdIntervalOffset(2) + UnchangedPwdIntervalOffset(2) = 16 bytes
        $HeaderSize = 16
    }

    process {
        try {
            # Validate input
            if ($null -eq $Blob) {
                Write-Log "[ConvertFrom-ManagedPassword] Blob is null"
                return $null
            }

            if ($Blob.Length -lt $HeaderSize) {
                Write-Log "[ConvertFrom-ManagedPassword] Blob too short (min $HeaderSize bytes required, got $($Blob.Length))"
                return $null
            }

            # Parse header using BinaryReader
            $stream = New-Object System.IO.MemoryStream($Blob, $false)
            $reader = New-Object System.IO.BinaryReader($stream)

            try {
                # Version (2 bytes): Must be 0x0001
                $version = $reader.ReadUInt16()
                if ($version -ne 1) {
                    Write-Log "[ConvertFrom-ManagedPassword] Unsupported version: $version (expected 1)"
                    return $null
                }

                # Reserved (2 bytes): Should be 0x0000, but we ignore it per spec
                [void]$reader.ReadUInt16()

                # Length (4 bytes): Total structure length in bytes
                $length = $reader.ReadInt32()
                if ($Blob.Length -lt $length) {
                    Write-Log "[ConvertFrom-ManagedPassword] Blob truncated: got $($Blob.Length) bytes, header says $length"
                    return $null
                }

                # CurrentPasswordOffset (2 bytes): Offset to current password
                $currentPasswordOffset = $reader.ReadUInt16()

                # PreviousPasswordOffset (2 bytes): Offset to previous password (0 if not present)
                $previousPasswordOffset = $reader.ReadUInt16()

                # QueryPasswordIntervalOffset (2 bytes): Offset to query interval
                $queryPasswordIntervalOffset = $reader.ReadUInt16()

                # UnchangedPasswordIntervalOffset (2 bytes): Offset to unchanged interval
                $unchangedPasswordIntervalOffset = $reader.ReadUInt16()

                Write-Log "[ConvertFrom-ManagedPassword] Parsed header - Version: $version, Length: $length, CurrentPwdOffset: $currentPasswordOffset, PrevPwdOffset: $previousPasswordOffset, QueryOffset: $queryPasswordIntervalOffset, UnchangedOffset: $unchangedPasswordIntervalOffset"

                # Validate offsets
                if ($currentPasswordOffset -lt $HeaderSize) {
                    Write-Log "[ConvertFrom-ManagedPassword] Invalid current password offset: $currentPasswordOffset (must be >= $HeaderSize)"
                    return $null
                }

                if ($queryPasswordIntervalOffset -lt $currentPasswordOffset) {
                    Write-Log "[ConvertFrom-ManagedPassword] Invalid offset order: QueryPasswordIntervalOffset ($queryPasswordIntervalOffset) < CurrentPasswordOffset ($currentPasswordOffset)"
                    return $null
                }

                # Validate we have enough bytes for the interval fields (8 bytes each)
                $minRequiredLength = $unchangedPasswordIntervalOffset + 8
                if ($Blob.Length -lt $minRequiredLength) {
                    Write-Log "[ConvertFrom-ManagedPassword] Blob too short for interval fields: need $minRequiredLength bytes, got $($Blob.Length)"
                    return $null
                }

                # Determine password boundaries
                $currentPasswordEnd = if ($previousPasswordOffset -gt 0 -and $previousPasswordOffset -gt $currentPasswordOffset) {
                    $previousPasswordOffset
                } else {
                    $queryPasswordIntervalOffset
                }

                # Validate password region
                if ($currentPasswordEnd -le $currentPasswordOffset) {
                    Write-Log "[ConvertFrom-ManagedPassword] Invalid password region: start=$currentPasswordOffset, end=$currentPasswordEnd"
                    return $null
                }

                # Read current password (null-terminated UTF-16LE string)
                $currentPasswordLength = $currentPasswordEnd - $currentPasswordOffset
                $currentPasswordBytes = New-Object byte[] $currentPasswordLength
                [Array]::Copy($Blob, $currentPasswordOffset, $currentPasswordBytes, 0, $currentPasswordLength)
                $currentPassword = Read-NullTerminatedUnicodeString -Bytes $currentPasswordBytes

                if ([string]::IsNullOrEmpty($currentPassword)) {
                    Write-Log "[ConvertFrom-ManagedPassword] Warning: Current password is empty (this should not happen for gMSA)"
                }

                # Read previous password if present
                $previousPassword = $null
                if ($previousPasswordOffset -gt 0 -and $previousPasswordOffset -gt $currentPasswordOffset -and $previousPasswordOffset -lt $queryPasswordIntervalOffset) {
                    $previousPasswordLength = $queryPasswordIntervalOffset - $previousPasswordOffset
                    $previousPasswordBytes = New-Object byte[] $previousPasswordLength
                    [Array]::Copy($Blob, $previousPasswordOffset, $previousPasswordBytes, 0, $previousPasswordLength)
                    $previousPassword = Read-NullTerminatedUnicodeString -Bytes $previousPasswordBytes
                }

                # Read query password interval (8 bytes, 100-nanosecond intervals as unsigned)
                $queryIntervalBytes = New-Object byte[] 8
                [Array]::Copy($Blob, $queryPasswordIntervalOffset, $queryIntervalBytes, 0, 8)
                $queryIntervalTicks = [BitConverter]::ToInt64($queryIntervalBytes, 0)
                # Note: Spec says unsigned, but TimeSpan.FromTicks takes long. Very large values are unlikely in practice.
                $queryPasswordInterval = [TimeSpan]::FromTicks($queryIntervalTicks)

                # Read unchanged password interval (8 bytes, 100-nanosecond intervals)
                $unchangedIntervalBytes = New-Object byte[] 8
                [Array]::Copy($Blob, $unchangedPasswordIntervalOffset, $unchangedIntervalBytes, 0, 8)
                $unchangedIntervalTicks = [BitConverter]::ToInt64($unchangedIntervalBytes, 0)
                $unchangedPasswordInterval = [TimeSpan]::FromTicks($unchangedIntervalTicks)

                Write-Log "[ConvertFrom-ManagedPassword] Password length: $($currentPassword.Length) chars, QueryInterval: $($queryPasswordInterval.TotalHours) hours"

                # Calculate NT hashes
                $currentNTHash = $null
                $previousNTHash = $null

                if (-not [string]::IsNullOrEmpty($currentPassword)) {
                    $currentNTHash = Get-NTHashFromPassword -Password $currentPassword
                }

                if (-not [string]::IsNullOrEmpty($previousPassword)) {
                    $previousNTHash = Get-NTHashFromPassword -Password $previousPassword
                }

                # Build result object with all properties upfront
                if ($AsSecureString) {
                    # Convert to SecureString
                    $secureCurrentPassword = $null
                    $securePreviousPassword = $null

                    if (-not [string]::IsNullOrEmpty($currentPassword)) {
                        $secureCurrentPassword = New-Object System.Security.SecureString
                        foreach ($char in $currentPassword.ToCharArray()) {
                            $secureCurrentPassword.AppendChar($char)
                        }
                        $secureCurrentPassword.MakeReadOnly()
                    }

                    if (-not [string]::IsNullOrEmpty($previousPassword)) {
                        $securePreviousPassword = New-Object System.Security.SecureString
                        foreach ($char in $previousPassword.ToCharArray()) {
                            $securePreviousPassword.AppendChar($char)
                        }
                        $securePreviousPassword.MakeReadOnly()
                    }

                    return [PSCustomObject]@{
                        Version                   = $version
                        CurrentPassword           = $secureCurrentPassword
                        PreviousPassword          = $securePreviousPassword
                        CurrentNTHash             = $currentNTHash
                        PreviousNTHash            = $previousNTHash
                        QueryPasswordInterval     = $queryPasswordInterval
                        UnchangedPasswordInterval = $unchangedPasswordInterval
                    }
                } else {
                    return [PSCustomObject]@{
                        Version                   = $version
                        CurrentPassword           = $currentPassword
                        PreviousPassword          = $previousPassword
                        CurrentNTHash             = $currentNTHash
                        PreviousNTHash            = $previousNTHash
                        QueryPasswordInterval     = $queryPasswordInterval
                        UnchangedPasswordInterval = $unchangedPasswordInterval
                    }
                }

            } finally {
                if ($reader) { $reader.Dispose() }
                if ($stream) { $stream.Dispose() }
            }

        } catch {
            Write-Log "[ConvertFrom-ManagedPassword] Error parsing blob: $_"
            return $null
        }
    }
}


function Read-NullTerminatedUnicodeString {
    <#
    .SYNOPSIS
    Reads a null-terminated UTF-16LE string from a byte array.
    Internal helper function for ConvertFrom-ManagedPassword.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [byte[]]$Bytes
    )

    if ($null -eq $Bytes -or $Bytes.Length -lt 2) {
        return [string]::Empty
    }

    # Ensure even length for UTF-16LE
    $effectiveLength = $Bytes.Length
    if ($effectiveLength % 2 -ne 0) {
        $effectiveLength = $effectiveLength - 1
    }

    if ($effectiveLength -lt 2) {
        return [string]::Empty
    }

    # Find null terminator (two consecutive zero bytes at even offset)
    $nullIndex = -1
    for ($i = 0; $i -lt $effectiveLength; $i += 2) {
        if ($Bytes[$i] -eq 0 -and $Bytes[$i + 1] -eq 0) {
            $nullIndex = $i
            break
        }
    }

    if ($nullIndex -eq -1) {
        # No null terminator found, use entire effective length
        $nullIndex = $effectiveLength
    }

    if ($nullIndex -eq 0) {
        return [string]::Empty
    }

    # Decode UTF-16LE string (excluding null terminator)
    return [System.Text.Encoding]::Unicode.GetString($Bytes, 0, $nullIndex)
}


function Get-NTHashFromPassword {
    <#
    .SYNOPSIS
    Calculates the NT hash (MD4 of UTF-16LE password) for a given password string.
    Internal helper function for ConvertFrom-ManagedPassword.

    .DESCRIPTION
    Uses the Get-MD4Hash function from Kerberos-Crypto.ps1 to compute the NT hash.
    The NT hash is MD4(UTF-16LE(password)).

    .PARAMETER Password
    The plaintext password string.

    .OUTPUTS
    Hex string representation of the 16-byte NT hash (uppercase).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Password
    )

    if ([string]::IsNullOrEmpty($Password)) {
        return $null
    }

    try {
        # Convert password to UTF-16LE bytes
        $passwordBytes = [System.Text.Encoding]::Unicode.GetBytes($Password)

        # Calculate MD4 hash (NT hash = MD4(UTF-16LE(password)))
        # Use the existing Get-MD4Hash function from Kerberos-Crypto.ps1
        $ntHashBytes = Get-MD4Hash -Data $passwordBytes

        if ($null -eq $ntHashBytes -or $ntHashBytes.Length -ne 16) {
            Write-Log "[Get-NTHashFromPassword] Get-MD4Hash returned invalid result"
            return $null
        }

        # Convert to hex string (uppercase for consistency)
        $ntHashHex = ($ntHashBytes | ForEach-Object { $_.ToString("X2") }) -join ''

        return $ntHashHex

    } catch {
        Write-Log "[Get-NTHashFromPassword] Error calculating NT hash: $_"
        return $null
    }
}



# ----- ConvertFrom-LAPSEncryptedPassword.ps1 -----

function ConvertFrom-LAPSEncryptedPassword {
    <#
    .SYNOPSIS
    Parses and optionally decrypts the msLAPS-EncryptedPassword attribute from Windows LAPS v2.

    .DESCRIPTION
    Decodes the LAPS encrypted password structure which uses DPAPI-NG (CNG DPAPI) protection.

    The function can:
    1. Parse metadata (always works):
       - Password update timestamp (from header)
       - Encryption algorithm info
       - Target SID (who is authorized to decrypt)

    2. Decrypt the password (only if authorized):
       - Calls NCryptUnprotectSecret Windows API
       - DC validates if caller is member of authorized group
       - Returns cleartext password and account name

    The encrypted blob structure:
    - 16-byte header: Timestamp (8) + EncryptedSize (4) + Flags (4)
    - Body: CMS EnvelopedData (DPAPI-NG protected)
    - JSON format after decryption: {"n":"AccountName","t":"HexTimestamp","p":"Password"}

    .PARAMETER Blob
    The raw byte array from the msLAPS-EncryptedPassword attribute.

    .PARAMETER Decrypt
    If specified, attempts to decrypt the password using the Windows CNG API.
    This requires the caller to be a member of an authorized group.

    .EXAMPLE
    # Parse metadata only (no decryption)
    $computer = Get-DomainComputer -Identity "WS001" -Properties msLAPS-EncryptedPassword
    $lapsInfo = ConvertFrom-LAPSEncryptedPassword -Blob $computer.'msLAPS-EncryptedPassword'
    $lapsInfo.UpdateTimestamp
    $lapsInfo.TargetSID

    .EXAMPLE
    # Decrypt password (requires authorization)
    $computer = Get-DomainComputer -Identity "WS001" -Properties msLAPS-EncryptedPassword
    $lapsInfo = ConvertFrom-LAPSEncryptedPassword -Blob $computer.'msLAPS-EncryptedPassword' -Decrypt
    $lapsInfo.Password
    $lapsInfo.Account

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [byte[]]$Blob,

        [Parameter(Mandatory = $false)]
        [switch]$Decrypt
    )

    begin {
        # LAPS v2 Encrypted Password blob structure (Windows LAPS):
        # The blob has a 16-byte header followed by CMS EnvelopedData
        #
        # Header (16 bytes):
        #   - Bytes 0-7:  Timestamp (FILETIME, Little-Endian) - Password update time
        #   - Bytes 8-11: Encrypted data length (DWORD, Little-Endian)
        #   - Bytes 12-15: Flags/Reserved (DWORD)
        #
        # Body: CMS EnvelopedData (DPAPI-NG protected)
        # JSON format after decryption: {"n":"AccountName","t":"HexTimestamp","p":"Password"}

        $HeaderSize = 16
    }

    process {
        try {
            # Validate input
            if ($null -eq $Blob) {
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Blob is null"
                return $null
            }

            if ($Blob.Length -lt 20) {
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Blob too short (min 20 bytes, got $($Blob.Length))"
                return $null
            }

            Write-Log "[ConvertFrom-LAPSEncryptedPassword] Blob size: $($Blob.Length) bytes, first bytes: $($Blob[0..15] -join ',')"

            # Check if blob starts with ASN.1 SEQUENCE (0x30) - no header
            # Or if it has a 16-byte header before CMS data
            $encryptedData = $null
            $updateTimestamp = $null

            if ($Blob[0] -eq 0x30) {
                # Raw CMS EnvelopedData without header
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Blob starts with ASN.1 SEQUENCE - no header"
                $encryptedData = $Blob
            } else {
                # Has 16-byte header - parse it
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Parsing 16-byte header"

                # Extract timestamp from header (bytes 0-7)
                # LAPS v2 uses Big-Endian format for FILETIME:
                #   Bytes 0-3: High DWORD (Big-Endian stored as Little-Endian DWORD)
                #   Bytes 4-7: Low DWORD (Big-Endian stored as Little-Endian DWORD)
                # Reconstruct: (HighDWORD << 32) | LowDWORD
                try {
                    $highDword = [BitConverter]::ToUInt32($Blob, 0)
                    $lowDword = [BitConverter]::ToUInt32($Blob, 4)
                    $fileTime = ([Int64]$highDword -shl 32) -bor [Int64]$lowDword

                    # Validate FILETIME is reasonable (between year 2000 and 2100)
                    $minFileTime = 125911584000000000  # 2000-01-01
                    $maxFileTime = 157766880000000000  # 2100-01-01

                    if ($fileTime -gt $minFileTime -and $fileTime -lt $maxFileTime) {
                        $updateTimestamp = [DateTime]::FromFileTimeUtc($fileTime)
                        Write-Log "[ConvertFrom-LAPSEncryptedPassword] Header timestamp: $updateTimestamp"
                    } else {
                        Write-Log "[ConvertFrom-LAPSEncryptedPassword] Header timestamp out of valid range: $fileTime (raw bytes: $($Blob[0..7] -join ','))"
                    }
                } catch {
                    Write-Log "[ConvertFrom-LAPSEncryptedPassword] Failed to parse header timestamp: $_"
                }

                # Extract encrypted size from header (bytes 8-11)
                $encryptedSize = [BitConverter]::ToUInt32($Blob, 8)
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Header encrypted size: $encryptedSize"

                # Extract flags (bytes 12-15)
                $flags = [BitConverter]::ToUInt32($Blob, 12)
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Header flags: 0x$($flags.ToString('X8'))"

                # Extract CMS data after header
                if ($Blob.Length -ge $HeaderSize + $encryptedSize) {
                    $encryptedData = New-Object byte[] $encryptedSize
                    [Array]::Copy($Blob, $HeaderSize, $encryptedData, 0, $encryptedSize)
                    Write-Log "[ConvertFrom-LAPSEncryptedPassword] Extracted CMS data: $($encryptedData.Length) bytes, starts with: 0x$($encryptedData[0].ToString('X2'))"
                } else {
                    # Encrypted size doesn't match - try using remaining bytes
                    $remainingSize = $Blob.Length - $HeaderSize
                    Write-Log "[ConvertFrom-LAPSEncryptedPassword] Size mismatch (header says $encryptedSize, have $remainingSize), using remaining bytes"
                    $encryptedData = New-Object byte[] $remainingSize
                    [Array]::Copy($Blob, $HeaderSize, $encryptedData, 0, $remainingSize)
                }
            }

            # Parse CMS structure to extract metadata (Target SID, algorithms)
            $targetSID = $null
            $contentEncryptionAlgorithm = $null
            $keyEncryptionAlgorithm = $null

            try {
                $cmsInfo = Parse-CMSEnvelopedData -Data $encryptedData
                if ($cmsInfo) {
                    $targetSID = $cmsInfo.TargetSID
                    $contentEncryptionAlgorithm = $cmsInfo.ContentEncryptionAlgorithm
                    $keyEncryptionAlgorithm = $cmsInfo.KeyEncryptionAlgorithm
                }
            } catch {
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Failed to parse CMS structure: $_"
            }

            # Resolve Target SID to name
            $targetSIDName = $null
            if ($targetSID) {
                try {
                    $targetSIDName = ConvertFrom-SID -SID $targetSID
                } catch {
                    $targetSIDName = $targetSID
                }
            }

            # Build result object with metadata
            $result = [PSCustomObject]@{
                UpdateTimestamp            = $updateTimestamp
                EncryptedSize              = if ($encryptedData) { $encryptedData.Length } else { $Blob.Length }
                TargetSID                  = $targetSID
                TargetSIDName              = $targetSIDName
                ContentEncryptionAlgorithm = $contentEncryptionAlgorithm
                KeyEncryptionAlgorithm     = $keyEncryptionAlgorithm
                Password                   = $null
                Account                    = $null
                DecryptionSucceeded        = $false
                DecryptionError            = $null
            }

            # Attempt decryption if requested
            if ($Decrypt) {
                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Attempting decryption via NCryptUnprotectSecret"

                try {
                    # LAPS v2 encrypted blob should be passed directly to NCryptUnprotectSecret
                    # The API handles the DPAPI-NG/CMS format internally
                    # Try full blob first (most common), then CMS-only as fallback
                    $decryptedData = $null

                    try {
                        Write-Log "[ConvertFrom-LAPSEncryptedPassword] Trying full blob ($($Blob.Length) bytes)"
                        $decryptedData = Invoke-NCryptUnprotectSecret -ProtectedBlob $Blob
                    } catch {
                        $fullError = $_.Exception.Message
                        Write-Log "[ConvertFrom-LAPSEncryptedPassword] Full blob failed: $fullError"

                        # If full blob fails, try CMS-only (without header)
                        if ($encryptedData -and $encryptedData.Length -ne $Blob.Length) {
                            try {
                                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Trying CMS-only ($($encryptedData.Length) bytes)"
                                $decryptedData = Invoke-NCryptUnprotectSecret -ProtectedBlob $encryptedData
                            } catch {
                                # Both failed - rethrow the original error
                                throw $fullError
                            }
                        } else {
                            throw
                        }
                    }

                    if ($decryptedData -and $decryptedData.Length -gt 0) {
                        # Parse the decrypted LAPS password structure (JSON format in UTF-16LE)
                        $jsonString = [System.Text.Encoding]::Unicode.GetString($decryptedData)

                        # Remove null terminator if present
                        $jsonString = $jsonString.TrimEnd([char]0)

                        Write-Log "[ConvertFrom-LAPSEncryptedPassword] Decrypted data length: $($decryptedData.Length), JSON length: $($jsonString.Length)"

                        if ($jsonString.StartsWith('{')) {
                            try {
                                $lapsData = $jsonString | ConvertFrom-Json

                                # Validate expected JSON properties exist
                                if ($null -ne $lapsData.p) {
                                    $result.Password = $lapsData.p
                                    $result.Account = $lapsData.n
                                    $result.DecryptionSucceeded = $true

                                    # Parse timestamp from JSON "t" property (hex FILETIME string)
                                    if ($lapsData.t) {
                                        try {
                                            $fileTime = [Convert]::ToInt64($lapsData.t, 16)
                                            $result.UpdateTimestamp = [DateTime]::FromFileTimeUtc($fileTime)
                                        } catch {
                                            Write-Log "[ConvertFrom-LAPSEncryptedPassword] Failed to parse timestamp: $($lapsData.t)"
                                        }
                                    }

                                    Write-Log "[ConvertFrom-LAPSEncryptedPassword] Successfully decrypted password for account: $($lapsData.n)"
                                } else {
                                    Write-Log "[ConvertFrom-LAPSEncryptedPassword] JSON missing 'p' (password) property"
                                    $result.DecryptionError = "JSON structure invalid - missing 'p' property"
                                }
                            } catch {
                                Write-Log "[ConvertFrom-LAPSEncryptedPassword] Failed to parse JSON: $_"
                                $result.DecryptionError = "JSON parse error: $_"
                            }
                        } else {
                            # Might be plain password without JSON wrapper
                            $result.Password = $jsonString
                            $result.DecryptionSucceeded = $true
                        }
                    } else {
                        $result.DecryptionError = "NCryptUnprotectSecret returned empty data"
                    }
                } catch {
                    $errorMessage = $_.Exception.Message
                    Write-Log "[ConvertFrom-LAPSEncryptedPassword] Decryption failed: $errorMessage"
                    $result.DecryptionError = $errorMessage

                    # Check for common error codes and provide meaningful messages
                    if ($errorMessage -match "0x8009310B") {
                        # NTE_NOT_SUPPORTED - typically means non-domain-joined system
                        $result.DecryptionError = "DPAPI-NG not supported - requires domain-joined system for LAPS v2 encrypted password decryption"
                    } elseif ($errorMessage -match "0x8009002C") {
                        # NTE_INTERNAL_ERROR - CMS format issue
                        $result.DecryptionError = "CMS format error - encrypted blob may be corrupted or incompatible"
                    } elseif ($errorMessage -match "0x80090034" -or $errorMessage -match "NTE_DECRYPTION_FAILURE") {
                        $result.DecryptionError = "Access denied - current user is not authorized to decrypt this password"
                    } elseif ($errorMessage -match "0x80070005" -or $errorMessage -match "ACCESS_DENIED") {
                        $result.DecryptionError = "Access denied - not a member of authorized group ($targetSIDName)"
                    }
                }
            }

            return $result

        } catch {
            Write-Log "[ConvertFrom-LAPSEncryptedPassword] Error: $_"
            return $null
        }
    }
}


function Parse-CMSEnvelopedData {
    <#
    .SYNOPSIS
    Parses a CMS EnvelopedData structure to extract DPAPI-NG metadata.
    Internal helper function.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Data
    )

    # This is a simplified ASN.1 parser for CMS EnvelopedData
    # Full parsing would require a proper ASN.1 library

    $result = @{
        TargetSID = $null
        ContentEncryptionAlgorithm = $null
        KeyEncryptionAlgorithm = $null
    }

    try {
        # Look for SID pattern in the data (S-1-5-21-...)
        # SIDs in DPAPI-NG are stored in binary format
        # Domain SIDs have format: S-1-5-21-<DomainID1>-<DomainID2>-<DomainID3>-<RID>
        # That's 4 sub-authorities after the "21" (which is the first sub-authority)

        # Search for SID header: 0x01 (revision) followed by sub-authority count
        for ($i = 0; $i -lt $Data.Length - 8; $i++) {
            # Check for SID revision 1 and reasonable sub-authority count (4-5 for domain SIDs)
            # Domain SID without RID = 4, with RID = 5
            if ($Data[$i] -eq 0x01 -and $Data[$i + 1] -ge 4 -and $Data[$i + 1] -le 6) {
                $subAuthCount = $Data[$i + 1]

                # Check bounds before accessing authority bytes
                if ($i + 8 + ($subAuthCount * 4) -gt $Data.Length) {
                    continue
                }

                # Check for NT Authority (0x00 0x00 0x00 0x00 0x00 0x05) at offset +2
                if ($Data[$i + 2] -eq 0 -and $Data[$i + 3] -eq 0 -and
                    $Data[$i + 4] -eq 0 -and $Data[$i + 5] -eq 0 -and
                    $Data[$i + 6] -eq 0 -and $Data[$i + 7] -eq 5) {

                    # Extract sub-authorities (each is 4 bytes, Little-Endian)
                    $subAuths = @()
                    for ($j = 0; $j -lt $subAuthCount; $j++) {
                        $offset = $i + 8 + ($j * 4)
                        $subAuth = [BitConverter]::ToUInt32($Data, $offset)
                        $subAuths += $subAuth
                    }

                    # Build SID string
                    $sidString = "S-1-5-" + ($subAuths -join '-')

                    # Validate it looks like a domain SID (S-1-5-21-<3 domain parts>[-RID])
                    # Domain SIDs: S-1-5-21-xxxxxxx-xxxxxxx-xxxxxxx or S-1-5-21-xxxxxxx-xxxxxxx-xxxxxxx-RID
                    if ($sidString -match '^S-1-5-21-\d+-\d+-\d+(-\d+)?$') {
                        $result.TargetSID = $sidString
                        Write-Log "[Parse-CMSEnvelopedData] Found Target SID: $sidString"
                        break
                    }
                }
            }
        }

        # Look for OID patterns for algorithm identification
        # AES-256-GCM OID: 2.16.840.1.101.3.4.1.46
        $aes256GcmOid = @(0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x01, 0x2E)
        if (Find-BytePattern -Data $Data -Pattern $aes256GcmOid) {
            $result.ContentEncryptionAlgorithm = "AES-256-GCM (2.16.840.1.101.3.4.1.46)"
        }

    } catch {
        Write-Log "[Parse-CMSEnvelopedData] Error parsing CMS: $_"
    }

    return $result
}


function Find-BytePattern {
    <#
    .SYNOPSIS
    Searches for a byte pattern in a byte array.
    Internal helper function.
    #>
    [CmdletBinding()]
    param(
        [byte[]]$Data,
        [byte[]]$Pattern
    )

    # Validate inputs
    if ($null -eq $Data -or $null -eq $Pattern -or $Data.Length -lt $Pattern.Length) {
        return $false
    }

    for ($i = 0; $i -le $Data.Length - $Pattern.Length; $i++) {
        $match = $true
        for ($j = 0; $j -lt $Pattern.Length; $j++) {
            if ($Data[$i + $j] -ne $Pattern[$j]) {
                $match = $false
                break
            }
        }
        if ($match) {
            return $true
        }
    }

    return $false
}


function Invoke-NCryptUnprotectSecret {
    <#
    .SYNOPSIS
    Calls the Windows NCryptUnprotectSecret API to decrypt DPAPI-NG protected data.

    .DESCRIPTION
    This function uses P/Invoke to call the native NCryptUnprotectSecret function
    from ncrypt.dll. The API contacts the Domain Controller which validates
    if the caller is authorized to decrypt the data.

    .PARAMETER ProtectedBlob
    The DPAPI-NG protected data blob.

    .OUTPUTS
    Byte array containing the decrypted data, or throws an exception on failure.

    .NOTES
    Requires Windows 8 / Server 2012 or later.
    The calling process must be able to contact a Domain Controller.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$ProtectedBlob
    )

    # Define P/Invoke signatures
    $ncryptSignatures = @"
using System;
using System.Runtime.InteropServices;

public class NCryptInterop
{
    // NCryptUnprotectSecret flags
    public const int NCRYPT_UNPROTECT_NO_DECRYPT = 0x00000001;
    public const int NCRYPT_SILENT_FLAG = 0x00000040;

    // SECURITY_STATUS values
    public const int ERROR_SUCCESS = 0;
    public const int NTE_DECRYPTION_FAILURE = unchecked((int)0x80090034);

    [StructLayout(LayoutKind.Sequential)]
    public struct NCryptDescriptor
    {
        public IntPtr pDescriptorString;
    }

    [DllImport("ncrypt.dll", CharSet = CharSet.Unicode)]
    public static extern int NCryptUnprotectSecret(
        IntPtr phDescriptor,           // Optional output descriptor handle
        int dwFlags,                   // Flags
        [In] byte[] pbProtectedBlob,   // Protected data
        int cbProtectedBlob,           // Size of protected data
        IntPtr pMemPara,               // Memory allocation (NULL = LocalAlloc)
        IntPtr hWnd,                   // Window handle for UI (NULL for silent)
        out IntPtr ppbData,            // Output: decrypted data
        out int pcbData                // Output: size of decrypted data
    );

    [DllImport("kernel32.dll")]
    public static extern IntPtr LocalFree(IntPtr hMem);
}
"@

    # Add the type if not already added
    if (-not ([System.Management.Automation.PSTypeName]'NCryptInterop').Type) {
        try {
            Add-Type -TypeDefinition $ncryptSignatures -Language CSharp -ErrorAction Stop
        } catch {
            if ($_.Exception.Message -notmatch "already exists") {
                throw $_
            }
        }
    }

    $ppbData = [IntPtr]::Zero
    $pcbData = 0

    try {
        # Call NCryptUnprotectSecret
        # Using NCRYPT_SILENT_FLAG to prevent UI prompts
        $result = [NCryptInterop]::NCryptUnprotectSecret(
            [IntPtr]::Zero,                      # No descriptor output needed
            [NCryptInterop]::NCRYPT_SILENT_FLAG, # Silent mode
            $ProtectedBlob,                      # Protected data
            $ProtectedBlob.Length,               # Size
            [IntPtr]::Zero,                      # Default memory allocation
            [IntPtr]::Zero,                      # No UI window
            [ref]$ppbData,                       # Output pointer
            [ref]$pcbData                        # Output size
        )

        if ($result -ne 0) {
            $errorHex = "0x{0:X8}" -f $result
            throw "NCryptUnprotectSecret failed with error code $errorHex"
        }

        if ($ppbData -eq [IntPtr]::Zero -or $pcbData -eq 0) {
            throw "NCryptUnprotectSecret returned empty data"
        }

        # Copy decrypted data to managed array
        $decryptedData = New-Object byte[] $pcbData
        [System.Runtime.InteropServices.Marshal]::Copy($ppbData, $decryptedData, 0, $pcbData)

        return $decryptedData

    } finally {
        # Free allocated memory
        if ($ppbData -ne [IntPtr]::Zero) {
            [void][NCryptInterop]::LocalFree($ppbData)
        }
    }
}



# ----- ConvertFrom-SupplementalCredentials.ps1 -----

<#
.SYNOPSIS
    Parses USER_PROPERTIES structure from supplementalCredentials attribute.

.DESCRIPTION
    Parses the supplementalCredentials attribute (Layer 3 decryption after DRSUAPI + RID-DES).
    Extracts Kerberos keys (AES256/AES128/DES), cleartext password, and WDigest hashes.

    Structure (from MS-SAMR):
    USER_PROPERTIES:
      Reserved1     : 4 bytes (0x00000000)
      Length        : 4 bytes
      Reserved2     : 2 bytes
      Reserved3     : 2 bytes
      Reserved4     : 96 bytes
      PropertySignature : 2 bytes (0x0050 = 'P')
      PropertyCount : 2 bytes
      UserProperties: variable (array of USER_PROPERTY)

    USER_PROPERTY:
      NameLength    : 2 bytes
      ValueLength   : 2 bytes
      Reserved      : 2 bytes
      PropertyName  : NameLength bytes (UTF-16LE)
      PropertyValue : ValueLength bytes (hex-encoded ASCII!)

.PARAMETER Data
    Raw supplementalCredentials bytes (after DRSUAPI + RID-DES decryption).

.OUTPUTS
    PSCustomObject with properties:
    - AES256Key (string, hex)
    - AES128Key (string, hex)
    - DESKey (string, hex)
    - KerberosSalt (string)
    - CleartextPassword (string, if available)
    - WDigestHashes (array of strings)

.EXAMPLE
    $suppCreds = ConvertFrom-SupplementalCredentials -Data $userData.SupplementalCredentials
    Write-Host "AES256: $($suppCreds.AES256Key)"

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function ConvertFrom-SupplementalCredentials {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data
    )

    process {
        try {
            if (-not $Data -or $Data.Length -lt 110) {
                Write-Log "[ConvertFrom-SupplementalCredentials] Data too small or empty"
                return $null
            }

            # Read USER_PROPERTIES header
            $offset = 0

            # Reserved1 (4 bytes) - skip
            $offset += 4

            # Length (4 bytes)
            $length = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4

            # Reserved2 + Reserved3 + Reserved4 (2 + 2 + 96 = 100 bytes) - skip
            $offset += 100

            # PropertySignature (2 bytes) - should be 0x0050 ('P')
            $signature = [BitConverter]::ToUInt16($Data, $offset)
            $offset += 2

            if ($signature -ne 0x0050) {
                Write-Log "[ConvertFrom-SupplementalCredentials] Invalid PropertySignature: 0x$($signature.ToString('X4')) (expected 0x0050)"
                return $null
            }

            # PropertyCount (2 bytes)
            $propertyCount = [BitConverter]::ToUInt16($Data, $offset)
            $offset += 2

            Write-Log "[ConvertFrom-SupplementalCredentials] PropertyCount: $propertyCount"

            # Parse USER_PROPERTY entries
            $properties = @{}

            for ($i = 0; $i -lt $propertyCount; $i++) {
                if ($offset + 6 -gt $Data.Length) {
                    Write-Log "[ConvertFrom-SupplementalCredentials] Incomplete property header at offset $offset"
                    break
                }

                # NameLength (2 bytes)
                $nameLength = [BitConverter]::ToUInt16($Data, $offset)
                $offset += 2

                # ValueLength (2 bytes)
                $valueLength = [BitConverter]::ToUInt16($Data, $offset)
                $offset += 2

                # Reserved (2 bytes) - skip
                $offset += 2

                # PropertyName (UTF-16LE)
                if ($offset + $nameLength -gt $Data.Length) {
                    Write-Log "[ConvertFrom-SupplementalCredentials] Incomplete property name at offset $offset"
                    break
                }

                $propertyName = [System.Text.Encoding]::Unicode.GetString($Data, $offset, $nameLength)
                $offset += $nameLength

                # PropertyValue (hex-encoded ASCII!)
                if ($offset + $valueLength -gt $Data.Length) {
                    Write-Log "[ConvertFrom-SupplementalCredentials] Incomplete property value at offset $offset"
                    break
                }

                $propertyValueHex = [System.Text.Encoding]::ASCII.GetString($Data, $offset, $valueLength)
                $offset += $valueLength

                # Convert hex string to bytes
                # Validate hex string length is even
                if ($propertyValueHex.Length % 2 -ne 0) {
                    Write-Log "[ConvertFrom-SupplementalCredentials] Invalid hex string length for '$propertyName' (must be even): $($propertyValueHex.Length)"
                    continue
                }

                try {
                    $propertyValueBytes = for ($j = 0; $j -lt $propertyValueHex.Length; $j += 2) {
                        [Convert]::ToByte($propertyValueHex.Substring($j, 2), 16)
                    }
                }
                catch {
                    Write-Log "[ConvertFrom-SupplementalCredentials] Failed to parse property value for '$propertyName': $($_.Exception.Message)"
                    continue
                }

                $properties[$propertyName] = $propertyValueBytes
                Write-Log "[ConvertFrom-SupplementalCredentials] Property: $propertyName (ValueLength: $valueLength bytes)"
            }

            # Extract Kerberos keys from Primary:Kerberos-Newer-Keys
            $aes256Key = $null
            $aes128Key = $null
            $desKey = $null
            $kerberosSalt = $null

            if ($properties.ContainsKey('Primary:Kerberos-Newer-Keys')) {
                $kerberosData = $properties['Primary:Kerberos-Newer-Keys']
                Write-Log "[ConvertFrom-SupplementalCredentials] Parsing Primary:Kerberos-Newer-Keys ($($kerberosData.Length) bytes)"
                $result = Parse-KerberosNewerKeys -Data $kerberosData
                if ($result) {
                    $aes256Key = $result.AES256Key
                    $aes128Key = $result.AES128Key
                    if ($result.DESKey) { $desKey = $result.DESKey }
                    $kerberosSalt = $result.Salt
                    Write-Log "[ConvertFrom-SupplementalCredentials] Extracted AES256: $($null -ne $aes256Key), AES128: $($null -ne $aes128Key), DES: $($null -ne $desKey), Salt: $kerberosSalt"
                } else {
                    Write-Log "[ConvertFrom-SupplementalCredentials] Parse-KerberosNewerKeys returned null"
                }
            }

            # Extract DES key from Primary:Kerberos (old format) - fallback if not in Newer-Keys
            if (-not $desKey -and $properties.ContainsKey('Primary:Kerberos')) {
                $kerberosData = $properties['Primary:Kerberos']
                $desKeyFromOld = Parse-KerberosKeys -Data $kerberosData
                if ($desKeyFromOld) { $desKey = $desKeyFromOld }
            }

            # Extract cleartext password
            $cleartextPassword = $null
            if ($properties.ContainsKey('Primary:CLEARTEXT')) {
                $cleartextData = $properties['Primary:CLEARTEXT']
                $cleartextPassword = [System.Text.Encoding]::Unicode.GetString($cleartextData)
            }

            # Extract WDigest hashes
            $wdigestHashes = @()
            if ($properties.ContainsKey('Primary:WDigest')) {
                $wdigestData = $properties['Primary:WDigest']
                $wdigestHashes = Parse-WDigestHashes -Data $wdigestData
            }

            # Return parsed credentials
            return [PSCustomObject]@{
                AES256Key = $aes256Key
                AES128Key = $aes128Key
                DESKey = $desKey
                KerberosSalt = $kerberosSalt
                CleartextPassword = $cleartextPassword
                WDigestHashes = $wdigestHashes
            }
        }
        catch {
            Write-Log "[ConvertFrom-SupplementalCredentials] Failed to parse supplementalCredentials: $($_.Exception.Message)"
            return $null
        }
    }
}

# Helper function to parse KERB_STORED_CREDENTIAL_NEW
function Parse-KerberosNewerKeys {
    [CmdletBinding()]
    param([byte[]]$Data)

    try {
        if ($Data.Length -lt 20) { return $null }

        $offset = 0

        # Revision (2 bytes) - should be 3 or 4
        $revision = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # Flags (2 bytes)
        $flags = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # CredentialCount (2 bytes)
        $credentialCount = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # ServiceCredentialCount (2 bytes)
        $serviceCredentialCount = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # OldCredentialCount (2 bytes)
        $oldCredentialCount = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # OlderCredentialCount (2 bytes)
        $olderCredentialCount = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # DefaultSaltLength (2 bytes)
        $defaultSaltLength = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2

        # DefaultSaltMaximumLength (2 bytes) - skip
        $offset += 2

        # DefaultSaltOffset (4 bytes)
        $defaultSaltOffset = [BitConverter]::ToUInt32($Data, $offset)
        $offset += 4

        # Extract salt
        $salt = $null
        if ($defaultSaltLength -gt 0 -and $defaultSaltOffset -lt $Data.Length -and ($defaultSaltOffset + $defaultSaltLength) -le $Data.Length) {
            $salt = [System.Text.Encoding]::Unicode.GetString($Data, $defaultSaltOffset, $defaultSaltLength)
        }

        # Parse KERB_KEY_DATA_NEW entries
        $aes256Key = $null
        $aes128Key = $null
        $desKey = $null

        Write-Verbose "[Parse-KerberosNewerKeys] Parsing $credentialCount credential entries starting at offset $offset"

        for ($i = 0; $i -lt $credentialCount; $i++) {

            # First entry is 28 bytes (with extra Reserved4), subsequent entries are 24 bytes
            $entrySize = if ($i -eq 0) { 28 } else { 24 }

            if ($offset + $entrySize -gt $Data.Length) {
                Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: Insufficient data at offset $offset"
                break
            }

            # KERB_KEY_DATA_NEW structure
            # Reserved1 (2 bytes)
            $offset += 2
            # Reserved2 (2 bytes)
            $offset += 2
            # Reserved3 (4 bytes)
            $offset += 4

            # Reserved4 (4 bytes) - ONLY in first entry for Revision 4
            if ($i -eq 0) {
                $offset += 4
            }

            # IterationCount (4 bytes) - PBKDF2 iterations
            $offset += 4
            # KeyType (4 bytes) - Encryption type (17=AES128, 18=AES256, 3=DES)
            $keyType = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4
            # KeyLength (4 bytes) - Key size in bytes
            $keyLength = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4
            # KeyOffset (4 bytes) - Offset from start of KERB_STORED_CREDENTIAL_NEW
            $keyOffset = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4

            Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: KeyType=${keyType}, KeyLength=${keyLength}, KeyOffset=${keyOffset}"

            # Extract key
            if ($keyOffset -lt $Data.Length -and ($keyOffset + $keyLength) -le $Data.Length) {
                $keyBytes = $Data[$keyOffset..($keyOffset + $keyLength - 1)]
                $keyHex = ($keyBytes | ForEach-Object { $_.ToString('x2') }) -join ''

                # Map KeyType to encryption type
                switch ($keyType) {
                    18 {
                        $aes256Key = $keyHex
                        $keySize = $keyHex.Length / 2
                        Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: Extracted AES256 key ($keySize bytes)"
                    }
                    17 {
                        $aes128Key = $keyHex
                        $keySize = $keyHex.Length / 2
                        Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: Extracted AES128 key ($keySize bytes)"
                    }
                    3 {
                        $desKey = $keyHex
                        $keySize = $keyHex.Length / 2
                        Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: Extracted DES key ($keySize bytes)"
                    }
                    default {
                        Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: Skipped KeyType $keyType"
                    }
                }
            } else {
                Write-Verbose "[Parse-KerberosNewerKeys] Entry ${i}: KeyOffset out of bounds (offset=${keyOffset}, length=${keyLength}, dataSize=$($Data.Length))"
            }
        }

        return [PSCustomObject]@{
            AES256Key = $aes256Key
            AES128Key = $aes128Key
            DESKey = $desKey
            Salt = $salt
        }
    }
    catch {
        Write-Log "[Parse-KerberosNewerKeys] Failed: $($_.Exception.Message)"
        return $null
    }
}

# Helper function to parse Primary:Kerberos (DES key)
function Parse-KerberosKeys {
    [CmdletBinding()]
    param([byte[]]$Data)

    try {
        # Similar to Parse-KerberosNewerKeys but looks for KeyType 3 (DES-CBC-MD5)
        if ($Data.Length -lt 20) { return $null }

        $offset = 0
        $revision = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2
        $offset += 2  # Flags
        $credentialCount = [BitConverter]::ToUInt16($Data, $offset)
        $offset += 2
        $offset += 2  # ServiceCredentialCount
        $offset += 2  # OldCredentialCount
        $offset += 2  # OlderCredentialCount
        $offset += 2  # DefaultSaltLength
        $offset += 2  # DefaultSaltMaximumLength
        $offset += 4  # DefaultSaltOffset

        for ($i = 0; $i -lt $credentialCount; $i++) {
            if ($offset + 20 -gt $Data.Length) { break }

            $offset += 8  # Reserved
            $offset += 4  # IterationCount
            $keyType = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4
            $keyLength = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4
            $keyOffset = [BitConverter]::ToUInt32($Data, $offset)
            $offset += 4

            if ($keyType -eq 3 -and $keyOffset -lt $Data.Length -and ($keyOffset + $keyLength) -le $Data.Length) {  # DES-CBC-MD5
                $keyBytes = $Data[$keyOffset..($keyOffset + $keyLength - 1)]
                return ($keyBytes | ForEach-Object { $_.ToString('x2') }) -join ''
            }
        }

        return $null
    }
    catch {
        Write-Log "[Parse-KerberosKeys] Failed: $($_.Exception.Message)"
        return $null
    }
}

# Helper function to parse WDigest hashes
function Parse-WDigestHashes {
    [CmdletBinding()]
    param([byte[]]$Data)

    try {
        # WDigest structure:
        # Offset 0-3:   Reserved1(1) + Reserved2(1) + Version(1) + NumberOfHashes(1)
        # Offset 4-15:  Reserved3 (12 bytes)
        # Offset 16+:   29 x MD5 hashes (16 bytes each)

        if ($Data.Length -lt (16 + 29 * 16)) {
            Write-Log "[Parse-WDigestHashes] Data too small: $($Data.Length) bytes"
            return @()
        }

        $hashes = @()
        $offset = 16  # Skip 16-byte header (not 8!)

        for ($i = 1; $i -le 29; $i++) {
            if ($offset + 16 -gt $Data.Length) { break }

            $hashBytes = $Data[$offset..($offset + 15)]
            $hashHex = ($hashBytes | ForEach-Object { $_.ToString('x2') }) -join ''

            # Only include non-zero hashes
            if ($hashHex -ne '00000000000000000000000000000000') {
                $hashes += "${i}: $hashHex"
            }

            $offset += 16
        }

        return $hashes
    }
    catch {
        Write-Log "[Parse-WDigestHashes] Failed: $($_.Exception.Message)"
        return @()
    }
}



# ----- ConvertFrom-TSProperties.ps1 -----

<#
.SYNOPSIS
    Decodes the Terminal Services property blob stored in userParameters / terminalServer.

.DESCRIPTION
    The userParameters attribute (and the related terminalServer attribute) carry a
    TSPropertyArray structure documented in [MS-TSTS] section 2.2.1.1. The blob holds
    legacy Terminal Services / Remote Desktop per-user settings such as the TS home
    directory, TS profile path, allow-logon flag, shadowing mode, and idle-timeout.

    Layout (little-endian):
        Reserved1 : 96 bytes  (48 WCHAR, usually all 0x20 0x00 = U+0020 spaces)
        Signature : 2 bytes   (WCHAR 'P' = 0x50 0x00)
        PropCount : 2 bytes   (USHORT, number of TSProperty entries)
        Properties: PropCount * TSPropertyStruct

    TSPropertyStruct:
        NameLength  : 2 bytes  (length of PropertyName in bytes)
        ValueLength : 2 bytes  (length of PropertyValue in bytes)
        Type        : 2 bytes  (1 = String, 2 = ULong)
        PropertyName: NameLength bytes (Unicode string)
        PropertyValue: ValueLength bytes (each output byte is encoded as 2 ASCII
                       characters where char = nibble + 0x30; 0..9 -> '0'..'9',
                       A..F -> ':'..'?')

.PARAMETER Bytes
    Raw byte[] read from LDAP. May be wrapped in a single-element array.

.OUTPUTS
    [string[]] - one human-readable line per recognised property. Returns $null when
    the blob does not look like a TSPropertyArray (signature mismatch).
#>
function ConvertFrom-TSProperties {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Bytes
    )

    # Unwrap single-element array
    if ($Bytes -is [array] -and $Bytes.Count -eq 1 -and $Bytes[0] -is [byte[]]) {
        $Bytes = $Bytes[0]
    }
    if ($Bytes -isnot [byte[]]) { return $null }

    # Need at least preamble + signature + count
    if ($Bytes.Length -lt 100) { return $null }

    # Validate signature: WCHAR 'P' at offset 96 (0x50 0x00 little-endian)
    if ($Bytes[96] -ne 0x50 -or $Bytes[97] -ne 0x00) { return $null }

    $propCount = [BitConverter]::ToUInt16($Bytes, 98)
    if ($propCount -lt 1 -or $propCount -gt 100) { return $null }  # sanity

    $offset = 100
    $lines = @()

    # Friendly labels for the well-known Ctx* property names
    $labelMap = @{
        'CtxCfgPresent'             = 'TSConfigPresent'
        'CtxCfgFlags1'              = 'TSConfigFlags'
        'CtxCallback'               = 'TSCallback'
        'CtxCallbackNumber'         = 'TSCallbackNumber'
        'CtxKeyboardLayout'         = 'TSKeyboardLayout'
        'CtxMinEncryptionLevel'     = 'TSMinEncryptionLevel'
        'CtxNWLogonServer'          = 'TSNetWareLogonServer'
        'CtxWFHomeDir'              = 'TSHomeDirectory'
        'CtxWFHomeDirDrive'         = 'TSHomeDrive'
        'CtxWFProfilePath'          = 'TSProfilePath'
        'CtxInitialProgram'         = 'TSInitialProgram'
        'CtxMaxConnectionTime'      = 'TSMaxConnectionTime'
        'CtxMaxDisconnectionTime'   = 'TSMaxDisconnectionTime'
        'CtxMaxIdleTime'            = 'TSMaxIdleTime'
        'CtxShadow'                 = 'TSShadowingSetting'
        'CtxWorkDirectory'          = 'TSWorkDirectory'
    }

    # Flag bits for CtxCfgFlags1 (only the ones useful for security review).
    # Use a plain hashtable, not [ordered]@{} - the OrderedDictionary indexer treats
    # integer arguments as positional indices, so $cfgFlags[0x20] returns the 32nd
    # entry (or fails) instead of the value under key 0x00000020. With @{} the
    # integer key lookup works as expected.
    $cfgFlags = @{
        0x00000008 = 'INHERIT_INITIAL_PROGRAM'
        0x00000010 = 'INHERIT_CALLBACK'
        0x00000020 = 'INHERIT_CALLBACK_NUMBER'
        0x00000040 = 'INHERIT_SHADOW'
        0x00000080 = 'INHERIT_MAX_DISCONNECTION_TIME'
        0x00000100 = 'INHERIT_MAX_CONNECTION_TIME'
        0x00000200 = 'INHERIT_MAX_IDLE_TIME'
        0x00000400 = 'INHERIT_AUTO_CLIENT'
        0x00010000 = 'AUTO_CLIENT_DRIVES'
        0x00020000 = 'AUTO_CLIENT_PRINTERS'
        0x00040000 = 'FORCE_CLIENT_PRINTER_DEFAULT'
        0x00080000 = 'DISABLE_ENCRYPTION'
        0x00100000 = 'HOMEDIR_MAP_ROOT'
        0x00200000 = 'USE_DEFAULT_GINA'
        0x00400000 = 'DISABLE_CPM'
        0x00800000 = 'DISABLE_CDM'
        0x01000000 = 'DISABLE_CCM'
        0x02000000 = 'DISABLE_LPT'
        0x04000000 = 'DISABLE_CLIP'
        0x08000000 = 'DISABLE_EXE'
        0x10000000 = 'WALLPAPER_DISABLED'
        0x40000000 = 'LOGON_DISABLED'
        0x80000000 = 'RECONNECT_SAME'
    }
    # Sorted ascending key list so flag enumeration is deterministic
    $cfgFlagKeys = ($cfgFlags.Keys | Sort-Object)

    try {
        for ($i = 0; $i -lt $propCount; $i++) {
            if ($offset + 6 -gt $Bytes.Length) { break }

            $nameLen  = [BitConverter]::ToUInt16($Bytes, $offset);     $offset += 2
            $valueLen = [BitConverter]::ToUInt16($Bytes, $offset);     $offset += 2
            $type     = [BitConverter]::ToUInt16($Bytes, $offset);     $offset += 2

            # Sanity: header lengths must point inside the buffer and the encoded
            # value must be an even number of bytes (two ASCII chars per output byte).
            if ($offset + $nameLen + $valueLen -gt $Bytes.Length) { break }
            if ($valueLen % 2 -ne 0) { break }

            $name = [System.Text.Encoding]::Unicode.GetString($Bytes, $offset, $nameLen)
            $offset += $nameLen

            # Decode value: each output byte = (nibbleHi - 0x30) << 4 | (nibbleLo - 0x30)
            # The valueLen is the length of the ENCODED ASCII representation, so the
            # decoded byte count is valueLen / 2.
            $decodedLen = [int]($valueLen / 2)
            $decoded = New-Object byte[] $decodedLen
            for ($k = 0; $k -lt $decodedLen; $k++) {
                $hi = $Bytes[$offset + ($k * 2)]     - 0x30
                $lo = $Bytes[$offset + ($k * 2) + 1] - 0x30
                $decoded[$k] = (($hi -shl 4) -bor $lo) -band 0xFF
            }
            $offset += $valueLen

            $label = if ($labelMap.ContainsKey($name)) { $labelMap[$name] } else { $name }

            switch ($type) {
                1 {
                    # String - decoded bytes are UTF-16LE Unicode (with trailing NULs)
                    $str = [System.Text.Encoding]::Unicode.GetString($decoded).TrimEnd([char]0)
                    if ($str) { $lines += "$label = '$str'" }
                }
                2 {
                    # ULong - decoded bytes are a 4-byte little-endian integer
                    if ($decoded.Length -ge 4) {
                        $val = [BitConverter]::ToUInt32($decoded, 0)
                        if ($name -eq 'CtxCfgFlags1') {
                            $setFlags = foreach ($mask in $cfgFlagKeys) {
                                if ($val -band $mask) { $cfgFlags[$mask] }
                            }
                            if ($setFlags) {
                                $lines += ("{0} = 0x{1:X8} ({2})" -f $label, $val, ($setFlags -join ', '))
                            } else {
                                $lines += ("{0} = 0x{1:X8}" -f $label, $val)
                            }
                        } elseif ($name -eq 'CtxCfgPresent') {
                            # 0xB00FA6C3 marker = configured at least once
                            $lines += ("{0} = 0x{1:X8}" -f $label, $val)
                        } else {
                            $lines += "$label = $val"
                        }
                    }
                }
                default {
                    $lines += "$label (type $type, $($decoded.Length) bytes)"
                }
            }
        }
    } catch {
        Write-Log "[ConvertFrom-TSProperties] Parse error: $_"
        return $null
    }

    if ($lines.Count -eq 0) { return $null }
    return $lines
}



# ----- ConvertFrom-TSClientLicense.ps1 -----

<#
.SYNOPSIS
    Decodes the legacy Terminal Server Per-User CAL token stored in the
    terminalServer attribute.

.DESCRIPTION
    The terminalServer attribute (1.2.840.113556.1.4.1410) is written by
    Remote Desktop Licensing the first time a user receives a Per-User CAL.
    The layout is not part of any public ADSI specification; the structure
    below was reconstructed empirically against TS 6.x (Server 2008 R2) and
    later RDS deployments:

        UInt32 LE  : Version / marker (0x00060000 for TS 6.x)
        FILETIME   : Token issue timestamp (UTC)
        WCHAR[]    : Null-terminated Windows Product ID of the licensed
                     instance, format XXXXX-XXX-XXXXXXX-XXXXX

    A typical record is 60 bytes (4 + 8 + 23 * 2 + 2 NUL terminator).

    NOTE: This format is unrelated to the TSPropertyArray held by the
    userParameters attribute - use ConvertFrom-TSProperties for that.

.PARAMETER Bytes
    Raw byte[] read from LDAP. May be wrapped in a single-element array.

.OUTPUTS
    [string[]] - one human-readable line per decoded field. Returns $null
    when the blob is too short, the FILETIME is implausible, or the data
    otherwise does not look like a CAL token.
#>
function ConvertFrom-TSClientLicense {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Bytes
    )

    # Unwrap single-element array
    if ($Bytes -is [array] -and $Bytes.Count -eq 1 -and $Bytes[0] -is [byte[]]) {
        $Bytes = $Bytes[0]
    }
    if ($Bytes -isnot [byte[]]) { return $null }

    # Minimum: 4 (version) + 8 (FILETIME) + 2 (WCHAR NUL terminator) = 14
    if ($Bytes.Length -lt 14) { return $null }

    $version  = [BitConverter]::ToUInt32($Bytes, 0)
    $fileTime = [BitConverter]::ToInt64($Bytes, 4)

    # Per-User CAL tracking was introduced with Server 2008; reject FILETIMEs
    # outside [2005, 2099] as a quick sanity check that this is really a CAL token.
    $issued = $null
    try { $issued = [DateTime]::FromFileTimeUtc($fileTime) } catch { return $null }
    if ($issued.Year -lt 2005 -or $issued.Year -gt 2099) { return $null }

    # Trailing UTF-16LE NUL-terminated Product ID string
    $strBytes  = $Bytes[12..($Bytes.Length - 1)]
    $productId = [System.Text.Encoding]::Unicode.GetString($strBytes).TrimEnd([char]0)

    $lines = @()
    $lines += ("Version = 0x{0:X8}" -f $version)
    $lines += ("Issued = {0:yyyy-MM-dd HH:mm:ss} UTC" -f $issued)
    if ($productId) { $lines += "ProductID = '$productId'" }
    return $lines
}



# ----- Get-CurrentUserTokenGroups.ps1 -----

function Get-CurrentUserTokenGroups {
    <#
    .SYNOPSIS
    Returns all SIDs the current authenticated user is a member of.

    .DESCRIPTION
    Queries the tokenGroups attribute for the current LDAP session to get all
    group memberships (including nested groups) of the authenticated user.

    This is useful for checking if the current user can decrypt LAPS encrypted
    passwords, as the Target SID must be in the user's token groups.

    The function caches results in $Script:CurrentUserTokenGroups for performance.

    .PARAMETER Force
    Force refresh of cached token groups.

    .EXAMPLE
    $groups = Get-CurrentUserTokenGroups
    if ($groups -contains 'S-1-5-21-...-512') {
        # User is in Domain Admins
    }

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [switch]$Force
    )

    # Return cached result if available and not forcing refresh
    if (-not $Force -and $Script:CurrentUserTokenGroups) {
        Write-Log "[Get-CurrentUserTokenGroups] Returning cached token groups ($($Script:CurrentUserTokenGroups.Count) SIDs)"
        return $Script:CurrentUserTokenGroups
    }

    # Need active LDAP connection
    # UNIFIED: Check for LdapConnection (works for both LDAP and LDAPS)
    if (-not $Script:LdapConnection -or -not $Script:LDAPContext) {
        Write-Log "[Get-CurrentUserTokenGroups] No active LDAP connection"
        return @()
    }

    try {
        Write-Log "[Get-CurrentUserTokenGroups] Querying tokenGroups for current session..."

        # Query tokenGroups on domain root with Base scope using Invoke-LDAPSearch
        # When using SSPI/Kerberos, this returns groups for the AUTHENTICATED user
        # Note: tokenGroups is a special constructed attribute that returns raw byte arrays
        $TokenResults = Invoke-LDAPSearch -Filter "(objectClass=*)" -Properties "tokenGroups" -Scope "Base" -Raw

        $TokenGroupSIDs = @()

        if ($TokenResults -and $TokenResults.Count -gt 0) {
            $TokenResult = $TokenResults[0]
            $tokenGroupsAttr = $TokenResult.tokenGroups

            if ($tokenGroupsAttr) {
                # tokenGroups can be single value or array
                $tokenGroupsArray = if ($tokenGroupsAttr -is [array]) { $tokenGroupsAttr } else { @($tokenGroupsAttr) }

                foreach ($sidBytes in $tokenGroupsArray) {
                    try {
                        if ($sidBytes -is [byte[]]) {
                            $sid = New-Object System.Security.Principal.SecurityIdentifier($sidBytes, 0)
                            $TokenGroupSIDs += $sid.Value
                        }
                    } catch {
                        Write-Log "[Get-CurrentUserTokenGroups] Failed to parse SID bytes: $_"
                    }
                }
                Write-Log "[Get-CurrentUserTokenGroups] Found $($TokenGroupSIDs.Count) token groups"
            } else {
                Write-Log "[Get-CurrentUserTokenGroups] tokenGroups attribute not found"
            }
        } else {
            Write-Log "[Get-CurrentUserTokenGroups] tokenGroups query returned no results"
        }

        # Cache the result
        $Script:CurrentUserTokenGroups = $TokenGroupSIDs

        return $TokenGroupSIDs

    } catch {
        Write-Log "[Get-CurrentUserTokenGroups] Error: $_"
        return @()
    }
}


function Test-SIDInTokenGroups {
    <#
    .SYNOPSIS
    Tests if a given SID is in the current user's token groups.

    .DESCRIPTION
    Checks if the specified SID (typically a LAPS Target SID) is in the
    current user's group memberships. This is a fast local check that
    can be used to determine if the user can decrypt an encrypted LAPS password.

    .PARAMETER SID
    The SID to check for membership.

    .EXAMPLE
    if (Test-SIDInTokenGroups -SID 'S-1-5-21-1234-5678-9012-512') {
        # User is authorized for this Target SID
    }

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$SID
    )

    $tokenGroups = Get-CurrentUserTokenGroups

    if (-not $tokenGroups -or $tokenGroups.Count -eq 0) {
        return $false
    }

    return ($tokenGroups -contains $SID)
}



# ----- Get-adPEASSession.ps1 -----

function Get-adPEASSession {
<#
.SYNOPSIS
    Shows information about the current adPEAS session or tests connection health.

.DESCRIPTION
    Displays detailed information about the current LDAP connection and session.
    Shows Domain, Server, Protocol, Authentication and Session duration.

    With -TestConnection switch, performs a health check on the active session:
    - Checks session variables
    - Validates LDAP connection object
    - Executes test query to verify connectivity
    - Measures query latency

.PARAMETER TestConnection
    Performs a connection health check instead of showing session info.
    Tests if the session is still active and responsive.
    Shows detailed diagnostic information including domain, server, latency.

.PARAMETER Quiet
    Suppresses all output during TestConnection.
    Only returns $true/$false without displaying test results.
    Useful when called programmatically (e.g., from Invoke-adPEAS).

.EXAMPLE
    Get-adPEASSession
    Shows current session information.

.EXAMPLE
    Get-adPEASSession -TestConnection
    Performs connection health check with diagnostic details.

.EXAMPLE
    Get-adPEASSession -TestConnection -Quiet
    Performs silent health check, returns only $true/$false.

.EXAMPLE
    if (Get-adPEASSession -TestConnection -Quiet) {
        Write-Host "Connection is healthy"
    }

.OUTPUTS
    Without -TestConnection: Displays session information to console
    With -TestConnection: $true if connection is healthy, $false if problems exist

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [switch]$TestConnection,

        [Parameter(Mandatory=$false)]
        [switch]$Quiet
    )

    process {
        # Check if session exists (common check for both modes)
        # LdapConnection is used for ALL LDAP operations (queries and modifications)
        $hasLdapConnection = ($null -ne $Script:LdapConnection)

        if (-not $Script:LDAPContext -or -not $hasLdapConnection) {
            if ($TestConnection) {
                if (-not $Quiet) {
                    Show-SubHeader "Checking connection health..."
                    Show-KeyValue "Session Variables:" "FAIL: No active session found" -Class Finding
                    return
                }
                return $false
            } else {
                Show-NoSessionError -Context "Get-adPEASSession"
                return $null
            }
        }

        # Test Connection Health
        if ($TestConnection) {
            try {
                # Only show output if not in Quiet mode
                if (-not $Quiet) {
                    Show-Line "Health:" -Class Hint
                    Show-SubHeader "Checking connection health..."
                }

                $testResults = @{
                    SessionExists = $true
                    ConnectionValid = $false
                    QuerySuccessful = $false
                    Latency = $null
                    HealthStatus = "Unknown"
                    Errors = @()
                }

                # Test 1: Session variables (already checked above)
                if (-not $Quiet) {
                    Show-KeyValue "Session Variables:" "PASS" -Class Standard
                }

                # Test 2: Check if connection object is valid
                # LdapConnection is the only connection object used for all operations
                if ($hasLdapConnection) {
                    $protocol = if ($Script:LDAPContext.UseLDAPS) { "LDAPS" } else { "LDAP" }
                    if (-not $Quiet) {
                        Show-KeyValue "LDAP Connection Object:" "PASS (LdapConnection for $protocol)" -Class Standard
                    }
                }
                else {
                    if (-not $Quiet) {
                        Show-KeyValue "LDAP Connection Object:" "FAIL: No connection object found" -Class Finding
                        return
                    }
                    return $false
                }

                # Test 3: Execute test query
                $queryStartTime = Get-Date

                try {
                    $testQuery = Invoke-LDAPSearch -Filter "(objectClass=domain)" -SearchBase $Script:LDAPContext.DomainDN -Properties "name" -Scope Base

                    if (-not $testQuery) {
                        if (-not $Quiet) {
                            Show-KeyValue "LDAP Query Execution:" "FAIL: Test query returned no results" -Class Finding
                            return
                        }
                        return $false
                    }

                    $queryEndTime = Get-Date
                    $latency = ($queryEndTime - $queryStartTime).TotalMilliseconds

                    if (-not $Quiet) {
                        Show-KeyValue "LDAP Query Execution:" "PASS (Latency: $([math]::Round($latency, 2)) ms)" -Class Standard
                    }
                    $testResults.QuerySuccessful = $true
                    $testResults.Latency = [math]::Round($latency, 2)

                }
                catch {
                    if (-not $Quiet) {
                        Show-KeyValue "LDAP Query Execution:" "FAIL: $($_.Exception.Message)" -Class Finding
                        return
                    }
                    return $false
                }

                # All tests passed
                $testResults.HealthStatus = "Healthy"

                if (-not $Quiet) {
                    Show-KeyValue "Result:" "PASS (All tests passed - Connection is healthy)" -Class Note
                    Show-EmptyLine
                    return
                }

                return $true
            }
            catch {
                if (-not $Quiet) {
                    Show-KeyValue "Unexpected Error:" "FAIL: $($_.Exception.Message)" -Class Finding
                    Show-EmptyLine
                    return
                }
                return $false
            }
        }

        # Show Session Information (default)
        else {
            # Use SubHeader for session info (big ===== headers reserved for Invoke-adPEAS modules)
            Show-SubHeader "Displaying active session information..."

            # Connection Details
            Show-Line "Connection:" -Class Hint
            Show-KeyValue "Domain:" $Script:LDAPContext.Domain

            # Display Domain SID
            if ($Script:LDAPContext.DomainSID) {
                Show-KeyValue "Domain SID:" $Script:LDAPContext.DomainSID
            }

            Show-KeyValue "Server:" $Script:LDAPContext.Server
            if ($Script:LDAPContext['ServerIP']) {
                Show-KeyValue "Server IP:" $Script:LDAPContext['ServerIP']
            }
            Show-KeyValue "Protocol:" "$($Script:LDAPContext.Protocol) (Port $($Script:LDAPContext.Port))"
            Show-KeyValue "Domain DN:" $Script:LDAPContext.DomainDN

            # Authentication Details
            Show-EmptyLine
            Show-Line "Authentication:" -Class Hint

            if ($Script:LDAPContext.KerberosUsed -and $Script:LDAPContext.TGTInfo -and $Script:LDAPContext.TGTInfo.UserName) {
                # For Kerberos auth (Hash/Key/PKINIT), show TGT user
                $TGTUser = "$($Script:LDAPContext.TGTInfo.UserName)@$($Script:LDAPContext.TGTInfo.Domain)"
                Show-KeyValue "Authenticated as:" $TGTUser

                # Show User SID if available
                if ($Script:LDAPContext.AuthenticatedUserSID) {
                    Show-KeyValue "User SID:" $Script:LDAPContext.AuthenticatedUserSID
                }

                # Show NT-Hash if recovered via UnPAC-the-hash (PKINIT only)
                if ($Script:LDAPContext.TGTInfo.NTHash) {
                    Show-KeyValue "NT-Hash:" $Script:LDAPContext.TGTInfo.NTHash
                }
            }
            elseif ($Script:LDAPContext.AuthenticatedUser) {
                Show-KeyValue "Authenticated as:" $Script:LDAPContext.AuthenticatedUser

                # Show User SID if available
                if ($Script:LDAPContext.AuthenticatedUserSID) {
                    Show-KeyValue "User SID:" $Script:LDAPContext.AuthenticatedUserSID
                }

                if ($Script:LDAPContext.IdentityMismatch) {
                    Show-KeyValue "Local Identity:" $Script:LDAPContext.LocalIdentity
                    Show-Line "  Identity Mismatch: DETECTED" -Class Hint
                }

                # Show DN and UPN if available
                if ($Script:LDAPContext.AuthenticatedUserDN) {
                    Show-KeyValue "Distinguished Name:" $Script:LDAPContext.AuthenticatedUserDN
                }
                if ($Script:LDAPContext.AuthenticatedUserUPN) {
                    Show-KeyValue "User Principal Name:" $Script:LDAPContext.AuthenticatedUserUPN
                }
            }
            # Fallback if LDAP verification not available
            elseif ($Script:LDAPContext.Credential) {
                Show-KeyValue "Authenticated as:" $Script:LDAPContext.Credential.UserName
            }
            else {
                Show-KeyValue "Authenticated as:" "$env:USERDOMAIN\$env:USERNAME"
            }

            # Authentication Method (Kerberos vs SimpleBind vs Schannel vs NTLM)
            $AuthMethodDisplay = switch ($Script:LDAPContext.AuthMethod) {
                'Kerberos' {
                    # Check if TGT info is available (explicit Kerberos) or detected via SSPI
                    if ($Script:LDAPContext.TGTInfo) {
                        'Kerberos (TGT/TGS)'
                    } else {
                        'Kerberos (SSPI)'
                    }
                }
                'Schannel' { 'Schannel (TLS Client Certificate)' }
                'SimpleBind' { if ($Script:LDAPContext.UseLDAPS) { 'SimpleBind (LDAPS)' } else { 'SimpleBind (LDAP)' } }
                'WindowsSSPI' { 'Windows SSPI (Negotiate)' }
                'WindowsAuth' { 'Windows Authentication (Negotiate)' }
                'NTLM' { if ($Script:LDAPContext.UseLDAPS) { 'NTLM (LDAPS)' } else { 'NTLM (LDAP)' } }
                'NTLM Impersonation' { 'NTLM Impersonation (runas /netonly)' }
                default { 'Unknown' }
            }
            Show-KeyValue "Authentication Method:" $AuthMethodDisplay

            # Show TGT details if Kerberos was used
            if ($Script:LDAPContext.KerberosUsed -and $Script:LDAPContext.TGTInfo) {
                $TGT = $Script:LDAPContext.TGTInfo

                # Encryption type mapping (from original session)
                $ETypeDisplay = switch ($TGT.EncryptionType) {
                    17 { 'AES128-CTS-HMAC-SHA1' }
                    18 { 'AES256-CTS-HMAC-SHA1' }
                    23 { 'RC4-HMAC (NTLM)' }
                    default { "etype $($TGT.EncryptionType)" }
                }
                Show-KeyValue "TGT Encryption:" $ETypeDisplay

                # Show TGT method (how the TGT was obtained)
                if ($TGT.Method) {
                    Show-KeyValue "TGT Method:" $TGT.Method
                }

                # Show TGT realm
                if ($TGT.Domain) {
                    Show-KeyValue "TGT Realm:" $TGT.Domain
                }

                # Show clock skew between local system and KDC
                if ($TGT.ClockSkew -and $TGT.ClockSkew -is [TimeSpan]) {
                    $skewSeconds = [Math]::Round($TGT.ClockSkew.TotalSeconds)
                    $skewAbs = [Math]::Abs($skewSeconds)
                    $skewSign = if ($skewSeconds -ge 0) { "+" } else { "-" }
                    if ($skewAbs -ge 3600) {
                        $skewDisplay = "${skewSign}$([Math]::Floor($skewAbs / 3600))h $([Math]::Floor(($skewAbs % 3600) / 60))m"
                    } elseif ($skewAbs -ge 60) {
                        $skewDisplay = "${skewSign}$([Math]::Floor($skewAbs / 60))m $($skewAbs % 60)s"
                    } else {
                        $skewDisplay = "${skewSign}${skewAbs}s"
                    }
                    if ($skewAbs -gt 300) {
                        # >5 minutes - exceeds Kerberos tolerance
                        Show-KeyValue "Clock Skew:" "$skewDisplay (WARNING: exceeds 5-minute Kerberos limit!)" -Class Finding
                    } elseif ($skewAbs -gt 270) {
                        # 4.5-5 minutes - close to Kerberos tolerance
                        Show-KeyValue "Clock Skew:" "$skewDisplay (WARNING: close to 5-minute Kerberos limit)" -Class Finding
                    } elseif ($skewAbs -gt 60) {
                        Show-KeyValue "Clock Skew:" $skewDisplay -Class Hint
                    } else {
                        Show-KeyValue "Clock Skew:" $skewDisplay
                    }
                }

                # LIVE TGT Status Check via LSA API
                # Use -Force to bypass the 60-second cache and get real-time ticket status
                $LiveTicketStatus = Test-KerberosTGTExists -Detailed -Force

                if ($LiveTicketStatus.Valid) {
                    # Tickets are valid - show live EndTime from LSA
                    $endTimeLocal = $LiveTicketStatus.EndTime.ToLocalTime()
                    $now = Get-Date
                    $timeRemaining = $LiveTicketStatus.EndTime - $now

                    if ($timeRemaining.TotalSeconds -gt 0) {
                        $remainingDisplay = "{0:hh\:mm\:ss}" -f $timeRemaining
                        Show-KeyValue "TGT Valid Until:" "$($endTimeLocal.ToString('yyyy-MM-dd HH:mm:ss')) (in $remainingDisplay)"
                    }
                    else {
                        Show-KeyValue "TGT Valid Until:" "$($endTimeLocal.ToString('yyyy-MM-dd HH:mm:ss'))" -Class Finding
                        Write-Warning "[!] TGT EXPIRED - Re-authentication required!"
                    }

                }
                elseif ($LiveTicketStatus.TicketCount -eq 0) {
                    # Tickets were purged (klist purge)
                    Show-KeyValue "TGT Status:" "NO TICKETS IN CACHE - Re-authenticate with Connect-adPEAS" -Class Finding
                }
                elseif (-not $LiveTicketStatus.TGTPresent) {
                    # Tickets exist but no TGT (only service tickets)
                    Show-KeyValue "TGT Status:" "NO TGT FOUND ($($LiveTicketStatus.TicketCount) service tickets) - Re-authenticate with Connect-adPEAS" -Class Finding
                }
                elseif ($LiveTicketStatus.Expired) {
                    # TGT exists but is expired
                    $expiredTime = if ($LiveTicketStatus.EndTime) {
                        $LiveTicketStatus.EndTime.ToLocalTime().ToString('yyyy-MM-dd HH:mm:ss')
                    } else { "unknown" }
                    Show-KeyValue "TGT Status:" "EXPIRED at $expiredTime - Re-authenticate with Connect-adPEAS" -Class Finding
                }
                elseif ($LiveTicketStatus.ClientMatch -eq $false) {
                    # TGT exists but for different user
                    $tgtClient = $LiveTicketStatus.ClientName
                    $expectedClient = $Script:LDAPContext.TGTInfo.UserName
                    Show-KeyValue "TGT Status:" "CLIENT MISMATCH (TGT=$tgtClient, Expected=$expectedClient) - Re-authenticate with Connect-adPEAS" -Class Finding
                }
                else {
                    # Unknown issue with tickets
                    Show-KeyValue "TGT Status:" "INVALID - Re-authenticate with Connect-adPEAS" -Class Finding
                }
            }

            # Session Metadata
            Show-EmptyLine
            Show-Line "Session:" -Class Hint
            if ($Script:LDAPContext.SessionStartTime) {
                $sessionDuration = (Get-Date) - $Script:LDAPContext.SessionStartTime
                Show-KeyValue "Session Started:" $Script:LDAPContext.SessionStartTime
                Show-KeyValue "Session Duration:" $sessionDuration.ToString('hh\:mm\:ss')
            }

            # Connection State - check live TGT status for Kerberos sessions
            if ($Script:LDAPContext.KerberosUsed) {
                # Re-use LiveTicketStatus if already queried, otherwise query again with -Force
                if (-not $LiveTicketStatus) {
                    $LiveTicketStatus = Test-KerberosTGTExists -Detailed -Force
                }

                if ($LiveTicketStatus.Valid) {
                    Show-KeyValue "Connection State:" "Connected (Kerberos TGT valid)"
                }
                elseif ($LiveTicketStatus.TicketCount -eq 0) {
                    Show-KeyValue "Connection State:" "DEGRADED (No Kerberos tickets)" -Class Finding
                }
                elseif (-not $LiveTicketStatus.TGTPresent) {
                    Show-KeyValue "Connection State:" "DEGRADED (No TGT, only service tickets)" -Class Finding
                }
                elseif ($LiveTicketStatus.Expired) {
                    Show-KeyValue "Connection State:" "DEGRADED (TGT expired)" -Class Finding
                }
                elseif ($LiveTicketStatus.ClientMatch -eq $false) {
                    Show-KeyValue "Connection State:" "DEGRADED (TGT client mismatch)" -Class Finding
                }
                else {
                    Show-KeyValue "Connection State:" "DEGRADED (TGT invalid)" -Class Finding
                }
            }
            elseif ($Script:LDAPContext.AuthMethod -eq 'Schannel') {
                Show-KeyValue "Connection State:" "Connected (Schannel/TLS)"
            }
            else {
                Show-KeyValue "Connection State:" "Connected"
            }

            # Hints
            Show-EmptyLine
            Show-Line "Help:" -Class Hint
            Show-KeyValue "Get-adPEASSession -TestConnection" "Test connection health"
            Show-KeyValue "Disconnect-adPEAS" "End the session"
            Show-EmptyLine
        }
    }
}



# ----- Test-KerberosTGTExists.ps1 -----

<#
.SYNOPSIS
    Checks if valid Kerberos tickets exist in the current session's ticket cache.

.DESCRIPTION
    Uses the LSA API to query the Kerberos ticket cache and verify TGT validity.

    Two-stage check:
    1. Quick count check (MessageType 1 - KerbQueryTicketCacheMessage)
    2. If tickets exist: Scan ALL tickets to find TGT (MessageType 14 - KerbQueryTicketCacheExMessage)

    Validates:
    - At least one ticket exists
    - TGT is present (ServerName starts with "krbtgt/")
    - TGT is not expired (EndTime > now)
    - Client matches authenticated user (optional, if LDAPContext available)

    The result is cached in $Script:LDAPContext for performance (60 second validity).

.PARAMETER Force
    Force a fresh check, ignoring any cached result.

.PARAMETER Detailed
    Return detailed ticket information instead of just $true/$false.

.EXAMPLE
    Test-KerberosTGTExists
    Returns $true if a valid TGT exists, $false otherwise.

.EXAMPLE
    Test-KerberosTGTExists -Detailed
    Returns a PSCustomObject with ticket details (ServerName, Realm, EndTime, etc.)

.EXAMPLE
    Test-KerberosTGTExists -Force
    Forces a fresh LSA query, ignoring cached results.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Test-KerberosTGTExists {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [switch]$Force,

        [Parameter(Mandatory=$false)]
        [switch]$Detailed
    )

    # Check cache first (unless Force is specified)
    if (-not $Force -and $Script:LDAPContext) {
        $lastCheck = $Script:LDAPContext['KerberosLastCheck']
        if ($lastCheck -and ((Get-Date) - $lastCheck).TotalSeconds -lt 60) {
            $cachedValid = $Script:LDAPContext['KerberosValid']
            Write-Log "[Test-KerberosTGTExists] Using cached result: KerberosValid=$cachedValid"
            if ($Detailed) {
                return [PSCustomObject]@{
                    Valid = $cachedValid
                    TicketCount = $Script:LDAPContext['KerberosTicketCount']
                    TGTPresent = $Script:LDAPContext['KerberosTGTPresent']
                    ClientMatch = $Script:LDAPContext['KerberosClientMatch']
                    ServerName = $Script:LDAPContext['KerberosServerName']
                    Realm = $Script:LDAPContext['KerberosRealm']
                    ClientName = $Script:LDAPContext['KerberosClientName']
                    EndTime = $Script:LDAPContext['KerberosEndTime']
                    Expired = $Script:LDAPContext['KerberosExpired']
                    EncryptionType = $Script:LDAPContext['KerberosEncryptionType']
                    TicketFlags = $Script:LDAPContext['KerberosTicketFlags']
                    Cached = $true
                }
            }
            return $cachedValid
        }
    }

    Write-Log "[Test-KerberosTGTExists] Checking Kerberos ticket cache..."

    # Define P/Invoke signatures for LSA API
    $LsaSignatures = @'
        [DllImport("secur32.dll", SetLastError = true)]
        public static extern uint LsaConnectUntrusted(out IntPtr LsaHandle);

        [DllImport("secur32.dll", SetLastError = true)]
        public static extern uint LsaLookupAuthenticationPackage(
            IntPtr LsaHandle,
            ref LSA_STRING PackageName,
            out uint AuthenticationPackage);

        [DllImport("secur32.dll", SetLastError = true)]
        public static extern uint LsaCallAuthenticationPackage(
            IntPtr LsaHandle,
            uint AuthenticationPackage,
            IntPtr ProtocolSubmitBuffer,
            uint SubmitBufferLength,
            out IntPtr ProtocolReturnBuffer,
            out uint ReturnBufferLength,
            out int ProtocolStatus);

        [DllImport("secur32.dll", SetLastError = true)]
        public static extern uint LsaDeregisterLogonProcess(IntPtr LsaHandle);

        [DllImport("secur32.dll", SetLastError = true)]
        public static extern uint LsaFreeReturnBuffer(IntPtr Buffer);

        [StructLayout(LayoutKind.Sequential)]
        public struct LSA_STRING
        {
            public ushort Length;
            public ushort MaximumLength;
            public IntPtr Buffer;
        }

        [StructLayout(LayoutKind.Sequential)]
        public struct UNICODE_STRING
        {
            public ushort Length;
            public ushort MaximumLength;
            public IntPtr Buffer;
        }

        // Request structure for both MessageType 1 and 14
        [StructLayout(LayoutKind.Sequential)]
        public struct KERB_QUERY_TKT_CACHE_REQUEST
        {
            public int MessageType;
            public long LogonId;       // LUID - use 0 for current session
        }

        // Response header for MessageType 1 (simple count)
        [StructLayout(LayoutKind.Sequential)]
        public struct KERB_QUERY_TKT_CACHE_RESPONSE
        {
            public int MessageType;
            public int CountOfTickets;
        }

        // Response header for MessageType 14 (extended info)
        [StructLayout(LayoutKind.Sequential)]
        public struct KERB_QUERY_TKT_CACHE_EX_RESPONSE
        {
            public int MessageType;
            public int CountOfTickets;
            // Followed by KERB_TICKET_CACHE_INFO_EX array
        }

        // Single ticket cache entry (extended)
        // Size: 104 bytes on x64, 56 bytes on x86
        [StructLayout(LayoutKind.Sequential)]
        public struct KERB_TICKET_CACHE_INFO_EX
        {
            public UNICODE_STRING ClientName;      // 16 bytes (x64) / 8 bytes (x86)
            public UNICODE_STRING ClientRealm;     // 16 bytes (x64) / 8 bytes (x86)
            public UNICODE_STRING ServerName;      // 16 bytes (x64) / 8 bytes (x86)
            public UNICODE_STRING ServerRealm;     // 16 bytes (x64) / 8 bytes (x86)
            public long StartTime;                 // 8 bytes - FILETIME
            public long EndTime;                   // 8 bytes - FILETIME
            public long RenewTime;                 // 8 bytes - FILETIME
            public int EncryptionType;             // 4 bytes
            public uint TicketFlags;               // 4 bytes
        }
'@

    try {
        # Add type if not already added
        if (-not ([System.Management.Automation.PSTypeName]'LSA.KerberosEx').Type) {
            Add-Type -MemberDefinition $LsaSignatures -Name 'KerberosEx' -Namespace 'LSA' -ErrorAction Stop
        }
    } catch {
        # Type might already exist from previous call
        if ($_.Exception.Message -notmatch 'already exists') {
            Write-Log "[Test-KerberosTGTExists] Failed to add LSA type: $_"
            # Return $false on type load failure - we cannot check tickets
            if ($Detailed) {
                return [PSCustomObject]@{
                    Valid = $false
                    Error = "Failed to load LSA types: $($_.Exception.Message)"
                    Cached = $false
                }
            }
            return $false
        }
    }

    $lsaHandle = [IntPtr]::Zero
    $returnBuffer = [IntPtr]::Zero
    $ticketCount = 0
    $ticketInfo = $null

    try {
        # Connect to LSA (untrusted - no special privileges needed)
        $status = [LSA.KerberosEx]::LsaConnectUntrusted([ref]$lsaHandle)
        if ($status -ne 0) {
            Write-Log "[Test-KerberosTGTExists] LsaConnectUntrusted failed: 0x$($status.ToString('X8'))"
            if ($Detailed) {
                return [PSCustomObject]@{ Valid = $false; Error = "LsaConnectUntrusted failed: 0x$($status.ToString('X8'))"; Cached = $false }
            }
            return $false
        }

        # Lookup Kerberos authentication package
        $kerberosName = "Kerberos"
        $lsaString = New-Object LSA.KerberosEx+LSA_STRING
        $lsaString.Length = [uint16]$kerberosName.Length
        $lsaString.MaximumLength = [uint16]($kerberosName.Length + 1)
        $lsaString.Buffer = [System.Runtime.InteropServices.Marshal]::StringToHGlobalAnsi($kerberosName)

        $authPackage = 0
        try {
            $status = [LSA.KerberosEx]::LsaLookupAuthenticationPackage($lsaHandle, [ref]$lsaString, [ref]$authPackage)
            if ($status -ne 0) {
                Write-Log "[Test-KerberosTGTExists] LsaLookupAuthenticationPackage failed: 0x$($status.ToString('X8'))"
                if ($Detailed) {
                    return [PSCustomObject]@{ Valid = $false; Error = "LsaLookupAuthenticationPackage failed: 0x$($status.ToString('X8'))"; Cached = $false }
                }
                return $false
            }
        } finally {
            [System.Runtime.InteropServices.Marshal]::FreeHGlobal($lsaString.Buffer)
        }

        # Stage 1: Quick count check with MessageType 1
        $request = New-Object LSA.KerberosEx+KERB_QUERY_TKT_CACHE_REQUEST
        $request.MessageType = 1  # KerbQueryTicketCacheMessage
        $request.LogonId = 0

        $requestSize = [System.Runtime.InteropServices.Marshal]::SizeOf($request)
        $requestPtr = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($requestSize)

        try {
            [System.Runtime.InteropServices.Marshal]::StructureToPtr($request, $requestPtr, $false)

            $returnBufferLength = 0
            $protocolStatus = 0

            $status = [LSA.KerberosEx]::LsaCallAuthenticationPackage(
                $lsaHandle,
                $authPackage,
                $requestPtr,
                $requestSize,
                [ref]$returnBuffer,
                [ref]$returnBufferLength,
                [ref]$protocolStatus
            )

            if ($status -eq 0 -and $protocolStatus -eq 0 -and $returnBuffer -ne [IntPtr]::Zero) {
                $response = [System.Runtime.InteropServices.Marshal]::PtrToStructure(
                    $returnBuffer,
                    [Type][LSA.KerberosEx+KERB_QUERY_TKT_CACHE_RESPONSE]
                )
                $ticketCount = $response.CountOfTickets
            }

            # Free buffer from Stage 1
            if ($returnBuffer -ne [IntPtr]::Zero) {
                [LSA.KerberosEx]::LsaFreeReturnBuffer($returnBuffer) | Out-Null
                $returnBuffer = [IntPtr]::Zero
            }
        } finally {
            [System.Runtime.InteropServices.Marshal]::FreeHGlobal($requestPtr)
        }

        # If no tickets, we're done
        if ($ticketCount -eq 0) {
            Write-Log "[Test-KerberosTGTExists] No tickets in cache"
            $ticketInfo = [PSCustomObject]@{
                Valid = $false
                TicketCount = 0
                TGTPresent = $false
                ClientMatch = $null
                ServerName = $null
                Realm = $null
                ClientName = $null
                EndTime = $null
                Expired = $true
                EncryptionType = $null
                TicketFlags = $null
                Cached = $false
            }
        } else {
            # Stage 2: Scan ALL tickets to find TGT with MessageType 14
            $request.MessageType = 14  # KerbQueryTicketCacheExMessage
            $requestPtr = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($requestSize)

            try {
                [System.Runtime.InteropServices.Marshal]::StructureToPtr($request, $requestPtr, $false)

                $returnBufferLength = 0
                $protocolStatus = 0

                $status = [LSA.KerberosEx]::LsaCallAuthenticationPackage(
                    $lsaHandle,
                    $authPackage,
                    $requestPtr,
                    $requestSize,
                    [ref]$returnBuffer,
                    [ref]$returnBufferLength,
                    [ref]$protocolStatus
                )

                if ($status -eq 0 -and $protocolStatus -eq 0 -and $returnBuffer -ne [IntPtr]::Zero) {
                    # Read response header
                    $responseEx = [System.Runtime.InteropServices.Marshal]::PtrToStructure(
                        $returnBuffer,
                        [Type][LSA.KerberosEx+KERB_QUERY_TKT_CACHE_EX_RESPONSE]
                    )

                    # Calculate struct size (architecture-dependent)
                    $ticketStructSize = [System.Runtime.InteropServices.Marshal]::SizeOf([Type][LSA.KerberosEx+KERB_TICKET_CACHE_INFO_EX])

                    # Scan ALL tickets to find TGT
                    # IMPORTANT: Multiple krbtgt tickets may exist (e.g., expired + renewed).
                    # We prefer a valid (non-expired) TGT over an expired one.
                    $tgtFound = $false
                    $tgtServerName = $null
                    $tgtServerRealm = $null
                    $tgtClientName = $null
                    $tgtEndTime = $null
                    $tgtExpired = $true
                    $tgtEncType = $null
                    $tgtFlags = $null

                    for ($i = 0; $i -lt $responseEx.CountOfTickets; $i++) {
                        # Calculate offset: header (8 bytes) + (index * struct size)
                        $ticketOffset = 8 + ($i * $ticketStructSize)
                        $ticketPtr = [IntPtr]::Add($returnBuffer, $ticketOffset)

                        try {
                            $ticket = [System.Runtime.InteropServices.Marshal]::PtrToStructure(
                                $ticketPtr,
                                [Type][LSA.KerberosEx+KERB_TICKET_CACHE_INFO_EX]
                            )

                            # Extract ServerName
                            $serverName = $null
                            if ($ticket.ServerName.Buffer -ne [IntPtr]::Zero -and $ticket.ServerName.Length -gt 0) {
                                $serverName = [System.Runtime.InteropServices.Marshal]::PtrToStringUni(
                                    $ticket.ServerName.Buffer,
                                    $ticket.ServerName.Length / 2
                                )
                            }

                            # Check if this is a TGT (ServerName starts with "krbtgt/")
                            if ($serverName -and $serverName -imatch '^krbtgt/') {
                                # Parse EndTime for this TGT candidate
                                $candidateEndTime = $null
                                $candidateExpired = $true
                                if ($ticket.EndTime -gt 0) {
                                    try {
                                        $candidateEndTime = [DateTime]::FromFileTime($ticket.EndTime)
                                        $candidateExpired = $candidateEndTime -lt (Get-Date)
                                    } catch {
                                        Write-Log "[Test-KerberosTGTExists] Failed to parse TGT EndTime for ticket[$i]: $_"
                                    }
                                }

                                # Accept this TGT if: (a) first TGT found, or (b) this one is valid and previous was expired
                                if (-not $tgtFound -or ($tgtExpired -and -not $candidateExpired)) {
                                    $tgtFound = $true
                                    $tgtServerName = $serverName
                                    $tgtEndTime = $candidateEndTime
                                    $tgtExpired = $candidateExpired

                                    # Extract additional TGT details
                                    if ($ticket.ServerRealm.Buffer -ne [IntPtr]::Zero -and $ticket.ServerRealm.Length -gt 0) {
                                        $tgtServerRealm = [System.Runtime.InteropServices.Marshal]::PtrToStringUni(
                                            $ticket.ServerRealm.Buffer,
                                            $ticket.ServerRealm.Length / 2
                                        )
                                    }
                                    if ($ticket.ClientName.Buffer -ne [IntPtr]::Zero -and $ticket.ClientName.Length -gt 0) {
                                        $tgtClientName = [System.Runtime.InteropServices.Marshal]::PtrToStringUni(
                                            $ticket.ClientName.Buffer,
                                            $ticket.ClientName.Length / 2
                                        )
                                    }

                                    $tgtEncType = $ticket.EncryptionType
                                    $tgtFlags = $ticket.TicketFlags

                                    # If this TGT is valid, no need to keep looking
                                    if (-not $candidateExpired) {
                                        break
                                    }
                                }
                            }
                        } catch {
                            Write-Log "[Test-KerberosTGTExists] Error reading ticket[$i]: $_"
                            # Continue to next ticket
                        }
                    }

                    # Determine client match (if TGT found and context available)
                    $clientMatch = $true
                    if ($tgtFound -and $tgtClientName -and $Script:LDAPContext -and $Script:LDAPContext.TGTInfo -and $Script:LDAPContext.TGTInfo.UserName) {
                        $expectedClient = $Script:LDAPContext.TGTInfo.UserName
                        $clientMatch = $tgtClientName -ieq $expectedClient
                        if (-not $clientMatch) {
                            Write-Log "[Test-KerberosTGTExists] Client mismatch: TGT=$tgtClientName, Expected=$expectedClient"
                        }
                    }

                    # Determine validity
                    # Valid if: TGT found AND not expired AND client matches
                    $isValid = $tgtFound -and (-not $tgtExpired) -and $clientMatch

                    # Only log the final result
                    if ($isValid) {
                        Write-Log "[Test-KerberosTGTExists] Valid TGT found: $tgtServerName (Client: $tgtClientName)"
                    } else {
                        Write-Log "[Test-KerberosTGTExists] No valid TGT: Found=$tgtFound, Expired=$tgtExpired, ClientMatch=$clientMatch"
                    }

                    $ticketInfo = [PSCustomObject]@{
                        Valid = $isValid
                        TicketCount = $ticketCount
                        TGTPresent = $tgtFound
                        ClientMatch = $clientMatch
                        ServerName = $tgtServerName
                        Realm = $tgtServerRealm
                        ClientName = $tgtClientName
                        EndTime = $tgtEndTime
                        Expired = $tgtExpired
                        EncryptionType = $tgtEncType
                        TicketFlags = $tgtFlags
                        Cached = $false
                    }
                } else {
                    Write-Log "[Test-KerberosTGTExists] Stage 2 failed: status=0x$($status.ToString('X8')), protocolStatus=0x$($protocolStatus.ToString('X8'))"
                    # Fallback: Stage 2 failed, but we know tickets exist from Stage 1
                    # Return conservative result (cannot verify TGT)
                    $ticketInfo = [PSCustomObject]@{
                        Valid = $false
                        TicketCount = $ticketCount
                        TGTPresent = $null
                        ClientMatch = $null
                        ServerName = $null
                        Realm = $null
                        ClientName = $null
                        EndTime = $null
                        Expired = $null
                        EncryptionType = $null
                        TicketFlags = $null
                        Error = "Stage 2 query failed: status=0x$($status.ToString('X8')), protocolStatus=0x$($protocolStatus.ToString('X8'))"
                        Cached = $false
                    }
                }
            } finally {
                [System.Runtime.InteropServices.Marshal]::FreeHGlobal($requestPtr)
            }
        }
    } catch {
        Write-Log "[Test-KerberosTGTExists] Exception: $_"
        # Return $false on exception - we cannot verify tickets
        if ($Detailed) {
            return [PSCustomObject]@{
                Valid = $false
                Error = $_.Exception.Message
                Cached = $false
            }
        }
        return $false
    } finally {
        # Cleanup
        if ($returnBuffer -ne [IntPtr]::Zero) {
            [LSA.KerberosEx]::LsaFreeReturnBuffer($returnBuffer) | Out-Null
        }
        if ($lsaHandle -ne [IntPtr]::Zero) {
            [LSA.KerberosEx]::LsaDeregisterLogonProcess($lsaHandle) | Out-Null
        }
    }

    # Ensure ticketInfo is set (defensive)
    if (-not $ticketInfo) {
        $ticketInfo = [PSCustomObject]@{
            Valid = $false
            TicketCount = $ticketCount
            TGTPresent = $false
            ClientMatch = $null
            ServerName = $null
            Realm = $null
            ClientName = $null
            EndTime = $null
            Expired = $null
            EncryptionType = $null
            TicketFlags = $null
            Error = "Unknown error: ticketInfo not set"
            Cached = $false
        }
    }

    # Cache result in LDAPContext if it exists
    if ($Script:LDAPContext) {
        $Script:LDAPContext['KerberosTicketCount'] = $ticketInfo.TicketCount
        $Script:LDAPContext['KerberosLastCheck'] = Get-Date
        $Script:LDAPContext['KerberosValid'] = $ticketInfo.Valid
        $Script:LDAPContext['KerberosTGTPresent'] = $ticketInfo.TGTPresent
        $Script:LDAPContext['KerberosClientMatch'] = $ticketInfo.ClientMatch
        $Script:LDAPContext['KerberosServerName'] = $ticketInfo.ServerName
        $Script:LDAPContext['KerberosRealm'] = $ticketInfo.Realm
        $Script:LDAPContext['KerberosClientName'] = $ticketInfo.ClientName
        $Script:LDAPContext['KerberosEndTime'] = $ticketInfo.EndTime
        $Script:LDAPContext['KerberosExpired'] = $ticketInfo.Expired
        $Script:LDAPContext['KerberosEncryptionType'] = $ticketInfo.EncryptionType
        $Script:LDAPContext['KerberosTicketFlags'] = $ticketInfo.TicketFlags
    }

    if ($Detailed) {
        return $ticketInfo
    }

    return $ticketInfo.Valid
}



# ----- Ensure-LDAPConnection.ps1 -----

<#
.SYNOPSIS
    Ensures that an LDAP connection to the Domain Controller exists.

.DESCRIPTION
    This helper function ensures the correct LDAP connection is active.

    Simple logic:
    - Determine target Domain/Server/Credential (use auto-discovery if not specified)
    - Compare with existing connection
    - If ANY difference -> establish new connection

    This guarantees that queries always go to the expected target.

.PARAMETER Domain
    The target domain to query. If not specified, uses current domain.

.PARAMETER Server
    Specific Domain Controller (FQDN or IP). If not specified, uses auto-discovery.

.PARAMETER Credential
    Alternative credentials for domain queries.

.EXAMPLE
    Ensure-LDAPConnection
    Ensures connection to current domain with auto-discovery.

.EXAMPLE
    Ensure-LDAPConnection -Server "dc01.contoso.com"
    Ensures connection to specific DC.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Ensure-LDAPConnection {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    # Check if ANY parameters were explicitly provided
    $HasExplicitParams = $PSBoundParameters.ContainsKey('Domain') -or
                        $PSBoundParameters.ContainsKey('Server') -or
                        $PSBoundParameters.ContainsKey('Credential')

    # If NO parameters AND existing session -> ALWAYS reuse existing session
    # UNIFIED: LDAPContext is set for both LDAP and LDAPS connections
    # The actual connection is in $Script:LdapConnection (LdapConnection)
    if (-not $HasExplicitParams -and $Script:LDAPContext) {
        # Quick-exit if session was already marked invalid (avoids repeated error messages)
        if ($Script:LDAPContext['SessionInvalid']) {
            Write-Log "[Ensure-LDAPConnection] Session already marked invalid - skipping"
            return $false
        }

        # Use centrally determined authenticated user from Connect-LDAP
        $UsernameDisplay = $Script:LDAPContext.AuthenticatedUser
        Write-Log "[Ensure-LDAPConnection] No parameters specified - reusing existing session: Domain=$($Script:LDAPContext.Domain), Server=$($Script:LDAPContext.Server), User=$UsernameDisplay"

        # Health-Check: For Kerberos-based auth methods, verify TGT still exists
        # This catches scenarios like "klist purge" or expired tickets
        $AuthMethod = $Script:LDAPContext['AuthMethod']
        $KerberosAuthMethods = @('Kerberos', 'PKINIT', 'OverpassTheHash', 'PassTheKey', 'PassTheTicket')

        if ($AuthMethod -in $KerberosAuthMethods) {
            $ticketCheck = Test-KerberosTGTExists -Detailed
            if (-not $ticketCheck.Valid) {
                # Build detailed error message
                $errorDetails = "Kerberos TGT no longer valid"
                if ($ticketCheck.TicketCount -eq 0) {
                    $errorDetails = "No Kerberos tickets in cache (purged or never obtained)"
                } elseif ($ticketCheck.Expired) {
                    $expiredTime = if ($ticketCheck.EndTime) { $ticketCheck.EndTime.ToString('yyyy-MM-dd HH:mm:ss') } else { "unknown" }
                    $errorDetails = "Kerberos TGT expired at $expiredTime"
                } elseif ($ticketCheck.ClientMatch -eq $false) {
                    $errorDetails = "Kerberos TGT client mismatch (TGT=$($ticketCheck.ClientName), Expected=$($Script:LDAPContext.TGTInfo.UserName))"
                }
                $errorDetails += ". Re-authenticate with Connect-adPEAS."

                Write-Log "[Ensure-LDAPConnection] TGT validation failed: $errorDetails"

                # Show user-friendly error with hints
                Show-ConnectionError -ErrorType "AuthenticationFailed" -Details $errorDetails -NoThrow

                # Mark session as invalid to prevent repeated error messages on subsequent checks
                $Script:LDAPContext['SessionInvalid'] = $true
                Show-Line "Aborting scan - LDAP session is no longer valid. Re-authenticate with Connect-adPEAS." -Class Finding

                # Return false - caller should handle this gracefully
                return $false
            }
        }

        return $true
    }

    # If NO parameters AND NO session -> Error with instructions
    if (-not $HasExplicitParams -and -not $Script:LDAPContext) {
        # Get calling function name for context
        $CallingFunction = (Get-PSCallStack)[1].Command
        Show-NoSessionError -Context $CallingFunction
        # Return $false to indicate failure (caller must handle)
        return $false
    }

    # Determine target domain (auto-discover if not specified)
    $TargetDomain = $Domain
    if (-not $TargetDomain) {
        try {
            $CurrentDomain = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()
            $TargetDomain = $CurrentDomain.Name
        } catch {
            throw "Could not detect current domain. Please specify -Domain parameter."
        }
    }

    # Determine target server (null = auto-discovery)
    $TargetServer = $Server

    # Check if we need a new connection
    $NeedNewConnection = $false

    if (-not $Script:LDAPContext) {
        # No connection exists
        $NeedNewConnection = $true
        Write-Log "[Ensure-LDAPConnection] No existing connection - establishing new connection"
    } else {
        # Connection exists - check if parameters match EXACTLY

        # Compare Domain (only if explicitly specified)
        if ($Domain -and $Script:LDAPContext.Domain -ne $TargetDomain) {
            $NeedNewConnection = $true
            Write-Log "[Ensure-LDAPConnection] Domain mismatch: Current=$($Script:LDAPContext.Domain), Target=$TargetDomain"
        }

        # Compare Server (only if explicitly specified)
        if ($TargetServer -and $Script:LDAPContext.Server -ne $TargetServer) {
            $NeedNewConnection = $true
            Write-Log "[Ensure-LDAPConnection] Server mismatch: Current=$($Script:LDAPContext.Server), Target=$TargetServer"
        }

        # If credential parameter is provided, always reconnect (safe approach)
        if ($Credential) {
            $NeedNewConnection = $true
            Write-Log "[Ensure-LDAPConnection] Credential parameter specified - establishing new connection"
        }

        if (-not $NeedNewConnection) {
            # Use centrally determined authenticated user from Connect-LDAP
            $UsernameDisplay = $Script:LDAPContext.AuthenticatedUser
            Write-Log "[Ensure-LDAPConnection] Using existing connection: Domain=$($Script:LDAPContext.Domain), Server=$($Script:LDAPContext.Server), User=$UsernameDisplay"
        }
    }

    # Establish new connection if needed
    if ($NeedNewConnection) {
        $ServerDisplay = if ($TargetServer) { $TargetServer } else { 'auto-discovery' }
        Write-Log "[Ensure-LDAPConnection] Establishing new connection to: Domain=$TargetDomain, Server=$ServerDisplay"

        try {
            $ConnectionParams = @{}
            if ($TargetDomain) { $ConnectionParams['Domain'] = $TargetDomain }
            if ($TargetServer) { $ConnectionParams['Server'] = $TargetServer }
            if ($Credential) { $ConnectionParams['Credential'] = $Credential }

            # Pass stored client certificate for Schannel reconnection
            if ($Script:LDAPContext -and $Script:LDAPContext['ClientCertificate']) {
                $ConnectionParams['ClientCertificate'] = $Script:LDAPContext['ClientCertificate']
                $ConnectionParams['UseLDAPS'] = $true  # Schannel requires LDAPS
            }

            # Connect-LDAP returns its DomainInfo hashtable (truthy) on success and
            # $null on failure. IMPORTANT: it does NOT throw on a failed bind - it
            # displays the specific error (e.g. LDAP 49) and returns $null, leaving any
            # pre-existing $Script:LDAPContext / $Script:LdapConnection intact. We must
            # therefore check the return value: if we blindly reported success here, the
            # caller would silently operate under the STALE previous session - a
            # different identity than the explicitly requested Domain/Server/Credential.
            $NewConnection = Connect-LDAP @ConnectionParams

            if (-not $NewConnection) {
                Write-Log "[Ensure-LDAPConnection] Connection attempt failed - no valid session established (Connect-LDAP already displayed the reason)"
                return $false
            }

            # Use centrally determined authenticated user from Connect-LDAP
            $UsernameDisplay = $Script:LDAPContext.AuthenticatedUser
            Write-Log "[Ensure-LDAPConnection] Successfully connected: Domain=$($Script:LDAPContext.Domain), Server=$($Script:LDAPContext.Server), User=$UsernameDisplay"
        } catch {
            # Re-throw error from Connect-LDAP without adding wrapper
            throw
        }
    }
    return $true
}



# ----- Test-AccountActivity.ps1 -----

function Test-AccountActivity {
    <#
    .SYNOPSIS
    Filters Active Directory accounts based on activity, password age, and status criteria.

    .DESCRIPTION
    Central filter function for AD account analysis. Accepts AD objects via pipeline and outputs only those that match ALL specified criteria.

    Works like Where-Object but with intelligent AD-specific filtering logic.
    Returns the original AD object unchanged if it passes all filters.

    Filter Categories:
    - Activity: Is account actively used (based on lastLogonTimestamp)
    - Password Age: When was password last changed
    - Account Status: Enabled/Disabled, security flags
    
    Important timestamps:
    - lastLogonTimestamp: Replicated, 9-14 day latency (msDS-LogonTimeSyncInterval)
    - lastLogon: NOT replicated, DC-specific, precise

    .PARAMETER ADObject
    The AD object (user or computer) to filter. Passed via pipeline.
    Required properties depend on filters used:
    - Activity filters: lastLogonTimestamp, userAccountControl
    - Password filters: pwdLastSet
    - LastLogon filter: lastLogon

    .PARAMETER IsActive
    Filter for accounts that ARE actively used (logged in within InactiveDays).
    Requires lastLogonTimestamp property.

    .PARAMETER IsInactive
    Filter for accounts that are NOT actively used (no login within InactiveDays).
    Requires lastLogonTimestamp property.

    .PARAMETER InactiveDays
    Threshold for activity determination in days.
    Default: Uses $Script:DefaultInactiveDays (typically 90 days) set by adPEAS.
    Can be overridden per-call if needed (e.g., -InactiveDays 180 for computers).
    When specified without -IsActive or -IsInactive, implicitly enables -IsInactive.

    .PARAMETER IsEnabled
    Filter for accounts that are enabled (not disabled).

    .PARAMETER IsDisabled
    Filter for accounts that are disabled.

    .PARAMETER NeverLoggedIn
    Filter for accounts that have never logged in (no lastLogonTimestamp).

    .PARAMETER HasLoggedIn
    Filter for accounts that have logged in at least once.

    .PARAMETER PasswordAgeDays
    Filter for accounts with password older than N days (exclusive: > not >=).

    .PARAMETER PasswordChangedInYear
    Filter for accounts with password changed in specific year (e.g., 2020).

    .PARAMETER PasswordChangedBeforeYear
    Filter for accounts with password changed BEFORE specific year (exclusive: year < value).

    .PARAMETER PasswordChangedAfterYear
    Filter for accounts with password changed AFTER specific year (exclusive: year > value).

    .PARAMETER PasswordNeverSet
    Filter for accounts where password was never set.

    .PARAMETER PasswordNeverExpires
    Filter for accounts with PASSWORD_NEVER_EXPIRES flag set.

    .PARAMETER PasswordNotRequired
    Filter for accounts with PASSWORD_NOT_REQUIRED flag set.

    .PARAMETER IncludeDetails
    If specified, adds ActivityDetails property to output object with analysis results.
    Useful for debugging or detailed reporting.

    .EXAMPLE
    # Get all users with password from before 2016
    Get-DomainUser -Properties lastLogonTimestamp,pwdLastSet,userAccountControl |
        Test-AccountActivity -PasswordChangedBeforeYear 2016

    .EXAMPLE
    # Get enabled users inactive for 2 years
    Get-DomainUser -Properties lastLogonTimestamp,userAccountControl |
        Test-AccountActivity -IsEnabled -IsInactive -InactiveDays 730

    .EXAMPLE
    # Get active users with password older than 5 years (security risk!)
    Get-DomainUser -Properties lastLogonTimestamp,pwdLastSet,userAccountControl |
        Test-AccountActivity -IsActive -PasswordAgeDays 1825

    .EXAMPLE
    # Get accounts that never logged in
    Get-DomainUser -Properties lastLogonTimestamp,userAccountControl |
        Test-AccountActivity -NeverLoggedIn

    .EXAMPLE
    # Get enabled accounts with PASSWORD_NEVER_EXPIRES
    Get-DomainUser -Properties lastLogonTimestamp,userAccountControl |
        Test-AccountActivity -IsEnabled -PasswordNeverExpires

    .EXAMPLE
    # Get inactive computers (no login in 180 days)
    Get-DomainComputer -Properties lastLogonTimestamp,userAccountControl |
        Test-AccountActivity -IsInactive -InactiveDays 180

    .EXAMPLE
    # Get users with password from exactly 2020
    Get-DomainUser -Properties pwdLastSet,userAccountControl |
        Test-AccountActivity -PasswordChangedInYear 2020

    .EXAMPLE
    # Combine multiple filters: Enabled + Active + Old Password + PasswordNeverExpires
    Get-DomainUser -Properties lastLogonTimestamp,pwdLastSet,userAccountControl |
        Test-AccountActivity -IsEnabled -IsActive -PasswordAgeDays 3650 -PasswordNeverExpires

    .OUTPUTS
    Original AD object if it passes all filters, nothing otherwise.
    With -IncludeDetails: Adds ActivityDetails property with analysis results.

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, ValueFromPipeline=$true)]
        [object]$ADObject,

        # Activity Filters
        [Parameter(Mandatory=$false)]
        [switch]$IsActive,

        [Parameter(Mandatory=$false)]
        [switch]$IsInactive,

        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 0,  # 0 = use $Script:DefaultInactiveDays

        # Account Status Filters
        [Parameter(Mandatory=$false)]
        [switch]$IsEnabled,

        [Parameter(Mandatory=$false)]
        [switch]$IsDisabled,

        [Parameter(Mandatory=$false)]
        [switch]$NeverLoggedIn,

        [Parameter(Mandatory=$false)]
        [switch]$HasLoggedIn,

        # Password Age Filters
        [Parameter(Mandatory=$false)]
        [int]$PasswordAgeDays = 0,

        [Parameter(Mandatory=$false)]
        [int]$PasswordChangedInYear = 0,

        [Parameter(Mandatory=$false)]
        [int]$PasswordChangedBeforeYear = 0,

        [Parameter(Mandatory=$false)]
        [int]$PasswordChangedAfterYear = 0,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordNeverSet,

        # Security Flag Filters
        [Parameter(Mandatory=$false)]
        [switch]$PasswordNeverExpires,

        [Parameter(Mandatory=$false)]
        [switch]$PasswordNotRequired,

        # Output Options
        [Parameter(Mandatory=$false)]
        [switch]$IncludeDetails
    )

    begin {
        # ===== Validate mutually exclusive parameters =====
        if ($IsActive -and $IsInactive) {
            throw "Parameters -IsActive and -IsInactive are mutually exclusive"
        }
        if ($IsEnabled -and $IsDisabled) {
            throw "Parameters -IsEnabled and -IsDisabled are mutually exclusive"
        }
        if ($NeverLoggedIn -and $HasLoggedIn) {
            throw "Parameters -NeverLoggedIn and -HasLoggedIn are mutually exclusive"
        }
    }

    process {
        # ===== Resolve InactiveDays from global constant if not explicitly set =====
        $effectiveInactiveDays = if ($InactiveDays -gt 0) {
            $InactiveDays
        } elseif ($Script:DefaultInactiveDays) {
            $Script:DefaultInactiveDays
        } else {
            90  # Fallback if no global constant exists
        }

        # ===== Implicit -IsInactive when -InactiveDays is explicitly provided =====
        if ($InactiveDays -gt 0 -and -not $IsActive -and -not $IsInactive) {
            $IsInactive = $true
        }

        # ===== Parse userAccountControl =====
        $uacValue = $ADObject.userAccountControl
        $uac = 0

        if ($uacValue -is [array]) {
            $uacValue = $uacValue[0]
        }

        if ($null -ne $uacValue) {
            if ($uacValue -is [int] -or $uacValue -is [long]) {
                $uac = [int]$uacValue
            }
            elseif ($uacValue -is [string]) {
                $parsed = 0
                if ([int]::TryParse($uacValue, [ref]$parsed)) {
                    $uac = $parsed
                }
            }
        }

        # ===== Determine account state =====
        $accountEnabled = -not (($uac -band 0x0002) -eq 0x0002)
        $hasPasswordNeverExpires = ($uac -band 0x10000) -eq 0x10000
        $hasPasswordNotRequired = ($uac -band 0x0020) -eq 0x0020

        # ===== Check enabled/disabled filter =====
        if ($IsEnabled -and -not $accountEnabled) {
            return  # Filter out: wanted enabled, but account is disabled
        }
        if ($IsDisabled -and $accountEnabled) {
            return  # Filter out: wanted disabled, but account is enabled
        }

        # ===== Check security flag filters =====
        if ($PasswordNeverExpires -and -not $hasPasswordNeverExpires) {
            return  # Filter out: wanted PasswordNeverExpires, but flag not set
        }
        if ($PasswordNotRequired -and -not $hasPasswordNotRequired) {
            return  # Filter out: wanted PasswordNotRequired, but flag not set
        }

        # ===== Parse lastLogonTimestamp =====
        $lastLogonTimestamp = $ADObject.lastLogonTimestamp
        $lastActivityDate = $null
        $hasEverLoggedIn = $false

        if ($lastLogonTimestamp) {
            if ($lastLogonTimestamp -is [array]) {
                $lastLogonTimestamp = $lastLogonTimestamp[0]
            }
            $lastActivityDate = Convert-ADTimestamp -Value $lastLogonTimestamp
            if ($lastActivityDate) {
                $hasEverLoggedIn = $true
            }
        }

        # ===== Check never logged in / has logged in filter =====
        if ($NeverLoggedIn -and $hasEverLoggedIn) {
            return  # Filter out: wanted never logged in, but has logged in
        }
        if ($HasLoggedIn -and -not $hasEverLoggedIn) {
            return  # Filter out: wanted has logged in, but never logged in
        }

        # ===== Check activity filter =====
        if ($IsActive -or $IsInactive) {
            # Accounts that never logged in (no lastLogonTimestamp) are NOT "inactive" -
            # they are "never used". Inactive means "was active once but not recently".
            # Never-logged-in accounts should be excluded from both IsActive and IsInactive.
            if (-not $hasEverLoggedIn) {
                if ($IsActive) {
                    return  # Filter out: never logged in, not active
                }
                if ($IsInactive) {
                    return  # Filter out: never logged in, not inactive either (use -NeverLoggedIn)
                }
            }

            $cutoffDate = (Get-Date).AddDays(-$effectiveInactiveDays)
            $isAccountActive = $lastActivityDate -gt $cutoffDate

            if ($IsActive -and -not $isAccountActive) {
                return  # Filter out: wanted active, but inactive
            }
            if ($IsInactive -and $isAccountActive) {
                return  # Filter out: wanted inactive, but active
            }
        }

        # ===== Parse pwdLastSet =====
        $pwdLastSet = $ADObject.pwdLastSet
        $passwordSetDate = $null
        $passwordYear = $null
        $daysSincePasswordChange = $null
        $passwordWasNeverSet = $true

        if ($pwdLastSet) {
            if ($pwdLastSet -is [array]) {
                $pwdLastSet = $pwdLastSet[0]
            }
            $passwordSetDate = Convert-ADTimestamp -Value $pwdLastSet
            if ($passwordSetDate) {
                $passwordWasNeverSet = $false
                $passwordYear = $passwordSetDate.Year
                $daysSincePasswordChange = [math]::Floor(((Get-Date) - $passwordSetDate).TotalDays)
            }
        }

        # ===== Check password never set filter =====
        if ($PasswordNeverSet -and -not $passwordWasNeverSet) {
            return  # Filter out: wanted password never set, but it was set
        }

        # ===== Check password age filters =====
        if ($PasswordAgeDays -gt 0) {
            # Use < (not <=) so -PasswordAgeDays 90 includes passwords exactly 90 days old
            if ($passwordWasNeverSet -or $daysSincePasswordChange -lt $PasswordAgeDays) {
                return  # Filter out: password not old enough (or never set)
            }
        }

        if ($PasswordChangedInYear -gt 0) {
            if ($passwordWasNeverSet -or $passwordYear -ne $PasswordChangedInYear) {
                return  # Filter out: password not from target year
            }
        }

        if ($PasswordChangedBeforeYear -gt 0) {
            if ($passwordWasNeverSet -or $passwordYear -ge $PasswordChangedBeforeYear) {
                return  # Filter out: password not before target year
            }
        }

        if ($PasswordChangedAfterYear -gt 0) {
            if ($passwordWasNeverSet -or $passwordYear -le $PasswordChangedAfterYear) {
                return  # Filter out: password not after target year
            }
        }

        # ===== All filters passed - output the object =====
        if ($IncludeDetails) {
            # Add analysis details to the object
            $details = [PSCustomObject]@{
                IsEnabled = $accountEnabled
                IsActive = if ($hasEverLoggedIn) { $lastActivityDate -gt (Get-Date).AddDays(-$effectiveInactiveDays) } else { $false }
                LastActivity = $lastActivityDate
                DaysSinceActivity = if ($lastActivityDate) { [math]::Floor(((Get-Date) - $lastActivityDate).TotalDays) } else { $null }
                NeverLoggedIn = -not $hasEverLoggedIn
                PasswordLastSet = $passwordSetDate
                PasswordYear = $passwordYear
                DaysSincePasswordChange = $daysSincePasswordChange
                PasswordNeverSet = $passwordWasNeverSet
                HasPasswordNeverExpires = $hasPasswordNeverExpires
                HasPasswordNotRequired = $hasPasswordNotRequired
            }

            # Add property to object
            # Note: Add-Member modifies the original object in-place, -PassThru returns it for pipeline
            $ADObject | Add-Member -NotePropertyName "ActivityDetails" -NotePropertyValue $details -PassThru
        }
        else {
            # Return original object unchanged
            $ADObject
        }
    }
}

function Convert-ADTimestamp {
    <#
    .SYNOPSIS
    Converts various AD timestamp formats to DateTime.

    .DESCRIPTION
    Helper function to handle different timestamp formats from AD:
    - DateTime objects (pass through)
    - FileTime integers (Windows file time)
    - String representations of FileTime or DateTime

    .PARAMETER Value
    The timestamp value to convert.

    .OUTPUTS
    DateTime object or $null if conversion fails.
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Value
    )

    try {
        if ($Value -is [DateTime]) {
            return $Value
        }
        elseif ($Value -is [long] -or $Value -is [int]) {
            # FileTime integer - check for "never" values
            if ($Value -le 0 -or $Value -eq 9223372036854775807) {
                return $null
            }
            return [DateTime]::FromFileTime([long]$Value)
        }
        elseif ($Value -is [string]) {
            # Try parsing as long (FileTime) first
            $parsed = 0L
            if ([long]::TryParse($Value, [ref]$parsed)) {
                if ($parsed -le 0 -or $parsed -eq 9223372036854775807) {
                    return $null
                }
                return [DateTime]::FromFileTime($parsed)
            }

            # Try parsing as DateTime string
            $parsedDate = [DateTime]::MinValue
            if ([DateTime]::TryParse($Value, [ref]$parsedDate)) {
                return $parsedDate
            }
        }
    }
    catch {
        Write-Log "[Convert-ADTimestamp] Error converting timestamp: $_"
    }

    return $null
}



# ----- Invoke-SMBAccess.ps1 -----

<#
.SYNOPSIS
    Executes scriptblock with SMB share access using credentials.

.DESCRIPTION
    Universal helper function for authenticated SMB/CIFS share access.

    Features:
    - Automatic credential handling (uses $Script:LDAPCredential or custom credentials)
    - PSDrive mounting for secure credential handling
    - Automatic SYSVOL/NETLOGON path detection
    - Retry logic for transient network errors
    - Comprehensive error handling and logging
    - Automatic cleanup (PSDrive removal)

    Use Cases:
    - SYSVOL access (GPO files, Registry.pol, GptTmpl.inf)
    - NETLOGON access (logon scripts)
    - Administrative shares (C$, ADMIN$)
    - Custom file shares

.PARAMETER ScriptBlock
    The code block to execute with SMB access.

.PARAMETER UNCPath
    Explicit UNC path to the share (e.g., "\\server\share" or "\\dc\C$").
    If not specified, defaults to SYSVOL share of current domain.

.PARAMETER Credential
    PSCredential object for authentication.
    If not specified, credential source is determined automatically:
    1. $Script:LDAPCredential (legacy support)
    2. $Script:LDAPContext['Credential'] - ONLY for SimpleBind sessions
       (Kerberos sessions use PTT, so SMB auth works automatically)
    3. Current user context (no explicit credentials)

.PARAMETER Description
    Optional description for logging/debugging purposes.
    Helps identify what operation is being performed.

.PARAMETER RetryCount
    Number of retry attempts on transient network errors.
    Default: 2

.PARAMETER Timeout
    Timeout in seconds for PSDrive mount operations.
    Default: 5 seconds (sufficient for LAN/VPN, quick failure on unreachable hosts)

.PARAMETER ErrorHandling
    How to handle errors:
    - Silent: Suppress errors, return $null (default)
    - Warn: Write warnings, continue execution
    - Stop: Throw errors, stop execution

.EXAMPLE
    # Basic usage - SYSVOL access with auto-credentials
    Invoke-SMBAccess -ScriptBlock {
        Get-ChildItem "\\$($Script:LDAPContext.Server)\SYSVOL\*" -Recurse
    }

.EXAMPLE
    # Explicit UNC path with description
    Invoke-SMBAccess -UNCPath "\\dc01\SYSVOL" -Description "Scanning GPO files" -ScriptBlock {
        Get-ChildItem $args[0] -Recurse -Filter "*.xml"
    }

.EXAMPLE
    # Custom credentials for administrative share
    $cred = Get-Credential
    Invoke-SMBAccess -UNCPath "\\server\C$" -Credential $cred -ScriptBlock {
        Get-ChildItem "\\server\C$\Windows\Temp"
    }

.EXAMPLE
    # With retry logic and custom timeout
    Invoke-SMBAccess -UNCPath "\\slowserver\share" -RetryCount 5 -Timeout 60 -ScriptBlock {
        Get-Content "\\slowserver\share\file.txt"
    }

.OUTPUTS
    Output of the passed scriptblock

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# ============================================================================
# SMB Share Access Cache
# ============================================================================
# Caches failed SMB share access attempts to avoid repeated timeouts.
# When a share (e.g., \\server\SYSVOL) fails, all subsequent access attempts
# to the same share return immediately instead of waiting for another timeout.
#
# Reset with: Reset-SMBShareAccessCache (called automatically by Disconnect-adPEAS)

if (-not $Script:SMBShareAccessCache) {
    $Script:SMBShareAccessCache = @{}
}

# ============================================================================
# SYSVOL File Cache
# ============================================================================
# Caches the result of a single recursive Get-ChildItem on the SYSVOL share.
# The first caller triggers the enumeration; all subsequent callers filter
# the cached FileInfo array locally - no additional SMB round-trips.
#
# Reset with: Reset-SYSVOLFileCache (called automatically by Disconnect-adPEAS)

if (-not $Script:SYSVOLFileCache) {
    $Script:SYSVOLFileCache = $null  # $null = not yet populated
}

<#
.SYNOPSIS
    Resets the SYSVOL file listing cache.
.DESCRIPTION
    Clears the cached SYSVOL file listing.
    Called automatically by Disconnect-adPEAS when a session ends.
#>
function Reset-SYSVOLFileCache {
    [CmdletBinding()]
    param()
    $Script:SYSVOLFileCache = $null
    Write-Log "[Reset-SYSVOLFileCache] Cache cleared"
}

<#
.SYNOPSIS
    Returns SYSVOL files matching the specified filter, using a cache to avoid repeated SMB traversals.

.DESCRIPTION
    On the first call, performs a single recursive Get-ChildItem on the SYSVOL share
    and caches ALL file objects. Subsequent calls filter the cached list locally.

    This eliminates redundant SMB directory traversals when multiple Check modules
    each need to search SYSVOL for different file types.

.PARAMETER Filter
    Filename pattern(s) to match. Supports wildcards.
    Examples: "*.xml", "GptTmpl.inf", @("scripts.ini", "psscripts.ini")

.PARAMETER SYSVOLPath
    Base path to search. Defaults to \\<Server>\SYSVOL\<Domain>\Policies.
    If not specified, auto-detects from LDAPContext.

.OUTPUTS
    Array of FileInfo objects matching the filter.
    Returns empty array if SYSVOL is not accessible or no files match.

.EXAMPLE
    $xmlFiles = Get-CachedSYSVOLFiles -Filter "*.xml"

.EXAMPLE
    $iniFiles = Get-CachedSYSVOLFiles -Filter @("scripts.ini", "psscripts.ini")
#>
function Get-CachedSYSVOLFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Filter,

        [Parameter(Mandatory=$false)]
        [string]$SYSVOLPath
    )

    # Auto-detect SYSVOL path if not provided
    if (-not $SYSVOLPath) {
        if (-not $Script:LDAPContext -or -not $Script:LDAPContext.Server) {
            Write-Log "[Get-CachedSYSVOLFiles] No LDAPContext available"
            return @()
        }
        $dcServer = $Script:LDAPContext.Server
        $domainFQDN = $Script:LDAPContext.Domain
        # Cache from domain folder (SYSVOL root is a DFS junction that Get-ChildItem may not traverse)
        $SYSVOLPath = "\\$dcServer\SYSVOL\$domainFQDN"
    }

    # Build cache on first access
    if ($null -eq $Script:SYSVOLFileCache) {
        Write-Log "[Get-CachedSYSVOLFiles] Building SYSVOL file cache from: $SYSVOLPath"

        if (-not (Test-Path $SYSVOLPath)) {
            Write-Log "[Get-CachedSYSVOLFiles] SYSVOL path not accessible: $SYSVOLPath"
            $Script:SYSVOLFileCache = @()
            return @()
        }

        # Enumerate per top-level subdirectory (typically Policies/{GUID} folders) with progress
        # This avoids a single blocking Get-ChildItem -Recurse over the entire SYSVOL tree
        $topLevelDirs = @(Get-ChildItem -Force -Path $SYSVOLPath -Directory -ErrorAction SilentlyContinue)
        $allFiles = [System.Collections.Generic.List[object]]::new()

        if ($topLevelDirs.Count -gt 0) {
            # Count total subdirectories for progress (Policies folder typically has one subdir per GPO)
            $subDirs = [System.Collections.Generic.List[object]]::new()
            foreach ($topDir in $topLevelDirs) {
                $childDirs = @(Get-ChildItem -Force -Path $topDir.FullName -Directory -ErrorAction SilentlyContinue)
                if ($childDirs.Count -gt 0) {
                    foreach ($cd in $childDirs) { $subDirs.Add($cd) }
                } else {
                    # Top-level dir has no subdirs (e.g., Scripts folder) - treat as single unit
                    $subDirs.Add($topDir)
                }
            }

            $totalDirs = $subDirs.Count
            $currentDirIndex = 0
            $showProgress = $totalDirs -gt $Script:ProgressThreshold

            foreach ($dir in $subDirs) {
                $currentDirIndex++
                if ($showProgress) {
                    Show-Progress -Activity "Building SYSVOL file cache" -Current $currentDirIndex -Total $totalDirs -ObjectName $dir.Name
                }
                $dirFiles = @(Get-ChildItem -Force -Path $dir.FullName -Recurse -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer })
                foreach ($f in $dirFiles) { $allFiles.Add($f) }
            }

            if ($showProgress) {
                Show-Progress -Activity "Building SYSVOL file cache" -Completed
            }

            # Also get files directly in the top-level SYSVOL path (not in subdirectories)
            $rootFiles = @(Get-ChildItem -Force -Path $SYSVOLPath -File -ErrorAction SilentlyContinue)
            foreach ($f in $rootFiles) { $allFiles.Add($f) }
        } else {
            # No subdirectories - fall back to flat recursive scan
            $allFiles = [System.Collections.Generic.List[object]]::new(
                @(Get-ChildItem -Force -Path $SYSVOLPath -Recurse -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer })
            )
        }

        $Script:SYSVOLFileCache = @($allFiles)
        Write-Log "[Get-CachedSYSVOLFiles] Cached $($Script:SYSVOLFileCache.Count) files from SYSVOL"
    }

    # Filter cached results locally
    $filterArray = @($Filter)
    $results = @($Script:SYSVOLFileCache | Where-Object {
        $fileName = $_.Name
        $matched = $false
        foreach ($f in $filterArray) {
            if ($fileName -like $f) {
                $matched = $true
                break
            }
        }
        $matched
    })

    Write-Log "[Get-CachedSYSVOLFiles] Filter '$($filterArray -join "', '")' matched $($results.Count) file(s)"
    return $results
}

<#
.SYNOPSIS
    Returns cached file content from SYSVOL, reading from SMB only on first access.
.DESCRIPTION
    Provides a content-level cache for SYSVOL files (e.g., GptTmpl.inf).
    Multiple check modules that read the same file per GPO will only trigger
    one SMB read - subsequent calls return the cached content.

    This complements Get-CachedSYSVOLFiles (which caches directory listings)
    by also caching the actual file content on demand.
.PARAMETER Path
    Full UNC path to the file to read.
.OUTPUTS
    [string] Raw file content, or $null if file does not exist.
#>
function Get-CachedSYSVOLContent {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path
    )

    if (-not $Script:SYSVOLContentCache) {
        $Script:SYSVOLContentCache = @{}
    }

    $cacheKey = $Path.ToLowerInvariant()

    if ($Script:SYSVOLContentCache.ContainsKey($cacheKey)) {
        return $Script:SYSVOLContentCache[$cacheKey]
    }

    if (-not (Test-Path $Path)) {
        return $null
    }

    $content = Get-Content -Path $Path -Raw -ErrorAction SilentlyContinue
    if ($null -ne $content) {
        $Script:SYSVOLContentCache[$cacheKey] = $content
    }

    return $content
}

<#
.SYNOPSIS
    Resets the SMB share access cache.
.DESCRIPTION
    Clears the cache of failed SMB share access attempts,
    the SYSVOL file listing cache, and the SYSVOL content cache.
    Called automatically by Disconnect-adPEAS when a session ends.
    Can also be called manually to retry previously failed shares.
#>
function Reset-SMBShareAccessCache {
    [CmdletBinding()]
    param()
    $Script:SMBShareAccessCache = @{}
    $Script:SYSVOLContentCache = @{}
    Write-Log "[Reset-SMBShareAccessCache] Cache cleared"
}

<#
.SYNOPSIS
    Tests if SYSVOL is accessible based on cached access results.
.DESCRIPTION
    Returns $true if SYSVOL has not been marked as inaccessible in the cache.
    Returns $false if a previous SYSVOL access attempt failed.
    Returns $null if SYSVOL access has not been attempted yet.

    Use this in Check modules to skip SYSVOL-dependent logic early
    without incurring another SMB timeout.
.EXAMPLE
    $sysvolStatus = Test-SysvolAccessible
    if ($sysvolStatus -eq $false) {
        Show-Line "Skipping - SYSVOL not accessible" -Class Hint
        return
    }
#>
function Test-SysvolAccessible {
    [CmdletBinding()]
    param()

    if (-not $Script:LDAPContext -or -not $Script:LDAPContext.Server) {
        return $null  # No session - unknown
    }

    # Build the SYSVOL share key the same way Invoke-SMBAccess does
    $smbServer = $Script:LDAPContext.Server
    $kerberosUsed = $Script:LDAPContext['KerberosUsed']

    if (-not $kerberosUsed -and $Script:LDAPContext['DnsServer']) {
        # SimpleBind with custom DNS uses IP
        if ($Script:LDAPContext['ServerIP']) {
            $smbServer = $Script:LDAPContext['ServerIP']
        }
    }

    $shareKey = "\\$smbServer\SYSVOL".ToLower()

    if ($Script:SMBShareAccessCache.ContainsKey($shareKey)) {
        return $false  # Previously failed
    }

    return $null  # Not attempted yet (or succeeded)
}

function Invoke-SMBAccess {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [ScriptBlock]$ScriptBlock,

        [Parameter(Mandatory=$false)]
        [string]$UNCPath,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [string]$Description,

        [Parameter(Mandatory=$false)]
        [ValidateRange(0, 10)]
        [int]$RetryCount = 2,

        [Parameter(Mandatory=$false)]
        [ValidateRange(1, 300)]
        [int]$Timeout = 5,

        [Parameter(Mandatory=$false)]
        [ValidateSet('Silent', 'Warn', 'Stop')]
        [string]$ErrorHandling = 'Silent'
    )

    begin {
        $operationDesc = if ($Description) { $Description } else { "SMB access" }
        Write-Log "[Invoke-SMBAccess] Starting: $operationDesc"
    }

    process {
        $driveName = $null
        $driveMounted = $false
        $credToUse = $null

        try {
            if ($Credential) {
                $credToUse = $Credential
                Write-Log "[Invoke-SMBAccess] Using provided credentials: $($Credential.UserName)"
            }
            elseif ($Script:LDAPCredential) {
                $credToUse = $Script:LDAPCredential
                Write-Log "[Invoke-SMBAccess] Using stored credentials: $($Script:LDAPCredential.UserName)"
            }
            elseif ($Script:LDAPContext -and $Script:LDAPContext['Credential']) {
                # Check if Kerberos was used - if yes, SMB should work automatically via PTT
                if ($Script:LDAPContext['KerberosUsed']) {
                    # Kerberos session - ticket already injected into Windows session
                    # SMB will use Kerberos auth automatically, no need for explicit credentials
                    Write-Log "[Invoke-SMBAccess] Kerberos session active - SMB will use Kerberos auth automatically"
                    $credToUse = $null
                }
                else {
                    # SimpleBind session - need to use stored credentials for SMB
                    $credToUse = $Script:LDAPContext['Credential']
                    Write-Log "[Invoke-SMBAccess] SimpleBind session - using stored credentials for SMB: $($credToUse.UserName)"
                }
            }
            else {
                Write-Log "[Invoke-SMBAccess] No credentials available, using current user context"
            }

            # Determine UNC path
            $targetPath = $UNCPath

            # Validate UNC path using central validation function (security check)
            # This prevents path traversal attacks and validates host/share format
            if ($targetPath) {
                if (-not (Test-ValidUNCPath -UNCPath $targetPath)) {
                    $errorMsg = "Invalid or potentially malicious UNC path: '$targetPath'. Path traversal or invalid format detected."
                    Write-Log "[Invoke-SMBAccess] Security: $errorMsg"

                    switch ($ErrorHandling) {
                        'Warn' { Write-Warning $errorMsg; return $null }
                        'Stop' { throw $errorMsg }
                        default { return $null }
                    }
                }
            }

            if (-not $targetPath) {
                # Auto-detect SYSVOL path
                if ($Script:LDAPContext -and $Script:LDAPContext.Server) {
                    $smbServer = $Script:LDAPContext.Server
                    $kerberosUsed = $Script:LDAPContext['KerberosUsed']
                    $hostsPatched = $Script:LDAPContext['EarlyHostsPatched']

                    if ($kerberosUsed -and $hostsPatched) {
                        # Kerberos with hosts file patching - MUST use hostname for SPN matching
                        Write-Log "[Invoke-SMBAccess] Kerberos+HostsPatched mode: Using hostname for SMB (SPN matching): $smbServer"
                    }
                    elseif ($kerberosUsed) {
                        # Kerberos without hosts patching - still use hostname (system DNS should work)
                        Write-Log "[Invoke-SMBAccess] Kerberos mode: Using hostname for SMB (SPN matching): $smbServer"
                    }
                    elseif ($Script:LDAPContext['DnsServer']) {
                        # SimpleBind with custom DNS - use IP address (system DNS can't resolve)
                        $resolvedIP = $null

                        # Source 1: ServerIP (set after successful connect)
                        if ($Script:LDAPContext['ServerIP']) {
                            $resolvedIP = $Script:LDAPContext['ServerIP']
                            Write-Log "[Invoke-SMBAccess] Using cached ServerIP: $resolvedIP"
                        }
                        # Source 2: DnsCache (populated during DNS resolution)
                        elseif ($Script:LDAPContext['DnsCache'] -and $Script:LDAPContext['DnsCache'].ContainsKey($smbServer.ToLower())) {
                            $resolvedIP = $Script:LDAPContext['DnsCache'][$smbServer.ToLower()]
                            Write-Log "[Invoke-SMBAccess] Using IP from DnsCache: $resolvedIP"
                        }
                        # Source 3: Try to resolve via custom DNS
                        else {
                            $resolvedIP = Resolve-adPEASName -Name $smbServer
                            if ($resolvedIP) {
                                Write-Log "[Invoke-SMBAccess] Resolved server via custom DNS: $resolvedIP"
                            }
                        }

                        if ($resolvedIP) {
                            $smbServer = $resolvedIP
                            Write-Log "[Invoke-SMBAccess] SimpleBind+CustomDNS mode: Using IP address for SMB: $smbServer"
                        }
                        else {
                            Write-Log "[Invoke-SMBAccess] WARNING: Custom DNS configured but could not resolve $smbServer - SMB may fail"
                        }
                    }
                    else {
                        # SimpleBind without custom DNS - use hostname (system DNS works)
                        Write-Log "[Invoke-SMBAccess] SimpleBind mode: Using hostname for SMB: $smbServer"
                    }

                    $targetPath = "\\$smbServer\SYSVOL"
                    Write-Log "[Invoke-SMBAccess] Auto-detected SYSVOL path: $targetPath"
                } else {
                    $errorMsg = "No UNC path specified and cannot auto-detect SYSVOL (LDAPContext not available)"
                    Write-Log "[Invoke-SMBAccess] $errorMsg"

                    switch ($ErrorHandling) {
                        'Warn' { Write-Warning $errorMsg }
                        'Stop' { throw $errorMsg }
                    }

                    # Fallback: Execute without path context
                    return & $ScriptBlock
                }
            }
            else {
                # If UNC path is provided but contains a hostname and custom DNS is active, may need to resolve it but for Kerberos, we MUST keep the hostname for SPN matching!
                $kerberosUsed = $Script:LDAPContext -and $Script:LDAPContext['KerberosUsed']

                if (-not $kerberosUsed -and $Script:LDAPContext -and $Script:LDAPContext['DnsServer'] -and $UNCPath -match '^\\\\([^\\]+)\\') {
                    # SimpleBind with custom DNS - need to convert hostname to IP
                    $uncHost = $Matches[1]
                    # Check if it's not already an IP address
                    $ipTest = $null
                    if (-not [System.Net.IPAddress]::TryParse($uncHost, [ref]$ipTest)) {
                        # Try to resolve using cached IP or DNS lookup
                        $resolvedIP = $null

                        # Source 1: DnsCache (use lowercase key for case-insensitive lookup)
                        if ($Script:LDAPContext['DnsCache'] -and $Script:LDAPContext['DnsCache'].ContainsKey($uncHost.ToLower())) {
                            $resolvedIP = $Script:LDAPContext['DnsCache'][$uncHost.ToLower()]
                        }
                        # Source 2: ServerIP (if hostname matches server or domain, case-insensitive)
                        elseif ($Script:LDAPContext['ServerIP'] -and ($uncHost.ToLower() -eq $Script:LDAPContext.Server.ToLower() -or $uncHost.ToLower() -eq $Script:LDAPContext.Domain.ToLower())) {
                            $resolvedIP = $Script:LDAPContext['ServerIP']
                        }
                        # Source 3: Try to resolve via custom DNS
                        else {
                            $resolvedIP = Resolve-adPEASName -Name $uncHost
                        }

                        if ($resolvedIP) {
                            $targetPath = $UNCPath -replace "^\\\\[^\\]+\\", "\\$resolvedIP\"
                            Write-Log "[Invoke-SMBAccess] SimpleBind: Converted hostname to IP in UNC path: $uncHost -> $resolvedIP"
                        }
                    }
                }
                elseif ($kerberosUsed) {
                    # Kerberos - keep hostname as-is for SPN matching
                    Write-Log "[Invoke-SMBAccess] Kerberos: Keeping hostname in UNC path for SPN matching"
                }
            }

            # Check share access cache - skip if this share previously failed
            # Extract share root (\\server\share) for cache lookup
            $shareKey = $null
            if ($targetPath -match '^(\\\\[^\\]+\\[^\\]+)') {
                $shareKey = $Matches[1].ToLower()
            }
            if ($shareKey -and $Script:SMBShareAccessCache.ContainsKey($shareKey)) {
                $cachedError = $Script:SMBShareAccessCache[$shareKey]
                Write-Log "[Invoke-SMBAccess] SKIPPED (cached failure): $operationDesc - Share '$shareKey' previously failed: $cachedError"

                switch ($ErrorHandling) {
                    'Warn' { Write-Warning "SMB access skipped (previously failed): $cachedError"; return $null }
                    'Stop' { throw "SMB access skipped (previously failed): $cachedError" }
                    default { return $null }
                }
            }

            # Execute with PSDrive mounting (secure credential handling)
            $attempt = 0
            $success = $false
            $lastError = $null

            # Determine if we should use runspace for timeout control
            # For Kerberos sessions, we MUST NOT use runspace because:
            # 1. Runspace is an isolated execution context
            # 2. Kerberos tickets in LSA cache are per-logon-session but runspace doesn't inherit proper context
            # 3. Direct mount in main process uses the injected Kerberos ticket correctly
            $kerberosSession = $Script:LDAPContext -and $Script:LDAPContext['KerberosUsed']

            if ($kerberosSession) {
                Write-Log "[Invoke-SMBAccess] Kerberos session detected - using direct mount (no runspace) to preserve ticket context"
            }

            while (-not $success -and $attempt -le $RetryCount) {
                $attempt++

                if ($attempt -gt 1) {
                    Write-Log "[Invoke-SMBAccess] Retry attempt $attempt of $RetryCount"
                    Start-Sleep -Seconds 2
                }

                try {
                    # PSDrive mounting for secure credential handling
                    $driveName = "adPEAS_SMB_$(Get-Random -Minimum 1000 -Maximum 9999)"

                    Write-Log "[Invoke-SMBAccess] Mounting PSDrive: $targetPath as ${driveName}:"

                    if ($kerberosSession -or $credToUse) {
                        # Direct mount in main process for:
                        # 1. Kerberos sessions (preserve ticket context from LSA cache)
                        # 2. Sessions with explicit credentials (credential object works in main process)
                        try {
                            if ($credToUse) {
                                Write-Log "[Invoke-SMBAccess] Direct mount with credentials"
                                New-PSDrive -Name $driveName -PSProvider FileSystem -Root $targetPath -Credential $credToUse -Scope Script -ErrorAction Stop | Out-Null
                            } else {
                                # Kerberos - no credentials needed, ticket in LSA cache is used automatically
                                Write-Log "[Invoke-SMBAccess] Direct mount with Kerberos (ticket from LSA cache)"
                                New-PSDrive -Name $driveName -PSProvider FileSystem -Root $targetPath -Scope Script -ErrorAction Stop | Out-Null
                            }
                            $driveMounted = $true
                            Write-Log "[Invoke-SMBAccess] PSDrive mounted successfully (direct)"

                            # Execute scriptblock
                            & $ScriptBlock $targetPath
                            $success = $true
                        } catch {
                            throw $_.Exception.Message
                        }
                    } else {
                        # Use runspace for timeout control when no credentials and no Kerberos
                        # This is for current user context where we want timeout protection
                        try {
                            # Mount PSDrive with timeout using runspace
                            # Note: Runspace provides true timeout control for slow/unreachable SMB targets
                            $runspace = [runspacefactory]::CreateRunspace()
                            $runspace.Open()

                            $powershell = [powershell]::Create()
                            $powershell.Runspace = $runspace

                            # Build the script dynamically
                            $scriptText = @"
param(`$driveName, `$targetPath)
try {
    New-PSDrive -Name `$driveName -PSProvider FileSystem -Root `$targetPath -Scope Global -ErrorAction Stop | Out-Null
    return @{ Success = `$true; Error = `$null }
} catch {
    return @{ Success = `$false; Error = `$_.Exception.Message }
}
"@
                            $null = $powershell.AddScript($scriptText)
                            $null = $powershell.AddParameter('driveName', $driveName)
                            $null = $powershell.AddParameter('targetPath', $targetPath)

                            $asyncResult = $powershell.BeginInvoke()

                            # Wait with actual timeout
                            $timeoutMs = $Timeout * 1000
                            $completed = $asyncResult.AsyncWaitHandle.WaitOne($timeoutMs)

                            if ($completed) {
                                # Operation completed within timeout
                                $result = $powershell.EndInvoke($asyncResult)

                                if ($result -and $result.Success) {
                                    $driveMounted = $true
                                    Write-Log "[Invoke-SMBAccess] PSDrive mounted successfully (runspace)"

                                    # Execute scriptblock
                                    & $ScriptBlock $targetPath
                                } else {
                                    $errorMsg = if ($result -and $result.Error) { $result.Error } else { "Unknown error during PSDrive mount" }
                                    throw $errorMsg
                                }
                            } else {
                                # True timeout - operation did not complete
                                Write-Log "[Invoke-SMBAccess] PSDrive mount timeout after $Timeout seconds - aborting runspace"
                                throw "PSDrive mount timeout after $Timeout seconds (SMB connection could not be established)"
                            }
                        } finally {
                            # Cleanup runspace resources
                            if ($powershell) {
                                $powershell.Stop()
                                $powershell.Dispose()
                            }
                            if ($runspace) {
                                $runspace.Close()
                                $runspace.Dispose()
                            }
                        }

                        $success = $true
                    }

                } catch {
                    $lastError = $_
                    Write-Log "[Invoke-SMBAccess] Error on attempt ${attempt}: $_"

                    # Check if error is retryable using central error code module
                    $errorInfo = Get-ExceptionErrorInfo -Exception $_.Exception -Context "SMB"
                    Write-Log "[Invoke-SMBAccess] Error analysis: $($errorInfo.Name) - $($errorInfo.Message) (Retryable: $($errorInfo.IsRetryable))"

                    if (-not $errorInfo.IsRetryable -or $attempt -gt $RetryCount) {
                        # Non-retryable error or max retries reached
                        throw
                    }
                }
            }

            if (-not $success) {
                throw $lastError
            }

        } catch {
            $errorMsg = "SMB access failed: $_"
            Write-Log "[Invoke-SMBAccess] $errorMsg"

            # Cache the failed share to prevent repeated timeout attempts
            if ($shareKey) {
                $Script:SMBShareAccessCache[$shareKey] = [string]$_
                Write-Log "[Invoke-SMBAccess] Cached failed share: $shareKey"
            }

            switch ($ErrorHandling) {
                'Silent' {
                    Write-Log "[Invoke-SMBAccess] Error suppressed (Silent mode)"
                    return $null
                }
                'Warn' {
                    Write-Warning $errorMsg
                    return $null
                }
                'Stop' {
                    throw $errorMsg
                }
            }

        } finally {
            # Cleanup: Close any open progress bars left by the scriptblock (e.g., on exception)
            if ($Script:LastProgressUpdate -and $Script:LastProgressUpdate.Count -gt 0) {
                foreach ($activityKey in @($Script:LastProgressUpdate.Keys)) {
                    try { Write-Progress -Activity $activityKey -Completed } catch { }
                }
                $Script:LastProgressUpdate = @{}
            }

            # Cleanup: Remove PSDrive if mounted
            if ($driveMounted -and $driveName) {
                try {
                    Write-Log "[Invoke-SMBAccess] Removing PSDrive ${driveName}:"
                    Remove-PSDrive -Name $driveName -Force -ErrorAction SilentlyContinue
                } catch {
                    Write-Log "[Invoke-SMBAccess] Failed to remove PSDrive: $_"
                }
            }
        }
    }

    end {
        Write-Log "[Invoke-SMBAccess] Completed: $operationDesc"
    }
}



# ----- Show-Progress.ps1 -----

<#
.SYNOPSIS
    Displays progress for long-running operations in Check modules.

.DESCRIPTION
    Unified progress indicator for Check modules processing large object counts.
    Automatically throttles updates to minimize performance impact.

    Features:
    - Automatic throttling (max 4 updates/sec, 250ms interval)
    - Percentage calculation
    - Optional object name display
    - Automatic cleanup on completion
    - Centralized threshold: $Script:ProgressThreshold (default: 30 items)

.PARAMETER Activity
    Activity name (e.g., "Checking user owners")

.PARAMETER Current
    Current item number (1-based)

.PARAMETER Total
    Total item count

.PARAMETER ObjectName
    Optional: Name of current object being processed

.PARAMETER MinInterval
    Minimum milliseconds between updates (default: 250ms = 4 updates/sec)

.PARAMETER Completed
    Switch to clear the progress bar

.EXAMPLE
    Show-Progress -Activity "Checking owners" -Current 34 -Total 17743
    Displays: "Testing 34 of 17743 (0.2%)"

.EXAMPLE
    Show-Progress -Activity "Testing accounts" -Current 100 -Total 5000 -ObjectName "john.doe"
    Displays: "Testing 100 of 5000 - john.doe (2%)"

.EXAMPLE
    Show-Progress -Activity "Processing users" -Completed
    Clears the progress bar

.EXAMPLE
    # Check if progress should be shown
    if ($totalCount -gt $Script:ProgressThreshold) {
        Show-Progress -Activity "Processing" -Current $i -Total $totalCount -ObjectName $item.Name
    }

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Performance: <0.5% overhead with throttling
    Threshold: Use $Script:ProgressThreshold (default: 30) for consistency
#>

# Global progress threshold - minimum items before showing progress
if (-not $Script:ProgressThreshold) {
    $Script:ProgressThreshold = 30
}

function Show-Progress {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Activity = "Processing",

        [Parameter(Mandatory=$false)]
        [int]$Current = 0,

        [Parameter(Mandatory=$false)]
        [int]$Total = 0,

        [Parameter(Mandatory=$false)]
        [string]$ObjectName,

        [Parameter(Mandatory=$false)]
        [int]$MinInterval = 250,

        [Parameter(Mandatory=$false)]
        [switch]$Completed
    )

    # Progress throttling: Track last update time to avoid performance impact
    if (-not $Script:LastProgressUpdate) {
        $Script:LastProgressUpdate = @{}
    }

    $activityKey = $Activity

    if ($Completed) {
        # Clear progress bar
        Write-Progress -Activity $Activity -Completed
        if ($Script:LastProgressUpdate.ContainsKey($activityKey)) {
            $Script:LastProgressUpdate.Remove($activityKey)
        }
        return
    }

    # Skip if no total or invalid values
    if ($Total -eq 0 -or $Current -gt $Total) {
        return
    }

    # Throttle updates (except first and last item)
    $now = [DateTime]::UtcNow
    if ($Script:LastProgressUpdate.ContainsKey($activityKey)) {
        $elapsed = ($now - $Script:LastProgressUpdate[$activityKey]).TotalMilliseconds

        # Always show first, last, and every N items based on interval
        if ($Current -ne 1 -and $Current -ne $Total -and $elapsed -lt $MinInterval) {
            return
        }
    }

    $Script:LastProgressUpdate[$activityKey] = $now

    # Calculate percentage
    $percentComplete = [math]::Min(100, [int](($Current / $Total) * 100))

    # Build status message
    $status = "Testing $Current of $Total"
    if ($ObjectName) {
        $status += " - $ObjectName"
    }

    # Display progress
    Write-Progress -Activity $Activity -Status $status -PercentComplete $percentComplete -CurrentOperation "$percentComplete% complete"
}



# ----- Kerberos-ASN1.ps1 -----

<#
.SYNOPSIS
    ASN.1 DER Encoder and Decoder for Kerberos protocol structures.

.DESCRIPTION
    Provides comprehensive ASN.1 DER encoding and decoding functions for Kerberos protocol implementation. Used by PKINIT, Kerberoast, and AS-REP Roast modules.

    Supports:
    - Primitive types: INTEGER, OCTET STRING, BIT STRING, BOOLEAN, NULL
    - String types: GeneralString, UTF8String, IA5String, PrintableString
    - Time types: GeneralizedTime, UTCTime
    - Constructed types: SEQUENCE, SET
    - Tagged types: Context-specific, Application, Universal

.NOTES
    Author: Alexander Sturz (@_61106960_)

    References:
    - RFC 4120: The Kerberos Network Authentication Service (V5)
    - RFC 4556: Public Key Cryptography for Initial Authentication in Kerberos (PKINIT)
    - ITU-T X.690: ASN.1 encoding rules (BER, CER, DER)
#>

#region ASN.1 Tag Constants

# Universal class tags (bits 7-6 = 00)
$Script:ASN1_BOOLEAN           = 0x01
$Script:ASN1_INTEGER           = 0x02
$Script:ASN1_BIT_STRING        = 0x03
$Script:ASN1_OCTET_STRING      = 0x04
$Script:ASN1_NULL              = 0x05
$Script:ASN1_OBJECT_IDENTIFIER = 0x06
$Script:ASN1_UTF8_STRING       = 0x0C
$Script:ASN1_SEQUENCE          = 0x30  # Constructed
$Script:ASN1_SET               = 0x31  # Constructed
$Script:ASN1_PRINTABLE_STRING  = 0x13
$Script:ASN1_IA5_STRING        = 0x16
$Script:ASN1_UTC_TIME          = 0x17
$Script:ASN1_GENERALIZED_TIME  = 0x18
$Script:ASN1_GENERAL_STRING    = 0x1B

# Tag class bits (bits 7-6)
$Script:ASN1_CLASS_UNIVERSAL   = 0x00
$Script:ASN1_CLASS_APPLICATION = 0x40
$Script:ASN1_CLASS_CONTEXT     = 0x80
$Script:ASN1_CLASS_PRIVATE     = 0xC0

# Constructed bit (bit 5)
$Script:ASN1_CONSTRUCTED       = 0x20

#endregion

#region ASN.1 Length Encoding/Decoding

<#
.SYNOPSIS
    Encodes length in DER format.
#>
function New-ASN1Length {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$Length
    )

    if ($Length -lt 0) {
        throw "ASN.1 length cannot be negative"
    }

    if ($Length -lt 128) {
        # Short form: single byte
        return [byte[]]@($Length)
    }
    else {
        # Long form: first byte = 0x80 | number of length bytes
        $lengthBytes = [System.Collections.Generic.List[byte]]::new()

        $tempLength = $Length
        while ($tempLength -gt 0) {
            $lengthBytes.Insert(0, [byte]($tempLength -band 0xFF))
            $tempLength = $tempLength -shr 8
        }

        $result = [byte[]]@(0x80 -bor $lengthBytes.Count) + $lengthBytes.ToArray()
        return $result
    }
}

<#
.SYNOPSIS
    Decodes DER length and returns length value and bytes consumed.
#>
function Read-ASN1Length {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data,

        [Parameter(Mandatory=$true)]
        [int]$Offset
    )

    if ($Offset -ge $Data.Length) {
        throw "ASN.1 length: offset beyond data"
    }

    $firstByte = $Data[$Offset]

    if ($firstByte -lt 128) {
        # Short form
        return @{
            Length = [int]$firstByte
            BytesConsumed = 1
        }
    }
    elseif ($firstByte -eq 0x80) {
        # Indefinite length (not allowed in DER)
        throw "ASN.1 indefinite length not supported in DER"
    }
    else {
        # Long form
        $numLengthBytes = $firstByte -band 0x7F

        if ($Offset + 1 + $numLengthBytes -gt $Data.Length) {
            throw "ASN.1 length: insufficient data for long form"
        }

        # Use [long] to prevent integer overflow with large ASN.1 structures
        [long]$length = 0
        for ($i = 0; $i -lt $numLengthBytes; $i++) {
            $length = ($length -shl 8) -bor $Data[$Offset + 1 + $i]
        }

        return @{
            Length = $length
            BytesConsumed = 1 + $numLengthBytes
        }
    }
}

#endregion

#region ASN.1 Primitive Encoders

<#
.SYNOPSIS
    Encodes an integer in ASN.1 DER format.
#>
function New-ASN1Integer {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [object]$Value
    )

    $bytes = $null

    if ($Value -is [byte[]]) {
        $bytes = $Value
    }
    elseif ($Value -is [array]) {
        # Handle Object[] arrays like @(5) or @(23) - convert to byte array
        # This is common when calling New-ASN1Integer -Value @(5) in PowerShell
        $bytes = [byte[]]($Value | ForEach-Object { [byte]$_ })
    }
    elseif ($Value -is [int] -or $Value -is [int64] -or $Value -is [uint32] -or $Value -is [uint64]) {
        # Convert to big-endian bytes
        if ($Value -eq 0) {
            $bytes = @(0x00)
        }
        else {
            $tempValue = [uint64]$Value
            $byteList = [System.Collections.Generic.List[byte]]::new()

            while ($tempValue -gt 0) {
                $byteList.Insert(0, [byte]($tempValue -band 0xFF))
                $tempValue = $tempValue -shr 8
            }

            $bytes = $byteList.ToArray()

            # Add leading zero if high bit is set (to keep positive)
            if ($bytes[0] -band 0x80) {
                $bytes = @(0x00) + $bytes
            }
        }
    }
    elseif ($Value -is [System.Numerics.BigInteger]) {
        $bytes = $Value.ToByteArray()
        [Array]::Reverse($bytes)  # .NET uses little-endian

        # Remove leading zeros but keep one if needed for sign
        while ($bytes.Length -gt 1 -and $bytes[0] -eq 0 -and -not ($bytes[1] -band 0x80)) {
            $bytes = [byte[]]$bytes[1..($bytes.Length - 1)]
        }
    }
    else {
        throw "Unsupported integer type: $($Value.GetType().Name)"
    }

    $tag = [byte]$Script:ASN1_INTEGER
    $lengthBytes = New-ASN1Length -Length $bytes.Length

    return [byte[]](@($tag) + $lengthBytes + $bytes)
}

<#
.SYNOPSIS
    Encodes an octet string in ASN.1 DER format.
#>
function New-ASN1OctetString {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [byte[]]$Value = @()
    )

    # Handle null or empty array
    if ($null -eq $Value) { $Value = @() }

    $tag = [byte]$Script:ASN1_OCTET_STRING
    $lengthBytes = New-ASN1Length -Length $Value.Length

    if ($Value.Length -eq 0) {
        return [byte[]](@($tag) + $lengthBytes)
    }
    return [byte[]](@($tag) + $lengthBytes + $Value)
}

<#
.SYNOPSIS
    Encodes a bit string in ASN.1 DER format.
#>
function New-ASN1BitString {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Value,

        [Parameter(Mandatory=$false)]
        [int]$UnusedBits = 0
    )

    if ($UnusedBits -lt 0 -or $UnusedBits -gt 7) {
        throw "UnusedBits must be 0-7"
    }

    $tag = [byte]$Script:ASN1_BIT_STRING
    $content = @([byte]$UnusedBits) + $Value
    $lengthBytes = New-ASN1Length -Length $content.Length

    return [byte[]](@($tag) + $lengthBytes + $content)
}

<#
.SYNOPSIS
    Encodes a boolean in ASN.1 DER format.
#>
function New-ASN1Boolean {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [bool]$Value
    )

    $tag = [byte]$Script:ASN1_BOOLEAN
    $content = if ($Value) { 0xFF } else { 0x00 }

    return [byte[]]@($tag, 0x01, $content)
}

<#
.SYNOPSIS
    Encodes NULL in ASN.1 DER format.
#>
function New-ASN1Null {
    return [byte[]]@($Script:ASN1_NULL, 0x00)
}

<#
.SYNOPSIS
    Encodes an OID in ASN.1 DER format.
#>
function New-ASN1ObjectIdentifier {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$OID
    )

    $components = $OID.Split('.') | ForEach-Object { [int]$_ }

    if ($components.Count -lt 2) {
        throw "OID must have at least 2 components"
    }

    $bytes = [System.Collections.Generic.List[byte]]::new()

    # First two components are encoded as (c1 * 40) + c2
    $bytes.Add([byte](($components[0] * 40) + $components[1]))

    # Remaining components use base-128 encoding
    for ($i = 2; $i -lt $components.Count; $i++) {
        $value = $components[$i]

        if ($value -eq 0) {
            $bytes.Add(0x00)
        }
        else {
            $encoded = [System.Collections.Generic.List[byte]]::new()

            while ($value -gt 0) {
                $encoded.Insert(0, [byte](($value -band 0x7F) -bor 0x80))
                $value = $value -shr 7
            }

            # Clear high bit on last byte
            $encoded[$encoded.Count - 1] = $encoded[$encoded.Count - 1] -band 0x7F
            $bytes.AddRange($encoded)
        }
    }

    $tag = [byte]$Script:ASN1_OBJECT_IDENTIFIER
    $lengthBytes = New-ASN1Length -Length $bytes.Count

    return [byte[]](@($tag) + $lengthBytes + $bytes.ToArray())
}

#endregion

#region ASN.1 String Encoders

<#
.SYNOPSIS
    Encodes a GeneralString in ASN.1 DER format.
#>
function New-ASN1GeneralString {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Value
    )

    $bytes = [System.Text.Encoding]::ASCII.GetBytes($Value)
    $tag = [byte]$Script:ASN1_GENERAL_STRING
    $lengthBytes = New-ASN1Length -Length $bytes.Length

    return [byte[]](@($tag) + $lengthBytes + $bytes)
}

<#
.SYNOPSIS
    Encodes a UTF8String in ASN.1 DER format.
