        static uint CalcCrc32(byte[] data)
        {
            uint dwCRC = 0xFFFFFFFF;
            for (int i = 0; i < data.Length; i++)
                dwCRC = (dwCRC >> 8) ^ dwCrc32Table[(data[i]) ^ (dwCRC & 0x000000FF)];
            return ~dwCRC;
        }
