# ----- Get-DomainInformation.ps1 -----

<#
.SYNOPSIS
    Collects comprehensive Active Directory domain information.

.DESCRIPTION
    Collects:
    - Domain Name (DNS + NetBIOS), SID, Functional Level
    - Forest Information
    - Parent/Child Domain Detection
    - Domain Controllers (detailed information)
    - Kerberos Policy
    - krbtgt Account Security Check
    - Guest Account Status (enabled/disabled, password age, group memberships)
    - Active Directory Sites and Subnets

.PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

.PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

.PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

.EXAMPLE
    Get-DomainInformation
    Returns comprehensive domain information for the current domain.

.EXAMPLE
    Get-DomainInformation -Domain "contoso.com" -Credential (Get-Credential)
    Returns domain information for contoso.com using specified credentials.

.NOTES
    Category: Domain
    Author: Alexander Sturz (@_61106960_)
#>

function Get-DomainInformation {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-DomainInformation] Starting domain enumeration"

        # Domain Functional Level Mapping
        $DomainModeLevel = @{
            0 = "Windows 2000 native"
            1 = "Windows 2003 interim"
            2 = "Windows 2003"
            3 = "Windows 2008"
            4 = "Windows 2008 R2"
            5 = "Windows 2012"
            6 = "Windows 2012 R2"
            7 = "Windows 2016"
            10 = "Windows 2025"
        }
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            $NetBIOSName = $null
            $KerberosPolicy = $null
            $PdcFSMO = $null

            # Use cached RootDSE data from LDAPContext (already available after Ensure-LDAPConnection)
            $DomainDN = $Script:LDAPContext.DomainDN
            $ForestDN = $Script:LDAPContext.RootDomainNamingContext
            $ConfigDN = $Script:LDAPContext.ConfigurationNamingContext
            $DomainFunc = $Script:LDAPContext.DomainFunctionality
            $ForestFunc = $Script:LDAPContext.ForestFunctionality
            $DomainName = $Script:LDAPContext.Domain
            $DomainSID = $Script:LDAPContext.DomainSID
            $ForestRootName = $ForestDN -replace "DC=", "" -replace ",", "."

            # Query domain object for additional attributes not in RootDSE
            try {
                $DomainObject = @(Get-DomainObject -LDAPFilter "(objectClass=domain)" -Scope Base @PSBoundParameters)[0]

                if ($DomainObject) {
                    # The domain object's 'name' attribute is the DNS label (e.g. "example"),
                    # NOT the NetBIOS name. Use the authoritative value resolved from the crossRef at
                    # connect time (LDAPContext.DomainNetBIOS); only fall back to 'name' if unavailable.
                    if ($Script:LDAPContext.DomainNetBIOS) {
                        $NetBIOSName = $Script:LDAPContext.DomainNetBIOS
                        Write-Log "[Get-DomainInformation] NetBIOS name (from crossRef): $NetBIOSName"
                    }
                    elseif ($DomainObject.name) {
                        $NetBIOSName = $DomainObject.name
                        Write-Log "[Get-DomainInformation] NetBIOS name fallback (domain object name/DNS label): $NetBIOSName"
                    }

                    # Kerberos Policy
                    $MaxTicketAge = $null
                    $MaxRenewAge = $null

                    if ($DomainObject.maxTicketAge) {
                        $TicketAgeTicks = [Math]::Abs([Int64]$DomainObject.maxTicketAge)
                        $MaxTicketAge = [TimeSpan]::FromTicks($TicketAgeTicks)
                    }

                    if ($DomainObject.maxRenewAge) {
                        $RenewAgeTicks = [Math]::Abs([Int64]$DomainObject.maxRenewAge)
                        $MaxRenewAge = [TimeSpan]::FromTicks($RenewAgeTicks)
                    }

                    $KerberosPolicy = @{
                        MaxTicketAge = $MaxTicketAge
                        MaxRenewAge = $MaxRenewAge
                    }

                    $PdcFSMO = $DomainObject.fSMORoleOwner
                }
            } catch {
                Write-Log "[Get-DomainInformation] Error retrieving domain object: $_"
            }

            # Parent/Child Domain Detection
            $ParentDomain = $null
            $ChildDomains = @()

            try {
                Write-Log "[Get-DomainInformation] Checking for parent/child domains"

                # Check if current domain is NOT the forest root (= has parent)
                if ($DomainDN -ne $ForestDN) {
                    $ParentDomain = $ForestRootName
                }

                # Query all domains in forest for child domains
                $PartitionsSearchBase = "CN=Partitions,$ConfigDN"
                $AllDomainsFilter = "(&(objectClass=crossRef)(systemFlags:1.2.840.113556.1.4.803:=2))"
                $AllDomains = Get-DomainObject -LDAPFilter $AllDomainsFilter -SearchBase $PartitionsSearchBase @PSBoundParameters

                if ($AllDomains) {
                    # Ensure $AllDomains is always an array
                    $AllDomainsArray = @($AllDomains)
                    foreach ($CrossRefEntry in $AllDomainsArray) {
                        $DomainNCName = $CrossRefEntry.nCName
                        $DomainDnsRoot = $CrossRefEntry.dnsRoot

                        # Check if this domain is a child of current domain
                        if ($DomainNCName -ne $DomainDN -and $DomainNCName -like "*,$DomainDN") {
                            $ChildDomains += $DomainDnsRoot
                        }
                    }
                }
            } catch {
                Write-Log "[Get-DomainInformation] Error retrieving parent/child domains: $_"
            }

            $DomainControllers = @()

            try {
                Write-Log "[Get-DomainInformation] Querying Domain Controllers with full details"
                $DCs = Get-DomainComputer -LDAPFilter "(primaryGroupID=516)" @PSBoundParameters

                if ($DCs) {
                    # Filter to current domain only (referral-chasing defense-in-depth)
                    $DomainControllers = @($DCs) | Where-Object {
                        -not $DomainDN -or $_.distinguishedName -like "*,$DomainDN"
                    }
                    $DomainControllers = @($DomainControllers)
                }
            } catch {
                Write-Log "[Get-DomainInformation] Error retrieving domain controllers: $_"
            }

            # krbtgt Account Age Check
            $KrbtgtInfo = $null
            $KrbtgtPasswordAge = $null
            $KrbtgtSeverity = "Info"

            try {
                Write-Log "[Get-DomainInformation] Checking krbtgt account password age"
                $KrbtgtAccount = @(Get-DomainObject -LDAPFilter "(sAMAccountName=krbtgt)" @PSBoundParameters)[0]

                if ($KrbtgtAccount -and $KrbtgtAccount.pwdLastSet) {
                    # pwdLastSet is already converted to DateTime by Get-DomainObject
                    $PwdLastSet = $KrbtgtAccount.pwdLastSet

                    $PasswordAge = (Get-Date) - $PwdLastSet
                    $KrbtgtPasswordAge = $PasswordAge.Days

                    # Determine severity
                    if ($KrbtgtPasswordAge -gt 730) {
                        # > 2 years
                        $KrbtgtSeverity = "Critical"
                    } elseif ($KrbtgtPasswordAge -gt 365) {
                        # > 1 year
                        $KrbtgtSeverity = "High"
                    } elseif ($KrbtgtPasswordAge -gt 180) {
                        # > 180 days
                        $KrbtgtSeverity = "Medium"
                    } else {
                        $KrbtgtSeverity = "Info"
                    }

                    $KrbtgtInfo = @{
                        PasswordLastSet = $PwdLastSet
                        PasswordAgeDays = $KrbtgtPasswordAge
                        Severity = $KrbtgtSeverity
                    }
                }
            } catch {
                Write-Log "[Get-DomainInformation] Error retrieving krbtgt account: $_"
            }

            # Guest Account Status Check
            $GuestInfo = $null
            $GuestEnabled = $false

            try {
                Write-Log "[Get-DomainInformation] Checking Guest account status"

                # Guest account has fixed RID 501 in domain
                $GuestSID = "$DomainSID-501"
                Write-Log "[Get-DomainInformation] Guest SID: $GuestSID"
                $GuestAccount = @(Get-DomainUser -Identity $GuestSID @PSBoundParameters)[0]
                Write-Log "[Get-DomainInformation] Found Guest accounts: $(@(Get-DomainUser -Identity $GuestSID @PSBoundParameters).Count)"

                if ($GuestAccount) {
                    # Check if account is enabled (userAccountControl already parsed by Get-DomainUser)
                    $uacFlags = $GuestAccount.userAccountControl
                    if ($uacFlags) {
                        # Check if ACCOUNTDISABLE flag is present in array
                        $GuestEnabled = -not ($uacFlags -contains 'ACCOUNTDISABLE')
                    }

                    # Get group memberships (only direct memberships)
                    $GuestGroups = @()
                    if ($GuestAccount.memberOf) {
                        $GuestGroups = @($GuestAccount.memberOf)
                    }

                    # Check if Guest is in privileged groups
                    $GuestSID = @($GuestAccount.objectSid)[0]
                    $IsPrivileged = (Test-IsPrivileged -Identity $GuestSID).IsPrivileged
                    Write-Log "[Get-DomainInformation] Guest IsPrivileged: $IsPrivileged"

                    $GuestInfo = @{
                        Enabled = $GuestEnabled
                        MemberOf = $GuestGroups
                        IsPrivileged = $IsPrivileged
                    }
                }
            } catch {
                Write-Log "[Get-DomainInformation] Error retrieving Guest account: $_"
            }

            # Sites and Subnets - Query via LDAP from Configuration Partition
            # Sites are forest-wide (stored in CN=Sites,CN=Configuration,DC=<forest-root>)
            # Works correctly for sub-domains because ConfigurationNamingContext always points to forest root
            $Sites = @()
            $Subnets = @()

            try {
                $configNC = $Script:LDAPContext.ConfigurationNamingContext
                if ($configNC) {
                    $sitesContainer = "CN=Sites,$configNC"
                    Write-Log "[Get-DomainInformation] Querying Sites and Subnets via LDAP from $sitesContainer"

                    # Query all site objects
                    $siteObjects = Get-DomainObject -LDAPFilter "(objectClass=site)" -SearchBase $sitesContainer -Properties 'name','distinguishedName' @PSBoundParameters
                    foreach ($siteObj in @($siteObjects)) {
                        if ($siteObj.name) {
                            $Sites += [PSCustomObject]@{
                                Name = $siteObj.name
                                DomainControllers = @()
                            }
                        }
                    }

                    # Query all subnet objects
                    $subnetContainer = "CN=Subnets,$sitesContainer"
                    $subnetObjects = Get-DomainObject -LDAPFilter "(objectClass=subnet)" -SearchBase $subnetContainer -Properties 'name','siteObject' @PSBoundParameters
                    foreach ($subnetObj in @($subnetObjects)) {
                        if ($subnetObj.name) {
                            # Extract site name from siteObject DN: CN=<SiteName>,CN=Sites,...
                            $subnetSiteName = $null
                            if ($subnetObj.siteObject -match '^CN=([^,]+),CN=Sites') {
                                $subnetSiteName = $Matches[1]
                            }
                            $Subnets += [PSCustomObject]@{
                                Name = $subnetObj.name
                                Site = $subnetSiteName
                            }
                        }
                    }

                    Write-Log "[Get-DomainInformation] Found $($Sites.Count) sites and $($Subnets.Count) subnets"

                    # Resolve DC-to-Site mapping
                    # Server objects: CN=<DC>,CN=Servers,CN=<SiteName>,CN=Sites,CN=Configuration,...
                    $serverObjects = Get-DomainObject -LDAPFilter "(objectClass=server)" -SearchBase $sitesContainer -Properties 'dNSHostName','distinguishedName' @PSBoundParameters

                    foreach ($serverObj in @($serverObjects)) {
                        $serverDN = $serverObj.distinguishedName
                        $serverDNS = $serverObj.dNSHostName
                        if (-not $serverDN -or -not $serverDNS) { continue }

                        # Extract site name from DN: CN=<DC>,CN=Servers,CN=<SiteName>,CN=Sites,...
                        if ($serverDN -match 'CN=Servers,CN=([^,]+),CN=Sites') {
                            $siteName = $Matches[1]
                            $siteEntry = $Sites | Where-Object { $_.Name -eq $siteName }
                            if ($siteEntry) {
                                $siteEntry.DomainControllers += $serverDNS
                            }
                        }
                    }
                    Write-Log "[Get-DomainInformation] DC-to-Site mapping completed"
                } else {
                    Write-Log "[Get-DomainInformation] No ConfigurationNamingContext available - skipping Sites/Subnets"
                }
            } catch {
                Write-Log "[Get-DomainInformation] Error retrieving Sites/Subnets: $_"
            }

            # ===================================================================
            # SubCheck 1: Domain Information
            # Severity: Finding (Anonymous LDAP), Hint (old FL), Note (default)
            # ===================================================================
            Show-SubHeader "Collecting domain information..." -ObjectType "DomainBasicInfo"

            # Build functional level texts
            $DomainFuncLevelText = $DomainModeLevel[[int]$DomainFunc]
            if (-not $DomainFuncLevelText) {
                $DomainFuncLevelText = "Unknown (Level $DomainFunc)"
            }

            $ForestFuncLevelText = $DomainModeLevel[[int]$ForestFunc]
            if (-not $ForestFuncLevelText) {
                $ForestFuncLevelText = "Unknown (Level $ForestFunc)"
            }

            # NetBIOS Name
            $NetBIOSDisplay = if ($NetBIOSName) { $NetBIOSName } else { "(not found)" }

            # Create domain info object (Domain Controllers shown separately with FSMO roles)
            $domainInfoObj = [PSCustomObject]@{
                domainNameDNS = $DomainName
                domainNameNetBIOS = $NetBIOSDisplay
                domainSID = $DomainSID
                domainFunctionalLevel = $DomainFuncLevelText
                forestFunctionalLevel = $ForestFuncLevelText
                forestName = $ForestRootName
            }

            # Add optional properties
            if ($ParentDomain) {
                $domainInfoObj | Add-Member -NotePropertyName 'parentDomain' -NotePropertyValue $ParentDomain -Force
            }
            if (@($ChildDomains).Count -gt 0) {
                $domainInfoObj | Add-Member -NotePropertyName 'childDomains' -NotePropertyValue ($ChildDomains -join ', ') -Force
            }

            # Determine severity for Domain Information
            # Finding: Anonymous LDAP Access enabled
            # Hint: Functional Level < 2016 (level 7)
            # Note: Everything OK
            $domainInfoSeverity = "Note"

            # Anonymous LDAP Access Warning - Critical finding
            if ($Script:LDAPContext['AnonymousAccessEnabled']) {
                $domainInfoObj | Add-Member -NotePropertyName 'anonymousLDAPAccess' -NotePropertyValue "ENABLED - Security Risk!" -Force
                $anonDetails = $Script:LDAPContext['AnonymousAccessDetails']
                if ($anonDetails -and $anonDetails.ReadableAttributes -and $anonDetails.ReadableAttributes.Count -gt 0) {
                    $domainInfoObj | Add-Member -NotePropertyName 'anonymousReadableAttributes' -NotePropertyValue ($anonDetails.ReadableAttributes -join ', ') -Force
                }
                $domainInfoSeverity = "Finding"
            }
            # Check for old functional level (< 2016 = level 7)
            elseif ([int]$DomainFunc -lt 7) {
                $domainInfoSeverity = "Hint"
            }

            # Output domain info object
            Show-Line "Found domain information:" -Class $domainInfoSeverity
            $domainInfoObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DomainBasicInfo' -Force
            Show-Object $domainInfoObj

            # ===================================================================
            # SubCheck 2: Kerberos Policy
            # Severity: Finding (krbtgt > 365d), Hint (krbtgt > 180d), Note (default)
            # ===================================================================
            Show-SubHeader "Analyzing Kerberos policy..." -ObjectType "KerberosPolicy"

            # Build Kerberos policy values
            $maxTicketAgeText = "10 hours (default)"
            $maxRenewalAgeText = "7 days (default)"

            if ($KerberosPolicy -and $KerberosPolicy.MaxTicketAge) {
                $TicketAgeHours = [Math]::Round($KerberosPolicy.MaxTicketAge.TotalHours, 1)
                $maxTicketAgeText = "$TicketAgeHours hours"
                if ($TicketAgeHours -eq 10) {
                    $maxTicketAgeText += " (default)"
                }
            }
            if ($KerberosPolicy -and $KerberosPolicy.MaxRenewAge) {
                $RenewAgeDays = [Math]::Round($KerberosPolicy.MaxRenewAge.TotalDays, 1)
                $maxRenewalAgeText = "$RenewAgeDays days"
                if ($RenewAgeDays -eq 7) {
                    $maxRenewalAgeText += " (default)"
                }
            }

            # Query DC current time from RootDSE (direct LdapConnection query, not via Invoke-LDAPSearch
            # because Invoke-LDAPSearch overrides empty SearchBase with DomainDN)
            $dcTimeText = $null
            try {
                $rootDSEReq = New-Object System.DirectoryServices.Protocols.SearchRequest
                $rootDSEReq.DistinguishedName = ""
                $rootDSEReq.Filter = "(objectClass=*)"
                $rootDSEReq.Scope = [System.DirectoryServices.Protocols.SearchScope]::Base
                [void]$rootDSEReq.Attributes.Add("currentTime")
                $rootDSEResp = $Script:LdapConnection.SendRequest($rootDSEReq)
                if ($rootDSEResp -and $rootDSEResp.Entries.Count -gt 0 -and $rootDSEResp.Entries[0].Attributes.Contains("currenttime")) {
                    $dcTimeStr = $rootDSEResp.Entries[0].Attributes["currenttime"].GetValues([string])[0]
                    # currentTime format: yyyyMMddHHmmss.0Z (Generalized Time)
                    $dcTimeUTC = [DateTime]::ParseExact($dcTimeStr.Substring(0, 14), "yyyyMMddHHmmss", $null)
                    $localTimeUTC = [DateTime]::UtcNow
                    $clockSkew = $dcTimeUTC - $localTimeUTC
                    $skewSeconds = [Math]::Round($clockSkew.TotalSeconds)
                    $skewAbs = [Math]::Abs($skewSeconds)
                    $skewSign = if ($skewSeconds -ge 0) { "+" } else { "-" }
                    if ($skewAbs -ge 3600) {
                        $skewDisplay = "${skewSign}$([Math]::Floor($skewAbs / 3600))h $([Math]::Floor(($skewAbs % 3600) / 60))m"
                    } elseif ($skewAbs -ge 60) {
                        $skewDisplay = "${skewSign}$([Math]::Floor($skewAbs / 60))m $($skewAbs % 60)s"
                    } else {
                        $skewDisplay = "${skewSign}${skewAbs}s"
                    }
                    $dcTimeText = "$($dcTimeUTC.ToString('yyyy-MM-dd HH:mm:ss')) UTC (skew: $skewDisplay)"
                }
            }
            catch {
                Write-Log "[Get-DomainInformation] Failed to query DC currentTime: $_"
            }

            $kerberosObj = [PSCustomObject]@{
                maxTicketAgeTGT = $maxTicketAgeText
                maxRenewalAge = $maxRenewalAgeText
            }

            # Add DC time if available
            if ($dcTimeText) {
                $kerberosObj | Add-Member -NotePropertyName 'domainControllerTime' -NotePropertyValue $dcTimeText -Force
            }

            # Determine severity for Kerberos Policy based on krbtgt age
            # Finding: krbtgt > 365 days (1 year)
            # Hint: krbtgt > 180 days
            # Note: krbtgt <= 180 days or not available
            $kerberosSeverity = "Note"

            if ($KrbtgtInfo) {
                $LastChanged = $KrbtgtInfo.PasswordLastSet.ToString('yyyy-MM-dd')
                $AgeText = "$KrbtgtPasswordAge days (last changed: $LastChanged)"
                $kerberosObj | Add-Member -NotePropertyName 'krbtgtPasswordAge' -NotePropertyValue $AgeText -Force

                # Set severity based on krbtgt age
                if ($KrbtgtPasswordAge -gt 365) {
                    $kerberosSeverity = "Finding"
                } elseif ($KrbtgtPasswordAge -gt 180) {
                    $kerberosSeverity = "Hint"
                }
            }

            # Output Kerberos policy object
            Show-Line "Found Kerberos policy:" -Class $kerberosSeverity
            $kerberosObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'KerberosPolicy' -Force
            Show-Object $kerberosObj

            # ===================================================================
            # SubCheck 3: Guest Account Status
            # Severity: Finding (enabled + privileged), Hint (enabled), Secure (disabled)
            # ===================================================================
            Show-SubHeader "Checking Guest Account Status..." -ObjectType "GuestAccount"

            if ($GuestInfo) {
                $statusText = if ($GuestInfo.Enabled) { "ENABLED" } else { "Disabled" }

                # Determine severity
                if ($GuestInfo.Enabled) {
                    if ($GuestInfo.IsPrivileged) {
                        $guestClass = "Finding"  # Enabled + privileged = critical
                        Write-Log "[Get-DomainInformation] Guest severity: Finding (enabled + privileged)"
                    } else {
                        $guestClass = "Hint"     # Enabled but not privileged
                        Write-Log "[Get-DomainInformation] Guest severity: Hint (enabled but not privileged)"
                    }
                } else {
                    $guestClass = "Secure"       # Disabled = secure
                    Write-Log "[Get-DomainInformation] Guest severity: Secure (disabled)"
                }

                # Build guest account object for display
                $guestObj = [PSCustomObject]@{
                    accountStatus = $statusText
                }

                # Add group memberships as array (not concatenated string) for proper transformer processing
                if (@($GuestInfo.MemberOf).Count -gt 0) {
                    $guestObj | Add-Member -NotePropertyName 'memberOf' -NotePropertyValue $GuestInfo.MemberOf -Force
                }

                Show-Line "Found $($statusText.ToLower()) Guest account" -Class $guestClass
                $guestObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GuestAccount' -Force
                Show-Object $guestObj

            } else {
                Show-Line "Guest account not found (unusual - RID 501 should always exist)" -Class Hint
            }

            # ===================================================================
            # SubCheck 4: Domain Controllers
            # Severity: Note (informational only, OS/LDAPS checked elsewhere)
            # ===================================================================
            Show-SubHeader "Searching for Domain Controllers..." -ObjectType "DomainController"

            # Query FSMO Roles first to associate with DCs
            $FSMORoles = @{}
            $FSMOByDC = @{}  # Map DC DN to list of FSMO roles
            try {
                Write-Log "[Get-DomainInformation] Querying FSMO role holders"

                # PDC Emulator (from domain object)
                if ($PdcFSMO) {
                    $FSMORoles['PDC Emulator'] = $PdcFSMO
                    Write-Log "[Get-DomainInformation] PDC Emulator: $PdcFSMO"
                }

                # Schema Master (forest-wide)
                $SchemaRole = @(Get-DomainObject -LDAPFilter "(objectClass=*)" -SearchBase "CN=Schema,$ConfigDN" -Scope Base @PSBoundParameters)[0]
                if ($SchemaRole -and $SchemaRole.fSMORoleOwner) {
                    $FSMORoles['Schema Master'] = $SchemaRole.fSMORoleOwner
                }

                # Infrastructure Master (domain-wide)
                $InfraRole = @(Get-DomainObject -LDAPFilter "(objectClass=*)" -SearchBase "CN=Infrastructure,$DomainDN" -Scope Base @PSBoundParameters)[0]
                if ($InfraRole -and $InfraRole.fSMORoleOwner) {
                    $FSMORoles['Infrastructure Master'] = $InfraRole.fSMORoleOwner
                }

                # RID Master (domain-wide)
                $RidRole = @(Get-DomainObject -LDAPFilter "(objectClass=*)" -SearchBase "CN=RID Manager`$,CN=System,$DomainDN" -Scope Base @PSBoundParameters)[0]
                if ($RidRole -and $RidRole.fSMORoleOwner) {
                    $FSMORoles['RID Master'] = $RidRole.fSMORoleOwner
                }

                # Domain Naming Master (forest-wide)
                $NamingRole = @(Get-DomainObject -LDAPFilter "(objectClass=*)" -SearchBase "CN=Partitions,$ConfigDN" -Scope Base @PSBoundParameters)[0]
                if ($NamingRole -and $NamingRole.fSMORoleOwner) {
                    $FSMORoles['Domain Naming Master'] = $NamingRole.fSMORoleOwner
                }

                # Build reverse mapping: DC DN -> FSMO roles
                # FSMO role owner is stored as: CN=NTDS Settings,CN=DCNAME,CN=Servers,CN=Site,CN=Sites,...
                foreach ($roleName in $FSMORoles.Keys) {
                    $roleOwnerDN = $FSMORoles[$roleName]
                    if ($roleOwnerDN -match 'CN=NTDS Settings,CN=([^,]+),') {
                        $dcName = $Matches[1]
                        if (-not $FSMOByDC.ContainsKey($dcName)) {
                            $FSMOByDC[$dcName] = @()
                        }
                        $FSMOByDC[$dcName] += $roleName
                    }
                }

                Write-Log "[Get-DomainInformation] FSMO role mapping complete: $($FSMOByDC.Count) DCs have FSMO roles"
            } catch {
                Write-Log "[Get-DomainInformation] Error querying FSMO roles: $_"
            }

            # Output Domain Controllers with FSMO roles
            if (@($DomainControllers).Count -gt 0) {
                # Build DC list with FSMO roles
                $dcDisplayList = @()
                foreach ($dc in $DomainControllers) {
                    $dcHostName = if ($dc.dNSHostName) { $dc.dNSHostName } else { $dc.name }
                    $dcName = $dc.name

                    # Check if this DC has any FSMO roles
                    $roles = @()
                    if ($FSMOByDC.ContainsKey($dcName)) {
                        $roles = $FSMOByDC[$dcName]
                    }

                    if (@($roles).Count -gt 0) {
                        $rolesText = $roles -join ", "
                        $dcDisplayList += "$dcHostName [$rolesText]"
                    } else {
                        $dcDisplayList += $dcHostName
                    }
                }

                $dcObj = [PSCustomObject]@{
                    domainControllers = $dcDisplayList -join "`n"
                }
                Show-Line "Found $(@($DomainControllers).Count) domain controller(s):" -Class Note
                $dcObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DomainControllers' -Force
                Show-Object $dcObj
            } else {
                Show-Line "No domain controllers found" -Class Note
            }

            # ===================================================================
            # SubCheck 5: Sites and Subnets
            # Severity: Hint (no subnets), Note (subnets found)
            # ===================================================================
            Show-SubHeader "Searching for Sites and Subnets..." -ObjectType "SitesAndSubnets"

            if (@($Sites).Count -gt 0) {
                Show-Line "Found $(@($Sites).Count) site(s) and $(@($Subnets).Count) subnet(s):" -Class Note

                foreach ($siteInfo in $Sites) {
                    # Build site object with subnets and DCs
                    $siteSubnets = @($Subnets | Where-Object { $_.Site -eq $siteInfo.Name })
                    $subnetDisplay = if ($siteSubnets.Count -gt 0) {
                        # Join with newline (not ", ") so the renderer prints one subnet per line,
                        # each padded to the value column - consistent with domainControllers above.
                        # A comma-joined string renders as one long line that wraps out of alignment.
                        ($siteSubnets | ForEach-Object { $_.Name }) -join "`n"
                    } else {
                        "(none)"
                    }
                    $dcDisplay = if ($siteInfo.DomainControllers.Count -gt 0) {
                        ($siteInfo.DomainControllers) -join ", "
                    } else {
                        "(none)"
                    }

                    $siteObj = [PSCustomObject]@{
                        Name = $siteInfo.Name
                        siteName = $siteInfo.Name
                        siteSubnets = $subnetDisplay
                        siteDomainControllers = $dcDisplay
                    }
                    $siteObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SitesAndSubnets' -Force
                    Show-Object $siteObj
                }
            } else {
                Show-Line "No AD sites found" -Class Hint
            }

        } catch {
            Write-Log "[Get-DomainInformation] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-DomainInformation] Domain enumeration completed"
    }
}



# ----- Get-DomainPasswordPolicy.ps1 -----

function Get-DomainPasswordPolicy {
    <#
    .SYNOPSIS
    Analyzes domain password policy configuration.

    .DESCRIPTION
    Evaluates both domain-level and Fine-Grained Password Policies (FGPP/PSO) for security weaknesses:

    Collects:
    - Domain Default Policy:
    - Fine-Grained Password Policies (FGPP):

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-DomainPasswordPolicy

    .EXAMPLE
    Get-DomainPasswordPolicy -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Domain
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-DomainPasswordPolicy] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Analyzing password policy..." -ObjectType "DomainPasswordPolicy"

            $domainDN = $Script:LDAPContext.DomainDN

            # Query domain object for password policy attributes
            $domainPolicyResults = Get-DomainObject -Identity $domainDN @PSBoundParameters

            if (-not $domainPolicyResults) {
                Write-Warning "[Get-DomainPasswordPolicy] Could not retrieve domain password policy from $domainDN"
                return
            }

            # Get-DomainObject may return single object or array - normalize to single object
            $domainPolicy = if ($domainPolicyResults -is [array]) { $domainPolicyResults[0] } else { $domainPolicyResults }

            # Extract and convert values.
            # NOTE: The interval attributes (minPwdAge, maxPwdAge, lockoutDuration,
            # lockOutObservationWindow) arrive as the RAW negative 100-nanosecond
            # interval string (e.g. "-18000000000"), NOT pre-formatted - they are
            # currently routed through Invoke-LDAPSearch's FileTime branch, whose
            # [DateTime]::FromFileTime() throws on these negative deltas and falls back
            # to the raw value. The "(\d+) days/minutes" regex branches below are kept
            # as a defensive path in case that ever changes. The critical part is the
            # Int64.MinValue (0x8000000000000000) "never" sentinel, which must be
            # recognised before dividing - otherwise it yields a nonsensical value
            # (e.g. lockoutDuration = 15372286728 minutes).
            # - minPwdLength, lockoutThreshold: integer as string (e.g., "7")
            # - pwdProperties: flag array (e.g., @("DOMAIN_PASSWORD_COMPLEX", ...))

            $minPwdLength = if ($domainPolicy.minPwdLength) {
                try { [int]$domainPolicy.minPwdLength } catch { 0 }
            } else { 0 }

            # minPwdAge: pre-formatted by Invoke-LDAPSearch as "N days", "Not set", or "Never"
            $minPwdAge = if ($domainPolicy.minPwdAge -and $domainPolicy.minPwdAge -notmatch "Not set|Never") {
                if ($domainPolicy.minPwdAge -match "(\d+)\s+days?") {
                    [int]$matches[1]
                } else {
                    try {
                        $ticks = [Math]::Abs([int64]$domainPolicy.minPwdAge)
                        [Math]::Round($ticks / 864000000000)
                    } catch { 0 }
                }
            } else { 0 }

            # maxPwdAge: pre-formatted by Invoke-LDAPSearch as "N days", "Not set", or "Never"
            $maxPwdAge = if ($domainPolicy.maxPwdAge -and $domainPolicy.maxPwdAge -notmatch "Not set|Never") {
                if ($domainPolicy.maxPwdAge -match "(\d+)\s+days?") {
                    [int]$matches[1]
                } else {
                    try {
                        $ticksValue = [int64]$domainPolicy.maxPwdAge
                        if ($ticksValue -ne [int64]::MinValue) {
                            $ticks = [Math]::Abs($ticksValue)
                            [Math]::Round($ticks / 864000000000)
                        } else { 0 }
                    } catch { 0 }
                }
            } else { 0 }

            $lockoutThreshold = if ($domainPolicy.lockoutThreshold -and $domainPolicy.lockoutThreshold -notmatch "Not set") {
                try { [int]$domainPolicy.lockoutThreshold } catch { 0 }
            } else { 0 }

            # lockoutDuration: raw negative 100ns interval, or "Not set"/"Never".
            # 0 or Int64.MinValue ("never" sentinel) => locked until manual unlock.
            $lockoutDuration = if ($domainPolicy.lockoutDuration -and $domainPolicy.lockoutDuration -notmatch "Not set|Never") {
                if ($domainPolicy.lockoutDuration -match "(\d+)\s+minutes?") {
                    [int]$matches[1]
                } else {
                    try {
                        $durValue = [int64]$domainPolicy.lockoutDuration
                        if ($durValue -eq [int64]::MinValue) {
                            0  # "never" sentinel -> displayed as "Forever (manual unlock)"
                        } else {
                            [Math]::Abs($durValue / 600000000)
                        }
                    } catch { 0 }
                }
            } else { 0 }

            # lockoutWindow: raw negative 100ns interval, or "Not set"/"Never".
            $lockoutWindow = if ($domainPolicy.lockOutObservationWindow -and $domainPolicy.lockOutObservationWindow -notmatch "Not set|Never") {
                if ($domainPolicy.lockOutObservationWindow -match "(\d+)\s+minutes?") {
                    [int]$matches[1]
                } else {
                    try {
                        $windowValue = [int64]$domainPolicy.lockOutObservationWindow
                        if ($windowValue -eq [int64]::MinValue) {
                            0  # "never" sentinel -> displayed as "N/A"
                        } else {
                            [Math]::Abs($windowValue / 600000000)
                        }
                    } catch { 0 }
                }
            } else { 0 }

            # Password Properties - Invoke-LDAPSearch returns flag array (e.g., @("DOMAIN_PASSWORD_COMPLEX"))
            # Check for flags by name instead of bitwise operations
            $pwdPropsValue = $domainPolicy.pwdProperties
            if ($pwdPropsValue -is [array] -or ($pwdPropsValue -is [string] -and $pwdPropsValue -match "DOMAIN_")) {
                # Pre-converted flag names from Invoke-LDAPSearch
                $pwdPropsArray = @($pwdPropsValue)
                $complexityEnabled = $pwdPropsArray -contains "DOMAIN_PASSWORD_COMPLEX"
                $reversibleEncryption = $pwdPropsArray -contains "DOMAIN_PASSWORD_STORE_CLEARTEXT"
            } else {
                # Raw integer value (fallback)
                $pwdPropsInt = if ($pwdPropsValue) { try { [int]$pwdPropsValue } catch { 0 } } else { 0 }
                $complexityEnabled = ($pwdPropsInt -band 1) -ne 0
                $reversibleEncryption = ($pwdPropsInt -band 16) -ne 0
            }

            # Create password policy object for consistent display
            $passwordPolicyObj = [PSCustomObject]@{
                minPwdLength = if ($minPwdLength -eq 0) { "Disabled" } else { "$minPwdLength characters" }
                minPwdAge = if ($minPwdAge -eq 0) { "Disabled" } else { "$minPwdAge days" }
                maxPwdAge = if ($maxPwdAge -eq 0) { "Disabled (Never expires)" } else { "$maxPwdAge days" }
                passwordComplexity = if ($complexityEnabled) { "Enabled" } else { "Disabled" }
                reversibleEncryption = if ($reversibleEncryption) { "Enabled" } else { "Disabled" }
                lockoutThreshold = if ($lockoutThreshold -eq 0) { "Disabled" } else { "After $lockoutThreshold failed attempts" }
                lockoutDuration = if ($lockoutDuration -eq 0) { "Forever (manual unlock)" } else { "$lockoutDuration minutes" }
                lockoutObservationWindow = if ($lockoutWindow -gt 0) { "$lockoutWindow minutes" } else { "N/A" }
            }

            # Determine severity based on policy weaknesses
            # Finding: Short password (<8), no complexity, reversible encryption, no lockout
            # Hint: Moderate weakness (8-13 chars, high lockout threshold)
            # Secure: Good policy
            $policyWeaknesses = @()

            # Check for critical weaknesses (Finding)
            if ($minPwdLength -lt 8) { $policyWeaknesses += "short_password" }
            if (-not $complexityEnabled) { $policyWeaknesses += "no_complexity" }
            if ($reversibleEncryption) { $policyWeaknesses += "reversible_encryption" }

            # Check for moderate weaknesses (Hint)
            $moderateWeaknesses = @()
            if ($minPwdLength -ge 8 -and $minPwdLength -lt 14) { $moderateWeaknesses += "moderate_password_length" }
            if ($lockoutThreshold -eq 0) { $moderateWeaknesses += "no_lockout" }
            if ($lockoutThreshold -gt 10) { $moderateWeaknesses += "high_lockout_threshold" }
            if ($maxPwdAge -eq 0) { $moderateWeaknesses += "password_never_expires" }

            # Determine overall severity
            $policySeverity = if (@($policyWeaknesses).Count -gt 0) {
                "Finding"
            } elseif (@($moderateWeaknesses).Count -gt 0) {
                "Hint"
            } else {
                "Secure"
            }

            Show-Line "Found password policy:" -Class $policySeverity
            $passwordPolicyObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DomainPasswordPolicy' -Force
            Show-Object $passwordPolicyObj

            # ===== Fine-Grained Password Policies (FGPP/PSO) Analysis =====
            Show-SubHeader "Checking for Fine-Grained Password Policies (FGPP)..." -ObjectType "FineGrainedPasswordPolicy"

            # DomainFunctionality might be a string or integer, ensure proper conversion
            $domainFunctionalLevel = 0
            if ($Script:LDAPContext.DomainFunctionality) {
                $dflValue = $Script:LDAPContext.DomainFunctionality
                if ($dflValue -is [int] -or $dflValue -is [long]) {
                    $domainFunctionalLevel = [int]$dflValue
                }
                elseif ($dflValue -is [string]) {
                    # Try to parse as integer
                    $parsed = 0
                    if ([int]::TryParse($dflValue, [ref]$parsed)) {
                        $domainFunctionalLevel = $parsed
                    }
                }
            }
            Write-Log "[Get-DomainPasswordPolicy] Domain Functional Level: $domainFunctionalLevel"

            if ($domainFunctionalLevel -ge 3) {
                # Query Password Settings Container
                $psoContainerDN = "CN=Password Settings Container,CN=System,$domainDN"

                # First check if Password Settings Container exists
                $psoContainerExists = $false
                try {
                    # Use Get-DomainObject to check container existence (no custom SearchBase issues)
                    $containerCheck = Get-DomainObject -Identity $psoContainerDN @PSBoundParameters -ErrorAction SilentlyContinue
                    if ($containerCheck) {
                        $psoContainerExists = $true
                        Write-Log "[Get-DomainPasswordPolicy] Password Settings Container exists"
                    } else {
                        Write-Log "[Get-DomainPasswordPolicy] Password Settings Container does not exist"
                    }
                } catch {
                    Write-Log "[Get-DomainPasswordPolicy] Password Settings Container does not exist (error: $_)"
                }

                if ($psoContainerExists) {
                    try {
                        $psos = Get-DomainObject -LDAPFilter "(objectClass=msDS-PasswordSettings)" -SearchBase $psoContainerDN @PSBoundParameters

                    if (@($psos).Count -gt 0) {
                        Show-Line "Found $(@($psos).Count) Fine-Grained Password Polic$(if(@($psos).Count -eq 1){'y'}else{'ies'}):" -Class Hint

                        foreach ($pso in $psos) {
                            $psoName = $pso.name
                            $precedence = if ($pso.'msDS-PasswordSettingsPrecedence') { [int]$pso.'msDS-PasswordSettingsPrecedence' } else { 999 }
                            $minLength = if ($pso.'msDS-MinimumPasswordLength') { [int]$pso.'msDS-MinimumPasswordLength' } else { 0 }
                            $complexityEnabled = if ($pso.'msDS-PasswordComplexityEnabled') { $pso.'msDS-PasswordComplexityEnabled' -eq 'TRUE' } else { $false }
                            $reversibleEncryption = if ($pso.'msDS-PasswordReversibleEncryptionEnabled') { $pso.'msDS-PasswordReversibleEncryptionEnabled' -eq 'TRUE' } else { $false }
                            $lockoutThresholdPSO = if ($pso.'msDS-LockoutThreshold') { [int]$pso.'msDS-LockoutThreshold' } else { 0 }
                            $appliesTo = if ($pso.'msDS-PSOAppliesTo') { $pso.'msDS-PSOAppliesTo' } else { @() }

                            # Create PSO object for consistent display
                            $psoObj = [PSCustomObject]@{
                                psoName = $psoName
                                precedence = $precedence
                                minPwdLength = if ($minLength -eq 0) { "Disabled" } else { "$minLength characters" }
                                passwordComplexity = if ($complexityEnabled) { "Enabled" } else { "Disabled" }
                                reversibleEncryption = if ($reversibleEncryption) { "Enabled" } else { "Disabled" }
                                lockoutThreshold = if ($lockoutThresholdPSO -eq 0) { "Disabled" } else { "After $lockoutThresholdPSO failed attempts" }
                                appliesTo = "$($appliesTo.Count) user(s)/group(s)"
                            }

                            $psoObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'FineGrainedPasswordPolicy' -Force
                            Show-Object $psoObj
                        }

                        # Output FGPP findings summary
                        $weakPSOCount = @($psos | Where-Object {
                            $psoRE = if ($_.'msDS-PasswordReversibleEncryptionEnabled') { $_.'msDS-PasswordReversibleEncryptionEnabled' -eq 'TRUE' } else { $false }
                            $psoMinLen = if ($_.'msDS-MinimumPasswordLength') { [int]$_.'msDS-MinimumPasswordLength' } else { 0 }
                            $psoComp = if ($_.'msDS-PasswordComplexityEnabled') { $_.'msDS-PasswordComplexityEnabled' -eq 'TRUE' } else { $false }
                            $psoLockout = if ($_.'msDS-LockoutThreshold') { [int]$_.'msDS-LockoutThreshold' } else { 0 }

                            $psoRE -or ($psoMinLen -lt 8) -or (-not $psoComp) -or ($psoLockout -eq 0)
                        }).Count

                        if ($weakPSOCount -gt 0) {
                            Show-Line "Found $weakPSOCount FGPP weakness(es)" -Class Finding
                        } else {
                            Show-Line "Fine-Grained Password Policies are properly configured" -Class Secure
                        }

                    } else {
                        Show-Line "No Fine-Grained Password Policies configured" -Class Note
                    }
                    } catch {
                        Write-Log "[Get-DomainPasswordPolicy] FGPP enumeration failed: $_" -Level Error
                        Write-Warning "[Get-DomainPasswordPolicy] Failed to query Fine-Grained Password Policies: $_"
                    }
                } else {
                    Show-Line "No Fine-Grained Password Policies configured" -Class Note
                }
            } else {
                Show-Line "Fine-Grained Password Policies not available (requires Domain Functional Level 2008+)" -Raw
            }

        } catch {
            Write-Log "[Get-DomainPasswordPolicy] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-DomainPasswordPolicy] Check completed"
    }
}



# ----- Get-DomainTrusts.ps1 -----

function Get-DomainTrusts {
    <#
    .SYNOPSIS
    Enumerates and analyzes domain trust relationships.

    .DESCRIPTION
    Collects comprehensive information about all domain trust relationships including:
    - Trust direction (Bidirectional, Inbound, Outbound)
    - Trust type (ParentChild, TreeRoot, External, Forest)
    - Trust attributes (Transitive, SID Filtering, Quarantined)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-DomainTrusts

    .EXAMPLE
    Get-DomainTrusts -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Domain
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-DomainTrusts] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Searching for domain trusts..." -ObjectType "DomainTrust"

            $trustsRaw = Get-DomainObject -LDAPFilter "(objectClass=trustedDomain)" @PSBoundParameters

            # Filter out self-referencing trust objects (e.g. child domain's trust back to us
            # returned as phantom object from GC, or trust object where trustPartner = own domain)
            $domainDNS = $Script:LDAPContext.DomainDNS
            $trusts = @($trustsRaw) | Where-Object {
                $_.trustPartner -and $_.trustPartner -ne $domainDNS
            }

            if (@($trusts).Count -gt 0) {
                Show-Line "Found $(@($trusts).Count) domain trust(s):" -Class Hint

                foreach ($trust in $trusts) {
                    # trustDirection, trustType and trustAttributes are already decoded
                    # by Invoke-LDAPSearch into readable strings/arrays
                    $direction = $trust.trustDirection
                    $type = $trust.trustType
                    $attrFlags = @($trust.trustAttributes)

                    # Derive boolean flags from decoded trustAttributes array
                    $isBidirectional = ($direction -eq 'Bidirectional')
                    $isTransitive = ($attrFlags -notcontains 'NON_TRANSITIVE')
                    $isQuarantined = ($attrFlags -contains 'QUARANTINED_DOMAIN')
                    $isForestTrust = ($attrFlags -contains 'FOREST_TRANSITIVE')
                    $isCrossOrg = ($attrFlags -contains 'CROSS_ORGANIZATION')
                    $isWithinForest = ($attrFlags -contains 'WITHIN_FOREST')
                    $isTreatAsExternal = ($attrFlags -contains 'TREAT_AS_EXTERNAL')
                    $usesRC4 = ($attrFlags -contains 'USES_RC4_ENCRYPTION')

                    # Create enhanced trust object for Show-Object
                    # No distinguishedName - custom objects without standard AD attributes
                    # use the dynamic fallback in Get-RenderModel for console output
                    $trustObject = [PSCustomObject]@{
                        trustPartner = $trust.trustPartner
                        flatName = $trust.flatName
                        trustDirection = $direction
                        trustType = $type
                        trustAttributes = $attrFlags
                        isBidirectional = $isBidirectional
                        isTransitive = $isTransitive
                        isForestTrust = $isForestTrust
                        isWithinForest = $isWithinForest
                        isQuarantined = $isQuarantined
                        isCrossOrg = $isCrossOrg
                        isTreatAsExternal = $isTreatAsExternal
                        usesRC4 = $usesRC4
                        whenCreated = $trust.whenCreated
                    }

                    $trustObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DomainTrust' -Force
                    Show-Object $trustObject

                }
            }

            if (@($trusts).Count -eq 0) {
                Show-Line "No external domain trusts found (isolated domain)" -Class Note
            }

        } catch {
            Write-Log "[Get-DomainTrusts] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-DomainTrusts] Check completed"
    }
}



# ----- Get-LDAPConfiguration.ps1 -----

function Get-LDAPConfiguration {
    <#
    .SYNOPSIS
    Checks LDAP Security Configuration (Signing + Channel Binding + Anonymous Binding).

    .DESCRIPTION
    Analyzes LDAP security configuration on Domain Controllers:

    1. LDAP Signing: Protects against LDAP Relay attacks
       - None (0): Insecure
       - Optional (1): Partially Secure
       - Required (2): Secure

    2. LDAP Channel Binding: Protection against Man-in-the-Middle
       - Never (0): Insecure
       - When Supported (1): Partially Secure
       - Always (2): Secure

    3. Anonymous LDAP Binding: Prevents unauthenticated AD enumeration
       - Allowed: Insecure
       - Restricted: Secure

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-LDAPConfiguration

    .EXAMPLE
    Get-LDAPConfiguration -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Domain
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-LDAPConfiguration] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Analyzing LDAP Signing/Channel Binding via GPO (SYSVOL)..." -ObjectType "LDAPConfigGPO"

            $domainFQDN = $Script:LDAPContext.Domain
            $dcServer = $Script:LDAPContext.Server

            $allGPOs = Get-DomainGPO @PSBoundParameters

            if (-not $allGPOs) {
                Show-Line "No GPOs found" -Class Hint
                return
            }

            # Get Domain Controllers
            $domainControllers = @(Get-DomainComputer -LDAPFilter "(userAccountControl:1.2.840.113556.1.4.803:=8192)" @PSBoundParameters)

            $dcCount = $domainControllers.Count

            # Use Invoke-SMBAccess for SYSVOL access (handles SimpleBind credentials)
            $Script:gpoFindings = @()
            $Script:sysvolAccessible = $false

            Invoke-SMBAccess -Description "Scanning SYSVOL for LDAP configuration GPOs" -ScriptBlock {
                $sysvolPath = "\\$dcServer\SYSVOL\$domainFQDN\Policies"

                # Test SYSVOL access
                if (-not (Test-Path $sysvolPath)) {
                    Write-Log "[Get-LDAPConfiguration] SYSVOL path not accessible: $sysvolPath"
                    return
                }

                $Script:sysvolAccessible = $true

                # Iterate the cached SYSVOL listing instead of probing a constructed path per GPO:
                # most GPOs have no GptTmpl.inf, so per-GPO probing costs one SMB round-trip each
                # for a file that usually does not exist.
                $gptTmplFiles = @(Get-CachedSYSVOLFiles -Filter "GptTmpl.inf")

                # GPO GUID -> GPO object, to resolve the file back to its GPO
                $gpoByGuid = @{}
                foreach ($g in $allGPOs) {
                    if ($g.Name) { $gpoByGuid[$g.Name.ToUpper()] = $g }
                }

                # Parse GPOs for LDAP Security settings
                $totalGPOs = $gptTmplFiles.Count
                $currentGPOIndex = 0
                foreach ($file in $gptTmplFiles) {
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                    if ($file.FullName -notmatch '\\Policies\\(\{[^}]+\})\\') { continue }
                    $gpo = $gpoByGuid[$Matches[1].ToUpper()]
                    if (-not $gpo) { continue }

                    $currentGPOIndex++
                    if ($totalGPOs -gt $Script:ProgressThreshold) {
                        Show-Progress -Activity "Scanning LDAP configuration GPO settings" -Current $currentGPOIndex -Total $totalGPOs -ObjectName $gpo.DisplayName
                    }

                    $content = Get-CachedSYSVOLContent -Path $file.FullName
                    if ($content) {
                        # Initialize values
                        $ldapSigningValue = $null
                        $ldapChannelBindingValue = $null
                        $restrictAnonymous = $null
                        $lsaAnonymousNameLookup = $null

                        # Parse Registry Values section
                        if ($content -match '(?s)\[Registry Values\](.*?)(\[|$)') {
                            $registrySection = $Matches[1]

                            # GptTmpl.inf format: MACHINE\...\LDAPServerIntegrity=4,<value> (4 = REG_DWORD)
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Services\\NTDS\\Parameters\\LDAPServerIntegrity.*?=.*?4,(\d+)') {
                                $ldapSigningValue = [int]$Matches[1]
                            }
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Services\\NTDS\\Parameters\\LdapEnforceChannelBinding.*?=.*?4,(\d+)') {
                                $ldapChannelBindingValue = [int]$Matches[1]
                            }
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Control\\Lsa\\RestrictAnonymous.*?=.*?4,(\d+)') {
                                $restrictAnonymous = [int]$Matches[1]
                            }
                        }

                        # Parse System Access section
                        if ($content -match '(?s)\[System Access\](.*?)(\[|$)') {
                            $systemAccessSection = $Matches[1]
                            if ($systemAccessSection -match 'LSAAnonymousNameLookup\s*=\s*(\d+)') {
                                $lsaAnonymousNameLookup = [int]$Matches[1]
                            }
                        }

                        # If any LDAP security settings found
                        if ($null -ne $ldapSigningValue -or $null -ne $ldapChannelBindingValue -or
                            $null -ne $restrictAnonymous -or $null -ne $lsaAnonymousNameLookup) {

                            $signingLevel = if ($null -ne $ldapSigningValue) {
                                switch ($ldapSigningValue) {
                                    0 { "None" }
                                    1 { "Optional" }
                                    2 { "Required" }
                                    default { "Unknown" }
                                }
                            } else { "Not Configured" }

                            $channelBindingLevel = if ($null -ne $ldapChannelBindingValue) {
                                switch ($ldapChannelBindingValue) {
                                    0 { "Never" }
                                    1 { "When Supported" }
                                    2 { "Always" }
                                    default { "Unknown" }
                                }
                            } else { "Not Configured" }

                            $anonymousBindingStatus = "Not Configured"
                            if ($null -ne $restrictAnonymous) {
                                $anonymousBindingStatus = if ($restrictAnonymous -eq 0) { "Allowed" } else { "Restricted" }
                            } elseif ($null -ne $lsaAnonymousNameLookup) {
                                $anonymousBindingStatus = if ($lsaAnonymousNameLookup -eq 1) { "Allowed" } else { "Restricted" }
                            }

                            # Get GPO linkage
                            $gpoLinkage = Get-GPOLinkage
                            # Normalize GUID to uppercase for hashtable lookup (Get-GPOLinkage uses uppercase keys)
                            $gpoNameUpper = $gpo.Name.ToUpper()
                            $links = $gpoLinkage[$gpoNameUpper]
                            $activeLinks = @()
                            $isDomainWide = $false
                            $coversDCs = $false

                            if ($links) {
                                $activeLinks = @($links | Where-Object { $_.LinkStatus -ne "Disabled" })
                                $domainWide = $activeLinks | Where-Object { $_.Scope -eq "Domain" }
                                $isDomainWide = ($null -ne $domainWide)

                                # Check if Domain Controllers OU is covered
                                if ($isDomainWide) {
                                    $coversDCs = $true
                                } else {
                                    foreach ($dc in $domainControllers) {
                                        if ($dc.distinguishedName -match '^CN=[^,]+,(.+)$') {
                                            $dcParentDN = $Matches[1]
                                            foreach ($link in $activeLinks) {
                                                # Check if the GPO link DN is an ancestor of the DC's parent OU
                                                # The link DN should be at the end of (or equal to) the DC's parent DN
                                                if ($dcParentDN -like "*$($link.DistinguishedName)" -or $dcParentDN -eq $link.DistinguishedName) {
                                                    $coversDCs = $true
                                                    break
                                                }
                                            }
                                        }
                                        if ($coversDCs) { break }
                                    }
                                }
                            }

                            # Enrich the native GPO object with LDAP security attributes
                            $gpo | Add-Member -NotePropertyName "LDAPSigning" -NotePropertyValue $signingLevel -Force
                            $gpo | Add-Member -NotePropertyName "ChannelBinding" -NotePropertyValue $channelBindingLevel -Force
                            $gpo | Add-Member -NotePropertyName "AnonymousBinding" -NotePropertyValue $anonymousBindingStatus -Force
                            $gpo | Add-Member -NotePropertyName "CoversDCs" -NotePropertyValue $coversDCs -Force

                            # Add LinkedOUs for display (shows where GPO applies)
                            if (@($activeLinks).Count -gt 0) {
                                $linkedOUsDisplay = @($activeLinks | ForEach-Object { $_.DistinguishedName })
                                $gpo | Add-Member -NotePropertyName "LinkedOUs" -NotePropertyValue $linkedOUsDisplay -Force

                                # Determine Scope for display
                                $scopeInfo = if ($isDomainWide) {
                                    "Domain-wide ($(@($activeLinks).Count) link(s))"
                                } else {
                                    "$(@($activeLinks).Count) OU(s)"
                                }
                                $gpo | Add-Member -NotePropertyName "Scope" -NotePropertyValue $scopeInfo -Force
                            } else {
                                $gpo | Add-Member -NotePropertyName "Scope" -NotePropertyValue "NOT LINKED" -Force
                            }

                            $Script:gpoFindings += $gpo
                        }
                    }
                }
                if ($totalGPOs -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Scanning LDAP configuration GPO settings" -Completed
                }
            }

            # Copy findings from script scope
            $gpoFindings = $Script:gpoFindings
            $Script:gpoFindings = $null
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:sysvolAccessible = $null

            # Check if SYSVOL was accessible
            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                } else {
                    Show-Line "SYSVOL access failed - cannot analyze GPO configuration for LDAP Security - SMB access failed (authentication/network issue)" -Class Finding
                }
                return
            }

            if ($gpoFindings -and $gpoFindings.Count -gt 0) {
                # Determine effective GPO per scope:
                # - DC OU / Domain scope: GPO with lowest LinkOrder (= highest priority) wins
                # - Other OUs: GPO is always effective for its own OU
                $gpoLinkage = Get-GPOLinkage
                $scopePriorityEff = @{ "DomainControllers" = 1; "Domain" = 2; "NotLinked" = 3 }

                foreach ($gpoFinding in $gpoFindings) {
                    $guid = $gpoFinding.Name.ToUpper()
                    $linksEff = if ($gpoLinkage) { $gpoLinkage[$guid] } else { $null }
                    $precScope = "NotLinked"; $precOrder = 999

                    if ($linksEff) {
                        $activeLinksEff = @($linksEff | Where-Object { -not $_.IsDisabled })
                        $dcLink  = $activeLinksEff | Where-Object { $_.DistinguishedName -match 'OU=Domain Controllers' } | Sort-Object { if ($_.LinkOrder) { [int]$_.LinkOrder } else { 999 } } | Select-Object -First 1
                        $domLink = $activeLinksEff | Where-Object { $_.Scope -eq "Domain" } | Sort-Object { if ($_.LinkOrder) { [int]$_.LinkOrder } else { 999 } } | Select-Object -First 1
                        if ($dcLink)      { $precScope = "DomainControllers"; $precOrder = if ($dcLink.LinkOrder)  { [int]$dcLink.LinkOrder }  else { 999 } }
                        elseif ($domLink) { $precScope = "Domain";            $precOrder = if ($domLink.LinkOrder) { [int]$domLink.LinkOrder } else { 999 } }
                    }

                    $gpoFinding | Add-Member -NotePropertyName '_PrecedenceScope' -NotePropertyValue $precScope -Force
                    $gpoFinding | Add-Member -NotePropertyName '_PrecedenceOrder' -NotePropertyValue $precOrder -Force
                    $gpoFinding | Add-Member -NotePropertyName 'IsEffectiveSetting' -NotePropertyValue $false -Force
                }

                # For DC OU / Domain scope: mark the single highest-priority GPO as effective
                $dcDomainGPOs = @($gpoFindings | Where-Object { $_._PrecedenceScope -ne "NotLinked" })
                if ($dcDomainGPOs.Count -gt 0) {
                    $effectiveDC = $dcDomainGPOs | Sort-Object @{Expression={$scopePriorityEff[$_._PrecedenceScope]}}, _PrecedenceOrder | Select-Object -First 1
                    if ($effectiveDC) { $effectiveDC.IsEffectiveSetting = $true }
                }

                # For other OUs: each GPO is effective for its own OU
                foreach ($gpoFinding in ($gpoFindings | Where-Object { $_._PrecedenceScope -eq "NotLinked" })) {
                    $gpoFinding.IsEffectiveSetting = $true
                }

                # Show Found message BEFORE data
                Show-Line "Found LDAP security configuration in $($gpoFindings.Count) GPO(s):" -Class Hint
                foreach ($gpoFinding in $gpoFindings) {
                    $gpoFinding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LDAPConfigGPO' -Force
                    Show-Object $gpoFinding
                }

            } else {
                Show-Line "No LDAP Security configuration found in any GPO - all $dcCount DC(s) potentially vulnerable" -Class Finding
            }

        } catch {
            Write-Log "[Get-LDAPConfiguration] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-LDAPConfiguration] Check completed"
    }
}



# ----- Get-SMBSigningStatus.ps1 -----

function Get-SMBSigningStatus {
    <#
    .SYNOPSIS
    Checks SMB Signing configuration status via GPO analysis.

    .DESCRIPTION
    Analyzes SMB Signing configuration by examining GPOs in SYSVOL and calculating coverage across all computer accounts.
    SMB Signing protects against SMB Relay and NTLM Relay attacks.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-SMBSigningStatus

    .EXAMPLE
    Get-SMBSigningStatus -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Domain
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-SMBSigningStatus] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Analyzing SMB Signing configuration via GPO (SYSVOL)..." -ObjectType "SMBSigning"

            $domainFQDN = $Script:LDAPContext.Domain
            $dcServer = $Script:LDAPContext.Server

            $allGPOs = Get-DomainGPO @PSBoundParameters

            if (-not $allGPOs -or @($allGPOs).Count -eq 0) {
                Show-Line "No GPOs found" -Class Note
                return
            }

            # Use Invoke-SMBAccess for SYSVOL access (handles SimpleBind credentials)
            $Script:smbGpoFindings = @()
            $Script:sysvolAccessible = $false

            Invoke-SMBAccess -Description "Scanning SYSVOL for SMB Signing GPOs" -ScriptBlock {
                $sysvolPath = "\\$dcServer\SYSVOL\$domainFQDN\Policies"

                if (-not (Test-Path $sysvolPath)) {
                    Write-Log "[Get-SMBSigningStatus] SYSVOL path not accessible: $sysvolPath"
                    return
                }

                $Script:sysvolAccessible = $true

                # Iterate the cached SYSVOL listing instead of probing a constructed path per GPO:
                # most GPOs have no GptTmpl.inf, so per-GPO probing costs one SMB round-trip each
                # for a file that usually does not exist.
                $gptTmplFiles = @(Get-CachedSYSVOLFiles -Filter "GptTmpl.inf")

                # GPO GUID -> GPO object, to resolve the file back to its GPO
                $gpoByGuid = @{}
                foreach ($g in $allGPOs) {
                    if ($g.Name) { $gpoByGuid[$g.Name.ToUpper()] = $g }
                }

                # Parse GPOs for SMB Signing settings
                $totalGPOs = $gptTmplFiles.Count
                $currentGPOIndex = 0
                foreach ($file in $gptTmplFiles) {
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                    if ($file.FullName -notmatch '\\Policies\\(\{[^}]+\})\\') { continue }
                    $gpoGUID = $Matches[1]
                    $gpo = $gpoByGuid[$gpoGUID.ToUpper()]
                    if (-not $gpo) { continue }

                    $currentGPOIndex++
                    if ($totalGPOs -gt $Script:ProgressThreshold) {
                        Show-Progress -Activity "Scanning SMB signing GPO settings" -Current $currentGPOIndex -Total $totalGPOs -ObjectName $gpo.DisplayName
                    }

                    $content = Get-CachedSYSVOLContent -Path $file.FullName
                    if ($content) {
                        # Look for SMB Signing settings in [Registry Values] section
                        if ($content -match '(?s)\[Registry Values\](.*?)(\[|$)') {
                            $registrySection = $Matches[1]

                            $serverRequire = $null
                            $serverEnable = $null
                            $clientRequire = $null
                            $clientEnable = $null

                            # Server Settings
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Services\\LanmanServer\\Parameters\\RequireSecuritySignature.*?=.*?4,(\d+)') {
                                $serverRequire = [int]$Matches[1]
                            }
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Services\\LanmanServer\\Parameters\\EnableSecuritySignature.*?=.*?4,(\d+)') {
                                $serverEnable = [int]$Matches[1]
                            }

                            # Client Settings
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Services\\LanmanWorkstation\\Parameters\\RequireSecuritySignature.*?=.*?4,(\d+)') {
                                $clientRequire = [int]$Matches[1]
                            }
                            if ($registrySection -match 'MACHINE\\System\\CurrentControlSet\\Services\\LanmanWorkstation\\Parameters\\EnableSecuritySignature.*?=.*?4,(\d+)') {
                                $clientEnable = [int]$Matches[1]
                            }

                            # If any SMB Signing settings found, add to findings
                            if ($null -ne $serverRequire -or $null -ne $serverEnable -or
                                $null -ne $clientRequire -or $null -ne $clientEnable) {

                                # Determine Server Status
                                $serverStatus = if ($null -eq $serverRequire -and $null -eq $serverEnable) {
                                    "Not configured"
                                } elseif ($serverRequire -eq 1) {
                                    "Required"
                                } elseif ($serverEnable -eq 1) {
                                    "Optional"
                                } elseif ($serverRequire -eq 0 -or $serverEnable -eq 0) {
                                    "Disabled"
                                } else {
                                    "Not configured"
                                }

                                # Determine Client Status
                                $clientStatus = if ($null -eq $clientRequire -and $null -eq $clientEnable) {
                                    "Not configured"
                                } elseif ($clientRequire -eq 1) {
                                    "Required"
                                } elseif ($clientEnable -eq 1) {
                                    "Optional"
                                } elseif ($clientRequire -eq 0 -or $clientEnable -eq 0) {
                                    "Disabled"
                                } else {
                                    "Not configured"
                                }

                                # Get GPO linkage
                                $gpoLinkage = Get-GPOLinkage
                                # Normalize GUID to uppercase for hashtable lookup (Get-GPOLinkage uses uppercase keys)
                                $gpoGUIDUpper = $gpoGUID.ToUpper()
                                $links = $gpoLinkage[$gpoGUIDUpper]
                                $activeLinks = @()
                                $isDomainWide = $false

                                if ($links) {
                                    $activeLinks = @($links | Where-Object { $_.LinkStatus -ne "Disabled" })
                                    $domainWide = $activeLinks | Where-Object { $_.Scope -eq "Domain" }
                                    $isDomainWide = ($null -ne $domainWide)
                                }

                                # Enrich the native GPO object with SMB Signing attributes
                                $gpo | Add-Member -NotePropertyName "ServerSigning" -NotePropertyValue $serverStatus -Force
                                $gpo | Add-Member -NotePropertyName "ClientSigning" -NotePropertyValue $clientStatus -Force
                                $gpo | Add-Member -NotePropertyName "IsDomainWide" -NotePropertyValue $isDomainWide -Force

                                # Add LinkedOUs for display (shows where GPO applies)
                                if (@($activeLinks).Count -gt 0) {
                                    $linkedOUsDisplay = @($activeLinks | ForEach-Object { $_.DistinguishedName })
                                    $gpo | Add-Member -NotePropertyName "LinkedOUs" -NotePropertyValue $linkedOUsDisplay -Force

                                    # Determine Scope for display
                                    $scopeInfo = if ($isDomainWide) {
                                        "Domain-wide ($(@($activeLinks).Count) link(s))"
                                    } else {
                                        "$(@($activeLinks).Count) OU(s)"
                                    }
                                    $gpo | Add-Member -NotePropertyName "Scope" -NotePropertyValue $scopeInfo -Force
                                } else {
                                    $gpo | Add-Member -NotePropertyName "Scope" -NotePropertyValue "NOT LINKED" -Force
                                }

                                $Script:smbGpoFindings += $gpo
                            }
                        }
                    }
                }
                if ($totalGPOs -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Scanning SMB signing GPO settings" -Completed
                }
            }

            $gpoFindings = $Script:smbGpoFindings
            $Script:smbGpoFindings = $null
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:sysvolAccessible = $null

            # Check if SYSVOL was accessible
            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                } else {
                    Show-Line "SYSVOL access failed - cannot analyze GPO configuration for SMB Signing - SMB access failed (authentication/network issue)" -Class Finding
                }
                return
            }

            if ($gpoFindings -and @($gpoFindings).Count -gt 0) {
                # Determine effective GPO per scope:
                # - DC OU / Domain scope: GPO with lowest LinkOrder (= highest priority) wins
                # - Other OUs (Servers, Workstations, etc.): GPO is always effective for its own OU
                $gpoLinkageForEff = Get-GPOLinkage
                $scopePriorityEff = @{ "DomainControllers" = 1; "Domain" = 2; "NotLinked" = 3 }

                foreach ($gpoFinding in $gpoFindings) {
                    $guid = $gpoFinding.Name.ToUpper()
                    $linksEff = if ($gpoLinkageForEff) { $gpoLinkageForEff[$guid] } else { $null }
                    $precScope = "NotLinked"; $precOrder = 999

                    if ($linksEff) {
                        $activeLinksEff = @($linksEff | Where-Object { -not $_.IsDisabled })
                        $dcLink  = $activeLinksEff | Where-Object { $_.DistinguishedName -match 'OU=Domain Controllers' } | Sort-Object { if ($_.LinkOrder) { [int]$_.LinkOrder } else { 999 } } | Select-Object -First 1
                        $domLink = $activeLinksEff | Where-Object { $_.Scope -eq "Domain" } | Sort-Object { if ($_.LinkOrder) { [int]$_.LinkOrder } else { 999 } } | Select-Object -First 1
                        if ($dcLink)      { $precScope = "DomainControllers"; $precOrder = if ($dcLink.LinkOrder)  { [int]$dcLink.LinkOrder }  else { 999 } }
                        elseif ($domLink) { $precScope = "Domain";            $precOrder = if ($domLink.LinkOrder) { [int]$domLink.LinkOrder } else { 999 } }
                    }

                    $gpoFinding | Add-Member -NotePropertyName '_PrecedenceScope' -NotePropertyValue $precScope -Force
                    $gpoFinding | Add-Member -NotePropertyName '_PrecedenceOrder' -NotePropertyValue $precOrder -Force
                    $gpoFinding | Add-Member -NotePropertyName 'IsEffectiveSetting' -NotePropertyValue $false -Force
                }

                # For DC OU / Domain scope: mark the single highest-priority GPO as effective
                $dcDomainGPOs = @($gpoFindings | Where-Object { $_._PrecedenceScope -ne "NotLinked" })
                if ($dcDomainGPOs.Count -gt 0) {
                    $effectiveDC = $dcDomainGPOs | Sort-Object @{Expression={$scopePriorityEff[$_._PrecedenceScope]}}, _PrecedenceOrder | Select-Object -First 1
                    if ($effectiveDC) { $effectiveDC.IsEffectiveSetting = $true }
                }

                # For other OUs (Servers, Workstations, etc.): each GPO is effective for its own OU
                # since there are typically no competing SMB Signing GPOs in those OUs
                foreach ($gpoFinding in ($gpoFindings | Where-Object { $_._PrecedenceScope -eq "NotLinked" })) {
                    $gpoFinding.IsEffectiveSetting = $true
                }

                Show-Line "Found SMB Signing configuration in $(@($gpoFindings).Count) GPO(s):" -Class Hint
                foreach ($gpoFinding in $gpoFindings) {
                    $gpoFinding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SMBSigning' -Force
                    Show-Object $gpoFinding
                }

                # Check if SMB Signing is only configured for Domain Controllers
                # This means member servers and clients rely on OS defaults (which vary by version)
                $gpoLinkage = Get-GPOLinkage
                $dcOnlyGPOs = @($gpoFindings | Where-Object {
                    # Normalize GUID to uppercase for hashtable lookup
                    $links = $gpoLinkage[$_.Name.ToUpper()]
                    if (-not $links) { return $false }

                    $activeLinks = @($links | Where-Object { $_.LinkStatus -ne "Disabled" })
                    if ($activeLinks.Count -eq 0) { return $false }

                    # Check if ALL active links are to Domain Controllers OU only
                    $allLinksToDCOU = $true
                    foreach ($link in $activeLinks) {
                        if ($link.DistinguishedName -notmatch 'OU=Domain Controllers') {
                            $allLinksToDCOU = $false
                            break
                        }
                    }
                    return $allLinksToDCOU
                })

                # If ALL SMB Signing GPOs are DC-only, warn about member servers.
                # Use Hint when the DC policy actually requires signing (partially secured).
                # Keep Finding when signing is only Optional or Disabled on DCs.
                if (@($dcOnlyGPOs).Count -eq @($gpoFindings).Count) {
                    $hasRequiredSigning = @($dcOnlyGPOs | Where-Object { $_.ServerSigning -eq 'Required' }).Count -gt 0
                    $dcOnlyClass = if ($hasRequiredSigning) { 'Hint' } else { 'Finding' }
                    Show-Line "SMB Signing only configured for Domain Controllers - Member Servers and Clients rely on OS defaults (varies by version)" -Class $dcOnlyClass
                }

                # Check for insecure configurations and report findings
                $insecureGPOs = @()
                foreach ($gpoFinding in $gpoFindings) {
                    # Server: Disabled or Optional is insecure (allows relay attacks)
                    if ($gpoFinding.ServerSigning -eq "Disabled" -or $gpoFinding.ServerSigning -eq "Optional") {
                        $insecureGPOs += $gpoFinding.DisplayName
                    }
                    # Client: Only flag as insecure if explicitly Disabled
                    elseif ($gpoFinding.ClientSigning -eq "Disabled") {
                        $insecureGPOs += $gpoFinding.DisplayName
                    }
                }

                if ($insecureGPOs.Count -gt 0) {
                    Show-Line "$($insecureGPOs.Count) GPO(s) with insecure SMB Signing configuration" -Class Finding
                }

            } else {
                Show-Line "No SMB Signing configuration found in any GPO - computers rely on OS defaults (varies by Windows version)" -Class Finding
            }

        } catch {
            Write-Log "[Get-SMBSigningStatus] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-SMBSigningStatus] Check completed"
    }
}



# ----- Get-PrivilegedGroupMembers.ps1 -----

function Get-PrivilegedGroupMembers {
    <#
    .SYNOPSIS
    Enumerates members of all privileged Active Directory groups with nested membership analysis.

    .DESCRIPTION
    This check identifies all members in privileged Active Directory groups including:
    - BUILTIN groups (Administrators, Account/Server/Print/Backup Operators, etc.)
    - Domain groups (Domain/Enterprise/Schema Admins, Group Policy Creator Owners, etc.)
    - Dynamic groups (DNS Admins)

    Features:
    - Distinguishes between direct members and nested group membership
    - Tracks nesting level and depth
    - Identifies high-risk nested groups (large membership)
    - Detects deep nesting (>3 levels)
    - Detects Foreign Security Principals (FSPs) from external domains/forests
    - Analyzes AdminSDHolder ACLs for unauthorized permissions
    - Checks Pre-Windows 2000 Compatible Access group for dangerous members

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-PrivilegedGroupMembers

    .EXAMPLE
    Get-PrivilegedGroupMembers -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        Write-Log "[Get-PrivilegedGroupMembers] Starting privileged group enumeration"

        # Built-in privileged groups (well-known SIDs)
        $Script:PrivilegedGroupSIDs = @{
            'S-1-5-32-544' = 'Administrators'
            'S-1-5-32-548' = 'Account Operators'
            'S-1-5-32-549' = 'Server Operators'
            'S-1-5-32-550' = 'Print Operators'
            'S-1-5-32-551' = 'Backup Operators'
            'S-1-5-32-578' = 'Hyper-V Administrators'
            'S-1-5-32-580' = 'Remote Management Users'
        }

        # Domain-specific privileged groups (RIDs)
        $Script:PrivilegedGroupRIDs = @{
            '512' = 'Domain Admins'
            '519' = 'Enterprise Admins'
            '518' = 'Schema Admins'
            '520' = 'Group Policy Creator Owners'
            '526' = 'Key Admins'
            '527' = 'Enterprise Key Admins'
            '517' = 'Cert Publishers'
        }

        # Dynamic groups (no fixed SID - resolve by name)
        $Script:DynamicPrivilegedGroups = @(
            'DnsAdmins'
        )
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                # Return without output to avoid redundant error display
                return
            }

            $AllGroupData = @()
            $TotalUniqueMembers = @{}
            $MembershipPaths = @{}  # Track all paths per member DN
            $Script:AllForeignMembers = @()
            $DomainSID = $Script:LDAPContext.DomainSID
            $domainDN = $Script:LDAPContext.DomainDN

            # ===== Helper Function: Filter GC multi-domain results =====
            # GC port 3268 can return objects from multiple domain partitions
            # (e.g. BUILTIN groups exist in every domain, DnsAdmins by name in parent+child)
            # Always pick only the group from the current domain.
            function Select-LocalDomainGroup {
                param([object]$GroupResult)

                $groups = @($GroupResult)
                if ($groups.Count -le 1) { return $groups | Select-Object -First 1 }

                # Filter to current domain
                if ($domainDN) {
                    $local = $groups | Where-Object { $_.distinguishedName -like "*,$domainDN" }
                    if ($local) {
                        Write-Log "[Get-PrivilegedGroupMembers] GC returned $($groups.Count) results - filtered to current domain"
                        return $local | Select-Object -First 1
                    }
                }

                # Fallback: first result
                Write-Log "[Get-PrivilegedGroupMembers] GC returned $($groups.Count) results - using first"
                return $groups | Select-Object -First 1
            }

            # ===== Helper Function: Recursive Group Member Resolution =====
            function Get-GroupMembersRecursive {
                param(
                    [string]$GroupDN,
                    [string]$GroupName,
                    [int]$NestingLevel = 0,
                    [hashtable]$Visited = @{},
                    [hashtable]$CredentialParams = @{},
                    [string]$MembershipPath = "Direct Member",
                    [object]$GroupObject = $null  # Pass already-fetched group to avoid duplicate query
                )

                # Prevent infinite loops
                if ($Visited.ContainsKey($GroupDN)) {
                    Write-Log "[Get-PrivilegedGroupMembers] Circular reference detected: $GroupDN"
                    return @{
                        DirectMembers = @()
                        NestedGroups = @()
                    }
                }
                $Visited[$GroupDN] = $true

                $DirectMembers = @()
                $NestedGroups = @()

                try {
                    # Use passed group object if available, otherwise fetch it
                    $Group = $GroupObject
                    if (-not $Group) {
                        $Group = @(Get-DomainGroup -Identity $GroupDN @CredentialParams)[0]
                        Write-Log "[Get-PrivilegedGroupMembers] Fetched nested group: $GroupName (DN: $GroupDN)"
                    } else {
                        Write-Log "[Get-PrivilegedGroupMembers] Using pre-fetched group: $GroupName (DN: $GroupDN)"
                    }

                    if (-not $Group) {
                        Write-Log "[Get-PrivilegedGroupMembers] WARNING: Group not found by DN: $GroupDN"
                        return @{ DirectMembers = @(); NestedGroups = @() }
                    }

                    $memberAttr = $Group.member
                    $memberCount = if ($memberAttr) { @($memberAttr).Count } else { 0 }
                    Write-Log "[Get-PrivilegedGroupMembers] Group found: True, Member count: $memberCount"

                    if ($memberAttr) {
                        $MemberDNs = @($Group.member)
                        Write-Log "[Get-PrivilegedGroupMembers] Group '$GroupName' has $($MemberDNs.Count) direct members (Nesting Level: $NestingLevel)"

                        foreach ($MemberDN in $MemberDNs) {
                            # Skip empty/null member DNs (can occur with GC multi-domain results)
                            if ([string]::IsNullOrWhiteSpace($MemberDN)) { continue }

                            # Get member object using Get-DomainObject
                            $Member = @(Get-DomainObject -Identity $MemberDN @CredentialParams)[0]

                            # Cross-domain member resolution: If member not found locally and DN belongs
                            # to a different domain (e.g. parent domain user in child domain group),
                            # try resolving via Global Catalog (port 3268/3269)
                            if (-not $Member -and $domainDN -and -not $MemberDN.EndsWith(",$domainDN")) {
                                Write-Log "[Get-PrivilegedGroupMembers] Cross-domain member detected: $MemberDN - trying GC lookup"
                                try {
                                    $gcConn = Get-GCConnection
                                    if ($gcConn) {
                                        # Use Invoke-LDAPSearch with GC connection for full attribute conversion.
                                        # Escape the member DN (may contain '(' ')' '\,' - e.g. "CN=Doe\, Jane (Contractor),...").
                                        $escapedMemberDN = Escape-LDAPFilterDN -DistinguishedName $MemberDN
                                        $Member = @(Invoke-LDAPSearch -Filter "(&(objectClass=*)(distinguishedName=$escapedMemberDN))" -SizeLimit 1 -LdapConnection $gcConn)[0]
                                        if ($Member) {
                                            Write-Log "[Get-PrivilegedGroupMembers] GC resolved cross-domain member: $($Member.distinguishedName)"
                                        }
                                    }
                                } catch {
                                    Write-Log "[Get-PrivilegedGroupMembers] GC lookup failed for $MemberDN : $_"
                                }
                            }

                            if ($Member) {
                                # Check if member is a group
                                if ($Member.objectClass -icontains "group") {
                                    # Nested group - recurse with updated path
                                    $NewPath = if ($MembershipPath -eq "Direct Member") {
                                        "via $($Member.sAMAccountName)"
                                    } else {
                                        "$MembershipPath ? $($Member.sAMAccountName)"
                                    }

                                    # Pass GC-resolved group object for cross-domain groups to avoid
                                    # local partition lookup failure in recursion
                                    $nestedGroupObj = $null
                                    if ($domainDN -and -not $MemberDN.EndsWith(",$domainDN")) {
                                        $nestedGroupObj = $Member  # GC-resolved object with member attribute
                                    }

                                    $NestedResult = Get-GroupMembersRecursive `
                                        -GroupDN $Member.distinguishedName `
                                        -GroupName $Member.sAMAccountName `
                                        -NestingLevel ($NestingLevel + 1) `
                                        -Visited $Visited `
                                        -CredentialParams $CredentialParams `
                                        -MembershipPath $NewPath `
                                        -GroupObject $nestedGroupObj

                                    # Calculate total member count from nested groups
                                    $NestedTotalCount = $NestedResult.DirectMembers.Count +
                                                        ($NestedResult.NestedGroups | Measure-Object -Property TotalMembers -Sum).Sum

                                    $NestedGroups += [PSCustomObject]@{
                                        GroupName = $Member.sAMAccountName
                                        DistinguishedName = $Member.distinguishedName
                                        NestingLevel = $NestingLevel + 1
                                        DirectMembers = $NestedResult.DirectMembers
                                        NestedGroups = $NestedResult.NestedGroups
                                        TotalMembers = $NestedTotalCount
                                    }
                                } else {
                                    # Direct member (user/computer/FSP)
                                    $IsForeignSecurityPrincipal = $Member.objectClass -icontains 'foreignSecurityPrincipal'

                                    if ($IsForeignSecurityPrincipal) {
                                        # Foreign Security Principal - extract SID from CN
                                        $MemberSID = $null
                                        if ($Member.distinguishedName -match '^CN=([^,]+)') {
                                            $MemberSID = $matches[1]
                                        }

                                        # Resolve SID to account name using central function
                                        $ResolvedName = if ($MemberSID) {
                                            ConvertFrom-SID -SID $MemberSID
                                        } else {
                                            "[FOREIGN - Unknown]"
                                        }

                                        # Check if resolution was successful (not same as SID)
                                        $ResolutionSuccessful = ($ResolvedName -ne $MemberSID)

                                        $MemberInfo = [PSCustomObject]@{
                                            Name = $ResolvedName
                                            SAMAccountName = if ($ResolutionSuccessful) { $ResolvedName.Split('\')[1] } else { "[FOREIGN]" }
                                            ObjectClass = "foreignSecurityPrincipal"
                                            DistinguishedName = $Member.distinguishedName
                                            SID = $MemberSID
                                            ResolvedName = if ($ResolutionSuccessful) { $ResolvedName } else { $null }
                                            NestingLevel = $NestingLevel
                                            IsForeign = $true
                                            MembershipPath = $MembershipPath
                                        }
                                    } else {
                                        # Regular member - determine object type from objectClass array
                                        # Priority: gMSA/sMSA > computer > user (most specific first)
                                        $objectClassArray = @($Member.objectClass)
                                        $detectedClass = 'user'  # Default fallback

                                        if ($objectClassArray -icontains 'msDS-GroupManagedServiceAccount') {
                                            $detectedClass = 'msDS-GroupManagedServiceAccount'
                                        }
                                        elseif ($objectClassArray -icontains 'msDS-ManagedServiceAccount') {
                                            $detectedClass = 'msDS-ManagedServiceAccount'
                                        }
                                        elseif ($objectClassArray -icontains 'computer') {
                                            $detectedClass = 'computer'
                                        }
                                        elseif ($objectClassArray -icontains 'user') {
                                            $detectedClass = 'user'
                                        }

                                        # Detect cross-domain members (resolved via GC, DN not in current domain)
                                        $isCrossDomain = ($domainDN -and -not $MemberDN.EndsWith(",$domainDN"))

                                        $MemberInfo = [PSCustomObject]@{
                                            Name = $Member.name
                                            SAMAccountName = $Member.sAMAccountName
                                            ObjectClass = $detectedClass
                                            DistinguishedName = $Member.distinguishedName
                                            SID = $Member.objectSid
                                            NestingLevel = $NestingLevel
                                            IsForeign = $false
                                            IsCrossDomain = $isCrossDomain
                                            GCObject = if ($isCrossDomain) { $Member } else { $null }
                                            MembershipPath = $MembershipPath
                                        }
                                    }

                                    $DirectMembers += $MemberInfo

                                    # Track foreign members for summary
                                    if ($IsForeignSecurityPrincipal) {
                                        $Script:AllForeignMembers += [PSCustomObject]@{
                                            SID = $MemberSID
                                            ResolvedName = $MemberInfo.ResolvedName
                                            PrivilegedGroup = $GroupName
                                            NestingLevel = $NestingLevel
                                        }
                                    }
                                }
                            }
                        }
                    }
                } catch {
                    Write-Log "[Get-PrivilegedGroupMembers] Error resolving members for $GroupDN : $_"
                }

                return @{
                    DirectMembers = $DirectMembers
                    NestedGroups = $NestedGroups
                }
            }

            # ===== Helper Function: Collect ALL members including from nested groups =====
            function Get-AllMembersFromResult {
                param(
                    [Parameter(Mandatory)]
                    $Result
                )

                $AllMembers = @()

                # Add direct members
                if ($Result.DirectMembers) {
                    $AllMembers += @($Result.DirectMembers)
                }

                # Recursively add members from nested groups
                if ($Result.NestedGroups) {
                    foreach ($NestedGroup in $Result.NestedGroups) {
                        # Each nested group has DirectMembers and NestedGroups properties
                        if ($NestedGroup.DirectMembers) {
                            $AllMembers += @($NestedGroup.DirectMembers)
                        }
                        if ($NestedGroup.NestedGroups) {
                            # Recurse into deeper nested groups
                            $AllMembers += Get-AllMembersFromResult -Result $NestedGroup
                        }
                    }
                }

                return $AllMembers
            }

            # ===== STEP 1: Query Domain-Specific Privileged Groups =====
            Show-SubHeader "Searching for privileged group members..." -ObjectType "PrivilegedGroupMember"

            # Build credential params for recursive calls (only relevant params)
            $CredParams = @{}
            if ($PSBoundParameters.ContainsKey('Domain')) { $CredParams['Domain'] = $Domain }
            if ($PSBoundParameters.ContainsKey('Server')) { $CredParams['Server'] = $Server }
            if ($PSBoundParameters.ContainsKey('Credential')) { $CredParams['Credential'] = $Credential }

            foreach ($RID in $Script:PrivilegedGroupRIDs.Keys) {
                try {
                    $GroupSID = "$DomainSID-$RID"
                    $GroupNameEN = $Script:PrivilegedGroupRIDs[$RID]

                    Write-Log "[Get-PrivilegedGroupMembers] Checking group: $GroupNameEN (SID: $GroupSID)"

                    # Find group by SID using Get-DomainGroup
                    $Group = Select-LocalDomainGroup (Get-DomainGroup -Identity $GroupSID @CredParams)

                    if ($Group) {
                        # Use actual sAMAccountName from AD (localized, e.g. "Domaenen-Admins" in German)
                        $GroupName = $Group.sAMAccountName
                        Write-Log "[Get-PrivilegedGroupMembers] Found group: $GroupName ($($Group.distinguishedName))"

                        # Each top-level group gets its own Visited hashtable to avoid cross-contamination
                        # Pass the already-fetched group object to avoid duplicate LDAP query
                        $Result = Get-GroupMembersRecursive -GroupDN $Group.distinguishedName -GroupName $GroupName -CredentialParams $CredParams -Visited @{} -GroupObject $Group

                        $DirectMemberCount = @($Result.DirectMembers).Count
                        $NestedGroupCount = @($Result.NestedGroups).Count
                        $NestedSum = ($Result.NestedGroups | Measure-Object -Property TotalMembers -Sum).Sum
                        if ($null -eq $NestedSum) { $NestedSum = 0 }
                        $TotalMemberCount = $DirectMemberCount + $NestedSum

                        Write-Log "[Get-PrivilegedGroupMembers] $GroupName - Direct: $DirectMemberCount, Nested groups: $NestedGroupCount, Total: $TotalMemberCount"

                        # Track unique members and their paths (including nested group members)
                        $AllMembersFromGroup = Get-AllMembersFromResult -Result $Result
                        foreach ($Member in $AllMembersFromGroup) {
                            $TotalUniqueMembers[$Member.DistinguishedName] = $Member

                            # Track membership path for this group
                            if (-not $MembershipPaths.ContainsKey($Member.DistinguishedName)) {
                                $MembershipPaths[$Member.DistinguishedName] = @()
                            }
                            if ($Member.MembershipPath -notin $MembershipPaths[$Member.DistinguishedName]) {
                                $MembershipPaths[$Member.DistinguishedName] += $Member.MembershipPath
                            }
                        }

                        # Add group data if it has any members (direct or nested)
                        if ($TotalMemberCount -gt 0) {
                            $AllGroupData += [PSCustomObject]@{
                                GroupName = $GroupName
                                GroupSID = $GroupSID
                                GroupType = "Domain"
                                DirectMemberCount = $DirectMemberCount
                                NestedGroupCount = $NestedGroupCount
                                TotalMemberCount = $TotalMemberCount
                                DirectMembers = $Result.DirectMembers
                                NestedGroups = $Result.NestedGroups
                            }
                        }
                    } else {
                        Write-Log "[Get-PrivilegedGroupMembers] Group not found: $GroupNameEN (SID: $GroupSID)"
                    }
                } catch {
                    Write-Warning "[Get-PrivilegedGroupMembers] Error checking group $GroupNameEN : $_"
                }
            }

            # ===== STEP 2: Query Built-in Privileged Groups =====
            foreach ($SID in $Script:PrivilegedGroupSIDs.Keys) {
                try {
                    $GroupNameEN = $Script:PrivilegedGroupSIDs[$SID]
                    Write-Log "[Get-PrivilegedGroupMembers] Checking built-in group: $GroupNameEN (SID: $SID)"

                    $Group = Select-LocalDomainGroup (Get-DomainGroup -Identity $SID @CredParams)

                    if ($Group) {
                        # Use actual sAMAccountName from AD (localized, e.g. "Administratoren" in German)
                        $GroupName = $Group.sAMAccountName
                        Write-Log "[Get-PrivilegedGroupMembers] Found built-in group: $GroupName ($($Group.distinguishedName))"

                        # Each top-level group gets its own Visited hashtable to avoid cross-contamination
                        # Pass the already-fetched group object to avoid duplicate LDAP query
                        $Result = Get-GroupMembersRecursive -GroupDN $Group.distinguishedName -GroupName $GroupName -CredentialParams $CredParams -Visited @{} -GroupObject $Group

                        $DirectMemberCount = @($Result.DirectMembers).Count
                        $NestedGroupCount = @($Result.NestedGroups).Count
                        $NestedSum = ($Result.NestedGroups | Measure-Object -Property TotalMembers -Sum).Sum
                        if ($null -eq $NestedSum) { $NestedSum = 0 }
                        $TotalMemberCount = $DirectMemberCount + $NestedSum

                        Write-Log "[Get-PrivilegedGroupMembers] $GroupName - Direct: $DirectMemberCount, Nested groups: $NestedGroupCount, Total: $TotalMemberCount"

                        # Track unique members and their paths (including nested group members)
                        $AllMembersFromGroup = Get-AllMembersFromResult -Result $Result
                        foreach ($Member in $AllMembersFromGroup) {
                            $TotalUniqueMembers[$Member.DistinguishedName] = $Member

                            # Track membership path for this group
                            if (-not $MembershipPaths.ContainsKey($Member.DistinguishedName)) {
                                $MembershipPaths[$Member.DistinguishedName] = @()
                            }
                            if ($Member.MembershipPath -notin $MembershipPaths[$Member.DistinguishedName]) {
                                $MembershipPaths[$Member.DistinguishedName] += $Member.MembershipPath
                            }
                        }

                        if ($TotalMemberCount -gt 0) {
                            $AllGroupData += [PSCustomObject]@{
                                GroupName = $GroupName
                                GroupSID = $SID
                                GroupType = "BUILTIN"
                                DirectMemberCount = $DirectMemberCount
                                NestedGroupCount = $NestedGroupCount
                                TotalMemberCount = $TotalMemberCount
                                DirectMembers = $Result.DirectMembers
                                NestedGroups = $Result.NestedGroups
                            }
                        }
                    } else {
                        Write-Log "[Get-PrivilegedGroupMembers] Built-in group not found: $GroupNameEN (SID: $SID)"
                    }
                } catch {
                    Write-Warning "[Get-PrivilegedGroupMembers] Error checking built-in group $GroupNameEN : $_"
                }
            }

            # ===== STEP 3: Query Dynamic Privileged Groups =====
            $domainDN = $Script:LDAPContext.DomainDN
            foreach ($GroupNameDynamic in $Script:DynamicPrivilegedGroups) {
                try {
                    Write-Log "[Get-PrivilegedGroupMembers] Checking dynamic group: $GroupNameDynamic"

                    $Group = Select-LocalDomainGroup (Get-DomainGroup -Identity $GroupNameDynamic @CredParams)

                    if ($Group) {
                        # Use actual sAMAccountName from AD (dynamic groups may have localized names)
                        $GroupName = $Group.sAMAccountName
                        Write-Log "[Get-PrivilegedGroupMembers] Found dynamic group: $GroupName ($($Group.distinguishedName))"

                        # Each top-level group gets its own Visited hashtable to avoid cross-contamination
                        # Pass the already-fetched group object to avoid duplicate LDAP query
                        $Result = Get-GroupMembersRecursive -GroupDN $Group.distinguishedName -GroupName $GroupName -CredentialParams $CredParams -Visited @{} -GroupObject $Group

                        $DirectMemberCount = @($Result.DirectMembers).Count
                        $NestedGroupCount = @($Result.NestedGroups).Count
                        $NestedSum = ($Result.NestedGroups | Measure-Object -Property TotalMembers -Sum).Sum
                        if ($null -eq $NestedSum) { $NestedSum = 0 }
                        $TotalMemberCount = $DirectMemberCount + $NestedSum

                        Write-Log "[Get-PrivilegedGroupMembers] $GroupName - Direct: $DirectMemberCount, Nested groups: $NestedGroupCount, Total: $TotalMemberCount"

                        # Track unique members and their paths (including nested group members)
                        $AllMembersFromGroup = Get-AllMembersFromResult -Result $Result
                        foreach ($Member in $AllMembersFromGroup) {
                            $TotalUniqueMembers[$Member.DistinguishedName] = $Member

                            # Track membership path for this group
                            if (-not $MembershipPaths.ContainsKey($Member.DistinguishedName)) {
                                $MembershipPaths[$Member.DistinguishedName] = @()
                            }
                            if ($Member.MembershipPath -notin $MembershipPaths[$Member.DistinguishedName]) {
                                $MembershipPaths[$Member.DistinguishedName] += $Member.MembershipPath
                            }
                        }

                        if ($TotalMemberCount -gt 0) {
                            $AllGroupData += [PSCustomObject]@{
                                GroupName = $GroupName
                                GroupSID = $Group.objectSid
                                GroupType = "Dynamic"
                                DirectMemberCount = $DirectMemberCount
                                NestedGroupCount = $NestedGroupCount
                                TotalMemberCount = $TotalMemberCount
                                DirectMembers = $Result.DirectMembers
                                NestedGroups = $Result.NestedGroups
                            }
                        }
                    } else {
                        Write-Log "[Get-PrivilegedGroupMembers] Dynamic group not found: $GroupNameDynamic"
                    }
                } catch {
                    Write-Warning "[Get-PrivilegedGroupMembers] Error checking dynamic group $GroupNameDynamic : $_"
                }
            }

            # ===== STEP 4: Build User-Centric View =====
            $TotalGroups = $AllGroupData.Count
            $TotalMembers = $TotalUniqueMembers.Count

            # Count by type for accurate summary message
            $UserCount = 0
            $ComputerCount = 0
            $gMSACount = 0
            $totalMembers = @($TotalUniqueMembers.Values).Count
            $currentIndex = 0

            foreach ($memberData in $TotalUniqueMembers.Values) {
                $currentIndex++

                # Progress indicator for large member counts
                if ($totalMembers -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Analyzing privileged members" -Current $currentIndex -Total $totalMembers -ObjectName $memberData.SAMAccountName
                }

                $objClass = $memberData.ObjectClass
                $samName = $memberData.SAMAccountName

                Write-Log "[Get-PrivilegedGroupMembers] Counting member: $samName, ObjectClass: '$objClass'"

                # gMSA and sMSA are service accounts (specific objectClass)
                if ($objClass -ieq 'msDS-GroupManagedServiceAccount' -or $objClass -ieq 'msDS-ManagedServiceAccount') {
                    $gMSACount++
                    Write-Log "[Get-PrivilegedGroupMembers]   -> Counted as gMSA"
                }
                # Computer accounts (regular computers and DCs)
                elseif ($objClass -ieq 'computer') {
                    $ComputerCount++
                    Write-Log "[Get-PrivilegedGroupMembers]   -> Counted as Computer"
                }
                # User accounts (including foreignSecurityPrincipal)
                elseif ($objClass -ieq 'user' -or $objClass -ieq 'foreignSecurityPrincipal') {
                    $UserCount++
                    Write-Log "[Get-PrivilegedGroupMembers]   -> Counted as User"
                }
                # Fallback: Check sAMAccountName for $ suffix (computer/gMSA indicator)
                elseif ($samName -and $samName.EndsWith('$')) {
                    # Could be computer or gMSA - check for gMSA pattern (often has specific naming)
                    $ComputerCount++
                    Write-Log "[Get-PrivilegedGroupMembers]   -> Counted as Computer ($ suffix fallback)"
                }
                else {
                    # Default to user for unknown types
                    $UserCount++
                    Write-Log "[Get-PrivilegedGroupMembers]   -> Counted as User (default fallback, class was: '$objClass')"
                }
            }

            # Clear progress bar
            if ($totalMembers -gt $Script:ProgressThreshold) {
                Show-Progress -Activity "Analyzing privileged members" -Completed
            }

            Write-Log "[Get-PrivilegedGroupMembers] Count summary: Users=$UserCount, gMSAs=$gMSACount, Computers=$ComputerCount"

            Write-Log "[Get-PrivilegedGroupMembers] AllGroupData contains $TotalGroups groups:"
            foreach ($gd in $AllGroupData) {
                Write-Log "[Get-PrivilegedGroupMembers]   - $($gd.GroupName) (Type: $($gd.GroupType), Members: $($gd.TotalMemberCount))"
            }
            Write-Log "[Get-PrivilegedGroupMembers] TotalUniqueMembers: $TotalMembers"

            # Build per-member group membership tracking
            $MemberGroupMemberships = @{}  # DN -> @{ Groups = @(); DirectGroups = @(); NestedVia = @{} }

            foreach ($GroupData in $AllGroupData) {
                # Helper function to collect all members from nested groups recursively
                function Get-AllMembersWithPaths {
                    param($Members, $NestedGroups, $TopLevelGroup, $ParentPath = $null)

                    $AllMembers = @()

                    # Add direct members
                    foreach ($Member in $Members) {
                        $AllMembers += [PSCustomObject]@{
                            MemberDN = $Member.DistinguishedName
                            MemberInfo = $Member
                            TopLevelGroup = $TopLevelGroup
                            IsDirect = ($null -eq $ParentPath)
                            NestedVia = $ParentPath
                        }
                    }

                    # Recursively add members from nested groups
                    foreach ($NestedGroup in $NestedGroups) {
                        $NewPath = if ($null -eq $ParentPath) {
                            $NestedGroup.GroupName
                        } else {
                            "$ParentPath -> $($NestedGroup.GroupName)"
                        }

                        $NestedMembers = Get-AllMembersWithPaths -Members $NestedGroup.DirectMembers -NestedGroups $NestedGroup.NestedGroups -TopLevelGroup $TopLevelGroup -ParentPath $NewPath
                        $AllMembers += $NestedMembers
                    }

                    return $AllMembers
                }

                # Collect all members for this top-level group
                $AllMembersFlat = Get-AllMembersWithPaths -Members $GroupData.DirectMembers -NestedGroups $GroupData.NestedGroups -TopLevelGroup $GroupData.GroupName

                foreach ($Entry in $AllMembersFlat) {
                    $dn = $Entry.MemberDN
                    if (-not $MemberGroupMemberships.ContainsKey($dn)) {
                        $MemberGroupMemberships[$dn] = @{
                            MemberInfo = $Entry.MemberInfo
                            Groups = @()
                            DirectGroups = @()
                            NestedPaths = @{}
                        }
                    }

                    # Track group membership
                    if ($Entry.TopLevelGroup -notin $MemberGroupMemberships[$dn].Groups) {
                        $MemberGroupMemberships[$dn].Groups += $Entry.TopLevelGroup
                    }

                    if ($Entry.IsDirect) {
                        if ($Entry.TopLevelGroup -notin $MemberGroupMemberships[$dn].DirectGroups) {
                            $MemberGroupMemberships[$dn].DirectGroups += $Entry.TopLevelGroup
                        }
                    } else {
                        if (-not $MemberGroupMemberships[$dn].NestedPaths.ContainsKey($Entry.TopLevelGroup)) {
                            $MemberGroupMemberships[$dn].NestedPaths[$Entry.TopLevelGroup] = @()
                        }
                        if ($Entry.NestedVia -notin $MemberGroupMemberships[$dn].NestedPaths[$Entry.TopLevelGroup]) {
                            $MemberGroupMemberships[$dn].NestedPaths[$Entry.TopLevelGroup] += $Entry.NestedVia
                        }
                    }
                }
            }

            # Show Found message BEFORE user data
            if ($TotalMembers -gt 0) {
                # Build summary message with accurate counts by type
                $summaryParts = @()
                if ($UserCount -gt 0) {
                    $summaryParts += "$UserCount user(s)"
                }
                if ($gMSACount -gt 0) {
                    $summaryParts += "$gMSACount gMSA(s)"
                }
                if ($ComputerCount -gt 0) {
                    $summaryParts += "$ComputerCount computer(s)"
                }
                $summaryText = $summaryParts -join ", "
                Show-Line "Found $summaryText across $TotalGroups privileged group(s):" -Class Finding
            }

            # Output each unique member with full user object
            foreach ($dn in $MemberGroupMemberships.Keys) {
                $MemberData = $MemberGroupMemberships[$dn]
                $BasicInfo = $MemberData.MemberInfo

                # Get full user object for Show-Object
                $FullUserObject = $null

                if ($BasicInfo.IsForeign) {
                    # Foreign Security Principal - create display object
                    $FullUserObject = [PSCustomObject]@{
                        sAMAccountName = if ($BasicInfo.ResolvedName) { "[FOREIGN] $($BasicInfo.ResolvedName)" } else { "[FOREIGN] $($BasicInfo.SID)" }
                        distinguishedName = $BasicInfo.DistinguishedName
                        objectSid = $BasicInfo.SID
                        objectClass = "foreignSecurityPrincipal"
                    }
                } elseif ($BasicInfo.IsCrossDomain -and $BasicInfo.GCObject) {
                    # Cross-domain member resolved via GC - use GC object directly
                    # (local Get-DomainUser/Computer would fail because DN is in another partition)
                    $FullUserObject = $BasicInfo.GCObject
                    Write-Log "[Get-PrivilegedGroupMembers] Using GC-resolved object for cross-domain member: $($BasicInfo.SAMAccountName)"
                } else {
                    # Get full user/computer object with all attributes
                    $FullUserObject = @(Get-DomainUser -Identity $dn @CredParams)[0]

                    if (-not $FullUserObject) {
                        # Might be a computer - try Get-DomainComputer
                        $FullUserObject = @(Get-DomainComputer -Identity $dn @CredParams)[0]
                    }

                    if (-not $FullUserObject) {
                        # Might be a gMSA or other special account type - try Get-DomainObject
                        # gMSAs have objectClass=msDS-GroupManagedServiceAccount, not user/computer
                        $FullUserObject = @(Get-DomainObject -Identity $dn @CredParams)[0]
                    }

                    if (-not $FullUserObject) {
                        # Fallback to basic info
                        $FullUserObject = [PSCustomObject]@{
                            sAMAccountName = $BasicInfo.SAMAccountName
                            distinguishedName = $BasicInfo.DistinguishedName
                        }
                    }
                }

                # Remove memberOf from object to avoid duplication with privilegedGroups
                # The privilegedGroups property below shows the relevant group memberships
                if ($FullUserObject.PSObject.Properties['memberOf']) {
                    $FullUserObject.PSObject.Properties.Remove('memberOf')
                }

                # Build privilege groups with SID for tier classification
                # SID lookup directly from $AllGroupData (no separate hashtable needed)
                $GroupEntries = @()
                foreach ($grp in $MemberData.Groups) {
                    # Find SID from AllGroupData by group name
                    $grpData = $AllGroupData | Where-Object { $_.GroupName -eq $grp } | Select-Object -First 1
                    $grpSID = if ($grpData) { $grpData.GroupSID } else { $null }

                    $displayText = if ($grp -in $MemberData.DirectGroups) {
                        "$grp (direct)"
                    } else {
                        $nestedPath = $MemberData.NestedPaths[$grp] -join ", "
                        "$grp (via $nestedPath)"
                    }
                    $GroupEntries += [PSCustomObject]@{
                        Name = $grp
                        SID = $grpSID
                        DisplayText = $displayText
                    }
                }
                # Add privilegedGroups as array property - Show-Object will format with proper alignment
                $FullUserObject | Add-Member -NotePropertyName 'privilegedGroups' -NotePropertyValue $GroupEntries -Force
                $FullUserObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PrivilegedGroupMember' -Force

                # Pass complete object to Show-Object (includes privilegedGroups)
                # Use -Class Hint: Privileged accounts are informational, not a finding per se
                # Individual problematic attributes (DONT_EXPIRE_PASSWORD, etc.) still show as Finding
                Show-Object $FullUserObject -Class Hint

                # Add blank line between accounts for readability
                Show-EmptyLine
            }

            # Show group summary if no members found
            if ($TotalMembers -eq 0) {
                Show-Line "No members found in privileged groups" -Class Note
            }

            # ===== STEP 5: Check AdminSDHolder ACLs =====
            Show-SubHeader "Checking AdminSDHolder ACLs..." -ObjectType "AdminSDHolderACL"

            $AdminSDHolderFindings = @()
            $DomainDN = $Script:LDAPContext.DomainDN
            $AdminSDHolderDN = "CN=AdminSDHolder,CN=System,$DomainDN"

            try {
                # Use auth-agnostic LDAP pipeline (works with Kerberos PTT, SimpleBind, etc.)
                $AdminSDHolderObj = @(Get-DomainObject -Identity $AdminSDHolderDN -Properties 'nTSecurityDescriptor' -Raw @connectionParams)[0]
                if (-not $AdminSDHolderObj -or -not $AdminSDHolderObj.nTSecurityDescriptor) {
                    Write-Log "[Get-PrivilegedGroupMembers] Could not retrieve AdminSDHolder security descriptor" -Level Error
                    throw "AdminSDHolder security descriptor not available"
                }

                $sdBytes = $AdminSDHolderObj.nTSecurityDescriptor
                $SecurityDescriptor = New-Object System.DirectoryServices.ActiveDirectorySecurity
                $SecurityDescriptor.SetSecurityDescriptorBinaryForm($sdBytes)

                if ($SecurityDescriptor) {
                    # Uses central privileged check from Test-IsPrivileged.ps1

                    # Deduplicate by tracking seen SIDs
                    $SeenSIDs = @{}

                    foreach ($ACE in $SecurityDescriptor.Access) {
                        if ($ACE.AccessControlType -ne 'Allow' -or $ACE.IsInherited) { continue }

                        # Get SID - IdentityReference may be SecurityIdentifier or NTAccount
                        $TrusteeSID = $null
                        $identRef = $ACE.IdentityReference
                        if ($identRef -is [System.Security.Principal.SecurityIdentifier]) {
                            $TrusteeSID = $identRef.Value
                        } else {
                            # NTAccount - use ConvertTo-SID for cross-domain support
                            $TrusteeSID = ConvertTo-SID -Identity $identRef.Value
                        }
                        if (-not $TrusteeSID) { continue }

                        # Skip if already processed this SID
                        if ($SeenSIDs.ContainsKey($TrusteeSID)) { continue }

                        # Skip ACEs with InheritedObjectType - they only apply to child objects, not AdminSDHolder itself
                        $inheritedObjectType = $ACE.InheritedObjectType
                        if ($inheritedObjectType -and $inheritedObjectType -ne [Guid]::Empty) {
                            Write-Log "[Get-PrivilegedGroupMembers] Skipping child-only ACE on AdminSDHolder: Trustee=$TrusteeSID"
                            continue
                        }

                        # Check for dangerous permissions
                        $Rights = $ACE.ActiveDirectoryRights
                        $objectType = $ACE.ObjectType

                        # GenericAll in AD is 0xF01FF (983551)
                        # We need to check if the EXACT GenericAll flag is set, not just if some rights overlap
                        # Also, GenericAll only applies to the whole object if ObjectType is empty
                        $GenericAllValue = [int][System.DirectoryServices.ActiveDirectoryRights]::GenericAll
                        $RightsValue = [int]$Rights

                        # Check if GenericAll is explicitly set (not just overlapping bits)
                        # AND ObjectType must be empty (applies to whole object, not specific attribute)
                        $HasGenericAll = (($RightsValue -band $GenericAllValue) -eq $GenericAllValue) -and
                                         (-not $objectType -or $objectType -eq [Guid]::Empty)

                        # WriteDacl (0x40000) and WriteOwner (0x80000) - only if ObjectType is empty
                        $HasWriteDacl = ($Rights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl) -and
                                        (-not $objectType -or $objectType -eq [Guid]::Empty)
                        $HasWriteOwner = ($Rights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner) -and
                                         (-not $objectType -or $objectType -eq [Guid]::Empty)

                        $HasDangerousPermission = $HasGenericAll -or $HasWriteDacl -or $HasWriteOwner

                        if (-not $HasDangerousPermission) { continue }

                        # Mark as seen
                        $SeenSIDs[$TrusteeSID] = $true

                        # Resolve name for display
                        $TrusteeName = ConvertFrom-SID -SID $TrusteeSID

                        # Determine severity
                        $severity = 'Finding'

                        if (-not $IncludePrivileged) {
                            # Use scope-based check for Domain Root ACL (AdminSDHolder has same expectations)
                            $scopeResult = Test-IsExpectedInScope -Identity $TrusteeSID -Scope 'DomainRootACL' -ReturnDetails

                            if ($scopeResult.Severity -eq 'Expected') {
                                Write-Log "[Get-PrivilegedGroupMembers] AdminSDHolder expected: $TrusteeName - $($scopeResult.Reason)"
                                continue
                            }

                            if ($scopeResult.Severity -eq 'Attention') {
                                Write-Log "[Get-PrivilegedGroupMembers] AdminSDHolder attention: $TrusteeName - $($scopeResult.Reason) - skipped (use -IncludePrivileged to include)"
                                continue
                            }

                            $severity = $scopeResult.Severity
                        } else {
                            # -IncludePrivileged: Show ALL accounts, but mark privileged ones for yellow display
                            $scopeResult = Test-IsExpectedInScope -Identity $TrusteeSID -Scope 'DomainRootACL' -ReturnDetails
                            $severity = $scopeResult.Severity
                            Write-Log "[Get-PrivilegedGroupMembers] IncludePrivileged: Including AdminSDHolder $TrusteeName ($TrusteeSID) with severity $severity"
                        }

                        $Permissions = @()
                        if ($HasGenericAll) { $Permissions += "GenericAll" }
                        if ($HasWriteDacl) { $Permissions += "WriteDacl" }
                        if ($HasWriteOwner) { $Permissions += "WriteOwner" }

                        $finding = [PSCustomObject]@{
                            Name = $TrusteeName
                            Trustee = $TrusteeName
                            TrusteeSID = $TrusteeSID
                            dangerousRights = $Permissions
                        }
                        if ($severity -in @('Expected', 'Attention')) {
                            $finding | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'AdminSDHolderACL' -Force
                        $AdminSDHolderFindings += $finding

                        Show-Object $finding
                    }
                }
            } catch {
                Write-Log "[Get-PrivilegedGroupMembers] Error checking AdminSDHolder: $_" -Level Error
            }

            if (@($AdminSDHolderFindings).Count -eq 0) {
                Show-Line "AdminSDHolder ACLs are secure" -Class Secure
            }

            # ===== STEP 6: Check Pre-Windows 2000 Compatible Access =====
            Show-SubHeader "Checking Pre-Windows 2000 Compatible Access group..." -ObjectType "PreWindows2000Access"

            $PreWin2000Findings = @()
            # Use Well-Known SID S-1-5-32-554 for language-independent lookup
            $PreWin2000SID = 'S-1-5-32-554'

            try {
                $PreWin2000Group = Select-LocalDomainGroup (Get-DomainGroup -Identity $PreWin2000SID @CredParams)

                if ($PreWin2000Group -and $PreWin2000Group.member) {
                    $DangerousSIDs = @{
                        'S-1-1-0' = @{ Name = 'Everyone'; Severity = 'Critical' }
                        'S-1-5-7' = @{ Name = 'Anonymous Logon'; Severity = 'Critical' }
                        'S-1-5-11' = @{ Name = 'Authenticated Users'; Severity = 'High' }
                    }

                    foreach ($MemberDN in $PreWin2000Group.member) {
                        $MemberObj = @(Get-DomainObject -Identity $MemberDN @CredParams)[0]

                        if ($MemberObj -and $MemberObj.objectSid) {
                            if ($DangerousSIDs.ContainsKey($MemberObj.objectSid)) {
                                $DangerousInfo = $DangerousSIDs[$MemberObj.objectSid]
                                $finding = [PSCustomObject]@{
                                    MemberName = $DangerousInfo.Name
                                    MemberSID = $MemberObj.objectSid
                                    Severity = $DangerousInfo.Severity
                                }
                                $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PreWindows2000Access' -Force
                                $PreWin2000Findings += $finding

                                Show-Line "$($DangerousInfo.Name) is a member" -Class Hint
                            }
                        }
                    }
                }

                if (@($PreWin2000Findings).Count -eq 0) {
                    Show-Line "No dangerous members in Pre-Windows 2000 Compatible Access group" -Class Secure
                }
            } catch {
                Write-Log "[Get-PrivilegedGroupMembers] Error checking Pre-Windows 2000 Compatible Access: $_" -Level Error
            }

        } catch {
            Write-Log "[Get-PrivilegedGroupMembers] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-PrivilegedGroupMembers] Privileged group enumeration completed"
    }
}




# ----- Get-ProtectedUsersStatus.ps1 -----

function Get-ProtectedUsersStatus {
    <#
    .SYNOPSIS
    Analyzes Protected Users coverage for Tier-0 accounts.

    .DESCRIPTION
    Evaluates how many true Tier-0 accounts are protected by the "Protected Users" security group.

    Tier-0 Definition (accounts that SHOULD be protected):
    - Domain Admins members
    - Enterprise Admins members (forest root)
    - Schema Admins members (forest root)
    - BUILTIN\Administrators members on DCs

    Excluded from protection metric (cannot use Protected Users):
    - krbtgt (service account)
    - DC$ computer accounts
    - gMSA accounts

    Additionally reports Operator group status (informational):
    - Account Operators
    - Backup Operators
    - Server Operators
    - Print Operators

    Severity based on protection coverage:
    - >80% protected = Secure
    - 20-80% protected = Hint
    - <20% protected = Finding

    Protected Users Security Features:
    - No NTLM, Digest, or CredSSP authentication
    - Kerberos pre-authentication always required (no AS-REP Roasting)
    - Kerberos TGT lifetime limited to 4 hours (instead of 10)
    - No DES/RC4 encryption for Kerberos (AES only)
    - No delegation possible (Unconstrained/Constrained/RBCD)
    - Credential caching disabled

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-ProtectedUsersStatus

    .EXAMPLE
    Get-ProtectedUsersStatus -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ProtectedUsersStatus] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Analyzing Protected Users coverage for Tier-0 accounts..." -ObjectType "Tier0Account"

            $domainDN = $Script:LDAPContext.DomainDN
            $domainSID = $Script:LDAPContext.DomainSID

            # Get Domain Functional Level
            $domainObj = @(Get-DomainObject -Identity $domainDN @PSBoundParameters)[0]

            $functionalLevelValue = if ($domainObj.'msDS-Behavior-Version') { [int]$domainObj.'msDS-Behavior-Version' } else { 0 }

            # Protected Users requires Windows Server 2012 R2 (Level 6) or higher
            if ($functionalLevelValue -lt 6) {
                Show-Line "Protected Users feature not available (requires Domain Functional Level 2012 R2+)" -Class Note
                return
            }

            # ===== Step 1: Get Protected Users group members =====
            $protectedUsersSID = "$domainSID-525"
            Write-Log "[Get-ProtectedUsersStatus] Looking for Protected Users group with SID: $protectedUsersSID"
            $protectedUsersGroup = @(Get-DomainGroup -Identity $protectedUsersSID @PSBoundParameters)[0]

            if (-not $protectedUsersGroup) {
                Show-Line "Protected Users group not found (should exist at this functional level)" -Class Hint
                return
            }

            # Get Protected Users members (SIDs for comparison)
            $protectedMemberSIDs = @{}
            if ($protectedUsersGroup.member) {
                foreach ($memberDN in @($protectedUsersGroup.member)) {
                    $memberObj = @(Get-DomainUser -Identity $memberDN -Properties 'objectSid','sAMAccountName' @PSBoundParameters)[0]
                    if ($memberObj -and $memberObj.objectSid) {
                        $protectedMemberSIDs[$memberObj.objectSid] = $memberObj.sAMAccountName
                    }
                }
            }

            Write-Log "[Get-ProtectedUsersStatus] Found $($protectedMemberSIDs.Count) members in Protected Users group"

            # ===== Step 2: Collect all Tier-0 account members =====
            # Get Tier-0 group SIDs from central definition
            $tier0GroupSIDs = Get-Tier0GroupSIDs -DomainSID $domainSID

            $tier0Accounts = @{}  # SID -> Account object (deduplicated)
            $tier0AccountGroups = @{}  # SID -> Array of group names (for display)

            foreach ($groupSID in $tier0GroupSIDs) {
                $groupObj = @(Get-DomainGroup -Identity $groupSID @PSBoundParameters)[0]

                if (-not $groupObj) {
                    Write-Log "[Get-ProtectedUsersStatus] Group not found: $groupSID"
                    continue
                }

                $groupName = $groupObj.sAMAccountName
                Write-Log "[Get-ProtectedUsersStatus] Processing Tier-0 group: $groupName ($groupSID)"

                # Get recursive members using LDAP_MATCHING_RULE_IN_CHAIN
                $groupDN = $groupObj.distinguishedName
                $escapedDN = $groupDN -replace '\\', '\5c' -replace '\*', '\2a' -replace '\(', '\28' -replace '\)', '\29'

                # Query all users who are (recursively) members of this group
                $members = @(Get-DomainUser -LDAPFilter "(memberOf:1.2.840.113556.1.4.1941:=$escapedDN)" @PSBoundParameters)

                foreach ($member in $members) {
                    if (-not $member.objectSid) { continue }

                    $memberSID = $member.objectSid

                    # Add to deduplicated list
                    if (-not $tier0Accounts.ContainsKey($memberSID)) {
                        $tier0Accounts[$memberSID] = $member
                        $tier0AccountGroups[$memberSID] = @()
                    }

                    # Track which groups this account belongs to
                    $tier0AccountGroups[$memberSID] += $groupName
                }

                # Also add direct group members (Get-DomainGroup returns member DNs)
                if ($groupObj.member) {
                    foreach ($memberDN in @($groupObj.member)) {
                        $memberObj = @(Get-DomainUser -Identity $memberDN @PSBoundParameters)[0]
                        if ($memberObj -and $memberObj.objectSid) {
                            $memberSID = $memberObj.objectSid
                            if (-not $tier0Accounts.ContainsKey($memberSID)) {
                                $tier0Accounts[$memberSID] = $memberObj
                                $tier0AccountGroups[$memberSID] = @()
                            }
                            if ($groupName -notin $tier0AccountGroups[$memberSID]) {
                                $tier0AccountGroups[$memberSID] += $groupName
                            }
                        }
                    }
                }
            }

            Write-Log "[Get-ProtectedUsersStatus] Found $($tier0Accounts.Count) unique Tier-0 accounts"

            # ===== Step 3: Filter out excluded accounts (krbtgt, DCs, gMSAs) =====
            $eligibleAccounts = @{}
            $excludedAccounts = @{}
            $totalTier0 = @($tier0Accounts.Keys).Count
            $currentIndex = 0

            foreach ($sid in $tier0Accounts.Keys) {
                $currentIndex++
                if ($totalTier0 -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Analyzing Tier0 account protection" -Current $currentIndex -Total $totalTier0 -ObjectName $tier0Accounts[$sid].sAMAccountName
                }
                $account = $tier0Accounts[$sid]
                $exclusionCheck = Test-IsExcludedFromProtectedUsers -Account $account

                if ($exclusionCheck.IsExcluded) {
                    $excludedAccounts[$sid] = @{
                        Account = $account
                        Reason = $exclusionCheck.Reason
                    }
                    Write-Log "[Get-ProtectedUsersStatus] Excluded: $($account.sAMAccountName) - $($exclusionCheck.Reason)"
                } else {
                    $eligibleAccounts[$sid] = $account
                }
            }
            if ($totalTier0 -gt $Script:ProgressThreshold) {
                Show-Progress -Activity "Analyzing Tier0 account protection" -Completed
            }

            Write-Log "[Get-ProtectedUsersStatus] Eligible for protection: $($eligibleAccounts.Count), Excluded: $($excludedAccounts.Count)"

            # ===== Step 4: Categorize eligible accounts =====
            $protectedTier0 = @()
            $unprotectedTier0 = @()

            foreach ($sid in $eligibleAccounts.Keys) {
                $account = $eligibleAccounts[$sid]
                $groups = $tier0AccountGroups[$sid] -join ', '

                if ($protectedMemberSIDs.ContainsKey($sid)) {
                    $protectedTier0 += [PSCustomObject]@{
                        Account = $account
                        Groups = $groups
                        IsProtected = $true
                    }
                } else {
                    $unprotectedTier0 += [PSCustomObject]@{
                        Account = $account
                        Groups = $groups
                        IsProtected = $false
                    }
                }
            }

            # ===== Step 5: Calculate coverage and determine severity =====
            $totalEligible = $eligibleAccounts.Count
            $totalProtected = $protectedTier0.Count

            $coveragePercent = if ($totalEligible -gt 0) {
                [math]::Round(($totalProtected / $totalEligible) * 100, 1)
            } else { 0 }

            # Determine severity based on coverage
            $severity = if ($coveragePercent -gt 80) {
                'Secure'
            } elseif ($coveragePercent -ge 20) {
                'Hint'
            } else {
                'Finding'
            }

            # ===== Step 6: Display results =====
            # Show unprotected accounts (the main concern)
            if (@($unprotectedTier0).Count -gt 0) {
                # Combined summary with unprotected count - use "Found" wording for consistency
                $summaryText = "Found $($unprotectedTier0.Count) unprotected Tier-0 account(s) ($totalProtected of $totalEligible in Protected Users, $coveragePercent%):"
                Show-Line $summaryText -Class $severity

                foreach ($item in $unprotectedTier0) {
                    $account = $item.Account
                    # Add tier0Groups property for display
                    $account | Add-Member -NotePropertyName 'tier0Groups' -NotePropertyValue $item.Groups -Force
                    $account | Add-Member -NotePropertyName 'protectedUsersStatus' -NotePropertyValue 'NOT PROTECTED' -Force
                    $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'Tier0Account' -Force
                    $account | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Unprotected' -Force
                    Show-Object $account
                }
            } else {
                # All accounts are protected (100% coverage)
                $summaryText = "Found $totalEligible Tier-0 account(s) - all in Protected Users ($coveragePercent%)"
                Show-Line $summaryText -Class $severity
            }

            # Show protected accounts (good)
            if (@($protectedTier0).Count -gt 0) {
                Show-Line "Protected Tier-0 accounts:" -Class Secure

                foreach ($item in $protectedTier0) {
                    $account = $item.Account
                    $account | Add-Member -NotePropertyName 'tier0Groups' -NotePropertyValue $item.Groups -Force
                    $account | Add-Member -NotePropertyName 'protectedUsersStatus' -NotePropertyValue 'Protected' -Force
                    $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'Tier0Account' -Force
                    $account | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Protected' -Force
                    Show-Object $account
                }
            }

            # Show excluded accounts (informational)
            if (@($excludedAccounts.Keys).Count -gt 0) {
                Show-Line "$($excludedAccounts.Count) account(s) excluded from metric (not applicable for Protected Users):" -Class Note

                foreach ($sid in $excludedAccounts.Keys) {
                    $info = $excludedAccounts[$sid]
                    $account = $info.Account
                    $account | Add-Member -NotePropertyName 'excludedReason' -NotePropertyValue $info.Reason -Force
                    $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'Tier0Account' -Force
                    $account | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Excluded' -Force
                    Show-Object $account
                }
            }

            # ===== Step 7: Operator groups (informational) =====
            # Collect operator groups with members, display as PSCustomObjects
            $operatorFindings = @()

            foreach ($operatorSID in $Script:OperatorSIDs) {
                $operatorGroup = @(Get-DomainGroup -Identity $operatorSID @PSBoundParameters)[0]

                if (-not $operatorGroup) { continue }
                if (-not $operatorGroup.member) { continue }

                $memberCount = @($operatorGroup.member).Count
                if ($memberCount -eq 0) { continue }

                # Get member names and check protection status
                $memberNameList = @()
                $protectedCount = 0

                foreach ($memberDN in @($operatorGroup.member)) {
                    $memberObj = @(Get-DomainUser -Identity $memberDN -Properties 'objectSid' @PSBoundParameters)[0]
                    if ($memberObj -and $memberObj.objectSid) {
                        if ($protectedMemberSIDs.ContainsKey($memberObj.objectSid)) {
                            $protectedCount++
                        }
                        # Resolve SID to DOMAIN\sAMAccountName (handles cross-domain)
                        $resolvedName = ConvertFrom-SID -SID $memberObj.objectSid
                        $memberNameList += $resolvedName
                    } else {
                        # Fallback: extract CN from DN
                        if ($memberDN -match '^CN=([^,]+)') {
                            $memberNameList += $Matches[1]
                        } else {
                            $memberNameList += $memberDN
                        }
                    }
                }

                # Create PSCustomObject for display
                $operatorFindings += [PSCustomObject]@{
                    OperatorGroup = $operatorGroup.sAMAccountName
                    OperatorGroupDN = $operatorGroup.distinguishedName
                    MemberCount = $memberCount
                    ProtectedCount = $protectedCount
                    Members = $memberNameList -join "`n"
                }
            }

            # Only show if there are operator groups with members
            if (@($operatorFindings).Count -gt 0) {
                Show-Line "Operator groups with members (consider for Protected Users):" -Class Hint

                foreach ($finding in $operatorFindings) {
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'OperatorGroup' -Force
                    Show-Object $finding
                }
            }

        } catch {
            Write-Log "[Get-ProtectedUsersStatus] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ProtectedUsersStatus] Check completed"
    }
}



# ----- Get-InactiveAdminAccounts.ps1 -----

function Get-InactiveAdminAccounts {
    <#
    .SYNOPSIS
    Detects inactive privileged user accounts (adminCount=1).

    .DESCRIPTION
    Identifies privileged user accounts (adminCount=1) that have been inactive for an extended period based on lastLogonTimestamp.
    Also detects orphaned admin accounts: accounts with adminCount=1 but no current privileged group memberships (former admins with AdminSDHolder protection).

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER InactiveDays
    Number of days without login to consider an account inactive (default: 180)

    .EXAMPLE
    Get-InactiveAdminAccounts

    .EXAMPLE
    Get-InactiveAdminAccounts -InactiveDays 90

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    Privileged Groups Checked: Uses Test-IsPrivileged with SID-based detection (language-independent)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 180
    )

    begin {
        Write-Log "[Get-InactiveAdminAccounts] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude InactiveDays which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                # Return without output to avoid redundant error display
                return
            }

            Show-SubHeader "Searching for inactive privileged accounts (>$InactiveDays days)..." -ObjectType "InactiveAdmin"

            # Query privileged accounts (adminCount=1), enabled, using optimized filters and filter for inactive accounts using Test-AccountActivity
            $adminAccounts = Get-DomainUser -AdminCount -Enabled @connectionParams

            $inactiveAccounts = @()

            if ($adminAccounts) {
                # Use Test-AccountActivity to filter for inactive accounts
                # -IsInactive: accounts that haven't logged in within InactiveDays
                # -IncludeDetails: adds ActivityDetails property with parsed timestamps
                $inactiveAdmins = @($adminAccounts | Test-AccountActivity -IsInactive -InactiveDays $InactiveDays -IncludeDetails)
                $totalInactive = $inactiveAdmins.Count
                $currentIndex = 0

                foreach ($account in $inactiveAdmins) {
                    $currentIndex++
                    if ($totalInactive -gt $Script:ProgressThreshold) { 
                        Show-Progress -Activity "Processing inactive admin accounts" -Current $currentIndex -Total $totalInactive -ObjectName $account.sAMAccountName
                    }
                    # Get days since logon from Test-AccountActivity
                    $daysSinceLogon = $account.ActivityDetails.DaysSinceActivity

                    # Check if account is orphaned (no privileged groups)
                    # Use SID-based detection via Test-IsPrivileged for language independence
                    $privilegedGroups = @()
                    $isOrphaned = $true

                    if ($account.memberOf) {
                        foreach ($groupDN in $account.memberOf) {
                            # Test-IsPrivileged accepts DN and resolves to SID internally
                            $category = (Test-IsPrivileged -Identity $groupDN -IncludeOperators).Category
                            if ($category -eq 'Privileged') {
                                # Extract group name and resolve SID for proper classification
                                $groupName = if ($groupDN -match '^CN=([^,]+)') { $matches[1] } else { $groupDN }
                                $groupSID = ConvertTo-SID -Identity $groupDN

                                # Use new format with SID for tier classification
                                $privilegedGroups += [PSCustomObject]@{
                                    Name = $groupName
                                    SID = $groupSID
                                    DisplayText = $groupName
                                }
                                $isOrphaned = $false
                            }
                        }
                    }

                    # Add analysis properties to the full account object
                    # Note: privilegedGroups is intentionally NOT added here - memberOf already shows group membership
                    # privilegedGroups is only used in Get-PrivilegedGroupMembers for tier classification
                    $account | Add-Member -NotePropertyName 'daysSinceLastLogon' -NotePropertyValue $daysSinceLogon -Force
                    $account | Add-Member -NotePropertyName 'isOrphaned' -NotePropertyValue $isOrphaned -Force

                    $inactiveAccounts += $account
                }
            }

            # Clear progress bar
            if ($totalInactive -gt $Script:ProgressThreshold) { 
                Show-Progress -Activity "Processing inactive admin accounts" -Completed
            }

            # Output results: summary first, then objects
            if (@($inactiveAccounts).Count -gt 0) {
                $orphanedCount = @($inactiveAccounts | Where-Object { $_.isOrphaned }).Count
                $orphanedInfo = if ($orphanedCount -gt 0) { ", $orphanedCount orphaned (adminCount=1 but no privileged groups)" } else { "" }
                Show-Line "Found $(@($inactiveAccounts).Count) inactive privileged account(s) (>$InactiveDays days$orphanedInfo):" -Class Finding

                foreach ($account in $inactiveAccounts) {
                    $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'InactiveAdmin' -Force
                    Show-Object $account
                }
            } else {
                Show-Line "No inactive privileged accounts found" -Class Secure
            }

        } catch {
            Write-Log "[Get-InactiveAdminAccounts] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-InactiveAdminAccounts] Check completed"
    }
}



# ----- Get-AdminPasswordNeverExpires.ps1 -----

function Get-AdminPasswordNeverExpires {
    <#
    .SYNOPSIS
    Detects privileged accounts with "Password never expires" flag set and stale passwords.

    .DESCRIPTION
    Identifies privileged user accounts where:
    1. Password is configured to never expire (DONT_EXPIRE_PASSWORD flag)
    2. Password has not been changed in over 365 days
    3. Account is verifiably member of privileged groups (not just adminCount=1)

    Uses adminCount=1 as initial filter, then validates actual privilege status via Test-IsPrivileged
    to avoid false positives from orphaned adminCount flags.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER PasswordAgeDays
    Minimum password age in days to report (default: 365)

    .EXAMPLE
    Get-AdminPasswordNeverExpires

    .EXAMPLE
    Get-AdminPasswordNeverExpires -PasswordAgeDays 180

    .EXAMPLE
    Get-AdminPasswordNeverExpires -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [int]$PasswordAgeDays = 365
    )

    begin {
        Write-Log "[Get-AdminPasswordNeverExpires] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude PasswordAgeDays which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                # Return without output to avoid redundant error display
                return
            }

            Show-SubHeader "Searching for privileged accounts with password never expires..." -ObjectType "PasswordNeverExpires"

            # Calculate FileTime for password age threshold
            $thresholdDate = (Get-Date).AddDays(-$PasswordAgeDays)
            $thresholdFileTime = $thresholdDate.ToFileTime()

            # Build LDAP filter for password age (pwdLastSet older than threshold)
            # pwdLastSet=0 means "must change at next logon" - exclude these
            $passwordAgeFilter = "(&(pwdLastSet>=1)(pwdLastSet<=$thresholdFileTime))"

            Write-Log "[Get-AdminPasswordNeverExpires] Password age threshold: $PasswordAgeDays days (before $($thresholdDate.ToString('yyyy-MM-dd')))"

            $candidates = Get-DomainUser -AdminCount -PasswordNeverExpires -LDAPFilter $passwordAgeFilter -ShowOwner @connectionParams

            if (-not $candidates -or @($candidates).Count -eq 0) {
                Show-Line "No privileged accounts with password never expires and password older than $PasswordAgeDays days found" -Class Secure
                return
            }

            Write-Log "[Get-AdminPasswordNeverExpires] Found $(@($candidates).Count) candidate(s) with adminCount=1, verifying actual privilege status..."

            # Verify each candidate is actually privileged (not just orphaned adminCount)
            $vulnerableAccounts = @()
            $totalCandidates = @($candidates).Count
            $currentIndex = 0

            foreach ($user in $candidates) {
                $currentIndex++

                # Progress indicator for large candidate counts
                if ($totalCandidates -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Verifying privileged accounts" `
                                 -Current $currentIndex `
                                 -Total $totalCandidates `
                                 -ObjectName $user.sAMAccountName
                }

                $privCheck = Test-IsPrivileged -Identity $user

                if ($privCheck.IsPrivileged -or $privCheck.Category -eq 'Operator') {
                    # Add privilege information to the user object
                    $user | Add-Member -NotePropertyName 'PrivilegedGroup' -NotePropertyValue $privCheck.MatchedGroup -Force
                    $user | Add-Member -NotePropertyName 'PrivilegeCategory' -NotePropertyValue $privCheck.Category -Force
                    $vulnerableAccounts += $user

                    Write-Log "[Get-AdminPasswordNeverExpires] Verified: $($user.sAMAccountName) is $($privCheck.Category) via $($privCheck.MatchedGroup)"
                } else {
                    Write-Log "[Get-AdminPasswordNeverExpires] Filtered out: $($user.sAMAccountName) has orphaned adminCount (Category: $($privCheck.Category))"
                }
            }

            # Clear progress bar
            if ($totalCandidates -gt $Script:ProgressThreshold) {
                Show-Progress -Activity "Verifying privileged accounts" -Completed
            }

            if ($vulnerableAccounts -and @($vulnerableAccounts).Count -gt 0) {
                Show-Line "Found $(@($vulnerableAccounts).Count) privileged account(s) with password never expires (password > $PasswordAgeDays days old):" -Class Finding

                foreach ($user in $vulnerableAccounts) {
                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordNeverExpires' -Force
                    Show-Object $user
                }
            } else {
                Show-Line "No privileged accounts with password never expires found (filtered $(@($candidates).Count) candidate(s) with orphaned adminCount)" -Class Secure
            }

        } catch {
            Write-Log "[Get-AdminPasswordNeverExpires] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-AdminPasswordNeverExpires] Check completed"
    }
}



# ----- Get-AdminReversibleEncryption.ps1 -----

function Get-AdminReversibleEncryption {
    <#
    .SYNOPSIS
    Detects privileged accounts with "Store Password using Reversible Encryption" enabled.

    .DESCRIPTION
    Identifies privileged user accounts (adminCount=1) where passwords are stored using reversible encryption (ENCRYPTED_TEXT_PWD_ALLOWED flag).

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-AdminReversibleEncryption

    .EXAMPLE
    Get-AdminReversibleEncryption -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-AdminReversibleEncryption] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                # Return without output to avoid redundant error display
                return
            }

            Show-SubHeader "Searching for privileged accounts with reversible encryption..." -ObjectType "ReversibleEncryption"

            # Query privileged accounts (adminCount=1) with ENCRYPTED_TEXT_PWD_ALLOWED flag
            $vulnerableAccounts = Get-DomainUser -AdminCount -ReversibleEncryption -ShowOwner @PSBoundParameters

            if ($vulnerableAccounts -and @($vulnerableAccounts).Count -gt 0) {
                $totalAccounts = @($vulnerableAccounts).Count
                Show-Line "Found $totalAccounts privileged account(s) with reversible password encryption:" -Class Finding

                $currentIndex = 0
                foreach ($user in $vulnerableAccounts) {
                    $currentIndex++

                    # Progress indicator for large account counts
                    if ($totalAccounts -gt $Script:ProgressThreshold) {
                        Show-Progress -Activity "Processing reversible encryption accounts" -Current $currentIndex -Total $totalAccounts -ObjectName $user.sAMAccountName
                    }

                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ReversibleEncryption' -Force
                    Show-Object $user
                }

                # Clear progress bar
                if ($totalAccounts -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Processing reversible encryption accounts" -Completed
                }
            } else {
                Show-Line "No privileged accounts with reversible password encryption found" -Class Secure
            }

        } catch {
            Write-Log "[Get-AdminReversibleEncryption] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-AdminReversibleEncryption] Check completed"
    }
}



# ----- Get-ManagedServiceAccountSecurity.ps1 -----

function Get-ManagedServiceAccountSecurity {
    <#
    .SYNOPSIS
    Analyzes Managed Service Account security configurations.

    .DESCRIPTION
    Identifies security issues with Managed Service Accounts (MSA/gMSA):

    1. gMSA Password Access Analysis:
       - Identifies who can retrieve gMSA passwords via msDS-GroupMSAMembership
       - Flags non-privileged principals with password access (security risk)

    2. gMSA Password Retrieval:
       - Attempts to read msDS-ManagedPassword for each gMSA
       - If successful, displays the NT hash (for authentication)
       - gMSA passwords are 256 random Unicode characters

    3. Standalone MSA Detection:
       - Finds legacy Managed Service Accounts (not gMSA)
       - Standalone MSAs are less secure than gMSAs (single-host, no automatic rotation)

    Security Relevance:
    - gMSA passwords readable by non-privileged accounts = credential theft risk
    - Standalone MSAs lack the security benefits of gMSAs
    - Misconfigured gMSA access can lead to lateral movement

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-ManagedServiceAccountSecurity

    .EXAMPLE
    Get-ManagedServiceAccountSecurity -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Accounts
    Severity: High (if non-privileged gMSA access or standalone MSAs found)
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ManagedServiceAccountSecurity] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Analyzing Managed Service Account security..." -ObjectType "gMSA"

            # ===== Check 1: gMSA Password Access Analysis =====
            Write-Log "[Get-ManagedServiceAccountSecurity] Checking gMSA password access permissions"

            # Get all gMSAs with details (includes msds-groupmsamembership)
            $gmsaAccounts = @(Get-DomainUser -GMSA -ShowGMSADetails @PSBoundParameters |
                Where-Object { $_.objectClass -icontains 'msDS-GroupManagedServiceAccount' })

            if ($gmsaAccounts.Count -gt 0) {
                Write-Log "[Get-ManagedServiceAccountSecurity] Found $($gmsaAccounts.Count) gMSA account(s)"

                $nonPrivilegedAccessFindings = @()

                $totalGMSAs = @($gmsaAccounts).Count
                $currentIndex = 0
                foreach ($gmsa in $gmsaAccounts) {
                    $currentIndex++
                    if ($totalGMSAs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing gMSA security" -Current $currentIndex -Total $totalGMSAs -ObjectName $gmsa.sAMAccountName }
                    $gmsaName = $gmsa.sAMAccountName
                    $groupMsaMembership = $gmsa.'msds-groupmsamembership'

                    if ($groupMsaMembership) {
                        # Parse the security descriptor to get principals with password access
                        $passwordReaders = @()
                        $hasBroadGroupAccess = $false

                        try {
                            # msds-groupmsamembership is a security descriptor in binary format
                            $sdBytes = if ($groupMsaMembership -is [byte[]]) {
                                $groupMsaMembership
                            } elseif ($groupMsaMembership -is [System.DirectoryServices.ResultPropertyValueCollection]) {
                                $groupMsaMembership[0]
                            } else {
                                $null
                            }

                            if ($sdBytes -and $sdBytes -is [byte[]]) {
                                $RawSD = New-Object System.Security.AccessControl.RawSecurityDescriptor($sdBytes, 0)

                                foreach ($ace in $RawSD.DiscretionaryAcl) {
                                    if ($ace.AceType -eq [System.Security.AccessControl.AceType]::AccessAllowed) {
                                        $principalSID = $ace.SecurityIdentifier.Value
                                        $principalName = ConvertFrom-SID -SID $principalSID

                                        # Use central Test-IsPrivileged for consistent classification
                                        $privCheck = Test-IsPrivileged -Identity $principalSID
                                        $category = $privCheck.Category

                                        # BroadGroup = Everyone, Authenticated Users, Domain Users (CRITICAL)
                                        # Privileged = Domain Admins, Enterprise Admins, etc. (expected)
                                        # Operator = Account Operators, Server Operators, etc. (noteworthy)
                                        # Standard = regular accounts (potential issue)
                                        $isPrivileged = $category -in @('Privileged', 'Operator')
                                        $isBroadGroup = $category -eq 'BroadGroup'

                                        if ($isBroadGroup) {
                                            $hasBroadGroupAccess = $true
                                        }

                                        $passwordReaders += [PSCustomObject]@{
                                            Principal = $principalName
                                            SID = $principalSID
                                            Category = $category
                                            IsPrivileged = $isPrivileged
                                            IsBroadGroup = $isBroadGroup
                                        }
                                    }
                                }
                            }
                        } catch {
                            Write-Log "[Get-ManagedServiceAccountSecurity] Failed to parse msDS-GroupMSAMembership for $gmsaName : $_"
                        }

                        # Check for non-privileged principals (includes BroadGroups which are especially critical)
                        $nonPrivReaders = @($passwordReaders | Where-Object { -not $_.IsPrivileged })

                        if ($nonPrivReaders.Count -gt 0) {
                            $nonPrivilegedAccessFindings += [PSCustomObject]@{
                                gMSA = $gmsaName
                                DN = $gmsa.distinguishedName
                                NonPrivilegedReaders = $nonPrivReaders
                                AllReaders = $passwordReaders
                                HasBroadGroupAccess = $hasBroadGroupAccess
                            }
                        }
                    }
                }
                if ($totalGMSAs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing gMSA security" -Completed }

                # Output non-privileged access findings
                if (@($nonPrivilegedAccessFindings).Count -gt 0) {
                    # Count how many have broad group access (critical)
                    $broadGroupCount = @($nonPrivilegedAccessFindings | Where-Object { $_.HasBroadGroupAccess }).Count
                    $broadGroupInfo = if ($broadGroupCount -gt 0) { " ($broadGroupCount with broad group access - CRITICAL)" } else { "" }
                    Show-Line "Found $(@($nonPrivilegedAccessFindings).Count) gMSA(s) with non-privileged password access$broadGroupInfo`:" -Class Finding

                    foreach ($finding in $nonPrivilegedAccessFindings) {
                        # Output the gMSA object itself (Show-Object will display relevant attributes)
                        $gmsaObj = $gmsaAccounts | Where-Object { $_.sAMAccountName -eq $finding.gMSA }
                        $gmsaObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'gMSA' -Force

                        # Context depends on whether broad group access exists
                        $contextText = if ($finding.HasBroadGroupAccess) { 'CRITICAL: Broad group access' } else { 'Non-privileged access' }
                        $gmsaObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue $contextText -Force
                        Show-Object $gmsaObj

                        # Additional context about password readers - highlight broad groups
                        $readerList = ($finding.NonPrivilegedReaders | ForEach-Object {
                            $prefix = if ($_.IsBroadGroup) { "[CRITICAL] " } else { "" }
                            "$prefix$($_.Principal) ($($_.SID))"
                        }) -join ", "
                        Show-Line "Non-privileged password readers: $readerList" -Class Hint
                    }
                } else {
                    Show-Line "All gMSA password access is properly restricted to privileged accounts" -Class Secure
                }

                # ===== Check 2: Attempt to read gMSA passwords =====
                Write-Log "[Get-ManagedServiceAccountSecurity] Attempting to read gMSA passwords"
                Show-SubHeader "Checking gMSA password access for current user..." -ObjectType "gMSAPassword"

                $passwordsRetrieved = 0

                $totalGMSAs = @($gmsaAccounts).Count
                $currentIndex = 0
                foreach ($gmsa in $gmsaAccounts) {
                    $currentIndex++
                    if ($totalGMSAs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing gMSA security" -Current $currentIndex -Total $totalGMSAs -ObjectName $gmsa.sAMAccountName }
                    $gmsaName = $gmsa.sAMAccountName
                    $gmsaDN = $gmsa.distinguishedName

                    Write-Log "[Get-ManagedServiceAccountSecurity] Attempting to read password for $gmsaName"

                    try {
                        # Query msDS-ManagedPassword - this is a constructed attribute
                        # Only returned if the caller has permission to read it
                        $gmsaWithPassword = @(Get-DomainUser -Identity $gmsaName -Properties 'msDS-ManagedPassword' @PSBoundParameters)[0]

                        $managedPasswordBlob = $gmsaWithPassword.'msDS-ManagedPassword'

                        if ($managedPasswordBlob) {
                            # Handle different return types
                            $passwordBytes = $null
                            if ($managedPasswordBlob -is [byte[]]) {
                                $passwordBytes = $managedPasswordBlob
                            } elseif ($managedPasswordBlob -is [System.DirectoryServices.ResultPropertyValueCollection]) {
                                $passwordBytes = $managedPasswordBlob[0]
                            } elseif ($managedPasswordBlob.GetType().Name -eq 'Object[]' -and $managedPasswordBlob.Count -gt 0) {
                                $passwordBytes = $managedPasswordBlob[0]
                            }

                            if ($passwordBytes -and $passwordBytes -is [byte[]] -and $passwordBytes.Length -gt 0) {
                                # Parse the password blob
                                $parsedPassword = ConvertFrom-ManagedPassword -Blob $passwordBytes

                                if ($parsedPassword -and $parsedPassword.CurrentNTHash) {
                                    $passwordsRetrieved++

                                    Show-Line "Successfully retrieved password for gMSA: $gmsaName" -Class Finding

                                    # Create gMSA password object for consistent display
                                    $queryHours = [Math]::Round($parsedPassword.QueryPasswordInterval.TotalHours, 1)
                                    $unchangedHours = [Math]::Round($parsedPassword.UnchangedPasswordInterval.TotalHours, 1)

                                    $gmsaPasswordObj = [PSCustomObject]@{
                                        sAMAccountName = $gmsaName
                                        distinguishedName = $gmsaDN
                                        ntHash = $parsedPassword.CurrentNTHash
                                    }

                                    if ($parsedPassword.PreviousNTHash) {
                                        $gmsaPasswordObj | Add-Member -NotePropertyName 'previousNTHash' -NotePropertyValue $parsedPassword.PreviousNTHash
                                    }

                                    $gmsaPasswordObj | Add-Member -NotePropertyName 'queryInterval' -NotePropertyValue "$queryHours hours"
                                    $gmsaPasswordObj | Add-Member -NotePropertyName 'unchangedInterval' -NotePropertyValue "$unchangedHours hours"
                                    $gmsaPasswordObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'gMSAPassword' -Force

                                    Show-Object $gmsaPasswordObj

                                    Show-Line "Use NT hash with: Pass-the-Hash, Overpass-the-Hash, or DCSync impersonation" -Class Hint
                                    Show-EmptyLine
                                } else {
                                    Write-Log "[Get-ManagedServiceAccountSecurity] Failed to parse password blob for $gmsaName"
                                }
                            } else {
                                Write-Log "[Get-ManagedServiceAccountSecurity] Password blob is empty or invalid type for $gmsaName"
                            }
                        } else {
                            Write-Log "[Get-ManagedServiceAccountSecurity] No msDS-ManagedPassword returned for $gmsaName (access denied or not available)"
                        }
                    } catch {
                        Write-Log "[Get-ManagedServiceAccountSecurity] Error reading password for $gmsaName : $_"
                    }
                }
                if ($totalGMSAs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing gMSA security" -Completed }

                if ($passwordsRetrieved -eq 0) {
                    Show-Line "Current user cannot retrieve any gMSA passwords" -Class Note
                } else {
                    Show-Line "Retrieved $passwordsRetrieved of $($gmsaAccounts.Count) gMSA password(s)" -Class Finding
                }

                # Output all gMSAs for visibility (they will show adminCount, delegation, SPNs via Show-Object)
                $gmsasWithoutFindings = @($gmsaAccounts | Where-Object {
                    $_.sAMAccountName -notin ($nonPrivilegedAccessFindings | ForEach-Object { $_.gMSA })
                })

                if ($gmsasWithoutFindings.Count -gt 0) {
                    Show-SubHeader "gMSA accounts with proper password access configuration:" -ObjectType "gMSAPassword"
                    foreach ($gmsa in $gmsasWithoutFindings) {
                        $gmsa | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'gMSA' -Force
                        Show-Object $gmsa
                    }
                }
            } else {
                Show-Line "No gMSA accounts found in domain" -Class Note
            }

            # ===== Check 3: Standalone MSA Detection =====
            Write-Log "[Get-ManagedServiceAccountSecurity] Checking for standalone MSAs"

            # Get all MSAs (not gMSAs) - these are legacy standalone MSAs
            $standaloneMSAs = @(Get-DomainUser -GMSA @PSBoundParameters |
                Where-Object {
                    $_.objectClass -icontains 'msDS-ManagedServiceAccount' -and
                    $_.objectClass -inotcontains 'msDS-GroupManagedServiceAccount'
                })

            if ($standaloneMSAs.Count -gt 0) {
                Show-Line "Found $($standaloneMSAs.Count) standalone MSA(s) (legacy, less secure than gMSA):" -Class Finding

                foreach ($msa in $standaloneMSAs) {
                    $msa | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'MSA' -Force
                    Show-Object $msa
                }

                Show-Line "Recommendation: Migrate standalone MSAs to gMSAs for improved security" -Class Hint
            } else {
                Show-Line "No standalone MSAs found" -Class Note
            }

        } catch {
            Write-Log "[Get-ManagedServiceAccountSecurity] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ManagedServiceAccountSecurity] Check completed"
    }
}



# ----- Get-SIDHistoryInjection.ps1 -----

function Get-SIDHistoryInjection {
    <#
    .SYNOPSIS
    Detects accounts with privileged SIDs in sIDHistory (SID History Injection attack vector).

    .DESCRIPTION
    Identifies user and computer accounts that have privileged SIDs stored in their sIDHistory attribute.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER IncludeNonPrivileged
    Also report accounts with non-privileged SIDs in sIDHistory (migration artifacts)

    .EXAMPLE
    Get-SIDHistoryInjection

    .EXAMPLE
    Get-SIDHistoryInjection -IncludeNonPrivileged

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludeNonPrivileged
    )

    begin {
        Write-Log "[Get-SIDHistoryInjection] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludeNonPrivileged which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for SID History Injection (privileged SIDs in sIDHistory)..." -ObjectType "SIDHistory"

            # Query all objects with sIDHistory attribute set
            $objectsWithSIDHistory = Get-DomainObject -LDAPFilter "(sIDHistory=*)" @connectionParams

            $privilegedFindings = @()
            $nonPrivilegedFindings = @()

            if ($objectsWithSIDHistory) {
                Write-Log "[Get-SIDHistoryInjection] Found $(@($objectsWithSIDHistory).Count) object(s) with sIDHistory"

                $totalObjects = @($objectsWithSIDHistory).Count
                $currentIndex = 0
                foreach ($obj in $objectsWithSIDHistory) {
                    $currentIndex++
                    if ($totalObjects -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking SID history" -Current $currentIndex -Total $totalObjects -ObjectName $obj.sAMAccountName }
                    $sidHistoryRaw = @($obj.sIDHistory)
                    $privilegedSIDs = @()
                    $nonPrivilegedSIDs = @()

                    foreach ($sidEntry in $sidHistoryRaw) {
                        # Convert byte array to SID string if needed
                        $sidString = $null
                        if ($sidEntry -is [byte[]]) {
                            try {
                                $secId = New-Object System.Security.Principal.SecurityIdentifier($sidEntry, 0)
                                $sidString = $secId.Value
                            } catch {
                                Write-Log "[Get-SIDHistoryInjection] Failed to convert sIDHistory byte array: $_"
                                continue
                            }
                        } elseif ($sidEntry -is [string]) {
                            $sidString = $sidEntry
                        } else {
                            continue
                        }

                        if (-not $sidString) { continue }

                        # Check if this sIDHistory SID is privileged
                        $privilegeCheck = Test-IsPrivileged -Identity $sidString -IncludeOperators
                        $resolvedName = ConvertFrom-SID -SID $sidString

                        $sidInfo = [PSCustomObject]@{
                            SID = $sidString
                            ResolvedName = if ($resolvedName -and $resolvedName -ne $sidString) { $resolvedName } else { "[Unresolved]" }
                            Category = $privilegeCheck.Category
                            Reason = $privilegeCheck.Reason
                        }

                        if ($privilegeCheck.Category -in @('Privileged', 'Operator')) {
                            $privilegedSIDs += $sidInfo
                            Write-Log "[Get-SIDHistoryInjection] $($obj.sAMAccountName) has privileged SID in sIDHistory: $sidString ($resolvedName)"
                        } else {
                            $nonPrivilegedSIDs += $sidInfo
                            Write-Log "[Get-SIDHistoryInjection] $($obj.sAMAccountName) has non-privileged SID in sIDHistory: $sidString"
                        }
                    }

                    # Add findings
                    if (@($privilegedSIDs).Count -gt 0) {
                        # Format privileged SIDs for display
                        $privilegedSIDsDisplay = ($privilegedSIDs | ForEach-Object {
                            if ($_.ResolvedName -ne "[Unresolved]") {
                                "$($_.ResolvedName) ($($_.SID))"
                            } else {
                                $_.SID
                            }
                        }) -join ", "

                        $obj | Add-Member -NotePropertyName 'privilegedSIDHistory' -NotePropertyValue $privilegedSIDsDisplay -Force
                        $obj | Add-Member -NotePropertyName 'privilegedSIDHistoryCount' -NotePropertyValue @($privilegedSIDs).Count -Force
                        $obj | Add-Member -NotePropertyName 'sidHistoryInjectionRisk' -NotePropertyValue "CRITICAL" -Force

                        $privilegedFindings += $obj
                    }

                    if ($IncludeNonPrivileged -and @($nonPrivilegedSIDs).Count -gt 0 -and @($privilegedSIDs).Count -eq 0) {
                        # Only add to non-privileged if no privileged SIDs found (avoid duplicates)
                        $nonPrivilegedSIDsDisplay = ($nonPrivilegedSIDs | ForEach-Object {
                            if ($_.ResolvedName -ne "[Unresolved]") {
                                "$($_.ResolvedName) ($($_.SID))"
                            } else {
                                $_.SID
                            }
                        }) -join ", "

                        $obj | Add-Member -NotePropertyName 'nonPrivilegedSIDHistory' -NotePropertyValue $nonPrivilegedSIDsDisplay -Force
                        $obj | Add-Member -NotePropertyName 'sIDHistoryCount' -NotePropertyValue $nonPrivilegedSIDs.Count -Force

                        $nonPrivilegedFindings += $obj
                    }
                }
            }
            if ($totalObjects -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking SID history" -Completed }

            # Output results
            if (@($privilegedFindings).Count -gt 0) {
                Show-Line "Found $(@($privilegedFindings).Count) account(s) with PRIVILEGED SIDs in sIDHistory (SID History Injection):" -Class Finding

                foreach ($finding in $privilegedFindings) {
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SIDHistory' -Force
                    $finding | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Privileged' -Force
                    Show-Object $finding
                }
            } else {
                Show-Line "No accounts with privileged SIDs in sIDHistory found" -Class Secure
            }

            # Non-privileged findings (migration artifacts) - only if requested
            if ($IncludeNonPrivileged -and @($nonPrivilegedFindings).Count -gt 0) {
                Show-SubHeader "Migration artifacts (non-privileged sIDHistory)..." -ObjectType "SIDHistory"
                Show-Line "Found $(@($nonPrivilegedFindings).Count) account(s) with non-privileged SIDs in sIDHistory (migration artifacts):" -Class Hint

                foreach ($finding in $nonPrivilegedFindings) {
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SIDHistory' -Force
                    $finding | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Migration' -Force
                    Show-Object $finding
                }
            }

        } catch {
            Write-Log "[Get-SIDHistoryInjection] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-SIDHistoryInjection] Check completed"
    }
}



# ----- Get-NonDefaultUserOwners.ps1 -----

function Get-NonDefaultUserOwners {
    <#
    .SYNOPSIS
    Identifies user accounts with non-default owners.

    .DESCRIPTION
    Enumerates all user accounts and checks if the owner of the security descriptor is different from the expected default (Domain Admins).

    Non-default ownership can indicate:
    - User created by a non-admin (e.g., via delegation)
    - Ownership changed post-creation
    - Potential for privilege escalation (owner has implicit control)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER IncludeHealthMailboxes
    Include Exchange Health Mailboxes in output. By default, these are filtered out as they are
    expected to be owned by the Exchange server that created them.

    .EXAMPLE
    Get-NonDefaultUserOwners

    .EXAMPLE
    Get-NonDefaultUserOwners -Domain "contoso.com" -Credential (Get-Credential)

    .EXAMPLE
    Get-NonDefaultUserOwners -IncludeHealthMailboxes

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludeHealthMailboxes,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC
    )

    begin {
        Write-Log "[Get-NonDefaultUserOwners] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludeHealthMailboxes which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for users with non-default owners..." -ObjectType "NonDefaultOwner"

            # OPSEC mode: Skip heavy-load enumeration
            if ($OPSEC) {
                Show-Line "OPSEC mode: Skipping user owner enumeration (would check all enabled users)" -Class "Hint"
                return
            }

            # Step 1: Bulk-load all enabled users with owner info in a single LDAP query
            # -ShowOwner adds nTSecurityDescriptor to the query and extracts Owner/OwnerSID clientside
            # -Properties 'distinguishedName' keeps network traffic minimal (only DN + nTSecurityDescriptor)
            $usersWithOwner = @(Get-DomainUser -Enabled -ShowOwner -Properties 'distinguishedName' @connectionParams)

            Write-Log "[Get-NonDefaultUserOwners] Found $($usersWithOwner.Count) enabled users, filtering non-default owners clientside..."

            $nonDefaultOwnerUsers = @()
            $nonDefaultOwnerDNs = @()
            $filteredHealthMailboxes = 0
            $currentIndex = 0
            $totalUsers = $usersWithOwner.Count

            foreach ($user in $usersWithOwner) {
                $currentIndex++

                # Progress indicator for large user counts
                if ($totalUsers -gt 50) {
                    Show-Progress -Activity "Checking user owners" -Current $currentIndex -Total $totalUsers
                }

                # Check if owner is non-default (clientside, no LDAP)
                if ($user.OwnerSID -and -not (Test-IsDefaultOwner -SID $user.OwnerSID)) {
                    $dn = if ($user.distinguishedName -is [array]) { $user.distinguishedName[0] } else { $user.distinguishedName }

                    # Filter Exchange Health Mailboxes by default (check DN pattern early to avoid unnecessary full-load)
                    if (-not $IncludeHealthMailboxes) {
                        if ($dn -like '*,CN=Monitoring Mailboxes,CN=Microsoft Exchange System Objects,*') {
                            $filteredHealthMailboxes++
                            Write-Log "[Get-NonDefaultUserOwners] Filtered Exchange Health Mailbox: $dn"
                            continue
                        }
                    }

                    $nonDefaultOwnerDNs += [PSCustomObject]@{
                        DN = $dn
                        Owner = $user.Owner
                        OwnerSID = $user.OwnerSID
                    }
                }
            }

            # Clear progress bar
            if ($totalUsers -gt 50) {
                Show-Progress -Activity "Checking user owners" -Completed
            }

            Write-Log "[Get-NonDefaultUserOwners] Found $($nonDefaultOwnerDNs.Count) user(s) with non-default owners, loading full objects..."

            # Step 2: Only for findings, fetch full user objects for Show-Object display
            $totalFindings = $nonDefaultOwnerDNs.Count
            $currentIndex = 0
            foreach ($finding in $nonDefaultOwnerDNs) {
                $currentIndex++
                if ($totalFindings -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Loading user details" -Current $currentIndex -Total $totalFindings
                }

                $fullUser = @(Get-DomainUser -Identity $finding.DN @connectionParams)[0]

                if ($fullUser) {
                    # HealthMailbox sAMAccountName check (DN pattern already filtered above)
                    if (-not $IncludeHealthMailboxes) {
                        if ($fullUser.sAMAccountName -like 'HealthMailbox*') {
                            $filteredHealthMailboxes++
                            Write-Log "[Get-NonDefaultUserOwners] Filtered Exchange Health Mailbox: $($fullUser.sAMAccountName)"
                            continue
                        }
                    }

                    # Add owner info to user object for display
                    $fullUser | Add-Member -NotePropertyName 'Owner' -NotePropertyValue $finding.Owner -Force
                    $fullUser | Add-Member -NotePropertyName 'OwnerSID' -NotePropertyValue $finding.OwnerSID -Force
                    $nonDefaultOwnerUsers += $fullUser
                }
            }

            if ($totalFindings -gt $Script:ProgressThreshold) {
                Show-Progress -Activity "Loading user details" -Completed
            }

            # Output results
            if (@($nonDefaultOwnerUsers).Count -gt 0) {
                Show-Line "Found $(@($nonDefaultOwnerUsers).Count) user(s) with non-default owners:" -Class Finding

                foreach ($user in $nonDefaultOwnerUsers) {
                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'NonDefaultOwner' -Force
                    Show-Object $user
                }

            } else {
                if ($filteredHealthMailboxes -gt 0) {
                    Show-Line "All users have default owners (filtered $filteredHealthMailboxes Exchange Health Mailboxes)" -Class Secure
                } else {
                    Show-Line "All users have default owners" -Class Secure
                }
            }

        } catch {
            Write-Log "[Get-NonDefaultUserOwners] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-NonDefaultUserOwners] Check completed"
    }
}



# ----- Get-PasswordNotRequired.ps1 -----

function Get-PasswordNotRequired {
    <#
    .SYNOPSIS
    Detects enabled user accounts with the PASSWD_NOTREQD flag set.

    .DESCRIPTION
    Identifies enabled user accounts where the "Password Not Required" (PASSWD_NOTREQD, UAC bit 32) flag is set.
    This flag allows the account to have an empty password, bypassing the domain password policy.
    While the flag alone does not guarantee an empty password (a password may have been set later), it indicates a hygiene issue and potential security risk.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-PasswordNotRequired

    .EXAMPLE
    Get-PasswordNotRequired -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Accounts
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-PasswordNotRequired] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Searching for enabled accounts with 'Password Not Required' flag..." -ObjectType "PasswordNotRequired"

            # Query enabled user accounts with PASSWD_NOTREQD flag (UAC bit 32)
            $accounts = Get-DomainUser -Enabled -PasswordNotRequired -ShowOwner @PSBoundParameters

            if ($accounts -and @($accounts).Count -gt 0) {
                $totalAccounts = @($accounts).Count
                Show-Line "Found $totalAccounts enabled account(s) with 'Password Not Required' flag (PASSWD_NOTREQD)" -Class Hint

                $currentIndex = 0
                foreach ($user in $accounts) {
                    $currentIndex++
                    if ($totalAccounts -gt $Script:ProgressThreshold) { Show-Progress -Activity "Processing accounts without password requirement" -Current $currentIndex -Total $totalAccounts -ObjectName $user.sAMAccountName }
                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordNotRequired' -Force
                    Show-Object $user
                }
                if ($totalAccounts -gt $Script:ProgressThreshold) { Show-Progress -Activity "Processing accounts without password requirement" -Completed }
            } else {
                Show-Line "No enabled accounts with 'Password Not Required' flag found" -Class Secure
            }

        } catch {
            Write-Log "[Get-PasswordNotRequired] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-PasswordNotRequired] Check completed"
    }
}



# ----- Get-UnconstrainedDelegation.ps1 -----

function Get-UnconstrainedDelegation {
    <#
    .SYNOPSIS
    Identifies accounts with Unconstrained Delegation enabled.

    .DESCRIPTION
    Detects computer and user accounts configured with Unconstrained Delegation, that allows a service to impersonate any user to any service.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-UnconstrainedDelegation

    .EXAMPLE
    Get-UnconstrainedDelegation -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Delegation
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-UnconstrainedDelegation] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Searching for accounts with Unconstrained Delegation..." -ObjectType "UnconstrainedDelegation"

            $unconstrainedComputers = @(Get-DomainComputer -Unconstrained -Enabled -ShowOwner @PSBoundParameters)
            $unconstrainedUsers = @(Get-DomainUser -Unconstrained -Enabled -ShowOwner @PSBoundParameters)

            $unconstrainedAccounts = $unconstrainedComputers + $unconstrainedUsers

            if (@($unconstrainedAccounts).Count -eq 0) {
                Show-Line "No accounts with Unconstrained Delegation found (excluding Domain Controllers)" -Class "Secure"
                return
            }

            $totalComputers = @($unconstrainedComputers).Count
            $totalUsers = @($unconstrainedUsers).Count
            $total = @($unconstrainedAccounts).Count

            Show-Line "Found $total account(s) with Unconstrained Delegation ($totalComputers computers, $totalUsers users):" -Class "Finding"

            foreach ($account in $unconstrainedAccounts) {
                # Add type marker for HTML report
                $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'UnconstrainedDelegation' -Force
                Show-Object $account
            }

        } catch {
            Write-Log "[Get-UnconstrainedDelegation] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-UnconstrainedDelegation] Check completed"
    }
}



# ----- Get-ConstrainedDelegation.ps1 -----

function Get-ConstrainedDelegation {
    <#
    .SYNOPSIS
    Identifies accounts with Constrained Delegation enabled.

    .DESCRIPTION
    Detects computer and user accounts configured with Constrained Delegation, which allows a service to impersonate users to specific services only.

    Two Types of Constrained Delegation:
    1. Standard Constrained Delegation (msDS-AllowedToDelegateTo attribute)
       - Requires user to authenticate with Kerberos
       - Delegation limited to specific SPNs
    2. Protocol Transition (TRUSTED_TO_AUTH_FOR_DELEGATION flag)
       - Allows delegation without Kerberos authentication from user
       - Service can accept non-Kerberos authentication and still delegate
       - Higher security risk

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-ConstrainedDelegation

    .EXAMPLE
    Get-ConstrainedDelegation -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Delegation
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ConstrainedDelegation] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Searching for accounts with Constrained Delegation..." -ObjectType "ConstrainedDelegation"

            $constrainedComputers = @(Get-DomainComputer -Constrained -Enabled -ShowOwner @PSBoundParameters)
            $constrainedUsers = @(Get-DomainUser -Constrained -Enabled -ShowOwner @PSBoundParameters)

            # Combine results
            $constrainedAccounts = $constrainedComputers + $constrainedUsers

            if (@($constrainedAccounts).Count -eq 0) {
                Show-Line "No accounts with Constrained Delegation found" -Class "Secure"
                return
            }

            # Categorize accounts
            $totalComputers = 0
            $totalUsers = 0
            $totalProtocolTransition = 0

            $totalAccounts = @($constrainedAccounts).Count
            $currentIndex = 0
            foreach ($account in $constrainedAccounts) {
                $currentIndex++
                if ($totalAccounts -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing constrained delegation" -Current $currentIndex -Total $totalAccounts -ObjectName $account.sAMAccountName }
                $isComputer = $account.objectClass -icontains "computer"
                if ($isComputer) {
                    $totalComputers++
                } else {
                    $totalUsers++
                }

                # Check for Protocol Transition (TRUSTED_TO_AUTH_FOR_DELEGATION)
                $uacFlags = $account.userAccountControl
                if ($uacFlags -contains "TRUSTED_TO_AUTH_FOR_DELEGATION") {
                    $totalProtocolTransition++
                }
            }
            if ($totalAccounts -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing constrained delegation" -Completed }

            $total = @($constrainedAccounts).Count

            Show-Line "Found $total account(s) with Constrained Delegation ($totalComputers computers, $totalUsers users, $totalProtocolTransition with Protocol Transition):" -Class "Finding"

            $totalAccounts = @($constrainedAccounts).Count
            $currentIndex = 0
            foreach ($account in $constrainedAccounts) {
                $currentIndex++
                if ($totalAccounts -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing constrained delegation" -Current $currentIndex -Total $totalAccounts -ObjectName $account.sAMAccountName }
                # Add type marker for HTML report
                $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ConstrainedDelegation' -Force
                Show-Object $account
            }
            if ($totalAccounts -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing constrained delegation" -Completed }

        } catch {
            Write-Log "[Get-ConstrainedDelegation] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ConstrainedDelegation] Check completed"
    }
}



# ----- Get-ResourceBasedConstrainedDelegation.ps1 -----

function Get-ResourceBasedConstrainedDelegation {
    <#
    .SYNOPSIS
    Identifies accounts with Resource-Based Constrained Delegation (RBCD) configured.

    .DESCRIPTION
    Detects computer and user accounts configured with Resource-Based Constrained Delegation, a newer delegation model where the target resource controls who can delegate to it.

    RBCD vs. Traditional Constrained Delegation:
    - Traditional: Source (delegating service) defines where it can delegate
    - RBCD: Target (resource) defines who can delegate to it
    - RBCD uses msDS-AllowedToActOnBehalfOfOtherIdentity attribute (Security Descriptor)
    - RBCD doesn't require Domain Admin to configure (can be self-managed)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-ResourceBasedConstrainedDelegation

    .EXAMPLE
    Get-ResourceBasedConstrainedDelegation -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Delegation
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ResourceBasedConstrainedDelegation] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Searching for accounts with RBCD configured..." -ObjectType "RBCDelegation"

            $rbcdComputers = @(Get-DomainComputer -RBCD -Enabled -ShowOwner @PSBoundParameters)
            $rbcdUsers = @(Get-DomainUser -RBCD -Enabled -ShowOwner @PSBoundParameters)

            # Combine results
            $rbcdAccounts = $rbcdComputers + $rbcdUsers

            if (@($rbcdAccounts).Count -eq 0) {
                Show-Line "No accounts with Resource-Based Constrained Delegation found" -Class "Secure"
                return
            }

            $totalComputers = @($rbcdComputers).Count
            $totalUsers = @($rbcdUsers).Count
            $total = @($rbcdAccounts).Count

            Show-Line "Found $total account(s) with Resource-Based Constrained Delegation ($totalComputers computers, $totalUsers users):" -Class "Finding"

            foreach ($account in $rbcdAccounts) {
                # Add type marker for HTML report
                $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'RBCDelegation' -Force
                Show-Object $account
            }

        } catch {
            Write-Log "[Get-ResourceBasedConstrainedDelegation] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ResourceBasedConstrainedDelegation] Check completed"
    }
}



# ----- Get-DangerousACLs.ps1 -----

function Get-DangerousACLs {
    <#
    .SYNOPSIS
    Detects dangerous ACL permissions on the Domain root object.

    .DESCRIPTION
    Analyzes Access Control Lists (ACLs) on the Domain root object for dangerous permissions that allow privilege escalation to Domain Admin:

    - DCSync Rights (DS-Replication-Get-Changes + DS-Replication-Get-Changes-All)
    - GenericAll (Full Control)
    - GenericWrite (Write all properties)
    - WriteDacl (Modify permissions)
    - WriteOwner (Take ownership)
    Focuses on NON-privileged accounts with these rights (privilege escalation vector).

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-DangerousACLs

    .EXAMPLE
    Get-DangerousACLs -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Rights
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        Write-Log "[Get-DangerousACLs] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            $domainDN = $Script:LDAPContext.DomainDN

            # ===== Step 1: Get Domain Root ACLs using Get-ObjectACL =====
            Show-SubHeader "Analyzing Domain root ACLs..." -ObjectType "DangerousACL"

            Write-Log "[Get-DangerousACLs] Domain DN: $domainDN"

            # Use Get-ObjectACL with DangerousOnly filter for efficient ACL analysis
            $aclResult = Get-ObjectACL -DistinguishedName $domainDN -DangerousOnly -AllowOnly @connectionParams

            if (-not $aclResult) {
                Show-Line "Failed to retrieve ACLs for domain root" -Class Note
                return
            }

            Write-Log "[Get-DangerousACLs] Retrieved $($aclResult.ACECount) dangerous ACEs"

            # ===== Step 2: Analyze ACEs =====
            # Only analyze ACEs that grant FULL permissions on the domain object

            $dcsyncAccounts = @{}
            $dangerousRightsAccounts = @()

            foreach ($ace in $aclResult.ACEs) {
                $trusteeSID = $ace.TrusteeSID
                $trusteeName = $ace.Trustee
                $objectType = $ace.ObjectType
                $inheritedObjectType = $ace.InheritedObjectType

                # Skip ACEs with InheritedObjectType - they only apply to child objects, not the domain root
                if ($inheritedObjectType -and $inheritedObjectType -ne '' -and $inheritedObjectType -ne '00000000-0000-0000-0000-000000000000') {
                    Write-Log "[Get-DangerousACLs] Skipping child-only ACE: Trustee=$trusteeName, InheritedType=$inheritedObjectType"
                    continue
                }

                # ===== Check for DCSync Rights =====
                $hasDCSync = $false
                foreach ($right in $ace.RightsRaw) {
                    if ($right -match 'DS-Replication-Get-Changes') {
                        if (-not $dcsyncAccounts.ContainsKey($trusteeSID)) {
                            $dcsyncAccounts[$trusteeSID] = @{
                                SID = $trusteeSID
                                Name = $trusteeName
                                Rights = @()
                            }
                        }
                        $dcsyncAccounts[$trusteeSID].Rights += $right
                        $hasDCSync = $true
                    }
                }

                # ===== Check for Dangerous Generic Rights =====
                if (-not $hasDCSync) {
                    # Skip if ObjectType is set - this means the right only applies to a specific attribute/extended right
                    if ($objectType -and $objectType -ne '' -and $objectType -ne '00000000-0000-0000-0000-000000000000') {
                        Write-Log "[Get-DangerousACLs] Skipping object-specific ACE: Trustee=$trusteeName, ObjectType=$objectType"
                        continue
                    }

                    $dangerousRights = @($ace.RightsRaw | Where-Object {
                        $_ -in @('GenericAll', 'GenericWrite', 'WriteDacl', 'WriteOwner')
                    })

                    if (@($dangerousRights).Count -gt 0) {
                        $dangerousRightsAccounts += [PSCustomObject]@{
                            SID = $trusteeSID
                            Name = $trusteeName
                            Rights = $dangerousRights
                        }
                    }
                }
            }

            # ===== Step 3: Collect non-privileged findings =====
            $dcsyncFindings = @()
            $dangerousRightsFindings = @()

            # Process DCSync accounts
            if ($dcsyncAccounts.Count -gt 0) {
                foreach ($sid in $dcsyncAccounts.Keys) {
                    $account = $dcsyncAccounts[$sid]
                    $rights = $account.Rights
                    $accountName = $account.Name

                    # Check if account has BOTH required rights for DCSync
                    $hasGetChanges = $rights -contains 'DS-Replication-Get-Changes'
                    $hasGetChangesAll = $rights -contains 'DS-Replication-Get-Changes-All'
                    $hasGetChangesFiltered = $rights -contains 'DS-Replication-Get-Changes-In-Filtered-Set'

                    $canDCSync = $hasGetChanges -and $hasGetChangesAll

                    if ($canDCSync) {
                        $rightsDisplay = "DS-Replication-Get-Changes, DS-Replication-Get-Changes-All"
                        if ($hasGetChangesFiltered) {
                            $rightsDisplay += ", DS-Replication-Get-Changes-In-Filtered-Set"
                        }

                        # Determine severity
                        $severity = 'Finding'

                        if (-not $IncludePrivileged) {
                            # Use scope-based check for DCSync rights
                            $scopeResult = Test-IsExpectedInScope -Identity $sid -Scope 'DCSync' -ReturnDetails

                            if ($scopeResult.Severity -eq 'Expected') {
                                Write-Log "[Get-DangerousACLs] DCSync rights (expected): $accountName - $($scopeResult.Reason)"
                                continue
                            }

                            if ($scopeResult.Severity -eq 'Attention') {
                                Write-Log "[Get-DangerousACLs] DCSync rights (attention): $accountName - $($scopeResult.Reason) - skipped (use -IncludePrivileged to include)"
                                continue
                            }

                            $severity = $scopeResult.Severity
                        } else {
                            # -IncludePrivileged: Show ALL accounts, but mark privileged ones for yellow display
                            $scopeResult = Test-IsExpectedInScope -Identity $sid -Scope 'DCSync' -ReturnDetails
                            $severity = $scopeResult.Severity
                            Write-Log "[Get-DangerousACLs] IncludePrivileged: Including DCSync $accountName ($sid) with severity $severity"
                        }

                        $dcsyncFindings += [PSCustomObject]@{
                            Name = $accountName
                            SID = $sid
                            Rights = $rightsDisplay
                            Severity = $severity
                        }
                    }
                }
            }

            # Process dangerous generic rights
            if (@($dangerousRightsAccounts).Count -gt 0) {
                $groupedAccounts = $dangerousRightsAccounts | Group-Object -Property SID

                foreach ($group in $groupedAccounts) {
                    $sid = $group.Name
                    $accountName = $group.Group[0].Name
                    $allRights = @()

                    foreach ($item in $group.Group) {
                        $allRights += $item.Rights
                    }

                    $allRights = $allRights | Select-Object -Unique
                    $rightsDisplay = $allRights -join ', '

                    # Determine severity
                    $severity = 'Finding'

                    if (-not $IncludePrivileged) {
                        # Use scope-based check for Domain Root ACL rights
                        $scopeResult = Test-IsExpectedInScope -Identity $sid -Scope 'DomainRootACL' -ReturnDetails

                        if ($scopeResult.Severity -eq 'Expected') {
                            Write-Log "[Get-DangerousACLs] Dangerous rights (expected): $accountName - $rightsDisplay - $($scopeResult.Reason)"
                            continue
                        }

                        if ($scopeResult.Severity -eq 'Attention') {
                            Write-Log "[Get-DangerousACLs] Dangerous rights (attention): $accountName - $rightsDisplay - $($scopeResult.Reason) - skipped (use -IncludePrivileged to include)"
                            continue
                        }

                        $severity = $scopeResult.Severity
                    } else {
                        # -IncludePrivileged: Show ALL accounts, but mark privileged ones for yellow display
                        $scopeResult = Test-IsExpectedInScope -Identity $sid -Scope 'DomainRootACL' -ReturnDetails
                        $severity = $scopeResult.Severity
                        Write-Log "[Get-DangerousACLs] IncludePrivileged: Including $accountName ($sid) with severity $severity"
                    }

                    $dangerousRightsFindings += [PSCustomObject]@{
                        Name = $accountName
                        SID = $sid
                        Rights = $rightsDisplay
                        Severity = $severity
                    }
                }
            }

            # ===== Step 4: Output findings with full AD objects =====
            # DCSync findings
            if (@($dcsyncFindings).Count -gt 0) {
                $countText = if ($IncludePrivileged) { "$(@($dcsyncFindings).Count) account(s)" } else { "$(@($dcsyncFindings).Count) non-privileged account(s)" }
                Show-Line "Found $countText with DCSync rights" -Class Finding

                foreach ($finding in $dcsyncFindings) {
                    # Try to resolve the SID to a full AD object (user or group)
                    $sidHex = ConvertTo-LDAPSIDHex -SID $finding.SID
                    $adObject = $null

                    if ($sidHex) {
                        $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                    }

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue $finding.Rights -Force
                        $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue $finding.Severity -Force
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousACL' -Force
                        Show-Object $adObject
                    } else {
                        # Create synthetic object for unresolvable SIDs (e.g., foreign domain principals)
                        $syntheticObject = [PSCustomObject]@{
                            sAMAccountName = $finding.Name
                            objectSid = $finding.SID
                            objectClass = 'foreignSecurityPrincipal'
                            dangerousRights = $finding.Rights
                            dangerousRightsSeverity = $finding.Severity
                        }
                        $syntheticObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousACL' -Force
                        Show-Object $syntheticObject
                    }
                }
            }

            # Dangerous rights findings
            if (@($dangerousRightsFindings).Count -gt 0) {
                $countText = if ($IncludePrivileged) { "$(@($dangerousRightsFindings).Count) account(s)" } else { "$(@($dangerousRightsFindings).Count) non-privileged account(s)" }
                Show-Line "Found $countText with dangerous rights on domain root" -Class Finding

                foreach ($finding in $dangerousRightsFindings) {
                    # Try to resolve the SID to a full AD object (user or group)
                    $sidHex = ConvertTo-LDAPSIDHex -SID $finding.SID
                    $adObject = $null

                    if ($sidHex) {
                        $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                    }

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue $finding.Rights -Force
                        $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue $finding.Severity -Force
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousACL' -Force
                        Show-Object $adObject
                    } else {
                        # Create synthetic object for unresolvable SIDs (e.g., foreign domain principals)
                        $syntheticObject = [PSCustomObject]@{
                            sAMAccountName = $finding.Name
                            objectSid = $finding.SID
                            objectClass = 'foreignSecurityPrincipal'
                            dangerousRights = $finding.Rights
                            dangerousRightsSeverity = $finding.Severity
                        }
                        $syntheticObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousACL' -Force
                        Show-Object $syntheticObject
                    }
                }
            }

            if (@($dcsyncFindings).Count -eq 0 -and @($dangerousRightsFindings).Count -eq 0) {
                Show-Line "No dangerous ACLs detected on domain root" -Class Secure
            }

        } catch {
            Write-Log "[Get-DangerousACLs] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-DangerousACLs] Check completed"
    }
}




# ----- Get-DangerousOUPermissions.ps1 -----

<#
.SYNOPSIS
    Identifies dangerous permissions on Organizational Units across the domain.

.DESCRIPTION
    Scans all OUs in the domain for critical permissions that could lead to privilege escalation or lateral movement:

    - GenericAll (Full Control) - Non-privileged accounts
    - Password Reset Rights - Ability to reset user passwords
    - Account Control Modification - Change userAccountControl flags
    - Group Membership Control - Modify group memberships
    - SPN Modification - Set servicePrincipalName (Kerberoasting prep)
    - Script Path Modification - Change logon scripts (code execution)
    - Delegation Rights - Configure constrained/unconstrained delegation
    - Object Creation - Create new users/computers
    - GPO Linking - Link malicious GPOs
    Focuses on non-privileged accounts having these rights (privileged accounts are expected to have high permissions and generate lower severity findings).

.PARAMETER Domain
    Domain to query. Uses current domain if not specified.

.PARAMETER Server
    Domain Controller to query. Uses auto-discovery if not specified.

.PARAMETER Credential
    PSCredential object for authentication.

.PARAMETER ExcludeInherited
    Only analyze explicit ACEs (exclude inherited permissions).

.PARAMETER CheckType
    Specific check types to perform. Default: All critical checks.

.EXAMPLE
    Get-DangerousOUPermissions
    Scans all OUs in current domain for dangerous permissions.

.EXAMPLE
    Get-DangerousOUPermissions -Domain "contoso.com" -Credential (Get-Credential)
    Scans with alternate credentials.

.EXAMPLE
    Get-DangerousOUPermissions -CheckType 'PasswordReset','GenericAll' -ExcludeInherited
    Only checks for password reset and full control rights, excluding inherited ACEs.

.OUTPUTS
    Hashtable with:
    - FindingsDetected: Boolean
    - Findings: Array of dangerous permission findings
    - Summary: Statistics by check type and severity

.NOTES
    Category: Rights
    Author: Alexander Sturz (@_61106960_)
#>

function Get-DangerousOUPermissions {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged,

        [Parameter(Mandatory=$false)]
        [switch]$ExcludeInherited,

        [Parameter(Mandatory=$false)]
        [ValidateSet(
            'All',
            'GenericAll',
            'GenericWrite',
            'WriteDacl',
            'WriteOwner',
            'PasswordReset',
            'AccountControl',
            'GroupMembership',
            'SPNModification',
            'ScriptPath',
            'Delegation',
            'LAPS',
            'ObjectCreation',
            'GPOLinking'
        )]
        [string[]]$CheckType = @('All')
    )

    begin {
        Write-Log "[Get-DangerousOUPermissions] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged, ExcludeInherited and CheckType which are not connection parameters)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Analyzing OU permissions..." -ObjectType "DangerousOUPermission"

            # Get all OUs in the domain using Get-DomainObject
            $OUs = Get-DomainObject -LDAPFilter "(objectClass=organizationalUnit)" @connectionParams

            if (-not $OUs -or @($OUs).Count -eq 0) {
                Write-Log "[Get-DangerousOUPermissions] No Organizational Units found"
                Show-Line "No dangerous OU permissions detected" -Class Note
                return
            }

            Write-Log "[Get-DangerousOUPermissions] Found $(@($OUs).Count) OU(s) to analyze"

            $allFindings = @()
            $ouCount = 0
            $ouWithFindings = 0

            # Analyze each OU
            $totalOUs = @($OUs).Count
            $currentIndex = 0
            foreach ($ou in $OUs) {
                $currentIndex++
                $ouCount++
                if ($totalOUs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing OU permissions" -Current $currentIndex -Total $totalOUs -ObjectName $ou.name }
                $ouDN = $ou.distinguishedName
                $ouName = $ou.name

                Write-Log "[Get-DangerousOUPermissions] Analyzing OU ($ouCount/$(@($OUs).Count)): $ouName"

                # Get-OUPermissions uses session context automatically
                $ouParams = @{
                    DistinguishedName = $ouDN
                    CheckType = $CheckType
                }
                if ($ExcludeInherited) { $ouParams['ExcludeInherited'] = $true }

                $ouPermissions = Get-OUPermissions @ouParams

                if (-not $ouPermissions -or -not $ouPermissions.Findings) {
                    continue
                }

                # Filter findings by severity
                # Account Operators (S-1-5-32-548) excluded - they have default OU permissions by design
                $allowedSeverities = if ($IncludePrivileged) { @('Critical', 'High', 'Info') } else { @('Critical', 'High') }
                $dangerousFindings = $ouPermissions.Findings | Where-Object {
                    $_.Severity -in $allowedSeverities -and
                    $_.SID -ne 'S-1-5-32-548'
                }

                if ($dangerousFindings) {
                    $ouWithFindings++

                    foreach ($finding in $dangerousFindings) {
                        # Check if this is an Exchange service group
                        # Exchange groups have by-design permissions that cannot be removed
                        $isExchangeService = $false
                        $exchangeCheck = Test-IsExchangeServiceGroup -Identity $finding.SID
                        if ($exchangeCheck.IsExchangeService) {
                            $isExchangeService = $true
                            Write-Log "[Get-DangerousOUPermissions] Exchange service group detected: $($finding.Principal)"
                        }

                        # Determine display severity:
                        # - Exchange service groups -> 'Attention' (yellow, by-design)
                        # - Privileged accounts (Info from Get-OUPermissions) with -IncludePrivileged -> 'Attention' (yellow)
                        # - Non-privileged -> original severity (Critical/High)
                        $isPrivilegedAccount = $finding.Severity -eq 'Info'
                        $displaySeverity = if ($isExchangeService) { 'Attention' }
                            elseif ($isPrivilegedAccount) { 'Attention' }
                            else { $finding.Severity }

                        $allFindings += [PSCustomObject]@{
                            OU           = $ouName
                            DistinguishedName = $ouDN
                            CheckType    = $finding.CheckType
                            Right        = $finding.Right
                            Principal    = $finding.Principal
                            SID          = $finding.SID
                            Severity     = $displaySeverity
                            InheritedFrom = $finding.InheritedFrom
                            IsExchangeService = $isExchangeService
                            IsPrivilegedAccount = $isPrivilegedAccount
                        }
                    }
                }
            }
            if ($totalOUs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing OU permissions" -Completed }

            # Display findings
            if (@($allFindings).Count -eq 0) {
                Show-Line "No dangerous OU permissions detected in $(@($OUs).Count) analyzed OU(s)" -Class Secure
                return
            }

            # Group findings by Principal first (show account once, then all OUs)
            $groupedByPrincipal = @($allFindings | Group-Object -Property SID)

            # Separate Exchange service groups from other findings for display
            $exchangeFindings = @($groupedByPrincipal | Where-Object { $_.Group[0].IsExchangeService -eq $true })
            $nonExchangeFindings = @($groupedByPrincipal | Where-Object { $_.Group[0].IsExchangeService -ne $true })

            # Batch resolve all unique SIDs to AD objects (avoids N+1 LDAP queries in display loops)
            $sidObjectMap = @{}
            $allUniqueSIDs = @($groupedByPrincipal | ForEach-Object { $_.Name } | Sort-Object -Unique)
            $resolvableSIDs = @($allUniqueSIDs | Where-Object { $_ -notmatch '^S-1-5-\d+$' })

            if ($resolvableSIDs.Count -gt 0) {
                $totalSIDs = $resolvableSIDs.Count
                $currentSIDIndex = 0
                foreach ($resolveSID in $resolvableSIDs) {
                    $currentSIDIndex++
                    if ($totalSIDs -gt $Script:ProgressThreshold) {
                        Show-Progress -Activity "Resolving account details" -Current $currentSIDIndex -Total $totalSIDs
                    }
                    $sidHex = ConvertTo-LDAPSIDHex -SID $resolveSID
                    if ($sidHex) {
                        $obj = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                        if ($obj) { $sidObjectMap[$resolveSID] = $obj }
                    }
                }
                if ($totalSIDs -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Resolving account details" -Completed
                }
            }

            # Display non-Exchange findings as Finding (red)
            if (@($nonExchangeFindings).Count -gt 0) {
                $countText = if ($IncludePrivileged) { "$(@($nonExchangeFindings).Count) account(s)" } else { "$(@($nonExchangeFindings).Count) non-privileged account(s)" }
                Show-Line "Found $countText with dangerous OU permissions in $ouWithFindings OU(s)" -Class Finding

                foreach ($principalGroup in $nonExchangeFindings) {
                    $sid = $principalGroup.Name
                    $principal = $principalGroup.Group[0].Principal
                    $ouFindings = $principalGroup.Group

                    # Collect all OUs and rights for this principal
                    $affectedOUs = @()
                    $dangerousRightsList = @()
                    $inheritanceSources = @()
                    foreach ($finding in $ouFindings) {
                        $ouEntry = $finding.DistinguishedName
                        if ($affectedOUs -notcontains $ouEntry) {
                            $affectedOUs += $ouEntry
                        }
                        if ($dangerousRightsList -notcontains $finding.Right) {
                            $dangerousRightsList += $finding.Right
                        }
                        if ($finding.InheritedFrom -and $inheritanceSources -notcontains $finding.InheritedFrom) {
                            $inheritanceSources += $finding.InheritedFrom
                        }
                    }

                    $isWellKnownSID = $sid -match '^S-1-5-\d+$'
                    $adObject = if ($sidObjectMap.ContainsKey($sid)) { $sidObjectMap[$sid] } else { $null }
                    $isPriv = $ouFindings[0].IsPrivilegedAccount

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue $dangerousRightsList -Force
                        $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $affectedOUs -Force
                        if (@($inheritanceSources).Count -gt 0) {
                            $adObject | Add-Member -NotePropertyName 'inheritedFrom' -NotePropertyValue $inheritanceSources -Force
                        }
                        if ($isPriv) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousOUPermission' -Force
                        Show-Object $adObject
                    } else {
                        $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $principal }
                        $fallbackObject = [PSCustomObject]@{
                            sAMAccountName = $resolvedName
                            objectSid = $sid
                            dangerousRights = $dangerousRightsList
                            affectedOUs = $affectedOUs
                        }
                        if (@($inheritanceSources).Count -gt 0) {
                            $fallbackObject | Add-Member -NotePropertyName 'inheritedFrom' -NotePropertyValue $inheritanceSources -Force
                        }
                        if ($isPriv) {
                            $fallbackObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousOUPermission' -Force
                        Show-Object $fallbackObject
                    }
                }
            }

            # Display Exchange service group findings as Hint (yellow) - by-design permissions
            # Only shown with -IncludePrivileged (Exchange groups are privileged by design)
            if ($IncludePrivileged -and @($exchangeFindings).Count -gt 0) {
                Show-Line "Found $(@($exchangeFindings).Count) Exchange service group(s) with OU permissions (by-design, cannot be removed)" -Class Hint

                foreach ($principalGroup in $exchangeFindings) {
                    $sid = $principalGroup.Name
                    $principal = $principalGroup.Group[0].Principal
                    $ouFindings = $principalGroup.Group

                    $affectedOUs = @()
                    $dangerousRightsList = @()
                    $inheritanceSources = @()
                    foreach ($finding in $ouFindings) {
                        $ouEntry = $finding.DistinguishedName
                        if ($affectedOUs -notcontains $ouEntry) {
                            $affectedOUs += $ouEntry
                        }
                        if ($dangerousRightsList -notcontains $finding.Right) {
                            $dangerousRightsList += $finding.Right
                        }
                        if ($finding.InheritedFrom -and $inheritanceSources -notcontains $finding.InheritedFrom) {
                            $inheritanceSources += $finding.InheritedFrom
                        }
                    }

                    $isWellKnownSID = $sid -match '^S-1-5-\d+$'
                    $adObject = if ($sidObjectMap.ContainsKey($sid)) { $sidObjectMap[$sid] } else { $null }

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue $dangerousRightsList -Force
                        $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $affectedOUs -Force
                        if (@($inheritanceSources).Count -gt 0) {
                            $adObject | Add-Member -NotePropertyName 'inheritedFrom' -NotePropertyValue $inheritanceSources -Force
                        }
                        $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        $adObject | Add-Member -NotePropertyName '_isExchangeGroup' -NotePropertyValue $true -Force
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousOUPermission' -Force
                        Show-Object $adObject
                    } else {
                        $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $principal }
                        $fallbackObject = [PSCustomObject]@{
                            sAMAccountName = $resolvedName
                            objectSid = $sid
                            dangerousRights = $dangerousRightsList
                            affectedOUs = $affectedOUs
                            dangerousRightsSeverity = 'Hint'
                        }
                        if (@($inheritanceSources).Count -gt 0) {
                            $fallbackObject | Add-Member -NotePropertyName 'inheritedFrom' -NotePropertyValue $inheritanceSources -Force
                        }
                        $fallbackObject | Add-Member -NotePropertyName '_isExchangeGroup' -NotePropertyValue $true -Force
                        $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DangerousOUPermission' -Force
                        Show-Object $fallbackObject
                    }
                }
            }

            # If no non-Exchange findings were displayed (and Exchange is hidden without -IncludePrivileged)
            if (@($nonExchangeFindings).Count -eq 0 -and (-not $IncludePrivileged -or @($exchangeFindings).Count -eq 0)) {
                Show-Line "No dangerous OU permissions detected in $(@($OUs).Count) analyzed OU(s)" -Class Secure
            }

        } catch {
            Write-Log "[Get-DangerousOUPermissions] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-DangerousOUPermissions] Analysis completed"
    }
}



# ----- Get-PasswordResetRights.ps1 -----

<#
.SYNOPSIS
    Identifies accounts with password reset rights on OUs containing privileged users.

.DESCRIPTION
    Scans Organizational Units that contain members of privileged groups for principals
    who have password reset extended rights. Password reset rights allow an account to
    reset another user's password without knowing the current password.

    Privileged groups analyzed (SID-based, language-independent):

    Domain Groups:
    - Domain Admins (RID 512)
    - Enterprise Admins (RID 519)
    - Schema Admins (RID 518)
    - Group Policy Creator Owners (RID 520)
    - Key Admins (RID 526)
    - Enterprise Key Admins (RID 527)
    - Cert Publishers (RID 517)

    Built-in Groups:
    - Administrators (S-1-5-32-544)
    - Account Operators (S-1-5-32-548)
    - Server Operators (S-1-5-32-549)
    - Print Operators (S-1-5-32-550)
    - Backup Operators (S-1-5-32-551)
    - Hyper-V Administrators (S-1-5-32-578)
    - Remote Management Users (S-1-5-32-580)

    The module identifies OUs by analyzing where members of these groups are actually located,
    not by guessing OU names. Uses LDAP_MATCHING_RULE_IN_CHAIN (OID 1.2.840.113556.1.4.1941)
    for recursive group membership resolution, finding users in nested groups as well.

.PARAMETER Domain
    Domain to query. Uses current domain if not specified.

.PARAMETER Server
    Domain Controller to query. Uses auto-discovery if not specified.

.PARAMETER Credential
    PSCredential object for authentication.

.PARAMETER IncludeAllOUs
    Analyze all OUs (not just those containing privileged users).

.EXAMPLE
    Get-PasswordResetRights
    Scans OUs containing privileged users for password reset rights.

.EXAMPLE
    Get-PasswordResetRights -IncludeAllOUs
    Scans all OUs in the domain.

.EXAMPLE
    Get-PasswordResetRights -Domain "contoso.com" -Credential (Get-Credential)
    Scans with alternate credentials.

.OUTPUTS
    Findings of non-privileged accounts with password reset rights on critical OUs.

.NOTES
    Category: Rights
    Author: Alexander Sturz (@_61106960_)
#>

function Get-PasswordResetRights {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged,

        [Parameter(Mandatory=$false)]
        [switch]$IncludeAllOUs
    )

    begin {
        Write-Log "[Get-PasswordResetRights] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged and IncludeAllOUs which are not connection parameters)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            $domainSID = $Script:LDAPContext.DomainSID
            $privilegedOUs = @{}  # Hashtable to deduplicate OUs

            Show-SubHeader "Analyzing password reset rights on OUs with privileged users..." -ObjectType "PasswordResetRight"

            if ($IncludeAllOUs) {
                # Analyze all OUs
                $allOUs = Get-DomainObject -LDAPFilter "(objectClass=organizationalUnit)" @connectionParams

                if ($allOUs) {
                    foreach ($ou in $allOUs) {
                        $ouDN = $ou.distinguishedName
                        if (-not $privilegedOUs.ContainsKey($ouDN)) {
                            $privilegedOUs[$ouDN] = [PSCustomObject]@{
                                DN = $ouDN
                                Name = $ou.name
                                Type = "All OUs"
                                PrivilegedUsers = @()
                            }
                        }
                    }
                }
                Write-Log "[Get-PasswordResetRights] Analyzing all $($privilegedOUs.Keys.Count) OUs"
            } else {
                # Find OUs containing members of privileged groups (SID-based)
                # Combine domain-relative RIDs and well-known SIDs into unified list
                $privilegedGroups = @(
                    # Domain-relative groups (RID combined with domain SID)
                    @{ SID = "$domainSID-512"; Name = 'Domain Admins' },
                    @{ SID = "$domainSID-519"; Name = 'Enterprise Admins' },
                    @{ SID = "$domainSID-518"; Name = 'Schema Admins' },
                    @{ SID = "$domainSID-520"; Name = 'Group Policy Creator Owners' },
                    @{ SID = "$domainSID-526"; Name = 'Key Admins' },
                    @{ SID = "$domainSID-527"; Name = 'Enterprise Key Admins' },
                    @{ SID = "$domainSID-517"; Name = 'Cert Publishers' },
                    # Well-known built-in groups (fixed SIDs)
                    @{ SID = 'S-1-5-32-544'; Name = 'Administrators' },
                    @{ SID = 'S-1-5-32-548'; Name = 'Account Operators' },
                    @{ SID = 'S-1-5-32-549'; Name = 'Server Operators' },
                    @{ SID = 'S-1-5-32-550'; Name = 'Print Operators' },
                    @{ SID = 'S-1-5-32-551'; Name = 'Backup Operators' },
                    @{ SID = 'S-1-5-32-578'; Name = 'Hyper-V Administrators' },
                    @{ SID = 'S-1-5-32-580'; Name = 'Remote Management Users' }
                )

                # Process all privileged groups (using LDAP_MATCHING_RULE_IN_CHAIN for recursive lookup)
                foreach ($groupInfo in $privilegedGroups) {
                    $groupSID = $groupInfo.SID
                    $groupName = $groupInfo.Name

                    Write-Log "[Get-PasswordResetRights] Analyzing members of $groupName ($groupSID) (recursive)"

                    # Get group by SID
                    $groupSIDHex = ConvertTo-LDAPSIDHex -SID $groupSID
                    if (-not $groupSIDHex) { continue }

                    # First get the group DN (use [0] to handle referral-chasing returning multiple results)
                    $group = @(Get-DomainObject -LDAPFilter "(objectSid=$groupSIDHex)" @connectionParams)[0]
                    if (-not $group) {
                        Write-Log "[Get-PasswordResetRights] Group $groupName not found"
                        continue
                    }

                    $groupDN = $group.distinguishedName
                    # Escape DN for LDAP filter to prevent injection (RFC 4515)
                    $escapedGroupDN = Escape-LDAPFilterDN -DistinguishedName $groupDN

                    # Get ALL members recursively using LDAP_MATCHING_RULE_IN_CHAIN (OID 1.2.840.113556.1.4.1941)
                    # This finds users who are members directly OR through nested group membership
                    $members = Get-DomainUser -LDAPFilter "(memberOf:1.2.840.113556.1.4.1941:=$escapedGroupDN)" @connectionParams

                    if ($members) {
                        foreach ($member in $members) {
                            $memberDN = $member.distinguishedName
                            $memberName = $member.sAMAccountName

                            # Extract parent OU/Container from member DN
                            if ($memberDN -match '^CN=[^,]+,(.+)$') {
                                $parentDN = $Matches[1]

                                if (-not $privilegedOUs.ContainsKey($parentDN)) {
                                    # Determine if it's an OU or Container
                                    $ouType = if ($parentDN -match '^OU=') { "OU" } else { "Container" }

                                    $privilegedOUs[$parentDN] = [PSCustomObject]@{
                                        DN = $parentDN
                                        Name = ($parentDN -split ',')[0] -replace '^(OU|CN)=', ''
                                        Type = "$ouType containing $groupName member(s)"
                                        PrivilegedUsers = @()
                                    }
                                }

                                # Track which privileged users are in this OU
                                $privilegedOUs[$parentDN].PrivilegedUsers += "$memberName ($groupName)"
                            }
                        }
                    }
                }

                Write-Log "[Get-PasswordResetRights] Found $($privilegedOUs.Keys.Count) OU(s)/Container(s) with privileged users"
            }

            if ($privilegedOUs.Keys.Count -eq 0) {
                Write-Log "[Get-PasswordResetRights] No OUs with privileged users found"
                Show-Line "No OUs with privileged users found to analyze" -Class Note
                return
            }

            $allFindings = @()

            # Analyze each OU for password reset rights
            foreach ($ouDN in $privilegedOUs.Keys) {
                $ouInfo = $privilegedOUs[$ouDN]
                Write-Log "[Get-PasswordResetRights] Analyzing: $($ouInfo.Name) ($ouDN)"

                # Get-OUPermissions uses session context automatically
                $ouPermissions = Get-OUPermissions -DistinguishedName $ouDN -CheckType 'PasswordReset'

                if (-not $ouPermissions -or -not $ouPermissions.Findings) {
                    continue
                }

                # Add findings with OU context
                $allowedSeverities = if ($IncludePrivileged) { @('Critical', 'High', 'Info') } else { @('Critical', 'High') }
                foreach ($finding in $ouPermissions.Findings) {
                    # Filter by severity
                    if ($finding.Severity -notin $allowedSeverities) {
                        continue
                    }

                    # Check if this is an Exchange service group
                    # Exchange groups have by-design permissions that cannot be removed
                    $isExchangeService = $false
                    $exchangeCheck = Test-IsExchangeServiceGroup -Identity $finding.SID
                    if ($exchangeCheck.IsExchangeService) {
                        $isExchangeService = $true
                        Write-Log "[Get-PasswordResetRights] Exchange service group detected: $($finding.Principal)"
                    }

                    # Determine display severity:
                    # - Exchange service groups -> 'Attention' (yellow, by-design)
                    # - Privileged accounts (Info from Get-OUPermissions) with -IncludePrivileged -> 'Attention' (yellow)
                    # - Non-privileged -> original severity (Critical/High)
                    $isPrivilegedAccount = $finding.Severity -eq 'Info'
                    $displaySeverity = if ($isExchangeService) { 'Attention' }
                        elseif ($isPrivilegedAccount) { 'Attention' }
                        else { $finding.Severity }

                    $allFindings += [PSCustomObject]@{
                        OU              = $ouInfo.Name
                        OUType          = $ouInfo.Type
                        DistinguishedName = $ouDN
                        Principal       = $finding.Principal
                        SID             = $finding.SID
                        Right           = $finding.Right
                        Severity        = $displaySeverity
                        Inherited       = $finding.InheritedFrom
                        PrivilegedUsers = $ouInfo.PrivilegedUsers
                        IsExchangeService = $isExchangeService
                        IsPrivilegedAccount = $isPrivilegedAccount
                    }
                }
            }

            if (@($allFindings).Count -eq 0) {
                Show-Line "No dangerous password reset rights detected in $($privilegedOUs.Keys.Count) analyzed OU(s)" -Class Secure
                return
            }

            # Group by principal (each principal may have rights on multiple OUs)
            $groupedByPrincipal = @($allFindings | Group-Object -Property SID)

            # Separate Exchange service groups from other findings for display
            $exchangeFindings = @($groupedByPrincipal | Where-Object { $_.Group[0].IsExchangeService -eq $true })
            $nonExchangeFindings = @($groupedByPrincipal | Where-Object { $_.Group[0].IsExchangeService -ne $true })

            # Display non-Exchange findings as Finding (red)
            if (@($nonExchangeFindings).Count -gt 0) {
                $countText = if ($IncludePrivileged) { "$(@($nonExchangeFindings).Count) account(s)" } else { "$(@($nonExchangeFindings).Count) non-privileged account(s)" }
                Show-Line "Found $countText with password reset rights on OUs containing privileged users" -Class Finding

                foreach ($principalGroup in $nonExchangeFindings) {
                    $sid = $principalGroup.Name
                    $principal = $principalGroup.Group[0].Principal
                    $affectedOUs = @($principalGroup.Group | ForEach-Object { $_.DistinguishedName } | Select-Object -Unique)

                    # Collect all privileged users that could be targeted
                    $targetableUsers = @()
                    foreach ($finding in $principalGroup.Group) {
                        if ($finding.PrivilegedUsers) {
                            $targetableUsers += $finding.PrivilegedUsers
                        }
                    }
                    $targetableUsers = $targetableUsers | Select-Object -Unique

                    # Check if this principal is privileged (for yellow display)
                    $isPriv = $principalGroup.Group[0].IsPrivilegedAccount

                    # Check if this is a well-known SID (S-1-5-X without domain sub-authorities)
                    # Well-known SIDs resolve to unhelpful ForeignSecurityPrincipal objects
                    $isWellKnownSID = $sid -match '^S-1-5-\d+$'

                    # Try to resolve the SID to a full AD object (skip for well-known SIDs)
                    $adObject = $null
                    if (-not $isWellKnownSID) {
                        $sidHex = ConvertTo-LDAPSIDHex -SID $sid
                        if ($sidHex) {
                            $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                        }
                    }

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue "Password Reset (ForceChangePassword)" -Force
                        $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $affectedOUs -Force
                        if (@($targetableUsers).Count -gt 0) {
                            $adObject | Add-Member -NotePropertyName 'targetablePrivilegedUsers' -NotePropertyValue $targetableUsers -Force
                        }
                        if ($isPriv) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordResetRight' -Force
                        Show-Object $adObject
                    } else {
                        # Fallback for well-known SIDs, foreign/deleted principals
                        $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $principal }
                        $fallbackObject = [PSCustomObject]@{
                            sAMAccountName = $resolvedName
                            objectSid = $sid
                            dangerousRights = "Password Reset (ForceChangePassword)"
                            affectedOUs = $affectedOUs
                        }
                        if (@($targetableUsers).Count -gt 0) {
                            $fallbackObject | Add-Member -NotePropertyName 'targetablePrivilegedUsers' -NotePropertyValue $targetableUsers -Force
                        }
                        if ($isPriv) {
                            $fallbackObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordResetRight' -Force
                        Show-Object $fallbackObject
                    }
                }
            }

            # Display Exchange service group findings as Hint (yellow) - by-design permissions
            # Only shown with -IncludePrivileged (Exchange groups are privileged by design)
            if ($IncludePrivileged -and @($exchangeFindings).Count -gt 0) {
                Show-Line "Found $(@($exchangeFindings).Count) Exchange service group(s) with password reset rights (by-design, cannot be removed)" -Class Hint

                foreach ($principalGroup in $exchangeFindings) {
                    $sid = $principalGroup.Name
                    $principal = $principalGroup.Group[0].Principal
                    $affectedOUs = @($principalGroup.Group | ForEach-Object { $_.DistinguishedName } | Select-Object -Unique)

                    # Collect all privileged users that could be targeted
                    $targetableUsers = @()
                    foreach ($finding in $principalGroup.Group) {
                        if ($finding.PrivilegedUsers) {
                            $targetableUsers += $finding.PrivilegedUsers
                        }
                    }
                    $targetableUsers = $targetableUsers | Select-Object -Unique

                    # Check if this is a well-known SID (S-1-5-X without domain sub-authorities)
                    $isWellKnownSID = $sid -match '^S-1-5-\d+$'

                    # Try to resolve the SID to a full AD object (skip for well-known SIDs)
                    $adObject = $null
                    if (-not $isWellKnownSID) {
                        $sidHex = ConvertTo-LDAPSIDHex -SID $sid
                        if ($sidHex) {
                            $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                        }
                    }

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue "Password Reset (ForceChangePassword)" -Force
                        $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $affectedOUs -Force
                        # Mark as Exchange service group for display formatting
                        $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        $adObject | Add-Member -NotePropertyName '_isExchangeGroup' -NotePropertyValue $true -Force
                        if (@($targetableUsers).Count -gt 0) {
                            $adObject | Add-Member -NotePropertyName 'targetablePrivilegedUsers' -NotePropertyValue $targetableUsers -Force
                        }
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordResetRight' -Force
                        Show-Object $adObject
                    } else {
                        # Fallback for well-known SIDs, foreign/deleted principals
                        $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $principal }
                        $fallbackObject = [PSCustomObject]@{
                            sAMAccountName = $resolvedName
                            objectSid = $sid
                            dangerousRights = "Password Reset (ForceChangePassword)"
                            affectedOUs = $affectedOUs
                            dangerousRightsSeverity = 'Hint'
                        }
                        if (@($targetableUsers).Count -gt 0) {
                            $fallbackObject | Add-Member -NotePropertyName 'targetablePrivilegedUsers' -NotePropertyValue $targetableUsers -Force
                        }
                        $fallbackObject | Add-Member -NotePropertyName '_isExchangeGroup' -NotePropertyValue $true -Force
                        $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordResetRight' -Force
                        Show-Object $fallbackObject
                    }
                }
            }

            # If no non-Exchange findings were displayed (and Exchange is hidden without -IncludePrivileged)
            if (@($nonExchangeFindings).Count -eq 0 -and (-not $IncludePrivileged -or @($exchangeFindings).Count -eq 0)) {
                Show-Line "No dangerous password reset rights detected in $($privilegedOUs.Keys.Count) analyzed OU(s)" -Class Secure
            }

        } catch {
            Write-Log "[Get-PasswordResetRights] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-PasswordResetRights] Analysis completed"
    }
}



# ----- Get-AddComputerRights.ps1 -----

function Get-AddComputerRights {
    <#
    .SYNOPSIS
    Analyzes "Add Computer to Domain" permissions and quota settings.

    .DESCRIPTION
    Performs comprehensive analysis of computer account creation permissions:

    1. ms-DS-MachineAccountQuota (Domain attribute)
       - Default: 10 (any authenticated user can add 10 computers)
       - Secure: 0 (only explicit permissions)

    2. ACL on CN=Computers container
       - Create Computer Objects permission
       - Extended Right "Add workstations to domain"

    3. GPO User Rights Assignment
       - "Add workstations to domain" (SeMachineAccountPrivilege)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-AddComputerRights

    .EXAMPLE
    Get-AddComputerRights -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Rights
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        Write-Log "[Get-AddComputerRights] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            $domainDN = $Script:LDAPContext.DomainDN
            $domainFQDN = $Script:LDAPContext.Domain

            Show-SubHeader "Analyzing Add Computer to Domain rights..." -ObjectType "AddComputerRight"

            $hasFindings = $false
            $quotaValue = 0

            # ===== Step 1: Check ms-DS-MachineAccountQuota =====
            # Escape DN for LDAP filter to prevent injection (RFC 4515)
            $escapedDomainDN = Escape-LDAPFilterDN -DistinguishedName $domainDN
            $domainResult = @(Get-DomainObject -LDAPFilter "(distinguishedName=$escapedDomainDN)" @connectionParams)[0]
            $machineQuota = if ($domainResult -and $domainResult.'ms-DS-MachineAccountQuota') {
                $domainResult.'ms-DS-MachineAccountQuota'
            } else {
                $null
            }

            if ($null -ne $machineQuota) {
                $quotaValue = if ($machineQuota -is [array]) { [int]$machineQuota[0] } else { [int]$machineQuota }
            } else {
                # Not configured = defaults to 10
                $quotaValue = 10
            }

            # ===== Step 2: Check ACL on CN=Computers Container =====
            $computersContainerDN = "CN=Computers,$domainDN"
            $createComputerAccounts = @()

            # Use Get-ObjectACL for ACL analysis (handles credentials automatically)
            $computerClassGUID = 'bf967a86-0de6-11d0-a285-00aa003049e2'
            $aclResult = Get-ObjectACL -DistinguishedName $computersContainerDN -Rights 'GenericAll','CreateChild' -AllowOnly -ExplicitOnly @connectionParams

            if ($aclResult -and $aclResult.ACEs) {
                $seenSIDs = @{}

                foreach ($ace in $aclResult.ACEs) {
                    $trusteeSID = $ace.TrusteeSID

                    # Skip ACEs with empty SID (can occur with orphaned/deleted principals)
                    if ([string]::IsNullOrEmpty($trusteeSID)) {
                        Write-Log "[Get-AddComputerRights] Skipping ACE with empty SID"
                        continue
                    }

                    if ($seenSIDs.ContainsKey($trusteeSID)) { continue }

                    # Check if this ACE grants CreateChild for Computer objects
                    $hasCreateChild = $false
                    if ($ace.RightsRaw -contains 'GenericAll') {
                        $hasCreateChild = $true
                    } elseif ($ace.RightsRaw -contains 'CreateChild') {
                        # CreateChild must be for all objects or specifically for Computer class
                        if (-not $ace.ObjectType -or $ace.ObjectType -eq $computerClassGUID) {
                            $hasCreateChild = $true
                        }
                    }

                    if ($hasCreateChild) {
                        $seenSIDs[$trusteeSID] = $true

                        # CN=Computers is a Container - use context-specific filtering
                        # SELF, Creator Owner, Pre-Windows 2000 Compatible Access are NORMAL here
                        $expectedCheck = Test-IsExpectedACLIdentity -SID $trusteeSID -Context 'Container'
                        if ($expectedCheck.Skip) {
                            Write-Log "[Get-AddComputerRights] Skipping expected identity: $($ace.Trustee) ($trusteeSID) - $($expectedCheck.Reason)"
                            continue
                        }

                        # Skip Authenticated Users if quota > 0 (they already have implicit rights via quota)
                        if ($trusteeSID -eq 'S-1-5-11' -and $quotaValue -gt 0) {
                            Write-Log "[Get-AddComputerRights] Skipping Authenticated Users ACL (already covered by quota)"
                            continue
                        }

                        # Determine severity
                        $severity = 'Finding'

                        if (-not $IncludePrivileged) {
                            # Use scope-based check for CN=Computers container ACL rights
                            $scopeResult = Test-IsExpectedInScope -Identity $trusteeSID -Scope 'ComputerContainerACL' -ReturnDetails

                            if ($scopeResult.Severity -eq 'Expected') {
                                Write-Log "[Get-AddComputerRights] CreateChild (expected): $($ace.Trustee) - $($scopeResult.Reason)"
                                continue
                            }

                            if ($scopeResult.Severity -eq 'Attention') {
                                Write-Log "[Get-AddComputerRights] CreateChild (attention): $($ace.Trustee) - $($scopeResult.Reason) - skipped (use -IncludePrivileged to include)"
                                continue
                            }

                            $severity = $scopeResult.Severity
                        } else {
                            # -IncludePrivileged: Show ALL accounts, but mark privileged ones for yellow display
                            $scopeResult = Test-IsExpectedInScope -Identity $trusteeSID -Scope 'ComputerContainerACL' -ReturnDetails
                            $severity = $scopeResult.Severity
                            Write-Log "[Get-AddComputerRights] IncludePrivileged: Including $($ace.Trustee) ($trusteeSID) with severity $severity"
                        }

                        $createComputerAccounts += [PSCustomObject]@{
                            SID = $trusteeSID
                            Name = $ace.Trustee
                            Severity = $severity
                        }
                    }
                }
            }

            # ===== Step 3: Check GPO User Rights Assignment =====
            $gpoFindings = @(Check-GPOAddComputerRights -DomainFQDN $domainFQDN @connectionParams)

            # ===== Step 4: Output findings as objects =====

            # Finding 1: MachineAccountQuota as object
            # Note: Quota > 0 is a Hint (not Finding) - it's a configuration worth noting but not critical
            if ($quotaValue -eq 0) {
                Show-Line "ms-DS-MachineAccountQuota is 0 - computer creation restricted to explicit permissions" -Class Secure
            } else {
                Show-Line "Found ms-DS-MachineAccountQuota configured - any authenticated user can add computers:" -Class Hint

                $quotaObject = [PSCustomObject]@{
                    'ms-DS-MachineAccountQuota' = $quotaValue
                }
                $quotaObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'MachineAccountQuota' -Force
                Show-Object $quotaObject
                $hasFindings = $true
            }

            # Finding 2: Explicit ACLs on CN=Computers (show full AD objects)
            if (@($createComputerAccounts).Count -gt 0) {
                Show-Line "Found $(@($createComputerAccounts).Count) account(s) with explicit CreateChild rights on CN=Computers:" -Class Finding

                foreach ($account in $createComputerAccounts) {
                    # Check if this is a well-known SID that does NOT belong to the domain partition.
                    # This covers all SIDs that have no domain-specific sub-authorities (S-1-5-21-*):
                    #   - Simple well-known SIDs:  S-1-1-0, S-1-5-11, S-1-5-18 (single authority)
                    #   - BUILTIN group SIDs:       S-1-5-32-544, S-1-5-32-554  (authority + one RID)
                    #   - Other special SIDs:       S-1-3-0, S-1-16-* etc.
                    # These objects do NOT exist as AD objects in the domain partition, so an LDAP
                    # objectSid query would always return nothing and fall into the UNRESOLVABLE path.
                    # ConvertFrom-SID resolves them directly via $Script:SIDToName.
                    $isWellKnownSID = $account.SID -notmatch '^S-1-5-21-'

                    # Try to resolve the SID to a full AD object (skip for well-known SIDs)
                    $adObject = $null
                    if (-not $isWellKnownSID) {
                        $sidHex = ConvertTo-LDAPSIDHex -SID $account.SID
                        if ($sidHex) {
                            $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                        }
                    }

                    if ($adObject) {
                        $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue "CreateChild (Computer) on CN=Computers" -Force
                        $adObject | Add-Member -NotePropertyName 'targetContainer' -NotePropertyValue $computersContainerDN -Force
                        if ($account.Severity -in @('Expected', 'Attention')) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'AddComputerRight' -Force
                        Show-Object $adObject
                    } else {
                        # Fallback for well-known SIDs, foreign/deleted principals
                        # For well-known SIDs, resolve name via ConvertFrom-SID
                        $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $account.SID } else { $account.Name }
                        $fallbackObject = [PSCustomObject]@{
                            sAMAccountName = $resolvedName
                            objectSid = $account.SID
                            dangerousRights = "CreateChild (Computer) on CN=Computers"
                            targetContainer = $computersContainerDN
                        }
                        if ($account.Severity -in @('Expected', 'Attention')) {
                            $fallbackObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                        }
                        $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'AddComputerRight' -Force
                        Show-Object $fallbackObject
                    }
                }
                $hasFindings = $true
            }

            # Finding 3: GPO grants SeMachineAccountPrivilege - as enriched native GPO objects
            # Note: Hint (not Finding) because GPO privilege alone doesn't enable computer creation without quota
            $dangerousGPOs = @($gpoFindings | Where-Object { $_._HasAuthenticatedUsers -or $_._HasEveryone })

            if (@($dangerousGPOs).Count -gt 0) {
                $effectiveGPO = @($gpoFindings | Where-Object { $_.IsEffectiveSetting -eq $true })[0]
                $effectiveIsDangerous = $effectiveGPO -and ($effectiveGPO._HasAuthenticatedUsers -or $effectiveGPO._HasEveryone)

                $lineClass = if ($effectiveIsDangerous) { "Hint" } else { "Secure" }
                Show-Line "Found $(@($gpoFindings).Count) GPO(s) configuring SeMachineAccountPrivilege:" -Class $lineClass

                # Show all GPOs that define SeMachineAccountPrivilege, sorted by precedence (highest first)
                $scopePriorityMap = @{ "DomainControllers" = 1; "Domain" = 2; "NotLinked" = 3 }
                $sortedGPOs = @($gpoFindings | Sort-Object @{Expression={$scopePriorityMap[$_._PrecedenceScope]}}, _PrecedenceOrder)

                foreach ($gpo in $sortedGPOs) {
                    $gpo | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'AddComputerGPO' -Force

                    $isEffective = $gpo.IsEffectiveSetting -eq $true
                    $isDangerous = $gpo._HasAuthenticatedUsers -or $gpo._HasEveryone
                    $objectClass = if ($isEffective) {
                        if ($effectiveIsDangerous) { "Hint" } else { "Secure" }
                    } else {
                        if ($isDangerous) { "Hint" } else { "Standard" }
                    }
                    Show-Object $gpo -Class $objectClass
                }
                $hasFindings = $true
            }

            if (-not $hasFindings) {
                Show-Line "Add Computer to Domain rights properly configured" -Class Secure
            }

        } catch {
            Write-Log "[Get-AddComputerRights] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-AddComputerRights] Check completed"
    }
}

# Helper Function: Check GPO User Rights Assignment
function Check-GPOAddComputerRights {
    [CmdletBinding()]
    param(
        [string]$DomainFQDN,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    try {
        # Build connection parameters (exclude DomainFQDN which is not a Get-DomainGPO parameter)
        $connectionParams = @{}
        if ($Domain) { $connectionParams['Domain'] = $Domain }
        if ($Server) { $connectionParams['Server'] = $Server }
        if ($Credential) { $connectionParams['Credential'] = $Credential }

        $gpos = Get-DomainGPO @connectionParams

        if (-not $gpos -or @($gpos).Count -eq 0) { return @() }

        $dcServer = $Script:LDAPContext.Server
        $domainDN = $Script:LDAPContext.DomainDN
        $dcOUDN = "OU=Domain Controllers,$domainDN"

        # Build GPO precedence map using Get-GPOLinkage (which reliably reads gPLink via Invoke-LDAPSearch)
        # Filter to DC OU and domain root - these are the containers that determine effective DC policy
        Write-Log "[Check-GPOAddComputerRights] Building GPO precedence map from GPO linkage data"
        $Script:gpoAddComputerPrecedenceMap = @{}

        $allGPOLinkage = Get-GPOLinkage
        if ($allGPOLinkage) {
            $dcOUDNUpper = $dcOUDN.ToUpper()
            $domainDNUpper = $domainDN.ToUpper()

            foreach ($gpoGUID in $allGPOLinkage.Keys) {
                foreach ($linkInfo in $allGPOLinkage[$gpoGUID]) {
                    if ($linkInfo.IsDisabled) { continue }

                    $linkDNUpper = $linkInfo.DistinguishedName.ToUpper()
                    $precedenceScope = $null

                    if ($linkDNUpper -eq $dcOUDNUpper) {
                        $precedenceScope = "DomainControllers"
                    } elseif ($linkDNUpper -eq $domainDNUpper) {
                        $precedenceScope = "Domain"
                    }

                    if ($precedenceScope -and -not $Script:gpoAddComputerPrecedenceMap.ContainsKey($gpoGUID)) {
                        $Script:gpoAddComputerPrecedenceMap[$gpoGUID] = [PSCustomObject]@{
                            GUID      = $gpoGUID
                            Scope     = $precedenceScope
                            LinkOrder = $linkInfo.LinkOrder
                        }
                    }
                }
            }
        }
        Write-Log "[Check-GPOAddComputerRights] Precedence map: $($Script:gpoAddComputerPrecedenceMap.Count) GPO(s) linked to DC OU or domain root"

        # Use Invoke-SMBAccess for SYSVOL access (handles SimpleBind credentials and custom DNS)
        $Script:gpoAddComputerFindings = @()

        Invoke-SMBAccess -Description "Scanning GPO User Rights Assignment" -ScriptBlock {
            $sysvolPath = "\\$dcServer\SYSVOL\$DomainFQDN\Policies"

            if (-not (Test-Path $sysvolPath)) {
                Write-Log "[Check-GPOAddComputerRights] SYSVOL path not accessible: $sysvolPath"
                return
            }

            # Iterate the cached SYSVOL listing instead of probing a constructed path per GPO:
            # most GPOs have no GptTmpl.inf, so per-GPO probing costs one SMB round-trip each
            # for a file that usually does not exist.
            $gptTmplFiles = @(Get-CachedSYSVOLFiles -Filter "GptTmpl.inf")

            # GPO GUID -> GPO object, to resolve the file back to its GPO
            $gpoByGuid = @{}
            foreach ($g in $gpos) {
                if ($g.Name) { $gpoByGuid[$g.Name.ToUpper()] = $g }
            }

            $totalGPOs = $gptTmplFiles.Count
            $currentGPOIndex = 0
            foreach ($file in $gptTmplFiles) {
                # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                if ($file.FullName -notmatch '\\Policies\\(\{[^}]+\})\\') { continue }
                $gpo = $gpoByGuid[$Matches[1].ToUpper()]
                if (-not $gpo) { continue }

                $currentGPOIndex++
                if ($totalGPOs -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Scanning GPO user rights assignment" -Current $currentGPOIndex -Total $totalGPOs -ObjectName $gpo.DisplayName
                }

                $content = Get-CachedSYSVOLContent -Path $file.FullName
                if ($content) {
                    if ($content -match '(?is)\[Privilege Rights\](.*?)(\[|$)') {
                        $privilegeRightsSection = $Matches[1]

                        if ($privilegeRightsSection -match '(?i)SeMachineAccountPrivilege\s*=\s*(.+)') {
                            $accountsLine = $Matches[1].Trim()
                            $accounts = $accountsLine -split ',' | ForEach-Object { $_.Trim().TrimStart('*') }

                            $accountNames = @()
                            $hasAuthenticatedUsers = $false
                            $hasEveryone = $false

                            foreach ($account in $accounts) {
                                if ([string]::IsNullOrWhiteSpace($account)) { continue }
                                $accountName = ConvertFrom-SID -SID $account
                                $accountNames += $accountName

                                # SID-based detection (language-independent)
                                # S-1-5-11 = Authenticated Users, S-1-1-0 = Everyone
                                if ($account -match 'S-1-5-11') { $hasAuthenticatedUsers = $true }
                                if ($account -match 'S-1-1-0')  { $hasEveryone = $true }
                            }

                            # Get linkage data for Scope/LinkedOUs (same pattern as LDAP/SMB checks)
                            $gpoLinkage = Get-GPOLinkage
                            $gpoGUIDKey = $gpo.Name.ToUpper()
                            $links = if ($gpoLinkage) { $gpoLinkage[$gpoGUIDKey] } else { $null }
                            $activeLinks = @()
                            $isDomainWide = $false

                            if ($links) {
                                $activeLinks = @($links | Where-Object { $_.LinkStatus -ne "Disabled" })
                                $isDomainWide = ($null -ne ($activeLinks | Where-Object { $_.Scope -eq "Domain" }))
                            }

                            # Determine precedence info (for effective setting calculation after scriptblock)
                            $precedenceInfo = $Script:gpoAddComputerPrecedenceMap[$gpoGUIDKey]
                            $precedenceScope = if ($precedenceInfo) { $precedenceInfo.Scope } else { "NotLinked" }
                            $precedenceOrder = if ($precedenceInfo -and $precedenceInfo.LinkOrder) { $precedenceInfo.LinkOrder } else { 999 }

                            # Enrich native GPO object (matching LDAP/SMB display pattern)
                            $gpo | Add-Member -NotePropertyName 'Accounts'              -NotePropertyValue $accountNames -Force
                            $gpo | Add-Member -NotePropertyName 'IsEffectiveSetting'    -NotePropertyValue $false -Force

                            if (@($activeLinks).Count -gt 0) {
                                $linkedOUsDisplay = @($activeLinks | ForEach-Object { $_.DistinguishedName })
                                $gpo | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUsDisplay -Force
                                $scopeInfo = if ($isDomainWide) {
                                    "Domain-wide ($(@($activeLinks).Count) link(s))"
                                } else {
                                    "$(@($activeLinks).Count) OU(s)"
                                }
                                $gpo | Add-Member -NotePropertyName 'Scope' -NotePropertyValue $scopeInfo -Force
                            } else {
                                $gpo | Add-Member -NotePropertyName 'Scope' -NotePropertyValue "NOT LINKED" -Force
                            }

                            # Internal precedence fields (not displayed, used for effective determination)
                            $gpo | Add-Member -NotePropertyName '_PrecedenceScope'        -NotePropertyValue $precedenceScope -Force
                            $gpo | Add-Member -NotePropertyName '_PrecedenceOrder'        -NotePropertyValue $precedenceOrder -Force
                            $gpo | Add-Member -NotePropertyName '_HasAuthenticatedUsers'  -NotePropertyValue $hasAuthenticatedUsers -Force
                            $gpo | Add-Member -NotePropertyName '_HasEveryone'            -NotePropertyValue $hasEveryone -Force

                            $Script:gpoAddComputerFindings += $gpo
                        }
                    }
                }
            }
            if ($totalGPOs -gt $Script:ProgressThreshold) {
                Show-Progress -Activity "Scanning GPO user rights assignment" -Completed
            }
        }

        $result = $Script:gpoAddComputerFindings
        $Script:gpoAddComputerFindings = $null
        $Script:gpoAddComputerPrecedenceMap = $null

        # Determine effective setting: DC OU GPOs take precedence over Domain GPOs;
        # within same scope, lower _PrecedenceOrder = higher priority (1 = highest)
        $linkedResults = @($result | Where-Object { $_._PrecedenceScope -ne "NotLinked" })
        if ($linkedResults.Count -gt 0) {
            $scopePriority = @{ "DomainControllers" = 1; "Domain" = 2 }
            $effectiveGPO = $linkedResults | Sort-Object @{Expression={$scopePriority[$_._PrecedenceScope]}}, _PrecedenceOrder | Select-Object -First 1
            if ($effectiveGPO) {
                $effectiveGPO.IsEffectiveSetting = $true
                Write-Log "[Check-GPOAddComputerRights] Effective GPO: '$($effectiveGPO.displayName)' (Scope=$($effectiveGPO._PrecedenceScope), LinkOrder=$($effectiveGPO._PrecedenceOrder))"
            }
        }

        return $result
    } catch {
        Write-Log "[Check-GPOAddComputerRights] Error: $_" -Level Error
        return @()
    }
}



# ----- Get-GPOUserRightsAssignment.ps1 -----

function Get-GPOUserRightsAssignment {
    <#
    .SYNOPSIS
    Detects dangerous Windows user rights / privileges assigned to non-privileged
    principals via Group Policy.

    .DESCRIPTION
    Parses the [Privilege Rights] section of GptTmpl.inf in every GPO's SYSVOL folder
    and flags assignments of sensitive user rights to non-privileged principals.

    User Rights Assignment via GPO is a classic, often-overlooked privilege-escalation and
    lateral-movement vector: a single GPO can grant rights like "Debug programs"
    (SeDebugPrivilege), "Back up files and directories" (SeBackupPrivilege) or
    "Allow log on through Remote Desktop Services" to a low-privileged principal across
    every computer the GPO applies to.

    Covered rights (two tiers):
    - Finding (direct SYSTEM / credential / domain compromise): SeDebug, SeTcb,
      SeImpersonate, SeAssignPrimaryToken, SeCreateToken, SeLoadDriver, SeBackup, SeRestore,
      SeTakeOwnership, SeEnableDelegation, SeSyncAgent, SeManageVolume, SeSecurity,
      SeRelabel, SeTrustedCredManAccess.
    - Hint (lateral movement / lower direct impact): SeRemoteInteractiveLogonRight (RDP),
      SeServiceLogonRight, SeBatchLogonRight, SeInteractiveLogonRight, SeSystemtime,
      SeRemoteShutdown, SeShutdown.

    Any right granted to a broad principal (Everyone, Authenticated Users, Domain Users,
    Users) is escalated to Finding regardless of tier.

    Note: SeMachineAccountPrivilege ("Add workstations to domain") is intentionally NOT
    reported here - it is covered by Get-AddComputerRights. Protective Se*Deny* rights are
    ignored.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER IncludePrivileged
    Also report rights granted to privileged principals (Domain Admins, Administrators,
    etc.). By default these are hidden as expected.

    .EXAMPLE
    Get-GPOUserRightsAssignment

    .EXAMPLE
    Get-GPOUserRightsAssignment -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Rights
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        Write-Log "[Get-GPOUserRightsAssignment] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged - not a connection parameter)
            $CredParams = @{}
            if ($Domain) { $CredParams['Domain'] = $Domain }
            if ($Server) { $CredParams['Server'] = $Server }
            if ($Credential) { $CredParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @CredParams)) {
                return
            }

            Show-SubHeader "Searching for dangerous user rights assigned via GPO..." -ObjectType "GPOUserRights"

            # Dangerous user rights -> friendly name + severity tier.
            # The attack-vector context lives in the GPO_DANGEROUS_USER_RIGHT finding definition
            # and is surfaced as an HTML tooltip (triggered on the 'userRight' attribute).
            $dangerousRights = [ordered]@{
                'SeDebugPrivilege'                = @{ Name = 'Debug programs';                                  Tier = 'Finding' }
                'SeTcbPrivilege'                  = @{ Name = 'Act as part of the operating system';              Tier = 'Finding' }
                'SeImpersonatePrivilege'          = @{ Name = 'Impersonate a client after authentication';       Tier = 'Finding' }
                'SeAssignPrimaryTokenPrivilege'   = @{ Name = 'Replace a process level token';                   Tier = 'Finding' }
                'SeCreateTokenPrivilege'          = @{ Name = 'Create a token object';                           Tier = 'Finding' }
                'SeLoadDriverPrivilege'           = @{ Name = 'Load and unload device drivers';                  Tier = 'Finding' }
                'SeBackupPrivilege'               = @{ Name = 'Back up files and directories';                   Tier = 'Finding' }
                'SeRestorePrivilege'              = @{ Name = 'Restore files and directories';                   Tier = 'Finding' }
                'SeTakeOwnershipPrivilege'        = @{ Name = 'Take ownership of files or other objects';        Tier = 'Finding' }
                'SeEnableDelegationPrivilege'     = @{ Name = 'Enable computer/user accounts to be trusted for delegation'; Tier = 'Finding' }
                'SeSyncAgentPrivilege'            = @{ Name = 'Synchronize directory service data';              Tier = 'Finding' }
                'SeManageVolumePrivilege'         = @{ Name = 'Perform volume maintenance tasks';                Tier = 'Finding' }
                'SeSecurityPrivilege'             = @{ Name = 'Manage auditing and security log';                Tier = 'Finding' }
                'SeRelabelPrivilege'              = @{ Name = 'Modify an object label';                          Tier = 'Finding' }
                'SeTrustedCredManAccessPrivilege' = @{ Name = 'Access Credential Manager as a trusted caller';   Tier = 'Finding' }
                'SeRemoteInteractiveLogonRight'   = @{ Name = 'Allow log on through Remote Desktop Services';    Tier = 'Hint' }
                'SeServiceLogonRight'             = @{ Name = 'Log on as a service';                             Tier = 'Hint' }
                'SeBatchLogonRight'               = @{ Name = 'Log on as a batch job';                           Tier = 'Hint' }
                'SeInteractiveLogonRight'         = @{ Name = 'Allow log on locally';                            Tier = 'Hint' }
                'SeSystemtimePrivilege'           = @{ Name = 'Change the system time';                          Tier = 'Hint' }
                'SeRemoteShutdownPrivilege'       = @{ Name = 'Force shutdown from a remote system';             Tier = 'Hint' }
                'SeShutdownPrivilege'             = @{ Name = 'Shut down the system';                            Tier = 'Hint' }
            }

            # Broad principals (Everyone, Authenticated Users, Domain Users, etc.) use the central
            # definitions in adPEAS-SIDs.ps1 ($Script:BroadGroupSIDs / $Script:BroadGroupRIDSuffixes)
            # via Test-IsBroadGroupSID / Test-IsBroadGroupRID. A sensitive right granted to one of
            # these is always escalated to Finding.

            # Enumerate GPOs and linkage once
            $gpos = @(Get-DomainGPO @CredParams)
            if ($gpos.Count -eq 0) {
                Show-Line "No GPOs found" -Class "Note"
                return
            }

            $gpoLinkage = Get-GPOLinkage
            $domainFQDN = $Script:LDAPContext.Domain
            $dcServer = $Script:LDAPContext.Server

            # Closure-visible state
            $includePriv = [bool]$IncludePrivileged
            $rightsMap = $dangerousRights
            $linkage = $gpoLinkage
            $Script:gpoUserRightsFindings = @()

            Invoke-SMBAccess -Description "Scanning GPO user rights assignments" -ScriptBlock {
                $sysvolPath = "\\$dcServer\SYSVOL\$domainFQDN\Policies"
                if (-not (Test-Path $sysvolPath)) {
                    Write-Log "[Get-GPOUserRightsAssignment] SYSVOL path not accessible: $sysvolPath"
                    return
                }

                # Iterate the cached SYSVOL listing instead of probing a constructed path per GPO:
                # most GPOs have no GptTmpl.inf, so per-GPO probing costs one SMB round-trip each
                # for a file that usually does not exist.
                $gptTmplFiles = @(Get-CachedSYSVOLFiles -Filter "GptTmpl.inf")

                # GPO GUID -> GPO object, to resolve the file back to its GPO
                $gpoByGuid = @{}
                foreach ($g in $gpos) {
                    if ($g.Name) { $gpoByGuid[$g.Name.ToUpper()] = $g }
                }

                $totalGPOs = $gptTmplFiles.Count
                $currentGPOIndex = 0
                foreach ($file in $gptTmplFiles) {
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                    if ($file.FullName -notmatch '\\Policies\\(\{[^}]+\})\\') { continue }
                    $gpo = $gpoByGuid[$Matches[1].ToUpper()]
                    if (-not $gpo) { continue }

                    $currentGPOIndex++
                    if ($totalGPOs -gt $Script:ProgressThreshold) {
                        Show-Progress -Activity "Scanning GPO user rights assignments" -Current $currentGPOIndex -Total $totalGPOs -ObjectName $gpo.displayName
                    }

                    $content = Get-CachedSYSVOLContent -Path $file.FullName
                    if (-not $content) { continue }
                    if ($content -notmatch '(?is)\[Privilege Rights\](.*?)(\[|$)') { continue }
                    $section = $Matches[1]

                    # Resolve linkage scope once per GPO
                    $gpoGUIDKey = $gpo.Name.ToUpper()
                    $links = if ($linkage) { $linkage[$gpoGUIDKey] } else { $null }
                    $activeLinks = @()
                    $isDomainWide = $false
                    if ($links) {
                        $activeLinks = @($links | Where-Object { $_.LinkStatus -ne "Disabled" })
                        $isDomainWide = ($null -ne ($activeLinks | Where-Object { $_.Scope -eq "Domain" }))
                    }
                    if (@($activeLinks).Count -gt 0) {
                        $linkedOUs = @($activeLinks | ForEach-Object { $_.DistinguishedName })
                        $scopeInfo = if ($isDomainWide) { "Domain-wide ($(@($activeLinks).Count) link(s))" } else { "$(@($activeLinks).Count) OU(s)" }
                    } else {
                        $linkedOUs = @()
                        $scopeInfo = "NOT LINKED"
                    }

                    foreach ($right in $rightsMap.Keys) {
                        $pattern = '(?im)^\s*' + [regex]::Escape($right) + '\s*=\s*(.+)$'
                        $m = [regex]::Match($section, $pattern)
                        if (-not $m.Success) { continue }

                        $tokens = $m.Groups[1].Value -split ',' | ForEach-Object { $_.Trim() }
                        $keptNames = @()
                        $anyBroad = $false

                        foreach ($token in $tokens) {
                            $raw = $token.TrimStart('*')
                            if ([string]::IsNullOrWhiteSpace($raw)) { continue }

                            # Resolve literal account names to a SID for consistent classification
                            # (GptTmpl.inf almost always uses *SID, but names can appear).
                            $sid = $raw
                            if ($raw -notmatch '^S-1-') {
                                $resolved = $null
                                try { $resolved = ConvertTo-SID -Identity $raw } catch { }
                                if ($resolved) { $sid = $resolved }
                            }

                            if ($sid -match '^S-1-') {
                                # Skip principals that are expected to hold user rights by default:
                                #  - privileged SIDs/RIDs (Administrators, Domain Admins, SYSTEM, ...)
                                #  - built-in operator groups (Account/Server/Print/Backup Operators) - the
                                #    Default Domain Controllers Policy grants these to them by design
                                #  - well-known service / builtin-support identities (SERVICE, IIS_IUSRS,
                                #    Performance Log Users, ...) - default holders, not privesc targets
                                $isPriv = (Test-IsPrivilegedSID -SID $sid) -or
                                          [bool](Test-IsPrivilegedRID -SID $sid) -or
                                          ($Script:OperatorSIDs -contains $sid) -or
                                          (Test-IsWellKnownServiceSID -SID $sid)
                                if ($isPriv -and -not $includePriv) { continue }
                                if ((Test-IsBroadGroupSID -SID $sid) -or [bool](Test-IsBroadGroupRID -SID $sid)) { $anyBroad = $true }
                                $keptNames += (ConvertFrom-SID -SID $sid)
                            } else {
                                # Unresolvable literal - include as-is (cannot classify)
                                $keptNames += $raw
                            }
                        }

                        if ($keptNames.Count -eq 0) { continue }

                        $info = $rightsMap[$right]
                        $severity = if ($anyBroad) { 'Finding' } else { $info.Tier }

                        $finding = [PSCustomObject]@{
                            gpoName       = $gpo.displayName
                            gpoGuid       = $gpo.Name
                            userRight     = $right
                            userRightName = $info.Name
                            principals    = $keptNames
                            scope         = $scopeInfo
                            linkedOUs     = $linkedOUs
                            _severity     = $severity
                        }
                        $Script:gpoUserRightsFindings += $finding
                    }
                }

                if ($totalGPOs -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Scanning GPO user rights assignments" -Completed
                }
            }

            $findings = @($Script:gpoUserRightsFindings)
            $Script:gpoUserRightsFindings = $null

            if ($findings.Count -gt 0) {
                # Header severity reflects the highest finding severity (red only if a real Finding exists)
                $hasFinding = @($findings | Where-Object { $_._severity -eq 'Finding' }).Count -gt 0
                $headerClass = if ($hasFinding) { "Finding" } else { "Hint" }
                Show-Line "Found $($findings.Count) dangerous user right assignment(s) via GPO:" -Class $headerClass
                # Findings first, then hints (severity order)
                $ordered = @($findings | Sort-Object @{Expression={ if ($_._severity -eq 'Finding') { 0 } else { 1 } }}, gpoName, userRight)
                foreach ($finding in $ordered) {
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPOUserRights' -Force
                    Show-Object $finding -Class $finding._severity
                }
            } elseif ((Test-SysvolAccessible) -eq $false) {
                # SYSVOL could not be read - report honestly instead of implying a clean result
                Show-Line "SYSVOL is not accessible - GPO user rights could not be evaluated" -Class "Note"
            } else {
                Show-Line "No dangerous user rights assigned via GPO to non-privileged principals" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-GPOUserRightsAssignment] Error: $_" -Level Error
            Show-Line "Error during check: $_" -Class "Finding"
        } finally {
            $Script:gpoUserRightsFindings = $null
        }
    }

    end {
        Write-Log "[Get-GPOUserRightsAssignment] Check completed"
    }
}



# ----- Get-LAPSPermissions.ps1 -----

function Get-LAPSPermissions {
    <#
    .SYNOPSIS
    Analyzes LAPS password read permissions across Organizational Units.

    .DESCRIPTION
    Scans all OUs containing computers and identifies who has permissions to read LAPS password attributes:

    - ms-Mcs-AdmPwd (Legacy LAPS)
    - msLAPS-Password (Windows LAPS Native)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER IncludePrivileged
    Also report privileged accounts with LAPS read access (shown as yellow/Hint severity).

    .EXAMPLE
    Get-LAPSPermissions

    .EXAMPLE
    Get-LAPSPermissions -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Rights
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        Write-Log "[Get-LAPSPermissions] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Analyzing LAPS read permissions by OU..." -ObjectType "LAPSPermission"

            # Check if LAPS schema info is available
            $lapsLegacySchemaPresent = $false
            $windowsLAPSSchemaPresent = $false

            if ($Script:LAPSSchemaInfo) {
                $lapsLegacySchemaPresent = $Script:LAPSSchemaInfo.LegacyPresent
                $windowsLAPSSchemaPresent = $Script:LAPSSchemaInfo.NativePresent
            } else {
                # Detect schema ourselves using Invoke-LDAPSearch with Schema Partition
                $schemaDN = $Script:LDAPContext.SchemaNamingContext

                if ($schemaDN) {
                    try {
                        # Check for Legacy LAPS schema attribute using Invoke-LDAPSearch
                        $legacySchemaFilter = "(&(objectClass=attributeSchema)(|(lDAPDisplayName=ms-Mcs-AdmPwdExpirationTime)(cn=ms-Mcs-AdmPwdExpirationTime)))"
                        $legacyResult = Invoke-LDAPSearch -Filter $legacySchemaFilter -SearchBase $schemaDN -Properties 'cn' -SizeLimit 1
                        if ($legacyResult) { $lapsLegacySchemaPresent = $true }

                        # Check for Windows LAPS Native schema attribute
                        $nativeSchemaFilter = "(&(objectClass=attributeSchema)(|(lDAPDisplayName=msLAPS-PasswordExpirationTime)(cn=msLAPS-PasswordExpirationTime)))"
                        $nativeResult = Invoke-LDAPSearch -Filter $nativeSchemaFilter -SearchBase $schemaDN -Properties 'cn' -SizeLimit 1
                        if ($nativeResult) { $windowsLAPSSchemaPresent = $true }
                    } catch {
                        Write-Log "[Get-LAPSPermissions] Schema query error: $($_.Exception.Message)"
                    }
                }

                # Fallback: check computer objects
                if (-not $lapsLegacySchemaPresent -and -not $windowsLAPSSchemaPresent) {
                    $legacyCheck = Get-DomainComputer -LDAPFilter "(ms-Mcs-AdmPwdExpirationTime=*)" -ResultLimit 1 @connectionParams
                    if ($legacyCheck) { $lapsLegacySchemaPresent = $true }

                    $nativeCheck = Get-DomainComputer -LDAPFilter "(msLAPS-PasswordExpirationTime=*)" -ResultLimit 1 @connectionParams
                    if ($nativeCheck) { $windowsLAPSSchemaPresent = $true }
                }

                # Cache schema info for other LAPS modules
                $Script:LAPSSchemaInfo = @{
                    LegacyPresent = $lapsLegacySchemaPresent
                    NativePresent = $windowsLAPSSchemaPresent
                }
            }

            if (-not $lapsLegacySchemaPresent -and -not $windowsLAPSSchemaPresent) {
                Show-Line "No LAPS schema found" -Class Note
                return
            }

            # Get all enabled computers and group by OU (only properties needed for filtering and grouping)
            # -Enabled filters server-side, Test-AccountActivity -IsActive uses $Script:DefaultInactiveDays
            $allComputers = @(Get-DomainComputer -Enabled -Properties "distinguishedName","lastLogonTimestamp" @connectionParams | Test-AccountActivity -IsActive)

            $computersByOU = @{}
            foreach ($computer in $allComputers) {
                $dn = $computer.distinguishedName
                if ($dn -match '^CN=[^,]+,(.+)$') {
                    $ouDN = $Matches[1]
                    if (-not $computersByOU.ContainsKey($ouDN)) {
                        $computersByOU[$ouDN] = 0
                    }
                    $computersByOU[$ouDN]++
                }
            }

            Write-Log "[Get-LAPSPermissions] Found $(@($computersByOU.Keys).Count) unique OUs with computers"

            # Analyze permissions for each OU
            $ouPermissionsResults = @()
            $filteredFindings = @()
            $allowedSeverities = if ($IncludePrivileged) { @('Critical', 'High', 'Medium', 'Info') } else { @('Critical', 'High', 'Medium') }

            $totalOUs = $computersByOU.Keys.Count
            $currentIndex = 0
            foreach ($ouDN in $computersByOU.Keys) {
                $currentIndex++
                if ($totalOUs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking LAPS permissions" -Current $currentIndex -Total $totalOUs -ObjectName $ouDN }
                $computerCount = $computersByOU[$ouDN]
                Write-Log "[Get-LAPSPermissions] Analyzing OU: $ouDN ($computerCount computers)"

                try {
                    # Get-OUPermissions uses session context automatically
                    $ouPerms = Get-OUPermissions -DistinguishedName $ouDN -CheckType 'LAPS'

                    if ($ouPerms -and $ouPerms.Findings) {
                        $legacyReaders = @()
                        $nativeReaders = @()

                        foreach ($finding in $ouPerms.Findings) {
                            $principal = $finding.Principal
                            $sid = $finding.SID
                            $severity = $finding.Severity

                            # Match Legacy LAPS (ms-Mcs-AdmPwd)
                            if ($finding.Right -match 'ms-Mcs-AdmPwd') {
                                if ($sid -notin @($legacyReaders | ForEach-Object { $_.SID })) {
                                    $legacyReaders += [PSCustomObject]@{
                                        Principal = $principal
                                        SID = $sid
                                        Severity = $severity
                                    }
                                }
                            }
                            # Match Windows LAPS (msLAPS-*) - includes EncryptedPassword, EncryptedPasswordHistory, Password, etc.
                            # Also match "All Properties" which covers all LAPS types
                            elseif ($finding.Right -match 'msLAPS-' -or $finding.Right -match 'All Properties') {
                                if ($sid -notin @($nativeReaders | ForEach-Object { $_.SID })) {
                                    $nativeReaders += [PSCustomObject]@{
                                        Principal = $principal
                                        SID = $sid
                                        Severity = $severity
                                    }
                                }
                            }
                        }

                        # Filter findings by allowed severities
                        # Check each reader for Exchange service group membership
                        $allReaders = $legacyReaders + $nativeReaders
                        $matchedReaders = @($allReaders | Where-Object { $_.Severity -in $allowedSeverities })

                        foreach ($reader in $matchedReaders) {
                            # Check if this is an Exchange service group
                            $exchangeCheck = Test-IsExchangeServiceGroup -Identity $reader.SID
                            if ($exchangeCheck.IsExchangeService) {
                                $reader | Add-Member -NotePropertyName 'IsExchangeService' -NotePropertyValue $true -Force
                                $reader | Add-Member -NotePropertyName 'OriginalSeverity' -NotePropertyValue $reader.Severity -Force
                                $reader.Severity = 'Attention'
                                Write-Log "[Get-LAPSPermissions] Exchange service group detected: $($reader.Principal)"
                            } else {
                                $reader | Add-Member -NotePropertyName 'IsExchangeService' -NotePropertyValue $false -Force
                                # Mark privileged accounts (Info from Get-OUPermissions) for yellow display
                                $isPriv = $reader.Severity -eq 'Info'
                                $reader | Add-Member -NotePropertyName 'IsPrivilegedAccount' -NotePropertyValue $isPriv -Force
                                if ($isPriv) {
                                    $reader | Add-Member -NotePropertyName 'OriginalSeverity' -NotePropertyValue $reader.Severity -Force
                                    $reader.Severity = 'Attention'
                                }
                            }
                        }

                        if (@($matchedReaders).Count -gt 0) {
                            $filteredFindings += [PSCustomObject]@{
                                OU = $ouDN
                                ComputerCount = $computerCount
                                MatchedReaders = $matchedReaders
                                LegacyReaders = $legacyReaders
                                NativeReaders = $nativeReaders
                            }
                        }

                        $ouPermissionsResults += [PSCustomObject]@{
                            OU = $ouDN
                            ComputerCount = $computerCount
                            LegacyReaders = $legacyReaders
                            NativeReaders = $nativeReaders
                        }
                    }
                } catch {
                    Write-Log "[Get-LAPSPermissions] Failed to query permissions for OU '$ouDN': $_"
                }
            }
            if ($totalOUs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking LAPS permissions" -Completed }

            # ===== Output findings =====
            if (@($filteredFindings).Count -gt 0) {
                # Group findings by principal and deduplicate OUs - a principal may have multiple LAPS property rights on the same OU
                # Track Exchange, privileged, and non-privileged separately
                $allReaderSIDs = @{}
                $exchangeReaderSIDs = @{}
                $privilegedReaderSIDs = @{}

                foreach ($finding in $filteredFindings) {
                    foreach ($reader in $finding.MatchedReaders) {
                        $sid = $reader.SID
                        $isExchange = $reader.IsExchangeService -eq $true
                        $isPriv = $reader.IsPrivilegedAccount -eq $true

                        # Choose correct hashtable based on status
                        $targetHash = if ($isExchange) { $exchangeReaderSIDs }
                            elseif ($isPriv) { $privilegedReaderSIDs }
                            else { $allReaderSIDs }

                        if (-not $targetHash.ContainsKey($sid)) {
                            $targetHash[$sid] = @{
                                Principal = $reader.Principal
                                SID = $sid
                                OUs = @()
                                IsExchangeService = $isExchange
                                IsPrivilegedAccount = $isPriv
                            }
                        }
                        # Only add OU if not already in the list (deduplicate)
                        $ouEntry = "$($finding.OU) ($($finding.ComputerCount) computers)"
                        if ($targetHash[$sid].OUs -notcontains $ouEntry) {
                            $targetHash[$sid].OUs += $ouEntry
                        }
                    }
                }

                # Batch resolve all unique SIDs to AD objects (avoids N+1 LDAP queries in display loops)
                $sidObjectMap = @{}
                $allUniqueSIDs = @(@($allReaderSIDs.Keys) + @($privilegedReaderSIDs.Keys) + @($exchangeReaderSIDs.Keys) | Sort-Object -Unique)
                $resolvableSIDs = @($allUniqueSIDs | Where-Object { $_ -notmatch '^S-1-5-\d+$' })

                if ($resolvableSIDs.Count -gt 0) {
                    $totalSIDs = $resolvableSIDs.Count
                    $currentSIDIndex = 0
                    foreach ($resolveSID in $resolvableSIDs) {
                        $currentSIDIndex++
                        if ($totalSIDs -gt $Script:ProgressThreshold) {
                            Show-Progress -Activity "Resolving account details" -Current $currentSIDIndex -Total $totalSIDs
                        }
                        $sidHex = ConvertTo-LDAPSIDHex -SID $resolveSID
                        if ($sidHex) {
                            $obj = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @connectionParams)[0]
                            if ($obj) { $sidObjectMap[$resolveSID] = $obj }
                        }
                    }
                    if ($totalSIDs -gt $Script:ProgressThreshold) {
                        Show-Progress -Activity "Resolving account details" -Completed
                    }
                }

                # Display non-privileged, non-Exchange findings as Finding (red)
                if ($allReaderSIDs.Keys.Count -gt 0) {
                    Show-Line "Found $($allReaderSIDs.Keys.Count) non-privileged account(s) with LAPS read access" -Class Finding

                    foreach ($sid in $allReaderSIDs.Keys) {
                        $readerInfo = $allReaderSIDs[$sid]
                        $isWellKnownSID = $sid -match '^S-1-5-\d+$'
                        $adObject = if ($sidObjectMap.ContainsKey($sid)) { $sidObjectMap[$sid] } else { $null }

                        if ($adObject) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue "LAPS Password Read" -Force
                            $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $readerInfo.OUs -Force
                            $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSPermission' -Force
                            Show-Object $adObject
                        } else {
                            $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $readerInfo.Principal }
                            $fallbackObject = [PSCustomObject]@{
                                sAMAccountName = $resolvedName
                                objectSid = $sid
                                dangerousRights = "LAPS Password Read"
                                affectedOUs = $readerInfo.OUs
                            }
                            $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSPermission' -Force
                            Show-Object $fallbackObject
                        }
                    }
                }

                # Display privileged findings as Hint (yellow) when -IncludePrivileged
                if ($IncludePrivileged -and $privilegedReaderSIDs.Keys.Count -gt 0) {
                    Show-Line "Found $($privilegedReaderSIDs.Keys.Count) privileged account(s) with LAPS read access (expected)" -Class Hint

                    foreach ($sid in $privilegedReaderSIDs.Keys) {
                        $readerInfo = $privilegedReaderSIDs[$sid]
                        $isWellKnownSID = $sid -match '^S-1-5-\d+$'
                        $adObject = if ($sidObjectMap.ContainsKey($sid)) { $sidObjectMap[$sid] } else { $null }

                        if ($adObject) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue "LAPS Password Read" -Force
                            $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $readerInfo.OUs -Force
                            $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                            $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSPermission' -Force
                            Show-Object $adObject
                        } else {
                            $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $readerInfo.Principal }
                            $fallbackObject = [PSCustomObject]@{
                                sAMAccountName = $resolvedName
                                objectSid = $sid
                                dangerousRights = "LAPS Password Read"
                                affectedOUs = $readerInfo.OUs
                                dangerousRightsSeverity = 'Hint'
                            }
                            $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSPermission' -Force
                            Show-Object $fallbackObject
                        }
                    }
                }

                # Display Exchange service group findings as Hint (yellow) - by-design permissions
                # Only shown with -IncludePrivileged (Exchange groups are privileged by design)
                if ($IncludePrivileged -and $exchangeReaderSIDs.Keys.Count -gt 0) {
                    Show-Line "Found $($exchangeReaderSIDs.Keys.Count) Exchange service group(s) with LAPS read access (by-design, cannot be removed)" -Class Hint

                    foreach ($sid in $exchangeReaderSIDs.Keys) {
                        $readerInfo = $exchangeReaderSIDs[$sid]
                        $isWellKnownSID = $sid -match '^S-1-5-\d+$'
                        $adObject = if ($sidObjectMap.ContainsKey($sid)) { $sidObjectMap[$sid] } else { $null }

                        if ($adObject) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue "LAPS Password Read" -Force
                            $adObject | Add-Member -NotePropertyName 'affectedOUs' -NotePropertyValue $readerInfo.OUs -Force
                            $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue 'Hint' -Force
                            $adObject | Add-Member -NotePropertyName '_isExchangeGroup' -NotePropertyValue $true -Force
                            $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSPermission' -Force
                            Show-Object $adObject
                        } else {
                            $resolvedName = if ($isWellKnownSID) { ConvertFrom-SID -SID $sid } else { $readerInfo.Principal }
                            $fallbackObject = [PSCustomObject]@{
                                sAMAccountName = $resolvedName
                                objectSid = $sid
                                dangerousRights = "LAPS Password Read"
                                affectedOUs = $readerInfo.OUs
                                dangerousRightsSeverity = 'Hint'
                            }
                            $fallbackObject | Add-Member -NotePropertyName '_isExchangeGroup' -NotePropertyValue $true -Force
                            $fallbackObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSPermission' -Force
                            Show-Object $fallbackObject
                        }
                    }
                }

                # If no non-Exchange findings were displayed (and Exchange is hidden without -IncludePrivileged)
                if ($allReaderSIDs.Keys.Count -eq 0 -and $privilegedReaderSIDs.Keys.Count -eq 0 -and (-not $IncludePrivileged -or $exchangeReaderSIDs.Keys.Count -eq 0)) {
                    Show-Line "No non-privileged accounts with LAPS read access found in $(@($computersByOU.Keys).Count) analyzed OU(s)" -Class Secure
                }

            } else {
                Show-Line "No non-privileged accounts with LAPS read access found in $(@($computersByOU.Keys).Count) analyzed OU(s)" -Class Secure
            }

        } catch {
            Write-Log "[Get-LAPSPermissions] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-LAPSPermissions] Check completed"
    }
}



# ----- Get-LAPSConfiguration.ps1 -----

<#
.SYNOPSIS
    Collects the unique non-empty values of one LAPS metadata field across all GPOs of one hive.

.DESCRIPTION
    Input is one of the Legacy/Native hashtables returned by Get-LAPSGPOConfig (GPO Name ->
    metadata hashtable). A field is included only where it was explicitly present on that GPO -
    a legitimate value of 0 (e.g. BackupDirectory=0) must be kept, never dropped by truthiness.

.PARAMETER GPOMetadataTable
    The Legacy or Native hashtable from Get-LAPSGPOConfig's result (GPO Name -> metadata hashtable).

.PARAMETER FieldName
    Metadata field to collect, e.g. 'PasswordComplexity'.

.OUTPUTS
    Array of unique values (empty array if the field isn't set on any GPO).

.NOTES
    Internal helper function
#>
function Get-LAPSGPOFieldValues {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [AllowNull()]
        [hashtable]$GPOMetadataTable,

        [Parameter(Mandatory=$true)]
        [string]$FieldName
    )

    if (-not $GPOMetadataTable) { return @() }

    $values = foreach ($metadata in $GPOMetadataTable.Values) {
        if ($metadata.ContainsKey($FieldName)) { $metadata[$FieldName] }
    }

    return @($values | Select-Object -Unique)
}

# PasswordComplexity value -> human readable meaning
# Reference: https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings
$Script:LAPSPasswordComplexityMap = @{
    1 = 'Large letters'
    2 = 'Large + small letters'
    3 = 'Large + small letters + numbers'
    4 = 'Large + small letters + numbers + special'
    5 = 'Large + small letters + numbers + special (improved readability)'
    6 = 'Passphrase (long words)'
    7 = 'Passphrase (short words)'
    8 = 'Passphrase (short words with unique prefixes)'
}

<#
.SYNOPSIS
    Builds a display object for the LAPS settings of a single GPO.

.DESCRIPTION
    Converts the raw metadata hashtable produced by Get-LAPSGPOConfig into a rendered object
    for Show-Object. Raw registry values are decoded into human-readable strings so the
    finding triggers in adPEAS-FindingDefinitions.ps1 can colour them and attach tooltips.

    Only settings actually present in this GPO are added as attributes - an absent setting
    means the Windows LAPS default applies, which is not the same as it being set to 0/empty.

.PARAMETER GPOName
    Display name of the GPO.

.PARAMETER Metadata
    The per-GPO metadata hashtable from Get-LAPSGPOConfig (field name -> value, plus GPOGUID).

.PARAMETER Generation
    'Windows LAPS' or 'LAPS Legacy'.

.PARAMETER GPOLinkage
    Hashtable from Get-GPOLinkage (GPO GUID -> linked OUs), used to show where the GPO applies.

.OUTPUTS
    PSCustomObject tagged as ObjectType 'LAPSGPOConfig'.

.NOTES
    Internal helper function
#>
function New-LAPSGPOConfigObject {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$GPOName,

        [Parameter(Mandatory=$true)]
        [hashtable]$Metadata,

        [Parameter(Mandatory=$true)]
        [ValidateSet('Windows LAPS', 'LAPS Legacy')]
        [string]$Generation,

        [Parameter(Mandatory=$false)]
        [AllowNull()]
        [hashtable]$GPOLinkage
    )

    $isNative = ($Generation -eq 'Windows LAPS')
    $accountField = if ($isNative) { 'AdministratorAccountName' } else { 'AdminAccountName' }

    $obj = [PSCustomObject][ordered]@{
        GPOName     = $GPOName
        LAPSVersion = $Generation
    }

    # Managed account - absent means LAPS manages the built-in local Administrator (RID 500)
    $managedAccount = if ($Metadata.ContainsKey($accountField)) {
        [string]$Metadata[$accountField]
    } else {
        'Administrator (built-in, RID 500)'
    }
    $obj | Add-Member -NotePropertyName 'ManagedAccount' -NotePropertyValue $managedAccount -Force

    if ($isNative) {
        # BackupDirectory: 0=Disabled, 1=Microsoft Entra ID only, 2=Active Directory
        if ($Metadata.ContainsKey('BackupDirectory')) {
            $backupText = switch ([int]$Metadata['BackupDirectory']) {
                0       { 'Disabled - password is not escrowed anywhere' }
                1       { 'Microsoft Entra ID only - password is not escrowed to this Active Directory' }
                2       { 'Active Directory' }
                default { "Unknown ($($Metadata['BackupDirectory']))" }
            }
            $obj | Add-Member -NotePropertyName 'BackupDirectory' -NotePropertyValue $backupText -Force
        }

        # ADPasswordEncryptionEnabled=0 -> password lands in plaintext msLAPS-Password
        if ($Metadata.ContainsKey('ADPasswordEncryptionEnabled')) {
            $encText = if ([int]$Metadata['ADPasswordEncryptionEnabled'] -eq 0) {
                'Disabled - password is stored UNENCRYPTED in msLAPS-Password'
            } else {
                'Enabled'
            }
            $obj | Add-Member -NotePropertyName 'PasswordEncryption' -NotePropertyValue $encText -Force
        }

        if ($Metadata.ContainsKey('ADPasswordEncryptionPrincipal')) {
            $obj | Add-Member -NotePropertyName 'EncryptionPrincipal' -NotePropertyValue ([string]$Metadata['ADPasswordEncryptionPrincipal']) -Force
        }
    }

    if ($Metadata.ContainsKey('PasswordComplexity')) {
        $complexityValue = [int]$Metadata['PasswordComplexity']
        $complexityText = if ($Script:LAPSPasswordComplexityMap.ContainsKey($complexityValue)) {
            "$complexityValue ($($Script:LAPSPasswordComplexityMap[$complexityValue]))"
        } else {
            [string]$complexityValue
        }
        $obj | Add-Member -NotePropertyName 'PasswordComplexity' -NotePropertyValue $complexityText -Force
    }

    foreach ($numericField in @('PasswordLength', 'PassphraseLength', 'PasswordAgeDays')) {
        if ($Metadata.ContainsKey($numericField)) {
            $obj | Add-Member -NotePropertyName $numericField -NotePropertyValue $Metadata[$numericField] -Force
        }
    }

    if ($isNative -and $Metadata.ContainsKey('PasswordExpirationProtectionEnabled')) {
        $expText = if ([int]$Metadata['PasswordExpirationProtectionEnabled'] -eq 0) {
            'Disabled - password max-age is not enforced'
        } else {
            'Enabled'
        }
        $obj | Add-Member -NotePropertyName 'ExpirationProtection' -NotePropertyValue $expText -Force
    }

    # GPO links - without these it is not visible where the settings actually apply.
    # An unlinked GPO is reported explicitly rather than by an absent row: LAPS settings in a
    # GPO that is linked nowhere apply to nothing, which is easy to miss otherwise. A failed
    # linkage lookup must not be reported as "not linked".
    $gpoGuid = if ($Metadata.ContainsKey('GPOGUID')) { $Metadata['GPOGUID'] } else { $null }
    $linkedOUs = @()
    if ($gpoGuid -and $GPOLinkage -and $GPOLinkage.ContainsKey($gpoGuid)) {
        $linkedOUs = @($GPOLinkage[$gpoGuid])
    }

    if ($linkedOUs.Count -gt 0) {
        $obj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUs -Force
    } elseif ($null -eq $GPOLinkage) {
        $obj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue 'Unknown - GPO linkage could not be resolved' -Force
    } else {
        $obj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue 'Not linked - these settings apply nowhere' -Force
    }
    $obj | Add-Member -NotePropertyName 'LinkedOUCount' -NotePropertyValue $linkedOUs.Count -Force

    if ($gpoGuid) {
        $obj | Add-Member -NotePropertyName 'GPOGUID' -NotePropertyValue $gpoGuid -Force
    }

    $obj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSGPOConfig' -Force

    return $obj
}

<#
.SYNOPSIS
    Builds the display objects for all GPOs that deploy LAPS settings.

.DESCRIPTION
    Resolves GPO linkage once and converts the Legacy and Native metadata tables from
    Get-LAPSGPOConfig into rendered objects. A GPO configuring both LAPS generations yields
    one object per generation, because the two are administered independently and Windows
    LAPS ignores the legacy policy root when its own root has any setting.

.PARAMETER LAPSGPOSettings
    The hashtable returned by Get-LAPSGPOConfig (keys 'Legacy' and 'Native').

.OUTPUTS
    Array of PSCustomObject tagged as ObjectType 'LAPSGPOConfig', Windows LAPS first.

.NOTES
    Internal helper function
#>
function Get-LAPSGPOConfigObjects {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [hashtable]$LAPSGPOSettings
    )

    $gpoLinkage = $null
    try {
        $gpoLinkage = Get-GPOLinkage
    } catch {
        Write-Log "[Get-LAPSGPOConfigObjects] Failed to resolve GPO linkage: $_"
    }

    $objects = @()

    if ($LAPSGPOSettings.Native) {
        foreach ($gpoName in ($LAPSGPOSettings.Native.Keys | Sort-Object)) {
            $objects += New-LAPSGPOConfigObject -GPOName $gpoName -Metadata $LAPSGPOSettings.Native[$gpoName] `
                -Generation 'Windows LAPS' -GPOLinkage $gpoLinkage
        }
    }

    if ($LAPSGPOSettings.Legacy) {
        foreach ($gpoName in ($LAPSGPOSettings.Legacy.Keys | Sort-Object)) {
            $objects += New-LAPSGPOConfigObject -GPOName $gpoName -Metadata $LAPSGPOSettings.Legacy[$gpoName] `
                -Generation 'LAPS Legacy' -GPOLinkage $gpoLinkage
        }
    }

    return $objects
}

function Get-LAPSConfiguration {
    <#
    .SYNOPSIS
    Analyzes Local Administrator Password Solution (LAPS) deployment and coverage.

    .DESCRIPTION
    Analyzes LAPS deployment status focusing on:
    - Schema detection (Legacy LAPS vs. Windows LAPS Native)
    - GPO configuration analysis (managed account name, password policy, backup/encryption settings)
    - Deployment coverage (% of computers with LAPS)
    - Computers without LAPS protection grouped by OU

    LAPS Versions Supported:
    - Legacy LAPS: Original Microsoft LAPS (ms-Mcs-* attributes)
    - Windows LAPS Native: Built-in since Server 2022/Win11 (msLAPS-* attributes)

    Related Checks:
    - Get-LAPSCredentialAccess (Creds): Can YOUR account read LAPS passwords?
    - Get-LAPSPermissions (Rights): WHO has LAPS read rights per OU?

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-LAPSConfiguration

    .EXAMPLE
    Get-LAPSConfiguration -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Computer
    Author: Alexander Sturz (@_61106960_)
    Reference:
    - LAPS Legacy: https://www.microsoft.com/en-us/download/details.aspx?id=46899
    - Windows LAPS: https://learn.microsoft.com/en-us/windows-server/identity/laps/
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-LAPSConfiguration] Starting check"

        # Properties needed for internal calculations only
        $ComputerProperties = @(
            'distinguishedName',
            'sAMAccountName',
            'lastLogonTimestamp',
            'ms-Mcs-AdmPwdExpirationTime',
            'msLAPS-PasswordExpirationTime'
        )
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            # ===== Step 1: Schema Detection =====
            Show-SubHeader "Checking for LAPS schema attributes..." -ObjectType "LAPSConfiguration"

            $lapsLegacySchemaPresent = $false
            $windowsLAPSSchemaPresent = $false

            $ldapServer = $Script:LDAPContext.Server
            $schemaDN = $Script:LDAPContext.SchemaNamingContext

            Write-Log "[Get-LAPSConfiguration] Server: $ldapServer, Schema DN: $schemaDN"

            # Method 1: Schema query using Invoke-LDAPSearch with Schema Partition
            if ($schemaDN) {
                try {
                    # Test Legacy LAPS schema attribute
                    $legacySchemaFilter = "(&(objectClass=attributeSchema)(|(lDAPDisplayName=ms-Mcs-AdmPwdExpirationTime)(cn=ms-Mcs-AdmPwdExpirationTime)))"
                    $legacyResult = Invoke-LDAPSearch -Filter $legacySchemaFilter -SearchBase $schemaDN -Properties 'cn' -SizeLimit 1
                    if ($legacyResult) {
                        $lapsLegacySchemaPresent = $true
                        Write-Log "[Get-LAPSConfiguration] LAPS Legacy schema attribute found"
                    }

                    # Test Windows LAPS Native schema attribute
                    $nativeSchemaFilter = "(&(objectClass=attributeSchema)(|(lDAPDisplayName=msLAPS-PasswordExpirationTime)(cn=msLAPS-PasswordExpirationTime)))"
                    $nativeResult = Invoke-LDAPSearch -Filter $nativeSchemaFilter -SearchBase $schemaDN -Properties 'cn' -SizeLimit 1
                    if ($nativeResult) {
                        $windowsLAPSSchemaPresent = $true
                        Write-Log "[Get-LAPSConfiguration] Windows LAPS Native schema attribute found"
                    }
                } catch {
                    Write-Log "[Get-LAPSConfiguration] Schema query error: $($_.Exception.Message)"
                }
            }

            # Method 2: Fallback - check if any computer has LAPS attributes (minimal query)
            if (-not $lapsLegacySchemaPresent -and -not $windowsLAPSSchemaPresent) {
                Write-Log "[Get-LAPSConfiguration] Schema query returned no results, checking computer objects"

                # Only fetch distinguishedName - we just need to know if any object exists
                $legacyCheck = Get-DomainComputer -LDAPFilter "(ms-Mcs-AdmPwdExpirationTime=*)" -Properties 'distinguishedName' -ResultLimit 1 @PSBoundParameters
                if ($legacyCheck) {
                    $lapsLegacySchemaPresent = $true
                    Write-Log "[Get-LAPSConfiguration] LAPS Legacy detected via computer attribute"
                }

                $nativeCheck = Get-DomainComputer -LDAPFilter "(msLAPS-PasswordExpirationTime=*)" -Properties 'distinguishedName' -ResultLimit 1 @PSBoundParameters
                if ($nativeCheck) {
                    $windowsLAPSSchemaPresent = $true
                    Write-Log "[Get-LAPSConfiguration] Windows LAPS Native detected via computer attribute"
                }
            }

            # Store schema info for other LAPS modules
            $Script:LAPSSchemaInfo = @{
                LegacyPresent = $lapsLegacySchemaPresent
                NativePresent = $windowsLAPSSchemaPresent
            }

            Write-Log "[Get-LAPSConfiguration] Detection result: Legacy=$lapsLegacySchemaPresent, Native=$windowsLAPSSchemaPresent"

            # ===== GPO Configuration (LAPS managed account name) =====
            # Fetched here (before the schema branch) because a GPO can configure the LAPS
            # AdminAccountName/AdministratorAccountName setting even when the schema was never
            # extended - that is itself a critical misconfiguration (LAPS "deployed" via GPO but
            # completely non-functional) and needs the same GPO/SYSVOL scan either way.
            $lapsGPOSettings = $null
            try {
                $lapsGPOSettings = Get-LAPSGPOConfig
            } catch {
                Write-Log "[Get-LAPSConfiguration] Failed to query LAPS GPO settings: $_"
            }
            $lapsGPOHasLegacy = $lapsGPOSettings -is [hashtable] -and $lapsGPOSettings.Legacy -and $lapsGPOSettings.Legacy.Count -gt 0
            $lapsGPOHasNative = $lapsGPOSettings -is [hashtable] -and $lapsGPOSettings.Native -and $lapsGPOSettings.Native.Count -gt 0

            # ===== No LAPS Schema Found =====
            if (-not $lapsLegacySchemaPresent -and -not $windowsLAPSSchemaPresent) {
                if ($lapsGPOHasLegacy -or $lapsGPOHasNative) {
                    Show-Line "LAPS GPO settings found, but the LAPS schema is NOT present in AD - LAPS is configured but completely non-functional!" -Class "Finding"

                    foreach ($gpoConfigObject in @(Get-LAPSGPOConfigObjects -LAPSGPOSettings $lapsGPOSettings)) {
                        Show-Object $gpoConfigObject
                    }
                } else {
                    Show-Line "No LAPS schema found - LAPS is not deployed" -Class "Finding"
                }

                # Get active computers grouped by OU (uses $Script:DefaultInactiveDays)
                $allComputers = @(Get-DomainComputer -Enabled -Properties $ComputerProperties @PSBoundParameters | Test-AccountActivity -IsActive)

                # Group by OU - store computer names
                $computersByOU = @{}
                foreach ($computer in $allComputers) {
                    $dn = $computer.distinguishedName
                    if ($dn -match '^CN=[^,]+,(.+)$') {
                        $ouDN = $Matches[1]
                        if (-not $computersByOU.ContainsKey($ouDN)) {
                            $computersByOU[$ouDN] = @()
                        }
                        $computerName = $computer.sAMAccountName -replace '\$$', ''
                        $computersByOU[$ouDN] += $computerName
                    }
                }

                Show-Line "$($allComputers.Count) computers (100%) without LAPS protection" -Class "Finding"

                # Output each OU as structured object for proper tooltip support
                foreach ($ouEntry in ($computersByOU.GetEnumerator() | Sort-Object { $_.Value.Count } -Descending)) {
                    $lapsFinding = [PSCustomObject]@{
                        ouName = $ouEntry.Key
                        computerCount = $ouEntry.Value.Count
                        lapsUnprotectedComputers = ($ouEntry.Value -join ", ")
                    }
                    $lapsFinding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSConfiguration' -Force
                    Show-Object $lapsFinding
                }
                return
            }

            # Report schema versions - schema presence is a positive indicator (Note = green)
            if ($lapsLegacySchemaPresent -and $windowsLAPSSchemaPresent) {
                Show-Line "Both LAPS Legacy and Windows LAPS Native schemas present" -Class "Note"
            } elseif ($lapsLegacySchemaPresent) {
                Show-Line "LAPS Legacy schema present" -Class "Note"
            } elseif ($windowsLAPSSchemaPresent) {
                Show-Line "Windows LAPS Native schema present" -Class "Note"
            }

            # ===== Step 2: GPO Configuration (LAPS managed account name + policy metadata) =====
            # $lapsGPOSettings was already fetched above (before the schema branch). Shown before
            # the coverage numbers because it explains WHY coverage looks the way it does (account
            # name, encryption, backup target) rather than as an afterthought once the reader
            # already has a coverage percentage in mind.
            if ($lapsGPOSettings -is [hashtable]) {
                if ($lapsGPOHasLegacy -or $lapsGPOHasNative) {
                    Show-SubHeader "Analyzing LAPS configuration deployed via GPO..." -ObjectType "LAPSGPOConfig"

                    $gpoConfigObjects = @(Get-LAPSGPOConfigObjects -LAPSGPOSettings $lapsGPOSettings)

                    Show-Line "Found $($gpoConfigObjects.Count) GPO(s) deploying LAPS settings" -Class "Hint"

                    foreach ($gpoConfigObject in $gpoConfigObjects) {
                        Show-Object $gpoConfigObject
                    }
                } else {
                    if ((Test-SysvolAccessible) -eq $false) {
                        Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                    } else {
                        Show-Line "No LAPS-related GPO settings found in SYSVOL - LAPS may be managed via Intune/CSP or local policy instead of GPO" -Class "Hint"
                    }
                }
            }

            # ===== Step 3: Enumerate Computers and Calculate Coverage =====
            Show-SubHeader "Analyzing LAPS deployment coverage..." -ObjectType "LAPSConfiguration"

            # Query 1: All enabled computers (for statistics)
            $allEnabledComputers = @(Get-DomainComputer -Enabled -Properties $ComputerProperties @PSBoundParameters)

            # Query 2: Active computers (enabled + recent logon) - uses $Script:DefaultInactiveDays
            $activeComputers = @($allEnabledComputers | Test-AccountActivity -IsActive)

            # Query 3: Computers WITH LAPS (LDAP-side filter) - much faster than client-side attribute check
            $computersWithLAPSRaw = @(Get-DomainComputer -Enabled -LAPS -Properties $ComputerProperties @PSBoundParameters)
            $computersWithLAPS = @($computersWithLAPSRaw | Test-AccountActivity -IsActive)

            # Categorize LAPS computers by type
            $computersWithLegacyLAPS = @()
            $computersWithWindowsLAPS = @()
            $computersWithBothLAPS = @()

            foreach ($computer in $computersWithLAPS) {
                $hasLegacyLAPS = $null -ne $computer.'ms-Mcs-AdmPwdExpirationTime'
                $hasWindowsLAPS = $null -ne $computer.'msLAPS-PasswordExpirationTime'

                if ($hasLegacyLAPS -and $hasWindowsLAPS) {
                    $computersWithBothLAPS += $computer
                } elseif ($hasLegacyLAPS) {
                    $computersWithLegacyLAPS += $computer
                } else {
                    $computersWithWindowsLAPS += $computer
                }
            }

            # Computers without LAPS = active computers minus those with LAPS
            $lapsComputerDNs = @{}
            foreach ($c in $computersWithLAPS) {
                $lapsComputerDNs[$c.distinguishedName] = $true
            }
            $computersWithoutLAPS = @($activeComputers | Where-Object { -not $lapsComputerDNs.ContainsKey($_.distinguishedName) })

            # Calculate statistics
            $activeCount = $activeComputers.Count
            $inactiveCount = $allEnabledComputers.Count - $activeCount

            $withLegacyLAPS = $computersWithLegacyLAPS.Count
            $withWindowsLAPS = $computersWithWindowsLAPS.Count
            $withBothLAPS = $computersWithBothLAPS.Count
            $withoutLAPS = $computersWithoutLAPS.Count

            $withAnyLAPS = $withLegacyLAPS + $withWindowsLAPS + $withBothLAPS
            $lapsCoverage = if ($activeCount -gt 0) { [math]::Round(($withAnyLAPS / $activeCount) * 100, 1) } else { 0 }
            $withoutLAPSPercent = if ($activeCount -gt 0) { [math]::Round(($withoutLAPS / $activeCount) * 100, 1) } else { 0 }

            # Output statistics - compact summary lines
            $inactiveInfo = if ($inactiveCount -gt 0) { " ($inactiveCount inactive excluded)" } else { "" }
            Show-Line "Found $activeCount active computers$inactiveInfo" -Class "Hint"

            # Build LAPS breakdown
            if ($withAnyLAPS -gt 0) {
                $lapsBreakdown = @()
                if ($withLegacyLAPS -gt 0) { $lapsBreakdown += "$withLegacyLAPS Legacy" }
                if ($withWindowsLAPS -gt 0) { $lapsBreakdown += "$withWindowsLAPS Native" }
                if ($withBothLAPS -gt 0) { $lapsBreakdown += "$withBothLAPS both" }
                $breakdownText = if ($lapsBreakdown.Count -gt 0) { " (" + ($lapsBreakdown -join ", ") + ")" } else { "" }
                Show-Line "$withAnyLAPS computers ($lapsCoverage%) with LAPS protection$breakdownText" -Class "Note"
            }

            # Highlight computers without LAPS
            if ($withoutLAPS -gt 0) {
                Show-Line "$withoutLAPS computers ($withoutLAPSPercent%) without LAPS protection" -Class "Finding"

                # Group by OU - store computer names instead of count
                $computersWithoutLAPSByOU = @{}
                $totalComputers = @($computersWithoutLAPS).Count
                $currentIndex = 0
                foreach ($computer in $computersWithoutLAPS) {
                    $currentIndex++
                    if ($totalComputers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking LAPS configuration" -Current $currentIndex -Total $totalComputers -ObjectName $computer.name }
                    $dn = $computer.distinguishedName
                    if ($dn -match '^CN=[^,]+,(.+)$') {
                        $ouDN = $Matches[1]
                        if (-not $computersWithoutLAPSByOU.ContainsKey($ouDN)) {
                            $computersWithoutLAPSByOU[$ouDN] = @()
                        }
                        # Use sAMAccountName for computer name
                        $computerName = $computer.sAMAccountName -replace '\$$', ''
                        $computersWithoutLAPSByOU[$ouDN] += $computerName
                    }
                }
                if ($totalComputers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking LAPS configuration" -Completed }

                # Output each OU as structured object for proper tooltip support
                foreach ($ouEntry in ($computersWithoutLAPSByOU.GetEnumerator() | Sort-Object { $_.Value.Count } -Descending)) {
                    $lapsFinding = [PSCustomObject]@{
                        ouName = $ouEntry.Key
                        computerCount = $ouEntry.Value.Count
                        lapsUnprotectedComputers = ($ouEntry.Value -join ", ")
                    }
                    $lapsFinding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSConfiguration' -Force
                    Show-Object $lapsFinding
                }
            } else {
                Show-Line "All computers (100%) have LAPS protection" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-LAPSConfiguration] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-LAPSConfiguration] Check completed"
    }
}




# ----- Get-OutdatedComputers.ps1 -----

function Get-OutdatedComputers {
    <#
    .SYNOPSIS
    Detects computers running outdated/unsupported Windows operating systems.

    .DESCRIPTION
    Identifies active computer accounts running unsupported Windows versions that pose security risks due to lack of security updates.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER InactiveDays
    Number of days since last logon to consider a computer as inactive (default: 90)

    .EXAMPLE
    Get-OutdatedComputers

    .EXAMPLE
    Get-OutdatedComputers -InactiveDays 180

    .NOTES
    Category: Computer
    Author: Alexander Sturz (@_61106960_)
    Note: lastLogonTimestamp has 9-14 day replication latency.
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [int]$InactiveDays = 90,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC
    )

    begin {
        Write-Log "[Get-OutdatedComputers] Starting check"

        # Windows lifecycle data is now centralized in adPEAS-SoftwareLifecycle.ps1
        # Uses: $Script:WindowsLifecycle, Get-NormalizedOSName, Test-IsOutdatedOS

        # Properties needed for filtering
        $FilterProperties = @('distinguishedName', 'operatingSystem', 'operatingSystemVersion', 'userAccountControl', 'lastLogonTimestamp')
    }

    process {
        try {
            # Build connection parameters (exclude InactiveDays which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for computers with outdated operating systems..." -ObjectType "OutdatedComputer"

            # OPSEC mode: Skip heavy-load enumeration
            if ($OPSEC) {
                Show-Line "OPSEC mode: Skipping outdated computer check (would check all enabled computers)" -Class "Hint"
                return
            }

            # Step 1: Get computers with minimal attributes for filtering
            $computers = @(Get-DomainComputer -Enabled -Properties $FilterProperties @connectionParams)

            $inactiveFilteredCount = 0
            $outdatedComputerDNs = @()

            if (@($computers).Count -gt 0) {
                # Get enabled computers with activity details
                $computersWithActivity = $computers | Test-AccountActivity -IncludeDetails

                $currentIndex = 0
                $totalComputers = @($computersWithActivity).Count

                foreach ($computer in $computersWithActivity) {
                    $currentIndex++

                    # Progress indicator for large computer counts
                    if ($totalComputers -gt 50) {
                        Show-Progress -Activity "Checking outdated OS" `
                                     -Current $currentIndex `
                                     -Total $totalComputers
                    }
                    # Skip if no OS info
                    if ([string]::IsNullOrEmpty($computer.operatingSystem)) {
                        continue
                    }

                    # Check if OS is outdated using central lifecycle module
                    $eolCheck = Test-IsOutdatedOS -OSName $computer.operatingSystem -OSVersion $computer.operatingSystemVersion

                    if ($eolCheck.IsOutdated) {
                        # Check if computer is active
                        $isActive = $computer.ActivityDetails.IsActive

                        if ($isActive) {
                            # Store DN for later full fetch
                            $outdatedComputerDNs += $computer.distinguishedName
                        } else {
                            # Count inactive outdated computers (stale accounts, not displayed)
                            $inactiveFilteredCount++
                        }
                    }
                }

                # Clear progress bar
                if ($totalComputers -gt 50) {
                    Show-Progress -Activity "Checking outdated OS" -Completed
                }
            }

            # Step 2: Only fetch full objects for outdated computers (for Show-Object)
            if (@($outdatedComputerDNs).Count -gt 0) {
                $inactiveInfo = if ($inactiveFilteredCount -gt 0) { " ($inactiveFilteredCount inactive accounts filtered)" } else { "" }
                Show-Line "Found $(@($outdatedComputerDNs).Count) computer(s) with outdated operating systems:$inactiveInfo" -Class "Finding"

                foreach ($dn in $outdatedComputerDNs) {
                    $fullComputer = @(Get-DomainComputer -Identity $dn @connectionParams)[0]
                    if ($fullComputer) {
                        # Get EOL details using central lifecycle module
                        $eolCheck = Test-IsOutdatedOS -OSName $fullComputer.operatingSystem -OSVersion $fullComputer.operatingSystemVersion
                        if ($eolCheck.IsOutdated) {
                            # Format EOL date as string for display
                            $eolDateStr = if ($eolCheck.EOLDate) { $eolCheck.EOLDate.ToString("yyyy-MM-dd") } else { "Unknown" }
                            $fullComputer | Add-Member -NotePropertyName 'eolDate' -NotePropertyValue $eolDateStr -Force
                            $fullComputer | Add-Member -NotePropertyName 'daysSinceEoL' -NotePropertyValue $eolCheck.DaysSinceEOL -Force
                        }
                        $fullComputer | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'OutdatedComputer' -Force
                        Show-Object $fullComputer
                    }
                }
            } elseif ($inactiveFilteredCount -gt 0) {
                Show-Line "No active computers with outdated OS ($inactiveFilteredCount inactive accounts filtered)" -Class "Secure"
            } else {
                Show-Line "No computers with outdated operating systems found" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-OutdatedComputers] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-OutdatedComputers] Check completed"
    }
}

# Note: Get-NormalizedOSName and Test-IsOutdatedOS are now in adPEAS-SoftwareLifecycle.ps1



# ----- Get-InfrastructureServers.ps1 -----

function Get-InfrastructureServers {
    <#
    .SYNOPSIS
    Identifies infrastructure servers via SPN analysis.

    .DESCRIPTION
    Enumerates critical infrastructure servers by analyzing Service Principal Names (SPNs) registered on computer accounts.

    Detected Server Types:
    - Domain Controllers (ldap/, gc/, DNS/)
    - Exchange Servers (exchangeAB/, exchangeRFR/, exchangeMDB/)
    - MSSQL Servers (MSSQLSvc/)
    - SCCM/ConfigMgr (SMS*, CCM*)
    - SCOM (MSOMHSvc/, MSOMSdkSvc/)
    - Entra ID Connect (azureadconnect, ADSync)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-InfrastructureServers

    .EXAMPLE
    Get-InfrastructureServers -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Computer
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-InfrastructureServers] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            # ===== Domain Controllers =====
            Show-SubHeader "Searching for Domain Controllers..." -ObjectType "DomainController"

            $domainControllers = @(Get-DomainComputer -LDAPFilter "(&(userAccountControl:1.2.840.113556.1.4.803:=8192))" @PSBoundParameters | Test-AccountActivity -IsEnabled)

            if ($domainControllers.Count -gt 0) {
                Show-Line "Found $($domainControllers.Count) Domain Controller(s):" -Class "Hint"
                foreach ($dc in $domainControllers) {
                    $dc | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'DomainController' -Force
                    $dc | Show-Object
                }
            } else {
                Show-Line "No Domain Controllers found (unexpected)" -Class "Note"
            }

            # ===== Exchange Servers =====
            Show-SubHeader "Searching for Exchange Servers..." -ObjectType "ExchangeServer"

            # Detect Exchange servers via "Exchange Servers" group membership
            $exchangeServers = @()
            $exchangeServersGroup = @(Get-DomainGroup -Identity "Exchange Servers" @PSBoundParameters)[0]
            if ($exchangeServersGroup -and $exchangeServersGroup.member) {
                foreach ($memberDN in @($exchangeServersGroup.member)) {
                    $memberObj = @(Get-DomainObject -Identity $memberDN @PSBoundParameters)[0]
                    if ($memberObj -and $memberObj.objectClass -icontains "computer") {
                        $exchangeServers += $memberObj
                    }
                }
            }
            # Filter for enabled servers only
            $exchangeServers = @($exchangeServers | Test-AccountActivity -IsEnabled)

            if ($exchangeServers.Count -gt 0) {
                Show-Line "Found $($exchangeServers.Count) Exchange Server(s):" -Class "Hint"
                foreach ($exch in $exchangeServers) {
                    $exch | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeServerBasic' -Force
                    $exch | Show-Object
                }
            } else {
                Show-Line "No Exchange Servers found" -Class "Note"
            }

            # ===== MSSQL Servers =====
            Show-SubHeader "Searching for MSSQL Servers..." -ObjectType "MSSQLServer"

            $mssqlServers = @(Get-DomainComputer -LDAPFilter "(servicePrincipalName=MSSQLSvc/*)" @PSBoundParameters | Test-AccountActivity -IsEnabled)

            if ($mssqlServers.Count -gt 0) {
                Show-Line "Found $($mssqlServers.Count) MSSQL Server(s):" -Class "Hint"
                foreach ($sql in $mssqlServers) {
                    $sql | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'MSSQLServer' -Force
                    $sql | Show-Object
                }
            } else {
                Show-Line "No MSSQL Servers found via SPN" -Class "Note"
            }

            # ===== SCCM/ConfigMgr Servers =====
            Show-SubHeader "Searching for SCCM/ConfigMgr Servers..." -ObjectType "SCCMServerBasic"

            # SCCM SPNs: SMS_Site_*, SMS_MP, SMS_DP, CCMSetup, etc.
            $sccmServers = @(Get-DomainComputer -LDAPFilter "(|(servicePrincipalName=SMS*)(servicePrincipalName=CCM*))" @PSBoundParameters | Test-AccountActivity -IsEnabled)

            if ($sccmServers.Count -gt 0) {
                Show-Line "Found $($sccmServers.Count) SCCM/ConfigMgr Server(s):" -Class "Hint"
                foreach ($sccm in $sccmServers) {
                    $sccm | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMServerBasic' -Force
                    $sccm | Show-Object
                }
            } else {
                Show-Line "No SCCM Servers found via SPN" -Class "Note"
            }

            # ===== SCOM Servers =====
            Show-SubHeader "Searching for SCOM Servers..." -ObjectType "SCOMServerBasic"

            # SCOM SPNs: MSOMHSvc (Health Service), MSOMSdkSvc (SDK Service)
            $scomServers = @(Get-DomainComputer -LDAPFilter "(|(servicePrincipalName=MSOMHSvc/*)(servicePrincipalName=MSOMSdkSvc/*))" @PSBoundParameters | Test-AccountActivity -IsEnabled)

            if ($scomServers.Count -gt 0) {
                Show-Line "Found $($scomServers.Count) SCOM Server(s):" -Class "Hint"
                foreach ($scom in $scomServers) {
                    $scom | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCOMServerBasic' -Force
                    $scom | Show-Object
                }
            } else {
                Show-Line "No SCOM Servers found via SPN" -Class "Note"
            }

            # ===== Entra ID Connect (Azure AD Connect) =====
            Show-SubHeader "Searching for Entra ID Connect..." -ObjectType "EntraConnect"

            $entraConnectIndicators = @()

            # Method 1: Look for MSOL_ accounts (service accounts created by Azure AD Connect)
            $msolAccounts = @(Get-DomainUser -LDAPFilter "(sAMAccountName=MSOL_*)" @PSBoundParameters)
            if ($msolAccounts.Count -gt 0) {
                $entraConnectIndicators += $msolAccounts
            }

            # Method 2: Look for ADSync service accounts
            $adsyncAccounts = @(Get-DomainUser -LDAPFilter "(|(sAMAccountName=ADSync*)(sAMAccountName=AAD_*))" @PSBoundParameters)
            if ($adsyncAccounts.Count -gt 0) {
                $entraConnectIndicators += $adsyncAccounts
            }

            # Method 3: Look for Entra Connect health agent SPN
            $entraHealthServers = @(Get-DomainComputer -LDAPFilter "(servicePrincipalName=*azureadconnect*)" @PSBoundParameters |
                Test-AccountActivity -IsEnabled)
            if ($entraHealthServers.Count -gt 0) {
                $entraConnectIndicators += $entraHealthServers
            }

            if ($entraConnectIndicators.Count -gt 0) {
                Show-Line "Found $($entraConnectIndicators.Count) Entra ID Connect indicator(s):" -Class "Hint"
                foreach ($indicator in $entraConnectIndicators) {
                    # Parse description to extract server name and tenant
                    # Pattern: "...running on computer SERVERNAME configured to synchronize to tenant TENANT.onmicrosoft.com..."
                    if ($indicator.description -match 'running on computer\s+(\S+)\s+configured to synchronize to tenant\s+(\S+)') {
                        $entraServerName = $Matches[1]
                        $entraTenant = $Matches[2]

                        # Add parsed information as NoteProperties
                        $indicator | Add-Member -NotePropertyName 'entraConnectServer' -NotePropertyValue $entraServerName -Force
                        $indicator | Add-Member -NotePropertyName 'entraM365Tenant' -NotePropertyValue $entraTenant -Force
                    }

                    $indicator | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'EntraConnect' -Force
                    $indicator | Show-Object
                }
            } else {
                Show-Line "No Entra ID Connect servers found" -Class "Note"
            }

        } catch {
            Write-Log "[Get-InfrastructureServers] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-InfrastructureServers] Check completed"
    }
}



# ----- Get-NonDefaultComputerOwners.ps1 -----

function Get-NonDefaultComputerOwners {
    <#
    .SYNOPSIS
    Identifies computer accounts with non-default owners.

    .DESCRIPTION
    Enumerates all computer accounts and checks if the owner of the security descriptor is different from the expected default (Domain Admins).

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-NonDefaultComputerOwners

    .EXAMPLE
    Get-NonDefaultComputerOwners -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Computer
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC
    )

    begin {
        Write-Log "[Get-NonDefaultComputerOwners] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude OPSEC which Ensure-LDAPConnection doesn't accept)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for computers with non-default owners..." -ObjectType "NonDefaultComputerOwner"

            # OPSEC mode: Skip heavy-load enumeration
            if ($OPSEC) {
                Show-Line "OPSEC mode: Skipping computer owner enumeration (would check all enabled computers)" -Class "Hint"
                return
            }

            # Step 1: Bulk-load all enabled computers with owner info in a single LDAP query
            # -ShowOwner adds nTSecurityDescriptor to the query and extracts Owner/OwnerSID clientside
            # -Properties 'distinguishedName' keeps network traffic minimal (only DN + nTSecurityDescriptor)
            $computersWithOwner = @(Get-DomainComputer -Enabled -ShowOwner -Properties 'distinguishedName' @connectionParams)

            Write-Log "[Get-NonDefaultComputerOwners] Found $($computersWithOwner.Count) enabled computers, filtering non-default owners clientside..."

            $nonDefaultOwnerComputers = @()
            $nonDefaultOwnerDNs = @()
            $currentIndex = 0
            $totalComputers = $computersWithOwner.Count

            foreach ($computer in $computersWithOwner) {
                $currentIndex++

                # Progress indicator for large computer counts
                if ($totalComputers -gt 50) {
                    Show-Progress -Activity "Checking computer owners" -Current $currentIndex -Total $totalComputers
                }

                # Check if owner is non-default (clientside, no LDAP)
                if ($computer.OwnerSID -and -not (Test-IsDefaultOwner -SID $computer.OwnerSID)) {
                    $dn = if ($computer.distinguishedName -is [array]) { $computer.distinguishedName[0] } else { $computer.distinguishedName }

                    $nonDefaultOwnerDNs += [PSCustomObject]@{
                        DN = $dn
                        Owner = $computer.Owner
                        OwnerSID = $computer.OwnerSID
                    }
                }
            }

            # Clear progress bar
            if ($totalComputers -gt 50) {
                Show-Progress -Activity "Checking computer owners" -Completed
            }

            Write-Log "[Get-NonDefaultComputerOwners] Found $($nonDefaultOwnerDNs.Count) computer(s) with non-default owners, loading full objects..."

            # Step 2: Only for findings, fetch full computer objects for Show-Object display
            $totalFindings = $nonDefaultOwnerDNs.Count
            $currentIndex = 0
            foreach ($finding in $nonDefaultOwnerDNs) {
                $currentIndex++
                if ($totalFindings -gt $Script:ProgressThreshold) {
                    Show-Progress -Activity "Loading computer details" -Current $currentIndex -Total $totalFindings
                }

                $fullComputer = @(Get-DomainComputer -Identity $finding.DN @connectionParams)[0]

                if ($fullComputer) {
                    # Add owner info to computer object for display
                    $fullComputer | Add-Member -NotePropertyName 'Owner' -NotePropertyValue $finding.Owner -Force
                    $fullComputer | Add-Member -NotePropertyName 'OwnerSID' -NotePropertyValue $finding.OwnerSID -Force
                    $nonDefaultOwnerComputers += $fullComputer
                }
            }

            if ($totalFindings -gt $Script:ProgressThreshold) {
                Show-Progress -Activity "Loading computer details" -Completed
            }

            # Output results
            if (@($nonDefaultOwnerComputers).Count -gt 0) {
                Show-Line "Found $(@($nonDefaultOwnerComputers).Count) computer(s) with non-default owners:" -Class "Finding"

                foreach ($computer in $nonDefaultOwnerComputers) {
                    $computer | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'NonDefaultComputerOwner' -Force
                    Show-Object $computer
                }
            } else {
                Show-Line "All computers have default owners" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-NonDefaultComputerOwners] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-NonDefaultComputerOwners] Check completed"
    }
}



# ----- Get-GPOPermissions.ps1 -----

function Get-GPOPermissions {
    <#
    .SYNOPSIS
    Detects dangerous permissions on Group Policy Objects (GPOs).

    .DESCRIPTION
    Analyzes Access Control Lists (ACLs) on all Group Policy Objects for dangerous permissions that allow non-privileged users to modify GPOs, leading to privilege escalation.

    Checks for:
    - WriteProperty / WriteDacl permissions on GPO objects
    - GenericAll / GenericWrite permissions
    - Non-privileged users with GPO modification rights

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-GPOPermissions

    .EXAMPLE
    Get-GPOPermissions -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: GPO
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        Write-Log "[Get-GPOPermissions] Starting check"

        # Dangerous ACE Types for GPOs
        $Script:DangerousGPOAccessRights = @(
            'GenericAll',
            'GenericWrite',
            'WriteProperty',
            'WriteDacl',
            'WriteOwner'
        )
    }

    process {
        try {
            # Build connection parameters (exclude IncludePrivileged which is not a connection parameter)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            $domainDN = $Script:LDAPContext.DomainDN

            # ===== Step 1: Enumerate GPOs =====
            Show-SubHeader "Searching for dangerous GPO permissions..." -ObjectType "GPOPermission"

            $allGPOs = @(Get-DomainGPO @connectionParams)

            if (-not $allGPOs -or @($allGPOs).Count -eq 0) {
                Show-Line "No GPOs found in domain" -Class Note
                return
            }

            # ===== Step 2: Enumerate Computers for Impact Analysis =====
            # Include ALL computers (workstations, servers, AND domain controllers) for accurate impact analysis
            # GPOs affecting DCs are often more critical than those affecting workstations
            $allComputers = @(Get-DomainComputer -Properties "name","distinguishedName" @connectionParams)

            if (-not $allComputers) {
                $allComputers = @()
            }

            # ===== Step 3: Get GPO Linkage =====
            $gpoLinkage = Get-GPOLinkage

            # ===== Step 4: Analyze GPO Permissions =====
            $vulnerableGPOsHash = @{}

            $totalGPOs = @($allGPOs).Count
            $currentIndex = 0
            foreach ($gpo in $allGPOs) {
                $currentIndex++
                if ($totalGPOs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking GPO permissions" -Current $currentIndex -Total $totalGPOs -ObjectName $gpo.displayName }
                $gpoDisplayName = $gpo.DisplayName
                $gpoDN = $gpo.DistinguishedName
                $gpoGUID = $gpo.Name

                Write-Log "[Get-GPOPermissions] Analyzing GPO: $gpoDisplayName ($gpoGUID)"

                try {
                    # Use Get-ObjectACL for ACL analysis (handles credentials automatically)
                    # Get-ObjectACL returns a wrapper object with .ACEs property containing actual ACE array
                    $aclResult = Get-ObjectACL -DistinguishedName $gpoDN -DangerousOnly -AllowOnly -ExplicitOnly @connectionParams

                    if (-not $aclResult -or -not $aclResult.ACEs -or @($aclResult.ACEs).Count -eq 0) {
                        Write-Log "[Get-GPOPermissions] No dangerous ACEs found for GPO: $gpoDisplayName"
                        continue
                    }

                    $dangerousAces = @($aclResult.ACEs)
                    Write-Log "[Get-GPOPermissions] Processing $($dangerousAces.Count) dangerous ACE(s) for GPO: $gpoDisplayName"
                    $vulnerableIdentities = @()

                    foreach ($ace in $dangerousAces) {
                        # Get-ObjectACL returns ACEs with: TrusteeSID, Trustee, Rights, RightsRaw
                        $aceSID = $ace.TrusteeSID
                        $aceRights = $ace.Rights  # String like "GenericAll, WriteProperty"
                        $aceRightsRaw = $ace.RightsRaw  # Array for matching

                        # Skip ACEs with empty SID (can occur with orphaned/deleted principals)
                        if ([string]::IsNullOrEmpty($aceSID)) {
                            Write-Log "[Get-GPOPermissions] Skipping ACE with empty SID on GPO $gpoDisplayName (ACE object type: $($ace.GetType().FullName))"
                            continue
                        }

                        # Determine which dangerous right matched (using RightsRaw array)
                        $dangerousRightMatched = ""
                        foreach ($dangerousRight in $Script:DangerousGPOAccessRights) {
                            if ($aceRightsRaw -contains $dangerousRight) {
                                $dangerousRightMatched = $dangerousRight
                                break
                            }
                        }

                        # Check if SID is expected (Creator Owner, SELF, etc.) using GPO context
                        $expectedCheck = Test-IsExpectedACLIdentity -SID $aceSID -Context 'GPO'
                        if ($expectedCheck.Skip) {
                            Write-Log "[Get-GPOPermissions] Skipping expected identity $aceSID on GPO $gpoDisplayName : $($expectedCheck.Reason)"
                            continue
                        }

                        # Resolve identity name for display
                        $identityName = if ($ace.Trustee) { $ace.Trustee } else { ConvertFrom-SID -SID $aceSID }

                        # Determine severity
                        $severity = 'Finding'

                        if (-not $IncludePrivileged) {
                            # Use scope-based check for GPO permissions
                            $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'GPO' -ReturnDetails

                            if ($scopeResult.Severity -eq 'Expected') {
                                Write-Log "[Get-GPOPermissions] Expected identity $aceSID has $aceRights on GPO $gpoDisplayName - $($scopeResult.Reason)"
                                continue
                            }

                            if ($scopeResult.Severity -eq 'Attention') {
                                Write-Log "[Get-GPOPermissions] Attention: $identityName has $aceRights on GPO $gpoDisplayName - $($scopeResult.Reason) - skipped (use -IncludePrivileged to include)"
                                continue
                            }

                            $severity = $scopeResult.Severity
                        } else {
                            # -IncludePrivileged: Show ALL accounts, but mark privileged ones for yellow display
                            $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'GPO' -ReturnDetails
                            $severity = $scopeResult.Severity
                            Write-Log "[Get-GPOPermissions] IncludePrivileged: Including $identityName ($aceSID) with severity $severity on GPO $gpoDisplayName"
                        }

                        Write-Log "[Get-GPOPermissions] FINDING: $identityName has $aceRights on GPO $gpoDisplayName"

                        $vulnerableIdentities += [PSCustomObject]@{
                            Identity = $identityName
                            SID = $aceSID
                            Rights = $aceRights
                            DangerousRight = $dangerousRightMatched
                            Severity = $severity
                        }
                    }

                    # If we found vulnerable identities for this GPO, add to results
                    if (@($vulnerableIdentities).Count -gt 0) {
                        # Get GPO Linkage for this GPO
                        $links = $gpoLinkage[$gpoGUID]
                        $activeLinks = @()
                        $isDomainWide = $false
                        $linkCount = 0

                        if ($links) {
                            $activeLinks = @($links | Where-Object { $_.LinkStatus -ne "Disabled" })
                            $linkCount = $activeLinks.Count

                            $domainWideLink = $activeLinks | Where-Object { $_.Scope -eq "Domain" }
                            $isDomainWide = ($null -ne $domainWideLink)
                        }

                        $affectedComputerCount = 0

                        if ($isDomainWide) {
                            $affectedComputerCount = @($allComputers).Count
                        }
                        elseif (@($activeLinks).Count -gt 0) {
                            foreach ($computer in $allComputers) {
                                $computerDN = $computer.distinguishedName

                                if ($computerDN -match '^CN=[^,]+,(.+)$') {
                                    $computerParentDN = $Matches[1]
                                    $isCovered = $false
                                    $currentDN = $computerParentDN

                                    while ($currentDN -ne $domainDN -and -not $isCovered) {
                                        foreach ($link in $activeLinks) {
                                            if ($link.DistinguishedName -eq $currentDN) {
                                                $isCovered = $true
                                                break
                                            }
                                        }

                                        if ($isCovered) { break }

                                        if ($currentDN -match '^[^,]+,(.+)$') {
                                            $currentDN = $Matches[1]
                                        }
                                        else {
                                            break
                                        }
                                    }

                                    if ($isCovered) {
                                        $affectedComputerCount++
                                    }
                                }
                            }
                        }

                        # Build scope info and linked OUs list
                        $scopeInfo = if ($isDomainWide) {
                            "Domain-wide"
                        } elseif ($linkCount -gt 0) {
                            "Linked to $linkCount OU(s)"
                        } else {
                            "NOT LINKED"
                        }

                        # Build LinkedOUs list (show where GPO is linked) - use full DN
                        $linkedOUsDisplay = $null
                        if (@($activeLinks).Count -gt 0) {
                            $linkedOUsDisplay = ($activeLinks | ForEach-Object {
                                $_.DistinguishedName
                            }) -join "`n"
                        }

                        # Format vulnerable identities for display
                        $identityDisplay = ($vulnerableIdentities | ForEach-Object {
                            "$($_.Identity) ($($_.DangerousRight))"
                        }) -join "`n"

                        $enrichedGPO = $gpo.PSObject.Copy()
                        $enrichedGPO | Add-Member -NotePropertyName "DangerousPermissions" -NotePropertyValue $identityDisplay -Force
                        $enrichedGPO | Add-Member -NotePropertyName "Scope" -NotePropertyValue $scopeInfo -Force
                        if ($linkedOUsDisplay) {
                            $enrichedGPO | Add-Member -NotePropertyName "LinkedOUs" -NotePropertyValue $linkedOUsDisplay -Force
                        }
                        $enrichedGPO | Add-Member -NotePropertyName "affectedComputerCount" -NotePropertyValue $affectedComputerCount -Force
                        $enrichedGPO | Add-Member -NotePropertyName "IsDomainWide" -NotePropertyValue $isDomainWide -Force

                        $vulnerableGPOsHash[$gpoGUID] = $enrichedGPO
                    }
                }
                catch {
                    Write-Log "[Get-GPOPermissions] Error analyzing GPO $gpoDisplayName : $_"
                }
            }
            if ($totalGPOs -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking GPO permissions" -Completed }

            $vulnerableGPOs = @($vulnerableGPOsHash.Values)

            if (@($vulnerableGPOs).Count -gt 0) {
                Show-Line "Found $(@($vulnerableGPOs).Count) GPO(s) with dangerous permissions" -Class Finding

                foreach ($gpo in $vulnerableGPOs) {
                    $gpo | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPOPermission' -Force
                    Show-Object $gpo
                }
            }
            else {
                Show-Line "No dangerous GPO permissions found in $(@($allGPOs).Count) analyzed GPO(s)" -Class Secure
            }

        } catch {
            Write-Log "[Get-GPOPermissions] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-GPOPermissions] Check completed"
    }
}



# ----- Get-GPOLocalGroupMembership.ps1 -----

function Get-GPOLocalGroupMembership {
    <#
    .SYNOPSIS
    Detects GPO-based local group membership assignments.

    .DESCRIPTION
    Analyzes Group Policy Objects for local group membership modifications:
    - Restricted Groups (GptTmpl.inf)
    - Group Policy Preferences Groups (Groups.xml)
    Requires SMB access to \\domain\SYSVOL.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-GPOLocalGroupMembership

    .EXAMPLE
    Get-GPOLocalGroupMembership -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: GPO
    Author: Alexander Sturz (@_61106960_)
    Reference:
    - Restricted Groups: https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj852219(v=ws.11)
    - Group Policy Preferences: https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/dn581922(v=ws.11)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-GPOLocalGroupMembership] Starting check"

        # Well-known SIDs for local groups
        $Script:LocalGroupSIDs = @{
            'S-1-5-32-544' = 'Administrators'
            'S-1-5-32-555' = 'Remote Desktop Users'
            'S-1-5-32-580' = 'Remote Management Users'
            'S-1-5-32-551' = 'Backup Operators'
            'S-1-5-32-547' = 'Power Users'
        }

        # Well-known SIDs for risky assignments (Everyone, Authenticated Users, etc.)
        $Script:RiskySIDs = @{
            'S-1-1-0' = 'Everyone'
            'S-1-5-11' = 'Authenticated Users'
            'S-1-5-7' = 'Anonymous Logon'
        }

        # Base severity per target group (using standard adPEAS severity values)
        # Finding = Critical/High issues, Hint = Medium issues, Note = Low/Info
        $Script:GroupSeverityConfig = @{
            'S-1-5-32-544' = @{ Severity = "Finding"; Risk = "Domain accounts added to local Administrators" }
            'S-1-5-32-555' = @{ Severity = "Hint"; Risk = "Domain accounts added to Remote Desktop Users" }
            'S-1-5-32-580' = @{ Severity = "Hint"; Risk = "Domain accounts added to Remote Management Users" }
            'S-1-5-32-551' = @{ Severity = "Hint"; Risk = "Domain accounts added to Backup Operators" }
            'S-1-5-32-547' = @{ Severity = "Note"; Risk = "Domain accounts added to Power Users" }
        }
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            $domainFQDN = $Script:LDAPContext.Domain
            $Script:vulnerableGPOs = @()

            Show-SubHeader "Searching for GPO local group assignments..." -ObjectType "GPOLocalGroup"

            $gpos = Get-DomainGPO @PSBoundParameters

            if (-not $gpos -or @($gpos).Count -eq 0) {
                Show-Line "No GPOs found in domain" -Class Note
                return
            }

            $gpoLinkage = Get-GPOLinkage

            # Build GPO GUID to name mapping for later lookup
            $gpoNameMap = @{}
            foreach ($gpo in $gpos) {
                $gpoNameMap[$gpo.Name] = $gpo.DisplayName
            }

            # Track SYSVOL access status
            $Script:sysvolAccessible = $false

            # SYSVOL Access with Credential Support
            Invoke-SMBAccess -Description "Scanning GPO Groups.xml files" -ScriptBlock {
                $sysvolPath = "\\$($Script:LDAPContext.Server)\SYSVOL\$domainFQDN\Policies"

                if (-not (Test-Path $sysvolPath)) {
                    Write-Log "[Get-GPOLocalGroupMembership] SYSVOL path not accessible: $sysvolPath"
                    return
                }

                $Script:sysvolAccessible = $true

                # Use cached SYSVOL file listing (no redundant SMB directory traversal)
                $gptTmplFiles = Get-CachedSYSVOLFiles -Filter "GptTmpl.inf"

                $totalFiles = @($gptTmplFiles).Count
                $currentIndex = 0
                foreach ($file in $gptTmplFiles) {
                    $currentIndex++
                    if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO local group assignments" -Current $currentIndex -Total $totalFiles -ObjectName $file.Name }
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                    if ($file.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                        $gpoGUID = $Matches[1]
                        $gpoName = if ($gpoNameMap.ContainsKey($gpoGUID)) { $gpoNameMap[$gpoGUID] } else { $gpoGUID }

                        try {
                            Write-Log "[Get-GPOLocalGroupMembership] Reading: $($file.FullName)"
                            $restrictedGroupsFindings = Parse-RestrictedGroups -FilePath $file.FullName -GPOName $gpoName -GPOGUID $gpoGUID

                            if ($restrictedGroupsFindings) {
                                $linkedOUs = @()
                                if ($gpoLinkage.ContainsKey($gpoGUID)) {
                                    $linkedOUs = $gpoLinkage[$gpoGUID]
                                }

                                foreach ($finding in $restrictedGroupsFindings) {
                                    $finding | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUs -Force
                                    $finding | Add-Member -NotePropertyName 'LinkedOUCount' -NotePropertyValue $linkedOUs.Count -Force
                                }

                                $Script:vulnerableGPOs += @($restrictedGroupsFindings)
                            }
                        } catch {
                            Write-Log "[Get-GPOLocalGroupMembership] Error parsing $($file.FullName): $_"
                        }
                    }
                }
                if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO local group assignments" -Completed }

                # Use cached SYSVOL file listing (no redundant SMB directory traversal)
                $groupsXmlFiles = Get-CachedSYSVOLFiles -Filter "Groups.xml"

                $totalXmlFiles = @($groupsXmlFiles).Count
                $currentXmlIndex = 0
                foreach ($file in $groupsXmlFiles) {
                    $currentXmlIndex++
                    if ($totalXmlFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPP Groups.xml files" -Current $currentXmlIndex -Total $totalXmlFiles -ObjectName $file.Name }
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                    if ($file.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                        $gpoGUID = $Matches[1]
                        $gpoName = if ($gpoNameMap.ContainsKey($gpoGUID)) { $gpoNameMap[$gpoGUID] } else { $gpoGUID }

                        try {
                            Write-Log "[Get-GPOLocalGroupMembership] Reading: $($file.FullName)"
                            $gppGroupsFindings = Parse-GPPGroups -FilePath $file.FullName -GPOName $gpoName -GPOGUID $gpoGUID

                            if ($gppGroupsFindings) {
                                $linkedOUs = @()
                                if ($gpoLinkage.ContainsKey($gpoGUID)) {
                                    $linkedOUs = $gpoLinkage[$gpoGUID]
                                }

                                foreach ($finding in $gppGroupsFindings) {
                                    $finding | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUs -Force
                                    $finding | Add-Member -NotePropertyName 'LinkedOUCount' -NotePropertyValue $linkedOUs.Count -Force
                                }

                                $Script:vulnerableGPOs += @($gppGroupsFindings)
                            }
                        } catch {
                            Write-Log "[Get-GPOLocalGroupMembership] Error parsing $($file.FullName): $_"
                        }
                    }
                }
                if ($totalXmlFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPP Groups.xml files" -Completed }
            }

            # Collect findings from scriptblock (Script scope bridges the child scope boundary)
            $vulnerableGPOs = $Script:vulnerableGPOs
            $Script:vulnerableGPOs = $null

            # Check if SYSVOL was accessible
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:sysvolAccessible = $null

            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                } else {
                    Show-Line "SYSVOL access failed - cannot analyze GPO local group assignments - SMB access failed (authentication/network issue)" -Class Finding
                }
                return
            }

            if (@($vulnerableGPOs).Count -gt 0) {
                Show-Line "Found $(@($vulnerableGPOs).Count) vulnerable GPO local group assignment(s)" -Class Finding

                foreach ($finding in $vulnerableGPOs) {
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPOLocalGroup' -Force
                    Show-Object $finding
                }
            } else {
                Show-Line "No vulnerable GPO local group assignments found in $(@($gpos).Count) analyzed GPO(s)" -Class Secure
            }

        } catch {
            Write-Log "[Get-GPOLocalGroupMembership] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-GPOLocalGroupMembership] Check completed"
    }
}

# Helper Function: Get severity and risk for a group assignment
function Get-GroupAssignmentSeverity {
    param(
        [string]$GroupSID,
        [array]$RiskyMembers
    )

    $config = $Script:GroupSeverityConfig[$GroupSID]
    if (-not $config) {
        return @{ Severity = "Hint"; Risk = "Domain accounts added to local group" }
    }

    $severity = $config.Severity
    $risk = $config.Risk

    # Escalate severity if risky members (Everyone, Domain Users, etc.) are present
    # Using standard adPEAS severity values: Note -> Hint -> Finding
    if (@($RiskyMembers).Count -gt 0) {
        $riskyList = $RiskyMembers -join ', '

        # Escalate: Note->Hint, Hint->Finding, Finding stays Finding
        $severity = switch ($severity) {
            "Note"     { "Hint" }
            "Hint"     { "Finding" }
            "Finding"  { "Finding" }
            default    { $severity }
        }

        $risk = "$risk (includes: $riskyList)"
    }

    return @{ Severity = $severity; Risk = $risk }
}

# Helper Function: Parse Restricted Groups (GptTmpl.inf)
function Parse-RestrictedGroups {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$FilePath,

        [Parameter(Mandatory=$true)]
        [string]$GPOName,

        [Parameter(Mandatory=$true)]
        [string]$GPOGUID
    )

    try {
        $content = Get-CachedSYSVOLContent -Path $FilePath
        if (-not $content) { return @() }
        $findings = @()

        if ($content -match '(?s)\[Group Membership\](.*?)(\[|$)') {
            $groupMembershipSection = $Matches[1]
            $lines = $groupMembershipSection -split "`n"

            foreach ($line in $lines) {
                $line = $line.Trim()

                if ($line -match '^\*(.+?)__Members\s*=\s*(.+)$') {
                    # Variant 1: *LOCAL_GROUP_SID__Members = *SID1, *SID2
                    # The local group is on the LEFT, members are on the RIGHT
                    $groupSID = $Matches[1]
                    $memberSIDs = $Matches[2] -split ',' | ForEach-Object { $_.Trim().TrimStart('*') }

                    if ($Script:LocalGroupSIDs.ContainsKey($groupSID)) {
                        $groupName = $Script:LocalGroupSIDs[$groupSID]

                        $memberNames = @()
                        $riskyMembers = @()

                        foreach ($memberSID in $memberSIDs) {
                            if ([string]::IsNullOrWhiteSpace($memberSID)) { continue }

                            $memberName = ""

                            if ($Script:RiskySIDs.ContainsKey($memberSID)) {
                                $memberName = $Script:RiskySIDs[$memberSID]
                                $riskyMembers += $memberName
                            } elseif ($memberSID -match '-513$') {
                                $memberName = "Domain Users"
                                $riskyMembers += $memberName
                            } else {
                                $memberName = ConvertFrom-SID -SID $memberSID
                            }

                            $memberNames += $memberName
                        }

                        # Get severity from centralized configuration
                        $severityResult = Get-GroupAssignmentSeverity -GroupSID $groupSID -RiskyMembers $riskyMembers

                        $findings += [PSCustomObject]@{
                            GPOName = $GPOName
                            GPOGUID = $GPOGUID
                            Type = "Restricted Groups"
                            TargetGroup = $groupName
                            TargetGroupSID = $groupSID
                            MembersAdded = $memberNames
                            MemberSIDs = $memberSIDs
                            RiskyMembers = $riskyMembers
                            Severity = $severityResult.Severity
                            Risk = $severityResult.Risk
                        }
                    }
                }
                elseif ($line -match '^\*(.+?)__Memberof\s*=\s*(.+)$') {
                    # Variant 2: *DOMAIN_SID__Memberof = *LOCAL_GROUP_SID1, *LOCAL_GROUP_SID2
                    # The account/group being added is on the LEFT, target local groups are on the RIGHT
                    # One finding per target local group (each may have different severity)
                    $memberSID = $Matches[1]
                    $targetGroupSIDs = $Matches[2] -split ',' | ForEach-Object { $_.Trim().TrimStart('*') }

                    # Resolve the member name and check if it is itself a risky principal
                    $memberName = ""
                    $riskyMembers = @()

                    if ($Script:RiskySIDs.ContainsKey($memberSID)) {
                        $memberName = $Script:RiskySIDs[$memberSID]
                        $riskyMembers += $memberName
                    } elseif ($memberSID -match '-513$') {
                        $memberName = "Domain Users"
                        $riskyMembers += $memberName
                    } else {
                        $memberName = ConvertFrom-SID -SID $memberSID
                    }

                    # Create one finding per target local group
                    foreach ($groupSID in $targetGroupSIDs) {
                        if ([string]::IsNullOrWhiteSpace($groupSID)) { continue }

                        if ($Script:LocalGroupSIDs.ContainsKey($groupSID)) {
                            $groupName = $Script:LocalGroupSIDs[$groupSID]

                            $severityResult = Get-GroupAssignmentSeverity -GroupSID $groupSID -RiskyMembers $riskyMembers

                            $findings += [PSCustomObject]@{
                                GPOName = $GPOName
                                GPOGUID = $GPOGUID
                                Type = "Restricted Groups"
                                TargetGroup = $groupName
                                TargetGroupSID = $groupSID
                                MembersAdded = @($memberName)
                                MemberSIDs = @($memberSID)
                                RiskyMembers = $riskyMembers
                                Severity = $severityResult.Severity
                                Risk = $severityResult.Risk
                            }
                        }
                    }
                }
            }
        }

        return $findings
    } catch {
        Write-Log "[Parse-RestrictedGroups] Error parsing $FilePath : $_"
        return $null
    }
}

# Helper Function: Parse Group Policy Preferences Groups (Groups.xml)
function Parse-GPPGroups {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$FilePath,

        [Parameter(Mandatory=$true)]
        [string]$GPOName,

        [Parameter(Mandatory=$true)]
        [string]$GPOGUID
    )

    try {
        # Use XmlDocument.Load() to honor the XML encoding declaration / BOM.
        # Get-Content defaults to the ANSI code page in Windows PowerShell 5.1,
        # which mojibakes UTF-8 Groups.xml: a localized group name containing an umlaut
        # then decodes into two wrong characters and no longer matches.
        $xmlContent = New-Object System.Xml.XmlDocument
        $xmlContent.Load($FilePath)
        $findings = @()

        $groups = $xmlContent.Groups.Group

        foreach ($group in $groups) {
            # Use groupSid attribute (SID-based, language-independent)
            $groupSID = $group.Properties.groupSid

            # Skip if no SID or not a target group (use centrally defined SIDs)
            if (-not $groupSID -or -not $Script:LocalGroupSIDs.ContainsKey($groupSID)) {
                continue
            }

            # Get canonical group name from SID
            $canonicalGroupName = $Script:LocalGroupSIDs[$groupSID]

            $members = @()
            $memberSIDs = @()
            $riskyMembers = @()

            if ($group.Properties.Members) {
                foreach ($member in $group.Properties.Members.Member) {
                    # Only process ADD actions
                    if ($member.action -ne 'ADD') { continue }

                    $memberName = $member.name
                    $memberSID = $member.sid

                    if ($memberName) {
                        $members += $memberName
                    }

                    if ($memberSID) {
                        $memberSIDs += $memberSID

                        # Check for risky SIDs (language-independent)
                        if ($Script:RiskySIDs.ContainsKey($memberSID)) {
                            $riskyMembers += $Script:RiskySIDs[$memberSID]
                        } elseif ($memberSID -match '-513$') {
                            # Domain Users (ends with -513)
                            $riskyMembers += "Domain Users"
                        }
                    }
                }
            }

            if (@($members).Count -eq 0) {
                continue
            }

            # Get severity from centralized configuration
            $severityResult = Get-GroupAssignmentSeverity -GroupSID $groupSID -RiskyMembers $riskyMembers

            $findings += [PSCustomObject]@{
                GPOName = $GPOName
                GPOGUID = $GPOGUID
                Type = "Group Policy Preferences"
                TargetGroup = $canonicalGroupName
                TargetGroupSID = $groupSID
                MembersAdded = $members
                MemberSIDs = $memberSIDs
                RiskyMembers = $riskyMembers
                Severity = $severityResult.Severity
                Risk = $severityResult.Risk
            }
        }

        return $findings
    } catch {
        Write-Log "[Parse-GPPGroups] Error parsing $FilePath : $_"
        return $null
    }
}




# ----- Get-GPOScheduledTasks.ps1 -----

function Get-GPOScheduledTasks {
    <#
    .SYNOPSIS
    Detects Scheduled Tasks distributed via Group Policy Preferences.

    .DESCRIPTION
    Analyzes Group Policy Objects for Scheduled Tasks (ScheduledTasks.xml).
    All Scheduled Tasks distributed via GPO are manually configured by administrators.

    Focuses on security-critical configurations:
    - Tasks running as SYSTEM or privileged accounts
    - Tasks executing from UNC paths (credential theft vector)
    - Tasks executing from world-writable locations (privilege escalation)
    - Command injection vulnerabilities

    Requires SMB access to \\domain\SYSVOL.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-GPOScheduledTasks

    .EXAMPLE
    Get-GPOScheduledTasks -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: GPO
    Author: Alexander Sturz (@_61106960_)
    Reference:
    - Group Policy Preferences: https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/dn581922(v=ws.11)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-GPOScheduledTasks] Starting check"

        # Risky paths (world-writable or commonly exploitable by standard users)
        $Script:RiskyPaths = @(
            'C:\Temp',
            'C:\Windows\Temp',
            '%TEMP%',
            '%TMP%',
            'C:\Users\Public',
            'C:\Users\Default',
            'C:\ProgramData',
            'C:\Windows\Tasks',
            'C:\Windows\System32\spool\drivers',
            'C:\Windows\debug',
            'C:\Windows\tracing',
            'C:\Windows\System32\LogFiles',
            'C:\Windows\Registration\CRMLog',
            'C:\Windows\Installer',
            'C:\Windows\Downloaded Program Files',
            'C:\inetpub\wwwroot',
            'C:\inetpub\temp',
            'C:\Scripts',
            'C:\PerfLogs'
        )
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            $domainFQDN = $Script:LDAPContext.Domain
            $Script:_gpoScheduledTasks = [System.Collections.ArrayList]::new()

            Show-SubHeader "Searching for GPO scheduled tasks..." -ObjectType "GPOScheduledTask"

            $gpos = Get-DomainGPO @PSBoundParameters

            if (-not $gpos) {
                Show-Line "No GPOs found in domain" -Class Note
                return
            }

            $gpoLinkage = Get-GPOLinkage

            # Track SYSVOL access status
            $Script:sysvolAccessible = $false

            # Build GPO GUID to name mapping for later lookup
            $gpoNameMap = @{}
            foreach ($gpo in $gpos) {
                $gpoNameMap[$gpo.Name] = $gpo.DisplayName
            }

            # SYSVOL Access with Credential Support
            Invoke-SMBAccess -Description "Scanning GPO ScheduledTasks.xml files" -ScriptBlock {
                $sysvolPath = "\\$($Script:LDAPContext.Server)\SYSVOL\$domainFQDN\Policies"

                if (-not (Test-Path $sysvolPath)) {
                    return
                }

                $Script:sysvolAccessible = $true

                # Use cached SYSVOL file listing (no redundant SMB directory traversal)
                $scheduledTasksFiles = Get-CachedSYSVOLFiles -Filter "ScheduledTasks.xml"

                if (-not $scheduledTasksFiles) {
                    Write-Log "[Get-GPOScheduledTasks] No ScheduledTasks.xml files found in SYSVOL"
                    return
                }

                Write-Log "[Get-GPOScheduledTasks] Found $($scheduledTasksFiles.Count) ScheduledTasks.xml file(s)"

                $totalFiles = @($scheduledTasksFiles).Count
                $currentIndex = 0
                foreach ($file in $scheduledTasksFiles) {
                    $currentIndex++
                    if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO scheduled tasks" -Current $currentIndex -Total $totalFiles -ObjectName $file.Name }
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\...
                    if ($file.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                        $gpoGUID = $Matches[1]
                        $gpoName = if ($gpoNameMap.ContainsKey($gpoGUID)) { $gpoNameMap[$gpoGUID] } else { $gpoGUID }

                        try {
                            Write-Log "[Get-GPOScheduledTasks] Reading: $($file.FullName)"
                            $taskFindings = Parse-ScheduledTasksXML -FilePath $file.FullName -GPOName $gpoName -GPOGUID $gpoGUID

                            if ($taskFindings) {
                                $linkedOUs = @()
                                if ($gpoLinkage.ContainsKey($gpoGUID)) {
                                    $linkedOUs = $gpoLinkage[$gpoGUID]
                                }

                                foreach ($task in $taskFindings) {
                                    # Only add LinkedOUs if not empty (prevents rendering issues with empty arrays)
                                    if ($linkedOUs.Count -gt 0) {
                                        $task | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUs -Force
                                    }
                                    $task | Add-Member -NotePropertyName 'LinkedOUCount' -NotePropertyValue $linkedOUs.Count -Force
                                }

                                [void]$Script:_gpoScheduledTasks.AddRange(@($taskFindings))
                            }
                        } catch {
                            Write-Log "[Get-GPOScheduledTasks] Error parsing $($file.FullName): $_"
                        }
                    }
                }
                if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO scheduled tasks" -Completed }
            }

            # Retrieve results and clean up Script-scoped temp variables
            $scheduledTasks = @($Script:_gpoScheduledTasks)
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:_gpoScheduledTasks = $null
            $Script:sysvolAccessible = $null

            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                } else {
                    Show-Line "SYSVOL access failed - cannot analyze GPO scheduled tasks - SMB access failed (authentication/network issue)" -Class Finding
                }
                return
            }

            if ($scheduledTasks.Count -gt 0) {
                Show-Line "Found $($scheduledTasks.Count) scheduled task(s) distributed via GPO" -Class Hint

                foreach ($task in $scheduledTasks) {
                    $task.PSObject.Properties.Remove('_Severity')
                    $task.PSObject.Properties.Remove('_Risk')
                    $task | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPOScheduledTask' -Force
                    Show-Object $task
                }
            } else {
                Show-Line "No scheduled tasks distributed via GPO in $($gpos.Count) analyzed GPO(s)" -Class Note
            }

        } catch {
            Write-Log "[Get-GPOScheduledTasks] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-GPOScheduledTasks] Check completed"
    }
}

# Helper Function: Parse ScheduledTasks.xml
function Parse-ScheduledTasksXML {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$FilePath,

        [Parameter(Mandatory=$true)]
        [string]$GPOName,

        [Parameter(Mandatory=$true)]
        [string]$GPOGUID
    )

    try {
        # Use XmlDocument.Load() to honor the XML encoding declaration / BOM.
        # Get-Content defaults to the ANSI code page in Windows PowerShell 5.1,
        # which mojibakes UTF-8 GPP XML (umlauts in task names / run-as accounts).
        $xmlContent = New-Object System.Xml.XmlDocument
        $xmlContent.Load($FilePath)
        $tasks = @()

        $context = if ($FilePath -match '\\Machine\\') { 'Machine' } else { 'User' }

        $taskNodes = $xmlContent.SelectNodes("//Task | //TaskV2 | //ImmediateTask | //ImmediateTaskV2")

        foreach ($taskNode in $taskNodes) {
            $taskName = if ($taskNode.Properties.name) { $taskNode.Properties.name } else { "Unnamed Task" }
            $runAs = if ($taskNode.Properties.runAs) { $taskNode.Properties.runAs } else { "Unknown" }
            $action = if ($taskNode.Properties.action) { $taskNode.Properties.action } else { "Unknown" }

            $command = ""
            $arguments = ""

            if ($taskNode.Properties.Task) {
                $taskXml = $taskNode.Properties.Task

                if ($taskXml.Actions) {
                    $execAction = $taskXml.Actions.Exec
                    if ($execAction) {
                        $command = if ($execAction.Command) { $execAction.Command } else { "" }
                        $arguments = if ($execAction.Arguments) { $execAction.Arguments } else { "" }
                    }
                }
            }

            if ([string]::IsNullOrEmpty($command)) {
                $command = if ($taskNode.Properties.appName) { $taskNode.Properties.appName } else { "" }
                $arguments = if ($taskNode.Properties.args) { $taskNode.Properties.args } else { "" }
            }

            $fullCommand = if ($arguments) { "$command $arguments" } else { $command }

            if ([string]::IsNullOrEmpty($fullCommand)) {
                continue
            }

            # Security Analysis
            $severity = "Note"
            $risk = ""

            # Check for SYSTEM account (well-known SID S-1-5-18 or common string patterns)
            # These are language-independent system accounts
            $isSystemAccount = $false
            if ($runAs -match '^S-1-5-18$' -or                           # SYSTEM SID directly
                $runAs -match '\\SYSTEM$' -or                             # NT AUTHORITY\SYSTEM (any language)
                $runAs -match '^SYSTEM$' -or                              # Just SYSTEM
                $runAs -match 'LocalSystem' -or                           # LocalSystem
                $runAs -match '^S-1-5-19$' -or                            # LOCAL SERVICE
                $runAs -match '\\LOCAL SERVICE$' -or
                $runAs -match '^S-1-5-20$' -or                            # NETWORK SERVICE
                $runAs -match '\\NETWORK SERVICE$') {
                $isSystemAccount = $true
            }

            # Try to resolve the account name to SID, then check if privileged
            $isPrivilegedAccount = $false
            if (-not $isSystemAccount -and $runAs -ne "Unknown" -and -not [string]::IsNullOrEmpty($runAs)) {
                try {
                    # Try to resolve account name to SID
                    $accountSID = $null
                    if ($runAs -match '^S-1-') {
                        # Already a SID
                        $accountSID = $runAs
                    } else {
                        # Try to resolve name to SID
                        $accountSID = ConvertTo-SID -Name $runAs
                    }

                    if ($accountSID) {
                        # Check if account is in a privileged category
                        $category = (Test-IsPrivileged -Identity $accountSID).Category
                        $isPrivilegedAccount = $category -in @('Privileged', 'Operator')
                    }
                } catch {
                    Write-Log "[Parse-ScheduledTasksXML] Could not resolve account '$runAs' to SID: $_"
                }
            }

            $hasUNCPath = $fullCommand -match '\\\\[^\\]+\\'
            $hasRiskyPath = $false

            foreach ($riskyPath in $Script:RiskyPaths) {
                if ($fullCommand -match [regex]::Escape($riskyPath)) {
                    $hasRiskyPath = $true
                    break
                }
            }

            $hasUnquotedPath = ($command -match '\s' -and $command -notmatch '^".*"$')
            $isPowerShell = $command -match 'powershell|pwsh'
            $isScript = $command -match '\.(bat|cmd|vbs|vbe|ps1|wsf)$'

            # Severity Determination (using standard adPEAS severity values)
            if ($isSystemAccount -and $hasUNCPath) {
                $severity = "Finding"
                $risk = "Task runs as SYSTEM and uses UNC path - SMB credential relay attack vector"
            } elseif ($isSystemAccount -and $hasRiskyPath) {
                $severity = "Finding"
                $risk = "Task runs as SYSTEM from world-writable location - privilege escalation via file modification"
            } elseif ($isSystemAccount -and $isScript) {
                $severity = "Finding"
                $risk = "Task runs script as SYSTEM - check if script is modifiable"
            } elseif ($isSystemAccount -and $isPowerShell) {
                $severity = "Finding"
                $risk = "Task runs PowerShell as SYSTEM - check command for injection vulnerabilities"
            } elseif ($isPrivilegedAccount) {
                $severity = "Finding"
                $risk = "Task runs as privileged account"
            } elseif ($hasUNCPath) {
                $severity = "Hint"
                $risk = "Task uses UNC path - potential SMB credential exposure"
            } elseif ($hasUnquotedPath) {
                $severity = "Hint"
                $risk = "Unquoted path with spaces - potential command injection"
            } elseif ($isSystemAccount) {
                $severity = "Hint"
                $risk = "Task runs as SYSTEM"
            }

            $trigger = "Unknown"
            if ($taskNode.Properties.Task.Triggers) {
                $triggers = $taskNode.Properties.Task.Triggers
                if ($triggers.LogonTrigger) {
                    $trigger = "At Logon"
                } elseif ($triggers.BootTrigger) {
                    $trigger = "At Startup"
                } elseif ($triggers.TimeTrigger) {
                    $trigger = "Scheduled (Time-based)"
                } elseif ($triggers.CalendarTrigger) {
                    $trigger = "Scheduled (Calendar)"
                }
            }

            # Build display object with only user-relevant properties
            # Internal analysis flags (Is*/Has*) are used above for severity but not displayed
            # _Severity and _Risk are internal transport properties (removed before Show-Object)
            $taskProps = [ordered]@{
                GPOName    = $GPOName
                TaskName   = $taskName
                Command    = $fullCommand
                RunAs      = $runAs
                Context    = $context
                Action     = $action
                Trigger    = $trigger
                _Severity  = $severity
                _Risk      = $risk
            }

            $task = [PSCustomObject]$taskProps

            $tasks += $task
        }

        return $tasks
    } catch {
        Write-Log "[Parse-ScheduledTasksXML] Error parsing $FilePath : $_"
        return $null
    }
}



# ----- Get-GPOScriptPaths.ps1 -----

function Get-GPOScriptPaths {
    <#
    .SYNOPSIS
    Detects Logon/Logoff/Startup/Shutdown scripts distributed via Group Policy.

    .DESCRIPTION
    Analyzes Group Policy Objects for script configurations in scripts.ini and psscripts.ini.
    These scripts are manually configured by administrators and execute automatically:
    - Startup/Shutdown scripts run as SYSTEM (Machine context)
    - Logon/Logoff scripts run in user context

    Focuses on:
    - Scripts running as SYSTEM (startup/shutdown) from UNC or writable paths
    - Scripts executing from network shares (credential exposure)
    - PowerShell scripts configured via psscripts.ini

    Requires SMB access to \\domain\SYSVOL.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-GPOScriptPaths

    .EXAMPLE
    Get-GPOScriptPaths -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: GPO
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-GPOScriptPaths] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            $domainFQDN = $Script:LDAPContext.Domain
            $Script:_gpoScriptFindings = [System.Collections.ArrayList]::new()

            Show-SubHeader "Searching for GPO-deployed scripts..." -ObjectType "GPOScriptPath"

            $gpos = Get-DomainGPO @PSBoundParameters

            if (-not $gpos) {
                Show-Line "No GPOs found in domain" -Class Note
                return
            }

            $gpoLinkage = Get-GPOLinkage

            # Build GPO GUID to name mapping
            $gpoNameMap = @{}
            foreach ($gpo in $gpos) {
                $gpoNameMap[$gpo.Name] = $gpo.DisplayName
            }

            # Track SYSVOL access status
            $Script:sysvolAccessible = $false

            # SYSVOL Access with Credential Support
            Invoke-SMBAccess -Description "Scanning GPO script configuration files" -ScriptBlock {
                $sysvolPath = "\\$($Script:LDAPContext.Server)\SYSVOL\$domainFQDN\Policies"

                if (-not (Test-Path $sysvolPath)) {
                    return
                }

                $Script:sysvolAccessible = $true

                # Use cached SYSVOL file listing (no redundant SMB directory traversal)
                $scriptFiles = @(Get-CachedSYSVOLFiles -Filter @("scripts.ini", "psscripts.ini"))

                if ($scriptFiles.Count -eq 0) {
                    Write-Log "[Get-GPOScriptPaths] No script configuration files found in SYSVOL"
                    return
                }

                Write-Log "[Get-GPOScriptPaths] Found $($scriptFiles.Count) script configuration file(s)"

                $totalFiles = @($scriptFiles).Count
                $currentIndex = 0
                foreach ($file in $scriptFiles) {
                    $currentIndex++
                    if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO script paths" -Current $currentIndex -Total $totalFiles -ObjectName $file.Name }
                    # Extract GPO GUID from path: ...\Policies\{GUID}\Machine\Scripts\...
                    if ($file.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                        $gpoGUID = $Matches[1]
                        $gpoName = if ($gpoNameMap.ContainsKey($gpoGUID)) { $gpoNameMap[$gpoGUID] } else { $gpoGUID }

                        # Determine context from path
                        $context = if ($file.FullName -match '\\Machine\\') { 'Machine' } else { 'User' }
                        $isPowerShell = $file.Name -eq 'psscripts.ini'

                        try {
                            Write-Log "[Get-GPOScriptPaths] Reading: $($file.FullName)"
                            $findings = Parse-ScriptIni -FilePath $file.FullName -GPOName $gpoName -GPOGUID $gpoGUID -Context $context -IsPowerShell $isPowerShell

                            if ($findings) {
                                $linkedOUs = @()
                                if ($gpoLinkage.ContainsKey($gpoGUID)) {
                                    $linkedOUs = $gpoLinkage[$gpoGUID]
                                }

                                foreach ($finding in $findings) {
                                    $finding | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUs -Force
                                    $finding | Add-Member -NotePropertyName 'LinkedOUCount' -NotePropertyValue $linkedOUs.Count -Force
                                }

                                [void]$Script:_gpoScriptFindings.AddRange(@($findings))
                            }
                        } catch {
                            Write-Log "[Get-GPOScriptPaths] Error parsing $($file.FullName): $_"
                        }
                    }
                }
                if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO script paths" -Completed }
            }

            # Retrieve results and clean up Script-scoped temp variables
            $scriptFindings = @($Script:_gpoScriptFindings)
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:_gpoScriptFindings = $null
            $Script:sysvolAccessible = $null

            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                } else {
                    Show-Line "SYSVOL access failed - cannot analyze GPO scripts - SMB access failed (authentication/network issue)" -Class Finding
                }
                return
            }

            if ($scriptFindings.Count -gt 0) {
                Show-Line "Found $($scriptFindings.Count) script(s) distributed via GPO" -Class Hint

                foreach ($finding in $scriptFindings) {
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPOScriptPath' -Force
                    Show-Object $finding
                }
            } else {
                Show-Line "No scripts distributed via GPO" -Class Note
            }

        } catch {
            Write-Log "[Get-GPOScriptPaths] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-GPOScriptPaths] Check completed"
    }
}

# Helper Function: Parse scripts.ini / psscripts.ini
function Parse-ScriptIni {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$FilePath,

        [Parameter(Mandatory=$true)]
        [string]$GPOName,

        [Parameter(Mandatory=$true)]
        [string]$GPOGUID,

        [Parameter(Mandatory=$true)]
        [string]$Context,

        [Parameter(Mandatory=$true)]
        [bool]$IsPowerShell
    )

    try {
        $content = Get-Content -Path $FilePath -ErrorAction Stop
        $findings = @()

        # scripts.ini format:
        # [Startup]       or [Shutdown] (Machine context)
        # [Logon]         or [Logoff]   (User context)
        # 0CmdLine=\\server\share\script.bat
        # 0Parameters=-param1 value1
        # [next section...]

        $currentSection = $null
        $scripts = @{}  # Key: "section_index", Value: @{CmdLine=...; Parameters=...}

        foreach ($line in $content) {
            $trimmed = $line.Trim()

            # Skip empty lines and comments
            if ([string]::IsNullOrEmpty($trimmed) -or $trimmed.StartsWith(';')) {
                continue
            }

            # Section header
            if ($trimmed -match '^\[(.+)\]$') {
                $currentSection = $Matches[1]
                continue
            }

            # Script entry: <index>CmdLine=<path> or <index>Parameters=<args>
            if ($currentSection -and $trimmed -match '^(\d+)(CmdLine|Parameters)\s*=\s*(.*)$') {
                $index = $Matches[1]
                $property = $Matches[2]
                $value = $Matches[3]

                $key = "${currentSection}_${index}"
                if (-not $scripts.ContainsKey($key)) {
                    $scripts[$key] = @{
                        Section = $currentSection
                        Index = $index
                        CmdLine = ''
                        Parameters = ''
                    }
                }
                $scripts[$key][$property] = $value
            }
        }

        # Process collected scripts
        foreach ($entry in $scripts.Values) {
            $cmdLine = $entry.CmdLine
            $parameters = $entry.Parameters
            $section = $entry.Section

            if ([string]::IsNullOrEmpty($cmdLine)) {
                continue
            }

            # Resolve relative paths to full SYSVOL path
            # scripts.ini lives in .../Policies/{GUID}/Machine|User/Scripts/Scripts.ini
            # Relative scripts are stored in .../Policies/{GUID}/Machine|User/Scripts/<Section>/<script>
            if ($cmdLine -notmatch '^\\\\' -and $cmdLine -notmatch '^[A-Za-z]:\\') {
                $scriptsDir = Split-Path $FilePath -Parent
                $cmdLine = Join-Path (Join-Path $scriptsDir $section) $cmdLine
            }

            $fullCommand = if ($parameters) { "$cmdLine $parameters" } else { $cmdLine }

            # Determine script type from section name
            $scriptType = switch ($section) {
                'Startup'  { 'Startup' }
                'Shutdown' { 'Shutdown' }
                'Logon'    { 'Logon' }
                'Logoff'   { 'Logoff' }
                default    { $section }
            }

            # Execution context: Machine startup/shutdown = SYSTEM
            $runsAsSystem = ($Context -eq 'Machine' -and $scriptType -in @('Startup', 'Shutdown'))
            $scriptRunContext = if ($runsAsSystem) { 'SYSTEM' } else { 'User' }

            # Detect UNC paths
            $hasUNCPath = $fullCommand -match '\\\\[^\\]+\\'

            # Detect script type from file extension (always extension-based, even for psscripts.ini)
            $scriptExtension = if ($cmdLine -match '\.(\w+)$') { $Matches[1].ToLower() } else { 'unknown' }
            $scriptLanguage = switch ($scriptExtension) {
                'ps1'  { 'PowerShell' }
                'bat'  { 'Batch' }
                'cmd'  { 'Batch' }
                'vbs'  { 'VBScript' }
                'vbe'  { 'VBScript (Encoded)' }
                'wsf'  { 'Windows Script' }
                'js'   { 'JScript' }
                default { if ($IsPowerShell) { 'PowerShell' } else { 'Unknown' } }
            }

            $finding = [PSCustomObject]@{
                GPOName        = $GPOName
                GPOGUID        = $GPOGUID
                ScriptType     = $scriptType
                ScriptPath     = $cmdLine
                Parameters     = $parameters
                FullCommand    = $fullCommand
                ScriptLanguage = $scriptLanguage
                ExecutionContext = $scriptRunContext
                RunsAsSystem   = $runsAsSystem
                HasUNCPath     = $hasUNCPath
                IsPowerShell   = $IsPowerShell
            }

            $findings += $finding
        }

        return $findings
    } catch {
        Write-Log "[Parse-ScriptIni] Error parsing $FilePath : $_"
        return $null
    }
}



# ----- Get-GPORegistrySettings.ps1 -----

function Get-GPORegistrySettings {
    <#
    .SYNOPSIS
    Detects security-relevant registry values deployed via Group Policy that enable attacks.

    .DESCRIPTION
    Analyzes Group Policy Objects for registry values that, when actively set, enable or
    facilitate credential theft, lateral movement, privilege escalation, or defense evasion.

    Both GPO registry delivery mechanisms are parsed from SYSVOL:
      - Administrative Templates -> Registry.pol  (PReg binary format)
      - Group Policy Preferences -> Registry.xml  (XML format)

    Matched values are defined centrally in adPEAS-RegistryKeys.ps1
    ($Script:DangerousRegistryKeys). Only POSITIVELY SET values are reported - absence of a
    hardening value is never reported as a finding, because GPO parsing cannot distinguish
    "not configured in this GPO" from "secure".

    Examples of detected settings: WDigest cleartext caching, the Zerologon/OneLogon
    VulnerableChannelAllowList, AlwaysInstallElevated, RDP Restricted Admin, UAC disabled,
    Point and Print (PrintNightmare), WSUS-over-HTTP, and explicitly disabled defenses.

    Note: this check sees only what is DEPLOYED via GPO. Values set locally/directly on a
    host (no Remote Registry) are out of scope by design.

    Requires SMB access to \\domain\SYSVOL.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-GPORegistrySettings

    .EXAMPLE
    Get-GPORegistrySettings -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: GPO
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-GPORegistrySettings] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            $Script:_gpoRegMatches = [System.Collections.ArrayList]::new()

            Show-SubHeader "Searching for vulnerable registry settings deployed via GPO..." -ObjectType "GPORegistrySetting"

            $gpos = Get-DomainGPO @PSBoundParameters

            if (-not $gpos) {
                Show-Line "No GPOs found in domain" -Class Note
                return
            }

            $gpoLinkage = Get-GPOLinkage

            # Build GPO GUID to name mapping
            $gpoNameMap = @{}
            foreach ($gpo in $gpos) {
                $gpoNameMap[$gpo.Name] = $gpo.DisplayName
            }

            # Track SYSVOL access status (exception in Clear-SessionState - cleaned up inline below)
            $Script:sysvolAccessible = $false

            # SYSVOL Access with Credential Support
            Invoke-SMBAccess -Description "Scanning GPO registry configuration files" -ScriptBlock {
                $sysvolPath = "\\$($Script:LDAPContext.Server)\SYSVOL\$($Script:LDAPContext.Domain)\Policies"

                if (-not (Test-Path $sysvolPath)) {
                    return
                }

                $Script:sysvolAccessible = $true

                # Single cached SYSVOL listing for both delivery mechanisms
                $regFiles = @(Get-CachedSYSVOLFiles -Filter @("Registry.pol", "Registry.xml"))

                if ($regFiles.Count -eq 0) {
                    Write-Log "[Get-GPORegistrySettings] No Registry.pol/Registry.xml files found in SYSVOL"
                    return
                }

                Write-Log "[Get-GPORegistrySettings] Found $($regFiles.Count) registry configuration file(s)"

                $totalFiles = $regFiles.Count
                $currentIndex = 0
                foreach ($file in $regFiles) {
                    $currentIndex++
                    if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO registry settings" -Current $currentIndex -Total $totalFiles -ObjectName $file.Name }

                    # Extract GPO GUID from path: ...\Policies\{GUID}\...
                    if ($file.FullName -notmatch '\\Policies\\(\{[^}]+\})\\') {
                        continue
                    }
                    $gpoGUID = $Matches[1]
                    $gpoName = if ($gpoNameMap.ContainsKey($gpoGUID)) { $gpoNameMap[$gpoGUID] } else { $gpoGUID }

                    try {
                        $records = @()
                        if ($file.Name -ieq 'Registry.pol') {
                            # Machine\Registry.pol -> HKLM, User\Registry.pol -> HKCU
                            $hive = if ($file.FullName -match '\\Machine\\') { 'HKLM' } else { 'HKCU' }
                            $records = @(Parse-PRegRecords -PolFilePath $file.FullName -Hive $hive)
                            $source = 'Registry.pol'
                        } else {
                            $hive = 'HKLM/HKCU'
                            $records = @(Parse-RegistryXml -XmlFilePath $file.FullName)
                            $source = 'Registry.xml'
                        }
                        if ($records.Count -gt 0) {
                            Write-Log "[Get-GPORegistrySettings] Analyzing GPO '$gpoName' - $source ($hive): $($records.Count) registry value(s)"
                        }

                        foreach ($record in $records) {
                            $entry = Test-DangerousRegistryRecord -Record $record
                            if ($entry) {
                                [void]$Script:_gpoRegMatches.Add([PSCustomObject]@{
                                    GPOGUID = $gpoGUID
                                    GPOName = $gpoName
                                    Source  = $source
                                    Entry   = $entry
                                    Record  = $record
                                })
                            }
                        }
                    } catch {
                        Write-Log "[Get-GPORegistrySettings] Error parsing $($file.FullName): $_"
                    }
                }
                if ($totalFiles -gt $Script:ProgressThreshold) { Show-Progress -Activity "Scanning GPO registry settings" -Completed }
            }

            # Retrieve results and clean up Script-scoped temp variables
            $rawMatches = @($Script:_gpoRegMatches)
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:_gpoRegMatches = $null
            $Script:sysvolAccessible = $null

            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class Hint
                } else {
                    Show-Line "SYSVOL access failed - cannot analyze GPO registry settings - SMB access failed (authentication/network issue)" -Class Finding
                }
                return
            }

            # Resolve findings (handles AlwaysInstallElevated two-hive correlation)
            $findings = @(Resolve-RegistryFindings -RawMatches $rawMatches)

            if ($findings.Count -gt 0) {
                Show-Line "Found $($findings.Count) vulnerable registry setting(s) deployed via GPO" -Class Hint

                foreach ($finding in $findings) {
                    $linkedOUs = @()
                    if ($gpoLinkage.ContainsKey($finding.GPOGUID)) {
                        $linkedOUs = $gpoLinkage[$finding.GPOGUID]
                    }
                    if ($linkedOUs.Count -gt 0) {
                        $finding | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $linkedOUs -Force
                    }
                    $finding | Add-Member -NotePropertyName 'LinkedOUCount' -NotePropertyValue $linkedOUs.Count -Force
                    $finding | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPORegistrySetting' -Force
                    Show-Object $finding
                }
            } else {
                Show-Line "No vulnerable registry settings deployed via GPO" -Class Note
            }

        } catch {
            Write-Log "[Get-GPORegistrySettings] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-GPORegistrySettings] Check completed"
    }
}

# =============================================================================
# Helper: Evaluate one normalized registry record against the dangerous-key table
# =============================================================================
function Test-DangerousRegistryRecord {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Record
    )

    $recKey = ($Record.Key -replace '^\\+', '').TrimEnd('\').ToLower()
    $recValueName = [string]$Record.ValueName
    $recHive = [string]$Record.Hive

    foreach ($entry in $Script:DangerousRegistryKeys) {
        if ($entry.Hive -ne $recHive) { continue }
        if (($entry.Key -replace '^\\+', '').TrimEnd('\').ToLower() -ne $recKey) { continue }
        if ($entry.ValueName.ToLower() -ne $recValueName.ToLower()) { continue }

        # Value name matched - now evaluate the dangerous condition
        $isMatch = $false
        switch ($entry.Match) {
            'Present' {
                $isMatch = $true
            }
            'Equals' {
                if ($null -ne $Record.ValueInt) { $isMatch = ([int64]$Record.ValueInt -eq [int64]$entry.MatchValue) }
            }
            'LessOrEqual' {
                if ($null -ne $Record.ValueInt) { $isMatch = ([int64]$Record.ValueInt -le [int64]$entry.MatchValue) }
            }
            'GreaterThan' {
                if ($null -ne $Record.ValueInt) { $isMatch = ([int64]$Record.ValueInt -gt [int64]$entry.MatchValue) }
            }
            'UrlNotHttps' {
                $sv = [string]$Record.ValueString
                if ($sv -and $sv.Trim().ToLower().StartsWith('http://')) { $isMatch = $true }
            }
        }

        if ($isMatch) {
            return $entry
        }
    }

    return $null
}

# =============================================================================
# Helper: Build display findings from raw matches (AlwaysInstallElevated correlation)
# =============================================================================
function Resolve-RegistryFindings {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [AllowEmptyCollection()]
        [array]$RawMatches
    )

    $findings = @()
    $aieMatches = @()

    foreach ($m in $RawMatches) {
        if ($m.Entry.Id -eq 'AIE_HKLM' -or $m.Entry.Id -eq 'AIE_HKCU') {
            $aieMatches += $m
            continue
        }
        $findings += (New-RegistryFinding -RegMatch $m)
    }

    # AlwaysInstallElevated is only exploitable when BOTH HKLM and HKCU are set to 1
    # within the same GPO. Single-hive matches are suppressed.
    $aieByGpo = $aieMatches | Group-Object -Property GPOGUID
    foreach ($group in $aieByGpo) {
        $ids = @($group.Group | ForEach-Object { $_.Entry.Id } | Sort-Object -Unique)
        if ($ids -contains 'AIE_HKLM' -and $ids -contains 'AIE_HKCU') {
            $hklmMatch = @($group.Group | Where-Object { $_.Entry.Id -eq 'AIE_HKLM' })[0]
            $finding = New-RegistryFinding -RegMatch $hklmMatch
            $finding.RegistryKey = 'HKLM+HKCU\Software\Policies\Microsoft\Windows\Installer\AlwaysInstallElevated'
            $finding.ConfiguredValue = '1 (both HKLM and HKCU)'
            $findings += $finding
        } else {
            Write-Log "[Get-GPORegistrySettings] AlwaysInstallElevated set in only one hive for GPO $($group.Name) - not exploitable, skipping"
        }
    }

    return $findings
}

# =============================================================================
# Helper: Construct a display object for a single match
# =============================================================================
function New-RegistryFinding {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $RegMatch
    )

    $entry = $RegMatch.Entry
    $record = $RegMatch.Record

    # Human-readable configured value
    $configured = '(value present)'
    if ($null -ne $record.ValueInt) {
        $configured = [string]$record.ValueInt
    } elseif ($record.ValueString) {
        $configured = [string]$record.ValueString
    }

    return [PSCustomObject][ordered]@{
        GPOName           = $RegMatch.GPOName
        Source            = $RegMatch.Source
        RegistryKey       = "$($entry.Hive)\$($entry.Key)\$($entry.ValueName)"
        ConfiguredValue   = $configured
        VulnerabilityName = $entry.VulnerabilityName
        RiskReason        = $entry.RiskReason
        Severity          = $entry.Severity
        GPOGUID           = $RegMatch.GPOGUID
    }
}

# =============================================================================
# Parser: Registry.pol (PReg binary format)
# See Parse-PRegRecords in modules/Helpers/Parse-RegistryPol.ps1 (shared with Get-LAPSGPOConfig)
# =============================================================================

# =============================================================================
# Parser: Registry.xml (Group Policy Preferences format)
# =============================================================================
function Parse-RegistryXml {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$XmlFilePath
    )

    $records = @()

    try {
        [xml]$xml = Get-Content -Path $XmlFilePath -ErrorAction Stop

        $regNodes = $xml.SelectNodes("//Registry")
        if (-not $regNodes) { return $records }

        foreach ($node in $regNodes) {
            $props = $node.Properties
            if (-not $props) { continue }

            # Normalize hive
            $hiveRaw = [string]$props.hive
            $hive = $null
            switch -Wildcard ($hiveRaw.ToUpper()) {
                'HKEY_LOCAL_MACHINE*' { $hive = 'HKLM' }
                'HKLM*'               { $hive = 'HKLM' }
                'HKEY_CURRENT_USER*'  { $hive = 'HKCU' }
                'HKCU*'               { $hive = 'HKCU' }
                default               { $hive = $hiveRaw }
            }

            $type = [string]$props.type
            $rawValue = [string]$props.value

            $valueInt = $null
            $valueString = $null
            if ($type -match 'DWORD|QWORD') {
                # GPP stores DWORD/QWORD values as hexadecimal in the XML value attribute
                $parsed = $null
                if ($rawValue -match '^[0-9A-Fa-f]+$') {
                    try { $parsed = [System.Convert]::ToInt64($rawValue, 16) } catch { $parsed = $null }
                }
                if ($null -eq $parsed -and $rawValue -match '^\d+$') {
                    try { $parsed = [System.Convert]::ToInt64($rawValue, 10) } catch { $parsed = $null }
                }
                $valueInt = $parsed
            } else {
                $valueString = $rawValue
            }

            $records += [PSCustomObject]@{
                Hive        = $hive
                Key         = [string]$props.key
                ValueName   = [string]$props.name
                Type        = $type
                ValueInt    = $valueInt
                ValueString = $valueString
            }
        }
    } catch {
        Write-Log "[Read-RegistryXmlRecords] Error parsing $XmlFilePath : $_"
    }

    return $records
}



# ----- Get-ADCSTemplate.ps1 -----

function Get-ADCSTemplate {
    <#
    .SYNOPSIS
    Retrieves AD CS certificate templates with security-relevant analysis for vulnerability detection.

    .DESCRIPTION
    Wrapper around Get-CertificateTemplate (Core module) that adds security-focused computed properties for ESC vulnerability detection:
    - EnrolleeSuppliesSubject (ESC1)
    - ClientAuthentication (ESC1)
    - AnyPurpose (ESC2)
    - EnrollmentAgent (ESC3 condition 1)
    - EnrollmentAgentSignatureRequired (ESC3 condition 2)
    - NoSecurityExtension (ESC9)
    - ManagerApprovalRequired
    - ExportableKey
    - EnrollmentPrincipals

    .PARAMETER Identity
    Specific certificate template name (cn) to query. If not specified, returns all templates.

    .PARAMETER ShowAll
    Include disabled (unpublished) templates. By default only enabled templates are returned.

    .PARAMETER Domain
    Target domain (FQDN). If not specified, uses current domain from session.

    .PARAMETER Server
    Specific Domain Controller to query. If not specified, uses session server.

    .PARAMETER Credential
    PSCredential object for authentication. If not specified, uses session credentials.

    .EXAMPLE
    Get-ADCSTemplate
    Returns all enabled certificate templates with security analysis.

    .EXAMPLE
    Get-ADCSTemplate -ShowAll
    Returns all templates (enabled and disabled).

    .NOTES
    Category: ADCS
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Identity,

        [Parameter(Mandatory=$false)]
        [switch]$ShowAll,

        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ADCSTemplate] Starting certificate template enumeration via Get-CertificateTemplate"
    }

    process {
        try {
            # Build connection parameters (only pass Domain/Server/Credential to Ensure-LDAPConnection)
            $ConnectionParams = @{}
            if ($Domain) { $ConnectionParams['Domain'] = $Domain }
            if ($Server) { $ConnectionParams['Server'] = $Server }
            if ($Credential) { $ConnectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @ConnectionParams)) {
                # Return without output to avoid redundant error display
                return
            }

        # Get templates from Core module (with converted values)
        # Use @PSBoundParameters to pass all parameters directly (simple module, no inner functions)
        # Core module handles all LDAP attribute conversion (pKIExpirationPeriod, flags, etc.)
        $templateResults = @(Get-CertificateTemplate @PSBoundParameters)

        # Check if query failed (auth error, network issue, etc.)
        $queryError = $templateResults | Where-Object { $_._QueryError -eq $true }
        if ($queryError) {
            Write-Log "[Get-ADCSTemplate] Get-CertificateTemplate returned error: $($queryError.ErrorMessage)"
            # Pass through the error marker so caller can handle it
            return $queryError
        }

        # Filter out any error markers (should be none at this point)
        $templates = @($templateResults | Where-Object { $_._QueryError -ne $true })

        if (@($templates).Count -eq 0) {
            Write-Log "[Get-ADCSTemplate] No templates returned from Get-CertificateTemplate"
            return
        }

        Write-Log "[Get-ADCSTemplate] Processing $($templates.Count) template(s) for security analysis"

        $totalTemplates = @($templates).Count
        $currentIndex = 0
        foreach ($coreTemplate in $templates) {
            $currentIndex++
            if ($totalTemplates -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing certificate templates" -Current $currentIndex -Total $totalTemplates -ObjectName $coreTemplate.displayName }
            # Build enhanced template object with security-relevant properties
            # Core module already converted all values - we just restructure and add computed properties
            $template = [PSCustomObject]@{
                # Basic identification (from Core)
                Name = $coreTemplate.cn
                DisplayName = $coreTemplate.displayName
                DistinguishedName = $coreTemplate.distinguishedName

                # CA publishing info: which CAs have this template enabled (from Core)
                PublishedOn = if ($coreTemplate.PublishedOn) { @($coreTemplate.PublishedOn) } else { @() }

                # Schema Version (from Core)
                SchemaVersion = if ($coreTemplate.'msPKI-Template-Schema-Version') {
                    [int]$coreTemplate.'msPKI-Template-Schema-Version'
                } else { 1 }

                # Flags for security analysis - Core converts to string arrays like @('ENROLLEE_SUPPLIES_SUBJECT')
                # We keep original values for display AND extract raw integers for bitwise operations
                CertificateNameFlagDisplay = $coreTemplate.'msPKI-Certificate-Name-Flag'
                EnrollmentFlagDisplay = $coreTemplate.'msPKI-Enrollment-Flag'
                PrivateKeyFlagDisplay = $coreTemplate.'msPKI-Private-Key-Flag'

                # Signatures required (from Core)
                RASignatureCount = if ($coreTemplate.'msPKI-RA-Signature') {
                    [int]$coreTemplate.'msPKI-RA-Signature'
                } else { 0 }
                RAApplicationPolicies = if ($coreTemplate.'msPKI-RA-Application-Policies') {
                    @($coreTemplate.'msPKI-RA-Application-Policies')
                } else { @() }

                # EKUs (from Core - may include friendly names like "Client Authentication (1.3.6.1.5.5.7.3.2)")
                ExtendedKeyUsage = if ($coreTemplate.pKIExtendedKeyUsage) {
                    @($coreTemplate.pKIExtendedKeyUsage)
                } else { @() }
                ApplicationPolicies = if ($coreTemplate.'msPKI-Certificate-Application-Policy') {
                    @($coreTemplate.'msPKI-Certificate-Application-Policy')
                } else { @() }

                # Key settings (from Core)
                MinimalKeySize = if ($coreTemplate.'msPKI-Minimal-Key-Size') {
                    [int]$coreTemplate.'msPKI-Minimal-Key-Size'
                } else { 0 }

                # Validity Period (already converted by Core to "2 year(s)", "90 day(s)", etc.)
                ValidityPeriod = if ($coreTemplate.pKIExpirationPeriod) {
                    $coreTemplate.pKIExpirationPeriod
                } else { "Unknown" }

                # Certificate Policies (issuance policy OIDs - needed for ESC13 detection)
                CertificatePolicies = if ($coreTemplate.'msPKI-Certificate-Policy') {
                    @($coreTemplate.'msPKI-Certificate-Policy')
                } else { @() }

                # Security Descriptor (from Core - for enrollment permissions parsing)
                SecurityDescriptor = $coreTemplate.nTSecurityDescriptor
            }

            # ===== Computed Security Properties (Check module logic) =====
            # Parse flags from converted string arrays (e.g., @('ENROLLEE_SUPPLIES_SUBJECT', 'SUBJECT_ALT_REQUIRE_UPN'))
            $certNameFlags = $template.CertificateNameFlagDisplay
            $enrollFlags = $template.EnrollmentFlagDisplay
            $privKeyFlags = $template.PrivateKeyFlagDisplay

            # EnrolleeSuppliesSubject (CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT)
            $template | Add-Member -NotePropertyName 'EnrolleeSuppliesSubject' -NotePropertyValue (
                ($certNameFlags -contains 'ENROLLEE_SUPPLIES_SUBJECT') -or
                ($certNameFlags -match 'ENROLLEE_SUPPLIES_SUBJECT')
            )

            # NoSecurityExtension (CT_FLAG_NO_SECURITY_EXTENSION)
            $template | Add-Member -NotePropertyName 'NoSecurityExtension' -NotePropertyValue (
                ($enrollFlags -contains 'NO_SECURITY_EXTENSION') -or
                ($enrollFlags -match 'NO_SECURITY_EXTENSION')
            )

            # Combine EKUs for analysis (Core may add friendly names, so match on OID)
            $allEKUs = @($template.ExtendedKeyUsage) + @($template.ApplicationPolicies) | Where-Object { $_ } | Select-Object -Unique
            $ekuString = $allEKUs -join ' '

            # ClientAuthentication - can be used for Kerberos auth
            $template | Add-Member -NotePropertyName 'ClientAuthentication' -NotePropertyValue (
                ($ekuString -match '1\.3\.6\.1\.5\.5\.7\.3\.2') -or      # Client Authentication
                ($ekuString -match '1\.3\.6\.1\.4\.1\.311\.20\.2\.2') -or # Smart Card Logon
                ($ekuString -match '2\.5\.29\.37\.0') -or                 # Any Purpose
                ($allEKUs.Count -eq 0)                                    # No EKUs = Any Purpose
            )

            # AnyPurpose EKU
            $template | Add-Member -NotePropertyName 'AnyPurpose' -NotePropertyValue (
                ($ekuString -match '2\.5\.29\.37\.0') -or ($allEKUs.Count -eq 0)
            )

            # EnrollmentAgent (Certificate Request Agent EKU)
            # ESC3 condition 1: the certificate issued FROM this template is an enrollment agent
            # certificate and can be used to co-sign requests on behalf of other principals.
            $template | Add-Member -NotePropertyName 'EnrollmentAgent' -NotePropertyValue (
                $ekuString -match '1\.3\.6\.1\.4\.1\.311\.20\.2\.1'
            )

            # EnrollmentAgentSignatureRequired (ESC3 condition 2)
            # The inverse of EnrollmentAgent: this template can only be issued when the request is
            # co-signed by a certificate carrying the Certificate Request Agent application policy.
            # Such a template is the TARGET of an "enroll on behalf of" attack - the agent picks the
            # subject, so client-auth templates of this kind are a full impersonation primitive.
            # RAApplicationPolicies carries friendly names ("Certificate Request Agent (Enrollment
            # Agent) (1.3.6.1.4.1.311.20.2.1)"), so match on the OID rather than on the name.
            $raPolicyString = @($template.RAApplicationPolicies) -join ' '
            $template | Add-Member -NotePropertyName 'EnrollmentAgentSignatureRequired' -NotePropertyValue (
                ($template.RASignatureCount -ge 1) -and ($raPolicyString -match '1\.3\.6\.1\.4\.1\.311\.20\.2\.1')
            )

            # ManagerApprovalRequired (PEND_ALL_REQUESTS)
            $template | Add-Member -NotePropertyName 'ManagerApprovalRequired' -NotePropertyValue (
                ($enrollFlags -contains 'PEND_ALL_REQUESTS') -or
                ($enrollFlags -match 'PEND_ALL_REQUESTS')
            )

            # ExportableKey (CT_FLAG_EXPORTABLE_KEY)
            $template | Add-Member -NotePropertyName 'ExportableKey' -NotePropertyValue (
                ($privKeyFlags -contains 'EXPORTABLE_KEY') -or
                ($privKeyFlags -match 'EXPORTABLE_KEY')
            )

            # Parse enrollment permissions from Security Descriptor
            # nTSecurityDescriptor is now a unified object with ACEs array
            $enrollmentPrincipals = @()
            $enrollmentPrincipalSIDs = @()

            # Access ACEs from the unified nTSecurityDescriptor structure
            $sdACEs = if ($coreTemplate.nTSecurityDescriptor -and $coreTemplate.nTSecurityDescriptor.ACEs) {
                $coreTemplate.nTSecurityDescriptor.ACEs
            } else {
                @()
            }

            if (@($sdACEs).Count -gt 0) {
                # Use structured ACEs (includes SIDs directly from SD)
                foreach ($ace in $sdACEs) {
                    # Only Allow ACEs
                    if ($ace.Type -ne 'Allow') { continue }

                    # Check for enrollment rights
                    $hasEnroll = $false
                    if ($ace.Rights -match 'ExtendedRight' -or $ace.Rights -match 'GenericAll') {
                        # Check if ExtendedRight is for Certificate-Enrollment or Certificate-AutoEnrollment
                        if ($ace.Rights -match 'GenericAll' -or
                            $ace.RightsDisplay -match 'Certificate-Enrollment' -or
                            $ace.RightsDisplay -match 'Certificate-AutoEnrollment' -or
                            $ace.RightsDisplay -match 'All-Extended-Rights') {
                            $hasEnroll = $true
                        }
                    }

                    if ($hasEnroll -and $ace.Name -and $enrollmentPrincipals -notcontains $ace.Name) {
                        $enrollmentPrincipals += $ace.Name
                        if ($ace.SID) {
                            $enrollmentPrincipalSIDs += $ace.SID
                        }
                    }
                }
            }
            $template | Add-Member -NotePropertyName 'EnrollmentPrincipals' -NotePropertyValue $enrollmentPrincipals
            $template | Add-Member -NotePropertyName 'EnrollmentPrincipalSIDs' -NotePropertyValue $enrollmentPrincipalSIDs

            # Parse write/modify permissions from Security Descriptor (for informational display)
            # These rights allow modifying the template itself (relevant for ESC4 context)
            $templateACL = @()
            $writeRights = @('GenericAll', 'GenericWrite', 'WriteDacl', 'WriteOwner')

            if (@($sdACEs).Count -gt 0) {
                $seenSIDs = @{}
                foreach ($ace in $sdACEs) {
                    if ($ace.Type -ne 'Allow') { continue }
                    if (-not $ace.SID) { continue }

                    # Check for write/modify rights
                    $hasWriteRight = $false
                    $matchedRight = ""

                    foreach ($right in $writeRights) {
                        if ($ace.Rights -match $right) {
                            $hasWriteRight = $true
                            $matchedRight = $right
                            break
                        }
                    }

                    # WriteProperty on all properties (empty ObjectType = all properties)
                    if (-not $hasWriteRight -and $ace.Rights -match 'WriteProperty') {
                        if (-not $ace.ObjectType) {
                            $hasWriteRight = $true
                            $matchedRight = "WriteProperty"
                        }
                    }

                    if (-not $hasWriteRight) { continue }

                    # Deduplicate by SID+right combination
                    $dedupeKey = "$($ace.SID)|$matchedRight"
                    if ($seenSIDs.ContainsKey($dedupeKey)) { continue }
                    $seenSIDs[$dedupeKey] = $true

                    $templateACL += [PSCustomObject]@{
                        Identity = if ($ace.Name) { $ace.Name } else { $ace.SID }
                        SID      = $ace.SID
                        Right    = $matchedRight
                    }
                }
            }

            # Add owner as well if not already covered by a write ACE
            if ($coreTemplate.nTSecurityDescriptor -and $coreTemplate.nTSecurityDescriptor.Owner) {
                $ownerSID  = $coreTemplate.nTSecurityDescriptor.Owner.SID
                $ownerName = $coreTemplate.nTSecurityDescriptor.Owner.Name
                if ($ownerSID -and -not ($templateACL | Where-Object { $_.SID -eq $ownerSID -and $_.Right -eq 'Owner' })) {
                    $templateACL += [PSCustomObject]@{
                        Identity = if ($ownerName) { $ownerName } else { $ownerSID }
                        SID      = $ownerSID
                        Right    = 'Owner'
                    }
                }
            }

            $template | Add-Member -NotePropertyName 'TemplateACL' -NotePropertyValue $templateACL

            Write-Output $template
        }
        if ($totalTemplates -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing certificate templates" -Completed }

        } catch {
            Write-Log "[Get-ADCSTemplate] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ADCSTemplate] Enumeration complete"
    }
}



# ----- Get-ADCSVulnerabilities.ps1 -----

function Get-ADCSVulnerabilities {
    <#
    .SYNOPSIS
    Detects Active Directory Certificate Services (AD CS) misconfigurations and vulnerabilities.

    .DESCRIPTION
    Enumerates AD CS certificate templates, Certificate Authorities, and PKI trust infrastructure to identify common security misconfigurations that could lead to privilege escalation.

    Checks for:
    - PKI Trust Infrastructure: Root CAs, NTAuth Store, AIA CAs
    - CA Certificate Security: Weak algorithms, short keys, expired certificates
    - ESC1: Client Authentication + Enrollee-Supplied Subject
    - ESC2: Any Purpose EKU
    - ESC3: Certificate Request Agent EKU (condition 1) and on-behalf-of target templates (condition 2)
    - ESC4: Dangerous Template Permissions
    - ESC5: Vulnerable PKI Container Permissions
    - ESC9: No Security Extension + Client Authentication
    - ESC13: Issuance Policy Linked to AD Group
    - ESC15: Schema v1 + Enrollee-Supplied Subject (CVE-2024-49019)
    - Dangerous AD object permissions on Certificate Authorities

    .PARAMETER Domain
    Target domain (FQDN). If not specified, uses current domain from session.

    .PARAMETER Server
    Specific Domain Controller to query. If not specified, uses session server.

    .PARAMETER Credential
    PSCredential object for authentication. If not specified, uses session credentials.

    .PARAMETER IncludePrivileged
    Include privileged accounts (Domain Admin members) in dangerous permissions output.
    By default, accounts that are members of Domain Admins/Enterprise Admins are not shown in ESC4 findings since they already have admin rights.
    Use this switch to display them as well (shown in yellow instead of red).

    .EXAMPLE
    Get-ADCSVulnerabilities
    Performs AD CS security analysis using current session.

    .EXAMPLE
    Get-ADCSVulnerabilities -Domain "contoso.com" -Credential (Get-Credential)
    Performs AD CS security analysis with explicit credentials.

    .EXAMPLE
    Get-ADCSVulnerabilities -IncludePrivileged
    Performs AD CS security analysis and includes privileged accounts in dangerous permissions.

    .NOTES
    Category: ADCS
    Author: Alexander Sturz (@_61106960_)
    Based on Certipy by @ly4k (https://github.com/ly4k/Certipy)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged
    )

    begin {
        # Helper function: Check if ALL enrollment principals are truly privileged
        # Uses central Test-IsPrivileged function from adPEAS-SIDs.ps1
        # "Truly privileged" = Category 'Privileged' (NOT Operator, NOT BroadGroup)
        # Uses SIDs when available (more reliable), falls back to names
        function Test-AllEnrollmentPrivileged {
            param(
                [string[]]$EnrollmentPrincipalSIDs,
                [string[]]$EnrollmentPrincipals,
                [hashtable]$CredParams = @{}
            )

            if (-not $EnrollmentPrincipals -or @($EnrollmentPrincipals).Count -eq 0) {
                # No enrollment principals = everyone can enroll = NOT privileged
                return $false
            }

            # Check each principal - use SID if available at same index, otherwise use name
            for ($i = 0; $i -lt $EnrollmentPrincipals.Count; $i++) {
                $principalName = $EnrollmentPrincipals[$i]
                $principalSID = if ($EnrollmentPrincipalSIDs -and $i -lt $EnrollmentPrincipalSIDs.Count) {
                    $EnrollmentPrincipalSIDs[$i]
                } else {
                    $null
                }

                # Use SID if available (more reliable), otherwise use name
                $identity = if ($principalSID) { $principalSID } else { $principalName }

                Write-Log "[Test-AllEnrollmentPrivileged] Checking: $principalName (SID: $principalSID, using: $identity)"

                # Use central Test-IsPrivileged function
                $result = Test-IsPrivileged -Identity $identity

                # Only Category 'Privileged' counts as truly privileged
                # Operators, BroadGroups, Standard, and Unknown are NOT privileged for enrollment purposes
                if ($result.Category -ne 'Privileged') {
                    Write-Log "[Test-AllEnrollmentPrivileged] Found non-privileged: $principalName (Category: $($result.Category), Reason: $($result.Reason))"
                    return $false
                }

                Write-Log "[Test-AllEnrollmentPrivileged] Privileged: $principalName (Category: $($result.Category))"
            }

            # All principals are truly privileged
            Write-Log "[Test-AllEnrollmentPrivileged] All enrollment principals are truly privileged"
            return $true
        }
    }

    process {
        # Build credential parameters for inner functions and DirectoryEntry calls (Pattern B)
        # MUST be defined BEFORE Ensure-LDAPConnection call!
        $CredParams = @{}
        if ($PSBoundParameters.ContainsKey('Domain')) { $CredParams['Domain'] = $Domain }
        if ($PSBoundParameters.ContainsKey('Server')) { $CredParams['Server'] = $Server }
        if ($PSBoundParameters.ContainsKey('Credential')) { $CredParams['Credential'] = $Credential }

        # Ensure LDAP connection (displays error if needed)
        if (-not (Ensure-LDAPConnection @CredParams)) {
            # Return without output to avoid redundant error display
            return
        }

        try {
            # Step 0: PKI Trust Infrastructure Overview (Root CAs, NTAuth Store)
            $configNC = $Script:LDAPContext.ConfigurationNamingContext
            Show-SubHeader "Checking PKI trust infrastructure..." -ObjectType "PKIInfrastructure"

            # --- Root CAs (trusted root certificates in AD) ---
            try {
                $rootCASearchBase = "CN=Certification Authorities,CN=Public Key Services,CN=Services,$configNC"
                $rootCAs = @(Invoke-LDAPSearch -Filter "(objectClass=certificationAuthority)" -SearchBase $rootCASearchBase -Properties 'cn','distinguishedName','cACertificate' -Scope OneLevel)

                if (@($rootCAs).Count -gt 0) {
                    Show-Line "Found $(@($rootCAs).Count) trusted Root CA(s) in AD configuration" -Class Note

                    foreach ($rootCA in $rootCAs) {
                        $rootCAName = if ($rootCA.cn -is [array]) { $rootCA.cn[0] } else { $rootCA.cn }
                        $rootCert = $rootCA.cACertificate
                        if ($rootCert -is [array]) { $rootCert = $rootCert[0] }

                        $rootCAObj = [PSCustomObject]@{
                            Name                   = $rootCAName
                            Subject                = if ($rootCert.SubjectFull) { $rootCert.SubjectFull } else { $rootCAName }
                            Issuer                 = if ($rootCert.IssuerFull) { $rootCert.IssuerFull } elseif ($rootCert.Issuer) { $rootCert.Issuer } else { $null }
                            SerialNumber           = if ($rootCert.SerialNumber) { $rootCert.SerialNumber } else { $null }
                            Thumbprint             = if ($rootCert.Thumbprint) { $rootCert.Thumbprint } else { "Unknown" }
                            Validity               = if ($rootCert.NotAfter) { "$($rootCert.NotBefore.ToString('yyyy-MM-dd')) to $($rootCert.NotAfter.ToString('yyyy-MM-dd'))" } else { "Unknown" }
                            Status                 = if ($rootCert.Status) { $rootCert.Status } else { "Unknown" }
                            SignatureAlgorithm     = if ($rootCert.SignatureAlgorithm) { $rootCert.SignatureAlgorithm } else { "Unknown" }
                            KeySize                = if ($rootCert.PublicKeyLength -and $rootCert.PublicKeyLength -gt 0) { "$($rootCert.PublicKeyLength) bit" } else { "Unknown" }
                            HasBasicConstraints    = if ($null -ne $rootCert.HasBasicConstraints) { $rootCert.HasBasicConstraints } else { $null }
                            CRLDistributionPoints  = if ($rootCert.CRLDistributionPoints -and @($rootCert.CRLDistributionPoints).Count -gt 0) { $rootCert.CRLDistributionPoints } else { $null }
                            OCSPURLs               = if ($rootCert.OCSPURLs -and @($rootCert.OCSPURLs).Count -gt 0) { $rootCert.OCSPURLs } else { $null }
                            AIAURLs                = if ($rootCert.AIAURLs -and @($rootCert.AIAURLs).Count -gt 0) { $rootCert.AIAURLs } else { $null }
                        }
                        $rootCAObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'RootCA' -Force
                        Show-Object $rootCAObj
                    }
                } else {
                    Show-Line "No trusted Root CAs found in AD configuration" -Class Note
                }
            }
            catch {
                Write-Log "[Get-ADCSVulnerabilities] Error querying Root CAs: $_" -Level Warning
            }

            # --- NTAuth Store (certificates trusted for domain authentication / PKINIT) ---
            try {
                $ntAuthSearchBase = "CN=Public Key Services,CN=Services,$configNC"
                $ntAuthResults = @(Invoke-LDAPSearch -Filter "(cn=NTAuthCertificates)" -SearchBase $ntAuthSearchBase -Properties 'cn','cACertificate' -Scope OneLevel)

                if (@($ntAuthResults).Count -gt 0) {
                    $ntAuthObj = $ntAuthResults[0]
                    $ntAuthCerts = $ntAuthObj.cACertificate

                    # cACertificate may be single object or array of objects
                    $certList = @()
                    if ($ntAuthCerts -is [array]) {
                        $certList = @($ntAuthCerts)
                    } elseif ($ntAuthCerts) {
                        $certList = @($ntAuthCerts)
                    }

                    if (@($certList).Count -gt 0) {
                        Show-Line "NTAuth Store contains $(@($certList).Count) certificate(s) trusted for domain authentication (PKINIT)" -Class Note
                        foreach ($ntCert in $certList) {
                            if ($ntCert -and $ntCert.Subject) {
                                # Extract CN from Subject for title display (e.g. "CN=Contoso-CA, DC=..." -> "Contoso-CA")
                                $ntCertSubject = if ($ntCert.SubjectFull) { $ntCert.SubjectFull } elseif ($ntCert.Subject) { $ntCert.Subject } else { "" }
                                $ntCertName = if ($ntCertSubject -match '^CN=([^,]+)') { $Matches[1] } else { "Unknown" }

                                $ntAuthCertObj = [PSCustomObject]@{
                                    Name                   = $ntCertName
                                    Subject                = if ($ntCertSubject) { $ntCertSubject } else { "Unknown" }
                                    Issuer                 = if ($ntCert.IssuerFull) { $ntCert.IssuerFull } elseif ($ntCert.Issuer) { $ntCert.Issuer } else { "Unknown" }
                                    SerialNumber           = if ($ntCert.SerialNumber) { $ntCert.SerialNumber } else { $null }
                                    Thumbprint             = if ($ntCert.Thumbprint) { $ntCert.Thumbprint } else { "Unknown" }
                                    Validity               = if ($ntCert.NotAfter) { "$($ntCert.NotBefore.ToString('yyyy-MM-dd')) to $($ntCert.NotAfter.ToString('yyyy-MM-dd'))" } else { "Unknown" }
                                    Status                 = if ($ntCert.Status) { $ntCert.Status } else { "Unknown" }
                                    SignatureAlgorithm     = if ($ntCert.SignatureAlgorithm) { $ntCert.SignatureAlgorithm } else { "Unknown" }
                                    KeySize                = if ($ntCert.PublicKeyLength -and $ntCert.PublicKeyLength -gt 0) { "$($ntCert.PublicKeyLength) bit" } else { "Unknown" }
                                    HasBasicConstraints    = if ($null -ne $ntCert.HasBasicConstraints) { $ntCert.HasBasicConstraints } else { $null }
                                    CRLDistributionPoints  = if ($ntCert.CRLDistributionPoints -and @($ntCert.CRLDistributionPoints).Count -gt 0) { $ntCert.CRLDistributionPoints } else { $null }
                                    OCSPURLs               = if ($ntCert.OCSPURLs -and @($ntCert.OCSPURLs).Count -gt 0) { $ntCert.OCSPURLs } else { $null }
                                    AIAURLs                = if ($ntCert.AIAURLs -and @($ntCert.AIAURLs).Count -gt 0) { $ntCert.AIAURLs } else { $null }
                                }
                                $ntAuthCertObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'NTAuthCertificate' -Force
                                Show-Object $ntAuthCertObj
                            }
                        }
                    } else {
                        Show-Line "NTAuth Store exists but contains no certificates" -Class Hint
                    }
                } else {
                    Show-Line "No NTAuth Store found - PKINIT certificate authentication may not be configured" -Class Note
                }
            }
            catch {
                Write-Log "[Get-ADCSVulnerabilities] Error querying NTAuth Store: $_" -Level Warning
            }

            # --- AIA CAs (Authority Information Access) ---
            try {
                $aiaSearchBase = "CN=AIA,CN=Public Key Services,CN=Services,$configNC"
                $aiaCAs = @(Invoke-LDAPSearch -Filter "(objectClass=certificationAuthority)" -SearchBase $aiaSearchBase -Properties 'cn','distinguishedName','cACertificate' -Scope OneLevel)

                if (@($aiaCAs).Count -gt 0) {
                    Show-Line "Found $(@($aiaCAs).Count) AIA (Authority Information Access) CA(s)" -Class Note
                    foreach ($aiaCA in $aiaCAs) {
                        $aiaCAName = if ($aiaCA.cn -is [array]) { $aiaCA.cn[0] } else { $aiaCA.cn }
                        $aiaCert = $aiaCA.cACertificate
                        if ($aiaCert -is [array]) { $aiaCert = $aiaCert[0] }

                        $aiaCAObj = [PSCustomObject]@{
                            Name                   = $aiaCAName
                            Subject                = if ($aiaCert -and $aiaCert.SubjectFull) { $aiaCert.SubjectFull } elseif ($aiaCert -and $aiaCert.Subject) { $aiaCert.Subject } else { $aiaCAName }
                            Issuer                 = if ($aiaCert -and $aiaCert.IssuerFull) { $aiaCert.IssuerFull } elseif ($aiaCert -and $aiaCert.Issuer) { $aiaCert.Issuer } else { "Unknown" }
                            SerialNumber           = if ($aiaCert -and $aiaCert.SerialNumber) { $aiaCert.SerialNumber } else { $null }
                            Thumbprint             = if ($aiaCert.Thumbprint) { $aiaCert.Thumbprint } else { "Unknown" }
                            Validity               = if ($aiaCert.NotAfter) { "$($aiaCert.NotBefore.ToString('yyyy-MM-dd')) to $($aiaCert.NotAfter.ToString('yyyy-MM-dd'))" } else { "Unknown" }
                            Status                 = if ($aiaCert.Status) { $aiaCert.Status } else { "Unknown" }
                            SignatureAlgorithm     = if ($aiaCert.SignatureAlgorithm) { $aiaCert.SignatureAlgorithm } else { "Unknown" }
                            KeySize                = if ($aiaCert.PublicKeyLength -and $aiaCert.PublicKeyLength -gt 0) { "$($aiaCert.PublicKeyLength) bit" } else { "Unknown" }
                            HasBasicConstraints    = if ($aiaCert -and $null -ne $aiaCert.HasBasicConstraints) { $aiaCert.HasBasicConstraints } else { $null }
                            CRLDistributionPoints  = if ($aiaCert -and $aiaCert.CRLDistributionPoints -and @($aiaCert.CRLDistributionPoints).Count -gt 0) { $aiaCert.CRLDistributionPoints } else { $null }
                            OCSPURLs               = if ($aiaCert -and $aiaCert.OCSPURLs -and @($aiaCert.OCSPURLs).Count -gt 0) { $aiaCert.OCSPURLs } else { $null }
                            AIAURLs                = if ($aiaCert -and $aiaCert.AIAURLs -and @($aiaCert.AIAURLs).Count -gt 0) { $aiaCert.AIAURLs } else { $null }
                        }
                        $aiaCAObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'AIACA' -Force
                        Show-Object $aiaCAObj
                    }
                }
            }
            catch {
                Write-Log "[Get-ADCSVulnerabilities] Error querying AIA CAs: $_" -Level Warning
            }

            # Step 1: Enumerate Certificate Authorities (Infrastructure)
            Show-SubHeader "Searching for AD CS Infrastructure..." -ObjectType "CertificateAuthority"
            $caResults = @(Get-CertificateAuthority @CredParams)

            # Check if query failed (auth error, network issue, etc.)
            $queryError = $caResults | Where-Object { $_._QueryError -eq $true }
            if ($queryError) {
                Write-Log "[Get-ADCSVulnerabilities] CA query failed: $($queryError.ErrorMessage)"
                Show-Line "Failed to query Certificate Authorities - LDAP query failed (authentication/network issue)" -Class Finding
                return
            }

            # Filter out any error markers (should be none at this point)
            $cas = @($caResults | Where-Object { $_._QueryError -ne $true })

            if (@($cas).Count -eq 0) {
                Show-Line "No Certificate Authorities found - AD CS not deployed" -Class Note
                return
            }

            # Display CA count immediately after search
            Show-Line "Found $($cas.Count) Certificate Authority(s)" -Class Hint

            # Track CA vulnerabilities for summary
            $caVulnerabilityCount = 0

            # Display CA details
            foreach ($ca in $cas) {
                # ===== Web Enrollment Detection (ESC8 Infrastructure Check) =====
                # Check HTTP/HTTPS availability and authentication methods
                # This does NOT determine ESC8 vulnerability itself (requires manual verification)
                # but provides useful infrastructure information for the tester
                $webEnrollmentResult = $null

                if ($ca.DNSHostName) {
                    # Get the CA computer object to check activity
                    # Escape for LDAP filter to prevent injection (RFC 4515)
                    $escapedDnsHostName = Escape-LDAPFilterValue -Value $ca.DNSHostName
                    $caComputer = @(Get-DomainComputer -LDAPFilter "(dNSHostName=$escapedDnsHostName)" @CredParams)[0]

                    # Determine if CA server is inactive (skip HTTP check for inactive servers)
                    $skipHttpCheck = $false
                    if ($caComputer) {
                        $isInactive = $null -ne ($caComputer | Test-AccountActivity -IsInactive)
                        if ($isInactive) {
                            Write-Log "[Get-ADCSVulnerabilities] Skipping HTTP check for $($ca.DNSHostName) - CA server inactive"
                            $skipHttpCheck = $true
                        }
                    }
                    # No computer object (cross-domain) - still attempt HTTP check since we have the hostname

                    if (-not $skipHttpCheck) {
                        Write-Log "[Get-ADCSVulnerabilities] Checking web enrollment for $($ca.DNSHostName) (CA: $($ca.Name))..."

                        try {
                            # Pass CA name for CES endpoint detection
                            # The CES URL pattern is: https://<hostname>/<CAName>_CES_<AuthType>/service.svc
                            $webEnrollmentResult = Invoke-HTTPRequest -ScanADCS -Uri $ca.DNSHostName -CAName $ca.Name -TestEPA
                            if ($webEnrollmentResult.Success) {
                                Write-Log "[Get-ADCSVulnerabilities] Web enrollment check successful for $($ca.DNSHostName)"
                                if ($null -ne $webEnrollmentResult.EPAEnabled) {
                                    Write-Log "[Get-ADCSVulnerabilities] EPA detection: Enabled=$($webEnrollmentResult.EPAEnabled), Confidence=$($webEnrollmentResult.EPAConfidence)"
                                }
                            }
                        }
                        catch {
                            Write-Log "[Get-ADCSVulnerabilities] Web enrollment check failed: $_"
                        }
                    }
                }

                # ===== ESC7: NOT IMPLEMENTED VIA LDAP =====
                # IMPORTANT: ESC7 (ManageCA/ManageCertificates permissions) CANNOT be detected via LDAP!
                # The CA security permissions are stored in the CA's registry, not in Active Directory.
                # The AD object (pKIEnrollmentService) only contains Enrollment permissions.
                #
                # To check ESC7, you need:
                # - Direct access to the CA server (ICertAdmin2 COM interface)
                # - Or use tools like Certify.exe, Certipy, or certsrv.msc
                #
                # What we CAN check via LDAP on the AD object:
                # - GenericAll, WriteDacl, WriteOwner on the pKIEnrollmentService object (allows modifying CA enrollment settings)
                # - These are NOT the same as ManageCA/ManageCertificates!

                $dangerousACEs = @()
                try {
                    # CA objects live in the Configuration partition - use Invoke-LDAPSearch with
                    # the CA's own DN as SearchBase and Base scope. Get-DomainObject searches the
                    # domain partition and returns 0 results for Configuration partition DNs.
                    $caSDObj = @(Invoke-LDAPSearch -Filter "(objectClass=*)" -SearchBase $ca.DistinguishedName -Properties 'nTSecurityDescriptor' -Raw -Scope Base)[0]
                    $securityDescriptor = $null
                    if ($caSDObj -and $caSDObj.nTSecurityDescriptor) {
                        $securityDescriptor = New-Object System.DirectoryServices.ActiveDirectorySecurity
                        $securityDescriptor.SetSecurityDescriptorBinaryForm($caSDObj.nTSecurityDescriptor)
                    }

                    if ($securityDescriptor) {
                        $dacl = $securityDescriptor.GetAccessRules($true, $false, [System.Security.Principal.SecurityIdentifier])

                        # Only check for dangerous AD object permissions (NOT CA permissions!)
                        # These allow modifying the CA's AD enrollment configuration
                        # Uses central $Script:GenericDangerousRights from adPEAS-GUIDs.ps1

                        foreach ($ace in $dacl) {
                            if ($ace.AccessControlType -ne 'Allow') { continue }

                            $aceSID = $ace.IdentityReference.Value
                            $aceRights = $ace.ActiveDirectoryRights.ToString()

                            $hasDangerousRight = $false
                            $matchedRight = ""

                            # Check generic dangerous rights on the AD object
                            foreach ($right in $Script:GenericDangerousRights) {
                                if ($aceRights -match $right) {
                                    $hasDangerousRight = $true
                                    $matchedRight = $right
                                    break
                                }
                            }

                            # Note: ExtendedRight with GUID 0e10c968-... is Certificate-Enrollment, NOT ManageCA!
                            # ManageCA/ManageCertificates are CA-level permissions stored in registry, not AD.
                            # We skip ExtendedRights here as Enroll is expected for most principals.

                            if (-not $hasDangerousRight) { continue }

                            $identityName = ConvertFrom-SID -SID $aceSID

                            # Use scope-based check for ADCS enrollment permissions
                            $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'ADCSEnroll' -ReturnDetails

                            if ($scopeResult.Severity -eq 'Expected') {
                                Write-Log "[Get-ADCSVulnerabilities] Expected identity $aceSID has $aceRights on CA $($ca.Name)"
                                continue
                            }

                            # Check if identity is privileged (includes Domain Controllers via group membership)
                            # Test-IsPrivileged checks static SIDs, RID suffixes, AND recursive group membership
                            $privCheck = Test-IsPrivileged -Identity $aceSID
                            if ($privCheck.IsPrivileged -eq $true) {
                                Write-Log "[Get-ADCSVulnerabilities] Privileged identity $identityName ($($privCheck.Category): $($privCheck.Reason)) has $aceRights on CA $($ca.Name) - expected"
                                continue
                            }

                            # Additional check: Is this the CA server itself? (CA computer account has rights on its own AD object)
                            # This is expected behavior - the CA needs to manage its own configuration
                            if ($identityName -and $ca.DNSHostName) {
                                $caComputerName = ($ca.DNSHostName -split '\.')[0]
                                if ($identityName -match "\\$caComputerName`$" -or $identityName -eq "$caComputerName`$") {
                                    Write-Log "[Get-ADCSVulnerabilities] CA server $caComputerName has $aceRights on its own AD object - expected"
                                    continue
                                }
                            }

                            $dangerousACEs += [PSCustomObject]@{
                                Identity = $identityName
                                IdentitySID = $aceSID
                                Rights = $aceRights
                                DangerousRight = $matchedRight
                                Severity = $scopeResult.Severity
                            }
                        }
                    }
                }
                catch {
                    Write-Log "[Get-ADCSVulnerabilities] CA AD object ACL check failed for '$($ca.Name)': $_"
                }

                # ===== Display: CA info =====
                # Note: We can only detect dangerous AD object permissions, not ESC7 (ManageCA/ManageCertificates)
                $hasDangerousADPermissions = @($dangerousACEs).Count -gt 0
                if ($hasDangerousADPermissions) {
                    $caVulnerabilityCount++
                }

                # CA Server info - add dangerousRights and web enrollment attributes
                if ($ca.DNSHostName) {
                    # Use the already retrieved $caComputer from web enrollment check, or fetch if not available
                    if (-not $caComputer) {
                        # Escape for LDAP filter to prevent injection (RFC 4515)
                        $escapedDnsHostName2 = Escape-LDAPFilterValue -Value $ca.DNSHostName
                        $caComputer = @(Get-DomainComputer -LDAPFilter "(dNSHostName=$escapedDnsHostName2)" @CredParams)[0]
                    }

                    if ($caComputer) {
                        # Add CA common name (from pKIEnrollmentService.cn) as a dedicated attribute -
                        # using 'displayName' would overwrite the underlying computer's actual displayName.
                        $caComputer | Add-Member -NotePropertyName 'caName' -NotePropertyValue $ca.Name -Force

                        # Add dangerous AD object permissions as dangerousRights attribute
                        if ($hasDangerousADPermissions) {
                            $permissionStrings = $dangerousACEs | ForEach-Object { "$($_.Identity): $($_.DangerousRight)" }
                            $caComputer | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue $permissionStrings -Force
                        }

                        # Add web enrollment attributes if check was successful
                        if ($webEnrollmentResult -and $webEnrollmentResult.Success) {
                            $caComputer | Add-Member -NotePropertyName 'HttpAvailable' -NotePropertyValue $webEnrollmentResult.HttpAvailable -Force
                            $caComputer | Add-Member -NotePropertyName 'HttpsAvailable' -NotePropertyValue $webEnrollmentResult.HttpsAvailable -Force

                            # Build active endpoints list with auth methods (new structure: Endpoints.<Name>.Available, Endpoints.<Name>.AuthMethods)
                            $activeEndpoints = @()
                            $endpointAuthMethods = @{}

                            if ($webEnrollmentResult.Endpoints.CertSrv.Available) {
                                $activeEndpoints += "CertSrv"
                                if ($webEnrollmentResult.Endpoints.CertSrv.AuthMethods) {
                                    $endpointAuthMethods['CertSrv'] = $webEnrollmentResult.Endpoints.CertSrv.AuthMethods
                                }
                            }
                            if ($webEnrollmentResult.Endpoints.CES.Available) {
                                $activeEndpoints += "CES"
                                if ($webEnrollmentResult.Endpoints.CES.AuthMethods) {
                                    $endpointAuthMethods['CES'] = $webEnrollmentResult.Endpoints.CES.AuthMethods
                                }
                            }
                            if ($webEnrollmentResult.Endpoints.CEP.Available) {
                                $activeEndpoints += "CEP"
                                if ($webEnrollmentResult.Endpoints.CEP.AuthMethods) {
                                    $endpointAuthMethods['CEP'] = $webEnrollmentResult.Endpoints.CEP.AuthMethods
                                }
                            }
                            if ($webEnrollmentResult.Endpoints.NDES.Available) {
                                $activeEndpoints += "NDES"
                                if ($webEnrollmentResult.Endpoints.NDES.AuthMethods) {
                                    $endpointAuthMethods['NDES'] = $webEnrollmentResult.Endpoints.NDES.AuthMethods
                                }
                            }

                            if (@($activeEndpoints).Count -gt 0) {
                                # Build array of endpoints with protocol, auth methods, and EPA status (multi-value, one per line)
                                # Show EACH available protocol separately (HTTP and HTTPS can both be available)
                                # EPA is only relevant for HTTPS - show it only on HTTPS lines
                                # ESC8 severity classification:
                                # - HTTP + NTLM = Critical (ESC8 directly exploitable, no EPA possible)
                                # - HTTPS + NTLM + EPA disabled = Finding (ESC8 possible)
                                # - HTTPS + NTLM + EPA enabled = Secure (protected)
                                # - HTTP + Negotiate = Hint (could have NTLM fallback)
                                # - HTTPS + Negotiate only = Standard (Kerberos-only is secure)
                                $endpointsWithAuth = @()

                                foreach ($ep in $activeEndpoints) {
                                    $authMethods = $endpointAuthMethods[$ep]
                                    $epData = $webEnrollmentResult.Endpoints.$ep

                                    # Render each endpoint by ITS OWN transport (not the global
                                    # protocol flags) so HTTPS-only endpoints like CEP/CES are not
                                    # dropped when CertSrv happens to be HTTP-only (and vice versa).
                                    # Show HTTP line if reachable via HTTP (no EPA - not applicable for HTTP)
                                    if ($epData.AvailableHttp) {
                                        $epString = "$ep via HTTP"
                                        if ($authMethods) {
                                            $epString += " ($authMethods)"
                                        }
                                        $endpointsWithAuth += $epString
                                    }

                                    # Show HTTPS line if reachable via HTTPS (with EPA status if tested)
                                    if ($epData.AvailableHttps) {
                                        $epString = "$ep via HTTPS"
                                        if ($authMethods) {
                                            $epString += " ($authMethods)"
                                        }
                                        # Add EPA status only for HTTPS (EPA is TLS-based)
                                        if ($null -ne $epData.EPAEnabled) {
                                            $epaStatus = if ($epData.EPAEnabled -eq $true) { "Enabled" } else { "Disabled" }
                                            $epString += " [EPA: $epaStatus]"
                                        }
                                        $endpointsWithAuth += $epString
                                    }
                                }
                                $caComputer | Add-Member -NotePropertyName 'WebEnrollmentEndpoints' -NotePropertyValue $endpointsWithAuth -Force
                            }

                            # Add legacy EPA properties (backward compatibility - first endpoint with NTLM)
                            # EPA protects against NTLM relay attacks over HTTPS (ESC8 mitigation)
                            if ($null -ne $webEnrollmentResult.EPAEnabled) {
                                $caComputer | Add-Member -NotePropertyName 'EPAEnabled' -NotePropertyValue $webEnrollmentResult.EPAEnabled -Force
                                $caComputer | Add-Member -NotePropertyName 'EPAConfidence' -NotePropertyValue $webEnrollmentResult.EPAConfidence -Force
                            }
                        }

                        # ===== CA Certificate Analysis =====
                        # Parse CA certificate properties for security assessment
                        $caCert = $ca.CACertificate
                        if ($caCert -and $caCert -isnot [string]) {
                            # Invoke-LDAPSearch already converted to PSCustomObject via Convert-CertificateToInfo
                            # Handle array (multi-valued) - use first certificate
                            if ($caCert -is [array]) { $caCert = $caCert[0] }

                            if ($caCert.Subject) {
                                $caComputer | Add-Member -NotePropertyName 'CACertSubject' -NotePropertyValue $caCert.Subject -Force
                            }
                            if ($caCert.Thumbprint) {
                                $caComputer | Add-Member -NotePropertyName 'CACertThumbprint' -NotePropertyValue $caCert.Thumbprint -Force
                            }
                            if ($caCert.NotBefore -and $caCert.NotAfter) {
                                $caComputer | Add-Member -NotePropertyName 'CACertValidity' -NotePropertyValue "$($caCert.NotBefore.ToString('yyyy-MM-dd')) to $($caCert.NotAfter.ToString('yyyy-MM-dd')) ($($caCert.Status))" -Force
                            }
                            if ($caCert.SignatureAlgorithm) {
                                $caComputer | Add-Member -NotePropertyName 'CACertSignatureAlgorithm' -NotePropertyValue $caCert.SignatureAlgorithm -Force
                            }
                            if ($caCert.PublicKeyLength -and $caCert.PublicKeyLength -gt 0) {
                                $caComputer | Add-Member -NotePropertyName 'CACertKeySize' -NotePropertyValue "$($caCert.PublicKeyLength) bit" -Force
                            }

                            # Flag weak signature algorithms
                            if ($caCert.SignatureAlgorithm -and $caCert.SignatureAlgorithm -match 'sha1|md5|md2') {
                                $caComputer | Add-Member -NotePropertyName 'CACertWeakSignature' -NotePropertyValue "Weak signature algorithm: $($caCert.SignatureAlgorithm)" -Force
                                $caVulnerabilityCount++
                                Write-Log "[Get-ADCSVulnerabilities] CA '$($ca.Name)' uses weak signature algorithm: $($caCert.SignatureAlgorithm)"
                            }

                            # Flag short key length
                            if ($caCert.PublicKeyLength -gt 0 -and $caCert.PublicKeyLength -lt 2048) {
                                $caComputer | Add-Member -NotePropertyName 'CACertShortKey' -NotePropertyValue "Insufficient key length: $($caCert.PublicKeyLength) bit (minimum 2048 recommended)" -Force
                                $caVulnerabilityCount++
                                Write-Log "[Get-ADCSVulnerabilities] CA '$($ca.Name)' uses short key: $($caCert.PublicKeyLength) bit"
                            }

                            # Flag expired certificates
                            if ($caCert.Status -eq 'EXPIRED') {
                                $caComputer | Add-Member -NotePropertyName 'CACertExpired' -NotePropertyValue "CA certificate expired on $($caCert.NotAfter.ToString('yyyy-MM-dd'))" -Force
                                $caVulnerabilityCount++
                                Write-Log "[Get-ADCSVulnerabilities] CA '$($ca.Name)' certificate is EXPIRED"
                            }
                        }

                        # Add enrollment service properties from Configuration Partition
                        # (may differ from or supplement what's on the computer object)
                        if ($ca.CertificateTemplates -and @($ca.CertificateTemplates).Count -gt 0) {
                            $caComputer | Add-Member -NotePropertyName 'certificateTemplates' -NotePropertyValue ($ca.CertificateTemplates -join ', ') -Force
                        }
                        if ($ca.Modified) {
                            $caComputer | Add-Member -NotePropertyName 'CALastModified' -NotePropertyValue $ca.Modified.ToString('yyyy-MM-dd HH:mm:ss') -Force
                        }

                        # Add type marker for HTML report
                        $caComputer | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'CertificateAuthority' -Force

                        Show-Object $caComputer
                    } else {
                        # Computer object not found in current domain partition
                        # (e.g., CA server is in root domain but we query from sub-domain)
                        # Build a synthetic object from CA enrollment service data (Configuration Partition)
                        Write-Log "[Get-ADCSVulnerabilities] CA computer '$($ca.DNSHostName)' not found in current domain - using Configuration Partition data"
                        $syntheticCA = [PSCustomObject]@{
                            dNSHostName          = $ca.DNSHostName
                            caName               = $ca.Name
                            caNote               = "CA server is not in the current domain partition - showing data from Configuration Partition only"
                            certificateTemplates = if ($ca.CertificateTemplates) { $ca.CertificateTemplates -join ', ' } else { $null }
                            CALastModified       = if ($ca.Modified) { $ca.Modified.ToString('yyyy-MM-dd HH:mm:ss') } else { $null }
                        }

                        # Add dangerous AD object permissions
                        if ($hasDangerousADPermissions) {
                            $permissionStrings = $dangerousACEs | ForEach-Object { "$($_.Identity): $($_.DangerousRight)" }
                            $syntheticCA | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue $permissionStrings -Force
                        }

                        # Add web enrollment attributes if check was successful (same logic as caComputer path)
                        if ($webEnrollmentResult -and $webEnrollmentResult.Success) {
                            $syntheticCA | Add-Member -NotePropertyName 'HttpAvailable' -NotePropertyValue $webEnrollmentResult.HttpAvailable -Force
                            $syntheticCA | Add-Member -NotePropertyName 'HttpsAvailable' -NotePropertyValue $webEnrollmentResult.HttpsAvailable -Force

                            $activeEndpoints = @()
                            $endpointAuthMethods = @{}
                            foreach ($epName in @('CertSrv', 'CES', 'CEP', 'NDES')) {
                                if ($webEnrollmentResult.Endpoints.$epName.Available) {
                                    $activeEndpoints += $epName
                                    if ($webEnrollmentResult.Endpoints.$epName.AuthMethods) {
                                        $endpointAuthMethods[$epName] = $webEnrollmentResult.Endpoints.$epName.AuthMethods
                                    }
                                }
                            }

                            if (@($activeEndpoints).Count -gt 0) {
                                $endpointsWithAuth = @()
                                foreach ($ep in $activeEndpoints) {
                                    $authMethods = $endpointAuthMethods[$ep]
                                    $epData = $webEnrollmentResult.Endpoints.$ep
                                    # Render each endpoint by its own transport (see caComputer path above).
                                    if ($epData.AvailableHttp) {
                                        $epString = "$ep via HTTP"
                                        if ($authMethods) { $epString += " ($authMethods)" }
                                        $endpointsWithAuth += $epString
                                    }
                                    if ($epData.AvailableHttps) {
                                        $epString = "$ep via HTTPS"
                                        if ($authMethods) { $epString += " ($authMethods)" }
                                        if ($null -ne $epData.EPAEnabled) {
                                            $epaStatus = if ($epData.EPAEnabled -eq $true) { "Enabled" } else { "Disabled" }
                                            $epString += " [EPA: $epaStatus]"
                                        }
                                        $endpointsWithAuth += $epString
                                    }
                                }
                                $syntheticCA | Add-Member -NotePropertyName 'WebEnrollmentEndpoints' -NotePropertyValue $endpointsWithAuth -Force
                            }

                            if ($null -ne $webEnrollmentResult.EPAEnabled) {
                                $syntheticCA | Add-Member -NotePropertyName 'EPAEnabled' -NotePropertyValue $webEnrollmentResult.EPAEnabled -Force
                                $syntheticCA | Add-Member -NotePropertyName 'EPAConfidence' -NotePropertyValue $webEnrollmentResult.EPAConfidence -Force
                            }
                        }

                        # CA Certificate Analysis (same as above)
                        $caCert = $ca.CACertificate
                        if ($caCert -and $caCert -isnot [string]) {
                            if ($caCert -is [array]) { $caCert = $caCert[0] }
                            if ($caCert.Subject) {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertSubject' -NotePropertyValue $caCert.Subject -Force
                            }
                            if ($caCert.Thumbprint) {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertThumbprint' -NotePropertyValue $caCert.Thumbprint -Force
                            }
                            if ($caCert.NotBefore -and $caCert.NotAfter) {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertValidity' -NotePropertyValue "$($caCert.NotBefore.ToString('yyyy-MM-dd')) to $($caCert.NotAfter.ToString('yyyy-MM-dd')) ($($caCert.Status))" -Force
                            }
                            if ($caCert.SignatureAlgorithm) {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertSignatureAlgorithm' -NotePropertyValue $caCert.SignatureAlgorithm -Force
                            }
                            if ($caCert.PublicKeyLength -and $caCert.PublicKeyLength -gt 0) {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertKeySize' -NotePropertyValue "$($caCert.PublicKeyLength) bit" -Force
                            }
                            if ($caCert.SignatureAlgorithm -and $caCert.SignatureAlgorithm -match 'sha1|md5|md2') {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertWeakSignature' -NotePropertyValue "Weak signature algorithm: $($caCert.SignatureAlgorithm)" -Force
                                $caVulnerabilityCount++
                            }
                            if ($caCert.PublicKeyLength -gt 0 -and $caCert.PublicKeyLength -lt 2048) {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertShortKey' -NotePropertyValue "Insufficient key length: $($caCert.PublicKeyLength) bit (minimum 2048 recommended)" -Force
                                $caVulnerabilityCount++
                            }
                            if ($caCert.Status -eq 'EXPIRED') {
                                $syntheticCA | Add-Member -NotePropertyName 'CACertExpired' -NotePropertyValue "CA certificate expired on $($caCert.NotAfter.ToString('yyyy-MM-dd'))" -Force
                                $caVulnerabilityCount++
                            }
                        }

                        $syntheticCA | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'CertificateAuthority' -Force
                        Show-Object $syntheticCA
                    }

                    # The web enrollment attributes (HttpAvailable / WebEnrollmentEndpoints,
                    # i.e. the ESC8 surface) are only added when the HTTP/HTTPS probe reached
                    # the CA. If the server was active and the probe was attempted but did not
                    # succeed (endpoint blocked or filtered), note it explicitly so a missing
                    # WebEnrollmentEndpoints row is not misread as "the CA has no web enrollment".
                    # Skipped-for-inactivity is deliberately silent (the INACTIVE marker covers it).
                    if (-not $skipHttpCheck) {
                        Show-WebEndpointUnreachable -ProbeResult $webEnrollmentResult -Hostname $ca.DNSHostName -CheckLabel 'Web enrollment check'
                    }
                } else {
                    # No DNS hostname - show permissions manually
                    if ($hasDangerousADPermissions) {
                        $permissionStrings = $dangerousACEs | ForEach-Object { "$($_.Identity): $($_.DangerousRight)" }
                        $permissionValue = $permissionStrings -join ", "
                        Show-KeyValue "dangerousADPermissions:" -Value $permissionValue -Class Finding
                    }
                    Show-EmptyLine
                }
            }

            # --- ESC5: Vulnerable PKI Object Access Control ---
            # Check for dangerous permissions on PKI container objects
            # If unprivileged users can write to these containers, they can:
            # - Create new vulnerable templates (ESC1-4)
            # - Modify existing templates
            # - Add themselves to enrollment permissions
            # - Manipulate NTAuth store
            try {
                Show-SubHeader "Checking PKI container permissions..." -ObjectType "PKIContainer"

                $pkiContainers = @(
                    @{
                        DN = "CN=Public Key Services,CN=Services,$configNC"
                        Name = "Public Key Services (Root)"
                        Description = "Root PKI container - controls entire PKI infrastructure"
                    },
                    @{
                        DN = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"
                        Name = "Certificate Templates Container"
                        Description = "Allows creating/modifying certificate templates"
                    },
                    @{
                        DN = "CN=Enrollment Services,CN=Public Key Services,CN=Services,$configNC"
                        Name = "Enrollment Services Container"
                        Description = "Controls certificate enrollment services"
                    },
                    @{
                        DN = "CN=NTAuthCertificates,CN=Public Key Services,CN=Services,$configNC"
                        Name = "NTAuth Store Container"
                        Description = "Controls trusted CAs for Kerberos authentication"
                    },
                    @{
                        DN = "CN=OID,CN=Public Key Services,CN=Services,$configNC"
                        Name = "OID Container"
                        Description = "Controls issuance policies (ESC13-related)"
                    }
                )

                # Collect findings per container
                $allFindings = @()

                foreach ($container in $pkiContainers) {
                    Write-Log "[Get-ADCSVulnerabilities] ESC5: Checking $($container.Name)..."

                    try {
                        # Get ACL for container - use Invoke-LDAPSearch with explicit SearchBase and -Raw
                        # (Configuration partition DNs require SearchBase to be set to configNC)
                        # -Raw is required to get nTSecurityDescriptor as byte[] instead of converted object
                        $containerObj = @(Invoke-LDAPSearch -Filter "(distinguishedName=$($container.DN))" -SearchBase $configNC -Properties 'nTSecurityDescriptor' -Raw -Scope Subtree)[0]

                        $containerACL = @()
                        if ($containerObj -and $containerObj.nTSecurityDescriptor) {
                            $secDescriptor = New-Object System.DirectoryServices.ActiveDirectorySecurity
                            $secDescriptor.SetSecurityDescriptorBinaryForm($containerObj.nTSecurityDescriptor)
                            $dacl = $secDescriptor.GetAccessRules($true, $false, [System.Security.Principal.SecurityIdentifier])

                            # Convert to PSCustomObject format
                            foreach ($ace in $dacl) {
                                $containerACL += [PSCustomObject]@{
                                    AccessControlType = $ace.AccessControlType
                                    IdentityReference = $ace.IdentityReference
                                    ActiveDirectoryRights = $ace.ActiveDirectoryRights
                                }
                            }
                        }

                        if ($containerACL) {
                            # Filter for dangerous permissions
                            $dangerousACEs = $containerACL | Where-Object {
                                $_.ActiveDirectoryRights -match 'GenericAll|WriteDacl|WriteOwner|GenericWrite' -and
                                $_.AccessControlType -eq 'Allow'
                            }

                            if ($dangerousACEs) {
                                # Analyze each ACE
                                foreach ($ace in $dangerousACEs) {
                                    $aceSID = $ace.IdentityReference.Value
                                    $aceRights = $ace.ActiveDirectoryRights.ToString()

                                    # Determine severity
                                    $severity = 'Finding'

                                    if (-not $IncludePrivileged) {
                                        # Use scope-based check for PKI container permissions
                                        $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'PKIContainer' -ReturnDetails

                                        if ($scopeResult.Severity -eq 'Expected') {
                                            Write-Log "[Get-ADCSVulnerabilities] Expected identity $aceSID has $aceRights on $($container.Name)"
                                            continue
                                        }

                                        if ($scopeResult.Severity -eq 'Attention') {
                                            Write-Log "[Get-ADCSVulnerabilities] Privileged identity $aceSID has $aceRights on $($container.Name) - skipped (use -IncludePrivileged to include)"
                                            continue
                                        }

                                        $severity = $scopeResult.Severity
                                    } else {
                                        # -IncludePrivileged: Show ALL accounts, but mark privileged ones
                                        $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'PKIContainer' -ReturnDetails
                                        $severity = $scopeResult.Severity
                                        Write-Log "[Get-ADCSVulnerabilities] IncludePrivileged: Including $aceSID with severity $severity"
                                    }

                                    # Add to findings
                                    $allFindings += [PSCustomObject]@{
                                        SID = $aceSID
                                        Rights = $aceRights
                                        Severity = $severity
                                        ContainerName = $container.Name
                                        ContainerDescription = $container.Description
                                    }
                                }
                            }
                        }
                    }
                    catch {
                        Write-Log "[Get-ADCSVulnerabilities] Error checking $($container.Name): $_" -Level Warning
                    }
                }

                # ===== Output findings with full AD objects =====
                if (@($allFindings).Count -gt 0) {
                    $countText = if ($IncludePrivileged) { "$(@($allFindings).Count) finding(s)" } else { "$(@($allFindings).Count) non-privileged finding(s)" }
                    Show-Line "Found $countText with dangerous PKI container permissions" -Class Finding

                    # Group by SID to consolidate multiple containers per principal
                    $groupedFindings = $allFindings | Group-Object -Property SID

                    foreach ($group in $groupedFindings) {
                        $sid = $group.Name
                        $findings = $group.Group
                        $allRights = @()
                        $allContainers = @()

                        foreach ($finding in $findings) {
                            $allRights += $finding.Rights
                            $allContainers += "$($finding.ContainerName) ($($finding.Rights))"
                        }

                        $allRights = $allRights | Select-Object -Unique
                        $severity = ($findings | Select-Object -First 1).Severity

                        # Try to resolve the SID to a full AD object
                        $sidHex = ConvertTo-LDAPSIDHex -SID $sid
                        $adObject = $null

                        if ($sidHex) {
                            $adObject = @(Get-DomainObject -LDAPFilter "(objectSid=$sidHex)" @CredParams)[0]
                        }

                        if ($adObject) {
                            $adObject | Add-Member -NotePropertyName 'dangerousRights' -NotePropertyValue ($allRights -join ', ') -Force
                            $adObject | Add-Member -NotePropertyName 'dangerousRightsSeverity' -NotePropertyValue $severity -Force
                            $adObject | Add-Member -NotePropertyName 'pkiContainersAffected' -NotePropertyValue $allContainers -Force
                            $adObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PKIContainer' -Force
                            Show-Object $adObject
                        } else {
                            # Create synthetic object for unresolvable SIDs
                            $resolvedName = ConvertFrom-SID -SID $sid
                            $syntheticObject = [PSCustomObject]@{
                                sAMAccountName = $resolvedName
                                objectSid = $sid
                                objectClass = 'foreignSecurityPrincipal'
                                dangerousRights = $allRights -join ', '
                                dangerousRightsSeverity = $severity
                                pkiContainersAffected = $allContainers
                            }
                            $syntheticObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PKIContainer' -Force
                            Show-Object $syntheticObject
                        }
                    }
                } else {
                    Show-Line "PKI container permissions are properly restricted" -Class Secure
                }
            }
            catch {
                Write-Log "[Get-ADCSVulnerabilities] Error during ESC5 check: $_" -Level Warning
                Show-Line "Error checking PKI container permissions" -Class Hint
            }

            # Step 2: Enumerate Certificate Templates (only enabled/published ones)
            Show-SubHeader "Searching for certificate templates..." -ObjectType "CertificateTemplate"
            $templateResults = @(Get-ADCSTemplate @CredParams)

            # Check if query failed (auth error, network issue, etc.)
            $templateQueryError = $templateResults | Where-Object { $_._QueryError -eq $true }
            if ($templateQueryError) {
                Write-Log "[Get-ADCSVulnerabilities] Template query failed: $($templateQueryError.ErrorMessage)"
                Show-Line "Failed to query certificate templates - LDAP query failed (authentication/network issue)" -Class Finding
                return
            }

            # Filter out any error markers (should be none at this point)
            $templates = @($templateResults | Where-Object { $_._QueryError -ne $true })

            if (@($templates).Count -eq 0) {
                Show-Line "No enabled certificate templates found" -Class Note
                return
            }

            # Track total vulnerabilities and interesting templates for summary
            $totalVulnerabilities = 0
            $interestingTemplates = @()

            # Pre-load issuance policy OID-to-group-link cache for ESC13 detection
            # Query once before template loop for performance
            $oidToGroupLink = @{}
            try {
                $oidSearchBase = "CN=OID,CN=Public Key Services,CN=Services,$configNC"
                $oidObjects = @(Invoke-LDAPSearch -Filter "(objectClass=msPKI-Enterprise-Oid)" `
                                                  -SearchBase $oidSearchBase `
                                                  -Properties 'cn','displayName','msPKI-Cert-Template-OID','msDS-OIDToGroupLink' `
                                                  -Scope OneLevel)

                foreach ($oidObj in $oidObjects) {
                    $oid = $oidObj.'msPKI-Cert-Template-OID'
                    if (-not $oid) { continue }
                    if ($oid -is [array]) { $oid = $oid[0] }

                    $groupLinkDN = $oidObj.'msDS-OIDToGroupLink'
                    if (-not $groupLinkDN) { continue }
                    if ($groupLinkDN -is [array]) { $groupLinkDN = $groupLinkDN[0] }

                    # Store group link DN and display name
                    $policyDisplayName = if ($oidObj.displayName) { $oidObj.displayName } else { $oidObj.cn }
                    if ($policyDisplayName -is [array]) { $policyDisplayName = $policyDisplayName[0] }

                    $oidToGroupLink[$oid] = @{
                        GroupLinkDN = $groupLinkDN
                        PolicyName  = $policyDisplayName
                    }
                }

                if ($oidToGroupLink.Count -gt 0) {
                    Write-Log "[Get-ADCSVulnerabilities] ESC13 cache: Found $($oidToGroupLink.Count) issuance policy OID(s) with group links"
                }
            }
            catch {
                Write-Log "[Get-ADCSVulnerabilities] ESC13: Error loading issuance policy cache: $_" -Level Warning
            }

            # Pre-pass: resolve enrollment privilege for every template once, and record which
            # templates hand out enrollment agent certificates to non-privileged principals.
            # ESC3 needs both halves of the chain and they can appear in any order in the result
            # set, so the answer must be known before the first template is judged.
            # The cache is keyed by DistinguishedName and reused in the main loop, so
            # Test-AllEnrollmentPrivileged still runs exactly once per template.
            $enrollPrivilegedCache = @{}
            $agentTemplateNames = @()
            foreach ($preTemplate in $templates) {
                $preKey = [string]$preTemplate.DistinguishedName
                $prePrivileged = Test-AllEnrollmentPrivileged -EnrollmentPrincipalSIDs $preTemplate.EnrollmentPrincipalSIDs -EnrollmentPrincipals $preTemplate.EnrollmentPrincipals -CredParams $CredParams
                $enrollPrivilegedCache[$preKey] = $prePrivileged

                if ($preTemplate.EnrollmentAgent -and -not $prePrivileged) {
                    $agentTemplateNames += $preTemplate.Name
                }
            }
            if (@($agentTemplateNames).Count -gt 0) {
                Write-Log "[Get-ADCSVulnerabilities] ESC3 chain: $(@($agentTemplateNames).Count) enrollment agent template(s) enrollable by non-privileged principals: $($agentTemplateNames -join ', ')"
            }

            # Step 3: Analyze Templates for Vulnerabilities (only enabled templates)
            $totalTemplates = @($templates).Count
            $currentIndex = 0
            foreach ($template in $templates) {
                $currentIndex++
                if ($totalTemplates -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing templates for vulnerabilities" -Current $currentIndex -Total $totalTemplates -ObjectName $template.DisplayName }

                $templateVulns = @()

                # Pre-check: Are ALL enrollment principals truly privileged?
                # If yes, ESC1/2/3/9/15 are NOT real vulnerabilities (only admins can enroll)
                # ESC4 (template permissions) is still checked regardless
                $allEnrollmentPrivileged = $enrollPrivilegedCache[[string]$template.DistinguishedName]
                if ($allEnrollmentPrivileged) {
                    Write-Log "[Get-ADCSVulnerabilities] Template '$($template.Name)': All enrollment principals are truly privileged - skipping ESC1/2/3/9/15"
                }

                # Registration Authority barrier: a template that demands co-signatures cannot be
                # enrolled directly, so the enrollment-driven ESCs below are only reachable once an
                # enrollment agent certificate is in hand. This deliberately does NOT cover ESC4 -
                # write access to the template lets an attacker drop the requirement first.
                $requiresRASignature = $template.RASignatureCount -ge 1

                # ===== ESC1: Client Authentication + Enrollee-Supplied Subject =====
                # Only flag if non-privileged users can enroll
                if ($template.EnrolleeSuppliesSubject -and $template.ClientAuthentication -and -not $allEnrollmentPrivileged) {
                    $templateVulns += [PSCustomObject]@{
                        ESC = "ESC1"
                        Title = "Client Authentication + Enrollee-Supplied Subject"
                        Severity = "Critical"
                        Description = "Template allows enrollee to specify arbitrary subject (SAN) and supports client authentication. Attacker can impersonate any user/computer."
                        Remediation = "Remove 'Enrollee supplies subject' flag OR remove client authentication EKUs."
                        Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc1"
                    }
                }

                # ===== ESC2: Any Purpose EKU =====
                # Only flag if non-privileged users can enroll
                if ($template.AnyPurpose -and -not $allEnrollmentPrivileged) {
                    # Check if it's the dangerous variant (schema v1 needs client auth to matter)
                    # A required RA co-signature no longer suppresses the finding here: it is a
                    # barrier, not a fix, and is accounted for centrally by the ra_signature_gated
                    # trigger so that ESC1/2/3/9/13/15 all treat it the same way.
                    $isDangerous = $false
                    if ($template.SchemaVersion -eq 1) {
                        $isDangerous = [bool]$template.ClientAuthentication
                    } else {
                        $isDangerous = $true
                    }

                    if ($isDangerous) {
                        $templateVulns += [PSCustomObject]@{
                            ESC = "ESC2"
                            Title = "Any Purpose EKU"
                            Severity = "High"
                            Description = "Template can be used for any purpose including client authentication. Can be abused for privilege escalation."
                            Remediation = "Specify explicit EKUs instead of 'Any Purpose' (OID 2.5.29.37.0)."
                            Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc2"
                        }
                    }
                }

                # ===== ESC3: Certificate Request Agent EKU =====
                # Only flag if non-privileged users can enroll
                if ($template.EnrollmentAgent -and -not $allEnrollmentPrivileged) {
                    $templateVulns += [PSCustomObject]@{
                        ESC = "ESC3"
                        Title = "Certificate Request Agent EKU"
                        Severity = "High"
                        Description = "Template has 'Certificate Request Agent' EKU (1.3.6.1.4.1.311.20.2.1). Attacker can request certificates on behalf of other users."
                        Remediation = "Remove 'Certificate Request Agent' EKU unless required for legitimate enrollment agents."
                        Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc3"
                    }
                }

                # ===== ESC3 (condition 2): Enrollment Agent Target Template =====
                # The mirror image of the check above. This template does not hand out agent
                # certificates - it is what an agent certificate is spent on. msPKI-RA-Signature >= 1
                # combined with a Certificate Request Agent application policy means the CA issues it
                # for whatever subject the co-signing agent names, so a client-auth template of this
                # kind is a direct impersonation primitive for anyone holding an agent certificate.
                # Note this is invisible to the condition 1 check: the Certificate Request Agent OID
                # sits in msPKI-RA-Application-Policies here, not in the template's own EKUs.
                if ($template.EnrollmentAgentSignatureRequired -and $template.ClientAuthentication -and -not $allEnrollmentPrivileged) {
                    $chainNote = if (@($agentTemplateNames).Count -gt 0) {
                        "At least one Certificate Request Agent template in this domain is enrollable by non-privileged principals, so the complete ESC3 chain is reachable without any pre-existing agent certificate - see the ESC3 findings in this section."
                    } else {
                        "No Certificate Request Agent template enrollable by non-privileged principals was found, so abuse requires an existing, stolen or CA-issued enrollment agent certificate."
                    }

                    $templateVulns += [PSCustomObject]@{
                        ESC = "ESC3-TARGET"
                        Title = "Enrollment Agent Target Template (ESC3 on-behalf-of)"
                        Severity = if (@($agentTemplateNames).Count -gt 0) { "High" } else { "Medium" }
                        Description = "Template requires $($template.RASignatureCount) enrollment agent co-signature(s) (msPKI-RA-Application-Policies contains 1.3.6.1.4.1.311.20.2.1) and supports client authentication. An enrollment agent can request a certificate for any principal from this template. $chainNote"
                        Remediation = "Enable enrollment agent restrictions on the CA (certutil -setreg policy\EnableEnrollmentAgentRestrictions 1) and limit which templates and target principals each agent may use, OR require manager approval on this template."
                        Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc3"
                    }
                }

                # ===== ESC4: Dangerous Template Permissions =====
                # Check if non-privileged users have dangerous permissions on this template
                try {
                    # Templates live in the Configuration partition - must use Invoke-LDAPSearch with
                    # the template's own DN as SearchBase and Base scope (single-object lookup).
                    # -Raw is required to get nTSecurityDescriptor as byte[] for parsing.
                    $templateSDObj = @(Invoke-LDAPSearch -Filter "(objectClass=*)" -SearchBase $template.DistinguishedName -Properties 'nTSecurityDescriptor' -Raw -Scope Base)[0]
                    $securityDescriptor = $null
                    if ($templateSDObj -and $templateSDObj.nTSecurityDescriptor) {
                        $securityDescriptor = New-Object System.DirectoryServices.ActiveDirectorySecurity
                        $securityDescriptor.SetSecurityDescriptorBinaryForm($templateSDObj.nTSecurityDescriptor)
                    }

                    if ($securityDescriptor) {
                        $dacl = $securityDescriptor.GetAccessRules($true, $false, [System.Security.Principal.SecurityIdentifier])

                        $dangerousACEs = @()
                        # Note: WriteProperty is only dangerous if it applies to ALL properties (empty ObjectType)
                        # Property-specific WriteProperty (with ObjectType GUID) is NOT dangerous for ESC4
                        $dangerousRights = @('GenericAll', 'GenericWrite', 'WriteDacl', 'WriteOwner')

                        # Uses central privileged SID definitions from ConvertFrom-SID.ps1

                        foreach ($ace in $dacl) {
                            if ($ace.AccessControlType -ne 'Allow') { continue }

                            $aceSID = $ace.IdentityReference.Value
                            $aceRights = $ace.ActiveDirectoryRights.ToString()

                            # Check if ACE has dangerous rights
                            $hasDangerousRight = $false
                            $matchedRight = ""

                            # First check the always-dangerous rights
                            foreach ($right in $dangerousRights) {
                                if ($aceRights -match $right) {
                                    $hasDangerousRight = $true
                                    $matchedRight = $right
                                    break
                                }
                            }

                            # WriteProperty is only dangerous if ObjectType is empty (applies to ALL properties)
                            # When ObjectType contains a GUID, it only grants write to a specific property (harmless for ESC4)
                            if (-not $hasDangerousRight -and $aceRights -match 'WriteProperty') {
                                $objectTypeGuid = $ace.ObjectType
                                # Empty GUID or all-zeros means "all properties" = dangerous
                                if ($null -eq $objectTypeGuid -or $objectTypeGuid -eq [Guid]::Empty) {
                                    $hasDangerousRight = $true
                                    $matchedRight = "WriteProperty (All)"
                                }
                                # else: property-specific WriteProperty is NOT dangerous
                            }

                            if (-not $hasDangerousRight) { continue }

                            # Resolve identity name for display
                            $identityName = ConvertFrom-SID -SID $aceSID

                            # Determine severity for this identity
                            $severity = 'Finding'

                            if (-not $IncludePrivileged) {
                                # Use scope-based check for ADCS template permissions (ESC4)
                                $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'ADCSEnroll' -ReturnDetails

                                # Skip Expected (direct match like Domain Admins group)
                                if ($scopeResult.Severity -eq 'Expected') {
                                    Write-Log "[Get-ADCSVulnerabilities] Expected identity $aceSID has $aceRights on template $($template.Name)"
                                    continue
                                }

                                # Skip Attention (member of privileged group)
                                if ($scopeResult.Severity -eq 'Attention') {
                                    Write-Log "[Get-ADCSVulnerabilities] Privileged identity $aceSID (member of admin group) has $aceRights on template $($template.Name) - skipped (use -IncludePrivileged to include)"
                                    continue
                                }

                                $severity = $scopeResult.Severity
                            } else {
                                # -IncludePrivileged: Show ALL accounts, but mark privileged ones for yellow display
                                $scopeResult = Test-IsExpectedInScope -Identity $aceSID -Scope 'ADCSEnroll' -ReturnDetails
                                # Expected or Attention -> will be shown in yellow (Hint)
                                # Finding -> will be shown in red
                                $severity = $scopeResult.Severity
                                Write-Log "[Get-ADCSVulnerabilities] IncludePrivileged: Including $identityName ($aceSID) with severity $severity"
                            }

                            # Account with dangerous rights - ESC4
                            $dangerousACEs += [PSCustomObject]@{
                                Identity = $identityName
                                IdentitySID = $aceSID
                                Rights = $aceRights
                                DangerousRight = $matchedRight
                                Severity = $severity
                            }
                        }

                        if (@($dangerousACEs).Count -gt 0) {
                            $identities = ($dangerousACEs | ForEach-Object { $_.Identity }) -join ', '
                            $templateVulns += [PSCustomObject]@{
                                ESC = "ESC4"
                                Title = "Dangerous Template Permissions"
                                Severity = "Critical"
                                Description = "Non-privileged accounts have modify permissions on this template: $identities. Attackers can modify template settings to enable ESC1-3 vulnerabilities."
                                Remediation = "Remove write permissions for non-privileged accounts. Only Domain Admins and Enterprise Admins should modify templates."
                                Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc4"
                                DangerousACEs = $dangerousACEs
                            }

                            Write-Log "[Get-ADCSVulnerabilities] ESC4: Template '$($template.Name)' has dangerous permissions for: $identities"
                        }
                    }
                }
                catch {
                    Write-Log "[Get-ADCSVulnerabilities] ESC4 check failed for template '$($template.Name)': $_"
                }

                # ===== ESC9: No Security Extension + Client Auth =====
                # Only flag if non-privileged users can enroll
                if ($template.NoSecurityExtension -and $template.ClientAuthentication -and -not $allEnrollmentPrivileged) {
                    $templateVulns += [PSCustomObject]@{
                        ESC = "ESC9"
                        Title = "No Security Extension + Client Authentication"
                        Severity = "High"
                        Description = "Template has NO_SECURITY_EXTENSION flag and supports client authentication. Attacker can modify userPrincipalName and request certificate for any user."
                        Remediation = "Remove NO_SECURITY_EXTENSION flag OR remove client authentication EKUs."
                        Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc9"
                    }
                }

                # ===== ESC13: Issuance Policy Linked to Group =====
                # Only flag if non-privileged users can enroll
                if (-not $allEnrollmentPrivileged -and $oidToGroupLink.Count -gt 0 -and @($template.CertificatePolicies).Count -gt 0) {
                    $linkedPolicies = @()

                    foreach ($policyOID in @($template.CertificatePolicies)) {
                        if ($oidToGroupLink.ContainsKey($policyOID)) {
                            $linkInfo = $oidToGroupLink[$policyOID]

                            # Resolve group name from DN
                            $groupName = $linkInfo.GroupLinkDN
                            try {
                                $escapedDN = Escape-LDAPFilterValue -Value $linkInfo.GroupLinkDN
                                $groupObj = @(Get-DomainObject -LDAPFilter "(distinguishedName=$escapedDN)" @CredParams)[0]
                                if ($groupObj) {
                                    $groupName = if ($groupObj.sAMAccountName) { $groupObj.sAMAccountName } else { $groupObj.name }
                                }
                            }
                            catch {
                                Write-Log "[Get-ADCSVulnerabilities] ESC13: Error resolving group '$($linkInfo.GroupLinkDN)': $_" -Level Debug
                            }

                            $linkedPolicies += "$($linkInfo.PolicyName) (OID: $policyOID) -> $groupName"
                            Write-Log "[Get-ADCSVulnerabilities] ESC13: Template '$($template.Name)' - Policy '$($linkInfo.PolicyName)' linked to group '$groupName'"
                        }
                    }

                    if (@($linkedPolicies).Count -gt 0) {
                        $templateVulns += [PSCustomObject]@{
                            ESC = "ESC13"
                            Title = "Issuance Policy Linked to Group"
                            Severity = "High"
                            Description = "Template uses issuance policy OID(s) linked to AD groups via msDS-OIDToGroupLink. Enrollment grants automatic group membership."
                            Remediation = "Remove msDS-OIDToGroupLink from the issuance policy OID, OR remove the policy from the template's msPKI-Certificate-Policy, OR restrict enrollment to privileged users."
                            Reference = "https://posts.specterops.io/adcs-esc13-abuse-technique-fda4272fbd53"
                        }

                        # Add linked policies info to template for display
                        $template | Add-Member -NotePropertyName 'IssuancePolicyGroupLinks' -NotePropertyValue $linkedPolicies -Force
                    }
                }

                # ===== ESC15: Schema v1 + Enrollee-Supplied Subject (CVE-2024-49019) =====
                # Only flag if non-privileged users can enroll
                if ($template.EnrolleeSuppliesSubject -and $template.SchemaVersion -eq 1 -and -not $allEnrollmentPrivileged) {
                    $templateVulns += [PSCustomObject]@{
                        ESC = "ESC15"
                        Title = "Schema v1 + Enrollee-Supplied Subject (CVE-2024-49019)"
                        Severity = "Critical"
                        Description = "Template allows enrollee to specify subject and uses schema version 1. Vulnerable to CVE-2024-49019."
                        Remediation = "Upgrade template to schema version 2+ OR remove 'Enrollee supplies subject' flag."
                        Reference = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc15"
                    }
                }

                # Record whether an enrollment agent certificate is obtainable in this domain.
                # Deliberately NOT displayed: which template to abuse for that is the tester's
                # call, and adPEAS already reports every candidate as its own ESC3 finding.
                # The flag exists solely for the ra_signature_gated trigger - if an agent
                # certificate is freely obtainable, the co-signature requirement is a formality
                # and the enrollment-driven ESCs keep their full severity instead of being damped.
                if ($requiresRASignature) {
                    $template | Add-Member -NotePropertyName 'EnrollmentAgentChainReachable' -NotePropertyValue (@($agentTemplateNames).Count -gt 0) -Force
                }

                # Display findings for this template
                # Show template if:
                # 1. It has ESC vulnerabilities (Critical/High findings), OR
                # 2. It has non-privileged enrollment (interesting for enumeration, like v1)
                $hasVulnerabilities = @($templateVulns).Count -gt 0
                $hasNonPrivilegedEnrollment = -not $allEnrollmentPrivileged -and @($template.EnrollmentPrincipals).Count -gt 0

                if ($hasVulnerabilities -or $hasNonPrivilegedEnrollment) {
                    if ($hasVulnerabilities) {
                        $totalVulnerabilities++

                        # Collect ESC list and ESC4 DangerousACEs
                        $escList = $templateVulns | ForEach-Object { $_.ESC }
                        $allESCs = ($escList | Sort-Object -Unique) -join ", "
                        $esc4Vuln = $templateVulns | Where-Object { $_.ESC -eq "ESC4" } | Select-Object -First 1

                        # Enrich template with vulnerability info for Show-Object
                        $template | Add-Member -NotePropertyName 'Vulnerabilities' -NotePropertyValue $allESCs -Force
                        if ($esc4Vuln -and $esc4Vuln.DangerousACEs) {
                            $template | Add-Member -NotePropertyName 'DangerousACEs' -NotePropertyValue $esc4Vuln.DangerousACEs -Force
                        }
                    }

                    # Collect for later display
                    $interestingTemplates += $template
                }
            }
            if ($totalTemplates -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing templates for vulnerabilities" -Completed }

            # Display summary and templates
            $interestingCount = @($interestingTemplates).Count
            if ($interestingCount -gt 0) {
                # Show informative message about what we found
                if ($totalVulnerabilities -gt 0) {
                    Show-Line "Found $interestingCount of $($templates.Count) templates with findings" -Class Finding
                } else {
                    Show-Line "Found $interestingCount of $($templates.Count) templates with non-privileged enrollment" -Class Hint
                }

                # Display all interesting templates
                foreach ($tmpl in $interestingTemplates) {
                    # Add type marker for HTML report
                    $tmpl | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'CertificateTemplate' -Force
                    Show-Object $tmpl
                }
            } else {
                # No interesting templates found
                $totalFindings = $totalVulnerabilities + $caVulnerabilityCount
                if ($totalFindings -eq 0) {
                    Show-Line "No findings in $($templates.Count) analyzed template(s) - all enrollment restricted to privileged users" -Class Secure
                }
            }

        }
        catch {
            Write-Log "[Get-ADCSVulnerabilities] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ADCSVulnerabilities] AD CS vulnerability scan complete"
    }
}





# ----- Get-ExchangeInfrastructure.ps1 -----

function Get-ExchangeInfrastructure {
    <#
    .SYNOPSIS
    Detects Microsoft Exchange Server infrastructure and security issues via LDAP.

    .DESCRIPTION
    Performs passive detection of Exchange Server infrastructure using LDAP queries only.
    Identifies Exchange organization, servers, versions, privileged groups (especially
    Exchange Trusted Subsystem with WriteDacl on Domain!), shared mailboxes, and service accounts.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-ExchangeInfrastructure
    Performs Exchange infrastructure detection and security analysis.

    .EXAMPLE
    Get-ExchangeInfrastructure -Domain "contoso.com" -Credential (Get-Credential)
    Performs Exchange detection with explicit credentials.

    .NOTES
    Category: Application
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-ExchangeInfrastructure] Starting check"
    }

    process {
        function Convert-ExchangeBuildToVersion {
            param([string]$BuildNumber)

            if (-not $BuildNumber) { return $null }

            $normalizedVersion = Get-NormalizedExchangeVersion -BuildNumber $BuildNumber

            if ($normalizedVersion) {
                # Convert lifecycle key to display name (add "Server" for consistency)
                return $normalizedVersion -replace '^Exchange ', 'Exchange Server '
            }

            return "Unknown Exchange Version"
        }

        # Helper function to get version severity class
        function Get-ExchangeVersionClass {
            param([string]$BuildNumber)

            if (-not $BuildNumber) { return "Standard" }

            return Get-ExchangeSeverity -BuildNumber $BuildNumber
        }

        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            # Get Configuration DN from context
            $configDN = $Script:LDAPContext.ConfigurationNamingContext

            # ===== Step 1: Check for Exchange Organization (internal, no output) =====
            $exchangeOrgExists = $false
            $organizationName = $null

            try {
                # Use Get-DomainObject to check for Exchange Organization container
                $exchangeOrgs = Get-DomainObject -LDAPFilter "(objectClass=msExchOrganizationContainer)" -SearchBase "CN=Microsoft Exchange,CN=Services,$configDN" @PSBoundParameters

                if ($exchangeOrgs) {
                    $exchangeOrgExists = $true

                    if ($exchangeOrgs -is [Array]) {
                        $organizationName = $exchangeOrgs[0].cn
                    } else {
                        $organizationName = $exchangeOrgs.cn
                    }
                }
            }
            catch {
                Write-Log "[Get-ExchangeInfrastructure] Exchange Organization not Found: $_"
            }

            if (-not $exchangeOrgExists) {
                Show-SubHeader "Checking for Exchange Organization..." -ObjectType "ExchangeServer"
                Show-Line "No Exchange Organization detected" -Class Note
                return
            }

            # ===== Step 1b: Exchange Organization Overview (Config Partition - forest-wide) =====
            # Queries the Configuration partition which is visible from any domain in the forest.
            # Outputs: 1 global Organization card + 1 card per Exchange server with VDirs/Connectors.
            Show-SubHeader "Checking Exchange Organization..." -ObjectType "ExchangeOrganization"

            $exchangeBase = "CN=Microsoft Exchange,CN=Services,$configDN"

            # --- Phase 1: Query all Config Partition data upfront ---
            $realServers = @()
            $allVDirs = @()
            $allRecvConnectors = @()
            $allSendConnectors = @()
            $allAcceptedDomains = @()

            try {
                # Exchange Servers: msExchExchangeServer includes role containers (Mailbox, Frontend).
                # Real servers have DN: CN=<name>,CN=Servers,CN=... (direct children of CN=Servers)
                # Role containers have DN: CN=Mailbox,CN=Transport Configuration,CN=<name>,CN=Servers,...
                $configServers = @(Get-DomainObject -LDAPFilter "(objectClass=msExchExchangeServer)" -SearchBase $exchangeBase @PSBoundParameters)
                $realServers = @($configServers | Where-Object {
                    $_.distinguishedName -match "CN=$([regex]::Escape($_.name)),CN=Servers,"
                })
            } catch {
                Write-Log "[Get-ExchangeInfrastructure] Error querying Config partition servers: $_" -Level Error
            }

            try {
                $vdirParts = @(
                    "(objectClass=msExchOWAVirtualDirectory)", "(objectClass=msExchECPVirtualDirectory)",
                    "(objectClass=msExchWebServicesVirtualDirectory)", "(objectClass=msExchActiveSyncVirtualDirectory)",
                    "(objectClass=msExchAutoDiscoverVirtualDirectory)", "(objectClass=msExchMapiVirtualDirectory)",
                    "(objectClass=msExchPowerShellVirtualDirectory)", "(objectClass=msExchRpcHttpVirtualDirectory)"
                )
                $vdirFilter = '(|' + ($vdirParts -join '') + ')'
                $allVDirs = @(Get-DomainObject -LDAPFilter $vdirFilter -SearchBase $exchangeBase @PSBoundParameters)
            } catch {
                Write-Log "[Get-ExchangeInfrastructure] Error querying Virtual Directories: $_" -Level Error
            }

            try {
                $allRecvConnectors = @(Get-DomainObject -LDAPFilter "(objectClass=msExchSmtpReceiveConnector)" -SearchBase $exchangeBase @PSBoundParameters)
            } catch {
                Write-Log "[Get-ExchangeInfrastructure] Error querying SMTP Receive Connectors: $_" -Level Error
            }

            try {
                $allSendConnectors = @(Get-DomainObject -LDAPFilter "(objectClass=msExchRoutingSMTPConnector)" -SearchBase $exchangeBase @PSBoundParameters)
            } catch {
                Write-Log "[Get-ExchangeInfrastructure] Error querying SMTP Send Connectors: $_" -Level Error
            }

            try {
                $allAcceptedDomains = @(Get-DomainObject -LDAPFilter "(objectClass=msExchAcceptedDomain)" -SearchBase $exchangeBase @PSBoundParameters)
            } catch {
                Write-Log "[Get-ExchangeInfrastructure] Error querying Accepted Domains: $_" -Level Error
            }

            # --- Phase 2: Global Organization Card ---
            $orgObj = [PSCustomObject]@{
                Name = $organizationName
                OrganizationName = $organizationName
            }

            if ($realServers.Count -gt 0) {
                $orgObj | Add-Member -NotePropertyName 'ExchangeServerCount' -NotePropertyValue "$($realServers.Count) server(s)" -Force
            }

            if (@($allAcceptedDomains).Count -gt 0) {
                $typeMap = @{ 0 = "Authoritative"; 1 = "InternalRelay"; 2 = "ExternalRelay" }
                $adLines = @()
                foreach ($ad in $allAcceptedDomains) {
                    $domainType = $typeMap[[int]$ad.msExchAcceptedDomainType]
                    if (-not $domainType) { $domainType = "Unknown" }
                    $adLines += "$($ad.msExchAcceptedDomainName) ($domainType)"
                }
                $orgObj | Add-Member -NotePropertyName 'AcceptedDomains' -NotePropertyValue $adLines -Force
            }

            if (@($allSendConnectors).Count -gt 0) {
                $scLines = @()
                foreach ($sc in $allSendConnectors) {
                    $addrSpaces = $sc.msExchConnectorAddressSpaces
                    $addrInfo = if ($addrSpaces) { " ($addrSpaces)" } else { "" }
                    $scLines += "$($sc.name)$addrInfo"
                }
                $orgObj | Add-Member -NotePropertyName 'SMTPSendConnectors' -NotePropertyValue $scLines -Force
            }

            $orgObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeOrganization' -Force
            Show-Line "Exchange Organization found in Configuration partition" -Class Hint
            Show-Object $orgObj

            # --- Phase 3: Per-Server Config Cards ---
            foreach ($srv in $realServers) {
                $srvName = $srv.name
                $srvDN = $srv.distinguishedName

                # Extract FQDN from networkAddress (ncacn_ip_tcp:srvex.sturz.org)
                $fqdn = $srvName
                $netAddr = $srv.networkAddress
                if ($netAddr) {
                    $addrStr = if ($netAddr -is [array]) { $netAddr -join ' ' } else { [string]$netAddr }
                    if ($addrStr -match 'ncacn_ip_tcp:([^\s]+)') { $fqdn = $Matches[1] }
                }

                # Extract Exchange version from serialNumber (e.g., "Version 15.2 (Build 32562.17)")
                # Note: The build number from Config partition reflects the schema version, not the actual installed CU/patch level
                $sn = $srv.serialNumber
                $exchVersion = if ($sn) { [string]$sn } else { "Unknown" }
                # Extract build number for EOL lifecycle check (e.g., "15.2.32562.17")
                $exchBuildNumber = $null
                if ($sn -match 'Version (\d+)\.(\d+).*Build (\d+)\.(\d+)') {
                    $exchBuildNumber = "$($Matches[1]).$($Matches[2]).$($Matches[3]).$($Matches[4])"
                }

                # Extract domain from Config DN (DC= components after CN=Configuration)
                $serverDomain = $null
                if ($srvDN -match 'CN=Configuration,(.+)$') {
                    $dcPart = $Matches[1]
                    $serverDomain = ($dcPart -replace 'DC=', '' -replace ',', '.')
                }

                $srvObj = [PSCustomObject]@{
                    Name = $srvName
                    dNSHostName = $fqdn
                    ExchangeVersion = $exchVersion
                }

                if ($exchBuildNumber) {
                    $srvObj | Add-Member -NotePropertyName 'ExchangeBuildNumber' -NotePropertyValue $exchBuildNumber -Force
                }
                if ($serverDomain) {
                    $srvObj | Add-Member -NotePropertyName 'forestRootDomain' -NotePropertyValue $serverDomain -Force
                }
                $srvObj | Add-Member -NotePropertyName 'distinguishedName' -NotePropertyValue $srvDN -Force

                # Map VDirs to this server (DN contains CN=<srvName>,CN=Servers)
                $escapedSrvName = [regex]::Escape($srvName)
                $srvVDirs = @($allVDirs | Where-Object {
                    $_.distinguishedName -match "CN=$escapedSrvName,CN=Servers,"
                })
                if ($srvVDirs.Count -gt 0) {
                    $vdirTypes = [ordered]@{}
                    $externalUrls = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($vdir in $srvVDirs) {
                        # Skip VDirs without any configured URL (e.g., "Exchange Back End" entries)
                        if (-not $vdir.msExchInternalHostName -and -not $vdir.msExchExternalHostName) { continue }
                        $vdirClass = if ($vdir.objectClass -is [array]) { $vdir.objectClass[-1] } else { $vdir.objectClass }
                        $shortType = $vdirClass -replace 'msExch|VirtualDirectory', ''
                        if (-not $vdirTypes.Contains($shortType)) { $vdirTypes[$shortType] = $true }
                        if ($vdir.msExchExternalHostName) {
                            try { [void]$externalUrls.Add(([uri]$vdir.msExchExternalHostName).Host) } catch {}
                        }
                    }
                    if ($vdirTypes.Count -gt 0) {
                        $srvObj | Add-Member -NotePropertyName 'VirtualDirectories' -NotePropertyValue (($vdirTypes.Keys | Sort-Object) -join ', ') -Force
                    }
                    if ($externalUrls.Count -gt 0) {
                        $srvObj | Add-Member -NotePropertyName 'ExternalHostnames' -NotePropertyValue ($externalUrls -join ', ') -Force
                    }
                }

                # Map SMTP Receive Connectors to this server
                $srvRecvConn = @($allRecvConnectors | Where-Object {
                    $_.distinguishedName -match "CN=$escapedSrvName,CN=Servers,"
                })
                if ($srvRecvConn.Count -gt 0) {
                    $srvObj | Add-Member -NotePropertyName 'SMTPReceiveConnectors' -NotePropertyValue "$($srvRecvConn.Count) connector(s)" -Force
                    $listeningPorts = [System.Collections.Generic.HashSet[string]]::new()
                    foreach ($rc in $srvRecvConn) {
                        $bindings = $rc.msExchSMTPReceiveBindings
                        if ($bindings) {
                            $bindStr = if ($bindings -is [array]) { $bindings -join ' ' } else { [string]$bindings }
                            $portMatches = [regex]::Matches($bindStr, ':(\d+)')
                            foreach ($pm in $portMatches) { [void]$listeningPorts.Add($pm.Groups[1].Value) }
                        }
                    }
                    if ($listeningPorts.Count -gt 0) {
                        $sortedPorts = $listeningPorts | Sort-Object { [int]$_ }
                        $srvObj | Add-Member -NotePropertyName 'SMTPListeningPorts' -NotePropertyValue ($sortedPorts -join ', ') -Force
                    }
                }

                $srvObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeConfigServer' -Force
                Show-Object $srvObj
            }

            # ===== Step 2: Enumerate Exchange Servers (Domain Partition - detailed) =====
            Show-SubHeader "Searching for Exchange servers..." -ObjectType "ExchangeServer"

            $exchangeServers = @()

            try {
                # Filter requires msExchCurrentServerRoles to have a value > 0 (valid Exchange role)
                $servers = Get-DomainComputer -LDAPFilter "(msExchCurrentServerRoles>=1)" @PSBoundParameters

                # Also check for Exchange Servers group membership
                $groupMembers = @()
                $exchangeServersGroup = @(Get-DomainGroup -Identity "Exchange Servers" @PSBoundParameters)[0]

                if ($exchangeServersGroup -and $exchangeServersGroup.member) {
                    foreach ($memberDN in $exchangeServersGroup.member) {
                        $memberObj = @(Get-DomainObject -Identity $memberDN @PSBoundParameters)[0]
                        if ($memberObj -and $memberObj.objectClass -icontains "computer") {
                            $groupMembers += $memberObj
                        }
                    }
                }

                # Merge results: servers from attributes + servers from group membership
                # Group membership is authoritative - if a computer is in "Exchange Servers" group, it's an Exchange server
                $allServers = @{}

                # Add servers found via attributes
                foreach ($srv in $servers) {
                    $key = if ($srv.distinguishedName) { $srv.distinguishedName } else { $srv.cn }
                    if (-not $allServers.ContainsKey($key)) {
                        $allServers[$key] = $srv
                    }
                }

                # Add servers found via group membership (these are authoritative)
                foreach ($srv in $groupMembers) {
                    $key = if ($srv.distinguishedName) { $srv.distinguishedName } else { $srv.cn }
                    if (-not $allServers.ContainsKey($key)) {
                        $allServers[$key] = $srv
                    }
                }

                $validServers = @($allServers.Values)

                foreach ($rawServer in $validServers) {
                    $rolesValue = if ($rawServer.msExchCurrentServerRoles) {
                        [int]$rawServer.msExchCurrentServerRoles
                    } else { 0 }

                    $versionValue = if ($rawServer.msExchVersion) {
                        [long]$rawServer.msExchVersion
                    } else { 0 }

                    # Decode server roles (bitfield)
                    $roles = @()
                    if ($rolesValue -band 2) { $roles += "Mailbox" }
                    if ($rolesValue -band 4) { $roles += "ClientAccess" }
                    if ($rolesValue -band 16) { $roles += "UnifiedMessaging" }
                    if ($rolesValue -band 32) { $roles += "HubTransport" }
                    if ($rolesValue -band 64) { $roles += "EdgeTransport" }

                    # Decode Exchange version. Major.Minor.Build.Revision encoded in long integer
                    # High 4 bits = Major, next 6 bits = Minor
                    $major = ($versionValue -shr 22) -band 0x3F
                    $minor = ($versionValue -shr 16) -band 0x3F
                    $build = ($versionValue -shr 0) -band 0xFFFF

                    $versionString = "$major.$minor.$build.0"

                    # Use the same Convert function for LDAP fallback
                    $exchangeVersion = Convert-ExchangeBuildToVersion -BuildNumber $versionString
                    $versionClass = Get-ExchangeVersionClass -BuildNumber $versionString
                    $isEOL = ($versionClass -eq "Finding")

                    $serverObj = [PSCustomObject]@{
                        ComputerName = if ($rawServer.cn) { $rawServer.cn } else { "Unknown" }
                        DNSHostName = if ($rawServer.dNSHostName) { $rawServer.dNSHostName } else { "Unknown" }
                        OperatingSystem = if ($rawServer.operatingSystem) { $rawServer.operatingSystem } else { "Unknown" }
                        Roles = $roles
                        RolesValue = $rolesValue
                        ExchangeVersion = $exchangeVersion
                        VersionString = $versionString
                        VersionValue = $versionValue
                        IsEOL = $isEOL
                        SPNs = @($rawServer.servicePrincipalName | Where-Object { $_ -match 'exchange|SMTP|HTTP' })
                        RawObject = $rawServer  # Store original object for Show-Object display
                    }

                    $exchangeServers += $serverObj
                }
            }
            catch {
                Write-Log "[Get-ExchangeInfrastructure] Error enumerating Exchange servers: $_" -Level Error
            }

            if (@($exchangeServers).Count -gt 0) {
                Show-Line "Exchange Organization: $organizationName - Found $(@($exchangeServers).Count) Exchange Server(s)" -Class Hint

                foreach ($exServer in $exchangeServers) {
                    # Get the raw object to add Exchange-specific attributes
                    $serverObject = $exServer.RawObject

                    if ($serverObject) {
                        # ===== HTTP-based Version Detection and Web Endpoint Analysis =====
                        # Try to get exact build number via HTTP/S, detect available endpoints,
                        # authentication methods, and EPA status - skip inactive servers to avoid timeouts
                        $webEnrollmentResult = $null

                        if ($exServer.DNSHostName -and $exServer.DNSHostName -ne "Unknown") {
                            # Check if server is inactive using Test-AccountActivity helper (uses $Script:DefaultInactiveDays)
                            $isInactive = $null -ne ($serverObject | Test-AccountActivity -IsInactive)

                            if ($isInactive) {
                                # Deliberately silent: the INACTIVE activity marker on the card
                                # already explains why no endpoints were probed.
                                Write-Log "[Get-ExchangeInfrastructure] Skipping HTTP check for $($exServer.DNSHostName) - server inactive"
                            } else {
                                # Fast TCP reachability check before expensive HTTP tests
                                # This avoids multiple 3-second timeouts for unreachable servers
                                $tcpReachable = $false
                                $tcpClient = $null
                                try {
                                    $tcpClient = New-Object System.Net.Sockets.TcpClient
                                    $connectResult = $tcpClient.BeginConnect($exServer.DNSHostName, 443, $null, $null)
                                    $tcpReachable = $connectResult.AsyncWaitHandle.WaitOne(2000, $false)  # 2 second timeout
                                    if ($tcpReachable) {
                                        $tcpClient.EndConnect($connectResult)
                                    }
                                }
                                catch {
                                    Write-Log "[Get-ExchangeInfrastructure] TCP check failed for $($exServer.DNSHostName): $_"
                                    $tcpReachable = $false
                                }
                                finally {
                                    if ($tcpClient) {
                                        try { $tcpClient.Close() } catch { }
                                        try { $tcpClient.Dispose() } catch { }
                                    }
                                }

                                if (-not $tcpReachable) {
                                    Write-Log "[Get-ExchangeInfrastructure] Skipping HTTP check for $($exServer.DNSHostName) - TCP port 443 not reachable"
                                } else {
                                    Write-Log "[Get-ExchangeInfrastructure] Detecting Exchange endpoints and EPA for $($exServer.DNSHostName)..."

                                    try {
                                        # Request with -TestEPA to check Extended Protection for Authentication
                                        $httpResult = Invoke-HTTPRequest -ScanExchange -Uri $exServer.DNSHostName -TestEPA
                                        $webEnrollmentResult = $httpResult

                                        if ($httpResult.Success) {
                                            $httpBuildNumber = $httpResult.BuildNumber
                                            $httpVersion = Convert-ExchangeBuildToVersion -BuildNumber $httpBuildNumber
                                            Write-Log "[Get-ExchangeInfrastructure] HTTP detection successful: $httpBuildNumber"

                                            # Add ExchangeVersion and ExchangeBuildNumber as properties to the object
                                            if ($httpBuildNumber) {
                                                $serverObject | Add-Member -NotePropertyName "ExchangeVersion" -NotePropertyValue $httpVersion -Force
                                                $serverObject | Add-Member -NotePropertyName "ExchangeBuildNumber" -NotePropertyValue $httpBuildNumber -Force
                                            }

                                            # Log EPA detection result
                                            if ($null -ne $httpResult.EPAEnabled) {
                                                Write-Log "[Get-ExchangeInfrastructure] EPA detection: Enabled=$($httpResult.EPAEnabled), Confidence=$($httpResult.EPAConfidence)"
                                            }
                                        }
                                    }
                                    catch {
                                        Write-Log "[Get-ExchangeInfrastructure] HTTP detection failed: $_"
                                    }
                                }

                                # Active server, but the probe did not reach it (TCP port filtered
                                # or HTTP/HTTPS blocked). Surface it the same way as other web checks
                                # so a missing WebEndpoints row is not misread as "no web endpoints".
                                Show-WebEndpointUnreachable -ProbeResult $webEnrollmentResult -Hostname $exServer.DNSHostName -CheckLabel 'Exchange endpoint check'
                            }
                        }

                        # Add roles if available
                        if ($exServer.Roles -and @($exServer.Roles).Count -gt 0) {
                            $serverObject | Add-Member -NotePropertyName "ExchangeRoles" -NotePropertyValue ($exServer.Roles -join ', ') -Force
                        }

                        # Add protocol availability
                        if ($webEnrollmentResult) {
                            $serverObject | Add-Member -NotePropertyName "HttpAvailable" -NotePropertyValue $webEnrollmentResult.HttpAvailable -Force
                            $serverObject | Add-Member -NotePropertyName "HttpsAvailable" -NotePropertyValue $webEnrollmentResult.HttpsAvailable -Force

                            # Build WebEndpoints array with auth methods and EPA status
                            # Format: "OWA via HTTPS (NTLM, Negotiate) [EPA: Disabled]"
                            # Show HTTP and HTTPS as separate lines (EPA only relevant for HTTPS)
                            $activeEndpoints = @()
                            $endpointAuthMethods = @{}

                            foreach ($ep in @('OWA', 'ECP', 'EWS', 'Autodiscover', 'MAPI', 'RPC', 'PowerShell', 'ActiveSync')) {
                                if ($webEnrollmentResult.Endpoints.$ep.Available) {
                                    $activeEndpoints += $ep
                                    if ($webEnrollmentResult.Endpoints.$ep.AuthMethods) {
                                        $endpointAuthMethods[$ep] = $webEnrollmentResult.Endpoints.$ep.AuthMethods
                                    }
                                }
                            }

                            if (@($activeEndpoints).Count -gt 0) {
                                $endpointsWithAuth = @()

                                foreach ($ep in $activeEndpoints) {
                                    $authMethods = $endpointAuthMethods[$ep]
                                    $epData = $webEnrollmentResult.Endpoints.$ep

                                    # Render each endpoint by ITS OWN transport (not the global
                                    # protocol flags) so an HTTPS-only endpoint such as EWS/MAPI is
                                    # not dropped when only OWA was reachable via HTTP (and vice versa).
                                    # Show HTTP line if reachable via HTTP (no EPA - not applicable for HTTP)
                                    if ($epData.AvailableHttp) {
                                        $epString = "$ep via HTTP"
                                        if ($authMethods) {
                                            $epString += " ($authMethods)"
                                        }
                                        $endpointsWithAuth += $epString
                                    }

                                    # Show HTTPS line if reachable via HTTPS (with EPA status if tested)
                                    if ($epData.AvailableHttps) {
                                        $epString = "$ep via HTTPS"
                                        if ($authMethods) {
                                            $epString += " ($authMethods)"
                                        }
                                        # Add EPA status only for HTTPS (EPA is TLS-based)
                                        if ($null -ne $epData.EPAEnabled) {
                                            $epaStatus = if ($epData.EPAEnabled -eq $true) { "Enabled" } else { "Disabled" }
                                            $epString += " [EPA: $epaStatus]"
                                        }
                                        $endpointsWithAuth += $epString
                                    }
                                }

                                $serverObject | Add-Member -NotePropertyName 'WebEndpoints' -NotePropertyValue $endpointsWithAuth -Force
                            }

                            # Add legacy EPA properties (for quick reference)
                            if ($null -ne $webEnrollmentResult.EPAEnabled) {
                                $serverObject | Add-Member -NotePropertyName 'EPAEnabled' -NotePropertyValue $webEnrollmentResult.EPAEnabled -Force
                                $serverObject | Add-Member -NotePropertyName 'EPAConfidence' -NotePropertyValue $webEnrollmentResult.EPAConfidence -Force
                            }
                        }

                        # Add type marker for reliable detection in HTML report
                        $serverObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeServer' -Force
                        # Set ExchangeVersion/BuildNumber from LDAP fallback only if HTTP didn't detect them
                        # and only if we actually have a valid version (not "Unknown" or "0.0.0.0")
                        if (-not $serverObject.ExchangeVersion -and $exServer.ExchangeVersion -and $exServer.ExchangeVersion -ne "Unknown Exchange Version") {
                            $serverObject | Add-Member -NotePropertyName "ExchangeVersion" -NotePropertyValue $exServer.ExchangeVersion -Force
                        }
                        if (-not $serverObject.ExchangeBuildNumber -and $exServer.VersionString -and $exServer.VersionString -ne "0.0.0.0") {
                            $serverObject | Add-Member -NotePropertyName "ExchangeBuildNumber" -NotePropertyValue $exServer.VersionString -Force
                        }
                        $displayVersion = if ($serverObject.ExchangeVersion) { $serverObject.ExchangeVersion } else { $exServer.ExchangeVersion }
                        # Only set context if we have a valid version (not "Unknown Exchange Version")
                        if ($displayVersion -and $displayVersion -ne "Unknown Exchange Version") {
                            $serverObject | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue $displayVersion -Force
                        }

                        # Output the enriched server object via Show-Object
                        Show-Object $serverObject
                    } else {
                        # Fallback: show basic info if RawObject not available
                        Show-KeyValue "ComputerName" -Value $exServer.ComputerName
                        if ($exServer.DNSHostName -and $exServer.DNSHostName -ne "Unknown") {
                            Show-KeyValue "DNSHostName" -Value $exServer.DNSHostName
                        }
                    }
                }
            } else {
                Show-Line "Exchange Organization: $organizationName - No active Exchange Servers found" -Class Note
            }

            # ===== Step 3: Check Exchange Trusted Subsystem =====
            Show-SubHeader "Checking Exchange Trusted Subsystem group..." -ObjectType "ExchangeTrustedSubsystem"

            try {
                # Use Get-DomainGroup to find Exchange Trusted Subsystem
                $trustedSubsystem = @(Get-DomainGroup -Identity "Exchange Trusted Subsystem" @PSBoundParameters)[0]

                if ($trustedSubsystem) {
                    $members = @($trustedSubsystem.member)

                    if (@($members).Count -gt 0) {
                        Show-Line "Found $(@($members).Count) member(s) in Exchange Trusted Subsystem:" -Class Hint

                        foreach ($memberDN in $members) {
                            # Use Get-DomainObject to retrieve full member object
                            try {
                                $memberObj = @(Get-DomainObject -Identity $memberDN @PSBoundParameters)[0]

                                if ($memberObj) {
                                    # Add type marker for reliable detection in HTML report
                                    $memberObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeTrustedSubsystem' -Force
                                    $memberObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Exchange Trusted Subsystem' -Force
                                    Show-Object $memberObj
                                }
                            }
                            catch {
                                Write-Log "[Get-ExchangeInfrastructure] Error resolving member ${memberDN}: ${_}"
                                # Fallback: Extract CN from DN
                                if ($memberDN -match 'CN=([^,]+)') {
                                    Show-Line "$($matches[1])" -Class Note
                                }
                            }
                        }
                    } else {
                        Show-Line "Exchange Trusted Subsystem group exists but has no members (unusual)" -Class Note
                    }
                } else {
                    Write-Log "[Get-ExchangeInfrastructure] Exchange Trusted Subsystem group not Found"
                }
            }
            catch {
                Write-Log "[Get-ExchangeInfrastructure] Error checking Exchange Trusted Subsystem: $_" -Level Error
            }

            # ===== Step 4: Check Exchange Windows Permissions =====
            Show-SubHeader "Checking Exchange Windows Permissions group..." -ObjectType "ExchangeWindowsPermissions"

            try {
                # Use Get-DomainGroup
                $windowsPermissions = @(Get-DomainGroup -Identity "Exchange Windows Permissions" @PSBoundParameters)[0]

                if ($windowsPermissions) {
                    $members = @($windowsPermissions.member)

                    if (@($members).Count -gt 0) {
                        Show-Line "Found $(@($members).Count) member(s) in Exchange Windows Permissions:" -Class Hint

                        foreach ($memberDN in $members) {
                            try {
                                $memberObj = @(Get-DomainObject -Identity $memberDN @PSBoundParameters)[0]

                                if ($memberObj) {
                                    # Add type marker for reliable detection in HTML report
                                    $memberObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeWindowsPermissions' -Force
                                    $memberObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Exchange Windows Permissions' -Force
                                    Show-Object $memberObj
                                }
                            }
                            catch {
                                Write-Log "[Get-ExchangeInfrastructure] Error resolving member ${memberDN}: ${_}"
                                if ($memberDN -match 'CN=([^,]+)') {
                                    Show-Line "$($matches[1])" -Class Note
                                }
                            }
                        }
                    }
                } else {
                    Write-Log "[Get-ExchangeInfrastructure] Exchange Windows Permissions group not found"
                }
            }
            catch {
                Write-Log "[Get-ExchangeInfrastructure] Error checking Exchange Windows Permissions: $_" -Level Error
            }

            # ===== Step 5: Check Organization Management =====
            Show-SubHeader "Checking Organization Management group..." -ObjectType "ExchangeOrganizationManagement"

            try {
                # Use Get-DomainGroup
                $orgManagement = @(Get-DomainGroup -Identity "Organization Management" @PSBoundParameters)[0]

                if ($orgManagement) {
                    $members = @($orgManagement.member)

                    if (@($members).Count -gt 0) {
                        Show-Line "Found $(@($members).Count) member(s) in Organization Management:" -Class Hint

                        foreach ($memberDN in $members) {
                            try {
                                $memberObj = @(Get-DomainObject -Identity $memberDN @PSBoundParameters)[0]

                                if ($memberObj) {
                                    # Add type marker for reliable detection in HTML report
                                    $memberObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ExchangeOrganizationManagement' -Force
                                    $memberObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Organization Management' -Force
                                    Show-Object $memberObj
                                }
                            }
                            catch {
                                Write-Log "[Get-ExchangeInfrastructure] Error resolving member ${memberDN}: ${_}"
                                if ($memberDN -match 'CN=([^,]+)') {
                                    Show-Line "$($matches[1])" -Class Note
                                }
                            }
                        }
                    } else {
                        Show-Line "Organization Management group exists but has no members (unusual)" -Class Note
                    }
                }
            }
            catch {
                Write-Log "[Get-ExchangeInfrastructure] Error checking Organization Management: $_" -Level Error
            }

            # ===== Summary & Recommendations =====
            # No additional summary needed - org info is shown with server count in Step 2

        }
        catch {
            Write-Log "[Get-ExchangeInfrastructure] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ExchangeInfrastructure] Check completed"
    }
}



# ----- Get-SCCMInfrastructure.ps1 -----

function Get-SCCMInfrastructure {
    <#
    .SYNOPSIS
    Detects Microsoft System Center Configuration Manager (SCCM/MECM) infrastructure.

    .DESCRIPTION
    Performs passive detection of SCCM/MECM infrastructure components using LDAP queries.
    Identifies site servers, management points, site hierarchy, service accounts, PXE/WDS servers, and the System Management container.

    Detection Methods:
    1. System Management container (CN=System Management,CN=System,<Domain DN>)
    2. mSSMSSite objects (SCCM site codes and hierarchy)
    3. mSSMSManagementPoint objects (MP hostnames, site type determination)
    4. Computers with SCCM-related SPNs (SMS*, SMSSQLBKUP*)
    5. PXE/WDS boot servers (connectionPoint, intellimirrorSCP)
    6. User accounts with SCCM-related SPNs
    7. SCCM-related security groups (*SCCM*, *SMS*, *ConfigMgr*, *MECM*)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-SCCMInfrastructure

    .EXAMPLE
    Get-SCCMInfrastructure -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Application
    Author: Alexander Sturz (@_61106960_)
    Based on research from Misconfiguration-Manager (@subat0mik)
    Reference: https://github.com/subat0mik/Misconfiguration-Manager
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-SCCMInfrastructure] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                # Return without output to avoid redundant error display
                return
            }

            $domainDN = $Script:LDAPContext.DomainDN

            # ===== Step 1: Check for SCCM Infrastructure =====
            Show-SubHeader "Checking for SCCM/MECM infrastructure..." -ObjectType "SCCMServer"

            $sccmDetected = $false
            $systemManagementPath = "CN=System Management,CN=System,$domainDN"
            $systemMgmt = $null

            # Detection Method 1: System Management Container
            try {
                $systemMgmt = Get-DomainObject -Identity $systemManagementPath @PSBoundParameters
                if ($systemMgmt) {
                    $sccmDetected = $true
                }
            } catch {
                Write-Log "[Get-SCCMInfrastructure] System Management container not found"
            }

            # Detection Method 2: SCCM SPNs on computers (lightweight, only for detection)
            if (-not $sccmDetected) {
                $sccmDetectionComputers = Get-DomainComputer -LDAPFilter "(servicePrincipalName=SMS*)" -Properties "cn" @PSBoundParameters
                if ($sccmDetectionComputers) {
                    $sccmDetected = $true
                }
            }

            # Detection Method 3: SCCM-related groups (lightweight, only for detection)
            if (-not $sccmDetected) {
                $sccmDetectionGroups = Get-DomainGroup -LDAPFilter "(|(cn=*SCCM*)(cn=*ConfigMgr*)(cn=*MECM*))" -Properties "cn" @PSBoundParameters
                if ($sccmDetectionGroups) {
                    $sccmDetected = $true
                }
            }

            # If no SCCM detected, stop here
            if (-not $sccmDetected) {
                Show-Line "No SCCM/MECM infrastructure detected" -Class Note
                return
            }

            # ===== SCCM Detected - Continue with detailed enumeration =====
            Show-Line "SCCM/MECM infrastructure detected" -Class Hint

            # ===== Step 2: System Management Container Details =====
            Show-SubHeader "Analyzing System Management container..." -ObjectType "SCCMServer"

            # Reuse result from Detection Method 1 (no duplicate query)
            if ($systemMgmt) {
                Show-Line "System Management container found at: $systemManagementPath" -Class Hint
            } else {
                Show-Line "System Management container not found (unusual if SCCM detected)" -Class Hint
            }

            # ===== Step 3: SCCM Sites via mSSMSSite =====
            Show-SubHeader "Enumerating SCCM sites from AD schema objects..." -ObjectType "SCCMSite"

            $sccmSiteInfos = @{}  # Hashtable for cross-reference in Step 4

            try {
                $sccmSiteObjects = @(Get-DomainObject -LDAPFilter "(objectClass=mSSMSSite)" -SearchBase $systemManagementPath -Properties "mSSMSSiteCode","mSSMSSourceForest","mSSMSHealthState","cn","distinguishedName" @PSBoundParameters)

                if ($sccmSiteObjects.Count -gt 0) {
                    Show-Line "Found $($sccmSiteObjects.Count) SCCM site(s) published to Active Directory" -Class Hint

                    foreach ($site in $sccmSiteObjects) {
                        $siteCode = $site.mSSMSSiteCode
                        $sourceForest = $site.mSSMSSourceForest

                        # Extract GUID from mSSMSHealthState (format: "SITECODE.{GUID}")
                        $siteGuid = $null
                        if ($site.mSSMSHealthState -match '\{([0-9a-fA-F\-]+)\}') {
                            $siteGuid = $Matches[1]
                        }

                        # Store for cross-reference with management points
                        if ($siteCode) {
                            $sccmSiteInfos[$siteCode] = @{
                                SourceForest = $sourceForest
                                SiteGuid = $siteGuid
                                CN = $site.cn
                            }
                        }

                        # Build display object for Show-Object (dynamic fallback renders all properties)
                        $siteObj = [PSCustomObject]@{
                            Name = $siteCode
                            SiteCode = $siteCode
                            SourceForest = $sourceForest
                            SiteGUID = $siteGuid
                            DistinguishedName = $site.distinguishedName
                        }
                        $siteObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMSite' -Force
                        Show-Object $siteObj
                    }
                } else {
                    Show-Line "No mSSMSSite objects found in System Management container" -Class Note
                }
            } catch {
                Write-Log "[Get-SCCMInfrastructure] Error querying mSSMSSite: $_" -Level Warning
            }

            # ===== Step 4: Management Points + Site Hierarchy =====
            Show-SubHeader "Enumerating SCCM Management Points and site hierarchy..." -ObjectType "SCCMManagementPoint"

            $casDetected = $false

            try {
                $mgmtPoints = @(Get-DomainObject -LDAPFilter "(objectClass=mSSMSManagementPoint)" -SearchBase $systemManagementPath -Properties "mSSMSMPName","mSSMSSiteCode","mSSMSCapabilities","cn","distinguishedName" @PSBoundParameters)

                if ($mgmtPoints.Count -gt 0) {
                    Show-Line "Found $($mgmtPoints.Count) SCCM Management Point(s)" -Class Hint

                    foreach ($mp in $mgmtPoints) {
                        $mpName = $mp.mSSMSMPName
                        $mpSiteCode = $mp.mSSMSSiteCode

                        # Parse mSSMSCapabilities XML for site hierarchy
                        $cmdLineSiteCode = $null
                        $rootSiteCode = $null
                        $forest = $null
                        $siteType = "Unknown"

                        if ($mp.mSSMSCapabilities) {
                            $xmlText = [string]$mp.mSSMSCapabilities
                            try {
                                # Clean entities for safe XML parsing
                                $xmlText = $xmlText -replace '&(?!amp;|lt;|gt;|quot;|apos;)', '&amp;'
                                $xmlDoc = [xml]$xmlText

                                # Extract CommandLine SMSSITECODE
                                $cmdLine = $xmlDoc.ClientOperationalSettings.CCM.CommandLine
                                if ($cmdLine -match 'SMSSITECODE=(\w+)') {
                                    $cmdLineSiteCode = $Matches[1]
                                }

                                # Extract RootSiteCode
                                $rootSiteCode = $xmlDoc.ClientOperationalSettings.RootSiteCode

                                # Extract Forest
                                $forest = $xmlDoc.ClientOperationalSettings.Forest.Value
                            } catch {
                                # XML parsing failed - try regex fallback for SMSSITECODE
                                if ($xmlText -match 'SMSSITECODE=(\w+)') {
                                    $cmdLineSiteCode = $Matches[1]
                                }
                                Write-Log "[Get-SCCMInfrastructure] XML parse warning for MP $mpName - using regex fallback" -Level Warning
                            }
                        }

                        # Determine site type (same logic as ConfigManBearPig)
                        if ($cmdLineSiteCode -and $mpSiteCode) {
                            if ($cmdLineSiteCode -eq $mpSiteCode) {
                                $siteType = "Primary Site"
                            } elseif ($rootSiteCode -eq $mpSiteCode) {
                                $siteType = "Central Administration Site (CAS)"
                                $casDetected = $true
                            } else {
                                $siteType = "Secondary Site"
                            }
                        }

                        # Build display object for Show-Object
                        $mpObj = [PSCustomObject]@{
                            Name = $mpName
                            ManagementPoint = $mpName
                            SiteCode = $mpSiteCode
                            SiteType = $siteType
                        }
                        if ($cmdLineSiteCode -and $cmdLineSiteCode -ne $mpSiteCode) {
                            $mpObj | Add-Member -NotePropertyName 'CommandLineSiteCode' -NotePropertyValue $cmdLineSiteCode -Force
                        }
                        if ($rootSiteCode) {
                            $mpObj | Add-Member -NotePropertyName 'RootSiteCode' -NotePropertyValue $rootSiteCode -Force
                        }
                        if ($forest) {
                            $mpObj | Add-Member -NotePropertyName 'Forest' -NotePropertyValue $forest -Force
                        }
                        $mpObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMManagementPoint' -Force
                        Show-Object $mpObj
                    }

                    # CAS Finding
                    if ($casDetected) {
                        Show-Line "Central Administration Site (CAS) detected - multi-site SCCM hierarchy" -Class Finding -FindingId "SCCM_SITE_HIERARCHY"
                    }
                } else {
                    Show-Line "No mSSMSManagementPoint objects found in System Management container" -Class Note
                }
            } catch {
                Write-Log "[Get-SCCMInfrastructure] Error querying mSSMSManagementPoint: $_" -Level Warning
            }

            # ===== Step 5: Enumerate SCCM Servers =====
            Show-SubHeader "Searching for SCCM site servers..." -ObjectType "SCCMServer"

            $sccmServers = [System.Collections.ArrayList]::new()
            $seenServerDNs = @{}

            $servers = Get-DomainComputer -LDAPFilter "(|(servicePrincipalName=SMS*)(servicePrincipalName=SMSSQLBKUP*))" @PSBoundParameters

            if ($servers) {
                foreach ($server in @($servers)) {
                    $dn = $server.distinguishedName
                    if ($dn -and -not $seenServerDNs.ContainsKey($dn)) {
                        $seenServerDNs[$dn] = $true
                        [void]$sccmServers.Add($server)
                    }
                }
            }

            if ($sccmServers.Count -gt 0) {
                Show-Line "Found $($sccmServers.Count) SCCM server(s)" -Class Hint

                foreach ($server in $sccmServers) {
                    $server | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMServer' -Force
                    Show-Object $server
                }
            } else {
                Show-Line "No SCCM servers found via SPN detection" -Class Note
            }

            # ===== Step 6: PXE/WDS Discovery =====
            Show-SubHeader "Searching for PXE/WDS boot servers..." -ObjectType "SCCMPXEServer"

            $pxeServersFound = $false

            try {
                # PXE Boot Servers via connectionPoint with netbootserver
                $pxePoints = @(Get-DomainObject -LDAPFilter "(&(objectClass=connectionPoint)(netbootserver=*))" -Properties "cn","distinguishedName","netbootserver" @PSBoundParameters)

                if ($pxePoints.Count -gt 0) {
                    $pxeServersFound = $true
                    Show-Line "Found $($pxePoints.Count) PXE boot server(s)" -Class Hint

                    foreach ($pxe in $pxePoints) {
                        $parentDN = $pxe.distinguishedName -replace '^[^,]+,', ''
                        $pxeObj = [PSCustomObject]@{
                            Name = $pxe.netbootserver
                            PXEServer = $pxe.netbootserver
                            ParentObject = $parentDN
                        }
                        $pxeObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMPXEServer' -Force
                        Show-Object $pxeObj
                    }
                }
            } catch {
                Write-Log "[Get-SCCMInfrastructure] Error querying PXE connectionPoints: $_" -Level Warning
            }

            try {
                # WDS Service Connection Points
                $wdsPoints = @(Get-DomainObject -LDAPFilter "(objectClass=intellimirrorSCP)" -Properties "cn","distinguishedName","serviceBindingInformation" @PSBoundParameters)

                if ($wdsPoints.Count -gt 0) {
                    $pxeServersFound = $true
                    Show-Line "Found $($wdsPoints.Count) WDS service connection point(s)" -Class Hint

                    foreach ($wds in $wdsPoints) {
                        $parentDN = $wds.distinguishedName -replace '^[^,]+,', ''
                        $wdsObj = [PSCustomObject]@{
                            Name = $wds.cn
                            WDSServicePoint = $wds.cn
                            ParentObject = $parentDN
                        }
                        if ($wds.serviceBindingInformation) {
                            $wdsObj | Add-Member -NotePropertyName 'BindingInfo' -NotePropertyValue $wds.serviceBindingInformation -Force
                        }
                        $wdsObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMPXEServer' -Force
                        Show-Object $wdsObj
                    }
                }
            } catch {
                Write-Log "[Get-SCCMInfrastructure] Error querying intellimirrorSCP: $_" -Level Warning
            }

            if ($pxeServersFound) {
                Show-Line "PXE/WDS servers detected" -Class Hint -FindingId "SCCM_PXE_EXPOSURE"
            } else {
                Show-Line "No PXE/WDS boot servers found" -Class Note
            }

            # ===== Step 7: SCCM Service Accounts =====
            Show-SubHeader "Searching for SCCM service accounts..." -ObjectType "SCCMServiceAccount"

            $serviceAccounts = Get-DomainUser -LDAPFilter "(servicePrincipalName=SMS*)" @PSBoundParameters

            if ($serviceAccounts) {
                Show-Line "Found $(@($serviceAccounts).Count) SCCM service account(s) with SMS* SPN" -Class Hint -FindingId "SCCM_SERVICE_ACCOUNT"

                foreach ($account in $serviceAccounts) {
                    $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMServiceAccount' -Force
                    Show-Object $account
                }
            } else {
                Show-Line "No SCCM service accounts found" -Class Secure
            }

            # ===== Step 8: SCCM-Related Groups =====
            Show-SubHeader "Searching for SCCM-related security groups..." -ObjectType "SCCMGroup"

            # Single LDAP query with OR filter (SMS_SiteToSiteConnection_ is SCCM-specific, avoids generic *SMS* false positives)
            $sccmGroupsFound = [System.Collections.ArrayList]::new()
            $seenGroupDNs = @{}

            $groups = Get-DomainGroup -LDAPFilter "(|(cn=*SCCM*)(cn=SMS_SiteToSiteConnection_*)(cn=SMS_SiteSystemToSiteServerConnection_*)(cn=*ConfigMgr*)(cn=*MECM*))" @PSBoundParameters

            if ($groups) {
                foreach ($group in @($groups)) {
                    $dn = $group.distinguishedName
                    if ($dn -and -not $seenGroupDNs.ContainsKey($dn)) {
                        $seenGroupDNs[$dn] = $true
                        [void]$sccmGroupsFound.Add($group)
                    }
                }
            }

            if ($sccmGroupsFound.Count -gt 0) {
                Show-Line "Found $($sccmGroupsFound.Count) SCCM-related group(s)" -Class Hint

                foreach ($group in $sccmGroupsFound) {
                    # Add member count without resolving individual members (avoids O(n) LDAP queries)
                    $memberCount = 0
                    if ($group.member) {
                        $memberCount = @($group.member).Count
                    }
                    $group | Add-Member -NotePropertyName 'MemberCount' -NotePropertyValue "$memberCount member(s)" -Force
                    # Remove member attribute to prevent Extended-attribute rendering from triggering
                    # per-DN SID resolution (Convert-DNsToMemberInfo -> ConvertTo-SID per member)
                    $group.PSObject.Properties.Remove('member')
                    $group | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCCMGroup' -Force
                    Show-Object $group
                }
            } else {
                Show-Line "No SCCM-related groups found" -Class Note
            }

        } catch {
            Write-Log "[Get-SCCMInfrastructure] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-SCCMInfrastructure] Check completed"
    }
}



# ----- Get-SCOMInfrastructure.ps1 -----

function Get-SCOMInfrastructure {
    <#
    .SYNOPSIS
    Detects Microsoft System Center Operations Manager (SCOM) infrastructure.

    .DESCRIPTION
    Performs passive detection of SCOM infrastructure components using LDAP queries.
    Identifies management servers, service accounts, and SCOM-related security groups.

    Detection Methods:
    1. Computers with SCOM-related SPNs (MSOMSdkSvc/*, MSOMHSvc/*)
    2. User accounts with SCOM-related SPNs
    3. SCOM-related security groups (*SCOM*, *OpsMgr*, *Operations Manager*)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-SCOMInfrastructure

    .EXAMPLE
    Get-SCOMInfrastructure -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Application
    Author: Alexander Sturz (@_61106960_)
    Based on research from SharpSCOM (@breakfix)
    Reference: https://github.com/breakfix/SharpSCOM
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-SCOMInfrastructure] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                # Return without output to avoid redundant error display
                return
            }

            # ===== Step 1: Check for SCOM Infrastructure =====
            Show-SubHeader "Checking for SCOM infrastructure..." -ObjectType "SCOMServer"

            $scomDetected = $false

            # Detection Method 1: SCOM SPNs on computers (SDK Service, Health Service)
            $scomSPNPatterns = @("MSOMSdkSvc*", "MSOMHSvc*")
            foreach ($spnPattern in $scomSPNPatterns) {
                $scomComputers = Get-DomainComputer -LDAPFilter "(servicePrincipalName=$spnPattern)" @PSBoundParameters
                if ($scomComputers) {
                    $scomDetected = $true
                    break
                }
            }

            # Detection Method 2: SCOM-related groups (with word boundary filtering)
            if (-not $scomDetected) {
                $allGroups = Get-DomainGroup -LDAPFilter "(|(cn=*SCOM*)(cn=*OpsMgr*)(cn=*Operations Manager*))" @PSBoundParameters
                if ($allGroups) {
                    # Apply word boundary regex to avoid false positives (e.g., "TeamsCommunicationsCom")
                    $filteredGroups = @($allGroups | Where-Object {
                        $_.cn -match '\bSCOM\b' -or
                        $_.cn -match '\bOpsMgr\b' -or
                        $_.cn -match 'Operations\s+Manager'
                    })
                    if ($filteredGroups.Count -gt 0) {
                        $scomDetected = $true
                    }
                }
            }

            # If no SCOM detected, stop here
            if (-not $scomDetected) {
                Show-Line "No SCOM infrastructure detected" -Class Note
                return
            }

            # ===== SCOM Detected - Continue with detailed enumeration =====
            Show-Line "SCOM infrastructure detected" -Class Hint

            # ===== Step 2: Enumerate SCOM Management Servers =====
            Show-SubHeader "Searching for SCOM management servers..." -ObjectType "SCOMServer"

            $scomServers = @()

            foreach ($spnPattern in $scomSPNPatterns) {
                $servers = Get-DomainComputer -LDAPFilter "(servicePrincipalName=$spnPattern)" @PSBoundParameters

                if ($servers) {
                    foreach ($server in $servers) {
                        # Avoid duplicates
                        if ($server.dNSHostName -notin $scomServers.dNSHostName) {
                            $scomServers += $server
                        }
                    }
                }
            }

            if (@($scomServers).Count -gt 0) {
                Show-Line "Found $(@($scomServers).Count) SCOM management server(s)" -Class Hint

                foreach ($server in $scomServers) {
                    $server | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCOMServer' -Force
                    Show-Object $server
                }
            } else {
                Show-Line "No SCOM management servers found via SPN detection" -Class Note
            }

            # ===== Step 3: SCOM Service Accounts =====
            Show-SubHeader "Searching for SCOM service accounts..." -ObjectType "SCOMServer"

            $serviceAccounts = @()

            foreach ($spnPattern in $scomSPNPatterns) {
                $accounts = Get-DomainUser -LDAPFilter "(servicePrincipalName=$spnPattern)" @PSBoundParameters

                if ($accounts) {
                    foreach ($account in $accounts) {
                        if ($account.sAMAccountName -notin $serviceAccounts.sAMAccountName) {
                            $serviceAccounts += $account
                        }
                    }
                }
            }

            if (@($serviceAccounts).Count -gt 0) {
                Show-Line "Found $(@($serviceAccounts).Count) SCOM service account(s)" -Class Hint

                foreach ($account in $serviceAccounts) {
                    $account | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCOMServiceAccount' -Force
                    Show-Object $account
                }
            } else {
                Show-Line "No SCOM service accounts found" -Class Note
            }

            # ===== Step 4: SCOM-Related Security Groups =====
            Show-SubHeader "Searching for SCOM-related security groups..." -ObjectType "SCOMServer"

            # Broad LDAP query to get potential SCOM groups
            $allGroups = Get-DomainGroup -LDAPFilter "(|(cn=*SCOM*)(cn=*OpsMgr*)(cn=*Operations Manager*))" @PSBoundParameters

            # Client-side filtering with word boundary regex to eliminate false positives
            # (e.g., "TeamsCommunicationsCom" should NOT match)
            $scomGroupsFound = @()
            if ($allGroups) {
                $scomGroupsFound = @($allGroups | Where-Object {
                    $_.cn -match '\bSCOM\b' -or
                    $_.cn -match '\bOpsMgr\b' -or
                    $_.cn -match 'Operations\s+Manager'
                })
            }

            if (@($scomGroupsFound).Count -gt 0) {
                Show-Line "Found $(@($scomGroupsFound).Count) SCOM-related group(s)" -Class Hint

                foreach ($group in $scomGroupsFound) {
                    # Add member count without resolving individual members (avoids O(n) LDAP queries)
                    $memberCount = 0
                    if ($group.member) {
                        $memberCount = @($group.member).Count
                    }
                    $group | Add-Member -NotePropertyName 'MemberCount' -NotePropertyValue "$memberCount member(s)" -Force
                    # Remove member attribute to prevent Extended-attribute rendering from triggering
                    # per-DN SID resolution (Convert-DNsToMemberInfo -> ConvertTo-SID per member)
                    $group.PSObject.Properties.Remove('member')
                    $group | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SCOMGroup' -Force
                    Show-Object $group
                }
            } else {
                Show-Line "No SCOM-related groups found" -Class Note
            }

        } catch {
            Write-Log "[Get-SCOMInfrastructure] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-SCOMInfrastructure] Check completed"
    }
}



# ----- Get-KerberoastableAccounts.ps1 -----

function Get-KerberoastableAccounts {
    <#
    .SYNOPSIS
    Identifies user accounts vulnerable to Kerberoasting attacks.

    .DESCRIPTION
    Finds user accounts with Service Principal Names (SPNs) that are vulnerable to Kerberoasting - attackers can request TGS tickets and attempt offline password cracking.

    Detects:
    - User accounts with SPNs set
    - Enabled accounts only
    - Excludes krbtgt account

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER OPSEC
    If specified, skips active testing (TGS ticket requests) for stealth.
    By default, performs active testing to prove vulnerability.

    .EXAMPLE
    Get-KerberoastableAccounts

    .EXAMPLE
    Get-KerberoastableAccounts -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC
    )

    begin {
        Write-Log "[Get-KerberoastableAccounts] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude OPSEC which Ensure-LDAPConnection doesn't accept)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for Kerberoastable accounts (users with SPNs)..." -ObjectType "Kerberoastable"

            # Use optimized filters: -SPN (has SPN), -Enabled (not disabled), additional filter: exclude krbtgt
            $kerberoastableUsers = @(Get-DomainUser -SPN -Enabled -LDAPFilter "(!(samAccountName=krbtgt))" -ShowOwner @connectionParams)

            if (@($kerberoastableUsers).Count -gt 0) {
                Show-Line "Found $(@($kerberoastableUsers).Count) kerberoastable user account(s):" -Class "Finding"

                # Determine testing mode based on OPSEC flag
                $canTestKerberoasting = -not $OPSEC

                if ($OPSEC) {
                    Show-Line "Skipping hash extraction (OPSEC mode)" -Class "Hint"
                }

                # Check if credentials are available for in-memory Kerberoasting (non-Kerberos auth)
                # Kerberos/WindowsSSPI auth has a TGT in the ticket cache - Windows API works directly
                # All other auth methods (SimpleBind, NTLM Impersonation) need credentials for in-memory TGS requests
                $authMethod = if ($Script:LDAPContext -and $Script:LDAPContext['AuthMethod']) {
                    $Script:LDAPContext['AuthMethod']
                } else {
                    'Unknown'
                }

                if ($authMethod -notin @('Kerberos', 'WindowsSSPI') -and $canTestKerberoasting) {
                    $hasCredentials = $false
                    if ($Credential) {
                        $hasCredentials = $true
                    } elseif ($Script:LDAPContext -and $Script:LDAPContext['Credential']) {
                        $hasCredentials = $true
                    }

                    if (-not $hasCredentials) {
                        Show-Line "Kerberoasting skipped - no credentials available (use -Credential or Connect-adPEAS -Credential)" -Class Finding
                        $canTestKerberoasting = $false
                    }
                }

                $totalUsers = @($kerberoastableUsers).Count
                $currentIndex = 0
                foreach ($user in $kerberoastableUsers) {
                    $currentIndex++
                    if ($totalUsers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing Kerberoastable accounts" -Current $currentIndex -Total $totalUsers -ObjectName $user.sAMAccountName }
                    # If testing enabled, request TGS and add hash as attribute
                    # Invoke-Kerberoast automatically selects the right method (Windows API vs In-Memory)
                    if ($canTestKerberoasting) {
                        Write-Log "[Get-KerberoastableAccounts] Kerberoasting $($user.sAMAccountName)"

                        try {
                            # Use pipeline input - Invoke-Kerberoast handles method selection automatically
                            $kerberoastResult = $user | Invoke-Kerberoast @connectionParams

                            if ($kerberoastResult -and $kerberoastResult.Success -and $kerberoastResult.Hash) {
                                # Add hash info as attributes to the user object
                                $hashLabel = "Hashcat (mode $($kerberoastResult.HashcatMode), $($kerberoastResult.EncryptionTypeName))"
                                $user | Add-Member -NotePropertyName 'KerberoastingHash' -NotePropertyValue $kerberoastResult.Hash -Force
                                $user | Add-Member -NotePropertyName 'KerberoastingHashType' -NotePropertyValue $hashLabel -Force
                                $user | Add-Member -NotePropertyName 'KerberoastEncryption' -NotePropertyValue $kerberoastResult.EncryptionType -Force
                            }
                            elseif ($kerberoastResult -and $kerberoastResult.Error) {
                                # Check if it's a credential/Kerberos issue
                                if ($kerberoastResult.Error -match 'NetworkCredentials|Kerberos credential|unable to create|No credentials') {
                                    $user | Add-Member -NotePropertyName 'KerberoastError' -NotePropertyValue "TGS request failed - no valid Kerberos credentials available" -Force
                                } else {
                                    $user | Add-Member -NotePropertyName 'KerberoastError' -NotePropertyValue "TGS request failed: $($kerberoastResult.Error)" -Force
                                }
                            }
                        } catch {
                            $user | Add-Member -NotePropertyName 'KerberoastError' -NotePropertyValue "Error: $($_.Exception.Message)" -Force
                        }
                    }

                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'Kerberoastable' -Force
                    Show-Object $user

                    # Blank line between accounts for readability
                    Show-EmptyLine
                }
                if ($totalUsers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing Kerberoastable accounts" -Completed }

            } else {
                Show-Line "No kerberoastable accounts found" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-KerberoastableAccounts] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-KerberoastableAccounts] Check completed"
    }
}



# ----- Get-ASREPRoastableAccounts.ps1 -----

function Get-ASREPRoastableAccounts {
    <#
    .SYNOPSIS
    Detects user accounts vulnerable to AS-REP Roasting attacks.

    .DESCRIPTION
    Identifies user accounts with "Do not require Kerberos preauthentication" enabled (userAccountControl flag DONT_REQ_PREAUTH / 4194304).
    AS-REP Roasting allows attackers to request AS-REP responses without valid credentials, which can then be cracked offline to recover plaintext passwords.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER OPSEC
    When enabled, skips active AS-REP hash extraction (Kerberos AS-REQ without pre-authentication).
    Detection of vulnerable accounts via LDAP query is always performed (passive).
    Use this in environments where Kerberos traffic is monitored.

    .EXAMPLE
    Get-ASREPRoastableAccounts

    .EXAMPLE
    Get-ASREPRoastableAccounts -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC
    )

    begin {
        Write-Log "[Get-ASREPRoastableAccounts] Starting AS-REP Roastable accounts check"
    }

    process {
        try {
            # Build connection parameters (exclude OPSEC which Ensure-LDAPConnection doesn't accept)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for AS-REP Roastable accounts (DONT_REQ_PREAUTH)..." -ObjectType "ASREPRoastable"

            $asrepRoastableUsers = Get-DomainUser -PreauthNotRequired -ShowOwner @connectionParams

            if (@($asrepRoastableUsers).Count -gt 0) {
                Show-Line "Found $(@($asrepRoastableUsers).Count) AS-REP Roastable account(s):" -Class "Finding"

                # Determine if we should extract hashes (not in OPSEC mode)
                $canTestASREPRoast = -not $OPSEC

                if ($OPSEC) {
                    Show-Line "Skipping hash extraction (OPSEC mode)" -Class "Hint"
                }

                $totalUsers = @($asrepRoastableUsers).Count
                $currentIndex = 0
                foreach ($user in $asrepRoastableUsers) {
                    $currentIndex++
                    if ($totalUsers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing AS-REP Roastable accounts" -Current $currentIndex -Total $totalUsers -ObjectName $user.sAMAccountName }
                    # If testing enabled, perform AS-REP Roast and add hash as attribute
                    if ($canTestASREPRoast) {
                        $testDomain = if ($Domain) { $Domain } else { $Script:LDAPContext.Domain }
                        $testDC = if ($Server) { $Server } else { $Script:LDAPContext.Server }

                        $roastResult = Invoke-ASREPRoast -SAMAccountName $user.sAMAccountName -Domain $testDomain -DomainController $testDC

                        if ($roastResult.Success -and $roastResult.Hash) {
                            # Determine hashcat mode based on encryption type
                            $hashcatMode = switch ($roastResult.EncryptionType) {
                                23 { 18200 }  # RC4
                                17 { 19600 }  # AES128
                                18 { 19700 }  # AES256
                                default { 18200 }
                            }

                            # Add hash info as attributes to the user object
                            $hashLabel = "Hashcat (mode $hashcatMode, $($roastResult.EncryptionTypeName))"
                            $user | Add-Member -NotePropertyName 'ASREPRoastingHash' -NotePropertyValue $roastResult.Hash -Force
                            $user | Add-Member -NotePropertyName 'ASREPRoastingHashType' -NotePropertyValue $hashLabel -Force
                            $user | Add-Member -NotePropertyName 'ASREPRoastEncryption' -NotePropertyValue $roastResult.EncryptionType -Force
                        }
                        elseif ($roastResult.Error) {
                            $user | Add-Member -NotePropertyName 'ASREPRoastError' -NotePropertyValue "Failed: $($roastResult.Error)" -Force
                        }
                    }

                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'ASREPRoastable' -Force
                    Show-Object $user

                    # Blank line between accounts for readability
                    Show-EmptyLine
                }
                if ($totalUsers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Analyzing AS-REP Roastable accounts" -Completed }
            } else {
                Show-Line "No AS-REP Roastable accounts found" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-ASREPRoastableAccounts] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-ASREPRoastableAccounts] Check completed"
    }
}



# ----- Get-UnixPasswordAccounts.ps1 -----

function Get-UnixPasswordAccounts {
    <#
    .SYNOPSIS
    Detects user accounts with readable password attributes in Active Directory.

    .DESCRIPTION
    Identifies user accounts with passwords or hashes stored in readable AD attributes.
    These passwords are often stored in weak or reversible formats and represent a security risk.

    Checked attributes:
    - unixUserPassword: Unix/Linux integration (often Base64 or plaintext)
    - userPassword: LDAP standard password attribute (often Base64)
    - msSFU30Password: Services for Unix 3.0 (plaintext/Base64)
    - sambaNTPassword: Samba integration NT hash (hex, directly usable for PtH)
    - sambaLMPassword: Samba LM hash (hex, weak encryption)

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-UnixPasswordAccounts

    .EXAMPLE
    Get-UnixPasswordAccounts -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-UnixPasswordAccounts] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Searching for accounts with readable password attributes..." -ObjectType "UnixPassword"

            # Extended LDAP filter for all password-related attributes
            # unixUserPassword: Unix/Linux integration, userPassword: LDAP standard, msSFU30Password: Services for Unix 3.0, sambaNTPassword: Samba NT hash, sambaLMPassword: Samba LM hash
            $passwordFilter = "(|(unixUserPassword=*)(userPassword=*)(msSFU30Password=*)(sambaNTPassword=*)(sambaLMPassword=*))"

            $usersWithPasswords = Get-DomainUser -LDAPFilter $passwordFilter -ShowOwner @PSBoundParameters

            if (@($usersWithPasswords).Count -gt 0) {
                Show-Line "Found $(@($usersWithPasswords).Count) account(s) with readable password attributes:" -Class "Finding"

                foreach ($user in $usersWithPasswords) {
                    $user | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'UnixPassword' -Force
                    Show-Object $user
                }
            } else {
                Show-Line "No accounts with readable password attributes found" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-UnixPasswordAccounts] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-UnixPasswordAccounts] Check completed"
    }
}



# ----- Get-CredentialExposure.ps1 -----

function Get-CredentialExposure {
    <#
    .SYNOPSIS
    Detects credential exposure in SYSVOL (GPP Passwords), NETLOGON scripts, or custom paths.

    .DESCRIPTION
    Performs comprehensive credential leakage detection:
    - Group Policy Preferences (GPP) passwords (cpassword attribute, MS14-025)
    - AutoAdminLogon passwords in Registry.xml (plaintext!)
    - NETLOGON/SYSVOL scripts with hardcoded credentials
    - VBScript Encoded (.vbe) file decoding
    - Custom UNC paths or local directories

    GPP Password Decryption:
    Microsoft published the AES-256 key used for cpassword encryption in MS14-025.
    All GPP passwords found will be automatically decrypted.

    Uses a two-tier detection system (Snaffler-inspired):
    - Tier 1 (Finding/Red): High-confidence patterns with extractable values
    - Tier 2 (Hint/Yellow): Lower-confidence patterns needing manual review

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .PARAMETER Path
    Custom UNC path or local directory to scan instead of SYSVOL/NETLOGON.
    When specified, skips LDAP connection and domain-based scanning.
    Supports UNC paths (\\server\share) and local paths (C:\Scripts).

    .EXAMPLE
    Get-CredentialExposure
    Scans SYSVOL/NETLOGON of the current or specified domain.

    .EXAMPLE
    Get-CredentialExposure -Domain "contoso.com" -Credential (Get-Credential)
    Scans SYSVOL/NETLOGON with explicit credentials.

    .EXAMPLE
    Get-CredentialExposure -Path "\\fileserver\scripts"
    Scans a custom UNC path for credentials (uses current user context).

    .EXAMPLE
    Get-CredentialExposure -Path "\\fileserver\scripts" -Credential (Get-Credential)
    Scans a custom UNC path with explicit credentials for authentication.

    .EXAMPLE
    Get-CredentialExposure -Path "C:\AdminScripts"
    Scans a local directory for credentials.

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    Reference:
    - MS14-025: https://support.microsoft.com/en-us/kb/2962486
    - GPP AES Key published by Microsoft in 2014
    - Snaffler: https://github.com/SnaffCon/Snaffler
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [string]$Path
    )

    begin {
        Write-Log "[Get-CredentialExposure] Starting check"
    }

    process {
        try {
            # Mode 1: Custom Path scanning (standalone mode)
            if ($Path) {
                Show-Line "Scanning Custom Path for Credentials" -Class "Note"
                Show-Line "Target: $Path" -Class "Hint"
                Show-EmptyLine

                # Check if UNC path and credentials provided - use temporary drive mapping
                $useTempDrive = $false
                $tempDriveLetter = $null
                $scanPath = $Path

                if ($Path -match '^\\\\' -and $Credential) {
                    Write-Log "[Get-CredentialExposure] UNC path with credentials - creating temporary drive mapping"

                    # Find an available drive letter (starting from Z: going down)
                    $usedDrives = (Get-PSDrive -PSProvider FileSystem).Name
                    $tempDriveLetter = ([char[]](90..65) | Where-Object { [string]$_ -notin $usedDrives } | Select-Object -First 1)

                    if ($tempDriveLetter) {
                        try {
                            $null = New-PSDrive -Name $tempDriveLetter -PSProvider FileSystem -Root $Path -Credential $Credential -ErrorAction Stop
                            $scanPath = "${tempDriveLetter}:\"
                            $useTempDrive = $true
                            Write-Log "[Get-CredentialExposure] Mapped $Path to ${tempDriveLetter}:"
                        }
                        catch {
                            Show-Line "Failed to connect to $Path with provided credentials: $_" -Class "Finding"
                            return
                        }
                    }
                    else {
                        Show-Line "No available drive letter for UNC mapping" -Class "Finding"
                        return
                    }
                }
                elseif ($Path -match '^\\\\') {
                    # UNC path without credentials - test access with current user
                    if (-not (Test-Path $Path)) {
                        Show-Line "Cannot access path: $Path (try using -Credential for authentication)" -Class "Finding"
                        return
                    }
                }
                elseif (-not (Test-Path $Path)) {
                    Show-Line "Cannot access path: $Path" -Class "Finding"
                    return
                }

                try {

                # Define patterns for custom path scan (same as SYSVOL scan)
                $tier1Patterns = @(
                    @{ Pattern = 'passw(or)?d\s*[=:]\s*["''][^"'']{3,}["'']'; Description = "Password assignment (quoted)" },
                    @{ Pattern = 'passw(or)?d\s*[=:]\s*(?!["''])\S{3,}'; Description = "Password assignment (unquoted)" },
                    @{ Pattern = '[-/]passw(or)?d\s+\S{3,}'; Description = "Password parameter" },
                    @{ Pattern = 'psexec.{0,100}\s-p\s+\S+'; Description = "PSExec with password" },
                    @{ Pattern = 'schtasks.{0,300}/rp\s+\S+'; Description = "Schtasks with password" },
                    @{ Pattern = 'net\s+user\s+\S+\s+\S+\s+/add'; Description = "Net user creation" },
                    @{ Pattern = 'cmdkey\s+/add:[^\s]+.*?/pass:\S+'; Description = "Cmdkey with password" },
                    @{ Pattern = 'connectionstring.{1,200}passw'; Description = "DB connection string" },
                    @{ Pattern = 'ConvertTo-SecureString\s+["''][^"'']+["'']'; Description = "SecureString conversion" },
                    @{ Pattern = 'api[_-]?key\s*[=:]\s*["''][^"'']{10,}["'']'; Description = "API key assignment" },
                    @{ Pattern = '\$cred(ential)?\s*=.*password'; Description = "Credential variable" }
                )
                $tier2Patterns = @(
                    @{ Pattern = "passw(or)?d"; Description = "Password mention" },
                    @{ Pattern = "passwd"; Description = "Passwd mention" },
                    @{ Pattern = "credential"; Description = "Credential mention" },
                    @{ Pattern = "<passw[^>]*>[^<]+</passw"; Description = "XML password element" },
                    @{ Pattern = "(secret|token)\s*[=:]\s*\S{5,}"; Description = "Secret/token assignment" }
                )
                $exclusionPatterns = @(
                    'passw(or)?d\s*(policy|policies|requirement|guideline)',
                    'passw(or)?d\s+(must|should|cannot|shall)\s+(be|contain|have|include)',
                    'passw(or)?d\s+(length|complexity|history|age|expir)',
                    'passw(or)?d\s+(reset|change|recover|forgot)',
                    '(minimum|maximum)\s+passw(or)?d',
                    '(set|change|update|reset)\s+(your|the|a)\s+passw(or)?d',
                    '^\s*(REM|::|''|#)\s+.*passw',
                    'echo\s+.*passw(or)?d.*help',
                    'usage:.*passw(or)?d',
                    'passw(or)?d\s*:\s*\*+',
                    'passw(or)?d\s*:\s*<[^>]+>',
                    'Enter\s+(your\s+)?passw(or)?d',
                    'passw(or)?d\s+prompt'
                )
                $netUsePattern = "net use (?<devicename>(\w|\*|LPT\d):?) (?<path>\\\\?.*?)(( (?<user>/user:((?<domain>[\w.]*)\\)?(?<username>\S*)))|( /(p(ersistent)?|P(ERSISTENT)?):(no|NO|yes|YES))|( (?<password>(?!/)\S*))|( /(delete|DELETE))|( /(savecred|SAVECRED))|( /(smartcard|SMARTCARD)))+"

                # Scan XML files for GPP passwords and AutoAdminLogon
                $xmlFiles = Get-ChildItem -Force -Path $scanPath -Recurse -Include "*.xml" -ErrorAction SilentlyContinue
                if (@($xmlFiles).Count -gt 0) {
                    Write-Log "[Get-CredentialExposure] Found $(@($xmlFiles).Count) XML file(s) in custom path"
                    foreach ($xmlFile in $xmlFiles) {
                        try {
                            [xml]$xmlContent = Get-Content -Path $xmlFile.Fullname -ErrorAction Stop
                            $fileName = Split-Path $xmlFile.FullName -Leaf

                            if ($xmlContent.InnerXml -match 'cpassword') {
                                $xmlContent.GetElementsByTagName('Properties') | ForEach-Object {
                                    if ($_.cpassword -and $_.cpassword -ne '') {
                                        $cpassword = $_.cpassword
                                        $decryptedPassword = ConvertFrom-GPPPassword -EncryptedPassword $cpassword
                                        $username = ""
                                        if ($_.userName) { $username = $_.userName }
                                        elseif ($_.accountName) { $username = $_.accountName }
                                        elseif ($_.newName) { $username = $_.newName }
                                        elseif ($_.runAs) { $username = $_.runAs }
                                        # Create credential object for proper display
                                        $credObj = [PSCustomObject]@{
                                            credentialType = "GPP Password"
                                            filePath = $xmlFile.Fullname
                                            userName = $username
                                            password = $decryptedPassword
                                        }
                                        Show-Line "Found GPP credential" -Class Finding
                                        $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                        $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'GPP Password' -Force
                                        Show-Object $credObj
                                    }
                                }
                            }
                            elseif ($fileName -match 'Registry\.xml' -and $xmlContent.InnerXml -match 'AutoAdminLogon') {
                                $autoLogonUser = $null
                                $autoLogonPassword = $null
                                $autoLogonDomain = $null
                                foreach ($prop in $xmlContent.GetElementsByTagName('Properties')) {
                                    if ($prop.name -match 'DefaultUserName') { $autoLogonUser = $prop.value }
                                    if ($prop.name -match 'DefaultPassword') { $autoLogonPassword = $prop.value }
                                    if ($prop.name -match 'DefaultDomainName') { $autoLogonDomain = $prop.value }
                                }
                                if ($autoLogonPassword -and $autoLogonPassword -ne '') {
                                    $fullUsername = if ($autoLogonDomain) { "$autoLogonDomain\$autoLogonUser" } else { $autoLogonUser }
                                    # Create credential object for proper display
                                    $credObj = [PSCustomObject]@{
                                        credentialType = "AutoAdminLogon"
                                        filePath = $xmlFile.Fullname
                                        userName = $fullUsername
                                        password = $autoLogonPassword
                                    }
                                    Show-Line "Found AutoAdminLogon credential" -Class Finding
                                        $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                        $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'AutoAdminLogon' -Force
                                        Show-Object $credObj
                                }
                            }
                        }
                        catch {
                            Write-Log "[Get-CredentialExposure] Error parsing $($xmlFile.Fullname): $_"
                        }
                    }
                }

                # Scan script/config files
                $searchExtensions = @('*.txt','*.bat','*.ini','*.conf','*.cnf','*.cmd','*.vbs','*.vbe','*.kix','*.ps1','*.psm1')
                $files = Get-ChildItem -Force -Path $scanPath -Recurse -Include $searchExtensions -ErrorAction SilentlyContinue

                if (@($files).Count -gt 0) {
                    Write-Log "[Get-CredentialExposure] Found $(@($files).Count) script/config file(s) in custom path"
                    foreach ($file in $files) {
                        try {
                            $fileContent = $null
                            if ($file.Extension -eq ".vbe") {
                                try {
                                    $encodedContent = Get-Content -Path $file.FullName -Raw -ErrorAction Stop
                                    $fileContent = ConvertFrom-VBE -EncodedScript $encodedContent
                                    Write-Log "[Get-CredentialExposure] Decoded VBE file: $($file.Name)"
                                }
                                catch {
                                    Write-Log "[Get-CredentialExposure] Failed to decode VBE file: $($file.Name)"
                                    continue
                                }
                            }
                            else {
                                $fileContent = Get-Content -Path $file.FullName -Raw -ErrorAction Stop
                            }
                            if (-not $fileContent) { continue }

                            $lines = $fileContent -split "`n"
                            $reportedLines = @{}

                            # Check net use credentials
                            $netUseMatches = [Regex]::Matches($fileContent, $netUsePattern)
                            foreach ($match in $netUseMatches) {
                                $foundUsername = $match.Groups["username"].Value
                                $foundPassword = $match.Groups["password"].Value
                                $foundDomain = $match.Groups["domain"].Value
                                if ($foundUsername -and $foundPassword) {
                                    $fullUser = if ($foundDomain) { "$foundDomain\$foundUsername" } else { $foundUsername }
                                    # Create credential object for proper display
                                    $credObj = [PSCustomObject]@{
                                        credentialType = "Net Use"
                                        filePath = $file.FullName
                                        userName = $fullUser
                                        password = $foundPassword
                                    }
                                    Show-Line "Found net use credential" -Class Finding
                                        $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                        $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Net Use' -Force
                                        Show-Object $credObj
                                    $reportedLines[$match.Value] = $true
                                }
                            }

                            # Two-tier detection on each line
                            foreach ($line in $lines) {
                                $trimmedLine = $line.Trim()
                                if ([string]::IsNullOrWhiteSpace($trimmedLine)) { continue }

                                $alreadyReported = $false
                                foreach ($reported in $reportedLines.Keys) {
                                    if ($trimmedLine -like "*$reported*") { $alreadyReported = $true; break }
                                }
                                if ($alreadyReported) { continue }

                                $isExcluded = $false
                                foreach ($exclusion in $exclusionPatterns) {
                                    if ($trimmedLine -match $exclusion) { $isExcluded = $true; break }
                                }
                                if ($isExcluded) { continue }

                                $tier1Match = $false
                                foreach ($pattern in $tier1Patterns) {
                                    if ($trimmedLine -match $pattern.Pattern) {
                                        # Create credential object for proper display
                                        $credObj = [PSCustomObject]@{
                                            credentialType = $pattern.Description
                                            filePath = $file.FullName
                                            matchedLine = $trimmedLine
                                        }
                                        Show-Line "Found credential pattern" -Class Finding
                                        $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                        $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue $pattern.Description -Force
                                        Show-Object $credObj
                                        $reportedLines[$trimmedLine] = $true
                                        $tier1Match = $true
                                        break
                                    }
                                }
                                if ($tier1Match) { continue }

                                foreach ($pattern in $tier2Patterns) {
                                    if ($trimmedLine -match $pattern.Pattern) {
                                        # Create credential object for proper display (lower severity)
                                        $credObj = [PSCustomObject]@{
                                            credentialType = "$($pattern.Description) (needs review)"
                                            filePath = $file.FullName
                                            matchedLine = $trimmedLine
                                        }
                                        Show-Line "Found possible sensitive information" -Class Hint
                                            $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                            $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue $pattern.Description -Force
                                            Show-Object $credObj
                                        $reportedLines[$trimmedLine] = $true
                                        break
                                    }
                                }
                            }
                        }
                        catch {
                            Write-Log "[Get-CredentialExposure] Error analyzing $($file.Name): $_"
                        }
                    }
                }
                else {
                    Show-Line "No script/config files found in path" -Class "Note"
                }

                }
                finally {
                    # Cleanup: Remove temporary drive mapping if created (always runs, even on error)
                    if ($useTempDrive -and $tempDriveLetter) {
                        try {
                            Remove-PSDrive -Name $tempDriveLetter -Force -ErrorAction SilentlyContinue
                            Write-Log "[Get-CredentialExposure] Removed temporary drive mapping ${tempDriveLetter}:"
                        }
                        catch {
                            Write-Log "[Get-CredentialExposure] Failed to remove temporary drive: $_"
                        }
                    }
                }

                return
            }

            # Mode 2: Domain-based SYSVOL/NETLOGON scanning
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            $dcServer = $Script:LDAPContext.Server

            # ===== Single SYSVOL scan: Mount once, enumerate once, analyze all =====
            Show-SubHeader "Searching for credentials in Group Policy files..." -ObjectType "GPPCredential"

            # Pre-load GPO linkage and name mapping (LDAP queries - must run before SMB block)
            $gpoLinkage = Get-GPOLinkage
            $gpoNameMap = @{}
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }
            $allGPOs = @(Get-DomainGPO @connectionParams)
            foreach ($gpo in $allGPOs) {
                if ($gpo.Name) {
                    $gpoNameMap[$gpo.Name.ToUpper()] = $gpo.DisplayName
                }
            }

            # Track SYSVOL access status
            $Script:sysvolAccessible = $false

            $domainFQDN = $Script:LDAPContext.Domain
            Invoke-SMBAccess -Description "Scanning SYSVOL for credentials and sensitive information" -ScriptBlock {
                $sysvolBase = "\\$dcServer\SYSVOL\$domainFQDN"
                $gppFindingsCount = 0
                $sysvolFindingsCount = 0

                if (-not (Test-Path $sysvolBase)) {
                    Show-Line "SYSVOL access failed - cannot search for credentials - SMB access failed (authentication/network issue)" -Class "Finding"
                }
                else {
                    $Script:sysvolAccessible = $true
                    Write-Log "[Get-CredentialExposure] SYSVOL accessible: $sysvolBase"

                    # Use cached SYSVOL file listing (builds cache on first call, reuses on subsequent calls)
                    $allExtensions = @('*.xml','*.txt','*.bat','*.ini','*.conf','*.cnf','*.cmd','*.vbs','*.vbe','*.kix')
                    $allFiles = @(Get-CachedSYSVOLFiles -Filter $allExtensions -SYSVOLPath $sysvolBase)

                    # Split into XML and script files locally (no additional SMB round-trips)
                    $xmlFiles = @($allFiles | Where-Object { $_.Extension -eq '.xml' })
                    $scriptFiles = @($allFiles | Where-Object { $_.Extension -ne '.xml' })

                    Write-Log "[Get-CredentialExposure] Split: $($xmlFiles.Count) XML, $($scriptFiles.Count) script/config"

                    # ===== Part 1: GPP Password Search (XML files) =====
                    if ($xmlFiles.Count -gt 0) {
                        Write-Log "[Get-CredentialExposure] Analyzing $($xmlFiles.Count) XML file(s)..."

                        $totalXmlFiles = @($xmlFiles).Count
                        $currentXmlIndex = 0
                        foreach ($xmlFile in $xmlFiles) {
                            $currentXmlIndex++
                            if ($totalXmlFiles -gt $Script:ProgressThreshold) {
                                Show-Progress -Activity "Scanning SYSVOL for GPP credentials" -Current $currentXmlIndex -Total $totalXmlFiles -ObjectName $xmlFile.Name
                            }
                            try {
                                Write-Log "[Get-CredentialExposure] Reading XML: $($xmlFile.FullName)"
                                [xml]$xmlContent = Get-Content -Path $xmlFile.Fullname -ErrorAction Stop
                                $fileName = Split-Path $xmlFile.FullName -Leaf

                                # Extract GPO GUID from SYSVOL path for linkage resolution
                                $fileGpoGUID = $null
                                $fileGpoName = $null
                                $fileLinkedOUs = @()
                                if ($xmlFile.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                                    $fileGpoGUID = $Matches[1].ToUpper()
                                    $fileGpoName = if ($gpoNameMap[$fileGpoGUID]) { $gpoNameMap[$fileGpoGUID] } else { $fileGpoGUID }
                                    if ($gpoLinkage -and $gpoLinkage.ContainsKey($fileGpoGUID)) {
                                        $fileLinkedOUs = $gpoLinkage[$fileGpoGUID]
                                    }
                                }

                                # Check 1: cpassword attribute (GPP encrypted passwords)
                                if ($xmlContent.InnerXml -match 'cpassword') {
                                    $xmlContent.GetElementsByTagName('Properties') | ForEach-Object {
                                        if ($_.cpassword -and $_.cpassword -ne '') {
                                            $cpassword = $_.cpassword
                                            $decryptedPassword = ConvertFrom-GPPPassword -EncryptedPassword $cpassword

                                            $username = ""
                                            if ($_.userName) { $username = $_.userName }
                                            elseif ($_.accountName) { $username = $_.accountName }
                                            elseif ($_.newName) { $username = $_.newName }
                                            elseif ($_.runAs) { $username = $_.runAs }

                                            $credObj = [PSCustomObject]@{
                                                credentialType = "GPP Password"
                                                filePath = $xmlFile.Fullname
                                                userName = $username
                                                password = $decryptedPassword
                                            }
                                            if ($fileGpoName) { $credObj | Add-Member -NotePropertyName 'gpoName' -NotePropertyValue $fileGpoName -Force }
                                            if ($fileLinkedOUs.Count -gt 0) { $credObj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $fileLinkedOUs -Force }
                                            Show-Line "Found GPP credential" -Class Finding
                                            $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                            $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'GPP Password' -Force
                                            Show-Object $credObj
                                            $gppFindingsCount++
                                        }
                                    }
                                }
                                # Check 2: AutoAdminLogon in Registry.xml (plaintext passwords!)
                                elseif ($fileName -match 'Registry\.xml' -and $xmlContent.InnerXml -match 'AutoAdminLogon') {
                                    $autoLogonUser = $null
                                    $autoLogonPassword = $null
                                    $autoLogonDomain = $null

                                    foreach ($prop in $xmlContent.GetElementsByTagName('Properties')) {
                                        if ($prop.name -match 'DefaultUserName') { $autoLogonUser = $prop.value }
                                        if ($prop.name -match 'DefaultPassword') { $autoLogonPassword = $prop.value }
                                        if ($prop.name -match 'DefaultDomainName') { $autoLogonDomain = $prop.value }
                                    }

                                    if ($autoLogonPassword -and $autoLogonPassword -ne '') {
                                        $fullUsername = if ($autoLogonDomain) { "$autoLogonDomain\$autoLogonUser" } else { $autoLogonUser }
                                        $credObj = [PSCustomObject]@{
                                            credentialType = "AutoAdminLogon"
                                            filePath = $xmlFile.Fullname
                                            userName = $fullUsername
                                            password = $autoLogonPassword
                                        }
                                        if ($fileGpoName) { $credObj | Add-Member -NotePropertyName 'gpoName' -NotePropertyValue $fileGpoName -Force }
                                        if ($fileLinkedOUs.Count -gt 0) { $credObj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $fileLinkedOUs -Force }
                                        Show-Line "Found AutoAdminLogon credential" -Class Finding
                                        $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'GPPCredential' -Force
                                        $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'AutoAdminLogon' -Force
                                        Show-Object $credObj
                                        $gppFindingsCount++
                                    }
                                }
                            }
                            catch {
                                Write-Log "[Get-CredentialExposure] Error parsing $($xmlFile.Fullname): $_"
                            }
                        }
                        if ($totalXmlFiles -gt $Script:ProgressThreshold) {
                            Show-Progress -Activity "Scanning SYSVOL for GPP credentials" -Completed
                        }
                    }

                    if ($gppFindingsCount -eq 0) {
                        Show-Line "No GPP credentials found in SYSVOL" -Class "Secure"
                    }

                    # ===== Part 2: Sensitive Information Search (script/config files) =====
                    Show-SubHeader "Searching for sensitive information in SYSVOL/NETLOGON..." -ObjectType "SYSVOLCredential"

                    if ($scriptFiles.Count -gt 0) {
                        Write-Log "[Get-CredentialExposure] Analyzing $($scriptFiles.Count) script/config file(s)..."

                        # Two-Tier Credential Detection System (Snaffler-inspired)
                        $tier1Patterns = @(
                            @{ Pattern = 'passw(or)?d\s*[=:]\s*["''][^"'']{3,}["'']'; Description = "Password assignment (quoted)" },
                            @{ Pattern = 'passw(or)?d\s*[=:]\s*(?!["''])\S{3,}'; Description = "Password assignment (unquoted)" },
                            @{ Pattern = '[-/]passw(or)?d\s+\S{3,}'; Description = "Password parameter" },
                            @{ Pattern = 'psexec.{0,100}\s-p\s+\S+'; Description = "PSExec with password" },
                            @{ Pattern = 'schtasks.{0,300}/rp\s+\S+'; Description = "Schtasks with password" },
                            @{ Pattern = 'net\s+user\s+\S+\s+\S+\s+/add'; Description = "Net user creation" },
                            @{ Pattern = 'cmdkey\s+/add:[^\s]+.*?/pass:\S+'; Description = "Cmdkey with password" },
                            @{ Pattern = 'connectionstring.{1,200}passw'; Description = "DB connection string" },
                            @{ Pattern = 'ConvertTo-SecureString\s+["''][^"'']+["'']'; Description = "SecureString conversion" },
                            @{ Pattern = 'api[_-]?key\s*[=:]\s*["''][^"'']{10,}["'']'; Description = "API key assignment" },
                            @{ Pattern = '\$cred(ential)?\s*=.*password'; Description = "Credential variable" }
                        )

                        $tier2Patterns = @(
                            @{ Pattern = "passw(or)?d"; Description = "Password mention" },
                            @{ Pattern = "passwd"; Description = "Passwd mention" },
                            @{ Pattern = "credential"; Description = "Credential mention" },
                            @{ Pattern = "<passw[^>]*>[^<]+</passw"; Description = "XML password element" },
                            @{ Pattern = "(secret|token)\s*[=:]\s*\S{5,}"; Description = "Secret/token assignment" }
                        )

                        $exclusionPatterns = @(
                            'passw(or)?d\s*(policy|policies|requirement|guideline)',
                            'passw(or)?d\s+(must|should|cannot|shall)\s+(be|contain|have|include)',
                            'passw(or)?d\s+(length|complexity|history|age|expir)',
                            'passw(or)?d\s+(reset|change|recover|forgot)',
                            '(minimum|maximum)\s+passw(or)?d',
                            '(set|change|update|reset)\s+(your|the|a)\s+passw(or)?d',
                            '^\s*(REM|::|''|#)\s+.*passw',
                            'echo\s+.*passw(or)?d.*help',
                            'usage:.*passw(or)?d',
                            'passw(or)?d\s*:\s*\*+',
                            'passw(or)?d\s*:\s*<[^>]+>',
                            'Enter\s+(your\s+)?passw(or)?d',
                            'passw(or)?d\s+prompt'
                        )

                        $netUsePattern = "net use (?<devicename>(\w|\*|LPT\d):?) (?<path>\\\\?.*?)(( (?<user>/user:((?<domain>[\w.]*)\\)?(?<username>\S*)))|( /(p(ersistent)?|P(ERSISTENT)?):(no|NO|yes|YES))|( (?<password>(?!/)\S*))|( /(delete|DELETE))|( /(savecred|SAVECRED))|( /(smartcard|SMARTCARD)))+"

                        $totalScriptFiles = @($scriptFiles).Count
                        $currentScriptIndex = 0
                        foreach ($file in $scriptFiles) {
                            $currentScriptIndex++
                            if ($totalScriptFiles -gt $Script:ProgressThreshold) {
                                Show-Progress -Activity "Scanning SYSVOL for sensitive information" -Current $currentScriptIndex -Total $totalScriptFiles -ObjectName $file.Name
                            }
                            try {
                                Write-Log "[Get-CredentialExposure] Reading script/config: $($file.FullName)"

                                # Extract GPO GUID from SYSVOL path for linkage resolution
                                $fileGpoGUID = $null
                                $fileGpoName = $null
                                $fileLinkedOUs = @()
                                if ($file.FullName -match '\\Policies\\(\{[^}]+\})\\') {
                                    $fileGpoGUID = $Matches[1].ToUpper()
                                    $fileGpoName = if ($gpoNameMap[$fileGpoGUID]) { $gpoNameMap[$fileGpoGUID] } else { $fileGpoGUID }
                                    if ($gpoLinkage -and $gpoLinkage.ContainsKey($fileGpoGUID)) {
                                        $fileLinkedOUs = $gpoLinkage[$fileGpoGUID]
                                    }
                                }

                                $fileContent = $null

                                if ($file.Extension -eq ".vbe") {
                                    try {
                                        $encodedContent = Get-Content -Path $file.FullName -Raw -ErrorAction Stop
                                        $fileContent = ConvertFrom-VBE -EncodedScript $encodedContent
                                        Write-Log "[Get-CredentialExposure] Decoded VBE file: $($file.Name)"
                                    }
                                    catch {
                                        Write-Log "[Get-CredentialExposure] Failed to decode VBE file: $($file.Name)"
                                        continue
                                    }
                                }
                                else {
                                    $fileContent = Get-Content -Path $file.FullName -Raw -ErrorAction Stop
                                }

                                if (-not $fileContent) { continue }

                                $lines = $fileContent -split "`n"
                                $reportedLines = @{}

                                # Check for net use credentials
                                $netUseMatches = [Regex]::Matches($fileContent, $netUsePattern)
                                foreach ($match in $netUseMatches) {
                                    $foundUsername = $match.Groups["username"].Value
                                    $foundPassword = $match.Groups["password"].Value
                                    $foundDomain = $match.Groups["domain"].Value

                                    if ($foundUsername -and $foundPassword) {
                                        $fullUser = if ($foundDomain) { "$foundDomain\$foundUsername" } else { $foundUsername }
                                        $credObj = [PSCustomObject]@{
                                            credentialType = "Net Use"
                                            filePath = $file.FullName
                                            userName = $fullUser
                                            password = $foundPassword
                                        }
                                        if ($fileGpoName) { $credObj | Add-Member -NotePropertyName 'gpoName' -NotePropertyValue $fileGpoName -Force }
                                        if ($fileLinkedOUs.Count -gt 0) { $credObj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $fileLinkedOUs -Force }
                                        Show-Line "Found net use credential" -Class Finding
                                        $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SYSVOLCredential' -Force
                                        $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue 'Net Use' -Force
                                        Show-Object $credObj
                                        $reportedLines[$match.Value] = $true
                                        $sysvolFindingsCount++
                                    }
                                }

                                # Two-tier credential detection on each line
                                foreach ($line in $lines) {
                                    $trimmedLine = $line.Trim()
                                    if ([string]::IsNullOrWhiteSpace($trimmedLine)) { continue }

                                    $alreadyReported = $false
                                    foreach ($reported in $reportedLines.Keys) {
                                        if ($trimmedLine -like "*$reported*") {
                                            $alreadyReported = $true
                                            break
                                        }
                                    }
                                    if ($alreadyReported) { continue }

                                    $isExcluded = $false
                                    foreach ($exclusion in $exclusionPatterns) {
                                        if ($trimmedLine -match $exclusion) {
                                            $isExcluded = $true
                                            Write-Log "[Get-CredentialExposure] Excluded by pattern: $trimmedLine"
                                            break
                                        }
                                    }
                                    if ($isExcluded) { continue }

                                    $tier1Match = $false
                                    foreach ($pattern in $tier1Patterns) {
                                        if ($trimmedLine -match $pattern.Pattern) {
                                            $credObj = [PSCustomObject]@{
                                                credentialType = $pattern.Description
                                                filePath = $file.FullName
                                                matchedLine = $trimmedLine
                                            }
                                            if ($fileGpoName) { $credObj | Add-Member -NotePropertyName 'gpoName' -NotePropertyValue $fileGpoName -Force }
                                            if ($fileLinkedOUs.Count -gt 0) { $credObj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $fileLinkedOUs -Force }
                                            Show-Line "Found credential pattern" -Class Finding
                                            $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SYSVOLCredential' -Force
                                            $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue $pattern.Description -Force
                                            Show-Object $credObj
                                            $reportedLines[$trimmedLine] = $true
                                            $tier1Match = $true
                                            $sysvolFindingsCount++
                                            break
                                        }
                                    }
                                    if ($tier1Match) { continue }

                                    foreach ($pattern in $tier2Patterns) {
                                        if ($trimmedLine -match $pattern.Pattern) {
                                            $credObj = [PSCustomObject]@{
                                                credentialType = "$($pattern.Description) (needs review)"
                                                filePath = $file.FullName
                                                matchedLine = $trimmedLine
                                            }
                                            if ($fileGpoName) { $credObj | Add-Member -NotePropertyName 'gpoName' -NotePropertyValue $fileGpoName -Force }
                                            if ($fileLinkedOUs.Count -gt 0) { $credObj | Add-Member -NotePropertyName 'LinkedOUs' -NotePropertyValue $fileLinkedOUs -Force }
                                            Show-Line "Found possible sensitive information" -Class Hint
                                            $credObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'SYSVOLCredential' -Force
                                            $credObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue $pattern.Description -Force
                                            Show-Object $credObj
                                            $reportedLines[$trimmedLine] = $true
                                            $sysvolFindingsCount++
                                            break
                                        }
                                    }
                                }
                            }
                            catch {
                                Write-Log "[Get-CredentialExposure] Error analyzing $($file.Name): $_"
                            }
                        }
                        if ($totalScriptFiles -gt $Script:ProgressThreshold) {
                            Show-Progress -Activity "Scanning SYSVOL for sensitive information" -Completed
                        }

                        if ($sysvolFindingsCount -eq 0) {
                            Show-Line "No sensitive information found in SYSVOL/NETLOGON scripts" -Class "Secure"
                        }
                    }
                    else {
                        Show-Line "No sensitive information found in SYSVOL/NETLOGON scripts" -Class "Secure"
                    }
                }
            }

            # Check if SYSVOL was accessible
            $sysvolAccessible = $Script:sysvolAccessible
            $Script:sysvolAccessible = $null

            if (-not $sysvolAccessible) {
                if ((Test-SysvolAccessible) -eq $false) {
                    Show-Line "Skipped - SYSVOL not accessible" -Class "Hint"
                } else {
                    Show-Line "SYSVOL access failed - cannot search for credentials - SMB access failed (authentication/network issue)" -Class "Finding"
                }
            }

        } catch {
            Write-Log "[Get-CredentialExposure] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-CredentialExposure] Check completed"
    }
}



# ----- Get-LAPSCredentialAccess.ps1 -----

function Get-LAPSCredentialAccess {
    <#
    .SYNOPSIS
    Tests if the current user account can read LAPS passwords.

    .DESCRIPTION
    Performs an actual read test on LAPS password attributes to determine if the current authenticated user has access to LAPS credentials.

    This check:
    - Attempts to read ms-Mcs-AdmPwd (Legacy LAPS) from computers
    - Attempts to read msLAPS-Password (Windows LAPS v2 plaintext) from computers
    - Attempts to read msLAPS-EncryptedPassword (Windows LAPS v2 encrypted) from computers
    - Parses encrypted LAPS metadata (timestamp, target SID)
    - Attempts decryption via NCryptUnprotectSecret if authorized
    - Reports which computers' passwords are accessible
    - Groups accessible credentials by OU

    Related Checks:
    - Get-LAPSConfiguration (Computer): Is LAPS deployed?
    - Get-LAPSPermissions (Rights): WHO has LAPS read rights per OU?

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-LAPSCredentialAccess

    .EXAMPLE
    Get-LAPSCredentialAccess -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-LAPSCredentialAccess] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Testing LAPS password read access for current user..." -ObjectType "LAPSCredential"

            # Check if LAPS schema info is available from Get-LAPSConfiguration
            $lapsLegacySchemaPresent = $false
            $windowsLAPSSchemaPresent = $false

            if ($Script:LAPSSchemaInfo) {
                $lapsLegacySchemaPresent = $Script:LAPSSchemaInfo.LegacyPresent
                $windowsLAPSSchemaPresent = $Script:LAPSSchemaInfo.NativePresent
            } else {
                # Detect schema ourselves using Invoke-LDAPSearch with Schema Partition
                $schemaDN = $Script:LDAPContext.SchemaNamingContext

                if ($schemaDN) {
                    try {
                        # Check for Legacy LAPS schema attribute (ms-Mcs-AdmPwdExpirationTime)
                        $legacySchemaFilter = "(&(objectClass=attributeSchema)(|(lDAPDisplayName=ms-Mcs-AdmPwdExpirationTime)(cn=ms-Mcs-AdmPwdExpirationTime)))"
                        $legacySchemaResult = Invoke-LDAPSearch -Filter $legacySchemaFilter -SearchBase $schemaDN -Properties 'cn' -SizeLimit 1
                        if ($legacySchemaResult) { $lapsLegacySchemaPresent = $true }

                        # Check for Windows LAPS schema attribute (msLAPS-PasswordExpirationTime)
                        $nativeSchemaFilter = "(&(objectClass=attributeSchema)(|(lDAPDisplayName=msLAPS-PasswordExpirationTime)(cn=msLAPS-PasswordExpirationTime)))"
                        $nativeSchemaResult = Invoke-LDAPSearch -Filter $nativeSchemaFilter -SearchBase $schemaDN -Properties 'cn' -SizeLimit 1
                        if ($nativeSchemaResult) { $windowsLAPSSchemaPresent = $true }

                        Write-Log "[Get-LAPSCredentialAccess] Schema check: Legacy=$lapsLegacySchemaPresent, Native=$windowsLAPSSchemaPresent"
                    } catch {
                        Write-Log "[Get-LAPSCredentialAccess] Schema query error: $($_.Exception.Message)"
                    }
                }

                # Fallback: check if any computer has LAPS attributes (minimal query)
                if (-not $lapsLegacySchemaPresent -and -not $windowsLAPSSchemaPresent) {
                    # Only fetch distinguishedName - we just need to know if any object exists
                    $legacyCheck = Get-DomainComputer -LDAPFilter "(ms-Mcs-AdmPwdExpirationTime=*)" -Properties 'distinguishedName' -ResultLimit 1 @PSBoundParameters
                    if ($legacyCheck) { $lapsLegacySchemaPresent = $true }

                    $nativeCheck = Get-DomainComputer -LDAPFilter "(msLAPS-PasswordExpirationTime=*)" -Properties 'distinguishedName' -ResultLimit 1 @PSBoundParameters
                    if ($nativeCheck) { $windowsLAPSSchemaPresent = $true }
                }

                # Cache schema info for other LAPS modules
                $Script:LAPSSchemaInfo = @{
                    LegacyPresent = $lapsLegacySchemaPresent
                    NativePresent = $windowsLAPSSchemaPresent
                }
            }

            if (-not $lapsLegacySchemaPresent -and -not $windowsLAPSSchemaPresent) {
                Show-Line "No LAPS schema found" -Class "Note"
                return
            }

            $readableComputers = @()

            # Test Legacy LAPS - query for readable ms-Mcs-AdmPwd
            # ACL-based: attribute only returned if user has read permission
            if ($lapsLegacySchemaPresent) {
                Write-Log "[Get-LAPSCredentialAccess] Querying for readable Legacy LAPS passwords"
                $computersWithLegacy = @(Get-DomainComputer -LDAPFilter "(ms-Mcs-AdmPwd=*)" @PSBoundParameters)
                $readableComputers += $computersWithLegacy
            }

            # Test Windows LAPS plaintext - query for msLAPS-Password attribute in AD
            if ($windowsLAPSSchemaPresent) {
                Write-Log "[Get-LAPSCredentialAccess] Querying for readable Windows LAPS plaintext passwords"
                $computersWithPlaintext = @(Get-DomainComputer -LDAPFilter "(msLAPS-Password=*)" @PSBoundParameters)
                $readableComputers += $computersWithPlaintext
            }

            # Test Windows LAPS encrypted - optimized approach:
            # 1. Get current user's token groups (once)
            # 2. Query all computers with ALL properties but -Raw (no decryption)
            # 3. Parse Target SID from each blob locally (<1ms)
            # 4. Check if Target SID is in our token groups (local check)
            # 5. For authorized: decrypt blob directly (no second LDAP query!)
            if ($windowsLAPSSchemaPresent) {
                Write-Log "[Get-LAPSCredentialAccess] Checking encrypted LAPS passwords (optimized)"

                # Step 1: Get current user's token groups (cached after first call)
                $myTokenGroups = Get-CurrentUserTokenGroups
                if ($myTokenGroups -and $myTokenGroups.Count -gt 0) {
                    Write-Log "[Get-LAPSCredentialAccess] Got $($myTokenGroups.Count) token groups for current user"

                    # Step 2: Query all computers with encrypted LAPS - ALL properties but Raw (no decryption)
                    # This way we have the full object and only need to decrypt the blob locally
                    $encryptedComputers = @(Get-DomainComputer -LDAPFilter "(msLAPS-EncryptedPassword=*)" -Raw @PSBoundParameters)

                    if (@($encryptedComputers).Count -gt 0) {
                        Write-Log "[Get-LAPSCredentialAccess] Found $($encryptedComputers.Count) computers with encrypted LAPS"

                        # Step 3, 4 & 5: Parse Target SID, check authorization, decrypt if authorized
                        $authorizedCount = 0
                        foreach ($comp in $encryptedComputers) {
                            $blob = $comp.'msLAPS-EncryptedPassword'
                            if ($blob) {
                                # Parse metadata only (no decryption attempt) - very fast, <1ms
                                $lapsInfo = ConvertFrom-LAPSEncryptedPassword -Blob $blob
                                if ($lapsInfo -and $lapsInfo.TargetSID) {
                                    # Check if Target SID is in our token groups (local check)
                                    if ($myTokenGroups -contains $lapsInfo.TargetSID) {
                                        $authorizedCount++
                                        # Decrypt directly - no second LDAP query needed!
                                        $decryptedInfo = ConvertFrom-LAPSEncryptedPassword -Blob $blob -Decrypt
                                        if ($decryptedInfo -and $decryptedInfo.DecryptionSucceeded) {
                                            # Convert Raw byte[] attributes to proper types for Show-Object
                                            if ($comp.objectSid -is [byte[]]) {
                                                try {
                                                    $sidObj = New-Object System.Security.Principal.SecurityIdentifier($comp.objectSid, 0)
                                                    $comp | Add-Member -NotePropertyName 'objectSid' -NotePropertyValue $sidObj.Value -Force
                                                } catch { }
                                            }
                                            if ($comp.objectGUID -is [byte[]]) {
                                                try {
                                                    $comp | Add-Member -NotePropertyName 'objectGUID' -NotePropertyValue ([System.Guid]$comp.objectGUID).ToString() -Force
                                                } catch { }
                                            }
                                            # Add decrypted LAPS properties to existing object
                                            $comp | Add-Member -NotePropertyName 'msLAPS-Password' -NotePropertyValue $decryptedInfo.Password -Force
                                            $comp | Add-Member -NotePropertyName 'msLAPS-Account' -NotePropertyValue $decryptedInfo.Account -Force
                                            $comp | Add-Member -NotePropertyName 'msLAPS-Updated' -NotePropertyValue $decryptedInfo.UpdateTimestamp -Force
                                            # Remove raw encrypted blob from output
                                            $comp.PSObject.Properties.Remove('msLAPS-EncryptedPassword')
                                            $readableComputers += $comp
                                        }
                                    }
                                }
                            }
                        }

                        Write-Log "[Get-LAPSCredentialAccess] User is authorized for $authorizedCount of $($encryptedComputers.Count) encrypted LAPS computers"
                    }
                } else {
                    Write-Log "[Get-LAPSCredentialAccess] Could not retrieve token groups - skipping encrypted LAPS optimization"
                    # Fallback: try sampling approach
                    $sampleComputers = @(Get-DomainComputer -LDAPFilter "(msLAPS-EncryptedPassword=*)" -ResultLimit 3 @PSBoundParameters)
                    if ($sampleComputers.Count -gt 0) {
                        $decryptableSample = $sampleComputers | Where-Object { $_.'msLAPS-Password' }
                        if ($decryptableSample) {
                            Write-Log "[Get-LAPSCredentialAccess] Fallback: Decryption works, loading all"
                            $allEncrypted = @(Get-DomainComputer -LDAPFilter "(msLAPS-EncryptedPassword=*)" @PSBoundParameters)
                            $decryptable = $allEncrypted | Where-Object { $_.'msLAPS-Password' }
                            $readableComputers += @($decryptable)
                        }
                    }
                }
            }

            # Output results
            if (@($readableComputers).Count -gt 0) {
                Show-Line "Found $(@($readableComputers).Count) computer(s) with readable LAPS password:" -Class "Finding"
                $totalComputers = @($readableComputers).Count
                $currentIndex = 0
                foreach ($computer in $readableComputers) {
                    $currentIndex++
                    if ($totalComputers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking LAPS credential access" -Current $currentIndex -Total $totalComputers -ObjectName $computer.name }
                    $computer | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'LAPSCredential' -Force
                    Show-Object $computer
                }
                if ($totalComputers -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking LAPS credential access" -Completed }
            } else {
                Show-Line "No readable LAPS passwords found" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-LAPSCredentialAccess] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-LAPSCredentialAccess] Check completed"
    }
}




# ----- Get-BitLockerRecoveryKeyAccess.ps1 -----

function Get-BitLockerRecoveryKeyAccess {
    <#
    .SYNOPSIS
    Tests which BitLocker recovery keys the current user can read from Active Directory.

    .DESCRIPTION
    BitLocker recovery information is escrowed in AD as separate child objects
    (objectClass=msFVE-RecoveryInformation) below each computer object - NOT as an
    attribute on the computer object itself. The 48-digit recovery password lives in the
    msFVE-RecoveryPassword attribute, whose read access is gated by a control access
    right / ACL.

    This check performs a SINGLE domain-wide, server-side filtered subtree query:

        (&(objectClass=msFVE-RecoveryInformation)(msFVE-RecoveryPassword=*))

    The presence filter (msFVE-RecoveryPassword=*) is ACL-gated: the DC only returns
    recovery objects whose password the bound user is actually allowed to read - the
    exact same mechanism used for Legacy LAPS (ms-Mcs-AdmPwd=*) in Get-LAPSCredentialAccess.
    This keeps the result set limited to readable keys from the start, instead of
    enumerating every computer account.

    Performance:
    - Schema short-circuit: if BitLocker recovery escrow is not used in the domain, the
      expensive domain-wide query is skipped entirely (cached in $Script:BitLockerSchemaInfo).
    - Single paged subtree query (paging handled by Invoke-LDAPSearch).
    - Computer name is derived from the recovery object's parent DN (no extra LDAP queries).

    Related Checks:
    - Get-LAPSCredentialAccess (Creds): Which LAPS passwords can the current user read?

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-BitLockerRecoveryKeyAccess

    .EXAMPLE
    Get-BitLockerRecoveryKeyAccess -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential
    )

    begin {
        Write-Log "[Get-BitLockerRecoveryKeyAccess] Starting check"
    }

    process {
        try {
            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @PSBoundParameters)) {
                return
            }

            Show-SubHeader "Testing BitLocker recovery key read access for current user..." -ObjectType "BitLockerRecoveryKey"

            # ===== Step 1: Schema / feasibility short-circuit (cached) =====
            # Many environments do not escrow BitLocker recovery keys to AD. Detect this once
            # and cache it so we never run the expensive domain-wide query needlessly.
            $bitLockerPresent = $false

            if ($Script:BitLockerSchemaInfo) {
                $bitLockerPresent = $Script:BitLockerSchemaInfo.Present
                Write-Log "[Get-BitLockerRecoveryKeyAccess] Using cached schema info: Present=$bitLockerPresent"
            } else {
                $schemaDN = $Script:LDAPContext.SchemaNamingContext

                # Method 1: Schema partition query for the msFVE-RecoveryInformation class
                if ($schemaDN) {
                    try {
                        $schemaFilter = "(&(objectClass=classSchema)(|(lDAPDisplayName=msFVE-RecoveryInformation)(cn=ms-FVE-RecoveryInformation)))"
                        $schemaResult = @(Get-DomainObject -LDAPFilter $schemaFilter -SearchBase $schemaDN -Properties 'cn' -ResultLimit 1 @PSBoundParameters)
                        if ($schemaResult.Count -gt 0) {
                            $bitLockerPresent = $true
                            Write-Log "[Get-BitLockerRecoveryKeyAccess] msFVE-RecoveryInformation schema class found"
                        }
                    } catch {
                        Write-Log "[Get-BitLockerRecoveryKeyAccess] Schema query error: $($_.Exception.Message)"
                    }
                }

                # Method 2: Fallback - check if any recovery object exists (minimal query)
                if (-not $bitLockerPresent) {
                    $existsCheck = @(Get-DomainObject -LDAPFilter "(objectClass=msFVE-RecoveryInformation)" -Properties 'distinguishedName' -ResultLimit 1 @PSBoundParameters)
                    if ($existsCheck.Count -gt 0) {
                        $bitLockerPresent = $true
                        Write-Log "[Get-BitLockerRecoveryKeyAccess] msFVE-RecoveryInformation objects detected"
                    }
                }

                # Cache result for repeated calls within the same session
                $Script:BitLockerSchemaInfo = @{ Present = $bitLockerPresent }
            }

            if (-not $bitLockerPresent) {
                Show-Line "BitLocker recovery escrow is not used in this domain (no msFVE-RecoveryInformation objects found)" -Class "Note"
                return
            }

            # ===== Step 2: Single ACL-gated subtree query for readable recovery keys =====
            # The (msFVE-RecoveryPassword=*) presence filter only matches objects whose
            # password the bound user is permitted to read (ACL-based attribute return).
            Write-Log "[Get-BitLockerRecoveryKeyAccess] Querying for readable BitLocker recovery keys"

            $recoveryProperties = @(
                'msFVE-RecoveryPassword',
                'msFVE-RecoveryGuid',
                'msFVE-VolumeGuid',
                'whenCreated'
            )

            $recoveryObjects = @(Get-DomainObject -LDAPFilter "(&(objectClass=msFVE-RecoveryInformation)(msFVE-RecoveryPassword=*))" -Properties $recoveryProperties -Raw @PSBoundParameters)

            Write-Log "[Get-BitLockerRecoveryKeyAccess] Found $($recoveryObjects.Count) readable recovery key(s)"

            # ===== Step 3: Output =====
            if ($recoveryObjects.Count -gt 0) {
                Show-Line "Found $($recoveryObjects.Count) readable BitLocker recovery key(s):" -Class "Hint"

                $totalObjects = $recoveryObjects.Count
                $currentIndex = 0
                foreach ($recoveryObject in $recoveryObjects) {
                    $currentIndex++
                    if ($totalObjects -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking BitLocker recovery key access" -Current $currentIndex -Total $totalObjects -ObjectName $recoveryObject.distinguishedName }

                    # Derive computer name + parent DN from the recovery object's DN.
                    # Recovery object DN: CN=<datetime>{guid},CN=<COMPUTERNAME>,OU=...,DC=...
                    # The msFVE CN value never contains commas, so stripping the first RDN is safe.
                    $recoveryDN = [string]$recoveryObject.distinguishedName
                    $parentDN = $recoveryDN -replace '^CN=[^,]+,', ''
                    $computerName = if ($parentDN -match '^CN=([^,]+),') { $Matches[1] } else { $parentDN }
                    $recoveryObject | Add-Member -NotePropertyName 'ComputerName' -NotePropertyValue $computerName -Force
                    # Replace the noisy recovery-object DN with the parent computer DN for display
                    $recoveryObject | Add-Member -NotePropertyName 'distinguishedName' -NotePropertyValue $parentDN -Force

                    # Convert recovery/volume GUID byte arrays to readable GUID strings
                    foreach ($guidAttr in @('msFVE-RecoveryGuid', 'msFVE-VolumeGuid')) {
                        $guidValue = $recoveryObject.$guidAttr
                        if ($guidValue -is [byte[]] -and $guidValue.Length -eq 16) {
                            try {
                                $guidObj = New-Object System.Guid -ArgumentList (,$guidValue)
                                $recoveryObject | Add-Member -NotePropertyName $guidAttr -NotePropertyValue $guidObj.ToString() -Force
                            } catch {
                                Write-Log "[Get-BitLockerRecoveryKeyAccess] Failed to convert $guidAttr for '$parentDN': $($_.Exception.Message)"
                            }
                        }
                    }

                    # Format whenCreated (raw generalized time, e.g. 20240115103045.0Z)
                    $whenCreatedRaw = [string]$recoveryObject.whenCreated
                    if ($whenCreatedRaw -match '^(\d{14})') {
                        try {
                            $escrowTime = [datetime]::ParseExact($Matches[1], 'yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal)
                            $recoveryObject | Add-Member -NotePropertyName 'whenCreated' -NotePropertyValue ($escrowTime.ToString('yyyy-MM-dd HH:mm:ss') + ' UTC') -Force
                        } catch {
                            # Leave raw value if parsing fails
                        }
                    }

                    $recoveryObject | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'BitLockerRecoveryKey' -Force
                    Show-Object $recoveryObject
                }
                if ($totalObjects -gt $Script:ProgressThreshold) { Show-Progress -Activity "Checking BitLocker recovery key access" -Completed }
            } else {
                Show-Line "No readable BitLocker recovery keys found" -Class "Secure"
            }

        } catch {
            Write-Log "[Get-BitLockerRecoveryKeyAccess] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-BitLockerRecoveryKeyAccess] Check completed"
    }
}



# ----- Get-PasswordInDescription.ps1 -----

function Get-PasswordInDescription {
    <#
    .SYNOPSIS
    Detects user and computer accounts with potential passwords in description or info attributes.

    .DESCRIPTION
    Scans the 'description' and 'info' attributes of user and computer accounts for patterns that indicate credentials are stored in plaintext.
    Uses a two-tier detection system:

    Tier 1 (Finding): High-confidence patterns with explicit password assignments (e.g., "password=Secret123")
    Tier 2 (Hint): Lower-confidence patterns with generic credential mentions (e.g., "password" without value)

    Exclusion patterns filter out false positives from password policy text, help text, and placeholders.

    .PARAMETER Domain
    Target domain (optional, uses current domain if not specified)

    .PARAMETER Server
    Domain Controller to query (optional, uses auto-discovery if not specified)

    .PARAMETER Credential
    PSCredential object for authentication (optional, uses current user if not specified)

    .EXAMPLE
    Get-PasswordInDescription

    .EXAMPLE
    Get-PasswordInDescription -Domain "contoso.com" -Credential (Get-Credential)

    .NOTES
    Category: Creds
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC
    )

    begin {
        Write-Log "[Get-PasswordInDescription] Starting check"
    }

    process {
        try {
            # Build connection parameters (exclude OPSEC which Ensure-LDAPConnection doesn't accept)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            # Ensure LDAP connection (displays error if needed)
            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            Show-SubHeader "Searching for credentials in description/info attributes..." -ObjectType "PasswordInDescription"

            # OPSEC mode: Skip heavy-load enumeration
            if ($OPSEC) {
                Show-Line "OPSEC mode: Skipping password-in-description check (would check all users and computers)" -Class "Hint"
                return
            }

            # Tier 1: High-confidence patterns (password assignment with value)
            # passw\S* covers: password, passwd, passwort, passord, passwuert, pasvorto (EN/DE/NO/LU/EO)
            $tier1Patterns = @(
                @{ Pattern = 'passw\S*\s*[=:]\s*["''][^"'']{3,}["'']'; Description = "Password-variant assignment (quoted)" }
                @{ Pattern = 'passw\S*\s*[=:]\s*(?!["''])\S{3,}'; Description = "Password-variant assignment (unquoted)" }
                @{ Pattern = 'pwd\s*[=:]\s*\S{3,}'; Description = "Pwd assignment" }
                @{ Pattern = 'pw\s*[=:]\s*\S{3,}'; Description = "PW assignment" }
                @{ Pattern = '\bpass\s*[=:]\s*\S{3,}'; Description = "Pass assignment" }
                @{ Pattern = 'kennwort\s*[=:]\s*\S{3,}'; Description = "Kennwort assignment (German)" }
                @{ Pattern = '\bparol[ae]?\s*[=:]\s*\S{3,}'; Description = "Parola/parole/parol assignment (RO/LV/IT)" }
            )

            # Tier 2: Lower-confidence patterns (generic credential mentions)
            $tier2Patterns = @(
                @{ Pattern = 'passw\S*'; Description = "Password-variant mention (EN/DE/NO/LU/EO)" }
                @{ Pattern = '\bparol[ae]?\b'; Description = "Parola/parole/parol mention (RO/LV/IT)" }
                @{ Pattern = '\bcred(ential)?s?\b'; Description = "Credential mention" }
                @{ Pattern = '\b(secret|token)\s*[=:]\s*\S{5,}'; Description = "Secret/token assignment" }
            )

            # Exclusion patterns (skip if line matches these - password policy text, help, etc.)
            # Conservative approach: better to show a false positive than to hide a real password
            # Only exact terms - no wildcards for foreign words we haven't verified in real AD data
            $exclusionPatterns = @(
                # Policy/guideline text (EN/DE/IT/RO)
                'passw\S*\s*(policy|policies|requirement|guideline|richtlinie|anforderung)',
                '\bparol[ae]?\s*(policy|politica|cerinta)',
                # Modal verbs: "password must/should..." (EN/DE/NO/IT/RO)
                # Norwegian letters are written as regex \u escapes to keep this file pure ASCII:
                # \u00E5 = a with ring, \u00F8 = o with stroke
                'passw\S*\s+(must|should|cannot|shall|muss|soll|darf|kann|m\u00E5|b\u00F8r|deve|trebuie)\s+',
                # Technical terms: length, complexity, expiry (EN/DE/NO/IT)
                'passw\S*\s+(length|complexity|history|age|expir|wechsel|ablauf|historie|lengde|utl\u00F8p|lunghezza|scadenza)',
                # Reset/change/recover (EN/IT/RO)
                'passw\S*\s+(reset|change|recover|forgot|reimpost|cambiar|schimb)',
                '\bparol[ae]?\s+(reset|change|reimpost|cambiar|schimbar)',
                # Relative: "minimum/maximum password"
                '(minimum|maximum)\s+passw\S*',
                # Imperative: "set/change/update your password" (EN)
                '(set|change|update|reset)\s+(your|the|a)\s+passw\S*',
                # Placeholders
                'passw\S*\s*:\s*\*+',
                'passw\S*\s*:\s*<[^>]+>',
                # Prompts
                'Enter\s+(your\s+)?passw\S*',
                'passw\S*\s+prompt'
            )

            $findingCount = 0
            $hintCount = 0

            # Process both Users and Computers
            foreach ($objectType in @('User', 'Computer')) {
                Write-Log "[Get-PasswordInDescription] Checking $objectType accounts..."

                # Phase 1: Lightweight query - only fetch description + info (DN is always included)
                # This avoids loading ALL properties for potentially thousands of objects
                $candidates = if ($objectType -eq 'User') {
                    Get-DomainUser -LDAPFilter "(|(description=*)(info=*))" -Properties "description","info" @connectionParams
                } else {
                    Get-DomainComputer -LDAPFilter "(|(description=*)(info=*))" -Properties "description","info" @connectionParams
                }

                if (-not $candidates) { continue }

                $currentIndex = 0
                $totalCandidates = @($candidates).Count

                foreach ($candidate in @($candidates)) {
                    $currentIndex++

                    # Progress indicator for large candidate counts
                    if ($totalCandidates -gt 50) {
                        Show-Progress -Activity "Checking $objectType descriptions" `
                                     -Current $currentIndex `
                                     -Total $totalCandidates
                    }
                    $accountName = $candidate.distinguishedName
                    $attributesToCheck = @()

                    if ($candidate.description) { $attributesToCheck += @{ Name = 'description'; Value = $candidate.description } }
                    if ($candidate.info) { $attributesToCheck += @{ Name = 'info'; Value = $candidate.info } }

                    foreach ($attr in $attributesToCheck) {
                        $attrValue = [string]$attr.Value

                        # Check exclusion patterns first
                        $excluded = $false
                        foreach ($exPattern in $exclusionPatterns) {
                            if ($attrValue -match $exPattern) {
                                $excluded = $true
                                Write-Log "[Get-PasswordInDescription] Excluded $accountName ($($attr.Name)): matches exclusion '$exPattern'"
                                break
                            }
                        }
                        if ($excluded) { continue }

                        # Check Tier 1 patterns (Finding)
                        $isTier1 = $false
                        foreach ($t1 in $tier1Patterns) {
                            if ($attrValue -imatch $t1.Pattern) {
                                $isTier1 = $true
                                Write-Log "[Get-PasswordInDescription] TIER1 match on $accountName ($($attr.Name)): $($t1.Description)"
                                break
                            }
                        }

                        if ($isTier1) {
                            $findingCount++
                            # Phase 2: Re-fetch full object for Show-Object display
                            $fullObj = if ($objectType -eq 'User') {
                                @(Get-DomainUser -Identity $accountName -ShowOwner @connectionParams)[0]
                            } else {
                                @(Get-DomainComputer -Identity $accountName @connectionParams)[0]
                            }
                            if ($fullObj) {
                                $fullObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordInDescription' -Force
                                $fullObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue "$objectType - $($attr.Name) attribute" -Force
                                Show-Line "Probable credential found in $($attr.Name) of $objectType '$($fullObj.sAMAccountName)'" -Class Finding
                                Show-Object $fullObj
                            }
                            break  # One match per object is enough
                        }

                        # Check Tier 2 patterns (Hint)
                        $isTier2 = $false
                        foreach ($t2 in $tier2Patterns) {
                            if ($attrValue -imatch $t2.Pattern) {
                                $isTier2 = $true
                                Write-Log "[Get-PasswordInDescription] TIER2 match on $accountName ($($attr.Name)): $($t2.Description)"
                                break
                            }
                        }

                        if ($isTier2) {
                            $hintCount++
                            # Phase 2: Re-fetch full object for Show-Object display
                            $fullObj = if ($objectType -eq 'User') {
                                @(Get-DomainUser -Identity $accountName -ShowOwner @connectionParams)[0]
                            } else {
                                @(Get-DomainComputer -Identity $accountName @connectionParams)[0]
                            }
                            if ($fullObj) {
                                $fullObj | Add-Member -NotePropertyName '_adPEASObjectType' -NotePropertyValue 'PasswordInDescription' -Force
                                $fullObj | Add-Member -NotePropertyName '_adPEASContext' -NotePropertyValue "$objectType - $($attr.Name) attribute" -Force
                                Show-Line "Possible credential mention in $($attr.Name) of $objectType '$($fullObj.sAMAccountName)'" -Class Hint
                                Show-Object $fullObj
                            }
                            break  # One match per object is enough
                        }
                    }
                }

                # Clear progress bar for this object type
                if ($totalCandidates -gt 50) {
                    Show-Progress -Activity "Checking $objectType descriptions" -Completed
                }
            }

            if ($findingCount -eq 0 -and $hintCount -eq 0) {
                Show-Line "No credentials found in description or info attributes" -Class Secure
            } else {
                Write-Log "[Get-PasswordInDescription] Total: $findingCount finding(s), $hintCount hint(s)"
            }

        } catch {
            Write-Log "[Get-PasswordInDescription] Error: $_" -Level Error
        }
    }

    end {
        Write-Log "[Get-PasswordInDescription] Check completed"
    }
}




# ==============================================
# REPORTING MODULES
# ==============================================

# ----- Export-HTMLReport.ps1 -----

<#
.SYNOPSIS
    Exports adPEAS findings to an interactive HTML report.

.DESCRIPTION
    Generates a standalone HTML report from collected findings.
    The report includes:
    - Dark/Light theme toggle (persisted in localStorage)
    - Sidebar navigation by severity and category
    - Collapsible finding sections
    - Object detail cards with attribute highlighting
    - Export buttons (Print/PDF)
    - Search functionality

    This function is called automatically by Invoke-adPEAS when -HTMLReport is specified.

.PARAMETER OutputPath
    Path for the HTML report file.

.PARAMETER DefaultTheme
    Initial theme: 'Light' or 'Dark' (default: Dark)

.EXAMPLE
    Export-HTMLReport -OutputPath ".\report.html"

.EXAMPLE
    Export-HTMLReport -OutputPath ".\report.html" -DefaultTheme Dark

.NOTES
    Author: Alexander Sturz (@_61106960_)
#>

# Helper function for HTML encoding (works in PowerShell Core without System.Web)
function ConvertTo-HtmlEncode {
    param([string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return "" }
    return $Text.Replace('&', '&amp;').Replace('<', '&lt;').Replace('>', '&gt;').Replace('"', '&quot;').Replace("'", '&#39;')
}

# Helper function to fix JSON Unicode escapes from ConvertTo-Json
# PowerShell's ConvertTo-Json escapes special characters as \uXXXX which displays literally in HTML
function Repair-JsonUnicodeEscapes {
    param([string]$Json)
    if ([string]::IsNullOrEmpty($Json)) { return $Json }

    # Convert Unicode escapes back to readable characters (e.g., \u0027 -> ')
    $result = [System.Text.RegularExpressions.Regex]::Replace(
        $Json,
        '\\u([0-9a-fA-F]{4})',
        { param($m) [char]::ConvertFromUtf32([Convert]::ToInt32($m.Groups[1].Value, 16)) }
    )

    # Fix double-escaped backslashes: PowerShell strings use \\ for single backslash,
    # then ConvertTo-Json escapes each \ to \\, resulting in \\\\
    # We need to convert \\\\ back to \\ for proper display in tooltips
    $result = $result -replace '\\\\\\\\', '\\'

    return $result
}

function Export-HTMLReport {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$OutputPath,

        [Parameter(Mandatory=$false)]
        [ValidateSet('Light', 'Dark')]
        [string]$DefaultTheme = 'Dark'
    )

    begin {
        Write-Log "[Export-HTMLReport] Starting HTML report generation"

        # Get collected findings
        $findings = Get-FindingsCollection

        if (-not $findings -or $findings.Count -eq 0) {
            Write-Warning "[Export-HTMLReport] No findings collected. HTML report will be empty."
            $findings = @()
        }

        Write-Log "[Export-HTMLReport] Processing $($findings.Count) findings"

        # Get context information
        $domain = if ($Script:LDAPContext) { $Script:LDAPContext.Domain } else { "Unknown" }
        $server = if ($Script:LDAPContext) { $Script:LDAPContext.Server } else { "Unknown" }
        $user = if ($Script:LDAPContext -and $Script:LDAPContext.Username) { $Script:LDAPContext.Username } else { "$env:USERDOMAIN\$env:USERNAME" }
        $generatedDate = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
        $version = if ($Script:adPEASVersion) { $Script:adPEASVersion } else { "2.0.0" }

        # Use disclaimer from main script (decoded at startup)
        $disclaimer = if ($Script:adPEASDisclaimer) { $Script:adPEASDisclaimer } else { "" }
    }

    process {
        # Filter out Header/SubHeader for counting (they are structural, not findings)
        # Also exclude findings with Category="Unknown" (these lack check context and shouldn't be displayed)
        $contentFindings = $findings | Where-Object {
            $_.Type -notin @('Header', 'SubHeader') -and $_.Category -ne 'Unknown'
        }

        # Count items using the same logic as cards on the right side:
        # - Objects count as individual items
        # - KeyValue/Line groups (per SubHeader) count as 1 result each
        # This ensures left sidebar counts match right side card counts
        $cardCounts = Get-CardBasedCounts -AllFindings $findings

        $findingCount = $cardCounts.Finding
        $hintCount = $cardCounts.Hint
        $noteCount = $cardCounts.Note
        $secureCount = $cardCounts.Secure
        $totalCount = $cardCounts.Total

        # Group findings by category for navigation (using card-based counts)
        $categories = $cardCounts.Categories

        # Build navigation HTML
        $navHtml = Build-NavigationHtml -Categories $categories -Findings $contentFindings

        # Build findings sections HTML (pass all findings to preserve structure)
        $sectionsHtml = Build-FindingSectionsHtml -Findings $findings

        # Build the complete HTML
        $html = Get-HTMLTemplate

        # Critical: Verify template was loaded successfully
        if (-not $html) {
            Write-Error "[Export-HTMLReport] Failed to load HTML template. Ensure template files exist in 'templates/' directory or build the project first."
            return
        }

        # Export finding definitions as JSON for tooltips
        $findingDefsJson = Repair-JsonUnicodeEscapes (Export-FindingDefinitionsJson -Minified)

        # Export check descriptions as JSON for help buttons
        $checkDefsJson = Repair-JsonUnicodeEscapes (Export-CheckDescriptionsJson -Minified)

        # Build scoring context data for context-aware risk calculation
        $scoringContext = Build-ScoringContext -AllFindings $findings
        $scoringContextJson = Repair-JsonUnicodeEscapes ($scoringContext | ConvertTo-Json -Depth 10 -Compress)

        # Use literal .Replace() for ALL token substitutions, never -replace. The placeholders are
        # literal "{{...}}" strings (no regex needed), and the replacement VALUES are data-derived:
        # any value containing a '$' followed by digits (a SID, a managed-password ID, an account
        # name, a description) is parsed by -replace's replacement engine as a capture-group
        # reference "$<n>", and a long digit run overflows with "Capture group numbers must be less
        # than or equal to Int32.MaxValue", aborting the whole report. HTML-encoding does not help -
        # it does not escape '$'. .Replace() treats both arguments as literal text.
        $html = $html.Replace('{{DOMAIN}}', [string](ConvertTo-HtmlEncode $domain))
        $html = $html.Replace('{{SERVER}}', [string](ConvertTo-HtmlEncode $server))
        $html = $html.Replace('{{USER}}', [string](ConvertTo-HtmlEncode $user))
        $html = $html.Replace('{{GENERATED}}', [string]$generatedDate)
        $html = $html.Replace('{{VERSION}}', [string]$version)
        $html = $html.Replace('{{DEFAULT_THEME}}', [string]$DefaultTheme.ToLower())
        $html = $html.Replace('{{FINDING_COUNT}}', [string]$findingCount)
        $html = $html.Replace('{{HINT_COUNT}}', [string]$hintCount)
        $html = $html.Replace('{{NOTE_COUNT}}', [string]$noteCount)
        $html = $html.Replace('{{SECURE_COUNT}}', [string]$secureCount)
        $html = $html.Replace('{{TOTAL_COUNT}}', [string]$totalCount)
        $html = $html.Replace('{{DISCLAIMER}}', [string](ConvertTo-HtmlEncode $disclaimer))
        $html = $html.Replace('{{NAVIGATION}}', [string]$navHtml)
        $html = $html.Replace('{{FINDINGS_SECTIONS}}', [string]$sectionsHtml)
        # JSON blobs likewise use .Replace() - they contain PowerShell code like "$_" that -replace
        # would interpret as regex capture groups (same failure class as above).
        $html = $html.Replace('{{FINDING_DEFINITIONS_JSON}}', $findingDefsJson)
        $html = $html.Replace('{{CHECK_DESCRIPTIONS_JSON}}', $checkDefsJson)
        $html = $html.Replace('{{SCORING_CONTEXT_JSON}}', $scoringContextJson)

        # Generate scoring definitions from central PowerShell definitions
        $scoringDefinitionsJs = ConvertTo-ScoringJavaScript
        $html = $html.Replace('{{SCORING_DEFINITIONS}}', $scoringDefinitionsJs)

    }

    end {
        # Write HTML file
        # Use .NET WriteAllText with BOM-less UTF-8 encoding.
        # PowerShell 5.1's Out-File -Encoding UTF8 always prepends a UTF-8 BOM (EF BB BF),
        # which can interfere with favicon data URI detection in Chromium-based browsers,
        # especially when the report is opened via the file:// protocol.
        try {
            $utf8NoBom = New-Object System.Text.UTF8Encoding $false
            $resolvedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputPath)
            [System.IO.File]::WriteAllText($resolvedPath, $html, $utf8NoBom)
            Write-Log "[Export-HTMLReport] Report saved to: $OutputPath"
        }
        catch {
            # Re-throw with context - no separate warning needed as throw displays the error
            throw "Failed to write HTML report to '$OutputPath': $_"
        }
    }
}

<#
.SYNOPSIS
    Calculates card-based counts matching the right-side card display logic.
.DESCRIPTION
    Processes findings to calculate counts that match what's shown on cards:
    - Objects count as individual items
    - KeyValue/Line groups (per SubHeader) count as 1 result each
    This ensures sidebar counts match card counts.
#>
function Get-CardBasedCounts {
    param(
        [array]$AllFindings
    )

    # Initialize counters
    $counts = @{
        Finding = 0
        Hint = 0
        Note = 0
        Secure = 0
        Total = 0
        Categories = @()
    }

    # Track category counts
    $categoryCounts = @{}

    # Process findings in order, grouping by SubHeader
    $currentSubHeader = $null
    $currentFindings = @()
    $currentCategory = $null

    foreach ($finding in $AllFindings) {
        if ($finding.Type -eq 'SubHeader') {
            # Process previous group if exists
            if ($currentSubHeader -and $currentFindings.Count -gt 0) {
                $groupCount = Get-GroupItemCount -Findings $currentFindings
                $groupSeverity = Get-GroupSeverity -Findings $currentFindings

                # Add to severity count
                $counts[$groupSeverity] += $groupCount

                # Add to category count
                if ($currentCategory -and $currentCategory -ne 'Unknown') {
                    if (-not $categoryCounts.ContainsKey($currentCategory)) {
                        $categoryCounts[$currentCategory] = 0
                    }
                    $categoryCounts[$currentCategory] += $groupCount
                }
            }

            # Start new group
            $currentSubHeader = $finding.Text
            $currentFindings = @()
        }
        elseif ($finding.Type -notin @('Header', 'SubHeader') -and $finding.Category -ne 'Unknown') {
            # Content finding
            $currentFindings += $finding
            $currentCategory = $finding.Category
        }
    }

    # Process last group
    if ($currentSubHeader -and $currentFindings.Count -gt 0) {
        $groupCount = Get-GroupItemCount -Findings $currentFindings
        $groupSeverity = Get-GroupSeverity -Findings $currentFindings

        $counts[$groupSeverity] += $groupCount

        if ($currentCategory -and $currentCategory -ne 'Unknown') {
            if (-not $categoryCounts.ContainsKey($currentCategory)) {
                $categoryCounts[$currentCategory] = 0
            }
            $categoryCounts[$currentCategory] += $groupCount
        }
    }

    # Calculate total
    $counts.Total = $counts.Finding + $counts.Hint + $counts.Note + $counts.Secure

    # Convert category counts to Group-Object format
    $counts.Categories = $categoryCounts.GetEnumerator() | ForEach-Object {
        [PSCustomObject]@{
            Name = $_.Key
            Count = $_.Value
        }
    } | Sort-Object Name

    return $counts
}

<#
.SYNOPSIS
    Builds scoring context data for context-aware risk scoring.
.DESCRIPTION
    Extracts relevant information from findings for JavaScript-based scoring:
    - Account information: SID, privileged group memberships, password age
    - Finding correlations: same account appearing in multiple checks
    - Credential exposure: encryption types, password policies
    This enables more accurate risk scoring based on actual impact.
#>
function Build-ScoringContext {
    param(
        [array]$AllFindings
    )

    $scoringContext = @{
        # Map of account SID -> account info (memberOf, pwdLastSet, etc.)
        accounts = @{}
        # Map of finding card ID -> additional context
        findingContext = @{}
        # Correlation data: which accounts appear in which checks
        correlations = @{}
        # Domain-level info
        domainInfo = @{
            passwordPolicy = $null
            krbtgtLastReset = $null
        }
    }

    # Track which accounts appear in which check types
    $accountToChecks = @{}

    foreach ($finding in $AllFindings) {
        if ($finding.Type -ne 'Object' -or -not $finding.Object) {
            continue
        }

        $obj = $finding.Object
        $checkTitle = $finding.CheckTitle

        # Extract account identifier (SID preferred, fallback to DN or sAMAccountName)
        $accountId = $null
        if ($obj.objectSid) {
            $accountId = $obj.objectSid
        } elseif ($obj.distinguishedName) {
            $accountId = $obj.distinguishedName
        } elseif ($obj.sAMAccountName) {
            $accountId = $obj.sAMAccountName
        }

        if (-not $accountId) {
            continue
        }

        # Track which checks this account appears in
        if (-not $accountToChecks.ContainsKey($accountId)) {
            $accountToChecks[$accountId] = @()
        }
        if ($checkTitle -and $checkTitle -notin $accountToChecks[$accountId]) {
            $accountToChecks[$accountId] += $checkTitle
        }

        # Build/update account info
        if (-not $scoringContext.accounts.ContainsKey($accountId)) {
            $scoringContext.accounts[$accountId] = @{
                sid = $obj.objectSid
                name = $obj.sAMAccountName
                dn = $obj.distinguishedName
                memberOf = @()
                memberOfSIDs = @()
                pwdLastSet = $null
                pwdAgeDays = $null
                encryptionTypes = @()
                uacFlags = @()
                isAdmin = $false
                adminTier = 'none'  # Microsoft Tiering: 'tier0'=DA/EA/SA, 'tier1'=operators, 'tier2'=other privileged, 'none'=standard
                isProtectedUser = $false  # Member of Protected Users group
            }
        }

        $acctInfo = $scoringContext.accounts[$accountId]

        # Extract memberOf (group names and SIDs)
        if ($obj.memberOf) {
            $groups = @($obj.memberOf)
            foreach ($groupDN in $groups) {
                if ($groupDN -is [string] -and $groupDN -match '^CN=([^,]+)') {
                    $groupName = $matches[1]
                    if ($groupName -notin $acctInfo.memberOf) {
                        $acctInfo.memberOf += $groupName
                    }
                }
            }
        }

        # Check for privilegedGroups (new format with SID)
        if ($obj.privilegedGroups) {
            foreach ($grp in $obj.privilegedGroups) {
                if ($grp.SID) {
                    if ($grp.SID -notin $acctInfo.memberOfSIDs) {
                        $acctInfo.memberOfSIDs += $grp.SID
                    }
                    # Check for Tier 0 admin groups (Domain Admins -512, Enterprise Admins -519, Schema Admins -518)
                    if ($grp.SID -match '-512$' -or $grp.SID -match '-519$' -or $grp.SID -match '-518$') {
                        $acctInfo.isAdmin = $true
                        $acctInfo.adminTier = 'tier0'
                    }
                    # Tier 1: Operators (Account Ops -548, Server Ops -549, Backup Ops -551)
                    elseif ($grp.SID -match '-(548|549|551)$' -and $acctInfo.adminTier -ne 'tier0') {
                        $acctInfo.isAdmin = $true
                        $acctInfo.adminTier = 'tier1'
                    }
                    # Tier 2: Other privileged
                    elseif ($acctInfo.adminTier -eq 'none') {
                        $acctInfo.isAdmin = $true
                        $acctInfo.adminTier = 'tier2'
                    }
                    # Protected Users group (SID ending with -525)
                    if ($grp.SID -match '-525$') {
                        $acctInfo.isProtectedUser = $true
                    }
                }
                if ($grp.Name -and $grp.Name -notin $acctInfo.memberOf) {
                    $acctInfo.memberOf += $grp.Name
                }
            }
        }

        # Also check memberOf for Protected Users (for objects that don't have privilegedGroups)
        if ($obj.memberOf -and -not $acctInfo.isProtectedUser) {
            foreach ($groupDN in @($obj.memberOf)) {
                # Check by name pattern (case-insensitive)
                if ($groupDN -match 'CN=Protected Users,') {
                    $acctInfo.isProtectedUser = $true
                    break
                }
            }
        }

        # Extract pwdLastSet and calculate age
        if ($obj.pwdLastSet -and -not $acctInfo.pwdLastSet) {
            $acctInfo.pwdLastSet = $obj.pwdLastSet
            # Calculate password age in days
            try {
                if ($obj.pwdLastSet -is [datetime]) {
                    $acctInfo.pwdAgeDays = [math]::Floor(((Get-Date) - $obj.pwdLastSet).TotalDays)
                } elseif ($obj.pwdLastSet -is [string] -and $obj.pwdLastSet -match '\d{4}') {
                    $pwdDate = [datetime]::Parse($obj.pwdLastSet)
                    $acctInfo.pwdAgeDays = [math]::Floor(((Get-Date) - $pwdDate).TotalDays)
                }
            } catch {
                # Ignore parsing errors
            }
        }

        # Extract encryption types (for Kerberoast analysis)
        if ($obj.'msDS-SupportedEncryptionTypes') {
            $encTypes = $obj.'msDS-SupportedEncryptionTypes'
            if ($encTypes) {
                # Decode encryption type flags
                $encValue = 0
                if ($encTypes -is [int]) { $encValue = $encTypes }
                elseif ($encTypes -is [string] -and $encTypes -match '^\d+$') { $encValue = [int]$encTypes }

                if ($encValue -band 0x1) { $acctInfo.encryptionTypes += 'DES-CBC-CRC' }
                if ($encValue -band 0x2) { $acctInfo.encryptionTypes += 'DES-CBC-MD5' }
                if ($encValue -band 0x4) { $acctInfo.encryptionTypes += 'RC4-HMAC' }
                if ($encValue -band 0x8) { $acctInfo.encryptionTypes += 'AES128' }
                if ($encValue -band 0x10) { $acctInfo.encryptionTypes += 'AES256' }
            }
        }

        # Extract UAC flags
        if ($obj.userAccountControl -and $obj.userAccountControl -is [array]) {
            $acctInfo.uacFlags = @($obj.userAccountControl)
        }

        # Update the account info
        $scoringContext.accounts[$accountId] = $acctInfo
    }

    # Build correlations: which accounts have multiple risky findings
    foreach ($accountId in $accountToChecks.Keys) {
        $checks = $accountToChecks[$accountId]
        if ($checks.Count -gt 1) {
            $scoringContext.correlations[$accountId] = @{
                checks = $checks
                count = $checks.Count
                # Check for particularly dangerous combinations
                hasDCSync = $checks -match 'DCSync|Replication' | Select-Object -First 1
                hasKerberoast = $checks -match 'Kerberoast' | Select-Object -First 1
                hasASREP = $checks -match 'AS-?REP' | Select-Object -First 1
                hasDelegation = $checks -match 'Delegation' | Select-Object -First 1
            }
        }
    }

    # Extract domain password policy from findings (if available)
    # Look for Password Policy findings which contain maxPwdAge
    foreach ($finding in $AllFindings) {
        if ($finding.CheckTitle -match 'Password Policy' -and $finding.Object) {
            $policyObj = $finding.Object

            # Extract maxPwdAge (maximum password age in days)
            if ($policyObj.maxPwdAge) {
                $maxAge = $policyObj.maxPwdAge
                # maxPwdAge can be in different formats: days as int, or timespan string
                if ($maxAge -is [int] -or $maxAge -is [double]) {
                    $scoringContext.domainInfo.maxPwdAgeDays = [int]$maxAge
                } elseif ($maxAge -is [string] -and $maxAge -match '(\d+)') {
                    $scoringContext.domainInfo.maxPwdAgeDays = [int]$matches[1]
                }
            }

            # Extract minPwdLength (handles both "12" and "12 characters" formats)
            if ($policyObj.minPwdLength) {
                $minLen = $policyObj.minPwdLength
                if ($minLen -is [int]) {
                    $scoringContext.domainInfo.minPwdLength = $minLen
                } elseif ($minLen -is [string] -and $minLen -match '(\d+)') {
                    $scoringContext.domainInfo.minPwdLength = [int]$matches[1]
                }
            }

            # Extract lockout settings (handles both "5" and "After 5 failed attempts" formats)
            if ($policyObj.lockoutThreshold) {
                $lockout = $policyObj.lockoutThreshold
                if ($lockout -is [int]) {
                    $scoringContext.domainInfo.lockoutThreshold = $lockout
                } elseif ($lockout -is [string] -and $lockout -match '(\d+)') {
                    $scoringContext.domainInfo.lockoutThreshold = [int]$matches[1]
                }
            }

            # Password complexity - pwdProperties is a bitmask
            # Bit 0 (value 1) = DOMAIN_PASSWORD_COMPLEX
            # Check various property names used in different contexts
            $complexityEnabled = $false

            if ($policyObj.pwdProperties) {
                $pwdProps = $policyObj.pwdProperties
                if ($pwdProps -is [int]) {
                    # Bit 0 = complexity required
                    $complexityEnabled = ($pwdProps -band 1) -eq 1
                } elseif ($pwdProps -is [string] -and $pwdProps -match '^\d+$') {
                    $complexityEnabled = ([int]$pwdProps -band 1) -eq 1
                }
            }

            # Also check explicit PasswordComplexity property (from some checks)
            if ($policyObj.PasswordComplexity) {
                $complexVal = $policyObj.PasswordComplexity
                if ($complexVal -eq $true -or $complexVal -eq 1 -or $complexVal -eq 'Enabled' -or $complexVal -eq 'True') {
                    $complexityEnabled = $true
                }
            }

            # Check for 'Complexity' in string representations
            if ($policyObj.passwordComplexityEnabled -or $policyObj.ComplexityEnabled) {
                $complexityEnabled = $true
            }

            $scoringContext.domainInfo.complexityEnabled = $complexityEnabled

            break  # Found policy, no need to continue
        }
    }

    # If no policy found in findings, use defaults (assume weak policy = higher risk)
    if (-not $scoringContext.domainInfo.maxPwdAgeDays) {
        $scoringContext.domainInfo.maxPwdAgeDays = 0  # 0 = never expires (worst case)
    }

    # ========== NEW: Build findings metadata for JSON-based scoring ==========
    # This eliminates the need for DOM traversal in JavaScript
    # Each entry represents one finding card (SubHeader group)
    $scoringContext.findingCards = @()

    $currentSubHeader = $null
    $currentCategory = $null
    $currentObjectType = $null
    $currentFindings = @()

    foreach ($finding in $AllFindings) {
        if ($finding.Type -eq 'Header') {
            # Flush previous group
            if ($currentSubHeader -and $currentFindings.Count -gt 0) {
                $cardMeta = Build-FindingCardMetadata -Title $currentSubHeader -Category $currentCategory -ObjectType $currentObjectType -Findings $currentFindings -ScoringContext $scoringContext
                if ($cardMeta) {
                    $scoringContext.findingCards += $cardMeta
                }
            }
            $currentSubHeader = $null
            $currentCategory = $null
            $currentObjectType = $null
            $currentFindings = @()
        }
        elseif ($finding.Type -eq 'SubHeader') {
            # Flush previous group
            if ($currentSubHeader -and $currentFindings.Count -gt 0) {
                $cardMeta = Build-FindingCardMetadata -Title $currentSubHeader -Category $currentCategory -ObjectType $currentObjectType -Findings $currentFindings -ScoringContext $scoringContext
                if ($cardMeta) {
                    $scoringContext.findingCards += $cardMeta
                }
            }
            $currentSubHeader = $finding.Text
            $currentObjectType = $finding.ObjectType
            $currentFindings = @()
        }
        else {
            # Content finding
            if ($finding.Category -ne 'Unknown') {
                if (-not $currentCategory) {
                    $currentCategory = ($finding.Category.ToLower() -replace '\s+', '-') -replace '[^a-z0-9\-]', ''
                }
                $currentFindings += $finding
            }
        }
    }

    # Flush last group
    if ($currentSubHeader -and $currentFindings.Count -gt 0) {
        $cardMeta = Build-FindingCardMetadata -Title $currentSubHeader -Category $currentCategory -ObjectType $currentObjectType -Findings $currentFindings -ScoringContext $scoringContext
        if ($cardMeta) {
            $scoringContext.findingCards += $cardMeta
        }
    }

    return $scoringContext
}

<#
.SYNOPSIS
    Builds metadata for a single finding card for JSON-based scoring.
.DESCRIPTION
    Extracts all information needed for score calculation without DOM traversal:
    - Card title, severity, category
    - Object count
    - Account SID (for context lookup)
    - Section name (for display)
#>
function Build-FindingCardMetadata {
    param(
        [string]$Title,
        [string]$Category,
        [string]$ObjectType,
        [array]$Findings,
        [hashtable]$ScoringContext
    )

    # Determine card severity (highest among findings)
    # Determine card severity from findings
    # Priority: Show-Line severity > Object AttributeSeverities
    $cardSeverity = 'note'
    $severityPriority = @{ 'finding' = 4; 'hint' = 3; 'secure' = 2; 'note' = 1; 'standard' = 0 }
    $currentPriority = 1

    foreach ($f in $Findings) {
        if ($f.Type -eq 'Object' -and $f.AttributeSeverities) {
            # Check attribute-level severities for objects
            foreach ($attrSev in $f.AttributeSeverities.Values) {
                $sevLower = $attrSev.ToLower()
                $priority = $severityPriority[$sevLower]
                if ($null -ne $priority -and $priority -gt $currentPriority) {
                    $currentPriority = $priority
                    $cardSeverity = $sevLower
                    if ($cardSeverity -eq 'finding') { break }
                }
            }
        } elseif ($f.Severity) {
            # Check Show-Line severity (Line/KeyValue findings)
            $sevLower = $f.Severity.ToLower()
            $priority = $severityPriority[$sevLower]
            if ($null -ne $priority -and $priority -gt $currentPriority) {
                $currentPriority = $priority
                $cardSeverity = $sevLower
            }
        }
        if ($cardSeverity -eq 'finding') { break }
    }

    # Count objects
    $objectCount = @($Findings | Where-Object { $_.Type -eq 'Object' }).Count
    if ($objectCount -eq 0) { $objectCount = 1 }

    # Find account SID from first object (for context lookup)
    $accountSID = $null
    foreach ($f in $Findings) {
        if ($f.Type -eq 'Object' -and $f.Object) {
            $obj = $f.Object
            if ($obj.objectSid) {
                $accountSID = $obj.objectSid
                break
            } elseif ($obj.distinguishedName) {
                $accountSID = $obj.distinguishedName
                break
            } elseif ($obj.sAMAccountName) {
                $accountSID = $obj.sAMAccountName
                break
            }
        }
    }

    # Get section name from CheckTitle
    $section = if ($Findings.Count -gt 0 -and $Findings[0].CheckTitle) {
        # Use the check's category as section
        $Findings[0].Category
    } else {
        $Category
    }

    # Collect vulnerability tags from objects (e.g., "ESC1", "ESC4" from ADCS templates)
    # These are used by JS scoring to match against findingBaseScores titles
    $vulnTags = @()
    # Collect FindingIds from attribute triggers and line findings
    # Used by JS to look up remediation/impact from findingDefinitions
    $findingIds = @()
    foreach ($f in $Findings) {
        if ($f.Type -eq 'Object' -and $f.Object) {
            $obj = $f.Object
            if ($obj.Vulnerabilities) {
                # Vulnerabilities can be "ESC1, ESC4" (comma-separated string)
                $tags = @($obj.Vulnerabilities -split ',\s*' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
                foreach ($tag in $tags) {
                    if ($tag -notin $vulnTags) {
                        $vulnTags += $tag
                    }
                }
            }
            # Extract FindingIds from object attributes via trigger matching
            if ($f.AttributeSeverities) {
                foreach ($attrName in $f.AttributeSeverities.Keys) {
                    $attrSev = $f.AttributeSeverities[$attrName]
                    if ($attrSev -eq 'Finding' -or $attrSev -eq 'Hint') {
                        $attrValue = $obj.$attrName
                        if ($null -ne $attrValue) {
                            $fid = Get-FindingIdForAttribute -Name $attrName -Value $attrValue
                            if ($fid -and $fid -notin $findingIds) {
                                $findingIds += $fid
                            }
                        }
                    }
                }
            }
        } elseif ($f.FindingId -and $f.FindingId -notin $findingIds) {
            # Line/KeyValue findings with explicit FindingId
            $findingIds += $f.FindingId
        }
    }

    return @{
        title = $Title
        severity = $cardSeverity
        category = $Category
        section = $section
        objectCount = $objectCount
        accountSID = $accountSID
        vulnerabilities = $vulnTags
        objectType = $ObjectType
        findingIds = $findingIds
    }
}

<#
.SYNOPSIS
    Gets item count for a group using card logic.
#>
function Get-GroupItemCount {
    param([array]$Findings)

    $objectCount = @($Findings | Where-Object { $_.Type -eq 'Object' }).Count

    if ($objectCount -gt 0) {
        return $objectCount
    } else {
        # No objects = 1 result (cohesive KeyValue/Line result)
        return 1
    }
}

<#
.SYNOPSIS
    Gets the highest severity for a group.
.DESCRIPTION
    Determines the highest severity by checking:
    1. For Objects: Check AttributeSeverities (actual attribute-level analysis)
    2. For Lines/KeyValue: Use the direct Severity property
    Priority: Finding > Hint > Secure > Note
#>
function Get-GroupSeverity {
    param([array]$Findings)

    $severityPriority = @{ 'Finding' = 4; 'Hint' = 3; 'Secure' = 2; 'Note' = 1; 'Standard' = 0 }
    $highestPriority = 0
    $highestSeverity = 'Note'

    foreach ($f in $Findings) {
        # For Objects: Check AttributeSeverities for actual severity
        if ($f.Type -eq 'Object' -and $f.AttributeSeverities) {
            foreach ($attrSev in $f.AttributeSeverities.Values) {
                $priority = $severityPriority[$attrSev]
                if ($null -ne $priority -and $priority -gt $highestPriority) {
                    $highestPriority = $priority
                    $highestSeverity = $attrSev
                    if ($highestSeverity -eq 'Finding') { return 'Finding' }  # Can't get higher
                }
            }
        }
        # For Lines/KeyValue: Use direct Severity (from Show-Line -Class)
        elseif ($f.Severity) {
            $priority = $severityPriority[$f.Severity]
            if ($null -ne $priority -and $priority -gt $highestPriority) {
                $highestPriority = $priority
                $highestSeverity = $f.Severity
                if ($highestSeverity -eq 'Finding') { return 'Finding' }
            }
        }
    }

    return $highestSeverity
}

<#
.SYNOPSIS
    Builds the navigation HTML for the sidebar.
#>
function Build-NavigationHtml {
    param(
        [array]$Categories,
        [array]$Findings
    )

    $nav = [System.Text.StringBuilder]::new()

    # Categories section
    # Calculate total findings across all categories
    $totalCategoryFindings = ($Categories | Measure-Object -Property Count -Sum).Sum
    if (-not $totalCategoryFindings) { $totalCategoryFindings = 0 }

    [void]$nav.AppendLine('<div class="sidebar-section">')
    [void]$nav.AppendLine('    <div class="sidebar-title">Categories</div>')
    [void]$nav.AppendLine('    <a class="nav-item category-filter" data-category="all" href="javascript:void(0)" onclick="filterByCategory(''all'')">')
    [void]$nav.AppendLine('        All Categories')
    [void]$nav.AppendLine("        <span class=`"count`">$totalCategoryFindings</span>")
    [void]$nav.AppendLine('    </a>')

    foreach ($cat in $Categories) {
        $catName = $cat.Name
        $catCount = $cat.Count
        # XSS Protection: Sanitize category ID - only allow alphanumeric and hyphens
        $catId = ($catName.ToLower() -replace '\s+', '-') -replace '[^a-z0-9\-]', ''
        # HTML-encode category name and ID to prevent XSS
        $catNameEncoded = [System.Net.WebUtility]::HtmlEncode($catName)
        $catIdEncoded = ConvertTo-HtmlEncode $catId

        [void]$nav.AppendLine("    <a class=`"nav-item category-filter`" data-category=`"$catIdEncoded`" href=`"javascript:void(0)`" onclick=`"filterByCategory('$catIdEncoded')`">")
        [void]$nav.AppendLine("        $catNameEncoded")
        [void]$nav.AppendLine("        <span class=`"count`">$catCount</span>")
        [void]$nav.AppendLine("    </a>")
    }

    [void]$nav.AppendLine('</div>')

    return $nav.ToString()
}

<#
.SYNOPSIS
    Builds the findings sections HTML following the console output structure.
.DESCRIPTION
    Processes findings in order, using Header/SubHeader entries to structure
    the output similar to what the user sees on the console.

    The category for each section is derived from the first content finding's
    Category property, which matches the navigation categories.
#>
function Build-FindingSectionsHtml {
    param(
        [array]$Findings
    )

    $sections = [System.Text.StringBuilder]::new()

    $currentHeader = $null
    $currentSubHeader = $null
    $currentSubHeaderObjectType = $null  # Track ObjectType from SubHeader
    $currentFindings = [System.Collections.ArrayList]::new()
    $currentCategory = $null
    $sectionStarted = $false
    $cardIndex = 0  # Tracks index into scoringContext.findingCards

    # Process findings in order (they are collected in console output order)
    foreach ($finding in $Findings) {

        if ($finding.Type -eq 'Header') {
            # Close previous section if exists
            if ($sectionStarted) {
                # Close previous subheader card if exists
                if ($currentSubHeader -and $currentFindings.Count -gt 0) {
                    $cardHtml = Build-FindingCardHtml -Title $currentSubHeader -Findings $currentFindings -Category $currentCategory -ObjectType $currentSubHeaderObjectType -CardIndex $cardIndex
                    $cardIndex++
                    [void]$sections.AppendLine($cardHtml)
                }
                [void]$sections.AppendLine("    </div>")
                [void]$sections.AppendLine("</section>")
            }

            # Start new section (but don't output HTML yet - need category from first finding)
            $currentHeader = $finding.Text -replace '^\++\s*|\s*\++$', ''  # Remove +++++ decorations
            $currentCategory = $null  # Will be set from first content finding
            $currentSubHeader = $null
            $currentSubHeaderObjectType = $null
            $currentFindings = [System.Collections.ArrayList]::new()
            $sectionStarted = $false
        }
        elseif ($finding.Type -eq 'SubHeader') {
            # Close previous subheader card if exists
            if ($currentSubHeader -and $currentFindings.Count -gt 0) {
                $cardHtml = Build-FindingCardHtml -Title $currentSubHeader -Findings $currentFindings -Category $currentCategory -ObjectType $currentSubHeaderObjectType -CardIndex $cardIndex
                $cardIndex++
                [void]$sections.AppendLine($cardHtml)
            }

            # Start new subheader group - capture ObjectType if present
            $currentSubHeader = $finding.Text
            $currentSubHeaderObjectType = $finding.ObjectType  # May be $null if not set
            $currentFindings = [System.Collections.ArrayList]::new()
        }
        else {
            # Skip findings with Category="Unknown" (they lack check context)
            if ($finding.Category -eq 'Unknown') {
                continue
            }

            # Content finding - derive category from first one
            if (-not $sectionStarted -and $currentHeader) {
                # Get category from this finding (e.g., "Accounts", "Domain")
                # XSS Protection: Sanitize category - only allow alphanumeric and hyphens
                $currentCategory = ($finding.Category.ToLower() -replace '\s+', '-') -replace '[^a-z0-9\-]', ''
                $sectionId = "cat-$currentCategory"
                $currentCategoryEncoded = ConvertTo-HtmlEncode $currentCategory

                [void]$sections.AppendLine("<section id=`"$sectionId`" class=`"section`" data-category=`"$currentCategoryEncoded`">")
                [void]$sections.AppendLine("    <div class=`"section-header`">")
                [void]$sections.AppendLine("        <div class=`"section-title`">$(ConvertTo-HtmlEncode $currentHeader)</div>")
                [void]$sections.AppendLine("    </div>")
                [void]$sections.AppendLine("    <div class=`"section-content`">")
                $sectionStarted = $true
            }

            # Add finding to current group
            [void]$currentFindings.Add($finding)
        }
    }

    # Close last section
    if ($sectionStarted) {
        if ($currentSubHeader -and $currentFindings.Count -gt 0) {
            $cardHtml = Build-FindingCardHtml -Title $currentSubHeader -Findings $currentFindings -Category $currentCategory -ObjectType $currentSubHeaderObjectType -CardIndex $cardIndex
            $cardIndex++
            [void]$sections.AppendLine($cardHtml)
        }
        [void]$sections.AppendLine("    </div>")
        [void]$sections.AppendLine("</section>")
    }

    return $sections.ToString()
}

<#
.SYNOPSIS
    Builds HTML for a single finding card (subheader group).
#>
function Build-FindingCardHtml {
    param(
        [string]$Title,
        [array]$Findings,
        [string]$Category,
        [string]$ObjectType,  # ObjectType from SubHeader for ObjectTypeDefinitions lookup
        [int]$CardIndex = -1  # Index into scoringContext.findingCards for score calculation
    )

    $card = [System.Text.StringBuilder]::new()

    # Determine card severity from findings
    # Priority: Show-Line severity > Object AttributeSeverities
    $cardSeverity = 'note'
    $severityPriority = @{ 'finding' = 4; 'hint' = 3; 'secure' = 2; 'note' = 1; 'standard' = 0 }
    $currentPriority = 1  # Start with 'note'

    foreach ($f in $Findings) {
        # For Objects: Check AttributeSeverities for actual severity
        if ($f.Type -eq 'Object' -and $f.AttributeSeverities) {
            foreach ($attrSev in $f.AttributeSeverities.Values) {
                $sevLower = $attrSev.ToLower()
                $priority = $severityPriority[$sevLower]
                if ($null -ne $priority -and $priority -gt $currentPriority) {
                    $currentPriority = $priority
                    $cardSeverity = $sevLower
                    if ($cardSeverity -eq 'finding') { break }  # Can't get higher
                }
            }
        }
        # For Lines/KeyValue: Use the Finding's Severity directly (from Show-Line -Class)
        elseif ($f.Severity) {
            $sevLower = $f.Severity.ToLower()
            $priority = $severityPriority[$sevLower]
            if ($null -ne $priority -and $priority -gt $currentPriority) {
                $currentPriority = $priority
                $cardSeverity = $sevLower
            }
        }

        if ($cardSeverity -eq 'finding') { break }  # Can't get higher than finding
    }

    # Count items intelligently:
    # - Objects (AD objects): count each as individual item
    # - KeyValue only (no Objects): this is ONE result (e.g., domain info, password policy)
    # - Lines only: also ONE result
    $objectCount = @($Findings | Where-Object { $_.Type -eq 'Object' }).Count

    # Determine what to display
    $countHtml = if ($objectCount -gt 0) {
        # Has Objects: show count (e.g., "3 item(s)" for 3 Kerberoastable users)
        "<span class=`"finding-count`">$objectCount item(s)</span>"
    } else {
        # No Objects (only KeyValue/Line): this is ONE cohesive result
        "<span class=`"finding-count`">1 result</span>"
    }

    # Use ObjectType for tooltip lookup and card title
    # Priority 1: ObjectType parameter (passed from SubHeader)
    # Priority 2: First object's _adPEASObjectType (fallback)
    $resolvedObjectType = $ObjectType

    # Fallback: Look for _adPEASObjectType in any finding object if not passed
    if (-not $resolvedObjectType) {
        foreach ($f in $Findings) {
            if ($f.Type -eq 'Object' -and $f.Object -and $f.Object._adPEASObjectType) {
                $resolvedObjectType = $f.Object._adPEASObjectType
                break
            }
        }
    }

    # Use ObjectTypeDefinitions.SectionTitle as card title (more professional for HTML report)
    # Console output uses verb-form ("Analyzing..."), HTML uses noun-form ("Domain Password Policy")
    $displayTitle = if ($resolvedObjectType -and $Script:ObjectTypeDefinitions[$resolvedObjectType] -and $Script:ObjectTypeDefinitions[$resolvedObjectType].SectionTitle) {
        $Script:ObjectTypeDefinitions[$resolvedObjectType].SectionTitle
    } else {
        $Title  # Fallback to original title if no SectionTitle exists
    }

    # Get Summary as subtitle from ObjectTypeDefinitions
    $subtitle = if ($resolvedObjectType -and $Script:ObjectTypeDefinitions[$resolvedObjectType] -and $Script:ObjectTypeDefinitions[$resolvedObjectType].Summary) {
        $Script:ObjectTypeDefinitions[$resolvedObjectType].Summary
    } else {
        $null
    }

    # XSS Protection: Encode title for both display and data attribute
    $titleEscaped = ConvertTo-HtmlEncode $displayTitle
    $subtitleEscaped = if ($subtitle) { ConvertTo-HtmlEncode $subtitle } else { $null }
    $titleForAttr = ConvertTo-HtmlEncode $Title  # Keep original for data-check-title lookup
    $objectTypeAttr = if ($resolvedObjectType) { " data-object-type=`"$(ConvertTo-HtmlEncode $resolvedObjectType)`"" } else { "" }

    $helpButtonHtml = "<span class=`"check-help-btn`" data-check-title=`"$titleForAttr`"$objectTypeAttr title=`"Click for more info`">?</span>"

    # XSS Protection: Encode category for data attribute
    $categoryEncoded = ConvertTo-HtmlEncode $Category

    # Generate unique ID for this finding card (for expand/collapse all)
    $findingCardId = "fc-" + [System.Guid]::NewGuid().ToString('N').Substring(0, 8)

    # Add Expand/Collapse All button if there are objects
    $expandCollapseBtn = if ($objectCount -gt 1) {
        "<button class=`"expand-collapse-btn`" onclick=`"event.stopPropagation(); toggleAllObjects('$findingCardId')`" title=`"Expand/Collapse all objects`"><span>&#9654;</span> Expand All</button>"
    } else { "" }

    $cardIndexAttr = if ($CardIndex -ge 0) { " data-card-index=`"$CardIndex`"" } else { "" }
    [void]$card.AppendLine("        <div class=`"finding-card`" id=`"$findingCardId`" data-card-id=`"$findingCardId`" data-severity=`"$cardSeverity`" data-category=`"$categoryEncoded`"$cardIndexAttr>")
    [void]$card.AppendLine("            <div class=`"finding-header`" onclick=`"toggleFinding(this)`">")
    [void]$card.AppendLine("                <input type=`"checkbox`" class=`"finding-checkbox`" onclick=`"event.stopPropagation(); toggleCompleted('$findingCardId', this.checked)`" aria-label=`"Mark as completed`">")
    [void]$card.AppendLine("                <div class=`"finding-severity-bar $cardSeverity`"></div>")
    [void]$card.AppendLine("                <div class=`"finding-content`">")
    [void]$card.AppendLine("                    <div class=`"finding-title-wrapper`"><span class=`"finding-title`">$titleEscaped</span>$helpButtonHtml</div>")
    if ($subtitleEscaped) {
        [void]$card.AppendLine("                    <div class=`"finding-subtitle`">$subtitleEscaped</div>")
    }
    [void]$card.AppendLine("                </div>")
    [void]$card.AppendLine("                <div class=`"finding-meta`">")
    [void]$card.AppendLine("                    $expandCollapseBtn")
    [void]$card.AppendLine("                    $countHtml")
    [void]$card.AppendLine("                    <span class=`"finding-toggle`">&#9660;</span>")
    [void]$card.AppendLine("                </div>")
    [void]$card.AppendLine("            </div>")
    [void]$card.AppendLine("            <div class=`"finding-body`">")

    # Output each finding
    foreach ($finding in $Findings) {
        $severityClass = $finding.Severity.ToLower()

        if ($finding.Type -eq 'Object' -and $finding.Object) {
            # AD Object - full detail card using RenderModel
            # Use cached RenderModel from finding (built during console output) or create new
            $renderModel = if ($finding.RenderModel) { $finding.RenderModel }
                           else { Get-RenderModel -Object $finding.Object }
            $objectHtml = Build-ObjectDetailHtml -Object $finding.Object -Severity $finding.Severity -RenderModel $renderModel
            [void]$card.AppendLine($objectHtml)
        }
        elseif ($finding.Type -eq 'KeyValue' -and $finding.Key) {
            # Key-Value pair with optional tooltip for findings
            $keyHtml = ConvertTo-HtmlEncode $finding.Key
            $valueHtml = ConvertTo-HtmlEncode $finding.Value

            # Check for finding tooltip if this is a Finding or Hint severity
            $findingId = if ($severityClass -eq 'finding' -or $severityClass -eq 'hint') {
                Get-FindingIdForAttribute -Name $finding.Key -Value $finding.Value
            } else { $null }

            # Build value span - with data-finding-id on the value for consistent tooltip behavior
            $valueSpan = if ($findingId) {
                "<span class=`"finding-value`" data-finding-id=`"$findingId`">$valueHtml</span>"
            } else {
                "<span class=`"finding-value`">$valueHtml</span>"
            }

            [void]$card.AppendLine("                <div class=`"finding-item $severityClass`">")
            [void]$card.AppendLine("                    <span class=`"finding-key`">$keyHtml</span>")
            [void]$card.AppendLine("                    $valueSpan")
            [void]$card.AppendLine("                </div>")
        }
        elseif ($finding.Type -eq 'Line' -and $finding.Text) {
            # Single line text with optional tooltip via FindingId
            $textHtml = ConvertTo-HtmlEncode $finding.Text
            $dataAttr = if ($finding.FindingId) { " data-finding-id=`"$($finding.FindingId)`"" } else { "" }
            [void]$card.AppendLine("                <div class=`"finding-item finding-line $severityClass`"$dataAttr>$textHtml</div>")
        }
    }

    [void]$card.AppendLine("            </div>")
    [void]$card.AppendLine("        </div>")

    return $card.ToString()
}

<#
.SYNOPSIS
    Generates a meaningful title for an object card based on object type.
.DESCRIPTION
    Detects the object type and returns an appropriate, descriptive title
    for the collapsed card header. Uses same detection logic as
    Get-ObjectTypeForOrdering in adPEAS-AttributeOrder.ps1.
#>
<#
.SYNOPSIS
    Gets the display title for an object card in the HTML report.
.DESCRIPTION
    Wrapper around the central Get-ObjectTypeTitle function from adPEAS-ObjectTypes.ps1.
    Handles special cases that require object-specific property access.
#>
function Get-ObjectCardTitle {
    param($Object)

    # If no ObjectType set, return UNTAGGED indicator
    # Note: displayName comes before Name because GPOs have Name=GUID but displayName=readable name
    if (-not $Object._adPEASObjectType) {
        $objName = if ($Object.sAMAccountName) { $Object.sAMAccountName }
                   elseif ($Object.displayName) { $Object.displayName }
                   elseif ($Object.Name) { $Object.Name }
                   elseif ($Object.dNSHostName) { $Object.dNSHostName }
                   else { "Unknown" }
        return "[UNTAGGED] $objName"
    }

    $objectType = $Object._adPEASObjectType
    $context = $Object._adPEASContext

    # Helper to get account/object name
    # Note: displayName comes before Name because GPOs have Name=GUID but displayName=readable name
    $objName = if ($Object.sAMAccountName) { $Object.sAMAccountName -replace '\$$' }
               elseif ($Object.displayName) { $Object.displayName }
               elseif ($Object.Name) { $Object.Name }
               elseif ($Object.dNSHostName) { $Object.dNSHostName }
               else { "Object" }

    # Handle special cases that need object-specific property access
    # These cannot be expressed in the simple TitleFormat templates
    switch ($objectType) {
        'EntraConnect' {
            $tenant = if ($Object.entraM365Tenant) { " ($($Object.entraM365Tenant))" } else { "" }
            return "Entra ID Connect: $objName$tenant"
        }
        'Tier0Account' {
            # Only show context if it's not "Unprotected" (that's already clear from the header)
            if ($context -and $context -ne 'Unprotected') {
                return "Tier-0 Account: $objName ($context)"
            }
            return "Tier-0 Account: $objName"
        }
        'OperatorGroup' {
            $grpName = if ($Object.OperatorGroup) { $Object.OperatorGroup } else { $objName }
            return "Operator Group: $grpName"
        }
        'SIDHistory' {
            $ctxInfo = if ($context -eq 'Privileged') { " (Privileged!)" } else { "" }
            return "SID History: $objName$ctxInfo"
        }
        { $_ -in @('GPPCredential', 'SYSVOLCredential') } {
            $credType = if ($Object.credentialType) { $Object.credentialType } else { "Credential" }
            return "Credential ($credType)"
        }
        'LAPSConfiguration' {
            $ouName = if ($Object.ouName) { $Object.ouName } else { $objName }
            return "LAPS Config: $ouName"
        }
        'DomainBasicInfo' {
            $domainName = if ($Object.domainNameDNS) { $Object.domainNameDNS } else { "Domain" }
            return "Domain: $domainName"
        }
        'DomainControllers' {
            $dcList = if ($Object.domainControllers) { @($Object.domainControllers -split "`n") } else { @() }
            $dcCount = $dcList.Count
            return "Domain Controllers ($dcCount)"
        }
        'FineGrainedPasswordPolicy' {
            $psoName = if ($Object.psoName) { $Object.psoName } elseif ($Object.Name) { $Object.Name } else { "PSO" }
            return "Fine-Grained Policy: $psoName"
        }
        'DomainTrust' {
            $trustTarget = if ($Object.trustPartner) { $Object.trustPartner } else { $objName }
            return "Trust: $trustTarget"
        }
        'GPOLocalGroup' {
            $localGrp = if ($Object.TargetGroup) { $Object.TargetGroup } else { "Local Group" }
            $gpoName = if ($Object.GPOName) { " ($($Object.GPOName))" } else { "" }
            return "GPO Local Group: $localGrp$gpoName"
        }
        'GPOScheduledTask' {
            $taskName = if ($Object.taskName) { $Object.taskName } else { "Task" }
            return "Scheduled Task: $taskName"
        }
        'AddComputerRight' {
            $principal = if ($Object.accountName) { $Object.accountName } else { $objName }
            return "Add Computer Right: $principal"
        }
        default {
            # Use central Get-ObjectTypeTitle for all standard cases
            return Get-ObjectTypeTitle -Object $Object
        }
    }
}

<#
.SYNOPSIS
    Builds HTML for an object detail card.
.DESCRIPTION
    Creates object detail HTML with primary attributes visible and extended attributes
    in a collapsible section. Primary attributes are determined by object type to match
    the console output from Get-RenderModel.ps1.
#>
function Build-ObjectDetailHtml {
    param(
        $Object,
        [string]$Severity,
        $RenderModel = $null
    )

    $html = [System.Text.StringBuilder]::new()

    # Detect object type and generate meaningful title
    $objectName = Get-ObjectCardTitle -Object $Object

    # Generate unique ID for this object's extended section
    $objectId = [System.Guid]::NewGuid().ToString('N').Substring(0, 8)

    # Check if title contains DN path (separated by ||)
    $titleHtml = if ($objectName -match '^(.+?)\|\|(.+)$') {
        $mainTitle = ConvertTo-HtmlEncode $matches[1]
        $dnPath = ConvertTo-HtmlEncode $matches[2]
        "$mainTitle <span class=`"object-dn-path`">($dnPath)</span>"
    } else {
        ConvertTo-HtmlEncode $objectName
    }

    # Object cards are collapsed by default, click header to expand
    [void]$html.AppendLine("                <div class=`"object-detail`" id=`"obj-$objectId`">")
    [void]$html.AppendLine("                    <div class=`"object-header`" onclick=`"toggleObjectCard('$objectId')`">")
    [void]$html.AppendLine("                        <span>$titleHtml</span>")
    [void]$html.AppendLine("                        <span class=`"expand-icon`">&#9654;</span>")
    [void]$html.AppendLine("                    </div>")
    [void]$html.AppendLine("                    <div class=`"object-body`">")
    [void]$html.AppendLine("                        <div class=`"attr-col-resizer`" title=`"Drag to resize the name column`" aria-hidden=`"true`"></div>")

    # Use RenderModel if available, otherwise create one
    if (-not $RenderModel) {
        $RenderModel = Get-RenderModel -Object $Object
    }

    # Delegate to Render-HtmlObject (from Render-HtmlObject.ps1)
    $bodyHtml = Render-HtmlObject -Model $RenderModel -ObjectId $objectId -Severity $Severity
    [void]$html.Append($bodyHtml)

    [void]$html.AppendLine("                    </div>")
    [void]$html.AppendLine("                </div>")

    return $html.ToString()
}

# NOTE: Build-AttributeRowHtml and Get-AttributeValueClass have been removed.
# All HTML rendering is now handled by Render-HtmlObject.ps1 via the RenderModel pipeline.

# NOTE: Get-FindingIdForAttribute() is defined in adPEAS-FindingDefinitions.ps1
# It uses the centralized $Script:FindingTriggerIndex for attribute -> FindingId mapping.

<#
.SYNOPSIS
    Returns the HTML template with CSS and JavaScript.
.DESCRIPTION
    This function contains the embedded HTML report template.
    Templates are maintained in separate files (templates/) and embedded at build time.
#>
function Get-HTMLTemplate {
    return @'
<!DOCTYPE html>
<html lang="en" data-theme="{{DEFAULT_THEME}}">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>adPEAS Security Report - {{DOMAIN}}</title>
    <style>
:root {
            /* adPEAS severity colors: Finding (red), Hint (yellow), Note (green), Secure (teal) */
            --finding: #d32f2f;
            --finding-bg-light: #ffebee;
            --finding-bg-dark: #4a1a1a;
            --hint: #f57c00;
            --hint-bg-light: #fff3e0;
            --hint-bg-dark: #4a3010;
            --note: #388e3c;
            --note-bg-light: #e8f5e9;
            --note-bg-dark: #1a3a1a;
            --secure: #2196f3;
            --secure-bg-light: #e3f2fd;
            --secure-bg-dark: #1a2a4a;
            --transition: 0.2s ease;
        }

        /* LIGHT MODE: Option B - Cool Professional (Corporate Clean) */
        [data-theme="light"] {
            --bg-main: #e2e8f0;           /* Kühles Grau - mehr Kontrast */
            --bg-card: #ffffff;
            --bg-sidebar: #edf2f7;         /* Hellgrau-Blau */
            --bg-header: #1a365d;          /* Navy */
            --bg-input: #edf2f7;
            --bg-hover: #e2e8f0;
            --bg-object-header: #2b6cb0;   /* Mittelblau statt Dunkelblau */
            --bg-object-header-hover: #3182ce;
            --border: #cbd5e0;             /* Deutlichere Borders */
            --text: #1a202c;
            --text-muted: #4a5568;
            --text-header: #ffffff;
            --text-inverse: #ffffff;
            --shadow: rgba(0,0,0,0.08);
            --finding-bg: var(--finding-bg-light);
            --hint-bg: var(--hint-bg-light);
            --note-bg: var(--note-bg-light);
            --secure-bg: var(--secure-bg-light);
            --accent: #2b6cb0;             /* Corporate Blue */
            --toggle-sun: #ecc94b;         /* Gedämpftes Gold für Toggle */
        }

        [data-theme="dark"] {
            --bg-main: #0d1117;
            --bg-card: #161b22;
            --bg-sidebar: #161b22;
            --bg-header: #21262d;
            --bg-input: #21262d;
            --bg-hover: #21262d;
            --bg-object-header: #30363d;
            --bg-object-header-hover: #3d444d;
            --border: #30363d;
            --text: #e6edf3;
            --text-muted: #8b949e;
            --text-header: #e6edf3;
            --text-inverse: #e6edf3;
            --shadow: rgba(0,0,0,0.3);
            --finding-bg: var(--finding-bg-dark);
            --hint-bg: var(--hint-bg-dark);
            --note-bg: var(--note-bg-dark);
            --secure-bg: var(--secure-bg-dark);
            --accent: #58a6ff;
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
            font-size: 14px;
            line-height: 1.6;
            color: var(--text);
            background: var(--bg-main);
            transition: background var(--transition), color var(--transition);
        }

        .header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 64px;
            background: var(--bg-header);
            color: var(--text-header);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 24px;
            z-index: 100;
            box-shadow: 0 2px 8px var(--shadow);
        }

        .header-brand {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .header-logo {
            height: 68px;
            width: auto;
        }

        .header-title {
            font-size: 28px;
            font-weight: 700;
            letter-spacing: 1px;
        }

        .header-disclaimer {
            flex: 1;
            text-align: center;
            font-size: 13px;
            color: rgba(255,255,255,0.75);
            padding: 0 20px;
            line-height: 1.5;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        /* Theme Toggle Switch - Modern Sliding Design */
        .theme-toggle {
            position: relative;
            display: flex;
            align-items: center;
            width: 64px;
            height: 32px;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            border-radius: 16px;
            cursor: pointer;
            border: 2px solid rgba(255,255,255,0.15);
            box-shadow: inset 0 2px 4px rgba(0,0,0,0.3), 0 1px 2px rgba(255,255,255,0.1);
            transition: all 0.4s ease;
            overflow: hidden;
        }

        .theme-toggle::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(135deg, #90cdf4 0%, #ecc94b 100%);
            opacity: 0;
            transition: opacity 0.4s ease;
            border-radius: 14px;
        }

        .theme-toggle:hover {
            border-color: rgba(255,255,255,0.3);
            box-shadow: inset 0 2px 4px rgba(0,0,0,0.3), 0 0 8px rgba(255,255,255,0.2);
        }

        .theme-toggle-slider {
            position: absolute;
            top: 3px;
            left: 3px;
            width: 22px;
            height: 22px;
            background: linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%);
            border-radius: 50%;
            transition: all 0.4s cubic-bezier(0.68, -0.15, 0.32, 1.15);
            box-shadow: 0 2px 6px rgba(0,0,0,0.3);
            z-index: 2;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .theme-toggle-slider::before {
            content: '☀';
            font-size: 13px;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .theme-toggle-slider::after {
            content: '☽';
            font-size: 13px;
            position: absolute;
            transition: opacity 0.3s ease;
        }

        /* Stars in dark mode background */
        .theme-toggle-stars {
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            z-index: 1;
            transition: opacity 0.4s ease;
        }

        .theme-toggle-stars::before,
        .theme-toggle-stars::after {
            content: '✦';
            position: absolute;
            color: rgba(255,255,255,0.7);
            font-size: 6px;
            transition: all 0.4s ease;
        }

        .theme-toggle-stars::before {
            top: 6px;
            right: 10px;
        }

        .theme-toggle-stars::after {
            content: '✧';
            bottom: 8px;
            right: 18px;
            font-size: 5px;
        }

        /* Light mode active state */
        [data-theme="light"] .theme-toggle::before {
            opacity: 1;
        }

        [data-theme="light"] .theme-toggle {
            border-color: rgba(0,0,0,0.1);
        }

        [data-theme="light"] .theme-toggle-slider {
            left: calc(100% - 25px);
            background: linear-gradient(135deg, #fefcbf 0%, var(--toggle-sun, #ecc94b) 100%);
            box-shadow: 0 0 8px rgba(236,201,75,0.6), 0 2px 6px rgba(0,0,0,0.2);
        }

        [data-theme="light"] .theme-toggle-slider::before {
            opacity: 1;
        }

        [data-theme="light"] .theme-toggle-slider::after {
            opacity: 0;
        }

        [data-theme="light"] .theme-toggle-stars {
            opacity: 0;
        }

        /* Hover animation on slider */
        .theme-toggle:hover .theme-toggle-slider {
            transform: scale(1.05);
        }

        /* Hide old text labels */
        .theme-toggle #themeIcon,
        .theme-toggle #themeLabel {
            display: none;
        }

        .btn {
            padding: 8px 16px;
            border: none;
            border-radius: 6px;
            font-size: 13px;
            cursor: pointer;
            background: transparent;
            color: var(--text-header);
            border: 1px solid rgba(255,255,255,0.3);
        }

        .btn:hover {
            background: rgba(255,255,255,0.1);
        }

        .sidebar {
            position: fixed;
            top: 64px;
            left: 0;
            bottom: 0;
            width: 280px;
            background: var(--bg-sidebar);
            border-right: 1px solid var(--border);
            overflow-y: auto;
            z-index: 50;
        }

        .sidebar-section {
            padding: 16px 0;
            border-bottom: 1px solid var(--border);
        }

        .sidebar-title {
            padding: 0 20px;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--text-muted);
            margin-bottom: 8px;
        }

        .sidebar-search {
            padding: 0 16px;
            margin-bottom: 12px;
        }

        .sidebar-search input {
            width: 100%;
            padding: 10px 12px;
            border: 1px solid var(--border);
            border-radius: 8px;
            font-size: 13px;
            background: var(--bg-input);
            color: var(--text);
        }

        .sidebar-search input:focus {
            outline: none;
            border-color: var(--accent);
        }

        .nav-item {
            display: flex;
            align-items: center;
            padding: 10px 20px;
            color: var(--text);
            text-decoration: none;
            cursor: pointer;
        }

        .nav-item:hover {
            background: var(--bg-hover);
        }

        .nav-item .count {
            margin-left: auto;
            padding: 3px 10px;
            border-radius: 12px;
            font-size: 12px;
            font-weight: 600;
            background: var(--bg-main);
        }

        .nav-item.finding .count { background: var(--finding-bg); color: var(--finding); }
        .nav-item.hint .count { background: var(--hint-bg); color: var(--hint); }
        .nav-item.note .count { background: var(--note-bg); color: var(--note); }
        .nav-item.secure .count { background: var(--secure-bg); color: var(--secure); }

        .nav-item.severity-filter.active {
            background: var(--accent);
            color: var(--text-inverse);
            font-weight: 600;
        }

        .nav-item.severity-filter.active .count {
            background: rgba(255,255,255,0.2);
            color: var(--text-inverse);
        }

        .nav-item.category-filter.active {
            background: var(--accent);
            color: var(--text-inverse);
            font-weight: 600;
        }

        .nav-item.category-filter.active .count {
            background: rgba(255,255,255,0.2);
            color: var(--text-inverse);
        }

        .nav-item.category-filter.category-highlight {
            border-left: 3px solid var(--accent);
            background: var(--hover);
            font-weight: 600;
            padding-left: 13px;
        }

        .main {
            margin-left: 280px;
            margin-top: 64px;
            padding: 24px;
            min-height: calc(100vh - 64px);
        }

        .summary-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 16px;
            margin-bottom: 24px;
        }

        .summary-card {
            background: var(--bg-card);
            border-radius: 12px;
            padding: 20px;
            border: 1px solid var(--border);
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .summary-card .icon {
            width: 52px;
            height: 52px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 22px;
            font-weight: bold;
        }

        .summary-card.finding .icon { background: var(--finding-bg); color: var(--finding); }
        .summary-card.hint .icon { background: var(--hint-bg); color: var(--hint); }
        .summary-card.note .icon { background: var(--note-bg); color: var(--note); }
        .summary-card.secure .icon { background: var(--secure-bg); color: var(--secure); }

        .summary-card .value {
            font-size: 32px;
            font-weight: 700;
            line-height: 1;
        }

        .summary-card.finding .value { color: var(--finding); }
        .summary-card.hint .value { color: var(--hint); }
        .summary-card.note .value { color: var(--note); }
        .summary-card.secure .value { color: var(--secure); }

        .summary-card .label {
            font-size: 13px;
            color: var(--text-muted);
            margin-top: 4px;
        }

        .info-bar {
            display: flex;
            gap: 24px;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 16px 24px;
            margin-bottom: 24px;
        }

        /* Top Priority Actions Section */
        .top-actions {
            background: linear-gradient(135deg, var(--finding-bg) 0%, var(--bg-card) 100%);
            border: 2px solid var(--finding);
            border-radius: 12px;
            padding: 20px 24px;
            margin-bottom: 24px;
        }

        .top-actions.collapsed .top-actions-list {
            display: none;
        }

        .top-actions.collapsed .top-actions-header {
            margin-bottom: 0;
        }

        .top-actions-toggle {
            background: none;
            border: 1px solid var(--border);
            color: var(--text-muted);
            cursor: pointer;
            padding: 4px 10px;
            border-radius: 4px;
            font-size: 12px;
            transition: all 0.2s ease;
        }

        .top-actions-toggle:hover {
            background: var(--bg-hover);
            color: var(--text);
        }

        .top-actions-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 16px;
        }

        .top-actions-title {
            font-size: 18px;
            font-weight: 700;
            color: var(--finding);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .top-actions-title .icon {
            font-size: 24px;
        }

        .top-actions-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .top-action-item {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: 14px 18px;
            display: flex;
            align-items: flex-start;
            gap: 14px;
        }

        .top-action-rank {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            background: var(--finding);
            color: white;
            font-weight: 700;
            font-size: 14px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .top-action-content {
            flex: 1;
            min-width: 0;
        }

        .top-action-title {
            font-weight: 600;
            font-size: 14px;
            color: var(--text);
            margin-bottom: 2px;
        }

        .top-action-meta {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 12px;
            color: var(--text-muted);
            margin-bottom: 6px;
        }

        .top-action-count {
            font-weight: 600;
        }

        .top-action-count::after {
            content: '|';
            margin-left: 8px;
            color: var(--border);
        }

        .top-action-section {
            text-transform: uppercase;
            letter-spacing: 0.5px;
            font-size: 11px;
        }

        .top-action-details {
            font-size: 13px;
            color: var(--text-muted);
            margin-bottom: 4px;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
            line-height: 1.4;
        }

        .top-action-fix {
            font-size: 12px;
            color: var(--accent);
            font-style: italic;
        }

        .top-action-score {
            font-size: 11px;
            font-weight: 600;
            color: white;
            padding: 4px 10px;
            border-radius: 4px;
            white-space: nowrap;
            min-width: 32px;
            text-align: center;
        }

        .top-action-score.score-critical {
            background: var(--finding);
        }

        .top-action-score.score-high {
            background: #e67e22;
        }

        .top-action-score.score-medium {
            background: var(--hint);
            color: #1a1a2e;
        }

        .top-action-score.score-low {
            background: var(--note);
            color: #1a1a2e;
        }

        .top-action-score.score-info {
            background: #6b7280;
            color: #ffffff;
        }

        .top-action-buttons {
            display: flex;
            gap: 8px;
            align-items: center;
            flex-shrink: 0;
        }

        .top-action-info-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 24px;
            height: 24px;
            background: var(--bg-hover);
            color: var(--text-muted);
            border: 1px solid var(--border);
            border-radius: 50%;
            font-size: 12px;
            font-weight: bold;
            cursor: help;
            transition: all 0.2s ease;
            flex-shrink: 0;
            align-self: center;
        }

        .top-action-info-btn:hover {
            background: var(--accent);
            border-color: var(--accent);
            color: white;
        }

        /* Top Action Info Tooltip */
        .top-action-tooltip-content {
            max-width: 400px;
        }

        .top-action-tooltip-header {
            font-weight: 600;
            font-size: 14px;
            color: var(--finding);
            margin-bottom: 12px;
            padding-bottom: 8px;
            border-bottom: 1px solid var(--border);
        }

        .top-action-tooltip-section {
            margin-bottom: 12px;
        }

        .top-action-tooltip-section:last-child {
            margin-bottom: 0;
        }

        .top-action-tooltip-label {
            font-size: 11px;
            font-weight: 600;
            color: var(--accent);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 4px;
        }

        .top-action-tooltip-text {
            font-size: 13px;
            color: var(--text);
            line-height: 1.5;
        }

        .top-action-tooltip-list {
            margin: 0;
            padding-left: 20px;
            font-size: 13px;
            color: var(--text);
            line-height: 1.6;
        }

        .top-action-tooltip-list li {
            margin-bottom: 4px;
        }

        .top-action-tooltip-note {
            background: var(--bg-hover);
            padding: 8px 10px;
            border-radius: 4px;
            border-left: 3px solid var(--hint);
        }

        .top-action-tooltip-note .top-action-tooltip-label {
            color: var(--hint);
        }

        .no-critical-actions {
            text-align: center;
            padding: 20px;
            color: var(--note);
            font-size: 14px;
        }

        /* Remediation Floating Tooltip */
        .remediation-floating-tooltip {
            position: absolute;
            z-index: 10000;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: 16px;
            box-shadow: 0 8px 24px rgba(0,0,0,0.3);
            max-width: 500px;
            min-width: 300px;
        }

        .remediation-tooltip-header {
            font-weight: 700;
            font-size: 14px;
            color: var(--accent);
            margin-bottom: 8px;
        }

        .remediation-tooltip-title {
            font-size: 13px;
            color: var(--text-muted);
            margin-bottom: 12px;
            padding-bottom: 8px;
            border-bottom: 1px solid var(--border);
        }

        .remediation-cmd {
            display: flex;
            flex-direction: column;
            gap: 6px;
            margin-bottom: 12px;
            padding-bottom: 10px;
            border-bottom: 1px solid var(--border);
        }

        .remediation-cmd:last-child {
            border-bottom: none;
            margin-bottom: 0;
            padding-bottom: 0;
        }

        .remediation-cmd-desc {
            font-size: 12px;
            color: var(--text-muted);
            font-weight: 500;
        }

        .remediation-cmd-row {
            display: flex;
            align-items: flex-start;
            gap: 8px;
        }

        .remediation-cmd code,
        .remediation-cmd-row code {
            flex: 1;
            background: var(--bg-hover);
            padding: 8px 10px;
            border-radius: 4px;
            font-family: 'Consolas', 'Monaco', monospace;
            font-size: 11px;
            color: var(--text);
            word-break: break-all;
        }

        .remediation-cmd .copy-btn {
            padding: 6px 10px;
            background: var(--accent);
            color: white;
            border: none;
            border-radius: 4px;
            font-size: 11px;
            cursor: pointer;
            flex-shrink: 0;
        }

        .remediation-cmd .copy-btn:hover {
            background: var(--accent-hover);
        }

        /* Card Controls (Expand/Collapse All) */
        .card-controls {
            display: flex;
            gap: 8px;
        }

        .card-control-btn {
            padding: 6px 12px;
            border: 1px solid var(--border);
            background: var(--bg-card);
            color: var(--text-muted);
            font-size: 12px;
            font-weight: 500;
            cursor: pointer;
            border-radius: 6px;
            transition: all 0.2s ease;
        }

        .card-control-btn:hover {
            background: var(--bg-hover);
            color: var(--text);
            border-color: var(--accent);
        }

        /* Copy Button for Remediation */
        .copy-btn {
            display: inline-flex;
            align-items: center;
            gap: 4px;
            padding: 4px 8px;
            background: var(--bg-hover);
            border: 1px solid var(--border);
            border-radius: 4px;
            cursor: pointer;
            font-size: 11px;
            color: var(--text-muted);
            transition: all 0.2s ease;
        }

        .copy-btn:hover {
            background: var(--accent);
            color: white;
            border-color: var(--accent);
        }

        .copy-btn.copied {
            background: var(--note);
            color: white;
            border-color: var(--note);
        }

        .remediation-code {
            background: var(--bg-main);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: 10px 12px;
            margin: 8px 0;
            font-family: 'Cascadia Code', Consolas, monospace;
            font-size: 12px;
            position: relative;
            overflow-x: auto;
        }

        .remediation-code .copy-btn {
            position: absolute;
            top: 6px;
            right: 6px;
        }

        .remediation-code pre {
            margin: 0;
            white-space: pre-wrap;
            word-break: break-all;
        }

        /* Score Badges (solid colors, matching Top Priority Action style) */
        .score-badge {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 2px 8px;
            border-radius: 4px;
            font-size: 11px;
            font-weight: 600;
            cursor: pointer;
            min-width: 28px;
            color: white;
        }
        .score-badge.score-critical { background: var(--finding); }
        .score-badge.score-high { background: #e67e22; }
        .score-badge.score-medium { background: var(--hint); color: #1a1a2e; }
        .score-badge.score-low { background: var(--note); color: #1a1a2e; }
        .score-badge.score-info { background: #6b7280; }


        /* Remediation Commands in Tooltip */
        .remediation-disclaimer {
            background: rgba(255, 193, 7, 0.15);
            border: 1px solid rgba(255, 193, 7, 0.3);
            border-radius: 6px;
            padding: 8px 10px;
            margin-bottom: 12px;
            font-size: 11px;
            color: var(--hint);
            line-height: 1.4;
        }
        .remediation-command {
            margin-bottom: 12px;
        }
        .remediation-command:last-child {
            margin-bottom: 0;
        }
        .remediation-command-desc {
            font-size: 12px;
            color: var(--text-muted);
            margin-bottom: 6px;
        }
        .tooltip-section-content .remediation-code {
            background: var(--bg-main);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: 8px 10px;
            padding-right: 60px;
            position: relative;
            font-family: 'Cascadia Code', Consolas, monospace;
            font-size: 11px;
        }
        .tooltip-section-content .remediation-code pre {
            margin: 0;
            white-space: pre-wrap;
            word-break: break-all;
            color: var(--text);
        }
        .tooltip-section-content .remediation-code .copy-btn {
            position: absolute;
            top: 4px;
            right: 4px;
            padding: 3px 8px;
            font-size: 10px;
        }

        .info-item .label {
            font-size: 11px;
            text-transform: uppercase;
            color: var(--text-muted);
            margin-bottom: 4px;
        }

        .info-item .value {
            font-size: 14px;
            font-weight: 600;
        }

        .section {
            background: var(--bg-card);
            border-radius: 12px;
            border: 1px solid var(--border);
            margin-bottom: 20px;
            overflow: hidden;
        }

        .section-header {
            padding: 16px 20px;
            border-bottom: 1px solid var(--border);
            background: var(--bg-hover);
        }

        .section-title {
            font-size: 16px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .section-badge {
            padding: 4px 12px;
            border-radius: 6px;
            font-size: 12px;
            font-weight: 600;
            color: white;
        }

        .section-badge.finding { background: var(--finding); }
        .section-badge.hint { background: var(--hint); }
        .section-badge.note { background: var(--note); }
        .section-badge.secure { background: var(--secure); }

        .section-content {
            padding: 20px;
        }

        /* ============================================
           Finding Card: Mockup A - Left-Aligned Scannable
           ============================================ */
        .finding-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            margin-bottom: 10px;
            overflow: hidden;
            transition: background 0.2s ease, opacity 0.2s ease;
            scroll-margin-top: 80px; /* Account for fixed header (64px) + padding */
        }

        .finding-card:hover {
            background: var(--bg-hover);
        }

        /* Completed finding styling */
        .finding-card.completed {
            opacity: 0.5;
        }

        .finding-card.completed .finding-title {
            text-decoration: line-through;
        }

        .finding-header {
            display: flex;
            align-items: center;
            padding: 14px 16px;
            gap: 12px;
            cursor: pointer;
        }

        .finding-checkbox {
            width: 18px;
            height: 18px;
            cursor: pointer;
            accent-color: var(--accent);
            flex-shrink: 0;
        }

        /* Severity indicator bar */
        .finding-severity-bar {
            width: 6px;
            height: 32px;
            border-radius: 3px;
            flex-shrink: 0;
        }

        .finding-severity-bar.finding { background: var(--finding); }
        .finding-severity-bar.hint { background: var(--hint); }
        .finding-severity-bar.note { background: var(--note); }
        .finding-severity-bar.secure { background: var(--secure); }

        /* Content area with title and optional subtitle */
        .finding-content {
            flex: 1;
            min-width: 0;
        }

        .finding-title-wrapper {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .finding-title {
            font-weight: 500;
            font-size: 14px;
        }

        /* Help button - visible only on hover in finding cards */
        .finding-card .check-help-btn {
            opacity: 0;
        }

        .finding-card:hover .check-help-btn {
            opacity: 1;
        }

        /* Subtitle (optional context info) */
        .finding-subtitle {
            font-size: 12px;
            color: var(--text-muted);
            margin-top: 2px;
        }

        /* Actions area (count, expand button, chevron) */
        .finding-meta {
            display: flex;
            align-items: center;
            gap: 12px;
            flex-shrink: 0;
        }

        .finding-count {
            font-size: 13px;
            color: var(--text-muted);
        }

        .expand-collapse-btn {
            font-size: 12px;
            color: var(--text-muted);
            background: transparent;
            border: 1px solid var(--border);
            padding: 4px 10px;
            border-radius: 4px;
            cursor: pointer;
            transition: all 0.15s ease;
            display: flex;
            align-items: center;
            gap: 4px;
            opacity: 0;
        }

        .finding-card:hover .expand-collapse-btn {
            opacity: 1;
        }

        .expand-collapse-btn:hover {
            background: var(--bg-card);
            color: var(--text);
            border-color: var(--accent);
        }

        .expand-collapse-btn span {
            font-size: 9px;
            transition: transform 0.2s ease;
        }

        .finding-toggle {
            color: var(--text-muted);
            font-size: 18px;
            transition: transform var(--transition);
        }

        .finding-card.expanded .finding-toggle {
            transform: rotate(180deg);
        }

        .finding-body {
            display: none;
            padding: 18px;
            background: var(--bg-main);
            border-top: 1px solid var(--border);
        }

        .finding-card.expanded .finding-body {
            display: block;
        }

        .finding-item {
            display: flex;
            padding: 10px 14px;
            border-bottom: 1px solid var(--border);
            font-size: 13px;
        }

        .finding-item:last-child {
            border-bottom: none;
        }

        .finding-item.finding-line {
            display: block;
        }

        .finding-key {
            min-width: 280px;
            color: var(--text-muted);
            font-weight: 500;
        }

        .finding-value {
            flex: 1;
            font-family: 'Cascadia Code', Consolas, monospace;
            font-size: 12px;
            color: var(--text);
        }

        /* Severity classes for KeyValue items - color BOTH key AND value for security-relevant findings */
        /* Note and Standard stay neutral (no coloring) */
        .finding-item.finding .finding-key { color: var(--finding); font-weight: 600; }
        .finding-item.finding .finding-value { color: var(--finding); }
        .finding-item.hint .finding-key { color: var(--hint); }
        .finding-item.hint .finding-value { color: var(--hint); }
        .finding-item.secure .finding-key { color: var(--secure); }
        .finding-item.secure .finding-value { color: var(--secure); }
        /* .finding-item.note - intentionally NOT colored (stays neutral) */

        /* Severity classes for single-line findings (finding-line) - color the entire line */
        .finding-item.finding-line.finding { color: var(--finding); font-weight: 600; }
        .finding-item.finding-line.hint { color: var(--hint); }
        .finding-item.finding-line.note { color: var(--note); }
        .finding-item.finding-line.secure { color: var(--secure); }
        .finding-item.finding-line.info { color: var(--text-muted); }

        .object-detail {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            margin-bottom: 12px;
            overflow: hidden;
        }

        .object-header {
            padding: 12px 18px;
            background: var(--bg-object-header);
            color: var(--text-inverse);
            font-weight: 600;
            font-size: 13px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: space-between;
            transition: background 0.15s ease;
        }

        .object-header:hover {
            background: var(--bg-object-header-hover, #4a4a4a);
        }

        .object-header .expand-icon {
            font-size: 10px;
            transition: transform 0.2s ease;
            margin-left: 12px;
            opacity: 0.7;
        }

        .object-detail.expanded .object-header .expand-icon {
            transform: rotate(90deg);
        }

        .object-dn-path {
            font-weight: 400;
            font-size: 11px;
            opacity: 0.7;
            margin-left: 6px;
        }

        .object-body {
            display: none;
        }

        .object-detail.expanded .object-body {
            display: block;
            position: relative;
        }

        /* Excel-like per-card column resizer (not persisted, resets on reload) */
        .attr-col-resizer {
            position: absolute;
            top: 0;
            bottom: 0;
            left: var(--attr-name-w, 280px);
            width: 9px;
            transform: translateX(-50%);
            cursor: col-resize;
            z-index: 2;
            opacity: 0;
            transition: opacity 0.15s ease;
        }

        .attr-col-resizer::before {
            content: "";
            position: absolute;
            top: 0;
            bottom: 0;
            left: 50%;
            width: 2px;
            transform: translateX(-50%);
            background: var(--accent);
        }

        .object-body:hover .attr-col-resizer {
            opacity: 0.35;
        }

        .attr-col-resizer:hover,
        .attr-col-resizer.resizing {
            opacity: 1;
        }

        body.col-resizing {
            cursor: col-resize;
            user-select: none;
        }

        .attr-row {
            display: flex;
            border-bottom: 1px solid var(--border);
            font-size: 13px;
        }

        .attr-row:last-child {
            border-bottom: none;
        }

        .attr-name {
            width: var(--attr-name-w, 280px);
            padding: 10px 18px 10px 20px;
            background: var(--bg-hover);
            font-weight: 500;
            color: var(--text-muted);
            flex-shrink: 0;
            border-right: 1px solid var(--border);
            word-break: break-word;
        }

        .attr-value {
            flex: 1;
            padding: 10px 18px;
            word-break: break-all;
            font-family: 'Cascadia Code', Consolas, monospace;
            font-size: 12px;
            color: var(--text);
        }

        .attr-value.finding { color: var(--finding); font-weight: 600; }
        .attr-value.hint { color: var(--hint); font-weight: 600; }
        .attr-value.note { color: var(--note); }
        .attr-value.secure { color: var(--secure); }

        /* Generic severity classes for inline elements (e.g., UAC flags) */
        span.finding { color: var(--finding); font-weight: 600; }
        span.hint { color: var(--hint); }
        span.secure { color: var(--secure); }

        /* Extended attributes toggle */
        .extended-attrs-toggle {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 10px 18px;
            background: var(--bg-hover);
            border-top: 1px solid var(--border);
            cursor: pointer;
            font-size: 12px;
            color: var(--text-muted);
            transition: background 0.2s;
        }

        .extended-attrs-toggle:hover {
            background: var(--bg-card);
            color: var(--text);
        }

        .extended-attrs-toggle .toggle-icon {
            font-size: 10px;
            transition: transform 0.2s;
        }

        .extended-attrs-toggle.expanded .toggle-icon {
            transform: rotate(90deg);
        }

        .extended-attrs {
            border-top: 1px solid var(--border);
            background: var(--bg-hover);
        }

        .extended-attrs .attr-row {
            opacity: 0.85;
        }

        .extended-attrs .attr-name {
            background: transparent;
        }

        /* Drag & Drop attribute reordering (handle-only, so row text stays selectable) */
        .attr-row {
            transition: opacity 0.2s, box-shadow 0.2s;
            position: relative;
        }

        /* Overlay: sits on top of the (grey) attr-name column, takes no layout
           width, so colours match and no white gutter / no layout shift. */
        .attr-drag-handle {
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 18px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--text-muted);
            font-size: 12px;
            line-height: 1;
            cursor: grab;
            opacity: 0;
            user-select: none;
            transition: opacity 0.15s ease;
            z-index: 1;
        }

        .attr-row:hover .attr-drag-handle {
            opacity: 0.55;
        }

        .attr-drag-handle:hover {
            opacity: 1;
        }

        .attr-drag-handle:active {
            cursor: grabbing;
        }

        .attr-row.dragging {
            opacity: 0.5;
        }

        .attr-row.drag-over {
            border-top: 2px solid var(--accent);
        }

        /* Keyboard shortcut help modal */
        .shortcut-help {
            display: none;
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 0;
            z-index: 1100;
            box-shadow: 0 8px 32px rgba(0,0,0,0.3);
            max-width: 700px;
            width: 90%;
            max-height: 85vh;
            overflow: hidden;
            flex-direction: column;
        }

        .shortcut-help.visible {
            display: flex;
        }

        .shortcut-help-backdrop {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0,0,0,0.5);
            z-index: 1099;
        }

        .shortcut-help-backdrop.visible {
            display: block;
        }

        .help-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 16px 24px;
            border-bottom: 1px solid var(--border);
            background: var(--bg-secondary);
        }

        .help-header h2 {
            margin: 0;
            font-size: 18px;
            color: var(--text);
        }

        .help-close-btn {
            background: none;
            border: none;
            font-size: 24px;
            color: var(--text-muted);
            cursor: pointer;
            padding: 0;
            line-height: 1;
        }

        .help-close-btn:hover {
            color: var(--text);
        }

        .help-content {
            padding: 24px;
            overflow-y: auto;
            flex: 1;
        }

        .help-section {
            margin-bottom: 24px;
        }

        .help-section:last-child {
            margin-bottom: 0;
        }

        .help-section h3 {
            margin: 0 0 12px 0;
            font-size: 14px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--primary);
            border-bottom: 1px solid var(--border);
            padding-bottom: 8px;
        }

        .help-section p {
            margin: 0 0 12px 0;
            color: var(--text-muted);
            font-size: 13px;
            line-height: 1.6;
        }

        .help-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
        }

        @media (max-width: 600px) {
            .help-grid {
                grid-template-columns: 1fr;
            }
        }

        .help-card {
            background: var(--bg-secondary);
            border-radius: 8px;
            padding: 12px;
            border: 1px solid var(--border);
        }

        .help-card-title {
            font-weight: 600;
            font-size: 13px;
            color: var(--text);
            margin-bottom: 6px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .help-card-desc {
            font-size: 12px;
            color: var(--text-muted);
            line-height: 1.5;
        }

        .severity-sample {
            display: inline-block;
            width: 12px;
            height: 12px;
            border-radius: 3px;
        }

        .severity-sample.finding { background: var(--severity-critical); }
        .severity-sample.hint { background: var(--severity-warning); }
        .severity-sample.note { background: var(--severity-info); }
        .severity-sample.secure { background: var(--severity-good); }

        .shortcut-help h3 {
            margin-bottom: 16px;
            font-size: 18px;
            color: var(--text);
        }

        .shortcut-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 8px;
        }

        @media (max-width: 500px) {
            .shortcut-grid {
                grid-template-columns: 1fr;
            }
        }

        .shortcut-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 6px 10px;
            background: var(--bg-secondary);
            border-radius: 6px;
        }

        .shortcut-key {
            background: var(--bg-hover);
            padding: 4px 10px;
            border-radius: 4px;
            font-family: 'Cascadia Code', Consolas, monospace;
            font-size: 11px;
            color: var(--text);
            border: 1px solid var(--border);
            white-space: nowrap;
        }

        .shortcut-desc {
            color: var(--text-muted);
            font-size: 12px;
            text-align: right;
        }

        /* Data Management Section in Help Modal */
        .data-management-section {
            border-top: 2px solid var(--border);
            padding-top: 20px;
            margin-top: 8px;
        }

        .data-storage-info {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 8px;
            margin-bottom: 12px;
        }

        @media (max-width: 500px) {
            .data-storage-info {
                grid-template-columns: 1fr;
            }
        }

        .data-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 12px;
            color: var(--text);
            padding: 6px 10px;
            background: var(--bg-secondary);
            border-radius: 6px;
            border: 1px solid var(--border);
        }

        .data-icon {
            font-size: 14px;
            opacity: 0.7;
        }

        .clear-data-btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 10px 16px;
            background: transparent;
            border: 1px solid var(--finding);
            border-radius: 6px;
            color: var(--finding);
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .clear-data-btn:hover {
            background: var(--finding);
            color: white;
        }

        .clear-data-btn:active {
            transform: scale(0.98);
        }

        .clear-data-icon {
            font-size: 16px;
        }

        .hide-completed-toggle {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 12px;
            color: var(--text-muted);
            cursor: pointer;
            padding: 4px 8px;
            border-radius: 4px;
        }

        .hide-completed-toggle:hover {
            background: var(--bg-card);
        }

        .hide-completed-toggle input {
            accent-color: var(--accent);
        }

        /* Hide completed findings when toggle is active */
        body.hide-completed .finding-card.completed {
            display: none !important;
        }

        /* Focused finding highlight for keyboard navigation and table dblclick */
        .finding-card.keyboard-focused {
            outline: 3px solid var(--accent);
            outline-offset: 2px;
            box-shadow: 0 0 12px rgba(59, 130, 246, 0.5);
        }

        /* ============================================================
           ACCESSIBILITY STYLES
           ============================================================ */

        /* Visually hidden but accessible to screen readers */
        .visually-hidden {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border: 0;
        }

        /* Skip links - visible only on focus for keyboard navigation */
        .skip-link {
            position: absolute;
            top: -40px;
            left: 0;
            background: var(--accent);
            color: white;
            padding: 8px 16px;
            text-decoration: none;
            font-weight: 600;
            z-index: 10000;
            border-radius: 0 0 4px 0;
            transition: top 0.2s ease;
        }

        .skip-link:focus {
            top: 0;
            outline: 2px solid var(--text);
            outline-offset: 2px;
        }

        /* Focus visible styles for better keyboard navigation */
        :focus-visible {
            outline: 2px solid var(--accent);
            outline-offset: 2px;
        }

        /* Remove default focus for mouse users */
        :focus:not(:focus-visible) {
            outline: none;
        }

        /* Ensure buttons maintain focus styles */
        button:focus-visible,
        .btn:focus-visible,
        .card-control-btn:focus-visible {
            outline: 2px solid var(--accent);
            outline-offset: 2px;
            box-shadow: 0 0 0 4px rgba(74, 144, 226, 0.25);
        }


        /* Summary card focus styles (now buttons) */
        .summary-card:focus-visible {
            outline: 2px solid var(--accent);
            outline-offset: 2px;
            transform: translateY(-2px);
        }

        /* Nav item focus styles */
        .nav-item:focus-visible {
            outline: 2px solid var(--accent);
            outline-offset: 2px;
            background: var(--bg-hover);
        }

        /* Reduced motion preference */
        @media (prefers-reduced-motion: reduce) {
            *,
            *::before,
            *::after {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
                scroll-behavior: auto !important;
            }

            .skip-link {
                transition: none;
            }
        }

        /* High contrast mode support */
        @media (prefers-contrast: high) {
            .severity-badge,
            .score-badge {
                border: 2px solid currentColor;
            }

            .finding-card {
                border-width: 2px;
            }

            .btn,
            .card-control-btn {
                border: 2px solid currentColor;
            }
        }

        /* ============================================================
           PRINT STYLES - Professional PDF Output
           ============================================================ */

        /* Print header - hidden on screen, visible only in print */
        .print-header {
            display: none;
        }


        /* Print Table of Contents - hidden on screen, visible only in print */
        .print-toc {
            display: none;
        }

        @media print {
            /* Reset for print */
            * {
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
                color-adjust: exact !important;
            }

            /* Page setup - standard margins let browser render its header/footer */
            @page {
                size: A4;
                margin: 15mm 10mm;
            }

            /* Hide interactive elements */
            .header,
            .sidebar,
            .theme-toggle,
            .progress-bar-container,
            .finding-checkbox,
            .toolbar,
            .shortcut-help,
            .shortcut-backdrop,
            .finding-tooltip,
            .check-help-modal,
            .attr-help-btn,
            .check-help-btn,
            .top-action-info-btn,
            .card-controls,
            .hide-completed-toggle,
            button,
            .btn {
                display: none !important;
            }

            body {
                background: white !important;
                color: black !important;
                font-size: 10pt !important;
                line-height: 1.4 !important;
                margin: 0 !important;
                padding: 0 !important;
            }

            .main {
                margin: 0 !important;
                padding: 0 !important;
                width: 100% !important;
            }

            /* Print header - logo left, title + domain right (first page only) */
            .print-header {
                display: flex !important;
                flex-direction: column;
                align-items: center;
                gap: 2mm;
                margin-bottom: 8mm;
                padding-bottom: 4mm;
                border-bottom: 2px solid #333;
            }

            .print-header-logo {
                width: 14mm;
                height: 14mm;
            }

            .print-header-text {
                display: flex;
                flex-direction: column;
                align-items: center;
            }

            .print-header-title {
                font-size: 18pt;
                font-weight: bold;
                color: black !important;
                letter-spacing: 0.5pt;
                line-height: 1.2;
            }

            .print-header-domain {
                font-size: 10pt;
                color: #555 !important;
                margin-top: 1mm;
            }

            .print-header-disclaimer {
                font-size: 7pt;
                color: #888 !important;
                margin-top: 2mm;
                font-style: italic;
            }

            /* Summary cards - horizontal layout */
            .summary-grid {
                display: flex !important;
                flex-wrap: wrap !important;
                gap: 5mm !important;
                margin-bottom: 8mm !important;
                page-break-inside: avoid;
            }

            .summary-card {
                flex: 1 1 22% !important;
                min-width: 40mm !important;
                padding: 3mm !important;
                border: 1px solid #ccc !important;
                border-radius: 2mm !important;
                background: #f9f9f9 !important;
            }

            .summary-card .icon {
                width: 8mm !important;
                height: 8mm !important;
                font-size: 10pt !important;
            }

            .summary-card .value {
                font-size: 14pt !important;
            }

            .summary-card .label {
                font-size: 8pt !important;
            }

            /* Severity colors for print */
            .summary-card.finding .icon,
            .summary-card.finding .value { color: #d32f2f !important; }
            .summary-card.hint .icon,
            .summary-card.hint .value { color: #f57c00 !important; }
            .summary-card.note .icon,
            .summary-card.note .value { color: #388e3c !important; }
            .summary-card.secure .icon,
            .summary-card.secure .value { color: #2196f3 !important; }

            /* Info bar */
            .info-bar {
                display: flex !important;
                flex-wrap: wrap !important;
                gap: 5mm !important;
                padding: 3mm !important;
                margin-bottom: 6mm !important;
                border: 1px solid #ccc !important;
                border-radius: 2mm !important;
                background: #f5f5f5 !important;
                font-size: 9pt !important;
                page-break-inside: avoid;
            }

            .info-item {
                flex: 1 1 auto !important;
            }

            .info-label {
                font-weight: bold !important;
                color: #666 !important;
            }

            /* ---- Table of Contents — Severity Matrix (generated by JS beforeprint) ---- */
            .print-toc {
                display: block !important;
                margin-bottom: 8mm !important;
                page-break-inside: avoid;
            }

            .print-toc-title {
                font-size: 12pt !important;
                font-weight: bold !important;
                margin-bottom: 3mm !important;
            }

            .print-toc-table {
                width: 100% !important;
                border-collapse: collapse !important;
                font-size: 9pt !important;
            }

            .print-toc-table thead th {
                padding: 1.5mm 2mm !important;
                text-align: center !important;
                font-weight: 700 !important;
                font-size: 8pt !important;
                text-transform: uppercase !important;
                letter-spacing: 0.3px !important;
                color: #555 !important;
                border-bottom: 2px solid #333 !important;
            }

            .print-toc-table thead th:first-child {
                text-align: left !important;
                width: auto !important;
            }

            .print-toc-table thead th:not(:first-child) {
                width: 14mm !important;
            }

            .print-toc-table tbody td,
            .print-toc-table tfoot td {
                padding: 1.5mm 2mm !important;
                text-align: center !important;
                font-size: 9pt !important;
            }

            .print-toc-table tbody tr {
                border-bottom: 1px solid #e0e0e0 !important;
            }

            /* Left border severity indicator */
            .print-toc-table tbody tr.toc-severity-finding {
                border-left: 3px solid #d32f2f !important;
            }
            .print-toc-table tbody tr.toc-severity-hint {
                border-left: 3px solid #f57c00 !important;
            }
            .print-toc-table tbody tr.toc-severity-secure {
                border-left: 3px solid #2196f3 !important;
            }
            .print-toc-table tbody tr.toc-severity-note {
                border-left: 3px solid #388e3c !important;
            }

            /* Section name cell */
            .toc-section-name {
                text-align: left !important;
                font-weight: 500 !important;
            }

            .toc-section-name a {
                color: #000 !important;
                text-decoration: none !important;
            }

            /* Severity count cells — colored numbers */
            .toc-cell-finding.has-value {
                color: #d32f2f !important;
                font-weight: 700 !important;
            }
            .toc-cell-hint.has-value {
                color: #f57c00 !important;
                font-weight: 700 !important;
            }
            .toc-cell-note.has-value {
                color: #388e3c !important;
                font-weight: 600 !important;
            }
            .toc-cell-secure.has-value {
                color: #2196f3 !important;
                font-weight: 600 !important;
            }

            .no-value {
                color: #ccc !important;
            }

            /* Footer totals row */
            .print-toc-table tfoot tr {
                border-top: 2px solid #333 !important;
            }

            .toc-total-label {
                text-align: left !important;
                font-weight: 700 !important;
                text-transform: uppercase !important;
                font-size: 8pt !important;
                letter-spacing: 0.3px !important;
            }

            /* Top Priority Actions in print */
            .top-actions {
                display: block !important;
                border: 2px solid #d32f2f !important;
                border-radius: 2mm !important;
                padding: 3mm !important;
                margin-bottom: 8mm !important;
                background: #fff5f5 !important;
                page-break-inside: avoid;
            }

            .top-actions.collapsed .top-actions-list {
                display: block !important;
            }

            .top-actions-toggle {
                display: none !important;
            }

            .top-action-item {
                border: 1px solid #ccc !important;
                border-radius: 2mm !important;
                padding: 2mm 3mm !important;
                margin-bottom: 2mm !important;
                background: white !important;
            }

            .top-action-rank {
                background: #d32f2f !important;
                color: white !important;
                width: 6mm !important;
                height: 6mm !important;
                font-size: 9pt !important;
            }

            .top-action-title {
                font-size: 10pt !important;
            }

            .top-action-details {
                font-size: 8pt !important;
                -webkit-line-clamp: unset !important;
            }

            .top-action-fix {
                font-size: 8pt !important;
                color: #2b6cb0 !important;
            }

            .top-action-score {
                padding: 1mm 2mm !important;
                font-size: 8pt !important;
            }

            /* ---- Sections ---- */
            .section {
                page-break-before: always;
                margin-bottom: 5mm !important;
            }

            /* First section should not force a new page */
            .section:first-of-type {
                page-break-before: auto;
            }

            .section-header {
                background: #e0e0e0 !important;
                color: black !important;
                padding: 2mm 4mm !important;
                font-size: 11pt !important;
                font-weight: bold !important;
                border-radius: 2mm 2mm 0 0 !important;
                page-break-after: avoid;
            }

            /* Finding cards */
            .finding-card {
                border: 1px solid #ccc !important;
                border-radius: 2mm !important;
                margin-bottom: 3mm !important;
                page-break-inside: avoid;
                background: white !important;
            }

            .finding-card.completed {
                opacity: 1 !important;
            }

            .finding-card.completed .finding-title {
                text-decoration: none !important;
            }

            .finding-header {
                padding: 2mm 3mm !important;
                background: #f5f5f5 !important;
                border-bottom: 1px solid #ddd !important;
            }

            .finding-title {
                font-size: 10pt !important;
                font-weight: 600 !important;
            }

            .finding-count {
                font-size: 8pt !important;
                color: #666 !important;
            }

            /* Always show finding body in print */
            .finding-body {
                display: block !important;
                padding: 3mm !important;
            }

            /* Finding items */
            .finding-item {
                padding: 1mm 0 !important;
                font-size: 9pt !important;
                border-bottom: 1px dotted #ddd !important;
            }

            .finding-item:last-child {
                border-bottom: none !important;
            }

            /* Severity indicators */
            .finding-item.finding::before { content: "[!] "; color: #d32f2f !important; font-weight: bold; }
            .finding-item.hint::before { content: "[+] "; color: #f57c00 !important; font-weight: bold; }
            .finding-item.note::before { content: "[*] "; color: #388e3c !important; font-weight: bold; }
            .finding-item.secure::before { content: "[#] "; color: #2196f3 !important; font-weight: bold; }

            /* Object cards */
            .object-card {
                border: 1px solid #ccc !important;
                border-radius: 2mm !important;
                margin: 2mm 0 !important;
                page-break-inside: avoid;
            }

            .object-header {
                background: #e8e8e8 !important;
                color: black !important;
                padding: 2mm 3mm !important;
                font-size: 9pt !important;
                font-weight: 600 !important;
            }

            .object-body {
                display: block !important;
                padding: 2mm 3mm !important;
            }

            /* Force expand extended attributes in print */
            .extended-attrs {
                display: block !important;
            }

            /* Hide expand/collapse icons and toggles in print */
            .object-toggle,
            .expand-icon,
            .collapse-icon,
            .finding-toggle,
            .extended-attrs-toggle,
            .attr-drag-handle,
            .attr-col-resizer {
                display: none !important;
            }

            /* Attribute rows */
            .attr-row {
                display: flex !important;
                padding: 1mm 0 !important;
                border-bottom: 1px dotted #eee !important;
                font-size: 8pt !important;
            }

            .attr-row:last-child {
                border-bottom: none !important;
            }

            .attr-name {
                flex: 0 0 35% !important;
                font-weight: 600 !important;
                color: #333 !important;
            }

            .attr-value {
                flex: 1 !important;
                word-break: break-word !important;
            }

            /* Colored spans in print */
            .finding, span.finding { color: #d32f2f !important; font-weight: 600 !important; }
            .hint, span.hint { color: #f57c00 !important; }
            .note, span.note { color: #388e3c !important; }
            .secure, span.secure { color: #2196f3 !important; }

            /* Links */
            a {
                color: #0066cc !important;
                text-decoration: none !important;
            }

            /* Global page break rules */
            h1, h2, h3, .section-header, .finding-header {
                page-break-after: avoid;
            }

            .finding-card, .object-card {
                page-break-inside: avoid;
            }
        }

        @media (max-width: 1024px) {
            .sidebar { display: none; }
            .main { margin-left: 0; }
            .summary-grid { grid-template-columns: repeat(2, 1fr); }
        }

        /* Finding Tooltip Styles */
        .finding-tooltip-trigger {
            cursor: help;
            position: relative;
            border-bottom: 1px dotted currentColor;
        }

        .finding-tooltip {
            display: none;
            position: fixed;
            z-index: 1000;
            max-width: 600px;
            max-height: 80vh;
            overflow-y: auto;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            box-shadow: 0 8px 32px rgba(0,0,0,0.3);
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
            font-size: 13px;
        }

        .finding-tooltip.visible {
            display: block;
        }

        .tooltip-header {
            padding: 16px 20px;
            background: var(--bg-header);
            color: var(--text-header);
            border-radius: 11px 11px 0 0;
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            cursor: move;
            user-select: none;
        }

        .tooltip-header:active {
            cursor: grabbing;
        }

        /* Draggable state for tooltips */
        .finding-tooltip.dragging,
        .check-tooltip.dragging {
            transition: none;
            user-select: none;
        }

        .tooltip-title {
            font-size: 16px;
            font-weight: 600;
            margin-bottom: 4px;
        }

        .tooltip-risk {
            padding: 4px 12px;
            border-radius: 4px;
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
        }

        .tooltip-risk.critical { background: #b71c1c; color: white; }
        .tooltip-risk.high { background: var(--finding); color: white; }
        .tooltip-risk.medium { background: var(--hint); color: white; }
        .tooltip-risk.low { background: var(--note); color: white; }
        .tooltip-risk.info { background: var(--secure); color: white; }
        .tooltip-risk.secure { background: var(--secure); color: white; }
        /* adPEAS severity classes (mapped from SeverityClasses enum) */
        .tooltip-risk.finding { background: var(--finding); color: white; }
        .tooltip-risk.hint { background: var(--hint); color: #1a1a2e; }
        .tooltip-risk.note { background: var(--note); color: #1a1a2e; }

        .tooltip-close {
            position: absolute;
            top: 12px;
            right: 12px;
            background: rgba(255,255,255,0.2);
            border: none;
            color: var(--text-header);
            width: 28px;
            height: 28px;
            border-radius: 50%;
            cursor: pointer;
            font-size: 18px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .tooltip-close:hover {
            background: rgba(255,255,255,0.3);
        }

        .tooltip-body {
            padding: 16px 20px;
        }

        .tooltip-section {
            margin-bottom: 16px;
        }

        .tooltip-section:last-child {
            margin-bottom: 0;
        }

        .tooltip-section-title {
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--text-muted);
            margin-bottom: 8px;
            display: flex;
            align-items: center;
            gap: 8px;
            cursor: pointer;
        }

        .tooltip-section-title .toggle-icon {
            font-size: 10px;
            transition: transform 0.2s;
        }

        .tooltip-section-title.collapsed .toggle-icon {
            transform: rotate(-90deg);
        }

        .tooltip-section-content {
            color: var(--text);
            line-height: 1.6;
        }

        .tooltip-section-content.collapsed {
            display: none;
        }

        .tooltip-section-content ul {
            margin: 0;
            padding-left: 20px;
        }

        .tooltip-section-content li {
            margin-bottom: 6px;
        }

        .tooltip-section-content ol {
            margin: 0;
            padding-left: 20px;
        }

        .tooltip-section-content ol li {
            margin-bottom: 8px;
        }

        .tooltip-references {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .tooltip-references a {
            color: var(--accent);
            text-decoration: none;
        }

        .tooltip-references a:hover {
            text-decoration: underline;
        }

        .tooltip-tools {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
        }

        .tooltip-tool {
            background: var(--bg-hover);
            padding: 4px 10px;
            border-radius: 4px;
            font-size: 12px;
            font-family: 'Cascadia Code', Consolas, monospace;
        }

        .tooltip-tool-link {
            color: var(--accent);
            text-decoration: none;
            transition: background 0.2s;
        }

        .tooltip-tool-link:hover {
            background: var(--bg-card);
            text-decoration: underline;
        }

        .tooltip-mitre {
            display: inline-block;
            background: #5c2d91;
            color: white;
            padding: 4px 10px;
            border-radius: 4px;
            font-size: 12px;
            font-weight: 600;
        }

        .tooltip-mitre a {
            color: white;
            text-decoration: none;
        }

        .tooltip-mitre a:hover {
            text-decoration: underline;
        }

        /* Score Breakdown Tooltip Styles */
        .score-tooltip {
            display: none;
            position: fixed;
            z-index: 1001;
            min-width: 280px;
            max-width: 350px;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            box-shadow: 0 8px 32px rgba(0,0,0,0.3);
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
            font-size: 13px;
            overflow: hidden;
        }

        .score-tooltip.visible {
            display: block;
        }

        .score-tooltip-header {
            padding: 12px 16px;
            background: var(--bg-header);
            color: var(--text-header);
            border-radius: 11px 11px 0 0;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .score-tooltip-title {
            font-size: 14px;
            font-weight: 600;
        }

        .score-tooltip-final {
            font-size: 18px;
            font-weight: 700;
            padding: 4px 12px;
            border-radius: 6px;
        }

        .score-tooltip-final.critical { background: var(--finding); color: white; }
        .score-tooltip-final.high { background: #e67e22; color: white; }
        .score-tooltip-final.medium { background: var(--hint); color: #1a1a2e; }
        .score-tooltip-final.low { background: var(--note); color: #1a1a2e; }
        .score-tooltip-final.info { background: #6b7280; color: white; }

        .score-tooltip-body {
            padding: 12px 16px;
        }

        .score-tooltip-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 8px 0;
            border-bottom: 1px solid var(--border);
        }

        .score-tooltip-row:last-child {
            border-bottom: none;
        }

        .score-tooltip-row.total {
            border-top: 2px solid var(--border);
            border-bottom: none;
            margin-top: 4px;
            padding-top: 12px;
            font-weight: 600;
        }

        .score-tooltip-label {
            color: var(--text-muted);
            font-size: 12px;
        }

        .score-tooltip-label .reason {
            display: block;
            font-size: 11px;
            color: var(--text-muted);
            opacity: 0.8;
            margin-top: 2px;
        }

        .score-tooltip-value {
            font-weight: 600;
            font-family: 'Cascadia Code', Consolas, monospace;
            font-size: 13px;
        }

        .score-tooltip-value.positive {
            color: var(--finding);
        }

        .score-tooltip-value.neutral {
            color: var(--text);
        }

        .score-tooltip-value.modifier {
            color: var(--hint);
        }

        /* Check Help Button Styles */
        .check-help-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 20px;
            height: 20px;
            margin-left: 8px;
            background: var(--bg-main);
            border: 1px solid var(--border);
            border-radius: 50%;
            color: var(--text-muted);
            font-size: 12px;
            font-weight: 600;
            cursor: help;
            transition: all 0.2s ease;
            flex-shrink: 0;
        }

        .check-help-btn:hover {
            background: var(--accent);
            border-color: var(--accent);
            color: white;
        }

        .finding-title-wrapper {
            display: flex;
            align-items: center;
        }

        /* Check Description Tooltip Styles */
        .check-tooltip {
            display: none;
            position: fixed;
            z-index: 1000;
            max-width: 500px;
            max-height: 70vh;
            overflow-y: auto;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            box-shadow: 0 8px 32px rgba(0,0,0,0.3);
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
            font-size: 13px;
        }

        .check-tooltip.visible {
            display: block;
        }

        .check-tooltip-header {
            padding: 14px 18px;
            background: var(--accent);
            color: white;
            border-radius: 11px 11px 0 0;
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: move;
            user-select: none;
        }

        .check-tooltip-header:active {
            cursor: grabbing;
        }

        .check-tooltip-title {
            font-size: 14px;
            font-weight: 600;
        }

        .check-tooltip-close {
            background: rgba(255,255,255,0.2);
            border: none;
            color: white;
            width: 24px;
            height: 24px;
            border-radius: 50%;
            cursor: pointer;
            font-size: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .check-tooltip-close:hover {
            background: rgba(255,255,255,0.3);
        }

        .check-tooltip-body {
            padding: 16px 18px;
        }

        .check-tooltip-summary {
            font-size: 14px;
            line-height: 1.6;
            margin-bottom: 16px;
            color: var(--text);
        }

        .check-tooltip-section {
            margin-bottom: 14px;
        }

        .check-tooltip-section:last-child {
            margin-bottom: 0;
        }

        .check-tooltip-section-title {
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--text-muted);
            margin-bottom: 8px;
        }

        .check-tooltip-section-content {
            color: var(--text);
            line-height: 1.6;
        }

        .check-tooltip-section-content ul {
            margin: 0;
            padding-left: 18px;
        }

        .check-tooltip-section-content li {
            margin-bottom: 4px;
        }

        /* Filtering note styling - subtle info box */
        .check-tooltip-filtering {
            background: rgba(59, 130, 246, 0.08);
            border-left: 3px solid var(--accent);
            padding: 10px 12px;
            border-radius: 0 4px 4px 0;
            margin-top: 12px;
        }

        .check-tooltip-filtering .check-tooltip-section-title {
            color: var(--accent);
        }

        .check-tooltip-filtering .check-tooltip-section-content {
            font-size: 12px;
            color: var(--text-muted);
        }

        /* Secure message styling - positive green info box */
        .check-tooltip-secure {
            background: rgba(56, 142, 60, 0.1);
            border-left: 3px solid var(--secure);
            padding: 10px 12px;
            border-radius: 0 4px 4px 0;
            margin-top: 12px;
        }

        .check-tooltip-secure .check-tooltip-section-title {
            color: var(--secure);
        }

        .check-tooltip-secure .check-tooltip-section-content {
            font-size: 12px;
            color: var(--text-muted);
        }

    </style>
    <script>
        // Immediate theme application to prevent flash of wrong theme
        (function() {
            try {
                var savedTheme = localStorage.getItem('adpeas-theme');
                if (savedTheme === 'dark' || savedTheme === 'light') {
                    document.documentElement.setAttribute('data-theme', savedTheme);
                }
            } catch (e) {
                // localStorage not available, use default theme from template
            }
        })();
    </script>
</head>
<body>
    <!-- Skip Links for Accessibility -->
    <a href="#topActionsContainer" class="skip-link">Skip to Top Priority Actions</a>
    <a href="#cardViewContainer" class="skip-link">Skip to Findings</a>
    <a href="#searchInput" class="skip-link">Skip to Search</a>

    <!-- Live Region for Screen Reader Announcements -->
    <div id="a11yAnnouncements" class="visually-hidden" aria-live="polite" aria-atomic="true"></div>

    <header class="header" role="banner">
        <div class="header-brand">
            <img class="header-logo" src="data:image/png;base64," alt="adPEAS Logo">
            <span class="header-title">adPEAS</span>
        </div>
        <div class="header-disclaimer">{{DISCLAIMER}}</div>
        <div class="header-actions">
            <button class="theme-toggle" onclick="toggleTheme()" aria-label="Toggle theme" aria-pressed="false" role="switch" title="Toggle Dark/Light Mode">
                <span class="theme-toggle-stars"></span>
                <span class="theme-toggle-slider"></span>
                <span id="themeIcon" aria-hidden="true">&#9788;</span>
                <span id="themeLabel">Light</span>
            </button>
            <button class="btn" onclick="toggleShortcutHelp()" title="Keyboard Shortcuts (?)" aria-label="Show keyboard shortcuts and help">&#63; Help</button>
            <button class="btn" onclick="window.print()" aria-label="Print report or save as PDF">Print / PDF</button>
        </div>
    </header>

    <aside class="sidebar" role="navigation" aria-label="Report navigation">
        <div class="sidebar-section">
            <div class="sidebar-search">
                <label for="searchInput" class="visually-hidden">Search findings</label>
                <input type="search" placeholder="Search findings... (press / to focus)" id="searchInput" aria-describedby="searchHint">
                <span id="searchHint" class="visually-hidden">Type to filter findings by text content</span>
            </div>
        </div>

        <div class="sidebar-section" role="group" aria-labelledby="severityFilterTitle">
            <div class="sidebar-title" id="severityFilterTitle">Findings by Class</div>
            <a class="nav-item severity-filter" data-severity="all" href="javascript:void(0)" onclick="filterBySeverity('all')" role="button" aria-pressed="true">
                All <span class="count" aria-label="total findings">{{TOTAL_COUNT}}</span>
            </a>
            <a class="nav-item severity-filter finding" data-severity="finding" href="javascript:void(0)" onclick="filterBySeverity('finding')" role="button" aria-pressed="false">
                Finding <span class="count" aria-label="critical findings">{{FINDING_COUNT}}</span>
            </a>
            <a class="nav-item severity-filter hint" data-severity="hint" href="javascript:void(0)" onclick="filterBySeverity('hint')" role="button" aria-pressed="false">
                Hint <span class="count" aria-label="hints">{{HINT_COUNT}}</span>
            </a>
            <a class="nav-item severity-filter note" data-severity="note" href="javascript:void(0)" onclick="filterBySeverity('note')" role="button" aria-pressed="false">
                Note <span class="count" aria-label="notes">{{NOTE_COUNT}}</span>
            </a>
            <a class="nav-item severity-filter secure" data-severity="secure" href="javascript:void(0)" onclick="filterBySeverity('secure')" role="button" aria-pressed="false">
                Secure <span class="count" aria-label="secure items">{{SECURE_COUNT}}</span>
            </a>
        </div>

        {{NAVIGATION}}
    </aside>

    <main class="main" role="main" aria-label="Report content">
        <!-- Print-only header on first page (hidden on screen, visible in PDF) -->
        <div class="print-header" aria-hidden="true">
            <img class="print-header-logo" src="data:image/png;base64," alt="adPEAS Logo">
            <div class="print-header-text">
                <div class="print-header-title">adPEAS Security Report</div>
                <div class="print-header-domain">{{DOMAIN}}</div>
                <div class="print-header-disclaimer">{{DISCLAIMER}}</div>
            </div>
        </div>

        <section id="summary" aria-labelledby="summaryTitle">
            <h1 id="summaryTitle" class="visually-hidden">Security Report Summary</h1>
            <div class="summary-grid" role="group" aria-label="Finding counts by severity">
                <button class="summary-card finding" onclick="filterBySeverity('finding')" aria-label="Filter by Findings: {{FINDING_COUNT}} critical issues">
                    <div class="icon" aria-hidden="true">&#33;</div>
                    <div>
                        <div class="value">{{FINDING_COUNT}}</div>
                        <div class="label">Finding</div>
                    </div>
                </button>
                <button class="summary-card hint" onclick="filterBySeverity('hint')" aria-label="Filter by Hints: {{HINT_COUNT}} items">
                    <div class="icon" aria-hidden="true">&#9650;</div>
                    <div>
                        <div class="value">{{HINT_COUNT}}</div>
                        <div class="label">Hint</div>
                    </div>
                </button>
                <button class="summary-card note" onclick="filterBySeverity('note')" aria-label="Filter by Notes: {{NOTE_COUNT}} items">
                    <div class="icon" aria-hidden="true">&#9679;</div>
                    <div>
                        <div class="value">{{NOTE_COUNT}}</div>
                        <div class="label">Note</div>
                    </div>
                </button>
                <button class="summary-card secure" onclick="filterBySeverity('secure')" aria-label="Filter by Secure: {{SECURE_COUNT}} items">
                    <div class="icon" aria-hidden="true">&#9675;</div>
                    <div>
                        <div class="value">{{SECURE_COUNT}}</div>
                        <div class="label">Secure</div>
                    </div>
                </button>
            </div>

            <div class="info-bar">
                <div class="info-item">
                    <div class="label">Domain</div>
                    <div class="value">{{DOMAIN}}</div>
                </div>
                <div class="info-item">
                    <div class="label">Domain Controller</div>
                    <div class="value">{{SERVER}}</div>
                </div>
                <div class="info-item">
                    <div class="label">User</div>
                    <div class="value">{{USER}}</div>
                </div>
                <div class="info-item">
                    <div class="label">Generated</div>
                    <div class="value">{{GENERATED}}</div>
                </div>
                <div class="info-item">
                    <div class="label">Version</div>
                    <div class="value">{{VERSION}}</div>
                </div>
            </div>

            <!-- Card Controls -->
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px;" role="toolbar" aria-label="View controls">
                <div class="card-controls" id="cardControls" role="group" aria-label="Card expansion controls">
                    <button class="card-control-btn" onclick="expandAllCards()" title="Expand all cards and top priorities" aria-label="Expand all finding cards">Expand All</button>
                    <button class="card-control-btn" onclick="collapseAllCards()" title="Collapse all cards and top priorities" aria-label="Collapse all finding cards">Collapse All</button>
                </div>
                <label class="hide-completed-toggle" style="margin: 0 16px;">
                    <input type="checkbox" id="hideCompletedToggle" onchange="toggleHideCompleted()" aria-describedby="hideCompletedHint">
                    <span>Hide completed</span>
                    <span id="hideCompletedHint" class="visually-hidden">Toggle to show or hide findings marked as completed</span>
                </label>
            </div>

            <!-- Top Priority Actions (generated by JavaScript) -->
            <div id="topActionsContainer"></div>
        </section>

        <!-- Card View Container -->
        <div id="cardViewContainer" role="region" aria-label="Findings card view">
        {{FINDINGS_SECTIONS}}
        </div>
    </main>
    <script>
// ============================================================
        // CONSTANTS
        // ============================================================
        const UI_CONSTANTS = {
            KEYBOARD_FOCUS_DURATION: 2000,      // ms - how long keyboard focus highlight stays
            SEARCH_DEBOUNCE_DELAY: 150,         // ms - delay before search filter applies
            TOOLTIP_CLOSE_DELAY: 100,           // ms - delay before tooltip click-to-close activates
            SCROLL_DELAY: 100,                  // ms - delay before scrollIntoView after DOM changes
            VIEWPORT_PADDING: 20,               // px - padding from viewport edges for positioning
            COPY_FEEDBACK_DURATION: 2000,       // ms - how long "Copied!" feedback shows on copy button
            A11Y_ANNOUNCEMENT_DELAY: 100        // ms - delay before screen reader announcements
        };

        // ============================================================
        // ACCESSIBILITY HELPERS
        // ============================================================

        // Announce message to screen readers via live region
        function announceToScreenReader(message, priority = 'polite') {
            const liveRegion = document.getElementById('a11yAnnouncements');
            if (!liveRegion) return;

            // Set priority (polite or assertive)
            liveRegion.setAttribute('aria-live', priority);

            // Clear and set message (timing helps screen readers pick up the change)
            liveRegion.textContent = '';
            setTimeout(() => {
                liveRegion.textContent = message;
            }, UI_CONSTANTS.A11Y_ANNOUNCEMENT_DELAY);
        }

        // Update ARIA pressed state for toggle buttons
        function updateAriaPressed(element, isPressed) {
            if (element) {
                element.setAttribute('aria-pressed', isPressed ? 'true' : 'false');
            }
        }

        // Update ARIA expanded state for collapsible elements
        function updateAriaExpanded(element, isExpanded) {
            if (element) {
                element.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
            }
        }

        // Manage focus for modal-like elements (tooltips, help modal)
        let previouslyFocusedElement = null;

        function trapFocus(element) {
            previouslyFocusedElement = document.activeElement;
            const focusableElements = element.querySelectorAll(
                'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
            );
            const firstFocusable = focusableElements[0];
            const lastFocusable = focusableElements[focusableElements.length - 1];

            if (firstFocusable) {
                firstFocusable.focus();
            }

            element.addEventListener('keydown', function handleTab(e) {
                if (e.key === 'Tab') {
                    if (e.shiftKey && document.activeElement === firstFocusable) {
                        e.preventDefault();
                        lastFocusable.focus();
                    } else if (!e.shiftKey && document.activeElement === lastFocusable) {
                        e.preventDefault();
                        firstFocusable.focus();
                    }
                }
            });
        }

        function restoreFocus() {
            if (previouslyFocusedElement && previouslyFocusedElement.focus) {
                previouslyFocusedElement.focus();
                previouslyFocusedElement = null;
            }
        }

        function toggleTheme() {
            const html = document.documentElement;
            const newTheme = html.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
            html.setAttribute('data-theme', newTheme);
            safeSetItem('adpeas-theme', newTheme);
            updateThemeUI(newTheme);
            announceToScreenReader('Theme changed to ' + newTheme + ' mode');
        }

        function updateThemeUI(theme) {
            document.getElementById('themeIcon').innerHTML = theme === 'dark' ? '&#9788;' : '&#9790;';
            document.getElementById('themeLabel').textContent = theme === 'dark' ? 'Light' : 'Dark';
            // Update ARIA state for theme toggle
            const themeToggle = document.querySelector('.theme-toggle');
            if (themeToggle) {
                updateAriaPressed(themeToggle, theme === 'dark');
            }
        }

        function toggleFinding(header) {
            // Don't toggle if the click was actually a text selection (allow copy)
            if (window.getSelection && window.getSelection().toString().length > 0) return;
            const card = header.closest('.finding-card');
            card.classList.toggle('expanded');

            // Highlight the category in the sidebar navigation
            highlightCategoryForCard(card);
        }

        function highlightCategoryForCard(card) {
            // Remove previous category highlight
            document.querySelectorAll('.category-filter.category-highlight').forEach(f => f.classList.remove('category-highlight'));

            if (!card.classList.contains('expanded')) return;

            // Get the card's category and highlight the matching nav item
            const category = card.dataset.category;
            if (category) {
                const navItem = document.querySelector('.category-filter[data-category="' + category + '"]');
                if (navItem) navItem.classList.add('category-highlight');
            }
        }

        function toggleExtendedAttrs(objectId) {
            const extSection = document.getElementById('ext-' + objectId);
            const toggleBtn = extSection.previousElementSibling;
            const icon = document.getElementById('icon-' + objectId);

            if (extSection.style.display === 'none') {
                extSection.style.display = 'block';
                toggleBtn.classList.add('expanded');
                toggleBtn.querySelector('span:last-child').textContent =
                    toggleBtn.querySelector('span:last-child').textContent.replace('Show', 'Hide');
            } else {
                extSection.style.display = 'none';
                toggleBtn.classList.remove('expanded');
                toggleBtn.querySelector('span:last-child').textContent =
                    toggleBtn.querySelector('span:last-child').textContent.replace('Hide', 'Show');
            }
        }

        // Toggle individual object card (collapsed/expanded)
        function toggleObjectCard(objectId) {
            // Don't toggle if the click was actually a text selection (allow copy)
            if (window.getSelection && window.getSelection().toString().length > 0) return;
            const card = document.getElementById('obj-' + objectId);
            if (card) {
                card.classList.toggle('expanded');
            }
        }

        // Expand all object cards in a finding-card
        function expandAllObjects(findingCardId) {
            const findingCard = document.getElementById(findingCardId);
            if (findingCard) {
                findingCard.querySelectorAll('.object-detail').forEach(obj => {
                    obj.classList.add('expanded');
                });
                updateExpandCollapseButton(findingCardId, true);
            }
        }

        // Collapse all object cards in a finding-card
        function collapseAllObjects(findingCardId) {
            const findingCard = document.getElementById(findingCardId);
            if (findingCard) {
                findingCard.querySelectorAll('.object-detail').forEach(obj => {
                    obj.classList.remove('expanded');
                });
                updateExpandCollapseButton(findingCardId, false);
            }
        }

        // Toggle all object cards in a finding-card
        function toggleAllObjects(findingCardId) {
            const findingCard = document.getElementById(findingCardId);
            if (findingCard) {
                const objects = findingCard.querySelectorAll('.object-detail');
                const expandedCount = findingCard.querySelectorAll('.object-detail.expanded').length;
                const shouldExpand = expandedCount < objects.length / 2;

                objects.forEach(obj => {
                    if (shouldExpand) {
                        obj.classList.add('expanded');
                    } else {
                        obj.classList.remove('expanded');
                    }
                });
                updateExpandCollapseButton(findingCardId, shouldExpand);
            }
        }

        // Update the expand/collapse button text
        function updateExpandCollapseButton(findingCardId, isExpanded) {
            const btn = document.querySelector(`#${findingCardId} .expand-collapse-btn`);
            if (btn) {
                btn.innerHTML = isExpanded
                    ? '<span>&#9660;</span> Collapse All'
                    : '<span>&#9654;</span> Expand All';
            }
        }

        let currentSeverityFilter = 'all';
        let currentCategoryFilter = 'all';
        let currentSearchQuery = '';
        let hideCompletedEnabled = false;

        function filterBySeverity(severity) {
            currentSeverityFilter = severity;
            // Reset category filter when severity is clicked
            currentCategoryFilter = 'all';

            // Update active state and ARIA pressed - severity gets highlighted, categories reset
            document.querySelectorAll('.severity-filter').forEach(link => {
                const isActive = link.dataset.severity === severity;
                link.classList.toggle('active', isActive);
                updateAriaPressed(link, isActive);
            });
            // Remove active and card-highlight from ALL categories
            document.querySelectorAll('.category-filter').forEach(link => {
                link.classList.remove('active', 'category-highlight');
                updateAriaPressed(link, false);
            });

            applyFilters();

            // Announce filter change to screen readers
            const count = document.querySelectorAll('.finding-card:not([style*="display: none"])').length;
            const severityLabel = severity === 'all' ? 'all severities' : severity;
            announceToScreenReader('Filtered by ' + severityLabel + '. ' + count + ' findings shown.');
        }

        function filterByCategory(category) {
            currentCategoryFilter = category;
            // Reset severity filter when category is clicked
            currentSeverityFilter = 'all';

            // Update active state and ARIA pressed - category gets highlighted, severities reset
            // Also clear card-highlight since user is now actively filtering
            document.querySelectorAll('.category-filter').forEach(link => {
                const isActive = link.dataset.category === category;
                link.classList.toggle('active', isActive);
                link.classList.remove('category-highlight');
                updateAriaPressed(link, isActive);
            });
            // Remove active from ALL severities (no highlight)
            document.querySelectorAll('.severity-filter').forEach(link => {
                link.classList.remove('active');
                updateAriaPressed(link, false);
            });

            applyFilters();

            // Announce filter change to screen readers
            const count = document.querySelectorAll('.finding-card:not([style*="display: none"])').length;
            announceToScreenReader('Filtered by category ' + category + '. ' + count + ' findings shown.');
        }

        function updateItemCount(card, visible, total) {
            const countEl = card.querySelector('.finding-count');
            if (countEl) {
                if (!countEl.dataset.originalText) {
                    countEl.dataset.originalText = countEl.textContent;
                }
                countEl.textContent = visible + ' of ' + total + ' item(s)';
            }
        }

        function resetItemCount(card) {
            const countEl = card.querySelector('.finding-count');
            if (countEl && countEl.dataset.originalText) {
                countEl.textContent = countEl.dataset.originalText;
            }
        }

        function applyFilters() {
            // Filter finding cards with item-level search filtering
            document.querySelectorAll('.finding-card').forEach(card => {
                const cardSeverity = card.dataset.severity;
                const cardCategory = card.dataset.category;
                const cardId = card.dataset.cardId;

                const matchesSeverity = currentSeverityFilter === 'all' || cardSeverity === currentSeverityFilter;
                const matchesCategory = currentCategoryFilter === 'all' || cardCategory === currentCategoryFilter;
                const isCompleted = completedFindings[cardId] === true;
                const matchesCompleted = !hideCompletedEnabled || !isCompleted;

                // Non-search filters: card-level only
                if (!matchesSeverity || !matchesCategory || !matchesCompleted) {
                    card.style.display = 'none';
                    return;
                }

                // No search query: show card, reset all items to visible
                if (currentSearchQuery === '') {
                    card.style.display = '';
                    card.querySelectorAll('.object-detail, .finding-item').forEach(item => {
                        item.style.display = '';
                    });
                    resetItemCount(card);
                    return;
                }

                // Search active: filter individual items within card
                const items = card.querySelectorAll(':scope > .finding-body > .object-detail, :scope > .finding-body > .finding-item');
                let visibleCount = 0;
                const totalCount = items.length;

                // Check if card header/title matches (show all items if card title matches)
                const header = card.querySelector('.finding-header');
                const headerMatches = header && header.textContent.toLowerCase().includes(currentSearchQuery);

                items.forEach(item => {
                    const itemText = item.textContent.toLowerCase();
                    if (itemText.includes(currentSearchQuery) || headerMatches) {
                        item.style.display = '';
                        visibleCount++;
                    } else {
                        item.style.display = 'none';
                    }
                });

                // Show card only if at least 1 item matches (or header matches)
                if (visibleCount > 0 || headerMatches) {
                    card.style.display = '';
                    if (visibleCount < totalCount && !headerMatches) {
                        updateItemCount(card, visibleCount, totalCount);
                    } else {
                        resetItemCount(card);
                    }
                } else {
                    card.style.display = 'none';
                }
            });
        }

        // Finding definitions (embedded from adPEAS-FindingDefinitions.ps1)
        const findingDefinitions = {{FINDING_DEFINITIONS_JSON}};

        // Check descriptions (embedded from adPEAS-ObjectTypes.ps1)
        const checkDescriptions = {{CHECK_DESCRIPTIONS_JSON}};

        // Scoring context data for context-aware risk calculation
        const scoringContext = {{SCORING_CONTEXT_JSON}};

        document.addEventListener('DOMContentLoaded', function() {
            // Favicon: adPEAS logo as 32x32 PNG via Blob URL (works on file:// protocol)
            (function() {
                try {
                    var b64 = '';
                    var byteStr = atob(b64);
                    var bytes = new Uint8Array(byteStr.length);
                    for (var i = 0; i < byteStr.length; i++) bytes[i] = byteStr.charCodeAt(i);
                    var blob = new Blob([bytes], { type: 'image/png' });
                    var url = URL.createObjectURL(blob);
                    var link = document.createElement('link');
                    link.rel = 'icon';
                    link.type = 'image/png';
                    link.href = url;
                    document.head.appendChild(link);
                } catch(e) { /* favicon setup failed, non-critical */ }
            })();

            // Theme: Check system preference first, then localStorage, then default
            let savedTheme = safeGetItem('adpeas-theme');
            if (!savedTheme) {
                // Auto-detect system preference
                if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
                    savedTheme = 'light';
                } else {
                    savedTheme = '{{DEFAULT_THEME}}';
                }
            }
            document.documentElement.setAttribute('data-theme', savedTheme);
            updateThemeUI(savedTheme);

            // Listen for system theme changes
            if (window.matchMedia) {
                window.matchMedia('(prefers-color-scheme: light)').addEventListener('change', function(e) {
                    // Only auto-switch if user hasn't manually set a preference
                    if (!safeGetItem('adpeas-theme')) {
                        const newTheme = e.matches ? 'light' : 'dark';
                        document.documentElement.setAttribute('data-theme', newTheme);
                        updateThemeUI(newTheme);
                    }
                });
            }

            // Debounced search input to prevent performance issues on large reports
            let searchDebounceTimer = null;
            document.getElementById('searchInput').addEventListener('input', function(e) {
                clearTimeout(searchDebounceTimer);
                searchDebounceTimer = setTimeout(() => {
                    currentSearchQuery = e.target.value.toLowerCase();
                    applyFilters();
                }, UI_CONSTANTS.SEARCH_DEBOUNCE_DELAY);
            });

            // Initialize finding tooltips
            initFindingTooltips();

            // Initialize check help tooltips
            initCheckTooltips();

            // Initialize score breakdown tooltips
            initScoreTooltips();

            // Initialize draggable tooltips/popups
            initDraggableTooltips();

            // Initialize checkbox system
            initCheckboxSystem();

            // Initialize keyboard shortcuts
            initKeyboardShortcuts();

            // Create shortcut help modal
            createShortcutHelpModal();

            // Generate Top Priority Actions
            generateTopPriorityActions();

            // Populate score badges on finding cards, then sort by score
            populateCardScores();
            sortCardsByScore();

            // Initialize attribute drag & drop reordering
            initAttributeDragAndDrop();

            // Initialize per-card name-column resizing
            initColumnResize();
        });

        let activeTooltip = null;

        function initFindingTooltips() {
            // Create tooltip container
            const tooltipDiv = document.createElement('div');
            tooltipDiv.id = 'findingTooltip';
            tooltipDiv.className = 'finding-tooltip';
            tooltipDiv.setAttribute('role', 'dialog');
            tooltipDiv.setAttribute('aria-modal', 'false');
            tooltipDiv.setAttribute('aria-label', 'Finding details');
            document.body.appendChild(tooltipDiv);

            // Add event listeners to all finding triggers
            document.querySelectorAll('[data-finding-id]').forEach(trigger => {
                trigger.classList.add('finding-tooltip-trigger');
                trigger.setAttribute('role', 'button');
                trigger.setAttribute('tabindex', '0');
                trigger.setAttribute('aria-haspopup', 'dialog');
                trigger.setAttribute('aria-expanded', 'false');

                // Click handler
                trigger.addEventListener('click', function(e) {
                    e.stopPropagation();
                    showFindingTooltip(this, this.dataset.findingId);
                });

                // Keyboard handler for accessibility
                trigger.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        e.stopPropagation();
                        showFindingTooltip(this, this.dataset.findingId);
                    }
                });
            });

            // Close tooltip when clicking outside
            document.addEventListener('click', function(e) {
                if (activeTooltip && !e.target.closest('.finding-tooltip') && !e.target.closest('[data-finding-id]')) {
                    hideTooltip();
                }
            });

            // Close on escape key
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && activeTooltip) {
                    hideTooltip();
                }
            });
        }

        let activeFindingTrigger = null;

        function showFindingTooltip(trigger, findingId) {
            const tooltip = document.getElementById('findingTooltip');
            const finding = findingDefinitions[findingId];

            if (!finding) {
                console.warn('Finding definition not found:', findingId);
                return;
            }

            // Close any previously open tooltip first
            if (activeFindingTrigger && activeFindingTrigger !== trigger) {
                activeFindingTrigger.setAttribute('aria-expanded', 'false');
            }

            // Get actual severity using hybrid approach (Option C):
            // 1. First: Check the trigger element itself for severity class (e.g., <span class="finding" data-finding-id="...">)
            // 2. Then: Check the attr-value div for severity class
            // 3. Fallback: Use parent card's severity
            // 4. Final fallback: Use static definition severity
            let actualSeverity = null;

            // Check severity class directly on the trigger element (most precise - for multi-value attributes)
            // HTML: <span class="finding" data-finding-id="PRIVILEGED_GROUP_MEMBERSHIP">Domain Admins</span>
            if (trigger.classList.contains('finding')) {
                actualSeverity = 'finding';
            } else if (trigger.classList.contains('hint')) {
                actualSeverity = 'hint';
            } else if (trigger.classList.contains('note')) {
                actualSeverity = 'note';
            } else if (trigger.classList.contains('secure')) {
                actualSeverity = 'secure';
            }

            // Check for attribute-level severity on attr-value div (for single-value attributes)
            if (!actualSeverity) {
                const attrValue = trigger.closest('.attr-value');
                if (attrValue) {
                    if (attrValue.classList.contains('finding')) {
                        actualSeverity = 'finding';
                    } else if (attrValue.classList.contains('hint')) {
                        actualSeverity = 'hint';
                    } else if (attrValue.classList.contains('note')) {
                        actualSeverity = 'note';
                    } else if (attrValue.classList.contains('secure')) {
                        actualSeverity = 'secure';
                    }
                }
            }

            // Fallback to card severity if no attribute severity found
            if (!actualSeverity) {
                const parentCard = trigger.closest('.finding-card');
                actualSeverity = parentCard?.dataset?.severity || null;
            }

            // Build tooltip HTML with actual severity override
            tooltip.innerHTML = buildTooltipHtml(finding, findingId, actualSeverity);

            // Make visible first (but off-screen) so we can measure
            tooltip.style.visibility = 'hidden';
            tooltip.classList.add('visible');

            // Position tooltip (now we can measure correctly)
            positionTooltip(tooltip, trigger);

            // Make fully visible
            tooltip.style.visibility = 'visible';
            activeTooltip = tooltip;
            activeFindingTrigger = trigger;

            // Update ARIA state
            trigger.setAttribute('aria-expanded', 'true');

            // Add section toggle listeners
            tooltip.querySelectorAll('.tooltip-section-title').forEach(title => {
                title.addEventListener('click', function() {
                    this.classList.toggle('collapsed');
                    const content = this.nextElementSibling;
                    content.classList.toggle('collapsed');
                });
            });
        }

        function hideTooltip() {
            const tooltip = document.getElementById('findingTooltip');
            tooltip.classList.remove('visible');
            activeTooltip = null;

            // Reset ARIA expanded state on trigger
            if (activeFindingTrigger) {
                activeFindingTrigger.setAttribute('aria-expanded', 'false');
                activeFindingTrigger = null;
            }
        }

        function positionTooltip(tooltip, trigger) {
            const rect = trigger.getBoundingClientRect();
            const viewportWidth = window.innerWidth;
            const viewportHeight = window.innerHeight;

            // Reset position for measurement
            tooltip.style.left = '0';
            tooltip.style.top = '0';

            // Get tooltip dimensions
            const tooltipRect = tooltip.getBoundingClientRect();

            // Calculate position - prefer below and to the right of trigger
            let left = rect.left;
            let top = rect.bottom + 8;

            // Adjust if too far right
            if (left + tooltipRect.width > viewportWidth - UI_CONSTANTS.VIEWPORT_PADDING) {
                left = viewportWidth - tooltipRect.width - 20;
            }

            // Adjust if too far left
            if (left < UI_CONSTANTS.VIEWPORT_PADDING) {
                left = UI_CONSTANTS.VIEWPORT_PADDING;
            }

            // Adjust if too far down - show above instead
            if (top + tooltipRect.height > viewportHeight - UI_CONSTANTS.VIEWPORT_PADDING) {
                top = rect.top - tooltipRect.height - 8;
            }

            // Ensure top is not negative
            if (top < UI_CONSTANTS.VIEWPORT_PADDING) {
                top = UI_CONSTANTS.VIEWPORT_PADDING;
            }

            tooltip.style.left = left + 'px';
            tooltip.style.top = top + 'px';
        }

        function buildTooltipHtml(finding, findingId, actualSeverity) {
            // Map card severity to display label and CSS class
            // actualSeverity comes from parent card's data-severity attribute
            // If provided, it overrides the static finding.risk from definition
            // Maps SeverityClasses (from adPEAS-Types.ps1) to display labels and CSS classes
            // These values are used for tooltip badges and match the central definitions
            const severityMap = {
                'finding': { label: 'FINDING', class: 'finding' },
                'hint': { label: 'HINT', class: 'hint' },
                'note': { label: 'NOTE', class: 'note' },
                'secure': { label: 'SECURE', class: 'secure' }  // Blue in CSS
            };

            let riskLabel, riskClass;
            if (actualSeverity && severityMap[actualSeverity]) {
                // Use actual severity from parent card (dynamic)
                riskLabel = severityMap[actualSeverity].label;
                riskClass = severityMap[actualSeverity].class;
            } else {
                // Fallback to static definition
                riskLabel = finding.risk;
                riskClass = finding.risk.toLowerCase();
            }

            let html = `
                <div class="tooltip-header">
                    <div>
                        <div class="tooltip-title">${escapeHtml(finding.title)}</div>
                        <span class="tooltip-risk ${riskClass}">${escapeHtml(riskLabel)}</span>
                    </div>
                    <button class="tooltip-close" onclick="hideTooltip()">&times;</button>
                </div>
                <div class="tooltip-body">
            `;

            // Description
            html += `
                <div class="tooltip-section">
                    <div class="tooltip-section-title">
                        <span class="toggle-icon">&#9660;</span> Description
                    </div>
                    <div class="tooltip-section-content">
                        ${escapeHtml(finding.description)}
                    </div>
                </div>
            `;

            // Impact (collapsed by default)
            if (finding.impact && finding.impact.length > 0) {
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-title collapsed">
                            <span class="toggle-icon">&#9660;</span> Impact
                        </div>
                        <div class="tooltip-section-content collapsed">
                            <ul>
                                ${finding.impact.map(i => `<li>${escapeHtml(i)}</li>`).join('')}
                            </ul>
                        </div>
                    </div>
                `;
            }

            // Attack/Protection section (collapsible by default)
            // For "Secure" findings, this section describes what attacks are prevented
            if (finding.attack && finding.attack.length > 0) {
                const isSecure = actualSeverity === 'secure' || (finding.risk && finding.risk.toLowerCase() === 'secure');
                const attackSectionTitle = isSecure ? 'Blocked Attack Vectors' : 'Attack Steps';
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-title collapsed">
                            <span class="toggle-icon">&#9660;</span> ${attackSectionTitle}
                        </div>
                        <div class="tooltip-section-content collapsed">
                            <ul>
                                ${finding.attack.map(a => `<li>${escapeHtml(a)}</li>`).join('')}
                            </ul>
                        </div>
                    </div>
                `;
            }

            // Remediation / Best Practices section
            // For "Secure" findings, this section describes how to maintain the secure configuration
            if (finding.remediation && finding.remediation.length > 0) {
                const isSecureConfig = actualSeverity === 'secure' || (finding.risk && finding.risk.toLowerCase() === 'secure');
                const remediationTitle = isSecureConfig ? 'Best Practices' : 'Remediation';
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-title collapsed">
                            <span class="toggle-icon">&#9660;</span> ${remediationTitle}
                        </div>
                        <div class="tooltip-section-content collapsed">
                            <ul>
                                ${finding.remediation.map(r => `<li>${escapeHtml(r)}</li>`).join('')}
                            </ul>
                        </div>
                    </div>
                `;
            }

            // Remediation Commands (PowerShell with Copy button)
            if (finding.remediationCommands && finding.remediationCommands.length > 0) {
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-title collapsed">
                            <span class="toggle-icon">&#9660;</span> Quick Fix Commands
                        </div>
                        <div class="tooltip-section-content collapsed">
                            <div class="remediation-disclaimer">&#9888; Example commands for reference only. Always test in a non-production environment first and adapt to your specific situation.</div>
                            ${finding.remediationCommands.map(cmd => `
                                <div class="remediation-command">
                                    <div class="remediation-command-desc">${escapeHtml(cmd.description)}</div>
                                    <div class="remediation-code">
                                        <button class="copy-btn" onclick="copyToClipboard(this, \`${cmd.command.replace(/`/g, '\\`').replace(/\\/g, '\\\\')}\`)">Copy</button>
                                        <pre>${escapeHtml(cmd.command)}</pre>
                                    </div>
                                </div>
                            `).join('')}
                        </div>
                    </div>
                `;
            }

            // References (collapsible by default)
            if (finding.references && finding.references.length > 0) {
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-title collapsed">
                            <span class="toggle-icon">&#9660;</span> References
                        </div>
                        <div class="tooltip-section-content collapsed tooltip-references">
                            ${finding.references.map(r => `<a href="${escapeHtml(r.url)}" target="_blank" rel="noopener">${escapeHtml(r.title)}</a>`).join('')}
                        </div>
                    </div>
                `;
            }

            // Tools (collapsible by default) - supports both string and object format
            if (finding.tools && finding.tools.length > 0) {
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-title collapsed">
                            <span class="toggle-icon">&#9660;</span> Tools
                        </div>
                        <div class="tooltip-section-content collapsed tooltip-tools">
                            ${finding.tools.map(t => {
                                // Support both string (legacy) and object format {name, url}
                                if (typeof t === 'object' && t.name) {
                                    if (t.url) {
                                        return `<a href="${escapeHtml(t.url)}" target="_blank" rel="noopener" class="tooltip-tool tooltip-tool-link">${escapeHtml(t.name)}</a>`;
                                    } else {
                                        return `<span class="tooltip-tool">${escapeHtml(t.name)}</span>`;
                                    }
                                } else {
                                    return `<span class="tooltip-tool">${escapeHtml(t)}</span>`;
                                }
                            }).join('')}
                        </div>
                    </div>
                `;
            }

            // MITRE ATT&CK
            if (finding.mitre) {
                const mitreUrl = `https://attack.mitre.org/techniques/${finding.mitre.replace('.', '/')}/`;
                html += `
                    <div class="tooltip-section">
                        <div class="tooltip-section-content">
                            <span class="tooltip-mitre">
                                <a href="${mitreUrl}" target="_blank" rel="noopener">MITRE ATT&CK: ${escapeHtml(finding.mitre)}</a>
                            </span>
                        </div>
                    </div>
                `;
            }

            html += '</div>';
            return html;
        }

        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Escape JSON for use in HTML data attributes
        // Uses single quotes in HTML attribute, escapes single quotes in JSON
        function escapeJsonForAttr(obj) {
            if (!obj) return '';
            const json = JSON.stringify(obj);
            // Replace single quotes with escaped version for safe embedding
            return json.replace(/'/g, '&#39;');
        }

        // Decode HTML entities in a string (for parsing data attributes)
        function decodeHtmlEntities(str) {
            if (!str) return '';
            const txt = document.createElement('textarea');
            txt.innerHTML = str;
            return txt.value;
        }

        // Check description tooltip functionality
        let activeCheckTooltip = null;

        let activeCheckTrigger = null;

        function initCheckTooltips() {
            // Create check tooltip container
            const tooltipDiv = document.createElement('div');
            tooltipDiv.id = 'checkTooltip';
            tooltipDiv.className = 'check-tooltip';
            tooltipDiv.setAttribute('role', 'dialog');
            tooltipDiv.setAttribute('aria-modal', 'false');
            tooltipDiv.setAttribute('aria-label', 'Check description');
            document.body.appendChild(tooltipDiv);

            // Add event listeners to all check help buttons
            document.querySelectorAll('.check-help-btn').forEach(btn => {
                btn.setAttribute('aria-haspopup', 'dialog');
                btn.setAttribute('aria-expanded', 'false');
                btn.setAttribute('aria-label', 'Show information about this check');

                btn.addEventListener('click', function(e) {
                    e.stopPropagation();
                    // Prefer ObjectType over title for tooltip lookup (more reliable)
                    const objectType = btn.dataset.objectType;
                    const checkTitle = btn.dataset.checkTitle;
                    showCheckTooltip(this, objectType, checkTitle);
                });

                // Keyboard support
                btn.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        e.stopPropagation();
                        const objectType = btn.dataset.objectType;
                        const checkTitle = btn.dataset.checkTitle;
                        showCheckTooltip(this, objectType, checkTitle);
                    }
                });
            });

            // Close tooltip when clicking outside
            document.addEventListener('click', function(e) {
                if (activeCheckTooltip && !e.target.closest('.check-tooltip') && !e.target.closest('.check-help-btn')) {
                    hideCheckTooltip();
                }
            });

            // Close on escape key (consistent with finding tooltip)
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && activeCheckTooltip) {
                    hideCheckTooltip();
                }
            });
        }

        function showCheckTooltip(trigger, objectType, checkTitle) {
            const tooltip = document.getElementById('checkTooltip');

            // Look up check description by ObjectType
            if (!objectType || !checkDescriptions[objectType]) {
                console.warn('Check description not found for ObjectType:', objectType);
                return;
            }

            const check = checkDescriptions[objectType];
            const lookupKey = objectType;

            // Get card severity from parent finding-card element
            const findingCard = trigger.closest('.finding-card');
            const cardSeverity = findingCard ? findingCard.dataset.severity : null;

            // Build tooltip HTML (pass severity for secure message display)
            tooltip.innerHTML = buildCheckTooltipHtml(check, checkTitle, cardSeverity);

            // Make visible first (but off-screen) so we can measure
            tooltip.style.visibility = 'hidden';
            tooltip.classList.add('visible');

            // Position tooltip (now we can measure correctly)
            positionCheckTooltip(tooltip, trigger);

            // Make fully visible
            tooltip.style.visibility = 'visible';
            activeCheckTooltip = tooltip;

            // Close any previous trigger and update ARIA
            if (activeCheckTrigger && activeCheckTrigger !== trigger) {
                activeCheckTrigger.setAttribute('aria-expanded', 'false');
            }
            activeCheckTrigger = trigger;
            trigger.setAttribute('aria-expanded', 'true');
        }

        function hideCheckTooltip() {
            const tooltip = document.getElementById('checkTooltip');
            tooltip.classList.remove('visible');

            // Reset ARIA state
            if (activeCheckTrigger) {
                activeCheckTrigger.setAttribute('aria-expanded', 'false');
                activeCheckTrigger = null;
            }
            activeCheckTooltip = null;
        }

        // Reuse the same positioning function for check tooltips
        function positionCheckTooltip(tooltip, trigger) {
            positionTooltip(tooltip, trigger);
        }

        // ============================================================
        // DRAGGABLE TOOLTIPS/POPUPS
        // ============================================================

        let dragState = {
            isDragging: false,
            tooltip: null,
            offsetX: 0,
            offsetY: 0
        };

        function initDraggableTooltips() {
            // Handle mousedown on tooltip headers
            document.addEventListener('mousedown', function(e) {
                const header = e.target.closest('.tooltip-header, .check-tooltip-header');
                if (!header) return;

                // Don't drag if clicking on close button
                if (e.target.closest('.tooltip-close, .check-tooltip-close')) return;

                const tooltip = header.closest('.finding-tooltip, .check-tooltip');
                if (!tooltip || !tooltip.classList.contains('visible')) return;

                e.preventDefault();
                dragState.isDragging = true;
                dragState.tooltip = tooltip;

                // Get current position (could be from CSS or previous drag)
                const rect = tooltip.getBoundingClientRect();
                dragState.offsetX = e.clientX - rect.left;
                dragState.offsetY = e.clientY - rect.top;

                tooltip.classList.add('dragging');
            });

            document.addEventListener('mousemove', function(e) {
                if (!dragState.isDragging || !dragState.tooltip) return;

                e.preventDefault();

                // Calculate new position
                let newX = e.clientX - dragState.offsetX;
                let newY = e.clientY - dragState.offsetY;

                // Keep within viewport bounds
                const tooltipRect = dragState.tooltip.getBoundingClientRect();
                const maxX = window.innerWidth - tooltipRect.width;
                const maxY = window.innerHeight - tooltipRect.height;

                newX = Math.max(0, Math.min(newX, maxX));
                newY = Math.max(0, Math.min(newY, maxY));

                dragState.tooltip.style.left = newX + 'px';
                dragState.tooltip.style.top = newY + 'px';
            });

            document.addEventListener('mouseup', function() {
                if (dragState.isDragging && dragState.tooltip) {
                    dragState.tooltip.classList.remove('dragging');
                }
                dragState.isDragging = false;
                dragState.tooltip = null;
            });

            // Prevent text selection while dragging
            document.addEventListener('selectstart', function(e) {
                if (dragState.isDragging) {
                    e.preventDefault();
                }
            });
        }

        function buildCheckTooltipHtml(check, checkTitle, cardSeverity) {
            let html = `
                <div class="check-tooltip-header">
                    <span class="check-tooltip-title">About this Check</span>
                    <button class="check-tooltip-close" onclick="hideCheckTooltip()">&times;</button>
                </div>
                <div class="check-tooltip-body">
            `;

            // Summary
            html += `<div class="check-tooltip-summary">${escapeHtml(check.summary)}</div>`;

            // Secure Message (shown when card severity is 'secure')
            if (cardSeverity === 'secure' && check.secureMessage) {
                html += `
                    <div class="check-tooltip-section check-tooltip-secure">
                        <div class="check-tooltip-section-title">Secure Configuration</div>
                        <div class="check-tooltip-section-content">
                            ${escapeHtml(check.secureMessage)}
                        </div>
                    </div>
                `;
            }

            // Why It Matters
            if (check.whyItMatters) {
                html += `
                    <div class="check-tooltip-section">
                        <div class="check-tooltip-section-title">Why It Matters</div>
                        <div class="check-tooltip-section-content">
                            ${escapeHtml(check.whyItMatters)}
                        </div>
                    </div>
                `;
            }

            // What We Check
            if (check.whatWeCheck && check.whatWeCheck.length > 0) {
                html += `
                    <div class="check-tooltip-section">
                        <div class="check-tooltip-section-title">What We Check</div>
                        <div class="check-tooltip-section-content">
                            <ul>
                                ${check.whatWeCheck.map(item => `<li>${escapeHtml(item)}</li>`).join('')}
                            </ul>
                        </div>
                    </div>
                `;
            }

            // Filtering Note (documents privilege filtering behavior)
            if (check.filteringNote) {
                html += `
                    <div class="check-tooltip-section check-tooltip-filtering">
                        <div class="check-tooltip-section-title">Output Filtering</div>
                        <div class="check-tooltip-section-content">
                            ${escapeHtml(check.filteringNote)}
                        </div>
                    </div>
                `;
            }

            html += '</div>';
            return html;
        }

        // ============================================================
        // CHECKBOX SYSTEM - Mark findings as completed
        // ============================================================

        let completedFindings = {};
        let reportHash = '';
        let localStorageAvailable = true;
        let localStorageWriteAttempts = 0;
        const MAX_WRITE_FAILURES = 3;

        // Safe localStorage wrapper with differentiated error handling
        // - Security errors (privacy mode): Permanently disable localStorage
        // - Quota errors: Retry up to MAX_WRITE_FAILURES times, then disable writes only
        // - Transient errors: Log and continue
        function safeGetItem(key) {
            if (!localStorageAvailable) return null;
            try {
                return localStorage.getItem(key);
            } catch (e) {
                if (isSecurityError(e)) {
                    console.warn('localStorage blocked (privacy mode):', e.message);
                    localStorageAvailable = false;
                } else {
                    console.warn('localStorage read failed:', e.message);
                }
                return null;
            }
        }

        function safeSetItem(key, value) {
            if (!localStorageAvailable) return false;
            try {
                localStorage.setItem(key, value);
                localStorageWriteAttempts = 0; // Reset on success
                return true;
            } catch (e) {
                if (isSecurityError(e)) {
                    // Privacy mode or security restriction - permanently disable
                    console.warn('localStorage blocked (privacy mode):', e.message);
                    localStorageAvailable = false;
                    return false;
                } else if (isQuotaError(e)) {
                    // Quota exceeded - try to clean up old data
                    localStorageWriteAttempts++;
                    console.warn('localStorage quota exceeded, attempt', localStorageWriteAttempts);
                    if (localStorageWriteAttempts >= MAX_WRITE_FAILURES) {
                        console.warn('localStorage quota exceeded repeatedly, disabling writes');
                        localStorageAvailable = false;
                    }
                    return false;
                } else {
                    // Other transient error - log but don't disable
                    console.warn('localStorage write failed:', e.message);
                    return false;
                }
            }
        }

        function isSecurityError(e) {
            // SecurityError is thrown in privacy mode or when localStorage is blocked
            return e.name === 'SecurityError' ||
                   (e.name === 'Error' && e.message.includes('access'));
        }

        function isQuotaError(e) {
            // QuotaExceededError when storage is full
            return e.name === 'QuotaExceededError' ||
                   e.name === 'NS_ERROR_DOM_QUOTA_REACHED' ||
                   (e.code && e.code === 22);
        }

        function initCheckboxSystem() {
            // Generate a hash from the report content for localStorage key
            reportHash = generateReportHash();

            // Load saved state
            const savedState = safeGetItem('adpeas-completed-' + reportHash);
            if (savedState) {
                try {
                    completedFindings = JSON.parse(savedState);
                } catch (e) {
                    completedFindings = {};
                }
            }

            // Initialize checkboxes on all finding cards (checkbox is already in HTML)
            document.querySelectorAll('.finding-card').forEach((card, index) => {
                // Use existing data-card-id (set by PowerShell) or generate fallback
                const cardId = card.dataset.cardId || ('finding-' + index);
                card.dataset.cardId = cardId;  // Ensure it's set if missing

                // Find existing checkbox and initialize it
                const checkbox = card.querySelector('.finding-checkbox');
                if (checkbox) {
                    checkbox.checked = !!completedFindings[cardId];
                    // Re-bind onclick to ensure proper cardId reference
                    checkbox.onclick = function(e) {
                        e.stopPropagation();
                        toggleCompleted(cardId, this.checked);
                    };
                }

                // Apply initial state
                if (completedFindings[cardId]) {
                    card.classList.add('completed');
                }
            });

            // Update progress bar
            updateProgress();

            // Load hide completed state
            const hideCompleted = safeGetItem('adpeas-hide-completed') === 'true';
            if (hideCompleted) {
                document.getElementById('hideCompletedToggle').checked = true;
                document.body.classList.add('hide-completed');
            }
        }

        function generateReportHash() {
            // Generate hash based on domain, timestamp, and finding titles for uniqueness
            // This ensures different reports don't share completed-state even if same domain/count
            const infoItems = document.querySelectorAll('.info-item');
            let domain = 'unknown';
            let generated = '';

            infoItems.forEach(item => {
                const label = item.querySelector('.label')?.textContent?.trim();
                const value = item.querySelector('.value')?.textContent?.trim();
                if (label === 'Domain') domain = value || 'unknown';
                if (label === 'Generated') generated = value || '';
            });

            // Include first 3 finding titles for additional uniqueness
            const titles = Array.from(document.querySelectorAll('.finding-title'))
                .slice(0, 3)
                .map(t => t.textContent || '')
                .join('');

            const hashInput = domain + generated + titles;
            // Simple hash function
            let hash = 0;
            for (let i = 0; i < hashInput.length; i++) {
                const char = hashInput.charCodeAt(i);
                hash = ((hash << 5) - hash) + char;
                hash = hash & hash; // Convert to 32bit integer
            }
            return domain.replace(/[^a-z0-9]/gi, '') + '-' + Math.abs(hash).toString(36);
        }

        function toggleCompleted(cardId, isCompleted) {
            if (isCompleted) {
                completedFindings[cardId] = true;
            } else {
                delete completedFindings[cardId];
            }

            // Update Card View UI
            const card = document.querySelector(`.finding-card[data-card-id="${cardId}"]`);
            if (card) {
                card.classList.toggle('completed', isCompleted);
            }

            // Save state
            safeSetItem('adpeas-completed-' + reportHash, JSON.stringify(completedFindings));

            // Update progress bar
            updateProgress();

            // Re-apply filters (if hide completed is enabled)
            if (hideCompletedEnabled) {
                applyFilters();
            }
        }

        function updateProgress() {
            // Update sidebar counts to show remaining (non-completed) findings
            updateSidebarCounts();
        }

        function updateSidebarCounts() {
            // Count non-completed cards per severity and category
            const severityCounts = { all: 0, finding: 0, hint: 0, note: 0, secure: 0 };
            const categoryCounts = {};

            document.querySelectorAll('.finding-card').forEach(card => {
                const cardId = card.dataset.cardId;
                const isCompleted = completedFindings[cardId];

                if (!isCompleted) {
                    severityCounts.all++;
                    const severity = card.dataset.severity || 'note';
                    if (severityCounts[severity] !== undefined) {
                        severityCounts[severity]++;
                    }

                    // Count by category
                    const category = card.dataset.category || '';
                    if (category) {
                        categoryCounts[category] = (categoryCounts[category] || 0) + 1;
                    }
                }
            });

            // Update sidebar severity filter counts
            document.querySelectorAll('.severity-filter').forEach(filter => {
                const severity = filter.dataset.severity;
                const countSpan = filter.querySelector('.count');
                if (countSpan && severityCounts[severity] !== undefined) {
                    countSpan.textContent = severityCounts[severity];
                }
            });

            // Update sidebar category filter counts
            document.querySelectorAll('.nav-item[data-category]').forEach(navItem => {
                const category = navItem.dataset.category;
                const countSpan = navItem.querySelector('.count');
                if (countSpan) {
                    if (category === 'all') {
                        countSpan.textContent = severityCounts.all;
                    } else if (categoryCounts[category] !== undefined) {
                        countSpan.textContent = categoryCounts[category];
                    } else {
                        countSpan.textContent = '0';
                    }
                }
            });

            // Update summary cards at the top
            const summaryMapping = {
                'finding': '.summary-card.finding .value',
                'hint': '.summary-card.hint .value',
                'note': '.summary-card.note .value',
                'secure': '.summary-card.secure .value'
            };

            Object.keys(summaryMapping).forEach(severity => {
                const el = document.querySelector(summaryMapping[severity]);
                if (el) {
                    el.textContent = severityCounts[severity];
                }
            });
        }

        function toggleHideCompleted() {
            const isChecked = document.getElementById('hideCompletedToggle').checked;
            hideCompletedEnabled = isChecked;
            document.body.classList.toggle('hide-completed', isChecked);
            safeSetItem('adpeas-hide-completed', isChecked);
            // Re-apply filters
            applyFilters();

            // Announce to screen readers
            const visibleCount = document.querySelectorAll('.finding-card:not([style*="display: none"])').length;
            const message = isChecked
                ? 'Completed findings hidden. ' + visibleCount + ' findings visible.'
                : 'Showing all findings including completed. ' + visibleCount + ' findings visible.';
            announceToScreenReader(message);
        }

        // ============================================================
        // KEYBOARD SHORTCUTS
        // ============================================================

        let currentFocusIndex = -1;
        let visibleCards = [];

        function initKeyboardShortcuts() {
            document.addEventListener('keydown', function(e) {
                // Don't trigger shortcuts when typing in search
                if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
                    if (e.key === 'Escape') {
                        // Clear search filter if the search input has a value
                        if (e.target.id === 'searchInput' && e.target.value) {
                            e.target.value = '';
                            currentSearchQuery = '';
                            applyFilters();
                        }
                        e.target.blur();
                        clearKeyboardFocus();
                    }
                    return;
                }

                switch(e.key) {
                    // Navigation: Arrow keys (intuitive)
                    case 'ArrowDown':
                        e.preventDefault();
                        navigateFinding(1);
                        break;
                    case 'ArrowUp':
                        e.preventDefault();
                        navigateFinding(-1);
                        break;

                    // Enter: Expand/Collapse
                    case 'Enter':
                        e.preventDefault();
                        if (currentFocusIndex >= 0) {
                            toggleCurrentFinding();
                        }
                        break;

                    // Toggle completed: Space (standard checkbox behavior)
                    case ' ':
                        e.preventDefault();
                        if (currentFocusIndex >= 0 && visibleCards[currentFocusIndex]) {
                            const card = visibleCards[currentFocusIndex];
                            const checkbox = card.querySelector('.finding-checkbox');
                            if (checkbox) {
                                checkbox.checked = !checkbox.checked;
                                toggleCompleted(card.dataset.cardId, checkbox.checked);
                            }
                        }
                        break;

                    // Search: / (vim-like, common in web apps)
                    case '/':
                        e.preventDefault();
                        document.getElementById('searchInput').focus();
                        break;

                    // Hide completed toggle: h
                    case 'h':
                        e.preventDefault();
                        const toggle = document.getElementById('hideCompletedToggle');
                        toggle.checked = !toggle.checked;
                        toggleHideCompleted();
                        break;

                    // Help: ? or F1
                    case '?':
                        e.preventDefault();
                        toggleShortcutHelp();
                        break;
                    case 'F1':
                        e.preventDefault();
                        toggleShortcutHelp();
                        break;

                    // Close/Cancel: Escape (standard)
                    case 'Escape':
                        hideTooltip();
                        hideCheckTooltip();
                        hideShortcutHelp();
                        clearKeyboardFocus();
                        break;
                }
            });
        }

        function getVisibleCards() {
            return Array.from(document.querySelectorAll('.finding-card')).filter(card => {
                return card.style.display !== 'none' && !card.closest('.section[style*="display: none"]');
            });
        }

        function navigateFinding(direction) {
            visibleCards = getVisibleCards();
            if (visibleCards.length === 0) return;

            // Remove visual focus from previous card (don't reset index)
            document.querySelectorAll('.keyboard-focused').forEach(el => {
                el.classList.remove('keyboard-focused');
            });

            // Calculate new index
            currentFocusIndex += direction;
            if (currentFocusIndex < 0) currentFocusIndex = visibleCards.length - 1;
            if (currentFocusIndex >= visibleCards.length) currentFocusIndex = 0;

            // Apply focus
            const card = visibleCards[currentFocusIndex];
            card.classList.add('keyboard-focused');
            card.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        function clearKeyboardFocus() {
            document.querySelectorAll('.keyboard-focused').forEach(el => {
                el.classList.remove('keyboard-focused');
            });
            currentFocusIndex = -1;
        }

        function toggleCurrentFinding() {
            if (currentFocusIndex >= 0 && visibleCards[currentFocusIndex]) {
                visibleCards[currentFocusIndex].classList.toggle('expanded');
            }
        }

        let allExpanded = false;
        function toggleAllFindings() {
            allExpanded = !allExpanded;
            document.querySelectorAll('.finding-card').forEach(card => {
                card.classList.toggle('expanded', allExpanded);
            });
        }

