        // Clear all adPEAS data from localStorage
        function clearAdPEASData() {
            const keys = Object.keys(localStorage).filter(k => k.startsWith('adpeas-'));
            const count = keys.length;

            if (count === 0) {
                announceToScreenReader('No adPEAS data found in storage.');
                alert('No adPEAS data found in browser storage.');
                return;
            }

            const confirmMsg = 'This will remove all adPEAS data from your browser:\n\n' +
                '• Completed findings (checkboxes) for ALL reports\n' +
                '• Theme preference\n\n' +
                'Found ' + count + ' stored item(s).\n\n' +
                'The page will reload after clearing. Continue?';

            if (confirm(confirmMsg)) {
                keys.forEach(k => localStorage.removeItem(k));
                announceToScreenReader('All adPEAS data cleared. Reloading page.');
                location.reload();
            }
        }

        function toggleShortcutHelp() {
            const backdrop = document.getElementById('shortcutBackdrop');
            const modal = document.getElementById('shortcutHelp');
            const isOpening = !modal.classList.contains('visible');

            backdrop.classList.toggle('visible');
            modal.classList.toggle('visible');

            if (isOpening) {
                // Focus trap and announce
                trapFocus(modal);
                announceToScreenReader('Help dialog opened. Press Escape to close.');
            } else {
                restoreFocus();
            }
        }

        function hideShortcutHelp() {
            document.getElementById('shortcutBackdrop').classList.remove('visible');
            document.getElementById('shortcutHelp').classList.remove('visible');
            restoreFocus();
        }

        // ============================================================
        // TOP PRIORITY ACTIONS with Context-Aware Risk Scoring
        // ============================================================

        // ==========================================================================
        // CONTEXT-AWARE SCORING SYSTEM
        // ==========================================================================
        // Score = BASE_SCORE * IMPACT_MODIFIER * EXPLOITABILITY_MODIFIER * SECURITY_MODIFIER + CORRELATION
        //
        // Definitions are maintained centrally in: src/modules/Core/adPEAS-ScoringDefinitions.ps1
        // Documentation: docs/10-Risk-Scoring-System.md
        // ==========================================================================

        // ---- BEGIN AUTO-GENERATED SCORING DEFINITIONS ----
        // Source: adPEAS-ScoringDefinitions.ps1
{{SCORING_DEFINITIONS}}
        // ---- END AUTO-GENERATED SCORING DEFINITIONS ----

        // Exploitability modifiers for cracking-based attacks
        // Uses values from securityModifiers, passwordAgeModifiers, passwordLengthModifiers, etc.
        function getExploitabilityModifier(accountInfo, findingType) {
            let modifier = 1.0;

            // Only apply these modifiers to attacks that require cracking
            const crackingAttacks = ['kerberoast', 'asrep', 'preauth'];
            const isCrackingAttack = crackingAttacks.some(a => findingType.includes(a));

            if (!isCrackingAttack || !accountInfo) {
                return modifier;
            }

            // Get domain password policy for context-aware age evaluation
            const maxPwdAgeDays = scoringContext?.domainInfo?.maxPwdAgeDays || 0;
            const minPwdLength = scoringContext?.domainInfo?.minPwdLength || 0;

            // Password age factor - relative to policy, not absolute
            if (accountInfo.pwdAgeDays !== null && accountInfo.pwdAgeDays > 0) {
                const pwdAge = accountInfo.pwdAgeDays;

                if (maxPwdAgeDays > 0) {
                    // Policy exists - evaluate relative to policy
                    const policyMultiples = pwdAge / maxPwdAgeDays;

                    if (policyMultiples >= 10) {
                        modifier *= passwordAgeModifiers.multiplier_10x;
                    } else if (policyMultiples >= 5) {
                        modifier *= passwordAgeModifiers.multiplier_5x;
                    } else if (policyMultiples >= 3) {
                        modifier *= passwordAgeModifiers.multiplier_3x;
                    } else if (policyMultiples >= 2) {
                        modifier *= passwordAgeModifiers.multiplier_2x;
                    } else if (policyMultiples >= 1) {
                        modifier *= passwordAgeModifiers.multiplier_1x;
                    } else {
                        modifier *= passwordAgeModifiers.within_policy;
                    }
                } else {
                    // No policy (never expires) - use absolute thresholds
                    if (pwdAge > 365 * 5) {
                        modifier *= passwordAgeModifiers.multiplier_5x;
                    } else if (pwdAge > 365 * 2) {
                        modifier *= passwordAgeModifiers.multiplier_2x;
                    } else if (pwdAge > 365) {
                        modifier *= passwordAgeModifiers.multiplier_1x;
                    }
                }
            }

            // Password policy strength affects cracking difficulty
            const complexityEnabled = scoringContext?.domainInfo?.complexityEnabled || false;

            // Password length impact on cracking time
            if (minPwdLength > 0) {
                if (minPwdLength < 8) {
                    modifier *= passwordLengthModifiers.very_weak;
                } else if (minPwdLength < 12) {
                    modifier *= passwordLengthModifiers.weak;
                } else if (minPwdLength < 16) {
                    modifier *= passwordLengthModifiers.standard;
                } else {
                    modifier *= passwordLengthModifiers.strong;
                }
            }

            // Password complexity
            if (!complexityEnabled) {
                modifier *= passwordComplexityModifiers.disabled;
            } else {
                modifier *= passwordComplexityModifiers.enabled;
            }

            // Combined weak policy scenario (short + no complexity)
            if (minPwdLength > 0 && minPwdLength < 10 && !complexityEnabled) {
                modifier *= 1.15;  // Additional penalty for very weak combination
            }

            // Encryption type factor (RC4 = much easier to crack)
            if (accountInfo.encryptionTypes && accountInfo.encryptionTypes.length > 0) {
                const hasRC4Only = accountInfo.encryptionTypes.includes('RC4-HMAC') &&
                                   !accountInfo.encryptionTypes.includes('AES256') &&
                                   !accountInfo.encryptionTypes.includes('AES128');
                const hasAES = accountInfo.encryptionTypes.includes('AES256') ||
                               accountInfo.encryptionTypes.includes('AES128');

                if (hasRC4Only) {
                    modifier *= encryptionTypeModifiers.rc4_only;
                } else if (hasAES && !accountInfo.encryptionTypes.includes('RC4-HMAC')) {
                    modifier *= encryptionTypeModifiers.aes256;
                }
            }

            return modifier;
        }

        // Security configuration modifiers - REDUCE score for secure settings
        // Uses values from securityModifiers object
        function getSecurityModifier(accountInfo, findingType) {
            if (!accountInfo || !accountInfo.uacFlags) {
                return 1.0;
            }

            let modifier = 1.0;
            const flags = accountInfo.uacFlags;
            const isCrackingAttack = ['kerberoast', 'asrep', 'preauth'].some(a => findingType.includes(a));
            const isCredentialAttack = ['credential', 'password', 'gpp', 'autoadmin'].some(a => findingType.includes(a));

            // ========================================
            // ACCOUNT STATUS FLAGS (affect ALL attacks)
            // ========================================

            if (flags.includes('ACCOUNTDISABLE') || flags.includes('Disabled')) {
                modifier *= securityModifiers.ACCOUNTDISABLE;
            }

            if (flags.includes('LOCKOUT') || flags.includes('Locked')) {
                modifier *= securityModifiers.LOCKOUT;
            }

            // ========================================
            // KERBEROS SECURITY FLAGS (affect cracking attacks)
            // ========================================

            if (isCrackingAttack) {
                if (flags.includes('SMARTCARD_REQUIRED') || flags.includes('SmartcardRequired')) {
                    modifier *= securityModifiers.SMARTCARD_REQUIRED;
                }

                if (accountInfo.isProtectedUser) {
                    modifier *= securityModifiers.PROTECTED_USERS;
                }
            }

            // ========================================
            // DELEGATION FLAGS (affect delegation attacks)
            // ========================================

            const isDelegationAttack = ['delegation', 'rbcd', 'constrained', 'unconstrained'].some(a => findingType.includes(a));

            if (isDelegationAttack) {
                if (flags.includes('NOT_DELEGATED') || flags.includes('NotDelegated') ||
                    flags.includes('AccountNotDelegated') || flags.includes('Sensitive')) {
                    modifier *= securityModifiers.NOT_DELEGATED;
                }
            }

            // ========================================
            // PASSWORD FLAGS (affect credential attacks)
            // ========================================

            if (isCrackingAttack || isCredentialAttack) {
                if (flags.includes('PASSWORD_EXPIRED') || flags.includes('PasswordExpired')) {
                    modifier *= securityModifiers.PASSWORD_EXPIRED;
                }
            }

            // ========================================
            // ENCRYPTION FLAGS (affect Kerberoast specifically)
            // ========================================

            if (flags.includes('USE_DES_KEY_ONLY') || flags.includes('DESKeyOnly')) {
                modifier *= securityModifiers.USE_DES_KEY_ONLY;
            }

            return modifier;
        }

        // Get account info from scoring context
        function getAccountInfoFromCard(card) {
            if (!scoringContext || !scoringContext.accounts) {
                return null;
            }

            // Try to find account by extracting identifiers from card content
            const objectDetails = card.querySelectorAll('.object-detail');
            for (const detail of objectDetails) {
                // Look for sAMAccountName or distinguishedName in the card
                const rows = detail.querySelectorAll('.attr-row');
                for (const row of rows) {
                    const nameEl = row.querySelector('.attr-name');
                    const valueEl = row.querySelector('.attr-value');
                    if (!nameEl || !valueEl) continue;

                    const attrName = nameEl.textContent.trim().toLowerCase();
                    const attrValue = valueEl.textContent.trim();

                    // Match by objectSid first (most reliable)
                    if (attrName === 'objectsid' && scoringContext.accounts[attrValue]) {
                        return scoringContext.accounts[attrValue];
                    }
                    // Match by DN
                    if (attrName === 'distinguishedname' && scoringContext.accounts[attrValue]) {
                        return scoringContext.accounts[attrValue];
                    }
                    // Match by sAMAccountName (iterate through accounts)
                    if (attrName === 'samaccountname') {
                        for (const [key, acct] of Object.entries(scoringContext.accounts)) {
                            if (acct.name && acct.name.toLowerCase() === attrValue.toLowerCase()) {
                                return acct;
                            }
                        }
                    }
                }
            }
            return null;
        }

        // Check if account appears in multiple risky findings (correlation bonus)
        // Uses values from correlationBonus object
        // Non-admin accounts get ENHANCED correlation bonus - they represent potential attack paths
        function getCorrelationBonus(accountInfo) {
            if (!scoringContext || !scoringContext.correlations || !accountInfo) {
                return 0;
            }

            // Find correlations for this account
            const accountId = accountInfo.sid || accountInfo.dn || accountInfo.name;
            const correlation = scoringContext.correlations[accountId];

            if (!correlation) {
                return 0;
            }

            // Determine if this is a non-admin account
            const isNonAdmin = !accountInfo.isAdmin && accountInfo.adminTier === 'none';

            let bonus = 0;

            // Dangerous combinations get max bonus
            if (correlation.hasDCSync && (correlation.hasKerberoast || correlation.hasASREP)) {
                bonus = isNonAdmin ? correlationBonus.nonAdminMaxBonus : correlationBonus.maxBonus;
            } else if (correlation.hasDelegation && correlation.hasKerberoast) {
                const perFinding = isNonAdmin ? correlationBonus.nonAdminPerFinding : correlationBonus.perFinding;
                const maxBonus = isNonAdmin ? correlationBonus.nonAdminMaxBonus : correlationBonus.maxBonus;
                bonus = Math.min(perFinding * 2, maxBonus);
            } else if (correlation.count >= 2) {
                // Non-admin with 3+ findings = enhanced bonus (potential privilege escalation path)
                if (isNonAdmin && correlation.count >= correlationBonus.nonAdminThreshold) {
                    // Enhanced correlation for non-admins appearing in multiple findings
                    bonus = Math.min((correlation.count - 1) * correlationBonus.nonAdminPerFinding, correlationBonus.nonAdminMaxBonus);
                } else {
                    // Standard correlation for admins or non-admins below threshold
                    bonus = Math.min((correlation.count - 1) * correlationBonus.perFinding, correlationBonus.maxBonus);
                }
            }

            return bonus;
        }

        // Calculate score with full breakdown for transparency
        function calculateFindingScoreWithBreakdown(card) {
            const severity = card.dataset.severity || 'note';
            const breakdown = {
                severity: severity,
                baseScore: 0,
                matchedPattern: null,
                impactMod: 1.0,
                impactReason: 'Standard',
                exploitMod: 1.0,
                exploitReasons: [],
                securityMod: 1.0,
                securityReasons: [],
                correlationBonus: 0,
                correlationReason: null,
                finalScore: 0
            };

            // Note and Secure = no security issue
            if (severity === 'note' || severity === 'secure') {
                breakdown.baseScore = 0;
                breakdown.finalScore = 0;
                return breakdown;
            }

            // HINT severity = informational findings
            if (severity === 'hint') {
                breakdown.baseScore = severityBaseScores['hint'] || 15;
                breakdown.finalScore = breakdown.baseScore;
                breakdown.matchedPattern = 'hint (informational)';
                return breakdown;
            }

            // Get finding title
            const title = (card.querySelector('.finding-title')?.textContent || '').toLowerCase();

            // 1. Determine BASE score from finding type
            breakdown.baseScore = severityBaseScores[severity] || 5;

            for (const [pattern, score] of Object.entries(findingBaseScores)) {
                if (title.includes(pattern.toLowerCase())) {
                    if (score > breakdown.baseScore) {
                        breakdown.baseScore = score;
                        breakdown.matchedPattern = pattern;
                    }
                }
            }

            // DCSync/Replication Rights are ALWAYS maximum
            if (breakdown.matchedPattern === 'dcsync' || breakdown.matchedPattern === 'replication rights') {
                breakdown.finalScore = 100;
                breakdown.impactReason = 'Maximum (DCSync)';
                return breakdown;
            }

            // 2. Get account context
            const accountInfo = getAccountInfoFromCard(card);

            // 3. Apply IMPACT modifier
            if (accountInfo && accountInfo.adminTier) {
                breakdown.impactMod = impactMultipliers[accountInfo.adminTier] || impactMultipliers.none;
                const tierNames = { tier0: 'Tier 0 (Domain Admin)', tier1: 'Tier 1 (Server Admin)', tier2: 'Tier 2 (Workstation Admin)', none: 'Non-Admin' };
                breakdown.impactReason = tierNames[accountInfo.adminTier] || 'Standard';
            }

            // 4. Apply EXPLOITABILITY modifier with reasons
            breakdown.exploitMod = getExploitabilityModifier(accountInfo, title);
            if (accountInfo) {
                if (accountInfo.pwdAgeDays > 365) {
                    breakdown.exploitReasons.push('Old password (' + Math.round(accountInfo.pwdAgeDays / 365) + 'y)');
                }
                if (accountInfo.encryptionTypes && accountInfo.encryptionTypes.includes('RC4-HMAC') && !accountInfo.encryptionTypes.includes('AES256')) {
                    breakdown.exploitReasons.push('RC4 encryption');
                }
            }
            if (breakdown.exploitReasons.length === 0 && breakdown.exploitMod !== 1.0) {
                breakdown.exploitReasons.push(breakdown.exploitMod > 1 ? 'Easier to exploit' : 'Harder to exploit');
            }

            // 5. Apply SECURITY modifier with reasons
            breakdown.securityMod = getSecurityModifier(accountInfo, title);
            if (accountInfo && accountInfo.uacFlags) {
                const flags = accountInfo.uacFlags;
                if (flags.includes('ACCOUNTDISABLE') || flags.includes('Disabled')) {
                    breakdown.securityReasons.push('Disabled');
                }
                if (flags.includes('SMARTCARD_REQUIRED') || flags.includes('SmartcardRequired')) {
                    breakdown.securityReasons.push('Smartcard required');
                }
                if (accountInfo.isProtectedUser) {
                    breakdown.securityReasons.push('Protected Users');
                }
            }
            if (breakdown.securityReasons.length === 0 && breakdown.securityMod !== 1.0) {
                breakdown.securityReasons.push(breakdown.securityMod < 1 ? 'Mitigated' : 'Vulnerable');
            }

            // 6. Add correlation bonus
            breakdown.correlationBonus = getCorrelationBonus(accountInfo);
            if (breakdown.correlationBonus > 0) {
                breakdown.correlationReason = 'Appears in multiple findings';
            }

            // Calculate final score
            let rawScore = Math.round(breakdown.baseScore * breakdown.impactMod * breakdown.exploitMod * breakdown.securityMod) + breakdown.correlationBonus;
            breakdown.finalScore = Math.min(Math.max(rawScore, 0), 100);

            return breakdown;
        }

        // Simple wrapper for backwards compatibility
        function calculateFindingScore(card) {
            return calculateFindingScoreWithBreakdown(card).finalScore;
        }

        // Format score breakdown as tooltip text
        function formatScoreBreakdown(breakdown) {
            if (breakdown.finalScore === 0) {
                return 'No risk score (informational)';
            }

            let lines = [];
            lines.push('Score Breakdown:');
            lines.push('─────────────────');
            lines.push('Base: ' + breakdown.baseScore + (breakdown.matchedPattern ? ' (' + breakdown.matchedPattern + ')' : ''));

            if (breakdown.impactMod !== 1.0) {
                lines.push('Impact: ×' + breakdown.impactMod.toFixed(2) + ' (' + breakdown.impactReason + ')');
            }

            if (breakdown.exploitMod !== 1.0) {
                const reasons = breakdown.exploitReasons.length > 0 ? breakdown.exploitReasons.join(', ') : '';
                lines.push('Exploitability: ×' + breakdown.exploitMod.toFixed(2) + (reasons ? ' (' + reasons + ')' : ''));
            }

            if (breakdown.securityMod !== 1.0) {
                const reasons = breakdown.securityReasons.length > 0 ? breakdown.securityReasons.join(', ') : '';
                lines.push('Security: ×' + breakdown.securityMod.toFixed(2) + (reasons ? ' (' + reasons + ')' : ''));
            }

            if (breakdown.correlationBonus > 0) {
                lines.push('Correlation: +' + breakdown.correlationBonus + (breakdown.correlationReason ? ' (' + breakdown.correlationReason + ')' : ''));
            }

            lines.push('─────────────────');
            lines.push('Final: ' + breakdown.finalScore);

            return lines.join('\n');
        }

        // Format score breakdown as styled HTML tooltip content
        function formatScoreBreakdownHtml(breakdown) {
            if (breakdown.finalScore === 0) {
                return `
                    <div class="score-tooltip-header">
                        <span class="score-tooltip-title">Score Breakdown</span>
                        <span class="score-tooltip-final info">0</span>
                    </div>
                    <div class="score-tooltip-body">
                        <div class="score-tooltip-row">
                            <span class="score-tooltip-label">No risk score (informational)</span>
                        </div>
                    </div>
                `;
            }

            const scoreClass = breakdown.finalScore >= scoreThresholds.critical ? 'critical' :
                               breakdown.finalScore >= scoreThresholds.high ? 'high' :
                               breakdown.finalScore >= scoreThresholds.medium ? 'medium' :
                               breakdown.finalScore >= scoreThresholds.low ? 'low' : 'info';

            let rowsHtml = '';

            // Base Score
            rowsHtml += `
                <div class="score-tooltip-row">
                    <span class="score-tooltip-label">Base Score${breakdown.matchedPattern ? `<span class="reason">${escapeHtml(breakdown.matchedPattern)}</span>` : ''}</span>
                    <span class="score-tooltip-value positive">${breakdown.baseScore}</span>
                </div>
            `;

            // Impact Modifier
            if (breakdown.impactMod !== 1.0) {
                rowsHtml += `
                    <div class="score-tooltip-row">
                        <span class="score-tooltip-label">Impact<span class="reason">${escapeHtml(breakdown.impactReason)}</span></span>
                        <span class="score-tooltip-value modifier">×${breakdown.impactMod.toFixed(2)}</span>
                    </div>
                `;
            }

            // Exploitability Modifier
            if (breakdown.exploitMod !== 1.0) {
                const reasons = breakdown.exploitReasons.length > 0 ? breakdown.exploitReasons.join(', ') : '';
                rowsHtml += `
                    <div class="score-tooltip-row">
                        <span class="score-tooltip-label">Exploitability${reasons ? `<span class="reason">${escapeHtml(reasons)}</span>` : ''}</span>
                        <span class="score-tooltip-value modifier">×${breakdown.exploitMod.toFixed(2)}</span>
                    </div>
                `;
            }

            // Security Modifier
            if (breakdown.securityMod !== 1.0) {
                const reasons = breakdown.securityReasons.length > 0 ? breakdown.securityReasons.join(', ') : '';
                rowsHtml += `
                    <div class="score-tooltip-row">
                        <span class="score-tooltip-label">Security${reasons ? `<span class="reason">${escapeHtml(reasons)}</span>` : ''}</span>
                        <span class="score-tooltip-value modifier">×${breakdown.securityMod.toFixed(2)}</span>
                    </div>
                `;
            }

            // Correlation Bonus
            if (breakdown.correlationBonus > 0) {
                rowsHtml += `
                    <div class="score-tooltip-row">
                        <span class="score-tooltip-label">Correlation${breakdown.correlationReason ? `<span class="reason">${escapeHtml(breakdown.correlationReason)}</span>` : ''}</span>
                        <span class="score-tooltip-value positive">+${breakdown.correlationBonus}</span>
                    </div>
                `;
            }

            return `
                <div class="score-tooltip-header">
                    <span class="score-tooltip-title">Score Breakdown</span>
                    <span class="score-tooltip-final ${scoreClass}">${breakdown.finalScore}</span>
                </div>
                <div class="score-tooltip-body">
                    ${rowsHtml}
                </div>
            `;
        }

        // Active score tooltip reference
        let activeScoreTooltip = null;

        // Initialize score tooltips for styled display
        function initScoreTooltips() {
            // Create tooltip container
            const tooltipDiv = document.createElement('div');
            tooltipDiv.id = 'scoreTooltip';
            tooltipDiv.className = 'score-tooltip';
            tooltipDiv.setAttribute('role', 'tooltip');
            document.body.appendChild(tooltipDiv);

            // Close tooltip when clicking outside
            document.addEventListener('click', function(e) {
                if (activeScoreTooltip && !e.target.closest('.score-tooltip') && !e.target.closest('[data-score-breakdown]')) {
                    closeScoreTooltip();
                }
            });

            // Close on Escape key
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && activeScoreTooltip) {
                    closeScoreTooltip();
                }
            });
        }

        function showScoreTooltip(trigger, breakdown) {
            const tooltip = document.getElementById('scoreTooltip');
            if (!tooltip) return;

            // Close any previously open tooltip first
            if (activeScoreTooltip) {
                closeScoreTooltip();
            }

            // Build tooltip HTML
            tooltip.innerHTML = formatScoreBreakdownHtml(breakdown);

            // Make visible for positioning measurement
            tooltip.style.visibility = 'hidden';
            tooltip.classList.add('visible');

            // Position tooltip
            positionScoreTooltip(tooltip, trigger);

            // Show tooltip
            tooltip.style.visibility = 'visible';
            activeScoreTooltip = tooltip;
        }

        function closeScoreTooltip() {
            const tooltip = document.getElementById('scoreTooltip');
            if (tooltip) {
                tooltip.classList.remove('visible');
            }
            activeScoreTooltip = null;
        }

        function positionScoreTooltip(tooltip, trigger) {
            const triggerRect = trigger.getBoundingClientRect();
            const tooltipRect = tooltip.getBoundingClientRect();
            const viewportWidth = window.innerWidth;
            const viewportHeight = window.innerHeight;
            const padding = UI_CONSTANTS.VIEWPORT_PADDING;

            // Default: position below the trigger, centered
            let left = triggerRect.left + (triggerRect.width / 2) - (tooltipRect.width / 2);
            let top = triggerRect.bottom + 8;

            // Adjust horizontal position if tooltip would overflow
            if (left < padding) {
                left = padding;
            } else if (left + tooltipRect.width > viewportWidth - padding) {
                left = viewportWidth - tooltipRect.width - padding;
            }

            // If tooltip would overflow bottom, position above trigger
            if (top + tooltipRect.height > viewportHeight - padding) {
                top = triggerRect.top - tooltipRect.height - 8;
            }

            // Ensure not above viewport
            if (top < padding) {
                top = padding;
            }

            tooltip.style.left = left + 'px';
            tooltip.style.top = top + 'px';
        }

        // Calculate score from finding metadata (JSON-based, no DOM traversal)
        function calculateScoreFromMetadata(findingMeta) {
            const severity = findingMeta.severity || 'note';
            const breakdown = {
                severity: severity,
                baseScore: 0,
                matchedPattern: null,
                impactMod: 1.0,
                impactReason: 'Standard',
                exploitMod: 1.0,
                exploitReasons: [],
                securityMod: 1.0,
                securityReasons: [],
                correlationBonus: 0,
                correlationReason: null,
                finalScore: 0
            };

            // Note and Secure = no security issue
            if (severity === 'note' || severity === 'secure') {
                return breakdown;
            }

            // HINT severity = informational findings
            if (severity === 'hint') {
                breakdown.baseScore = severityBaseScores['hint'] || 15;
                breakdown.finalScore = breakdown.baseScore;
                breakdown.matchedPattern = 'hint (informational)';
                return breakdown;
            }

            // Get finding title
            const title = (findingMeta.title || '').toLowerCase();

            // 1. Determine BASE score from finding type
            breakdown.baseScore = severityBaseScores[severity] || 5;

            for (const [pattern, score] of Object.entries(findingBaseScores)) {
                if (title.includes(pattern.toLowerCase())) {
                    if (score > breakdown.baseScore) {
                        breakdown.baseScore = score;
                        breakdown.matchedPattern = pattern;
                    }
                }
            }

            // 1b. Check vulnerability tags (e.g., ADCS ESC1, ESC4) against findingBaseScores
            // When the card title (e.g., "Certificate Templates") doesn't match,
            // but objects contain vulnerability tags, use the highest matching score
            if (findingMeta.vulnerabilities && findingMeta.vulnerabilities.length > 0) {
                for (const vulnTag of findingMeta.vulnerabilities) {
                    const vulnLower = vulnTag.toLowerCase();
                    for (const [pattern, score] of Object.entries(findingBaseScores)) {
                        // Match "esc1" against FindingID keys like "esc1_template", "esc1_vulnerable_..."
                        if (pattern.toLowerCase().startsWith(vulnLower + '_') || pattern.toLowerCase() === vulnLower) {
                            if (score > breakdown.baseScore) {
                                breakdown.baseScore = score;
                                breakdown.matchedPattern = pattern + ' (via ' + vulnTag + ')';
                            }
                        }
                    }
                }
            }

            // DCSync/Replication Rights are ALWAYS maximum
            if (breakdown.matchedPattern && (breakdown.matchedPattern.startsWith('dcsync') || breakdown.matchedPattern.startsWith('replication rights'))) {
                breakdown.finalScore = 100;
                breakdown.impactReason = 'Maximum (DCSync)';
                return breakdown;
            }

            // 2. Get account context from scoringContext using accountSID
            const accountInfo = findingMeta.accountSID ? scoringContext?.accounts?.[findingMeta.accountSID] : null;

            // 3. Apply IMPACT modifier
            if (accountInfo && accountInfo.adminTier) {
                breakdown.impactMod = impactMultipliers[accountInfo.adminTier] || impactMultipliers.none;
                const tierNames = { tier0: 'Tier 0 (Domain Admin)', tier1: 'Tier 1 (Server Admin)', tier2: 'Tier 2 (Workstation Admin)', none: 'Non-Admin' };
                breakdown.impactReason = tierNames[accountInfo.adminTier] || 'Standard';
            }

            // 4. Apply EXPLOITABILITY modifier with reasons
            breakdown.exploitMod = getExploitabilityModifier(accountInfo, title);
            if (accountInfo) {
                if (accountInfo.pwdAgeDays > 365) {
                    breakdown.exploitReasons.push('Old password (' + Math.round(accountInfo.pwdAgeDays / 365) + 'y)');
                }
                if (accountInfo.encryptionTypes && accountInfo.encryptionTypes.includes('RC4-HMAC') && !accountInfo.encryptionTypes.includes('AES256')) {
                    breakdown.exploitReasons.push('RC4 encryption');
                }
            }
            if (breakdown.exploitReasons.length === 0 && breakdown.exploitMod !== 1.0) {
                breakdown.exploitReasons.push(breakdown.exploitMod > 1 ? 'Easier to exploit' : 'Harder to exploit');
            }

            // 5. Apply SECURITY modifier with reasons
            breakdown.securityMod = getSecurityModifier(accountInfo, title);
            if (accountInfo && accountInfo.uacFlags) {
                const flags = accountInfo.uacFlags;
                if (flags.includes('ACCOUNTDISABLE') || flags.includes('Disabled')) {
                    breakdown.securityReasons.push('Disabled');
                }
                if (flags.includes('SMARTCARD_REQUIRED') || flags.includes('SmartcardRequired')) {
                    breakdown.securityReasons.push('Smartcard required');
                }
                if (accountInfo.isProtectedUser) {
                    breakdown.securityReasons.push('Protected Users');
                }
            }
            if (breakdown.securityReasons.length === 0 && breakdown.securityMod !== 1.0) {
                breakdown.securityReasons.push(breakdown.securityMod < 1 ? 'Mitigated' : 'Vulnerable');
            }

            // 6. Add correlation bonus
            breakdown.correlationBonus = getCorrelationBonus(accountInfo);
            if (breakdown.correlationBonus > 0) {
                breakdown.correlationReason = 'Appears in multiple findings';
            }

            // Calculate final score
            let rawScore = Math.round(breakdown.baseScore * breakdown.impactMod * breakdown.exploitMod * breakdown.securityMod) + breakdown.correlationBonus;
            breakdown.finalScore = Math.min(Math.max(rawScore, 0), 100);

            return breakdown;
        }

        // Find the best matching findingDefinition for a given finding card metadata
        // Priority: 0) ObjectType primaryFindingId, 1) findingIds from metadata, 2) vulnerability tags, 3) title keyword matching
        function findBestFindingDefinition(meta) {
            if (!findingDefinitions || !meta) return null;
            let bestKey = null;
            let bestScore = 0;

            // 0. ObjectType-level primary finding (highest authority — prevents incidental attribute
            //    triggers from overriding the card's actual topic)
            if (meta.objectType && checkDescriptions) {
                const checkInfo = checkDescriptions[meta.objectType];
                if (checkInfo?.primaryFindingId && findingDefinitions[checkInfo.primaryFindingId]) {
                    return findingDefinitions[checkInfo.primaryFindingId];
                }
            }

            // 1. Direct FindingId lookup (most reliable — from attribute trigger matching)
            if (meta.findingIds && meta.findingIds.length > 0) {
                for (const fid of meta.findingIds) {
                    if (findingDefinitions[fid]) {
                        const score = findingBaseScores[fid] || 0;
                        if (score > bestScore || !bestKey) {
                            bestScore = score;
                            bestKey = fid;
                        }
                    }
                }
            }

            // 2. Vulnerability tags (e.g., "ESC1" → "ESC1_TEMPLATE")
            if (!bestKey && meta.vulnerabilities && meta.vulnerabilities.length > 0) {
                for (const vulnTag of meta.vulnerabilities) {
                    const vulnLower = vulnTag.toLowerCase();
                    for (const [key, score] of Object.entries(findingBaseScores)) {
                        if (key.toLowerCase().startsWith(vulnLower + '_') || key.toLowerCase() === vulnLower) {
                            if (score > bestScore && findingDefinitions[key]) {
                                bestScore = score;
                                bestKey = key;
                            }
                        }
                    }
                }
            }

            // 3. Fallback: title keyword matching
            if (!bestKey) {
                const titleLower = (meta.title || '').toLowerCase();
                for (const [key, score] of Object.entries(findingBaseScores)) {
                    if (titleLower.includes(key.toLowerCase()) && score > bestScore && findingDefinitions[key]) {
                        bestScore = score;
                        bestKey = key;
                    }
                }
            }

            return bestKey ? findingDefinitions[bestKey] : null;
        }

        function generateTopPriorityActions() {
            const container = document.getElementById('topActionsContainer');
            if (!container) return;

            // ========== OPTIMIZED: Use JSON-based scoring if available ==========
            // This avoids DOM traversal for initial score calculation
            let scoredFindings = [];
            let totalCriticalCount = 0;

            if (scoringContext?.findingCards?.length > 0) {
                // NEW: JSON-based scoring (no DOM traversal needed)
                const criticalFindings = scoringContext.findingCards.filter(f => f.severity === 'finding');
                totalCriticalCount = criticalFindings.length;

                if (criticalFindings.length > 0) {
                    scoredFindings = criticalFindings.map((meta, idx) => {
                        const breakdown = calculateScoreFromMetadata(meta);
                        return {
                            meta: meta,
                            index: idx,
                            score: breakdown.finalScore,
                            breakdown: breakdown,
                            title: meta.title || 'Unknown Finding',
                            section: meta.section || meta.category || 'Unknown'
                        };
                    }).sort((a, b) => b.score - a.score);
                }
            } else {
                // FALLBACK: DOM-based scoring (legacy behavior)
                const allCards = Array.from(document.querySelectorAll('.finding-card'));
                const findingCards = allCards.filter(card => card.dataset.severity === 'finding');
                totalCriticalCount = findingCards.length;

                if (findingCards.length > 0) {
                    scoredFindings = findingCards.map((card, idx) => {
                        const breakdown = calculateFindingScoreWithBreakdown(card);
                        return {
                            card: card,
                            index: idx,
                            score: breakdown.finalScore,
                            breakdown: breakdown,
                            title: card.querySelector('.finding-title')?.textContent || 'Unknown Finding',
                            section: card.closest('.section')?.querySelector('.section-title')?.textContent || 'Unknown'
                        };
                    }).sort((a, b) => b.score - a.score);
                }
            }

            if (totalCriticalCount === 0) {
                // No critical findings - show success message
                container.innerHTML = `
                    <div class="top-actions" style="border-color: var(--note); background: linear-gradient(135deg, var(--note-bg) 0%, var(--bg-card) 100%);">
                        <div class="top-actions-header">
                            <div class="top-actions-title" style="color: var(--note);">
                                <span class="icon">&#10003;</span>
                                No Critical Findings
                            </div>
                        </div>
                        <p style="margin: 0; color: var(--text-muted);">No high-priority security issues were detected. Review the hints and notes for potential improvements.</p>
                    </div>
                `;
                return;
            }

            // Take top 3
            const top3 = scoredFindings.slice(0, 3);

            // Generate HTML
            let actionsHTML = `
                <div class="top-actions">
                    <div class="top-actions-header">
                        <div class="top-actions-title">
                            <span class="icon">&#9889;</span>
                            Top Priority Actions
                        </div>
                        <div style="display: flex; align-items: center; gap: 12px;">
                            <span style="font-size: 12px; color: var(--text-muted);">${totalCriticalCount} critical findings total</span>
                            <button class="top-actions-toggle" onclick="toggleTopActions()" title="Toggle Top Priority Actions">
                                <span class="toggle-icon">&#9660;</span>
                            </button>
                        </div>
                    </div>
                    <div class="top-actions-list">
            `;

            top3.forEach((item, index) => {
                // Resolve objectType and card ID from JSON metadata or DOM
                let cardId = '';
                let objectType = '';
                let checkTitle = item.title;

                if (item.meta) {
                    // JSON-based path: objectType from metadata
                    objectType = item.meta.objectType || '';
                    checkTitle = item.meta.title || item.title;
                } else if (item.card) {
                    // DOM-based fallback
                    cardId = item.card.dataset.cardId || '';
                    const checkHelpBtn = item.card.querySelector('.check-help-btn');
                    objectType = checkHelpBtn?.dataset.objectType || '';
                    checkTitle = checkHelpBtn?.dataset.checkTitle || item.title;
                }

                // Look up check description for professional title and impact text
                const checkInfo = (objectType && checkDescriptions) ? checkDescriptions[objectType] : null;

                // Professional title: checkDescriptions.title > internal check title
                const displayTitle = checkInfo?.title || item.title;

                // Impact description from checkDescriptions.whyItMatters
                const impactText = checkInfo?.whyItMatters || '';

                // Remediation from findingDefinitions (best match by findingIds/vulnerabilities/title)
                const findingDef = findBestFindingDefinition(item.meta || { title: item.title });
                const remediationText = findingDef?.remediation?.[0] || '';

                // Object count for "N affected" label
                const objectCount = item.meta?.objectCount || 0;

                // Build meta line: "N affected | Section"
                let metaHtml = '';
                if (objectCount > 0) {
                    metaHtml += `<span class="top-action-count">${objectCount} affected</span>`;
                }
                metaHtml += `<span class="top-action-section">${escapeHtml(item.section)}</span>`;

                // Build buttons HTML (info button + score badge)
                let buttonsHtml = '';
                if (checkInfo) {
                    buttonsHtml += `<button class="top-action-info-btn" onclick="event.stopPropagation(); showTopActionInfo(this, '${escapeHtml(objectType)}', '${escapeHtml(checkTitle)}')" data-object-type="${escapeHtml(objectType)}" data-check-title="${escapeHtml(checkTitle)}" title="More Info">?</button>`;
                }
                const scoreClass = item.score >= scoreThresholds.critical ? 'score-critical' : item.score >= scoreThresholds.high ? 'score-high' : item.score >= scoreThresholds.medium ? 'score-medium' : item.score >= scoreThresholds.low ? 'score-low' : 'score-info';
                const breakdownJson = escapeJsonForAttr(item.breakdown);
                buttonsHtml += `<span class="top-action-score ${scoreClass}" data-score-breakdown='${breakdownJson}' onclick="event.stopPropagation(); showScoreTooltip(this, JSON.parse(this.dataset.scoreBreakdown));" style="cursor: pointer;">${item.score}</span>`;

                // Build detail lines (impact + remediation)
                let detailsHtml = '';
                if (impactText) {
                    detailsHtml += `<div class="top-action-details">${escapeHtml(impactText)}</div>`;
                }
                if (remediationText) {
                    detailsHtml += `<div class="top-action-fix">&rarr; ${escapeHtml(remediationText)}</div>`;
                }

                actionsHTML += `
                    <div class="top-action-item" data-target-card="${cardId}" data-target-title="${escapeHtml(checkTitle)}" data-target-index="${item.index}" onclick="scrollToFindingCard(this)" style="cursor: pointer;">
                        <div class="top-action-rank">${index + 1}</div>
                        <div class="top-action-content">
                            <div class="top-action-title">${escapeHtml(displayTitle)}</div>
                            <div class="top-action-meta">${metaHtml}</div>
                            ${detailsHtml}
                        </div>
                        <div class="top-action-buttons" onclick="event.stopPropagation()">${buttonsHtml}</div>
                    </div>
                `;
            });

            actionsHTML += `
                    </div>
                </div>
            `;

            container.innerHTML = actionsHTML;
        }

        function scrollToFindingCard(element) {
            const cardId = element.dataset.targetCard;
            const targetTitle = element.dataset.targetTitle;
            const targetIndex = parseInt(element.dataset.targetIndex);

            let card = cardId ? document.querySelector('.finding-card[data-card-id="' + cardId + '"]') : null;

            // Second try: find by data-check-title
            if (!card && targetTitle) {
                const allCards = Array.from(document.querySelectorAll('.finding-card'));
                card = allCards.find(c => {
                    const helpBtn = c.querySelector('.check-help-btn');
                    return helpBtn && helpBtn.dataset.checkTitle === targetTitle;
                });
            }

            // Fallback: find by index among finding cards
            if (!card && targetIndex >= 0) {
                const findingCards = Array.from(document.querySelectorAll('.finding-card')).filter(c => c.dataset.severity === 'finding');
                card = findingCards[targetIndex];
            }

            if (!card) return;

            // Reset filters to ensure the card is visible
            currentSeverityFilter = 'all';
            currentCategoryFilter = 'all';
            currentSearchQuery = '';

            // Update filter UI
            document.querySelectorAll('.severity-filter').forEach(f => f.classList.remove('active'));
            document.querySelectorAll('.nav-item[data-category]').forEach(f => f.classList.remove('active'));
            const allSeverityFilter = document.querySelector('.severity-filter[data-severity="all"]');
            const allCategoryFilter = document.querySelector('.nav-item[data-category="all"]');
            if (allSeverityFilter) allSeverityFilter.classList.add('active');
            if (allCategoryFilter) allCategoryFilter.classList.add('active');
            const searchInput = document.getElementById('searchInput');
            if (searchInput) searchInput.value = '';

            // Apply filters to show all cards and sections
            applyFilters();

            // Ensure the card is visible
            card.style.display = '';

            // Collapse all other cards first, then expand only the target card
            document.querySelectorAll('.finding-card.expanded').forEach(c => c.classList.remove('expanded'));
            card.classList.add('expanded');

            // Highlight the category in the sidebar
            highlightCategoryForCard(card);

            // Remove any previous highlight
            document.querySelectorAll('.finding-card.keyboard-focused').forEach(c => c.classList.remove('keyboard-focused'));

            // Use setTimeout to ensure the DOM has fully updated after view switch + filter changes
            setTimeout(() => {
                card.scrollIntoView({ behavior: 'auto', block: 'start' });
                card.classList.add('keyboard-focused');
                setTimeout(() => card.classList.remove('keyboard-focused'), UI_CONSTANTS.KEYBOARD_FOCUS_DURATION);
            }, 150);
        }

        function showTopActionInfo(btn, objectType, checkTitle) {
            // Look up check description by ObjectType
            if (!objectType || !checkDescriptions[objectType]) return;
            const checkInfo = checkDescriptions[objectType];

            // Build tooltip content similar to check tooltip
            let content = '<div class="top-action-tooltip-content">';
            content += '<div class="top-action-tooltip-header">' + escapeHtml(checkTitle) + '</div>';

            if (checkInfo.summary) {
                content += '<div class="top-action-tooltip-section">';
                content += '<div class="top-action-tooltip-label">Summary</div>';
                content += '<div class="top-action-tooltip-text">' + escapeHtml(checkInfo.summary) + '</div>';
                content += '</div>';
            }

            if (checkInfo.whyItMatters) {
                content += '<div class="top-action-tooltip-section">';
                content += '<div class="top-action-tooltip-label">Why It Matters</div>';
                content += '<div class="top-action-tooltip-text">' + escapeHtml(checkInfo.whyItMatters) + '</div>';
                content += '</div>';
            }

            if (checkInfo.whatWeCheck && checkInfo.whatWeCheck.length > 0) {
                content += '<div class="top-action-tooltip-section">';
                content += '<div class="top-action-tooltip-label">What We Check</div>';
                content += '<ul class="top-action-tooltip-list">';
                checkInfo.whatWeCheck.forEach(item => {
                    content += '<li>' + escapeHtml(item) + '</li>';
                });
                content += '</ul>';
                content += '</div>';
            }

            if (checkInfo.filteringNote) {
                content += '<div class="top-action-tooltip-section top-action-tooltip-note">';
                content += '<div class="top-action-tooltip-label">Note</div>';
                content += '<div class="top-action-tooltip-text">' + escapeHtml(checkInfo.filteringNote) + '</div>';
                content += '</div>';
            }

            content += '</div>';

            // Show as tooltip near the button
            showTooltipAt(btn, content);
        }

        // Track active floating tooltip and its event listener for cleanup
        let activeFloatingTooltip = null;
        let activeFloatingTooltipListener = null;

        function showTooltipAt(element, content) {
            // Remove any existing tooltip and clean up its event listener
            if (activeFloatingTooltip) {
                activeFloatingTooltip.remove();
                if (activeFloatingTooltipListener) {
                    document.removeEventListener('click', activeFloatingTooltipListener);
                    activeFloatingTooltipListener = null;
                }
                activeFloatingTooltip = null;
            }

            // Create tooltip
            const tooltip = document.createElement('div');
            tooltip.className = 'remediation-floating-tooltip';
            tooltip.innerHTML = content;
            document.body.appendChild(tooltip);
            activeFloatingTooltip = tooltip;

            // Position near element with smart positioning
            const rect = element.getBoundingClientRect();
            const tooltipRect = tooltip.getBoundingClientRect();
            const viewportHeight = window.innerHeight;
            const viewportWidth = window.innerWidth;

            // Calculate vertical position - prefer below, but go above if not enough space
            let top;
            if (rect.bottom + tooltipRect.height + 20 > viewportHeight) {
                // Not enough space below - show above
                top = rect.top + window.scrollY - tooltipRect.height - 8;
            } else {
                // Show below
                top = rect.bottom + window.scrollY + 8;
            }

            // Calculate horizontal position
            let left = rect.left + window.scrollX - 100;
            if (left + tooltipRect.width > viewportWidth - UI_CONSTANTS.VIEWPORT_PADDING) {
                left = viewportWidth - tooltipRect.width - 20;
            }
            if (left < UI_CONSTANTS.VIEWPORT_PADDING) {
                left = UI_CONSTANTS.VIEWPORT_PADDING;
            }

            tooltip.style.top = top + 'px';
            tooltip.style.left = left + 'px';

            // Create named listener for proper cleanup
            activeFloatingTooltipListener = function closeTooltip(e) {
                if (!tooltip.contains(e.target) && e.target !== element) {
                    tooltip.remove();
                    document.removeEventListener('click', closeTooltip);
                    activeFloatingTooltip = null;
                    activeFloatingTooltipListener = null;
                }
            };

            // Close on outside click (with small delay to prevent immediate close)
            setTimeout(() => {
                if (activeFloatingTooltip === tooltip) {
                    document.addEventListener('click', activeFloatingTooltipListener);
                }
            }, UI_CONSTANTS.TOOLTIP_CLOSE_DELAY);
        }

        // ============================================================
        // SCORE SORT STATE
        // ============================================================

        // Populate score badges into finding card headers
        function populateCardScores() {
            const cards = document.querySelectorAll('.finding-card');
            if (!cards.length) return;

            cards.forEach((card, index) => {
                const severity = card.dataset.severity || 'note';

                // Note and Secure cards have no score
                if (severity === 'note' || severity === 'secure') return;

                // Calculate score from JSON metadata (preferred) or DOM fallback
                let breakdown;
                const cardIndex = parseInt(card.dataset.cardIndex);
                if (!isNaN(cardIndex) && scoringContext?.findingCards?.[cardIndex]) {
                    breakdown = calculateScoreFromMetadata(scoringContext.findingCards[cardIndex]);
                } else {
                    breakdown = calculateFindingScoreWithBreakdown(card);
                }

                if (breakdown.finalScore <= 0) return;

                // Determine score class
                const scoreClass = breakdown.finalScore >= scoreThresholds.critical ? 'score-critical' :
                                   breakdown.finalScore >= scoreThresholds.high ? 'score-high' :
                                   breakdown.finalScore >= scoreThresholds.medium ? 'score-medium' :
                                   breakdown.finalScore >= scoreThresholds.low ? 'score-low' : 'score-info';

                // Create score badge element
                const badge = document.createElement('span');
                badge.className = 'score-badge ' + scoreClass;
                badge.textContent = breakdown.finalScore;
                badge.dataset.scoreBreakdown = JSON.stringify(breakdown);
                badge.title = 'Risk Score (click for details)';
                badge.addEventListener('click', function(e) {
                    e.stopPropagation();
                    showScoreTooltip(this, breakdown);
                });

                // Insert badge into finding-meta area (before chevron, after count)
                const meta = card.querySelector('.finding-meta');
                const chevron = meta?.querySelector('.finding-toggle');
                if (meta && chevron) {
                    meta.insertBefore(badge, chevron);
                }

                // Store score on the card element for sorting
                card.dataset.score = breakdown.finalScore;
            });
        }

        // Severity order for sorting (lower = more critical)
        const SEVERITY_ORDER = { 'finding': 0, 'hint': 1, 'note': 2, 'secure': 3 };

        // Sort all finding cards by score (descending), then by severity
        // Called once after populateCardScores() — sections are hidden, cards are flat-sorted
        function sortCardsByScore() {
            const container = document.getElementById('cardViewContainer');
            if (!container) return;

            const allCards = Array.from(container.querySelectorAll('.finding-card'));
            if (allCards.length === 0) return;

            const scoredCards = allCards.map(card => ({
                element: card,
                score: parseInt(card.dataset.score) || 0,
                severity: SEVERITY_ORDER[card.dataset.severity] ?? 99
            }));

            // Sort by score descending, then by severity
            scoredCards.sort((a, b) => {
                if (b.score !== a.score) return b.score - a.score;
                return a.severity - b.severity;
            });

            // Hide all sections (cards are shown flat)
            container.querySelectorAll('.section').forEach(s => s.style.display = 'none');

            // Append sorted cards directly to container
            scoredCards.forEach(item => container.appendChild(item.element));
        }

        function expandAllCards() {
            // Expand all finding cards
            document.querySelectorAll('.finding-card').forEach(card => {
                card.classList.add('expanded');
            });
            // Expand top priority actions
            const topActions = document.querySelector('.top-actions');
            if (topActions) {
                topActions.classList.remove('collapsed');
                updateTopActionsToggleIcon(topActions);
            }
        }

        function collapseAllCards() {
            // Collapse all finding cards
            document.querySelectorAll('.finding-card').forEach(card => {
                card.classList.remove('expanded');
            });
            // Collapse top priority actions
            const topActions = document.querySelector('.top-actions');
            if (topActions) {
                topActions.classList.add('collapsed');
                updateTopActionsToggleIcon(topActions);
            }
        }

        function toggleTopActions() {
            const topActions = document.querySelector('.top-actions');
            if (topActions) {
                topActions.classList.toggle('collapsed');
                updateTopActionsToggleIcon(topActions);
            }
        }

        function updateTopActionsToggleIcon(topActions) {
            const toggleIcon = topActions.querySelector('.toggle-icon');
            if (toggleIcon) {
                toggleIcon.innerHTML = topActions.classList.contains('collapsed') ? '&#9654;' : '&#9660;';
            }
        }

        // ============================================================
        // COPY BUTTON for Remediation
        // ============================================================

        function copyToClipboard(button, text) {
            navigator.clipboard.writeText(text).then(() => {
                button.classList.add('copied');
                const originalText = button.textContent;
                button.textContent = 'Copied!';
                setTimeout(() => {
                    button.classList.remove('copied');
                    button.textContent = originalText;
                }, UI_CONSTANTS.COPY_FEEDBACK_DURATION);
            }).catch(err => {
                console.error('Failed to copy:', err);
                button.textContent = 'Failed';
                setTimeout(() => {
                    button.textContent = 'Copy';
                }, UI_CONSTANTS.COPY_FEEDBACK_DURATION);
            });
        }

        // ============================================================
        // Per-card name column resizing (Excel-like, not persisted)
        // ============================================================

        function initColumnResize() {
            const MIN_NAME_W = 120;   // px - keep the name column usable
            const MIN_VALUE_W = 140;  // px - keep the value column usable
            let resizer = null;
            let objectBody = null;
            let startX = 0;
            let startW = 0;
            let maxW = 0;

            document.addEventListener('mousedown', function(e) {
                const r = e.target.closest('.attr-col-resizer');
                if (!r) return;

                objectBody = r.closest('.object-body');
                if (!objectBody) return;

                e.preventDefault();
                resizer = r;

                // Current width from the CSS variable or the rendered name cell
                const nameCell = objectBody.querySelector('.attr-name');
                startW = nameCell ? nameCell.getBoundingClientRect().width : 280;
                startX = e.clientX;
                maxW = Math.max(MIN_NAME_W, objectBody.clientWidth - MIN_VALUE_W);

                resizer.classList.add('resizing');
                document.body.classList.add('col-resizing');
            });

            document.addEventListener('mousemove', function(e) {
                if (!resizer || !objectBody) return;
                e.preventDefault();
                let w = startW + (e.clientX - startX);
                w = Math.max(MIN_NAME_W, Math.min(w, maxW));
                objectBody.style.setProperty('--attr-name-w', w + 'px');
            });

            document.addEventListener('mouseup', function() {
                if (!resizer) return;
                resizer.classList.remove('resizing');
                document.body.classList.remove('col-resizing');
                resizer = null;
                objectBody = null;
            });
        }

        // ============================================================
        // DRAG & DROP Attribute Reordering
        // ============================================================

        function initAttributeDragAndDrop() {
            let draggedElement = null;

            // Only the dedicated drag handle starts a drag, so the rest of the
            // row text stays freely selectable / copyable.
            document.addEventListener('dragstart', function(e) {
                const handle = (e.target.classList && e.target.classList.contains('attr-drag-handle')) ? e.target : null;
                const row = handle ? handle.closest('.attr-row') : null;
                if (row) {
                    draggedElement = row;
                    row.classList.add('dragging');
                    e.dataTransfer.effectAllowed = 'move';
                    e.dataTransfer.setData('text/html', row.innerHTML);
                }
            });

            document.addEventListener('dragend', function() {
                if (draggedElement) {
                    draggedElement.classList.remove('dragging');
                    // Remove all drag-over indicators
                    document.querySelectorAll('.attr-row.drag-over').forEach(el => {
                        el.classList.remove('drag-over');
                    });
                    draggedElement = null;
                }
            });

            document.addEventListener('dragover', function(e) {
                if (!draggedElement) return;

                const target = e.target.closest('.attr-row');
                if (!target || target === draggedElement) return;

                e.preventDefault();
                e.dataTransfer.dropEffect = 'move';

                // Remove previous drag-over indicators
                document.querySelectorAll('.attr-row.drag-over').forEach(el => {
                    if (el !== target) el.classList.remove('drag-over');
                });

                // Add drag-over indicator to current target
                target.classList.add('drag-over');
            });

            document.addEventListener('drop', function(e) {
                if (!draggedElement) return;

                const target = e.target.closest('.attr-row');
                if (!target || target === draggedElement) return;

                e.preventDefault();
                e.stopPropagation();

                // Get target parent container
                const targetParent = target.parentNode;

                // Determine insertion position based on mouse Y position
                const targetRect = target.getBoundingClientRect();
                const midPoint = targetRect.top + (targetRect.height / 2);

                if (e.clientY < midPoint) {
                    // Insert before target
                    targetParent.insertBefore(draggedElement, target);
                } else {
                    // Insert after target
                    if (target.nextSibling) {
                        targetParent.insertBefore(draggedElement, target.nextSibling);
                    } else {
                        targetParent.appendChild(draggedElement);
                    }
                }

                // Remove drag-over indicator
                target.classList.remove('drag-over');

                // Update extended attributes counter after cross-container moves
                updateExtendedAttrCounters(draggedElement);
            });
        }

        // Update the "Show/Hide N more attribute(s)" counter after drag & drop
        function updateExtendedAttrCounters(movedElement) {
            // Find the closest object-body container
            const objectBody = movedElement.closest('.object-body');
            if (!objectBody) return;

            const extSection = objectBody.querySelector('.extended-attrs');
            const toggleBtn = objectBody.querySelector('.extended-attrs-toggle');
            if (!extSection || !toggleBtn) return;

            // Count remaining attr-rows in extended section
            const extCount = extSection.querySelectorAll(':scope > .attr-row').length;
            const textSpan = toggleBtn.querySelector('span:last-child');
            if (!textSpan) return;

            if (extCount === 0) {
                // No more extended attributes — hide toggle and section
                toggleBtn.style.display = 'none';
                extSection.style.display = 'none';
            } else {
                toggleBtn.style.display = '';
                // Update counter text, preserve Show/Hide prefix
                const currentText = textSpan.textContent;
                const prefix = currentText.startsWith('Hide') ? 'Hide' : 'Show';
                textSpan.textContent = prefix + ' ' + extCount + ' more attribute(s)';
            }
        }

        // ============================================================
        //  PRINT / PDF PREPARATION
        //  Ensures all content is expanded and a Table of Contents
        //  is generated before the browser renders the print layout.
        // ============================================================

        // State snapshot to restore after printing
        var printStateSnapshot = null;

        function preparePrint() {
            // Save current state so we can restore after printing
            printStateSnapshot = {
                expandedCards: [],
                collapsedTopActions: false,
                hiddenCompletedState: false
            };

            // Remember which cards were NOT expanded (so we can collapse them back)
            document.querySelectorAll('.finding-card:not(.expanded)').forEach(function(card) {
                printStateSnapshot.expandedCards.push(card);
            });

            // Remember top-actions state
            var topActions = document.querySelector('.top-actions');
            if (topActions && topActions.classList.contains('collapsed')) {
                printStateSnapshot.collapsedTopActions = true;
            }

            // Remember hide-completed state
            var hideToggle = document.getElementById('hideCompletedToggle');
            if (hideToggle && hideToggle.checked) {
                printStateSnapshot.hiddenCompletedState = true;
                hideToggle.checked = false;
                toggleHideCompleted();
            }

            // Expand ALL finding cards for print
            document.querySelectorAll('.finding-card').forEach(function(card) {
                card.classList.add('expanded');
            });

            // Expand top-actions
            if (topActions) {
                topActions.classList.remove('collapsed');
                updateTopActionsToggleIcon(topActions);
            }

            // Build Table of Contents from section headers
            buildPrintTOC();
        }

        function restoreAfterPrint() {
            if (!printStateSnapshot) return;

            // Collapse cards that were not expanded before print
            printStateSnapshot.expandedCards.forEach(function(card) {
                card.classList.remove('expanded');
            });

            // Restore top-actions collapsed state
            if (printStateSnapshot.collapsedTopActions) {
                var topActions = document.querySelector('.top-actions');
                if (topActions) {
                    topActions.classList.add('collapsed');
                    updateTopActionsToggleIcon(topActions);
                }
            }

            // Restore hide-completed state
            if (printStateSnapshot.hiddenCompletedState) {
                var hideToggle = document.getElementById('hideCompletedToggle');
                if (hideToggle) {
                    hideToggle.checked = true;
                    toggleHideCompleted();
                }
            }

            // Remove TOC
            var toc = document.getElementById('printTOC');
            if (toc) toc.remove();

            printStateSnapshot = null;
        }

        function buildPrintTOC() {
            // Remove existing TOC if any
            var existing = document.getElementById('printTOC');
            if (existing) existing.remove();

            var sections = document.querySelectorAll('.section');
            if (sections.length === 0) return;

            var toc = document.createElement('div');
            toc.id = 'printTOC';
            toc.className = 'print-toc';

            var tocTitle = document.createElement('div');
            tocTitle.className = 'print-toc-title';
            tocTitle.textContent = 'Table of Contents';
            toc.appendChild(tocTitle);

            // Build severity matrix table
            var table = document.createElement('table');
            table.className = 'print-toc-table';

            // Table header
            var thead = document.createElement('thead');
            var headerRow = document.createElement('tr');
            ['Section', 'Findings', 'Hints', 'Notes', 'Secure'].forEach(function(label) {
                var th = document.createElement('th');
                th.textContent = label;
                headerRow.appendChild(th);
            });
            thead.appendChild(headerRow);
            table.appendChild(thead);

            // Pre-build severity counts per section using data-category attribute
            // Note: Cards may be sorted flat outside their sections (sortCardsByScore),
            // so we use the card's data-category to map back to section IDs (cat-<category>)
            var sectionCounts = {};
            document.querySelectorAll('.finding-card[data-severity][data-category]').forEach(function(card) {
                var sid = 'cat-' + card.getAttribute('data-category');
                if (!sectionCounts[sid]) sectionCounts[sid] = { finding: 0, hint: 0, note: 0, secure: 0 };
                var sev = card.getAttribute('data-severity');
                if (sectionCounts[sid][sev] !== undefined) sectionCounts[sid][sev]++;
            });

            // Table body
            var tbody = document.createElement('tbody');
            var totals = { finding: 0, hint: 0, note: 0, secure: 0 };

            sections.forEach(function(section, index) {
                var titleEl = section.querySelector('.section-title');
                if (!titleEl) return;

                var sectionTitle = titleEl.textContent.trim();
                // Strip [N/M] prefix for cleaner display
                sectionTitle = sectionTitle.replace(/^\[\d+\/\d+\]\s*/, '');
                var sectionId = section.id;

                // Get pre-computed counts for this section
                var counts = sectionCounts[sectionId] || { finding: 0, hint: 0, note: 0, secure: 0 };

                // Accumulate totals
                totals.finding += counts.finding;
                totals.hint += counts.hint;
                totals.note += counts.note;
                totals.secure += counts.secure;

                // Determine highest severity for left border color
                var severity = counts.finding > 0 ? 'finding' : counts.hint > 0 ? 'hint' : counts.secure > 0 ? 'secure' : 'note';

                var row = document.createElement('tr');
                row.className = 'toc-severity-' + severity;

                // Section name cell with link
                var nameCell = document.createElement('td');
                nameCell.className = 'toc-section-name';
                var link = document.createElement('a');
                link.href = '#' + sectionId;
                link.textContent = (index + 1) + '. ' + sectionTitle;
                nameCell.appendChild(link);
                row.appendChild(nameCell);

                // Severity count cells
                [
                    { key: 'finding', cls: 'toc-cell-finding' },
                    { key: 'hint', cls: 'toc-cell-hint' },
                    { key: 'note', cls: 'toc-cell-note' },
                    { key: 'secure', cls: 'toc-cell-secure' }
                ].forEach(function(col) {
                    var td = document.createElement('td');
                    td.className = col.cls;
                    if (counts[col.key] > 0) {
                        td.textContent = counts[col.key];
                        td.classList.add('has-value');
                    } else {
                        td.textContent = '\u2013'; // en-dash
                        td.classList.add('no-value');
                    }
                    row.appendChild(td);
                });

                tbody.appendChild(row);
            });
            table.appendChild(tbody);

            // Table footer with totals
            var tfoot = document.createElement('tfoot');
            var footerRow = document.createElement('tr');

            var totalLabel = document.createElement('td');
            totalLabel.className = 'toc-section-name toc-total-label';
            totalLabel.textContent = 'Total';
            footerRow.appendChild(totalLabel);

            [
                { key: 'finding', cls: 'toc-cell-finding' },
                { key: 'hint', cls: 'toc-cell-hint' },
                { key: 'note', cls: 'toc-cell-note' },
                { key: 'secure', cls: 'toc-cell-secure' }
            ].forEach(function(col) {
                var td = document.createElement('td');
                td.className = col.cls;
                if (totals[col.key] > 0) {
                    td.textContent = totals[col.key];
                    td.classList.add('has-value');
                } else {
                    td.textContent = '\u2013';
                    td.classList.add('no-value');
                }
                footerRow.appendChild(td);
            });

            tfoot.appendChild(footerRow);
            table.appendChild(tfoot);

            toc.appendChild(table);

            // Insert TOC after info-bar, before card controls
            var infoBar = document.querySelector('.info-bar');
            if (infoBar && infoBar.parentNode) {
                infoBar.parentNode.insertBefore(toc, infoBar.nextSibling);
            }
        }

        // Register print event handlers
        window.addEventListener('beforeprint', preparePrint);
        window.addEventListener('afterprint', restoreAfterPrint);

    </script>
</body>
</html>

'@
}



# ----- Convert-adPEASReport.ps1 -----

function Convert-adPEASReport {
    <#
    .SYNOPSIS
    Generates HTML and/or text reports from a previously exported JSON findings cache.

    .DESCRIPTION
    Converts an adPEAS JSON findings export into a fresh HTML, text, or JSON report without
    requiring an active LDAP connection. This enables:

    - Regenerating reports with a newer adPEAS version (updated finding definitions, scoring, templates)
    - Creating reports offline from previously collected scan data
    - Converting between output formats (e.g., JSON-only scan to HTML report)
    - Re-exporting JSON with updated version metadata (-Format JSON)

    The JSON file is produced automatically during any scan with -Outputfile parameter.

    .PARAMETER InputJson
    Path to the JSON findings cache file (produced by a previous adPEAS scan).

    .PARAMETER OutputPath
    Base path for output files (without extension). Files created:
    - .html (Interactive HTML report)
    - .txt  (Text report)
    - .json (Re-exported JSON with current adPEAS version metadata)

    .PARAMETER Format
    Output format: HTML, Text, JSON, or All (default: All).

    .PARAMETER License
    Optional path to a license JSON file for the report disclaimer.

    .PARAMETER NoColor
    Write plain text output without ANSI color codes.

    .EXAMPLE
    Convert-adPEASReport -InputJson ".\report.json" -OutputPath ".\new_report"

    .EXAMPLE
    Convert-adPEASReport -InputJson ".\report.json" -OutputPath ".\new_report" -Format HTML

    .EXAMPLE
    Convert-adPEASReport -InputJson ".\report.json" -OutputPath ".\new_report" -License ".\license.json"

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$InputJson,

        [Parameter(Mandatory=$true)]
        [string]$OutputPath,

        [Parameter(Mandatory=$false)]
        [ValidateSet('Text', 'HTML', 'JSON', 'All')]
        [string]$Format = 'All',

        [Parameter(Mandatory=$false)]
        [string]$License,

        [Parameter(Mandatory=$false)]
        [switch]$NoColor
    )

    begin {
        Write-Log "[Convert-adPEASReport] Starting offline report generation"
    }

    process {
        # Validate input file
        if (-not (Test-Path $InputJson)) {
            Write-Error "[Convert-adPEASReport] Input file not found: $InputJson"
            return
        }

        # Save current state for restoration
        $previousLDAPContext = $Script:LDAPContext
        $previousOutputfile = $Script:adPEAS_Outputfile
        $previousOutputColor = $Script:adPEAS_OutputColor
        $previousFindingsEnabled = $Script:adPEAS_FindingsCollectionEnabled
        $previousDisclaimer = $Script:adPEASDisclaimer

        try {
            # 1. Read and validate JSON (single read, reused for metadata and import)
            $rawJson = Get-Content -Path $InputJson -Raw -Encoding UTF8
            $cache = $rawJson | ConvertFrom-Json

            if (-not $cache.CacheVersion) {
                Write-Error "[Convert-adPEASReport] Invalid JSON file - missing CacheVersion field"
                return
            }
            if ($cache.CacheVersion -ne 1) {
                Write-Error "[Convert-adPEASReport] Unsupported cache version $($cache.CacheVersion) - expected 1"
                return
            }

            $sourceDomain = if ($cache.Domain -and $cache.Domain -ne 'Unknown') { $cache.Domain } else { 'Unknown' }
            $sourceServer = if ($cache.Server) { $cache.Server } else { 'Unknown' }
            $sourceVersion = if ($cache.adPEASVersion) { $cache.adPEASVersion } else { 'Unknown' }
            $sourceDate = if ($cache.ExportDate) { $cache.ExportDate } else { 'Unknown' }
            $findingCount = if ($cache.FindingCount) { $cache.FindingCount } else { 0 }

            # Display source info
            Show-Line "Source: $InputJson" -Class Note -NoCollect
            Show-Line "Domain: $sourceDomain, Server: $sourceServer" -Class Note -NoCollect
            Show-Line "Original scan: $sourceDate (adPEAS $sourceVersion)" -Class Note -NoCollect
            Show-Line "Findings: $findingCount" -Class Note -NoCollect
            $currentVersion = if ($Script:adPEASVersion) { $Script:adPEASVersion } else { '2.0.0' }
            if ($sourceVersion -ne $currentVersion -and $sourceVersion -ne 'Unknown') {
                Show-Line "Regenerating with adPEAS $currentVersion (updated definitions/scoring)" -Class Hint -NoCollect
            }

            # 2. Import findings from already-parsed cache (avoids re-reading the file)
            $findings = Import-FindingsFromCache -Cache $cache
            if (@($findings).Count -eq 0) {
                Write-Warning "[Convert-adPEASReport] No findings loaded from JSON file"
                return
            }

            # 3. Stub LDAPContext for report generation
            $Script:LDAPContext = @{
                Domain   = $sourceDomain
                Server   = $sourceServer
                DomainDN = $null
                Username = 'Offline'
            }

            # 4. Handle license / disclaimer
            # Priority: -License param > RuntimeLicense > EmbeddedLicense > Default disclaimer
            $_licJson = $null
            if ($License) {
                if (Test-Path $License) {
                    $_licJson = Get-Content -Path $License -Raw -Encoding UTF8
                } else {
                    Write-Warning "[Convert-adPEASReport] License file not found: $License"
                }
            } elseif ($Script:RuntimeLicense) {
                $_licJson = $Script:RuntimeLicense
            } elseif ($Script:EmbeddedLicense) {
                $_licJson = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Script:EmbeddedLicense))
            }

            $_licResult = if ($_licJson) { Test-adPEASLicense -LicenseJson $_licJson } else { $null }

            if ($_licResult -and $_licResult.IsValid -and -not $_licResult.Expired) {
                $Script:adPEASDisclaimer = $_licResult.Message
            } else {
                # Default disclaimer (XOR obfuscated) - same as Invoke-adPEAS
                $_lm="GCQlP2w+KTwjPjhsOy0/bCspIik+LTgpKGw5PyUiK2wtbDgjIyBsOCQtOGw+KT05JT4pP2wtbDotICUobC8jISEpPi8lLSBsICUvKSI/KWwqIz5sLyMiPzkgOCUiK2wjPmwhLSItKykobD8pPjolLylsOT8pYg==";$_lk=0x4C
                $Script:adPEASDisclaimer=(-join([Convert]::FromBase64String($_lm)|ForEach-Object{[char]($_-bxor$_lk)}))
            }

            # 5. Resolve output path
            $resolvedBase = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputPath)

            # Strip any existing extension from the base path
            if ([System.IO.Path]::HasExtension($resolvedBase)) {
                $resolvedBase = [System.IO.Path]::ChangeExtension($resolvedBase, $null).TrimEnd('.')
            }

            # Warn if output JSON would overwrite the input file
            $resolvedInput = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($InputJson)
            $outputJsonPath = "$resolvedBase.json"
            if ($Format -in @('All', 'JSON') -and $resolvedInput -eq $outputJsonPath) {
                Write-Warning "[Convert-adPEASReport] Output path '$outputJsonPath' is the same as input file. JSON will be re-exported in place."
            }

            # Ensure output directory exists
            $outputDir = Split-Path -Parent $resolvedBase
            if ($outputDir -and -not (Test-Path $outputDir)) {
                New-Item -ItemType Directory -Path $outputDir -Force | Out-Null
            }

            # 6. Generate HTML report
            if ($Format -in @('HTML', 'All')) {
                Initialize-FindingsCollection
                Set-FindingsCollection -Findings $findings

                $htmlPath = "$resolvedBase.html"
                try {
                    Export-HTMLReport -OutputPath $htmlPath
                    Show-Line "HTML report saved to: $htmlPath" -Class Hint -NoCollect
                } catch {
                    Write-Warning "[Convert-adPEASReport] Error generating HTML report: $_"
                }

                Clear-FindingsCollection
            }

            # 6b. Generate JSON export (for -Format All or -Format JSON)
            if ($Format -in @('All', 'JSON')) {
                Initialize-FindingsCollection
                Set-FindingsCollection -Findings $findings

                $jsonPath = "$resolvedBase.json"
                try {
                    Export-FindingsCache -Path $jsonPath
                    Show-Line "JSON export saved to: $jsonPath" -Class Hint -NoCollect
                } catch {
                    Write-Warning "[Convert-adPEASReport] Error saving JSON: $_"
                }

                Clear-FindingsCollection
            }

            # 7. Generate text report
            if ($Format -in @('Text', 'All')) {
                $textPath = "$resolvedBase.txt"
                $Script:adPEAS_Outputfile = $textPath
                $Script:adPEAS_OutputColor = if ($NoColor) { $false } else { $null }

                # Create/clear the text file
                $utf8Encoding = [System.Text.Encoding]::UTF8
                [System.IO.File]::WriteAllText($textPath, "", $utf8Encoding)

                # Replay findings through Show-* functions (writes to console + file)
                Invoke-FindingsReplay -Findings $findings

                $Script:adPEAS_Outputfile = $null
                Show-Line "Text report saved to: $textPath" -Class Hint -NoCollect
            }

            # Show HTML path again after text replay (the earlier message scrolls away)
            if ($Format -eq 'All' -and $htmlPath) {
                Show-Line "HTML report saved to: $htmlPath" -Class Hint -NoCollect
            }

        } finally {
            # Restore previous state
            $Script:LDAPContext = $previousLDAPContext
            $Script:adPEAS_Outputfile = $previousOutputfile
            $Script:adPEAS_OutputColor = $previousOutputColor
            $Script:adPEAS_FindingsCollectionEnabled = $previousFindingsEnabled
            $Script:adPEASDisclaimer = $previousDisclaimer
            Clear-FindingsCollection
        }
    }

    end {
        Write-Log "[Convert-adPEASReport] Report generation completed"
    }
}

<#
.SYNOPSIS
    Replays findings through the Show-* output system for text report generation.
.DESCRIPTION
    Iterates over imported findings and calls the appropriate Show-* function for each,
    producing console and file output identical to a live scan. Uses -NoCollect to avoid
    re-collecting findings that are already in the collection.
#>
function Invoke-FindingsReplay {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [array]$Findings
    )

    foreach ($finding in $Findings) {
        switch ($finding.Type) {
            'Header' {
                # Show-Header delegates to Show-Output -Class Info which calls Write-adPEASHeader
                Show-Output -Class Info -Value $finding.Text -NoCollect
            }
            'SubHeader' {
                Show-SubHeader $finding.Text -ObjectType $finding.ObjectType -NoCollect
            }
            'Object' {
                if ($finding.Object) {
                    Show-Object $finding.Object -Class $finding.Class -NoCollect
                }
            }
            'KeyValue' {
                $kvParams = @{
                    Key       = $finding.Key
                    Value     = $finding.Value
                    Class     = $finding.Class
                    NoCollect = $true
                }
                if ($finding.FindingId) { $kvParams['FindingId'] = $finding.FindingId }
                Show-Output @kvParams
            }
            'Line' {
                $lineParams = @{
                    Text      = $finding.Text
                    Class     = $finding.Class
                    NoCollect = $true
                }
                if ($finding.FindingId) { $lineParams['FindingId'] = $finding.FindingId }
                Show-Line @lineParams
            }
        }
    }
}



# ----- Compare-adPEASReport.ps1 -----

function Compare-adPEASReport {
    <#
    .SYNOPSIS
    Compares two adPEAS JSON findings exports and shows differences.

    .DESCRIPTION
    Analyzes two JSON findings caches from different scans and produces a structured
    comparison showing:

    - New findings (in current but not in baseline) - potential new vulnerabilities
    - Remediated findings (in baseline but not in current) - fixed issues
    - Changed findings (severity changed between scans)
    - Summary statistics

    This enables tracking remediation progress, detecting new vulnerabilities,
    and trend analysis across multiple scans.

    .PARAMETER Baseline
    Path to the baseline (older) JSON findings cache file.

    .PARAMETER Current
    Path to the current (newer) JSON findings cache file.

    .PARAMETER OutputPath
    Optional base path for diff report output files (without extension).
    If specified, generates a text diff report.

    .PARAMETER NoColor
    Write plain text output without ANSI color codes.

    .EXAMPLE
    Compare-adPEASReport -Baseline ".\scan_q1.json" -Current ".\scan_q2.json"

    .EXAMPLE
    Compare-adPEASReport -Baseline ".\scan_jan.json" -Current ".\scan_apr.json" -OutputPath ".\diff_report"

    .NOTES
    Author: Alexander Sturz (@_61106960_)
    #>

    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$Baseline,

        [Parameter(Mandatory=$true)]
        [string]$Current,

        [Parameter(Mandatory=$false)]
        [string]$OutputPath,

        [Parameter(Mandatory=$false)]
        [switch]$NoColor
    )

    begin {
        Write-Log "[Compare-adPEASReport] Starting report comparison"
    }

    process {
        # Validate input files
        if (-not (Test-Path $Baseline)) {
            Write-Error "[Compare-adPEASReport] Baseline file not found: $Baseline"
            return
        }
        if (-not (Test-Path $Current)) {
            Write-Error "[Compare-adPEASReport] Current file not found: $Current"
            return
        }

        # Save and configure output state
        $previousOutputfile = $Script:adPEAS_Outputfile
        $previousOutputColor = $Script:adPEAS_OutputColor

        try {
            # Configure file output if requested
            if ($OutputPath) {
                $resolvedBase = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputPath)
                # Strip any existing extension from the base path
                if ([System.IO.Path]::HasExtension($resolvedBase)) {
                    $resolvedBase = [System.IO.Path]::ChangeExtension($resolvedBase, $null).TrimEnd('.')
                }
                $outputDir = Split-Path -Parent $resolvedBase
                if ($outputDir -and -not (Test-Path $outputDir)) {
                    New-Item -ItemType Directory -Path $outputDir -Force | Out-Null
                }
                $textPath = "$resolvedBase.txt"
                $Script:adPEAS_Outputfile = $textPath
                [System.IO.File]::WriteAllText($textPath, "", [System.Text.Encoding]::UTF8)
            }
            $Script:adPEAS_OutputColor = if ($NoColor) { $false } else { $null }

            # 1. Load and validate JSON (single read per file, reused for metadata and import)
            $baselineCache = (Get-Content -Path $Baseline -Raw -Encoding UTF8) | ConvertFrom-Json
            $currentCache = (Get-Content -Path $Current -Raw -Encoding UTF8) | ConvertFrom-Json

            # Validate cache versions
            foreach ($entry in @(@{Name='Baseline'; Cache=$baselineCache; Path=$Baseline}, @{Name='Current'; Cache=$currentCache; Path=$Current})) {
                if (-not $entry.Cache.CacheVersion) {
                    Write-Error "[Compare-adPEASReport] Invalid JSON file ($($entry.Name)): $($entry.Path)"
                    return
                }
                if ($entry.Cache.CacheVersion -ne 1) {
                    Write-Error "[Compare-adPEASReport] Unsupported cache version $($entry.Cache.CacheVersion) in $($entry.Name): $($entry.Path)"
                    return
                }
            }

            # Extract metadata
            $baselineMeta = @{
                Domain  = if ($baselineCache.Domain) { $baselineCache.Domain } else { 'Unknown' }
                Date    = if ($baselineCache.ExportDate) { try { ([datetime]::Parse($baselineCache.ExportDate)).ToString('yyyy-MM-dd HH:mm') } catch { $baselineCache.ExportDate } } else { 'Unknown' }
                Version = if ($baselineCache.adPEASVersion) { $baselineCache.adPEASVersion } else { 'Unknown' }
                Count   = if ($baselineCache.FindingCount) { $baselineCache.FindingCount } else { 0 }
            }
            $currentMeta = @{
                Domain  = if ($currentCache.Domain) { $currentCache.Domain } else { 'Unknown' }
                Date    = if ($currentCache.ExportDate) { try { ([datetime]::Parse($currentCache.ExportDate)).ToString('yyyy-MM-dd HH:mm') } catch { $currentCache.ExportDate } } else { 'Unknown' }
                Version = if ($currentCache.adPEASVersion) { $currentCache.adPEASVersion } else { 'Unknown' }
                Count   = if ($currentCache.FindingCount) { $currentCache.FindingCount } else { 0 }
            }

            # Cross-domain warning
            if ($baselineMeta.Domain -ne 'Unknown' -and $currentMeta.Domain -ne 'Unknown' -and
                $baselineMeta.Domain -ne $currentMeta.Domain) {
                Write-Warning "[Compare-adPEASReport] Domain mismatch: Baseline='$($baselineMeta.Domain)' vs Current='$($currentMeta.Domain)'"
                Write-Warning "[Compare-adPEASReport] Comparison results may not be meaningful across different domains"
            }

            # 2. Import findings from already-parsed caches (avoids re-reading files)
            $baselineFindings = Import-FindingsFromCache -Cache $baselineCache
            $currentFindings = Import-FindingsFromCache -Cache $currentCache

            # Filter to comparable findings only
            # Skip structural elements (Header, SubHeader) and internal artifacts (Category = Unknown:
            # disclaimers, connection messages, merge notes, progress indicators)
            $baselineComparable = @($baselineFindings | Where-Object {
                $_.Type -notin @('Header', 'SubHeader') -and $_.Category -ne 'Unknown'
            })
            $currentComparable = @($currentFindings | Where-Object {
                $_.Type -notin @('Header', 'SubHeader') -and $_.Category -ne 'Unknown'
            })

            # 3. Build identity maps
            $baselineMap = @{}
            foreach ($f in $baselineComparable) {
                $id = Get-FindingIdentity -Finding $f
                if ($id) { $baselineMap[$id] = $f }
            }
            $currentMap = @{}
            foreach ($f in $currentComparable) {
                $id = Get-FindingIdentity -Finding $f
                if ($id) { $currentMap[$id] = $f }
            }

            # 4. Compute diff
            $added = [System.Collections.ArrayList]::new()
            $removed = [System.Collections.ArrayList]::new()
            $changed = [System.Collections.ArrayList]::new()
            $unchangedCount = 0

            # Find added and changed
            foreach ($id in $currentMap.Keys) {
                if (-not $baselineMap.ContainsKey($id)) {
                    [void]$added.Add($currentMap[$id])
                } else {
                    $bf = $baselineMap[$id]
                    $cf = $currentMap[$id]
                    $severityChanged = $bf.Severity -ne $cf.Severity
                    # For KeyValue findings, also detect value changes
                    $valueChanged = $cf.Type -eq 'KeyValue' -and $bf.Value -ne $cf.Value
                    # For Line findings, detect text changes (numbers were normalized in identity)
                    $textChanged = $cf.Type -eq 'Line' -and $bf.Text -ne $cf.Text
                    if ($severityChanged -or $valueChanged -or $textChanged) {
                        [void]$changed.Add(@{ Baseline = $bf; Current = $cf; Identity = $id })
                    } else {
                        $unchangedCount++
                    }
                }
            }

            # Find removed
            foreach ($id in $baselineMap.Keys) {
                if (-not $currentMap.ContainsKey($id)) {
                    [void]$removed.Add($baselineMap[$id])
                }
            }

            # 5. Detect scope differences (categories only in one scan)
            $baselineCategories = @($baselineComparable | ForEach-Object { $_.Category } | Select-Object -Unique | Sort-Object)
            $currentCategories = @($currentComparable | ForEach-Object { $_.Category } | Select-Object -Unique | Sort-Object)
            $onlyInBaseline = @($baselineCategories | Where-Object { $_ -notin $currentCategories })
            $onlyInCurrent = @($currentCategories | Where-Object { $_ -notin $baselineCategories })
            $sharedCategories = @($baselineCategories | Where-Object { $_ -in $currentCategories })

            # Separate scope-only findings from real added/removed
            # Findings in non-overlapping categories are NOT real changes - they reflect
            # different scan scopes (e.g., one scan ran -Module Accounts, the other ran all modules)
            $scopeOnlyBaseline = @()
            $scopeOnlyCurrent = @()
            if ($onlyInBaseline.Count -gt 0) {
                $scopeOnlyBaseline = @($removed | Where-Object { $_.Category -in $onlyInBaseline })
                $removed = [System.Collections.ArrayList]@($removed | Where-Object { $_.Category -notin $onlyInBaseline })
            }
            if ($onlyInCurrent.Count -gt 0) {
                $scopeOnlyCurrent = @($added | Where-Object { $_.Category -in $onlyInCurrent })
                $added = [System.Collections.ArrayList]@($added | Where-Object { $_.Category -notin $onlyInCurrent })
            }

            # 6. Output report
            Show-Output -Class Info -Value "adPEAS Report Comparison" -NoCollect

            Show-Line "Baseline: $(Split-Path -Leaf $Baseline) ($($baselineMeta.Date), $($baselineMeta.Domain), adPEAS $($baselineMeta.Version))" -Class Note -NoCollect
            Show-Line "Current:  $(Split-Path -Leaf $Current) ($($currentMeta.Date), $($currentMeta.Domain), adPEAS $($currentMeta.Version))" -Class Note -NoCollect

            # Summary
            Show-Output -Class Info -Value "Comparison Summary" -NoCollect

            Show-Output -Key "New findings (added)" -Value "$($added.Count)" -Class $(if ($added.Count -gt 0) { 'Finding' } else { 'Note' }) -NoCollect
            Show-Output -Key "Remediated findings (removed)" -Value "$($removed.Count)" -Class $(if ($removed.Count -gt 0) { 'Secure' } else { 'Note' }) -NoCollect
            Show-Output -Key "Changed findings" -Value "$($changed.Count)" -Class $(if ($changed.Count -gt 0) { 'Hint' } else { 'Note' }) -NoCollect
            Show-Output -Key "Unchanged findings" -Value "$unchangedCount" -Class Note -NoCollect
            Show-Output -Key "Compared categories" -Value "$($sharedCategories.Count) ($($sharedCategories -join ', '))" -Class Note -NoCollect

            # New findings detail
            if ($added.Count -gt 0) {
                Show-Output -Class Info -Value "New Findings ($($added.Count))" -NoCollect

                $addedGroups = $added | Group-Object -Property { "$($_.Category) > $($_.CheckTitle)" }
                foreach ($group in ($addedGroups | Sort-Object Name)) {
                    Show-SubHeader $group.Name -NoCollect
                    foreach ($f in $group.Group) {
                        $displayName = Get-FindingDisplayName -Finding $f
                        Show-Line "$displayName ($($f.Severity))" -Class Finding -NoCollect
                    }
                }
            }

            # Remediated findings detail
            if ($removed.Count -gt 0) {
                Show-Output -Class Info -Value "Remediated Findings ($($removed.Count))" -NoCollect

                $removedGroups = $removed | Group-Object -Property { "$($_.Category) > $($_.CheckTitle)" }
                foreach ($group in ($removedGroups | Sort-Object Name)) {
                    Show-SubHeader $group.Name -NoCollect
                    foreach ($f in $group.Group) {
                        $displayName = Get-FindingDisplayName -Finding $f
                        Show-Line "$displayName (was: $($f.Severity))" -Class Secure -NoCollect
                    }
                }
            }

            # Changed findings detail
            if ($changed.Count -gt 0) {
                Show-Output -Class Info -Value "Changed Findings ($($changed.Count))" -NoCollect

                $changedGroups = $changed | Group-Object -Property { "$($_.Current.Category) > $($_.Current.CheckTitle)" }
                foreach ($group in ($changedGroups | Sort-Object Name)) {
                    Show-SubHeader $group.Name -NoCollect
                    foreach ($entry in $group.Group) {
                        $displayName = Get-FindingDisplayName -Finding $entry.Current
                        # Build change description based on what changed
                        $changeDesc = @()
                        if ($entry.Baseline.Severity -ne $entry.Current.Severity) {
                            $changeDesc += "severity: $($entry.Baseline.Severity) -> $($entry.Current.Severity)"
                        }
                        if ($entry.Current.Type -eq 'KeyValue' -and $entry.Baseline.Value -ne $entry.Current.Value) {
                            $changeDesc += "value: $($entry.Baseline.Value) -> $($entry.Current.Value)"
                        }
                        if ($entry.Current.Type -eq 'Line' -and $entry.Baseline.Text -ne $entry.Current.Text) {
                            $changeDesc += "text changed"
                        }
                        $changeText = $changeDesc -join ', '
                        Show-Line "$displayName ($changeText)" -Class Hint -NoCollect
                    }
                }
            }

            # Scope differences (different scan modules between baseline and current)
            if ($onlyInBaseline.Count -gt 0 -or $onlyInCurrent.Count -gt 0) {
                Show-Output -Class Info -Value "Scan Scope Differences" -NoCollect
                Show-Line "The following categories were not scanned in both reports and are excluded from the comparison above." -Class Note -NoCollect

                if ($onlyInCurrent.Count -gt 0) {
                    Show-Line "Only in current scan: $($onlyInCurrent -join ', ') ($($scopeOnlyCurrent.Count) finding(s) not compared)" -Class Hint -NoCollect
                }
                if ($onlyInBaseline.Count -gt 0) {
                    Show-Line "Only in baseline scan: $($onlyInBaseline -join ', ') ($($scopeOnlyBaseline.Count) finding(s) not compared)" -Class Hint -NoCollect
                }
            }

            # Generate HTML diff report
            if ($OutputPath) {
                $htmlPath = "$resolvedBase.html"
                try {
                    Export-DiffHtmlReport -OutputPath $htmlPath `
                        -BaselineMeta $baselineMeta -CurrentMeta $currentMeta `
                        -BaselineFile (Split-Path -Leaf $Baseline) -CurrentFile (Split-Path -Leaf $Current) `
                        -Added $added -Removed $removed -Changed $changed `
                        -UnchangedCount $unchangedCount `
                        -SharedCategories $sharedCategories `
                        -OnlyInBaseline $onlyInBaseline -OnlyInCurrent $onlyInCurrent `
                        -ScopeOnlyBaseline $scopeOnlyBaseline -ScopeOnlyCurrent $scopeOnlyCurrent
                    Show-Line "HTML diff report saved to: $htmlPath" -Class Hint -NoCollect
                } catch {
                    Write-Warning "[Compare-adPEASReport] Error generating HTML diff report: $_"
                }
            }

            # File output notification
            if ($OutputPath) {
                Show-Line "Text diff report saved to: $textPath" -Class Hint -NoCollect
            }

        } finally {
            $Script:adPEAS_Outputfile = $previousOutputfile
            $Script:adPEAS_OutputColor = $previousOutputColor
        }
    }

    end {
        Write-Log "[Compare-adPEASReport] Comparison completed"
    }
}

<#
.SYNOPSIS
    Computes a stable identity string for a finding to enable cross-scan matching.
.DESCRIPTION
    Generates a unique key from Category, CheckName, and type-specific identifiers
    (distinguishedName, sAMAccountName, Key, or Text) to match findings across scans.
#>
function Get-FindingIdentity {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Finding
    )

    $prefix = "$($Finding.Category)|$($Finding.CheckName)"

    switch ($Finding.Type) {
        'Object' {
            $op = $Finding.Object
            if (-not $op) { $op = $Finding.ObjectProperties }

            $oid = $null
            if ($op) {
                # Priority: distinguishedName > sAMAccountName > Name > cn > displayName
                if ($op.distinguishedName) { $oid = $op.distinguishedName }
                elseif ($op.sAMAccountName) { $oid = $op.sAMAccountName }
                elseif ($op.Name) { $oid = $op.Name }
                elseif ($op.cn) { $oid = $op.cn }
                elseif ($op.displayName) { $oid = $op.displayName }
                # For synthetic objects (ACLs, permissions) try composite key
                elseif ($op.PrincipalName -and $op.TargetObject) { $oid = "$($op.PrincipalName)->$($op.TargetObject)" }
                elseif ($op.PrincipalName) { $oid = $op.PrincipalName }
                # For credential findings (GPPCredential, SYSVOLCredential) use userName+filePath
                elseif ($op.userName -and $op.filePath) { $oid = "$($op.userName)|$($op.filePath)" }
                elseif ($op.filePath) { $oid = $op.filePath }
                elseif ($op.credentialType) { $oid = $op.credentialType }
                # For domain info objects, use _adPEASObjectType as stable identity
                elseif ($op._adPEASObjectType) { $oid = $op._adPEASObjectType }
                # Last resort: use first non-internal property value
                else {
                    foreach ($p in $op.PSObject.Properties) {
                        if ($p.Name -notin @('_adPEASObjectType', '_adPEASContext', '_Severity', '_Risk') -and $p.Value) {
                            $oid = "$($p.Name)=$($p.Value)"; break
                        }
                    }
                }
            }
            if (-not $oid) { $oid = 'unknown' }
            return "$prefix|Object|$oid"
        }
        'KeyValue' {
            return "$prefix|KV|$($Finding.Key)"
        }
        'Line' {
            # Normalize dynamic numbers so count changes don't create phantom diffs
            # e.g., "Found 5 accounts" and "Found 3 accounts" match to same identity
            $normalizedText = $Finding.Text -replace '\d+', '#'
            return "$prefix|Line|$normalizedText"
        }
        default {
            return $null
        }
    }
}

<#
.SYNOPSIS
    Extracts a human-readable display name from a finding for diff output.
#>
function Get-FindingDisplayName {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        $Finding
    )

    switch ($Finding.Type) {
        'Object' {
            $op = $Finding.Object
            if (-not $op) { return '[Object]' }

            if ($op.sAMAccountName) { return $op.sAMAccountName }
            if ($op.Name) { return $op.Name }
            if ($op.cn) { return $op.cn }
            if ($op.displayName) { return $op.displayName }
            if ($op.distinguishedName) {
                # Extract CN from DN for readability
                if ($op.distinguishedName -match '^CN=([^,]+)') { return $Matches[1] }
                return $op.distinguishedName
            }
            if ($op.PrincipalName) { return "$($op.PrincipalName) -> $($op.TargetObject)" }
            # Domain info objects: use _adPEASObjectType or first meaningful property
            if ($op._adPEASObjectType) { return $op._adPEASObjectType }
            foreach ($p in $op.PSObject.Properties) {
                if ($p.Name -notin @('_adPEASObjectType', '_adPEASContext', '_Severity', '_Risk') -and $p.Value) {
                    $val = [string]$p.Value
                    if ($val.Length -gt 60) { $val = $val.Substring(0, 57) + '...' }
                    return $val
                }
            }
            return '[Object]'
        }
        'KeyValue' {
            if ($Finding.Value) {
                return "$($Finding.Key): $($Finding.Value)"
            }
            return $Finding.Key
        }
        'Line' {
            return $Finding.Text
        }
        default {
            return $Finding.Text
        }
    }
}

<#
.SYNOPSIS
    Generates a standalone HTML diff report from comparison results.
.DESCRIPTION
    Creates a self-contained HTML file with embedded CSS and JS that visualizes
    the differences between two adPEAS scans. Uses the same color scheme and
    theme system as the main adPEAS HTML report.
#>
function Export-DiffHtmlReport {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)]
        [string]$OutputPath,

        [hashtable]$BaselineMeta,
        [hashtable]$CurrentMeta,
        [string]$BaselineFile,
        [string]$CurrentFile,
        $Added,
        $Removed,
        $Changed,
        [int]$UnchangedCount,
        [string[]]$SharedCategories,
        [string[]]$OnlyInBaseline,
        [string[]]$OnlyInCurrent,
        $ScopeOnlyBaseline,
        $ScopeOnlyCurrent
    )

    # Load diff template
    $html = Get-DiffHTMLTemplate
    if (-not $html) {
        Write-Warning "[Export-DiffHtmlReport] Failed to load diff HTML template"
        return
    }

    # Build diff sections HTML
    $sectionsHtml = [System.Text.StringBuilder]::new()

    # New Findings section
    if ($Added.Count -gt 0) {
        [void]$sectionsHtml.Append((Build-DiffSectionHtml -Title "New Findings" -Findings $Added -SectionType 'new'))
    }

    # Remediated Findings section
    if ($Removed.Count -gt 0) {
        [void]$sectionsHtml.Append((Build-DiffSectionHtml -Title "Remediated Findings" -Findings $Removed -SectionType 'remediated'))
    }

    # Changed Findings section
    if ($Changed.Count -gt 0) {
        [void]$sectionsHtml.Append((Build-DiffChangedSectionHtml -Title "Changed Findings" -ChangedEntries $Changed))
    }

    # Scope Differences section
    if ($OnlyInBaseline.Count -gt 0 -or $OnlyInCurrent.Count -gt 0) {
        $scopeHtml = [System.Text.StringBuilder]::new()
        [void]$scopeHtml.AppendLine('<section class="section">')
        [void]$scopeHtml.AppendLine('  <div class="section-header" onclick="toggleSection(this)">')
        [void]$scopeHtml.AppendLine('    <div class="section-title">Scan Scope Differences</div>')
        [void]$scopeHtml.AppendLine('    <span class="section-toggle">&#9660;</span>')
        [void]$scopeHtml.AppendLine('  </div>')
        [void]$scopeHtml.AppendLine('  <div class="section-content">')
        [void]$scopeHtml.AppendLine('    <div class="scope-info">')
        [void]$scopeHtml.AppendLine('      The following categories were not scanned in both reports and are excluded from the comparison above.<br>')
        if ($OnlyInCurrent.Count -gt 0) {
            $cats = (ConvertTo-HtmlEncode ($OnlyInCurrent -join ', '))
            [void]$scopeHtml.AppendLine("      <strong>Only in current scan:</strong> $cats ($($ScopeOnlyCurrent.Count) finding(s) not compared)<br>")
        }
        if ($OnlyInBaseline.Count -gt 0) {
            $cats = (ConvertTo-HtmlEncode ($OnlyInBaseline -join ', '))
            [void]$scopeHtml.AppendLine("      <strong>Only in baseline scan:</strong> $cats ($($ScopeOnlyBaseline.Count) finding(s) not compared)")
        }
        [void]$scopeHtml.AppendLine('    </div>')
        [void]$scopeHtml.AppendLine('  </div>')
        [void]$scopeHtml.AppendLine('</section>')
        [void]$sectionsHtml.Append($scopeHtml.ToString())
    }

    # Empty state
    if ($Added.Count -eq 0 -and $Removed.Count -eq 0 -and $Changed.Count -eq 0 -and
        $OnlyInBaseline.Count -eq 0 -and $OnlyInCurrent.Count -eq 0) {
        [void]$sectionsHtml.AppendLine('<div class="empty-state">No differences found between the two scans.</div>')
    }

    # Build info strings
    $baselineInfo = "$BaselineFile ($($BaselineMeta.Date), $($BaselineMeta.Domain), adPEAS $($BaselineMeta.Version))"
    $currentInfo = "$CurrentFile ($($CurrentMeta.Date), $($CurrentMeta.Domain), adPEAS $($CurrentMeta.Version))"
    $comparedCats = if ($SharedCategories.Count -gt 0) { "$($SharedCategories.Count) ($($SharedCategories -join ', '))" } else { "None" }
    $version = if ($Script:adPEASVersion) { $Script:adPEASVersion } else { "2.0.0" }
    $generatedDate = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $domain = $BaselineMeta.Domain

    # Replace placeholders
    # Literal .Replace() for every token - a data value containing '$' + digits would otherwise be
    # read as a regex capture-group reference by -replace and overflow Int32.MaxValue (see the
    # detailed note in Export-HTMLReport.ps1). HTML-encoding does not escape '$'.
    $html = $html.Replace('{{DOMAIN}}', [string](ConvertTo-HtmlEncode $domain))
    $html = $html.Replace('{{NEW_COUNT}}', [string]$Added.Count)
    $html = $html.Replace('{{REMEDIATED_COUNT}}', [string]$Removed.Count)
    $html = $html.Replace('{{CHANGED_COUNT}}', [string]$Changed.Count)
    $html = $html.Replace('{{UNCHANGED_COUNT}}', [string]$UnchangedCount)
    $html = $html.Replace('{{BASELINE_INFO}}', [string](ConvertTo-HtmlEncode $baselineInfo))
    $html = $html.Replace('{{CURRENT_INFO}}', [string](ConvertTo-HtmlEncode $currentInfo))
    $html = $html.Replace('{{COMPARED_CATEGORIES}}', [string](ConvertTo-HtmlEncode $comparedCats))
    $html = $html.Replace('{{GENERATED}}', [string]$generatedDate)
    $html = $html.Replace('{{VERSION}}', [string]$version)
    $html = $html.Replace('{{DIFF_SECTIONS}}', $sectionsHtml.ToString())

    # Write file (UTF-8 without BOM, same as Export-HTMLReport)
    $utf8NoBom = New-Object System.Text.UTF8Encoding $false
    $resolvedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($OutputPath)
    [System.IO.File]::WriteAllText($resolvedPath, $html, $utf8NoBom)

    Write-Log "[Export-DiffHtmlReport] HTML diff report saved to: $OutputPath"
}

<#
.SYNOPSIS
    Builds an HTML section with finding items for the diff report.
.PARAMETER Title
    Section title (e.g., "New Findings", "Remediated Findings").
.PARAMETER Findings
    Array of finding objects to render.
.PARAMETER SectionType
    Visual style: 'new' (red badge), 'remediated' (blue badge).
#>
function Build-DiffSectionHtml {
    [CmdletBinding()]
    param(
        [string]$Title,
        [array]$Findings,
        [string]$SectionType
    )

    $sb = [System.Text.StringBuilder]::new()
    [void]$sb.AppendLine('<section class="section">')
    [void]$sb.AppendLine("  <div class=`"section-header`" onclick=`"toggleSection(this)`">")
    $escapedTitle = ConvertTo-HtmlEncode $Title
    [void]$sb.AppendLine("    <div class=`"section-title`">$escapedTitle <span class=`"section-count`">$($Findings.Count)</span></div>")
    [void]$sb.AppendLine('    <span class="section-toggle">&#9660;</span>')
    [void]$sb.AppendLine('  </div>')
    [void]$sb.AppendLine('  <div class="section-content">')

    # Group by Category > CheckTitle for readability
    $groups = $Findings | Group-Object -Property { "$($_.Category) > $($_.CheckTitle)" }
    foreach ($group in ($groups | Sort-Object Name)) {
        foreach ($f in $group.Group) {
            $displayName = ConvertTo-HtmlEncode (Get-FindingDisplayName -Finding $f)
            $severity = if ($f.Severity) { $f.Severity.ToLower() } else { 'standard' }
            $category = ConvertTo-HtmlEncode $group.Name

            $badgeClass = if ($SectionType -eq 'new') { 'badge-new' } else { 'badge-fixed' }
            $badgeText = if ($SectionType -eq 'new') { 'NEW' } else { 'FIXED' }

            [void]$sb.AppendLine("    <div class=`"diff-item`">")
            [void]$sb.AppendLine("      <div class=`"severity-bar $severity`"></div>")
            [void]$sb.AppendLine("      <div class=`"diff-item-name`">$displayName</div>")
            [void]$sb.AppendLine("      <div class=`"diff-item-meta`">$category</div>")
            [void]$sb.AppendLine("      <span class=`"diff-item-badge $badgeClass`">$badgeText</span>")
            [void]$sb.AppendLine('    </div>')
        }
    }

    [void]$sb.AppendLine('  </div>')
    [void]$sb.AppendLine('</section>')
    return $sb.ToString()
}

<#
.SYNOPSIS
    Builds an HTML section for changed findings with before/after details.
#>
function Build-DiffChangedSectionHtml {
    [CmdletBinding()]
    param(
        [string]$Title,
        [array]$ChangedEntries
    )

    $sb = [System.Text.StringBuilder]::new()
    [void]$sb.AppendLine('<section class="section">')
    [void]$sb.AppendLine("  <div class=`"section-header`" onclick=`"toggleSection(this)`">")
    $escapedTitle = ConvertTo-HtmlEncode $Title
    [void]$sb.AppendLine("    <div class=`"section-title`">$escapedTitle <span class=`"section-count`">$($ChangedEntries.Count)</span></div>")
    [void]$sb.AppendLine('    <span class="section-toggle">&#9660;</span>')
    [void]$sb.AppendLine('  </div>')
    [void]$sb.AppendLine('  <div class="section-content">')

    $groups = $ChangedEntries | Group-Object -Property { "$($_.Current.Category) > $($_.Current.CheckTitle)" }
    foreach ($group in ($groups | Sort-Object Name)) {
        foreach ($entry in $group.Group) {
            $displayName = ConvertTo-HtmlEncode (Get-FindingDisplayName -Finding $entry.Current)
            $severity = if ($entry.Current.Severity) { $entry.Current.Severity.ToLower() } else { 'standard' }
            $category = ConvertTo-HtmlEncode $group.Name

            # Build change description
            $changeDesc = @()
            if ($entry.Baseline.Severity -ne $entry.Current.Severity) {
                $changeDesc += "$($entry.Baseline.Severity) &#8594; $($entry.Current.Severity)"
            }
            if ($entry.Current.Type -eq 'KeyValue' -and $entry.Baseline.Value -ne $entry.Current.Value) {
                $oldVal = ConvertTo-HtmlEncode ([string]$entry.Baseline.Value)
                $newVal = ConvertTo-HtmlEncode ([string]$entry.Current.Value)
                if ($oldVal.Length -gt 40) { $oldVal = $oldVal.Substring(0, 37) + '...' }
                if ($newVal.Length -gt 40) { $newVal = $newVal.Substring(0, 37) + '...' }
                $changeDesc += "$oldVal &#8594; $newVal"
            }
            if ($entry.Current.Type -eq 'Line' -and $entry.Baseline.Text -ne $entry.Current.Text) {
                $changeDesc += "text changed"
            }
            $changeHtml = $changeDesc -join ', '

            [void]$sb.AppendLine("    <div class=`"diff-item`">")
            [void]$sb.AppendLine("      <div class=`"severity-bar $severity`"></div>")
            [void]$sb.AppendLine("      <div class=`"diff-item-name`">$displayName <span style=`"font-size:12px;color:var(--text-muted)`">($changeHtml)</span></div>")
            [void]$sb.AppendLine("      <div class=`"diff-item-meta`">$category</div>")
            [void]$sb.AppendLine('      <span class="diff-item-badge badge-changed">CHANGED</span>')
            [void]$sb.AppendLine('    </div>')
        }
    }

    [void]$sb.AppendLine('  </div>')
    [void]$sb.AppendLine('</section>')
    return $sb.ToString()
}

<#
.SYNOPSIS
    Returns the diff HTML template.
.DESCRIPTION
    This function contains the embedded diff report template.
    Template is maintained in templates/diff-template.html and embedded at build time.
#>
function Get-DiffHTMLTemplate {
    return @'
<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>adPEAS Comparison Report - {{DOMAIN}}</title>
    <script>
        (function() {
            try {
                var savedTheme = localStorage.getItem('adpeas-theme');
                if (savedTheme === 'dark' || savedTheme === 'light') {
                    document.documentElement.setAttribute('data-theme', savedTheme);
                }
            } catch (e) {}
        })();
    </script>
    <style>
        /* ============================================================
           adPEAS Diff Report - Embedded Styles
           Color scheme matches the main adPEAS report
           ============================================================ */
        :root {
            --finding: #d32f2f;
            --finding-bg-light: #ffebee;
            --finding-bg-dark: #4a1a1a;
            --hint: #f57c00;
            --hint-bg-light: #fff3e0;
            --hint-bg-dark: #4a3010;
            --note: #388e3c;
            --note-bg-light: #e8f5e9;
            --note-bg-dark: #1a3a1a;
            --secure: #2196f3;
            --secure-bg-light: #e3f2fd;
            --secure-bg-dark: #1a2a4a;
        }

        [data-theme="light"] {
            --bg-main: #e2e8f0;
            --bg-card: #ffffff;
            --bg-header: #1a365d;
            --bg-hover: #f1f5f9;
            --text: #1a202c;
            --text-muted: #64748b;
            --border: #e2e8f0;
            --finding-bg: var(--finding-bg-light);
            --hint-bg: var(--hint-bg-light);
            --note-bg: var(--note-bg-light);
            --secure-bg: var(--secure-bg-light);
        }

        [data-theme="dark"] {
            --bg-main: #0d1117;
            --bg-card: #161b22;
            --bg-header: #21262d;
            --bg-hover: #1c2128;
            --text: #e6edf3;
            --text-muted: #8b949e;
            --border: #30363d;
            --finding-bg: var(--finding-bg-dark);
            --hint-bg: var(--hint-bg-dark);
            --note-bg: var(--note-bg-dark);
            --secure-bg: var(--secure-bg-dark);
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: var(--bg-main);
            color: var(--text);
            line-height: 1.6;
        }

        /* Header */
        .header {
            position: fixed; top: 0; left: 0; right: 0; z-index: 100;
            height: 64px;
            background: var(--bg-header);
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 24px;
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }
        .header-brand {
            display: flex; align-items: center; gap: 12px;
        }
        .header-logo { height: 36px; width: 36px; }
        .header-title { font-size: 20px; font-weight: 700; }
        .header-subtitle { font-size: 13px; color: rgba(255,255,255,0.6); margin-left: 8px; }
        .header-actions { display: flex; gap: 8px; align-items: center; }
        .btn {
            padding: 6px 14px; border-radius: 6px;
            border: 1px solid rgba(255,255,255,0.2);
            background: transparent; color: #fff;
            cursor: pointer; font-size: 13px;
        }
        .btn:hover { background: rgba(255,255,255,0.1); }

        /* Theme toggle */
        .theme-toggle {
            position: relative; width: 52px; height: 28px;
            border-radius: 14px; border: none; cursor: pointer;
            background: #334155; transition: background 0.3s;
        }
        .theme-toggle-slider {
            position: absolute; top: 3px; left: 3px;
            width: 22px; height: 22px; border-radius: 50%;
            background: #fff; transition: transform 0.3s;
        }
        [data-theme="light"] .theme-toggle { background: #93c5fd; }
        [data-theme="light"] .theme-toggle-slider { transform: translateX(24px); }
        .theme-icon { position: absolute; right: 7px; top: 5px; font-size: 14px; }
        [data-theme="light"] .theme-icon { left: 7px; right: auto; }

        /* Main content */
        .main {
            max-width: 1100px;
            margin: 88px auto 40px;
            padding: 0 24px;
        }

        /* Summary cards */
        .summary-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 16px;
            margin-bottom: 24px;
        }
        .summary-card {
            background: var(--bg-card);
            border-radius: 12px;
            padding: 20px;
            border: 1px solid var(--border);
            display: flex;
            align-items: center;
            gap: 16px;
        }
        .summary-card .icon {
            width: 52px; height: 52px;
            border-radius: 12px;
            display: flex; align-items: center; justify-content: center;
            font-size: 22px; font-weight: bold;
        }
        .summary-card .value { font-size: 32px; font-weight: 700; line-height: 1; }
        .summary-card .label { font-size: 13px; color: var(--text-muted); margin-top: 4px; }

        .summary-card.new-findings .icon { background: var(--finding-bg); color: var(--finding); }
        .summary-card.new-findings .value { color: var(--finding); }
        .summary-card.remediated .icon { background: var(--secure-bg); color: var(--secure); }
        .summary-card.remediated .value { color: var(--secure); }
        .summary-card.changed .icon { background: var(--hint-bg); color: var(--hint); }
        .summary-card.changed .value { color: var(--hint); }
        .summary-card.unchanged .icon { background: var(--note-bg); color: var(--note); }
        .summary-card.unchanged .value { color: var(--note); }

        /* Info bar */
        .info-bar {
            display: flex; flex-wrap: wrap; gap: 8px 24px;
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: 14px 20px;
            margin-bottom: 24px;
        }
        .info-item .label { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }
        .info-item .value { font-size: 13px; font-weight: 500; }

        /* Sections */
        .section {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            margin-bottom: 16px;
            overflow: hidden;
        }
        .section-header {
            padding: 14px 20px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
            user-select: none;
        }
        .section-header:hover { background: var(--bg-hover); }
        .section-title {
            font-size: 16px; font-weight: 600;
            display: flex; align-items: center; gap: 10px;
        }
        .section-count {
            font-size: 13px; color: var(--text-muted);
            background: var(--bg-main); border-radius: 12px;
            padding: 2px 10px;
        }
        .section-toggle { font-size: 12px; color: var(--text-muted); transition: transform 0.2s; }
        .section-toggle.collapsed { transform: rotate(-90deg); }
        .section-content { padding: 0 20px 16px; }
        .section-content.hidden { display: none; }

        /* Finding items */
        .diff-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 10px 12px;
            border-radius: 6px;
            margin-bottom: 4px;
        }
        .diff-item:hover { background: var(--bg-hover); }
        .severity-bar {
            width: 4px; height: 28px;
            border-radius: 2px; flex-shrink: 0;
        }
        .severity-bar.finding { background: var(--finding); }
        .severity-bar.hint { background: var(--hint); }
        .severity-bar.note { background: var(--note); }
        .severity-bar.secure { background: var(--secure); }
        .severity-bar.standard { background: var(--text-muted); }
        .diff-item-name { flex: 1; font-size: 14px; }
        .diff-item-meta { font-size: 12px; color: var(--text-muted); }
        .diff-item-badge {
            font-size: 11px; font-weight: 600;
            padding: 2px 8px; border-radius: 4px;
            text-transform: uppercase; letter-spacing: 0.3px;
        }
        .badge-new { background: var(--finding-bg); color: var(--finding); }
        .badge-fixed { background: var(--secure-bg); color: var(--secure); }
        .badge-changed { background: var(--hint-bg); color: var(--hint); }

        /* Scope info */
        .scope-info {
            padding: 14px 16px;
            background: var(--bg-hover);
            border-radius: 6px;
            font-size: 13px;
            color: var(--text-muted);
            line-height: 1.8;
        }
        .scope-info strong { color: var(--text); }

        /* Empty state */
        .empty-state {
            text-align: center;
            padding: 20px;
            color: var(--text-muted);
            font-size: 14px;
        }

        /* Print */
        @media print {
            .header { position: static; }
            .main { margin-top: 16px; }
            .section { break-inside: avoid; }
            .btn, .theme-toggle { display: none; }
        }

        /* Responsive */
        @media (max-width: 768px) {
            .summary-grid { grid-template-columns: repeat(2, 1fr); }
            .info-bar { flex-direction: column; }
        }
    </style>
</head>
<body>
    <header class="header" role="banner">
        <div class="header-brand">
            <img class="header-logo" src="data:image/png;base64," alt="adPEAS Logo">
            <span class="header-title">adPEAS</span>
            <span class="header-subtitle">Comparison Report</span>
        </div>
        <div class="header-actions">
            <button class="theme-toggle" onclick="toggleTheme()" aria-label="Toggle theme">
                <span class="theme-toggle-slider"></span>
                <span class="theme-icon" aria-hidden="true">&#9788;</span>
            </button>
            <button class="btn" onclick="window.print()">Print / PDF</button>
        </div>
    </header>

    <main class="main">
        <div class="summary-grid">
            <div class="summary-card new-findings">
                <div class="icon" aria-hidden="true">&#33;</div>
                <div>
                    <div class="value">{{NEW_COUNT}}</div>
                    <div class="label">New</div>
                </div>
            </div>
            <div class="summary-card remediated">
                <div class="icon" aria-hidden="true">&#10003;</div>
                <div>
                    <div class="value">{{REMEDIATED_COUNT}}</div>
                    <div class="label">Remediated</div>
                </div>
            </div>
            <div class="summary-card changed">
                <div class="icon" aria-hidden="true">&#9650;</div>
                <div>
                    <div class="value">{{CHANGED_COUNT}}</div>
                    <div class="label">Changed</div>
                </div>
            </div>
            <div class="summary-card unchanged">
                <div class="icon" aria-hidden="true">&#9679;</div>
                <div>
                    <div class="value">{{UNCHANGED_COUNT}}</div>
                    <div class="label">Unchanged</div>
                </div>
            </div>
        </div>

        <div class="info-bar">
            <div class="info-item">
                <div class="label">Baseline</div>
                <div class="value">{{BASELINE_INFO}}</div>
            </div>
            <div class="info-item">
                <div class="label">Current</div>
                <div class="value">{{CURRENT_INFO}}</div>
            </div>
            <div class="info-item">
                <div class="label">Compared</div>
                <div class="value">{{COMPARED_CATEGORIES}}</div>
            </div>
            <div class="info-item">
                <div class="label">Generated</div>
                <div class="value">{{GENERATED}}</div>
            </div>
            <div class="info-item">
                <div class="label">Version</div>
                <div class="value">{{VERSION}}</div>
            </div>
        </div>

        {{DIFF_SECTIONS}}
    </main>

    <script>
        function toggleTheme() {
            var current = document.documentElement.getAttribute('data-theme');
            var next = current === 'dark' ? 'light' : 'dark';
            document.documentElement.setAttribute('data-theme', next);
            try { localStorage.setItem('adpeas-theme', next); } catch (e) {}
        }
        function toggleSection(el) {
            var content = el.parentElement.querySelector('.section-content');
            var toggle = el.querySelector('.section-toggle');
            if (content.classList.contains('hidden')) {
                content.classList.remove('hidden');
                toggle.classList.remove('collapsed');
            } else {
                content.classList.add('hidden');
                toggle.classList.add('collapsed');
            }
        }
    </script>
</body>
</html>

'@
}




# ==============================================
# COLLECTOR MODULES
# ==============================================

# ----- Invoke-adPEASCollector.ps1 -----

function Invoke-adPEASCollector {
<#
.SYNOPSIS
    BloodHound-compatible data collector for adPEAS v2.

.DESCRIPTION
    Collects Active Directory data and exports it in BloodHound-compatible JSON format.
    This is a DCOnly implementation focusing on LDAP-based collection:

    Collected Data:
    - Users (with properties, SPNs, delegation settings)
    - Groups (with members and ACEs)
    - Computers (with properties and delegation)
    - Domains (with trusts and properties)
    - OUs (with properties and links)
    - Containers (CN=Users, CN=Computers, etc.)
    - GPOs (with links and properties)
    - Certificate Templates (ADCS)
    - Enterprise CAs (ADCS)
    - Root CAs (ADCS)
    - AIA CAs (ADCS)
    - NTAuth Stores (ADCS)
    - Issuance Policies (ADCS)

    NOT included (requires Win32 API):
    - Session collection (NetSessionEnum)
    - Local group membership (NetLocalGroupGetMembers)

    Output Format:
    - BloodHound CE compatible JSON (version 6)
    - Packaged as ZIP file

.PARAMETER Domain
    Target domain to collect (optional, uses current session domain).

.PARAMETER Server
    Specific Domain Controller to query.

.PARAMETER Credential
    PSCredential for authentication.

.PARAMETER OutputPath
    Path for output ZIP file. Default: current directory.

.PARAMETER CollectionMethod
    What to collect. Default: DCOnly
    Options: DCOnly, ACL, ObjectProps, Trusts, Container, CertServices

    DCOnly collects everything available via LDAP (users, groups, computers,
    domains, OUs, containers, GPOs, ADCS objects, ACLs). The other options allow partial collection.

.PARAMETER NoZip
    Output individual JSON files instead of ZIP.

.PARAMETER PrettyPrint
    Format JSON with indentation (larger files but readable).

.EXAMPLE
    Invoke-adPEASCollector -OutputPath .\bloodhound_data.zip

.EXAMPLE
    Invoke-adPEASCollector -Domain "contoso.com" -Credential (Get-Credential)

.EXAMPLE
    Invoke-adPEASCollector -CollectionMethod ObjectProps -NoZip
    Collects only object properties (no ACLs) for faster collection.

.NOTES
    Category: Collector
    Author: Alexander Sturz (@_61106960_)
#>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false)]
        [string]$OutputPath,

        [Parameter(Mandatory=$false)]
        [ValidateSet('DCOnly', 'ACL', 'ObjectProps', 'Trusts', 'Container', 'CertServices')]
        [string]$CollectionMethod = 'DCOnly',

        [Parameter(Mandatory=$false)]
        [switch]$NoZip,

        [Parameter(Mandatory=$false)]
        [switch]$PrettyPrint
    )

    begin {
        Write-Log "[Invoke-adPEASCollector] Starting collection"
        $Script:CollectorVersion = "1.0.0"
        $Script:JsonVersion = 6
        $Script:CollectionTimestamp = Get-Date -Format "yyyyMMddHHmmss"
    }

    process {
        try {
            # Build connection params for Collect-BH* functions (they don't accept OutputPath, CollectionMethod, etc.)
            $connectionParams = @{}
            if ($Domain) { $connectionParams['Domain'] = $Domain }
            if ($Server) { $connectionParams['Server'] = $Server }
            if ($Credential) { $connectionParams['Credential'] = $Credential }

            if (-not (Ensure-LDAPConnection @connectionParams)) {
                return
            }

            $domainName = $Script:LDAPContext.Domain.ToUpper()
            $domainDN = $Script:LDAPContext.DomainDN
            $domainSID = $null

            Show-SubHeader "Collecting BloodHound CE data..." -ObjectType "BloodHoundCollector"

            # Get Domain SID
            $domainObj = @(Get-DomainObject -LDAPFilter "(distinguishedName=$domainDN)" @connectionParams)[0]

            if ($domainObj.objectSid) {
                $domainSID = Convert-SidToString -SidInput $domainObj.objectSid
            }

            $defaultFileName = "$($Script:CollectionTimestamp)_$($domainName)_BloodHound.zip"

            if ([string]::IsNullOrEmpty($OutputPath)) {
                $OutputPath = Join-Path (Get-Location) $defaultFileName
            }
            elseif (Test-Path $OutputPath -PathType Container) {
                # OutputPath is an existing directory - append default filename
                $OutputPath = Join-Path $OutputPath $defaultFileName
                Write-Log "[Invoke-adPEASCollector] Output directory specified, using: $OutputPath"
            }
            elseif ($OutputPath -match '[\\/]$') {
                # OutputPath ends with slash - treat as directory
                if (-not (Test-Path $OutputPath)) {
                    New-Item -ItemType Directory -Path $OutputPath -Force | Out-Null
                }
                $OutputPath = Join-Path $OutputPath $defaultFileName
                Write-Log "[Invoke-adPEASCollector] Output directory specified, using: $OutputPath"
            }

            $tempDir = Join-Path $env:TEMP "adPEAS_BH_$Script:CollectionTimestamp"
            if (-not (Test-Path $tempDir)) {
                New-Item -ItemType Directory -Path $tempDir -Force | Out-Null
            }

            Write-Log "[Invoke-adPEASCollector] Temporary directory: $tempDir"

            $collectedData = @{
                Users             = @()
                Groups            = @()
                Computers         = @()
                Domains           = @()
                OUs               = @()
                Containers        = @()
                GPOs              = @()
                CertTemplates     = @()
                EnterpriseCAs     = @()
                RootCAs           = @()
                AIACAs            = @()
                NTAuthStores      = @()
                IssuancePolicies  = @()
            }

            # Determine what to collect based on CollectionMethod
            $collectUsers = $CollectionMethod -in @('DCOnly', 'ObjectProps', 'ACL')
            $collectGroups = $CollectionMethod -in @('DCOnly', 'ObjectProps', 'ACL')
            $collectComputers = $CollectionMethod -in @('DCOnly', 'ObjectProps', 'ACL')
            $collectDomains = $CollectionMethod -in @('DCOnly', 'Trusts')
            $collectOUs = $CollectionMethod -in @('DCOnly', 'Container', 'ACL')
            $collectContainers = $CollectionMethod -in @('DCOnly', 'Container')
            $collectGPOs = $CollectionMethod -in @('DCOnly', 'Container', 'ACL')
            $collectACLs = $CollectionMethod -in @('DCOnly', 'ACL')
            $collectADCS = $CollectionMethod -in @('DCOnly', 'ACL', 'CertServices')

            # Count total collection steps for progress display
            $totalSteps = 0
            if ($collectDomains) { $totalSteps++ }          # Domain
            if ($collectUsers) { $totalSteps++ }            # Users
            if ($collectGroups) { $totalSteps++ }           # Groups
            if ($collectComputers) { $totalSteps++ }        # Computers
            if ($collectOUs) { $totalSteps++ }              # OUs
            if ($collectContainers) { $totalSteps++ }       # Containers
            if ($collectGPOs) { $totalSteps++ }             # GPOs
            if ($collectADCS) { $totalSteps += 6 }          # 6 ADCS object types
            $totalSteps++                                    # Writing JSON
            $currentStep = 0
            $Script:CollectedParts = [System.Collections.Generic.List[string]]::new()

            # Progress display: two dynamic lines
            # Line 1: "Collected: 1 domain, 30 users, 76 groups" (grows with each step)
            # Line 2: "Collecting: Computers...  [4/14]" (active step, overwritten)
            $Script:ProgressPadWidth = 100

            # ANSI escape character (PowerShell 5.1 compatible - `e only works in PS7+)
            $esc = [char]0x1B
            $Script:CursorUp = "$esc[1A"
            $Script:CursorDown = "$esc[1B"

            # Helper function (defined in Script scope for catch block access)
            $Script:WriteCollectionStatus = {
                param([string]$Status, [int]$Step, [int]$Total, [switch]$Complete, [switch]$Init)
                $pw = $Script:ProgressPadWidth
                $up = $Script:CursorUp
                $dn = $Script:CursorDown
                if ($Init) {
                    # Print initial two lines (collected + active)
                    Write-Host "Collected: (starting...)".PadRight($pw) -NoNewline -ForegroundColor DarkGray
                    Write-Host ""
                    Write-Host "Collecting: $Status".PadRight($pw) -NoNewline
                } elseif ($Complete) {
                    # Clear both lines: clear active line, move up, clear collected line
                    Write-Host "`r$(' ' * $pw)" -NoNewline
                    Write-Host "$up`r$(' ' * $pw)$dn`r" -NoNewline
                    # Move cursor back up to the collected line for final output
                    Write-Host "$up`r" -NoNewline
                } else {
                    # Update both lines: move up to collected line, update it, move down, update active
                    $collectedLine = if ($Script:CollectedParts.Count -gt 0) {
                        "Collected: $($Script:CollectedParts -join ', ')"
                    } else {
                        "Collected: (starting...)"
                    }
                    $activeLine = "Collecting: $Status  [$Step/$Total]"
                    Write-Host "$up`r$($collectedLine.PadRight($pw))" -NoNewline -ForegroundColor DarkGray
                    Write-Host "$dn`r$($activeLine.PadRight($pw))" -NoNewline
                }
            }

            # Local wrapper functions
            function Write-CollectionStatus {
                param([string]$Status, [switch]$Complete, [switch]$Init)
                & $Script:WriteCollectionStatus -Status $Status -Step $currentStep -Total $totalSteps -Complete:$Complete -Init:$Init
            }
            function Add-CollectedPart {
                param([string]$Label, [int]$Count)
                if ($Count -gt 0) { $Script:CollectedParts.Add("$Count $Label") }
            }

            # Build caches for SPN resolution, DN-to-identity mapping, and ADCS template mapping
            Write-CollectionStatus -Init "Building caches..."
            Build-ComputerHostnameCache -ConnectionParams $connectionParams
            Build-DNIdentityCache -ConnectionParams $connectionParams
            if ($collectADCS) {
                Build-TemplateCNToOIDCache -ConnectionParams $connectionParams
            }

            # ----- Collect Domain -----
            if ($collectDomains) {
                $currentStep++
                Write-CollectionStatus "Domain..."
                $collectedData.Domains = @(Collect-BHDomain -DomainDN $domainDN -DomainSID $domainSID @connectionParams)
                Add-CollectedPart -Label "domains" -Count @($collectedData.Domains).Count
            }

            # ----- Collect Users -----
            if ($collectUsers) {
                $currentStep++
                Write-CollectionStatus "Users..."
                $collectedData.Users = @(Collect-BHUsers -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)
                Add-CollectedPart -Label "users" -Count @($collectedData.Users).Count
            }

            # ----- Collect Groups -----
            if ($collectGroups) {
                $currentStep++
                Write-CollectionStatus "Groups..."
                $collectedData.Groups = @(Collect-BHGroups -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)
                Add-CollectedPart -Label "groups" -Count @($collectedData.Groups).Count
            }

            # ----- Collect Computers -----
            if ($collectComputers) {
                $currentStep++
                Write-CollectionStatus "Computers..."
                $collectedData.Computers = @(Collect-BHComputers -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)
                Add-CollectedPart -Label "computers" -Count @($collectedData.Computers).Count
            }

            # ----- Collect OUs -----
            if ($collectOUs) {
                $currentStep++
                Write-CollectionStatus "OUs..."
                $collectedData.OUs = @(Collect-BHOUs -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)
                Add-CollectedPart -Label "OUs" -Count @($collectedData.OUs).Count
            }

            # ----- Collect Containers -----
            if ($collectContainers) {
                $currentStep++
                Write-CollectionStatus "Containers..."
                $collectedData.Containers = @(Collect-BHContainers -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)
                Add-CollectedPart -Label "containers" -Count @($collectedData.Containers).Count
            }

            # ----- Collect GPOs -----
            if ($collectGPOs) {
                $currentStep++
                Write-CollectionStatus "GPOs..."
                $collectedData.GPOs = @(Collect-BHGPOs -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)
                Add-CollectedPart -Label "GPOs" -Count @($collectedData.GPOs).Count
            }

            # ----- Collect ADCS Objects -----
            if ($collectADCS) {
                $currentStep++
                Write-CollectionStatus "Certificate Templates..."
                $collectedData.CertTemplates = @(Collect-BHCertTemplates -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)

                $currentStep++
                Write-CollectionStatus "Enterprise CAs..."
                $collectedData.EnterpriseCAs = @(Collect-BHEnterpriseCAs -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)

                $currentStep++
                Write-CollectionStatus "Root CAs..."
                $collectedData.RootCAs = @(Collect-BHRootCAs -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)

                $currentStep++
                Write-CollectionStatus "AIA CAs..."
                $collectedData.AIACAs = @(Collect-BHAIACAs -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)

                $currentStep++
                Write-CollectionStatus "NTAuth Stores..."
                $collectedData.NTAuthStores = @(Collect-BHNTAuthStores -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)

                $currentStep++
                Write-CollectionStatus "Issuance Policies..."
                $collectedData.IssuancePolicies = @(Collect-BHIssuancePolicies -DomainSID $domainSID -CollectACLs:$collectACLs @connectionParams)

                # Add combined ADCS count
                $adcsTotal = @($collectedData.CertTemplates).Count + @($collectedData.EnterpriseCAs).Count +
                             @($collectedData.RootCAs).Count + @($collectedData.AIACAs).Count +
                             @($collectedData.NTAuthStores).Count + @($collectedData.IssuancePolicies).Count
                Add-CollectedPart -Label "ADCS objects" -Count $adcsTotal
            }

            # ----- Write JSON -----
            $currentStep++
            Write-CollectionStatus "Writing JSON..."

            # Write JSON Files

            $jsonFiles = @()

            if (@($collectedData.Users).Count -gt 0) {
                $usersFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_users.json"
                Write-BHJsonFile -Data $collectedData.Users -Type "users" -FilePath $usersFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $usersFile
            }

            if (@($collectedData.Groups).Count -gt 0) {
                $groupsFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_groups.json"
                Write-BHJsonFile -Data $collectedData.Groups -Type "groups" -FilePath $groupsFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $groupsFile
            }

            if (@($collectedData.Computers).Count -gt 0) {
                $computersFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_computers.json"
                Write-BHJsonFile -Data $collectedData.Computers -Type "computers" -FilePath $computersFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $computersFile
            }

            if (@($collectedData.Domains).Count -gt 0) {
                $domainsFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_domains.json"
                Write-BHJsonFile -Data $collectedData.Domains -Type "domains" -FilePath $domainsFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $domainsFile
            }

            if (@($collectedData.OUs).Count -gt 0) {
                $ousFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_ous.json"
                Write-BHJsonFile -Data $collectedData.OUs -Type "ous" -FilePath $ousFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $ousFile
            }

            if (@($collectedData.Containers).Count -gt 0) {
                $containersFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_containers.json"
                Write-BHJsonFile -Data $collectedData.Containers -Type "containers" -FilePath $containersFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $containersFile
            }

            if (@($collectedData.GPOs).Count -gt 0) {
                $gposFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_gpos.json"
                Write-BHJsonFile -Data $collectedData.GPOs -Type "gpos" -FilePath $gposFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $gposFile
            }

            if (@($collectedData.CertTemplates).Count -gt 0) {
                $certTemplatesFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_certtemplates.json"
                Write-BHJsonFile -Data $collectedData.CertTemplates -Type "certtemplates" -FilePath $certTemplatesFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $certTemplatesFile
            }

            if (@($collectedData.EnterpriseCAs).Count -gt 0) {
                $enterpriseCAsFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_enterprisecas.json"
                Write-BHJsonFile -Data $collectedData.EnterpriseCAs -Type "enterprisecas" -FilePath $enterpriseCAsFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $enterpriseCAsFile
            }

            if (@($collectedData.RootCAs).Count -gt 0) {
                $rootCAsFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_rootcas.json"
                Write-BHJsonFile -Data $collectedData.RootCAs -Type "rootcas" -FilePath $rootCAsFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $rootCAsFile
            }

            if (@($collectedData.AIACAs).Count -gt 0) {
                $aiaCAsFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_aiacas.json"
                Write-BHJsonFile -Data $collectedData.AIACAs -Type "aiacas" -FilePath $aiaCAsFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $aiaCAsFile
            }

            if (@($collectedData.NTAuthStores).Count -gt 0) {
                $ntAuthStoresFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_ntauthstores.json"
                Write-BHJsonFile -Data $collectedData.NTAuthStores -Type "ntauthstores" -FilePath $ntAuthStoresFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $ntAuthStoresFile
            }

            if (@($collectedData.IssuancePolicies).Count -gt 0) {
                $issuancePoliciesFile = Join-Path $tempDir "$($Script:CollectionTimestamp)_issuancepolicies.json"
                Write-BHJsonFile -Data $collectedData.IssuancePolicies -Type "issuancepolicies" -FilePath $issuancePoliciesFile -PrettyPrint:$PrettyPrint
                $jsonFiles += $issuancePoliciesFile
            }

            # Clear the active status line
            Write-CollectionStatus -Complete

            # Create ZIP or Copy Files
            if ($NoZip) {
                $outputDir = Split-Path $OutputPath -Parent
                if ([string]::IsNullOrEmpty($outputDir)) {
                    $outputDir = Get-Location
                }
                foreach ($file in $jsonFiles) {
                    Copy-Item -Path $file -Destination $outputDir -Force
                }
            }
            else {
                if (Test-Path $OutputPath -PathType Leaf) {
                    # Only delete if it's a file, not a directory
                    Remove-Item $OutputPath -Force
                }
                elseif (Test-Path $OutputPath -PathType Container) {
                    Write-Warning "OutputPath '$OutputPath' is a directory. Adding default filename."
                    $OutputPath = Join-Path $OutputPath "$($Script:CollectionTimestamp)_BloodHound.zip"
                }

                # Ensure output directory exists
                $outputDir = Split-Path $OutputPath -Parent
                if (-not [string]::IsNullOrEmpty($outputDir) -and -not (Test-Path $outputDir)) {
                    New-Item -ItemType Directory -Path $outputDir -Force | Out-Null
                }

                Add-Type -AssemblyName System.IO.Compression.FileSystem
                [System.IO.Compression.ZipFile]::CreateFromDirectory($tempDir, $OutputPath)
            }

            # Cleanup temp directory
            Remove-Item -Path $tempDir -Recurse -Force -ErrorAction SilentlyContinue

            $totalObjects = @($collectedData.Users).Count + @($collectedData.Groups).Count + @($collectedData.Computers).Count +
                           @($collectedData.OUs).Count + @($collectedData.Containers).Count + @($collectedData.GPOs).Count +
                           @($collectedData.CertTemplates).Count + @($collectedData.EnterpriseCAs).Count +
                           @($collectedData.RootCAs).Count + @($collectedData.AIACAs).Count +
                           @($collectedData.NTAuthStores).Count + @($collectedData.IssuancePolicies).Count

            $summaryString = $Script:CollectedParts -join ", "

            Show-Line "Collected $totalObjects objects from $domainName`: $summaryString" -Class Hint -FindingId 'BLOODHOUND_COLLECTION_COMPLETE'

            if ($NoZip) {
                Show-Line "Output: $outputDir (JSON files)" -Class Note
            }
            else {
                $outputFileName = Split-Path $OutputPath -Leaf
                Show-Line "Output: $outputFileName" -Class Note
            }
        }
        catch {
            $collectStack = $_.ScriptStackTrace
            Write-Log "[Invoke-adPEASCollector] Collection failed: $_" -Level Error
            Write-Log $collectStack
            # Clear the inline progress lines using Script-scope function
            if ($Script:WriteCollectionStatus) {
                & $Script:WriteCollectionStatus -Complete -Step 0 -Total 0
            }
            Write-Warning "[Invoke-adPEASCollector] BloodHound collection failed: $_"
            # Surface the failure origin without requiring -Verbose. The full stack trace above
            # only reaches the verbose stream; a collection failure should always be diagnosable,
            # so show the top frames (function + line) that raised the error.
            if ($collectStack) {
                $topFrames = (($collectStack -split "`r?`n" | Where-Object { $_ -match '\S' }) | Select-Object -First 3) -join [Environment]::NewLine
                Write-Warning "[Invoke-adPEASCollector] Failure origin (top of stack):$([Environment]::NewLine)$topFrames"
            }
        }
    }
    end {
        # Clean up caches to free memory
        $Script:DNToIdentityCache = $null
        $Script:ParentDNToChildren = $null
        $Script:ComputerHostnameCache = $null
        $Script:TemplateCNToOID = $null
        Write-Log "[Invoke-adPEASCollector] Collection completed"
    }
}

<#
.SYNOPSIS
    Safely gets an integer value from an AD property that might be an array or single value.
#>
function Get-SafeInt {
    param(
        $Value,
        [int]$Default = 0
    )

    if ($null -eq $Value) {
        return $Default
    }

    # If it's an array, take the first element
    if ($Value -is [array]) {
        $Value = $Value[0]
    }

    try {
        return [int]$Value
    }
    catch {
        Write-Log "[Get-SafeInt] Failed to convert value to int: $_" -Level Debug
        return $Default
    }
}


<#
.SYNOPSIS
    Converts various SID input formats to string representation.
.DESCRIPTION
    Handles SID input as byte array, string (SID format S-1-...), or SecurityIdentifier object.
#>
function Convert-SidToString {
    param(
        [Parameter(Mandatory=$true)]
        $SidInput
    )

    try {
        # Already a string in SID format
        if ($SidInput -is [string]) {
            if ($SidInput -match '^S-1-') {
                return $SidInput
            }
            # Try to parse as SecurityIdentifier from string
            return (New-Object System.Security.Principal.SecurityIdentifier($SidInput)).Value
        }

        # Byte array
        if ($SidInput -is [byte[]]) {
            return (New-Object System.Security.Principal.SecurityIdentifier($SidInput, 0)).Value
        }

        # SecurityIdentifier object
        if ($SidInput -is [System.Security.Principal.SecurityIdentifier]) {
            return $SidInput.Value
        }

        # Array of bytes (sometimes returned as object[])
        if ($SidInput -is [array]) {
            $bytes = [byte[]]$SidInput
            return (New-Object System.Security.Principal.SecurityIdentifier($bytes, 0)).Value
        }

        # Fallback: try direct conversion
        return (New-Object System.Security.Principal.SecurityIdentifier($SidInput, 0)).Value
    }
    catch {
        Write-Log "[Convert-SidToString] Failed to convert SID: $_"
        return $null
    }
}


<#
.SYNOPSIS
    Converts PKI period byte array (FILETIME interval) to ISO 8601 duration string.
.DESCRIPTION
    PKI attributes like pKIExpirationPeriod and pKIOverlapPeriod are stored as 8-byte
    negative FILETIME intervals (100-nanosecond units). This function converts them to
    ISO 8601 duration strings for BloodHound CE (e.g., "P2Y", "P90D", "PT6H").
#>
function ConvertTo-ISODuration {
    param([byte[]]$PeriodBytes)

    if (-not $PeriodBytes -or $PeriodBytes.Length -ne 8) { return "P0D" }

    try {
        $int64Value = [BitConverter]::ToInt64($PeriodBytes, 0)
        $seconds = [Math]::Abs($int64Value) / 10000000

        if ($seconds -ge 31536000) {
            $years = [Math]::Floor($seconds / 31536000)
            return "P${years}Y"
        }
        elseif ($seconds -ge 86400) {
            $days = [Math]::Floor($seconds / 86400)
            return "P${days}D"
        }
        elseif ($seconds -ge 3600) {
            $hours = [Math]::Floor($seconds / 3600)
            return "PT${hours}H"
        }
        else {
            $minutes = [Math]::Floor($seconds / 60)
            if ($minutes -le 0) { $minutes = 1 }
            return "PT${minutes}M"
        }
    }
    catch {
        Write-Log "[ConvertTo-ISODuration] Error converting period bytes: $_" -Level Debug
        return "P0D"
    }
}


<#
.SYNOPSIS
    Parses X509 certificate properties from DER-encoded byte array.
.DESCRIPTION
    Extracts thumbprint, subject name, basic constraints and path length from a
    DER-encoded certificate (cACertificate attribute).
#>
function Get-CertificateProperties {
    param([byte[]]$CertificateBytes)

    $defaultResult = @{ Thumbprint = ""; Name = ""; HasBasicConstraints = $false; PathLength = 0 }

    if (-not $CertificateBytes -or $CertificateBytes.Length -eq 0) {
        return $defaultResult
    }

    try {
        $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(,$CertificateBytes)
        $thumbprint = $cert.Thumbprint
        $subject = $cert.Subject

        # Parse basic constraints extension
        $hasBC = $false
        $pathLen = 0
        foreach ($ext in $cert.Extensions) {
            if ($ext.Oid.Value -eq '2.5.29.19') {
                $hasBC = $true
                $bcExt = [System.Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]$ext
                if ($bcExt.HasPathLengthConstraint) {
                    $pathLen = $bcExt.PathLengthConstraint
                }
                break
            }
        }

        return @{
            Thumbprint          = $thumbprint
            Name                = $subject
            HasBasicConstraints = $hasBC
            PathLength          = $pathLen
        }
    }
    catch {
        Write-Log "[Get-CertificateProperties] Error parsing certificate: $_" -Level Debug
        return $defaultResult
    }
}


<#
.SYNOPSIS
    Builds a hostname-to-SID cache from all computer objects for efficient SPN resolution.
.DESCRIPTION
    Queries all domain computers once and caches dNSHostName/sAMAccountName to SID mappings.
    Used by Resolve-SPNToTarget for AllowedToDelegate and SPNTargets resolution.
#>
function Build-ComputerHostnameCache {
    param([hashtable]$ConnectionParams = @{})

    # Use $null check, not truthiness: an empty @{} left by Clear-SessionState is truthy and would
    # make this skip the rebuild, leaving SPN/delegation resolution running on an empty cache.
    if ($null -ne $Script:ComputerHostnameCache) { return }
    $Script:ComputerHostnameCache = @{}

    $computers = Get-DomainComputer -Properties sAMAccountName,dNSHostName,objectSid @ConnectionParams

    foreach ($comp in @($computers)) {
        if ($comp.objectSid) {
            $sid = Convert-SidToString -SidInput $comp.objectSid
            if ($sid) {
                if ($comp.dNSHostName) {
                    $Script:ComputerHostnameCache[$comp.dNSHostName.ToLower()] = $sid
                }
                if ($comp.sAMAccountName) {
                    $shortName = $comp.sAMAccountName.TrimEnd('$').ToLower()
                    $Script:ComputerHostnameCache[$shortName] = $sid
                }
            }
        }
    }

    Write-Log "[Build-ComputerHostnameCache] Cached $($Script:ComputerHostnameCache.Count) hostname-to-SID mappings"
}


<#
.SYNOPSIS
    Pre-builds DN-to-identity and parent-to-children caches for all domain objects.
.DESCRIPTION
    Performs a single bulk LDAP query to fetch all security-relevant objects with minimal
    properties and builds two lookup hashtables:
    - DNToIdentityCache: Maps DN to {ObjectIdentifier, ObjectType} for group member resolution
    - ParentDNToChildren: Maps parent DN to list of direct child identities for OU/Container child objects

    This eliminates the N+1 query anti-pattern where each OU/Container issued 4 separate
    subtree queries, and each group member required an individual LDAP lookup.
#>
function Build-DNIdentityCache {
    param([hashtable]$ConnectionParams = @{})

    # Both caches are built together and must be rebuilt together. Require BOTH to be non-null:
    # a half-built state (e.g. DNToIdentityCache reset to @{} by Clear-SessionState while
    # ParentDNToChildren is $null) would otherwise skip the rebuild and later crash Collect-BHOUs.
    # Note @{} is truthy, so checking a single cache is not enough to detect "not built".
    if ($null -ne $Script:DNToIdentityCache -and $null -ne $Script:ParentDNToChildren) { return }
    $Script:DNToIdentityCache = @{}
    $Script:ParentDNToChildren = @{}

    # Single bulk query: all security-relevant objects with minimal properties
    # objectClass=user also matches computers (AD class hierarchy: computer inherits from user)
    # Get-BHObjectType distinguishes via $ObjectClass[-1] (most specific class)
    $allObjects = Get-DomainObject -LDAPFilter "(|(objectClass=user)(objectClass=group)(objectClass=organizationalUnit)(objectClass=container)(objectClass=groupPolicyContainer))" `
        -Properties 'distinguishedName','objectSid','objectGuid','objectClass','name' @ConnectionParams

    foreach ($obj in @($allObjects)) {
        $dn = $obj.distinguishedName
        if (-not $dn) { continue }

        $objType = Get-BHObjectType -ObjectClass $obj.objectClass
        $objId = $null
        if ($obj.objectSid) {
            $objId = Convert-SidToString -SidInput $obj.objectSid
        } elseif ($obj.objectGuid) {
            $objId = $obj.objectGuid.ToString().ToUpper()
        }
        if (-not $objId) { continue }

        # DN -> Identity mapping (for group member resolution)
        $Script:DNToIdentityCache[$dn] = @{
            ObjectIdentifier = $objId
            ObjectType       = $objType
        }

        # Parent DN -> Children mapping (for OU/Container/Domain child objects)
        $parentDN = $dn -replace '^[^,]+,', ''
        if (-not $Script:ParentDNToChildren.ContainsKey($parentDN)) {
            $Script:ParentDNToChildren[$parentDN] = [System.Collections.Generic.List[hashtable]]::new()
        }
        $Script:ParentDNToChildren[$parentDN].Add(@{
            ObjectIdentifier = $objId
            ObjectType       = $objType
        })
    }

    Write-Log "[Build-DNIdentityCache] Cached $($Script:DNToIdentityCache.Count) objects, $($Script:ParentDNToChildren.Count) parent groups"
}


# Helper: Convert objectGUID (byte[] or Guid) to uppercase GUID string
function ConvertTo-BHGuid {
    param([object]$Value)
    if ($null -eq $Value) { return "" }
    try {
        if ($Value -is [byte[]] -and $Value.Length -eq 16) { return ([Guid]$Value).ToString().ToUpper() }
        if ($Value -is [array] -and $Value.Count -eq 16) { return ([Guid][byte[]]$Value).ToString().ToUpper() }
        return $Value.ToString().ToUpper()
    } catch { return "" }
}

# Helper: Convert AD negative 100-ns interval to human-readable string
# 0 or near-MaxValue = "Forever"
function Convert-ADIntervalToString {
    param([object]$Value)
    if ($null -eq $Value) { return "Forever" }
    try {
        $int64Val = [Int64]$Value
        if ($int64Val -eq 0) { return "Forever" }
        if ([Math]::Abs($int64Val) -ge 9223372036854775000) { return "Forever" }
        $seconds = [Math]::Abs($int64Val) / 10000000
        $ts = [TimeSpan]::FromSeconds($seconds)
        if ($ts.TotalDays -ge 1) {
            $d = [int]$ts.TotalDays
            return "$d day$(if ($d -ne 1) {'s'})"
        } elseif ($ts.TotalHours -ge 1) {
            $h = [int]$ts.TotalHours
            return "$h hour$(if ($h -ne 1) {'s'})"
        } else {
            $m = [int]$ts.TotalMinutes
            return "$m minute$(if ($m -ne 1) {'s'})"
        }
    } catch { return "Forever" }
}

# Helper: Convert ADCS certificate name flag integer to string (BH CE expects string, not int)
function Convert-CertNameFlagToString {
    param([int]$Value)
    return [string]$Value
}

# Helper: Convert ADCS enrollment flag integer to string (BH CE expects string, not int)
function Convert-EnrollFlagToString {
    param([int]$Value)
    return [string]$Value
}

# Helper: Convert CA flag integer to string (BH CE expects string, not int)
function Convert-CAFlagToString {
    param([int]$Value)
    return [string]$Value
}


# Helper: Get ContainedBy for objects in the Configuration partition
# Looks up the parent container's GUID via LDAP (one lookup per unique parent)
function Get-BHContainedByConfig {
    param([string]$DistinguishedName)
    if (-not $DistinguishedName) { return $null }
    if ($DistinguishedName -notmatch '^[^,]+,(.+)$') { return $null }
    $parentDN = $Matches[1]
    # Use a script-level cache to avoid repeated LDAP lookups
    if (-not $Script:ConfigContainerGuidCache) { $Script:ConfigContainerGuidCache = @{} }
    if ($Script:ConfigContainerGuidCache.ContainsKey($parentDN)) {
        $cachedGuid = $Script:ConfigContainerGuidCache[$parentDN]
        if ($cachedGuid) { return @{ ObjectIdentifier = $cachedGuid; ObjectType = 'Container' } }
        return $null
    }
    try {
        $escapedParentDN = Escape-LDAPFilterDN -DistinguishedName $parentDN
        $parentObj = @(Invoke-LDAPSearch -Filter "(distinguishedName=$escapedParentDN)" -SearchBase $parentDN -Properties objectGUID -Scope Base)[0]
        if ($parentObj -and $parentObj.objectGUID) {
            $guid = ConvertTo-BHGuid -Value $parentObj.objectGUID
            $Script:ConfigContainerGuidCache[$parentDN] = $guid
            if ($guid) { return @{ ObjectIdentifier = $guid; ObjectType = 'Container' } }
        }
    } catch { Write-Log "[Get-BHContainedByConfig] LDAP lookup failed for '$parentDN': $_" -Level Debug }
    $Script:ConfigContainerGuidCache[$parentDN] = ""
    return $null
}


<#
.SYNOPSIS
    Resolves an SPN to a computer SID using the pre-built hostname cache.
.DESCRIPTION
    Extracts the hostname from an SPN (format: service/hostname or service/hostname:port)
    and looks it up in the ComputerHostnameCache to find the computer SID.
#>
function Resolve-SPNToTarget {
    param([string]$SPN)

    if (-not $SPN -or -not $Script:ComputerHostnameCache) { return $null }

    # Extract hostname from SPN (service/hostname or service/hostname:port)
    if ($SPN -match '^[^/]+/([^:/]+)') {
        $hostname = $Matches[1].ToLower()

        # Try exact match on dNSHostName first
        if ($Script:ComputerHostnameCache.ContainsKey($hostname)) {
            return @{ ObjectIdentifier = $Script:ComputerHostnameCache[$hostname]; ObjectType = 'Computer' }
        }

        # Try short hostname (before first dot)
        $shortHost = ($hostname -split '\.')[0].ToLower()
        if ($Script:ComputerHostnameCache.ContainsKey($shortHost)) {
            return @{ ObjectIdentifier = $Script:ComputerHostnameCache[$shortHost]; ObjectType = 'Computer' }
        }
    }

    return $null
}


<#
.SYNOPSIS
    Builds a cache mapping certificate template CN names to their OID identifiers.
.DESCRIPTION
    BloodHound CE identifies certificate templates by their msPKI-Cert-Template-OID,
    while Enterprise CAs store published templates as CN names. This cache enables
    the CN-to-OID lookup needed for the EnabledCertTemplates relationship.
#>
function Build-TemplateCNToOIDCache {
    param([hashtable]$ConnectionParams = @{})

    $Script:TemplateCNToOID = @{}
    $configNC = $Script:LDAPContext.ConfigurationNamingContext

    if (-not $configNC) {
        Write-Log "[Build-TemplateCNToOIDCache] No Configuration NC available" -Level Debug
        return
    }

    $searchBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

    try {
        $templates = Invoke-LDAPSearch -Filter "(objectClass=pKICertificateTemplate)" -SearchBase $searchBase -Properties cn,'msPKI-Cert-Template-OID' -Raw

        foreach ($t in @($templates)) {
            $cn = $null
            $oid = $null

            if ($t.cn) { $cn = if ($t.cn -is [array]) { $t.cn[0] } else { $t.cn } }
            if ($t.'msPKI-Cert-Template-OID') {
                $oid = if ($t.'msPKI-Cert-Template-OID' -is [array]) { $t.'msPKI-Cert-Template-OID'[0] } else { $t.'msPKI-Cert-Template-OID' }
            }

            if ($cn -and $oid) {
                # Raw byte arrays need string conversion
                if ($oid -is [byte[]]) {
                    $oid = [System.Text.Encoding]::UTF8.GetString($oid)
                }
                if ($cn -is [byte[]]) {
                    $cn = [System.Text.Encoding]::UTF8.GetString($cn)
                }
                $Script:TemplateCNToOID[$cn] = $oid
            }
        }
    }
    catch {
        Write-Log "[Build-TemplateCNToOIDCache] Error building cache: $_" -Level Debug
    }

    Write-Log "[Build-TemplateCNToOIDCache] Cached $($Script:TemplateCNToOID.Count) template CN-to-OID mappings"
}


<#
.SYNOPSIS
    Writes BloodHound-compatible JSON file.
#>
function Write-BHJsonFile {
    param(
        [array]$Data,
        [string]$Type,
        [string]$FilePath,
        [switch]$PrettyPrint
    )

    # Calculate meta.methods bitmask per entity type (SharpHound v6 collection method flags)
    $methodsBitmask = switch ($Type) {
        'users'            { 1 -bor 64 -bor 512 -bor 1024 }  # Group + ACL + ObjectProps + SPNTargets
        'groups'           { 1 -bor 64 -bor 512 }             # Group + ACL + ObjectProps
        'computers'        { 1 -bor 64 -bor 512 }             # Group + ACL + ObjectProps
        'domains'          { 32 -bor 64 -bor 128 -bor 512 }   # Trusts + ACL + Container + ObjectProps
        'ous'              { 64 -bor 128 }                     # ACL + Container
        'containers'       { 128 }                             # Container
        'gpos'             { 64 -bor 128 }                     # ACL + Container
        'certtemplates'    { 64 -bor 262144 }                  # ACL + CertServices
        'enterprisecas'    { 64 -bor 262144 }                  # ACL + CertServices
        'rootcas'          { 64 -bor 262144 }                  # ACL + CertServices
        'aiacas'           { 64 -bor 262144 }                  # ACL + CertServices
        'ntauthstores'     { 64 -bor 262144 }                  # ACL + CertServices
        'issuancepolicies' { 64 -bor 262144 }                  # ACL + CertServices
        default            { 0 }
    }

    $jsonObject = @{
        data = $Data
        meta = @{
            type    = $Type
            count   = @($Data).Count
            version = $Script:JsonVersion
            methods = $methodsBitmask
        }
    }

    # Use central Export-adPEASFile helper for consistent file handling
    # Default: compact JSON (smaller files, BH CE compatible); PrettyPrint is opt-in
    if ($PrettyPrint) {
        $exportResult = Export-adPEASFile -Path $FilePath -Content $jsonObject -Type Json -JsonDepth 20 -Force
    } else {
        $exportResult = Export-adPEASFile -Path $FilePath -Content $jsonObject -Type Json -JsonDepth 20 -Force -Compress
    }

    if (-not $exportResult.Success) {
        Write-Error "[Export-BloodHoundJson] Failed to export: $($exportResult.Message)"
    }
}


<#
.SYNOPSIS
    Converts Windows FILETIME to Unix timestamp.
#>
function ConvertTo-UnixTimestamp {
    param($FileTime)

    if ($null -eq $FileTime -or $FileTime -eq 0 -or $FileTime -eq 9223372036854775807) {
        return -1
    }

    try {
        # Handle DateTime objects directly
        if ($FileTime -is [DateTime]) {
            return [int64]($FileTime.ToUniversalTime() - [DateTime]::UnixEpoch).TotalSeconds
        }
        # Handle LDAP Generalized Time strings ("20220412123456.0Z")
        if ($FileTime -is [string] -and $FileTime.Length -ge 14) {
            $dt = [DateTime]::ParseExact($FileTime.Substring(0, 14), 'yyyyMMddHHmmss', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal)
            return [int64]($dt.ToUniversalTime() - [DateTime]::UnixEpoch).TotalSeconds
        }
        # Handle Windows FILETIME (int64)
        $date = [DateTime]::FromFileTimeUtc($FileTime)
        return [int64]($date - [DateTime]::UnixEpoch).TotalSeconds
    }
    catch {
        Write-Log "[ConvertTo-UnixTimestamp] Failed to convert FileTime: $_" -Level Debug
        return -1
    }
}


<#
.SYNOPSIS
    Gets the BloodHound object type string from an AD object.
#>
function Get-BHObjectType {
    param($ObjectClass)

    if ($ObjectClass -is [array]) {
        $ObjectClass = $ObjectClass[-1]  # Last element is most specific
    }

    switch -Regex ($ObjectClass) {
        'user'                  { return 'User' }
        'computer'              { return 'Computer' }
        'group'                 { return 'Group' }
        'organizationalUnit'    { return 'OU' }
        'container'             { return 'Container' }
        'groupPolicyContainer'  { return 'GPO' }
        'domain'                { return 'Domain' }
        'trustedDomain'         { return 'Domain' }
        default                 { return 'Base' }
    }
}


<#
.SYNOPSIS
    Converts ACEs to BloodHound format with full DCOnly edge support.
.DESCRIPTION
    Parses nTSecurityDescriptor and extracts all BloodHound-compatible edges:
    - Owns (Owner has implicit GenericAll)
    - GenericAll, GenericWrite, WriteDacl, WriteOwner
    - DCSync rights (GetChanges, GetChangesAll, GetChangesInFilteredSet)
    - ForceChangePassword, AddMember, AddSelf
    - WriteSPN (servicePrincipalName write)
    - AddKeyCredentialLink (msDS-KeyCredentialLink write)
    - AllowedToAct (msDS-AllowedToActOnBehalfOfOtherIdentity write)
    - ReadLAPSPassword (ms-Mcs-AdmPwd read)
    - ReadGMSAPassword (msDS-GroupMSAMembership read)
    - AllExtendedRights
    - WriteAccountRestrictions (userAccountControl write)
#>
function ConvertTo-BHAces {
    param(
        [string]$DistinguishedName,
        [string]$ObjectType = 'Base',
        [hashtable]$ConnectionParams = @{}
    )

    $bhAces = @()

    # Initialize BloodHound GUID mappings (only once per session)
    if (-not $Script:BHPropertyGUIDs) {
        # Well-known property GUIDs for WriteProperty edges
        $Script:BHPropertyGUIDs = @{
            # WriteSPN - servicePrincipalName
            'f3a64788-5306-11d1-a9c5-0000f80367c1' = 'WriteSPN'
            # AddKeyCredentialLink - msDS-KeyCredentialLink
            '5b47d60f-6090-40b2-9f37-2a4de88f3063' = 'AddKeyCredentialLink'
            # AllowedToAct - msDS-AllowedToActOnBehalfOfOtherIdentity
            '3f78c3e5-f79a-46bd-a0b8-9d18116ddc79' = 'AddAllowedToAct'
            # WriteAccountRestrictions - userAccountControl
            '4c164200-20c0-11d0-a768-00aa006e0529' = 'WriteAccountRestrictions'
            # Member (group membership)
            'bf9679c0-0de6-11d0-a285-00aa003049e2' = 'AddMember'
            # GPLink
            'f30e3bbe-9ff0-11d1-b603-0000f80367c1' = 'WriteGPLink'
            # ADCS: msPKI-Enrollment-Flag write
            'd15ef7d8-f226-46db-ae79-b34e560bd12c' = 'WritePKIEnrollmentFlag'
            # ADCS: msPKI-Certificate-Name-Flag write
            'ea1dddc4-60ff-416e-8cc0-17cee534bce7' = 'WritePKINameFlag'
        }

        # Extended rights GUIDs
        $Script:BHExtendedRightGUIDs = @{
            # DCSync rights
            '1131f6aa-9c07-11d1-f79f-00c04fc2dcd2' = 'GetChanges'
            '1131f6ad-9c07-11d1-f79f-00c04fc2dcd2' = 'GetChangesAll'
            '89e95b76-444d-4c62-991a-0facbeda640c' = 'GetChangesInFilteredSet'
            # User password reset
            '00299570-246d-11d0-a768-00aa006e0529' = 'ForceChangePassword'
            # LAPS password read
            'e362ed86-b728-0842-b27d-2dea7a9df218' = 'ReadLAPSPassword'
            # All extended rights
            '00000000-0000-0000-0000-000000000000' = 'AllExtendedRights'
            # ADCS: Certificate-Enrollment
            '0e10c968-78fb-11d2-90d4-00c04f79dc55' = 'Enroll'
            # ADCS: Certificate-AutoEnrollment
            'a05b8cc2-17bc-4802-a710-e7c15ab866a2' = 'AutoEnroll'
            # ADCS: ManageCA (CA admin right)
            'ee138f32-c3ec-11d1-bbc5-0080c76670c0' = 'ManageCA'
            # ADCS: ManageCertificates (CA officer right)
            '98291c0c-7fd7-11d2-9917-00c04fc2d4cf' = 'ManageCertificates'
        }

        # GMSA password read - special handling via GenericAll on msDS-GroupManagedServiceAccount
        $Script:BHGMSAReadGUID = '5b47d60f-6090-40b2-9f37-2a4de88f3063'
    }

    try {
        # Get the object with nTSecurityDescriptor and GMSA membership attribute
        # IMPORTANT: Use -Raw to get nTSecurityDescriptor as byte[] instead of converted ACL
        # Escape DN for LDAP filter to prevent injection (RFC 4515)
        $escapedDN = Escape-LDAPFilterDN -DistinguishedName $DistinguishedName
        $adObject = @(Get-DomainObject -LDAPFilter "(distinguishedName=$escapedDN)" -Properties nTSecurityDescriptor,objectClass,'msDS-GroupMSAMembership' -Raw @ConnectionParams)[0]

        if (-not $adObject -or -not $adObject.nTSecurityDescriptor) {
            return $bhAces
        }

        # ===== GMSA PASSWORD READ EDGE =====
        # msDS-GroupMSAMembership contains a security descriptor that defines who can read the password
        if ($adObject.'msDS-GroupMSAMembership') {
            try {
                $gmsaSD = New-Object System.DirectoryServices.ActiveDirectorySecurity
                $gmsaSD.SetSecurityDescriptorBinaryForm($adObject.'msDS-GroupMSAMembership')
                $gmsaDACL = $gmsaSD.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier])

                foreach ($gmsaAce in $gmsaDACL) {
                    if ($gmsaAce.AccessControlType -eq 'Allow') {
                        $gmsaTrusteeSID = $gmsaAce.IdentityReference.Value

                        # Skip system principals
                        if ($gmsaTrusteeSID -notin @('S-1-5-18', 'S-1-3-0', 'S-1-5-10')) {
                            $bhAces += @{
                                PrincipalSID  = $gmsaTrusteeSID
                                PrincipalType = Get-BHPrincipalType -SID $gmsaTrusteeSID
                                RightName     = 'ReadGMSAPassword'
                                IsInherited   = $false
                            }
                        }
                    }
                }
            }
            catch {
                Write-Log "[ConvertTo-BHAces] Error parsing GMSA membership for $DistinguishedName : $_"
            }
        }

        # Parse security descriptor
        $RawSD = New-Object System.DirectoryServices.ActiveDirectorySecurity
        $RawSD.SetSecurityDescriptorBinaryForm($adObject.nTSecurityDescriptor)

        # ===== OWNS EDGE =====
        # Owner has implicit GenericAll equivalent
        $ownerSID = $RawSD.GetOwner([System.Security.Principal.SecurityIdentifier]).Value

        # Skip only non-actionable system owners
        # Domain Admins/Enterprise Admins ownership IS valuable for attack path analysis
        $skipOwners = @(
            'S-1-5-18',          # SYSTEM (not user-controllable)
            'S-1-3-0',           # Creator Owner (placeholder)
            'S-1-5-10'           # Self (placeholder)
        )

        if ($ownerSID -and $ownerSID -notin $skipOwners) {
            $bhAces += @{
                PrincipalSID  = $ownerSID
                PrincipalType = Get-BHPrincipalType -SID $ownerSID
                RightName     = 'Owns'
                IsInherited   = $false
            }
        }

        # ===== DACL EDGES =====
        $DACL = $RawSD.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier])

        foreach ($ace in $DACL) {
            # Only process Allow ACEs
            if ($ace.AccessControlType -ne 'Allow') { continue }

            $trusteeSID = $ace.IdentityReference.Value

            # Filter principals that create noise without attack value
            $skipPrincipals = @(
                'S-1-3-0',       # Creator Owner (placeholder, not actionable)
                'S-1-5-10',      # Self (placeholder, not actionable)
                'S-1-5-18'       # SYSTEM (not user-controllable, no attack path)
            )
            if ($trusteeSID -in $skipPrincipals) { continue }

            $principalType = Get-BHPrincipalType -SID $trusteeSID
            $adRights = $ace.ActiveDirectoryRights
            $objectTypeGuid = if ($ace.ObjectType -and $ace.ObjectType -ne [System.Guid]::Empty) {
                $ace.ObjectType.ToString().ToLower()
            } else { $null }

            $isInherited = $ace.IsInherited

            # ----- GenericAll -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::GenericAll) -eq [System.DirectoryServices.ActiveDirectoryRights]::GenericAll) {
                $bhAces += @{
                    PrincipalSID  = $trusteeSID
                    PrincipalType = $principalType
                    RightName     = 'GenericAll'
                    IsInherited   = $isInherited
                }
                continue  # GenericAll encompasses everything, skip other checks
            }

            # ----- GenericWrite -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::GenericWrite) -eq [System.DirectoryServices.ActiveDirectoryRights]::GenericWrite) {
                $bhAces += @{
                    PrincipalSID  = $trusteeSID
                    PrincipalType = $principalType
                    RightName     = 'GenericWrite'
                    IsInherited   = $isInherited
                }
            }

            # ----- WriteDacl -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl) -eq [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl) {
                $bhAces += @{
                    PrincipalSID  = $trusteeSID
                    PrincipalType = $principalType
                    RightName     = 'WriteDacl'
                    IsInherited   = $isInherited
                }
            }

            # ----- WriteOwner -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner) -eq [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner) {
                $bhAces += @{
                    PrincipalSID  = $trusteeSID
                    PrincipalType = $principalType
                    RightName     = 'WriteOwner'
                    IsInherited   = $isInherited
                }
            }

            # ----- WriteProperty (property-specific edges) -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty) -eq [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty) {
                if ($objectTypeGuid) {
                    # Check for known property GUIDs
                    if ($Script:BHPropertyGUIDs.ContainsKey($objectTypeGuid)) {
                        $rightName = $Script:BHPropertyGUIDs[$objectTypeGuid]
                        $bhAces += @{
                            PrincipalSID  = $trusteeSID
                            PrincipalType = $principalType
                            RightName     = $rightName
                            IsInherited   = $isInherited
                        }
                    }
                }
                else {
                    # WriteProperty with no ObjectType = write all properties
                    # This is similar to GenericWrite for attack purposes
                    # Add specific edges based on object type
                    if ($ObjectType -eq 'User') {
                        $bhAces += @{ PrincipalSID = $trusteeSID; PrincipalType = $principalType; RightName = 'WriteSPN'; IsInherited = $isInherited }
                        $bhAces += @{ PrincipalSID = $trusteeSID; PrincipalType = $principalType; RightName = 'AddKeyCredentialLink'; IsInherited = $isInherited }
                    }
                    elseif ($ObjectType -eq 'Computer') {
                        $bhAces += @{ PrincipalSID = $trusteeSID; PrincipalType = $principalType; RightName = 'AddAllowedToAct'; IsInherited = $isInherited }
                        $bhAces += @{ PrincipalSID = $trusteeSID; PrincipalType = $principalType; RightName = 'AddKeyCredentialLink'; IsInherited = $isInherited }
                    }
                    elseif ($ObjectType -eq 'Group') {
                        $bhAces += @{ PrincipalSID = $trusteeSID; PrincipalType = $principalType; RightName = 'AddMember'; IsInherited = $isInherited }
                    }
                }
            }

            # ----- Self (AddSelf for groups) -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::Self) -eq [System.DirectoryServices.ActiveDirectoryRights]::Self) {
                if ($ObjectType -eq 'Group') {
                    $bhAces += @{
                        PrincipalSID  = $trusteeSID
                        PrincipalType = $principalType
                        RightName     = 'AddSelf'
                        IsInherited   = $isInherited
                    }
                }
            }

            # ----- ExtendedRight -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight) -eq [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight) {
                if ($objectTypeGuid) {
                    # Check for known extended rights
                    if ($Script:BHExtendedRightGUIDs.ContainsKey($objectTypeGuid)) {
                        $rightName = $Script:BHExtendedRightGUIDs[$objectTypeGuid]
                        $bhAces += @{
                            PrincipalSID  = $trusteeSID
                            PrincipalType = $principalType
                            RightName     = $rightName
                            IsInherited   = $isInherited
                        }
                    }
                }
                else {
                    # ExtendedRight with no ObjectType = AllExtendedRights
                    $bhAces += @{
                        PrincipalSID  = $trusteeSID
                        PrincipalType = $principalType
                        RightName     = 'AllExtendedRights'
                        IsInherited   = $isInherited
                    }
                }
            }

            # ----- ReadProperty for LAPS -----
            if (($adRights -band [System.DirectoryServices.ActiveDirectoryRights]::ReadProperty) -eq [System.DirectoryServices.ActiveDirectoryRights]::ReadProperty) {
                if ($objectTypeGuid -eq 'e362ed86-b728-0842-b27d-2dea7a9df218') {
                    $bhAces += @{
                        PrincipalSID  = $trusteeSID
                        PrincipalType = $principalType
                        RightName     = 'ReadLAPSPassword'
                        IsInherited   = $isInherited
                    }
                }
            }
        }
    }
    catch {
        Write-Log "[ConvertTo-BHAces] Error processing ACLs for $DistinguishedName : $_"
    }

    # Remove duplicates
    $uniqueAces = @()
    $seen = @{}
    foreach ($ace in $bhAces) {
        $key = "$($ace.PrincipalSID)|$($ace.RightName)"
        if (-not $seen.ContainsKey($key)) {
            $seen[$key] = $true
            $uniqueAces += $ace
        }
    }

    return $uniqueAces
}


<#
.SYNOPSIS
    Determines the BloodHound principal type from a SID.
#>
function Get-BHPrincipalType {
    param([string]$SID)

    if (-not $SID) { return 'Base' }

    # Well-known group SIDs
    if ($SID -match '^S-1-5-32-') { return 'Group' }  # Builtin groups

    # Domain SID patterns
    if ($SID -match '-5\d{2}$') {
        # RIDs 500-599 are typically users/computers
        $rid = [int]($SID -split '-')[-1]
        if ($rid -eq 500 -or $rid -eq 501 -or $rid -eq 502) {
            return 'User'  # Administrator, Guest, krbtgt
        }
        elseif ($rid -ge 512 -and $rid -le 527) {
            return 'Group'  # Domain groups (DA, DU, DC, etc.)
        }
    }

    # Computer accounts end with $ in name, but we check RID pattern
    # RID >= 1000 and ends with even number often computer, odd often user
    # This is a heuristic - not 100% accurate without LDAP lookup
    if ($SID -match '-\d{4,}$') {
        $rid = [int]($SID -split '-')[-1]
        if ($rid -ge 1000) {
            # Could be user, computer, or group - default to Base
            return 'Base'
        }
    }

    return 'Base'
}


<#
.SYNOPSIS
    Collects domain information in BloodHound format.
#>
function Collect-BHDomain {
    param(
        [string]$DomainDN,
        [string]$DomainSID,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    # Escape DN for LDAP filter to prevent injection (RFC 4515)
    $escapedDomainDN = Escape-LDAPFilterDN -DistinguishedName $DomainDN
    $domainObj = @(Get-DomainObject -LDAPFilter "(distinguishedName=$escapedDomainDN)" @connectionParams)[0]

    if (-not $domainObj) { return @() }

    $domainName = $Script:LDAPContext.Domain.ToUpper()

    # Get functional level
    # Note: Windows Server 2019 does not have its own functional level (uses 2016 level = 7)
    $functionalLevel = switch ($domainObj.'msDS-Behavior-Version') {
        0       { '2000' }
        1       { '2003 Interim' }
        2       { '2003' }
        3       { '2008' }
        4       { '2008 R2' }
        5       { '2012' }
        6       { '2012 R2' }
        7       { '2016' }
        10      { '2025' }
        default { 'Unknown' }
    }

    # Query NetBIOS name from Partitions container
    $netbiosName = ""
    $configNC = $Script:LDAPContext.ConfigurationNamingContext
    if ($configNC) {
        try {
            $partitionsBase = "CN=Partitions,$configNC"
            $crossRef = @(Invoke-LDAPSearch -Filter "(&(objectClass=crossRef)(nCName=$DomainDN))" -SearchBase $partitionsBase -Properties nETBIOSName -Scope OneLevel @connectionParams)[0]
            if ($crossRef -and $crossRef.nETBIOSName) { $netbiosName = $crossRef.nETBIOSName }
        } catch { Write-Log "[Collect-BHDomain] NetBIOS name lookup failed: $_" -Level Debug }
    }

    # Get trusts
    $trusts = @()
    $trustObjects = Get-DomainObject -LDAPFilter "(objectClass=trustedDomain)" @connectionParams

    foreach ($trust in $trustObjects) {
        # trustDirection, trustType and trustAttributes are pre-decoded by Invoke-LDAPSearch
        # Reverse-map strings back to integers for BloodHound CE JSON format
        $trustDirInt = switch ($trust.trustDirection) {
            'Disabled'      { 0 }
            'Inbound'       { 1 }
            'Outbound'      { 2 }
            'Bidirectional' { 3 }
            default         { 0 }
        }

        $trustTypeInt = switch ($trust.trustType) {
            'Windows NT (Downlevel)'      { 1 }
            'Active Directory (Uplevel)'  { 2 }
            'MIT Kerberos Realm'          { 3 }
            'DCE'                         { 4 }
            default                       { 2 }
        }

        # trustAttributes is a string array of flag names
        $attrFlags = @($trust.trustAttributes)

        $trusts += @{
            TargetDomainSid     = if ($trust.securityIdentifier) { Convert-SidToString -SidInput $trust.securityIdentifier } else { "" }
            TargetDomainName    = if ($trust.name) { $trust.name.ToUpper() } else { "" }
            IsTransitive        = ($attrFlags -notcontains 'NON_TRANSITIVE')
            TrustDirection      = $trustDirInt
            TrustType           = $trustTypeInt
            SidFilteringEnabled = ($attrFlags -contains 'QUARANTINED_DOMAIN')
        }
    }

    # Get child objects from pre-built DN identity cache (O(1) lookup)
    $childObjects = @()
    if ($Script:ParentDNToChildren -and $Script:ParentDNToChildren.ContainsKey($DomainDN)) {
        $childObjects = @($Script:ParentDNToChildren[$DomainDN])
    }

    # Get GPO links
    $gpoLinks = @()
    if ($domainObj.gPLink) {
        $gpLinkString = $domainObj.gPLink
        $linkMatches = [regex]::Matches($gpLinkString, '\[LDAP://([^\]]+);(\d)\]')
        foreach ($match in $linkMatches) {
            $gpoDN = $match.Groups[1].Value
            $enforced = $match.Groups[2].Value -eq '2'

            # Get GPO GUID
            if ($gpoDN -match '\{([A-Fa-f0-9-]+)\}') {
                $gpoGuid = $Matches[1].ToUpper()
                $gpoLinks += @{
                    GUID       = $gpoGuid
                    IsEnforced = $enforced
                }
            }
        }
    }

    return @{
        ObjectIdentifier     = $DomainSID
        ForestRootIdentifier = $DomainSID
        Properties           = @{
            name                                    = $domainName
            domain                                  = $domainName
            domainsid                               = $DomainSID
            distinguishedname                       = $DomainDN
            description                             = if ($domainObj.description) { $domainObj.description } else { $null }
            functionallevel                         = $functionalLevel
            highvalue                               = $true
            whencreated                             = ConvertTo-UnixTimestamp $domainObj.whenCreated
            objectguid                              = ConvertTo-BHGuid -Value $domainObj.objectGUID
            isaclprotected                          = $false
            doesanyacegrantownerrights              = $false
            doesanyinheritedacegrantownerrights     = $false
            collected                               = $true
            netbios                                 = $netbiosName
            dsheuristics                            = if ($domainObj.dSHeuristics) { $domainObj.dSHeuristics } else { $null }
            expirepasswordsonsmartcardonlyaccounts  = if ($domainObj.'msDS-ExpirePasswordsOnSmartCardOnlyAccounts') { [bool]$domainObj.'msDS-ExpirePasswordsOnSmartCardOnlyAccounts' } else { $false }
            machineaccountquota                     = Get-SafeInt -Value $domainObj.'ms-DS-MachineAccountQuota' -Default 10
            lockoutthreshold                        = Get-SafeInt -Value $domainObj.lockoutThreshold -Default 0
            minpwdlength                            = Get-SafeInt -Value $domainObj.minPwdLength -Default 0
            pwdhistorylength                        = Get-SafeInt -Value $domainObj.pwdHistoryLength -Default 0
            pwdproperties                           = Get-SafeInt -Value $domainObj.pwdProperties -Default 0
            lockoutduration                         = Convert-ADIntervalToString -Value $domainObj.lockoutDuration
            lockoutobservationwindow                = if ($domainObj.lockOutObservationWindow) { [Int64]$domainObj.lockOutObservationWindow } else { 0 }
            maxpwdage                               = Convert-ADIntervalToString -Value $domainObj.maxPwdAge
            minpwdage                               = Convert-ADIntervalToString -Value $domainObj.minPwdAge
        }
        Trusts           = $trusts
        ChildObjects     = $childObjects
        Links            = $gpoLinks
        Aces             = @(ConvertTo-BHAces -DistinguishedName $DomainDN -ObjectType 'Domain' @connectionParams)
        IsDeleted        = $false
    }
}


<#
.SYNOPSIS
    Collects user objects in BloodHound format.
#>
function Collect-BHUsers {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $users = Get-DomainUser @connectionParams

    $bhUsers = @()

    foreach ($user in $users) {
        $sid = $null
        if ($user.objectSid) {
            $sid = Convert-SidToString -SidInput $user.objectSid
            if (-not $sid) {
                Write-Log "[Collect-BHUsers] Failed to parse SID for $($user.sAMAccountName)"
                continue
            }
        }
        else {
            continue
        }

        $uac = Get-SafeInt -Value $user.userAccountControl -Default 0

        # Parse SPNs
        $spns = @()
        if ($user.servicePrincipalName) {
            if ($user.servicePrincipalName -is [array]) {
                $spns = $user.servicePrincipalName
            }
            else {
                $spns = @($user.servicePrincipalName)
            }
        }

        # Parse SID history
        $sidHistory = @()
        if ($user.sIDHistory) {
            $historyItems = if ($user.sIDHistory -is [array]) { $user.sIDHistory } else { @($user.sIDHistory) }
            foreach ($histSid in $historyItems) {
                $convertedSid = Convert-SidToString -SidInput $histSid
                if ($convertedSid) {
                    $sidHistory += $convertedSid
                }
            }
        }
        # HasSIDHistory is a TypedPrincipal array (BH CE expects []ein.TypedPrincipal, not bool)
        $sidHistoryTyped = @($sidHistory | ForEach-Object { @{ ObjectIdentifier = $_; ObjectType = 'User' } })

        # Parse allowed to delegate (resolve SPNs to computer SIDs)
        $allowedToDelegate = @()
        if ($user.'msDS-AllowedToDelegateTo') {
            $delegateTargets = $user.'msDS-AllowedToDelegateTo'
            if ($delegateTargets -isnot [array]) { $delegateTargets = @($delegateTargets) }
            foreach ($target in $delegateTargets) {
                $resolved = Resolve-SPNToTarget -SPN $target
                if ($resolved) {
                    $allowedToDelegate += $resolved
                } else {
                    $allowedToDelegate += @{ ObjectIdentifier = $target; ObjectType = 'Computer' }
                }
            }
        }

        # Parse SPNTargets (resolve user SPNs to target computers)
        $spnTargets = @()
        foreach ($spn in $spns) {
            $resolved = Resolve-SPNToTarget -SPN $spn
            if ($resolved) {
                $port = 0
                if ($spn -match ':(\d+)') { $port = [int]$Matches[1] }
                $spnTargets += @{
                    ObjectIdentifier = $resolved.ObjectIdentifier
                    ObjectType       = $resolved.ObjectType
                    Port             = $port
                }
            }
        }

        # Get primary group SID
        $primaryGroupRid = Get-SafeInt -Value $user.primaryGroupID -Default 513
        $primaryGroupSID = "$DomainSID-$primaryGroupRid"

        $bhUser = @{
            ObjectIdentifier   = $sid
            Properties         = @{
                name                    = "$($user.sAMAccountName)@$domainName"
                domain                  = $domainName
                domainsid               = $DomainSID
                distinguishedname       = $user.distinguishedName
                highvalue               = $false
                samaccountname          = $user.sAMAccountName
                description             = if ($user.description) { $user.description } else { $null }
                whencreated             = ConvertTo-UnixTimestamp $user.whenCreated
                sensitive               = ($uac -band 0x100000) -ne 0  # NOT_DELEGATED
                dontreqpreauth          = ($uac -band 0x400000) -ne 0  # DONT_REQ_PREAUTH
                passwordnotreqd         = ($uac -band 0x20) -ne 0     # PASSWD_NOTREQD
                unconstraineddelegation = ($uac -band 0x80000) -ne 0  # TRUSTED_FOR_DELEGATION
                pwdneverexpires         = ($uac -band 0x10000) -ne 0  # DONT_EXPIRE_PASSWORD
                enabled                 = ($uac -band 0x2) -eq 0      # ACCOUNTDISABLE
                trustedtoauth           = ($uac -band 0x1000000) -ne 0 # TRUSTED_TO_AUTH_FOR_DELEGATION
                lastlogon               = ConvertTo-UnixTimestamp $user.lastLogon
                lastlogontimestamp      = ConvertTo-UnixTimestamp $user.lastLogonTimestamp
                pwdlastset              = ConvertTo-UnixTimestamp $user.pwdLastSet
                serviceprincipalnames   = $spns
                hasspn                  = @($spns).Count -gt 0
                displayname             = $user.displayName
                email                   = $user.mail
                title                   = $user.title
                homedirectory           = $user.homeDirectory
                userpassword            = $null
                unixpassword            = $null
                unicodepassword         = $null
                sfupassword             = $null
                logonscript                         = $user.scriptPath
                admincount                          = (Get-SafeInt -Value $user.adminCount) -gt 0
                sidhistory                          = $sidHistory
                objectguid                          = ConvertTo-BHGuid -Value $user.objectGUID
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                encryptedtextpwdallowed             = ($uac -band 0x80) -ne 0
                logonscriptenabled                  = ($uac -band 0x1) -ne 0
                usedeskeyonly                       = ($uac -band 0x200000) -ne 0
                profilepath                         = if ($user.profilePath) { $user.profilePath } else { $null }
                supportedencryptiontypes            = $null
            }
            PrimaryGroupSID    = $primaryGroupSID
            AllowedToDelegate  = $allowedToDelegate
            HasSIDHistory           = $sidHistoryTyped
            SPNTargets         = $spnTargets
            Aces               = @()
            IsDeleted          = $false
        }

        # Collect ACLs if requested
        if ($CollectACLs) {
            $bhUser.Aces = @(ConvertTo-BHAces -DistinguishedName $user.distinguishedName -ObjectType 'User' @connectionParams)
        }

        $bhUsers += $bhUser
    }

    return $bhUsers
}


<#
.SYNOPSIS
    Collects group objects in BloodHound format.
#>
function Collect-BHGroups {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $groups = Get-DomainGroup @connectionParams

    $bhGroups = @()

    foreach ($group in $groups) {
        $sid = $null
        if ($group.objectSid) {
            $sid = Convert-SidToString -SidInput $group.objectSid
            if (-not $sid) {
                Write-Log "[Collect-BHGroups] Failed to parse SID for $($group.sAMAccountName)"
                continue
            }
        }
        else {
            continue
        }

        # High-value groups
        $highValueRids = @('-512', '-519', '-518', '-516', '-498', '-500')
        $highValue = $false
        foreach ($rid in $highValueRids) {
            if ($sid.EndsWith($rid)) {
                $highValue = $true
                break
            }
        }

        # Parse members using DN identity cache (O(1) per member)
        $members = @()
        if ($group.member) {
            $memberDNs = if ($group.member -is [array]) { $group.member } else { @($group.member) }

            foreach ($memberDN in $memberDNs) {
                if ($Script:DNToIdentityCache -and $Script:DNToIdentityCache.ContainsKey($memberDN)) {
                    $members += $Script:DNToIdentityCache[$memberDN]
                } else {
                    # Fallback for cache misses (cross-domain members, deleted objects)
                    $escapedMemberDN = Escape-LDAPFilterDN -DistinguishedName $memberDN
                    $memberObj = @(Get-DomainObject -LDAPFilter "(distinguishedName=$escapedMemberDN)" -Properties objectSid,objectClass @connectionParams)[0]

                    if ($memberObj -and $memberObj.objectSid) {
                        $memberSID = Convert-SidToString -SidInput $memberObj.objectSid
                        if ($memberSID) {
                            $members += @{
                                ObjectIdentifier = $memberSID
                                ObjectType       = Get-BHObjectType -ObjectClass $memberObj.objectClass
                            }
                        }
                    }
                }
            }
        }

        $bhGroup = @{
            ObjectIdentifier = $sid
            Properties       = @{
                name              = "$($group.sAMAccountName)@$domainName"
                domain            = $domainName
                domainsid         = $DomainSID
                distinguishedname = $group.distinguishedName
                highvalue         = $highValue
                samaccountname    = $group.sAMAccountName
                description       = if ($group.description) { $group.description } else { $null }
                whencreated                         = ConvertTo-UnixTimestamp $group.whenCreated
                admincount                          = (Get-SafeInt -Value $group.adminCount) -gt 0
                objectguid                          = ConvertTo-BHGuid -Value $group.objectGUID
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
            }
            Members          = $members
            Aces             = @()
            IsDeleted        = $false
        }

        # Collect ACLs if requested
        if ($CollectACLs) {
            $bhGroup.Aces = @(ConvertTo-BHAces -DistinguishedName $group.distinguishedName -ObjectType 'Group' @connectionParams)
        }

        $bhGroups += $bhGroup
    }

    return $bhGroups
}


<#
.SYNOPSIS
    Collects computer objects in BloodHound format.
#>
function Collect-BHComputers {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()

    $computers = Get-DomainComputer @connectionParams

    $bhComputers = @()

    foreach ($computer in $computers) {
        $sid = $null
        if ($computer.objectSid) {
            $sid = Convert-SidToString -SidInput $computer.objectSid
            if (-not $sid) {
                Write-Log "[Collect-BHComputers] Failed to parse SID for $($computer.name)"
                continue
            }
        }
        else {
            continue
        }

        $uac = Get-SafeInt -Value $computer.userAccountControl -Default 0
        $isDC = ($uac -band 0x2000) -ne 0  # SERVER_TRUST_ACCOUNT

        # Get primary group SID
        $primaryGroupRid = Get-SafeInt -Value $computer.primaryGroupID -Default 515
        $primaryGroupSID = "$DomainSID-$primaryGroupRid"

        # Parse allowed to delegate (resolve SPNs to computer SIDs)
        $allowedToDelegate = @()
        if ($computer.'msDS-AllowedToDelegateTo') {
            $delegateTargets = $computer.'msDS-AllowedToDelegateTo'
            if ($delegateTargets -isnot [array]) { $delegateTargets = @($delegateTargets) }
            foreach ($target in $delegateTargets) {
                $resolved = Resolve-SPNToTarget -SPN $target
                if ($resolved) {
                    $allowedToDelegate += $resolved
                } else {
                    $allowedToDelegate += @{ ObjectIdentifier = $target; ObjectType = 'Computer' }
                }
            }
        }

        # Parse allowed to act (RBCD)
        $allowedToAct = @()
        if ($computer.'msDS-AllowedToActOnBehalfOfOtherIdentity') {
            try {
                $sd = New-Object System.DirectoryServices.ActiveDirectorySecurity
                $sd.SetSecurityDescriptorBinaryForm($computer.'msDS-AllowedToActOnBehalfOfOtherIdentity')
                foreach ($ace in $sd.Access) {
                    # Get SID - IdentityReference may be SecurityIdentifier or NTAccount
                    $sidValue = $null
                    $identRef = $ace.IdentityReference
                    if ($identRef -is [System.Security.Principal.SecurityIdentifier]) {
                        $sidValue = $identRef.Value
                    } else {
                        # NTAccount - use ConvertTo-SID for cross-domain support
                        $sidValue = ConvertTo-SID -Identity $identRef.Value
                    }
                    if ($sidValue) {
                        $allowedToAct += @{
                            ObjectIdentifier = $sidValue
                            ObjectType       = 'Unknown'
                        }
                    }
                }
            }
            catch {
                Write-Log "[Collect-BHComputers] Error parsing RBCD for $($computer.name): $_" -Level Debug
            }
        }

        # SID History
        $sidHistory = @()
        if ($computer.sIDHistory) {
            $historyItems = if ($computer.sIDHistory -is [array]) { $computer.sIDHistory } else { @($computer.sIDHistory) }
            foreach ($histSid in $historyItems) {
                $convertedSid = Convert-SidToString -SidInput $histSid
                if ($convertedSid) {
                    $sidHistory += $convertedSid
                }
            }
        }
        # HasSIDHistory is a TypedPrincipal array (BH CE expects []ein.TypedPrincipal, not bool)
        $sidHistoryTyped = @($sidHistory | ForEach-Object { @{ ObjectIdentifier = $_; ObjectType = 'Computer' } })

        $bhComputer = @{
            ObjectIdentifier    = $sid
            Properties          = @{
                name                    = "$($computer.dNSHostName)".ToUpper()
                domain                  = $domainName
                domainsid               = $DomainSID
                distinguishedname       = $computer.distinguishedName
                highvalue               = $isDC
                samaccountname          = $computer.sAMAccountName
                description             = if ($computer.description) { $computer.description } else { $null }
                whencreated             = ConvertTo-UnixTimestamp $computer.whenCreated
                operatingsystem         = $computer.operatingSystem
                enabled                 = ($uac -band 0x2) -eq 0
                unconstraineddelegation = ($uac -band 0x80000) -ne 0
                trustedtoauth           = ($uac -band 0x1000000) -ne 0
                lastlogon               = ConvertTo-UnixTimestamp $computer.lastLogon
                lastlogontimestamp      = ConvertTo-UnixTimestamp $computer.lastLogonTimestamp
                pwdlastset              = ConvertTo-UnixTimestamp $computer.pwdLastSet
                serviceprincipalnames   = @(
                    if ($computer.servicePrincipalName -and $computer.servicePrincipalName -isnot [hashtable]) {
                        $computer.servicePrincipalName
                    }
                )
                haslaps                             = ($null -ne $computer.'ms-Mcs-AdmPwdExpirationTime') -or ($null -ne $computer.'msLAPS-PasswordExpirationTime')
                sidhistory                          = $sidHistory
                isdc                               = $isDC
                objectguid                          = ConvertTo-BHGuid -Value $computer.objectGUID
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                encryptedtextpwdallowed             = ($uac -band 0x80) -ne 0
                logonscriptenabled                  = ($uac -band 0x1) -ne 0
                email                               = if ($computer.mail) { $computer.mail } else { $null }
                usedeskeyonly                       = ($uac -band 0x200000) -ne 0
                supportedencryptiontypes            = $null
            }
            PrimaryGroupSID     = $primaryGroupSID
            AllowedToDelegate   = $allowedToDelegate
            AllowedToAct        = $allowedToAct
            HasSIDHistory           = $sidHistoryTyped
            # Phase 1: No session/local group collection
            Sessions            = @{
                Collected     = $false
                FailureReason = "Not collected in Phase 1 (LDAP-only)"
                Results       = @()
            }
            PrivilegedSessions  = @{
                Collected     = $false
                FailureReason = "Not collected in Phase 1 (LDAP-only)"
                Results       = @()
            }
            RegistrySessions    = @{
                Collected     = $false
                FailureReason = "Not collected in Phase 1 (LDAP-only)"
                Results       = @()
            }
            # SharpHound v2.12.0: LocalAdmins/RemoteDesktopUsers/DcomUsers/PSRemoteUsers replaced by:
            LocalGroups         = @()
            UserRights          = @()
            DumpSMSAPassword    = @()
            DCRegistryData          = $null
            IsWebClientRunning      = $null
            NTLMRegistryData        = $null
            NtlmSessions            = $null
            SmbInfo                 = $null
            Aces                    = @()
            IsDeleted               = $false
        }

        # Collect ACLs if requested
        if ($CollectACLs) {
            $bhComputer.Aces = @(ConvertTo-BHAces -DistinguishedName $computer.distinguishedName -ObjectType 'Computer' @connectionParams)
        }

        $bhComputers += $bhComputer
    }

    return $bhComputers
}


<#
.SYNOPSIS
    Collects OU objects in BloodHound format.
#>
function Collect-BHOUs {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $domainDN = $Script:LDAPContext.DomainDN

    $ous = Get-DomainObject -LDAPFilter "(objectClass=organizationalUnit)" @connectionParams

    $bhOUs = @()

    foreach ($ou in $ous) {
        $ouGuid = ConvertTo-BHGuid -Value $ou.objectGuid

        # Get child objects from pre-built DN identity cache (O(1) lookup)
        $childObjects = @()
        $ouDN = $ou.distinguishedName
        # Null-guard the cache (as Collect-BHDomain does): degrade to no children rather than crash
        # if the cache was never built.
        if ($Script:ParentDNToChildren -and $Script:ParentDNToChildren.ContainsKey($ouDN)) {
            $childObjects = @($Script:ParentDNToChildren[$ouDN])
        }

        # GPO links
        $gpoLinks = @()
        if ($ou.gPLink) {
            $gpLinkString = $ou.gPLink
            $linkMatches = [regex]::Matches($gpLinkString, '\[LDAP://([^\]]+);(\d)\]')
            foreach ($match in $linkMatches) {
                $gpoDN = $match.Groups[1].Value
                $enforced = $match.Groups[2].Value -eq '2'

                if ($gpoDN -match '\{([A-Fa-f0-9-]+)\}') {
                    $gpoGuid = $Matches[1].ToUpper()
                    $gpoLinks += @{
                        GUID       = $gpoGuid
                        IsEnforced = $enforced
                    }
                }
            }
        }

        $bhOU = @{
            ObjectIdentifier   = $ouGuid
            Properties         = @{
                name                                = "$($ou.name)@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $ou.distinguishedName
                highvalue                           = $false
                description                         = if ($ou.description) { $ou.description } else { $null }
                whencreated                         = ConvertTo-UnixTimestamp $ou.whenCreated
                blocksinheritance                   = ((Get-SafeInt -Value $ou.gPOptions) -band 1) -ne 0
                objectguid                          = $ouGuid
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
            }
            ChildObjects       = $childObjects
            Links              = $gpoLinks
            GPOChanges         = @{
                LocalAdmins        = @()
                RemoteDesktopUsers = @()
                DcomUsers          = @()
                PSRemoteUsers      = @()
                AffectedComputers  = @()
            }
            Aces               = @()
            IsDeleted          = $false
        }

        # Collect ACLs if requested
        if ($CollectACLs) {
            $bhOU.Aces = @(ConvertTo-BHAces -DistinguishedName $ou.distinguishedName -ObjectType 'OU' @connectionParams)
        }

        $bhOUs += $bhOU
    }

    return $bhOUs
}


<#
.SYNOPSIS
    Collects container objects in BloodHound format.
#>
function Collect-BHContainers {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()

    # Get standard containers
    $containers = Get-DomainObject -LDAPFilter "(&(objectClass=container)(!(objectClass=groupPolicyContainer)))" @connectionParams

    $bhContainers = @()

    foreach ($container in $containers) {
        $containerGuid = ConvertTo-BHGuid -Value $container.objectGuid
        $containerDN = $container.distinguishedName

        # Get child objects from pre-built DN identity cache (O(1) lookup)
        $childObjects = @()
        # Null-guard the cache (as Collect-BHDomain does): degrade to no children rather than crash.
        if ($Script:ParentDNToChildren -and $Script:ParentDNToChildren.ContainsKey($containerDN)) {
            $childObjects = @($Script:ParentDNToChildren[$containerDN])
        }

        $bhContainer = @{
            ObjectIdentifier = $containerGuid
            Properties       = @{
                name                                = "$($container.name)@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $containerDN
                highvalue                           = $false
                objectguid                          = $containerGuid
                description                         = if ($container.description) { $container.description } else { $null }
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                whencreated                         = ConvertTo-UnixTimestamp $container.whenCreated
            }
            ChildObjects     = $childObjects
            Aces             = @()
            IsDeleted        = $false
        }

        if ($CollectACLs) {
            $bhContainer.Aces = @(ConvertTo-BHAces -DistinguishedName $containerDN -ObjectType 'Container' @connectionParams)
        }

        $bhContainers += $bhContainer
    }

    return $bhContainers
}


<#
.SYNOPSIS
    Collects GPO objects in BloodHound format.
#>
function Collect-BHGPOs {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()

    $gpos = Get-DomainGPO @connectionParams

    $bhGPOs = @()

    foreach ($gpo in $gpos) {
        # GPO GUID from name attribute (CN={GUID})
        $gpoGuid = ""
        if ($gpo.name -match '\{([A-Fa-f0-9-]+)\}') {
            $gpoGuid = $Matches[1].ToUpper()
        }
        else {
            continue
        }

        $bhGPO = @{
            ObjectIdentifier = $gpoGuid
            Properties       = @{
                name                                = "$($gpo.displayName)@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $gpo.distinguishedName
                highvalue                           = $false
                description                         = if ($gpo.description) { $gpo.description } else { $null }
                whencreated                         = ConvertTo-UnixTimestamp $gpo.whenCreated
                gpcpath                             = $gpo.gPCFileSysPath
                objectguid                          = $gpoGuid
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                gpostatus                           = "0"
            }
            Aces             = @()
            IsDeleted        = $false
        }

        # Collect ACLs if requested
        if ($CollectACLs) {
            $bhGPO.Aces = @(ConvertTo-BHAces -DistinguishedName $gpo.distinguishedName -ObjectType 'GPO' @connectionParams)
        }

        $bhGPOs += $bhGPO
    }

    return $bhGPOs
}


<#
.SYNOPSIS
    Collects certificate template objects in BloodHound format.
.DESCRIPTION
    Queries pKICertificateTemplate objects from the Configuration partition and converts
    them to BloodHound CE v6 format. Uses Invoke-LDAPSearch -Raw for raw integer flags
    rather than Get-CertificateTemplate (which converts flags to human-readable strings).
#>
function Collect-BHCertTemplates {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $configNC = $Script:LDAPContext.ConfigurationNamingContext

    if (-not $configNC) {
        Write-Log "[Collect-BHCertTemplates] No Configuration NC available"
        return @()
    }

    $searchBase = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

    $templateProps = @(
        'cn', 'distinguishedName', 'objectGUID', 'displayName', 'whenCreated',
        'msPKI-Cert-Template-OID',
        'pKIExpirationPeriod', 'pKIOverlapPeriod',
        'msPKI-Template-Schema-Version',
        'msPKI-Enrollment-Flag', 'msPKI-Certificate-Name-Flag',
        'pKIExtendedKeyUsage', 'msPKI-Certificate-Application-Policy',
        'msPKI-RA-Signature', 'msPKI-RA-Application-Policies', 'msPKI-RA-Policies',
        'nTSecurityDescriptor'
    )

    $templates = Invoke-LDAPSearch -Filter "(objectClass=pKICertificateTemplate)" -SearchBase $searchBase -Properties $templateProps -Raw

    $bhTemplates = @()

    # OIDs that enable authentication
    $authOIDs = @('1.3.6.1.5.5.7.3.2', '1.3.6.1.4.1.311.20.2.2', '1.3.6.1.5.2.3.4', '2.5.29.37.0')

    foreach ($template in @($templates)) {
        # Extract CN (may be byte[] from -Raw)
        $cn = $template.cn
        if ($cn -is [byte[]]) { $cn = [System.Text.Encoding]::UTF8.GetString($cn) }
        if ($cn -is [array]) { $cn = $cn[0] }

        # ObjectIdentifier = OID (NOT objectGuid)
        $oid = $template.'msPKI-Cert-Template-OID'
        if ($oid -is [byte[]]) { $oid = [System.Text.Encoding]::UTF8.GetString($oid) }
        if ($oid -is [array]) { $oid = $oid[0] }
        if (-not $oid) { continue }

        $dn = $template.distinguishedName
        if ($dn -is [byte[]]) { $dn = [System.Text.Encoding]::UTF8.GetString($dn) }
        if ($dn -is [array]) { $dn = $dn[0] }

        # Parse integer flags
        $enrollmentFlag = Get-SafeInt -Value $template.'msPKI-Enrollment-Flag'
        $certNameFlag = Get-SafeInt -Value $template.'msPKI-Certificate-Name-Flag'
        $schemaVersion = Get-SafeInt -Value $template.'msPKI-Template-Schema-Version'
        $raSignature = Get-SafeInt -Value $template.'msPKI-RA-Signature'

        # Parse displayName
        $templateDisplayName = $template.displayName
        if ($templateDisplayName -is [byte[]]) { $templateDisplayName = [System.Text.Encoding]::UTF8.GetString($templateDisplayName) }
        if ($templateDisplayName -is [array]) { $templateDisplayName = $templateDisplayName[0] }

        # Parse whenCreated (raw Generalized Time string in -Raw mode)
        $rawWhenCreated = $template.whenCreated
        if ($rawWhenCreated -is [byte[]]) { $rawWhenCreated = [System.Text.Encoding]::ASCII.GetString($rawWhenCreated) }
        if ($rawWhenCreated -is [array]) { $rawWhenCreated = $rawWhenCreated[0] }
        $templateWhenCreated = ConvertTo-UnixTimestamp $rawWhenCreated

        # Parse objectGUID
        $templateGuid = ""
        if ($template.objectGUID) {
            $rawGuid = $template.objectGUID
            if ($rawGuid -is [array] -and $rawGuid.Count -gt 0) { $rawGuid = $rawGuid[0] }
            $templateGuid = ConvertTo-BHGuid -Value $rawGuid
        }

        # Parse EKU arrays
        $ekus = @()
        if ($template.pKIExtendedKeyUsage) {
            $rawEkus = if ($template.pKIExtendedKeyUsage -is [array]) { $template.pKIExtendedKeyUsage } else { @($template.pKIExtendedKeyUsage) }
            foreach ($eku in $rawEkus) {
                if ($eku -is [byte[]]) { $eku = [System.Text.Encoding]::UTF8.GetString($eku) }
                if ($eku) { $ekus += $eku }
            }
        }

        $certAppPolicy = @()
        if ($template.'msPKI-Certificate-Application-Policy') {
            $rawCap = if ($template.'msPKI-Certificate-Application-Policy' -is [array]) { $template.'msPKI-Certificate-Application-Policy' } else { @($template.'msPKI-Certificate-Application-Policy') }
            foreach ($cap in $rawCap) {
                if ($cap -is [byte[]]) { $cap = [System.Text.Encoding]::UTF8.GetString($cap) }
                if ($cap) { $certAppPolicy += $cap }
            }
        }

        $appPolicies = @()
        if ($template.'msPKI-RA-Application-Policies') {
            $rawAp = if ($template.'msPKI-RA-Application-Policies' -is [array]) { $template.'msPKI-RA-Application-Policies' } else { @($template.'msPKI-RA-Application-Policies') }
            foreach ($ap in $rawAp) {
                if ($ap -is [byte[]]) { $ap = [System.Text.Encoding]::UTF8.GetString($ap) }
                if ($ap) { $appPolicies += $ap }
            }
        }

        $issuancePolicies = @()
        if ($template.'msPKI-RA-Policies') {
            $rawIp = if ($template.'msPKI-RA-Policies' -is [array]) { $template.'msPKI-RA-Policies' } else { @($template.'msPKI-RA-Policies') }
            foreach ($ip in $rawIp) {
                if ($ip -is [byte[]]) { $ip = [System.Text.Encoding]::UTF8.GetString($ip) }
                if ($ip) { $issuancePolicies += $ip }
            }
        }

        # Effective EKUs = union of pKIExtendedKeyUsage + msPKI-Certificate-Application-Policy
        $effectiveEkus = @($ekus) + @($certAppPolicy) | Where-Object { $_ } | Select-Object -Unique

        # Authentication enabled: true if any auth OID present, or if no EKUs defined (any purpose)
        $authEnabled = (@($effectiveEkus).Count -eq 0) -or ($effectiveEkus | Where-Object { $_ -in $authOIDs })
        $authEnabled = [bool]$authEnabled

        # Validity/renewal periods from raw byte arrays
        $validityPeriod = "P0D"
        $renewalPeriod = "P0D"
        if ($template.pKIExpirationPeriod -is [byte[]]) {
            $validityPeriod = ConvertTo-ISODuration -PeriodBytes $template.pKIExpirationPeriod
        }
        if ($template.pKIOverlapPeriod -is [byte[]]) {
            $renewalPeriod = ConvertTo-ISODuration -PeriodBytes $template.pKIOverlapPeriod
        }

        $bhTemplate = @{
            ObjectIdentifier = $oid
            Properties       = @{
                name                                = "$cn@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $dn
                highvalue                           = $false
                validityperiod                      = $validityPeriod
                renewalperiod                       = $renewalPeriod
                schemaversion                       = $schemaVersion
                enrollmentflag                      = Convert-EnrollFlagToString -Value $enrollmentFlag
                certificatenameflag                 = Convert-CertNameFlagToString -Value $certNameFlag
                oid                                 = $oid
                requiresmanagerapproval             = ($enrollmentFlag -band 0x2) -ne 0
                enrolleesuppliessubject             = ($certNameFlag -band 0x1) -ne 0
                subjectaltrequireupn                = ($certNameFlag -band 0x2000000) -ne 0
                subjectaltrequiredns                = ($certNameFlag -band 0x8000000) -ne 0
                subjectaltrequiredomaindns          = ($certNameFlag -band 0x400000) -ne 0
                subjectaltrequireemail              = ($certNameFlag -band 0x4000000) -ne 0
                subjectaltrequirespn                = ($certNameFlag -band 0x800) -ne 0
                nosecurityextension                 = ($enrollmentFlag -band 0x80000) -ne 0
                ekus                                = $ekus
                certificateapplicationpolicy        = $certAppPolicy
                authorizedsignatures                = $raSignature
                applicationpolicies                 = $appPolicies
                issuancepolicies                    = $issuancePolicies
                effectiveekus                       = @($effectiveEkus)
                authenticationenabled               = $authEnabled
                objectguid                          = $templateGuid
                displayname                         = if ($templateDisplayName) { $templateDisplayName } else { $null }
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                schannelauthenticationenabled       = $false
                subjectrequireemail                 = ($certNameFlag -band 0x20000000) -ne 0
                whencreated                         = $templateWhenCreated
                certificatepolicy                   = @()
            }
            ContainedBy      = Get-BHContainedByConfig -DistinguishedName $dn
            Aces             = @()
            IsDeleted        = $false
        }

        if ($CollectACLs -and $dn) {
            $bhTemplate.Aces = @(ConvertTo-BHAces -DistinguishedName $dn -ObjectType 'CertTemplate' @connectionParams)
        }

        $bhTemplates += $bhTemplate
    }

    return $bhTemplates
}


<#
.SYNOPSIS
    Collects Enterprise CA objects in BloodHound format.
.DESCRIPTION
    Reuses Get-CertificateAuthority (Core) to query pKIEnrollmentService objects,
    then transforms them to BloodHound CE v6 format with EnabledCertTemplates and
    HostingComputer relationships.
#>
function Collect-BHEnterpriseCAs {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()

    $cas = Get-CertificateAuthority @connectionParams

    $bhCAs = @()

    foreach ($ca in @($cas)) {
        # Skip error markers
        if ($ca._QueryError) { continue }
        if (-not $ca.Name) { continue }

        $caGuid = ""
        if ($ca.ObjectGUID) {
            $caGuid = $ca.ObjectGUID.ToString().ToUpper()
        } else {
            continue
        }

        # Parse CA certificate
        $certProps = @{ Thumbprint = ""; Name = ""; HasBasicConstraints = $false; PathLength = 0 }
        if ($ca.CACertificate) {
            $certBytes = if ($ca.CACertificate -is [array] -and $ca.CACertificate[0] -is [byte]) {
                [byte[]]$ca.CACertificate
            } elseif ($ca.CACertificate -is [array]) {
                $ca.CACertificate[0]
            } else {
                $ca.CACertificate
            }
            if ($certBytes -is [byte[]]) {
                $certProps = Get-CertificateProperties -CertificateBytes $certBytes
            }
        }

        # Build certchain (all cert thumbprints)
        $certChain = @()
        if ($certProps.Thumbprint) { $certChain += $certProps.Thumbprint }

        # Resolve EnabledCertTemplates: template CN -> OID
        $enabledTemplates = @()
        foreach ($templateCN in @($ca.CertificateTemplates)) {
            if ($Script:TemplateCNToOID -and $Script:TemplateCNToOID.ContainsKey($templateCN)) {
                $enabledTemplates += @{
                    ObjectIdentifier = $Script:TemplateCNToOID[$templateCN]
                    ObjectType       = 'CertTemplate'
                }
            }
        }

        # Resolve HostingComputer: dNSHostName -> computer SID
        $hostingSID = ""
        if ($ca.DNSHostName -and $Script:ComputerHostnameCache) {
            $hostKey = $ca.DNSHostName.ToLower()
            if ($Script:ComputerHostnameCache.ContainsKey($hostKey)) {
                $hostingSID = $Script:ComputerHostnameCache[$hostKey]
            }
        }

        $bhCA = @{
            ObjectIdentifier     = $caGuid
            Properties           = @{
                name                                = "$($ca.Name)@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $ca.DistinguishedName
                highvalue                           = $false
                dnshostname                         = $ca.DNSHostName
                basicconstraintpathlength           = $certProps.PathLength
                hasbasicconstraints                 = $certProps.HasBasicConstraints
                certchain                           = $certChain
                certname                            = $certProps.Name
                certthumbprint                      = $certProps.Thumbprint
                flags                               = Convert-CAFlagToString -Value $(if ($ca.Flags) { [int]$ca.Flags } else { 0 })
                caname                              = $ca.Name
                objectguid                          = ConvertTo-BHGuid -Value $ca.ObjectGUID
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                unresolvedpublishedtemplates        = @()
                whencreated                         = ConvertTo-UnixTimestamp $ca.Created
            }
            # CARegistryData must be top-level (not inside Properties) - nested dicts inside
            # Properties cause Neo4j Map{} errors when BH CE writes them as node properties.
            CARegistryData          = $null
            HttpEnrollmentEndpoints = @()
            EnabledCertTemplates    = $enabledTemplates
            HostingComputer         = $hostingSID
            ContainedBy             = Get-BHContainedByConfig -DistinguishedName $ca.DistinguishedName
            Aces                    = @()
            IsDeleted               = $false
            IsACLProtected          = $false
        }

        if ($CollectACLs -and $ca.DistinguishedName) {
            $bhCA.Aces = @(ConvertTo-BHAces -DistinguishedName $ca.DistinguishedName -ObjectType 'EnterpriseCA' @connectionParams)
        }

        $bhCAs += $bhCA
    }

    return $bhCAs
}


<#
.SYNOPSIS
    Collects Root CA objects in BloodHound format.
.DESCRIPTION
    Queries certificationAuthority objects from the Certification Authorities container
    in the Configuration partition. These are the trusted root CAs for the forest.
#>
function Collect-BHRootCAs {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $configNC = $Script:LDAPContext.ConfigurationNamingContext

    if (-not $configNC) {
        Write-Log "[Collect-BHRootCAs] No Configuration NC available"
        return @()
    }

    $searchBase = "CN=Certification Authorities,CN=Public Key Services,CN=Services,$configNC"

    $rootCAs = Invoke-LDAPSearch -Filter "(objectClass=certificationAuthority)" -SearchBase $searchBase -Properties cn,distinguishedName,objectGUID,cACertificate,whenCreated -Raw -Scope OneLevel

    $bhRootCAs = @()

    foreach ($rootCA in @($rootCAs)) {
        $cn = $rootCA.cn
        if ($cn -is [byte[]]) { $cn = [System.Text.Encoding]::UTF8.GetString($cn) }
        if ($cn -is [array]) { $cn = $cn[0] }

        $dn = $rootCA.distinguishedName
        if ($dn -is [byte[]]) { $dn = [System.Text.Encoding]::UTF8.GetString($dn) }
        if ($dn -is [array]) { $dn = $dn[0] }

        $guid = ""
        if ($rootCA.objectGUID) {
            if ($rootCA.objectGUID -is [byte[]]) {
                $guid = ([Guid]$rootCA.objectGUID).ToString().ToUpper()
            } else {
                $guid = $rootCA.objectGUID.ToString().ToUpper()
            }
        }
        if (-not $guid) { continue }

        # Parse whenCreated
        $rawWhenCreated = $rootCA.whenCreated
        if ($rawWhenCreated -is [byte[]]) { $rawWhenCreated = [System.Text.Encoding]::ASCII.GetString($rawWhenCreated) }
        if ($rawWhenCreated -is [array]) { $rawWhenCreated = $rawWhenCreated[0] }
        $rootCAWhenCreated = ConvertTo-UnixTimestamp $rawWhenCreated

        # Parse certificate
        $certProps = @{ Thumbprint = ""; Name = ""; HasBasicConstraints = $false; PathLength = 0 }
        if ($rootCA.cACertificate) {
            $certBytes = $rootCA.cACertificate
            if ($certBytes -is [array] -and $certBytes[0] -isnot [byte]) { $certBytes = $certBytes[0] }
            if ($certBytes -is [byte[]]) {
                $certProps = Get-CertificateProperties -CertificateBytes $certBytes
            }
        }

        $bhRootCA = @{
            ObjectIdentifier = $guid
            Properties       = @{
                name                                = "$cn@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $dn
                highvalue                           = $false
                certname                            = $certProps.Name
                certthumbprint                      = $certProps.Thumbprint
                hasbasicconstraints                 = $certProps.HasBasicConstraints
                basicconstraintpathlength           = $certProps.PathLength
                objectguid                          = $guid
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                certchain                           = @($certProps.Thumbprint | Where-Object { $_ })
                whencreated                         = $rootCAWhenCreated
            }
            DomainSID        = $DomainSID
            ContainedBy      = Get-BHContainedByConfig -DistinguishedName $dn
            Aces             = @()
            IsDeleted        = $false
        }

        if ($CollectACLs -and $dn) {
            $bhRootCA.Aces = @(ConvertTo-BHAces -DistinguishedName $dn -ObjectType 'RootCA' @connectionParams)
        }

        $bhRootCAs += $bhRootCA
    }

    return $bhRootCAs
}


<#
.SYNOPSIS
    Collects AIA CA objects in BloodHound format.
.DESCRIPTION
    Queries certificationAuthority objects from the AIA (Authority Information Access)
    container in the Configuration partition.
#>
function Collect-BHAIACAs {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $configNC = $Script:LDAPContext.ConfigurationNamingContext

    if (-not $configNC) {
        Write-Log "[Collect-BHAIACAs] No Configuration NC available"
        return @()
    }

    $searchBase = "CN=AIA,CN=Public Key Services,CN=Services,$configNC"

    $aiaCAs = Invoke-LDAPSearch -Filter "(objectClass=certificationAuthority)" -SearchBase $searchBase -Properties cn,distinguishedName,objectGUID,cACertificate,crossCertificatePair,whenCreated -Raw -Scope OneLevel

    $bhAIACAs = @()

    foreach ($aiaCA in @($aiaCAs)) {
        $cn = $aiaCA.cn
        if ($cn -is [byte[]]) { $cn = [System.Text.Encoding]::UTF8.GetString($cn) }
        if ($cn -is [array]) { $cn = $cn[0] }

        $dn = $aiaCA.distinguishedName
        if ($dn -is [byte[]]) { $dn = [System.Text.Encoding]::UTF8.GetString($dn) }
        if ($dn -is [array]) { $dn = $dn[0] }

        $guid = ""
        if ($aiaCA.objectGUID) {
            if ($aiaCA.objectGUID -is [byte[]]) {
                $guid = ([Guid]$aiaCA.objectGUID).ToString().ToUpper()
            } else {
                $guid = $aiaCA.objectGUID.ToString().ToUpper()
            }
        }
        if (-not $guid) { continue }

        # Parse whenCreated
        $rawWhenCreated = $aiaCA.whenCreated
        if ($rawWhenCreated -is [byte[]]) { $rawWhenCreated = [System.Text.Encoding]::ASCII.GetString($rawWhenCreated) }
        if ($rawWhenCreated -is [array]) { $rawWhenCreated = $rawWhenCreated[0] }
        $aiaCAWhenCreated = ConvertTo-UnixTimestamp $rawWhenCreated

        # Parse certificate
        $certProps = @{ Thumbprint = ""; Name = ""; HasBasicConstraints = $false; PathLength = 0 }
        if ($aiaCA.cACertificate) {
            $certBytes = $aiaCA.cACertificate
            if ($certBytes -is [array] -and $certBytes[0] -isnot [byte]) { $certBytes = $certBytes[0] }
            if ($certBytes -is [byte[]]) {
                $certProps = Get-CertificateProperties -CertificateBytes $certBytes
            }
        }

        # Check for CRL Distribution Points extension (hascrl)
        $hasCRL = $false
        if ($aiaCA.cACertificate) {
            try {
                $certBytesForCRL = $aiaCA.cACertificate
                if ($certBytesForCRL -is [array] -and $certBytesForCRL[0] -isnot [byte]) { $certBytesForCRL = $certBytesForCRL[0] }
                if ($certBytesForCRL -is [byte[]]) {
                    $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(,$certBytesForCRL)
                    foreach ($ext in $cert.Extensions) {
                        if ($ext.Oid.Value -eq '2.5.29.31') { $hasCRL = $true; break }
                    }
                }
            }
            catch { Write-Log "[Collect-BHAIACAs] CRL extension check failed for '$cn': $_" -Level Debug }
        }

        $bhAIACA = @{
            ObjectIdentifier = $guid
            Properties       = @{
                name                                = "$cn@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $dn
                highvalue                           = $false
                certname                            = $certProps.Name
                certthumbprint                      = $certProps.Thumbprint
                hascrl                              = $hasCRL
                crosscertificatepair                = @()
                objectguid                          = $guid
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                hasbasicconstraints                 = $certProps.HasBasicConstraints
                basicconstraintpathlength           = $certProps.PathLength
                hascrosscertificatepair             = $false
                certchain                           = @($certProps.Thumbprint | Where-Object { $_ })
                whencreated                         = $aiaCAWhenCreated
            }
            ContainedBy      = Get-BHContainedByConfig -DistinguishedName $dn
            Aces             = @()
            IsDeleted        = $false
        }

        if ($CollectACLs -and $dn) {
            $bhAIACA.Aces = @(ConvertTo-BHAces -DistinguishedName $dn -ObjectType 'AIACA' @connectionParams)
        }

        $bhAIACAs += $bhAIACA
    }

    return $bhAIACAs
}


<#
.SYNOPSIS
    Collects NTAuth Store objects in BloodHound format.
.DESCRIPTION
    Queries the NTAuthCertificates object from the Public Key Services container.
    The NTAuth store defines which CAs are trusted for smart card / certificate-based logon.
#>
function Collect-BHNTAuthStores {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $configNC = $Script:LDAPContext.ConfigurationNamingContext

    if (-not $configNC) {
        Write-Log "[Collect-BHNTAuthStores] No Configuration NC available"
        return @()
    }

    $searchBase = "CN=Public Key Services,CN=Services,$configNC"

    $ntAuth = Invoke-LDAPSearch -Filter "(cn=NTAuthCertificates)" -SearchBase $searchBase -Properties cn,distinguishedName,objectGUID,cACertificate,whenCreated -Raw -Scope OneLevel

    $bhNTAuthStores = @()

    foreach ($ntAuthObj in @($ntAuth)) {
        $cn = $ntAuthObj.cn
        if ($cn -is [byte[]]) { $cn = [System.Text.Encoding]::UTF8.GetString($cn) }
        if ($cn -is [array]) { $cn = $cn[0] }

        $dn = $ntAuthObj.distinguishedName
        if ($dn -is [byte[]]) { $dn = [System.Text.Encoding]::UTF8.GetString($dn) }
        if ($dn -is [array]) { $dn = $dn[0] }

        $guid = ""
        if ($ntAuthObj.objectGUID) {
            if ($ntAuthObj.objectGUID -is [byte[]]) {
                $guid = ([Guid]$ntAuthObj.objectGUID).ToString().ToUpper()
            } else {
                $guid = $ntAuthObj.objectGUID.ToString().ToUpper()
            }
        }
        if (-not $guid) { continue }

        # Parse whenCreated
        $rawWhenCreated = $ntAuthObj.whenCreated
        if ($rawWhenCreated -is [byte[]]) { $rawWhenCreated = [System.Text.Encoding]::ASCII.GetString($rawWhenCreated) }
        if ($rawWhenCreated -is [array]) { $rawWhenCreated = $rawWhenCreated[0] }
        $ntAuthWhenCreated = ConvertTo-UnixTimestamp $rawWhenCreated

        # Parse all certificates to extract thumbprints
        $certThumbprints = @()
        if ($ntAuthObj.cACertificate) {
            $rawCerts = $ntAuthObj.cACertificate
            # cACertificate may be multi-valued (array of byte arrays) or single byte array
            if ($rawCerts -is [byte[]]) {
                $props = Get-CertificateProperties -CertificateBytes $rawCerts
                if ($props.Thumbprint) { $certThumbprints += $props.Thumbprint }
            }
            elseif ($rawCerts -is [array]) {
                foreach ($certBytes in $rawCerts) {
                    if ($certBytes -is [byte[]]) {
                        $props = Get-CertificateProperties -CertificateBytes $certBytes
                        if ($props.Thumbprint) { $certThumbprints += $props.Thumbprint }
                    }
                }
            }
        }

        $bhNTAuthStore = @{
            ObjectIdentifier = $guid
            Properties       = @{
                name                                = "$cn@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $dn
                highvalue                           = $false
                certthumbprints                     = $certThumbprints
                objectguid                          = $guid
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                whencreated                         = $ntAuthWhenCreated
            }
            DomainSID        = $DomainSID
            ContainedBy      = Get-BHContainedByConfig -DistinguishedName $dn
            Aces             = @()
            IsDeleted        = $false
        }

        if ($CollectACLs -and $dn) {
            $bhNTAuthStore.Aces = @(ConvertTo-BHAces -DistinguishedName $dn -ObjectType 'NTAuthStore' @connectionParams)
        }

        $bhNTAuthStores += $bhNTAuthStore
    }

    return $bhNTAuthStores
}


<#
.SYNOPSIS
    Collects Issuance Policy objects in BloodHound format.
.DESCRIPTION
    Queries msPKI-Enterprise-Oid objects from the OID container in the Configuration
    partition. Issuance policies can be linked to groups via msDS-OIDToGroupLink,
    enabling certificate-based group membership attacks.
#>
function Collect-BHIssuancePolicies {
    param(
        [string]$DomainSID,
        [switch]$CollectACLs,
        [string]$Domain,
        [string]$Server,
        [System.Management.Automation.PSCredential]$Credential
    )

    $connectionParams = @{}
    if ($Domain) { $connectionParams['Domain'] = $Domain }
    if ($Server) { $connectionParams['Server'] = $Server }
    if ($Credential) { $connectionParams['Credential'] = $Credential }

    $domainName = $Script:LDAPContext.Domain.ToUpper()
    $configNC = $Script:LDAPContext.ConfigurationNamingContext

    if (-not $configNC) {
        Write-Log "[Collect-BHIssuancePolicies] No Configuration NC available"
        return @()
    }

    $searchBase = "CN=OID,CN=Public Key Services,CN=Services,$configNC"

    $oidObjects = Invoke-LDAPSearch -Filter "(objectClass=msPKI-Enterprise-Oid)" -SearchBase $searchBase -Properties cn,displayName,distinguishedName,objectGUID,'msPKI-Cert-Template-OID','msDS-OIDToGroupLink',whenCreated -Raw

    $bhPolicies = @()

    foreach ($oidObj in @($oidObjects)) {
        # Only include objects with an OID (issuance policies)
        $oid = $oidObj.'msPKI-Cert-Template-OID'
        if ($oid -is [byte[]]) { $oid = [System.Text.Encoding]::UTF8.GetString($oid) }
        if ($oid -is [array]) { $oid = $oid[0] }
        if (-not $oid) { continue }

        $cn = $oidObj.cn
        if ($cn -is [byte[]]) { $cn = [System.Text.Encoding]::UTF8.GetString($cn) }
        if ($cn -is [array]) { $cn = $cn[0] }

        $displayName = $oidObj.displayName
        if ($displayName -is [byte[]]) { $displayName = [System.Text.Encoding]::UTF8.GetString($displayName) }
        if ($displayName -is [array]) { $displayName = $displayName[0] }

        $dn = $oidObj.distinguishedName
        if ($dn -is [byte[]]) { $dn = [System.Text.Encoding]::UTF8.GetString($dn) }
        if ($dn -is [array]) { $dn = $dn[0] }

        $name = if ($displayName) { $displayName } else { $cn }

        # Parse objectGUID
        $policyGuid = ""
        if ($oidObj.objectGUID) {
            $rawGuid = $oidObj.objectGUID
            if ($rawGuid -is [array] -and $rawGuid.Count -gt 0) { $rawGuid = $rawGuid[0] }
            $policyGuid = ConvertTo-BHGuid -Value $rawGuid
        }

        # Parse whenCreated
        $rawWhenCreated = $oidObj.whenCreated
        if ($rawWhenCreated -is [byte[]]) { $rawWhenCreated = [System.Text.Encoding]::ASCII.GetString($rawWhenCreated) }
        if ($rawWhenCreated -is [array]) { $rawWhenCreated = $rawWhenCreated[0] }
        $policyWhenCreated = ConvertTo-UnixTimestamp $rawWhenCreated

        # Resolve GroupLink: msDS-OIDToGroupLink DN -> group SID
        $groupLink = @{ ObjectIdentifier = $null; ObjectType = 'Base' }
        if ($oidObj.'msDS-OIDToGroupLink') {
            $groupLinkDN = $oidObj.'msDS-OIDToGroupLink'
            if ($groupLinkDN -is [byte[]]) { $groupLinkDN = [System.Text.Encoding]::UTF8.GetString($groupLinkDN) }
            if ($groupLinkDN -is [array]) { $groupLinkDN = $groupLinkDN[0] }

            if ($groupLinkDN) {
                try {
                    $escapedDN = Escape-LDAPFilterDN -DistinguishedName $groupLinkDN
                    $groupObj = @(Get-DomainObject -LDAPFilter "(distinguishedName=$escapedDN)" -Properties objectSid @connectionParams)[0]
                    if ($groupObj -and $groupObj.objectSid) {
                        $resolvedSid = Convert-SidToString -SidInput $groupObj.objectSid
                        if ($resolvedSid) {
                            $groupLink = @{ ObjectIdentifier = $resolvedSid; ObjectType = 'Group' }
                        }
                    }
                }
                catch {
                    Write-Log "[Collect-BHIssuancePolicies] Error resolving GroupLink DN: $_" -Level Debug
                }
            }
        }

        $bhPolicy = @{
            ObjectIdentifier = $oid
            Properties       = @{
                name                                = "$name@$domainName"
                domain                              = $domainName
                domainsid                           = $DomainSID
                distinguishedname                   = $dn
                highvalue                           = $false
                certtemplateoid                     = $oid
                objectguid                          = $policyGuid
                displayname                         = if ($displayName) { $displayName } else { $null }
                isaclprotected                      = $false
                doesanyacegrantownerrights          = $false
                doesanyinheritedacegrantownerrights = $false
                whencreated                         = $policyWhenCreated
            }
            GroupLink        = $groupLink
            ContainedBy      = Get-BHContainedByConfig -DistinguishedName $dn
            Aces             = @()
            IsDeleted        = $false
        }

        if ($CollectACLs -and $dn) {
            $bhPolicy.Aces = @(ConvertTo-BHAces -DistinguishedName $dn -ObjectType 'IssuancePolicy' @connectionParams)
        }

        $bhPolicies += $bhPolicy
    }

    return $bhPolicies
}




# ==============================================
# MAIN LOGIC
# ==============================================

<#
.SYNOPSIS
    adPEAS v2 - Active Directory Privilege Escalation Awesome Scripts

.DESCRIPTION
    Security analysis tool for identifying vulnerabilities and misconfigurations in Active Directory environments.

.EXAMPLE
    # v2 Style: Two-step (explicit session management)
    Import-Module .\adPEAS.ps1
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Invoke-adPEAS

.EXAMPLE
    # v1 Style: One-step (direct execution with connection parameters)
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -UseWindowsAuth

.EXAMPLE
    # v1 Style: With credentials
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -Credential (Get-Credential)

.EXAMPLE
    # v1 Style: With username/password
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -Username "john.doe" -Password "P@ssw0rd!"

.EXAMPLE
    # Write output to file (with ANSI colors by default)
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -UseWindowsAuth -Outputfile .\adPEAS_out.txt

.EXAMPLE
    # Write output to file without colors (plain text)
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -UseWindowsAuth -Outputfile .\adPEAS_out.txt -NoColor

.EXAMPLE
    # Run specific Modules with existing session
    Import-Module .\adPEAS.ps1
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Invoke-adPEAS -Module Domain,Accounts,GPO

.EXAMPLE
    # OPSEC mode (stealth - no Kerberoast, ASREPRoast, BloodHound collection)
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -UseWindowsAuth -OPSEC

.NOTES
    Author: Alexander Sturz (@_61106960_)

.LINK
    https://github.com/61106960/adPEAS
#>

#Requires -Version 5.1

# ===== Script Variables =====
$Script:adPEASVersion = "2.4.1"

# Handle ScriptPath for different execution contexts:
# - Normal: $MyInvocation.MyCommand.Path is set
# - ScriptBlock::Create() (obfuscated/embedded): $MyInvocation.MyCommand.Path is $null
if ($MyInvocation.MyCommand.Path) {
    $Script:ScriptPath = Split-Path -Parent $MyInvocation.MyCommand.Path
} else {
    # Running via ScriptBlock (e.g., obfuscated version) - modules are already combined
    $Script:ScriptPath = $null
}

# Output Configuration
$Script:adPEAS_OutputColor = $true
$Script:adPEAS_Outputfile = $null
$Script:adPEAS_VerboseLogging = $false

# Activity Threshold Configuration
# Default: 90 days - accounts inactive longer are considered stale
# Can be overridden via Invoke-adPEAS -InactiveDays parameter
$Script:DefaultInactiveDays = 90

# License Configuration
# EmbeddedLicense is replaced at build time by Build-Release.ps1 (Base64-encoded JSON)
# RuntimeLicense is set by -License parameter at runtime
$Script:EmbeddedLicense = $null
$Script:RuntimeLicense = $null

# ===== Main Function =====
function Invoke-adPEAS {
<#
.SYNOPSIS
    Main execution function for adPEAS v2.

.DESCRIPTION
    This function wraps the entire adPEAS execution logic.
    Can be called with connection parameters or reuse an existing session.

    Connection Parameters (Optional - pass-through to Connect-adPEAS):
    - Domain, Server, UseLDAPS, TimeoutSeconds
    - Authentication: UseWindowsAuth, Credential, Username/Password, Certificate/CertificatePassword

    If connection parameters are provided, Invoke-adPEAS will establish a connection automatically.
    If no parameters are provided, it will reuse an existing session or show help.

    SESSION PERSISTENCE:
    The LDAP session is always kept alive after Invoke-adPEAS completes.
    This allows you to:
    - Check the session with Get-adPEASSession
    - Run additional Get-Domain* queries
    - Execute additional scans with Invoke-adPEAS
    Use Disconnect-adPEAS to explicitly close the session when done.

.PARAMETER Domain
    The Active Directory domain to analyze (optional).

.PARAMETER Server
    Specific Domain Controller (FQDN or IP) (optional).

.PARAMETER UseWindowsAuth
    Use Windows Authentication (current user context).

.PARAMETER Credential
    PSCredential object for authentication.

.PARAMETER Username
    Username for authentication (requires -Password).

.PARAMETER Password
    Password for authentication (requires -Username). Accepts String or SecureString.

.PARAMETER Certificate
    Path to PKCS#12 certificate file or Base64-encoded certificate for PKINIT authentication.

.PARAMETER CertificatePassword
    Password for certificate (requires -Certificate). Accepts String or SecureString.

.PARAMETER UseLDAPS
    Forces LDAPS (Port 636).

.PARAMETER Outputfile
    Path to output file (without extension). If set, adPEAS writes reports to this path.
    Generates up to 3 files depending on -Format:
      - .txt  (Text report, with -Format Text or All)
      - .html (Interactive HTML report, with -Format HTML or All)
      - .json (Machine-readable JSON export, with -Format JSON or All)
    By default, text output includes ANSI color codes (viewable with cat/Get-Content).
    Use -NoColor to write plain text without color codes.

.PARAMETER Module
    Array of Modules to execute. Available: Domain, Creds, Rights, Delegation, ADCS, Accounts, GPO, Computer, Application, BloodHound.
    Default: All Modules.

.PARAMETER OPSEC
    Skips OPSEC-critical and heavy-load checks (Kerberoast, ASREPRoast, BloodHound collection, PasswordInDescription, NonDefaultOwners, OutdatedComputers).
    These checks enumerate thousands of objects and generate significant LDAP traffic.

.PARAMETER NoColor
    Disables colored console output. Useful for logging or terminals that don't support ANSI colors.

.PARAMETER VerboseLogging
    Writes verbose log messages (Write-Log) to the output file AND enables -Verbose for console output.
    Requires -Outputfile to be specified for file logging.
    Useful for troubleshooting and detailed analysis.

.PARAMETER InactiveDays
    Threshold in days for account activity analysis. Accounts without login activity
    within this period are considered inactive/stale. Default: 90 days.
    This affects checks like Get-LAPSPermissions, Get-LAPSConfiguration, Get-InactiveAdminAccounts, etc.

.PARAMETER IncludePrivileged
    Include privileged accounts (Domain Admins, Enterprise Admins, etc.) in permission checks.
    By default, these expected privileged accounts are hidden from output.
    When enabled, privileged accounts are shown in yellow (Hint) instead of red (Finding).
    Affects: Get-DangerousACLs, Get-GPOPermissions, Get-AddComputerRights, Get-PrivilegedGroupMembers, Get-ADCSVulnerabilities.

.PARAMETER TimeoutSeconds
    Timeout in seconds for LDAP operations.
    Default: 30 seconds
    Valid range: 5-600 seconds. Increase for high-latency connections (SOCKS tunnels, VPN).
    Example: -TimeoutSeconds 120

.PARAMETER OutputAppend
    Appends findings to an existing report instead of overwriting it.
    Requires -Outputfile to be specified.
    When used with -Module, only the specified module's findings are replaced in the report.
    Previous findings from other modules are preserved using the JSON export file.
    Example: Run modules individually and build up a combined report:
      Invoke-adPEAS -Module Domain -Outputfile report -OutputAppend
      Invoke-adPEAS -Module Accounts -Outputfile report -OutputAppend

.EXAMPLE
    # v1 Style: Direct execution with connection parameters
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -UseWindowsAuth

.EXAMPLE
    # v1 Style: With credentials
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -Credential (Get-Credential)

.EXAMPLE
    # v1 Style: With username/password
    Import-Module .\adPEAS.ps1
    Invoke-adPEAS -Domain "contoso.com" -Username "john.doe" -Password "P@ssw0rd!"

.EXAMPLE
    # v2 Style: Establish session first, then run
    Import-Module .\adPEAS.ps1
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Invoke-adPEAS

.EXAMPLE
    # Write to file with existing session
    Invoke-adPEAS -Outputfile .\adPEAS_out.txt

.EXAMPLE
    # Run specific Modules only
    Invoke-adPEAS -Module Domain,Accounts,GPO

.EXAMPLE
    # OPSEC mode (stealth - no Kerberoast, ASREPRoast, BloodHound collection)
    Invoke-adPEAS -Domain "contoso.com" -UseWindowsAuth -OPSEC

.EXAMPLE
    # Incremental scan: Run modules separately and build up one combined report
    Connect-adPEAS -Domain "contoso.com" -UseWindowsAuth
    Invoke-adPEAS -Module Domain -Outputfile .\report -OutputAppend
    Invoke-adPEAS -Module Accounts -Outputfile .\report -OutputAppend
    Invoke-adPEAS -Module Rights -Outputfile .\report -OutputAppend
    # report.html now contains findings from all three modules
#>
    [CmdletBinding(DefaultParameterSetName='Default')]
    param(
        # ===== Connection Parameters (Optional - Pass-through to Connect-adPEAS) =====
        [Parameter(Mandatory=$false)]
        [string]$Domain,

        [Parameter(Mandatory=$false)]
        [string]$Server,

        [Parameter(Mandatory=$false)]
        [switch]$UseLDAPS,

        [Parameter(Mandatory=$false, ParameterSetName='WindowsAuth')]
        [switch]$UseWindowsAuth,

        [Parameter(Mandatory=$false, ParameterSetName='PSCredential')]
        [System.Management.Automation.PSCredential]$Credential,

        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        [string]$Username,

        [Parameter(Mandatory=$false, ParameterSetName='UsernamePassword')]
        $Password,  # Accepts SecureString or String

        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        [string]$Certificate,

        [Parameter(Mandatory=$false, ParameterSetName='Certificate')]
        $CertificatePassword = "",  # Accepts SecureString or String. Default: empty (for unprotected PFX)

        # ===== Execution Parameters =====
        [Parameter(Mandatory=$false)]
        [string]$Outputfile,

        [Parameter(Mandatory=$false)]
        [ValidateSet("Domain","Creds","Rights","Delegation","ADCS","Accounts","GPO","Computer","Application","Bloodhound")]
        [string[]]$Module,

        [Parameter(Mandatory=$false)]
        [switch]$OPSEC,

        [Parameter(Mandatory=$false)]
        [switch]$NoColor,

        [Parameter(Mandatory=$false)]
        [switch]$VerboseLogging,

        [Parameter(Mandatory=$false)]
        [ValidateRange(1, 3650)]
        [int]$InactiveDays = 90,

        [Parameter(Mandatory=$false)]
        [switch]$IncludePrivileged,

        [Parameter(Mandatory=$false)]
        [ValidateRange(5, 600)]
        [int]$TimeoutSeconds = 30,

        # ===== Output Format Parameters =====
        [Parameter(Mandatory=$false)]
        [ValidateSet('Text', 'HTML', 'JSON', 'All')]
        [string]$Format = 'All',

        # ===== Append Mode =====
        [Parameter(Mandatory=$false)]
        [switch]$OutputAppend,

        # ===== License Parameter =====
        [Parameter(Mandatory=$false)]
        [string]$License,

        # ===== Statistics Parameter =====
        [Parameter(Mandatory=$false)]
        [switch]$Statistics
    )

    # Reset script variables for each invocation
    # NOTE: $StartTime is intentionally local - it is only consumed within this invocation.
    # Making it $Script: would expose it to Clear-SessionState (called by Connect-adPEAS on
    # repeated invocations), which would null it before the duration calculation at the end.
    $StartTime = Get-Date
    $Script:adPEAS_OutputColor = -not $NoColor
    $Script:adPEAS_Outputfile = $null
    $Script:adPEAS_VerboseLogging = $VerboseLogging
    $Script:DefaultInactiveDays = $InactiveDays

    # Initialize LDAP Statistics tracking (null = disabled, zero overhead)
    if ($Statistics) {
        $Script:LDAPStatistics = @{
            TotalQueries        = 0
            TotalResults        = 0
            TotalEstimatedBytes = 0
            Modules             = [ordered]@{}
            _ModuleStartQueries = 0
            _ModuleStartResults = 0
            _ModuleStartBytes   = 0
            _CurrentModule      = $null
        }
    } else {
        $Script:LDAPStatistics = $null
    }

    # Auto-enable -Verbose when -VerboseLogging is used
    # Set local $VerbosePreference so it propagates to child function calls via scope chain
    if ($VerboseLogging) {
        $VerbosePreference = 'Continue'
    }

    # Validate -OutputAppend requires -Outputfile
    if ($OutputAppend -and -not $PSBoundParameters['Outputfile']) {
        Write-Warning "[adPEAS] -OutputAppend requires -Outputfile. Ignoring -OutputAppend."
        $OutputAppend = [switch]::new($false)
    }

    # Validate -OutputAppend requires a format that produces JSON (for findings merge)
    if ($OutputAppend -and $Format -notin @('All', 'JSON')) {
        Write-Warning "[adPEAS] -OutputAppend requires JSON findings cache. Use -Format All or -Format JSON. Ignoring -OutputAppend."
        $OutputAppend = [switch]::new($false)
    }

    # Initialize findings collection if HTML or JSON format requested
    if ($Format -in @('HTML', 'JSON', 'All')) {
        Initialize-FindingsCollection
        Write-Log "[adPEAS] Findings collection enabled (Format: $Format)"
    }

    # ===== Output File Configuration =====
    # Determine output file paths based on -Outputfile and -Format parameters
    $Script:HTMLOutputPath = $null
    $Script:JSONOutputPath = $null
    # Track IncludePrivileged mode for HTML report tooltip filtering
    $Script:IncludePrivilegedMode = $IncludePrivileged.IsPresent

    if ($PSBoundParameters['Outputfile']) {
        # Resolve to absolute path to ensure consistent file access throughout the script
        # This is critical because relative paths may fail when functions change working directory
        $resolvedOutputfile = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($Outputfile)

        # Strip any existing extension from the base path
        $basePath = $resolvedOutputfile
        if ([System.IO.Path]::HasExtension($resolvedOutputfile)) {
            $basePath = [System.IO.Path]::ChangeExtension($resolvedOutputfile, $null).TrimEnd('.')
        }

        # Create directory if it doesn't exist
        $OutputDir = Split-Path -Parent $basePath
        if ($OutputDir -and -not (Test-Path $OutputDir)) {
            try {
                New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
                Write-Warning "[adPEAS] Directory '$OutputDir' did not exist and was created"
            } catch {
                Write-Warning "[adPEAS] Could not create directory '$OutputDir': $_"
                return
            }
        }

        # Set output paths based on format
        if ($Format -in @('Text', 'All')) {
            $textPath = "$basePath.txt"
            try {
                if (-not $OutputAppend) {
                    # Normal mode: Create/truncate file to verify write access
                    [io.file]::OpenWrite($textPath).close()
                }
                # Append mode: File will be created or appended to by Write-adPEASOutput
                $Script:adPEAS_Outputfile = $textPath
            } catch {
                Write-Warning "[adPEAS] Unable to write text output to '$textPath', please check path and permissions!"
            }
        }

        if ($Format -in @('HTML', 'All')) {
            $Script:HTMLOutputPath = "$basePath.html"
        }

        # For HTML-only and JSON-only mode, don't write to text file
        if ($Format -in @('HTML', 'JSON')) {
            $Script:adPEAS_Outputfile = $null
        }
    }

    # Warn if VerboseLogging is enabled without text output (but still enable console verbose)
    if ($VerboseLogging -and -not $Script:adPEAS_Outputfile) {
        Write-Warning "[adPEAS] -VerboseLogging: File logging requires -Outputfile with Text format. Verbose messages will be shown in console only."
        # Keep VerboseLogging = $true so that $VerbosePreference stays 'Continue' for console output
        # File logging won't happen since $Script:adPEAS_Outputfile is $null
    }

# ===== Banner =====
Show-Logo -Version $Script:adPEASVersion

# ===== Main Logic =====
try {
    # ===== License Validation =====
    $_licJson = $null
    # Priority: runtime -License param > Connect-adPEAS stored license > embedded license
    if ($PSBoundParameters.ContainsKey('License') -and $License -and (Test-Path $License -ErrorAction SilentlyContinue)) {
        $_licJson = Get-Content $License -Raw -Encoding UTF8
    }
    elseif ($Script:RuntimeLicense) {
        $_licJson = $Script:RuntimeLicense
    }
    elseif ($Script:EmbeddedLicense) {
        $_licJson = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Script:EmbeddedLicense))
    }

    $_licResult = if ($_licJson) { Test-adPEASLicense -LicenseJson $_licJson } else { $null }

    if ($_licResult -and $_licResult.IsValid -and -not $_licResult.Expired) {
        $Script:adPEASDisclaimer = $_licResult.Message
        Show-Line $Script:adPEASDisclaimer -Class Note
    }
    else {
        # Default disclaimer (XOR obfuscated)
        $_lm="GCQlP2w+KTwjPjhsOy0/bCspIik+LTgpKGw5PyUiK2wtbDgjIyBsOCQtOGw+KT05JT4pP2wtbDotICUobC8jISEpPi8lLSBsICUvKSI/KWwqIz5sLyMiPzkgOCUiK2wjPmwhLSItKykobD8pPjolLylsOT8pYg==";$_lk=0x4C
        $Script:adPEASDisclaimer=(-join([Convert]::FromBase64String($_lm)|ForEach-Object{[char]($_-bxor$_lk)}))
        Show-Line $Script:adPEASDisclaimer -Class Finding
    }
    Write-Log "[adPEAS] Script started: $StartTime"
    Write-Log "[adPEAS] Version: $Script:adPEASVersion"

    if ($OPSEC) {
        Write-Log "[adPEAS] OPSEC mode enabled: No ASREPRoast/Kerberoast/BloodHound"
    }

    # ===== Connection Handling =====
    # Check if ANY connection/authentication parameters were provided
    $HasConnectionParams = $PSBoundParameters.ContainsKey('Domain') -or
                          $PSBoundParameters.ContainsKey('Server') -or
                          $PSBoundParameters.ContainsKey('UseWindowsAuth') -or
                          $PSBoundParameters.ContainsKey('Credential') -or
                          $PSBoundParameters.ContainsKey('Username') -or
                          $PSBoundParameters.ContainsKey('Password') -or
                          $PSBoundParameters.ContainsKey('Certificate') -or
                          $PSBoundParameters.ContainsKey('CertificatePassword') -or
                          $PSBoundParameters.ContainsKey('UseLDAPS')

    # Check for active LdapConnection (used for all LDAP operations)
    $hasLdapConnection = ($null -ne $Script:LdapConnection)
    $HasActiveSession = ($null -ne $Script:LDAPContext) -and $hasLdapConnection

    # Scenario 1: No connection parameters AND no active session ? Show help
    if (-not $HasConnectionParams -and -not $HasActiveSession) {
        Show-NoSessionError -Context "Invoke-adPEAS"
        return
    }

    # Scenario 2: Active session exists AND no new connection parameters ? Reuse session
    if ($HasActiveSession -and -not $HasConnectionParams) {
        Write-Log "[adPEAS] Reusing existing LDAP session"
        Show-Header "Using existing LDAP connection"

        # Use LDAP-verified identity if available
        $AuthenticatedUser = if ($Script:LDAPContext.AuthenticatedUser) {
            $Script:LDAPContext.AuthenticatedUser
        } elseif ($Script:LDAPContext.Credential) {
            $Script:LDAPContext.Credential.UserName
        } else {
            "$env:USERDOMAIN\$env:USERNAME"
        }

        # Build auth method display string
        $AuthDisplay = switch ($Script:LDAPContext.AuthMethod) {
            'Kerberos'    { "Kerberos" }
            'SimpleBind'  { "LDAP SimpleBind" }
            'WindowsSSPI' { if ($Script:LDAPContext.KerberosUsed) { "Kerberos (SSPI)" } else { "Windows SSPI" } }
            default       { $Script:LDAPContext.Protocol }  # Fallback to protocol if AuthMethod not set
        }

        Show-Line "Connected to domain '$($Script:LDAPContext.Domain)' on server '$($Script:LDAPContext.Server)' as '$AuthenticatedUser' via $AuthDisplay"
    }
    # Scenario 3: Connection parameters provided ? Establish new connection via Connect-adPEAS
    elseif ($HasConnectionParams) {
        Show-Header "Establishing LDAP Connection"

        # Build parameters for Connect-adPEAS (pass-through)
        $ConnectionParams = @{}

        # Common parameters
        if ($PSBoundParameters.ContainsKey('Domain')) { $ConnectionParams['Domain'] = $Domain }
        if ($PSBoundParameters.ContainsKey('Server')) { $ConnectionParams['Server'] = $Server }
        if ($PSBoundParameters.ContainsKey('UseLDAPS')) { $ConnectionParams['UseLDAPS'] = $true }
        # Always ignore SSL errors for maximum compatibility in pentesting environments
        $ConnectionParams['IgnoreSSLErrors'] = $true

        # Authentication parameters (parameter-set specific)
        if ($PSBoundParameters.ContainsKey('UseWindowsAuth')) { $ConnectionParams['UseWindowsAuth'] = $true }
        if ($PSBoundParameters.ContainsKey('Credential')) { $ConnectionParams['Credential'] = $Credential }
        if ($PSBoundParameters.ContainsKey('Username')) { $ConnectionParams['Username'] = $Username }
        if ($PSBoundParameters.ContainsKey('Password')) { $ConnectionParams['Password'] = $Password }
        if ($PSBoundParameters.ContainsKey('Certificate')) { $ConnectionParams['Certificate'] = $Certificate }
        if ($PSBoundParameters.ContainsKey('CertificatePassword')) { $ConnectionParams['CertificatePassword'] = $CertificatePassword }

        # Timeout parameter (pass-through to Connect-adPEAS)
        if ($PSBoundParameters.ContainsKey('TimeoutSeconds')) { $ConnectionParams['TimeoutSeconds'] = $TimeoutSeconds }

        # License parameter (pass-through to Connect-adPEAS)
        if ($PSBoundParameters.ContainsKey('License')) { $ConnectionParams['License'] = $License }

        # Authentication method handling
        $HasAuthMethod = $PSBoundParameters.ContainsKey('UseWindowsAuth') -or
                        $PSBoundParameters.ContainsKey('Credential') -or
                        $PSBoundParameters.ContainsKey('Username') -or
                        $PSBoundParameters.ContainsKey('Certificate')

        if (-not $HasAuthMethod) {
            # No new auth method specified - check if we can reuse existing session credentials
            if ($HasActiveSession -and $Script:LDAPContext.Credential) {
                # Reuse credentials from existing session
                Write-Log "[adPEAS] Reusing credentials from existing session"
                $ConnectionParams['Credential'] = $Script:LDAPContext.Credential
            }
            elseif ($HasActiveSession -and $Script:LDAPContext.Certificate) {
                # Reuse certificate auth from existing session
                Write-Log "[adPEAS] Reusing certificate authentication from existing session"
                $ConnectionParams['Certificate'] = $Script:LDAPContext.Certificate
                if ($Script:LDAPContext.CertificatePassword) {
                    $ConnectionParams['CertificatePassword'] = $Script:LDAPContext.CertificatePassword
                }
            }
            else {
                # No session or session uses Windows Auth - default to Windows Auth
                Write-Log "[adPEAS] No authentication method specified - defaulting to Windows Authentication"
                $ConnectionParams['UseWindowsAuth'] = $true
            }
        }

        try {
            # Call Connect-adPEAS with pass-through parameters (use -Quiet to suppress session info)
            # Connect-adPEAS handles all auth logic, error messages, and user verification
            $Connection = Connect-adPEAS @ConnectionParams -Quiet

            if (-not $Connection) {
                # Connect-adPEAS failed (returned $null)
                Show-Error -Type Connection
                return
            }

            # Use LDAP-verified identity if available
            $AuthenticatedUser = if ($Connection.AuthenticatedUser) {
                $Connection.AuthenticatedUser
            } elseif ($Connection.Credential) {
                $Connection.Credential.UserName
            } else {
                "$env:USERDOMAIN\$env:USERNAME"
            }

            # Build auth method display string
            $AuthDisplay = switch ($Connection.AuthMethod) {
                'Kerberos'    { "Kerberos" }
                'SimpleBind'  { "LDAP SimpleBind" }
                'WindowsSSPI' { if ($Connection.KerberosUsed) { "Kerberos (SSPI)" } else { "Windows SSPI" } }
                default       { $Connection.Protocol }  # Fallback to protocol if AuthMethod not set
            }

            Show-Line "Successfully connected to domain '$($Connection.Domain)' on server '$($Connection.Server)' as '$AuthenticatedUser' via $AuthDisplay" -Class Note
        } catch {
            # Connect-adPEAS threw an error (already displayed by Connect-adPEAS)
            Show-Error -Type Connection
            return
        }
    }

    # ===== Connection Health Check =====
    # Verify that the DC is actually reachable by performing a test query
    Write-Log "[adPEAS] Verifying Domain Controller connectivity..."

    # Use -Quiet mode to suppress detailed output
    $connectionHealthy = Get-adPEASSession -TestConnection -Quiet

    if (-not $connectionHealthy) {
        Show-Error -Type HealthCheck -Message "Domain Controller is not responding" -Hints @(
            "The connection was established but queries to the DC are failing",
            "Possible causes: DC offline, network connectivity lost, firewall blocking LDAP queries"
        )
        return
    }

    Write-Log "[adPEAS] Connection health check passed - DC is reachable"

    # ===== Kerberos Session Health Check =====
    # For Kerberos-based sessions, verify the TGT is still valid before starting module execution
    # This catches overnight ticket expiration early, instead of failing on every individual check
    # Reset SessionInvalid flag from any previous failed run - give fresh TGT check a fair chance
    if ($Script:LDAPContext -and $Script:LDAPContext['SessionInvalid']) {
        $Script:LDAPContext.Remove('SessionInvalid')
        Write-Log "[adPEAS] Cleared SessionInvalid flag from previous run"
    }
    if (-not (Ensure-LDAPConnection)) {
        # Ensure-LDAPConnection already displayed the error message and set SessionInvalid flag
        Show-Header "Scan Summary"
        Show-Line "Duration: 0 seconds" -Class Hint
        Show-Line "Scan was aborted due to invalid LDAP session. No reports were generated." -Class Finding
        Show-Line "Re-authenticate with Connect-adPEAS and try again." -Class Hint
        return
    }

    # 2. Determine Modules
    if (-not $Module) {
        $Module = @('Domain','Creds','Rights','Delegation','ADCS','Accounts','GPO','Computer','Application','Bloodhound')
    }

    # OPSEC mode excludes BloodHound collection entirely - drop it from the list
    # so the displayed module list and progress counter reflect what will actually run.
    if ($OPSEC) {
        $Module = @($Module | Where-Object { $_ -ne 'Bloodhound' })
    }

    Write-Log "[adPEAS] Executing Modules: $($Module -join ', ')"
    Show-Line "Executing Modules: $($Module -join ', ')"

    # Module progress counter
    $moduleCounter = 0
    $moduleTotal = $Module.Count

    # Category Header Mapping - displayed once per module category
    $Script:ModuleCategoryHeaders = @{
        'Domain'     = "Domain Configuration"
        'Accounts'   = "Privileged Accounts"
        'Delegation' = "Delegation Settings"
        'Rights'     = "Access Permissions"
        'Computer'   = "Computer Security"
        'GPO'        = "Group Policy Objects"
        'ADCS'       = "Certificate Services"
        'Application'= "Application Infrastructure"
        'Creds'      = "Credential Exposure"
        'Bloodhound' = "BloodHound Data"
    }

    # 3. Execute checks
    # Helper function to run a check with context for HTML reporting
    function Invoke-CheckWithContext {
        param(
            [string]$Category,
            [string]$CheckName,
            [string]$Title,
            [scriptblock]$Check
        )
        # Skip all remaining checks if session became invalid (e.g., expired Kerberos TGT)
        if ($Script:LDAPContext -and $Script:LDAPContext['SessionInvalid']) {
            Write-Log "[adPEAS] Skipping check '$CheckName' - session invalid"
            return
        }
        Set-CheckContext -Category $Category -CheckName $CheckName -Title $Title
        try {
            & $Check
        } catch {
            Write-Warning "[adPEAS] Check '$CheckName' failed: $_"
            Write-Log "[adPEAS] Check '$CheckName' failed: $_" -Level Error
        } finally {
            Clear-CheckContext
        }
    }

    # Helper functions for LDAP Statistics tracking (no-op when $Script:LDAPStatistics is $null)
    function Enter-StatisticsModule {
        param([string]$ModuleName)
        if (-not $Script:LDAPStatistics) { return }
        $Script:LDAPStatistics._CurrentModule = $ModuleName
        $Script:LDAPStatistics._ModuleStartQueries = $Script:LDAPStatistics.TotalQueries
        $Script:LDAPStatistics._ModuleStartResults = $Script:LDAPStatistics.TotalResults
        $Script:LDAPStatistics._ModuleStartBytes   = $Script:LDAPStatistics.TotalEstimatedBytes
    }

    function Exit-StatisticsModule {
        param([string]$ModuleName)
        if (-not $Script:LDAPStatistics) { return }

        $deltaQueries = $Script:LDAPStatistics.TotalQueries - $Script:LDAPStatistics._ModuleStartQueries
        $deltaResults = $Script:LDAPStatistics.TotalResults - $Script:LDAPStatistics._ModuleStartResults
        $deltaBytes   = $Script:LDAPStatistics.TotalEstimatedBytes - $Script:LDAPStatistics._ModuleStartBytes

        $Script:LDAPStatistics.Modules[$ModuleName] = @{
            Queries        = $deltaQueries
            Results        = $deltaResults
            EstimatedBytes = $deltaBytes
        }
        $Script:LDAPStatistics._CurrentModule = $null

        # Per-module display
        $displayName = if ($Script:ModuleCategoryHeaders[$ModuleName]) {
            $Script:ModuleCategoryHeaders[$ModuleName]
        } else { $ModuleName }

        Show-SubHeader "LDAP Statistics for $displayName"
        Show-KeyValue "Queries" $deltaQueries -Class Note
        Show-KeyValue "Results" $deltaResults -Class Note
        Show-KeyValue "Estimated Traffic" (Format-ByteSize $deltaBytes) -Class Note
    }

    function Format-ByteSize {
        param([long]$Bytes)
        if ($Bytes -ge 1MB) { return "{0:N1} MB" -f ($Bytes / 1MB) }
        if ($Bytes -ge 1KB) { return "{0:N1} KB" -f ($Bytes / 1KB) }
        return "$Bytes Bytes"
    }

    # Domain Module - baseline context for all subsequent checks
    if ($Module -contains 'Domain') {
        $moduleCounter++
        Enter-StatisticsModule 'Domain'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Domain'])"
        try {
            Invoke-CheckWithContext -Category 'Domain' -CheckName 'Get-DomainInformation' -Title 'Domain Information' -Check { Get-DomainInformation }
            Invoke-CheckWithContext -Category 'Domain' -CheckName 'Get-DomainPasswordPolicy' -Title 'Password Policy' -Check { Get-DomainPasswordPolicy }
            Invoke-CheckWithContext -Category 'Domain' -CheckName 'Get-DomainTrusts' -Title 'Domain Trusts' -Check { Get-DomainTrusts }
            Invoke-CheckWithContext -Category 'Domain' -CheckName 'Get-LDAPConfiguration' -Title 'LDAP Configuration' -Check { Get-LDAPConfiguration }
            Invoke-CheckWithContext -Category 'Domain' -CheckName 'Get-SMBSigningStatus' -Title 'SMB Signing Status' -Check { Get-SMBSigningStatus }
        } catch {
            Write-Warning "[adPEAS] Error executing Domain Module: $_"
        }
        Exit-StatisticsModule 'Domain'
    }

    # Creds Module - immediately actionable findings first
    if ($Module -contains 'Creds') {
        $moduleCounter++
        Enter-StatisticsModule 'Creds'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Creds'])"
        try {
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-LAPSCredentialAccess' -Title 'LAPS Credential Access' -Check { Get-LAPSCredentialAccess }
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-BitLockerRecoveryKeyAccess' -Title 'BitLocker Recovery Key Access' -Check { Get-BitLockerRecoveryKeyAccess }
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-CredentialExposure' -Title 'Credential Exposure' -Check { Get-CredentialExposure }
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-PasswordInDescription' -Title 'Passwords in Description/Info' -Check { Get-PasswordInDescription -OPSEC:$OPSEC }
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-KerberoastableAccounts' -Title 'Kerberoastable Accounts' -Check { Get-KerberoastableAccounts -OPSEC:$OPSEC }
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-ASREPRoastableAccounts' -Title 'ASREProastable Accounts' -Check { Get-ASREPRoastableAccounts -OPSEC:$OPSEC }
            Invoke-CheckWithContext -Category 'Creds' -CheckName 'Get-UnixPasswordAccounts' -Title 'Unix Password Accounts' -Check { Get-UnixPasswordAccounts }
        } catch {
            Write-Warning "[adPEAS] Error executing Creds Module: $_"
        }
        Exit-StatisticsModule 'Creds'
    }

    # Rights Module - privilege escalation paths
    if ($Module -contains 'Rights') {
        $moduleCounter++
        Enter-StatisticsModule 'Rights'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Rights'])"
        try {
            Invoke-CheckWithContext -Category 'Rights' -CheckName 'Get-DangerousACLs' -Title 'Dangerous ACLs' -Check { Get-DangerousACLs -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'Rights' -CheckName 'Get-DangerousOUPermissions' -Title 'Dangerous OU Permissions' -Check { Get-DangerousOUPermissions -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'Rights' -CheckName 'Get-PasswordResetRights' -Title 'Password Reset Rights' -Check { Get-PasswordResetRights -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'Rights' -CheckName 'Get-AddComputerRights' -Title 'Add Computer Rights' -Check { Get-AddComputerRights -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'Rights' -CheckName 'Get-GPOUserRightsAssignment' -Title 'GPO User Rights Assignment' -Check { Get-GPOUserRightsAssignment -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'Rights' -CheckName 'Get-LAPSPermissions' -Title 'LAPS Permissions' -Check { Get-LAPSPermissions -IncludePrivileged:$IncludePrivileged }
        } catch {
            Write-Warning "[adPEAS] Error executing Rights Module: $_"
        }
        Exit-StatisticsModule 'Rights'
    }

    # Delegation Module - delegation abuse vectors
    if ($Module -contains 'Delegation') {
        $moduleCounter++
        Enter-StatisticsModule 'Delegation'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Delegation'])"
        try {
            Invoke-CheckWithContext -Category 'Delegation' -CheckName 'Get-UnconstrainedDelegation' -Title 'Unconstrained Delegation' -Check { Get-UnconstrainedDelegation }
            Invoke-CheckWithContext -Category 'Delegation' -CheckName 'Get-ConstrainedDelegation' -Title 'Constrained Delegation' -Check { Get-ConstrainedDelegation }
            Invoke-CheckWithContext -Category 'Delegation' -CheckName 'Get-ResourceBasedConstrainedDelegation' -Title 'Resource-Based Constrained Delegation' -Check { Get-ResourceBasedConstrainedDelegation }
        } catch {
            Write-Warning "[adPEAS] Error executing Delegation Module: $_"
        }
        Exit-StatisticsModule 'Delegation'
    }

    # ADCS Module - certificate abuse (often critical)
    if ($Module -contains 'ADCS') {
        $moduleCounter++
        Enter-StatisticsModule 'ADCS'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['ADCS'])"
        try {
            Invoke-CheckWithContext -Category 'ADCS' -CheckName 'Get-ADCSVulnerabilities' -Title 'ADCS Vulnerabilities' -Check { Get-ADCSVulnerabilities -IncludePrivileged:$IncludePrivileged }
        } catch {
            Write-Warning "[adPEAS] Error executing ADCS Module: $_"
        }
        Exit-StatisticsModule 'ADCS'
    }

    # Accounts Module - privileged account hygiene
    if ($Module -contains 'Accounts') {
        $moduleCounter++
        Enter-StatisticsModule 'Accounts'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Accounts'])"
        try {
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-PrivilegedGroupMembers' -Title 'Privileged Group Members' -Check { Get-PrivilegedGroupMembers -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-SIDHistoryInjection' -Title 'SID History Injection' -Check { Get-SIDHistoryInjection }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-ManagedServiceAccountSecurity' -Title 'Managed Service Account Security' -Check { Get-ManagedServiceAccountSecurity }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-ProtectedUsersStatus' -Title 'Protected Users Status' -Check { Get-ProtectedUsersStatus }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-InactiveAdminAccounts' -Title 'Inactive Admin Accounts' -Check { Get-InactiveAdminAccounts }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-AdminPasswordNeverExpires' -Title 'Admin Password Never Expires' -Check { Get-AdminPasswordNeverExpires }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-AdminReversibleEncryption' -Title 'Admin Reversible Encryption' -Check { Get-AdminReversibleEncryption }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-PasswordNotRequired' -Title 'Password Not Required Accounts' -Check { Get-PasswordNotRequired }
            Invoke-CheckWithContext -Category 'Accounts' -CheckName 'Get-NonDefaultUserOwners' -Title 'Non-Default User Owners' -Check { Get-NonDefaultUserOwners -OPSEC:$OPSEC }
        } catch {
            Write-Warning "[adPEAS] Error executing Accounts Module: $_"
        }
        Exit-StatisticsModule 'Accounts'
    }

    # GPO Module - GPO abuse vectors
    if ($Module -contains 'GPO') {
        $moduleCounter++
        Enter-StatisticsModule 'GPO'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['GPO'])"
        try {
            Invoke-CheckWithContext -Category 'GPO' -CheckName 'Get-GPOPermissions' -Title 'GPO Permissions' -Check { Get-GPOPermissions -IncludePrivileged:$IncludePrivileged }
            Invoke-CheckWithContext -Category 'GPO' -CheckName 'Get-GPOLocalGroupMembership' -Title 'GPO Local Group Membership' -Check { Get-GPOLocalGroupMembership }
            Invoke-CheckWithContext -Category 'GPO' -CheckName 'Get-GPOScheduledTasks' -Title 'GPO Scheduled Tasks' -Check { Get-GPOScheduledTasks }
            Invoke-CheckWithContext -Category 'GPO' -CheckName 'Get-GPOScriptPaths' -Title 'GPO Script Paths' -Check { Get-GPOScriptPaths }
            Invoke-CheckWithContext -Category 'GPO' -CheckName 'Get-GPORegistrySettings' -Title 'GPO Registry Settings' -Check { Get-GPORegistrySettings }
        } catch {
            Write-Warning "[adPEAS] Error executing GPO Module: $_"
        }
        Exit-StatisticsModule 'GPO'
    }

    # Computer Module - computer security and LAPS configuration
    if ($Module -contains 'Computer') {
        $moduleCounter++
        Enter-StatisticsModule 'Computer'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Computer'])"
        try {
            Invoke-CheckWithContext -Category 'Computer' -CheckName 'Get-InfrastructureServers' -Title 'Infrastructure Servers' -Check { Get-InfrastructureServers }
            Invoke-CheckWithContext -Category 'Computer' -CheckName 'Get-NonDefaultComputerOwners' -Title 'Non-Default Computer Owners' -Check { Get-NonDefaultComputerOwners -OPSEC:$OPSEC }
            Invoke-CheckWithContext -Category 'Computer' -CheckName 'Get-LAPSConfiguration' -Title 'LAPS Configuration' -Check { Get-LAPSConfiguration }
            Invoke-CheckWithContext -Category 'Computer' -CheckName 'Get-OutdatedComputers' -Title 'Outdated Computers' -Check { Get-OutdatedComputers -OPSEC:$OPSEC }
        } catch {
            Write-Warning "[adPEAS] Error executing Computer Module: $_"
        }
        Exit-StatisticsModule 'Computer'
    }

    # Application Module - infrastructure overview (Exchange, SCCM, SCOM)
    if ($Module -contains 'Application') {
        $moduleCounter++
        Enter-StatisticsModule 'Application'
        Show-Header "[$moduleCounter/$moduleTotal] Analyzing $($Script:ModuleCategoryHeaders['Application'])"
        try {
            Invoke-CheckWithContext -Category 'Application' -CheckName 'Get-ExchangeInfrastructure' -Title 'Exchange Infrastructure' -Check { Get-ExchangeInfrastructure }
            Invoke-CheckWithContext -Category 'Application' -CheckName 'Get-SCCMInfrastructure' -Title 'SCCM Infrastructure' -Check { Get-SCCMInfrastructure }
            Invoke-CheckWithContext -Category 'Application' -CheckName 'Get-SCOMInfrastructure' -Title 'SCOM Infrastructure' -Check { Get-SCOMInfrastructure }
        } catch {
            Write-Warning "[adPEAS] Error executing Application Module: $_"
        }
        Exit-StatisticsModule 'Application'
    }

    # Bloodhound Module (excluded from $Module above when -OPSEC is set)
    if ($Module -contains 'Bloodhound') {
        $moduleCounter++
        Enter-StatisticsModule 'Bloodhound'
        Show-Header "[$moduleCounter/$moduleTotal] Collecting $($Script:ModuleCategoryHeaders['Bloodhound'])"

        try {
            # Pass output directory to collector if -Outputfile was specified
            $bhOutputDir = $null
            if ($Script:adPEAS_Outputfile) {
                $bhOutputDir = Split-Path -Parent $Script:adPEAS_Outputfile
            } elseif ($Script:HTMLOutputPath) {
                $bhOutputDir = Split-Path -Parent $Script:HTMLOutputPath
            }
            if ($bhOutputDir) {
                Invoke-CheckWithContext -Category 'Bloodhound' -CheckName 'Invoke-adPEASCollector' -Title 'BloodHound Collector' -Check { Invoke-adPEASCollector -OutputPath $bhOutputDir }
            } else {
                Invoke-CheckWithContext -Category 'Bloodhound' -CheckName 'Invoke-adPEASCollector' -Title 'BloodHound Collector' -Check { Invoke-adPEASCollector }
            }
        } catch {
            Write-Warning "[adPEAS] Error executing Bloodhound Module: $_"
        }
        Exit-StatisticsModule 'Bloodhound'
    }

    # Check if session became invalid during check execution (e.g., expired Kerberos TGT)
    $sessionAborted = $Script:LDAPContext -and $Script:LDAPContext['SessionInvalid']

    # 4. Merge with previous findings if -OutputAppend
    # The JSON cache path is always basePath.json, regardless of output format
    if ($OutputAppend -and -not $sessionAborted) {
        $cachePath = "$basePath.json"

        if (Test-Path $cachePath) {
            try {
                $previousFindings = Import-FindingsCache -Path $cachePath
                $currentFindings = Get-FindingsCollection

                # Module names = Category names (1:1 mapping)
                $replacedCategories = @($Module)

                $mergedFindings = Merge-FindingsCollection `
                    -PreviousFindings $previousFindings `
                    -CurrentFindings $currentFindings `
                    -ReplacedCategories $replacedCategories

                Set-FindingsCollection -Findings $mergedFindings
                Show-Line "Appended to existing report: merged $($previousFindings.Count) previous + $($currentFindings.Count) new findings" -Class Note
            }
            catch {
                Write-Warning "[adPEAS] Could not load previous findings from '$cachePath': $_"
                Write-Warning "[adPEAS] Continuing without append - creating fresh report"
            }
        } else {
            Write-Log "[adPEAS] No previous cache found at '$cachePath' - first append run"
        }
    }

    # 5. Generate HTML Report if requested
    if ($Script:HTMLOutputPath -and -not $sessionAborted) {
        try {
            Export-HTMLReport -OutputPath $Script:HTMLOutputPath
            Write-Log "[adPEAS] HTML report generated: $($Script:HTMLOutputPath)"
        } catch {
            Write-Warning "[adPEAS] Error generating HTML report: $_"
            $Script:HTMLOutputPath = $null  # Clear path so we don't show it in summary
        }
    }

    # 5b. Generate JSON export (for -Format All or -Format JSON)
    # JSON path is always basePath.json, used for -OutputAppend cache and Convert-adPEASReport
    if ($Format -in @('All', 'JSON') -and $basePath -and -not $sessionAborted) {
        $jsonPath = "$basePath.json"
        try {
            Export-FindingsCache -Path $jsonPath
            $Script:JSONOutputPath = $jsonPath
            Write-Log "[adPEAS] Findings JSON saved to: $jsonPath"
        }
        catch {
            Write-Warning "[adPEAS] Could not save JSON export to '$jsonPath': $_"
            $Script:JSONOutputPath = $null
        }
    }

    # 6. LDAP Statistics Summary (before Scan Summary)
    if ($Script:LDAPStatistics -and $Script:LDAPStatistics.Modules.Count -gt 0) {
        Show-Header "LDAP Statistics Summary"

        foreach ($modName in $Script:LDAPStatistics.Modules.Keys) {
            $modStats = $Script:LDAPStatistics.Modules[$modName]
            $displayName = if ($Script:ModuleCategoryHeaders[$modName]) {
                $Script:ModuleCategoryHeaders[$modName]
            } else { $modName }

            $statsObj = [PSCustomObject]@{
                Name             = $displayName
                Queries          = $modStats.Queries
                Results          = $modStats.Results
                EstimatedTraffic = Format-ByteSize $modStats.EstimatedBytes
            }
            $statsObj | Add-Member '_adPEASObjectType' 'LDAPStatisticsModule' -Force
            Show-Object $statsObj
        }

        # Total row
        $totalObj = [PSCustomObject]@{
            Name             = "Total"
            Queries          = $Script:LDAPStatistics.TotalQueries
            Results          = $Script:LDAPStatistics.TotalResults
            EstimatedTraffic = Format-ByteSize $Script:LDAPStatistics.TotalEstimatedBytes
        }
        $totalObj | Add-Member '_adPEASObjectType' 'LDAPStatisticsTotal' -Force
        Show-Object $totalObj
    }

    # 7. Summary
    $EndTime = Get-Date
    $Duration = $EndTime - $StartTime

    Show-Header "Scan Summary"
    Show-Line "Duration: $([Math]::Round($Duration.TotalSeconds, 1)) seconds" -Class Hint

    if ($sessionAborted) {
        Show-Line "Scan was aborted due to invalid LDAP session. No reports were generated." -Class Finding
        Show-Line "Re-authenticate with Connect-adPEAS and try again." -Class Hint
    } else {
        # 7. Report file notifications (after summary)
        if ($Script:adPEAS_Outputfile) {
            Show-Line "Text report saved to: $Script:adPEAS_Outputfile" -Class Hint
        }
        if ($Script:HTMLOutputPath) {
            Show-Line "HTML report saved to: $Script:HTMLOutputPath" -Class Hint
        }
        if ($htmlPath) {
            $cachePath = [System.IO.Path]::ChangeExtension($htmlPath, '.json')
            if (Test-Path $cachePath) {
                Show-Line "JSON export saved to: $cachePath" -Class Hint
            }
        }
        if ($Script:JSONOutputPath -and (Test-Path $Script:JSONOutputPath)) {
            Show-Line "JSON export saved to: $Script:JSONOutputPath" -Class Hint
        }
    }

} catch {
    Show-Line "CRITICAL ERROR: $_" -Class Finding
    Write-Error $_.ScriptStackTrace
    return
}
finally {
    # Clean up findings collection (even on early returns, to prevent stale state)
    Clear-FindingsCollection

    # Session is always kept alive after Invoke-adPEAS completes.
    # This allows users to run Get-adPEASSession, Get-Domain* queries, or additional scans.
    # Use Disconnect-adPEAS to explicitly close the session when done.
    Write-Log "[adPEAS] Session kept alive - use Disconnect-adPEAS to close"
    Write-Log "[adPEAS] adPEAS v2 completed"
}
}
# ===== End of Invoke-adPEAS Function =====

# ===== Module Import Message =====
# Use Show-Logo for consistent banner display

Show-Logo -Version $Script:adPEASVersion

# Quick Start Guide (centralized in Get-adPEASHelp)
Get-adPEASHelp -Section QuickStart
